INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nha-van-tu-do', 'Những Nhà Văn Tự Do', 'Freedom Writers', 'https://phimimg.com/upload/vod/20231231-1/a1cb24603114bdc1213ac86e32a44e2e.jpg', 'https://phimimg.com/upload/vod/20231231-1/d8fea585d5abaf4cdc61facc7f6452e4.jpg', '<p>Đó là năm 1994 tại Long Beach, California. Erin Gruwell duy tâm chỉ mới bắt đầu công việc giảng dạy đầu tiên của mình, đó là giáo viên tiếng Anh và sinh viên năm thứ hai tại trường trung học Woodrow Wilson, hai năm trước, đã thực hiện một chương trình tích hợp tự nguyện. Đối với nhiều giáo viên hiện tại, sự tích hợp đã hủy hoại trường học, có vị học thuật Stellar trước đây đã được thay thế bằng nhiều sinh viên sẽ may mắn khi tốt nghiệp hoặc thậm chí là biết chữ. Mặc dù đã chọn trường về mục đích vì chương trình tích hợp, Erin không chuẩn bị cho bản chất của lớp học của cô, người có học sinh sống theo các thế hệ của các quy tắc đạo đức nghiêm ngặt của việc bảo vệ tất cả các chi phí. Nhiều người đang ở trong các băng đảng và hầu hết tất cả đều biết ai đó đã bị giết bởi bạo lực băng đảng. Người Latin ghét những người Campuchia ghét người da đen và vân vân. Người duy nhất học sinh ghét nhiều hơn là cô Gruwell. Cho đến khi Erin giữ một cuộc thảo luận chưa được thực hiện về một ổ đĩa gần đây, bằng cách bắn chết rằng cô ấy bắt đầu hoàn toàn để hiểu những gì cô ấy chống lại. Và đó không phải là cho đến khi cô ấy cung cấp một nhiệm vụ viết một tạp chí hàng ngày - sẽ không được chấm điểm, và sẽ vẫn chưa đọc được bởi cô ấy trừ khi họ chọn - rằng các sinh viên bắt đầu mở ra cho cô ấy. Khi Erin cố gắng hơn và khó hơn để có các nguồn lực được cung cấp để giảng dạy đúng cách (thường dẫn đến việc cô ấy cần phải trả tiền cho họ thông qua công việc thứ hai và thứ ba), cô ấy có vẻ phải đối mặt với sự kháng cự lớn hơn, đặc biệt là từ các đồng nghiệp của cô ấy, chẳng hạn như Margaret Campbell, Phần đầu của cô, người sống theo các quy định và thấy những nguồn lực như một sự lãng phí và Brian Gelford, người sẽ bảo vệ vị trí tư nhân của mình về việc dạy các lớp Honours Honours hoàn toàn. Erin cũng thấy rằng công việc giảng dạy của cô đang đặt một căng thẳng cho cuộc hôn nhân của mình với Scott Casey, một người đàn ông dường như đã mất cách lý tưởng của riêng mình trong cuộc sống.</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324520);
