INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-phim-nguoi-lon', 'Đóng Phim Người Lớn', 'I Want Candy', 'https://phimimg.com/upload/vod/20231231-1/cad4056282d258dfdf27e5a2e5b9125a.jpg', 'https://phimimg.com/upload/vod/20231231-1/2e357c371992bc3f0b85bbe847de4510.jpg', '<p>Hai chàng trai đầy hy vọng đến từ Leatherhead đang cố gắng thâm nhập vào các bộ phim đã tình cờ gặp được cơ hội trong đời. Chán nản với giáo viên làm phim nghệ thuật của họ, nhà sản xuất muốn trở thành Joe và người bạn đạo diễn tài năng nhưng thần kinh Baggy của anh ấy đến London để bán thứ mà họ biết là một kịch bản làm bằng vàng.</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Riley","avatar":""},{"name":"Tom Burke","avatar":""},{"name":"Carmen Electra","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Michelle Ryan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324520);
