INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-thap-mat-troi', 'Đi Thắp Mặt Trời', 'Sunshine', 'https://phimimg.com/upload/vod/20231230-1/a474542a2d71b26d2268f27e2137df18.jpg', 'https://phimimg.com/upload/vod/20231230-1/21758b248c30f96de5e71cfb4fdf0424.jpg', '<p>Năm mươi năm tới trong tương lai, mặt trời sắp chết và Trái đất bị đe dọa bởi nhiệt độ bắc cực. Một nhóm phi hành gia được cử đến để hồi sinh Mặt trời — nhưng nhiệm vụ thất bại. Bảy năm sau, một đội mới được gửi đến để hoàn thành sứ mệnh là hy vọng cuối cùng của nhân loại.</p>', 'Full', 1, 'single', 'completed', 10, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Cliff Curtis","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
