INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-dua-huyen-thoai-2007', 'Tay Đua Huyền Thoại', 'Ta Ra Rum Pum', 'https://phimimg.com/upload/vod/20240123-1/8335d295038fe7df167dc1bfb6b7bbc9.jpg', 'https://phimimg.com/upload/vod/20240123-1/ecd922f42506ae935d624d60f42bd76e.jpg', '<p>Một vận động viên đua xe hàng đầu có vợ đẹp và 2 đứa con (1 trai 1 gái), cuộc sống tưởng chừng như hoàn hảo nhưng rồi anh bất ngờ gặp tai nạn. Mọi thứ thay đổi hoàn toàn... Liệu anh chàng cùng gia đình sẽ phải xoay sở ra sao?</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Saif Ali Khan","avatar":""},{"name":"Rani Mukerji","avatar":""},{"name":"Javed Jaffrey","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324520);
