INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-trai-dat', 'Hành Trình Trái Đất', 'Planet Earth', 'https://phimimg.com/upload/vod/20231219-1/55069acd91290a981fbf8316abdea688.jpg', 'https://phimimg.com/upload/vod/20231219-1/10217adb22c29ebeef2eb537fe683ff3.jpg', '<p>Hành Tinh Trái Đất của chúng ta thật đẹp và kì diệu - đẹp nhất, kì diệu nhất trong 10 hành tinh của hệ mặt trời. Planet Earth là một bộ phim tài liệu được dàn dựng công phu trong suốt 5 năm trời để tôn vinh vẻ đẹp ấy. Qua 11 phần của bộ phim này, bạn sẽ được chu du từ cực Nam tới cực Bắc, qua các Sa Mạc, rừng mưa, lên những dãy núi cao, lặn xuống dưới biển sâu, khám phá những hang động huyền bí v.v... rất thú vị và kích thích.</p>', 'Full', 11, 'series', 'completed', 8, 2007, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"David Attenborough","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Huw Cordey","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324520);
