INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bloodrayne-2-deliverance', 'BloodRayne 2: Deliverance', 'BloodRayne II: Deliverance', 'https://phimimg.com/upload/vod/20231219-1/40274c598cda9408533cdc6e3ff7e740.jpg', 'https://phimimg.com/upload/vod/20231219-1/508925ef5bf4b73ab3f211a2334baaed.jpg', '<p>Rayne, một chiến binh nửa người nửa ma cà rồng, đang ở miền Tây hoang dã của Mỹ những năm 1880 để ngăn chặn tên ma cà rồng Billy the Kid và đội cao bồi ma cà rồng của hắn.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Natassia Malthe","avatar":""},{"name":"Zack Ward","avatar":""},{"name":"Michael Paré","avatar":""},{"name":"Brendan Fletcher","avatar":""},{"name":"Chris Coppola","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324520);
