INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-hang-xom', 'Cô Gái Hàng Xóm', 'The Girl Next Door', 'https://phimimg.com/upload/vod/20231219-1/dc53162e1f4c28c1d0a1724b6f6873b7.jpg', 'https://phimimg.com/upload/vod/20231219-1/96267dca7a03517ffdd8a36a8bd1be4e.jpg', '<p>Dựa trên một câu chuyện có thật từng gây phẫn nộ trong dư luận, bộ phim tái hiện lại những ám ảnh kinh hoàng của một cô gái 16 tuổi đã bị bắt nhốt và tra tấn dã man dưới tầng hầm. Trong thực tế, vào năm 1965, Sylvia Likens đã bị tra tấn bởi Gertrude Baniszewski cùng con của bà và những người hàng xóm xung quanh nhà Gertrude. Những người công tố của tòa án đã ví câu chuyện của Likens là một tội ác khủng khiếp nhất từng xảy ra tại Indiana. Lúc này Sylvia Likens chỉ mới 16 tuổi.</p>', 'Full', 1, 'single', 'completed', 10, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Blythe Auffarth","avatar":""},{"name":"Daniel Manche","avatar":""},{"name":"Michael Zegen","avatar":""},{"name":"Catherine Mary Stewart","avatar":""},{"name":"Grant Show","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
