INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-cua-ac-than', 'Đêm Của Ác Thần', 'Gabriel', 'https://phimimg.com/upload/vod/20231219-1/6209836114cbd4eda2a100609532ad87.jpg', 'https://phimimg.com/upload/vod/20231219-1/823702aa2a6204d6ecf45f1e90339f19.jpg', '<p>Gabriel kể câu chuyện về một tổng lãnh thiên thần chiến đấu để mang ánh sáng trở lại luyện ngục - nơi bóng tối ngự trị - và cứu rỗi linh hồn của cư dân thành phố.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwaine Stevenson","avatar":""},{"name":"Jack Campbell","avatar":""},{"name":"Erika Heynatz","avatar":""},{"name":"Andy Whitfield","avatar":""},{"name":"Samantha Noble","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324520);
