INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-cuu-hoa', 'Chú Chó Cứu Hỏa', 'Firehouse Dog', 'https://phimimg.com/upload/vod/20231219-1/bed85fb39179ac888ee593e2d2f78436.jpg', 'https://phimimg.com/upload/vod/20231219-1/14e8c173008e04729d83f318fa17f661.jpg', '<p>Chú chó cứu hỏa - Firehouse Dog kể về chú chó ngôi sao Hollywood tên Rex và cậu bé Shane - vừa là ông chủ vừa là bạn của chú. Một ngày, Rex bị lạc đến một thành phố hoàn toàn xa lạ. Tại đây, chú gặp đủ thứ rắc rối, khác xa với cuộc sống êm ấm trước đây. Rex bất đắc dĩ thuộc về ông chủ Shane, con trai một lính cứu hỏa. Shane sớm phát hiện những siêu kỹ năng mà Rex đã từng được huấn luyện để đóng những cảnh phim ngoạn mục. Shane và Rex cùng tham gia vào những trận chiến với \</p>', 'Full', 1, 'single', 'completed', 10, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Hutcherson","avatar":""},{"name":"Bill Nunn","avatar":""},{"name":"Bruce Greenwood","avatar":""},{"name":"Dash Mihok","avatar":""},{"name":"Steven Culp","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324520);
