INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-viet-quat-trong-dem', 'Mùi Việt Quất Trong Đêm', 'My Blueberry Nights', 'null', 'https://phimimg.com/upload/vod/20230910-1/2f624f7b9942d62b7626090ee9e41a50.jpg', '<p>Elizabeth vừa trải qua một cuộc chia tay đặc biệt khó chịu và giờ cô sẵn sàng bỏ lại bạn bè và những kỷ niệm phía sau để theo đuổi ước mơ của mình trên khắp đất nước. Để hỗ trợ bản thân trên hành trình của mình, Elizabeth nhận một loạt công việc phục vụ bàn trên đường đi. Khi Elizabeth vượt qua con đường với hàng loạt linh hồn lạc lối mà khao khát của họ thậm chí còn lớn hơn cả chính cô, sự rối loạn cảm xúc của họ cuối cùng đã giúp cô hiểu rõ hơn về các vấn đề của chính mình...</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Norah Jones","avatar":""},{"name":"Jude Law","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Cat Power","avatar":""},{"name":"Frankie Faison","avatar":""},{"name":"Michael Delano","avatar":""},{"name":"Chad R. Davis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324520);
