INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('majin-tantei-nougami-neuro', 'Majin Tantei Nougami Neuro', 'Majin Tantei Nougami Neuro', 'https://phimimg.com/upload/vod/20231219-1/e1e65ffc744aad055f41d99215f0d340.jpg', 'https://phimimg.com/upload/vod/20231219-1/dede07e4fcdb089e60880395ce9ec986.jpg', '<p>Ác quỷ Neuro luôn luôn thèm khát được ăn những bí ẩn. Ở địa ngục không thể nào thỏa mãn được cơn đói đó nên Neuro đã lên thế giới loài người nhằm tìm kiếm những bí ẩn. Vụ án mạng của cha một cô gái có vẻ khá hấp dẫn với Neuro... Nhưng điều gì còn đang chờ đợi hai người ở phía trước? Hãy cùng tìm hiểu trong series án mạng cực gay cấn và hấp dẫn này.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 9, 2007, 'Vietsub', 'Full HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
