INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-nien-su-nanoha-phan-3', 'Biên Niên Sử Nanoha (Phần 3)', 'Nanoha (Season 3)', 'https://phimimg.com/upload/vod/20231219-1/4e22ff1fe8ac582adabf498353783120.jpg', 'https://phimimg.com/upload/vod/20231219-1/4336cd9aeb231ed3d9dd3e5c9c854f65.jpg', '<p>Lấy bối cảnh 10 năm sau Nanoha As. Nanoha, Fate và Hayate lúc này đã là những thành viên chủ chốt của Cục quản lý Không gian và Thời gian. Họ đóng vai trò là những người hướng dẫn cho thế hệ pháp sư tiếp theo là Subaru, Tiana, Caro và Erio. Đồng thời, mọi người sẽ phải chiến đấu với kẻ thù từ Project F, chính là chương trình mà mẹ của Fate đã tham gia trước kia.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 9, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324520);
