INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-dat-truoc', 'Không Đặt Trước', 'No Reservations', 'https://phimimg.com/upload/vod/20231219-1/37a04bc5cefb61198280fcff5caf55de.jpg', 'https://phimimg.com/upload/vod/20231219-1/a3569637f98ac382fc6d2b2658508e0c.jpg', '<p>Cô bếp trưởng Kate là một người có cuộc sống nghiêm nghị, quy củ và khó gần, đặc biệt với những ai làm cho bếp ăn của cô mất đi sự hoàn hảo. Có lẽ tính cách đó đã làm cho cuộc sống riêng của Kate trôi đi trong cô đơn. Nhưng tất cả dường như đã thay đổi khi Nick, một chàng phụ bếp đẹp trai, trẻ trung đến căn bếp của cô.</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Aaron Eckhart","avatar":""},{"name":"Abigail Breslin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324520);
