INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('return-to-house-on-haunted-hill', 'Return To House On Haunted Hill', 'Return To House On Haunted Hill', 'https://phimimg.com/upload/vod/20231219-1/004dbbd5bf57ec001d105f4de0668001.jpg', 'https://phimimg.com/upload/vod/20231219-1/9a2837bf5cbca4d69d8ef0dd78bf6e3d.jpg', '<p>Tám năm đã trôi qua kể từ khi Sara Wolfe và Eddie Baker thoát khỏi Ngôi nhà trên Đồi Ma ám. Giờ đây, Ariel, em gái của Sara, bị bắt cóc, vào trong nhà cùng với một nhóm thợ săn kho báu để tìm bức tượng Baphomet, trị giá hàng triệu đô la và được cho là nguyên nhân dẫn đến tội ác của Ngôi nhà.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Righetti","avatar":""},{"name":"Cerina Vincent","avatar":""},{"name":"Erik Palladino","avatar":""},{"name":"Jeffrey Combs","avatar":""},{"name":"Andrew Pleavin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
