INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-hoa-bao-truoc', 'Tai Họa Báo Trước', 'Cassandra''s Dream', 'https://phimimg.com/upload/vod/20231214-1/bcc9a06d8eb8fe53f26d2a7e21cad369.jpg', 'https://phimimg.com/upload/vod/20231214-1/1b3c25e936201122460fa3722c5134c6.jpg', '<p>Câu chuyện về hai anh em gặp khó khăn nghiêm trọng về tài chính. Khi một bên thứ ba đề xuất, họ chuyển sang phạm tội, mọi thứ trở nên tồi tệ và cả hai trở thành kẻ thù của nhau.</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Hayley Atwell","avatar":""},{"name":"Sally Hawkins","avatar":""},{"name":"Tom Wilkinson","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324520);
