INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-toi-yuma', 'Chuyến Tàu Tới Yuma', '3:10 To Yuma', 'https://phimimg.com/upload/vod/20231213-1/29eac63335b4d4cc2fc86f98b63350f6.jpg', 'https://phimimg.com/upload/vod/20231213-1/35887632437cd0a85861befc53fdbce3.jpg', '<p>Dan Evans để lại một chân ở chiến trường trong cuộc nội chiến Mỹ. Anh tới bang Arizona để kiếm sống bằng nghề chăn nuôi gia súc. Tình trạng hạn hán liên miên cùng với sự chèn ép của chủ trang trại bên cạnh đẩy gia đình anh vào cảnh nợ nần triền miên. Khốn quẫn lên tới đỉnh điểm khi những kẻ lạ mặt đột nhập vào trang trại của Dan lúc nửa đêm và đốt cháy nhà kho. Đến sáng hôm sau, gia đình anh hầu như chẳng còn gì. Trong lúc rong ruổi tới thị trấn tìm việc làm, Dan và hai cậu con trai chứng kiến một vụ cướp xe chở tiền vô cùng táo bạo. Nhóm cướp do Ben Wade và Charlie Price cầm đầu. Bất chấp sự phản đối của Charlie, Ben quyết định không bắn 3 nhân chứng sau khi Dan hứa sẽ im lặng...</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Christian Bale","avatar":""},{"name":"Ben Foster","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324520);
