INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-tho-cao-ma-quy-tren-pho-fleet', 'Gã Thợ Cạo Ma Quỷ Trên Phố Fleet', 'Sweeney Todd The Demon Barber Of Fleet Street', 'https://phimimg.com/upload/vod/20231212-1/4e8523d55993d1c4d3ab7eb779c7d548.jpg', 'https://phimimg.com/upload/vod/20231212-1/f9e804c807e1d6bc2bf8f9476521ea7a.jpg', '<p>Để chiếm đoạt người vợ đẹp mê hồn của Benjamin Baker - một anh thợ cạo - viên thẩm phán Turpin nhẫn tâm hãm hại khiến anh bị đi tù, nhà cửa tan nát. Sau 15 năm bị đày ải, Benjamin vượt ngục, trở lại London thì hay tin vợ đã tự sát, đứa con bị Turpin giam giữ. Đau đớn và uất hận, Benjamin đổi tên thành Sweeney Todd và bắt đầu kế hoạch trả thù man rợ.</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Jamie Campbell Bower","avatar":""},{"name":"Jayne Wisener","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324520);
