INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-voi-thien-nhien', 'Về Với Thiên Nhiên', 'Into The Wild', 'https://phimimg.com/upload/vod/20231211-1/09dce130ea2cb02410d9b64fb7c98de7.jpg', 'https://phimimg.com/upload/vod/20231211-1/e0f5e1300d9b9f3590189d6250838a11.jpg', '<p>Sau khi tốt nghiệp đại học Emory vào năm 1992, chàng cựu sinh viên và cũng là một vận động viên tài giỏi Christopher quyết định hiến hết $24,000 trong tài khoản tiết kiệm của mình cho từ thiện và đi đến vùng Alaska sống hòa mình với thiên nhiên.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emile Hirsch","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Catherine Keener","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324520);
