INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-chang-sieu-quay', 'Anh Chàng Siêu Quậy', 'Hot Rod', 'https://phimimg.com/upload/vod/20231211-1/0e5edac25e5935949cfed0057b91d98e.jpg', 'https://phimimg.com/upload/vod/20231211-1/838b6839a4597716eeec7c612e12e94f.jpg', '<p>Đối với Rod Kimble, thực hiện các pha nguy hiểm là một cách sống, mặc dù anh ấy khá dễ gặp tai nạn. Rod tội nghiệp thậm chí không nhận được bất kỳ sự tôn trọng nào từ cha dượng Frank, người đã đánh bại anh ta trong các trận đấu đối kháng hàng tuần. Khi Frank ngã bệnh, Rod nghĩ ra trò nguy hiểm kỳ quặc nhất của mình để quyên góp tiền cho ca phẫu thuật của Frank -- và sau đó Rod sẽ đá vào mông Frank.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Andy Samberg","avatar":""},{"name":"Jorma Taccone","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Danny McBride","avatar":""},{"name":"Isla Fisher","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324520);
