INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-bao-2007', 'Tình Báo', 'Rendition', 'https://phimimg.com/upload/vod/20231211-1/26ce8cdb0500018e563bbb5a98fd2d92.jpg', 'https://phimimg.com/upload/vod/20231211-1/5516310d62fe892307419aa41fd01e3a.jpg', '<p>Khi một vụ đánh bom khủng bố ở Bắc Phi giết chết 19 bao gồm. Một kỹ sư hóa học Ai Cập, một kỹ sư hóa học Ai Cập bay từ Nam Phi đến vợ ở Mỹ, bị bắt khi đến Hoa Kỳ. Anh biến mất. Vợ anh hỏi Thượng nghị sĩ để được giúp đỡ.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324520);
