INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tham-cua-doi-canh-sat', 'Chuyến Thăm Của Đội Cảnh Sát', 'The Band''s Visit', 'https://phimimg.com/upload/vod/20231211-1/0311d9e0dadaeca065ca922e0be5a174.jpg', 'https://phimimg.com/upload/vod/20231211-1/99648d7e99876eb2256c63e035cf262d.jpg', '<p>Phim là một câu chuyện bình dị, kể về một nhóm cảnh sát Hi Lạp đi thăm một vùng xa mạc hẻo lánh ở Israel và bị lạc ở đó. Tại vùng đất gần như bị cô lập này, họ đã được tiếp xúc với những người dân nghèo khổ, để thấu hiểu hơn về cuộc sống của họ. Câu chuyện giản dị, nó là những vết cắt đời thường song được truyền đạt một cách hết sức xúc động đến người xem…</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sasson Gabai","avatar":""},{"name":"Ronit Elkabetz","avatar":""},{"name":"Khalifa Natour","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324520);
