INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-bau-o-cali', 'Kho Báu Ở Cali', 'King Of California', 'https://phimimg.com/upload/vod/20231212-1/d734c8ddcfebbfb492d6c6c3c0429f1a.jpg', 'https://phimimg.com/upload/vod/20231212-1/980ba8a772710ff3137caef800f05372.jpg', '<p>Charlie được thả khỏi nhà thương điên và chuyển đến sống với Miranda, cô con gái nhỏ mà anh đã bỏ lại. Charlie tin rằng có kho báu được giấu bên dưới Costco địa phương, vì vậy anh ấy đã cùng nhau lên kế hoạch khai quật chiến lợi phẩm. Bằng cách thuyết phục Miranda nghỉ việc tại McDonalds và thay vào đó làm việc tại cửa hàng bán buôn, anh ta có thể lấy được chìa khóa. Mặc dù Miranda hay nghi ngờ nhưng cô vẫn giúp cha mình thực hiện nhiệm vụ phi lý của ông.</p>', 'Full', 1, 'single', 'completed', 10, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Evan Rachel Wood","avatar":""},{"name":"Willis Burks II","avatar":""},{"name":"Kathleen Wilhoite","avatar":""},{"name":"Arthur Santiago","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324520);
