INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-23-bi-an', 'Số 23 Bí Ẩn', 'The Number 23', 'https://phimimg.com/upload/vod/20231212-1/080a8299555a8c5f9d4fe84543e8336b.jpg', 'https://phimimg.com/upload/vod/20231212-1/575aa89e8d7c345da5dd91f1791c92b7.jpg', '<p>Vào ngày sinh nhật của mình, Walter Sparrow, một người bắt chó đáng yêu, thực hiện một cuộc gọi khiến anh ta đến muộn và trễ để đón vợ. Cô ấy đã duyệt vào một cuốn sách sau, tìm một cuốn tiểu thuyết được bao phủ màu đỏ, một bí ẩn giết người với số học vòng lặp liên tục xung quanh số 23. Câu chuyện quyến rũ Walter: Anh ấy mơ ước, anh ấy nhận thấy các khía cạnh của cuộc sống của anh ấy có thể được kết xuất bởi 23 , Anh ta tìm kiếm tác giả, anh ta ở lại khách sạn (trong phòng 23) nơi các sự kiện trong tiểu thuyết diễn ra, và anh ta bắt đầu tin rằng đó không phải là tiểu thuyết. Vợ và con trai của anh ta cố gắng giúp anh ta, đôi khi trong sự cảm thông, đôi khi để bảo vệ anh ta. Dần dần, với sự nguy hiểm với chính mình và với gia đình anh, anh nhắm vào sự thật.</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324520);
