INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-dai-ngan-ha', 'Vượt Dải Ngân Hà', 'Across The Universe', 'https://phimimg.com/upload/vod/20231212-1/316b81807937447988b88d8dbf9f5a2c.jpg', 'https://phimimg.com/upload/vod/20231212-1/42d619de65c3a8e1f527bd3248f02ea5.jpg', '<p>Vượt Dải Ngân Hà là bộ phim đậm chất văn hóa Mỹ thập kỷ 60 với phong trào chống lại chiến tranh, những hoài bão tự do của thanh niên Mỹ và tất nhiên không thể thiếu những ca khúc bất hủ của The Beatles. Bộ phim như một bản tình ca sôi nổi của Jude, một chàng trai Anh đã vượt đại dương đi tới nước Mỹ để tìm lại cha mình và Lucy, cô gái Mỹ có một người bạn trai đã hy sinh tại chiến trường...</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Evan Rachel Wood","avatar":""},{"name":"Jim Sturgess","avatar":""},{"name":"Joe Anderson","avatar":""},{"name":"Dana Fuchs","avatar":""},{"name":"Martin Luther McCoy","avatar":""},{"name":"T.V. Carpio","avatar":""},{"name":"Spencer Liff","avatar":""},{"name":"Lisa Dwyer Hogg","avatar":""},{"name":"Nicholas Lumley","avatar":""},{"name":"Michael Ryan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324520);
