INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-quai-vat-ho-loch-ness', 'Huyền Thoại Quái Vật Hồ Loch Ness', 'The Water Horse', 'https://phimimg.com/upload/vod/20231211-1/f61c2a67a610532bcffe73cf4ad20ee7.jpg', 'https://phimimg.com/upload/vod/20231211-1/40635795309f1fe0803c4a95b43e8131.jpg', '<p>Khi quả trứng nở, một chú khủng long con xuất hiện. Angus coi chú là một con vật nuôi độc nhất vô nhị đặt tên là Crusoe. Rắc rối xảy ra khi Crusoe lớn quá nhanh và thu hút sự chú ý của mọi người xung quanh hồ. Tình bạn của Angus với Crusoe không cho phép cậu bỏ mặc chú khủng long dưới sự hiếu kỳ thái quá của mọi người. Cậu bé đã tìm mọi cách để Crusoe được sinh sống yên ổn trong môi trường tự nhiên.</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emily Watson","avatar":""},{"name":"David Morrissey","avatar":""},{"name":"Alex Etel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324520);
