INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-tinh-nhue', 'Biệt Đội Tinh Nhuệ', 'Elite Squad', 'https://phimimg.com/upload/vod/20231211-1/974f58379099fd5f1843d1bc34d12484.jpg', 'https://phimimg.com/upload/vod/20231211-1/dac5429071cc4db5be13ad649c76e456.jpg', '<p>Bộ phim mô tả tình trạng tham nhũng, bạo lực và giết chóc chung quanh cuộc đấu tranh của đội cảnh sát đặc nhiệm của Rio de Janero chống lại các băng nhóm buôn lậu ma túy có trang bị vũ khí trong thành phố. Nhiều thập niên, thủ phủ người Nam Mỹ ở de Janeiro Rio, Brasil đã choáng váng với những vụ chết. Strewn khu ổ chuột bị thành sẹo bởi bạo lực và máu. Đều đặn là patrolled bởi những tốp thuốc điên mà có trận đánh lửa với cảnh sát thường căng ở ngoài lên trên những đường phố lớn chính và sự quay lại bình thường của những thường dân vào trong những tổn thất</p>', 'Full', 1, 'single', 'completed', 32, 2007, 'Vietsub', 'HD', 'Bồ Đào Nha', 0, '[{"name":"Wagner Moura","avatar":""},{"name":"Caio Junqueira","avatar":""},{"name":"André Ramiro","avatar":""},{"name":"Milhem Cortaz","avatar":""},{"name":"Fernanda Machado","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324520);
