INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-bau-quoc-gia-2-quyen-sach-bi-mat', 'Kho Báu Quốc Gia 2: Quyển Sách Bí Mật', 'National Treasure: Book Of Secrets', 'https://phimimg.com/upload/vod/20240103-1/71d5fcd002486f686d5c8620634ec32c.jpg', 'https://phimimg.com/upload/vod/20240103-1/a64158c2c4f27f0a87ac03b4325ad985.jpg', '<p>Vài năm kể từ Benjamin Franklin Gates (Nicolas Cage) đã tìm thấy Templar của Hiệp sĩ và trở nên giàu có và nổi tiếng. Bây giờ, một thợ săn kho báu khác tên Mitch Wilkinson (Ed Harris) đã tìm thấy một trang thiếu sót của Nhật ký John Wilkes, nơi chứa manh mối cho vị trí của một thành phố vàng bị mất, Ben phải cạnh tranh với Mitch để tìm thành phố bị mất , anh ta đến Pháp và Vương quốc Anh để tìm những manh mối khác và thậm chí là đỉnh cao trong cuốn sách bí mật của tổng thống để cùng nhau đặt các mảnh ghép với nhau, cha mẹ và bạn bè của anh ta cũng giúp Ben tìm thành phố bị mất và đi trước một bước đi trước Mitch.</p>', 'Full', 1, 'single', 'completed', 6, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324520);
