INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-simpsons-movie', 'The Simpsons Movie', 'The Simpsons Movie', 'https://phimimg.com/upload/vod/20231211-1/bc15e28026954829090aedf25c48f7d3.jpg', 'https://phimimg.com/upload/vod/20231211-1/43fa99302b355275943db757f036989a.jpg', '<p>Homer thông qua một con lợn đang chạy trốn khỏi Krusty Burger sau Krusty cố gắng giết anh ta, đặt tên cho con lợn Lợn nhện. Đồng thời, hồ được bảo vệ sau khi khán giả chìm vào ngày xanh sà lan là vào thùng rác sau khi họ đề cập đến môi trường. Trong khi đó, chất thải của Spider Lợn đã lấp đầy một silo chỉ trong 2 ngày, dường như với sự giúp đỡ của Homer. Homer không thể đến bãi rác nhanh chóng để đổ silo trong hồ, gây ô nhiễm nó. Russ Cargill, ông chủ phản diện của EPA, mang đến Arnold Schwarzenegger, Tổng thống Hoa Kỳ, 5 lựa chọn và buộc ông chọn 4 (không may, để tiêu diệt Springfield) và đưa một mái vòm lên Springfield để ngăn chặn sơ tán. Homer, tuy nhiên, đã trốn thoát, cùng với gia đình. Anh ta có thể ngăn chặn Cargill độc ác từ việc tiêu diệt thị trấn quê hương của mình, và gia đình anh ta đã bị buộc phải trở về Springfield?</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324520);
