INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-sau-cua-so', 'Tội Ác Sau Cửa Sổ', 'Disturbia', 'https://phimimg.com/upload/vod/20231211-1/867c8f76e8f9c0387db7edc8f3fba886.jpg', 'https://phimimg.com/upload/vod/20231211-1/f4cca4abc9a0bf45bbebaf773d48fa96.jpg', '<p>Kale là một thanh niên 17 tuổi bị quản thúc tại gia sau khi đấm giáo viên của mình. Anh ta bị giam trong nhà và quyết định sử dụng thời gian rảnh rỗi để theo dõi những người hàng xóm của mình. Mọi thứ bắt đầu trở nên kỳ lạ khi những vị khách bước vào nhà của Turner và không quay trở ra. Kale và những người bạn của mình, Ronnie và Ashley, bắt đầu ngày càng quan tâm hơn đến những gì đang thực sự xảy ra trong ngôi nhà của Robert Turner.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shia LaBeouf","avatar":""},{"name":"Sarah Roemer","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"David Morse","avatar":""},{"name":"Aaron Yoo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
