INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-cao-diem-3', 'Giờ Cao Điểm 3', 'Rush Hour 3', 'https://phimimg.com/upload/vod/20231210-1/eeaa20506534d24246457c953c48019f.jpg', 'https://phimimg.com/upload/vod/20231210-1/ab5860df9137b0922a9a9ace30b6190b.jpg', '<p>Gần ba năm sau cuộc phiêu lưu cuối cùng của họ trong Rush Hour 2 (2001), Carter hiện đang làm nhân viên giao thông Los Angeles, trong khi bạn của ông và Thanh tra cảnh sát Ace Hồng Kông, Lee, hộ tống Đại sứ Trung Quốc, Han, đến Tòa án Hình sự Thế giới , để tiết lộ thông tin quan trọng về các bộ ba. Tuy nhiên, sau một nỗ lực ám sát đã bị phá vỡ, bộ đôi không phù hợp sẽ thấy mình ở Paris đẹp như tranh vẽ, vật lộn để lấy một danh sách tên quý giá, vì tay sai của tội ác giết người cố gắng hết sức để ngăn chặn họ. Một lần nữa, Lee và Carter phải chiến đấu theo cách của họ thông qua các băng dâm nguy hiểm; Tuy nhiên, lần này, quá khứ đã quay trở lại Haunt Lee. Các chàng trai sẽ hoàn thành công việc một lần và mãi mãi?</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324520);
