INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-mo-duong', 'Người Mở Đường', 'Pathfinder', 'https://phimimg.com/upload/vod/20231209-1/7dfd8b5556e74ba1d08fd34c153bb301.jpg', 'https://phimimg.com/upload/vod/20231209-1/2fe6c22e5de82f93b0bbb896cf9f524d.jpg', '<p>Đây là phim mang yếu tố hành Động: Gần 1 ngàn năm trước, người Vikings thống trị biển cả, có một cậu bé tộc Vikings chẳng may bị bỏ lại khi bộ tộc di cư, cậu được đem về và nuôi dưỡng bởi 1 tộc người bản địa. Nhiều năm trôi qua, cậu bé ngày nào đã trở thành 1 chiến binh dũng mãnh và đó cũng là lúc người Vikings trở lại, không tìm lại người xưa mà để thôn tính, xâm chiếm các bộ tộc khác, trong đó có bộ lạc của chàng chiến binh đã sống và lớn lên..</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Karl Urban","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Moon Bloodgood","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324520);
