INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('single-blog', 'Single Blog', 'Single Blog', 'null', 'https://phimimg.com/upload/vod/20231210-1/b870253d5ba88c46bc5552b88d6e9acb.jpg', '<p>Tình dục hay tình yêu, cái nào quan trọng hơn? Có ba người bạn tình nữ: Vivian là phù phiếm, Kitty là người đứng đắn và đứng đắn, và Mei Wah thì bủn xỉn. Thông qua những trải nghiệm mới về tình yêu và tình dục, họ tìm thấy chính mình. Ba người phụ nữ, với ba kinh nghiệm tình yêu và tình dục khác nhau, cho chúng ta biết rằng tình dục và tình yêu không thể tách rời. Phụ nữ nói nhiều luôn khiến bạn chìm đắm trong suy nghĩ.</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Caihua Li","avatar":""},{"name":"Jo Koo","avatar":""},{"name":"Monie Tung","avatar":""},{"name":"Anya","avatar":""},{"name":"Chen Hui Hong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324520);
