INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-sao-ma-thuat', 'Ánh Sao Ma Thuật', 'Stardust', 'https://phimimg.com/upload/vod/20231210-1/dfcc15d9535d30dd997e7a5e99752a27.jpg', 'https://phimimg.com/upload/vod/20231210-1/e25d7b4148927bb60f9cb232b11f9137.jpg', '<p>Phim là câu chuyện về Tristan - một chàng trai ở một làng quê nhỏ - quyết định dấn thân vào vùng đất ma thuật để tìm món quà cho người mà anh yêu. Anh không ngờ rằng món quà anh đang tìm kiếm lại là một ngôi sao ma thuật, một cô gái sẽ dẫn anh vào những cuộc phiêu lưu kì lạ và sẽ thay đổi cuộc đời anh mãi mãi...</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlie Cox","avatar":""},{"name":"Claire Danes","avatar":""},{"name":"Sienna Miller","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324520);
