INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-quay-so-phan', 'Vòng Quay Số Phận', 'The Air I Breathe', 'null', 'https://phimimg.com/upload/vod/20231209-1/75836384827bfeddc3ac1da599ecba63.jpg', '<p>Vòng Quay Số Phận - The Air I Breathe kể về bốn nhân vật: một vị thương gia đặt cược cuộc sống của mình dựa vào những con ngựa đua, một tay găng tơ có thể nhìn thấy được tương lai, một ngôi sao ca nhạc trở thành con mồi của một tay trùm tội phạm và một vị bác sĩ chạy đua với thời gian để cứu lấy tình yêu của cuộc đời mình… Bốn câu chuyện được lồng ghép khéo léo trong bộ phim tượng trưng cho bốn thứ cảm xúc cơ bản của con người trong cuộc sống bao gồm vui sướng, giận dữ, yêu thương và ghét bỏ.</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324520);
