INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-soi', 'Hồn Sói', 'Blood And Chocolate', 'https://phimimg.com/upload/vod/20231209-1/b93462ef525e0e589530a282cd7bcd22.jpg', 'https://phimimg.com/upload/vod/20231209-1/b41bd99d2b6094925399106e1da0ff6a.jpg', '<p>Một người sói tuổi teen bị giằng xé giữa việc tôn vinh bí mật của gia đình và tình yêu của cô dành cho một người đàn ông.</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Agnes Bruckner","avatar":""},{"name":"Hugh Dancy","avatar":""},{"name":"Katja Riemann","avatar":""},{"name":"Olivier Martinez","avatar":""},{"name":"Bryan Dick","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324520);
