INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('paranormal-activity', 'Paranormal Activity', 'Paranormal Activity', 'https://phimimg.com/upload/vod/20231210-1/f0abefcdebd0707aa853e7bd54eacd84.jpg', 'https://phimimg.com/upload/vod/20231210-1/e69173508970ceea660dbc6e7a30819a.jpg', '<p>Sau khi một cặp vợ chồng trẻ thuộc tầng lớp trung lưu chuyển đến một nơi có vẻ giống như một ngôi nhà ngoại ô điển hình, họ ngày càng trở nên lo lắng bởi sự hiện diện có thể là ma quỷ hoặc không nhưng chắc chắn là hoạt động tích cực nhất vào lúc nửa đêm. Tiếp theo là năm phần đáng sợ trong loạt phim, đây là cảnh gây sốc ban đầu được tìm thấy đã bắt đầu tất cả.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katie Featherston","avatar":""},{"name":"Micah Sloat","avatar":""},{"name":"Mark Fredrichs","avatar":""},{"name":"Amber Armstrong","avatar":""},{"name":"Ashley Palmer","avatar":""},{"name":"Crystal Cartwright","avatar":""},{"name":"Spencer Marks","avatar":""},{"name":"Randy McDowell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
