INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dung-cam', 'Người Dũng Cảm', 'The Brave One', 'https://phimimg.com/upload/vod/20231210-1/da09b8a6b3862b031501acb52de1d84f.jpg', 'https://phimimg.com/upload/vod/20231210-1/ec311b57c55aae2375b5a8fb70545a2f.jpg', '<p>Là một phát thanh viên nổi tiếng của đài NY, có một vị hôn phu yêu thương hết mực, Erica Bain (Jodie Foster thủ diễn) đã có một cuộc sống hạnh phúc mà cô luôn yêu quí nhưng...một tối nọ, những điều Erica hết mực yêu quí ấy chẳng may bị cướp đi tất cả bởi 1 lũ côn đồ, chúng làm trọng thương cô còn người chồng sắp cưới thì bị giết chết.Quá phẫn uất, Erica quyết tâm phải trả thù, hòa lẫn vào từng đêm đen New York, cô tìm và giết từng kẻ một nhưng càng dấn sâu vào cuộc trả thù, Erica mới nhận ra rằng, mình đang dần trở thành chẳng khác gì so với lũ côn đồ lúc xưa...</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jodie Foster","avatar":""},{"name":"Terrence Howard","avatar":""},{"name":"Nicky Katt","avatar":""},{"name":"Naveen Andrews","avatar":""},{"name":"Mary Steenburgen","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
