INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-xe-4', 'Quái Xế 4', 'Taxi 4', 'https://phimimg.com/upload/vod/20231209-1/2313a5b931f2bce1c858b25a581f1811.jpg', 'https://phimimg.com/upload/vod/20231209-1/433c3f2194d507151dd28658137b7091.jpg', '<p>Một nhóm tội phạm... vui nhộn. Nghe có vẻ vô lý nhỉ, nhưng đúng là những tội phạm người Bỉ này khiến ai cũng phải nghi ngờ khả năng… phạm tội của chúng. Hãy tới Marseilles cùng tham gia vào chuyến phiêu lưu rượt đuổi của giữa một tài xế taxi cực nhanh lẹ tinh thông và những gã cớm... gàn, thao tác chậm chạp quá sức tưởng tượng. Cuộc rượt đuổi dài cả 24 tiếng đằng đẵng, vượt qua bao nhiêu chặng đường như xi nê và để lại bao nhiêu trận cười hấp dẫn! Cuối cùng, Daniel và Emilien, hai cảnh sát kỳ cựu, có vẻ sắp đầu hàng...</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Samy Naceri","avatar":""},{"name":"Frédéric Diefenthal","avatar":""},{"name":"Bernard Farcy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324520);
