INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-ba-ten-cuop-the-ki', 'Mười Ba Tên Cướp Thế Kỉ', 'Ocean''s Thirteen', 'https://phimimg.com/upload/vod/20231209-1/63a52339cb76b0803164759ab6f37f3b.jpg', 'https://phimimg.com/upload/vod/20231209-1/654fab6da74773ad3b358c34835e7bd4.jpg', '<p>Reuben, một thành viên trong băng cướp Ocean, cùng hợp tác xây khách sạn và sòng bạc với Willy. Nhưng gã này đã khéo léo gạt Reuben và một mình, chiếm lấy quyền điều khiển khách sạn, để lại cho Reuben một món tiền bèo bọt và một cơn đau tim khiến ông phải đi cấp cứu. Ocean, và đội quân hợp tác với Benedict, quyết định trả thù với mong muốn Willy sẽ phá sản ngay trong đêm khai trương, và cướp lấy những viên kim cương của gã này...</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Matt Damon","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324520);
