INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loai-ac-doc-4-tinh-giac', 'Loài Ác Độc 4: Tỉnh Giấc', 'Species: The Awakening', 'https://phimimg.com/upload/vod/20231208-1/f007f09581700b30da1bfdbf3f6fb50c.jpg', 'https://phimimg.com/upload/vod/20231208-1/79e1924eebba07209c005c447e6b6c9f.jpg', '<p>Miranda được một người chú tên Tom đem về nuôi dưỡng và cho ăn học tử tế. Từ bé đến lớn, cô không về thắc mắc về thân thế của mình. Khi đã là một giảng viên đại học danh tiếng, Miranda không còn bận tâm đến việc tìm hiểu xem cha mẹ ruột của mình là ai. Với cô, có được sự yêu thương của chú Tom là quá đủ. Nhưng một ngày kia, Miranda bỗng nhiên bất tỉnh. Lúc mở mắt ra, cô thấy mình nằm giữa một bãi máu, giống như vừa có một vụ thảm sát xảy ra mà cô chính là hung thủ. Hết sức sợ hãi, Miranda tìm gặp người chú để hỏi rõ sự tình. Cô kinh hoàng khi biết được sự thật rằng mình chỉ mang một nửa dòng máu con người, nửa kia được tạo ra từ ADN của người ngoài hành tinh...</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Helena Mattsson","avatar":""},{"name":"Ben Cross","avatar":""},{"name":"Dominic Keating","avatar":""},{"name":"Marlene Favela","avatar":""},{"name":"Meagen Fay","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
