INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-dong-am-nhac', 'Thần Đồng Âm Nhạc', 'August Rush', 'https://phimimg.com/upload/vod/20231208-1/7f4a2ab966f9d7e11b553e1126c856a4.jpg', 'https://phimimg.com/upload/vod/20231208-1/288ed805660c2104f01abfcee85ffbf2.jpg', '<p>Lyla và Louis, một ca sĩ và một nhạc sĩ, yêu nhau nhưng nhanh chóng buộc phải chia tay. Lyla buộc phải từ bỏ đứa con mới sinh của mình nhưng cô không hề hay biết, cậu bé lớn lên trở thành một thiên tài âm nhạc.</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Freddie Highmore","avatar":""},{"name":"Keri Russell","avatar":""},{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Terrence Howard","avatar":""},{"name":"Robin Williams","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324520);
