INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-ngu-lam-quan', 'Sứ Mệnh Ngự Lâm Quân', 'In The Name Of The King: A Dungeon Siege Tale', 'https://phimimg.com/upload/vod/20231208-1/733cde77f464ad47feb256ab3d8a1f8a.jpg', 'https://phimimg.com/upload/vod/20231208-1/6b006f4b8e3be2bf46536dfaaf2148c9.jpg', '<p>Một người đàn ông tên Farmer lên đường giải cứu người vợ bị bắt cóc và trả thù cho cái chết của con trai mình - hai hành động được thực hiện bởi Krugs, một chủng tộc gồm các chiến binh động vật bị điều khiển bởi ác nhân Gallian.</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"John Rhys-Davies","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Leelee Sobieski","avatar":""},{"name":"Burt Reynolds","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324520);
