INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-tham', 'Mật Thám', 'Breach', 'https://phimimg.com/upload/vod/20231208-1/c314366948f985484b047faa6d1df43c.jpg', 'https://phimimg.com/upload/vod/20231208-1/9f97a50de1c31c15117343d421d9d47f.jpg', '<p>Vào một sáng chủ nhật lạnh giá, nhân viên tập sự Eric ONeill (Ryan Phillippe) bị gọi tới nhiệm sở và được giao nhiệm vụ đặc biệt: tới văn phòng mới có tên gọi bộ phận bảo mật, trở thành thư ký cho Robert Hanssen (Chris Cooper), một điệp viên cao cấp của FBI. Vốn xuất thân từ ngành tình báo và nể phục Hanssen như cha ruột, Eric coi nhiệm vụ lần này là cơ hội để anh học hỏi từ chuyên gia hàng đầu của Mỹ về công tác phản gián Xô Viết nhằm nhanh chóng được toại nguyện tham vọng trở thành điệp viên. Tuy nhiên FBI lại có kế hoạch khác để sử dụng anh, qua điều tra, FBI phát giác ra rất nhiều tài liệu quan trọng bị lọt vào tay Liên Xô, làm thiệt hại cho Hoa kỳ nhiều tỷ đô la. Bên cạnh đó, việc Hanssen liên tục thoát chết nhiều lần trong gang tấc trong khi các nhân viên của ông bị bắt, giết chết thảm thương làm FBI nảy sinh nghi vấn. Nhiệm vụ thực sự của anh là trông chừng sếp, tìm bằng chứng về tội phản quốc của nhân vật đã có 30 năm làm việc cho Cục Điều tra Liên bang.</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Cooper","avatar":""},{"name":"Ryan Phillippe","avatar":""},{"name":"Laura Linney","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"Caroline Dhavernas","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
