INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-nha-shrek', 'Giáng Sinh Nhà Shrek', 'Shrek The Halls', 'https://phimimg.com/upload/vod/20231219-1/3bdf5627b29065c55250869c619d2be3.jpg', 'https://phimimg.com/upload/vod/20231219-1/2b727bfb046c05316c561641d43e8808.jpg', '<p>Phim lấy bối cảnh sau khi Shrek phần 3 phát sóng, lúc Fiona vừa mới sinh em bé. Shrek đang sống yên ổn với gia đình của khu vực đầm lầy của mình thì giáng sinh tới. Dưới sự thúc giục của lừa Donkey, Shrek lưỡng lự hứa với công chúa Fiona là sẽ dành tặng nàng một món quà giáng sinh thật đặc biệt, nhưng thực ra cu cậu chẳng biết Giáng sinh là gì. Một chủ cửa hàng đã cho Shrek quyển sách Giáng sinh cho kẻ ngốc, dạy cách tổ chức giáng sinh từng bước một.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mike Myers","avatar":""},{"name":"Eddie Murphy","avatar":""},{"name":"Cameron Diaz","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324520);
