INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-dua-nguy-hiem', 'Trò Đùa Nguy Hiểm', 'Sleuth', 'https://phimimg.com/upload/vod/20231208-1/ca84ffe0b2e6f32f0b63e7a0895424f8.jpg', 'https://phimimg.com/upload/vod/20231208-1/29d6b47edd35136565463c8ed9a609ad.jpg', '<p>Trên khu đất rộng lớn ở nông thôn của mình, một nhà văn lớn tuổi đấu trí với nam diễn viên đang vật lộn, người đã đánh cắp trái tim của vợ mình.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Caine","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Harold Pinter","avatar":""},{"name":"Carmel O''Sullivan","avatar":""},{"name":"Kenneth Branagh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
