INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rise-of-the-footsoldier', 'Rise Of The Footsoldier', 'Rise Of The Footsoldier', 'https://phimimg.com/upload/vod/20231208-1/d46e148d2a2c331d056a1d33b533bece.jpg', 'https://phimimg.com/upload/vod/20231208-1/09bb8a9cc494cb5f2a58ae1906d8f942.jpg', '<p>Sự trỗi dậy của Footsolder sau sự trỗi dậy không thể tha thứ của Carlton Leach từ một trong những vị tướng đáng sợ nhất của ruộng bậc thang để trở thành thành viên của một nhóm tội phạm khét tiếng, những người dồi dào qua London và Essex vào cuối thập niên tám mươi và những năm chín mươi. Đó là ba thập kỷ cuộc đời của mình theo ông từ chủ nghĩa côn đồ bóng đá, thông qua sự nghiệp đang phát triển như một bouncer, sự tham gia của anh ta vào các khía cạnh tội phạm của bối cảnh Rave ban đầu và sau đó là sự gia tăng quyền lực nhất là một trong những người sợ hãi và tôn trọng nhất tội phạm trong nước</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324520);
