INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hieu-lenh-tap-ket', 'Hiệu Lệnh Tập Kết', 'Assembly', 'https://phimimg.com/upload/vod/20231206-1/974653ac3634b686f8749329aae82a6d.jpg', 'https://phimimg.com/upload/vod/20231206-1/44b476a6de7082c690471949fd4c4fa4.jpg', '<p>Sau khi dẫn dắt lực lượng ít ỏi chống lại đội quân Quốc Dân Đảng trong cuộc Nội chiến Trung Quốc, giờ đây Chỉ huy Cổ phải đấu tranh để thay đổi thế cờ.</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Hàm Dư","avatar":""},{"name":"Đặng Siêu","avatar":""},{"name":"Viên Văn Khang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324520);
