INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-me-noi-loan', 'Đam Mê Nổi Loạn', 'Young People Fucking', 'https://phimimg.com/upload/vod/20231205-1/9e8846b2bbcdfc054b6cef8e2f11d890.jpg', 'https://phimimg.com/upload/vod/20231205-1/0485bdcd2ed3c61ebb5fbbe1b579ca88.jpg', '<p>Vào một đêm thứ Ba, năm cặp đôi có những cuộc phiêu lưu tình dục riêng biệt. Matt và Kris, những người bạn trong nhiều năm, muốn có khoảng thời gian vui vẻ chỉ một lần, không ràng buộc. Abby và Andrew, đã kết hôn, tổ chức sinh nhật cho anh ấy, nhưng nó bị hủy hoại bởi sự tức giận và thông tin sai lệch. Mia và Eric là người yêu cũ, đảm bảo rằng họ sẽ ở bên nhau. Jaime và Ken làm việc cùng nhau và đây là buổi hẹn hò đầu tiên. Inez và Gord mời bạn cùng phòng của mình, Dave, tham gia cùng họ. Vào thời điểm mỗi cặp vợ chồng trải qua khúc dạo đầu, màn dạo đầu, tình dục, khúc dạo đầu, cực khoái và hậu vận, họ đã trả lời được những câu hỏi cơ bản: tình dục có thể ẩn danh không, chúng ta có buồn chán không, cuộc hôn nhân của chúng ta có thực sự kết thúc không, có ai nói sự thật không , và làm thế nào để chúng ta làm cho ai đó hạnh phúc?</p>', 'Full', 1, 'single', 'completed', 7, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aaron Abrams","avatar":""},{"name":"Carly Pope","avatar":""},{"name":"Kristin Booth","avatar":""},{"name":"Josh Dean","avatar":""},{"name":"Sonja Bennett","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324520);
