INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-bat-dac-di', 'Nhiệm Vụ Bất Đắc Dĩ', 'Shoot ''Em Up', 'https://phimimg.com/upload/vod/20231204-1/f7b344ef708fbc10762c408c6becd73c.jpg', 'https://phimimg.com/upload/vod/20231204-1/e181fe6973c60446c6e19d1c2d425225.jpg', '<p>Một người đàn ông lạ mặt buộc phải đối đầu với cả một đạo quân sát thủ khi anh quyết định đứng ra hợp tác với một người phụ nữ xa lạ nhằm bảo vệ cho một đứa bé sơ sinh trước sự truy sát của 1 ông trùm…</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clive Owen","avatar":""},{"name":"Monica Bellucci","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Greg Bryk","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
