INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thong-linh', 'Thống Lĩnh', 'The Warlords', 'https://phimimg.com/upload/vod/20231203-1/de47d755fe37c9b343e3c4bf9989d085.jpg', 'https://phimimg.com/upload/vod/20231203-1/b8cd5d6107c33327cf73c67ca75c0c69.jpg', '<p>Những năm 1850,đất nước Trung Hoa dưới sự cai trị triều đình nhà Thanh thối nát dần trở nên kiệt quệ bởi nạn Bạch họa (nha phiến) lại bị xâu xé bởi các nước thực dân phương Tây, thêm vào đó là nạn đói Lưỡng Quảng khiến cho hơn 430 triệu dân sống trong cảnh lầm than, khốn khổ đã làm nền cho cuộc khởi nghĩa nông dân Thái Bình Thiên Quốc. Mùa thu năm 1870, vì quá bất mãn với triều đình, Đại tướng quân họ Mã quyết định dấy binh tạo phản, dù con đường đã chọn là một con đường không có lối ra nhưng lòng tham cùng sự khao khát quyền lực đã làm lu mờ lý trí họ Mã, ông muốn mình có thể làm nên một triều đại mới thay thế triều Thanh thối nát. Nhưng số phận của Mã Tướng quân lại bị thay đổi hoàn toàn bởi ba người, họ đều là huynh đệ của nhau. Chính những kẻ đó là người đưa ông len đỉnh cao danh vọng và cũng chính họ dìm ông xuống nấm mồ sâu...</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jet Li","avatar":""},{"name":"Lưu Đức Hòa","avatar":""},{"name":"Takeshi Kaneshiro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324520);
