INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-so-sinh-menh', 'Quyển Sổ Sinh Mệnh', 'Death Note', 'https://phimimg.com/upload/vod/20231204-1/9f68cb34f61daedcf33b1874f3cdb030.jpg', 'https://phimimg.com/upload/vod/20231204-1/0ee8dd5a70b170127b953221d2872f4e.jpg', '<p>Một thần chết tên Ryuuku cố tình đánh rơi quyển sổ Death Note xuống thế giới loài người với mong muốn rằng hắn sẽ tìm được một thú vui nào đó từ việc này. Một học sinh trung học tên Yagami Light (hay Yagami Raito) là người nhặt được quyển sổ này và vì thế mà có khả năng giết bất cứ người nào chỉ bằng cách cách viết tên người đó vào quyển sổ và tưởng tượng ra khuôn mặt họ khi viết. Cậu quyết định dùng Death Note để tiêu diệt những kẻ tội phạm và những kẻ giết người tàn ác thông qua cuốn sổ. Khi tỉ lệ tôi phạm giảm xuống, mọi người nhanh chóng đặt cho cậu cái tên Kira. Đó cũng chính là lúc ICPO thuê L, thám tử tài giỏi bậc nhất thế giới, để tìm ra chân tướng thật sự của Kira...</p>', 'Hoàn Tất (37/37)', 37, 'hoathinh', 'completed', 15, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
