INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-danh-thue', 'Sát Thủ Đánh Thuê', 'Hitman', 'https://phimimg.com/upload/vod/20231204-1/7eae07c5c2f8f7b75395bce42fecf53b.jpg', 'https://phimimg.com/upload/vod/20231204-1/f5b6a958c8d29dc883ad0c9292e5bd1a.jpg', '<p>Trong bộ vest đen lịch thiệp, với gương mặt pha nét Á Đông lạnh lùng, hắn khiến những con mồi của mình phải chùn bước, run sợ mà nạp mạng cho hắn. Hắn là một Sát thủ chuyên nghiệp, được huấn luyện với tất cả những ngón nghề cùng sự khôn ngoan để lấy mạng kẻ khác, chẳng ai biết tên thật của hắn, chỉ biết hắn được gọi là 47, đó là 2 con số được in cùng 1 thanh mã vạch như trên các gói hàng đằng sau cổ và dưới cái đầu trọc lóc đến lạnh lẽo của hắn. Thợ săn trở thành con mồi khi hắn bị cả Interpol cùng quân đội Nga truy lùng khắp Đông Âu sau khi thực hiện 1 hợp đồng ám sát nhưng nguy hiểm lớn nhất đang rình rập hắn không phải từ những họng súng truy lùng kia mà là từ một ả đàn bà, kẻ đã làm con tim băng giá của 1 gã Sát thủ bắt đầu tan chảy</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Timothy Olyphant","avatar":""},{"name":"Dougray Scott","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Ulrich Thomsen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324520);
