INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('evan-toan-nang', 'Evan Toàn Năng', 'Evan Almighty', 'https://phimimg.com/upload/vod/20231202-1/6ccafbb28a1910500f86ba30da660f53.jpg', 'https://phimimg.com/upload/vod/20231202-1/391a790fd820e565ddf6e3615078e0ce.jpg', '<p>Buffalo Newsman Evan Baxter được bầu vào Quốc hội với khẩu hiệu, &quot;Thay đổi thế giới.&quot; Anh may mắn vào một ngôi nhà lớn ở vùng ngoại ô Virginia mới. Văn phòng Capitol của ông cũng là tuyệt vời, nhưng có một lời bắt: anh ta đã khai thác bởi Quốc hội mạnh mẽ lâu dài để đồng tài trợ hóa đơn cho phép phát triển trong các công viên quốc gia. Trong các bước, người xuất hiện để không tin Evan và nhẹ nhàng ra lệnh cho anh ta xây dựng một hòm. Các công cụ và gỗ đến sân của Evan, các cặp động vật theo sau, râu và tóc của anh ta phát triển điên cuồng, quần áo của Nomad và một nhân viên xuất hiện. Long phát triển thiếu kiên nhẫn, Evan bắt đầu xây dựng, gia đình anh ta rời khỏi anh ta, các phóng viên tụ tập, và hạn hán nắm chặt D.C. Tuy nhiên, Evan tin tưởng. Nhưng anh ấy sẽ thay đổi thế giới chứ?</p>', 'Full', 1, 'single', 'completed', 18, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Carell","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Lauren Graham","avatar":""},{"name":"Johnny Simmons","avatar":""},{"name":"Graham Phillips","avatar":""},{"name":"Jimmy Bennett","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Wanda Sykes","avatar":""},{"name":"John Michael Higgins","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"Harve Presnell","avatar":""},{"name":"P.J. Byrne","avatar":""},{"name":"Ralph Louis Harris","avatar":""},{"name":"Arden Myrin","avatar":""},{"name":"Brian Howe","avatar":""},{"name":"Ralph P. Mart","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324520);
