INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-o-hanh-tinh-terra', 'Cuộc Chiến Ở Hành Tinh Terra', 'Battle for Terra', 'https://phimimg.com/upload/vod/20231202-1/ca62910c822b52358254b85c8178490d.jpg', 'https://phimimg.com/upload/vod/20231202-1/1f2e5a290e22a433bf4b28ae6ea26ccb.jpg', '<p>Battle for Terra kể câu chuyện về Senn (Justin Long) và Mala (Evan Rachel Wood), hai thiếu niên nổi loạn trên hành tinh thơ mộng Terra, nơi cuộc sống hoà bình và khoan dung, không chấp nhận chiến tranh và vũ khí hủy diệt hàng loạt. Nhưng khi Terra bị những người trái đất trốn cuộc nội chiến và thảm họa môi trường đến ẩn náu thì lập tức hành tinh rơi vào hỗn loạn. Trong cuộc nổi dậy, Mala kết bạn với một phi công trái đất bị thương và hai người phát hiện ra hai chủng tộc có nhiều điểm giống nhau nhưng họ cũng nhận thấy chỉ có một chủng tộc có thể tồn tại trong hành tinh có nguồn tài nguyên giới hạn này.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Evan Rachel Wood","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"James Garner","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"David Cross","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Dennis Quaid","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Rosanna Arquette","avatar":""},{"name":"Beverly D''Angelo","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Mark Hamill","avatar":""},{"name":"Brooke Bloom","avatar":""},{"name":"Tom Connolly","avatar":""},{"name":"Michael Sco","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113