INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-phong-cua-fermat', 'Căn Phòng Của Fermat', 'Fermat''s Room', 'https://phimimg.com/upload/vod/20231202-1/a941e79f97b2a355598c0cf02d6b5ad8.jpg', 'https://phimimg.com/upload/vod/20231202-1/bf5b6a44b59ff853a3cd7ab3643fdd7a.jpg', '<p>Bốn nhà toán học không quen biết nhau được mời bởi một chủ nhà bí ẩn với lý do giải quyết một bí ẩn lớn. Căn phòng mà họ đang ở hóa ra lại là một căn phòng đang thu nhỏ lại sẽ nghiền nát họ nếu họ không kịp thời phát hiện ra điều gì đã kết nối tất cả lại với nhau và tại sao ai đó lại muốn giết họ.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Lluís Homar","avatar":""},{"name":"Santi Millán","avatar":""},{"name":"Alejo Sauras","avatar":""},{"name":"Federico Luppi","avatar":""},{"name":"Elena Ballesteros","avatar":""},{"name":"Helena Carrión","avatar":""},{"name":"Núria Badia","avatar":""},{"name":"Mar del Hoyo","avatar":""},{"name":"Ariadna Cabrol","avatar":""},{"name":"San Yélamos","avatar":""},{"name":"Alicia Fernández","avatar":""},{"name":"Josep Minguell","avatar":""},{"name":"Juanma Falcón","avatar":""},{"name":"Víctor Benjumea","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324520);
