INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-tri', 'Đấu Trí', 'Michael Clayton', 'https://phimimg.com/upload/vod/20231202-1/810e0ed5194101173a434b7daf0c2849.jpg', 'https://phimimg.com/upload/vod/20231202-1/47cbdb2f8f7df22c1fc7226a742f2e1b.jpg', '<p>Một luật sư được biết đến với cái tên Fixer nhận làm một vụ kiện lớn nhất trong sự nghiệp của mình. Nhưng đó cũng là bước ngoặt đem đến cho Fixer những hậu quả phiền toái.</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Michael O''Keefe","avatar":""},{"name":"Sydney Pollack","avatar":""},{"name":"Danielle Skraastad","avatar":""},{"name":"Wai Chan","avatar":""},{"name":"Alberto Vazquez","avatar":""},{"name":"Brian Koppelman","avatar":""},{"name":"Tom McCarthy","avatar":""},{"name":"Denis O''Hare","avatar":""},{"name":"Julie White","avatar":""},{"name":"Austin Williams","avatar":""},{"name":"Jennifer Van Dyck","avatar":""},{"name":"Frank Wood","avatar":""},{"name":"Richard Hecht","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324520);
