INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-cung-bay-xac-song', 'Bay Cùng Bầy Xác Sống', 'Flight of the Living Dead', 'https://phimimg.com/upload/vod/20231201-1/365f2a43a0ca97ea9514dadde8cdc369.jpg', 'https://phimimg.com/upload/vod/20231201-1/f381ec1e5e76182580b2a4df056438a6.jpg', '<p>Trên chuyến bay từ Los Angeles đến Paris, một nhà khoa học điên chạy trốn khỏi CIA đang vận chuyển một chiếc quan tài chứa thi thể của một đồng nghiệp bị nhiễm virus biến đổi gen. Trong khi chiếc 747 băng qua một cơn giông bão dữ dội, sự không ổn định của máy bay đã cho phép xác chết ra khỏi thùng chứa.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Chisum","avatar":""},{"name":"Kristen Kerr","avatar":""},{"name":"Richard Tyson","avatar":""},{"name":"Kevin J. O''Connor","avatar":""},{"name":"Erick Avari","avatar":""},{"name":"Laura Cayouette","avatar":""},{"name":"Siena Goines","avatar":""},{"name":"Serah D''Laine","avatar":""},{"name":"Heidi Marnhout","avatar":""},{"name":"Mieko Hillman","avatar":""},{"name":"Brian Kolodziej","avatar":""},{"name":"Dale Midkiff","avatar":""},{"name":"Brian Thompson","avatar":""},{"name":"David Spielberg","avatar":""},{"name":"Tucker Smallwood","avatar":""},{"name":"Raymond J.","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324521);
