INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-gio-gia-toc', 'Sóng Gió Gia Tộc', 'Heart Of Greed', 'https://phimimg.com/upload/vod/20231203-1/8d6bcb1541a5fcb7167320643c35ad53.jpg', 'https://phimimg.com/upload/vod/20231203-1/b63ab2cf2e55a698da7d4c108e061873.jpg', '<p>Phim xoay quanh những vấn đề xảy ra trong một gia đình giàu có có tiếng. Câu chuyện bắt đầu với ông chủ Đường Nhân Giai còn gọi là Bào lớn – một ông chủ có tiếng trong giới kinh doanh bào ngư. Bào lớn rất xem trọng hạnh phúc trong gia đình vì ông có 1 lúc 2 người vợ sống chung trong một ngôi nhà nên ông lúc nào cũng phải giữ hòa khí cho cả 2 bà vợ. Các người con của ông rất hòa thuận và yêu thương nhau. Người vợ lớn của ông là một người phụ nữ tốt bụng và biết nhường nhịn đối với người vợ nhỏ của ông. Nhưng ngược lại bà vợ nhỏ thì lúc nào cũng ít kỷ và lo sợ mình mất phần trong gia sản khổng lồ của Bào lớn, mọi chuyện rắc rối xảy ra khi Bào lớn bệnh và qua đời….</p>', 'Full', 1, 'series', 'completed', 18, 2007, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Hạ Vũ TVB","avatar":""},{"name":"Quan Cúc Anh","avatar":""},{"name":"Mễ Tuyết","avatar":""},{"name":"Lâm Phong","avatar":""},{"name":"Trần Hào","avatar":""},{"name":"Chung Gia Hân","avatar":""},{"name":"Lý Tư Kỳ","avatar":""},{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Mông Gia Tuệ","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324521);
