INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuop-nha-bang', 'Cướp Nhà Băng', 'The Lookout', 'https://phimimg.com/upload/vod/20231130-1/42a746a439118b40fa7f87710b6a932f.jpg', 'https://phimimg.com/upload/vod/20231130-1/48938360500ee41110a3a07c63a6c1da.jpg', '<p>Chris từng là một vận động viên trung học đầy triển vọng nhưng cuộc sống của anh bị đảo lộn sau một tai nạn thương tâm. Khi cố gắng duy trì một cuộc sống bình thường, anh ấy nhận công việc lao công tại một ngân hàng, nơi cuối cùng anh ấy thấy mình bị cuốn vào một vụ trộm đã được lên kế hoạch.</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Jeff Daniels","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Bruce McGill","avatar":""},{"name":"Alberta Watson","avatar":""},{"name":"Aaron Berg","avatar":""},{"name":"Morgan Kelly","avatar":""},{"name":"Greg Dunham","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Sergio Di Zio","avatar":""},{"name":"David Huband","avatar":""},{"name":"Tinsel Korey","avatar":""},{"name":"Suzanne Kelly","avatar":""},{"name":"Brian Edward Roach","avatar":""},{"name":"Martin Roach","avatar":""},{"name":"O","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324521);
