INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuop-nha-bang', 'Cướp Nhà Băng', 'The Lookout', 'cướp nhà băng the lookout joseph gordon-levitt jeff daniels matthew goode isla fisher carla gugino bruce mcgill alberta watson aaron berg morgan kelly greg dunham alex borstein sergio di zio david huband tinsel korey suzanne kelly brian edward roach martin roach o ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-quai-di-hoang', 'Tứ Quái Đi Hoang', 'Wild Hogs', 'https://phimimg.com/upload/vod/20231130-1/fd65c1fa08739c0b32dad367b02848a8.jpg', 'https://phimimg.com/upload/vod/20231130-1/901b8f8da89968c639d96eee55d9fe79.jpg', '<p>Kẻ đầu trò trong Tứ quái đi hoang - Woody Stevens - vốn là một luật sư danh tiếng, có cuộc sống mà nhiều người phải ghen tỵ. Nhưng người đàn ông giàu có này đã rơi từ đỉnh cao giấc mơ xuống đáy sâu ác mộng khi gia đình tan vỡ. Quá chua chát, anh rời bỏ thành thị ồn ào cùng Doug Madsen - một nha sĩ mải miết công việc, Bobby Davis - anh thợ sửa ống nước ôm mộng văn sĩ và Dudley Frank - một trai già độc thân. Diện chiếc áo da đen, cưỡi trên yên những chiếc Harley Davidson, họ những mong trút bỏ được cơn “khủng hoảng tuổi trung niên” đang hành hạ mình. Quá phấn khích với tự do trên con đường rộng mở, bốn tay lái môtô nghiệp dư không thể lường trước những chuyện có thể xảy đến với họ dọc đường đi. Những chuyện hài hước và hiểm nguy cũng từ đây mà ra. Họ bị một tay cảnh sát giao thông đồng tính bám đuổi, rồi đụng độ với hội Del Fuegos - những tay lái môtô giang hồ thứ thiệt. Tứ quái phải tìm cách tự bảo vệ mình và bạn bè trước mánh khóe của những kẻ lưu manh chuyên nghiệp. Liệu những anh chàng “giang hồ vặt” này có thể trở về an toàn...</p>', 'Full', 1, 'single', 'completed', 8, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tim Allen","avatar":""},{"name":"John Travolta","avatar":""},{"name":"Martin Lawrence","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"M.C. Gainey","avatar":""},{"name":"Jill Hennessy","avatar":""},{"name":"Dominic Janes","avatar":""},{"name":"Tichina Arnold","avatar":""},{"name":"Stephen Tobolowsky","avatar":""},{"name":"Jason Sklar","avatar":""},{"name":"Randy Sklar","avatar":""},{"name":"Drew Sidora","avatar":""},{"name":"Cymfenee","avatar":""},{"name":"Margaret Travolta","avatar":""},{"name":"Victor I","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324521);
