INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-duc-la-chuyen-nho-2', 'Tình Dục Là Chuyện Nhỏ 2', 'Sex is Zero 2', 'https://phimimg.com/upload/vod/20231130-1/0b52d6b42293731b3079489177fc7825.jpg', 'https://phimimg.com/upload/vod/20231130-1/4b8c684ca6979ee52b1808c9d304272d.jpg', '<p>Tiếp nối phần 1, phim Sex Is Zero 2 xoay quanh nhân vật Eun-Sik sau khi chia tay với người bạn gái trước. Lúc này, Eun-Sik bắt đầu tìm một khởi đầu mới với nhà vô địch bơi lội Kyung-Ah. Tuy nhiên, khi biết được Kyung-Ah từng bị cưỡng hiếp trong quá khứ, Eun-Sik đã vô cùng thất vọng. Qúa đau khổ, Kyeong-ah đành sang Mỹ với Gi-Joo - người luôn theo đuổi cô. Nhưng sau đó, Kyeong-ah nhận ra rằng người duy nhất cô yêu lại là Eun-sik chứ không phải ai khác….</p>', 'Full', 1, 'single', 'completed', 9, 2007, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Im Chang-jung","avatar":""},{"name":"Song Ji-hyo","avatar":""},{"name":"Choi Sung-kook","avatar":""},{"name":"Shin Yi","avatar":""},{"name":"Lee Sang-yun","avatar":""},{"name":"Yoo Chae-young","avatar":""},{"name":"Lee Hwa-sun","avatar":""},{"name":"Lee Si-yeon","avatar":""},{"name":"Sin Eunjeong","avatar":""},{"name":"Hong Ji-young","avatar":""},{"name":"Kim Myeong-Kyu","avatar":""},{"name":"Choi Hyun","avatar":""},{"name":"Park Young-soo","avatar":""},{"name":"Song Jae-ryong","avatar":""},{"name":"Park Seohyeon","avatar":""},{"name":"Park Jae-Woong","avatar":""},{"name":"Kim Tae-ho","avatar":""},{"name":"Lee Jong-rae","avatar":""},{"name":"Y","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324521);
