INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-si-choi-dan', 'Nghệ Sĩ Chơi Đàn', 'Once', 'https://phimimg.com/upload/vod/20231130-1/f244e306dd49e17cd5b8e2f8d7a509c9.jpg', 'https://phimimg.com/upload/vod/20231130-1/3203c2a40fac84de40419d59a536cbd8.jpg', '<p>Một người thợ sửa máy hút bụi ngoài giờ làm nhạc sĩ đường phố và hy vọng sẽ thành công lớn. Một ngày nọ, một người Séc nhập cư kiếm sống bằng nghề bán hoa, đến gặp anh và thông báo rằng cô cũng là một ca sĩ kiêm nhạc sĩ đầy tham vọng. Cặp đôi quyết định hợp tác và những bài hát mà họ sáng tác phản ánh câu chuyện về tình yêu đang chớm nở của họ.</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Glen Hansard","avatar":""},{"name":"Markéta Irglová","avatar":""},{"name":"Hugh Walsh","avatar":""},{"name":"Gerard Hendrick","avatar":""},{"name":"Alaistair Foley","avatar":""},{"name":"Geoff Minogue","avatar":""},{"name":"Bill Hodnett","avatar":""},{"name":"Danuse Ktrestova","avatar":""},{"name":"Darren Healy","avatar":""},{"name":"Mal Whyte","avatar":""},{"name":"Marcella Plunkett","avatar":""},{"name":"Niall Cleary","avatar":""},{"name":"Sean Miller","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324521);
