INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-phong-bi-an-1408', 'Căn Phòng Bí Ẩn 1408', '1408', 'https://phimimg.com/upload/vod/20231129-1/1583a35f908c28d20e20b56859b44881.jpg', 'https://phimimg.com/upload/vod/20231129-1/bace90cd53d5fde00988335d3df4c0f3.jpg', '<p>Mike Enslin là một nhà văn nổi tiếng chuyên viết truyện kinh dị, anh là người trước giờ chưa bao giờ biết sợ ma, mỗi khi nghe tin nơi đâu bị ma ám thì anh liền đến đó ngủ lại một đêm rồi viết bài về nơi đó. Hôm nọ, Enslin lục trong đống thư cũ và thấy một tờ giấy của một khách sạn tên Dolphin ở New York ghi là &quot;đừng vào phòng 1408&quot;, anh nghĩ rằng đó chỉ là lời quảng cáo tầm thường của những khách sạn vắng khách. Ngày hôm sau, Enslin đến thẳng New York, vào khách sạn Dolphin đăng ký ngủ một đêm trong phòng 1408, mặc dù người quản lý khách sạn là Gerald Olin nhiều lần ngăn cản anh bằng cách cho anh xem hình ảnh những nạn nhân trước kia thuê phòng 1408 bị chết thê thảm nhưng Enslin vẫn cương quyết ở lại căn phòng ma ám ấy...</p>', 'Full', 1, 'single', 'completed', 10, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cusack","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Mary McCormack","avatar":""},{"name":"Jasmine Jessica Anthony","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Alexandra Silber","avatar":""},{"name":"Noah Lee Margetts","avatar":""},{"name":"William Armstrong","avatar":""},{"name":"Paul Birchard","avatar":""},{"name":"Margot Leicester","avatar":""},{"name":"Angel Oquendo","avatar":""},{"name":"Walter Lewis","avatar":""},{"name":"Eric Meyers","avatar":""},{"name":"Holly Hayes","avatar":""},{"name":"Johann Urb","avatar":""},{"name":"Andrew-Lee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324521);
