INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('halloween', 'Halloween', 'Halloween', 'https://phimimg.com/upload/vod/20231130-1/93fc238f76144be7a5c31ee128e6fa5f.jpg', 'https://phimimg.com/upload/vod/20231130-1/90ee87329a7378833ec8ebe1b856034b.jpg', '<p>Sau khi bị cam kết trong 17 năm, Michael Myers, giờ đã trưởng thành và vẫn còn rất nguy hiểm, trốn thoát khỏi trại tâm thần (nơi anh ta bị cam kết khi mới 10 tuổi) và anh ta ngay lập tức quay trở lại Haddonfield, nơi anh ta muốn tìm em gái bé bỏng của mình. Laurie. Bất cứ ai băng qua con đường của anh ta đều gặp nguy hiểm chết người.</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scout Taylor-Compton","avatar":""},{"name":"Tyler Mane","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"Daeg Faerch","avatar":""},{"name":"Sheri Moon Zombie","avatar":""},{"name":"Danielle Harris","avatar":""},{"name":"Brad Dourif","avatar":""},{"name":"William Forsythe","avatar":""},{"name":"Kristina Klebe","avatar":""},{"name":"Leslie Easterbrook","avatar":""},{"name":"Hanna Hall","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Daryl Sabara","avatar":""},{"name":"Dee Wallace","avatar":""},{"name":"Skyler Gisondo","avatar":""},{"name":"Ken Foree","avatar":""},{"name":"Lew Temp","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324521);
