INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-om-shanti', 'Chuyện Tình Om Shanti', 'Om Shanti Om', 'https://phimimg.com/upload/vod/20231130-1/4b912a94900e5e7c4b299ff1e23b2172.jpg', 'https://phimimg.com/upload/vod/20231130-1/9495a83c1a560e615ec4ad4c48355a08.jpg', '<p>Trong những năm 70, Om (Shah khan ), là 1 diễn viên đầy tham vọng đã bị giết hại. Nhưng ngay lập tức, Om đã được hồi sinh ở kiếp sau. Anh đã cố gắng đi tìm để khám phá ra tại sao mình lại bị giết và đi tìm Shanti, người con gái mà anh yêu...</p>', 'Full', 1, 'single', 'completed', 10, 2007, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Shah Rukh Khan","avatar":""},{"name":"Deepika Padukone","avatar":""},{"name":"Arjun Rampal","avatar":""},{"name":"Shreyas Talpade","avatar":""},{"name":"Kirron Kher","avatar":""},{"name":"Nitesh Pandey","avatar":""},{"name":"Shawar Ali","avatar":""},{"name":"Yuvika Chaudhary","avatar":""},{"name":"Satish Shah","avatar":""},{"name":"Juhi Chawla Mehta","avatar":""},{"name":"Javed Sheikh","avatar":""},{"name":"Masood Akhtar","avatar":""},{"name":"Hrithik Roshan","avatar":""},{"name":"Preity Zinta","avatar":""},{"name":"Vishal Dadlani","avatar":""},{"name":"Abhishek Bachchan","avatar":""},{"name":"Rishi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
