INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-tuyet', 'Thiên Thần Tuyết', 'Snow Angels', 'https://phimimg.com/upload/vod/20231130-1/d70facc97db7203ee3e3384b6f213f47.jpg', 'https://phimimg.com/upload/vod/20231130-1/75b2105a5a69a094faf35304ba9abd3e.jpg', '<p>Cô hầu bàn Annie đã ly thân với người chồng nghiện rượu đang tự tử của mình, Glenn. Glenn đã trở thành một Cơ đốc nhân theo đạo Tin lành, nhưng những nỗ lực thất thường của anh ấy trong việc quay lại cuộc sống của Annie đã khiến cô ấy cảnh giác. Học sinh trung học Arthur làm việc tại nhà hàng của Annie, ngày càng thân thiết với một đứa trẻ mới trong thị trấn, Lila, sau giờ học. Khi con gái của Glenn và Annie mất tích, cả thị trấn tìm kiếm cô, trong khi anh ngày càng mất kiểm soát.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Beckinsale","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Michael Angarano","avatar":""},{"name":"Jeannetta Arnette","avatar":""},{"name":"Griffin Dunne","avatar":""},{"name":"Nicky Katt","avatar":""},{"name":"Tom Noonan","avatar":""},{"name":"Connor Paolo","avatar":""},{"name":"Amy Sedaris","avatar":""},{"name":"Olivia Thirlby","avatar":""},{"name":"Gracie Hudson","avatar":""},{"name":"Brian Downey","avatar":""},{"name":"Carroll Godsman","avatar":""},{"name":"Daniel Lillford","avatar":""},{"name":"Deborah Allen","avatar":""},{"name":"Slavko Negulic","avatar":""},{"name":"Leah Ostry","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324521);
