INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('in-the-land-of-women', 'In the Land of Women', 'In the Land of Women', 'https://phimimg.com/upload/vod/20231129-1/ffe2506f54126bfb8c668ebb75af2868.jpg', 'https://phimimg.com/upload/vod/20231129-1/4e43cf2d811c62a0867294fff17f9f47.jpg', '<p>Sau cuộc chia tay tồi tệ với bạn gái khiến anh đau lòng, Carter Webb chuyển đến Michigan để chăm sóc người bà ốm yếu của mình. Khi đến đó, anh bị lẫn vào cuộc sống của hai mẹ con sống bên kia đường.</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Meg Ryan","avatar":""},{"name":"Kristen Stewart","avatar":""},{"name":"Adam Brody","avatar":""},{"name":"JoBeth Williams","avatar":""},{"name":"Olympia Dukakis","avatar":""},{"name":"Makenzie Vega","avatar":""},{"name":"Elena Anaya","avatar":""},{"name":"Kelsey Keel","avatar":""},{"name":"Danielle Savre","avatar":""},{"name":"Gia Mantegna","avatar":""},{"name":"Rob Reinis","avatar":""},{"name":"Dustin Milligan","avatar":""},{"name":"Graham Wardle","avatar":""},{"name":"Elise Gatien","avatar":""},{"name":"Beau Mirchoff","avatar":""},{"name":"Clark Gregg","avatar":""},{"name":"Ilyse Mimoun","avatar":""},{"name":"Ginnifer Go","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
