INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('30-ngay-den-toi', '30 Ngày Đen Tối', '30 Days of Night', 'https://phimimg.com/upload/vod/20231127-1/ededa66143003f7e6097d969da941ce8.jpg', 'https://phimimg.com/upload/vod/20231127-1/f68727a3f82e0b9ae0b93cb0cacfef56.jpg', '<p>Vì nằm tận nơi cực Bắc, mùa đông ở Barrow có hẳn 30 ngày thị trấn hoàn toàn chìm trong bóng tối. Ngay khi ánh nắng cuối cùng tắt hẳn ở Barrow thì thị trấn cũng xảy ra hàng loạt các vụ án bí ẩn như: điện thoại cầm tay bị lấy trộm và bị đốt, đàn chó bị kẻ lạ mặt giết một cách khó hiểu, trạm điện bị cắt, những phương tiện có thể liên lạc với thế giới bên ngoài đều bị cắt đứt…Những hiện tượng này báo hiệu cho một cuộc đổ bộ của nhóm ma cà rồng lên thị trấn. Và một người lạ mặt xuất hiện gây ẩu đả trong quán bar, liệu đó có phải là một điềm báo?</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Hartnett","avatar":""},{"name":"Melissa George","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Mark Boone Junior","avatar":""},{"name":"Mark Rendall","avatar":""},{"name":"Amber Sainsbury","avatar":""},{"name":"Manu Bennett","avatar":""},{"name":"Megan Franich","avatar":""},{"name":"Craig Hall","avatar":""},{"name":"Chic Littlewood","avatar":""},{"name":"Nathaniel Lees","avatar":""},{"name":"Elizabeth Hawthorne","avatar":""},{"name":"Joel Tobeck","avatar":""},{"name":"Kate Elliott","avatar":""},{"name":"Camille Keenan","avatar":""},{"name":"Peter Feen","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324521);
