INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-duoc-bao-truoc-2007', 'Cái Chết Được Báo Trước', 'Before the Devil Knows You''re Dead', 'https://phimimg.com/upload/vod/20231129-1/71dadd5af1dd9701b93688b9c8ec2554.jpg', 'https://phimimg.com/upload/vod/20231129-1/56776410e65c10ee460397dc210d55d3.jpg', '<p>Before The Devil Knows You&quot;re Dead là bộ phim tâm lý kể về một bi kịch của một gia đình nọ, khi niềm tin vào những người thân thương nhất bị phản bội. Tại New York, Andy là một tay môi giới ranh ma, nhưng hắn ta lại đang lâm vào tình huống rỗng túi. Cùng đường, Andy qua sang dụ dỗ cậu em trai Hank thực hiện vụ cướp tại một cửa hiệu kim hoàn ngoài ngoại ô – nơi mà Andy cho là dễ ra tay nhất. Trớ trêu thay, người chủ của cửa hiệu kim hoàn nọ chính là bố mẹ ruột của 2 anh em. Thế rồi, khi kế hoạch tưởng như hoàn hảo của họ thất bại và để lại hậu quả khôn lường, cả hai phải đối đầu với sự truy tìm của cảnh sát và cả ông bố khó tính của mình…</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Albert Finney","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Aleksa Palladino","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Amy Ryan","avatar":""},{"name":"Sarah Livingston","avatar":""},{"name":"Brían F. O''Byrne","avatar":""},{"name":"Rosemary Harris","avatar":""},{"name":"Blaine Horton","avatar":""},{"name":"Arija Bareikis","avatar":""},{"name":"Leonardo Cimino","avatar":""},{"name":"Lee Wilkof","avatar":""},{"name":"Damon Gupton","avatar":""},{"name":"Myra Lucreti","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324521);
