INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('superman-doomsday', 'Superman: Doomsday', 'Superman: Doomsday', 'https://phimimg.com/upload/vod/20231129-1/9d4fa55c4d7b7a5fe66b5247bc6feb06.jpg', 'https://phimimg.com/upload/vod/20231129-1/78f0ba849fb3f2eccacfaa9246ba9655.jpg', '<p>Khi LexCorp vô tình giải phóng một sinh vật giết người, Superman gặp thử thách lớn nhất với tư cách là nhà vô địch. Dựa trên cốt truyện &quot;Cái chết của siêu nhân&quot; xuất hiện trong các ấn phẩm của DC Comics vào những năm 1990.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Baldwin","avatar":""},{"name":"Anne Heche","avatar":""},{"name":"James Marsters","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Swoosie Kurtz","avatar":""},{"name":"Tom Kenny","avatar":""},{"name":"Ray Wise","avatar":""},{"name":"Cree Summer","avatar":""},{"name":"Adam Wylie","avatar":""},{"name":"Chris Cox","avatar":""},{"name":"Hettie Lynne Hurtes","avatar":""},{"name":"James Arnold Taylor","avatar":""},{"name":"Townsend Coleman","avatar":""},{"name":"Kimberly Brooks","avatar":""},{"name":"Kevin Smith","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324521);
