INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-no', 'Ngòi Nổ', 'Flash Point', 'https://phimimg.com/upload/vod/20231129-1/c58f3aea85dc99345ea4b8ca7326a3df.jpg', 'https://phimimg.com/upload/vod/20231129-1/4231bed2fc055c9a307d2164fb9395df.jpg', '<p>Một người đàn ông lái chiếc xe lao nhanh trên đường. Đó là Mã Quân (Chung Tử Đơn), thành viên của đội trọng án Hong Kong. Cũng giống chiếc xe thể thao anh điều khiển, Mã Quân thường hành động nhanh như chớp, chính xác nhưng nhiều khi khá thô bạo. Không ít lần anh bị kỷ luật vì đánh tội phạm thừa sống thiếu chết. Mã Quân ghét cay ghét đắng những kẻ sống ngoài lề pháp luật, trong đó đặc biệt có ba anh em nhà Vỹ Tra (Lữ Lương Vỹ), tên thủ lĩnh hung hăng, Tonny (Trâu Triệu Long), thằng anh hai lạnh lùng tàn bạo và A Hổ, thằng em út chỉ biết dùng sức mạnh của nắm đấm. Ranh ma, tàn ác nhưng biết đoàn kết, chúng là một tổ chức tội phạm có uy thế tại Hong Kong và là cái gai trong mắt đội trọng án.</p>', 'Full', 1, 'single', 'completed', 11, 2007, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Collin Chou","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Xing Yu","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Xu Qing","avatar":""},{"name":"Teresa Ha Ping","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Tony Ho","avatar":""},{"name":"Irene Wong","avatar":""},{"name":"Timmy Hung","avatar":""},{"name":"Aaron Leung","avatar":""},{"name":"Ben Lam","avatar":""},{"name":"Austin Wai Tin-Chi","avatar":""},{"name":"Ai Wai","avatar":""},{"name":"Wong Chi-Wai","avatar":""},{"name":"Kenji Tanigaki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324521);
