INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-do-mau-va-sat', 'Quỷ Đỏ: Máu và Sắt', 'Hellboy Animated: Blood and Iron', 'https://phimimg.com/upload/vod/20231125-1/0a86756ec4b1de5154dc71effb647476.jpg', 'https://phimimg.com/upload/vod/20231125-1/c1cfb20612794e90c1456f9c954d2449.jpg', '<p>Khi Hellboy, Liz Sherman và Abe Sapien được giao nhiệm vụ điều tra dinh thự bị ma ám của một tỷ phú săn đón công chúng, họ khám phá ra âm mưu hồi sinh một ma cà rồng xinh đẹp nhưng quái dị trong quá khứ của Giáo sư Bruttenholm. Nhưng trước khi họ có thể ngăn chặn cuộc tắm máu của cô ấy, Hellboy sẽ phải chiến đấu với đàn hạc, chó săn địa ngục, một người sói khổng lồ và thậm chí cả nữ thần hung dữ Hecate.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ron Perlman","avatar":""},{"name":"Selma Blair","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Doug Jones","avatar":""},{"name":"Peri Gilpin","avatar":""},{"name":"J. Grant Albrecht","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Grey DeLisle","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Kath Soucie","avatar":""},{"name":"DeeDee Rescher","avatar":""},{"name":"Cree Summer","avatar":""},{"name":"James Arnold Taylor","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f0