INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-khong-gian-khong-don-doc', 'Đặc Vụ Không Gian: Không Đơn Độc', 'Evangelion: 1.0 You Are (Not) Alone', 'https://phimimg.com/upload/vod/20231125-1/7dfc6aa581697936f415b3eb34cc7fb8.jpg', 'https://phimimg.com/upload/vod/20231125-1/b0bccd3c9952381a7d6f53eb213ef9ce.jpg', '<p>Bộ phim xoay quanh cuộc chiến chống lại sự xâm lược của sinh vật khổng lồ &quot;Angel&quot;. Chuyện bắt đầu vào năm 2015, khi thế giới đã bị phá hủy bởi một sinh vật gọi là Adam, lúc này Ikari Shinji đến một thành phố và đã gặp một Angel đang phá hủy nó. Shinji đã được một cô gái trong tổ chức đưa xuống nơi đang chế tạo một robot có tên &quot;Eva&quot; để chiến đấu chống lại Angel...</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Megumi Ogata","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Motomu Kiyokawa","avatar":""},{"name":"Miki Nagasawa","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Hiro Yuuki","avatar":""},{"name":"Tetsuya Iwanaga","avatar":""},{"name":"Junko Iwao","avatar":""},{"name":"Mugihito","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
