INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dac-vu-khong-gian-khong-don-doc', 'Đặc Vụ Không Gian: Không Đơn Độc', 'Evangelion: 1.0 You Are (Not) Alone', 'đặc vụ không gian: không đơn độc evangelion: 1.0 you are (not) alone megumi ogata megumi hayashibara kotono mitsuishi yuriko yamaguchi akira ishida fumihiko tachiki motomu kiyokawa miki nagasawa takehito koyasu tomokazu seki hiro yuuki tetsuya iwanaga junko iwao mugihito ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shelter', 'Shelter', 'Shelter', 'https://phimimg.com/upload/vod/20231125-1/ab3e01d90e6d09ca273e16f7136fd159.jpg', 'https://phimimg.com/upload/vod/20231125-1/12f6065f696e4f36295ee2290c5a7340.jpg', '<p>Buộc phải từ bỏ ước mơ vào trường nghệ thuật, Zach làm những công việc bế tắc để nuôi em gái và con trai của cô ấy. Đặt câu hỏi về cuộc sống của mình, anh ấy vẽ tranh, lướt sóng và đi chơi với người bạn thân nhất của mình, Gabe. Khi anh trai của Gabe trở về nhà vào mùa hè, Zach đột nhiên thấy mình bị cuốn vào một mối quan hệ mà anh không ngờ tới.</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Rowe","avatar":""},{"name":"Trevor Wright","avatar":""},{"name":"Tricia Pierce","avatar":""},{"name":"Tina Holmes","avatar":""},{"name":"Jackson Wurth","avatar":""},{"name":"Katie Walder","avatar":""},{"name":"Matt Bushell","avatar":""},{"name":"Ross Thomas","avatar":""},{"name":"Albert Reed","avatar":""},{"name":"Joy Gohring","avatar":""},{"name":"Don Margolin","avatar":""},{"name":"Alejandro Patiño","avatar":""},{"name":"Caitlin Crosby","avatar":""},{"name":"Alicia Sixtos","avatar":""},{"name":"Tarek Zohdy","avatar":""},{"name":"Robbi Chong","avatar":""},{"name":"Dominic Figlio","avatar":""},{"name":"Christina Blev","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324521);
