INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-sat-vo-dich', 'Người Sắt Vô Địch', 'The Invincible Iron Man', 'https://phimimg.com/upload/vod/20231125-1/d3fd823383a8086297670eaf7d697334.jpg', 'https://phimimg.com/upload/vod/20231125-1/2c7ca58ad0084d16c86633a691ea5c14.jpg', '<p>The Invincible Iron Man là bộ phim hoạt hình về Người Sắt. Lần này, để đương đầu với sức mạnh hủy diệt trong trận chiến một sống một chết, Tony đã tạo ra chiếc áo giáp được hỗ trợ bởi các vũ khí công nghệ cao. Vì ẩn mình trong bộ áo giáp nên anh được gọi là Người Sắt &quot;Iron Man&quot;. Cuộc chiến đấu bắt đầu bốn chiến binh đầy phép thuật, những người biết tận dụng sức mạnh từ các yếu tố trên trái đất như nước, gió và lửa.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marc Worden","avatar":""},{"name":"Gwendoline Yeo","avatar":""},{"name":"John McCook","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Elisa Gabrielli","avatar":""},{"name":"Rodney Saulsberry","avatar":""},{"name":"James Sie","avatar":""},{"name":"Stephen Mendillo","avatar":""},{"name":"John DeMita","avatar":""},{"name":"George Cheung","avatar":""},{"name":"Chris Edgerly","avatar":""},{"name":"Paul Nakauchi","avatar":""},{"name":"Michael Yama","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324521