INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-nguoi-my', 'Tội Ác Người Mỹ', 'An American Crime', 'https://phimimg.com/upload/vod/20231124-1/496f5ab36309f73591b94f16fa1e6bd5.jpg', 'https://phimimg.com/upload/vod/20231124-1/847d811eac49af69ee617d81b03f44f0.jpg', '<p>Dựa trên một câu chuyện có thật gây chấn động quốc gia năm 1965, phim kể về câu chuyện thương tâm về 2 cô gái trẻ Sylvia và Jennie đã bị một người phụ nữ tên Gertrude hành hạ và đánh đập.</p>', 'Full', 1, 'single', 'completed', 10, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elliot Page","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Hayley McFarland","avatar":""},{"name":"Nick Searcy","avatar":""},{"name":"Romy Rosemont","avatar":""},{"name":"Ari Graynor","avatar":""},{"name":"Scout Taylor-Compton","avatar":""},{"name":"Tristan Jarred","avatar":""},{"name":"Hannah Leigh","avatar":""},{"name":"Bradley Whitford","avatar":""},{"name":"James Franco","avatar":""},{"name":"Scott Eastwood","avatar":""},{"name":"Michael O''Keefe","avatar":""},{"name":"Carlie Westerman","avatar":""},{"name":"Michelle Benes","avatar":""},{"name":"Jeremy Su","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324521);
