INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-assassination-of-jesse-james-by-the-coward-robert-ford', 'The Assassination of Jesse James by the Coward Robert Ford', 'The Assassination of Jesse James by the Coward Robert Ford', 'https://phimimg.com/upload/vod/20231124-1/4330c90d4d2f880b735ee3cd52310223.jpg', 'https://phimimg.com/upload/vod/20231124-1/c271f7dbc491e6f92d995081524c8273.jpg', '<p>Kẻ ngoài vòng pháp luật Jesse James được đồn đại là &#39;tay súng nhanh nhất phương Tây&#39;. Là một người háo hức được tuyển vào băng đảng khét tiếng của James, Robert Ford cuối cùng trở nên ghen tị với kẻ ngoài vòng pháp luật nổi tiếng và khi Robert và anh trai cảm nhận được cơ hội để giết James, hành động giết người của họ đã nâng mục tiêu của họ lên gần địa vị thần thoại.</p>', 'Full', 1, 'single', 'completed', 20, 2007, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Casey Affleck","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Paul Schneider","avatar":""},{"name":"Jeremy Renner","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Sam Shepard","avatar":""},{"name":"Mary-Louise Parker","avatar":""},{"name":"Zooey Deschanel","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"Michael Parks","avatar":""},{"name":"Alison Elliott","avatar":""},{"name":"James Carville","avatar":""},{"name":"Tom Aldredge","avatar":""},{"name":"Hugh Ross","avatar":""},{"name":"Brooklynn Proulx","avatar":""},{"name":"Dustin Bolling","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324521);
