INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-assassination-of-jesse-james-by-the-coward-robert-ford', 'The Assassination of Jesse James by the Coward Robert Ford', 'The Assassination of Jesse James by the Coward Robert Ford', 'the assassination of jesse james by the coward robert ford the assassination of jesse james by the coward robert ford casey affleck brad pitt sam rockwell paul schneider jeremy renner garret dillahunt sam shepard mary-louise parker zooey deschanel ted levine michael parks alison elliott james carville tom aldredge hugh ross brooklynn proulx dustin bolling ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuc-chang-may-man', 'Chúc Chàng May Mắn', 'Good Luck Chuck', 'https://phimimg.com/upload/vod/20231124-1/951f8084054521bdbb5cd5bed77e18e4.jpg', 'https://phimimg.com/upload/vod/20231124-1/45e857afc88c08de66cfa2268d1fba80.jpg', '<p>Phim xoay quanh chuyện tình duyên lận đận của anh chàng vừa may mắn lại vừa không may Charlie Logan (Dane Cook) – thường được gọi là Chuck, chịu một lời nguyền là khi anh ngủ với bất cứ một cô gái nào thì ngay sau đó cô ấy rời bỏ anh và tìm thấy người đàn ông đích thực của đời mình. Ai cũng mong có một đêm với anh để sau đó mau chóng tìm được chồng như ý. Tận dụng “danh tiếng” này, Charlie tha hồ phiêu lưu. Một ngày, trong một đám cưới, anh gặp Cam (Jessica Alba) – cô gái yêu chim cánh cụt đến phát cuồng. Dù cô nàng hậu đậu đụng đâu vỡ đấy, đi đứng cũng tự gây tai nạn nhưng lại quyến rũ chết người. Tìm thấy tình yêu, Charlie không muốn Cam rời bỏ anh như bao phụ nữ khác để kết hôn với ai. Vậy là bắt đầu chuỗi dở ...</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Dane Cook","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Ellia English","avatar":""},{"name":"Lonny Ross","avatar":""},{"name":"Troy Gentile","avatar":""},{"name":"Chelan Simmons","avatar":""},{"name":"Mackenzie Mowat","avatar":""},{"name":"Sasha Pieterse","avatar":""},{"name":"Caroline Ford","avatar":""},{"name":"Chiara Zanni","avatar":""},{"name":"Benjamin Ayres","avatar":""},{"name":"Carrie Fleming","avatar":""},{"name":"Yan-Kay Crystal Lowe","avatar":""},{"name":"Tava Smiley","avatar":""},{"name":"Annie Wood","avatar":""},{"name":"Kari-Ann Wood","avatar":""},{"name":"Victo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324521);
