INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-trai-cung-bo', 'Cắm Trại Cùng Bố', 'Daddy Day Camp', 'https://phimimg.com/upload/vod/20231124-1/e2106cf6b0be476a9612bc14f67a5d8c.jpg', 'https://phimimg.com/upload/vod/20231124-1/037e7a385d61b28ce8f17377667fa785.jpg', '<p>Trong phần tiếp theo của &quot;Daddy Day Care&quot;, hai ông bố vụng về Charlie và Phil phải đương đầu với những tòa nhà xập xệ và học sinh ngỗ ngược khi họ tiếp quản một trại hè.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Tamala Jones","avatar":""},{"name":"Paul Rae","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Richard Gant","avatar":""},{"name":"Talon G. Ackerman","avatar":""},{"name":"Joshua David McLerran","avatar":""},{"name":"Brian Doyle-Murray","avatar":""},{"name":"Spencir Bridges","avatar":""},{"name":"Dallin Boyce","avatar":""},{"name":"Telise Galanis","avatar":""},{"name":"Taggart Hurtubise","avatar":""},{"name":"Molly Jepson","avatar":""},{"name":"Tad D''Agostino","avatar":""},{"name":"Tyger Rawlings","avatar":""},{"name":"Zacha","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324521);
