INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rl-stine-gio-ma-am-dung-nghi-ve-no', 'R.L. Stine - Giờ ma ám: Đừng nghĩ về nó', 'R.L. Stine''s The Haunting Hour: Don''t Think About It', 'https://phimimg.com/upload/vod/20231124-1/f12ed66855d60bee14d238d92f4b3561.jpg', 'https://phimimg.com/upload/vod/20231124-1/6bda763338e2c10298ab0e02324bd386.jpg', '<p>Một thiếu nữ thích đùa, khó hòa đồng tìm thấy một cuốn sách bí ẩn tại cửa hàng bán đồ Halloween và vô tình thả con quái vật hai đầu trong đó ra.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emily Osment","avatar":""},{"name":"Brittany Curran","avatar":""},{"name":"Alex Winzenread","avatar":""},{"name":"Michelle Duffy","avatar":""},{"name":"John Hawkinson","avatar":""},{"name":"Cody Linley","avatar":""},{"name":"Tobin Bell","avatar":""},{"name":"John P. Hopkins","avatar":""},{"name":"Michael Dickson","avatar":""},{"name":"Colleen Dengel","avatar":""},{"name":"Katelyn Pippy","avatar":""},{"name":"Marty Schiff","avatar":""},{"name":"Barbara Russell","avatar":""},{"name":"Maria Becoates-Bey","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324521);
