INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('rl-stine-gio-ma-am-dung-nghi-ve-no', 'R.L. Stine - Giờ ma ám: Đừng nghĩ về nó', 'R.L. Stine''s The Haunting Hour: Don''t Think About It', 'r.l. stine - giờ ma ám: đừng nghĩ về nó r.l. stine''s the haunting hour: don''t think about it emily osment brittany curran alex winzenread michelle duffy john hawkinson cody linley tobin bell john p. hopkins michael dickson colleen dengel katelyn pippy marty schiff barbara russell maria becoates-bey ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khuc-vinh-quang', 'Vũ Khúc Vinh Quang', 'Blades of Glory', 'https://phimimg.com/upload/vod/20231121-1/edae1cb83f333ce922f36779446bc898.jpg', 'https://phimimg.com/upload/vod/20231121-1/060ae6bd91f6cbc07cc9ad22c5ff573c.jpg', '<p>Cách đây 3 năm rưỡi, họ,Chazz Michael Michaels (Will Ferrell) và Jimmy MacElroy (Jon Heder), từng là đôi nam trượt băng nghệ thuật nổi tiếng nhất, chiếc huy chường vàng giải Vô địch Thế Giới gần như trong tầm tay họ nhưng rồi chỉ vì một mâu thuẫn nhỏ nhoi đã khiến mọi thứ vuột ra khỏi tầm tay, ẩu đả tại giải khiến họ bị ban tổ chức cấm thi đấu vô thời hạn. Nay, một cơ hội vàng đã đến, họ lại có thể cùng nhau kết hợp giành lại những vinh quang trên sân băng khi lệnh cấm thi đấu của họ được bãi bỏ và việc đầu tiên là họ phải cùng dẹp bỏ thói tị nạnh với nhau...</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Ferrell","avatar":""},{"name":"Jon Heder","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Amy Poehler","avatar":""},{"name":"Jenna Fischer","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Craig T. Nelson","avatar":""},{"name":"Romany Malco","avatar":""},{"name":"Nick Swardson","avatar":""},{"name":"Scott Hamilton","avatar":""},{"name":"Andy Richter","avatar":""},{"name":"Greg Lindsay","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Nick Jameson","avatar":""},{"name":"Tom Virtue","avatar":""},{"name":"Ben Wilson","avatar":""},{"name":"William Daniels","avatar":""},{"name":"Zachary Ferre","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324521);
