INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('88-minutes', '88 Minutes', '88 Minutes', 'https://phimimg.com/upload/vod/20231123-1/a0f6954094f9f2a3770a8e385e986781.jpg', 'https://phimimg.com/upload/vod/20231123-1/a13800181856e09b33eb174f3a47d18d.jpg', '<p>Một giáo sư đại học, người ngoài giờ làm bác sĩ tâm thần pháp y cho FBI, nhận được một lời đe dọa tử vong tuyên bố rằng anh ta chỉ còn 88 phút để sống.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Al Pacino","avatar":""},{"name":"Alicia Witt","avatar":""},{"name":"Leelee Sobieski","avatar":""},{"name":"Amy Brenneman","avatar":""},{"name":"William Forsythe","avatar":""},{"name":"Deborah Kara Unger","avatar":""},{"name":"Ben McKenzie","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Leah Cairns","avatar":""},{"name":"Stephen Moyer","avatar":""},{"name":"Christopher Redman","avatar":""},{"name":"Brendan Fletcher","avatar":""},{"name":"Paul Campbell","avatar":""},{"name":"Tim Perez","avatar":""},{"name":"Bob Stephenson","avatar":""},{"name":"Mike Dopud","avatar":""},{"name":"Philip Moon","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324521);
