INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-dac-biet', 'Cậu Bé Đặc Biệt', 'Taare Zameen Par', 'https://phimimg.com/upload/vod/20231120-1/48b4c4e0b3a1d6bba030ce250702462d.jpg', 'https://phimimg.com/upload/vod/20231120-1/74746f6bdcf3dd6b3798f5d99a59c4e3.jpg', '<p>Bộ phim khám phá cuộc sống và trí tưởng tượng của cậu bé 8 tuổi Ishaan Awasthy. Trong khi vượt trội hơn hẳn về mặt nghệ thuật thì chính sự yếu kém về thành tích học tập đã làm ba mẹ Ishaan gửi cậu bé vào trường nội trú. Giáo viên dạy nghệ thuật mới của Ishaan cho rằng cậu bé bị mắc chứng khó đọc và ra sức cố gắng để giúp cậu bé vượt qua khuyết tật này. Taare Zameen Par là bộ phim về trẻ em và đề cập đến những khả năng của trẻ nhỏ. Chính tiêu đề đã thể hiện rất rõ nội dung phim. Tất cả những đứa trẻ đều đặc biệt và hết sức tuyệt vời!</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Darsheel Safary","avatar":""},{"name":"Aamir Khan","avatar":""},{"name":"Tisca Chopra","avatar":""},{"name":"Vipin Sharma","avatar":""},{"name":"Tanay Chheda","avatar":""},{"name":"Sachet Engineer","avatar":""},{"name":"Girija Oak","avatar":""},{"name":"Bugs Bhargava","avatar":""},{"name":"Shankar Sachdev","avatar":""},{"name":"Lalita Lajmi","avatar":""},{"name":"Ravi Khanvilkar","avatar":""},{"name":"Meghna Malik","avatar":""},{"name":"M. K. Raina","avatar":""},{"name":"Ayaan","avatar":""},{"name":"Veer Mohan","avatar":""},{"name":"Aniket Engineer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
