INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-sinh-sieu-quay', 'Nữ Sinh Siêu Quậy', 'St. Trinian''s', 'https://phimimg.com/upload/vod/20231201-1/652a9eefa5f1db84af3d938e642032b0.jpg', 'https://phimimg.com/upload/vod/20231201-1/921b44127454e939868e352d1d785db3.jpg', '<p>Khi ngôi trường thân yêu của họ bị đe dọa đóng cửa nếu các thế lực không huy động được quỹ thích hợp, các cô gái lên kế hoạch đánh cắp một bức tranh vô giá và sử dụng lợi nhuận để kéo St. Trinian&#39;s ra khỏi màu đỏ.</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Talulah Riley","avatar":""},{"name":"Rupert Everett","avatar":""},{"name":"Gemma Arterton","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Jodie Whittaker","avatar":""},{"name":"Russell Brand","avatar":""},{"name":"Anna Chancellor","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Tamsin Egerton","avatar":""},{"name":"Antonia Bernath","avatar":""},{"name":"Amara Karan","avatar":""},{"name":"Paloma Faith","avatar":""},{"name":"Kathryn Drysdale","avatar":""},{"name":"Lily Cole","avatar":""},{"name":"Holly Mackie","avatar":""},{"name":"Cloe Mackie","avatar":""},{"name":"Lucy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324521);
