INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shadows-in-the-palace', 'Shadows in the Palace', 'Shadows in the Palace', 'https://phimimg.com/upload/vod/20231119-1/1950672ee847a827b62ccbad6ab2e8bb.jpg', 'https://phimimg.com/upload/vod/20231119-1/9123b48b3982dacfab57f0e714dd7873.jpg', '<p>Trong thời kỳ Chosun, một người phụ nữ triều đình được tìm thấy đã chết, bị treo bởi những chiếc bè của cung điện. Sau khi kiểm tra xác chết, nơi các bác sĩ Chun-Ryung phát hiện ra rằng người giúp việc chết có lẽ đã bị sát hại và thực hiện điều tra ngay cả khi cao hơn áp lực của cô để khiến cô phải đóng trường hợp tự tử.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Jin-hee","avatar":""},{"name":"Yoon Se-a","avatar":""},{"name":"Seo Young-hee","avatar":""},{"name":"Im Jung-eun","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Kim Sung-ryung","avatar":""},{"name":"Kim Nam-jin","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Nam Jeong-hee","avatar":""},{"name":"Kim Hak-sun","avatar":""},{"name":"Lee Young-hee","avatar":""},{"name":"Go Seo-hee","avatar":""},{"name":"Chu Kwi-jung","avatar":""},{"name":"Moon Ga-young","avatar":""},{"name":"Ye Su-jeong","avatar":""},{"name":"Son Young-soon","avatar":""},{"name":"Seo Ri-seul","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324521);
