INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-lam-bo', 'Kế Hoạch Làm Bố', 'The Game Plan', 'https://phimimg.com/upload/vod/20231119-1/5a0a856993ec41e3f4876107ce09d1c7.jpg', 'https://phimimg.com/upload/vod/20231119-1/f31c15dc9c0380ab71acfa3f00911dc0.jpg', '<p>Ngôi sao bóng đá cử nhân Joe Kingman dường như có tất cả. Anh ấy giàu có và vô tư, và đội của anh ấy đang trên đường giành chức vô địch. Đột nhiên, anh nhận được một số tin tức bất ngờ: Anh có một cô con gái nhỏ, kết quả của cuộc tình lần cuối với vợ cũ. Joe phải học cách cân bằng cuộc sống cá nhân và nghề nghiệp của mình với nhu cầu của con mình.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Madison Pettis","avatar":""},{"name":"Kyra Sedgwick","avatar":""},{"name":"Roselyn Sánchez","avatar":""},{"name":"Morris Chestnut","avatar":""},{"name":"Hayes MacArthur","avatar":""},{"name":"Brian J. White","avatar":""},{"name":"Jamal Duff","avatar":""},{"name":"Paige Turco","avatar":""},{"name":"Gordon Clapp","avatar":""},{"name":"Kate Nauta","avatar":""},{"name":"Robert Torti","avatar":""},{"name":"Jackie Flynn","avatar":""},{"name":"Lauren Storm","avatar":""},{"name":"Tubbs","avatar":""},{"name":"Marv Albert","avatar":""},{"name":"Boomer Esiason","avatar":""},{"name":"Jim Gray","avatar":""},{"name":"St","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324521);
