INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khi-sinh-hoc', 'Vũ Khí Sinh Học', 'The Invasion', 'https://phimimg.com/upload/vod/20231117-1/f36aedb1359e3bc390e7a7e7b9484c85.jpg', 'https://phimimg.com/upload/vod/20231117-1/170e730f7deb48045501bbb40fdbb27c.jpg', '<p>Nhà tâm lý học Carol Bennell của Washington, D.C. và đồng nghiệp của cô, Tiến sĩ Ben Driscoll là hai người duy nhất trên Trái đất biết về một dịch bệnh đang hoành hành khắp thành phố. Họ phát hiện ra một loại virus ngoài hành tinh trên một con tàu con thoi bị rơi có thể biến bất kỳ ai tiếp xúc với nó thành những chiếc máy bay không người lái khi họ đang ngủ. Carol nhận ra con trai mình đang nắm giữ chìa khóa để ngăn chặn sự lây lan của bệnh dịch hạch và cô chạy đua đi tìm con trai mình trước khi quá muộn.</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Daniel Craig","avatar":""},{"name":"Jeremy Northam","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Jackson Bond","avatar":""},{"name":"Veronica Cartwright","avatar":""},{"name":"Josef Sommer","avatar":""},{"name":"Celia Weston","avatar":""},{"name":"Malin Åkerman","avatar":""},{"name":"Roger Rees","avatar":""},{"name":"Eric Benjamin","avatar":""},{"name":"Susan Floyd","avatar":""},{"name":"Stephanie Berry","avatar":""},{"name":"Alexis Raben","avatar":""},{"name":"Adam LeFevre","avatar":""},{"name":"Joanna Merlin","avatar":""},{"name":"Michael Stone Fo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd7