INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-lai-cuoc-doi-2007', 'Làm Lại Cuộc Đời', 'Boy A', 'https://phimimg.com/upload/vod/20231108-1/09038348424173545fbd3a95231b0e80.jpg', 'https://phimimg.com/upload/vod/20231108-1/7be2b16d4ca0af6204131bb984c8ba20.jpg', '<p>Nội dung phim kể về một thanh niên sau khi ra tù được đưa vào nhân thân mới, dưới sự giám sát của người giám hộ. Được giúp đỡ bởi người giám sát, người mà anh ta xem như cha, anh ta tìm được công việc và bạn bè. Anh đã sống tốt, trở thành tấm gương cho mọi người xung quanh, nhưng lỗi lầm thời niên thiếu vẫn ám ảnh, rồi đột ngột quay lại thật trớ trêu đúng lúc anh biến thành người hùng của thị trấn.</p>', 'Full', 1, 'single', 'completed', 10, 2007, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Andrew Garfield","avatar":""},{"name":"Katie Lyons","avatar":""},{"name":"Peter Mullan","avatar":""},{"name":"Shaun Evans","avatar":""},{"name":"Siobhan Finneran","avatar":""},{"name":"Alfie Owen","avatar":""},{"name":"James Young","avatar":""},{"name":"Jeremy Swift","avatar":""},{"name":"Taylor Doherty","avatar":""},{"name":"Anthony Lewis","avatar":""},{"name":"Tilly Vosburgh","avatar":""},{"name":"Josef Altin","avatar":""},{"name":"Skye Bennett","avatar":""},{"name":"Steven Pacey","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
