INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ban-da-nhan-cach', 'Cô Bạn Đa Nhân Cách', 'Two Faces of My Girlfriend', 'https://phimimg.com/upload/vod/20231129-1/299ce556464736941718ea5ef99d0380.jpg', 'https://phimimg.com/upload/vod/20231129-1/5844d683b0265916198ef98691e898b3.jpg', '<p>Giới thiệu: Anh chàng Gu Chang tuy đã 23 tuổi rồi nhưng vẫn chưa biết được mùi vị ngọt ngào của nụ hôn đầu, vì vậy, đó cũng là lí do mà Gu Chang luôn bị bạn bè trêu chọc. Một ngày nọ, Gu Chang tình cờ nhặt được một chiếc ví bị ai đó đánh rơi. Thế là duyên số đã đưa Gu Chang tìm đến với người chủ của chiếc ví – cô nàng Ani xinh đẹp. Gu Chang đã cảm thấy mình yêu Ani ngay từ cái nhìn đầu tiên dù anh vẫn cảm nhận được rằng cô gái này có một điều gì đó thật khác thường và đôi chút hơi ngông cuồng. Ani dường như là một mẫu bạn gái hoàn hảo đối với Gu Chang cho đến khi anh phát hiện ra rằng Ani là một con người đa nhân cách – hậu quả từ sự chấn động do cái chết của bạn trai cũ của Ani năm xưa. Ani chỉ là tên của một nhân cách của cô gái, còn tên thật của cô chính là Yuri…</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Bong Tae-gyu","avatar":""},{"name":"Jung Ryeo-won","avatar":""},{"name":"Lee Hae-eun","avatar":""},{"name":"Shin Eun-jung","avatar":""},{"name":"Kim In-kwon","avatar":""},{"name":"Jo Dal-hwan","avatar":""},{"name":"Jin Tae-hyeon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
