INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xxy', 'XXY', 'XXY', 'https://phimimg.com/upload/vod/20231117-1/b131a5cb7f8ca901b1160d1070b2408d.jpg', 'https://phimimg.com/upload/vod/20231117-1/ef54402f9c0e7ef67426170a991ebc40.jpg', '<p>Alex, một thanh niên 15 tuổi khác giới, đang sống như một cô gái, nhưng cô ấy và gia đình bắt đầu tự hỏi liệu cô ấy có phải là một cậu bé về mặt tình cảm hay không khi những tiến bộ về tình dục của một thiếu niên khác khiến vấn đề trở nên nghiêm trọng. Khi Alex phải đối mặt với quyết định cuối cùng về giới tính của mình, cô ấy gặp cả sự thù địch và lòng trắc ẩn.</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Inés Efrón","avatar":""},{"name":"Martín Piroyansky","avatar":""},{"name":"Ricardo Darín","avatar":""},{"name":"Valeria Bertuccelli","avatar":""},{"name":"Germán Palacios","avatar":""},{"name":"Guillermo Angelelli","avatar":""},{"name":"César Troncoso","avatar":""},{"name":"Jean Pierre Reguerraz","avatar":""},{"name":"Luciano Nóbile","avatar":""},{"name":"Lucas Escariz","avatar":""},{"name":"Ailín Salas","avatar":""},{"name":"Carolina Peleritti","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
