INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hat-tao-nguoi-may-noi-day', 'Hạt Táo: Người Máy Nổi Dậy', 'Appleseed: Ex Machina', 'https://phimimg.com/upload/vod/20231116-1/ff8a770402147ffa5c3d221f77999a9c.jpg', 'https://phimimg.com/upload/vod/20231116-1/d88811fc15be02a77168f5a733bd2dde.jpg', '<p>Là thành viên của ESWAT, lực lượng ưu tú phục vụ Olympus, Deunan và Briaereos được triển khai ở bất cứ nơi nào xảy ra rắc rối. Olympus nhận thấy mình đang bị tấn công lén lút - khủng bố người máy, những kẻ quá khích công nghệ nano chết người và những công dân nổi loạn chỉ là một số mối đe dọa mà Deunan phải đương đầu khi cô chiến đấu để cứu lấy Olympus!</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ai Kobayashi","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Yuji Kishi","avatar":""},{"name":"Kong Kuwata","avatar":""},{"name":"Shinpachi Tsuji","avatar":""},{"name":"Gara Takashima","avatar":""},{"name":"Rei Igarashi","avatar":""},{"name":"Rica Fukami","avatar":""},{"name":"Takaya Hashi","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Yasuyuki Kase","avatar":""},{"name":"Takaya Kuroda","avatar":""},{"name":"Naoko Kouda","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324521);
