INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trao-doi', 'Trao Đổi', 'Trade', 'https://phimimg.com/upload/vod/20231117-1/3116b7e40aa8d0db58136029022d2c32.jpg', 'https://phimimg.com/upload/vod/20231117-1/30e6bebe8020a21ee3c64d353e689de0.jpg', '<p>Một cảnh sát Texas, có con gái riêng có thể đã bị bắt làm nô lệ tình dục, hợp tác với một thanh niên Mexico để tìm em gái của cậu bé, người đã bị bắt cóc và ép làm gái mại dâm. Trong khi đó, một phụ nữ Ukraine được hứa hẹn một cuộc sống tốt đẹp hơn ở Mỹ cũng trở thành nạn nhân.</p>', 'Full', 1, 'single', 'completed', 18, 2007, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Kevin Kline","avatar":""},{"name":"Cesar Ramos","avatar":""},{"name":"Paulina Gaitán","avatar":""},{"name":"Alicja Bachleda-Curuś","avatar":""},{"name":"Marco Pérez","avatar":""},{"name":"Linda Emond","avatar":""},{"name":"Zack Ward","avatar":""},{"name":"Kate del Castillo","avatar":""},{"name":"Pasha D. Lychnikoff","avatar":""},{"name":"Natalia Traven","avatar":""},{"name":"Guillermo Iván","avatar":""},{"name":"Christian Vázquez","avatar":""},{"name":"José Sefami","avatar":""},{"name":"Tim Reid","avatar":""},{"name":"María Luisa Coronel","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324521);
