INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trao-doi', 'Trao Đổi', 'Trade', 'trao đổi trade kevin kline cesar ramos paulina gaitán alicja bachleda-curuś marco pérez linda emond zack ward kate del castillo pasha d. lychnikoff natalia traven guillermo iván christian vázquez josé sefami tim reid maría luisa coronel ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-than-chet-cuoc-muu-phan-cua-bui-kim-cuong-mot-thanh-hyorinmaru-khac', 'Sứ Mệnh Thần Chết: Cuộc Mưu Phản Của Bụi Kim Cương - Một Thanh Hyorinmaru Khác', 'Bleach the Movie: The DiamondDust Rebellion', 'https://phimimg.com/upload/vod/20231117-1/e36ef1102a4b071ee8fe2e3620be793e.jpg', 'https://phimimg.com/upload/vod/20231117-1/387f0121f6eb90ddc5a17cfdd4aeb3e6.jpg', '<p>Đội trưởng đội 10, Hitsugaya Toushirou của Hộ Đình Thập Tam Đội thuộc tâm linh giới đào ngũ vì một lí do không xác định trong một lần làm nhiệm vụ bảo vệ cho đoàn diễu hành đang trên đường thay đổi chỗ cất giữ Vương Ấn của hoàng tộc. Vì lí do đó, toàn đội 10 bị giam lỏng tại doạnh trại và đội trưởng Hitsugaya bị gán cho cái mác phản bội. Tung tích của Vương Ấn và Hitsugaya cùng nhân dạng của kẻ đã cướp Vương Ấn đều không xác định được. Trong tình thế hổn loạn đó, đội trưởng Kyoraku ở tâm linh giới cùng đội tìm kiếm do đội phó đội 3 Kira và đội trưởng tạm thời đội 9 Hisagi ở nhân giới cùng bị đánh trọng thương bởi Hyourinmaru gần như trong cùng một thời điểm. Một lệnh khẩn được ban ra: Đặc việc bắt giữ Hitsugaya Toushirou lên hàng đầu và xử tử hắn ngay tại chỗ nếu hắn chống cự!</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masakazu Morita","avatar":""},{"name":"Romi Park","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Fumiko Orikasa","avatar":""},{"name":"Kentaro Ito","avatar":""},{"name":"Kaya Matsutani","avatar":""},{"name":"Masaaki Tsukada","avatar":""},{"name":"Aya Hisakawa","avatar":""},{"name":"Yukana","avatar":""},{"name":"Noriaki Sugiyama","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Yuki Matsuoka","avatar":""},{"name":"Hideo Ishikawa","avatar":""},{"name":"Ryotaro Okiayu","avatar":""},{"name":"Nobuyuki Hiyama","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Tom","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324521);
