INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-anh-duong', 'Bí Mật Ánh Dương', 'Secret Sunshine', 'https://phimimg.com/upload/vod/20231115-1/e0abcd222ad0664735939360a3278a90.jpg', 'https://phimimg.com/upload/vod/20231115-1/49e044b8f671209a44e2856443cc05b6.jpg', '<p>Shin Ae và cậu con trai Jun cùng dời đến làng Miryang sinh sống. Shin Ae đã mất rất nhiều thứ, mất đi người chồng của mình và mơ ước trở thành một nhà dương cầm. Tại ngôi làng này, Shin Ae bắt đầu một cuộc sống mới bằng việc mở một lớp dạy đàn. Tại nơi đây, có một người đàn ông tên Jong Chan đem lòng cảm mến Shin Ae ngay từ lần gặp đầu tiên, và anh luôn lặng lẽ giúp đỡ Shin Ae vượt qua mọi khó khăn.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jeon Do-yeon","avatar":""},{"name":"Song Kang-ho","avatar":""},{"name":"Jo Young-jin","avatar":""},{"name":"Seon Jeong-yeop","avatar":""},{"name":"Kim Young-jae","avatar":""},{"name":"Park Myung-shin","avatar":""},{"name":"Cha Mi-kyeong","avatar":""},{"name":"Oh Man-seok","avatar":""},{"name":"Jang Hye-jin","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Kim Mi-hyang","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Lee Yoon-hee","avatar":""},{"name":"Go Seo-hee","avatar":""},{"name":"Lee Dong-yong","avatar":""},{"name":"Kim Min-jae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
