INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bi-mat-anh-duong', 'Bí Mật Ánh Dương', 'Secret Sunshine', 'bí mật ánh dương secret sunshine jeon do-yeon song kang-ho jo young-jin seon jeong-yeop kim young-jae park myung-shin cha mi-kyeong oh man-seok jang hye-jin lee sung-min kim mi-hyang lee hee-jun kim jong-soo yeom hye-ran lee yoon-hee go seo-hee lee dong-yong kim min-jae ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-tho-mimzy-cuoi-cung', 'Chú Thỏ Mimzy Cuối Cùng', 'The Last Mimzy', 'https://phimimg.com/upload/vod/20231113-1/756fc7ba134921278f8d7a25d50b5bf3.jpg', 'https://phimimg.com/upload/vod/20231113-1/106658451b37b041d07982aac41e6b45.jpg', '<p>Bộ phim được chuyển thể từ truyện ngắn khoa học viễn tưởng năm 1943 &quot;Mimsy Were the Borogove&quot; của Lewis Padgett. Trong một lần nghịch ngợm hai anh em là Noah và Emma đã tìm thấy một chiếc hộp chứa đựng nhiều đồ vật thú vị mà đối với những đứa trẻ như chúng, chúng chỉ nghĩ đó đơn giản là đồ chơi. Sau một thời gian vui đùa với chúng, cả hai cô cậu bé bỗng nhiên trở nên thông minh một cách kỳ lạ. Không ai biết lý do tại sao, nhưng có vẻ như họ trở nên thông thái và sáng suốt hơn những gì mà từ nhỏ đến giờ họ thể hiện, họ giỏi hơn những đứa trẻ trong độ tuổi của họ có thể làm. Nhưng rồi sự việc không dừng lại ở đó khi mà Emma cho mẹ cô biết rằng chú thỏ nhồi bông Mimzy - một trong những đồ chơi trong hộp - là từ tương lai đến để đưa ra chỉ thị cho một nhiệm vụ quan trọng mà người mở chiếc hộp ra phải thực hiện chỉ thị này. Liệu chỉ thị đến từ chú thỏ tương lai cho anh em nhà Noah và Emma là gì? Họ có thực hiện được nhiệm vụ được giao hay không?</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joely Richardson","avatar":""},{"name":"Rainn Wilson","avatar":""},{"name":"Rhiannon Leigh Wryn","avatar":""},{"name":"Kathryn Hahn","avatar":""},{"name":"Chris O''Neil","avatar":""},{"name":"Timothy Hutton","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Kirsten Alter","avatar":""},{"name":"Irene Snow","avatar":""},{"name":"Marc Musso","avatar":""},{"name":"Nicole Muñoz","avatar":""},{"name":"Scott E. Miller","avatar":""},{"name":"Megan McKinnon","avatar":""},{"name":"Randi Lynne","avatar":""},{"name":"Tom Heaton","avatar":""},{"name":"Fred Keating","avatar":""},{"name":"Calum","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324521);
