INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-la-chap-nhan', 'Sống Là Chấp Nhận', 'Dan in Real Life', 'https://phimimg.com/upload/vod/20231113-1/4d4657582c97ef81ac4acd9eba910447.jpg', 'https://phimimg.com/upload/vod/20231113-1/ed2678c2c829585f444437738f89845f.jpg', '<p>Dan Burns, một phóng viên phụ trách một chuyên mục của một tờ báo, góa vợ và là cha của 3 cô con gái Jane, Cara, và Lilly. Cả gia đình của anh sống tại vùng ngoại ô New Jersey. Chuyên mục của anh được một công ty truyền thông báo chí cung cấp tin bài trên toàn quốc. Khi 3 bố con anh tổ chức chuyến đi đến đảo Rhode thăm bố mẹ của anh trong lần gặp mặt người thân thường niên, nhiều chuyện rắc rối đã xảy ra: Cara không muốn đến đảo Rhode và xa bạn trai của mình nên tìm mội cách để phá hỏng chuyến đi. Nhưng cũng trong thời gian này, Dan gặp Marie và họ đã phát triển mối quan hệ của mình thành 1 mối quan hệ tình yêu nghiêm túc.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Carell","avatar":""},{"name":"Juliette Binoche","avatar":""},{"name":"Dane Cook","avatar":""},{"name":"Alison Pill","avatar":""},{"name":"Britt Robertson","avatar":""},{"name":"Marlene Lawston","avatar":""},{"name":"Dianne Wiest","avatar":""},{"name":"John Mahoney","avatar":""},{"name":"Norbert Leo Butz","avatar":""},{"name":"Amy Ryan","avatar":""},{"name":"Jessica Hecht","avatar":""},{"name":"Frank Wood","avatar":""},{"name":"Henry Priest Miller","avatar":""},{"name":"Ella Miller","avatar":""},{"name":"CJ Adams","avatar":""},{"name":"Jessica Lussier","avatar":""},{"name":"Seth D''Antuono","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"C