INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-thi-hoa-hau-toc', 'Cuộc Thi Hoa Hậu Tóc', 'Hairspray', 'https://phimimg.com/upload/vod/20231115-1/07996de954333ecf73402b146d39cdc0.jpg', 'https://phimimg.com/upload/vod/20231115-1/889b3f887622e6ed2425bfca4b5f0486.jpg', '<p>Phim điện ảnh Mỹ thuộc thề loại thể thao âm nhạc nói về một cô bé có niềm đam mê nhảy múa và thích được biểu diễn trong chương trình khiêu vũ. Nhưng cũng từ đó cô nhận được sự ganh ghét từ phí cô bạn nhảy. Liệu cô có thực hiện được mơ ước trong khi có rất nhiều áp lực xung quanh mình.</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Nikki Blonsky","avatar":""},{"name":"Zac Efron","avatar":""},{"name":"John Travolta","avatar":""},{"name":"Brittany Snow","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Amanda Bynes","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Elijah Kelley","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Taylor Parks","avatar":""},{"name":"Jayne Eastwood","avatar":""},{"name":"Paul Dooley","avatar":""},{"name":"Jerry Stiller","avatar":""},{"name":"Darren Frost","avatar":""},{"name":"John Waters","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
