INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-khach', 'Du Khách', 'The Visitor', 'https://phimimg.com/upload/vod/20231113-1/36a08ae19b6be8b59774a1dba9e78f28.jpg', 'https://phimimg.com/upload/vod/20231113-1/0d4355297cea65f32e054e6a22e52cc2.jpg', '<p>Một giáo sư đại học đến thành phố New York để tham dự một hội nghị và tìm thấy một cặp vợ chồng trẻ sống trong căn hộ của mình.</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Jenkins","avatar":""},{"name":"Haaz Sleiman","avatar":""},{"name":"Danai Gurira","avatar":""},{"name":"Hiam Abbass","avatar":""},{"name":"Marian Seldes","avatar":""},{"name":"Maggie Moore","avatar":""},{"name":"Richard Kind","avatar":""},{"name":"Michael Cumpsty","avatar":""},{"name":"Bill McHenry","avatar":""},{"name":"Tzahi Moskovitz","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324521);
