INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-lan-ngoc-trai', 'Thợ Lặn Ngọc Trai', 'Pearl Diver', 'https://phimimg.com/upload/vod/20231112-1/69b848ce15ad97c23cd896947a9b1681.jpg', 'https://phimimg.com/upload/vod/20231112-1/d5997c40201ac611fa52b26528596e0c.jpg', '<p>Thợ Lặn Ngọc Trai - Pearl Diver là câu chuyện đầy góc khuất về hai chị em. Họ bị ám ảnh bởi vụ giết mẹ năm hai mươi tuổi và những bí mật chôn giấu đằng sau đó. Hai mươi năm sau, một đêm sẽ lại thay đổi cuộc đời họ. Họ học được rằng đôi khi những bí mật từ quá khứ có thể mang lại hy vọng cho tương lai.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joey Honsa","avatar":""},{"name":"Amy Jean Johnson","avatar":""},{"name":"Emily Stoltzfus","avatar":""},{"name":"Jeremy Glickstein","avatar":""},{"name":"Maddie Abshire","avatar":""},{"name":"Brian Boland","avatar":""},{"name":"Bob Miller","avatar":""},{"name":"Kim Stauffer","avatar":""},{"name":"Cary Leiter","avatar":""},{"name":"Arden Weiner","avatar":""},{"name":"Christopher Collard","avatar":""},{"name":"Edwin Wilson","avatar":""},{"name":"Jim Bowen","avatar":""},{"name":"Laura Gouin","avatar":""},{"name":"Evgeniy Lazarev","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
