INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon', 'Linh Hồn', 'Saawariya', 'https://phimimg.com/upload/vod/20231112-1/67c9552e839c25b9daaa0b37ce835319.jpg', 'https://phimimg.com/upload/vod/20231112-1/66eab01cc6bac2058d18812aebc0d96f.jpg', '<p>Linh Hồn là bộ phim tình cảm xoay quanh hai linh hồn bơ vơ tình cờ gặp nhau tại một thị trấn nhỏ trong một kỳ nghỉ. Họ từ bỏ tất cả để được là chính mình những giấc mơ huyền diệu được dệt thành một bản tình ca đầy màu sắc. Nước mắt có thể rơi, nhưng tình yêu thì không dừng lại.</p>', 'Full', 1, 'single', 'completed', 18, 2007, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Ranbir Kapoor","avatar":""},{"name":"Sonam Kapoor Ahuja","avatar":""},{"name":"Salman Khan","avatar":""},{"name":"Rani Mukerji","avatar":""},{"name":"Zohra Sehgal","avatar":""},{"name":"Begum Para","avatar":""},{"name":"Kenny Desai","avatar":""},{"name":"Vibha Chibber","avatar":""},{"name":"Neha Bam","avatar":""},{"name":"Sanaya Irani","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324521);
