INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-nang-qua-yeu', 'Khi Nàng Quá Yêu', 'The Heartbreak Kid', 'https://phimimg.com/upload/vod/20231113-1/ffaea58c76a5612015bf7032fae76b7b.jpg', 'https://phimimg.com/upload/vod/20231113-1/f302cc4bc64407bfde975c852aa666f5.jpg', '<p>Eddie, người đàn ông độc thân 40 tuổi cuối cùng đã nói &quot;Tôi đồng ý&quot; với Lila xinh đẹp và gợi cảm. Nhưng trong tuần trăng mật của họ ở Mexico, người phụ nữ trong mộng của anh ta hóa ra lại là một cơn ác mộng hoàn toàn, và anh chàng không bao giờ có thể bóp cò súng nhận ra mình đã nhảy súng.</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Malin Åkerman","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Jerry Stiller","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Mae LaBorde","avatar":""},{"name":"Carlos Mencia","avatar":""},{"name":"Scott Wilson","avatar":""},{"name":"Polly Holliday","avatar":""},{"name":"Danny McBride","avatar":""},{"name":"Roy Jenkins","avatar":""},{"name":"Stephanie Courtney","avatar":""},{"name":"Natalie Carter","avatar":""},{"name":"Nicol Paone","avatar":""},{"name":"Miranda May","avatar":""},{"name":"Kathy Lamkin","avatar":""},{"name":"Dean Norris","avatar":""},{"name":"Lesli","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324521);
