INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('den-phut-cuoi-cung', 'Đến Phút Cuối Cùng', 'Until Death', 'https://phimimg.com/upload/vod/20231111-1/db7d42e3a373b2a3c96dc23bfdd67f4b.jpg', 'https://phimimg.com/upload/vod/20231111-1/cfb8cddabbabe3fe066c8e799cadd95c.jpg', '<p>Anthony Stowe làm trong đội cảnh sát chống ma túy nhưng chính anh lại là một con nghiện. Gần như mọi đồng nghiệp đều căm ghét Anthony vì anh cư xử quá tệ bạc. Ngay đến chuyện gia đình của anh cũng gặp không ít vấn đề. Vợ anh vừa thông báo có thai, nhưng đứa bé trong bụng lại không phải là con anh. Một ngày nọ, Anthony được giao nhiệm vụ truy quét một nhóm tội phạm chuyên mua bán ma túy. Lần này, tên trùm ma túy lại chính là một người đồng đội cũ của Anthony. Hắn đã cho người truy sát Anthony và dùng súng bắn thẳng vào đầu anh. Anthony rơi vào trạng thái hôn mê trong suốt nhiều tháng liền. May mắn trở về từ cõi chết, Anthony bỗng nhận ra những năm tháng vừa qua anh đã sống một cuộc đời thật vô ích. Anh muốn bắt đầu một quãng đời mới, trở thành một người cha tốt, một người chồng tốt. Nhưng Anthony lập tức phải đương đầu với những thử thách đầy khó khăn: vợ anh vừa bị bắt cóc và kẻ thù của anh vẫn đang truy đuổi anh từng ngày...</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Selina Giles","avatar":""},{"name":"Fiona O''Shaughnessy","avatar":""},{"name":"William Ash","avatar":""},{"name":"Alana Maria","avatar":""},{"name":"Gary Beadle","avatar":""},{"name":"Mark Dymond","avatar":""},{"name":"Stephen Rea","avatar":""},{"name":"Wes Robinson","avatar":""},{"name":"Stephen Lord","avatar":""},{"name":"Julia Horvath","avatar":""},{"name":"Rachel O''Meara","avatar":""},{"name":"Michal Yannai","avatar":""},{"name":"Rachel Grant","avatar":""},{"name":"Buffy Davis","avatar":""},{"name":"Maggie Eldred","avatar":""},{"name":"C. Ger","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324521);
