INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('niem-song', 'Niềm Sống', 'The Bucket List', 'https://phimimg.com/upload/vod/20231111-1/d2da58e12695604b233b07ac2ed42a7c.jpg', 'https://phimimg.com/upload/vod/20231111-1/679303d7f985b70a9ef34f7887673583.jpg', '<p>Nhà triệu phú Edward Cole và Carter Chambers, một người công nhân thợ máy trở thành bạn của nhau vì cả hai đều là bệnh nhân của một trung tâm chữa bệnh ung thư. Họ được sắp xếp ở chung phòng với nhau và 2 người đã quyết định bỏ lại những lo lắng đời thường mà sẽ làm những việc mà họ muốn trước khi quá muộn theo một danh sách mà 2 người đề ra. Và vì thế, 2 người đàn ông trung niên không có một điểm gì giống nhau ngoại trừ căn bệnh ung thư đã an ủi nhau, trở thành bạn bè và tìm được niềm vui lúc tuổi già...</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Nicholson","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Sean Hayes","avatar":""},{"name":"Beverly Todd","avatar":""},{"name":"Alfonso Freeman","avatar":""},{"name":"Destiny Brownridge","avatar":""},{"name":"Rob Morrow","avatar":""},{"name":"Dawn Lewis","avatar":""},{"name":"Rowena King","avatar":""},{"name":"Annton Berry Jr.","avatar":""},{"name":"Verda Bridges","avatar":""},{"name":"Brian Copeland","avatar":""},{"name":"Ian Anthony Dale","avatar":""},{"name":"Jennifer Defrancisco","avatar":""},{"name":"Angela Gardner","avatar":""},{"name":"Noel Gugliemi","avatar":""},{"name":"Jon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324521);
