INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rambow-nhi', 'Rambow Nhí', 'Son of Rambow', 'https://phimimg.com/upload/vod/20231111-1/75a033902447dd4f79847ac2a55fdcb5.jpg', 'https://phimimg.com/upload/vod/20231111-1/d733e4104acc5f29c33d266d1b3c7e77.jpg', '<p>Will đang tìm cách thoát khỏi gia đình thì gặp Lee, kẻ bắt nạt học đường. Được trang bị một máy quay video và một bản sao của Rambo, Lee dự định làm một video hoành tráng đầy hành động của riêng mình.</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Milner","avatar":""},{"name":"Will Poulter","avatar":""},{"name":"Jessica Hynes","avatar":""},{"name":"Jules Sitruk","avatar":""},{"name":"Neil Dudgeon","avatar":""},{"name":"Ed Westwick","avatar":""},{"name":"Anna Wing","avatar":""},{"name":"Tallulah Evans","avatar":""},{"name":"Emilie Chesnais","avatar":""},{"name":"Paul Ritter","avatar":""},{"name":"Adam Buxton","avatar":""},{"name":"Adam Godley","avatar":""},{"name":"Asa Butterfield","avatar":""},{"name":"Edgar Wright","avatar":""},{"name":"Adam Paul Harvey","avatar":""},{"name":"Atila Emirali","avatar":""},{"name":"Louise Jennings","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324521);
