INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-vuong-hoc-duong', 'Bá Vương Học Đường', 'Crows Zero', 'https://phimimg.com/upload/vod/20231111-1/2d851e3a142446f7cd4b09e83149e515.jpg', 'https://phimimg.com/upload/vod/20231111-1/9aab6f101a41304b7b9e1e77bd79e5d4.jpg', '<p>Genji Takiya, con trai của bố già xã hội đen vừa mới chuyển đến Suzaran với mục tiêu chế ngự trường học để tiếp quản vị trí của bố mình trong tổ chức. Genji nhanh chóng tìm ra kẻ mạnh nhất là Tamao Serizawa, người cũng đang thiết lập sự thống trị của mình trên các lớp của cấp học. Là một kẻ mới đến, Genji không được để tâm do vậy anh tìm kiếm sự giúp đỡ từ một mafia cũng xuất thân từ trường Suzaran, Ken Katagiri và tự xây dựng băng đảng riêng của mình như một cuộc ganh đua với Tamao tới vị trí cai trị cao nhất.</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shun Oguri","avatar":""},{"name":"Kyosuke Yabe","avatar":""},{"name":"Meisa Kuroki","avatar":""},{"name":"Takayuki Yamada","avatar":""},{"name":"Kenichi Endo","avatar":""},{"name":"Goro Kishitani","avatar":""},{"name":"Kenta Kiritani","avatar":""},{"name":"Sousuke Takaoka","avatar":""},{"name":"Yusuke Kamiji","avatar":""},{"name":"Shunsuke Daitoh","avatar":""},{"name":"Kaname Endo","avatar":""},{"name":"Dai Watanabe","avatar":""},{"name":"Motoki Fukami","avatar":""},{"name":"Hisato Izaki","avatar":""},{"name":"Yusuke Izaki","avatar":""},{"name":"Suzunosuke Tanaka","avatar":""},{"name":"Sansei Shiomi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id