INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-nguy-hiem', 'Nhiệm Vụ Nguy Hiểm', 'Reno 911!: Miami', 'https://phimimg.com/upload/vod/20231111-1/856cf9d8b5c765039fc364bd534e1b62.jpg', 'https://phimimg.com/upload/vod/20231111-1/040375eedcb35b38211a3a9cbac36325.jpg', '<p>Một nhóm cảnh sát Reno ăn mặc rách rưới được gọi đến để cứu vãn tình thế sau khi một cuộc tấn công khủng bố làm gián đoạn một hội nghị cảnh sát quốc gia ở Bãi biển Miami trong kỳ nghỉ xuân. Dựa trên loạt phim Comedy Central.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Carlos Alazraqui","avatar":""},{"name":"Mary Birdsong","avatar":""},{"name":"Robert Ben Garant","avatar":""},{"name":"Kerri Kenney","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Wendi McLendon-Covey","avatar":""},{"name":"Niecy Nash","avatar":""},{"name":"Cedric Yarbrough","avatar":""},{"name":"Lennie Loftin","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"Alejandra Gutierrez","avatar":""},{"name":"Brandon Molale","avatar":""},{"name":"Kathryn Fiore","avatar":""},{"name":"David Koechner","avatar":""},{"name":"Dave Holmes","avatar":""},{"name":"Patton Oswal","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324521);
