INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhiem-vu-nguy-hiem', 'Nhiệm Vụ Nguy Hiểm', 'Reno 911!: Miami', 'nhiệm vụ nguy hiểm reno 911!: miami carlos alazraqui mary birdsong robert ben garant kerri kenney thomas lennon wendi mclendon-covey niecy nash cedric yarbrough lennie loftin danny devito alejandra gutierrez brandon molale kathryn fiore david koechner dave holmes patton oswal ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-tham-sat-o-katyn', 'Vụ Thảm Sát Ở Katyn', 'Katyn', 'https://phimimg.com/upload/vod/20231110-1/44c7aaa68b4a3865ba4b763520f1098a.jpg', 'https://phimimg.com/upload/vod/20231110-1/63f4e7b62855afbbae6d05bfd515ca17.jpg', '<p>Katyn là tên một cánh rừng trên lãnh thổ Nga, gần Smolensk. Tháng tám 1941, đạo quân phát xít Đức khám phá thấy tại Katyn các mồ chôn tập thể của hơn 4.000 sĩ quan Ba Lan, mỗi nạn nhân bị bắn một phát súng vào đầu. Kể từ đó, Katyn đồng nghĩa với các vụ thảm sát của hàng chục ngàn tù nhân Ba Lan thuộc thành phần ưu tú nước này mà mộ phần nằm rải rác ở biên giới phía tây nước Nga. Thảm sát Katyn là tên gọi của vụ giết người hàng loạt, được thực hiện bởi Bộ Dân ủy Nội vụ Liên Xô (NKVD) chiểu theo quyết định ra ngày 5-3-1940 của Bộ Chính trị Ủy ban Trung ương Đảng Cộng sản Liên Xô, đối với khoảng 15 ngàn tù binh Ba Lan, đa phần là sĩ quan dự bị và sĩ quan từ cấp tá trở lên, khi đó bị giam tại các trại tù trên lãnh thổ ...</p>', 'Full', 1, 'single', 'completed', 24, 2007, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Andrzej Chyra","avatar":""},{"name":"Maja Ostaszewska","avatar":""},{"name":"Artur Żmijewski","avatar":""},{"name":"Danuta Stenka","avatar":""},{"name":"Jan Englert","avatar":""},{"name":"Magdalena Cielecka","avatar":""},{"name":"Agnieszka Glińska","avatar":""},{"name":"Paweł Małaszyński","avatar":""},{"name":"Maja Komorowska","avatar":""},{"name":"Władysław Kowalski","avatar":""},{"name":"Antoni Pawlicki","avatar":""},{"name":"Agnieszka Kawiorska","avatar":""},{"name":"Sergey Garmash","avatar":""},{"name":"Joachim Paul Assböck","avatar":""},{"name":"Waldem","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324521);
