INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-nhay-soi-dong', 'Điệu Nhảy Sôi Động', 'Stomp the Yard', 'https://phimimg.com/upload/vod/20231109-1/a13b397615fd51cc626ba87a210121cc.jpg', 'https://phimimg.com/upload/vod/20231109-1/43cf499d8cdb2d2a169789c7d3cb0b13.jpg', '<p>Sau cái chết của em trai mình, một vũ công đường phố 19 tuổi rắc rối đến từ Los Angeles đã có thể vượt qua hội trường dành cho trẻ vị thành niên bằng cách đăng ký vào trường Đại học Truth lịch sử của người da đen ở Atlanta, Georgia. Nhưng những nỗ lực của anh ấy để có được một nền giáo dục và thu hút cô gái anh ấy thích đã bị gạt sang một bên khi anh ấy được hai hội anh em hàng đầu trong trường tán tỉnh, cả hai đều muốn và cần những bước nhảy theo phong cách đường phố khốc liệt của anh ấy để giành chiến thắng trong cuộc thi trình diễn bước đi quốc gia rất được thèm muốn.</p>', 'Full', 1, 'single', 'completed', 21, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Columbus Short","avatar":""},{"name":"Meagan Good","avatar":""},{"name":"Ne-Yo","avatar":""},{"name":"Darrin Henson","avatar":""},{"name":"Jermaine Williams","avatar":""},{"name":"Chris Brown","avatar":""},{"name":"Laz Alonso","avatar":""},{"name":"Brian J. White","avatar":""},{"name":"Valarie Pettiford","avatar":""},{"name":"Harry Lennix","avatar":""},{"name":"April Clark","avatar":""},{"name":"Wanita \"D. Woods\" Woodgette","avatar":""},{"name":"Allan Louis","avatar":""},{"name":"Tony Vaughn","avatar":""},{"name":"Michael Franklin","avatar":""},{"name":"Duain Richmond","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324521);
