INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-my', 'Giang Hồ Mỹ', 'American Gangster', 'https://phimimg.com/upload/vod/20231109-1/f44e4d42b1b2f4dd5ad0973abb7452a8.jpg', 'https://phimimg.com/upload/vod/20231109-1/ff5192bee7dc34c8d2ce08e88f34a33c.jpg', '<p>Tham vọng và tệ nạn đối đầu ở Harlem hồi 1970, khi một trùm ma túy có sức lôi cuốn vươn lên nắm quyền, rồi đối đầu với một thanh tra chính trực và những kẻ thù nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Denzel Washington","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"Armand Assante","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"John Hawkes","avatar":""},{"name":"RZA","avatar":""},{"name":"Lymari Nadal","avatar":""},{"name":"Yul Vazquez","avatar":""},{"name":"Ruby Dee","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Joe Morton","avatar":""},{"name":"Common","avatar":""},{"name":"Ritchie Coster","avatar":""},{"name":"Jon Polito","avatar":""},{"name":"Kev","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324521);
