INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('your-friend-the-rat', 'Your Friend the Rat', 'Your Friend the Rat', 'https://phimimg.com/upload/vod/20231109-1/3715b5937f53e199ec49e1ca9990e088.jpg', 'https://phimimg.com/upload/vod/20231109-1/6e6d4d91cf2df265a9ebe3aa5acfb006.jpg', '<p>Hãy đối mặt với nó, chuột không phải là sinh vật được yêu thích nhất trên trái đất. Tuy nhiên, có thể câu chuyện nhỏ về lịch sử tương tác giữa con người và chuột này sẽ thay đổi giai điệu của thế giới. Ít nhất thì đó là hy vọng của Remy, ngôi sao của Ratatouille, và người em bất đắc dĩ Emile của anh khi họ hướng dẫn chúng ta về lịch sử thế giới từ góc nhìn của một con chuột. Tại sao tất cả chúng ta không thể hòa thuận với nhau?</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patton Oswalt","avatar":""},{"name":"Peter Sohn","avatar":""},{"name":"Lou Romano","avatar":""},{"name":"Jim Capobianco","avatar":""},{"name":"John Ratzenberger","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324521);
