INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-binh-cuoi-cung', 'Đạo Binh Cuối Cùng', 'The Last Legion', 'https://phimimg.com/upload/vod/20231109-1/39e97a89f76deb7c4b48ebf0a9156586.jpg', 'https://phimimg.com/upload/vod/20231109-1/bd5ccd762842e266ea334ce21bd2e47c.jpg', '<p>Khi đế chế La Mã sụp đổ, chàng trai trẻ Romulus Augustus chạy trốn khỏi thành phố và dấn thân vào chuyến hành trình đầy nguy hiểm đến Anh để truy lùng quân đoàn ủng hộ.</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Firth","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Aishwarya Rai Bachchan","avatar":""},{"name":"Peter Mullan","avatar":""},{"name":"Kevin McKidd","avatar":""},{"name":"John Hannah","avatar":""},{"name":"Iain Glen","avatar":""},{"name":"Thomas Brodie-Sangster","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"Nonso Anozie","avatar":""},{"name":"Owen Teale","avatar":""},{"name":"Alexander Siddig","avatar":""},{"name":"Robert Pugh","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Harry Van Gorkum","avatar":""},{"name":"Murray McArthur","avatar":""},{"name":"Lee Ingl","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324521);
