INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-da-xong-chua', 'Chúng Ta Đã Xong Chưa', 'Are We Done Yet?', 'https://phimimg.com/upload/vod/20231109-1/92ece294282c3264b3b581418da5a08c.jpg', 'https://phimimg.com/upload/vod/20231109-1/35686617440be060cd0f1996ed084f40.jpg', '<p>Cặp vợ chồng mới cưới Nick và Suzanne quyết định chuyển đến vùng ngoại ô để mang lại cuộc sống tốt hơn cho hai đứa con của họ. Nhưng ý tưởng về ngôi nhà mơ ước của họ bị xáo trộn bởi một nhà thầu có cách tiếp cận kinh doanh kỳ lạ.</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ice Cube","avatar":""},{"name":"Nia Long","avatar":""},{"name":"John C. McGinley","avatar":""},{"name":"Aleisha Allen","avatar":""},{"name":"Philip Bolden","avatar":""},{"name":"Jonathan Katz","avatar":""},{"name":"Linda Kash","avatar":""},{"name":"Alexandr Kalugin","avatar":""},{"name":"Dan Joffre","avatar":""},{"name":"Pedro Miguel Arce","avatar":""},{"name":"Tahj Mowry","avatar":""},{"name":"Jacob Vargas","avatar":""},{"name":"Brenda Prieur","avatar":""},{"name":"Hayes MacArthur","avatar":""},{"name":"Colin Strange","avatar":""},{"name":"Gavin Strange","avatar":""},{"name":"Chris Gauthier","avatar":""},{"name":"Tara Me","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324521);
