INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nha-hung-bien', 'Những Nhà Hùng Biện', 'The Great Debaters', 'https://phimimg.com/upload/vod/20231109-1/68cced6b2c0282be00fb65fbcbe4d050.jpg', 'https://phimimg.com/upload/vod/20231109-1/aa446682f6cf4f7aad77bd0c8202bf2f.jpg', '<p>Những Nhà Hùng Biện - The Great Debaters dựa trên câu chuyện có thật, xoay quanh những nỗ lực của huấn luyện viên Melvin B. Tolson (Denzel Washington) tại Wiley College - một trường đại học dành cho người da màu. Năm 1935, ông đã truyền cảm hứng cho các sinh viên thành lập nhóm tranh luận đầu tiên của trường, thách thức Harvard trong Giải vô địch quốc gia và cuối cùng giành giải vô địch một cách thuyết phục.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Whitaker","avatar":""},{"name":"Denzel Washington","avatar":""},{"name":"Nate Parker","avatar":""},{"name":"Jurnee Smollett","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Kimberly Elise","avatar":""},{"name":"Jermaine Williams","avatar":""},{"name":"Gina Ravera","avatar":""},{"name":"John Heard","avatar":""},{"name":"Devyn A. Tyler","avatar":""},{"name":"Trenton McClain Boyd","avatar":""},{"name":"Ritchie Montgomery","avatar":""},{"name":"Jackson Walker","avatar":""},{"name":"Tim Parati","avatar":""},{"name":"Robert X. Golphin","avatar":""},{"name":"Justice","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
