INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-don-duong', 'Kẻ Đón Đường', 'The Hitcher', 'https://phimimg.com/upload/vod/20231108-1/7621f31b53cfce8ae357992e4a9c1e2e.jpg', 'https://phimimg.com/upload/vod/20231108-1/962b91f0f568b3bfaab0c98ae88db525.jpg', '<p>Khi đang lái xe qua sa mạc New Mexico trong một đêm mưa, các sinh viên đại học Jim Halsey và bạn gái của anh ấy là Grace Andrews đã nhờ người quá giang John Ryder. Khi ở trong xe của họ, kẻ lạ mặt tỏ ra là một kẻ tâm thần dùng dao đe dọa đôi vợ chồng trẻ, nhưng Jim đã thành công ném hắn ra khỏi xe trên đường. Sáng hôm sau, cặp vợ chồng trẻ nhìn thấy John trên một chiếc ô tô khác.</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Bean","avatar":""},{"name":"Sophia Bush","avatar":""},{"name":"Zachary Knighton","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Kyle Davis","avatar":""},{"name":"Danny Bolero","avatar":""},{"name":"Jeffrey Hutchinson","avatar":""},{"name":"Skip O''Brien","avatar":""},{"name":"Travis Schuldt","avatar":""},{"name":"Yara Martinez","avatar":""},{"name":"Lauren Cohn","avatar":""},{"name":"Kurt Grossi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324521);
