INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-biet-ke-giet-minh', 'Tôi Biết Kẻ Giết Mình', 'I Know Who Killed Me', 'https://phimimg.com/upload/vod/20231108-1/91a1708569c8d8d9ba682cfb3152c4ec.jpg', 'https://phimimg.com/upload/vod/20231108-1/a461cfc92aa62198b821a77cc3845556.jpg', '<p>Một thị trấn nhỏ bình dị bị rung chuyển khi Aubrey Fleming, một phụ nữ trẻ thông minh và đầy triển vọng, bị một kẻ giết người hàng loạt tàn bạo bắt cóc và tra tấn. Khi cố gắng trốn thoát, cô gái bị chấn thương tỉnh lại trong bệnh viện khẳng định rằng cô không phải là người mà họ nghĩ và rằng Aubrey Fleming thực sự vẫn đang gặp nguy hiểm tính mạng.</p>', 'Full', 1, 'single', 'completed', 18, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lindsay Lohan","avatar":""},{"name":"Julia Ormond","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Spencer Garrett","avatar":""},{"name":"Gregory Itzin","avatar":""},{"name":"Kenya Moore","avatar":""},{"name":"Garcelle Beauvais","avatar":""},{"name":"Bonnie Aarons","avatar":""},{"name":"Michael Adler","avatar":""},{"name":"Art Bell","avatar":""},{"name":"Michael Esparza","avatar":""},{"name":"Cornelia Guest","avatar":""},{"name":"Brian Geraghty","avatar":""},{"name":"David Figlioli","avatar":""},{"name":"Megan Henning","avatar":""},{"name":"Jason Wilburn","avatar":""},{"name":"Jesse Hlubi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324521);
