INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-duoc-cuoi', 'Quyền Được Cưới', 'License to Wed', 'https://phimimg.com/upload/vod/20231108-1/70fd991140bcbbbcbee83a894047aa18.jpg', 'https://phimimg.com/upload/vod/20231108-1/4d86280db30cbc488748334ed8005571.jpg', '<p>Mới đính hôn, Ben và Sadie nóng lòng muốn bắt đầu cuộc sống chung và sống hạnh phúc mãi mãi. Tuy nhiên, Mục sư Frank của nhà thờ gia đình Sadie sẽ không ban phước cho sự kết hợp của họ cho đến khi họ vượt qua khóa học chuẩn bị kết hôn &quot;hoàn hảo&quot; đã được cấp bằng sáng chế của ông bao gồm các lớp học kỳ quặc, bài tập về nhà kỳ lạ và một số hành vi xâm phạm quyền riêng tư hoàn toàn.</p>', 'Full', 1, 'single', 'completed', 20, 2007, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Mandy Moore","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"Eric Christian Olsen","avatar":""},{"name":"Christine Taylor","avatar":""},{"name":"Josh Flitter","avatar":""},{"name":"DeRay Davis","avatar":""},{"name":"Peter Strauss","avatar":""},{"name":"Grace Zabriskie","avatar":""},{"name":"Roxanne Hart","avatar":""},{"name":"Mindy Kaling","avatar":""},{"name":"Angela Kinsey","avatar":""},{"name":"Rachael Harris","avatar":""},{"name":"Brian Baumgartner","avatar":""},{"name":"David Quinlan","avatar":""},{"name":"Bob Balaban","avatar":""},{"name":"Wanda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324521);
