INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-lam-bac-gia', 'Những Kẻ Làm Bạc Giả', 'The Counterfeiters', 'https://phimimg.com/upload/vod/20231108-1/cc0980e6860350716dcc987e972eff21.jpg', 'https://phimimg.com/upload/vod/20231108-1/3e838ffaa88ec84b437a01902d5f3065.jpg', '<p>Phim dựa trên chuyện có thật về chiến dịch làm giả đồng bảng Anh của Đức quốc xã trong thế chiến thế giới thứ hai. Ngoài nội dung hấp dẫn (có lẽ chỉ đối với các bác sưu tầm tiền), phim quay cũng rất đẹp, nhạc nền hay.</p>', 'Full', 1, 'single', 'completed', 21, 2007, 'Vietsub', 'HD', 'Áo', 0, '[{"name":"Karl Markovics","avatar":""},{"name":"August Diehl","avatar":""},{"name":"Devid Striesow","avatar":""},{"name":"Martin Brambach","avatar":""},{"name":"August Zirner","avatar":""},{"name":"Veit Stübner","avatar":""},{"name":"Sebastian Urzendowsky","avatar":""},{"name":"Andreas Schmidt","avatar":""},{"name":"Tilo Prückner","avatar":""},{"name":"Lenn Kudrjawizki","avatar":""},{"name":"Marie Bäumer","avatar":""},{"name":"Arndt Schwering-Sohnrey","avatar":""},{"name":"Dolores Chaplin","avatar":""},{"name":"Heinz Schubert","avatar":""},{"name":"Holger Schober","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324521);
