INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-ke-lam-bac-gia', 'Những Kẻ Làm Bạc Giả', 'The Counterfeiters', 'những kẻ làm bạc giả the counterfeiters karl markovics august diehl devid striesow martin brambach august zirner veit stübner sebastian urzendowsky andreas schmidt tilo prückner lenn kudrjawizki marie bäumer arndt schwering-sohnrey dolores chaplin heinz schubert holger schober ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-trong-mong-2007', 'Người Tình Trong Mộng', 'Lars and the Real Girl', 'https://phimimg.com/upload/vod/20231107-1/d82a09c10333f296c5a5ecd033873588.jpg', 'https://phimimg.com/upload/vod/20231107-1/b435fcf0a0d47f056bd0dcca1f862a3b.jpg', '<p>Lars cực kỳ nhút nhát và không thể kết bạn hay giao lưu. Anh trai và chị dâu lo lắng cho anh nên khi thông báo anh có bạn gái quen trên mạng, họ vui mừng khôn xiết. Nhưng tân nương của Lars là một phụ nữ bằng nhựa có kích thước như người thật. Theo lời khuyên của bác sĩ, gia đình anh ta và những người còn lại trong cộng đồng đi cùng với sự ảo tưởng của anh ta.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Gosling","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Paul Schneider","avatar":""},{"name":"R.D. Reid","avatar":""},{"name":"Kelli Garner","avatar":""},{"name":"Nancy Beatty","avatar":""},{"name":"Doug Lennox","avatar":""},{"name":"Joe Bostick","avatar":""},{"name":"Liz Gordon","avatar":""},{"name":"Nicky Guadagni","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Karen Robinson","avatar":""},{"name":"Maxwell McCabe-Lokos","avatar":""},{"name":"Billy Parrott","avatar":""},{"name":"Sally Cahill","avatar":""},{"name":"Angela Vint","avatar":""},{"name":"Liisa Repo-Martel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324521);
