INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-tinh-trong-mong-2007', 'Người Tình Trong Mộng', 'Lars and the Real Girl', 'người tình trong mộng lars and the real girl ryan gosling emily mortimer paul schneider r.d. reid kelli garner nancy beatty doug lennox joe bostick liz gordon nicky guadagni patricia clarkson karen robinson maxwell mccabe-lokos billy parrott sally cahill angela vint liisa repo-martel ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuop-bien-vung-caribbean-noi-tan-cung-the-gioi', 'Cướp Biển Vùng Caribbean: Nơi Tận Cùng Thế Giới', 'Pirates of the Caribbean: At World''s End', 'https://phimimg.com/upload/vod/20231103-1/ba45100da060ae86e8438897805e72b4.jpg', 'https://phimimg.com/upload/vod/20231103-1/19bdbfef7f276ad0296f2332e1b0b499.jpg', '<p>Để cứu nguy cho cướp biển toàn thế giới khỏi nguy cơ bị xóa sổ hoàn toàn bởi Davy Jones cùng chiếc Flying Dutchman (lúc này đã trở thành tay sai của công ty Đông Ấn), Will Turner, Elizabeth Swann và thuyền trưởng Barbossa cùng nhau đi tìm đủ chín tên trùm cướp biển cùng đi tới tận cùng thế giới để giải cứu cho Jack và chống lại Davy Jones… Nổi bật lên trong phần 3 là cuộc chiến gay gắt giữa cái thiện và cái ác những phút sinh tử cận kề của các nhân vật góp phần tăng kịch tính cho phim. Nổi bật trong phần này là sự xuất hiện của hàng loạt nhân vật với quốc tịch khác nhau nổi bật trong đó là Châu Nhuận Phát đại diện của châu á. Cuối cùng là đại cảnh nơi tận cùng thế giới được xây dựng vô cùng đặc sắc.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Chow Yun-fat","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Jack Davenport","avatar":""},{"name":"Kevin McNally","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Keith Richards","avatar":""},{"name":"Lee Arenberg","avatar":""},{"name":"Mackenzie Crook","avatar":""},{"name":"Greg Ellis","avatar":""},{"name":"David Bailie","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324521);
