INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-mai-buoi-hoang-hon-2', 'Mãi Mãi Buổi Hoàng Hôn 2', 'Always: Sunset On Third Street 2', 'https://phimimg.com/upload/vod/20231103-1/4c07fe8f8ae2f83dcfa2852acad7f345.jpg', 'https://phimimg.com/upload/vod/20231103-1/5a40fc1df05de3f2b01f5a4ad8ad0ac7.jpg', '<p>Vẫn là con đường ngả màu trong ráng chiều, vẫn là những ngôi nhà gỗ nhạt màu vẻ xưa cũ, mọi thứ đơn giản chỉ là tiếp tục hơi thở từ tốn rất đặc trưng của Always 1. Câu chuyện phim giờ đi theo một hướng khác, tập trung hơn vào mối tình của nhà văn Chagawa và cô vũ công Hiromi, theo cách mạch lạc và đẹp đẽ.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Maki Horikita","avatar":""},{"name":"Hidetaka Yoshioka","avatar":""},{"name":"Shinichi Tsutsumi","avatar":""},{"name":"Kazuki Koshimizu","avatar":""},{"name":"Koyuki","avatar":""},{"name":"Tomokazu Miura","avatar":""},{"name":"Hiroko Yakushimaru","avatar":""},{"name":"Kenta Suga","avatar":""},{"name":"Masako Motai","avatar":""},{"name":"Fumiyo Kohinata","avatar":""},{"name":"Takaya Kamikawa","avatar":""},{"name":"Shigemitsu Ogi","avatar":""},{"name":"Kazue Fukiishi","avatar":""},{"name":"Shihori Kanjiya","avatar":""},{"name":"Ikkei Watanabe","avatar":""},{"name":"Magi","avatar":""},{"name":"Seiji Fuk","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
