INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tro-kinh-hoang', 'Nhà Trọ Kinh Hoàng', 'Vacancy', 'https://phimimg.com/upload/vod/20231106-1/4581bc6ecca0be311ccd8543f29a5c30.jpg', 'https://phimimg.com/upload/vod/20231106-1/787825e0ae1286aed90dc2a54106c9c2.jpg', '<p>Trong đêm tối, xe của David và Amy Foxs bị hỏng giữa đường họ buộc phải tìm nơi nghỉ chân qua đêm. Muốn chờ tới sáng để sửa xe, họ quyết định chọn một nhà trọ, do Mason - một người kỳ lạ quản lý. Khi họ tìm thấy vài cuốn phim ghi lại những cảnh máu me kinh dị trong từng căn phòng của nhà trọ mà họ đang ở và nhanh chóng nhận ra những cuốn phim họ đang xem không phải là những đoạn phim bình thường mà đó là những cảnh khủng khiếp do chính người từng trọ căn phòng này và họ chính là những nạn nhân kế tiếp của những người làm phim này trừ khi họ cùng nhau làm gì đó để cứu lấy tính mạng của chính mình, vượt qua đêm ác mộng dài nhất trong cuộc đời họ.</p>', 'Full', 1, 'single', 'completed', 12, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Beckinsale","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Frank Whaley","avatar":""},{"name":"Ethan Embry","avatar":""},{"name":"Scott G. Anderson","avatar":""},{"name":"Mark Casella","avatar":""},{"name":"David Doty","avatar":""},{"name":"Norm Compton","avatar":""},{"name":"Caryn Mower","avatar":""},{"name":"Meegan E. Godfrey","avatar":""},{"name":"Kym Stys","avatar":""},{"name":"Andrew Fiscella","avatar":""},{"name":"Dale Waddington","avatar":""},{"name":"Ernest Misko","avatar":""},{"name":"Bryan Ross","avatar":""},{"name":"Chevon Hicks","avatar":""},{"name":"Betsy Hammer","avatar":""},{"name":"Kevin Dun","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b9