INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('4-thang-3-tuan-va-2-ngay', '4 Tháng 3 Tuần Và 2 Ngày', '4 Months, 3 Weeks and 2 Days', 'https://phimimg.com/upload/vod/20231103-1/500188d0acdbb67784dc77ce43276f82.jpg', 'https://phimimg.com/upload/vod/20231103-1/c0a8da8d683aac3983636e49b9551855.jpg', '<p>Lấy bối cảnh những năm 80, nhưng sức tác động mạnh mẽ của 4 Months, 3 Weeks, and 2 Days dường như không bị thời gian giới hạn. Một phim ám ảnh và xuất sắc hàng đầu về chủ đề nhức nhối ở bất kì thời đại nào: Nạn nạo phá thai. Chuyện phim khá đơn giản, nhưng 4 Months, 3 Weeks, and 2 Days có được sự cuốn hút riêng đến từ cách kể: Hai ngày của hai cô gái, khi Olivie Otilia và Dragut Gabita tìm cách nạo thai cho Gabita tại một phòng khách sạn, căn phòng mà Otilia vất vả lắm mới thuê được. Gã đàn ông mà hai cô nhờ vả, tự gọi Bebe (“Bebe” tiếng Rumani nghĩa là “baby” (trẻ em), một kiểu mỉa mai của đạo diễn Cristian Mungiu: Một “đứa trẻ” chuyên giết những đứa trẻ), không chỉ muốn tiền, hắn còn muốn cả tình...</p>', 'Full', 1, 'single', 'completed', 20, 2007, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Anamaria Marinca","avatar":""},{"name":"Laura Vasiliu","avatar":""},{"name":"Vlad Ivanov","avatar":""},{"name":"Alexandru Potocean","avatar":""},{"name":"Luminița Gheorghiu","avatar":""},{"name":"Adi Cărăuleanu","avatar":""},{"name":"Liliana Mocanu","avatar":""},{"name":"Doru Ana","avatar":""},{"name":"Ion Sapdaru","avatar":""},{"name":"Cerasela Iosifescu","avatar":""},{"name":"Tania Popa","avatar":""},{"name":"Teodor Corban","avatar":""},{"name":"Eugenia Bosânceanu","avatar":""},{"name":"Mărioara Sterian","avatar":""},{"name":"Georgeta Păduraru Burdujan","avatar":""},{"name":"G","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
