INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('4-thang-3-tuan-va-2-ngay', '4 Tháng 3 Tuần Và 2 Ngày', '4 Months, 3 Weeks and 2 Days', '4 tháng 3 tuần và 2 ngày 4 months, 3 weeks and 2 days anamaria marinca laura vasiliu vlad ivanov alexandru potocean luminița gheorghiu adi cărăuleanu liliana mocanu doru ana ion sapdaru cerasela iosifescu tania popa teodor corban eugenia bosânceanu mărioara sterian georgeta păduraru burdujan g ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-xe-chet-choc', 'Cỗ Xe Chết Chóc', 'Death Proof', 'https://phimimg.com/upload/vod/20231110-1/50c02811fc5cc4c5a3c5e52edf386d2f.jpg', 'https://phimimg.com/upload/vod/20231110-1/16ff24ae122a29bbd73145be0a056111.jpg', '<p>Stuntman Mike từng là tay đua xe mạo hiểm ở Hollywood. Mike thường lấy phụ nữ làm mục tiêu để... giết chết họ với chiếc xe &quot;thử thách chết người&quot; của anh. Ở màn I, Mike xuất đầu lộ diện tại Austin, Texas. Mục tiêu là nhóm phụ nữ mà anh ta biết khá rõ. Nhóm này gồm Jungle Julia, một cô gái nghiện thuốc và dễ dãi, một người mẫu thời trang kiêm DJ đài truyền thanh; Arlene, người mẫu; Shanna, cô gái hư hỏng và Pam, cô nàng lập dị. Pam luôn cố gắng khiến Mike chú ý đến cô mà không biết được mình đang rơi vào một tay căm ghét đàn bà rất nguy hiểm. Ở màn II, Mike xuất hiện tại Tennessee, nơi anh vô tình chọn được một nhóm phụ nữ khác, những người làm trong xưởng phim. Mike lặng lẽ theo dõi họ. Abernathy là chuyên viên trang điểm và người ...</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kurt Russell","avatar":""},{"name":"Zoë Bell","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Vanessa Ferlito","avatar":""},{"name":"Sydney Tamiia Poitier","avatar":""},{"name":"Tracie Thoms","avatar":""},{"name":"Rose McGowan","avatar":""},{"name":"Jordan Ladd","avatar":""},{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Quentin Tarantino","avatar":""},{"name":"Marcy Harriell","avatar":""},{"name":"Eli Roth","avatar":""},{"name":"Omar Doom","avatar":""},{"name":"Michael Bacall","avatar":""},{"name":"Monica Staggs","avatar":""},{"name":"Jonathan Loughran","avatar":""},{"name":"Mic","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324521);
