INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-anh-hung-ca', 'Thiên Anh Hùng Ca', 'Epic Movie', 'https://phimimg.com/upload/vod/20231103-1/fa7e83311d543c502934ba5e56ba71d3.jpg', 'https://phimimg.com/upload/vod/20231103-1/37b1f4ffecaf057cb1b985fa8f6a4559.jpg', '<p>Bạn nghĩ sao khi tất cả các nhân vật xuất hiện trong mùa phim 2006 như: cô nàng Paris Hilton đỏng đảnh, gã thuyền trưởng Jack Swallow không-được-bình-thường, X-Men, &quot;chú&quot; bé phù thủy Harry Porter, thầy tu đô vật Narcho, Bond Girls...cùng tham gia vào 1 cuộc chiến giữa cái Thiện và cái Ác. Trong đó, đứng đầu phe Ác là my-super-ex girlfriend....</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kal Penn","avatar":""},{"name":"Adam Campbell","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Jayma Mays","avatar":""},{"name":"Faune Chambers","avatar":""},{"name":"Crispin Glover","avatar":""},{"name":"Tony Cox","avatar":""},{"name":"Héctor Jiménez","avatar":""},{"name":"Darrell Hammond","avatar":""},{"name":"Carmen Electra","avatar":""},{"name":"David Carradine","avatar":""},{"name":"Fred Willard","avatar":""},{"name":"Kevin McDonald","avatar":""},{"name":"George Alvarez","avatar":""},{"name":"Crista Flanagan","avatar":""},{"name":"Dana Seltzer","avatar":""},{"name":"Dane Farwell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324521);
