INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-dai-nan-kinh-hoang', 'Mười Đại Nạn Kinh Hoàng', 'The Reaping', 'https://phimimg.com/upload/vod/20231102-1/892a2412bc41977587801e0fb8057ffd.jpg', 'https://phimimg.com/upload/vod/20231102-1/07ccb5cfa0cb3732ba93ec0a599fd61c.jpg', '<p>Từng là một con chiên ngoan đạo, Katherine đã bị mất lòng tin vào Chúa khi những người thân của mình bị chết trong một tai nạn thảm khốc. Nhưng rồi khi một thành phố nhỏ ở Louisiana xảy ra những hiện tượng giống hệt như 10 đại nạn được miêu tả trong kinh Thánh thì Katherine mới nhận ra rằng có những điều nếu không có lòng tin thì sẽ chẳng làm được gì.</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hilary Swank","avatar":""},{"name":"David Morrissey","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"AnnaSophia Robb","avatar":""},{"name":"Stephen Rea","avatar":""},{"name":"William Ragsdale","avatar":""},{"name":"John McConnell","avatar":""},{"name":"David Jensen","avatar":""},{"name":"Yvonne Landry","avatar":""},{"name":"Samuel Garland","avatar":""},{"name":"Myles Cleveland","avatar":""},{"name":"Andrea Frankle","avatar":""},{"name":"Mark Lynch","avatar":""},{"name":"Stuart Greer","avatar":""},{"name":"Lara Grice","avatar":""},{"name":"Cody Sanders","avatar":""},{"name":"Burgess Jenkins","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324521);
