INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-thoi-tho-ta', 'Tình Yêu Thời Thổ Tả', 'Love in the Time of Cholera', 'https://phimimg.com/upload/vod/20231102-1/8f276d5d50f6a9393fb1e4c8dc32a88b.jpg', 'https://phimimg.com/upload/vod/20231102-1/6cd4128331faedf91b15af1029df4ab5.jpg', '<p>Câu chuyện lấy bối cảnh của cảng biển Caribbean những năm 1880, vào thời mà đại dịch thổ tả đã hạ gục biết bao người. Có anh chàng điện tín viên Florentino Ariza đã gặp và yêu say đắm nàng Fermina Daza, thiếu nữ có dáng đi kiêu hãnh của một loài “hoẵng cái”. Hai người cùng bốc cháy trong tình yêu qua những cánh thư và những tờ điện tín, nhưng cuối cùng cô gái đã phải làm một cuộc “viễn du để tìm quên lãng” vì cha cô đã phát hiện ra mối tình vụng trộm giữa 2 người…</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Javier Bardem","avatar":""},{"name":"Unax Ugalde","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Catalina Sandino Moreno","avatar":""},{"name":"Héctor Elizondo","avatar":""},{"name":"Liev Schreiber","avatar":""},{"name":"Fernanda Montenegro","avatar":""},{"name":"Laura Harring","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Ana Claudia Talancón","avatar":""},{"name":"Alicia Borrachero","avatar":""},{"name":"Marcela Mar","avatar":""},{"name":"Angie Cepeda","avatar":""},{"name":"Giovanna Mezzogiorno","avatar":""},{"name":"Rubria Negr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324521);
