INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trai-ong-gia-noel', 'Anh Trai Ông Già Noel', 'Fred Claus', 'https://phimimg.com/upload/vod/20231101-1/5981101bbf0fa62fc95ea4e09d56c34f.jpg', 'https://phimimg.com/upload/vod/20231101-1/cd9647be93b33790d6a2c57e651fe565.jpg', '<p>Suốt thời thơ ấu, Fred Claus luôn bị lu mờ trước cậu em trai thánh thiện tên Nick - người sau này trở thành Ông già Noel. Nhiều năm sau, khi cần một số tiền lớn để làm ăn, Fred buộc phải gọi cho Nick để nhờ giúp đỡ. Nick nhận lời với điều kiện Fred phải đến giúp vài ngày nhân dịp Giáng sinh bận rộn. Công việc của Fred là phải xem xét từng trường hợp cụ thể để quyết định xem đó là trẻ ngoan hay trẻ hư - việc mà từ trước đến giờ Fred chưa từng trải nghiệm.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vince Vaughn","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"John Michael Higgins","avatar":""},{"name":"Miranda Richardson","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Trevor Peacock","avatar":""},{"name":"Ludacris","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Jeremy Swift","avatar":""},{"name":"Elizabeth Berrington","avatar":""},{"name":"Kevin Spacey","avatar":""},{"name":"Rio Hackford","avatar":""},{"name":"Bobb''e J. Thompson","avatar":""},{"name":"Allan Corduner","avatar":""},{"name":"Jordon Hu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
