INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-than-tien-o-new-york', 'Chuyện Thần Tiên Ở New York', 'Enchanted', 'https://phimimg.com/upload/vod/20231101-1/489a3225e7530cd909a1d6449d358727.jpg', 'https://phimimg.com/upload/vod/20231101-1/675b25eb8d750420fd3aa1d75adbc7b1.jpg', '<p>Chuyện thần tiên ở New York: Thật khó để xếp Enchanted vào thể loại phim nhất định nào đó. Theo lời đạo diễn Kevin Lima thì phim được xếp vào thể loại nào cũng đúng. Điều đó chính là thử thách lớn nhất của ông trong sự nghiệp đạo diễn – tổng hợp nhiều thể loại và đồng hóa trong một bộ phim. Nào là hoạt hình, lãng mạn, hài, có một chút phiêu lưu mạo hiểm và có cả thể loại phim ca nhạc nữa. Đạo diễn phải cân bằng tất cả để đem đến cho khán giả một bộ phim cổ tích thời hiện đại hấp dẫn. Có ai theo dõi bản xếp hạng Top 10 phim mấy tuần nay thì sẽ thấy bộ phim cổ tích theo mô típ cũ kỹ &quot;Enchanted&quot; luôn có mặt trong Top 3 phim ăn khách nhất liên tục.Walt Disney đúng là tài thật, luôn nắm tâm lý khán giả, Enchanted thành công vang dội chứng tỏ con ...</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amy Adams","avatar":""},{"name":"Patrick Dempsey","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Idina Menzel","avatar":""},{"name":"Rachel Covey","avatar":""},{"name":"Susan Sarandon","avatar":""},{"name":"Julie Andrews","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Kevin Lima","avatar":""},{"name":"Emma Rose Lima","avatar":""},{"name":"Teala Dunn","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Courtney Williams","avatar":""},{"name":"William Huntley","avatar":""},{"name":"Samantha Ivers","avatar":""},{"name":"Elizabeth Mathi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324521);
