INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-boi-samurai', 'Cao Bồi Samurai', 'Sukiyaki Western Django', 'https://phimimg.com/upload/vod/20231101-1/1d7e7f8ab59abb5c6bf15d7bd7f1ea78.jpg', 'https://phimimg.com/upload/vod/20231101-1/38a4298f4f7990e401c9054a49ca0a7a.jpg', '<p>2 thị tộc: thị tộc trắng Genji được dẫn dắt bởi Yoshitsune và thị tộc đỏ Heike do Kiyomori cầm đầu cùng lao vào cuộc tìm kiếm kho báu huyền thoại được chôn giấu tại một thị trấn miền núi nghèo khó. Một ngày nọ, một tay súng cô độc với tài bắn súng thiện nghệ cùng một vết thương trong lòng tình cờ xuất hiện tại thị trấn nọ. Cả hai thị tộc đều dùng hết mọi cách dụ dỗ, mua chuộc và kể cả hăm dọa với hy vọng kéo được tay súng kia về phía mình nhằm giành được những lợi thế nhất định trong cuộc tìm kiếm. Những trò dơ bẩn, sự phản bội, dục vọng điên cuồng và những xung đột tình cảm kịch tính đan xem vào nhau trong tác phẩm theo phong cách Cao bồi kiểu Nhật của đạo diễn nổi tiếng Takashi Miike...</p>', 'Full', 1, 'single', 'completed', 22, 2007, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hideaki Ito","avatar":""},{"name":"Koichi Sato","avatar":""},{"name":"Yûsuke Iseya","avatar":""},{"name":"Kaori Momoi","avatar":""},{"name":"Teruyuki Kagawa","avatar":""},{"name":"Takaaki Ishibashi","avatar":""},{"name":"Masanobu Ando","avatar":""},{"name":"Yoshino Kimura","avatar":""},{"name":"Masato Sakai","avatar":""},{"name":"Shun Oguri","avatar":""},{"name":"Renji Ishibashi","avatar":""},{"name":"Quentin Tarantino","avatar":""},{"name":"Shingo Katori","avatar":""},{"name":"Yutaka Matsushige","avatar":""},{"name":"Toshiyuki Nishida","avatar":""},{"name":"Yoji Tanaka","avatar":""},{"name":"Hideaki","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324521);
