INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-com', 'Siêu Cớm', 'Hot Fuzz', 'https://phimimg.com/upload/vod/20231030-1/b7c991ddc0508008a9930eb7fa9117c0.jpg', 'https://phimimg.com/upload/vod/20231030-1/257e457954bf4e4ff46b0c25a1dc01cd.jpg', '<p>Nicholas Angel là một cảnh sát giỏi nhất Luân Đôn từ trước đến nay với kỷ lục các vụ bắt giữ lên đến 400% nhiều hơn bất kỳ đồng nghiệp nào! Giỏi đến thế thì bị ghen ghét là chuyện thường nên các sếp đã ký quyết định đày ải Nicholas đến ngôi làng Sandford bình yên. Tại đây, anh gặp đồng đội mê ăn Danny Butterman vốn là con của cảnh sát trưởng đáng kính Frank Butterman. &nbsp;Danny là một người ghiền phim hành động do đó tin tưởng người đồng nghiệp mới có thể sẽ đưa anh vào những cuộc phiêu lưu, cơ hội để tham gia các trận đấu súng và những pha rượt đuổi nghẹt thở từng ao ướt. Tuy nhiên, Nicholas sớm tẩy não cái ý tưởng trẻ con của Danny. Chẳng bao lâu sau khi Nicholas phát hiện ngôi làng Sandford không yên ổn như mọi người vẫn tưởng sau một loạt tai nạn chấn động. Anh biết rằng mình sắp phải ra tay chấn chỉnh kỷ cương trong khi Danny thì vui mừng với giấc mơ sắp trở thành hiện thật. Đã đến lúc bộ đôi Nicholas - Danny thực hiện sứ mệnh đem lại sự bình yên cho Sandford...</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Simon Pegg","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Paddy Considine","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Kevin Eldon","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Bill Bailey","avatar":""},{"name":"Karl Johnson","avatar":""},{"name":"Timothy Dalton","avatar":""},{"name":"Edward Woodward","avatar":""},{"name":"Billie Whitelaw","avatar":""},{"name":"Stuart Wilson","avatar":""},{"name":"Paul Freeman","avatar":""},{"name":"Rory McCann","avatar":""},{"name":"Kenneth Cranham","avatar":""},{"name":"Maria Charles","avatar":""},{"name":"Peter Wi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324521);
