INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-com', 'Siêu Cớm', 'Hot Fuzz', 'siêu cớm hot fuzz simon pegg nick frost jim broadbent paddy considine rafe spall kevin eldon olivia colman bill bailey karl johnson timothy dalton edward woodward billie whitelaw stuart wilson paul freeman rory mccann kenneth cranham maria charles peter wi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-mo-2', 'Lò Mổ 2', 'Hostel: Part II', 'https://phimimg.com/upload/vod/20231029-1/e9cbfa5273107db5261d5c731657c99e.jpg', 'https://phimimg.com/upload/vod/20231029-1/3681e8ed809d5d554ae75126e47b87f4.jpg', '<p>Miền đất dữ Slovakia vẫn luôn quyến rũ trong mắt các sinh viên Mỹ. Trên chuyến tàu hướng đến Đông Âu, Beth, Loa và Whitney không thể cưỡng lại sức hấp dẫn của những suối nước nóng thiên nhiên đẹp như tranh vẽ ở Slovakia từ lời kể của Axelle, cô bạn học xinh đẹp cùng lớp. Họ quyết định dừng chân thưởng ngoạn Slovakia rồi mới tiếp tục lên đường, và điểm dừng của họ là một… Hostel. Ngâm mình trong dòng nước ấm áp mờ mờ hơi sương giữa một khung cảnh thần tiên thơ mộng, gặp gỡ những chàng trai mạnh mẽ và quyến rũ. Các thiếu nữ lâng lâng như trên mây, Thiên Đàng chính là nơi đây. Chỉ có Beth luôn cảm thấy bất an, một nỗi sợ hãi cứ len lõi trong tâm hồn nàng giữa vùng đất Slovakia xa lạ.</p>', 'Full', 1, 'single', 'completed', 22, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lauren German","avatar":""},{"name":"Heather Matarazzo","avatar":""},{"name":"Bijou Phillips","avatar":""},{"name":"Vera Jordanova","avatar":""},{"name":"Jay Hernandez","avatar":""},{"name":"Roger Bart","avatar":""},{"name":"Petr Vančura","avatar":""},{"name":"Richard Burgi","avatar":""},{"name":"Jordan Ladd","avatar":""},{"name":"Stanislav Yanevski","avatar":""},{"name":"Zuzana Geislerová","avatar":""},{"name":"Milan Kňažko","avatar":""},{"name":"Roman Janečka","avatar":""},{"name":"Davide Dominici","avatar":""},{"name":"Edwige Fenech","avatar":""},{"name":"Luc Merenda","avatar":""},{"name":"Susanna","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324521);
