INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-tuong-sieu-nhien', 'Hiện Tượng Siêu Nhiên', 'Paranormal Activity', 'https://phimimg.com/upload/vod/20231029-1/d75c34481155a392dec24dc31a25713c.jpg', 'https://phimimg.com/upload/vod/20231029-1/ffaf8f6d9e896896ecc8177b4fd70a25.jpg', '<p>Sau khi một cặp vợ chồng trẻ thuộc tầng lớp trung lưu chuyển đến một nơi có vẻ giống như một ngôi nhà ngoại ô điển hình, họ ngày càng trở nên lo lắng bởi sự hiện diện có thể là ma quỷ hoặc không nhưng chắc chắn là hoạt động tích cực nhất vào lúc nửa đêm. Tiếp theo là năm phần đáng sợ trong loạt phim, đây là cảnh gây sốc ban đầu được tìm thấy đã bắt đầu tất cả.</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katie Featherston","avatar":""},{"name":"Micah Sloat","avatar":""},{"name":"Mark Fredrichs","avatar":""},{"name":"Amber Armstrong","avatar":""},{"name":"Ashley Palmer","avatar":""},{"name":"Crystal Cartwright","avatar":""},{"name":"Spencer Marks","avatar":""},{"name":"Randy McDowell","avatar":""},{"name":"James Piper","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324521);
