INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-se-phai-do', 'Máu Sẽ Phải Đổ', 'There Will Be Blood', 'https://phimimg.com/upload/vod/20231029-1/226883d34e1e51209cbc571e4c428c44.jpg', 'https://phimimg.com/upload/vod/20231029-1/0f006ee5ddc073d4633fa1a08769b09b.jpg', '<p>Bộ phim dựa trên tiểu thuyết Oil (Dầu mỏ) nổi tiếng của nhà văn Upton Sinclair viết năm năm 1927 kể về cuộc đời của tay buôn dầu mỏ Daniel Plainview, cuộc đời ấy đã thay đổi do những tham vọng và để đạt được giấc mơ Mỹ, bàn tay anh bắt đầu nhúng chàm... Sẽ có Tham lam. Sẽ Có Báo Thù.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Day-Lewis","avatar":""},{"name":"Paul Dano","avatar":""},{"name":"Kevin J. O''Connor","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Dillon Freasier","avatar":""},{"name":"Hope Elizabeth Reeves","avatar":""},{"name":"Colleen Foy","avatar":""},{"name":"Barry Del Sherman","avatar":""},{"name":"David Willis","avatar":""},{"name":"Hans Howes","avatar":""},{"name":"Sydney McCallister","avatar":""},{"name":"Paul F. Tompkins","avatar":""},{"name":"Kevin Breznahan","avatar":""},{"name":"Jim Meskimen","avatar":""},{"name":"Erica Sullivan","avatar":""},{"name":"Randa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
