INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mau-se-phai-do', 'Máu Sẽ Phải Đổ', 'There Will Be Blood', 'máu sẽ phải đổ there will be blood daniel day-lewis paul dano kevin j. o''connor ciarán hinds dillon freasier hope elizabeth reeves colleen foy barry del sherman david willis hans howes sydney mccallister paul f. tompkins kevin breznahan jim meskimen erica sullivan randa ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-den-yuma', 'Chuyến Tàu Đến Yuma', '3:10 to Yuma', 'https://phimimg.com/upload/vod/20231029-1/7fb401f884c976a0c474e0571b46605a.jpg', 'https://phimimg.com/upload/vod/20231029-1/ff20478cc0982ed5ae61c2b9cefeabbf.jpg', '<p>Dan Evans để lại một chân ở chiến trường trong cuộc nội chiến Mỹ. Anh đã tới bang Arizona để kiếm sống bằng nghề chăn nuôi gia súc. Tình trạng hạn hán liên miên cùng với sự chèn ép của chủ trang trại bên cạnh đẩy gia đình anh vào cảnh nợ nần triền miên. Tình trạng khốn quẫn lên tới đỉnh điểm khi những kẻ lạ mặt đột nhập vào trang trại của Dan lúc nửa đêm và đốt cháy nhà kho. Đến sáng hôm sau thì gia đình anh hầu như chẳng còn gì. Trong lúc rong ruổi tới thị trấn tìm việc làm, Dan và hai cậu con trai chứng kiến một vụ cướp xe chở tiền vô cùng táo bạo của nhóm cướp do Ben Wade và Charlie Price cầm đầu. Bất chấp sự phản đối của Charlie, Ben quyết định không bắn 3 nhân chứng sau khi Dan hứa sẽ im lặng.</p>', 'Full', 1, 'single', 'completed', 23, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Christian Bale","avatar":""},{"name":"Peter Fonda","avatar":""},{"name":"Gretchen Mol","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Dallas Roberts","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Vinessa Shaw","avatar":""},{"name":"Logan Lerman","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Lennie Loftin","avatar":""},{"name":"Johnny Whitworth","avatar":""},{"name":"Luce Rains","avatar":""},{"name":"Rio Alexander","avatar":""},{"name":"Shawn Howell","avatar":""},{"name":"Pat Ricotti","avatar":""},{"name":"Ramon Frank","avatar":""},{"name":"Deryle J. Lujan","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324521);
