INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bat-tu', 'Người Bất Tử', 'The Man from Earth', 'https://phimimg.com/upload/vod/20231030-1/3526cf343484f8bd529d7429fbc2e273.jpg', 'https://phimimg.com/upload/vod/20231030-1/da4a53c69a3a41aadc36c7dd66941fa0.jpg', '<p>Bộ phim The Man from Earth (Người Bất Tử) kể về bữa tiệc chia tay của Giáo sư John Oldman trước khi quyết định về hưu, ông đã tiết lộ cho những người bạn của mình, ông là một người bất tử đã sống trên trái đất suốt 14.000 năm. Ông kể ông đã từng đi thuyền với Ma-gen-lăng, đã gặp đức Phật, đã trải qua tất cả các biến cố của lịch sử, và đỉnh điểm, thật ra ông chính là...</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Lee Smith","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"John Billingsley","avatar":""},{"name":"Ellen Crawford","avatar":""},{"name":"Annika Peterson","avatar":""},{"name":"Alexis Thorpe","avatar":""},{"name":"William Katt","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"Steven Littles","avatar":""},{"name":"Chase Sprague","avatar":""},{"name":"Robbie Bryan","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324521);
