INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-la-ban-vang', 'Chiếc La Bàn Vàng', 'The Golden Compass', 'https://phimimg.com/upload/vod/20231026-1/44be8119188e0afb969086540200b615.jpg', 'https://phimimg.com/upload/vod/20231026-1/3e2dcf588ac8cbdae3c23449053a6a31.jpg', '<p>Cô bé mồ côi từ nhỏ Lyra đánh đổi cuộc sống vô tư trong khuôn viên Đại học Jordan của mình để có một cuộc phiêu lưu ở thế giới khác, nơi phương Bắc xa xôi.</p>', 'Full', 1, 'single', 'completed', 16, 2007, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Daniel Craig","avatar":""},{"name":"Dakota Blue Richards","avatar":""},{"name":"Ben Walker","avatar":""},{"name":"Freddie Highmore","avatar":""},{"name":"Ian McKellen","avatar":""},{"name":"Eva Green","avatar":""},{"name":"Jim Carter","avatar":""},{"name":"Tom Courtenay","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Sam Elliott","avatar":""},{"name":"Christopher Lee","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Edward de Souza","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Jack Shephe","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324521);
