INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('28-tuan-sau', '28 Tuần Sau', '28 Weeks Later', 'https://phimimg.com/upload/vod/20231026-1/2937bed8c0b59c20d8cf8df32515c534.jpg', 'https://phimimg.com/upload/vod/20231026-1/64f65dcbfa1a35fe41541141b21bfd9c.jpg', '<p>28 tuần đã trôi qua kể từ ngày xảy ra sự kiện virus lan tràn khắp nước Anh, quật ngã những người dân đảo sương mù và biến họ thành những xác chết khát máu, dưới sự giúp sức mạnh mẽ từ quân đội Mỹ, giới cầm quyền Anh thở phào nhẹ nhõm tuyên bố nạn dịch đã được kiểm soát và tiêu diệt, người dân lại có thể trở về mái nhà của họ sau những tháng ngày khủng khiếp khi để sống sót họ phải giết ngay chính những người thân yêu của mình và cả việc che giấu mầm bệnh virus vẫn còn đang phát triển và biến đổi mạnh mẽ hơn trong cơ thể họ...</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Robert Carlyle","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Jeremy Renner","avatar":""},{"name":"Harold Perrineau","avatar":""},{"name":"Catherine McCormack","avatar":""},{"name":"Imogen Poots","avatar":""},{"name":"Mackintosh Muggleton","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Amanda Walker","avatar":""},{"name":"Shahid Ahmed","avatar":""},{"name":"Garfield Morgan","avatar":""},{"name":"Emily Beecham","avatar":""},{"name":"Jordan El-Balawi","avatar":""},{"name":"Meghan Popiel","avatar":""},{"name":"Stewart Alexander","avatar":""},{"name":"Philip Bulco","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849