INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-vang-phieu-luu-ky', 'Ong Vàng Phiêu Lưu Ký', 'Bee Movie', 'ong vàng phiêu lưu ký bee movie jerry seinfeld renée zellweger matthew broderick patrick warburton john goodman chris rock kathy bates barry levinson larry king ray liotta sting oprah winfrey larry miller megan mullally rip torn michael richards mario joyner jim cumming ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('beowulf-ac-quy-long-hanh', 'Beowulf: Ác Quỷ Lộng Hành', 'Beowulf', 'https://phimimg.com/upload/vod/20231026-1/13c0eb9a799d0562350e8626e659648d.jpg', 'https://phimimg.com/upload/vod/20231026-1/0d3d8b52b8b5b93acc58c003ed1b6382.jpg', '<p>Chuyện xảy ra tại đế quốc Đan Mạch cổ xưa. Đất nước của vua Hrothgar (Anthony Hopkins) bị quấy nhiễu bởi Grendel, một con quái vật hung hãn. Người anh hùng Beowulf (Ray Winstone) cùng 14 chiến hữu người Viking quả cảm xuất hiện và tiêu trừ nó. Nhưng Beowulf phải đối mặt với một thử thách mà nhiều năm trước vua Hrothgar đã thất bại và đang phải trả giá. Beowulf phải chiến thắng sự trả thù của mẹ của quái vật Grendel (Angeline Jolie) - một người đàn bà cực kỳ quyến rũ với cái đuôi rắn kỳ dị, chính là thử thách đáng sợ nhất...</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ray Winstone","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Crispin Glover","avatar":""},{"name":"Alison Lohman","avatar":""},{"name":"Paul Baker","avatar":""},{"name":"John Bilezikjian","avatar":""},{"name":"Rod D. Harbour","avatar":""},{"name":"Brice Martinet","avatar":""},{"name":"Sonje Fortag","avatar":""},{"name":"Sharisse Baker-Bernard","avatar":""},{"name":"Charlotte Salt","avatar":""},{"name":"Julene Renee","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324521);
