INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-lem-iii-quay-nguoc-thoi-gian', 'Lọ Lem III: Quay Ngược Thời Gian', 'Cinderella III: A Twist in Time', 'https://phimimg.com/upload/vod/20231025-1/51e4a5e0c684f8e758d9bc623194a0aa.jpg', 'https://phimimg.com/upload/vod/20231025-1/06140d9fe633c271a1ea47de636747e9.jpg', '<p>Khi mẹ kế độc ác của Cinderella chiếm đoạt được cây đũa phép từ bà tiên đỡ đầu và cho quay ngược vòng quay thời gian, Cinderella phải cố gắng tìm được hoàng tử và phá vỡ lời nguyền mới mà bà mẹ kế đã ếm lên chàng. Cùng với sự giúp đỡ của Gus, Jaq và tất cả những nhân vật đáng yêu sẽ trở lại trong tập phim thú vị và mới mẻ, pha trộn sự hài hước, hóm hỉnh của một trong những bộ phim nổi tiếng nhất thời đại.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Hale","avatar":""},{"name":"Christopher Daniel Barnes","avatar":""},{"name":"Susanne Blakeslee","avatar":""},{"name":"Tress MacNeille","avatar":""},{"name":"Russi Taylor","avatar":""},{"name":"Andre Stojka","avatar":""},{"name":"Holland Taylor","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Corey Burton","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Tami Tappan Damiano","avatar":""},{"name":"Jessica Gee-George","avatar":""},{"name":"Lesli Margherita","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324522);
