INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-doi-co-mat-2', 'Ngọn Đồi Có Mắt 2', 'The Hills Have Eyes 2', 'https://phimimg.com/upload/vod/20231025-1/f8f17e4782e5538c1e1f0d869c854bd8.jpg', 'https://phimimg.com/upload/vod/20231025-1/cba564d490e0ab11ad5835d79b58205d.jpg', '<p>Giống như phần 1, Ngọn đồi có mắt 2 là hành trình đầy nguy hiểm vượt qua vùng sa mạc nơi những sinh vật quái dị, ghê rợn luôn sẵn sàng xẻ thịt con mồi ra từng mảnh. Câu chuyện lần này xoay quanh chiến dịch giải cứu nhóm nhà khoa học bị mắc kẹt ở vùng căn cứ quân sự bí mật không được nhắc tên giữa hoang mạc Nevada của đội lính đặc nhiệm đầy tinh nhuệ. Liệu họ có hoàn thành nhiệm vụ, khi thứ đầu tiên họ gặp phải là một xác sống giữa vũng máu đầy bi thảm...</p>', 'Full', 1, 'single', 'completed', 15, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael McMillian","avatar":""},{"name":"Jessica Stroup","avatar":""},{"name":"Jacob Vargas","avatar":""},{"name":"Flex Alexander","avatar":""},{"name":"Michael Bailey Smith","avatar":""},{"name":"Lee Thompson Young","avatar":""},{"name":"Daniella Alonso","avatar":""},{"name":"Archie Kao","avatar":""},{"name":"Jay Acovone","avatar":""},{"name":"Jeff Kober","avatar":""},{"name":"David Reynolds","avatar":""},{"name":"Philip Pavel","avatar":""},{"name":"Eric Edelstein","avatar":""},{"name":"Joseph Beddelem","avatar":""},{"name":"Ben Crowley","avatar":""},{"name":"Reshad Strik","avatar":""},{"name":"Tyre","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324522);
