INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-dau-thu-thach-4', 'Đương Đầu Thử Thách 4', 'Live Free or Die Hard', 'https://phimimg.com/upload/vod/20231023-1/afc10f4752b1c3e2c6d61e7c047a6a9a.jpg', 'https://phimimg.com/upload/vod/20231023-1/84c87c0c93565f96f82cb07009157028.jpg', '<p>Hệ thống máy tính ở FBI bị xâm nhập, Giám Đốc FBI quyết định bắt hết những hackers bị tình nghi. Trên đường áp giải tội phạm, McClane vô tình khám phá ra âm mưu khủng bố của Thomas Gabriel.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Maggie Q","avatar":""},{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Kevin Smith","avatar":""},{"name":"Christina Chang","avatar":""},{"name":"Sung Kang","avatar":""},{"name":"Zeljko Ivanek","avatar":""},{"name":"Yorgo Constantine","avatar":""},{"name":"Jonathan Sadowski","avatar":""},{"name":"Andrew Friedman","avatar":""},{"name":"Cyril Raffaelli","avatar":""},{"name":"Chris Palermo","avatar":""},{"name":"Jake McDorman","avatar":""},{"name":"Mat","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324522);
