INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-suong-mu', 'Quái Vật Sương Mù', 'The Mist', 'https://phimimg.com/upload/vod/20231023-1/8330054fc108abd4abaf897c9e638c90.jpg', 'https://phimimg.com/upload/vod/20231023-1/8b205cd305365a8062356e0a5dce9586.jpg', '<p>David và con trai của mình bị mắc kẹt trong một siêu thị cùng với một số người dân khác trong thị trấn, khi một màn sương mù đột ngột bao trùm toàn bộ thành phố, mang theo những sinh vật khát máu có thể nuốt chửng bất cứ ai trên đường đi của họ.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Thomas Jane","avatar":""},{"name":"Laurie Holden","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"Andre Braugher","avatar":""},{"name":"William Sadler","avatar":""},{"name":"Jeffrey DeMunn","avatar":""},{"name":"Samuel Witwer","avatar":""},{"name":"Chris Owen","avatar":""},{"name":"Alexa Davalos","avatar":""},{"name":"David Jensen","avatar":""},{"name":"Frances Sternhagen","avatar":""},{"name":"Nathan Gamble","avatar":""},{"name":"Robert C. Treveiler","avatar":""},{"name":"Melissa McBride","avatar":""},{"name":"Andy Stahl","avatar":""},{"name":"Buck Ta","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324522);
