INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-ro-tuong-lai', 'Thấy Rõ Tương Lai', 'Next', 'https://phimimg.com/upload/vod/20231022-1/bc6fac761f526608815adf7baa3dfd02.jpg', 'https://phimimg.com/upload/vod/20231022-1/bf3d889284dba148b4dfb015f1e851a4.jpg', '<p>Cris Johnson, nhà ảo thuật đến từ Las Vegas với một khả năng đặc biệt là nhìn thấy tương lai trước 2 phút. Chán nản trước sự quan tâm đặc biệt, những cuộc kiểm tra của chính phủ và các tổ chức y tế trước sức mạnh đặc biệt này, Cris đổi tên và ẩn danh, biểu diễn những trò ảo thuật rẻ tiền và chơi bài để sống. Nhưng khi một nhóm khủng bố đe doạ cho phát nổ thiết bị hạt nhân ở Los Angeles, đặc vụ chính phủ Callie Ferris phải dùng tất cả những mánh khoé để bắt Cris và thuyết phục anh giúp đỡ ngăn chặn thảm hoạ đang đến.</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Jessica Biel","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Jim Beaver","avatar":""},{"name":"Tory Kittles","avatar":""},{"name":"Peter Falk","avatar":""},{"name":"Enzo Cilenti","avatar":""},{"name":"José Zúñiga","avatar":""},{"name":"Jason Butler Harner","avatar":""},{"name":"Sergej Trifunović","avatar":""},{"name":"Nicolas Pajon","avatar":""},{"name":"Michael Trucco","avatar":""},{"name":"Charles Rahi Chun","avatar":""},{"name":"Patricia Prata","avatar":""},{"name":"Jon Hughes","avatar":""},{"name":"Jack Ong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324522);
