INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-sat-nhan-hoan-hao', 'Tên Sát Nhân Hoàn Hảo', 'Zodiac', 'https://phimimg.com/upload/vod/20231022-1/9a7c4d24d70d48c2d78e4cbb51117303.jpg', 'https://phimimg.com/upload/vod/20231022-1/9ac8d8c3dc69ba5cda341cb4174ad891.jpg', '<p>Robert Graysmith là một hoạ sĩ hoạt hình làm việc cho công ty San Francisco Chronicle. Lối sống kỳ quặc của anh luôn gây khó chịu cho Paul Avery, một phóng viên thường bị thói quen uống rượu của mình gây cản trở công việc.&nbsp; Tuy vậy, cả hai lại trở thành bạn bè nhờ có chung một sự quan tâm: tên giết người Zodiac.Graysmith dần bị ám ảnh bởi vụ án trong khi cuộc sống của Avery chìm đắm trong men rượu để tìm quên. Trình độ nghiệp dư của Graysmith dẫn anh bước chung trên con đường của David Toschi, một thanh tra cảnh sát đã thất bại trong việc bắt tên sát nhân; Sherwood Morrill, một chuyên gia phân tích chữ viết tay và Linda del Buono, tên tội phạm có quen biết một nạn nhân của gã Zodiac. Đối với Graysmith hiện tại, công việc lẫn vợ con đều ...</p>', 'Full', 1, 'single', 'completed', 13, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Anthony Edwards","avatar":""},{"name":"Robert Downey Jr.","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Richmond Arquette","avatar":""},{"name":"Bob Stephenson","avatar":""},{"name":"John Lacy","avatar":""},{"name":"Chloë Sevigny","avatar":""},{"name":"Ed Setrakian","avatar":""},{"name":"John Getz","avatar":""},{"name":"John Terry","avatar":""},{"name":"Candy Clark","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"Ju","avatar":""}]', '[{"name":"Hình Sự