INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('300-chien-binh', '300 Chiến Binh', '300', 'https://phimimg.com/upload/vod/20231023-1/76174f87c8f3a08de66707f3d9192114.jpg', 'https://phimimg.com/upload/vod/20231023-1/3be1915454a245e19083b45353bb050c.jpg', '<p>Dựa trên bộ truyện tranh lịch sử nổi tiếng của nhà văn Frank Miller, 300 là một thiên anh hùng ca kể về cuộc chiến Thermopylae lẫy lừng trong lịch sử cổ đại, năm 480 trước CN, khi vua Leonidas cùng 300 tinh binh Sparta đã quyết tử đánh trả đạo quân Ba Tư khổng lồ gần 1 triệu quân do vua Xerxes chỉ huy nhằm thôn tính đất nước Hy Lạp.</p>', 'Full', 1, 'single', 'completed', 18, 2007, 'Vietsub', 'HD', 'Bulgaria', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Dominic West","avatar":""},{"name":"David Wenham","avatar":""},{"name":"Vincent Regan","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Tom Wisdom","avatar":""},{"name":"Andrew Pleavin","avatar":""},{"name":"Andrew Tiernan","avatar":""},{"name":"Rodrigo Santoro","avatar":""},{"name":"Giovani Cimmino","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Greg Kramer","avatar":""},{"name":"Alex Ivanovici","avatar":""},{"name":"Kelly Craig","avatar":""},{"name":"Eli Snyder","avatar":""},{"name":"Tyler Neitzel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324522);
