INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ca-stan', 'Đại Ca Stan​', 'Big Stan', 'https://phimimg.com/upload/vod/20231022-1/12603a926e27a6d95b6cfaaf8e0b6ee9.jpg', 'https://phimimg.com/upload/vod/20231022-1/7a12d2b6d4433788c82f7ceed94fbf63.jpg', '<p>Anh chàng Stan giàu có bị kết án 3 năm tù vì tội lừa đảo trong việc môi giới nhà đất. Với 6 tháng còn lại trước khi lĩnh án, Stan tìm đủ mọi cách để có thể sống sót trong tù với những tên tù nhân to con và dã man. Và anh gặp được Master, một cao thủ võ lâm, người đồng ý huấn luyện với Stan trở thành đại ca trong tù. Bằng những phương pháp quái gở, kinh dị Master tin rằng Stan sẽ trở nên khỏe mạnh và có võ nghệ cao cường. Ngày kinh hoàng cũng đến, Stan bỏ lại sau lưng cô vợ xinh đẹp, bốc lửa, căn biệt thự cùng chiếc xe hơi đắt tiền để lên đường đi tù. Liệu anh chàng nhỏ bé, láu cá Stan có chống trọi được với những tên tội phạm dã man và thiếu thốn tình cảm trong tù.</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rob Schneider","avatar":""},{"name":"David Carradine","avatar":""},{"name":"Jennifer Morrison","avatar":""},{"name":"Scott Wilson","avatar":""},{"name":"Richard Kind","avatar":""},{"name":"Sally Kirkland","avatar":""},{"name":"M. Emmet Walsh","avatar":""},{"name":"Henry Gibson","avatar":""},{"name":"Jackson Rathbone","avatar":""},{"name":"Kevin Gage","avatar":""},{"name":"Bob Sapp","avatar":""},{"name":"Brandon T. Jackson","avatar":""},{"name":"Dan Haggerty","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"Marcia Wallace","avatar":""},{"name":"Olivia Munn","avatar":""},{"name":"Buddy Lewis","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324522);
