INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-chon-dung-than', 'Không Chốn Dung Thân', 'No Country for Old Men', 'https://phimimg.com/upload/vod/20231020-1/2b4febc79e8782d17a580a50182ca856.jpg', 'https://phimimg.com/upload/vod/20231020-1/ed74ee2b1c611c1a06c8f953b1a116b1.jpg', '<p>Phim lấy bối cảnh tại thời đại mới, khi ma túy vượt mặt trộm cắp trở thành loại tội phạm nguy hiểm nhất và khi súng được sử dụng tự do tại một thị trấn nhỏ. Câu chuyện bắt đầu khi Llewelyn Moss tình cờ tìm thấy chiếc xe tải chất đầy ma túy và 200 triệu USD tiền mặt. Khi Moss quyết định lấy đi số tiền cũng là lúc anh ấn nút khởi động cho guồng quay tội ác mà thậm chí cả luật pháp – thứ luật pháp còn tồn tại bên trong cơ thể già nua của viên cảnh sát trưởng Bell – cũng không thể ngăn cản. Cũng vì số tiền đó mà Moss trở thành nạn nhân của Chigurh, tên tội phạm máu lạnh vô cùng độc ác, thích quyết định số phận nạn nhân bằng trò chơi tung đồng xu...</p>', 'Full', 1, 'single', 'completed', 14, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tommy Lee Jones","avatar":""},{"name":"Javier Bardem","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Kelly Macdonald","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Tess Harper","avatar":""},{"name":"Barry Corbin","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Rodger Boyce","avatar":""},{"name":"Beth Grant","avatar":""},{"name":"Ana Reeder","avatar":""},{"name":"Kit Gwin","avatar":""},{"name":"Zach Hopkins","avatar":""},{"name":"Chip Love","avatar":""},{"name":"Eduardo Antonio Garcia","avatar":""},{"name":"Gene Jones","avatar":""},{"name":"Myk Watf","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324522);
