INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-huyen-thoai', 'Tôi Là Huyền Thoại', 'I Am Legend', 'https://phimimg.com/upload/vod/20231020-1/15e51ebfecb49b3a1dc3d4498dd81213.jpg', 'https://phimimg.com/upload/vod/20231020-1/66c5b3fee6fcad5df8b0c3606f6bd3a7.jpg', '<p>Năm 2012 thành phố New York đầy những tòa nhà chọc trời, những tấm biển quảng cáo màu sắc đã trở thành một thành phố chết. Không có một bóng người, chỉ có cỏ dại mọc trên các xa lộ và những chiếc ô tô rỉ sét nằm ngổn ngang. Cách đó 3 năm, một chủng virus khủng khiếp đã càn quét khắp Trái Đất, tiêu diệt gần như toàn bộ nhân loại. Những người còn sống thì bị biến thành các sinh vật gớm ghiếc, hung tợn, thèm thịt tươi và sợ ánh mặt trời. Chỉ trừ, có lẽ không nhiều hơn một người, nhà khoa học Robert Neville (Will Smith).</p>', 'Full', 1, 'single', 'completed', 26, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"Charlie Tahan","avatar":""},{"name":"Dash Mihok","avatar":""},{"name":"Salli Richardson-Whitfield","avatar":""},{"name":"Willow Smith","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Darrell Foster","avatar":""},{"name":"Joanna Numata","avatar":""},{"name":"Samuel Glen","avatar":""},{"name":"Pedro Mojica","avatar":""},{"name":"Marin Ireland","avatar":""},{"name":"Alexander DiPersia","avatar":""},{"name":"Raul Torres","avatar":""},{"name":"April Grace","avatar":""},{"name":"James McCauley","avatar":""},{"name":"Anthony C.","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324522);
