INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-robinsons', 'Gia Đình Robinsons', 'Meet the Robinsons', 'https://phimimg.com/upload/vod/20231019-1/db1dfa508f0e07d43fd6b0bd9848e09d.jpg', 'https://phimimg.com/upload/vod/20231019-1/8a733dc06acccf57ee52354a87b64339.jpg', '<p>Là một cậu bé tài năng, Lewis sở hữu trong tay hàng chục phát minh, trong đó có một công cụ giúp con người tìm lại ký ức đã qua của mình. Dự định tìm lại người mẹ thất lạc năm xưa của Lewis dựa vào phát minh này chưa kịp thực hiện thì nó đã bị đánh cắp. Không còn cách nào khác, Lewis đành bắt tay với Wilbur Robinson, một người lạ mặt, và cả hai người họ bắt đầu cuộc phiêu lưu mang đầy sự bất ngờ.</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Hansen","avatar":""},{"name":"Jordan Fry","avatar":""},{"name":"Wesley Singerman","avatar":""},{"name":"Matthew Josten","avatar":""},{"name":"Stephen J. Anderson","avatar":""},{"name":"Tom Selleck","avatar":""},{"name":"Tom Kenny","avatar":""},{"name":"Laurie Metcalf","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Nicole Sullivan","avatar":""},{"name":"Harland Williams","avatar":""},{"name":"John H. H. Ford","avatar":""},{"name":"Don Hall","avatar":""},{"name":"Paul Butcher","avatar":""},{"name":"Tracey Miller-Zarneke","avatar":""},{"name":"Jessie Flower","avatar":""},{"name":"Eth","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324522);
