INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-robinsons', 'Gia Đình Robinsons', 'Meet the Robinsons', 'gia đình robinsons meet the robinsons daniel hansen jordan fry wesley singerman matthew josten stephen j. anderson tom selleck tom kenny laurie metcalf angela bassett nicole sullivan harland williams john h. h. ford don hall paul butcher tracey miller-zarneke jessie flower eth ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-te-hai', 'Siêu Tệ Hại', 'Superbad', 'https://phimimg.com/upload/vod/20231019-1/43e6c00f781e5f108b95b3799e5e3efc.jpg', 'https://phimimg.com/upload/vod/20231019-1/63876f364241513f9267064fa2671308.jpg', '<p>Superbad kể về cuộc hành trình của đôi bạn thân Seth (Jonah Hill đóng) và Evan (Michael Cera) trên con đường tìm kiếm &quot;trái cấm&quot; trước khi họ học lên cao hơn. Tuy nhiên ngoại hình cũng như tính cách của cả hai thì lại không được bình thường cho lắm. Seth béo ú còn Evan lại quá nhút nhát, đương nhiên họ không phải những đối tượng được các cô nàng &quot;ngó ngàng&quot; tới.&nbsp; Chỉ còn ba tuần nữa là kết thúc những năm học phổ thông, vì vậy quyết tâm của cả hai ngày càng tăng cao. Cùng với &quot;mọt sách&quot; Fogell (Christopher Mintz-Plasse), cả ba được cô bạn Jules cùng lớp mời đến tham dự bữa tiệc tại nhà riêng. Oái oăm thay khi Jules nhờ Seth mua rượu bia mang đến buổi party, cô hứa hẹn sẽ có rất &quot;nhiều điều thú vị&quot; dành cho cậu tại đây nếu Seth thực hiện thành công phi vụ.</p>', 'Full', 1, 'single', 'completed', 20, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonah Hill","avatar":""},{"name":"Michael Cera","avatar":""},{"name":"Christopher Mintz-Plasse","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Martha MacIsaac","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Aviva Baumann","avatar":""},{"name":"Joe Lo Truglio","avatar":""},{"name":"Kevin Corrigan","avatar":""},{"name":"Clement Blake","avatar":""},{"name":"Erica Vittina Phillips","avatar":""},{"name":"Joe Nuñez","avatar":""},{"name":"Dave Franco","avatar":""},{"name":"Marcella Lentz-Pope","avatar":""},{"name":"Scott Gerbacia","avatar":""},{"name":"Lau","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324522);
