INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-re-tu-than-duong-cung', 'Ngã Rẽ Tử Thần: Đường Cùng', 'Wrong Turn 2: Dead End', 'https://phimimg.com/upload/vod/20231018-1/ce3f523948e4852cfd6cd24e1c1d06c6.jpg', 'https://phimimg.com/upload/vod/20231018-1/cd9dcd9337110334e9582d8af51bc8ce.jpg', '<p>Khu rừng miền Tây Virginia giờ đây có cả thảy là 5 kẻ đột biến gen khát máu đang trú ngụ là: Three Finger, Pa, Ma, Brother và Sister (trong phần này không có One Eye và Saw Tooth), bọn chúng vẫn chờ đón những nạn nhân xấu số như phần trước. Một ngày kia một đài truyền hình tổ chức một trò chơi có tính mạo hiểm ngay tại khu rừng Virginia này, mỗi người tham gia trò chơi sẽ được đeo một cái máy camera nhỏ trên đầu rồi đi sâu vào rừng, tất cả những gì họ thấy sẽ được phát lên TV cho hàng triệu khán giả khác thấy, nếu đến tối mà ai tìm được đường ra khỏi khu rừng đầu tiên sẽ là người thắng cuộc, nhận được phần thưởng là số tiền to lớn 100,000 USD. Những người bạn trẻ đó đồng ý ngay vì họ thấy trò này cũng có tính chất cảm giác mạnh, thế là lần lượt từng người bị gia đình của Three Finger giết chết, ai sẽ là người may mắn sống sót trở về.</p>', 'Full', 1, 'single', 'completed', 19, 2007, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Erica Leerhsen","avatar":""},{"name":"Henry Rollins","avatar":""},{"name":"Aleksa Palladino","avatar":""},{"name":"Crystal Lowe","avatar":""},{"name":"Rorelee Tio","avatar":""},{"name":"Kimberly Caldwell","avatar":""},{"name":"Daniella Alonso","avatar":""},{"name":"Texas Battle","avatar":""},{"name":"Steve Braun","avatar":""},{"name":"Ken Kirzinger","avatar":""},{"name":"Patton Oswalt","avatar":""},{"name":"Matthew Currie Holmes","avatar":""},{"name":"Wayne Robson","avatar":""},{"name":"Jeff Scrutton","avatar":""},{"name":"Ashlea Earl","avatar":""},{"name":"Clint Carleton","avatar":""},{"name":"Cedri","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324522);
