INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-cua-4', 'Lưỡi Cưa 4', 'Saw IV', 'https://phimimg.com/upload/vod/20231017-1/15b1fbdfe7feb7bb7c1ebb451bec2aca.jpg', 'https://phimimg.com/upload/vod/20231017-1/31a47ab907ba44ee00ff378f9ecc3c91.jpg', '<p>Jigsaw có thể đã chết, nhưng khi một cuộn băng được tìm thấy trong bụng hắn trong lúc khám nghiệm tử thi, cảnh sát biết rằng di sản độc địa của hắn mới chỉ bắt đầu.</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tobin Bell","avatar":""},{"name":"Costas Mandylor","avatar":""},{"name":"Scott Patterson","avatar":""},{"name":"Betsy Russell","avatar":""},{"name":"Lyriq Bent","avatar":""},{"name":"Athena Karkanis","avatar":""},{"name":"Louis Ferreira","avatar":""},{"name":"Simon Reynolds","avatar":""},{"name":"Donnie Wahlberg","avatar":""},{"name":"Angus Macfadyen","avatar":""},{"name":"Shawnee Smith","avatar":""},{"name":"Bahar Soomekh","avatar":""},{"name":"Dina Meyer","avatar":""},{"name":"Mike Realba","avatar":""},{"name":"Marty Adams","avatar":""},{"name":"Sarain Boylan","avatar":""},{"name":"Billy Otis","avatar":""},{"name":"Jame","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324522);
