INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-mat-chuoc', 'Vua Mạt Chược', 'House Of Mahjong', 'https://phimimg.com/upload/vod/20231012-1/6b20b607ac24eb7df8dd8e4e29d5eae2.jpg', 'https://phimimg.com/upload/vod/20231012-1/154bfa2fccdc7ca5eace51c18f323a54.jpg', '<p>Gi, người muốn bắt đầu kinh doanh tại Trung tâm thương mại Fu Gui, cần học chơi mạt chược Đài Loan để trở thành khách thuê ở đó. Tất cả những người thuê nhà khác đều dạy cô kỹ thuật chơi trò chơi nhưng Fu Ho đã đánh bại Gi. Tuy nhiên, anh ấn tượng với quyết tâm của cô và thuê một nơi cho Gi. Trong khi đó, con trai của Fu Ho, Sun Gui, trở về Hồng Kông và lên kế hoạch tiếp quản trung tâm mua sắm. Anh ta tìm bốn chuyên gia mạt chược để đánh bạc với những người thuê nhà. Gi, Sam, Lam và những người khác mất tiền và phương tiện sinh tồn. May mắn thay, Lâm đã tìm thấy.</p>', 'Full', 1, 'single', 'completed', 19, 2007, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Cheung Tat-Ming","avatar":""},{"name":"Matt Chow Hoi-Kwong","avatar":""},{"name":"Ha Chun-Chau","avatar":""},{"name":"Elanne Kwong","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Rain Li","avatar":""},{"name":"Dayo Wong","avatar":""},{"name":"Raymond Wong Ho-yin","avatar":""},{"name":"Candy Lo","avatar":""},{"name":"Amanda Lee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324522);
