INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-nhan-ban-sac', 'Nữ Nhân Bản Sắc', 'Wonder Women', 'null', 'https://phimimg.com/upload/vod/20231011-1/1214f7882271f9f7be727cfe5a4e72cc.jpg', '<p>Năm bàn giao 1997 chứng kiến nhiều kịch tính đối với Joy (Gigi Leung), giám đốc tài chính của một công ty lớn. Cô phải vật lộn để duy trì cuộc sống gia đình bên nhau khi chồng cô buộc phải chuyển đến Singapore do có nguồn gốc từ Anh và con trai cô bị bệnh tật. Bạn thân và trợ lý của Joy (do Fiona Sit thủ vai) là một cô gái trẻ đang cố gắng tìm hiểu người bạn trai tinh ranh của mình. Tuy nhiên, cô vẫn cố gắng giúp đỡ nhưng Joy lại chìm vào tuyệt vọng sâu sắc hơn do vấn đề gia đình. Một ngày nọ, sự dằn vặt trở nên không thể chịu đựng nổi và Niềm vui tan vỡ. Mọi thứ có vẻ ảm đạm đối với cả hai cho đến khi một người bạn thực hiện lời hứa cũ và mang lại cho họ niềm hạnh phúc trở lại.</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Gigi Leung","avatar":""},{"name":"Fiona Sit","avatar":""},{"name":"George Lam Chi-Cheung","avatar":""},{"name":"Kevin Cheng","avatar":""},{"name":"Hacken Lee","avatar":""},{"name":"Hins Cheung","avatar":""},{"name":"Kitty Yuen","avatar":""},{"name":"Eddy Ko","avatar":""},{"name":"Jimmy Fu Git-Ming","avatar":""},{"name":"Carisa Yan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324522);
