INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-than-bo-lac', 'Đơn Thân Bộ Lạc', 'Single Blog', 'https://phimimg.com/upload/vod/20231010-1/45a3721cf49b0daddc7efb5344a15c7a.jpg', 'https://phimimg.com/upload/vod/20231010-1/d845a51af17c705c0685a6f8bc5b4342.jpg', '<p>Tình dục và tình yêu, cái nào quan trọng hơn? Có ba người bạn nữ ở cùng nhà: Vivian phù phiếm, Kitty nghiêm nghị và đứng đắn, còn Mei Wah thì ngổ ngáo. Thông qua những trải nghiệm mới về tình yêu và tình dục, họ tìm thấy chính mình. Ba người phụ nữ, với ba trải nghiệm tình yêu và tình dục khác nhau, cho chúng ta biết rằng tình dục và tình yêu không thể tách rời. Phụ nữ nói chuyện luôn khiến bạn lạc lối trong suy nghĩ.</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jo Kuk Cho-Lam","avatar":""},{"name":"Rain Li","avatar":""},{"name":"Carl Ng","avatar":""},{"name":"Monie Tung Man-Lee","avatar":""},{"name":"Anya Wu","avatar":""},{"name":"Chan Fai-hung","avatar":""},{"name":"Derek Tsang","avatar":""},{"name":"Jolie Chan","avatar":""},{"name":"Raymond Wong Ho-yin","avatar":""},{"name":"Andrew Lin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324522);
