INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-hoc-ma-am-2007', 'Trường Học Ma Ám', 'The Haunted School', 'https://phimimg.com/upload/vod/20231010-1/bbcbb9b93958d6df0c24c6964a33fce7.jpg', 'https://phimimg.com/upload/vod/20231010-1/967a27ce0570d65b71ba711b257fc5df.jpg', '<p>Trường nội trú Narranmoda rất nghiêm khắc đối với nữ sinh và có những quy tắc ứng xử cứng nhắc, nhưng hiệu trưởng vẫn nhận 4 nam sinh để cải thiện thu nhập cho trường. Tuy nhiên, các chàng trai bị tách biệt khỏi các cô gái và thanh tra Miss Fong giữ họ dưới sự giám sát của học sinh giám sát tận tâm Ho Yat-Man. Truyền thuyết đô thị kể rằng ngôi trường bị ma ám và khi học sinh vi phạm nội quy của trường, họ được gọi đến văn phòng giám đốc và biến mất hoặc được tìm thấy đã chết.</p>', 'Full', 1, 'single', 'completed', 19, 2007, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Theresa Fu","avatar":""},{"name":"Chui Tien-You","avatar":""},{"name":"Don Li","avatar":""},{"name":"Macy Chan","avatar":""},{"name":"Toby Leung Ching-Kei","avatar":""},{"name":"Steven Cheung","avatar":""},{"name":"Amanda Lee","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324522);
