INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-hoc-ma-am-2007', 'Trường Học Ma Ám', 'The Haunted School', 'trường học ma ám the haunted school theresa fu chui tien-you don li macy chan toby leung ching-kei steven cheung amanda lee cheung kwok-keung ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nguoi-chet', 'Yêu Người Chết', 'In Love With The Dead', 'https://phimimg.com/upload/vod/20231007-1/000da2cd2a54124849464a1a63a10cd9.jpg', 'https://phimimg.com/upload/vod/20231007-1/c937cc2f76ceb23ab6025695595a5d5e.jpg', '<p>Tại Hồng Kông, nhà thiết kế thành đạt Ming sống cùng cô bạn gái yêu dấu Wai Luk và em gái yêu thích truyện tranh ma của cô. Khi Wai được chẩn đoán mắc bệnh ung thư tuyến tụy, cuộc sống của Ming bị đảo lộn và anh hy sinh sự nghiệp để dành nhiều thời gian hơn cho Wai. Anh ta tìm được một công việc mới ở một vị trí thấp hơn và bất ngờ phát hiện ra rằng ông chủ mới của anh ta, Chu Fong, chính là người bạn cũ của anh ta ở trường tiểu học. Khi Wai từ bỏ hóa trị, cô quyết định tự điều trị theo phương pháp y học cổ truyền Trung Quốc do dì cô hướng dẫn. Cô ấy có những hành vi kỳ lạ ở nhà và người chị sợ hãi của cô ấy khẳng định rằng cô ấy là ma. Trong khi đó, Ming thân thiết hơn với Fong, một doanh nhân thành đạt nhưng lại là một người phụ nữ cần tình yêu. Trong chuyến đi đến Bắc Kinh, họ có tình một đêm. Trong những ngày tiếp theo, Ming và Fong có một mối tình và Ming tin rằng Wai chính là linh hồn đang giải quyết các vấn đề của cô để tiến lên một tầm cao mới.</p>', 'Full', 1, 'single', 'completed', 21, 2007, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Shawn Yue","avatar":""},{"name":"Stephy Tang","avatar":""},{"name":"Yung Yung Yu","avatar":""},{"name":"Cho Wing-Lim","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Zeng Qi Qi","avatar":""},{"name":"Kiki Sheung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324522);
