INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-nhi-ban-sac', 'Nam Nhi Bản Sắc', 'Invisible Target', 'https://phimimg.com/upload/vod/20231006-1/1b59385ba882aafd6ddb74cc4a424719.jpg', 'https://phimimg.com/upload/vod/20231006-1/889e32c15e6289e73c111bb554118840.jpg', '<p>Một băng cướp có vũ trang thực hiện vụ cướp ngay giữa ban ngày, mang đi 100 triệu USD từ chiếc xe chở tiền sau khi gây ra một vụ nổ kinh hoàng. Một trong số những nạn nhân đáng thương của chúng là vợ chưa cưới của viên cảnh sát Trần Chân (Tạ Đình Phong). Sáu tháng sau, vẫn bị ám ảnh bởi cái chết của người yêu, Trần Chân không nguôi ý định trả thù. Cùng lúc đó, viên thanh tra trẻ tuổi tên Phương Vĩnh Oai (Dư Văn Lạc) cũng lần theo dấu vết để truy tìm những kẻ chủ mưu của vụ cướp táo tợn cách đó nửa năm.</p>', 'Full', 1, 'single', 'completed', 17, 2007, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Nicholas Tse","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Jaycee Chan","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Andy On","avatar":""},{"name":"Elanne Kwong","avatar":""},{"name":"Ka Wah Lam","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Candy Liu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324522);
