INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-trong-giang-ho', 'Người Trong Giang Hồ', 'A Mob Story', 'https://phimimg.com/upload/vod/20231006-1/e3ef91480f5c1e26a296cf39bb48dd15.jpg', 'https://phimimg.com/upload/vod/20231006-1/3b3078c346be26a05f16751d0d82daed.jpg', '<p>Sát thủ toàn thời gian Ah Qi (do Julian Cheung đóng vai chính) đã trở lại. Lần này, anh nhận được nhiệm vụ giết bạn gái mới của Fa. Với tốc độ cực nhanh, Ah Qi bắn Fa và cùng bạn gái nhảy xuống biển để trốn thoát. Tuyệt vọng, Ah Qi chạy đến Đài Loan và đến gặp người bạn Xiao Gui, người hiện đang bị Zhiling mê hoặc. Để chuộc cô, Xiao Gui không ngần ngại giết người. Sự xuất hiện của Ah Qi khiến Zhiling, người luôn coi thường Xiao Gui, trở nên lạnh lùng hơn với Xiao Gui. Máu của Xiao Gui sôi lên vì phẫn nộ và anh hoàn thành nhiệm vụ cùng Ah Qi, nhưng điều chờ đợi họ sau đó là tình anh em bấp bênh...</p>', 'Full', 1, 'single', 'completed', 22, 2007, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Julian Cheung","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Hugo Ng","avatar":""},{"name":"Raymond Wong Ho-yin","avatar":""},{"name":"Mandy Chiang","avatar":""},{"name":"Johnny Lu","avatar":""},{"name":"Cai Xinghung","avatar":""},{"name":"Bonnie Wong","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324522);
