INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-khong-the-noi', 'Bí Mật Không Thể Nói', 'Secret', 'https://phimimg.com/upload/vod/20231006-1/223b60920c14c4c34e3c8ebc7f0b578c.jpg', 'https://phimimg.com/upload/vod/20231006-1/dbf72e6595b73de7d74a7002a2828ea9.jpg', '<p>Một bộ phim tình yêu giả tưởng mà Châu Kiệt Luân vừa làm đạo diễn 
vừa làm diễn viên! Với một học sinh chuyển trường với tài năng âm nhạc 
cao siêu, gặp cô gái thần bí chơi đàn trong phòng piano, liệu tình yêu 
có đến đúng hẹn như âm nhạc không?</p>', 'Full', 1, 'single', 'completed', 20, 2007, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jay Chou","avatar":""},{"name":"Gwei Lun-mei","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Alice Tzeng","avatar":""},{"name":"So Ming-Ming","avatar":""},{"name":"Huang Jun-Lang","avatar":""},{"name":"Devon Song","avatar":""},{"name":"Zhan Yu-Hao","avatar":""},{"name":"Chase Chang","avatar":""},{"name":"Aviis Zhong","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324522);
