INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-khi-chet-choc', 'Không Khí Chết Chóc', 'Dead Air', 'https://phimimg.com/upload/vod/20231004-1/1deee2aaca7751e6d5a1b15bbacbd654.jpg', 'https://phimimg.com/upload/vod/20231004-1/087ac86ca0e20960fd4cf5c678c5c62f.jpg', '<p>Đạo diễn truyền hình Luo Jun rất muốn quay một bộ phim siêu nhiên, nhưng rating của bộ phim quá thấp và anh phải đối mặt với số phận phải dừng bộ phim của mình, trong khi mối quan hệ của anh với bạn gái và bạn thân Âu Dương Vi Bang đang căng thẳng. Luo Jun lái xe điên cuồng vào lúc nửa đêm và gặp tai nạn xe hơi trong khu rừng im lặng. Anh ta nghe thấy tiếng kêu cứu và sau đó nhìn thấy một phụ nữ mang thai đang ngồi bên gốc cây. Anh giúp người phụ nữ mang thai bế đứa con mới chào đời thì phát hiện cổ họng của cô bị cắt và cô khó thở. Luo Jun, người chạy trốn khỏi hiện trường sau khi gọi cảnh sát, kể từ đó đã bị hồn ma mang thai Fu Yingsi theo dõi. Cô cảm ơn sự giúp đỡ của anh, hy vọng Luo Jun có thể nuôi đứa trẻ và hứa sẽ trả ơn lòng tốt của anh.</p>', 'Full', 1, 'single', 'completed', 22, 2007, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Derek Tsang","avatar":""},{"name":"Leila Tong","avatar":""},{"name":"Terence Yin","avatar":""},{"name":"Raymond Wong Ho-yin","avatar":""},{"name":"Jo Kuk Cho-Lam","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""},{"name":"Susan Tse","avatar":""},{"name":"Ben Cheung Ka-Lun","avatar":""},{"name":"Max Mak Yiu-Kai","avatar":""},{"name":"Ng Hiu-Kwan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324522);
