INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nhi-vien', 'Cô Nhi Viện', 'The Orphanage', 'https://phimimg.com/upload/vod/20230917-1/add8b307099f4a8f47e1d8807aeed514.jpg', 'https://phimimg.com/upload/vod/20230917-1/a0f508b1d1d2ea0c66026e28aa408dd1.jpg', '<p><span style="font-family: ">Sau nhiều năm xa cách, một người đàn bà nọ quyết định trở về nơi cô lớn lên, đó là một trại trẻ mồ côi xưa ven bờ biển. Và cũng từ lúc đó, đứa con nuôi của cô bắt đầu kết bạn với những đứa trẻ...vô hình</span></p>', 'Full', 1, 'single', 'completed', 32, 2007, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Belén Rueda","avatar":""},{"name":"Fernando Cayo","avatar":""},{"name":"Roger Príncep","avatar":""},{"name":"Mabel Rivera","avatar":""},{"name":"Montserrat Carulla","avatar":""},{"name":"Andrés Gertrúdix","avatar":""},{"name":"Edgar Vivar","avatar":""},{"name":"Óscar Casas","avatar":""},{"name":"Geraldine Chaplin","avatar":""},{"name":"Carmen López","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324522);
