INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giua-sa-mac-lua', 'Giữa Sa Mạc Lửa', 'The Kingdom', 'https://phimimg.com/upload/vod/20230917-1/ff4a1bee33f74e82e37435291afc41f0.jpg', 'https://phimimg.com/upload/vod/20230917-1/718b1db0e1ff9987e91d70bfdd133650.jpg', '<p><span style="font-family: ">Dựa trên một sự kiện có thật, ngày 12 tháng 5 năm 2003, tại khu định cư dành cho người Mỹ tại Riyadh, Saudi Arabia đã xảy ra một vụ đánh bom cảm tử khiến 35 người thiệt mạng và hơn 160 người bị thương, tất cả họ đều là thường dân vô tội, quyết tâm truy bắt bằng được những kẻ chủ mưu, Chính phủ Hoa Kỳ đã biệt phái 1 đội đặc vụ FBI đến Saudi Arabia để điều tra sự việc, nhưng liệu &quot;vào hang cọp có bắt được cọp&quot;? Khi những kẻ chủ mưu không phải chỉ là 1 tập thể nhỏ nhoi mà là 1 tổ chức khủng bố khổng lồ, Al-Qaeda cùng cả một thế giới Hồi giáo luôn căm ghét người Mỹ vì những gì chính phủ Hoa Kỳ đã và đang làm trên vùng đất Trung Đông này...</span></p>', 'Full', 1, 'single', 'completed', 25, 2007, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Jamie Foxx","avatar":""},{"name":"Jennifer Garner","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Ali Soliman","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Ashraf Barhom","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Tim McGraw","avatar":""},{"name":"Kyle Chandler","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324522);
