INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-gioi', 'Sắc, Giới', 'Lust Caution', 'https://phimimg.com/upload/vod/20230912-1/48760a00b5aa00be3ad26f2b5ab16e7b.jpg', 'https://phimimg.com/upload/vod/20230912-1/090ab936bb860b653a504a62b5cc2def.jpg', '<p><span style="font-family: ">Sắc giới có lẽ là bộ phim gây nhiều tranh cãi nhất của đạo diễn Lý An trong suốt sự nghiệp đạo diễn của ông , người ta không phải tranh cãi về hàng loạt giải thưởng lớn mà phim đạt được tại nhiều liên hoan phim khác nhau mà là về một câu trả lời chưa được giải đáp “Cảnh nóng trong phim là thật hay chỉ là dàn dựng?”. Những người trong cuộc không phủ nhận cũng không xác thực làm cho nhiều người lại càng tò mò và cho dù câu trả lời là như thế nào thì cũng phải nói rằng nội dung của phim rất hay.</span></p>', 'Full', 1, 'single', 'completed', 28, 2007, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Tang Wei","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Leehom Wang","avatar":""},{"name":"Tsung-Hua Tou","avatar":""},{"name":"Jacqueline Zhu Zhi-Ying","avatar":""},{"name":"Kao Ying-Hsuan","avatar":""},{"name":"Lawrence Ko","avatar":""},{"name":"Johnson Yuen Tak-Cheung","avatar":""},{"name":"Chin Ka-Lok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324522);
