INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ran-nut', 'Rạn Nứt', 'Fracture', 'https://phimimg.com/upload/vod/20230912-1/17a5f887668f1df14e2cac9a2e646f03.jpg', 'https://phimimg.com/upload/vod/20230912-1/558ce79bb6f760f19fe60e8414189447.jpg', '<p><span style="font-family: ">Phim kể về một kỹ sư đầu óc vô cùng tỉ mỉ, chính xác tên là Ted Crawford (Anthony Hopkins) và một viên luật sư trẻ tuổi đầy tham vọng Willy Beachum (Ryan Gosling đóng). Hai người đã bị lôi cuốn vào một cuộc đấu trí vô cùng khốc liệt với đầy rẫy âm mưu và thủ đoạn sau khi Crawford được xử trắng án trong cái chết của vợ ông ta...</span></p>', 'Full', 1, 'single', 'completed', 29, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anthony Hopkins","avatar":""},{"name":"Ryan Gosling","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"Billy Burke","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"Bob Gunton","avatar":""},{"name":"Josh Stamberg","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324522);
