INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-tu-sieu-dang-su-gia-bac', 'Bộ Tứ Siêu Đẳng: Sứ Giả Bạc', 'Fantastic Four: Rise of the Silver Surfer', 'https://phimimg.com/upload/vod/20230912-1/3d5123604f2c848fc305a2542828b7ff.jpg', 'https://phimimg.com/upload/vod/20230912-1/c8aee8f475142816faaeaac478394176.jpg', '<p><span style="font-family: ">Đã hai năm trôi qua kể từ khi tên ác nhân Victor Von Doom bị bộ tứ siêu đẳng làm cho biến thành tượng sắt. Reed Richards và Sue Storm đang chuẩn bị cho đám cưới của họ. Đúng lúc này, một vật thể lạ bằng bạc xuất hiện trên bầu khí quyển của Trái Đất, mang theo nguồn năng lượng khổng lồ, gây nên hiện tượng dao động phân tử trên diện rộng, khiến vỏ Trái Đất bị nhiều vết nứt. Bên cạnh đó Fantastic Four còn phải để tâm đến đối thủ truyền kiếp là gã tiến sĩ Doom luôn thừa cơ hội tìm cách hãm hại họ…</span></p>', 'Full', 1, 'single', 'completed', 34, 2007, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ioan Gruffudd","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Michael Chiklis","avatar":""},{"name":"Julian McMahon","avatar":""},{"name":"Doug Jones","avatar":""},{"name":"Kerry Washington","avatar":""},{"name":"Andre Braugher","avatar":""},{"name":"Laurence Fishburne","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324522);
