INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-kim-giap', 'Hoàng Kim Giáp', 'Curse Of The Golden Flower', 'https://phimimg.com/uploads/movies/20260713/hoang-kim-giap-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/hoang-kim-giap-poster.webp', '<p>Bộ phim sử thi cổ trang lấy bối cảnh thời hậu Đường ở Trung Hoa với tham vọng thống nhất thiên hạ, chinh chiến triền miên, để lại khoảng trống quyền lực to lớn trong cung cấm. Không tiết chế được dục vọng, vương hậu lén lút gian dâm với Đại vương tử Nguyên Tường...</p>', 'Full', 1, 'single', 'completed', 54, 2006, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Nhuận Phát","avatar":""},{"name":"Củng Lợi","avatar":""},{"name":"Lưu Diệp","avatar":""},{"name":"Châu Kiệt Luân","avatar":""},{"name":"Lý Mạn","avatar":""},{"name":"Nghê Đại Hồng","avatar":""},{"name":"Trần Cẩn","avatar":""},{"name":"Tần Tuấn Kiệt","avatar":""},{"name":"Quách Thường Huy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Curse of the Golden Flower","La città proibita","La Cité interdite","Cesarzowa","황후花","Den gyllene blommans förbannelse","Man cheng jin dai huang jin jia","Slaget om den forbudte by","Kampen om den forbudte by","滿城盡帶黃金甲"]', 1784690324522);
