INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoang-kim-giap', 'Hoàng Kim Giáp', 'Curse Of The Golden Flower', 'hoàng kim giáp curse of the golden flower châu nhuận phát củng lợi lưu diệp châu kiệt luân lý mạn nghê đại hồng trần cẩn tần tuấn kiệt quách thường huy curse of the golden flower la città proibita la cité interdite cesarzowa 황후花 den gyllene blommans förbannelse man cheng jin dai huang jin jia slaget om den forbudte by kampen om den forbudte by 滿城盡帶黃金甲', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-click-huyen-bi-dieu-khien-ky-dieu', 'Cú Click Huyền Bí (Điều Khiển Kỳ Diệu)', 'Click', 'https://phimimg.com/uploads/movies/20260710/cu-click-huyen-bi-dieu-khien-ky-dieu-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/cu-click-huyen-bi-dieu-khien-ky-dieu-poster.webp', '<p>"Click" nói về anh chàng kiến trúc sư Michael Newman tham công tiếc việc đến nỗi chả để ý gì đến gia đình cùa mình, thậm chí ngay cả đến cô vợ Donna và 2 đứa con của anh ta. Trong 1 lần tìm mua thiết bị điều khiển từ xa vì cái ở nhà đã hỏng, anh đã tình cờ có được 1 cái thiết bị điều khiển đa năng có thể "tua" nhanh cho anh biết được quá khứ và tương lai của mình. Những rắc rối bắt đầu xảy ra khi nó không tuân theo mệnh lệnh và thoát khỏi sự điều khiển của anh...  Click mang nội dung nhẹ nhành như chính hơi thở cuộc sống. Michael tiêu biểu cho hàng chục triệu người trên trái đất này đang mải miết với công việc và bỏ quên gia đình mình đến khi thất bại trong sự nghiệp họ mới nhận ra rằng gia đình là nơi trú ẩn cuối cùng và an toàn nhất mà mình đang có.</p>', 'Full', 1, 'single', 'completed', 61, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Kate Beckinsale","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"David Hasselhoff","avatar":""},{"name":"Henry Winkler","avatar":""},{"name":"Julie Kavner","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Joseph Castanon","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Jake Hoffman","avatar":""},{"name":"Tatum McCann","avatar":""},{"name":"Lorraine Nicholson","avatar":""},{"name":"Katie Cassidy","avatar":""},{"name":"Cameron Monaghan","avatar":""},{"name":"Jennifer Coolidge","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["神奇遥控器","命运自选台","Klik život na dálkové ovládání","命運好好玩","קליק","Clic","Click Perdiendo el Control","클릭","Kumanda","Click","Click: Perdiendo el Control","Click - Télécommandez votre vie","Cambia la tua vita con un click","Click: Perdiendo El Control"]', 1784690324522);
