INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-the-gioi-phan-1', 'Giải Cứu Thế Giới (Phần 1)', 'Heroes (Season 1)', 'https://phimimg.com/upload/vod/20260702-1/b8c57b3775649d3423cdd47ae3b29d6b.jpg', 'https://phimimg.com/upload/vod/20260702-1/ca1ce7ef95da295e1c7813ee69e26acb.jpg', '<p>Những con người bình thường bỗng chốc phát hiện ra mình sở hữu những siêu năng lực phi thường. Cuộc đời của họ bắt đầu đan xen và gắn kết với nhau khi một thảm họa tàn khốc sắp xảy ra cần phải được ngăn chặn.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 34, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zachary Quinto","avatar":""},{"name":"Hayden Panettiere","avatar":""},{"name":"Milo Ventimiglia","avatar":""},{"name":"Masi Oka","avatar":""},{"name":"Jack Coleman","avatar":""},{"name":"Adrian Pasdar","avatar":""},{"name":"Greg Grunberg","avatar":""},{"name":"Sendhil Ramamurthy","avatar":""},{"name":"Ali Larter","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"James Kyson","avatar":""},{"name":"Cristine Rose","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Série Heroes","Heroes (2006)","英雄","Héroes","Heroes"]', 1784690324522);
