INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-van-phong-phan-3', 'Chuyện Văn Phòng (Phần 3)', 'The Office (Season 3)', 'https://phimimg.com/upload/vod/20260604-1/c3dc8fce7c2a92f658bef149de515ec5.jpg', 'https://phimimg.com/upload/vod/20260604-1/cebd040ce973799e8da036c9fdaa977d.jpg', '<p>Phần này đánh dấu sự chuyển nhân vật chính Jim Halpert từ Scranton đến Stamford, đồng thời giới thiệu Rashida Jones trong vai Karen Filippelli, và Ed Helms trong vai Andy Bernard—cả hai thành viên của Dunder Mifflin Stamford—là những nhân vật định kỳ. Cốt truyện chính của các tập đầu mùa đề cập đến một vấn đề tái diễn trong phần một và hai - vấn đề cắt giảm quy mô công ty - trong khi ở nửa cuối mùa, các mối quan hệ giữa các văn phòng cũng trở thành một điểm cốt truyện chính.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 30, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rainn Wilson","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Jenna Fischer","avatar":""},{"name":"Ed Helms","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zyra","Punë zyre","Vida de Escritório","美版办公室","The Office (US) – Das Büro","The Office (U.S.)","آفیس","The Office US","The Office","The Office (US)","The Office (US) Extended Superfan Cut","The Office: An American Workplace","The Office: Superfan Episodes","The Office Superfan Episodes"]', 1784690324522);
