INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-smallville-phan-6', 'Thị Trấn Smallville (Phần 6)', 'Smallville (Season 6)', 'https://phimimg.com/upload/vod/20250604-1/3fb3b38871f4a9d5cafc96a2c42c1d4f.jpg', 'https://phimimg.com/upload/vod/20250604-1/1cb7abd863540cdfbcbd2599cf33c06c.jpg', '<p>Clark thoát khỏi Vùng Bóng Ma với sự giúp đỡ từ một đồng minh bất ngờ. Sau đó, cậu bắt đầu nhiệm vụ truy lùng những tù nhân nguy hiểm đã theo cậu đến Trái Đất. Thêm vào những rắc rối của Clark, trong thị trấn xuất hiện một cảnh vệ mới mang biệt danh Green Arrow. Trong khi đó, mối quan hệ giữa Lex và Lana bước sang một giai đoạn mới. Khi mùa phim tiếp diễn, sự đối đầu giữa Clark Kent và Lex Luthor sẽ bùng nổ thành một cuộc chiến ác liệt giữa cái thiện và cái ác.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 16, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Welling","avatar":""},{"name":"Erica Durance","avatar":""},{"name":"Cassidy Freeman","avatar":""},{"name":"Justin Hartley","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Smallville"]', 1784690324522);
