INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-cap-cuu-phan-13', 'Phòng Cấp Cứu (Phần 13)', 'ER (Season 13)', 'https://phimimg.com/upload/vod/20260526-1/8220efce04f5460bffeb1a1148f50191.jpg', 'https://phimimg.com/upload/vod/20260526-1/b5d5855a7fa46918460faafc074e9de0.jpg', '<p>ER (Phòng Cấp Cứu) đi sâu vào khai thác guồng quay công việc nội bộ đầy áp lực tại một bệnh viện đào tạo lớn ở thành thị, đồng thời lột tả những vấn đề nan giải và mang tính quyết định mà đội ngũ y bác sĩ cùng nhân viên tận tụy tại phòng cấp cứu luôn trong tình trạng quá tải nơi đây phải đối mặt hàng ngày.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 18, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Maura Tierney","avatar":""},{"name":"Parminder Nagra","avatar":""},{"name":"Linda Cardellini","avatar":""},{"name":"Scott Grimes","avatar":""},{"name":"David Lyons","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"John Stamos","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Plantão Médico","急诊室的故事","急诊室的春天","Emergency Room","E.R. - Emergency Room","ER"]', 1784690324522);
