INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-hai-tu-than-3', 'Lưỡi Hái Tử Thần 3', 'Final Destination 3', 'https://phimimg.com/upload/vod/20250519-1/0036acf9837b9a5185f90ce37b7f8d91.jpg', 'https://phimimg.com/upload/vod/20250519-1/34339aa8e4cd194fb3c7597c0771fdf7.jpg', '<p>Cô nữ sinh trung học xinh đẹp Wendy sẽ có một buổi tốt nghiệp trung học thật tuyệt vời nếu cô và nhóm bạn cùng trường không bước vào khu vui chơi cảm giác mạnh Roller Coaster - tàu lượn siêu tốc. Khi cả nhóm chuẩn bị bước lên tàu lượn. Wendy bỗng có một linh cảm lạ về tai nạn kinh hoàng sẽ xảy đến với cô và nhóm bạn. Sợ hãi, Wendy đòi xuống. Vài người đi cùng cũng xuống theo. Và linh cảm của Wendy trở thành sự thật. Chuyến tàu gặp tai nạn... Nhưng đó chỉ mới là sự bắt đầu, bởi tất cả những người đáng lẽ sẽ đi chuyến tàu đó đang phải đối mặt từng ngày với những tai nạn vô tình hoặc ngẫu nhiên có thể cướp đi mạng sống của họ... Wendy và Kevin, một người bạn cùng sống sót sẽ làm thế nào để tự cứu mình và cảnh báo cho những người khác? Chưa kể chuyến tàu cao tốc định mệnh đó còn có cả em gái của Wendy.</p>', 'Full', 1, 'single', 'completed', 19, 2006, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Ryan Merriman","avatar":""},{"name":"Kris Lemche","avatar":""},{"name":"Alexz Johnson","avatar":""},{"name":"Sam Easton","avatar":""},{"name":"Jesse Moss","avatar":""},{"name":"Gina Holden","avatar":""},{"name":"Texas Battle","avatar":""},{"name":"Chelan Simmons","avatar":""},{"name":"Amanda Crew","avatar":""},{"name":"Yan-Kay Crystal Lowe","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Ecstasia Sanders","avatar":""},{"name":"Jody Racicot","avatar":""},{"name":"Patrick Gallagher","avatar":""},{"name":"Maggie Ma","avatar":""},{"name":"Jim Shield","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["مقصد نهایی 3","파이널 데스티네이션 3","โกงความตาย เย้ยความตาย","Destination Ultime 3","死神來了 3","데스티네이션 3: 파이널 데스티네이션","파이널 데스티네이션","絕命終結站3","Ultimate Destination 3","Vlepo to thanato sou 3","Fainaru deddo kôsutâ","Final Dead Coaster","Cheating Death: Final Destination 3","Final Destination 3-D","死神再3來了","Final Destination 3"]', 1784690324522);
