INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trai-toi-va-toi-iii-toi-khong-the-noi-toi-yeu-ban', 'Anh Trai Tôi Và Tôi III: Tôi Không Thể Nói Tôi Yêu Bạn', 'Aniki And Me 3: Switched Hearts', 'https://phimimg.com/upload/vod/20260518-1/1be7652a3d73a728ca95081458d92896.jpg', 'https://phimimg.com/upload/vod/20260518-1/143b6d0e26831340c48e23f8cb4e49af.jpg', '<p>Yuma, một nhân viên công ty thương mại, bận rộn với công việc và đang dần xa cách với vị hôn thê Yoko của mình. Người bạn thời thơ ấu và đồng nghiệp cấp dưới của anh, Atsushi, người coi Yuma như anh trai, là người đồng tính. Nhưng Yuma không biết điều này. Một ngày nọ, Atsushi mời Yuma đến một lễ hội mùa hè. Say xỉn, Yuma ở lại căn hộ của Atsushi. Ánh mắt của Atsushi rơi vào nửa thân dưới của Yuma, khi anh ngủ không có khả năng tự vệ trong bộ yukata của mình. Anh theo bản năng đưa tay ra để chạm vào nó. Ngay lúc đó, Yuma cảm thấy có điều gì đó không ổn và thức dậy. Bực bội khi biết Atsushi là người đồng tính, Yuma về nhà. Ngày hôm sau, khi Atsushi đang xin lỗi Yuma về đêm hôm trước, sấm sét vang lên! Trước khi anh biết điều đó, cơ thể của họ đã bị hoán đổi. Atsushi, trong hình dạng của Yuma, kiểm tra nửa thân dưới của anh trai mình, người mà anh ngưỡng mộ, và bị mê hoặc ngay tại chỗ. Yuma, trong thân xác Atsushi, tái nhợt đi. Hai người buộc phải sống như thế này một thời gian...</p>', 'Full', 1, 'single', 'completed', 20, 2006, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryo Kuraki","avatar":""},{"name":"Yusuke Sakamoto","avatar":""},{"name":"Takami Kazumasa","avatar":""},{"name":"横須賀正一","avatar":""},{"name":"樹かず","avatar":""},{"name":"風間恭子","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Aniki to ore 3: Suki to ienakute","Aniki to ore III: Suki to ienakute","兄貴と俺Ⅲ 好きと言えなくて"]', 1784690324522);
