INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nu-mac-do-prada-yeu-nu-thich-hang-hieu', 'Yêu Nữ Mặc Đồ Prada (Yêu Nữ Thích Hàng Hiệu)', 'The Devil Wears Prada', 'https://phimimg.com/upload/vod/20260513-1/952d8c0323ac34a677a3e8ca8783f4d7.jpg', 'https://phimimg.com/upload/vod/20260513-1/22f062a622d8d6098f47f3beea211555.jpg', '<p>Một sinh viên tốt nghiệp thông minh nhưng nhạy cảm mới làm nghề trợ lý cho Miranda Priestly, tổng biên tập tạp chí thời trang cao cấp. Liệu cô ấy có thể hoàn thành công việc cho Miranda khó tính không?</p>', 'Full', 1, 'single', 'completed', 22, 2006, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Meryl Streep","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Simon Baker","avatar":""},{"name":"Adrian Grenier","avatar":""},{"name":"Tracie Thoms","avatar":""},{"name":"Rich Sommer","avatar":""},{"name":"Daniel Sunjata","avatar":""},{"name":"David Marshall Grant","avatar":""},{"name":"James Naughton","avatar":""},{"name":"Tibor Feldman","avatar":""},{"name":"Rebecca Mader","avatar":""},{"name":"Jimena Hoyos","avatar":""},{"name":"Gisele Bündchen","avatar":""},{"name":"George C. Wolfe","avatar":""},{"name":"John Rothm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["时尚女魔头","Eshmaki atarebs pradas","Vrag nosi Pradu","Ir velnias devi Prada","Diabel ubiera sie u Prady","Diavolul se imbraca de la Prada","Đavo nosi Pradu","Дьявол носит «Prada»","Hudicevka v Pradi","Диявол носить \"Прада\"","Djävulen bär Prada","악마는 프라다를 입는다","O Diabo Veste Prada","Şeytan Marka Giyer","Şeytan Prada Geyiner","穿著Prada的惡魔","穿普拉达的女王","Սատանան կրում է Պրադա","El Diablo Viste a la Moda","El Diablo Viste de Prada","Yêu Nữ Mặc Đồ Prada","Il diavolo veste Prada","Djalli vishet me prada","The Devil Wears Prada"]', 1784690324522);
