INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-nu-mac-do-prada-yeu-nu-thich-hang-hieu', 'Yêu Nữ Mặc Đồ Prada (Yêu Nữ Thích Hàng Hiệu)', 'The Devil Wears Prada', 'yêu nữ mặc đồ prada (yêu nữ thích hàng hiệu) the devil wears prada meryl streep anne hathaway emily blunt stanley tucci simon baker adrian grenier tracie thoms rich sommer daniel sunjata david marshall grant james naughton tibor feldman rebecca mader jimena hoyos gisele bündchen george c. wolfe john rothm 时尚女魔头 eshmaki atarebs pradas vrag nosi pradu ir velnias devi prada diabel ubiera sie u prady diavolul se imbraca de la prada đavo nosi pradu дьявол носит «prada» hudicevka v pradi диявол носить "прада" djävulen bär prada 악마는 프라다를 입는다 o diabo veste prada şeytan marka giyer şeytan prada geyiner 穿著prada的惡魔 穿普拉达的女王 սատանան կրում է պրադա el diablo viste a la moda el diablo viste de prada yêu nữ mặc đồ prada il diavolo veste prada djalli vishet me prada the devil wears prada', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-bi-gian-doan', 'Tình Yêu Bị Gián Đoạn', 'Love, Interrupted', 'https://phimimg.com/upload/vod/20260511-1/0b8645b428d6860c554ed9e4fd22ac13.jpg', 'https://phimimg.com/upload/vod/20260511-1/4b43384f520d7f73d24e7fc4491e30d2.jpg', '<p>Một yêu cầu được gửi đến Sobue, người làm việc trong giới kinh doanh ngầm. Nhiệm vụ là bắt Shiro, một nhân viên đã bỏ trốn cùng tiền thắng cược từ một tiệm pachinko. Cùng với người học việc Katsuya, họ lập tức bắt đầu điều tra. Shiro, đang lẩn trốn, dễ dàng bị phát hiện, nhưng hắn đã trốn thoát được dù bị tấn công. Maggie, chủ một quán bar dành cho người đồng tính, tìm thấy một người đàn ông bất tỉnh trước quán bar và đưa anh ta về nhà. Đó chính là Shiro, người đầy sẹo. Thân hình trần trụi của Shiro rất đẹp và khiến hắn muốn tấn công, nhưng...</p>', 'Full', 1, 'single', 'completed', 17, 2006, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"佐野和宏","avatar":""},{"name":"Shinichiro Toyonaga","avatar":""},{"name":"銀治","avatar":""},{"name":"本多菊次朗","avatar":""},{"name":"吉岡睦雄","avatar":""},{"name":"向夏","avatar":""},{"name":"John A. Michaels","avatar":""},{"name":"Shôko Iroka","avatar":""},{"name":"横須賀正一","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Suteki na kata omoi","素敵な片想い","素敵な片思い"]', 1784690324522);
