INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giai-cuu-toi-phan-3', 'Giải Cứu Tôi (Phần 3)', 'Rescue Me (Season 3)', 'giải cứu tôi (phần 3) rescue me (season 3) denis leary adam ferrara andrea roth john scurti daniel sunjata michael lombardi steven pasquale larenz tate callie thorne 火线救援 rescue me - salvami レスキュー・ミー ニューヨークのえいゆうたち レスキュー・ミー ～ nyの英雄たち rescue me: fdny rescue me', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('30-rock-phan-1', '30 Rock (Phần 1)', '30 Rock (Season 1)', 'https://phimimg.com/upload/vod/20260501-1/a2d03644d8b1c6c80afb4c7d8d733fd2.jpg', 'https://phimimg.com/upload/vod/20260501-1/3dafa5343139fcd2c2e2e200c3d5eb40.jpg', '<p>Liz Lemon đang cố giữ chương trình “TGS” hoạt động thì Jack Donaghy xuất hiện và thay đổi mọi thứ theo hướng thương mại hóa. Đồng thời, Tracy Jordan được đưa vào làm ngôi sao chính, khiến hậu trường trở nên hỗn loạn. Liz bị kẹt giữa việc bảo vệ chất lượng show và chiều lòng sếp, từ đó thiết lập mối quan hệ “đối đầu rồi hợp tác” với Jack.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 17, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tina Fey","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Jack McBrayer","avatar":""},{"name":"Scott Adsit","avatar":""},{"name":"Judah Friedlander","avatar":""},{"name":"Keith Powell","avatar":""},{"name":"Maulik Pancholy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["30 ROCK サーティー･ロック","サーティー･ロック","30 락","30락","30록","30 Rock"]', 1784690324522);
