INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-thu', 'Đường Thư', 'Letter Way', 'https://phimimg.com/upload/vod/20250401-1/b53da8cf2f77a5145fdfb5a9d09fdf75.jpg', 'https://phimimg.com/upload/vod/20250401-1/58b916f66e7f43ff096c9417c10c331a.jpg', '<p>Đường Thư là bộ phim chiến tranh Việt Nam của đạo diễn Bùi Tuấn Dũng với sự tham gia của diễn viên Quốc Tuấn, Tuấn Tú. Trong phim, Tân (Quốc Tuấn đóng) và An (Tuấn Tú đóng) là hai chiến sĩ quân bưu mặt trận, nhận lệnh vận chuyển một công văn thượng khẩn giữa chiến trường ác liệt. &nbsp;Bằng mọi giá họ phải chuyển mật lệnh của cấp trên đến một đơn vị quân giải phóng đang bị địch bao vây ở cao điểm 861, cách chỉ huy sở nhiều ngày đường. Nếu lệnh đến chậm hoặc không đến được, thì cả đơn vị này có nguy cơ bị tiêu diệt. &nbsp;Trên đường đến cao điểm 861, hai chiến sĩ quân bưu – một đã dạn dày trận mạc (Tân) và một là “lính mới” (An) – đã phải đối mặt với muôn vàn khó khăn, gian khổ, hiểm nguy. Phẩm chất gan dạ, mưu trí, dũng cảm và ý thức trách nhiệm của người chiến sĩ quân bưu được bộc lộ qua việc họ xử lý những tình huống, những trở ngại trên “đường thư”. Và họ đã hoàn thành xuất sắc nhiệm vụ, dù phải chấp nhận những hy sinh, tổn thất to lớn…</p>', 'Full', 1, 'single', 'completed', 22, 2006, 'Vietsub', 'HD', 'Việt Nam', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["烽火激战","Đường Thư"]', 1784690324522);
