INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doa-song-hoac-chet', 'DOA: Sống hoặc Chết', 'DOA: Dead or Alive', 'https://phimimg.com/upload/vod/20260318-1/791c86d67a9a93e2e5241cb65426bfd3.jpg', 'https://phimimg.com/upload/vod/20260318-1/a1c2392cb613e90be2c937cb7beeca71.jpg', '<p>Lấy cảm hứng từ series game nổi tiếng Dead or Alive của Tecmo, bộ phim kể về 4 cô gái cực kì quyến rũ, võ thuật cao cường với các biệt danh Sát thủ, Quyền Vương, Vua Trộm, Ninja đều cùng nhận được lời mời bí ẩn tham gia vào một giải đấu trên một hòn đảo kì bí, mà ở đó, chỉ có chiến đấu hết sức mình hoặc là chết...</p>', 'Full', 1, 'single', 'completed', 18, 2006, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Devon Aoki","avatar":""},{"name":"Jaime Pressly","avatar":""},{"name":"Matthew Marsden","avatar":""},{"name":"Holly Valance","avatar":""},{"name":"Sarah Carter","avatar":""},{"name":"Natassia Malthe","avatar":""},{"name":"Kane Kosugi","avatar":""},{"name":"Collin Chou","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Kevin Nash","avatar":""},{"name":"Brian J. White","avatar":""},{"name":"Steve Howey","avatar":""},{"name":"Derek Boyer","avatar":""},{"name":"Silvio Simac","avatar":""},{"name":"Fang Liu","avatar":""},{"name":"Ying Wang","avatar":""},{"name":"Chad McCord","avatar":""},{"name":"Martin Crewes","avatar":""},{"name":"Theodore","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dead Or Alive","D.O.A.: Mort ou vif","DOA - Vivo o Muerto","Elusalt või surnult","डीओए: डेड और अलाइव","DOA デッド・オア・アライブ","DOA: Dzīvi vai miruši","Mrtav ili živ","生死格鬥","디.오