INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-su-hitman-reborn-katekyo-hitman-reborn', 'Gia Sư Hitman Reborn! (Katekyo Hitman Reborn!)', 'REBORN!', 'https://phimimg.com/upload/vod/20260319-1/0951b2aa38ce7dc5eadac3062b287bb6.jpg', 'https://phimimg.com/upload/vod/20260319-1/fae5d3e4be35f270664f4e5aa10b2180.jpg', '<p>Tsuna, một học sinh trung học nhút nhát, là một kẻ thất bại trong cả học tập, thể thao lẫn cuộc sống xã hội. Nhưng mọi thứ xung quanh Tsuna đã hoàn toàn thay đổi khi một đứa trẻ tên Reborn xuất hiện, tự xưng là sát thủ người Ý đến từ gia tộc Vongola! Reborn được cử đến để huấn luyện Tsuna cho cuộc sống tương lai với tư cách là ông trùm mafia của gia tộc!</p>', 'Hoàn Tất (203/203)', 203, 'hoathinh', 'completed', 22, 2006, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yukari Kokubun","avatar":""},{"name":"NEEKO","avatar":""},{"name":"Takashi Kondo","avatar":""},{"name":"Toshinobu Iida","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Yuka Terasaki","avatar":""},{"name":"Junko Takeuchi","avatar":""},{"name":"Satomi Akesaka","avatar":""},{"name":"Suguru Inoue","avatar":""},{"name":"Hidenobu Kiuchi","avatar":""},{"name":"Daisuke Namikawa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["家庭教师HITMAN REBORN！","Katekyo Hitman Reborn","Home Tutor Hitman Reborn","Reborn !","Katei Kyoshi Hitman Reborn!","Katekyo Hitman Reborn!","Katekyou Hitman Reborn!","Учитель-мафиози Реборн!","Hitman Reborn!","Home Tutor Hitman REBORN!","家庭教師ヒットマン REBORN!"]', 1784690324522);
