INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-thap-trang-thien-than-ao-trang', 'Tòa Tháp Trắng (Thiên Thần Áo Trắng)', 'The Hospital', 'https://phimimg.com/upload/vod/20260310-1/aff181100ccbf0239a0c0e20ebc5d31d.jpg', 'https://phimimg.com/upload/vod/20260310-1/1a281ad5d177b8ecd7ea6b75f2f86a2e.jpg', '<p>Bộ phim mang đậm tính hiện thực khốc liệt tại bệnh viện với nhiều thủ đoạn, đấu đá của những bác sỹ mưu cầu quyền lực cũng như là tấm lòng y đức của những thiên thần áo trắng nhân ái thực sự vì bệnh nhân.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 24, 2006, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Ngôn Thừa Húc","avatar":""},{"name":"Trương Quân Ninh","avatar":""},{"name":"Trương Quốc Giai","avatar":""},{"name":"Ngô Mạnh Đạt","avatar":""},{"name":"Dương Cẩn Hoa","avatar":""},{"name":"Đường Trị Bình","avatar":""},{"name":"Đới Lập Nhẫn","avatar":""},{"name":"Trương Huệ Xuân","avatar":""},{"name":"Phí Tường","avatar":""},{"name":"Trương Phục Kiện","avatar":""},{"name":"Hứa An An","avatar":""},{"name":"Tu Kiệt Khải","avatar":""},{"name":"Liêu Ngữ Tình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Hospital","白色巨塔"]', 1784690324522);
