INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toa-thap-trang-thien-than-ao-trang', 'Tòa Tháp Trắng (Thiên Thần Áo Trắng)', 'The Hospital', 'tòa tháp trắng (thiên thần áo trắng) the hospital ngôn thừa húc trương quân ninh trương quốc giai ngô mạnh đạt dương cẩn hoa đường trị bình đới lập nhẫn trương huệ xuân phí tường trương phục kiện hứa an an tu kiệt khải liêu ngữ tình the hospital 白色巨塔', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-nhanh-qua-nguy-hiem-3-duong-dua-tokyo', 'Quá Nhanh Quá Nguy Hiểm 3: Đường Đua Tokyo', 'The Fast and the Furious: Tokyo Drift', 'https://phimimg.com/upload/vod/20260225-1/91a428fe1e688cf3b8ef8241417cd308.jpg', 'https://phimimg.com/upload/vod/20260225-1/daf8ff6191e7bf541a53e17e434b6c93.jpg', '<p>Sean Boswell bị dính líu đến vụ đua xe đường phố tại Los Angeles, cùng một loạt vụ rắc rối với pháp luật trong quá khứ có nguy cơ anh sẽ bị giam giữ. Do đó, mẹ anh đã gửi anh đến chỗ cha mình ở Tokyo, Nhật Bản, người đang là sĩ quan Hải quân Hoa Kỳ. Trong thời gian gặp mặt cha mình ở Tokyo, anh đã bị cảnh báo nếu còn phá phách và liên quan đến đua xe nữa, thì cha anh sẽ gửi trả anh về Mỹ để nhận án tù. Câu chuyện trở nên rắc rối hơn khi Sean phải lòng bạn gái của tay trùm đua xe tại Nhật. Anh mạo hiểm nhận lời thách thức của hắn nhưng thất bại. Và để trả món nợ đó, Sean phải xâm nhập vào thế giới ngầm ở Tokyo, nơi cái giá trả cho những cuộc cá cược không còn tính bằng tiền mà là mạng sống...</p>', 'Full', 1, 'single', 'completed', 22, 2006, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Lucas Black","avatar":""},{"name":"Nathalie Kelley","avatar":""},{"name":"Sung Kang","avatar":""},{"name":"Shad Moss","avatar":""},{"name":"Brian Tee","avatar":""},{"name":"Leonardo Nam","avatar":""},{"name":"Brian Goodman","avatar":""},{"name":"Zachery Ty Bryan","avatar":""},{"name":"Nikki Griffin","avatar":""},{"name":"Jason Tobin","avatar":""},{"name":"Keiko Kitagawa","avatar":""},{"name":"Lynda Boyd","avatar":""},{"name":"Sonny Chiba","avatar":""},{"name":"Damien Marzette","avatar":""},{"name":"Trula M. Marcus","avatar":""},{"name":"Brandon Brendel","avatar":""},{"name":"Daniel Booko","avatar":""},{"name":"David V. Th