INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-dieu-dai-hiep-2006', 'Thần Điêu Đại Hiệp', 'The Return Of The Condor Heroes', 'https://phimimg.com/upload/vod/20250604-1/35d4c0a7899cabb6052d16bfd3de23dc.jpg', 'https://phimimg.com/upload/vod/20250604-1/cbe2cb525c7c7a1609ca89f49ee8124c.jpg', '<p>Thần điêu hiệp lữ là phim dựa trên tiểu thuyết cùng tên của Kim Dung, còn có tên khác là Thần Điêu đại hiệp. Thần điêu hiệp lữ là phần hai trong bộ Xạ điêu tam bộ khúc. Bối cảnh của Thần điêu hiệp lữ là vào cuối thời Nam Tống, khi quân Mông Cổ đã lớn mạnh, tiêu diệt hầu hết châu Á, châu Âu, đang trực tiếp uy hiếp an nguy của Nam Tống.

Câu chuyện xoay quanh tình yêu của hai nhân vật chính là Dương Quá và Tiểu Long Nữ giữa những cuộc chiến tang thương đẫm máu cả trên giang hồ lẫn chiến trường.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 29, 2006, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Huỳnh Hiểu Minh","avatar":""},{"name":"Lưu Diệc Phi","avatar":""},{"name":"Vương Lạc Dũng","avatar":""},{"name":"Khổng Lâm","avatar":""},{"name":"Mạnh Quảng Mĩ","avatar":""},{"name":"Ba Âm","avatar":""},{"name":"Dương Mịch","avatar":""},{"name":"Trần Tử Hàm","avatar":""},{"name":"Cao Hổ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["神雕侠侣 (2006)","신조협려 2006","มังกรหยก ภาค 2","The Return of the Condor Heroes","Thần Điêu Đại Hiệp","神雕侠侣"]', 1784690324522);
