INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-doi-cam-lang', 'Ngọn Đồi Câm Lặng', 'Silent Hill', 'https://phimimg.com/upload/vod/20260123-1/3818a4d6353990b000b5421316818373.jpg', 'https://phimimg.com/upload/vod/20260123-1/f50a7a3b17afb082ec5dbc1bb2aaea86.jpg', '<p>Trên đường đi đưa cô con gái nhỏ Sharon của mình đến 1 nơi chữa bệnh, Rose đã dừng chân tại 1 thành phố hẻo lánh của vùng đồi Silent. Trong lúc còn đang hoang mang trước khung cảnh vắng lặng thì Rose phát hiện ra Sharon đã mất tích. Cố gắng truy tìm dấu vết của con gái, Rose đã phát hiện ra khi màn đêm bao phủ xuống thành phố thì đó cũng là lúc bóng tối trỗi dậy đầy kinh hoàng. Bị mắc bẫy ở 1 nơi chỉ toàn là chết chóc cùng các con quái vật khủng khiếp, liệu Rose có tìm ra cách để cứu Sharon hay không...</p>', 'Full', 1, 'single', 'completed', 24, 2006, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Radha Mitchell","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Jodelle Ferland","avatar":""},{"name":"Laurie Holden","avatar":""},{"name":"Deborah Kara Unger","avatar":""},{"name":"Kim Coates","avatar":""},{"name":"Tanya Allen","avatar":""},{"name":"Alice Krige","avatar":""},{"name":"Nicky Guadagni","avatar":""},{"name":"Maxine Dumont","avatar":""},{"name":"Chris Britton","avatar":""},{"name":"Colleen Williams","avatar":""},{"name":"Ron Gabriel","avatar":""},{"name":"Derek Ritschel","avatar":""},{"name":"Eve Crawford","avatar":""},{"name":"Amanda Hiebert","avatar":""},{"name":"Roberto Campane","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Silent Hill - Willkommen in der Hölle","Terror en Silent 