INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngon-doi-cam-lang', 'Ngọn Đồi Câm Lặng', 'Silent Hill', 'ngọn đồi câm lặng silent hill radha mitchell sean bean jodelle ferland laurie holden deborah kara unger kim coates tanya allen alice krige nicky guadagni maxine dumont chris britton colleen williams ron gabriel derek ritschel eve crawford amanda hiebert roberto campane silent hill - willkommen in der hölle terror en silent hill saylent hill terror em silent hill сайлънт хил 寂静岭 silent hill - a halott város サイレントヒル сайлент хилл klusais kalns tylioji kalva a maldição do vale 사일런트 힐 沉默之丘 sessiz tepe сайлент гілл saylent xill ngọn đồi câm lặng silent hill', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-bao-luc', 'Thành Phố Bạo Lực', 'The City of Violence', 'https://phimimg.com/upload/vod/20260109-1/08f3685af8a8a31b16216f4727bcdbeb.jpg', 'https://phimimg.com/upload/vod/20260109-1/8002350b2e877f0a2896ea095039de7e.jpg', '<p>Taesu, một cảnh sát điều tra tội phạm tại Seoul, không bao giờ quên những tháng ngày sôi động một thời: trốn học, quậy phá, đánh nhau cùng bốn thằng bạn chí cốt Pil Ho, Dong Wan, Seok Hwan, và Wang Jae.Nhận được tin cái chết của Wang Jae, Taesu lập tức rời Seoul quay trở về quê nhà. Mọi thứ đã thay đổi. Kể từ khi Wang Jae trao quyền hành vào tay Pil Ho, sòng bạc trong vùng mọc lên khắp nơi, bọn nhóc côn đồ ngang nhiên quậy phá, hành hung, nghiện ngập.Trước cái chết gây nhiều hoài nghi của người bạn thân, Taesu và Seok Hwan bắt đầu cuộc điều tra tìm kiếm thủ phạm. Hai người không khỏi bất ngờ khi phát hiện ra những việc làm lâu nay người bạn thân thiết của họ Pil Ho ngầm theo đuổi…</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Doo-hong","avatar":""},{"name":"Ryoo Seung-wan","avatar":""},{"name":"Lee Beom-soo","avatar":""},{"name":"Jeong Seok-yong","avatar":""},{"name":"An Kil-kang","avatar":""},{"name":"Kim Seo-hyung","avatar":""},{"name":"Lee Joo-sil","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Jo Deok-hyeon","avatar":""},{"name":"Kim Ki-cheon","avatar":""},{"name":"Kim Hyo-Seon","avatar":""},{"name":"Seo Ji-oh","avatar":""},{"name":"Gu Ja-hoon","avatar":""},{"name":"Lim Jun-Il","avatar":""},{"name":"On Ju-wan","avatar":""},{"name":"Jung Woo","avatar":""},{"name":"Kim Si-hoo","avatar":""},{"name":"Kim Dong-young","avatar":""},{"name":"Park Young","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Jjakpae","짝패","A Cidade da Violência","City of Violence","I poli tis vias","Az erőszak városa","Miasto przemocy","Город насилия","The City of Violence"]', 1784690324522);
