INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-trat-su-muoi-3', 'Tân Trát Sư Muội 3', 'Love Undercover 3', 'https://phimimg.com/upload/vod/20251214-1/afe1100db668719ab7f4afcff5ee625e.jpg', 'https://phimimg.com/upload/vod/20251214-1/a958e6aa1ca821acd8e7d985ad0ea12a.jpg', '<p>Oa là một cô gái 18 tuổi có ý định gia nhập lực lượng cảnh sát. Cô ấy thông minh, tài giỏi và khéo léo nên giành được lợi thế hơn những người khác.Trong một lần, cô cứu được Sếp Chung và đồng đội của anh. Để bày tỏ lòng biết ơn của mình, Sếp Chung đã thuyết phục Oa gia nhập lực lượng cảnh sát với mức lương cao và anh quay trở lại học viện giảng dạy cảnh sát chỉ để hỗ trợ Oa tốt nghiệp thành công. Oa sau đó gia nhập đội của sếp Chung nhưng lại có một nhóm người lười biếng trong nhóm...</p>', 'Full', 1, 'single', 'completed', 18, 2006, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Hiết Khả Kỳ","avatar":""},{"name":"Lăng Thần Nhân","avatar":""},{"name":"Tôn Mỹ","avatar":""},{"name":"Hứa Thiệu Hùng","avatar":""},{"name":"Hoàng Hạo Nhiên","avatar":""},{"name":"Viện Khương Đan","avatar":""},{"name":"Lê Diệu Tường","avatar":""},{"name":"Đào Kiết Quang","avatar":""},{"name":"Hỏa Hỏa","avatar":""},{"name":"Chu Gia Thanh","avatar":""},{"name":"Tào Chấn Hào","avatar":""},{"name":"Tiểm Sắc Lệ","avatar":""},{"name":"Châu Tú Na","avatar":""},{"name":"Trần Văn Cương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Love Undercover 3","新紮師妹3"]', 1784690324522);
