INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-phau-thuat-cua-grey-phan-3', 'Ca Phẫu Thuật Của Grey (Phần 3)', 'Grey''s Anatomy (Season 3)', 'https://phimimg.com/upload/vod/20251104-1/48406ee6d7bacaa0a7c7c734ca0c40fb.jpg', 'https://phimimg.com/upload/vod/20251104-1/48ca923b6165ff35e7cc4f9781db383d.jpg', '<p><span style="text-wrap-mode: wrap;">Bác sĩ thực tập (và sau này là bác sĩ nội trú) Meredith Grey bị cuốn vào những mối quan hệ cá nhân, cũng như quan hệ công việc với các đồng nghiệp ở bệnh viện Seattle.</span></p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 12, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ellen Pompeo","avatar":""},{"name":"Chandra Wilson","avatar":""},{"name":"James Pickens Jr.","avatar":""},{"name":"Kevin McKidd","avatar":""},{"name":"Caterina Scorsone","avatar":""},{"name":"Camilla Luddington","avatar":""},{"name":"Kim Raver","avatar":""},{"name":"Jason George","avatar":""},{"name":"Chris Carmack","avatar":""},{"name":"Anthony Hill","avatar":""},{"name":"Adelaide Kane","avatar":""},{"name":"Alexis Floyd","avatar":""},{"name":"Niko Terho","avatar":""},{"name":"Harry Shum Jr.","avatar":""},{"name":"Trevor Jackson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Anatomia e Greit","A Anatomia de Grey","L''anatomie de Grey","实习医生","Grey''s Anatomy Die jungen Ärzte","Grey''s Anatomy Die jungen Aerzte","Grey''s Anatomy - Die jungen Ärzte","A coeur ouvert","그레이 아나토미","Анатомія пристрасті","Greys Anatomy","Grey''s Anatomy"]', 1784690324522);
