INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ca-phau-thuat-cua-grey-phan-3', 'Ca Phẫu Thuật Của Grey (Phần 3)', 'Grey''s Anatomy (Season 3)', 'ca phẫu thuật của grey (phần 3) grey''s anatomy (season 3) ellen pompeo chandra wilson james pickens jr. kevin mckidd caterina scorsone camilla luddington kim raver jason george chris carmack anthony hill adelaide kane alexis floyd niko terho harry shum jr. trevor jackson anatomia e greit a anatomia de grey l''anatomie de grey 实习医生 grey''s anatomy die jungen ärzte grey''s anatomy die jungen aerzte grey''s anatomy - die jungen ärzte a coeur ouvert 그레이 아나토미 анатомія пристрасті greys anatomy grey''s anatomy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tinh-bao-cib', 'Đội tình báo CIB', 'C.I.B. Files', 'https://phimimg.com/upload/vod/20251023-1/23397a619f9cb547ccbc1f6f672453dc.jpg', 'https://phimimg.com/upload/vod/20251023-1/61cd94f89338c6c6bc535700bf979332.jpg', '<p>Đội tình báo CIB tập trung những con người thông minh, gan dạ trong đó hai anh em Chung Tín, Chung Chính nổi bật bởi sự nhạy bén hơn người. Chung Tín làm việc ở đội phụ trách khai thác thông tin qua điện thoại, giám sát đối tượng để thu thập tin tức. Chung Chính thuộc bộ phận phân tích tin tức từ các trinh sát. Tuy không cùng một tổ nhưng công việc của hai anh em Chung hỗ trợ nhau và giúp đỡ rất nhiều cho phía cảnh sát nhanh chóng bắt được tội phạm. Chung Tín đã lập gia đình và vợ anh là Mỹ lệ. Chung Chính có người yêu tên Tâm Ngôn. Mỹ Lệ và Tâm Ngôn đều là phóng viên và công tác tại cùng một tòa soạn. Ngang tài, ngang sức và cùng có tham vọng quyền lực, giữa hai người luôn có một cuộc cạnh tranh ngầm, gay gắt được che đậy khéo léo bằng thái độ giả lả, thân thiết bên ngoài. Sự mâu thuẫn từ hai người phụ nữ cộng với những áp lực vô hình từ công việc khiến cuộc sống gia đình của Chung Tín và Chung Chính bị ảnh hưởng. Dù là những người đàn ông tài ba, dũng cảm nhưng trước những rắc rối gia đình và rắc rối từ những người phụ nữ yêu thương cả Chung Tín và Chung Chính đều không giải quyết một cách dứt khoát được…</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2006, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Bowie Lam","avatar":""},{"name":"Wong Hei","avatar":""},{"name":"Maggie Shiu","avatar":""},{"name":"Christine Ng Wing-Mei","avatar":""},{"name":"Kenny Wong Tak-Ban","avatar":""},{"name":"Chen Hung-Lieh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["刑事情報科"]', 1784690324522);
