INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('family-guy-phan-5', 'Family Guy (Phần 5)', 'Family Guy (Season 5)', 'family guy (phần 5) family guy (season 5) seth macfarlane alex borstein mila kunis seth green patrick warburton arif zahir გრიფინები keluarga pria مرد خانه خانواده‌ دوست 쇼킹 패밀리 쇼킹패밀리 परिवारको केटा сім’янин ґріффіни family guy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-ra-so-6', 'Lối Ra Số 6', 'Exit No 6', 'https://phimimg.com/upload/vod/20251013-1/085b70fa8ae1887aeed3b740dedc8391.jpg', 'https://phimimg.com/upload/vod/20251013-1/409b534beaaf5a47dcf2a13597698e02.jpg', '<p>Fion và Tiểu Vy là đôi bạn cùng lớn lên từ nhỏ, nhưng luôn bị cha mẹ đem ra so sánh — từ thành tích học tập cho đến khả năng chơi đàn piano. Cả hai từng hứa sẽ chỉ là “bạn tốt thật sự”, không để chuyện thắng thua chen vào tình bạn, và cùng nhau “đóng băng” bản nhạc dự thi trong tủ lạnh để thể hiện quyết tâm đó. Tuy nhiên, trong ngày thi, Fion vẫn hoàn thành phần biểu diễn, trong khi Tiểu Vy phản kháng bằng cách chơi loạn khúc nhạc rồi tức giận bỏ đi đến khu Tây Môn Đinh. Tại đây, cô gặp gỡ Phạm Đạt Ân – một thanh niên buôn hàng rong, và Vance – chàng trai mê trượt ván. Cuộc sống tự do, sôi nổi ở phố phường khiến Tiểu Vy cảm thấy như được sống thật với chính mình. Trong khi đó, Fion lập nhóm mạng “Câu lạc bộ Lá Thu” để tìm bạn. Khi tình cờ gặp lại Tiểu Vy trên phố, cả hai làm hòa và Fion được Tiểu Vy giới thiệu với nhóm bạn mới. Nhưng rồi, tình cảm của hai cô gái lại một lần nữa bị thử thách khi cả hai cùng nảy sinh rung động với Phạm Đạt Ân…</p>', 'Full', 1, 'single', 'completed', 19, 2006, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Bành Vu Yến","avatar":""},{"name":"Nguyễn Kinh Thiên","avatar":""},{"name":"Lưu Hà Na","avatar":""},{"name":"Trần Linh","avatar":""},{"name":"Trương Hàn","avatar":""},{"name":"Lâm Dục Hiền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Liu hao chu kou","六號出口"]', 1784690324522);
