INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-bach-dao', 'Hắc Bạch Đạo', 'On the Edge', 'https://phimimg.com/upload/vod/20251014-1/aa4cd376c1a05dbac2d3f20b1a3a3511.jpg', 'https://phimimg.com/upload/vod/20251014-1/bd4a5370be6492664e6c2c0112f10c3f.jpg', '<p>Sau 8 năm hoạt động ngầm trong một hội tam hoàng, Sheng cuối cùng cũng bắt được thủ lĩnh của hội tam hoàng và tiếp tục nhiệm vụ cảnh sát của mình. Tuy nhiên, cuộc sống không trở lại bình thường khi anh phải đối mặt với sự nghi ngờ của đồng nghiệp và thậm chí còn bị đội điều tra theo dõi. Một ngày nọ, anh gặp một số thành viên Hội Tam Hoàng mà trước đó anh đã kết bạn với tư cách là một đặc vụ chìm và bị ép vào chân tường khi được yêu cầu cộng tác với họ một lần nữa.</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Nick Cheung Ka-Fai","avatar":""},{"name":"Francis Ng Chun-Yu","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Rain Lee Choi-Wah","avatar":""},{"name":"Derek Tsang Kwok-Cheung","avatar":""},{"name":"Calvin Poon Yuen-Leung","avatar":""},{"name":"Lester Chit-Man Chan","avatar":""},{"name":"Chik King-Man","avatar":""},{"name":"Pauline Yam Bo-Lam","avatar":""},{"name":"Raymond Tsang Chau-Ming","avatar":""},{"name":"Ming-Sing Wong","avatar":""},{"name":"Y.Y. Lam","avatar":""},{"name":"Wong Ting Pong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["On The Edge","On The Edge HK","All Life On The Edge","黑白道"]', 1784690324522);
