INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-tau-tuyet-menh', 'Con Tàu Tuyệt Mệnh', 'Poseidon', 'https://phimimg.com/upload/vod/20250930-1/17287bc880b037c243d51a0a8fe93510.jpg', 'https://phimimg.com/upload/vod/20250930-1/22907106eb74b7be71df24a629176e09.jpg', '<p>Poseidon một con tàu lộng lẫy sang trọng được mang tên vị thần cao cả cai quản đại dương – Poseidon. Và đêm nay, khi khoảnh khắc giao thừa đang tích tắc gõ nhịp, khi phòng dạ vũ tưng bừng những điệu nhảy say mê, những ly rượu nồng nàn, con tàu càng trở nên lộng lẫy hơn bao giờ hết. Poseidon quả xứng đáng vị trí độc tôn giữa bắc Đại Tây Dương này. Nhưng rồi một con sóng hung hãn từ đâu ập đến và cả con tàu ngập chìm trong sóng nước lạnh băng. Poseidon đành chấp nhận định mệnh và khép lại cuộc hành trình của mình chăng? Không! Chính lúc này một câu chuyện khác lại mở ra: câu chuyện của những con người mang số phận hoàn toàn khác nhau nhưng có cùng một niềm tin khao khát được sống.</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Josh Lucas","avatar":""},{"name":"Kurt Russell","avatar":""},{"name":"Jacinda Barrett","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"Emmy Rossum","avatar":""},{"name":"Mía Maestro","avatar":""},{"name":"Mike Vogel","avatar":""},{"name":"Kevin Dillon","avatar":""},{"name":"Freddy Rodríguez","avatar":""},{"name":"Jimmy Bennett","avatar":""},{"name":"Fergie","avatar":""},{"name":"Andre Braugher","avatar":""},{"name":"Kirk B.R. Woller","avatar":""},{"name":"Kelly McNair","avatar":""},{"name":"Gabriel Jarret","avatar":""},{"name":"David Reivers","avatar":""},{"name":"Gordon Thomson","avatar":""},{"name":"Jan Mu","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["新海神号历险记","Le Poséidon","The Poseidon Adventure","Poseidon: The IMAX Experience","Poseidón","ポセイドン：2006","Poseidon"]', 1784690324522);
