INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-tau-tuyet-menh', 'Con Tàu Tuyệt Mệnh', 'Poseidon', 'con tàu tuyệt mệnh poseidon josh lucas kurt russell jacinda barrett richard dreyfuss emmy rossum mía maestro mike vogel kevin dillon freddy rodríguez jimmy bennett fergie andre braugher kirk b.r. woller kelly mcnair gabriel jarret david reivers gordon thomson jan mu 新海神号历险记 le poséidon the poseidon adventure poseidon: the imax experience poseidón ポセイドン：2006 poseidon', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-bac-phan-1', 'Linh Hồn Bạc (Phần 1)', 'Gintama (Season 1)', 'https://phimimg.com/upload/vod/20231219-1/c1ebbb1c7a02cb008416f51340f77012.jpg', 'https://phimimg.com/upload/vod/20231219-1/b0d8e40e0f5d9932c4672c3c51d4aacb.jpg', '<p>Đất nước của những Samurai. Có một thời đất nước chúng tôi được gọi như vậy.20 năm trước…Những kẻ ngoài hành tinh tự xưng là Amanto đột ngột đổ bộ xuống và thiết lập lệnh cấm mang kiếm. Samurai giờ đây bị khinh rẻ, coi thường. Trong thời đại như thế, vẫn còn một người đầy tinh thần samurai. Tên anh ta là Sakata Gintoki. Và tôi, Shimura Shinpachi, cùng Kagura-chan vì một số việc đưa đẩy mà bắt đầu làm việc cho cái tên vô trách nhiệm, hảo ngọt đó tại Vạn Sự Ốc. 3 người Vạn Sự Ốc chúng tôi sẽ cùng nhau dọn sạch Edo hủ bại này. Ừm, anime này là vậy thì phải?</p>', 'Hoàn Tất (265/265)', 265, 'hoathinh', 'completed', 137, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324522);
