INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-huong-duong-2006', 'Hoa Hướng Dương', 'Sunflower', 'https://phimimg.com/upload/vod/20250911-1/48898de1df081cded4884891f9ac6e12.jpg', 'https://phimimg.com/upload/vod/20250911-1/ee1ebce0bd7d9ccdebd251ab5dc81c64.jpg', '<p>Tae-sik ra tù sau 10 năm chịu án vì tội giết người, chỉ mong có một cuộc sống bình thường. Một người phụ nữ trong vùng đã dang tay chào đón và coi anh như con trai, giúp anh có cơ hội bắt đầu lại. Thế nhưng, băng nhóm cũ tìm cách phá hủy mái ấm mới để xây hộp đêm. Tae-sik buộc phải đứng lên bảo vệ gia đình mà anh vừa tìm thấy.</p>', 'Full', 1, 'single', 'completed', 18, 2006, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Rae-won","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Huh Yi-jae","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Kim Jung-tae","avatar":""},{"name":"Han Jung-soo","avatar":""},{"name":"Ji Dae-han","avatar":""},{"name":"Park Sung-woong","avatar":""},{"name":"Park Eun-hye","avatar":""},{"name":"Jung Eun-pyo","avatar":""},{"name":"Lee Ho-seong","avatar":""},{"name":"Kim Won-jin","avatar":""},{"name":"Park Cheol-ho","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hae-ba-ra-gi","Sunflower","向日葵","해바라기"]', 1784690324522);
