INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-so-tu-than-2-cai-ten-cuoi-cung', 'Cuốn Sổ Tử Thần 2: Cái Tên Cuối Cùng', 'Death Note 2: The Last Name', 'https://phimimg.com/upload/vod/20250903-1/fa63951fb9b09b7bcdb72cb53df8eb08.jpg', 'https://phimimg.com/upload/vod/20250903-1/8ab0b51aa2b46ee824d0734ece66cfda.jpg', '<p>Ở phần này mặc dù L chấp nhận cho Light cùng hợp tác trong tổ điều tra nhưng anh vẫn nghi ngờ Light chính là KIRA. Mặc khác Light cũng đang tìm cách biết được tên thật của L. &nbsp;Cuốn sổ Death Note của Light cũng đến trang cuối và L sẽ là nạn nhân &quot;chốt danh sách&quot;? Và KIRA có thành công trong ý định làm &quot;trong sạch&quot; thế giới. Trong lúc này lại có một cuốn Death Note thứ 2 xuất hiện...</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tatsuya Fujiwara","avatar":""},{"name":"Takeshi Kaga","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Erika Toda","avatar":""},{"name":"Shigeki Hosokawa","avatar":""},{"name":"Shunji Fujimura","avatar":""},{"name":"Kenichi Matsuyama","avatar":""},{"name":"Sota Aoyama","avatar":""},{"name":"Magi","avatar":""},{"name":"Shinnosuke Ikehata","avatar":""},{"name":"Alexa Devine","avatar":""},{"name":"Godai Michiko","avatar":""},{"name":"Itsuji Itao","avatar":""},{"name":"Nana Katase","avatar":""},{"name":"Miyuki Komatsu","avatar":""},{"name":"Ai Maeda","avatar":""},{"name":"Hikari Mitsushima","avatar":""},{"name":"Ik","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d