INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-so-tu-than-2006', 'Cuốn Sổ Tử Thần', 'Death Note', 'https://phimimg.com/upload/vod/20250903-1/3f519b3b5cfe94eff75bbd7bc872c3fc.jpg', 'https://phimimg.com/upload/vod/20250903-1/651024688832c905d75d74cb881face2.jpg', '<p>Yagami Raito là một sinh viên đại học bình thường. Một ngày nọ, cậu nhận được một quyển sổ làm đảo lộn cuộc sống của mình. Quyển sổ thức tỉnh ý thức công lý và khả năng thiên tài tiềm ẩn trong cậu. Cậu trở thành kẻ giết người Kira, dùng quyển sổ trừng phạt bọn tội phạm hung ác. &nbsp;L là một thám tử tư nổi tiếng. L nhận định Kira là kẻ xấu và quyết tâm bắt Kira. Sau đó, N, một người có vẻ ngoài xinh đẹp nhưng vô cùng nguy hiểm, xuất hiện.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tatsuya Fujiwara","avatar":""},{"name":"Kenichi Matsuyama","avatar":""},{"name":"Asaka Seto","avatar":""},{"name":"Shigeki Hosokawa","avatar":""},{"name":"Erika Toda","avatar":""},{"name":"Shunji Fujimura","avatar":""},{"name":"Takeshi Kaga","avatar":""},{"name":"Yuu Kashii","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Sota Aoyama","avatar":""},{"name":"Norman England","avatar":""},{"name":"Godai Michiko","avatar":""},{"name":"Miyuki Komatsu","avatar":""},{"name":"Matt Lagan","avatar":""},{"name":"Sarutoki Minagawa","avatar":""},{"name":"Hikari Mitsushima","avatar":""},{"name":"Takeo N","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Тетрадь смерти","死亡笔记","死亡笔记 I",