INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xmen-3-phan-xet-cuoi-cung', 'X-Men 3: Phán Xét Cuối Cùng', 'X-Men: The Last Stand', 'https://phimimg.com/upload/vod/20250817-1/2978955c7d763ac05c01d1d15fe25337.jpg', 'https://phimimg.com/upload/vod/20250817-1/fa40c39ee00b0c8fab9d01363afc7389.jpg', '<p>Phim X-men 3: The Last Stand 2006 tiếp nối 2 phần trước. Nhưng lần này, cộng đồng những người bị đột biến đứng trước ngã ba đường: phải lựa chọn tiếp tục cuộc sống bị xã hội xa lánh để giữ lại những sức mạnh độc nhất tạo hoá ban tặng, hoặc từ bỏ tất cả để hoà nhập trong cuộc sống bình thường. Mâu thuẫn bắt đầu giữa người đứng đầu dị nhân Chales Xavier và Eric Lehnsherr khi một người ủng hộ chủ trương một người vì mọi người còn một người lại khăng khăng kẻ mạnh nhất sẽ chiến thắng. Và liều thuốc hoá giải cho người đột biến những tưởng là con đường giải thoát họ lại trở thành nguyên nhân gián tiếp đưa cả dị nhân và thường nhân vào cuộc đấu tranh quyết liệt. Diễn viên góp mặt gồm có Hugh Jackma, Patrick Stewart, Ian McKellen, Famke Janssen, James Marsden với Bryan Singer là đạo diễn. Một cuộc chiến để kết thúc tất cả, để đưa ra một phán quyết cuối cùng…</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Ian McKellen","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Shawn Ashmore","avatar":""},{"name":"Elliot Page","avatar":""},{"name":"Anna Paquin","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Aaron Stanford","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Michael Murphy","avatar":""},{"name":"Rebecca Romijn","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Dania Ramirez","avatar":""},{"name":"Shohreh Aghdashloo","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["X-Men 3","X戰警3：最後戰役","Люди Икс Последняя битва","X-men 3 - L''Affrontement Final","X-Men 3: The Last Stand","X-Men 3: O Confronto Final","X-Men III: The Last Stand","X-Men 3 - O Confronto Final","X-Men: La Batalla Final","X-Men 3 - Conflitto finale","X战警3：背水一战","G‘aroyib odamlar 3: So‘ngi intiqom","X-מן 3: המפלט האחרון","X-Men : L''Engagement Ultime","Iks-odamlar 3","X-Men 3: La decisión final","X-Men III: La Batalla Final","變種特攻3","Dị Nhân 3: Phán Xét Cuối Cùng","X-Men 3: Son Direniş","X战警3","X-Men: The Last Stand"]', 1784690324522);
