INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xmen-3-phan-xet-cuoi-cung', 'X-Men 3: Phán Xét Cuối Cùng', 'X-Men: The Last Stand', 'x-men 3: phán xét cuối cùng x-men: the last stand hugh jackman patrick stewart ian mckellen famke janssen halle berry kelsey grammer shawn ashmore elliot page anna paquin vinnie jones aaron stanford ben foster michael murphy rebecca romijn james marsden dania ramirez shohreh aghdashloo c x-men 3 x戰警3：最後戰役 люди икс последняя битва x-men 3 - l''affrontement final x-men 3: the last stand x-men 3: o confronto final x-men iii: the last stand x-men 3 - o confronto final x-men: la batalla final x-men 3 - conflitto finale x战警3：背水一战 g‘aroyib odamlar 3: so‘ngi intiqom x-מן 3: המפלט האחרון x-men : l''engagement ultime iks-odamlar 3 x-men 3: la decisión final x-men iii: la batalla final 變種特攻3 dị nhân 3: phán xét cuối cùng x-men 3: son direniş x战警3 x-men: the last stand', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-day-phan-4', 'Đường Dây (Phần 4)', 'The Wire (Season 4)', 'https://phimimg.com/upload/vod/20250816-1/86882df2f330f3300a48f559b2ae1216.jpg', 'https://phimimg.com/upload/vod/20250816-1/9defc7e98616332c4a11452098a89307.jpg', '<p>Tác phẩm này đã được tạp chí điện ảnh lớn nhất thế giới Empire đưa vào danh sách bình chọn Top 50 phim truyền hình hay nhất mọi thời đại và từng là TV series ăn khách nhất của đài HBO. Mỗi mùa phim lại tập trung vào một khía cạnh trong thành phố Baltimore như buôn bán ma túy bất hợp pháp, hệ thống cảng biển, thành phố, bộ máy quan liêu, hệ thống trường học và các phương tiện truyền thông đại chúng.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 12, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dominic West","avatar":""},{"name":"Lance Reddick","avatar":""},{"name":"Sonja Sohn","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"Michael Kenneth Williams","avatar":""},{"name":"Deirdre Lovejoy","avatar":""},{"name":"J.D. Williams","avatar":""},{"name":"John Doman","avatar":""},{"name":"Jamie Hector","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Seth Gilliam","avatar":""},{"name":"Domenick Lombardozzi","avatar":""},{"name":"Corey Parker Robinson","avatar":""},{"name":"Isiah Whitlock","avatar":""},{"name":"Jr.","avatar":""},{"name":"Michael Kostroff","avatar":""},{"name":"Re","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["火线重案组","The Wire","وایر"]', 1784690324522);
