INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-kinh-hai-3', 'Mùa Hè Kinh Hãi 3', 'I''ll Always Know What You Did Last Summer', 'https://phimimg.com/upload/vod/20250815-1/94c5449c93d052a294adaf5a4c93e1a7.jpg', 'https://phimimg.com/upload/vod/20250815-1/42804602e3234bd9a8717708ff859e03.jpg', '<p>Khi trò đùa đơn giản vào ngày Quốc khánh 4/7 biến thành thảm kịch chết chóc, hội bạn cảnh giác chôn vùi bí mật của họ. Nhưng rồi kẻ bí ẩn đeo mặt nạ đe dọa trả thù.</p>', 'Full', 1, 'single', 'completed', 9, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brooke Nevin","avatar":""},{"name":"David Paetkau","avatar":""},{"name":"Torrey DeVitto","avatar":""},{"name":"Ben Easter","avatar":""},{"name":"Seth Packard","avatar":""},{"name":"K.C. Clyde","avatar":""},{"name":"Clayton Taylor","avatar":""},{"name":"Michael Flynn","avatar":""},{"name":"Don Shanks","avatar":""},{"name":"Britt Leary","avatar":""},{"name":"Star LaPoint","avatar":""},{"name":"Junior Richard","avatar":""},{"name":"Levi Whitlock","avatar":""},{"name":"Chad Chiniquy","avatar":""},{"name":"Manny Slack","avatar":""},{"name":"James Jamison","avatar":""},{"name":"Brett Yoder","avatar":""},{"name":"Daniel Drysdale","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Eu sempre vou saber o que você fizeram no verão passado","Siempre sabré lo que hiciste el verano pasado","나는 언제나 네가 지난 여름에 한 일을 알고 있을 것이다","Siempre sabré lo que hicisteis el último verano","I Know What You Did Last Summer 3","Siempre sabré lo que hicieron el verano pasado","I''ll Always Know What You Did Last Summer","Souviens-toi... l''é