INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mua-he-kinh-hai-3', 'Mùa Hè Kinh Hãi 3', 'I''ll Always Know What You Did Last Summer', 'mùa hè kinh hãi 3 i''ll always know what you did last summer brooke nevin david paetkau torrey devitto ben easter seth packard k.c. clyde clayton taylor michael flynn don shanks britt leary star lapoint junior richard levi whitlock chad chiniquy manny slack james jamison brett yoder daniel drysdale eu sempre vou saber o que você fizeram no verão passado siempre sabré lo que hiciste el verano pasado 나는 언제나 네가 지난 여름에 한 일을 알고 있을 것이다 siempre sabré lo que hicisteis el último verano i know what you did last summer 3 siempre sabré lo que hicieron el verano pasado i''ll always know what you did last summer souviens-toi... l''été dernier iii le pacte du silence : jusqu’à la mort i will always know what you did last summer uvijek ću znati što si radila prošlog ljeta keçən yay neylədiyini həmişə biləcəm', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-truong-ba-da-hang-thit', 'Hồn Trương Ba Da Hàng Thịt', 'Trương Ba''s Soul In The Butcher''s Body', 'https://phimimg.com/upload/vod/20250812-1/f0bfc802a803a1eb0b94d9d91f382f5f.jpg', 'https://phimimg.com/upload/vod/20250812-1/79ff1ca017d12370d7c3331f66709511.jpg', '<p>Phim dựa theo điển tích về chuyện chàng Trương Ba nho nhã trong xác anh Hàng Thịt. Trong Hồn Trương Ba, Da Hàng Thịt &quot;phiên bản 2006&quot;, Trương Ba (Johnny Trí Nguyễn) lịch lãm, phong lưu, nổi tiếng trong các vũ trường, được quý cô, quý bà và cả giới đồng tính mê mệt; còn Sang Hàng Thịt (Phước Sang) là người chí thú làm ăn với lò mổ gia truyền.</p>', 'Full', 1, 'single', 'completed', 19, 2006, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Johnny Trí Nguyễn","avatar":""},{"name":"Anh Thư","avatar":""},{"name":"Phước Sang","avatar":""},{"name":"Phương Thanh","avatar":""},{"name":"Lương Mạnh Hải","avatar":""},{"name":"Hiếu Hiền","avatar":""},{"name":"Minh Thuận","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hồn Trương Ba, da hàng thịt"]', 1784690324522);
