INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-than-tiet-khi-su-cuoi-cung-cuon-2-tho', 'Thế Thần: Tiết Khí Sư Cuối Cùng (Cuốn 2: Thổ)', 'Avatar: The Last Airbender (Book Two: Earth)', 'thế thần: tiết khí sư cuối cùng (cuốn 2: thổ) avatar: the last airbender (book two: earth) zach tyler eisen mae whitman jack de sena dante basco jessie flower dee bradley baker avatar: de legende van aang avatar - a lenda de aang avatar - the last airbender avatar: la leyenda de aang avatar: el último maestro aire 降世神通: 最後的氣宗 降世神通：最后的气宗 avatar: the legend of aang ავატარი: ჰაერის უკანასკნელი მბრძანებელი άβαταρ: ο τελευταίος μαχητής του ανέμου άβαταρ: ο τελευταίος ανεμοδαμαστής avatár - aang legendája avatar: an taer-lúbóir deiridh אווטאר: האגדה של אנג آواتار: افسانه آنگ آواتار: آخرین باد افزار avatar - la leggenda di aang アバター 伝説の少年アン 아바타: 아앙의 전설 awatar: legenda aanga avatar: o último airbender (2005) avatar: legenda lui aang آفاتار: مسخر الهواء الأخير avatar atla avatar: the last airbender', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-an-nha-thanh', 'Kỳ Án Nhà Thanh', 'A Pillow Case Of Mystery', 'https://phimimg.com/upload/vod/20250716-1/c134f8dc65789a3643ee02600dbc8860.jpg', 'https://phimimg.com/upload/vod/20250716-1/6c342124c88b27c64cb37f7a047736bf.jpg', '<p>Lấy bối cảnh vào đầu thế kỷ thứ 19, nội dung của phim Kỳ Án Nhà Thanh xoay quanh anh chàng Thi Thế Luân (Âu Dương Chấn Hoa), cha cậu vốn là tướng sĩ triều đình Thi Lang. Lúc nhỏ, Thi Thế Luân đã cho thấy tố chất hơn người của mình, không chỉ là một cậu bé thông minh mà còn rất lanh lợi và mồm mép. Năm 8 tuổi, cậu tận mắt chứng kiến cảnh một gia đình bị thảm sát. Kể từ thời điểm đó, cảnh tượng hãi hùng đó, nó đã in sâu vào tâm trí của cậu bé, nó trở thành nỗi ám ảnh luôn đeo bám trong suốt cuộc đời cậu. Trong khi đó, bởi được mẹ là Triệu Nguyệt Nga (Lý Phong) hết mực cưng chiều, nên càng lớn Thi Thế Luân càng ỷ lại và lười biếng. Khi lớn lên Thi Thế Luân, được bổ nhiệm làm quan chi huyện, anh vô tình bắt gặp một linh hồn, kèm theo trong một cái gối phép thuật, người giúp anh ta giải quyết các vụ án. Từ đó, Thế Luân trở thành Gối Thần Kỳ Án ở trong vùng. Sau một loạt các vụ án chưa được giải quyết, người dân trong trấn bắt đầu để xem anh ta là vị quan vô dụng. Trong khi Thế Luân tìm kiếm bằng chứng của một vụ án, anh ta vô tình bị thương và máu của anh bị nhỏ trên chiếc gối bí ẩn. Anh ngất xỉu và trong giấc mơ anh được gặp thần gối Đường Đa Phước, người giúp anh ta có thể giải mã những bí ẩn trong các vụ án, giúp anh nhanh chóng lấy được niềm tin của người dân trong vùng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 14, 2006, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Hạo Dân","avatar":""},{"name":"Tuyên Huyên","avatar":""},{"name":"Âu Dương Chấn Hoa","avatar":""},{"name":"Tạ Thiên Hoa","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Pillow Case of Mystery","施公奇案"]', 1784690324522);
