INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-dat-lien-va-dai-duong', 'Huyền Thoại Đất Liền Và Đại Dương', 'Tales From Earthsea', 'https://phimimg.com/upload/vod/20250716-1/8aa9bab56fd2920a08d6431447bf97cd.jpg', 'https://phimimg.com/upload/vod/20250716-1/91305912ed68e8295384b25146166633.jpg', '<p>Thế giới dần suy tàn, Đại pháp sư đưa vị hoàng tử mang trong lòng nhiều trăn trở và cả ác tâm lên đường tìm kiếm ngọn nguồn cái ác, cứu lấy những người con gái họ yêu.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2006, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Junichi Okada","avatar":""},{"name":"Aoi Teshima","avatar":""},{"name":"Bunta Sugawara","avatar":""},{"name":"Yuko Tanaka","avatar":""},{"name":"Teruyuki Kagawa","avatar":""},{"name":"Jun Fubuki","avatar":""},{"name":"Takashi Naito","avatar":""},{"name":"Mitsuko Baisho","avatar":""},{"name":"Yui Natsukawa","avatar":""},{"name":"Kaoru Kobayashi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["地海战纪","Tales from Earthsea","게드전기","Ιστορίες από τη Γαιοθάλασσα","סיפורי ארץ-ים","地海传说","Contos de Terramar","Gedo senki","ゲド戦記"]', 1784690324522);
