INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyen-thoai-dat-lien-va-dai-duong', 'Huyền Thoại Đất Liền Và Đại Dương', 'Tales From Earthsea', 'huyền thoại đất liền và đại dương tales from earthsea junichi okada aoi teshima bunta sugawara yuko tanaka teruyuki kagawa jun fubuki takashi naito mitsuko baisho yui natsukawa kaoru kobayashi 地海战纪 tales from earthsea 게드전기 ιστορίες από τη γαιοθάλασσα סיפורי ארץ-ים 地海传说 contos de terramar gedo senki ゲド戦記', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-mat-ngot', 'Ngôi Nhà Mật Ngọt', 'At Home With Love', 'https://phimimg.com/upload/vod/20250617-1/6664b8b2ea6791ab3d4570ce7f76fb9a.jpg', 'https://phimimg.com/upload/vod/20250617-1/b8f1bfaac3102f1d7afef5a32abc65bb.jpg', '<p>Có cả sự nghiệp lẫn tình yêu là mong muốn của rất nhiều người. Nhưng, hai điều này rất khó vẹn toàn. Nhân vật chính của “Ngôi nhà mật ngọt” đang lâm vào hoàn cảnh tương tự, khi phải chọn giữ lại người yêu hay tiếp tục thăng tiến. Chung Chí Lương (do Ngô Khải Hoa đóng) và Từ Chỉ Linh (do Mông Gia Tuệ đóng) đến với nhau do sự tác hợp của cha Lương – ông Chung Bang (do Chung Cảnh Huy đóng). Sau khi ông Bang về hưu, Lương đã tiếp quản công ty bất động sản của ba. Đồng thời, ông Bang còn giới thiệu Linh vào làm. Nhờ vậy, Linh trở thành bạn gái của Lương. Lâu nay, vì quá mải mê với công việc mà quan hệ của Lương và ba ngày càng xa cách. Chính Linh là người đứng giữa, gắn kết hai ba con lại gần nhau hơn. Không khí gia đình dần trở nên đầm ấm. Lương và Linh ngỡ rằng sẽ có một cái kết đẹp. Nào ngờ, Linh bỗng thay đổi như một người khác. Cô luôn đặt chuyện tiền bạc lên hàng đầu. Thậm chí, Linh còn sẵn sàng rời bỏ công ty của Lương để qua công ty đối thủ làm việc. Lương sẽ làm gì để cứu vãn mối quan hệ này?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2006, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ngô Khải Hoa","avatar":""},{"name":"Mông Gia Tuệ","avatar":""},{"name":"Chung Cảnh Huy","avatar":""},{"name":"Tào Vĩnh Liêm","avatar":""},{"name":"Hồ Định Hân","avatar":""},{"name":"Đàm Tiểu Hoàn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["At home with love","樓住有情人"]', 1784690324522);
