INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-luu-vong', 'Sát Thủ Lưu Vong', 'Exiled', 'https://phimimg.com/upload/vod/20250707-1/ffc0b1549e961af8f728532b11640984.jpg', 'https://phimimg.com/upload/vod/20250707-1/5a54ec745ff849b4e47232f53947819e.jpg', '<p>Một nhóm năm sát thủ gồm Hòa, Miêu, Ba, Hỏa và Thái chơi thân với nhau, cùng làm việc dưới trướng ông trùm thế lực. Bỗng một ngày, Hòa đột ngột &quot;rửa tay gác kiếm&quot; và đưa vợ con sang Ma Cao. Ông trùm Đại Phi đã cử Hỏa và Ba đến giết Hòa, nhưng họ gặp lại Miêu và Thái, những người muốn bảo vệ Hòa, cả nhóm quyết định tái hợp. Ông trùm càng thêm căm phẫn, quyết tâm tiêu diệt tất cả. Sau khi Hòa bị sát hại, bốn sát thủ còn lại thề sẽ trả thù. Cuộc chiến cuối cùng giữa cả nhóm và hai thế lực đối đầu bao gồm cả Đại Phi và trùm Quyền Cường bắt đầu.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Trương Gia Huy","avatar":""},{"name":"Lâm Tuyết","avatar":""},{"name":"Huỳnh Thu Sinh","avatar":""},{"name":"Ngô Chấn Vũ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["放逐","Fong juk","エグザイル／絆：2006","放‧逐"]', 1784690324522);
