INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-thu-luu-vong', 'Sát Thủ Lưu Vong', 'Exiled', 'sát thủ lưu vong exiled trương gia huy lâm tuyết huỳnh thu sinh ngô chấn vũ 放逐 fong juk エグザイル／絆：2006 放‧逐', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-kiem-ha-thien-son', 'Thất Kiếm Hạ Thiên Sơn', 'Seven Swordsmen', 'https://phimimg.com/upload/vod/20250611-1/c086d45772c792ea2f05f8c7b9d9ada9.jpg', 'https://phimimg.com/upload/vod/20250611-1/5ca7d066affe2b3399263031f35e53d8.jpg', '<p>Bối cảnh phim được lấy vào giữa thế kỷ thứ 17, lúc này người Mãn Châu chinh phục các lãnh thổ của nhà Minh cũ và thành lập nên triều Thanh. Lo sợ rằng võ lâm (những võ sĩ và kiếm khách) sẽ đe dọa họ, chính quyền nhà Thanh thông qua lệnh cấm võ thuật cấm người dân thường tập luyện võ thuật và sở hữu vũ khí, vì thế những thanh kiếm trên giang hồ ngày càng trở nên khan hiếm, người luyện võ không dùng kiếm, người rèn kiếm phải bỏ nghề.

Chính quyền ngày càng lộng hành, nạn cướp bóc ngày một nhiều do người dân không có vũ khí để tự vệ, khi mọi thứ ngày một tồi tệ hơn cũng là lúc trên giang hồ xuất hiện Thất Kiếm Khách cùng những thanh kiếm “có một không hai” như Giao Long Kiếm, Can Kiếm và Cảnh Tinh Kiếm, đủ để bảo vệ những ngôi làng, những người dân khỏi sự chết chóc…</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 33, 2006, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Văn Trác","avatar":""},{"name":"Vương Học Binh","avatar":""},{"name":"Thái Thiếu Phân","avatar":""},{"name":"Lí Tiểu Nhiễm","avatar":""},{"name":"Kiều Chấn Vũ","avatar":""},{"name":"Vương Lệ Khôn","avatar":""},{"name":"Lữ Lương Vĩ","avatar":""},{"name":"Tôn Phi Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["Seven Swordsmen","칠검하천산","Seven Swords of Mount Heaven","七剑下天山"]', 1784690324522);
