INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-nha-ma-quai', 'Ngôi Nhà Ma Quái', 'Monster House', 'ngôi nhà ma quái monster house mitchel musso sam lerner spencer locke steve buscemi maggie gyllenhaal kevin james nick cannon jon heder jason lee catherine o''hara fred willard kathleen turner ryan whitney woody schultz ian mcconnel erik walker matthew fahey mariss monster house 3d rém rom 3d къща-чудовище 魔怪屋 straszny dom 怪獸屋 la maison monstre draugahúsið 怪兽小屋 monster house', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chay-an-phan-1', 'Chạy Án (Phần 1)', 'Chay An (Season 1)', 'https://phimimg.com/upload/vod/20250604-1/e43bb1fa07e1f5c3dec04d5258a4559c.jpg', 'https://phimimg.com/upload/vod/20250604-1/7473121614403fa143bf0b82c577f70e.gif', '<p>Lấy cảm hứng từ vụ án Mai Văn Dâu, Chạy án tập trung vào cuộc đời của Cao Thanh Lâm (Việt Anh), con trai của Thứ trưởng Cao Đức Cẩm, học Thạc sĩ Tin học ở Mỹ và sau đó trở về nắm giữ vị trí Trưởng phòng thương mại điện tử ở ngân hàng Phú Tài do ông Trương Ngọc Trác đứng đầu. Tuy ông Cẩm là một cán bộ mẫu mực, đứng đắn, nhưng lại nhu nhược, để cho vợ là Dung thao túng gia đình, dựa vào danh nghĩa của chồng để làm ăn quan hệ với những doanh nghiệp trong tỉnh, và để Lâm được nuông chiều quá mức. Sau khi trở về, không những Lâm không thay đổi mà còn cấu bè kết phái với các phần tử bất hảo, chơi bời và dây vào xã hội đen khiến gia đình điêu đứng và gây ra những nguy hại về sau...</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 14, 2006, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Việt Anh","avatar":""},{"name":"Phan Hòa","avatar":""},{"name":"Lê Dũng Nhi","avatar":""},{"name":"NSƯT Hương Dung","avatar":""},{"name":"Nguyễn Văn Báu","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324522);
