INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hop-dem-shortbus', 'Hộp Đêm Shortbus', 'Shortbus', 'https://phimimg.com/upload/vod/20250526-1/3f3040fb15e54e7f83a5675b5f4cc4aa.jpg', 'https://phimimg.com/upload/vod/20250526-1/d38b4809ce1726a78c97ecb777105cec.jpg', '<p>Lấy bối cảnh ở thành phố New York đương đại, Shortbus xoay quanh Sofia Lin ( Sook-Yin Lee ), người đã kết hôn với Rob (Raphael Barker) đẹp trai nhưng không tham vọng và hơi lém lỉnh. Cô ấy làm tư vấn cho các cặp đôi / nhà trị liệu tình dục . Cô tiếp xúc với một cặp vợ chồng: một cựu ngôi sao nhí Jamie ( PJ DeBoy ) hơi tự cao tự đại và cựu nhân viên tình dục James ( Paul Dawson ), nhân vật chính khác của bộ phim. Ngay từ đầu, James gợi ý với bạn trai rằng họ nên công khai mối quan hệ của mình để quan hệ tình dục với người khác. Trong lần tư vấn đầu tiên của họ, Sofia bắt bẻ, tát Jamie, và sau đó nói lời xin lỗi tiết lộ về &quot;cơn cực khoái trước&quot; của côtrạng thái. Cặp đôi gợi ý cô ấy tham dự một tiệm thẩm mỹ xã hội / nghệ thuật / tình dục hàng tuần ở Brooklyn có tên &quot;Shortbus&quot;, do nghệ sĩ kéo Justin Bond (chơi vs chính mình) chủ trì. Sofia từ từ mở ra những trải nghiệm mới; điều này bao gồm một tình bạn với một người thống trị tên là Severin ( Lindsay Beamish ). Việc Sofia không thể đạt được cực khoái bắt đầu gây ra xung đột với Rob, người lần lượt bắt đầu tham dự Shortbus với Sofia.</p>', 'Full', 1, 'single', 'completed', 27, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sook-Yin Lee","avatar":""},{"name":"Paul Dawson","avatar":""},{"name":"PJ DeBoy","avatar":""},{"name":"Lindsay Beamish","avatar":""},{"name":"Jay Brannan","avatar":""},{"name":"Raphael Barker","avatar":""},{"name":"Adam Hardman","avatar":""},{"name":"Peter Stickles","avatar":""},{"name":"Alan Mandell","avatar":""},{"name":"Stephen Kent Jusick","avatar":""},{"name":"David Pittu","avatar":""},{"name":"Jeff Whitty","avatar":""},{"name":"Mickey Cottrell","avatar":""},{"name":"Mary Beth Peil","avatar":""},{"name":"Shanti Carson","avatar":""},{"name":"Jan Hilmer","avatar":""},{"name":"Justin Vivian Bond","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["性爱巴士","Shortbus - Dove tutto è permesso","The Sex Film Project","Tu última parada","Шортбъс","Клуб Shortbus","숏버스","Клуб «Микроавтобус»","短巴士","Shortbus"]', 1784690324522);
