INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-baby', 'Kế Hoạch Baby', 'Rob-B-Hood', 'https://phimimg.com/upload/vod/20250523-1/24b7ff9fd4a407d9039af3090da7c99f.jpg', 'https://phimimg.com/upload/vod/20250523-1/ae23a0ca2fd6284c375d2f67ff5af76a.jpg', '<p>Kế Hoạch Baby kể về 3 tên trộm, cùng chung một mục đích hám tiền, gặp nhau lập thành một nhóm chuyên trộm két bẻ khóa, khoét vách kiếm tiền nhưng cả 3 tên ăn trộm đều có những mục đích tiêu tiền khác nhau, kẻ cờ bạc, kẻ bao gái, kẻ tích góp để dành. Trong một phi vụ không trót lọt,cảnh sát dí chạy dài, tên cầm đầu lại bị hốt, bất đắc dĩ 2 kẻ còn lại phải ôm theo một em bé con gia chủ hòng thực hiện kế hoạch tống tiền nhưng giờ lại phải thay nhau chăm sóc cho đứa bé suốt ngày khóc thét kia. Và từ từ, sự thơ ngây của đứa trẻ đã khiến 3 tên quay trở lại con đường lương thiện....</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Thành Long","avatar":""},{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Hứa Quán Văn","avatar":""},{"name":"Nguyên Bưu","avatar":""},{"name":"Teresa Carpio","avatar":""},{"name":"Cao Viên Viên","avatar":""},{"name":"Doãn Tử Duy","avatar":""},{"name":"Trần Bảo Quốc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Project BB","Rob-B-Hood","Akce nemluvně","宝贝计划","Dos ladrones y medio","Robin B Hood","Rob-B-Hood - Das 30 Millionen Dollar Baby","Rob B Hood","Jackie Chan: Rob-B-Hood","2 Ladrones y medio","プロジェクトBB","Três Ladrões e Um Bebê","寶貝計劃","Baby","R