INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-hoach-baby', 'Kế Hoạch Baby', 'Rob-B-Hood', 'kế hoạch baby rob-b-hood thành long cổ thiên lạc hứa quán văn nguyên bưu teresa carpio cao viên viên doãn tử duy trần bảo quốc jackie chan project bb rob-b-hood akce nemluvně 宝贝计划 dos ladrones y medio robin b hood rob-b-hood - das 30 millionen dollar baby rob b hood jackie chan: rob-b-hood 2 ladrones y medio プロジェクトbb três ladrões e um bebê 寶貝計劃 baby robin-b-hood сокровище в пелёнках bo bui gai wak bb 프로젝트 ke hoach bat coc', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-chu-khung-long-cua-nobita', 'Doraemon: Chú Khủng Long của Nobita', 'Doraemon: Nobita''s Dinosaur', 'https://phimimg.com/upload/vod/20250521-1/4df92776d44f885264fa2136cdd76ae8.jpg', 'https://phimimg.com/upload/vod/20250521-1/39ad1898c1c6dc933ca932e4e1b7bc86.jpg', '<p>Nobita tình cờ tìm được một quả trứng khủng long hóa thạch, cậu dùng bảo bối &quot;Khăn trùm thời gian&quot; đưa quả trứng trở về thời điểm 100 triệu năm trước và ấp cho trứng nở để khoe với bạn bè mình. Nỗ lực của Nobita đã thành công khi chú khủng long thuộc chi Mamenchisaurus (xà đầu long) chào đời, được cậu đặt tên là Pisuke. Nobita và Doraemon bí mật chăm sóc Pīsuke đến khi khủng long trưởng thành, tình cảm của cậu dành cho khủng long cũng tăng dần theo thời gian. Đến khi Pisuke không thể sống vừa trong nhà nữa, Nobita phải nuôi khủng long ở hồ nước trong công viên, không may cư dân thành phố đã phát hiện ra và tiến hành chiến dịch truy bắt; Nobita và Doraemon đành thả Pīsuke về lại quê hương ở Kỷ Phấn trắng.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2006, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Eiichiro Funakoshi","avatar":""},{"name":"Kenji Utsumi","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Yasunori Matsumoto","avatar":""},{"name":"Minami Takayama","avatar":""},{"name":"Hideyuki Tanaka","avatar":""},{"name":"Masayo Kurata","avatar":""},{"name":"Sumomo Momomori","avatar":""},{"name":"Ayumi Sena","avatar":""},{"name":"Misato Fukuen","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Gekijouban Doraemon: Nobita no Kyouryuu Niimarumaruroku","大雄的恐龍2006","哆啦A夢：新·大雄的恐龍","哆啦A梦：新・大雄的恐龙","映画ドラえもん のび太の恐竜 (2006)","โดราเอมอนเดอะมูฟวี่: ไดโนเสาร์ของโนบิตะ","โดราเอมอนเดอะมูฟวี่ ตอน ไดโนเสาร์ของโนบิตะ","ไดโนเสาร์ของโนบิตะ","電影哆啦A夢：新大雄的恐龍","Doraemon the Movie: Nobita''s Dinosaur","Doraemon: Nobita''s Dinosaur","哆啦A梦 新・大雄的恐龙","Doraemon: Nobita dan Dunia Dinosaur","映画ドラえもん のび太の恐竜2006"]', 1784690324522);
