INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-an-miami', 'Chuyên Án Miami', 'Miami Vice', 'https://phimimg.com/upload/vod/20231129-1/366e774294208dcd157d50009b19001a.jpg', 'https://phimimg.com/upload/vod/20231129-1/aabc72941d27521bdaf253e014736067.jpg', '<p>Chuyên án Miami (tựa gốc Miami Vice) là phiên bản phim nhựa phỏng theo serie phim truyền hình ăn khách cùng tên được phát hành từ cuối thập kỷ 80. Bộ phim hành động này quy tụ một dàn diễn viên nổi tiếng vẫn đang được yêu mến, bao gồm Củng Lợi, Colin Farell, Jamie Foxx và Naomi Harris.</p>', 'Full', 1, 'single', 'completed', 18, 2006, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Gong Li","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Justin Theroux","avatar":""},{"name":"Barry Shabaka Henley","avatar":""},{"name":"Elizabeth Rodriguez","avatar":""},{"name":"John Hawkes","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Luis Tosar","avatar":""},{"name":"Domenick Lombardozzi","avatar":""},{"name":"Isaach De Bankolé","avatar":""},{"name":"Tom Towles","avatar":""},{"name":"Mario Ernesto Sánchez","avatar":""},{"name":"Fran","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
