INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-an-miami', 'Chuyên Án Miami', 'Miami Vice', 'chuyên án miami miami vice colin farrell jamie foxx gong li naomie harris john ortiz ciarán hinds justin theroux barry shabaka henley elizabeth rodriguez john hawkes eddie marsan luis tosar domenick lombardozzi isaach de bankolé tom towles mario ernesto sánchez fran ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-bang-ha-2-bang-tan', 'Kỷ Băng Hà 2: Băng Tan', 'Ice Age: The Meltdown', 'https://phimimg.com/upload/vod/20250412-1/39f58cae66895688a09c8bbc1df8bdba.jpg', 'https://phimimg.com/upload/vod/20250412-1/e5e000835e03a79dac14af8546c0b05e.jpg', '<p>Sau thành công của Ice Age phần 1, trong Ice Age 2: The Meltdown, nhóm bạn Diego, Manny và Sid lại tái ngộ với khán giả khi khối băng chuẩn bị tan chảy ra và nó sẽ tàn phá cả thung lũng. Tình thế trở nên nguy hiểm hơn khi câu chuyện giờ đây xuất hiện thêm 2 sinh vật biển lúc nào cũng rình rập dưới làn nước lạnh lẽo. Ba người bạn của chúng ta phải hợp sức với nhau để giúp mọi người tránh khỏi thảm họa này. Liệu những người anh hùng của chúng ta có tới đích an toàn? Liệu Manny và Ellie có tìm được tình yêu đích thực với nhau? Liệu chú sóc Scrat có giành được quả đầu cho mình? Liệu Diego có chiến thắng nỗi sợ hãi của một chú hổ không biết bơi? Liệu Sid có được tôn trọng đúng mực?</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2006, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ray Romano","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Denis Leary","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Josh Peck","avatar":""},{"name":"Jay Leno","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Chris Wedge","avatar":""},{"name":"Peter Ackerman","avatar":""},{"name":"Caitlin Rose Anderson","avatar":""},{"name":"Connor Anderson","avatar":""},{"name":"Joseph Bologna","avatar":""},{"name":"Jack Crocicchia","avatar":""},{"name":"Peter DeSève","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"Clea Lewis","avatar":""},{"name":"St","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id