INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-kiem-giang-ho', 'Du Kiếm Giang Hồ', 'Vagabond Vigilante', 'https://phimimg.com/upload/vod/20250405-1/7d6254fc166f8a88912d19bf6ebb35dd.jpg', 'https://phimimg.com/upload/vod/20250405-1/e9eeb9c96d90d1dc62ecd3d6e0272408.jpg', '<p>Vừa biết tin Mạnh Nguyên Siêu (do Trần Long đóng) bị giết chết, tổng tiêu đầu Dương Mục (do Trần Cẩm Hồng đóng) lập tức mang sính lễ đến hỏi cưới Vân Tử La (do Quách Thiện Ni đóng). Lúc này, La đã mang cốt nhục của Siêu. Để bảo toàn tính mạng đứa bé, cô đành nhận lời lấy Mục. Thật ra, Siêu đã thoát chết trong gang tấc. Anh định trở về hội ngộ cùng La nhưng đã quá muộn. Siêu đành lặng lẽ bỏ đi, dồn hết tâm sức để thực hiện di nguyện của cha – liên minh tiêu cục của 18 tỉnh. Ước vọng của Siêu gặp nhiều sóng gió vì sự xuất hiện của phái Phù Tang mà người đứng đầu là Mưu Tông Đào (do Lý Thiên Tường đóng). Vì Siêu vô tình giúp sư muội Lâm Vô Song (do Trần Di Dung đóng) đoạt được ngôi vị tôn chủ của phái Phù Tang, nên Đào càng căm hận Siêu. Trong khi đó, Mục lo sợ mất La, đã vu cho Siêu tội thông dâm, khiến anh thân bại danh liệt. Tổ chức liên minh chưa kịp ra đời đã bị chết yểu. Thừa cơ hội này, Đào cấu kết với tổng lệnh ngự lâm quân Bắc Cung Vọng (do Lưu Vệ Hoa đóng), mua chuộc Mục, tiếp tục dồn Siêu vào con đường cùng. May thay, bên cạnh Siêu còn có Mậu Trường Phong (do Hà Gia Kính đóng). Chẳng những ngưỡng mộ đạo pháp của Mạnh gia, Phong còn yêu thầm La từ rất lâu. Cho nên, anh nguyện bất chấp tất cả để giúp đỡ Siêu và La, kể cả phải hy sinh tính mạng của mình.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 18, 2006, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Sonija Kwok Sin-Nae","avatar":""},{"name":"Sunny Chan Kam-Hung","avatar":""},{"name":"Kenny Ho Kar-King","avatar":""},{"name":"Chen Long","avatar":""},{"name":"Lee Tin-Cheung","avatar":""},{"name":"Li Qian","avatar":""},{"name":"Liu Wei-Hua","avatar":""},{"name":"Yang Minna","avatar":""},{"name":"Zhu Yuchen","avatar":""},{"name":"Li Jianqun","avatar":""},{"name":"Pan Hong","avatar":""},{"name":"Wang Yanan","avatar":""},{"name":"Cao Jun","avatar":""},{"name":"Liang Zhao","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["Vagabond Vigilante","遊劍江湖"]', 1784690324523);
