INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-menh', 'Sinh Mệnh', 'Life', 'https://phimimg.com/upload/vod/20250403-1/e17df8b66ed760ef91659fca2f1dcca2.jpg', 'https://phimimg.com/upload/vod/20250403-1/3c7c0468d6f7ea7970fb2905845fbab2.jpg', '<p>Trong giai đoạn Chiến tranh Việt Nam (1968-1970), Linh &quot;gấu&quot; là lính vận tải trên tuyến đường Trường Sơn, luôn khao khát có con với vợ là Lợi. Khi mẹ và vợ đến thăm nhưng không gặp được anh, thủ trưởng Thạnh tạo cơ hội cho Linh về quê bằng cách giao nhiệm vụ vận chuyển hàng &quot;đặc biệt&quot; vào Quảng Bình cùng đồng đội Đán và Nga. Trên đường đi, họ đối mặt với bom đạn ác liệt và phát hiện hàng hóa chỉ là giấy trắng dành cho trẻ em. Khi đến nơi, Linh chứng kiến anh trai của Nga đã hy sinh. Trên đường về, Linh và Nga nảy sinh tình cảm. Không lâu sau, một trận bom cướp đi mạng sống của Linh và Đán, chỉ còn Nga sống sót. Cô mang thai con của Linh và sinh con trong bệnh viện dã chiến, bên cạnh Lợi và mẹ Linh.</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Võ Thành Tâm","avatar":""},{"name":"Kiều Thanh","avatar":""},{"name":"Nguyễn Kim Trang","avatar":""},{"name":"Phạm Thanh Thủy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["A tanítványok"]', 1784690324523);
