INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-thanh', 'Thương Thành', 'Confession Of Pain', 'https://phimimg.com/upload/vod/20250331-1/39e25fdd1f6e2f58360c712e8f742df1.jpg', 'https://phimimg.com/upload/vod/20250331-1/f83920bc87266cf8fa8cf2f7837e977d.jpg', '<p>Trong ngành cảnh sát Hong Kong, Hei (Lương Triều Vỹ) là một thanh tra tài danh. Anh không chỉ thành công trong sự nghiệp mà còn có một cuộc sống hạnh phúc với nghệ sĩ Susan (Từ Tịnh Lôi). Song cảnh sát kỳ cựu này cũng không thể giải quyết được vụ sát hại người anh vợ và cha vợ vốn là một tỷ phú. Susan quá đau đớn và lo sợ nghĩ mình cũng đang bị theo dõi nên nhờ tới Bong (Kim Thành Vũ) trợ giúp điều tra. Bong vốn là người đồng nghiệp &quot;vào sinh ra tử&quot; với Hei, nhưng đã chuyển nghề làm thám tử tư. Anh sống trong cảnh trầm uất sau khi người yêu tự tử…</p>', 'Full', 1, 'single', 'completed', 20, 2006, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lương Triều Vỹ","avatar":""},{"name":"Kim Thành Vũ","avatar":""},{"name":"Thư Kỳ","avatar":""},{"name":"Từ Tịnh Lôi","avatar":""},{"name":"Đỗ Vấn Trạch","avatar":""},{"name":"Doãn Dương Minh","avatar":""},{"name":"Giang Mỹ Nghi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["seung sing","상성: 상처받은 도시","傷城","คู่เดือด เฉือนคม"]', 1784690324523);
