INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuong-thanh', 'Thương Thành', 'Confession Of Pain', 'thương thành confession of pain lương triều vỹ kim thành vũ thư kỳ từ tịnh lôi đỗ vấn trạch doãn dương minh giang mỹ nghi seung sing 상성: 상처받은 도시 傷城 คู่เดือด เฉือนคม', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quoc-xe-hoi', 'Vương Quốc Xe Hơi', 'Cars', 'https://phimimg.com/upload/vod/20250327-1/a6e1e3ea8701b0a730dd6e811075a463.jpg', 'https://phimimg.com/upload/vod/20250327-1/5fa33713b0d22023274fbd7b5c5b8f44.jpg', '<p>McQueen Tia chớp khoác trên mình lớp sơn đỏ rực, rất sung sức, tự mãn và thường trực nụ cười mỉa mai. Lao vun vút trên đường 66 tới California để tranh cúp Piston, cậu đã đâm sầm vào thị trấn Radiator Springs buồn tẻ, phá nát đường đi và suýt bị ngồi tù. Chỉ vài ngày nữa, anh chàng phải tham gia cuộc đua, mong được đại gia Dinoco tài trợ để trở thành &quot;sao&quot;. Nhờ sáng kiến của cô nàng luật sư Sally - một chiếc Porsche bóng bẩy đời 2002 - McQueen phải đem thân hình công tử ra kéo chiếc xe rải nhựa khổng lồ để làm lại đường. Cậu làm quen với bác sĩ Hudson, một chiếc Hudson Hornet đời 1951 từng là huyền thoại của đường đua Piston. Ngoài ra còn có Mater chiếc xe tải cũ mèm, gỉ sét và vui tính. Từ thị trấn nhỏ bé này, McQueen đã nhận ra nhiều điều ý nghĩa trong cuộc sống.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2006, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Paul Newman","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Larry the Cable Guy","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Guido Quaroni","avatar":""},{"name":"Jenifer Lewis","avatar":""},{"name":"Paul Dooley","avatar":""},{"name":"Michael Wallis","avatar":""},{"name":"George Carlin","avatar":""},{"name":"Katherine Helmond","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"Joe Ranft","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Richard Petty","avatar":""},{"name":"Jeremy Piven","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["反斗车王","كارز","Bílar","Mashinha","Cars: Una aventura sobre ruedas","Көліктер","Maşınlar","Cars - Motori Ruggenti","Cars 1","Bilar","Auti","カーズ","Cars"]', 1784690324523);
