INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoc-lam-hoang-hau', 'Được Làm Hoàng Hậu', 'Princess Hours', 'https://phimimg.com/upload/vod/20250317-1/86cdb13d5f10c0de839c41cb87c0fb32.jpg', 'https://phimimg.com/upload/vod/20250317-1/41003633baca4e641daedfb296de92f5.jpg', '<p>Dựa trên một truyện tranh nổi tiếng, kể về một cô gái 17 tuổi vẫn hay thích mặc quần thể dục dưới váy, bỗng một ngày trở thành Thái tử phi - người phụ nữ quyền lực thứ 3 của Hàn Quốc. Cô kết hôn với Thái tử đẹp trai nhất Hàn Quốc - Lee Yul, anh chàng làm gục ngã trái tim bao cô gái. Đồng thời cô còn là người tình trong mộng của anh trai thái tử Lee Yul.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2006, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoon Eun-hye","avatar":""},{"name":"Ju Ji-hoon","avatar":""},{"name":"Song Ji-hyo","avatar":""},{"name":"Kim Jeong-hoon","avatar":""},{"name":"Lee Yoon-ji","avatar":""},{"name":"Kim Hye-ja","avatar":""},{"name":"Yun Yoo-sun","avatar":""},{"name":"Shim Hye-jin","avatar":""},{"name":"Park Chan-hwan","avatar":""},{"name":"Im Ye-jin","avatar":""},{"name":"Kang Nam-gil","avatar":""},{"name":"Choi Bool-am","avatar":""},{"name":"Kim Sang-joong","avatar":""},{"name":"Kim Seok","avatar":""},{"name":"Jeon Yeo-jin","avatar":""},{"name":"Choi Sung-joon","avatar":""},{"name":"Lee Yong-joo","avatar":""},{"name":"Kim Dong-seok","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我的野蛮王妃","宮(クン)～Love in Palace","Goong","我的野蠻王妃","宮—野蠻王妃","궁"]', 1784690324