INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-gio-hoc-tren-san-thuong', 'Sau Giờ Học Trên Sân Thượng', 'See You After School', 'https://phimimg.com/upload/vod/20250223-1/2517a8b1db96cbed8cd8de7390e20d70.jpg', 'https://phimimg.com/upload/vod/20250223-1/081db5532219b5036d33e32a338c2bde.jpg', '<p>Sau khi trải qua khóa huấn luyện để vượt qua nạn bắt nạt, một thiếu niên trung học gặp rắc rối trong cuộc sống và các mối quan hệ ở trường phải đối mặt với kẻ bắt nạt ngay trong ngày đầu tiên đi học.</p>', 'Full', 1, 'single', 'completed', 8, 2006, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Bong Tae-gyu","avatar":""},{"name":"Jin Tae-hyeon","avatar":""},{"name":"Jeong Yoon-jo","avatar":""},{"name":"Ha Seok-jin","avatar":""},{"name":"Cheng Yun","avatar":""},{"name":"Seung-yeol Cha","avatar":""},{"name":"Chang-ju Sin","avatar":""},{"name":"Baek Soo-jang","avatar":""},{"name":"Choi Eun-ju","avatar":""},{"name":"Chu Sang-mi","avatar":""},{"name":"Son Byeong-uk","avatar":""},{"name":"Hong Kyeong-yeon","avatar":""},{"name":"Jeong Dae-hoon","avatar":""},{"name":"Lee Je-hoon","avatar":""},{"name":"Jo Dal-hwan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Rooftop After School","Uvidíme se po škole","Bang-gwa-hoo-ock-sang","방과후 옥상"]', 1784690324523);
