INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sau-gio-hoc-tren-san-thuong', 'Sau Giờ Học Trên Sân Thượng', 'See You After School', 'sau giờ học trên sân thượng see you after school bong tae-gyu jin tae-hyeon jeong yoon-jo ha seok-jin cheng yun seung-yeol cha chang-ju sin baek soo-jang choi eun-ju chu sang-mi son byeong-uk hong kyeong-yeon jeong dae-hoon lee je-hoon jo dal-hwan rooftop after school uvidíme se po škole bang-gwa-hoo-ock-sang 방과후 옥상', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-hoi-den-2', 'Xã Hội Đen 2', 'Election 2', 'https://phimimg.com/upload/vod/20250219-1/852e1d212dd9cc0a69b6ed31386c223e.jpg', 'https://phimimg.com/upload/vod/20250219-1/e928e8a425a59e55dba85d990abe048b.jpg', '<p>Jimmy, một tay gangster có ăn học, mang vẻ tri thức lịch sự của một doanh nhân, là kẻ chỉ ham kiếm tiền và làm giàu. Hắn tìm cách liên lạc với các quan chức, tạo quan hệ làm ăn với những kẻ chức quyền. Không chịu yên phận ở Hong Kong, hắn còn cộng tác làm ăn lớn ở Trung Quốc đại lục. Đã qua hai năm kể từ khi Lok (Nhậm Đạt Hoa) chiến thắng trong cuộc bầu cử và lên làm chủ tịch của Wo Sing. Đến hẹn lại lên, năm nay Wo Sing lại tổ chức bầu chọn ra người lãnh đạo mới.Quyền lực và những lợi nhuận thu được từ chiếc ghế chủ tịch khiến không ít kẻ có dã tâm tìm cách đánh bại những ứng cử viên khác. Ngay cả Lok, vị chủ tịch đương thời, cũng ngấm ngầm vận động từng kẻ tay chân ủng hộ mình, suy tính kế hoạch giữ ...</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Wong Tin-Lam","avatar":""},{"name":"Gordon Lam Ka-Tung","avatar":""},{"name":"Nick Cheung Ka-Fai","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Andy On Chi-Kit","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Tam Bing-Man","avatar":""},{"name":"Poon Yuet-Tung","avatar":""},{"name":"You Yongzhi","avatar":""},{"name":"Albert Cheung Miu-Hau","avatar":""},{"name":"Yuen Bun","avatar":""},{"name":"Jonathan Lee Yat-Sing","avatar":""},{"name":"Wong Sze-Yan","avatar":""},{"name":"Chiu C","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Triad Election","Black Society 2: Triads Value Peace Most","Elección 2","Election 2: Triaden","Election II - Triadit","Election: Volume 2","I triada 2","Election 2","エレクション 死の報復","흑사회2","黑社會2：以和為貴","黑社會2","黑社会2","黑社会2：以和为贵","黑社會2:以和為貴","Hak se wui: Yi woo wai kwai","Wybór mafii 2","흑사회 II"]', 1784690324523);
