INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-ky-cuoc-phieu-luu-cua-sieu-khi', 'Tây Du Ký : Cuộc Phiêu Lưu Của Siêu Khỉ', 'Journey To The West : Adventures Of The Super Monkey', 'https://phimimg.com/upload/vod/20250209-1/889c1b1b1588c806ca4e1eacd2217deb.jpg', 'https://phimimg.com/upload/vod/20250209-1/b16efcc86108cba4ca52873a73f2805a.jpg', '<p>Dựa trên tiểu thuyết kinh điển Tây Du Kí, một nhà sư lên đường đến Tây Trúc thỉnh kinh cùng với một con khỉ nghịch ngợm, một con quái vật ở sông và một con heo tham lam.</p>', 'Full', 11, 'series', 'completed', 20, 2006, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shingo Katori","avatar":""},{"name":"Eri Fukatsu","avatar":""},{"name":"Uchimura Teruyoshi","avatar":""},{"name":"Atsushi Ito","avatar":""},{"name":"Asami Mizukawa","avatar":""},{"name":"Ohkura Koji","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Saiyuki","Saiyuuki","Adventures of the Super Monkey - Journey to the West","Journey to the West","Monkey Magic","西遊記"]', 1784690324523);
