INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shinchan', 'Shin-chan', 'Cậu Bé Bút Chì', 'https://phimimg.com/upload/vod/20250110-1/b3e7bcd6fc569bf2c71b698c0be2df17.jpg', 'https://phimimg.com/upload/vod/20250110-1/a4f6956b4f9c950d83e84a999d87c1b8.jpg', '<p>Ở trường mẫu giáo, nhóc Shin 5 tuổi hóm hỉnh là cậu bé hoạt bát nhất trong nhóm bạn chơi chung. Ở nhà, Shin cũng luôn là thành viên tạo nên tiếng cười cho bố mẹ và cô em gái bé nhỏ. Phim chuyển thể từ truyện tranh ăn khách cùng tên của Nhật mang đến cho hàng triệu khán giả nhí cùng gia đình những tiếng cười thư giãn.</p>', 'Hoàn Tất (104/104)', 104, 'series', 'completed', 21, 2006, 'Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Laura Bailey","avatar":""},{"name":"Cynthia Cranz","avatar":""},{"name":"Colleen Clinkenbeard","avatar":""},{"name":"Chuck Huber","avatar":""},{"name":"Chris Cason","avatar":""},{"name":"Brina Palencia","avatar":""},{"name":"Carrie Savage","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Shin-chan","Crayon Shin-chan","Shin Chan Funimation","Shin Chan","Shin Chan Dub"]', 1784690324523);
