INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-house-phan-3', 'Bác Sĩ House (Phần 3)', 'House (Season 3)', 'https://phimimg.com/upload/vod/20250103-1/44d7dcba225407584bffda4be2c09661.jpg', 'https://phimimg.com/upload/vod/20250103-1/998311a4ee6e88493e4b17abbb011eeb.jpg', '<p>Trong phần cuối của Phần 2, House phải chịu nhiều vết thương do đạn bắn do chồng của một bệnh nhân cũ quyết tâm thực hiện quả báo vì cách House đối xử với trường hợp của vợ anh ta. Trước sự ngạc nhiên gây sốc đối với đồng nghiệp của mình, House vượt qua thử thách với một quan điểm hơi mới về cách điều trị bệnh nhân của mình - nhưng liệu nó có ảnh hưởng đến cách anh ấy đưa ra quyết định y tế không? Và liệu nó có kéo dài không?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Laurie","avatar":""},{"name":"Robert Sean Leonard","avatar":""},{"name":"Omar Epps","avatar":""},{"name":"Jesse Spencer","avatar":""},{"name":"Odette Annable","avatar":""},{"name":"Peter Jacobson","avatar":""},{"name":"Charlyne Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Doctor House","豪斯医生","House - Medical Division","دکتر هاوس","ドクター・ハウス","닥터 하우스","Доктор Гаус","House M.D.","House"]', 1784690324523);
