INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-sieu-hang-phan-4', 'Điệp Viên Siêu Hạng (Phần 4)', 'Totally Spies! (Season 4)', 'https://phimimg.com/upload/vod/20240828-1/26e28fb59a7fa5fbf5651eef7b1dabcb.jpg', 'https://phimimg.com/upload/vod/20240828-1/38071e0b6e15013f962e38a0f6801482.jpg', '<p>Ba Nữ Thám Tử - Totally Spies kể về cuộc sống của ba nữ điệp viên siêu hạng tuổi thiếu niên là Sam, Clover và Alex. Cả ba có tính cách khác nhau nhưng đều phối hợp với nhau khá hoàn hảo trong các điệp vụ. Họ có nhiệm vụ bắt những tên tội phạm quốc tế nguy hiểm thông qua ông Jerry, lãnh đạo của WOOHP - Tổ chức Quốc tế về Bảo vệ Con người. Jerry là một người rất nghiêm khắc nhưng ông luôn là một đứa con sợ mẹ, và ông đã giấu mẹ mình về việc mình làm sếp của WOOHP và nói rằng mình là một ông chủ khách sạn. Mẹ của ba nữ điệp viên biết con mình là điệp viên bí mật nên đã mua cho ba đứa con một ngôi nhà lớn gần trường. Bên cạnh đó, Sam, Clover và Alex sống cuộc sống bình thường như bao cô gái khác như đi học, có bạn trai...</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 11, 2006, 'Thuyết Minh', 'FHD', 'Pháp', 0, '[{"name":"Jennifer Hale","avatar":""},{"name":"Andrea Baker","avatar":""},{"name":"Katie Griffin","avatar":""},{"name":"Claire Guyot","avatar":""},{"name":"Fily Keita","avatar":""},{"name":"Céline Mauge","avatar":""},{"name":"Jean-Claude Donda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324523);
