INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-cuc-dai', 'Hoa Cúc Dại', 'Daisy', 'https://phimimg.com/upload/vod/20231213-1/7a64f4524a2ea0394ce3cbf0119feaa9.jpg', 'https://phimimg.com/upload/vod/20231213-1/14f7d73ea522c6b8a1206799c8a7e5d4.jpg', '<p>Trong phim Hoa Cúc Dại, cô họa sĩ Hye Young (Jun Ji Hyun thủ vai) là một cô gái người Hàn ngây thơ trong sáng sống ở Amsterdam, làm việc ở cửa hàng bán đồ cổ của ông và vẽ tranh cho du khách. Vào một ngày nọ trong phim này, cô ấy bắt đầu nhận được những khóm hoa cúc dại hằng ngày được gửi đến đúng giờ đó từ một người hâm mộ bí mật, cô cho rằng người đó là người đã từng xây cây cầu nhỏ cho cô ấy. Cô ấy gặp Jeong Woo (Lee Sung Jae đóng), cô ấy không biết anh ấy là một nhân viên mật vụ quốc tế chuyên theo dõi tội phạm ở Hà Lan. Theo dõi phim Hoa Cúc Dại và hy vọng bộ phim online này sẽ mang lại những giờ phút thư giãn cho các bạn!</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jun Ji-hyun","avatar":""},{"name":"Jung Woo-sung","avatar":""},{"name":"Lee Sung-jae","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
