INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-sopranos-phan-6', 'Gia Đình Sopranos (Phần 6)', 'The Sopranos (Season 6)', 'https://phimimg.com/upload/vod/20241105-1/2e684097f5df6eb82dfd1a5ebd714a2a.jpg', 'https://phimimg.com/upload/vod/20241105-1/083c91aeef890c49fc4652957ba5ca31.jpg', '<p>Khi các tập cuối bắt đầu hình thành, Tony phải đối mặt với vô số khủng hoảng gây căng thẳng ở nhà, tại nơi làm việc và từ luật pháp. Trong khi vợ và các con của anh ấy đưa ra những lựa chọn hứa hẹn sẽ thay đổi bộ mặt cuộc sống gia đình của Sopranos, Tony cũng nghi ngờ lòng trung thành của một số người thân cận nhất với anh ấy tại nơi làm việc. . . không ai trong số họ nằm trên sự nghi ngờ.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 21, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Gandolfini","avatar":""},{"name":"Edie Falco","avatar":""},{"name":"Jamie-Lynn Sigler","avatar":""},{"name":"Robert Iler","avatar":""},{"name":"Lorraine Bracco","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Steven Van Zandt","avatar":""},{"name":"Tony Sirico","avatar":""},{"name":"Dominic Chianese","avatar":""},{"name":"Aida Turturro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Família Soprano","人在江湖","Rodina Sopránů","آل سوبرانو","סופרנוס","द सोप्रानोस","سوپرانو","خانواده سوپرانو","سوپرانوز","Rodzina Soprano","Семья Сопрано","Клан Сопрано","The Sopranos"]', 1784690324523);
