INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pucca', 'Pucca', 'Pucca', 'https://phimimg.com/upload/vod/20241104-1/7db0d1cfd5687c0878a0a83febdc5d25.jpg', 'https://phimimg.com/upload/vod/20241104-1/6a825d3758be1cb4d1833de27fc817d9.jpg', '<p>Pucca là cô bé đáng yêu, năng động, táo bạo, luôn mạnh mẽ thể hiện tình cảm với cậu nhóc ninja Garu. Trong các cuộc rượt đuổi hấp dẫn hay những màn đối đầu vui nhộn, Pucca luôn &quot;hạ gục&quot; Garu bằng sự vui vẻ yêu đời và ý chí kiên định của mình.</p>', 'Hoàn Tất (117/117)', 117, 'hoathinh', 'completed', 15, 2006, 'Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Michael Dobson","avatar":""},{"name":"Dave ''Squatch'' Ward","avatar":""},{"name":"Richard Newman","avatar":""},{"name":"Tabitha St. Germain","avatar":""},{"name":"Brian Dobson","avatar":""},{"name":"Dale Wilson","avatar":""},{"name":"Chantal Strand","avatar":""},{"name":"Brian Drummond","avatar":""},{"name":"Lee Tockar","avatar":""},{"name":"Kathleen Barr","avatar":""},{"name":"French Tickner","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["PUCCA","Pucca"]', 1784690324523);
