INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-thep-phan-1', 'Bằng Chứng Thép (Phần 1)', 'Forensic Heroes (Season 1)', 'https://phimimg.com/upload/vod/20241029-1/24a5664a9460beb7ee97bc6e65010a62.jpg', 'https://phimimg.com/upload/vod/20241029-1/48bce5e6c90a2db93167c2a6158c6ac6.jpg', '<p>Cao Ngạn Bác là bác sĩ pháp y cao cấp, phụ trách khâu hóa nghiệm ở Bộ Sự vụ Pháp chứng. Công việc của anh là đến hiện trường vụ án, thu thập bằng chứng, hóa nghiệm vật chứng, hỗ trợ cảnh sát phá án.

Cổ Trạch Lâm cũng là bác sĩ pháp y. Sở trường của anh là phẫu thuật tử thi. Cao Ngạn Bác và Cổ Trạch Lâm không chỉ là đồng nghiệp ở nơi làm việc, mà trong gia đình, họ còn có thêm mối quan hệ anh rể - em vợ.

Lương Tiểu Nhu là một cô cảnh sát dễ thương, thông minh, gan dạ. Tuy còn trẻ nhưng Tiểu Nhu đã được thăng chức Tổ trưởng Tổ Trọng án - Tổng bộ Tây Cửu Long. Thế rồi xảy ra vụ án Cổ Trạch Dao - chính là vợ của Cao Ngạn Bác.

Vụ án xảy ra vào lúc Lâm Bái Bái - người yêu năm xưa của Ngạn Bác - từ Mỹ trở về... Tất cả các manh mối và bằng chứng đều bất lợi cho Ngạn Bác… Ai là hung thủ trong cái chết của Cổ Trạch Dao khi cô còn đang trong thời gian điều trị tại bệnh viện…</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 20, 2006, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Mông Gia Tuệ","avatar":""},{"name":"Lâm Văn Long","avatar":""},{"name":"Âu Dương Chấn Hoa","avatar":""},{"name":"Chung Gia Hân","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["法证先锋","Forensic Heroes","法證先鋒"]', 1784690324523);
