INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-khat-mau-phan-1', 'Thiên Thần Khát Máu (Phần 1)', 'Dexter (Season 1)', 'https://phimimg.com/upload/vod/20241010-1/362847f2546cfa38ac2793e1001aec93.jpg', 'https://phimimg.com/upload/vod/20241010-1/fd91c61bbf6168e72ca2d8442b13dcee.jpg', '<p>Vào ban ngày, Dexter Morgan là một nhân viên vui tính của Sở cảnh sát Miami. Anh là một chuyên viên giám định vết máu và cũng là trụ cột gia đình, là người chu cấp cho chị (em) gái. Dexter có một người bạn gái đứng đắn, với hai đứa trẻ hết lòng kính mến anh. Nhưng anh cũng có một cuộc sống thực sự khác về đêm.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 27, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael C. Hall","avatar":""},{"name":"Jennifer Carpenter","avatar":""},{"name":"Geoff Pierson","avatar":""},{"name":"David Zayas","avatar":""},{"name":"James Remar","avatar":""},{"name":"Aimee Garcia","avatar":""},{"name":"Desmond Harrington","avatar":""},{"name":"C.S. Lee","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Декстер","双面法医","Ντέξτερ","デクスター","Правосудие Декстера","Dexter"]', 1784690324523);
