INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-bat-kha-thi-3', 'Nhiệm Vụ: Bất Khả Thi 3', 'Mission: Impossible III', 'https://phimimg.com/upload/vod/20231019-1/fefe2dc90b13739a4958e4d19bf8be1e.jpg', 'https://phimimg.com/upload/vod/20231019-1/f43cb7f7e5a5ca54b3cae946839519a4.jpg', '<p>Siêu điệp viên Ethan Hunt muốn “rửa đao gác kiếm” để cưới vợ và tập trung vào huấn luyện điệp viên trẻ, nhưng anh bất ngờ nhận được tin từ IMF rằng Lindsey Farris, đồng nghiệp và cũng là học trò trước đây của anh, đã mất tích trong khi theo dấu Owen Davian, một tên cáo già giết người không ghớm tay. Ethan phải bỏ dở lễ cưới để đi tìm Lindsey Farris. Cứu được Lindsey khỏi tay kẻ bắt cóc, nhưng Ethan không thể giành lại cô từ tay thần chết. Những gì cô để lại là một câu nói lấp lửng mà cô chưa kịp nói hết với anh, kèm theo là một tấm bưu ảnh Berlin gửi về địa chỉ của Ethan sau khi cô chết. Dằn vặt, ân hận và căm thù kẻ gài bom trong đầu cô học trò yêu quý, Ethan quyết định phải bắt cho bằng được Davian.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Billy Crudup","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Keri Russell","avatar":""},{"name":"Maggie Q","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Bahar Soomekh","avatar":""},{"name":"Jeff Chase","avatar":""},{"name":"Michael Berry Jr.","avatar":""},{"name":"Carla Gallo","avatar":""},{"name":"Bellamy Young","avatar":""},{"name":"Paul Ke","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
