INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-va-co-gai-mu', 'Hoàng Tử Và Cô Gái Mù', 'Fanaa', 'https://phimimg.com/upload/vod/20240905-1/317a5d51f585602118b540dd760e727e.jpg', 'https://phimimg.com/upload/vod/20240905-1/1abef920fe5d41f3de385542f8f59e24.jpg', '<p>Zooni Ali Beg là một cô gái mù Kashmiri lần đầu tiên đi du lịch mà không có cha mẹ cùng một đoàn múa đến Delhi để biểu diễn trong một buổi lễ kỷ niệm ngày độc lập. Trên hành trình của mình, cô gặp Rehan Khan, một casanova và hướng dẫn viên du lịch, người đã tán tỉnh cô. Mặc dù bạn bè của cô đã cảnh báo Zooni về anh ta, nhưng cô không thể cưỡng lại việc yêu anh ta và anh ta đưa cô đi tham quan riêng ở New Delhi. Nhưng Rehan còn nhiều điều hơn những gì bạn thấy và Zooni sẽ phải đưa ra một quyết định đau lòng.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Aamir Khan","avatar":""},{"name":"Kajol","avatar":""},{"name":"Rishi Kapoor","avatar":""},{"name":"Kirron Kher","avatar":""},{"name":"Sanaya Irani","avatar":""},{"name":"Shiney Ahuja","avatar":""},{"name":"Lillete Dubey","avatar":""},{"name":"Tabu","avatar":""},{"name":"Ali Haji","avatar":""},{"name":"Lara Dutta","avatar":""},{"name":"Gautami Kapoor","avatar":""},{"name":"Jaspal Bhatti","avatar":""},{"name":"Satish Shah","avatar":""},{"name":"Shruti Seth","avatar":""},{"name":"Vrajesh Hirjee","avatar":""},{"name":"Sharat Saxena","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
