INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-10-le-cau-hon-cua-tham-tu', 'Thám Tử Lừng Danh Conan 10: Lễ Cầu Hồn Của Thám Tử', 'Detective Conan: The Private Eyes'' Requiem', 'https://phimimg.com/upload/vod/20231019-1/0917f5e766f0db18b7ab170d9211e3c1.jpg', 'https://phimimg.com/upload/vod/20231019-1/80c1632826980315e36db7514f6dcfb3.jpg', '<p>Một người đàn ông bí ẩn hỏi Kogoro để đến Yokohama. He asked Ran, Conan and the others go with him. Ông đã yêu cầu Ran, Conan và những người khác đi với anh ta. However, it was a trap, and Ran and the Detective Boys are taken as hostage. Tuy nhiên, nó đã là một cái bẫy, và Ran và Detective Boys được lấy làm con tin. The case that the mysterious man gave Kogoro must be solved within 12 hours, or else the bomb, hidden in VIP passes for an amusement park and worn by Ran and the others, will explode. Các trường hợp đó, người đàn ông bí ẩn đã Kogoro phải được giải quyết trong vòng 12 giờ, hoặc người nào khác quả bom, ẩn trong VIP qua cho một khu vui chơi và mòn của Ran và những người khác, sẽ phát nổ. The criminal also knows that Conan is Shinichi Kudo. tội phạm cũng biết rằng Conan là Shinichi Kudo. Heiji Hattori ...</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2006, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Ai Orikasa","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Atsuko Yuya","avatar":""},{"name":"Gara Takashima","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Ryou Horikawa","avatar":""},{"name":"Yuko Miyamura","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
