INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-can-cho', 'Chó Cắn Chó', 'Dog Bite Dog', 'https://phimimg.com/upload/vod/20240726-1/576ed3201971dde3cddb48b02d9edea2.jpg', 'https://phimimg.com/upload/vod/20240726-1/bc3637b35f185e4c07a306a22c618f0f.jpg', '<p>Bộ phim kể về Pang, một sát thủ trẻ tuổi từ Campuchia đến Hong Kong để thực hiện một vụ ám sát. Từ nhỏ, Bằng đã sống trong một thế giới phải giết để sinh tồn, hình thành tính cách chiến đấu cao. Trong một lần hành động, Bằng đánh trọng thương một viên cảnh sát, bạn thân của Vĩ. Vĩ, một cảnh sát nóng nảy, quyết tâm trả thù Bằng bằng mọi cách. Cuộc đối đầu này dẫn đến những trận chiến khốc liệt và căng thẳng giữa hai người, phơi bày những góc khuất của con người trong cuộc chiến sinh tồn.</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"陳冠希","avatar":""},{"name":"李燦森","avatar":""},{"name":"Weiying Pei","avatar":""},{"name":"張兆輝","avatar":""},{"name":"黎耀祥","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"林嘉華","avatar":""},{"name":"Hao Ren","avatar":""},{"name":"Ask Lee","avatar":""},{"name":"Ka Sing Chau","avatar":""},{"name":"Fire Lee Ka-Wing","avatar":""},{"name":"Ting-Fung Li","avatar":""},{"name":"顧錦華","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
