INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-ha-de-nhat-kiem', 'Thiên Hạ Đệ Nhất Kiếm', 'World''s Finest', 'https://phimimg.com/upload/vod/20240611-1/7a24af784b58def88dc764242a21a37c.jpg', 'https://phimimg.com/upload/vod/20240611-1/642ea39a83ede1d78b4cee55f94d89ff.jpg', '<p><em>Lấy bối cảnh vào thời nhà Minh, lúc này tiên hoàng đã hạ lệnh cho thiết đảm thần hầu Chu Vô Thị lập nên 1 tổ chức có tên Hộ Long Sơn Trang nơi tụ tập những kỳ tài để bảo vệ hoàng gia. Nơi đây vang danh bởi có 1 hệ thống tình báo thuộc hàng đệ nhất thiên hạ, dường như không có chuyện gì xảy ra trên đời mà họ không biết, qua nhiều năm thu thập Hộ Long Sơn Trang đã ghi lại thông tin của hàng vạn người kèm những bí mật của họ. Bên cạnh Thần Hầu có tứ đại mật thám họ là những cánh tay đắc lực thực hiện những nhiệm vụ khó khăn nguy hiểm chống lại thế lực đối đầu là Đông Xưởng để bảo vệ Hộ Long Sơn Trang cùng Hoàng Tộc. Thế nhưng đến cuối cùng họ nhận ra mình chỉ là con cờ bị người ta sai khiến nhằm vào âm mưu soán ngôi.</em></p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 23, 2006, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Cao Viên Viên","avatar":""},{"name":"Hoắc Kiến Hoa","avatar":""},{"name":"Trương Vệ Kiện","avatar":""},{"name":"Lý Á Bằng","avatar":""},{"name":"Huỳnh Thánh Y","avatar":""},{"name":"Lưu Tùng Nhân","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324523);
