INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-phong-than', 'Bảng Phong Thần', 'The Legend and the Hero', 'https://phimimg.com/upload/vod/20240609-1/13faf174bd7552f6516d0180f1cb27b9.jpg', 'https://phimimg.com/upload/vod/20240609-1/5141239f181f0f1d9874a8162906108e.jpg', '<p>Bộ phim kể về câu chuyện của Tô Đắc Kỉ tốt bụng và giản dị, rời bỏ quê hương của mình và từ bỏ tình yêu để đến Triều Ca. Để hoàn thành sứ mệnh của nữ thần Nữ Oa, Tô Đắc Kỉ đã bị hồ ly nhập hồn, giúp đỡ nhà Chu lật đỗ triều đại nhà Thương.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 15, 2006, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Alan Lau","avatar":""},{"name":"Victor Huang","avatar":""},{"name":"林心如","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Like Wang","avatar":""},{"name":"Miao Haojun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324523);
