INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-nha-gau-2', 'Anh Em Nhà Gấu 2', 'Brother Bear 2', 'https://phimimg.com/upload/vod/20231024-1/bc45236118734a90add1b2e235932d04.jpg', 'https://phimimg.com/upload/vod/20231024-1/ad7048f6adc15244817dffcbd3d42e39.jpg', '<p>Phần hai của bộ phim Anh Em Nhà Gấu xoay quanh câu chuyện giữa Kenai và Nita, một cô gái mà anh đã gặp khi anh còn rất trẻ. Sau khi cho cô một lá bùa và hứa hẹn họ sẽ là những người bạn mãi mãi. Sau đó Nita rời khỏi nhà mình và Kenai không bao giờ nhìn thấy cô một lần nữa. Khi Nita lớn lên, cô rất xinh đẹp . Cô đang chuẩn bị cho đám cưới của mình sắp diễn ra. Tuy nhiên, tổ tiên không hài lòng, họ cho rằng Nita đã được gắn liền với Kenai. Cách duy nhất để Nita phá vỡ liên kết của họ và kết hôn hạnh phúc là hành trình đến chính là nơi mà Kenai đã cho cô bùa hộ mệnh...</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Dempsey","avatar":""},{"name":"Mandy Moore","avatar":""},{"name":"Jeremy Suarez","avatar":""},{"name":"Rick Moranis","avatar":""},{"name":"Dave Thomas","avatar":""},{"name":"Andrea Martin","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Wanda Sykes","avatar":""},{"name":"Wendie Malick","avatar":""},{"name":"Kathy Najimy","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Jessie Flower","avatar":""},{"name":"Jack Weber","avatar":""},{"name":"Tress MacNeille","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324523);
