INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-da-can-mui-2006', 'Kỳ Đà Cản Mũi', 'You, Me and Dupree', 'https://phimimg.com/upload/vod/20240617-1/c0da8c4e6cb4f64ade10f42bf0f85bc8.jpg', 'https://phimimg.com/upload/vod/20240617-1/b64f48fbbce96f539dc056f5a15c28cf.jpg', '<p>Chàng kiến trúc sư Carl Peterson (Matt Dillon thủ vai) có một khởi đầu hoàn hảo với công việc ổn định, một ngôi nhà xinh xắn và cô vợ xinh đẹp là con gái sếp. Nhưng mọi việc rối tung khi cậu bạn thân Dupree (Owen Wilson đóng) đến ở nhờ.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Kate Hudson","avatar":""},{"name":"Matt Dillon","avatar":""},{"name":"Michael Douglas","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Amanda Detmer","avatar":""},{"name":"Ralph Ting","avatar":""},{"name":"Todd Stashwick","avatar":""},{"name":"Bill Hader","avatar":""},{"name":"Lance Armstrong","avatar":""},{"name":"Jason Winer","avatar":""},{"name":"Sidney S. Liufau","avatar":""},{"name":"Billy Gardell","avatar":""},{"name":"Eli Vargas","avatar":""},{"name":"Houston Mack","avatar":""},{"name":"Bob Larkin","avatar":""},{"name":"Suzanne Ford","avatar":""},{"name":"Claudia Choi","avatar":""},{"name":"Sum","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324523);
