INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('com-tot-com-xau', 'Cớm Tốt, Cớm Xấu', 'Bon Cop Bad Cop', 'cớm tốt, cớm xấu bon cop bad cop patrick huard colm feore michel beaudry patrice bélanger hugolin chevrette richard howland erik knudsen sarah-jeanne labrosse sarain boylan nicolas canuel lucie laurier pierre lebeau louis-josé houde rick mercer pierre boudreau manon brunel ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-duong-gia-tuong', 'Thiếu Niên Dương Gia Tướng', 'Young Warriors of the Yang Clan', 'https://phimimg.com/upload/vod/20240530-1/2e4ec2111af625bd3340f8841d59e805.jpg', 'https://phimimg.com/upload/vod/20240530-1/8319c85fe3531b377098e078b79bd319.jpg', '<p>Vào thời điểm Dương gia tướng quy Tống, Bắc Hán bị diệt hậu, di thần Dương Nghiệp được Tống Thái Tông khí trọng, Dương Nghiệp cùng 7 người con trai cầm quân ra trận chống lại quân Liêu, tri ngộ chi ân báo đáp Tống Thái Tông, viết nên trung nghĩa sử thoại oai danh thiên hạ. Công nguyên 980, quân Tống tấn công U Châu, khiến quân Liêu sở bại, Tống Thái Tông bại hối trở về kinh thành. Từ đó, Liêu quân không ngừng tập kích biên giới nhà Tống, triều Tống luôn trong cảnh chiến loạn không được an bình, Thái Tông phái &quot;anh dũng vô địch&quot; Dương Nghiệp trấn giữ Nhạn Môn Quan.

Không may, trong trận chiến tại Kim Sa Thang, Dương gia tướng rơi vào bẫy phục kích của quân Liêu, khiến cho Dương Nghiệp và bốn người con trai hy sinh, một người bị quân Liêu bắt sống. Hai người con còn lại là Dương Ngũ Lang và Dương Lục Lang đã kế thừa sự nghiệp của Dương gia, đem lại hòa bình và thịnh vượng cho Đại Tống</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 23, 2006, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"胡歌","avatar":""},{"name":"Eddie Peng","avatar":""},{"name":"Peter Ho","avatar":""},{"name":"Chen Long","avatar":""},{"name":"劉詩詩","avatar":""},{"name":"Yuan Hong","avatar":""},{"name":"童瑤","avatar":""},{"name":"Chen Jie","avatar":""},{"name":"Zong Fengyan","avatar":""},{"name":"Li Jie","avatar":""},{"name":"Chia-Ming Weng","avatar":""},{"name":"Amy Chan","avatar":""},{"name":"吳磊","avatar":""},{"name":"Song Yang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324523);
