INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-cau-chuyen-kinh-di-tang-lau-bi-mat', 'Bốn Câu Chuyện Kinh Dị: Tầng Lầu Bí Mật', 'Four Horror Tales: Hidden Floor', 'https://phimimg.com/upload/vod/20240508-1/8c2672f0155a38451323d5f071cd3642.jpg', 'https://phimimg.com/upload/vod/20240508-1/6707f84edc19dd717722769e24f7c8cb.jpg', '<p>Tác phẩm sản xuất năm 2006 nằm trong series phim kinh dị Four Horror Tales gồm 4 phần: February 29, Hidden Floor, Roommates và Dark Forest. Hidden Floor xoay quanh cuộc sống của bà mẹ đơn thân Min Young cùng cô con gái sáu tuổi Joo Hee. Chẳng bao lâu sau khi dọn đến ở tầng năm của một khu chung cư cũ, mặc dù sống khá thầm lặng, hai mẹ con liên tục nhận được lời phàn nàn từ người đàn ông tầng dưới về những tiếng ồn phát ra từ căn hộ của mình. Hơn thế nữa, Min Young bắt đầu cảm thấy lo lắng và ngờ vực bởi thái độ thản nhiên của những người hàng xóm khác trước loạt án mạng rùng rợn và bí hiểm liên tiếp xảy ra xung quanh khu vực.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Seo-hyung","avatar":""},{"name":"Kim You-jung","avatar":""},{"name":"Jo Young-jin","avatar":""},{"name":"Kim Young-sun","avatar":""},{"name":"Kim Ja-young","avatar":""},{"name":"Lee Hwang-eui","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324523);
