INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bon-cau-chuyen-kinh-di-tang-lau-bi-mat', 'Bốn Câu Chuyện Kinh Dị: Tầng Lầu Bí Mật', 'Four Horror Tales: Hidden Floor', 'bốn câu chuyện kinh dị: tầng lầu bí mật four horror tales: hidden floor kim seo-hyung kim you-jung jo young-jin kim young-sun kim ja-young lee hwang-eui ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-nguc-phan-2', 'Vượt Ngục (Phần 2)', 'Prison Break (Season 2)', 'https://phimimg.com/upload/vod/20240409-1/8477ef8dc0c7ade9b3d7fdf8753b3497.jpg', 'https://phimimg.com/upload/vod/20240409-1/d6046941dd4a8a9beae7283b3aade74b.jpg', '<p>Phần hai bắt đầu từ tám giờ kể từ lúc trốn thoát, tập trung chủ yếu vào từng tên tù vượt ngục. Các tù nhân tách ra, chạy trốn và ẩn náu trên khắp đất nước trong khi giới chức trách luôn theo sát phía sau, săn đuổi họ vì những mục đích khác nhau. Brad Bellick - quản giáo trại giam - bị sa thải và tham gia cuộc truy lùng vì món tiền thưởng kếch xù. Vài người trong nhóm vượt ngục liên kết lại cùng nhau đi tìm một số tiền lớn được cất giấu cách đó khá lâu bởi một tù nhân khác. Alexander Mahone - Đặc vụ liên bang được giao nhiệm vụ truy tìm và bắt sống tám tên tù vượt ngục, nhưng bị phát hiện đang làm việc cho Hội Đồng Hành (The Company) - Hội Đồng Hành muốn 8 tên tù phải chết.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 13, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dominic Purcell","avatar":""},{"name":"Wentworth Miller","avatar":""},{"name":"Amaury Nolasco","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Sarah Wayne Callies","avatar":""},{"name":"Wade Williams","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Paul Adelstein","avatar":""},{"name":"Marshall Allman","avatar":""},{"name":"Rockmond Dunbar","avatar":""},{"name":"Jodi Lyn O''keefe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324523);
