INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('smokin-aces', 'Smokin'' Aces', 'Smokin'' Aces', 'https://phimimg.com/upload/vod/20240228-1/2c6f214ec4d37c827f29c4a6f85c8d52.jpg', 'https://phimimg.com/upload/vod/20240228-1/a59dabbc4dec505e7992a762b060172f.jpg', '<p>Tại một góc đường yên tĩnh, người qua đường bắt gặp một chiếc xe tải nhỏ nằm im lìm suốt nhiều ngày đêm. Trong thùng xe, cảnh sát đang cố lắng nghe mọi động tĩnh bên trong ngôi biệt thự bên đường.
 Sau tất cả những tội ác tay trùm Primo Sparazza gây ra, cảnh sát chỉ trông chờ tìm thấy một bằng chứng thuyết phục để tống cổ tên khốn vào nhà đá. Nhưng mọi tội ác đều được gột rửa không một chút dấu vết. Buddy “Aces” Israel, kẻ được mệnh danh là Thần Bài vời các màn biểu diễn điệu nghệ tại các sòng bạc vùng Lake Jahoe, Neveda, từng là tay thân tín nhất của Sparazza. Những ngày gần đây, tên Buddy ngày càng trở nên chướng mắt.
 Trong những cuộc điện thoại, cảnh sát được biết Sparazza sẵn sàng trả một triệu đô cho tên côn đồ nào muốn phanh thây tên khốn Buddie. Chỉ đợi có thế, cảnh sát lập tức nhập cuộc với chương trình “Bảo Vệ Nhân Chứng” của FBI…</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Andy García","avatar":""},{"name":"Martin Henderson","avatar":""},{"name":"Chris Pine","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Alicia Keys","avatar":""},{"name":"Common","avatar":""},{"name":"Taraji P. Henson","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Ben Affleck","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324523);
