INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-bac-nghiet-nga', 'Canh Bạc Nghiệt Ngã', 'Tazza: The High Rollers', 'https://phimimg.com/upload/vod/20240228-1/727d3a1175df5655bb0bc9a67379152e.jpg', 'https://phimimg.com/upload/vod/20240228-1/450b2376879899ee4aeaf524f5aa143a.jpg', '<p>Go-ni cố gắng hết sức để tôn thờ Pyung Gyung-jang như thầy của mình và hứa sẽ ngừng cờ bạc sau khi giành lại được tiền. Nhưng mong muốn của con người là vô tận.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Cho Seung-woo","avatar":""},{"name":"Kim Hye-soo","avatar":""},{"name":"Choi Dong-hoon","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324523);
