INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuon-nho', 'Vườn Nho', 'The Vineyard Man', 'https://phimimg.com/upload/vod/20240228-1/286168aec19cda3355cc463e7724e3c6.jpg', 'https://phimimg.com/upload/vod/20240228-1/0b0c1a36cd2e3e9be0f0daf3a5dada47.jpg', '<p>The Vineyard Man là một bộ phim truyền hình Hàn Quốc năm 2006 được phát sóng trên kênh KBS2. Nó được chuyển thể từ cuốn sách bán chạy nhất cùng tên của Kim Rang.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 15, 2006, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Yoon Eun-hye","avatar":""},{"name":"Oh Man-seok","avatar":""},{"name":"Kim Ji-seok","avatar":""},{"name":"Kim Chang-wan","avatar":""},{"name":"Lee Hwa-sun","avatar":""},{"name":"Jeong So-yeong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
