INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vuon-nho', 'Vườn Nho', 'The Vineyard Man', 'vườn nho the vineyard man yoon eun-hye oh man-seok kim ji-seok kim chang-wan lee hwa-sun jeong so-yeong ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-nguyen-thuy', 'Linh Hồn Nguyên Thủy', 'Origin: Spirits Of The Past', 'https://phimimg.com/upload/vod/20240227-1/787ab6ad563bfce952d6dd86a14f29d0.jpg', 'https://phimimg.com/upload/vod/20240227-1/9a3d77e285a0835f66d1396d250c10cc.jpg', '<p>Phim lấy bối cảnh 300 năm sau sự kiện những cái cây có ý thức trong một phòng thí nghiệm trên Mặt Trăng được tạo ra với khả năng phát triển trong điều kiện khắc nghiệt và khô cằn đã quyết định thoát ra phá hủy Mặt Trăng và hủy diệt nền văn minh của con người cũng như phục hồi lại Trái Đất như lúc nguyên sinh là được bao phủ bởi rừng. Cốt truyện phim xoay quanh cậu bé có mái tóc trắng tên Agito là hậu duệ của những người sống sót đã học cách thích nghi và cùng tồn tại với thiên nhiên. Cậu đã vô tình tìm ra một cô gái đã ngủ suốt 300 năm đeo một chiếc vòng cổ có thể đánh thức một thứ vũ khí khổng lồ từ 300 năm trước. Việc này đã khiến cô trở thành mục tiêu của những thế lực muốn phá hủy thiên nhiên và giành lại thế giới của con người như trước kia. Được thiên nhiên ban cho sức mạnh Agito đã lên đường giải cứu cô.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Aoi Miyazaki","avatar":""},{"name":"Yûko Kotegawa","avatar":""},{"name":"Masaru Hamaguchi","avatar":""},{"name":"Ryo Katsuji","avatar":""},{"name":"Toshikazu Fukawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c430