INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-ho-mon', 'Long Hổ Môn', 'Dragon Tiger Gate', 'null', 'https://phimimg.com/upload/vod/20240227-1/04ca87e353b8525a12adabb7706bde10.jpg', '<p>Long Hổ Môn - Dragon Tiger Gate là bộ phim kể về Tiểu Long vốn là đệ tử của Long Hổ Môn. Vì hoàn cảnh hai mẹ con anh đã phải rời khỏi môn phái. Tuy sống ở Hắc bang hoành hành bá đạo, nhưng trong anh vẫn là một Tiểu Long trượng nghĩa và một quyết tâm đường đường chính chính trở về Long Hổ Môn. Để giúp anh hoàn thành tâm nguyện, đại ca của Hắc bang là Mã Khôn nhất thời đồng ý rửa tay gác kiếm. Nhưng giang hồ không một ai có thể tự quyết định vận mệnh của mình. Mã Khôn đã bị thảm sát khi xúc phạm đến Tà Thần Hoả Vân – đại ma đầu La Sát giáo, bằng việc trả lại La Sát lệnh cho hắn. Để cứu người yêu là Tiểu Long, nữ La Sát đành lòng chuyển cơn thịnh nộ của Tà Thần về phía Long Hổ Môn. Kể từ đó những trận đấu long trời lở đất bắt đầu…</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nicholas Tse","avatar":""},{"name":"SHAWN YUE","avatar":""},{"name":"Donnie Yen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324523);
