INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-tu-do-vat', 'Thầy Tu Đô Vật', 'Nacho Libre', 'https://phimimg.com/upload/vod/20240220-1/b7d0da21dbb9b42b9f19eff3bcdbaa3b.jpg', 'https://phimimg.com/upload/vod/20240220-1/5b4a2382d1eb33d397afd14df2292373.jpg', '<p>Nacho Libre dựa trên câu chuyện về Fray Tormenta (Friar Storm), hay còn gọi là Rev. Sergio Gutierrez Benitez, một linh mục Công giáo người Mexico ngoài đời thực, người đã có 23 năm làm luchador đeo mặt nạ. Anh ấy đã thi đấu để hỗ trợ trại trẻ mồ côi mà anh ấy chỉ đạo.</p>', 'Full', 1, 'single', 'completed', 23, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Black","avatar":""},{"name":"Ana de la Reguera","avatar":""},{"name":"Héctor Jiménez","avatar":""},{"name":"Darius Rose","avatar":""},{"name":"Moisés Arias","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324523);
