INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-boss-my-teacher', 'My Boss, My Teacher', 'My Boss, My Teacher', 'https://phimimg.com/upload/vod/20240220-1/b0409e3cd99441ab0480454a5a6c67aa.jpg', 'https://phimimg.com/upload/vod/20240220-1/fc5f453fd7feb29b89c84dfa83776703.jpg', '<p>Doo-sik (Jung Jun-ho), số hai của một băng đảng hàng đầu, những con chó D, đầy tham vọng và kỳ vọng, vì cơ hội thời gian cuộc sống của anh ta để trở lại trường học không phải là một học sinh chứ không phải Bảo vệ, nhưng là một giáo viên học sinh! Đó thực sự là một cái gì đó đối với anh ta, vì anh ta đã không hoàn thành khóa học trung học của mình nhiều năm trước. Bây giờ nó là một cơ hội thứ hai cho anh ta. Anh ta chỉ giải thích hành nghề giảng dạy này như một thứ giống như một khóa học thích ứng xã hội cho các tù nhân sẽ được giải thoát và trở lại xã hội sớm. Nhưng anh ấy đã có những gì nó cần là một giáo viên? Ngay cả vào ngày đầu tiên, anh ta chỉ ra khỏi đường và lập dị. Anh vào trường qua lỗ chó. Và sẽ mất nhiều thời gian để tổng hợp rằng hành vi của anh ta chỉ là quá nhiều cho các sinh viên chấp nhận và tôn trọng trong một giáo viên. Và khi số phận sẽ có nó, ông chủ của chính mình, thủ lĩnh của những con chó D, hiện đang ở ngay trước mặt anh ta, như một trong những sinh viên, và hai người đàn ông trung thành của anh ta nằm ngoài tầm với mỗi khi anh ta gặp rắc rối! Doo-sik chỉ lao theo cách này và lao theo cách đó và tất cả các sự cố đang dẫn đầu doo-sik đến một nơi không ai mong đợi.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324523);
