INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-y-than-tuong', 'Bố Y Thần Tướng', 'Bố Y Thần Tướng', 'https://phimimg.com/upload/vod/20240215-1/b7f61d32087116a096cf22321f82eb2d.jpg', 'https://phimimg.com/upload/vod/20240215-1/524655c96ab21ef850ca8454457e8126.jpg', '<p>Lý Bố Y vốn tinh thông tướng thuật, mang trọng trách tìm lại các cao thủ trong cuộc chiến Kim Ấn nhưng luôn gặp phải sự cản trở từ Lại Dược Nhi – thần y phía Hắc đạo. Vì Bạch đạo, vì thanh lý môn hộ, vì phải xóa bỏ điềm báo Ma trưởng Đạo tiêu, Bố Y không thể tránh khỏi trận quyết chiến cùng Dược Nhi…</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 26, 2006, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Lâm Văn Long","avatar":""},{"name":"Lâm Phong","avatar":""},{"name":"Dương Di","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324523);
