INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('karin', 'Karin', 'Karin', 'https://phimimg.com/upload/vod/20240215-1/089198d5d711adaf8692b426212ff229.jpg', 'https://phimimg.com/upload/vod/20240215-1/3b0f72178d74b27dc6ec2294648ecaee.jpg', '<p>Maaka Karin sinh ra trong một gia đình vampire nhưng cô không hẳn là một vampire. Điểm khác biệt của cô với các vampire khác trong gia đình là cô có thể đi ra ngoài nắng, ăn tỏi, thích cây thánh giá, bơi lội dưới nước, và đặc biệt nhất là cô không hề đi “hút máu” người mà ngược lại là … “phun máu” mỗi khi gặp ai đó đang bất hạnh. Một ngày kia, một cậu học sinh mới chuyển tới lớp cô tên là Usui đã bất ngờ biết được bí mật của cô. Và mọi chuyện bắt đầu từ đây…</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 20, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324523);
