INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-hwang-jin-yi', 'Nàng Hwang Jin Yi', 'Hwang Jin Yi', 'https://phimimg.com/upload/vod/20240215-1/a6585b213302bbd10bd4f26953f08e9a.jpg', 'https://phimimg.com/upload/vod/20240215-1/5dc345cd39ef2a91f4b768b88fb6aa16.jpg', '<p>Câu chuyện về Hwang Jin Yi, Gisaeng nổi tiếng thế kỷ 16. Câu chuyện kể về cuộc đời của vũ công, nhạc sĩ và nhà thơ thời Joseon, Hwang Jin Yi, người không ngừng tìm kiếm sự hoàn hảo trong nghệ thuật của mình và những khó khăn mà phụ nữ phải đối mặt do địa vị xã hội thấp kém của họ. Hwang Jin Yi là con ngoài giá thú của một quý tộc và Heon Keum, một nhạc sĩ nổi tiếng gisaneg. Câu chuyện xoay quanh bốn người đàn ông trong cuộc đời cô và cô theo đuổi nghệ thuật khiêu vũ. Mối tình đầu của cô với con trai một nhà quý tộc Kim Eun Ho kết thúc trong bi kịch. Mối tình của cô và Kim Jung Han cũng không có một kết thúc có hậu. Byuk Kye Soo là người thân của Hoàng hậu, người bị ám ảnh bởi cô ấy và đã thử mọi thủ đoạn nhưng vẫn không thể có được cô ấy. Cuối cùng là vệ sĩ tận tụy của cô, Yi Saeng, người không bao giờ bỏ rơi cô những lúc cần thiết. Trong khi đó, có Bu Yong, người không chỉ là đối thủ của Hwang Ji Yi về vũ đạo mà còn về tình yêu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2006, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
