INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-la-cai-dinh-gi', 'Không Là Cái Đinh Gỉ', 'Big Nothing', 'https://phimimg.com/upload/vod/20240220-1/e0dec2748acb31e296a1592107fc75ae.jpg', 'https://phimimg.com/upload/vod/20240220-1/c8037a330d0054d762d7ede60bbb050f.jpg', '<p>Một giáo viên thất nghiệp thất vọng liên kết với một kẻ lừa đảo và bạn gái của hắn trong một âm mưu tống tiền.</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Schwimmer","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Natascha McElhone","avatar":""},{"name":"Jon Polito","avatar":""},{"name":"Mimi Rogers","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
