INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-chua-giang-sinh', 'Câu Chuyện Chúa Giáng Sinh', 'The Nativity Story', 'https://phimimg.com/upload/vod/20240219-1/ddd1b88bf9eba2b1ecc9b2bc14ebced4.jpg', 'https://phimimg.com/upload/vod/20240219-1/4294f5e5c69b6d831c43716a5044f3ee.jpg', '<p>Ma-ri và Giô-sép thực hiện cuộc hành trình gian khổ đến Bết-lê-hem vì một sự kiện may mắn trong phần kể lại câu chuyện Chúa giáng sinh này. Bản chuyển thể câu chuyện trong Kinh thánh được nghiên cứu tỉ mỉ và có hình ảnh đẹp mắt này theo chân cặp đôi trên con đường gian khổ đến một ngôi làng nhỏ, nơi họ tìm thấy nơi trú ẩn trong một máng cỏ yên tĩnh và Chúa Giê-su ra đời.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keisha Castle-Hughes","avatar":""},{"name":"Oscar Isaac","avatar":""},{"name":"Hiam Abbass","avatar":""},{"name":"Shaun Toub","avatar":""},{"name":"Ciarán Hinds","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
