INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cashback', 'Cashback', 'Cashback', 'https://phimimg.com/upload/vod/20240207-1/8a68954f8928ca625af99500fd0fe26a.jpg', 'https://phimimg.com/upload/vod/20240207-1/572d3493c3e07f982481d805fb3a03d9.jpg', '<p>Khi sinh viên nghệ thuật Ben Willis chia tay với bạn gái Suzy, anh ta phát triển chứng mất ngủ mạn tính sau khi tìm hiểu xem cô ấy nhanh lên như thế nào. Để vượt qua nhiều giờ trong đêm, anh ta bắt đầu làm việc ca đêm muộn tại siêu thị địa phương. Ở đó, ông gặp một dàn nhân vật đầy màu sắc, tất cả những người đều có nghệ thuật của riêng mình trong việc đối phó với sự nhàm chán của một ca làm việc tám giờ. Nghệ thuật của Ben là anh ấy tưởng tượng mình đang dừng thời gian. Bằng cách này, anh ta có thể đánh giá cao vẻ đẹp nghệ thuật của thế giới đông lạnh và những người trong đó - đặc biệt là Sharon, cô gái kiểm tra xinh đẹp và yên tĩnh, có lẽ có câu trả lời để giải quyết vấn đề mất ngủ của Ben.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324523);
