INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('day-la-nuoc-anh', 'Đây Là Nước Anh', 'This Is England', 'https://phimimg.com/upload/vod/20240207-1/61484688cfbf6506f304e83d5fab2936.jpg', 'https://phimimg.com/upload/vod/20240207-1/73209c84a36c41677e736b769df9a15a.jpg', '<p>Lấy bối cảnh những năm 1980 và kể về cuộc đời của cậu bé Shaun (Thomas Turgoose) mất cha từ nhỏ trong cuộc chiến Falklands. 12 tuổi cậu liên tục trốn học và đi lang thang khắp nơi. Một ngày Shaun gặp một nhóm thanh thiếu niên do Woody dẫn đầu, do cảm thông với Shaun nên họ quyết định mời cậu tham gia vào nhóm. Tại nhóm này, Shaun tìm thấy hình bóng của một người anh trai từ Woody, sự yêu quý và tôn trọng từ các thành viên khác và những cảm xúc đầu đời khó quên từ Smell, một cô gái lớn tuổi hơn... tuy nhiên mọi thứ dần thay đổi khi Combo (Stephen Graham), một gã theo chủ nghĩa dân tộc quốc gia và phân biệt chủng tộc quay lại nhóm sau 1 thời gian ở tù và tước quyền thủ lĩnh của Woody...</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Thomas Turgoose","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Jo Hartley","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324523);
