INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nham-hoan-thu', 'Yêu Nhầm Hoạn Thư', 'My Super Ex-Girlfriend', 'https://phimimg.com/upload/vod/20240207-1/76bd1ef877babf7699f0edeefdece677.jpg', 'https://phimimg.com/upload/vod/20240207-1/171e3dff2dba0701ccac329b4ae8f5f4.jpg', '<p>Yêu Nhầm Hoạn Thư - My Super Ex-Girlfriend xoay quanh Jenny Johnson. Đời thường, cô là một sinh viên hiền lành và cởi mở. Nhưng mỗi khi xảy ra cháy nhà, cướp bóc hay bất kỳ sự cố nào ở Manhattan, cô liền biến thành một nữ siêu nhân mang tên G-Girl. Cô có thể nhấc bổng được ô tô, bay lượn trên không với tốc độ tên lửa, nghe được mọi âm thanh trong bán kính vài dặm, nhìn rõ trong bóng đêm và không thể bị thương bằng súng đạn hay dao kiếm. Cuộc sống của Jenny thay đổi kể từ khi cô gặp Matt Saunders – nhân viên của một công ty kiến trúc – cùng với bạn của anh này là Vaughn Haige trong một chuyến tàu điện ngầm.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Uma Thurman","avatar":""},{"name":"Anna Faris","avatar":""},{"name":"Luke Wilson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
