INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bloody-reunion', 'Bloody Reunion', 'Bloody Reunion', 'https://phimimg.com/upload/vod/20240220-1/29e50d17d558e723c3d292749df7460d.jpg', 'https://phimimg.com/upload/vod/20240220-1/feade2548109342c6c54a0d80dc166c1.jpg', '<p>Những mối hận thù bị chôn vùi có những hậu quả thảm hại cho một cuộc hội ngộ đẳng cấp trong bộ phim đẫm máu chưa hợp lý này từ Giám đốc Hàn Quốc Dae-Woong Lim.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324523);
