INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-va-danh-du-2006', 'Tình Yêu Và Danh Dự', 'Love And Honor', 'https://phimimg.com/upload/vod/20240128-1/0534a6aa9308785ba0f86211a3ad3b59.jpg', 'https://phimimg.com/upload/vod/20240128-1/c8c06fd9089e08b016cafe80872f9f6f.jpg', '<p>Mimura Shinojo chuyên làm việc nếm thử thức ăn cho vị lãnh chúa. Nếu thức ăn có chất độc, anh sẽ là người bị mất mạng trước. Đây là một cách để các võ sĩ samurai tỏ rõ lòng trung thành của mình đối với chủ nhân. Trong một lần nếm món ốc sên sống có độc, cả hai mắt Mimura vĩnh viễn mất ánh sáng. Nỗi bất hạnh của anh không dừng lại ở đó. Không nguồn sinh sống, vợ anh, Kayo buộc phải cầu cứu một người có thế lực và bị thất thân. Tâm hồn Mimura rất đỗi đau đớn, bị giằng xé giữa một bên là danh dự samurai, một bên là tình yêu dành cho người vợ thương yêu mình hết mực.</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takuya Kimura","avatar":""},{"name":"Rei Dan","avatar":""},{"name":"Takashi Sasano","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324523);
