INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('avengers-tran-chien-cuoi-cung', 'Avengers: Trận Chiến Cuối Cùng', 'Ultimate Avengers: The Movie', 'https://phimimg.com/upload/vod/20240128-1/72824a2b39de2fbb3e9617058b2f9eb3.jpg', 'https://phimimg.com/upload/vod/20240128-1/4278b5bc228cbc7963f50547e6c76cff.jpg', '<p>Khi một tên lửa hạt nhân được bắn vào Washington vào năm 1945, Captain America đã cho nổ nó ở tầng trên của bầu khí quyển. Nhưng sau đó ông đã rơi hàng dặm xuống vực sâu băng giá của Bắc Đại Tây Dương, nơi ông lưu lạc hơn sáu mươi năm. Nhưng giờ đây, khi thế giới đang đối mặt với cùng một ác quỷ, Captain America phải trỗi dậy trở lại như là hy vọng sống sót cuối cùng của chúng ta.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fred Tatasciore","avatar":""},{"name":"Justin Gross","avatar":""},{"name":"Michael Massee","avatar":""},{"name":"Olivia d''Abo","avatar":""},{"name":"Grey DeLisle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324523);
