INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aquamarine', 'Aquamarine', 'Aquamarine', 'https://phimimg.com/upload/vod/20240128-1/ea0746a9e75e10c352479441c481706e.jpg', 'https://phimimg.com/upload/vod/20240128-1/b57ecfb352ce4fb823d64a376a1f1c1d.jpg', '<p>Hai cô gái tuổi teen phát hiện ra rằng nàng tiên cá thực sự tồn tại sau khi một cơn bão dữ dội cuốn trôi một người vào bờ biển. Nàng tiên cá, một sinh vật ngổ ngáo tên là Aquamarine, quyết tâm chứng minh cho cha mình thấy rằng tình yêu thực sự tồn tại và nhờ các cô gái giúp đỡ để giành được trái tim của một nhân viên cứu hộ đẹp trai.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma Roberts","avatar":""},{"name":"JoJo","avatar":""},{"name":"Sara Paxton","avatar":""},{"name":"Jake McDorman","avatar":""},{"name":"Arielle Kebbel","avatar":""},{"name":"Claudia Karvan","avatar":""},{"name":"Bruce Spence","avatar":""},{"name":"Tammin Sursok","avatar":""},{"name":"Roy Billing","avatar":""},{"name":"Julia Blake","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324523);
