INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-mong-gay-huyen-thoai', 'Chiếc Móng Gảy Huyền Thoại', 'Tenacious D In The Pick Of Destiny', 'https://phimimg.com/upload/vod/20240128-1/64a0ff4d68e4d1e4b51825446785a5af.jpg', 'https://phimimg.com/upload/vod/20240128-1/263e9fcf5dc52e1a72c1be166e380865.jpg', '<p>Chiếc Mỏng Gảy Huyền Thoại - Tenacious D In The Pick Of Destiny là một bộ phim âm nhạc hài của đạo diễn Liam Lynch. Nhạc sĩ JB (Jack Black) và KG (Kyle Gass) bắt đầu một tình bạn và thành lập một ban nhạc rock vĩ đại nhất trên thế giới. Để biến ước mơ đó trở thành sự thật, bộ đôi này tham gia vào một nhiệm vụ tìm kiếm một cây đàn guitar huyền thoại sở hữu sức mạnh siêu nhiên. Liệu cả hai có thể vượt qua những khó khăn để trở thành huyền thoại hay không?</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Black","avatar":""},{"name":"Kyle Gass","avatar":""},{"name":"JR Reed","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324523);
