INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-bo-mandy-lane', 'Khủng Bố Mandy Lane', 'All The Boys Love Mandy Lane', 'https://phimimg.com/upload/vod/20240128-1/bca7f5916c4ccbdee6de8e011ca25ad5.jpg', 'https://phimimg.com/upload/vod/20240128-1/00889193ee808a0bfab411630eea2afe.jpg', '<p>Khủng Bố Mandy Lane - All The Boys Love Mandy Lane: Mandy Lane là một thiếu nữ xinh đẹp và trong trắng. Cô bé mồ côi, lớn lên trong sự chăm sóc của dì, và là đích nhắm của tất cả các chàng trai ở trường. Sau cái chết của một người bạn tại buổi tiệc tại hồ bơi, Mandy kết bạn với Chloe, Markin, Red, Bird và Jake.</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amber Heard","avatar":""},{"name":"Anson Mount","avatar":""},{"name":"Whitney Able","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324523);
