INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-mui-heo', 'Cô Nàng Mũi Heo', 'Penelope', 'https://phimimg.com/upload/vod/20240126-1/f315b7e14c7b360f1ee44ef3f563b54e.jpg', 'https://phimimg.com/upload/vod/20240126-1/bbb87ef39b0afd016b49444db2c6c134.jpg', '<p>Người thừa kế bị bỏ rơi Penelope Wilhern bị nguyền rủa, và lối thoát duy nhất là phải lòng một người phù hợp. Nhưng làm sao cô ấy có thể tìm được người bạn tâm giao của mình khi cô ấy bị cô lập trong khu đất của gia đình mình chỉ có cha mẹ cô ấy bầu bạn. Câu chuyện cổ tích phi truyền thống này kể về một cô gái bất chấp quy ước để tạo ra một kết thúc có hậu cho riêng mình.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christina Ricci","avatar":""},{"name":"James McAvoy","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"Peter Dinklage","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324523);
