INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don', 'Don', 'Don', 'https://phimimg.com/upload/vod/20240126-1/20e17e67ea0ef08f378dffc96fdc6051.jpg', 'https://phimimg.com/upload/vod/20240126-1/5d6c632771bd963f75c5f02032cd5f95.jpg', '<p>DCP DeSilva tìm ra cách đưa kẻ đứng đầu đáng sợ của đế chế tội phạm ra trước công lý bằng cách chiêu mộ một người tên Vijay, người trông giống hệt tên trùm tội phạm. Mưu mẹo hoạt động quá tốt, và chẳng bao lâu Vijay nhận thấy tính mạng của mình gặp nguy hiểm khi DeSilva, người duy nhất biết danh tính thực sự của anh, qua đời.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Shah Rukh Khan","avatar":""},{"name":"Priyanka Chopra","avatar":""},{"name":"Arjun Rampal","avatar":""},{"name":"Isha Koppikar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
