INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trom-giac-mo', 'Kẻ Trộm Giấc Mơ', 'Paprika', 'https://phimimg.com/upload/vod/20240126-1/3b13fbf1b967ee2428f8ffa72663518d.jpg', 'https://phimimg.com/upload/vod/20240126-1/48dbc5f50673929737c7227a25046ba6.jpg', '<p>Ba nhà khoa học tại nền tảng cho nghiên cứu tâm thần không đảm bảo một thiết bị mà họ đã phát minh ra, D.C. Mini, cho phép mọi người ghi lại và xem những giấc mơ của họ. Một tên trộm sử dụng thiết bị để vào tâm trí của mọi người, khi thức dậy, và đánh lạc hướng họ với những giấc mơ của chính họ và những người khác. Chaos xảy ra. Bộ ba - Chiba, Tokita và Shima - được hỗ trợ bởi một thanh tra cảnh sát và bởi một sprite tên là Paprika phải cố gắng xác định kẻ trộm khi họ phẫn nộ các cuộc tấn công của kẻ trộm vào tâm lý của chính họ. Những giấc mơ, thực tế và những bộ phim hợp nhất, trong khi các nhân vật đặt câu hỏi về giới hạn của khoa học và sự khôn ngoan của người anh lớn.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324523);
