INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-duong-gian', 'Trở Lại Dương Gian', 'Scoop', 'https://phimimg.com/upload/vod/20240123-1/5d03ab20d7def4438f11312cc28edce9.jpg', 'https://phimimg.com/upload/vod/20240123-1/dba3b0096be3e7600af955631353058a.jpg', '<p>Một sinh viên báo chí người Mỹ ở London biết được một câu chuyện lớn và bắt đầu ngoại tình với một quý tộc khi vụ việc xảy ra.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Woody Allen","avatar":""},{"name":"Hugh Jackman","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Charles Dance","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
