INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-chu-xinh-dep', 'Cô Chủ Xinh Đẹp', 'Volver', 'https://phimimg.com/upload/vod/20240123-1/d85b264cd99be730e17d8b3a30267ccb.jpg', 'https://phimimg.com/upload/vod/20240123-1/6f7144db1691d26361be642da78201fc.jpg', '<p>Raimunda sống và làm việc ở Madrid với chồng là Paco và con gái Paula của họ. Em gái của Raimunda là Sole sống gần đó. Hai chị em nhớ mẹ Irene, người đã chết cách đây vài năm trong một vụ cháy nhà cùng với cha của họ. Khi một người hàng xóm cũ ở quê nhà của họ báo cáo rằng cô ấy đã nhìn thấy hồn ma của Irene, các cô con gái không tin cô ấy. Tuy nhiên, sau một vụ giết người và một bi kịch gia đình, linh hồn của Irene hiện hình xung quanh các cô con gái của cô để an ủi họ.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Penélope Cruz","avatar":""},{"name":"Carmen Maura","avatar":""},{"name":"Lola Dueñas","avatar":""},{"name":"Blanca Portillo","avatar":""},{"name":"Yohana Cobo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
