INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-doi-cam-tu', 'Phi Đội Cảm Tử', 'Flyboys', 'https://phimimg.com/upload/vod/20240126-1/f8b1a7b79c67ff6fd02461d03bad0429.jpg', 'https://phimimg.com/upload/vod/20240126-1/969b6a204e241a4d779b1c6e6c2b40e0.jpg', '<p>Nội dung phim kể về cuộc chiến tranh thế giới lần thứ nhất nổ ra tại châu Âu vào năm 1917, Pháp, Anh và Italia liên minh để chống lại quân đội Đức hung hãn. Trong khi đó ở bên kia Đại Tây Dương, phần lớn thanh niên Mỹ không tán thành cuộc chiến nhưng họ cũng tình nguyện chiến đấu bên cạnh đồng minh ở chiến trường trên đất Pháp. Một số tham gia bộ binh, số khác gia nhập các đoàn cứu thương. Tuy nhiên, một nhóm nhỏ có suy nghĩ hoàn toàn khác với quyết định học lái máy bay và câu chuyện của họ bắt đầu.Buộc phải từ giã gia đình, Blaine Rawlings bắt đầu tìm kiếm tương lai trên đất Pháp xa xôi. Tại ga xe lửa cùng vùng Nebraska, William Jensen hứa hẹn sẽ là niềm tự hào của gia đình.Trong khi đó, Briggs Lowry cũng vừa rời New York để lên đường vượt đại dương. Họ không hẹn trước mà gặp nhau để trở thành đồng đội.Tuy nhiên, những gì mà họ tưởng tượng ra là họ sắp bước vào một chuyến phiêu lưu nguy hiểm và lãng mạn để trở thành những không quân đầu tiên của thế giới…</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Franco","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Jennifer Decker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324523);
