INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ty-hon', 'Người Tý Hon', 'Little Man', 'https://phimimg.com/upload/vod/20240124-1/f27d6cc7d50add7a8c5a2563d0354ff0.jpg', 'https://phimimg.com/upload/vod/20240124-1/473a2bbeb11f4e64aba8e33ce7fe5bbd.jpg', '<p>Sau nhiều năm phải ngồi gỡ lịch trong nhà đá, tên trộm kim cương Calvin quyết định sẽ rút khỏi chốn giang hồ, nhưng y chỉ cam tâm rút lui sau khi làm thêm một vụ ra trò nữa với người bạn đồng nghiệp Percy. Nhờ có “lợi thế” ngoại hình chỉ bằng một cậu nhóc sơ sinh, Calvin lẻn vào ngăn tủ đựng kim cương một cách rất dễ dàng. Nhưng lưới trời quả thật rất khó thoát. Calvin và Percy bị cảnh sát truy đuổi vào đến tận siêu thị. Trong tình huống nguy cấp, để tránh sự nghi ngờ, Calvin đã nhét viên kim cương khổng lồ vào chiếc giỏ xách của một phụ nữ đang mua hàng cùng chồng. Người phụ nữ đó là Vanessa và chồng cô là Darryl. Cả hai trở về nhà, hoàn toàn không hay biết gì về sự tồn tại của viên kim cương ăn cắp nằm trong giỏ...</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shawn Wayans","avatar":""},{"name":"Marlon Wayans","avatar":""},{"name":"Kerry Washington","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324523);
