INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-ben-ho', 'Ngôi Nhà Bên Hồ', 'The Lake House', 'https://phimimg.com/upload/vod/20240118-1/de67e3228ba6e8aefca33137f45cdf7f.jpg', 'https://phimimg.com/upload/vod/20240118-1/9b451f9a6d6105441bc4c2606e87fead.jpg', '<p>Bộ phim kể về câu chuyện tình vượt thời gian của anh chàng kiến trúc sư cô độc Alex và cô bác sĩ Kate thông qua việc trao đổi thư ở một ngôi nhà ven hồ. Cả hai người họ phải vượt qua 2 năm cách biệt để tìm cách giải mã những bí ẩn đứng phía sau mối quan hệ kỳ lạ này...</p>', 'Full', 1, 'single', 'completed', 9, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Sandra Bullock","avatar":""},{"name":"Christopher Plummer","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324523);
