INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-tro-lai-2006', 'Siêu Nhân Trở Lại', 'Superman Returns', 'https://phimimg.com/upload/vod/20240104-1/74e87729efed4c765d210b5482f193d5.jpg', 'https://phimimg.com/upload/vod/20240104-1/5d096eb68f9bab57706f7d68111a3add.jpg', '<p>Sau một cuộc vắng mặt bí ẩn vài năm, người đàn ông của thép trở về Trái đất trong Siêu nhân phiêu lưu hành động hoành tráng trở lại, một chương mới tăng vọt trong Saga của một trong những siêu anh hùng yêu thích nhất thế giới. Trong khi một kẻ thù cũ sẽ khiến anh ta bất khả xâm phạm một lần và mãi mãi, Superman phải đối mặt với việc nhận ra sự đau lòng mà người phụ nữ yêu, Lois Lane, đã chuyển đến cuộc sống của mình. Hay có cô ấy? Supermans Bittersweet Return thách thức anh ta thu hẹp khoảng cách giữa họ trong khi tìm một nơi trong một xã hội đã học cách sống sót mà không có anh ta. Trong một nỗ lực để bảo vệ thế giới, anh ta yêu thích sự hủy diệt của Cataclysmic, Superman bắt đầu một hành trình cứu chuộc sử thi đưa anh ta từ sâu thẳm đại dương đến xa vươn xa.</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brandon Routh","avatar":""},{"name":"Kevin Spacey","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Parker Posey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324523);
