INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('teen-titans-rac-roi-o-tokyo', 'Teen Titans: Rắc Rối Ở Tokyo', 'Teen Titans: Trouble In Tokyo', 'https://phimimg.com/upload/vod/20240104-1/c3eb8fe69c13f553f8a4bbe4c2dbea24.jpg', 'https://phimimg.com/upload/vod/20240104-1/b0d4b458a7944fff8a7ee5314365070f.jpg', '<p>Vào một ngày, một tên ninja hiện đại xuất hiện và đã tấn công thành phố cũng như tháp Titans. Các Titan đã rất vả mới có thể bắt được hắn và biết được hắn là Saico Tek, được phái đến bởi một tên tội phạm bí ẩn và nguy hiểm có tên là Brushogun. Và thế là các Titan đã tới Nhật Bản để truy tìm tên tội phạm đó</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Greg Cipes","avatar":""},{"name":"Khary Payton","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Hynden Walch","avatar":""},{"name":"Robert Ito","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324523);
