INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nang-goc-2', 'Bản Năng Gốc 2', 'Basic Instinct 2', 'https://phimimg.com/upload/vod/20240104-1/b0bd45f5e907978a858864be767a3bbc.jpg', 'https://phimimg.com/upload/vod/20240104-1/fbbd9886a3d8f442c406232edb1e160d.jpg', '<p>Tiếp theo phần 1 đã ra mắt vào năm 1994, lần này tiểu thuyết gia Catherine Tramell lại một lần nữa gặp rắc rối với cảnh sát khi họ cử bác sĩ tâm thần học Andrew Glass đến phỏng vấn để xem xét cô có đủ điều kiện dự phiên tòa xét xử hay không. Và như thanh tra Nick Curran trước đây, Glass cũng bị Catherine chinh phục và dần dần sa chân vào trò chơi quyến rũ đầy chết người của cô.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sharon Stone","avatar":""},{"name":"David Morrissey","avatar":""},{"name":"Charlotte Rampling","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Stan Collymore","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
