INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('marie-antoinette', 'Marie Antoinette', 'Marie Antoinette', 'https://phimimg.com/upload/vod/20240103-1/1d48271faefcb66ce336a32c4bf3f016.jpg', 'https://phimimg.com/upload/vod/20240103-1/930556ff5b52e0a153932f0d7479c1ce.jpg', '<p>Việc kể lại Nữ hoàng mang tính biểu tượng nhưng xấu của Pháp, Marie Antoinette. Từ sự hứa hôn và hôn nhân của cô ấy đến Louis XVI ở tuổi 14 để triều đại của cô ấy với tư cách là nữ hoàng ở tuổi 19 và đến cuối triều đại của cô ấy như nữ hoàng, và cuối cùng là sự sụp đổ của Versailles.</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
