INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-vuot-thoi-gian-2006', 'Cô Gái Vượt Thời Gian', 'The Girl Who Leapt Through Time', 'https://phimimg.com/upload/vod/20240108-1/cf367982c035d5063ada04b656b6d35f.jpg', 'https://phimimg.com/upload/vod/20240108-1/168e39d6110cb70e0f69b58b41a4ef7d.jpg', '<p>Khi cô gái Makoto Konno 17 tuổi nhận ra mình có khả năng nhảy vượt thời gian, cô đã dành điều kì diệu này để sửa lại thành tích học tập cũng như những tai nạn ngớ ngẩn cô hay gặp phải. Tuy nhiên cô dần nhận ra việc thay đổi quá khứ không hề đơn giản như vậy, và tương lai của cô và bạn bè mình phụ thuộc vào chính khả năng nguy hiểm này.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Riisa Naka","avatar":""},{"name":"Takuya Ishida","avatar":""},{"name":"Mitsutaka Itakura","avatar":""},{"name":"Ayami Kakiuchi","avatar":""},{"name":"Mitsuki Tanimura","avatar":""},{"name":"Yuki Sekido","avatar":""},{"name":"Utawaka Katsura","avatar":""},{"name":"Midori Ando","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Keiko Yamamoto","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
