INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-gai-vuot-thoi-gian-2006', 'Cô Gái Vượt Thời Gian', 'The Girl Who Leapt Through Time', 'cô gái vượt thời gian the girl who leapt through time riisa naka takuya ishida mitsutaka itakura ayami kakiuchi mitsuki tanimura yuki sekido utawaka katsura midori ando fumihiko tachiki keiko yamamoto ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-cua-quy-satan', 'Đứa Con Của Quỷ Satan', 'The Omen', 'https://phimimg.com/upload/vod/20231201-1/76bf3e451c9552f8e153924445cbc379.jpg', 'https://phimimg.com/upload/vod/20231201-1/8dcdd8569c5ad3be7f3154d263ee09c1.jpg', '<p>Katherine, vợ vị đại sứ Mỹ Robert Thorn vì khó sinh nên đứa bé đã chết ngay khi mới chào đời. Không muốn người vợ đau buồn sau hai lần xảy thai lại phải đối mặt với tin dữ, Robert được vị linh mục gợi ý việc đánh tráo đứa bé. Đứa trẻ được thay thế cũng sinh ra trong đêm hôm đó, nhưng mẹ đứa bé đã qua đời ngay khi nó vừa cất tiếng khóc đầu tiên. Đứa trẻ được hai vợ chồng đem về nuôi, đặt tên là Damien và xem nó như máu thịt. Katherine không hề biết sự thật. Robert biết nhưng ông lại không ngờ đến một điều kinh khủng hơn đang ẩn chứa trong thân xác cậu bé Damien...</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liev Schreiber","avatar":""},{"name":"Julia Stiles","avatar":""},{"name":"Seamus Davey-Fitzpatrick","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Pete Postlethwaite","avatar":""},{"name":"Mia Farrow","avatar":""},{"name":"Predrag Bjelac","avatar":""},{"name":"Carlo Sabatini","avatar":""},{"name":"Amy Huck","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Giovanni Lombardo Radice","avatar":""},{"name":"Harvey Stephens","avatar":""},{"name":"Tomas Wooler","avatar":""},{"name":"Baby Zikova","avatar":""},{"name":"Baby Morvas","avatar":""},{"name":"Baby Muller","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324523);
