INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('brave-story', 'Brave Story', 'Brave Story', 'https://phimimg.com/upload/vod/20231231-1/217cc8e3ccc229e7057385fb87ef4ad9.jpg', 'https://phimimg.com/upload/vod/20231231-1/de939236a3ca3dd91573e746b841e7f3.jpg', '<p>Học sinh trung học Jr. Wataru và những người bạn của mình thích chơi trong một tòa nhà bỏ hoang và tìm kiếm những con ma. Tuy nhiên có vẻ như anh không phải là người duy nhất. Một học sinh bí ẩn khác, Mitsuru, cho Wataru thấy rằng có một cánh cửa thần kỳ dẫn đến một thế giới khác, nơi người ta có thể đến và được Nữ thần May mắn ban cho một điều ước! Khi bi kịch ập đến với gia đình Wataru, anh quyết định mở cánh cửa cho chính mình.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takako Matsu","avatar":""},{"name":"Eiji Wentz","avatar":""},{"name":"Miki Imai","avatar":""},{"name":"Shirô Itô","avatar":""},{"name":"Ayako Kawasumi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
