INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-cua-3', 'Lưỡi Cưa 3', 'Saw III', 'https://phimimg.com/upload/vod/20231231-1/20c3222473524b82b47a895a2a89ecd8.jpg', 'https://phimimg.com/upload/vod/20231231-1/b67e32207f2c73f1b8bf846ca8115acb.jpg', '<p>Jeff là một người đàn ông đau khổ đau buồn và nhớ con trai mình bị giết bởi một tài xế say rượu trong một tai nạn xe hơi. Anh ta đã bị ám ảnh để trả thù người lái xe say rượu, thẩm phán và chỉ có nhân chứng từ chối làm chứng; Anh cũng đã trở nên bỏ bê con gái của mình. Lynn Denlon là một bác sĩ phẫu thuật lành nghề đang lừa dối chồng và bị trầm cảm. Cả hai đều bị bắt cóc và mang đến kho của Jigsaw, nơi họ phải chơi hai trò chơi riêng biệt: Jeff phải chọn có để cứu hoặc để những người mà anh ta chịu trách nhiệm về cái chết của con trai mình chết, trong khi Lynn phải giữ cho Jigsaw còn sống cho đến khi Jeff hoàn thành bài kiểm tra của mình, hoặc đối mặt với hậu quả chết người.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324523);
