INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-yen', 'Dạ Yến', 'The Banquet', 'https://phimimg.com/upload/vod/20231231-1/781d317804123f29d758955127c32041.jpg', 'https://phimimg.com/upload/vod/20231231-1/c59d30d30a6f15b5701331702be3813f.jpg', '<p>Dạ Yến - The Banquet là bộ phim được lấy vào năm 907 sau Công nguyên, thời điểm mà triều chính nhà Đường đang gặp những vấn đề nghiêm trọng, không chỉ đơn giản là đang bị rạn nứt mà là còn đấu ngầm giữa các thế lực tranh giành quyền lực tàn nhẫn đến ghê người. Thái tử Vô Loan yêu Uyển Nhi, nhưng cha của hoàng đế lấy cô làm hoàng hậu. Vô Loan từ đó phiêu du thiên hạ, học nhảy và âm nhạc, hòa mình vào thiên nhiên để quên đi sự đời. Biến cố bắt đầu xảy đến nơi hoàng cung khi mà người chú ruột của thái tử đã giết cha của cậu ta, cướp ngôi và lấy luôn Hoàng hậu, thậm chí là y còn gửi đi rất nhiều sát thủ để giết Vu Loan. Thái tử thoát chết nhưng bị bắt. Hoàng đế sắp đặt lễ đăng quang của Uyển Nhi và áp giải Vu Loan đến một vùng đất xa xôi, sau đó ông ta tổ chức một bữa tiệc lúc nửa đêm vào ngày thứ 100 kỉ niệm ông ta lên ngôi. Thuốc độc, sự phản bội, sự trở lại của Vô Loan và tình yêu vô tận của Thanh Nữ dành cho Vô Loan đã mở ra một khoảnh khắc quyết định...</p>', 'Full', 1, 'single', 'completed', 9, 2006, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Ngạn Tổ","avatar":""},{"name":"Châu Tấn","avatar":""},{"name":"Chương Tử Di","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
