INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-chet-choc', 'Kỳ Nghỉ Chết Chóc', 'Turistas', 'https://phimimg.com/upload/vod/20240102-1/3bcd74f7acba3d417fb83c8d8671d50e.jpg', 'https://phimimg.com/upload/vod/20240102-1/67dfe53c4faec04650733533c08a0882.jpg', '<p>Hai anh em Alex và Bea cùng người bạn thân Amy quyết định thực hiện một chuyến du lịch bằng đường bộ đến miền nam Brazil. Cùng đi với họ trên xe là những thanh niên ưa mạo hiểm mang nhiều quốc tịch khác nhau. Cuộc hành trình chỉ vừa bắt đầu thì bất trắc đã xảy đến. Chiếc xe buýt sau khi tránh một nhóm thiếu niên đã rơi thẳng xuống vực sâu, may mắn là toàn bộ hành khách đã kịp nhảy ra ngoài... Trong khoảng thời gian chờ đợi chuyến xe kế tiếp, Alex và các bạn bèn tìm đến một quán bar nằm cạnh biển để vui chơi. Cuộc vui từng bừng khiến họ không còn muốn đón xe buýt nữa. Cả nhóm quyết định sẽ ở lại bãi biển một đêm. Sáng hôm sau, khi tỉnh dậy, cả nhóm phát hiện tất cả hành lý và giấy tờ của họ đã bị cướp sạch. Họ xô xát với những người địa phương và cuối cùng được một người bạn Brazil là Kiko đứng ra giúp đỡ. Kiko khuyên họ nên đi vào rừng, nơi Kiko có một ngôi nhà có thể làm nơi dừng chân an toàn cho cả nhóm. Nhưng ngôi nhà an toàn đó hoàn toàn không tồn tại. Nhóm bạn trẻ đang tự mình bước thẳng đến địa ngục mà chẳng hề hay biết gì.</p>', 'Full', 1, 'single', 'completed', 9, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Duhamel","avatar":""},{"name":"Melissa George","avatar":""},{"name":"Olivia Wilde","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
