INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-vinh-quang', 'Con Đường Vinh Quang', 'Glory Road', 'https://phimimg.com/upload/vod/20240102-1/a590702ac5f4c030f77eda06ca15fe9b.jpg', 'https://phimimg.com/upload/vod/20240102-1/10af484f3e8245aeaf2ff60872206195.jpg', '<p>Năm 1966, huấn luyện viên Don Haskins của Texas Western dẫn đầu đội hình xuất phát toàn đen đầu tiên cho một đội bóng rổ đại học đến chức vô địch quốc gia NCAA.</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Lucas","avatar":""},{"name":"Derek Luke","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Austin Nichols","avatar":""},{"name":"Evan Jones","avatar":""}]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
