INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-moi', 'Người Mới', 'Something New', 'https://phimimg.com/upload/vod/20240102-1/2c65780658c0d78c8bf80f53aec1fa6b.jpg', 'https://phimimg.com/upload/vod/20240102-1/4b1e4b8516db89c32a26a3378054efd8.jpg', '<p>Có đời sống cá nhân trắc trở, kế toán viên người da đen Kenya đành đồng ý đến buổi hẹn sắp đặt với một kiến trúc sư quyến rũ. Nhưng anh tình cờ lại là người da trắng.</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sanaa Lathan","avatar":""},{"name":"Simon Baker","avatar":""},{"name":"Mike Epps","avatar":""},{"name":"Donald Faison","avatar":""},{"name":"Blair Underwood","avatar":""},{"name":"Wendy Raquel Robinson","avatar":""},{"name":"Alfre Woodard","avatar":""},{"name":"Golden Brooks","avatar":""},{"name":"Taraji P. Henson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
