INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-goi-luc-nua-dem', 'Cuộc Gọi Lúc Nửa Đêm', 'When A Stranger Calls', 'https://phimimg.com/upload/vod/20231231-1/ee0756d5c567fe13f572febb26850f6a.jpg', 'https://phimimg.com/upload/vod/20231231-1/97b95b39eb8278ba7e1c852d067692a0.jpg', '<p>Jill Johnson làm công việc giữ trẻ ca đêm cho một gia đình giàu có sống trên ngọn đồi vắng vẻ. Trong lúc bọn trẻ ngủ say, Jill bắt đầu khám phá ngôi nhà rộng lớn và hiện đại. Nhưng rồi một kẻ bí ẩn liên tục gọi điện thoại đến quấy rối cô. Được bảo vệ bởi hệ thống an ninh tối tân, nhưng liệu Jill có thực sự an toàn trong ngôi nhà đó không?</p>', 'Full', 1, 'single', 'completed', 8, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Camilla Belle","avatar":""},{"name":"Tommy Flanagan","avatar":""},{"name":"Tessa Thompson","avatar":""},{"name":"Katie Cassidy","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324523);
