INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-quan-luc-chien', 'Thủy Quân Lục Chiến', 'The Marine', 'https://phimimg.com/upload/vod/20231231-1/239540f76fd54fda11851cbdf338fa3e.jpg', 'https://phimimg.com/upload/vod/20231231-1/5277f371cb018f323dba660b85b3c154.jpg', '<p>Một nhóm trộm kim cương đang chạy trốn đã bắt cóc vợ của một lính thủy đánh bộ mới giải ngũ, người này đang đuổi theo vùng hoang dã Nam Carolinian để lấy lại cô ấy.</p>', 'Full', 1, 'single', 'completed', 8, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cena","avatar":""},{"name":"Kelly Carlson","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Abigail Bianca","avatar":""},{"name":"Christina Lindley","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
