INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('stay-alive', 'Stay Alive', 'Stay Alive', 'https://phimimg.com/upload/vod/20231231-1/807805f8e8f297c3ed119489a98113ad.jpg', 'https://phimimg.com/upload/vod/20231231-1/7fca83e1f827f49e6acfb1ba6057e703.jpg', '<p>Sau cái chết bí ẩn, tàn bạo của một người bạn cũ, một nhóm thanh thiếu niên thấy mình đang sở hữu Stay Alive, một trò chơi điện tử 3-D cực kỳ chân thực dựa trên câu chuyện có thật rùng rợn về một nữ quý tộc thế kỷ 17, được gọi là &nbsp;Nữ Bá tước Máu. Các game thủ không biết gì về trò chơi ngoài việc họ không được phép có nó... và họ rất muốn chơi nó. Không thể cưỡng lại sự cám dỗ, những đứa trẻ bắt đầu chơi trò chơi rùng rợn nhưng nhanh chóng tạo ra một mối liên hệ ớn lạnh -- chúng đang bị sát hại từng người một theo cách giống như các nhân vật mà chúng đã chơi trong trò chơi. Khi ranh giới giữa thế giới trò chơi và thế giới thực biến mất, các thiếu niên phải tìm cách đánh bại Nữ bá tước máu độc ác và tàn nhẫn, trong khi cố gắng ... sống sót.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Samaire Armstrong","avatar":""},{"name":"Frankie Muniz","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Jon Foster","avatar":""},{"name":"Wendell Pierce","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
