INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-dep-ngan-can-2006', 'Sắc Đẹp Ngàn Cân', '200 Pounds Beauty', 'https://phimimg.com/upload/vod/20230930-1/10569c780ff6d365a0da150c001f96c6.jpg', 'https://phimimg.com/upload/vod/20230930-1/d2bcef7fc409c50ab5f95309b2222de2.jpg', '<p>Hanna hát thế cho một ca sĩ nhạc pop nổi tiếng tên Ami, chỉ vì cô có một thân hình quá khổ mà không thể nào trở thành ca sĩ chính thức được. Cho đến một ngày khi Ami làm bẽ mặt Hanna trước Sang Jun, người Hanna yêu thầm, thì cô quyết tâm phẫu thuật, giảm cân, để lấy lại những thứ đáng ra thuộc về mình mình.</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ju Jin-mo","avatar":""},{"name":"Kim A-joong","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Kim Hyun-sook","avatar":""},{"name":"Im Hyun-sik","avatar":""},{"name":"Lee Han-wi","avatar":""},{"name":"Ji Seo-Yun","avatar":""},{"name":"Park No-shik","avatar":""},{"name":"Kim Myeong-Kyu","avatar":""},{"name":"Venny","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324523);
