INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-chi-huyen-bi', 'Sợi Chỉ Huyền Bí', 'Silk', 'https://phimimg.com/upload/vod/20231230-1/04b16e20f7f6cbd48b4e8c8021dfec52.jpg', 'https://phimimg.com/upload/vod/20231230-1/0c31a6fcbbfc4fb7cd4c9a3e8f621299.jpg', '<p>Ở Đài Bắc, một nhóm thợ săn ma trả tiền cho một người làm nghề máy ảnh tự do để chụp ảnh những nơi đang tìm kiếm hoạt động huyền bí. Từ những âm thanh của sự vật, những nỗ lực trước đó đã không thành công. Người cầm máy đang chụp ảnh và lần này chụp được hình ảnh một cậu bé trong một căn phòng dường như trống trải. Nhóm thợ săn ma rất hồi hộp và tự mình điều tra thêm. Họ mang theo một sĩ quan cảnh sát, một tay súng sắc bén và một đầu đọc môi để được trợ giúp thêm trong quá trình điều tra nhằm nghiên cứu thêm về Ghost. Cán bộ có mẹ bị bệnh hôn mê, cơ thể đang phân hủy. Mặc dù viên cảnh sát từ chối đề nghị giúp đỡ trong giai đoạn đầu, anh ta chấp nhận vụ việc do tò mò. Mặt khác, giám đốc của toàn bộ chương trình này kêu gọi nhóm từ bỏ nghiên cứu của họ vì nó có vẻ vô giá trị và gây tốn kém cho chính phủ Nhật Bản. Nhóm nghiên cứu tiết lộ một khối lập phương từ tính có thể tự phân chia và thu nhận năng lượng ở mọi dạng. Khả năng giữ năng lượng của nó đến mức nó có thể chịu được lực của trọng lực và lơ lửng trong không khí. Giám đốc rõ ràng đồng ý đề nghị hỗ trợ thêm. Nó được tiết lộ thêm rằng các bức tường của căn phòng của con ma bị bắt được đóng bằng hàng ngàn khối như vậy để cản trở sự di chuyển của cậu bé ma.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Thuyết Minh', 'HD', 'Đài Loan', 0, '[{"name":"Yôsuke Eguchi","avatar":""},{"name":"Chang Chen","avatar":""},{"name":"Karena Lam","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
