INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-va-cho-san-2', 'Cáo Và Chó Săn 2', 'The Fox And The Hound 2', 'https://phimimg.com/upload/vod/20231230-1/d04e3222b4725dbd76baea174ffd24e2.jpg', 'https://phimimg.com/upload/vod/20231230-1/d657c6f41369c98b92868b991e36df7c.jpg', '<p>Kết thúc của Disney: Bất chấp câu chuyện về một tình bạn bất thường và những trở ngại tưởng như không thể vượt qua được, Disney vẫn bằng cách này hay cách khác vẫn tìm được một kết thúc có hậu cho The Fox and the Hound. Câu chuyện kết thúc khi chú chó săn Copper bảo vệ người bạn ấu thơ của mình, cáo Todd, khỏi chính người chủ của mình. Todd sau đó sống hạnh phúc cùng một cô cáo còn Copper tiếp tục với cuộc sống của một chú chó săn bình thường.Kết thúc thực sự: Daniel P. Mannix, tác giả của câu chuyện gốc, có lẽ chưa từng được gặp bất cứ một đứa trẻ nào trước khi viết The Fox and the Hound. Trong phiên bản này, Copper trở thành một con chó săn khát máu săn lùng cáo Todd để trả thù cho một chú chó săn khác đã chết trong ...</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Reba McEntire","avatar":""},{"name":"Patrick Swayze","avatar":""},{"name":"Jonah Bobo","avatar":""},{"name":"Harrison Fahn","avatar":""},{"name":"Jeff Foxworthy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324523);
