INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-chu-cho-dung-cam', 'Những Chú Chó Dũng Cảm', 'Eight Below', 'https://phimimg.com/upload/vod/20231230-1/da2ffd25bc49f95ba36b5f1f5a540ab9.jpg', 'https://phimimg.com/upload/vod/20231230-1/63e93dc4270336f0a3e4c90dc8ffc0e8.jpg', '<p>Phim kể về ba người thành viên của một nhóm thám hiểm đã bị buộc phải bỏ lại đàn chó kéo xe trượt của mình bởi vì tai nạn và thời tiết nguy hiểm. Trong mùa đông lạnh giá của vùng Nam Cực tàn nhẫn đó, đàn chó đã phải tự đấu tranh sinh tồn tìm cách sống sót trong suốt 6 tháng trời.</p>', 'Full', 1, 'single', 'completed', 9, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Walker","avatar":""},{"name":"Jason Biggs","avatar":""},{"name":"Bruce Greenwood","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324523);
