INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('asterix-va-cuop-bien-vikings', 'Asterix Và Cướp Biển Vikings', 'Astérix Et Les Vikings', 'https://phimimg.com/upload/vod/20231227-1/2022f338b9cecc3010adb2d06e13e002.jpg', 'https://phimimg.com/upload/vod/20231227-1/9a3db60ac72a8c843519f1b2663836bf.jpg', '<p>Asterix và Obelix được giao một nhiệm vụ khó khăn: Biến cháu trai lười biếng của tù trưởng Justforkix thành một chiến binh. Khi những người Viking bắt cóc anh ta và đưa anh ta trở về quê hương của họ, Asterix và Obelix phải đến Na Uy để giải cứu Justforkix.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2006, 'Thuyết Minh', 'HD', 'Pháp', 0, '[{"name":"Roger Carel","avatar":""},{"name":"Lorànt Deutsch","avatar":""},{"name":"Sara Forestier","avatar":""},{"name":"Jacques Frantz","avatar":""},{"name":"Stéphane Fourreau","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324523);
