INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-meo-sieu-quay-2', 'Chú Mèo Siêu Quậy 2', 'Garfield: A Tail Of Two Kitties', 'https://phimimg.com/upload/vod/20231215-1/7fe5f26b5e6fe529c91e5a37da11cb38.jpg', 'https://phimimg.com/upload/vod/20231215-1/7c5320b5b014f207386b84be0070ef84.jpg', '<p>Garfield (Bill Murray) đã trở lại và lần này anh ta và con chó Sidekick Odie của mình theo chủ sở hữu của họ, Jon Arbuckle (Breckin Meyer), đến Anh, Vương quốc Anh có thể không bao giờ hồi phục, khi Garfield bị nhầm là một con mèo giống như nhau, Regal Cat có thừa hưởng một lâu đài. Garfield Savors the Royal Treatment có đủ khả năng bởi các đối tượng bốn chân trung thành của mình, nhưng triều đại của anh ta đang gặp nguy hiểm. Lạy lễ bướng bỉnh bất tử ác Dargis (Sir Billy Connolly) quyết tâm để tránh xa Garfield, để anh ta có thể biến lâu đài thành một khu nghỉ mát. Thế giới lớn hơn của Garfield, tốt hơn, hoàn hảo hơn sẽ sớm bị đảo lộn trong câu chuyện của hai chú mèo con này.</p>', 'Full', 1, 'single', 'completed', 8, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324523);
