INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hieu-ung-canh-buom-2', 'Hiệu Ứng Cánh Bướm 2', 'The Butterfly Effect 2', 'https://phimimg.com/upload/vod/20231215-1/3d54671f956376f4b323ffd89870475f.jpg', 'https://phimimg.com/upload/vod/20231215-1/70dbb43344eb89667a3e51402860c45a.jpg', '<p>Sau khi bạn gái của anh, Julie, và hai người bạn thân nhất thiệt mạng trong một vụ tai nạn ô tô thảm khốc, Nick phải vật lộn để đương đầu với sự mất mát và đau buồn của mình. Bị chứng đau nửa đầu, Nick sớm phát hiện ra rằng anh có khả năng thay đổi quá khứ thông qua ký ức của mình. Tuy nhiên, những nỗ lực du hành thời gian của anh ấy để thay đổi quá khứ và cứu lấy một tình yêu đích thực của mình đã gây ra những hậu quả bất ngờ và thảm khốc.</p>', 'Full', 1, 'single', 'completed', 8, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eric Lively","avatar":""},{"name":"Erica Durance","avatar":""},{"name":"Dustin Milligan","avatar":""},{"name":"Gina Holden","avatar":""},{"name":"Susan Hogan","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
