INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-do-ma-ca-rong', 'Cám Dỗ Ma Cà Rồng', 'The Insatiable', 'https://phimimg.com/upload/vod/20231212-1/fdc3c53b31ceb8c859b19263902b6d52.jpg', 'https://phimimg.com/upload/vod/20231212-1/1fbe7fd859af5f67cc03bab81e874d51.jpg', '<p>Cám Dỗ Ma Cà Rồng - The Insatiable kể về một anh chàng quê mùa chứng kiến cảnh một nữ ma cà rồng ăn thịt một gã ăn mày và trở nên say mê cô. Sau đó, anh ta theo dõi cô gái ma cà rồng này và nhốt cô trong một tầng hầm để không thể giết người một lần nữa.</p>', 'Full', 1, 'single', 'completed', 8, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Biehn","avatar":""},{"name":"Sean Patrick Flanery","avatar":""},{"name":"Charlotte Ayanna","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324523);
