INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-hau-nhi', 'Hoa Hậu Nhí', 'Little Miss Sunshine', 'https://phimimg.com/upload/vod/20231211-1/c29e014032edac102a80b399f4c459d4.jpg', 'https://phimimg.com/upload/vod/20231211-1/5f14dfcb1df071e050e7965c49104d64.jpg', '<p>Để chiều lòng cô con gái nhỏ 7 tuổi Olive, cả gia đình Hoover cùng nhau khăn gói lên đường từ Albuquerque đi đến Redondo Beach, California để Olive tham dự cuộc thi sắc đẹp dành cho các bé gái. Trên đường đi cả gia đình đã trải qua mọi chuyện vui buồn, khó khăn lẫn hạnh phúc để rồi nhận ra giá trị tốt đẹp khi có người thân bên cạnh cuộc đời.</p>', 'Full', 1, 'single', 'completed', 8, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Carell","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Greg Kinnear","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324523);
