INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-vien-thoi-a', 'Sinh Viên Thời @', 'Accepted', 'https://phimimg.com/upload/vod/20231211-1/5bb16447ace8bc67bfb5094c6a0bc751.jpg', 'https://phimimg.com/upload/vod/20231211-1/2ada4f3fd83685168ed9fd5b6307d48c.jpg', '<p>Bạn nghĩ thế nào khi gặp một trường đại học mà chỉ cần click chuột là được chấp nhận trở thành sinh viên? Học viện kỹ thuật South Harmon là một ví dụ. Ở đó không có lớp học hay giảng viên mà là thế giới của cảm xúc, đam mê sáng tạo và tự do tuổi trẻ. Lần lượt nhận 8 giấy báo trượt của 8 trường đại học, Bartleby Gains phải nghĩ ra kế sách để trấn an cha mẹ. Anh cùng nhóm bạn trung học đã nghĩ ra việc dọn dẹp một bệnh viện tâm thần bỏ hoang thành một trường học, lập trang web hoàn chỉnh để hợp thức hóa việc đi học của mình. Ngôi trường ma có tên gọi là Học Viện Kỹ Thuật South Harmon...</p>', 'Full', 1, 'single', 'completed', 8, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Justin Long","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Blake Lively","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
