INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-danh-vong', 'Giấc Mơ Danh Vọng', 'Dreamgirls', 'https://phimimg.com/upload/vod/20231211-1/46fd45747dc5549b2097ee3b643d41c5.jpg', 'https://phimimg.com/upload/vod/20231211-1/2b1e634597cf19c221a5996aa339830d.jpg', '<p>Ba cô gái trẻ mơ ước trở thành ngôi sao nhạc pop — và đạt được ước nguyện khi họ được chọn trở thành ca sĩ dự bị cho James Thunder Early huyền thoại.</p>', 'Full', 1, 'single', 'completed', 9, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jamie Foxx","avatar":""},{"name":"Beyoncé","avatar":""},{"name":"Eddie Murphy","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Jennifer Hudson","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
