INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-so-may-man', 'Con Số May Mắn', 'Lucky Number Slevin', 'https://phimimg.com/upload/vod/20231211-1/1bad5452ddb55ae2b5d28c3d7f965575.jpg', 'https://phimimg.com/upload/vod/20231211-1/42b34b36e5d10f2e9add51b48cc2e9e4.jpg', '<p>Thuộc thể loại Hành Động Phiêu Lưu đan xen với nhiều tình tiết siêu nhiên, nội dung của phim Con Số May Mắn bắt đầu từ một phòng chờ ở sân bay, khi mà một người đàn ông ngồi trên xe lăn nói với một người lạ một câu chuyện về một cuộc đua ngựa cố định vào năm 1979 dẫn đến cái chết của một gia đình. Tại Manhattan, hai tên trộm và con trai của một ông chủ Mob đã bị chết. Một thanh niên chỉ mới ra khỏi phòng tắm đã đứng trả lời ngay tại cánh cửa cho một người phụ nữ hàng xóm và giải thích rằng anh ta đang thăm viếng, anh đã có một tuần tồi tệ, kể cả việc đã bị bắt cóc, và không biết bạn của anh ta ở đâu.</p>', 'Full', 1, 'single', 'completed', 9, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Hartnett","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Morgan Freeman","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
