INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-ve-si-dac-nhiem', 'Nữ Vệ Sĩ Đặc Nhiệm', 'Air Force 2', 'https://phimimg.com/upload/vod/20240104-1/caea6006eb9fb8153efeacce1a6e0f7d.jpg', 'https://phimimg.com/upload/vod/20240104-1/19244b34ef593a691ebc6b9272b51407.jpg', '<p>Nữ Vệ Sĩ Đặc Nhiệm - Air Force 2 kể về cuộc giải cứu Phó Tổng thống đầy hồi hộp và căng thẳng. Khi máy bay của Phó Tổng thống rơi xuống một hòn đảo xa xôi ở Thái Bình Dương, ông bị lực lượng nổi dậy bắt cóc và đòi tiền chuộc. Liệu nữ nhân viên mật vụ và thư ký báo chí của ông có thể thâm nhập vào hang ổ của bọn bắt cóc và cứu ông ta hay không?</p>', 'Full', 1, 'single', 'completed', 6, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Keith","avatar":""},{"name":"David Millbern","avatar":""},{"name":"Mariel Hemingway","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324523);
