INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-so-den', 'Cuốn Sổ Đen', 'Black Book', 'https://phimimg.com/upload/vod/20231211-1/d66f9737eb2f009a5c5fec5696911b35.jpg', 'https://phimimg.com/upload/vod/20231211-1/a37a56db2234a04de3789a9cbb2be237.jpg', '<p>Năm 1944, khi Đức quốc xã thực hiện chiến dịch diệt trừ Do Thái, những người Do Thái vô tội đã tìm đường đưa gia đình mình đến lánh nạn tại những vùng chưa bị quân đội Đức chiếm giữ, trong số đó có Rachel Steinn và người nhà của cô. Thế nhưng khi Rachel và mọi người đều tưởng rằng mình sắp đến nơi an toàn thì đoàn tàu lại bị tấn công. Những kẻ phản bội đã thông báo cuộc chạy trốn cho Đức quốc xã, mục đích là cướp đi toàn bộ tài sản của những người Do Thái đi trên tàu.Rachel may mắn sống sót. Cô lập tức gia nhập phong trào kháng chiến và đổi tên thành Ellis. Nhiệm vụ mà cô được giao hết sức phức tạp: dùng giọng hát và cơ thể kiều diễm của mình để đưa nhân viên mật vụ Ludwig Muntze lên giường, trà trộn ...</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Carice van Houten","avatar":""},{"name":"Sebastian Koch","avatar":""},{"name":"Thom Hoffman","avatar":""},{"name":"Halina Reijn","avatar":""},{"name":"Waldemar Kobus","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
