INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-hai-tac-ten-linh-may-khong-lo-trong-lau-dai-karakuri', 'Vua Hải Tặc: Tên Lính Máy Khổng Lồ Trong Lâu Đài Karakuri', 'One Piece The Movie Karakuri Jou No Meka Kyohei (Movie 7)', 'https://phimimg.com/upload/vod/20231210-1/c2fde95c1c85eb26eaab1da1c0acb6fc.jpg', 'https://phimimg.com/upload/vod/20231210-1/f95b6251caa2f185a8181883f92f2a91.jpg', '<p>Vua Hải Tặc: Tên lính máy khổng lồ trong lâu đài Karakuri là movie thứ 7 trong loạt anime và manga của One Piece. Phim diễn ra trước các sự kiện trong Water 7 Arc, và được phát hành vào ngày 4 tháng 3 năm 2016. Movie thứ 7 bắt dầu diễn ra trong 1 cơn bão dữ dội, khi đó băng Mũ Rơm đã kiếm được 1 chiếc rương từ 1 con tàu đắm cũ. Chiếc rương được mở ra và ở trong đó chỉ có 1 bà lão. Để trả ơn, bà ta tiết lộ cho nhóm Mũ Rơm về chiếc vương miện bằng vàng ở đảo Mecha. Khi Luffy và đồng đội lên đảo thì phải chiến đấu chống lại Ratchet – chủ nhân của hòn đảo này. Và tại đây Luffy lần đầu tiên kích hoạt được Gear Second. Bí ẩn về chiếc vương miện vàng cũng từ từ được tiết lộ.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
