INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('day-watch', 'Day Watch', 'Day Watch', 'https://phimimg.com/upload/vod/20231230-1/5cea4d03bb95305ff7d546e6ec290cd0.jpg', 'https://phimimg.com/upload/vod/20231230-1/966c9e9ceb0537684002147c94c05cbd.jpg', '<p>Một người đàn ông phục vụ trong cuộc chiến giữa các thế lực Ánh sáng và Bóng tối sở hữu một thiết bị có thể khôi phục sự sống cho Moscow, nơi gần như đã bị phá hủy bởi một sự kiện tận thế.</p>', 'Full', 1, 'single', 'completed', 16, 2006, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Konstantin Khabenskiy","avatar":""},{"name":"Mariya Poroshina","avatar":""},{"name":"Vladimir Menshov","avatar":""},{"name":"Galina Tyunina","avatar":""},{"name":"Zhanna Friske","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324523);
