INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('day-watch', 'Day Watch', 'Day Watch', 'day watch day watch konstantin khabenskiy mariya poroshina vladimir menshov galina tyunina zhanna friske ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giong-noi-nhan-loai', 'Giống Nòi Nhân Loại', 'Children Of Men', 'https://phimimg.com/upload/vod/20231211-1/ae097a0cc511707d408574546486e4a7.jpg', 'https://phimimg.com/upload/vod/20231211-1/30dedeace3839d30f43ed84ffebe7741.jpg', '<p>London, 2027. Trong thế giới dystopia này, con người đã không có khả năng sinh sản trong mười tám năm vì một lý do không xác định, có nghĩa là sự tuyệt chủng sắp xảy ra của loài. Anh là một xã hội văn minh còn lại trên hành tinh, nơi đã dẫn đến những người muốn nhập cư ở đó. Như vậy, nó đã trở thành một nhà nước cảnh sát để xử lý những người nhập cư, những người được đưa vào các trại tị nạn. Bà aron chính phủ thấp, một khi một nhà hoạt động, được các loài cá tiếp cận, được coi là một nhóm khủng bố, được dẫn dắt bởi người vợ cũ Julian Taylor, người mà anh ta đã không nhìn thấy gần hai mươi năm, cuộc hôn nhân của họ tan rã sau cái chết của họ Con trai sơ sinh Dylan trong đại dịch cúm 2008. Mặc dù các loài cá đã sử dụng khủng bố có nghĩa là trong cuộc cách mạng đang diễn ra trong cuộc chiến trong cuộc chiến cho các quyền nhập cư, Julian thề rằng bây giờ họ sẽ hỗ trợ chỉ bằng cách nói chuyện với người dân. Những gì cô ấy muốn là để theo cách sử dụng các kết nối của mình để có được giấy tờ quá cảnh cho một phụ nữ nhập cư trẻ tên là Kee Cần đến bờ biển. Mặc dù ban đầu không muốn làm điều đó vì khó khăn, Theo có thể cấp cho Julian, tuy nhiên, điều này với sự thay đổi mà bây giờ anh ta cần phải đi cùng Kee trên hành trình của mình. Khi Theo và Kee tiến bộ trên hành trình đó, Theo học nhiều hơn về những gì đang xảy ra, bao gồm lý do KEE cần phải đến bờ biển, thực tế là không có ai trong nhóm biết nếu điểm đến cuối của họ thậm chí còn tồn tại và đó Và cuộc sống của Kee có mối nguy hiểm lớn hơn anh ta tin rằng khi họ bắt đầu cuộc hành trình. Nhưng nhiệm vụ duy nhất của Theo sẽ giúp KEE có bất kỳ chi phí nào cho sự sống còn của loài</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324523);
