INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-cuop-xinh-dep', 'Băng Cướp Xinh Đẹp', 'Bandidas', 'https://phimimg.com/upload/vod/20231211-1/6f25b457d43e09984593d545b1c490fc.jpg', 'https://phimimg.com/upload/vod/20231211-1/2465832fe8e2b799e7fc0666b3b6913f.jpg', '<p>Hai cô gái bị đẩy vào cảnh bần cùng khi ruộng đất của họ bị một trùm tài phiệt dùng vũ lực cướp đoạt. Không còn gì để hy vọng, họ buộc phải đi cướp các ngân hàng của tay trùm để giúp đỡ những người cùng cảnh ngộ và đòi lại công lý cho gia đình.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Penélope Cruz","avatar":""},{"name":"Salma Hayek","avatar":""},{"name":"Steve Zahn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324523);
