INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-giang-ho', 'Gái Giang Hồ', 'Tazza: The High Rollers', 'https://phimimg.com/upload/vod/20231209-1/f491b94d8dfd85dd82c9ac0a0d2023de.jpg', 'https://phimimg.com/upload/vod/20231209-1/09c264c8a6365754ac9c8250eaa07f0a.jpg', '<p>Gái Giang Hồ - The High Rollers là bộ phim hình sự tội phạm, hài Hàn Quốc 2006 của đạo diễn Dong-Hoon Choi. Bộ phim mô tả một cuộc sống của những kẻ nghiện cờ bạc, sống chết với cờ bạc, trong đó có Go-ni (do Seung-woo Cho thủ vai). Sau nhiều lần bại trận, tài sản của anh biến mất. Quyết tâm không thể từ bỏ, anh muốn theo học những tay chơi bài khét tếng. Quá may mắn cho anh khi gặp được Pyeong, một bậc đại cao thủ trong giới cờ bạc nhưng nay đã lui về ở ẩn. Nhận tấy nơi Go-ni tố chất của một thần bài, ông Pyeong đã thu nạp a làm đệ tử để chỉ dạy thành một tay chơi bài chuyên nghiệp. Do được truền lại tất cả các bí kiếp của Pyeong, Go-in giờ đây đánh đâu thắng đó. Số phận đưa anh đến gặp một “nữ quái” có thể lột sạch tiền của những kẻ mới chập chững bước vào sòng bạc chỉ trong chớp mắt tại Bussan. Và rồi diễn biến tiếp theo sẽ như thế nào? Ai thắng, ai thua? Cuộc đời của đôi trai gái chỉ dừng lại ở những ván bài thôi ư?</p>', 'Full', 1, 'single', 'completed', 8, 2006, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Seung-woo Cho","avatar":""},{"name":"Yun-shik Baek","avatar":""},{"name":"Hye-su Kim","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324523);
