INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('violet-sieu-dang', 'Violet Siêu Đẳng', 'Ultraviolet', 'https://phimimg.com/upload/vod/20231209-1/64af99b81161ef0378b87a3f4963b0e9.jpg', 'https://phimimg.com/upload/vod/20231209-1/b5bda4c2afe1db96e34eda78699714c5.jpg', '<p>Căn bệnh có đặc điểm như của ma cà rồng bắt đầu lây lan trong cộng đồng, mang lại cho người bị nhiễm trí thông minh cao, sức chịu đựng tuyệt vời và tốc độ nhanh như chớp.</p>', 'Full', 1, 'single', 'completed', 8, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"Cameron Bright","avatar":""},{"name":"Nick Chinlund","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324523);
