INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiet-huyet-bong-bau-duc', 'Nhiệt Huyết Bóng Bầu Dục', 'Gridiron Gang', 'https://phimimg.com/upload/vod/20231209-1/779525d0c89282b2e0abe2783ea51e5b.jpg', 'https://phimimg.com/upload/vod/20231209-1/90e165c4c0ed994c0165f446c02346da.jpg', '<p>Trong bộ phim chính kịch cảm động này, một nhân viên quản chế tại trại giam thanh thiếu niên hi vọng có thể rèn giũa những tội nhân ấy thành một đội bóng bầu dục cừ khôi.</p>', 'Full', 1, 'single', 'completed', 16, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Xzibit","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Leon Rippy","avatar":""},{"name":"Jade Yorker","avatar":""},{"name":"Setu Taase","avatar":""},{"name":"L. Scott Caldwell","avatar":""},{"name":"David V. Thomas","avatar":""},{"name":"Brandon Mychal Smith","avatar":""},{"name":"Jamal Mixon","avatar":""}]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
