INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-hang-xom-chet-tiet', 'Gã Hàng Xóm Chết Tiệt', 'Deck The Halls', 'https://phimimg.com/upload/vod/20231208-1/a65365705d9747c8b07d5fc5c2bbec0b.jpg', 'https://phimimg.com/upload/vod/20231208-1/bd9fa25ddd5b728e4aac15ff6cfa6475.jpg', '<p>Gã Hàng Xóm Chết Tiệt - Deck The Halls xoay quanh cuộc sống của gia đình Steve Finch (Matthew Broderick). Steve Finch vẫn luôn là ông vua của ngày lễ Giáng sinh về khoản trang trí nổi bật nhà cửa. Mải mê với những ý tưởng về một kỳ nghỉ đáng nhớ, Steve không hề để ý đến chuyện cô con gái Madison thực sự đã lớn, và cậu con trai 10 tuổi Carter chỉ mong muốn được đi mua đồ Giáng sinh với bố. Đến một ngày, Buddy Hall cùng gia đình đến và trở thành hàng xóm mới của nhà Steve. Không chịu thua kém, Buddy quyết định sẽ phủ lên nhà cả tấn đèn trang trí nhấp nháy. Steve vô cùng lo lắng. Một cuộc chiến tranh không khoan nhượng bắt đầu giữa hai anh hàng xóm.</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kristin Chenowith","avatar":""},{"name":"Kristin Davis","avatar":""},{"name":"Danny DeVito","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
