INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nong-trai-vui-nhon', 'Nông Trại Vui Nhộn', 'Barnyard', 'https://phimimg.com/upload/vod/20231210-1/601522d1f502e93ecfcc568442e8fd91.jpg', 'https://phimimg.com/upload/vod/20231210-1/a6f690652e545b634cc0a8e3f35f499e.jpg', '<p>Bộ phim mở đầu bằng cảnh chú bò Otis (Kevin James) trượt tuyết trên một quả đồi cùng với 4 con vật khác: gà trống không biết gáy Peck (Rob Paulsen), chuột Pip (Jeff Garcia), lợn Pig (Tino Insana) háu đói, chồn sương Freddy (Cam Clarke) - kẻ thường xuyên phải chống lại ham muốn ăn thịt gà Peck và các con gia cầm khác. Cuộc vui kéo dài chưa được bao lâu thì Otis sực nhớ ra là chú cùng các bạn phải trở về trang trại để tham dự một cuộc họp quan trọng...</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin James","avatar":""},{"name":"Courteney Cox","avatar":""},{"name":"Danny Glover","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324523);
