INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-vua-cuoi-cung-cua-scotland', 'Vị Vua Cuối Cùng Của Scotland', 'The Last King Of Scotland', 'https://phimimg.com/upload/vod/20231208-1/ff86933bce894476461f5d074cb91c82.jpg', 'https://phimimg.com/upload/vod/20231208-1/951245ec3eaaca6be540843e5aa6c63f.jpg', '<p>Bác sĩ trẻ người Scotland, Nicholas Garrigan quyết định đã đến lúc cho một cuộc phiêu lưu sau khi anh ta hoàn thành chương trình giáo dục chính thức, vì vậy anh ta quyết định thử vận may của mình ở Uganda, và đến khi Tổng thống Obote sụp đổ. Tướng Idi Amin lên nắm quyền và yêu cầu Garrigan trở thành bác sĩ riêng của mình.</p>', 'Full', 1, 'single', 'completed', 9, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Forest Whitaker","avatar":""},{"name":"James McAvoy","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Gillian Anderson","avatar":""},{"name":"Kerry Washington","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
