INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bat-tu-suoi-nguon', 'Người Bất Tử (Suối Nguồn)', 'The Fountain', 'https://phimimg.com/upload/vod/20231209-1/9748292ce9a2081c8e1b10fe478fd2cb.jpg', 'https://phimimg.com/upload/vod/20231209-1/1a1a9b3d46cda1b40308aa0871ef3c09.jpg', '<p>Hoàn cảnh gia đình của Tom - tiến sỹ thần kinh đứng đầu một viện nghiên cứu thật bi đát: bố mất vì bệnh nan y, nay cuộc sống của vợ anh cũng đang đếm từng ngày vì chính căn bệnh đó. Để cứu sống vợ, anh chỉ đạo các nhà khoa học dùng khỉ làm vật thí nghiệm chế tạo một loại thuốc trường sinh bất tử. Anh quyết bằng mọi giá thực hiện điều đó, cho đến khi anh ngộ ra bản chất của sự bất tử ...</p>', 'Full', 1, 'single', 'completed', 9, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Ellen Burstyn","avatar":""},{"name":"Mark Margolis","avatar":""},{"name":"Stephen McHattie","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
