INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hong-sung-tu-than', 'Họng Súng Tử Thần', 'Running Scared', 'https://phimimg.com/upload/vod/20231209-1/c4f879d4a18f166392577b82fbfb3add.jpg', 'https://phimimg.com/upload/vod/20231209-1/1cf48f5a235d486e1b8745a94859fd66.jpg', '<p>Joey vốn là một tay xã hội đen cấp thấp chuyên đảm nhiệm việc thủ tiêu các khẩu súng các ông trùm đã dùng trong các vụ thanh toán. Trong một vụ đụng độ giữa ông trùm của Joey và cảnh sát, khẩu súng mà Joey có nhiệm vụ phải tiêu hủy lại lọt vào tay một cậu nhóc 10t vốn là bạn thân của con trai anh. Cậu bé này đã dùng chính khẩu súng này bắn người cha dượng của mình và trớ trêu thay, người cha dượng này lại chính là cháu của một trùm xã hội đen đang có việc làm ăn với băng nhóm của Joey. Giờ đây đứng giữa cảnh sát và sếp của mình, Joey phải làm thế nào mới thoát được rắc rối này?</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Walker","avatar":""},{"name":"Cameron Bright","avatar":""},{"name":"Chazz Palminteri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324523);
