INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-tran-do', 'Bát Trận Đồ', 'Bát Trận Đồ', 'https://phimimg.com/upload/vod/20231207-1/a2797b21ada046f5d6472d4a75886115.jpg', 'https://phimimg.com/upload/vod/20231207-1/33516765f1eb2fd15d2a5e5f396f112e.jpg', '<p>Phim Bát trận đồ lấy bối cảnh vào năm 200 sau Công nguyên, ba nước Ngụy - Thục - Ngô phân chia thiên hạ. Bát trận đồ là quyển binh pháp đúc kết những kinh nghiệm chinh chiến của Khổng Minh - Gia Cát Lượng. Theo lời Võ hậu tiên đoán, 600 năm sau, quyển binh pháp này sẽ tái xuất hiện và làm dấy lên một trận phong ba, người có được Bát trận đồ sẽ trở thành bá chủ võ lâm. Gia Cát Khổng Minh bỗng nhiên từ trần không biết nguyên do nhưng hậu nhân vẫn tin tưởng vào trận pháp binh thư mà ông đã dùng hết tinh lực của mình để hoàn thành. Sự tái xuất giang hồ của Bát trận đồ sau 600 năm là sự khởi đầu cho những âm mưu xưng bá, những câu chuyện ly kỳ cùng những mối tình dang dở.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 17, 2006, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Hải My","avatar":""},{"name":"Trần Pháp Dung","avatar":""},{"name":"Thái Thiếu Phấn","avatar":""},{"name":"Vu Ba","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324523);
