INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-lua-ha-dong', 'Áo Lụa Hà Đông', 'The White Silk Dress', 'https://phimimg.com/upload/vod/20231210-1/227786e1c7d3eb95f79840eb2b96c00f.jpg', 'https://phimimg.com/upload/vod/20231210-1/63f61040bfde74c35a44c086e0f5ef10.jpg', '<p>Phim lấy bối cảnh những năm 1954, dưới sự đàn áp của thực dân Pháp, miền Bắc lâm vào thời loạn lạc. Đôi vợ chồng Dần và Gù cũng theo dòng người di cư từ Bắc vào Nam để đi tìm một tương lai tươi sáng hơn. Nhưng do đói khổ, lại vừa đúng lúc Dần hạ sinh đứa con đầu lòng, hai vợ chồng đành phải dừng chân tại Hội An. Từ đó, họ gắn bó với mảnh đất này như quê hương thứ hai...</p>', 'Full', 1, 'single', 'completed', 21, 2006, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Trương Ngọc Ánh","avatar":""},{"name":"NSƯT Quốc Khánh","avatar":""},{"name":"NSND Việt Anh","avatar":""},{"name":"NSND Như Quỳnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
