INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-su-that-kho-chiu', 'Một Sự Thật Khó Chịu', 'An Inconvenient Truth', 'https://phimimg.com/upload/vod/20231206-1/84dbf484ba982ac38574c43ef7e81de3.jpg', 'https://phimimg.com/upload/vod/20231206-1/37bc71dbc406aa8d075ef9514ecc94d4.jpg', '<p>Một bộ phim tài liệu về chiến dịch của Al Gore nhằm biến vấn đề nóng lên toàn cầu trở thành một vấn đề được công nhận trên toàn thế giới.</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Al Gore","avatar":""},{"name":"Billy West","avatar":""},{"name":"Ronald Reagan","avatar":""},{"name":"George W. Bush","avatar":""},{"name":"George H. W. Bush","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324523);
