INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-bat-tri-dac-khu-b13', 'Vùng Đất Bất Trị: Đặc Khu B13', 'District B13', 'https://phimimg.com/upload/vod/20231205-1/6438035cbe9d9497fa910aa59ae6b246.jpg', 'https://phimimg.com/upload/vod/20231205-1/006fc4f435ecd77058f54e731f5f7949.jpg', '<p>Bộ phim lấy bối cảnh thành phố Paris năm 2010, khi những khu vực nguy hiểm thuộc ngoại vi thành phố được bao bọc bởi các bức tường, và ở đó không có trường học, bệnh viện và ngay cả cảnh sát, chỉ có các tay buôn bán ma túy làm anh làm chị ở đây. Ở quận 13, Leito là một người thật thà, ông sống trong một căn hộ sạch sẽ và không cho phép các tay buôn thuốc phiện béng mảng đến khu vực này. Khi Leito phá hủy một triệu euro tiền buôn thuốc phiện của Taha Bemamud, tên này đã bắt cóc Lola, em gái của Leito, và những tên cảnh sát đã ăn tiền của Taha bắt Leito. Sáu tháng sau, cảnh sát trường Damien Tomaso tốt bụng được giao nhiệm vụ tìm một quả bom đã bị đánh cắp, quả bom có thể phá hủy cả quận 13 và hai triệu người dân ở đây. Cùng với Leito, họ đã tìm ra sự thật đằng sau việc đánh cắp quả bom, cũng như những bí mật của quận 13...</p>', 'Full', 1, 'single', 'completed', 9, 2006, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Cyril Raffaelli","avatar":""},{"name":"David Belle","avatar":""},{"name":"Tony D''Amario","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324523);
