INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('copying-beethoven', 'Copying Beethoven', 'Copying Beethoven', 'https://phimimg.com/upload/vod/20231202-1/3173e07341ce2aac4033de0f9352c6c1.jpg', 'https://phimimg.com/upload/vod/20231202-1/de906ef7c5c02ae56cf56976542b1094.jpg', '<p>Một cuộc khám phá hư cấu về cuộc đời của Beethoven trong những ngày cuối cùng ông làm việc cho Bản giao hưởng thứ chín. Bây giờ là năm 1824. Beethoven đang chạy đua để hoàn thành bản giao hưởng mới của mình. Tuy nhiên, đã nhiều năm trôi qua kể từ thành công cuối cùng của anh ấy và anh ấy đang bị ám ảnh bởi chứng điếc, sự cô đơn và chấn thương cá nhân. Cần gấp một người sao chép để giúp nhà soạn nhạc. Một nhân vật hư cấu được giới thiệu dưới hình dạng một sinh viên nhạc viện trẻ tuổi và là nhà soạn nhạc đầy tham vọng tên là Anna Holtz. Beethoven lanh lợi nghi ngờ rằng một người phụ nữ có thể tham gia vào kiệt tác của mình nhưng dần dần tin tưởng vào sự giúp đỡ của Anna và cuối cùng trở nên khá yêu mến cô ấy. Vào thời điểm tác phẩm được trình diễn, sự hiện diện của cô ấy trong cuộc đời anh là một điều tất yếu. Sự hiểu biết sâu sắc của cô ấy về công việc của anh ấy đến mức cô ấy thậm chí còn sửa chữa những sai lầm mà anh ấy mắc phải, trong khi tính cách đam mê của cô ấy mở ra cánh cửa vào thế giới riêng tư của anh ấy.</p>', 'Full', 1, 'single', 'completed', 9, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ed Harris","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Phyllida Law","avatar":""},{"name":"Ralph Riach","avatar":""},{"name":"Bill Stewart","avatar":""},{"name":"Angus Barnett","avatar":""},{"name":"Viktoria Dihen","avatar":""},{"name":"Matyelok Gibbs","avatar":""},{"name":"Karl Johnson","avatar":""},{"name":"Joe Anderson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
