INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoanh-khac-cuoc-doi', 'Khoảnh Khắc Cuộc Đời', 'The Lives of Others', 'https://phimimg.com/upload/vod/20231201-1/8383f26a64bb907ac27fb9f98e78a62c.jpg', 'https://phimimg.com/upload/vod/20231201-1/31558c2413bda43b948e5354311e8757.jpg', '<p>Đông Đức tháng 11, 1984. Wiesler là nhân viên Stasi chuyên theo dõi người khác. Điệp vụ mới nhất của hắn là nghe trộm hàng ngày hoạt động của cặp nghệ sĩ Sieland và Dreyman. Từ sự quan sát cuộc sống của những người khác, Wiesler đã có những biến chuyển tâm lý rõ rệt để dẫn đến thay đổi cuộc sống của chính mình.</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Martina Gedeck","avatar":""},{"name":"Ulrich Mühe","avatar":""},{"name":"Sebastian Koch","avatar":""},{"name":"Ulrich Tukur","avatar":""},{"name":"Thomas Thieme","avatar":""},{"name":"Hans-Uwe Bauer","avatar":""},{"name":"Volkmar Kleinert","avatar":""},{"name":"Matthias Brenner","avatar":""},{"name":"Charly Hübner","avatar":""},{"name":"Herbert Knaup","avatar":""},{"name":"Bastian Trost","avatar":""},{"name":"Marie Gruber","avatar":""},{"name":"Volker Michalowski","avatar":""},{"name":"Werner Daehn","avatar":""},{"name":"Hinnerk Schönemann","avatar":""},{"name":"Thomas Arnold","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
