INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-thap-doi', 'Thảm Họa Tháp Đôi', 'World Trade Center', 'https://phimimg.com/upload/vod/20231130-1/72f55e3afd7a8cd504b968edd884fdff.jpg', 'https://phimimg.com/upload/vod/20231130-1/b5a7f4cf23061ca658fa7030e353d997.jpg', '<p>Hai sĩ quan cảnh sát đấu tranh để sống sót khi họ bị mắc kẹt dưới đống đổ nát của Trung tâm Thương mại Thế giới vào ngày 11 tháng 9 năm 2001.</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Maria Bello","avatar":""},{"name":"Maggie Gyllenhaal","avatar":""},{"name":"Danny Nucci","avatar":""},{"name":"Stephen Dorff","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Jay Hernandez","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Dorothy Lyman","avatar":""},{"name":"Peter McRobbie","avatar":""},{"name":"Wass Stevens","avatar":""},{"name":"Frank Whaley","avatar":""},{"name":"Stoney Westmoreland","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Lola Cook","avatar":""},{"name":"Connor Paolo","avatar":""},{"name":"Anthony Piccininn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324523);
