INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoac-nguyen-giap-2006', 'Hoắc Nguyên Giáp', 'Fearless', 'https://phimimg.com/upload/vod/20231007-1/c654ee82398e4fa38317895668556582.jpg', 'https://phimimg.com/upload/vod/20231007-1/57e1856e13deb93f400e2aee85e66ffb.jpg', '<p>Hoắc Nguyên Giáp từ bé đã có ước mơ được nối tiếp cha mình trở thành cao thủ võ thuật Trung Hoa. Trải qua khó khăn và thử thách, cuối cùng Nguyên Giáp cũng đạt được ước nguyện đó. Nhưng rồi một số biến cố xảy đến khiến cho anh phải vắng mặt một thời gian. Tài năng của anh tỏa sáng trở lại khi một cuộc thi võ thuật được diễn ra và anh mang vinh dự đại diện cho đất nước mình để tham gia.</p>', 'Full', 1, 'single', 'completed', 16, 2006, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jet Li","avatar":""},{"name":"Sun Li","avatar":""},{"name":"Dong Yong","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Pau Hei-Ching","avatar":""},{"name":"Chen Zhihui","avatar":""},{"name":"Leung Ting","avatar":""},{"name":"Qu Yun","avatar":""},{"name":"Ma Zhongxuan","avatar":""},{"name":"Nathan Jones","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324523);
