INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-ao-giac-2006', 'Ký Ức Ảo Giác', 'Déjà Vu', 'https://phimimg.com/upload/vod/20231026-1/d3a3525c639b83ab583109eac0badcfe.jpg', 'https://phimimg.com/upload/vod/20231026-1/8a585668445dbe7923c84885bbea33ba.jpg', '<p>Ký ức ảo giác là một phim khoa học viễn tưởng giật gân của Mỹ năm 2006. Kịch bản phim do Bill Marsilii và Terry Rossio viết, và Jerry Bruckheimer sản xuất. Phim có sự tham gia của Denzel Washington, Paula Patton, Jim Caviezel, Val Kilmer, Adam Goldberg và Bruce Greenwood</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Paula Patton","avatar":""},{"name":"Val Kilmer","avatar":""},{"name":"Jim Caviezel","avatar":""},{"name":"Adam Goldberg","avatar":""},{"name":"Elden Henson","avatar":""},{"name":"Erika Alexander","avatar":""},{"name":"Bruce Greenwood","avatar":""},{"name":"Rich Hutchman","avatar":""},{"name":"Matt Craven","avatar":""},{"name":"Donna W. Scott","avatar":""},{"name":"Elle Fanning","avatar":""},{"name":"Brian Howe","avatar":""},{"name":"Enrique Castillo","avatar":""},{"name":"Mark Phinney","avatar":""},{"name":"Shondrella Avery","avatar":""},{"name":"John McConnel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324523);
