INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-huy-hoang', 'Ngày Huy Hoàng', 'Days of Glory', 'https://phimimg.com/upload/vod/20231129-1/a6b5dab50ff8a6a0cca681212e294e83.jpg', 'https://phimimg.com/upload/vod/20231129-1/28863674d5f2d811d08966a3ea1dff40.jpg', '<p>Năm 1943. Họ chưa bao giờ đặt chân lên đất Pháp nhưng vì nước Pháp đang có chiến tranh nên Said, Abdelkader, Messaoud và Yassir đã gia nhập Quân đội Pháp, cùng với 130.000 binh sĩ “bản địa” khác, để giải phóng “tổ quốc” khỏi kẻ thù Đức Quốc xã. Những anh hùng mà lịch sử đã lãng quên…</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jamel Debbouze","avatar":""},{"name":"Samy Naceri","avatar":""},{"name":"Roschdy Zem","avatar":""},{"name":"Sami Bouajila","avatar":""},{"name":"Bernard Blancan","avatar":""},{"name":"Mathieu Simonet","avatar":""},{"name":"Assaad Bouab","avatar":""},{"name":"Benoît Giros","avatar":""},{"name":"Mélanie Laurent","avatar":""},{"name":"Antoine Chappey","avatar":""},{"name":"Aurélie Eltvedt","avatar":""},{"name":"Thomas Langmann","avatar":""},{"name":"Thibault de Montalembert","avatar":""},{"name":"Diouc Koma","avatar":""},{"name":"Philippe Beglia","avatar":""},{"name":"Momo Debbouze","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324523);
