INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-su-bien-xanh', 'Thiên Sứ Biển Xanh', 'The Guardian', 'https://phimimg.com/upload/vod/20231129-1/43ee3cf9793fad1e7fbc7c2539edcb8f.jpg', 'https://phimimg.com/upload/vod/20231129-1/98e8b41f1c4ef923ae40f75987c0be8c.jpg', '<p>Câu chuyện nói về các nhân viên làm công việc nguy hiểm, cứu hộ trên biển. Một người thầy dày dặn kinh nghiệm và gặp không ít bất hạnh trong đời tư, một học trò gan dạ dũng cảm nhưng ngang tàng và bướng bỉnh. Chỉ khi đối mặt với cái chết, người ta mới thấm thía được cái giá của sự sống. Ben Randall (Kenvin Costner) đau đớn khi mất những đồng đội từng vào sinh ra tử với ông trong một cơn bão khủng khiếp khi đang làm nhiệm vụ nên ông chuyển đến một trường đào tạo đội cứu hộ trên biển và quyết tâm huấn luyện các học viên ở đây thành những nhân viên cứu hộ giỏi. Tại đây, ông gặp chàng trai trẻ ngang tàng, Jake Fischer (Ashton Kutcher), vốn là một tay bơi cự phách. Randall đã dùng tình thương và kinh nghiệm của mình không chỉ để đào tạo cậu thành một nhân viên cứu hộ giỏi mà còn giúp cậu hiểu ra giá trị của lòng dũng cảm và tính vị tha mà một nhân viên cứu hộ cần phải có.</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Costner","avatar":""},{"name":"Ashton Kutcher","avatar":""},{"name":"Sela Ward","avatar":""},{"name":"Melissa Sagemiller","avatar":""},{"name":"Dulé Hill","avatar":""},{"name":"Bryce Cass","avatar":""},{"name":"Omari Hardwick","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Benny Ciaramello","avatar":""},{"name":"Shelby Fenner","avatar":""},{"name":"Peter Gail","avatar":""},{"name":"Damon Lipari","avatar":""},{"name":"Scott Mueller","avatar":""},{"name":"Travis Willingham","avatar":""},{"name":"Eric Norris","avatar":""},{"name":"John Heard","avatar":""},{"name":"Richar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324523);
