INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('deck-the-halls', 'Deck the Halls', 'Deck the Halls', 'https://phimimg.com/upload/vod/20231129-1/b5cfa85a72393cfef0977a7527e140b3.jpg', 'https://phimimg.com/upload/vod/20231129-1/2d0506266fa892f350480c6b7caff6c4.jpg', '<p>Quyết tâm lật đổ triều đại của Steve Finch với tư cách là vua mùa lễ hội của thị trấn, Buddy Hall trát ngôi nhà của mình bằng rất nhiều đèn trang trí đến nỗi có thể nhìn thấy nó từ không gian! Khi vợ của họ gắn bó và con cái của họ cũng làm theo, hai người đàn ông chỉ leo thang sự ganh đua của họ - và sự trang trí của họ.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Danny DeVito","avatar":""},{"name":"Matthew Broderick","avatar":""},{"name":"Kristin Davis","avatar":""},{"name":"Kristin Chenoweth","avatar":""},{"name":"Alia Shawkat","avatar":""},{"name":"Dylan Blue","avatar":""},{"name":"Kelly Aldridge","avatar":""},{"name":"Sabrina Aldridge","avatar":""},{"name":"Jorge Garcia","avatar":""},{"name":"Fred Armisen","avatar":""},{"name":"Gillian Vigman","avatar":""},{"name":"Ryan Devlin","avatar":""},{"name":"Sean O''Bryan","avatar":""},{"name":"Su-chin Pak","avatar":""},{"name":"Jackie Burroughs","avatar":""},{"name":"Garry Chalk","avatar":""},{"name":"Nicola P","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324523);
