INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('deck-the-halls', 'Deck the Halls', 'Deck the Halls', 'deck the halls deck the halls danny devito matthew broderick kristin davis kristin chenoweth alia shawkat dylan blue kelly aldridge sabrina aldridge jorge garcia fred armisen gillian vigman ryan devlin sean o''bryan su-chin pak jackie burroughs garry chalk nicola p ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-thu-thu-tro-ve-kho-tang-vua-solomon', 'Hội Thủ Thư: Trở Về Kho Tàng Vua Solomon', 'The Librarian: Return to King Solomon''s Mines', 'https://phimimg.com/upload/vod/20231129-1/8e40d074db6ee9fcdd100ac0cfbedfd4.jpg', 'https://phimimg.com/upload/vod/20231129-1/a1074fff6c9e8950d67d44244adfd991.jpg', '<p>Sau chiến công hiển hách chiến thắng thế lực thù địch Serpent Brotherhood, Flynn Carsen quyết định nhận lãnh một công việc “không đụng hàng”: thủ thư. Với 22 tấm bằng trong tay, có vẻ công việc mới này có thể giúp anh che giấu được thân phận của minh. Anh bảo vệ một khối lượng sách khổng lồ, là kho tàng cực kỳ quý giá bao gồm những quyển sách thần thoại cổ tích bất hủ. Một ngày Carsen nghe được tin một lực lượng đen tối khác đang tiến hành thực hiện mưu đồ tìm kiếm chiếc chìa khoá mở cuốn sách ma thuật huyền bí của vua Solomon, cuốn sách có một phép màu ghê gớm có thể giúp ai sở hữu nó kiểm soát đuợc cả không gian lẫn thời gian… Sức mạnh mà ai cũng thèm khát có được nó bằng mọi giá. Carsen không hình dung ra sự nguy hiểm khi để kẻ xấu chiếm đoạt đuợc kho báu này. Một kế hoạch được phác thảo, chuyến phiêu lưu mới của chàng thủ thư bắt đâu. Lần này đồng hành bên cạnh anh là nhà khảo cổ học xinh đẹp Emily Davenport.</p>', 'Full', 1, 'single', 'completed', 16, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Noah Wyle","avatar":""},{"name":"Gabrielle Anwar","avatar":""},{"name":"Bob Newhart","avatar":""},{"name":"Jane Curtin","avatar":""},{"name":"Olympia Dukakis","avatar":""},{"name":"Erick Avari","avatar":""},{"name":"Hakeem Kae-Kazim","avatar":""},{"name":"Robert Foxworth","avatar":""},{"name":"Zahn McClarnon","avatar":""},{"name":"Lisa Brenner","avatar":""},{"name":"Jonathan Frakes","avatar":""},{"name":"Peter Butler","avatar":""},{"name":"Tertius Meintjes","avatar":""},{"name":"Dawie Ackermann","avatar":""},{"name":"Mehboob Bawa","avatar":""},{"name":"Raffaele Sabatini","avatar":""},{"name":"Marisa","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324523);
