INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-nhau-di-tu', 'Cùng Nhau Đi Tù', 'Let''s Go to Prison', 'https://phimimg.com/upload/vod/20231125-1/76e3cf9d5d24aae7b4494b62671fdc34.jpg', 'https://phimimg.com/upload/vod/20231125-1/c2f6443c5b700cb36306830b760bdd3b.jpg', '<p>Một tù nhân có cơ hội trả thù khi con trai của vị thẩm phán đã tống anh vào tù bị kết án oan và phải ngồi tù.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dax Shepard","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Chi McBride","avatar":""},{"name":"David Koechner","avatar":""},{"name":"Dylan Baker","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Jay Whittaker","avatar":""},{"name":"Amy Hill","avatar":""},{"name":"David Darlow","avatar":""},{"name":"Bob Odenkirk","avatar":""},{"name":"Jerry Minor","avatar":""},{"name":"Joseph Marcus","avatar":""},{"name":"Nick Phalen","avatar":""},{"name":"A.J. Balance","avatar":""},{"name":"Mary Seibel","avatar":""},{"name":"Susan Messing","avatar":""},{"name":"Jim Zulevic","avatar":""},{"name":"Bill McGough","avatar":""},{"name":"Bert Ma","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324524);
