INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-tu-do', 'Chiến Binh Tự Do', 'V for Vendetta', 'https://phimimg.com/upload/vod/20231125-1/ababbd1c14e8a113faf72ae6accb51ca.jpg', 'https://phimimg.com/upload/vod/20231125-1/cc96a09fa249430b33c5cd958c8bf8a5.jpg', '<p>Dựa theo bộ truyện tranh của Alan Moore, câu chuyện nói về thời tương lai tại Anh quốc, một tên khủng bố với biệt danh V đấu tranh chống lại chính phủ Anh cùng với sự giúp đỡ của một người phụ nữ mang tên Evey, nguời được V cứu sống...Nhân vật chính là V có kế hoạch cho nổ tòa đại hình và nhà quốc hội Anh, nhằm lật đổ đảng chuyên chế đang cầm quyền tại Anh lúc bấy giờ. Anh luôn xuất hiện trong bộ áo choàng đen và chiếc mặt nạ Guy Fawkes - biểu tượng của tư tưởng vô chính phủ.Bối cảnh xảy ra là nước Anh chuyên chế, câu chuyện xoay quanh một phụ nữ trẻ dịu dàng tên Evey Hammond (Natalie Portman). Cô đang muốn có một cuộc sống bình lặng yên ổn sau những biến cố xảy ra trong quá khứ. Một ngày nọ, Evey được cứu thoát ...</p>', 'Full', 1, 'single', 'completed', 10, 2006, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Natalie Portman","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Stephen Rea","avatar":""},{"name":"Stephen Fry","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Tim Pigott-Smith","avatar":""},{"name":"Natasha Wightman","avatar":""},{"name":"Rupert Graves","avatar":""},{"name":"Roger Allam","avatar":""},{"name":"Ben Miles","avatar":""},{"name":"Sinéad Cusack","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"John Standing","avatar":""},{"name":"Imogen Poots","avatar":""},{"name":"Clive Ashborn","avatar":""},{"name":"Emma Field-Rayner","avatar":""},{"name":"Ian Burfield","avatar":""},{"name":"Mark P","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822