INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('memories-of-matsuko', 'Memories of Matsuko', 'Memories of Matsuko', 'https://phimimg.com/upload/vod/20231125-1/b9c7274509fb96f5e1622c7f443453b1.jpg', 'https://phimimg.com/upload/vod/20231125-1/d54d1f8711cfc1be6c56e9c1c9b374fa.jpg', '<p>Trong khi lục lọi đồ đạc của người dì vừa qua đời, Matsuko, cháu trai Sho đã cùng nhau tìm hiểu những sự kiện quan trọng đã nhấn chìm cuộc đời của Matsuko vào một bi kịch tuyệt vọng.</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Miki Nakatani","avatar":""},{"name":"Eita Nagayama","avatar":""},{"name":"Yûsuke Iseya","avatar":""},{"name":"Teruyuki Kagawa","avatar":""},{"name":"Mikako Ichikawa","avatar":""},{"name":"Asuka Kurosawa","avatar":""},{"name":"Akira Emoto","avatar":""},{"name":"Gori","avatar":""},{"name":"Ko Shibasaki","avatar":""},{"name":"Kankuro Kudo","avatar":""},{"name":"Shinji Takeda","avatar":""},{"name":"Yoshiyoshi Arakawa","avatar":""},{"name":"Gekidan Hitori","avatar":""},{"name":"Magi","avatar":""},{"name":"Shosuke Tanihara","avatar":""},{"name":"Cunning Takeyama","avatar":""},{"name":"Masahiro Koumoto","avatar":""},{"name":"Tak","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324524);
