INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-rocky-balboa', 'Huyền Thoại Rocky Balboa', 'Rocky Balboa', 'https://phimimg.com/upload/vod/20231125-1/4fd386ae003e76f9dd1789428425faaf.jpg', 'https://phimimg.com/upload/vod/20231125-1/104fa01f31e2f2a9a32ec86e7462e645.jpg', '<p>Bắt đầu từ khoảng thời gian 16 năm của phần trước, vợ của Rocky Balboa đã qua đời vì căn bệnh ung thư, bỏ lại một mình Rocky cùng cậu con trai nay đã trưởng thành, giờ đây thì ông không còn tâm trí để mà chạy theo danh vọng, thay vào đó ông thường nghĩ về quá khứ. Một cuộc gặp mặt ngẫu nhiên với một cô gái bây giờ đã trưởng thành khiến anh trở lại đúng hướng. Rocky luôn muốn giúp đỡ những người mà anh quan tâm đến việc cho cô và con trai mượn một bàn tay. Rocky hiện sở hữu một nhà hàng nhỏ ở trung tâm của Philadelphia, ông ấy thường dành thời gian rảnh kể những câu chuyện cho những người hỏi về những cuộc chiến cũ và chụp ảnh với người hâm mộ.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Burt Young","avatar":""},{"name":"Antonio Tarver","avatar":""},{"name":"Geraldine Hughes","avatar":""},{"name":"Milo Ventimiglia","avatar":""},{"name":"Tony Burton","avatar":""},{"name":"A.J. Benza","avatar":""},{"name":"James Francis Kelly III","avatar":""},{"name":"Lou DiBella","avatar":""},{"name":"Mike Tyson","avatar":""},{"name":"Henry G. Sanders","avatar":""},{"name":"Pedro Lovell","avatar":""},{"name":"Ana Gerena","avatar":""},{"name":"Angela Boyd","avatar":""},{"name":"Louis Giansante","avatar":""},{"name":"Maureen Schilling","avatar":""},{"name":"Lah","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
