INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('unknown', 'Unknown', 'Unknown', 'unknown unknown jim caviezel greg kinnear bridget moynahan joe pantoliano barry pepper jeremy sisto peter stormare clayne crawford chris mulkey kevin chapman mark boone junior david selby adam rodríguez thomas rosales jr. patricia belcher jeff daniel phill ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('au-trung-ma', 'Ấu Trùng Ma', 'Slither', 'https://phimimg.com/upload/vod/20231123-1/1c975f6ec3bef08da1a81201aa73d210.jpg', 'https://phimimg.com/upload/vod/20231123-1/7d66294b0f6f9d172614c0bc26b0b5ca.jpg', '<p>Một thiên thạch lạ lùng đã rơi xuống thành phố yên bình Wheelsy. Một loại ký sinh trùng gớm ghiếc thoát ra từ trong mảnh thiên thạch này. Nó nằm yên rất lâu và chờ đợi, chờ tìm được một thân xác thích hợp để làm nơi trú ngụ trước khi thực hiện kế hoạch thôn tính quả địa cầu. Và nạn nhân xấu số chính là Grant Grant, anh chàng giàu có và quyền lực nhất vùng. &nbsp;Sau khi mắc phải loại ký sinh từ Vũ trụ, Grant ăn càng ngày càng nhiều, lúc nào anh cũng thèm thịt tươi. Những con thú cưng, những đàn gia cầm và thậm chí là rất nhiều người dân trong vùng bắt đầu biết mất một cách bí ẩn. Tất cả manh mối đều cho thấy Grant Grant chính là ngọn nguồn của những vụ mất tích này. Cô vợ Starla của Grant cũng dần cảm thấy nghi ngờ về hành vi lạ lùng của chồng mình. Nhưng đến khi Starla biết được sự thật thì dường như mọi việc đã quá muộn màng. Grant đã hóa thành một sinh vật dị dạng vô cùng khủng khiếp...</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Nathan Fillion","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Gregg Henry","avatar":""},{"name":"Tania Saulnier","avatar":""},{"name":"Don Thompson","avatar":""},{"name":"Jenna Fischer","avatar":""},{"name":"Xantha Radley","avatar":""},{"name":"Dustin Milligan","avatar":""},{"name":"James Gunn","avatar":""},{"name":"Lloyd Kaufman","avatar":""},{"name":"Rob Zombie","avatar":""},{"name":"Haig Sutherland","avatar":""},{"name":"Zak Ludwig","avatar":""},{"name":"Iris Quinn","avatar":""},{"name":"William MacDonald","avatar":""},{"name":"Matreya Fedor","avatar":""},{"name":"Am","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324524);
