INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-goya', 'Bóng Ma Goya', 'Goya''s Ghosts', 'https://phimimg.com/upload/vod/20231120-1/b03af01f415ed17832275d1db52f426e.jpg', 'https://phimimg.com/upload/vod/20231120-1/06b0ac77950f64a7e78f38dbf9542f6f.jpg', '<p>Họa sĩ Francisco Goya dính líu đến Tòa án Dị giáo Tây Ban Nha sau khi nàng thơ của ông, Inés, bị nhà thờ bắt giữ vì tội dị giáo. Gia đình cô hướng về anh ta, hy vọng rằng mối liên hệ của anh ta với Điều tra viên cuồng tín Lorenzo, người mà anh ta đang vẽ tranh, có thể giúp cô được thả.</p>', 'Full', 1, 'single', 'completed', 19, 2006, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Javier Bardem","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Randy Quaid","avatar":""},{"name":"José Luis Gómez","avatar":""},{"name":"Michael Lonsdale","avatar":""},{"name":"Blanca Portillo","avatar":""},{"name":"Mabel Rivera","avatar":""},{"name":"Unax Ugalde","avatar":""},{"name":"Fernando Tielve","avatar":""},{"name":"David Calder","avatar":""},{"name":"Ramón Langa","avatar":""},{"name":"Manuel de Blas","avatar":""},{"name":"Andrés Lima","avatar":""},{"name":"Concha Hidalgo","avatar":""},{"name":"Trinidad Rugero","avatar":""},{"name":"Silvia","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324524);
