INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('little-children', 'Little Children', 'Little Children', 'https://phimimg.com/upload/vod/20231116-1/4774d3f723e6a93f83a8a982134546a8.jpg', 'https://phimimg.com/upload/vod/20231116-1/6885f761ba0dae82a90515dfa0ba3c25.jpg', '<p>Cuộc sống của hai cặp vợ chồng thất tình từ những cuộc hôn nhân riêng biệt, một tội phạm tình dục đã đăng ký và một cựu sĩ quan cảnh sát bị thất sủng giao nhau khi họ đấu tranh để chống lại sự tổn thương và cám dỗ của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Winslet","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Jackie Earle Haley","avatar":""},{"name":"Noah Emmerich","avatar":""},{"name":"Gregg Edelman","avatar":""},{"name":"Phyllis Somerville","avatar":""},{"name":"Raymond J. Barry","avatar":""},{"name":"Jane Adams","avatar":""},{"name":"Will Lyman","avatar":""},{"name":"Ty Simpkins","avatar":""},{"name":"Sadie Goldstein","avatar":""},{"name":"Helen Carey","avatar":""},{"name":"Sarah Buxton","avatar":""},{"name":"Mary B. McCann","avatar":""},{"name":"Trini Alvarado","avatar":""},{"name":"Marsh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324524);
