INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-so-hieu-93', 'Chuyến Bay Số Hiệu 93', 'United 93', 'https://phimimg.com/upload/vod/20231116-1/af0e9021e6ca4224b7ad3b1a144766ff.jpg', 'https://phimimg.com/upload/vod/20231116-1/650d7ea348a6de4a0a479898b5c0d4e1.jpg', '<p>United 93 được dựa theo sự kiện có thật về chuyến bay của hãng hàng không United Airlines mang số hiệu 93 khởi hành từ sân bay quốc tế Newark trên đường bay đến San Francisco ngày 11/9/2001. Bất ngờ máy bay bị không tặc buộc phải chuyển hướng đến Washington D.C. Không khí căng thẳng và bàng hoàng đến bất lực của những người làm việc tại Trung tâm giám sát không lưu trước thảm kịch đang diễn ra. Còn trên chuyến bay United 93, nơi mà 40 hành khách và phi hành đoàn đã cùng nhau chống trả quyết liệt 4 tên khủng bố khiến cho kế hoạch lái máy bay đâm vào Nhà Trắng của chúng bất thành.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"J.J. Johnson","avatar":""},{"name":"Gary Commock","avatar":""},{"name":"Polly Adams","avatar":""},{"name":"Opal Alladin","avatar":""},{"name":"Starla Benford","avatar":""},{"name":"Trish Gates","avatar":""},{"name":"Nancy McDoniel","avatar":""},{"name":"David Alan Basche","avatar":""},{"name":"Richard Bekins","avatar":""},{"name":"Susan Blommaert","avatar":""},{"name":"Ray Charleson","avatar":""},{"name":"Christian Clemenson","avatar":""},{"name":"Liza Colón-Zayas","avatar":""},{"name":"Lorna Dallas","avatar":""},{"name":"Denny Dillon","avatar":""},{"name":"Trieste Kelly Dunn","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035a