INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-trai-tim-co-don', 'Những Trái Tim Cô Đơn', 'Lonely Hearts', 'https://phimimg.com/upload/vod/20231118-1/456fb51e14113880603a964ad4ec77ee.jpg', 'https://phimimg.com/upload/vod/20231118-1/0dd80227775ab4f487dc9a05541bed48.jpg', '<p>Vào cuối những năm 1940, một cặp đôi sát nhân được biết đến với cái tên &#39;Kẻ sát nhân những trái tim cô đơn&#39; đã giết chết gần chục người. Hai thám tử cố gắng bắt bộ đôi tìm thấy mục tiêu của họ thông qua các thông tin cá nhân trên báo.</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Travolta","avatar":""},{"name":"James Gandolfini","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"Scott Caan","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Michael Gaston","avatar":""},{"name":"Dan Byrd","avatar":""},{"name":"Alice Krige","avatar":""},{"name":"Dagmara Domińczyk","avatar":""},{"name":"Bailee Madison","avatar":""},{"name":"Bruce MacVittie","avatar":""},{"name":"John Doman","avatar":""},{"name":"Ellen Travolta","avatar":""},{"name":"Jason Gray-Stanford","avatar":""},{"name":"Sam Travolta","avatar":""},{"name":"Jonathan Ra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324524);
