INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('love-asia', 'Love Asia', 'Love Asia', 'null', 'https://phimimg.com/upload/vod/20231117-1/fb7f6763689a2f0c3a1b81487a66e230.jpg', '<p>Với 10 siêu mẫu nổi tiếng khắp châu Á, được giám sát bởi Maggie Q, và thậm chí với Lin Chi-ling, một cô gái ngọt ngào ở Đài Loan, &quot;Love Asia&quot; được chụp bởi nhiếp ảnh gia thời trang người Singapore Leslie Kee. Được quay tại các khu nghỉ dưỡng ở Langkawi, Kuala Lumpur và những nơi khác ở Malaysia, đó là một bộ phim của mùa hè. Trong bộ phim này, có cảnh hậu trường quay cảnh Lin Chiling chơi piano, khiêu vũ và tiệc tùng với các siêu mẫu khác trong quán rượu.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Maggie Q","avatar":""},{"name":"Lin Chi-ling","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324524);
