INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-di-thu-vi', 'Chuyến Đi Thú Vị', 'RV', 'https://phimimg.com/upload/vod/20231116-1/aefd7c655e492f4eb42b030aba842a04.jpg', 'https://phimimg.com/upload/vod/20231116-1/8bfb5cc1094ab51f1984625a4f4f2df2.jpg', '<p>Leo lên chiếc xe giải trí khổng lồ của họ để thực hiện một chuyến đi xuyên quốc gia đến Colorado Rockies, gia đình Munro – dẫn đầu là tộc trưởng rối loạn chức năng, Bob – chuẩn bị cho cuộc phiêu lưu để đời. Nhưng việc dành hai tuần cùng nhau trong một không gian nhỏ nghiêm túc có một cách làm chật chội phong cách của họ.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Cheryl Hines","avatar":""},{"name":"JoJo","avatar":""},{"name":"Josh Hutcherson","avatar":""},{"name":"Jeff Daniels","avatar":""},{"name":"Kristin Chenoweth","avatar":""},{"name":"Hunter Parrish","avatar":""},{"name":"Chloe Sonnenfeld","avatar":""},{"name":"Alex Ferris","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Tony Hale","avatar":""},{"name":"Brian Howe","avatar":""},{"name":"Richard Ian Cox","avatar":""},{"name":"Erika-Shaye Gair","avatar":""},{"name":"Veronika Sztopa","avatar":""},{"name":"Rob LaBelle","avatar":""},{"name":"Brian Markinson","avatar":""},{"name":"Kirs","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324524);
