INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ran-doc-tren-khong', 'Rắn Độc Trên Không', 'Snakes on a Plane', 'https://phimimg.com/upload/vod/20231116-1/cc4d0e90ebb6ee79b3dab0256936ffbd.jpg', 'https://phimimg.com/upload/vod/20231116-1/fa80753d0eb1f3bbdd88a48ddf6c8098.jpg', '<p>Là nhân chứng duy nhất chống lại tên trùm xã hội đen Eddie trước tòa, Sean được các đặc vụ FBI dẫn giải trên chuyến bay từ Hawaii đến Los Angeles. Nhưng bọn tội phạm cao tay hơn, bọn chúng đưa hàng trăm con rắn độc lên máy bay nhằm thực hiện âm mưu thâm độc: giết người bịt đầu mối! Khi máy bay bay ngang qua Thái Bình Dương thì hàng trăm con rắn độc đủ mọi kích cỡ từ khoang hành lý bắt đầu chui ra theo ống thông gió bò khắp máy bay, phá hủy hệ thống máy móc và bắt đầu cắn chết người...</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Samuel L. Jackson","avatar":""},{"name":"Julianna Margulies","avatar":""},{"name":"Nathan Phillips","avatar":""},{"name":"Kenan Thompson","avatar":""},{"name":"Rachel Blanchard","avatar":""},{"name":"Flex Alexander","avatar":""},{"name":"Keith Dallas","avatar":""},{"name":"Sunny Mabrey","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Elsa Pataky","avatar":""},{"name":"Bruce James","avatar":""},{"name":"Casey Dubois","avatar":""},{"name":"Gerard Plunkett","avatar":""},{"name":"Terry Chen","avatar":""},{"name":"Emily Holmes","avatar":""},{"name":"Mark Houghton","avatar":""},{"name":"David Koechn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85