INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-quyen', 'Hắc Quyền', 'Fatal Contact', 'https://phimimg.com/upload/vod/20231113-1/081c0cde75a32a4276b6d71afbdd5c6f.jpg', 'https://phimimg.com/upload/vod/20231113-1/2b96a1ed9741e3ea5a14db080eee587e.jpg', '<p>Cao Cương tính tình chính trực, võ nghệ cao cường, từng đoạt quán quân giải wushu toàn quốc. Trong một lần đến Hong Kong biểu diễn ngắn hạn, Cao Cương bị dẫn dắt vào một hội thi đấu võ đài bất hợp pháp, và rồi dần dần anh lún sâu vào một thế giới đen tối, máu me và tội ác. Bộ phim Hợp Đồng Giết Thuê do Ngô Kinh thủ vai cũng đã đóng dấu một bước ngoặt trong cuộc đời anh...</p>', 'Full', 1, 'single', 'completed', 16, 2006, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wu Jing","avatar":""},{"name":"Ronald Cheng","avatar":""},{"name":"Miki Yeung","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Andy On","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Timmy Hung","avatar":""},{"name":"Johnny Lu","avatar":""},{"name":"Theresa Fu","avatar":""},{"name":"Hui Siu-Hung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324524);
