INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-song-han', 'Quái Vật Sông Hàn', 'The Host', 'https://phimimg.com/upload/vod/20231114-1/06aa1b6af676f1736b81d7ffc95aad16.jpg', 'https://phimimg.com/upload/vod/20231114-1/d74dc1ac175f3b3ca7b29a174ea78faf.jpg', '<p>Trước bom tấn Parasite, đạo diễn Bong Joon Ho đã từng thành công với dòng phim quái vật với The Host (tựa Việt: Quái Vật Sông Hàn).phim kể về cuộc chiến đấu của gia đình Hee Bong với một con quái vật ở bờ sông Han. Mọi sự việc đều do những chất thải hóa học của một nhà máy bên dòng sông Hàn đã tạo ra một con quái vật khổng lồ.Ban đầu, con quái vật chỉ ăn những động vật nhỏ dưới lòng sông nhưng rồi một ngày, nó bắt đầu tấn công và ăn thịt con người. Chứng kiến cô con gái bé bỏng bị bắt đi, Hee Bong – một chàng trai sống bên bờ sông Hàn đã cùng những người thân của mình lên đường tìm kiếm con quái vật… Một cuộc chiến không cân sức giữa những con người nhỏ bé với một con quái vật to lớn, nhanh nhẹn và nó thích ăn thịt người . Liệu họ có cứu được cô bé và tiêu diệu được con quái vật , chúng ta cùng theo dõi.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Song Kang-ho","avatar":""},{"name":"Byun Hee-bong","avatar":""},{"name":"Park Hae-il","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"Ko A-sung","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Lee Jae-eung","avatar":""},{"name":"Lee Dong-ho","avatar":""},{"name":"Yoon Je-moon","avatar":""},{"name":"Yim Pil-sung","avatar":""},{"name":"Kim Roi-ha","avatar":""},{"name":"Koh Soo-hee","avatar":""},{"name":"Kim Hak-sun","avatar":""},{"name":"Scott Wilson","avatar":""},{"name":"Brian Rhee","avatar":""},{"name":"Paul Lazar","avatar":""},{"name":"David Anselmo","avatar":""},{"name":"Baek Do-bin","avatar":""},{"name":"Martin Lord Cayce","avatar":""},{"name":"Ch","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324524);
