INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-sieu-nhan', 'Học Viện Siêu Nhân', 'Zoom', 'https://phimimg.com/upload/vod/20231115-1/c71df9d20a93751288800a8ec2cf3333.jpg', 'https://phimimg.com/upload/vod/20231115-1/ff9d0148dabb9642ee5f1c4eb8f8f18f.jpg', '<p>Cựu Siêu anh hùng Jack Shepard, còn được gọi là Captain Zoom, được gọi trở lại để làm việc để biến một nhóm trẻ em Ragtag không thể biến thành một thế hệ siêu anh hùng mới. Tại một học viện quyền riêng tư, ông đào tạo Dylan, một cậu bé 17 tuổi có thể biến vô hình; Mùa hè, một cô gái 16 tuổi với sức mạnh telekinetic; Tucker, một cậu bé 12 tuổi với sức mạnh để mở rộng bất kỳ phần nào trong cơ thể mình; và Cindy, một cô gái 6 tuổi với siêu sức mạnh.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tim Allen","avatar":""},{"name":"Courteney Cox","avatar":""},{"name":"Chevy Chase","avatar":""},{"name":"Spencer Breslin","avatar":""},{"name":"Kevin Zegers","avatar":""},{"name":"Kate Mara","avatar":""},{"name":"Michael Cassidy","avatar":""},{"name":"Ryan Whitney Newman","avatar":""},{"name":"Rip Torn","avatar":""},{"name":"Cornelia Guest","avatar":""},{"name":"Ashton Moio","avatar":""},{"name":"Hunter Aarniokoski","avatar":""},{"name":"Thomas F. Wilson","avatar":""},{"name":"Ridge Canipe","avatar":""},{"name":"Danny McCarthy","avatar":""},{"name":"David L. Lander","avatar":""},{"name":"Lauren Sánch","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-ho