INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-toi-la-gangster-3', 'Vợ Tôi Là Gangster 3', 'My Wife Is a Gangster 3', 'https://phimimg.com/upload/vod/20231115-1/7824c1ec2f430e6a18e0435d7f0d0fd7.jpg', 'https://phimimg.com/upload/vod/20231115-1/e342eae2e59f17508a4ea5ca13f9f7a5.jpg', '<p>Aryung là người thừa kế tài sản của một Trùm gangster Hong Kong khét tiếng nhưng trước sự truy đuổi gắt gao của các băng nhóm đối địch, cô đành tạm lánh qua quê mẹ, Hàn Quốc., ở đây cô gặp Gichul, một tay tập tành làm gangster, bảo vệ. Để giao tiếp được với Aryung, Gichul phải thuê Yunhee làm người phiên dịch và bao nhiêu sự cố cười ra nước mắt bắt đầu từ đây</p>', 'Full', 1, 'single', 'completed', 20, 2006, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Shu Qi","avatar":""},{"name":"Lee Beom-su","avatar":""},{"name":"Hyun Young","avatar":""},{"name":"Oh Ji-ho","avatar":""},{"name":"Jo Hee-bong","avatar":""},{"name":"Kim Byung-choon","avatar":""},{"name":"Choi Ryung","avatar":""},{"name":"Kim Byung-man","avatar":""},{"name":"Ti Lung","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Shek Sau","avatar":""},{"name":"Wong Shu-Tong","avatar":""},{"name":"Choi Min-soo","avatar":""},{"name":"Hong Seok-yeon","avatar":""},{"name":"Lee Ki-Yong","avatar":""},{"name":"Ho Pak-Kwong","avatar":""},{"name":"Tang Chiu-Yau","avatar":""},{"name":"Anthony Carpio","avatar":""},{"name":"Johnny Cheung Wa","avatar":""},{"name":"Mak Wai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
