INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-lao-tot-bung', 'Ông Lão Tốt Bụng', 'Black Snake Moan', 'https://phimimg.com/upload/vod/20231113-1/7cbfeb79e76b63ddf6a0031cd34091c8.jpg', 'https://phimimg.com/upload/vod/20231113-1/bb9360775f5bd723dbaeb4c853ac945b.jpg', '<p>Một nghệ sĩ blues kính sợ Chúa đến với một phụ nữ trẻ hoang dã, là nạn nhân của lạm dụng tình dục thời thơ ấu, đang tìm kiếm tình yêu ở khắp mọi nơi, nhưng không bao giờ tìm thấy nó.</p>', 'Full', 1, 'single', 'completed', 12, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christina Ricci","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Justin Timberlake","avatar":""},{"name":"S. Epatha Merkerson","avatar":""},{"name":"John Cothran","avatar":""},{"name":"David Banner","avatar":""},{"name":"Michael Raymond-James","avatar":""},{"name":"Adriane Lenox","avatar":""},{"name":"Kim Richards","avatar":""},{"name":"Neimus K. Williams","avatar":""},{"name":"Leonard L. Thomas","avatar":""},{"name":"Ruby Wilson","avatar":""},{"name":"Claude Phillips","avatar":""},{"name":"Amy Lavere","avatar":""},{"name":"Clare Grant","avatar":""},{"name":"Jeff","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
