INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('half-nelson', 'Half Nelson', 'Half Nelson', 'https://phimimg.com/upload/vod/20231112-1/2c2d9942a5c1f1b8fbd976d45313d750.jpg', 'https://phimimg.com/upload/vod/20231112-1/99d34fb7f549f823c043371ba42c01f0.jpg', '<p>Bất chấp sự cống hiến của mình cho những học sinh trung học cơ sở lấp đầy lớp học của mình, giáo viên lý tưởng Dan Dunne có một cuộc sống nghiện ngập bí mật mà phần lớn học sinh của ông sẽ không bao giờ biết. Nhưng mọi thứ thay đổi khi cậu học sinh rắc rối Drey phát hiện ra điều đáng kinh ngạc về cuộc đời bí mật của mình, khiến mối quan hệ mong manh giữa hai người có thể kết thúc một cách thảm hại hoặc mang đến một chất xúc tác cho hy vọng.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Gosling","avatar":""},{"name":"Shareeka Epps","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Jeff Lima","avatar":""},{"name":"Monique Gabriela Curnen","avatar":""},{"name":"Tina Holmes","avatar":""},{"name":"Nathan Corbett","avatar":""},{"name":"Tyra Kwao-Vovo","avatar":""},{"name":"Rosemary Ledee","avatar":""},{"name":"Tristan Mack Wilds","avatar":""},{"name":"Bryce Silver","avatar":""},{"name":"Kaela C. Pabon","avatar":""},{"name":"Erica Rivera","avatar":""},{"name":"Stephanie Bast","avatar":""},{"name":"Eleanor Hutchins","avatar":""},{"name":"Sebastian Sozzi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
