INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('half-nelson', 'Half Nelson', 'Half Nelson', 'half nelson half nelson ryan gosling shareeka epps anthony mackie jeff lima monique gabriela curnen tina holmes nathan corbett tyra kwao-vovo rosemary ledee tristan mack wilds bryce silver kaela c. pabon erica rivera stephanie bast eleanor hutchins sebastian sozzi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-co-cha-ong', 'Ngọn Cờ Cha Ông', 'Flags of Our Fathers', 'https://phimimg.com/upload/vod/20231112-1/b46c7ba1af05221004d8baf9f9df029c.jpg', 'https://phimimg.com/upload/vod/20231112-1/b5989dab36e2b5b3b9727ba91113663c.jpg', '<p>Tháng 2 năm 1945, Đại chiến thế giới lần thứ hai đang ở trong giai đoạn quyết liệt nhất. Lúc này, phe Đồng minh gần như đã giành thắng lợi ở mặt trận châu Âu, song cuộc chiến ở khu vực Thái Bình Dương vẫn tiếp tục diễn ra căng thẳng với sự hiện diện của phát xít Nhật. Một trong những trận đánh quan trọng và đẫm máu nhất đã diễn ra ở đảo Iwo Jima của Nhật Bản. Sau nhiều ngày giao tranh ác liệt, quân đội Mỹ đã đánh tan đạo quân của phát xít Nhật cố thủ tại đây. Trận chiến kết thúc với một hình ảnh đi vào lịch sử: 5 lính thủy đánh bộ và một bác sĩ hải quân Mỹ dựng ngọn cờ Mỹ trên đỉnh núi Suribachi, báo hiệu chiến thắng cho quân Đồng minh.</p>', 'Full', 1, 'single', 'completed', 17, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Phillippe","avatar":""},{"name":"Jesse Bradford","avatar":""},{"name":"Adam Beach","avatar":""},{"name":"John Benjamin Hickey","avatar":""},{"name":"John Slattery","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Paul Walker","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Melanie Lynskey","avatar":""},{"name":"Tom McCarthy","avatar":""},{"name":"Chris Bauer","avatar":""},{"name":"Judith Ivey","avatar":""},{"name":"Myra Turley","avatar":""},{"name":"Joseph Cross","avatar":""},{"name":"Benjamin Walker","avatar":""},{"name":"Al","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324524);
