INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngon-co-cha-ong', 'Ngọn Cờ Cha Ông', 'Flags of Our Fathers', 'ngọn cờ cha ông flags of our fathers ryan phillippe jesse bradford adam beach john benjamin hickey john slattery barry pepper jamie bell paul walker robert patrick neal mcdonough melanie lynskey tom mccarthy chris bauer judith ivey myra turley joseph cross benjamin walker al ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('com-xau-com-tot', 'Cớm Xấu Cớm Tốt', 'Good Cop, Bad Cop', 'https://phimimg.com/upload/vod/20231113-1/cad32ce8fff88c31a2ae8b57f7209983.jpg', 'https://phimimg.com/upload/vod/20231113-1/4483e89232bc04dba047b231a5720e7a.jpg', '<p>Phải khó khăn lắm Martin Ware, thanh tra cảnh sát hàng đầu Montreal, mới làm quen được với việc phải cộng tác với người cộng sự ương bướng, thanh tra cảnh sát David Bouchard. Thứ duy nhất có thể khiến hai con ngựa chứng xích lại gần nhau chính là niềm đam mê công việc. Tệ hại là công việc đang lôi họ xa dần với gia đình thân thuộc của mình.Một vụ án kì quặc đang đợi cả hai ở phía trước. Xác chết của một tay kế toán khá giả đuợc tìm thấy nằm vắt ngang trên một biển quảng cáo lớn tại một con đường xa lộ. Nạn nhân dường như được thả xuống từ độ cao tối thiểu là 80 m từ trên cao, thân thể mang rất nhiều thương tích trước khi chết…Bầu nhiệt huyết đang nóng chảy buộc hai người đồng nghiệp xông pha vào một cuộc điều tra đầy gay cấn, ly kỳ, đầy nguy hiểm… Nhờ đó, hai người đàn ông tự mãn đã nhận ra được những ý nghĩa thực sự của cuộc sống, tình yêu và người cộng sự.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Patrick Huard","avatar":""},{"name":"Colm Feore","avatar":""},{"name":"Michel Beaudry","avatar":""},{"name":"Patrice Bélanger","avatar":""},{"name":"Hugolin Chevrette","avatar":""},{"name":"Richard Howland","avatar":""},{"name":"Erik Knudsen","avatar":""},{"name":"Sarah-Jeanne Labrosse","avatar":""},{"name":"Sarain Boylan","avatar":""},{"name":"Nicolas Canuel","avatar":""},{"name":"Lucie Laurier","avatar":""},{"name":"Pierre Lebeau","avatar":""},{"name":"Louis-José Houde","avatar":""},{"name":"Rick Mercer","avatar":""},{"name":"Pierre Boudreau","avatar":""},{"name":"Manon Brunel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324524);
