INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-bao-tap', 'Điệp Viên Bão Táp', 'Stormbreaker', 'https://phimimg.com/upload/vod/20231111-1/cf8de16c604863f1e9a57bcea752fe0b.jpg', 'https://phimimg.com/upload/vod/20231111-1/5ea10f858214cf3385c0c6ca4cd73319.jpg', '<p>Alex Rider nghĩ rằng anh ta là một cậu học sinh bình thường, cho đến khi chú của anh ta bị giết. Anh ta phát hiện ra rằng chú của mình thực sự là gián điệp trong một nhiệm vụ, khi anh ta bị giết. Alex được tuyển dụng bởi Alan Blunt để tiếp tục nhiệm vụ. Anh ta được cử đến Cornwall để điều tra một hệ thống máy tính mới mà Darrius Sayle đã tạo ra. Anh ấy dự định cung cấp hệ thống máy tính mới cho mọi trường học trong cả nước, nhưng anh Blunt có những ý tưởng khác và Alex phải tìm ra nó là gì.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alex Pettyfer","avatar":""},{"name":"Sarah Bolger","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Stephen Fry","avatar":""},{"name":"Damian Lewis","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Sophie Okonedo","avatar":""},{"name":"Missi Pyle","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Alicia Silverstone","avatar":""},{"name":"Jimmy Carr","avatar":""},{"name":"Ashley Walters","avatar":""},{"name":"Morgan Walters","avatar":""},{"name":"Martin Herdman","avatar":""},{"name":"Scott Chisholm","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324524);
