INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-trom-ti-hon', 'Tên Trộm Tí Hon', 'Little Man', 'https://phimimg.com/upload/vod/20231111-1/5eef676539f71c02d8b27362d41f5bc1.jpg', 'https://phimimg.com/upload/vod/20231111-1/db02764b2b08668bfb4fdef45bb67395.jpg', '<p>Một người đàn ông muốn làm cha đến nỗi anh tin vào tất thảy mọi thứ, kể cả chuyện một tên trộm đào tẩu có gương mặt trẻ con là một đứa bé bị bỏ rơi.</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marlon Wayans","avatar":""},{"name":"Shawn Wayans","avatar":""},{"name":"Kerry Washington","avatar":""},{"name":"John Witherspoon","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Rob Schneider","avatar":""},{"name":"David Alan Grier","avatar":""},{"name":"Dave Sheridan","avatar":""},{"name":"Anthony Harrison","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"Brittany Daniel","avatar":""},{"name":"Fred Stoller","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Chazz Palminteri","avatar":""},{"name":"Anastacia","avatar":""},{"name":"Damie","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324524);
