INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tro-treu-cua-tien-hoa', 'Sự Trớ Trêu Của Tiến Hóa', 'Idiocracy', 'https://phimimg.com/upload/vod/20231111-1/af2098071e8d8ea5ea648b5c8ff1c1ad.jpg', 'https://phimimg.com/upload/vod/20231111-1/e88fd2f50d1c26e0b46552143dda21fe.jpg', '<p>Để kiểm tra Dự án ngủ đông con người tuyệt mật của mình, Lầu Năm Góc chọn những người Mỹ bình thường nhất mà họ có thể tìm thấy - một binh nhì và một gái điếm - và gửi họ đến năm 2505 sau một loạt sự kiện kỳ lạ. Nhưng khi đến nơi, họ thấy một nền văn minh ngu ngốc đến nỗi họ là những người thông minh nhất xung quanh.</p>', 'Full', 1, 'single', 'completed', 18, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Wilson","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Dax Shepard","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Anthony ''Citric'' Campos","avatar":""},{"name":"David Herman","avatar":""},{"name":"Sonny Castillo","avatar":""},{"name":"Kevin McAfee","avatar":""},{"name":"Robert Musgrave","avatar":""},{"name":"Michael McCafferty","avatar":""},{"name":"Christopher Ryan","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Heath Jones","avatar":""},{"name":"Eli Muñoz","avatar":""},{"name":"Patrick Fischler","avatar":""},{"name":"Darlene Hunt","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324524);
