INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-7-ten-khong-lo-trong-lau-dai-karakuri', 'Đảo Hải Tặc 7: Tên Khổng Lồ Trong Lâu Đài Karakuri', 'One Piece: Karakuri shiro no Mecha Kyohei', 'https://phimimg.com/upload/vod/20231111-1/36715c6c7718095c64923f0ee7111917.jpg', 'https://phimimg.com/upload/vod/20231111-1/55403f22575b8e95d33c6f2085b91d83.jpg', '<p>Băng Mũ Rơm đã vớt được hòm kho báu từ một con tàu chìm. Chiếc hòm được mở và bên trong chỉ có một bà lão đang trốn ở đó. Để được đưa về nhà, bà lão đã cho họ biết về chiếc vương miện vàng trên hòn đảo bà ta sống - Mecha Island. Khi đến nơi, tàu của họ đã bị chủ hòn đảo tấn công. Nhưng sau đó, người chủ đã nhờ hải tặc để khám phá bí mật của chiếc vương miện vàng. Chiếc vương miện này có phải là may mắn cho nhóm hải tặc Mũ Rơm hay không? Lời nguyền nào đang chờ đợi họ?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayumi Tanaka","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Kazue Ikura","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Goro Inagaki","avatar":""},{"name":"Koji Kato","avatar":""},{"name":"Keiichiro Yamamoto","avatar":""},{"name":"Hisako Kyoda","avatar":""},{"name":"Takeshi Aono","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324524);
