INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-pho-khoc-liet-giang-ho-gac-kiem', 'Con Phố Khốc Liệt / Giang Hồ Gác Kiếm', 'A Dirty Carnival', 'https://phimimg.com/upload/vod/20231111-1/c95f10b47a4277871590a77b23a47703.jpg', 'https://phimimg.com/upload/vod/20231111-1/e5e87a8e20eff60ace60d77daa0a5b8a.jpg', '<p>Một tên côn đồ nhỏ tuổi đi đòi nợ cho hội tam hoàng địa phương bị giằng xé giữa khát vọng phạm tội và sự tận tâm với gia đình.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Zo In-sung","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Namkoong Min","avatar":""},{"name":"Lee Bo-young","avatar":""},{"name":"Jin Goo","avatar":""},{"name":"Yoon Je-moon","avatar":""},{"name":"Eun-Sook Sunwoo","avatar":""},{"name":"Lee Jong-hyuk","avatar":""},{"name":"Cho Jin-woong","avatar":""},{"name":"Huh Yi-jae","avatar":""},{"name":"Lee Shin-seong","avatar":""},{"name":"Kwon Tae-won","avatar":""},{"name":"Kim Byung-choon","avatar":""},{"name":"Park Hyo-joon","avatar":""},{"name":"Park Min-gyu","avatar":""},{"name":"Park Hyeok-min","avatar":""},{"name":"Kim Su-nam","avatar":""},{"name":"Choi Jae-hwan","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324524);
