INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-pho-khoc-liet-giang-ho-gac-kiem', 'Con Phố Khốc Liệt / Giang Hồ Gác Kiếm', 'A Dirty Carnival', 'con phố khốc liệt / giang hồ gác kiếm a dirty carnival zo in-sung cheon ho-jin namkoong min lee bo-young jin goo yoon je-moon eun-sook sunwoo lee jong-hyuk cho jin-woong huh yi-jae lee shin-seong kwon tae-won kim byung-choon park hyo-joon park min-gyu park hyeok-min kim su-nam choi jae-hwan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-cuong-mau', 'Kim Cương Máu', 'Blood Diamond', 'https://phimimg.com/upload/vod/20231111-1/c33859da27377fdf42c75d4241022ffe.jpg', 'https://phimimg.com/upload/vod/20231111-1/84b57741e2e32cca8d56963be606f549.jpg', '<p>Giữa cuộc nội chiến nảy lửa bùng nổ năm 1999 ở Sierra Leone, một tên lính đánh thuê trở thành kẻ buôn lậu và một ngư dân bình thường ở vùng Mende cùng nhau tham gia thực hiện hai nhiệm vụ liều lĩnh: truy tìm viên kim cương hồng vô giá và giải cứu đứa con trai của tay ngư dân bị quân phiến loạn tàn bạo bắt đi lính khi chỉ là một đứa bé. Chúng lần lượt đi qua các vùng đất xinh đẹp, tàn phá, giết chóc, đổ máu và để lại những ký ức đầy ác mộng cho những đứa trẻ ấy. Phim là cuộc phiêu lưu gay cấn đầy cảm xúc, tính nhân bản sâu xắc xen lẫn những pha hành động thót tim, khiến người xem xúc động tận đáy lòng.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Kagiso Kuypers","avatar":""},{"name":"Arnold Vosloo","avatar":""},{"name":"Antony Coleman","avatar":""},{"name":"Benu Mabhena","avatar":""},{"name":"Anointing Lukola","avatar":""},{"name":"David Harewood","avatar":""},{"name":"Basil Wallace","avatar":""},{"name":"Jimi Mistry","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Marius Weyers","avatar":""},{"name":"Stephen Collins","avatar":""},{"name":"Ntare Guma Mbaho Mwine","avatar":""},{"name":"Ato Ess","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29