INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-chung-so-lay-vo', 'Hội Chứng Sợ Lấy Vợ', 'Failure to Launch', 'https://phimimg.com/upload/vod/20231109-1/9de5558a64e9d6fadaeb500dd1dad862.jpg', 'https://phimimg.com/upload/vod/20231109-1/cb1a5f5c7847b364f923acaa3cf03a85.jpg', '<p>Tripp, một người đàn ông hấp dẫn ở độ tuổi 30, vẫn đang sống với bố mẹ là Al và Sue. Những người bạn thân nhất của Tripp là Demo và Ace vẫn đang sống trong nhà của cha mẹ họ và có vẻ tự hào về điều đó. Tuy nhiên, Al và Sue không hài lòng và rất thích thú khi những người bạn có con trai trưởng thành mới chuyển đi xa nhà tiết lộ rằng họ đã thuê một chuyên gia để dàn xếp vấn đề và không thể vui hơn với kết quả này.</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew McConaughey","avatar":""},{"name":"Sarah Jessica Parker","avatar":""},{"name":"Zooey Deschanel","avatar":""},{"name":"Justin Bartha","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Terry Bradshaw","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Tyrel Jackson Williams","avatar":""},{"name":"Katheryn Winnick","avatar":""},{"name":"Patton Oswalt","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Stephen Tobolowsky","avatar":""},{"name":"Kate McGregor-Stewart","avatar":""},{"name":"Adam Alexi-Malle","avatar":""},{"name":"Gret","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324524);
