INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lau-dai-mua-he', 'Lâu Đài Mùa Hè', 'Summer Palace', 'https://phimimg.com/upload/vod/20231109-1/8aa9c64c05b983be6f53a82820773878.jpg', 'https://phimimg.com/upload/vod/20231109-1/8226e6112ac89cfe3c4e35c347638267.jpg', '<p>Cô gái nông thôn Yu Hong rời làng, gia đình và người yêu để đến Bắc Kinh học tập. Tại trường đại học, cô khám phá ra một thế giới mãnh liệt của tự do tình dục và niềm vui bị cấm đoán. Mê mẩn, cưỡng bách, cô yêu điên cuồng cậu sinh viên Zhou Wei. Bị thúc đẩy bởi những đam mê ám ảnh mà họ không thể hiểu và cũng không thể kiểm soát, mối quan hệ của họ trở thành một trong những trò chơi nguy hiểm - phản bội, buộc tội, khiêu khích - khi xung quanh họ, các bạn học của họ bắt đầu biểu tình, đòi dân chủ và tự do.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hao Lei","avatar":""},{"name":"Guo Xiaodong","avatar":""},{"name":"Hu Ling","avatar":""},{"name":"Zhang Xianmin","avatar":""},{"name":"Cui Lin","avatar":""},{"name":"Zeng Meihuizi","avatar":""},{"name":"Bai Xueyun","avatar":""},{"name":"Duan Yihong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324524);
