INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang', 'Nữ Hoàng', 'The Queen', 'https://phimimg.com/upload/vod/20231109-1/e0abf7908e13f1da39808ae1034fefe0.jpg', 'https://phimimg.com/upload/vod/20231109-1/78001ecfa1f284f7fd7d10d3b601d4bd.jpg', '<p>Nữ hoàng là một hậu trường thân mật nhìn thoáng qua về sự tương tác giữa HM Elizabeth II và Thủ tướng Tony Blair trong cuộc đấu tranh của họ, sau cái chết của Diana, để đạt được thỏa hiệp giữa bi kịch riêng tư đối với gia đình Hoàng gia và nhu cầu của công chúng đối với một màn trình diễn tang tóc công khai.</p>', 'Full', 1, 'single', 'completed', 18, 2006, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Helen Mirren","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Helen McCrory","avatar":""},{"name":"Alex Jennings","avatar":""},{"name":"Roger Allam","avatar":""},{"name":"Sylvia Syms","avatar":""},{"name":"Paul Barrett","avatar":""},{"name":"Tim McMullan","avatar":""},{"name":"Douglas Reith","avatar":""},{"name":"Mark Bazeley","avatar":""},{"name":"Robin Soans","avatar":""},{"name":"Lola Peploe","avatar":""},{"name":"Joyce Henderson","avatar":""},{"name":"Pat Laffan","avatar":""},{"name":"Amanda Hadingue","avatar":""},{"name":"John McGlynn","avatar":""},{"name":"Gray O&#039","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324524);
