INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('banh-my-5-mot-dam-khoa-than', 'Bánh Mỹ 5: Một Dặm Khỏa Thân', 'American Pie Presents: The Naked Mile', 'https://phimimg.com/upload/vod/20231110-1/466f6e75b7b27df0fce228798a7a35f7.jpg', 'https://phimimg.com/upload/vod/20231110-1/3db42895b9ead10987dab8a1b32078e0.jpg', '<p>Cũng mang họ Stifler nhưng không hiểu sao anh chàng Erik lại chẳng thừa hưởng được chút bản lĩnh nào từ các bậc cha chú và anh chị. Vốn không có máu ăn chơi như mọi người trong gia đình, Erik có nhiều khả năng sẽ phải kết thúc bậc học phổ thông mà vẫn chưa một lần vượt rào cùng bạn gái. Điều này hoàn toàn đi ngược lại truyền thống “vui hết mình” của dòng họ Stifler nên mọi người luôn nhìn Erik bằng ánh mắt xa lạ.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John White","avatar":""},{"name":"Jessy Schram","avatar":""},{"name":"Steve Talley","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Eugene Levy","avatar":""},{"name":"Ross Thomas","avatar":""},{"name":"Jake Siegel","avatar":""},{"name":"Jordan Prentice","avatar":""},{"name":"Maria Ricossa","avatar":""},{"name":"Candace Kroslak","avatar":""},{"name":"Mika Winkler","avatar":""},{"name":"Joe Bostick","avatar":""},{"name":"Alyssa Nicole Pallett","avatar":""},{"name":"Jessica Booker","avatar":""},{"name":"Michelle Cormier","avatar":""},{"name":"Stephany Sexton","avatar":""},{"name":"Bill","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324524);
