INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('banh-my-5-mot-dam-khoa-than', 'Bánh Mỹ 5: Một Dặm Khỏa Thân', 'American Pie Presents: The Naked Mile', 'bánh mỹ 5: một dặm khỏa thân american pie presents: the naked mile john white jessy schram steve talley christopher mcdonald eugene levy ross thomas jake siegel jordan prentice maria ricossa candace kroslak mika winkler joe bostick alyssa nicole pallett jessica booker michelle cormier stephany sexton bill ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-riu', 'Lưỡi Rìu', 'Hatchet', 'https://phimimg.com/upload/vod/20231109-1/df76d4f4088caed4c11c25e1ba42390d.jpg', 'https://phimimg.com/upload/vod/20231109-1/d6c5bb63ccd02cc05387f35300fb78fe.jpg', '<p>Hatchet (Lưỡi Rìu) là bộ phim kinh dị xoay quanh chuyến phiêu lưu của Ben cùng những người bạn của anh. Nhóm bạn trẻ cùng hướng dẫn viên Shawn bắt đầu tiến vào vùng đầm lầy, tương truyền là nơi trú ngụ của nhiều loài ma quỷ. Vừa đi, Shawn vừa kể cho đoàn khách nghe một truyền thuyết về Victor Crowley. Ngay từ khi chào đời, Victor đã không may mang trên người một dung mạo xấu xí hệt như quái thú. Do bị bọn trẻ hàng xóm khinh miệt và nhạo báng suốt nhiều năm liền, Victor dần dần bị khống chế bởi lòng thù hận của chính mình. Cho đến một ngày, hắn cầm trong tay một lưỡi rìu sáng loáng và bước ra khỏi khu đầm lầy…</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joel David Moore","avatar":""},{"name":"Amara Zaragoza","avatar":""},{"name":"Deon Richmond","avatar":""},{"name":"Kane Hodder","avatar":""},{"name":"Joleigh Fioravanti","avatar":""},{"name":"Mercedes McNab","avatar":""},{"name":"Joel Murray","avatar":""},{"name":"Parry Shen","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"Patrika Darbo","avatar":""},{"name":"Robert Englund","avatar":""},{"name":"Joshua Leonard","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"John Carl Buechler","avatar":""},{"name":"Rileah Vanderbilt","avatar":""},{"name":"Adam Weisman","avatar":""},{"name":"Adam","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324524);
