INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('barbie-12-nang-cong-chua-thich-khieu-vu', 'Barbie: 12 Nàng Công Chúa Thích Khiêu Vũ', 'Barbie in the 12 Dancing Princesses', 'https://phimimg.com/upload/vod/20231109-1/f547fac8bdf6266560f5ba7f79d19192.jpg', 'https://phimimg.com/upload/vod/20231109-1/75d7817e47709f246c563ac63994fa7c.jpg', '<p>Phim kể về 12 chị em - 12 nàng công chúa đều có chung sở thích là khiêu vũ. Vào ngày sinh nhật của 3 công chúa út, họ đã tìm ra một lối đi vào xứ sở diệu kì - nơi mọi điều ước đều thành sự thật. Họ còn phải cũng nhau chống lại Rowena - người đang rắp tâm chiếm ngai vàng của cha mình. 12 nàng tiên sẽ chống lại Rowena như thế nào và sẽ có những khó khăn gì, mời các bạn cùng theo dõi để biết kết quả cuối cùng của bộ phim này nhé!</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2006, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Kelly Sheridan","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Christopher Gaze","avatar":""},{"name":"Nicole Oliver","avatar":""},{"name":"Lalainia Lindbjerg","avatar":""},{"name":"Kathleen Barr","avatar":""},{"name":"Adrienne Carter","avatar":""},{"name":"Chantal Strand","avatar":""},{"name":"Britt McKillip","avatar":""},{"name":"Maddy Capozzi","avatar":""},{"name":"Ashleigh Ball","avatar":""},{"name":"Chiara Zanni","avatar":""},{"name":"Jennifer Copping","avatar":""},{"name":"Shawn Macdonald","avatar":""},{"name":"Garry Chalk","avatar":""},{"name":"Gabe Kh","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324524);
