INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-cuoi-cung', 'Kỳ Nghỉ Cuối Cùng', 'Last Holiday', 'https://phimimg.com/upload/vod/20231109-1/64a1ee9e1b310aafef93e5abc3ebca4c.jpg', 'https://phimimg.com/upload/vod/20231109-1/1bb35bb6116658d0c705f77472a61a6f.jpg', '<p>Kỳ Nghỉ Cuối Cùng - Last Holiday: Một ngày nọ, Georgia Byrd, cô nhân viên bán hàng nhút nhát ở New Orclean được thông báo đã mắc phải một căn bệnh nan y và chỉ còn sống được ba tuần. Còn quá nhiều việc muốn làm, Georgia quyết định rút toàn bộ khoản tiền tiết kiệm ở ngân hàng, đi chuyến du lịch đầu tiên và cũng là cuối cùng của mình.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Queen Latifah","avatar":""},{"name":"LL Cool J","avatar":""},{"name":"Timothy Hutton","avatar":""},{"name":"Alicia Witt","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Michael Nouri","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"Jane Adams","avatar":""},{"name":"Michel Estime","avatar":""},{"name":"Susan Kellermann","avatar":""},{"name":"Jascha Washington","avatar":""},{"name":"Matt Ross","avatar":""},{"name":"Ranjit Chowdhry","avatar":""},{"name":"Jaqueline Fleming","avatar":""},{"name":"Kendall Mosby","avatar":""},{"name":"Chloe Bailey","avatar":""},{"name":"Halle B","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
