INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('16-nga-re', '16 Ngã Rẽ', '16 Blocks', 'https://phimimg.com/upload/vod/20231109-1/be3cad4dbfaaf896e1494065a3534820.jpg', 'https://phimimg.com/upload/vod/20231109-1/fe8055c3760b162e12f6b17e2c21200d.jpg', '<p>Jack mệt mỏi sau một đêm dài tại sở cảnh sát. nhưng vẫn muốn nhận thêm một công việc tưởng chừng rất đơn giản, giải tên trộm vặt Eddie đến tòa án để làm nhân chứng trước 10 sáng. Khi tiếng súng đầu tiên nhắm vào Eddie, Jack hiểu rằng đây không phải là nhân vật bình thường. Nhóm người đang truy lùng Eddie chính là những đồng nghiệp cảnh sát. Những gì mà Eddie sắp khai cũng sẽ ảnh hưởng trực tiếp đến anh. Nhưng 2 con người ngẫu nhiêu trên cùng một chiến tuyến không chỉ có giây phút mong manh đó. Để đến tòa án. họ phải vượt qua tất cả 16 dãy phố. Giữa cái sống và cái chết, giữa nhiệm vụ và thoát tội, giữa áp lực công việc và cuộc sống bình lặng, viên cảnh sát đã chọn cho mình lối hành xử với triết lý sống: &quot;Con người có thể thay đổi được bản tính&quot;.</p>', 'Full', 1, 'single', 'completed', 16, 2006, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Yasiin Bey","avatar":""},{"name":"David Morse","avatar":""},{"name":"Jenna Stern","avatar":""},{"name":"Casey Sander","avatar":""},{"name":"Cylk Cozart","avatar":""},{"name":"David Zayas","avatar":""},{"name":"Robert Racki","avatar":""},{"name":"Patrick Garrow","avatar":""},{"name":"Sasha Roiz","avatar":""},{"name":"Conrad Pla","avatar":""},{"name":"Hechter Ubarry","avatar":""},{"name":"Richard Fitzpatrick","avatar":""},{"name":"Peter McRobbie","avatar":""},{"name":"Michael F. Keenan","avatar":""},{"name":"Robert Clohessy","avatar":""},{"name":"Jess Mal Gibbons","avatar":""},{"name":"Ti","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324524);
