INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-phong-vien-ky-quai', 'Tay phóng viên kỳ quái', 'Borat: Cultural Learnings of America for Make Benefit Glorious Nation of Kazakhstan', 'https://phimimg.com/upload/vod/20231108-1/6ed5a157ded46a80a230331a9a5b3abd.jpg', 'https://phimimg.com/upload/vod/20231108-1/174b04e1bb60f743be4261458ebf00c1.jpg', '<p>Nhà báo người Kazakhstan Borat Sagdiyev đến Mỹ để thực hiện một bộ phim tài liệu. Khi anh ta đi ngoằn ngoèo trên khắp đất nước, Borat gặp những người thật trong các tình huống thực tế với những hậu quả điên loạn. Hành vi ngang ngược của anh ta tạo ra những phản ứng mạnh mẽ xung quanh việc anh ta phơi bày những định kiến và đạo đức giả trong văn hóa Mỹ.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sacha Baron Cohen","avatar":""},{"name":"Ken Davitian","avatar":""},{"name":"Luenell","avatar":""},{"name":"Pamela Anderson","avatar":""},{"name":"Bob Barr","avatar":""},{"name":"Alan Keyes","avatar":""},{"name":"Carole De Saram","avatar":""},{"name":"Mitchell Falk","avatar":""},{"name":"David Corcoran","avatar":""},{"name":"Andre Darnell Myers","avatar":""},{"name":"Jean-Pierre Parent","avatar":""},{"name":"Chip Pickering","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324524);
