INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tay-phong-vien-ky-quai', 'Tay phóng viên kỳ quái', 'Borat: Cultural Learnings of America for Make Benefit Glorious Nation of Kazakhstan', 'tay phóng viên kỳ quái borat: cultural learnings of america for make benefit glorious nation of kazakhstan sacha baron cohen ken davitian luenell pamela anderson bob barr alan keyes carole de saram mitchell falk david corcoran andre darnell myers jean-pierre parent chip pickering ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('honey-clover', 'Honey & Clover', 'Honey & Clover', 'https://phimimg.com/upload/vod/20231113-1/3ea6a8ccb4dde67e01d3279f8e59f5ea.jpg', 'https://phimimg.com/upload/vod/20231113-1/229113f53b6d45abf603654f715c052a.jpg', '<p>Kiến trúc sư nhút nhát Takemoto, sinh viên gốm sứ ngậm nghiện Ayumi, Mayama cao cấp chăm chỉ, và nghệ thuật siêu cao cấp Madman Morita là bốn sinh viên tại một trường cao đẳng nghệ thuật tại Nhật Bản, mỗi người được giáo sư Hanamoto giảng dạy. Khi thần đồng nghệ thuật Hagumi, con gái của anh họ Hanamoto, đến trường, Takemoto rơi xuống ngay lập tức. Tuy nhiên, giáo sư Hanamoto nghi ngờ rằng Hagumi có thể mở lòng cho Morita nhanh hơn, khiến Takemoto tẩy trang để quyết định liệu anh ta có nên mang lại Morita hay không hoặc tiếp tục chiến đấu vì tình cảm của mình. Trong khi đó, Ayumi theo đuổi Mayama, người trông cậy ngay qua cô ấy vì đang tình yêu một cách ám ảnh với ông chủ của mình ... một người phụ nữ lớn tuổi, góa chồng.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sho Sakurai","avatar":""},{"name":"Yu Aoi","avatar":""},{"name":"Yûsuke Iseya","avatar":""},{"name":"Ryo Kase","avatar":""},{"name":"Megumi Seki","avatar":""},{"name":"Masato Sakai","avatar":""},{"name":"Naomi Nishida","avatar":""},{"name":"Gin Pun Chou","avatar":""},{"name":"Kenta Hamano","avatar":""},{"name":"Jun''ichi Haruta","avatar":""},{"name":"Keisuke Horibe","avatar":""},{"name":"Tetsuhiro Ikeda","avatar":""},{"name":"Kei Majima","avatar":""},{"name":"Tomu Miyazaki","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Yumi Shimizu","avatar":""},{"name":"Seiichi Tanabe","avatar":""},{"name":"Go Riju","avatar":""},{"name":"Nao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324524);
