INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-mien-tay', 'Sát Thủ Miền Tây', 'Seraphim Falls', 'https://phimimg.com/upload/vod/20231107-1/bcd5e0d872d33e1ad5ad33523da22a83.jpg', 'https://phimimg.com/upload/vod/20231107-1/a5d484f6a14a9c59b004086f30a63be2.jpg', '<p>Sát Thủ Miền Tây - Seraphim Falls là một bộ phim hành động phiêu lưu 2006 của đạo diễn Mỹ David Von Ancken. Vào những năm 1860, năm người đàn ông đã được băng qua 1/6 Nevada trong hơn 2 tuần. Bọn họ được Đại tá Morsman Carver (Liam Neeson) thuê để săn lùng Gideon. Lòng thù hận của quá lớn khiến cho những gì ở quá khứ không thể nào trôi đi trong Carver. Nhưng hạnh động trả thù đó có làm nguôi những nỗi đau trong cuộc nội chiến ở quá khứ? Liệu Gideon có ra sức chống trả lại kẻ đang ra sức giết mình?</p>', 'Full', 1, 'single', 'completed', 20, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Michael Wincott","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Ed Lauter","avatar":""},{"name":"Kevin J. O''Connor","avatar":""},{"name":"John Robinson","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Angie Harmon","avatar":""},{"name":"Tom Noonan","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Robert Baker","avatar":""},{"name":"James Jordan","avatar":""},{"name":"Nate Mooney","avatar":""},{"name":"Wes Studi","avatar":""},{"name":"Shannon Zeller","avatar":""},{"name":"Adon Cravens","avatar":""},{"name":"Ar","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
