INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-thu-mien-tay', 'Sát Thủ Miền Tây', 'Seraphim Falls', 'sát thủ miền tây seraphim falls liam neeson pierce brosnan michael wincott xander berkeley ed lauter kevin j. o''connor john robinson anjelica huston angie harmon tom noonan jimmi simpson robert baker james jordan nate mooney wes studi shannon zeller adon cravens ar ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-yeu', 'Khi Yêu', 'Heavenly Forest', 'https://phimimg.com/upload/vod/20231106-1/ca50a65af6a6ac424fe60e9540f7bf50.jpg', 'https://phimimg.com/upload/vod/20231106-1/8c6741c361af5747ffb0ba6efb51b744.jpg', '<p>Câu chuyện bắt đầu với Makoto Segawa, sinh viên năm nhất trường đại học Meikei. Vào ngày làm lễ khai giảng đại học, Makoto gặp một cô gái có khuôn mặt tươi tắn, kỳ quặc tên là Shizuru. Makoto có một mặc cảm khiến anh ấy ngại tiếp xúc với người khác, nhưng cô ấy đã thành công trong việc khiến anh ấy cởi mở với cô ấy một cách tự nhiên. Tất cả những gì Shizuru muốn là được ở bên Makoto, vì vậy cô ấy cũng cầm theo một chiếc máy ảnh. Cả hai dành cả ngày cùng nhau chụp ảnh trong khu rừng phía sau khuôn viên trường. Tuy nhiên, Makoto lại có tình cảm với một học sinh khác tên Miyuki. Shizuru quyết định rằng nếu Makoto thích Miyuki, cô ấy cũng muốn thích cô ấy. Cô ấy muốn thích mọi thứ mà anh ấy làm. Một ngày nọ, cô ấy nói với Makoto rằng cô ấy muốn chụp một bức ảnh họ hôn nhau trong rừng để làm quà cho &#39;sinh nhật của cô ấy&#39;. Anh ấy bắt buộc vì lợi ích của cô ấy, và họ hôn nhau trong rừng.</p>', 'Full', 1, 'single', 'completed', 20, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hiroshi Tamaki","avatar":""},{"name":"Aoi Miyazaki","avatar":""},{"name":"Meisa Kuroki","avatar":""},{"name":"Munetaka Aoki","avatar":""},{"name":"Keisuke Koide","avatar":""},{"name":"Yûya Ogawa","avatar":""},{"name":"Asae Oonishi","avatar":""},{"name":"Misa Uehara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324524);
