INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-babel', 'Tháp Babel', 'Babel', 'https://phimimg.com/upload/vod/20231106-1/f1dd2964ac355192a5aa9fd9edaf0714.jpg', 'https://phimimg.com/upload/vod/20231106-1/3c60b8532783261e802cf8fd2e863746.jpg', '<p>Lấy cảm hứng từ câu chuyện về tháp Babel trong Kinh thánh Cựu ước, kịch tác gia Guillermo Arriaga và đạo diễn Alejandro Gonzalez Inarritu đã làm ra Babel. Babel là tên một ngọn tháp được xây bởi sự đồng tâm hiệp lực của loài người nhưng nó cao chạm đến tận thiên đường đã khiến Thượng đế nổi giận và làm cho loài người nói những thứ tiếng khác nhau, chính vì thế không còn ai hiểu ai và tháp Babel không bao giờ hoàn thành được. Babel trở thành từ để ám chỉ sự khác biệt về ngôn ngữ của con người, và đó cũng chính là ý tưởng chính của bộ phim.</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Rinko Kikuchi","avatar":""},{"name":"Adriana Barraza","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Satoshi Nikaido","avatar":""},{"name":"Said Tarchani","avatar":""},{"name":"Boubker Ait El Caid","avatar":""},{"name":"Gael García Bernal","avatar":""},{"name":"Nathan Gamble","avatar":""},{"name":"Elle Fanning","avatar":""},{"name":"Mohamed Akhzam","avatar":""},{"name":"Yuko Murata","avatar":""},{"name":"Koji Yakusho","avatar":""},{"name":"Mustapha Rachidi","avatar":""},{"name":"Harriet Walter","avatar":""},{"name":"Michael Maloney","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
