INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tra-thu-ten-sat-gai', 'Trả Thù Tên Sát Gái', 'John Tucker Must Die', 'https://phimimg.com/upload/vod/20231103-1/e08855c1b544453bb46c2e863f11be11.jpg', 'https://phimimg.com/upload/vod/20231103-1/1169111d40cd1cfa48bb74a491bfafd9.jpg', '<p>Sau khi phát hiện ra tất cả họ đang hẹn hò với cùng một chàng trai, ba sinh viên nổi tiếng từ các nhóm khác nhau đã cùng nhau trả thù, vì vậy họ tranh thủ sự giúp đỡ của một cô gái mới trong thị trấn và âm mưu làm tan nát trái tim của anh ta, đồng thời hủy hoại danh tiếng của anh ta.</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jesse Metcalfe","avatar":""},{"name":"Brittany Snow","avatar":""},{"name":"Ashanti","avatar":""},{"name":"Sophia Bush","avatar":""},{"name":"Arielle Kebbel","avatar":""},{"name":"Penn Badgley","avatar":""},{"name":"Jenny McCarthy-Wahlberg","avatar":""},{"name":"Fatso-Fasano","avatar":""},{"name":"Patricia Drake","avatar":""},{"name":"Taylor Kitsch","avatar":""},{"name":"Amber Borycki","avatar":""},{"name":"Meghan Ory","avatar":""},{"name":"Nicole LaPlaca","avatar":""},{"name":"Nicole Fraissinet","avatar":""},{"name":"Samantha McLeod","avatar":""},{"name":"Woody Jeffreys","avatar":""},{"name":"Kevin M","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324524);
