INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-cho-xu', 'Điệp Vụ Chó Xù', 'The Shaggy Dog', 'https://phimimg.com/upload/vod/20231102-1/1161f64d860158717f8d19c366682ac5.jpg', 'https://phimimg.com/upload/vod/20231102-1/97f915df959a0ed036f9fd2d20b2a8a8.jpg', '<p>Ông chủ Strictland của tập đoàn Grant phát hiện ra một chú chó có tuổi thọ kỳ diệu hơn 300 năm mà vẫn sống khỏe mạnh, thì ra do cấu trúc gien của nó đã bị đảo lộn và bảy năm bình thường chỉ ngắn bằng một năm của chó. Không thể bỏ lỡ một cơ hội ngàn vàng nghiên cứu quy luật gien của chú chó và vận dụng cho con người, tập đoàn Grant tìm mọi thủ đoạn để sở hữu được con vật đặc biệt này. Nhưng chú chó khôn ngoan đã tự tìm cho mình một ông chủ tốt bụng hơn, đó là luật sư đang nổi đình nổi đám Dave Douglas và trở thành con vật nuôi Shaggy ngoan ngoãn...</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tim Allen","avatar":""},{"name":"Kristin Davis","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Spencer Breslin","avatar":""},{"name":"Robert Downey Jr.","avatar":""},{"name":"Zena Grey","avatar":""},{"name":"Joshua Leonard","avatar":""},{"name":"Jane Curtin","avatar":""},{"name":"Annabelle Gurwitch","avatar":""},{"name":"Jarrad Paul","avatar":""},{"name":"Bess Wohl","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Shawn Pyfrom","avatar":""},{"name":"Joel David Moore","avatar":""},{"name":"Kevin Cooney","avatar":""},{"name":"Craig Kilborn","avatar":""},{"name":"Jeanette Brox","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324524);
