INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diep-vu-cho-xu', 'Điệp Vụ Chó Xù', 'The Shaggy Dog', 'điệp vụ chó xù the shaggy dog tim allen kristin davis danny glover spencer breslin robert downey jr. zena grey joshua leonard jane curtin annabelle gurwitch jarrad paul bess wohl philip baker hall shawn pyfrom joel david moore kevin cooney craig kilborn jeanette brox ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuop-bien-vung-caribbean-chiec-ruong-tu-than', 'Cướp Biển Vùng Caribbean: Chiếc Rương Tử Thần', 'Pirates of the Caribbean: Dead Man''s Chest', 'https://phimimg.com/upload/vod/20231102-1/1a717a73d2a10c4c26edefd5a4bfdfdf.jpg', 'https://phimimg.com/upload/vod/20231102-1/8a3ffed4ba581125318ef8466101c8f9.jpg', '<p>Cuối cùng sau nhiều nỗ lực Jack Sparrow đã chiếm lại đuợc con tàu huyền thoại Ngọc Trai Đen. Tuy nhiên, để giành được Ngọc Trai Đen, Jack đã gây thù kết oán với Davy Jones (thuyền trưởng con tàu ma Flying Dutchman). Để chiến thắng Davy chỉ còn cách tìm được chiếc rương tử thần và Jack – Will – Elizabeth lại dấn thân vào cuộc phiêu lưu mới… Hình ảnh kì dị nhưng khá vui nhộn đã trở thành thương hiệu cho các phim do Walt Disney sản xuất. So với phần I phần II được lồng ghép thêm nhiều tình huống hài hước hơn. Các đại cảnh lớn được thiết kế công phu hoành tráng mang tới dấu ấn riêng.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Jack Davenport","avatar":""},{"name":"Kevin McNally","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Lee Arenberg","avatar":""},{"name":"Mackenzie Crook","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"David Bailie","avatar":""},{"name":"Martin Klebba","avatar":""},{"name":"David Schofield","avatar":""},{"name":"Alex Norton","avatar":""},{"name":"Dermot Keane","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324524);
