INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-nham-mafia-3', 'Cưới Nhầm Mafia 3', 'Marrying The Mafia 3', 'https://phimimg.com/upload/vod/20231102-1/949301713a504706836360c24867d370.jpg', 'https://phimimg.com/upload/vod/20231102-1/8427a7e53b5cedcdd7560781ba9ca736.jpg', '<p>Giã từ sự nghiệp Mafia, gia đình &quot;bà trùm&quot; Hong quyết định dấn thân vào kinh doanh thực phẩm với bí kíp kim chi gia truyền, chẳng lâu sau, gia đình bà thành công rực rỡ, nhà nhà ăn kim chi, người người ăn kim chi do công ty bà sản xuất. Chính lúc này, gã cảnh sát tha hóa Bong, kẻ vẫn ấm ức vì chuyện bị đẩy vào tù thì ít mà do mất tình yêu thì nhiều, đã ra tù và cấu kết với các lọan đảng Mafia còn lại nhằm hãm hại gia đình &quot;cựu Mafia&quot; nhưng hắn nào đâu biết rằng, một mình hắn sao chống lại được cả 1 đại gia đình đoàn kết một lòng....</p>', 'Full', 1, 'single', 'completed', 17, 2006, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Shin Hyun-joon","avatar":""},{"name":"Kim Won-hee","avatar":""},{"name":"Kim Soo-mi","avatar":""},{"name":"Tak Jae-hoon","avatar":""},{"name":"Lim Hyung-jun","avatar":""},{"name":"Gong Hyung-jin","avatar":""},{"name":"Shin Yi","avatar":""},{"name":"Kim Yong-geon","avatar":""},{"name":"Jeong Jun-ha","avatar":""},{"name":"Kim Hae-gon","avatar":""},{"name":"Jeong Bong-yeon","avatar":""},{"name":"Jang Hee-jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324524);
