INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-thuat-gia-tai-ba', 'Ảo Thuật Gia Tài Ba', 'The Illusionist', 'https://phimimg.com/upload/vod/20231101-1/7f3b2488de414175f6f4763e6de0a5ad.jpg', 'https://phimimg.com/upload/vod/20231101-1/e5d545d3951a07c6144af0019f95a22e.jpg', '<p>Vào thập niên 90, ở thành Vienna, Eisenheim vốn là một nhà ảo thuật tài ba được công chúng ngưỡng mộ. Anh đem lòng yêu Sophie, cô bạn nhỏ từ thời thơ ấu, nhưng lại bị ngăn cản bởi địa vị xã hội của hai người quá chênh lệch. Khi Sophie được gả cho hoàng tử, Eisenheim sử dụng ma thuật của mình để tìm cách cướp cô lại và gây nên sự chao đảo trong hoàng gia.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Edward Norton","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Jessica Biel","avatar":""},{"name":"Rufus Sewell","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Eleanor Tomlinson","avatar":""},{"name":"Jake Wood","avatar":""},{"name":"Tom Fisher","avatar":""},{"name":"Karl Johnson","avatar":""},{"name":"Vincent Franklin","avatar":""},{"name":"Nicholas Blane","avatar":""},{"name":"Philip McGough","avatar":""},{"name":"Erich Redman","avatar":""},{"name":"Michael Carter","avatar":""},{"name":"Andreas Grothusen","avatar":""},{"name":"Brian","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324524);
