INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-huong-cau-chuyen-ke-sat-nhan', 'Mùi Hương: Câu Chuyện Kẻ Sát Nhân', 'Perfume: The Story of a Murderer', 'https://phimimg.com/upload/vod/20231101-1/2a4247fb369e3e0634396b92f5527bc9.jpg', 'https://phimimg.com/upload/vod/20231101-1/25cbef67bbe896b6558941093c6b3c69.jpg', '<p>Có khứu giác nhạy bén bẩm sinh, Jean-Baptiste lại làm những việc xấu để tạo ra loại nước hoa mang mùi hương tinh túy của người phụ nữ.</p>', 'Full', 1, 'single', 'completed', 18, 2006, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Ben Whishaw","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Rachel Hurd-Wood","avatar":""},{"name":"Dustin Hoffman","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Karoline Herfurth","avatar":""},{"name":"David Calder","avatar":""},{"name":"Simon Chandler","avatar":""},{"name":"Sian Thomas","avatar":""},{"name":"Jessica Schwarz","avatar":""},{"name":"Corinna Harfouch","avatar":""},{"name":"Paul Berrondo","avatar":""},{"name":"Timothy Davies","avatar":""},{"name":"Sam Douglas","avatar":""},{"name":"Harris Gordon","avatar":""},{"name":"Sara Forestier","avatar":""},{"name":"Joanna Grif","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
