INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mui-huong-cau-chuyen-ke-sat-nhan', 'Mùi Hương: Câu Chuyện Kẻ Sát Nhân', 'Perfume: The Story of a Murderer', 'mùi hương: câu chuyện kẻ sát nhân perfume: the story of a murderer ben whishaw alan rickman rachel hurd-wood dustin hoffman john hurt karoline herfurth david calder simon chandler sian thomas jessica schwarz corinna harfouch paul berrondo timothy davies sam douglas harris gordon sara forestier joanna grif ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-phap-mac-cong', 'Binh pháp Mặc công', 'Battle of the Warriors', 'https://phimimg.com/upload/vod/20231101-1/1a2ffa12f6be19527fc6b75c2d00e40b.jpg', 'https://phimimg.com/upload/vod/20231101-1/d6837ce481270ae7a8c1717292fe259a.jpg', '<p>Binh Pháp Mặc Công lấy bối cảnh năm 370 trước Công Nguyên. Lúc này nước Triệu muốn khởi binh phạt nước Yên. Và muốn diệt được nước Yên, nước Triệu phải thâu tóm được nước Lương, một nước nhỏ cỡ vài trăm dặm án ngữ cửa ngõ vào Yên. Nhưng Lương vương không hề biết đại họa sắp giáng xuống đầu mình mà suốt ngày chỉ đam mê tửu sắc, quần thần khiếp hãi nhu nhược. Vì vậy, vua tôi bàn tới bàn lui định dâng thành là kế thượng sách, thà làm chư hầu dưới trướng Triệu vương còn hơn thành tan nước mất. Nhưng có một người quyết không khuất phục, không để dân nước Lương trở thành lưu dân, nô lệ của nước Triệu. Đó là Cổ Lý tướng quân đa mưu túc trí, học trò của Mặc Tử lừng danh Chiến quốc xưa. Anh đã lãnh đạo quân Lương chiến đấu đến hơi thở cuối cùng...</p>', 'Full', 1, 'single', 'completed', 19, 2006, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Ahn Sung-ki","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Choi Si-won","avatar":""},{"name":"Zhiwen Wang","avatar":""},{"name":"Chin Siu-ho","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Nicky Wu","avatar":""},{"name":"Sammy Hung","avatar":""},{"name":"Zhou Bo","avatar":""},{"name":"Gao Shan","avatar":""},{"name":"Lin Yongjian","avatar":""},{"name":"Zhang Jian","avatar":""},{"name":"Zhang Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324524);
