INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('binh-phap-mac-cong', 'Binh pháp Mặc công', 'Battle of the Warriors', 'binh pháp mặc công battle of the warriors andy lau ahn sung-ki fan bingbing choi si-won zhiwen wang chin siu-ho wu ma nicky wu sammy hung zhou bo gao shan lin yongjian zhang jian zhang li ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-la-thu-tu-iwo-jima', 'Những Lá Thư Từ Iwo Jima', 'Letters from Iwo Jima', 'https://phimimg.com/upload/vod/20231101-1/6bc3c1f1dc039317be72454a76d3d79f.jpg', 'https://phimimg.com/upload/vod/20231101-1/a2baae383af1b7ff56b132c2cefaef42.jpg', '<p>Ở Iwo Jima, hàng trăm lá thư của binh lính Nhật bị chôn vùi dưới đống đổ nát, để rồi 60 năm sau, giở các trang thư, người ta đọc được những câu chuyện xúc động về họ. Đó là thư của Saigo gửi cho vợ và con gái, là thư của Trung úy Nishi gửi cho người thân, là thư của Shimizu gửi cho mẹ, là thư của chỉ huy Kuribayashi gửi cho vợ và con trai. Letters from Iwo Jima được quay cùng thời gian với Flags Of Our Fathers - một tác phẩm điện ảnh khác cũng về cuộc chiến ở Iwo Jima và cũng là của đạo diễn Clint Eastwood. Nếu như trong Flags Of Our Fathers, Eastwood mô tả trận đánh với góc nhìn từ phía người Mỹ, thì với Letters from Iwo Jima, ông kể lại cuộc chiến này với góc nhìn từ phía người lính Nhật. Ông đã vẽ nên bức chân dung toàn cảnh cuộc chiến được nhìn từ hai phía, để thấy rằng chiến tranh, dù thắng hay thua, thì cũng đều là sự mất mát. Và chiến tranh, chẳng đem lại điều gì ngoài Máu, Nước mắt, Mất mát và Những cuộc chia ly mãi mãi.</p>', 'Full', 1, 'single', 'completed', 17, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ken Watanabe","avatar":""},{"name":"Kazunari Ninomiya","avatar":""},{"name":"Tsuyoshi Ihara","avatar":""},{"name":"Ryo Kase","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Hiroshi Watanabe","avatar":""},{"name":"Takumi Bando","avatar":""},{"name":"Yuki Matsuzaki","avatar":""},{"name":"Takashi Yamaguchi","avatar":""},{"name":"Eijiro Ozaki","avatar":""},{"name":"Nae Yuuki","avatar":""},{"name":"Nobumasa Sakagami","avatar":""},{"name":"Lucas Elliot Eberl","avatar":""},{"name":"Sonny Saito","avatar":""},{"name":"Steve Santa Sekiyoshi","avatar":""},{"name":"Hiro Abe","avatar":""},{"name":"Tos","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324524);
