INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-la-thu-tu-iwo-jima', 'Những Lá Thư Từ Iwo Jima', 'Letters from Iwo Jima', 'những lá thư từ iwo jima letters from iwo jima ken watanabe kazunari ninomiya tsuyoshi ihara ryo kase shido nakamura hiroshi watanabe takumi bando yuki matsuzaki takashi yamaguchi eijiro ozaki nae yuuki nobumasa sakagami lucas elliot eberl sonny saito steve santa sekiyoshi hiro abe tos ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('den-va-trang', 'Đen Và Trắng', 'Tekkonkinkreet', 'https://phimimg.com/upload/vod/20231101-1/42324436d9086d516b118b0387b073a8.jpg', 'https://phimimg.com/upload/vod/20231101-1/2301a360dae5ee8bfeb6ddb5ffeda196.jpg', '<p>Đen Và Trắng - Tekkonkinkreet (2006): Anh em Kuro (nghĩa là màu đen) và Shiro (nghĩa là màu trắng) với tên gọi &quot;Mèo&quot; tuy chỉ là hai đứa trẻ mồ côi nhưng lại rất ranh mãnh, chúng thống trị thành phố Châu Báu. Kuro và Shiro tính tình cũng như tên của chúng - Kuro không ngại dùng bạo lực để bảo vệ thành phố &quot;của mình&quot;, Shiro ngây thơ và trong sáng như một đóa hoa sen giữa bùn lầy. Bọn yakuza do Suzuki (từng là cựu cảnh sát, nickname là &quot;Chuột&quot;) dẫn đầu trở về muốn đoạt lại quyền kiểm soát thành phố. Qua những tranh chấp, dần dần cả Kuro/Shiro (Mèo) và bọn người của Suzuki (Chuột) mới nhận ra kẻ thù chung lớn nhất của họ là những người ngoại quốc với ý đồ biến thành phố thành công viên giải trí cho trẻ em...</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazunari Ninomiya","avatar":""},{"name":"Yûsuke Iseya","avatar":""},{"name":"Yu Aoi","avatar":""},{"name":"Kankuro Kudo","avatar":""},{"name":"Min Tanaka","avatar":""},{"name":"Rokuro Naya","avatar":""},{"name":"Tomomichi Nishimura","avatar":""},{"name":"Mugihito","avatar":""},{"name":"Nao Omori","avatar":""},{"name":"Yoshinori Okada","avatar":""},{"name":"Kazuko Kurosawa","avatar":""},{"name":"Tomoko Murakami","avatar":""},{"name":"Miyuki Oshima","avatar":""},{"name":"Yūki Tamaki","avatar":""},{"name":"Mayumi Yamaguchi","avatar":""},{"name":"Harumi Asai","avatar":""},{"name":"Atsushi Imaizumi","avatar":""},{"name":"Bryan","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324524);
