INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('den-va-trang', 'Đen Và Trắng', 'Tekkonkinkreet', 'đen và trắng tekkonkinkreet kazunari ninomiya yûsuke iseya yu aoi kankuro kudo min tanaka rokuro naya tomomichi nishimura mugihito nao omori yoshinori okada kazuko kurosawa tomoko murakami miyuki oshima yūki tamaki mayumi yamaguchi harumi asai atsushi imaizumi bryan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-noi-voi-ai-ca', 'Đừng Nói Với Ai Cả', 'Tell No One', 'https://phimimg.com/upload/vod/20231101-1/d3448cf00f18b8ed6b0f61a43d84627b.jpg', 'https://phimimg.com/upload/vod/20231101-1/dc877fdfec46aed79b6443206c2404e8.jpg', '<p>Bác sĩ Alex Beck vẫn còn suy sụp sau cái chết của vợ mình 8 năm về trước. Một hôm anh nhận được một email nặc danh, trong đó đường dẫn (link) đến một video trực tiếp. Anh nhận ra khuôn mặt quen thuộc giữa đám đông trong đoạn video, đó chính là Margot, vợ của anh. Có phải cô còn sống? Và tại sao cô lại bảo anh đừng nói cho ai biết?</p>', 'Full', 1, 'single', 'completed', 19, 2006, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"François Cluzet","avatar":""},{"name":"Marie-Josée Croze","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"François Berléand","avatar":""},{"name":"André Dussollier","avatar":""},{"name":"Marina Hands","avatar":""},{"name":"Jean Rochefort","avatar":""},{"name":"Guillaume Canet","avatar":""},{"name":"Olivier Marchal","avatar":""},{"name":"Florence Thomassin","avatar":""},{"name":"Philippe Lefebvre","avatar":""},{"name":"Gilles Lellouche","avatar":""},{"name":"Nathalie Baye","avatar":""},{"name":"Dorothée Brière","avatar":""},{"name":"Brigitt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324524);
