INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-co-gai-va-buc-tuong-', 'Chàng Trai Cô Gái Và Bức Tường', 'Man, Woman & the Wall', 'https://phimimg.com/upload/vod/20231031-1/bad6abcfb32f39085ec27c171d127496.jpg', 'https://phimimg.com/upload/vod/20231031-1/be1b1bb951a75e87ec1c40b90cab8fc9.jpg', '<p>Khi Ryo, một phóng viên tạp chí trẻ, chuyển đến một căn hộ mới, anh được chào đón bởi những âm thanh say đắm của cô hàng xóm xinh đẹp đáng kinh ngạc Satsuki. Nhận ra bức tường ngăn cách căn hộ của họ mỏng như tờ giấy, nhà báo bị quyến rũ bắt đầu nghe lén mọi chi tiết về cuộc sống của cô gái hàng xóm: những cuộc trò chuyện của cô ấy, bồn tắm bong bóng của cô ấy... tiếng khóc khó thở của cô ấy.</p>', 'Full', 1, 'single', 'completed', 18, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sora Aoi","avatar":""},{"name":"Shou Nishino","avatar":""},{"name":"Keita Ôno","avatar":""},{"name":"Hiroto Kato","avatar":""},{"name":"Takashi Oda","avatar":""},{"name":"Mutsuo Yoshioka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324524);
