INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naruto-nhung-linh-gac-cua-nguyet-quoc', 'Naruto: Những Lính Gác Của Nguyệt Quốc', 'Naruto the Movie: Guardians of the Crescent Moon Kingdom', 'https://phimimg.com/upload/vod/20231029-1/cc41bea78d11fb4a81cb4c019eb85fc4.jpg', 'https://phimimg.com/upload/vod/20231029-1/9794e1bf2dce6913b4483993d775dc4d.jpg', '<p>Câu chuyện bắt đầu từ việc bộ bốn Naruto, Sakura, Rock Lee và Kakashi nhận nhiệm vụ bảo vệ vị hoàng tử béo hay ham chơi Michiru và cậu con trai với cặp kính cận to Hikaru bắn mũi tên đầu cao su vào băng bảo vệ trán của Naruto và cho rằng những Ninja này thật vô dụng. Theo lời của Tsunade, đây là một nơi du lịch khá nổi tiếng với hòn đảo hình mặt trăng liềm cùng với biển đẹp luôn khiến bà bị cuốn hút bởi nó và rất mong một ngày nào đó sẽ được đến đây. Bộ bốn này phải chống lại bọn cướp tấn công những du khách theo cảnh báo của Tsunade. Ban đêm khi hai bố con Michiru ăn uống sung sướng mà cả bốn phải ăn mì ở ngoài, chưa kể cơn rét vào đêm khuya khoắt ...</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2006, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Junko Takeuchi","avatar":""},{"name":"Chie Nakamura","avatar":""},{"name":"Yōichi Masukawa","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Kyousuke Ikeda","avatar":""},{"name":"Rokuro Naya","avatar":""},{"name":"Marika Hayashi","avatar":""},{"name":"Tomomichi Nishimura","avatar":""},{"name":"Kenji Hamada","avatar":""},{"name":"Umeji Sasaki","avatar":""},{"name":"Masashi Sugawara","avatar":""},{"name":"Haruhi Nanao","avatar":""},{"name":"Hisao Egawa","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2