INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mang-nhen-cua-charlotte', 'Mạng Nhện Của Charlotte', 'Charlotte''s Web', 'https://phimimg.com/upload/vod/20231029-1/b0b246e808adcaba7227aef4921b8ba7.jpg', 'https://phimimg.com/upload/vod/20231029-1/509dcf80db97d82fed19c4b502cb9ba8.jpg', '<p>Những lễ hội của mùa cuối năm sắp đến và điều này làm chú lợn Wilbur rất sợ hãi vì điều đó đồng nghĩa với nguy cơ Wilbur phải trở thành bữa ăn cho gia đình nhà nông Zuckerman. Lo sợ phải chết Wilbur đã nhờ đến sự giúp đỡ của chú nhện Charlotte và cô bé Fern để tìm cách trốn thoát mối nguy này.</p>', 'Full', 1, 'single', 'completed', 16, 2006, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Dakota Fanning","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Oprah Winfrey","avatar":""},{"name":"Cedric the Entertainer","avatar":""},{"name":"Reba McEntire","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Robert Redford","avatar":""},{"name":"Thomas Haden Church","avatar":""},{"name":"André 3000","avatar":""},{"name":"Dominic Scott Kay","avatar":""},{"name":"Sam Shepard","avatar":""},{"name":"Abraham Benrubi","avatar":""},{"name":"Kevin Anderson","avatar":""},{"name":"Essie Davis","avatar":""},{"name":"Si","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324524);
