INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-than-tien-barbie-xu-so-mermaidia', 'Chuyện Thần Tiên Barbie: Xứ Sở Mermaidia', 'Barbie Fairytopia: Mermaidia', 'https://phimimg.com/upload/vod/20231026-1/3fc41b3c8527e980e8229837dfaa66de.jpg', 'https://phimimg.com/upload/vod/20231026-1/ca40edfd0d84940386a514d7452222f3.jpg', '<p>Trong phần hoạt hình tiếp theo của Fairytopia, Elina nhờ đến sự giúp đỡ của nàng tiên cá Nori để cứu bạn mình là Nalu, một hoàng tử người cá bị Laverna độc ác bắt giữ.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kelly Sheridan","avatar":""},{"name":"Lee Tockar","avatar":""},{"name":"Christopher Gaze","avatar":""},{"name":"Kathleen Barr","avatar":""},{"name":"Chiara Zanni","avatar":""},{"name":"Andrea Libman","avatar":""},{"name":"Brittney Wilson","avatar":""},{"name":"Pam Hyatt","avatar":""},{"name":"Tabitha St. Germain","avatar":""},{"name":"Venus Terzo","avatar":""},{"name":"Blu Mankuma","avatar":""},{"name":"Alessandro Juliani","avatar":""},{"name":"Nicole Oliver","avatar":""},{"name":"Teryl Rothery","avatar":""},{"name":"Raphael Wagner","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324524);
