INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-duong-pho', 'Vũ Điệu Đường Phố', 'Step Up', 'https://phimimg.com/upload/vod/20231029-1/696f56f230b1b453266796c5bd95ded6.jpg', 'https://phimimg.com/upload/vod/20231029-1/e14f2fb07a6f0140027cd7f76438c1e5.jpg', '<p>Tyler vốn là một chàng trai trẻ mang đầy tính cách nổi loạn ở vùng Baltimore. Ngược lại với anh là Nora, một cô gái học khiêu vũ đang hy vọng sẽ đậu vào trường nghệ thuật Maryland nổi tiếng và điều Nora cần là một bạn nhảy giỏi. &nbsp;Khi hai người họ gặp nhau, Tyler nhận ra rằng đây chính là cơ hội để anh thoát khỏi những rắc rối và bắt đầu lại cuộc sống cho mình.</p>', 'Full', 1, 'single', 'completed', 18, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Channing Tatum","avatar":""},{"name":"Jenna Dewan","avatar":""},{"name":"Damaine Radcliff","avatar":""},{"name":"Rachel Griffiths","avatar":""},{"name":"De''Shawn Washington","avatar":""},{"name":"Alyson Stoner","avatar":""},{"name":"Drew Sidora","avatar":""},{"name":"Josh Henderson","avatar":""},{"name":"Mario Barrett","avatar":""},{"name":"Tim Lacatena","avatar":""},{"name":"Deirdre Lovejoy","avatar":""},{"name":"Heavy D","avatar":""},{"name":"Jane Beard","avatar":""},{"name":"Richard Pelzman","avatar":""},{"name":"Carlyncia S. Peck","avatar":""},{"name":"Ryan Sands","avatar":""},{"name":"DeLon","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324524);
