INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arthur-va-nhung-nguoi-ban-vo-hinh', 'Arthur và Những Người Bạn Vô Hình', 'Arthur and the Invisibles', 'https://phimimg.com/upload/vod/20231030-1/0bd0ff852d44c224678f4dee935b21d0.jpg', 'https://phimimg.com/upload/vod/20231030-1/c46283e1c6fdcd2fb4ca3997bc5a28e2.jpg', '<p>Arthur là một cậu bé mười tuổi mạnh mẽ, cha mẹ đi tìm việc làm, người ông lập dị đã mất tích vài năm và sống với bà ngoại trong một ngôi nhà nông thôn, trong hai ngày nữa, sẽ bị thu hồi, phá bỏ và biến thành một khu chung cư trừ khi ông nội của Arthur quay lại ký một số giấy tờ và trả hết nợ cho gia đình. Arthur phát hiện ra rằng chìa khóa thành công nằm ở việc anh đến vùng đất của Minimoys, những sinh vật không lớn hơn một chiếc răng, mà ông của anh đã giúp chuyển đến khu vườn của họ. Đâu đó trong số đó còn ẩn giấu một đống hồng ngọc. Liệu Arthur có thể có trái tim dũng cảm và cứu được thế giới? Sự lãng mạn cũng vẫy gọi và một nhân vật phản diện đang ẩn nấp.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2006, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Freddie Highmore","avatar":""},{"name":"Madonna","avatar":""},{"name":"Mia Farrow","avatar":""},{"name":"Jimmy Fallon","avatar":""},{"name":"David Bowie","avatar":""},{"name":"Doug Rand","avatar":""},{"name":"Penny Balfour","avatar":""},{"name":"Ron Crawford","avatar":""},{"name":"David Suchet","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Adam LeFevre","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Snoop Dogg","avatar":""},{"name":"Jean Bejote Njamba","avatar":""},{"name":"Lee Delong","avatar":""},{"name":"Saul Jephcott","avatar":""},{"name":"Christian Erickson","avatar":""},{"name":"Eric Ballie","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113