INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-san-ban', 'Mùa Săn Bắn', 'Open Season', 'https://phimimg.com/upload/vod/20231030-1/bf23f9c2e187e57114ababd12c986a8b.jpg', 'https://phimimg.com/upload/vod/20231030-1/da58a4fc31b80e3a88ac153225acfb4a.jpg', '<p>Boog, một con nặng 900 pound đã được thuần hóa. Gấu xám Bắc Mỹ bị mắc kẹt trong rừng 3 ngày trước Mùa mở cửa. Bị buộc phải dựa vào Elliot, một con nai la nói nhanh, cả hai hình thành một tình bạn khó có thể xảy ra và phải nhanh chóng tập hợp các động vật rừng khác nếu chúng muốn thành lập một đội quân ragtag chống lại những người thợ săn.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Lawrence","avatar":""},{"name":"Ashton Kutcher","avatar":""},{"name":"Gary Sinise","avatar":""},{"name":"Debra Messing","avatar":""},{"name":"Billy Connolly","avatar":""},{"name":"Georgia Engel","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Gordon Tootoosis","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Cody Cameron","avatar":""},{"name":"Nika Futterman","avatar":""},{"name":"Danny Mann","avatar":""},{"name":"Jack McGee","avatar":""},{"name":"Michelle Murdocca","avatar":""},{"name":"Fergal Reilly","avatar":""},{"name":"Maddie Ta","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324524);
