INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-mo', 'Lò Mổ', 'Hostel', 'https://phimimg.com/upload/vod/20231026-1/0ee49e50b234ca2e9070dfc3240535c1.jpg', 'https://phimimg.com/upload/vod/20231026-1/91b93e478567e3facc3881eb54e11eb5.jpg', '<p>Paxton và Josh trên đường cùng nhau đi du lịch balô sang châu Âu đã kết bạn với Oli, một anh chàng người Iceland. Oli khoe khoang với hai người bạn của mình về một nơi ở ngoài thành phố Slovakian có đầy các cô gái xinh đẹp và quyến rũ.Paxton và Josh hăm hở đến thử thì quả nhiên như lời Oli kể nhưng họ không thể ngờ rằng phía sau những gương mặt tươi cười kia là cả một cạm bẫy chết người.</p>', 'Full', 1, 'single', 'completed', 21, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jay Hernandez","avatar":""},{"name":"Keiko Seiko","avatar":""},{"name":"Barbara Nedeljakova","avatar":""},{"name":"Eythor Gudjonsson","avatar":""},{"name":"Jana Havlickova","avatar":""},{"name":"Derek Richardson","avatar":""},{"name":"Paula Wild","avatar":""},{"name":"Jan Vlasák","avatar":""},{"name":"Jana Kaderabkova","avatar":""},{"name":"Rick Hoffman","avatar":""},{"name":"Ľubomír Bukový","avatar":""},{"name":"Jennifer Lim","avatar":""},{"name":"Miroslav Táborský","avatar":""},{"name":"Petr Janiš","avatar":""},{"name":"Takashi Miike","avatar":""},{"name":"Patrik Zigo","avatar":""},{"name":"Milda J","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324524);
