INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-chim-canh-cut', 'Vũ Điệu Chim Cánh Cụt', 'Happy Feet', 'https://phimimg.com/upload/vod/20231026-1/2ab33bceec1a65609519ee3b6f6c2a07.jpg', 'https://phimimg.com/upload/vod/20231026-1/542546e30cd000afda8b39d487b3017a.jpg', '<p>Không giống các bạn của mình, chú chim cánh cụt Mumble không có giọng hát hay để quyến rũ bạn tình, nhưng bù lại cậu khiêu vũ rất giỏi.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2006, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Elijah Wood","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"Brittany Murphy","avatar":""},{"name":"Hugh Jackman","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Anthony LaPaglia","avatar":""},{"name":"Elizabeth Daily","avatar":""},{"name":"Magda Szubanski","avatar":""},{"name":"Miriam Margolyes","avatar":""},{"name":"Carlos Alazraqui","avatar":""},{"name":"Lombardo Boyar","avatar":""},{"name":"Jeffrey Garcia","avatar":""},{"name":"Johnny A. Sanchez","avatar":""},{"name":"Fat Joe","avatar":""},{"name":"Alyssa Shafer","avatar":""},{"name":"Ces","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324524);
