INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ngam-tien-hoa', 'Thế Giới Ngầm: Tiến Hóa', 'Underworld: Evolution', 'https://phimimg.com/upload/vod/20231026-1/cb065d3bcf4643b6e2a74f093f784322.jpg', 'https://phimimg.com/upload/vod/20231026-1/b50f5fae4c50ccc3230f545e66c235f8.jpg', '<p>Phần tiếp theo của bộ phim Underworld này tiếp tục nói về cuộc chiến tranh giữa Death Dealers (ma cà rồng) và Lycans (người sói) với thời gian là khi bắt đầu mối thù truyền kiếp đó. Đứng đầu của hai bên là Selene, nữ ma cà rồng xinh đẹp và Michael, anh chàng người sói mạnh mẽ. &nbsp;Cả hai người họ đều cố gắng giải mã những bí ẩn về dòng máu của họ và xen lẫn vào đó là tình yêu, khiến cho cuộc chiến thù hận càng đau thương hơn khi họ phải chạm trán với nhau.</p>', 'Full', 1, 'single', 'completed', 14, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Beckinsale","avatar":""},{"name":"Scott Speedman","avatar":""},{"name":"Tony Curran","avatar":""},{"name":"Shane Brolly","avatar":""},{"name":"Derek Jacobi","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Steven Mackintosh","avatar":""},{"name":"Zita Görög","avatar":""},{"name":"Brian Steele","avatar":""},{"name":"John Mann","avatar":""},{"name":"Scott McElroy","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Sophia Myles","avatar":""},{"name":"Richard Cetrone","avatar":""},{"name":"Mike Mukatis","avatar":""},{"name":"Raoul Ganeev","avatar":""},{"name":"Andrew Kavadas","avatar":""},{"name":"Kayla Le","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324524);
