INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-kia-hang-rao', 'Bên Kia Hàng Rào', 'Over the Hedge', 'https://phimimg.com/upload/vod/20231026-1/ef1f97fabf3e6783c3c0ca17d3e27d5a.jpg', 'https://phimimg.com/upload/vod/20231026-1/a437f0516e80efd42f8bed5303f7ffb1.jpg', '<p>Thức dậy sau một kỳ ngủ đông, Ông rùa Verne và những con thú trong cánh rừng ven rìa thành phố phía Tây đột nhiên thấy xuất hiện một hàng rào rất cao bao quanh nơi chúng đang sinh sống. Hơn nửa cánh rừng của chúng biến mất, lượng thức ăn còn lại trở nên ít ỏi. Verne cho rằng muông thú nên tập dần cho quen với cảnh đói kém này. Vả lại theo ông, thức ăn tự nhiên là hợp với động vật nhất, hơn hẳn so với đồ của con người. &nbsp;Nhưng một chú chồn tên RJ xuất hiện và chỉ cho họ một cách khác mạo hiểm hơn: vượt rào và lấy thức ăn của con người. Đám thú cho rằng đó là một ý tưởng hay nên ào ào đi trộm lương thực về. Tuy nhiên chúng đâu biết một sự thật là RJ đang nợ Vincent - một chú gấu to lớn- rất nhiều thức ăn. Mà nó lại chỉ có 1 tuần để kiếm đủ số lương thực đó trước khi RJ phải đánh đổi mạng sống của nó..</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Garry Shandling","avatar":""},{"name":"Steve Carell","avatar":""},{"name":"Wanda Sykes","avatar":""},{"name":"William Shatner","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Thomas Haden Church","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Eugene Levy","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Avril Lavigne","avatar":""},{"name":"Omid Djalili","avatar":""},{"name":"Sami Kirkpatrick","avatar":""},{"name":"Shane Baumel","avatar":""},{"name":"Madison Davenport","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324524);
