INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muu-cau-hanh-phuc', 'Mưu Cầu Hạnh Phúc', 'The Pursuit of Happyness', 'https://phimimg.com/upload/vod/20231023-1/7b9ab65b83ddc16eb1087126a1b25d37.jpg', 'https://phimimg.com/upload/vod/20231023-1/fad4ac939135f6384d5d305942a813c1.jpg', '<p>Chris Gardner một người bán hàng không gặp may thất bại trong kinh doanh, nợ nần chồng chất, vợ bỏ, bị đuổi khỏi nhà do không trả được tiền thuê, tất cả mọi cánh cửa dường như đã đóng sập với Chris nhưng với lòng quyết tâm, ý chí sắt đá và đặc biệt là cậu con trai Christopher đã trở thành động lực thôi thúc Chris vươn lên.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Jaden Smith","avatar":""},{"name":"Thandiwe Newton","avatar":""},{"name":"Brian Howe","avatar":""},{"name":"James Karen","avatar":""},{"name":"Kurt Fuller","avatar":""},{"name":"Dan Castellaneta","avatar":""},{"name":"Joe Nuñez","avatar":""},{"name":"David Fine","avatar":""},{"name":"Takayo Fischer","avatar":""},{"name":"Kevin West","avatar":""},{"name":"George Cheung","avatar":""},{"name":"Geoff Callan","avatar":""},{"name":"Scott Klace","avatar":""},{"name":"Rashida Clendening","avatar":""},{"name":"Peter Fitzsimmons","avatar":""},{"name":"Maurice Sherbanee","avatar":""},{"name":"Zuhair","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
