INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-doi-co-mat', 'Ngọn Đồi Có Mắt', 'The Hills Have Eyes', 'https://phimimg.com/upload/vod/20231022-1/3c5f1c6895caf9b52076a74461522569.jpg', 'https://phimimg.com/upload/vod/20231022-1/49b6df2ee4f0b85cde1d075154ff2918.jpg', '<p>Cả gia đình người Mỹ Carter quyết định rời thành phố bắt đầu một chuyến du lịch, nhưng không may họ bị mắc kẹt giữa sa mạc xa xôi của vùng New Mexico. Kinh khủng hơn, nơi đó không chỉ là vùng hoang mạc chết chóc mà còn là nơi thử nghiệm bom hạt nhân những năm 50, nơi tạo ra hàng loạt những sinh vật man rợ sẵn sàng lao tới để tấn công họ. Hãy cùng trải nghiệm cuộc phiêu lưu đầy kinh dị và ghê rợn cùng gia đình Carter tại Ngọn đồi có mắt ngay bây giờ.</p>', 'Full', 1, 'single', 'completed', 18, 2006, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Aaron Stanford","avatar":""},{"name":"Kathleen Quinlan","avatar":""},{"name":"Vinessa Shaw","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"Emilie de Ravin","avatar":""},{"name":"Dan Byrd","avatar":""},{"name":"Tom Bower","avatar":""},{"name":"Billy Drago","avatar":""},{"name":"Robert Joy","avatar":""},{"name":"Desmond Askew","avatar":""},{"name":"Ezra Buzzington","avatar":""},{"name":"Michael Bailey Smith","avatar":""},{"name":"Laura Ortiz","avatar":""},{"name":"Maxime Giffard","avatar":""},{"name":"Maisie Camilleri Preziosi","avatar":""},{"name":"Greg Nicotero","avatar":""},{"name":"Ivana T","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324524);
