INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-o-vien-bao-tang', 'Đêm Ở Viện Bảo Tàng', 'Night at the Museum', 'https://phimimg.com/upload/vod/20231023-1/36fdeaeaad8f8166f837b9c4e49b258d.jpg', 'https://phimimg.com/upload/vod/20231023-1/20b2a3081cc9e888adba0593d393ad24.jpg', '<p>Night At The Museum (Đêm Ở Viện Bảo Tàng) xoay quanh nhân vật Larry Daley, một anh chàng hay mộng mơ, suốt ngày nghĩ mình là người vĩ đại nhưng chưa gặp thời. Để con trai không nghĩ mình là một kẻ lông bông, anh chàng quết định nhận một chân gác đêm tại Bảo tàng Lịch sử và Tự nhiên. Nhưng anh không ngờ rằng, ban ngày, Viện Bảo tàng cũng như bao Bảo tàng khác, nhưng đến đêm, tất cả những hình nộm người, thú và các đồ vật đều đồng loạt sống dậy và thi nhau làm loạn.</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Dick Van Dyke","avatar":""},{"name":"Mickey Rooney","avatar":""},{"name":"Bill Cobbs","avatar":""},{"name":"Jake Cherry","avatar":""},{"name":"Ricky Gervais","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"Kim Raver","avatar":""},{"name":"Patrick Gallagher","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"Pierfrancesco Favino","avatar":""},{"name":"Charlie Murphy","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Mizuo Peck","avatar":""},{"name":"Kerry van der Griend","avatar":""},{"name":"Dan Rizzuto","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d