INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-than-vung-texas-khoi-dau', 'Tử Thần Vùng Texas: Khởi Đầu', 'The Texas Chainsaw Massacre: The Beginning', 'https://phimimg.com/upload/vod/20231022-1/1107dda7301ffab2235ce794bd58faad.jpg', 'https://phimimg.com/upload/vod/20231022-1/7d5a9ba0d4cb2db6f7adb47deecda581.jpg', '<p>Chrissie và những người bạn của cô ấy đã bắt đầu một chuyến đi đường dài để tận hưởng lần cuối trước khi chuyển đến Việt Nam. Trên đường đi, những người đi xe đạp quấy rối bộ tứ và gây ra một tai nạn khiến Chrissie văng khỏi xe. Người luật sư đến hiện trường giết một trong những kẻ đi xe đạp và đưa bạn bè của Chrissie đến trang trại Hewitt, nơi gã Leatherface trẻ đang học cách sử dụng vũ khí.</p>', 'Full', 1, 'single', 'completed', 13, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jordana Brewster","avatar":""},{"name":"Taylor Handley","avatar":""},{"name":"Diora Baird","avatar":""},{"name":"Matt Bomer","avatar":""},{"name":"R. Lee Ermey","avatar":""},{"name":"Lew Temple","avatar":""},{"name":"Andrew Bryniarski","avatar":""},{"name":"Tim DeZarn","avatar":""},{"name":"Lee Tergesen","avatar":""},{"name":"Cyia Batten","avatar":""},{"name":"Terrence Evans","avatar":""},{"name":"Marietta Marich","avatar":""},{"name":"L.A. Calkins","avatar":""},{"name":"Allison Marich","avatar":""},{"name":"Marcus H. Nelson","avatar":""},{"name":"Kathy Lamkin","avatar":""},{"name":"Melody Chase","avatar":""},{"name":"Emi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324524);
