INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-lap-di', 'Kẻ Lập Dị', 'Crank', 'https://phimimg.com/upload/vod/20231023-1/15fac1da75ccafa1aff2813cb5c1c835.jpg', 'https://phimimg.com/upload/vod/20231023-1/611d94bc4a4c3b442fcef747a248f060.jpg', '<p>Một sát thủ bị đầu độc biết rằng anh có thể thoát chết nếu tiếp tục kích thích adrenaline khi chạy đua trên đường phố Los Angeles.</p>', 'Full', 1, 'single', 'completed', 11, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"Jose Pablo Cantillo","avatar":""},{"name":"Efren Ramirez","avatar":""},{"name":"Dwight Yoakam","avatar":""},{"name":"Carlos Sanz","avatar":""},{"name":"Reno Wilson","avatar":""},{"name":"Edi Gathegi","avatar":""},{"name":"Glenn Howerton","avatar":""},{"name":"Jay Xcala","avatar":""},{"name":"Keone Young","avatar":""},{"name":"Valarie Rae Miller","avatar":""},{"name":"Yousuf Azami","avatar":""},{"name":"Laurent Schwaar","avatar":""},{"name":"David Brown","avatar":""},{"name":"Dorian Kingi","avatar":""},{"name":"Med Abrous","avatar":""},{"name":"Daniel St","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324524);
