INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-lap-di', 'Kẻ Lập Dị', 'Crank', 'kẻ lập dị crank jason statham amy smart jose pablo cantillo efren ramirez dwight yoakam carlos sanz reno wilson edi gathegi glenn howerton jay xcala keone young valarie rae miller yousuf azami laurent schwaar david brown dorian kingi med abrous daniel st ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-cung-than-nong', 'Mê Cung Thần Nông', 'Pan''s Labyrinth', 'https://phimimg.com/upload/vod/20231023-1/1ab13c20ca0a6358cb9b0e10572d380d.jpg', 'https://phimimg.com/upload/vod/20231023-1/30644c30b6eecb5ef43dcea2dbe98ecb.jpg', '<p>Câu chuyện diễn ra ở Tây Ban Nha vào mùa hè năm 1944, năm năm sau Nội chiến Tây Ban Nha, trong thời kỳ đầu của Pháp. Câu chuyện kể đan xen thế giới thực này với một thế giới thần thoại tập trung vào một mê cung bị bỏ hoang, bị bỏ rơi và một sinh vật huyền bí, người mà nhân vật chính, Ofelia, tương tác. Cha dượng của Ofelia, Thuyền trưởng Falangist Vidal, săn lùng Ma giáo Tây Ban Nha, người chiến đấu chống lại chế độ Pháp giáo trong khu vực, trong khi bà mẹ mang thai của Ofelia, Carmen ngày càng ốm yếu. Ofelia gặp một số sinh vật kỳ lạ và ma thuật trở thành trung tâm trong câu chuyện của cô, dẫn dắt cô vượt qua những thử thách của khu vườn mê cung cũ.</p>', 'Full', 1, 'single', 'completed', 21, 2006, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Ivana Baquero","avatar":""},{"name":"Maribel Verdú","avatar":""},{"name":"Sergi López","avatar":""},{"name":"Doug Jones","avatar":""},{"name":"Ariadna Gil","avatar":""},{"name":"Álex Angulo","avatar":""},{"name":"Roger Casamajor","avatar":""},{"name":"Manolo Solo","avatar":""},{"name":"César Vea","avatar":""},{"name":"Iván Massagué","avatar":""},{"name":"Gonzalo Uriarte","avatar":""},{"name":"Eusebio Lázaro","avatar":""},{"name":"Francisco Vidal","avatar":""},{"name":"Juanjo Cucalón","avatar":""},{"name":"Lina Mira","avatar":""},{"name":"Mario Zorrilla","avatar":""},{"name":"Sebastián Haro","avatar":""},{"name":"Mila Espi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324524);
