INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khai-huyen', 'Khải Huyền', 'Apocalypto', 'https://phimimg.com/upload/vod/20231022-1/db44952a4e0379b74916d16c6da4af7f.jpg', 'https://phimimg.com/upload/vod/20231022-1/9b67298a4ef304d856616bdc0091411a.jpg', '<p>Bộ phim hư cấu, lấy đề tài về nền văn minh Châu Mỹ cổ đại, với đế chế Maya đầy huyền bí có thật trong lịch sự nhân loại thống trị Châu Mỹ hơn 1000 năm, với bối cảnh 500 năm sau khi Maya diệt vong, ở nhiều nơi trong rừng già Châu Mỹ, nền văn minh Maya vẫn còn tồn tại với những Kim tự tháp Maya cao vời vợi và sự dựng xây nên văn minh đó đồng nghĩa với sự chinh phục, tiêu diệt biết bao bộ lạc nhỏ xung quanh, cướp bóc những phồn hoa, những của cải, con người, máu và nước mắt để rồi một ngày, cả thế giới ấy bị nhấn chìm vào sự hủy diệt, có phải ấy chính là sự trừng phạt của thần thánh cho những hành động mà họ đã gây cho cho những dân tộc khác ?. Tất cả những sự kiện, những suy nghĩ, những bí ẩn trên về ...</p>', 'Full', 1, 'single', 'completed', 22, 2006, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Rudy Youngblood","avatar":""},{"name":"Raoul Max Trujillo","avatar":""},{"name":"Gerardo Taracena","avatar":""},{"name":"Iazua Larios","avatar":""},{"name":"Antonio Monroy","avatar":""},{"name":"María Isabel Díaz Lago","avatar":""},{"name":"Dalia Hernández","avatar":""},{"name":"Jonathan Brewer","avatar":""},{"name":"Morris Birdyellowhead","avatar":""},{"name":"Carlos Emilio Báez","avatar":""},{"name":"Amilcar Ramírez","avatar":""},{"name":"Israel Contreras","avatar":""},{"name":"Israel Ríos","avatar":""},{"name":"Espiridion Acosta Cac","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324524);
