INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-song-bac-hoang-gia', 'Điệp Viên 007: Sòng Bạc Hoàng Gia', 'Casino Royale', 'https://phimimg.com/upload/vod/20231020-1/f7a4755d5dfcf0279c92d79f1e5aa1ec.jpg', 'https://phimimg.com/upload/vod/20231020-1/df99606ce88e0f88e85fa0eefa781b0e.jpg', '<p>Martin Campbell, Neal Purvis, Robert Wade, Sau những thành tích đáng kể, chàng điệp viên huyền thoại James Bond được gắn số. Nhiệm vụ đầu tiên ở vị trí mới là đến Madagascar theo dõi tên khủng bố Mollaka. Mọi việc không được lên kế hoạch trước và không hoàn thành như ý muốn, bởi vậy anh quyết định hoạt động độc lập với MI6 và tự mình điều tra từ những manh mối có được để thanh toán nhóm khủng bố này.</p>', 'Full', 1, 'single', 'completed', 22, 2006, 'Vietsub', 'HD', 'Séc', 0, '[{"name":"Daniel Craig","avatar":""},{"name":"Eva Green","avatar":""},{"name":"Mads Mikkelsen","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Giancarlo Giannini","avatar":""},{"name":"Caterina Murino","avatar":""},{"name":"Simon Abkarian","avatar":""},{"name":"Isaach De Bankolé","avatar":""},{"name":"Jesper Christensen","avatar":""},{"name":"Ivana Miličević","avatar":""},{"name":"Tobias Menzies","avatar":""},{"name":"Claudio Santamaria","avatar":""},{"name":"Sébastien Foucan","avatar":""},{"name":"Malcolm Sinclair","avatar":""},{"name":"Richa","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324524);
