INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-boston', 'Điệp Vụ Boston', 'The Departed', 'https://phimimg.com/upload/vod/20231020-1/e54e6a8a12632bc0889c03cb4639d735.jpg', 'https://phimimg.com/upload/vod/20231020-1/5a4934506ecac74ce5a9407ff58df0e8.jpg', '<p>The Departed (Điệp Vụ Boston) là bộ phim được dựng lại từ siêu phẩm Vô Gian Đạo (Infernal Affairs) của Hồng Kông. Nội dung phim xoay quanh hai con người có hai lai lịch hoàn toàn khác nhau nhưng lại đi chung một con đường: làm nội gián. Billy Costigan, một cảnh sát chìm được cài vào băng nhóm tội phạm do Frank Costello cầm đầu. Cùng lúc này, nhân viên cảnh sát Colin Sullivan lại là một tay tội phạm được đưa vào nội bộ cảnh sát nhằm cung cấp tin tức cho Frank. Cả hai bước vào cuộc rượt đuổi với nhiệm vụ khai thác thông tin mật của mỗi bên, đồng thời phải che giấu thân phận thật sự của mình...</p>', 'Full', 1, 'single', 'completed', 16, 2006, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jack Nicholson","avatar":""},{"name":"Leonardo DiCaprio","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Mark Wahlberg","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Anthony Anderson","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Kevin Corrigan","avatar":""},{"name":"James Badge Dale","avatar":""},{"name":"David O''Hara","avatar":""},{"name":"Robert Wahlberg","avatar":""},{"name":"Kristen Dalton","avatar":""},{"name":"Thomas B. Duffy","avatar":""},{"name":"Richard Hughes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324524);
