INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-thuat-gia-dau-tri', 'Ảo Thuật Gia Đấu Trí', 'The Prestige', 'https://phimimg.com/upload/vod/20231020-1/033f14d49221c32831cb50b655dafee3.jpg', 'https://phimimg.com/upload/vod/20231020-1/31cc9cdbc15c942e8a0244cb20ee7182.jpg', '<p>The Prestige xoay quanh hai ảo thuật gia đại tài là Robert Angier (Hugh Jackman) và Alfred Borden (Christian Bale). Ban đầu họ là những người bạn, thế nhưng bởi giấc mơ tạo ra tiết mục hấp dẫn nhất quá lớn, khiến họ đã bị cuốn vào một cuộc cạnh tranh một mất một còn với kết cục bi thảm.&nbsp; Cũng mang đậm dấu ấn như bao phim khác của Christopher Nolan, The Prestige có kết cấu tương đối phức tạp. Cách kể chuyện không theo trình tự thời gian dẫn đến có đôi chỗ người xem sẽ cảm thấy mơ hồ, khó nắm bắt.</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Hugh Jackman","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Rebecca Hall","avatar":""},{"name":"David Bowie","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Piper Perabo","avatar":""},{"name":"Jim Piddock","avatar":""},{"name":"Samantha Mahurin","avatar":""},{"name":"Mark Ryan","avatar":""},{"name":"Jamie Harris","avatar":""},{"name":"Daniel Davis","avatar":""},{"name":"Roger Rees","avatar":""},{"name":"Ricky Jay","avatar":""},{"name":"Christopher Neame","avatar":""},{"name":"Monty Stuart","avatar":""},{"name":"Ron Perkin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324524);
