INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-cua-pao', 'Chuyện Của Pao', 'Pao''s Story', 'null', 'https://phimimg.com/upload/vod/20231011-1/8a3b20a28a9017a0fa35d3cc87c4063d.jpg', '<p>Pao – cô gái miền núi hồn nhiên luôn thắc mắc về những gì xảy ra trong gia đình mình: Sao “mẹ già” bỗng mất tích bên dòng suối? Sao mẹ đẻ lại không ở cùng hai chị em Pao? Đi tìm nguồn cơn câu chuyện cũng là hành trình mà Pao lần giở được những bí mật mà các bà mẹ của cô cũng như chính cô luôn chôn giấu…</p>', 'Full', 1, 'single', 'completed', 23, 2006, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Do Thi Hai Yen","avatar":""},{"name":"Hoa Thuy Do","avatar":""},{"name":"Thanh Kha Ly","avatar":""},{"name":"Nhu Quynh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
