INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-thich-mua-sam', 'Cô Gái Thích Mua Sắm', 'Shopaholics', 'https://phimimg.com/upload/vod/20231010-1/6473c362edef4f3326a350c1c33b7955.jpg', 'https://phimimg.com/upload/vod/20231010-1/1594575fb1d6baf2bf13b817ee37e168.jpg', '<p>Fong là một người nghiện mua sắm và đã mắc phải một khoản nợ nghiêm trọng nào đó. Cô tìm kiếm sự giúp đỡ của Choosey, một bác sĩ tâm thần có những vấn đề tâm lý vui nhộn.</p>', 'Full', 1, 'single', 'completed', 15, 2006, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Cecilia Cheung","avatar":""},{"name":"Jordan Chan","avatar":""},{"name":"Ella Koon","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Paula Tsui","avatar":""},{"name":"Ha Chun-Chau","avatar":""},{"name":"Wong Tin-lam","avatar":""},{"name":"Perrie Lai Hoi-San","avatar":""},{"name":"Lam Hoi-Man","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324524);
