INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mat-thu-ba-2006', 'Con Mắt Thứ Ba', 'The Third Eye', 'https://phimimg.com/upload/vod/20231010-1/13d757195998c6ef1242c81b5a42f2af.jpg', 'https://phimimg.com/upload/vod/20231010-1/a1b708ec775f35c0f1495586bc06e7a9.jpg', '<p>Zhang Liang là một chàng trai trẻ không tham gia vào bất kỳ công việc phù hợp nào. Sở thích bí mật của anh ấy là chơi với tất cả các loại công nghệ chân thực công nghệ cao, đặc biệt là những bức ảnh chân thực. Anh ta yêu điên cuồng một nữ tiếp viên hàng không trẻ tuổi. Liang mang theo đầy đủ trang thiết bị của mình để ở trong một nhà nghỉ. Anh ta bí mật lắp đặt máy quay video lỗ kim trong phòng tiếp viên cũng như những người thuê nhà khác. Thông qua những điều này, Liang đã khám phá được bí mật của mọi người. Anh ta không để ý rằng mình sẽ trở thành người dẫn đầu thay vì người ngoài cuộc...</p>', 'Full', 1, 'single', 'completed', 17, 2006, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Race Wong","avatar":""},{"name":"Wong Yau-Nam","avatar":""},{"name":"Farini Cheung Yui-Ling","avatar":""},{"name":"Joman Chiang","avatar":""},{"name":"Sarika Choy","avatar":""},{"name":"Tony Ho","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Samuel Pang","avatar":""},{"name":"Wong Chi-On","avatar":""},{"name":"Derek Tsang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324524);
