INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-noi-tinh-tu', 'Hãy Nói Tình Tự', 'Feel It Say It', 'https://phimimg.com/upload/vod/20231008-1/321d14ed58bd93e95a33a7e1a72cc6cb.jpg', 'https://phimimg.com/upload/vod/20231008-1/3519b1063cab3a1745f19ef8ea4a8426.jpg', '<p>Một số câu chuyện đan xen vào bộ phim hài vui nhộn này. Eric Kot vào vai bác sĩ da liễu bộ phận sinh dục, bác sĩ Heung, người rất yêu quý và tôn trọng nghề nghiệp của mình. Anh và trợ lý Ma ngầm làm việc cùng nhau một cách chuyên nghiệp nhưng không thể tiến thêm một bước nào khác ngoài công việc. Nghệ sĩ đang lên Fifi Wong muốn làm nên chuyện lớn trong sự nghiệp của mình, sau đó cô ấy đã phải lòng To Bing hiền lành ngay từ cái nhìn đầu tiên mặc dù cả hai người đều đã có một nửa quan trọng khác của mình.</p>', 'Full', 1, 'single', 'completed', 20, 2006, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Eric Kot Man-Fai","avatar":""},{"name":"Jerry Lamb Hiu-Fung","avatar":""},{"name":"Tiffany Lee","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Lau Yee Tat","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Anson Leung Chun-Yat","avatar":""},{"name":"Candy Lo","avatar":""},{"name":"Simon Lui","avatar":""},{"name":"Chung-hei Wang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324524);
