INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-mat-chuoc', 'Anh Hùng Mạt Chược', 'Bet to Basic', 'https://phimimg.com/upload/vod/20231006-1/a26e4b78456bf9411b7a66d6385e6d9d.jpg', 'https://phimimg.com/upload/vod/20231006-1/b1be75991240ea326b32e449451efa98.jpg', '<p>Một thợ làm tóc, một trưởng thôn và một bác sĩ thú y từng có bạn 
gái nhưng vẫn khăng khăng chơi trên cánh đồng. Một đêm nọ, một linh hồn 
