INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-say-sua', 'Cuộc Đời Say Sưa', 'Cocktail', 'https://phimimg.com/upload/vod/20231006-1/5073ea77eb8f17bd8f0c8788bda2c983.jpg', 'https://phimimg.com/upload/vod/20231006-1/bd57311a999d92e7e3094b879dc7dcb2.jpg', '<p><span class="key"></span>“Cuộc đời say sưa” kể về cậu chuyện xảy 
ra trong một quán rượu có tên là “ một nửa trần gian”. Bộ phim xoay 
quanh câu chuyện ông chủ Paul học cách pha chế rượu trong quán rượu “ 
một nửa nhân gian”, trong số khách hàng ra vào quán rượu hàng ngày, anh 
đã trải qua không biết bao nhiêu câu chuyện của từng người, đưa vào 
trong cốc rượu những vị đắng, cay, ngọt, bùi, &nbsp;pha chế ra những loại 
rượu đời người thích hợp với tâm trạng của bản thân.</p>', 'Full', 1, 'single', 'completed', 19, 2006, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Bobo Chan","avatar":""},{"name":"Suet-Fei Chiu","avatar":""},{"name":"Endy Chow","avatar":""},{"name":"Eric Kot Man-Fai","avatar":""},{"name":"Johnson Lee Sze-Chit","avatar":""},{"name":"Anson Leung Chun-Yat","avatar":""},{"name":"Patrick Tang","avatar":""},{"name":"Derek Tsang","avatar":""},{"name":"Monnie Tung","avatar":""},{"name":"Race Wong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
