INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoanh-khac-mua-he', 'Khoảnh Khắc Mùa Hè', 'Once in A Summer', 'https://phimimg.com/upload/vod/20231002-1/335c984bcb2f07c6c67951e7e44c184e.jpg', 'https://phimimg.com/upload/vod/20231002-1/f43e815cc1d22cbf24c0f09d5ca47d0a.jpg', '<p>Lấy bối cảnh là thời điểm năm 1969 tại Hàn Quốc, khi phong trào sinh viên biểu tình chống chính quyền nổi dậy mạnh mẽ, <span style="font-style: italic;">Once in a Summer</span>
 kể về chàng sinh viên điển trai người Seoul Suk Young (Lee Byung Hun 
đóng) cùng bạn bè đi về một ngôi làng nông thôn làm tình nguyện viên mùa
 hè. Tại đây, Suk Young đã tình cờ gặp Jung In
 (Soo Ae) - cô gái có đôi mắt trong như hồ nước, nụ cười tươi đầy tinh 
nghịch nhưng cũng ẩn nét buồn. Jung In là nhân viên của thư viện làng, 
ngày nào cũng đi làm muộn, thích giúp đỡ mọi người nhưng dường như có 
một bóng tối nào đó đã phủ lên cuộc đời cô gái ấy. Người làng thi thoảng
 vẫn bóng gió về chuyện cha cô &quot;hại cả cái làng này&quot;...</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br/></p><p><br/></p>', 'Full', 1, 'single', 'completed', 22, 2006, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lee Byung-hun","avatar":""},{"name":"Soo Ae","avatar":""},{"name":"Lee Se-eun","avatar":""},{"name":"Lee Hae-eun","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Jeong Seok-yong","avatar":""},{"name":"Na Ki-soo","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Yoo Hae-jin","avatar":""},{"name":"Kim Kyeong-ran","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324524);
