INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-la-dan-ong', 'Cô Ấy Là Đàn Ông', 'She''s the Man', 'https://phimimg.com/upload/vod/20230919-1/3c35f7b919a3be2769a10d06e4865249.jpg', 'https://phimimg.com/upload/vod/20230919-1/ee360db76b679e5973992b7402bcc35c.jpg', '<p><span style="font-family: ">Viola Hastings đang gặp khó khăn thực sự. Các biến chứng đe dọa kế hoạch của cô ấy là đóng giả anh trai sinh đôi của mình, Sebastian, và thay thế anh ta tại một trường nội trú mới. Cô ấy yêu người bạn cùng phòng đẹp trai của mình, Duke, người yêu Olivia xinh đẹp, người đã yêu Sebastian! Như thể vẫn chưa đủ, cặp song sinh của Viola trở về từ London trước thời hạn nhưng không biết rằng em gái của anh đã thay thế anh trong khuôn viên trường.</span></p>', 'Full', 1, 'single', 'completed', 22, 2006, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Bynes","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Laura Ramsey","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"David Cross","avatar":""},{"name":"Julie Hagerty","avatar":""},{"name":"Robert Hoffman","avatar":""},{"name":"Alexandra Breckenridge","avatar":""},{"name":"Jonathan Sadowski","avatar":""},{"name":"Amanda Crew","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324524);
