INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-nga-2006', 'Cú Ngã (2006)', 'The Fall (2006)', 'https://phimimg.com/upload/vod/20230916-1/241f73d07cdff453205cacb74aad82b2.jpg', 'https://phimimg.com/upload/vod/20230916-1/b4c15bc097b15e9690eae0b2c38ae37d.jpg', '<p>Los Angles, mùa thu năm 1920, bị gãy tay, bé Alexandria chẳng thể nào vui chơi cùng bạn bè, chỉ một mình quanh quẩn ở bệnh viện. Cho đến một ngày nọ, cô bé phát hiện một &quot;kho tàng&quot; truyện cổ tích khổng lồ với những điều diệu kỳ từ một anh thanh niên Roy bị bệnh nằm liệt giường trong bệnh viện. Và đó là những câu chuyện thần tiên kỳ diệu nhất mà bé được nghe. Nhưng Roy kể chuyện cho cô bé thực chất vì một ý đồ đen tối của y…</p>', 'Full', 1, 'single', 'completed', 31, 2006, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Lee Pace","avatar":""},{"name":"Catinca Untaru","avatar":""},{"name":"Jeetu Verma","avatar":""},{"name":"Marcus Wesley","avatar":""},{"name":"Leo Bill","avatar":""},{"name":"Julian Bleach","avatar":""},{"name":"Justine Waddell","avatar":""},{"name":"Kim Uylenbroek","avatar":""},{"name":"Aiden Lithgow","avatar":""},{"name":"Emil Hostina","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324524);
