INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-cuc', 'Vô Cực', 'The Promise', 'https://phimimg.com/uploads/movies/20260713/vo-cuc-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/vo-cuc-poster.webp', '<p>The Promise (Vô Cực) là bộ phim võ thuật về thế giới ngầm của Trung Hoa cổ đại. Trong đó, Vương Phi Khuynh Thành nhận được sự ban phép của Nữ thần Vận Mệnh khiến cô từ một cô gái nghèo trở thành Vương Phi xinh đẹp, được sủng ái với một điều kiện là cô không bao giờ có được một tình yêu chân thật. Nhưng rồi cô nhận được tình yêu từ một người nô lệ. Anh đã dùng sinh mạng của mình để đánh đổi tất cả, giúp Vương Phi giải thoát lời nguyền. Nhưng câu chuyện không chỉ đơn giản như thế...</p>', 'Full', 1, 'single', 'completed', 53, 2005, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Cecilia Cheung","avatar":""},{"name":"Liu Ye","avatar":""},{"name":"Chen Hong","avatar":""},{"name":"Cheng Qian","avatar":""},{"name":"Jang Dong-gun","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Nicholas Tse Ting-Fung","avatar":""},{"name":"Yu Jinwei","avatar":""},{"name":"Guan Xiaotong","avatar":""},{"name":"Shi Lei","avatar":""},{"name":"Lu Peng","avatar":""},{"name":"Anthony Brandon Wong","avatar":""},{"name":"Qian Bo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["La promesa: la leyenda de los caballeros del viento","Master of the Crimson Armor","无极","無極","The Promise","Кля