INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-dogtown', 'Chúa Tể Dogtown', 'Lords Of Dogtown', 'https://phimimg.com/upload/vod/20260704-1/eb1fc64850f6ced794f9ce512b5b37bb.jpg', 'https://phimimg.com/upload/vod/20260704-1/4a0401c8c00a8884f6689fc72105b066.jpg', '<p>Câu chuyện có thật và táo bạo về ba thiếu niên lướt sóng đến từ bãi biển Venice, California, những người đã đưa bộ môn trượt ván lên một tầm cao mới và thay đổi thế giới thể thao mãi mãi. Stacy Peralta, Tony Alva và Jay Adams hợp thành nhóm Z-Boys — một lũ nhóc vô danh tiểu tốt cho đến khi họ sáng tạo ra một phong cách trượt ván hoàn toàn mới, biến nó trở thành một hiện tượng trên toàn cầu. Thế nhưng, khi niềm đam mê của họ biến thành một cỗ máy kiếm tiền, chính sự thành công đó đã xé nát tình bạn của họ.</p>', 'Full', 1, 'single', 'completed', 46, 2005, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"John Robinson","avatar":""},{"name":"Emile Hirsch","avatar":""},{"name":"Rebecca De Mornay","avatar":""},{"name":"William Mapother","avatar":""},{"name":"Julio Oscar Mechoso","avatar":""},{"name":"Victor Rasuk","avatar":""},{"name":"Nikki Reed","avatar":""},{"name":"Heath Ledger","avatar":""},{"name":"Vincent Laresca","avatar":""},{"name":"Brian Zarate","avatar":""},{"name":"Pablo Schreiber","avatar":""},{"name":"Elden Henson","avatar":""},{"name":"Michael Angarano","avatar":""},{"name":"Mitch Hedberg","avatar":""},{"name":"Benjamin Nurick","avatar":""},{"name":"Stephanie Limb","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dogtown urai","독타운의 제왕들","Lords of Dogtown"]', 1784690324524);
