INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-lua-thanh-rome-phan-1', 'Máu Lửa Thành Rome (Phần 1)', 'Rome (Season 1)', 'https://phimimg.com/upload/vod/20260626-1/758b67848bf966356083483c2a43d76d.jpg', 'https://phimimg.com/upload/vod/20260626-1/adfd800e602ef9c9050a1661d4404367.jpg', '<p>Bộ phim truyền hình sử thi miêu tả thời kì biến đổi đẫm máu của Rome từ một nước Cộng hòa sang Đế quốc, một chuyển biến được tạo dựng nên từ sự suy đồi của thể chế chính trị, sự cạnh tranh của giới thượng lưu và những kẻ tham vọng. Trong khi nói về những kẻ giàu có, quyền thế và quan trọng trong lịch sử, Rome lại tập trung xoay quanh cuộc sống, gia đình, người thân của hai người lính thường Lucius Vorenus và Titus Pullo...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 48, 2005, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Kevin McKidd","avatar":""},{"name":"Ray Stevenson","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"James Purefoy","avatar":""},{"name":"Polly Walker","avatar":""},{"name":"Lindsay Duncan","avatar":""},{"name":"Tobias Menzies","avatar":""},{"name":"Max Pirkis","avatar":""},{"name":"Simon Woods","avatar":""},{"name":"Kerry Condon","avatar":""},{"name":"Chiara Mastalli","avatar":""},{"name":"David Bamber","avatar":""},{"name":"Nicholas Woodeson","avatar":""},{"name":"Lee Boardman","avatar":""},{"name":"Ian McNeice","avatar":""},{"name":"Tommaso Sacco","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["罗马","ROME［ローマ］","로마","Rome"]', 1784690324525);
