INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-rung-ron-o-amityville', 'Chuyện Rùng Rợn Ở Amityville', 'The Amityville Horror', 'https://phimimg.com/upload/vod/20260617-1/db063635476fafaa5b4bef2dfb74c355.jpg', 'https://phimimg.com/upload/vod/20260617-1/32524cd90e5c73b53ebf1116a31eb0f6.jpg', '<p>Bản làm lại dựng tóc gáy của bộ phim kinh dị đình đám năm 1979 này mô tả thử thách của gia tộc Lutz, ngôi nhà mới của họ có quá khứ đẫm máu và di sản của quỷ dữ. Chẳng bao lâu sau, người tộc trưởng của gia đình gặp ác mộng và con gái ông nhìn thấy những bóng ma.</p>', 'Full', 1, 'single', 'completed', 30, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Melissa George","avatar":""},{"name":"Jesse James","avatar":""},{"name":"Jimmy Bennett","avatar":""},{"name":"Chloë Grace Moretz","avatar":""},{"name":"Rachel Nichols","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Isabel Conner","avatar":""},{"name":"Brendan Donaldson","avatar":""},{"name":"Annabel Armour","avatar":""},{"name":"Rich Komenich","avatar":""},{"name":"David Gee","avatar":""},{"name":"Danny McCarthy","avatar":""},{"name":"Nancy Lollar","avatar":""},{"name":"José Taitano","avatar":""},{"name":"Lenore Thomas","avatar":""},{"name":"Marie","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Amityville I: The Amityville Horror Redux","Horror em Amityville","Amityville''i õudus","Τρόμος στο Amityville","Amitvilio kosmaras","Dehset sokagi","Amityville: The Horror","Horror Amityville","The Amityville Horror 9","Horor v Amityville","The Amityville Horror"]', 1784690324525);
