INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguc-tu-thep', 'Ngục Tù Thép', 'Chaos', 'https://phimimg.com/upload/vod/20260608-1/83b7c6b05eae72e4f6cdcccf98b3fbb7.jpg', 'https://phimimg.com/upload/vod/20260608-1/3047c4c6c864153cbecc08af665b1211.jpg', '<p>Một vụ rửa tiền táo tợn và chuyên nghiệp diễn ra ngay trước mũi cảnh sát bang Seattle. Toán cướp bịt mặt xông vào ngân hàng Globai, bắt các con tin uy hiếp cảnh sát, tên Lorenz cầm đầu toán cướp đòi được thương lượng với cựu nhân viên Quentin Conners.</p>', 'Full', 1, 'single', 'completed', 44, 2005, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Ryan Phillippe","avatar":""},{"name":"Wesley Snipes","avatar":""},{"name":"Henry Czerny","avatar":""},{"name":"Justine Waddell","avatar":""},{"name":"Nicholas Lea","avatar":""},{"name":"Jessica Steen","avatar":""},{"name":"Rob LaBelle","avatar":""},{"name":"John Cassini","avatar":""},{"name":"Damon Johnson","avatar":""},{"name":"Paul Perri","avatar":""},{"name":"Keegan Connor Tracy","avatar":""},{"name":"Natassia Malthe","avatar":""},{"name":"Ty Olsson","avatar":""},{"name":"Terry Chen","avatar":""},{"name":"Ken Medlock","avatar":""},{"name":"Michasha Armstrong","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Haos","混沌理论","混乱作战","Pearl Street Bridge","Chaos"]', 1784690324525);
