INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-van-phong-phan-2', 'Chuyện Văn Phòng (Phần 2)', 'The Office (Season 2)', 'https://phimimg.com/upload/vod/20260604-1/0e6722fbb82fb0d18f1c5c46edb82a48.jpg', 'https://phimimg.com/upload/vod/20260604-1/14c088a5df14a90328a4844ed3cdd8c0.jpg', '<p>Bắt đầu với The Dundies, phần thứ hai tiếp tục phát triển thành cốt truyện về nỗi lo sợ công ty sẽ cắt giảm quy mô, cùng với việc giới thiệu các nhân vật mới và phát triển một số nhân vật phụ — đặc biệt là nhân vật Dwight Schrute. Michael Scott sớm bắt đầu mối quan hệ với ông chủ của mình Jan Levenson và mối quan hệ của Pam Beesley và Jim Halpert trở thành một trong những tâm điểm của mùa giải. Sự tương hợp của họ trở nên rõ ràng hơn khi tình cảm của Jim dành cho Pam ngày càng lớn, trong khi cô phải vật lộn với mối quan hệ của mình với nhân viên kho hàng Roy Anderson.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 24, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rainn Wilson","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Jenna Fischer","avatar":""},{"name":"Ed Helms","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zyra","Punë zyre","Vida de Escritório","美版办公室","The Office (US) – Das Büro","The Office (U.S.)","آفیس","The Office US","The Office","The Office (US)","The Office (US) Extended Superfan Cut","The Office: An American Workplace","The Office: Superfan Episodes","The Office Superfan Episodes"]', 1784690324525);
