INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-van-phong-phan-1', 'Chuyện Văn Phòng (Phần 1)', 'The Office (Season 1)', 'https://phimimg.com/upload/vod/20260604-1/134ff009cbda97b4cf812543496abbbd.jpg', 'https://phimimg.com/upload/vod/20260604-1/41f628b4291c4bd2de08c5a63586c406.jpg', '<p>Phần này đã giới thiệu các nhân vật chính và thiết lập cốt truyện chung, xoay quanh Michael Scott, giám đốc khu vực của văn phòng chi nhánh Scranton, cố gắng thuyết phục các nhà làm phim tài liệu rằng anh ta đang chủ trì một văn phòng hạnh phúc và hoạt động tốt. Trong khi đó, đại diện bán hàng Jim Halpert tìm ra phương pháp để làm suy yếu người bạn cùng nhóm của mình, Dwight Schrute; lễ tân Pam Beesly cố gắng đối phó với sự vô cảm và thất bại của Michael; và nhân viên tạm thời Ryan Howard chủ yếu đóng vai trò là người quan sát sự điên rồ xung quanh anh ta.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 25, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rainn Wilson","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Jenna Fischer","avatar":""},{"name":"Ed Helms","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zyra","Punë zyre","Vida de Escritório","美版办公室","The Office (US) – Das Büro","The Office (U.S.)","آفیس","The Office US","The Office","The Office (US)","The Office (US) Extended Superfan Cut","The Office: An American Workplace","The Office: Superfan Episodes","The Office Superfan Episodes"]', 1784690324525);
