INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-cua-cac-nu-hoang-phan-8', 'Vua Của Các Nữ Hoàng (Phần 8)', 'The King Of Queens (Season 8)', 'https://phimimg.com/upload/vod/20240928-1/e504b91b359ce95c4f35b500da86a8b1.jpg', 'https://phimimg.com/upload/vod/20260606-1/1d2134d2b2c87c089feead9cc9cd6168.jpg', '<p>Cuộc sống của người giao hàng Doug Heffernan thật tốt đẹp cho đến khi người bố vợ mới góa vợ của anh, Arthur, chuyển đến sống cùng anh và vợ Carrie. Doug không còn là vua trong lãnh địa của mình nữa, và thay vì có một chiếc tivi màn hình lớn trong tầng hầm mới được tân trang lại, giờ đây anh ta có một ông già điên rồ.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 22, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin James","avatar":""},{"name":"Leah Remini","avatar":""},{"name":"Jerry Stiller","avatar":""},{"name":"Victor Williams","avatar":""},{"name":"Patton Oswalt","avatar":""},{"name":"Gary Valentine","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Rei do Queens","O Rei do Bairro","King of Queens","The King of Queens","Férjek gyöngye","پادشاه ملکه‌ها","Trăsniţii din Queens"]', 1784690324525);
