INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-smallville-phan-5', 'Thị Trấn Smallville (Phần 5)', 'Smallville (Season 5)', 'https://phimimg.com/upload/vod/20250604-1/297bdc8a863ebc09fb44f298cb91cdd5.jpg', 'https://phimimg.com/upload/vod/20250604-1/ebb10c602b0c67f53f507fc68890c51e.jpg', '<p>Clark Kent giờ đây đã bắt đầu học chính thức tại Đại học Central Kansas, nhưng đó không phải là tất cả những gì cậu đang gánh vác. Cậu mang trên vai toàn bộ định mệnh của mình — và có lẽ là cả thế giới. Trong mùa năm, Clark cuối cùng cũng bắt đầu chấp nhận định mệnh ấy và tiến những bước dài trên con đường trở thành Người Thép. Đồng thời, cậu chạm trán với giáo sư Milton Fine, người mà sự xuất hiện tại Smallville sẽ gây ra những tác động tàn phá đến tình bạn vốn đã rạn nứt giữa cậu và Lex.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 17, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Welling","avatar":""},{"name":"Erica Durance","avatar":""},{"name":"Cassidy Freeman","avatar":""},{"name":"Justin Hartley","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Smallville"]', 1784690324525);
