INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-hon-loan-phan-4', 'Vùng Đất Hỗn Loạn (Phần 4)', 'Everwood (Season 4)', 'https://phimimg.com/upload/vod/20260604-1/2fe3ff065ceb74120697f32924d35b25.jpg', 'https://phimimg.com/upload/vod/20260604-1/b9c36d84a31d20663a64188df863ce87.jpg', '<p>Sau khi vợ qua đời, bác sĩ phẫu thuật nọ cùng các con từ New York chuyển đến thị trấn nhỏ Everwood để xây dựng lại cuộc sống và hàn gắn tình cảm gia đình.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 23, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Treat Williams","avatar":""},{"name":"Gregory Smith","avatar":""},{"name":"Emily VanCamp","avatar":""},{"name":"Debra Mooney","avatar":""},{"name":"John Beasley","avatar":""},{"name":"Vivien Cardone","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Stephanie Niznik","avatar":""},{"name":"Merrilyn Gann","avatar":""},{"name":"Tom Amandes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["사랑의 마을, 에버우드","Everwood"]', 1784690324525);
