INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-em-nha-feller', 'Chị Em Nhà Feller', 'In Her Shoes', 'https://phimimg.com/upload/vod/20260530-1/8c252fbdc99a8faa4b5113360d5fe6e9.jpg', 'https://phimimg.com/upload/vod/20260530-1/be8b0f62b38a45bf8566aadcf4254943.jpg', '<p>Maggie – một cô gái tiệc tùng lêu lổng và vô trách nhiệm – bị tống cổ khỏi nhà của bố và mẹ kế, nơi cô bấy lâu nay vẫn ăn bám miễn phí. Sau đó, cô được người chị gái chăm chỉ của mình là Rose – một luật sư đang làm việc tại Philadelphia – cưu mang. Thế nhưng, sau khi lối sống quậy phá và bừa bãi của Maggie làm hủy hoại chuyện tình cảm của chị gái, Rose cũng không thể chịu đựng nổi và buộc phải đuổi cô đi. Bước ngoặt xảy ra khi người bà ngoại mà hai chị em chưa từng biết đến sự tồn tại bất ngờ bước vào cuộc đời họ, buộc hai chị em phải đối mặt với những sự thật phức tạp về chính bản thân mình và gia đình.</p>', 'Full', 1, 'single', 'completed', 22, 2005, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Cameron Diaz","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Shirley MacLaine","avatar":""},{"name":"Mark Feuerstein","avatar":""},{"name":"Ken Howard","avatar":""},{"name":"Richard Burgi","avatar":""},{"name":"Brooke Smith","avatar":""},{"name":"Candice Azzara","avatar":""},{"name":"Francine Beers","avatar":""},{"name":"Anson Mount","avatar":""},{"name":"Eric Balfour","avatar":""},{"name":"Andy Powers","avatar":""},{"name":"Jerry Adler","avatar":""},{"name":"John Mastrangelo Sr.","avatar":""},{"name":"Emilio Mignucci","avatar":""},{"name":"Terrance Christopher Jones","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["In Her Shoes"]', 1784690324525);
