INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-cap-cuu-phan-12', 'Phòng Cấp Cứu (Phần 12)', 'ER (Season 12)', 'https://phimimg.com/upload/vod/20260526-1/8441c2a3fa1a21a9230d5d223a36e3d4.jpg', 'https://phimimg.com/upload/vod/20260526-1/11406ba743607fcddfea191a78e5dba4.jpg', '<p>ER (Phòng Cấp Cứu) đi sâu vào khai thác guồng quay công việc nội bộ đầy áp lực tại một bệnh viện đào tạo lớn ở thành thị, đồng thời lột tả những vấn đề nan giải và mang tính quyết định mà đội ngũ y bác sĩ cùng nhân viên tận tụy tại phòng cấp cứu luôn trong tình trạng quá tải nơi đây phải đối mặt hàng ngày.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 23, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Maura Tierney","avatar":""},{"name":"Parminder Nagra","avatar":""},{"name":"Linda Cardellini","avatar":""},{"name":"Scott Grimes","avatar":""},{"name":"David Lyons","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"John Stamos","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Plantão Médico","急诊室的故事","急诊室的春天","Emergency Room","E.R. - Emergency Room","ER"]', 1784690324525);
