INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-chi-yeu-nguoi-la', 'Tôi Chỉ Yêu Người Lạ', 'Innocent', 'https://phimimg.com/upload/vod/20260513-1/298ac3aa18204b14987243323658ad0a.jpg', 'https://phimimg.com/upload/vod/20260513-1/8cb31e3a34e655cc8b62c0002e66ffff.jpg', '<p>Eric, 17 tuổi, theo cha mẹ di cư sang Canada và buộc phải đối mặt với những vấn đề tình cảm và văn hóa khác nhau. Cậu không chỉ phải thích nghi với môi trường mới mà còn phải chấp nhận giới tính thật của mình. Đứng trước ngưỡng cửa trưởng thành, cậu gặp gỡ một loạt những mối tình tiềm năng - anh họ đẹp trai, một người bạn học, một luật sư trung niên và cuối cùng là một phụ bếp. Họ đại diện cho những giai đoạn phát triển khác nhau của Eric, từ say mê, tình dục, tình yêu đến ý thức trách nhiệm.</p>', 'Full', 1, 'single', 'completed', 20, 2005, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Timothy Lee","avatar":""},{"name":"Larry Peloso","avatar":""},{"name":"David Yee","avatar":""},{"name":"David Song Wei Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Athoos","Ji oi mak sun yen","Innocent"]', 1784690324525);
