INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-thuc-tinh-tuyet-dep', 'Sự Thức Tỉnh Tuyệt đẹp', 'Beautiful Awakening', 'https://phimimg.com/upload/vod/20260513-1/b5059e83bfccd49f8adad57121fb1bac.jpg', 'https://phimimg.com/upload/vod/20260513-1/50e286d89bae80fa0a20aed53db93cb3.jpg', '<p>Một người đàn ông lạ mặt quấn toàn thân bằng màng bọc thực phẩm và dùng máy rung để chơi đùa với anh. Một người đàn ông cuồng rau củ nhét một quả mướp đắng vào miệng anh. Một người đàn ông mê hải sản nhét tôm vào miệng anh... Giờ đây, anh đang đối diện với chính mình lần đầu tiên. Đúng lúc này, người đàn ông nhớ ra mình đã gặp tai nạn giao thông...</p>', 'Full', 1, 'single', 'completed', 18, 2005, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshiaki Suzuki","avatar":""},{"name":"松浦祐也","avatar":""},{"name":"Atsushi Kusanagi","avatar":""},{"name":"Rentoku Miura","avatar":""},{"name":"荒木太郎","avatar":""},{"name":"平川直大","avatar":""},{"name":"佐々木麻由子","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Utsukushiki kakusei","美しき覚醒"]', 1784690324525);
