INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-cua-chu-cho-vang', 'Hang Của Chú Chó Vàng', 'The Cave Of The Yellow Dog', 'https://phimimg.com/upload/vod/20260509-1/5e8a4508be2be062087dc67d31f752d7.jpg', 'https://phimimg.com/upload/vod/20260509-1/e58d30d74d70d09cb1a7036f325938f4.jpg', '<p>Cô bé du mục Nansal tìm thấy một chú chó con trên thảo nguyên Mông Cổ, và chú chó trở thành người bạn thân nhất của cô bé - bất chấp sự phản đối của cha mẹ. Câu chuyện kể về một gia đình du mục Mông Cổ - lối sống truyền thống của họ và sức hút ngày càng tăng của thành thị.</p>', 'Full', 1, 'single', 'completed', 32, 2005, 'Thuyết Minh', 'FHD', 'Đức', 0, '[{"name":"Batchuluun Urjindorj","avatar":""},{"name":"Buyandulam Daramdadi","avatar":""},{"name":"Nansal Batchuluun","avatar":""},{"name":"Nansalmaa Batchuluun","avatar":""},{"name":"Batbayar Batchuluun","avatar":""},{"name":"Tserenpuntsag Ish","avatar":""},{"name":"Scharav Sumiya","avatar":""},{"name":"Battur Lhamsuren","avatar":""},{"name":"Batjargal Ulzidelger","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Cave of the Yellow Dog","Cave of the Yellow Dog","Die Höhle des gelben Hundes - Eine Geschichte aus der Mongolei","El perro mongol","Sarı Köpeğin Yuvası","Die Höhle des gelben Hundes","Shar nokhoïr tam","Jaskinia żółtego psa","Le Chien jaune de Mongolie","天空の草原のナンサ","Il cane giallo della Mongolia","Пещера желтого пса","小黃狗的窩","A sárga kutya barlangja","Keltaisen koiran luola","Шар нохойн там"]', 1784690324525);
