INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hang-cua-chu-cho-vang', 'Hang Của Chú Chó Vàng', 'The Cave Of The Yellow Dog', 'hang của chú chó vàng the cave of the yellow dog batchuluun urjindorj buyandulam daramdadi nansal batchuluun nansalmaa batchuluun batbayar batchuluun tserenpuntsag ish scharav sumiya battur lhamsuren batjargal ulzidelger the cave of the yellow dog cave of the yellow dog die höhle des gelben hundes - eine geschichte aus der mongolei el perro mongol sarı köpeğin yuvası die höhle des gelben hundes shar nokhoïr tam jaskinia żółtego psa le chien jaune de mongolie 天空の草原のナンサ il cane giallo della mongolia пещера желтого пса 小黃狗的窩 a sárga kutya barlangja keltaisen koiran luola шар нохойн там', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuon-sao-bang-ban-nhat-phan-1', 'Vườn Sao Băng (Bản Nhật) (Phần 1)', 'Boys Over Flowers (Hana Yori Dango) (Season 1)', 'https://phimimg.com/upload/vod/20250713-1/2de1ec1c1304c382cc76063073b68936.jpg', 'https://phimimg.com/upload/vod/20250713-1/e8ed7297d8cd3f69312aaed03fa9e275.jpg', '<p>Makino Tsukushi là học sinh nghèo duy nhất trong học viện Eitoku, một trường học đặc biệt dành cho các cậu ấm cô chiêu trên khắp Nhật Bản. Ngôi trường được cai trị bởi một nhóm 4 chàng trai đến từ các gia đình thế lực bậc nhất Nhật Bản với cái tên Flower 4 (F4): Domyoji Tsukasa, trưởng nhóm F4 và người thừa kế Tập đoàn Tài chính Toàn cầu Domyoji ; Hanazawa Rui, con trai ông chủ một công ty lớn; Nishikado Sojiro, một tay chơi có tiếng và là người thừa kế một đạo quán; và Mimasaka Akira, người có liên quan với thế giới ngầm. Nếu một học sinh làm mếch lòng F4, anh/cô ta sẽ nhận một thông báo màu đỏ, bị cả trường tẩy chay và cuối cùng phải rời trường.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 17, 2005, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mao Inoue","avatar":""},{"name":"Jun Matsumoto","avatar":""},{"name":"Shun Oguri","avatar":""},{"name":"Shota Matsuda","avatar":""},{"name":"Tsuyoshi Abe","avatar":""},{"name":"Toma Ikuta","avatar":""},{"name":"Mako Ishino","avatar":""},{"name":"Megumi Sato","avatar":""},{"name":"Aki Nishihara","avatar":""},{"name":"Aki Fukada","avatar":""},{"name":"Seto Saki","avatar":""},{"name":"Mayumi Sada","avatar":""},{"name":"Emiko Matsuoka","avatar":""},{"name":"David Ito","avatar":""},{"name":"Nanako Matsushima","avatar":""},{"name":"Shugo Oshinari","avatar":""},{"name":"Takako Katou","avatar":""},{"name":"Natsuki Kato","avatar":""},{"name":"Kento Han","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hana yori dango Drama","Hanadan","花より男子(2005)","花より男子2(リターンズ)","Boys Before Flowers","花より男子"]', 1784690324525);
