INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-phong-sai-gon', 'Giải Phóng Sài Gòn', 'Liberation of Saigon', 'https://phimimg.com/upload/vod/20250401-1/44e5e954f923b5aafed6ce5fa4869635.jpg', 'https://phimimg.com/upload/vod/20250401-1/5d69eb577c1f41d25071eca1cda63594.jpg', '<p>bộ phim truyện sử thi hoành tráng và đầy xúc động. Bối cảnh sinh động, tái hiện chân thực, bộ phim đã kể lại những dấu mốc chính của Chiến dịch Hồ Chí Minh lịch sử giải phóng Sài Gòn và hoàn toàn miền Nam, thống nhất đất nước. Phim có sự tham gia diễn xuất của các diễn viên như Hà Văn Trọng, Đức Nhuận, Hoàng Quân Tạo, Dương Trọng Hiếu, Thành Hội, Lan Hương, Thanh Thúy,...</p>', 'Full', 1, 'single', 'completed', 23, 2005, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Pham Cuong","avatar":""},{"name":"Quang Dai","avatar":""},{"name":"Tom Du Can","avatar":""},{"name":"Nguyen Si Hien","avatar":""},{"name":"Duong Trong Hieu","avatar":""},{"name":"Hua Thành Hoi","avatar":""},{"name":"Nguyen Tien Hoi","avatar":""},{"name":"Minh Hoàn","avatar":""},{"name":"Lan Hương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Giai phóng Sai Gòn","Liberation de Saïgon","Giải Phóng Sài Gòn"]', 1784690324525);
