INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-xuat-phan-1', 'Tái Xuất (Phần 1)', 'The Comeback (Season 1)', 'https://phimimg.com/upload/vod/20260422-1/3621bdced156cc3e155b2245e2d8b298.jpg', 'https://phimimg.com/upload/vod/20260422-1/2c5cdc5e002e5a12f9d84a8bbb796ef6.jpg', '<p>Đối với Valerie Cherish, không có cái giá nào là quá đắt để có thể níu giữ ánh hào quang sân khấu. Tuyệt vọng trong việc hồi sinh sự nghiệp đang lụi tàn của mình, cô đồng ý trở thành ngôi sao trong một chương trình truyền hình thực tế, cho phép máy quay theo sát mọi cử động khi cô giành được một vai diễn trong bộ phim hài tình huống (sitcom) mới của nhà đài.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 15, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lisa Kudrow","avatar":""},{"name":"Laura Silverman","avatar":""},{"name":"Damian Young","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["喜开二度","The Comeback"]', 1784690324525);
