INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doc-ma-vuot-ngan-dam', 'Độc Mã Vượt Ngàn Dặm', 'Riding Alone for Thousands of Miles', 'https://phimimg.com/upload/vod/20260409-1/933eaf9cf496427f809a37e0434d19f8.jpg', 'https://phimimg.com/upload/vod/20260409-1/d73619341fb49d941a6ae5ff6e6e96f1.jpg', '<p>Takada, một ngư dân Nhật Bản, đã xa cách con trai mình nhiều năm, nhưng khi con trai ông được chẩn đoán mắc bệnh ung thư giai đoạn cuối, con dâu ông, Rie, đã gọi ông đến bệnh viện. Qua một loạt những trở ngại và các mối quan hệ, ông bất ngờ hiểu rõ hơn về bản thân và con trai mình.</p>', 'Full', 1, 'single', 'completed', 20, 2005, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ken Takakura","avatar":""},{"name":"Shinobu Terajima","avatar":""},{"name":"Kiichi Nakai","avatar":""},{"name":"Ken Nakamoto","avatar":""},{"name":"Li Jia-Min","avatar":""},{"name":"Jiang Wen","avatar":""},{"name":"Lin Qiu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Riding Alone","Pour un fils","Qian li zou dan qi","Der einsame Tausendmeilenritt","単騎、千里を走る。","千里走单骑"]', 1784690324525);
