INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doc-ma-vuot-ngan-dam', 'Độc Mã Vượt Ngàn Dặm', 'Riding Alone for Thousands of Miles', 'độc mã vượt ngàn dặm riding alone for thousands of miles ken takakura shinobu terajima kiichi nakai ken nakamoto li jia-min jiang wen lin qiu riding alone pour un fils qian li zou dan qi der einsame tausendmeilenritt 単騎、千里を走る。 千里走单骑', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('24-gio-chong-khung-bo-phan-4', '24 Giờ Chống Khủng Bố (Phần 4)', '24 (Season 4)', 'https://phimimg.com/upload/vod/20260407-1/6806ed62fcb1531f477d020d9043ae36.jpg', 'https://phimimg.com/upload/vod/20260407-1/ecb64c92ef3d6192f74ca44a378dbe45.jpg', '<p>Đặc vụ Bauer làm việc cho tổ chức Counter Terrorist Unit (tạm dịch là Đơn vị chống khủng bố) &nbsp;tại Los Angeles. Bauer là một đặc vụ đầy kinh nghiệm và thành thạo &nbsp;trong cách tiếp cận cũng như tra khảo những đối tượng khủng bố nguy &nbsp;hiểm, nhưng đôi khi những cách này cũng rất tàn bạo. Hầu hết trong suốt &nbsp;cả loạt phim, yếu tố cốt truyện chính diễn ra giống như một bộ phim về &nbsp;chính trị. Còn cốt truyện điển hình trong phim là Bauer luôn phải chạy &nbsp;đua với thời gian trong nỗ lực ngăn chặn nhiều âm mưu khủng bố khác nhau &nbsp;bao gồm: âm mưu ám sát tổng thống, vũ khí hủy diệt hàng loạt, khủng bố &nbsp;bằng vũ khí sinh học, tấn công mạng Internet,... cũng như những âm mưu &nbsp;đối phó với chính phủ và tham nhũng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kiefer Sutherland","avatar":""},{"name":"Mary Lynn Rajskub","avatar":""},{"name":"Kim Raver","avatar":""},{"name":"Yvonne Strahovski","avatar":""},{"name":"Tate Donovan","avatar":""},{"name":"William Devane","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["24小时","24小时