INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-tich-phan-2', 'Mất Tích (Phần 2)', 'Lost (Season 2)', 'https://phimimg.com/upload/vod/20260201-1/0fdbb16cf0ab1304f1c702ae7b59a853.jpg', 'https://phimimg.com/upload/vod/20260201-1/497b38d3da6eded8d9a1dc106bfeb3da.jpg', '<p>Phim là câu chuyện về những con người sống sót trên chuyến bay Oceanic Airlines Flight 815 từ Sydney đến Los Angeles. Máy bay của họ rơi xuống một hòn đảo kỳ bí đâu đó ở Nam Thái Bình Dương với những hiện tượng không thể giải thích được. Xuyên suốt bộ phim là quá trình tìm kiếm đường trở về của những người sống sót, thông qua đó khám phá điều bí ẩn của hòn đảo và The Others - Một nhóm người đã ở trên đảo từ trước.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matthew Fox","avatar":""},{"name":"Evangeline Lilly","avatar":""},{"name":"Terry O''Quinn","avatar":""},{"name":"Josh Holloway","avatar":""},{"name":"Michael Emerson","avatar":""},{"name":"Jorge Garcia","avatar":""},{"name":"Naveen Andrews","avatar":""},{"name":"Jeff Fahey","avatar":""},{"name":"Nestor Carbonell","avatar":""},{"name":"Henry Ian Cusick","avatar":""},{"name":"Yunjin Kim","avatar":""},{"name":"Daniel Dae Kim","avatar":""},{"name":"Emilie de Ravin","avatar":""},{"name":"Ken Leung","avatar":""},{"name":"Zuleikha Robinson","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["迷失 (2004)","گمشدگان","گمشده","ロスト","Ｌ