INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-nhieu-bao-nhieu', 'Yêu Em Nhiều Bao Nhiêu', 'How Much Do You Love Me?', 'https://phimimg.com/upload/vod/20260123-1/5b10abdae6badfc9a0cbddb7940e3963.jpg', 'https://phimimg.com/upload/vod/20260123-1/44a3bb0af471e46f180c95de4f41c850.jpg', '<p>Sau khi trúng số, François đến một quán bar ở Pigalle và trả một trăm nghìn Euro mỗi tháng cho một cô gái điếm tên là Daniela để sống với anh ta như vợ cho đến khi hết tiền.</p>', 'Full', 1, 'single', 'completed', 19, 2005, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Monica Bellucci","avatar":""},{"name":"Bernard Campan","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"Jean-Pierre Darroussin","avatar":""},{"name":"François Rollin","avatar":""},{"name":"Jean Barney","avatar":""},{"name":"Baptiste Roussillon","avatar":""},{"name":"Valérie Karsenti","avatar":""},{"name":"Jean Dell","avatar":""},{"name":"Sara Forestier","avatar":""},{"name":"Michel Vuillermoz","avatar":""},{"name":"Édouard Baer","avatar":""},{"name":"Farida Rahouadj","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["挑逗性高潮","你爱我价几何","偷情爱美神","Combien tu m''aimes ?"]', 1784690324525);
