INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-mau-phu-thuy', 'Bảo Mẫu Phù Thủy', 'Nanny McPhee', 'https://phimimg.com/upload/vod/20260116-1/48f794852c2bbbb7cd05ab7044301cf4.jpg', 'https://phimimg.com/upload/vod/20260116-1/71942b19031dd8cab5cccc053ac63a42.jpg', '<p>Nanny McPhee là một bảo mẫu kỳ lạ sở hữu phép thuật đặc biệt, được thuê để chăm sóc bầy trẻ nghịch ngợm trong gia đình một ông bố góa vợ. Ban đầu, lũ trẻ tìm mọi cách đuổi cô đi vì ngoại hình khác thường và tính cách nghiêm khắc. Thế nhưng, qua những bài học bất ngờ, chúng dần học được kỷ luật, yêu thương và trách nhiệm. Khi bọn trẻ thay đổi, diện mạo của Nanny McPhee cũng dần trở nên hiền hòa và ấm áp hơn.</p>', 'Full', 1, 'single', 'completed', 17, 2005, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Emma Thompson","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Kelly Macdonald","avatar":""},{"name":"Thomas Brodie-Sangster","avatar":""},{"name":"Eliza Bennett","avatar":""},{"name":"Jennifer Rae Daykin","avatar":""},{"name":"Raphaël Coleman","avatar":""},{"name":"Samuel Honywood","avatar":""},{"name":"Holly Gibbs","avatar":""},{"name":"Hebe Barnes","avatar":""},{"name":"Zinnia Barnes","avatar":""},{"name":"Angela Lansbury","avatar":""},{"name":"Celia Imrie","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Elizabeth Berrington","avatar":""},{"name":"Derek","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Моя ужасная няня","Nanny McPhee - A varázsdada","La nana mágica: Nanny Mcphee","Νάνι Μακ Φι: Η Μαγική Νταντά","Nanny McPhee: A Babá Encantada","Няня МакФі","Nanny McPhee: a Ama Mágica","Nanny McPhee, la nana mágica","내니 맥피: 우리 유모는 마법사","내니 맥피; 우리 유모는 마법사","내니맥피 1; 우리 유모는 마법사","내니맥피 1: 우리 유모는 마법사","Nanny McPhee 1","Eine zauberhafte Nanny","Nanny McPhee"]', 1784690324525);
