INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bao-mau-phu-thuy', 'Bảo Mẫu Phù Thủy', 'Nanny McPhee', 'bảo mẫu phù thủy nanny mcphee emma thompson colin firth kelly macdonald thomas brodie-sangster eliza bennett jennifer rae daykin raphaël coleman samuel honywood holly gibbs hebe barnes zinnia barnes angela lansbury celia imrie imelda staunton elizabeth berrington derek моя ужасная няня nanny mcphee - a varázsdada la nana mágica: nanny mcphee νάνι μακ φι: η μαγική νταντά nanny mcphee: a babá encantada няня макфі nanny mcphee: a ama mágica nanny mcphee, la nana mágica 내니 맥피: 우리 유모는 마법사 내니 맥피; 우리 유모는 마법사 내니맥피 1; 우리 유모는 마법사 내니맥피 1: 우리 유모는 마법사 nanny mcphee 1 eine zauberhafte nanny nanny mcphee', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('40-tuoi-van-con-zin', '40 Tuổi Vẫn Còn Zin', 'The 40 Year Old Virgin', 'https://phimimg.com/upload/vod/20260116-1/5fa14a0dddda217e68b113201482e36f.jpg', 'https://phimimg.com/upload/vod/20260116-1/7cdf015e3c0968fc7b4b208bd6952ee9.jpg', '<p>Andy Stitzer 40 tuổi, làm công việc đóng dấu hoá đơn ở 1 cửa hàng điện tử, có 1 căn hộ xinh xắn, 1 bộ sưu tập những nhân vật hoạt hình đáng tự hào, những người bạn tốt, bản thân cũng là 1 người tốt bụng. Nhưng còn 1 điều mà hầu hết những người ở tuổi anh đều đã từng trải qua, nhưng anh thì chưa: Đó là Andy chưa từng nếm trải hương vị đàn bà. Bạn bè ở cửa hàng tìm mọi cách để giúp Andy, nhưng chẳng lần nào thành công, cho tới khi anh gặp Trish, 1 người mẹ 40 với 3 đứa con. Bạn bè của Andy dự đoán chuyện ấy có thể đã xảy ra... cho tới khi họ nghe tin rằng Andy và Trish đã bắt đầu mối quan hệ giữa họ dựa trên sự thỏa thuận là cả hai sẽ không có chuyện ấy...</p>', 'Full', 1, 'single', 'completed', 15, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Steve Carell","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Romany Malco","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Jane Lynch","avatar":""},{"name":"Gerry Bednob","avatar":""},{"name":"Shelley Malil","avatar":""},{"name":"Kat Dennings","avatar":""},{"name":"Jordan Masterson","avatar":""},{"name":"Chelsea Smith","avatar":""},{"name":"Jonah Hill","avatar":""},{"name":"Erica Vittina Phillips","avatar":""},{"name":"Marika Domińczyk","avatar":""},{"name":"Mindy Kaling","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["The 40 Year-Old Virgin","40 Ans Toujours Puceau","The 40-Year-Old Virgin","O Virgem de 40 Anos","The 40 Year Old Virgin: Unrated Edition","40 ans et encore puceau","光棍四十一枝花","The 40-Year-Old Virgin (Extended Version)","40-річний незайманий","Virgen A Los 40","40살까지 못해본 남자","40 il Bakir","Jungfrau 40 maennlich sucht","The 40 Year Old Virgin"]', 1784690324525);
