INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('40-tuoi-van-con-zin', '40 Tuổi Vẫn Còn Zin', 'The 40 Year Old Virgin', '40 tuổi vẫn còn zin the 40 year old virgin steve carell catherine keener paul rudd romany malco seth rogen elizabeth banks leslie mann jane lynch gerry bednob shelley malil kat dennings jordan masterson chelsea smith jonah hill erica vittina phillips marika domińczyk mindy kaling the 40 year-old virgin 40 ans toujours puceau the 40-year-old virgin o virgem de 40 anos the 40 year old virgin: unrated edition 40 ans et encore puceau 光棍四十一枝花 the 40-year-old virgin (extended version) 40-річний незайманий virgen a los 40 40살까지 못해본 남자 40 il bakir jungfrau 40 maennlich sucht the 40 year old virgin', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('king-kong-va-nguoi-dep', 'King Kong và Người Đẹp', 'King Kong', 'https://phimimg.com/upload/vod/20260108-1/aaa45fbdcf05df613619351a938dd6c1.jpg', 'https://phimimg.com/upload/vod/20260108-1/b9a5012a608743bdf33e04aafe0e4f90.jpg', '<p>Lấy bối cảnh năm 1933, khi cuộc đại khủng hoảng quét qua nước Mỹ, hàng loạt người phải ra đường vì thất nghiệp, và các diễn viên cũng không phải ngoại lệ. Trong cơn khốn khó, nữ diễn viên trẻ Ann như tìm được hy vọng khó tin khi nhận lời mời của tay đạo diễn Carl. Cả đoàn làm phim phiêu lưu tới hòn đảo Đầu lâu với tham vọng thực hiện bộ phim để đời. &nbsp;Đặt chân lên đảo, đoàn người đụng độ với những thổ dân ở đây. Ann bị bắt làm vật tế cho Kong, con dã nhân khổng lồ, nỗi khiếp sợ của những thổ dân. Những giây phút bị Kong bắt, Ann vô tình lại thuần hóa con vật khổng lồ này. Chính cô làm mồi nhử để đoàn người đánh thuốc mê Kong. &nbsp;Mọi chuyện trở nên tồi tệ khi Kong trở thành món hàng độc trưng bày trước công chúng ở New York và phá tung xiềng xích, thoát ra đường phố. Chỉ có Ann mới có thể làm nguôi con dã nhân...</p>', 'Full', 1, 'single', 'completed', 17, 2005, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Naomi Watts","avatar":""},{"name":"Adrien Brody","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Colin Hanks","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Jamie Bell","avatar":""},{"name":"Kyle Chandler","avatar":""},{"name":"Evan Parke","avatar":""},{"name":"Lobo Chan","avatar":""},{"name":"John Sumner","avatar":""},{"name":"Craig Hall","avatar":""},{"name":"Peter McKenzie","avatar":""},{"name":"William Johnson","avatar":""},{"name":"David Pittu","avatar":""},{"name":"Mark Hadlow","avatar":""},{"name":"Geraldine Brophy","avatar":""},{"name":"David Dennis","avatar":""},{"name":"Pip","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["金剛","کینگ کنگ","King Kong","キング・コング：2005"]', 1784690324525);
