INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-ba-smith', 'Ông Bà Smith', 'Mr. & Mrs. Smith', 'https://phimimg.com/upload/vod/20251228-1/b6826448618805dd719f647ab403efe8.jpg', 'https://phimimg.com/upload/vod/20251228-1/6bfa59bcf0a86ced6956aec17117f609.jpg', '<p>Mối tình của họ bắt đầu tình cờ khi John và Jane gặp nhau ở sảnh một khách sạn lớn. Jane gặp chút rắc rối với cảnh sát và John xuất hiện cứu nguy cho người đẹp. Sau đó họ bắt đầu hẹn hò, đi ăn, đi nhảy cùng nhau và cuối cùng là cưới nhau. &nbsp;Hai người làm việc cho những tổ chức bí mật, nhưng bà Smith lại ngụy trang bằng một công việc ở ban biên tập một tạp chí thời trang còn ông Smith thì ra dáng một doanh nhân quản lý công việc kinh doanh của gia đình. Họ nhận lệnh từ những người chủ khác nhau nhưng lại có nhiệm vụ giống nhau - cùng ám sát một người. Người này không hề biết gì về công việc của người kia cho đến khi họ cố truy tìm đối tượng thì họ trở thành đối thủ của nhau...</p>', 'Full', 1, 'single', 'completed', 38, 2005, 'Vietsub', 'FHD', 'Thụy Sĩ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Adam Brody","avatar":""},{"name":"Kerry Washington","avatar":""},{"name":"Keith David","avatar":""},{"name":"Chris Weitz","avatar":""},{"name":"Rachael Huntley","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Stephanie March","avatar":""},{"name":"Jennifer Morrison","avatar":""},{"name":"Theresa Barrera","avatar":""},{"name":"Perrey Reeves","avatar":""},{"name":"Melanie Tolbert","avatar":""},{"name":"Jerry T. Adams","avatar":""},{"name":"Elijah Alexander","avatar":""},{"name":"Han","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"ha