INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-den-madagascar', 'Cuộc Phiêu Lưu Đến Madagascar', 'Madagascar', 'https://phimimg.com/upload/vod/20250316-1/47cf367a623c460f2388d1214664debf.jpg', 'https://phimimg.com/upload/vod/20250316-1/0627e8e8ad3a096a4234c950056653ca.jpg', '<p>Tại sở thú trung tâm New York, một con sư tử, con ngựa vằn, một hươu cao cổ và một con hà mã kết bạn với nhau và chúng cũng là &quot;sao&quot; của các sô diễn. Rồi đến khi một con thú bị biến mất trong chuồng, thì ba con khác cũng thoát ra để tìm con thú bị lạc đã đi theo chiếc thuyền đến tận một hòn đảo của Madagascar - Châu Phi. Chiếc tàu bị lật ngoài biển, tất cả các con thú bị giam cầm đã nếm trải thế nào là môi trường hoang dã…</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2005, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Chris Rock","avatar":""},{"name":"David Schwimmer","avatar":""},{"name":"Jada Pinkett Smith","avatar":""},{"name":"Sacha Baron Cohen","avatar":""},{"name":"Cedric the Entertainer","avatar":""},{"name":"Andy Richter","avatar":""},{"name":"Tom McGrath","avatar":""},{"name":"Christopher Knights","avatar":""},{"name":"Chris Miller","avatar":""},{"name":"Conrad Vernon","avatar":""},{"name":"Eric Darnell","avatar":""},{"name":"David Cowgill","avatar":""},{"name":"Elisa Gabrielli","avatar":""},{"name":"Stephen Apostolina","avatar":""},{"name":"Devika","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Madagascar 1","마다가스카 1","M