INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-thuy-danh-bo', 'Lính Thủy Đánh Bộ', 'Jarhead', 'https://phimimg.com/upload/vod/20251216-1/b98f5e75f87d86130cf531c9fc6e71f6.jpg', 'https://phimimg.com/upload/vod/20251216-1/c3b204ac26f54d174be4ca3373c75a48.jpg', '<p>Jarhead cũng là một bộ phim chiến tranh như mọi bộ phim chiến tranh khác, nhưng khác hẳn với mọi bộ phim chiến tranh khác đó, Jarhead là câu chuyện thật về một người lính Mỹ. Jarhead không phải là câu chuyện kể về &quot;chúng tôi đã chiến đấu ra sao&quot;, mà là &quot;chúng tôi đã không chiến đấu ra sao&quot;. Jarhead không có nhiều cảnh action, không có nhiều cảnh giao chiến. Nói đúng ra, Jarhead là một bộ phim về chiến tranh không action, không giao chiến và cảm giác của người trong cuộc trong cuộc chiến ấy.Jarhead, nếu bạn không biết, có nghĩa lóng là US. Marine. Swoff, khi bị hỏi tại sao lại gia nhập Jarhead, đã trả lời &quot;Tôi bị lạc trên đường đến College&quot;. Một cảnh sau đó của bộ phim, Swoff được phỏng vấn và được đưa ra vài gợi ý cho &quot;Tại sao anh lại vào ...</p>', 'Full', 1, 'single', 'completed', 17, 2005, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Scott MacDonald","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Laz Alonso","avatar":""},{"name":"Lucas Black","avatar":""},{"name":"Brian Geraghty","avatar":""},{"name":"Damion Poitier","avatar":""},{"name":"Jocko Sims","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"John Krasinski","avatar":""},{"name":"Kevin Foster","avatar":""},{"name":"Riad Galayini","avatar":""},{"name":"Craig Coyne","avatar":""},{"name":"Katherine Randolph","avatar":""},{"name":"Rini Bell","avatar":""},{"name":"Den","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["鍋蓋頭","Merijalkaväen mies","Gušteri","Marinac","Marinec","Soldado anonimo","Máquina Zero","자헤드: 그들만의 전쟁","ジャーヘッド：2005","锅盖头","平頭日記","Jarhead"]', 1784690324525);
