INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-ky-an-phan-1', 'Giang Hồ Kỳ Án (Phần 1)', 'The Gentle Crackdown (Season 1)', 'https://phimimg.com/upload/vod/20251124-1/c4358aa2f843f308f6aff41ae0fbd281.jpg', 'https://phimimg.com/upload/vod/20251124-1/b87a6121c2e880d1d47deac557d7b46e.jpg', '<p>Đến khi trưởng thành, do cha là Lục thần bộ đã hy sinh trong trận hỏa hoạn để cứu một tử tù mà ông cho là vô tội, nên Lục Thập Nghĩa quyết tâm trở thành một bộ phái nghĩa hiệp. Nhưng dưới thời phong kiến, phụ nữ không thể đảm đương các chức vụ cao trong xã hội, nên Lục Thập Nghĩa phải tìm mọi cách để chứng tỏ mình không thua kém nam nhi. Được sự giúp đỡ của quan huyện mới nhậm chức là Thủy Đông Lâu (Trần Hào đóng), Lục Thập Nghĩa đã phá được nhiều vụ trọng án, đồng thời rửa sạch oan tình cho mẹ mình, trở thành trợ thủ đắc lực bên cạnh Thủy Đông Lâu. Cô đã làm thay đổi cái nhìn định kiến về người phụ nữ &quot;chân yếu tay mềm&quot; trong xã hội thời xưa.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 14, 2005, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Niki Chow Lai-Kei","avatar":""},{"name":"Moses Chan","avatar":""},{"name":"Michelle Yim","avatar":""},{"name":"Wayne Lai Yiu-Cheung","avatar":""},{"name":"Halina Tam Siu-Wan","avatar":""},{"name":"Mimi Chu Mai-Mai","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Cindy Au","avatar":""},{"name":"Eddy Ko Hung","avatar":""},{"name":"Johnson Lee Sze-Chit","avatar":""},{"name":"Mandy Lam Suk Man","avatar":""},{"name":"Ng Wai-San","avatar":""},{"name":"Candy Chiu Ching-Yee","avatar":""},{"name":"Lee Shing-Cheong","avatar":""},{"name":"Sunny Tai Yiu-Ming","avatar":""},{"name":"Isa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Sau Choi Yu Jeuk Bing","秀才遇著兵"]', 1784690324525);
