INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-xxx-lien-minh-chinh-phu-sieu-diep-vien-2', 'Điệp Viên xXx: Liên Minh Chính Phủ (Siêu Điệp Viên 2)', 'xXx: State Of The Union', 'https://phimimg.com/upload/vod/20251122-1/ebcc13e299881eb89a3767942ad21ffe.jpg', 'https://phimimg.com/upload/vod/20251122-1/3eb9f32f69905d854c63748e3844e8d5.jpg', '<p>Sau khi phá tan âm mưu cho nổ một trái bom sinh học của nhóm mafia Nga trong phần 1, giờ đây nhân viên NSA Gibbons lại phải tiếp tục tuyển mộ một tay điệp viên siêu hạng xXx khác cho nhiệm vụ mới. Điệp viên xXx này sẽ được gửi đến thủ đô Washington, DC, sử dụng tài năng của mình để lần theo dấu vết và đập tan âm mưu lật đổ chính quyền Hoa Kỳ. Đối đầu với xXx trong phần sequel này lại là một nhân vật có thế lực trong Nhà Trắng, đồng thời cũng là kẻ cầm đầu nhóm quân đội phân lập phản động chống lại Tổng thống...</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ice Cube","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Scott Speedman","avatar":""},{"name":"Peter Strauss","avatar":""},{"name":"Xzibit","avatar":""},{"name":"Michael Roof","avatar":""},{"name":"Sunny Mabrey","avatar":""},{"name":"Nona Gaye","avatar":""},{"name":"John Gleeson Connolly","avatar":""},{"name":"Ramon De Ocampo","avatar":""},{"name":"Barry Sigismondi","avatar":""},{"name":"J. Anthony Brown","avatar":""},{"name":"Bruce Bruce","avatar":""},{"name":"David Rountree","avatar":""},{"name":"Ned Schmidtke","avatar":""},{"name":"Lisa Joyner","avatar":""},{"name":"G","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình S