INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-sa-phan-1', 'Cần Sa (Phần 1)', 'Weeds (Season 1)', 'https://phimimg.com/upload/vod/20251112-1/3c717eb072dca629686000afe694f3a5.jpg', 'https://phimimg.com/upload/vod/20251112-1/55f0acaa09507793150fea599dacacd0.jpg', '<p>Sau cái chết đột ngột của chồng, một bà mẹ sống ở vùng ngoại ô phải tìm đến việc bán cần sa để nuôi gia đình.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mary-Louise Parker","avatar":""},{"name":"Justin Kirk","avatar":""},{"name":"Hunter Parrish","avatar":""},{"name":"Alexander Gould","avatar":""},{"name":"Kevin Nealon","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Ethan Kent","avatar":""},{"name":"Gavin Kent","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Spangli","علف‌ها","WEEDS～ママの秘密","Weeds ～ママの秘密","Косяки","Коноплі","Weeds"]', 1784690324525);
