INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('can-sa-phan-1', 'Cần Sa (Phần 1)', 'Weeds (Season 1)', 'cần sa (phần 1) weeds (season 1) mary-louise parker justin kirk hunter parrish alexander gould kevin nealon jennifer jason leigh ethan kent gavin kent spangli علف‌ها weeds～ママの秘密 weeds ～ママの秘密 косяки коноплі weeds', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ve-chang-vuong', 'Chuyện Về Chàng Vượng', 'Life Made Simple', 'https://phimimg.com/upload/vod/20251107-1/5523a9d2cb6b4d60f6af3f603ad2fccd.jpg', 'https://phimimg.com/upload/vod/20251107-1/4a8e8f6ea6a01cd7d74875b619aef6b0.jpg', '<p>Bộ phim kể về Đinh Thường Vượng, một chàng trai gần 30 tuổi nhưng thiểu năng trí tuệ như đứa trẻ 7 tuổi, sống cùng người mẹ hiếu thảo.Anh có mối tình thơ ấu sâu đậm với Kỳ Phụng, người anh gọi là "Vợ bé nhỏ". Vì giúp Phụng đi du học, Vượng đã hi sinh tiền đám cưới để chờ đợi cô.Bốn năm sau, Phụng về nước làm việc tại tập đoàn Chung Thị. Vượng theo vào công ty để bảo vệ cô, nơi anh gặp lại Chung Cẩm Vinh (cha ruột đã bỏ rơi anh) và Chung Tử Thông (anh trai cùng cha khác mẹ).Phim là câu chuyện về tình mẫu tử, tình yêu chân thành của Thường Vượng, và mối tình tay ba phức tạp khi Kỳ Phụng phải lựa chọn giữa một bên là Tử Thông giàu có, và một bên là Thường Vượng ngây thơ nhưng mang lại hạnh phúc thật sự.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 11, 2005, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trương Tịnh Sơ","avatar":""},{"name":"Dương Thiên Hoa","avatar":""},{"name":"Quách Phú Thành","avatar":""},{"name":"Lưu Thanh Vân","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324525);
