INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngot-dang-cuoc-doi', 'Ngọt Đắng Cuộc Đời', 'A Bittersweet Life', 'ngọt đắng cuộc đời a bittersweet life lee byung-hun kim yeong-cheol shin min-a kim roi-ha lee ki-young hwang jung-min eric mun oh dal-su kim hae-gon kim han jin goo lee hang-soo oh kwang-rok jeon kuk-hwan lee seung-ho kim seung-o lee han-sol vadym domashchenko sonny nico k dalkomhan insaeng a bittersweet life หวานขมปมชีวิต 不归路 кисло- сладкая жизнь горько-сладкая жизнь حياة حلوة ومرة یک زندگی تلخ و شیرین 甘い人生 го́речь и сла́дость słodko-gorzkie życie doce tortura o gosto da vingança ngọt đắng cuộc đời எ பிட்டர்ஸ்வீட் லைப் എ ബിറ്റർസ്വീറ്റ് ലൈഫ് горчиво-сладък живот 甜蜜的人生 不悔 ტკბილი ცხოვრების სიმწარე γλυκόπικρη ζωή סיפור מריר מתוק keserédes élet acı tatlı hayat гірко-солодкий присмак життя 달콤한 인생', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat', 'Cảnh Sát (Học cảnh hùng tâm)', 'The Academy', 'https://phimimg.com/upload/vod/20251023-1/2ec589aeadb85184d8ff3d525900f0e4.jpg', 'https://phimimg.com/upload/vod/20251023-1/b0645a31bbec068892e65fd122d2be04.jpg', '<p>Văn đăng ký vào trường đào tạo cảnh sát vì niềm đam mê, trong khi Kiệt chỉ vì muốn &quot;trả thù&quot; ông thầy Thắng của Học Viện Cảnh Sát. Hai người hai cá tính khác nhau nhưng lại chung một điểm là cứng đầu .

Họ không những có xích mích với nhau mà còn không ưa gì các ông thầy mặt lạnh như tiền trong trường Trải qua thời kỳ huấn luyện gian khổ, họ mới hiểu ra rằng, đằng sau những tấm mặt nạ lạnh lùng, các ông thầy của họ đều có một trái tim ấm áp.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 10, 2005, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Sammul Chan","avatar":""},{"name":"Ron Ng Cheuk-Hai","avatar":""},{"name":"Michael Miu Kiu-Wai","avatar":""},{"name":"Kathy Chow Hoi-Mei","avatar":""},{"name":"Michael Tse Tin-Wah","avatar":""},{"name":"Elanne Kwong Yeuk-Lam","avatar":""},{"name":"Leung Ka Ki","avatar":""},{"name":"Casper Chan","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Ellesmere Choi","avatar":""},{"name":"Dickson Lee Kar-Sing","avatar":""},{"name":"Dominic Lam Ka-Wah","avatar":""},{"name":"Joel Chan","avatar":""},{"name":"Dexter Yeung Tin-King","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["斗气冤家好兄弟","The Academy","Cảnh Sát","Học Cảnh Hùng Tâm","學警雄心"]', 1784690324525);
