INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-vo-hinh', 'Đảo Vô Hình', 'The Island', 'https://phimimg.com/upload/vod/20251023-1/5a03aff9aff730caaca32575aba0a0e3.jpg', 'https://phimimg.com/upload/vod/20251023-1/f31636fd62262b310880a812ee4975eb.jpg', '<p>Tình cờ, Lincoln phát hiện ra những người được chọn bị giết chết để lấy đi những cơ quan nội tạng nhằm phục vụ cho giao dịch mua bán có tầm cỡ quốc tế. Anh đã kịp thời cứu sống cô bạn gái của mình - Sarah Jordan.Cả hai phải chiến đấu để trốn thoát khỏi sự truy sát của những tay sát thủ chuyên nghiệp có sự tiếp tay của cảnh sát và FBI. Nhưng điều họ muốn làm nhất lúc này chính là việc quay trở lại để tìm hiểu sự thật và cảnh báo những cư dân vô tội về âm mưu này...</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Ethan Phillips","avatar":""},{"name":"Brian Stepanek","avatar":""},{"name":"Noa Tishby","avatar":""},{"name":"Siobhan Flynn","avatar":""},{"name":"Troy Blendell","avatar":""},{"name":"Jamie McBride","avatar":""},{"name":"Kevin McCorkle","avatar":""},{"name":"Gary Nickens","avatar":""},{"name":"Kathleen Rose Perkins","avatar":""},{"name":"Katy Boyer","avatar":""},{"name":"W","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug