INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('family-guy-phan-4', 'Family Guy (Phần 4)', 'Family Guy (Season 4)', 'family guy (phần 4) family guy (season 4) seth macfarlane alex borstein mila kunis seth green patrick warburton arif zahir გრიფინები keluarga pria مرد خانه خانواده‌ دوست 쇼킹 패밀리 쇼킹패밀리 परिवारको केटा сім’янин ґріффіни family guy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-thuat-phan-8', 'Phép Thuật (Phần 8)', 'Charmed (Season 8)', 'https://phimimg.com/upload/vod/20250915-1/c9c157785195a43aea308785665b86b3.jpg', 'https://phimimg.com/upload/vod/20250915-1/edc19366ec0bf194b72b534fa2a24494.jpg', '<p>Charmed (Phép Thuật) là bộ phim dài tập của Mỹ gồm 8 phần kể về những chị em gái nhà Halliwell. Họ là những phù thuỷ tốt có phép thuật. Mỗi chị em gái sở hũu một phép thuật khác nhau với những quyền năng và sức mạnh khác nhau. Và phép thuật của họ mạnh mẽ hơn cả khi họ kết hợp với nhau, tạo thành “Bộ ba phép thuật” quyền năng và mạnh mẽ. Họ với phép thuật của mình chống lại những thế lực hắc ám, chiến đấu, chống lại lũ quỷ và bè lũ thợ săn phù thủy. Với “Cuốn sách của bóng tối” làm bạn, làm “người dẫn đường”, họ đã từng bước trưởng thành trong cuộc sống. Sức mạnh của họ ngày càng phát triển, và chính vì thế, những mối nguy hiểm đối với họ ngày càng gia tăng. Họ - những chị em gái nhà Halliwell – luôn kiên cường, mạnh mẽ chống lại cái ác, bảo vệ người vô tội. Mỗi tập phim kể về một câu chuyện nhỏ trong cuộc sống của ba chị em, xen vào đó là những yếu tố hài hước và chân thực trong cuộc sống thường ngày.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 12, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Holly Marie Combs","avatar":""},{"name":"Alyssa Milano","avatar":""},{"name":"Rose McGowan","avatar":""},{"name":"Brian Krause","avatar":""},{"name":"Kaley Cuoco","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fc