INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tinh-ca-buon', 'Bản Tình Ca Buồn', 'Sad Love Story', 'https://phimimg.com/upload/vod/20250905-1/14d11bd7669405ce94dcc700bcb52d66.jpg', 'https://phimimg.com/upload/vod/20250905-1/975cf420d45644de4faa9c373001ccf4.jpg', '<p>Bộ phim&nbsp;kể về mối tình tay ba đầy nước mắt giữa Jun-young – chàng nhạc sĩ nghèo, Hye-in – cô gái mù giàu tình cảm, và Gun-woo – người bạn thân. Sau nhiều năm xa cách, họ gặp lại nhau trong những mâu thuẫn giữa tình yêu, tình bạn và sự nghiệp, để rồi câu chuyện kết thúc bằng một bản tình ca buồn đúng như tên gọi.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 2005, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"MC Mong","avatar":""},{"name":"Jin Hee-kyung","avatar":""},{"name":"Kwon Sang-woo","avatar":""},{"name":"Yeon Joo Kim","avatar":""},{"name":"Kim Hee-seon","avatar":""},{"name":"Lee Yeong-ha","avatar":""},{"name":"Nah Young Hee","avatar":""},{"name":"Yeon Jeong-hun","avatar":""},{"name":"Jung Woo","avatar":""},{"name":"Kim Hee-jung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["슬픈 연가"]', 1784690324525);
