INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-than-tiet-khi-su-cuoi-cung-cuon-1-thuy', 'Thế Thần: Tiết Khí Sư Cuối Cùng (Cuốn 1: Thủy)', 'Avatar: The Last Airbender (Book One: Water)', 'https://phimimg.com/upload/vod/20250812-1/e34a8b24b10f7a3a16a4c76bd04f095b.jpg', 'https://phimimg.com/upload/vod/20250812-1/286905161129eddad77558e69bd12ae3.jpg', '<p>Khi một cậu bé tìm thấy trong tảng băng được rã đông, thế giới biết được rằng cậu là Thế Thần mà họ hằng mong đợi, và số phận của cậu thay đổi chóng mặt.</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 22, 2005, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zach Tyler Eisen","avatar":""},{"name":"Mae Whitman","avatar":""},{"name":"Jack De Sena","avatar":""},{"name":"Dante Basco","avatar":""},{"name":"Jessie Flower","avatar":""},{"name":"Dee Bradley Baker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Avatar: De Legende van Aang","Avatar - A Lenda de Aang","Avatar - The Last Airbender","Avatar: la leyenda de Aang","Avatar: El Último Maestro Aire","降世神通: 最後的氣宗","降世神通：最后的气宗","Avatar: The Legend of Aang","ავატარი: ჰაერის უკანასკნელი მბრძანებელი","Άβαταρ: Ο Τελευταίος Μαχητής του Ανέμου","Άβαταρ: Ο Τελευταίος Ανεμοδαμαστής","Avatár - Aang legendája","Avatar: An tAer-Lúbóir Deiridh","אווטאר: האגדה של אנג","آواتار: افسانه آنگ","آواتار: آخرین باد افزار","Avatar - La leggenda di Aang","アバター 伝説の少年アン","아바타: 아앙의 전설","Awatar: Legenda Aanga","Avatar: O Último Airbender (2005)","Avatar: Legenda lui Aang","آفاتا