INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-than-tiet-khi-su-cuoi-cung-cuon-1-thuy', 'Thế Thần: Tiết Khí Sư Cuối Cùng (Cuốn 1: Thủy)', 'Avatar: The Last Airbender (Book One: Water)', 'thế thần: tiết khí sư cuối cùng (cuốn 1: thủy) avatar: the last airbender (book one: water) zach tyler eisen mae whitman jack de sena dante basco jessie flower dee bradley baker avatar: de legende van aang avatar - a lenda de aang avatar - the last airbender avatar: la leyenda de aang avatar: el último maestro aire 降世神通: 最後的氣宗 降世神通：最后的气宗 avatar: the legend of aang ავატარი: ჰაერის უკანასკნელი მბრძანებელი άβαταρ: ο τελευταίος μαχητής του ανέμου άβαταρ: ο τελευταίος ανεμοδαμαστής avatár - aang legendája avatar: an taer-lúbóir deiridh אווטאר: האגדה של אנג آواتار: افسانه آنگ آواتار: آخرین باد افزار avatar - la leggenda di aang アバター 伝説の少年アン 아바타: 아앙의 전설 awatar: legenda aanga avatar: o último airbender (2005) avatar: legenda lui aang آفاتار: مسخر الهواء الأخير avatar atla avatar: the last airbender', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('final-fantasy-vii-cuoc-hanh-trinh-cua-nhung-dua-tre', 'Final Fantasy VII: Cuộc Hành Trình Của Những Đứa Trẻ', 'Final Fantasy VII: Advent Children', 'https://phimimg.com/upload/vod/20250723-1/e6b75e1af23faca4295cefb4798348bc.jpg', 'https://phimimg.com/upload/vod/20250723-1/9fb5a693dc158c01ea4b21ffe07813d6.jpg', '<p>Hai năm trôi qua, kể từ khi Cloud Strife sử dụng năng lượng &quot;Dòng sinh mệnh&quot; để ngăn chặn sự huỷ diệt của Jenova, những mầm mống hủy diệt và bệnh tật của Jenova vẫn còn ảnh hưởng đến những đứa trẻ sống tại khu vực tập đoàn Shinra. Thêm vào đó, thế hệ tiếp theo của Cloud với đại diện là Kajah, muốn kế thừa ý nguyện của Jenova là hủy diệt toàn bộ sự sống trên hành tinh. Trong khi đó, Cloud lại tiếp tục lạc hướng trên con đường tìm ra con người thật của mình. Đồng thời, mầm mống phá hoại của Jenova trong người anh vẫn chưa hoàn toàn bị mất đi và cái chết của Aeris, đã bào mòn ý chí chiến đấu trong anh. Nhưng vì sinh mạng của những đứa trẻ vô tội và cũng vì bảo vệ cho những người mà mình thương yêu, Cloud buộc phải cầm kiếm chiến đấu...</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Takahiro Sakurai","avatar":""},{"name":"Ayumi Ito","avatar":""},{"name":"Showtaro Morikubo","avatar":""},{"name":"Maaya Sakamoto","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Taiten Kusunoki","avatar":""},{"name":"Yuji Kishi","avatar":""},{"name":"Shôgo Suzuki","avatar":""},{"name":"Masahiro Kobayashi","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Hideo Ishikawa","avatar":""},{"name":"Masachika Ichimura","avatar":""},{"name":"Miyu Tsuzurahara","avatar":""},{"name":"Kyousuke Ikeda","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Megumi Toyogu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Final Fantasy VII - Advent Children","Final Fantasy VII Advent Children","Final Fantasy VII-Advent Children","Final Fantasy VII: EL rescate","Fainaru Fantajî Sebun Adobento Chirudoren","Final Fantasy 7 - Advent''s Children","파이널 판타지 7 어드벤트 칠드런","最终幻想VII 降临之子","Final Fantasy VII: Advent Children Complete","最终幻想7 降临之子","ファイナルファンタジーVII アドベントチルドレン","Остання Фантазія 7: Останній наказ","Фінальна Фантазія VII: Останній наказ","파이널 판타지 7","太空戰士VII - 天子再臨","太空戰士：降臨之子","Final Fantasy 7: Djeca adventa","Final Fantasy VII 降臨神子","파이널 판타지 7; 어드벤트 칠드런 컴플리트","파이널 판타지 7: 어드벤트 칠드런 컴플리트","파이널 판타지 VII: 어드벤트 칠드런","파이널 판타지 VII; 어드벤트 칠드런","파이널 판타지 7; 어드벤트 칠드런","파이널 판타지 7: 어드벤트 칠드런","파이널 판타지 7 : 어드벤트 칠드런","Final Fantasy 7 - Advent Children Complete","Final Fantasy VII: Advent Children"]', 1784690324525);
