INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-tinh-vo', 'Gia Đình Tinh Võ', 'House Of Fury', 'https://phimimg.com/upload/vod/20250607-1/5b75df03a97b7bc7ea9e66e9a4290802.jpg', 'https://phimimg.com/upload/vod/20250607-1/a7877623d64f9cd9657225c10538a019.jpg', '<p>Một lực lượng đen tối đang cố truy lùng tung tích một cựu đặc nhiệm tên Tử Long để trả nợ máu, và chiếc chìa khoá để tìm ra Tử Long chính là Tiểu Bảo. Trong nỗi bàng hoàng và lo lắng khôn nguôi cho sự an nguy của cha, hai anh em phát hiện ra mình đang bị những đại cao thủ săn đuổi ráo riết, thì ra cha họ đã dấu hồ sơ bí mật của những lính đặc nhiệm về hưu trên người họ. Và cuộc chiến sinh tử đã bắt đầu</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Huỳnh Thu Sinh","avatar":""},{"name":"Ngô Ngạn Tổ","avatar":""},{"name":"Thái Trác Nghiên","avatar":""},{"name":"Chung Hân Đồng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Puños de furia","Naked Weapon 2","Дом гнева","Casa da Fúria - 2005","House of Fury","精武家庭"]', 1784690324525);
