INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('harry-potter-va-chiec-coc-lua', 'Harry Potter và Chiếc Cốc Lửa', 'Harry Potter and the Goblet of Fire', 'https://phimimg.com/upload/vod/20250602-1/a659814ab76a70bec26ee3b4bb35a645.jpg', 'https://phimimg.com/upload/vod/20250602-1/b7b55d9ad5585acd63a0d51717edbe7e.jpg', '<p>Khi giải Quidditch Thế giới bị cắt ngang bởi những kẻ ủng hộ Chúa tể Voldemort và sự trở lại của Dấu hiệu hắc ám khủng khiếp, Harry ý thức được rõ ràng rằng, Chúa tể Voldemort đang ngày càng mạnh hơn. Và để trở lại thế giới phép thuật, Chúa tể hắc ám cần phải đánh bại kẻ duy nhất sống sót từ lời nguyền chết chóc của hắn - Harry Potter. Vì lẽ đó, khi Harry bị buộc phải bước vào giải đấu Tam Pháp thuật uy tín nhưng nguy hiểm, cậu nhận ra rằng trên cả chiến thắng, cậu phải giữ được mạng sống của mình.</p>', 'Full', 1, 'single', 'completed', 16, 2005, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Robert Pattinson","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"David Tennant","avatar":""},{"name":"Predrag Bjelac","avatar":""},{"name":"Clémence Poésy","avatar":""},{"name":"Stanislav Yanevski","avatar":""},{"name":"Frances de la Tour","avatar":""},{"name":"Roger Lloyd Pack","avatar":""},{"name":"Miranda","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Harry Potter dhe Kupa e Zjarrit","ハリー・ポッターと炎のゴブレット","ハリーポッターと炎のゴブレット","הרי פותר וגביע האש","Harry Potter ja tulepeeker","哈利·波特与火焰杯","แฮร์รี่ พอตเตอร์กับถ้วยอัคนี","해리포터와 불의 잔","هاري بوتر وكأس النار","Հարրի Փոթերը և Կրակի գավաթը","هری پاتر و جام آتش","Harry Potter og Ildbegeret","Harry Potter 4","Harry Potter 4 - Goblet of Fire (2005)","Harry Potter 4 - The Goblet of Fire (2005)","HP4","Harry Potter and the Goblet of Fire"]', 1784690324525);
