INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thung-lung-soi', 'Thung Lũng Sói', 'Wolf Creek', 'https://phimimg.com/upload/vod/20250523-1/67e6337ff645efac555e1975478a4619.jpg', 'https://phimimg.com/upload/vod/20250523-1/ec888fe6a8d6c00ba3b72425bf06efd3.jpg', '<p>Một nhóm du khách ba lô bị mắc kẹt ở vùng hẻo lánh của nước Úc rơi vào tay một kẻ sát nhân ẩn náu trong rừng rậm. Hắn ban đầu giả vờ tốt bụng, đề nghị sửa xe giúp họ, nhưng sau đó lại bắt giữ và giam cầm họ, khiến họ phải đấu tranh để sinh tồn trong cơn ác mộng kinh hoàng giữa thiên nhiên hoang dã.</p>', 'Full', 1, 'single', 'completed', 37, 2005, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"John Jarratt","avatar":""},{"name":"Cassandra Magrath","avatar":""},{"name":"Kestie Morassi","avatar":""},{"name":"Nathan Phillips","avatar":""},{"name":"Gordon Poole","avatar":""},{"name":"Guy O''Donnell","avatar":""},{"name":"Phil Stevenson","avatar":""},{"name":"Geoff Revell","avatar":""},{"name":"Andy McPhee","avatar":""},{"name":"Aaron Sterns","avatar":""},{"name":"Michael Moody","avatar":""},{"name":"David Rock","avatar":""},{"name":"Teresa Palmer","avatar":""},{"name":"Paul Curran","avatar":""},{"name":"Aaron J. March","avatar":""},{"name":"Sean Gannon","avatar":""},{"name":"Darren Humphre","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wolf Creek 1","Wolf Creek - UR","Wolf Creek - OZ","El cazador de Wolf Creek","Viagem ao Inferno","Terreur à Wolf Creek","Wolf Creek - O apolytos tromos","Волчий ручей","Wolf Creek"]', 1784690324525);
