INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-thien-ha-sieu-nhan-spd', 'Cảnh Sát Thiên Hà (Siêu Nhân SPD)', 'Power Rangers SPD', 'https://phimimg.com/upload/vod/20250414-1/4403217c1c51a4526ec9c9813fba3d6d.jpg', 'https://phimimg.com/upload/vod/20250414-1/02cb8724e6543eeb70d009eb3bf313a9.jpg', '<p>Vào năm 2020, con người trái Đất làm quen với cuộc sống mới , sống chung với những Alien , một thời đại của công nghệ khoa học và triển. Power Rangers S.P.D Song song đó vẫn có những tay “Mafia” chuyên gấy chiến giữa các hình tinh với nhau để tạo thuận lợi cho việc buôn bán vũ khí , áo giáp ,……. Đứng đầu danh sách “đen” là Emperor Gruumm. Power Rangers S.P.D Hội đồng những người Alien đã thành lập lực lượng an ninh trên toàn vũ trụ nhằm bảo vệ toàn thể vũ trụ.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 13, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Deka Rangers, l''escadron d''enquêtes spéciales","Tokuso Sentai Dekaranger","特搜戰隊","Tokusō Sentai Dekarenjā","Tokusou sentai Dekarenjâ","Tokusou Sentai Dekaranger","파워레인저 S.P.D","특수전대 데카 레인저","특수전대 데카레인저","특수전대 데카렌쟈","특수 전대 데카 레인저","Special Investigation Squadron Detective Ranger","Special Investigation Dekaranger","Special Police Dekaranger","Power Rangers S.P.D","Super Sentai 28 - Dekaranger","特捜戦隊デカレンジャー"]', 1784690324525);
