INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('canh-sat-thien-ha-sieu-nhan-spd', 'Cảnh Sát Thiên Hà (Siêu Nhân SPD)', 'Power Rangers SPD', 'cảnh sát thiên hà (siêu nhân spd) power rangers spd  deka rangers, l''escadron d''enquêtes spéciales tokuso sentai dekaranger 特搜戰隊 tokusō sentai dekarenjā tokusou sentai dekarenjâ tokusou sentai dekaranger 파워레인저 s.p.d 특수전대 데카 레인저 특수전대 데카레인저 특수전대 데카렌쟈 특수 전대 데카 레인저 special investigation squadron detective ranger special investigation dekaranger special police dekaranger power rangers s.p.d super sentai 28 - dekaranger 特捜戦隊デカレンジャー', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-thuat-quyen-ru', 'Nghệ Thuật Quyến Rũ', 'The Art of Seduction', 'https://phimimg.com/upload/vod/20250411-1/9b2af4566c0785ab7663f361736e1fe8.jpg', 'https://phimimg.com/upload/vod/20250411-1/86257e6006e9f8d5cc2d6ece43b8b391.jpg', '<p>Han Ji Won, một mẫu phụ nữ hiện đại, hội tụ nhiều ưu điểm: xinh đẹp, tự tin, thông minh, nghề nghiệp ổn định. Nhưng điều đặc biệt nhất ở cô là khả năng diễn kịch không thua các nghệ sĩ trên sân khấu. Trên con đường tìm kiếm chàng hoàng tử hoàn hảo, cô đã biến tất cả bí quyết làm duyên làm dáng phái yếu thành một thứ vũ khí chết người. Tất cả những đối tượng mà cô đã tốn công “bài binh bố trận” đều đổ rầm rầm chỉ sau những màn như giả vờ tông xe, rồi chớp chớp mắt xin lỗi bằng gương mặt ngây thơ đáng yêu. Tất cả, chỉ trừ một người.</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Son Ye-jin","avatar":""},{"name":"Song Il-gook","avatar":""},{"name":"Ahn Sun-Young","avatar":""},{"name":"Woo Hyeon","avatar":""},{"name":"Jung Sung-il","avatar":""},{"name":"Ahn Sang-tae","avatar":""},{"name":"Hong Seok-cheon","avatar":""},{"name":"Hyun Young","avatar":""},{"name":"Noh Joo-hyun","avatar":""},{"name":"Park Jun-gyu","avatar":""},{"name":"Kim Ae-kyung","avatar":""},{"name":"Jung Jung-ah","avatar":""},{"name":"Kim Tae-jeong","avatar":""},{"name":"Lee Jung-hoon","avatar":""},{"name":"Geum Bo-ra","avatar":""},{"name":"Lee Mae-ri","avatar":""},{"name":"Park Yong-woo","avatar":""},{"name":"Song Yong-sik","avatar":""},{"name":"Ji San","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Jakeob-ui jeongseok","The Art of Seduction","Art.Of.Suduction","搭讪的法则","诱惑的艺术","작업의 정석"]', 1784690324525);
