INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-nang-tinh-ve-lap-bien', 'Chuyện Nàng Tinh Vệ Lấp Biển', 'Jing Wei Tian Hai', 'https://phimimg.com/upload/vod/20250409-1/5797fd2335b6a166446c1926cddb8d14.jpg', 'https://phimimg.com/upload/vod/20250409-1/7665c2573534fb3265c7568ab72eae0d.jpg', '<p>Bộ phim là một câu chuyện thần thoại của dân gian gắn liền với truyền thuyết lý giải những hiện tượng tự nhiên xảy ra trong thuở khai thiên lập địa. Những tình tiết trong bộ phim là khả năng sáng tạo và cách nhìn nhận về cuộc sống một cách phong phú của con người.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 32, 2005, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Kỳ Long","avatar":""},{"name":"Lý Giải","avatar":""},{"name":"Từ Thiếu Cường","avatar":""},{"name":"Thư Sướng","avatar":""},{"name":"Nhan Đơn Thân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Jing Wei Tian Hai","精卫填海"]', 1784690324525);
