INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-kiem-ky-hiep', 'Tiên Kiếm Kỳ Hiệp', 'Chinese Paladin', 'https://phimimg.com/upload/vod/20250314-1/71d1ad4cb3ac164e759486302e4510d9.jpg', 'https://phimimg.com/upload/vod/20250314-1/1bc510896227a76ed0f65115c1b3edd3.jpg', '<p>Lý Tiêu Dao là chàng trai ngây ngô, tuấn tú, thích cuộc sống ung dung tự tại. Tuy không có võ công cao cường nhưng lúc nào cũng luôn mong muốn trở thành thiên hạ đệ nhất cao thủ. Trước khi đi đến đảo tiên, anh đã bị ba người lạ mặt cho uống một viên thuốc lạ. Sau khi đến đảo tiên, anh đã gặp được Triệu Linh Nhi, hậu nhân của Nữ Oa. Cuộc gặp gỡ giữa cô và Lý Tiêu Dao ở chốn bồng lai tiên cảnh đã gắn kết cuộc đời của hai người với nhau. Trước khi rời đảo tiên, anh hứa sẽ trở lại đón Linh Nhi. Nhưng khi trở về, anh bị viên thuốc của 3 người lạ làm mất trí nên mọi chuyện trên đảo tiên anh đều quên hết. Đúng lúc đó, Linh Nhi bị bọn người của Bái Nguyệt giáo bắt đưa đến nhà của Tiêu Dao. May mắn thay, Tiêu Dao bắt gặp và giải cứu Linh Nhi nhưng anh lại không nhớ ra cô là ai. Tiêu Dao và Linh Nhi quen được Lâm Nguyệt Như là một tiểu thư ngang ngạnh, bướng bỉnh nhưng cũng rất tốt bụng và thiện lương. Từ đó, vận mệnh của ba người họ đã trở thành vòng luẩn quẩn khó tháo gỡ được.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 19, 2005, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"An Dĩ Hiên","avatar":""},{"name":"Lưu Diệc Phi","avatar":""},{"name":"Bành Vu Yến","avatar":""},{"name":"Hồ Ca","avatar":""},{"name":"Từ Cẩm Giang","avatar":""},{"name":"Lưu Phẩm Ngôn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["仙剑一","仙剑奇侠传一","仙剑奇侠传 2005","Меч и фея","The Sword and the Fairy","Xian Jian Qi Xia Zhuan","Legend of Sword and Fairy","Chinese Paladin","Sword and Fairy 1","仙剑奇侠传"]', 1784690324525);
