INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-su-voi-nang', 'Tâm sự với nàng', 'Monamour', 'https://phimimg.com/upload/vod/20250303-1/84049429493b2a95f49c9916dbac0137.jpg', 'https://phimimg.com/upload/vod/20250303-1/20553c455c4ec72e001f6962b1e1d492.jpg', '<p>Film xoay quanh một phụ nữ quyến rũ là Marta, chồng cô Dario là chủ của một nhà xuất bản lớn.
 Sự nghiệp của Dario đảm bảo cho Marta một cuộc sống đầy đủ và không phải lo nghĩ, tuy nhiên Marta vẫn có một điều chưa vừa lòng đó là chuyện chăn gối của hai người, mỗi lần “gần nhau” Dario đều “chưa đến chợ đã hết tiền tiêu” khiến Marta khá bất mãn, Marta mỗi đêm đều trút bầu tâm sự của mình vào nhật kí. Một ngày nọ Marta gặp được Leon, một nghệ sĩ nghiệp dư đẹp trai trong một triển lãm tranh.
 Một nghệ sĩ lãng tử đa tình và một phụ nữ thiếu thốn tình cảm làm sao thoát khỏi vòng dây tình ái, Leon mang đến cho Marta những gì mà Dario chồng cô không thể đáp ứng được, những trải nghiệm mới với Leon đều được cô lưu giữ vào nhật kí của mình. Cuốn nhật kí của Marta rồi thì cũng đến tay DarioLà một film về tình dục của Ý nên các cảnh sex trong film khá táo bạo, các bạn xem qua sẽ có cảm giác hơi không quen, tuy nhiên film có một thông điệp rõ ràng, khá thích hợp với những cặp vợ chồng mới cưới.</p>', 'Full', 1, 'single', 'completed', 18, 2005, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Anna Jimskaia","avatar":""},{"name":"Riccardo Marino","avatar":""},{"name":"Max Parodi","avatar":""},{"name":"Nela Lucic","avatar":""},{"name":"Lucia Lucchesino","avatar":""},{"name":"Virginia Barrett","avatar":""},{"name":"Daniela Machi","avatar":""},{"name":"Paolo Lanza","avatar":""},{"name":"Tinto Brass","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["放荡的情欲","Μοναμούρ","Моя любов","Monamour: Любовь моя","Mon Amour","Tinto Brass: Monamour","My Love","奸情","ティント・ブラスの白日夢","مونامور","Monamour"]', 1784690324525);
