INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dep-bao-thu', 'Người Đẹp Báo Thù', 'Lady Vengeance', 'https://phimimg.com/upload/vod/20250226-1/a40970cd51172c2a632da3dbd92e4710.jpg', 'https://phimimg.com/upload/vod/20250226-1/231302b6cc99dcf2d31367037328f613.jpg', '<p>Sau 13 năm tù vì tội bắt cóc và giết hại cậu bé 6 tuổi, Lee Guem-ja xinh đẹp bắt đầu tìm cách trả thù người đàn ông thực sự chịu trách nhiệm cho cái chết của cậu bé. Với sự giúp đỡ của những người bạn tù và đoàn tụ với con gái, cô ngày càng tiến gần hơn đến mục tiêu của mình. Nhưng liệu hành động của cô ấy có dẫn đến sự nhẹ nhõm mà cô ấy đang tìm kiếm?</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Young-ae","avatar":""},{"name":"Choi Min-sik","avatar":""},{"name":"Kwon Yea-young","avatar":""},{"name":"Kim Si-hoo","avatar":""},{"name":"Nam Il-woo","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Lee Seung-shin","avatar":""},{"name":"Kim Bu-seon","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Koh Soo-hee","avatar":""},{"name":"Seo Young-ju","avatar":""},{"name":"Kim Jin-goo","avatar":""},{"name":"Kim Ik-tae","avatar":""},{"name":"Lee Yeong-mi","avatar":""},{"name":"Jang Jeong-ae","avatar":""},{"name":"Choi Jung-woo","avatar":""},{"name":"Park Myung-shin","avatar":""},{"name":"Lee Yong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Chinjeolhan geumjassi","Lady Vengeance - Leben für die Rache","I ekdikisi mias kyrias","Simpatía por la mujer venganza","Simpatija za gdu. Osvetnicu