INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-ghe-xanh', 'Chiếc Ghế Xanh', 'Green Chair', 'https://phimimg.com/upload/vod/20250223-1/4de9266c07969087e70d2aa41d8ce2bb.jpg', 'https://phimimg.com/upload/vod/20250223-1/402af5e03f92515d702b7888075895fe.jpg', '<p>Khi phải lòng một chàng trai trẻ đẹp trai, một bà nội trợ Hàn Quốc thấy mình là trung tâm của một vụ bê bối tình dục và bị săn đuổi bởi các nhà báo lá cải đói khát. Cô thề sẽ loại anh ta ra khỏi cuộc đời mình nhưng rồi anh ta đến tuổi hợp pháp.</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Suh Jung","avatar":""},{"name":"Shim Ji-ho","avatar":""},{"name":"Oh Youn-hong","avatar":""},{"name":"Kim Hye-ok","avatar":""},{"name":"Kim Jeon-han","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Noksaek uija","녹색의자","녹색 의자"]', 1784690324525);
