INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-hoi-den-1', 'Xã Hội Đen 1', 'Election', 'https://phimimg.com/upload/vod/20250219-1/3f20100c92ea4e40357f1e104297214a.jpg', 'https://phimimg.com/upload/vod/20250219-1/d8095997fc724ed129bf42aa2dc13dd6.jpg', '<p>Sóng gió nổi dậy mỗi lần Hội Tam Hoàng tìm người kế nhiệm cho nhiệm kỳ 2 năm cầm quyền lãnh đạo Hội. Lần này hai ứng cử viên sáng giá cho chức vụ tối cao ấy là Đại D và A Lực. Hai người đại diện cho 2 tính cách đối lập: Đại D thì hùng hổ, hiếu chiến còn A Lực thì thâm trầm. Để dành phiếu cho cuộc chạy đua, cả hai không ngại dùng mọi thủ đoạn với cả những người cùng Hội. Mọi thứ chỉ ngã ngũ khi chiếc Long đầu côn - biểu tượng quyền lực tối cao của Hội nằm trong tay một trong hai người tranh cử. Liệu có bao nhiêu máu phải đổ cho cuộc chạy đua tàn khốc ấy và ai là người thắng cuộc cuối cùng?</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Tony Leung Ka-Fai","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Nick Cheung Ka-Fai","avatar":""},{"name":"Gordon Lam Ka-Tung","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Wong Tin-Lam","avatar":""},{"name":"Tam Bing-Man","avatar":""},{"name":"Maggie Siu Mei-Kei","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"You Yongzhi","avatar":""},{"name":"Wang Chung","avatar":""},{"name":"Chan Siu-Pang","avatar":""},{"name":"Yuen Bun","avatar":""},{"name":"Berg Ng Ting-Yip","avatar":""},{"name":"Ronald Yan Ma","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Black Society","Election: Vol 1","Election: Volume 1","Eleição","Eleição - O Submundo do Poder","Hei she hui","I triada","Longcheng suiyue","黑社会1：龙城岁月","Election 1","エレクション","Election","Hak se wui","Hēi Shè Huì","흑사회","龙城岁月","Hak se wooi","Wybór mafii","エレクション：2005","エレクション 黒社会","黑社會"]', 1784690324525);
