INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xa-hoi-den-1', 'Xã Hội Đen 1', 'Election', 'xã hội đen 1 election simon yam tony leung ka-fai louis koo nick cheung ka-fai gordon lam ka-tung eddie cheung lam suet wong tin-lam tam bing-man maggie siu mei-kei david chiang da-wei you yongzhi wang chung chan siu-pang yuen bun berg ng ting-yip ronald yan ma black society election: vol 1 election: volume 1 eleição eleição - o submundo do poder hei she hui i triada longcheng suiyue 黑社会1：龙城岁月 election 1 エレクション election hak se wui hēi shè huì 흑사회 龙城岁月 hak se wooi wybór mafii エレクション：2005 エレクション 黒社会 黑社會', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-tac-hen-ho', 'Quy Tắc Hẹn Hò', 'Rules Of Dating', 'https://phimimg.com/upload/vod/20250210-1/20764c7911e8edf3995fcf7b6011d890.jpg', 'https://phimimg.com/upload/vod/20250210-1/8afd0cecf5689b495544f96862c18d21.jpg', '<p>Một người phụ nữ sống nội tâm, thờ ơ gia nhập một trường trung học với tư cách là một giáo viên học sinh, dưới sự giám sát của một người đàn ông vô liêm sỉ, trẻ hơn cô một tuổi. Trong một chuyến đi học, người giám sát nói với học viên rằng anh ta muốn quan hệ tình dục với cô ấy. Bộ phim đề cập đến người phụ nữ sẵn sàng nhưng vẫn thờ ơ với mối quan hệ thể xác với tiền bối chuyên nghiệp của mình. Đạo đức, luân lý, tình cảm, tình yêu hiện lên rồi bị bác bỏ.</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Hae-il","avatar":""},{"name":"Kang Hye-jung","avatar":""},{"name":"Grina Park","avatar":""},{"name":"Seo Young-hwa","avatar":""},{"name":"Park Jin-woo","avatar":""},{"name":"Woo Ki-hong","avatar":""},{"name":"Jung Young-ki","avatar":""},{"name":"Lee Hyun-Jung","avatar":""},{"name":"Kim Se-dong","avatar":""},{"name":"Choi Jae-hwan","avatar":""},{"name":"Kim Ja-young","avatar":""},{"name":"Kim Shin-rock","avatar":""},{"name":"Choi Sun-joong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Yeonae-ui mokjeok","Purpose Of Love","연애의 목적"]', 1784690324525);
