INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-house-phan-2', 'Bác Sĩ House (Phần 2)', 'House (Season 2)', 'https://phimimg.com/upload/vod/20250103-1/dd09f739e7cedf8a3afc386308f91fa5.jpg', 'https://phimimg.com/upload/vod/20250103-1/a3256f3df31872138c784f91a60cbdc5.jpg', '<p>House M. D. ( Bác Sĩ House M. D.) là bộ phim về y học mang yếu tố tâm lý pha lẫn hài hước, hồi hộp và một chút gì đó trinh thám. Câu chuyện xoay quanh những căn bệnh quái lạ và những cách chữa độc chiêu của bác sĩ House – là một bác sĩ tài năng quái dị, chỉ có nửa cơ ở chân phải và là người đứng đầu khoa chuẩn đoán bệnh viện thực hành Princeton-Plainsboro cùng với các đồng nghiệp. Đan xen giữa những căn bệnh đó là những mẩu chuyện nhỏ, cuộc sống và mối quan hệ giữa House và các đồng nghiệp</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 15, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Laurie","avatar":""},{"name":"Robert Sean Leonard","avatar":""},{"name":"Omar Epps","avatar":""},{"name":"Jesse Spencer","avatar":""},{"name":"Odette Annable","avatar":""},{"name":"Peter Jacobson","avatar":""},{"name":"Charlyne Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Doctor House","豪斯医生","House - Medical Division","دکتر هاوس","ドクター・ハウス","닥터 하우스","Доктор Гаус","House M.D.","House"]', 1784690324525);
