INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-ho-mot-nha', 'Ba Họ Một Nhà', 'A Handful Of Love', 'https://phimimg.com/upload/vod/20241214-1/3928001279c785bfb68576e15d3a089c.jpg', 'https://phimimg.com/upload/vod/20241214-1/e2bf31949e6b0a8f919474cc56fb33e5.jpg', '<p>Một đại họa đã ập đến một gia đình hạnh phúc, tai nạn giao thông đã cướp đi sinh mạng của người mẹ, nhưng thật không may người bố cũng bị ung thư và qua đời ngay sau đó, để lại năm đứa con mồ côi giữa dòng đời. Đôi vợ chồng trẻ Cố Gia Nguyên và Cốc Tuệ Đình đang chuẩn bị bước vào cuộc sống hai người thì nay phải thay anh chị chăm sóc năm đứa trẻ của họ, không chịu nổi cú sốc mất cả cha lẫn mẹ, cả lũ trẻ quyết định bỏ nhà ra đi, phải cực khổ lắm cậu mợ mới thuyết phục và giải thích cho bọn trẻ thì chúng mới chịu trở về.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 2005, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"馬德鐘","avatar":""},{"name":"Jessica Hester Hsuan","avatar":""},{"name":"Don Li","avatar":""},{"name":"Mimi Lo","avatar":""},{"name":"Vin Choi","avatar":""},{"name":"Rachel Poon","avatar":""},{"name":"Johnson Lee Sze-Chit","avatar":""},{"name":"廖啟智","avatar":""},{"name":"Gregory Charles Rivers","avatar":""},{"name":"艾威","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324525);
