INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-khach-vuot-thoi-gian', 'Kiếm Khách Vượt Thời Gian', 'The Legend Of Love', 'https://phimimg.com/upload/vod/20241207-1/cdfb76d725ead73c03238df88c3120f6.jpg', 'https://phimimg.com/upload/vod/20241207-1/28e500a0df0c8a7e65b2b714feec96fb.jpg', '<p>Mễ Thương (Lý Uy đóng) từ nhỏ nhà tan cửa nát, tất cả đều là do người sư thúc đi vào tà đạo Trần Hoằng Khai gây ra. Y vì muốn cướp đoạt bí kíp võ công của cha mẹ Mễ Thương mà giết chết cả nhà cậu, may nhờ có đại sư bá Tả Vô Sân cứu mạng kịp thời, Mễ Thương mới thoát khỏi đại nạn. Tả Vô Sân truyền dạy võ công cho Mễ Thương nhưng không hề kể cho cậu nghe thân thế thật sự của cậu, một ngày nôi Trần Hoằng Khai tìm được tung tích của họ và truy đuổi họ tới vực sâu, Mễ Thương và sư đệ rớt vào vòng xoáy thời gian bay tới tương lai năm 2003. Tại đây họ gặp được Cary, cô gái ngoài mặt tham tiền nhưng thật sự rất có nghĩa khí, cô dụ dỗ Mễ Thương ký hợp đồng làm diễn viên với cô. Ngày tháng trôi qua, Mễ Thương dần dần có tình cảm với Cary, nhưng Trần Hoằng Khai đã truy đuổi tới thời hiện đại, và định mệnh 2 người của 2 thế giới khác nhau không thể ở cùng nhau. Mễ Thương sẽ làm gì để bảo vệ tình yêu của mình?</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 18, 2005, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Lý Uy","avatar":""},{"name":"Trần Hảo","avatar":""},{"name":"Tôn Hưng","avatar":""},{"name":"Dương Quang","avatar":""},{"name":"Trương Bác","avatar":""},{"name":"Đường Vu Hồng","avatar":""},{"name":"Trương Diệu Dương Thể loại: Hành Động","avatar":""},{"name":"Võ Thuật - Kiếm Hiệp","avatar":""},{"name":"Xuyên Không","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493