INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhien-phan-1', 'Siêu Nhiên (Phần 1)', 'Supernatural (Season 1)', 'https://phimimg.com/upload/vod/20241124-1/0cf44c52a4dc496bc973cba8a4a8e23b.jpg', 'https://phimimg.com/upload/vod/20241124-1/0ea43d7f1d53c407571524e74fa011bb.jpg', '<p>Bộ phim kể về câu chuyện của hai anh em nhà Winchester rong rủi trên khắp nước Mỹ để tiêu diệt ma quỷ và những hình thái siêu nhiên khác.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 17, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jared Padalecki","avatar":""},{"name":"Jensen Ackles","avatar":""},{"name":"Misha Collins","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["凶鬼恶灵","სუპერნატურალი","SUPERNATURAL スーパーナチュラル","슈퍼내츄럴","Supernatural"]', 1784690324525);
