INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yen-hoa-tam-nguyet', 'Yên Hoa Tam Nguyệt', 'Misty Love In Palace Place', 'https://phimimg.com/upload/vod/20240711-1/47631e69a276101ab5de4e8b8425c73d.jpg', 'https://phimimg.com/upload/vod/20240711-1/d58ef1bd32de97a89e47375f36b2f47a.jpg', '<p><em>Phim nói về cuộc đời của nhà thơ người Mãn, tên Nạp Lan Dung Nhược, và những mối tình của ông, cùng tình bạn giữa Dung Nhược, Khang Hy và Sách Lạp Vượng (con của Sách vương gia) và những sự tranh chấp với vua Khang Hy. Nạp Lan Dung Nhược yêu hai người con gái, một là Khổng Tú Trinh, thê tử trông phần mộ của vua Thuận Trị (cha Khang Hy). Về sau Dung Nhược yêu Thẩm Uyển, con gái của một phạm nhân triều đình và cũng là một người yêu thơ, nhưng Khang Hy cũng yêu Thẩm Uyển và lén thả cha nàng nhưng không dám công khai rửa sạch tội cho ông. Bên cạnh đó, tướng quân Tôn Diên Linh một lòng yêu Tú Trinh nhưng không được nàng đáp lại. Sau ông mưu phản cùng Ngô Tam Quế không thành. Nạp Lan Dung Nhược còn có một người vợ xinh đẹp nhưng bệnh hoạn tên Vũ Thiền, cũng hết lòng yêu anh. Bên cạnh những mối tình này là sự tranh chấp trong triều đình giữa Nạp Lan Minh Châu, cha của Nạp Lan Dung Nhược, và Ngao Bái, sau đó đến Sách vương gia. Tuy là con quan tể tướng nhưng Dung Nhược chưa bao giờ đoái hoài đến những danh phận tiền tài mà cha anh muốn có. Vì tham tiền hối lộ, Minh Châu cấu kết với một phú thương ở Giang Nam, từ đây con gái của phú thương này tên Quan Ánh Tâm đem long yêu Dung Nhược...</em></p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 11, 2005, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Hạo Dân","avatar":""},{"name":"Cao Viên Viên","avatar":""},{"name":"Đỗ Vũ Lộ","avatar":""},{"name":"Châu Hác Lôi","avatar":""},{"name":"Lã Hành","avatar":""},{"name":"Trương Na","avatar":""},{"name":"Trương Thần Quang","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324525);
