INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mangal-pandey-cuoc-noi-day', 'Mangal Pandey: Cuộc Nổi Dậy', 'Mangal Pandey: The Rising', 'https://phimimg.com/upload/vod/20240906-1/89cbebe7250db83c025a980e9f3da72e.jpg', 'https://phimimg.com/upload/vod/20240906-1/72d466a677d66251221de3f4c0f51471.jpg', '<p>Bộ phim dựa trên sự kiện, nhân vật có thật thời kỳ Ấn Độ bị Anh Quốc đô hộ. Sự kiện nổi dậy của đội quân nhà máy Đông Ấn kéo theo các cuộc nổi dậy khắp đất nước vào năm 1857 và cái chết của Mangal Pandey là tiền đề, là động lực cho cuộc kháng chiến của nhân dân Ấn, và cuộc kháng chiến kéo dài dòng dã 90 năm, Ấn Độ hoàn toàn được giải phóng vào 15/08/1947.</p>', 'Full', 1, 'single', 'completed', 9, 2005, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Aamir Khan","avatar":""},{"name":"Rani Mukerji","avatar":""},{"name":"Toby Stephens","avatar":""},{"name":"Ameesha Patel","avatar":""},{"name":"Om Puri","avatar":""},{"name":"Kirron Kher","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324525);
