INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-9-am-muu-tren-bien', 'Thám Tử Lừng Danh Conan 9: Âm Mưu Trên Biển', 'Detective Conan: Strategy Above the Depths', 'https://phimimg.com/upload/vod/20231019-1/ec974729f7fb7f607816635065d7b46a.jpg', 'https://phimimg.com/upload/vod/20231019-1/83acf2471428e1df30e87d785ce8b811.jpg', '<p>Bộ phim hoạt hình thứ 9 của bộ truyện tranh Thám tử lừng danh Conan lấy bối cảnh trên một con tàu du ngoại sang trọng &amp; đắt tiền. 15 năm trước, có một con tàu du ngoạn tên &quot;Yashiromaru&quot;, được đóng bởi tập đoàn Yashiro, bị đắm khi đang thả buồm. Hiện tại, có một con tàu mới, chiếc &quot;Saint Aphrodite&quot;, cũng được đóng bởi tập đoàn Yashiro. Conan, Sonoko &amp; những người khác là khách mời trên con tàu ấy. Ngày thứ 2 trên con tàu, bà chủ của dòng họ Yoshiro được phát hiện bị giết trong căn phòng của bà ta. Ngay sau đó, chủ tịch của tập đoàn Yashiro cũng bị phát hiện mất tích. Ông ấy đã bị ném từ trên con tàu xuống biển. Có vẻ như thủ phạm của 2 vụ án là cùng 1 người. Tại bữa tiệc chào mừng, thám tử Kogoro đưa ra suy luận của ...</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2005, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Yoshiko Sakakibara","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Atsuko Yuya","avatar":""},{"name":"Isshin Chiba","avatar":""},{"name":"Toru Okawa","avatar":""},{"name":"Kôji Nakata","avatar":""},{"name":"Shi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324525);
