INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-nguc-phan-1', 'Vượt Ngục (Phần 1)', 'Prison Break (Season 1)', 'https://phimimg.com/upload/vod/20240409-1/cd2cf1929e27de8a4f7fd7eb55921880.jpg', 'https://phimimg.com/upload/vod/20240409-1/2c89ca8656f2c1703427def10106e569.jpg', '<p>Prison Break là 1 serie phim truyền hình xuất sắc thuộc thể loại hình sự, bắt đầu được phát sóng tại Mỹ từ tháng 9 năm 2005, đến nay đã trải qua 4 seasons. Phần 1 với 22 tập và phần 4 vẫn đang chiếu. Phim chưa được phát sóng ở Việt Nam và cũng chưa được báo chí Việt Nam đưa tin mấy nên hầu như chúng ta vẫn chưa ai biết gì về nó . Thật đáng tiếc khi mà chúng ta vẫn đang phải đứng ngoài dòng chảy Prison Break trong khi cả thế giới đang lên cơn sốt với nó, độ hot không thua kém bất cứ 1 siêu phẩm phim nhựa nào của Hollywood đang được trình chiếu !!!</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 16, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dominic Purcell","avatar":""},{"name":"Wentworth Miller","avatar":""},{"name":"Amaury Nolasco","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Sarah Wayne Callies","avatar":""},{"name":"Wade Williams","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Paul Adelstein","avatar":""},{"name":"Marshall Allman","avatar":""},{"name":"Rockmond Dunbar","avatar":""},{"name":"Jodi Lyn O''keefe","avatar":""},{"name":"Robin Tunney","avatar":""},{"name":"Peter Stormare","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324525);
