INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tom-va-jerry-qua-nhanh-qua-nguy-hiem', 'Tom và Jerry: Quá Nhanh Quá Nguy Hiểm', 'Tom and Jerry: The Fast and the Furry', 'https://phimimg.com/upload/vod/20231026-1/85cfeba079bc2bb04686719c2b9567ff.jpg', 'https://phimimg.com/upload/vod/20231026-1/c24cace262cb2c9454753a7aada8f8c8.jpg', '<p>Sau khi bị chủ Tom đuổi khỏi ngôi nhà cũ vì gây thiệt hại lớn, mèo và chuột Tom và Jerry tham gia một cuộc đua mang tên &quot;Siêu đua tuyệt vời&quot;. để giành được một biệt thự.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlie Adler","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Jess Harnell","avatar":""},{"name":"Tom Kenny","avatar":""},{"name":"Bill Kopp","avatar":""},{"name":"Tress MacNeille","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Billy West","avatar":""},{"name":"J. Grant Albrecht","avatar":""},{"name":"Thom Pinto","avatar":""},{"name":"Neil Ross","avatar":""},{"name":"Renna Nightingale","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324525);
