INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wallace-gromit-loi-nguyen-cua-ma-tho', 'Wallace & Gromit: Lời Nguyền Của Ma Thỏ', 'Wallace & Gromit: The Curse of the Were-Rabbit', 'https://phimimg.com/upload/vod/20231026-1/a01762d268fdfff120a37be8f56ca956.jpg', 'https://phimimg.com/upload/vod/20231026-1/19b00293ab27eebbfd1ef2e409756c86.jpg', '<p>Wallace lập dị yêu phô mai và chú chó láu lỉnh Gromit điều tra một bí ẩn trong cuộc phiêu lưu hoạt hình của Nick Park, trong đó nhà phát minh đáng yêu và chú chó con dũng cảm của anh điều hành một doanh nghiệp tiêu diệt các loài gây hại trong vườn ở thị trấn. Chỉ sử dụng những phương pháp nhân đạo để biến ngôi nhà của họ thành nơi trú ẩn cho lũ sâu bọ bị đuổi khỏi nhà, cặp đôi tình cờ phát hiện ra một bí ẩn liên quan đến một con quái vật háu ăn ăn chay đe dọa phá hỏng cuộc thi trồng rau hàng năm.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2005, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Peter Sallis","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Peter Kay","avatar":""},{"name":"Nicholas Smith","avatar":""},{"name":"Liz Smith","avatar":""},{"name":"John Thomson","avatar":""},{"name":"Mark Gatiss","avatar":""},{"name":"Vincent Ebrahim","avatar":""},{"name":"Geraldine McEwan","avatar":""},{"name":"Edward Kelsey","avatar":""},{"name":"Dicken Ashworth","avatar":""},{"name":"Robert Horvath","avatar":""},{"name":"Pete Atkin","avatar":""},{"name":"Noni Lewis","avatar":""},{"name":"Ben Whitehead","avatar":""},{"name":"Christopher Fairb","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca8