INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-keo-phan-3', 'Dao Kéo (Phần 3)', 'Nip/Tuck (Season 3)', 'https://phimimg.com/upload/vod/20240627-1/1b8e0d2bb3a8bddedbc62456db0ad0b3.jpg', 'https://phimimg.com/upload/vod/20240627-1/0755a0d9498d11a1a19846cd57343de7.jpg', '<p>Hai bác sĩ phẫu thuật thẩm mỹ - một người đàn ông tận tụy với gia đình và một người là một tay chơi vô đạo đức - cố gắng duy trì công việc kinh doanh của mình trong khi phải vượt qua vô số khó khăn, từ cá nhân đến khách hàng có liên hệ tội phạm.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 11, 2005, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dylan Walsh","avatar":""},{"name":"Julian McMahon","avatar":""},{"name":"Joel Richardson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324525);
