INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-song-truy-lac', 'Lối Sống Trụy Lạc', 'Havoc', 'https://phimimg.com/upload/vod/20240620-1/71971decf090f9ba8ce096f976412ed7.jpg', 'https://phimimg.com/upload/vod/20240620-1/51d4e5b816728cf597eebde4442d8906.jpg', '<p>Havoc kể về hành trình lầm lạc của 2 cô gái con nhà giàu Allison (Anne Hathaway) và Emily (Bijou Phillips) khi họ bước vào thế giới của các băng nhóm găngxtơ Mỹ La tinh ở phía Đông Los Angeles. Ban đầu, họ chỉ tò mò muốn tìm hiểu những cảm giác mới mẻ, nhưng càng về sau họ càng lún sâu vào vòng xoáy của bạo lực, ma túy để rồi cuối cùng trở thành gái điếm. Trong phim có nhiều lời thoại sử dụng ngôn ngữ đường phố, nhiều cảnh sex và đánh đấm. Theo ý kiến của một số khán giả Mỹ trẻ tuổi trên các diễn đàn điện ảnh, nội dung của bộ phim không xa lạ với những vấn đề họ đang đối mặt trong cuộc sống hằng ngày.</p>', 'Full', 1, 'single', 'completed', 12, 2005, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Bijou Phillips","avatar":""},{"name":"Shiri Appleby","avatar":""},{"name":"Michael Biehn","avatar":""},{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Matt O''Leary","avatar":""},{"name":"Freddy Rodríguez","avatar":""},{"name":"Laura San Giacomo","avatar":""},{"name":"Mike Vogel","avatar":""},{"name":"Raymond Cruz","avatar":""},{"name":"Alexis Dziena","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Sam Hennings","avatar":""},{"name":"Cecilia Peck","avatar":""},{"name":"Josh Peck","avatar":""},{"name":"J. D. Pardo","avatar":""},{"name":"Terri H","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324525);
