INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-tinh-ngot-ngao', 'Lưới Tình Ngọt Ngào', 'The Intimate', 'https://phimimg.com/upload/vod/20240228-1/c8168519f06637b79ac3fbe835138473.jpg', 'https://phimimg.com/upload/vod/20240228-1/cdf11b140d80e911158d19b2fc9f597e.jpg', '<p>Lần đầu gặp nhau hôm nay, người đàn ông và người phụ nữ tiến tới sự thân mật kéo dài một ngày… Có lẽ việc chấp nhận lời cầu hôn từ một người hoàn toàn xa lạ chỉ là một ngày cho người phụ nữ đã hẹn hò với một người đàn ông được 7 năm này năm và ai sẽ kết hôn vào tháng tới. Tuy nhiên, cảm thấy nhẹ nhõm và phấn khích trước những cách thân mật mà “người đàn ông” này chạm vào và nhìn cô, lần đầu tiên trong đời cô cảm thấy bối rối và xao xuyến.</p>', 'Full', 1, 'single', 'completed', 19, 2005, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Sung Hyun-ah","avatar":""},{"name":"Cho Dong-Hyuk","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324525);
