INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('troi-buoc', 'Trói Buộc', 'Love Bond / Nợ Tình', 'https://phimimg.com/upload/vod/20240228-1/7b3e5cf6d8a77f85b101cf8587b334d1.jpg', 'https://phimimg.com/upload/vod/20240228-1/53cada285e208ae5d85826a1f9022513.jpg', '<p>Cha mẹ mất sớm, Nhất Giang là anh cả phải gánh vác toàn bộ mọi việc trong gia đình, dạy dỗ và nuôi nấng các em ăn học nên người, gây dựng cơ nghiệp. Sau khi chia tay với bạn gái, Nhất Giang về làm việc tại công ty của người em thứ hai. Trong một lần tình cờ, Nhất Giang phát hiện ra chàng trai đang sửa chữa cho tiệm trà nhà hàng xóm chính là người em trai Tam Hà lưu lạc bấy lâu nay của mình. Nhất Giang sẽ làm gì để đưa người em trai của mình trở về đoàn tụ với gia đình.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 16, 2005, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Đào Đại Vũ","avatar":""},{"name":"Quách Khả Doanh","avatar":""},{"name":"Trần Hào","avatar":""},{"name":"Liêu Bích Nhi","avatar":""},{"name":"Hướng Hải Lam","avatar":""},{"name":"Tần Bái","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324525);
