INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-giao-doan', 'Hắc Giáo Đoàn', 'Gray-Man', 'https://phimimg.com/upload/vod/20240220-1/fbe9ad5bd65c9135d0011b223d0d8d17.jpg', 'https://phimimg.com/upload/vod/20240220-1/e3f58e1d57c027e1311d28a45f09c4c8.jpg', '<p>Vào cuối thế kỷ 19, Allen Walker chính thức gia nhập tổ chức Exorcist và bắt đầu đi tiêu diệt các sinh vật được gọi là Akuma; vũ khí cơ khí do Thiên niên kỷ Earl với những linh hồn đau khổ của người chết. Allen có một con mắt bị nguyền rủa và vũ khí chống Akuma, mang sức mạnh của Innocence, một món quà dành cho anh là một tông đồ của Chúa. Allen, cùng với Exorcist đồng nghiệp của mình phải chấm dứt âm mưu cuối cùng của thiên niên kỷ của Earl có thể dẫn đến sự hủy diệt của thế giới và tất cả những ai sống trên đó.</p>', 'Hoàn Tất (71/71)', 71, 'hoathinh', 'completed', 16, 2005, 'Lồng Tiếng', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324525);
