INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-ong-lam-to', 'Mùa Ong Làm Tổ', 'Bee Season', 'https://phimimg.com/upload/vod/20240220-1/d8787250b68b26c2d87189aad37727d9.jpg', 'https://phimimg.com/upload/vod/20240220-1/f38d55edf3160372206bb55e58a18c4a.jpg', '<p>Trong Mùa Ong Làm Tổ - Bee Season, cô bé 12 tuổi chưa từng đóng phim Flora Cross đã tỏa sáng bên cạnh những bậc gạo cội Richard Gere và Juliette Binoche. Bộ phim của hai đạo diễn Scott McGehee và David Siegel dựa theo tiểu thuyết của Myla Goldberg, xoay quanh gia đình giáo sư Saul có cô con gái siêu việt. Sau này, trải qua nhiều nỗ lực, cô trở thành giảng viên trẻ tài năng, được nhiều người ngưỡng mộ.</p>', 'Full', 1, 'single', 'completed', 14, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Juliette Binoche","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"Flora Cross","avatar":""},{"name":"Richard Gere","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324525);
