INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('whats-new-scoobydoo-phan-3', 'What''s New, Scooby-Doo? (Phần 3)', 'What''s New, Scooby-Doo? (Season 3)', 'https://phimimg.com/upload/vod/20240215-1/eedc4e4c9a53d79780940ce074961829.jpg', 'https://phimimg.com/upload/vod/20240215-1/f47ee18acdf085ce761325d54db77a7d.jpg', '<p>Phần thứ ba có sự góp mặt của những người giải quyết tội phạm yêu thích của mọi người trong một số bối cảnh theo chủ đề thể thao. Từ một trận đấu vật thất bại đến một cuộc đua xe cổ bị ma ám, và thậm chí là một giải đấu gôn mini bị một chú hề kim loại khủng bố, cả nhóm vẫn giữ bình tĩnh ở bất kỳ đấu trường nào. Nhưng Phần Ba không chỉ mang đến những sự kiện thể thao ma quái khi băng nhóm săn ma toàn cầu đến thăm Paris, Moscow, Hồng Kông, Úc và Miền Tây Cổ. Ruh-roh, quả thật vậy!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 12, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Frank Welker","avatar":""},{"name":"Casey Kasem","avatar":""},{"name":"Mindy Cohn","avatar":""},{"name":"Grey DeLisle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324525);
