INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-ngoai-phi-tien', 'Thiên Ngoại Phi Tiên', 'The Little Fairy', 'https://phimimg.com/upload/vod/20240215-1/74cd45b308f7c442087284a5979036ac.jpg', 'https://phimimg.com/upload/vod/20240215-1/b5e8861d2828106b1476f61bf5283b9a.jpg', '<p>Thiên Ngoại Phi Tiên xoay quanh chuyện tình ly kỳ, đẹp đẽ của chàng thư sinh Đổng Vĩnh và nàng tiên nữ bướng bỉnh Tiểu Thất. Thất Công Chúa - Tiểu Thất do tính cách ngang ngạnh nên bị Ngọc Hoàng trừng trị, đày xuống trần gian. Nàng phải làm 100 việc tốt để phục hồi lại phép thuật. Trong khi đó, Đổng Vĩnh là chàng thư sinh thông minh, hiền lành, tốt bụng. Gặp Tiểu Thất, thế giới của Đổng Vĩnh thay đổi. Dù năm lần bảy lượt bị thiên đình và Ngọc Hoàng ngăn cản, bị đánh trọng thương, Đổng Vĩnh vẫn cố gắng vươn lên, tìm lại tình yêu của cuộc đời mình. Hành trình tình yêu của cặp đôi đã đem lại tiếng cười cũng như lấy đi nước mắt của nhiều khán giả.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 23, 2005, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Hồ Ca","avatar":""},{"name":"Lâm Y Thần","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324526);
