INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('choi-ngai-2', 'Chơi Ngải 2', 'Art Of The Devil II', 'https://phimimg.com/upload/vod/20240220-1/f456da00a1c3e5316edd23b72589ae47.jpg', 'https://phimimg.com/upload/vod/20240220-1/d58bbbe45c418b9c3cacd750156d098b.jpg', '<p>Một nhóm bạn học trung học đoàn tụ sau hai năm khi một trong những người cha tự tử của họ. Tất cả họ đều dành cả đêm tại địa điểm của bạn mình. Khi Darkness ngã, những điều kỳ lạ bắt đầu xảy ra với họ từng người một. Như thể ai đó đang sử dụng nghệ thuật đen trên họ để trả thù cho một hành động mà nhóm bạn này đã cam kết trở lại trường trung học</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'HD', 'Thái Lan', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324526);
