INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-dong-quai-vat', 'Hang Động Quái Vật', 'The Descent', 'https://phimimg.com/upload/vod/20240207-1/58bb940b752f4aceae186ecd2c3574c5.jpg', 'https://phimimg.com/upload/vod/20240207-1/79c5c17312a88672f555a4d8ea4870be.jpg', '<p>Một nhóm các bạn nữ do Juno dẫn đầu đã có một cuộc chạm trán với những kẻ khát máu khi họ bị mắc bẫy tại hang núi. Họ hoảng sợ nhưng sự sợ hãi thật sự đến từ trong bản thân của mỗi người họ...</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Shauna Macdonald","avatar":""},{"name":"Natalie Mendoza","avatar":""},{"name":"Alex Reid","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324526);
