INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-uc-ke-sat-nhan-2005', 'Hồi Ức Kẻ Sát Nhân', 'The Memory Of A Killer', 'https://phimimg.com/upload/vod/20240205-1/dce71d267e8751514dd9b64487368062.jpg', 'https://phimimg.com/upload/vod/20240205-1/6c86acf5779a941ad71db11b6fb9f3da.jpg', '<p>Vincke và Verstuyft là những thám tử tốt nhất của sở cảnh sát Antwerp. Họ đang phải đối mặt với vụ giết người liên quan tới một giám đốc điều hành và phải nỗ lực hết mình để có thể bắt kẻ giết người</p>', 'Full', 1, 'single', 'completed', 17, 2005, 'Vietsub', 'HD', 'Hà Lan', 0, '[{"name":"Koen De Bouw","avatar":""},{"name":"Werner De Smedt","avatar":""},{"name":"Jan Decleir","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
