INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-long-than-long-dac-canh', 'Mãnh Long - Thần Long Đặc Cảnh', 'Dragon Squad', 'https://phimimg.com/upload/vod/20240205-1/47541e05c1b093d2be84a611b781962c.jpg', 'https://phimimg.com/upload/vod/20240205-1/5089d890d51b29a518de45784d95523c.jpg', '<p>Chỉ huy Hon Sun (Nhậm Đạt Hoa) thực sự cần tới một sự giúp đỡ để đảm bảo việc chuyển an toàn tên Đoàn Vĩnh Hào tới tòa án. Hắn là một quân bài quan trọng của bọn mafia Hong Kong, tín đồ của những vụ trộm cướp và những vụ buôn bán bất chính thuộc mọi thể loại, là kẻ chịu trách nhiệm đối với cái chết của rất nhiều nhân viên cảnh sát vài năm trước đó. Nguyên nhân là do mối hận thù nhiều năm trước đó: anh trai của Vĩnh Hào là Đoàn Biên Hổ đã gây ra cái chết của em trai Petros, rồi ba năm trước đây, chính trong vụ án này, trung úy Ko đã cắt ngang đường Kong Long (Hồng Kim Bảo), một cảnh sát vi phạm nguyên tắc và đã gây nên một vụ đụng độ chết chóc. Cuộc chạm chán nảy lửa và không ít thương vong bắt đầu…</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Vanness Wu","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Yu Xia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
