INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-azumi-2-tinh-hay-tu', 'Sát Thủ Azumi 2: Tình Hay Tử', 'Azumi 2: Death Or Love', 'https://phimimg.com/upload/vod/20240128-1/0216015aa40920c14c366cca4f37dc7d.jpg', 'https://phimimg.com/upload/vod/20240128-1/eeba93a6b539cd2191164fe7dd04db88.jpg', '<p>Azumi tiếp tục cùng người bạn duy nhất sống sót hoàn thành sứ mệnh của mình. Trên cuộc hành trình cô gặp một chàng trai làm nghề ăn cướp có khuôn mặt y hệt người anh em năm xưa của cô. Sứ mệnh của Azumi là mong muốn chấm dứt chiến tranh, thế nhưng một khi tên tướng soái độc ác ấy chưa chết thì cô không thể hoàn thành sứ mệnh. Và sứ mệnh lần này khiến cô mất đi người bạn duy nhất của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Aya Ueto","avatar":""},{"name":"Yûma Ishigaki","avatar":""},{"name":"Chiaki Kuriyama","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
