INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-thu-azumi-2-tinh-hay-tu', 'Sát Thủ Azumi 2: Tình Hay Tử', 'Azumi 2: Death Or Love', 'sát thủ azumi 2: tình hay tử azumi 2: death or love aya ueto yûma ishigaki chiaki kuriyama ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('feast', 'Feast', 'Feast', 'https://phimimg.com/upload/vod/20240128-1/e459ba483c706aaef8c78f46c4d0b8e3.jpg', 'https://phimimg.com/upload/vod/20240128-1/aabf87c3a18164ec90dbfb5d4f010367.jpg', '<p>Bị mắc kẹt trong một quán rượu hẻo lánh, một nhóm người lạ phải liên kết với nhau để sinh tồn. Bên ngoài quán bar, một bầy quái vật ăn thịt hung hãn đang cố gắng đột nhập và ăn thịt những con người đang sợ hãi bên trong.</p>', 'Full', 1, 'single', 'completed', 14, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Henry Rollins","avatar":""},{"name":"Balthazar Getty","avatar":""},{"name":"Navi Rawat","avatar":""},{"name":"Judah Friedlander","avatar":""},{"name":"Jason Mewes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324526);
