INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('feast', 'Feast', 'Feast', 'feast feast henry rollins balthazar getty navi rawat judah friedlander jason mewes ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-thang-tu', 'Tuyết Tháng Tư', 'April Snow', 'null', 'https://phimimg.com/upload/vod/20240128-1/6e22019f680d31e0a326de75c6fbc1f0.jpg', '<p>Buổi hòa nhạc đang diễn ra thì người phụ trách ánh sáng In Su (Bae Yong Joon đóng) vội vã bàn giao công việc cho trợ lý rồi rời đi. Anh vừa biết tin vợ mình là Su Jin (Im Sang Hyo đóng) bị tai nạn xe hơi nên chạy ngay đến phòng phẫu thuật ở thành phố Samcheok, tỉnh Gangwon, nơi anh gặp được Seo Young (Son Ye Jin đóng). Hóa ra chồng của Seo Young là Kyung Ho (do Ryu Seung Soo đóng) cũng đi chung xe với vợ của anh và đây là vụ ngoại tình. Su Jin và Kyung Ho đều đã phản bội tình cảm trong hôn nhân của họ, cả hai bị hôn mê sâu và trở thành người thực vật do chấn thương nghiêm trọng. Trong quá trình giải quyết hậu quả vụ tai nạn, In Su và Seo Young nhận ra sự rung động giữa hai người và dần dần bị thu hút bởi đối phương. Họ ở trong cùng một nhà nghỉ và cuối cùng yêu nhau. Hai người có cùng hoàn cảnh cảm thấy vô cùng đau khổ. Chính lúc này thì Su Jin tỉnh dậy…</p>', 'Full', 1, 'single', 'completed', 12, 2005, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Bae Yong Jun","avatar":""},{"name":"Son Ye jin","avatar":""},{"name":"Liu Cheng Xiu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324526);
