INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-tien-thuong-2005', 'Thợ Săn Tiền Thưởng', 'Domino', 'https://phimimg.com/upload/vod/20240126-1/874275cac973ae7fddcf01912332ec5f.jpg', 'https://phimimg.com/upload/vod/20240126-1/9af550cc0063f68fcf75e433c78c2b8c.jpg', '<p>Phim là một câu chuyện có thật về con gái tài tử Laurel Harvey là Domino, một người mẫu cho tập đoàn Ford nổi tiếng, nhưng cô đã từ bỏ cuộc sống phồn hoa này ở Beverley Hills để trở thành một người săn tiền thưởng.</p>', 'Full', 1, 'single', 'completed', 23, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keira Knightley","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Édgar Ramírez","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
