INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-mai-buoi-hoang-hon', 'Mãi Mãi Buổi Hoàng Hôn', 'Always: Sunset On Third Street', 'https://phimimg.com/upload/vod/20240123-1/9beacabcdbf3d06ab985471675a55923.jpg', 'https://phimimg.com/upload/vod/20240123-1/b375e8e9928b67867d1d7267e345a335.jpg', '<p>Bối cảnh phim nhuốm màu cổ xưa với Tokyo của những năm 60. Nước Nhật đang trong giai đoạn chuyển mình sau cuộc chiến, với những phố phường giản dị và cuộc sống con người còn quá sơ sài, thiếu thốn. Không có những khu công nghiệp quy mô hay các tòa nhà chọc trời, mà thậm chí những thiết bị gia đình dường như quá xa vời. Những gì hiển hiện trên khu phố số 3 không bóng bẩy, cầu kỳ mà mang đầy không khí bình an và ấm áp nhờ ánh dương lan tỏa của buổi hoàng hôn. Lẫn trong tiếng gió đung đẩy các dây phong linh là tiếng cười đùa, là âm thanh làm việc, là khao khát dựng xây cuộc sống mãnh liệt.</p>', 'Full', 1, 'single', 'completed', 14, 2005, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tsutsumi Shinichi","avatar":""},{"name":"Maki Horikita","avatar":""},{"name":"Hidetaka Yoshioka","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
