INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-sat-gai', 'Tay Sát Gái', 'Casanova', 'https://phimimg.com/upload/vod/20240123-1/530eb648eb056f3003410e9e7f901372.jpg', 'https://phimimg.com/upload/vod/20240123-1/d99aa04d3991853e340439dc1a864f05.jpg', '<p>Casanova anh chàng điển trai như xứ Venice của anh. Từ các trinh nữ nổi tiếng đoan trang đến những nữ tu khi thấy thì anh đều muốn...xử ngay. Vào 1 ngày anh ngồi lại và bắt đầu tổng kết - mà theo anh đó là công việc vô cùng nhàm chán - Mỗi trang giấy sẽ dành cho 1 người phụ nữ, số trang đã lên tới 10000. Tiếng tăm của anh thậm chí đi vào cả kịch, sân khấu tới những tác phẩm điện ảnh đương thời.</p>', 'Full', 1, 'single', 'completed', 20, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Heath Ledger","avatar":""},{"name":"Sienna Miller","avatar":""},{"name":"Jeremy Irons","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
