INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-cung', 'Cánh Cung', 'The Bow', 'https://phimimg.com/upload/vod/20240126-1/ac18c762acb25a402b6be284651156bc.jpg', 'https://phimimg.com/upload/vod/20240126-1/1689a9a5ad47206e3f793e9dcaf078ee.jpg', '<p>Giữa vùng trời biển mênh mông, một chiếc tàu gỗ bỏ neo trên sóng nước dập dềnh. Trên tàu là hai con người, một ông già và một cô gái trẻ làm nghề phục dịch khách lên tàu câu cá. Hàng ngày lão ngư lái xuồng máy vào bờ, đón người có sở thích đi câu ngoài khơi xa. Cô gái ở lại tàu, háo hức chờ đợi những ai đến từ thế giới đất liền. Người không biết sẽ nghĩ họ là hai ông cháu, kẻ tường tận xầm xì kể nhau nghe sự tích trên biển cả: 10 năm trước, lão già nhặt được con bé 6 tuổi, đem về tàu nuôi khôn lớn đến giờ mà chẳng hề cho cô đặt chân lên bờ một lần. Lão dự định khi cô gái tròn 17 tuổi sẽ tổ chức hôn lễ với nàng...Khách có tâm dè bỉu lão già là đồ thối tha, trơ trẽn. Kẻ hắc ám lại cho đấy là cơ ...</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Han Yeo-reum","avatar":""},{"name":"Seo Ji-seok","avatar":""},{"name":"Jeon Kuk-hwan","avatar":""},{"name":"Seong-hwang Jeon","avatar":""},{"name":"Jo Hyun-wu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324526);
