INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-canh-hoa-roi', 'Những Cánh Hoa Rơi', 'Broken Flowers', 'https://phimimg.com/upload/vod/20240122-1/d6d4eda86bec06131f01e4d46e9f9471.jpg', 'https://phimimg.com/upload/vod/20240122-1/42eaac5be981932f56f8d0e8629a8586.jpg', '<p>Khi ông già độc thân Don Johnston (Murray) bị cô bạn gái cuối cùng bỏ rơi, ông nhận được một lá thư hồng nói cho ông biết rằng ông có một đứa con trai đang đi tìm kiếm ông. Thế là Don lục lọi lại ký ức của mình và lên đường băng qua khắp mọi miền đất nước để tìm về những mối tình xưa tìm kiếm đứa con trai mà ông chưa hề biết mặt. Những chuyến viếng thăm bất ngờ của Don với từng phụ nữ trong đời ông chứa đựng nhiều sự bất ngờ cho cả hai, và khám phá cả những bất ngờ trong quá khứ lẫn hiện tại của Don...</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Murray","avatar":""},{"name":"Julie Delpy","avatar":""},{"name":"Sharon Stone","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Jessica Lange","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324526);
