INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-kich-seoul', 'Đột Kích Seoul', 'Seoul Raiders', 'https://phimimg.com/upload/vod/20240121-1/3f6df3b1416c3ce5cd7e9ea8930d3bee.jpg', 'https://phimimg.com/upload/vod/20240121-1/90987493a972b6aebf45ec0d2652abeb.jpg', '<p>Lương Triều Vĩ và Thư Kỳ liên hoàn xuất kích, nhập vai cảnh sát hình sự quốc tế và nữ tặc gợi cảm với những tranh chấp hài hước.</p>', 'Full', 1, 'single', 'completed', 12, 2005, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tony Chiu-Wai Leung","avatar":""},{"name":"Fanny Shu","avatar":""},{"name":"Hsu Chi","avatar":""},{"name":"Shu Kei","avatar":""},{"name":"Richie Jen","avatar":""},{"name":"Xian Qi Ren (本名）","avatar":""},{"name":"Xiao Chi (昵称)","avatar":""},{"name":"Xiao Qi (昵称)","avatar":""},{"name":"Zheng Zhen","avatar":""},{"name":"VICKIE.ZHAO","avatar":""},{"name":"meme","avatar":""},{"name":"Ji-Yeon Park","avatar":""},{"name":"Lee Jung Jin","avatar":""},{"name":"Lai Hu Zao Fei","avatar":""},{"name":"Matthew Tang Hon Keung","avatar":""},{"name":"Sasha Hou","avatar":""},{"name":"Jin Liu Shi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324526);
