INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-thien-vu', 'Phi Thiên Vũ', 'Shinobi: Heart Under Blade', 'https://phimimg.com/upload/vod/20240121-1/8b3012f8be9622f604b1b63d1db2c263.jpg', 'https://phimimg.com/upload/vod/20240121-1/f2bef1499d8b9abb94aaa0545ab9455d.jpg', '<p>Bộ phim nói về tình yêu giữa hai ninja vào thời kỳ đầu Tokugawa. Vì muốn giữa hòa bình cho hai bên nên tổ tiên của Oboro và Gennosuke đã cùng lập một hiệp ước. Khi Oboro và Gennosuke gặp nhau, họ không biết gì về thân phận của đối phương mà đã phải lòng nhau. Nankobo Tenkai vì dã tâm thống trị nước Nhật đã gây nên cuộc chiến giữa hai gia đình của Oboro và Gennosuke khiến họ phải chọn lựa giữa tình yêu và mối thù gia tộc.</p>', 'Full', 1, 'single', 'completed', 9, 2005, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yukie Nakama","avatar":""},{"name":"Jô Odagiri","avatar":""},{"name":"Tomoka Kurotani","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
