INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-va-con-trai-toi', 'Cha Và Con Trai Tôi', 'My Father And My Son', 'https://phimimg.com/upload/vod/20240121-1/54f946a90cbb2c27d1bb9c9a27c5e90c.jpg', 'https://phimimg.com/upload/vod/20240121-1/861a0f459ca7d8849f44ab9ee2b12865.jpg', '<p>Một nhà báo cánh tả có vợ chết khi sinh con trai trong một cuộc đảo chính quân sự trở về trang trại của gia đình anh ta. Bị cha ghẻ lạnh vì quay lưng lại với gia đình và thay vào đó lãng phí cuộc đời của mình cho hoạt động chính trị, anh cố gắng kết nối lại với ông để con trai mình có một nơi ở khi sức khỏe của anh ngày càng giảm sút do phải chịu đựng quá nhiều sự tra tấn. .</p>', 'Full', 1, 'single', 'completed', 19, 2005, 'Vietsub', 'HD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Çetin Tekindor","avatar":""},{"name":"Fikret Kuşkan","avatar":""},{"name":"Binnur Kaya","avatar":""},{"name":"Ege Tanman","avatar":""},{"name":"Özge Özberk","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324526);
