INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-kinh-hoang', 'Chuyến Bay Kinh Hoàng', 'Flightplan', 'https://phimimg.com/upload/vod/20240109-1/4ddc5fe764a033413b567907491d8b7c.jpg', 'https://phimimg.com/upload/vod/20240109-1/ccc1a03ec03d69c765968d63e87ad286.jpg', '<p>Thế là hạnh phúc tan vỡ khi người chồng yêu thương từ giã cuộc đời vì một tai nạn bất ngờ. Kyle Pratt quyết định đưa Julia, đứa con gái lên 6, cùng xác chồng về quê nội, ở bên kia đại dương, tận nước Mỹ xa xôi. Sau nhiều thủ tục nhiêu kê, mọi việc cũng ổn thỏa. Đêm trước khi lên đường, không ngủ được, qua khung cửa sổ, Kyle thấy mấy người đàn ông râu rậm ở nhà đối diện đang hướng ánh nhìn về phía chị. Julia sợ, cả đời nó chưa đi xa bao giờ. Vậy mà ở phòng chờ thênh thang náo nhiệt của phi cảng, con bé dám rời mẹ chạy đến gian hàng sách thiếu nhi, Kyle bị một phen hú vía. Thấy chiếc E-474 khổng lồ, Julia lo lắng về chuyến bay. Kyle trấn an con, để nó tin tưởng vào sự an toàn của máy bay, vì cô ...</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jodie Foster","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Kate Beahan","avatar":""},{"name":"Michael Irby","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324526);
