INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('herbie-noi-loan', 'Herbie Nổi Loạn', 'Herbie: Fully Loaded', 'https://phimimg.com/upload/vod/20240104-1/14fe063c72ba9082fe8bef5631ea5e28.jpg', 'https://phimimg.com/upload/vod/20240104-1/92d92df885852ec954ebab6eff129f25.jpg', '<p>Maggie Peyton là chủ sở hữu mới của số 53 - Lỗi Volkswagen của Volkswagen miễn phí với tâm trí của riêng mình; Cô ấy đặt chiếc xe qua những bước đi trên đường để trở thành đối thủ cạnh tranh NASCAR. Là một thành viên thế hệ thứ ba của một gia đình NASCAR, Racing là trong máu của Maggie Peyton, nhưng cô bị cấm theo đuổi giấc mơ của mình bởi người cha bảo vệ quá mức của mình, Ray Peyton, Sr. Khi Ray Sr. cung cấp cho Maggie một chiếc xe tốt nghiệp đại học, anh ấy đưa cô đến một bãi rác để chọn một từ một loại xe rất đã qua sử dụng. Maggie có mắt cô ấy trên một chiếc Nissan cũ, nhưng một lỗi bị rỉ sét nhất định, đập vào 63 VW dường như đang kêu gọi sự chú ý của cô ấy. Trước sự ngạc nhiên của cô, Maggie rời đi rất nhiều với Herbie. Khi cô chuẩn bị rời khỏi thị trấn cho một vị trí với ESPN News, Maggie phát hiện ra rằng Herbie có một tâm trí của chính mình - và một tuyến đường thay thế cho tương lai của cô.</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324526);
