INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-diec', 'Cô Gái Điếc', 'The Quiet', 'https://phimimg.com/upload/vod/20240104-1/3711d0224d6a92faa2e67b4082dfb28b.jpg', 'https://phimimg.com/upload/vod/20240104-1/3b5275a883ced6a6ec438561583b2eaf.jpg', '<p>Sau khi người cha góa bụa của cô qua đời, Dot thiếu niên khiếm thính chuyển đến sống với cha mẹ đỡ đầu của cô, Olivia và Paul Deer. Con gái của Deers, Nina, công khai thù địch với Dot, nhưng điều đó không ngăn cản cô kể những bí mật của mình cho người chị kế thầm lặng của mình, bao gồm cả việc cô muốn giết người cha dâm đãng của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elisha Cuthbert","avatar":""},{"name":"Camilla Belle","avatar":""},{"name":"Shawn Ashmore","avatar":""},{"name":"Martin Donovan","avatar":""},{"name":"Edie Falco","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324526);
