INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-ke-ca-cuoc', 'Hai Kẻ Cá Cược', 'Two For The Money', 'https://phimimg.com/upload/vod/20240108-1/eec8b61b579ea1a638b0b5aa156f34db.jpg', 'https://phimimg.com/upload/vod/20240108-1/c7e5d7dcde8cd662431b36e1816badac.jpg', '<p>Hai Kẻ Cá Cược - Two for the Money: Walter Abrams là chủ nhân của Hotline cá cược thể thao chuyên phục vụ cho những người đánh bạc lớn. Anh thuê cựu ngôi sao bóng đá làm việc cho mình. Abrams sớm phát hiện ra rằng tân binh mới này có sở trường về những trò bóng bánh. Cho đến một ngày, cả hai lao vào một cuộc đối đầu chết người trị giá hàng triệu đô la..</p>', 'Full', 1, 'single', 'completed', 17, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew McConaughey","avatar":""},{"name":"Al Pacino","avatar":""},{"name":"Rene Russo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '[]', 1784690324526);
