INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuc-ngu-ngon-va-chuc-may-man', 'Chúc Ngủ Ngon Và Chúc May Mắn', 'Good Night, And Good Luck.', 'https://phimimg.com/upload/vod/20240108-1/ddc89b86027326767c54dc30d237590a.jpg', 'https://phimimg.com/upload/vod/20240108-1/56976898ad9d4d05ac46d47a60110558.jpg', '<p>Phim được làm với màu trắng đen kể về những năm 1950 khi mà công nghệ truyền hình Mỹ chỉ mới bước đi những dấu chân đầu tiên. Lúc bấy giờ ở đài truyền hình CBS Murrow là người đứng đầu của chương trình tài liệu. Ông và các cộng sự của mình thực hiện một chương trình nói về việc xét xử không rõ ràng một quân nhân trong Hải quân Mỹ và việc này dẫn đến những mâu thuẫn giữa giới truyền thông với quân đội mà người đại diện là thượng nghị sĩ Joseph McCarthy.</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Strathairn","avatar":""},{"name":"George Clooney","avatar":""},{"name":"Patricia Clarkson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
