INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chia-khoa-xuong-nguoi', 'Chìa Khóa Xương Người', 'The Skeleton Key', 'https://phimimg.com/upload/vod/20231231-1/e87f224553d5d8774c89056f2f5169de.jpg', 'https://phimimg.com/upload/vod/20231231-1/dd69ad95fecb087b582edeac776f88ac.jpg', '<p>Nurse Caroline Ellis rời khỏi công việc của mình để chăm sóc người cao tuổi Ben Devereux, người đã bị đột quỵ và không thể nói chuyện. Khi cô đến nhà anh ở Giáo xứ Terrebonne, Louisiana, cô gặp vợ của Ben Violet, người có hành động đáng ngờ và đáng sợ. Luật sư của gia đình, Luke Marshall, thuyết phục Caroline ở lại. Cô ấy đi đến gác mái và tìm thấy một căn phòng bí mật có đầy đủ các phép thuật, tóc và xương được sử dụng để luyện tập Hoodoo, nhưng Violet nói rằng cô chưa bao giờ thấy căn phòng bí mật này. Caroline muốn giúp Ben, nghĩ rằng Violet đã đưa ra một câu thần chú lên anh ta. Cô ấy biết Hoodoo không thể làm tổn thương một người không tin vào điều đó. Caroline có thể cứu Ben, hoặc cuối cùng cô ấy sẽ là người cần phải được cứu?</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324526);
