INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-yeu', 'Hồn Yêu', 'Just Like Heaven', 'https://phimimg.com/upload/vod/20240102-1/6f003a5dfab10e607d0117de4f3089af.jpg', 'https://phimimg.com/upload/vod/20240102-1/db381c831a2af1d868945e34d71f41a0.jpg', '<p>Elizabeth Masterson, một bác sĩ tận tâm ở San Francisco, gần như không có thời gian cho bất cứ điều gì. Khi cô gặp tai nạn xe hơi bi thảm và đi vào một cuộc hôn mê, một kiến trúc sư cảnh quan di chuyển vào căn hộ của Elizabeth cho thuê - nơi anh gặp dạng ethereal mất trí nhớ của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324526);
