INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-vo-phu-thuy', 'Cô Vợ Phù Thủy', 'Bewitched', 'https://phimimg.com/upload/vod/20240102-1/571ef65285402f14d5fa7690f5977f8c.jpg', 'https://phimimg.com/upload/vod/20240102-1/7a692c6da43d698815ed10678ed89c65.jpg', '<p>Phim Bewitched (2005) kể câu chuyện khi Jack vô tình gặp Isabel. Anh ngay lập tức bị cô hút hồn với cái mũi giống của Elizabeth Montgomery - người đóng vai nữ chính Samantha trong phiên bản gốc bộ phim Bewitched. Anh bị thuyết phục rằng cô sẽ làm tròn vai Samantha trong loạt phim mới của mình. Isabel cũng nhanh chóng bị tác động bởi Jack, cô thấy anh là một người đàn ông đạo đức có thể giúp cô có một cuộc sống bình thường mà cô hằng ao ước. Mọi chuyện bắt đầu một cách hoàn hảo nhưng đem lại cho 2 người những tình huống mà họ không lường trước được…</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Will Ferrell","avatar":""},{"name":"Shirley MacLaine","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324526);
