INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tho-dieu-ky', 'Tuổi Thơ Diệu Kỳ', 'Wait ''Til You''re Older', 'https://phimimg.com/upload/vod/20240102-1/b31d078fe44edb875236ac39ee6a7c39.jpg', 'https://phimimg.com/upload/vod/20240102-1/319be6dc3b9643745f367831c424a379.jpg', '<p>Quang là cậu bé không hạnh phúc. Mẹ tự sát, cậu cho rằng đó là lỗi của mẹ kế và rất ghét cha mình. Cậu gặp người có thuốc trưởng thành cấp tốc và uống loại thuốc đó. Quang trở thành thanh niên 20 tuổi. Nhưng tác dụng phụ của thuốc làm cậu mỗi đêm lại già đi vài tuổi. Liệu cậu có trở về với gia đình?</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Karen Mok","avatar":""},{"name":"Lâm Gia Đống","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
