INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-tinh-yeu', 'Thị Trấn Tình Yêu', 'Elizabethtown', 'https://phimimg.com/upload/vod/20240111-1/a26ea3f7e836972e71725ed7619e386a.jpg', 'https://phimimg.com/upload/vod/20240111-1/214ebcf47be32a0e91782cebdfc2ee49.jpg', '<p>Drew Baylor được xem như một thành công lớn của gia đình. Gia đình anh chuyển từ thị trấn Kentucky đến California. Tại đây anh làm việc với vai trò một nhà thiết kế cho một công ty sản xuất giày thể thao lớn nhất nước. Nhưng thành công đã từ chối anh với thất bại thảm hại trong sản phẩm thiết kế mới nhất. Thất bại này khiến anh mất việc làm, do công ty thua lỗ hàng trăm triệu USD, thậm chí người đuổi việc anh lại chính là người bạn gái Ellen...</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Orlando Bloom","avatar":""},{"name":"Kirsten Dunst","avatar":""},{"name":"Susan Sarandon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
