INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-kim-thuat-su-nguoi-chinh-phuc-shamballa', 'Giả Kim Thuật Sư: Người Chinh Phục Shamballa', 'Hagane No Renkinjutsushi: Shambala O Yuku Mono', 'https://phimimg.com/upload/vod/20240126-1/1d3d8881ab3feabbf6b2fe1a0c660718.jpg', 'https://phimimg.com/upload/vod/20240126-1/edc748f3c773acf3e8c303cf55db6d1e.jpg', '<p>Edward, người được gửi đến thế giới hiện thực, đang nghiên cứu kỹ thuật tên lửa để trở về thế giới cũ. Lúc đó, Alphonse tìm được người hỗ trợ và bắt đầu chế tạo tên lửa.Tuy nhiên, âm mưu của Hiệp hội Thule - tổ chức bí ẩn lại được che giấu ở đằng sau.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2005, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324526);
