INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-anh-kiem', 'Vô Ảnh Kiếm', 'Shadowless Sword', 'https://phimimg.com/upload/vod/20231231-1/ee84cbe4726a9839a8e31508dae67c02.jpg', 'https://phimimg.com/upload/vod/20231231-1/fdc5e4aa9b338d0844e450fcb254873f.jpg', '<p>Shadowless Sword nói về những năm 926 kinh đô Balhae lọt vào tay quân Georan, nhà nước Dongranguk hình thành, xác lập quyền ngoại bang cai trị trên lãnh thổ muôn đời của người Triều Tiên cổ. Không chấp nhận bị đà áp, thần dân Balhae nhen nhóm ngọn lửa đấu tranh đánh đuổi xâm lược, giành lại non sông đất nước. Triều đình Georan sử dụng một bộ phận người Balhae bất mãn vương quyền cũ làm công cụ tiêu diệt mầm mống phản loạn, dìm trào lưu nổi dậy trong biển máu. Chúng lập đội quân Đao Sát với toàn cao thủ máu lạnh, tiến hành những cuộc thanh trừng kinh thiên động địa.</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Young-jun Kim","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
