INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-hau-fbi-2', 'Hoa Hậu FBI 2', 'Miss Congeniality 2: Armed And Fabulous', 'https://phimimg.com/upload/vod/20231227-1/6702a6a204baaff35d4c9b3c1408ea79.jpg', 'https://phimimg.com/upload/vod/20231227-1/3f1fe6d682ec22f2dc0973fd7ac009a8.jpg', '<p>Tình yêu tan vỡ, tinh thần xuống thấp khiến Gracie Hart trở nên chán nản với công việc điều tra. Để lên dây cót và tận dụng tiếng tăm sẵn có của cô, Gracie được mời làm gương mặt đại diện cho FBI với sự hỗ trợ của ông sếp McDonald và anh bạn Joel chịu chơi. Khi Gracie đang trên chuyến đi vòng quanh đất nước với điệp viên Sam Fuller làm vệ sĩ riêng, thì bạn cô, Hoa hậu Mỹ, và người dẫn chương trình Stan Fields bị bắt cóc. Gracie buộc phải cầm súng và trở lại cuộc chơi. Cô quyết định tự mình điều tra vụ này, chống lại lệnh một nhân vật chóp bu của FBI Collins. Lúc thì Gracie giả dạng là một bà già Do Thái ngồi xe lăn, lúc lại trở thành một nàng gái nhảy thực thụ. Cô mang đến cho khán giả rất nhiều tiếng cười.</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Regina King","avatar":""},{"name":"William Shatner","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
