INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-boc-ma-mat-cuoi', 'Vỏ Bọc Ma: Mặt Cười', 'Ghost In The Shell: Stand Alone Complex - The Laughing Man', 'https://phimimg.com/upload/vod/20231227-1/44c377960c6ae43a1f1d5e043bcd91d3.jpg', 'https://phimimg.com/upload/vod/20231227-1/c731f228b9fb9641a1786ed4127041d0.jpg', '<p>Đó là tương lai, khi một cơ thể hoàn chỉnh được tạo ra bằng công nghệ Cybord hóa - da thịt cấy ghép với máy móc, giúp tăng cường sức mạnh một cách hoàn hảo. Trớ trêu thay, phe thiện - ác đều sở hữu những công nghệ tân tiến đó, khiến cuộc chiến giữa 2 phần thế giới càng trở nên khốc liệt. Lúc ...</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2005, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Atsuko Tanaka","avatar":""},{"name":"Osamu Saka","avatar":""},{"name":"Yutaka Nakano","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Toru Okawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324526);
