INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-chien-tranh', 'Trùm Chiến Tranh', 'Lord Of War', 'https://phimimg.com/upload/vod/20231219-1/ad3f2f907802a736a7722fb579260c07.jpg', 'https://phimimg.com/upload/vod/20231219-1/777c41624ad8e285cdc010832df690b9.jpg', '<p>Vào những năm 70 tại Little Odessa, một người nhập cư Ukrainian tên là Yuri Orlov quyết định thay đổi cuộc sống của mình bằng cách kết hợp với anh trai Vitaly Orlov để trở thành người buôn bán vũ khí. Vì miếng cơm manh áo, anh chấp nhận cả nguy hiểm thậm chí sẵn sàng đút lót để có thể yên ổn làm ăn. Nhờ nhanh nhạy, Yuri trở thành tỉ phú, anh dùng tiền của mình để quyến rũ người đẹp Ava Fontaine. Cả hai đã đi đến hôn nhân và có một cậu con trai. Nhưng họ không thể sống yên ổn cho đến khi Jack Valentine quyết tâm khám phá ra đường dây buôn bán của Yuri và tìm mọi cách để tống anh vào tù. Nhưng chính Yuri đã làm Jack thay đổi suy nghĩ và hiểu rằng dù xấu xa nhưng Yuri vẫn là người cần thiết cho tổ quốc mình.</p>', 'Full', 1, 'single', 'completed', 9, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Jared Leto","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324526);
