INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-trom-cho', 'Những Kẻ Trộm Chó', 'Lost Dogs', 'https://phimimg.com/upload/vod/20231219-1/16c656fdf8cbbce72c70d86c3b41712a.jpg', 'https://phimimg.com/upload/vod/20231219-1/f9aa318e751c5c78b0b279e83874e833.jpg', '<p>Những Kẻ Trộm Chó - Lost Dogs kể về một nhóm trộm đã lên kế hoạch bắt cóc chó cưng của một nhà buôn đồ cổ để đòi tiền chuộc. Nhưng điều chúng không biết là gia chủ cũng đang mang trên mình món nợ lớn, hơn nữa cậu con trai của họ còn là cảnh sát. Một phi vụ không ít sóng gió, và cũng không thiếu những điều chẳng ai lường trước được.</p>', 'Full', 1, 'single', 'completed', 9, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeremy Edwards","avatar":""},{"name":"Ron Moody","avatar":""},{"name":"Sean Boru","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
