INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-ke-trom-cho', 'Những Kẻ Trộm Chó', 'Lost Dogs', 'những kẻ trộm chó lost dogs jeremy edwards ron moody sean boru ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-anh-em', 'Bốn Anh Em', 'Four Brothers', 'https://phimimg.com/upload/vod/20231219-1/618a5482b1c9d5ff56ce7799b8d52885.jpg', 'https://phimimg.com/upload/vod/20231219-1/e820026bb7aed348754cc71398c76c3c.jpg', '<p>Trong quá trình điều tra cái chết đầy bí hiểm của người mẹ nuôi, 4 anh em nhà Mercer phát hiện ra mối liên hệ mờ ám giữa nhiều quan chức với một mạng lưới buôn bán ma túy trong thành phố. Họ từng là những đứa trẻ mồ côi sống lang thang.Nhưng cuộc đời họ đã thay đổi kể từ khi Evelyn Mercer mang họ về nuôi. Mặc dù không có quan hệ huyết thống và khác màu da nhưng 4 anh em hết mực thương yêu nhau. Anh cả Bobby Mercer (Mark Wahlberg) là người nóng tính hay gây gổ nhưng rất tình nghĩa. Với hành trang là một tuổi thơ đầy bạo lực, Bobby vào tù như đi chợ. Lớn tuổi thứ hai, điềm đạm và biết tính toán nhất là Jeremiah Mercer - chủ một công ty xây dựng. Anh đã kết hôn và có hai con gái. Trong mắt mọi người, Jeremiah là một doanh nhân lương thiện, chăm chỉ. Người nhiều tuổi thứ ba là Angel Mercer. Anh thường được được những người xung quanh gọi là “tay chơi” bởi khả năng chinh phục phụ nữ siêu đẳng. Angel gia nhập lực lượng lính thủy đánh bộ ngay sau khi rời trường phổ thông. Ít tuổi, ít nói và đa cảm nhất là Jack Mercer – người được coi là đối lập hoàn toàn so với các ông anh. Jack từng trải qua một tuổi thơ kinh hoàng trước khi được Evelyn Mercer đem về nuôi. Jack cũng là người theo Bobby nhất,chắc cũng chính vì điều này mà anh có một kết cục buồn. Nhận được tin mẹ Evelyn qua đời trong một vụ cướp tại cửa hàng, bốn anh em vội vã quay trở về Detroit để chôn cất. Những tên cướp dường như đã vô tình giết chết bà. Cảnh sát tin là như thế sau khi nghe lời khai của một nhân chứng. Nhưng anh em nhà Mercer thấy vụ việc có nhiều điểm đáng ngờ và họ quyết định tự điều tra để làm rõ chân tướng.</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"André Benjamin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324526);
