INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doc-duong-gio-bui', 'Dọc Đường Gió Bụi', 'Walk The Line', 'https://phimimg.com/upload/vod/20231219-1/4c1facb6a44203e89e8e5f4a8579525b.jpg', 'https://phimimg.com/upload/vod/20231219-1/d5a81d6aa834a2b1f065643018241f1a.jpg', '<p>Biên niên sử về cuộc đời của huyền thoại nhạc đồng quê Johnny Cash, từ những ngày đầu ở trang trại bông ở Arkansas cho đến khi nổi tiếng với Sun Records ở Memphis, nơi anh thu âm cùng với Elvis Presley, Jerry Lee Lewis và Carl Perkins.</p>', 'Full', 1, 'single', 'completed', 7, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joaquin Phoenix","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"Ginnifer Goodwin","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Dallas Roberts","avatar":""},{"name":"Dan John Miller","avatar":""},{"name":"Larry Bagby","avatar":""},{"name":"Shelby Lynne","avatar":""},{"name":"Tyler Hilton","avatar":""},{"name":"Waylon Payne","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324526);
