INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-uc-cua-mot-geisha', 'Hồi Ức Của Một Geisha', 'Memoirs Of A Geisha', 'https://phimimg.com/upload/vod/20231213-1/019db8fb4ded1511f8eaede05eef95a5.jpg', 'https://phimimg.com/upload/vod/20231213-1/8f16ad48c34afb21af9138fdb627dfaa.jpg', '<p>Bị bán cho nhà geisha khi còn nhỏ, con gái của một ngư dân trở thành geisha được săn đón nhất Kyoto – nhưng sự cạnh tranh ngăn cản tương lai mà cô khao khát.</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chương Tử Di","avatar":""},{"name":"Watanabe Ken","avatar":""},{"name":"Yakusho Koji","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324526);
