INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tom-and-jerry-the-fast-and-the-furry', 'Tom And Jerry: The Fast And The Furry', 'Tom And Jerry: The Fast And The Furry', 'https://phimimg.com/upload/vod/20231213-1/da5b7f29627d9bca74d00f29045a39ed.jpg', 'https://phimimg.com/upload/vod/20231213-1/8c4ecc4a03b717b7e25bbdefbaf8f26c.jpg', '<p>Tom và Jerry và tay đua khác cố gắng giành được chìa khóa cho giải thưởng. Trước tiên, họ đến Mexico và tìm ra xếp hạng là quá cao để họ mở rộng nó đến Jungle Amazon. Tom loại bỏ Mẹ bóng đá bằng cách khiến cô ấy lái xe minivan của mình thành một hố cát lún. Bugs bầy đàn và ăn bóng đá.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324526);
