INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cry_wolf-sat-nhan-giau-mat', 'Cry_Wolf: Sát Nhân Giấu Mặt', 'Cry Wolf', 'https://phimimg.com/upload/vod/20231213-1/398163a8ec88c80e3bdc2d719d2deb07.jpg', 'https://phimimg.com/upload/vod/20231213-1/776b7a2df9c766c403da7ecf2a1e0852.jpg', '<p>Khi một phụ nữ trẻ bị sát hại gần trường nội trú của họ, một nhóm thiếu niên lan truyền tin đồn về kẻ sát nhân trong trường – cho đến khi xuất hiện các nạn nhân tử vong.</p>', 'Full', 1, 'single', 'completed', 8, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julian Morris","avatar":""},{"name":"Lindy Booth","avatar":""},{"name":"Jared Padalecki","avatar":""},{"name":"Jon Bon Jovi","avatar":""},{"name":"Sandra McCoy","avatar":""},{"name":"Kristy Wu","avatar":""},{"name":"Jesse Janzen","avatar":""},{"name":"Paul James","avatar":""},{"name":"Anna Deavere Smith","avatar":""},{"name":"Ethan Cohn","avatar":""},{"name":"Gary Cole","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324526);
