INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-nua-su-that', 'Một Nửa Sự Thật', 'Imagine Me & You', 'https://phimimg.com/upload/vod/20231212-1/8585cd97849a62f0d5e6005752bc957b.jpg', 'https://phimimg.com/upload/vod/20231212-1/abf6f3856272cabb5de765a145f82cf9.jpg', '<p>Trong lễ cưới của mình, Rachel để ý đến Luce trong số khán giả và cảm thấy bị cô ấy thu hút ngay lập tức. Hai người phụ nữ trở thành bạn thân của nhau, và khi Rachel biết Luce là một người đồng tính nữ, cô ấy nhận ra rằng mặc dù có cuộc hôn nhân hạnh phúc với Heck, nhưng cô ấy lại yêu Luce. Khi đặt câu hỏi về xu hướng tính dục của mình, Rachel phải quyết định giữa mối quan hệ ổn định với Heck và mối tình lãng mạn mới đầy phấn khích với Luce.</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Piper Perabo","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Celia Imrie","avatar":""},{"name":"Anthony Stewart Head","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324526);
