INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-vo-2005', 'Đổ Vỡ', 'Crash', 'https://phimimg.com/upload/vod/20231212-1/2e33593a40055d3dacb2525e3c171af8.jpg', 'https://phimimg.com/upload/vod/20231212-1/c70f8bad7e741552ede4654c6269fae8.jpg', '<p>Một gia đình có người vợ là người vùng Brentwood với người chồng là 1 công tố viên. Một chủ tiệm người Persia. Hai viên cảnh sát điều tra và họ cũng là người yêu của nhau. Một nhà đạo diễn phim truyền hình da đen cùng người vợ của mình. Một tay sửa khóa người Mexico. Hai tên trộm xe. Một cảnh sát viên thiếu kinh nghiệm. Và cuối cùng là một cặp đôi người Hàn Quốc. Tất cả họ đều sống ở Los Angeles và 1 tai nạn xe hơi đã đem họ gặp gỡ lẫn nhau...</p>', 'Full', 1, 'single', 'completed', 8, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Don Cheadle","avatar":""},{"name":"Sandra Bullock","avatar":""},{"name":"Thandie Newton","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
