INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-den-noi-chua', 'Đã Đến Nơi Chưa?', 'Are We There Yet?', 'https://phimimg.com/upload/vod/20231212-1/e9e38918c4a9a1eb1cf7abf5f23fc325.jpg', 'https://phimimg.com/upload/vod/20231212-1/897938481d4ecd6e9305bf852bd1d6bd.jpg', '<p>Để ghi điểm với một bà mẹ đơn thân, một người đàn ông quyết tâm theo đuổi bèn ngỏ ý đưa các con của cô đi phượt rồi buộc phải chịu đựng các trò tinh quái của chúng.</p>', 'Full', 1, 'single', 'completed', 9, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ice Cube","avatar":""},{"name":"Nia Long","avatar":""},{"name":"Aleisha Allen","avatar":""},{"name":"Philip Bolden","avatar":""},{"name":"Jay Mohr","avatar":""},{"name":"M.C. Gainey","avatar":""},{"name":"Tracy Morgan","avatar":""},{"name":"Henry Simmons","avatar":""},{"name":"Ray Galletti","avatar":""},{"name":"Viv Leacock","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324526);
