INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-lan-chon-cat', 'Ba Lần Chôn Cất', 'The Three Burials Of Melquiades Estrada', 'https://phimimg.com/upload/vod/20231212-1/8feaf24c44b916798f3ea4da12f1dc81.jpg', 'https://phimimg.com/upload/vod/20231212-1/4bb45d509c52de09381a3731a3ddfcbc.jpg', '<p>Ba Lần Chôn Cất - The Three Burials of Melquiades Estrada là một bộ phim Mexico-Mỹ của diễn viên-đạo diễn Tommy Lee Jones. Ở Texas lân cận biên giới của Mexico, một cảnh sát tuần tra biên giới kiêu ngạo Mike Norton giết nhầm chàng cao bồi Melquiades Estrada và chôn ông trong sa mạc. Khi cơ thể của Melquiades vô tình tìm thấy một tuần sau đó. Người bạn thân nhất của Melquiades, quản đốc trang trại Pete Perkins tuyên bố đem Melquiades về quê nhà Jimenez và ép cảnh sát trưởng địa phương Belmont để tìm ra kẻ giết người. Tuy nhiên, Melquiades không được giao cho Pete vì ông không phải là người thân của cái xác và được chôn cất tại nghĩa trang địa phương. Khi Rachel tiết lộ danh tính của kẻ giết người, Pete bắt cóc Mike và buộc anh ta phải đào mộ và mang Melquiades về với gia đình ở Mexico. Cuộc hành trình này sẽ chứng kiến điều gì? Melquiades có đoàn tụ được với gia đình mình hay không?</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tommy Lee Jones","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Dwight Yoakam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
