INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-ky', 'Phân Kỳ', 'Divergence', 'null', 'https://phimimg.com/upload/vod/20231211-1/57b756a254dd323ab9a89f06d741cbfc.jpg', '<p>Khi tên tội phạm rửa tiền bị áp giải trở lại Hồng Kông, kẻ giết người chuyên nghiệp Qu đã bắn hắn và trốn thoát. Chủ mưu đằng sau đó là thủ lĩnh của nhóm rửa tiền, Rao Tiansong, nhưng con trai của ông ta cũng đã bị bắt cóc bởi những nhân vật bí ẩn khác. Vụ án bắt đầu trở nên phức tạp và nó được giao cho cảnh sát, Sun. Sun luôn là người không may mắn. Trước sự ngạc nhiên của mình, anh phát hiện ra rằng Amy, vợ của luật sư Du Housheng của Rao Tiansong, giống như bạn gái của anh đã biến mất mười năm trước. Chính vì vậy, anh đã dành rất nhiều công sức cho quá trình điều tra vụ án.</p>', 'Full', 1, 'single', 'completed', 7, 2005, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Daniel Wu","avatar":""},{"name":"Gallenvaw","avatar":""},{"name":"Gallen Lo","avatar":""},{"name":"Aaron Kwok","avatar":""},{"name":"Sing Sing (昵称) / Fu Shing Kwok (本名)","avatar":""},{"name":"Ekin Cheng","avatar":""},{"name":"Angelica Lee","avatar":""},{"name":"Sinje Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324526);
