INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-di-duoi-dia-nguc', 'Người Đi Dưới Địa Ngục', 'Constantine', 'https://phimimg.com/upload/vod/20231211-1/5d9210405fad5a09e04ddec7a113374d.jpg', 'https://phimimg.com/upload/vod/20231211-1/dfb5ab108c8a60f6031435bf0d797675.jpg', '<p>John Constantine được tiếp cận bởi Det. Angela Dodson, người cần sự giúp đỡ của mình để chứng minh rằng cái chết của chị gái của cô ấy là cái chết của cô ấy không phải là một vụ tự tử. Người phụ nữ chết là một người Công giáo sùng đạo và Angela từ chối chấp nhận cô ấy sẽ đưa cuộc sống của chính mình. Cô ấy đã hỏi Constantine để được giúp đỡ vì anh ta có tiếng là một danh tiếng để đối phó với thần bí. Trên thực tế, anh ta là một thợ săn quỷ có mục đích duy nhất trên trái đất là gửi quỷ trở lại vùng Nether. Bản thân John đã đến địa ngục và biết rằng anh ta định trở lại ở đó về cái chết của mình - nhưng hy vọng những việc làm tốt của anh ta có thể tìm thấy anh ta một nơi trên thiên đường. Khi anh ta nhìn vào cái chết của Isabel, anh ta nhận ra những con quỷ đang cố gắng vượt qua thế giới loài người, và những trận chiến của ông dẫn dắt anh ta thành một cuộc xung đột trực tiếp với Satan.</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324526);
