INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-bo-cau', 'Biệt Đội Bồ Câu', 'Valiant', 'https://phimimg.com/upload/vod/20231211-1/fc77eddeed8bd6d8c23fb9bc34208536.jpg', 'https://phimimg.com/upload/vod/20231211-1/7063b41265c8c3ecc12a28e9f47b7e43.jpg', '<p>Valiant kể về cuộc phiêu lưu vui nhộn của chú bồ câu có vóc dáng khiêm tốn tên Valiant. Tuy thường bị trêu chọc về kích thước của mình nhưng Valiant luôn mơ ước được gia nhập vào lực lượng bồ câu đưa thư Hoàng gia Anh phục vụ trong Thế chiến thứ 2. Cuối cùng, Valiant cũng được nhận vào một đội huấn luyện cùng với các chú bồ câu Bugsy bẩn thỉu, Lofty luôn ra vẻ nghiêm nghị, Toughwood khù khờ...</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Ricky Gervais","avatar":""},{"name":"Tim Curry","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324526);
