INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-choi-bo-cua-ma-quy', 'Sự Chối Bỏ Của Ma Quỷ', 'The Devil''s Rejects', 'https://phimimg.com/upload/vod/20231211-1/d8fadd876eb193ddbd916e0f43563707.jpg', 'https://phimimg.com/upload/vod/20231211-1/5f7b52455cee60dd7cc89bbc70bbf931.jpg', '<p>Phần tiếp theo của House of 1000 Corpses – gia đình Firefly bị cảnh sát trưởng Wydell và một đội vũ trang súng ống phục kích tại ngôi nhà biệt lập của họ – nhưng chỉ có Otis và em gái của anh, Baby, xoay sở để thoát khỏi làn đạn mà không hề hấn gì. Trốn trong một nhà nghỉ tù túng, cặp anh em bị truy nã chờ gặp người cha lầm lạc của họ, Thuyền trưởng Spaulding, giết chết bất cứ ai tình cờ cản đường họ.</p>', 'Full', 1, 'single', 'completed', 9, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sid Haig","avatar":""},{"name":"Bill Moseley","avatar":""},{"name":"Sheri Moon Zombie","avatar":""},{"name":"William Forsythe","avatar":""},{"name":"Ken Foree","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324526);
