INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-moi-la-yeu', 'Thế Mới Là Yêu', 'A Lot Like Love', 'https://phimimg.com/upload/vod/20231211-1/9c086fd37286b087481826db928d31db.jpg', 'https://phimimg.com/upload/vod/20231211-1/053b5ec1994741631c4fb0a914d9aec0.jpg', '<p>Có những mối tình bắt đầu ngay từ cái nhìn đầu tiên, một tình yêu sét đánh. Nhưng cũng có những mối tình được thăng bậc từ tình bạn và bền vững với thời gian. Chuyện tình cảm giữa Oliver và Emily thuộc dạng thứ 2. Tình cờ gặp nhau trên 1 chuyến bay từ L.A sang New York. Họ tự nhận thấy mình khônng hợp nhau. 7 năm sau, họ liệu tình bạn giữa họ lại chuyển thành tình yêu. Điều gì đã làm nên sự thay đổi ấy?</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashton Kutcher","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"Taryn Manning","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
