INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shakugan-cua-shana', 'Shakugan Của Shana', 'Burning Eyes Shana, Flaming Eyes Shana, Shana Of The Burning Eyes', 'https://phimimg.com/upload/vod/20231219-1/f07be57757a2ac25ee36094a29e1c23a.jpg', 'https://phimimg.com/upload/vod/20231219-1/8e5fc4ebb85426a2d1d826bceb87c9fe.jpg', '<p>Yuji Sakai, một học sinh trung học bình thường ở thành phố Misaki, đã tham gia vào thế giới phi thường với sự xuất hiện của một cô gái tên Shana với mái tóc rực lửa và đôi mắt bừng sáng. Cô gái nói với Yuji, Anh không còn tồn tại nữa đâu! Mặc dù cả ra sức phản bác nhau, nhưng họ dần dần bị thu hút bởi nhau ...</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 11, 2005, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324526);
