INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('7-seconds', '7 Seconds', '7 Seconds', 'https://phimimg.com/upload/vod/20231210-1/1257fc2bb0dc0a6d208118e3c3957259.jpg', 'https://phimimg.com/upload/vod/20231210-1/72d6454194320097c91ee37ea5c058e9.jpg', '<p>Khi một tên trộm giàu kinh nghiệm vô tình bỏ trốn cùng một bức tranh của Van Gogh, cộng sự của anh ta bị bọn côn đồ bắt cóc để truy đuổi bức tranh, buộc tên tội phạm phải lên kế hoạch giải cứu.</p>', 'Full', 1, 'single', 'completed', 17, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wesley Snipes","avatar":""},{"name":"Tamzin Outhwaite","avatar":""},{"name":"Deobia Oparei","avatar":""},{"name":"Georgina Rylance","avatar":""},{"name":"Pete Lee-Wilson","avatar":""},{"name":"Adrian Lukis","avatar":""},{"name":"Stephen Boxer","avatar":""},{"name":"Adrian Pintea","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"George Anton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324526);
