INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('7-seconds', '7 Seconds', '7 Seconds', '7 seconds 7 seconds wesley snipes tamzin outhwaite deobia oparei georgina rylance pete lee-wilson adrian lukis stephen boxer adrian pintea corey johnson george anton ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-kiem', 'Thất Kiếm', 'Seven Swords', 'null', 'https://phimimg.com/upload/vod/20231210-1/95d14c4c08ee538fe6c6bb5225c9cb08.jpg', '<p>Thất Kiếm - Seven Swords kể về năm 1600, người Mãn Thanh đã tràn vào Trung Nguyên và lập nên triều đại của hoàng tộc Ái Tân Giáp La. Nhưng những tổ chức phản Thanh vẫn còn rất nhiều trong nhân gian và triều đình thì muốn tiêu diệt một cách nhanh chóng những tổ chức này. Mục tiêu đầu tiên được nhắm đến đó chính là Vũ Trang. Một sơn trang có bề ngoài khá yên tĩnh này ẩn chứa bên trong là những anh hùng của Thiên Địa Hội. Vũ Trang lâm vào tình thế nguy kịch, Vũ Nguyên Anh và Hàn Chí Bang đành phải lên Thiên Sơn cầu cứu. Một nhóm 7 người trên Thiên Sơn với 7 cây kiếm mà người ta gọi là Thất Kiếm nhanh chóng xuống núi để hỗ trợ Vũ Trang, liệu rằng họ có về kịp để cứu những người dân vô tội nơi đây.</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chung Tử Đơn","avatar":""},{"name":"Dương Thái Ni","avatar":""},{"name":"Lê Minh","avatar":""},{"name":"Chân Tử Đan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
