INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-ranh', 'Lằn Ranh', 'Stay', 'null', 'https://phimimg.com/upload/vod/20231209-1/eb615d022ef2b20dd5b43a2c05e28823.jpg', '<p>Lằn Ranh - Stay kể về những giây phút hấp hối cuối đời của anh thanh niên trẻ Henry Letham (Ryan Gosling) sau khi gặp phải một tai nạn ô tô kinh hoàng. Tai nạn đã ngay lập tức cướp đi cuộc sống của bố mẹ cũng như người con gái mà anh yêu thương nhất. Những giây phút đấu tranh giữa sự sống và cái chết, những dằn vặt tội lỗi vì đã gây ra tai nạn cũng như tất cả những luyến tiếc của Henry được thể hiện qua hình ảnh của vị bác sĩ tâm lý cùng cô người yêu họa sĩ. Cả 2 nhân vật này đều là do chàng thanh niên trong lúc mê man tưởng tượng ra, họ chính là 2 người cuối cùng anh nhìn thấy trước khi chết.</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Naomi Watts","avatar":""},{"name":"Ryan Gosling","avatar":""},{"name":"Bob Hoskins","avatar":""},{"name":"Janeane Garofalo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
