INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-kich-phan-khu-13', 'Đột Kích Phân Khu 13', 'Assault On Precinct 13', 'https://phimimg.com/upload/vod/20231209-1/d56d76519947c5e2516e9937841f810e.jpg', 'https://phimimg.com/upload/vod/20231209-1/736899d31d375afa24fb359f87ae1046.jpg', '<p>Jake Roenick là một nhân viên đặc biệt của cục phòng chống tội phạm ma túy. Trong một nhiệm vụ, anh đã chứng kiến 2 nhân viên của mình hy sinh và bản thân anh cũng bị thương trong lần đó. Không vượt qua được nỗi ám ảnh, anh từ chức, chấp nhận trở thành một cảnh sát khu vực tầm thường...</p>', 'Full', 1, 'single', 'completed', 12, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Gabriel Byrne","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
