INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-thuat-cua-gai', 'Nghệ Thuật Cua Gái', 'Hitch', 'https://phimimg.com/upload/vod/20231208-1/798def029e30505e0997e46e205a4197.jpg', 'https://phimimg.com/upload/vod/20231208-1/6e7662f055dec81efcf2c39cd0d1a38b.jpg', '<p>Một chuyên viên làm dịch vụ mai mối bị đe dọa vì có một nữ phóng viên giả dạng đăng ký là 1 khách hàng để điều tra mọi mánh lới của anh rồi đang tải trên báo. Bằng mánh lới của mình, anh tìm cách tiếp cận với âm mưu trả thù cô. Nhưng liệu mọi việc có diễn ra đúng kế hoạch khi anh rơi vào lưới tình? Liệu đây có phải là tình yêu thực sự của anh?</p>', 'Full', 1, 'single', 'completed', 11, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Eva Mendes","avatar":""},{"name":"Kevin James","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324526);
