INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phat-thanh-vien-thoi-tiet', 'Phát Thanh Viên Thời Tiết', 'The Weather Man', 'https://phimimg.com/upload/vod/20231208-1/58f503b26b75889c7d33e81e4ffcfdf4.jpg', 'https://phimimg.com/upload/vod/20231208-1/05f05931f13327d8a6be66c1cb29c9b8.jpg', '<p>Dave Spritz là một phát thanh viên về thời tiết trên truyền hình được nhiều người biết đến. Đột nhiên anh được giao cho làm một show truyền hình buổi sáng và tên tuổi của Dave trở nên nổi tiếng trước công chúng. Nhưng gia đình anh thì ngược lại, mối quan hệ của anh và người vợ cũ cùng đứa con trai của mình có nguy cơ tan vỡ. Hòng cứu vãn lại tình thế, Dave đã đến gặp cha của mình, một nhà tiểu thuyết nổi tiếng, tìm kiếm một lời khuyên...</p>', 'Full', 1, 'single', 'completed', 9, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Hope Davis","avatar":""},{"name":"Nicholas Hoult","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
