INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phat-thanh-vien-thoi-tiet', 'Phát Thanh Viên Thời Tiết', 'The Weather Man', 'phát thanh viên thời tiết the weather man nicolas cage hope davis nicholas hoult ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hitch', 'Hitch', 'Hitch', 'https://phimimg.com/upload/vod/20231208-1/421c0a2efa72761a93f3a7d5f12a14b0.jpg', 'https://phimimg.com/upload/vod/20231208-1/0526a46b7a2e3b839d011356b82922e0.jpg', '<p>Xoay xoay quanh trò chơi vĩnh cửu của tình yêu, người mai mối đó và bác sĩ hẹn hò tốt nhất của thành phố New York, Alex Hitch, có thể đảm bảo rằng bất kỳ người đàn ông nào cũng có thể khiến cô gái trong mơ của mình nếu anh ta vượt qua nỗi sợ hãi của mình và theo lời khuyên không thể sai lầm của anh ta. Tuy nhiên, khi Kế toán rụt rè, Albert Brennaman, hãy yêu cầu sự giúp đỡ của mình để thu hút sự chú ý của người thừa kế giàu có và xinh đẹp, Allegra Cole, Hitch sẽ bất ngờ khám phá trận đấu hoàn hảo của anh ấy: Chuyên mục Tin đồn tò mò, Sara Melas. Bây giờ, người quyến rũ tự tin thấy mình đang cần các dịch vụ của mình để cứu mối quan hệ của mình. Nhưng, chuyên gia bạc lưỡi bạc có thể sống sót sau những biến chứng tinh tế của tình yêu?</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324526);
