INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-vao-dai-ngan-ha', 'Cuộc Phiêu Lưu Vào Dải Ngân Hà', 'The Hitchhiker''s Guide to the Galaxy', 'https://phimimg.com/upload/vod/20231205-1/90bbefd53301c07531469b7f08c5704d.jpg', 'https://phimimg.com/upload/vod/20231205-1/372b09522194b51ab043d19da2e2a5b8.jpg', '<p>Trái Đất bị hủy diệt để có chỗ cho việc xây đường cao tốc ngân hà. Arthur Dent, một trong những người Trái đất sống sót, đã rơi vào cuộc du hành vũ trụ nhờ anh chàng Ford bạn thân lâu năm – vốn là một người ngoài hành tinh. Họ đã lần lượt đối mặt với những chủng tộc ngoài hành tinh rất kỳ lạ, có những người khổng lồ nhưng đần độn, có những người tới 50 chân... Và họ cũng đã gặp Zephod, vị tổng thống ngân hà rất kỳ quặc, kẻ đã tự bắt cóc chính bản thân mình. Tình cờ thay, đang ở cùng với Zephod là Trillian, cô gái Trái đất mà trước đây Arthur tán tỉnh.</p>', 'Full', 1, 'single', 'completed', 12, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Freeman","avatar":""},{"name":"Mos Def","avatar":""},{"name":"Sam Rockwell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324526);
