INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sin-city', 'Sin City', 'Sin City', 'https://phimimg.com/upload/vod/20231205-1/d856ef557dc91f9b102237744351be27.jpg', 'https://phimimg.com/upload/vod/20231205-1/cfd1f8afe1396fd5277e4e60f5f84645.jpg', '<p>Sin City (Thành Phố Tội Ác) được trích từ ba tập trong bộ truyện tranh dài kỳ của Frank Miller. Câu chuyện thứ nhất: “The Hard Goodbye” với Mickey Rourke trong vai Marv, một tên đồ tể hình dáng dị hợm, báo thù cho cô gái điếm mà hắn tôn thờ bởi cô là người duy nhất dám ngủ với hắn nhưng lại bị giết chết ngay trong đêm ái ân ấy. Câu chuyện thứ hai: “The Big Fat Kill”, Clive Owen trong vai Dwight McCarthy, tay nhiếp ảnh gia vô tình giết chết một tên cớm bẩn khiến thỏa thuận ngầm giữa băng gái điếm và cảnh sát bị phá vỡ, gây ra một cuộc đối đầu đáng sợ. Câu chuyện thứ ba: “That Yellow Bastard”, Bruce Willis trong vai viên cảnh sát John Hartigan, người tốt hiếm hoi trên đời đã phải trả giá đắt khi bảo vệ một vũ nữ thoát y ngây thơ. Ba mẩu chuyện rời rạc này được làm theo dạng chương hồi và quy về một mối ở đoạn cuối khiến người xem bất ngờ.</p>', 'Full', 1, 'single', 'completed', 10, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Rutger Hauer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324526);
