INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-ma-2005', 'Cô Dâu Ma', 'Corpse Bride', 'https://phimimg.com/upload/vod/20231016-1/73bc1e5bcfbc061bfdd612b19d822036.jpg', 'https://phimimg.com/upload/vod/20231016-1/09b38d638fb767b013cb9927702db313.jpg', '<p>Câu chuyện là bộ phim hoạt hình lãng mạn hài hước: Victor – con trai một gia đình bán cá sắp làm đám cưới với Victoria – con gái của một gia đình quý tộc danh giá đang đến hồi khánh kiệt. Sau buổi “thực tập” cử hành hôn lễ bất thành, Victor đã một mình đi ra cánh rừng hoang vắng để tập dợt vai trò chú rể. Sau khi đọc xong lời nguyền, anh chàng Victor đã vô tình đeo chiếc nhẫn cưới vào một cành cây có hình dạng ngón tay ở một bìa rừng và đọc to lời thề vợ chồng. Không ngờ cành cây đó lại chính là ngón tay của một xác cô gái bị mưu sát đã lâu. Và như một câu chuyện cười có thật, bây giờ xác chết đó nhờ lời thề của Victor mà trở thành người vợ chính thức của anh chàng. Liệu người và ma, trần thế và địa ngục, ở đâu Victor sẽ tìm được tình yêu?</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Tracey Ullman","avatar":""},{"name":"Paul Whitehouse","avatar":""},{"name":"Joanna Lumley","avatar":""},{"name":"Albert Finney","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Christopher Lee","avatar":""},{"name":"Michael Gough","avatar":""},{"name":"Jane Horrocks","avatar":""},{"name":"Enn Reitel","avatar":""},{"name":"Deep Roy","avatar":""},{"name":"Danny Elfman","avatar":""},{"name":"Stephen Ballantyne","avatar":""},{"name":"Lisa Kay","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324526);
