INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-kich-bat-ngo', 'Đột Kích Bất Ngờ', 'The Marksman', 'https://phimimg.com/upload/vod/20231129-1/b1d0ba81ca07471cc576b3fe720a94e7.jpg', 'https://phimimg.com/upload/vod/20231129-1/e3d7c964b0a33603a31cb93bc2935b68.jpg', '<p>Phiến quân Chechnya tiếp quản một nhà máy hạt nhân của Nga và phải nhờ đến một đặc vụ bí ẩn (Snipes) để ngăn chặn chúng.</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wesley Snipes","avatar":""},{"name":"Emma Samms","avatar":""},{"name":"William Hope","avatar":""},{"name":"Anthony Warren","avatar":""},{"name":"Peter Youngblood Hills","avatar":""},{"name":"Ryan McCluskey","avatar":""},{"name":"Warren Derosa","avatar":""},{"name":"Christiaan Haig","avatar":""},{"name":"Gelu Nitu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
