INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khung-bo-o-munich', 'Vụ Khủng Bố Ở Munich', 'Munich', 'https://phimimg.com/upload/vod/20231129-1/2a2aee71f691732d7de3973c80d41ecc.jpg', 'https://phimimg.com/upload/vod/20231129-1/771270cf7bc0e8fe20ef322df24a7513.jpg', '<p>Phim mở màn bằng vụ tấn công chớp nhoáng vào những vận động viên Israel tại làng Olympic tại Munich, Tây Đức vào thời điểm đang diễn ra Thế vận hội năm 1972. Điều này đã khiến chính phủ Israel vô cùng giận dữ. Họ lên kế hoạch chiêu mộ một đội xuất sắc để tiêu diệt những kẻ khủng bố này. Nhóm này do Avner (Eric Bana) - cận vệ thân tín của Thủ tướng Golda Meir chỉ huy, sống rải rác ở các nước Tây Âu. Những thành viên chủ chốt của nhóm là Robert (Mathieu Kassovitz) - người chuyên chế tạo bom mìn, Carl (Ciarán Hinds) - người chuyên xóa bỏ dấu vết sau khi hành động, Steve (Daniel Craige) - thiện xạ bách phát bách trúng và Hans (Hanns Zischler) - người chuyên làm giấy tờ giả mạo. Họ được thay đổi toàn bộ lý lịch tại Israel, cắt đứt mọi liên hệ với gia đình, được trợ cấp toàn bộ tiền sinh hoạt và ăn chơi tại Tây Âu</p>', 'Full', 1, 'single', 'completed', 12, 2005, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Eric Bana","avatar":""},{"name":"Daniel Craig","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Mathieu Kassovitz","avatar":""},{"name":"Hanns Zischler","avatar":""},{"name":"Ayelet Zurer","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Gila Almagor","avatar":""},{"name":"Michael Lonsdale","avatar":""},{"name":"Mathieu Amalric","avatar":""},{"name":"Moritz Bleibtreu","avatar":""},{"name":"Valeria Bruni Tedeschi","avatar":""},{"name":"Meret Becker","avatar":""},{"name":"Marie-Josée Croze","avatar":""},{"name":"Yvan Attal","avatar":""},{"name":"Ami Weinberg","avatar":""},{"name":"Ly","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
