INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sahara-con-tau-tu-than', 'Sahara: Con Tàu Tử Thần', 'Sahara', 'https://phimimg.com/upload/vod/20231208-1/148702e3fc695ae29b95aed2f073e06a.jpg', 'https://phimimg.com/upload/vod/20231208-1/48d0487e32b1d791693b4bfd3db12ee2.jpg', '<p>Tận dụng tài chính của Quỹ Đô đốc Đô Mạch của Hoa Kỳ, bao gồm cả Cứu hộ Marine Tech Cứu thủ Navy Dirk Pitt của Hoa Kỳ Brilliant, bao gồm cả Buddy Al Giordino, trong đó giấc mơ tìm kiếm tiếng Việt bị mất tích bí ẩn trên tàu chiến Ironclad của cái chết. Các pitts va vào bằng chứng cho lý thuyết của mình, nó đã vượt qua Đại Tây Dương lên sông Nigeria, nơi Đô đốc có một dự án môi trường. Than ôi, đó là một chế độ độc tài Tây Phi nơi Tổng thống tàn nhẫn ngăn chặn những người sa mạc, trong giải đấu với tỷ phú công nghiệp năng lượng của Pháp Yves Massarde. Tiết kiệm liều lĩnh, những người nghiên cứu dịch bệnh Tiến sĩ Eva Rojas, anh ta biết bí mật bị cấm sử dụng độc hại độc hại của nhà vệ sinh bị bắt cóc, thông qua hệ thống dịch tiết dưới lòng đất, gây ô nhiễm đại dương và do đó gây ra dịch bệnh giết người toàn cầu.</p>', 'Full', 1, 'single', 'completed', 16, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324526);
