INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-dau-gau', 'Kẻ Đầu Gấu', 'Tsotsi', 'https://phimimg.com/upload/vod/20231127-1/b3baff01eb78515879451c153a7095d8.jpg', 'https://phimimg.com/upload/vod/20231127-1/405fe10a521ba751e714c63684df2ad1.jpg', '<p>Bộ phim đoạt nhiều giải thưởng của Nam Phi kể về một cậu bé Nam Phi từ khu ổ chuột tên là Tsotsi, nghĩa là Gangster. Tsotsi, người đã rời khỏi nhà khi còn nhỏ để thoát khỏi cha mẹ bơ vơ, tìm thấy một đứa bé ở băng ghế sau của chiếc ô tô mà anh ta vừa đánh cắp. Anh ấy quyết định rằng trách nhiệm của mình là chăm sóc đứa bé và trong quá trình đó, anh ấy biết rằng có lẽ cuộc sống xã hội đen không phải là cách tốt nhất.</p>', 'Full', 1, 'single', 'completed', 18, 2005, 'Vietsub', 'HD', 'Nam Phi', 0, '[{"name":"Presley Chweneyagae","avatar":""},{"name":"Jerry Mofokeng","avatar":""},{"name":"Terry Pheto","avatar":""},{"name":"Zenzo Ngqobe","avatar":""},{"name":"Zola","avatar":""},{"name":"Rapulana Seiphemo","avatar":""},{"name":"Nambitha Mpumlwana","avatar":""},{"name":"Percy Matsemela","avatar":""},{"name":"Thembi Nyandeni","avatar":""},{"name":"Owen Sejake","avatar":""},{"name":"Israel Makoe","avatar":""},{"name":"Sindi Khambule","avatar":""},{"name":"Benny Moshe","avatar":""},{"name":"Mothusi Magano","avatar":""},{"name":"Kenneth Nkosi","avatar":""},{"name":"Ian Roberts","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324526);
