INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quoc-thien-duong', 'Vương Quốc Thiên Đường', 'Kingdom of Heaven', 'https://phimimg.com/upload/vod/20231125-1/86e47c332e657d58bbb18de6c1a598db.jpg', 'https://phimimg.com/upload/vod/20231125-1/e3222a65da021f5b199b6562636be54a.jpg', '<p>Trận chiến vĩ đại thành Jerusalem trước quân đội của Vua Ai Cập Saladin được ghi vào lịch sử như một trận chiến của những người sùng đạo bảo vệ vương quốc thiên đàng linh thiêng của họ. Bộ phim các bạn sắp xem sẽ tái hiện lịch sử hùng tráng với những đại cảnh hành động ấn tượng của trận đại chiến lịch sử. Nhân vật chính là chàng thợ rèn Balian quả cảm, được số mệnh dẫn lối trở thành người lãnh đạo quân đội Jerusalem...</p>', 'Full', 1, 'single', 'completed', 26, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Orlando Bloom","avatar":""},{"name":"Eva Green","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Edward Norton","avatar":""},{"name":"Ghassan Massoud","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Alexander Siddig","avatar":""},{"name":"Khaled El Nabawy","avatar":""},{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"Kevin McKidd","avatar":""},{"name":"Velibor Topic","avatar":""},{"name":"Jon Finch","avatar":""},{"name":"Ulrich Th","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tra