INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-do-dang', 'Cuộc Sống Dở Dang', 'An Unfinished Life', 'https://phimimg.com/upload/vod/20231124-1/4cfa83cc226c2b73845af34be873c197.jpg', 'https://phimimg.com/upload/vod/20231124-1/3df3e022fed8fbfa07c5472841d9b538.jpg', '<p>Một góa phụ đau buồn mang con gái chuyển đến sống cùng người bố chồng xa cách ở Wyoming, nơi thời gian giúp họ hàn gắn và tha thứ.</p>', 'Full', 1, 'single', 'completed', 15, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Redford","avatar":""},{"name":"Jennifer Lopez","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Becca Gardner","avatar":""},{"name":"Josh Lucas","avatar":""},{"name":"Damian Lewis","avatar":""},{"name":"Camryn Manheim","avatar":""},{"name":"Lynda Boyd","avatar":""},{"name":"Rob Hayter","avatar":""},{"name":"P. Lynn Johnson","avatar":""},{"name":"Byron Lucas","avatar":""},{"name":"Trevor Moss","avatar":""},{"name":"R. Nelson Brown","avatar":""},{"name":"Dillard Brinson","avatar":""},{"name":"Jason Diablo","avatar":""},{"name":"Sean J. Dory","avatar":""},{"name":"Bryan Korenberg","avatar":""},{"name":"Bonn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324526);
