INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thao-xich-danny-doi-cho', 'Tháo Xích - Danny Đời Chó', 'Unleashed - Danny The Dog', 'https://phimimg.com/upload/vod/20231121-1/920458e667b2584fc3114469b71615f7.jpg', 'https://phimimg.com/upload/vod/20231121-1/4043ae064928ff902a228d6ad72a0e10.jpg', '<p>Unleashed (Tháo Xích) là bộ phim hành động kể về Danny, một chàng trai trẻ bị đối xử như một con chó và được nuôi dạy để trở thành một cỗ máy đánh nhau trong suốt khoảng thời gian bị cầm tù. Sau này, anh bị chứng hôn mê và được chăm sóc bởi những con người nhân hậu, thế nhưng tên chủ cũ ác độc của anh lại muốn tìm lại vũ khí nguy hiểm và đáng giá nhất của hắn : một chiến binh vô địch bị điều khiển bởi chiếc vòng quấn chặt lấy cổ. Rồi Danny gặp cha con Sam và Victoria, họ đã giúp cảm hóa Danny, loại bỏ tính cách tàn nhẫn đầy bạo lực mà anh bị nhồi nhét và huấn luyện từ nhiều năm nay.</p>', 'Full', 1, 'single', 'completed', 15, 2005, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jet Li","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Bob Hoskins","avatar":""},{"name":"Kerry Condon","avatar":""},{"name":"Vincent Regan","avatar":""},{"name":"Dylan Brown","avatar":""},{"name":"Tamer Hassan","avatar":""},{"name":"Phyllida Law","avatar":""},{"name":"Michael Jenn","avatar":""},{"name":"Carole Ann Wilson","avatar":""},{"name":"Mike Lambert","avatar":""},{"name":"Puthirith Chou","avatar":""},{"name":"Jaclyn Tze Wey","avatar":""},{"name":"Tony Theng","avatar":""},{"name":"Owen Lay","avatar":""},{"name":"Andy Beckwith","avatar":""},{"name":"Franck Xie Cheng","avatar":""},{"name":"Michael Webber","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324526);
