INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-nguy-hiem', 'Sứ Mệnh Nguy Hiểm', 'Serenity', 'https://phimimg.com/upload/vod/20231121-1/7c439f5d995bc88628e1e1b009933dac.jpg', 'https://phimimg.com/upload/vod/20231121-1/dc38bf9c0b819ee8a524296bffce069f.jpg', '<p>Bộ phim được làm dựa trên kịch bản chuyển thể từ một phim truyền hình tên là &quot;Firefly&quot;. Phim kể về cuộc phiêu lưu trong không gian của những người điều hành con tàu Serenity gồm thuyền trưởng Malcolm và các nhân viên là Zoe, Wash, Kaylee và Jayne. Khi Malcolm đồng ý chở 2 vị khách là vị bác sĩ trẻ Simon cùng với người chị có tinh thần bất ổn River thì những rắc rối bắt đầu xảy ra.</p>', 'Full', 1, 'single', 'completed', 16, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nathan Fillion","avatar":""},{"name":"Summer Glau","avatar":""},{"name":"Gina Torres","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Morena Baccarin","avatar":""},{"name":"Adam Baldwin","avatar":""},{"name":"Jewel Staite","avatar":""},{"name":"Sean Maher","avatar":""},{"name":"Ron Glass","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"David Krumholtz","avatar":""},{"name":"Michael Hitchcock","avatar":""},{"name":"Sarah Paulson","avatar":""},{"name":"Yan Feldman","avatar":""},{"name":"Rafael Feldman","avatar":""},{"name":"Nectar Rose","avatar":""},{"name":"Tamara Taylor","avatar":""},{"name":"Glenn H","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075