INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dinh-hon-lau-dai', 'Cuộc Đính Hôn Lâu Dài', 'A Very Long Engagement: On the Set of a Romantic Epic', 'null', 'https://phimimg.com/upload/vod/20231118-1/dc8e37422693176d467d4ff74d81c1c6.jpg', '<p>Bộ phim kể lại chuyện tình của Mathilde và hôn thê Maneck. Hai người đã thề non hẹn biển trước khi chàng trai ra trận năm 1916. Năm 1919, khi cuộc chiến chấm dứt, Mathilde lúc đó 19 tuổi được báo tin là vị hôn phu của cô, Maneck đã tử trận tại biên phòng Somme. Dựa theo trực giác, Mathilde đã quyết định đi điều tra, tìm tông tích người yêu, cô muốn biết trong trường hợp nào Maneck chết, hoặc Maneck có thật sự chết hay chăng. Trong hành trình của Mathilde, với những lời thuật lại của các nhân chứng còn sống có những chuyện dở khóc, dở cười, những mẫu chuyện đời, những mối tình cũng như hoàn cảnh của bốn anh lính cùng chung số phận với Maneck...</p>', 'Full', 1, 'single', 'completed', 14, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Audrey Tautou","avatar":""},{"name":"Gaspard Ulliel","avatar":""},{"name":"Jodie Foster","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324526);
