INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-notorious-bettie-page', 'The Notorious Bettie Page', 'The Notorious Bettie Page', 'https://phimimg.com/upload/vod/20231116-1/63915bedb976855cabf2aaadbf164ce5.jpg', 'https://phimimg.com/upload/vod/20231116-1/9fc1e96ec8c53703e86ec5970b93dd4e.jpg', '<p>Bettie Page lớn lên trong một gia đình theo đạo bảo thủ ở Tennessee và trở thành người mẫu ảnh gây sốt ở New York những năm 1950. Những bức ảnh ghim huyền thoại của Bettie đã khiến cô trở thành mục tiêu của cuộc điều tra của Thượng viện về nội dung khiêu dâm và biến cô thành một biểu tượng khiêu dâm tiếp tục làm say mê người hâm mộ cho đến ngày nay.</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gretchen Mol","avatar":""},{"name":"Chris Bauer","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Sarah Paulson","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"Tara Subkoff","avatar":""},{"name":"John Cullum","avatar":""},{"name":"Cara Seymour","avatar":""},{"name":"Austin Pendleton","avatar":""},{"name":"Norman Reedus","avatar":""},{"name":"Dallas Roberts","avatar":""},{"name":"Victor Slezak","avatar":""},{"name":"Ann Dowd","avatar":""},{"name":"Michael Gaston","avatar":""},{"name":"Jefferson Mays","avatar":""},{"name":"Aaron Lazar","avatar":""},{"name":"Benjamin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324526);
