INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-dien-dai-thanh', 'Tình Điên Đại Thánh', 'A Chinese Tall Story', 'https://phimimg.com/upload/vod/20231128-1/750d8b2122191a34f6d5a9e12158f6bf.jpg', 'https://phimimg.com/upload/vod/20231128-1/ec7957a638dfa5a51eb9a3325037f1bc.jpg', '<p>Nhà sư trẻ Taka và ba đệ tử của mình bị bắt bởi một cây ma quỷ. Taka trốn thoát nhờ cây gậy thần của Vua khỉ và quyết định giải thoát cho những người bạn đồng hành của mình. Trên đường đi, anh gặp một đồng minh kỳ lạ tên là Meiyan, một cô gái nửa người nửa quái vật. Khi Taka và người bạn mới của mình bắt đầu một cuộc phiêu lưu kỳ thú, họ sẽ phải đối mặt với nhiều khó khăn và trận chiến và rất có thể sẽ quyết định số phận của nhân loại và toàn vũ trụ...</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Nicholas Tse","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Chen Bolin","avatar":""},{"name":"Kenny Kwan","avatar":""},{"name":"Steven Cheung","avatar":""},{"name":"Isabella Leong","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Gordon Liu Chia-hui","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Lee Kin-Yan","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""},{"name":"Dai Jiaoqian","avatar":""},{"name":"Cheng Kai-Yan","avatar":""},{"name":"Mo Jan-Sou","avatar":""},{"name":"Cheuk Wan","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324526);
