INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-pha-lang', 'Sát Phá Lang', 'SPL: Kill Zone', 'https://phimimg.com/upload/vod/20231117-1/60615e2252ea7fe8a6e7244fbedb76a6.jpg', 'https://phimimg.com/upload/vod/20231117-1/66f7c951fe0f494017fbd245f4eb61a6.jpg', '<p>Bộ phim là cuộc đối đầu giữa hai cảnh sát điều tra với một tên trùm xã hội đen khôn ngoan và trợ thủ của hắn, một sát thủ vô tình. Những tình tiết gay cấn, những pha biểu diễn võ thuật đẹp mắt, các diễn viên nhập vai… Bộ phim đã kéo khán giả trở lại với thể loại phim hành động đặc trưng của Hong Kong.</p>', 'Full', 1, 'single', 'completed', 16, 2005, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Sammo Hung","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Ken Chang","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Danny Summer","avatar":""},{"name":"Austin Wai Tin-Chi","avatar":""},{"name":"Timmy Hung","avatar":""},{"name":"Jing Ke","avatar":""},{"name":"Kenji Tanigaki","avatar":""},{"name":"So Tung","avatar":""},{"name":"Vincent Sze","avatar":""},{"name":"Tat-Chee Chan","avatar":""},{"name":"Maggie Poon Mei Kei","avatar":""},{"name":"Jeff Kam Chun-Man","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
