INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-sap', 'Ngôi Nhà Sáp', 'House of Wax', 'https://phimimg.com/upload/vod/20231117-1/9e4071b985bea05c812656ce706b4395.jpg', 'https://phimimg.com/upload/vod/20231117-1/f1d470bbfdcdd7934fb6948e294c39de.jpg', '<p>Một nhóm bạn bị mắc kẹt trên đường đến một trận đấu bóng đá đến gần một bảo tàng tượng sáp bỏ hoang để được giúp đỡ. Nhưng các sự kiện diễn ra khiến họ phải chạy trốn khỏi những người anh em giết người quản lý nơi này.</p>', 'Full', 1, 'single', 'completed', 18, 2005, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Elisha Cuthbert","avatar":""},{"name":"Chad Michael Murray","avatar":""},{"name":"Brian Van Holt","avatar":""},{"name":"Paris Hilton","avatar":""},{"name":"Jared Padalecki","avatar":""},{"name":"Robert Ri''chard","avatar":""},{"name":"Jon Abrahams","avatar":""},{"name":"Damon Herriman","avatar":""},{"name":"Dragicia Debert","avatar":""},{"name":"Murray Smith","avatar":""},{"name":"Thomas Adamson","avatar":""},{"name":"Sam Harkess","avatar":""},{"name":"Emma Lung","avatar":""},{"name":"Andy Anderson","avatar":""},{"name":"Kendal Rae","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
