INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('little-manhattan', 'Little Manhattan', 'Little Manhattan', 'https://phimimg.com/upload/vod/20231113-1/f0d049f488413f2781f1f3813879aba9.jpg', 'https://phimimg.com/upload/vod/20231113-1/03b7950a951150085b643793a6d6e26b.jpg', '<p>Gabe mười tuổi chỉ là một đứa trẻ bình thường lớn lên ở Manhattan cho đến khi Rosemary Telesco bước vào cuộc đời cậu, thực sự là tham gia lớp học karate của cậu. Nhưng trước khi Gabe có thể nói cho Rosemary biết cảm giác của mình, cô ấy đã nói với anh ấy rằng cô ấy sẽ không đến trường công lập nữa. Gabe còn rất nhiều điều để tìm hiểu về cuộc sống, tình yêu và các cô gái.</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Hutcherson","avatar":""},{"name":"Charlie Ray","avatar":""},{"name":"Bradley Whitford","avatar":""},{"name":"Cynthia Nixon","avatar":""},{"name":"Willie Garson","avatar":""},{"name":"J. Kyle Manzay","avatar":""},{"name":"Josh Pais","avatar":""},{"name":"John Dossett","avatar":""},{"name":"Talia Balsam","avatar":""},{"name":"Jonah Meyerson","avatar":""},{"name":"Tonye Patano","avatar":""},{"name":"Connor Hutcherson","avatar":""},{"name":"Mike Chaturantabut","avatar":""},{"name":"Timothy Adams","avatar":""},{"name":"Jess Weixler","avatar":""},{"name":"Calvin Brown","avatar":""},{"name":"Alex Trebe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324526);
