INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hide-and-seek', 'Hide and Seek', 'Hide and Seek', 'https://phimimg.com/upload/vod/20231114-1/e035bec7657c84f529d73153a1964e7f.jpg', 'https://phimimg.com/upload/vod/20231114-1/b0d34134cdaa1e4191f081a95bd3582b.jpg', '<p>David Callaway cố gắng sắp xếp lại cuộc sống của mình sau vụ tự tử của vợ và phải một mình nuôi con gái chín tuổi, Emily. Lúc đầu, David rất thích thú khi phát hiện ra rằng Emily đã tạo ra một người bạn tưởng tượng tên là &quot;Charlie&quot;, nhưng không lâu sau &quot;Charlie&quot; đã tạo ra một người bạn tưởng tượng. phát triển một khía cạnh độc ác và bạo lực, và khi David phải vật lộn với những vấn đề tình cảm ngày càng gia tăng của con gái mình, anh nhận ra một điều đáng sợ rằng &quot;Charlie&quot; đang phải đối mặt với sự thật. không chỉ là sự tưởng tượng của Emily.</p>', 'Full', 1, 'single', 'completed', 16, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Elisabeth Shue","avatar":""},{"name":"Amy Irving","avatar":""},{"name":"Dylan Baker","avatar":""},{"name":"Melissa Leo","avatar":""},{"name":"Robert John Burke","avatar":""},{"name":"Molly Grant Kallins","avatar":""},{"name":"David Chandler","avatar":""},{"name":"Stewart Summers","avatar":""},{"name":"Jake Dylan Baumer","avatar":""},{"name":"Brendan Sexton III","avatar":""},{"name":"James McCaffrey","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324526);
