INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-cam', 'Hang Cấm', 'The Cave', 'https://phimimg.com/upload/vod/20231114-1/07d33b0f4eae4526dbfea919056c72b7.jpg', 'https://phimimg.com/upload/vod/20231114-1/76013305501b5149bc38bba180f44489.jpg', '<p>Một nhóm gồm những nhà thám hiểm và nhà khoa học đã khám phá ra một hệ thống hang động mới tại Romania. Tuy nhiên, một tai nạn đã xảy ra, và đá đã đổ xuống lấp mất lối ra. Sau khi đi sâu vào trong lòng hang động, cả nhóm đã phát hiện ra rằng nơi này là nơi cư ngụ của những sinh vật nguy hiểm đang chờ đợi họ...</p>', 'Full', 1, 'single', 'completed', 14, 2005, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Cole Hauser","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Morris Chestnut","avatar":""},{"name":"Eddie Cibrian","avatar":""},{"name":"Piper Perabo","avatar":""},{"name":"Daniel Dae Kim","avatar":""},{"name":"Kieran Darcy-Smith","avatar":""},{"name":"Rick Ravanello","avatar":""},{"name":"Marcel Iureș","avatar":""},{"name":"Vlad Rădescu","avatar":""},{"name":"Simon Kunz","avatar":""},{"name":"David Kennedy","avatar":""},{"name":"Alin Panc","avatar":""},{"name":"Zoltan Butuc","avatar":""},{"name":"Brian Steele","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
