INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-doi-9', 'Đại Đội 9', '9th Company', 'https://phimimg.com/upload/vod/20231115-1/ad802da099dba48f1ab0f3c360367268.jpg', 'https://phimimg.com/upload/vod/20231115-1/7a1860df4b93175a494e8775b83ccd99.jpg', '<p>Tiểu đoàn 9 là bộ phim hành động khai thác đề tài Chiến tranh Afghanistan của đạo diễn Fyodor Bondarchuk, ra mắt lần đầu năm 2007. Trong một buổi lễ chia tay tại Krasnoyarsk, một nhóm thanh niên tân binh của Liên Xô đang chuẩn bị cho sự ra đi đến căn cứ quân sự của họ. Khi đến phi thuyền tại thung lũng Fergana của Uzbekistan, họ gặp giáo sư Praporschik Dygalo, một cựu chiến binh dày dạn kinh nghiệm có nhiều chuyến đi đến Afghanistan và một huấn luyện viên tàn bạo. Trong quá trình huấn luyện, những tân binh phải vượt qua những khác biệt và xây dựng một mối quan hệ đoàn kết. Giữa các khoá đào tạo, họ nhận được các bài học về hoạt động chất dẻo nổ và cách tiến hành tại Afghanistan.</p>', 'Full', 1, 'single', 'completed', 20, 2005, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Aleksey Chadov","avatar":""},{"name":"Artur Smolyaninov","avatar":""},{"name":"Konstantin Kryukov","avatar":""},{"name":"Ivan Kokorin","avatar":""},{"name":"Artyom Mikhalkov","avatar":""},{"name":"Soslan Fidarov","avatar":""},{"name":"Mikhail Porechenkov","avatar":""},{"name":"Dmitriy Mukhamadeev","avatar":""},{"name":"Fyodor Bondarchuk","avatar":""},{"name":"Amadu Mamadakov","avatar":""},{"name":"Mikhail Evlanov","avatar":""},{"name":"Marat Gudiev","avatar":""},{"name":"Aleksandr Bashirov","avatar":""},{"name":"Ivan Nikolaev","avatar":""},{"name":"Irina Ra","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324526);
