INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-doi-tu-do', 'Đánh Đổi Tự Do', 'The Proposition', 'https://phimimg.com/upload/vod/20231111-1/4ece54462fcf1be7754bd1020791f3aa.jpg', 'https://phimimg.com/upload/vod/20231111-1/983afc04308269bb87e0a19e84a06f05.jpg', '<p>Trong một vùng sa mạc hoang vu ở Úc thời kỳ bị nước Anh chiếm đóng ở cuối thế kỷ 19, một gia đình bị sát hại dã man từ phụ nữ tới trẻ con do băng nhóm của anh em nhà Burns gây ra. Hối hận vì tội lỗi của mình, Charlie (Guy Pearce) rời khỏi băng nhóm cùng với người em út bị thiểu năng Mike Burns (Richard Wilson). Nhưng cả hai anh em bị đại úy Morris Stanley (Ray Winstone) bắt giữ và Stanley đã đưa ra một lời &quot;đề nghị&quot; cho Charlie. Nếu Charlie không bắt người anh cả Arthur (Danny Huston) của mình về chịu tội, thì vào Giáng sinh, Stanley sẽ treo cổ Mike...</p>', 'Full', 1, 'single', 'completed', 24, 2005, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Guy Pearce","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"John Hurt","avatar":""},{"name":"David Wenham","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Richard Wilson","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"Jeremy Madrona","avatar":""},{"name":"Jae Mamuyac","avatar":""},{"name":"Mick Roughan","avatar":""},{"name":"Shane Watt","avatar":""},{"name":"Robert Morgan","avatar":""},{"name":"David Gulpilil","avatar":""},{"name":"Bryan Probets","avatar":""},{"name":"Oliver Ackland","avatar":""},{"name":"David Vallon","avatar":""},{"name":"Daniel Parker","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324526);
