INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-chien-binh-tuong-lai', 'Nữ Chiến Binh Tương Lai', 'Æon Flux', 'https://phimimg.com/upload/vod/20231111-1/36b8b663655432549bcff477f8cc6175.jpg', 'https://phimimg.com/upload/vod/20231111-1/e1921326b40cf1eaa50f540cf9457408.jpg', '<p>400 năm sau, dịch bệnh đã quét sạch phần lớn dân số thế giới, ngoại trừ một thành phố có tường bao quanh, Bregna, được cai trị bởi một đại hội các nhà khoa học. Khi Æon Flux, đặc vụ hàng đầu trong cuộc nổi dậy ngầm &#39;Monican&#39;, được giao nhiệm vụ giết một nhà lãnh đạo chính phủ, cô khám phá ra một thế giới bí mật.</p>', 'Full', 1, 'single', 'completed', 15, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlize Theron","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Jonny Lee Miller","avatar":""},{"name":"Sophie Okonedo","avatar":""},{"name":"Frances McDormand","avatar":""},{"name":"Pete Postlethwaite","avatar":""},{"name":"Amelia Warner","avatar":""},{"name":"Caroline Chikezie","avatar":""},{"name":"Nikolai Kinski","avatar":""},{"name":"Paterson Joseph","avatar":""},{"name":"Yangzom Brauen","avatar":""},{"name":"Aoibheann O''Hara","avatar":""},{"name":"Thomas Huber","avatar":""},{"name":"Weijian Liu","avatar":""},{"name":"Maverick Quek","avatar":""},{"name":"Ra","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
