INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-manh-len-doi', 'Lưu Manh Lên Đời', 'Hustle & Flow', 'https://phimimg.com/upload/vod/20231111-1/e01e3656d151919fece3486599e91497.jpg', 'https://phimimg.com/upload/vod/20231111-1/ec8158f3bf70f97938a601e6cb21ebfa.jpg', '<p>DJay là một gã lưu manh đường phố buôn bán ma tuý. Hắn không cảm thấy cuộc đời mình có chút nào ý nghĩa. Sau đó, hắn gặp lại người bạn cũ và niềm say mê âm nhạc, ước mơ trở thành ca sĩ nhạc rap đã sống lại trong hắn. Cả hai cùng bắt tay với một tay trống người da trắng cho ra một ca khúc khởi đầu sự nghiệp mới</p>', 'Full', 1, 'single', 'completed', 19, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Terrence Howard","avatar":""},{"name":"Anthony Anderson","avatar":""},{"name":"Taryn Manning","avatar":""},{"name":"Taraji P. Henson","avatar":""},{"name":"DJ Qualls","avatar":""},{"name":"Ludacris","avatar":""},{"name":"Paula Jai Parker","avatar":""},{"name":"Elise Neal","avatar":""},{"name":"Isaac Hayes","avatar":""},{"name":"Jordan Houston","avatar":""},{"name":"William Engram","avatar":""},{"name":"Bobby Sandimanie","avatar":""},{"name":"Haystak","avatar":""},{"name":"Claude Phillips","avatar":""},{"name":"Josey Scott","avatar":""},{"name":"John Still","avatar":""},{"name":"Jay Munn","avatar":""},{"name":"Michael Hook","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324526);
