INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ngay-cuoi-cung-2005', 'Những Ngày Cuối Cùng', 'Sophie Scholl: The Final Days', 'https://phimimg.com/upload/vod/20231110-1/9471ac24a692a91bbbce70450c383fa4.jpg', 'https://phimimg.com/upload/vod/20231110-1/9398d48873ec88a94ab5cf87b1c1b957.jpg', '<p>Sophie Scholl: The Final Days - Die letzten Tage (Những Ngày Cuối Cùng) là phim truyện thứ ba của đạo diễn trẻ Marc Rothermund, kịch bản của Fred Breinersdorfer, nhà văn kiêm nhà soạn kịch và luật sư. Tác phẩm điện ảnh đến từ Đức đã đem lại 3 chiến thắng tại Liên hoan phim Berlin và 3 chiến thắng ở Liên hoan phim Châu Âu. Phim cũng được đề cử Oscar cho hạng mục Phim ngoại ngữ hay nhất 2006. Bộ phim được đón nhận nồng nhiệt ở nhiều nước châu Âu và là một phim có nhiều người xem nhất tại Pháp. Nó được đồng thanh khen ngợi là một tác phẩm kinh điển.</p>', 'Full', 1, 'single', 'completed', 15, 2005, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Julia Jentsch","avatar":""},{"name":"Fabian Hinrichs","avatar":""},{"name":"Alexander Held","avatar":""},{"name":"Johanna Gastdorf","avatar":""},{"name":"André Hennicke","avatar":""},{"name":"Florian Stetter","avatar":""},{"name":"Maximilian Brückner","avatar":""},{"name":"Johannes Suhm","avatar":""},{"name":"Jörg Hube","avatar":""},{"name":"Petra Kelling","avatar":""},{"name":"Franz Staber","avatar":""},{"name":"Lilli Jung","avatar":""},{"name":"Norbert Heckner","avatar":""},{"name":"Klaus Händl","avatar":""},{"name":"Maria Hofstätter","avatar":""},{"name":"Wolfgang Pregler","avatar":""},{"name":"Ch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324526);
