INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-trieu-dua-tre', 'Hàng triệu đứa trẻ', 'Millions', 'https://phimimg.com/upload/vod/20231110-1/26b54c6d83543d149ee9c139f225f9a9.jpg', 'https://phimimg.com/upload/vod/20231110-1/bece3b4e316bb5288bb63a2d5f75151a.jpg', '<p>Hai cậu bé, vẫn còn đau buồn trước cái chết của mẹ, vô tình trở thành ân nhân của một vụ cướp ngân hàng vào tuần trước khi Vương quốc Anh chuyển đồng tiền chính thức sang đồng Euro. Một đứa trẻ phải làm gì?</p>', 'Full', 1, 'single', 'completed', 14, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexander Nathan Etel","avatar":""},{"name":"Lewis McGibbon","avatar":""},{"name":"James Nesbitt","avatar":""},{"name":"Daisy Donovan","avatar":""},{"name":"Christopher Fulford","avatar":""},{"name":"Enzo Cilenti","avatar":""},{"name":"Alun Armstrong","avatar":""},{"name":"Jane Hogarth","avatar":""},{"name":"Pearce Quigley","avatar":""},{"name":"Nasser Memarzia","avatar":""},{"name":"Kathryn Pogson","avatar":""},{"name":"Harry Kirkham","avatar":""},{"name":"Cornelius Macarthy","avatar":""},{"name":"Kolade Agboke","avatar":""},{"name":"James Quinn","avatar":""},{"name":"Leslie Ph","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324526);
