INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-va-hong-sung', 'Nụ Hôn Và Họng Súng', 'Kiss Kiss Bang Bang', 'https://phimimg.com/upload/vod/20231109-1/8a537f94729273e4b09793c49a416e08.jpg', 'https://phimimg.com/upload/vod/20231109-1/98c48692dcd773875fb98029eace4f1a.jpg', '<p>Tại Los Angeles, tên lừa đảo Harry Lockhart (Robert Downey Jr.) phải chạy trốn cảnh sát sau một vụ cướp bất thành, tình cờ lạc vào một buổi thử giọng cho một bộ phim. Tại đây, Harry gặp lại Harmony Faith Lane (Michelle Monaghan), một diễn viên xinh đẹp từng làm anh điên đảo ở thời thơ ấu. Anh chàng cũng gặp Gay Perry (Val Kilmer), một tay thám tử tư mạo danh và đồng tính. Cùng lúc, một loạt những vụ sát hại phụ nữ vô cùng bí ẩn và phức tạp đang xảy ra khắp thành phố L.A, và Harry trở thành một thám tử bất đắc dĩ dưới sự hướng dẫn của Perry. Từ đó, Gay và Harry đã phát hiện ra nhiều điều bí ẩn và đen tối ẩn quanh những vụ ám sát nên 2 anh chàng &quot;gà chọi&quot; này đã quyết tâm điều tra vừa tìm ra sự thật vừa... kiếm tiền với sự giúp đỡ của cô nàng Harmony cũng đang khao khát sự giàu có bên cạnh sự nổi tiếng...</p>', 'Full', 1, 'single', 'completed', 15, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Val Kilmer","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Corbin Bernsen","avatar":""},{"name":"Dash Mihok","avatar":""},{"name":"Larry Miller","avatar":""},{"name":"Rockmond Dunbar","avatar":""},{"name":"Shannyn Sossamon","avatar":""},{"name":"Angela Lindvall","avatar":""},{"name":"Indio Falconer Downey","avatar":""},{"name":"Ariel Winter","avatar":""},{"name":"Duane Carnahan","avatar":""},{"name":"Josh Richman","avatar":""},{"name":"Martha Hackett","avatar":""},{"name":"Nancy Fish","avatar":""},{"name":"Bill McAdams Jr.","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
