INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-hoc-sieu-nhan', 'Trường Học Siêu Nhân', 'Sky High', 'https://phimimg.com/upload/vod/20231109-1/c3f6462a693aef5d6948d393d22f40aa.jpg', 'https://phimimg.com/upload/vod/20231109-1/48cf4fbcca3116fedb696e505b1103bc.jpg', '<p>Tất cả đều bắt đầu khi Young sẽ thành trì, con trai của hai siêu anh hùng nổi tiếng: Steve và Josie, A.K.A. Chỉ huy vô cùng mạnh mẽ, dường như bất khả xâm phạm và và JetStream bay tốc độ cao. Tuy nhiên, sẽ không thực sự biết nếu anh ta có bất kỳ sức mạnh nào của riêng mình, và đã không nói với cha mẹ mình này. Anh ấy và người bạn thân nhất của anh ấy, Layla đang đối mặt với ngày đầu tiên của một ngôi trường bí mật của họ trong những đám mây như không có trên Trái đất: Sky High, trường trung học đầu tiên và duy nhất dành cho trẻ em với sức mạnh siêu con người đi qua tuổi dậy thì chiến đấu tội phạm. Nhưng không có siêu năng lực rõ ràng của riêng mình, tuy nhiên, dường như sẽ được định sẵn để lớn lên một Sidekick. Nhưng khi anh phát hiện ra những điểm mạnh thực sự của mình, anh ta cũng sẽ học được rằng nó có lòng trung thành và tinh thần đồng đội để thực sự trở thành một anh hùng!</p>', 'Full', 1, 'single', 'completed', 16, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Angarano","avatar":""},{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Kurt Russell","avatar":""},{"name":"Kelly Preston","avatar":""},{"name":"Danielle Panabaker","avatar":""},{"name":"Bruce Campbell","avatar":""},{"name":"Lynda Carter","avatar":""},{"name":"Kevin Heffernan","avatar":""},{"name":"Dee Jay Daniels","avatar":""},{"name":"Kelly Vitz","avatar":""},{"name":"Loren Berman","avatar":""},{"name":"Nicholas Braun","avatar":""},{"name":"Steven Strait","avatar":""},{"name":"Malika","avatar":""},{"name":"Khadijah Haqq McCray","avatar":""},{"name":"Jake Sandvig","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324526);
