INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bao-ve-2005', 'Người Bảo Vệ', 'The Protector', 'https://phimimg.com/upload/vod/20231026-1/cf353484703e363d9e5238834d24535b.jpg', 'https://phimimg.com/upload/vod/20231026-1/272a8fc13d4d4467730c9c9c7a7e188a.jpg', '<p>Tại Bangkok, cậu bé Kham được cha nuôi dưỡng trong rừng cùng những chú voi như một thành viên trong gia đình. Khi con voi già của mình và con Kern con bị bọn tội phạm đánh cắp, Kham phát hiện ra rằng những con vật đó đã được gửi đến Sidney. Anh ta đi đến Úc, nơi anh ta tìm thấy chú voi con trong một nhà hàng thuộc sở hữu của Madame Rose độc ác, thủ lĩnh của một tổ chức mafia Thái quốc tế. Với sự hỗ trợ của trung sĩ Thái Lan hiệu quả Mark, người đã tham gia vào một âm mưu, Kham chiến đấu để giải cứu con vật khỏi đám đông.</p>', 'Full', 1, 'single', 'completed', 20, 2005, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Tony Jaa","avatar":""},{"name":"Petchtai Wongkamlao","avatar":""},{"name":"Bongkoj Khongmalai","avatar":""},{"name":"Jin Xing","avatar":""},{"name":"Nathan Jones","avatar":""},{"name":"Johnny Nguyen","avatar":""},{"name":"Lateef Crowder","avatar":""},{"name":"Jonathan Patrick Foo","avatar":""},{"name":"Damian de Montemas","avatar":""},{"name":"David Asavanond","avatar":""},{"name":"Ron Smoorenburg","avatar":""},{"name":"Kittapon Wattanasinchai","avatar":""},{"name":"Patrarin Punyanutatam","avatar":""},{"name":"Surasak Chaiat","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
