INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-ice-harvest', 'The Ice Harvest', 'The Ice Harvest', 'https://phimimg.com/upload/vod/20231108-1/f1578bbc6e7d5f191d51b5b9c984ba07.jpg', 'https://phimimg.com/upload/vod/20231108-1/875a792342dad0c4b951e62e3141962b.jpg', '<p>Hành vi larceny, ham muốn và gây chết người. Trong thác nước IceBound, Texas, đó là đêm Giáng sinh, và năm nay Charlie Arglist chỉ có thể có một cái gì đó để ăn mừng. Charlie, một luật sư cho các doanh nghiệp nhếch nhác của Thác Wichita, và cộng sự không lành mạnh của ông, Stely Vic Cavanaugan vừa tham gia thành công 2 triệu đô la từ Boss Boss Boss của Thành phố Kansas. Nhưng giải thưởng thực sự dành cho Charlie là Renata tuyệt đẹp, người điều hành Câu lạc bộ Dải Lồng Sweet. Charlie hy vọng sẽ tuột khỏi thị trấn với Renata. Nhưng khi ánh sáng ban ngày mờ dần và một cơn bão băng, tất cả mọi người từ bạn thân của Charlie Pete van Heuten đến cảnh sát địa phương bắt đầu tự hỏi chính xác những gì trong stocking Giáng sinh của Charlie - và 12 giờ đêm Giáng sinh tràn ngập những bất ngờ.</p>', 'Full', 1, 'single', 'completed', 14, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cusack","avatar":""},{"name":"Billy Bob Thornton","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"Randy Quaid","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Mike Starr","avatar":""},{"name":"Ned Bellamy","avatar":""},{"name":"T.J. Jagodowski","avatar":""},{"name":"David Pasquesi","avatar":""},{"name":"Lara Phillips","avatar":""},{"name":"Bill Noble","avatar":""},{"name":"Brad Smith","avatar":""},{"name":"Meghan Maureen McDonough","avatar":""},{"name":"Jenny Wade","avatar":""},{"name":"Tab Baker","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324526);
