INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-san-bang', 'Công Chúa Sân Băng', 'Ice Princess', 'https://phimimg.com/upload/vod/20231108-1/22d5fa7b4e982bea2ba8c669a8f54276.jpg', 'https://phimimg.com/upload/vod/20231108-1/894e4a805397580837f88eee44610b2d.jpg', '<p>Với sự giúp đỡ của huấn luyện viên, mẹ cô và cậu bé điều khiển cỗ máy Zamboni, không gì có thể ngăn cản Casey thực hiện ước mơ trở thành nhà vô địch trượt băng nghệ thuật.</p>', 'Full', 1, 'single', 'completed', 16, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Trachtenberg","avatar":""},{"name":"Joan Cusack","avatar":""},{"name":"Amy Stewart","avatar":""},{"name":"Steve Ross","avatar":""},{"name":"Hayden Panettiere","avatar":""},{"name":"Kim Cattrall","avatar":""},{"name":"Trevor Blumas","avatar":""},{"name":"Kirsten Olson","avatar":""},{"name":"Jocelyn Lai","avatar":""},{"name":"Connie Ray","avatar":""},{"name":"Paul Sun-Hyung Lee","avatar":""},{"name":"Roy Bradshaw","avatar":""},{"name":"Mark Hird","avatar":""},{"name":"Ben Gilbank","avatar":""},{"name":"Thanh Nguyen","avatar":""},{"name":"Cole Campbell","avatar":""},{"name":"Brandon Lajko","avatar":""},{"name":"Jess","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324526);
