INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-na-xanh-nhi', 'Mặt Nạ Xanh Nhí', 'Son of the Mask', 'https://phimimg.com/upload/vod/20231108-1/b12f6a094512933c9d04cb22cb9cdb52.jpg', 'https://phimimg.com/upload/vod/20231108-1/737f342c47f26b88a76224f6c4ac3460.jpg', '<p>Tim Avery, một họa sĩ vẽ tranh biếm họa đầy tham vọng, rơi vào tình thế khó khăn khi chú chó của anh tình cờ nhìn thấy chiếc mặt nạ của Loki. Sau đó, sau khi thụ thai một cậu con trai sơ sinh &quot;được sinh ra từ chiếc mặt nạ&quot;, anh ấy phát hiện ra việc nuôi dạy một đứa trẻ có thể trở nên tồi tệ như thế nào.</p>', 'Full', 1, 'single', 'completed', 18, 2005, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Jamie Kennedy","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Traylor Howard","avatar":""},{"name":"Kal Penn","avatar":""},{"name":"Steven Wright","avatar":""},{"name":"Ben Stein","avatar":""},{"name":"Peter Callan","avatar":""},{"name":"Liam Falconer","avatar":""},{"name":"Ryan Falconer","avatar":""},{"name":"Brett Pickup","avatar":""},{"name":"Ashley Lyons","avatar":""},{"name":"Wayne McDaniel","avatar":""},{"name":"Sandy Winton","avatar":""},{"name":"Rebecca Massey","avatar":""},{"name":"Issac Longmuir","avatar":""},{"name":"Tayzin Fahey-Leigh","avatar":""},{"name":"Skyla Laginha","avatar":""},{"name":"Lochi","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324526);
