INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-tu-than', 'Biệt Đội Tử Thần', 'Doom', 'https://phimimg.com/upload/vod/20231108-1/ec0a02f02cc45545ce624c6c787a4aa8.jpg', 'https://phimimg.com/upload/vod/20231108-1/b01214dacd8eae866c9f31d48bcfc1fa.jpg', '<p>Vào năm 2046, tại Nevada người ta phát minh ra một portal để đưa người lên sao hoả chỉ trong tíc tắc. Thế là nhân dịp này họ đưa hàng tá nhà khoa học và lập nên một “viện nghiên cứu” để nghiên cứu về Sao hoả. Do dễ dàng như vậy nên ko như thất bại của các phi thuyền trước đó, lần này họ thành công trong việc xây dựng một phức hợp khá đồ sộ trên bề mặt sao Hoả. Và quan trọng hơn, sau khi đào bới một hồi thì họ phát hiện ra sao Hoả từng có người sinh sống trên đó… Viện nghiên cứu xảy ra các biến cố kỳ lạ. Mọi công việc nghiên cứu bị đình trệ. Hệ thống liên lạc không thể sử dụng được nữa. Mức độ báo động lên đến cấp độ 5 và Biệt đội Phản ứng nhanh vào cuộc. Họ được trang bị tận răng các vũ khí tối tân nhất để bước vào cuộc chiến đấu với Sarge và Reaper là hai người đứng đầu của đội.</p>', 'Full', 1, 'single', 'completed', 15, 2005, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Karl Urban","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Deobia Oparei","avatar":""},{"name":"Razaaq Adoti","avatar":""},{"name":"Al Weaver","avatar":""},{"name":"Ben Daniels","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Dexter Fletcher","avatar":""},{"name":"Doug Jones","avatar":""},{"name":"Brian Steele","avatar":""},{"name":"Yao Chin","avatar":""},{"name":"Robert Russell","avatar":""},{"name":"Daniel York","avatar":""},{"name":"Ian Hughes","avatar":""},{"name":"Sara Houghton","avatar":""},{"name":"Blanka Jarosova","avatar":""},{"name":"Vladislav Dyntera","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324526);
