INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-dau-bo', 'Võ Sĩ Đấu Bò', 'The Matador', 'https://phimimg.com/upload/vod/20231107-1/7fbca5733ceec16ae746979cbedc501c.jpg', 'https://phimimg.com/upload/vod/20231107-1/161e648aabe40d1940d142b6cfc20684.jpg', '<p>Sát thủ tên Julian Noble chợt nhận ra cuộc sống thật bạc bẽo khi hắn chẳng có lấy một người bạn bên cạnh. Vào một dịp tình cờ Julian quen được Danny Wright, một doanh nhân đang bị vận xui đeo đuổi. Julian và Danny kết bạn với nhau và các tình huống hài hước xảy ra .</p>', 'Full', 1, 'single', 'completed', 14, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Greg Kinnear","avatar":""},{"name":"Hope Davis","avatar":""},{"name":"Portia Dawson","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"Israel Tellez","avatar":""},{"name":"Arlin Miller","avatar":""},{"name":"Azucena Medina","avatar":""},{"name":"Jonah Meyerson","avatar":""},{"name":"Wiveca Bonerais","avatar":""},{"name":"Roberto Sosa","avatar":""},{"name":"Antonio Zavala Kugler","avatar":""},{"name":"Ramon Alvarez","avatar":""},{"name":"Luz Maria Molina","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Rachel Schwartz","avatar":""},{"name":"Ca","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
