INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-cuoi', 'Ngày Cưới', 'The Wedding Date', 'https://phimimg.com/upload/vod/20231107-1/fed905495768c0253ecba9a4b5aed9cf.jpg', 'https://phimimg.com/upload/vod/20231107-1/7be3b56915d88fce4ca0fc0cc34b3fd2.jpg', '<p>Câu chuyện bắt đầu với việc cơn ác mộng tồi tệ nhất của Kat Ellis (Debra Messing) trở thành hiện thực. Người em gái cùng mẹ khác cha Amy (Amy Adam) lên xe hoa trước cô và tệ hơn nữa phù rể chính là vị hôn phu cũ của cô, Jeffrey (Jeremy Sheffield). Sau khi bị anh ta bỏ rơi 2 năm trước, Kat tới New York sống, vẫn cô đơn và muốn tìm một người đàn ông đích thực cho mình. Vốn luôn là tâm điểm của sự chú ý từ thời còn đi học, Kat không thể về nhà dự đám cưới em gái tại London một mình. Vì thế, cô quyết định thuê một anh chàng hoàn hảo vào vai bạn trai. Đó là Nick (Dermot Mulroney), một người đàn ông đẹp trai, thông minh, khéo ăn nói, nhạy cảm, nói chung là một quý ông hoàn hảo đáng với 6.000 USD Kat bỏ ra. Kế hoạch của họ là làm kẻ đã bỏ rơi cô nàng phải hối hận. Nhưng “âm mưu” của Kat bị chệch hướng khi cô cảm thấy bị Nick quyến rũ, và dường như chính Nick cũng thấy bị hấp dẫn bởi Kat. Mối quan hệ giữa họ sẽ đi đến đâu khi bị ràng buộc bởi giao kèo từ lúc trước?</p>', 'Full', 1, 'single', 'completed', 15, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Debra Messing","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Amy Adams","avatar":""},{"name":"Jack Davenport","avatar":""},{"name":"Jeremy Sheffield","avatar":""},{"name":"Peter Egan","avatar":""},{"name":"Sarah Parish","avatar":""},{"name":"Holland Taylor","avatar":""},{"name":"Jay Simon","avatar":""},{"name":"Danielle Lewis","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324526);
