INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-xem-ai', 'Đoán Xem Ai', 'Guess Who', 'https://phimimg.com/upload/vod/20231107-1/1ba4f138f55394ed930fb54b5c8ed36a.jpg', 'https://phimimg.com/upload/vod/20231107-1/a8cd2decc699cd06b33f8292eed87861.jpg', '<p>Đoán Xem Ai - Guess Who xoay quanh cuộc sống của Theresa. Nhân dịp kỷ niệm lần thứ 25 đám cưới của bố mẹ, Theresa quyết định giới thiệu chàng rể tương lai với gia đình. Mọi chuyện trở nên rắc rối khi cô lại không thông báo cho họ anh là người da trắng. Còn Simon thì giấu cô chuyện anh đã thôi việc ở một ngân hàng đầu tư danh tiếng. Cả hai người lờ đi chuyện này khiến cho hiểu lầm nối tiếp hiểu lầm và rắc rối lên đến đỉnh điểm khi họ đổ tội cho nhau trong khi cả hai cần đoàn kết lại để “chiến đấu” với ông bố khó tính.</p>', 'Full', 1, 'single', 'completed', 14, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bernie Mac","avatar":""},{"name":"Ashton Kutcher","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Judith Scott","avatar":""},{"name":"Hal Williams","avatar":""},{"name":"Kellee Stewart","avatar":""},{"name":"Jessica Cauffiel","avatar":""},{"name":"Robert Curtis Brown","avatar":""},{"name":"RonReaco Lee","avatar":""},{"name":"Paula Newsome","avatar":""},{"name":"Niecy Nash","avatar":""},{"name":"Sherri Shepherd","avatar":""},{"name":"Phil Reeves","avatar":""},{"name":"Nicole Sullivan","avatar":""},{"name":"JoNell Kennedy","avatar":""},{"name":"Kimberly Scott","avatar":""},{"name":"Denise Dows","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324526);
