INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dot-kich-vi-dai', 'Cuộc Đột Kích Vĩ Đại', 'The Great Raid', 'https://phimimg.com/upload/vod/20231103-1/2286ca54b505340bcda6b875a7e581b2.jpg', 'https://phimimg.com/upload/vod/20231103-1/97d0f0e2223ef0c18a17661df5f05cf3.jpg', '<p>Bộ phim tái hiện một sự kiện lịch sử chưa từng được kể. Trong Thế chiến thứ hai, đại đội đặc nhiệm Mỹ đột kích vào một trại tập trung giữa rừng sâu do hàng nghìn lính Nhật canh giữ để giải cứu hơn 500 tù binh chiến tranh. Trên thực tế, cho tới nay vụ đột kích cabanatuan vẫn được đánh giá là chiến dịch giải cứu thành công nhất trong lịch sử quân đội mỹ. 121 lính đặc nhiệm đã giải thoát 512 tù binh và tiêu diệt hơn 500 lính nhật. Chỉ có 2 lính mỹ và 21 du kích philippines hy sinh...</p>', 'Full', 1, 'single', 'completed', 18, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Franklin D. Roosevelt","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"James Franco","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"Logan Marshall-Green","avatar":""},{"name":"Joseph Fiennes","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Robert Mammone","avatar":""},{"name":"Max Martini","avatar":""},{"name":"Mark Consuelos","avatar":""},{"name":"Cesar Montano","avatar":""},{"name":"James Carpinello","avatar":""},{"name":"Clayne Crawford","avatar":""},{"name":"Motoki Kobayashi","avatar":""},{"name":"Gotaro Tsunashima","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324526);
