INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-sang-tren-sao-diem-vuong', 'Bữa Sáng Trên Sao Diêm Vương', 'Breakfast on Pluto', 'https://phimimg.com/upload/vod/20231103-1/dd5d68fb0b804ae1df870a6a242f25e7.jpg', 'https://phimimg.com/upload/vod/20231103-1/b44cb1e5d757449b1c0146f07f0a9ea3.jpg', '<p>Vào những năm 1970, một phụ nữ trans trẻ, Patrick &quot;Mèo con&quot; Braden, đến tuổi bằng cách rời khỏi thị trấn Ailen của mình cho London, một phần để tìm mẹ và một phần vì bản sắc giới tính của cô nằm ngoài sự hiểu biết của thị trấn.</p>', 'Full', 1, 'single', 'completed', 15, 2005, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Eva Birthistle","avatar":""},{"name":"Ruth Negga","avatar":""},{"name":"Laurence Kinlan","avatar":""},{"name":"Stephen Rea","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Conor McEvoy","avatar":""},{"name":"Bryan Ferry","avatar":""},{"name":"Antonia Campbell-Hughes","avatar":""},{"name":"Eamonn Owens","avatar":""},{"name":"Owen Roe","avatar":""},{"name":"Paraic Breathnach","avatar":""},{"name":"Ruth McCabe","avatar":""},{"name":"Charlene McKenna","avatar":""},{"name":"Chris McHallem","avatar":""},{"name":"Dominic C","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324526);
