INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('charlie-va-nha-may-socola', 'Charlie và Nhà Máy Sôcôla', 'Charlie and the Chocolate Factory', 'https://phimimg.com/upload/vod/20231103-1/5cd98ebbd20ebd6e1db59c26014c6ba2.jpg', 'https://phimimg.com/upload/vod/20231103-1/de14143b065ed3203c13e69573d48dd7.jpg', '<p>Willi Wonka là một người sản xuất chocolate nổi tiếng nhất thế giới, mở một cuộc thi mà người thắng giải sẽ được vào tham quan nhà máy sản xuất chocolate của mình. Nhà nghèo, cậu bé Charlie Bucket phải sớm lao động để giúp đỡ gia đình ao ước được ăn thật nhiều kẹo, em tham gia trò chơi may mắn của Willy Wonka, ông chủ nhà máy chocolate tuyệt diệu nhất thế giới. Wonka giấu 5 tấm vé vàng trong những thanh chocolate, ai tìm thấy những tấm vé này sẽ được thưởng một chuyến tham quan đặc biệt tại nhà máy chocolate. Charlie tìm được một vé và bắt đầu cuộc phiêu lưu kỳ diệu cùng 4 đứa trẻ khác...</p>', 'Full', 1, 'single', 'completed', 15, 2005, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Freddie Highmore","avatar":""},{"name":"David Kelly","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"Missi Pyle","avatar":""},{"name":"James Fox","avatar":""},{"name":"Deep Roy","avatar":""},{"name":"Christopher Lee","avatar":""},{"name":"Adam Godley","avatar":""},{"name":"Franziska Troegner","avatar":""},{"name":"AnnaSophia Robb","avatar":""},{"name":"Julia Winter","avatar":""},{"name":"Jordan Fry","avatar":""},{"name":"Philip Wiegratz","avatar":""},{"name":"Blair Dunlop","avatar":""},{"name":"Liz Smith","avatar":""},{"name":"Eileen E","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaa