INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-phieu-luu-cua-ban-nhac-rock', 'Chuyến Phiêu Lưu Của Ban Nhạc Rock', 'Stomp! Shout! Scream!', 'https://phimimg.com/upload/vod/20231110-1/b1c0042f0a0b3265341336519ba29186.jpg', 'https://phimimg.com/upload/vod/20231110-1/3fcf225e00345ff3c9d943e310cb8979.jpg', '<p>Chuyến Phiêu Lưu Của Ban Nhạc Rock - Stomp! Shout! Scream! kể về một biến cố trên đảo Merriville khi có một tàn dư xuất hiện trên bãi biển. Một loạt vụ thám án và mất tích xảy ra liên tục và không có lời giải đáp. Cùng lúc đó, các cô gái ban nhạc rock Viola đang thực hiện tua lưu diễn tại đó. Kẻ giết người là ai? Bí ẩn là gì? Các cô gái sẽ gặp phải khó khăn gì?</p>', 'Full', 1, 'single', 'completed', 17, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Claire Bronson","avatar":""},{"name":"Cynthia Evans","avatar":""},{"name":"Mary Kraft","avatar":""},{"name":"Jonathan Michael Green","avatar":""},{"name":"Travis Young","avatar":""},{"name":"Christopher Hines","avatar":""},{"name":"Adrian Roberts","avatar":""},{"name":"Bill Szymanski","avatar":""},{"name":"Alex Orr","avatar":""},{"name":"Edward Hastings","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324526);
