INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngan-can-than-chet', 'Ngăn Cản Thần Chết', 'The Jacket', 'https://phimimg.com/upload/vod/20231101-1/4dd81c3f4ecbe640e536732e8b90abb2.jpg', 'https://phimimg.com/upload/vod/20231101-1/d7b9baf5556e709a47a8b7dac7d9be7c.jpg', '<p>Một cựu quân nhân bắt đầu cuộc hành trình đến tương lai, nơi anh ta có thể thấy trước cái chết của mình và để lại những câu hỏi có thể cứu mạng anh ta và những người anh ta yêu thương.</p>', 'Full', 1, 'single', 'completed', 19, 2005, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Adrien Brody","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Kris Kristofferson","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Kelly Lynch","avatar":""},{"name":"Brad Renfro","avatar":""},{"name":"Daniel Craig","avatar":""},{"name":"Angel Coulby","avatar":""},{"name":"Steven Mackintosh","avatar":""},{"name":"Brendan Coyle","avatar":""},{"name":"Mackenzie Phillips","avatar":""},{"name":"Laura Marano","avatar":""},{"name":"Jason Lewis","avatar":""},{"name":"Richard Dillane","avatar":""},{"name":"Jonah Lotan","avatar":""},{"name":"Nigel Whitmey","avatar":""},{"name":"Ia","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324526);
