INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zathura-chuyen-phieu-luu-vu-tru', 'Zathura: Chuyến Phiêu Lưu Vũ Trụ', 'Zathura: A Space Adventure', 'https://phimimg.com/upload/vod/20231101-1/07eb44a7719855f12f0e8f0129a8f17e.jpg', 'https://phimimg.com/upload/vod/20231101-1/05be609e649b42797daad019ed09c71d.jpg', '<p>Phim Zathura: A Space Adventure (Zathura: Chuyến Phiêu Lưu Vũ Trụ) là bộ phim hài hước xoay quanh cuộc phiêu lưu ngoài không gian của hai anh em Danny và Walter khi tình cờ chơi một bộ trò chơi cũ có tên Zathura. Oái ăm ở chỗ, nếu không chiến thắng trong trò chơi này thì hai anh em sẽ bị nhốt trong thế giới ngoài vũ trụ trong trò chơi mãi mãi. Liệu Danny và Walter có dành chiến thắng cuối cùng? Chuyến du hành không gian của họ có gì thú vị?</p>', 'Full', 1, 'single', 'completed', 12, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Hutcherson","avatar":""},{"name":"Jonah Bobo","avatar":""},{"name":"Dax Shepard","avatar":""},{"name":"Kristen Stewart","avatar":""},{"name":"Tim Robbins","avatar":""},{"name":"Frank Oz","avatar":""},{"name":"John Alexander","avatar":""},{"name":"Derek Mears","avatar":""},{"name":"Douglas Tait","avatar":""},{"name":"Joe Bucaro III","avatar":""},{"name":"Jeff Wolfe","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324526);
