INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-mo-coi', 'Cậu Bé Mồ Côi', 'Oliver Twist', 'https://phimimg.com/upload/vod/20231101-1/31112ad8ec443367cb3177eb87663803.jpg', 'https://phimimg.com/upload/vod/20231101-1/6cbd98d6056b8ee79cdb701f9836e017.jpg', '<p>Oliver Twist phiên bản quay phim hiện đại của cuốn sách bán chạy nhất của Charles Dickens, một bản chuyển thể của Roman Polanski. Câu chuyện cổ điển của Dickens, nơi một đứa trẻ mồ côi gặp một tên móc túi trên đường phố London. Từ đó, anh gia nhập một gia đình gồm những cậu bé được huấn luyện để ăn trộm cho chủ nhân của chúng.</p>', 'Full', 1, 'single', 'completed', 23, 2005, 'Vietsub', 'HD', 'Séc', 0, '[{"name":"Barney Clark","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Jamie Foreman","avatar":""},{"name":"Harry Eden","avatar":""},{"name":"Edward Hardwicke","avatar":""},{"name":"Leanne Rowe","avatar":""},{"name":"Ian McNeice","avatar":""},{"name":"Chris Overton","avatar":""},{"name":"Andy Linden","avatar":""},{"name":"Teresa Churcher","avatar":""},{"name":"Jake Curran","avatar":""},{"name":"Turbo","avatar":""},{"name":"Lewis Chase","avatar":""},{"name":"Levi Hayes","avatar":""},{"name":"Jeremy Swift","avatar":""},{"name":"Gillian Hanna","avatar":""},{"name":"Michael Heath","avatar":""},{"name":"Patrick Godfrey","avatar":""},{"name":"Mark","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324526);
