INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-kich-hoang-da', 'Bi Kịch Hoang Dã', 'Grizzly Man', 'https://phimimg.com/upload/vod/20231101-1/032db5b05d1348b9206cb28834c1c6bc.jpg', 'https://phimimg.com/upload/vod/20231101-1/4e9d5434adb09f14e75223eeb6e94b11.jpg', '<p>Bộ phim là cuốn biên niên sử về cuộc đời và cái chết của Timothy Treadwell – một người có niềm đam mê mãnh liệt với những chú gấu xám Bắc Mỹ. Bộ phim đi lần theo từng bước chân của ông trong suốt chặng đường dài ông sống và tiếp xúc với loài gấu hung tợn này trước khi bản thân mình và bạn gái bị chính những con gấu giết chết và ăn thịt vào năm 2003. Song song đó là những bài phỏng vấn riêng về những người thân, bạn bè xung quanh Treadwell. Phần băng ghi hình sau cùng của ông rốt cục cũng được tìm thấy, và được Discovery Docs – đơn vị chuyên làm phim tài liệu trực thuộc kênh Discovery Channel và Lions Gate Entertaiment đồng sản xuất.</p>', 'Full', 1, 'single', 'completed', 20, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Timothy Treadwell","avatar":""},{"name":"Kathleen Parker","avatar":""},{"name":"Warren Queeney","avatar":""},{"name":"Willy Fulton","avatar":""},{"name":"Sam Egli","avatar":""},{"name":"Werner Herzog","avatar":""},{"name":"David Letterman","avatar":""},{"name":"Jewel Palovak","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324526);
