INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-vang-den', 'Đế Chế Vàng Đen', 'Syriana', 'https://phimimg.com/upload/vod/20231101-1/0e7c542772beb832e8e9e03e4604d7c5.jpg', 'https://phimimg.com/upload/vod/20231101-1/d6db580f398de438ddaa3d3b370024f7.jpg', '<p>Ngành công nghiệp dầu mỏ Trung Đông là bối cảnh của vở kịch căng thẳng này, đan xen nhiều mạch truyện lại với nhau. Bennett Holiday là một luật sư người Mỹ chịu trách nhiệm tạo điều kiện thuận lợi cho việc sáp nhập các công ty dầu mỏ đáng ngờ, trong khi Bryan Woodman, một nhà phân tích năng lượng có trụ sở tại Thụy Sĩ, trải qua cả bi kịch cá nhân và cơ hội trong chuyến thăm hoàng gia Ả Rập. Trong khi đó, đặc vụ CIA kỳ cựu Bob Barnes phát hiện ra một âm mưu ám sát có nguồn gốc đáng lo ngại.</p>', 'Full', 1, 'single', 'completed', 15, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"William Hurt","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Alexander Siddig","avatar":""},{"name":"Kayvan Novak","avatar":""},{"name":"Amr Waked","avatar":""},{"name":"Robert Foxworth","avatar":""},{"name":"Nicky Henson","avatar":""},{"name":"Nicholas Art","avatar":""},{"name":"Steven Hinkle","avatar":""},{"name":"Daisy Tormé","avatar":""},{"name":"Peter Gerety","avatar":""},{"name":"Richard Lintern","avatar":""},{"name":"Ma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
