INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-on-vi-hut-thuoc', 'Cảm Ơn Vì Hút Thuốc', 'Thank You for Smoking', 'https://phimimg.com/upload/vod/20231031-1/c167a947822fe2127945976e5a39c0cd.jpg', 'https://phimimg.com/upload/vod/20231031-1/7643fc9073e29a9e7e71f2ec0205f757.jpg', '<p>Nick Naylor là một bác sĩ quay đầy lôi cuốn của Big Tobacco, người sẽ chiến đấu để bảo vệ quyền hút thuốc của nước Mỹ - ngay cả khi điều đó giết chết anh ta - trong khi vẫn là hình mẫu cho cậu con trai 12 tuổi của mình. Khi hứng chịu cơn thịnh nộ của một thượng nghị sĩ đang cố gắng dập tắt thuốc lá, khả năng &quot;lọc lọc sự thật&quot; của Nick sẽ bị thử thách.</p>', 'Full', 1, 'single', 'completed', 14, 2005, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Aaron Eckhart","avatar":""},{"name":"Maria Bello","avatar":""},{"name":"Cameron Bright","avatar":""},{"name":"Adam Brody","avatar":""},{"name":"Sam Elliott","avatar":""},{"name":"Katie Holmes","avatar":""},{"name":"Rob Lowe","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"David Koechner","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Kim Dickens","avatar":""},{"name":"Connie Ray","avatar":""},{"name":"Joan Lunden","avatar":""},{"name":"Mary Jo Smith","avatar":""},{"name":"Todd Louiso","avatar":""},{"name":"Jeff Witzke","avatar":""},{"name":"Marianne Muellerleile","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324526);
