INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-trum-chien-tranh', 'Ông Trùm Chiến Tranh​', 'Lord of War', 'https://phimimg.com/upload/vod/20231030-1/8715c9cd7e425b2f8e7c11fcd9c110b9.jpg', 'https://phimimg.com/upload/vod/20231030-1/b0910c87f99f5edff8b9892e8043a735.jpg', '<p>Bộ phim lấy bối cảnh nước Mỹ những năm đầu thập niên 80. Yuri Orlov (Nicolas Cage) là người gốc Ukraina nhưng theo gia đình chuyển tới thành phố New York từ khi còn nhỏ. Sống giữa một thành phố có tỷ lệ phạm pháp cao vào bậc nhất nước Mỹ, ngay từ nhỏ Yuri đã quen với cảnh bắn giết. Cho rằng bạo lực sẽ chẳng bao giờ biến mất trong xã hội, gã ta nảy ra ý định làm giàu bằng con đường buôn súng.</p>', 'Full', 1, 'single', 'completed', 19, 2005, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Bridget Moynahan","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Eamonn Walker","avatar":""},{"name":"Ian Holm","avatar":""},{"name":"Sammi Rotibi","avatar":""},{"name":"Tanit Phoenix","avatar":""},{"name":"Shake Tukhmanyan","avatar":""},{"name":"Jared Burke","avatar":""},{"name":"David Shumbris","avatar":""},{"name":"Weston Cage Coppola","avatar":""},{"name":"Jeremy Crutchley","avatar":""},{"name":"Jean-Pierre Nshanian","avatar":""},{"name":"Eric Uys","avatar":""},{"name":"Stewart Morgan","avatar":""},{"name":"Jasper Len","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324526);
