INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-toi-ac', 'Thành Phố Tội Ác', 'Sin City', 'https://phimimg.com/upload/vod/20231030-1/2c55dbb149b6b9f791cdf32452c54467.jpg', 'https://phimimg.com/upload/vod/20231030-1/8fdd83145b4d61405869e4aec2659c39.jpg', '<p>Sin City (Thành Phố Tội Ác) được trích từ ba tập trong bộ truyện tranh dài kỳ của Frank Miller. Câu chuyện thứ nhất: “The Hard Goodbye” với Mickey Rourke trong vai Marv, một tên đồ tể hình dáng dị hợm, báo thù cho cô gái điếm mà hắn tôn thờ bởi cô là người duy nhất dám ngủ với hắn nhưng lại bị giết chết ngay trong đêm ái ân ấy. Câu chuyện thứ hai: “The Big Fat Kill”, Clive Owen trong vai Dwight McCarthy, tay nhiếp ảnh gia vô tình giết chết một tên cớm bẩn khiến thỏa thuận ngầm giữa băng gái điếm và cảnh sát bị phá vỡ, gây ra một cuộc đối đầu đáng sợ. Câu chuyện thứ ba: “That Yellow Bastard”, Bruce Willis trong vai viên cảnh sát John Hartigan, người tốt hiếm hoi trên đời đã phải trả giá đắt khi bảo vệ một vũ nữ thoát y ngây thơ. Ba mẩu chuyện rời rạc này được làm theo dạng chương hồi và quy về một mối ở đoạn cuối khiến người xem bất ngờ.</p>', 'Full', 1, 'single', 'completed', 12, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Jessica Alba","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Rutger Hauer","avatar":""},{"name":"Benicio del Toro","avatar":""},{"name":"Alexis Bledel","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Powers Boothe","avatar":""},{"name":"Nick Stahl","avatar":""},{"name":"Devon Aoki","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Josh Hartnett","avatar":""},{"name":"Jaime King","avatar":""},{"name":"Brittany Murphy","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324526);
