INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naruto-huyen-thoai-da-gelel', 'Naruto: Huyền Thoại Đá Gelel', 'Naruto the Movie: Legend of the Stone of Gelel', 'https://phimimg.com/upload/vod/20231030-1/875ed09419acf562355ef1730c251961.jpg', 'https://phimimg.com/upload/vod/20231030-1/4d2cbd168ef8a196cd5d4229f9893f68.jpg', '<p>Naruto the Movie 2: Huyền Thoại Đá Gelel: Câu chuyện mở đầu với trận chiến tại một bờ biển hoang vắng vào ban đêm giữa ninja làng Cát và những tên khổng lồ mặc chiếc áo giáp nâu. Những ninja làng Cát đang hoàn toàn bị thất thế trước những tên to lớn này. Một trận chiến mới của Naruto bắt đầu.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2005, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Junko Takeuchi","avatar":""},{"name":"Chie Nakamura","avatar":""},{"name":"Gaamon Kai","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Showtaro Morikubo","avatar":""},{"name":"Takako Honda","avatar":""},{"name":"Yasuyuki Kase","avatar":""},{"name":"Sachiko Kojima","avatar":""},{"name":"Tomoka Kurokawa","avatar":""},{"name":"Houko Kuwashima","avatar":""},{"name":"Akio Nojima","avatar":""},{"name":"Nachi Nozawa","avatar":""},{"name":"Urara Takano","avatar":""},{"name":"Yuko Kato","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324526);
