INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-de-lac-da-2', 'Hoàng Đế Lạc Đà 2', 'Kronk''s New Groove', 'https://phimimg.com/upload/vod/20231030-1/fbfa1ac9676349ba5a20225994bf0f4b.jpg', 'https://phimimg.com/upload/vod/20231030-1/293a78e9bebf0342bbdb435f7bce62cc.jpg', '<p>The Emperor&quot;s New Groove 2: Kronk&quot;s New Groove là phần thứ hai của loạt phim hoạt hình nổi tiếng The Emperor&quot;s New Groove của Walt Disney. Trong phần này, Kronk bắt đầu cuộc sống bình thường với một công việc thú vị là đầu bếp. Mọi thứ đều rất bình yên và vui vẻ nếu như anh không nhận được lệnh triệu tập llama-gram. Nội dung của bức thứ nói về chuyến thăm sắp tới của cha anh. Ông mong mỏi được gặp Kronk cùng vợ và các con của anh trong một ngôi nhà trên đỉnh đồi. Nhưng hiện thực mà ông mơ ước thì lại không như vậy. Liệu Kronk sẽ làm gì để qua mặt được bố mình đây?</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Warburton","avatar":""},{"name":"Tracey Ullman","avatar":""},{"name":"Eartha Kitt","avatar":""},{"name":"David Spade","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Wendie Malick","avatar":""},{"name":"John Mahoney","avatar":""},{"name":"John Fiedler","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Bob Bergen","avatar":""},{"name":"Brian Cummings","avatar":""},{"name":"Patti Deutsch","avatar":""},{"name":"Anthony Ghannam","avatar":""},{"name":"Gatlin Kate James","avatar":""},{"name":"Jessie Flower","avatar":""},{"name":"Eli Russell Linnetz","avatar":""},{"name":"Mark Loti","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":