INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-quy', 'Hang Quỷ', 'The Descent', 'https://phimimg.com/upload/vod/20231030-1/08af024ffe1868e8769570f7061f2607.jpg', 'https://phimimg.com/upload/vod/20231030-1/e1074eda6372b555cd52bc4abb200fb3.jpg', '<p>Bộ phim xoay quanh một nhóm sáu cô gái dẫn đầu bởi Juno (Natalie Mendoza) gồm có Sarah, Beth, Sam, Rebecca và Holly trong một chuyến thám hiểm hang động. Cả nhóm đã lên kế hoạch đầy đủ và chắc chắn rằng đây là một hang động đã được khám phá, tuy nhiên năm người còn lại không hề biết rằng vì tính hiếu kì mà Juno đã dẫn họ đến một hang động chưa được khám phá để thám hiểm.
 Cả sáu cô gái sau đó đã bị mắc kẹt trong hang và đối mặt với lũ quái vật hình thù kì dị và khát máu, các cô phải tìm đường thoát thân và cùng lúc ấy các cô phát hiện ra nỗi sợ thực sự không phải chỉ đến từ con quái vật kia, mà còn xuất phát từ một người trong chính họ. Phim có nội dung khá quen thuộc nhưng cách dẫn dắt phim của đạo diễn khá tốt, các cảnh kinh dị và trốn chạy vô cùng hồi hộp, kịch tích</p>', 'Full', 1, 'single', 'completed', 16, 2005, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Shauna Macdonald","avatar":""},{"name":"Natalie Mendoza","avatar":""},{"name":"Alex Reid","avatar":""},{"name":"MyAnna Buring","avatar":""},{"name":"Saskia Mulder","avatar":""},{"name":"Nora-Jane Noone","avatar":""},{"name":"Leslie Simpson","avatar":""},{"name":"Oliver Milburn","avatar":""},{"name":"Molly Kayll","avatar":""},{"name":"Craig Conway","avatar":""},{"name":"Tristan Matthiae","avatar":""},{"name":"Mark Cronfield","avatar":""},{"name":"Stephen Lamb","avatar":""},{"name":"Catherine Dyson","avatar":""},{"name":"Julie Ellis","avatar":""},{"name":"Sophie Trott","avatar":""},{"name":"Stuart Luis","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324526);
