INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-khu-toi-ac', 'Quá Khứ Tội Ác', 'A History of Violence', 'https://phimimg.com/upload/vod/20231026-1/05c616ddd76a541b8d45517d154e7dac.jpg', 'https://phimimg.com/upload/vod/20231026-1/03a8628fc8ec3cf5bfc12d4f77b9fba9.jpg', '<p>Tom Stall được xem là một trong những người đứng đầu một thành phố nhỏ nơi anh cùng người vợ và hai đứa con của mình sống những ngày êm đềm bằng việc kinh doanh một quán ăn. Nhưng rồi cuộc sống của gia đình anh bị xáo trộn khi anh trở thành anh hùng của thành phố khi phá vỡ được một vụ cướp và được các hãng truyền thông ca ngợi hết lời. Việc này gây chú ý cho một nhóm cướp và rắc rối liên tục đến với Tom Stall khi bọn chúng nghĩ rằng anh không phải chỉ là một kẻ bình thường như những người khác...</p>', 'Full', 1, 'single', 'completed', 16, 2005, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Viggo Mortensen","avatar":""},{"name":"Maria Bello","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"William Hurt","avatar":""},{"name":"Ashton Holmes","avatar":""},{"name":"Peter MacNeill","avatar":""},{"name":"Heidi Hayes","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Greg Bryk","avatar":""},{"name":"Kyle Schmid","avatar":""},{"name":"Sumela Kay","avatar":""},{"name":"Gerry Quigley","avatar":""},{"name":"Deborah Drakeford","avatar":""},{"name":"Bill MacDonald","avatar":""},{"name":"Aidan Devine","avatar":""},{"name":"Morgan Kelly","avatar":""},{"name":"Ian Matthews","avatar":""},{"name":"Jason Barb","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324526);
