INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-cau-be-ca-map-va-co-gai-nham-thach', 'Cuộc Phiêu Lưu của Cậu Bé Cá Mập và Cô Gái Nham Thạch', 'The Adventures of Sharkboy and Lavagirl', 'https://phimimg.com/upload/vod/20231026-1/545b3154b1ed904f8d8823494ff4404a.jpg', 'https://phimimg.com/upload/vod/20231026-1/0c57ff371dce18422d1a3cf4a6da0407.jpg', '<p>Những người bạn tưởng tượng – Cậu bé cá mập thông thái và Cô gái nham thạch có thể tạo lửa – hóa thân vào đời thực để giúp cậu nhóc 10 tuổi mơ mộng chống lại bạn xấu.</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Taylor Lautner","avatar":""},{"name":"Taylor Dooley","avatar":""},{"name":"Cayden Boyd","avatar":""},{"name":"David Arquette","avatar":""},{"name":"Kristin Davis","avatar":""},{"name":"Jacob Davich","avatar":""},{"name":"Sasha Pieterse","avatar":""},{"name":"George Lopez","avatar":""},{"name":"Rico Torres","avatar":""},{"name":"Marc Musso","avatar":""},{"name":"Shane Graham","avatar":""},{"name":"Tiger Darrow","avatar":""},{"name":"Racer Rodriguez","avatar":""},{"name":"Rebel Rodriguez","avatar":""},{"name":"Rocket Rodriguez","avatar":""},{"name":"Robert Rodriguez","avatar":""},{"name":"Araceli Gonzá","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324527);
