INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-phieu-luu-cua-cau-be-ca-map-va-co-gai-nham-thach', 'Cuộc Phiêu Lưu của Cậu Bé Cá Mập và Cô Gái Nham Thạch', 'The Adventures of Sharkboy and Lavagirl', 'cuộc phiêu lưu của cậu bé cá mập và cô gái nham thạch the adventures of sharkboy and lavagirl taylor lautner taylor dooley cayden boyd david arquette kristin davis jacob davich sasha pieterse george lopez rico torres marc musso shane graham tiger darrow racer rodriguez rebel rodriguez rocket rodriguez robert rodriguez araceli gonzá ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lilo-va-stitch-2-phep-mau-yeu-thuong', 'Lilo Và Stitch 2: Phép Màu Yêu Thương', 'Lilo & Stitch 2: Stitch Has a Glitch', 'https://phimimg.com/upload/vod/20231026-1/b393526ae1cd170d8ad299cd93c59f65.jpg', 'https://phimimg.com/upload/vod/20231026-1/b858a61530b4e07d296d0c5fa9a79fe1.jpg', '<p>Stitch được Jumba tạo ra bằng một thí nghiệm gien, nhưng khi bắt đầu nạp điện cho Stitch thì cảnh sát Liên ngân hà ập vào bắt Jumba đi. Khi đó quá trình nạp điện chưa đầy đủ, Stitch như một cỗ máy chưa ăn nhịp, chạy không đều, thỉnh thoảng lên những cơn như cơn động kinh của con người địa cầu, và sẵn sàng phá hủy mọi thứ xung quanh.Nhà bác học Jumba biết lỗ hổng này trong con người Stitch nên cố gắng tạo ra một Buồng hợp nhất, mong sạc lại dòng điện cho Stitch.Trong một diễn biến khác, Stitch cùng Lilo đi tìm ý tưởng cho điệu múa hula trong kỳ tranh tài ngày 1 tháng 5 tới kề bên, bằng cách đi theo hành trình của ông hoàng nhạc rock Elvis Presley. Sau khi đã có ý tưởng và chuẩn bị đầy đủ thì Stitch lại lên những cơn liên tiếp. ...</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Sanders","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Tia Carrere","avatar":""},{"name":"David Ogden Stiers","avatar":""},{"name":"Kevin McDonald","avatar":""},{"name":"Kunewa Mook","avatar":""},{"name":"Jason Scott Lee","avatar":""},{"name":"William J. Caparella","avatar":""},{"name":"Holliston Coleman","avatar":""},{"name":"Matt Corboy","avatar":""},{"name":"Jennifer Hale","avatar":""},{"name":"Jillian Henry","avatar":""},{"name":"Liliana Mumy","avatar":""},{"name":"Emily Osment","avatar":""},{"name":"Paul Vogt","avatar":""},{"name":"Grace Rolek","avatar":""},{"name":"Bill Farm","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324527);
