INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-bat-dau', 'Người Dơi Bắt Đầu', 'Batman Begins', 'https://phimimg.com/upload/vod/20231023-1/c5fe0b9f5815ac736bb25aad1ee879dd.jpg', 'https://phimimg.com/upload/vod/20231023-1/b4f3e1b2cff5e3e5e0ce210c3a998afb.jpg', '<p>Bruce Wayne thuở nhỏ là một cậu bé mắc chứng sợ dơi và có bố mẹ bị giết bởi tên cướp tên Joe Chill. Lớn lên, nung nấu ý định trả thù, Bruce Wayne rời khỏi thành phố và gặp được Henri Ducard, người truyền dạy cho anh những bí kíp võ thuật. Từ đây, với bản chất lương thiện, Bruce Wayne trở thành người hùng trừ gian diệt ác của thành phố… Với sự tham gia của dàn diễn viên nổi tiếng Christian Bale, Katie Holmes, Gary Oldman và được dàn dựng bởi đạo diễn tài ba Christopher Nolan, chỉ vài tháng sau khi ra mắt, Batman Begins đã được độc giả của tạp chí Empire bầu chọn đứng thứ 36 trong các phim hay nhất mọi thời đại, trở thành một trong những huyền thoại của dòng phim siêu anh hùng.</p>', 'Full', 1, 'single', 'completed', 14, 2005, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Katie Holmes","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Cillian Murphy","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Mark Boone Junior","avatar":""},{"name":"Linus Roache","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"Rutger Hauer","avatar":""},{"name":"Gus Lewis","avatar":""},{"name":"Emma Lockhart","avatar":""},{"name":"Larry Holden","avatar":""},{"name":"Colin McFarlane","avatar":""},{"name":"Christine Adams","avatar":""},{"name":"Vi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324527);
