INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-van-chuyen-2', 'Người Vận Chuyển 2', 'Transporter 2', 'https://phimimg.com/upload/vod/20231023-1/4b5fc0c21b3a36e7c6c1d537fc9755b5.jpg', 'https://phimimg.com/upload/vod/20231023-1/ca380e0cfa07ba269120ef885a774ea4.jpg', '<p>Sau khi nghỉ hưu ở Miami, cựu nhân viên của Lực lượng đặc biệt - Frank Martin hành nghề tài xế cho gia đình giàu có Billings. Frank được hai cậu nhóc của gia đình đó rất thần tượng và yêu mến. Khi hai cậu bé bị bắt cóc tống tiền anh đã một mình hành động mà không báo cảnh sát để giải cứu hai người bạn nhỏ.</p>', 'Full', 1, 'single', 'completed', 18, 2005, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Amber Valletta","avatar":""},{"name":"Alessandro Gassmann","avatar":""},{"name":"Kate Nauta","avatar":""},{"name":"Matthew Modine","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Keith David","avatar":""},{"name":"Hunter Clary","avatar":""},{"name":"Shannon Briggs","avatar":""},{"name":"François Berléand","avatar":""},{"name":"Raymond Tong","avatar":""},{"name":"George Kapetan","avatar":""},{"name":"Jeff Chase","avatar":""},{"name":"Gregg Weiner","avatar":""},{"name":"Gregg Davis","avatar":""},{"name":"AnnaLynne McCord","avatar":""},{"name":"Reggie Pier","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324527);
