INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-van-chuyen-2', 'Người Vận Chuyển 2', 'Transporter 2', 'người vận chuyển 2 transporter 2 jason statham amber valletta alessandro gassmann kate nauta matthew modine jason flemyng keith david hunter clary shannon briggs françois berléand raymond tong george kapetan jeff chase gregg weiner gregg davis annalynne mccord reggie pier ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-wars-phan-3-su-tra-thu-cua-nguoi-sith', 'Star Wars: Phần 3 - Sự Trả Thù Của Người Sith', 'Star Wars: Episode III - Revenge of the Sith', 'https://phimimg.com/upload/vod/20231023-1/e93462f25795c24d552f9449fa5af648.jpg', 'https://phimimg.com/upload/vod/20231023-1/1be6b5d3d54f9524c191eb5f09fe7fc8.jpg', '<p>Bộ phim diễn ra trong khoảng thời gian sau ba năm dai dẳng của cuộc chiến tranh trong dãy thiên hà, và cuộc chiến tranh vô tính cũng gần sắp tới hồi kết thúc. Hội đồng các hiệp sĩ Jedi giao nhiệm vụ cho Obi-Wan Kenobi tóm cổ tên tướng Grievous, kẻ cầm đầu chủ chốt của đội quân ly khai Separatist đem ra xét xử về tội lỗi mà hắn gây ra. Cùng lúc đó trên hành tinh Coruscant, thủ tướng Palpatine ngày càng tăng thêm quyền lực của mình.&nbsp; Sức mạnh cả trong đường lối chính trị của ông ta đã từng bước biến đổi thể chế cộng hòa từng xa lánh chiến tranh thành một đế quốc Galactic hùng cường hiếu chiến. Đối với đồng minh thân cận nhất của mình, Anakin Skywalker, ông ta dần hé lộ bản chất thật sự của quyền lực nơi ông ta muốn hướng đến và lời hứa bí mật với phe Force trong một nỗ lực chiêu dụ anh đứng về phía ác...</p>', 'Full', 1, 'single', 'completed', 13, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hayden Christensen","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Ian McDiarmid","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Jimmy Smits","avatar":""},{"name":"Frank Oz","avatar":""},{"name":"Anthony Daniels","avatar":""},{"name":"Christopher Lee","avatar":""},{"name":"Keisha Castle-Hughes","avatar":""},{"name":"Silas Carson","avatar":""},{"name":"Jay Laga''aia","avatar":""},{"name":"Bruce Spence","avatar":""},{"name":"Wayne Pygram","avatar":""},{"name":"Temuera Morrison","avatar":""},{"name":"David Bower","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324527);
