INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-den-tu-dia-nguc', 'Người Đến Từ Địa Ngục', 'Constantine', 'https://phimimg.com/upload/vod/20231020-1/028b25ad12ae1692f202e4064843eb06.jpg', 'https://phimimg.com/upload/vod/20231020-1/65241b67b021ac701f53ae9aeade41a8.jpg', '<p>John Constantine, người được tạo hóa ban tặng một món quà mà anh hoàn toàn không muốn, đó là khả năng nhận diện bản thể của thiên thần và ác quỷ tồn tại trong mỗi con người, chuyên điều tra những vụ án đầy huyền bí và siêu nhiên. Anh hợp tác với nữ thám tử Los Angeles là Angela Dodson điều tra cái chết bí ẩn của chị gái sinh đôi bị tâm thần Isabel Dodson. Khi còn sống, Isabel thường nhắc đến những điều quái dị mà người thường không thấy được. Lúc này trên vùng sa mạc Mexico, mầm mống của cái ác và bóng tối đang chờ cơ hội để trỗi dậy.</p>', 'Full', 1, 'single', 'completed', 20, 2005, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Shia LaBeouf","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Max Baker","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Gavin Rossdale","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Jesse Ramirez","avatar":""},{"name":"José Zúñiga","avatar":""},{"name":"April Grace","avatar":""},{"name":"Larry Cedar","avatar":""},{"name":"Francis Guinan","avatar":""},{"name":"Suzanne Whang","avatar":""},{"name":"Jhoanna Trias","avatar":""},{"name":"Alice Lo","avatar":""},{"name":"Nicholas","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324527);
