INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kieu-hanh-va-dinh-kien', 'Kiêu Hãnh và Định Kiến', 'Pride & Prejudice', 'https://phimimg.com/upload/vod/20231019-1/9a5647c48ab759949951c39ffc9aa8b7.jpg', 'https://phimimg.com/upload/vod/20231019-1/214350ac39076c40ffd2927b6effd0ae.jpg', '<p>Pride &amp; Prejudice là một bộ phim tình cảm của đạo diễn Joe Wright dựa trên cuốn tiểu thuyết cùng tên của nhà văn Jane Austen xuất bản năm 1813. Phim xoay quanh câu chuyện của năm chị em trong một gia đình tiểu quý tộc tại Anh. Họ luôn phải đối mặt với những vấn đề trong hôn nhân, tư cách đạo đức và quan niệm sai lầm. Jane xinh đẹp và mạnh mẽ, Elizabeth (Keira Knightley) thông minh, Mary (Talulah Riley) ham học, Kitty (Carey Mulligan) nhí nhảnh và Lydia (Jena Malone) hoang dã. Cuộc sống của họ diễn ra êm đềm cho đến khi một chàng trai trẻ giàu có, Bingley (Simon Woods), và bạn thân của anh, Darcy (Matthew MacFadyen) trở thành hàng xóm của họ. Nhiều sự cố từ đó bắt đầu nảy sinh...</p>', 'Full', 1, 'single', 'completed', 18, 2005, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Keira Knightley","avatar":""},{"name":"Matthew Macfadyen","avatar":""},{"name":"Brenda Blethyn","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Jena Malone","avatar":""},{"name":"Carey Mulligan","avatar":""},{"name":"Talulah Riley","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Simon Woods","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Claudie Blakley","avatar":""},{"name":"Peter Wight","avatar":""},{"name":"Penelope Wilton","avatar":""},{"name":"Kelly Reilly","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"Sylvester","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324527);
