INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-nien-su-narnia-su-tu-phu-thuy-va-cai-tu-ao', 'Biên Niên Sử Narnia: Sư Tử, Phù Thủy và Cái Tủ Áo', 'The Chronicles of Narnia: The Lion, the Witch and the Wardrobe', 'https://phimimg.com/upload/vod/20231018-1/0e8ec88b56c00dda678805df5eea41ba.jpg', 'https://phimimg.com/upload/vod/20231018-1/0d922463e4fffd0bba4803af3949c29b.jpg', '<p>Dựa theo cuốn tiểu thuyết của CS Lewis, 4 đứa trẻ tại Luân Đôn được gửi về nhà một vị giáo sư tại miền quê hoang vắng nhằm tránh khỏi cuộc thế chiến thứ 2. Trong một lần chơi trốn tìm, bọn trẻ đã khám phá ra một chiếc tủ áo, là cánh cửa dẫn đến một thế giới kỳ lạ mang tên Narnia, một vùng đất chịu sự cai quản của một mụ phù thuỷ độc ác. Để đánh bại mụ phù thủy, bọn trẻ phải gia nhập vào hàng ngũ của Aslan, vị thần sư tử của Narnia, và từ đây, một cuộc chiến đấu diễn ra giữa cái thiện và ác.</p>', 'Full', 1, 'single', 'completed', 18, 2005, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Georgie Henley","avatar":""},{"name":"Skandar Keynes","avatar":""},{"name":"William Moseley","avatar":""},{"name":"Anna Popplewell","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"James McAvoy","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Kiran Shah","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Judy McIntosh","avatar":""},{"name":"Elizabeth Hawthorne","avatar":""},{"name":"Patrick Kake","avatar":""},{"name":"Shane Rangi","avatar":""},{"name":"Brandon Cook","avatar":""},{"name":"Cassie Cook","avatar":""},{"name":"Morris Lupton","avatar":""},{"name":"Shelly Edwards","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324527);
