INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hung-nam-qua-nu', 'Hung Nam Quả Nữ', 'Set Up', 'null', 'https://phimimg.com/upload/vod/20231009-1/56866ef0fb451879f1ca75db014c27e8.jpg', '<p>Đạo diễn Billy Chung đã thành công trong việc tạo ra sự căng thẳng tột độ trong Set up như ông đã từng làm trong tác phẩm trước Color of the Loyalty với Vương Tinh. Christy Chung vào vai Moon, một nhà văn viết truyện kinh dị sắp kết hôn với một doanh nhân. Để chữa khỏi bệnh cận thị trước ngày cưới, cô phải trải qua một cuộc phẫu thuật mắt khiến cô bị mù trong ba ngày. Trong khi đó, cô ở trong ngôi nhà mới ở một khu vực hẻo lánh và yên tĩnh cùng với chị gái Yan. Ở đó, cô trải qua nỗi lo lắng thực sự trước hôn nhân khi ba tên cướp đột nhập vào nhà cô! Khi thị lực dần hồi phục, Moon cố gắng hết sức để tự cứu mình trong khi cô nhận ra rằng rốt cuộc mình có thể đã bị sắp đặt...</p>', 'Full', 1, 'single', 'completed', 20, 2005, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Christy Chung","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Roy Cheung","avatar":""},{"name":"Cheung Yiu-Yeung","avatar":""},{"name":"Tony Ho","avatar":""},{"name":"Johnny Lu","avatar":""},{"name":"Marco Lok Nik-Wai","avatar":""},{"name":"Alan Ng Wing-Lun","avatar":""},{"name":"Pang Mei-Seung","avatar":""},{"name":"Winnie Leung","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324527);
