INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuc-cua-quyet-dinh', 'Khúc Cua Quyết Định', 'Initial D', 'https://phimimg.com/upload/vod/20231006-1/a0d152c1e447df19ee6a69a5ddf1bef6.jpg', 'https://phimimg.com/upload/vod/20231006-1/dd11758b1a504ffa2fb9f9fc354deb38.jpg', '<p>Initial D mang đến cho khán giả những màn lạng lách nghẹt thở mà nhiều người cho rằng nó chỉ có trong trí tưởng tượng. Phim thể hiện đa dạng những cuộc đua nguy hiểm từ các thành phố đông đúc cho đến sườn núi tăm tối, quanh co. Initial D có sự tham gia của các ngôi sao châu Á: Châu Kiệt Luân, Trần Quán Hy, Huỳnh Thu Sinh, Dư Văn Lạc, Anne Suzuki... Bộ phim có kinh phí thực hiện 12 triệu USD, do Lưu Vĩ Cường và Mạch Triệu Huy - hai đạo diễn nổi tiếng với bộ ba phim Vô gian đạo – thực hiện.</p>', 'Full', 1, 'single', 'completed', 18, 2005, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jay Chou","avatar":""},{"name":"Anne Suzuki","avatar":""},{"name":"Jordan Chan","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Kenny Bee","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Edison Chen","avatar":""},{"name":"Tsuyoshi Abe","avatar":""},{"name":"Liu Geng-Hong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324527);
