INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-canh-sat-chim', 'Nữ Cảnh Sát Chìm', 'She''s On Duty', 'https://phimimg.com/upload/vod/20231002-1/6905f120dff940669a1856e1cd44e8be.jpg', 'https://phimimg.com/upload/vod/20231002-1/476f1463fb111fc3eb4fc66a21004283.jpg', '<p>Về phương diện kiến thức, Jae In đương nhiên không thể bằng những 
người khác, hơn nữa còn phải luôn bảo vệ bản thân không bị người khác 
nhìn thấu. Một nữ đầu gấu trong lớp tên Jo Hye Ryung (Hong Soo Ah thủ 
vai) cũng thấy ngứa mắt với Jae In và luôn tìm cách gây khó dễ. Do thân 
phận nằm vùng cản trở, Jae In không thể làm gì khác ngoài việc im hơi 
lặng tiếng. Điều khiến Jae In vui vẻ là cô có hảo cảm với một người tên 
No Young (Gong Yoo thủ vai). Nhưng nghĩ đến thân phận thật và tuổi tác 
của mình, Jae In lại cảm thấy vô cùng rầu rĩ. Vất vả lắm hành động mới 
có tiến triển, đối tượng điều tra bắt đầu tin tưởng Jae In, cô cũng có 
được đầu mối quan trọng, vậy nhưng giữa chừng lại xuất hiện biến số...</p>', 'Full', 1, 'single', 'completed', 18, 2005, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Sun-a","avatar":""},{"name":"Gong Yoo","avatar":""},{"name":"Nam Sang-mi","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Noh Joo-hyun","avatar":""},{"name":"Hong Soo-ah","avatar":""},{"name":"Oh Gwang-rok","avatar":""},{"name":"Moon Seo-yeon","avatar":""},{"name":"Park Sang-myeon","avatar":""},{"name":"Kim Kap-soo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324527);
