INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-canh-sat-chim', 'Nữ Cảnh Sát Chìm', 'She''s On Duty', 'nữ cảnh sát chìm she''s on duty kim sun-a gong yoo nam sang-mi kim sang-ho noh joo-hyun hong soo-ah oh gwang-rok moon seo-yeon park sang-myeon kim kap-soo ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-vua-va-chu-he', 'Nhà Vua Và Chú Hề', 'King and the Clown', 'https://phimimg.com/upload/vod/20231002-1/f8258699a5c08b0a617c96b54bc83273.jpg', 'https://phimimg.com/upload/vod/20231002-1/3dd5582f8ad33a5a21c9458640349cbe.jpg', '<p><span class="key"></span>Phim kể về một gánh hát đường phố, nay 
đây mai đó và chuyên diễn kịch chế nhạo sự thối nát của nhà vua, phi 
tần, hoàng cung,… Rồi một ngày họ vô tình bị đẩy vào hoàng cung để mua 
vui cho nhà vua xem. Thích thú trước những trò diễn hề, gánh hát được 
giữ lại. Những tưởng sẽ có một cuộc sống no đủ ấm áp, gánh hát ấy không 
hề biết rằng chốn thâm cung là nơi có nhiều dã tâm nhất.</p>', 'Full', 1, 'single', 'completed', 17, 2005, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kam Woo-sung","avatar":""},{"name":"Lee Joon-gi","avatar":""},{"name":"Jung Jin-young","avatar":""},{"name":"Kang Sung-yeon","avatar":""},{"name":"Yoo Hae-jin","avatar":""},{"name":"Hang-Seon Jang","avatar":""},{"name":"Jeong Seok-yong","avatar":""},{"name":"Lee Seung-hun","avatar":""},{"name":"Yoon Joo-sang","avatar":""},{"name":"Choi Il-hwa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324527);
