INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-bo-gap-me-phan-1', 'Khi Bố Gặp Mẹ (Phần 1)', 'How I Met Your Mother (Season 1)', 'https://phimimg.com/upload/vod/20231001-1/2080c93b6e1452ee5ad80af2f4413172.jpg', 'https://phimimg.com/upload/vod/20231001-1/a02f3434b190f5eeff594ab79bd69408.jpg', '<p>Ted Mosby, một kiến trúc sư, kể lại cho các con của mình nghe những sự kiện đã dẫn anh đến gặp mẹ của chúng. Cuộc hành trình của anh ấy trở nên sôi động hơn khi có sự hiện diện của những người bạn Lily, Marshall, Robin và Barney.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 22, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Radnor","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Jason Segel","avatar":""},{"name":"Alyson Hannigan","avatar":""},{"name":"Cobie Smulders","avatar":""},{"name":"Cristin Milioti","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324527);
