INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-chien-o-lang-dongmakgol', 'Tử Chiến Ở Làng Dongmakgol', 'Welcome to Dongmakgol', 'https://phimimg.com/upload/vod/20230930-1/4861bf71f2668078fb272967e028b661.jpg', 'https://phimimg.com/upload/vod/20230930-1/88aeb202d1576845b42b364061ccb892.jpg', '<p>Tháng 9 năm 1950 là lúc mà các cuộc chiến tranh đang đến hồi gay cấn nhất ở Hàn Quốc. Lực lượng Đồng minh tiếp tục đổ bộ xuống In Cheon và tiến hành nhiều đợt rải bom bừa bãi nhằm diệt sạch lực lượng Quân đội nhân dân ở khắp nơi. Trong khi đó, cuộc nội chiến giữa Quân đội miền Nam chống Quân đội miền Bắc vẫn còn chưa ngã ngũ. Tình thế lúc này vô cùng hỗn loạn. Giữa bom đạn khốc liệt như thế, sáu người lính đến từ những chiến tuyến đối lập nhau lại vô tình gặp nhau tại một ngôi làng rất đặc biệt, làng Dong mak gol, nơi không hề tồn tại một dấu vết nào của chiến tranh. Một là đại úy Hải quân Mỹ, hai chàng thuộc Quân đội miền Nam, và ba người còn lại là quân nhân Quân đội miền Bắc. Tại ngôi làng đó, những người lính trẻ đã được học những bài học vô cùng quý báu về cuộc sống mà suýt nữa họ đã bỏ lỡ...</p>', 'Full', 1, 'single', 'completed', 24, 2005, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[]', '[]', 1784690324527);
