INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tinh', 'Bạn Tình', 'Lie with Me', 'https://phimimg.com/upload/vod/20230926-1/5bba3ffb28f5524cede28de307661603.jpg', 'https://phimimg.com/upload/vod/20230926-1/7ab0b2b829fd8d4f019eac01d62e9490.jpg', '<p>Hạnh phúc khi không bị ràng buộc, Leila phàm ăn tình dục thỏa mãn ham muốn của mình với một loạt bạn tình trên giường thay đổi nhanh chóng, không quan tâm đến hậu quả về mặt tình cảm. Nhưng tất cả thay đổi khi cô gặp một nghệ sĩ đang tìm kiếm sự cam kết sâu sắc hơn.</p>', 'Full', 1, 'single', 'completed', 20, 2005, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Lauren Lee Smith","avatar":""},{"name":"Eric Balfour","avatar":""},{"name":"Polly Shannon","avatar":""},{"name":"Mayko Nguyen","avatar":""},{"name":"Michael Facciolo","avatar":""},{"name":"Kate Lynch","avatar":""},{"name":"Ron White","avatar":""},{"name":"Kristin Lehman","avatar":""},{"name":"Don Francks","avatar":""},{"name":"Richard Chevolleau","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324527);
