INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-pha-roi-hon-le', 'Những Kẻ Phá Rối Hôn Lễ', 'Wedding Crashers', 'https://phimimg.com/upload/vod/20230919-1/0900be6425f31a63f104e22bbb3ad51f.jpg', 'https://phimimg.com/upload/vod/20230919-1/827bc939dab336ef37a3d634572ca87c.jpg', '<p>John và bạn của anh ta, Jeremy là những tên tội phạm tình cảm, biết cách lợi dụng hy vọng và ước mơ của phụ nữ để trục lợi xác thịt. Phương thức hoạt động của họ: đám cưới đổ vỡ. Thông thường, họ gặp những vị khách muốn chúc mừng ngày lãng mạn bằng một cuộc hẹn hò ngẫu nhiên. Nhưng khi John gặp Claire, anh khám phá ra tình yêu đích thực – và nỗi đau lòng – là như thế nào.</p>', 'Full', 1, 'single', 'completed', 24, 2005, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Jane Seymour","avatar":""},{"name":"Ellen Albertini Dow","avatar":""},{"name":"Keir O''Donnell","avatar":""},{"name":"Bradley Cooper","avatar":""},{"name":"Ron Canada","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324527);
