INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('50-lan-hen-dau-tien', '50 Lần Hẹn Đầu Tiên', '50 First Dates', 'https://phimimg.com/uploads/movies/20260710/50-lan-hen-dau-tien-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/50-lan-hen-dau-tien-poster.webp', '<p>Lucy là một cô gái bị mất trí nhớ sau một tai nạn thảm khốc, sau khi ngủ dậy cô lại quên tất cả mọi thứ xảy ra ngày hôm qua. Henny là một bác sĩ thú y làm trong một công viên thủy sinh tại Hawaii, anh đã đem lòng yêu Lucy và tìm mọi cách để cô nhớ lại mọi thứ. Từ đây bắt đầu những tình tiết dở khóc dở cười xảy ra.</p>', 'Full', 1, 'single', 'completed', 41, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"Rob Schneider","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Lusia Strus","avatar":""},{"name":"Dan Aykroyd","avatar":""},{"name":"Amy Hill","avatar":""},{"name":"Allen Covert","avatar":""},{"name":"Blake Clark","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Pomaika''i Brown","avatar":""},{"name":"Joe Nakashima","avatar":""},{"name":"Peter Dante","avatar":""},{"name":"Dom Magwili","avatar":""},{"name":"Jonathan Loughran","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Como si fuera la primera vez","Como si Fuera la Primera Vez","Cheotkisuman 50baenjjae","Mereu la prima întâlnire","50 pŭrvi sreshti","Káthe Forá, Próti Forá","50 pervykh potseluyev","Pedeset prvih sastanaka","50 pershykh potsilunkiv","50 krát a stále po prvý raz","50 เดท จีบเธอไม่เคยจำ","50回目のファースト・キス","Como Si Fuera la Primera Vez","50x a stále poprvé","첫키스만 50번째","50 առաջին ժամադրությունները","50 volt