INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-than-tinh-yeu-than-ai-tinh', 'Nữ Thần Tình Yêu (Thần Ái Tình)', 'Eros', 'https://phimimg.com/uploads/movies/20260710/nu-than-tinh-yeu-than-ai-tinh-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/nu-than-tinh-yeu-than-ai-tinh-poster.webp', '<p>Ba phim ngắn, của các đạo diễn Michelangelo Antonioni, Steven Soderbergh và Wong Kar Wai, đề cập đến các chủ đề về tình yêu và tình dục.</p>', 'Full', 1, 'single', 'completed', 58, 2004, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Gong Li","avatar":""},{"name":"Chang Chen","avatar":""},{"name":"Tien Feng","avatar":""},{"name":"Robert Downey Jr.","avatar":""},{"name":"Alan Arkin","avatar":""},{"name":"Ele Keats","avatar":""},{"name":"Christopher Buchholz","avatar":""},{"name":"Regina Nemni","avatar":""},{"name":"Luisa Ranieri","avatar":""},{"name":"Chan Chun-Luk","avatar":""},{"name":"Cecilia Luci","avatar":""},{"name":"Riccardo Manfredi","avatar":""},{"name":"Valerio Burroni","avatar":""},{"name":"Pelino Tarantelli","avatar":""},{"name":"Chow Kin-Kwan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Eros: The Hand","Eros: Equilibrium","Eros: The Dangerous Thread of Things","에로스 더 핸드","그녀의 손길","Eros"]', 1784690324527);
