INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dep-noi-doi', 'Người Đẹp Nói Dối', 'Too Beautiful to Lie', 'https://phimimg.com/upload/vod/20260608-1/c8c9282f6d655ad084e0f130914e9253.jpg', 'https://phimimg.com/upload/vod/20260608-1/90f48d47383378a35147165ca4bbf8f2.jpg', '<p>Cô tù nhân xinh đẹp vừa được trở về với cuộc sống tự do lại rơi vào một rắc rối - cô phải tìm chủ nhân của chiếc nhẫn kim cương quý giá để đánh đổi lại món quà cưới cho người chị gái. Sự cố nối tiếp sự cố, cô trở thành con dâu tương lai bất đắc dĩ của ông thị trưởng. Ju Young Ju (Kim Ha Nul) – nữ phạm nhân xinh đẹp vừa được mãn hạn tù do có thời gian cải tạo tích cực trong trại giam và những xảo thuật tinh quái. Cô hào hứng chuẩn bị cho đám cưới của người chị gái sau khi bước ra khỏi song sắt nhà tù với món quà cưới là đôi ngỗng bằng gỗ do chính tay cô tự làm.</p>', 'Full', 1, 'single', 'completed', 24, 2004, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Ha-neul","avatar":""},{"name":"Gang Dong-won","avatar":""},{"name":"Lee Chun-hee","avatar":""},{"name":"Song Jae-ho","avatar":""},{"name":"Myeong Ji-yeon","avatar":""},{"name":"Kim Jae-rok","avatar":""},{"name":"Im Ha-ryong","avatar":""},{"name":"Lee Jae-gu","avatar":""},{"name":"Park Gun-tae","avatar":""},{"name":"Nam Sang-mi","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Park Jin-young","avatar":""},{"name":"Lee Young-eun","avatar":""},{"name":"Jin Kyung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Don''t Believe in Her","그녀를 믿지 마세요","Don''t Believe Her","Too Beautiful To Lie","Geunyeoreul midji maseyo"]', 1784690324527);
