INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-smallville-phan-4', 'Thị Trấn Smallville (Phần 4)', 'Smallville (Season 4)', 'https://phimimg.com/upload/vod/20250604-1/9460e90a203d56592766d3adeb387e59.jpg', 'https://phimimg.com/upload/vod/20250604-1/f97b143cff5c12102fbbd5c41fae02ae.jpg', '<p>Năm cuối trung học của Clark Kent sẽ có rất nhiều điều đáng nhớ! Lois Lane — thông minh, thẳng thắn và hoàn toàn khiến Clark phát bực — đến Smallville để điều tra cái chết của người em họ. Lana có bạn trai mới lớn tuổi hơn. Clark quyết định đi ngược lại mong muốn của cha mẹ và gia nhập đội bóng bầu dục với vị trí tiền vệ. Trong khi Clark bắt đầu hành trình tìm kiếm ba viên pha lê Krypton bí ẩn, Lex lại dấn sâu hơn vào con đường tăm tối.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 18, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Welling","avatar":""},{"name":"Erica Durance","avatar":""},{"name":"Cassidy Freeman","avatar":""},{"name":"Justin Hartley","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Smallville"]', 1784690324527);
