INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-dat-khong-lo-4-huyen-thoai-bat-dau', 'Sâu Đất Khổng Lồ 4: Huyền Thoại Bắt Đầu', 'Tremors 4: The Legend Begins', 'https://phimimg.com/upload/vod/20260525-1/fefd92e29b56ec29502204cb440a68e8.jpg', 'https://phimimg.com/upload/vod/20260525-1/b4d8d36d6ec49d086d0081ba923abc63.jpg', '<p>Vào năm 1889, mười bảy người đàn ông đã bỏ mạng một cách đầy bí ẩn. Quá sợ hãi trước những sự kiện kỳ quái liên tiếp xảy ra gần đây, những người thợ mỏ đang sinh sống tại thị trấn đã lũ lượt kéo nhau bỏ xứ mà đi, cho đến khi nơi đây chẳng còn lại gì ngoài cái vỏ rỗng tuếch của một cộng đồng từng một thời tấp nập.</p>', 'Full', 1, 'single', 'completed', 48, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Gross","avatar":""},{"name":"Sara Botsford","avatar":""},{"name":"Billy Drago","avatar":""},{"name":"Brent Roam","avatar":""},{"name":"August Schellenberg","avatar":""},{"name":"J.E. Freeman","avatar":""},{"name":"Ming Lo","avatar":""},{"name":"Lydia Look","avatar":""},{"name":"Sam Ly","avatar":""},{"name":"Neil Kopit","avatar":""},{"name":"Sean Moran","avatar":""},{"name":"Matthew Seth Wilson","avatar":""},{"name":"John Dixon","avatar":""},{"name":"Dan Lemieux","avatar":""},{"name":"Don Ruffin","avatar":""},{"name":"Lou Carlucci","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Tremors IV- The Legend Begins","Tremors 4 - Agli inizi della leggenda","Terror Bajo Tierra 4 Comienza la Leyenda","O Ataque dos Vermes Malditos 4: O Começo da Lenda","Tremors 4. - A legenda elkezdődik","불가사리 4","Tremors IV The Legend Begins","Wstrząsy 4: Początek legendy","Tremors 4 The Legend Begins","深淵異形4","Yeraltı Canavarı 4: Efsane Başlıyor","Tremors 4: The Legend Begins"]', 1784690324527);
