INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sau-dat-khong-lo-4-huyen-thoai-bat-dau', 'Sâu Đất Khổng Lồ 4: Huyền Thoại Bắt Đầu', 'Tremors 4: The Legend Begins', 'sâu đất khổng lồ 4: huyền thoại bắt đầu tremors 4: the legend begins michael gross sara botsford billy drago brent roam august schellenberg j.e. freeman ming lo lydia look sam ly neil kopit sean moran matthew seth wilson john dixon dan lemieux don ruffin lou carlucci tremors iv- the legend begins tremors 4 - agli inizi della leggenda terror bajo tierra 4 comienza la leyenda o ataque dos vermes malditos 4: o começo da lenda tremors 4. - a legenda elkezdődik 불가사리 4 tremors iv the legend begins wstrząsy 4: początek legendy tremors 4 the legend begins 深淵異形4 yeraltı canavarı 4: efsane başlıyor tremors 4: the legend begins', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trai-toi-va-toi-ii-dot-chay-hoa-cuc', 'Anh Trai Tôi Và Tôi II: Đốt Cháy Hoa Cúc', 'Aniki To Ore 2: Moeru Kikumon', 'https://phimimg.com/upload/vod/20260518-1/bdd6807b5088bedcf343df169d9e6752.jpg', 'https://phimimg.com/upload/vod/20260518-1/e00136f9d004298df80f79c078290936.jpg', '<p>Phần thứ hai trong loạt phim đồng tính Anh trai tôi và tôi. Kotaro, một học sinh trung học, có một người anh trai kế sau khi chị gái cậu kết hôn. Tuy nhiên, người anh trai kế đó hóa ra lại là Ryoichi, giáo viên thể dục chủ nhiệm của cậu, người mà Kotaro thầm thương trộm nhớ. Kotaro biết được từ Kasama, bạn của Ryoichi, rằng hai người từng là bạn tình thời đại học.</p>', 'Full', 1, 'single', 'completed', 20, 2004, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryo Kuraki","avatar":""},{"name":"松浦祐也","avatar":""},{"name":"野上正義","avatar":""},{"name":"なかみつせいじ","avatar":""},{"name":"林由美香","avatar":""},{"name":"Mikihiro Hyôdo","avatar":""},{"name":"Masanobu Matsuda","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["兄貴と俺Ⅱ／燃える菊紋","兄貴と俺Ⅱ 燃える菊紋"]', 1784690324527);
