INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-cung-tinh-yeu', 'Mê Cung Tình Yêu', 'Labyrinth Of Love', 'https://phimimg.com/upload/vod/20260513-1/3549f5f309dd058e3229e9a74ca285ca.jpg', 'https://phimimg.com/upload/vod/20260513-1/15836320d12d10d0ad79d632c0604258.jpg', '<p>Yusuke 25 tuổi và sống với cha. Ông đã chăm sóc cha mình từ khi cha cậu mất mẹ lúc còn nhỏ. Yusuke đã có quan hệ với Shinozaki, một nhiếp ảnh gia đồng tính nổi tiếng, với vai trò là nhà tạo mẫu, người mẫu và người yêu trong khoảng một năm trở lại đây. Số tiền cậu nhận được từ Shinozaki rất lớn, và bản thân cậu cũng không biết liệu đây là tình yêu hay chỉ là mối quan hệ được trả tiền. Cậu cũng có quan hệ tình dục không ràng buộc với chủ quán bar đồng tính nơi cậu làm việc bán thời gian. Một ngày nọ, Yusuke biết được cha mình đang có kế hoạch tái hôn, và người phụ nữ đó đến quán bar đồng tính nơi cậu làm việc bán thời gian.</p>', 'Full', 1, 'single', 'completed', 18, 2004, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kento Mori","avatar":""},{"name":"Kôji Makimura","avatar":""},{"name":"Wataru Tsunashima","avatar":""},{"name":"本多菊次朗","avatar":""},{"name":"横須賀正一","avatar":""},{"name":"池島ゆたか","avatar":""},{"name":"Kôran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ai no labyrinth","愛のラビリンス"]', 1784690324527);
