INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-dong-truc-tiep', 'Hành Động Trực Tiếp', 'Direct Action', 'https://phimimg.com/upload/vod/20260511-1/85626ba1f4f6b4afefd2145a16398e0f.jpg', 'https://phimimg.com/upload/vod/20260511-1/200350781e1967ed3e8c80cd477c8d67.jpg', '<p>Frank Gannon, một cảnh sát kỳ cựu, đang bị các đồng nghiệp truy đuổi sau khi họ phát hiện ra anh ta đã phản bội tình anh em và vạch trần cho cơ quan liên bang về nạn tham nhũng quy mô lớn trong Sở Cảnh sát Los Angeles (LAPD). Anh ta chỉ còn một ngày để chứng minh sự vô tội của mình và sống sót.</p>', 'Full', 1, 'single', 'completed', 22, 2004, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Polly Shannon","avatar":""},{"name":"Donald Burda","avatar":""},{"name":"Rothaford Gray","avatar":""},{"name":"Conrad Dunn","avatar":""},{"name":"Walter Alza","avatar":""},{"name":"Alex Karzis","avatar":""},{"name":"Larry Day","avatar":""},{"name":"Natacha La Ferriere","avatar":""},{"name":"Daniel Kash","avatar":""},{"name":"Stacey Coke","avatar":""},{"name":"Joseph Griffin","avatar":""},{"name":"Vanessa Thompson","avatar":""},{"name":"Anthony J. Mifsud","avatar":""},{"name":"Tim Sell","avatar":""},{"name":"Jim Codrington","avatar":""},{"name":"Ian Alden","avatar":""},{"name":"Dan Wil","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Corrupción al límite","非法基地","Direct Action"]', 1784690324527);
