INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hanh-dong-truc-tiep', 'Hành Động Trực Tiếp', 'Direct Action', 'hành động trực tiếp direct action dolph lundgren polly shannon donald burda rothaford gray conrad dunn walter alza alex karzis larry day natacha la ferriere daniel kash stacey coke joseph griffin vanessa thompson anthony j. mifsud tim sell jim codrington ian alden dan wil corrupción al límite 非法基地 direct action', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-le-dieu-do-that-dang-buon', 'Có Lẽ điều đó Thật đáng Buồn', 'Maybe It''s Sad', 'https://phimimg.com/upload/vod/20260511-1/76ea037ad43652e67fe5580b50a525da.jpg', 'https://phimimg.com/upload/vod/20260511-1/ea05624b633955833fb8270cc2f1861b.jpg', '<p>Sau khi tốt nghiệp đại học, Satoshi Takagi gia nhập công ty quảng cáo mà anh luôn mơ ước và bắt đầu cuộc sống công việc với đầy nhiệt huyết. Satoshi có một người bạn trai, hơn cả bạn nhưng chưa phải người yêu, nhưng ngay cả khi cô ấy cố gắng nói chuyện với anh về công ty, anh ta chỉ muốn thân xác của Satoshi và hoàn toàn không chịu lắng nghe. Tôi có quyền gì mà chỉ muốn thân xác? Khoảng cách giữa anh ta và Satoshi đã nới rộng ra một chút. Mặc dù vậy, Satoshi vẫn cố gắng hết sức trong công việc. Anh thực sự bắt đầu có cảm tình với sếp của mình, Furukawa. Tuy nhiên, Furukawa là một người đàn ông thẳng thắn và đang hẹn hò với đồng nghiệp của Satoshi, một nữ nhân viên văn phòng. Mặc dù đó là một giấc mơ không thể thành hiện thực, nhưng tình cảm của tôi dành cho Furukawa, người làm việc một cách điềm tĩnh, ngày càng mạnh mẽ hơn.</p>', 'Full', 1, 'single', 'completed', 22, 2004, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Naoyuki Chiba","avatar":""},{"name":"Tomohiro Okada","avatar":""},{"name":"Fumihito Hirakawa","avatar":""},{"name":"野村貴浩","avatar":""},{"name":"林由美香","avatar":""},{"name":"なかみつせいじ","avatar":""},{"name":"鈴木敦子","avatar":""},{"name":"Kaoru Akitsu","avatar":""},{"name":"Rio Mochizuki","avatar":""},{"name":"白石雅彦","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Setsunaikamo shirenai","Just When I Need You Most","せつないかもしれない"]', 1784690324527);
