INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('godzilla-tran-chien-cuoi-cung', 'Godzilla: Trận chiến cuối cùng', 'Godzilla: Final Wars', 'https://phimimg.com/upload/vod/20260420-1/5e8bac863c954dca20aeab8a2641e2b3.jpg', 'https://phimimg.com/upload/vod/20260420-1/9d05f830d9ebd8edce49267b7c44f882.jpg', '<p>Dự án kỷ niệm 50 năm Godzilla, trong đó Gojira (Godzilla) du hành khắp thế giới để chiến đấu với những kẻ thù cũ của mình cùng một con quái vật bí ẩn mới có tên là Monster X.</p>', 'Full', 1, 'single', 'completed', 22, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Masahiro Matsuoka","avatar":""},{"name":"Rei Kikukawa","avatar":""},{"name":"Don Frye","avatar":""},{"name":"Maki Mizuno","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Kane Kosugi","avatar":""},{"name":"Kumi Mizuno","avatar":""},{"name":"Akira Takarada","avatar":""},{"name":"Masatô Ibu","avatar":""},{"name":"Masanobu Takashima","avatar":""},{"name":"Shigeru Izumiya","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Chihiro Ohtsuka","avatar":""},{"name":"Masami Nagasawa","avatar":""},{"name":"Masakatsu Funaki","avatar":""},{"name":"Kenji Sahara","avatar":""},{"name":"Kenta Suga","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Godzilla - Final Wars","Godzilla 28 - Godzilla: Final Wars","ゴジラ FINAL WARS","Gojira: Fainaru uôzu","고질라 - 파이널 워즈","Ґодзілла: Final wars","ゴジラ ファイナルウォーズ"]', 1784690324527);
