INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-duoi-thap-co', 'Cuộc Chiến Dưới Tháp Cổ', 'AVP: Alien vs. Predator', 'https://phimimg.com/upload/vod/20260320-1/a4faa824b908a3f27f69a5551d396280.jpg', 'https://phimimg.com/upload/vod/20260320-1/6a58e44ac508354c78faf9b6ea80f5b1.jpg', '<p>AVP: Alien VS Predator (Cuộc Chiến Dưới Tháp Cổ) là bộ phim hành động, khoa học viễn tưởng xoay quanh hai con quái vật đến từ hai hành tinh khác nhau chiến đấu trên trái đất vào những ngày đầu còn sơ khai. Cùng lúc đó là sự khám phá của 1 nhóm nghiên cứu về những toà kim tự tháp bị chôn vùi dẫn dắt đoàn thám hiểm về thời kỳ băng hà của Trái Đất. Và hai con quái vật đánh nhau đến long trời lở đất. Ai thắng? Ai thua? Tuy nhiên, những người bị thiệt hại nhiều nhất có lẽ là những nhà thám hiểm...</p>', 'Full', 1, 'single', 'completed', 23, 2004, 'Vietsub', 'FHD', 'Séc', 0, '[{"name":"Sanaa Lathan","avatar":""},{"name":"Lance Henriksen","avatar":""},{"name":"Ian Whyte","avatar":""},{"name":"Raoul Bova","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"Colin Salmon","avatar":""},{"name":"Tommy Flanagan","avatar":""},{"name":"Joseph Rye","avatar":""},{"name":"Agathe de La Boulaye","avatar":""},{"name":"Carsten Nørgaard","avatar":""},{"name":"Sam Troughton","avatar":""},{"name":"Petr Jákl","avatar":""},{"name":"Pavel Bezděk","avatar":""},{"name":"Kieran Bew","avatar":""},{"name":"Carsten Voigt","avatar":""},{"name":"Jan Filipenský","avatar":""},{"name":"Adrian Bouchet","avatar":""},{"name":"Andy L","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["异形战场","異形戰場","Alien vs. depredador","Bigane Alayhe Predator","Tudin protiv predatora","Alien vs Depredador","Prishŭletsŭt sreshtu khishtnikŭt","Álien Enantíon Kynigoú","Chuzhoy protiv Khishchnika","Chuzhyy proty Khyzhaka","AVP 1։ Alien vs. Predator","הטורף נגד הנוסע השמיני","Alien vs Predator - A Halál a Ragadozó ellen","Cuộc Chiến Dưới Tháp Cổ","異獸戰","Alien vs Predator","에이리언 VS 프레데터","에이리언 vs. 프레데터","Alien vs. Predador","Vetřelci vs. Predátor","AVP: Alien vs. Predator"]', 1784690324527);
