INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zebraman', 'Zebraman', 'Zebraman', 'https://phimimg.com/upload/vod/20260218-1/336e160dd97773bd1dcc8789e58c8e07.jpg', 'https://phimimg.com/upload/vod/20260218-1/527a849571d416836328bd722b4c60a8.jpg', '<p>Một thầy giáo tiểu học thất thế, luôn cảm thấy lạc lõng với cuộc đời, bất ngờ nhận được &#39;tiếng gọi&#39; để trở thành hiện thân ngoài đời thực của một siêu anh hùng trong chương trình truyền hình cũ từ những năm 1970 — Zebraman.</p>', 'Full', 1, 'single', 'completed', 22, 2004, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Show Aikawa","avatar":""},{"name":"Kyoka Suzuki","avatar":""},{"name":"Atsuro Watabe","avatar":""},{"name":"Yui Ichikawa","avatar":""},{"name":"Koen Kondo","avatar":""},{"name":"Ren Osugi","avatar":""},{"name":"Makiko Watanabe","avatar":""},{"name":"Kumiko Aso","avatar":""},{"name":"Ryo Iwamatsu","avatar":""},{"name":"Teruyoshi Uchimura","avatar":""},{"name":"Akira Emoto","avatar":""},{"name":"Yoji Tanaka","avatar":""},{"name":"Arata Furuta","avatar":""},{"name":"Yuu Tokui","avatar":""},{"name":"Daisuke Iijima","avatar":""},{"name":"Miyako Kawahara","avatar":""},{"name":"Yūta Sone","avatar":""},{"name":"Tokitoshi Shiota","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ゼブラーマン"]', 1784690324527);
