INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-banh-ngot-ngao', 'Chiếc Bánh Ngọt Ngào', 'Sweet Buns', 'https://phimimg.com/upload/vod/20260124-1/0678b2b780a4304443a5d216a76a17df.jpg', 'https://phimimg.com/upload/vod/20260124-1/fb055d62d534fdd7bc1e2e4b548d1a2f.jpg', '<p>Garan là một cô giáo tiểu học hồn nhiên, còn Nam-jun là một luật sư trẻ vừa trở về quê nhà. Cả hai vốn là &quot;oan gia&quot; từ thời thơ ấu, gắn liền với kỷ niệm tranh giành chiếc bánh mì đậu đỏ khiến họ ghét nhau ra mặt.&nbsp; Định mệnh khiến họ liên tục chạm trán trong những tình huống dở khóc dở cười tại quê nhà. Từ những cuộc cãi vã &quot;gầm gừ&quot; không hồi kết, những ký ức tuổi thơ dần ùa về, khiến mối quan hệ giữa &quot;cô nàng trẻ con&quot; và &quot;anh chàng chủ nợ&quot; dần chuyển hóa thành một tình yêu nhẹ nhàng và ấm áp.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 22, 2004, 'Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Kang-hee","avatar":""},{"name":"Kim Nam-gil","avatar":""},{"name":"Jeong So-yeong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["단팥빵"]', 1784690324527);
