INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-ray-charles', 'Huyền Thoại Ray Charles', 'Ray', 'https://phimimg.com/upload/vod/20260123-1/e1434aafedace3011a20b497cdfe57fb.jpg', 'https://phimimg.com/upload/vod/20260123-1/ad075308a3e61819de23f9bab075efe3.jpg', '<p>Sinh ra và lớn lên trong cảnh bần hàn ở vùng nông thôn Florida, Mỹ, cậu bé da đen bất hạnh Ray Charles (Jamie Fox) không còn nhìn thấy ánh sáng từ khi lên 7 tuổi, sau khi chứng kiến cảnh cậu em bé bỏng bị chết chìm trong bồn tắm. Sự kiện này ám ảnh Ray trong suốt cuộc đời. Không cam chịu số phận mù lòa, cậu đã kiên trì tự học nhạc với sự giúp đỡ tận tụy của người mẹ góa Aretha. Ray được mọi người công nhận là một thiên tài âm nhạc. Trên con đường chinh phục đỉnh vinh quang, Ray Charles đã phấn đấu không mệt mỏi, trải qua sự cảm dỗ nghiện ngập và ma túy. Cái giá của sự nổi tiếng còn đẩy ông vào những mối quan hệ rắc rối, luôn phải đấu tranh và toan tính. Cùng đó là sự đổ vỡ trong cuộc sống gia đình, sự kỳ thị chủng tộc…</p>', 'Full', 1, 'single', 'completed', 18, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jamie Foxx","avatar":""},{"name":"Kerry Washington","avatar":""},{"name":"Regina King","avatar":""},{"name":"Harry Lennix","avatar":""},{"name":"Clifton Powell","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Sharon Warren","avatar":""},{"name":"C.J. Sanders","avatar":""},{"name":"Curtis Armstrong","avatar":""},{"name":"Richard Schiff","avatar":""},{"name":"Larenz Tate","avatar":""},{"name":"Terrence Howard","avatar":""},{"name":"David Krumholtz","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"Aunjanue Ellis-Taylor","avatar":""},{"name":"Chris Thomas Kin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Unchain My Heart: The Ray Charles Story","Ռեյ","Ray"]', 1784690324527);
