INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyen-thoai-ray-charles', 'Huyền Thoại Ray Charles', 'Ray', 'huyền thoại ray charles ray jamie foxx kerry washington regina king harry lennix clifton powell bokeem woodbine sharon warren c.j. sanders curtis armstrong richard schiff larenz tate terrence howard david krumholtz wendell pierce aunjanue ellis-taylor chris thomas kin unchain my heart: the ray charles story ռեյ ray', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-khi-co-polly', 'Từ Khi Có Polly', 'Along Came Polly', 'https://phimimg.com/upload/vod/20260122-1/2d18a97c9f780613679ff7d36ed93dc7.jpg', 'https://phimimg.com/upload/vod/20260122-1/104e35423127ee8d1afeeb284af00d83.jpg', '<p>Reuben Feffer (Ben Stiller) không thích mạo hiểm, nhưng cuộc sống có trật tự và có kế hoạch của anh ta rất phức tạp khi trong tuần trăng mật, vợ anh ta (Debra Messing) bắt đầu quan tâm đến một người hướng dẫn lặn Cuba cơ bắp (Hank Azaria). Cùng lúc đó, Polly (Jennifer Aniston), một người bạn thời thơ ấu của anh, bước vào sân khấu, giới thiệu cho anh những môn thể thao mạo hiểm, thức ăn cay và nhảy salsa. Nói tóm lại, cô dạy anh sống vô tư và tận hưởng từng khoảnh khắc.</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Debra Messing","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Hank Azaria","avatar":""},{"name":"Bryan Brown","avatar":""},{"name":"Jsu Garcia","avatar":""},{"name":"Michele Lee","avatar":""},{"name":"Bob Dishy","avatar":""},{"name":"Missi Pyle","avatar":""},{"name":"Judah Friedlander","avatar":""},{"name":"Kevin Hart","avatar":""},{"name":"Masi Oka","avatar":""},{"name":"Kym Whitley","avatar":""},{"name":"Amy Hohn","avatar":""},{"name":"Nathan Dean","avatar":""},{"name":"Cheryl Hines","avatar":""},{"name":"Caroli","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["I onda je naišla Poli","A osʹ i Polli","Zavrŭshtaneto na Poli","Otan Gnórisa tin Póly","A vot i Polli","Und dann kam Polly","Along Came Polly"]', 1784690324527);
