INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tu-khi-co-polly', 'Từ Khi Có Polly', 'Along Came Polly', 'từ khi có polly along came polly ben stiller jennifer aniston philip seymour hoffman debra messing alec baldwin hank azaria bryan brown jsu garcia michele lee bob dishy missi pyle judah friedlander kevin hart masi oka kym whitley amy hohn nathan dean cheryl hines caroli i onda je naišla poli a osʹ i polli zavrŭshtaneto na poli otan gnórisa tin póly a vot i polli und dann kam polly along came polly', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-diep-vien-2-quyen-luc-cua-bourne', 'Siêu Điệp Viên 2: Quyền Lực Của Bourne', 'The Bourne Supremacy', 'https://phimimg.com/upload/vod/20260116-1/3ff780e90fe9a60b47536e5bae181ef4.jpg', 'https://phimimg.com/upload/vod/20260116-1/076c1de48a1ee724c0e1a93453d8355f.jpg', '<p>2 năm đã trôi qua kể từ ngày chương trình Treadstone đổ bể, Jason Bourne mai danh ẩn tích sống hạnh phúc cùng bạn gái xinh đẹp Marie. Anh chỉ mang máng nhớ mình là một điệp viên CIA. Thỉnh thoảng những hình ảnh kinh hoàng lại hiện về trong trí óc trong phim hay này nhưng Jason không thể hồi tưởng chi tiết cụ thể những gì đã diễn ra... Trên đường phố đông đúc, phát hiện bị theo dõi, một khuôn mặt làm Jason gợi nhớ về dự án Treadstone mà anh từng tham gia. Linh cảm nguy hiểm cận kề, anh cùng Marie tìm đường lẩn trốn. Không may trong cuộc truy sát, bạn gái anh đã vĩnh viễn ra đi, Jason thoát chết nhưng phải lặn biệt tăm. Nuốt nỗi đau vào lòng, tiêu hủy giấy tờ hình ảnh, bay về Châu Âu, anh quyết tâm đi tìm sự thật.</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Franka Potente","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Julia Stiles","avatar":""},{"name":"Karl Urban","avatar":""},{"name":"Gabriel Mann","avatar":""},{"name":"Joan Allen","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Tom Gallop","avatar":""},{"name":"John Bedford Lloyd","avatar":""},{"name":"Ethan Sandler","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Karel Roden","avatar":""},{"name":"Tomas Arana","avatar":""},{"name":"Oksana Akinshina","avatar":""},{"name":"Yevgeni Sitokhin","avatar":""},{"name":"Marina Weis","avatar":""},{"name":"Tim Grif","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La supremacía de Bourne","The Bourne Identity 2 - Bourne Supremacy","Jason Bourne 2 - La Mort dans la peau","A Supremacia Bourne","Bourne 2 - The Bourne Supremacy","Jason Bourne 2 - Bournův mýtus","Prevŭzkhodstvoto na Born","Sti skiá ton kataskópon","Prevoskhodstvo Borna","Bornova nadmoć","Perevaha Borna","谍影重重2：伯恩的霸权","Bourne Duellen","Bourne II: The Bourne Supremacy","谍影重重2.至尊伯恩","ボーン・スプレマシー：2004","叛諜追擊2 機密圈套","神鬼認證2：神鬼疑雲","Jason Bourne 2 - Die Bourne Verschwörung","Jason Bourne 2","谍影重重2","叛諜追擊2：機密圈套","سيادة بورن","The Bourne Supremacy"]', 1784690324527);
