INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-diep-vien-2-quyen-luc-cua-bourne', 'Siêu Điệp Viên 2: Quyền Lực Của Bourne', 'The Bourne Supremacy', 'siêu điệp viên 2: quyền lực của bourne the bourne supremacy matt damon franka potente brian cox julia stiles karl urban gabriel mann joan allen marton csokas tom gallop john bedford lloyd ethan sandler michelle monaghan karel roden tomas arana oksana akinshina yevgeni sitokhin marina weis tim grif la supremacía de bourne the bourne identity 2 - bourne supremacy jason bourne 2 - la mort dans la peau a supremacia bourne bourne 2 - the bourne supremacy jason bourne 2 - bournův mýtus prevŭzkhodstvoto na born sti skiá ton kataskópon prevoskhodstvo borna bornova nadmoć perevaha borna 谍影重重2：伯恩的霸权 bourne duellen bourne ii: the bourne supremacy 谍影重重2.至尊伯恩 ボーン・スプレマシー：2004 叛諜追擊2 機密圈套 神鬼認證2：神鬼疑雲 jason bourne 2 - die bourne verschwörung jason bourne 2 谍影重重2 叛諜追擊2：機密圈套 سيادة بورن the bourne supremacy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ca-map', 'Câu Chuyện Cá Mập', 'Shark Tale', 'https://phimimg.com/upload/vod/20260108-1/e84a24eb64ee42ce09cb9087b812d3a7.jpg', 'https://phimimg.com/upload/vod/20260108-1/bfb7594330399667c4765e8930fd4e52.jpg', '<p>Chú cá nhỏ Oscar làm dịch vụ chăm sóc cá voi, hay khoe khoang vô tình trở thành &quot;sát thủ cá mập&quot;. Với bản tính ba hoa, cậu thổi phồng sự việc giả vờ như mình là một anh hùng. Cũng vì vậy mà Oscar vướng vào rắc rối với Lenny, anh chàng cá mập chỉ thích ăn chay.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2004, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Renée Zellweger","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Ziggy Marley","avatar":""},{"name":"Martin Scorsese","avatar":""},{"name":"David P. Smith","avatar":""},{"name":"Doug E. Doug","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Vincent Pastore","avatar":""},{"name":"Peter Falk","avatar":""},{"name":"Katie Couric","avatar":""},{"name":"Phil LaMarr","avatar":""},{"name":"Shelley Morrison","avatar":""},{"name":"David Soren","avatar":""},{"name":"Bobb''e J.","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["鯊魚黑幫","El espanta tiburones","Priča o ajkulama","Istoriya s akuli","Karchariomáchos","Pidvodna bratva","Haaiensnaaier","Grosse Haie - Kleine Fische","Köpəkbalığı Hekayəsi","鯊膽大話王","鲨鱼故事","Shark Tale"]', 1784690324527);
