INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-ca-map', 'Câu Chuyện Cá Mập', 'Shark Tale', 'câu chuyện cá mập shark tale will smith robert de niro renée zellweger jack black angelina jolie ziggy marley martin scorsese david p. smith doug e. doug michael imperioli vincent pastore peter falk katie couric phil lamarr shelley morrison david soren bobb''e j. 鯊魚黑幫 el espanta tiburones priča o ajkulama istoriya s akuli karchariomáchos pidvodna bratva haaiensnaaier grosse haie - kleine fische köpəkbalığı hekayəsi 鯊膽大話王 鲨鱼故事 shark tale', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-cau-chuyen-canh-sat', 'Tân Câu Chuyện Cảnh Sát', 'New Police Story', 'https://phimimg.com/upload/vod/20251222-1/0b76c73d6dc46780eec9c4852f488356.jpg', 'https://phimimg.com/upload/vod/20251222-1/cff62c3d16cd1d2024c436d76e7131f8.jpg', '<p>Bị người cha là thanh tra trưởng ngược đãi từ nhỏ nên Joe mang trong lòng nỗi hận thù cao độ với cảnh sát. Hắn cùng một băng cướp năm người liên tục tấn công các ngân hàng. Và sau khi cướp xong, chúng cố ý nhấn chuông báo động dụ cảnh sát tới và nã súng vào họ xem như một trò vui. Trong một lần bắt tin nơi ẩn nấp của bọn cướp chúng, đội cảnh sát của thanh tra Wing gồm 9 người lọt bẫy và hi sinh, chỉ có anh thoát được. Cảm thấy có lỗi với đồng đội, Wing tìm kiếm sự an ủi trong men rượu. Phá được vô số vụ án lớn, Wing là một huyền thoại trong giới cảnh sát, được rất nhiều đàn em ngưỡng mộ, trong đó có Frank (Tạ Đình Phong). Tình cờ gặp thần tượng của mình say bí tỉ ngoài đường, Phong đưa Wing về nhà và giúp anh lấy lại sự tự tin. Hai người tạo thành một cặp ăn ý, cùng nhau họ quyết tâm tiêu diệt băng cướp vô cùng nguy hiểm của Joe.</p>', 'Full', 1, 'single', 'completed', 19, 2004, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Nicholas Tse Ting-Fung","avatar":""},{"name":"Charlie Yeung Choi-Nei","avatar":""},{"name":"Charlene Choi Chuek-Yin","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Andy On Chi-Kit","avatar":""},{"name":"Terence Yin Chi-Wai","avatar":""},{"name":"Hiro Hayama","avatar":""},{"name":"Coco Chiang Yi","avatar":""},{"name":"Dave Wong Kit","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Ken Lo Wai-Kwong","avatar":""},{"name":"Timmy Hung Tin-Ming","avatar":""},{"name":"Sammy Hung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["San ging chaat goo si","Nova policijska prica","Xin jing cha gu shi","Golpe de furia","Hong Kong Kokusai Keisatsu: New Police Story","Süper Polis 5","Police Story 4 - New Police Story","A Hora do Acerto","新警察故事"]', 1784690324527);
