INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-cong-ty-phu', 'Phi Công Tỷ Phú', 'The Aviator', 'https://phimimg.com/upload/vod/20251129-1/cb9360fa881773e5086b638b0eb1e3d4.jpg', 'https://phimimg.com/upload/vod/20251129-1/aa869350396407f7dc8dffdc7aa9cb87.jpg', '<p>Howard Hughes, một ông trùm lập dị với bộ óc thiên tài, mắc chứng bệnh tâm thần có nguy cơ hủy hoại sự nghiệp. Khi sự đấu tranh của anh ấy vượt quá giới hạn kiên trì của mình, anh ấy hồi tưởng về quá khứ.</p>', 'Full', 1, 'single', 'completed', 17, 2004, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Kate Beckinsale","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Alan Alda","avatar":""},{"name":"Ian Holm","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Gwen Stefani","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"Matt Ross","avatar":""},{"name":"Kelli Garner","avatar":""},{"name":"Frances Conroy","avatar":""},{"name":"Brent Spiner","avatar":""},{"name":"Stanley DeSantis","avatar":""},{"name":"Edward Herrmann","avatar":""},{"name":"Willem Dafoe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Aviatorŭt","Iptamenos kroisos","Авијатичар","Ավիատորը","神鬼玩家","The Aviator"]', 1784690324527);
