INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-ai-biet', 'Không Ai Biết', 'Nobody Knows', 'https://phimimg.com/upload/vod/20251124-1/fc2c25281b93a024e15e13aef89b6f1b.jpg', 'https://phimimg.com/upload/vod/20251124-1/bf554ca541bd758233d1a8f167f6a242.jpg', '<p>Bộ phim xoay quanh bốn đứa trẻ Akira (nam, 12 tuổi), Kyoko (nữ, 10 tuổi), Shigeru (nam, 7 tuổi) và Yuki (nữ, 5 tuổi). Chúng đều là anh chị em cùng mẹ khác cha. Mẹ chúng là Keiko, một phụ nữ trẻ ham vui và điệu đà, thường xuyên vắng nhà. Mọi việc trong nhà đều do Akira quán xuyến, với sự giúp đỡ của Kyoko. Ban đầu, thời gian vắng mặt của Keiko chỉ tính đến khuya trong ngày, nhưng sau đó là một tháng, rồi là mãi mãi. Cô ta nói dối là đi làm xa, nhưng Akira và Kyoko biết rằng mẹ đã bỏ nhà để sinh sống với bạn trai mới. Tiền bạc Keiko để lại cứ thế cạn dần, Akira vẫn chưa đủ tuổi lao động, những đứa trẻ dần lâm vào bế tắc sống còn. Chúng phải dựa vào những vòi nước ở công viên và sushi thừa ở cửa hàng tiện lợi gần đó để duy trì cuộc sống...</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuya Yagira","avatar":""},{"name":"Ayu Kitaura","avatar":""},{"name":"Hiei Kimura","avatar":""},{"name":"Momoko Shimizu","avatar":""},{"name":"Hanae Kan","avatar":""},{"name":"YOU","avatar":""},{"name":"Ryo Kase","avatar":""},{"name":"Kazuyoshi Kushida","avatar":""},{"name":"Yukiko Okamoto","avatar":""},{"name":"Sei Hiraizumi","avatar":""},{"name":"Takako Tate","avatar":""},{"name":"Yuichi Kimura","avatar":""},{"name":"Kenichi Endo","avatar":""},{"name":"Susumu Terajima","avatar":""},{"name":"Shinichi Hashizawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["谁知赤子心","无人知晓的夏日清晨","Dare mo shiranai","Nobody Knows - Die Kofferkinder","Nessuno lo sa","誰も知らない"]', 1784690324527);
