INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-su-tu-3-2004', 'Vua Sư Tử 3', 'The Lion King 1½', 'https://phimimg.com/upload/vod/20251120-1/5eb587829dd240f3c2447a33250006f7.jpg', 'https://phimimg.com/upload/vod/20251120-1/b631b447a62d8cc9a921a12adacb764f.jpg', '<p>The Lion King 1½ được coi là phần 3 của The Lion King, mặc dù trong phần này sự xuất hiện của Simba không nhiều. Phần này nhắc nhiều đến Timon (người bạn từ thuở thiếu thời của Simba). Anh chàng trên con đường đi tìm &quot;Vùng đất hứa&quot; (hay chính xác hơn là &quot;vùng đất không có việc làm&quot; - vì Timon làm việc gì cũng hỏng). Phần 3 của phim là một phần vui nhộn khiến bạn có thể cười thả ga...</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nathan Lane","avatar":""},{"name":"Ernie Sabella","avatar":""},{"name":"Julie Kavner","avatar":""},{"name":"Jerry Stiller","avatar":""},{"name":"Matthew Broderick","avatar":""},{"name":"Robert Guillaume","avatar":""},{"name":"Moira Kelly","avatar":""},{"name":"Whoopi Goldberg","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Edward Hibbert","avatar":""},{"name":"Jason Rudofsky","avatar":""},{"name":"Matt Weinberg","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Corey Burton","avatar":""},{"name":"Bill Farmer","avatar":""},{"name":"Shaun Fleming","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Hakuna Matata","The Lion King 3: Hakuna Matata","The Lion King III","The Lion King 3","Le Roi Lion 3 - Hakuna Matata","The Lion King III Hakuna Mata