INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-thanh-quyet-2004', 'Liên Thành Quyết', 'A Deadly Secret', 'https://phimimg.com/upload/vod/20250929-1/b06f66369b6bfa9a2ac7738d98826231.jpg', 'https://phimimg.com/upload/vod/20250929-1/5e8e3da0cecde21588350a00d6bf27b8.jpg', '<p>Địch Vân là đệ tử của Thích Trường Phát, một trong ba cao thủ xuất chúng đã quy ẩn giang hồ. Từ nhỏ vốn mồ côi, Địch Vân được Thích Trường Phát nhận làm đệ tử, truyền thụ võ công cùng với con gái là Thích Phương. Địch Vân và Thích Phương có tình cảm sâu nặng hơn tình huynh muội, định một ngày nào đó sẽ cùng nhau chung sống dưới một mái ấm nhỏ mà hạnh phúc. Không ngờ đến một ngày, Vạn Chấn Sơn – sư huynh của Thích Trường Phát, mời sư đệ lên thành để truy tìm bí kíp võ công “Liên thành quyết kiếm”. Tại đây, Vạn Khuê – con trai của Vạn Chấn Sơn đã nảy sinh tình ý với Thích Phương, tìm cách hãm hại Địch Vân, đẩy chàng vào chốn tù ngục. Đinh Điển là một nho sinh tài hoa, vì có một mối tình với Lăng Sương Hoa, con gái của huyện lệnh mà bị hãm hại, cả đời phải sống trong nhà lao cách biệt, không sao đến được với người mình yêu dấu.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 13, 2004, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Duệ","avatar":""},{"name":"Hà Mỹ Điền","avatar":""},{"name":"Thư Sướng","avatar":""},{"name":"Đổ Chí Quốc","avatar":""},{"name":"Lục Tiểu Linh Đồng","avatar":""},{"name":"Tiền Vịnh Trần","avatar":""},{"name":"Vương Hải Địa","avatar":""},{"name":"Cao Bối Bối","avatar":""},{"name":"Kế Xuân Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["连城诀","連城訣","Liên Thành Quyết","Secret Of The Linked Cities"]', 1784690324527);
