INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-gai-nhac-jazz', 'Những Cô Gái Nhạc Jazz', 'Swing Girls', 'https://phimimg.com/upload/vod/20250919-1/3ea922eb1ff4498cdad9b89b07652126.jpg', 'https://phimimg.com/upload/vod/20250919-1/278fb9e3702d6a20346e7b6d4cc9b61d.jpg', '<p>Tại một trường trung học vùng nông thôn Nhật Bản, một nhóm nữ sinh vốn dĩ chẳng hứng thú gì với âm nhạc được giao nhiệm vụ mang cơm trưa cho ban nhạc của trường — những nam sinh đang tham gia câu lạc bộ nhạc jazz. Tuy nhiên, do một sự cố ngớ ngẩn (thức ăn bị hư), toàn bộ thành viên ban nhạc bị ngộ độc thực phẩm và phải nhập viện.</p>', 'Full', 1, 'single', 'completed', 17, 2004, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Juri Ueno","avatar":""},{"name":"Yuta Hiraoka","avatar":""},{"name":"Shihori Kanjiya","avatar":""},{"name":"Yuika Motokariya","avatar":""},{"name":"Yukari Toyoshima","avatar":""},{"name":"Naoto Takenaka","avatar":""},{"name":"Nagisa Abe","avatar":""},{"name":"Noriko Eguchi","avatar":""},{"name":"Hana Kino","avatar":""},{"name":"Fumiyo Kohinata","avatar":""},{"name":"Fumiko Mizuta","avatar":""},{"name":"Madoka Matsuda","avatar":""},{"name":"Naomi Nishida","avatar":""},{"name":"Mutsuko Sakura","avatar":""},{"name":"Miho Shiraishi","avatar":""},{"name":"Issey Takahashi","avatar":""},{"name":"Masaaki Tak","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["喇叭书院","Suwingu gâruzu","스윙걸즈","搖擺女孩","摇摆少女","Swing Girls","スウィングガールズ：2004","Garotas do Balanço","スウィングガールズ"]', 1784690324527);
