INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phep-thuat-phan-7', 'Phép Thuật (Phần 7)', 'Charmed (Season 7)', 'phép thuật (phần 7) charmed (season 7) holly marie combs alyssa milano rose mcgowan brian krause kaley cuoco charmed: jovens bruxas oi magisses η μαγευτικές チャームド 魔女3姉妹 チャームド〜魔女3姉妹〜 hechiceras чародійки зачаровані всі жінки відьми усі жінки відьми charmed', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-duc-no-hoa', 'Sắc Dục Nở Hoa', 'Colour Blossoms', 'https://phimimg.com/upload/vod/20250909-1/4d2f969639d6ee642c2b506de87a39db.jpg', 'https://phimimg.com/upload/vod/20250909-1/5bd1a9a1929750c8da3ad2a22ffb4a03.jpg', '<p>Một nhân viên môi giới bất động sản bị cuốn vào mối quan hệ nồng nhiệt nhưng đầy tính bạo dâm với một nữ nhiếp ảnh gia người Nhật. Cả hai quấn quýt trong một căn hộ sang trọng thuộc sở hữu của một quý bà Nhật Bản thượng lưu tao nhã, đồng thời va chạm với một viên cảnh sát si tình, một người phụ nữ Hàn Quốc bí ẩn, và rồi dần mắc kẹt trong mạng lưới chằng chịt của bạo lực, những đam mê chéo nhau và những dục vọng trần trụi không kiểm soát.</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Teresa Cheung","avatar":""},{"name":"Keiko Matsuzaka","avatar":""},{"name":"Carl Ng Ka-Lung","avatar":""},{"name":"Sho Yokouchi","avatar":""},{"name":"Harisu","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Ku Feng","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Color Blossoms","Toh sik","하리수 도색","桃色"]', 1784690324527);
