INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nhen-2', 'Người Nhện 2', 'Spider-Man 2', 'https://phimimg.com/upload/vod/20250828-1/61c18f4cfb84ca64fc6182fa7ff3a3a4.jpg', 'https://phimimg.com/upload/vod/20250828-1/05a7ca0a3b7469278e817e726dcd966d.jpg', '<p>Đã hai năm kể từ khi Peter Parker im lặng rời bỏ Mary Jane Watson, tình yêu vĩ đại của anh và quyết định tiếp tục đảm nhận trách nhiệm của mình với tư cách là Người Nhện. Peter phải đối mặt với những thử thách mới khi anh chiến đấu với món quà và lời nguyền về sức mạnh của mình bằng cách cân bằng hai danh tính: Người nhện siêu anh hùng khó nắm bắt và sinh viên đại học. Mối quan hệ với những người mà anh ấy trân trọng nhất hiện đang có nguy cơ bị phơi bày với sự xuất hiện của một nhân vật phản diện nhiều xúc tu mạnh mẽ Octopus, &quot;Doc Ock. Sức hấp dẫn của cô đối với MJ ngày càng lớn khi cô chiến đấu với sự thôi thúc từ bỏ cuộc sống bí mật của mình và tuyên bố tình yêu của mình. Trong khi đó, MJ đã tiếp tục cuộc sống của mình. Cuộc sống của cô Mối quan hệ của Peter với người bạn thân nhất Harry Osborn đã bị phá vỡ bởi mối thù truyền kiếp của Harry chống lại Người Nhện, người mà anh ta chịu trách nhiệm cho cái chết của cha mình.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tobey Maguire","avatar":""},{"name":"Kirsten Dunst","avatar":""},{"name":"James Franco","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Rosemary Harris","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Donna Murphy","avatar":""},{"name":"Daniel Gillies","avatar":""},{"name":"Dylan Baker","avatar":""},{"name":"Bill Nunn","avatar":""},{"name":"Vanessa Ferlito","avatar":""},{"name":"Aasif Mandvi","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Cliff Robertson","avatar":""},{"name":"Ted Raimi","avatar":""},{"name":"Elizabeth Banks","avatar":""},{"name":"Bruce Campbell","avatar":""},{"name":"Gregg","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Spajdermen 2","Spáinterman 2","Spider-Man 2 Lives","Spider-Man 2: The IMAX Experience","Spider-Man: No More","Spider-Man II","Spider-Man 2 - Spider-Man ist zurück","Spaĭdŭr-men 2","Lyudyna-pavuk 2","Hämähäkkimies 2","ობობა-კაცი 2","სპაიდერმენი 2","Spider-Man 2.1","スパイダーマン2：2004","Người Nhện 2","Spider Man II","Homem Aranha 2","蜘蛛侠2 (托比·马奎尔)","ပင့်ကူလူသား ၂","Hörümçək-Adam 2","الرجل العنكبوت ٢","Spider-Man 2"]', 1784690324527);
