INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lau-dai-bay-cua-phap-su-howl', 'Lâu Đài Bay Của Pháp Sư Howl', 'Howl''s Moving Castle', 'lâu đài bay của pháp sư howl howl''s moving castle chieko baisho takuya kimura akihiro miwa tatsuya gashûin ryunosuke kamiki mitsunori isaki yo oizumi akio otsuka daijirō harada haruko katō makoto yasumura manabu muraji keiko tsukamoto tsuzuki kayako seiji sasaki hiroshi takahashi mayuno y haulov pokretni zamak замок-мандрівник подвижният замък на хол шагающий замок хаула hauru no ugoku shiro howl no ugoku shiro قلعۀ متحرک هاول ghaleye motahareke howl ghaleh motahareke howl le chateau ambulant 하울의 움직이는 성 howl''un yürüyen şatosu det levende slottet 哈尔的移动城堡 yeriyən şato howlův kráčející hrad ハウルの動く城 el increíble castillo vagabundo 哈爾移動城堡 howls bewegende kasteel הטירה הנעה 霍爾的移動城堡 հաուլի թափառող դղյակը ходячий замок 哈尔移动城堡 o castelo animado howl''s moving castle', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-quy-du-khai-huyen', 'Vùng Đất Quỷ Dữ: Khải Huyền', 'Resident Evil: Apocalypse', 'https://phimimg.com/upload/vod/20250716-1/805e67dfa522275ae25287dabe56ff40.jpg', 'https://phimimg.com/upload/vod/20250716-1/d8a9fe4438e0c15f396bff356ca676a5.jpg', '<p>Alice tỉnh dậy tại thành phố Raccoon- nơi mà cư dân ở đây đã bị biến thành zombie và quái vật. Với sự giúp đỡ của Jill Valentine, Carlos Olivera, Alice phải tìm một cách ra khỏi thành phố này trước khi nó bị phá hủy bởi tên lửa hạt nhân.</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"Sienna Guillory","avatar":""},{"name":"Oded Fehr","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Sophie Vavasseur","avatar":""},{"name":"Razaaq Adoti","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Mike Epps","avatar":""},{"name":"Sandrine Holt","avatar":""},{"name":"Matthew G. Taylor","avatar":""},{"name":"Zack Ward","avatar":""},{"name":"Iain Glen","avatar":""},{"name":"Dave Nichols","avatar":""},{"name":"Stefen Hayes","avatar":""},{"name":"Geoffrey Pounsett","avatar":""},{"name":"Shaun Austin-Olsen","avatar":""},{"name":"Geny Walter","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Resident Evil 2: Apocalypse","Resident Evil 2","Biohazard II: Apocalypse","Resident Evil II - Apocalypse","Resident Evil 2 -  Apocalypse","Resident Evil 2 - Apocolypse","Resident Evil 2 - Apocalypse","Oselia zla 2: Apokalipsys","Оселя зла 2: Апокаліпсис","Resident Evil 2 - Apocalipse","Resident Evil Apocalypse Extended","레지던트 이블 2","Obitel'' zla 2: Apokalipsis","Resident Evil. Apocalypse","레지던트 이블 2-아포칼립스","Zarazno zlo: Apokalipsis","Resident Evil: Apokálypsi","Pritajeno zlo - Apokalipsa","Resident Evil：Apocalypse","레지던트 이블 2: 아포칼립스","生化危机2：启示录","Resident Evil Apocalypse","バイオハザード2","الشر المقيم : نهاية العالم","Resident Evil: Apocalypse"]', 1784690324527);
