INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-thien-su-vo-danh', 'Những Thiên Sứ Vô Danh', 'Angels of Mission', 'https://phimimg.com/upload/vod/20250616-1/78a712c40b9573af7edb23c0636a6089.jpg', 'https://phimimg.com/upload/vod/20250616-1/0ba756dbe66692e8767c924faa167340.jpg', '<p>Đội Chống Khủng Bố (CTU) chuyên phụ trách thu thập thông tin tình báo và chống lại các hoạt động khủng bố, trong đó có ba nữ cảnh sát xinh đẹp với cá tính khác nhau nhưng đều có biểu hiện xuất sắc chính là Tống Lạc Kỳ, Diêu Lệ Hoa và Đường Bảo Nhi. Lạc Kỳ là thanh tra tổng CTU, hào phóng cởi mở, xử lý công việc công tư phân minh, chuyện tình cảm không bao giờ dây dưa kéo dài. Lệ Hoa thân thủ vượt trội, tuy tính tình hơi bốc đồng nhưng luôn tràn đầy nhiệt huyết với công việc. Bảo Nhi thông minh lanh lợi, thích nhàn hạ, có tài bắn súng vô cùng chuẩn xác. Ba nữ cảnh sát vừa là đồng nghiệp ăn ý lại vừa là bạn tốt của nhau, cùng vào sinh ra tử, chống lại những hoạt động khủng bố.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2004, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Sonija Kwok Sin-Nae","avatar":""},{"name":"Charmaine Sheh Sze-Man","avatar":""},{"name":"Shirley Yeung Sze-Kei","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Shek Sau","avatar":""},{"name":"Claire Yiu","avatar":""},{"name":"Stephen Au Kam-Tong","avatar":""},{"name":"Timmy Hung Tin-Ming","avatar":""},{"name":"Felton Law Gwan-Joh","avatar":""},{"name":"Gilbert Lam Wai-San","avatar":""},{"name":"Ko Cheun-Man","avatar":""},{"name":"Ken Lok Tat-Wah","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Ram Chiang Chi-Kwong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["無名天使3D"]', 1784690324527);
