INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-coc-2004', 'Bắt Cóc (Tín Hiệu Sống)', 'Cellular', 'https://phimimg.com/upload/vod/20250609-1/b19a0d3ffea37fa31dc00cb8aee7efd6.jpg', 'https://phimimg.com/upload/vod/20250609-1/cec0dbd324334323ee7c925d0124f5b9.jpg', '<p>Một chàng trai trẻ nhận được một cuộc điện thoại khẩn cấp trên điện thoại di động của mình từ một người phụ nữ lớn tuổi. Một vụ bắt cóc ? Người phụ nữ cho biết đã bị bắt cóc, và những kẻ bắt cóc sẽ nhắm tiếp vào chồng và con của cô.</p>', 'Full', 1, 'single', 'completed', 17, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kim Basinger","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Jason Statham","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Noah Emmerich","avatar":""},{"name":"Valerie Cruz","avatar":""},{"name":"Richard Burgi","avatar":""},{"name":"Eric Christian Olsen","avatar":""},{"name":"Jessica Biel","avatar":""},{"name":"Rick Hoffman","avatar":""},{"name":"Will Beinbrink","avatar":""},{"name":"Greg Collins","avatar":""},{"name":"Erin Foster","avatar":""},{"name":"Brenda Ballard","avatar":""},{"name":"Paige Cannon","avatar":""},{"name":"Caroline Aaron","avatar":""},{"name":"Chase Ellis B","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["保持通话","Celular","Final Call","Cellular"]', 1784690324527);
