INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngheo-con-bi-ma-am', 'Nghèo Còn Bị Ma Ám', 'Poor Ghost', 'https://phimimg.com/upload/vod/20250608-1/7b074ac1e4ce389107ec502b5b9353a2.jpg', 'https://phimimg.com/upload/vod/20250608-1/8ba5d7ff5da2b51e9a75269a79378a07.jpg', '<p>Vì thói nghiện cờ bạc, Trương Dương phải trốn chạy bọn cho vay nặng lãi và dạt về một khu nhà cũ kỹ. Tại đây, anh ta gặp một hồn ma xuất hiện mỗi đêm để “ân ái” với anh. Điều kỳ lạ là: mỗi lần sau khi “giao lưu thể xác”, anh lại phát hiện một dãy số bí ẩn trong… quần lót. Từ đó, vận may của Trương Dương thay đổi hoàn toàn – trúng số, thắng cược, tiền tài ập đến như mơ...</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Matthew Ng Ting","avatar":""},{"name":"April Tung Ling","avatar":""},{"name":"Long-Ming Lee","avatar":""},{"name":"Tat Wah Choi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Misfortune","Poor Ghost","愈窮愈見鬼"]', 1784690324527);
