INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoanh-khac-de-nho', 'Khoảnh Khắc Để Nhớ', 'A Moment to Remember', 'https://phimimg.com/upload/vod/20250604-1/6ab931ad1c00ea7428525a30f943e43c.jpg', 'https://phimimg.com/upload/vod/20250604-1/a712fb19932918696883bf0ec2392ad5.jpg', '<p>Kể về Soo Jin - một nhà thiết kế thời trang bị bệnh mất trí nhớ ngắn hạn. cô hay bỏ quên những thứ mình mua và ví tiền nơi mà cô đến mua. Một ngày cô bỏ quên chai nước, và ở đây cô đã găp một chàng trai lúc đầu có nhiều mâu thuẫn xảy ra nhưng sau này họ là một đôi. Bộ phim cũng nói lên những cố gắng của cô để không quên hình ảnh của Chul Soo khi mà bệnh cô càng nặng thêm sau khi kết hôn...</p>', 'Full', 1, 'single', 'completed', 10, 2004, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Woo-sung","avatar":""},{"name":"Son Ye-jin","avatar":""},{"name":"Baek Jong-hak","avatar":""},{"name":"Lee Sun-jin","avatar":""},{"name":"Park Sang-gyu","avatar":""},{"name":"Kim Hee-ryung","avatar":""},{"name":"Seon Ji-hyun","avatar":""},{"name":"Kim Bu-seon","avatar":""},{"name":"Jang In-han","avatar":""},{"name":"Kwon Byung-gil","avatar":""},{"name":"Shin Cheol-jin","avatar":""},{"name":"Kim Joong-ki","avatar":""},{"name":"Jin Yong-uk","avatar":""},{"name":"Seo Jin-won","avatar":""},{"name":"Shin Hyun-tak","avatar":""},{"name":"Hyun Young","avatar":""},{"name":"Park Mi-sook","avatar":""},{"name":"David Lee McInnis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["我脑中的橡皮擦","拥抱这分钟","我腦中的橡皮擦","A Moment To Remember","Eraser in my head","Nae Meorisokui Jiwoogae","내 머리 속의 지우개","私の頭の中の消しゴム：2004","私の頭の中の消しゴム：2004-JPN","私の頭の中の消しゴム：2004-KOR"]', 1784690324527);
