INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khoanh-khac-de-nho', 'Khoảnh Khắc Để Nhớ', 'A Moment to Remember', 'khoảnh khắc để nhớ a moment to remember jung woo-sung son ye-jin baek jong-hak lee sun-jin park sang-gyu kim hee-ryung seon ji-hyun kim bu-seon jang in-han kwon byung-gil shin cheol-jin kim joong-ki jin yong-uk seo jin-won shin hyun-tak hyun young park mi-sook david lee mcinnis 我脑中的橡皮擦 拥抱这分钟 我腦中的橡皮擦 a moment to remember eraser in my head nae meorisokui jiwoogae 내 머리 속의 지우개 私の頭の中の消しゴム：2004 私の頭の中の消しゴム：2004-jpn 私の頭の中の消しゴム：2004-kor', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-ta-diet-ma-phan-3', 'Khử Tà Diệt Ma (Phần 3)', 'My Date with a Vampire (Season 3)', 'https://phimimg.com/upload/vod/20250602-1/2d299b49b2b86e73f5c7639774368778.jpg', 'https://phimimg.com/upload/vod/20250602-1/a4d428e7978ce9bc56994901ce3ce9fa.jpg', '<p>Câu chuyện xoay quanh Phụng Sanh, một cô gái trở thành ma cà rồng sau một vụ tấn công bí ẩn. Trong khi đó, Long Nhạt là một ma đầu và kẻ săn sinh mạng, tạo nên những cuộc phiêu lưu đầy kịch tính và những hiện tượng siêu nhiên bí ẩn. Xuyên suốt bộ phim, những nhân vật này phải đối mặt với nhiều thử thách nguy hiểm và những mối tình phức tạp, đan xen giữa thế giới thực và thế giới ma quái.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 13, 2004, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Joey Man Yee-Man","avatar":""},{"name":"Eric Wan Tin-Chiu","avatar":""},{"name":"Kenneth Chan","avatar":""},{"name":"Alice Chan Wai","avatar":""},{"name":"Pinky Cheung Man-Chi","avatar":""},{"name":"Wong Shu-Tong","avatar":""},{"name":"Daniel Cheung","avatar":""},{"name":"Thomas Sin Ho-Ying","avatar":""},{"name":"Asuka Higuchi","avatar":""},{"name":"Ricky Chan Po-Yuen","avatar":""},{"name":"Ruco Chan","avatar":""},{"name":"Andrew Yuen","avatar":""},{"name":"Qin Lan","avatar":""},{"name":"Norman Tsui","avatar":""},{"name":"Remus Kam","avatar":""},{"name":"Tats Lau Yee-Tat","avatar":""},{"name":"Jason","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["我和僵尸有个约会","我和殭屍有個約會","나랑 좀비 약속이 있어서"]', 1784690324527);
