INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khu-ta-diet-ma-phan-3', 'Khử Tà Diệt Ma (Phần 3)', 'My Date with a Vampire (Season 3)', 'khử tà diệt ma (phần 3) my date with a vampire (season 3) joey man yee-man eric wan tin-chiu kenneth chan alice chan wai pinky cheung man-chi wong shu-tong daniel cheung thomas sin ho-ying asuka higuchi ricky chan po-yuen ruco chan andrew yuen qin lan norman tsui remus kam tats lau yee-tat jason 我和僵尸有个约会 我和殭屍有個約會 나랑 좀비 약속이 있어서', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('harry-potter-va-tu-nhan-azkaban', 'Harry Potter và Tù Nhân Azkaban', 'Harry Potter and the Prisoner of Azkaban', 'https://phimimg.com/upload/vod/20250602-1/56e3b9d83afe1bb47579e9b3488474f4.jpg', 'https://phimimg.com/upload/vod/20250602-1/01a4ce613a13f86f386fc37b9d01044b.jpg', '<p>Harry đang mong chờ đến cuối mùa hè để bắt đầu một khóa học mới tại Hogwarts, và rời khỏi ngôi nhà của người dì và người chú đáng khinh của mình, Dursley, càng sớm càng tốt. Điều Harry không biết là anh sẽ phải rời khỏi Privet Drive sớm và bất ngờ sau khi biến dì Marge của mình thành một quả bóng bay khổng lồ. Một chiếc xe buýt đêm, và tất nhiên là mê hoặc, sẽ đưa anh ta đến quán rượu Leaky Cauldron, nơi không ai khác ngoài Cornelius Fudge, Bộ trưởng Bộ Pháp thuật, đang chờ anh ta.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Tom Felton","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Julie Walters","avatar":""},{"name":"Richard Griffiths","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"Maggie Smith","avatar":""},{"name":"David Bradley","avatar":""},{"name":"Pam Ferris","avatar":""},{"name":"Dawn F","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Hari Poter i zatvorenik iz Askabana","Garri Potter i uznik Azkabana","Khari Potŭr i zatvornikŭt ot Azkaban","O Chári Póter kai o Aichmálotos tou Azkampán","Hari Poter i Zatvorenikot od Azkaban","Harri Potter i v''yazenʹ Azkabanu","Harry Potter A Vezen Zazkabanu","Harry Potter Eo Prisoneiro de Azkaban","Harry Potter e o Prisioneiro de Azkaban","해리포터와 아즈카반의 죄수","Гарри Поттер и узник Азкабана","ハリー・ポッターとアズカバンの囚人","ハリーポッターとアズカバンの囚人","הרי פותר והאסיר מאזקבאן","Harry Potter et le Prisonnier d''Azkaban","Harry Potter ja Azkabani vang","哈利·波特与阿兹卡班的囚徒","แฮร์รี่ พอตเตอร์กับนักโทษแห่งอัซคาบัน","Harry Potter và Tên Tù Nhân Ngục Azkaban","هاري بوتر وسجين أزكابان","Հարրի Փոթերը և Ազկաբանի Բանտարկյալը","هری پاتر و زندن آزکابان","Harry Potter 3","Harry Potter 3 - Prisoner of Azkaban","Harry Potter 3 - The Prisoner of Azkaban","HP3","Harry Potter and the Prisoner of Azkaban"]', 1784690324527);
