INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('harry-potter-va-tu-nhan-azkaban', 'Harry Potter và Tù Nhân Azkaban', 'Harry Potter and the Prisoner of Azkaban', 'harry potter và tù nhân azkaban harry potter and the prisoner of azkaban daniel radcliffe rupert grint emma watson robbie coltrane michael gambon gary oldman david thewlis timothy spall alan rickman tom felton emma thompson julie walters richard griffiths fiona shaw maggie smith david bradley pam ferris dawn f hari poter i zatvorenik iz askabana garri potter i uznik azkabana khari potŭr i zatvornikŭt ot azkaban o chári póter kai o aichmálotos tou azkampán hari poter i zatvorenikot od azkaban harri potter i v''yazenʹ azkabanu harry potter a vezen zazkabanu harry potter eo prisoneiro de azkaban harry potter e o prisioneiro de azkaban 해리포터와 아즈카반의 죄수 гарри поттер и узник азкабана ハリー・ポッターとアズカバンの囚人 ハリーポッターとアズカバンの囚人 הרי פותר והאסיר מאזקבאן harry potter et le prisonnier d''azkaban harry potter ja azkabani vang 哈利·波特与阿兹卡班的囚徒 แฮร์รี่ พอตเตอร์กับนักโทษแห่งอัซคาบัน harry potter và tên tù nhân ngục azkaban هاري بوتر وسجين أزكابان հարրի փոթերը և ազկաբանի բանտարկյալը هری پاتر و زندن آزکابان harry potter 3 harry potter 3 - prisoner of azkaban harry potter 3 - the prisoner of azkaban hp3 harry potter and the prisoner of azkaban', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naruto-cuoc-chien-o-tuyet-quoc', 'Naruto: Cuộc Chiến Ở Tuyết Quốc', 'Naruto the Movie: Ninja Clash in the Land of Snow', 'https://phimimg.com/upload/vod/20250604-1/ba12f01d984089cf39643771999f14b9.jpg', 'https://phimimg.com/upload/vod/20250604-1/4d040231dadbce1a312340480c69cfb2.jpg', '<p>Bộ phim mở đầu với công chúa Fuun cùng ba anh lính trung thành là trợ lí đắc lực của cô. Họ đã định bỏ cuộc khi phải chiến đấu mệt mỏi với Mao-tay bạo chúa già. Nhưng công chú Fuun nhất quyết không bỏ cuộc và trong lúc tức giận đã hiện lên chakra bảy màu để chống lại Mao. Cả ba trợ lí quyết định cũng sử dụng nguồn chakra của mình để hợp sức cùng công chúa Fuun và đã chống lại Mao. Cuối cùng họ cũng đã thắng và quyết định quay về nơi hiện lên cầu vồng.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2004, 'Vietsub + Lồng Tiếng', 'HD', 'Nhật Bản', 0, '[{"name":"Junko Takeuchi","avatar":""},{"name":"Chie Nakamura","avatar":""},{"name":"Noriaki Sugiyama","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Hidehiko Ishizuka","avatar":""},{"name":"Yuhko Kaida","avatar":""},{"name":"Hirotaka Suzuoki","avatar":""},{"name":"Ikuo Nishikawa","avatar":""},{"name":"Jun Karasawa","avatar":""},{"name":"Tsutomu Isobe","avatar":""},{"name":"Chikao Ohtsuka","avatar":""},{"name":"Yutaka Nakano","avatar":""},{"name":"Kan Tanaka","avatar":""},{"name":"Holly Kaneko","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["NARUTO: Dai Katsugeki! Yuki Hime Ninpouchou Dattebayo!!","Naruto : Les chroniques ninja de la princesse des neiges","火影忍者剧场版：大活剧！雪姬忍法帖","대활극!! 설희인법첩","Naruto 1: Confronto Ninja no País da Neve!","NARUTO: NINJA ĐẠI CHIẾN Ở TUYẾT QUỐC","Naruto Film 1 - Naruto et la Princesse des neiges","Naruto the Movie: Ninja Clash in the Land of Snow","Naruto: It''s the Snow Princess'' Ninja Art Book!","Naruto The Movie","Naruto 1: Záchrana sněžné princezny","Naruto - Geheimmission im Land des ewigen Schnees","Naruto le film : Naruto et la princesse des neiges","Naruto the Movie 1: Ninja Clash in the Land of Snow","Naruto et la princesse des neiges","Наруто (фильм первый)","Naruto: Dai Katsugeki! Yuki Hime Ninpou Chou Datte ba yo!!","나루토 극장판 1기 - 대활극! 설희인법첩","나루토 극장판 1: 대활극! 설희인법첩","Naruto: ¡Batalla ninja en la tierra de la nieve!","火影忍者剧场版1：大活剧！雪姬忍法帖","فیلم ناروتو: مبارزه نینجایی در سرزمین برف","ناروتو: برخورد نینجایی در سرزمین برف","나루토 극장판 1: 대활극! 눈의 공주 인법첩","나루토 극장판 대활극! 눈의 공주 인법첩","Naruto Movie 1: Dai Katsugeki!! Yuki Hime Ninpouchou Dattebayo!","劇場版 NARUTO 大活劇! 雪姫忍法帖だってばよ!!"]', 1784690324527);
