INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xich-lai-gan-nhau', 'Xích Lại Gần Nhau', 'Closer', 'https://phimimg.com/upload/vod/20250526-1/d334c07cf440744f9fcfda301333f1a6.jpg', 'https://phimimg.com/upload/vod/20250526-1/deeb3ec3b0f74a2aaa6dc2cda019a7e0.jpg', '<p>Closer là một câu truyện tình yêu phức tạp của 4 nhân vật chính, cả 4 người đều cùng lúc rơi vào một vòng luẩn quẩn trò chơi tình yêu, tình dục, đam mê và bi kịch. Họ vừa là nạn nhân vừa là thủ phạm, trong mối quan hệ tay tư chồng chéo giữa một nhà báo đẹp trai Dan Wolf (Jude Law), một vũ nữ thoát y Alice Ayred (Natalie Portman), một nữ nhiếp ảnh gia Anne Cameron (Julia Roberts) và chồng cô một bác sĩ da liễu nghiện sex Larry Bagley (Clive Owen).</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jude Law","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Colin Stinton","avatar":""},{"name":"Nick Hobbs","avatar":""},{"name":"Steve Benham","avatar":""},{"name":"Elizabeth Bower","avatar":""},{"name":"Daniel Dresner","avatar":""},{"name":"Rrenford Junior Fagan","avatar":""},{"name":"Antony Gabriel","avatar":""},{"name":"Michael Haley","avatar":""},{"name":"Selena Mars","avatar":""},{"name":"Steve Morphew","avatar":""},{"name":"Peter Rnic","avatar":""},{"name":"Robert Stone","avatar":""},{"name":"Jacqui-Lee Pryce","avatar":""},{"name":"R","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Closer (Cegados por el deseo)","Ex epafis","靠近","诱心人","클로저","Cegados por el deseo (Closer)","Closer"]', 1784690324527);
