INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-truong-sky-va-the-gioi-tuong-lai', 'Cơ Trưởng Sky Và Thế Giới Tương Lai (Thống Soái Bầu Trời)', 'Sky Captain and the World of Tomorrow', 'https://phimimg.com/upload/vod/20250514-1/3a3f1790aa363086fcf5012bd3fe1432.jpg', 'https://phimimg.com/upload/vod/20250514-1/636917a9de1aba5cdc4e63e0d92b0ed2.jpg', '<p>Năm 1939, thành phố New York bị tấn công bởi một nhóm robot khổng lồ, cùng lúc đó một số nhà khoa học hàng đầu đột nhiên mất tích. Để tìm ra sự thật, nữ ký giả xinh đẹp Polly Perkins cùng với chàng phi công điển trai Joe Sullivan (thường được gọi Sky Captain) quyết định làm một chuyến hành trình mạo hiểm đến Nepal, theo những dấu hiệu để lại của chàng khoa học gia trẻ tuổi Dex trước khi Dex bị bắt.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jude Law","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Bai Ling","avatar":""},{"name":"Omid Djalili","avatar":""},{"name":"Laurence Olivier","avatar":""},{"name":"Trevor Baxter","avatar":""},{"name":"Julian Curry","avatar":""},{"name":"Peter Law","avatar":""},{"name":"Jon Rumney","avatar":""},{"name":"Khan Bonfils","avatar":""},{"name":"Samta Gyatso","avatar":""},{"name":"Louis Hilyer","avatar":""},{"name":"Mark Wells","avatar":""},{"name":"James Cash","avatar":""},{"name":"Tenzin Bhagen","avatar":""},{"name":"Thup","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug"