INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-kho-nan-cua-chua-giesu', 'Cuộc khổ nạn của Chúa Giêsu', 'The Passion of the Christ', 'cuộc khổ nạn của chúa giêsu the passion of the christ jim caviezel maia morgenstern christo jivkov francesco de vito monica bellucci mattia sbragia toni bertorelli luca lionello hristo shopov claudia gerini fabio sartor giacinto ferro aleksander mincer sheila mokhtari lucio allocca paco recont passion the passion the passion of christ the passion recut kristuksen kärsimyskertomus kristi lidandes historia strastite khristovi ta páthi tou christoú strasti khristovy stradanje hristovo strasti khrystovi die passion christi a paixão de cristo the passion of the christ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-nhay-chu', 'Ta Nhảy Chứ', 'Shall We Dance', 'https://phimimg.com/upload/vod/20231103-1/cd76364ac2467d55a52fdd56fed3a9db.jpg', 'https://phimimg.com/upload/vod/20231103-1/870ec6fc1de35a3a0b1d628e09defba2.jpg', '<p>John Clark là một người đàn ông với một công việc tuyệt vời, một người vợ duyên dáng và một gia đình yêu thương, những người vẫn cảm thấy thiếu một cái gì đó như ông đã làm theo cách của mình mỗi ngày qua thành phố. Mỗi buổi tối trên đường về nhà đi làm của mình, John nhìn thấy một phụ nữ đẹp, nhìn chằm chằm với một biểu hiện bị mất thông qua các cửa sổ của một phòng khiêu vũ. Bị ám ảnh bởi cái nhìn của cô, John hấp tấp nhảy ra khỏi tàu một đêm, và dấu hiệu cho học khiêu vũ, hy vọng để gặp cô ấy. Lúc đầu, nó có vẻ như là một sai lầm. Cô giáo của mình hóa ra là không Paulina, nhưng cũ Hoa hậu Mitzi, và John chứng minh chỉ là vụng về như các bạn cùng lớp của mình tránh khỏi thất bại như nhau trên sàn nhảy. Thậm chí tệ hơn, khi ông không đáp ứng Paulina, cô lạnh lùng nói với John cô hy vọng ông đã đến phòng thu để nghiêm túc học khiêu vũ và không nhìn cho một ngày. Tuy nhiên, như bài học của mình tiếp tục, John rơi vào tình yêu với vũ đạo. Giữ nỗi ám ảnh mới của mình từ gia đình và đồng nghiệp, John luống cuống huấn luyện cho cuộc thi nhảy lớn nhất của Chicago. Tình bạn của ông với hoa Paulina, như mình...</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Richard Gere","avatar":""},{"name":"Jennifer Lopez","avatar":""},{"name":"Susan Sarandon","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Lisa Ann Walter","avatar":""},{"name":"Anita Gillette","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Omar Benson Miller","avatar":""},{"name":"Tamara Hope","avatar":""},{"name":"Stark Sands","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Nick Cannon","avatar":""},{"name":"Sarah Lafleur","avatar":""},{"name":"Onalee Ames","avatar":""},{"name":"Diana Salvatore","avatar":""},{"name":"Daphne Korol","avatar":""},{"name":"David Spa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324527);
