INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-sieu-nhan', 'Gia Đình Siêu Nhân', 'The Incredibles', 'https://phimimg.com/upload/vod/20250327-1/0cf972d6b55b908d1bbde0e7a75b1f14.jpg', 'https://phimimg.com/upload/vod/20250327-1/7b8f8881bd38bdc97d2170160234bb69.jpg', '<p>Một gia đình gồm các siêu anh hùng gần như đã nghỉ hưu, hơi thừa cân và cố gắng sống sót trong cuộc sống hàng ngày khắc nghiệt, bị buộc phải hành động ... chỉ đơn giản là để cứu thế giới. Bob Paar từng là một trong những siêu anh hùng vĩ đại nhất thế giới (anh ta còn được gọi là &quot;Mr. Incredible&quot;), cứu mạng và chiến đấu với những kẻ ác hàng ngày. Mười lăm năm đã trôi qua, và Bob và vợ (một cựu siêu anh hùng nổi tiếng ở bên phải) đã nhận được một bản sắc dân sự và lui về ngoại vi để sống một cuộc sống bình thường với ba đứa con của họ. Bob kiểm tra thời hạn yêu cầu bảo hiểm và chống lại sự nhàm chán và tình yêu. Anh ta háo hức muốn trở lại hành động, vì vậy khi nhận được một liên lạc bí ẩn ra lệnh cho anh ta đến một hòn đảo xa xôi để thực hiện một nhiệm vụ tối mật, anh ta đã không nghĩ hai lần.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2004, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Craig T. Nelson","avatar":""},{"name":"Holly Hunter","avatar":""},{"name":"Sarah Vowell","avatar":""},{"name":"Spencer Fox","avatar":""},{"name":"Jason Lee","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Elizabeth Peña","avatar":""},{"name":"Eli Fucile","avatar":""},{"name":"Maeve Andrews","avatar":""},{"name":"Brad Bird","avatar":""},{"name":"Dominique Louis","avatar":""},{"name":"Teddy Newton","avatar":""},{"name":"Jean Sincere","avatar":""},{"name":"Wallace Shawn","avatar":""},{"name":"Lou Romano","avatar":""},{"name":"Wayne Canney","avatar":""},{"name":"Michael Bird","avatar":""},{"name":"Bud Luckey","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Hum Hain Lajawaab","Os Incríveis Os Super Heróis","超人总动员","Super oila","Fenomenalnite","Oi Apíthanoi","Les Incroyable","Os Incríveis: Os Super Heróis","სუპერ ოჯახი","Los Increibles","Mr.インクレディブル","超人特攻隊","Gia Đình Siêu Nhân","Supersimeyka","Supersemeyka","Nevijeni","The Incredibles","The Incredibles 1","Суперсямейка"]', 1784690324527);
