INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-sieu-nhan', 'Gia Đình Siêu Nhân', 'The Incredibles', 'gia đình siêu nhân the incredibles craig t. nelson holly hunter sarah vowell spencer fox jason lee samuel l. jackson elizabeth peña eli fucile maeve andrews brad bird dominique louis teddy newton jean sincere wallace shawn lou romano wayne canney michael bird bud luckey b hum hain lajawaab os incríveis os super heróis 超人总动员 super oila fenomenalnite oi apíthanoi les incroyable os incríveis: os super heróis სუპერ ოჯახი los increibles mr.インクレディブル 超人特攻隊 gia đình siêu nhân supersimeyka supersemeyka nevijeni the incredibles the incredibles 1 суперсямейка', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-sam-set', 'Siêu Nhân Sấm Sét', 'Power Rangers Dino Thunder', 'https://phimimg.com/upload/vod/20250320-1/85a8db151e39332849f6a8d183d3f831.jpg', 'https://phimimg.com/upload/vod/20250320-1/26eaee19ce62e49b2e708af2b5e7f1cf.jpg', '<p>Một sự cố đã gây ra vụ nổ ở một phòng thí nghiệm, xuất hiện một sinh vật nửa người nửa khủng long Mesogog. Tommy Oliver đã kịp thời chạy thoát. Nhiều năm sau, anh đến giảng dạy ở trường Reefside High, California với tư cách là một tiến sĩ. Trong một lần đến thăm bảo tàng trưng bày hóa thạch khủng long, anh đã mang theo 3 học sinh bị kỷ luật là Conner, Ethan và Kira. 3 học sinh này vô tình tìm được căn cứ bí mật của Tommy và 3 viên đá là màu đỏ, xanh, vàng. Conner nhặt viên màu đỏ, Ethan nhặt viên màu xanh, Kira nhặt viên màu vàng, sức mạnh của 3 viên đá sau đó đã ăn sâu vào trong 3 người. Biết rằng sức mạnh của ba viên đá không thể thoát ra khỏi cơ thể học trò mình, Tommy đã tiết lộ cho họ về những viên đá và sức mạnh siêu nhân. 3 người dưới sự huấn luyện của thầy giáo, trở thành những siêu nhân với sứ mệnh bảo vệ Trái Đất khỏi âm mưu đưa Trái Đất về với thời tiền sử. Đội sau đó có thêm sự giúp đỡ của Tommy khi anh trở lại làm siêu nhân và Trent Fernandez. Cuối cùng, 5 siêu nhân cũng đã làm được điều này, nhưng đổi lại họ mất hết Zord và sức mạnh siêu nhân của mình. Phim kết thúc với cảnh các nhân vật đến dự dạ hội của trường.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 13, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Power Rangers: Zeo","Power Rangers: Turbo","Power Rangers: Tempestade Ninja","Power Rangers: Galáxia Perdida","Power Rangers: Dino Trovão","Power Rangers: Força do Tempo","Power Rangers: No Espaço","Power Rangers: SPD","Power Rangers: Força Animal","Power Rangers: O Resgate","Power Rangers: Super Megaforce","Power Rangers: Aço Ninja","Power Rangers: Dino Charge","Power Rangers: RPM","Power Rangers: Megaforce","Power Rangers: Super Aço Ninja","Power Rangers: Operação Ultraveloz","Power Rangers: Samurai","Power Rangers: Super Samurai","Power Rangers: Dino Supercharge","Power Rangers: Fúria Cósmica","Power Rangers: Força Mística","Power Rangers: Fúria da Selva","超凡战队","恐龙战队","Πάουερ Ρειντζερς","파워 레인저","파워레인저","파워레인저 와일드포스","Mighty Morphin Power Rangers","Power Rangers Time Force","Power Rangers Dino Charge","Power Rangers Ninja Steel","Power Rangers Wild Force","Power Rangers Megaforce","Power Rangers Lightspeed Rescue","Power Rangers In Space","Power Rangers Beast Morphers","Power Rangers RPM","Power Rangers Super Samurai","Power Rangers Ninja Storm","Power Rangers Mystic Force","Power Rangers Jungle Fury","Power Rangers Samurai","Mighty Morphin Alien Rangers","Power Rangers Operation Overdrive","Power Rangers Dino Fury","Power Rangers Turbo","Power Rangers Zeo","Power Rangers Lost Galaxy","Power Rangers Dino Thunder","Power Rangers Super Ninja Steel","Power Rangers S.P.D.","Power Rangers Super Megaforce","Power Rangers Dino Super Charge","Power Rangers Cosmic Fury","Power Rangers"]', 1784690324527);
