INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-quai-di', 'Bác Sĩ Quái Dị', 'Black Jack', 'https://phimimg.com/upload/vod/20250316-1/cd3f3aa529bf69f921d40f9cb04369a0.jpg', 'https://phimimg.com/upload/vod/20250316-1/4e6d992e885500e0c4c2b70327825b8a.jpg', '<p>Tên thật của bác sĩ Black Jack là Hazama Kuuro, Mồ côi mẹ từ nhỏ và là người sống sót duy nhât sau tai nạn thảm khốc. Để trả thù cho những kể đã hại chết mẹ anh, Black Jack đi khắp nơi để tìm kiếm tung tích của chúng, Anh là một bác sĩ thiên tài có thể chữa mọi căn bệnh hiểm nghèo và những ca mổ bất thường mà không ai dám thực hiện. Tuy Nhiên Black Jack không có giấy phép hành nghề, Bị Đồng nghiệp gọi là đồ lang băm hay bác sĩ giết người. Bởi Anh là một người có khuôn mặt đánh sợ, mang vết sẹo dài. Black Jack thường hét giá rất cao khi chữa bệnh cho bất kỳ ai, đôi khi anh lại làm không công. Mặc dù bị người đời khinh miệt, coi như là một kẻ giết người nhưng anh vẫn là một vị bác sĩ giàu lòng trắc ẩn, Có thể cứu chữa người khác.</p>', 'Hoàn Tất (80/80)', 80, 'hoathinh', 'completed', 14, 2004, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akio Otsuka","avatar":""},{"name":"Yuko Mizutani","avatar":""},{"name":"Mako Hyodo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Black Jack","怪医黑杰克21","ブラック・ジャック 21","블랙 잭","블랙잭","Black Jack (TV)","Bác Sĩ Quái Dị 21","ブラック・ジャック"]', 1784690324527);
