INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-linh-ky-hieu-lam-phan-3', 'Bản Lĩnh Kỷ Hiểu Lam (Phần 3)', 'The Bronze Teeth (Season 3)', 'bản lĩnh kỷ hiểu lam (phần 3) the bronze teeth (season 3) trương quốc lập vương cương trương thiết lâm viên lập dương thiên hoa the eloquent ji xiaolan the bronze teeth 철치동아 기효람 bản lĩnh kỷ hiểu lam 铁齿铜牙纪晓岚', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-trong-nha-hat', 'Bóng Ma Trong Nhà Hát', 'The Phantom of the Opera', 'https://phimimg.com/upload/vod/20250308-1/6d2b29b71913f8e6a5da4da6d83de956.jpg', 'https://phimimg.com/upload/vod/20250308-1/73fdddc93c2b1ea9410e29296079466b.jpg', '<p>Cô gái xinh đẹp bé nhỏ Christine tham gia trong một đoàn ca kịch trong nhà hát. Do tính đóng đảnh của cô ca sĩ chính, một lần Christine được trở thành người hát solo trong cả vở diễn và được khán giả đón nhận nồng nhiệt.Christine (Emmy Rossum) luôn linh cảm có một người hộ mệnh nào đó luôn ở bên mình, truyền cảm cho giọng hát của mình và bảo vệ nàng trước tất cả những ai muốn hại nàng. Một đêm nọ, sau những tràng pháo tay hâm mộ, ngập tràn trong cả rừng hoa chúc mừng, Christine nhận được một bông hồng. Rồi như mơ, như thực, nàng được một người đàn ông đeo mặt nạ (Gerard Butler) dẫn sâu vào tầng hầm nhà hát, đi đến xứ sở kỳ lạ của anh ta. Nơi đó, nàng được trân trọng như một nàng công chúa. Nhưng người đàn ông nhất ...</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Emmy Rossum","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Miranda Richardson","avatar":""},{"name":"Minnie Driver","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Simon Callow","avatar":""},{"name":"Victor McGuire","avatar":""},{"name":"Jennifer Ellison","avatar":""},{"name":"Murray Melvin","avatar":""},{"name":"Kevin McNally","avatar":""},{"name":"James Fleet","avatar":""},{"name":"Imogen Bain","avatar":""},{"name":"Miles Western","avatar":""},{"name":"Judith Paris","avatar":""},{"name":"Halcro Johnston","avatar":""},{"name":"Paul Brooke","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["El fantasma de la ópera de Andrew Lloyd Webber","El Fantasma de la Ópera","Musical - The Phantom Of The Opera","פנטום האופרה","Andrew Lloyd Webber''s Das Phantom der Oper","Andrew Lloyd Webber''s The Phantom of the Opera","歌劇魅影(2004)","安德魯洛伊韋伯之歌劇魅影","The Phantom of the Opera"]', 1784690324527);
