INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-tinh-yeu-2004', 'Nhật Ký Tình Yêu', 'The Notebook', 'https://phimimg.com/upload/vod/20250203-1/57b5be791f5ed0a2defba822013bba6e.jpg', 'https://phimimg.com/upload/vod/20250203-1/1805d317cc678f6f785536eb176479d9.jpg', '<p>Dựa trên cuốn tiểu thuyết của nhà văn Nicholas Sparks xuất bản năm 1996, bộ phim là câu chuyện tình giữa Noah (Ryan Gosling) và Allie (Rachel McAdams) kể từ lần đầu họ gặp nhau tại North Carolina vào thập niên 40. Như mọi mối tình ngang trái khác, tình cảm giữa Noah và Allie gặp phải rào cản, xa cách trong nhiều năm liền trước khi đoàn tụ mãi mãi về sau.</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Gosling","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Gena Rowlands","avatar":""},{"name":"James Garner","avatar":""},{"name":"Joan Allen","avatar":""},{"name":"David Thornton","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Kevin Connolly","avatar":""},{"name":"Sam Shepard","avatar":""},{"name":"Starletta DuPois","avatar":""},{"name":"Ed Grady","avatar":""},{"name":"Jennifer Echols","avatar":""},{"name":"Heather Wahlquist","avatar":""},{"name":"Cullen Moss","avatar":""},{"name":"Thunderbird Dinwiddie","avatar":""},{"name":"James Middleton","avatar":""},{"name":"Peter R","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Diario de una pasión","深情日记","写我情真","N''Oublie Jamais","El Diario de Noa","Užrašų knygutė","Diario de una Pasion","Тетрадката","Το Ημερολόγιο","きみに読む物語","Dnevnik pamjati","노트북","Dagboken - Jag sökte dig och fann mitt hjärta","手札情緣","The Notebook"]', 1784690324527);
