INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diep-vien-sieu-hang-phan-3', 'Điệp Viên Siêu Hạng (Phần 3)', 'Totally Spies! (Season 3)', 'điệp viên siêu hạng (phần 3) totally spies! (season 3) jennifer hale andrea baker katie griffin claire guyot fily keita céline mauge jean-claude donda ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-loi-anh-yeu-em', 'Xin Lỗi, Anh Yêu Em', 'Sorry, I Love You', 'https://phimimg.com/upload/vod/20241209-1/ac79dbc7b2bc7aaa0a52b9e82839557e.jpg', 'https://phimimg.com/upload/vod/20241209-1/d7c89654a23c64d3fff2c191d1edb735.jpg', '<p>Bộ phim là một câu chuyện tình yêu đầy nước mắt và bi kịch giữa Cha Moo Hyuk và Song Eun Chae. Cha Moo Hyuk được nhận nuôi ở Úc nhưng bị ngược đãi và sớm bỏ nhà ra đi từ nhỏ. Một ngày, Moo Hyuk gặp gỡ Song Eun Chae, người làm việc cho Choi Yoon, một ca sĩ nổi tiếng ở Hàn Quốc, cũng là người Eun Chae thầm yêu. Cuộc gặp gỡ định mệnh với Moo Hyuk đã thay đổi không chỉ cuộc sống của cô mà còn đối với cuộc sống của Choi Yoon. Bởi vì một tai nạn liên quan đến người bạn gái cũ, trong đầu Moo Hyuk còn để lại một mảnh đạn và anh chỉ còn 3 tháng để sống. Điều này khiến cho anh quay trở lại Hàn Quốc để tìm mẹ ruột của mình. Càng tìm hiểu, trái tim Moo Hyuk càng thay đổi, muốn trả thù người đã bỏ rơi mình. Mặc dù sự tăm tối luôn vây quanh Moo Hyuk, anh lại tìm được một người sự hạnh phúc không ngờ tới từ một người mà anh vốn dĩ không nên yêu.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 13, 2004, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lim Soo-jung","avatar":""},{"name":"So Ji-sub","avatar":""},{"name":"Jung Kyung-ho","avatar":""},{"name":"Choi Yeo-jin","avatar":""},{"name":"Seo Ji-young","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Kim Hye-ok","avatar":""},{"name":"Lee Hye-young","avatar":""},{"name":"Lee Yeong-ha","avatar":""},{"name":"Shin Goo","avatar":""},{"name":"Park Gun-tae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["对不起，我爱你","ขอโทษครับ ผมรักคุณ","I''m Sorry I Love You","Sorry I Love You","Im Sorry I Love You","Sorry, I Love You","Xin lỗi, anh yêu em","미안하다, 사랑한다"]', 1784690324527);
