INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-nang-lam-chieu', 'Những Cô Nàng Lắm Chiêu', 'Mean Girls', 'https://phimimg.com/upload/vod/20241114-1/4094ea6b1cf7f59a9059b6019d14fa15.jpg', 'https://phimimg.com/upload/vod/20241114-1/ea714f01c4def3e61e23fc97230876cb.jpg', '<p>Sau khoảng thời gian học tại gia ở nước ngoài, nữ sinh mới Cady có khóa học cấp tốc về cuộc sống ở trường cấp 3 khi một nhóm nữ sinh nổi tiếng mời cô nhập hội.</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lindsay Lohan","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Lizzy Caplan","avatar":""},{"name":"Lacey Chabert","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Daniel Franzese","avatar":""},{"name":"Jonathan Bennett","avatar":""},{"name":"Rajiv Surendra","avatar":""},{"name":"Tina Fey","avatar":""},{"name":"Tim Meadows","avatar":""},{"name":"Ana Gasteyer","avatar":""},{"name":"Neil Flynn","avatar":""},{"name":"Amy Poehler","avatar":""},{"name":"Dwayne Hill","avatar":""},{"name":"Diego Klattenhoff","avatar":""},{"name":"Molly Shanahan","avatar":""},{"name":"Elana Shilling","avatar":""},{"name":"G","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Naujokė","Зіпсовані дівчиська","퀸카로 살아남는 법","Погані дівчиська","Ta Kaka Koritsia","Τα Κακά Κορίτσια","Lolita Malgré Moi","Pis Qızlar","ミーン・ガールズ","Julmad Tüdrukud","Mean Girls - Tylyt Tytöt","Դատարկ Աղջիկները","Méchantes Ados","贱女孩","Chicas pesadas","Meninas Malvadas","Giras e Terríveis","Гадни момичета","Опасне девојке","Круті дівчата","Жаман қыздар","Yaramaz qızlar","Girls Club – Vorsicht bissig!","Õelad tüdrukud","Opasne djevojke"