INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-co-nang-lam-chieu', 'Những Cô Nàng Lắm Chiêu', 'Mean Girls', 'những cô nàng lắm chiêu mean girls lindsay lohan rachel mcadams lizzy caplan lacey chabert amanda seyfried daniel franzese jonathan bennett rajiv surendra tina fey tim meadows ana gasteyer neil flynn amy poehler dwayne hill diego klattenhoff molly shanahan elana shilling g naujokė зіпсовані дівчиська 퀸카로 살아남는 법 погані дівчиська ta kaka koritsia τα κακά κορίτσια lolita malgré moi pis qızlar ミーン・ガールズ julmad tüdrukud mean girls - tylyt tytöt դատարկ աղջիկները méchantes ados 贱女孩 chicas pesadas meninas malvadas giras e terríveis гадни момичета опасне девојке круті дівчата жаман қыздар yaramaz qızlar girls club – vorsicht bissig! õelad tüdrukud opasne djevojke nekrietneles bajos csajok wredne dziewczyny fete rele kötü kızlar protivný sprostý holky ստոր աղջիկները مین گرلز فتيات لئيمات دختران بدجنس ילדות רעות cô gái lắm chiêu มีนเกิลส์ ก๊วนสาวซ่าส์วีนซะไม่มี mean girls', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-sopranos-phan-5', 'Gia Đình Sopranos (Phần 5)', 'The Sopranos (Season 5)', 'https://phimimg.com/upload/vod/20241105-1/bbade4b974d56ad71d8f6c6bf728e62d.jpg', 'https://phimimg.com/upload/vod/20241105-1/8367c667a58c9f38492747dcca933d84.jpg', '<p>Trong phần năm, Tony và Carmela ly thân đàm phán các vấn đề về gia đình và tiền bạc. Trong khi đó, cuộc hội ngộ của Tony với người anh họ được ân xá Tony Blundetto có thể gây nguy hiểm cho liên minh của anh với Johnny Sack; và Adriana tham gia sâu hơn với Feds.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 14, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Gandolfini","avatar":""},{"name":"Edie Falco","avatar":""},{"name":"Jamie-Lynn Sigler","avatar":""},{"name":"Robert Iler","avatar":""},{"name":"Lorraine Bracco","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Steven Van Zandt","avatar":""},{"name":"Tony Sirico","avatar":""},{"name":"Dominic Chianese","avatar":""},{"name":"Aida Turturro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Família Soprano","人在江湖","Rodina Sopránů","آل سوبرانو","סופרנוס","द सोप्रानोस","سوپرانو","خانواده سوپرانو","سوپرانوز","Rodzina Soprano","Семья Сопрано","Клан Сопрано","The Sopranos"]', 1784690324528);
