INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-sopranos-phan-5', 'Gia Đình Sopranos (Phần 5)', 'The Sopranos (Season 5)', 'gia đình sopranos (phần 5) the sopranos (season 5) james gandolfini edie falco jamie-lynn sigler robert iler lorraine bracco michael imperioli steven van zandt tony sirico dominic chianese aida turturro família soprano 人在江湖 rodina sopránů آل سوبرانو סופרנוס द सोप्रानोस سوپرانو خانواده سوپرانو سوپرانوز rodzina soprano семья сопрано клан сопрано the sopranos', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('han-so-kieu-hung', 'Hán Sở Kiêu Hùng', 'The Conqueror''s Story', 'https://phimimg.com/upload/vod/20241028-1/96643ac9a18e139444de1c28536f3b18.jpg', 'https://phimimg.com/upload/vod/20241028-1/708a2a12f35f7eea11e0cb33f5b4bc93.jpg', '<p>Vào thời nhà Tần, quần hùng vì muốn phản Tần xưng bá, nên ra sức tranh giành thế lực, trong đó có Hạng Võ và Lưu Bang. Dưới trướng Hạng Võ có Phạm Tăng, Anh Bố, Hạng Lương và Hạng Trang, họ đều lần lượt bỏ đi vì không chấp nhận được tính bảo thủ cố chấp của ông. Lưu bang thì được các tướng Hàn Tín, Trương Lương, Trần Bình, Tiêu Hà và Phàn Khoái hết lòng tận tụy. Lữ Trí là vợ của Lưu Bang vốn là một người có chí lớn nhưng nữ nhi nân đành cam phận cho đến khi nàng gặp được Lưu Bang. Người yêu của Hạng Võ là Ngu Cơ, nàng là người vô cùng xinh đẹp, nhưng chính Ngu Cơ lại là mối hiểm họa về sau cho Hạng Võ...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 19, 2004, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"鄭少秋","avatar":""},{"name":"江華","avatar":""},{"name":"Maggie Cheung Hoh-Yee","avatar":""},{"name":"吳美珩","avatar":""},{"name":"黎耀祥","avatar":""},{"name":"Ram Chiang","avatar":""},{"name":"Law Lok-Lam","avatar":""},{"name":"Brian Wong","avatar":""},{"name":"王俊棠","avatar":""},{"name":"Kong Hon","avatar":""},{"name":"Chen Hung-Lieh","avatar":""},{"name":"艾威","avatar":""},{"name":"魯振順","avatar":""},{"name":"余子明","avatar":""},{"name":"Timothy Cheng Chi-Sing","avatar":""},{"name":"敖嘉年","avatar":""},{"name":"羅君左","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["楚漢驕雄"]', 