INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('han-so-kieu-hung', 'Hán Sở Kiêu Hùng', 'The Conqueror''s Story', 'hán sở kiêu hùng the conqueror''s story 鄭少秋 江華 maggie cheung hoh-yee 吳美珩 黎耀祥 ram chiang law lok-lam brian wong 王俊棠 kong hon chen hung-lieh 艾威 魯振順 余子明 timothy cheng chi-sing 敖嘉年 羅君左 楚漢驕雄', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-robot', 'Tôi, Robot', 'I, Robot', 'https://phimimg.com/upload/vod/20241028-1/ccb4bed448750d727e95eedbbbb4f1bf.jpg', 'https://phimimg.com/upload/vod/20241028-1/fb11486fa97f61133bd90f35450de3a1.jpg', '<p>Thời tương lai năm 2035, khi mà con người chế tạo ra rô-bốt để làm tất cả các công việc nặng nhọc thay mình. Nhưng khi một loại rô-bốt mới được chế tạo và phản lại loài người... chuyện gì sẽ xảy ra?</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Bridget Moynahan","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Bruce Greenwood","avatar":""},{"name":"Shia LaBeouf","avatar":""},{"name":"Chi McBride","avatar":""},{"name":"Jerry Wasserman","avatar":""},{"name":"Peter Shinkoda","avatar":""},{"name":"Terry Chen","avatar":""},{"name":"David Haysom","avatar":""},{"name":"Scott Heindl","avatar":""},{"name":"Adrian Ricard","avatar":""},{"name":"Fiona Hogan","avatar":""},{"name":"Sharon Wilkins","avatar":""},{"name":"Craig March","avatar":""},{"name":"Darren Moore","avatar":""},{"name":"Emily Ten","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["智能叛变","我，机器人","Ja, robot","I, Robot - 3D","Yo, robot","机械公敌","Az, robotŭt","Egó, to Rompót","YA, robot","YA, Robot","I,Robot","I Robot","智能叛變","Mən, Robot","I, Robot"]', 1784690324528);
