INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-ha-vo-tac', 'Thiên Hạ Vô Tặc', 'A World Without Thieves', 'https://phimimg.com/upload/vod/20240102-1/e9b81a2d5b1a0ef7b15335280ef58c25.jpg', 'https://phimimg.com/upload/vod/20240102-1/15c3bc8f90c66280df6827b38fb244e4.jpg', '<p>Tuyệt phẩm tinh tế hiếm có do Lưu Đức Hoa và Lưu Nhược Anh thủ vai khắc họa lại những mánh khóe lừa bịp vô cùng tinh vi khiến khán giả rối mắt. Thánh lừa bịp vì tình yêu mà quay đầu là bờ mang lại cho khán giả những câu chuyện sâu sắc cảm động.</p>', 'Full', 1, 'single', 'completed', 22, 2004, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Lý Băng Băng","avatar":""},{"name":"Vương Bảo Cường","avatar":""},{"name":"Cát Ưu","avatar":""},{"name":"Lưu Nhược Anh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324528);
