INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-quyen-anh', 'Cô Nàng Quyền Anh', 'A Girl Boxer', 'https://phimimg.com/upload/vod/20231108-1/d8eeed28aab872d852f4237f50ccd14c.jpg', 'https://phimimg.com/upload/vod/20231108-1/d2b0ff9a5af7c9eb52a78b34a0247aec.jpg', '<p>Bộ phim Cô Nàng Quyền Anh - A Girl Boxer kể về câu chuyện một võ đài quyền anh trở thành nơi chiến đấu của tình yêu và sự giằng xé giữa tình yêu và tình thân. Tin Ha và Kin Fung sắp đính hôn, nhưng để thành hiện thực, Kin phải đánh bại cha cô, một võ sĩ quyền anh huyền thoại, trong một trận đấu quyền anh.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"Hanabi Kim","avatar":""},{"name":"Marco Ngai Chun-Git","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Anita Wong Yi-Yi","avatar":""},{"name":"Joey Leung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324528);
