INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-phong-2046', 'Căn Phòng 2046', '2046', 'https://phimimg.com/upload/vod/20240724-1/606369b9ba8f0c519a519c0fe5ab9acd.jpg', 'https://phimimg.com/upload/vod/20240724-1/bb93b365761a3a72c37a31fd29d6478a.jpg', '<p>Năm 1966, Châu từ Singapore trở lại Hồng Kông. Anh viết bài cho một tờ báo để kiếm sống. Buổi tối Giáng Sinh 24 tháng 12 năm 1966, Châu gặp lại một người bạn cũ - Lulu, trong một hộp đêm. Lulu uống quá say và Châu đưa cô ta về nhà, căn phòng cô trọ số 2046. Hôm sau khi Châu trở lại khách sạn để trả chìa khóa thì ông chủ nói rằng không có ai tên Lulu ở đó. Châu quyết định trọ lại khách sạn và lấy căn phòng 2047. Anh biết rằng hôm trước người bạn trai của Lulu đã giết cô ta trong phòng 2046 vì ghen tuông.</p>', 'Full', 1, 'single', 'completed', 26, 2004, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"梁朝偉","avatar":""},{"name":"Gong Li","avatar":""},{"name":"Faye Wong","avatar":""},{"name":"木村拓哉","avatar":""},{"name":"Zhang Ziyi","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"張震","avatar":""},{"name":"董潔","avatar":""},{"name":"張曼玉","avatar":""},{"name":"Thongchai McIntyre","avatar":""},{"name":"Wang Sum","avatar":""},{"name":"Siu Ping-lam","avatar":""},{"name":"康華","avatar":""},{"name":"Farini Cheung Yui-Ling","avatar":""},{"name":"Sabrina Cheung","avatar":""},{"name":"Jiang Xinyu","avatar":""},{"name":"江道海","avatar":""},{"name":"Alice Lee","avatar":""},{"name":"Siu Ming Lee","avatar":""},{"name":"Fei-lin Miao","avatar":""},{"name":"吳廷燁","avatar":""},{"name":"Ben Yuen Foo-Wah","avatar":""},{"name":"程小龍","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324528);
