INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('can-phong-2046', 'Căn Phòng 2046', '2046', 'căn phòng 2046 2046 梁朝偉 gong li faye wong 木村拓哉 zhang ziyi carina lau 張震 董潔 張曼玉 thongchai mcintyre wang sum siu ping-lam 康華 farini cheung yui-ling sabrina cheung jiang xinyu 江道海 alice lee siu ming lee fei-lin miao 吳廷燁 ben yuen foo-wah 程小龍 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trom-long-trao-phung-2', 'Trộm Long Tráo Phụng 2', 'Empress Enters Place', 'https://phimimg.com/upload/vod/20240628-1/49f61f90d965b70126c4c3f7992ef55b.jpg', 'https://phimimg.com/upload/vod/20240628-1/e776c6f29228291b1d8fa5e8b5b1baab.jpg', '<p><em>Hoàng Đế Cháng Khang phong Thiên Thiên làm Hoàng hậu, trong ngày sắc phong giữa đường bị nhóm thích khách xuất hiện có ý đồ giết Hoàng hậu, nhưng sau đó mọi người phát hiện đó không phải là Hoàng hậu thiên Thiên chỉ là 1 cung nữ. Đại đô đốc Thù Vũ tay nắm binh quyền nhưng không thỏa mãn, có ý định đưa con gái là Mộng Mộng lên làm Hoàng hậu, chính Thù Vũ đã nhiều lần có ý định ám sát Thiên thiên, nhưng trái ngược Mộng Mộng là 1 người con gái ngoan ngoãn. Thiên Thiên tới Dương Châu mở học viện dạy cho những tên lưu manh, đầu trộm đuôi cướp, ngay cả những kỹ nữ cũng trở thành học sinh. Chánh Khang kiếm tới Dương Châu, khuyên Thi.</em></p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 12, 2004, 'Lồng Tiếng', 'HD', 'Đài Loan', 0, '[{"name":"Trương Đình","avatar":""},{"name":"Ngô Đại Duy","avatar":""},{"name":"Ngô Mạnh Đạt","avatar":""},{"name":"Ngưu Lợi","avatar":""},{"name":"Tống Đan Đan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
