INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-tieu-phan-3-kieu-nu-tuyet-tran', 'Bảo Tiêu (Phần 3) -  Kiều Nữ Tuyệt Trần', 'Bodyguards: Heavenly Charm', 'https://phimimg.com/upload/vod/20240627-1/2435f1c4f75b2cc6fc192bdc1f9ab491.jpg', 'https://phimimg.com/upload/vod/20240627-1/38e04da98200e787a42a0aa34dc359bc.jpg', '<p><em>Tiếp đà thành công của 2 phần trước, tựa phim kiếm hiệp nổi tiếng của đài ATV với sự tham gia của Triển hộ vệ Hà Gia Kính mang tên Bảo Tiêu tiếp tục cho ra mắt phần 3 vào năm 1998, đây cũng là phần cuối cùng trong seri đình đám này và nó được lấy tên là Kiều Nữ Giang Hồ. Với sự đầu tư mạnh mẽ cả về cảnh quay, cốt truyện, dàn diễn viên cho tới những trận thư hùng đầy ác liệt và mãn nhãn, Bảo Tiêu 3 là một cái kết đầy hoàn hảo cho loạt phim kiếm hiệp được biết tới trên khắp châu Á này.</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 20, 2004, 'Lồng Tiếng', 'HD', 'Đài Loan', 0, '[{"name":"Hà Gia Kính","avatar":""},{"name":"Lưu Ngọc Đình","avatar":""},{"name":"Hứa Tịnh","avatar":""},{"name":"Huỳnh Văn Hào","avatar":""},{"name":"Cố Quán Trung","avatar":""},{"name":"Trần Hồng Liệt","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324528);
