INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-8-nha-ao-thuat-voi-doi-canh-bac', 'Thám Tử Lừng Danh Conan 8: Nhà Ảo Thuật Với Đôi Cánh Bạc', 'Detective Conan: Magician of the Silver Sky', 'https://phimimg.com/upload/vod/20231019-1/300115f6f253046d3d8a3e90144d766d.jpg', 'https://phimimg.com/upload/vod/20231019-1/9c3fba845947edd2e1caaa9fa5e57964.jpg', '<p>Trong lần phá án này, nhiệm vụ của Conan là bảo vệ &quot;Viên Đá Định Mệnh&quot; trước lời thách thức của siêu trộm Kid. Trong buổi công diễn vở kịch cuối cùng, hắn hóa thân thành Shinichi và thản nhiên tới gần Ran. Mải tập trung vào mục đích chính, Conan bị mắc bẫy khi bị hắn đánh lạc hướng. Bởi Kid sẽ thực sự hành động trên chuyến bay của cô Juri tới Hakodate... Thảm họa xảy ra trên máy bay khi một hung thủ âm mưu giết cô Juri xuất hiện. Liệu mọi người có sống sót khi cả hai phi công bị nhiễm độc, máy bay đang rơi tự do? Conan có bắt được siêu trộm Kid và giao nộp hắn cho cảnh sát hay không?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2004, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Hidekatsu Shibata","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Gara Takashima","avatar":""},{"name":"Keiko Toda","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Daiki Nakamura","avatar":""},{"name":"Katsuji Mori","avatar":""},{"name":"Kyoko Hikami","avatar":""},{"name":"Masashi Sugawara","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
