INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bup-be-hinh-nhan', 'Búp Bê Hình Nhân', 'The Doll Master', 'https://phimimg.com/upload/vod/20240726-1/34f217302970fe3825b8a295a3350cd9.jpg', 'https://phimimg.com/upload/vod/20240726-1/073c1ad28afabee5f722a91b494151ef.jpg', '<p>Chuyện phim Búp bê hình nhân bắt đầu khi nhà điêu khắc Hae Mi (Kim Yoo Mi) cùng với bốn người khác được mời đến một bảo tàng biệt lập để làm mẫu cho những hình nhân mới được tạo ra dựa trên hình ảnh của họ. Cả năm người được chào đón rất nhiệt tình. Thế nhưng, ngay sau đó, Hae Mi bắt đầu phát hiện những điều bất thường trong khuôn viên bảo tàng. Mọi chuyện càng căng thẳng tột độ khi một người trong nhóm bị treo cổ. Dần dần, những người khác cũng bị sát hại. Tất cả những gì xảy ra không dễ dàng giải quyết như Hae Mi nghĩ. Cô cũng phát hiện ra những hình nhân không chỉ đơn giản là hình nhân và những bí ẩn kinh hoàng dần lộ diện.</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"임은경","avatar":""},{"name":"김유미","avatar":""},{"name":"심형탁","avatar":""},{"name":"Ok Ji-young","avatar":""},{"name":"임형준","avatar":""},{"name":"Lee Ka-yeong","avatar":""},{"name":"천호진","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324528);
