INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bup-be-hinh-nhan', 'Búp Bê Hình Nhân', 'The Doll Master', 'búp bê hình nhân the doll master 임은경 김유미 심형탁 ok ji-young 임형준 lee ka-yeong 천호진 ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-tien-tu-bao', 'Ngự Tiền Tứ Bảo', 'Imperial Four Treasures', 'https://phimimg.com/upload/vod/20240724-1/95b6a91e0d4c53a38ecb7d13404c922f.jpg', 'https://phimimg.com/upload/vod/20240724-1/d291ffd7d67efb094d674bc49715f5fe.jpg', '<p><em>Triệu Văn Trác, một trong những ngôi sao võ thuật hàng đầu của làng điện ảnh hoa ngữ. Anh được khán giả Việt biết đến từ bộ phim truyền hình Phong Vân với vai Nhiếp Phong. Ngoài ra, anh còn tham gia hàng loạt dự án đình điện ảnh đám như: Tô Khất Nhi, Chiến Lang hay Tân Bạch Phát Ma nữ,…Không chỉ vậy, Triệu Văn Trác còn rất tích cực tham gia các bộ phim truyền hình, với nhiều thể loại khác nhau, nhưng đa số là phim võ thuật. Ngự Tiền Tứ Bảo là một trong số ít những bộ phim không thuộc thể loại võ thuật do anh tham gia. Phim có tựa đề tiếng anh là Imperial First Four Treasures, do đạo diễn kỳ cựu Hoàng Tổ Quyền chỉ đạo nội dung, với sự tham gia của nhiều diễn viên nổi tiếng như: Triệu Văn Trác, Lưu Nghi Vĩ, Lô Tinh Vũ,…phim thuộc thể loại cổ trang hài hước, được phát sóng lần đầu tiên vào năm 2004. Nội dung phim xoay quanh câu chuyện hài hước của 4 người được mệnh danh là ngự tiền tứ bảo của vua Khang Hy. Trong 4 người này có 2 người có thân phận là ăn mày nhưng được Quái Tăng (chính là cha của vua Khang Hy) điểm hóa thành 2 đại thần quan trọng trong triều đình. Hai người còn lại là Nạp Lan Dung Nhược và Thi Sĩ Luân, cả 4 người đều là đại thần thân cận bên cạnh vua. Không chỉ là những cánh tay đắc lực của Khang Hy, họ còn là những người được nhân dân yêu quý bậc nhất. Tuy rằng, tính cách mỗi người một kiểu, suốt ngày cãi cự và xung đột nhau nhưng khi có việc quan trọng thì họ không ngừng giúp đỡ lẫn nhau. Sau cùng, 4 người cùng nhau loại bỏ những tên gian thần trong triều, đồng thời ra sức cải thiện cuộc sống cho nhân dân.</em></p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 21, 2004, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Triệu Văn Trác","avatar":""},{"name":"Lưu Nghi Vĩ","avatar":""},{"name":"Lô Tinh Vũ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324528);
