INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-tung-hiep-anh', 'Bình Tung Hiệp Ảnh', 'Heroic Legend', 'https://phimimg.com/upload/vod/20240719-1/e198da13cbc456069e238d516949f146.jpg', 'https://phimimg.com/upload/vod/20240719-1/114af1ef51e4bda9a1f14c814b836bf9.jpg', '<p>Chuyện kể về một vị sứ thần Đại Minh tên Vân Tĩnh, bị hữu thừa tướng nước Ngõa Trì Trương Tôn Châu bắt chăn dê 20 năm ở quan ngoại. Khi được trở về, ông lại bị triều đình nghi là phản thần và ép tự vẫn. Cháu gái ông Vân Lỗi được Cửu Thiên Huyền Nữ Diệp Doanh Doanh thu làm đồ đệ, 10 năm sau quay lại Ngõa Trì tìm Trương Tôn Châu báo thù, không ngờ rơi vào ái tình với con trai Trương Tôn Châu là Trương Đan Phong. Đi cùng với đó tất nhiên là những âm mưu thâm hiểm chốn giang hồ, nhằm chiếm đoạt một kho báu rất lớn của Trương Sĩ Thành, tổ tiên Trương Đan Phong, để lại...</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 25, 2004, 'Lồng Tiếng', 'FullHD', 'Trung Quốc', 0, '[{"name":"Huang Haibing","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Sun Hao","avatar":""},{"name":"Han Xue","avatar":""},{"name":"Feifei Sun","avatar":""},{"name":"Sun Chenxi","avatar":""},{"name":"Zhang Jiayi","avatar":""},{"name":"Da Shichang","avatar":""},{"name":"Shen Junyi","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324528);
