INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ba-noi-tro-kieu-my-phan-1', 'Những Bà Nội Trợ Kiểu Mỹ (Phần 1)', 'Desperate Housewives (Season 1)', 'https://phimimg.com/upload/vod/20240618-1/f414adfa535eeb1172dbef6a2133574f.jpg', 'https://phimimg.com/upload/vod/20240618-1/5d01c0645b301be1872067986c16b0b7.jpg', '<p>Mary Alice Young, một bà nội trợ có vẻ hoàn hảo đã tự tử vì sợ rằng một bí mật đen tối liên quan đến cô, chồng cô và con trai họ sẽ bị bại lộ.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 12, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Teri Hatcher","avatar":""},{"name":"Felicity Huffman","avatar":""},{"name":"Marcia Cross","avatar":""},{"name":"Eva Longoria","avatar":""},{"name":"Ricardo Chavira","avatar":""},{"name":"Doug Savant","avatar":""},{"name":"James Denton","avatar":""},{"name":"Brenda Strong","avatar":""},{"name":"Vanessa Williams","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
