INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-keo-phan-2', 'Dao Kéo (Phần 2)', 'Nip/Tuck (Season 2)', 'https://phimimg.com/upload/vod/20240627-1/84679dce1512bc9125a7400b17144c53.jpg', 'https://phimimg.com/upload/vod/20240627-1/ae72732bdc297f0e80e72f385a1f3649.jpg', '<p>Hai bác sĩ phẫu thuật thẩm mỹ - một người đàn ông tận tụy với gia đình và một người là một tay chơi vô đạo đức - cố gắng duy trì công việc kinh doanh của mình trong khi phải vượt qua vô số khó khăn, từ cá nhân đến khách hàng có liên hệ tội phạm.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 11, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dylan Walsh","avatar":""},{"name":"Julian McMahon","avatar":""},{"name":"Joel Richardson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
