INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loai-ac-doc-3', 'Loài Ác Độc 3', 'Species III', 'https://phimimg.com/upload/vod/20240616-1/4f7ab82994e5eb920715c3d54e44d3b1.jpg', 'https://phimimg.com/upload/vod/20240616-1/52087c4a840d4a94560f06cb303e7e80.jpg', '<p>Phần tiếp theo của loạt phim kinh dị giả tưởng Species I và II về những người lai bởi ADN của con người và người ngoài hành tinh, những kẻ cực kỳ quyến rũ nhưng cũng cực kỳ độc ác với sức mạnh khủng khiếp. Ngoại trừ Sara, đứa con của Eve – cô nàng kiều diễm thích giết đàn ông trong phần II – có dòng máu thuần nhất, những kẻ nửa người nửa alien đều đang mắc phải một căn bệnh chết người. Sara được giáo sư Almond và chàng sinh viên Dean che chở trước sự truy lùng của quân đội, trong lúc này những kẻ mang ADN của alien khác cũng đang lùng sục cô, nhằm từ Sara tìm ra giải pháp chữa trị căn bệnh tai quái của chúng. Và cũng như các phần trước, những cô nàng nóng bỏng đi đến đâu, nơi đó sẽ xuất hiện vài cái xác của những ...</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robin Dunne","avatar":""},{"name":"Robert Knepper","avatar":""},{"name":"Sunny Mabrey","avatar":""},{"name":"Amelia Cooke","avatar":""},{"name":"Christopher Neame","avatar":""},{"name":"Patricia Bethune","avatar":""},{"name":"Michael Warren","avatar":""},{"name":"Natasha Henstridge","avatar":""},{"name":"John Paul Pitoc","avatar":""},{"name":"Joel Stoffer","avatar":""},{"name":"James Leo Ryan","avatar":""},{"name":"Savanna Fields","avatar":""},{"name":"Reed Frerichs","avatar":""},{"name":"Marc D. Wilson","avatar":""},{"name":"Matthew Yang King","avatar":""},{"name":"Rick Dean","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324528);
