INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-than', 'Hải Thần', 'Emperor Of The Sea', 'https://phimimg.com/upload/vod/20240229-1/eae8da29c00736e32d2e7469670d1e30.jpg', 'https://phimimg.com/upload/vod/20240229-1/33733ccd1cb4baf2924d97f0f3277d0e.jpg', '<p>Phim kể câu chuyện về một nhân vật có thật trong lịch sử: thương nhân Jang Bo Go (Choi Soo Jong đóng), người từ một kẻ làm thuê trên một chiếc tàu biển nhờ tài năng của mình mà trở thành nhà buôn tài giỏi, một sĩ quan hải quân cấp cao và được mệnh danh là Hải thần trên biển. Bộ phim là tác phẩm hiếm hoi của Hàn Quốc khai thác đề tài thương nhân đường thủy và được dàn dựng với quy mô hoành tráng và qui tụ dàn diễn viên hàng đầu như Choi Soo Jong, Song Il Gook,... Đây cũng là tác phẩm góp phần quan trọng làm nên tên tuổi cho nữ hoàng nước mắt Soo Ae.</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 15, 2004, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Il-gook","avatar":""},{"name":"Kim Kap-soo","avatar":""},{"name":"Park Young-kyu","avatar":""},{"name":"Chae Jung-an","avatar":""},{"name":"Choi Soo-jong","avatar":""},{"name":"Soo Ae","avatar":""},{"name":"Bae Soo-bin","avatar":""},{"name":"Kim A-joong","avatar":""},{"name":"Seo Do-young","avatar":""},{"name":"Baek Sung-hyun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
