INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-vo-si', 'Huyền Thoại Võ Sĩ', 'Fighter In The Wind', 'https://phimimg.com/upload/vod/20240228-1/be57cfce70d36ae879def6047e4da001.jpg', 'https://phimimg.com/upload/vod/20240228-1/4468d0ac99d6c0e88e251de60aabbafb.jpg', '<p>Câu chuyện về vận động viên karate Choi Yeung-Eui, người đã đến Nhật Bản sau Thế chiến thứ hai để trở thành phi công chiến đấu nhưng thay vào đó lại tìm thấy một con đường rất khác. Anh ta đổi tên thành Masutatsu Oyama và đi khắp đất nước, lần lượt đánh bại các võ sĩ. Bộ phim này tập trung vào giai đoạn anh vẫn còn trẻ và đang phát triển phong cách karate nổi tiếng của mình, Kyokushin.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Yang Dong-geun","avatar":""},{"name":"Hirayama Aya","avatar":""},{"name":"Kato Masaya","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
