INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-ay-ta-gap-nhau', 'Nơi Ấy Ta Gặp Nhau', 'Wicker Park', 'https://phimimg.com/upload/vod/20240228-1/27a0f10706cdb8026fb7c723f4afa8a2.jpg', 'https://phimimg.com/upload/vod/20240228-1/c1ccb14fe04ec2ad59fff880b3e644c6.jpg', '<p>Nàng gặp chàng lần đầu tiên ở công viên Wicker, và như người ta vẫn thường nói về tiếng sét ái tình, nàng hiểu rằng nàng không thể yêu ai khác ngoài chàng. Nàng đã theo dõi chàng, tiếp cận chàng, và thậm chí dùng mọi thủ đoạn kể cả việc phản bội người bạn thân nhất…Chàng đang thất nghiệp, phải phụ việc bán hàng trong một cửa hàng bán camera. Một lần tình cờ, nhìn lên màn hình, chàng trông thấy nàng và đó là tình yêu.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Hartnett","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"Matthew Lillard","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
