INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-moi-la-yeu-2004', 'Thế Mới Là Yêu', 'Win A Date With Tad Hamilton!', 'https://phimimg.com/upload/vod/20240228-1/11e050027469498de7f7f145963a1948.jpg', 'https://phimimg.com/upload/vod/20240228-1/14a6169f66b28dc35244abeb2ebc3e3d.jpg', '<p>Một cô gái ở thị trấn nhỏ được hẹn hò với một ngôi sao Hollywood thông qua một cuộc thi. Khi buổi hẹn hò diễn ra tốt đẹp hơn mong đợi, một mối tình tay ba hình thành giữa cô gái, người nổi tiếng và bạn thân của cô gái.</p>', 'Full', 1, 'single', 'completed', 24, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Bosworth","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Josh Duhamel","avatar":""},{"name":"Nathan Lane","avatar":""},{"name":"Sean Hayes","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
