INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-tru-be-nho-cua-toi', 'Vũ Trụ Bé Nhỏ Của Tôi', 'My Tiny Universe', 'https://phimimg.com/upload/vod/20240228-1/e1f639c39c1e9db67e1d4e7c7009ca62.jpg', 'https://phimimg.com/upload/vod/20240228-1/e0f3dd9738689e1a70dcfd8325de1e9d.jpg', '<p>Vũ Trụ Bé Nhỏ Của Tôi - My Tiny Universe là một bộ phim hài đen tối. Bobby Devillin, một trong những nhà sản xuất chuỗi phim hành động lớn nhất ở Hollywood trong suốt hai thập kỷ qua. Nhưng cuộc sống cá nhân của anh là một con tàu đắm. Vee, người vợ thứ hai của anh là MC dẫn chương trình trên tạp chí truyền hình Hollywood, luôn bám vào cuộc hôn nhân mười lăm năm bất chấp việc anh ngoại tình nhiều lần. Nhưng rồi vào một ngày, cuộc sống hào nhoáng bên ngoài của Bobby phải dừng lại khi một nam diễn viên bất ngờ nhặt được chiếc điện thoại của anh từ trong bụi cây. Anh ta đã lôi ra một mạng lưới tình nhân của Bobby và dụ tất cả các cô này đến nơi ẩn thân bí mật của Bobby, phá hủy thế giới của Bobby.</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Heard","avatar":""},{"name":"Debi Mazar","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
