INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-giet-thue', 'Sát Thủ Giết Thuê', 'Collateral', 'https://phimimg.com/upload/vod/20240220-1/118c524b8f29e2db9464383f28a72a0a.jpg', 'https://phimimg.com/upload/vod/20240220-1/81499b25964cc446fb61d115e27b7bec.jpg', '<p>Tài xế Max làm nghề lái taxi đã 12 năm, và trong những vị khách đã bước lên xe của mình thì anh không thể nào quên được Vincent, một kẻ giết mướn chuyên nghiệp. Đêm ấy Vincent đã ngồi trên xe của Max, ép anh chở hắn đi giết 5 mạng người trong một đêm. Max không những rơi vào sự sợ hãi còn bị nghi oan là kẻ giết người...</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"Jada Pinkett Smith","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324528);
