INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-lon', 'Cá Lớn', 'Big Fish', 'https://phimimg.com/upload/vod/20240219-1/2af0c36c15c7c5f72a6a3898b7b3ca3b.jpg', 'https://phimimg.com/upload/vod/20240219-1/f2d305076f309b11c97db66ff1245eeb.jpg', '<p>Khi còn nhỏ Will đã được cha mình kể hàng trăm lần về những câu chuyện kì lạ của cuộc đời ông. Khi lớn lên, Will trở nên chán ngán những câu chuyện mà cha cậu vẫn còn kể đi kể lại. Cho rằng cha chưa bao giờ nói thật với mình, cậu giận và không nói chuyện với cha của mình trong vòng ba năm. Cho đến một ngày kia khi được tin người cha bệnh nặng gần qua đời, Will quyết tâm đi tìm sự thật của những câu chuyện trên và phát hiện ra nhiều điều chưa biết về cha...</p>', 'Full', 1, 'single', 'completed', 16, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Albert Finney","avatar":""},{"name":"Billy Crudup","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324528);
