INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nac-thang-lua', 'Nấc Thang Lửa', 'Ladder 49', 'https://phimimg.com/upload/vod/20240207-1/012eaf6f26943cfd38ea9e4e57c36cfc.jpg', 'https://phimimg.com/upload/vod/20240207-1/25369e63d51b942a5e462f1f679625dc.jpg', '<p>Dưới con mắt cảnh giác của thuyền trưởng Mike Kennedy của ông Mike Kennedy, Jack Firefolder Morrison trưởng thành vào một cựu chiến binh dày dạn tại một trạm cứu hỏa Baltimore. Tuy nhiên, Jack đã đạt đến một ngã tư, vì sự hy sinh mà anh ta đã đưa ra đã khiến anh ta bị tổn hại một cách vô số thời gian và ảnh hưởng đáng kể đến mối quan hệ của anh ta với vợ con. Đáp ứng với ngọn lửa tồi tệ nhất trong sự nghiệp của mình, anh ta bị mắc kẹt trong một tòa nhà 20 tầng. Và khi anh ta phản ánh cuộc sống của mình, bây giờ Phó trưởng Kennedy điên cuồng tọa độ nỗ lực để cứu anh ta.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324528);
