INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-riddick', 'Chiến Binh Riddick', 'The Chronicles Of Riddick', 'https://phimimg.com/upload/vod/20240207-1/5afbe9bf9e32035ad532b654b2a03f3c.jpg', 'https://phimimg.com/upload/vod/20240207-1/a06af807c6056f352242612c3bcc03fd.jpg', '<p>Bộ film nói về Riddick (Vin Diesel), một tên tù vượt ngục và bị dính vào cuộc chiến giữa Chúa tể Marshal và đội quân Necromonger của mình với nhóm Elementals mà đội trưởng Aereon của nhóm là người giúp Riddick khám phá con người thật của chính mình... &nbsp;</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vin Diesel","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Colm Feore","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324528);
