INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-luc-anh-sang', 'Thế Lực Ánh Sáng', 'Night Watch', 'https://phimimg.com/upload/vod/20240207-1/17726aee0fa50dc4a919ab744a77e827.jpg', 'https://phimimg.com/upload/vod/20240207-1/d49d769397585ee28895097cdc9f8737.jpg', '<p>Trong số những người bình thường sống có Những người khác sở hữu nhiều sức mạnh siêu nhiên khác nhau. Họ được chia thành thế lực ánh sáng và thế lực bóng tối, những kẻ đã ký hiệp định đình chiến cách đây vài thế kỷ để chấm dứt một trận chiến tàn khốc. Kể từ đó, lực lượng ánh sáng cai trị ban ngày trong khi ban đêm thuộc về đối thủ bóng tối của họ. Ở Moscow thời hiện đại, bóng tối Những người khác thực sự đi lang thang trong đêm với tư cách là ma cà rồng trong khi Người gác đêm của các lực lượng ánh sáng, trong số đó có Anton, nhân vật chính của bộ phim, cố gắng kiểm soát họ và hạn chế sự phẫn nộ của họ</p>', 'Full', 1, 'single', 'completed', 29, 2004, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Konstantin Khabenskiy","avatar":""},{"name":"Vladimir Menshov","avatar":""},{"name":"Galina Tyunina","avatar":""},{"name":"Mariya Poroshina","avatar":""},{"name":"Zhanna Friske","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
