INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-girl-next-door', 'The Girl Next Door', 'The Girl Next Door', 'https://phimimg.com/upload/vod/20240205-1/754d3c37bbc2dfa36001012ac4c57026.jpg', 'https://phimimg.com/upload/vod/20240205-1/36fcc44be327dd1adaed34dbe188cd09.jpg', '<p>Chàng trai 18 tuổi, Matthew Kidman là một học trò gương mẫu và có thành tích đáng nể. Tuy nhiên, không như các bạn cùng trang lứa quậy hết mình thì Matthew vẫn hoàn toàn miễn nhiễm với các trò nghịch ngợm. Mọi sự bắt đầu thay đổi kể từ khi nhà bên có một cô gái xinh đẹp đến trông nhà hộ bà bác. Matthew gần như bị đổ ngay từ ánh nhìn đầu tiên trước Danielle, đặc biệt là khi cô nàng thay đồ trong phòng mà không hề để ý, bên cửa sổ đối diện đang có một đôi mắt hình chữ A, cái miệng hình chữ O to tướng. Matthew đang nghĩ cách kiếm chuyện làm quen người đẹp thì Danielle đã dò được suy nghĩ trong đầu anh. Cô nàng sang nhà mời anh đi chơi và ngay trong lần đầu ra mắt, Matt đã bị nàng thuyết phục cởi bỏ hết cả quần áo. Thật trớ trêu, ngày mà Matthew tưởng có thể vỗ ngực tự hào với đám bạn rằng mình chài được một em ngon lành cũng là lúc cậu bạn thân phát hiện ra Danielle là một diễn viên phim cấp 3. Chuyện gì sẽ xảy ra, Matthew sẽ làm gì để giữ được mối rung cảm đầu đời của mình?</p>', 'Full', 1, 'single', 'completed', 22, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emile Hirsch","avatar":""},{"name":"Elisha Cuthbert","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"James Remar","avatar":""},{"name":"Chris Marquette","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
