INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-chet', 'Điểm Chết', 'R-Point', 'https://phimimg.com/upload/vod/20240205-1/03c5019500d86cc38bbc4b14067fb5e0.jpg', 'https://phimimg.com/upload/vod/20240205-1/f394b0ea0f42fdb4036521c921ad0e92.jpg', '<p>Điểm Chết - R-Point (2004):Phim lấy bối cảnh nội chiến Việt Nam năm 1972 khi một số lính Hàn tham gia trong liên minh Mỹ đánh miền Nam Việt Nam. Câu chuyện kỳ bí đã xảy ra trong nhiệm vụ giải cứu binh đoàn Battalion 53 của Hàn Quốc bị mất tích tại một vùng chiến sự đặc biệt được gọi là điểm R.</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kam Wu-seong","avatar":""},{"name":"Park Won-sang","avatar":""},{"name":"Jin-ho Song","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
