INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tra-herbal-tieng-quang-dong', 'Quán Trà Herbal (Tiếng Quảng Đông)', 'Herbal Tea ( Cantonese )', 'https://phimimg.com/upload/vod/20240220-1/00ddaa27196c10b2bec993e52f23a685.jpg', 'https://phimimg.com/upload/vod/20240220-1/40a501a88c633b22365f7acce829bb8b.jpg', '<p>Bản tính của Lâm Vỹ Châu rất vô tư phóng khoáng, ông bố già của cô đã qua đời lúc cô mới 12 tuổi, đã giao cô cho một quán trà nguội để cô quản lý, từ đó Vỹ Châu đã làm việc chăm chỉ và tô điểm cho quán trà càng thêm có sức sống. Với tính cách vô tư cô đã không để ý anh chàng một sách Triệu Thế Xuân đã có tình cảm mến mộ vớiTô Lương người bạn hợp tác cùng cô . Một ngày nọ , cô đã cho Chân Chí Đan thuê phòng với giá thuê rất rẻ , Chân là người đóng thế võ thuật, mơ ước có ngày trở thành diễn viên chính,có một người bạn diễn viên là Linda và một người thầy không chuyên nghiệp. Sau khi Chân Chí Đan bị LinDa phụ tình,sự quan tâm và nhiệt tình của Lâm Vỹ Châu khiến cho hai người xích lại gần nhau hơn.\n</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lo Candy","avatar":""},{"name":"Jordan Chan","avatar":""},{"name":"Patrick Tang","avatar":""},{"name":"Ka-Yee Lee","avatar":""},{"name":"Lily","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
