INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-my', 'Biệt Đội Mỹ', 'Team America: World Police', 'https://phimimg.com/upload/vod/20240128-1/baa09ba97abd4f04f55d72182213d9e0.jpg', 'https://phimimg.com/upload/vod/20240128-1/3bda8cbb2df127b46ac4425939d45336.jpg', '<p>Team America World Police theo chân một lực lượng cảnh sát quốc tế chuyên duy trì sự ổn định toàn cầu. Biết được rằng nhà độc tài Kim Jong il ra tay để hủy diệt thế giới, nhóm đã chiêu mộ ngôi sao Broadway Gary Johnston để hoạt động bí mật. Với sự giúp đỡ của Team America, Gary đã khám phá ra kế hoạch hủy diệt thế giới. Đội Mỹ sẽ có thể cứu nó trong thời gian? Phim có sự tham gia của… Samuel L Jackson, Tim Robbins, Sean Penn, Michael Moore, Helen Hunt, Matt Damon, Susan Sarandon, George Clooney, Danny Glover, Ethan Hawke, Alec Baldwin… hay không?</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Trey Parker","avatar":""},{"name":"Matt Stone","avatar":""},{"name":"Kristen Miller","avatar":""},{"name":"Masasa Moyo","avatar":""},{"name":"Daran Norris","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324528);
