INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mieu-nu', 'Miêu Nữ', 'Catwoman', 'https://phimimg.com/upload/vod/20240128-1/803b0686a7aa36f8aba79f7a7d40e850.jpg', 'https://phimimg.com/upload/vod/20240128-1/3ce57ca3c648a203418a70eaa13783fa.jpg', '<p>Catdess là câu chuyện về sự nhút nhát, nghệ sĩ nhạy cảm nhạy cảm Philips, một người phụ nữ dường như không thể ngừng xin lỗi vì sự tồn tại của chính mình. Cô làm việc như một nhà thiết kế đồ họa cho Hedare Beauty, một công ty mỹ phẩm voi Mammoth trên bờ vực phát hành một sản phẩm chống lão hóa cách mạng. Khi sự kiên nhẫn vô tình xảy ra trên một bí mật đen tối, chủ nhân của cô đang trốn, cô thấy mình ở giữa một âm mưu của công ty. Những gì xảy ra tiếp theo thay đổi sự kiên nhẫn mãi mãi. Trong một bước ngoặt huyền bí của số phận, cô được biến thành một người phụ nữ với sức mạnh, tốc độ, nhanh nhẹn và cảm giác cực kỳ nhạy bén của một con mèo. Với năng lực mới của mình và trực giác Feline, sự kiên nhẫn trở thành người phụ nữ, một sinh vật bóng bẩy và lén lút cân bằng trên đường mỏng giữa tốt và xấu. Giống như bất kỳ Wildcat nào, cô ấy nguy hiểm, khó nắm bắt và không được khám phá. Cuộc phiêu lưu của cô phức tạp bởi một mối quan hệ đang phát triển với Tom Lone, một cảnh sát đã rơi vào sự kiên nhẫn nhưng không thể lay chuyển niềm đam mê của mình với người phụ nữ bí ẩn, người dường như chịu trách nhiệm cho một chuỗi các cuộc tấn công Sprees gây ô nhiễm thành phố</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324528);
