INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-dao-tu-than', 'Hòn Đảo Tử Thần', 'Mindhunters', 'https://phimimg.com/upload/vod/20240128-1/ca224d20074ddd0d5537b76ac35fbae0.jpg', 'https://phimimg.com/upload/vod/20240128-1/be834a328943cee169ab24fe3935a060.jpg', '<p>Các học viên trong chương trình lập hồ sơ tâm lý của FBI phải áp dụng khóa đào tạo của họ vào thực tế khi họ phát hiện ra một kẻ giết người ở giữa họ. Dựa rất lỏng lẻo vào Agatha Christies And Then There Were none.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"LL Cool J","avatar":""},{"name":"Jonny Lee Miller","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Kathryn Morris","avatar":""},{"name":"Patricia Velásquez","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
