INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-com-so-tai', 'Siêu Cớm So Tài', '36th Precinct', 'https://phimimg.com/upload/vod/20240128-1/ebf67264205a38a57c26b2fa8ccd4993.jpg', 'https://phimimg.com/upload/vod/20240128-1/14cddc9ae19e142c2cf6789b0261f03f.jpg', '<p>Bối cảnh phim diễn ra ở Paris, nơi hai cảnh sát đang tranh giành chiếc ghế cảnh sát trưởng còn trống trong khi đang truy lùng một băng trộm hung bạo. Bộ phim được đạo diễn bởi Olivier Marchal, một cựu sĩ quan cảnh sát đã có 12 năm làm việc với cảnh sát Pháp trước khi tạo ra câu chuyện này, một phần được lấy từ những sự kiện có thật xảy ra trong những năm 1980 ở Pháp.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Daniel Auteuil","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"André Dussollier","avatar":""},{"name":"Roschdy Zem","avatar":""},{"name":"Valeria Golino","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
