INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('11-gio-14-phut', '11 Giờ 14 Phút', '11:14', 'https://phimimg.com/upload/vod/20240126-1/4d3bf3562051450c89d0d36042de6fcc.jpg', 'https://phimimg.com/upload/vod/20240126-1/390846cb6e8cede58d996f40b79ddd99.jpg', '<p>Bộ phim là chuỗi sự kiện diễn ra đồng thời vào lúc 11:14 tại những địa điểm khác nhau, nhưng nó lại đưa đến những kết cục bi thảm. Diễn biến phim rất lôi cuốn và hấp dẫn...</p>', 'Full', 1, 'single', 'completed', 16, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Henry Thomas","avatar":""},{"name":"Colin Hanks","avatar":""},{"name":"Ben Foster","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324528);
