INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thu-trong-nguc', 'Báo Thù Trong Ngục', 'Doing Hard Time', 'https://phimimg.com/upload/vod/20240126-1/8e11bf87240e453f282fddcc8ccd455b.jpg', 'https://phimimg.com/upload/vod/20240126-1/b042751c82b773c85cf7631678f47714.jpg', '<p>Sau khi những kẻ sát hại con anh được nhận bản án quá nhẹ, người đàn ông quyết tâm trả thù đã cố tình để mình bị tống giam để thực thi thứ công lý mà anh muốn.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Boris Kodjoe","avatar":""},{"name":"Michael Kenneth Williams","avatar":""},{"name":"Sticky Fingaz","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
