INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bao-thu-trong-nguc', 'Báo Thù Trong Ngục', 'Doing Hard Time', 'báo thù trong ngục doing hard time boris kodjoe michael kenneth williams sticky fingaz ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-de-arthur', 'Hoàng Đế Arthur', 'King Arthur', 'https://phimimg.com/upload/vod/20240126-1/93dd90c5ebb9b0738573b021be74b622.jpg', 'https://phimimg.com/upload/vod/20240126-1/f57d516069d0e29a1174115d5165ca85.jpg', '<p>Arthur (Clive Owen) sẵn sàng rời khỏi Anh để trở về với hòa bình và ổn định của Rome. Nhưng trước đó, một nhiệm vụ cuối cùng khiến anh ta và các hiệp sĩ của Bàn Tròn (Lancelot, Galahad, Bors, Tristan và Gawain) hiểu rằng, sau sự sụp đổ của Rome (476 sau Công nguyên), những gì Anh cần là một vị vua để bảo vệ nó khỏi mối đe dọa của cuộc xâm lược của người Saxon và đưa nó vào một thời điểm mới. Được hướng dẫn bởi Merlin và bởi Geneva (Keira Knightley) dũng cảm và xinh đẹp, Arthur sẽ phải tự tìm cho mình sức mạnh cần thiết để thay đổi tiến trình lịch sử.</p>', 'Full', 1, 'single', 'completed', 10, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clive Owen","avatar":""},{"name":"Ioan Gruffudd","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Mads Mikkelsen","avatar":""},{"name":"Joel Edgerton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324528);
