INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-cung-lap-phuong-0', 'Mê Cung Lập Phương 0', 'Cube Zero', 'https://phimimg.com/upload/vod/20240123-1/c336c17093db92afe146e50f80cb715d.jpg', 'https://phimimg.com/upload/vod/20240123-1/722aaadf6f2d3655d099f71cd373e420.jpg', '<p>Cube Zero là bộ phim thứ ba trong bộ ba nhưng lần này thay vì một bộ phim về những người bị mắc kẹt trong một khối lập phương chết chóc cố gắng thoát ra, chúng ta nhìn thấy nó từ con mắt của một người đang điều khiển khối lập phương và sự tra tấn của các nạn nhân bên trong. Khi tên mọt sách không thể đứng nhìn một người phụ nữ đau khổ, anh ta tự mình bước vào khối lập phương để cố gắng cứu cô ấy.</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zachary Bennett","avatar":""},{"name":"Stephanie Moore","avatar":""},{"name":"Michael Riley","avatar":""},{"name":"Martin Roach","avatar":""},{"name":"David Huband","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
