INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-bong-choi-ky-tai', 'Đội Bóng Chọi Kỳ Tài', 'DodgeBall: A True Underdog Story', 'https://phimimg.com/upload/vod/20240123-1/2c42321962f78b4cb80674d86786aa40.jpg', 'https://phimimg.com/upload/vod/20240123-1/25174df95e38906ba1765c9e0ef5fffe.jpg', '<p>Khi White Goodman, chủ sở hữu của một trung tâm thể hình cao cấp, thời thượng, có ý định tiếp quản phòng tập thể dục địa phương đang gặp khó khăn do Pete La Fleur, người luôn vui vẻ, may mắn, điều hành, chỉ có một cách duy nhất để La Fleur chống trả: bóng ném . Được hỗ trợ bởi một chuyên gia về bóng né và luật sư của Goodman, La Fleur và nhóm những kẻ kém cỏi của anh ta khởi động một trận chiến hạ gục, kéo dài, trong đó người chiến thắng sẽ có tất cả.</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vince Vaughn","avatar":""},{"name":"Christine Taylor","avatar":""},{"name":"Ben Stiller","avatar":""},{"name":"Rip Torn","avatar":""},{"name":"Justin Long","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
