INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('banh-da-tang', 'Bánh Đa Tầng', 'Layer Cake', 'https://phimimg.com/upload/vod/20240104-1/e684f689dd8561643b331f29f1d4f264.jpg', 'https://phimimg.com/upload/vod/20240104-1/c19e1a2e13ef03b72d940675f316feec.jpg', '<p>Ông trùm Jimmy Price của giới buôn ma túy Anh trước khi xuống tay nghỉ hưu đã quyết định làm cú chót giúp tìm lại cô con gái cưng bị mất tích của người bạn Edward lâu năm của mình - 1 ông trùm khác trong giới xây dựng và báo chí. Cuộc tìm kiếm trở nên phức tạp khi xuất hiện cùng nó là số thuốc lắc hạng 1 trị giá 2 triệu bảng Anh và 1 loạt rắc rối kèm theo.</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Craig","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"George Harris","avatar":""},{"name":"Sally Hawkins","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
