INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-sup-do', 'Đế Chế Sụp Đổ', 'Downfall', 'https://phimimg.com/upload/vod/20240104-1/45f93b095e4e7129440397ee5214b7da.jpg', 'https://phimimg.com/upload/vod/20240104-1/eb8b9c48f2a1c69a69a4715edd07d6af.jpg', '<p>Downfall - Der Untergang (2004) là một tác phẩm điện ảnh xuất sắc của Đức, hơn hết đây là bộ phim quan trọng vì nhân vật chính là một trong những tên tuổi có ảnh hưởng đến sự thay đổi của nhân loại - Adolf Hitler.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Bruno Ganz","avatar":""},{"name":"Alexandra Maria Lara","avatar":""},{"name":"Corinna Harfouch","avatar":""},{"name":"Ulrich Matthes","avatar":""},{"name":"Juliane Köhler","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
