INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('escape-from-hong-kong-island', 'Escape From Hong Kong Island', 'Escape From Hong Kong Island', 'https://phimimg.com/upload/vod/20240104-1/1c5763ffc24b6a5324bf247cd1628c86.jpg', 'https://phimimg.com/upload/vod/20240104-1/246b44e3be7733fa16fc2de8292a8b6d.jpg', '<p>Raymond Mak là một tay giao dịch chứng khoán hèn hạ, một ngày bị Địa ngục giao cho. Đầu tiên anh ta bị ông chủ sa thải và sau đó anh ta bị cướp. Raymond đã có việc làm mới ở bên kia bến cảng, nhưng để đi từ Wanchai đến Tsimshatsui cần ít nhất ba đô la cho một chuyến phà, hoặc nhiều hơn cho MTR hoặc taxi. Nhưng không có tiền mặt hay giấy tờ tùy thân, Raymond sẽ phải kêu gọi giúp đỡ một hoặc hai điều.</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jordan Chan","avatar":""},{"name":"CoCo","avatar":""},{"name":"Paul Wong","avatar":""},{"name":"Wing Yip","avatar":""},{"name":"Yip Sai Wing","avatar":""},{"name":"Steve Wong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
