INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('escape-from-hong-kong-island', 'Escape From Hong Kong Island', 'Escape From Hong Kong Island', 'escape from hong kong island escape from hong kong island jordan chan coco paul wong wing yip yip sai wing steve wong ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-cuu-nan', 'Khách Sạn Cứu Nạn', 'Hotel Rwanda', 'https://phimimg.com/upload/vod/20240104-1/ff19db71397c3a3e15a221c8fdf52684.jpg', 'https://phimimg.com/upload/vod/20240104-1/2ff178122aeb507dfff33cc4f7271f00.jpg', '<p>Năm 1994, một cuộc giao tranh sắc tộc đẫm máu đã nổ ra tại Rwanda giữa người Hutu và người Tutsi. Trong bối cảnh hoảng loạn ấy với cái chết luôn gần kề, một nhân viên quản lý khách sạn đã làm nên “kỳ tích” khi cứu sống hơn 1.200 người thoát khỏi cuộc tàn sát - một Danh sách Schindler ở Rwanda.Bộ phim Hotel Rwanda (Tựa phim tại VN: Khách sạn cứu nạn) được làm dựa theo câu chuyện có thật về cuộc đời Paul Rusesabagina (Don Cheadle thủ vai) - một người Hutu tốt bụng, quản lý khách sạn 5 sao Des Mille Collines ở Kigali.Sau khi lên nắm quyền, những kẻ quá khích thuộc tộc người Hutu đã kích động gây nên một cuộc thanh trừng “tận gốc” người Tutsi. Paul cùng vợ (người Tutsi) và các con cũng không ngoại lệ.Một buổi sáng, toán quân Hutu đã ...</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Don Cheadle","avatar":""},{"name":"Xolani Mali","avatar":""},{"name":"Desmond Dube","avatar":""},{"name":"Hakeem Kae-Kazim","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
