INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sep-moi', 'Sếp Mới', 'In Good Company', 'https://phimimg.com/upload/vod/20240103-1/a54931317f155378023d844080cac49b.jpg', 'https://phimimg.com/upload/vod/20240103-1/468bbaa9892ef0972ef3d76ff78bf08c.jpg', '<p>Dan Foreman là một giám đốc điều hành kinh doanh quảng cáo dày dạn kinh nghiệm tại một ấn phẩm cấp cao khi việc tiếp quản công ty dẫn đến việc anh ta được giao cho người giám sát ngây thơ Carter Duryea, người bằng nửa tuổi anh ta. Vấn đề trở nên tồi tệ hơn khi người giám sát mới của Dan có quan hệ tình cảm với con gái của anh ta, một sinh viên đại học 18 tuổi Alex.</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dennis Quaid","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Marg Helgenberger","avatar":""},{"name":"David Paymer","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
