INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sep-moi', 'Sếp Mới', 'In Good Company', 'sếp mới in good company dennis quaid topher grace scarlett johansson marg helgenberger david paymer ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-o-nho-ky-di', 'Kẻ Ở Nhờ Kỳ Dị', '3-Iron', 'https://phimimg.com/upload/vod/20240108-1/e65e0800c81084c94b6239719563b214.jpg', 'https://phimimg.com/upload/vod/20240108-1/1ecc79f38d7a2aeea771901c94641f2d.jpg', '<p>Tae Soek ngày thường làm nghề phát truyền đơn, còn dán cả lên ở khoá cửa nhà người ta, buổi tối anh đi kiểm tra nếu tờ đơn không bị bỏ xuống thì lẻn vào nhà và xem đó như là nhà của mình. Một ngày, anh đến ngôi nhà của Seon Hwa, chồng của cô luôn ngược đãi và hành hạ cô còn không cho Seon Hwa đi ra khỏi nhà. Tae Soek nhìn thấy tờ đơn vẫn còn trên khoá cửa nên đã đột nhập vào mà không biết Seon Hwa bị nhốt bên trong. Seon Hwa phát hiện có người, còn Tae Soek bỏ đi rồi quay lại thì thấy hình ảnh chồng Seon Hwa hành hạ cô. Tae Soek bèn dùng gậy đáng gold dạy cho chồng Seon Hwa một trận rồi dắt Seon Hwa bỏ trốn. Cả hai cùng trải qua những tháng ngày lén lút sống trong căn nhà của người khác...</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Seung-yeon","avatar":""},{"name":"Jae Hee","avatar":""},{"name":"Hyuk-ho Kwon","avatar":""},{"name":"Ju Jin-mo","avatar":""},{"name":"Choi Jeong-ho","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
