INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('que-huong-tren-dong-co', 'Quê Hương Trên Đồng Cỏ', 'Home On The Range', 'https://phimimg.com/upload/vod/20231231-1/a2c3819cd51020d085064fde7e98a55a.jpg', 'https://phimimg.com/upload/vod/20231231-1/dcc54673933d90ddbda2dc3ef4edcd09.jpg', '<p>Ở vùng ngoại ô, có một nông trại trong mơ của gia súc, nơi mà heo, bò, gà sống rất vui vẻ chan hòa và không bao giờ bị “làm thịt”. Nhưng rồi bà chủ nhân hậu bị phá sản, nông trại bị tịch thu để bán đấu giá. Nghe đâu những người đang lăm le mua lại nông trại sẽ sẵn sàng “làm thịt” hết gia súc. Trước hiểm họa bị giết thịt, bầy gia súc quyết định tìm cách cứu vãn nông trại. Chúng cử ra ba cô bò cái Grace, Maggie và Caloway đỏng đảnh nhưng dũng cảm và mưu trí đến gặp cảnh sát trưởng để thương lượng. Thử thách của chúng là bắt được một tên cướp và đem số tiền thưởng về để cứu nông trại. Liệu ba cô bò cái có hoàn thành được nhiệm vụ...</p>', 'Full', 1, 'single', 'completed', 9, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Judi Dench","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Jennifer Tilly","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324528);
