INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-hoi-nach-anh-trang-tinh-yeu', 'Công Chúa Hôi Nách (Ánh Trăng Tình Yêu)', 'Elixir Of Love', 'https://phimimg.com/upload/vod/20240102-1/7a5f3faa852156bcce5b66b7dab5c71e.jpg', 'https://phimimg.com/upload/vod/20240102-1/df9189c3f1979ac1d615eef785988697.jpg', '<p>Công chúa từ khi ra đời đã mang trên người một mùi hôi khó chịu, các thái y phải bó tay. Chàng trai nghèo Thẩm Mộng Khai luôn lấy việc chữa trị cho công chúa làm sự nghiệp cả đời. Tình cờ anh quen Hàm Hương, một cô gái bán cá tình nguyện giúp đỡ Thẩm Mộng Khai tìm phương thuốc đặc biệt để chữa khỏi mùi hôi cho Công chúa. Mặc dù mục tiêu của Thẩm Mộng Khai là tìm ra cách chữa trị và thành thân với Công chúa, nhưng anh và Hàm Hương ngày càng gắn bó trong hành trình tìm ra phương thuốc đó. Một ngày chàng tìm ra được phương pháp trị bệnh cho công chúa, vui mừng chuẩn bị vào kinh thì Hàm Hương biến mất. Lúc này chàng mới phát hiện ra Hàm Hương mới là tình yêu thật sự của mình. Anh vẫn phải làm tròn trách nhiệm với công chúa đồng thời đi tìm tình yêu của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"Nhậm Hiền Tề","avatar":""},{"name":"Dương Thiên Hoa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
