INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('scoobydoo-2-quai-vat-hien-hinh', 'Scooby-Doo 2: Quái Vật Hiện Hình', 'Scooby-Doo 2: Monsters Unleashed', 'https://phimimg.com/upload/vod/20240102-1/2771ff9d881b74abfe7c0404a5b26047.jpg', 'https://phimimg.com/upload/vod/20240102-1/0fa4615c3d1d5dd6390163069819ff0c.jpg', '<p>Phim Scooby-Doo 2: Quái Vật Hiện Hình - Scooby-Doo 2: Monsters Unleashed 2004: Chú chó Scooby và nhóm bạn đối mặt với một tên độc ác vô danh đeo mặt nạ đang khống chế thành phố Collsville bởi con quái vật máy được tạo ra bởi Tổng công ty Kỳ Bí như con ma khổng lồ, hiệp sỹ tàng hình, con ma điện... Dưới áp lực của nữ phóng viên Heather Jasper-Howe và những người dân xứ Coolvilles, nhóm bạn cùng hợp sức điều tra.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Freddie Prinze Jr.","avatar":""},{"name":"Sarah Michelle Gellar","avatar":""},{"name":"Matthew Lillard","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
