INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hana-and-alice', 'Hana And Alice', 'Hana And Alice', 'https://phimimg.com/upload/vod/20231231-1/70869bbbce9297a5787d230bfb77213d.jpg', 'https://phimimg.com/upload/vod/20231231-1/8cf6d19a0cea29e47ed7f952c5e9c484.jpg', '<p>Khi vào trường trung học, hai người bạn thân tên Hana và Alice nhận thấy một cậu bé một năm lớn tuổi hơn trong khi chờ tàu, và cả hai đều bị yêu một năm khá mạnh mẽ với anh ta. Một ngày nọ trong khi bí mật theo anh về nhà, Hana chứng kiến cậu bé bước vào một bức tường và bất tỉnh. Khi anh thức dậy, cô nói dối và thuyết phục anh rằng anh phải có mất trí nhớ, bởi vì anh không nhớ sự thật rằng cô là bạn gái của anh. Sau này, vui nhộn xảy ra khi hai cô gái cố gắng chạy trốn với lời nói dối. Tất nhiên, các biến chứng sớm phát sinh.</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
