INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('heo-peppa-phan-1', 'Heo Peppa (Phần 1)', 'Peppa Pig (Season 1)', 'https://phimimg.com/upload/vod/20240109-1/f6a16075def21cfd0006d4e145d4c906.jpg', 'https://phimimg.com/upload/vod/20240109-1/be453ddc07a9b6b59dd8fc0e6ec42a09.jpg', '<p>Trong thế giới của heo Peppa, mỗi ngày luôn thật đặc biệt, nhất là khi có những vũng nước để đùa nghịch, trò vui để chơi và bạn bè để ghé thăm.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 9, 2004, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Lily Snowden-Fine","avatar":""},{"name":"John Sparkes","avatar":""},{"name":"Richard Ridings","avatar":""},{"name":"Morwenna Banks","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324528);
