INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-nhan-dan-an-do', 'Chúng Ta, Nhân Dân Ấn Độ', 'Swades', 'https://phimimg.com/upload/vod/20231230-1/3a9b1cbf1a81142e615deeb5b3e91595.jpg', 'https://phimimg.com/upload/vod/20231230-1/de2be17751687a5ca134c12f27553586.jpg', '<p>Mohan Bhargav (Shah Rukh Khan) là một nhà khoa học gốc Ấn thành đạt tại cơ quan NASA (Mỹ). Sau bao nhiêu năm xa cách, anh quay về quê hương để tìm lại người vú nuôi đã nuôi dạy anh từ thời tấm bé để đưa bà về Mỹ phụng dưỡng. Quãng thời gian Mohan ở tại quê nhà, anh đã chứng kiến những nét lạc hậu, những suy nghĩ phân biệt giai cấp, mù chữ bao trùm những người dân nghèo ở đây. Mohan phải làm gì để có thể thay đổi được những điều hủ lậu và thay đổi vùng quê của mình...</p>', 'Full', 1, 'single', 'completed', 9, 2004, 'Vietsub', '360p', 'Ấn Độ', 0, '[{"name":"Shah Rukh Khan","avatar":""},{"name":"Gayatri Joshi","avatar":""},{"name":"Kishori Balal","avatar":""},{"name":"Smith Seth","avatar":""},{"name":"Lekh Tandon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
