INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-nhat-ai-nu', 'Đệ Nhất Ái Nữ', 'First Daughter', 'null', 'https://phimimg.com/upload/vod/20231219-1/263a74563c1d35bd0d34355595bdf8a7.jpg', '<p>Con gái Tổng thống Hoa Kỳ nhất quyết muốn đi học đại học như một đứa trẻ bình thường. Nhưng khi bạn có bố là lãnh đạo của thế giới tự do, bình thường chỉ là tương đối.</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katie Holmes","avatar":""},{"name":"Marc Blucas","avatar":""},{"name":"Amerie","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
