INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-boc-ma-2-vo-toi', 'Vỏ Bọc Ma 2: Vô Tội', 'Ghost In The Shell 2: Innocence', 'https://phimimg.com/upload/vod/20231219-1/fedad777b289a093dd6e9d07fa0b85a5.jpg', 'https://phimimg.com/upload/vod/20231219-1/fc9034b77fe7645b7127afa8c2d6e83a.jpg', '<p>Thám tử người máy Batou được giao nhiệm vụ điều tra một loạt vụ giết người do gynoids - những người máy giống búp bê, tất cả đều bị trục trặc, bị giết, rồi tự hủy sau đó. Bộ não của các gynoid khởi tạo để bảo vệ phần mềm của nhà sản xuất chúng, nhưng trong một gynoid mà chính Batou đã vô hiệu hóa, vẫn còn một tệp: một giọng nói nói cụm từ Giúp tôi với.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2004, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Atsuko Tanaka","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Tamio Ohki","avatar":""},{"name":"Yutaka Nakano","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
