INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tho-lac-loi', 'Tuổi Thơ Lạc Lối', 'Samaritan Girl', 'https://phimimg.com/upload/vod/20231219-1/d3e185e9291043f7d942f19568b703db.jpg', 'https://phimimg.com/upload/vod/20231219-1/5d78996b4d6fa4b5160f2d741b72a60e.jpg', '<p>Jae-Young là một cô gái điếm nghiệp dư ngủ với những người đàn ông trong khi người bạn thân nhất của cô Yeo-Jin quản lý cô, hẹn hò, chăm sóc tiền và đảm bảo bờ biển rõ ràng. Khi Jae-Young rơi vào tình yêu với một trong những người đàn ông đó mà cô ta ngăn chặn cảm xúc của mình đối với anh ta đối với người bạn của mình, người ghen tị. Một ngày nọ, Yeo-Jin thất bại trong việc làm công việc của mình nhìn ra cảnh sát ...</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324528);
