INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-vi-tra', 'Hương Vị Trà', 'The Taste Of Tea', 'https://phimimg.com/upload/vod/20231219-1/bf070ad73443aa423e3272228aa7b9dd.jpg', 'https://phimimg.com/upload/vod/20231219-1/d9fb144eae14b36fe5da6712f9cc4859.jpg', '<p>Bộ phim xoay quanh câu chuyện về gia đình Haruno sống trong một căn nhà cổ, ở một vùng nông thôn ngoại thành Tokyo, nơi mà vẻ đẹp thiên nhiên vẫn còn ngự trị. Haruno là kiểu gia đình thường gặp ở nước Nhật, hai đứa trẻ ngày ngày tới trường, người cha đi làm, người mẹ làm nội trợ, và ông nội sống chung với cả nhà. Ngôi nhà còn có sự góp mặt người chú, một nhà sản xuất âm nhạc đang tới ở chơi. Họ có thói quen cùng nhau ngồi trên hiên nhà, lặng lẽ nhìn ra khoảng không xanh biếc trước mặt trong khi mỗi người theo đuổi một ý nghĩ.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Maya Banno","avatar":""},{"name":"Takahiro Satô","avatar":""},{"name":"Tadanobu Asano","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
