INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nhan-tao', 'Người Nhân Tạo', 'Casshern', 'https://phimimg.com/upload/vod/20231219-1/5476464307647340156fad0090962bee.jpg', 'https://phimimg.com/upload/vod/20231219-1/df3bb57a6cb1e4bd994980fc5c2569ee.jpg', '<p>Người Nhân Tạo - Casshern: Gần 50 năm sau cuộc chiến tranh của nhân loại, thế giới bị chia cách bởi hai phe Á Tế Á Liên Bang và Âu Công Thể. Sau khi chiến tranh kết thúc thì nước Công hoà Á Tế Á Liên Bang giành được thắng lợi nắm giữ khu vực Châu Á và Châu Âu.</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yûsuke Iseya","avatar":""},{"name":"Kumiko Asô","avatar":""},{"name":"Akira Terao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324528);
