INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-hai-tac-thanh-kiem-bi-nguyen-rua', 'Vua Hải Tặc: Thánh Kiếm Bị Nguyền Rủa', 'One Piece Cursed Holy Sword One Piece: Norowareta Seiken (Movie 5)', 'https://phimimg.com/upload/vod/20231215-1/eac8f1c4961475612e2047947f54c0c0.jpg', 'https://phimimg.com/upload/vod/20231215-1/bc0130111285c5ccbb13381368008054.jpg', '<p>Vì sự truy đuổi của hải quân, Rufu và nhóm của anh đã đến đảo Aska trên đường trốn thoát. Nami nghe nói rằng có một Thất tinh kiếm trên hòn đảo này. Cô luôn muốn được tận mắt nhìn thấy vẻ đẹp của Thất Tinh Kiếm. Sauron biến mất sau khi nhìn thấy một con dao đã được bắn vào mình. Trong khi băng hải tặc Mũ Rơm đang tìm kiếm Sauron, họ đã gặp một cô gái tên Maya đang giữ ba viên đá quý. Họ đã nghe về bảy ngôi sao huyền thoại. Đằng sau thanh kiếm, có một truyền thuyết chưa được biết đến. Người được điều khiển bởi thanh kiếm bảy sao này là Saka, đồng minh trẻ tuổi của Sauron. Để cứu Saka, Sauron đã quyết định cắt bỏ vận đỏ đáng ngại trên đảo. Mặt trăng...</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2004, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
