INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-tau-dien-ngam', 'Quái Vật Tàu Điện Ngầm', 'Creep', 'https://phimimg.com/upload/vod/20231215-1/d47cb3fad5364ed45c1ad8b8f6c95111.jpg', 'https://phimimg.com/upload/vod/20231215-1/714f9f514315059e7009b3c95c7fe6de.jpg', '<p>Bị mắc kẹt trong một ga tàu điện ngầm ở London, một người phụ nữ đang bị truy đuổi bởi một kẻ tấn công tiềm năng đi vào mê cung đường hầm vô danh bên dưới đường phố của thành phố</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Franka Potente","avatar":""},{"name":"Vas Blackwood","avatar":""},{"name":"Ken Campbell","avatar":""},{"name":"Jeremy Sheffield","avatar":""},{"name":"Paul Rattray","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
