INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-nguyen-vong', 'Ba Nguyện Vọng', 'Fantasia', 'https://phimimg.com/upload/vod/20231213-1/df144951b3728965826ff324a38e4190.jpg', 'https://phimimg.com/upload/vod/20231213-1/7b935dfcd75e3dd64a645d5da57f543d.jpg', '<p>Bộ ba thám tử vụng về triệu tập nữ pháp sư từ một cái đèn, rồi nghi vấn về pháp thuật của cô khi cô phá hoại nhiều hơn là biến điều ước của họ thành hiện thực.</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Bá Chi","avatar":""},{"name":"Lưu Thanh Vân","avatar":""},{"name":"Cổ Thiên Lạc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
