INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ba-nguyen-vong', 'Ba Nguyện Vọng', 'Fantasia', 'ba nguyện vọng fantasia trương bá chi lưu thanh vân cổ thiên lạc ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-kiem-quy-trao', 'Ấn Kiếm Quỷ Trảo', 'The Hidden Blade', 'https://phimimg.com/upload/vod/20231212-1/5d34fd56dd926dc38ea69733199de1a7.jpg', 'https://phimimg.com/upload/vod/20231212-1/75578053eb478b53b101e1a38888b25f.jpg', '<p>Bộ phim chủ yếu dựa vào câu chuyện trong tiểu thuyết Ẩn chi kiếm viết thành kịch bản. Đó là những năm tháng cuối cùng của thời đại Mạc Phủ, những con người của tầng lớp thấp nhất trong xã hội vì muốn sinh tồn mà không ngừng tranh chấp và đau đớn, cùng với sự khát khao trong tình yêu... Câu chuyện xảy ra tại phiên trấn giả tưởng Umisaka ở miềng Đông Bắc nước Nhật, vào cuối thời Mạc phủ Edo. Nửa đầu phim có nhịp điệu khá trầm, chủ yếu miêu tả tình cảm nhẹ nhàng của Katagiri Munezō với cô hầu gái Kie. Sau khi Kie đi lấy chồng, Munezō trải qua những ngày tháng tẻ nhạt, giữ gìn tiết tháo của một Samurai điển hình trong bối cảnh đất nước ngày càng Âu hóa, tiếp xúc với nhiều thứ văn minh từ phương Tây. Nhưng tình yêu thầm kín của một Samurai dành cho nàng hầu gái là điều không thể chấp nhận được trong cái xã hội cũ kỹ vẫn chưa thoát khỏi những suy nghĩ lạc hậu của đám Samurai nơi quê mùa. Nửa sau của bộ phim biến chuyển khá nhanh, khi Munezō hay tin một thân hữu của mình là Hazama Yaichirō tạo phản chống lại Mạc phủ, bị đầy về xứ để hành hình. Qua bao nhiêu âm mưu bẩn thỉu của đám quan lại bất tài, Munezō bị buộc phải giết chết người bằng hữu của mình với danh nghĩa giúp phiên trấn thanh trừng phản loạn. Nhưng rồi biết được vợ của Hazama bị lợi dụng trong vụ việc này nên đâm cổ tự sát theo chồng, Munezō quyết tâm dùng bí chiêu “ẩn kiếm quỷ trảo” để báo thù cho bạn mình.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masatoshi Nagase","avatar":""},{"name":"Takako Matsu","avatar":""},{"name":"Hidetaka Yoshioka","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324528);
