INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-dieu-duc-cam', 'Giai Điệu Dục Cảm', '9 Songs', 'https://phimimg.com/upload/vod/20231211-1/05ab6403d2c1d6fb87d951a7b6ee5fe2.jpg', 'https://phimimg.com/upload/vod/20231211-1/42ebef82b6bfec812a6da93552c4732e.jpg', '<p>Matt, một nhà nghiên cứu về sông băng trẻ tuổi, bay vút qua vùng băng giá rộng lớn, im lặng của Nam Cực khi anh nhớ lại mối tình của mình với Lisa. Họ gặp nhau tại một buổi hòa nhạc rock đông đúc trong hội trường âm nhạc rộng lớn - Học viện Brixton ở London. Họ đang ở trên giường vào cuối đêm. Cùng nhau, trong khoảng thời gian vài tháng, họ theo đuổi niềm đam mê tình dục chung mà các giai đoạn không thể tránh khỏi diễn ra trái ngược với chín bài hát trong buổi hòa nhạc trực tiếp.</p>', 'Full', 1, 'single', 'completed', 9, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kieran O''Brien","avatar":""},{"name":"Margo Stilley","avatar":""},{"name":"Courtney Taylor-Taylor","avatar":""},{"name":"Alex Kapranos","avatar":""},{"name":"Guy Garvey","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
