INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doat-mang', 'Đoạt Mạng', 'Taking Lives', 'https://phimimg.com/upload/vod/20231211-1/997abf766e580e77bb5af1b726ca7bb9.jpg', 'https://phimimg.com/upload/vod/20231211-1/3cca35b10e2cb6be52b77e4a2df4d4e6.jpg', '<p>Kẻ sát nhân cuồng loạn nhưng cực kỳ thông minh tinh quái, sau mỗi lần giết chết một nạn nhân, hắn sẽ mượn danh họ và sống bằng cuộc đời kẻ xấu số, nhưng mỗi khi cảnh sát tìm thấy xác nạn nhân thì hắn đã có một nạn nhân mới, một cuộc đời mới. Illeana đến Montreal với quyết tâm truy tìm kẻ hung thủ nhưng cô đâu có ngờ cô trở thành mục tiêu săn đuổi mới của hắn…</p>', 'Full', 1, 'single', 'completed', 10, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Angelina Jolie","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Kiefer Sutherland","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
