INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chasing-liberty', 'Chasing Liberty', 'Chasing Liberty', 'https://phimimg.com/upload/vod/20231211-1/62d8551f1f3f3c8bdf8c234ba5b9b7af.jpg', 'https://phimimg.com/upload/vod/20231211-1/9a565296db1ede77c2af236ed5955a29.jpg', '<p>Con gái của Tổng thống, không thể trải nghiệm cuộc sống như một thanh niên 18 tuổi bình thường, đã trốn thoát khỏi đoàn tùy tùng của các Mật vụ khi đi du lịch ở Châu Âu. Cô phải lòng một anh chàng lạ mặt người Anh đẹp trai, người cũng tình cờ làm việc cho cha cô.</p>', 'Full', 1, 'single', 'completed', 10, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mandy Moore","avatar":""},{"name":"Matthew Goode","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Annabella Sciorra","avatar":""},{"name":"Stark Sands","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
