INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chasing-liberty', 'Chasing Liberty', 'Chasing Liberty', 'chasing liberty chasing liberty mandy moore matthew goode jeremy piven annabella sciorra stark sands ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-chorus', 'The Chorus', 'Les Choristes', 'https://phimimg.com/upload/vod/20231211-1/c96248a39cf14fe3083e78a7a58f27d6.jpg', 'https://phimimg.com/upload/vod/20231211-1/2ce68e82e86faaf628c77203a43c1a6c.jpg', '<p>Fond de letang là một trường nội trú cho các chàng trai gặp khó khăn nằm ở vùng nông thôn Pháp. Vào giữa thế kỷ XX, nó được điều hành bởi hiệu trưởng M. Rachin, một kỷ luật tự cao tự đại, có câu thần chú không chính thức cho trường là hành động - phản ứng, có nghĩa là sẽ có hậu quả nghiêm trọng đối với bất kỳ cậu bé nào ngoài dòng. Cách tiếp cận này dường như không hoạt động như các chàng trai như một tập thể là một bó ngang bậy. Đổi lại, các giáo viên không dạy, nhưng luôn luôn theo dõi hành động lật đổ tiếp theo từ các chàng trai. Ngày 15 tháng 1 năm 1949 đánh dấu sự xuất hiện đến trường của người giám sát mới, M. Clément Mathieu, một người đàn ông trung niên đang nắm bắt trong việc tìm vị trí của mình trong cuộc sống sau một loạt các nỗ lực thất bại. Mặc dù anh ta tìm thấy các chàng trai một người bất cẩn rất nhiều, Mathieu không tin vào chính sách hành động - phản ứng, và như vậy, Butts Heads với Rachin trong khi bí mật làm suy yếu chính sách. Từ từ, cách tiếp cận của Mathieu để cố gắng phù hợp với kỷ luật với tội phạm có tác động tích cực đến một số ít học sinh. Với sự chấp thuận miễn cưỡng của Rachin, Mathieu bắt đầu một thí nghiệm lớn hơn khi cố gắng biến đổi bầu không khí chung trong trường, cốt lõi trong thí nghiệm để bắt đầu một dàn hợp xướng giữa các sinh viên của mình. Động thái này là một điều khó khăn cho anh ta như một nhạc sĩ thất bại, cũng như đối với các sinh viên không giới hạn ban đầu. Trong quá trình này, Mathieu tập trung vào hai học sinh khác nhau vì hai lý do khác nhau. Pépinot, một cậu bé, dường như thiếu sự hướng dẫn và tập trung, và người luôn nói rằng anh ta đang đợi thứ bảy khi cha anh ta sẽ đón anh ta, người không bao giờ làm. Và Pierre Morhange, một học sinh lớn tuổi, là một sự lỗi thời: hướng nội, nhưng dễ bị bộc phát về sự khuất phục cá nhân - ác quỷ với khuôn mặt của một thiên thần như những giáo viên khác mô tả anh ta. Đằng sau lý do cho sự khuất phục của mình, Mathieu nào từ từ học hỏi, Morhange che giấu một tình yêu âm nhạc và một tài năng thực sự trong đó. Ngoài việc vượt qua những trở ngại rõ ràng của Rachin và chủ nghĩa hoài nghi của học sinh và âm đại của Rachin, Mathieu có một thách thức khác trong Pascal Mondain mới đến, một cậu bé lớn hơn bối rối với xu hướng bệnh lý có sự hiện diện một mình có thể tàn phá trong trường, và không chỉ với dự án của Mathieu . Hơn năm mươi năm sau, Morhange và Pépinot, những người đã không gặp nhau kể từ thời điểm đó và không dành nhiều thời gian cho nhau khi ở trường, đang đọc qua hồi ký của Mathieu từ thời của ông ở trường, điều này unmasks Lý do tại sao hai người được tư nhân vào hồi ký và hiệu ứng anh ta có trong cuộc sống của họ</p>', 'Full', 1, 'single', 'completed', 29, 2004, 'Vietsub', 'HD', 'Pháp', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324528);
