INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('immortal', 'Immortal', 'Immortal', 'https://phimimg.com/upload/vod/20231210-1/12ad95d8502ab651f32941c6065d8e19.jpg', 'https://phimimg.com/upload/vod/20231210-1/366ee24a10304fc6223789907d7ffc85.jpg', '<p>Trong tương lai xa, Trái đất bị chiếm giữ bởi các vị thần cổ đại và con người bị biến đổi gen. Khi một vị thần bị kết án tử hình, anh ta tìm kiếm một vật chủ mới là con người và một người phụ nữ để sinh con cho anh ta.</p>', 'Full', 1, 'single', 'completed', 9, 2004, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Linda Hardy","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Charlotte Rampling","avatar":""},{"name":"Yann Collette","avatar":""},{"name":"Frédéric Pierrot","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
