INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giay-cua-nguoi-chet', 'Giày Của Người Chết', 'Dead Man''s Shoes', 'https://phimimg.com/upload/vod/20231211-1/e634b0b5ba9b152b9b458250c679f861.jpg', 'https://phimimg.com/upload/vod/20231211-1/c8d06626a9d06eae512b1c15bba12ce3.jpg', '<p>Một người lính trở về thị trấn nhỏ của mình và thực hiện một cuộc trả thù chết người đối với những tên côn đồ đã hành hạ người anh trai đần độn của anh ta khi anh ta đi vắng.</p>', 'Full', 1, 'single', 'completed', 8, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paddy Considine","avatar":""},{"name":"Gary Stretch","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Jo Hartley","avatar":""},{"name":"Seamus O''Neill","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
