INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-cong-chua-2-dam-cuoi-hoang-gia', 'Nhật Ký Công Chúa 2: Đám Cưới Hoàng Gia', 'The Princess Diaries 2: Royal Engagement', 'https://phimimg.com/upload/vod/20231211-1/c482986df8b6440b15a2dbb279f6cd75.jpg', 'https://phimimg.com/upload/vod/20231211-1/548a7f050e50d49e0545e9286ce6abff.jpg', '<p>Công chúa Mia giờ đã bước sang tuổi 21 và chuẩn bị thừa kế ngôi vị Nữ hoàng Genovia từ bà ngoại Clarisse. Nhưng Bá tước Mabrey lại muốn cháu trai của mình Nicholas Devereaux lên ngôi trị vì đất nước này vì một người phụ nữ chưa kết hôn không thể trở thành nữ hoàng. Với sự hậu thuẫn của quốc hội, ông ta ra sức phản đối sự đăng quang của Mia. Nhưng Nữ hoàng Clarisse cho rằng công chúa có quyền tìm cho mình một người chồng trong thời hạn 30 ngày. Bá tước không chịu thua, quyết phá hỏng kế hoạch đó bằng được. Vấn đề rắc rối ở chỗ Nicholas gặp Mia và hai người ngay lập tức phải lòng nhau. Tuy nhiên, sau khi biết anh ta là ai thì công chúa không còn tin vào Nicholas nữa. Nữ hoàng Clarisse cho rằng nên mời anh ta nghỉ lại trong thời gian 30 ngày để tiện theo dõi âm mưu của ông Bá tước và người cháu trai. Kết cục câu chuyện tranh chấp ngôi vị trong hoàng gia này sẽ đi đến đâu?</p>', 'Full', 1, 'single', 'completed', 7, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Julie Andrews","avatar":""},{"name":"Hector Elizondo","avatar":""},{"name":"John Rhys-Davies","avatar":""},{"name":"Heather Matarazzo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":