INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('papa-loves-you', 'PaPa Loves You', 'PaPa Loves You', 'null', 'https://phimimg.com/upload/vod/20231211-1/168d8c9e77e8c5549c071d327559fd7e.jpg', '<p>Ellen nổi loạn (Charlene Choi) nghiện võ thuật, nhưng xấu hổ với cha mình, một người cha đơn thân và một giáo viên piano hèn nhát Yam (Tony Leung Ka-Fai). Thế là xảy ra những cuộc tranh chấp hài hước không ngớt. Tuy nhiên, khi Yam đau lòng, anh lại nhầm trở thành thủ lĩnh Hung, điều này khiến Ellen cảm thấy tự hào và khuấy động rắc rối khắp nơi. Cuối cùng, cô ấy gặp rắc rối và Yam bị sỉ nhục vì cô ấy; sau đó Ellen cảm động và làm theo đức tính tôn trọng người khác.</p>', 'Full', 1, 'single', 'completed', 10, 2004, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tony Ka Fai Leung","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Steven Cheung","avatar":""},{"name":"Steven Cheung Chi Hang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324528);
