INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('80-ngay-vong-quanh-the-gioi', '80 Ngày Vòng Quanh Thế Giới', 'Around The World In 80 Days', 'https://phimimg.com/upload/vod/20231209-1/17d8007bd586a9a9ce8895bafc2104b5.jpg', 'https://phimimg.com/upload/vod/20231209-1/73c9863b702ffcd9e9848155d67efc90.jpg', '<p>Tượng Phật Ngọc Bích, bảo vật đem lại bình an và hạnh phúc của người dân làng Lanzhou Trung Quốc đã bị đánh cắp và chuyển sang Anh Quốc. Lau Xing - một trong Thập Hổ Trung Hoa, được cử sang Anh Quốc để đoạt lại Pho tượng báu. Ở Anh, Tượng Phật Ngọc Bích được cất giữ trong Ngân Hàng Anh, và Lau Xing phải đột nhập ngân hàng để cướp lại Pho tượng. Sau khi đoạt được pho tượng, vấn đề khó khăn của Lau Xing là làm sao mang Pho tượng an toàn về Lanzhou.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Thành Long","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Jim Broadbent","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324528);
