INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-gai-tong-thong', 'Con Gái Tổng Thống', 'First Daughter', 'https://phimimg.com/upload/vod/20231209-1/682e14d802cd0edb63dd52f7f41b0a3a.jpg', 'https://phimimg.com/upload/vod/20231209-1/3b6d907455ddfe4b2c20d74c39ed5be1.jpg', '<p>Con Gái Tổng Thống - First Daughter có sự tham gia của Katie Holmes trong vai Samantha MacKenzie, con gái của Tổng thống Hoa Kỳ, người đăng ký học đại học và nảy sinh mối quan hệ với một sinh viên khác (Marc Blucas). Bộ phim theo chân Samantha khi cô trải nghiệm cảm giác tự do mới trong thời gian rời khỏi Nhà Trắng và những thuận lợi và khó khăn trong cuộc sống đại học của cô.</p>', 'Full', 1, 'single', 'completed', 9, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Keaton","avatar":""},{"name":"Amerie","avatar":""},{"name":"Katie Holmes","avatar":""},{"name":"Lela Rochon Fuqua","avatar":""},{"name":"Margaret Colin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
