INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-ngoai-du-kien', 'Cuộc Chiến Ngoài Dự Kiến', 'Spartan', 'https://phimimg.com/upload/vod/20231210-1/e8346979f03408bd7cef44d55745db1b.jpg', 'https://phimimg.com/upload/vod/20231210-1/e873ebfd8b7925ebcac097339f12a0a2.jpg', '<p>Trận Chiến Ngoài Dự Kiến là một bộ phim kể về chuyên gia huấn luyện giỏi nhất của lực lượng đặc nhiệm Delta Force thuộc quân đội Mỹ. Anh chơi thân với Jackie Black, nữ võ sư phụ trách huấn luyện sử dụng dao. Khi Laura Newton, con gái của tổng thống Mỹ và sinh viên đại học Harvard, bị bắt cóc, cơ quan mật vụ không muốn để lộ tin tức ra ngoài vì lo ngại rằng sự nghiệp chính trị của tổng thống có thể bị ảnh hưởng. Anh sẽ làm gì đển giải cứu con tin?</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Val Kilmer","avatar":""},{"name":"Derek Luke","avatar":""},{"name":"William H. Macy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324528);
