INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-mien-dat-hua', 'Đi Tìm Miền Đất Hứa', 'Finding Neverland', 'https://phimimg.com/upload/vod/20231208-1/6816a2c9b6fd6cd9f9c1f6a8842cd5d3.jpg', 'https://phimimg.com/upload/vod/20231208-1/516ab5f09e3f15cdf1fdb20f57eece2f.jpg', '<p>Là một trong những bộ phim được đón chờ nhất trong mùa phim cuối năm 2004. Finding neverland lấy bối cảnh năm 1904 tại London, theo suốt quá trình hình thành ý tưởng và nỗ lực đưa nhân vật Peter Pan đến với công chúng của nhà văn J.M. Barrie, và buổi trình diễn vở kịch Peter Pan tại nhà hát đã thay đổi không chỉ cuộc đời của anh mà còn của tất cả những</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Julie Christie","avatar":""},{"name":"Dustin Hoffman","avatar":""},{"name":"Freddie Highmore","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
