INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-len-trau', 'Mùa Len Trâu', 'Mua Len Trau', 'null', 'https://phimimg.com/upload/vod/20231210-1/ff6c9ff6382f04651de31437947d4c60.jpg', '<p>Chuyện phim dựa trên tác phẩm Mùa len trâu trong tập truyện Hương rừng Cà Mau của nhà văn Sơn Nam, kể về cuộc sống của những người nông dân miền Nam đầu thế kỷ 20. Mỗi khi mùa mưa về, nước tràn ngập mọi nơi, có những người làm nghề &quot;len trâu&quot;, đưa trâu đi tìm cỏ để sống qua mùa lũ.</p>', 'Full', 1, 'single', 'completed', 18, 2004, 'Vietsub', 'HD', 'Việt Nam', 1, '[{"name":"Kim Long Thach","avatar":""},{"name":"Thi Kieu Trinh Nguyen","avatar":""},{"name":"The Lu Le","avatar":""},{"name":"Huu Thanh Nguyen","avatar":""},{"name":"Zan Sram Kra","avatar":""},{"name":"Van Be Truong","avatar":""},{"name":"Nguyen Anh Hoa","avatar":""},{"name":"Tham Nguyen Thi","avatar":""},{"name":"Hoang Nhan Vo","avatar":""},{"name":"Trương Quang Thịnh","avatar":""},{"name":"Nguyen Van Day","avatar":""},{"name":"Thi Thu Tam Cao","avatar":""},{"name":"Huu Phuoc Nguyen","avatar":""},{"name":"Chau Nguyen","avatar":""},{"name":"Trung Truc Thach","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
