INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-football-factory', 'The Football Factory', 'The Football Factory', 'https://phimimg.com/upload/vod/20231208-1/d15758f66a7c40cc8c8a59b50f3fde28.jpg', 'https://phimimg.com/upload/vod/20231208-1/12020094364b0455bc58cc8e1ecfecc7.jpg', '<p>Nhà máy bóng đá không chỉ là một nghiên cứu về nỗi ám ảnh của người Anh với bạo lực bóng đá; Đó là về những người đàn ông đang tìm kiếm quân đội để tham gia, chiến tranh để chiến đấu và những nơi để thuộc về. Một nền văn hóa bị lãng quên của những người đàn ông Anglo-Saxon chán ngấy với việc được nói rằng họ không đủ tốt và sử dụng nắm đấm của họ như một loại thuốc mà họ mô tả là mạnh hơn so với tình dục và các loại thuốc tập hợp. Bắn theo phong cách doanh nghiệp với năng lượng và sự sống động của thiết bị cầm tay, nhà máy bóng đá thật đáng sợ nhưng đầy sự hài hước đau đớn vì những suy nghĩ và hành động cực đoan của bốn nhân vật diễn ra trước chúng ta.</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324528);
