INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ba-trom-cap-phan-dac-biet-giang-sinh', 'Bộ Ba Trộm Cắp: Phần Đặc Biệt Giáng Sinh', 'Trailer Park Boys: Xmas Special', 'https://phimimg.com/upload/vod/20231208-1/33625f29b128a284da4426731c4c2c0e.jpg', 'https://phimimg.com/upload/vod/20231208-1/66eb92c6f2bba9901d84144dfc1e1913.jpg', '<p>Hãy cùng tìm hiểu về bến đỗ nhà lưu động Sunnyvale hồi đó, khi Randy còn làm nghề mại dâm, J-Roc còn chưa hát rap và Barb cùng Lahey còn ở bên nhau.</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"John Paul Tremblay","avatar":""},{"name":"Robb Wells","avatar":""},{"name":"John Dunsworth","avatar":""},{"name":"Patrick Roach","avatar":""},{"name":"Lucy Decoutere","avatar":""},{"name":"Sarah Dunsworth","avatar":""},{"name":"Cory Bowles","avatar":""},{"name":"Barrie Dunn","avatar":""},{"name":"Michael Jackson","avatar":""},{"name":"Shelley Thompson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
