INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bo-ba-trom-cap-phan-dac-biet-giang-sinh', 'Bộ Ba Trộm Cắp: Phần Đặc Biệt Giáng Sinh', 'Trailer Park Boys: Xmas Special', 'bộ ba trộm cắp: phần đặc biệt giáng sinh trailer park boys: xmas special john paul tremblay robb wells john dunsworth patrick roach lucy decoutere sarah dunsworth cory bowles barrie dunn michael jackson shelley thompson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-goi-nho', 'Cuộc Gọi Nhỡ', 'One Missed Call', 'https://phimimg.com/upload/vod/20231204-1/dac4dbee527b2b30f23b64578cbe5b67.jpg', 'https://phimimg.com/upload/vod/20231204-1/3af5744b309e97a51b27aaa563362fec.jpg', '<p>Sau giờ học, Yumi và những người bạn tổ chức một buổi họp nhóm như thường lệ. Cuộc vui đang diễn ra thì điện thoại của cô bạn Yoko đổ một loạt chuông khác thường. Do Yoko không nhấc máy nên một cuộc gọi nhỡ được lưu lại trong điện thoại. Kỳ lạ thay, thời điểm cuộc gọi này được thực hiện lại là ba ngày sau đó. Khi Yoko mở tin nhắn kèm theo cuộc gọi nhỡ, cô bỗng nghe thấy một tiếng thét thất thanh. Tiếng thét của chính cô. Vốn không tin vào những chuyện ma quái, Yoko cho rằng đây chỉ là một trò đùa tinh nghịch của ai đó. Cô gần như không còn bận tâm đến cuộc gọi đó nữa. Nhưng ba ngày sau, đúng vào thời điểm cuộc gọi nhỡ được thực hiện, Yoko đã chết bất đắc kỳ tử khi rơi xuống từ một cây cầu. Mất đi một người bạn, Yumi vô cùng hoang mang. Cô lại càng hoảng sợ hơn khi những người trong nhóm đều lần lượt qua đời một cách bí ẩn sau khi nhận được những cuộc gọi ma quái. Yumi quyết định tìm hiểu chân tướng sự việc. Nhưng rồi một ngày nọ, Yumi kiểm tra điện thoại của mình. Có một cuộc gọi nhỡ...</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Ko Shibasaki","avatar":""},{"name":"Shin''ichi Tsutsumi","avatar":""},{"name":"Kazue Fukiishi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
