INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-lua-ngoan-muc', 'Cú Lừa Ngoạn Mục', 'The Big Swindle', 'https://phimimg.com/upload/vod/20231202-1/6fb1f5f7c1164621d0cb7c636ab56490.jpg', 'https://phimimg.com/upload/vod/20231202-1/d9ec08c0f443422f8e423270d5919583.jpg', '<p>Chang Huyk lập kế hoạch cướp ngân hàng lớn nhất Đại Hàn Dân quốc vô cùng hoàn hảo. Anh tập hợp 5 chuyên gia từ khắp nơi để thực hiện phi vụ 5 tỷ won này, mọi thứ tính đủ đường chỉ chừ một việc họ không tin nhau. Kết thúc phi vụ, số tiền đánh cắp biến mất... Bộ phim Cú lừa ngoạn mục sẽ đem đến những hồi tưởng về vụ cướp và mọi nghi vấn chỉ được giải đáp vào phút cuối cùng..</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Shin-yang","avatar":""},{"name":"Baek Yoon-sik","avatar":""},{"name":"Yum Jung-ah","avatar":""},{"name":"Lee Moon-sik","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Park Won-sang","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Son Ji-na","avatar":""},{"name":"Kim Yoon-seok","avatar":""},{"name":"Son Byeong-uk","avatar":""},{"name":"Jo Hee-bong","avatar":""},{"name":"Im Ha-ryong","avatar":""},{"name":"Yu Seon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324528);
