INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-rong', 'Kiếm Rồng', 'Arahan', 'https://phimimg.com/upload/vod/20231202-1/c88088212c31d149402eb24fd5c10621.jpg', 'https://phimimg.com/upload/vod/20231202-1/f83a7f19097ce2a0a376bfe8e628a099.jpg', '<p>Chàng cảnh sát hậu đậu Sang-hwan đuổi theo tên giật đồ của một người đi đường nhưng bị thương nặng. Tên cướp được nữ hiệp Wi-jin bắt gọn. Cô đưa Sang-hwan về võ đường để chăm sóc. Tại đây, Sang-hwan được diện kiến 6 vị sư phụ và biết đến Khí, nguồn năng lượng của mọi sinh thể trong vũ trụ, có thể biến bất kỳ ai thành một đấu sỹ đầy sức mạnh. Sang-hwan bắt đầu công cuộc tập luyện. Cùng lúc, tên nghịch đồ Heuk-woon vượt ngục và quay về tấn công các vị sư phụ để đoạt bí kíp Arahan. Khi các vị sư phụ đã bị đả bại, chỉ còn Sang-hwan và Wi-jin là hy vọng cuối cùng của sư môn, thậm chí cả thế giới. Nhưng liệu họ có đảm đương được sứ mệnh to lớn này không?</p>', 'Full', 1, 'single', 'completed', 18, 2004, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Ryoo Seung-bum","avatar":""},{"name":"Yoon Soy","avatar":""},{"name":"Ahn Sung-ki","avatar":""},{"name":"Jung Doo-hong","avatar":""},{"name":"Yoon Joo-sang","avatar":""},{"name":"Ahn Kil-kang","avatar":""},{"name":"Baek Chan-Ki","avatar":""},{"name":"Lee Won","avatar":""},{"name":"Lee Oi-soo","avatar":""},{"name":"Kim Dong-joo","avatar":""},{"name":"Im Ha-ryong","avatar":""},{"name":"Bong Tae-gyu","avatar":""},{"name":"Park Yoon-Bae","avatar":""},{"name":"Hyo-Seon Kim","avatar":""},{"name":"Woo Jung-kook","avatar":""},{"name":"Yang Ik-june","avatar":""},{"name":"Min Hye-Ryeong","avatar":""},{"name":"Kim Yeong-in","avatar":""},{"name":"Lee Dae-","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
