INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-xuyen-vu-tru-phan-3', 'Trận Chiến Xuyên Vũ Trụ (Phần 3)', 'Stargate: Atlantis (Season 3)', 'https://phimimg.com/upload/vod/20231203-1/fc212d3668d1871162b7dbaaa55d4e26.jpg', 'https://phimimg.com/upload/vod/20231203-1/9ffa57cb58564cf7924e1de11a426c03.jpg', '<p>Stargate Atlantis là 1 trong những bộ phim hành động viễn tưởng hay nhất mọi thời đại. Dưới sự dẫn dắt của đội trưởng John Sheppard, đội SG1 có những chuyến du hành vượt không gian, tới những hành tinh có nền công nghệ cao hơn nhằm tiêu diệt kẻ thù. Những kỹ xảo ấn tượng trong cuộc giao chiến cùng những pha hành động đẹp mắt chắc chắn sẽ khiến các fan của phim hành động không thể bỏ qua series phim đặc biệt này.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joe Flanigan","avatar":""},{"name":"Rachel Luttrell","avatar":""},{"name":"David Hewlett","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324528);
