INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tamamono', 'Tamamono', 'Mối Tình Câm Lặng', 'https://phimimg.com/upload/vod/20231211-1/1484aec3d67255c67978fde6dae961dc.jpg', 'https://phimimg.com/upload/vod/20231211-1/e909d8e5590628a1686fd8f0e485a3f3.jpg', '<p>Phim kể về câu chuyện của Aiko, một phụ nữ câm 35 tuổi làm việc trong một sân chơi bowling, và mối tình ngắn ngủi của cô với Yoshioka, một chàng trai trẻ làm công việc đưa thư. Cả hai gặp nhau khi Aiko vô tình hất ngã Yoshioka khỏi xe đạp và họ có quan hệ tình dục ngay sau đó. Aiko bắt đầu chuẩn bị những hộp cơm trưa và đưa cho Yoshioka tại nơi làm việc của anh ấy như một cách thể hiện tình cảm, điều mà cô ấy không thể thực hiện bằng lời nói.</p>', 'Full', 1, 'single', 'completed', 7, 2004, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yumika Hayashi","avatar":""},{"name":"Mutsuo Yoshioka","avatar":""},{"name":"Lemon Hanazawa","avatar":""},{"name":"Kiyomi Itō","avatar":""},{"name":"Yohta Kawase","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
