INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mickeys-twice-upon-a-christmas', 'Mickey''s Twice Upon a Christmas', 'Mickey''s Twice Upon a Christmas', 'https://phimimg.com/upload/vod/20231130-1/ba23dcdf2df6aa1d77188ada79fdcc26.jpg', 'https://phimimg.com/upload/vod/20231130-1/e42ef8e0536339245c51cbb879c221d9.jpg', '<p>Ông già Noel, chuột Mickey và tất cả những người bạn Disney của ông góp mặt trong một bộ phim gốc nói về tầm quan trọng của việc mở rộng trái tim đón nhận tinh thần thực sự của Giáng sinh. Donald già cứng đầu cố gắng chống lại niềm vui của mùa trong vô vọng. Mickey và Pluto học được bài học lớn về sức mạnh của tình bạn.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wayne Allwine","avatar":""},{"name":"Tony Anselmo","avatar":""},{"name":"Bill Farmer","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Tress MacNeille","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Jason Marsden","avatar":""},{"name":"Chuck McCann","avatar":""},{"name":"Clive Revill","avatar":""},{"name":"Russi Taylor","avatar":""},{"name":"Alan Young","avatar":""},{"name":"Gregg Berger","avatar":""},{"name":"Cork Hubbert","avatar":""},{"name":"Kellie Martin","avatar":""},{"name":"Edie McClurg","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Peter Siragusa","avatar":""},{"name":"Gene Weygandt","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324528);
