INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-quy', 'Người Quỷ', 'Devilman', 'https://phimimg.com/upload/vod/20231211-1/850d189525d0e09530924f74cc21d35f.jpg', 'https://phimimg.com/upload/vod/20231211-1/f07e2c0377c094624137245d168739e1.jpg', '<p>Một cuộc thám hiểm khoa học nhằm tìm kiếm một nguồn năng lượng mới đã giải phóng một nhóm ác quỷ mạnh mẽ bắt đầu chiếm hữu cơ thể con người và hủy diệt nền văn minh. Đôi bạn thân Akira và Ryo ở hai phe khác nhau trong cuộc đấu tranh hoành tráng này. Sức mạnh bên trong của Akira cho phép anh duy trì danh tính của mình và chiến đấu vì điều tốt đẹp, nhưng Ryo yếu hơn đã hoàn toàn bị chính Satan vượt qua.</p>', 'Full', 1, 'single', 'completed', 9, 2004, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hisato Izaki","avatar":""},{"name":"Yûsuke Izaki","avatar":""},{"name":"Ayana Sakai","avatar":""},{"name":"Asuka Shibuya","avatar":""},{"name":"Ryûdô Uzaki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324528);
