INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-y-nhe-em', 'Đồng Ý Nhé Em', 'Say I Do', 'https://phimimg.com/upload/vod/20231130-1/653c8cb85be55e318f631a040c607946.jpg', 'https://phimimg.com/upload/vod/20231130-1/b302eea73462e894473ffa9ff3d107c6.jpg', '<p>Hàng loạt hiểu lầm khiến Estrella sôi nổi thành đôi cùng Victor nhút nhát và do dự trên một chương trình hẹn hò – trong đó họ bất đắc dĩ phải kết hôn.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Santi Millán","avatar":""},{"name":"Paz Vega","avatar":""},{"name":"Constantino Romero","avatar":""},{"name":"Chus Lampreave","avatar":""},{"name":"Santiago Segura","avatar":""},{"name":"Ornella Muti","avatar":""},{"name":"José Luis Torrijo","avatar":""},{"name":"Pepe Viyuela","avatar":""},{"name":"Skizzo Arnedillo","avatar":""},{"name":"Fernando Caballero","avatar":""},{"name":"Sagrario Calero","avatar":""},{"name":"Guacimara Correa","avatar":""},{"name":"Luis Cuenca","avatar":""},{"name":"Lucas Fuica","avatar":""},{"name":"Karla Sofía Gascón","avatar":""},{"name":"Daniel Grao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
