INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-than-tien', 'Câu Chuyện Thần Tiên', 'Ella Enchanted', 'https://phimimg.com/upload/vod/20231129-1/d85ea0ef7c016e33cd43e35b18987eb5.jpg', 'https://phimimg.com/upload/vod/20231129-1/a5f8f71056844d22f1ccd24ce40fd3b5.jpg', '<p>Ella sống trong một thế giới kỳ diệu, trong đó mỗi đứa trẻ, vào thời điểm sinh ra, đều được tặng một &quot;món quà&quot; nhân đức; từ một bà tiên đỡ đầu. Tuy nhiên, cái gọi là năng khiếu của Ella lại là sự vâng lời. Quyền thừa kế này chứng tỏ mình là một lời nguyền khi Ella thấy mình nằm trong tay của một số nhân vật vô đạo đức mà cô ấy thực sự không thể làm trái lời. Quyết tâm giành quyền kiểm soát cuộc sống và các quyết định của mình, Ella bắt đầu cuộc hành trình tìm kiếm bà tiên đỡ đầu, người mà cô hy vọng sẽ hóa giải lời nguyền. Tuy nhiên, con đường này không hề dễ dàng - Ella phải vượt qua hàng loạt chướng ngại vật khó chịu bao gồm yêu tinh, người khổng lồ, chị kế độc ác, yêu tinh và người chú độc ác của Hoàng tử Charmont, người muốn chiếm lấy vương miện và cai trị vương quốc.</p>', 'Full', 1, 'single', 'completed', 16, 2004, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Hugh Dancy","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Vivica A. Fox","avatar":""},{"name":"Joanna Lumley","avatar":""},{"name":"Jimi Mistry","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Aidan McArdle","avatar":""},{"name":"Heidi Klum","avatar":""},{"name":"Jim Carter","avatar":""},{"name":"Jennifer Higham","avatar":""},{"name":"Parminder Nagra","avatar":""},{"name":"Lucy Punch","avatar":""},{"name":"Minnie Driver","avatar":""},{"name":"Patrick Bergin","avatar":""},{"name":"Eric Idle","avatar":""},{"name":"Alvaro Lucchesi","avatar":""},{"name":"Donna Dent","avatar":""},{"name":"Par","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
