INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-sinh-diep-vien', 'Nữ Sinh Điệp Viên', 'D.E.B.S.', 'https://phimimg.com/upload/vod/20231129-1/b666307caed1362c9999783142ba071a.jpg', 'https://phimimg.com/upload/vod/20231129-1/58e08665c6481d4bc520f3cf1fd40a7c.jpg', '<p>Khi bốn cô nàng vượt qua bài kiểm tra SAT vốn bí mật đo lường tiềm năng gián điệp của một thiếu niên, họ được chiêu mộ vào nhóm bán quân sự ưu tú D.E.B.S.</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sara Foster","avatar":""},{"name":"Meagan Good","avatar":""},{"name":"Jordana Brewster","avatar":""},{"name":"Devon Aoki","avatar":""},{"name":"Jill Ritchie","avatar":""},{"name":"Christina Kirk","avatar":""},{"name":"Geoff Stults","avatar":""},{"name":"Jimmi Simpson","avatar":""},{"name":"Holland Taylor","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Jessica Cauffiel","avatar":""},{"name":"J.B. Ghuman Jr.","avatar":""},{"name":"Scoot McNairy","avatar":""},{"name":"Jean St. James","avatar":""},{"name":"Eric Dearborn","avatar":""},{"name":"Jenny Mollen","avatar":""},{"name":"Aimee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324528);
