INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-dinh-menh-2004', 'Chuyến Bay Định Mệnh', 'Flight of the Phoenix', 'https://phimimg.com/upload/vod/20231129-1/c39e04472c6c71df5230c165b175fed2.jpg', 'https://phimimg.com/upload/vod/20231129-1/82aa2807d70d08a9f5e810b8fa3d9e7f.jpg', '<p>Một nhóm người sống sót vụ tai nạn hàng không bị mắc kẹt trong sa mạc Mông Cổ không có cơ hội giải cứu. Đối mặt với một môi trường tàn bạo, tài nguyên cạn kiệt, và một cuộc tấn công của những kẻ buôn lậu sa mạc, họ nhận ra hy vọng duy nhất của họ làm được những điều không thể... Đó là xây dựng một chiếc máy bay mới từ đống đổ nát cách đây một năm...</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dennis Quaid","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Miranda Otto","avatar":""},{"name":"Tony Curran","avatar":""},{"name":"Sticky Fingaz","avatar":""},{"name":"Jacob Vargas","avatar":""},{"name":"Hugh Laurie","avatar":""},{"name":"Scott Michael Campbell","avatar":""},{"name":"Kevork Malikyan","avatar":""},{"name":"Jared Padalecki","avatar":""},{"name":"Paul Ditchfield","avatar":""},{"name":"Martin Hindy","avatar":""},{"name":"Bob Brown","avatar":""},{"name":"Anthony Brandon Wong","avatar":""},{"name":"Derek Barton","avatar":""},{"name":"Jim","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324528);
