INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hat-tao', 'Hạt Táo', 'Appleseed', 'https://phimimg.com/upload/vod/20231129-1/323d9837cefdeb029e783c169d849008.jpg', 'https://phimimg.com/upload/vod/20231129-1/bfca1df996826bdbff5f48febc7512c3.jpg', '<p>Trong một xã hội không tưởng được tạo ra vào cuối chiến tranh thế giới thứ ba, một nữ chiến binh bị bắt khỏi vùng đất cằn cỗi bắt đầu nhìn thấy những vết nứt trên mặt tiền mới này. Và cộng đồng này đã lên kế hoạch gì cho phần còn lại của nhân loại?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2004, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ai Kobayashi","avatar":""},{"name":"Asumi Miwa","avatar":""},{"name":"Jurota Kosugi","avatar":""},{"name":"Yuki Matsuoka","avatar":""},{"name":"Yuzuru Fujimoto","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Mami Koyama","avatar":""},{"name":"Miho Yamada","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Ryuji Nakagi","avatar":""},{"name":"Fumio Matsuoka","avatar":""},{"name":"Hirotake Nagata","avatar":""},{"name":"Norihiko Kuwagaki","avatar":""},{"name":"Yoshiyuki Kaneko","avatar":""},{"name":"Ikuo Nishikawa","avatar":""},{"name":"Takehiro Koyama","avatar":""},{"name":"Em","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324528);
