INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('com-chim-com-noi', 'Cớm Chìm, Cớm Nổi', 'Starsky & Hutch', 'https://phimimg.com/upload/vod/20231129-1/6e0a7e7b09cd9228049748777330c2f3.jpg', 'https://phimimg.com/upload/vod/20231129-1/b50863c466a6dc3d871c882fd74cf790.jpg', '<p>Nằm trong những năm 1970 trong một đô thị tên là &quot;Bay City&quot;, đây là câu chuyện về hai đối tác thám tử cảnh sát, Ken &quot;Hutch&quot; Hutchinson, và Dave Starsky, người dường như luôn có những trường hợp khó khăn nhất từ sếp của họ, Đội trưởng Dobey, dựa vào Omniscient Street Informer Gấu và cuộc đua đến hiện trường của những tội ác trong Quả nóng Ford Torino năm 1974 của họ, kể câu chuyện về trường hợp lớn đầu tiên của họ (như một tiền truyện cho chương trình truyền hình), liên quan đến một cựu đại lý ma túy trường đại học người đã tiếp tục trở thành một tên tội phạm cổ trắng.</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Snoop Dogg","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Fred Williamson","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"Carmen Electra","avatar":""},{"name":"George Cheung","avatar":""},{"name":"Chris Penn","avatar":""},{"name":"Brande Roderick","avatar":""},{"name":"Molly Sims","avatar":""},{"name":"Matt Walsh","avatar":""},{"name":"G.T. Holme","avatar":""},{"name":"Jeffrey Lorenzo","avatar":""},{"name":"Har Mar Superstar","avatar":""},{"name":"Patton Oswal","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324528);
