INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chu-duong-dua', 'Bá Chủ Đường Đua', 'Torque', 'https://phimimg.com/upload/vod/20231124-1/c75c28cb9fca89957ff048cd85307d7d.jpg', 'https://phimimg.com/upload/vod/20231124-1/62ec22d0e1f81c2d5851d36b31cdcf88.jpg', '<p>Biker Cary Ford bị một đối thủ cũ và thủ lĩnh băng đảng mô tô đóng khung vì tội giết một thành viên băng đảng khác, người tình cờ là anh trai của Trey, thủ lĩnh của băng đảng mô tô đáng sợ nhất đất nước. Ford hiện đang chạy trốn để cố gắng xóa tên của mình khỏi vụ giết người với Trey và băng nhóm của anh ta đang tìm kiếm máu của anh ta.</p>', 'Full', 1, 'single', 'completed', 16, 2004, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Martin Henderson","avatar":""},{"name":"Ice Cube","avatar":""},{"name":"Monet Mazur","avatar":""},{"name":"Jaime Pressly","avatar":""},{"name":"Matt Schulze","avatar":""},{"name":"Jay Hernandez","avatar":""},{"name":"Christina Milian","avatar":""},{"name":"Faizon Love","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"Joseph Kahn","avatar":""},{"name":"John Ashker","avatar":""},{"name":"Max Beesley","avatar":""},{"name":"Dane Cook","avatar":""},{"name":"John Doe","avatar":""},{"name":"Gichi Gamba","avatar":""},{"name":"Lance Gilbert","avatar":""},{"name":"Will Yun Lee","avatar":""},{"name":"Justina Machado","avatar":""},{"name":"Hayden M","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324528);
