INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-thanh-troy', 'Người Hùng Thành Troy', 'Troy', 'https://phimimg.com/upload/vod/20231124-1/ee06104571b6f7224ec0ddb7315526d5.jpg', 'https://phimimg.com/upload/vod/20231124-1/89dd14d8d09717065aa8d4c18141534a.jpg', '<p>Trong suốt các thời đại, đàn ông đã gây chiến. Một số cho quyền lực, một số cho vinh quang hoặc danh dự, và một số cho tình yêu. Ở Hy Lạp cổ đại, niềm đam mê của hai người tình huyền thoại nhất trong lịch sử là Paris, Hoàng tử thành Troia (Orlando Bloom) và Helen (Diane Kruger), Nữ hoàng Sparta, đã mở ra một cuộc chiến tranh tàn phá nền văn minh. Vụ bắt cóc Helen bởi Paris, tách cô khỏi chồng mình, Vua Menelaus (Bren-dan Gleeson), là một sự xúc phạm mà Family Pride cho rằng đối mặt với Menelaus là một mối quan hệ với anh trai của cô là Agamemnon (Brian Cox), vị vua quyền lực của cô Mycenae, người sớm tái hợp tất cả các bộ lạc lớn của Hy Lạp để phục hồi Helen khỏi Trojans và bảo vệ danh dự của anh trai cô. Sự thật là cuộc chiến vì danh dự của Agamemnon bị hủy hoại bởi lòng tham không thể kiểm soát của anh ta khi anh ta cần phải chinh phục thành Troia để giành quyền kiểm soát Biển Aegean.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Eric Bana","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"Peter O''Toole","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Saffron Burrows","avatar":""},{"name":"Garrett Hedlund","avatar":""},{"name":"Vincent Regan","avatar":""},{"name":"Julie Christie","avatar":""},{"name":"Nathan Jones","avatar":""},{"name":"Mark Lewis Jones","avatar":""},{"name":"John Shrapnel","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Nigel Te","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324528);
