INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truoc-luc-hoang-hon', 'Trước Lúc Hoàng Hôn', 'Before Sunset', 'https://phimimg.com/upload/vod/20231123-1/f393f590232831a0599b1d826a38654a.jpg', 'https://phimimg.com/upload/vod/20231123-1/77ee3f0cb1c6e73fa51fccfe81169e81.jpg', '<p>Jesses (Ethan Hawke), một nhà văn trẻ, trong buổi ở Paris giới thiệu sách mới của mình, anh gặp lại Celine (Julie Delpy). Celine là người bạn anh quen cách đây 9 năm, là nguồn cảm hứng cho anh viết được cuốn sách hiện tại. Vì thời gian có hạn, Jesses chỉ có khoảng 20 phút gặp Celine trước khi ra phi trường đi tiếp. Hai người bạn gặp gỡ nhau, nói với nhau rất nhiều chuyện về công việc, gia đình. Trong phim Trước Lúc Hoàng Hôn hay Before Sunset có sự hiện diện của các diễn viên như Ethan Hawke, Julie Delpy, Vernon Dobtcheff với Richard Linklater là đạo diễn. Họ cũng nhớ lại khoảng thời gian 9 năm trước khi lần đầu gặp nhau. Phim có độ dài đến 80 phút được phát hành vào năm 2004. Các bạn đang xem phim Trước Lúc Hoàng Hôn hay Before Sunset, đây là phim ...</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Julie Delpy","avatar":""},{"name":"Vernon Dobtcheff","avatar":""},{"name":"Louise Lemoine Torrès","avatar":""},{"name":"Rodolphe Pauly","avatar":""},{"name":"Mariane Plasteig","avatar":""},{"name":"Diabolo","avatar":""},{"name":"Denis Evrard","avatar":""},{"name":"Albert Delpy","avatar":""},{"name":"Marie Pillet","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324528);
