INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ma-theo-duoi', 'Hồn Ma Theo Đuổi', 'Shutter', 'https://phimimg.com/upload/vod/20231123-1/697d599d98984bdd3b81b3f4feb95bb5.jpg', 'https://phimimg.com/upload/vod/20231123-1/7cb9ac4da4b930d8ae5b26a11dd9032e.jpg', '<p>Trên đường về từ đám cưới của cậu bạn thân Tonn, xe của Tun và cô bạn gái là Jane đụng phải 1 cô gái. Trong cơn hoảng loạn, Tun đã giục Jane lái xe đi bỏ mặc sự sống chết của nạn nhân. &nbsp;Sau tai nạn đó, Jane luôn gặp ác mộng. Mỗi ngày cô phải sống trong sự thấp thỏm, lo âu và hối hận. Trong khi đó Tun lại xem như không có chuyện gì xảy ra. Cho đến khi những đốm sáng kì lạ xuất hiện trên các bức ảnh của Tun và những người bạn của anh lần lượt chết 1 cách khó hiểu, cơn ác mộng thật sự mới bắt đầu… &nbsp;Lần theo dấu vết của những đốm sáng bí ẩn đó, Jane phát hiện tất cả chúng hợp thành khuôn mặt của một cô gái. Cô gái này chính là bạn gái cũ của Tun, những bí mật đen tối nhất trong quá khứ dần dần được hé mở…</p>', 'Full', 1, 'single', 'completed', 18, 2004, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Ananda Everingham","avatar":""},{"name":"Natthaweeranuch Thongmee","avatar":""},{"name":"Achita Sikamana","avatar":""},{"name":"Unnop Chanpaibool","avatar":""},{"name":"Titikarn Tongprasearth","avatar":""},{"name":"Sivagorn Muttamara","avatar":""},{"name":"Chachchaya Chalemphol","avatar":""},{"name":"Kachornsak Naruepatr","avatar":""},{"name":"Apichart Chusakul","avatar":""},{"name":"Binn Kitchachonpong","avatar":""},{"name":"Panitan Mavichak","avatar":""},{"name":"Samruay Jaratjaroonpong","avatar":""},{"name":"Ji","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","