INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-huynh-de-co-bay-phap-phoi', 'Tình Huynh Đệ - Cờ Bay Phấp Phới', 'Tae Guk Gi: The Brotherhood Of War', 'https://phimimg.com/upload/vod/20231123-1/1319b3769c90ad70d90086eb4dabb7d7.jpg', 'https://phimimg.com/upload/vod/20231123-1/7b2d6dedd3aa1acb49d62d8bb1f6eec3.jpg', '<p>Tình Huynh Đệ - Cờ Bay Phấp Phới - Tae Guk Gi: The Brotherhood Of War: Taegukgi dựa trên bối cảnh thành phố Seoul vào năm 1950, hai anh em ruột Jin Tae và Jin Suk trong một gia đình lao động nghèo khó nhưng hết mực yêu thương đùm bọc lẫn nhau. Hàng ngày, Jin Tae làm công việc đánh giày cho khách để kiếm tiền phụ giúp gia đình và phụ trang trải việc ăn học cho cậu em Jin Suk với ước mơ được vào đại học. Tháng 6/1950 quân Bắc Hàn bất thình lình tấn công, chiến tranh Triều Tiên bùng nổ. Jin Suk bị quân cảnh bắt đi lính. Jin Tae buộc phải tham gia quân đội Nam Hàn để bảo bọc em mình, hy vọng Jin Suk còn có thể có cơ hội trở về nhà. Để thực hiện ý đồ ấy, Jin Tae luôn xung phong đi đầu nhận lãnh những nhiệm vụ nguy hiểm và lập được nhiều chiến công để tác động đến các sỹ quan chỉ huy cùng đồng đội cho em trai có thể được an toàn trở về nhà...</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jang Dong-gun","avatar":""},{"name":"Won Bin","avatar":""},{"name":"Eun-ju Lee","avatar":""},{"name":"Gong Hyung-jin","avatar":""},{"name":"Park Jeong-Woo","avatar":""},{"name":"Yun-hie Jo","avatar":""},{"name":"Lee Young-lan","avatar":""},{"name":"Ahn Kil-kang","avatar":""},{"name":"Min-ho Jang","avatar":""},{"name":"Dae-Hoon Jeong","avatar":""},{"name":"Jeon Jae-hyeong","avatar":""},{"name":"Jung Doo-hong","avatar":""},{"name":"Kim Bo-kyung","avatar":""},{"name":"Kim Soo-ro","avatar":""},{"name":"Jung Ho-bin","avatar":""},{"name":"Lim Hyung-jun","avatar":""},{"name":"Kwon Tae-won","avatar":""},{"name":"Park Kil-soo","avatar":""},{"name":"Jin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324528);
