INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-cua-bi-mat', 'Ô Cửa Bí Mật', 'Secret Window', 'https://phimimg.com/upload/vod/20231120-1/330adfa7b0710691090f7e02ad259a0e.jpg', 'https://phimimg.com/upload/vod/20231120-1/dadd8e8f414f78f16278d0038a3d34e7.jpg', '<p>Một nhà văn thành công trải qua cuộc ly hôn đau đớn. Khi về căn nhà hẻo lánh bên hồ, anh bị một kẻ cố làm ra vẻ mình là nhà văn rình mò và buộc tội anh đạo văn.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"John Turturro","avatar":""},{"name":"Maria Bello","avatar":""},{"name":"Timothy Hutton","avatar":""},{"name":"Charles S. Dutton","avatar":""},{"name":"Len Cariou","avatar":""},{"name":"Joan Heney","avatar":""},{"name":"John Dunn-Hill","avatar":""},{"name":"Vlasta Vrana","avatar":""},{"name":"Matt Holland","avatar":""},{"name":"Gillian Ferrabee","avatar":""},{"name":"Bronwen Mantel","avatar":""},{"name":"Elizabeth Marleau","avatar":""},{"name":"Kyle Allatt","avatar":""},{"name":"Richard Jutras","avatar":""},{"name":"Sarah Allen","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
