INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-noi-quan-ruou', 'Tình Yêu Nơi Quán Rượu', 'Sideways', 'https://phimimg.com/upload/vod/20231116-1/3b4942cb8eb3068d83b4effafed4a1bf.jpg', 'https://phimimg.com/upload/vod/20231116-1/4882dcf6a2d37ae00fca506d6b7a8b82.jpg', '<p>Sideways (Tình Yêu Nơi Quán Rượu) là tác phẩm tiêu biểu cho phong cách ấy. Tình huống của phim đơn giản, co lại đúng bằng kích cỡ thực tế: Hai gã trung niên du hành về miền quê Santa Barbara, California, trước khi một trong hai làm đám cưới. Nhân vật chính là kẻ còn tự do, thầy giáo u sầu Miles (Paul Giamatti) đã ly dị vợ, mê rượu bao nhiêu thì chán đời bấy nhiêu. Trái ngược là diễn viên nghiệp dư Jack (Thomas Haden Church) sắp cưới vợ, tích cực, có vẻ háo hức của một đứa trẻ trước mọi thứ. Cặp đôi điển hình này trèo lên xe hơi mà không cần biết dẫn về đâu. Trong quá trình du ngoạn và thưởng thức rượu nho, tại vùng đất lãng mạn này, họ đã gặp hai cô gái dễ thương, những tình cảm đã nảy sinh trong những tâm hồn khao khát yêu thương... đồng thời cũng phát hiện ra những tài năng... bên lề của chính họ.</p>', 'Full', 1, 'single', 'completed', 21, 2004, 'Vietsub', 'HD', 'Hungary', 0, '[{"name":"Paul Giamatti","avatar":""},{"name":"Thomas Haden Church","avatar":""},{"name":"Virginia Madsen","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"Marylouise Burke","avatar":""},{"name":"Jessica Hecht","avatar":""},{"name":"Missy Doty","avatar":""},{"name":"M.C. Gainey","avatar":""},{"name":"Alysia Reiner","avatar":""},{"name":"Shake Tukhmanyan","avatar":""},{"name":"Shaun Duke","avatar":""},{"name":"Robert Covarrubias","avatar":""},{"name":"Patrick Gallagher","avatar":""},{"name":"Stephanie Faracy","avatar":""},{"name":"Joe Marinelli","avatar":""},{"name":"Chris Burroughs","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324528);
