INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-noi-quan-ruou', 'Tình Yêu Nơi Quán Rượu', 'Sideways', 'tình yêu nơi quán rượu sideways paul giamatti thomas haden church virginia madsen sandra oh marylouise burke jessica hecht missy doty m.c. gainey alysia reiner shake tukhmanyan shaun duke robert covarrubias patrick gallagher stephanie faracy joe marinelli chris burroughs ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngang-cao-dau', 'Ngẩng Cao Đầu', 'Walking Tall', 'https://phimimg.com/upload/vod/20231120-1/d095b50f8c665b94a67a197fcb8e47ab.jpg', 'https://phimimg.com/upload/vod/20231120-1/d5c73d8118a91fc12d5f6388b8d04a86.jpg', '<p>Chris Vaughn là 1 binh sĩ nghỉ hưu, anh trở về thị trấn nhỏ quê anh để sống 1 cuộc sống mới, nhưng anh nhận ra rằng người bạn học con nhà giàu năm xưa với anh là Jay lại là 1 tên trùm luôn làm những chuyện phạm pháp nơi thành phố bé nhỏ ấy. Chris nhìn thấy rằng quê anh giờ tràn ngập tội phạm, thuốc phiện và đầy bạo lực. Được sự giúp đỡ của ngường bạn cũ là Ray, Chris trớ thành cảnh sát và anh thề rằng sẽ đưa thị trấn này trớ nên bình yên như cũ. Việc anh làm đã khiến mạng sống của anh và gia đình anh trở nên nguy hiểm nhưng anh không hề bỏ cuộc chỉ vì muốn làm việc tốt cho nơi anh đã sinh ra và lớn lên...</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Johnny Knoxville","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Kristen Wilson","avatar":""},{"name":"Ashley Scott","avatar":""},{"name":"Khleo Thomas","avatar":""},{"name":"John Beasley","avatar":""},{"name":"Barbara Tarbuck","avatar":""},{"name":"Michael Bowen","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Andrew Tarbet","avatar":""},{"name":"Patrick Gallagher","avatar":""},{"name":"John Stewart","avatar":""},{"name":"Eric Breker","avatar":""},{"name":"Ryan Robbins","avatar":""},{"name":"Michael Adamthwaite","avatar":""},{"name":"Darcy","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"