INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-trieu-do', 'Cô Gái Triệu Đô', 'Million Dollar Baby', 'https://phimimg.com/upload/vod/20231119-1/0efa263576ace44102d1dbdc84c19c35.jpg', 'https://phimimg.com/upload/vod/20231119-1/95c9251517a70dd557fe97e374d20511.jpg', '<p>Million Dollar Baby là câu chuyện mà ẩn đằng sau đó nhiều lớp lang ý nghĩa và thông điệp sâu sắc. Phim ca ngợi ý chí ngoan cường và sức sống mãnh liệt của người phụ nữ, câu chuyện về tình người, tình cảm gia đình. Thêm vào đó, phim còn phản ánh rất nhiều thực tế khắc nghiệt của cuộc sống và bài học về cái giá của vinh quang.</p>', 'Full', 1, 'single', 'completed', 22, 2004, 'Vietsub', 'HD', 'Thụy Sĩ', 0, '[{"name":"Clint Eastwood","avatar":""},{"name":"Hilary Swank","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Jay Baruchel","avatar":""},{"name":"Mike Colter","avatar":""},{"name":"Lucia Rijker","avatar":""},{"name":"Brían F. O''Byrne","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Margo Martindale","avatar":""},{"name":"Riki Lindhome","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Benito Martinez","avatar":""},{"name":"Bruce MacVittie","avatar":""},{"name":"David Powledge","avatar":""},{"name":"Joe D''Angerio","avatar":""},{"name":"Marcus Chait","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
