INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-nhu', 'Giá Như', 'If Only', 'https://phimimg.com/upload/vod/20231119-1/20aa4a2cd6b603d0b7b4ad9b49e6b2df.jpg', 'https://phimimg.com/upload/vod/20231119-1/3c82237197ef6b5ef7e0b32fc8a5d7fa.jpg', '<p>Ian Wyndham (Nicholls) là một doanh nhân người Anh sống với bạn gái nhạc sĩ của mình, Samantha Andrews (Hewitt) tại London. Ian mất Sam cho các cấp làm cho Sam cảm giác dễ bị tổn thương trong vai trò của một người yêu thương hơn. Nửa đầu của bộ phim mô tả một ngày mà lên đến đỉnh điểm trong một hàng trong đó sôi thất vọng Samantha hơn. Xe taxi Samantha sản lượng đánh bắt được trúng một chiếc xe khác ở phía trước của Ian và cô chết.Một Ian nguôi ngoai đi lại ngủ một mình chỉ để thức dậy vào lúc bắt đầu cùng ngày và Sam vẫn còn sống cho thấy rằng nó đã được tất cả một giấc mơ. Vào thời điểm đó, ông đến để nhận ra rằng anh đã dùng Samantha cho các cấp, và khi cậu đến sống lại trong cùng một ngày, Ian sau đó được trao một ...</p>', 'Full', 1, 'single', 'completed', 12, 2004, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jennifer Love Hewitt","avatar":""},{"name":"Paul Nicholls","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Diana Hardcastle","avatar":""},{"name":"Lucy Davenport","avatar":""},{"name":"Kevin Moore","avatar":""},{"name":"Roy Sampson","avatar":""},{"name":"Oscar James","avatar":""},{"name":"Terence Harvey","avatar":""},{"name":"Neville Phillips","avatar":""},{"name":"Teo-Wa Vuong","avatar":""},{"name":"Danny Babington","avatar":""},{"name":"Stewart Wright","avatar":""},{"name":"Pippa Haywood","avatar":""},{"name":"Anthony Milner","avatar":""},{"name":"Marc Finn","avatar":""},{"name":"Al Wild","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324528);
