INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bui-doi', 'Bụi Đời', 'The Beautiful Country', 'https://phimimg.com/upload/vod/20231116-1/9d918569de3b07ecf229195e47c2c66c.jpg', 'https://phimimg.com/upload/vod/20231116-1/66305f769bce940a35bfdbbe206f2e0a.jpg', '<p>The Beautiful Country (Bụi đời) là bộ phim là một phim độc lập của đạo diễn Na-Uy Hans Peter Moland kể về một đứa trẻ Việt Nam mang trong mình hai dòng máu Mỹ - Việt. Bình – nhân vật chính của bộ phim sống trong cô đơn và buồn tẻ cùng gia đình tại một khu vực nông thôn. Anh là chàng trai có tính cách nhút nhát, khép kín và luôn mang theo những đau đáu, dằn vặt về xuất thân của mình. Ký ức duy nhất của anh về cha mình đó là một bức ảnh được chụp từ thời thơ ấu. Một ngày kia Bình quyết định rời vùng quê của mình đi tìm mẹ - người đang làm giúp việc tại Sài Gòn. Ở đó, anh cảm nhận được sự nghèo khổ của mẹ và phát hiện ra mình còn có một người em trai. Một tai nạn chết người nghiêm trọng đã khởi đầu một cuộc sống đầy biến động cho Bình.</p>', 'Full', 1, 'single', 'completed', 22, 2004, 'Vietsub', 'HD', 'Na Uy', 0, '[{"name":"Nick Nolte","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Bai Ling","avatar":""},{"name":"Temuera Morrison","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Damien Nguyen","avatar":""},{"name":"John Hussey","avatar":""},{"name":"Kirk Griffith","avatar":""},{"name":"Arthur J. Nascarella","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
