INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('superstar-gam-sayong', 'Superstar Gam Sa-Yong', 'Superstar Gam Sa-Yong', 'https://phimimg.com/upload/vod/20231115-1/8f6c927626670c3e8cd7ab5c6b44609c.jpg', 'https://phimimg.com/upload/vod/20231115-1/53eea6a42d265639795999275adf6ff8.jpg', '<p>Một bình cứu trợ cho đội tồi tệ nhất trong giải đấu bắt giữ cơ hội không thể làm việc chín hiệp chống lại ngôi sao bắt đầu ném bóng của đội tốt nhất của giải đấu khi không ai muốn đối mặt với anh ta.</p>', 'Full', 1, 'single', 'completed', 16, 2004, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Beom-su","avatar":""},{"name":"Yoon Jin-seo","avatar":""},{"name":"Kim Soo-mi","avatar":""},{"name":"Jang Hang-seon","avatar":""},{"name":"Gong Yoo","avatar":""},{"name":"Park Hyo-ju","avatar":""},{"name":"Ha Jung-woo","avatar":""},{"name":"Jo Hee-bong","avatar":""},{"name":"Ryu Seung-su","avatar":""},{"name":"Lee Hyeok-jae","avatar":""},{"name":"Jang So-yeon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
