INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-latinh-tren-dat-my', 'Người Latinh trên đất Mỹ', 'Spanglish', 'https://phimimg.com/upload/vod/20231115-1/8f0edee722fa993bb6944d61efd5f40c.jpg', 'https://phimimg.com/upload/vod/20231115-1/0d3dcb0fa2ad35e8b8152a5a4099345a.jpg', '<p>Một đầu bếp thành đạt nhưng hôn nhân không xuôi chèo mát mái. Anh kết nối với người giúp việc mới của gia đình – một bà mẹ tận tụy đến từ Mexico không biết tiếng Anh.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Téa Leoni","avatar":""},{"name":"Paz Vega","avatar":""},{"name":"Cloris Leachman","avatar":""},{"name":"Shelbie Bruce","avatar":""},{"name":"Sarah Steele","avatar":""},{"name":"Ian Hyland","avatar":""},{"name":"Victoria Luna","avatar":""},{"name":"Cecilia Suárez","avatar":""},{"name":"Ricardo Molina","avatar":""},{"name":"Brenda Canela","avatar":""},{"name":"Eddy Martin","avatar":""},{"name":"Sarah Hyland","avatar":""},{"name":"Spencer Locke","avatar":""},{"name":"Liz Carey","avatar":""},{"name":"Nicole Nieth","avatar":""},{"name":"Jamie Kaler","avatar":""},{"name":"James Lancaster","avatar":""},{"name":"Phi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
