INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-tau-khong-gian-2-anh-hung-lien-bang', 'Chiến Binh Tàu Không Gian 2: Anh Hùng Liên Bang', 'Starship Troopers 2: Hero of the Federation', 'https://phimimg.com/upload/vod/20231114-1/fcbafeb28643b6e4cb926d19bcd1c13f.jpg', 'https://phimimg.com/upload/vod/20231114-1/9225969ab2e5e97aaa51985ff9413660.jpg', '<p>Các chiến binh vũ trụ đã trở lại để chiến đấu với lũ bọ khổng lồ. Nhưng lần này, họ còn phải đối đầu với mối đe dọa từ con người.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colleen Porch","avatar":""},{"name":"Richard Burgi","avatar":""},{"name":"Lawrence Monoson","avatar":""},{"name":"Brenda Strong","avatar":""},{"name":"Ed Lauter","avatar":""},{"name":"Cy Carter","avatar":""},{"name":"Kelly Carlson","avatar":""},{"name":"Ed Quinn","avatar":""},{"name":"Sandrine Holt","avatar":""},{"name":"J.P. Manoux","avatar":""},{"name":"Drew Powell","avatar":""},{"name":"Billy Brown","avatar":""},{"name":"Jason-Shane Scott","avatar":""},{"name":"Brian Tee","avatar":""},{"name":"David Wells","avatar":""},{"name":"Tim Conlon","avatar":""},{"name":"Bobby C. King","avatar":""},{"name":"Stephen Stanton","avatar":""},{"name":"Sean","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324528);
