INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-little-bride', 'My Little Bride', 'My Little Bride', 'https://phimimg.com/upload/vod/20231114-1/3f8df419ce030cf6d3c070442a9f2f80.jpg', 'https://phimimg.com/upload/vod/20231114-1/b36c67ddb6cfc6444f273d67a8709c83.jpg', '<p>Điều duy nhất của ông Seo Bo-Eun của Seo Bo-eun muốn là gặp cô ấy Wed; Anh ta thậm chí còn giả mạo một căn bệnh chí mạng để có được cách của mình. Anh ta sắp xếp cuộc hôn nhân của mình đến 20-một công viên Sang-Min, cháu trai của một người bạn gia đình. Giữ bí mật về cuộc hôn nhân của họ từ tất cả trừ một số ít, những cặp vợ chồng mới cưới cố gắng sống cuộc sống riêng biệt của họ là bình thường nhất có thể, nhưng điều này sớm trở nên phức tạp hơn nhiều.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Moon Geun-young","avatar":""},{"name":"Kim Rae-won","avatar":""},{"name":"Kim Bo-kyung","avatar":""},{"name":"Ahn Sun-Young","avatar":""},{"name":"Kim In-mun","avatar":""},{"name":"Song Ki-Yoon","avatar":""},{"name":"Han Jin-hee","avatar":""},{"name":"Eun-Sook Sunwoo","avatar":""},{"name":"Kim Hye-ok","avatar":""},{"name":"Park Jin-woo","avatar":""},{"name":"Shin Se-kyung","avatar":""},{"name":"Ryu Deok-hwan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
