INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('my-little-bride', 'My Little Bride', 'My Little Bride', 'my little bride my little bride moon geun-young kim rae-won kim bo-kyung ahn sun-young kim in-mun song ki-yoon han jin-hee eun-sook sunwoo kim hye-ok park jin-woo shin se-kyung ryu deok-hwan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-thu-thu-bi-an-nhung-luoi-mac', 'Hội Thủ Thư: Bí Ẩn Những Lưỡi Mác', 'The Librarian: Quest for the Spear', 'https://phimimg.com/upload/vod/20231114-1/08422adb0bdc856e7e47e3af4e83c169.jpg', 'https://phimimg.com/upload/vod/20231114-1/0edeaa3d4c715a3e75d722996a8dfe25.jpg', '<p>Flynn Carsen (Noah Wyle) là một sinh viên khảo cổ học xuất sắc. Với thú vui đọc sách và vốn hiểu biết phong phú về lịch sử, văn hoá, ngôn ngữ các dân tộc cổ đại, anh muốn ở lại trường để làm công tác nghiên cứu. Nhưng vị giáo sư của Carsen đã đuổi khéo chàng sinh viên giỏi của ông ra khỏi trường, cho rằng anh chỉ là “mọt sách” và nên tự tích luỹ kinh nghiệm sống ở thế giới bên ngoài. Một ngày anh nhận được giấy mời phỏng vấn cho vị trí thủ thư của một thư viện, Carsen vui vẻ nhận lời mà không hề biết đó thực ra là một tổ chức bí ẩn có nhiệm vụ tìm kiếm bảo vệ những cổ vật quý giá trên toàn thế giới. Nhiều vật trong số chúng chỉ tồn tại trong truyền thuyết và thần thoại. Những chuyến phiêu lưu kì thú nhưng cũng cực kì nguy hiểm bổng mở ra ngay trước mắt anh chàng mọt sách...</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Noah Wyle","avatar":""},{"name":"Sonya Walger","avatar":""},{"name":"Kelly Hu","avatar":""},{"name":"Bob Newhart","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"David Dayan Fisher","avatar":""},{"name":"Jane Curtin","avatar":""},{"name":"Olympia Dukakis","avatar":""},{"name":"Lisa Brenner","avatar":""},{"name":"Mario Iván Martínez","avatar":""},{"name":"Clyde Kusatsu","avatar":""},{"name":"Alejandra Gollas","avatar":""},{"name":"José Montini","avatar":""},{"name":"Jessica Moreno","avatar":""},{"name":"Mauricio Llera","avatar":""},{"name":"Antonio Monroy","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324528);
