INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoi-thu-thu-bi-an-nhung-luoi-mac', 'Hội Thủ Thư: Bí Ẩn Những Lưỡi Mác', 'The Librarian: Quest for the Spear', 'hội thủ thư: bí ẩn những lưỡi mác the librarian: quest for the spear noah wyle sonya walger kelly hu bob newhart kyle maclachlan david dayan fisher jane curtin olympia dukakis lisa brenner mario iván martínez clyde kusatsu alejandra gollas josé montini jessica moreno mauricio llera antonio monroy ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-nam-my', 'Hành Trình Nam Mỹ', 'The Motorcycle Diaries', 'https://phimimg.com/upload/vod/20231115-1/6060edf60f263d7de71dca21afef6719.jpg', 'https://phimimg.com/upload/vod/20231115-1/0d8f73834edc3393342a649efa9d216a.jpg', '<p>Năm 1952, sinh viên y khoa hai mươi ba tuổi Ernesto Guevara de la Serna - Fuser cho bạn bè và sau đó được biết đến với &#39;Ernesto Che Guevara&#39; - một học kỳ xa lễ tốt nghiệp, quyết định hoãn học kỳ cuối cùng của mình để đi cùng hai mươi chín năm Người bạn sinh hóa cũ &#39;Alberto Granado&#39; - mial cho bạn bè của mình - trong bốn tháng, chuyến đi xe mô tô dài 8.000 km trong suốt Nam Mỹ bắt đầu từ nhà của họ ở Buenos Aires. Nhiệm vụ của họ là nhìn thấy những thứ mà họ chỉ đọc về những cuốn sách về lục địa mà họ sống, và kết thúc nhiệm vụ đó vào sinh nhật thứ ba của Alberto ở phía bên kia lục địa trong Bán đảo Guajira ở Venezuela. Không phải tất cả trong chuyến đi này diễn ra theo chương trình sơ bộ của họ do một chiếc xe máy bị phá vỡ, một sự thiếu tiền liên tục (họ thường kéo dài sự thật để có được sự ưu ái của nhiều người lạ để giúp đỡ họ), lập luận giữa hai người thường xuyên Cô lập chỉ với nhau, ham muốn libidos đang hoành hành mà đôi khi khiến chúng gặp rắc rối và đối phó với hen suyễn mạn tính của Fuser. Nhưng một cơ hội gặp gỡ với một vài người cộng sản ở sa mạc Chile và một chuyến thăm kéo dài đến Thuộc địa San Pablo Leper trong lưu vực Amazon Perúvian trong số những thứ khác ảnh hưởng sâu sắc đến những gì mỗi người sẽ muốn làm với cuộc sống của mình và trái phiếu từng có với người khác .</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gael García Bernal","avatar":""},{"name":"Rodrigo de la Serna","avatar":""},{"name":"Mercedes Morán","avatar":""},{"name":"Mía Maestro","avatar":""},{"name":"Jean Pierre Noher","avatar":""},{"name":"Lucas Oro","avatar":""},{"name":"Marina Glezer","avatar":""},{"name":"Sofia Bertolotto","avatar":""},{"name":"Franco Solazzi","avatar":""},{"name":"Ricardo Díaz Mourelle","avatar":""},{"name":"Gustavo Bueno","avatar":""},{"name":"Antonella Costa","avatar":""},{"name":"Natalia Lobo","avatar":""},{"name":"Erto Pantoja","avatar":""},{"name":"Cristián Chaparro","avatar":""},{"name":"Cris","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
