INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hanh-trinh-nam-my', 'Hành Trình Nam Mỹ', 'The Motorcycle Diaries', 'hành trình nam mỹ the motorcycle diaries gael garcía bernal rodrigo de la serna mercedes morán mía maestro jean pierre noher lucas oro marina glezer sofia bertolotto franco solazzi ricardo díaz mourelle gustavo bueno antonella costa natalia lobo erto pantoja cristián chaparro cris ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ung-cu-vien-bi-giat-day', 'Ứng Cử Viên Bị Giật Dây', 'The Manchurian Candidate', 'https://phimimg.com/upload/vod/20231115-1/eec35a80622f0c7d9181bfcc3a7e923b.jpg', 'https://phimimg.com/upload/vod/20231115-1/b0ff5d9559e4ae596116f6165aa23555.jpg', '<p>Phim được dựa trên tiểu thuyết cùng tên của Richard Condon và là phiên bản làm lại của bộ phim cùng tên năm 1962. Bối cảnh của phim diễn ra trong thời đại hiện đại, khi mà một nhóm quân đội Mỹ đang tham gia vào một cuộc chiến ở Trung Đông. Trong một cuộc tấn công, Đại úy Ben Marco (do Denzel Washington thủ vai) và đồng đội của anh bị bắt và giam giữ trong một trại tù ở Manchuria. Sau khi trở về Mỹ, Ben bắt đầu trải qua những cơn ác mộng và những hồi tưởng kỳ lạ về thời gian bị giam giữ. Anh nghi ngờ rằng mình và đồng đội đã trải qua sự kiểm soát tâm lý và kiểm soát não bộ trong khi ở trong trại tù.</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Liev Schreiber","avatar":""},{"name":"Simon McBurney","avatar":""},{"name":"Kimberly Elise","avatar":""},{"name":"Bruno Ganz","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Anthony Mackie","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"Miguel Ferrer","avatar":""},{"name":"Dean Stockwell","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"Pablo Schreiber","avatar":""},{"name":"Jude Ciccolella","avatar":""},{"name":"Obba Babatundé","avatar":""},{"name":"Zeljko Ivan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324528);
