INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-bach-long', 'Tiểu Bạch Long', 'The White Dragon', 'https://phimimg.com/upload/vod/20231115-1/5682a876a4589ed56696638ca3b68b0f.jpg', 'https://phimimg.com/upload/vod/20231115-1/ae95ef3eb315584fbb53b8ffc93009a8.jpg', '<p>Hắc Phụng từ lâu vẫn mơ mộng về 1 chàng hoàng tử mạnh mẽ và cô đã thoả nguyện khi trở thành ng yêu của nhị hoàng tử. Cơ duyên đã giúp cô có được công lực của bà già Bạch Long và trở thành Tiểu Bạch Long hành hiệp trượng nghĩa.Và rồi cô phải đối đầu với Mục Kê Vũ, 1 kẻ giết mướn (bị mù) nhưng chỉ giết những kẻ đáng chết. Mục Kê Vũ được thuê giết nhị hoàng tử nên vì tình yêu Tiểu Bạch Long đã lập mưu để giết y. Rốt cuộc Bạch Long bị gãy chân và được Mục Kê Vũ đem về nhà bó bột. Vì ko thể trở về với tình trạng xấu xí như thế được nên Bạch Long phải ở lại đó và dần bị cảm mến bởi bản tính tốt đẹp của Mục Kê Vũ. Còn tay sát thủ cũng biết rằng mình yêu cô gái này rồi nhưng ko thể thấy được ...</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Cecilia Cheung Pak-Chi","avatar":""},{"name":"Francis Ng","avatar":""},{"name":"Avi K. Garg","avatar":""},{"name":"Lei Liu","avatar":""},{"name":"Andy On","avatar":""},{"name":"Xiaolong Ding","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Suet Nei","avatar":""},{"name":"Patrick Tang","avatar":""},{"name":"Kitty Yuen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52