INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-phut-o-new-york', 'Một Phút Ở New York', 'New York Minute', 'https://phimimg.com/upload/vod/20231115-1/63bc1c794eb0ad7343fbc2bc8c3cb1d6.jpg', 'https://phimimg.com/upload/vod/20231115-1/f38a2941676b58343e09b833c96036b1.jpg', '<p>Bộ phim bắt đầu với cơn ác mộng của Jane Ryan (Ashley Olsen). Cô bị ám ảnh với bài phát biểu phải thực hiện tại đại học Columbia để giành suất học bổng danh giá Oxford. Với cô ngày hôm nay là một dấu mốc quan trọng trong đời. Và Jane đâu biết rằng đó cũng là một ngày khủng khiếp đối với mình trước khi cùng cô em Roxy (Mary-Kate Olsen) đi từ Long Island sang New York. Trái ngược với sự mẫu mực và hoàn hảo của Jane, Roxy là một cô gái nghịch ngợm ưa nổi loạn. Trong khi chị mình lo lắng cho bài phát biểu thì cô vắt óc tính kế trốn học để đi dự buổi ghi hình của ban nhạc Simple Plan. Roxy dự định gửi lại nhóm tìm kiếm tài năng của họ một bản thu thử tác phẩm do ban nhạc của cô trình bày. Nhưng kế hoạch của hai chị em đều đổ bể khi họ cùng bị vướng vào một vụ trao đổi liên quan đến bọn tội phạm chuyên sao chép trái phép đĩa nhạc. Roxy vô tình có được con chip quan trọng của chúng, còn gã đầu gấu Bennie Bang (Andy Richter) thì nắm được cuốn sổ ghi chép của Jane. Tình thế trở nên khó khăn khi giám thị chuyên lùng học sinh trốn học Max Lomax (Eugene Levy) điên cuồng lần theo dấu vết của Roxy. Trong cuộc chạy trốn từ phố người Hoa đến Harlem, hai chị em tình cờ được giúp đỡ bởi Trey Lipton (Jared Padalecki) con trai thượng nghị sĩ Anne Lipton (Andrea Martin) và cậu chàng đi xe đạp đẹp trai Jim. Tuy nhiên, thời gian không còn nhiều, Jane phải có mặt đúng giờ để phát biểu, mà cuốn sổ tay thì chưa đòi lại được. Roxy thì có nguy cơ bị đuổi học nếu Max túm được cô. Cả hai đều lâm vào thế kẹt, nhưng mọi thứ đều có thể thay đổi vào phút chót!...</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ashley Olsen","avatar":""},{"name":"Mary-Kate Olsen","avatar":""},{"name":"Eugene Levy","avatar":""},{"name":"Andy Richter","avatar":""},{"name":"Riley Smith","avatar":""},{"name":"Jared Padalecki","avatar":""},{"name":"Drew Pinsky","avatar":""},{"name":"Darrell Hammond","avatar":""},{"name":"Andrea Martin","avatar":""},{"name":"Alannah Ong","avatar":""},{"name":"Bob Saget","avatar":""},{"name":"Jack Osbourne","avatar":""},{"name":"Mary Bond Davis","avatar":""},{"name":"Neil Crone","avatar":""},{"name":"Sébastien Lefebvre","avatar":""},{"name":"David Desrosiers","avatar":""},{"name":"Pierre Bouvier","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324528);
