INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('guong-phong-thuy', 'Gương phong thủy', 'Feng Shui', 'https://phimimg.com/upload/vod/20231113-1/c622d5f80ff2cf544dd04ce465d6f5e2.jpg', 'https://phimimg.com/upload/vod/20231113-1/54e23543dbfeccb36540f8f13d339a49.jpg', '<p>Khi người phụ nữ nọ mang chiếc gương cổ về nhà để cầu may, dường như nó đã thay đổi vận mệnh của cả gia đình cô, nhưng rồi một lời nguyền độc ác bắt đầu hủy hoại cuộc sống của họ.</p>', 'Full', 1, 'single', 'completed', 18, 2004, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Kris Aquino","avatar":""},{"name":"Jay Manalo","avatar":""},{"name":"Lotlot De Leon","avatar":""},{"name":"Ilonah Jean","avatar":""},{"name":"John Manalo","avatar":""},{"name":"Julianne Gomez","avatar":""},{"name":"Ernesto Sto. Tomas","avatar":""},{"name":"Cherry Pie Picache","avatar":""},{"name":"Nonie Buencamino","avatar":""},{"name":"Jenny Miller","avatar":""},{"name":"Gerard Pizzaras","avatar":""},{"name":"Joonee Gamboa","avatar":""},{"name":"Daria Ramirez","avatar":""},{"name":"Archie Adamos","avatar":""},{"name":"Emil Sandoval","avatar":""},{"name":"Luz Fernandez","avatar":""},{"name":"Leo Gamb","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
