INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mat-am-duong-2', 'Con mắt âm dương 2', 'The Eye 2', 'https://phimimg.com/upload/vod/20231112-1/627c562eb19afad424c282a80dddfdef.jpg', 'https://phimimg.com/upload/vod/20231112-1/0f6cecce06423a4b2a46a407d10e5349.jpg', '<p>Một phụ nữ mang thai bỗng có khả năng nhìn thấy linh hồn. Cô còn tin rằng một trong số họ muốn nhập vào cơ thể đứa con chưa chào đời của mình.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Shu Qi","avatar":""},{"name":"Eugenia Yuan","avatar":""},{"name":"Jesdaporn Pholdee","avatar":""},{"name":"Supasawat Buranavech","avatar":""},{"name":"Kwai Ying Cheung","avatar":""},{"name":"Yiu Kwai Cheung","avatar":""},{"name":"Lawrence Chou","avatar":""},{"name":"Phillip Chung-Fung Kwok","avatar":""},{"name":"Chuwong Earsakul","avatar":""},{"name":"Connie Lai","avatar":""},{"name":"Fanny Lee Man-Fan","avatar":""},{"name":"Harasawin Lee","avatar":""},{"name":"May Phua","avatar":""},{"name":"Jongchai Poomrmarin","avatar":""},{"name":"Derek Tsang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324528);
