INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-su-khai-huyen', 'Thiên Sứ Khải Huyền', 'Crimson Rivers II: Angels of the Apocalypse', 'https://phimimg.com/upload/vod/20231112-1/137d30fc6fa017ad8ed0522f22ea7914.jpg', 'https://phimimg.com/upload/vod/20231112-1/ba0deaacd73610fd787172e378cd03b0.jpg', '<p>Không ai được an toàn khi những vụ giết người dường như ngẫu nhiên xuất hiện như một mô hình chết chóc nhằm mở ra ngày tận thế. Một nạn nhân bị sát hại có cùng DNA với Chúa Kitô. Một kẻ giết người hàng loạt bắt chước cái chết của 12 Tông đồ. Thanh tra Niemans và một thám tử trẻ, nổi loạn lập nhóm với một chuyên gia xinh đẹp về tôn giáo để phá án trước khi nghi phạm khó nắm bắt của họ hoàn thành chu kỳ khủng bố, mở đường cho một thảm họa đẫm máu thậm chí còn lớn hơn.</p>', 'Full', 1, 'single', 'completed', 17, 2004, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean Reno","avatar":""},{"name":"Benoît Magimel","avatar":""},{"name":"Camille Natta","avatar":""},{"name":"Christopher Lee","avatar":""},{"name":"Johnny Hallyday","avatar":""},{"name":"Gabrielle Lazure","avatar":""},{"name":"Serge Riaboukine","avatar":""},{"name":"Augustin Legrand","avatar":""},{"name":"André Penvern","avatar":""},{"name":"Francis Renaud","avatar":""},{"name":"Olivier Brocheriou","avatar":""},{"name":"David Saracino","avatar":""},{"name":"Michaël Abiteboul","avatar":""},{"name":"Ériq Ebouaney","avatar":""},{"name":"Jo Prestia","avatar":""},{"name":"Cyril Raffae","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324528);
