INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-su-khai-huyen', 'Thiên Sứ Khải Huyền', 'Crimson Rivers II: Angels of the Apocalypse', 'thiên sứ khải huyền crimson rivers ii: angels of the apocalypse jean reno benoît magimel camille natta christopher lee johnny hallyday gabrielle lazure serge riaboukine augustin legrand andré penvern francis renaud olivier brocheriou david saracino michaël abiteboul ériq ebouaney jo prestia cyril raffae ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-am-cua-cha', 'Tổ Ấm Của Cha', 'In My Father''s Den', 'https://phimimg.com/upload/vod/20231111-1/76c30f3646454ee872ac775063981c5b.jpg', 'https://phimimg.com/upload/vod/20231111-1/5742906f7ddc2ad85ca8298df0d9c14c.jpg', '<p>Paul (Macfadyen), một nhà báo chiến tranh từng đoạt giải thưởng, trở về quê hương New Zealand xa xôi của mình sau cái chết của cha anh, người đầy vết sẹo chiến trường và mệt mỏi với thế giới. Đối với Celia (Barclay) mười sáu tuổi bất mãn, anh mở ra một thế giới mà cô chỉ mơ ước. Cô tích cực theo đuổi tình bạn với anh ta, bị mê hoặc bởi sự hoài nghi của anh ta và trải nghiệm về thế giới bên ngoài sự tồn tại ở thị trấn nhỏ của cô. Nhưng nhiều người, bao gồm cả các thành viên của cả hai gia đình họ (Otto, Moy), không hài lòng với tình bạn và khi Celia mất tích, Paul trở thành nghi phạm chính ngày càng bị ghê tởm và bị ngược đãi trong vụ mất tích của cô. Khi sự thật bạo lực và cấp bách dần dần lộ ra, Paul buộc phải đối mặt với bi kịch gia đình và sự phản bội mà anh đã trốn chạy khi còn trẻ, đồng thời đối mặt với những hậu quả nghiêm trọng của sự im lặng và bí mật đã bao trùm suốt cuộc đời trưởng thành của anh.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Matthew Macfadyen","avatar":""},{"name":"Emily Barclay","avatar":""},{"name":"Miranda Otto","avatar":""},{"name":"Colin Moy","avatar":""},{"name":"Jimmy Keen","avatar":""},{"name":"Jodie Rimmer","avatar":""},{"name":"Matthew Chamberlain","avatar":""},{"name":"Vicky Haughton","avatar":""},{"name":"Antony Starr","avatar":""},{"name":"Vanessa Riddell","avatar":""},{"name":"Toby Alexander","avatar":""},{"name":"Nicholas Hayward","avatar":""},{"name":"Liam Herbert","avatar":""},{"name":"Asher Emanuel","avatar":""},{"name":"Sian Davis","avatar":""},{"name":"Josephine Davison","avatar":""},{"name":"Geoff Do","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
