INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tru-ta-su-khoi-dau', 'Người Trừ Tà: Sự Khởi Đầu', 'Exorcist: The Beginning', 'https://phimimg.com/upload/vod/20231113-1/49d208ac24e784834eb211c26934046b.jpg', 'https://phimimg.com/upload/vod/20231113-1/14093c29fd0706dfd5af136cdfbbf27e.jpg', '<p>Được cử đến châu Phi vào cuối Thế chiến II để hỗ trợ cộng đồng địa phương, Cha Lankester Merrin không ngờ mình phải đương đầu với một thế lực ma quỷ với cái tên Pazuzu.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Stellan Skarsgård","avatar":""},{"name":"Izabella Scorupco","avatar":""},{"name":"James D''Arcy","avatar":""},{"name":"Julian Wadham","avatar":""},{"name":"Remy Sweeney","avatar":""},{"name":"Andrew French","avatar":""},{"name":"Antonie Kamerling","avatar":""},{"name":"Ben Cross","avatar":""},{"name":"Alan Ford","avatar":""},{"name":"Ralph Brown","avatar":""},{"name":"David Bradley","avatar":""},{"name":"Eddie Osei","avatar":""},{"name":"Israel Aduramo","avatar":""},{"name":"Patrick O''Kane","avatar":""},{"name":"James Bellamy","avatar":""},{"name":"Cecilia Amati","avatar":""},{"name":"Matti","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
