INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-tru-ta-su-khoi-dau', 'Người Trừ Tà: Sự Khởi Đầu', 'Exorcist: The Beginning', 'người trừ tà: sự khởi đầu exorcist: the beginning stellan skarsgård izabella scorupco james d''arcy julian wadham remy sweeney andrew french antonie kamerling ben cross alan ford ralph brown david bradley eddie osei israel aduramo patrick o''kane james bellamy cecilia amati matti ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-gio-yeu-thuong', 'Ngọn Gió Yêu Thương', 'Windstruck', 'https://phimimg.com/upload/vod/20231111-1/af413f2e2de1f9eae5908bbbab3753a5.jpg', 'https://phimimg.com/upload/vod/20231111-1/25a3d975c5f91cc958916e997179e8ac.jpg', '<p>Kyung-jin, một sĩ quan cảnh sát thấy mình đang đuổi theo một kẻ tình nghi giật túi vào ngày nghỉ của mình. Tuy nhiên, người đàn ông mà cô bắt được hóa ra lại là Myungwoo, một người qua đường đang cố bắt tên tội phạm thực sự.</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jun Ji-hyun","avatar":""},{"name":"Jang Hyuk","avatar":""},{"name":"Kim Jung-tae","avatar":""},{"name":"Kim Soo-ro","avatar":""},{"name":"Lee Ki-woo","avatar":""},{"name":"Kim Chang-wan","avatar":""},{"name":"Jung Ho-bin","avatar":""},{"name":"Im Ye-jin","avatar":""},{"name":"Dae-Hoon Jeong","avatar":""},{"name":"Jeon Jae-hyeong","avatar":""},{"name":"Cha Tae-hyun","avatar":""},{"name":"Kim Jin-Su","avatar":""},{"name":"Baek Kyung-chan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
