INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-bep-ma-thuat', 'Đầu Bếp Ma Thuật', 'Magic Kitchen', 'https://phimimg.com/upload/vod/20231111-1/58a0da3cc09e0bfb9832ef9986019ec0.jpg', 'https://phimimg.com/upload/vod/20231111-1/71d57987708841f000c8e5aeb193beaa.jpg', '<p>Đầu Bếp Ma Thuật - The Magic Kitchen xoay quanh cô nàng xinh đẹp Mộ Dung Ưu, vốn là một đầu bếp kiêm bà chủ của một nhà hàng ăn tư lịch sự ở Hồng Kông có tên gọi là Magical Kitchen, nơi mà những khách hàng sẽ có cảm giác như mình đang ở trong một ngôi nhà chứ không phải là một nhà hàng. Tài nghệ nấu ăn của cô được mọi giới thưởng thức và khen ngợi, nhà ăn cũng khá nổi tiếng, đến chương trình thi nấu ăn nổi tiếng của Nhật Bản cũng đến mời cô làm giám khảo. Tuy nhiên, theo như lời kể của mẹ cô thì cô sẽ bị ám ảnh bởi một lời nguyền trong gia đình, thứ đã làm lu mờ ba thế hệ, khiến cô thất bại trong mọi mối quan hệ.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jerry Yan","avatar":""},{"name":"Sammi Cheng","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Maggie Q","avatar":""},{"name":"Nicola Cheung","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Stephen Fung","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Michael Wong","avatar":""},{"name":"Sheila Chan Suk-Lan","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Michael Tong","avatar":""},{"name":"Lik-Chi Lee","avatar":""},{"name":"Jacqueline Law","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324528);
