INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-bep-ma-thuat', 'Đầu Bếp Ma Thuật', 'Magic Kitchen', 'đầu bếp ma thuật magic kitchen jerry yan sammi cheng andy lau maggie q nicola cheung anthony wong stephen fung daniel wu michael wong sheila chan suk-lan law kar-ying michael tong lik-chi lee jacqueline law ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-nha-ben-2', 'Sát Thủ Nhà Bên 2', 'The Whole Ten Yards', 'https://phimimg.com/upload/vod/20231111-1/edd2a7551a93970e3536ed4c47cdf9a6.jpg', 'https://phimimg.com/upload/vod/20231111-1/61168871e7975116690627375bc5f384.jpg', '<p>Jimmy &quot;The Tulip&quot; Tudeski giờ đây dành cả ngày để dọn dẹp nhà cửa và hoàn thiện kỹ năng nấu nướng của mình với vợ, Jill, một sát thủ có chủ đích vẫn chưa thành công. Đột nhiên, một mối liên hệ không mong muốn và không mong muốn với quá khứ của họ bất ngờ xuất hiện trước cửa nhà Jimmy và Jill; đó là Oz, và anh ấy đang cầu xin họ giúp anh ấy giải cứu vợ mình, Cynthia.</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Matthew Perry","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"Natasha Henstridge","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Frank Collison","avatar":""},{"name":"Johnny Messner","avatar":""},{"name":"Silas Weir Mitchell","avatar":""},{"name":"Tasha Smith","avatar":""},{"name":"Elisa Gallay","avatar":""},{"name":"Tallulah Willis","avatar":""},{"name":"Johnny Williams","avatar":""},{"name":"McNally Sagal","avatar":""},{"name":"Carl Ciarfalio","avatar":""},{"name":"Doc Duhame","avatar":""},{"name":"Ned Bellamy","avatar":""},{"name":"Lou Beatt","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324528);
