INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-kia-dam-may-noi-ta-hen-uoc', 'Bên Kia Đám Mây, Nơi Ta Hẹn Ước', 'The Place Promised in Our Early Days', 'https://phimimg.com/upload/vod/20231110-1/cd4c1485d879277de98da4998cb663aa.jpg', 'https://phimimg.com/upload/vod/20231110-1/b7e64071ca0c1b4a90d74a4016a41baf.jpg', '<p>Khi Nhật Bản chịu sự kiểm soát của hai chế độ sau Thế chiến II, một nhóm bạn đặt mục tiêu chế tạo một con tàu nhằm giúp họ điều tra tòa tháp sừng sững ở Hokkaido.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2004, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hidetaka Yoshioka","avatar":""},{"name":"Masato Hagiwara","avatar":""},{"name":"Yuuka Nanri","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Risa Mizuno","avatar":""},{"name":"Hidenobu Kiuchi","avatar":""},{"name":"Masami Iwasaki","avatar":""},{"name":"Eiji Takemoto","avatar":""},{"name":"Takahiro Hirano","avatar":""},{"name":"Takeshi Maeda","avatar":""},{"name":"Yûki Nakao","avatar":""},{"name":"Rie Nakagawa","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324528);
