INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-nghi-mat-kinh-hoang', 'Chuyến Nghỉ Mát Kinh Hoàng', 'Club Dread', 'https://phimimg.com/upload/vod/20231109-1/b44a701851da79b2ac250ed4b11c0595.jpg', 'https://phimimg.com/upload/vod/20231109-1/14d676b21d6c60e724ea89a5b27d85de.jpg', '<p>Khi một kẻ giết người hàng loạt làm gián đoạn cuộc vui tại Khu nghỉ dưỡng Bãi biển Dừa của Pete Pete hào nhoáng - một hòn đảo thiên đường theo chủ nghĩa khoái lạc dành cho những người chơi đu dây --- nhân viên của câu lạc bộ phải ngăn chặn bạo lực ... hoặc ít nhất là che giấu nó!</p>', 'Full', 1, 'single', 'completed', 17, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Heffernan","avatar":""},{"name":"Jay Chandrasekhar","avatar":""},{"name":"Brittany Daniel","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Steve Lemme","avatar":""},{"name":"Jordan Ladd","avatar":""},{"name":"Elena Lyons","avatar":""},{"name":"Paul Soter","avatar":""},{"name":"Erik Stolhanske","avatar":""},{"name":"Tanja Reichert","avatar":""},{"name":"Nat Faxon","avatar":""},{"name":"Julio Bekhor","avatar":""},{"name":"Bryan Scott","avatar":""},{"name":"M.C. Gainey","avatar":""},{"name":"Lindsay Price","avatar":""},{"name":"Samm Levine","avatar":""},{"name":"Veronica Segura","avatar":""},{"name":"Ryan Falk","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324528);
