INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hieu-ung-canh-buom', 'Hiệu Ứng Cánh Bướm', 'The Butterfly Effect', 'https://phimimg.com/upload/vod/20231109-1/f6352a87cae51ed3787f469d6d42ff02.jpg', 'https://phimimg.com/upload/vod/20231109-1/09c9feaa8ed442cf14d08836cba253b1.jpg', '<p>Một chàng trai trẻ phải vật lộn để tiếp cận những ký ức tuổi thơ thăng hoa. Anh ta tìm thấy một kỹ thuật cho phép anh ta du hành trở lại quá khứ, để chiếm lấy cơ thể thời thơ ấu của mình và thay đổi lịch sử. Tuy nhiên, anh ấy sớm nhận ra rằng mọi thay đổi của anh ấy đều có những hậu quả bất ngờ.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ashton Kutcher","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"Eric Stoltz","avatar":""},{"name":"Melora Walters","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"William Lee Scott","avatar":""},{"name":"Elden Henson","avatar":""},{"name":"Logan Lerman","avatar":""},{"name":"John Patrick Amedori","avatar":""},{"name":"Irina Gorovaia","avatar":""},{"name":"Kevin G. Schmidt","avatar":""},{"name":"Jesse James","avatar":""},{"name":"Nathaniel DeVeaux","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Callum Keith Rennie","avatar":""},{"name":"Cameron Bright","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324528);
