INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hieu-ung-canh-buom', 'Hiệu Ứng Cánh Bướm', 'The Butterfly Effect', 'hiệu ứng cánh bướm the butterfly effect ashton kutcher amy smart eric stoltz melora walters ethan suplee william lee scott elden henson logan lerman john patrick amedori irina gorovaia kevin g. schmidt jesse james nathaniel deveaux kevin durand callum keith rennie cameron bright ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-anh-hoang-hon', 'Sau Ánh Hoàng Hôn', 'After the Sunset', 'https://phimimg.com/upload/vod/20231108-1/fb07993e7eb9d64a04286f6cd7aee372.jpg', 'https://phimimg.com/upload/vod/20231108-1/439d0022ca9778895099b9c202fb7918.jpg', '<p>Max Burdett Vua Alibis cùng tòng phạm Lola đến Đảo Thiên Đường ở Bahamas để nghỉ ngơi sau khi vụ đánh cắp trót lọt viên kim cương thứ hai trong bộ ba viên Napoleon nổi tiếng. Với những gì đạt được họ chẳng cần lo nghĩ gì cho tương lai. Hai tên cướp sẵn sàng thư giãn và tận hưởng sự giàu có rất khó nhọc của mình. Nhưng Stan, nhân viên FBI đã theo gót Max hàng năm trời không tin rằng đối tượng của mình đã nghỉ hưu. Anh nghĩ Max và Lola thực ra đang lập mưu đánh cắp viên kim cương Napoleon thứ ba  một trong ba viên hoàn mỹ lớn nhất thế giới, mà tình cờ sẽ ghé Đảo Thiên Đường theo lịch trình triển lãm. Khi hai đối thủ truyền kiếp gặp mặt, Max nhanh chóng đổi hướng và kết bạn với viên thanh tra nản chí, cho anh thấy Đảo Thiên Đường có không ít điều thú vị. Nhưng để tìm hiểu được thực sự Max và Lola muốn gì, Stan sẽ phải xem xét kỹ lưỡng mọi uẩn khúc trong câu truyện hành động về tình bạn, sự nghi ngờ và trộm cắp này...</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"Troy Garity","avatar":""},{"name":"Russell Hornsby","avatar":""},{"name":"Rex Linn","avatar":""},{"name":"Michael Bowen","avatar":""},{"name":"Mark Moses","avatar":""},{"name":"Obba Babatundé","avatar":""},{"name":"Jeff Garlin","avatar":""},{"name":"Kate Walsh","avatar":""},{"name":"Tom McGowan","avatar":""},{"name":"Rachael Harris","avatar":""},{"name":"Joel McKinnon Miller","avatar":""},{"name":"Lisa Thornhill","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324528);
