INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-khong-lo-san-lung-huyet-lan', 'Trăn Khổng Lồ: Săn Lùng Huyết Lan', 'Anacondas: The Hunt for the Blood Orchid', 'https://phimimg.com/upload/vod/20231108-1/301ac3c590f4af3d6e73905991a141ab.jpg', 'https://phimimg.com/upload/vod/20231108-1/4b7ec443f3aa112faef33e9d25f19e8e.jpg', '<p>Một đoàn thám hiểm khoa học đã tham gia vào một nhóm của một công ty dược phẩm hùng mạnh trong cuộc tìm kiếm một loài phong lan đen quý hiếm nở rộ trong khu rừng sâu của đảo Borneo. Sự thích thú với loài hoa này là do nó chứa một chất mạnh mẽ chứa đựng những bí mật của tuổi trẻ vĩnh cửu, thậm chí là bất tử. Nhưng họ sớm phát hiện ra rằng hoa lan được sử dụng bởi những con rắn khổng lồ để tăng kích thước và sức sống của nó.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"KaDee Strickland","avatar":""},{"name":"Johnny Messner","avatar":""},{"name":"Nicholas Hope","avatar":""},{"name":"Morris Chestnut","avatar":""},{"name":"Matthew Marsden","avatar":""},{"name":"Karl Yune","avatar":""},{"name":"Salli Richardson-Whitfield","avatar":""},{"name":"Eugene Byrd","avatar":""},{"name":"Nicholas Gonzalez","avatar":""},{"name":"Denis Arndt","avatar":""},{"name":"Peter Curtin","avatar":""},{"name":"Andy Anderson","avatar":""},{"name":"Khoa Do","avatar":""},{"name":"Andre Tandjung","avatar":""},{"name":"Aireti","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324528);
