INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('3-cau-chuyen-kinh-di', '3 Câu Chuyện Kinh Dị', 'Three... Extremes', 'https://phimimg.com/upload/vod/20231115-1/17f5f0cd5e88c664e3f1666bbe966912.jpg', 'https://phimimg.com/upload/vod/20231115-1/d91ca30d196daf59b401bad2e1490e98.jpg', '<p>Là một phim kinh dị đa quốc gia hợp tác giữa 3 đạo diễn khá nổi tiếng: Fruit Chan của Hồng Kông ( Trần Quả - gần đây được biết đến với bộ 2 phim kinh dị &quot;Mê li - Kỳ huyễn dạ&quot; từ sách khá nổi tiếng), Park Chan Wook của Hàn (Trilogy Vengeance, Oldboy), Takashi Miike của Nhật ( Ichi The Killer hay gần đây là 13 Assassins).</p>', 'Full', 1, 'single', 'completed', 16, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Kyoko Hasegawa","avatar":""},{"name":"Atsuro Watabe","avatar":""},{"name":"Mai Suzuki","avatar":""},{"name":"Yuu Suzuki","avatar":""},{"name":"Mitsuru Akaboshi","avatar":""},{"name":"Miriam Yeung Chin-Wah","avatar":""},{"name":"Bai Ling","avatar":""},{"name":"Pauline Lau","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Meme Tian Pu-Jun","avatar":""},{"name":"Miki Yeung","avatar":""},{"name":"Wong Sum-Yuen","avatar":""},{"name":"Wu Wai-Man","avatar":""},{"name":"Wong Siu-Foon","avatar":""},{"name":"Ho-Man Chan","avatar":""},{"name":"Lee Byung-hun","avatar":""},{"name":"Im Won-hee","avatar":""},{"name":"Kang","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324528);
