INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-nhay-duong-pho', 'Sàn Nhảy Đường Phố', 'You Got Served', 'https://phimimg.com/upload/vod/20231108-1/a7131e84e57413429aa94ad3dc7bd39e.jpg', 'https://phimimg.com/upload/vod/20231108-1/37dd191bdd53c9d1aa3ce15f18cb8e98.jpg', '<p>Khi đối thủ tự phụ thách đấu nhóm nhảy của họ trong một trận đấu, hai người bạn thân nhất phải gạt đi nỗi lo và nỗ lực thi đấu để giành lấy tiền bạc và vinh quang.</p>', 'Full', 1, 'single', 'completed', 20, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Marques Houston","avatar":""},{"name":"Omarion","avatar":""},{"name":"J-Boog","avatar":""},{"name":"Lil'' Fizz","avatar":""},{"name":"Jennifer Freeman","avatar":""},{"name":"Meagan Good","avatar":""},{"name":"Raz B","avatar":""},{"name":"Michael Taliferro","avatar":""},{"name":"Steve Harvey","avatar":""},{"name":"Lil'' Kim","avatar":""},{"name":"La La Anthony","avatar":""},{"name":"Malcolm David Kelley","avatar":""},{"name":"Wade Robson","avatar":""},{"name":"Alison Faulk","avatar":""},{"name":"Teresa Espinosa","avatar":""},{"name":"Marty Dew","avatar":""},{"name":"Christopher Jones","avatar":""},{"name":"Jackée H","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324529);
