INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-khong-xa', 'Ngày Không Xa', 'The Day After Tomorrow', 'https://phimimg.com/upload/vod/20231108-1/2f561b1fc48ed00b91874db6fcbdab02.jpg', 'https://phimimg.com/upload/vod/20231108-1/cae8fdbb54088fa84b17e5b8ac7e0803.jpg', '<p>Phim được làm với kinh phí lớn và nhiều hiệu quả đặc biệt .Nội dung phim về những tác động của hiệu ứng nhà kính và hiện tượng trái đất nóng dần lên đến sự biến động của thời tiết.Hàng loạt các cơn bão ,lũ lụt,động đất ,sóng thần đã đưa trái đất trở về thời băng hà.Trung tâm của phim là câu chuyện một nhà nghiên cứu về thời tiết,giáo sư Adrian cố cứu thế giới và cậu con trai Sam ra khỏi Newyork khi thành phố này đang chịu những hiệu ứng của thời tiết.Ông là người duy nhất trở ngược lên miền bắc trong khi tất cả xuôi về miền nam...</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dennis Quaid","avatar":""},{"name":"Jake Gyllenhaal","avatar":""},{"name":"Emmy Rossum","avatar":""},{"name":"Dash Mihok","avatar":""},{"name":"Jay O. Sanders","avatar":""},{"name":"Sela Ward","avatar":""},{"name":"Austin Nichols","avatar":""},{"name":"Arjay Smith","avatar":""},{"name":"Tamlyn Tomita","avatar":""},{"name":"Sasha Roiz","avatar":""},{"name":"Ian Holm","avatar":""},{"name":"Richard McMillan","avatar":""},{"name":"Nassim Sharara","avatar":""},{"name":"Carl Alacchi","avatar":""},{"name":"Kenneth Welsh","avatar":""},{"name":"Michel ''Gish'' Abou-Samah","avatar":""},{"name":"Kenneth","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug