INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngay-khong-xa', 'Ngày Không Xa', 'The Day After Tomorrow', 'ngày không xa the day after tomorrow dennis quaid jake gyllenhaal emmy rossum dash mihok jay o. sanders sela ward austin nichols arjay smith tamlyn tomita sasha roiz ian holm richard mcmillan nassim sharara carl alacchi kenneth welsh michel ''gish'' abou-samah kenneth ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alexander-dai-de', 'Alexander Đại đế', 'Alexander', 'https://phimimg.com/upload/vod/20231108-1/512f99250427f7ffe48baaf2b66b8410.jpg', 'https://phimimg.com/upload/vod/20231108-1/0862dbcdbc93d3088af7a80906ecf829.jpg', '<p>Đó là rất nhiều điều đối với nhiều người: một vị vua chiến binh đẹp trai đầy tham vọng, dũng cảm và kiêu ngạo của tuổi trẻ, dẫn dắt đội quân nhỏ bé của mình chống lại lực lượng Ba Tư khổng lồ ... một đứa con trai tuyệt vọng tìm kiếm sự chấp thuận của người cha nghiêm khắc, cứng rắn trận chiến, và người đấu tranh giữa lòng trung thành với nó và tình yêu của anh dành cho mẹ mình ... một kẻ chinh phục tàn nhẫn, người không bao giờ thua trận và đẩy binh lính của mình đến tận cùng của thế giới đã biết ... một người có tầm nhìn, chiến công và định mệnh dấu ấn của họ về lịch sử, giúp định hình thế giới của chúng ta ngày nay. Ông là tất cả và nhiều hơn nữa. Ông là Alexander Đại đế.</p>', 'Full', 1, 'single', 'completed', 17, 2004, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Val Kilmer","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Jessie Kamm","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Connor Paolo","avatar":""},{"name":"Patrick Carroll","avatar":""},{"name":"Peter Williamson","avatar":""},{"name":"Morgan Christopher Ferris","avatar":""},{"name":"Rob Earley","avatar":""},{"name":"Aleczander Gordon","avatar":""},{"name":"John Kavanagh","avatar":""},{"name":"Gary","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf