INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-tuoi-30', 'Thiếu Nữ Tuổi 30', '13 Going on 30', 'https://phimimg.com/upload/vod/20231108-1/acbe5b25ed8d45117b55882337cc4059.jpg', 'https://phimimg.com/upload/vod/20231108-1/b3715eb07c65c2b8ee747152bd53ac3c.jpg', '<p>Sinh nhật thứ 13, Jenna ước trở thành người lớn để có thể tự quyết định cuộc sống. Điều ước đã trở thành hiện thực khi những hạt bụi màu nhiệm biến Jenna từ một cô bé nhút nhát thành nữ biên tập viên thành đạt và cực kỳ quyến rũ. Tuy nhiên cô nhanh chóng nhận ra làm người lớn thật sự không dễ, quá nhiều rắc rối, muộn phiền và nhất là khi cậu bạn thân thời thơ ấu đã không còn nhớ đến mình và chuẩn bị lấy vợ.</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Garner","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Christa B. Allen","avatar":""},{"name":"Sean Marquette","avatar":""},{"name":"Alexandra Kyle","avatar":""},{"name":"Kathy Baker","avatar":""},{"name":"Phil Reeves","avatar":""},{"name":"Lynn Collins","avatar":""},{"name":"Sam Ball","avatar":""},{"name":"Susan Egan","avatar":""},{"name":"Marcia DeBonis","avatar":""},{"name":"Kiersten Warren","avatar":""},{"name":"Scout Taylor-Compton","avatar":""},{"name":"Jim Gaffigan","avatar":""},{"name":"Alex Black","avatar":""},{"name":"Ashley","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324529);
