INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-lo-lem', 'Câu Chuyện Lọ Lem', 'A Cinderella Story', 'https://phimimg.com/upload/vod/20231103-1/c57c02a3420a4a4bb79a76c8e65e6561.jpg', 'https://phimimg.com/upload/vod/20231103-1/9975af951e0d46a5e67d9c46b0835d1b.jpg', '<p>Samantha Montgomery (Hilary Duff) hoặc &quot;Sam&quot;, có một tuổi thơ thô lỗ với cha cô chết trong một trận động đất và một mẹ kế mới với hai cô con gái khủng khiếp. Nhưng về mặt tươi sáng, Sam có một người bạn thân tuyệt vời có tên Carter (Dan Byrd) và mối quan hệ e-mail với một chàng trai tên là Nomad. Một ngày nọ, Sam nhận được một e-mail từ Nom Domad của cô nói rằng anh muốn gặp cô ở giữa sàn nhảy tại buổi khiêu vũ Halloween của trường trung học. Cô chấp nhận lời mời và lướt vào phòng mặc trang phục tốt nhất từ trước đến nay. NOMAD của cô ấy đưa cô ấy ra ngoài nơi họ chia sẻ một điệu nhảy lãng mạn cùng nhau và Sam nhận ra rằng người bạn e-mail của cô ấy là chàng trai nổi tiếng nhất ở trường, Austin Ames (Chad Michael Murray). Cô ấy quay trở lại quán ăn mẹ kế của mình trước khi cô ấy biết rằng cô ấy đã đi đến điệu nhảy và thả điện thoại trên đường đi. Austin tìm thấy nó và bắt đầu tìm kiếm Lọ Lem của mình.</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Hilary Duff","avatar":""},{"name":"Chad Michael Murray","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Dan Byrd","avatar":""},{"name":"Regina King","avatar":""},{"name":"Julie Gonzalo","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Madeline Zima","avatar":""},{"name":"Andrea Avery","avatar":""},{"name":"Mary Pat Gleason","avatar":""},{"name":"Paul Rodríguez","avatar":""},{"name":"Whip Hubley","avatar":""},{"name":"Kevin Kilner","avatar":""},{"name":"Erica Hubbard","avatar":""},{"name":"Simon Helberg","avatar":""},{"name":"Brad Bufanda","avatar":""},{"name":"J. D. Pardo","avatar":""},{"name":"Aimee-","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324529);
