INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-ra-de-chien-dau', 'Sinh Ra Để Chiến Đấu', 'Born to Fight', 'https://phimimg.com/upload/vod/20231113-1/7a67fb747035e59dabc88eda1c6a959f.jpg', 'https://phimimg.com/upload/vod/20231113-1/8cd00d3f1613f27f248166a8e155fcfa.jpg', '<p>Trong cuộc truy bắt tướng Yang, tên cầm đầu một đội quân khủng bố nguy hiểm, người cấp trên mà Pe Deaw kính trọng nhất đã hy sinh. Sau nhiệm vụ lần đó, Pe Deaw xin nghỉ phép, cùng cô em gái theo đoàn công tác xã hội của nhóm vận động viên thể dục - thể thao đến thăm làng Pantong. Không ngờ, ngôi làng đột ngột bị bao vây bởi một nhóm khủng bố hùng hậu, tự xưng là quân đội dưới trướng tướng Yang. Chúng lập đài quan sát, phong toả toàn bộ ngôi làng, buộc chính phủ phải thả tướng Yang. Điều kiện trao đổi là mạng sống của tất cả người dân trong làng. Đồng thời, chúng bí mật lập trình cho một tên lửa hạt nhân phóng thẳng đến đích là thủ đô Bangkok, hòng huỷ diệt hoàn toàn bộ mặt của Thái Lan… Không thể đứng nhìn những người dân vô tội lần lượt bị thiệt mạng, Pe Deaw đã chiến đấu bằng tất cả bản năng của mình, quyết không để một người nào nữa phải chết…</p>', 'Full', 1, 'single', 'completed', 19, 2004, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Dan Chupong","avatar":""},{"name":"Nappon Gomarachun","avatar":""},{"name":"Santisuk Promsiri","avatar":""},{"name":"Piyapong Piew-on","avatar":""},{"name":"Somrak Khamsing","avatar":""},{"name":"Amornthep Waewsang","avatar":""},{"name":"Suebsak Pansueb","avatar":""},{"name":"Nantaway Wongwanichislip","avatar":""},{"name":"Kessarin Ektawatkul","avatar":""},{"name":"Rattaporn Khemtong","avatar":""},{"name":"Chatthapong Phantana-Angkul","avatar":""},{"name":"Sasisa Jindamanee","avatar":""},{"name":"Payong Mounda","avatar":""},{"name":"Sw","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324529);
