INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-than-thuc-giac', 'Tử Thần Thức Giấc', 'Wake of Death', 'https://phimimg.com/upload/vod/20231103-1/7a9c09ac8eafc99b9d41cb3ba01864e3.jpg', 'https://phimimg.com/upload/vod/20231103-1/5b4d524fdda95af4cac89e90b1715927.jpg', '<p>Ben Archer, một cựu nhân viên thực thi pháp luật, tìm cách trả thù một tên trùm Trung Quốc tàn nhẫn chịu trách nhiệm về vụ giết vợ dã man của mình. Khi Archer gia nhập lực lượng với những người bạn cũ trong thế giới ngầm của mình, một cuộc chiến tổng lực được tiến hành chống lại Hội Tam hoàng Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Valerie Tian","avatar":""},{"name":"Philip Tan","avatar":""},{"name":"Tony Schiena","avatar":""},{"name":"Claude Hernandez","avatar":""},{"name":"Lisa King","avatar":""},{"name":"Anthony Fridjhon","avatar":""},{"name":"Danny Keogh","avatar":""},{"name":"Pierre Marais","avatar":""},{"name":"Warrick Grier","avatar":""},{"name":"Tom Wu","avatar":""},{"name":"Jacqueline Chan","avatar":""},{"name":"Burt Kwouk","avatar":""},{"name":"Joon Chong","avatar":""},{"name":"Bo Petersen","avatar":""},{"name":"Tarryn Meaker","avatar":""},{"name":"Arnold Chon","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324529);
