INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('203040', '20/30/40', '20/30/40', 'https://phimimg.com/upload/vod/20231109-1/1873e22a177b51a20f7a264e9c4bd943.jpg', 'https://phimimg.com/upload/vod/20231109-1/54a1b246ed4b37701b74682455287778.jpg', '<p>Ba phụ nữ ở các độ tuổi 20, 30 và 40 phải tìm cách vượt qua những thử thách mà họ đang đối mặt trong cuộc sống và tình yêu.</p>', 'Full', 1, 'single', 'completed', 17, 2004, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Sylvia Chang","avatar":""},{"name":"René Liu","avatar":""},{"name":"Angelica Lee","avatar":""},{"name":"Kate Yeung","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Richie Jen","avatar":""},{"name":"Chen Bolin","avatar":""},{"name":"Umin Boya","avatar":""},{"name":"Joanne Tseng","avatar":""},{"name":"Phoebe Huang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324529);
