INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-lua', 'Biển Lửa', 'Hidalgo', 'https://phimimg.com/upload/vod/20231101-1/36157b7d52929fa53927687e7a68acd7.jpg', 'https://phimimg.com/upload/vod/20231101-1/955e0c09cdd8223e723b400dcd49b012.jpg', '<p>Năm 1890, Gia đình hoàng tộc Sheik lần đầu tiên mời người Mỹ đến tham dự cuộc đua ngựa Ocean Of Fire qua sa mạc Ả Rập, sự thử thách gay go nhất để tìm kiếm chú ngựa bền bỉ nhất. Frank T. Hopkins (Mortensen) là anh chàng cao bồi đã đến tham dự cùng chú ngựa Hidalgo. Cuộc đua không chỉ là vinh dự và kiêu hãnh mà còn là cuộc đua cho mạng sống của cả Frank và Hidalgo.</p>', 'Full', 1, 'single', 'completed', 23, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Viggo Mortensen","avatar":""},{"name":"Zuleikha Robinson","avatar":""},{"name":"Omar Sharif","avatar":""},{"name":"Louise Lombard","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Adoni Maropis","avatar":""},{"name":"Silas Carson","avatar":""},{"name":"C. Thomas Howell","avatar":""},{"name":"Chris Owen","avatar":""},{"name":"Frank Collison","avatar":""},{"name":"Victor Talmadge","avatar":""},{"name":"Adam Alexi-Malle","avatar":""},{"name":"Harsh Nayyar","avatar":""},{"name":"Joshua Wolf Coleman","avatar":""},{"name":"Saïd Taghmaoui","avatar":""},{"name":"Peter Mensah","avatar":""},{"name":"F","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324529);
