INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-map-dom-huyen-thoai', 'Cá Mập Đốm Huyền Thoại', 'The Life Aquatic with Steve Zissou', 'https://phimimg.com/upload/vod/20231101-1/e7fbccec406c9ce4077e894d9b1ee198.jpg', 'https://phimimg.com/upload/vod/20231101-1/5fc3c1184c9167fdae12b2bc5879f4e1.jpg', '<p>Nhà hải dương học nổi tiếng Steve Zissou đã thề sẽ trả thù con cá mập quý hiếm đã nuốt chửng một thành viên trong đoàn của ông. Ngoài đội thông thường của mình, anh ấy còn tham gia cùng trên thuyền của mình với Ned, một người đàn ông tin rằng Zissou là cha của mình, và Jane, một nhà báo đang mang thai bởi một người đàn ông đã có gia đình. Họ đi du lịch trên biển, tất cả thường xuyên đụng độ cướp biển và có lẽ đau đớn hơn là nhiều nhân vật khác nhau trong quá khứ của Zissou, bao gồm cả người vợ bị ghẻ lạnh của anh, Eleanor.</p>', 'Full', 1, 'single', 'completed', 15, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Murray","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"Bud Cort","avatar":""},{"name":"Seu Jorge","avatar":""},{"name":"Robyn Cohen","avatar":""},{"name":"Waris Ahluwalia","avatar":""},{"name":"Niels Koizumi","avatar":""},{"name":"Pawel Wdowczak","avatar":""},{"name":"Matthew Gray Gubler","avatar":""},{"name":"Seymour Cassel","avatar":""},{"name":"Antonio Monda","avatar":""},{"name":"Isab","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324529);
