INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-tri-tue', 'Trò Chơi Trí Tuệ', 'Mind Game', 'https://phimimg.com/upload/vod/20231101-1/7e4d4bf7c9115ed748568f819b0b4008.jpg', 'https://phimimg.com/upload/vod/20231101-1/b9ca69567d93a23cceee73bdb1e97e0f.jpg', '<p>Phim kể về Nishi, một kẻ thất bại phải lòng bạn gái thời thơ ấu của mình. Sau cuộc chạm trán với mafia Nhật Bản, bộ phim theo chân Nishi khi anh hành trình đến thiên đường và quay trở lại, và cuối cùng bị mắc kẹt ở một nơi thậm chí còn khó xảy ra hơn.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2004, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Koji Imada","avatar":""},{"name":"Sayaka Maeda","avatar":""},{"name":"Takashi Fujii","avatar":""},{"name":"Seiko Takuma","avatar":""},{"name":"Tomomitsu Yamaguchi","avatar":""},{"name":"Toshio Sakata","avatar":""},{"name":"Jôji Shimaki","avatar":""},{"name":"Rintaro Nishi","avatar":""},{"name":"Kenichi Chujou","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324529);
