INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen', 'Lời Nguyền', 'The Grudge', 'https://phimimg.com/upload/vod/20231101-1/5af41b2e8fa74cdf5358206f0bc2062b.jpg', 'https://phimimg.com/upload/vod/20231101-1/3e0dc3fe2d034367b84f6db54469680a.jpg', '<p>Hai du học sinh Mỹ Karen và Doug quyết định chọn Nhật Bản là điểm dừng chân sau nhiều lựa chọ đắn đo. Karen tìm công việc làm thêm tại trung tâm dưỡng lão. Karen được giới thiệu tới chăm sóc một bà cụ, cô không hề biết rằng người chăm sóc bà cụ đã biến mất cách đó mấy ngày. Cảnh tượng khác lạ trong ngôi nhà như báo trước rằng căn nhà này không hề bình thường.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sarah Michelle Gellar","avatar":""},{"name":"Jason Behr","avatar":""},{"name":"Takako Fuji","avatar":""},{"name":"Yuya Ozeki","avatar":""},{"name":"William Mapother","avatar":""},{"name":"Clea DuVall","avatar":""},{"name":"KaDee Strickland","avatar":""},{"name":"Grace Zabriskie","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Rosa Blasi","avatar":""},{"name":"Ted Raimi","avatar":""},{"name":"Ryo Ishibashi","avatar":""},{"name":"Yoko Maki","avatar":""},{"name":"Takashi Matsuyama","avatar":""},{"name":"Hiroshi Matsunaga","avatar":""},{"name":"Hajime Okayama","avatar":""},{"name":"Yoshiyuki Mo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324529);
