INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-hai-ten-cuop-the-ky', 'Mười Hai Tên Cướp Thế Kỷ', 'Ocean''s Twelve', 'https://phimimg.com/upload/vod/20231101-1/4d1c941c92bc5304b99b25c7b8c9a6f5.jpg', 'https://phimimg.com/upload/vod/20231101-1/8d65d3f53929dd96ac32fa248e002cf6.jpg', '<p>Vậy là đã 3 năm trôi qua kể từ khi Danny Ocean cùng 10 đồng đội tiến hành thành công vụ cướp tiền hoành tráng nhất trong lịch sử. Qua mặt quý ông Terry Benedict, &quot;11 Tên Cướp Thế Kỷ&quot; đã cuỗm đi 150 triệu USD tiền mặt từ một sòng bạc ở Las Vegas. Vừa tức vì bị mất tiền, vừa giận vì bị hạ nhục, Terry quyết truy tìm 11 kẻ lừa đảo nhằm rửa mối hận này và đòi cả phần lãi sau ngần ấy năm.Ocean và bạn bè chỉ có 12 ngày để kiếm đủ tiền để trả cho Terry. Lần này nhóm Ocean tái xuất giang hồ và nhắm đến mục tiêu mới, viên kim cương trị giá hàng triệu USD đang được trưng bày tại viện bảo tàng Amsterdam.Đây quả là một thử thách lớn với họ, bởi nhóm vừa phải tìm cách qua mặt lực lượng an ninh bảo vệ, vốn được cảnh sát ...</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Andy García","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Bernie Mac","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Casey Affleck","avatar":""},{"name":"Scott Caan","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"Eddie Jemison","avatar":""},{"name":"Carl Reiner","avatar":""},{"name":"Elliott Gould","avatar":""},{"name":"Shaobo Qin","avatar":""},{"name":"Eddie Izzard","avatar":""},{"name":"Jeroen Krabbé","avatar":""},{"name":"Robbie Coltran","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324529);
