INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('muoi-hai-ten-cuop-the-ky', 'Mười Hai Tên Cướp Thế Kỷ', 'Ocean''s Twelve', 'mười hai tên cướp thế kỷ ocean''s twelve george clooney brad pitt matt damon catherine zeta-jones andy garcía don cheadle bernie mac julia roberts casey affleck scott caan vincent cassel eddie jemison carl reiner elliott gould shaobo qin eddie izzard jeroen krabbé robbie coltran ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-mot-mai-cheo', 'Không Một Mái Chèo', 'Without a Paddle', 'https://phimimg.com/upload/vod/20231101-1/99a6c794f54763c9662d6762e694eb8a.jpg', 'https://phimimg.com/upload/vod/20231101-1/43467c543df8bf915ea3d8be8de499eb.jpg', '<p>3 chàng trai trẻ đi vào vùng Oregon hoang dã để tìm kiếm kho báu bị mất tích. Họ dùng ca-nô đi về phía thượng nguồn mà không hề biết mình đang phạm phải sai lầm. Bị đuổi bắt bởi 2 người nông dân buôn lậu, họ chạm trán với cuộc thách thức chết người và phải tự tìm cách bảo vệ mình.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Seth Green","avatar":""},{"name":"Matthew Lillard","avatar":""},{"name":"Dax Shepard","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"Abraham Benrubi","avatar":""},{"name":"Antony Starr","avatar":""},{"name":"Burt Reynolds","avatar":""},{"name":"Christina Moore","avatar":""},{"name":"Rachel Blanchard","avatar":""},{"name":"Bonnie Somerville","avatar":""},{"name":"Ray Baker","avatar":""},{"name":"Andrew Hampton","avatar":""},{"name":"Jarred Rumbold","avatar":""},{"name":"Matthew Price","avatar":""},{"name":"Carl Snell","avatar":""},{"name":"Nadine Bernecker","avatar":""},{"name":"David Stott","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324529);
