INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-ban-tia-3', 'Lính Bắn Tỉa 3', 'Sniper 3', 'https://phimimg.com/upload/vod/20231030-1/a416d9e15542ce3807444db78c65dd51.jpg', 'https://phimimg.com/upload/vod/20231030-1/643973f29827a11a03d22a3b242e7946.jpg', '<p>Sau khi tiêu diệt các lãnh chúa, trùm ma túy và sát thủ quốc tế, Thomas Beckett giờ đây phải đối mặt với kẻ thù cuối cùng, người bạn thân nhất của mình, Paul Finnegan.</p>', 'Full', 1, 'single', 'completed', 16, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Berenger","avatar":""},{"name":"Byron Mann","avatar":""},{"name":"Denis Arndt","avatar":""},{"name":"John Doman","avatar":""},{"name":"Troy Winbush","avatar":""},{"name":"Jeannetta Arnette","avatar":""},{"name":"William Duffy","avatar":""},{"name":"Nophand Boonyai","avatar":""},{"name":"Dom Haetrakul","avatar":""},{"name":"Govit Vattanakun","avatar":""},{"name":"Naraporn Chainin","avatar":""},{"name":"Zawit Subanunt","avatar":""},{"name":"Bangongsak Kansai","avatar":""},{"name":"Aoyama Isao","avatar":""},{"name":"Ken Streutker","avatar":""},{"name":"Zakareth Ruben","avatar":""},{"name":"Tharinee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324529);
