INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bridget-jones-ben-le-ly-luan', 'Bridget Jones: Bên Lề Lý Luận', 'Bridget Jones: The Edge of Reason', 'https://phimimg.com/upload/vod/20231030-1/d9b8f96484009562e77d11833bef3f0d.jpg', 'https://phimimg.com/upload/vod/20231030-1/e8ae02e68d802f3cf247e38a9231d4c9.jpg', '<p>Trong phần tiếp theo này của bộ phim đình đám, Bridget – cô nàng độc thân trước đây – nhận ra rằng cuộc sống với anh chàng người yêu mới không lung linh như cô tưởng.</p>', 'Full', 1, 'single', 'completed', 18, 2004, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Renée Zellweger","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Hugh Grant","avatar":""},{"name":"Jacinda Barrett","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Gemma Jones","avatar":""},{"name":"Sally Phillips","avatar":""},{"name":"Celia Imrie","avatar":""},{"name":"James Faulkner","avatar":""},{"name":"Shirley Henderson","avatar":""},{"name":"James Callis","avatar":""},{"name":"Neil Pearson","avatar":""},{"name":"Jessica Hynes","avatar":""},{"name":"Donald Douglas","avatar":""},{"name":"Shirley Dixon","avatar":""},{"name":"Jeremy Paxman","avatar":""},{"name":"Ian McNeice","avatar":""},{"name":"Pa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324529);
