INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-5-loi-nguyen-thanh-kiem', 'Đảo Hải Tặc 5: Lời Nguyền Thành Kiếm', 'One Piece: Curse of the Sacred Sword', 'https://phimimg.com/upload/vod/20231030-1/dc56fdaf636cb1b09a694e609df82fd7.jpg', 'https://phimimg.com/upload/vod/20231030-1/5d48dad21e5805209766ea183ce87bd9.jpg', '<p>Trên Asuka Island, băng Mũ Rơm được biết về một thanh kiếm huyền thoại và đó còn là thanh kiếm đắt nhất trên thế giới, nhưng thanh kiếm này cũng mang theo lời nguyền chết người. Khi trở về thuyền, họ phát hiện Zoro – người được giao nhiệm vụ canh thuyền đã biến mất... Hai sự kiện trùng hợp này có liên quan đến nhau hay không? Điều gì đang chờ đợi họ ở phía trước?</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2004, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayumi Tanaka","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Ryoka Yuzuki","avatar":""},{"name":"Shido Nakamura","avatar":""},{"name":"Hiroki Uchi","avatar":""},{"name":"Seiji Sasaki","avatar":""},{"name":"Masami Hisamoto","avatar":""},{"name":"Takeshi Aono","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Eiji Takemoto","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324529);
