INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-bao-thu-2', 'Cô Dâu Báo Thù 2', 'Kill Bill: Vol. 2', 'https://phimimg.com/upload/vod/20231026-1/d6facae56b5b682f7dbc1ef90155c28d.jpg', 'https://phimimg.com/upload/vod/20231026-1/f91ce01327a2634c5fee9fb1c49ccd03.jpg', '<p>Phần 2 mở đầu với những sự kiện xảy ra trước vụ thảm sát tại thánh đường Two Pines, thành phố El Paso, bang Texas. Hôm đó, một đôi uyên ương tập dượt để chuẩn bị cho hôn lễ chính thức. Chú rể, Tommy, sở hữu một cửa hàng trong thành phố, còn cô dâu tên Arleen. Một người đàn ông trạc ngũ tuần tên Bill (David Carradine) xuất hiện trước mặt quan khách. Với phong thái lịch thiệp, vui vẻ, ông ta tự giới thiệu là cha của cô dâu. Arleen kéo Bill ra một chỗ khuất, cầu xin ông ta để cô yên trong ngày cưới và Bill tỏ vẻ đồng ý.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Uma Thurman","avatar":""},{"name":"David Carradine","avatar":""},{"name":"Daryl Hannah","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Gordon Liu Chia-hui","avatar":""},{"name":"Michael Parks","avatar":""},{"name":"Perla Haney-Jardine","avatar":""},{"name":"Larry Bishop","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Vivica A. Fox","avatar":""},{"name":"Julie Dreyfus","avatar":""},{"name":"Christopher Allen Nelson","avatar":""},{"name":"Helen Kim","avatar":""},{"name":"Laura Cayouette","avatar":""},{"name":"Jun Kunimur","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324529);
