INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-do', 'Quỷ Đỏ', 'Hellboy', 'https://phimimg.com/upload/vod/20231026-1/1a0688ecfea72e4d4a3a45e26a477e58.jpg', 'https://phimimg.com/upload/vod/20231026-1/6f7c4c848456b102c05bd7ead5d66bbc.jpg', '<p>Năm 1944, mục đích của mọi phù thuỷ, đứa con của Satan là Hellboy đã bị lạc ra khỏi nhà mình và được nhận nuôi bới các nhân viên cảnh sát của Mỹ. Được nuôi dạy với mục đích lớn lên anh sẽ làm người tốt nhưng anh lại lớn lên với hình dạng khác người với da đỏ rực, 1 cái đuôi, màng tay và 2 lỗ hổng lớn nơi mà sừng anh đã mọc. Hellboy được bổ nhiệm điều tra một chuyện lạ và câu chuyện này đã đưa anh gặp kẻ thù ngày xưa, Nazi, kẻ đã thay đổi số phận của anh...</p>', 'Full', 1, 'single', 'completed', 25, 2004, 'Vietsub', 'HD', 'Séc', 0, '[{"name":"Ron Perlman","avatar":""},{"name":"Selma Blair","avatar":""},{"name":"Doug Jones","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Rupert Evans","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Ladislav Beran","avatar":""},{"name":"Bridget Hodson","avatar":""},{"name":"Karel Roden","avatar":""},{"name":"Brian Steele","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Kevin Trainor","avatar":""},{"name":"Brian Caspe","avatar":""},{"name":"James Babson","avatar":""},{"name":"Stephen Fisher","avatar":""},{"name":"Garth Cooper","avatar":""},{"name":"Angus MacInnes","avatar":""},{"name":"Jim Howick","avatar":""},{"name":"Ma","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324529);
