INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-du-lich-chau-au', 'Chuyến Du Lịch Châu Âu', 'EuroTrip', 'https://phimimg.com/upload/vod/20231026-1/cf1ac8b725711652efb3e3f38e3e8dc0.jpg', 'https://phimimg.com/upload/vod/20231026-1/f626ff5d5d03ab086217baacab1d862c.jpg', '<p>EuroTrip là một bộ phim hài hước của bộ đôi đạo diễn Jeff Schaffer và Alec Berg. Nội dung phim là câu chuyện của nhân vật chính là anh chàng Scott Thomas được một người bạn gốc Đức chỉ dẫn vượt qua kì thi môn tiếng Đức, sau kì thi người bạn đã rủ cậu ta đến du lịch châu Âu thăm nước Đức một chuyến, Scott Thomas rất nghi ngờ về điều đó vì cậu kia là con trai, tiếp theo Thomas cứ nghĩ cậu bạn của mình là một anh chàng gay chính tông đang lên kế hoạch làm thịt mình nên hơi lưỡng lự trước quyết định đi hay không trong phim Chuyến Du Lịch Châu Âu - EuroTrip (2004). Nhưng khi Thomas biết được người bạn đồng hành cùng họ là một cô gái xinh đẹp ngây ngất đã khiến cho cậu ta thay đổi suy nghĩ và quyết định đi ngay lập tức.</p>', 'Full', 1, 'single', 'completed', 21, 2004, 'Vietsub', 'HD', 'Séc', 0, '[{"name":"Scott Mechlowicz","avatar":""},{"name":"Jacob Pitts","avatar":""},{"name":"Travis Wester","avatar":""},{"name":"Michelle Trachtenberg","avatar":""},{"name":"Jessica Boehrs","avatar":""},{"name":"Kristin Kreuk","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Dominic Raacke","avatar":""},{"name":"Jana Pallaske","avatar":""},{"name":"Nial Iskhakov","avatar":""},{"name":"Petr Jákl","avatar":""},{"name":"Molly Schade","avatar":""},{"name":"Jakki Degg","avatar":""},{"name":"Lenka Dayrit","avatar":""},{"name":"Cathy Meils","avatar":""},{"name":"J.P. Manoux","avatar":""},{"name":"Patrick Rapold","avatar":""},{"name":"Fr","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324529);
