INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-than-ky', 'Câu Chuyện Thần Kỳ', 'Lemony Snicket''s A Series of Unfortunate Events', 'https://phimimg.com/upload/vod/20231026-1/a67c9256931f9a2827d2432683578bdd.jpg', 'https://phimimg.com/upload/vod/20231026-1/b1dd01c2a64f1f0a6b07f7f57bb8c912.jpg', '<p>Cha mẹ của ba đứa trẻ giàu có thiệt mạng trong một vụ hỏa hoạn. Khi họ được gửi đến một người họ hàng xa, họ phát hiện ra rằng anh ta đang âm mưu giết họ và chiếm đoạt tài sản của họ.</p>', 'Full', 1, 'single', 'completed', 19, 2004, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Emily Browning","avatar":""},{"name":"Liam Aiken","avatar":""},{"name":"Jim Carrey","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Kara Hoffman","avatar":""},{"name":"Shelby Hoffman","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Billy Connolly","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Jane Adams","avatar":""},{"name":"Craig Ferguson","avatar":""},{"name":"Jamie Harris","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Cedric the Entertainer","avatar":""},{"name":"Bob Clend","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324529);
