INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trung-phat', 'Kẻ Trừng Phạt', 'The Punisher', 'https://phimimg.com/upload/vod/20231024-1/065b7ef7500fd63e5c172c41e8fab779.jpg', 'https://phimimg.com/upload/vod/20231024-1/697ebb383dabdb84be07b5e1883bb4ab.jpg', '<p>The Punisher là một bộ phim hành động thú vị phỏng theo bộ truyện tranh “Welcome Back, Frank”. Frank Castle vốn là thành viên đội đặc nhiệm và điệp viên ngầm FBI quyết định thay đổi để có được sự bình yên với cô vợ Maria và cậu con trai Will. Trong nhiệm vụ cuối cùng, Frank đóng giả một tên môi giới vũ khí lậu rất hoàn hảo, nhưng một trục trặc nhỏ xảy ra. Đó là sự xuất hiện của Bobby Saint, con trai ông trùm xã hội đen Howard Saint trong cuộc trao đổi. Khi cảnh sát ập đến theo đúng kế hoạch, hắn vô tình bị bắn chết, gia đình Saint ráo riết đòi trả thù FBI. Howard sai đám tay chân tới tấn công gia đình Castle và tất cả các thành viên đều bị chúng giết, ngoại trừ Frank. Anh sống sót với nỗi đau quá lớn cả về thể xác lẫn tâm hồn, quyết tâm sắt đá trừng trị kẻ ác, Frank một mình đối đầu với thế lực ngầm của nhà Howard Saint. Trong cuộc chiến một mất một còn này, ai là kẻ chiến thắng?</p>', 'Full', 1, 'single', 'completed', 16, 2004, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Thomas Jane","avatar":""},{"name":"John Travolta","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Roy Scheider","avatar":""},{"name":"Laura Harring","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Samantha Mathis","avatar":""},{"name":"James Carpinello","avatar":""},{"name":"A. Russell Andrews","avatar":""},{"name":"Eddie Jemison","avatar":""},{"name":"John Pinette","avatar":""},{"name":"Rebecca Romijn","avatar":""},{"name":"Mark Collie","avatar":""},{"name":"Marcus Johns","avatar":""},{"name":"Omar Avila","avatar":""},{"name":"Russell Durham Comegys","avatar":""},{"name":"Antoni Cor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324529);
