INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-duong-vinh-cuu-cua-tam-hon-thanh-khiet', 'Ánh Dương Vĩnh Cửu Của Tâm Hồn Thanh Khiết', 'Eternal Sunshine of the Spotless Mind', 'https://phimimg.com/upload/vod/20231022-1/cf7fde3dc06509ececf122abd649e25d.jpg', 'https://phimimg.com/upload/vod/20231022-1/d93b4d475f496f700efe4774adc1909a.jpg', '<p>Joel (Jim Carrey) bàng hoàng nhận ra rằng ký ức của cô bạn gái Clementine (Kate Winslet) về tình yêu của 2 người đã bị xóa mờ trong tâm trí.Đau khổ và tuyệt vọng, Joel nhờ tiến sĩ Howard Mierzwiak (Tom Wilkinson) thực hiện việc xóa hình ảnh của Clementine ra khỏi trái tim anh. Nhưng trong khi thực hiện điều này, Joel lại cảm thấy vẫn còn yêu Clemetine. Thế là cuộc rượt đuổi tình yêu bắt đầu khiến Joel nhận ra rằng anh chưa bao giờ dứt bỏ được Clemetine ra khỏi trái tim mình...</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Kirsten Dunst","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Elijah Wood","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Jane Adams","avatar":""},{"name":"David Cross","avatar":""},{"name":"Deirdre O''Connell","avatar":""},{"name":"Thomas Jay Ryan","avatar":""},{"name":"Ryan Whitney","avatar":""},{"name":"Lola Daehler","avatar":""},{"name":"Debbon Ayer","avatar":""},{"name":"Gerry Robert Byrne","avatar":""},{"name":"Brian Price","avatar":""},{"name":"Josh Flitter","avatar":""},{"name":"Paulie Litt","avatar":""},{"name":"Amir","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984