INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-to-quoc', 'Không Tổ Quốc', 'The Terminal', 'https://phimimg.com/upload/vod/20231023-1/9f9de4f8efc342c534273efda0e127c8.jpg', 'https://phimimg.com/upload/vod/20231023-1/a98367b8ba567b65668505cd327cec60.jpg', '<p>Bộ phim xoay quanh chuyến bay của một vị hành khách từ Đông Âu. Anh tình cờ trở thành “công dân” tại cảng hàng không ở New York vì chiến tranh nổ ra đã tàn phá và xóa tên đất nước của anh ra khỏi bản đồ, làm cho passport của anh không còn hiệu lực. Anh buộc phải sống tạm thời tại sân bay, làm bạn với các phi hành đoàn, và thật bất ngờ, anh tìm được tình yêu của mình cũng chính tại “ngôi nhà” lạ lùng này.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Chi McBride","avatar":""},{"name":"Diego Luna","avatar":""},{"name":"Barry Shabaka Henley","avatar":""},{"name":"Kumar Pallana","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Eddie Jones","avatar":""},{"name":"Jude Ciccolella","avatar":""},{"name":"Corey Reynolds","avatar":""},{"name":"Guillermo Díaz","avatar":""},{"name":"Rini Bell","avatar":""},{"name":"Stephen Mendel","avatar":""},{"name":"Valeriy Nikolaev","avatar":""},{"name":"Michael Nouri","avatar":""},{"name":"Ana Maria","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324529);
