INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-to-quoc', 'Không Tổ Quốc', 'The Terminal', 'không tổ quốc the terminal tom hanks catherine zeta-jones stanley tucci chi mcbride diego luna barry shabaka henley kumar pallana zoe saldaña eddie jones jude ciccolella corey reynolds guillermo díaz rini bell stephen mendel valeriy nikolaev michael nouri ana maria ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-bau-quoc-gia', 'Kho Báu Quốc Gia', 'National Treasure', 'https://phimimg.com/upload/vod/20231023-1/359ae685c37fb6b5298fa7b9416e7281.jpg', 'https://phimimg.com/upload/vod/20231023-1/7b8aeaea3c64fdaffe5532e4790829bd.jpg', '<p>Thợ săn kho báu Benjamin Franklin Gates đã dành cả cuộc đời của mình để tìm ra kho báu Hiệp sĩ huyền thoại Templar, được cho là một chuyến đi đáng kinh ngạc nhất mọi thời đại và được giấu ở đâu đó trên nước Mỹ. Trong bảy thế hệ, các thành viên của gia đình Gates đã tìm kiếm những manh mối do những người sáng lập của Mỹ để lại và họ đã đi đến mọi nơi trên đất nước để tìm kiếm kho báu. Giờ đây, maverick Ben cuối cùng đã phát hiện ra manh mối cuối cùng sẽ đưa anh ta đến kho báu: một bản đồ được giấu ở mặt sau của Tuyên ngôn Độc lập. Sự tồn tại của bản đồ thu hút sự chú ý của đối thủ cạnh tranh lớn của Gates, Ian Howe và Ben phải đối mặt với một vấn đề nan giải: Hoặc anh ta là người đầu tiên đánh cắp tài liệu quan trọng nhất của nước Mỹ, được bảo vệ bởi hệ thống an ninh tinh vi nhất thế giới, hoặc anh ta sẽ để nó rơi vào tay cực kỳ nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 13, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"Justin Bartha","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"David Dayan Fisher","avatar":""},{"name":"Stewart Finlay-McLennan","avatar":""},{"name":"Oleg Taktarov","avatar":""},{"name":"Stephen A. Pope","avatar":""},{"name":"Annie Parisse","avatar":""},{"name":"Mark Pellegrino","avatar":""},{"name":"Armando Riesco","avatar":""},{"name":"Erik King","avatar":""},{"name":"Don McManus","avatar":""},{"name":"Ron","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324529);
