INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-dien-mai-phuc', 'Thập Diện Mai Phục', 'House of Flying Daggers', 'https://phimimg.com/upload/vod/20231023-1/0176a88b73dddff584e033113eece9bd.jpg', 'https://phimimg.com/upload/vod/20231023-1/1a67037ab7ade7552c3a7fd6f347d4b8.jpg', '<p>Thập diện Mai Phục lấy bối cảnh năm 859 sau Công nguyên tại Trung Hoa.Tổ chức Phi Đao Môn chống lại triều đình bệ rạc đã cài được kiếm khách Lưu bộ đầu làm nội gián trong hàng ngũ binh lính triều đình, giữ chức đội trưởng cùng với Kim bộ đầu. Theo kế hoạch của Lưu, Kim chấp nhận giả làm người giải cứu cho kỹ nữ mù Tiểu Muội để tìm cách tiêu diệt Phi đao môn. Chàng không ngờ cô gái mù mà mình trót đem lòng yêu, thực ra chỉ là con mồi nhằm đưa Kim và cả triều đình vào bẫy…</p>', 'Full', 1, 'single', 'completed', 11, 2004, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Takeshi Kaneshiro","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Zhang Ziyi","avatar":""},{"name":"Song Dandan","avatar":""},{"name":"Hongfei Zhao","avatar":""},{"name":"Jun Guo","avatar":""},{"name":"Zhang Shu","avatar":""},{"name":"Jiusheng Wang","avatar":""},{"name":"Zhengyong Zhang","avatar":""},{"name":"Yongxin Wang","avatar":""},{"name":"Dong Liu","avatar":""},{"name":"Qi Zi","avatar":""},{"name":"Xuedong Qu","avatar":""},{"name":"Liping Tian","avatar":""},{"name":"Hongwei Zhao","avatar":""},{"name":"Huang Weina","avatar":""},{"name":"Ge Dan","avatar":""},{"name":"Yang Xiadong","avatar":""},{"name":"Shang Yisha","avatar":""},{"name":"Liu Ying","avatar":""},{"name":"Huang J","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be