INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giua-bay-xac-song', 'Giữa Bầy Xác Sống', 'Shaun of the Dead', 'https://phimimg.com/upload/vod/20231023-1/f14e3b8381f90543b00ace22db55360d.jpg', 'https://phimimg.com/upload/vod/20231023-1/af8e27dd47baf2616d92ee98d65f1c28.jpg', '<p>Shaun, 29 tuổi, là một nhân viên của công ty bán hàng, sống với 2 người bạn thân, Ed và Pete. Một ngày nọ, như bao ngày bình thường khác, anh dậy, anh ngồi nói chuyện với Ed, ra cửa hàng tạp hóa gần nhà mua nước ngọt và kem....thế nhưng, anh không hề để ý những việc xung quanh, anh chỉ biết đi, và làm việc của mình. Và rồi, khi Ed nói với anh có một người phụ nữ ở ngoài vườn của mình....anh và Ed dường như không sợ...mà còn đùa giỡn , anh đã phát hiện ra rằng mọi người trong thành phố dường như có những hành động rất lạ, rất kì quặc....Và anh đã biết điều gì đã xảy ra khi anh nghe tin tức trên TV...</p>', 'Full', 1, 'single', 'completed', 18, 2004, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Simon Pegg","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Kate Ashfield","avatar":""},{"name":"Lucy Davis","avatar":""},{"name":"Dylan Moran","avatar":""},{"name":"Penelope Wilton","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Peter Serafinowicz","avatar":""},{"name":"Jessica Hynes","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Matt Lucas","avatar":""},{"name":"Reece Shearsmith","avatar":""},{"name":"Tamsin Greig","avatar":""},{"name":"Julia Deakin","avatar":""},{"name":"Steve Emerson","avatar":""},{"name":"Nicola Cunningham","avatar":""},{"name":"Arvind","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 