INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-minh-tu-than', 'Bình Minh Tử Thần', 'Dawn of the Dead', 'https://phimimg.com/upload/vod/20231022-1/5d139314914592bb44b23f06f1cd821c.jpg', 'https://phimimg.com/upload/vod/20231022-1/76899d8cfd88f5c6082e240f6e54b273.jpg', '<p>Những người sống sót sau một dịch bệnh gây nhiễm bệnh biến thành zombie ăn thịt, hãy lánh nạn trong một trung tâm mua sắm. Ngoài việc chiến đấu với xác sống, họ cũng phải giải quyết các vấn đề từ bên trong.</p>', 'Full', 1, 'single', 'completed', 20, 2004, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Sarah Polley","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Ty Burrell","avatar":""},{"name":"Inna Korobkina","avatar":""},{"name":"Jake Weber","avatar":""},{"name":"Michael Kelly","avatar":""},{"name":"Kim Poirier","avatar":""},{"name":"Mekhi Phifer","avatar":""},{"name":"Matt Frewer","avatar":""},{"name":"Kevin Zegers","avatar":""},{"name":"Lindy Booth","avatar":""},{"name":"Jayne Eastwood","avatar":""},{"name":"Boyd Banks","avatar":""},{"name":"R.D. Reid","avatar":""},{"name":"Louis Ferreira","avatar":""},{"name":"Bruce Bohne","avatar":""},{"name":"Hannah Lochner","avatar":""},{"name":"Michael Barry","avatar":""},{"name":"Ermes B","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324529);
