INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('spongebob-chu-bot-bien-tinh-nghich', 'SpongeBob: Chú Bọt Biển Tinh Nghịch', 'The SpongeBob SquarePants Movie', 'https://phimimg.com/upload/vod/20231020-1/22f8bd436a9e57184f4f9e3b06960ac3.jpg', 'https://phimimg.com/upload/vod/20231020-1/dde139daecaa7dc091b75d3be23836ea.jpg', '<p>Có vấn đề trong quá trình sản xuất Bikini Bottom. Ai đó đã đánh cắp vương miện của Vua Neptune, và có vẻ như ông chủ Krab, ông chủ của SpongeBob, chính là thủ phạm. Mặc dù ông ấy vừa bị bỏ qua vì việc thúc đẩy ước mơ của mình, SpongeBob sát cánh cùng ông chủ của mình và cùng với người bạn thân Patrick của mình thực hiện một nhiệm vụ nguy hiểm đến Thành phố Shell để giành lại vương miện và cứu mạng ông Krab.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Kenny","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Rodger Bumpass","avatar":""},{"name":"Bill Fagerbakke","avatar":""},{"name":"Mr. Lawrence","avatar":""},{"name":"Jill Talley","avatar":""},{"name":"Carolyn Lawrence","avatar":""},{"name":"Mary Jo Catlett","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"David Hasselhoff","avatar":""},{"name":"Kristopher Logan","avatar":""},{"name":"D.P. FitzGerald","avatar":""},{"name":"Cole S. McKay","avatar":""},{"name":"Dylan Haggerty","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"P