INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-tho-may', 'Gã Thợ Máy', 'The Machinist', 'https://phimimg.com/upload/vod/20231021-1/7296829bf1dd242b426f58338161d3bf.jpg', 'https://phimimg.com/upload/vod/20231021-1/23921f0cc836bc5434e0ea550447d58f.jpg', '<p>Trevor Reznik, một người thợ tiện bị chứng mất ngủ suốt một năm trời khiến anh gầy rộc như một bóng ma. Trevor đối mặt với những chuyện kỳ lạ diễn ra ở xưởng làm việc và trong nhà mình, bị ám ảnh bởi một đồng nghiệp mà không một ai nghĩ rằng hắn thật sự hiện diện và bị cuốn vào trò ‘mèo vờn chuột’ của một kẻ bí ẩn luôn gửi lại lời nhắn trên tờ ghi chú dán trên tủ lạnh trong phòng anh.</p>', 'Full', 1, 'single', 'completed', 24, 2004, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Aitana Sánchez-Gijón","avatar":""},{"name":"John Sharian","avatar":""},{"name":"Michael Ironside","avatar":""},{"name":"Lawrence Gilliard Jr.","avatar":""},{"name":"Craig Stevenson","avatar":""},{"name":"Reg E. Cathey","avatar":""},{"name":"Anna Massey","avatar":""},{"name":"Matthew Romero Moore","avatar":""},{"name":"James DePaul","avatar":""},{"name":"Robert Long","avatar":""},{"name":"Chike Johnson","avatar":""},{"name":"Colin Stinton","avatar":""},{"name":"Ferran Lahoz","avatar":""},{"name":"Je","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324529);
