INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-chan-tinh-tot-bung-2', 'Gã Chằn Tinh Tốt Bụng 2', 'Shrek 2', 'https://phimimg.com/upload/vod/20231018-1/2a86a042780df2b0603d8128fe8973e1.jpg', 'https://phimimg.com/upload/vod/20231018-1/31bcdb520669fb34db405f80ea777aec.jpg', '<p>Sau khi đánh bại con rồng lửa và lãnh chúa Farquaad để giành lấy trái tim của công chúa Fiona; gã chằn tinh Shrek giờ sống cuộc sống yên bình. Cả hai trải qua kỳ nghỉ trăng mật đầy lãng mạn. Cơn ác mộng thực sự đến khi quốc vương và hoàng hậu xứ Xa thật xa vời hai con về gặp mặt. Cùng với Lừa lắm mồm, đôi vợ chồng trẻ quay về kinh thành náo nhiệt. Kinh thành thân quen chào đón công chúa Fiona, xong không ai ngờ chàng phò mã là... chằn tinh. Còn cô công chúa yểu điệu ngày nào giờ cũng trong bộ dạng phục phịch xanh lét như chồng. Chàng rể trái ý quốc vương đã khiến Bà tiên đỡ đầu, Hoàng tử quyến rũ và tên sát thủ Mèo đi hia vào cuộc nhằm... thủ tiêu Shrek để lập phò mã mới!</p>', 'Full', 1, 'hoathinh', 'completed', 21, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mike Myers","avatar":""},{"name":"Eddie Murphy","avatar":""},{"name":"Cameron Diaz","avatar":""},{"name":"Julie Andrews","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Rupert Everett","avatar":""},{"name":"Jennifer Saunders","avatar":""},{"name":"Aron Warner","avatar":""},{"name":"Kelly Asbury","avatar":""},{"name":"Cody Cameron","avatar":""},{"name":"Conrad Vernon","avatar":""},{"name":"Christopher Knights","avatar":""},{"name":"David P. Smith","avatar":""},{"name":"Mark Moseley","avatar":""},{"name":"Kelly Cooney Cilella","avatar":""},{"name":"Wendy","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug"