INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-cua', 'Lưỡi Cưa', 'Saw', 'https://phimimg.com/upload/vod/20231014-1/9e2464726895b5dd6e79e8a19c5d138c.jpg', 'https://phimimg.com/upload/vod/20231014-1/e5179afbc61d241902dd5cf81de55ba1.jpg', '<p>Bạn có giết người để được sống không? Đó là điều mà hai người đàn ông tự hỏi khi họ bị một tên sát nhân hàng loạt bắt cóc và phải hợp sức trong một tình huống chết chóc.</p>', 'Full', 1, 'single', 'completed', 19, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cary Elwes","avatar":""},{"name":"Leigh Whannell","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Monica Potter","avatar":""},{"name":"Ken Leung","avatar":""},{"name":"Makenzie Vega","avatar":""},{"name":"Michael Emerson","avatar":""},{"name":"Shawnee Smith","avatar":""},{"name":"Dina Meyer","avatar":""},{"name":"Alexandra Bokyun Chun","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324529);
