INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-tac-tam-bao', 'Tiên Tạc Tam Bảo', 'Three Of A Kind', 'https://phimimg.com/upload/vod/20231012-1/72eb1f468166f6051776bc0f652afe47.jpg', 'https://phimimg.com/upload/vod/20231012-1/6f178ca2240a8b301f8656dfcb3770c2.jpg', '<p>Tiểu thuyết gia nổi tiếng Ngân (Michael Hui) đang có một cuộc sống thoải mái nhờ tiền bản quyền của những cuốn tiểu thuyết đã xuất bản của mình. Giờ đây ông đã dồn toàn bộ sự chú ý của mình vào con gái Sophia (Miriam Yeung). Sophia đã đến độ tuổi thích hợp để kết hôn và vẫn đang tìm kiếm Hoàng tử quyến rũ của mình. Cô phải lòng Frankie (Lau Ching Wan), sếp của cô và một tay chơi. Do một tai nạn nào đó, Frankie quyết định ở lại nhà Sophia một thời gian, Sau đó, Sophia và Frankie trở thành người yêu của nhau và dự định kết hôn! Ngân yêu con gái đến mức biết mình phải hủy diệt tình yêu của họ trước khi quá muộn. Sophia phải đưa ra quyết định sinh tử giữa Frankie và cha cô...</p>', 'Full', 1, 'single', 'completed', 25, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Michael Hui","avatar":""},{"name":"Miriam Yeung","avatar":""},{"name":"Lau Ching-wan","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Lo Meng","avatar":""},{"name":"Hiro Hayama","avatar":""},{"name":"Monica Lo","avatar":""},{"name":"Jin Song","avatar":""},{"name":"Crystal Tin Yue-Lai","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324529);
