INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-quyen-ru', 'Cô Nàng Quyến Rũ', 'The Attractive One', 'null', 'https://phimimg.com/upload/vod/20231010-1/7c81b5fbfc1a59026d1fa19ae3512c3e.jpg', '<p>Người Hấp Dẫn là một bộ phim hài lãng mạn, có nhịp độ tốt, thú vị. Nó nhẹ nhàng, có chủ ý ngốc nghếch nhưng điều đó không ngăn cản nó trở thành một câu chuyện cảm động về những kẻ lập dị yêu nhau và trốn tránh thừa nhận điều đó.</p>', 'Full', 1, 'single', 'completed', 14, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Joey Yung","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Yumiko Cheng","avatar":""},{"name":"Jia Zong-Chao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324529);
