INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-thu-sat', 'Giang Hồ Thù Sát', 'One Nite In MongKok', 'https://phimimg.com/upload/vod/20231010-1/c9f79b73032088d73e6b87a80790c4c6.jpg', 'https://phimimg.com/upload/vod/20231010-1/5c7aa683652a68b1b595eb8c1bbf84c7.jpg', '<p>Khu Hoàng Giác tại Hong Kong là một trong những khu vực “thần bí” với biết bao tội ác luôn xảy ra ở nơi đây. Lai Phúc từ nước ngoài trở về để tìm tung tích của người bạn gái tên Tố Nhi, không may bị gạt phải làm kẻ giết mướn cho XHĐ. Anh gặp Đan Đan, một kỹ nữ, hai con người cùng cảnh ngộ gặp nhau và thông cảm cho nhau dưới cái chốn sa đoạ này, Đan quyết định giúp lai tìm kiếm tung tích của Tố Nhi…Nhưng sự việc vẫn chưa dừng tại đây vì Tố Nhi đã bị sát hại.</p>', 'Full', 1, 'single', 'completed', 19, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Cecilia Cheung","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Alex Fong","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Anson Leung Chun-Yat","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Paul Che Biu-law","avatar":""},{"name":"Ken Wong","avatar":""},{"name":"Henry Fong","avatar":""},{"name":"Sam Lee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324529);
