INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tra-herbal', 'Quán Trà Herbal', 'Herbal Tea', 'null', 'https://phimimg.com/upload/vod/20231010-1/f371de72492d4a75226ef124f1aa0451.jpg', '<p>Thật may mắn, nam diễn viên Dan thuê một căn hộ từ Mei-Chu. Cảm thấy có lỗi với anh, Mei-Chu giúp Dan xoay chuyển tình thế, cải thiện cuộc sống và giúp anh đoàn tụ với bạn gái cũ. Khi cô nhận ra mình yêu anh thì có phải đã quá muộn?</p>', 'Full', 1, 'single', 'completed', 29, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jordan Chan","avatar":""},{"name":"Candy Lo","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Spencer Lam","avatar":""},{"name":"Patrick Tang","avatar":""},{"name":"Lo Meng","avatar":""},{"name":"Simon Lui","avatar":""},{"name":"Ka-Yee Lee","avatar":""},{"name":"Chen Man Lei","avatar":""},{"name":"Belinda Hamnett","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324529);
