INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-the-vo-song', 'Tuyệt Thế Vô Song', 'Driving Miss Wealthy', 'null', 'https://phimimg.com/upload/vod/20231009-1/7913f744ba16be2497b62d64f47f2db9.jpg', '<p>Lương vào vai Jennifer, cô con gái hư hỏng của một triệu phú. Khi cha của Jennifer nhận ra rằng cô tiêu quá nhiều tiền, ông đã thuê Kit (Lau) đóng giả làm tài xế người Philippines và đi kèm cô. Sau đó, cha của Jennifer quyết định rằng ông sẽ dạy cô giá trị của đồng tiền và sự chăm chỉ, vì vậy ông giả vờ ốm, để lại toàn bộ số tiền cho Pamela, đối tác kinh doanh của ông. Pamela đuổi Jennifer ra đường để sống cùng Kit</p>', 'Full', 1, 'single', 'completed', 19, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Gigi Leung","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Lau Yee Tat","avatar":""},{"name":"May Law Koon-Lan","avatar":""},{"name":"Sophie Wong","avatar":""},{"name":"Jim Chim Sui-Man","avatar":""},{"name":"Chow Chung","avatar":""},{"name":"Jamie Luk Kim-Ming","avatar":""},{"name":"William Duen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324529);
