INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngua-suot-bay-nam', 'Ngứa Suốt Bảy Năm', 'Itchy Heart', 'https://phimimg.com/upload/vod/20231006-1/afd889d40220fc972c3c6d9fb8c6ecfb.jpg', 'https://phimimg.com/upload/vod/20231006-1/50a989f379298f27363484eb1aeec89b.jpg', '<p>Phản ánh chân thực quan điểm của người Hồng Kông về tình yêu và hôn nhân, &quot;Itchy Heart&quot; kể câu chuyện về một người đàn ông đã có gia đình muốn tìm kiếm sự phấn khích trong hôn nhân bằng cách gặp gỡ một người mới. Khi vợ anh đi du lịch, ham muốn phấn khích mới của Chi-man (Lau Ching-Wan) đã lấn át anh khi anh gặp Cherry (Cherry In) xinh đẹp và trẻ trung và bạn gái cũ Bing (Carina Lau). Sau khi biết vợ ngoại tình, anh quyết định ly hôn mà không biết có nên cho mình cơ hội thứ hai để yêu lần nữa hay không. Đây là một bộ phim hài phản ánh hiện thực rất thực tế về hôn nhân ngày nay. Với việc khắc họa chi tiết cảm xúc của các nhân vật, bản thân câu chuyện đã thành công tạo được tiếng vang trong lòng khán giả bằng kịch bản vừa đắng vừa ngọt.</p>', 'Full', 1, 'single', 'completed', 20, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Cherrie Ying Choi-Yi","avatar":""},{"name":"Andy On","avatar":""},{"name":"Coco Chiang Yi","avatar":""},{"name":"Hiro Hayama","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324529);
