INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-trong-rock', 'Tình Yêu Trong Rock', 'Love On The Rocks', 'https://phimimg.com/upload/vod/20231006-1/0ecbd4fc5509e5c69a08a1df74a6abbb.jpg', 'https://phimimg.com/upload/vod/20231006-1/5968ba34fc86475dfefb1da8a835a0b4.jpg', '<p>Wong bị sốc khi biết bạn gái Annie (Leung) rằng cô ấy muốn chia tay. Anh quyết định lên mạng và tìm kiếm sự giúp đỡ từ các chuyên gia tình yêu trên mạng. Anh tìm thấy Crystal, một cố vấn tình yêu 19 tuổi tự xưng là người chưa bao giờ thực sự có mối quan hệ nào. Khi cô hỗ trợ Wong bằng cách bảo anh gặp lại tất cả bạn gái cũ để tìm ra gốc rễ vấn đề của anh, hai người họ cũng nhận ra mình phải lòng nhau.</p>', 'Full', 1, 'single', 'completed', 29, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Gigi Leung","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Rain Li","avatar":""},{"name":"Alex Fong Lik-sun","avatar":""},{"name":"Kathy Chow Man-Kei","avatar":""},{"name":"Chan Fai-hung","avatar":""},{"name":"Cheuk Wan-Chi","avatar":""},{"name":"Hui Siu-Hung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324529);
