INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boc-pha-2004', 'Bộc Phá (2004)', 'Primer (2004)', 'https://phimimg.com/upload/vod/20230919-1/8e94d4762be55af6c07432deb73a3475.jpg', 'https://phimimg.com/upload/vod/20230919-1/38135b0be52ea02c3a423cab6d3b6a81.jpg', '<p><span style="font-family: ">Câu chuyện bắt đầu với 1 nhóm 4 nhà sáng chế tại gia sau khi bị ăn cắp 1 ý tưởng sản phẩm đã quyết định chế tạo 1 thiết bị có thể làm giảm trọng lượng của vật đặt trong nó. Thế nhưng Abe, 1 trong 4 người, vô tình phát hiện ra vật này sau khi được đặt trong cỗ máy đã trải qua 1 lượng thời gian dài gấp 1300 lần bình thường. Abe quyết định chế tạo 1 phiên bản lớn hơn của cỗ máy để 1 con người có thể chui vào trong và nói với Aaron về điều này. Và họ đã tạo ra một cỗ máy thời gian một cách vô tình. Họ quyết định dùng cỗ máy để chơi chứng khoán và cá độ thể thao khi mà họ biết chắc chắn kết quả mà không nói với 2 người còn lại, Phillip và Robert, bất cứ điều gì. Thế nhưng khi họ bắt đầu thử nghiệm nhiều hơn với cỗ máy, mọi chuyện không còn đơn giản như lúc đầu.</span></p>', 'Full', 1, 'single', 'completed', 22, 2004, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shane Carruth","avatar":""},{"name":"David Sullivan","avatar":""},{"name":"Casey Gooden","avatar":""},{"name":"Anand Upadhyaya","avatar":""},{"name":"Carrie Crawford","avatar":""},{"name":"Jay Butler","avatar":""},{"name":"John Carruth","avatar":""},{"name":"Juan Tapia","avatar":""},{"name":"Ashley Warren","avatar":""},{"name":"Samantha Thomson","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324529);
