INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-quai-tai-xe-2004', 'Nữ Quái Tài Xế (2004)', 'Taxi (2004)', 'https://phimimg.com/upload/vod/20230917-1/f528a091d8ff021f1c9c57bd26ca15e5.jpg', 'https://phimimg.com/upload/vod/20230917-1/637fa3ded25a6c5aea71487660671b32.jpg', '<p>Một tài xế taxi lắm lời và hung hãn có những lời khuyên hữu ích dành cho một cảnh sát xanh và kém cỏi trong việc giải quyết một chuỗi vụ cướp ngân hàng ở Thành phố New York do bộ tứ nữ cướp ngân hàng người Brazil thực hiện.</p>', 'Full', 1, 'single', 'completed', 26, 2004, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Queen Latifah","avatar":""},{"name":"Jimmy Fallon","avatar":""},{"name":"Gisele Bündchen","avatar":""},{"name":"Henry Simmons","avatar":""},{"name":"Jennifer Esposito","avatar":""},{"name":"Ann-Margret","avatar":""},{"name":"Christian Kane","avatar":""},{"name":"Ana Cristina Oliveira","avatar":""},{"name":"Patton Oswalt","avatar":""},{"name":"Ingrid Vandebosch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324529);
