INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-hau-bac', 'Diều Hâu Bạc', 'Silver Hawk', 'https://phimimg.com/upload/vod/20230912-1/f24b0d9cca63ff57c27c17bfca98d81c.jpg', 'https://phimimg.com/upload/vod/20230912-1/dbbc743fb97d3e73b8de9071521ea141.jpg', '<p><span style="font-family: ">Silver Hawk là bộ phim hành động phiêu lưu của Dương Tử Quỳnh. Trong phim cô vào vai một nữ hiệp ẩn mặt luôn giúp đỡ cảnh sát tóm gọn những tên tội phạm…Cô có một sở thích đó là đánh nhau. Cứ mỗi lần đánh nhau là cô lại tìm thấy niềm vui cho bản thân mình. Việc làm tốt của cô ngược lại khiến một nữ cảnh sát cảm thấy tức tối vì thua kém. Và rồi mục tiêu của họ là một tên tội phạm nguy hiểm đang có âm mưu đen tối gây lo ngại đến cho loài người...</span></p>', 'Full', 1, 'single', 'completed', 29, 2004, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Michelle Yeoh","avatar":""},{"name":"Richie Jen","avatar":""},{"name":"Li Bingbing","avatar":""},{"name":"Luke Goss","avatar":""},{"name":"Michael Jai White","avatar":""},{"name":"Koichi Iwaki","avatar":""},{"name":"Lisa S.","avatar":""},{"name":"Daming Chen","avatar":""},{"name":"Brandon Chang","avatar":""},{"name":"Hei Zi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324529);
