INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-2', 'Lời Nguyền 2', 'Ju-on: The Grudge 2', 'https://phimimg.com/uploads/movies/20260710/loi-nguyen-2-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/loi-nguyen-2-poster.webp', '<p>Khi đang lái xe, nữ diễn viên phim kinh dị đang mang thai Kyôko Harase và vị hôn phu của cô bị tai nạn xe hơi. Cô mất đứa con và hôn phu của cô rơi vào trạng thái hôn mê. Kyôko bị nguyền rủa cùng với một đoàn làm phim truyền hình khi họ quay một chương trình trong ngôi nhà ma ám, nơi Kayako bị chồng cô sát hại dã man nhiều năm trước. Trong khi từng thành viên trong đội chết hoặc biến mất, Kyôko được thông báo rằng cô có một thai nhi ba tháng rưỡi trong bụng.</p>', 'Full', 1, 'single', 'completed', 51, 2003, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Noriko Sakai","avatar":""},{"name":"Shingo Katsurayama","avatar":""},{"name":"Yui Ichikawa","avatar":""},{"name":"Emi Yamamoto","avatar":""},{"name":"Chiharu Niiyama","avatar":""},{"name":"Kei Horie","avatar":""},{"name":"Erika Kuroishi","avatar":""},{"name":"Kaoru Mizuki","avatar":""},{"name":"Ayumu Saito","avatar":""},{"name":"Shinobu Yuki","avatar":""},{"name":"Takako Fuji","avatar":""},{"name":"Yuya Ozeki","avatar":""},{"name":"Fumika Hidejima","avatar":""},{"name":"Hidetoshi Kageyama","avatar":""},{"name":"Hiroko Toda","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The grudge II - Kirous jatkuu","The Grudge 2","A harag 2.","Ju-on: Rancore 2","La maldición 2","Förbannelsen fortsätter - The Grudge II","Прокляття 2","Ju-on: The Grudge 2","Ju-on 2","ผี...ดุ 2","呪怨2"]', 1784690324529);
