INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giua-bay-lang-soi', 'Giữa Bầy Lang Sói', 'Belly of the Beast', 'https://phimimg.com/upload/vod/20260604-1/59f0050b2c44b769bdcaa10f241c48b7.jpg', 'https://phimimg.com/upload/vod/20260604-1/bdd15c55f84ca20265f2d4dd9a2ae9e0.jpg', '<p>Khu chợ tại trung tâm thành phố vương quốc Thái Lan sáng nay vẫn nhộn nhịp như mọi ngày. Các bà hàng tôm, hàng cá vẫn “tám” với nhau. Người mua, kẻ bán cứ mặc cả, tranh luận ồn ào náo nhiệt như cảnh vốn thường thấy ở các nước khu vực Đông Nam Á. Chẳng có gì thay đổi mấy. Ồ không, có đấy!! Một ông Tây béo tốt, tuổi trạc tứ tuần đang lững thững đi vào. Trên tay ông ta chỉ mang một chiếc giỏ xách đựng hành lý. Chẳng có gì đáng chú ý hơn ở người đàn ông này ngoài cái tướng khá tốt của ông ta…</p>', 'Full', 1, 'single', 'completed', 37, 2003, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Byron Mann","avatar":""},{"name":"Monica Lo Suk-Yee","avatar":""},{"name":"Tom Wu","avatar":""},{"name":"Sara Malakul Lane","avatar":""},{"name":"Elidh MacQueen","avatar":""},{"name":"Kevork Malikyan","avatar":""},{"name":"Pongpat Wachirabunjong","avatar":""},{"name":"Malin Moberg","avatar":""},{"name":"Vincent Riotta","avatar":""},{"name":"Patrick Robinson","avatar":""},{"name":"Tony Ching Siu-Tung","avatar":""},{"name":"Alastair Vardy","avatar":""},{"name":"Andy Adam","avatar":""},{"name":"Shahkrit Yamnarm","avatar":""},{"name":"Martin McDo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bestia","Bestie","Le Ventre de la bête","Inside the Beast","Las entrañas de la bestia","潜龙轰天3：野兽之腹","Belly of the Beast"]', 1784690324529);
