INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-smallville-phan-3', 'Thị Trấn Smallville (Phần 3)', 'Smallville (Season 3)', 'https://phimimg.com/upload/vod/20250604-1/7f7b5c82a066c7912c87212a99437282.jpg', 'https://phimimg.com/upload/vod/20250604-1/d9548c93d557df9eee1738a1252026ed.jpg', '<p>Ai cũng có một tương lai. Clark Kent có một định mệnh — nếu cậu sẵn sàng chấp nhận và làm chủ tất cả những sức mạnh phi thường cùng những trách nhiệm to lớn đi kèm với nó. Trong mùa ba đầy biến cố, sự tái hiện hấp dẫn về huyền thoại Superman cùng các nhân vật kinh điển tiếp tục khi Clark đối mặt với mặt tối của mình và Jonathan Kent phải thực hiện một thỏa thuận nguy hiểm với Jor-El để cứu con trai.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 19, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Welling","avatar":""},{"name":"Erica Durance","avatar":""},{"name":"Cassidy Freeman","avatar":""},{"name":"Justin Hartley","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Smallville"]', 1784690324529);
