INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-hon-loan-phan-2', 'Vùng Đất Hỗn Loạn (Phần 2)', 'Everwood (Season 2)', 'https://phimimg.com/upload/vod/20260604-1/b949d87dc79e2c5734e38b334f66959a.jpg', 'https://phimimg.com/upload/vod/20260604-1/6d8b0bc2bd1266be9a2a03deb566b170.jpg', '<p>Sau khi vợ qua đời, bác sĩ phẫu thuật nọ cùng các con từ New York chuyển đến thị trấn nhỏ Everwood để xây dựng lại cuộc sống và hàn gắn tình cảm gia đình.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 17, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Treat Williams","avatar":""},{"name":"Gregory Smith","avatar":""},{"name":"Emily VanCamp","avatar":""},{"name":"Debra Mooney","avatar":""},{"name":"John Beasley","avatar":""},{"name":"Vivien Cardone","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Stephanie Niznik","avatar":""},{"name":"Merrilyn Gann","avatar":""},{"name":"Tom Amandes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["사랑의 마을, 에버우드","Everwood"]', 1784690324529);
