INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-y-san-sang-charlie-achtung-fertig-charlie', 'Chú Ý! Sẵn Sàng! Charlie! (Achtung, Fertig, Charlie!)', 'Ready, Steady, Charlie!', 'https://phimimg.com/upload/vod/20260520-1/0acad226a8ef733ea8b770817eb56f2d.jpg', 'https://phimimg.com/upload/vod/20260520-1/eca2386a578e13eb7e811100d3209e66.jpg', '<p>Ngay tại một nhà thờ ở Thụy Sĩ, Antonio Carrera đang chuẩn bị cử hành hôn lễ với cô con gái xinh đẹp của một ông trùm Mafia Ý, thì cảnh sát quân đội bất ngờ ập vào. Họ áp giải anh đi thực hiện nghĩa vụ quân sự bắt buộc kéo dài 15 tuần của Thụy Sĩ, để lại một đám cưới dang dở và một tình huống dở khóc dở cười.</p>', 'Full', 1, 'single', 'completed', 39, 2003, 'Vietsub', 'FHD', 'Thụy Sĩ', 0, '[{"name":"Michael Koch","avatar":""},{"name":"Melanie Winiger","avatar":""},{"name":"Mia Aegerter","avatar":""},{"name":"Marco Rima","avatar":""},{"name":"Martin Rapold","avatar":""},{"name":"Mike Müller","avatar":""},{"name":"Max Rüdlinger","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ready, steady, Charlie!","Achtung, Fertig, Charlie!"]', 1784690324529);
