INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('se-co-thu-phai-thay-doi', 'Sẽ Có Thứ Phải Thay Đổi', 'Something''s Gotta Give', 'https://phimimg.com/upload/vod/20260512-1/85581b10013990346d2855f644de023f.jpg', 'https://phimimg.com/upload/vod/20260512-1/03b7fb490fe0c6317eae9040a825961e.jpg', '<p>Khi Harry Sanborn, giám đốc điều hành ngành công nghiệp âm nhạc lớn tuổi, độc thân suốt đời, và cô bạn gái mới nhất của anh, Marin, đến nhà mẹ cô ở Hamptons, họ phát hiện ra mẹ cô, nhà viết kịch Erica Barry, cũng dự định ở lại cuối tuần. Erica rất phẫn nộ trước mối quan hệ này và cách cư xử phân biệt giới tính của Harry. Nhưng khi Harry lên cơn đau tim trong thời gian ở đó, và bác sĩ kê đơn nghỉ ngơi, lựa chọn duy nhất của anh là ở lại nhà Barry. Được Erica và bác sĩ chăm sóc, một mối tình tay ba bắt đầu hình thành.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jack Nicholson","avatar":""},{"name":"Diane Keaton","avatar":""},{"name":"Keanu Reeves","avatar":""},{"name":"Frances McDormand","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Paul Michael Glaser","avatar":""},{"name":"Rachel Ticotin","avatar":""},{"name":"Patrick Fischler","avatar":""},{"name":"KaDee Strickland","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Cuando menos te lo esperas","Milovať je zábavné","Aşkta Herşey Mümkün","Tout peut arriver","Alguém Tem Que Ceder","Something''s Gotta Give"]', 1784690324529);
