INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aniki-va-toi', 'Aniki Và Tôi', 'Aniki And Me', 'https://phimimg.com/upload/vod/20260511-1/09bcbb5efec72737a1bf6768ac214b84.jpg', 'https://phimimg.com/upload/vod/20260511-1/a8b87cf63710eddb3147f84c397d0f3c.jpg', '<p>Noboru và Takashi gặp nhau trong tù. Bàng hoàng trước sự phản bội của người yêu, Akira trở nên nghiện săn đàn ông ở Hattenba và cuối cùng bị bỏ tù vì tội buôn bán ma túy. Noboru, người từng là vật thỏa mãn dục vọng của các tù nhân trong tù, được Takashi, một thành viên của băng đảng Ogasawara thuộc tổ chức hiệp sĩ, giúp đỡ. Takashi thuyết phục Noboru chăm sóc bản thân, và nhờ những nỗ lực của mình, Noboru đã có thể cải tạo bản thân và kính trọng Takashi như một người anh trai. Một ngày nọ, anh trai của Takashi, Kanzaki, đến thăm và thông báo rằng anh ta đã bị khai trừ khỏi nhóm...</p>', 'Full', 1, 'single', 'completed', 17, 2003, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryo Kuraki","avatar":""},{"name":"石川ゆうや","avatar":""},{"name":"なかみつせいじ","avatar":""},{"name":"飯島大介","avatar":""},{"name":"哀上男","avatar":""},{"name":"久須美欽一","avatar":""},{"name":"Kôji Makimura","avatar":""},{"name":"中村公彦","avatar":""},{"name":"横須賀正一","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["兄貴と俺"]', 1784690324529);
