INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiec-quai-thu-duoi-anh-trang', 'Tiệc Quái Thú Dưới ánh Trăng', 'Beasts Under The Moon', 'https://phimimg.com/upload/vod/20260511-1/4cd2288d1c485184e92f137b788c66b8.jpg', 'https://phimimg.com/upload/vod/20260511-1/b47bf6f95f62c532d5a784997843b651.jpg', '<p>Hide, một nhiếp ảnh gia chuyên chụp ảnh khỏa thân nam, quyết định kết hôn với Taku. Hai người thề nguyện sống bên nhau trọn đời. Tuy nhiên, khi người yêu cũ của Hide, Hisashi, đến dự đám cưới, một bầu không khí khó chịu bắt đầu bao trùm giữa hai người...</p>', 'Full', 1, 'single', 'completed', 14, 2003, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Wataru Narita","avatar":""},{"name":"Yoshiaki Suzuki","avatar":""},{"name":"柳東士","avatar":""},{"name":"平川直大","avatar":""},{"name":"Rintaro Taira","avatar":""},{"name":"吉岡睦雄","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Gekka no kemono utage","月下の獣宴"]', 1784690324529);
