INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-nhin-cua-mot-chang-trai-xinh-dep', 'Ánh Nhìn Của Một Chàng Trai Xinh đẹp', 'The Gaze Of A Beautiful Boy', 'https://phimimg.com/upload/vod/20260511-1/361ebc7adb2c8403c37b45a9e55d945c.jpg', 'https://phimimg.com/upload/vod/20260511-1/20aff05a551ab288b2e78dd4acba9429.jpg', '<p>Fumiya, một chàng trai xinh đẹp không có chỗ ở cố định, bán thân cho những người đàn ông lạ mặt trong công viên. Một ngày nọ, cậu gặp rắc rối nhưng được một giáo sư đại học trung niên cứu giúp, người đã giúp cậu bắt đầu một cuộc sống mới. Tuy nhiên, khi phát hiện ra vị giáo sư có vết sẹo giống hệt Fumiya trên trán, cậu đã biết được một sự thật gây sốc... Sau khi tìm hiểu về cuộc sống của những người đàn ông sống vì tình yêu xuyên suốt thời gian, Fumiya tự hào bước ra dưới ánh nắng xuyên qua những tán cây.</p>', 'Full', 1, 'single', 'completed', 18, 2003, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"永井努","avatar":""},{"name":"久保新二","avatar":""},{"name":"本多菊次朗","avatar":""},{"name":"Masaaki Kokubo","avatar":""},{"name":"横須賀正一","avatar":""},{"name":"なかみつせいじ","avatar":""},{"name":"Tomomi Aizawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Bishonen no manazashi","美少年のまなざし"]', 1784690324529);
