INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-tich-thoi-nay', 'Cổ tích thời nay', 'Uptown Girls', 'https://phimimg.com/upload/vod/20260502-1/51c06b605dbea8eb9bbf2839dadfafe0.jpg', 'https://phimimg.com/upload/vod/20260502-1/c74c595673ee67b31740d2facf9363c9.jpg', '<p>Molly Gun là một cô gái sống vô tư vô lo nhờ vào khối tài sản được người cha là cố siêu sao nhạc rock để lại. Nhưng một ngày, tên quản lý đã cuỗm số tiền đó và cao chạy xa bay, để lại cô công chúa này phải ra đời tập bươn chải để nuôi sống bản thân. Cô được thuê làm bảo mẫu cho cô tiểu như Ray già dặn, kỹ tính, và có phần hoài nghi về thế giới dù chỉ mới 8 tuổi. Cùng nhau, cả hai dạy cho người còn lại cách sống đúng với độ tuổi của chính mình - Molly học cách sống có trách nhiệm hơn còn Ray tìm cách trở về làm một đứa trẻ thực thụ.</p>', 'Full', 1, 'single', 'completed', 19, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brittany Murphy","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Marley Shelton","avatar":""},{"name":"Donald Faison","avatar":""},{"name":"Jesse Spencer","avatar":""},{"name":"Austin Pendleton","avatar":""},{"name":"Heather Locklear","avatar":""},{"name":"Will Toale","avatar":""},{"name":"Marceline Hugot","avatar":""},{"name":"Pell James","avatar":""},{"name":"Quddus","avatar":""},{"name":"Russell Steinberg","avatar":""},{"name":"Fisher Stevens","avatar":""},{"name":"Susanna Frazer","avatar":""},{"name":"Wynter Kullman","avatar":""},{"name":"Amy Korb","avatar":""},{"name":"Geraldine Bart","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Pequeñas grandes amigas","Pequeñas Grandes Amigas","Niñera a la fuerza","Holky z lepší společnosti","Petites Princesses","Uptown Girls - Meninas Bem","Uptown Girls"]', 1784690324529);
