INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ba-mong-du', 'Người Đàn Bà Mộng Du', 'The Sleepwalking Woman', 'https://phimimg.com/upload/vod/20250403-1/a4943589746bbf183bd53933de0baf4e.jpg', 'https://phimimg.com/upload/vod/20250403-1/0901573a2cc4f5b99760f267aba722a3.jpg', '<p>Bộ phim đan xen giữa quá khứ và hiện tại. Trong chiến tranh, Quỳ là một nữ quân y trên chiến trường Trường Sơn, cô yêu Hòa -một đội trưởng- nhưng Hòa lại hy sinh trong chiến trận. Hòa bình lập lại, Quỳ có cuộc tình mới với Phiên -bạn của Hòa- dù được yêu thương hết mực nhưng Quỳ không thể quên được quá khứ cũng như không thể hòa mình vào cuộc sống mới.</p>', 'Full', 1, 'single', 'completed', 22, 2003, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hồng Ánh","avatar":""},{"name":"Võ Hoài Nam","avatar":""},{"name":"Lê Vũ Long","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jin dan Jun","ប្រាថ្នា៣ខ","Jin & Jun"]', 1784690324529);
