INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-nhanh-qua-nguy-hiem-2', 'Quá Nhanh Quá Nguy Hiểm 2', '2 Fast 2 Furious', 'https://phimimg.com/upload/vod/20260225-1/6eecdcafc1445db1df3a8fcd2ffd44e2.jpg', 'https://phimimg.com/upload/vod/20260225-1/1460be9dbde45f0d76401dd878be3f76.jpg', '<p>Brian O&quot;Conner là một cảnh sát giỏi bị mất chức chỉ vì bọn tội phạm đã sử dụng những thủ đoạn quá tinh vi. Và nay anh có cơ hội chuộc lại lỗi lẫm với cuộc thử thách lần hai. Để thực hiện nhiệm vụ của mình, Brian O&quot;Conner phải gia nhập hội đua xe trái phép trên các đường phố Miami để tìm kiếm tung tích Carter Verone, một tên tội phạm chuyên buôn ma tuý và rửa tiền. Anh và cậu bạn thân Roman Pearce được giao nhiệm vụ chuyển số tiền phi pháp cho Carter Verone hiện đang núp dưới danh nghĩa một thương gia xuất nhập khẩu ở Miami. Ngoài Roman Pearce, Brian O&quot;Conner còn nhận được sự giúp đỡ của nữ mật vụ tài năng và hấp dẫn, Monica Clemente, trong vai người yêu bất đắc dĩ của Carter Verone. Và cuộc phiêu lưu cùng những pha rượt đuổi bắt đầu...</p>', 'Full', 1, 'single', 'completed', 21, 2003, 'Vietsub + Thuyết Minh', 'FHD', 'Đức', 0, '[{"name":"Paul Walker","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Eva Mendes","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Ludacris","avatar":""},{"name":"James Remar","avatar":""},{"name":"Thom Barry","avatar":""},{"name":"Michael Ealy","avatar":""},{"name":"Mark Boone Junior","avatar":""},{"name":"Devon Aoki","avatar":""},{"name":"Roberto ''Sanz'' Sanchez","avatar":""},{"name":"Mo Gallini","avatar":""},{"name":"Edward Finlay","avatar":""},{"name":"Jin Au-Yeung","avatar":""},{"name":"Amaury Nolasco","avatar":""},{"name":"Eric Etebari","avatar":""},{"name":"John Cenatiempo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Halálosabb iramban","Wild Speed X2","+rápido +furioso","Bŭrzi i yarostni 2","Oi Machités ton Drómon 2","Dvoynoy forsazh","Prebrzi i prežestoki","Podviynyy forsazh","速度与激情2：飙风再起","เร็ว...แรงทะลุนรก: เร็วคูณ 2 ดับเบิ้ลแรงท้านรก","Mais Velozes Mais Furiosos","玩命關頭2：飆風再起","F&F2 - 2 Fast 2 Furious","Za Szybcy, za Wściekli","Fast & Furious 2 - 2 Fast 2 Furious","狂野時速2","Hızlı ve Öfkeli 2","Quá Nhanh Quá Nguy Hiểm 2","2 Fast 2 Furious: A todo gas 2","Más rápido, más furioso","Паклене улице 2","Fast & Furious 2","Fast And Furious 2 - 2 Fast 2 Furious","Forsaj 2","ワイルド・スピードX2：2003","2 מהיר 2 עצבני","Velozes e Furiosos","+Rápido +Furioso","The Fast and the Furious II: 2 Fast 2 Furious","A todo gas 2","분노의 질주 2","+ Rápido + furioso","2 Fast 2 Furious"]', 1784690324529);
