INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('qua-nhanh-qua-nguy-hiem-2', 'Quá Nhanh Quá Nguy Hiểm 2', '2 Fast 2 Furious', 'quá nhanh quá nguy hiểm 2 2 fast 2 furious paul walker tyrese gibson eva mendes cole hauser ludacris james remar thom barry michael ealy mark boone junior devon aoki roberto ''sanz'' sanchez mo gallini edward finlay jin au-yeung amaury nolasco eric etebari john cenatiempo halálosabb iramban wild speed x2 +rápido +furioso bŭrzi i yarostni 2 oi machités ton drómon 2 dvoynoy forsazh prebrzi i prežestoki podviynyy forsazh 速度与激情2：飙风再起 เร็ว...แรงทะลุนรก: เร็วคูณ 2 ดับเบิ้ลแรงท้านรก mais velozes mais furiosos 玩命關頭2：飆風再起 f&f2 - 2 fast 2 furious za szybcy, za wściekli fast & furious 2 - 2 fast 2 furious 狂野時速2 hızlı ve öfkeli 2 quá nhanh quá nguy hiểm 2 2 fast 2 furious: a todo gas 2 más rápido, más furioso паклене улице 2 fast & furious 2 fast and furious 2 - 2 fast 2 furious forsaj 2 ワイルド・スピードx2：2003 2 מהיר 2 עצבני velozes e furiosos +rápido +furioso the fast and the furious ii: 2 fast 2 furious a todo gas 2 분노의 질주 2 + rápido + furioso 2 fast 2 furious', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-chau-cach-cach-phan-3', 'Hoàn Châu Cách Cách (Phần 3)', 'My Fair Princess (Season 3)', 'https://phimimg.com/upload/vod/20260224-1/7fd1add057b8f95f87f13261c458a9df.jpg', 'https://phimimg.com/upload/vod/20260224-1/b346e936023f9229470ba7d3417d1f03.jpg', '<p>Chuyển thể từ tiểu thuyết cùng tên của nữ tác giả Quỳnh Dao. Cả bộ phim có 3 phần, sản xuất trong khoảng các năm 1997, 1998 và 2003. Hầu hết các cảnh trong phim đều được thực hiện ở thủ đô Bắc Kinh và tỉnh Hà Bắc của Trung Quốc Đại lục.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 24, 2003, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Huỳnh Dịch","avatar":""},{"name":"Cổ Cự Cơ","avatar":""},{"name":"Mã Y Lợi","avatar":""},{"name":"Châu Kiệt","avatar":""},{"name":"Tần Lam","avatar":""},{"name":"Vương Diễm","avatar":""},{"name":"Địch Long","avatar":""},{"name":"Tưởng Cần Cần","avatar":""},{"name":"Lưu Đào","avatar":""},{"name":"Tàng Kim Sinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["还珠格格","還珠格格","Putri Huan Zhu","還珠姫 〜プリンセスのつくりかた〜　(Kanju Hime ~Purinsesu no Tsukuri Kata~)","ព្រះនាងយេយេ (Preah Neang Ye Ye)","황제의 딸 (Hwangje-ui Ttal; \"Emperor''s Daughter\")","Хуанжу Гэг (Khuanju Geg)","還珠格格 (Waan Jyu Ge Ge )","My Fair Princess","还珠格格 (Huan Zhu Ge Ge)","องค์หญิงกำมะลอ (Xngkh̒ h̄ỵing kảmalx)","還珠格格 (Huan Zhu Ge Ge)","Huanzhu Gege","Princess Pearl","Princess Returning Pearl","Return 