INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-dung-tu-than', 'Trạm Dừng Tử Thần', 'Cabin Fever', 'https://phimimg.com/upload/vod/20260210-1/a7fc88262588a189e4812e169f93ae63.jpg', 'https://phimimg.com/upload/vod/20260210-1/9a1483dfd54dcc587a66106ffefc2c14.jpg', '<p>Một nhóm năm sinh viên tốt nghiệp đại học thuê một căn nhà gỗ trong rừng và bắt đầu trở thành nạn nhân của một loại virus ăn thịt người kinh hoàng, điều này thu hút sự chú ý không mong muốn của những người dân địa phương khát máu.</p>', 'Full', 1, 'single', 'completed', 16, 2003, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rider Strong","avatar":""},{"name":"Jordan Ladd","avatar":""},{"name":"Cerina Vincent","avatar":""},{"name":"Giuseppe Andrews","avatar":""},{"name":"James DeBello","avatar":""},{"name":"Eli Roth","avatar":""},{"name":"Julie Childress","avatar":""},{"name":"Jessica Elder","avatar":""},{"name":"Darcy Martin","avatar":""},{"name":"Heather Simmons","avatar":""},{"name":"Joey Kern","avatar":""},{"name":"Richard Fullerton","avatar":""},{"name":"Arie Verveen","avatar":""},{"name":"Robert Harris","avatar":""},{"name":"Tim Parati","avatar":""},{"name":"Matthew Helms","avatar":""},{"name":"Hal Courtney","avatar":""},{"name":"Jay Aa","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["To katafygio tou tromou","Cabin fever - fièvre noire","Fièvre noire","Fiebre en la cabaña","La cabaña sangrienta","Kyabin fiba","Cabin Fever - UR","Khizha na smŭrtta","Likhoradka","Cabin Fever Director''s Cut","Cabin Fever"]', 1784690324529);
