INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-trat-su-muoi-2', 'Tân Trát Sư Muội 2', 'Love Undercover 2: Love Mission', 'https://phimimg.com/upload/vod/20251214-1/5e782a661f38ea173b4145cadd0fddf2.jpg', 'https://phimimg.com/upload/vod/20251214-1/4777d7a4f3d618112de7945eefd941c2.jpg', '<p>Nữ cảnh sát dũng cảm và vô địch Phương Lệ Quyên cùng với chàng trai trẻ tài năng Âu Hải Văn có cuộc sống ngọt ngào, khiến ai cũng phải ngưỡng mộ. Lệ Quyên được thăng cấp nhanh chóng, trở thành huyền thoại của cảnh sát.Đội của Lệ Quyên và Sếp Chung nhận nhiệm vụ mới: bảo vệ và tiếp đón Công chúa Tasah (người Hoa kiều đến từ Cộng hòa Potosi).Lệ Quyên đã sắp xếp lịch trình và biến biệt thự sang trọng của Hải Văn thành nơi ở cho Công chúa, điều này khiến Hải Văn bất mãn, và hai người xảy ra cãi vã lần đầu tiên.Tuy nhiên, việc bảo vệ Công chúa chỉ là khúc dạo đầu. Một cuộc phiêu lưu lớn thực sự đang chờ đợi Phương Lệ Quyên ở phía sau, và thử thách chỉ mới bắt đầu.</p>', 'Full', 1, 'single', 'completed', 28, 2003, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Dương Thiên Hoa","avatar":""},{"name":"Ngô Ngạn Tổ","avatar":""},{"name":"Đỗ Văn Trạch","avatar":""},{"name":"Mã Đức Chung","avatar":""},{"name":"Đường Thi Vịnh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["San chat bye mooi 2","新扎师妹2","新紮師妹2美麗任務"]', 1784690324529);
