INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khat-vong-tuoi-tre', 'Khát Vọng Tuổi Trẻ', 'Aqua Heroes', 'https://phimimg.com/upload/vod/20251010-1/71c691432af64c93d498dad655da5435.jpg', 'https://phimimg.com/upload/vod/20251010-1/3f68c2c273d36e5ab4b691dfaa85386f.jpg', '<p>Những Mùa Hè Không Quên: Cuộc Chiến Giữa Những Thiên Thần và ⁣Quỷ Dữ

Vào những ngày hè đầy nắng, một ⁤nhóm thanh ⁣niên năng động đang tập luyện bên bờ hồ bơi. Họ‍ hăng hái chuẩn bị cho buổi lễ dạ hội bơi⁢ lội⁤ sắp diễn ra. Trước khi xây dựng được một đội ngũ vững mạnh,họ đã phải đối mặt ⁤với nhiều thử thách: một số đã rời bỏ dự án,trong khi những người khác thậm chí còn nghi ngờ về việc⁣ tiếp tục theo đuổi bộ môn này. Đội “Thiên thần” đã trải qua không ít đau thương trước khi thực sự trở thành một tập thể thống nhất.

Gia Đình Phân Rã‍ và Cuộc chiến Tình Yêu

Người sáng lập đội bóng là TAK, có ⁣hai cô con gái rất khác nhau. Con gái lớn của ông là HAN (CHAN MAN WOON, BO BO), người hay xảy ra mâu thuẫn⁣ với em gái mình, WING (TONG LEILA).‍ WING từng sống xa gia đình trong nhiều năm và⁤ thường gặp khó khăn trong việc chấp nhận tổ ấm mới của‍ mình. Cô luôn cảm thấy ‍ghen tị với HAN vì tình cảm mà cả hai đều dành cho đội trưởng LOK⁣ (SIU EDWIN).

Câu ‍Chuyện⁣ Buồn Của WING...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2003, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Bobo Chan Man-Yuen","avatar":""},{"name":"Wilson Ai Wai","avatar":""},{"name":"Sheren Tang Shui-Man","avatar":""},{"name":"Leila Tong","avatar":""},{"name":"Stephy Tang Lai-Yan","avatar":""},{"name":"Theresa Fu Wing","avatar":""},{"name":"Iva Law Wing-Han","avatar":""},{"name":"Bosco Wong Chung-Chak","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["恋爱自由式","戀愛自由式","Aqua Heroes"]', 1784690324529);
