INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-gian-dao-3', 'Vô Gian Đạo 3', 'Infernal Affairs 3', 'https://phimimg.com/upload/vod/20250920-1/9f8aa278757278b8fa119df56c179278.jpg', 'https://phimimg.com/upload/vod/20250920-1/46003d04e57244beb9d1bd91191c9b1a.jpg', '<p>Trong phim Vô Gian Đạo phần 3, bác sĩ Lý từng chữa trị tâm lý cho Trần Vĩnh Nhân (khi anh này còn sống và còn là cảnh sát chìm được cài vào băng đảng ông trùm Sâm) nay lại gặp Lưu Kiến Minh - kẻ đã giết Nhân để bịt đầu mối và sẵn sàng thủ tiêu bất cứ ai có thể phát hiện ra y là nội gián trong sở cảnh sát. Minh nay phải đối đầu với cuộc điều tra &quot;quyết tìm ra sự thật&quot; của cảnh sát Dương Cẩm Vinh và Thẩm Trừng vốn cũng là cảnh sát chìm lâu năm... Phim Vô Gian Đạo 3 thỏa mãn người xem khi có rất nhiều ngôi sao điện ảnh Hong Kong trong cùng một bộ phim. Và rõ ràng sự khác biệt về vai vế, phong cách giữa các thế hệ diễn viên đã tạo ra một sự phong phú đầy cuốn hút.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Leon Lai","avatar":""},{"name":"Chen Daoming","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Eric Tsang Chi-Wai","avatar":""},{"name":"Kelly Chen","avatar":""},{"name":"Sammi Cheng","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Edison Chen","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Eddie Li Yu-Yeung","avatar":""},{"name":"Chapman To Man-Chat","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Gordon Lam Ka-Tung","avatar":""},{"name":"Berg Ng Ting-Yi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b618