INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-gian-dao-2', 'Vô Gian Đạo 2', 'Infernal Affairs 2', 'https://phimimg.com/upload/vod/20250920-1/b4fe087ad034df07067caf56dcbb2e61.jpg', 'https://phimimg.com/upload/vod/20250920-1/c324d471c0fa0083a5f247538b0cbefe.jpg', '<p>Vô Gian Đạo phần 2 lại đưa người xem ngược về thời điểm trước phần đầu. Nghê Khôn, trùm xã hội đen bị sát hại. Nghê Vĩnh Hiếu, đứa con trai, lên kế vị và phát hiện ra viên cảnh sát trẻ Trần Vĩnh Nhân là con trai riêng của cha mình. Vĩnh Nhân bị đuổi khỏi sở cảnh sát. Đội trưởng Huỳnh nhận Nhân làm tay trong để điều tra về gia đình của Vĩnh Hiếu. Nhưng Vĩnh Hiếu rất cao tay, đã tìm ra được bằng chứng cho thấy chính Huỳnh cấu kết với Mary, vợ của Hán Thẩm, đã sai người giết cha hắn. Nghê Vĩnh Hiếu cho đàn em báo thù... &nbsp;Phim Vô Gian Đạo 2 xoay quanh cuộc chiến giữa các băng đảng. Hai đạo diễn xuất sắc Lưu Vĩ Cường (Andrew Lau) và Mạch Triệu Huy (Alan Mak) tiếp tục hợp tác ăn ý trong tác phẩm này, góp phần giúp bộ phim đạt doanh thu kỉ lục năm 2003.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shawn Yue","avatar":""},{"name":"Edison Chen","avatar":""},{"name":"Francis Ng Chun-Yu","avatar":""},{"name":"Eric Tsang Chi-Wai","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Hu Jun","avatar":""},{"name":"Andrew Lin Hoi","avatar":""},{"name":"Roy Cheung Yiu-Yeung","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Joe Cheung Tung-Cho","avatar":""},{"name":"Chapman To Man-Chat","avatar":""},{"name":"Kelly Fu","avatar":""},{"name":"Henry Fong Ping","avatar":""},{"name":"Peter Ngor Chi-Kwan","avatar":""},{"name":"Teddy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be1