INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-gian-dao-2', 'Vô Gian Đạo 2', 'Infernal Affairs 2', 'vô gian đạo 2 infernal affairs 2 shawn yue edison chen francis ng chun-yu eric tsang chi-wai carina lau anthony wong chau-sang hu jun andrew lin hoi roy cheung yiu-yeung liu kai-chi joe cheung tung-cho chapman to man-chat kelly fu henry fong ping peter ngor chi-kwan teddy mou gaan dou 2 mou gaan dou ii infernal affairs ii - abstieg in die achte hölle 无间道正序版 無間道 2 infernal affairs 2 infernal affairs ii infiltrados 2 juego sucio 2 インファナル・アフェアii 無間序曲：2003 无间道ii infernal affairs 2 hk 無間道ii 无间道2 امور دوزخی ۲ اعمال شیطانی ۲ infernal affairs ⅱ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-thuat-phan-6', 'Phép Thuật (Phần 6)', 'Charmed (Season 6)', 'https://phimimg.com/upload/vod/20250915-1/b3f9067af8d3315c07ec4e0934dfd670.jpg', 'https://phimimg.com/upload/vod/20250915-1/ac6b384fd33ebf3cd611f7cd2a13ff10.jpg', '<p>Charmed (Phép Thuật) là bộ phim dài tập của Mỹ gồm 8 phần kể về những chị em gái nhà Halliwell. Họ là những phù thuỷ tốt có phép thuật. Mỗi chị em gái sở hũu một phép thuật khác nhau với những quyền năng và sức mạnh khác nhau. Và phép thuật của họ mạnh mẽ hơn cả khi họ kết hợp với nhau, tạo thành “Bộ ba phép thuật” quyền năng và mạnh mẽ. Họ với phép thuật của mình chống lại những thế lực hắc ám, chiến đấu, chống lại lũ quỷ và bè lũ thợ săn phù thủy. Với “Cuốn sách của bóng tối” làm bạn, làm “người dẫn đường”, họ đã từng bước trưởng thành trong cuộc sống. Sức mạnh của họ ngày càng phát triển, và chính vì thế, những mối nguy hiểm đối với họ ngày càng gia tăng. Họ - những chị em gái nhà Halliwell – luôn kiên cường, mạnh mẽ chống lại cái ác, bảo vệ người vô tội. Mỗi tập phim kể về một câu chuyện nhỏ trong cuộc sống của ba chị em, xen vào đó là những yếu tố hài hước và chân thực trong cuộc sống thường ngày.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 11, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Holly Marie Combs","avatar":""},{"name":"Alyssa Milano","avatar":""},{"name":"Rose McGowan","avatar":""},{"name":"Brian Krause","avatar":""},{"name":"Kaley Cuoco","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fc