INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-tuu-quyen', 'Hầu Tửu Quyền', 'Drunken Monkey', 'https://phimimg.com/upload/vod/20250825-1/625c424732e65549a678274944b0d97b.jpg', 'https://phimimg.com/upload/vod/20250825-1/3a06f66b2f2b454f54b02aee20adc944.jpg', '<p>Ca Thủ là công tử của thương gia họ Trần chốn kinh thành. Y không ham chữ nghĩa, chỉ yêu thích hội họa, đặc biệt là khát khao xuất bản cuốn sách vẽ thế võ hầu quyền lưu danh trong thiên hạ. Tuấn là một thanh niên có thân thể dẻo dai, cường tráng, đam mê luyện võ. Tuấn là người hầu và cũng là ông cậu Ca Thủ bởi một mối quan hệ rất đỗi lằng nhằng trong gia tộc. Nhân một lần cả hai bị trục xuất khỏi trường học bởi một trò quậy phá, Tuấn và Ca Thủ quyết tâm lên đường tìm kiếm người anh hùng Mã Bình. Vị trưởng môn Chung Vũ Tiêu Cục này từng nổi danh trong chốn giang hồ với ngón võ hầu quyền độc nhất. Nhưng một người mai danh ẩn tính thật không dễ gì tìm kiếm, cho đến khi họ may mắn gặp được Mẫn, một cô gái xinh đẹp, cá tính và được trang bị những ngón võ hầu quyền điêu luyện.</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Wu Jing","avatar":""},{"name":"Sammy Lau","avatar":""},{"name":"Shannon Yao","avatar":""},{"name":"Gordon Liu Chia-Hui","avatar":""},{"name":"Li Haitao","avatar":""},{"name":"Lau Kar-Leung","avatar":""},{"name":"Chi Kuan-Chun","avatar":""},{"name":"Chang Chen-Huan","avatar":""},{"name":"Chiu Jan-Wa","avatar":""},{"name":"Choi Jing","avatar":""},{"name":"Chow Hing-Hak","avatar":""},{"name":"Liu Xueshen","avatar":""},{"name":"Ma Wen-Qiang","avatar":""},{"name":"Ng Kwok-Ping","avatar":""},{"name":"Shi Zhang-Jin","avatar":""},{"name":"Si Gin-Wa","avatar":""},{"name":"Tung Wing-Hing","avatar":""},{"name":"Yao Weixing","avatar":""},{"name":"Yiu Kin-","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Chui Ma Lau","醉马骝","Zui hou","Zui ma liu","Zhui ma lao","Atsalinoi mahites","醉猴","醉馬騮"]', 1784690324529);
