INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-duc-vo-hinh', 'Quỷ Dục Vô Hình', 'The Stealth Sex Fiend', 'https://phimimg.com/upload/vod/20250817-1/1f99c52b0360de9da4946076d3d1a55d.jpg', 'https://phimimg.com/upload/vod/20250817-1/8cde3610364e9b32d8f3fa6d788c07dc.jpg', '<p>Nam chính Cường Tử vô tình ăn phải thuốc kích dục đã hết hạn, nên biến thành người vô hình! Hắn ta lại lợi dụng “ưu thế” vô hình này để đi rình mò chuyện dâm ô. Sau đó, để giải cứu người vợ ngực lớn bị bọn cho vay nặng lãi giam giữ, Cường Tử gây ra hàng loạt tình huống dở khóc dở cười. Câu chuyện liên tục xuất hiện những diễn biến bất ngờ… Trong lúc người vô hình Cường Tử đang vội vã đi cứu vợ, thì chính người vợ ấy, trong khi bị giam giữ, lại bất ngờ nảy sinh một mối tình lệch lạc với kẻ cho vay nặng lãi, khiến câu chuyện càng thêm phức tạp.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Lee Long-Ming","avatar":""},{"name":"Wong Ching","avatar":""},{"name":"Bo Chi","avatar":""},{"name":"Tat Wah Choi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yînxíng yínmó: Yông qín guì lì shuâng chái","Yin Xing Yin Mo","The Stealth Sex Fiend","隱形淫魔之勇擒貴利雙柴","Invisible Erotomania"]', 1784690324529);
