INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xmen-2-lien-minh-di-nhan', 'X-Men 2: Liên Minh Dị Nhân', 'X2', 'https://phimimg.com/upload/vod/20250817-1/edcb9fef341ffcff366ff5fc030f3940.jpg', 'https://phimimg.com/upload/vod/20250817-1/84d775dcda2b44f1b9660c71fcdb21df.jpg', '<p>Một cuộc chiến mới lại bắt đầu với những người đột biến gien di truyền, cả tốt lẫn xấu khi tổng thống Mỹ bị ám sát tại Nhà Trắng. Magneto trốn thoát. Nhưng giờ, họ phải cùng hợp sức để chống lại một người: tướng William Stryker - người chủ trương tiêu diệt hết những người đột biến trên thế giới và Yuriko - một người đột biến luôn đối đầu với Wolverine...</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patrick Stewart","avatar":""},{"name":"Hugh Jackman","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Ian McKellen","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Rebecca Romijn","avatar":""},{"name":"Aaron Stanford","avatar":""},{"name":"Shawn Ashmore","avatar":""},{"name":"Anna Paquin","avatar":""},{"name":"Kelly Hu","avatar":""},{"name":"Michael Reid MacKay","avatar":""},{"name":"Bruce Davison","avatar":""},{"name":"Katie Stuart","avatar":""},{"name":"Ty Olsson","avatar":""},{"name":"Daniel Cudm","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]'