INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-thien-than-nuoc-my', 'Những Thiên Thần Nước Mỹ', 'Angels In America', 'https://phimimg.com/upload/vod/20250817-1/a65c9f432ec19947db4512bb150bb179.jpg', 'https://phimimg.com/upload/vod/20250817-1/86369c55c9d69c3e1192815f4baae463.jpg', '<p>Một bộ phim do HBO sản xuất lấy bối cảnh nước Mỹ vào thời điểm xảy ra nhiều biến động xã hội, trong đó nổi bật là đại dịch AIDS. Bộ phim chứa đựng nhiều hình ảnh ẩn dụ và các chiêm nghiệm sâu sắc về cuộc sống.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 10, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Al Pacino","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Mary-Louise Parker","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Justin Kirk","avatar":""},{"name":"Ben Shenkman","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Brian Markinson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Angels in America","Anjos na América","美国天使","Ingeri in America"]', 1784690324529);
