INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-day-phan-2', 'Đường Dây (Phần 2)', 'The Wire (Season 2)', 'https://phimimg.com/upload/vod/20250816-1/80587d1f1a8a1327837c17634dc8a54d.jpg', 'https://phimimg.com/upload/vod/20250816-1/521f590a2dd68faa9259bd2495327a80.jpg', '<p>Tác phẩm này đã được tạp chí điện ảnh lớn nhất thế giới Empire đưa vào danh sách bình chọn Top 50 phim truyền hình hay nhất mọi thời đại và từng là TV series ăn khách nhất của đài HBO. Mỗi mùa phim lại tập trung vào một khía cạnh trong thành phố Baltimore như buôn bán ma túy bất hợp pháp, hệ thống cảng biển, thành phố, bộ máy quan liêu, hệ thống trường học và các phương tiện truyền thông đại chúng.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 13, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dominic West","avatar":""},{"name":"Lance Reddick","avatar":""},{"name":"Sonja Sohn","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"Michael Kenneth Williams","avatar":""},{"name":"Deirdre Lovejoy","avatar":""},{"name":"J.D. Williams","avatar":""},{"name":"John Doman","avatar":""},{"name":"Jamie Hector","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Seth Gilliam","avatar":""},{"name":"Domenick Lombardozzi","avatar":""},{"name":"Corey Parker Robinson","avatar":""},{"name":"Isiah Whitlock","avatar":""},{"name":"Jr.","avatar":""},{"name":"Michael Kostroff","avatar":""},{"name":"Re","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["火线重案组","The Wire","وایر"]', 1784690324529);
