INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-long-bat-bo', 'Thiên Long Bát Bộ', 'Demi-Gods And Semi-Devils', 'https://phimimg.com/upload/vod/20250810-1/6ad642d2d67c8f354b83cfdb7a6c5aa5.jpg', 'https://phimimg.com/upload/vod/20250810-1/93928938c9562ad962c7109f732c9709.jpg', '<p>Câu chuyện xoay quanh mối quan hệ phức tạp giữa nhiều nhân vật đến từ nhiều nước

và môn phái khác nhau: Tiêu Phong, Đoàn Dự, Hư Trúc. Với tác phẩm này, Kim Dung muốn nói đến mối quan hệ nhân - quả giữa chính bản thân các nhân vật với gia đình, xã hội, dân tộc, đất nước. Chuyện xảy ra vào thời Bắc Tống và cũng bao gồm các nước Đại Lý, Khiết Đan, Thổ Phồn và Tây Hạ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 29, 2003, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Quân","avatar":""},{"name":"Lâm Chí Dĩnh","avatar":""},{"name":"Cao Hổ","avatar":""},{"name":"Lưu Diệc Phi","avatar":""},{"name":"Trần Hảo","avatar":""},{"name":"Lưu Đào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["天龙八部 (2003)","천룡팔부","Tian Long Ba Bu","Heaven Dragon the Eighth Episode","Demi Gods & Semi Devils (2003)","The demi gods and semi devils","Thiên Long Bát Bộ","天龙八部"]', 1784690324529);
