INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-huy-diet-3-nguoi-may-noi-loan', 'Kẻ Hủy Diệt 3: Người Máy Nổi Loạn', 'Terminator 3: Rise Of The Machines', 'https://phimimg.com/upload/vod/20250806-1/c26d4187c0a0e0d30ccd3a5368a1589a.jpg', 'https://phimimg.com/upload/vod/20250806-1/c3ff101d4168918e1f36ff2589ee38a2.jpg', '<p>Đã một thập kỷ kể từ khi John Connor - Nick Stahl - cứu nhân loại khỏi sự hủy diệt. Hôm nay John 25 tuổi và sống ẩn mình: không có bằng chứng tài liệu nào về sự tồn tại của anh ta. Vì vậy, anh tránh bị Skynet - tập đoàn máy tinh vi từng cố gắng kết liễu cuộc đời mình. Nhưng bây giờ, từ tương lai, anh ta đã được gửi T-X (Kristanna Loken), cỗ máy giết người cyborg phát triển nhất của Skynet. Nhiệm vụ của nó là hoàn thành công việc mà người tiền nhiệm của nó, T-1000, không thể hoàn thành. T-X là một cỗ máy tàn nhẫn vì nó đẹp ở khía cạnh con người. Giờ đây, hy vọng sống sót duy nhất cho Connnor là Kẻ hủy diệt.</p>', 'Full', 1, 'single', 'completed', 16, 2003, 'Vietsub + Thuyết Minh', 'FHD', 'Đức', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Nick Stahl","avatar":""},{"name":"Claire Danes","avatar":""},{"name":"Kristanna Loken","avatar":""},{"name":"Earl Boen","avatar":""},{"name":"David Andrews","avatar":""},{"name":"Carolyn Hennesy","avatar":""},{"name":"Jay Acovone","avatar":""},{"name":"Mark Famiglietti","avatar":""},{"name":"Moira Sinise","avatar":""},{"name":"Chopper Bernet","avatar":""},{"name":"Christopher Lawford","avatar":""},{"name":"M.C. Gainey","avatar":""},{"name":"Susan Merson","avatar":""},{"name":"Elizabeth Morehead","avatar":""},{"name":"Billy D. Lucas","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Terminator 3: pobuna mašina","Terminator 3","York Square","T3: Rise of the Machines","T3","Terminator 3: Maskinernas uppror","Terminator 3: Buntŭt na mashinite","Exolothreftís 3: I Exégersi ton Michanón","Terminator 3: Vosstaniye mashin","Terminator 3: Povstannya mashyn","Terminator 3 - Le Soulèvement des Machines","O Exterminador do Futuro 3 A Rebeliao das Maquinas","终结者3","เทอร์มิเนเตอร์ 3 : กำเนิดใหม่เครื่องจักรสังหาร","未來戰士3：殲滅者TX","Терминатор 3. Восстание машин","终结者3：机器觉醒","未来战士3：歼灭者TX","Terminator 3: Rise of the Machines"]', 1784690324529);
