INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-phan-ung-phan-4', 'Lực Lượng Phản Ứng (Phần 4)', 'Armed Reaction (Season 4)', 'https://phimimg.com/upload/vod/20250717-1/9c4287bd9c385fbce22dcc290394bc60.jpg', 'https://phimimg.com/upload/vod/20250717-1/36a6bafd4fd81f5c41f9fbd99573b198.jpg', '<p>Từ nhỏ, Trần Tam Nguyên đã chịu sự ảnh hưởng của chú mình là Trần Tiểu Sanh, cô gia nhập đội cảnh sát làm sư tỉ cầm sung và trở thành bạn tốt của Chu Tố Nga. Sau khi ly hôn, Tố Nga quen biết Trần Tiểu Sanh, hai người từ đôi oan gia đấu khẩu dần trở thành tình nhân. Tam Nguyên vì có biểu hiện xuất sắc nên được điều chuyển qua tổ chống mại dâm, hợp tác cùng Trình Phong, trở thành một đôi “anh em” tốt, nhưng một lần tình cờ, cô phát hiện Trình Phong có tình cảm với mình. Nhưng khi hai người ở bên nhau, Tam Nguyên lại đột nhiên ngừng bước…</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 10, 2003, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Âu Dương Chấn Hoa","avatar":""},{"name":"Quan Vịnh Hà","avatar":""},{"name":"Đằng Lệ Danh","avatar":""},{"name":"Ngụy Tuấn Kiệt","avatar":""},{"name":"Chu Mễ Mễ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["陀枪师姐","陀枪师姐2021","陀枪师姐 第5季 2021","Tuo qiang shi jie","陀槍師姐","Armed Reaction"]', 1784690324529);
