INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luc-luong-phan-ung-phan-4', 'Lực Lượng Phản Ứng (Phần 4)', 'Armed Reaction (Season 4)', 'lực lượng phản ứng (phần 4) armed reaction (season 4) âu dương chấn hoa quan vịnh hà đằng lệ danh ngụy tuấn kiệt chu mễ mễ 陀枪师姐 陀枪师姐2021 陀枪师姐 第5季 2021 tuo qiang shi jie 陀槍師姐 armed reaction', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-man-bi-mat-phan-2-nhan-chung', 'Bức Màn Bí Mật (Phần 2) (Nhân Chứng)', 'Witness To A Prosecution (Season 2)', 'https://phimimg.com/upload/vod/20250717-1/a5034c030532b125c6c1ebe5341a2d4d.jpg', 'https://phimimg.com/upload/vod/20250717-1/2b7bc55b7508e1637f46d100a88309b4.jpg', '<p>Phim là câu chuyện kể về hai chàng trai tên Tống Từ và Đường Tư bị kết án oan. Sau khi tranh luận với trưởng thôn về đất đai của gia đình, Chee, cùng với một phụ nữ vô gia cư tên trộm Tong Sze (Jessica Hsuan), bị cáo buộc giết trưởng và kết án tử hình. Làng mới được bổ nhiệm thẩm phán Sung Yik (Frankie Lam) tìm thấy các trường hợp nghi ngờ và điều tra. Với sự giúp đỡ của bí ẩn chưa có kinh nghiệm nhân viên điều tra Ma Kwai (Lau Kong), Yik thành công thu hồi Chee và Sze của câu. Kwai trở thành chủ nhân viên điều tra của Chee và Yik sử dụng Chee pháp y bác sĩ y tế cá nhân của mình. Cả hai trở thành bạn bè tốt, đối tác, giải quyết thành công nhiều vụ giết người trong thị trấn. Sze phát triển một lòng Yik, không biết rằng Yik và Nhiếp Phong (Mariane Chan), con gái của Nip cảnh sát cấp cao của Yan-phổi (Gordon Liu), đã có một mối quan hệ. Chee, mặt khác, rơi cho Lâm Choi nhúng (Eileen Yeow), con gái hư hỏng của thương gia giàu có Lâm (Lee Lung-kei). Choi nhúng, tuy nhiên, có đôi mắt của mình trên Yik.Vài tháng sau, một người đàn ông cũng tên của Sung Yik hiện và đối mặt với Yik, gọi anh là một kẻ phản bội. Sau khi cãi nhau dữ dội 2, Yik giả vô tình giết chết Sung thực Yik. Trong cơn hoảng loạn, anh vùi cơ thể Sung Yik trong vườn của các cửa hàng gia đình gạo Sung. Yik của người thân sau đó bí ẩn chết từng người một; Chee cuối cùng phát hiện ra cơ thể của Sung Yik thực và bắt đầu phát triển nghi ngờ Yik hiện tại, một người đàn ông mà anh ta luôn tôn trọng và đối xử như một người bạn.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 11, 2003, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Âu Dương Chấn Hoa","avatar":""},{"name":"Xa Thi Mạn","avatar":""},{"name":"Đằng Lệ Minh","avatar":""},{"name":"Âu Cẩm Đường","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["洗冤录1","Witness to a Prosecution","洗冤錄"]', 1784690324529);
