INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('buc-man-bi-mat-phan-2-nhan-chung', 'Bức Màn Bí Mật (Phần 2) (Nhân Chứng)', 'Witness To A Prosecution (Season 2)', 'bức màn bí mật (phần 2) (nhân chứng) witness to a prosecution (season 2) âu dương chấn hoa xa thi mạn đằng lệ minh âu cẩm đường 洗冤录1 witness to a prosecution 洗冤錄', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-nhung-phap-su-gio-bi-an', 'Doraemon: Nobita và Những Pháp Sư Gió Bí Ẩn', 'Doraemon: Nobita and the Windmasters', 'https://phimimg.com/upload/vod/20250521-1/c7241c40bbe8fba3ab85cf19c0ea501c.jpg', 'https://phimimg.com/upload/vod/20250521-1/b868b6bdf13baf0a6cc90aaa8d022371.jpg', '<p>Một ngày nọ, Nobita tình cờ gặp một quả cầu gió giống như một sinh vật đến từ một vùng đất xa xôi, bị thổi bay vào khu vực lân cận của họ sau cơn bão gần đây đi qua khu vực này. Nobita đặt tên cho nó là Fuuko. Cuối cùng, cậu, Doraemon và những người bạn của họ đưa nó đến một vùng nông thôn rộng lớn qua Cánh cửa bất kỳ. Tại đó, họ tìm hiểu về Làng Gió và Bão, và danh tính thực của Fuuko. Chẳng bao lâu nữa, Nobita và những người bạn của cậu phải bảo vệ Fuuko khỏi Làng Bão và Nobuo giờ đã bị chiếm hữu, người đang bị điều khiển bởi linh hồn của thủ lĩnh cũ của Làng Bão.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2003, 'Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Michiko Nomura","avatar":""},{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Kazuya Tatekabe","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["不可思議的風使者","Doraemon Nobita to fushigi kazetsukai","Doraemon: Nobita and the wind wizards","Nobita and the Windmasters","大雄與風之使者","도라에몽: 노비타와 이상한 풍사","哆啦A夢：大雄與不可思議的風使者","Nobita và Những pháp sư gió bí ẩn","doremon va phap su gio bi an","Doraemon: Anak Angin Taufan","Doraemon: Nobita dan Pesuruh Angin","映画ドラえもん のび太とふしぎ風使い"]', 1784690324529);
