INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-nhung-phap-su-gio-bi-an', 'Doraemon: Nobita và Những Pháp Sư Gió Bí Ẩn', 'Doraemon: Nobita and the Windmasters', 'doraemon: nobita và những pháp sư gió bí ẩn doraemon: nobita and the windmasters michiko nomura nobuyo oyama noriko ohara kaneta kimotsuki kazuya tatekabe 不可思議的風使者 doraemon nobita to fushigi kazetsukai doraemon: nobita and the wind wizards nobita and the windmasters 大雄與風之使者 도라에몽: 노비타와 이상한 풍사 哆啦a夢：大雄與不可思議的風使者 nobita và những pháp sư gió bí ẩn doremon va phap su gio bi an doraemon: anak angin taufan doraemon: nobita dan pesuruh angin 映画ドラえもん のび太とふしぎ風使い', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-hai-tu-than-2', 'Lưỡi Hái Tử Thần 2', 'Final Destination 2', 'https://phimimg.com/upload/vod/20250519-1/15f2005cec3079a9fe0fdd9261400f97.jpg', 'https://phimimg.com/upload/vod/20250519-1/3d5863f52a18b35d6b684b4f5ab04238.jpg', '<p>Thoát chết trong một vụ tai nạn giao thông nhờ linh cảm báo trước, Kimberly bàng hoàng nhận ra rằng đã từng có một nhóm người thoát chết trong một vụ tai nạn máy bay nhưng họ lần lượt bị chết trong những tình huống kỳ lạ. Những người thoát chết trong vụ tai nạn giao thông lần này cũng bán tín bán nghi cho đến khi vài người trong số họ bị tử thần lấy mạng. Chỉ duy nhất một cách để không chị giết chết: họ phải đánh lừa được tử thần. Một phim kinh dị nổi gai ốc...</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"A. J. Cook","avatar":""},{"name":"Ali Larter","avatar":""},{"name":"Michael Landes","avatar":""},{"name":"Terrence ''T.C.'' Carson","avatar":""},{"name":"Jonathan Cherry","avatar":""},{"name":"Keegan Connor Tracy","avatar":""},{"name":"Lynda Boyd","avatar":""},{"name":"James Kirk","avatar":""},{"name":"Justina Machado","avatar":""},{"name":"David Paetkau","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Sarah Carter","avatar":""},{"name":"Alejandro Rae","avatar":""},{"name":"Shaun Sipos","avatar":""},{"name":"Andrew Airlie","avatar":""},{"name":"Noel Fisher","avatar":""},{"name":"Christ","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["絕命終結站2","Destino Final 2","مقصد نهایی 2","Destination Finale 2","Final Destination - viimeinen määränpää 2","Put bez povratka 2","Galutinis tikslas 2","Brez po