INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-cuoi-nang-mona-lisa', 'Nụ Cười Nàng Mona Lisa', 'Mona Lisa Smile', 'https://phimimg.com/upload/vod/20250511-1/37e0a1069f1a4653d1aca60a15ea6562.jpg', 'https://phimimg.com/upload/vod/20250511-1/f2b97eb50c4bd5ecfce6d44b0c36606b.jpg', '<p>Năm 1953, phụ nữ ở trường đại học Wellesley được đánh giá qua cuộc hôn nhân của họ, cho đến khi xuất hiện một giáo sư đe dọa thay đổi hiện trạng này.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Julia Roberts","avatar":""},{"name":"Kirsten Dunst","avatar":""},{"name":"Julia Stiles","avatar":""},{"name":"Maggie Gyllenhaal","avatar":""},{"name":"Ginnifer Goodwin","avatar":""},{"name":"Dominic West","avatar":""},{"name":"Juliet Stevenson","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"John Slattery","avatar":""},{"name":"Marian Seldes","avatar":""},{"name":"Donna Mitchell","avatar":""},{"name":"Terence Rigby","avatar":""},{"name":"Jennie Eisenhower","avatar":""},{"name":"Leslie Lyles","avatar":""},{"name":"Laura Allen","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Le sourire de Mona Lisa","Mona Lisa Smile","La sonrisa de Mona Lisa","Mona Lisas leende","O Sorriso de Monalisa","Усмішка Мони Лізи","모나리자 스마일","To hamogelo tis Mona Lisa","To xamogelo tis Mona Lisa","โมนา ลิซ่า ขีดชีวิตเขียนฝันให้บานฉ่ำ"]', 1784690324529);
