INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-trai-dat', 'Tâm Trái Đất', 'The Core', 'https://phimimg.com/upload/vod/20250420-1/ea54288afdfc42340b302c0140e846c4.jpg', 'https://phimimg.com/upload/vod/20250420-1/b409a26db068abb33d4a26e29015990b.jpg', '<p>Tâm Trái Đất lấy bối cảnh khi tâm Trái Đất ngừng quay khiến hàng loạt thảm kịch xảy ra. Trước tình cảnh đó, giáo sư Josh Keyes cùng một nhóm 5 khoa học gia được Chính phủ giao nhiệm vụ tối quan trọng: Du hành vào tâm Trái đất và đặt bom hạt nhân để khởi động lại ‘trái tim của Địa Cầu’.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Aaron Eckhart","avatar":""},{"name":"Hilary Swank","avatar":""},{"name":"Delroy Lindo","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"DJ Qualls","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Bruce Greenwood","avatar":""},{"name":"Christopher Shyer","avatar":""},{"name":"Ray Galletti","avatar":""},{"name":"Eileen Pedde","avatar":""},{"name":"Rekha Sharma","avatar":""},{"name":"Tom Scholte","avatar":""},{"name":"Glenn Morshower","avatar":""},{"name":"Anthony Harrison","avatar":""},{"name":"Alfre Woodard","avatar":""},{"name":"Fred Keating","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zemnoe jadro","Yadroto","O pyrinas: Apostoli sto kentro tis Gis","Jezgro","Yadro zemli","Fusion","The Core - Der innere Kern","ผ่านรกกลางใจโลก","The Core"]', 1784690324529);
