INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-vong-trong-dem', 'Cầu Vồng Trong Đêm', 'Fate Twisters', 'https://phimimg.com/upload/vod/20250415-1/cc9db85f5bc95d5f866a0ff12f1765ff.jpg', 'https://phimimg.com/upload/vod/20250415-1/1b6d91c9feb8da5bcb1f0d8d3b803030.jpg', '<p>Sau khi mẹ mất, Lạc Thiên Sanh (do Ngô Khải Hoa đóng) sống chung với cậu là Lạc Hiền. Anh vừa đi học vừa kiếm tiền nuôi gia đình cậu. Trong khi đó, cô sinh viên Thường Hỷ (do Thái Thiếu Phân đóng) phải nghỉ học để nuôi cháu gái Thường Tiểu Lối (do Thành Ca Doanh đóng) vì vợ chồng chị hai đã qua đời do tai nạn. Hỷ phải làm nhiều nghề để nuôi cháu gái bị bệnh hen suyễn. Cô không tiết lộ thân phận thật của Lối, xem cháu như con ruột của mình.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 12, 2003, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ada Choi Siu-Fan","avatar":""},{"name":"Lawrence Ng Kai-Wah","avatar":""},{"name":"Gigi Lai Chi","avatar":""},{"name":"Eddie Kwan Lai-Kit","avatar":""},{"name":"Eddy Ko Hung","avatar":""},{"name":"Peter Lai Bei-Dak","avatar":""},{"name":"Sunny Tai Yiu-Ming","avatar":""},{"name":"Margaret Chung","avatar":""},{"name":"Anita Chan Wing-Yin","avatar":""},{"name":"Tsang Wai-Wan","avatar":""},{"name":"Wai-Man Ngai","avatar":""},{"name":"Rosanne Lui Shan","avatar":""},{"name":"Timothy Shaw Chun-Yung","avatar":""},{"name":"Ku Feng","avatar":""},{"name":"Yu Miu-Lin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["黑夜彩虹"]', 1784690324529);
