INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-vong-trong-dem', 'Cầu Vồng Trong Đêm', 'Fate Twisters', 'cầu vồng trong đêm fate twisters ada choi siu-fan lawrence ng kai-wah gigi lai chi eddie kwan lai-kit eddy ko hung peter lai bei-dak sunny tai yiu-ming margaret chung anita chan wing-yin tsang wai-wan wai-man ngai rosanne lui shan timothy shaw chun-yung ku feng yu miu-lin 黑夜彩虹', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-dogville', 'Thị Trấn Dogville', 'Dogville', 'https://phimimg.com/upload/vod/20250414-1/439e136d9f7cc2dd72af6010311b1bb1.jpg', 'https://phimimg.com/upload/vod/20250414-1/3700ec15209a76d2bcd2ceaa2820a29c.jpg', '<p>Bộ phim kể về Grace, một người phụ nữ bí ẩn đang chạy trốn khỏi những kẻ truy đuổi, tình cờ đến một thị trấn nhỏ hẻo lánh tên là Dogville. Ban đầu, người dân thị trấn không tin tưởng cô, nhưng sau khi được một thanh niên tên Tom bảo lãnh, họ đồng ý cho cô trú lại — với điều kiện Grace phải làm việc để &quot;xứng đáng&quot; với lòng tốt của họ. Tuy nhiên, khi sự hiện diện của Grace bắt đầu khiến Dogville đối mặt với hiểm nguy, lòng tốt ấy dần biến mất. Dân thị trấn ngày càng đòi hỏi nhiều hơn, bóc lột và đối xử với cô ngày một tàn nhẫn, đến mức phi nhân tính. Cuối cùng, khi thân phận thật của Grace được tiết lộ, cô buộc phải đưa ra quyết định tàn khốc: tha thứ cho Dogville — hay trừng phạt họ vì những điều đã gây ra cho mình.</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Ben Gazzara","avatar":""},{"name":"Chloë Sevigny","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"James Caan","avatar":""},{"name":"Blair Brown","avatar":""},{"name":"Zeljko Ivanek","avatar":""},{"name":"Jeremy Davies","avatar":""},{"name":"Lauren Bacall","avatar":""},{"name":"Harriet Andersson","avatar":""},{"name":"Thom Hoffman","avatar":""},{"name":"Jean-","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Dogville: Uma Cidade Não Muito Longe","U - Der Film ''Dogville'' erzählt in neun Kapiteln und einem Prolog.","The Film ''Dogville'' as Told in Nine Chapters and a Prologue","Ổ Chó","Догвил","Dogvili","Dogville - A menedék","ドッグヴィル","Dogvilis","Догвилль","厄夜變奏曲","Kibirli Kasaba","Доґвіль","Thị Trấn Dogville","Dogville"]', 1784690324529);
