INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thi-tran-dogville', 'Thị Trấn Dogville', 'Dogville', 'thị trấn dogville dogville nicole kidman paul bettany john hurt stellan skarsgård philip baker hall patricia clarkson ben gazzara chloë sevigny siobhan fallon hogan james caan blair brown zeljko ivanek jeremy davies lauren bacall harriet andersson thom hoffman jean- dogville: uma cidade não muito longe u - der film ''dogville'' erzählt in neun kapiteln und einem prolog. the film ''dogville'' as told in nine chapters and a prologue ổ chó догвил dogvili dogville - a menedék ドッグヴィル dogvilis догвилль 厄夜變奏曲 kibirli kasaba доґвіль thị trấn dogville dogville', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-thap-trang-vi-dai', 'Tòa Tháp Trắng Vĩ Đại', 'The Great White Tower', 'https://phimimg.com/upload/vod/20250404-1/40438881646a69c19a33684c73ff64a0.jpg', 'https://phimimg.com/upload/vod/20250404-1/5146e2e3c45a66afd8a7a6bc15e9c4d5.jpg', '<p>Bộ phim kể về Zaizen Goro, một bác sĩ phẫu thuật tài giỏi nhưng đầy tham vọng, đối lập với Satomi Shuji, một bác sĩ tận tâm với y đức. Câu chuyện gồm hai phần: Cuộc chiến quyền lực: Zaizen mưu mô giành chức giáo sư tại một bệnh viện danh tiếng, trong khi Satomi chỉ tập trung cứu người. Vụ kiện y khoa: Một ca phẫu thuật thất bại dẫn đến kiện tụng, phơi bày tham vọng và đạo đức trong ngành y. Bộ phim khai thác sâu sắc về quyền lực, y đức và giá trị của sinh mạng con người.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 20, 2003, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshiaki Karasawa","avatar":""},{"name":"Yosuke Eguchi","avatar":""},{"name":"Hitomi Kuroki","avatar":""},{"name":"Akiko Yada","avatar":""},{"name":"Maki Mizuno","avatar":""},{"name":"Masatô Ibu","avatar":""},{"name":"Koji Ishizaka","avatar":""},{"name":"Atsuko Takahata","avatar":""},{"name":"Toshiyuki Nishida","avatar":""},{"name":"Mayumi Wakamura","avatar":""},{"name":"Tōru Shinagawa","avatar":""},{"name":"Ikki Sawamura","avatar":""},{"name":"Tae Kimura","avatar":""},{"name":"Hideaki Ito","avatar":""},{"name":"Kuranosuke Sasaki","avatar":""},{"name":"Naomi Nishida","avatar":""},{"name":"Rino Katase","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["白色巨塔","Shiroi kyotô","白い巨塔(2003)","Shiroi Kyotou","Shiroi Kyoto","하얀거탑(2003)","白い巨塔"]', 1784690324529);
