INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toa-thap-trang-vi-dai', 'Tòa Tháp Trắng Vĩ Đại', 'The Great White Tower', 'tòa tháp trắng vĩ đại the great white tower toshiaki karasawa yosuke eguchi hitomi kuroki akiko yada maki mizuno masatô ibu koji ishizaka atsuko takahata toshiyuki nishida mayumi wakamura tōru shinagawa ikki sawamura tae kimura hideaki ito kuranosuke sasaki naomi nishida rino katase 白色巨塔 shiroi kyotô 白い巨塔(2003) shiroi kyotou shiroi kyoto 하얀거탑(2003) 白い巨塔', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-cuong-phong', 'Siêu Nhân Cuồng Phong', 'Power Rangers Ninja Storm', 'https://phimimg.com/upload/vod/20250401-1/232437b54ae9c42d741745da0703ca45.jpg', 'https://phimimg.com/upload/vod/20250401-1/246eac2181126ca7c9a00638f8935e7b.jpg', '<p>Sâu trong những ngọn núi là học viện Ninja. Văn thư cổ đại ghi chép rằng: những chiến binh ưu tú nhất sẽ được chọn trở thành các Ranger bảo vệ nhân loại. Và thế giới Ninja tồn tại hai trường phái: Wind Ninja và Thunder Ninja. Tại học viện Wind Ninja, có ba học viên có tiềm năng lớn nhưng lười nhác là Shane Clarke, Tori Hanson và Dustin Brooks. Một ngày nọ, bè lũ Ninja tà ác từ ngoài vũ trụ do Lothor cầm đầu kéo đến phá huỷ học viện, bắt giữ tất cả học viên. &quot;Sensei&quot; Kanoi Wantanabe, hiệu trưởng học viện phải biến thành chuột lang để thoát thân. Shane, Tori và Dustin không ở học viện nên thoát nạn. Cam, con trai của Sensei dẫn đến Ninja Ops, căn cứ bí mật dưới lòng đất. Sensei trao cho họ các Wind Morpher, chiến đấu với bè lũ Lothor dưới danh nghĩa Wind Rangers. Sau này, họ gặp Hunter và Blake Bradley, tức các Thunder Ranger, hai học viên sót lại của học viện Thunder Ninja do học viện này cũng bị bè lũ Lothor tấn công. Các Ninja của hai trường phái giờ phải hợp tác với nhau, cùng với cả Cam, sau này là Green Samurai Ranger, đánh đuổi bè lũ Lothor ra khỏi Trái Đất, bảo vệ nhân loại.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 14, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324529);
