INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-nemo', 'Đi Tìm Nemo', 'Finding Nemo', 'https://phimimg.com/upload/vod/20250327-1/1d50e10bae6b4fa7d3b8e9f819780d3f.jpg', 'https://phimimg.com/upload/vod/20250327-1/83dcf493baaa2c3383457e72abc2b32d.jpg', '<p>Nemo, một chú cá hề trẻ thích phiêu lưu, bất ngờ được đưa từ nhà Great Barrier Reef của mình đến một bể cá văn phòng của nha sĩ. Cha Marlin lo lắng và một chú cá thân thiện nhưng hay quên Dory mang Nemo về nhà - gặp gỡ cá mập ăn chay, lướt rùa rùa, sứa thôi miên, hải âu đói, và nhiều thứ khác trên đường đi.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2003, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Albert Brooks","avatar":""},{"name":"Ellen DeGeneres","avatar":""},{"name":"Alexander Gould","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Austin Pendleton","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Vicki Lewis","avatar":""},{"name":"Joe Ranft","avatar":""},{"name":"Andrew Stanton","avatar":""},{"name":"Elizabeth Perkins","avatar":""},{"name":"Nicholas Bird","avatar":""},{"name":"Bob Peterson","avatar":""},{"name":"Barry Humphries","avatar":""},{"name":"Eric Bana","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Finding Nemo 3D","Disney Pixar Finding Nemo","Op zoek naar Nemo","نيمو","Hitta Nemo 3D","Tŭrseneto na Nemo","Psáchnontas ton Némo","V poiskakh Nemo","Potraga za Nemom","U poshukakh Nemo","ნემოს ძიება","ნემოს ძიებისას","Đi Tìm Nemo","İtmiş Balıq Nemo","Leitin að Nemo","У пошуках Нэма","Finding Nemo"]', 1784690324529);
