INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('di-tim-nemo', 'Đi Tìm Nemo', 'Finding Nemo', 'đi tìm nemo finding nemo albert brooks ellen degeneres alexander gould willem dafoe geoffrey rush brad garrett allison janney austin pendleton stephen root vicki lewis joe ranft andrew stanton elizabeth perkins nicholas bird bob peterson barry humphries eric bana finding nemo 3d disney pixar finding nemo op zoek naar nemo نيمو hitta nemo 3d tŭrseneto na nemo psáchnontas ton némo v poiskakh nemo potraga za nemom u poshukakh nemo ნემოს ძიება ნემოს ძიებისას đi tìm nemo i̇tmiş balıq nemo leitin að nemo у пошуках нэма finding nemo', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-tuyet-mat', 'Hồ Sơ Tuyệt Mật', 'The ''W'' Files', 'https://phimimg.com/upload/vod/20250324-1/91cfdaaeec3ea13cb1dcfbe23720bae1.jpg', 'https://phimimg.com/upload/vod/20250324-1/934f0388a9b154f36d67448eb51002f2.jpg', '<p>Vốn là người thích khám phá những điều kỳ thú trong cuộc sống nên Vệ Tư Lý đã cùng một người bạn thành lập một công ty thám tử. Võ công giỏi, thân thủ nhanh nhẹn, lại thêm tài trí thông minh nên Vệ Tư Lý trở thành một thám tử nổi tiếng. Một lần, anh gặp gỡ và quen biết bác sĩ Bạch Tố. Bạch Tố nhiều lần giúp anh thoát khỏi nguy hiểm. Tình yêu giữa họ dần nảy nở. Bạch Tố có người anh trai là Bạch Cơ Vĩ. Vì muốn chiếm đoạt kho báu, Bạch Cơ Vĩ đã đánh cắp chìa khóa bí mật của cha và một mình lên đường tìm kiếm kho báu. Bạch Tố bèn lên đường đi tìm anh trai mình. Vệ Tư Lý cũng theo sát bên cô.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 11, 2003, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Gallen Lo Ka-Leung","avatar":""},{"name":"Yoyo Mung Ka-Wai","avatar":""},{"name":"Fiona Yuen Choi-Wan","avatar":""},{"name":"Tavia Yeung","avatar":""},{"name":"Michael Tong Man-Lung","avatar":""},{"name":"Eddy Ko Hung","avatar":""},{"name":"Power Chan","avatar":""},{"name":"Mak Cheung-Ching","avatar":""},{"name":"Ming Yeung","avatar":""},{"name":"Roger Kwok Chun-On","avatar":""},{"name":"Anne Heung Hoi-Lam","avatar":""},{"name":"Samuel Kwok Fung","avatar":""},{"name":"Derek Kwok Jing-Hung","avatar":""},{"name":"Yoki Man Si-Kei","avatar":""},{"name":"Jimmy A","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f0084903