INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-sang-dieu-ky-cua-martin', 'Buổi Sáng Diệu Kỳ Của Martin', 'Martin Morning', 'https://phimimg.com/upload/vod/20250318-1/006df410e7ce7c8d775339e818dfdca3.jpg', 'https://phimimg.com/upload/vod/20250318-1/b0dc984abcece82adb6a0140604da8ad.jpg', '<p>Martin, cậu bé chín tuổi, có đặc điểm kỳ lạ: mỗi sáng thức dậy cậu bé biến thành những sinh vật cực &quot;ngầu&quot; - phù thủy Merlin, ma cà rồng, hay một siêu anh hùng và nhiều hơn thế nữa. Và dù có bị biến đổi, thì Martin vẫn đi học với bạn bè của mình, và những cuộc phiêu lưu cứ thế diễn ra mỗi ngày...</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 11, 2003, 'Thuyết Minh', 'FHD', 'Pháp', 0, '[]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324529);
