INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-em-khong-qua-10-ngay', 'Yêu em không quá 10 ngày', 'How to Lose a Guy in 10 Days', 'yêu em không quá 10 ngày how to lose a guy in 10 days kate hudson matthew mcconaughey kathryn hahn annie parisse adam goldberg thomas lennon michael michele shalom harlow robert klein bebe neuwirth samantha quan justin peroff celia weston james murtaugh rebecca harris archie macgregor john di hogyan veszítsünk el egy pasit 10 nap alatt hvordan bli dumpet på 10 dager como perder a un chico en 10 dias bir oğlan 10 gündə necə i̇tirilər? 10일 안에 남자친구에게 차이는 법 πώς να χωρίσετε σε δέκα μέρες 10일 안에 남자 친구에게 차이는 법 10일안에 남자친구에게 차이는 법 10일안에 남자 친구에게 차이는 법 comment perdre son mec en 10 jours how to lose a guy in 10 days', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-cua-nhung-chiec-nhan-su-tro-lai-cua-nha-vua', 'Chúa Tể Của Những Chiếc Nhẫn: Sự Trở Lại Của Nhà Vua', 'The Lord of the Rings: The Return of the King', 'https://phimimg.com/upload/vod/20250219-1/55705980dbf57659fd445f17e7024ad2.jpg', 'https://phimimg.com/upload/vod/20250219-1/66cc63a6f719e7ad25992639b050ab57.jpg', '<p>Sauron huy động toàn lực cho trận chiến khốc liệt cuối cùng, tấn công vào Gondor – vùng đất huyết mạch của loài người. Gondor dưới sự lãnh đạo của vị vua nhu nhược trở nên quá mong manh và nguy ngập. Đó chính là lúc những người anh hùng phát huy hết khả năng của mình. Cùng với sự hỗ trợ của các chiến binh Rohan, lực lượng những hồn ma bị nguyền rủa trong khe núi, Aragorn đã thống lĩnh những người Gondor chống lại Sauron, anh đã thực hiện sứ mệnh mà số phận giao phó cho mình, Aragorn sinh ra để trở thành Vua của Gondor, anh đã chứng minh điều đó. Cùng lúc đó, Frodo và Sam tiếp tục dấn sâu vào vùng đất ma quỷ đầy hiểm nguy để thực thi sứ mạng của mình, sứ mạng tiêu hủy Chiếc Nhẫn Quyền Lực. Có thể nói Sự Trở Lại Của Nhà Vua Phim là phần có nội dung hấp dẫn cùng những màn chiến đấu cực hay, cực kỳ hoành tráng.</p>', 'Full', 1, 'single', 'completed', 15, 2003, 'Vietsub', 'FHD', 'New Zealand', 0, '[{"name":"Elijah Wood","avatar":""},{"name":"Ian McKellen","avatar":""},{"name":"Viggo Mortensen","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Dominic Monaghan","avatar":""},{"name":"Billy Boyd","avatar":""},{"name":"John Noble","avatar":""},{"name":"David Wenham","avatar":""},{"name":"Miranda Otto","avatar":""},{"name":"Bernard Hill","avatar":""},{"name":"John Rhys-Davies","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Liv Tyler","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Karl Urban","avatar":""},{"name":"Ian Holm","avatar":""},{"name":"Sean B","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["The Return of the King","Sagan om konungens återkomst","Le Seigneur des Anneaux: Le Retour du Roi","Le Retour du Roi","The Lord of the Rings 3: The Return of the King","魔戒三部曲：王者再臨","魔戒3：王者归来","Господар на прстените: Враќањето на кралот","The Lord of the Rings III: The Return of the King","ESDLA","El señor de los anillos: El retorno del rey","LOTR: The Return Of The King","Chúa Tể Của Những Chiếc Nhẫn 3: Hai Tòa Tháp","ロード・オブ・ザ・リング／王の帰還：2003","The Lord of the Rings The Return of the King","Üzüklərin Hökmdarı:Kralın Qayıdışı","指环王3：王者无敌","LOTR3 - The Return of the King","ロード・オブ・ザ・リング／王の帰還","指环王3：王者归来","Le Seigneur des anneaux : Le Retour du roi - version longue","Der Herr der Ringe - Die Rueckkehr des Koenigs","Մատանիների Տիրակալը 3","Yüzüklerin Efendisi: Kralın Dönüşü","Властелин колец 3","Il Signore degli Anelli: Il Ritorno del Re","The Lord of the Rings: The Return of the King"]', 1784690324529);
