INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thu-2003', 'Báo Thù', 'Oldboy', 'https://phimimg.com/upload/vod/20231022-1/0e9beeeafd08f3621144442f2242c211.jpg', 'https://phimimg.com/upload/vod/20231022-1/8469764c512e903fa566e8595ba8e3a9.jpg', '<p>Oldboy được chuyển thể từ bộ truyện tranh nổi tiếng cùng tên của hai tác giả Nhật Bản là Minegishi Nobuaki và Tsuchiya Garon. Oldboy là bộ phim thứ hai trong bộ ba phim The Vengeance. Bộ phim kể về câu chuyện của Oh Dae-Su, người bị bắt nhốt trong một căn phòng khách sạn suốt 15 năm mà không hề biết rõ mục đích của kẻ bắt cóc. Khi được giải thoát, Dae Su rơi vào những cái bẫy của âm mưu và bạo lực. Trong cuộc hành trình tìm kiếm nhằm trả thù kẻ đã gây ra đau khổ cho mình, Dae-Su rơi vào vòng xoáy tình cảm với một đầu bếp sushi. Bất ngờ nối tiếp bất ngờ từ đây...</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Choi Min-sik","avatar":""},{"name":"Yoo Ji-tae","avatar":""},{"name":"Kang Hye-jung","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Ji Dae-han","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Lee Seung-shin","avatar":""},{"name":"Yoon Jin-seo","avatar":""},{"name":"Oh Tae-kyung","avatar":""},{"name":"Yoo Yeon-seok","avatar":""},{"name":"You Il-han","avatar":""},{"name":"Oh Kwang-rok","avatar":""},{"name":"Park Myung-shin","avatar":""},{"name":"Lee Dae-yeon","avatar":""},{"name":"Kim Su-hyun","avatar":""},{"name":"Yong-ih","avatar":""},{"name":"Syd Lim","avatar":""},{"name":"Mun Seong-Bok","avatar":""},{"name":"Yoon Jin-yul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b