INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-cuoi-ca-voi', 'Người Cưỡi Cá Voi', 'Whale Rider', 'https://phimimg.com/upload/vod/20241031-1/f7bb67a5048a359ffa77ecdba615be52.jpg', 'https://phimimg.com/upload/vod/20241031-1/b2180197826acddf40f5d8eecf757708.jpg', '<p>Khi Paikea sinh ra, mẹ và người anh trai song sinh của em chết. Cha em, Porourangi, đau đớn, không chỉ vì vợ con mất mà bởi chính người ông đã không thèm nhìn đến người vợ con trai mình đã mất và cũng không muốn nhìn đứa con cháu gái còn sống sót. Cha Paikea bỏ đi, để cô bé lớn lên cùng ông bà… Ông nội Koro, dù thất vọng bởi đứa cháu trai đã chết, cũng có nghĩa là không có người nối dõi vai trò tù trưởng lâu đời của dòng họ, vẫn yêu thương đứa cháu gái của mình. Nhưng mặc cho tình yêu ấy, ông luôn từ chối nhìn nhận khả năng lãnh đạo của cháu gái và đi tìm một đứa bé trai trong bộ lạc có thể thực hiện lời tiên tri, cưỡi cá voi đưa bộ tộc qua khỏi cơn sóng gió để trở thành tù trưởng…</p>', 'Full', 1, 'single', 'completed', 17, 2003, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Keisha Castle-Hughes","avatar":""},{"name":"Rawiri Paratene","avatar":""},{"name":"Vicky Haughton","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Grant Roa","avatar":""},{"name":"Mana Taumaunu","avatar":""},{"name":"Rachel House","avatar":""},{"name":"Taungaroa Emile","avatar":""},{"name":"Tammy Davis","avatar":""},{"name":"Mabel Wharekawa","avatar":""},{"name":"Rawinia Clarke","avatar":""},{"name":"Tahei Simpson","avatar":""},{"name":"Roi Taimana","avatar":""},{"name":"Elizabeth Skeen","avatar":""},{"name":"Rutene Spooner","avatar":""},{"name":"John Sumner","avatar":""},{"name":"Jane O�","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Te Kaieke Tohora","Encantadora de Baleias","La Légende des baleines","Paï","Paï : L''Élue d''un peuple nouveau","Valasratsastaja","Whale Rider"]', 1784690324530);
