INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuop-bien-vung-caribbean-loi-nguyen-tau-ngoc-trai-den', 'Cướp Biển Vùng Caribbean: Lời Nguyền Tàu Ngọc Trai Đen', 'Pirates of the Caribbean: The Curse of the Black Pearl', 'https://phimimg.com/upload/vod/20241008-1/c7193f8762bd01569d49ca33b8a9d72b.jpg', 'https://phimimg.com/upload/vod/20241008-1/44ee66be4e1e248afdb9a5aec76617b0.jpg', '<p>Khi chiếc thuyền của gia đình cô bé Elizabeth đi qua vùng biển Caribe nhiều cướp biển họ đã cứu được cậu bé Will Turner. Cả gia đình Elizabeth không hề biết rằng Will là William Turner, con trai của một tên trùm cướp biển khét tiếng. &nbsp;Nhiều năm sau, mọi chuyện dần dần được hé lộ khi Elizabeth bị ngã xuống biển do một tai nạn và được thuyền trưởng Jack Sparrow cứu thoát.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Jack Davenport","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Lee Arenberg","avatar":""},{"name":"Mackenzie Crook","avatar":""},{"name":"Damian O''Hare","avatar":""},{"name":"Giles New","avatar":""},{"name":"Angus Barnett","avatar":""},{"name":"David Bailie","avatar":""},{"name":"Michael Berry Jr.","avatar":""},{"name":"Isaac C. Singleton Jr.","avatar":""},{"name":"Kevin McNally","avatar":""},{"name":"Treva Etienne","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Shodeday Ha-Caribim: Klalat Ha-Pnina Ha-Sh''hora","Piraty Karybsʹkoho morya: Prok