INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-be-peter-pan', 'Chú Bé Peter Pan', 'Peter Pan', 'https://phimimg.com/upload/vod/20241004-1/88aef2a2d20d2a2a47cd0b09f4f1c01c.jpg', 'https://phimimg.com/upload/vod/20241004-1/27ce351d80e3142b3f805dcb5706eac7.jpg', '<p>Trong Edwardian London ngột ngạt, Wendy Darling mê hoặc các anh trai của mình mỗi đêm bằng những câu chuyện trước khi đi ngủ về kiếm thuật, chém gió và Thuyền trưởng Hook đáng sợ. Nhưng những đứa trẻ trở thành anh hùng của một câu chuyện thậm chí còn vĩ đại hơn, khi Peter Pan bay vào nhà trẻ của chúng vào một đêm nọ và dẫn chúng băng qua những mái nhà ngập ánh trăng xuyên qua một thiên hà đầy sao và đến những khu rừng tươi tốt của Neverland.</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jason Isaacs","avatar":""},{"name":"Jeremy Sumpter","avatar":""},{"name":"Rachel Hurd-Wood","avatar":""},{"name":"Lynn Redgrave","avatar":""},{"name":"Richard Briers","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Geoffrey Palmer","avatar":""},{"name":"Harry Newell","avatar":""},{"name":"Freddie Popplewell","avatar":""},{"name":"Ludivine Sagnier","avatar":""},{"name":"Mathew Waters","avatar":""},{"name":"George MacKay","avatar":""},{"name":"Harry Eden","avatar":""},{"name":"Patrick Hurd-Wood","avatar":""},{"name":"Bill Kerr","avatar":""},{"name":"Saffron Burrows","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Pán Péter","ピーター・パン","PETER PAN, LA GRAN AVENTURA","פיטר פן","피터팬","بيتر بان","彼得·潘","小飞侠","小飞侠彼得潘","Πίτερ Πα