INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ban-gia-su', 'Cô Bạn Gia Sư', 'My Tutor Friend', 'https://phimimg.com/upload/vod/20231208-1/5222097e660de2f55c8e72f913dd64e9.jpg', 'https://phimimg.com/upload/vod/20231208-1/e5017637dca84a96e601cee20a325412.jpg', '<p>Trong phim Cô Bạn Gia Sư, Choi Soo-wan và Kim Ji-hoon tuy cùng tuổi nhưng học lực lại có cách biệt lớn. Trong phim online này, Soo-wan đã là sinh viên đại học năm thứ hai, nhưng Ji-hoon vẫn còn đang là học sinh cấp ba vì bị lưu ban tới hai lần. Hoàn cảnh gia đình của cả hai cũng khác nhau một trời một vực. Soo-wan thì bị gán cho biệt danh gà quê. Trong khi đó, Ji-hoon là một công tử nhà giàu đẹp trai. Soo-wan vì phải kiếm thêm tiền đóng học phí mà phải đi làm gia sư dạy thêm cho Ji-hoon, và những rắc rối nảy sinh từ đây. Xem phim Cô Bạn Gia Sư bạn sẽ rất hài lòng với chất lượng dịch vụ xem phim online.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"HaNeul Kim","avatar":""},{"name":"Sang-Woo Kwon","avatar":""},{"name":"Il-seob Baek","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324530);
