INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-ho-tham-van-tam', 'Phú Hộ Thẩm Vạn Tam', 'The Magic Bowl', 'https://phimimg.com/upload/vod/20240916-1/2a8ddbcd59ca39f553340c029b7f8729.jpg', 'https://phimimg.com/upload/vod/20240916-1/c633d90dc2233516149794593f421803.jpg', '<p>Thẩm Vạn Tam vốn xuất thân trong một gia đình nhà nông nghèo. Yêu Triệu Tuyết Nga nhưng anh không có đủ tiền để cưới nàng. Vạn Tam quyết tâm đi làm giàu. Gặp biết bao gian khổ, có những lúc đi đến đường cùng do kẻ thù hãm hại, nhưng Thẩm Vạn tam đã lại đứng dậy cùng với sự giúp đỡ của Lục Xuân Hương, trở thành một phú hộ giàu có nhất của Trung Quốc</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 13, 2003, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"張衛健","avatar":""},{"name":"范冰冰","avatar":""},{"name":"Zhang Ting","avatar":""},{"name":"Liang Guanhua","avatar":""},{"name":"Qiang Gao","avatar":""},{"name":"Kou Zhenhai","avatar":""},{"name":"彭丹","avatar":""},{"name":"Sun Feihu","avatar":""},{"name":"朱泳腾","avatar":""},{"name":"许还山","avatar":""},{"name":"徐松子","avatar":""},{"name":"Xie Run","avatar":""},{"name":"薛佳凝","avatar":""},{"name":"Shang Yansheng","avatar":""},{"name":"Tu Ruying","avatar":""},{"name":"Yuzhi Zheng","avatar":""},{"name":"Cao Duo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324530);
