INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('net-dep-cua-loai-ran', 'Nét Đẹp Của Loài Rắn', 'The Beauty Of Snakes', 'https://phimimg.com/upload/vod/20240711-1/f7ca19f96201ca91a136abbf89ca59db.jpg', 'https://phimimg.com/upload/vod/20240711-1/5aa39a5d51a78aa5ace5259e21ed38a1.jpg', '<p>Đi từ sa mạc Namibia đến rừng Amazon, bộ phim tài liệu này mang đến cái nhìn cận cảnh về thế giới loài rắn với tất cả vẻ đẹp lộng lẫy của nó. Camera gắn trên lưng rắn cho phép người xem có cái nhìn toàn cảnh về thói quen và môi trường sống của chúng. Đoạn phim thu được cho thấy cách chúng giao phối, sinh con, săn mồi, kiếm ăn và tìm đường đi khắp thế giới. Rắn hổ mang, rắn sợi và rắn lục sừng sa mạc và chỉ là một vài trong số những sinh vật đặc trưng.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aoife McMahon","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324530);
