INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('y-thien-do-long-ky-ban-2003', 'Ỷ Thiên Đồ Long Ký (Bản 2003)', 'The Heaven Sword And Dragon Saber', 'https://phimimg.com/upload/vod/20240229-1/828822d7ea300748618589d7ae4abe16.jpg', 'https://phimimg.com/upload/vod/20240229-1/b57bd944d9ddf3a65f6cc91045d363e5.jpg', '<p>Ỷ Thiên Đồ Long Ký - The Heaven Sword And Dragon Saber dựa trên một tiểu thuyết võ hiệp của nhà văn Kim Dung, bối cảnh lấy vào cuối thời nhà Nguyên, 80 năm sau sự kiện trên đỉnh Hoa Sơn trong Thần Điêu Hiệp Lữ. Lúc này, nhà Nguyên đang bị suy yếu bởi các cuộc khởi nghĩa và vì sự xa hoa lãng phí của triều đình. Phim xoay quanh Trương Vô Kỵ - với bản tính kiên nhẫn, chất phác và y thuật cao siêu - và mối tình phức tạp với 4 cô gái, bên cạnh đó là những âm mưu thủ đoạn đầy máu tanh trên giang hồ nhằm chiếm đoạt 2 món báu vật là Đồ Long đao và Ỷ Thiên kiếm với lời đồn nếu tìm được bí mật trong đao kiếm sẽ hiệu triệu thiên hạ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 11, 2003, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Thích Tiểu Long","avatar":""},{"name":"Cao Viên Viên","avatar":""},{"name":"Giả Tịnh Văn","avatar":""},{"name":"Tô Hữu Bằng","avatar":""},{"name":"Trần Tú Lệ","avatar":""},{"name":"Trương Quốc Lập","avatar":""},{"name":"Trương Thiết Lâm","avatar":""},{"name":"Từ Cẩm Giang","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324530);
