INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('y-thien-do-long-ky-ban-2003', 'Ỷ Thiên Đồ Long Ký (Bản 2003)', 'The Heaven Sword And Dragon Saber', 'ỷ thiên đồ long ký (bản 2003) the heaven sword and dragon saber thích tiểu long cao viên viên giả tịnh văn tô hữu bằng trần tú lệ trương quốc lập trương thiết lâm từ cẩm giang ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-7-me-cung-trong-thanh-pho-co', 'Thám Tử Lừng Danh Conan 7: Mê Cung Trong Thành Phố Cổ', 'Detective Conan: Crossroad in the Ancient Capital', 'https://phimimg.com/upload/vod/20231019-1/e3c1029d2d0f32731a7efbf550c8e19d.jpg', 'https://phimimg.com/upload/vod/20231019-1/8181665b3e06a5fdfa73ae777e840871.jpg', '<p>Một kẻ giỏi kiếm đạo liên tiếp gây ra 5 vụ án mạng làm xôn xao giới cảnh sát Tokyo. Theo lời mời, Conan cùng thám tử Mori đến đền Sanno để tìm pho tượng Như Lai đã bị đánh cắp 8 năm về trước! Tình cờ gặp lại Hattori, hai người bắt tay hợp tác phá án. Trong quá trình thu thập thông tin, Hattori giáp mặt hung thủ và bị đe dọa đến tính mạng. Sự xuất hiện của cô bé Kazuha, mối tình đầu của Hattori càng làm mọi việc trở nên rối rắm. Conan sẽ làm thế nào để tìm ra hung thủ và bảo toàn mạng sống cho Hattori và Kazuha?</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2003, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Ryou Horikawa","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Atsuko Yuya","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Ryotaro Okiayu","avatar":""},{"name":"Yuko Miyamura","avatar":""},{"name":"Hirotaka Suzuok","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324530);
