INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-lung-danh-conan-7-me-cung-trong-thanh-pho-co', 'Thám Tử Lừng Danh Conan 7: Mê Cung Trong Thành Phố Cổ', 'Detective Conan: Crossroad in the Ancient Capital', 'thám tử lừng danh conan 7: mê cung trong thành phố cổ detective conan: crossroad in the ancient capital minami takayama wakana yamazaki akira kamiya kappei yamaguchi ryou horikawa chafurin atsuko yuya kazuhiko inoue megumi hayashibara ikue otani yukiko iwai kenichi ogata wataru takagi naoko matsui ryotaro okiayu yuko miyamura hirotaka suzuok ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-mua-he', 'Hương Mùa Hè', 'Summer Scent', 'https://phimimg.com/upload/vod/20240813-1/6600d56a40a286102fcf8e212282cac0.jpg', 'https://phimimg.com/upload/vod/20240813-1/b532152b0580198bd6384151a21b5177.jpg', '<p>Vì một tai nạn thảm khốc Min Woo mất đi mối tình đầu ngay trong ngày cưới. Mang theo trái tim tan vỡ chàng trai rời Hàn Quốc đến Ý xa xôi, tại đây chàng gặp Jong Ah, một cô gái hoạt bát, cá tính, dù Jong Ah luôn hướng về Min Woo nhưng nỗi đau trong quá khứ khiến anh không còn tin vào tình yêu và chỉ xem cô như người em gái. Hye Won - cô gái xinh như đóa hoa có cuộc sống tưởng như hoàn hảo, công việc tốt, vị hôn phu giỏi giang hết mực chăm lo cho cô. Nhưng từ nhỏ Hye Won đã mắc bệnh tim. Sau một lần được đưa ra nước ngoài để phẫu thuật thay tim, cô trở nên mạnh mẽ hơn. Nhưng Hye Won luôn cảm giác mình đang sống bằng trái tim của một người khác. Trong một lần tình cờ trú mưa, Hye Won gặp Min Woo. Cuộc gặp gỡ tình cờ nhưng đầy duyên nợ giữa Hye Won và Min Woo đã đưa họ đến với tình yêu lãng mạn trong những ngày mưa. Hye Won phải sống trong tâm trạng giằng xé, vừa không muốn làm tổn thương vị hôn phu của mình vừa không thể che giấu tình cảm định mệnh đối với Min Woo.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2003, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"손예진","avatar":""},{"name":"송승헌","avatar":""},{"name":"한지혜","avatar":""},{"name":"류진","avatar":""},{"name":"하재영","avatar":""},{"name":"신애","avatar":""},{"name":"조은숙","avatar":""},{"name":"김해숙","avatar":""},{"name":"김용건","avatar":""},{"name":"안정훈","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
