INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ganh-xiec-phan-1', 'Gánh Xiếc (Phần 1)', 'Carnivale (Season 1)', 'https://phimimg.com/upload/vod/20240808-1/67a5150480b4ed53752e1f3c3c5f4cbf.jpg', 'https://phimimg.com/upload/vod/20240808-1/a1f2aeb2ec6c9a113caa0758163caf83.jpg', '<p>Carnivale là một bộ phim truyền hình Mỹ lấy bối cảnh tại Hoa Kỳ trong thời kỳ Đại suy thoái và Dust Bowl. Khi theo dõi cuộc sống của hai nhóm người khác biệt, câu chuyện bao quát của nó mô tả cuộc chiến giữa thiện và ác và cuộc đấu tranh giữa ý chí tự do và số phận; cốt truyện kết hợp thần học Kitô giáo với thuyết ngộ đạo và truyền thuyết Masonic, đặc biệt là của Knights Templar.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 13, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nick Stahl","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Michael J. Anderson","avatar":""},{"name":"Adrienne Barbeau","avatar":""},{"name":"Debra Christofferson","avatar":""},{"name":"Tim DeKay","avatar":""},{"name":"Clea DuVall","avatar":""},{"name":"Cynthia Ettinger","avatar":""},{"name":"Carla Gallo","avatar":""},{"name":"Toby Huss","avatar":""},{"name":"Amy Madigan","avatar":""},{"name":"Brian Turk","avatar":""},{"name":"Ralph Waite","avatar":""},{"name":"John Fleck","avatar":""},{"name":"Blake Shields","avatar":""},{"name":"John Carroll Lynch","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324530);
