INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tu-dam-mau', 'Nhà Tù Đẫm Máu', 'Carandiru', 'https://phimimg.com/upload/vod/20240803-1/95b02bce6d2f9d4c493382246acd79a5.jpg', 'https://phimimg.com/upload/vod/20240803-1/e9ec8aa5b61cca49e552bb68c3f95866.jpg', '<p>Bác sĩ Drauzio Varella bắt đầu công tác phòng chống AIDS tại nhà tù lớn nhất Brazil, Carandiru ở São Paulo, nơi đang giam giữ gần gấp đôi mức tối đa là 4.000 người. Doc học hỏi từ kinh nghiệm và những câu chuyện bi thảm về những tội ác ghê tởm đã đổ đống cặn bã ở đó và những bộ phim truyền hình đam mê thêm những người tử tế khác. Ngay khi anh ta tin rằng sẽ khiến các tù nhân vui vẻ với một giải đấu bóng đá, một lý lẽ ngớ ngẩn về dây quần áo mở đầu cho một cuộc đàn áp cuộc nổi dậy cơ hội chính trị.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Luiz Carlos Vasconcelos","avatar":""},{"name":"Milton Gonçalves","avatar":""},{"name":"Ivan de Almeida","avatar":""},{"name":"Aílton Graça","avatar":""},{"name":"Maria Luísa Mendonça","avatar":""},{"name":"Aida Leiner","avatar":""},{"name":"Rodrigo Santoro","avatar":""},{"name":"Gero Camilo","avatar":""},{"name":"Lázaro Ramos","avatar":""},{"name":"Caio Blat","avatar":""},{"name":"Wagner Moura","avatar":""},{"name":"Julia Ianina","avatar":""},{"name":"Sabrina Greve","avatar":""},{"name":"Floriano Peixoto","avatar":""},{"name":"Ricardo Blat","avatar":""},{"name":"Vanessa Gerbelli","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324530);
