INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-den-nhi-do-8-dieu-hung-tranh-bip', 'Nhất Đen Nhì Đỏ 8 - Điêu Hùng Tranh Bịp', 'Who''s The Winner 8', 'https://phimimg.com/upload/vod/20240609-1/4aa9eeb576c1b0f47620f32cae9a0d6c.jpg', 'https://phimimg.com/upload/vod/20240609-1/264e1f3c43d1d45c97000201b2cfe346.jpg', '<p><em>Cờ bạc có thể bộc lộ lòng ham của con người. Điêu Hùng Tranh Bịp là một bi kịch nhắm vào đề tài này, lột trần tâm lý mê cờ bạc của con người. Cốt truyện được mở màng khi anh chàng Trịnh Thiên Lãng ăn mặc sáng sủa nhà nghề cờ bạc chạm trán cô lừa bịp diễm kiều Lý Mẫn. Rồi đi tới tranh gianh nhau vì một cuốn bí cập cờ bạc theo truyền thuyết…</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 2003, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Trương Gia Huy","avatar":""},{"name":"Giang Hoa","avatar":""},{"name":"Vạn Ý Vân","avatar":""},{"name":"Dương Ngọc Mai","avatar":""},{"name":"Doãn Thiên Chiếu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324530);
