INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-cuoi-kieu-my', 'Đám Cưới Kiểu Mỹ', 'American Wedding', 'https://phimimg.com/upload/vod/20231023-1/7ca925ba8dcd31fd75550cd7d4c30cca.jpg', 'https://phimimg.com/upload/vod/20231023-1/3ccd64aecd0b44efaa545e67dc0cccd8.jpg', '<p>American Wedding kể về đám cưới của Jim và Michelle, kết quả đáng mong ước từ mối tình trong 2 phần trước đó của họ. Kể từ lời cầu hôn không giống ai, hàng tá chuyện rắc rối không ngừng xảy đến với cặp đôi như bữa tiệc độc thân bất thành, sự xuất hiện của những ông bạn gay hay tệ hơn là toàn bộ hoa cưới bỗng héo rũ ngay trước lễ cưới… Với sự trợ giúp của những ông bạn “phá hoại”, ngày vui của Jim và Michelle sẽ diễn ra như thế nào? Mặc dù xoay quanh cặp đôi Jim và Michelle nhưng phần 3 của loạt phim American Pie này là lần đầu tiên câu chuyện tập trung vào nhân vật Steve Stifler và những trò hề tinh quái của anh. Với kịch bản hài hước, diễn xuất tự nhiên cùng những cảnh quay đẹp mắt, bộ phim đã ẵm hai giải thưởng tại MTV Movie Awards và Teen Choice Awards vào năm 2004.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Biggs","avatar":""},{"name":"Alyson Hannigan","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Eddie Kaye Thomas","avatar":""},{"name":"Thomas Ian Nicholas","avatar":""},{"name":"January Jones","avatar":""},{"name":"Eugene Levy","avatar":""},{"name":"Molly Cheek","avatar":""},{"name":"Deborah Rush","avatar":""},{"name":"Fred Willard","avatar":""},{"name":"Angela Paton","avatar":""},{"name":"Eric Allan Kramer","avatar":""},{"name":"John Cho","avatar":""},{"name":"Justin Isfeld","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Amanda Swisten","avatar":""},{"name":"Ni","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
