INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-keo-phan-1', 'Dao Kéo (Phần 1)', 'Nip/Tuck (Season 1)', 'https://phimimg.com/upload/vod/20240627-1/814c1cfa478aea407bcbe89c2d3a9df2.jpg', 'https://phimimg.com/upload/vod/20240627-1/1b156653b3e1618a2645297bbd2bb38f.jpg', '<p>Hai bác sĩ phẫu thuật thẩm mỹ - một người đàn ông tận tụy với gia đình và một người là một tay chơi vô đạo đức - cố gắng duy trì công việc kinh doanh của mình trong khi phải vượt qua vô số khó khăn, từ cá nhân đến khách hàng có liên hệ tội phạm.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 10, 2003, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dylan Walsh","avatar":""},{"name":"Julian McMahon","avatar":""},{"name":"Joel Richardson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324530);
