INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-cua-david-gale', 'Cuộc Đời Của David Gale', 'The Life Of David Gale', 'https://phimimg.com/upload/vod/20240227-1/7eb65b77c24e106cee025809fdea69a7.jpg', 'https://phimimg.com/upload/vod/20240227-1/27f1fedfbc090a3f677ff136bd999f51.jpg', '<p>Khi một giáo sư ở Texas kiêm người ủng hộ việc bãi bỏ án tử bị buộc tội oan, anh cuối cùng lại trở thành tội nhân chịu án tử.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Spacey","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Laura Linney","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324530);
