INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-doan-ma-tran', 'Binh Đoàn Ma Trận', 'The Animatrix', 'https://phimimg.com/upload/vod/20240219-1/8cf1d89d56c5cb9381ba2f80bc82c5d6.jpg', 'https://phimimg.com/upload/vod/20240219-1/f28d13cd41f22478039807bdffe46bcc.jpg', '<p>Trực tiếp từ những người tạo ra bộ ba Ma trận đột phá, bộ sưu tập phim hoạt hình ngắn này của các đạo diễn anime hàng đầu thế giới kết hợp đồ họa máy tính và phim hoạt hình Nhật Bản để cung cấp bối cảnh của vũ trụ Ma trận và cuộc xung đột giữa con người và máy móc. Các bộ phim ngắn bao gồm Chuyến bay cuối cùng của Osiris, Thời kỳ phục hưng thứ hai, Câu chuyện của đứa trẻ, Chương trình, Kỷ lục thế giới, Vượt ra ngoài, Câu chuyện trinh thám và Trúng tuyển.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"Clayton Watson","avatar":""},{"name":"Pamela Adlon","avatar":""},{"name":"Melinda Clarke","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324530);
