INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-thuong-hai', 'Hiệp Sĩ Thượng Hải', 'Shanghai Knights', 'https://phimimg.com/upload/vod/20240219-1/28e75fe9ea4877b276d233ce3c729677.jpg', 'https://phimimg.com/upload/vod/20240219-1/0f12d1c5ee7dcf1613dabb04bfb6a327.jpg', '<p>Bộ phim thuật lại cuộc phiêu lưu sang xứ sở sương mù của một người gốc Hoa muốn báo thù cho cha và một anh chàng hiệp sĩ rỏm suốt ngày nổ như ngô rang.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Fann Wong","avatar":""},{"name":"Aidan Gillen","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Tom Fisher","avatar":""},{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Alison King","avatar":""},{"name":"Constantine Gregory","avatar":""},{"name":"Anna-Louise Plowman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
