INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-phong-thap', 'Lôi Phong Tháp', 'Lôi Phong Tháp', 'https://phimimg.com/upload/vod/20240126-1/df2a7016b076f54f1b12b8e50e0477e2.jpg', 'https://phimimg.com/upload/vod/20240126-1/9a1fabfdd086b1744889a5b74c465029.jpg', '<p>Lôi Phong Tháp lấy bối cảnh năm Trung Diệp, Gia Tịnh nhà Minh, giặc Oa hoành hành, dân chúng lầm than. Lúc này người anh hùng trẻ tuổi Thích Kế Quang dẫn dắt Thích Gia Quân chống trả quân giặc, chém đầu thủ lĩnh giặc Oa. Từ đó tiếng tăm của chàng trai này được mọi người gần xa biết đến, trở thành thánh nhân trong trái tim dân chúng, anh hùng trong lòng các thiếu nữ. Triều đình vì trọng dụng nhân tài nên đã gọi anh nhập cung nhậm chức. Cũng từ đây bắt đầu một mối tình nhiều nước mắt giữa Thích Kế Quang và nàng Cửu Công Chúa.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 15, 2003, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Thiết Lâm","avatar":""},{"name":"Tiêu Anh Tuấn","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324530);
