INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-phong-thap', 'Lôi Phong Tháp', 'Lôi Phong Tháp', 'lôi phong tháp lôi phong tháp trương thiết lâm tiêu anh tuấn ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuy-quyen-say-vo-dich', 'Túy Quyền: Say Vô Địch', 'Túy Quyền: Say Vô Địch', 'https://phimimg.com/upload/vod/20240118-1/a68724b5cbebf1350766da0bcbc5a1f6.jpg', 'https://phimimg.com/upload/vod/20240118-1/80eb2ffb370ee66205a1ac961fccffcb.jpg', '<p>Phim Túy Quyền: Say Vô Địch lấy bối cảnh vào thời Mãn Thanh với sự cai trị của vua Ung Chính. Ở thành Dương Châu có nhà họ Long cưới vợ cho cậu con trai quý tử tên Long Thiếu Ngọc với nàng dâu xinh đẹp giỏi võ nhưng lại nổi tiếng là thích “động tay động chân” tên Hồng Mai. Hai người vốn có hôn ước từ khi còn trong bụng mẹ, tính tình cô dâu lại khắc chế được chàng công tử nên dễ dàng được chấp thuận. Thế nhưng, ngược đời là giữa đường Ngọc lại bỏ chạy, rồi cậu bị Mai bắt lại, dẫn về bái đường. Ai ngờ, khi Bái Thiên Địa thì gia gia của Mai qua đời, hôn lễ vì thế mà chưa thể hoàn thành một cách trọn vẹn. Không lâu sau, Ngọc quen biết cô đào tên Băng và con gái của Đề Đốc tên Viên, thường ra ngoài gây chuyện, đều được Mai tương trợ. Ngọc bái cha của Băng là sư phụ, có mâu thuẫn với hai người anh em là Thái và Chiếu. Rồi một ngày, bi kịch ập đến khiến không chỉ Ngọc bị hãm hại mà còn mất cha, từ đó Ngọc mới nhận ra điều gì thực sự tốt với mình.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 15, 2003, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Gia Huy","avatar":""},{"name":"Ngô Mạnh Đạt","avatar":""},{"name":"Viên Vịnh Nghi","avatar":""},{"name":"Hồng Y Bình","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324530);
