INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-mo-nha-tre', 'Bố Mở Nhà Trẻ', 'Daddy Day Care', 'https://phimimg.com/upload/vod/20240207-1/72b9aa6c3bb814a3377052c10af63c3c.jpg', 'https://phimimg.com/upload/vod/20240207-1/988127c6ca5c4d3b4d6f9008ade63237.jpg', '<p>Khi một ông bố tận tâm mất đi công việc béo bở trên web và đối mặt với tình trạng kiệt quệ tài chính, anh cùng hai người bạn mở một doanh nghiệp có tên là Daddy Day Care.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Jeff Garlin","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Regina King","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Kevin Nealon","avatar":""},{"name":"Jonathan Katz","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Lisa Edelstein","avatar":""},{"name":"Lacey Chabert","avatar":""},{"name":"Laura Kightlinger","avatar":""},{"name":"Leila Arcieri","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324530);
