INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('batman-bi-an-doi-nu', 'Batman: Bí Ẩn Dơi Nữ', 'Batman: Mystery Of The Batwoman', 'https://phimimg.com/upload/vod/20240207-1/808831194fceaefdf7835d6e8e0a8f98.jpg', 'https://phimimg.com/upload/vod/20240207-1/fee39baa4ebeab6b1510f81fffe67ec3.jpg', '<p>Hiệp sĩ bóng đêm Batman phải đối mặt với một câu hỏi khó, ai thực sự là nữ người dơi, khi tất cả các phương án Batman nghi ngờ đều vừa bị bác bỏ, nhưng một lần nữa,với khả năng thám tử siêu việt,Batman vừa tìm ra được sự thật đằng sau câu chuyện đầy rắc rối đó...</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Conroy","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Hector Elizondo","avatar":""},{"name":"Kyra Sedgwick","avatar":""},{"name":"David Ogden Stiers","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324530);
