INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-sieu-hang', 'Thợ Săn Siêu Hạng', 'The League Of Extraordinary Gentlemen', 'https://phimimg.com/upload/vod/20240128-1/26569e863d8dfb2ee1997da703773329.jpg', 'https://phimimg.com/upload/vod/20240128-1/9083bfd271531934a633d40912c144c5.jpg', '<p>Mượn ý tưởng từ cuốn tiểu thuyết hùng tráng và sinh động cùng tên của Alan Moore, bộ phim là câu chuyện về những nhân vật nổi tiếng của kho tàng văn học như Thuyền Trưởng Nemo, Allan Quatermain, Invisible Man, Mina Murray và Dr. Jekyll. Họ cùng chiến đấu bên nhau chống lại cái ác dưới mệnh lệnh tối cao trong giai đoạn quá độ của thế kỷ 19. Không những chứa đựng những tình huống vui nhộn, thú vị, bộ phim được xem như là sự kết hợp của Tom Sawyer và Dorian Gray.</p>', 'Full', 1, 'single', 'completed', 23, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Connery","avatar":""},{"name":"Stuart Townsend","avatar":""},{"name":"Peta Wilson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324530);
