INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-bac-bac-thang-giau', 'Bài Bạc Bác Thằng Giàu', 'Shade', 'https://phimimg.com/upload/vod/20240126-1/720781066201f52340575fd1605660df.jpg', 'https://phimimg.com/upload/vod/20240126-1/edbc6f5b91d4d2652c8458a514ee286a.jpg', '<p>Phim có khung cảnh của những sòng bài thâu đêm suốt sáng và những quán bar nhộn nhịp ở Los Angeles. Câu chuyện kể về một nhóm nghiện bài bạc đụng độ một cao thủ và thắng đậm nhưng sau đó phải đối mặt với đòn thù của lũ giang hồ.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joe Nicolo","avatar":""},{"name":"Carl Mazzocone Sr.","avatar":""},{"name":"George Tovar","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
