INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-thoi-tien-su-x-cuoc-di-cu-vi-dai', 'Vùng Đất Thời Tiền Sử X: Cuộc Di Cư Vĩ đại', 'The Land Before Time X: The Great Longneck Migration', 'https://phimimg.com/upload/vod/20240126-1/326bb31138e9dfe71a376dbe4de301ad.jpg', 'https://phimimg.com/upload/vod/20240126-1/1790cf4844cde54d79027374528f74a0.jpg', '<p>Chú khủng long cổ dài đáng yêu Chân Nhỏ phải đưa ra lựa chọn khó khăn: ở lại với khủng long bố mất tích từ lâu hay trở về với bạn bè và gia đình quen thuộc của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Ingle","avatar":""},{"name":"Alec Medlock","avatar":""},{"name":"Kenneth Mars","avatar":""},{"name":"Miriam Flynn","avatar":""},{"name":"Aria Noelle Curzon","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Anndi McAfee","avatar":""},{"name":"James Garner","avatar":""},{"name":"Bernadette Peters","avatar":""},{"name":"Kiefer Sutherland","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324530);
