INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vung-dat-thoi-tien-su-x-cuoc-di-cu-vi-dai', 'Vùng Đất Thời Tiền Sử X: Cuộc Di Cư Vĩ đại', 'The Land Before Time X: The Great Longneck Migration', 'vùng đất thời tiền sử x: cuộc di cư vĩ đại the land before time x: the great longneck migration john ingle alec medlock kenneth mars miriam flynn aria noelle curzon jeff bennett rob paulsen anndi mcafee james garner bernadette peters kiefer sutherland ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-dien-phong-the', 'Từ Điển Phòng The', 'The Sleeping Dictionary', 'https://phimimg.com/upload/vod/20240126-1/d95ae93c9a933a3974d3080c2f88ac38.jpg', 'https://phimimg.com/upload/vod/20240126-1/fbf1cd8fb10ad6a31ff75522290bf7fc.jpg', '<p>Một thanh niên người Anh được cử đến Sarawak để trở thành thành viên của chính quyền thuộc địa Anh. Anh gặp phải một số truyền thống không chính thống của địa phương và thấy mình phải đối mặt với những quyết định khó khăn trong lòng liên quan đến Selima xinh đẹp, đối tượng vô tình của tình cảm của anh.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Alba","avatar":""},{"name":"Hugh Dancy","avatar":""},{"name":"Brenda Blethyn","avatar":""},{"name":"Christopher Ling Lee Ian","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Bob Hoskins","avatar":""},{"name":"K.K. Moggie","avatar":""},{"name":"Noah Taylor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324530);
