INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-am-sat', 'Biệt Đội Ám Sát', 'Silmido', 'https://phimimg.com/upload/vod/20240126-1/d2e3657d064ed128a0407706acc894c2.jpg', 'https://phimimg.com/upload/vod/20240126-1/328373e7bffb6313c3b0074dce97338d.jpg', '<p>Phim Silmido (2003) có liên quan đến chính trị. Tháng 1/1968, mang trong mình tội danh giết người bị tử hình, In Chan đột nhiên được thoát chết và bí mật nhận một nhiệm vụ đến một hòn đảo phía Tây Nam. Khi đến đảo In Chan mới biết rằng có 30 người nữa cũng được thoát tội chết và đưa đến hòn đảo này và mang cùng một nhiệm vụ giống anh.</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Sung-kee Ahn","avatar":""},{"name":"Kyung-gu Sol","avatar":""},{"name":"Jun-ho Heo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
