INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-kiem-soat', 'Trạm Kiểm Soát', 'Kontroll', 'https://phimimg.com/upload/vod/20240126-1/24bd0745b330111d0bf85ed85287984b.jpg', 'https://phimimg.com/upload/vod/20240126-1/c931d02cce948388b8ad931cfbbb5cae.jpg', '<p>Câu chuyện kể về một chàng trai trẻ kỳ lạ, Bulcsú và những người kiểm tra vé đồng nghiệp trong nhóm của anh ta làm việc trên tàu điện ngầm Budapest Metro. Câu chuyện về cuộc đua dọc theo đường đua và về một kẻ giết người hàng loạt bí ẩn. Và một câu chuyện về tình yêu.</p>', 'Full', 1, 'single', 'completed', 17, 2003, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Sándor Csányi","avatar":""},{"name":"Csaba Pindroch","avatar":""},{"name":"Zoltán Mucsi","avatar":""},{"name":"Sándor Badár","avatar":""},{"name":"Zsolt Nagy","avatar":""},{"name":"Bence Mátyássy","avatar":""},{"name":"Győző Szabó","avatar":""},{"name":"Lajos Kovács","avatar":""},{"name":"Balla Eszter","avatar":""},{"name":"László Nádasi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324530);
