INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tram-kiem-soat', 'Trạm Kiểm Soát', 'Kontroll', 'trạm kiểm soát kontroll sándor csányi csaba pindroch zoltán mucsi sándor badár zsolt nagy bence mátyássy győző szabó lajos kovács balla eszter lászló nádasi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lau-dai-bat-tu', 'Lâu Đài Bất Tử', 'The Haunted Mansion', 'https://phimimg.com/upload/vod/20240123-1/2a396595d3e548111017ce50b579679c.jpg', 'https://phimimg.com/upload/vod/20240123-1/0c49b1f1fcfb830e83d54383a485f571.jpg', '<p>Trong dịp kỷ niệm ngày cưới, vợ chồng Jim Evers nhận được cú điện thoại mời cô vợ Sarah đến chơi tại một tòa biệt thự huyền bí. Vốn là một nhà kinh doanh bất động sản, Jim liền lập 1 kế hoạch kinh doanh ngôi biệt thự bằng cách cùng vợ con làm một chuyến dã ngoại gia đình. Thế nhưng ngôi biệt thự ma ám mà họ tham quan lại bị khống chế bởi thế giới bên kia. Và từ đó, những rắc rối, phiền toái bắt đầu phủ lấy gia đình Jim. Sau khi cùng vợ con vượt qua tất cả, Jim khám phá ra rằng không món lợi nhuận nào đáng giá hơn hạnh phúc của gia đình.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Marsha Thomason","avatar":""},{"name":"Jennifer Tilly","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324530);
