INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cua-nhan-loai', 'Cuộc Chiến Của Nhân Loại', 'Beyond Borders', 'https://phimimg.com/upload/vod/20240121-1/0c9d47e414a1eecb4a7e05019366a719.jpg', 'https://phimimg.com/upload/vod/20240121-1/4e08d157914498f7b84bf2aa924d07d5.jpg', '<p>Sarah Jordan, một phụ nữ Mỹ quyến rũ, có chồng là con một trùm tư bản ở Anh quốc. Cuộc sống của Sarah tưởng chừng như sẽ mãi êm đềm trong nhung lụa và tình yêu cuồng si của chồng. Nhưng rồi cái ngày định mệnh ấy, cái ngày mà cô gặp người đàn ông của đời mình, đã làm cuộc sống của Sarah hoàn toàn thay đổi. Người đàn ông đó là Nick Callahan, một bác sĩ tình nguyện luôn có mặt ở những nơi nóng bỏng nhất của thế giới vì hoạt động nhân đạo. Ánh mắt ấy, dáng người ấy và cái thái độ hiên ngang ấy cứ ám ảnh Sarah mãi, cô không sao quên được. Nick đã làm thức tỉnh trong cô bầu nhiệt huyết mãnh liệt được giúp đỡ những mảnh đời cơ cực, những nạn nhân của chiến tranh và đói nghèo, nhưng trên hết là một niềm khao khát mãnh liệt được gặp lại Nick.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clive Owen","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Linus Roache","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
