INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-thien-than-cua-charlie-2', 'Những Thiên Thần Của Charlie 2', 'Charlie''s Angels: Full Throttle', 'https://phimimg.com/upload/vod/20240121-1/2b5f301656082ae27e7f0f4dcf1a9cec.jpg', 'https://phimimg.com/upload/vod/20240121-1/1c33ad111155dfa714c376bc602ea5e1.jpg', '<p>Bộ ba nữ thám tử của Charlie được giao nhiệm vụ cải trang để tìm lại hai chiếc nhẫn trang sức bằng bạc có chứa thông tin được mã hóa, tiết lộ danh tính của những đối tượng nằm trong Chương trình bảo vệ nhân chứng của FBI. Các cô gái sẽ phải chạy đua với thời gian, vì nếu để danh sách này rơi vào tay kẻ xấu thì hàng nghìn người sẽ gặp nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Drew Barrymore","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Cameron Diaz","avatar":""},{"name":"Jaclyn Smith","avatar":""},{"name":"John Forsythe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324530);
