INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chuyen-gioi', 'Người Chuyển Giới', 'Tiresia', 'https://phimimg.com/upload/vod/20240205-1/d59ef0b458c88b40e53aa0f69b83ceef.jpg', 'https://phimimg.com/upload/vod/20240205-1/b1a9894298669dc5ebf51d77227fca2b.jpg', '<p>Dựa trên truyền thuyết về Tiresias, phim kể về một người chuyển giới bị một người đàn ông bắt cóc và bỏ mặc cho đến chết trong rừng. Sau đó, cô được một gia đình cứu sống và nhận được món quà nói về tương lai.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Laurent Lucas","avatar":""},{"name":"Clara Choveaux","avatar":""},{"name":"Thiago Telès","avatar":""},{"name":"Célia Catalifo","avatar":""},{"name":"Lou Castel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324530);
