INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ba-cua-lang-nguoi-dep', 'Bộ Ba Của Làng Người Đẹp', 'The Triplets of Belleville', 'https://phimimg.com/upload/vod/20231101-1/197e55c6fb8401704e85cbbcb9d18010.jpg', 'https://phimimg.com/upload/vod/20231101-1/4f18456c136a85745ca70da02ae9b66a.jpg', '<p>The Triplets of Belleville - Les Triplettes de Belleville (Bộ Ba Của Làng Người Đẹp) là bộ phim hoạt hình dài 78 phút do Pháp sản xuất. Được chắp bút bởi Sylvain Chomet, bộ phim kể về một cậu bé mồ côi Champion, lớn lên trong vòng tay của bà Madame Souza bên cạnh chú chó mập ú Bruno. Cậu bé rất ít nói và luôn nhìn ngắm bức ảnh của bố mẹ mình. Dường như hiểu được nỗi buồn của Champion nên bà Madame Souza luôn cố gắng làm mọi thứ để cậu bé được vui.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2003, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Suzy Falk","avatar":""},{"name":"Lina Boudreau","avatar":""},{"name":"Betty Bonifassi","avatar":""},{"name":"Michèle Caucheteux","avatar":""},{"name":"Jean-Claude Donda","avatar":""},{"name":"Mari-Lou Gauthier","avatar":""},{"name":"Charles Linton","avatar":""},{"name":"Monica Viegas","avatar":""},{"name":"Michel Robin","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324530);
