INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('che-ngu-cuong-no', 'Chế Ngự Cuồng Nộ', 'Anger Management', 'https://phimimg.com/upload/vod/20240111-1/20894ab99cedaee2e72b112210f7512c.jpg', 'https://phimimg.com/upload/vod/20240111-1/93590dfe2aa33da86270eacc5059fb52.jpg', '<p>Sau một hiểu lầm trên máy bay, anh chàng hiền lành Dave Buznik bị kết tội nóng giận mất kiểm soát, và buộc phải điều trị bởi ông bác sĩ chuyên khoa tâm lý khống chế cơn giận Buddy Rydell. Thế nhưng khóa điều trị càng làm anh chàng Dave nổi điên bởi những hóa đơn của nó! Hãy cùng theo dõi bộ phim để có giây phút sảng khoái với Adam Sandler...</p>', 'Full', 1, 'single', 'completed', 14, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Nicholson","avatar":""},{"name":"Adam Sandler","avatar":""},{"name":"Marisa Tomei","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
