INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-cody-banks', 'Điệp Viên Cody Banks', 'Agent Cody Banks', 'https://phimimg.com/upload/vod/20240103-1/2a5ebc29ce7543ee8344e4365af94994.jpg', 'https://phimimg.com/upload/vod/20240103-1/8aa060501eeb6844326d0e47f31988c2.jpg', '<p>Được chính phủ Hoa Kỳ tuyển dụng làm đặc vụ, cậu thiếu niên mọt sách Cody Banks phải thân thiết hơn với cô bạn cùng lớp dễ thương Natalie để tìm hiểu về một kế hoạch xấu xa do cha cô ấp ủ. Nhưng bất chấp tính cách đặc vụ, Cody vẫn phải vật lộn với cơn giận dữ của tuổi teen.</p>', 'Full', 1, 'single', 'completed', 15, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Frankie Muniz","avatar":""},{"name":"Hilary Duff","avatar":""},{"name":"Angie Harmon","avatar":""},{"name":"Keith David","avatar":""},{"name":"Cynthia Stevenson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324530);
