INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-co-mot-ta-con', 'Nhà Có Một Tá Con', 'Cheaper By The Dozen', 'https://phimimg.com/upload/vod/20240108-1/b9e053133613172db95316cd3ff117fa.jpg', 'https://phimimg.com/upload/vod/20240108-1/1a5a6ac97c4f11d296d9ce2575a9478d.jpg', '<p>Nhà Có Một Tá Con - Cheaper By The Dozen: Một gia đình 12 người con, di chuyển từ một thị trấn nhỏ Illinois đến thành phố lớn sau khi Tom Baker được công việc trong mơ của mình một huấn luyện đội tuyển bóng đá. Trong khi đó, vợ của ông ước mơ nhận cuốn sách của mình được xuất bản. Mâu thuẫn giữa hai vợ chồng ngày càng lớn, các con sẽ làm gì để cứu vãn gia đình của họ đây khi hạnh phúc bắt đầu tan rã...</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Martin","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Hilary Duff","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324530);
