INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-chien-binh-mang-ten-thanh', 'Những Chiến Binh Mang Tên Thánh', 'Saints And Soldiers', 'https://phimimg.com/upload/vod/20231231-1/4e022c19f3796be906c423fd893f92c4.jpg', 'https://phimimg.com/upload/vod/20231231-1/377848d3ba89241a4fe08cd2ff01c210.jpg', '<p>Năm 1945. Ba tuần trước khi quân đội Đồng Minh đánh bại phát-xít Đức, giải phóng châu Âu, chấm dứt Thế chiến II, tại Melmedy, 4 chiến sĩ người Mỹ gồm Hạ sĩ Greer biệt danh “Deacon-Thầy tu”, Quân y Steven Gould, Trung sĩ Gunderson và Binh nhì Kendrick đã trốn thoát được khỏi sự truy sát của quân Đức và đang tìm đường về với đơn vị của mình. Trên đường đi, họ gặp Trung sĩ không quân người Anh Oberon Winley – người đang nắm trong tay mọi kế hoạch tấn công tối mật của quân đội Đức, và cũng đang tìm cách thông báo những bí mật này cho chỉ huy của Đồng Minh. Họ đã cùng nhau tìm đường dến nơi đóng quân của Đồng Minh. Họ đã cùng nhau chiến đấu, vượt qua mọi nguy hiểm và cả sự hy sinh cao cả cho một châu Âu hòa bình bằng một tinh thần quả cảm. Một thiên anh hùng ca đầy xúc động.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Corbin Allred","avatar":""},{"name":"Alexander Polinsky","avatar":""},{"name":"Kirby Heyborne","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
