INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lat-mat', 'Lật Mặt', 'Paycheck', 'https://phimimg.com/upload/vod/20240102-1/c6eeb3229a32691e6768332ab3cda3d6.jpg', 'https://phimimg.com/upload/vod/20240102-1/e27701b32c0227266c81165ffe3f3ab9.jpg', '<p>Bộ phim xoay quanh kỹ sư chuyên về quang và cáp quang tên là Micheal, một người làm việc theo thời vụ cho các công ty lớn (sau mỗi đợt nghiên cứu công nghệ mới, các công ty sẽ xóa trí nhớ của anh ta trong suốt thời gian nghiên cứu). Sau một đợt nghiên cứu dài 3 năm cho công ty, anh tỉnh dậy mà chẳng nhớ đã làm gì. Anh nhận ra thù lao gần 100 triệu dollar của mình đã không còn, thay vào đó là một gói những thứ linh tinh do chính anh ta gửi cách đó 3 tuần, anh bàng hoàng hơn nữa khi bị FBI bắt vì tội phản quốc. Lúc này anh nhận ra, những món đồ linh tinh là những chìa khóa cứu mạng anh trong những tình thế hiểm nghèo. Anh sẽ tìm lại quá khứ của mình và chứng minh vô tội như thế nào, các bạn hãy khám phá nhé!</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Aaron Eckhart","avatar":""},{"name":"Uma Thurman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324530);
