INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-lenin', 'Tạm Biệt Lenin!', 'Good Bye Lenin!', 'https://phimimg.com/upload/vod/20240102-1/82cc860bf12cf0afe2a5690dce0cad52.jpg', 'https://phimimg.com/upload/vod/20240102-1/d31c7f77609c205ecc3d08062babebde.jpg', '<p>Bộ phim lần theo một nhà cộng sản tận tuỵ, người đã sống sót sau hàng tháng hôn mê trước sự kiện bức tường Berlin sụp đổ. Phim đã đứng đầu LHP ở Đức hồi tháng 6. Nam diễn viên xuất sắc Bruehl hân hoan: “Tôi quá sức mừng rỡ. Phim thực sự là một bài học lịch sử cho tôi”.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Daniel Brühl","avatar":""},{"name":"Katrin Saß","avatar":""},{"name":"Chulpan Khamatova","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
