INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boi-tham-doan-chay-tron', 'Bồi Thẩm Đoàn Chạy Trốn', 'Runaway Jury', 'null', 'https://phimimg.com/upload/vod/20240102-1/4a2de7a5fca07365f807bdb14e4c1732.jpg', '<p>Bồi Thẩm Đoàn Chạy Trốn - Runaway Jury kể về một vụ án nghiêm trọng xảy ra ngay tòa cao ốc Laurel Morgan, khiến 11 người bị giết, 5 người bị thương, còn thủ phạm thì tự sát ngay sau đó. Trong số các nạn nhân thiệt mạng có Jacob Wood – một nhà môi giới chứng khoán vừa tổ chức sinh nhật lần thứ tư cho cậu con trai Henry hồi cuối tuần. Hai năm sau khi vụ việc lắng xuống, một công ty luật đại diện là Wendell Rohr và Lawrencen Green khuyên Celeste Wood – vợ Jacob – đâm đơn kiện hãng sản xuất vũ khí để đòi công lý. Chiến thắng nghiêng về phe nào hoàn toàn phụ thuộc vào quyết định của thẩm phán và 12 thành viên bồi thẩm đoàn.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cusack","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Gene Hackman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
