INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-tien-dang-yeu', 'Chàng Tiên Đáng Yêu', 'Elf', 'https://phimimg.com/upload/vod/20231231-1/4d39d5d1731b48cfe02d4df7930fbaa9.jpg', 'https://phimimg.com/upload/vod/20231231-1/c807877d9b0afd39777fb42846f8b5fd.jpg', '<p>Elf là bộ phim kể về đứa con bị bỏ rơi và được ông già Noel nhặt về nuôi. Khi lớn lên cậu được ông già Noel tiết lộ thân thế thật sự của mình. Vì thế cậu quyết định đi tìm người cha ruột của mình. Khi gặp lại người cha ruột của mình cậu không được người cha nhìn nhận mà còn ruồng bỏ. Mất nhiều thời gian cậu mới chinh phục được người cha và sau đó là bà mẹ kế và đứa em cùng cha khác mẹ.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Ferrell","avatar":""},{"name":"James Caan","avatar":""},{"name":"Bob Newhart","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324530);
