INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-toi-la-gangster-2', 'Vợ Tôi Là Gangster 2', 'My Wife Is A Gangster 2', 'https://phimimg.com/upload/vod/20231231-1/50f06b5897c21e11fcf7a74a74761887.jpg', 'https://phimimg.com/upload/vod/20231231-1/592ee8262130101baf9c2e9c995ccbeb.jpg', '<p>Eun Jin biệt danh Cá Bạc là nữ thủ lĩnh của băng nhóm xã hội đen “Cây Kéo”. Trong một lần đụng độ với nhóm xã hội đen “Cá Mập Trắng”, Eun Jin bị ngã từ trên sân thượng tòa nhà cao ốc xuống đất, nhưng may mắn cho cô là đã rớt xuống trúng xe chở gà, và tình cờ một ông chủ nhà hàng Trung Hoa bắt gặp cô nằm bất tỉnh đã đưa cô đi bệnh viện, nhưng rồi cô đã hoàn toàn mất trí nhớ quên hết những gì đã xảy ra trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Thuyết Minh', 'HD', 'Hàn Quốc', 0, '[{"name":"Eun-Kyung Shin","avatar":""},{"name":"Jun Gyu Park","avatar":""},{"name":"Se-jin Jang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
