INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-don-doc', 'Kẻ Đơn Độc', 'A Man Apart', 'https://phimimg.com/upload/vod/20231208-1/5efc836ebe96dafb54b4458abfc63f13.jpg', 'https://phimimg.com/upload/vod/20231208-1/9f24589ec6d0d81eda8fb9aa0fcb053e.jpg', '<p>Anh chàng cơ bắp Vin Diesel vào vai một chiến sĩ đặc nhiệm đi bắt tội phạm ma túy. Nhưng khi hay tin người vợ yêu quý bị tổ chức tội phạm sát hại, anh đã quên tất cả và chỉ còn nhớ một điều duy nhất, đó là trả thù cho vợ mình...</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vin Diesel","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"Larenz Tate","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
