INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tinh-dang-do', 'Mối Tình Dang Dở', 'Josee, The Tiger And The Fish', 'https://phimimg.com/upload/vod/20231230-1/1d6fcd511e495492651359bd432eb0cd.jpg', 'https://phimimg.com/upload/vod/20231230-1/07b44366da2e8da61680948e12bfecb2.jpg', '<p>Một sinh viên trẻ tuổi, điển trai Tsuneo nghe được một câu chuyện về người đàn bà già thường đẩy xe đẩy vào buổi đêm, người ta nói rằng bà lão kì bí vận chuyển hàng cấm và thông tin cho bọn tội phạm thế nhưng một lần tình cờ Tsuneo phát hiện thật ra bà đang đưa đứa cháu gái tật nguyền Josee đi dạo hàng ngày. Dần dần, Tsuneo khám phá ra rằng thế giới của Josee có rất nhiều điểm thú vị, cho dù người bà không muốn ai biết đến sự tồn tại của Josee, cô vẫn sống và khát vọng được học tập, được hòa mình vào thế giới hiện tại...Tsuneo cũng không biết tự lúc nào anh yêu Josee, thế nhưng, giữa họ có quá nhiều rào cản...</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Satoshi Tsumabuki","avatar":""},{"name":"Chizuru Ikewaki","avatar":""},{"name":"Juri Ueno","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
