INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thu-toi-cua-sat-nhan', 'Lời Thú Tội Của Sát Nhân', 'Confessions Of A Dangerous Mind', 'https://phimimg.com/upload/vod/20231211-1/1d1f8772704b5b1b74f3eace2a64e90b.jpg', 'https://phimimg.com/upload/vod/20231211-1/b700159e1bbc090716f27a4c715e3fbe.jpg', '<p>Lời Thú Tội Của Kẻ Sát Nhân - Confessions of a Dangersous Mind là một bộ phim hình sự tội phạm hài 2002 của đạo diễn George Clooney. Nhà sản xuất chương trình trò chơi truyền hình Chuck Barris (Sam Rockwell) đang ở đĩnh cao của sự nghiệp. The Dating Game là một trong những chương trình hàng đầu do chính sự sáng tạo của ông làm nên. Nhưng không ai biết ông là một tên sát thủ bí mật của C.I.A và ông tuyên bố rằng đã giết chết 33 người. Bộ mặt sắp được phơi bày?</p>', 'Full', 1, 'single', 'completed', 9, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sam Rockwell","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"George Clooney","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324530);
