INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-mu', 'Siêu Nhân Mù', 'Daredevil', 'null', 'https://phimimg.com/upload/vod/20231211-1/89b791d5348cb5fab058052ecf408ad0.jpg', '<p>Siêu Nhân Mù - Daredevil xoay quanh Matt Murdock - một chàng trai luật sư bị mù từ bé. Sở hữu những giác quan nhạy bén đã biến Matt trở thành người siêu năng lực. Matt Murdock chống lại sự bất công vào ban ngày với vai luật sư và vào ban đêm với vai siêu anh hùng Daredevil ở Hells Kitchen, thành phố New York. Nhưng một ngày, Matt phải đối mặt với băng đảng xã hội đen do Kingpin đứng đầu cực kì nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 14, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
