INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-hai-tac-cuoc-dua-tu-than', 'Vua Hải Tặc: Cuộc Đua Tử Thần', 'One Piece The Movie Dead End No Bouken (Movie 4)', 'https://phimimg.com/upload/vod/20231211-1/c8b17e74cd76eb5e2d7cd449d547fc84.jpg', 'https://phimimg.com/upload/vod/20231211-1/86f73ae1fa3992612e4abbc03f2a970a.jpg', '<p>Luffy và thủy thủ đoàn đến bến cảng Anabaru. Sòng bạc địa phương đang tổ chức một cuộc thi, trong đó người chiến thắng sẽ nhận được phần thưởng lớn bằng tiền nếu anh ta về đích trước. Nami rất phấn khởi và quyết định tham gia cuộc thi. Tuy nhiên, có một âm mưu đằng sau cuộc thi và kẻ chủ mưu là một cựu chỉ huy quân đội, Gasparde. Kế hoạch của anh ta là dụ tất cả những tên cướp biển đến căn cứ quân sự và đưa họ đến chỗ chết. Luffy và cả nhóm phải vượt qua vô số thử thách và khổ nạn trên đường đi để hoàn thành cuộc phiêu lưu không có hồi kết này.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2003, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324530);
