INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-boi', 'Hồ Bơi', 'Swimming Pool', 'https://phimimg.com/upload/vod/20231211-1/54a8b335259cfc47b24080d61e129d23.jpg', 'https://phimimg.com/upload/vod/20231211-1/02494687439c539502b313cf9218c1f3.jpg', '<p>Câu chuyện về một nhà viết văn Sarah Morton từ England đến Pháp để giành trọn thời gian cho tác phẩm của mìn. Bà trú tại căn nhà của tay chủ nhà xuất bản cũng là tình nhân của mình, John tại Paris. Những tưởng sẽ có thời gian tĩnh lặng và riêng tư để dồn hết tâm trí cho tác phẩm tiểu thuyết trinh thám nhưng bất ngờ chỉ 1 ngày sau khi dọn đến, bà bị làm phiền bởi người khách không mời chính là con gái của tình nhân của mình, Julie.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlotte Rampling","avatar":""},{"name":"Ludivine Sagnier","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Jean-Marie Lamour","avatar":""},{"name":"Marc Fayolle","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324530);
