INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-man-dem-buong-xuong', 'Khi Màn Đêm Buông Xuống', 'Darkness Falls', 'https://phimimg.com/upload/vod/20231211-1/7be8f874a6971c7469a7ebb6a52e328b.jpg', 'https://phimimg.com/upload/vod/20231211-1/00353e2b14b102a6da488eed3da34737.jpg', '<p>Một linh hồn báo thù đã lấy hình dạng của Tiên răng để báo thù chính xác thị trấn đã giam giữ cô 150 năm trước. Đối lập duy nhất của cô là đứa con duy nhất, giờ đã trưởng thành, người đã sống sót trước cô.</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chaney Kley","avatar":""},{"name":"Emma Caulfield","avatar":""},{"name":"Lee Cormie","avatar":""},{"name":"Sullivan Stapleton","avatar":""},{"name":"Emily Browning","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324530);
