INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-day-chuyen-dinh-menh', 'Sợi Dây Chuyền Định Mệnh', 'My Lucky Star', 'https://phimimg.com/upload/vod/20231211-1/1e7134eecb95bb00bea54d7349b0098d.jpg', 'https://phimimg.com/upload/vod/20231211-1/4024f7d6236829250d4c4ed05ef32dd8.jpg', '<p>Sợi Dây Chuyền Định Mệnh - My Lucky Star xoay quanh câu chuyện về mối tình đầy trắc trở và gian nan của cặp đôi Yip và Lai. Trong phim, cả hai đã bắt đầu tìm hiểu nhau khi biết rằng số mạng của người kia rất hợp với mình. Sau khi cả Yip và Lai đều có tình cảm với đối phương và tưởng chừng như họ có thể đến với nhau thì một loạt sóng gió lại xảy đến. Nguyên nhân đó là sự xuất hiện của Duen cùng với những bùa chú nhằm chia cách Yip và Lai.</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Dương Thiên Hoa","avatar":""},{"name":"Lương Triều Vỹ","avatar":""},{"name":"Trịnh Trung Cơ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
