INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuyen-truong-va-dai-uy', 'Thuyền Trưởng Và Đại Úy', 'Master And Commander: The Far Side Of The World', 'https://phimimg.com/upload/vod/20231211-1/67f1e186b77710d9503d3f55a8a8b1b0.jpg', 'https://phimimg.com/upload/vod/20231211-1/648f38583b5313c7b001f13f6fd75799.jpg', '<p>Câu chuyện về thuyền trưởng Hải Quân Hoàng Gia Anh Quốc cùng thủy thủ đoàn trên con tàu Surprise đang làm nhiệm vụ trên biển trong thời kỳ chiến tranh giữa Anh và Pháp thời Napoleon. Họ gặp rất nhiều sóng gió, bão biển lẫn hiểm nguy trước kẻ thù. Ranh giới giữa cái chết và sự sống chỉ là sợi chỉ mong manh. Và nếu không có sự sáng suốt của thuyền trưởng Jack cùng thủy thủ đoàn dũng cảm thì kết cục của họ sẽ rất bi thảm...</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Billy Boyd","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
