INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-si-mu', 'Kiếm Sĩ Mù', 'The Blind Swordsman: Zatoichi', 'https://phimimg.com/upload/vod/20231210-1/3f0a2621791c3f7235cd66ab08bdec17.jpg', 'https://phimimg.com/upload/vod/20231210-1/cf353528ca78ee936430c5983350eec7.jpg', '<p>Phim là một trong những câu truyện kể về Zatoichi, một võ sĩ đạo mù nổi tiếng trong lịch sử Nhật Bản. Lần này trong khi phiêu bạt ông đã gặp hai chị em xinh đẹp Osei và Okinu, những người đang lần theo dấu vết của một băng cướp đã sát hại gia đình khi họ còn nhỏ. Hattori, một võ sĩ tài năng đã phải làm vệ sĩ cho bọn cướp kia để có tiền chữa trị cho người vợ bị bệnh nặng. Sau một trận đánh nghẹt thở, Zatoichi đã vượt qua được Hattori để tiếp tục lột mặt tên đầu đảng dấu mặt của bọn cướp, trả được mối thù cho hai chị em Osei và Okinu, đem lại cuộc sống yên bình cho người dân trong vùng ....</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takeshi Kitano","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Yui Natsukawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
