INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-no', 'Trừ Nợ', 'The Rundown', 'https://phimimg.com/upload/vod/20231209-1/86d30fa8fba921ba8eca540b6181ffdf.jpg', 'https://phimimg.com/upload/vod/20231209-1/115a3fc7d3c061e91bcdb5365b903f1c.jpg', '<p>Phim mở đầu với người hùng Beck được một triệu phú thuê sang Amazon dẫn độ Travis đem về Mỹ. Tiền thưởng cho chuyến đi mạo hiểm này là 250.000 đô-la. Travis chính là con trai của ông - một chàng thanh niên đam mê những cuộc phiêu lưu mạo hiểm đã bỏ nhà ra đi. Beck lên đường sang Amazon, đến thị trấn El Dorado hẻo lánh giữa rừng già. Đây là trung tâm mỏ vàng dưới quyền cai trị của Hatcher. Hắn điều hành công việc khai khoáng, bóc lột sức lao động của người bản xứ nhưng không ai dám chống lại gã. Trong khi đang hỏi thăm tin tức thì Beck gặp được Travis và khống chế anh ta đưa ra phi trường về lại Mỹ. Trên đường đi, xe của Beck lao xuống vực, cả hai rơi vào tay thổ dân Amazon. Họ đã cùng nhau chống lại Hatcher, giải thoát cho các công nhân làm nô lệ trong mỏ vàng. Liệu Beck có nhận được số tiền thưởng? Số phận của Travis sẽ ra sao?</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Christopher Walken","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
