INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-nam-hanh-phuc', 'Trăm Năm Hạnh Phúc', 'Love For All Seasons', 'https://phimimg.com/upload/vod/20231209-1/829ff0a41cf6065f29b18c04362def04.jpg', 'https://phimimg.com/upload/vod/20231209-1/c9150db5660842450429586046edbb92.jpg', '<p>Tiger là một thương gia giàu có và nổi tiếng ở Hồng Kông, đồng thời cũng là 1 tay sát gái chuyên nghiệp. Do mắc một chứng bệnh khó chữa anh phải đến Trung Quốc nhờ một vị thần y chữa bệnh. Tại đây anh gặp May - hậu nhân của vị thần y kia. May có võ công cao cường nhưng tiếc thay sư tỷ của cô - Lý Mạc Sầu do bị phụ tình nên hoá điên đòi thách đấu với cô. May không muốn Tiger bị liên lụy nên nhanh chóng chữa bệnh cho anh và đuổi anh về Hồng Kông. May thất bại dưới tay Lý Mạc Sầu do cô không học được bí quyết của sư phụ truyền lại. Bí quyết này chỉ có một kẻ bị đau đớn vì tình yêu mới có thể học thành được. May đành liều một phen đến Hồng Kông nhờ Tiger giúp cô hiểu được cảm giác đau đớn của tình yêu để quyết đấu lại một lần nữa với sư tỷ của mình. Lúc đầu cả hai chỉ vì giúp nhau có cảm giác bị phụ bạc nên không có tình cảm, nhưng mưa dầm thấm lâu, cả hai phát hiện ra đã yêu đối phương lúc nào không hay...</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Trịnh Tú Văn","avatar":""},{"name":"Cổ Thiên Nhạc","avatar":""},{"name":"Suet Lam","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
