INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-thoi-o-mexico', 'Một Thời Ở Mexico', 'Once Upon A Time In Mexico', 'https://phimimg.com/upload/vod/20231205-1/02211af02028df46eacde04f8984cbf1.jpg', 'https://phimimg.com/upload/vod/20231205-1/cabae0a1ab73eb92725c0334fce9da74.jpg', '<p>El Mariachi được gã đặc vụ CIA biến chất Sands thuê đi ngăn chặn vụ ám sát tổng thống Mexico vì biết anh có mối thù không đội trời chung với tên sát thủ. Âm mưu của Sands là để tên giết người ra tay trước, sau đó giết hắn để trừ hậu họa. Thế nhưng mọi chuyện lại xoay chuyển theo một kết cục không ai có thể ngờ đến.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Antonio Banderas","avatar":""},{"name":"Salma Hayek","avatar":""},{"name":"Johnny Depp","avatar":""},{"name":"Eva Mendes","avatar":""},{"name":"Willem Dafoe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324530);
