INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-hai-chi-em', 'Câu Chuyện Hai Chị Em', 'A Tale of Two Sisters', 'https://phimimg.com/upload/vod/20231204-1/991ad5f09e7a410d64dd9115436afd01.jpg', 'https://phimimg.com/upload/vod/20231204-1/8644f9c8752afa36d04d3cb0facc0f9d.jpg', '<p>Câu chuyện bắt đầu trong một bệnh viện tâm thần, vị bác sĩ đang nói chuyện với một cô gái trẻ có mái tóc xõa phủ ngang mặt. Ông đưa cho cô gái bức hình chụp gia đình cô, cố gắng thuyết phục cô gái kể về ngày đó.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kap-su Kim","avatar":""},{"name":"Jung-ah Yum","avatar":""},{"name":"Su-jeong Lim","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324530);
