INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('crazy-first-love', 'Crazy First Love', 'Crazy First Love', 'https://phimimg.com/upload/vod/20231215-1/3fc7376cf571eb5401d6f70954eec67b.jpg', 'https://phimimg.com/upload/vod/20231215-1/611aa56b3b9c53c24ef9f241c1c9a0a3.jpg', '<p>Một sinh viên trẻ yêu điên cuồng con gái của một giáo sư. Được giáo sư hứa sẽ cho anh cưới con gái nếu anh tốt nghiệp đại học với tấm bằng luật, chàng sinh viên chăm chỉ và cuối cùng đã thành công. Khi đến lúc vị giáo sư thực hiện lời hứa của mình, con gái ông bất ngờ thông báo rằng cô sẽ kết hôn với một người khác...</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324530);
