INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cang-gia-kim-thuat-su', 'Cang Giả Kim Thuật Sư', 'Fullmetal Alchemist', 'https://phimimg.com/upload/vod/20231204-1/b32b0238cd916ca80c1f2a44fcf2aa7a.jpg', 'https://phimimg.com/upload/vod/20231204-1/980a68755140e80c0db5aa635758c6f7.jpg', '<p>Hai anh em Edward Elric và Alphonse vì nhớ thương người mẹ đã khuất mà xúc phạm đến điều đại kị nhất trong thuật giả kim “Chuyển hóa con người” và mất đi mọi thứ. Người anh Edward Elric khoác lên mình Automail (chi giả sinh học), có biệt danh là Cang giả kim thuật sư. Người em Alphonse có linh hồn bị cố định trong áo giáp. Bộ phim là hành trình tìm kiếm Hòn đá triết gia để giành lại những gì đã mất của hai anh em.</p>', 'Hoàn Tất (51/51)', 51, 'hoathinh', 'completed', 11, 2003, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
