INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve-qua-khu-2013', 'Trở Về Quá Khứ 2013', 'Timeline 2013', 'https://phimimg.com/upload/vod/20231213-1/29aa81a0fee56e6e26672e9a228049bf.jpg', 'https://phimimg.com/upload/vod/20231213-1/c1794580785ed53094db7a4c8e9676ba.jpg', '<p>Ba sinh viên khảo cổ học đang tiến hành công trình nghiên cứu buộc phải quay về nước Pháp thế kỷ 14 để giải cứu giáo sư của mình, hội viên của viện Hàn Lâm nhưng mắc phải chứng ám ảnh. Ông đã bị kẹt lại đó khi mạo hiểm nghiên cứu tai nghe mắt thấy về thời đại ông tâm đắc...</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Walker","avatar":""},{"name":"Gerard Butler","avatar":""},{"name":"Billy Connolly","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324530);
