INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-chet-choc', 'Lời Nguyền Chết Chóc', 'The Death Curse', 'null', 'https://phimimg.com/upload/vod/20231213-1/ec1b93a39585416ca1adb7e40144132d.jpg', '<p>Ding Shi nhận được một lá thư từ cha cô, trong đó cô được yêu cầu gặp 7 anh chị em khác mà cô chưa từng gặp. Luật sư của cha cô và 6 anh chị em có mặt khi cô đến ngôi nhà cũ. Trước sự ngạc nhiên của cô, một trong những anh trai của cô là bạn trai cũ của cô. Theo di chúc của cha cô, tất cả 8 người con phải thức dậy để ông được thừa kế khối tài sản lớn. Bất đắc dĩ như vậy, họ ở lại và những điều kỳ quặc lần lượt xảy ra, bao gồm cái chết của người anh cả và người quản gia xuất hiện với một con dao trên tay… ..</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Charlene Choi","avatar":""},{"name":"Gillian Chung","avatar":""},{"name":"ALEX","avatar":""},{"name":"Raymond Ho-Yin Wong","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324530);
