INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-hai-tac-vuon-ra-dai-duong-giac-mo-to-lon-cua-bo', 'Vua Hải Tặc: Vươn Ra đại Dương! Giấc Mơ To Lớn Của Bố!', 'One Piece: Oounabara Ni Hirake! Dekkai Dekkai Chichi No Yume!', 'https://phimimg.com/upload/vod/20231212-1/16b827d13779ee310faf6c2f1899ede0.jpg', 'https://phimimg.com/upload/vod/20231212-1/bd6b3e308535389fa6c87cb078746635.jpg', '<p>Vua Hải Tặc: Vươn ra đại dương! Giấc mơ to lớn của bố! là chương trình truyền hình đặc biệt của anime One Piece. Phim được phát sóng sau tập 149 của anime vào ngày 6 tháng 8 năm 2003. Câu chuyện bắt đầu trên con tàu của Hải Tặc Zap. Nơi các thành viên đã quá mệt mỏi và muốn bỏ trốn, nhưng lại không có tiền. Có một đứa trẻ tên là Amanda, có cha là một thợ săn tiền thưởng chuyên nghiệp. Đã tiết lộ cho họ về 1 kho báu khổng lồ, với điều kiện phải mang chúng bỏ trốn theo. Trên đường bỏ chạy họ gặp được băng Mũ Rơm và đã hợp tác với nhau. Thật không may họ đã gặp được băng Hải tặc Bayan và phải chiến đấu chống lại chúng.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2003, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324530);
