INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-tuoi-tre-cua-joe-young-adam', 'Thời Tuổi Trẻ Của Joe Young Adam', 'Young Adam', 'https://phimimg.com/upload/vod/20231201-1/38feb43c7b11d313709c2e918bdc654c.jpg', 'https://phimimg.com/upload/vod/20231201-1/a072e1c4b797eef41ce7bfe89011c710.jpg', '<p>Một thanh niên trôi dạt làm việc trên sà lan trên sông đã phá vỡ cuộc sống của những người chủ của anh ta trong khi che giấu sự thật rằng anh ta biết nhiều hơn về một người phụ nữ đã chết được tìm thấy trên sông hơn là anh ta thừa nhận.</p>', 'Full', 1, 'single', 'completed', 9, 2003, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Peter Mullan","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Jack McElhone","avatar":""},{"name":"Therese Bradley","avatar":""},{"name":"Ewan Stewart","avatar":""},{"name":"Stuart McQuarrie","avatar":""},{"name":"Pauline Turner","avatar":""},{"name":"Alan Cooke","avatar":""},{"name":"Rory McCann","avatar":""},{"name":"Ian Hanmore","avatar":""},{"name":"Mhairi Morrison","avatar":""},{"name":"Anne Marie Timoney","avatar":""},{"name":"John Yule","avatar":""},{"name":"John Comerford","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
