INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-on-nin-gium', 'Làm Ơn Nín Giùm', 'Ruby & Quentin', 'https://phimimg.com/upload/vod/20231201-1/04b78b6b9fc6aa23bc7d61627fe08c14.jpg', 'https://phimimg.com/upload/vod/20231201-1/11433ebe39f53108126628114bf0b3f1.jpg', '<p>Sau khi giấu chiến lợi phẩm của mình và bị tống vào tù, Ruby, một kẻ sống ngoài vòng pháp luật đang ấp ủ gặp Quentin, một người khổng lồ lém lỉnh và ba hoa kết bạn với anh ta. Sau khi Quentin thất bại trong nỗ lực trốn thoát một mình, họ cùng nhau chia tay. Không thể lay chuyển Quentin Ruby vụng về buộc phải đưa anh ta đi cùng khi anh ta truy đuổi các đối tác cũ của mình để trả thù cho cái chết của người phụ nữ anh ta yêu và lấy tiền.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Gérard Depardieu","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Richard Berry","avatar":""},{"name":"André Dussollier","avatar":""},{"name":"Jean-Pierre Malo","avatar":""},{"name":"Leonor Varela","avatar":""},{"name":"Jean-Michel Noirey","avatar":""},{"name":"Laurent Gamelon","avatar":""},{"name":"Aurélien Recoing","avatar":""},{"name":"Vincent Moscato","avatar":""},{"name":"Ticky Holgado","avatar":""},{"name":"Michel Aumont","avatar":""},{"name":"Loïc Brabant","avatar":""},{"name":"Arnaud Cassand","avatar":""},{"name":"Edgar Givry","avatar":""},{"name":"Adrien Saint-Jo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324530);
