INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lam-on-nin-gium', 'Làm Ơn Nín Giùm', 'Ruby & Quentin', 'làm ơn nín giùm ruby & quentin gérard depardieu jean reno richard berry andré dussollier jean-pierre malo leonor varela jean-michel noirey laurent gamelon aurélien recoing vincent moscato ticky holgado michel aumont loïc brabant arnaud cassand edgar givry adrien saint-jo ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-lam-thuong-de', 'Một Ngày Làm Thượng Đế', 'Bruce Almighty', 'https://phimimg.com/upload/vod/20231130-1/5b86228b89a06d27c81b4e7f7ba8522a.jpg', 'https://phimimg.com/upload/vod/20231130-1/8098849c3551ad004890a56c29a400d5.jpg', '<p>Cuộc đời thật bất công, chắc chắn Chúa trời đang &quot;chơi xỏ&quot; mình - đó là suy nghĩ của anh chàng phóng viên truyền hình Bruce Nolan khi cuộc sống liên tiếp rơi vào bế tắc. Ai trong chúng ta cũng từng rơi vào hoàn cảnh như Bruce Nolan, nhưng có lẽ chỉ có mình anh mới được Chúa trời xuất hiện và trao cho anh quyền năng tối thượng để thay ông &quot;làm việc&quot;. Liệu rằng Bruce Nolan với những phép màu thần thánh có thay Chúa làm việc hiệu quả hơn hay không? Một bộ phim hài hước, duyên dáng mang nhiều ý nghĩa sâu sắc sẽ làm hài lòng bất cứ người xem khó tính nào, đặc biệt &quot;cây hài&quot; nổi tiếng Jim Carrey cũng là cái tên đảm bảo cho tiếng cười không ngớt trong 90 phút sắp tới!</p>', 'Full', 1, 'single', 'completed', 14, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Catherine Bell","avatar":""},{"name":"Lisa Ann Walter","avatar":""},{"name":"Steve Carell","avatar":""},{"name":"Nora Dunn","avatar":""},{"name":"Eddie Jemison","avatar":""},{"name":"Paul Satterfield","avatar":""},{"name":"Mark Kiely","avatar":""},{"name":"Sally Kirkland","avatar":""},{"name":"Tony Bennett","avatar":""},{"name":"Timothy Di Pri","avatar":""},{"name":"Brian Tahash","avatar":""},{"name":"Lou Felder","avatar":""},{"name":"Lillian Adams","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324530);
