INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-dich-thuc-2003', 'Tình Yêu Đích Thực', 'Love Actually', 'https://phimimg.com/upload/vod/20231030-1/52d67efe2f307a003f36fac2008e6351.jpg', 'https://phimimg.com/upload/vod/20231030-1/22f594247327bdd649f02eae36ea28a1.jpg', '<p>Phim tuyệt vời về tình yêu &amp; Giáng Sinh. Với nhịp điệu chậm rãi, tám câu chuyện tình lần lượt được đan chéo với nhau mà không làm mạch phim bị xáo trộn. Bên cạnh đó, mỗi cuộc tình lại mang một màu sắc khác nhau: lãng mạn, hài hước và sâu sắc... đã dạo nên một bản nhạc muôn điệu về tình yêu. Love Actually trở thành bộ phim hài lãng mạn có doanh thu cao nhất vào dịp cuối tuần trong lịch sử phim được công chiếu ở Anh và giữ vị trí quán quân bảng xếp hạng phim ăn khách nhất Anh quốc.</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Alan Rickman","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Hugh Grant","avatar":""},{"name":"Laura Linney","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Martine McCutcheon","avatar":""},{"name":"Andrew Lincoln","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Gregor Fisher","avatar":""},{"name":"Heike Makatsch","avatar":""},{"name":"Kris Marshall","avatar":""},{"name":"Lúcia Moniz","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Rodrigo Santoro","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324530);
