INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-dich-thuc-2003', 'Tình Yêu Đích Thực', 'Love Actually', 'tình yêu đích thực love actually alan rickman bill nighy colin firth emma thompson hugh grant laura linney liam neeson martine mccutcheon andrew lincoln keira knightley chiwetel ejiofor gregor fisher heike makatsch kris marshall lúcia moniz martin freeman rodrigo santoro ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-lizzie-mcguire', 'Nàng Lizzie McGuire', 'The Lizzie McGuire Movie', 'https://phimimg.com/upload/vod/20231129-1/a9c1e414825a0b7ba8204d393d2cde8b.jpg', 'https://phimimg.com/upload/vod/20231129-1/0c314af37228b742dafa26010e113836.jpg', '<p>Hầu như tất cả các cô gái ở lứa tuổi teen đều có máu phiêu lưu và luôn mong muốn có một chuyến chu du thật đáng nhớ trước khi trưởng thành, nhất là lại tới một nơi đẹp như Rome ở Italy. Cô nàng Lizzie (Hilary Duff) trong bộ phim The Lizzie McGuire Movie đã có chuyến du lịch làm thay đổi cả cuộc đời mình. 16 tuổi, vui tính, tốt bụng nhưng Lizzie vẫn luôn gặp những rắc rối do cô bé khá nhút nhát. Một lần tới Rome cùng bạn bè, Lizzie đã bị nhầm tưởng là Isabella – một ca sĩ rất nổi tiếng tại đây, từ đó cô bé bước vào một cuộc phiêu lưu đầy bất ngờ và lãng mạn trong vai Isabella, bên cạnh chàng ca sĩ Paolo đẹp trai hào hoa. Nhưng rồi bất ngờ Isabella thật xuất hiện và chuyện gì sẽ xảy ra tiếp theo đây nhỉ?</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hilary Duff","avatar":""},{"name":"Adam Lamberg","avatar":""},{"name":"Yani Gellman","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Brendan Kelly","avatar":""},{"name":"Ashlie Brillault","avatar":""},{"name":"Clayton Snyder","avatar":""},{"name":"Jake Thomas","avatar":""},{"name":"Jody Racicot","avatar":""},{"name":"Hallie Todd","avatar":""},{"name":"Robert Carradine","avatar":""},{"name":"Carly Schroeder","avatar":""},{"name":"Daniel Escobar","avatar":""},{"name":"Peter Kelamis","avatar":""},{"name":"Katy Louise Saunders","avatar":""},{"name":"Ona Grauer","avatar":""},{"name":"Antonio Cu","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324530);
