INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lara-croft-ke-cuop-lang-mo-cai-noi-cua-su-song', 'Lara Croft: Kẻ Cướp Lăng Mộ - Cái Nôi Của Sự Sống', 'Lara Croft: Tomb Raider - The Cradle of Life', 'https://phimimg.com/upload/vod/20231130-1/19b23108786f7710bbd50acc3f67ae6c.jpg', 'https://phimimg.com/upload/vod/20231130-1/ae6b905a4442266779d13dc7f9fbd0d2.jpg', '<p>MI6, cơ quan mật vụ Anh, nhờ Lara Croft tìm chiếc bình Pandora. Tiến sĩ Jonathan Reiss – nhà khoa học từng đoạt giải Nobel nhưng lại có tâm địa xấu xa – chạy đua với MI6 trong nỗ lực tìm kiếm chiếc bình hòng hủy diệt nền văn minh trên hành tinh xanh. Lara tìm anh bạn cũ Terry Sheridan, từng phục vụ trong lực lượng đặc nhiệm của Hải quân hoàng gia Anh, để nhờ giúp đỡ lấy lại quả cầu. Rủi thay, Terry đang bị nhốt trong nhà tù quân sự ở Kazakhstan. Nhờ có sự can thiệp của MI6, Terry được thả với một điều kiện: tuân theo mệnh lệnh của Lara. Hai người bắt đầu cuộc hành trình, rong ruổi từ lục địa này sang lục địa khác để tìm bọn người đánh cắp quả cầu.</p>', 'Full', 1, 'single', 'completed', 14, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Angelina Jolie","avatar":""},{"name":"Gerard Butler","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Chris Barrie","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Til Schweiger","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Terence Yin","avatar":""},{"name":"Daniel Caltagirone","avatar":""},{"name":"Fabiano Martell","avatar":""},{"name":"Jonny Coyne","avatar":""},{"name":"Robert Cavanah","avatar":""},{"name":"Ronan Vibert","avatar":""},{"name":"Lenny Juma","avatar":""},{"name":"Raymond Ofula","avatar":""},{"name":"Hezron Ajuala","avatar":""},{"name":"Alfred","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
