INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lara-croft-ke-cuop-lang-mo-cai-noi-cua-su-song', 'Lara Croft: Kẻ Cướp Lăng Mộ - Cái Nôi Của Sự Sống', 'Lara Croft: Tomb Raider - The Cradle of Life', 'lara croft: kẻ cướp lăng mộ - cái nôi của sự sống lara croft: tomb raider - the cradle of life angelina jolie gerard butler ciarán hinds chris barrie noah taylor djimon hounsou til schweiger simon yam terence yin daniel caltagirone fabiano martell jonny coyne robert cavanah ronan vibert lenny juma raymond ofula hezron ajuala alfred ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-cuoi', 'Yêu Là Cưới', 'Just Married', 'https://phimimg.com/upload/vod/20231129-1/2e6d17a949714a71177ca6ad8e0ca632.jpg', 'https://phimimg.com/upload/vod/20231129-1/5d668abaec3b235f8651ddd566896395.jpg', '<p>Câu chuyện vui nhộn về tuần trăng mật giữa một cặp vợ chồng mới cưới. Các diễn viên trong phim Ashton Kutcher, Brittany Murphy, Christian Kane do Shawn Levy làm đạo diễn. Nàng là con gái cưng của một gia đình giàu có, còn chàng là phát thanh viên chương trình thể thao và giao thông. Phim có độ dài 95 phút được phát hành vào 2003. Bạn đang xem phim Yêu Là Cưới | Just Married 2003 là phim mang yếu tố Hài Hước. Họ gặp nhau, bị tiếng sét ái tình và kết hôn chớp nhoáng khi chưa kịp hiểu nhiều về nhau. Tuần trăng mật tại Châu Âu của họ đã nảy sinh biết bao nhiêu chuyện dở khóc dở cười và họ chia tay nhau ngay sau khi trở về Mỹ. Nhưng dần dà, họ thật sự cảm thấy mình không thể sống thiếu người kia.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Ashton Kutcher","avatar":""},{"name":"Brittany Murphy","avatar":""},{"name":"Christian Kane","avatar":""},{"name":"David Moscow","avatar":""},{"name":"Alex Thomas","avatar":""},{"name":"Valeria Andrews","avatar":""},{"name":"Monet Mazur","avatar":""},{"name":"David Rasche","avatar":""},{"name":"Thad Luckinbill","avatar":""},{"name":"David Agranov","avatar":""},{"name":"Taran Killam","avatar":""},{"name":"Raymond J. Barry","avatar":""},{"name":"Toshi Toda","avatar":""},{"name":"George Gaynes","avatar":""},{"name":"Jill Parker-Jones","avatar":""},{"name":"Clement von Franckenstein","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
