INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-danh', 'Định Danh', 'Identity', 'https://phimimg.com/upload/vod/20231129-1/71cd4c30b899d4750fb3d81646a9c529.jpg', 'https://phimimg.com/upload/vod/20231129-1/28e86c15f8dbd4d7978c61ce96f0d763.jpg', '<p>11 người tình cờ tá túc tại một nhà trọ cũ kĩ trong đêm mưa tầm tã. Khi cơn mưa ngày càng nặng hạt cũng chính là lúc chuỗi giết người kinh hoàng của 1 tên sát nhân giấu mặt bắt đầu.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cusack","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"John Hawkes","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Clea DuVall","avatar":""},{"name":"John C. McGinley","avatar":""},{"name":"William Lee Scott","avatar":""},{"name":"Jake Busey","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Rebecca De Mornay","avatar":""},{"name":"Carmen Argenziano","avatar":""},{"name":"Marshall Bell","avatar":""},{"name":"Leila Kenzle","avatar":""},{"name":"Matt Letscher","avatar":""},{"name":"Bret Loehr","avatar":""},{"name":"Holmes Osbor","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
