INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-co-bien', 'Thiên Cơ Biến', 'Vampire Effect', 'https://phimimg.com/upload/vod/20231129-1/4409bf6b2652c921296931ee382d1e35.jpg', 'https://phimimg.com/upload/vod/20231129-1/9a971845248dc5de9d238142bfeacc9d.jpg', '<p>Bộ phim là câu chuyện xoay quanh cuộc chạy trốn của vị Hoàng tử thứ 5 của gia tộc ma cà rồng. Để tránh sự truy đuổi của Duke, Hoàng tử đã sang Hong Kong lánh nạn, ở đây anh gặp được Helen, em gái của một người chuyên đi săn ma cà rồng. Tình cờ gặp nhau để rồi nảy sinh tình cảm, một con người và một ma cà rồng, liệu họ có thể vượt qua mọi thử thách để sống cùng nhau ? Liệu Duke truy tím Hoàng tử cuối cùng của gia tộc nhằm mục đích gì ? Mời các bạn theo dõi bộ phim để có câu trả lời cuối cùng.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Gillian Chung","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Ekin Cheng Yee-Kin","avatar":""},{"name":"Josie Ho","avatar":""},{"name":"Jackie Chan","avatar":""},{"name":"Edison Chen","avatar":""},{"name":"Mickey Hardt","avatar":""},{"name":"Karen Mok Man-Wai","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Spencer Lam","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Matt Chow Hoi-Kwong","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Ricardo Mamood-Vega","avatar":""},{"name":"Mandy Chiang","avatar":""},{"name":"Maggie Lau Sze-Wai","avatar":""},{"name":"Winn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324530);
