INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-than-vung-texas-2003', 'Tử Thần Vùng Texas', 'The Texas Chainsaw Massacre', 'https://phimimg.com/upload/vod/20231127-1/803a29e0c34074755f257d885fc2eed7.jpg', 'https://phimimg.com/upload/vod/20231127-1/4be13838320dab68300fe948c71478f8.jpg', '<p>Sau khi cho một người trẻ tuôi đang bị thương đi nhờ xe, năm người bạn thấy mình bị rình rập và săn đuổi bởi một kẻ giết người cầm cưa quái dị và gia đình đầy những kẻ tâm thần không kém hắn.</p>', 'Full', 1, 'single', 'completed', 10, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jessica Biel","avatar":""},{"name":"Jonathan Tucker","avatar":""},{"name":"Andrew Bryniarski","avatar":""},{"name":"Erica Leerhsen","avatar":""},{"name":"Eric Balfour","avatar":""},{"name":"Mike Vogel","avatar":""},{"name":"R. Lee Ermey","avatar":""},{"name":"David Dorfman","avatar":""},{"name":"Lauren German","avatar":""},{"name":"Heather Kafka","avatar":""},{"name":"Terrence Evans","avatar":""},{"name":"Marietta Marich","avatar":""},{"name":"John Larroquette","avatar":""},{"name":"Kathy Lamkin","avatar":""},{"name":"Brad Leland","avatar":""},{"name":"Mamie Meek","avatar":""},{"name":"Harry Jay Know","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324530);
