INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-loi-o-tokyo', 'Lạc Lối Ở Tokyo', 'Lost in Translation', 'https://phimimg.com/upload/vod/20231129-1/5f50d83b5bcec8c441fd518278cc3d34.jpg', 'https://phimimg.com/upload/vod/20231129-1/87ff232fafccc10a19b44ab1c6b31d9f.jpg', '<p>Một chàng diễn viên sắp hết thời, một cô cử nhân triết học cùng rời nước Mỹ để rồi vô tình gặp nhau ở Tokyo. Từ chỗ xa lạ, sự cô đơn và đồng cảm đã đưa họ xích lại gần nhau, tạo nên một mối quan hệ lạ lùng nhưng vô cùng lãng mạn. Câu chuyện của họ như một bản nhạc êm dịu chảy vào lòng người.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Murray","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Anna Faris","avatar":""},{"name":"Akiko Takeshita","avatar":""},{"name":"Kazuyoshi Minamimagoe","avatar":""},{"name":"Kazuko Shibata","avatar":""},{"name":"Take","avatar":""},{"name":"Ryuichiro Baba","avatar":""},{"name":"Akira Yamaguchi","avatar":""},{"name":"Catherine Lambert","avatar":""},{"name":"François du Bois","avatar":""},{"name":"Tim Leffman","avatar":""},{"name":"Gregory Pekar","avatar":""},{"name":"Richard Allen","avatar":""},{"name":"Diamond Yukai","avatar":""},{"name":"Jun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
