INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-azumi', 'Sát Thủ Azumi', 'Azumi', 'https://phimimg.com/upload/vod/20231129-1/37403aad47767b69585e3e4308b08fca.jpg', 'https://phimimg.com/upload/vod/20231129-1/bb629b5a7a4aa6d7a29d8be7e60cbe9b.jpg', '<p>Ở một nơi nào đó trên đất nước Nhật Bản thời phong kiến, một đứa trẻ nữ ngồi bệt dưới đất bên cạnh xác người mẹ đã chết. Từ phía xa, một người lạ mặt cùng ba đứa trẻ nam đi tới. Đó là một samurai đi tìm môn đồ cho mình. Từ đó, Azumi được người thày nghiêm khắc đưa về nuôi dưỡng. Họ sống cách xa mọi điều văn minh, cùng nhau trải qua những bài tập luyện và những thử thách rất khắc nghiệt. Mối quan hệ giữa các chiến binh trẻ càng được thắt chặt và sự quyết tâm của họ ngày một lớn hơn. Rồi cũng đến lúc họ phải lên đường thực hiện nhiệm vụ của mình. Nhưng trước đó người thầy ra lệnh 5 người trong số bọn họ phải giết một trong năm người còn lại và bọn họ đã thực hiện. Azumi đã giết cậu bạn thân nhất của mình...</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Aya Ueto","avatar":""},{"name":"Kenji Kohashi","avatar":""},{"name":"Hiroki Narimiya","avatar":""},{"name":"Takatoshi Kaneko","avatar":""},{"name":"Yuma Ishigaki","avatar":""},{"name":"Yasuomi Sano","avatar":""},{"name":"Shinji Suzuki","avatar":""},{"name":"Eita Nagayama","avatar":""},{"name":"Shôgo Yamaguchi","avatar":""},{"name":"Shun Oguri","avatar":""},{"name":"Joe Odagiri","avatar":""},{"name":"Aya Okamoto","avatar":""},{"name":"Minoru Matsumoto","avatar":""},{"name":"Hideo Sakaki","avatar":""},{"name":"Kenichi Endo","avatar":""},{"name":"Kazuya Shimizu","avatar":""},{"name":"Tak Sakaguchi","avatar":""},{"name":"Ryo","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390