INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hulk-nguoi-khong-lo-xanh', 'Hulk: Người Khổng Lồ Xanh', 'Hulk', 'https://phimimg.com/upload/vod/20231125-1/e6c898a539c1339cf27f7b446d4cf65e.jpg', 'https://phimimg.com/upload/vod/20231125-1/4c87272c276aa430aa86c1b1d40c0681.jpg', '<p>Mang trong mình chất phóng xạ lạ, Bruce Banner mất kiểm soát bản thân và biến thành người khổng lồ xanh mỗi khi giận dữ. Con quái vật với sức mạnh kinh hoàng phá hủy mọi thứ trong tầm mắt. &nbsp;Vật lộn với một bản thể khác của mình, Bruce còn trở thành mục tiêu săn đuổi của chính phủ. Những kẻ khát khao sức mạnh của người khổng lồ xanh cũng theo dõi anh.</p>', 'Full', 1, 'single', 'completed', 14, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eric Bana","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Sam Elliott","avatar":""},{"name":"Josh Lucas","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Paul Kersey","avatar":""},{"name":"Cara Buono","avatar":""},{"name":"Kevin Rankin","avatar":""},{"name":"Todd Tesen","avatar":""},{"name":"Celia Weston","avatar":""},{"name":"Mike Erwin","avatar":""},{"name":"Lou Ferrigno","avatar":""},{"name":"Stan Lee","avatar":""},{"name":"Regi Davis","avatar":""},{"name":"Craig Damon","avatar":""},{"name":"Geoffrey Scott","avatar":""},{"name":"Regina McKee Redwing","avatar":""},{"name":"Daniel Dae Kim","avatar":""},{"name":"Daniella","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324530);
