INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-ha-thu-dong-roi-lai-xuan', 'Xuân, Hạ, Thu, Đông... Rồi Lại Xuân', 'Spring, Summer, Fall, Winter... and Spring', 'https://phimimg.com/upload/vod/20231125-1/3682c9bb3d0e146169fb60a0b20871a9.jpg', 'https://phimimg.com/upload/vod/20231125-1/0b1186c2a4392a5040c782d73c282ce8.jpg', '<p>Tại cái hồ cách biệt với thế giới bên ngoài, nơi đó có vị sư già sống trên một thủy am nhỏ. Vị sư nuôi một cậu trai trẻ và dạy dỗ cậu để trở thành một vị hòa thượng. 5 mùa trôi qua, mỗi mùa tượng trưng cho một giai đoạn của cuộc đời vị tiểu hòa thượng này. Phim đem đến những điều thú vị về thân phận, về mâu thuẫn giữa tình yêu trần tục và thánh thiện, giữa sự vô tâm và bản tính tốt đẹp của con người.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Oh Young-soo","avatar":""},{"name":"Kim Ki-duk","avatar":""},{"name":"Kim Young-min","avatar":""},{"name":"Seo Jae-kyeong","avatar":""},{"name":"Kim Jong-ho","avatar":""},{"name":"Ha Yeo-jin","avatar":""},{"name":"Kim Jung-young","avatar":""},{"name":"Ji Dae-han","avatar":""},{"name":"Choe Min","avatar":""},{"name":"Park Ji-a","avatar":""},{"name":"Song Min-young","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324530);
