INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dac-nhiem-swat', 'Đội Đặc Nhiệm S.W.A.T.', 'S.W.A.T.', 'https://phimimg.com/upload/vod/20231125-1/d35b710f6884604a7efc1afdb4b718d8.jpg', 'https://phimimg.com/upload/vod/20231125-1/3fd01632cc31c57257c1a2067c36ced2.jpg', '<p>Hondo Harrelson tuyển Jim Street gia nhập đơn vị tinh nhuệ của Sở Cảnh sát Los Angeles. Họ cùng nhau tìm kiếm thêm thành viên, bao gồm Deke Kay cứng rắn và bà mẹ đơn thân Chris Sanchez. Nhiệm vụ lớn đầu tiên của đội là hộ tống trùm tội phạm Alex Montel vào tù. Việc này có vẻ như thường lệ, nhưng khi Montel đưa ra phần thưởng khổng lồ cho bất kỳ ai có thể giải thoát anh ta, những tên tội phạm đủ loại sẽ xông lên giành giải thưởng.</p>', 'Full', 1, 'single', 'completed', 11, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Samuel L. Jackson","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"Michelle Rodriguez","avatar":""},{"name":"LL Cool J","avatar":""},{"name":"Josh Charles","avatar":""},{"name":"Jeremy Renner","avatar":""},{"name":"Brian Van Holt","avatar":""},{"name":"Olivier Martinez","avatar":""},{"name":"Domenick Lombardozzi","avatar":""},{"name":"Reg E. Cathey","avatar":""},{"name":"Larry Poindexter","avatar":""},{"name":"Page Kennedy","avatar":""},{"name":"James DuMont","avatar":""},{"name":"Denis Arndt","avatar":""},{"name":"Lindsey Ginter","avatar":""},{"name":"Octavia Spencer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324530);
