INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-giu-giac-mo', 'Người Giữ Giấc Mơ', 'Dreamcatcher', 'https://phimimg.com/upload/vod/20231125-1/88b30fb957e094a95cd2c81ce6291579.jpg', 'https://phimimg.com/upload/vod/20231125-1/78c401267d24d815620cb84b6b01767a.jpg', '<p>Dreamcatcher là tên gọi của một loại bùa bình an. Truyền thuyết kể rằng: Ojibwa - một bộ tộc người Mỹ - tin rằng màn đêm luôn chứa đựng những giấc mơ đẹp và những giấc mơ xấu. Trong văn hóa của Ojibwa, Dreamcatcher là một loại bùa được treo đầu giường để bảo vệ những đứa trẻ đang ngủ khỏi những cơn ác mộng. Câu chuyện bắt đầu khi bốn người bạn thân từ thời thơ ấu có chuyến họp mặt săn bắn hàng năm tại một cabin trong rừng, và rồi những điều kỳ lạ xảy ra ...</p>', 'Full', 1, 'single', 'completed', 14, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Morgan Freeman","avatar":""},{"name":"Thomas Jane","avatar":""},{"name":"Jason Lee","avatar":""},{"name":"Damian Lewis","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"Donnie Wahlberg","avatar":""},{"name":"Mikey Holekamp","avatar":""},{"name":"Reece Thompson","avatar":""},{"name":"Giacomo Baessato","avatar":""},{"name":"Joel Palmer","avatar":""},{"name":"Andrew Robb","avatar":""},{"name":"Rosemary Dunsmore","avatar":""},{"name":"Michael O''Neill","avatar":""},{"name":"Eric Keenleyside","avatar":""},{"name":"C. Ernst Harth","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","s