INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-giu-giac-mo', 'Người Giữ Giấc Mơ', 'Dreamcatcher', 'người giữ giấc mơ dreamcatcher morgan freeman thomas jane jason lee damian lewis timothy olyphant tom sizemore donnie wahlberg mikey holekamp reece thompson giacomo baessato joel palmer andrew robb rosemary dunsmore michael o''neill eric keenleyside c. ernst harth m ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoang-khac-cua-tuoi-tre', 'Khoảng Khắc Của Tuổi Trẻ', 'The Best of Youth', 'https://phimimg.com/upload/vod/20231124-1/9d296825ad691b4340a458986e361561.jpg', 'https://phimimg.com/upload/vod/20231124-1/e9c436bf7d41e646ca070731714b6443.jpg', '<p>Khoảng Khắc Của Tuổi Trẻ lấy tựa từ một ý thơ của nhà thơ/đạo diễn Pier Paolo Pasolini, một biểu tượng văn hóa nước Ý bị sát hại vào năm 1975. Đạo diễn Giordana từng làm phim về ông trước đây, và muốn tưởng nhớ đến ông.Bộ phim gồm rất nhiều cuộc đời, rất nhiều sự kiện, nhưng chủ yếu xoay quanh hai anh em nhà Caratis, bắt đầu từ mùa hè năm 1966 khi họ chuẩn bị tốt nghiệp đại học. Người anh Matteo (Alessio Boni), nóng tính, bốc đồng và khó gần, trượt kỳ tốt nghiệp nhưng giấu tất cả mọi người. Kể cả bố, mẹ, chị gái, em trai Nicole và một em gái bé bỏng. Trong khi chờ đợi, anh nhận một công việc tình nguyện đưa những bệnh nhân tâm thần đi dạo. Ở đó, Matteo gặp gỡ một cô gái trẻ xinh đẹp, Giorgia (Jasmine Trinca)</p>', 'Full', 1, 'single', 'completed', 16, 2003, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Luigi Lo Cascio","avatar":""},{"name":"Alessio Boni","avatar":""},{"name":"Adriana Asti","avatar":""},{"name":"Sonia Bergamasco","avatar":""},{"name":"Fabrizio Gifuni","avatar":""},{"name":"Maya Sansa","avatar":""},{"name":"Valentina Carnelutti","avatar":""},{"name":"Jasmine Trinca","avatar":""},{"name":"Andrea Tidona","avatar":""},{"name":"Lidia Vitale","avatar":""},{"name":"Claudio Gioè","avatar":""},{"name":"Paolo Bonanni","avatar":""},{"name":"Giovanni Scifoni","avatar":""},{"name":"Riccardo Scamarcio","avatar":""},{"name":"Camilla Filippi","avatar":""},{"name":"Mario Schian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
