INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buong-dien-thoai', 'Buồng Điện Thoại', 'Phone Booth', 'https://phimimg.com/upload/vod/20231120-1/62977564fe96457c7d3fdf0221f57890.jpg', 'https://phimimg.com/upload/vod/20231120-1/69858389b9c52c5fce7ec40462796159.jpg', '<p>Nội dung phim xoay quanh Stu, một tay môi giới ngôi sao chẳng có mấy tiếng tăm nhưng đủ tài loè bịp lắm người. Trong số đó là Pam, cô bé dưới quê mới lên, dễ thương, đáng yêu và dễ dụ. Hàng ngày, Stu ra buồng điện thoại công cộng để gọi cho Pam, quyến rũ, tán tỉnh cô bé. Stu không dùng di động gọi vì anh ta sợ Kelly, vợ của mình, sẽ lần ra chuyện tình vụng trộm này. Thế rồi ngày hôm ấy, ngày cuối cùng của buồng điện thoại công cộng cuối cùng của New York, Stu tiếp tục gọi cho Pam. Rồi điện thoại bỗng reo lên Stu nhấc lên. Bên kia là giọng một người đàn ông yêu cầu anh gọi điện cho Pam và Kelly thú nhận tội lỗi, nếu không, hắn sẽ bắn tỉa anh ngay lập tức. Có bao giờ bạn bước vào một trạm điện thoại công cộng bên đường và nhận ra rằng mình không thể bước ra được?</p>', 'Full', 1, 'single', 'completed', 15, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Radha Mitchell","avatar":""},{"name":"Katie Holmes","avatar":""},{"name":"Paula Jai Parker","avatar":""},{"name":"Arian Ash","avatar":""},{"name":"Tia Texada","avatar":""},{"name":"John Enos III","avatar":""},{"name":"Richard T. Jones","avatar":""},{"name":"Keith Nobbs","avatar":""},{"name":"Dell Yount","avatar":""},{"name":"James MacDonald","avatar":""},{"name":"Josh Pais","avatar":""},{"name":"Yorgo Constantine","avatar":""},{"name":"Colin Patrick Lynch","avatar":""},{"name":"Troy Gi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324530);
