INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-gia-noel-xau-tinh', 'Ông Già Noel Xấu Tính', 'Bad Santa', 'https://phimimg.com/upload/vod/20231123-1/43e4bcc8a40b69241ecf10f06c498ef8.jpg', 'https://phimimg.com/upload/vod/20231123-1/20a95f295804fe7297a39a186661d7ef.jpg', '<p>Một kẻ lừa đảo khốn khổ và đối tác của anh ta đóng giả ông già Noel và Người trợ giúp nhỏ của anh ta để cướp các cửa hàng bách hóa vào đêm Giáng sinh. Nhưng họ gặp rắc rối khi kẻ lừa đảo kết bạn với một đứa trẻ rắc rối.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Billy Bob Thornton","avatar":""},{"name":"Tony Cox","avatar":""},{"name":"Brett Kelly","avatar":""},{"name":"Bernie Mac","avatar":""},{"name":"John Ritter","avatar":""},{"name":"Lauren Graham","avatar":""},{"name":"Lauren Tom","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Cloris Leachman","avatar":""},{"name":"Lorna Scott","avatar":""},{"name":"Billy Gardell","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Kerry Rossall","avatar":""},{"name":"Curtis Taylor","avatar":""},{"name":"Ajay Naidu","avatar":""},{"name":"Harrison Bieker","avatar":""},{"name":"Dylan Charles","avatar":""},{"name":"Alexandra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324530);
