INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-gia-noel-xau-tinh', 'Ông Già Noel Xấu Tính', 'Bad Santa', 'ông già noel xấu tính bad santa billy bob thornton tony cox brett kelly bernie mac john ritter lauren graham lauren tom octavia spencer cloris leachman lorna scott billy gardell alex borstein kerry rossall curtis taylor ajay naidu harrison bieker dylan charles alexandra ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-mong-mo', 'Những Kẻ Mộng Mơ', 'The Dreamers', 'https://phimimg.com/upload/vod/20231120-1/ddaa7895c9a408f12917f5d4a02f78d3.jpg', 'https://phimimg.com/upload/vod/20231120-1/b19a9a4a4208727fe64b27b3fc1705b3.jpg', '<p>Cậu sinh viên trẻ Matthew (Michael Pitt) xuất thân từ một gia đình Mỹ nghèo nhưng say mê điện ảnh, cậu quyết định đến Paris học tiếng Pháp và được đắm chìm vào mọi thể loại điện ảnh trên thế giới. Matthew bị thu hút bởi hai anh em sinh đôi Theo (Louis Garrel) và Isabelle (Eva Green) bởi chất chơi, sành điệu của họ. Trong một cuộc biểu tình của giới sinh viên và văn nghệ sĩ chống lại quyết định loại một nhà làm phim khỏi Viện lưu trữ văn hóa, Matthew làm quen với hai người và dần dần bị cuốn vào mối quan hệ kỳ lạ làm thay đổi con người cậu. Từ đây, những giấc mơ hoang đường quyện vào nhau, thổn thức một cách trần trụi, hào nhoáng lẫn trong giả tạo, ngọt ngào xen giữa cay nghiệt. Họ đi từ giấc mơ này đến giấc mơ khác, mộng mị lang lang giữa không gian riêng ảo mộng bên cạnh thế giới thực đổ nát, sôi sục của một Paris hỗn loạn năm 1968.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Pitt","avatar":""},{"name":"Eva Green","avatar":""},{"name":"Louis Garrel","avatar":""},{"name":"Anna Chancellor","avatar":""},{"name":"Robin Renucci","avatar":""},{"name":"Jean-Pierre Kalfon","avatar":""},{"name":"Jean-Pierre Léaud","avatar":""},{"name":"Florian Cadiou","avatar":""},{"name":"Pierre Hancisse","avatar":""},{"name":"Valentin Merlet","avatar":""},{"name":"Lola Peploe","avatar":""},{"name":"Ingy Fillion","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
