INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rock-hoc-tro', 'Rock Học Trò', 'School of Rock', 'https://phimimg.com/upload/vod/20231119-1/7c36ace5bbb6878c44fb1cf8231447ab.jpg', 'https://phimimg.com/upload/vod/20231119-1/244605721e63ceabc51de09731aefd26.jpg', '<p>Bị ban nhạc sa thải, tay guitar kiêm giọng ca chính Dewey Finn đã nhận một công việc xa lạ với anh để kiếm sống, đó là làm giáo viên dạy lớp 4 tại một trường tư thục có kỷ luật nghiêm ngặt. Anh đã táo bạo biến các học sinh thành những rocker thực thụ, một kiểu &quot;Rock học trò&quot;.</p>', 'Full', 1, 'single', 'completed', 18, 2003, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Jack Black","avatar":""},{"name":"Joan Cusack","avatar":""},{"name":"Mike White","avatar":""},{"name":"Sarah Silverman","avatar":""},{"name":"Miranda Cosgrove","avatar":""},{"name":"Joey Gaydos Jr.","avatar":""},{"name":"Kevin Alexander Clark","avatar":""},{"name":"Rivkah Reyes","avatar":""},{"name":"Robert Tsai","avatar":""},{"name":"Maryam Hassan","avatar":""},{"name":"Aleisha Allen","avatar":""},{"name":"Caitlin Hale","avatar":""},{"name":"Brian Falduto","avatar":""},{"name":"Z Infante","avatar":""},{"name":"James Hosey","avatar":""},{"name":"Angelo Massagli","avatar":""},{"name":"Cole Hawkins","avatar":""},{"name":"Le","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324530);
