INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hop-dong-hon-nhan', 'Hợp Đồng Hôn Nhân', 'Intolerable Cruelty', 'https://phimimg.com/upload/vod/20231118-1/5e3814aa301351fc41abb8cd06a0b64c.jpg', 'https://phimimg.com/upload/vod/20231118-1/227647043b7de87a07d65df9686c9e92.jpg', '<p>Miles Massey (George Clooney) là một luật sư tên tuổi ở Los Angeles. Anh nổi tiếng với các vụ kiện tụng về hôn nhân gia đình, tranh chấp tài sản. Với tài ăn nói khéo léo lẫn trí thông minh của mình, Miles có thể đổi trắng thay đen, luôn mang lại thắng lợi cho thân chủ của mình trong các vụ tranh tụng trước tòa án. Một ngày nọ Miles Massey đón tiếp một vị khách hàng quan trọng. Đó là Rex Rexroth (Edward Herrmann), một tay kinh doanh bất động sản, đến nhờ Miles làm luật sư trong vụ ly dị với cô vợ xinh đẹp Marylin (Catherine Zeta-Jones).</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Edward Herrmann","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Billy Bob Thornton","avatar":""},{"name":"Stacey Travis","avatar":""},{"name":"Cedric the Entertainer","avatar":""},{"name":"Paul Adelstein","avatar":""},{"name":"Julia Duffy","avatar":""},{"name":"Jonathan Hadary","avatar":""},{"name":"Tom Aldredge","avatar":""},{"name":"Jack Kyle","avatar":""},{"name":"Irwin Keyes","avatar":""},{"name":"Judith Drake","avatar":""},{"name":"George Ives","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
