INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vet-cat', 'Vết Cắt', 'In the Cut', 'https://phimimg.com/upload/vod/20231109-1/75c803ecdf635067ecb284f3a077efce.jpg', 'https://phimimg.com/upload/vod/20231109-1/122b4f491c5972988524948cdfb2da0b.jpg', '<p>Sau vụ sát hại dã man một phụ nữ trẻ trong khu phố của mình, một giáo viên tiếng Anh sống ở thành phố New York — như thể để kiểm tra giới hạn an toàn của chính mình — đẩy mình vào một mối quan hệ tình dục mạo hiểm không tưởng với một thám tử cảnh sát.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Meg Ryan","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Nick Damici","avatar":""},{"name":"Sharrieff Pugh","avatar":""},{"name":"Heather Litteer","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Michael Nuccio","avatar":""},{"name":"Allison Nega","avatar":""},{"name":"Dominick Aries","avatar":""},{"name":"Susan Gardner","avatar":""},{"name":"Daniel T. Booth","avatar":""},{"name":"Yaani King Mondschein","avatar":""},{"name":"Frank Harts","avatar":""},{"name":"Sebastian Sozzi","avatar":""},{"name":"Zach Wegner","avatar":""},{"name":"Patric","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
