INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-cold-mountain', 'Thị Trấn Cold Mountain', 'Cold Mountain', 'https://phimimg.com/upload/vod/20231117-1/bba03201b953865b80e8b3ef9912c4b0.jpg', 'https://phimimg.com/upload/vod/20231117-1/4f7e25cfdafdf3c90cd5b1bda490e164.jpg', '<p>Trong câu chuyện kinh điển về tình yêu và sự tận tụy này lấy bối cảnh là Nội chiến Hoa Kỳ, một người lính miền Nam bị thương tên là W.P. Inman đào ngũ và bắt đầu cuộc hành trình đầy nguy hiểm trở về nhà ở Cold Mountain, North Carolina để đoàn tụ với người yêu của mình.
 Ada, người vợ trẻ mà anh đã bỏ lại để chăm sóc trang trại của họ, đã phải đấu tranh để giữ cho ngôi nhà của họ được nguyên vẹn với sự hỗ trợ của Ruby, một cô gái nghèo bí ẩn được một người hàng xóm tốt bụng gửi đến giúp.</p>', 'Full', 1, 'single', 'completed', 14, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jude Law","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Renée Zellweger","avatar":""},{"name":"Eileen Atkins","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Ray Winstone","avatar":""},{"name":"Kathy Baker","avatar":""},{"name":"James Gammon","avatar":""},{"name":"Charlie Hunnam","avatar":""},{"name":"Jack White","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"Jena Malone","avatar":""},{"name":"Melora W","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
