INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-bao-thu-1', 'Cô Dâu Báo Thù 1', 'Kill Bill: Vol. 1', 'https://phimimg.com/upload/vod/20231114-1/a052ddce66f4e54bc6387f5bf91be65d.jpg', 'https://phimimg.com/upload/vod/20231114-1/5a22793fb677c22c7d24401c67baed91.jpg', '<p>Nhân vật chính của bộ phim được gọi là &quot;Cô Dâu&quot; (Uma Thurman), là một thành viên của Tổ chức Ám Sát Vipe, dẫn đầu bởi Bill, người yêu của cô. Khi nhận ra mình mang thai đứa con của Bill, &quot;Cô Dâu&quot; đã quyết định rời bỏ cuộc sống của một kẻ ám sát, giết người. Cô đến Texas, gặp một người đàn ông trẻ, và quyết định sống cuộc sống mới. Nhưng vào ngày cưới, Bill đã xuất hiện cùng với 4 sát thủ còn lại giết hết tất cả mọi người. Nhưng họ đã sơ sót, &quot;Cô Dâu&quot; vẫn còn sống và chìm trong hôn mê suốt 4 năm trời. Tỉnh dậy, nhớ lại tất cả những gì đã xảy ra, đứa bé trong bụng không còn nữa. Đau đớn tột cùng, cô quyết định trả thù năm người đã phá hủy cuộc sống của cô và giết chết con cô. Và hành trình giết Bill bắt đầu...</p>', 'Full', 1, 'single', 'completed', 15, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Uma Thurman","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Vivica A. Fox","avatar":""},{"name":"Daryl Hannah","avatar":""},{"name":"David Carradine","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Julie Dreyfus","avatar":""},{"name":"Chiaki Kuriyama","avatar":""},{"name":"Sonny Chiba","avatar":""},{"name":"Gordon Liu Chia-hui","avatar":""},{"name":"Michael Parks","avatar":""},{"name":"Michael Bowen","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Kenji Ohba","avatar":""},{"name":"Yuki Kazamatsuri","avatar":""},{"name":"James Parks","avatar":""},{"name":"Sakichi Sato","avatar":""},{"name":"Jon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324530);
