INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-cupid-2003', 'Chuyện Tình Cupid', 'Why Me, Sweetie?!', 'https://phimimg.com/upload/vod/20231111-1/0a10b00154c667f4fff5c12908e1db73.jpg', 'https://phimimg.com/upload/vod/20231111-1/6356353ce37345e5f9caf731a8129bb3.jpg', '<p>Trong phim này, Louis Koo cố gắng tán tỉnh một sinh viên sân khấu điện ảnh Bắc Kinh (Cherry Ying), nhưng anh ta bị mất trí nhớ, và anh ta liên tục quên cô ấy là ai.</p>', 'Full', 1, 'single', 'completed', 14, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Cherrie Ying Choi-Yi","avatar":""},{"name":"Tats Lau Yee-Tat","avatar":""},{"name":"Sui Junbo","avatar":""},{"name":"Zhu Hong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
