INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-tinh-yeu-2003', 'Câu Chuyện Tình Yêu', 'Down with Love', 'https://phimimg.com/upload/vod/20231111-1/8dfa4bdc8c957067c3daee29a8fcbfc9.jpg', 'https://phimimg.com/upload/vod/20231111-1/efbec8be2e453fc7b092dfeda6450b64.jpg', '<p>Câu Chuyện Tình Yêu - Down with Love kể về cuộc cách mạng giới tính đầu tiên tại Mỹ năm 1960. Phim xoay quanh nhà báo Catcher Block. Anh đã thề rằng sẽ quyến rũ nhà văn Barbara Novak - người rao giảng rằng phụ nữ không cần đàn ông để làm cho họ hạnh phúc. Tuy nhiên, anh bắt đầu rơi vào tình yêu của Barbara Novak trong khi thực hiện âm mưu của mình.</p>', 'Full', 1, 'single', 'completed', 15, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Renée Zellweger","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Sarah Paulson","avatar":""},{"name":"David Hyde Pierce","avatar":""},{"name":"Rachel Dratch","avatar":""},{"name":"Jack Plotnick","avatar":""},{"name":"Tony Randall","avatar":""},{"name":"John Aylward","avatar":""},{"name":"Matt Ross","avatar":""},{"name":"Michael Ensign","avatar":""},{"name":"Timothy Omundson","avatar":""},{"name":"Jeri Ryan","avatar":""},{"name":"Ivana Miličević","avatar":""},{"name":"Melissa George","avatar":""},{"name":"Dorie Barton","avatar":""},{"name":"Laura Kightlinger","avatar":""},{"name":"Chris Par","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
