INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-hai-tac-bao-ve-vo-dien-lon-cuoi-cung', 'Vua Hải Tặc: Bảo vệ! Vở diễn lớn cuối cùng', 'One Piece: Mamore! Saigo no Dai Butai', 'https://phimimg.com/upload/vod/20231110-1/b9ea5e36087c4d6d3be88daaaa289628.jpg', 'https://phimimg.com/upload/vod/20231110-1/ca76c367690231c46579119aa9fb152b.jpg', '<p>Vua Hải Tặc: Bảo vệ! Vở diễn lớn cuối cùng là chương trình truyền hình đặc biệt của anime One Piece. Phim được phát sóng vào ngày 14 tháng 12 năm 2003 và sau tập 174 của anime. Bộ phim kể về Trung Úy Hải Quân Randolph - người đã mất gia đình vì Hải Tặc, đang dự định tổ chức một buổi biểu diễn cuối cùng trước khi về hưu. Thật không may cho ông vì bị một kẻ dưới quyền phản bội – Governor, đã lập ra một kế hoạch độc ác để bắt Randolph. Băng Mũ Rơm vô tình biết được kế hoạch đó nên đã tìm mọi cách để bảo vệ danh dự của ông và buổi biểu diễn cuối cùng này.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2003, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayumi Tanaka","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Issei Futamata","avatar":""},{"name":"Banjo Ginga","avatar":""},{"name":"Keiichi Sonobe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324530);
