INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bao-ve-kinh-thanh', 'Người Bảo Vệ Kinh Thánh', 'Bulletproof Monk', 'https://phimimg.com/upload/vod/20231108-1/ea108f21d8543f2cb18839639fcd71f0.jpg', 'https://phimimg.com/upload/vod/20231108-1/deec3fc87f96f208d1396117d10b9d16.jpg', '<p>Một bậc thầy kung fu Tây Tạng bí ẩn và bất tử, người đã dành 60 năm qua đi khắp thế giới để bảo vệ Scroll of the Ultimate cổ xưa, cố vấn cho một đứa trẻ đường phố ích kỷ trong những điều phức tạp của kung fu cổ xưa.</p>', 'Full', 1, 'single', 'completed', 13, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Jaime King","avatar":""},{"name":"Karel Roden","avatar":""},{"name":"Victoria Smurfit","avatar":""},{"name":"Mako","avatar":""},{"name":"K.C. Collins","avatar":""},{"name":"Rob Archer","avatar":""},{"name":"Marcus Jean Pirae","avatar":""},{"name":"Roger Yuan","avatar":""},{"name":"Sean Bell","avatar":""},{"name":"Kishaya Dudley","avatar":""},{"name":"Joel Harris","avatar":""},{"name":"Bayo Akinfemi","avatar":""},{"name":"Russell Yuen","avatar":""},{"name":"Mauricio Rodas","avatar":""},{"name":"Wong Ming-Kin","avatar":""},{"name":"Matt Birman","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324530);
