INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-ho-cho-thue', 'Căn Hộ Cho Thuê', 'Duplex', 'https://phimimg.com/upload/vod/20231107-1/a0e8b8d2dede02e05eb235e7cbc56a18.jpg', 'https://phimimg.com/upload/vod/20231107-1/c2ffd1583d94a637a3f62aae9544e437.jpg', '<p>Khi một cặp vợ chồng trẻ mua ngôi nhà mơ ước của mình, họ không biết bà già nhỏ bé ngọt ngào ở tầng trên sẽ khiến họ phải trải qua những gì!</p>', 'Full', 1, 'single', 'completed', 19, 2003, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"Eileen Essell","avatar":""},{"name":"Amber Valletta","avatar":""},{"name":"Justin Theroux","avatar":""},{"name":"Swoosie Kurtz","avatar":""},{"name":"Jackie Sandler","avatar":""},{"name":"James Remar","avatar":""},{"name":"Robert Wisdom","avatar":""},{"name":"Wallace Shawn","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Cheryl Klein","avatar":""},{"name":"Christopher Doyle","avatar":""},{"name":"Tim Maculan","avatar":""},{"name":"Christina Kirk","avatar":""},{"name":"John Hamburg","avatar":""},{"name":"Jenette Goldste","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324530);
