INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-lung-so-hai-2', 'Kẻ Săn Lùng Sợ Hãi 2', 'Jeepers Creepers 2', 'https://phimimg.com/upload/vod/20231114-1/e1fd69400b9cfd736681e30184c4fb16.jpg', 'https://phimimg.com/upload/vod/20231114-1/e1b4679f194dc6c099130775db57d5fe.jpg', '<p>Khi chiếc xe buýt của họ bị hỏng bên một con đường vắng vẻ, một nhóm vận động viên trung học phát hiện ra một đối thủ mà họ không thể đánh bại – và có thể không sống sót. Nhìn chằm chằm vào họ qua cửa sổ xe buýt của trường một cách thèm khát, The Creeper quay trở lại hết lần này đến lần khác. Nhưng khi các đồng đội phát hiện ra rằng nó chọn lọc đối tượng tấn công, nó sẽ kiểm tra khả năng gắn bó với nhau của họ – khi mối đe dọa vô độ cố gắng xé nát họ!</p>', 'Full', 1, 'single', 'completed', 15, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ray Wise","avatar":""},{"name":"Jonathan Breck","avatar":""},{"name":"Nicki Aycox","avatar":""},{"name":"Eric Nenninger","avatar":""},{"name":"Marieh Delfino","avatar":""},{"name":"Al Santos","avatar":""},{"name":"Tom Tarantini","avatar":""},{"name":"Josh Hammond","avatar":""},{"name":"Luke Edwards","avatar":""},{"name":"Garikayi Mutambirwa","avatar":""},{"name":"Thom Gossom Jr.","avatar":""},{"name":"Billy Aaron Brown","avatar":""},{"name":"Kasan Butcher","avatar":""},{"name":"Shaun Fleming","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Diane Delano","avatar":""},{"name":"Travis Schiffner","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324530);
