INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-dia-anh-hung', 'Thiên địa anh hùng', 'Warriors of Heaven and Earth', 'thiên địa anh hùng warriors of heaven and earth jiang wen kiichi nakai wang xueqi zhao wei bagen hasi tao ho linian lu deshun wang haibin li yeerjiang mahepushen chuangao hou zhou yun wei li yuming du harrison liu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nga-re-tu-than', 'Ngã Rẽ Tử Thần', 'Wrong Turn', 'https://phimimg.com/upload/vod/20231101-1/0bf9ce04f208fb17c3cb6298e722d6c9.jpg', 'https://phimimg.com/upload/vod/20231101-1/7f8ab75222661f3dfc831820d9f979a9.jpg', '<p>Đã từ nhiều năm nay, chính phủ rất thắc mắc về những vụ biến mất bất ngờ của những người khách du lịch, hầu hết tất cả bọn họ đều biến mất ở khu rừng miền Tây bang Virginia (West Virginia), nhưng thực ra họ đã bị giết bởi ba anh em đột biến gen khát máu, tàn ác và chuyên bắt cóc người ăn thịt, chúng không có tên, chỉ được biết là Three Finger, One Eye, Saw Tooth (Ba Ngón, Một Mắt và Răng Cưa). &nbsp;Một hôm nọ, có anh chàng tên là Chris Flynn đang trên đường đến nơi phỏng vấn việc làm, cũng đi ngang qua khu rừng Virginia này. Xe anh bị hư, anh tình cờ gặp được vài người thanh thiếu niên khác trạc tuổi mình, Jesse (Eliza Dushku), Carly (Emmanuelle Chriqui), Scott (Jeremy Sisto), Evan (Kevin Zegers), Francine (Lindy Booth) cũng cùng chung hoàn cảnh, nhưng xe họ không hư mà cán phải dây kẽm gai của ai đặt sẵn. Lúc này họ mới nhận ra rằng có một thứ gì đó đang săn họ và họ phải chiến đấu hay bỏ chạy vì mạng sống của mình.</p>', 'Full', 1, 'single', 'completed', 21, 2003, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Eliza Dushku","avatar":""},{"name":"Desmond Harrington","avatar":""},{"name":"Emmanuelle Chriqui","avatar":""},{"name":"Julian Richings","avatar":""},{"name":"Lindy Booth","avatar":""},{"name":"James Downing","avatar":""},{"name":"Jeremy Sisto","avatar":""},{"name":"Wayne Robson","avatar":""},{"name":"David Huband","avatar":""},{"name":"Kevin Zegers","avatar":""},{"name":"Yvonne Gaudry","avatar":""},{"name":"Garry Robbins","avatar":""},{"name":"Joel Harris","avatar":""},{"name":"Ted Clark","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
