INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-boi-mien-vien-tay', 'Cao Bồi Miền Viễn Tây', 'Open Range', 'https://phimimg.com/upload/vod/20231101-1/a0720bffa763ff6dc9e6ac9bedbc1500.jpg', 'https://phimimg.com/upload/vod/20231101-1/b61d977cc06672cd8634dc6b82332015.jpg', '<p>Phim xoay quanh 4 tay cao bồi từ bỏ quá khứ, sống cuộc đời lang bạt là Boss, Charlie, Mose và Buttons. Đang trên đường dẫn đàn gia súc, họ gặp phải trận mưa lớn khiến Mose, thành viên hiền lành nhất nhóm được cử quay về thị trấn để lấy thêm đồ dự trữ. Khi không thấy Mose quay lại, Boss và Charlie lần theo dấu vết của anh và phát hiện ra Mose đang bị giam giữ bởi tên chủ trại gian ác. Charlie vốn đã buông súng, quyết định trở lại và chỉ đạo cuộc chiến cao bồi thứ thiệt để cứu người anh em của mình. Mose được thả ra và đưa đến bác sĩ, chính nơi đây, họ đã gặp gỡ người phụ nữ quan trọng của cuộc đời. Nhưng kể từ sau trận chiến, cuộc sống yên ổn của 4 tay cao bồi không còn nữa...</p>', 'Full', 1, 'single', 'completed', 24, 2003, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kevin Costner","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Michael Jeter","avatar":""},{"name":"Diego Luna","avatar":""},{"name":"James Russo","avatar":""},{"name":"Abraham Benrubi","avatar":""},{"name":"Kim Coates","avatar":""},{"name":"Annette Bening","avatar":""},{"name":"Dean McDermott","avatar":""},{"name":"Herb Kohler","avatar":""},{"name":"Peter MacNeill","avatar":""},{"name":"Cliff Saunders","avatar":""},{"name":"Patricia Stutz","avatar":""},{"name":"Julian Richings","avatar":""},{"name":"Ian Tracey","avatar":""},{"name":"Rod Wilson","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324530);
