INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cao-boi-mien-vien-tay', 'Cao Bồi Miền Viễn Tây', 'Open Range', 'cao bồi miền viễn tây open range kevin costner robert duvall michael gambon michael jeter diego luna james russo abraham benrubi kim coates annette bening dean mcdermott herb kohler peter macneill cliff saunders patricia stutz julian richings ian tracey rod wilson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-song-ky-bi', 'Dòng Sông Kỳ Bí', 'Mystic River', 'https://phimimg.com/upload/vod/20231030-1/d8da2eade9ece5ad081c2bca977c58bc.jpg', 'https://phimimg.com/upload/vod/20231030-1/ba9ff98564df09dcbff0cc31a34256a7.jpg', '<p>Jimmy, Sean và Dave là ba đứa trẻ trạc tuổi, sống trong cùng khu phố. Chúng cùng viết tên trên một nền xi măng chưa kịp khô với ước muốn những cái tên sẽ tồn tại mãi mãi. Khi Dave chưa kịp viết hết tên mình, một chiếc xe cảnh sát tới bắt cậu bé đi. Buồn thay, bọn chúng không phải là những cảnh sát thật sự. Cậu bé phải trải qua bốn ngày kinh hoàng trong một căn hầm tối tăm cùng hai kẻ mặt người dạ thú. Sau đó, dù được cứu thoát nhưng Dave không bao giờ có thể vui tươi và hồn nhiên như trước được nữa. Tình bạn của ba đứa trẻ kết thúc từ đây. Họ vẫn sống gần nhau nhưng đường đời lại chia ba ngã rẽ tưởng không bao giờ hợp lại. 25 năm sau, một bi kịch lại xảy ra. Cô con gái Katie của Jimmy bị giết. Sự việc khủng khiếp này kéo ba người bạn cũ một lần nữa trở về “bên nhau”. Để rồi, họ nhận ra bóng ma quá khứ vẫn luôn đè nặng trên vai mỗi người...</p>', 'Full', 1, 'single', 'completed', 15, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Penn","avatar":""},{"name":"Tim Robbins","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"Laura Linney","avatar":""},{"name":"Kevin Chapman","avatar":""},{"name":"Tom Guiry","avatar":""},{"name":"Emmy Rossum","avatar":""},{"name":"Spencer Treat Clark","avatar":""},{"name":"Andrew Mackin","avatar":""},{"name":"Adam Nelson","avatar":""},{"name":"Robert Wahlberg","avatar":""},{"name":"Jenny O''Hara","avatar":""},{"name":"John Doman","avatar":""},{"name":"Cameron Bowen","avatar":""},{"name":"Jason Kelly","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324530);
