INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dong-song-ky-bi', 'Dòng Sông Kỳ Bí', 'Mystic River', 'dòng sông kỳ bí mystic river sean penn tim robbins kevin bacon laurence fishburne marcia gay harden laura linney kevin chapman tom guiry emmy rossum spencer treat clark andrew mackin adam nelson robert wahlberg jenny o''hara john doman cameron bowen jason kelly c ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ruot-duoi', 'Rượt Đuổi', 'The Rundown', 'https://phimimg.com/upload/vod/20231030-1/08dc1e5891b150e7cdb085d703cc38a2.jpg', 'https://phimimg.com/upload/vod/20231030-1/8ed5c6854c7d3b484a915031fb0dfe0e.jpg', '<p>Beck được một triệu phú thuê sang Amazon dẫn độ Travis, con trai của ông - một thanh niên đam mê những cuộc phiêu lưu mạo hiểm đã bỏ nhà ra đi trở về Mỹ. Beck lên đường sang Amazon, đến thị trấn El Dorado hẻo lánh giữa rừng già. Đây là trung tâm mỏ vàng dưới quyền cai trị của Hatcher. Hắn điều hành công việc khai khoáng, bóc lột sức lao động của người bản xứ nhưng không ai dám chống lại gã. Trong khi đang hỏi thăm tin tức thì Beck gặp được Travis và khống chế anh ta đưa ra phi trường về lại Mỹ. Trên đường đi, xe của Beck lao xuống vực, cả hai rơi vào tay thổ dân Amazon. Họ đã cùng nhau chống lại Hatcher, giải thoát cho các công nhân làm nô lệ trong mỏ vàng. Liệu Beck có nhận được số tiền thưởng? Số phận của Travis sẽ ra sao?</p>', 'Full', 1, 'single', 'completed', 16, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dwayne Johnson","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"Jon Gries","avatar":""},{"name":"William Lucking","avatar":""},{"name":"Ernie Reyes Jr.","avatar":""},{"name":"Stuart F. Wilson","avatar":""},{"name":"Dennis Keiffer","avatar":""},{"name":"Garrett Warren","avatar":""},{"name":"Toby Holguin","avatar":""},{"name":"Paul S. Power","avatar":""},{"name":"Stephen Bishop","avatar":""},{"name":"Chuck Norman","avatar":""},{"name":"Jamal Duff","avatar":""},{"name":"Jo","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
