INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-4-cuoc-dua-tu-than', 'Đảo Hải Tặc 4: Cuộc Đua Tử Thần', 'One Piece: Dead End Adventure', 'https://phimimg.com/upload/vod/20231030-1/8e4a089fd195361f2754b56cc4e7df6e.jpg', 'https://phimimg.com/upload/vod/20231030-1/9ffa2b27de79217b6528deb3ba7b7c64.jpg', '<p>Đảo Hải Tặc 4: Cuộc Đua Tử Thần – Nhóm Luffy có cuộc hành trính tới bến cảng Anabaru. Tại đây đang tổ chức một cuộc thi mà người chiến thắng sẽ có được một món tiền thưởng rất lớn nếu như giành vị trí quán quân. Nami vô cùng phấn khích và đã quyết định tham gia cuộc thi này.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2003, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayumi Tanaka","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Miki Sakai","avatar":""},{"name":"Tarō Ishida","avatar":""},{"name":"Jurota Kosugi","avatar":""},{"name":"Mitsuru Miyamoto","avatar":""},{"name":"Ichiro Nagai","avatar":""},{"name":"Eiji Takemoto","avatar":""},{"name":"Daisuke Gori","avatar":""},{"name":"Tetsu Inada","avatar":""},{"name":"Koji Haramaki","avatar":""},{"name":"Shuichi Ikeda","avatar":""},{"name":"Tak","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324530);
