INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-mu', 'Hiệp Sĩ Mù', 'Daredevil', 'https://phimimg.com/upload/vod/20231025-1/d41007995387c9bf90659a008fa26625.jpg', 'https://phimimg.com/upload/vod/20231025-1/4c0c91bc52b10238d70712203601ea22.jpg', '<p>Phim xây dựng dựa trên nhân vật nổi tiếng của Marvel, Matt Murdock, con trai một võ sĩ quyền Anh. Cha cậu trở thành nạn nhân của xã hội đen khi ông định đương đầu với chúng. Matt quyết tâm báo thù cho cha cho dù một tai nạn từ nhỏ đã cướp đi con mắt của cậu. Tuy nhiên, cái tai nạn ấy cũng mang đến cho cậu một khả năng ngoại cảm tuyệt vời, cậu có khả năng nhìn, nghe, cảm nhận hơn những người khác. Sau những năm tháng cực nhọc luyện tập võ nghệ cũng như đạt kết quả tốt trong trường luật, Matt trở thành luật sư vào ban ngày và một DareDevil vào ban đêm gieo bao nỗi kinh hoàng. Sau khi người yêu bị giết chết, Matt quyết định truy tìm Bulleyes để trả thù, và anh vô tình biết được bí mật về cái chết của người cha. Anh phải truy tìm ra tên trùm đầu sỏ đứng sau lưng những vụ cá cược quyền anh để đòi lại công lý cho cha mình.</p>', 'Full', 1, 'single', 'completed', 15, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Jennifer Garner","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Scott Terra","avatar":""},{"name":"Ellen Pompeo","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Leland Orser","avatar":""},{"name":"Lennie Loftin","avatar":""},{"name":"Erick Avari","avatar":""},{"name":"Derrick O''Connor","avatar":""},{"name":"Paul Ben-Victor","avatar":""},{"name":"David Keith","avatar":""},{"name":"Frankie J. Allison","avatar":""},{"name":"Joe J. Garcia","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324530);
