INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-italia', 'Phi Vụ Italia', 'The Italian Job', 'https://phimimg.com/upload/vod/20231025-1/d50de2a6591d8a28f4638d78aa578b70.jpg', 'https://phimimg.com/upload/vod/20231025-1/b0eddc3a5eb2598986d874f476b637e6.jpg', '<p>Kế hoạch là hoàn hảo, nó đã được thực hiện đến mức hoàn hảo và họ có một lối thoát rõ ràng. Yếu tố rủi ro duy nhất mà tâm trí tội phạm bậc thầy Charlie Croker không thể ngăn chặn đến từ một trong những thành viên của băng đảng, bao gồm người đàn ông bên trong Steve, thiên tài máy tính Lyle, tài xế Rob, chuyên gia về chất nổ &quot;Tai trái&quot; và kẻ phá hoại an toàn kỳ cựu John Bridger . Sau khi giáng một đòn đáng kinh ngạc trị giá hàng triệu đô la vào một cung điện Venetian được bảo vệ nghiêm ngặt, Charlie và đồng bọn bị sốc khi phát hiện ra rằng một trong số họ đã phản bội họ. Bây giờ không còn là về các chiến lợi phẩm mà là về sự trả thù. Sau đó, Stella xinh đẹp bước vào hiện trường, một chuyên gia bẻ khóa an toàn gia nhập Charlie và đồng bọn khi họ trở về California để tìm kiếm kẻ phản bội.</p>', 'Full', 1, 'single', 'completed', 21, 2003, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Edward Norton","avatar":""},{"name":"Jason Statham","avatar":""},{"name":"Seth Green","avatar":""},{"name":"Yasiin Bey","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Boris Lee Krutonog","avatar":""},{"name":"Franky G","avatar":""},{"name":"Gawtti","avatar":""},{"name":"Olek Krupa","avatar":""},{"name":"Melanie Jayne","avatar":""},{"name":"Kobra Devoux","avatar":""},{"name":"Oscar Nunez","avatar":""},{"name":"Fausto Callegarini","avatar":""},{"name":"Stefano Petronelli","avatar":""},{"name":"Fabio Scarpa","avatar":""},{"name":"Cris","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324530);
