INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ngam', 'Thế Giới Ngầm', 'Underworld', 'https://phimimg.com/upload/vod/20231024-1/77fefd7c26fa57b5f3d34e57f9ef61fc.jpg', 'https://phimimg.com/upload/vod/20231024-1/04adc72fe08af1cfc9909f2d35a3af92.jpg', '<p>Underworld là một bộ phim hành động kinh dị về bí mật giữa 2 dòng họ Vampires và Lycans. Câu chuyện chủ yếu xoay quanh Selene, một vampire được gọi là &quot;Death Dealer&quot;, hay gọi là thợ săn Lycans.Cô ấy bị quyến rũ bởi Michael Corvin - người bị bọn Lycans săn đuổi. Micheal bị Lycans cắn và anh sẽ biến trở thành Lycan, Selence đang cố gắng để không cho điều đó xảy ra…</p>', 'Full', 1, 'single', 'completed', 19, 2003, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Kate Beckinsale","avatar":""},{"name":"Scott Speedman","avatar":""},{"name":"Michael Sheen","avatar":""},{"name":"Shane Brolly","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Erwin Leder","avatar":""},{"name":"Sophia Myles","avatar":""},{"name":"Robbie Gee","avatar":""},{"name":"Wentworth Miller","avatar":""},{"name":"Kevin Grevioux","avatar":""},{"name":"Zita Görög","avatar":""},{"name":"Scott McElroy","avatar":""},{"name":"Richard Cetrone","avatar":""},{"name":"Mike Mukatis","avatar":""},{"name":"Dennis J. Kozeluh","avatar":""},{"name":"Todd Schneider","avatar":""},{"name":"Sándor Bolla","avatar":""},{"name":"H","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
