INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-nha-gau', 'Anh Em Nhà Gấu', 'Brother Bear', 'https://phimimg.com/upload/vod/20231024-1/d2c3e61c36695a108466086f9d59a8b9.jpg', 'https://phimimg.com/upload/vod/20231024-1/3e0a0c68593a0731f0845dd76740b2e3.jpg', '<p>Cách đây từ rất lâu, khi Trái Đất vừa mới thoát ra khỏi Kỉ Băng hà, có ba anh em nọ là thợ săn tại vùng đất là châu Mĩ ngày nay. Sau khi người anh cả Sitka (D. B. Sweeney) bị gấu giết chết, ngươi em út tính khí bốc đồng Kenai (Joaquin Phoenix) đã giết những con gấu để trả thù, nhưng cậu đã bị Những Linh Hồn Lớn biến thành một con gấu. Denahi (Jason Raize), người anh thứ hai, đã bắt gặp chú gấu này và với ý nghĩ rằng nó đã giết chết Kenai, anh đã truy đuổi nó để trả thù. Anh em săn đuổi nhau, và cơ hội sống sót duy nhất cho Kenai là phải kết bạn với kẻ thù truyền kiếp của mình là một chú gấu xám Bắc Mĩ con tên là Koda (Jeremy Suarez). Và trong hành trình đó, chính Koda đã cho Kenai thấy ý nghĩ thực sự của tình anh ...</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joaquin Phoenix","avatar":""},{"name":"Jeremy Suarez","avatar":""},{"name":"Jason Raize","avatar":""},{"name":"Rick Moranis","avatar":""},{"name":"Dave Thomas","avatar":""},{"name":"D.B. Sweeney","avatar":""},{"name":"Joan Copeland","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Harold Gould","avatar":""},{"name":"Paul Christie","avatar":""},{"name":"Danny Mastrogiorgio","avatar":""},{"name":"Estelle Harris","avatar":""},{"name":"Greg Proops","avatar":""},{"name":"Pauley Perrette","avatar":""},{"name":"Bumper Robinson","avatar":""},{"name":"Darko Cesar","avatar":""},{"name":"Angay","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a