INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoc-mat-mat-troi', 'Nước Mắt Mặt Trời', 'Tears of the Sun', 'https://phimimg.com/upload/vod/20231023-1/1fe13fa4df94c4bf9044078e68162650.jpg', 'https://phimimg.com/upload/vod/20231023-1/6000796132401f0ebd32f5e9abcfbff8.jpg', '<p>Bruce Willis vào vai đại uý hải quân Mỹ A.K. Waters và được phái đến Nigeria để giải cứu bác sĩ Lena Kendricks, một công dân nước Mỹ tình nguyện đi làm việc tại Nigeria. Nhưng khi Waters đến để giải cứu bác sĩ Kendricks vì Nigeria hiện tại đang gặp nhiều chuyển biến về chính trị; nhưng bác sĩ Kendricks từ chối quay trở lại Mỹ nếu không đem theo được những bệnh nhân của mình. Và để hoàn thành nhiệm vụ, Waters buộc phải dẫn theo một nhóm dân tị nạn trên đường đi đến biên giới Cameroon hòng thoát khỏi sự truy bắt của những tên nổi loạn...</p>', 'Full', 1, 'single', 'completed', 17, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Monica Bellucci","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Eamonn Walker","avatar":""},{"name":"Johnny Messner","avatar":""},{"name":"Nick Chinlund","avatar":""},{"name":"Tom Skerritt","avatar":""},{"name":"Akosua Busia","avatar":""},{"name":"Chad Smith","avatar":""},{"name":"Charles Ingram","avatar":""},{"name":"Paul Francis","avatar":""},{"name":"Malick Bowens","avatar":""},{"name":"Awaovieyi Agie","avatar":""},{"name":"Ida Onyango","avatar":""},{"name":"Benjamin Ochieng","avatar":""},{"name":"Kanayo Chiemelu","avatar":""},{"name":"Hadar Busia-Sing","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', 