INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-meo-doi-mu', 'Chú Mèo Đội Mũ', 'The Cat in the Hat', 'https://phimimg.com/upload/vod/20231022-1/73cf05eee3b4ca027e88bd2ae8b0416e.jpg', 'https://phimimg.com/upload/vod/20231022-1/345b9529a65c9d80e81e2bfbd858ff64.jpg', '<p>Trong một ngày mưa, khi mẹ của họ đi vắng, Conrad và Sally cùng chú cá cưng của họ được chú mèo đội mũ tinh nghịch đến thăm. Niềm vui nhanh chóng trở nên hỗn loạn và hai anh em phải tìm cách thoát khỏi con mèo điên loạn.</p>', 'Full', 1, 'single', 'completed', 14, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mike Myers","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Spencer Breslin","avatar":""},{"name":"Kelly Preston","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Amy Hill","avatar":""},{"name":"Sean Hayes","avatar":""},{"name":"Danielle C. Ryan","avatar":""},{"name":"Taylor Rice","avatar":""},{"name":"Brittany Oaks","avatar":""},{"name":"Talia-Lynn Prairie","avatar":""},{"name":"Dan Castellaneta","avatar":""},{"name":"Victor Brandt","avatar":""},{"name":"Daran Norris","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Clint Howard","avatar":""},{"name":"Paige Hurd","avatar":""},{"name":"Steven","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324530);
