INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-uc-ke-sat-nhan', 'Hồi Ức Kẻ Sát Nhân', 'Memories of Murder', 'https://phimimg.com/upload/vod/20231023-1/e3721123be1391ec4d227df4a880ac11.jpg', 'https://phimimg.com/upload/vod/20231023-1/b11259b01df26fd6d5b4e831437adaea.jpg', '<p>Bộ phim mở đầu bằng cảnh một cánh đồng lúa vàng – hình ảnh đặc trưng của thôn quê Hàn Quốc thập niên 80. Nhưng đằng sau cảnh yên bình ấy lại là một câu chuyện giật gân, đáng sợ. Người dân làng bỗng phát hiện ra thi thể bị xâm hại của một phụ nữ tại bờ sông. Khi cuộc điều tra của thám tử địa phương Park Doo Man (Song Kang Ho) vẫn đang đi vào bế tắc và dân làng còn chưa kịp định thần thì xác nạn nhân tiếp theo lại được tìm thấy. Sự việc đã gieo rắc một nỗi ám ảnh kinh hoàng tới những người dân trong toàn Hàn Quốc. Phía Seoul đã cử Seo Tae Yoon, một thám tử điều tra được đào tạo bài bản tới xử lý vụ việc. Tuy nhiên, càng tìm ra được nhiều dấu vết của thủ phạm, các vụ án giết người lại càng xảy ra nhiều hơn với mức độ đáng sợ hơn. Phía cảnh sát rơi vào bế tắc vì kẻ sát nhân luôn đi trước họ một bước...</p>', 'Full', 1, 'single', 'completed', 20, 2003, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Song Kang-ho","avatar":""},{"name":"Kim Sang-kyung","avatar":""},{"name":"Kim Roi-ha","avatar":""},{"name":"Song Jae-ho","avatar":""},{"name":"Byun Hee-bong","avatar":""},{"name":"Go Seo-hee","avatar":""},{"name":"Ryu Tae-ho","avatar":""},{"name":"Park No-shik","avatar":""},{"name":"Park Hae-il","avatar":""},{"name":"Jeon Mi-seon","avatar":""},{"name":"Seo Young-hwa","avatar":""},{"name":"Woo Go-na","avatar":""},{"name":"Choi Jong-ryul","avatar":""},{"name":"Yoo Seung-mok","avatar":""},{"name":"Shin Hyun-jong","avatar":""},{"name":"Jung In-sun","avatar":""},{"name":"Lee Jae-eung","avatar":""},{"name":"Kwon Byung-gil","avatar":""},{"name":"Park","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324530);
