INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-tuong-phat', 'Truy Tìm Tượng Phật', 'Ong-Bak', 'https://phimimg.com/upload/vod/20231023-1/3d93b2b137d711bd83941085fbea4f7d.jpg', 'https://phimimg.com/upload/vod/20231023-1/e3b018fa38779341cd6dc3a253db2f32.jpg', '<p>Ting, một chàng trai tỉnh lẻ, tình nguyện lên thành phố tìm lại đầu pho tượng phật thiêng liêng bị đám tội phạm cướp đi. Sự giúp đỡ (vô dụng) của gã đồng hương đẩy Ting vào những cuộc đấu bất hợp pháp.Với bản tính chất phác, Ting lao vào những cuộc đấu hòng tìm lại hành trang đã mất cùng mong mỏi tìm lại được cổ vật thiêng mà cả làng đang ngóng chờ.Phim đánh dấu sự xuất hiện của ngôi sao hành động Tony Jaa. Để chuẩn bị cho phim, anh đã khổ luyện 4 năm môn Muay Boran, nguyên gốc của Muay Thái hiện đại.Trong suốt quá trình quay phim, Tony Jaa không sử dụng diễn viên đóng thế. Những cảnh giao đấu trong phim cũng không hề sử dụng kỹ xảo hay các thiết bị hỗ trợ nào.</p>', 'Full', 1, 'single', 'completed', 21, 2003, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Tony Jaa","avatar":""},{"name":"Petchtai Wongkamlao","avatar":""},{"name":"Patrarin Punyanutatam","avatar":""},{"name":"Suchao Pongwilai","avatar":""},{"name":"Choomporn Theppitak","avatar":""},{"name":"Cheathavuth Watcharakhun","avatar":""},{"name":"Wannakit Sirioput","avatar":""},{"name":"Rungrawee Barijindakul","avatar":""},{"name":"Chatthapong Phantana-Angkul","avatar":""},{"name":"Nudhapol Asavabhakhin","avatar":""},{"name":"Pornpimol Chookanthong","avatar":""},{"name":"Udom Songsaeng","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6