INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-dao-cuoi-cung', 'Võ Sĩ Đạo Cuối Cùng', 'The Last Samurai', 'https://phimimg.com/upload/vod/20231022-1/6b7aefdba7251e14954941ab32b317f8.jpg', 'https://phimimg.com/upload/vod/20231022-1/716c4b78a5ce577c8f155f78098619d2.jpg', '<p>Bối cảnh đặt vào những năm 1870, film có tính chất sự thi này miêu tả sự bắt đầu hiện đại hóa của Nhật Bản, một đất nước có quá khứ là một xã hội phong kiến, là biểu tượng của sự trừ tiệt đời sống của Samurai. Chúng ta nhìn thấy tất cả những việc này xảy ra từ một cái nhìn của một người ghiền rượu từng là cựu chiến binh mài gọt láng bóng những khẩu súng Winchester. Đại Úy Woodrow Algren, người đến Nhật Bản để huấn luyện các quân lính của Hoàng Đế, Meiji, một phần của sự ly khai từ truyền thống lâu đời dựa vào những chiến binh samurai để bảo vệ lãnh thổ, như một quân đội mới của Hoàng Đế để thay thế những chiến binh samurai. Khi Algren bị thương trong một trân đấu và bị bắt, anh ta đã học được danh ...</p>', 'Full', 1, 'single', 'completed', 16, 2003, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Ken Watanabe","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Tony Goldwyn","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Koyuki","avatar":""},{"name":"Shin Koyamada","avatar":""},{"name":"Billy Connolly","avatar":""},{"name":"Togo Igawa","avatar":""},{"name":"Shichinosuke Nakamura","avatar":""},{"name":"Masato Harada","avatar":""},{"name":"William Atherton","avatar":""},{"name":"Chad Lindberg","avatar":""},{"name":"Scott Wilson","avatar":""},{"name":"Ray Godshall Sr.","avatar":""},{"name":"Masashi Odate","avatar":""},{"name":"John Koyama","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324530);
