INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ga-trai-hu-2', 'Những Gã Trai Hư 2', 'Bad Boys II', 'https://phimimg.com/upload/vod/20231023-1/09e98d0a0181611b6187b43f4d98586c.jpg', 'https://phimimg.com/upload/vod/20231023-1/49a830796a741eeb7a21e878bd0e5f7e.jpg', '<p>Marcus và Mike vẫn tiếp tục những trận cãi vã bất đồng với nhau. Marcus đề nghị xin chuyển công tác để không phải gặp Mike. Tuy nhiên, một lần nữa họ lại buộc phải sát cánh với nhau trong một phi vụ ngăn chặn một lượng thuốc lắc khổng lồ được tuồn vào thành phố...</p>', 'Full', 1, 'single', 'completed', 14, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Martin Lawrence","avatar":""},{"name":"Gabrielle Union","avatar":""},{"name":"Jordi Mollà","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Theresa Randle","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Jon Seda","avatar":""},{"name":"Yul Vazquez","avatar":""},{"name":"Jason Manuel Olazabal","avatar":""},{"name":"Otto Sanchez","avatar":""},{"name":"Henry Rollins","avatar":""},{"name":"Antoni Corone","avatar":""},{"name":"Gary Nickens","avatar":""},{"name":"Rey Hernandez","avatar":""},{"name":"Charlie John","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324531);
