INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-tran-cuoc-cach-mang', 'Ma Trận: Cuộc Cách Mạng', 'The Matrix Revolutions', 'https://phimimg.com/upload/vod/20231019-1/1d138bca905766a1cead66938236abf6.jpg', 'https://phimimg.com/upload/vod/20231019-1/1adddafd99749bc4ab307db30fc51bd4.jpg', '<p>Cư dân thành phố Zion chuẩn bị cho cuộc bảo vệ thành phố khỏi làn sóng tấn công của các cỗ máy. Trong khi đó, Neo bị mắc kẹt ở khoảng giữa &quot;thế giới thực&quot; và ma trận. Còn đặc vụ Smith lại đang có một toan tính có thể tiêu diệt cả hai phe máy móc lẫn con người.</p>', 'Full', 1, 'single', 'completed', 12, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Jada Pinkett Smith","avatar":""},{"name":"Mary Alice","avatar":""},{"name":"Harold Perrineau","avatar":""},{"name":"Collin Chou","avatar":""},{"name":"Harry Lennix","avatar":""},{"name":"Ian Bliss","avatar":""},{"name":"Lambert Wilson","avatar":""},{"name":"Bruce Spence","avatar":""},{"name":"Monica Bellucci","avatar":""},{"name":"Nona Gaye","avatar":""},{"name":"Anthony Zerbe","avatar":""},{"name":"Tanveer K. Atwal","avatar":""},{"name":"Helmut Bak","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324531);
