INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-tran-tai-lap', 'Ma Trận: Tái Lập', 'The Matrix Reloaded', 'https://phimimg.com/upload/vod/20231021-1/8da0be4716d76efb6324e76575a0d5ef.jpg', 'https://phimimg.com/upload/vod/20231021-1/9d403f94f073c97bb84ea1d62b8dda88.jpg', '<p>6 tháng sau sự kiện ở phần 1, Neo được coi là cứu tinh mới của loài người. Trước nguy cơ bị hàng nghìn cỗ máy săn lùng tấn công vào thành phố Zion, bộ ba Neo, Morpheus, Trinity phải đi tìm lời khuyên từ Nhà tiên tri. Trong khi đó, đặc vụ Smith lại trở nên mạnh hơn bao giờ khi hắn có khả năng nhân số lượng bản thể lên nhiều lần.</p>', 'Full', 1, 'single', 'completed', 15, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Jada Pinkett Smith","avatar":""},{"name":"Gloria Foster","avatar":""},{"name":"Harold Perrineau","avatar":""},{"name":"Monica Bellucci","avatar":""},{"name":"Harry Lennix","avatar":""},{"name":"Lambert Wilson","avatar":""},{"name":"Randall Duk Kim","avatar":""},{"name":"Nona Gaye","avatar":""},{"name":"Anthony Zerbe","avatar":""},{"name":"Daniel Bernhardt","avatar":""},{"name":"Helmut Bakaitis","avatar":""},{"name":"David Kilde","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324531);
