INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-khong-moi-2003', 'Khách Không Mời', 'The Uninvited', 'https://phimimg.com/upload/vod/20230929-1/d43adc4fd92cb79f1764c69f1778fa42.jpg', 'https://phimimg.com/upload/vod/20230929-1/25cfb2d91e6cd0c24e4386aa5f009889.jpg', '<p>Jung Won (Park Shin Yang thủ vai) là một nhà thiết kế nội thất 
đang chuẩn bị kết hôn với vị hôn thê của mình. Trong một lần ngủ quên 
khi ngồi tàu điện ngầm về nhà, ở trạm cuối, anh tỉnh lại thì phát hiện 
bênh cạnh có hai cô gái đang ngồi dựa vào nhau. Anh không đánh thức các 
cô gái mà tự mình rời đi. Ngày hôm sau, Jung Won xem tin tức mới biết, 
thì ra hai cô gái ngày hôm qua đã chết trong toa tàu. Jung Won cảm thấy 
vô cùng áy náy. Một ngày nọ, anh gặp được Yeon (Jun Ji Hyun thủ vai), là
 một cô gái có chứng thèm ngủ. Sau một lần hôn mê tỉnh dậy, Yeon phát 
hiện mình có mắt âm dương, có thể thấy được mọi hồn ma. Jung Won như thể
 gặp được cứu tinh, anh hy vọng Yeon có thể giúp mình tìm hiểu rõ câu 
chuyện về hồn ma hai cô gái.</p><p><br/></p><p><br/></p>', 'Full', 1, 'single', 'completed', 22, 2003, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park Shin-yang","avatar":""},{"name":"Jun Ji-hyun","avatar":""},{"name":"Yoo Sun","avatar":""},{"name":"Lee Joo-sil","avatar":""},{"name":"Lee Seok-jun","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324531);
