INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anna-va-vo-lam', 'Anna Và Võ Lâm', 'Anna In Kungfu Land', 'null', 'https://phimimg.com/upload/vod/20231012-1/49fffd311d1c9af66b94184473a749a1.jpg', '<p>Miriam Yeung vào vai một người mang dòng máu lai Trung Quốc đại diện cho cha cô (một nhà sư Thiếu Lâm đã đào thoát sang Nhật Bản sau khi yêu một người Nhật) tại một giải đấu võ thuật.&nbsp; Những gì cô ấy thực sự muốn là trải nghiệm mối tình đầu (với Ekin Cheng, một giám đốc tiếp thị) và trở thành một ngôi sao điện ảnh.&nbsp; Cả hai điều này đều được hoàn thành trong thời gian cô ở Hồng Kông.</p>', 'Full', 1, 'single', 'completed', 16, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Miriam Yeung","avatar":""},{"name":"Ekin Cheng","avatar":""},{"name":"You-Nam Wong","avatar":""},{"name":"Denise Ho","avatar":""},{"name":"Yasuaki Kurata","avatar":""},{"name":"Chloe Chiu","avatar":""},{"name":"Shi Xiaohu","avatar":""},{"name":"Poon Lung-Kwan","avatar":""},{"name":"Lee Kwan-Lung","avatar":""},{"name":"Cheung Tat-Ming","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324531);
