INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anna-va-vo-lam', 'Anna Và Võ Lâm', 'Anna In Kungfu Land', 'anna và võ lâm anna in kungfu land miriam yeung ekin cheng you-nam wong denise ho yasuaki kurata chloe chiu shi xiaohu poon lung-kwan lee kwan-lung cheung tat-ming ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-chung-thiet-kim-cuong', 'Tuyệt Chủng Thiết Kim Cương', 'The Spy Dad', 'https://phimimg.com/upload/vod/20231010-1/1a6c275811c1961029f2b5df6c5d186a.jpg', 'https://phimimg.com/upload/vod/20231010-1/87446c7011d0ccb2bc110ef24ce788ff.jpg', '<p>Tại Hồng Kông, một tổ chức khủng bố có kế hoạch tống tiền chính phủ thế giới với sự trợ giúp của hai căn bệnh chết người mà một nhà khoa học ngốc nghếch đã tạo ra. Hai đặc vụ Interpol đã đến để ngăn chặn âm mưu thống trị thế giới độc ác của họ, nhưng một trong số họ đã trở thành nạn nhân của một trong những căn bệnh và lang thang hành động như một đứa trẻ sáu tuổi. Anh ta vô tâm bước vào biệt thự của một ngôi sao phim hành động bị bắt nạt, và ngôi sao Jones Bon, buộc phải trông trẻ cho anh ta trong khi giải quyết các vấn đề liên quan đến người vợ đã ly hôn và hai cô con gái của anh ta. Chỉ một khoảng thời gian ngắn trôi qua khi Jones, mặc dù chú ý nhiều hơn đến việc giải quyết hoàn cảnh gia đình, nhưng lại thấy mình đang chiến đấu với bọn khủng bố.</p>', 'Full', 1, 'single', 'completed', 18, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Candice Yu","avatar":""},{"name":"Gillian Chung","avatar":""},{"name":"Jordan Chan","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Teresa Mo","avatar":""},{"name":"Eric Kot Man-Fai","avatar":""},{"name":"Elvis Tsui","avatar":""},{"name":"Edison Chen","avatar":""},{"name":"Jim Chim Sui-Man","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324531);
