INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuyet-chung-thiet-kim-cuong', 'Tuyệt Chủng Thiết Kim Cương', 'The Spy Dad', 'tuyệt chủng thiết kim cương the spy dad tony leung ka-fai candice yu gillian chung jordan chan chapman to teresa mo eric kot man-fai elvis tsui edison chen jim chim sui-man ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-thap-nuong', 'Đỗ Thập Nương', 'Miss Du Shi Niang', 'null', 'https://phimimg.com/upload/vod/20231010-1/0e1c7d358e4c3692138ca5579154bab5.jpg', '<p>Du Shiniang, một người đẹp tuyệt vời thuộc sở hữu của một nữ hầu sành điệu, Yecha. Shiniang mịn màng và bóng bẩy, được rất nhiều người đàn ông ngưỡng mộ nhưng cô lại kiêu hãnh như một quả mận tuyết, khao khát gặp được một người đàn ông đích thực và trở thành một người phụ nữ đức hạnh. Sau nhiều năm tìm kiếm trong số những người đàn ông đến tìm cô, Shiniang cuối cùng cũng gặp được Li Jia, một người đàn ông đẹp trai và giản dị. Shiniang cam kết kết hôn với anh ta và chơi một trò lừa nhỏ để giải thoát cô khỏi Yecha với sự giúp đỡ của Li Jia. Để kiểm tra xem người đàn ông có chung thủy hay không, Thị Nương thiết kế một thử thách nhỏ. Li Jia vô tình biết được ý định của cô và hành động như một quý ông. Cuối cùng, Shiniang rất vui mừng khi thấy mình đã vượt qua bài kiểm tra và vui vẻ về nhà cùng Li Jia.</p>', 'Full', 1, 'single', 'completed', 19, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Michelle Reis","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Lydia Shum Tin-Ha","avatar":""},{"name":"Clifton Ko Chi-Sum","avatar":""},{"name":"Anson Leung Chun-Yat","avatar":""},{"name":"Suet-Fei Chiu","avatar":""},{"name":"Chan Ka-Yee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324531);
