INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-anh-hung', 'Đại Anh Hùng', 'Running On Karma', 'https://phimimg.com/upload/vod/20231009-1/e8d026db31339626dbd19d0d6548b670.jpg', 'https://phimimg.com/upload/vod/20231009-1/24baf834e25e1d92399cb3633e9fc3d7.jpg', '<p>Một nhà sư trở thành vận động viên thể hình, với năng khiếu nhìn thấu cuộc sống của mọi người, kết bạn với một nữ cảnh sát và sử dụng năng khiếu của mình để thay đổi sức mạnh của Nghiệp báo và số phận của cô ấy.</p>', 'Full', 1, 'single', 'completed', 19, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Cecilia Cheung","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Karen Tong","avatar":""},{"name":"Wong Chun","avatar":""},{"name":"Jimmy Wong Wa-Wo","avatar":""},{"name":"Hon Kwok-Choi","avatar":""},{"name":"Yuen Bun","avatar":""},{"name":"Yu Wen-Zhong","avatar":""},{"name":"Hou Lian-Sheng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324531);
