INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luyen-tinh-goi-canh', 'Luyến Tình Gối Cánh', 'Good Times, Bed Times', 'https://phimimg.com/upload/vod/20231008-1/ecb673c5388dbafcb603451674b98989.jpg', 'https://phimimg.com/upload/vod/20231008-1/4183b984ec204a8328f3050047926364.jpg', '<p>Đây là câu chuyện về Carrie (Sammi Cheng), người đóng vai một phóng viên báo lá cải đang viết câu chuyện về cảnh sát Paul Ko (Louis Koo). Xung quanh có tin đồn rằng anh ta bất lực và Carrie đang tìm kiếm sự thật. Tất nhiên, từ đó bạn sẽ xem liệu họ có kết nối được không. Ngoài ra còn có Raymond (Lau Ching Wan) trong vai người yêu cũ của Carrie, một thẩm phán và Charlene Choi có vẻ ngoài rất trẻ, người đóng vai Tabbie, người muốn sống cùng Raymond. Trong một đoạn dạo đầu nhỏ nhưng vui nhộn, Sandra Ng luôn tuyệt vời vào vai Bobo.</p>', 'Full', 1, 'single', 'completed', 19, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Lau Ching-wan","avatar":""},{"name":"Sammi Cheng","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Sandra Ng Kwun-Yu","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Jim Chim Sui-Man","avatar":""},{"name":"Lau Yee Tat","avatar":""},{"name":"Lee Lik-Chi","avatar":""},{"name":"Lam Suet","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324531);
