INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-co-gap-ke-thu', 'Tình Cờ Gặp Kẻ Thù', 'Looking For Mister Perfect', 'https://phimimg.com/upload/vod/20231006-1/d6836c393b68a21d47becfde9d2503e7.webp', 'https://phimimg.com/upload/vod/20231006-1/a63028333f724fdef53af6d58fa50db6.jpg', '<p>Một nữ cảnh sát luôn gặp xui xẻo nhất trong tình yêu. Trong chuyến đi đến Malaysia, cuối cùng cô cũng gặp được người đàn ông trong mơ của mình. Tuy nhiên, Người đàn ông hoàn hảo của cô ấy có thể không phải là tất cả những gì anh ấy thể hiện.</p>', 'Full', 1, 'single', 'completed', 31, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Shu Qi","avatar":""},{"name":"Andy On","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Ruby Wong Cheuk-Ling","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Raymond Wong Ho-yin","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"David Wu","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Isabel Chan Yat-Ning","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324531);
