INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-co-gap-ke-thu', 'Tình Cờ Gặp Kẻ Thù', 'Looking For Mister Perfect', 'tình cờ gặp kẻ thù looking for mister perfect shu qi andy on simon yam ruby wong cheuk-ling lam suet raymond wong ho-yin hui siu-hung david wu chapman to isabel chan yat-ning ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nho-mai-cuoc-tinh', 'Nhớ Mãi Cuộc Tình', 'Lost In Time', 'https://phimimg.com/upload/vod/20231006-1/9a2be6c4e758d5f922c2945b2a09b990.jpg', 'https://phimimg.com/upload/vod/20231006-1/dab6b038f77bdea76ed38a1d88dc4496.jpg', '<p>Sau cái chết đau thương của người chồng sắp cưới, Tiểu Tuệ nén chịu tất cả thay anh tiếp tục nghề lái xe bus với bao gian nan vất vả, còn chăm sóc cả đứa con riêng của anh với người vợ trước. Một bộ phim tình cảm xúc động, rất tuyệt vời của Trương Bách Chi kể từ bộ phim Tinh Nguyện.&nbsp; Xe buýt nhỏ lái xe, Ah Man (Louis Koo) chết trong một tai nạn trong quá trình chuyển trên xe buýt nhỏ của mình có số giấy phép là DY1314. Ảnh hưởng bởi những tin tức xấu, Siu Wai (Cecilia Cheung), Ah Man của vợ, biết cô ấy có để thực hiện, đặc biệt là khi có Lok Lok, con trai của Man Ah và người vợ cũ của mình. Đang cố gắng để kiếm sống cho Lok Lok, Siu Wai sửa chữa xe buýt nhỏ và trở thành một trình điều khiển bản thân mình. Cô phải đối mặt với nhiều khó khăn như là một trình điều khiển xe buýt nhỏ, nhưng Đại Fai (Lau Ching Wan) giúp cô khắc phục vấn đề này.</p>', 'Full', 1, 'single', 'completed', 19, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Cecilia Cheung","avatar":""},{"name":"Daichi Harashima","avatar":""},{"name":"Lau Ching-wan","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Pau Hei-Ching","avatar":""},{"name":"Elena Kong Mei-Yee","avatar":""},{"name":"Johnny Lu","avatar":""},{"name":"Edmond So","avatar":""},{"name":"Michael Chan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324531);
