INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nho-mai-cuoc-tinh', 'Nhớ Mãi Cuộc Tình', 'Lost In Time', 'nhớ mãi cuộc tình lost in time cecilia cheung daichi harashima lau ching-wan louis koo paul chun pau hei-ching elena kong mei-yee johnny lu edmond so michael chan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-cua-benh-sars', 'Cuộc Sống Của Bệnh SARS', 'City of SARS', 'https://phimimg.com/upload/vod/20231006-1/33b16380bff7bc857fffd9e0009588eb.webp', 'https://phimimg.com/upload/vod/20231006-1/01344f9995d2fffed2e2a871e9e497bc.jpg', '<p>Câu chuyện diễn ra trong đợt bùng phát dịch SARS, với tư cách là một y tá, Lin Weihao (do Yang Christine thủ vai) đã chống lại áp lực to lớn và kiên trì chiến đấu ở tiền tuyến. Đối lập hoàn toàn với Lin Weihao là Chen Junhao (do Tam Yaowen thủ vai), một bác sĩ, mặc dù mặc áo khoác trắng nhưng khi dịch bệnh bùng phát, suy nghĩ đầu tiên của anh là trốn thoát, nhưng dần dần, Chen Junhao bị thu hút bởi Lin Weihao Cảm động trước việc mình đã làm, anh cảm thấy xấu hổ và quyết định gánh vác trách nhiệm của mình.<br/>Lan Xiong (Eric Tsang) là một người mới nổi giàu có, nhưng em gái anh lại yêu một chủ hiệu thuốc vô danh (Qian Jiale). Lan Xiong cố gắng hết sức để chia cắt hai người, nhưng sau dịch SARS, Lan Xiong khi doanh nghiệp phá sản và mọi thứ đã mất, chính ông chủ hiệu thuốc đã ra tay giúp đỡ bất chấp mối hận thù trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 22, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Eric Tsang","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Kristy Yang","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Felix Wong","avatar":""},{"name":"Jerry Lamb Hiu-Fung","avatar":""},{"name":"Serena Po","avatar":""},{"name":"Edwin Siu","avatar":""},{"name":"Amanda Lee","avatar":""},{"name":"Gabriel Harrison","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324531);
