INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-bach-sam-lam', 'Hắc Bạch Sâm Lâm', 'Colour Of The Truth', 'https://phimimg.com/upload/vod/20231006-1/1c6dd98245966bf4e58fe5e692dd4111.jpg', 'https://phimimg.com/upload/vod/20231006-1/b78cbdf1c4a07f2269c0bffa62397d21.jpg', '<p>Một người đàn ông trở thành cảnh sát để hạ gục viên giám đốc cảnh sát có thể đã giết cha anh ta và của một ông trùm Hội Tam Hoàng đầy thù hận.</p>', 'Full', 1, 'single', 'completed', 22, 2003, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Anthony Wong","avatar":""},{"name":"Raymond Wong Ho-yin","avatar":""},{"name":"Patrick Tse Yin","avatar":""},{"name":"Jordan Chan","avatar":""},{"name":"Gillian Chung","avatar":""},{"name":"Francis Ng","avatar":""},{"name":"Lau Ching-wan","avatar":""},{"name":"Pinky Cheung","avatar":""},{"name":"Terence Yin","avatar":""},{"name":"Winnie Leung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324531);
