INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-o-nhuc-ho-cho', 'Nỗi Ô Nhục Họ Cho', 'Untold Scandal', 'https://phimimg.com/upload/vod/20231002-1/f6020460dedf44bc5b836ceb1df07a24.jpg', 'https://phimimg.com/upload/vod/20231002-1/c4af4e14cf75cff73d45ba535f6f98f0.jpg', '<p>Cho Won là một gã sở khanh mang vỏ bọc của một thư sinh, còn phu nhân Cho là chị họ của hắn, cũng là vợ cả một quan lớn trong triều. Để được ngủ với phu nhân Cho, Cho Won cược rằng sẽ có thể quyến rũ được Jung, một góa phụ còn trinh, nếu thất bại hắn sẽ phải đi tu. Tuy nhiên, Cho Won không ngờ rằng hắn thực sự phải lòng con mồi của mình, trong khi chính phu nhân Cho lại ngầm có tình cảm với hắn từ lâu</p>', 'Full', 1, 'single', 'completed', 17, 2003, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Bae Yong-jun","avatar":""},{"name":"Lee Mi-sook","avatar":""},{"name":"Jeon Do-yeon","avatar":""},{"name":"Jo Hyun-jae","avatar":""},{"name":"Lee So-yeon","avatar":""},{"name":"Jeon Yang-ja","avatar":""},{"name":"Na Han-il","avatar":""},{"name":"Lee Mi-Ji","avatar":""},{"name":"Choi Seong-min","avatar":""},{"name":"Han Yi-bin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324531);
