INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-carmen', 'Nàng Carmen', 'Carmen', 'https://phimimg.com/upload/vod/20230922-1/c0c43d925cc25bac9d99b1a5b4216a8c.jpg', 'https://phimimg.com/upload/vod/20230922-1/e91929904ee466068b38e363d934185f.jpg', '<p>Trong tác phẩm chuyển thể từ vở opera cổ điển của đạo diễn Vicente Aranda, một nhà văn người Pháp đã ghi lại sức mạnh quyến rũ của cô gái xinh đẹp Gypsy Carmen, người đã quyến rũ một người lính trẻ, đánh thức niềm đam mê của anh ta nhưng cuối cùng lại dẫn đến bi kịch. Jose bị ám ảnh bởi Carmen và thấy mình không thể kiểm soát được sự ghen tuông của mình, điều này buộc anh phải đưa ra một quyết định chết người trong câu chuyện nảy lửa về tình yêu và sự phản bội này.</p>', 'Full', 1, 'single', 'completed', 26, 2003, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Paz Vega","avatar":""},{"name":"Leonardo Sbaraglia","avatar":""},{"name":"Antonio Dechent","avatar":""},{"name":"Joan Crosas","avatar":""},{"name":"Jay Benedict","avatar":""},{"name":"Joe Mackay","avatar":""},{"name":"Josep Linuesa","avatar":""},{"name":"María Botto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324531);
