INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-xua-yeu-dau', 'Ngày Xưa Yêu Dấu', 'The Classic', 'https://phimimg.com/upload/vod/20230919-1/ec632c094589852fcdcade8411af5f7b.jpg', 'https://phimimg.com/upload/vod/20230919-1/9e707d1c201f1a0cc3a8c08390e262fc.jpg', '<p><span style="font-family: ">Ngày xưa yêu dấu (2003), The classic Ji Hye và Soo Kyoung là hai người bạn học cùng một trường đại học và cùng phải lòng Sang Min, một người bạn trong câu lạc bộ kịch của họ. Câu chuyện càng trở nên kịch tính hơn khi mà Soo Kyoung lại nhờ Ji Hye viết thư tình cho Sang Min. Ji Hye đã viết lên những dùng cảm xúc chân thật của bản thân nhưng lại kí tên bạn mình. Cảm động bởi những lá thư, Sang Min bắt đầu bị thu hút bởi Soo Kyoung. Nhưng Ji Hae lại cảm thấy khó chịu, thậm chí là tự trách mình, cố tránh mặt cậu ấy. Và rồi là sự trùng hợp ngẫu nhiên hay do số phận đưa đẩy, cô đón nhận tình yêu của Sang Min. Ji Hye sống cùng mẹ từ nhỏ, khi người bố đã đột ngột qua đời. Mẹ cô đã đi du lịch nước ngoài để khuây khỏa nỗi cô đơn trong lòng. Một ngày, Ji Hae dọn dẹp gác mái. Tại đây, cô tìm được một chiếc hộp bí mật lưu trữ kỉ vật cùng những trang hồi ức về mối tình đầu của mẹ cô trong quá khứ..</span></p>', 'Full', 1, 'single', 'completed', 19, 2003, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Son Ye-jin","avatar":""},{"name":"Cho Seung-woo","avatar":""},{"name":"Zo In-sung","avatar":""},{"name":"Lee Ki-woo","avatar":""},{"name":"Seo Young-hee","avatar":""},{"name":"Lee Joo-Eun","avatar":""},{"name":"Park Do-Yoo","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Lee Seung-cheol","avatar":""},{"name":"Hyun Sook-hee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324531);
