INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-xua-2003', 'Trường Xưa (2003)', 'Old School (2003)', 'https://phimimg.com/upload/vod/20230918-1/6951dc4ed7bff87b3678abc6ad9c3d41.jpg', 'https://phimimg.com/upload/vod/20230918-1/ebb700cc3d861c8e42ebf87d619bd0c5.jpg', '<p><span style="font-family: ">Một phim cực vui. Nếu bạn thích American Pie thì chắc chắn bạn sẽ thích phim này. Còn nếu bạn không thích American Pie thì cũng chưa chắc bạn đã không thích phim này . Hãy thử xem để biết , chứ giới thiệu 0 thì hổng đủ.Tóm tắt nội dung phim như sau:Có 3 người bạn học cũ rất thân là Mitch, Frank và Beanie. Mitch vừa chia tay với vợ sau khi phát hiện vợ ngoại tình. Frank thì vừa lập gia đình, còn Beanie đã có 2 đứa con nhỏ. Mitch sau khi chia tay vợ đã dọn đến thuê 1 căn hộ thuộc 1 trường ĐH. Beanie nảy ra sáng kiến là sẽ sử dụng căn nhà này như 1 điểm ăn chơi, wậy tới bến . Tuy nhiên chỉ ngay sau ngày ăn chơi đầu tiên thì tai họa đã xảy ra: vợ chồng Frank xích mích sau khi vợ anh chàng cùng bạn bè túm được ông chồng say khướt đang khoả ...</span></p>', 'Full', 1, 'single', 'completed', 24, 2003, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Luke Wilson","avatar":""},{"name":"Will Ferrell","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Ellen Pompeo","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"Leah Remini","avatar":""},{"name":"Perrey Reeves","avatar":""},{"name":"Craig Kilborn","avatar":""},{"name":"Elisha Cuthbert","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324531);
