INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('juwanna-mann', 'Juwanna Mann', 'Juwanna Mann', 'https://phimimg.com/upload/vod/20260705-1/c49369ea594ff36dadb7e43fd1fb650e.jpg', 'https://phimimg.com/upload/vod/20260705-1/dac073459dbf8c90b826e393fe749970.jpg', '<p>Khi những trò quậy phá khiến anh bị đình chỉ khỏi giải bóng rổ nam chuyên nghiệp, một cầu thủ ngổ ngáo khoác lên thân phận khác và gia nhập đội nữ để tiếp tục thi đấu.</p>', 'Full', 1, 'single', 'completed', 36, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Miguel A. Núñez Jr.","avatar":""},{"name":"Vivica A. Fox","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Tommy Davidson","avatar":""},{"name":"Ginuwine","avatar":""},{"name":"Lil'' Kim","avatar":""},{"name":"Dikembe Mutombo","avatar":""},{"name":"Vlade Divac","avatar":""},{"name":"Muggsy Bogues","avatar":""},{"name":"Rasheed Wallace","avatar":""},{"name":"Kim Wayans","avatar":""},{"name":"Jenifer Lewis","avatar":""},{"name":"Annie Corley","avatar":""},{"name":"Terry Loughlin","avatar":""},{"name":"Bonnie Johnson","avatar":""},{"name":"Tammi Reiss","avatar":""},{"name":"Jay Leno","avatar":""},{"name":"Seth C","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mister Sister - Eine Drag Queen in der Liga","쥬와나 만","슈팅히어로 주와나","Juwanna Mann"]', 1784690324531);
