INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('juwanna-mann', 'Juwanna Mann', 'Juwanna Mann', 'juwanna mann juwanna mann miguel a. núñez jr. vivica a. fox kevin pollak tommy davidson ginuwine lil'' kim dikembe mutombo vlade divac muggsy bogues rasheed wallace kim wayans jenifer lewis annie corley terry loughlin bonnie johnson tammi reiss jay leno seth c mister sister - eine drag queen in der liga 쥬와나 만 슈팅히어로 주와나 juwanna mann', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-dang-so', 'Lời Nguyền Đáng Sợ', 'The Mothman Prophecies', 'https://phimimg.com/upload/vod/20260608-1/b29eb8c5fd0ed27d274459f98b48b0f4.jpg', 'https://phimimg.com/upload/vod/20260608-1/4d8e0cc24af201868c8bb5c2669fd790.jpg', '<p>Cuộc đời John Klein, một phóng viên kỳ cựu của tờ Washington Post, đột ngột rẽ sang hướng khác sau khi cô vợ Mary qua đời vì tai nạn giao thông trong ngày lễ Giáng sinh. Vào cái ngày định mệnh ấy, văn phòng môi giới nhà đất dẫn hai người đi xem một ngôi nhà rộng và đẹp. Trên đường về Mary cầm lái. Bỗng nhiên chiếc xe lao vào một cây to bên đường. Đầu Mary đập mạnh vào cửa kính, nhưng John không hề hấn gì. Vừa tỉnh lại, Mary khẳng định là cô nhìn thấy một sinh vật lạ. John không hiểu vợ nói gì, cho rằng cô bị hoảng loạn tâm thần. Mặc dù Mary chỉ dính chấn thương nhẹ, nhưng khi chụp cộng hưởng từ, các bác sĩ phát hiện một khối u trong não của cô. Một ca mổ được tiến hành, nhưng Mary không qua khỏi. ...</p>', 'Full', 1, 'single', 'completed', 21, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Richard Gere","avatar":""},{"name":"Laura Linney","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Debra Messing","avatar":""},{"name":"David Eigenberg","avatar":""},{"name":"Alan Bates","avatar":""},{"name":"Lucinda Jenney","avatar":""},{"name":"Nesbitt Blaisdell","avatar":""},{"name":"Bill Laing","avatar":""},{"name":"Dan Callahan","avatar":""},{"name":"Yvonne Erickson","avatar":""},{"name":"Tom Stoviak","avatar":""},{"name":"Scott Nunnally","avatar":""},{"name":"Harris Mackenzie","avatar":""},{"name":"Zachary Mott","avatar":""},{"name":"Ann McDonough","avatar":""},{"name":"Bob Tracey","avatar":""},{"name":"Tom","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7