INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bai-rac', 'Vua Bãi Rác', 'The Landfill King', 'https://phimimg.com/upload/vod/20260604-1/283e66e2f4759fef82f368694d135ba2.jpg', 'https://phimimg.com/upload/vod/20260604-1/5e8e1003ff434564d40fe6d2d29b8e2e.jpg', '<p>Vua Bãi Rác kể về những số phận dưới đáy xã hội, từ các ngả khác nhau quần tụ về bãi rác, hình thành một cộng đồng với đủ niềm vui, nỗi buồn lẫn đau khổ.</p>', 'Full', 1, 'single', 'completed', 38, 2002, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Võ Hoài Nam","avatar":""},{"name":"Nguyễn Bích Ngọc","avatar":""},{"name":"Công Lý","avatar":""},{"name":"Doãn Hoàng Kiên","avatar":""},{"name":"Lệ Hằng","avatar":""},{"name":"Trần Hạnh","avatar":""},{"name":"Đức Long","avatar":""},{"name":"Nguyễn Thị Tần","avatar":""},{"name":"Duy Hậu","avatar":""},{"name":"Minh Phương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Foul King","Vua bãi rác"]', 1784690324531);
