INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-smallville-phan-2', 'Thị Trấn Smallville (Phần 2)', 'Smallville (Season 2)', 'https://phimimg.com/upload/vod/20250604-1/857299f3d4b7f17be7506f66af2f65f7.jpg', 'https://phimimg.com/upload/vod/20250604-1/f175b3188b997d808266c9b2585241c1.jpg', '<p>Huyền thoại tiếp tục phát triển mạnh mẽ hơn trong mùa hai đầy kịch tính của Smallville. Suốt 23 tập của mùa này, Clark Kent vật lộn với sứ mệnh của mình khi khám phá nguồn gốc thật sự: liệu cậu được gửi đến Trái Đất để cứu nhân loại hay hủy diệt nó? Giữa những hỗn loạn ấy, mối quan hệ giữa Lana và Clark trở nên gần gũi hơn bao giờ hết; Lex kết hôn; Lionel dụ dỗ Chloe bước vào con đường tăm tối; gia đình Kent nhận được một tin tức kỳ diệu; còn Pete trở thành người giữ bí mật của Clark.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 14, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Welling","avatar":""},{"name":"Erica Durance","avatar":""},{"name":"Cassidy Freeman","avatar":""},{"name":"Justin Hartley","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Smallville"]', 1784690324531);
