INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-nguoi-yeu-nhau', 'Hai Người Yêu Nhau', 'Two Lovers, One Ghost', 'https://phimimg.com/upload/vod/20260603-1/0fda2b7bd192a7ac4de802b19ddfbcfe.jpg', 'https://phimimg.com/upload/vod/20260603-1/aeb29a5f9dac00682b177ed129ab1e28.jpg', '<p>Hiro và Makio bắt đầu sống chung không lâu sau khi họ hẹn hò. Hiro cũng đã chuyển đến sống cùng bạn gái cũ Mitsuru, nhưng Makio không tò mò về chuyện đó và lặng lẽ đốt bức ảnh của Mitsuru. Từ đó, Makio bắt đầu thỉnh thoảng bị mất trí nhớ. Mỗi khi anh ta mất trí nhớ, Hiro cảm thấy có điều gì đó kỳ lạ về hành vi bất thường của Makio. Điều này là bởi vì anh ta có vẻ ngoài giống Mitsuru. Hiro bắt đầu tìm kiếm Mitsuru, nhưng không tìm thấy manh mối nào. Sau đó, Makio hỏi anh ta, Tại sao cậu lại bỏ tôi? và anh ta ngất xỉu. Cả hai quyết định đối mặt với bí ẩn này. Một ngày nọ, Makio tìm thấy một người đàn ông trông giống Mitsuru và đuổi theo anh ta. Kazuki, một người trừ tà, đã ngăn anh ta lại. Anh ta nói với Makio rằng một linh hồn đáng sợ đang ám ảnh anh ta. Makio yêu cầu anh ta trừ tà cho linh hồn đó... Bạn có tin được không? Bạn có tin vào tình yêu điên cuồng tột cùng không?</p>', 'Full', 1, 'single', 'completed', 18, 2002, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ranran Nakayama","avatar":""},{"name":"Shinobu Miyazawa","avatar":""},{"name":"Kaito Nono","avatar":""},{"name":"Hiro","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ふたりの恋人"]', 1784690324531);
