INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-noi-12-ngay-dem', 'Hà Nội 12 Ngày Đêm', 'Hanoi 12 Days and Nights', 'https://phimimg.com/upload/vod/20250401-1/31de51f7bfbda459afb441e90d5662b9.jpg', 'https://phimimg.com/upload/vod/20250401-1/e78b598e7a8cb3f454639835a9fa2b19.jpg', '<p>Hà Nội 12 ngày đêm được thể hiện rất công phu với mục đích tái hiện một phần trận Điện Biên Phủ trên không – một cuộc chiến đấu ác liệt của nhân dân Hà Nội chống lại cuộc tập kích chiến lược bằng máy bay B-52 của đế quốc Mỹ vào cuối tháng 12 năm 1972, buộc Chính phủ Hoa Kỳ phải ký Hiệp định Paris đem lại hòa bình ở miền Bắc Việt Nam.</p>', 'Full', 1, 'single', 'completed', 23, 2002, 'Vietsub', 'HD', 'Việt Nam', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Hà Nội 12 Ngày Đêm"]', 1784690324531);
