INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-diep-vien-danh-tinh-cua-bourne', 'Siêu Điệp Viên: Danh Tính Của Bourne', 'The Bourne Identity', 'https://phimimg.com/upload/vod/20260116-1/fcda0119b8925c26296c2465d6c4dbb5.jpg', 'https://phimimg.com/upload/vod/20260116-1/1e6e51046f16cfe737c802bad7bf610b.jpg', '<p>Ngoài khơi biển Địa Trung Hải, chiếc tàu đánh cá đã cứu được một chàng trai đang trôi vật vờ theo sóng nước, người đầy vết đạn bắn. Anh không biết mình là ai, mình đã làm gì... Manh mối lờ mờ duy nhất là dòng chữ ghi địa chỉ một ngân hàng Thuỵ Sĩ do con chip laser cấy vào người anh phát ra. Sau khi tàu cập bến, anh lên đường lao vào cuộc tìm kiếm lại quá khứ. Liệu anh sẽ tìm ra được những gì trong quá khứ?</p>', 'Full', 1, 'single', 'completed', 21, 2002, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Franka Potente","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Clive Owen","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"Gabriel Mann","avatar":""},{"name":"Julia Stiles","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Josh Hamilton","avatar":""},{"name":"Orso Maria Guerrini","avatar":""},{"name":"Tim Dutton","avatar":""},{"name":"Denis Braccini","avatar":""},{"name":"Nicky Naudé","avatar":""},{"name":"David Selburg","avatar":""},{"name":"Demetri Goritsas","avatar":""},{"name":"Russell Le","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["El caso Bourne","Jason Bourne - La Mémoire dans la Peau","Chorís taftótita","Samolichnostta na Born","Identifikatsiya Borna","Bornov identitet","Identyfikatsiya Borna","A Identidade Bourne","谍影重重：伯恩的身份","Borna identitāte","Borna mīklainā personība","叛諜追擊","Identidad Desconocida","The Bourne Identity"]', 1784690324531);
