INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-niem-phat-tai', 'Tâm Niệm Phát Tài', 'Fat Choi Spirit', 'https://phimimg.com/upload/vod/20231008-1/6eaaf840e30ce044d83e962a4e3149c9.jpg', 'https://phimimg.com/upload/vod/20231008-1/afe538c96553d648e4fd4b97fe15cbf8.jpg', '<p>Andy là một tay chơi mạt chược nổi tiếng, anh đã từng làm cho cả gia đình tan gia bại sản vì niềm yêu thích đánh mạt chược của mình. Nhưng khi em trai Andy là Louis gặp khó khăn về tài chính thì Andy buộc phải quay lại với bàn đấu mạt chược để giúp em mình...</p>', 'Full', 1, 'single', 'completed', 17, 2002, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Lưu Thanh Vân","avatar":""},{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Lương Vịnh Kỳ","avatar":""},{"name":"Ứng Thể Thành","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324531);
