INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-ngot-ngao-nhat', 'Điều Ngọt Ngào Nhất', 'The Sweetest Thing', 'https://phimimg.com/upload/vod/20251229-1/16e6efc644ea6f2dbeb643bffb6f0e75.jpg', 'https://phimimg.com/upload/vod/20251229-1/eba82eae9734e5ef651619088a554d7e.jpg', '<p>Chuyện tình cảm của Christina đang dậm chân tại chỗ. Sau nhiều năm né tránh những rắc rối của một mối quan hệ nghiêm túc, một đêm nọ, khi đi chơi hộp đêm với các cô bạn gái, cô gặp Peter, người hoàn hảo dành cho mình. Chán ngấy những trò chơi tình cảm, cuối cùng cô cũng lấy hết can đảm để hạ thấp cảnh giác và làm theo trái tim mình, nhưng rồi phát hiện ra Peter đột ngột rời khỏi thị trấn. Cùng với Courtney, cô bắt đầu hành trình tìm lại người đã vuột mất.</p>', 'Full', 1, 'single', 'completed', 16, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Cameron Diaz","avatar":""},{"name":"Christina Applegate","avatar":""},{"name":"Selma Blair","avatar":""},{"name":"Thomas Jane","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Parker Posey","avatar":""},{"name":"Lillian Adams","avatar":""},{"name":"Chelsea Bond","avatar":""},{"name":"Judith Chapman","avatar":""},{"name":"Joe Bellan","avatar":""},{"name":"Georgia Engel","avatar":""},{"name":"Jennifer Gimenez","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Siena Goines","avatar":""},{"name":"Bryan Anthony","avatar":""},{"name":"Linda Asuma","avatar":""},{"name":"Vahe Bejan","avatar":""},{"name":"Herb An","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["The Sweetest Thing"]', 1784690324531);
