INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-ve-nha-2002', 'Đường Về Nhà', 'The Way Home', 'https://phimimg.com/upload/vod/20251218-1/3718ed9700230ed6386fb20809e9db55.jpg', 'https://phimimg.com/upload/vod/20251218-1/ce8dff81b391e71926b8184a9fd576d6.jpg', '<p>Bộ phim muốn truyền tải thông điệp đến thế hệ trẻ về tình yêu vô điều kiện của những người già đã hi sinh quên mình cho họ vì vậy họ hãy giành nhiều thời gian của mình để chăm sóc, quan tâm đến ông bà, bố mẹ mình. Nội dung chính của bộ phim câu chuyện ấm áp về một người bà và đứa cháu trai sống ở thành phố đã về quê sống với bà ở một ngôi làng nông thôn.</p>', 'Full', 1, 'single', 'completed', 16, 2002, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Eul-boon","avatar":""},{"name":"Yoo Seung-ho","avatar":""},{"name":"Dong Hyo-hee","avatar":""},{"name":"Min Kyung-Hyun","avatar":""},{"name":"Yim Eun-kyung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Jibeuro","집으로...","Todos los caminos llevan a casa","집으로","愛·回家","Kore''ye Dönüş"]', 1784690324531);
