INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-bao-cao-thieu-so', 'Bản Báo Cáo Thiểu Số', 'Minority Report', 'https://phimimg.com/upload/vod/20251216-1/cc259066d11198bb24b15cca822df35a.jpg', 'https://phimimg.com/upload/vod/20251216-1/5826579a1b567e27d8ecf5669e8e24ed.jpg', '<p>Thanh tra John Anderton đầy trách nhiệm và tuyệt đối tin tưởng vào Bộ phận dự đoán. Nhưng thật trớ trêu khi một ngày Bộ phận thông báo rằng John chính là kẻ giết người tiếp theo, nạn nhân là một người anh không hề quen biết. Không còn cách nào khác, anh phải chạy trốn. Trên đường đi tìm ra sự thực về Bản báo cáo thiểu số, John đã khám phá ra bí mật về Bộ phận Dự Đoán này mà không ai có thể ngờ tới được.</p>', 'Full', 1, 'single', 'completed', 21, 2002, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Samantha Morton","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"Max von Sydow","avatar":""},{"name":"Kathryn Morris","avatar":""},{"name":"Steve Harris","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Patrick Kilpatrick","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Jessica Capshaw","avatar":""},{"name":"Daniel London","avatar":""},{"name":"Lois Smith","avatar":""},{"name":"Tim Blake Nelson","avatar":""},{"name":"Caroline Lagerfelt","avatar":""},{"name":"Jason Antoon","avatar":""},{"name":"Mike Binder","avatar":""},{"name":"Arye","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Suvišni izveštaj","Second Sight","Total Recall 2","Spetsialen doklad","Osoboye mneniye","Osoblyva dumka","Raport Mniejszości","未來報告","關鍵報告","Rapport minoritaire","Sentencia Previa","マイノリティ・リポート","Minority Report"]', 1784690324531);
