INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-trat-su-muoi', 'Tân Trát Sư Muội', 'Love Undercover', 'https://phimimg.com/upload/vod/20251206-1/c312093178cf40e9c52bb03ff27e6f1f.jpg', 'https://phimimg.com/upload/vod/20251206-1/38abbd607ce3114e16fd864f658de9dd.jpg', '<p>Trong phim Nữ Cảnh Sát Mới Ra Trường, Dương Thiên Hoa sẽ vào vai cô gái xinh đẹp – Fong, cô vốn được vào Trường trường cảnh sát để thực hiện ước mơ bấy lâu nay, nhưng thành tích thực sự của cô chỉ được trường cho phép làm một số việc nhỏ nhặt trong sở cảnh sát sau khi được tốt nghiệp. Dù vậy, vào một ngày nọ, cô đã được giao một nhiệm vụ vô cùng quan trọng, đó là đóng giả làm một nhân viên phục vụ bàn và đi đặt máy nghe lén ở chỗ mục tiêu. Sau đó, một chuyện bất ngờ đã xảy ra khiến kế hoạch của họ đã bị đổ bể hoàn toàn…</p>', 'Full', 1, 'single', 'completed', 22, 2002, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Diệp Thiên Hoa","avatar":""},{"name":"Ngô Ngạn Tổ","avatar":""},{"name":"Trương Chung","avatar":""},{"name":"Lý Diệu Minh","avatar":""},{"name":"Lý Tiểu Kỳ","avatar":""},{"name":"Mạc Tiểu Phái","avatar":""},{"name":"Ngô Chi Hùng","avatar":""},{"name":"Vương Ho Nhân","avatar":""},{"name":"Vương Diệt Đồng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sun jaat si mui","新紮師妹"]', 1784690324531);
