INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-gia-tuyet-2', 'Ông Già Tuyết 2', 'The Santa Clause 2', 'https://phimimg.com/upload/vod/20251214-1/bc0ff9ee8f61095e74543df50d511a52.jpg', 'https://phimimg.com/upload/vod/20251214-1/5b06dd3111b7e2c24b445c8b1c10c8a0.jpg', '<p>Hãy coi chừng! Ông lớn mặc đồ đỏ (Santa Claus) sắp đến thị trấn một lần nữa.&nbsp; Lần này, Scott Calvin — người còn được biết đến là Ông già Noel — phát hiện ra một điều khoản khó hiểu trong hợp đồng của mình, yêu cầu anh phải lấy vợ.&nbsp; Anh phải rời Bắc Cực để hoàn thành nghĩa vụ này, nếu không, anh sẽ buộc phải từ bỏ công việc Giáng sinh vĩ đại của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tim Allen","avatar":""},{"name":"Judge Reinhold","avatar":""},{"name":"Wendy Crewson","avatar":""},{"name":"Elizabeth Mitchell","avatar":""},{"name":"David Krumholtz","avatar":""},{"name":"Eric Lloyd","avatar":""},{"name":"Spencer Breslin","avatar":""},{"name":"Liliana Mumy","avatar":""},{"name":"Danielle Woodman","avatar":""},{"name":"Art LaFleur","avatar":""},{"name":"Aisha Tyler","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Jay Thomas","avatar":""},{"name":"Michael Dorn","avatar":""},{"name":"Christopher Attadia","avatar":""},{"name":"Curtis Butchart","avatar":""},{"name":"Jamal Allen","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Santa Clause 2: The Mrs. Clause","The Mrs. Clause: Santa Clause 2","Santa Cláusula - Sarilhos No Natal","Sa