INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-ngoat-cuoc-doi', 'Bước Ngoặt Cuộc Đời', 'Golden Faith', 'https://phimimg.com/upload/vod/20251023-1/87168b208a139d45267c6e14b6668c9d.jpg', 'https://phimimg.com/upload/vod/20251023-1/78c7b25f32909b877a808ada280161dd.jpg', '<p>Đinh Thiện Bản (do La Gia Lương đóng) từ lúc 6 tuổi trong một cơn bão đã lạc mất gia đình. Anh được Đinh Vinh Bang (do Tần Bái đóng) nhận làm con nuôi. Trong một lần sang Úc công tác, anh quen biết với Trình Thiên Lam (do Tuyên Huyên đóng) - một nữ công tố tính tình ngay thẳng. Khi trở về Hồng Kông, vì giúp cha nuôi mà Thiện Bản đánh mất tình cảm với Thiên Lam. Anh dính líu vào một vụ án và người thụ lý vụ án này lại là em trai thất lạc Chung Thủ Khang (do Ôn Triệu Luân đóng).

Con trai ruột của Đinh Vinh Bang là Đinh Thiện Hành (do Lâm Phong đóng) du học trở về, sau bị chú ba xúi giục đã xem Thiện Bản như là kẻ thù và tìm mọi cách chiếm đoạt tài sản sau khi cha Vinh Bang qua đời.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 14, 2002, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Gallen Lo Ka-Leung","avatar":""},{"name":"Jessica Hsuan","avatar":""},{"name":"Deric Wan","avatar":""},{"name":"Raymond Lam Fung","avatar":""},{"name":"Michelle Ye Xuan","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Myolie Wu Hang-Yee","avatar":""},{"name":"Benz Hui Siu-Hung","avatar":""},{"name":"Jay Lau Kam-Ling","avatar":""},{"name":"Samuel Kwok Fung","avatar":""},{"name":"Kwan Ching","avatar":""},{"name":"Wilson Ai Wai","avatar":""},{"name":"Shek Sau","avatar":""},{"name":"Anne Heung Hoi-Lam","avatar":""},{"name":"Gigi Wong","avatar":""},{"name":"Tavia Yeung","avatar":""},{"name":"Po","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["流金歲月","流金岁月","Golden Faith"]', 1784690324531);
