INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-bat-dac-di', 'Điệp Viên Bất Đắc Dĩ (Bộ Vest Tuxedo)', 'The Tuxedo', 'https://phimimg.com/upload/vod/20251023-1/2e3256af61cd7cc227961e57a674dcd5.jpg', 'https://phimimg.com/upload/vod/20251023-1/994d08a961f693079819815b6579a2a9.jpg', '<p>Jimmy Tong là một người lái xe tầm thường cho nhà tỷ phú Clack Devlin đến khi Devlin gặp tai nạn và phải vào bệnh viện. Tong được đưa về nhà để tìm và đem vào một số vật dụng cho Devlin, vô tình anh đã mặc thử bộ vest của Devlin và phát hiện ra rằng bất cứ ai mặc vào sẽ có được một sức mạnh thần kỳ. Khám phá này đã đẩy Tong vào thế giới của những mưu đồ và điệp vụ xuyên quốc gia, đồng thời ghép anh và người cộng sự thiếu kinh nghiệm lại gần nhau...</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Jennifer Love Hewitt","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Debi Mazar","avatar":""},{"name":"Ritchie Coster","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Mia Cottet","avatar":""},{"name":"Romany Malco","avatar":""},{"name":"Daniel Kash","avatar":""},{"name":"Jody Racicot","avatar":""},{"name":"Scott Wickware","avatar":""},{"name":"Christian Potenza","avatar":""},{"name":"Karen Glave","avatar":""},{"name":"Scott Yaphe","avatar":""},{"name":"Boyd Banks","avatar":""},{"name":"Colin Mochrie","avatar":""},{"name":"James Brown","avatar":""},{"name":"Paul Bat","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89