INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-hanh-giua-cac-vi-sao-10-bao-ung', 'Du Hành Giữa Các Vì Sao 10: Báo Ứng', 'Star Trek: Nemesis', 'https://phimimg.com/upload/vod/20250930-1/414636d6d8611e32434e7aa985a5374c.jpg', 'https://phimimg.com/upload/vod/20250930-1/99a808477654eb55e09de26580976ee6.jpg', '<p>Trên đường đi hưởng tuần trăng mật của William Riker đến Deanna Troi trên hành tinh Betazed, quê hương của cô, Thuyền trưởng Jean-Luc Picard và thủy thủ đoàn của U.S.S. Enterprise nhận được tin báo từ Starfleet rằng một cuộc đảo chính đã dẫn đến việc thành lập một nhà lãnh đạo chính trị mới của người Romulan, Shinzon, người tuyên bố tìm kiếm hòa bình với Liên đoàn các hành tinh thống nhất do con người hậu thuẫn. Khi ở trong lãnh thổ của kẻ thù, thuyền trưởng và thủy thủ đoàn của anh ta có một khám phá đáng kinh ngạc: Shinzon là con người, một nô lệ từ hành tinh chị em Romulan của Remus, và có một mối quan hệ bí mật, gây sốc với chính Picard.</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patrick Stewart","avatar":""},{"name":"Jonathan Frakes","avatar":""},{"name":"Brent Spiner","avatar":""},{"name":"LeVar Burton","avatar":""},{"name":"Michael Dorn","avatar":""},{"name":"Gates McFadden","avatar":""},{"name":"Marina Sirtis","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Dina Meyer","avatar":""},{"name":"Jude Ciccolella","avatar":""},{"name":"Shannon Cochran","avatar":""},{"name":"Kate Mulgrew","avatar":""},{"name":"Wil Wheaton","avatar":""},{"name":"Stuart Baird","avatar":""},{"name":"Alan Dale","avatar":""},{"name":"David Ralphe","avatar":""},{"name":"Majel Barret","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Star Trek 10: Nemesis","Star Trek X - Nemesis","Star Trek X - La nemesi","Star Trek X: Nemesis","Star Trek - Nemesis","Star Trek X Nemesis","Star Trek 10 - Nemesis","10 Star Trek X - Nemesis","Star Trek: Némesis","スター・トレック10 ネメシス","Star Trek 10","Стар Трек 10","10_Star Trek. Nemesis","Viaje a las estrellas 10 Nemesis","Star Trek X: Nemezis","Star Trek 10. - Nemezis","Star Trek X. - Nemezis","星际旅行10：复仇女神","Jornada nas Estrelas: Nêmesis","스타트렉: 네메시스","스타트렉 10: 네메시스","星际迷航10：复仇女神","스타 트렉: 네메시스","スター・トレック ネメシス S.T.X","Звездный путь 10: Возмездие","Star Trek: Nemesis"]', 1784690324531);
