INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('du-hanh-giua-cac-vi-sao-10-bao-ung', 'Du Hành Giữa Các Vì Sao 10: Báo Ứng', 'Star Trek: Nemesis', 'du hành giữa các vì sao 10: báo ứng star trek: nemesis patrick stewart jonathan frakes brent spiner levar burton michael dorn gates mcfadden marina sirtis tom hardy ron perlman dina meyer jude ciccolella shannon cochran kate mulgrew wil wheaton stuart baird alan dale david ralphe majel barret star trek 10: nemesis star trek x - nemesis star trek x - la nemesi star trek x: nemesis star trek - nemesis star trek x nemesis star trek 10 - nemesis 10 star trek x - nemesis star trek: némesis スター・トレック10 ネメシス star trek 10 стар трек 10 10_star trek. nemesis viaje a las estrellas 10 nemesis star trek x: nemezis star trek 10. - nemezis star trek x. - nemezis 星际旅行10：复仇女神 jornada nas estrelas: nêmesis 스타트렉: 네메시스 스타트렉 10: 네메시스 星际迷航10：复仇女神 스타 트렉: 네메시스 スター・トレック ネメシス s.t.x звездный путь 10: возмездие star trek: nemesis', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nhen-2002', 'Người Nhện', 'Spider-Man', 'https://phimimg.com/upload/vod/20250828-1/8d06a88a548d9de439a2821242557e15.jpg', 'https://phimimg.com/upload/vod/20250828-1/32b691d8abf459ca3c8f0c4371971a88.jpg', '<p>Peter Parker là một sinh viên trẻ và nhút nhát, đã sống với dì May và chú Ben kể từ khi cha mẹ anh ta mất khi anh ta còn rất nhỏ. Peter yêu người hàng xóm xinh đẹp của mình, nhưng sự thiếu lôi cuốn của anh ta không khiến anh ta trở nên nổi tiếng ở trường trung học. Một ngày nọ, anh ta bị cắn bởi một con nhện đã bị biến đổi gen, phát hiện ra ngày hôm sau anh ta sở hữu sức mạnh khác thường: anh ta có sức mạnh và sự nhanh nhẹn của một con nhện. Cuộc phiêu lưu của Người Nhện, dựa trên truyện tranh nổi tiếng Stan Lee và Steve Ditko, đã càn quét phòng vé Mỹ và phá vỡ kỷ lục phá vỡ kỷ lục vào cuối tuần đầu tiên của anh: 114 triệu đô la, lần đầu tiên trong lịch sử, anh tìm cách phá vỡ Rào cản 100 triệu đô la vào một ngày cuối tuần bình thường.</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tobey Maguire","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Kirsten Dunst","avatar":""},{"name":"James Franco","avatar":""},{"name":"Cliff Robertson","avatar":""},{"name":"Rosemary Harris","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Joe Manganiello","avatar":""},{"name":"Gerry Becker","avatar":""},{"name":"Bill Nunn","avatar":""},{"name":"Jack Betts","avatar":""},{"name":"Stanley Anderson","avatar":""},{"name":"Ron Perkins","avatar":""},{"name":"Michael Papajohn","avatar":""},{"name":"K.K. Dodds","avatar":""},{"name":"Ted Raimi","avatar":""},{"name":"Bruce Campbell","avatar":""},{"name":"Elizabe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Spajdermen","Spider-Man: The Motion Picture","Spiderman","Spaĭdŭr-men","Lyudyna-pavuk","蜘蛛侠1 (托比·马奎尔)","스파이더 맨","Hämähäkkimies","ობობა-კაცი","სპაიდერმენი","Spider-Man 1","Spider-Man I","スパイダーマン：2002","Người Nhện","Spider Man","Սարդ Մարդը","ပင့်ကူလူသား","Hörümçək-Adam","الرجل العنكبوت","ⵙⴱⴰⵢⴷⵔⵎⴰⵏ","Spider-Man"]', 1784690324531);
