INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-nhen-2002', 'Người Nhện', 'Spider-Man', 'người nhện spider-man tobey maguire willem dafoe kirsten dunst james franco cliff robertson rosemary harris j.k. simmons joe manganiello gerry becker bill nunn jack betts stanley anderson ron perkins michael papajohn k.k. dodds ted raimi bruce campbell elizabe spajdermen spider-man: the motion picture spiderman spaĭdŭr-men lyudyna-pavuk 蜘蛛侠1 (托比·马奎尔) 스파이더 맨 hämähäkkimies ობობა-კაცი სპაიდერმენი spider-man 1 spider-man i スパイダーマン：2002 người nhện spider man սարդ մարդը ပင့်ကူလူသား hörümçək-adam الرجل العنكبوت ⵙⴱⴰⵢⴷⵔⵎⴰⵏ spider-man', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-thay-co-giup-do-onegai-sensei', 'Xin Thầy Cô Giúp Đỡ! (Onegai Sensei)', 'Please Teacher!', 'https://phimimg.com/upload/vod/20250923-1/ae2f761294163865b27da6a49db1f9b5.jpg', 'https://phimimg.com/upload/vod/20250923-1/2c9307615daa1983ee2af17674c3a156.jpg', '<p><span style="text-wrap-mode: wrap;">Đây là câu chuyện về mối tình giữa Mizuho, một đặc phái viên của Hội Đồng Tối Cao thẩm định các vấn đề liên quan tới hành tinh - ngân hà đến trái đất trong một đặc sứ của mình và Kei một học sinh... Truyện bắt đầu khi Kei nhìn lên bầu trời đêm, một bầu trời đầy sao hiện lên trong mắt của Kei ...tình cờ cậu phát hiện ra một cô gái đứng trong quầng sáng ở bờ hồ...Tưởng như mọi sự chỉ là như một giấc mộng đêm hè, nhưng giấc mơ đó cứ theo đuổi và ám ảnh anh chàng. Rồi đến khi bỗng dưng Kei nhận ra cô gái kia lại là cô giáo mới của mình!!! Hai người trở thành hàng xóm sau bao nhiêu cái vô lí nhưng rất có lí nếu nhìn từ phía ngoài cuộc ... sau đó nhiều sự hiểu lầm, khác giới tính khác điều kiện sinh sống và cả văn hóa những khúc mắc trong thời gian hoạt động tại địa cầu và...</span></p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 12, 2002, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kikuko Inoue","avatar":""},{"name":"Soichiro Hoshi","avatar":""},{"name":"Yumi Takada","avatar":""},{"name":"Satomi Korogi","avatar":""},{"name":"Tomoko Kaneda","avatar":""},{"name":"Rei Sakuma","avatar":""},{"name":"Ayako Kawasumi","avatar":""},{"name":"Yukari Tamura","avatar":""},{"name":"Mitsuo Iwata","avatar":""},{"name":"Sayaka Ohara","avatar":""},{"name":"Hiroaki Miura","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Naoya Uchida","avatar":""},{"name":"Rei Sakuma","avatar":""},{"name":"Omi Minami","avatar":""},{"name":"Chinami Nishimura","avatar":""},{"name":"Yutaka Nakano","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Please Teacher!","Onegai Teacher","오네가이 티쳐","부탁해요 선생님","플리즈☆티쳐","오네가이 티처","플리즈 티처","拜託了老師","おねがい☆ティーチャー"]', 1784690324531);
