INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xin-thay-co-giup-do-onegai-sensei', 'Xin Thầy Cô Giúp Đỡ! (Onegai Sensei)', 'Please Teacher!', 'xin thầy cô giúp đỡ! (onegai sensei) please teacher! kikuko inoue soichiro hoshi yumi takada satomi korogi tomoko kaneda rei sakuma ayako kawasumi yukari tamura mitsuo iwata sayaka ohara hiroaki miura tomokazu sugita naoya uchida rei sakuma omi minami chinami nishimura yutaka nakano please teacher! onegai teacher 오네가이 티쳐 부탁해요 선생님 플리즈☆티쳐 오네가이 티처 플리즈 티처 拜託了老師 おねがい☆ティーチャー', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-gian-dao', 'Vô Gian Đạo', 'Infernal Affairs', 'https://phimimg.com/upload/vod/20250920-1/feb68c75e666c7184d266f57e9d18685.jpg', 'https://phimimg.com/upload/vod/20250920-1/31019aa6030c3165042335a82e07f293.jpg', '<p>Trong phim Vô Gian Đạo, Lưu Kiến Minh là trợ thủ đắc lực cho Sâm, một ông trùm mafia, hoạt động bí mật bằng cách trà trộn vào Cục Điều tra hình sự Hong Kong. Ở bên kia chiến tuyến nhưng giống hệt trường hợp của Lưu Kiến Minh, Trần Vĩnh Nhân là cảnh sát nằm vùng. Anh &quot;đội lốt&quot; một tên mafia trong băng đảng của Sam một cách hoàn hảo. Cuộc đấu trí căng thẳng giữa hai kỳ phùng địch thủ của hai phe thiện và ác sẽ diễn ra như thế nào? Với sự tham gia của các ngôi sao như Lương Triều Vỹ, Lưu Đức Hoa và Trịnh Tú Văn, &quot;Vô gian đạo&quot; khai thác đề tài cũ, nhưng theo một cách hoàn toàn mới. Cả hai đạo diễn rất khéo léo khi dẫn dắt các tình tiết và nhân vật, khiến bộ phim trở thành hiện tượng của điện ảnh thành công ngay khi mới ra đời.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Eric Tsang Chi-Wai","avatar":""},{"name":"Kelly Chen","avatar":""},{"name":"Sammi Cheng","avatar":""},{"name":"Elva Hsiao","avatar":""},{"name":"Chapman To Man-Chat","avatar":""},{"name":"Gordon Lam Ka-Tung","avatar":""},{"name":"Shawn Yue","avatar":""},{"name":"Edison Chen","avatar":""},{"name":"Berg Ng Ting-Yip","avatar":""},{"name":"Wan Chi-Keung","avatar":""},{"name":"Dion Lam","avatar":""},{"name":"Tony Ho","avatar":""},{"name":"Courtney Wu","avatar":""},{"name":"Hui Kam Fung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Infernal Affairs I","Infernal affairs 1: Origines d''une saga","无间道","無間道","无间道 I","Wu jian dao","I Want to Be You","Infiltrados","Juego sucio","무간도 1","インファナル・アフェア：2002","Infernal Affairs 1","Infernal Affairs – Die achte Hölle","Infernal Affairs 1 HK","Mou gaan dou","امور دوزخی","اعمال شیطانی"]', 1784690324531);
