INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-gian-dao', 'Vô Gian Đạo', 'Infernal Affairs', 'vô gian đạo infernal affairs andy lau tony leung chiu-wai anthony wong chau-sang eric tsang chi-wai kelly chen sammi cheng elva hsiao chapman to man-chat gordon lam ka-tung shawn yue edison chen berg ng ting-yip wan chi-keung dion lam tony ho courtney wu hui kam fung infernal affairs i infernal affairs 1: origines d''une saga 无间道 無間道 无间道 i wu jian dao i want to be you infiltrados juego sucio 무간도 1 インファナル・アフェア：2002 infernal affairs 1 infernal affairs – die achte hölle infernal affairs 1 hk mou gaan dou امور دوزخی اعمال شیطانی', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-thuat-phan-5', 'Phép Thuật (Phần 5)', 'Charmed (Season 5)', 'https://phimimg.com/upload/vod/20250915-1/7d6de79630bf9a56f9aba8cdd44c5793.jpg', 'https://phimimg.com/upload/vod/20250915-1/342f68b16e155d235012d9271d2e624b.jpg', '<p>Charmed (Phép Thuật) là bộ phim dài tập của Mỹ gồm 8 phần kể về những chị em gái nhà Halliwell. Họ là những phù thuỷ tốt có phép thuật. Mỗi chị em gái sở hũu một phép thuật khác nhau với những quyền năng và sức mạnh khác nhau. Và phép thuật của họ mạnh mẽ hơn cả khi họ kết hợp với nhau, tạo thành “Bộ ba phép thuật” quyền năng và mạnh mẽ. Họ với phép thuật của mình chống lại những thế lực hắc ám, chiến đấu, chống lại lũ quỷ và bè lũ thợ săn phù thủy. Với “Cuốn sách của bóng tối” làm bạn, làm “người dẫn đường”, họ đã từng bước trưởng thành trong cuộc sống. Sức mạnh của họ ngày càng phát triển, và chính vì thế, những mối nguy hiểm đối với họ ngày càng gia tăng. Họ - những chị em gái nhà Halliwell – luôn kiên cường, mạnh mẽ chống lại cái ác, bảo vệ người vô tội. Mỗi tập phim kể về một câu chuyện nhỏ trong cuộc sống của ba chị em, xen vào đó là những yếu tố hài hước và chân thực trong cuộc sống thường ngày.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 13, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Holly Marie Combs","avatar":""},{"name":"Alyssa Milano","avatar":""},{"name":"Rose McGowan","avatar":""},{"name":"Brian Krause","avatar":""},{"name":"Kaley Cuoco","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Charmed: Jovens Bruxas","Oi magisses","Η Μαγευτικές","チャームド 魔女3姉妹","チャームド〜魔女3姉妹〜","Hechiceras","Чародійки","Зачаровані","Всі жінки відьми","Усі жінки відьми","Charmed"]', 1784690324531);
