INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loai-meo-tra-on', 'Loài Mèo Trả Ơn', 'The Cat Returns', 'https://phimimg.com/upload/vod/20250716-1/f7fcd3b04e73c5ffca4846c7b0e603a2.jpg', 'https://phimimg.com/upload/vod/20250716-1/18726c46403a29f8d2c10be126796606.jpg', '<p>Haru, một nữ sinh buồn chán với thói quen bình thường của mình, đã cứu mạng một con mèo khác thường và đột nhiên thế giới của cô bị biến đổi ngoài những gì cô từng tưởng tượng. Vua Mèo thưởng cho hành động tốt của cô bằng một loạt quà, trong đó có một màn cầu hôn vô cùng sốc với con trai mình! Haru bắt đầu một cuộc hành trình bất ngờ đến Vương quốc Mèo, nơi đôi mắt của cô được mở ra với một thế giới hoàn toàn khác.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2002, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Chizuru Ikewaki","avatar":""},{"name":"Yoshihiko Hakamada","avatar":""},{"name":"Aki Maeda","avatar":""},{"name":"Tetsu Watanabe","avatar":""},{"name":"Yousuke Saito","avatar":""},{"name":"Takayuki Yamada","avatar":""},{"name":"Hitomi Sato","avatar":""},{"name":"Kenta Satoi","avatar":""},{"name":"Mari Hamada","avatar":""},{"name":"Kumiko Okae","avatar":""},{"name":"Tetsuro Tamba","avatar":""},{"name":"Yo Oizumi","avatar":""},{"name":"Yoko Honna","avatar":""},{"name":"Ken Yasuda","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nek