INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-noi-doi', 'Vua Nói Dối', 'Big Fat Liar', 'https://phimimg.com/upload/vod/20250618-1/bf0b2313867dc9511c0e60ad9f9fc9c5.jpg', 'https://phimimg.com/upload/vod/20250618-1/07813f1354a002b5e295c966c7562f60.jpg', '<p>Jackson, một học sinh cấp 2 nổi tiếng nói dối cả cha mẹ, lẫn thầy cô. Bị cô giáo buộc phải viết xong bài luận văn trong ngày, nếu không thì phải học hè, Jackson đã viết một truyện siêu lừa gạt để nộp cho cô giáo. Trên đường đến trường, Jackson bị tai nạn phải đi nhờ xe của Marty, một nhà biên kịch kiêm sản xuất phim, và làm rơi bài luận trên xe. Không ai tin Jackson, và cậu phải học thay vì được nghỉ hè. Tình cờ, trong một buổi xem phim, Jackson phát hiện bài luận của mình - kể cả tên - đã biến thành bộ phim sắp quay ở Hollywood. Cậu rủ Kelly, cô bạn gái cùng lớp, đến Hollywood đòi lại sự thật để khỏi phải &quot;cả đời là kẻ nói dối&quot;.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Frankie Muniz","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Amanda Bynes","avatar":""},{"name":"Amanda Detmer","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"Russell Hornsby","avatar":""},{"name":"Michael Bryan French","avatar":""},{"name":"Christine Tucci","avatar":""},{"name":"Lee Majors","avatar":""},{"name":"Donald Faison","avatar":""},{"name":"Sean O''Bryan","avatar":""},{"name":"Amy Hill","avatar":""},{"name":"John Cho","avatar":""},{"name":"Matthew Frauman","avatar":""},{"name":"Don Yesso","avatar":""},{"name":"Rebecca Corry","avatar":""},{"name":"Sparkle","avatar":""},{"name":"Taran Killa","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaa