INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-tren-mang', 'Chuyện Tình Trên Mạng', 'Network Love Story', 'https://phimimg.com/upload/vod/20250616-1/c2750f4c9e4ac9b6a3ccea10c9260371.jpg', 'https://phimimg.com/upload/vod/20250616-1/b4bb4230b2d3e6326120eb88dd4e13d0.jpg', '<p>Chuyện Tình Trên Mạng lồng tiếng – Network Love Story : Đào Khản (do Lục Nghị đóng) là một nhà thiết kế trang web có tài và rất nghị lực. Trong một cuộc thi, anh làm quen với cô gái xinh đẹp Liễu Thúy Vân (do Tưởng Hồng đóng). Hai người nảy sinh xích mích, tranh cãi nhau kịch liệt. Oan gia ngõ hẹp, Khản và Vân bất ngờ phát hiện cả hai đang làm việc chung một tòa nhà. Cứ mỗi lần đụng độ, họ lại chọc ngoáy nhau, gây nên bao tình huống cười ra nước mắt. Bề ngoài có vẻ cả hai đều hài hước, vô tâm. Nhưng thực chất, mỗi người đều có nỗi khổ riêng, không biết tỏ cùng ai. Khản lập công ty bán hàng trực tuyến với Hà Gia Lâm (do Trần Hạo Dân đóng) và Dương Tuệ Na (do Diệp Tuyền đóng). Việc kinh doanh lên xuống thất thường, bị một kẻ bí ẩn đứng sau giật dây phá hoại. Còn Vân làm việc cho một công ty bất động sản. Cô được hai chàng trai theo đuổi, là anh đồng nghiệp Châu Uy (do Đồng Đại Vi đóng) và giám đốc công ty đá quý Lục Nãi Thánh (do Trịnh Gia Dĩnh đóng). Uy và Thánh, một kẻ thích khoe khoang, một người rất lập dị, khiến Vân cảm thấy phiền phức nhưng cũng khá phân vân.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 2002, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Lu Yi","avatar":""},{"name":"Benny Chan Ho-Man","avatar":""},{"name":"Michelle Ye Xuan","avatar":""},{"name":"Tong Dawei","avatar":""},{"name":"Zhang Heng","avatar":""},{"name":"Eddy Ko Hung","avatar":""},{"name":"Kevin Cheng Ka-Wing","avatar":""},{"name":"Alan Lau","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["e网情深","Network Love Story","一網情深"]', 1784690324531);
