INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('harry-potter-va-can-phong-bi-mat', 'Harry Potter và Căn Phòng Bí Mật', 'Harry Potter and the Chamber of Secrets', 'https://phimimg.com/upload/vod/20250602-1/e9618bc36b27371bf5765869d9f23831.jpg', 'https://phimimg.com/upload/vod/20250602-1/742fc1a9dd99323db33c3e2d90e9b094.jpg', '<p>Harry trở lại năm thứ hai tại Hogwarts, nhưng phát hiện ra rằng những điều tồi tệ đang xảy ra bởi vì một trang web có tên là Phòng chứa bí mật đã được người thừa kế của Slytherin mở ra và sẽ khiến những đứa trẻ của Muggles, những kẻ không trong sạch, xuất hiện một cách bí ẩn bởi một con vật quái dị.</p>', 'Full', 1, 'single', 'completed', 21, 2002, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"Toby Jones","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Richard Harris","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Tom Felton","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Shirley Henderson","avatar":""},{"name":"Richard Griffiths","avatar":""},{"name":"Julie Walters","avatar":""},{"name":"Bonnie Wright","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"Maggie Smith","avatar":""},{"name":"Warwick Davis","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Harii Pottâ to himitsu no heya","Hari Poter i Dvorana tajni","Garri Potter i Tainaya komnata","Khari Potŭr i stayata na taĭnite","O Chári Póter kai i Kámara me ta Mystiká","Harri Potter i tayemna kimnata","Harry Potter dan Kamar Rahasia","Harr