INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('harry-potter-va-can-phong-bi-mat', 'Harry Potter và Căn Phòng Bí Mật', 'Harry Potter and the Chamber of Secrets', 'harry potter và căn phòng bí mật harry potter and the chamber of secrets daniel radcliffe rupert grint emma watson kenneth branagh toby jones robbie coltrane richard harris alan rickman tom felton jason isaacs shirley henderson richard griffiths julie walters bonnie wright fiona shaw maggie smith warwick davis harii pottâ to himitsu no heya hari poter i dvorana tajni garri potter i tainaya komnata khari potŭr i stayata na taĭnite o chári póter kai i kámara me ta mystiká harri potter i tayemna kimnata harry potter dan kamar rahasia harry potter a taiemna komnata harry potter y la cámara secreta 해리 포터 2 harry potter e a câmara secreta 해리포터와 비밀의 방 гарри поттер и тайная комната ハリー・ポッターと秘密の部屋 ハリーポッターと秘密の部屋 הרי פותר וחדר הסודות harry potter ja saladuste kamber 哈利·波特与密室 แฮร์รี่ พอตเตอร์กับห้องแห่งความลับ هاري بوتر وحجرة الأسرار հարրի փոթերը և գաղտնի սենյակը هری پاتر و تالار اسرار harry potter 2 harry potter 2 - chamber of secrets harry potter 2 - the chamber of secrets harry potter and the chamber of secrets', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lilo-va-stitch', 'Lilo Và Stitch', 'Lilo & Stitch', 'https://phimimg.com/upload/vod/20250530-1/fc747a38b27a79dbfd829da48ac69f3b.jpg', 'https://phimimg.com/upload/vod/20250530-1/fd94904db8149c1868f474d57275f111.jpg', '<p>Lilo &amp; Stitch là một phim hoạt hình của Walt Disney Pictures phát hành năm 2002. Phim kể về các chuyến phiêu lưu đi tìm các thí nghiệm thất lạc của Lilo và chú chó Stitch và là một trong số những bộ phim hoạt hình nổi bật nhất của Disney. Chris Sanders và Dean DeBlois đã cùng nhau viết kịch bản và đạo diễn bộ phim. Lilo &amp; Stitch đã nhận được đề cử cho Giải Oscar cho phim hoạt hình hay nhất năm 2002, giải thưởng sau đó đã thuộc về Vùng đất linh hồn (Bản Tiếng Anh của Spirited Away cũng được phát hành bởi Walt Disney Pictures).Các phần tiếp theo của bộ phim, Stitch! The Movie, Lilo &amp; Stitch 2: Stitch Has a Glitch và Leroy &amp; Stitch đã được sản xuất để phát hành thẳng dưới dạng đĩa hình. Một loạt phim truyền hình, Lilo &amp; Stitch: The Series cũng được sản xuất cho ...</p>', 'Full', 1, 'hoathinh', 'completed', 21, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Daveigh Chase","avatar":""},{"name":"Chris Sanders","avatar":""},{"name":"Tia Carrere","avatar":""},{"name":"David Ogden Stiers","avatar":""},{"name":"Kevin McDonald","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Zoe Caldwell","avatar":""},{"name":"Jason Scott Lee","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Susan Hegarty","avatar":""},{"name":"Amy Hill","avatar":""},{"name":"Steve Alterman","avatar":""},{"name":"Emily Anderson","avatar":""},{"name":"Jack Angel","avatar":""},{"name":"Bill Asing","avatar":""},{"name":"Erica Beck","avatar":""},{"name":"Bob Bergen","avatar":""},{"name":"S",