INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tha-troi-voi-doi', 'Thả Trôi Với Đời', 'Life or Something Like It', 'https://phimimg.com/upload/vod/20250511-1/bf486875f12acea81992a9aafa57d381.jpg', 'https://phimimg.com/upload/vod/20250511-1/fa7fcdf8e86b674709b841237f793d33.jpg', '<p>Một phóng viên Lanie Kerrigan phỏng vấn một người đàn ông vô gia cư tâm linh cho một mảnh ghép về điểm số của một trò chơi bóng đá. Thay vào đó, anh nói với cô rằng cuộc sống của cô không có ý nghĩa gì và sẽ kết thúc chỉ sau vài ngày, điều này khiến cô phải hành động, cố gắng thay đổi mô hình cuộc sống của cô ...</p>', 'Full', 1, 'single', 'completed', 21, 2002, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Angelina Jolie","avatar":""},{"name":"Edward Burns","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Christian Kane","avatar":""},{"name":"Melissa Errico","avatar":""},{"name":"Lisa Thornhill","avatar":""},{"name":"Stockard Channing","avatar":""},{"name":"Gregory Itzin","avatar":""},{"name":"Max Baker","avatar":""},{"name":"Christopher Shyer","avatar":""},{"name":"James Gammon","avatar":""},{"name":"Jesse Rutherford","avatar":""},{"name":"Veena Sood","avatar":""},{"name":"Victoria Deschanel","avatar":""},{"name":"David Dunard","avatar":""},{"name":"Andromeda Dunker","avatar":""},{"name":"Er","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Life or Something Like That","Una vida en siete días","Life or Something Like It"]', 1784690324531);
