INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-luan-hoi-sinh-tu', 'Vòng Luân Hồi Sinh Tử', 'Samsara', 'https://phimimg.com/upload/vod/20250511-1/25fef1ad899f69df9da6ace00fae1ab2.jpg', 'https://phimimg.com/upload/vod/20250511-1/fb493e9fda7bc2dcdee1b6d9abf088f7.jpg', '<p>Samsara (2001) là một tác phẩm điện ảnh độc đáo và sâu sắc đến từ điện ảnh châu Á, đặc biệt thu hút khán giả không chỉ bởi nội dung đầy chất triết lý mà còn bởi sự góp mặt của Chung Lệ Đề (Christy Chung) – nữ diễn viên nổi tiếng với vẻ đẹp gợi cảm và phong cách diễn xuất phóng khoáng.</p>', 'Full', 1, 'single', 'completed', 21, 2002, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Shawn Ku","avatar":""},{"name":"Christy Chung Lai-Tai","avatar":""},{"name":"Neelesha Barthel","avatar":""},{"name":"Lhakpa Tsering","avatar":""},{"name":"Tenzin Tashi","avatar":""},{"name":"Jamayang Jinpa","avatar":""},{"name":"Jampa Kalsang Tamang","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["轮回","Samsara","འཁོར་བ།"]', 1784690324531);
