INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-bang-ha', 'Kỷ Băng Hà', 'Ice Age', 'https://phimimg.com/upload/vod/20250412-1/3ca28d9176882ca5769cd9def292b479.jpg', 'https://phimimg.com/upload/vod/20250412-1/55653fd65104d06b8e93dcd96b4eb730.jpg', '<p>Giữa thời điểm sắp chuyển sang chuyển sang kỷ băng giá, mọi con vật đều đi kiếm nơi ấm áp để sống. Manny, Sid, Diego phải theo bước chân con người để đưa 1 cậu bé bị lạc trở về với gia đình...nhưng Diego lại có một âm mưu khác để bắt chú bé đi vì Diego là 1 chú cọp nhận nhiệm vụ bắt sống đứa bé về cho Soto... Nhưng suốt quá trình trải qua những khó khăn cùng nhau 3 người bạn đã có được những tình cảm thật thân thiết để rồi cùng nhau chống lại đàn cọp gian ác.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2002, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ray Romano","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Denis Leary","avatar":""},{"name":"Goran Višnjić","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Cedric the Entertainer","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Diedrich Bader","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Lorri Bagley","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Peter Ackerman","avatar":""},{"name":"P.J. Benjamin","avatar":""},{"name":"Josh Hamilton","avatar":""},{"name":"Chris Wedge","avatar":""},{"name":"Denny Dillon","avatar":""},{"name":"Mitzi McCall","avatar":""},{"name":"Tara","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Ledeno doba","I epochí ton pagetónon","Lʹodovykovyy peri