INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-thao-thoi-vang-bong', 'Mê Thảo Thời Vang Bóng', 'Me Thao A Time Of Past Glory', 'https://phimimg.com/upload/vod/20250406-1/2fb8441dc5d20aad6acd45ae9191b2ce.jpg', 'https://phimimg.com/upload/vod/20250406-1/10cd1b93c7a423221c0dbeaff5559cdb.jpg', '<p>Nguyễn, chủ nhân ấp Mê Thảo, tài giỏi nhân đức được bà con kính trọng nhưng sau khi vị hôn thê bất ngờ qua đời vì tai nạn xe thì Nguyễn trở nên điên loạn, sống đau khổ và căm thù “sản phẩm văn minh”. Mê Thảo chìm trong u ám cùng nỗi đau của Nguyễn. Tam thương bạn, tìm mọi cách kể cả dùng tính mạng của mình để cứu Nguyễn. Nhưng liệu Mê Thảo có vượt qua được kiếp nạn lụi tàn?</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Đơn Dương","avatar":""},{"name":"Dũng Nhi","avatar":""},{"name":"Nguyễn Minh Trang","avatar":""},{"name":"Thúy Nga","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324531);
