INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-tinh-2002', 'Ngoại Tình', 'Unfaithful', 'https://phimimg.com/upload/vod/20231120-1/3279f72f1baf79889535f677eb974612.jpg', 'https://phimimg.com/upload/vod/20231120-1/1851a6b139d0078de9155d56d7952ab8.jpg', '<p>Là một người vợ hiền, một người mẹ với đứa con dễ thương và có một người chồng giỏi giang nhưng Connie đã vô tình rơi vào cạm bẫy tình và ngoại tình với một chàng trai trẻ trong một buổi chiều mưa tầm tã. Chồng cô, Edward khi phát hiện ra mối quan hệ đã nổi giận lôi đình và vô tình giết chết người tình của vợ. Unfaithful là tác phẩm điện ảnh khá hoàn hảo ở thể loại tâm lý, từ kết cấu kịch bản...</p>', 'Full', 1, 'single', 'completed', 34, 2002, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Richard Gere","avatar":""},{"name":"Diane Lane","avatar":""},{"name":"Olivier Martinez","avatar":""},{"name":"Erik Per Sullivan","avatar":""},{"name":"Zeljko Ivanek","avatar":""},{"name":"Dominic Chianese","avatar":""},{"name":"Kate Burton","avatar":""},{"name":"Chad Lowe","avatar":""},{"name":"Gary Basaraba","avatar":""},{"name":"Myra Lucretia Taylor","avatar":""},{"name":"Michelle Monaghan","avatar":""},{"name":"Margaret Colin","avatar":""},{"name":"Lisa Emery","avatar":""},{"name":"Michael Emerson","avatar":""},{"name":"Geoffrey Nauffts","avatar":""},{"name":"Joseph Badalucco","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324531);
