INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-linh-ky-hieu-lam-phan-2', 'Bản Lĩnh Kỷ Hiểu Lam (Phần 2)', 'The Bronze Teeth (Season 2)', 'https://phimimg.com/upload/vod/20250311-1/2e96c9f2cf33b984bd3646e9599e6549.jpg', 'https://phimimg.com/upload/vod/20250311-1/abca3ebad102a064788cd8b0894e5d2c.jpg', '<p>Bộ phim dựa trên câu chuyện có thật về một đại học sĩ đời vua Càn Long, triều Thanh - Kỷ Hiểu Lam, một học sĩ ngay thẳng, tương phản với đại thần Hoà Thân tham lam. Cốt truyện tập trung xung quanh những vấn đề mà nhà Thanh phải đối đầu, cùng với những pha hài hước vô cùng thú vị giữa ba nhân vật Càn Long, Kỷ Hiểu Lam và Hòa Thân.</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 12, 2002, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Quốc Lập","avatar":""},{"name":"Vương Cương","avatar":""},{"name":"Trương Thiết Lâm","avatar":""},{"name":"Viên Lập","avatar":""},{"name":"Dương Thiên Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["The Eloquent Ji Xiaolan","The Bronze Teeth","철치동아 기효람","Bản Lĩnh Kỷ Hiểu Lam","铁齿铜牙纪晓岚"]', 1784690324531);
