INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-cua-nhung-chiec-nhan-hai-toa-thap', 'Chúa Tể Của Những Chiếc Nhẫn: Hai Tòa Tháp', 'The Lord of the Rings: The Two Towers', 'https://phimimg.com/upload/vod/20250219-1/443c06cdcf69accdf1015367e7190ee4.jpg', 'https://phimimg.com/upload/vod/20250219-1/5d70b0eaa932fa04eeccbdf588913a87.jpg', '<p>Cuộc hành trình đi hủy diệt chiếc nhẫn tiếp tục với bao nguy hiểm chờ đợi Frodo ở phía trước. Lần này, anh và Sam có một bạn đồng hành mới là Gollum. Trong khi đó, Gandalf may mắn thoát chết, hơn nữa sức mạnh của ông còn vượt xa hơn rất nhiều. Ông cùng Aragon, Legolas và Gimli cùng những thần rừng tìm cách phá hủy âm mưu của Saruman. Tiếp nối thành công của phần 1 The Lord Of The Ring 2 kế thừa và đan xen giữa hai hệ thống nhân vật cũ và mới làm cho nội dung phim càng thêm lôi cuốn người xem. The Lord Of The Ring 2 cũng mang về 2 Giải Oscar cho hạng mục âm thanh và kĩ xảo.</p>', 'Full', 1, 'single', 'completed', 23, 2002, 'Vietsub', 'FHD', 'New Zealand', 0, '[{"name":"Elijah Wood","avatar":""},{"name":"Ian McKellen","avatar":""},{"name":"Viggo Mortensen","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"John Rhys-Davies","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Bernard Hill","avatar":""},{"name":"Miranda Otto","avatar":""},{"name":"Dominic Monaghan","avatar":""},{"name":"Billy Boyd","avatar":""},{"name":"Christopher Lee","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Liv Tyler","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"David Wenham","avatar":""},{"name":"Brad Dourif","avatar":""},{"name":"Karl Urban","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Le Seigneur des Anneaux: Les Deux Tours","The Lord of the Rings 2: The Two Towers","魔戒二部曲：雙城奇謀","Господар на прстените: Двете кули","ศึกหอคอยคู่กู้พิภพ","The Lord of the Rings II: The Two Towers","El señor de los anillos: Las dos torres","Chúa Tể Của Những Chiếc Nhẫn 2: Hai Tòa Tháp","ロード・オブ・ザ・リング／二つの塔：2002","Üzüklərin Hökmdarı:İki Qala","Yüzüklerin Efendisi: İki Kule","ロード・オブ・ザ・リング／二つの塔","The Lord of the Rings The Two Towers","LOTR2 - The Two Towers","魔戒2 雙城奇謀","Le Seigneur des anneaux Les Deux Tours - version Longue","Մատանիների Տիրակալը 2","Der Herr der Ringe - Die zwei Tuerme","Властелин колец 2","Il Signore degli Anelli: Le due Torri","The Lord of the Rings: The Two Towers"]', 1784690324531);
