INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-dien-danh-vong', 'Sàn Diễn Danh Vọng', 'Chicago', 'https://phimimg.com/upload/vod/20241224-1/8b658ac35b4c4dfc45e55a39e9878b47.jpg', 'https://phimimg.com/upload/vod/20241224-1/f8db1d0b73307743dad08b6492a9caeb.jpg', '<p>Sau thành công vang dội của &quot;Moulin rouge&quot;, vào năm 2001, một năm sau đó, Hollywood đã kịp tung ra một bộ phim nhạc kịch mang tên Chicago. Dường như thể loại nhạc kịch đã hồi sinh sau một thời gian &quot;ngủ yên&quot; đến mấy thập kỉ. Phim có độ dài 113 phút được phát hành vào 2002. Chicago, những năm 20. Ai cũng muốn trở thành nổi tiếng nhưng ở một thành phố bon chen, xô bồ như Chicago thì cơ hội mở ra thật chật hẹp. Nàng Roxie Hart ( Renée Zellweger ) tuy đã cưới anh chàng cục mịch mà chung tình Amos ( John C. Reilly ) nhưng còn léng phéng với tên Fred Casely ( Dominic West ). Phim thuộc thể loại phim Tình Cảm. Cô luôn mơ tưởng một ngày nào đó sẽ trở nên nổi tiếng. Tên Fred luôn liến thoắng hứa giúp đỡ Roxie trên đường công danh nhưng một đêm, sau khi hú hí ...</p>', 'Full', 1, 'single', 'completed', 10, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Renée Zellweger","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Richard Gere","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Ekaterina Chtchelkanova","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Christine Baranski","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Taye Diggs","avatar":""},{"name":"Colm Feore","avatar":""},{"name":"Dominic West","avatar":""},{"name":"Mya","avatar":""},{"name":"Deidre Goodwin","avatar":""},{"name":"Denise Faye","avatar":""},{"name":"Susan Misner","avatar":""},{"name":"Cliff Saunders","avatar":""},{"name":"Jayne Eastwood","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["漫舞芝加哥","시카고","Чикагo","Chicago (Diamond Edition)","Chicago"]', 1784690324531);
