INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-day-thi', 'Tuổi Dậy Thì', 'Ken Park', 'https://phimimg.com/upload/vod/20231212-1/e14a7b42d315a6d39462f1b045340b3f.jpg', 'https://phimimg.com/upload/vod/20231212-1/1b22d2a54d32cae00e51448a00b0dc0d.jpg', '<p>Ken Park tập trung vào một số thanh thiếu niên và cuộc sống gia đình đau khổ của họ. Shawn dường như là thông thường nhất. Tate tràn ngập cơn thịnh nộ tâm thần; Claude thường xuyên bị quấy rối bởi người cha tàn bạo của mình và được nuông chiều khá khó chịu bởi người mẹ đang mang thai to lớn của mình. Peaches chăm sóc người cha sùng đạo của cô, nhưng lại khao khát tự do. Tất cả đều khá chặt chẽ, hoặc vì vậy họ tuyên bố.</p>', 'Full', 1, 'single', 'completed', 10, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Ransone","avatar":""},{"name":"Tiffany Limos","avatar":""},{"name":"Stephen Jasso","avatar":""},{"name":"James Bullard","avatar":""},{"name":"Mike Apaletegui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324531);
