INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phia-ben-kia-cua-giuong', 'Phía Bên Kia Của Giường', 'The Other Side Of The Bed', 'https://phimimg.com/upload/vod/20241105-1/82e93974386880577a4cb0990d83fd46.jpg', 'https://phimimg.com/upload/vod/20241105-1/6c2e43c257bdeda68905b4e3c133933d.jpg', '<p>Khi Paula rời xa người bạn đời Pedro, anh nhớ cô và tìm kiếm sự an ủi bên những người bạn thân nhất của mình, Javier và Sonia. Paula đang ngoại tình với Javier. Pedro cố gắng tìm ra ai là người tình bí mật của Paula và thuê thám tử tư. Trong khi đó, khi đang an ủi Pedro, Sonia đã có tình một đêm với anh và Javier cho rằng cô đang lừa dối anh với người bạn đồng tính nữ Luzia.</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Ernesto Alterio","avatar":""},{"name":"Paz Vega","avatar":""},{"name":"Guillermo Toledo","avatar":""},{"name":"Natalia Verbeke","avatar":""},{"name":"Alberto San Juan","avatar":""},{"name":"María Esteve","avatar":""},{"name":"Ramón Barea","avatar":""},{"name":"Nathalie Poza","avatar":""},{"name":"Carol Salvador","avatar":""},{"name":"Geli Albaladejo","avatar":""},{"name":"Blanca Marsillach","avatar":""},{"name":"Coté Soler","avatar":""},{"name":"Luis Bermejo","avatar":""},{"name":"Curro Iglesias","avatar":""},{"name":"Javier Gutiérrez","avatar":""},{"name":"Mohamed Khashoggi","avatar":""},{"name":"Da","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["The Wrong Side of the Bed","El otro lado de la cama"]', 1784690324531);
