INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-tinh-tat-nguyen-2', 'Thú Tính Tật Nguyền 2', 'Crime Of A Beast 2', 'https://phimimg.com/upload/vod/20241101-1/0f1c73e5b6d09895090ca95fdabe9f02.jpg', 'https://phimimg.com/upload/vod/20241101-1/53f1a9b62239af5bf66878b9e1b3b65f.jpg', '<p>Một tai nạn đã kéo những người lạ Rex, Amy và Ivy cùng đến một hòn đảo xa xôi. Amy yêu Rex nhưng không chỉ quan hệ tình dục với Amy, Rex còn quyết định trở thành Vua của hai Nữ hoàng trên đảo trong suốt cuộc đời. Biết Rex là người như thế nào, Amy quyết định rời hòn đảo cùng Ivy. Liệu số phận có đối xử tốt với họ?</p>', 'Full', 1, 'single', 'completed', 22, 2002, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"林雅诗","avatar":""},{"name":"Sophie Ngan","avatar":""},{"name":"Alvin Cheung Jeung Man","avatar":""},{"name":"Raymond Tsang Chau-Ming","avatar":""},{"name":"Chung Kwok Keung","avatar":""},{"name":"Kelvin Won Chun Ming","avatar":""},{"name":"秦煌","avatar":""},{"name":"Leung Siu-Dik","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Zung gik keung gan II: Yuen si sau sing","Crime of Beast 2","終極強姦II：原始獸性"]', 1784690324531);
