INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thu-tinh-tat-nguyen-2', 'Thú Tính Tật Nguyền 2', 'Crime Of A Beast 2', 'thú tính tật nguyền 2 crime of a beast 2 林雅诗 sophie ngan alvin cheung jeung man raymond tsang chau-ming chung kwok keung kelvin won chun ming 秦煌 leung siu-dik zung gik keung gan ii: yuen si sau sing crime of beast 2 終極強姦ii：原始獸性', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-thu-coc', 'Đoạn Thù Cốc', 'Peaceful Valley', 'https://phimimg.com/upload/vod/20240923-1/0f41889d4e9565bcfd76dc48f1982807.jpg', 'https://phimimg.com/upload/vod/20240923-1/239fa5c0a7583fa7f521d2793d668886.jpg', '<p>Đoạn Thù Cốc kể về việc đại tướng quân Vạn Bá Long phụng mệnh Phúc thân vương dẫn theo quan binh đuổi giết con chim ưng đã làm ái thiếp của thân vương bị thương. Khi cuộc chiến đang diễn ra ác liệt trên sa mạc, bỗng nổi lên một trận bão cát. Trong giây phút thập tử nhất sinh, Vạn Bá Long và binh lính của ông được con chim ưng chỉ hướng, tìm được lối thoát... Từ đó, đội quân của Vạn Bá Long giác ngộ chân lý thiện ác, quyết tâm rửa tay gác kiếm, thề không trở lại Trung Nguyên phục dịch triều đình, họ tìm đến một sơn cốc sinh sống, đặt tên sơn cốc là &#39;Đoạn thù cốc&#39;. Nghĩa tử của Vạn Bá Long là Thạch Hạo Thiên, là một người tuổi trẻ tài cao, cương trực. Một lần, anh cứu được Phương Hữu Vi và tiểu thư Bạch Tuyền của một gia đình danh gia vọng tộc ở trấn Hòa Bình, nhưng tấm lòng của Thạch Hạo Thiên lại vô tình khơi ngòi những ân oán giang hồ sau bao nhiêu năm &#39;Đoạn thù cốc&#39; không dính líu đến...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 11, 2002, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồng Kim Bảo","avatar":""},{"name":"Quan Lễ Kiệt","avatar":""},{"name":"Kỳ Diễm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["群雄武侠传之断肠谷","Duan Chou Gu","断仇谷"]', 1784690324531);
