INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naruto', 'Naruto', 'Naruto', 'https://phimimg.com/upload/vod/20240902-1/b6351dd1c32a103effae4d0c28093061.jpg', 'https://phimimg.com/upload/vod/20240902-1/7dcfa841d910cc96425432f893f2a192.jpg', '<p>Bộ phim kể về cậu về quá trình lớn lên và cuộc đời của cậu bé những nguy hiểm mà cậu đã gặp phải kèm theo đó là một động lực và niềm tin phi thường , một tâm hồn trong sáng chứa đựng những trò nghịch ngợm bướng bỉnh nhưng đầy hồn nhiên . Cùng với việc xoay quanh những người đã bỏ mạng do tranh giành quyền lực cộng với sự đau thương , mất mát mà Naruto đã trải qua.</p>', 'Hoàn Tất (220/220)', 220, 'hoathinh', 'completed', 14, 2002, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"竹内順子","avatar":""},{"name":"杉山紀彰","avatar":""},{"name":"中村千絵","avatar":""},{"name":"井上和彦","avatar":""},{"name":"柴田秀勝","avatar":""},{"name":"遠近孝一","avatar":""},{"name":"江原正士","avatar":""},{"name":"増川洋一","avatar":""},{"name":"田村ゆかり","avatar":""},{"name":"柚木涼香","avatar":""},{"name":"森久保祥太郎","avatar":""},{"name":"伊藤健太郎","avatar":""},{"name":"川田紳司","avatar":""},{"name":"水樹奈々","avatar":""},{"name":"鳥海浩輔","avatar":""},{"name":"石川英郎","avatar":""},{"name":"Tomoyuki Dan","avatar":""},{"name":"関俊彦","avatar":""},{"name":"神奈延年","avatar":""},{"name":"くじら","avatar":""},{"name":"大塚芳忠","avatar":""},{"name":"Keiko Nemoto","avatar":""},{"name":"朴璐美","avatar":""},{"name":"小杉十郎太","avatar":""},{"name":"勝生真沙子","avatar":""},{"name":"Rumi Ochiai","avatar":""},{"name":"加瀬康之","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id"