INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-the-khuat-phuc', 'Không Thể Khuất Phục', 'Lofty Waters Verdant Bow', 'https://phimimg.com/upload/vod/20240625-1/54987a1cbf418e3bd58c06a5925dbad7.jpg', 'https://phimimg.com/upload/vod/20240625-1/a78af7d56363a6cf8898cc75f04baeba.jpg', '<p>The story starts off with Gam Sai Wai when he embarks on his journey to find Lui Sei Leong to get rid of the poison that is passed on by his master into his body. Sai Wais master had died because of the poison and before his death, he had told Sai Wai to go find Lui Sei Leong because she can help him. During his journey, he makes friends with lots of people and meets two women who love him very much. The two women are Lai Shing Nam and Kuk Chi Wah. He also gets caught in the affairs of the martial arts world during his journey and keeps on helping the good people, especially Lai Shing Nam and Kuk Chi Wah to fight for justice until he becomes the hero without realizing it.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2002, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Lâm Phong","avatar":""},{"name":"Diệp Tuyền","avatar":""},{"name":"Lý Thể Hoa","avatar":""},{"name":"Cao Hùng","avatar":""},{"name":"Trương Triệu Huy","avatar":""},{"name":"Trần Quốc Bang","avatar":""},{"name":"La Mẫn Trang","avatar":""},{"name":"Lạc Ứng Quân","avatar":""},{"name":"Phùng Hiểu Văn","avatar":""},{"name":"Viên Thể Vân","avatar":""},{"name":"Quách Chính Hồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324531);
