INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-the-khuat-phuc', 'Không Thể Khuất Phục', 'Lofty Waters Verdant Bow', 'không thể khuất phục lofty waters verdant bow lâm phong diệp tuyền lý thể hoa cao hùng trương triệu huy trần quốc bang la mẫn trang lạc ứng quân phùng hiểu văn viên thể vân quách chính hồng ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-6-bong-ma-duong-baker', 'Thám Tử Lừng Danh Conan 6: Bóng Ma Đường Baker', 'Detective Conan: The Phantom of Baker Street', 'https://phimimg.com/upload/vod/20231019-1/63b25b83c4eb493350b9c6e18eb6e802.jpg', 'https://phimimg.com/upload/vod/20231019-1/a042bf0433e2beba6e0e125797271402.jpg', '<p>Với sự phát triển của công nghệ, một trò chơi mới ra đời và chỉ được giành cho các con cháu của quan chức Nhật Bản. Conan và Đội Thám Tử Nhí lớp 1B cũng có cơ hội được mời đến tham gia trò chơi máy tính ảo mới này. Tuy nhiên, người lập trình trò chơi đã phát biểu rằng nếu mọi người không thể trả lời câu đố trong trò chơi, tất cả họ đều phải chết. Conan nhanh chóng nhận ra đây là một cạm bẫy nguy hiểm đến tính mạng, cậu buộc phải chiến thắng để cứu mọi người. Liệu trò chơi ma quái này có buông tha những đứa trẻ hay không?</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2002, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Hideyuki Tanaka","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Rikako Aikawa","avatar":""},{"name":"Yuzuru Fujimoto","avatar":""},{"name":"Kei Hayami","avatar":""},{"name":"Show Hayami","avatar":""},{"name":"Hiroaki Hirata","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324531);
