INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('public-enemy', 'Public Enemy', 'Public Enemy', 'public enemy public enemy 설경구 이성재 강신일 김정학 도용구 안내상 이문식 성지루 유해진 lee kan-hee 이정헌 기주봉 김윤아 김희선 oh seung-myeong park seoung-tae 서태화 양은용 이석구 안진수 양재성 윤문식 kim gyeong-ryong kim kang-il 유명순 권병길 안석환 hong soon-chang 전수경 won woong-jae lim seung-dae kim tae-hwan j ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-den-nhi-do-7-song-thien-chi-ton', 'Nhất Đen Nhì Đỏ 7 - Song Thiên Chí Tôn', 'Who''s The Winner 7', 'https://phimimg.com/upload/vod/20240609-1/b562e2a8a2f1e8672b4317fc8a3786f2.jpg', 'https://phimimg.com/upload/vod/20240609-1/396d8dc215e3577ec7611ff06c499ec0.jpg', '<p><em>Câu chuyện kể về mối thâm thù giữa hai nhà họ Ngôn Khôn – Long Đình Quang khi cùng nhau đấu một ván sinh tử để giành đảo San Hô. Họ Long đã thắng trong ván bài này còn nhà họ Ngôn phảitrốn đi để bảo toàn mạng sống. Quá khứ tưởng đã đi vào quên lãng, nhưng trớ trêu thay, con trai nhà họ Ngôn là Ngôn Phi và con gái nhà họ Long là Long Kỳ Phương đã gặp gỡ và yêu nhau. Mọi chuyện trở nên rắc rối hơn, khi nhà họ Long phát hiện ra Ngôn Khôn còn sống và Ngôn Phi là hậu duệ của kẻ thù không đội trời chung. Trong lúc nghi ngờ, vì muốn trả thù cho cha, Ngôn Phi đã lừa dối chính người yêu của mình, nói dối với Kỳ Phương mình không phải Ngôn Phi, chờ ngày có cơ hội trả thù Long Đình Quang cho cha mình. Giấy không gói được lửa cuối cùng sự thật cũng dần sángtỏ, thân thế của Ngôn Phi lộ ra. Nhưng lúc này, Kỳ Phương cũng đã mang dòng máu của họ Ngôn. Ngôn Phi xin Kỳ Phương tha thứ bởi anh vẫn rất yêu Kỳ Phương và vì đứa con sắp chào đời. Ngôn Phi hoàn thành tâm nguyện trả thù cho cha. Long Đình Quang bị điên, Ngôn Khôn cũng đi biệt tích giang hồ. Kỳ Phương sinh cho Ngôn Phi một bé trai đặt tên là Ngôn Tinh. Kỳ Phương luôn ray rứt vì mối tình ngang trái với Ngôn Phi, yêu, hận giằng xé. Sau một lần gặp tai nạn, Kỳ Phương bị mất trí nhớ và được em nuôi Lạc Văn Hân nhờ Huỳnh Ngũ chăm sóc và đưa ra nước ngoài sinh sống. Ngôn Phi và Kỳ Phương lại xa cách. khoảng thời gian này, Ngôn Phi càng đau khổ nhận ra rằng: trái tim anh chỉ có hình ảnh của Kỳ Phương.</em></p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 11, 2002, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Lý Nam Tinh","avatar":""},{"name":"Lý San San","avatar":""},{"name":"Trịnh Huệ Ngọc","avatar":""},{"name":"Du Ký","avatar":""},{"name":"Ngô Chấn Vũ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324531);
