INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-den-nhi-do-7-song-thien-chi-ton', 'Nhất Đen Nhì Đỏ 7 - Song Thiên Chí Tôn', 'Who''s The Winner 7', 'nhất đen nhì đỏ 7 - song thiên chí tôn who''s the winner 7 lý nam tinh lý san san trịnh huệ ngọc du ký ngô chấn vũ ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-cau-2002', 'Tinh Cầu', 'The Star', 'https://phimimg.com/upload/vod/20240628-1/a96c115f0edb000ed834eed5b8ba8699.jpg', 'https://phimimg.com/upload/vod/20240628-1/139ada2b77656cc3d91245ebf6b9cc3c.jpg', '<p>Zvezda (Tinh Cầu) là bộ phim tâm lý chiến tranh kể về sư đoàn Hồng quân - những chiến sĩ tinh nhuệ, dạn dày lửa đạn, tuy cá tính rất khác nhau nhưng tất cả đều giống nhau ở lí tưởng và mục đích chiến đấu cao cả: Vì Tổ quốc, sẵn sàng hi sinh !. Mà nhân vật trung tâm là đội trưởng Trung úy Travkin. Trong đơn vị, anh là một con người điềm tĩnh, ít nói, sống chan hòa với đồng đội, trong chiến đấu, anh là người chỉ huy mưu trí, quả cảm, luôn dẫn dắt đơn vị hoàn thành nhiệm vụ. Không chỉ dành được sự tín nhiệm tuyệt đối của các cấp chỉ huy và anh em trong đơn vị, Travkin còn chiếm được tình yêu nồng thắm của cô hiệu thính viên xinh đẹp Katya. Giữa cánh rừng trận mạc, mối tình thi vị, trong sáng của Travkin và Katya ngân vang như một khúc ca lãng mạn, làm nổi bật vẻ đẹp dịu dàng mà gan góc của tâm hồn Nga, một vẻ đẹp cứu rỗi cả thế giới.</p>', 'Full', 1, 'single', 'completed', 26, 2002, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Igor Petrenko","avatar":""},{"name":"Artyom Semakin","avatar":""},{"name":"Aleksei Panin","avatar":""},{"name":"Aleksei Kravchenko","avatar":""},{"name":"...","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324531);
