INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-cau-2002', 'Tinh Cầu', 'The Star', 'tinh cầu the star igor petrenko artyom semakin aleksei panin aleksei kravchenko ... ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyet-han', 'Huyết Hận', 'Blood Work', 'https://phimimg.com/upload/vod/20240628-1/f7ed37c5b8f0a0320e8a6447a360871b.jpg', 'https://phimimg.com/upload/vod/20240628-1/68ed49d7d495744bb80c6f7b31514609.jpg', '<p>Clint Eastwood vốn rất thích những kịch bản trong đó những tên giết người tâm thần luôn thích chơi trò mèo vờn chuột với cớm. Từ phim Dirty Harry cho tới In the line of fire và nay là  Blood Work, một lần nữa anh cớm già phải tức tưởi xin về hưu sau vụ bắn hụt tên giết người tâm thần có biệt danh The code killer. Hai năm sau đó, Terry McCabb vẫn âm thầm săn lùng tên giết người, và tên  The code killer này vẫn âm thầm gài bẫy anh, vì hắn chỉ muốn làm cho anh chết vì uất ức. Và Terry rơi vào bẫy của hắn, một cái bẫy mang tính chất lừa lọc, phản bội và đẫm đầy máu, nhưng đây là lần cuối cùng, Terry không để vụt kẻ thù trong đời này.</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Clint Eastwood","avatar":""},{"name":"Jeff Daniels","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Wanda De Jesus","avatar":""},{"name":"Tina Lifford","avatar":""},{"name":"Paul Rodríguez","avatar":""},{"name":"Dylan Walsh","avatar":""},{"name":"Mason Lucero","avatar":""},{"name":"Gerry Becker","avatar":""},{"name":"Rick Hoffman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324531);
