INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('k19-tau-ngam-tu-than', 'K-19: Tàu Ngầm Tử Thần', 'K-19: The Widowmaker', 'https://phimimg.com/upload/vod/20240616-1/a18a3bc02cf154daf722fc4a6711a7ca.jpg', 'https://phimimg.com/upload/vod/20240616-1/f9994e64823ba7178d2028cae27a3ebe.jpg', '<p>Trong phim K-19: The Widowmaker (K-19: Tàu Ngầm Tử Thần) (2002), để đáp trả hành động khiêu khích của Nhà Trắng, bộ chỉ huy tối cao Nga quyết định đưa K-19, tàu ngầm nguyên tử đầu tiên của mình án ngữ vùng biển giữa New York và Washington. Không may lò phản ứng hạt nhân của tàu gặp sự cố đe doạ phát nổ, buộc thủy thủ đoàn phải chạy đua với thời gian để cứu nhân loại tránh khỏi cuộc chiến tranh hủy diệt …</p>', 'Full', 1, 'single', 'completed', 9, 2002, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Joss Ackland","avatar":""},{"name":"John Shrapnel","avatar":""},{"name":"Donald Sumpter","avatar":""},{"name":"Tim Woodward","avatar":""},{"name":"Steve Nicolson","avatar":""},{"name":"George Anton","avatar":""},{"name":"James Francis Ginty","avatar":""},{"name":"Lex Shrapnel","avatar":""},{"name":"Ingvar E. Sigurðsson","avatar":""},{"name":"Sam Spruell","avatar":""},{"name":"Sam Redford","avatar":""},{"name":"Peter Stebbings","avatar":""},{"name":"Roman Podhora","avatar":""},{"name":"Shaun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324531);
