INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tinh-ca-mua-dong', 'Bản Tình Ca Mùa Đông', 'Winter Sonata', 'https://phimimg.com/upload/vod/20240606-1/2898843403f004d06d6b249a813b9887.jpg', 'https://phimimg.com/upload/vod/20240606-1/f12326a33951e80ee283605398efcd8e.jpg', '<p>Kang Joon-sang, con một nghệ sĩ piano nổi tiếng. Do hoàn cảnh gia đình, anh không thực sự hoà nhập được với mọi người và cũng ít khi thể hiện bản thân mình. Mẹ anh luôn nói rằng cha anh đã mất, nhưng bằng linh cảm của chính mình, anh tin rằng cha anh vẫn còn sống. Sau này khi lớn lên, anh đã quay trở về quê hương mình, nơi cha mẹ anh đã từng yêu nhau, để tìm tung tích về người cha ruột. Joon-sang chuyển đến 1 trường trung học nơi Yoo-jin (Choi Ji-woo thủ vai) đang theo học. Hai người đã gặp nhau và yêu nhau. Nhưng oái ăm thay, chính lúc này, Joon-sang khám phá ra rằng, có thể cha anh chính là người cha trước đây của Yoo-Jin. Joon-sang đã quyết định ra đi nhưng vẫn muốn gặp Yoo-Jin lần cuối. Chính thời khắc đó, anh bất ngờ bị tai nạn ô tô…</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2002, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"배용준","avatar":""},{"name":"박솔미","avatar":""},{"name":"최지우","avatar":""},{"name":"박용하","avatar":""},{"name":"정동환","avatar":""},{"name":"이혜은","avatar":""},{"name":"류승수","avatar":""},{"name":"장항선","avatar":""},{"name":"Won-joong Jeong","avatar":""},{"name":"하재영","avatar":""},{"name":"김해숙","avatar":""},{"name":"이효춘","avatar":""},{"name":"송옥숙","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324531);
