INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-gia-hoan-luong-2', 'Bố Già Hoàn Lương 2', 'Analyze That', 'https://phimimg.com/upload/vod/20240228-1/0b347e3417e7ff17dca95d5630335858.jpg', 'https://phimimg.com/upload/vod/20240228-1/013a5d815fe64c36bbf4631c93257180.jpg', '<p>Trong phần tiếp theo này, sau khi ra khỏi nhà tù SingSing, Paul Vitti lại bị đưa đến gặp bác sĩ Ben Sobe. Ông trùm mafia này cần có sự giúp đỡ của Sobel để có thể trở lại cuộc sống bình thường. Vì thế, bác sĩ Sobel giờ đây rơi vào thế tiến thoái lưỡng nan, cuộc sống của ông và gia đình thêm một lần nữa bị xáo trộn vì sự hiện diện thường trực của tên trùm mafia trong căn nhà của mình. Nhiệm vụ của ông là phải giúp tên trùm trở lại cuộc sống lương thiện càng nhanh càng tốt.</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Billy Crystal","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Joe Viterelli","avatar":""},{"name":"Cathy Moriarty","avatar":""},{"name":"Joey Diaz","avatar":""},{"name":"Jerome Le Page","avatar":""},{"name":"Joseph Bono","avatar":""},{"name":"Brian Rogalski","avatar":""},{"name":"Thomas Rosales Jr.","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324531);
