INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-may-thoi-gian', 'Cỗ Máy Thời Gian', 'The Time Machine', 'https://phimimg.com/upload/vod/20240220-1/3fa8da79cace67b229b53998e4eb3dcd.jpg', 'https://phimimg.com/upload/vod/20240220-1/297f01b9de23df439f49c6e9272cdae6.jpg', '<p>Dựa trên cuốn tiểu thuyết khoa học viễn tưởng kinh điển của HG Wells, nhà khoa học vừa là nhà phát minh, Alexander Hartdegen, đã chứng minh được bước đi trên thời gian là điều có thể.Quyết tâm của anh đã tạo ra khá nhiều rắc rối vì đã làm thay đổi quá khứ. Để vận hành thử cổ máy thời gian của mình, Hartdegen quay về 800000 ở tương lai, nơi ông khám phá ra rằng loài người đã phân chia ra một là kẻ đi săn và 2 là kẻ bị săn.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Guy Pearce","avatar":""},{"name":"Yancey Arias","avatar":""},{"name":"Mark Addy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324531);
