INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-lo-60', 'Xa Lộ 60', 'Interstate 60', 'https://phimimg.com/upload/vod/20240205-1/c68021ea4d1d754e50120e5271ff2976.jpg', 'https://phimimg.com/upload/vod/20240205-1/a33dc53b617d063d51ee100c4adb273a.jpg', '<p>Một họa sĩ đầy tham vọng gặp gỡ nhiều nhân vật khác nhau và học được những bài học quý giá khi đi du lịch khắp nước Mỹ.</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Marsden","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Matthew Edison","avatar":""},{"name":"Paul Brogren","avatar":""},{"name":"Wayne Robson","avatar":""},{"name":"Michael J. Fox","avatar":""},{"name":"John Bourgeois","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324531);
