INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-sung', 'Tìm Súng', 'The Missing Gun', 'https://phimimg.com/upload/vod/20240228-1/0515e37982a08cb885a0c6a97db7def0.jpg', 'https://phimimg.com/upload/vod/20240228-1/6ff01b73026929c66a33176d92411436.jpg', '<p>Trong bộ phim kinh dị căng thẳng này, Ma Shan (Wen Jiang) là một thám tử cảnh sát Trung Quốc, tỉnh dậy vào một buổi sáng sau một đêm say khướt tại tiệc cưới của em gái mình và phát hiện ra khẩu súng của mình đã bị đánh cắp. Vì chỉ có cảnh sát mới được phép mang súng, Ma Shan cảnh giác về khả năng chết người của vụ trộm, và anh bắt đầu đi tìm vũ khí của mình; tuy nhiên, ký ức về đám cưới của những người bạn của Mã Shan cũng mơ hồ như của anh, và không ai có thể biết ai đã chở anh về nhà. Tình huống trở nên căng thẳng khi bạn gái cũ của Ma Shan đến thị trấn để thăm và nhanh chóng được phát hiện bị bắn chết với những viên đạn khớp với viên đạn dùng trong súng của anh ta.</p>', 'Full', 1, 'single', 'completed', 21, 2002, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jiang Wen","avatar":""},{"name":"Ning Jing","avatar":""},{"name":"Shi Liang","avatar":""},{"name":"Liu Xiaoning","avatar":""},{"name":"Wu Yujuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324531);
