INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-van', 'Phong Vân', 'Wind And Cloud', 'https://phimimg.com/upload/vod/20240118-1/eaa636ed4a5876ff70871e2cc2e5f1ac.jpg', 'https://phimimg.com/upload/vod/20240118-1/8364c15be9401993047ae720eed2dcd2.jpg', '<p>Phong Vân - Wind And Cloud xoay quanh nhân vật Hùng Bá. Nghe theo lời phán của Ni Bồ Tát, Hùng Bá đã dốc hết sức tìm Phong Vân. Cơ duyên đã tự đến khi hắn thu nạp được được hai đệ từ xuất sắc và truyền cho mỗi người một tuyệt học: Nhiếp Phong Bộ Kinh Vân. Nhờ Phong Vân nên Hùng Bá đã nhanh chóng làm bá chủ thiên hạ. Nhưng vì tính đa nghi nên hắn đã nhờ Ni Bồ Tát phán thêm một quẻ nữa và chính quẻ này làm thay đổi mối quan hệ thầy trò giữa Hùng Bá và Phong Vân: Thành tại Phong Vân - Bại tại Phong Vân. Vậy là hắn tìm mọi cách chia rẽ 3 đệ tử của mình là Nhiếp Phong, Bộ Kinh Vân và Tần Sương để họ tự tiêu diệt lẫn nhau. Phong Vân sau khi nhận ra âm mưu của Hùng Bá đã qua rất nhiều khó khăn mới tiêu diệt được hắn. Nhưng số phận Bộ Kinh Vân và Nhiếp Phong không thể thoát ra được phân tranh võ lâm!</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 17, 2002, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Nhuận Đông","avatar":""},{"name":"Triệu Văn Trác","avatar":""},{"name":"Thiên Diệp Chân Nhất","avatar":""},{"name":"Vương Hỷ","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324531);
