INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khi-khieu-goi', 'Vũ Khí Khiêu Gợi', 'Naked Weapon', 'null', 'https://phimimg.com/upload/vod/20240207-1/581f17362d9cd0caaa6e3bcca5f5897b.jpg', '<p>Vũ Khí Khiêu Gợi - Naked Weapon xoay quanh câu chuyện người đứng đầu tổ chức giết thuê đang làm cơ quan tình báo trung ương phải đau đầu chính là Madame M (Almen Wong). Nhưng sau khi tiêu diệt vũ khí bí mật của mình, bà phải mở cuộc tuyển chọn mới, đó là lý do tại sao, trẻ em nữ khắp nơi trên thế giới bắt đầu biến mất. Đặc điểm chung của những bé gái này là tuổi từ 13 đến 14, giỏi thể thao, ngoại hình xinh xắn. Tất cả được bí mật đưa tới một hòn đảo, tập trung rèn luyện trong lò đào tạo sát thủ của Madame M. Ở đó, chúng học võ, luyện thể lực, làm quen với vũ khí hiện đại, trau dồi hiểu biết xã hội và học cách trở nên tàn nhẫn. Sau mỗi bài thi, số học viên giảm một nửa, cho đến vòng cuối cùng chỉ còn Jing (Jewel Li Fei), Charlene (Maggie Q) và Katherine (Anya).</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Maggie Q","avatar":""},{"name":"Anya","avatar":""},{"name":"Daniel Wu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324531);
