INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-dau', 'Quyết Đấu', 'Undisputed', 'https://phimimg.com/upload/vod/20240207-1/d07c69a29ebd2464ff7d5b259428f57d.jpg', 'https://phimimg.com/upload/vod/20240207-1/e8d2e4ba500316bc8db4a0f23a5bdaf2.jpg', '<p>Undisputed là bộ phim hành động kể về Monroe Hutchen từng là một tay đấm hạng nặng đầy triển vọng. Anh bất ngờ bị kết án ngộ sát và nhận án chung thân không ân xá tại nhà từ Sweetwater. Giờ đây, Monroe bị buộc tham gia những cuộc đấu không khoan nhượng được tổ chức trong ngục. Đối thủ xứng tầm xuất hiện, tay đấm James Chambers bị kết án hiếp dâm, xuất hiện tại Sweetwater. Cuộc đấu giữa hai đấu sỹ có thể mở ra cơ hội được phóng thích khi ông trùm Emmanuel treo giải thưởng một triệu đô cho cuộc đấu đẫm máu này...</p>', 'Full', 1, 'single', 'completed', 10, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wesley Snipes","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Peter Falk","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324531);
