INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-tot-dinh', 'Tội Ác Tột Đỉnh', 'High Crimes', 'https://phimimg.com/upload/vod/20240205-1/c9e7eb1c4d233a839aaf8712a430c895.jpg', 'https://phimimg.com/upload/vod/20240205-1/c21a92f664a34f1f11d099c8ab533cc8.jpg', '<p>Tội Ác Tột Đỉnh - High Crimes xoay quanh cuộc sống của Claire Kubik - một luật sư từng cãi thắng nhiều vụ án nổi tiếng. Tom Kubik, chồng cô, làm nghề thiết kế mỹ thuật. Trong mắt mọi người, họ là một cặp vợ chồng hạnh phúc, thành đạt. Mọi chuyện bắt đầu kể từ khi ngôi nhà của họ bị đột nhập. Nhận được thông báo, cảnh sát tới lấy dấu vân tay của kẻ lạ để điều tra nhưng rồi người bị bắt lại chính là người chồng. Từ đây, hàng loạt bí ẩn đã được hé lộ.</p>', 'Full', 1, 'single', 'completed', 24, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Amanda Peet","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Ashley Judd","avatar":""},{"name":"Adam Scott","avatar":""},{"name":"Jessie B''Franklin","avatar":""},{"name":"Jim Caviezel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324531);
