INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-thoi-tien-su-ix-du-hanh-den-ho-nuoc-lon', 'Vùng Đất Thời Tiền Sử IX: Du Hành Đến Hồ Nước Lớn', 'The Land Before Time IX: Journey To Big Water', 'https://phimimg.com/upload/vod/20240220-1/596a940d0c68a07b30b142030d47bc11.jpg', 'https://phimimg.com/upload/vod/20240220-1/b9369623aec5ad220f49022f77a2a55e.jpg', '<p>Sau khi kết bạn với Mo, cậu bạn giống cá heo đang lạc đường, Littlefoot và hội bạn dũng cảm tham gia chuyến phiêu lưu ra Đại Hải để đưa Mo trở về nhà.</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Ingle","avatar":""},{"name":"Kenneth Mars","avatar":""},{"name":"Miriam Flynn","avatar":""},{"name":"Thomas Dekker","avatar":""},{"name":"Anndi McAfee","avatar":""},{"name":"Aria Noelle Curzon","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Tress MacNeille","avatar":""},{"name":"Jeff Bennett","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324531);
