INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('digimon-tamers-locomon-noi-dien', 'Digimon Tamers - Locomon Nổi Điên!', 'Digimon Tamers: Bousou Digimon Tokkyuu Digimon Tamers: Runaway Locomon', 'https://phimimg.com/upload/vod/20240220-1/496ac02d3b80b37d47ad6d1eaf5bc36c.jpg', 'https://phimimg.com/upload/vod/20240220-1/bc226a343ffc8d72f084c565a9f463d0.jpg', '<p>Locomon, một Digimon tàu hỏa, đã bất ngờ xuất hiện trong thế giới thực. Tất cả những người huấn luyện tranh giành dừng tàu trước khi nó đến đích cuối cùng là cổng vào thế giới Kỹ thuật số.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2002, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324531);
