INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-cua-chua-troi', 'Thành Phố Của Chúa Trời', 'City Of God', 'https://phimimg.com/upload/vod/20240108-1/9fcc1ac772fb5da447d6a060fa9ef73f.jpg', 'https://phimimg.com/upload/vod/20240108-1/3ff3b251ff63f95bda79bfe962201163.jpg', '<p>City of God khắc họa bức tranh đẫm máu và nhuốm màu bạo lực của một khu phố nhỏ nghèo nàn thuộc ngọai vi thành phố Rio, Brazil. Cuộc sống nghèo nàn, lạc hậu và thấm đẫm bi thương đã đẩy những con người, đúng hơn là những đứa trẻ phải làm quen với bạo lực, dao, và súng đạn. Bạo lực dần dần hình thành khi những đứa trẻ chỉ 13, 14 cầm trong tay những khẩu súng vô tình, lập băng nhóm đi cướp bóc của dân buôn. Tender Trio là một trong những băng nhóm đầu tiên. Cái lứa tuổi bồng bột ấy, cùng với những chiến tích lừng lẫy và hiển hách của những anh lớn đã ảnh hưởng không nhỏ đến những đứa trẻ chưa biết nghĩ là gì. Và điều gì đến cũng phải đến, khi những bậc đàn anh Tender Trio phải trả giá cho những gì chúng đã gây ra (và không gây ra), một tầng lớp đàn em đã có dịp trỗi dậy, mạnh mẽ hơn, quỷ quái hơn và cũng tàn bạo hơn.</p>', 'Full', 1, 'single', 'completed', 28, 2002, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Alexandre Rodrigues","avatar":""},{"name":"Matheus Nachtergaele","avatar":""},{"name":"Leandro Firmino","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324531);
