INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-duoi-toi-pham', 'Truy Đuổi Tội Phạm', 'Narc', 'https://phimimg.com/upload/vod/20240102-1/1b198ef651d762813c6d68620e9aac6b.jpg', 'https://phimimg.com/upload/vod/20240102-1/ebd5ecff20376ca12378b24177eeea39.jpg', '<p>Khi dấu vết của cuộc điều tra sát hại một cảnh sát trở nên nguội lạnh, một sĩ quan ma túy bí mật đã bị thu hút trở lại lực lượng để giúp giải quyết vụ án.</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Patric","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Chi McBride","avatar":""},{"name":"John Ortiz","avatar":""},{"name":"Krista Bridges","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324531);
