INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh', 'Chiến Tranh', 'War - Voyna', 'https://phimimg.com/upload/vod/20231231-1/c378f289fe82a754d948e932f1644f78.jpg', 'https://phimimg.com/upload/vod/20231231-1/9252c44bbb9df1afd6ce5ea58c133184.jpg', '<p>Trung sĩ Ivan Ermakov bị bọn khủng bố Chechen bắt giữ làm con tin cùng những người khác, trong đó có đại úy Medvedev và nghệ sĩ người Anh John Boyle cùng cô vợ chưa cưới Margaret khi họ đi du lịch đến Gruzia. Bọn chúng muốn 2 triệu bảng tiền chuộc từ 2 người Anh, tay trùm Aslan thả Ivan và John để về lấy tiền chuộc. Với lời hẹn sau 2 tháng mà không có tiền thì sẽ cắt đầu Margaret. Johnđã nỗ lực quyên tiền nhưng không kiếm nổi số tiền lớn. Đến Bộ ngoại giao Anh và Nga thì đều gặp phải những cái lắc đầu từ chối giải cứu cho Margaret. John phải làm gì để giải cứu vợ mình?</p>', 'Full', 1, 'single', 'completed', 17, 2002, 'Vietsub', 'HD', 'Nga', 0, '[{"name":"Aleksey Chadov","avatar":""},{"name":"Ian Kelly","avatar":""},{"name":"Ingeborga Dapkunaite","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324531);
