INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-quyet-chinh-hinh', 'Bí Quyết Chỉnh Hình', 'Beauty And The Breast', 'https://phimimg.com/upload/vod/20240123-1/2441c5b1ac97cf0cb4e2a772b2f5f2dd.jpg', 'https://phimimg.com/upload/vod/20240123-1/63f8afdfc49ca95abff73dd0dfe93d50.jpg', '<p>Bí Quyết Chỉnh Hình - Beauty and the Breast xoay quanh câu chuyện của Mario. Anh là một chuyên gia săn tìm phụ nữ để thỏa lòng mong ước cho ông sếp có tính trăng hoa của mình. Để tiện làm việc, Mario nhận anh chàng Harper làm trợ lý. Mục tiêu nhắm đến của Mario là cô gái xinh đẹp Yuki, người đồng thời cũng là dồng nghiệp tương lai của anh ta và cũng khiến Mario xao động.</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Ngạn Tổ","avatar":""},{"name":"Ngô Trấn Vũ","avatar":""},{"name":"Lý Gia Hân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324531);
