INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ba-toi-loi', 'Người Đàn Bà Tội Lỗi', 'Femme Fatale', 'https://phimimg.com/upload/vod/20231230-1/8b781cd2cceb52651e48fe8fa6ba0fba.jpg', 'https://phimimg.com/upload/vod/20231230-1/1c3230d19e61371a422e0e0b520dac9f.jpg', '<p>Một vụ lừa đảo kim cương trị giá 10 triệu đô la, danh tính bị đánh cắp, cuộc sống mới khi kết hôn với một nhà ngoại giao. Laure Ash đã mạo hiểm lớn, thắng lớn. Nhưng sau đó, một tờ báo lá cải đã chộp được bức ảnh của cô ở Paris, và đột nhiên, những kẻ thù trong quá khứ bí mật của Laure biết cô là ai và ở đâu. Và tất cả bọn họ đều muốn chia phần của mình trong vụ trộm kim cương. Hoặc cuộc sống của cô ấy. Hoặc cả hai.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rebecca Romijn","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Peter Coyote","avatar":""},{"name":"Rie Rasmussen","avatar":""},{"name":"Gregg Henry","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324531);
