INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-diep-vien', 'Tôi Là Điệp Viên', 'I Spy', 'https://phimimg.com/upload/vod/20231227-1/e3aa132ca041846f67b3300a28063d45.jpg', 'https://phimimg.com/upload/vod/20231227-1/18dd792f6f04f29fa72bc546e4178c07.jpg', '<p>Khi Switchblade, nguyên mẫu máy bay chiến đấu tàng hình phức tạp nhất được tạo ra, bị đánh cắp khỏi chính phủ Hoa Kỳ, một trong những điệp viên hàng đầu của Hoa Kỳ, Alex Scott, được kêu gọi hành động. Điều anh ta không mong đợi là được hợp tác với một thường dân tự phụ, Nhà vô địch quyền anh hạng nhất thế giới Kelly Robinson, trong một nhiệm vụ gián điệp bí mật hàng đầu nguy hiểm. Nhiệm vụ của họ: sử dụng kỹ năng và sự hài hước ngang nhau để bắt Arnold Gundars, một trong những tay buôn vũ khí thành công nhất thế giới.</p>', 'Full', 1, 'single', 'completed', 22, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Keith Dallas","avatar":""},{"name":"Malcolm McDowell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324531);
