INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-diet-vong', 'Con Đường Diệt Vong', 'Road To Perdition', 'https://phimimg.com/upload/vod/20231219-1/11e62077bdb833e98bb469e76ce66082.jpg', 'https://phimimg.com/upload/vod/20231219-1/5d620827f3f82a5cd12a8db47dace4db.jpg', '<p>Câu chuyện xảy ra vào những năm 30 ở thành phố Rock Island, bang Illinois. Michael Sullivan từng là trẻ mồ côi và được John Rooney, trùm xã hội đen trong thành phố, đêm về nuôi. Lớn lên, anh tham gia Đại chiến thế giới lần thứ nhất và lập được nhiều công trạng. Chiến tranh kết thúc, Micheal rời quân ngũ và trở thành một sát thủ khét tiếng dưới trướng John, người mà anh luôn tôn thờ. John tỏ ra thân mật với Michael hơn cả con ruột. Ông ta rất quan tâm tới hai đứa con trai của anh. Điều này khiến Connor Rooney, con trai của John, vô cùng tức giận. Quan hệ giữa hai cha con nhà Rooney trở nên căng thẳng chỉ vì Michael.Lợi dụng một số sự cố, Conner cùng một số tay chân thân tín bí mật tới nhà Micheal để hạ sát toàn bộ gia đình. Vợ và con trai cả ...</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Anderson","avatar":""},{"name":"Celeste Holm","avatar":""},{"name":"Tom Hanks","avatar":""},{"name":"Laurence Luckinbill","avatar":""},{"name":"Anne Jeffreys","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324531);
