INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-hen-chet-ngay-khac', 'Điệp Viên 007: Hẹn Chết Ngày Khác', 'Die Another Day', 'https://phimimg.com/upload/vod/20231219-1/1298419e70aa972869032f86f80fb585.jpg', 'https://phimimg.com/upload/vod/20231219-1/354697fd424f52c80d17812ca0e6baec.jpg', '<p>Trong lần xuất hiện này, James Bond nhận nhiệm vụ điều tra đường dây buôn lậu vũ khí do đại tá Moon cầm đầu. Không may anh bị một đồng nghiệp bán đứng và lãnh 14 tháng tù rồi được thả ra trong phi vụ trao đổi lấy Zao – cánh tay phải của Moon. Để truy ra kẻ phản bội, James đi khắp nơi từ Hồng Kông, Cuba đến xứ sở sương mù để theo dấu Zao. Trong khi tháo chạy, hắn để lại manh mối là những viên kim cương xuất xứ từ công ty của Gustav Graves. Phiêu lưu vòng quanh thế giới, điệp viên 007 cố gắng lật mặt kẻ phản bội và ngăn chặn một cuộc chiến có thể huỷ diệt cả thế giới.</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Rick Yune","avatar":""},{"name":"Toby Stephens","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324532);
