INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-sao-de-tot-nghiep', 'Làm Sao Để Tốt Nghiệp', 'Van Wilder: Party Liaison', 'https://phimimg.com/upload/vod/20231214-1/709b9f8b2788d5e109c9b04dacfdfb99.jpg', 'https://phimimg.com/upload/vod/20231214-1/594cee4211b565007e0778d7479f3112.jpg', '<p>Anh chàng Van Wilder (Ryan Reynolds) đã mài đũng quần những 7 năm trên ghế nhà trường, thế nhưng, chuyện tốt nghiệp đối với chàng ta vẫn là một điều quá xa vời. Được bao vây xung quanh bởi một đội ngũ những người hâm mộ và có cả một trợ lý riêng, cuộc sống của Van giống như một ông hoàng trong trường học.Thế nhưng, khi cha của Van quyết định cúp hết mọi chi phí sinh hoạt của cậu con trai cưng, chàng ta bắt đầu phải tự thân vận động và xoay sở khốn khổ nếu muốn kéo dài cuộc sống xa hoa của mình trước đây. Không những thế, Van còn bị lôi kéo vào cuộc chiến nảy lửa với cô nàng ký giả học đường lắm chuyện Gwen Pearson…</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Tara Reid","avatar":""},{"name":"Tim Matheson","avatar":""},{"name":"Kal Penn","avatar":""},{"name":"Teck Holmes","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324532);
