INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-hieu-chuon-chuon', 'Mật Hiệu Chuồn Chuồn', 'Dragonfly', 'https://phimimg.com/upload/vod/20231211-1/ec766e3ac8974ccc9f7832efcbf9e31a.jpg', 'https://phimimg.com/upload/vod/20231211-1/fe1981e9119ff6ada1d37771023d0dad.jpg', '<p>Joe Darrows (Kevin Costner) và Emily Darrow (Susanna Thompson) là bác sĩ của một bênh việc tại vùng Chicago. Trong một lần đi làm tình nguyện tại Venezuela để giúp đỡ người bản địa ở khu vực Amazon, Emily đã qua đời khi một chiếc xe buýt chở cô gặp phải sạt lở đất và lao xuống con sông bên dưới trong khi đang mang thai 7 tháng. Thi thể của cô không được chính quyền địa phương tìm thấy. Sau một thời gian, Joe Darrow dần học được cách làm quen với sự mất mát quá to lớn này và quay trở lại làm việc. Nhưng một đêm, anh bị đánh thức bởi một con chuồn chuồn, loài động vật mà vợ anh vô cùng yêu thích. Joe bắt đầu đến thăm những bệnh nhân của Emily tại khoa Ung bướu. Và điều kì lạ xảy ra khi xác chết và những bệnh nhân sắp qua đời bắt ...</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Costner","avatar":""},{"name":"Joe Morton","avatar":""},{"name":"Ron Rifkin","avatar":""},{"name":"Susanna Thompson","avatar":""},{"name":"Kathy Bates","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324532);
