INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-sieu-quay', 'Chú Chó Siêu Quậy', 'Scooby-Doo', 'https://phimimg.com/upload/vod/20231211-1/9849109f4354b640dee4ab9a19b0aaa1.jpg', 'https://phimimg.com/upload/vod/20231211-1/c1bece1c6b21124dd04e2457c90d5e83.jpg', '<p>Câu chuyện về chú chó Scooby Doo cùng tập đoàn Mystery thực hiện một cuộc phiêu lưu đầy thú vị và nguy hiểm. Họ gồm Fred, Daphne, Velma và Shaggy bổng dưng xảy ra một chút mâu thuẫn nhỏ và đường ai nấy đi nhưng cuối cùng họ cũng xóa bỏ được mâu thuẫn với mọi nỗ lực để đoàn kết lại với nhau một lần nữa nhằm chống lại định mệnh. Họ cùng chiến đấu để phá tan âm mưu đen tối và huyền bí của khu công viên vui chơi giải trí Spooky Island từ những biểu hiện kỳ lạ của các du khách từng đến đây...</p>', 'Full', 1, 'single', 'completed', 17, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Lillard","avatar":""},{"name":"Freddie Prinze Jr.","avatar":""},{"name":"Sarah Michelle Gellar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324532);
