INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('25th-hour', '25th Hour', '25th Hour', 'https://phimimg.com/upload/vod/20231211-1/35782a69f97091e11fad8cebf4ebc33e.jpg', 'https://phimimg.com/upload/vod/20231211-1/120b299b87719e1ddde11707b8710e7b.jpg', '<p>25th Hour là bộ phim tâm lý kề về Monty Brogan, là một ông vua của khu Manhattan sang trọng tại New York chỉ còn 24 giờ nữa là vào khám nằm suốt 7 năm trời. Trong ngày cuối cùng còn hít thở không khí tự do, Monty ngẫm nghĩ về cuộc đời và không hiểu sao cuộc sống xa hoa tại các hội quán thượng lưu ở New York lại làm ông xa cách với những người thân yêu nhất. Monty tìm gặp lại người cha gia mà chính ông rời bỏ, gặp cả những người bạn bè cũ thời hàn vi, kể cả cô bồ cũ Naturelle không chắc có phải cô báo tin cho cảnh sát bắt ông hay không. Bộ phim nói về suy nghĩ của một người về cuộc đời, thân phận để đi đến một quyết định sau cùng.</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Edward Norton","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Anna Paquin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324532);
