INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ba-so-magdalene', 'Những Bà Sơ Magdalene', 'The Magdalene Sisters', 'https://phimimg.com/upload/vod/20231211-1/0e035ac2a0bd68c02fdf5e88f72ad03e.jpg', 'https://phimimg.com/upload/vod/20231211-1/40d8ebae68df4d2aec17deef5f7b8ce1.jpg', '<p>Bốn người phụ nữ được đưa vào trại tị nạn của hội chị em Magdalene để sửa chữa hành vi tội lỗi của họ: Crispina và Rose đã sinh một đứa con trước hôn nhân, Margaret bị anh họ cưỡng hiếp và cô bé mồ côi Bernadette nhiều lần bị bắt quả tang tán tỉnh các chàng trai. Tất cả phải làm việc trong tiệm giặt là dưới sự giám sát nghiêm ngặt của các nữ tu, những người phá vỡ ý chí của họ thông qua hình phạt tàn bạo.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anne-Marie Duff","avatar":""},{"name":"Nora-Jane Noone","avatar":""},{"name":"Dorothy Duffy","avatar":""},{"name":"Geraldine McEwan","avatar":""},{"name":"Eileen Walsh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324532);
