INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-tau-ma', 'Con Tàu Ma', 'Ghost Ship', 'https://phimimg.com/upload/vod/20231210-1/5f687c1ada2a0a98bde41b832e1edd17.jpg', 'https://phimimg.com/upload/vod/20231210-1/c96a6c7a09fd8b0803cf0b4b1b3866c4.jpg', '<p>Sau khi phát hiện ra một con tàu chở khách bị mất từ năm 1962 trôi nổi trên Biển Bering, Salvager yêu cầu tàu là của riêng họ. Một khi họ bắt đầu kéo con tàu ma về phía bến cảng, một loạt các Ocrenses kỳ quái xảy ra và nhóm bị mắc kẹt bên trong con tàu, mà họ sớm học được là nơi sinh sống của một sinh vật ma quỷ.</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324532);
