INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('austin-giai-cuu-the-gioi', 'Austin Giải Cứu Thế Giới', 'Austin Powers In Goldmember', 'https://phimimg.com/upload/vod/20231230-1/869a4b348edf191664b0e036e6589aba.jpg', 'https://phimimg.com/upload/vod/20231230-1/9c4aa75c56af245ce78996c2233fb023.jpg', '<p>Anh ta tìm thấy Mojo của mình, em bé, và bây giờ Austin Powers trở lại trong cuộc phiêu lưu hài kịch Shagadelic này. Sshhh! Lượt quạt khi Tiến sĩ Evil và Mini-Me thoát khỏi nhà tù. Tham gia các lực lượng với Superfreaky Goldmember, họ bắt cóc cha của Austin, Master Spy Nigel Powers, trong một kế hoạch du lịch thời gian Dastardly để chiếm lĩnh thế giới. Trước khi bạn có thể nói Lắc chiến lợi phẩm, Austin Du thuyền đến năm 1975 và hợp tác với Sexy Foxxy Cleopatra để ngăn chặn Tiến sĩ Evil và Goldmember từ tình trạng lộn xộn tinh nghịch của họ.</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324532);
