INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-doc-ma', 'Những Người Đọc Mã', 'Windtalkers', 'https://phimimg.com/upload/vod/20231211-1/0468574b7ca3a2cfb353971adc7cfd8a.jpg', 'https://phimimg.com/upload/vod/20231211-1/2590eb2a7e3f427eafa7c59d7a0b7089.jpg', '<p>Năm 1944, cục diện chiến tranh thế giới II thay đổi hoàn toàn theo hướng bất lợi cho phe Trục. Trên mặt trận Thái Bình Dương, phát xít Nhật buộc phải rời bỏ vùng đất quan trọng. Nhờ co cụm lại nên sức kháng cự của quân đội Nhật hoàng hầu như không giảm đi là mấy. Bộ chỉ huy tối cao của quân Mỹ điên đầu khi những mệnh lệnh của họ đều bị đối phương giải mã thành công, gây vô số tổn thất cho các đơn vị. Các nhà toán học Mỹ sử dụng gần hết ngôn ngữ của các bộ lạc thiểu số làm mã khóa, nhưng chúng vẫn bị các chuyên gia của Nhật hóa giải. Cuối cùng, người ta quyết định dùng ngôn ngữ của bộ lạc Navajo, sinh sống trên cao nguyên Towering Arizona, bởi người Nhật không hề biết đến sự tồn tại của bộ lạc này. Thế là người ta động viên thanh niên của bộ tộc Navajo ra trận. Tất cả bọn họ được huấn luyện để trở thành binh sĩ truyền tin, giải mã. Trong số những người ra trận có hai người bạn chơi thân với nhau: Ben Yahzee và Whitehorse...</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Adam Beach","avatar":""},{"name":"Peter Stormare","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324532);
