INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('blade-ii', 'Blade II', 'Blade II', 'https://phimimg.com/upload/vod/20231210-1/de48c16283a7e2074bc40d0ead0a5f5e.jpg', 'https://phimimg.com/upload/vod/20231210-1/656fd9980117f8c0b7bcbc1904e21a40.jpg', '<p>Một đột biến hiếm gặp đã xảy ra trong cộng đồng ma cà rồng. Máy gặt. Một ma cà rồng được tiêu thụ với một ngụm máu vô độ mà họ săn mồi trên ma cà rồng cũng như con người, biến đổi nạn nhân đủ may mắn để sống sót thành những người gặt. Bây giờ họ nhanh chóng mở rộng dân số đe dọa sự tồn tại của ma cà rồng, và sẽ sớm không có đủ con người trên thế giới để đáp ứng sự đổ máu của họ. Blade, Whistler và một chuyên gia Armory tên Scud được giới thiệu tò mò bởi Hội đồng Shadow. Hội đồng miễn cưỡng thừa nhận rằng họ đang ở trong một tình huống thảm khuất và họ cần sự giúp đỡ của Blade. Lưỡi dao sau đó kéo dài vào một liên minh với Bloodpack, một nhóm ma cà rồng ưu tú được đào tạo trong tất cả các chế độ chiến đấu để đánh bại mối đe dọa Reaper. Đội của Blade và Bloodpack là dòng hàng phòng ngự duy nhất có thể ngăn chặn dân số Reaper quét sạch ma cà rồng và quần thể người.</p>', 'Full', 1, 'single', 'completed', 16, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324532);
