INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-nhan-la-dieu-dien-ro', 'Hôn Nhân Là Điều Điên Rồ', 'Marriage Is A Crazy Thing', 'https://phimimg.com/upload/vod/20231209-1/bf84d00b6223bce96607304a3e3f36c3.jpg', 'https://phimimg.com/upload/vod/20231209-1/a2503953ff5fa467306b94f0f34bc916.jpg', '<p>Trong buổi hôn lễ của em trai mình, Joon Young được giới thiệu làm quen với cô bác sĩ đã có gia đình Yoen Hee. Sau khi hôn lễ kết thúc thì trời cũng đã khuya, Yoen Hee không thể đón xe bus về được. Joon Young đề nghị đến một khách sạn nhỏ gần đấy thuê phòng trọ vì như vậy sẽ rẻ hơn là đón taxi về. Yoen Hee đồng ý và trong đêm đầu tiên gặp nhau đó cả hai đã quan hệ với nhau. Yoen Hee là một cô gái có tư tưởng cởi mở, còn Joon Young là một chàng trai không thích kết hôn nhưng lại muốn đeo đuổi tình cảm. Vì vậy Yoen Hee quyết định tìm một nơi có thể che giấu chồng mình, 2 tuần một lần quan hệ với Joon Young.</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Uhm Jung-hwa","avatar":""},{"name":"Kam Woo-sung","avatar":""},{"name":"Park Won-sang","avatar":""},{"name":"Lee Joo-sil","avatar":""},{"name":"Kim Ki-chun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324532);
