INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kungfu-bo-sua', 'Kungfu Bò Sữa', 'Kung Pow: Enter The Fist', 'https://phimimg.com/upload/vod/20231208-1/4a3e169d93f637b046fa1efb66a862bf.jpg', 'https://phimimg.com/upload/vod/20231208-1/05d883901a591873acd90a67d8bdbbfc.jpg', '<p>Một bộ phim trong một bộ phim, được tạo ra để giả mạo thể loại võ thuật. Biên kịch / đạo diễn Steve Oedekerk sử dụng các nhân vật đương đại và ghép họ vào một bộ phim kung-fu những năm 1970, đan xen cái mới và cái cũ. Là nhân vật chính, Người được chọn, Oedekerk lên đường trả thù cho cái chết của cha mẹ mình dưới bàn tay của huyền thoại kung-fu Master Pain. Trên đường đi, anh ta gặp một số nhân vật kỳ lạ.</p>', 'Full', 1, 'single', 'completed', 17, 2002, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Lung Fei","avatar":""},{"name":"Tad Horino","avatar":""},{"name":"Steve Oedekerk","avatar":""},{"name":"Peggy Lu","avatar":""},{"name":"Jennifer Tung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324532);
