INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-toi-tung-la-linh', 'Chúng Tôi Từng Là Lính', 'We Were Soldiers', 'https://phimimg.com/upload/vod/20231203-1/e7612c317dea17ff11ee9dc302e40d6f.jpg', 'https://phimimg.com/upload/vod/20231203-1/47fdf8c7e9386c6d9c46290987768e25.jpg', '<p>Câu chuyện về trận đánh lớn đầu tiên của giai đoạn chống Mỹ trong Chiến tranh Việt Nam và những người lính của cả hai bên tham chiến.</p>', 'Full', 1, 'single', 'completed', 9, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Greg Kinnear","avatar":""},{"name":"Madeleine Stowe","avatar":""},{"name":"Sam Elliott","avatar":""},{"name":"Chris Klein","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324532);
