INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-tuoc-monte-cristo', 'Bá Tước Monte Cristo', 'The Count of Monte Cristo', 'https://phimimg.com/upload/vod/20231204-1/aaef37054ead846711dd13629de7d7ac.jpg', 'https://phimimg.com/upload/vod/20231204-1/2c99d5d9afe33cd4e09d75b3ea441760.jpg', '<p>Bá Tước Monte Cristo 2002 là phiên bản làm lại của phim cùng tên. Dantes, một thủy thủ bị kết tội oan vì bị lừa bởi người bạn Fernand, vì hắn này muốn cướp cô bạn gái Mercedes của Dantes. Dantes bị giam trên nhà tù đảo Chateau suốt 13 năm. Tại đây, với sự giúp đỡ của người bạn tù, anh ấy đã vượt ngục, thừa hưởng tài sản của ông ấy và trở thành Bá Tước Monte Cristo. Anh ấy bắt đầu trả thù những kẻ đã phản bội trong quá khứ....</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Caviezel","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Richard Harris","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324532);
