INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-chung-than', 'Phi Vụ Chung Thân', 'Welcome to Collinwood', 'https://phimimg.com/upload/vod/20231130-1/fac7804d019dff3dc34b2a7b3c7fa72e.jpg', 'https://phimimg.com/upload/vod/20231130-1/1fa5011137ecf45694d78b2651ddc192.jpg', '<p>Khi Cosimo đề xuất một kế hoạch cướp ngon ăn từ trong tù chung thân, hắn biết phải nhanh chóng ra ngoài để chén vụ này. Khi mà hắn không thể làm gì vì kẹt cứng nơi đây, hy vọng duy nhất là vào cô bạn gái và một nhân vật thế thân.</p>', 'Full', 1, 'single', 'completed', 8, 2002, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"William H. Macy","avatar":""},{"name":"Isaiah Washington","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Michael Jeter","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"John Buck Jr.","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Andy Davoli","avatar":""},{"name":"Brett C. Leonard","avatar":""},{"name":"Frank O''Donnell","avatar":""},{"name":"Peter Veneziano","avatar":""},{"name":"Bernard Canepari","avatar":""},{"name":"Art Oughton","avatar":""},{"name":"Ray Calabrese","avatar":""},{"name":"George Clooney","avatar":""},{"name":"Annie Kitra","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324532);
