INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ton-that-ngoai-du-kien', 'Tổn Thất Ngoài Dự Kiến', 'Collateral Damage', 'https://phimimg.com/upload/vod/20231130-1/7a70c2690d1a3bb3b8fc7c64a2e9a06f.jpg', 'https://phimimg.com/upload/vod/20231130-1/9418b054bf716bba7746311c32b22053.jpg', '<p>Gordy Brewer, anh lính cứu hỏa bị cuốn vào vòng xoáy phức tạp và nguy hiểm của thế giới khủng bố toàn cầu sau khi mất vợ và con trong một vụ đánh bom. Mặc dù nghi ngờ Claudio, thủ lĩnh phiến quân tại Colombia, đứng sau vụ việc, nhưng trước sự lơ là của chính quyền và bị ám ảnh bởi ý nghĩ kẻ chịu trách nhiệm cho cái chết của vợ con sẽ không bao giờ bị xét xử, Brewer quyết định tự mình trừng trị kẻ có tội.</p>', 'Full', 1, 'single', 'completed', 10, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Francesca Neri","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"John Turturro","avatar":""},{"name":"Jsu Garcia","avatar":""},{"name":"Tyler Posey","avatar":""},{"name":"Michael Milhoan","avatar":""},{"name":"Rick Worthy","avatar":""},{"name":"Raymond Cruz","avatar":""},{"name":"Lindsay Frost","avatar":""},{"name":"Ethan Dampf","avatar":""},{"name":"Jorge Zepeda","avatar":""},{"name":"Miguel Sandoval","avatar":""},{"name":"Harry Lennix","avatar":""},{"name":"Madison Mason","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324532);
