INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-cuong-say', 'Tình Cuồng Say', 'Punch-Drunk Love', 'https://phimimg.com/upload/vod/20231129-1/335f642027e1bf5e5085c3de6ef1bbe5.jpg', 'https://phimimg.com/upload/vod/20231129-1/b31f4dccc586f62dea491e093a9d2eba.jpg', '<p>Đây là bộ phim do đạo diễn Paul Thomas Anderson (được biết tới với phim Boogie night, Magnolia) . trong phim Adam Sandler trong vai Barry Egan , một doanh nhân tìm kiếm bạn tình bằng dịch vụ tìm bạn qua điện thoại, nhưng anh luôn thất vọng khi gặp họ. Một ngày kia anh gặp được người trong mộng ( do Emily Watson đóng). Phim không dành cho ai thích dạn phim tốc độ vì diễn biến câu chuyện khá chậm..</p>', 'Full', 1, 'single', 'completed', 10, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Mary Lynn Rajskub","avatar":""},{"name":"Robert Smigel","avatar":""},{"name":"Jason Andrews","avatar":""},{"name":"Don McManus","avatar":""},{"name":"David Schrempf","avatar":""},{"name":"Seann Conway","avatar":""},{"name":"Rico Bueno","avatar":""},{"name":"Hazel Mailloux","avatar":""},{"name":"Karen Kilgariff","avatar":""},{"name":"Julie Hermelin","avatar":""},{"name":"Salvador Curiel","avatar":""},{"name":"Jorge Barahona","avatar":""},{"name":"Erne","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324532);
