INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sut-nhu-beckham', 'Sút Như Beckham', 'Bend It Like Beckham', 'https://phimimg.com/upload/vod/20231129-1/aaa09f4520d07a99eecc70ebc5e359e8.jpg', 'https://phimimg.com/upload/vod/20231129-1/adc63875bcfa38be249eb629423aa0d0.jpg', '<p>Bhamra là một gia đình người Ấn Độ sống ở London có hai con gái Pinky (Archie Panjabi) và Jessminder (Parminder K. Nagra), trong khi cô chị Pinky chuẩn bị lấy chồng thì cô em Jessminder lại trao trái tim mình cho trái bóng tròn và thần tượng David Beckham. Đối với một gia đình theo đạo Sikh, việc con gái mặc đồ thể thao, chạy theo trái bóng, thay vì khoác trang phục truyền thống và học nấu nướng, là điều không thể chấp nhận nên họ cố gắng nuôi dạy uốn nắn cô vào khuôn phép. Nhưng Jessminder vẫn trốn ra sân chơi bóng cùng các chàng trai...</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Parminder Nagra","avatar":""},{"name":"Keira Knightley","avatar":""},{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Anupam Kher","avatar":""},{"name":"Shaheen Khan","avatar":""},{"name":"Frank Harper","avatar":""},{"name":"Juliet Stevenson","avatar":""},{"name":"Ameet Chana","avatar":""},{"name":"Archie Panjabi","avatar":""},{"name":"Shaznay Lewis","avatar":""},{"name":"Pooja Shah","avatar":""},{"name":"Preeya Kalidas","avatar":""},{"name":"Shobu Kapoor","avatar":""},{"name":"Ace Bhatti","avatar":""},{"name":"Sarita Khajuria","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
