INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sut-nhu-beckham', 'Sút Như Beckham', 'Bend It Like Beckham', 'sút như beckham bend it like beckham parminder nagra keira knightley jonathan rhys meyers anupam kher shaheen khan frank harper juliet stevenson ameet chana archie panjabi shaznay lewis pooja shah preeya kalidas shobu kapoor ace bhatti sarita khajuria ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve-tuoi-tho', 'Trở Về Tuổi Thơ', 'About a Boy', 'https://phimimg.com/upload/vod/20231130-1/6bdce5e9aef3ea3ca5858cf5a15abcc6.jpg', 'https://phimimg.com/upload/vod/20231130-1/4a5f818fdb215b1834773416a628a010.jpg', '<p>Ngót nghét 40 tuổi mà anh chàng Will vẫn cứ lông bông, mọi cố gắng của bạn bè hòng nhốt anh &quot;vào rọ&quot; đều vô nghĩa. Chán chê với chuyện gạ gẫm bọn gái trẻ, một ngày anh nổi hứng với máy bay già. Anh lên kế hoạch kỹ càng, tạo ra hàng đống khó khăn, tình huống gia đình... cho các chị dễ mũi lòng.
 Nhưng thử thách thực sự với anh lại là một cậu bé.</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hugh Grant","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Natalia Tena","avatar":""},{"name":"Victoria Smurfit","avatar":""},{"name":"Augustus Prew","avatar":""},{"name":"Sharon Small","avatar":""},{"name":"Madison Cook","avatar":""},{"name":"Jordan Cook","avatar":""},{"name":"Nicholas Hutchison","avatar":""},{"name":"Ryan Speechley","avatar":""},{"name":"Joseph Speechley","avatar":""},{"name":"Denise Stephenson","avatar":""},{"name":"Chris Webster","avatar":""},{"name":"Isabel Brook","avatar":""},{"name":"Orlando","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
