INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-hy-sinh-cao-ca', 'Sự Hy Sinh Cao Cả', 'Hart''s War', 'https://phimimg.com/upload/vod/20231128-1/dcc03b8d4e336762391a7d91f01ac636.jpg', 'https://phimimg.com/upload/vod/20231128-1/44afd5257a7d2a6829551fc426bc47c8.jpg', '<p>Khi Đại tá William McNamara bị tước tự do trong trại tù binh Đức, anh quyết tâm tiếp tục chiến đấu ngay cả từ phía sau phòng tuyến của kẻ thù. Tranh thủ sự giúp đỡ của một trung úy trẻ trong một âm mưu xuất sắc chống lại những kẻ bắt giữ anh, McNamara mạo hiểm mọi thứ trong sứ mệnh giải phóng người của mình và thay đổi kết quả của cuộc chiến.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Colin Farrell","avatar":""},{"name":"Terrence Howard","avatar":""},{"name":"Marcel Iureș","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Linus Roache","avatar":""},{"name":"Vicellous Shannon","avatar":""},{"name":"Rory Cochrane","avatar":""},{"name":"Joe Spano","avatar":""},{"name":"Michael Weston","avatar":""},{"name":"Adrian Grenier","avatar":""},{"name":"Jonathan Brandis","avatar":""},{"name":"Maury Sterling","avatar":""},{"name":"Sam Jaeger","avatar":""},{"name":"Scott Michael Campbell","avatar":""},{"name":"Rick Ravanello","avatar":""},{"name":"Sebas","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324532);
