INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-tro-ve', 'Người Hùng Trở Về', 'Returner', 'https://phimimg.com/upload/vod/20231127-1/987e584960c64b3fd5d60c20e99fab4b.jpg', 'https://phimimg.com/upload/vod/20231127-1/75f08a8b527bb752d5f897b0e2b22bab.jpg', '<p>Sau khi một cuộc xâm lược của người ngoài hành tinh đe dọa hủy diệt loài người, một cô gái trẻ người Nhật, tên là Milly, du hành ngược thời gian từ năm 2084 đến tháng 10 năm 2002, và nhờ sự trợ giúp bất đắc dĩ của tay súng lão luyện ở Tokyo, tên là Miyamoto, để khám phá và ngăn chặn sự khởi đầu của cuộc xâm lược. chiến tranh. Tuy nhiên, rắc rối xảy ra khi hai nhân vật chính buộc phải đối phó với một trùm mafia Nhật Bản, tên là Mizoguchi, người bằng cách nào đó đã tham gia vào việc bắt đầu cuộc chiến bằng cách giam giữ con tàu vũ trụ đầu tiên của người ngoài hành tinh và phi công người ngoài hành tinh của nó, trong khi hai anh hùng của chúng ta chạy đua chống lại đồng hồ để tìm cách ngăn chặn sự hủy diệt sắp tới từ hạm đội xâm lược của người ngoài hành tinh đang tìm cách báo thù trên đường đến Trái đất.</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takeshi Kaneshiro","avatar":""},{"name":"Anne Suzuki","avatar":""},{"name":"Kirin Kiki","avatar":""},{"name":"Goro Kishitani","avatar":""},{"name":"Yukiko Okamoto","avatar":""},{"name":"Mitsu Murata","avatar":""},{"name":"Kisuke Iida","avatar":""},{"name":"Kazuya Shimizu","avatar":""},{"name":"Chiharu Kawai","avatar":""},{"name":"Dean Harrington","avatar":""},{"name":"Xiaoqun Zhao","avatar":""},{"name":"Masaya Takahashi","avatar":""},{"name":"Shugo Oshinari","avatar":""},{"name":"Kanata Hongo","avatar":""},{"name":"Hoshi Ishida","avatar":""},{"name":"Adeyto","avatar":""},{"name":"Kenji Motomiya","avatar":""},{"name":"Gorô","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324532);
