INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-ngoi', 'Đổi Ngôi', 'Changing Lanes', 'https://phimimg.com/upload/vod/20231129-1/b30cf603a2e03ad58bf2ff89a622e7f2.jpg', 'https://phimimg.com/upload/vod/20231129-1/19d23df20193e7b0248cb6f1ac68de7a.jpg', '<p>Câu chuyện là sự đấu trí của hai người đàn ông xa lạ tình cờ chạm trán trên đường đến tòa án. Một người đến đúng giờ nhưng mất cặp tài liệu quan trọng, một người trễ giờ nên thất bại trong công việc nhưng lại chính là “thủ phạm” giữ cặp tài liệu quan trọng của người kia...</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Sydney Pollack","avatar":""},{"name":"William Hurt","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Dylan Baker","avatar":""},{"name":"Kim Staunton","avatar":""},{"name":"John Benjamin Hickey","avatar":""},{"name":"Michael McGrath","avatar":""},{"name":"Bruce Altman","avatar":""},{"name":"Jennifer Dundas","avatar":""},{"name":"Joe Grifasi","avatar":""},{"name":"Tina Sloan","avatar":""},{"name":"Akil Walker","avatar":""},{"name":"Matt Malloy","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324532);
