INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-dot-bien', 'Sói Đột Biến', 'Dog Soldiers', 'https://phimimg.com/upload/vod/20231124-1/09443065c6b788ecdd69ce50ebd1131d.jpg', 'https://phimimg.com/upload/vod/20231124-1/82218528683327794c4e0f3b2e9801bb.jpg', '<p>Một đội lính Anh đang huấn luyện ở vùng hoang dã vắng vẻ của Scotland tìm thấy một đội trưởng Lực lượng Đặc biệt bị thương và những người còn lại trong đội của anh ta. Khi họ gặp nhà động vật học Megan, hóa ra người sói đang hoạt động trong khu vực. Họ phải chuẩn bị cho một số hành động vì đêm nay sẽ có trăng tròn...</p>', 'Full', 1, 'single', 'completed', 11, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Pertwee","avatar":""},{"name":"Kevin McKidd","avatar":""},{"name":"Emma Cleasby","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"Thomas Lockyer","avatar":""},{"name":"Darren Morfitt","avatar":""},{"name":"Chris Robson","avatar":""},{"name":"Leslie Simpson","avatar":""},{"name":"Tina Landini","avatar":""},{"name":"Craig Conway","avatar":""},{"name":"Villrikke''s Acer","avatar":""},{"name":"Bryn Walters","avatar":""},{"name":"Ben Wright","avatar":""},{"name":"Brian Claxton Payne","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324532);
