INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cung-duong', 'Kẻ Cùng Đường', 'John Q', 'https://phimimg.com/upload/vod/20231124-1/476bfa8e7ff63a6cd2f9c7afae2e22ce.jpg', 'https://phimimg.com/upload/vod/20231124-1/20d35d88846ae173992c29aaaffc8668.jpg', '<p>Nghèo khó, cùng cực với đồng lương công nhân eo hẹp, John và vợ thực sự bế tắc khi không thể kiếm đủ tiền để phẫu thuật tim cho con, trong khi mạng sống của cậu bé chỉ còn tính bằng ngày. Trong cơn cùng quẫn, John dùng súng khống chế bác sĩ và bắt các bệnh nhân khác làm con tin để yêu cầu bệnh viện ghép tim cho con trai.</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"James Woods","avatar":""},{"name":"Kimberly Elise","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Shawn Hatosy","avatar":""},{"name":"Eddie Griffin","avatar":""},{"name":"Kevin Connolly","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Anne Heche","avatar":""},{"name":"Laura Harring","avatar":""},{"name":"Heather Wahlquist","avatar":""},{"name":"Daniel E. Smith","avatar":""},{"name":"David Thornton","avatar":""},{"name":"Paul Johansson","avatar":""},{"name":"Obba Babatundé","avatar":""},{"name":"Troy Byer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324532);
