INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ngu', 'Mất Ngủ', 'Insomnia', 'https://phimimg.com/upload/vod/20231120-1/fddf2a22b8a9bc1066b24b2b74975a45.jpg', 'https://phimimg.com/upload/vod/20231120-1/d5a1f3d3e35ea9ef9ddb24e74050de2f.jpg', '<p>Cuộc nổ súng diễn ra trong sương mù dày đặc khi Will Dormer giăng một cái bẫy để bẫy kẻ sát nhân. Súng nổ… đồng nghiệp Hap Eckhart ngã gục. Anh có thể lừa tất cả, chỉ trừ tên sát nhân Walter Finch ! Hắn mặc cả với Dormer, sẽ đổ tội cho nữ cảnh sát trẻ tuổi Ellie Burr…Robin Williams trong vai một kẻ giết người nhưng lại không xem mình là kẻ giết người… Al Pacino trong vai một cảnh sát bị phân tâm, lòng chân thật và sự lừa dối, mặc cảm có tội và sự tự do… Một vùng đất lúc nào cũng có ánh mặt trời, Dormer không có nơi ẩn nấp, ngay cả trong cơn ác mộng của chính mình!Phim này xứng đáng lọt vào top những bộ phim hình sự hay nhất đã từng công chiếu . Phim hay từ cốt chuyện lỳ kỳ , lôi cuốn , đến cách diễn xuất tinh tế của ...</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Al Pacino","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"Hilary Swank","avatar":""},{"name":"Martin Donovan","avatar":""},{"name":"Maura Tierney","avatar":""},{"name":"Nicky Katt","avatar":""},{"name":"Paul Dooley","avatar":""},{"name":"Yan-Kay Crystal Lowe","avatar":""},{"name":"Jay Brazeau","avatar":""},{"name":"Larry Holden","avatar":""},{"name":"Kerry Sandomirsky","avatar":""},{"name":"Lorne Cardinal","avatar":""},{"name":"Katharine Isabelle","avatar":""},{"name":"Jonathan Jackson","avatar":""},{"name":"Paula Shaw","avatar":""},{"name":"Oliver ''Ole'' Z","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324532);
