INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-nguoi-phu-nu', 'Tám Người Phụ Nữ', '8 Women', 'https://phimimg.com/upload/vod/20231120-1/dc9d778105effadb1c251446a7a5f4b4.jpg', 'https://phimimg.com/upload/vod/20231120-1/865d7dbf339c88ca84404d488157c110.jpg', '<p>Lấy bối cảnh là những năm 1950, trong 1 gia đình tư sản. Marcel, người đàn ông duy nhất trong gia đình bị phát hiện đã chết do một con dao đâm sau lưng, vào buổi sáng đứa con gái từ Paris về thăm gia đình... Cuộc điều tra tìm kiếm hung thủ đã hé mở ra những bí mật kinh hoàng, làm rớt những chiếc mặt nạ che phủ những tâm hồn đau đớn. Kẻ sát nhân sẽ vẫn thoát được nếu mọi người vẫn cứ giả dối, chỉ có cách để tìm ra hung thủ khi tám người đàn bà nói thật những điều họ che dấu. Và khi hung thủ lộ diện cũng là lúc gia đình chứng kiến một sự thật phũ phàng.</p>', 'Full', 1, 'single', 'completed', 20, 2002, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Catherine Deneuve","avatar":""},{"name":"Isabelle Huppert","avatar":""},{"name":"Fanny Ardant","avatar":""},{"name":"Firmine Richard","avatar":""},{"name":"Emmanuelle Béart","avatar":""},{"name":"Virginie Ledoyen","avatar":""},{"name":"Ludivine Sagnier","avatar":""},{"name":"Danielle Darrieux","avatar":""},{"name":"Dominique Lamure","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324532);
