INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-duc-la-chuyen-nho', 'Tình Dục Là Chuyện Nhỏ', 'Sex Is Zero', 'https://phimimg.com/upload/vod/20231120-1/85e3133f75a9c4aa194abfc3ca72f2ce.jpg', 'https://phimimg.com/upload/vod/20231120-1/570b3a2571af72f4e0bc06c3bf8e7495.jpg', '<p>“Sex is Zero” là tập hợp những câu chuyện giới tính của một nhóm học sinh Hàn Quốc. Bộ phim lập tức gây sốc vì đề cập tới vấn đề tình dục học trò và những cảnh phim nóng &quot;bỏng tay&quot;.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Im Chang-jung","avatar":""},{"name":"Ha Ji-won","avatar":""},{"name":"Jin Jae-young","avatar":""},{"name":"Yoo Chae-young","avatar":""},{"name":"Shin Yi","avatar":""},{"name":"Ham So-won","avatar":""},{"name":"Yun Si-hu","avatar":""},{"name":"Choi Sung-kook","avatar":""},{"name":"Choi Won-young","avatar":""},{"name":"Lee Si-yeon","avatar":""},{"name":"Ki Joo-bong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
