INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('s1m0ne', 'S1m0ne', 'S1m0ne', 'https://phimimg.com/upload/vod/20231120-1/0a9ca33b61453fb5f1976a5800741f7d.jpg', 'https://phimimg.com/upload/vod/20231120-1/b07c72fa654a3fdc7d0cd73c8f8bea72.jpg', '<p>Sự nghiệp của một nhà sản xuất vỡ mộng, người đang tuyệt vọng cho một hit, đang có nguy cơ tuyệt chủng khi ngôi sao của anh ta bước ra khỏi bộ phim. Buộc phải suy nghĩ nhanh, nhà sản xuất quyết định kỹ thuật số tạo một nữ diễn viên &quot;Simone&quot; để phụ cho ngôi sao - nữ diễn viên tổng hợp hoàn toàn đáng tin cậy đầu tiên. &quot;Nữ diễn viên&quot; trở thành một cảm giác qua đêm, với sự nghiệp ca hát lớn, và mọi người đều nghĩ rằng cô ấy là một người thực sự. Tuy nhiên, như Skyrockets nổi tiếng của Simone, anh ta không thể chịu đựng được sự gian lận của mình với chính mình hoặc thế giới.</p>', 'Full', 1, 'single', 'completed', 10, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Al Pacino","avatar":""},{"name":"Rachel Roberts","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Evan Rachel Wood","avatar":""},{"name":"Jay Mohr","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Jason Schwartzman","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Rebecca Romijn","avatar":""},{"name":"James Gleason","avatar":""},{"name":"Christopher Neiman","avatar":""},{"name":"Jolie Jenkins","avatar":""},{"name":"Joel Heyman","avatar":""},{"name":"Benjamin Salisbury","avatar":""},{"name":"Darnell Williams","avatar":""},{"name":"Jim Rash","avatar":""},{"name":"Ron Perk","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3