INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung', 'Anh Hùng', 'Hero 2002', 'https://phimimg.com/upload/vod/20231115-1/9b3931c9a4fb26f968dd3335a4f569e7.jpg', 'https://phimimg.com/upload/vod/20231115-1/0a8b5fb12a53dceb8d7e16456ab517a1.jpg', '<p>Phim Anh Hùng lấy bối cảnh trong thời Trung Quốc cổ đại, trước khi triều đại của hoàng đế đầu tiên, chiến tranh phe phái suốt Sáu Quốc âm mưu ám sát nhà lãnh đạo mạnh mẽ nhất, Tần. Khi một quan chức nhỏ đánh bại ba kẻ thù chính Qin, anh được triệu tập vào cung điện để nói với Tần câu chuyện của chiến thắng đáng ngạc nhiên của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jet Li","avatar":""},{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Zhang Ziyi","avatar":""},{"name":"Chen Daoming","avatar":""},{"name":"Zhongyuan Liu","avatar":""},{"name":"Tianyong Zheng","avatar":""},{"name":"Qin Yan","avatar":""},{"name":"Zhang Yakun","avatar":""},{"name":"James Hong","avatar":""},{"name":"Chang Xiao Yang","avatar":""},{"name":"Jin Ming","avatar":""},{"name":"Ma Wen Hua","avatar":""},{"name":"Shou Xin Wang","avatar":""},{"name":"Xu Kuang Hua","avatar":""},{"name":"Zhang Jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324532);
