INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-si-co-han', 'Kiếm Sĩ Cơ Hàn', 'The Twilight Samurai', 'https://phimimg.com/upload/vod/20231113-1/0c6e063cfbbfc81ef38df108d404faa6.jpg', 'https://phimimg.com/upload/vod/20231113-1/6a7b4e183d9c78eaf7ec0ab3622b8017.jpg', '<p>Iguchi Seibei là một samurai thứ cấp sống trong thời đại đầy biến động của xã hội Nhật Bản đầu thế kỷ thứ 19. Vợ mất đi, Iguchi phải làm việc thật cật lực để trả nợ nên không có thời gian chăm sóc bản thân và giao lưu vời bạn bè, vì vậy anh bị mang biệt danh chàng samurai cơ hàn. Tomoe, một cô gái xinh đẹp và đầy nghị lực với mong muốn được chia sẻ cuộc sống với anh nhưng Iguchi đã từ chối. Mọi chuyện thay đổi kể từ khi Igucho bị bắt buộc phải đi quyết chiến với một samurai bị coi là phản nghịch. Đó là một kiếm sĩ cô đơn có cùng cảnh ngộ với Iguchi, anh đứng trước một lựa chọn sinh tử. Cuối cùng, người bạn mới quen này đã giúp anh một lối thoát và có được một cuộc sống hạnh phúc với Tomoe.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hiroyuki Sanada","avatar":""},{"name":"Rie Miyazawa","avatar":""},{"name":"Nenji Kobayashi","avatar":""},{"name":"Mitsuru Fukikoshi","avatar":""},{"name":"Min Tanaka","avatar":""},{"name":"Ren Osugi","avatar":""},{"name":"Hiroshi Kanbe","avatar":""},{"name":"Miki Ito","avatar":""},{"name":"Erina Hashiguchi","avatar":""},{"name":"Keiko Kishi","avatar":""},{"name":"Reiko Kusamura","avatar":""},{"name":"Tetsurō Tamba","avatar":""},{"name":"Kanako Fukaura","avatar":""},{"name":"Makoto Akatsuka","avatar":""},{"name":"Masahiro Sato","avatar":""},{"name":"Masayasu Kitayama","avatar":""},{"name":"Baijaku Nak","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
