INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-my-tram-lang', 'Người Mỹ Trầm Lặng', 'The Quiet American', 'https://phimimg.com/upload/vod/20231113-1/609e9a13de40b1a73fecba3a5f813d5f.jpg', 'https://phimimg.com/upload/vod/20231113-1/64c793158ca5142c583319890386828c.jpg', '<p>Vào đầu những năm 1950 tại Việt Nam, một thanh niên Mỹ vướng vào mối tình tay ba đầy nguy hiểm khi phải lòng cô bồ nhí xinh đẹp của một nhà báo người Anh. Khi chiến tranh nổ ra xung quanh họ, bộ ba chìm sâu hơn vào thế giới của ma túy, đam mê và sự phản bội, nơi dường như không có gì giống như vậy.</p>', 'Full', 1, 'single', 'completed', 17, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Caine","avatar":""},{"name":"Brendan Fraser","avatar":""},{"name":"Do Thi Hai Yen","avatar":""},{"name":"Tzi Ma","avatar":""},{"name":"Rade Šerbedžija","avatar":""},{"name":"Robert Stanton","avatar":""},{"name":"Holmes Osborne","avatar":""},{"name":"Quang Hai","avatar":""},{"name":"Ferdinand Hoang","avatar":""},{"name":"Pham Thi Mai Hoa","avatar":""},{"name":"Mathias Mlekuz","avatar":""},{"name":"Kevin Tran","avatar":""},{"name":"Lap Phan","avatar":""},{"name":"Tim Bennett","avatar":""},{"name":"Jeff Truman","avatar":""},{"name":"Hong Nhung","avatar":""},{"name":"Lucia Noyce","avatar":""},{"name":"Hiliary Douglas","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324532);
