INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-lem-ii-giac-mo-thanh-su-that', 'Lọ Lem II: Giấc Mơ Thành Sự Thật', 'Cinderella II: Dreams Come True', 'https://phimimg.com/upload/vod/20231113-1/56085dc8e86a4fdd689112cb956bf66b.jpg', 'https://phimimg.com/upload/vod/20231113-1/a0de5d5cafa039aa692815835ef7e38a.jpg', '<p>Cinderella II: Dreams Come True (Lọ Lem II: Giấc mơ thành sự thật): là phần tiếp theo dạng direct-to-video đầu tiên của bộ phim Lọ Lem của Disney vào năm 1950. Phim được làm từ năm 2001 và phát hành vào 26/2/2002. Tiếp theo phần II là Cinderella III: A Twist in Time vào năm 2007. Phim gồm có 3 phần: Lọ Lem chuẩn bị cho một buổi dạ hội, chú chuột Jag được biến thành người, một trong 2 cô chị độc ác của Lọ Lem (Anastasia, cô nàng tóc đỏ mặc váy hồng) đã yêu một chàng nướng bánh trẻ tuổi, một người có địa vị thấp mà Qúy bà Tremaine và Drizella nhất quyết phản đối.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2002, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Jennifer Hale","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Corey Burton","avatar":""},{"name":"Andre Stojka","avatar":""},{"name":"Russi Taylor","avatar":""},{"name":"Susanne Blakeslee","avatar":""},{"name":"Tress MacNeille","avatar":""},{"name":"Holland Taylor","avatar":""},{"name":"Christopher Daniel Barnes","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Bob Bergen","avatar":""},{"name":"Susan Blu","avatar":""},{"name":"Rodger Bumpass","avatar":""},{"name":"Jennifer Darling","avatar":""},{"name":"Paul Eiding","avatar":""},{"name":"Sherry L","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324532);
