INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ali-g-indahouse', 'Ali G Indahouse', 'Ali G Indahouse', 'https://phimimg.com/upload/vod/20231112-1/5a1c0a6f91f8afbdf20c4911c9174ccb.jpg', 'https://phimimg.com/upload/vod/20231112-1/c744bf90cabb8632dcedc4bf19b23468.jpg', '<p>Ali G (Sacha Baron Cohen) Vô tình trở thành một con tốt trong âm mưu độc ác của Thủ tướng David Carlton (Charles Dance) để lật đổ Thủ tướng của Vương quốc Anh (Sir Michael Gambon). Tuy nhiên, thay vì đưa Thủ tướng xuống, Ali được quốc gia chấp nhận là tiếng nói của tuổi trẻ và &quot;thực tế&quot;, khiến thủ tướng và chính phủ của ông phổ biến hơn bao giờ hết.</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Sacha Baron Cohen","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Kellie Bright","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Paul Clayton","avatar":""},{"name":"Rhona Mitra","avatar":""},{"name":"Barbara New","avatar":""},{"name":"Emilio Rivera","avatar":""},{"name":"Gina La Piana","avatar":""},{"name":"Dana de Celis","avatar":""},{"name":"Martin Ball","avatar":""},{"name":"Steffan Rhodri","avatar":""},{"name":"Eileen Essell","avatar":""},{"name":"Frank Dunne","avatar":""},{"name":"Naomi Campbell","avatar":""},{"name":"Tony Way","avatar":""},{"name":"Jon Sn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324532);
