INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ali-g-indahouse', 'Ali G Indahouse', 'Ali G Indahouse', 'ali g indahouse ali g indahouse sacha baron cohen michael gambon charles dance kellie bright martin freeman paul clayton rhona mitra barbara new emilio rivera gina la piana dana de celis martin ball steffan rhodri eileen essell frank dunne naomi campbell tony way jon sn ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-do-khong-gian', 'Dị Độ Không Gian', 'Inner Senses', 'https://phimimg.com/upload/vod/20231111-1/d16ad4eaa826cb78dbabb56d9ef0896d.jpg', 'https://phimimg.com/upload/vod/20231111-1/4c1e78fb592e875947e32e5e46bf04ec.jpg', '<p>Dị độ không gian (Inner Senses) là bộ phim kinh dị tâm lý của Hong Kong, ra mắt năm 2002 do La Chí Lương làm đạo diễn. Phim có sự tham gia của Trương Quốc Vinh và Lâm Gia Hân. Bộ phim làm về đề tài ảo giác, chấn thương tâm lý, trầm cảm và tự sát. Trong phim, Trương Quốc Vinh vào vai bác sĩ tâm lý A Chiêm. Trong lúc làm việc, anh đã gặp Chương Hân, một cô gái tin rằng mình có khả năng nhìn thấy ma. Với tư cách một bác sĩ, A Chiêm đã tiếp cận Chương Hân, đào sâu vào những quá khứ của cô để tìm cách giải quyết vấn đề. Thế nhưng trong quá trình điều trị cho Chương Hân, A Chiêm lại phát hiện ra những vấn đề tâm lý của chính mình. Anh bắt đầu gặp những ảo giác về người bạn gái cũ. Dị độ không gian là bộ phim cuối cùng của Trương Quốc Vinh, khán giả tin rằng anh đã đưa cảm xúc thật của mình vào nhân vật trong phim, và bộ phim được đánh giá thành công cũng là nhờ vào diễn xuất của các diễn viên chính. Bộ phim này cũng giúp Trương Quốc Vinh nhận được đề cử Nam diễn viên xuất sắc nhất của Giải thưởng Điện ảnh Hong Kong và Liên hoan phim Kim Mã.</p>', 'Full', 1, 'single', 'completed', 15, 2002, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leslie Cheung","avatar":""},{"name":"Karena Lam","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Valerie Chow","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""},{"name":"Leung Tin","avatar":""},{"name":"So Pik Wong","avatar":""},{"name":"Maggie Poon Mei Kei","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324532);
