INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kich-ban-chuyen-the', 'Kịch Bản Chuyển Thể', 'Adaptation.', 'https://phimimg.com/upload/vod/20231111-1/3744936d77b014ff165bd8cd441302a1.jpg', 'https://phimimg.com/upload/vod/20231111-1/3acea021e7253b02e86d698197d9c134.jpg', '<p>Charlie và Donald là hai anh em song sinh nhưng tính cách trai ngược nhau. Charlie thì trầm lặng khép kín, Donald thì vui vẻ cởi mở, cả hai đều là kịch tác gia. Trong khi Charlie là một cây bút có tên tuổi của các hãng phim thì Donald đang mày mò với tác phẩm hành động kinh dị của mình. Susan Orlean là phóng viên của tờ NewYoker Times, cô vửa cho ra tác phẩm &quot; THE ORCHID THIEF&quot;, một truyện ngắn viết về nhân vật John Larouche, một kẻ săn lùng hoa lan dại. Charlie được hãng phim mời viết kịch bản chuyển thể cho cuốn BEST SELLER này. Charlie vô cùng bối rối, không biết bắt đầu như thế nào. Trong cơn tuỵêt vọng, anh nhờ tới sự giúp đỡ của cậu em Donald.lúc này đang hân hoan với kịch bản đầu tay ra mắt thành công.</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Jay Tavare","avatar":""},{"name":"Litefoot","avatar":""},{"name":"Roger Willie","avatar":""},{"name":"Jim Beaver","avatar":""},{"name":"Cara Seymour","avatar":""},{"name":"Doug Jones","avatar":""},{"name":"Gary Farmer","avatar":""},{"name":"Peter Jason","avatar":""},{"name":"Gregory Itzin","avatar":""},{"name":"Curtis Hanson","avatar":""},{"name":"Agnes NaDene Baddoo","avatar":""},{"name":"Paul Fortune","avatar":""},{"name":"Paul Jasmin","avatar":""},{"name":"Lisa Love","avatar":""},{"name":"Wendy Mog","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324532);
