INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-am-anh', 'Sự Ám Ảnh', 'One Hour Photo', 'https://phimimg.com/upload/vod/20231110-1/10947af2c7970b70ffee6c4edf83c96a.jpg', 'https://phimimg.com/upload/vod/20231110-1/52a68660fea32de8c9f32d15c4e1f36b.jpg', '<p>Sy Parrish là một người đàn ông trung niên độc thân làm việc tại một cửa hàng rửa ảnh. Bất ngờ bị sa thải và tình cờ phát hiện ra một bí mật tồi tệ đã khiến Sy thay đổi. Sự cô độc giày xéo, sự bệnh hoạn tiềm ẩn trong con người Sy từ những ký ức của tuổi thơ bị chà đạp qua những bức ảnh biến thái đã khiến ông từ một con người hiền lành dễ thương thành một người đàn ông nguy hiểm đối với người khác… Trong đó có gia đình Nina, một gia đình hạnh phúc luôn người coi ông như người thân thiết trong nhà. Cho đến một hôm ông bị sa thải và tình cờ biết được bí mật về vụ ngoại tình của người chồng trong gia đình mà ông yêu mến, Sy trở thành một con người đáng sợ...</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"Michael Vartan","avatar":""},{"name":"Gary Cole","avatar":""},{"name":"Erin Daniels","avatar":""},{"name":"Clark Gregg","avatar":""},{"name":"Nick Searcy","avatar":""},{"name":"Dylan Smith","avatar":""},{"name":"Eriq La Salle","avatar":""},{"name":"Paul Hansen Kim","avatar":""},{"name":"Lee Garlington","avatar":""},{"name":"Marion Calvert","avatar":""},{"name":"David Moreland","avatar":""},{"name":"Shaun P. O''Hagan","avatar":""},{"name":"Jim Rash","avatar":""},{"name":"Dave Engfer","avatar":""},{"name":"Jimmy Shubert","avatar":""},{"name":"An","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324532);
