INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-cung-lap-phuong-2-sieu-lap-phuong', 'Mê Cung Lập Phương 2: Siêu Lập Phương', 'Cube 2: Hypercube', 'https://phimimg.com/upload/vod/20231110-1/beb8e6843b5c30a18076ebe89720252f.jpg', 'https://phimimg.com/upload/vod/20231110-1/b576ec0be85304e81c02d8c91a753926.jpg', '<p>Phần tiếp theo của bộ phim đầu tiên kinh phí thấp Cube. Lần này, các tù nhân tìm thấy chính họ trong một môi trường hình khối tiên tiến hơn mà họ phải trốn thoát trước khi bị giết. Một bộ phim khoa học viễn tưởng trong đó không gian và thời gian có nhiều hơn một con đường.</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Kari Matchett","avatar":""},{"name":"Geraint Wyn Davies","avatar":""},{"name":"Grace Lynn Kung","avatar":""},{"name":"Matthew Ferguson","avatar":""},{"name":"Neil Crone","avatar":""},{"name":"Barbara Gordon","avatar":""},{"name":"Lindsey Connell","avatar":""},{"name":"Greer Kent","avatar":""},{"name":"Bruce Gray","avatar":""},{"name":"Philip Akin","avatar":""},{"name":"Paul Robbins","avatar":""},{"name":"Andrew Scorer","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324532);
