INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-wars-phan-2-cuoc-tan-cong-cua-nguoi-vo-tinh', 'Star Wars: Phần 2 - Cuộc Tấn Công Của Người Vô Tính', 'Star Wars: Episode II - Attack of the Clones', 'https://phimimg.com/upload/vod/20231110-1/a4792a4579d6ea5fb927b53b0be842b9.jpg', 'https://phimimg.com/upload/vod/20231110-1/6a2eedc0804a01bc0f34343d06199e21.jpg', '<p>Cậu bé Anakin của mười năm trước giờ đã trở thành một chàng Jedi cao to và đẹp trai. Song song là nàng Padmé Amidala cũng trở thành một cô gái xinh đẹp tuyệt vời. Với sự trở về để bỏ phiếu chống đối việc thành lập quên đội Cộng Hòa Liên bang, Padme trở thành mục tiêu của một loạt vụ ám sát không thành...</p>', 'Full', 1, 'single', 'completed', 13, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hayden Christensen","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Christopher Lee","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Frank Oz","avatar":""},{"name":"Ian McDiarmid","avatar":""},{"name":"Pernilla August","avatar":""},{"name":"Temuera Morrison","avatar":""},{"name":"Jimmy Smits","avatar":""},{"name":"Jack Thompson","avatar":""},{"name":"Leeanna Walsman","avatar":""},{"name":"Ahmed Best","avatar":""},{"name":"Rose Byrne","avatar":""},{"name":"Oliver Ford Davies","avatar":""},{"name":"Ron Falk","avatar":""},{"name":"Jay Laga","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324532);
