INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-khac', 'Thời Khắc', 'The Hours', 'https://phimimg.com/upload/vod/20231109-1/4d1f8e006ab47851d7970b0f3e6be38e.jpg', 'https://phimimg.com/upload/vod/20231109-1/c0c08171147ddc7ac6bf13ec8f31552d.jpg', '<p>Thời khắc nói về Laura Brown, một bà nội trợ có thai, đang có kế hoạch một bữa tiệc dành cho chồng cô, nhưng cô không thể ngừng đọc cuốn tiểu thuyết &quot;Bà Dalloway &quot;. Clarissa Vaughn, một người phụ nữ hiện đại sống trong thời điểm hiện nay là một bữa tiệc cho cô bạn của Richard, một tác giả nổi tiếng chết vì AIDS. Hai câu chuyện được đồng thời liên kết với các công việc và cuộc sống của Virginia Woolf, người đang viết cuốn tiểu thuyết đề cập trước.</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Julianne Moore","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Stephen Dillane","avatar":""},{"name":"Miranda Richardson","avatar":""},{"name":"George Loftus","avatar":""},{"name":"Charley Ramm","avatar":""},{"name":"Sophie Wyburd","avatar":""},{"name":"Lyndsey Marshal","avatar":""},{"name":"Linda Bassett","avatar":""},{"name":"Christian Coulson","avatar":""},{"name":"Michael Culkin","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Clai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324532);
