INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-tap-nha-giam', 'Bão Táp Nhà Giam', 'Half Past Dead', 'https://phimimg.com/upload/vod/20231109-1/82a8c5b86d5d5806b7daba77e98068ec.jpg', 'https://phimimg.com/upload/vod/20231109-1/b328a55c918add54cefe2d51841a4110.jpg', '<p>Một kẻ chủ mưu tội phạm lên kế hoạch thâm nhập nhà tù công nghệ cao để thuyết phục một người đàn ông lãnh án tử hé lộ nơi y giấu số tài sản từ vụ trộm chưa được phá giải.</p>', 'Full', 1, 'single', 'completed', 16, 2002, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Morris Chestnut","avatar":""},{"name":"Ja Rule","avatar":""},{"name":"Nia Peeples","avatar":""},{"name":"Alexandra Kamp","avatar":""},{"name":"Claudia Christian","avatar":""},{"name":"Tony Plana","avatar":""},{"name":"Kurupt","avatar":""},{"name":"Michael Taliferro","avatar":""},{"name":"Bruce Weitz","avatar":""},{"name":"Matt Battaglia","avatar":""},{"name":"Richard Bremmer","avatar":""},{"name":"Stephen J. Cannell","avatar":""},{"name":"Linda Thorson","avatar":""},{"name":"Michael McGrady","avatar":""},{"name":"Ross King","avatar":""},{"name":"Yasmina Filali","avatar":""},{"name":"Ke","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324532);
