INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-thu-ky-xinh-dep', 'Cô Thư Ký Xinh Đẹp', 'Secretary', 'https://phimimg.com/upload/vod/20231108-1/b8965080d111dbb736c816f9c4143ddd.jpg', 'https://phimimg.com/upload/vod/20231108-1/c5b3df9b255fb4d34fee03bc77db8056.jpg', '<p>Nữ Thư Ký xoay quanh mối quan hệ tình ái đầy nhục dục giữa cô nàng thư ký xinh đẹp tên là Lee Holloway (Maggie Gyllenhaal) và ông chủ của mình, luật sư E. Edward Grey (James Spader đóng). Holloway vốn là một người phụ nữ mong manh sống tình cảm, gần đây cô được trả về từ một bệnh viện về thần kinh, và sau đó cô đã lên kế hoạch đi học để đạt được kỹ năng của một thư ký mà sau đó là cô có thể tìm được việc làm.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Maggie Gyllenhaal","avatar":""},{"name":"James Spader","avatar":""},{"name":"Jeremy Davies","avatar":""},{"name":"Lesley Ann Warren","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Amy Locane","avatar":""},{"name":"Patrick Bauchau","avatar":""},{"name":"Jessica Tuck","avatar":""},{"name":"Oz Perkins","avatar":""},{"name":"Mary Joy","avatar":""},{"name":"Sabrina Grdevich","avatar":""},{"name":"Lacey Kohl","avatar":""},{"name":"Julene Renee","avatar":""},{"name":"Lauren Cohn","avatar":""},{"name":"Christina Gray","avatar":""},{"name":"Cali T. Rossen","avatar":""},{"name":"Lily Knight","avatar":""},{"name":"Ezr","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
