INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('asterix-va-obelix-nhiem-vu-cua-cleopatra', 'Asterix và Obelix Nhiệm Vụ Của Cleopatra', 'Asterix and Obelix Meet Cleopatra', 'https://phimimg.com/upload/vod/20231108-1/259ea235166437e00524bbc6ece8682c.jpg', 'https://phimimg.com/upload/vod/20231108-1/82eb1fc4dbd3deef18c91e6f2cb3bbd8.jpg', '<p>Nữ hoàng Cleopatra xinh đẹp và đầy tham vọng của Ai Cập đánh cược với Quốc vương Ceasar Roman rằng thần dân của bà có thể xây cho ngài một cung điện mới toanh chỉ trong vòng 3 tháng. Nhưng không may mọi kiến trúc sư của bà đều quá kém cỏi, thế là mọi niềm hy vọng dồn vào Numerobis. Chàng trai trẻ đành phải nhờ đến ông bạn già Druid Panaramix từ xứ Galia. Druid, cha đẻ của loại thần dược tăng cường sinh lực, lập tức lên đường cùng hai cộng sự Asterix và Obelix. Với sức mạnh của bộ ba, lâu đài sắp sửa hoàn thành. Ceasar không muốn bị mất mặt bèn sai lính phá hỏng công trình nhưng ngài đã đánh giá quá thấp cặp bài trùng Asterix và Obelix...</p>', 'Full', 1, 'single', 'completed', 18, 2002, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Christian Clavier","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"Jamel Debbouze","avatar":""},{"name":"Monica Bellucci","avatar":""},{"name":"Alain Chabat","avatar":""},{"name":"Claude Rich","avatar":""},{"name":"Gérard Darmon","avatar":""},{"name":"Édouard Baer","avatar":""},{"name":"Dieudonné","avatar":""},{"name":"Mouss Diouf","avatar":""},{"name":"Marina Foïs","avatar":""},{"name":"Bernard Farcy","avatar":""},{"name":"Jean Benguigui","avatar":""},{"name":"Michel Crémadès","avatar":""},{"name":"Jean-Paul Rouve","avatar":""},{"name":"Édouard Montoute","avatar":""},{"name":"Chantal L","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324532);
