INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-hoan-doi-ky-dieu', 'Sự Hoán Đổi Kỳ Diệu', 'The Hot Chick', 'https://phimimg.com/upload/vod/20231108-1/e0f081fa9460f7363d2c372c0ac51cab.jpg', 'https://phimimg.com/upload/vod/20231108-1/17c34ec01947dd6da7166451be1a9a09.jpg', '<p>Jessica Spencer không chỉ là cô gái nổi tiếng nhất trong trường mà còn là người hiền lành nhất. Nhưng mọi thứ thay đổi đối với cô thiếu niên hấp dẫn khi một tai nạn quái đản liên quan đến một đôi bông tai bị nguyền rủa và một cuộc gặp gỡ tình cờ tại một trạm xăng khiến cô phải hoán đổi thân xác với Clive, một kẻ gian xảo. Jessica, trong hình dạng của Clive đáng ghét, phải vật lộn để điều chỉnh với sự thay đổi triệt để này và bắt đầu lấy lại cơ thể của chính mình trước buổi vũ hội sắp tới.</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rob Schneider","avatar":""},{"name":"Rachel McAdams","avatar":""},{"name":"Anna Faris","avatar":""},{"name":"Matthew Lawrence","avatar":""},{"name":"Eric Christian Olsen","avatar":""},{"name":"Robert Davi","avatar":""},{"name":"Melora Hardin","avatar":""},{"name":"Alexandra Holden","avatar":""},{"name":"Maritza Murray","avatar":""},{"name":"Fay Hauser","avatar":""},{"name":"Jodi Long","avatar":""},{"name":"Tia Mowry","avatar":""},{"name":"Tamera Mowry-Housley","avatar":""},{"name":"Lee Garlington","avatar":""},{"name":"Angie Stone","avatar":""},{"name":"Matt Weinberg","avatar":""},{"name":"Leila Kenz","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324532);
