INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rong-lua', 'Rồng Lửa', 'Reign of Fire', 'https://phimimg.com/upload/vod/20231103-1/9fc1368229f7a9a226328bdf8404b8c8.jpg', 'https://phimimg.com/upload/vod/20231103-1/3fc68584e80847cf4beb545cc159b7b3.jpg', '<p>Vào một ngày tại thành phố London, cậu bé Quinn 12 tuổi đến thăm nơi làm việc của mẹ dưới lòng đất. Rồi họ bỗng nghe thấy hơi thở rất lớn và nặng nhọc, hơi thở của một con rồng. Trong lúc đưa Quinn lên mặt đất, mẹ cậu đã chết. 20 năm sau, cả thế giới lo lắng trong sự đe dọa của loài rồng. Họ sống trong sợ hãi và lo âu. Cách duy nhất chính là chiến đấu đến cùng để tranh giành sự sinh tồn.</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Matthew McConaughey","avatar":""},{"name":"Izabella Scorupco","avatar":""},{"name":"Gerard Butler","avatar":""},{"name":"Alexander Siddig","avatar":""},{"name":"Scott Moutter","avatar":""},{"name":"David Kennedy","avatar":""},{"name":"Ned Dennehy","avatar":""},{"name":"Rory Keenan","avatar":""},{"name":"Terence Maynard","avatar":""},{"name":"Doug Cockle","avatar":""},{"name":"Randall Carlton","avatar":""},{"name":"Ben Thornton","avatar":""},{"name":"Alice Krige","avatar":""},{"name":"Malcolm Douglas","avatar":""},{"name":"Berts Folan","avatar":""},{"name":"Brian","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324532);
