INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-tam-chan', 'Quái Vật Tám Chân', 'Eight Legged Freaks', 'https://phimimg.com/upload/vod/20231102-1/d90faa4a048c68c66306742211640fae.jpg', 'https://phimimg.com/upload/vod/20231102-1/0fef65b0ba8912b30fce558a19788812.jpg', '<p>Chris McCormick trở về quê hương yên tĩnh Prosperity, Arizona, để mở lại mỏ khai thác của người cha quá cố. Tuy nhiên, một vụ tràn hóa chất và chất thải độc hại gây chết người đã tạo ra một đội quân nhện khổng lồ nguy hiểm. Cuộc sống của người dân địa phương đang bị đe dọa, Chris và cảnh sát trưởng Sam Parker phải huy động một nhóm cư dân của thị trấn vào cuộc chiến chống lại những con quái vật tám chân khát máu.</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"David Arquette","avatar":""},{"name":"Kari Wuhrer","avatar":""},{"name":"Doug E. Doug","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Rick Overton","avatar":""},{"name":"Matt Czuchry","avatar":""},{"name":"Riley Smith","avatar":""},{"name":"Leon Rippy","avatar":""},{"name":"Randi Klein","avatar":""},{"name":"Terey Summers","avatar":""},{"name":"Scott Terra","avatar":""},{"name":"Eileen Ryan","avatar":""},{"name":"Jane Edith Wilson","avatar":""},{"name":"Jack Moore","avatar":""},{"name":"Roy Gaintner","avatar":""},{"name":"Jay Arlen Jones","avatar":""},{"name":"Matt Holwick","avatar":""},{"name":"John Stor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324532);
