INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('que-nha-alabama', 'Quê Nhà Alabama', 'Sweet Home Alabama', 'https://phimimg.com/upload/vod/20231031-1/63a0e876f387feff3df5df635fb28288.jpg', 'https://phimimg.com/upload/vod/20231031-1/e8eecff497a557003a4e2fd2c4032859.jpg', '<p>Nhà thiết kế thời trang New York, Melanie Carmichael đột nhiên nhận ra mình đã đính hôn với người độc thân đủ điều kiện nhất của thành phố. Nhưng quá khứ của cô ấy chứa đựng nhiều bí mật - bao gồm cả Jake, người chồng khó tính mà cô ấy kết hôn ở trường trung học, người không chịu ly hôn với cô ấy. Bị ràng buộc và quyết tâm chấm dứt mối quan hệ đầy tranh cãi của họ một lần và mãi mãi, Melanie lẻn về nhà ở Alabama để đối mặt với quá khứ của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Reese Witherspoon","avatar":""},{"name":"Josh Lucas","avatar":""},{"name":"Patrick Dempsey","avatar":""},{"name":"Candice Bergen","avatar":""},{"name":"Mary Kay Place","avatar":""},{"name":"Fred Ward","avatar":""},{"name":"Jean Smart","avatar":""},{"name":"Ethan Embry","avatar":""},{"name":"Melanie Lynskey","avatar":""},{"name":"Courtney Gains","avatar":""},{"name":"Mary Lynn Rajskub","avatar":""},{"name":"Rhona Mitra","avatar":""},{"name":"Nathan Lee Graham","avatar":""},{"name":"Sean Bridgers","avatar":""},{"name":"Fleet Cooper","avatar":""},{"name":"Kevin Sussman","avatar":""},{"name":"Thomas Curt","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
