INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-ban-tia-2', 'Lính Bắn Tỉa 2', 'Sniper 2', 'https://phimimg.com/upload/vod/20231030-1/1dfa6d0e1d27ce1dda3a9babcd787dd7.jpg', 'https://phimimg.com/upload/vod/20231030-1/f5373717c3d95345748309dfc32201a9.jpg', '<p>Một cựu lính bắn tỉa của Thủy quân lục chiến bị lôi kéo trở lại thực hiện một nhiệm vụ tuyệt mật nhằm hạ gục một vị tướng lừa đảo bị cáo buộc điều hành một chiến dịch lén lút thực hiện các nhiệm vụ thanh lọc sắc tộc tấn công và bỏ chạy ở một khu vực được gọi là &quot;Vùng đất không có người&quot;.</p>', 'Full', 1, 'single', 'completed', 17, 2002, 'Vietsub', 'HD', 'Hungary', 0, '[{"name":"Tom Berenger","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Dan Butler","avatar":""},{"name":"Linden Ashby","avatar":""},{"name":"Erika Marozsán","avatar":""},{"name":"Tamás Puskás","avatar":""},{"name":"Can Togay","avatar":""},{"name":"Barna Illyés","avatar":""},{"name":"Ferenc Kovács","avatar":""},{"name":"Dennis Hayden","avatar":""},{"name":"Béla Jáki","avatar":""},{"name":"László Áron","avatar":""},{"name":"Lukács Bicskey","avatar":""},{"name":"Zoltán Seress","avatar":""},{"name":"Tas Szöllösi","avatar":""},{"name":"Ben O''Brien","avatar":""},{"name":"Andrew Hefler","avatar":""},{"name":"Peter Linka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324532);
