INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-da-roi', 'Chuyện Đã Rồi', 'Irreversible', 'https://phimimg.com/upload/vod/20231026-1/1f6ec8c9e52e11d6e8bf5096d9d9ef90.jpg', 'https://phimimg.com/upload/vod/20231026-1/e102a54d590ed003b69886bdd1585756.jpg', '<p>Irreversible có một trong những cảnh sex kinh hoàng nhất trong lịch sử điện ảnh hiện đại.\r Đó là cảnh Alex (Monica Bellucci) tức giận bỏ một bữa tiệc ra về khi bị bạn trai đem ra làm trò cười. Trên đường về nhà, cô vô tình chứng kiến kẻ ma cô có tên le Tenia đánh đập một gái điếm chuyển giới. Alex bị le Tenia để ý. Hắn theo cô xuống đường hầm, đẩy cô vào tường và cưỡng hiếp.
 Một trong những điều khiến cảnh quay này làm người xem sởn da gà và cảm giác như thật là bởi nó là cảnh quay liền. Trên thực tế, cảnh quay này cũng được quay nhiều đúp và hiệu ứng quay liên tục chỉ được tạo ra bằng kỹ xảo.
 Đạo diễn Gaspar Noe cho biết: \&quot;Khóa quần vẫn được giữ nguyên trong lúc chúng tôi quay cảnh này. Nếu không, mọi thứ sẽ là quá sức với Monica. Nhưng sự can thiệp về kỹ xảo trong phần hậu kỳ đã làm cảnh đó trông rất thật</p>', 'Full', 1, 'single', 'completed', 18, 2002, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Monica Bellucci","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"Albert Dupontel","avatar":""},{"name":"Jo Prestia","avatar":""},{"name":"Philippe Nahon","avatar":""},{"name":"Stéphane Drouot","avatar":""},{"name":"Jean-Louis Costes","avatar":""},{"name":"Mick Gondouin","avatar":""},{"name":"Mourad Khima","avatar":""},{"name":"Layde Hellal","avatar":""},{"name":"Dominique Nato","avatar":""},{"name":"Michel Fesche","avatar":""},{"name":"Victoria Jaramillo","avatar":""},{"name":"Jean-Yves Le Quellec","avatar":""},{"name":"Isabelle Giami","avatar":""},{"name":"Fatima Ad","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324532);
