INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('halloween-8-quy-du-phuc-sinh', 'Halloween 8: Quỷ Dữ Phục Sinh', 'Halloween: Resurrection', 'https://phimimg.com/upload/vod/20231026-1/7c1f3dbc38bbfa3698732ed01ca57e67.jpg', 'https://phimimg.com/upload/vod/20231026-1/561d72eb0670e9cce40665f15977dd0a.jpg', '<p>Kẻ giết người hàng loạt Michael Myers vẫn chưa kết thúc với Laurie Strode, và sự cạnh tranh của họ cuối cùng cũng kết thúc. Nhưng đây có phải là lần cuối chúng ta nhìn thấy Myers? Freddie Harris và Nora Winston là những lập trình viên thực tế tại DangerTainment và đang có kế hoạch gửi một nhóm gồm 6 thanh thiếu niên thích cảm giác mạnh đến ngôi nhà thời thơ ấu của Myers. Camera được đặt khắp nhà và không ai có thể ra khỏi nhà... và sau đó Michael về đến nhà!</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jamie Lee Curtis","avatar":""},{"name":"Brad Loree","avatar":""},{"name":"Busta Rhymes","avatar":""},{"name":"Bianca Kajlich","avatar":""},{"name":"Katee Sackhoff","avatar":""},{"name":"Thomas Ian Nicholas","avatar":""},{"name":"Tyra Banks","avatar":""},{"name":"Sean Patrick Thomas","avatar":""},{"name":"Ryan Merriman","avatar":""},{"name":"Daisy McCrackin","avatar":""},{"name":"Luke Kirby","avatar":""},{"name":"Billy Kay","avatar":""},{"name":"Gus Lynch","avatar":""},{"name":"Lorena Gale","avatar":""},{"name":"Marisa Rudiak","avatar":""},{"name":"Brent Chapman","avatar":""},{"name":"Dan Joffre","avatar":""},{"name":"Haig","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324532);
