INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-nhi-2-hon-dao-cua-nhung-giac-mo-da-mat', 'Điệp Viên Nhí 2: Hòn Đảo Của Những Giấc Mơ Đã Mất', 'Spy Kids 2: The Island of Lost Dreams', 'https://phimimg.com/upload/vod/20231026-1/34b62dc4db078a274c87a709871c3952.jpg', 'https://phimimg.com/upload/vod/20231026-1/83a55b1704ce34675f21a8ae9bc39945.jpg', '<p>Khám phá những cuộc phiêu lưu xa hơn của Carmen và Juni Cortez, những người hiện đã gia nhập công việc gián điệp của gia đình với tư cách là đặc vụ OSS cấp 2. Nhiệm vụ mới của họ là giải cứu thế giới khỏi một nhà khoa học điên sống trên một hòn đảo núi lửa với một đàn sinh vật giàu trí tưởng tượng. Trên hòn đảo kỳ lạ này, không có thiết bị nào của Cortez hoạt động và họ phải dựa vào trí thông minh của mình - và dựa vào nhau - để tồn tại và cứu lấy thế giới.</p>', 'Full', 1, 'single', 'completed', 12, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexa PenaVega","avatar":""},{"name":"Daryl Sabara","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Mike Judge","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Matt O''Leary","avatar":""},{"name":"Emily Osment","avatar":""},{"name":"Ricardo Montalban","avatar":""},{"name":"Holland Taylor","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Taylor Momsen","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Bill","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324532);
