INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diep-vien-nhi-2-hon-dao-cua-nhung-giac-mo-da-mat', 'Điệp Viên Nhí 2: Hòn Đảo Của Những Giấc Mơ Đã Mất', 'Spy Kids 2: The Island of Lost Dreams', 'điệp viên nhí 2: hòn đảo của những giấc mơ đã mất spy kids 2: the island of lost dreams alexa penavega daryl sabara antonio banderas carla gugino steve buscemi mike judge danny trejo cheech marin matt o''leary emily osment ricardo montalban holland taylor alan cumming tony shalhoub taylor momsen christopher mcdonald bill ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-new-york', 'Băng Đảng New York', 'Gangs of New York', 'https://phimimg.com/upload/vod/20231026-1/a0b9357349784c95860398add1884fea.jpg', 'https://phimimg.com/upload/vod/20231026-1/11074ff34b3bcc6bd98941915ce5bb9a.jpg', '<p>Manhattan những năm 1860, giao lộ Five Points được coi là khu tăm tối và lúc nhúc dân lưu vong nhất của thành phố, tại đây mọi cái xấu xa và lộn xộn đều có thể được tìm thấy. Amsterdam Vallon một chàng trai gốc Ireland xuất hiện, anh là con trai duy nhất của Priest Vallon – người thủ lĩnh xưa kia của băng Dead Rabbits, tập hợp những người Ireland di cư sang nước Mỹ. Amsterdam trở lại nơi cha anh từng bị William Cutting biệt danh Bill “Đồ Tể” sát hại 16 năm về trước trong một trận đụng độ nảy lửa tranh giành mảnh đất trú chân. Sau ngần ấy năm sống trong trại tị nạn, không ngày nào anh quên được mối thâm thù này. Còn băng của Bill “Đồ Tể” năm nào cũng không quên tổ chức buổi lễ kỷ niệm chiến thắng trước băng Dead Rabbits của Priest Vallon…</p>', 'Full', 1, 'single', 'completed', 22, 2002, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Daniel Day-Lewis","avatar":""},{"name":"Cameron Diaz","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Henry Thomas","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Gary Lewis","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Alec McCowen","avatar":""},{"name":"David Hemmings","avatar":""},{"name":"Lawrence Gilliard Jr.","avatar":""},{"name":"Cara Seymour","avatar":""},{"name":"Roger Ashton-Griffit","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324532);
