INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-ngoat-dang-nho', 'Bước Ngoặt Đáng Nhớ', 'A Walk to Remember', 'https://phimimg.com/upload/vod/20231026-1/edd8d6ca34602c6b9f91f7767f244534.jpg', 'https://phimimg.com/upload/vod/20231026-1/196adfd511521b45bf3b171f2f073bb6.jpg', '<p>&quot;Bước Ngoặt Đáng Nhớ&quot; Thành phố cảng xinh đẹp phía Bắc Carolina đã gợi cho Landon Carter những kỷ niệm đẹp về năm cuối thời trung học... và về cô gái đã làm bùng lên trong anh niềm tin vào những giấc mơ. Nghiêm nghị, tự tin và mạnh mẽ, Jamie Sullivan là một cô gái chính trực không màn đến công danh sự nghiệp. Anh chàng Landon Carter lạnh lùng, kiêu ngạo luôn trêu chọc bất cứ ai mà anh cảm thấy có hứng thú, và với tính cách khác biệt, Jamie là một trong số đó. Hoàn cảnh đã khiến cho hai con người trái ngược nhau này đến với nhau. Cả Landon và Jamie phát hiện ra rằng, sức mạnh tình yêu có thể hoàn toàn làm thay đổi cuộc sống của họ và làm cho nó có ý nghĩa hơn bao giờ hết...</p>', 'Full', 1, 'single', 'completed', 16, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mandy Moore","avatar":""},{"name":"Shane West","avatar":""},{"name":"Peter Coyote","avatar":""},{"name":"Daryl Hannah","avatar":""},{"name":"Lauren German","avatar":""},{"name":"Clayne Crawford","avatar":""},{"name":"Paz de la Huerta","avatar":""},{"name":"Matt Lutz","avatar":""},{"name":"Al Thompson","avatar":""},{"name":"Jonathan Parks Jordan","avatar":""},{"name":"David Andrews","avatar":""},{"name":"David Lee Smith","avatar":""},{"name":"Xavier Hernandez","avatar":""},{"name":"Marisa Miller","avatar":""},{"name":"Erik Smith","avatar":""},{"name":"Al Butler","avatar":""},{"name":"Seth Howard","avatar":""},{"name":"Juli","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
