INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('barbie-vao-vai-rapunzel', 'Barbie vào vai Rapunzel', 'Barbie as Rapunzel', 'https://phimimg.com/upload/vod/20231026-1/dbe33429b3257daade339f7efb8c96d4.jpg', 'https://phimimg.com/upload/vod/20231026-1/34a058e143c6ac61a8708a3145cfe798.jpg', '<p>Barbie dùng năng lực sáng tạo để vẽ đường thoát khỏi lâu đài và cứu hoàng tử khỏi nanh vuốt của mụ phù thủy độc ác.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2002, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Kelly Sheridan","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Cree Summer","avatar":""},{"name":"Ian James Corlett","avatar":""},{"name":"Mark Hildreth","avatar":""},{"name":"David Kaye","avatar":""},{"name":"Peter Kelamis","avatar":""},{"name":"Russell Roberts","avatar":""},{"name":"Christopher Gaze","avatar":""},{"name":"Terry Klassen","avatar":""},{"name":"Chantal Strand","avatar":""},{"name":"Danny McKinnon","avatar":""},{"name":"Britt McKillip","avatar":""},{"name":"Jocelyne Loewen","avatar":""},{"name":"Dale Wilson","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324532);
