INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('101-chu-cho-dom-ii', '101 Chú Chó Đốm II', '101 Dalmatians II: Patch''s London Adventure', 'https://phimimg.com/upload/vod/20231026-1/c894f2579ec154d91092f6a72f688144.jpg', 'https://phimimg.com/upload/vod/20231026-1/3dac786e6ebf87692a9c1d8d1ec6e5dd.jpg', '<p>Việc trở thành một trong 101 khiến Patch bị ảnh hưởng nặng nề, người không cảm thấy mình là người độc đáo. Khi anh &quot;vô tình bị bỏ lại vào ngày chuyển nhà, anh gặp thần tượng của mình, Thunderbolt, người đã mời anh tham gia một chiến dịch quảng bá.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Barry Bostwick","avatar":""},{"name":"Jason Alexander","avatar":""},{"name":"Martin Short","avatar":""},{"name":"Bobby Lockwood","avatar":""},{"name":"Susanne Blakeslee","avatar":""},{"name":"Samuel West","avatar":""},{"name":"Maurice LaMarche","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Jodi Benson","avatar":""},{"name":"Tim Bentinck","avatar":""},{"name":"Kath Soucie","avatar":""},{"name":"Mary MacLeod","avatar":""},{"name":"Michael Lerner","avatar":""},{"name":"Kathryn Beaumont","avatar":""},{"name":"Nicolette Little","avatar":""},{"name":"Ursula Brooks","avatar":""},{"name":"Nick Me","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324532);
