INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('101-chu-cho-dom-ii', '101 Chú Chó Đốm II', '101 Dalmatians II: Patch''s London Adventure', '101 chú chó đốm ii 101 dalmatians ii: patch''s london adventure barry bostwick jason alexander martin short bobby lockwood susanne blakeslee samuel west maurice lamarche jeff bennett jodi benson tim bentinck kath soucie mary macleod michael lerner kathryn beaumont nicolette little ursula brooks nick me ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-cua-chua', 'Thành Phố Của Chúa', 'City of God', 'https://phimimg.com/upload/vod/20231024-1/f4f435cc19e5845c7a8929bfc0c31308.jpg', 'https://phimimg.com/upload/vod/20231024-1/b175fbba74ab1b23cb277852f698ea1b.jpg', '<p>City of God - một khu ổ chuột ở thành phố Rio de Janero - có cái tên như vậy với mong muốn điều tốt đẹp hơn đến với người trong vùng. Vậy mà, thực tế thật khắc nghiệt và tàn nhẫn. Trẻ em tiếp xúc súng đạn nhiều hơn là sách vở. Thanh niên thì trộm cắp, cướp bóc. Thế nhưng người dân chẳng ghét những kẻ trộm cắp lặt vặt, thậm chí còn bao che cho họ bởi người họ căm ghét hơn cả là cảnh sát địa phương. Những tên chuyên quyền này thản nhiên móc nối với bọn cầm đầu xã hội đen, ra sức bắn giết bất kì ai chúng cho là nghi phạm. Đến cảnh sát, người thay mặt cho chính quyền, lại làm ngơ trước tội phạm như vậy thì còn biết trông chờ vào ai? Cái vòng tội lỗi, đói nghèo cứ bám lấy thành phố này.</p>', 'Full', 1, 'single', 'completed', 33, 2002, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Alexandre Rodrigues","avatar":""},{"name":"Leandro Firmino","avatar":""},{"name":"Phellipe Haagensen","avatar":""},{"name":"Douglas Silva","avatar":""},{"name":"Jonathan Haagensen","avatar":""},{"name":"Matheus Nachtergaele","avatar":""},{"name":"Seu Jorge","avatar":""},{"name":"Jefechander Suplino","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"Roberta Rodrigues","avatar":""},{"name":"Luis Otávio","avatar":""},{"name":"Darlan Cunha","avatar":""},{"name":"Thiago Martins","avatar":""},{"name":"Gero Camilo","avatar":""},{"name":"Daniel Zettel","avatar":""},{"name":"Charl","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324532);
