INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('28-ngay-sau', '28 Ngày Sau', '28 Days Later', 'https://phimimg.com/upload/vod/20231023-1/c906333f9e494e4d1907d09297cc7927.jpg', 'https://phimimg.com/upload/vod/20231023-1/4a55bcefea6c7fe7864bbd618a989e15.jpg', '<p>Một căn bệnh truyền nhiễm nguy hiểm bùng phát thành đại dịch trên khắp nước Anh, đẩy nền văn minh nhân loại vào nguy cơ tuyệt diệt. Những người sống sót chạy về một căn cứ quân sự để tập hợp lực lượng chống lại những con bệnh...</p>', 'Full', 1, 'single', 'completed', 15, 2002, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Megan Burns","avatar":""},{"name":"Christopher Eccleston","avatar":""},{"name":"Noah Huntley","avatar":""},{"name":"Luke Mably","avatar":""},{"name":"Stuart McQuarrie","avatar":""},{"name":"Ricci Harnett","avatar":""},{"name":"Leo Bill","avatar":""},{"name":"Junior Laniyan","avatar":""},{"name":"Ray Panthaki","avatar":""},{"name":"Sanjay Rambaruth","avatar":""},{"name":"Marvin Campbell","avatar":""},{"name":"Christopher Dunne","avatar":""},{"name":"Emma Hitching","avatar":""},{"name":"Ale","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324532);
