INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-van-chuyen-2002', 'Người Vận Chuyển', 'The Transporter', 'https://phimimg.com/upload/vod/20231023-1/508f2078279c3858f324171da19bfce0.jpg', 'https://phimimg.com/upload/vod/20231023-1/cf7d988a01e8ca765a5c31d0e609773c.jpg', '<p>Frank Martin - cựu thành viên của lực lượng đặc biệt tại Mỹ, sau khi về sống tại Pháp anh nhận vận chuyển hàng với 3 điều luật : 1 - Không thay đổi giao kèo.&nbsp; 2 - Không hỏi tên của chủ hàng. 3 - Không bao giờ xem gói hàng nhận vận chuyển.&nbsp; Mọi thương vụ của anh đều làm đúng với 3 điều luật trên nhưng khi anh nhận chuyển một gói hàng của &quot;Wall Street&quot; thì anh đã vi phạm vào điều luật thứ 3. Anh phát hiện một cô gái xinh đẹp - Lai - trong đó và sự thật đằng sau phi vụ này là một đường dây buôn người từ Trung Quốc sang Pháp do chính cha của Lai làm chủ mưu.</p>', 'Full', 1, 'single', 'completed', 18, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"François Berléand","avatar":""},{"name":"Matt Schulze","avatar":""},{"name":"Ric Young","avatar":""},{"name":"Doug Rand","avatar":""},{"name":"Didier Saint Melin","avatar":""},{"name":"Tonio Descanvelle","avatar":""},{"name":"Laurent Desponds","avatar":""},{"name":"Matthieu Albertini","avatar":""},{"name":"Vincent Nemeth","avatar":""},{"name":"Jean-Yves Bilien","avatar":""},{"name":"Jean-Marie Paris","avatar":""},{"name":"Adrian Dearnell","avatar":""},{"name":"Alfred Lot","avatar":""},{"name":"Audrey Hamm","avatar":""},{"name":"Sebast","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad35