INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-chau-bau', 'Hành Tinh Châu Báu', 'Treasure Planet', 'https://phimimg.com/upload/vod/20231022-1/2d33bec4c50bc9a9383d522ac625552e.jpg', 'https://phimimg.com/upload/vod/20231022-1/99d063fbc5a49d3d8c80eb4a6cf1f033.jpg', '<p>Khi cậu bé lái thuyền buồm không gian Jim Hawkins phát hiện ra bản đồ dẫn đến &quot;chiến lợi phẩm của một ngàn thế giới&quot; liên thiên hà, một đầu bếp người máy tên John Silver đã dạy cậu cách chiến đấu với các siêu tân tinh và bão không gian trên hành trình tìm kiếm kho báu.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Brian Murray","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"David Hyde Pierce","avatar":""},{"name":"Martin Short","avatar":""},{"name":"Dane A. Davis","avatar":""},{"name":"Michael Wincott","avatar":""},{"name":"Laurie Metcalf","avatar":""},{"name":"Roscoe Lee Browne","avatar":""},{"name":"Patrick McGoohan","avatar":""},{"name":"Corey Burton","avatar":""},{"name":"Michael McShane","avatar":""},{"name":"Tony Jay","avatar":""},{"name":"Austin Majors","avatar":""},{"name":"Jack Angel","avatar":""},{"name":"Bob Bergen","avatar":""},{"name":"Rodger","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324532);
