INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-ao-den-2', 'Đặc Vụ Áo Đen 2', 'Men in Black II', 'https://phimimg.com/upload/vod/20231023-1/3ddf6e35f8aed0ce844fabd0d24d662a.jpg', 'https://phimimg.com/upload/vod/20231023-1/1cf338be7a5e7ac7d94f148269cf97ad.jpg', '<p>Sau khi hoàn thành nhiệm vụ, đặc vụ K lui về ở ẩn, vui thú điền viên. Còn đặc vụ J vẫn làm cho MIB và loay hoay đi tìm một cộng sự mới cho mình. Nhưng đặc vụ K sớm phải từ bỏ cuộc sống dân thường của mình để trở lại MIB khi Trái đất lại lâm nguy và ông là người duy nhất biết cách đánh bại kẻ chủ mưu. Song song với nhiệm vụ cứu Trái đất, đặc vụ K còn phải giải quyết chuyện tình cảm của mình với Laura Vazquez – một cô hầu gái, người sau này trở thành chìa khóa của mọi vấn đề. Tất nhiên, nhiệm vụ của hai đặc vụ J và K không hề đơn giản, nhất là khi K chẳng còn nhỡ chút gì về MIB do đã bị xóa trí nhớ và kẻ thù cũng hiểu rõ K như ông hiểu kẻ đó.</p>', 'Full', 1, 'single', 'completed', 16, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Tommy Lee Jones","avatar":""},{"name":"Lara Flynn Boyle","avatar":""},{"name":"Rosario Dawson","avatar":""},{"name":"Johnny Knoxville","avatar":""},{"name":"Rip Torn","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Jack Kehler","avatar":""},{"name":"David Cross","avatar":""},{"name":"Colombe Jacobsen-Derstine","avatar":""},{"name":"Peter Spellos","avatar":""},{"name":"Michael Rivkin","avatar":""},{"name":"Michael Bailey Smith","avatar":""},{"name":"Lenny Venito","avatar":""},{"name":"Howard Spi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324532);
