INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-si-duong-cam', 'Nghệ Sĩ Dương Cầm', 'The Pianist', 'https://phimimg.com/upload/vod/20231023-1/934dea0d4ff46d7c19fec284325ce3c4.jpg', 'https://phimimg.com/upload/vod/20231023-1/916adb60a0afe2ca5a758655664a7302.jpg', '<p>Câu chuyện có thật về những trải nghiệm của nghệ sĩ dương cầm Władysław Szpilman ở Warsaw trong thời kỳ Đức Quốc xã chiếm đóng. Khi những người Do Thái của thành phố bị buộc vào một khu ổ chuột, Szpilman tìm việc chơi đàn trong một quán cà phê; và khi gia đình ông bị trục xuất vào năm 1942, ông trốn lại và sinh tồn trong đống đổ nát của thành phố bị chiến tranh tàn phá.</p>', 'Full', 1, 'single', 'completed', 22, 2002, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Adrien Brody","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Frank Finlay","avatar":""},{"name":"Maureen Lipman","avatar":""},{"name":"Emilia Fox","avatar":""},{"name":"Ed Stoppard","avatar":""},{"name":"Julia Rayner","avatar":""},{"name":"Jessica Kate Meyer","avatar":""},{"name":"Michal Zebrowski","avatar":""},{"name":"Wanja Mues","avatar":""},{"name":"Richard Ridings","avatar":""},{"name":"Nomi Sharron","avatar":""},{"name":"Anthony Milner","avatar":""},{"name":"Lucy Skeaping","avatar":""},{"name":"Roddy Skeaping","avatar":""},{"name":"Ben Harlan","avatar":""},{"name":"Thomas Lawin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324532);
