INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-dao-hai-luoi', 'Con Dao Hai Lưỡi', 'Equilibrium', 'https://phimimg.com/upload/vod/20231021-1/d5f924e1cd5982e79dd35ba6b0d58e1b.jpg', 'https://phimimg.com/upload/vod/20231021-1/229d4f55fe3036a71dadc7d11f640669.jpg', '<p>Cuối thế chiến III của thế kỷ 21, nước Libria được đặt dưới sự kiểm soát của chính phủ độc tài Tetragramaton. Các nhà lãnh đạo e sợ rằng, nhân loại sẽ không thể tồn tại nếu chiến tranh thế giới thứ IV xảy ra. Vì thế, họ lên kế hoạch xây dựng một xã hội mới với những điều luật hoàn toàn khác so với trước kia.</p>', 'Full', 1, 'single', 'completed', 16, 2002, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Taye Diggs","avatar":""},{"name":"Angus Macfadyen","avatar":""},{"name":"Matthew Harbour","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Emily Siewert","avatar":""},{"name":"Maria Pia Calzone","avatar":""},{"name":"Dominic Purcell","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"David Hemmings","avatar":""},{"name":"David Barrash","avatar":""},{"name":"Christian Kahrmann","avatar":""},{"name":"John Keogh","avatar":""},{"name":"Dirk Martens","avatar":""},{"name":"Florian","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324532);
