INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bip', 'Vua Bịp', 'The Conman', 'https://phimimg.com/upload/vod/20231012-1/cde9a086827acc5204bc98a6a29cc335.jpg', 'https://phimimg.com/upload/vod/20231012-1/782724e4096b07f7b86ee9b8018b012d.jpg', '<p>Ka-shing đã sống cả cuộc đời mình như một chàng trai kém may mắn, cho đến một ngày anh được Spring, một người anh em trong băng đảng, mời làm việc. Spring là một tay cờ bạc và biến vận xui của Ka-shing thành Hòn đá Phù thủy. Kau, kẻ thù của Spring, thua lỗ nặng tại sòng bạc của mình và thề sẽ loại bỏ cả hai. Ka ra lệnh cho người của mình bóp méo vận may của Ka-shing bằng cách phá hủy Phong Thủy của ông. Nhưng tất cả chỉ là một mánh lới quảng cáo để giành chiến thắng trong cuộc thi cờ bạc, hay Ka-shing chắc chắn sẽ mất khả năng đánh bạc của mình?</p>', 'Full', 1, 'single', 'completed', 14, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Nick Cheung","avatar":""},{"name":"Wyman Wong Wai-Man","avatar":""},{"name":"Stephen Fung","avatar":""},{"name":"Mango Wong","avatar":""},{"name":"Monica Lo","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Wong Tin-lam","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Philip Keung Hiu-Man","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324532);
