INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-5-va-thang-8', 'Tháng 5 Và Tháng 8', 'May & August', 'null', 'https://phimimg.com/upload/vod/20231010-1/3ef91de04aae19ce6ed742e2df549e3f.jpg', '<p>Tháng 5 và tháng 8 là hai chị em tốt. Họ sống trong một gia đình ấm áp từ nhỏ và cuộc sống trôi qua em đềm hạnh phúc. Sự xuất hiện của chiến tranh đã phá vỡ hạnh phúc của gia đình của hai chị em, người cha qua đời và cả gia đình trông cậy hết vào mẹ - một người phụ nữ mạnh mẽ. Thảm họa không chỉ có thể, tháng 8 bị sốt cao, mẹ đã vượt qua bao nguy hiểm đến con đường&nbsp; bị quân đội Nhật phong tỏa để đi tìm , về sau mẹ không may qua đời, cũng may trốn thoát, tháng 5 đưa em gái đến trại tị nạn giáo hội xây giành cho người nghèo. Cuộc sống trong trại tị nạn thật khó khăn và đầy nguy hiểm. Cuối cùng, vào tháng Năm và tháng Tám, có người thân đến tìm, cùng với cậu hai chị em đến Trấn Giang và ở đó hai chị em đã gặp lại người đàn ông mà hai chị em đã từng gặp. Chẳng mấy chốc, Tr</p>', 'Full', 1, 'single', 'completed', 27, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Cecilia Yip","avatar":""},{"name":"Lin Quan","avatar":""},{"name":"Lap-yi Kau","avatar":""},{"name":"Lee Wa-Lun","avatar":""},{"name":"May Xue","avatar":""},{"name":"Xue Bin","avatar":""},{"name":"Sung Gwong-Wa","avatar":""},{"name":"Li Hui-Xia","avatar":""},{"name":"Xu Cai-gen","avatar":""},{"name":"Mark Cheung Lui","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324532);
