INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tu-ha-dong', 'Sư Tử Hà Đông', 'The Lion Roars', 'https://phimimg.com/upload/vod/20231010-1/48b41537ed085a18a6a7d80ca4262863.jpg', 'https://phimimg.com/upload/vod/20231010-1/5aec1a13cdd4819054a74f2e5aa27d75.jpg', '<p>Sư tử Hà Đông (Ngo ga yau yat chek hiu dung see) là một phim tình cảm hài nhẹ nhàng pha chút hiện đại có nội dung nói về đề tài tình yêu với những tình huống hài hước được thể hiện hết sức thành công của bộ đôi diến viên trai tài gái sắc Cổ Thiên Lạc và Trương Bá Chi.&nbsp; Quý Thường là một tú tài nổi tiếng, trong một lần vô tình anh đã gặp Nguyệt Nga đang ra tay cứu anh trai mình. Sau đó Nguyệt Nga còn cổ vũ khi Quý Thường biểu diễn trên sân khấu. Chỉ tình cờ gặp nhau hai lần nhưng cả hai đã thầm cảm mến đối phương. Nhà vua biết được đã ban hôn cho cả hai. Sau khi cưới Nguyệt Nga, Quý Thường mới phát hiện vợ mình rất đanh đá và hay đánh người. Vì vậy anh rất sợ vợ tuy nhiên anh vẫn rất yêu vợ.</p>', 'Full', 1, 'single', 'completed', 16, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Cecilia Cheung","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Wyman Wong Wai-Man","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Emotion Cheung Kam-Ching","avatar":""},{"name":"Raymond Wong Ho-yin","avatar":""},{"name":"Joe Lee Yiu-Ming","avatar":""},{"name":"Fanny Chan Ping-Ping","avatar":""},{"name":"Mao Jian","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324532);
