INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-huyet-nhan', 'Lam Huyết Nhân', 'The Wesley''s Mysterious File', 'https://phimimg.com/upload/vod/20231010-1/4292d29decf1ab57da80dd1ed5d2aa65.jpg', 'https://phimimg.com/upload/vod/20231010-1/5616a9f00a3ba2c31e707a275a27d551.jpg', '<p>Lam Huyết Nhân-The Wesley’s Mysterious File (2002): Wesley là người chuyên chịu trách nhiệm về những sự kiện lạ lùng diễn ra trên trái đất. Một ngày nọ, Wesley gặp Fong trong một cửa hiệu đồ cổ đang tìm cách mua một khúc xương màu xanh. Fong là người của hành tinh Lam Huyết, cô đã rờikhỏi hành tinh của mình 600 năm trước để đi tìm quyển sách thiêng của giống nòi mình. Wesley và Fong nảy sinh tình cảm với nhau trong lúc một đội biệt kích được phái đến để truy đuổi Kill và Rape, 2 người thuộc hành tinh Lam Huyết xuống trái đất để bắt Fong về.</p>', 'Full', 1, 'single', 'completed', 22, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Roy Cheung","avatar":""},{"name":"Thomas Hudak","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Almen Wong Pui-Ha","avatar":""},{"name":"Samuel Pang","avatar":""},{"name":"YoYo Fong Cho-Yiu","avatar":""},{"name":"Wong Jing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
