INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('baby-tuyet-hao', 'Baby Tuyệt Hảo', 'Mighty Baby', 'https://phimimg.com/upload/vod/20231010-1/ffe8cb64d1dcd4dd5efb4923d9fe6fde.jpg', 'https://phimimg.com/upload/vod/20231010-1/8b057c4f8bd4d8e3dcbb37ac04e9c446.jpg', '<p>Sau khi thiết kế thành công chiếc áo ngực hoàn hảo, Lena, Johnny và Wayne được lệnh đưa ra kế hoạch tiếp thị cho dòng sản phẩm chăm sóc trẻ em &quot;Mighty Baby&quot;. Cuộc sống của Johnny phức tạp khi anh thuê cô thư ký kỳ quặc Sabrina. Về phần Lena và Wayne, mối quan hệ của họ bị đe dọa khi Lena phát hiện ra rằng Wayne sợ trẻ sơ sinh. Để giúp Wayne vượt qua nỗi sợ hãi, Lena thuê chuyên gia về trẻ em Boey. Thật không may cho Lena, Wayne bắt đầu nảy sinh tình cảm với Boey.</p>', 'Full', 1, 'single', 'completed', 21, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Gigi Leung","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Cherrie Ying Choi-Yi","avatar":""},{"name":"Cecilia Cheung","avatar":""},{"name":"Chikako Aoyama","avatar":""},{"name":"Cheuk Wan-Chi","avatar":""},{"name":"Kate Yeung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324532);
