INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-trai-thay-ma', 'Mắt Trái Thấy Ma', 'My Left Eye Sees Ghosts', 'https://phimimg.com/upload/vod/20231010-1/b773a808f9b6f60e077647f0f140f683.jpg', 'https://phimimg.com/upload/vod/20231010-1/cc26deb99ded4b4a69a078f83e6cbf99.jpg', '<p>Một tai nạn xe hơi đã mang đến cho một cô gái trẻ hư hỏng, rắc rối khả năng nhìn thấy ma, trong đó có hồn ma của một người bạn học cũ.</p>', 'Full', 1, 'single', 'completed', 18, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammi Cheng","avatar":""},{"name":"Lau Ching-wan","avatar":""},{"name":"Cherrie Ying Choi-Yi","avatar":""},{"name":"Lee San-San","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Bonnie Wong","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Wong Tin-lam","avatar":""},{"name":"Kelly Lin","avatar":""},{"name":"Yoyo Yiu Wing-Man","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
