INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-toi-18-tuoi', 'Vợ Tôi 18 Tuổi', 'My Wife Is 18', 'https://phimimg.com/upload/vod/20231010-1/33d24c9f1a94273b6f2aa76e3b18e11b.jpg', 'https://phimimg.com/upload/vod/20231010-1/27692f3eff30185da148ed95b350a65b.jpg', '<p>Sau khi kết thúc kỳ thi mở dành cho học sinh Lớp 5 và xin cấp chứng minh thư người lớn, Yoyo, mười tám tuổi, khởi hành đến London để gặp một chàng trai được cha mẹ tốt bụng của cô giới thiệu ở Anh. Anh chàng tên là Cheung, khoảng ba mươi tuổi. Ông nội của Yoyo và Cheung là bạn bè thời chiến. Họ thề sẽ cho những đứa con trong bụng của họ kết hôn khi chúng lớn lên. Tuy nhiên, những đứa trẻ hóa ra đều là phụ nữ. Hai người phụ nữ hiện đã là mẹ. Họ tình cờ gặp lại nhau và muốn biến điều ước của cha mình thành hiện thực, vì vậy họ sắp xếp để Yoyo và Cheung gặp nhau ở London. Yoyo và Cheung hứa sẽ kết hôn để làm hài lòng mẹ của họ. Nhưng vào ngày cưới, họ cũng ký giấy ly hôn có hiệu lực một năm sau khi kết hôn.</p>', 'Full', 1, 'single', 'completed', 17, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ekin Cheng","avatar":""},{"name":"Charlene Choi","avatar":""},{"name":"Stephanie Che","avatar":""},{"name":"Bernice Liu","avatar":""},{"name":"Patrick Tang","avatar":""},{"name":"Ronald Cheng","avatar":""},{"name":"Sandy Lam San-San","avatar":""},{"name":"May Lai Shun-Wai","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Fung Lee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
