INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-han-phuc-hoat', 'Vô Hạn Phục Hoạt', 'Second Time Around', 'https://phimimg.com/upload/vod/20231009-1/e661a823f57e3c019077ea6b25b70700.jpg', 'https://phimimg.com/upload/vod/20231009-1/dd820a8bb02abce6d96d80105daaafb2.jpg', '<p>Một chàng trai trẻ đến Las Vegas cùng người bạn thân nhất của mình với hy vọng kiếm được nhiều tiền. Sau khi mất hết số tiền đó, họ được một cô gái trẻ giúp đỡ. Cô gái kể cho chàng trai về một số viên đá đặc biệt liên quan đến việc du hành thời gian và các vũ trụ song song. Trong một tai nạn xe hơi, chàng trai và cô gái là những người sống sót duy nhất. Bị truy đuổi bởi một nữ thám tử, họ vô tình quay ngược thời gian về ngày Giáng sinh. Tại đó, chàng trai quyết định thay đổi và làm những điều đúng đắn, và cuối cùng anh ta cũng phải lòng nữ thám tử.</p>', 'Full', 1, 'single', 'completed', 19, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ekin Cheng","avatar":""},{"name":"Cecilia Cheung","avatar":""},{"name":"Ke Huy Quan","avatar":""},{"name":"Annamaria Ambera","avatar":""},{"name":"John Wang","avatar":""},{"name":"Alexander Fung","avatar":""},{"name":"Johnny Koo","avatar":""},{"name":"Lynne Langdon","avatar":""},{"name":"Glen Pon","avatar":""},{"name":"David Quan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
