INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nam-vo-nu', 'Thiện Nam Võ Nữ', 'Dry Wood, Fierce Fire', 'https://phimimg.com/upload/vod/20231009-1/0660e95b8278b86b0fe7a8cbf6119d0a.jpg', 'https://phimimg.com/upload/vod/20231009-1/4f8880ebc205b163359aa4336314d907.jpg', '<p>Một bác sĩ/nhà thảo dược học Trung Quốc có khả năng kỳ lạ là có thể nhận ra vấn đề chỉ bằng cách chạm nhẹ vào mạch và nhìn vào lưỡi. Bộ phim hài lãng mạn nhỏ về một người như vậy có thể được hưởng lợi từ một kỳ thi như vậy.</p>', 'Full', 1, 'single', 'completed', 29, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Miriam Yeung","avatar":""},{"name":"Flora Chan","avatar":""},{"name":"Wyman Wong Wai-Man","avatar":""},{"name":"Sharon Chan Man-Chi","avatar":""},{"name":"Lo Meng","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Matt Chow Hoi-Kwong","avatar":""},{"name":"Nelson Cheung Hok-Yun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324532);
