INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-thanh-dam', 'Trò Chơi Thanh Đạm', 'Frugal Game', 'https://phimimg.com/upload/vod/20231008-1/13d97f5af01e881963a8dbd753fc25f5.jpg', 'https://phimimg.com/upload/vod/20231008-1/476dd9e9575f238d29fbabc344bd4a6c.jpg', '<p>Diana và Wai đã trở nên gánh nặng nợ nần và trong kế hoạch kiếm tiền nhanh chóng, họ đã thành lập một &quot;gia đình&quot; giả để tham gia một chương trình truyền hình thực tế. Gia đình họ phải đọ sức với một gia đình khác và họ phải cạnh tranh để xem ai có thể sống nhờ số tiền nhỏ nhất. Nhưng khi trò chơi gần kết thúc, nhà sản xuất chương trình buộc đạo diễn phải thực hiện một số thay đổi để tăng xếp hạng, điều này có thể vô tình vạch trần hành vi gian lận của Diana và Wai.</p>', 'Full', 1, 'single', 'completed', 21, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Eason Chan","avatar":""},{"name":"Carol Cheng","avatar":""},{"name":"Miriam Yeung","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""},{"name":"Conroy Chan","avatar":""},{"name":"Yiu Tak-Shing","avatar":""},{"name":"Woo Ying-Man","avatar":""},{"name":"Chan Man-Lei","avatar":""},{"name":"Benny Li Shun-Yan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324532);
