INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-phong-ma', 'Văn Phòng Ma', 'Ghost Office', 'https://phimimg.com/upload/vod/20231008-1/53565f7601c1f25cb98734296a885f6b.jpg', 'https://phimimg.com/upload/vod/20231008-1/9c1d54ce4dbbe8d17be6e9d4adc984cd.jpg', '<p>Tuyển tập ba truyện ngắn về các hoạt động siêu nhiên tại nơi làm việc.</p>', 'Full', 1, 'single', 'completed', 20, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Stephanie Lam","avatar":""},{"name":"Kenny Lam","avatar":""},{"name":"Woody Chan","avatar":""},{"name":"Matt Chow Hoi-Kwong","avatar":""},{"name":"Crystal Suen Ah-Lei","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"JoJo Shum","avatar":""},{"name":"Mango Wong","avatar":""},{"name":"Samantha Teoh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324532);
