INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-yeu-thuong', 'Hành Tinh Yêu Thương', 'Tiramisu', 'null', 'https://phimimg.com/upload/vod/20231008-1/69fcf9a356bc23d64b80ec8cb15922d2.jpg', '<p>Là câu chuyện về một người đàn ông tên Fung, ở độ tuổi đôi mươi, sống cuộc đời làm người đưa thư vào ban ngày và người gác cổng vào ban đêm. Một ngày nọ, nhờ số mệnh và định mệnh, anh gặp được một cô gái xinh đẹp, Jane, trên một chuyến tàu điện ngầm khi đang giao một gói hàng. Kể từ giây phút này cuộc đời anh sẽ thay đổi mãi mãi.</p>', 'Full', 1, 'single', 'completed', 22, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Karena Lam","avatar":""},{"name":"Eason Chan","avatar":""},{"name":"Candy Lo","avatar":""},{"name":"Vincent Kok","avatar":""},{"name":"Nicholas Tse","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324532);
