INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-phong-ma-am', 'Văn Phòng Ma Ám', 'Haunted Office', 'https://phimimg.com/upload/vod/20231008-1/eeeb87dbf6b8a4d410df51a94725e9a2.jpg', 'https://phimimg.com/upload/vod/20231008-1/f7747e787840a9871d9b02d381f2e04a.jpg', '<p>Các nhân viên làm việc tại một tòa nhà cao tầng bắt đầu gặp phải hàng loạt sự việc kỳ lạ. Ken, một người mới được thuê đã thu hút Shan đáng yêu nhưng bị quấy rối về mặt tinh thần. Trong khi đó, Pat dường như đang bị khủng bố bởi con quỷ độc ác trú ngụ trong gian hàng cuối cùng trong phòng tắm dành cho người phụ nữ. Và Richard, một ông chủ xấu tính của một công ty khác trong cùng tòa nhà, muốn loại bỏ nhân viên lâu năm Mary của mình và bắt đầu nghi ngờ rằng toàn bộ nhân viên của mình đã trở thành ma.</p>', 'Full', 1, 'single', 'completed', 20, 2002, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Shu Qi","avatar":""},{"name":"Jordan Chan","avatar":""},{"name":"Stephen Fung","avatar":""},{"name":"Karen Mok","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Elena Kong Mei-Yee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324532);
