INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('van-phong-ma-am', 'Văn Phòng Ma Ám', 'Haunted Office', 'văn phòng ma ám haunted office shu qi jordan chan stephen fung karen mok kingdom yuen helena law lan elena kong mei-yee ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kham-pha-cuoc-song', 'Khám Phá Cuộc Sống', 'On the Occasion of Remembering the Turning Gate', 'https://phimimg.com/upload/vod/20230926-1/44fa0c91f5d2d8b6a52ee4b52b134cff.jpg', 'https://phimimg.com/upload/vod/20230926-1/516f63d30365a5211daf59cb656bbbbf.jpg', '<p>Nam diễn viên Gyung-soo bị bỏ rơi và quyết định rời Seoul để thăm một người bạn. Bạn của anh ấy nói với anh ấy rằng truyền thuyết Cổng Xoay báo trước những sự kiện trong tương lai. Trong chuyến thăm của mình, Gyung-soo gặp Myung-sook, người nhanh chóng phải lòng anh. Sau một đêm đam mê, anh lên tàu trở về Seoul và gặp một người phụ nữ đã có gia đình, người này tuyên bố biết anh. Gyung-soo nghĩ có thể anh yêu cô nhưng có lẽ anh đã chọn nhầm người phụ nữ.</p>', 'Full', 1, 'single', 'completed', 21, 2002, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Sang-kyung","avatar":""},{"name":"Chu Sang-mi","avatar":""},{"name":"Ye Ji Won","avatar":""},{"name":"Kim Hak-sun","avatar":""},{"name":"Ahn Kil-kang","avatar":""},{"name":"Kim Choo-wol","avatar":""},{"name":"George Georgiou","avatar":""},{"name":"Jun Guk-hyang","avatar":""},{"name":"Shin Hyun-jong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324532);
