INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-so-hai-tot-cung', 'Nỗi Sợ Hãi Tột Cùng', 'The Sum of All Fears', 'https://phimimg.com/upload/vod/20230917-1/1d9315184e6ed9f5c10259252805b71a.jpg', 'https://phimimg.com/upload/vod/20230917-1/942daab342939fd4bebe420339f4139c.jpg', '<p><span style="font-family: ">Tổng thống Nga đột ngột qua đời và một nhân vật có lai lịch chính trị bí ẩn lên nắm quyọn điều hành đất nước. Sự thay đổi đó gây nên chứng hoang tưởng trong giới quan chức Cục Tình báo trung ương Mỹ (CIA). Vì vậy, giám đốc CIA Bill Cabot tuyển dụng nhà phân tích trẻ Jack Ryan để đánh giá và tìm giải pháp. Đúng lúc đó, điều không ai ngề xảy ra: một trái bom nguyên tử phát nổ trên đất Mỹ và Washington lập tức quy trách nhiệm cho người Nga. Ryan sẽ phải vận dụng hết năng lực của mình để tìm ra sự thật, tránh để thế giới lâm vào cuộc chiến mới...</span></p>', 'Full', 1, 'single', 'completed', 28, 2002, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Liev Schreiber","avatar":""},{"name":"Bridget Moynahan","avatar":""},{"name":"Alan Bates","avatar":""},{"name":"Ciarán Hinds","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Ron Rifkin","avatar":""},{"name":"Bruce McGill","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324532);
