INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-bong-thieu-lam', 'Đội Bóng Thiếu Lâm', 'Shaolin Soccer', 'https://phimimg.com/uploads/movies/20260713/doi-bong-thieu-lam-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/doi-bong-thieu-lam-poster.webp', '<p>Vì bán rẻ tài năng mà Thiết Cước, cầu thủ danh tiếng một thời, trở thành lão huấn luyện viên nát rượu. Ông gặp Tinh, chàng võ sư muốn truyền bá kungfu ra toàn thế giới. Cả hai bắt tay lập đội bóng và kêu gọi các huynh đệ Thiếu lâm xưa gia nhập. Đội bóng kỳ lạ bắt đầu gia nhập làng túc cầu.</p>', 'Full', 1, 'single', 'completed', 43, 2001, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Vicky Zhao Wei","avatar":""},{"name":"Patrick Tse Yin","avatar":""},{"name":"Karen Mok Man-Wai","avatar":""},{"name":"Wong Yat-Fei","avatar":""},{"name":"Mo Meilin","avatar":""},{"name":"Tenky Tin Kai-Man","avatar":""},{"name":"Danny Chan Kwok-Kwan","avatar":""},{"name":"Lam Tze-Chung","avatar":""},{"name":"Vincent Kok Tak-Chiu","avatar":""},{"name":"Steven Fung Min-Hang","avatar":""},{"name":"Jazz Lam Tsz-Sin","avatar":""},{"name":"Yuen Siu-Lung","avatar":""},{"name":"Wong Ming-Kin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Siu Lam juk kau","Futbol Kung Fu","Atsalini klotsia","Shao Lin zu qiu","Üsd, vágd, focizzál!","Shaolin Soccer - Arbitri, rigori e filosofia zen","Kung Fu Soccer","Futbol z Shaolin","O Ás da Bola","Shaolin Soccer","Shaolin gola","少林サッカー","少林足球"]', 1784690324532);
