INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ke', 'Chuyện Kể', 'Storytelling', 'https://phimimg.com/upload/vod/20260706-1/2b5df0c4fa7bcdd09c75c4d4b0fc1ae2.jpg', 'https://phimimg.com/upload/vod/20260706-1/fe5c2ea3dd86663747245e7bf0e5a15f.jpg', '<p>Phim gồm hai phần độc lập: &quot;Fiction&quot; kể về Vi, một sinh viên đại học có mối quan hệ phức tạp với bạn trai khuyết tật và giáo sư da màu, cô viết một truyện ngắn dựa trên trải nghiệm tình dục gây tranh cãi với giáo sư, khiến lớp học phản ứng dữ dội; &quot;Non-Fiction&quot; theo chân Toby, một nhà làm phim tài liệu nghiệp dư, ghi hình cuộc sống của Scooby – một học sinh trung học bất mãn, sống trong gia đình rối loạn, với ước mơ trở thành người nổi tiếng, qua đó phản ánh sự giả tạo trong truyền thông và xung đột thế hệ.</p>', 'Full', 1, 'single', 'completed', 58, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Selma Blair","avatar":""},{"name":"Leo Fitzpatrick","avatar":""},{"name":"Robert Wisdom","avatar":""},{"name":"Aleksa Palladino","avatar":""},{"name":"Mark Webber","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Jonathan Osser","avatar":""},{"name":"Lupe Ontiveros","avatar":""},{"name":"Julie Hagerty","avatar":""},{"name":"Noah Fleiss","avatar":""},{"name":"Maria Thayer","avatar":""},{"name":"Angela Goethals","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Devorah Rose","avatar":""},{"name":"Nancy Anne Ridder","avatar":""},{"name":"Steve Ros","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cosas que no se olvidan","Untitled Todd Solondz Project","Storytelling"]', 1784690324532);
