INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-am-anh-tam-linh', 'Nỗi Ám Ảnh Tâm Linh', 'Pulse', 'https://phimimg.com/upload/vod/20260606-1/8d8391ae184977ea1f7a829b234ba9ff.jpg', 'https://phimimg.com/upload/vod/20260606-1/c3dfde20da4f9347ffab8300403e6b1e.jpg', '<p>Chuyện phim gồm hai mạch phim song hành. &nbsp;Bộ phim kinh dị chứa đựng ý nghĩa ẩn dụ về sự đơn độc của con người, dẫn tới những cơn trầm cảm và ý nghĩ tuyệt vọng, một điều đang ngày càng được quan tâm hơn trong đời sống xã hội Nhật Bản.Đây là câu chuyện về sự cô đơn và cô lập của con người trong xã hội hiện đại vốn bị tha hoá bởi công nghệ và chủ nghĩa tiêu thụ. Kairo (Pulse) là một bộ phim mang màu sắc ảm đạm và u tối. Câu hỏi mà bộ phim đặt ra là liệu khoa học kỹ thuật có thể rút ngắn khoảng cách giữa hai thế giới âm và dương, kết nối người sống và người chết với nhau không.</p>', 'Full', 1, 'single', 'completed', 24, 2001, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kumiko Aso","avatar":""},{"name":"Haruhiko Kato","avatar":""},{"name":"Koyuki","avatar":""},{"name":"Kurume Arisaka","avatar":""},{"name":"Masatoshi Matsuo","avatar":""},{"name":"Shinji Takeda","avatar":""},{"name":"Kenji Mizuhashi","avatar":""},{"name":"Shun Sugata","avatar":""},{"name":"Ken Furusawa","avatar":""},{"name":"Teruo Ono","avatar":""},{"name":"Show Aikawa","avatar":""},{"name":"Koji Yakusho","avatar":""},{"name":"Masayuki Shionoya","avatar":""},{"name":"Kaori Ichijō","avatar":""},{"name":"Takumi Tanji","avatar":""},{"name":"Jun Fubuki","avatar":""},{"name":"Hassei Takano","avatar":""},{"name":"Atsushi Yuki","avatar":""},{"name":"G","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Kairo","Pulse","회로","Puls","Mạch","回路"]', 1784690324532);
