INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-luyen', 'Biệt Luyến', 'Stolen Love', 'https://phimimg.com/upload/vod/20260605-1/5158442d9d02061ea086664d0da18fb2.jpg', 'https://phimimg.com/upload/vod/20260605-1/07860f7b1181b6a42a320cd2c98258a5.jpg', '<p>Kể về một kiến trúc sư thành công Rick (Raymond Lam đóng vai), người phát hiện ra anh ta có thể có một quá khứ bị lãng quên. Anh ấy bị một chiếc ô tô đâm khi đang chìm đắm trong suy nghĩ về một quảng cáo có sự góp mặt của Angela Lok (Rain Li), một tiểu thuyết gia nổi tiếng. Khi tỉnh dậy, anh ấy phát hiện ra mình đã mất khả năng sáng tạo. Chỉ khi anh ấy ở gần Angela thì tia lửa mới quay trở lại. Vậy anh ta làm gì? Tất nhiên, anh ta chuyển vào tòa nhà của cô ấy.</p>', 'Full', 1, 'single', 'completed', 29, 2001, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Raymond Lam Fung","avatar":""},{"name":"Rain Lee Choi-Wah","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Margaret Chung","avatar":""},{"name":"Wyman Wong Wai-Man","avatar":""},{"name":"Wong Yat-Fei","avatar":""},{"name":"Joe Ma Wai-Ho","avatar":""},{"name":"Teresa Lee Fung","avatar":""},{"name":"Samson Yeung","avatar":""},{"name":"Soi Cheang","avatar":""},{"name":"Louis Wong Chun-Kau","avatar":""},{"name":"Simon Yu Sai-Tang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Bit luen","别恋","別戀"]', 1784690324532);
