INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-smallville-phan-1', 'Thị Trấn Smallville (Phần 1)', 'Smallville (Season 1)', 'https://phimimg.com/upload/vod/20250604-1/02a8877107a3864891027fc4365db395.jpg', 'https://phimimg.com/upload/vod/20250604-1/538931a785814702878cf416b519e720.jpg', '<p>Giữa cậu bé mà Clark Kent từng nghĩ mình là và người đàn ông mà cậu định trở thành là những câu chuyện hấp dẫn của Smallville. Loạt phim hành động nổi tiếng tái hiện lại huyền thoại Superman từ những khởi nguồn.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 20, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Welling","avatar":""},{"name":"Erica Durance","avatar":""},{"name":"Cassidy Freeman","avatar":""},{"name":"Justin Hartley","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Smallville"]', 1784690324532);
