INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-mat-thien-than', 'Cặp mắt thiên thần', 'Angel Eyes', 'https://phimimg.com/upload/vod/20260508-1/e6ccb87d5d079f7184c5eebee7b91efc.jpg', 'https://phimimg.com/upload/vod/20260508-1/ba94838923ac7f02136822129b262ab6.jpg', '<p>Sharon Pogue là nữ cảnh sát ở Chicago mang nhiều tổn thương gia đình và quá khứ đau buồn. Một đêm cô được người đàn ông bí ẩn tên Catch cứu mạng. Hai người dần nảy sinh tình cảm, nhưng Catch cũng đang che giấu một quá khứ bi kịch và danh tính thật của mình. Phim thiên về cảm xúc, chữa lành tâm lý và những con người cô độc hơn là romance kiểu ngọt ngào thông thường.</p>', 'Full', 1, 'single', 'completed', 21, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lopez","avatar":""},{"name":"Jim Caviezel","avatar":""},{"name":"Jeremy Sisto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Глаза ангела","Les yeux d''un ange","Angel Eyes"]', 1784690324532);
