INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuong-quy', 'Xương Quỷ​', 'The Devil''s Backbone', 'https://phimimg.com/upload/vod/20260504-1/513d9c4580b567955111ce5994742e35.jpg', 'https://phimimg.com/upload/vod/20260504-1/47e212337d7c6928691e6833c8da868e.jpg', '<p>Lấy bối cảnh thời gain sau cuộc nội chiến của Tây Ban Nha vào năm 1939. Carlos, con của một liệt sỹ trong chiến tranh bị người giám hộ của mình bỏ rơi tại một trại trẻ mồ côi. Sau khi Carlos đến trại trẻ mồ côi này, hồn ma của Santi, vốn cũng là một thành viên tại đây hiện về vào buổi đêm và thường thì thầm với Carlos rằng: “Rất nhiều người trong số các bạn sẽ chết. Và kỳ lạ thay, những lời tiên đoán của con ma ấy lại thành sự thật. Từ đó, nhiều chuyện ly kì, rùng rợn xảy ra.</p>', 'Full', 1, 'single', 'completed', 30, 2001, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Marisa Paredes","avatar":""},{"name":"Eduardo Noriega","avatar":""},{"name":"Federico Luppi","avatar":""},{"name":"Fernando Tielve","avatar":""},{"name":"Íñigo Garcés","avatar":""},{"name":"Irene Visedo","avatar":""},{"name":"José Manuel Lorenzo","avatar":""},{"name":"Francisco Maestre","avatar":""},{"name":"Junio Valverde","avatar":""},{"name":"Berta Ojea","avatar":""},{"name":"Adrián Lamana","avatar":""},{"name":"Daniel Esparza","avatar":""},{"name":"Miguel Ortiz","avatar":""},{"name":"Juan Carlos Vellido","avatar":""},{"name":"Javier Bódalo","avatar":""},{"name":"Víctor Elías","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Das Rückgrat de