INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-su-khong-bang-cap', 'Luật Sư Không Bằng Cấp', 'Legally Blonde', 'https://phimimg.com/upload/vod/20260502-1/f0cb752af54f0cbbf6d1099c0e07061b.jpg', 'https://phimimg.com/upload/vod/20260502-1/95eb0974790ee6182e231f9a4659bd69.jpg', '<p>Elle mong muốn trở thành vợ của Warner Huntington III, nhưng bị anh chia tay trước khi anh đi học tại Trường Luật Harvard vì cho rằng cô quá nông cạn.</p>', 'Full', 1, 'single', 'completed', 22, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Reese Witherspoon","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Selma Blair","avatar":""},{"name":"Matthew Davis","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Holland Taylor","avatar":""},{"name":"Ali Larter","avatar":""},{"name":"Jessica Cauffiel","avatar":""},{"name":"Alanna Ubach","avatar":""},{"name":"Osgood Perkins","avatar":""},{"name":"Linda Cardellini","avatar":""},{"name":"Bruce Thomas","avatar":""},{"name":"Meredith Scott Lynn","avatar":""},{"name":"Raquel Welch","avatar":""},{"name":"Samantha Lemole","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["金髮尤物","Legally Blonde 1","Pravá blondýna","Natürlich blond - Vor dem Gesetz sind alle blond!","Legally Blonde 01 Legally Blonde","금발이 너무해","Blonde et légale","Blonde et légale (1)","Legalmente Loura","キューティ・ブロンド：2001","Legally Blonde"]', 1784690324532);
