INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luat-su-khong-bang-cap', 'Luật Sư Không Bằng Cấp', 'Legally Blonde', 'luật sư không bằng cấp legally blonde reese witherspoon luke wilson selma blair matthew davis victor garber jennifer coolidge holland taylor ali larter jessica cauffiel alanna ubach osgood perkins linda cardellini bruce thomas meredith scott lynn raquel welch samantha lemole k 金髮尤物 legally blonde 1 pravá blondýna natürlich blond - vor dem gesetz sind alle blond! legally blonde 01 legally blonde 금발이 너무해 blonde et légale blonde et légale (1) legalmente loura キューティ・ブロンド：2001 legally blonde', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-ngao-giang-ho-2001', 'Tiếu Ngạo Giang Hồ', 'Laughing In The Wind', 'https://phimimg.com/upload/vod/20250621-1/6d77231a0d187979e1d2e4ca1adc389b.jpg', 'https://phimimg.com/upload/vod/20250621-1/0482018c793dcaff8b9c9a3aee497fda.jpg', '<p>Đau khổ vì bị người yêu Nhạc Linh San phụ bạc, bị đồng môn hiểu lầm và bị trục xuất khỏi sư môn, Lệnh Hồ Xung đã lang thang, phiêu bạt khắp nơi và trải qua biết bao sóng gió. Do may mắn, chàng đã được rất nhiều cao thủ võ lâm truyền thụ võ công và trở thành một trong những đệ nhất võ lâm ở Trung nguyên.

Rồi hạnh phúc cũng mỉm cười với chàng trai có tấm lòng nhân ái, luôn biết hy sinh vì người khác. Chàng đã lọt vào mắt xanh của Thánh cô Ma giáo Niệm Doanh Doanh. Bị cuốn hút bởi tính cách của Hồ Xung, Doanh Doanh sẵn sàng từ bỏ danh lợi, chấp nhận hy sinh cả tính mạng để xả thân cứu người mình yêu. Hai con người với tình yêu sâu nặng đã cùng nhau phiêu bạt khắp thế gian để hợp tấu khúc &quot;Tiếu ngạo giang hồ&quot; do hai bậc tiền nhân là Khúc Dương và Lưu Chính Phong truyền lại cho hậu thế.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 30, 2001, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Yapeng","avatar":""},{"name":"Xu Qing","avatar":""},{"name":"Li Jie","avatar":""},{"name":"Wei Zi","avatar":""},{"name":"Bayaneruul","avatar":""},{"name":"苗乙乙","avatar":""},{"name":"Chen Lifeng","avatar":""},{"name":"Lü Xiaohe","avatar":""},{"name":"Li Qinqin","avatar":""},{"name":"Zang Jinsheng","avatar":""},{"name":"Yang Kun","avatar":""},{"name":"Yu Chenghui","avatar":""},{"name":"Huang Zongluo","avatar":""},{"name":"Li Fei","avatar":""},{"name":"Sun Haiying","avatar":""},{"name":"Mao Weitao","avatar":""},{"name":"Tu Men","avatar":""},{"name":"Liu Dong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["笑傲江湖 (2001)","افسانه شجاعان","소오강호","the legendary swordsman","Tiếu Ngạo Giang Hồ (2001)","笑傲江湖"]', 1784690324532);
