INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('24-gio-chong-khung-bo-phan-1', '24 Giờ Chống Khủng Bố (Phần 1)', '24 (Season 1)', '24 giờ chống khủng bố (phần 1) 24 (season 1) kiefer sutherland mary lynn rajskub kim raver yvonne strahovski tate donovan william devane 24小时 24小时反恐部队 24 stunden 24 heures chrono بیست و چهار 24 ore トゥエンティフォー 24 horas przez 24 godziny 24 hodín 24 години двадцять чотири години twenty four 24: live another day 24', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-nhanh-qua-nguy-hiem', 'Quá Nhanh Quá Nguy Hiểm', 'The Fast and the Furious', 'https://phimimg.com/upload/vod/20260225-1/86a288d937e9d6911ad95d3571c5b411.jpg', 'https://phimimg.com/upload/vod/20260225-1/4ec284130f7214bc573d5e63379cf05d.jpg', '<p>Bộ phim mở màn với cảnh cướp xe tải khá ngoạn mục và hoàn toàn mang tính “bất khả thi” ở ngoài đời. Sau hàng loạt những vụ cướp, cánh xe tải bắt đầu gây áp lực mạnh với FBI. Bằng mọi giá, cơ quan điều tra phải ra tay ngăn chặn băng cướp nguy hiểm và táo tợn này… Brian, một cảnh sát mật đã tìm cách trà trộn vào đội của Dominic, ông hoàng tốc độ để tìm hiểu sự thật. Anh dần nhận ra rằng dòng tiền chảy qua nhóm của Dominic và Johny Trần (đối thủ của Dominic) có sự mờ ám. Cùng lúc đó, mối tình giữa Brian và Mia, em gái Dominic cũng trở nên sâu sắc... Đứng trước sự lựa chọn giữa băng nhóm Dominic và nhiệm vụ của FBI, Brian buộc phải quyết định và tìm xem giới hạn thật sự của bản thân mình là ở đâu...</p>', 'Full', 1, 'single', 'completed', 20, 2001, 'Vietsub + Thuyết Minh', 'FHD', 'Đức', 0, '[{"name":"Paul Walker","avatar":""},{"name":"Vin Diesel","avatar":""},{"name":"Michelle Rodriguez","avatar":""},{"name":"Jordana Brewster","avatar":""},{"name":"Rick Yune","avatar":""},{"name":"Chad Lindberg","avatar":""},{"name":"Johnny Strong","avatar":""},{"name":"Matt Schulze","avatar":""},{"name":"Ja Rule","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"Thom Barry","avatar":""},{"name":"Vyto Ruginis","avatar":""},{"name":"Stanton Rutledge","avatar":""},{"name":"Noel Gugliemi","avatar":""},{"name":"R.J. de Vera","avatar":""},{"name":"Beau Holden","avatar":""},{"name":"Reggie Lee","avatar":""},{"name":"David Douglas","avatar":""},{"name":"Pet","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wild Speed","The Fast and the Furious (A todo gas)","Bŭrzi i yarostni","Oi Machités ton Drómon","Форсаж","Paklene ulice","Forsazh","玩命關頭","速度与激情","Quá Nhanh Quá Nguy Hiểm","狂野時速1","The Fast and the Furious: The Original","Fast and Furious","Forsaj","F&F1 - The Fast And The Furious","Fast & Furious 1","Rápido y furioso","ഫാസ്റ്റ് ആൻഡ് ഫ്യൂരിസ്","The Fast and the Furious"]', 1784690324532);
