INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-ngo-ngao', 'Cô Nàng Ngổ Ngáo', 'My Sassy Girl', 'https://phimimg.com/upload/vod/20251023-1/71e59c568fe09da069e9d8a6f2df74ae.jpg', 'https://phimimg.com/upload/vod/20251023-1/d38b8b8903e3b3b32b2974a2f48c6d48.jpg', '<p>Trong bộ phim, nhân vật nam chính đã có cuộc gặp gỡ với một cô gái say rượu trên tàu điện và điều này đã làm thay đổi cuộc đời anh. Nội dung phim dựa trên một câu chuyện có thật được kể lại qua một chuỗi những lá thư tình viết bởi Kim Ho-sik, người khởi đầu đã gửi chúng trên Internet và sau đó chuyển thể chúng thành tiểu thuyết.</p>', 'Full', 1, 'single', 'completed', 23, 2001, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jun Ji-hyun","avatar":""},{"name":"Cha Tae-hyun","avatar":""},{"name":"Kim In-mun","avatar":""},{"name":"Song Ok-suk","avatar":""},{"name":"Han Jin-hee","avatar":""},{"name":"Hyun Sook-hee","avatar":""},{"name":"Kim Il-woo","avatar":""},{"name":"Seo Dong-won","avatar":""},{"name":"Yoo Soon-chul","avatar":""},{"name":"Park Seon-a","avatar":""},{"name":"Im Ho","avatar":""},{"name":"Lee Mu-yeong","avatar":""},{"name":"Kwak Jae-yong","avatar":""},{"name":"Yang Geum-seok","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Kim Young-jun","avatar":""},{"name":"Lee Ji-hoon","avatar":""},{"name":"Park Seung-bae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Yeopgijeogin Geunyeo","My Sassy Girl","엽기적인 그녀","猟奇的な彼女","উদ্ভট সেই মেয়েটি","Miss Unerhört"]', 1784690324532);
