INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-uop-ai-cap-2-xac-uop-tro-lai', 'Xác Ướp Ai Cập 2 (Xác Ướp Trở Lại)', 'The Mummy Returns', 'https://phimimg.com/upload/vod/20251020-1/5d95ea18877feb5f061c44900b6c9ee4.jpg', 'https://phimimg.com/upload/vod/20251020-1/760062c784b82a02ac21ef79ea80bf35.jpg', '<p>Đã 8 năm trôi qua kể từ khi Rick và Evelyn lần đầu tiên gặp nhau. Trong phần hai của loạt phim về xác ướp Ai Cập, họ đã kết hôn và có một câu con trai kháu khỉnh 8 tuổi Alex. Lần trở lại này, cả Evelyn và Alex đều gặp nguy hiểm khi cậu bé nghịch ngợm đeo vào tay chiếc vòng của Vua Bọ Cạp còn Evelyn thì phát hiện ra mình là một công chúa Ai Cập trong thế giới cổ xưa...</p>', 'Full', 1, 'single', 'completed', 23, 2001, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brendan Fraser","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"John Hannah","avatar":""},{"name":"Oded Fehr","avatar":""},{"name":"Arnold Vosloo","avatar":""},{"name":"Patricia Velásquez","avatar":""},{"name":"Freddie Boath","avatar":""},{"name":"Dwayne Johnson","avatar":""},{"name":"Alun Armstrong","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"Shaun Parkes","avatar":""},{"name":"Bruce Byron","avatar":""},{"name":"Joe Dixon","avatar":""},{"name":"Tom Fisher","avatar":""},{"name":"Aharon Ipalé","avatar":""},{"name":"Quill Roberts","avatar":""},{"name":"Donna Air","avatar":""},{"name":"Tre","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Mummy 2","O Retorno da M