INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-vien-piano', 'Giáo Viên Piano', 'The Piano Teacher', 'https://phimimg.com/upload/vod/20251015-1/dd30dae2c09973c250fd287fc5441695.jpg', 'https://phimimg.com/upload/vod/20251015-1/2dc5719d06ae68b108bbf72643441ea4.jpg', '<p>The Piano Teacher (2001) nói về mối tình giữa 1 cô giáo dạy piano bước vào giai đoạn hồi xuân và chàng học trò trẻ tuổi. Phim này đã từng đoạt ba giải thưởng lớn tại Liên hoan phim Cannes vào năm 2001, mặc cho nó là 1 bộ phim gây ra nhiều tranh cãi.</p>', 'Full', 1, 'single', 'completed', 41, 2001, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Isabelle Huppert","avatar":""},{"name":"Annie Girardot","avatar":""},{"name":"Benoît Magimel","avatar":""},{"name":"Susanne Lothar","avatar":""},{"name":"Udo Samel","avatar":""},{"name":"Anna Sigalevitch","avatar":""},{"name":"Cornelia Köndgen","avatar":""},{"name":"Thomas Weinhappel","avatar":""},{"name":"Georg Friedrich","avatar":""},{"name":"Philipp Heiss","avatar":""},{"name":"William Mang","avatar":""},{"name":"Rudolf Melichar","avatar":""},{"name":"Michael Schottenberg","avatar":""},{"name":"Gabriele Schuchter","avatar":""},{"name":"Dieter Berner","avatar":""},{"name":"Vol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["The Piano Player","The Piano Teacher","La profesora de piano","Klaveriõpetaja","Pianolärarinnan","I daskala tou pianou","Profesorka klavira","La Pianista","피아니스트","Pianisten","Die Klavierspielerin","Піаністка","Pianistka","La Pianiste"]', 1784690324532);
