INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-hi-man-ba', 'Thiên Hi Mạn Ba', 'Millennium Mambo', 'https://phimimg.com/upload/vod/20251013-1/9698b34ce5d22a2453e201d2212bd263.jpg', 'https://phimimg.com/upload/vod/20251013-1/a2e5080ecd6940ee5b73accc646f6dea.jpg', '<p>Nhân vật chính, Vicky, do nữ diễn viên Thư Kỳ thể hiện, lấy bối cảnh từ năm 2011 kể lại về cuộc đời của Vicky 10 năm về trước đó. Cô ấy mô tả tuổi trẻ của mình với câu chuyện về cuộc đời thay đổi của cô vào đầu thiên niên kỷ mới. Cô làm tiếp viên trong một quán bar thời thượng. Vicky bị vướng vào mối tình giữa hai người đàn ông, Hạo Hạo và Jack, và cuộc hành trình song song của tâm hồn và cách đối mặt tuổi trẻ thoáng qua của một cô gái.</p>', 'Full', 1, 'single', 'completed', 17, 2001, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Thư Kỳ","avatar":""},{"name":"Trương Chấn","avatar":""},{"name":"Đoan Dĩ Ninh","avatar":""},{"name":"Du Đan Phong","avatar":""},{"name":"Lý Tiểu Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qianxi Manbo","Qian xi man bo","Millenium Mambo","밀레니엄 맘보","ミレニアム・マンボ","Миллениум Мамбо","千禧曼波"]', 1784690324532);
