INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-dua-ac-liet', 'Đường Đua Ác Liệt', 'On The Track Or Off', 'https://phimimg.com/upload/vod/20251008-1/3422d9a6320975a7ab0180d5c614cbdb.jpg', 'https://phimimg.com/upload/vod/20251008-1/99264c5c21d1a2997dc50ecd5ffdbcf8.jpg', '<p>Cam Nguyên từ nhỏ đã thích các chú ngựa nên mơ ước sau này có thể trở thành huấn luyện viên ngựa. Mặc dù gặp nhiều khó khăn nhưng Nguyên luôn cố gắng đạt được lý tưởng của mình. Trong chuyện tình cảm, Nguyên lại phân vân với lựa chọn của mình. Anh có tình cảm với cả hai chị em Lục Dĩnh Đồng và Lục Dĩnh Di. Vì cha bỏ đi, còn mẹ chỉ biết chơi cổ phiếu thua lỗ mà chị em Dĩnh Di luôn bị áp lực phải kiếm tiền. Tuy không thích công việc vẽ truyện tranh, nhưng vì lo cho mẹ và em gái Lục Dĩnh Ân ăn học mà Di vẫn tiếp tục làm việc. Thậm chí, Di hy sinh tình yêu, nhường Cam Nguyên cho chị. Trong khi đó, nữ phóng viên Dĩnh Đồng luôn bất chấp thủ đoạn để đạt được mục đích. Sau khi bạn trai là Từ Diệu Đông qua đời thì Đồng bất chấp quen Cam Nguyên.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 14, 2001, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Steven Ma Chun-Wai","avatar":""},{"name":"Ada Choi Siu-Fan","avatar":""},{"name":"Bonnie Chiu Hok-Yee","avatar":""},{"name":"Frankie Lam","avatar":""},{"name":"Shek Sau","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Wilson Ai Wai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["On The Track Or Off","勇往直前"]', 1784690324532);
