INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-hiep-si', 'Huyền Thoại Hiệp Sĩ', 'A Knight''s Tale', 'https://phimimg.com/upload/vod/20251008-1/0f1b30ddc2990451351bc6e5bca09fb3.jpg', 'https://phimimg.com/upload/vod/20251008-1/0a8f7ee9eaf465e29092303223c3fb47.jpg', '<p>Cái chết bất ngờ của chủ, một hiệp sĩ tài ba, đã khiến chàng thanh niên William trở thành hiệp sĩ bất đắc dĩ. Đó là bước ngoặt trong cuộc đời anh nông dân nghèo, biến cố khởi đầu cho một sự nghiệp lẫy lừng khắp châu Âu thời trung cổ. Bộ phim lấy bối cảnh châu Âu những năm cuối thế kỷ 14. William Thatcher (Heath Ledger) được sinh ra trong một gia đình nông dân nghèo ở London. Cậu được cha cho làm người hầu cận của hiệp sĩ Ector, một trong những tay kiếm hàng đầu tại nước Anh. Do thường xuyên đi theo chủ tới những trận đấu thương trên lưng ngựa - một trò tiêu khiển của giới hiệp sĩ quý tộc - nên ước mơ lớn nhất của cậu là trở thành hiệp sĩ. Ector hiểu được nguyện vọng của William và đầu tư nhiều thời gian dạy ...</p>', 'Full', 1, 'single', 'completed', 17, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Heath Ledger","avatar":""},{"name":"Rufus Sewell","avatar":""},{"name":"Shannyn Sossamon","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Laura Fraser","avatar":""},{"name":"Mark Addy","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Bérénice Bejo","avatar":""},{"name":"Scott Handy","avatar":""},{"name":"James Purefoy","avatar":""},{"name":"Leagh Conwell","avatar":""},{"name":"Christopher Cazenove","avatar":""},{"name":"Steven O''Donnell","avatar":""},{"name":"Jonathan Slinger","avatar":""},{"name":"Nick Brimble","avatar":""},{"name":"Karel Dobrý","avatar":""},{"name":"Philip Len","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Knight''s Tale","騎士風雲錄","Corazón de caballero","O thrylos enos ippoti","Rock You!","Priča o vitezu","Kato ritsarite","Istoriya rytsarya","Istoriya lytsarya","Chevalier","ロック・ユー!","A Knight''s Tale"]', 1784690324532);
