INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyen-thoai-hiep-si', 'Huyền Thoại Hiệp Sĩ', 'A Knight''s Tale', 'huyền thoại hiệp sĩ a knight''s tale heath ledger rufus sewell shannyn sossamon paul bettany laura fraser mark addy alan tudyk bérénice bejo scott handy james purefoy leagh conwell christopher cazenove steven o''donnell jonathan slinger nick brimble karel dobrý philip len knight''s tale 騎士風雲錄 corazón de caballero o thrylos enos ippoti rock you! priča o vitezu kato ritsarite istoriya rytsarya istoriya lytsarya chevalier ロック・ユー! a knight''s tale', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-thuat-phan-4', 'Phép Thuật (Phần 4)', 'Charmed (Season 4)', 'https://phimimg.com/upload/vod/20250915-1/014a09f0b2d0a260bd49cfc347c006d5.jpg', 'https://phimimg.com/upload/vod/20250915-1/f5b018dd40830dead5dfb3ff185f086f.jpg', '<p>Charmed (Phép Thuật) là bộ phim dài tập của Mỹ gồm 8 phần kể về những chị em gái nhà Halliwell. Họ là những phù thuỷ tốt có phép thuật. Mỗi chị em gái sở hũu một phép thuật khác nhau với những quyền năng và sức mạnh khác nhau. Và phép thuật của họ mạnh mẽ hơn cả khi họ kết hợp với nhau, tạo thành “Bộ ba phép thuật” quyền năng và mạnh mẽ. Họ với phép thuật của mình chống lại những thế lực hắc ám, chiến đấu, chống lại lũ quỷ và bè lũ thợ săn phù thủy. Với “Cuốn sách của bóng tối” làm bạn, làm “người dẫn đường”, họ đã từng bước trưởng thành trong cuộc sống. Sức mạnh của họ ngày càng phát triển, và chính vì thế, những mối nguy hiểm đối với họ ngày càng gia tăng. Họ - những chị em gái nhà Halliwell – luôn kiên cường, mạnh mẽ chống lại cái ác, bảo vệ người vô tội. Mỗi tập phim kể về một câu chuyện nhỏ trong cuộc sống của ba chị em, xen vào đó là những yếu tố hài hước và chân thực trong cuộc sống thường ngày.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 21, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Holly Marie Combs","avatar":""},{"name":"Alyssa Milano","avatar":""},{"name":"Rose McGowan","avatar":""},{"name":"Brian Krause","avatar":""},{"name":"Kaley Cuoco","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Charmed: Jovens Bruxas","Oi magisses","Η Μαγευτικές","チャームド 魔女3姉妹","チャームド〜魔女3姉妹〜","Hechiceras","Чародійки","Зачаровані","Всі жінки відьми","Усі жінки відьми","Charmed"]', 1784690324532);
