INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phep-thuat-phan-4', 'Phép Thuật (Phần 4)', 'Charmed (Season 4)', 'phép thuật (phần 4) charmed (season 4) holly marie combs alyssa milano rose mcgowan brian krause kaley cuoco charmed: jovens bruxas oi magisses η μαγευτικές チャームド 魔女3姉妹 チャームド〜魔女3姉妹〜 hechiceras чародійки зачаровані всі жінки відьми усі жінки відьми charmed', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-doc-ton', 'Kẻ Độc Tôn', 'The One', 'https://phimimg.com/upload/vod/20250723-1/c8502af79a69d72d8c10a080a36d0e47.jpg', 'https://phimimg.com/upload/vod/20250723-1/816bd011ce9ac358767b9bef6e06e4f4.jpg', '<p>Gabriel Yulaw là cựu đặc vụ đa vũ trụ, người đã từng hạ sát phiên bản của chính mình ở một vũ trụ khác để tự vệ. Chính điều này khiến những phiên bản khác của anh ngày càng mạnh hơn. Khi Yulaw phát hiện ra điều này, anh đã sát hại 122 phiên bản khác nhau của chính mình trong vòng 2 năm. Nhưng anh không dừng lại ở đó. Anh tiếp tục tìm kiếm các phiên bản khác để thủ tiêu các phiên bản còn lại.</p>', 'Full', 1, 'single', 'completed', 16, 2001, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lý Liên Kiệt","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Delroy Lindo","avatar":""},{"name":"Jason Statham","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jet Li''s The One","Le seul","เดี่ยวมหาประลัย","救世主","平行歼灭战","最后一强","Kẻ Độc Tôn","Միակը","The One"]', 1784690324532);
