INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-may-thoi-gian-2001', 'Cỗ Máy Thời Gian', 'A Step Into The Past', 'https://phimimg.com/upload/vod/20250720-1/599795c88ff87107019ff6c364ae34bd.jpg', 'https://phimimg.com/upload/vod/20250720-1/941ed784cd3aaeb70124cd3b829892ca.jpg', '<p>Bộ phim truyền hình Hồng Kông do TVB sản xuất năm 2001 dựa trên tiểu thuyết Tầm Tần ký của nhà văn Hoàng Dịch. Phim kể về câu chuyện du hành ngược thời gian của một Lực lượng Cảnh sát Hồng Kông thế kỷ 21 trở về thời Chiến quốc của Trung Quốc cách đó 2000 năm. Tại đây anh ta đã tham gia vào nhiều sự kiện lịch sử quan trọng dẫn đến lần đầu thống nhất Trung Hoa của nhà Tần.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 14, 2001, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Giang Hoa","avatar":""},{"name":"Tuyên Huyên","avatar":""},{"name":"Quách Thiện Ni","avatar":""},{"name":"Lâm Phong","avatar":""},{"name":"Đằng Lệ Minh","avatar":""},{"name":"Trịnh Tuyết Nhi","avatar":""},{"name":"Diêu Doanh Doanh","avatar":""},{"name":"Quách Phong","avatar":""},{"name":"Hàn Mã Lợi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["寻秦记","寻秦记2001版","寻秦记（2001）","寻秦记 2001","尋秦記","Chum chun gei","A Step Into The Past","Thời đại Chiến Quốc","Cỗ Máy Thời Gian"]', 1784690324532);
