INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-may-thoi-gian-2001', 'Cỗ Máy Thời Gian', 'A Step Into The Past', 'cỗ máy thời gian a step into the past cổ thiên lạc giang hoa tuyên huyên quách thiện ni lâm phong đằng lệ minh trịnh tuyết nhi diêu doanh doanh quách phong hàn mã lợi 寻秦记 寻秦记2001版 寻秦记（2001） 寻秦记 2001 尋秦記 chum chun gei a step into the past thời đại chiến quốc cỗ máy thời gian', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-vien-ky-jura-3', 'Công Viên Kỷ Jura 3', 'Jurassic Park III', 'https://phimimg.com/upload/vod/20250717-1/29aa3cc71946fa298a5c5954c0ec3b94.jpg', 'https://phimimg.com/upload/vod/20250717-1/db5016bb45dca4771f172503f73dc8ec.jpg', '<p>Tám năm trôi qua kể từ lần cuối cùng tiến sĩ Alan Grant chạm trán với bọn khủng long, giờ đây ông hoàn toàn thoải mái với cuộc sống chẳng dính dáng gì đến đám sinh vật thời tiền sử đó. &nbsp;Nhưng không may, ông gặp khó khăn về tài chính trong quá trình làm nghiên cứu, vì thế đành phải nhận sự trợ giúp của một doanh nhân giàu có Paul Kirby. Đó là một chuyến bay tới vùng Isla Sorna hẻo lánh, nơi có cơ sở nghiên cứu thứ hai của InGen. Theo thỏa thuận này, tiến sĩ Alan sẽ có tài trợ trang trải cho những nghiên cứu của mình. &nbsp;Nhưng mục đích chính của nhà Kirby lại là nhờ một chuyên gia về khủng long tìm giúp Eric con trai mình. Cậu bé 14 tuổi đã vô tình nhảy dù xuống hòn đảo hoang vắng. Sau một tai nạn đáng tiếc, nhóm 7 người đã bị bỏ lại trên đó và tiến sĩ Alan bắt đầu hiểu ra lý do thực sự của lời mời từ Paul Kirby.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sam Neill","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Téa Leoni","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Trevor Morgan","avatar":""},{"name":"Michael Jeter","avatar":""},{"name":"John Diehl","avatar":""},{"name":"Bruce A. Young","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Taylor Nichols","avatar":""},{"name":"Mark Harelik","avatar":""},{"name":"Julio Oscar Mechoso","avatar":""},{"name":"Blake Michael Bryan","avatar":""},{"name":"Sarah Danielle Madison","avatar":""},{"name":"Linda Park","avatar":""},{"name":"Sonia Jackson","avatar":""},{"name":"Bruc","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Park iz doba jure 3","Tzourásik Park 3","侏儸紀公園3","Dzhurasik park 3","ジュラシック・パークIII","Parque Jurasico 3","Jurassic Park III","Jurassic Park 3","ジュラシック・パーク3：2001","侏罗纪公园3"]', 1784690324532);
