INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luc-luong-phan-ung-phan-3', 'Lực Lượng Phản Ứng (Phần 3)', 'Armed Reaction (Season 3)', 'lực lượng phản ứng (phần 3) armed reaction (season 3) âu dương chấn hoa quan vịnh hà đằng lệ danh ngụy tuấn kiệt chu mễ mễ 陀枪师姐 陀枪师姐2021 陀枪师姐 第5季 2021 tuo qiang shi jie 陀槍師姐 armed reaction', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-linh-hon', 'Vùng Đất Linh Hồn', 'Spirited Away', 'https://phimimg.com/upload/vod/20250716-1/3be680dcb8b627540ea2703730db511f.jpg', 'https://phimimg.com/upload/vod/20250716-1/cdd1c3fa96086f48519393cc1ad98f7e.jpg', '<p>Câu chuyện kể về cô bé bướng bỉnh Chihiro. Gia đình của Chihiro chuyển từ thành phố về quê sinh sống, và Chihiro chẳng thích thú tí nào với sự thay đổi này. &nbsp;Bố của Chihiro là một tay lái xe tệ hại và có một trí nhớ &quot;quá tồi&quot;, ông đã lái xe lạc đường đến một thành phố bị bỏ hoang, không bóng người. Bị cuốn hút bởi mùi vị thơm ngon của thức ăn, bố mẹ của Chihiro bắt đầu &quot;thưởng thức&quot;, nhưng kết quả họ bị biến thành những con heo mập. Còn thành phố không người kia, sau khi trời tối, tất cả sống dậy, những bóng ma bắt đầu xuất hiện và hoạt động. Cô bé bướng bỉnh phải làm gì để cứu bố mẹ mình và thoát khỏi đây?</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2001, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Rumi Hiiragi","avatar":""},{"name":"Miyu Irino","avatar":""},{"name":"Mari Natsuki","avatar":""},{"name":"Takashi Naito","avatar":""},{"name":"Yasuko Sawaguchi","avatar":""},{"name":"Tsunehiko Kamijô","avatar":""},{"name":"Takehiko Ono","avatar":""},{"name":"Bunta Sugawara","avatar":""},{"name":"Akio Nakamura","avatar":""},{"name":"Yumi Tamai","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Tatsuya Gashûin","avatar":""},{"name":"Yo Oizumi","avatar":""},{"name":"Ken Yasuda","avatar":""},{"name":"Koba Hayashi","avatar":""},{"name":"Shigeru Wakita","avatar":""},{"name":"Shirou Saitou","avatar":""},{"name":"Mich","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sen to Chihiro no Kamikakushi","Unesenniye prizrakami","Chihiro ilmmiid gaskkas","El viatge de Chihiro","Shahr Ashbah","千與千尋","Ruhların Qaçışı","Sen gwa Chihiro ui Haengbang Bulmyeong","Shahre Ashbah","Shahr-e Ashbah","The Spiriting Away of Sen and Chihiro","Vùng đất linh hồn","המסע המופלא","神隐少女","Ուրվականներից քշվածները","Urvakanneric Crvatsnery","센과 치히로의 행방불명","El viaje de Chihiro","Miyazaki''s Spirited Away","A Viagem de Chihiro","Le Voyage de Chihiro","มิติวิญญาณมหัศจรรย์","Унесённые призраками","千と千尋の神隠し"]', 1784690324533);
