INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vung-dat-linh-hon', 'Vùng Đất Linh Hồn', 'Spirited Away', 'vùng đất linh hồn spirited away rumi hiiragi miyu irino mari natsuki takashi naito yasuko sawaguchi tsunehiko kamijô takehiko ono bunta sugawara akio nakamura yumi tamai ryunosuke kamiki tatsuya gashûin yo oizumi ken yasuda koba hayashi shigeru wakita shirou saitou mich sen to chihiro no kamikakushi unesenniye prizrakami chihiro ilmmiid gaskkas el viatge de chihiro shahr ashbah 千與千尋 ruhların qaçışı sen gwa chihiro ui haengbang bulmyeong shahre ashbah shahr-e ashbah the spiriting away of sen and chihiro vùng đất linh hồn המסע המופלא 神隐少女 ուրվականներից քշվածները urvakanneric crvatsnery 센과 치히로의 행방불명 el viaje de chihiro miyazaki''s spirited away a viagem de chihiro le voyage de chihiro มิติวิญญาณมหัศจรรย์ унесённые призраками 千と千尋の神隠し', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('courage-chu-cho-nhut-nhat-phan-3', 'Courage: Chú Chó Nhút Nhát (Phần 3)', 'Courage the Cowardly Dog (Season 3)', 'https://phimimg.com/upload/vod/20250602-1/60e8c659b0f7ec72894760cb2afe3cb6.jpg', 'https://phimimg.com/upload/vod/20250602-1/35c77148cd581363cf49e70eaf2372eb.jpg', '<p>Chú chó Courage nhút nhát được nhận nuôi bởi bà Muriel ở vùng Nowhere cùng với chồng là Eustace. Những câu chuyện kinh dị ở vùng này sẽ được Courage mang đến cùng với những cách giải quyết đầy dũng cảm.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 24, 2001, 'Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Marty Grabstein","avatar":""},{"name":"Thea White","avatar":""},{"name":"Lionel G. Wilson","avatar":""},{"name":"Simon Prebble","avatar":""},{"name":"Billie Lou Watt","avatar":""},{"name":"Paul Schoeffler","avatar":""},{"name":"Arthur Anderson","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Coraje, el perro cobarde","Agallas, el perro cobarde","Bátor, a gyáva kutya","겁쟁이 강아지 커리지","เคอเรจ เจ้าตูบจอมขลาด","เคอเรจ เจ้าตูบจอมขี้ขลาด","Cesur Korkak Köpek","Courage the Cowardly Dog"]', 1784690324533);
