INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('courage-chu-cho-nhut-nhat-phan-3', 'Courage: Chú Chó Nhút Nhát (Phần 3)', 'Courage the Cowardly Dog (Season 3)', 'courage: chú chó nhút nhát (phần 3) courage the cowardly dog (season 3) marty grabstein thea white lionel g. wilson simon prebble billie lou watt paul schoeffler arthur anderson coraje, el perro cobarde agallas, el perro cobarde bátor, a gyáva kutya 겁쟁이 강아지 커리지 เคอเรจ เจ้าตูบจอมขลาด เคอเรจ เจ้าตูบจอมขี้ขลาด cesur korkak köpek courage the cowardly dog', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('harry-potter-va-hon-da-phu-thuy', 'Harry Potter và Hòn Đá Phù Thủy', 'Harry Potter and the Philosopher''s Stone', 'https://phimimg.com/upload/vod/20250602-1/0f3aebe145b25b985a1deece53635c99.jpg', 'https://phimimg.com/upload/vod/20250604-1/4f59b1adab4ec3e7354f1da1d4297d03.jpg', '<p>Harry Potter và Hòn Đá Phù Thủy là bộ phim đầu tiên trong series phim “Harry Potter” được xây dựng dựa trên tiểu thuyết của nhà văn J.K.Rowling. Nhân vật chính của phim, Harry Potter - một cậu bé 11 tuổi sau khi mồ côi cha mẹ đã bị gửi đến nhà dì dượng của mình, gia đình Dursley. Tuy nhiên, cậu bé bị ngược đãi và không hề biết về thân phận thực sự của mình. &nbsp;Vào sinh nhật thứ 11 của Harry, một người lai khổng lồ là Rubeus Hagrid đã đến tìm cậu bé để đưa cậu về trường Pháp Thuật Hogwarts. Lúc này, Harry mới biết được mình là phù thủy và một phần câu chuyện về cha mẹ mình, những người đã bị Voldemort giết hại. Cùng với trí thông minh và lòng dũng cảm, cậu bé đã cùng những người bạn của mình khám phá những điều bí mật nguy hiểm về thế giới của phép thuật...</p>', 'Full', 1, 'single', 'completed', 21, 2001, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Daniel Radcliffe","avatar":""},{"name":"Rupert Grint","avatar":""},{"name":"Emma Watson","avatar":""},{"name":"Richard Harris","avatar":""},{"name":"Tom Felton","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Maggie Smith","avatar":""},{"name":"Richard Griffiths","avatar":""},{"name":"Ian Hart","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"John Hurt","avatar":""},{"name":"David Bradley","avatar":""},{"name":"Matthew Lewis","avatar":""},{"name":"Sean Biggerstaff","avatar":""},{"name":"Warwick Davis","avatar":""},{"name":"Harry Melling","avatar":""},{"name":"James P","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Хари Потър и философският камък","Hari Poter i Kamen mudrosti","ہیری پوٹر اور فلسفی کا پتھر","O Chári Póter kai i Filosofikí Líthos","Hari Poter i Kamenot na mudrosta","Harri Potter i filosofsʹkyy kaminʹ","Harry Potter and the Sorcerer''s Stone","해리포터와 마법사의 돌","ハリーポッターと賢者の石","הרי פותר ואבן החכמים","Harry Potter à l''école des sorciers","Harry Potter dhe Guri Filozofal","Harry Potter ja tarkade kivi","哈利·波特与魔法石","Harry Potter en de Steen der Wijzen","Harry Potter y la Piedra Filosofal","แฮร์รี่ พอตเตอร์กับศิลาอาถรรพ์","هاري بوتر وحجر الفيلسوف","Harry Potter e a Pedra Filosofal","Harry Potter e la pietra filosofale","Հարրի Փոթերը և Փիլիսոփայական Քարը","هری پاتر و سنگ جادو","හැරී පොටර් සහ මායා ගල","Harry Potter și Piatra Filosofală","Harry Potter 1 - Sorcerer''s Stone","Harry Potter and the Philosopher''s Stone"]', 1784690324533);
