INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('harry-potter-va-hon-da-phu-thuy', 'Harry Potter và Hòn Đá Phù Thủy', 'Harry Potter and the Philosopher''s Stone', 'harry potter và hòn đá phù thủy harry potter and the philosopher''s stone daniel radcliffe rupert grint emma watson richard harris tom felton alan rickman robbie coltrane maggie smith richard griffiths ian hart fiona shaw john hurt david bradley matthew lewis sean biggerstaff warwick davis harry melling james p хари потър и философският камък hari poter i kamen mudrosti ہیری پوٹر اور فلسفی کا پتھر o chári póter kai i filosofikí líthos hari poter i kamenot na mudrosta harri potter i filosofsʹkyy kaminʹ harry potter and the sorcerer''s stone 해리포터와 마법사의 돌 ハリーポッターと賢者の石 הרי פותר ואבן החכמים harry potter à l''école des sorciers harry potter dhe guri filozofal harry potter ja tarkade kivi 哈利·波特与魔法石 harry potter en de steen der wijzen harry potter y la piedra filosofal แฮร์รี่ พอตเตอร์กับศิลาอาถรรพ์ هاري بوتر وحجر الفيلسوف harry potter e a pedra filosofal harry potter e la pietra filosofale հարրի փոթերը և փիլիսոփայական քարը هری پاتر و سنگ جادو හැරී පොටර් සහ මායා ගල harry potter și piatra filosofală harry potter 1 - sorcerer''s stone harry potter and the philosopher''s stone', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-nhung-dung-si-co-canh', 'Doraemon: Nobita và Những Dũng Sĩ Có Cánh', 'Doraemon: Nobita and the Winged Braves', 'https://phimimg.com/upload/vod/20250521-1/c13bc9759142bc85240151f21ce976ee.jpg', 'https://phimimg.com/upload/vod/20250521-1/82f0cee07b135d83c89f47ca6043f479.jpg', '<p>Sau khi xem chương trình truyền hình về loài chim và một loài được cho là có hình người được phát hiện ở Châu Phi, Nobita mơ ước có thể &nbsp;được bay bằng đôi cánh. Cậu ta tạo ra đôi cánh bằng gỗ sau khi Doraemon từ chối giúp đỡ cậu ấy , dù nhiều lần thất bại với đôi cánh tự chế của mình. Trong khi giúp Shizuka lấy lại con chim hoàng yến cưng của mình, họ chứng kiến một cánh cổng mở ra trên bầu trời và một con chim hình người cưỡi máy bay lao ra. Anh ta tự giới thiệu mình là Gusuke, một người chim sống ở &quot;Birdopia&quot;. Doraemon, Nobita và Shizuka giúp Gusuke sửa chiếc máy bay của mình, và Nobita nhanh chóng trở thành bạn của cậu. Khi Gusuke trở về nhà của mình, Gian và Suneo đã bắt được anh ta và lấy máy bay của anh ta. Ba người còn lại theo họ qua cổng</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2001, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Sachiko Chijimatsu","avatar":""},{"name":"Rina Chinen","avatar":""},{"name":"Daisuke Gori","avatar":""},{"name":"Kyoko Hikami","avatar":""},{"name":"Yasunori Matsumoto","avatar":""},{"name":"Hisaya Morishige","avatar":""},{"name":"Ai Orikasa","avatar":""},{"name":"Bin Shimada","avatar":""},{"name":"Sumiko Shirakawa","avatar":""},{"name":"Ichiro Nagai","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["翼之勇者","Nobita and the Winged Braves","Doraemon en el mágico mundo de las aves","Doraemon Nobita to tsubasa no yuusha tachi","도라에몽 : 노비타와 날개의 용사들","哆啦A夢：大雄與翼之勇者","도라에몽: 진구와 날개 달린 용사들","Doraemon The Movie Nobita aur Birdopia Ka Sultan","哆啦A梦：大雄与翼之勇者","Doraemon: Nobita và Những Dũng Sĩ Có Cánh","도라에몽 : 노비타와 날개 달린 용사들","도라에몽 극장판: 진구와 날개의 용사들","のび太と翼の勇者たち"]', 1784690324533);
