INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-nhung-dung-si-co-canh', 'Doraemon: Nobita và Những Dũng Sĩ Có Cánh', 'Doraemon: Nobita and the Winged Braves', 'doraemon: nobita và những dũng sĩ có cánh doraemon: nobita and the winged braves nobuyo oyama noriko ohara michiko nomura kazuya tatekabe kaneta kimotsuki sachiko chijimatsu rina chinen daisuke gori kyoko hikami yasunori matsumoto hisaya morishige ai orikasa bin shimada sumiko shirakawa ichiro nagai 翼之勇者 nobita and the winged braves doraemon en el mágico mundo de las aves doraemon nobita to tsubasa no yuusha tachi 도라에몽 : 노비타와 날개의 용사들 哆啦a夢：大雄與翼之勇者 도라에몽: 진구와 날개 달린 용사들 doraemon the movie nobita aur birdopia ka sultan 哆啦a梦：大雄与翼之勇者 doraemon: nobita và những dũng sĩ có cánh 도라에몽 : 노비타와 날개 달린 용사들 도라에몽 극장판: 진구와 날개의 용사들 のび太と翼の勇者たち', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-hau-gay-canh', 'Diều Hâu Gãy Cánh', 'Black Hawk Down', 'https://phimimg.com/upload/vod/20250526-1/1cbf4a8b5c266d6d54c5e02d10358488.jpg', 'https://phimimg.com/upload/vod/20250526-1/bb686f492ceef3202275c349458c6ffb.jpg', '<p>&quot;Black Hawk Down&quot; dựa theo cuốn tiểu thuyết ăn khách nói về cuộc chiến ở Somali vào tháng 10 năm 1993. Do bất đồng trong việc chia sẻ quyền lực, nội chiến đã xảy ra ở đất nước vốn đã nghèo đói và bị hạn hán triền miên. Liên Hiệp quốc và các tổ chức nhân đạo vội vã vào cuộc, nhưng những chuyến hàng cứu trợ đã bị Aidid - thủ lĩnh có nhiều quyền lực nhất, đang chiếm giữ thủ đô Mogadishu - cướp đi để nuôi quân của mình. Trước tình hình đó, 20.000 lính Mỹ đã đổ bộ vào Somali nhằm khôi phục trật tự. Kế hoạch Black Hawk được triển khai với mục tiêu truy bắt thủ lĩnh Aidid.</p>', 'Full', 1, 'single', 'completed', 21, 2001, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Josh Hartnett","avatar":""},{"name":"Eric Bana","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Sam Shepard","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Tom Hardy","avatar":""},{"name":"Charlie Hofheimer","avatar":""},{"name":"Hugh Dancy","avatar":""},{"name":"Tom Guiry","avatar":""},{"name":"Brian Van Holt","avatar":""},{"name":"Steven Ford","avatar":""},{"name":"Ron Eldard","avatar":""},{"name":"Gregory Sporleder","avatar":""},{"name":"Zeljko Ivanek","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Pad crnog jastreba","Падение черного ястреба","La caída del halcón negro","Blek Khouk","Mavro geraki: I katarripsi","Chernyy yastreb","Padinnia chornoho yastruba","Helikopter w Ogniu","Чёрный ястреб","Falcão Negro em Perigo","Black Hawk derribado","ブラックホーク・ダウン：2001","黑鹰坠落","黑鷹15小時","Operațiunea Mogadishu","Black Hawk Down"]', 1784690324533);
