INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dieu-hau-gay-canh', 'Diều Hâu Gãy Cánh', 'Black Hawk Down', 'diều hâu gãy cánh black hawk down josh hartnett eric bana ewan mcgregor tom sizemore william fichtner sam shepard jason isaacs ewen bremner orlando bloom tom hardy charlie hofheimer hugh dancy tom guiry brian van holt steven ford ron eldard gregory sporleder zeljko ivanek pad crnog jastreba падение черного ястреба la caída del halcón negro blek khouk mavro geraki: i katarripsi chernyy yastreb padinnia chornoho yastruba helikopter w ogniu чёрный ястреб falcão negro em perigo black hawk derribado ブラックホーク・ダウン：2001 黑鹰坠落 黑鷹15小時 operațiunea mogadishu black hawk down', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-thoi-gian', 'Siêu Nhân Thời Gian', 'Power Rangers Time Force', 'https://phimimg.com/upload/vod/20250414-1/8df0d43e0a9666f01db8ca2a13dcdb49.jpg', 'https://phimimg.com/upload/vod/20250414-1/1354122ceabe8c5a060257b1e314ec8e.jpg', '<p>Siêu Nhân Cảnh Sát Thời Gian-Power Ranger Time Force là phiên bản thứ 9 trong loạt phim Power Rangers của hãng phim Saban,được sản xuất vào năm 2001. Power Rangers Time Force Bộ phim Siêu Nhân Cảnh Sát được lấy bối cảnh ở trong tương lai,đó là năm 3000.Và&nbsp; ở thời đại đó,nhờ vào lực lượng an ninh mang tên Time Force mà tất cả mọi người được bảo vệ khỏi người đột biến,và tên đầu cầm đầu các tên tội phạm đột biến khác chính là Ransik. Power Rangers Time Force Rồi 1 ngày nọ,sỉ quan Alex (siêu nhân đỏ) đã bắt giữ được tên Ransik,và ngay sau đó, đội trưởng Logan đã giao nhiệm vụ cho một nhóm bạn gồm có: Jen (người yêu của Alex), Lucas, Katie và Trip áp giải và tống giam tên Ransik, Tuy nhiên trên đường áp giải hắn đến nhà lao thì tên Ransik đã tẩu thoát và vượt thời gian để trở về thời đại năm 2001 (nơi mà không có các cảnh sát Time Force) với âm mưu làm độc chiếm thế giới, trước khi hắn ta trở về quá khứ thì tên Ransik đã ra tay giết chết Alex. Power Rangers Time Force Và trong lúc nguy kịch ấy,sĩ quan Alex đã trao mopher của mình và giao lại nhiệm vụ bắt tên Ransik trở lại cho sĩ quan Jen,sĩ quan Jen và những người đồng đội của cô đã lấy các mopher khác và đuổi bắt tên Ransik đến năm 2001.Ở đây, họ gặp được Wes, một người có gươn mặt giống hệt Alex,cho nên&nbsp; Wes đã cùng với nhóm của Jen trở thành các siêu nhân Time Force và bảo vệ thành phố Silver Hills trước cái ác.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 12, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324533);
