INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-ty-quai-vat', 'Công Ty Quái Vật', 'Monsters, Inc.', 'https://phimimg.com/upload/vod/20250327-1/b993434eec5c6b37fd729d336a304e31.jpg', 'https://phimimg.com/upload/vod/20250327-1/5f825b60b2a74cb431f9f0098cf90a89.jpg', '<p>Bộ phim nói về một ngôi làng chỉ toàn là Monsters sinh sống. Và trong ngôi làng đó có một xưởng sản xuất mang tên gọi là Monster, Inc. là một xưởng sản xuất điện cho cả thành phố. Còn điện thì đến từ... &quot;tiếng thét&quot; của các em bé bị các Monsters nhát ma. Và trong số những anh chàng Monsters thuộc hàng sao của hãng , chuyên thu thập nhiều điện nhất là Sulley và anh chàng một mắt bé xíu, một trợ lý đắc lực Mike... Thành phố này có cuộc sống bình thường cho đến một ngày... hai chàng gặp đối thủ của mình.... Và từ những tranh chấp đó, một cô bé con đã tình cờ lạc vào xứ sở Monster, gây nên nỗi kinh hoàng cho tất cả mọi người. Nhưng điều lý thú là cô bé này lại lạc vào tay anh chàng Monster nổi tiếng dữ dằn nhất...</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2001, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"John Goodman","avatar":""},{"name":"Billy Crystal","avatar":""},{"name":"Mary Gibbs","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"James Coburn","avatar":""},{"name":"Jennifer Tilly","avatar":""},{"name":"Bob Peterson","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"Frank Oz","avatar":""},{"name":"Daniel Gerson","avatar":""},{"name":"Steve Susskind","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Jeff Pidgeon","avatar":""},{"name":"Samuel Lord Black","avatar":""},{"name":"Jack Angel","avatar":""},{"name":"Bob Bergen","avatar":""},{"name":"Rodger Bumpass","avatar":""},{"name":"Gino Conf","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["怪兽公司","Miflatzot, ba''am","Công Ty Quái Vật","Hidden City","شركة الوحوش","Monstres et Cie","Monsters en Co","Bampoúlas A.E.","Monstres & Compagnie","Monstres et Compagnie","Talasŭmi OOD","Korporatsiya monstrov","Čudovišta iz ormara","Korporatsiya monstriv","Kollide Kompanii","מפלצות בע\"מ","Monsterbedriften","モンスターズインク","Canavarlar Şirkəti","怪獸公司","شركة المرعبين المحدودة","Monsters, Inc."]', 1784690324533);
