INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('power-rangers-timeforce-teamup-lightspeed', 'Power Rangers: TimeForce TeamUp Lightspeed', 'Power Rangers: TimeForce TeamUp Lightspeed', 'https://phimimg.com/upload/vod/20250320-1/96a7675ce263ecdc2cac05126ef7f8fb.jpg', 'https://phimimg.com/upload/vod/20250320-1/1f73a420089c285dabfa9adc76e4e99d.jpg', '<p>Khi một băng nhóm tội phạm đột biến do Ransik mạnh mẽ cầm đầu trốn thoát khỏi năm 3000 đến năm 2001, một nhóm cảnh sát từ cơ quan thực thi pháp luật Time Force truy đuổi chúng xuyên thời gian. Để hỗ trợ chúng, họ tuyển dụng một người phụ nữ thượng lưu để giúp chúng giải phóng sức mạnh và trở thành Power Rangers để ngăn chặn băng đảng của Ransik.</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Power Rangers Super Megaforce Finale: Legendary Battle","Power Rangers Super Megaforce: The Legendary Battle"]', 1784690324533);
