INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-sac-cuoc-doi', 'Hương Sắc Cuộc Đời', 'Colourful Life', 'https://phimimg.com/upload/vod/20250318-1/22faf0d0c30bb418379fcff74f816105.jpg', 'https://phimimg.com/upload/vod/20250318-1/45785e8e7002746fb5e132225e29f39a.jpg', '<p>Hương sắc cuộc đời do TVB Hong Kong sản xuất năm 2011,phim dài 20 tập.Phim Hương sắc cuộc đời nói về một gia đình làm nghề nhuộn vải và những mâu thuẫn âm ĩ trong gia đình đó.ANh em đấu đá lẫn nhau làm cho gia đình có nguy cơ bị phá sản,sự nghiệp của ông cha gầy dựng hàng chục năm sắp có nguy cơ tan biến.Nhưng lúc họ trong tình cảnh nguy kịch nhất thì họ mới hiểu ra một điều là chỉ có đoàn kết lại thì mới có thể lật ngược tình thế,gầy dựng lại sự nghiệp cho gia đình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2001, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Angelina Lo Yuen-Yan","avatar":""},{"name":"Annie Man Chung-Han","avatar":""},{"name":"Louisa So Yuk-Wah","avatar":""},{"name":"Louis Yuen Siu-Cheung","avatar":""},{"name":"Frankie Lam","avatar":""},{"name":"Mimi Chu Mai-Mai","avatar":""},{"name":"Florence Kwok Siu-Wan","avatar":""},{"name":"Myolie Wu Hang-Yee","avatar":""},{"name":"Cutie Mui Siu-Wai","avatar":""},{"name":"Ronald Cheng Chung-Kei","avatar":""},{"name":"Ellesmere Choi","avatar":""},{"name":"Gigi Wong","avatar":""},{"name":"Lo Meng","avatar":""},{"name":"May Kwong","avatar":""},{"name":"Michel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["四大娘子","Colorful Life","錦繡良緣"]', 1784690324533);
