INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-linh-ky-hieu-lam-phan-1', 'Bản Lĩnh Kỷ Hiểu Lam (Phần 1)', 'The Bronze Teeth (Season 1)', 'https://phimimg.com/upload/vod/20250311-1/c5e9e0d78536846b2a15addedbaf79a9.jpg', 'https://phimimg.com/upload/vod/20250311-1/4bc43d62b7f0eafb88b59dbb6ba1e4d1.jpg', '<p>Bộ phim dựa trên câu chuyện có thật về một đại học sĩ đời vua Càn Long, triều Thanh - Kỷ Hiểu Lam, một học sĩ ngay thẳng, tương phản với đại thần Hoà Thân tham lam. Cốt truyện tập trung xung quanh những vấn đề mà nhà Thanh phải đối đầu, cùng với những pha hài hước vô cùng thú vị giữa ba nhân vật Càn Long, Kỷ Hiểu Lam và Hòa Thân.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 19, 2001, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Quốc Lập","avatar":""},{"name":"Vương Cương","avatar":""},{"name":"Trương Thiết Lâm","avatar":""},{"name":"Viên Lập","avatar":""},{"name":"Dương Thiên Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["The Eloquent Ji Xiaolan","The Bronze Teeth","철치동아 기효람","Bản Lĩnh Kỷ Hiểu Lam","铁齿铜牙纪晓岚"]', 1784690324533);
