INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-linh-ky-hieu-lam-phan-1', 'Bản Lĩnh Kỷ Hiểu Lam (Phần 1)', 'The Bronze Teeth (Season 1)', 'bản lĩnh kỷ hiểu lam (phần 1) the bronze teeth (season 1) trương quốc lập vương cương trương thiết lâm viên lập dương thiên hoa the eloquent ji xiaolan the bronze teeth 철치동아 기효람 bản lĩnh kỷ hiểu lam 铁齿铜牙纪晓岚', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-cua-nhung-chiec-nhan-hiep-hoi-nhan-than', 'Chúa Tể Của Những Chiếc Nhẫn: Hiệp Hội Nhẫn Thần', 'The Lord of the Rings: The Fellowship of the Ring', 'https://phimimg.com/upload/vod/20250219-1/2914842d6e095080d1905a36d75a52e8.jpg', 'https://phimimg.com/upload/vod/20250219-1/5ea639097fb8d1413febf837cb924d21.jpg', '<p>Chiếc nhẫn chúa mang sức mạnh bá chủ vô tình được số phận đưa vào tay chàng hobbit trẻ tuổi Frodo. Khi thày phù thủy Gandalf phát hiện ra chiếc nhẫn này đã từng thuộc về bạo chúa Sauron, Frodo phải nhận nhiệm vụ mang nhẫn tới khe núi Hủy diệt để tiêu hủy nó. &nbsp;Không đơn độc trong hành trình gian khó, Frodo còn tiếp nhận những người đồng hành thuộc các tộc khác nhau: Legolas tộc Elf; Gimli tộc Dwarf; Aragon, Boromir và ba người bạn Hobbit trung thành...</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'FHD', 'New Zealand', 0, '[{"name":"Elijah Wood","avatar":""},{"name":"Ian McKellen","avatar":""},{"name":"Viggo Mortensen","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Ian Holm","avatar":""},{"name":"Liv Tyler","avatar":""},{"name":"Christopher Lee","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Billy Boyd","avatar":""},{"name":"Dominic Monaghan","avatar":""},{"name":"John Rhys-Davies","avatar":""},{"name":"Orlando Bloom","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Marton Csokas","avatar":""},{"name":"Craig Parker","avatar":""},{"name":"Lawrence Makoar","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Sagan om ringen: Härskarringen","Le Seigneur des Anneaux: La Communauté de l''Anneau","指环王1：护戒使者","Господар на прстените: Дружината на Прстенот","อภินิหารแหวนครองพิภพ","El señor de los anillos: La comunidad del anillo","魔戒首部曲：魔戒现身","Der Herr der Ringe - Die Gefährten","Üzüklərin Hökmdarı:Üzük Qardaşlığı","ロード・オブ・ザ・リング","LOTR1- The Fellowship of the Ring","指环王1：魔戒再现","The Lord of the Rings I: The Fellowship of the Ring","Le Seigneur des Anneaux: La Communauté de l''Anneau - version longue","Der Herr der Ringe - Die Gefaehrten","Մատանիների Տիրակալը 1","LOTR1","The Lord of the Rings I","Валадар Пярсцёнкаў: Брацтва Пярсцёнка","Yüzüklerin Efendisi: Yüzük Kardeşliği","Il Signore degli Anelli - La Compagnia dell''Anello","Sagan om ringen","The Lord of the Rings: The Fellowship of the Ring"]', 1784690324533);
