INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chua-te-cua-nhung-chiec-nhan-hiep-hoi-nhan-than', 'Chúa Tể Của Những Chiếc Nhẫn: Hiệp Hội Nhẫn Thần', 'The Lord of the Rings: The Fellowship of the Ring', 'chúa tể của những chiếc nhẫn: hiệp hội nhẫn thần the lord of the rings: the fellowship of the ring elijah wood ian mckellen viggo mortensen sean astin ian holm liv tyler christopher lee sean bean billy boyd dominic monaghan john rhys-davies orlando bloom cate blanchett hugo weaving andy serkis marton csokas craig parker lawrence makoar sagan om ringen: härskarringen le seigneur des anneaux: la communauté de l''anneau 指环王1：护戒使者 господар на прстените: дружината на прстенот อภินิหารแหวนครองพิภพ el señor de los anillos: la comunidad del anillo 魔戒首部曲：魔戒现身 der herr der ringe - die gefährten üzüklərin hökmdarı:üzük qardaşlığı ロード・オブ・ザ・リング lotr1- the fellowship of the ring 指环王1：魔戒再现 the lord of the rings i: the fellowship of the ring le seigneur des anneaux: la communauté de l''anneau - version longue der herr der ringe - die gefaehrten մատանիների տիրակալը 1 lotr1 the lord of the rings i валадар пярсцёнкаў: брацтва пярсцёнка yüzüklerin efendisi: yüzük kardeşliği il signore degli anelli - la compagnia dell''anello sagan om ringen the lord of the rings: the fellowship of the ring', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dom-dom-2001', 'Đom Đóm', 'The Firefly', 'https://phimimg.com/upload/vod/20250210-1/eccb31a5189b4eb00c947e59b868c4c1.jpg', 'https://phimimg.com/upload/vod/20250210-1/c444a143500f2cbc7437c8a41d43b62f.jpg', '<p>Biểu tượng điện ảnh Nhật Bản Ken Takakura, người đã đóng vai chính trong hơn 100 bộ phim, xuất hiện trong bộ phim đầy suy ngẫm về chiến tranh và sự tưởng niệm này. Hideji Yamaoka (Takakura) từng là một phi công cảm tử trong chiến tranh và sống sót sau khi Nhật Bản đầu hàng. Sau nhiều thập kỷ làm ngư dân ở Kumamoto, một thành phố ven biển tỉnh lẻ ở phía nam Kyushu, Yamaoka vẫn miễn cưỡng khi nhắc đến những trải nghiệm thời chiến của mình với bất kỳ ai, chứ đừng nói đến một phóng viên xâm phạm đang tìm kiếm câu chuyện đặc biệt. Sau đó, một loạt sự kiện làm Yamaoka bàng hoàng, buộc ông phải nhìn nhận lại quá khứ của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2001, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ken Takakura","avatar":""},{"name":"Yuko Tanaka","avatar":""},{"name":"Isao Natsuyagi","avatar":""},{"name":"Ryuji Harada","avatar":""},{"name":"Takami Mizuhashi","avatar":""},{"name":"Ayako Kobayashi","avatar":""},{"name":"Kiichi Nakai","avatar":""},{"name":"Hisashi Igawa","avatar":""},{"name":"Tomoko Naraoka","avatar":""},{"name":"Nenji Kobayashi","avatar":""},{"name":"Renji Ishibashi","avatar":""},{"name":"Yukiyoshi Ozawa","avatar":""},{"name":"Yûko Fueki","avatar":""},{"name":"Shigeo Kobayashi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["HOTARU","ホタル"]', 1784690324533);
