INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-nang-gilmore-phan-2', 'Những Cô Nàng Gilmore (Phần 2)', 'Gilmore Girls (Season 2)', 'https://phimimg.com/upload/vod/20250116-1/dc196a08b75aaf84086ccbd9d5ecd110.jpg', 'https://phimimg.com/upload/vod/20250116-1/2466044282b727327fa5ff7e3b885a6b.jpg', '<p>Gilmore Girls kể về cuộc sống của bà mẹ đơn thân Lorelai Gilmore ( Lauren Graham ) và cô con gái tuổi teen ham học của bà, Lorelai &quot;Rory&quot; Gilmore , sống tại thị trấn hư cấu cổ kính Stars Hollow , Connecticut.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 11, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lauren Graham","avatar":""},{"name":"Alexis Bledel","avatar":""},{"name":"Scott Patterson","avatar":""},{"name":"Melissa McCarthy","avatar":""},{"name":"Keiko Agena","avatar":""},{"name":"Yanic Truesdale","avatar":""},{"name":"Liza Weil","avatar":""},{"name":"Sean Gunn","avatar":""},{"name":"Matt Czuchry","avatar":""},{"name":"Kelly Bishop","avatar":""},{"name":"Edward Herrmann","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Gilmore Girls: Tal Mãe, Tal Filha","Gilmore Girls"]', 1784690324533);
