INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-sau-tac-dat-phan-1', 'Dưới Sáu Tấc Đất (Phần 1)', 'Six Feet Under (Season 1)', 'https://phimimg.com/upload/vod/20250116-1/afbcb298b204c8c92ff1a3b1da3fa4e4.jpg', 'https://phimimg.com/upload/vod/20250116-1/f910bf3822fad5c28a4ada5671579c79.jpg', '<p>Với gia đình Fisher, những người làm nghề mai táng, thế giới bên ngoài nhà tang lễ của họ nhiều thử thách và kém dễ đoán hơn nhiều so với cuộc sống trong gia đình. Bộ phim mang lại góc nhìn châm biếm về cuộc sống của một gia đình với nghề nghiệp đặc biệt và nhiều cá tính thú vị.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 13, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Peter Krause","avatar":""},{"name":"Michael C. Hall","avatar":""},{"name":"Frances Conroy","avatar":""},{"name":"Lauren Ambrose","avatar":""},{"name":"Freddy Rodríguez","avatar":""},{"name":"Mathew St. Patrick","avatar":""},{"name":"Rachel Griffiths","avatar":""},{"name":"Justina Machado","avatar":""},{"name":"Tina Holmes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["六尺风云","身前身后","六呎风云","Six Feet Under"]', 1784690324533);
