INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-dia-truyen-thuyet-bao-lien-dang', 'Thiên Địa Truyền Thuyết Bảo Liên Đăng', 'Lotus Lantern World Legend', 'https://phimimg.com/upload/vod/20250111-1/7ab071734b783c8b9fee93fbc9c7de2d.jpg', 'https://phimimg.com/upload/vod/20250111-1/be58e2b58c28f4c748e3c4e3fdb7adfe.jpg', '<p>Tương truyền rằng, ở giữa trời đất, có một thứ pháp khí, có thể cải biến số mệnh, vượt qua không gian, thời gian, lai hồi quá khứ vị lai. Thứ pháp lực này giấu tại Thất Trùng Thiên, Quỳnh Hoa Cung, ở trong Bảo Liên Đăng. Tam Thánh Mẫu, ngồi trên Bảo Liên Đăng hạ phàm, lợi dụng lực của Bảo Liên Đăng, mê hoặc dân chúng, khiến vô số anh hùng, cam tâm bỏ mạng, danh sỹ tự hủy cuộc đời, gây họa nhân gian…</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2001, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Jimmy Lin Chih-Ying","avatar":""},{"name":"Yu Li","avatar":""},{"name":"Roger Kwok Chun-On","avatar":""},{"name":"Shen Aojun","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Jackson Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Lotus Lantern World Legend","天地传说之宝莲灯"]', 1784690324533);
