INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuon-sao-bang-phan-1', 'Vườn Sao Băng (Phần 1)', 'Meteor Garden (Season 1)', 'https://phimimg.com/upload/vod/20250103-1/ad863a793c3509d284cd73c7e791beda.jpg', 'https://phimimg.com/upload/vod/20250103-1/9ebc71c78b5b71b3f6c518697ac86b4a.jpg', '<p><span style="text-wrap-mode: wrap;">Sam Thái là một cô gái xinh đẹp nhà nghèo, nghĩa khí. Cha mẹ của Sam Thái cố gắng dành dụm tiền cho cô vào học trong một ngôi trường thượng lưu. Sam Thái đã đụng độ với bốn học sinh nam tự xưng danh là F4. Sau cuộc khai chiến của đôi bên, nhóm F4 không chịu thua vì đây là lần đầu tiên có học sinh trong trường dám chống lại họ và kế hoạch &quot;trù dập&quot; con nhỏ &quot;khó ưa&quot; Sam Thái bắt đầu được triển khai.</span></p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 21, 2001, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Jerry Yan","avatar":""},{"name":"Barbie Hsu","avatar":""},{"name":"Vic Chou","avatar":""},{"name":"Ken Chu","avatar":""},{"name":"Vanness Wu","avatar":""},{"name":"Michelle Saram","avatar":""},{"name":"Hsu Hsiao-Shun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["Pineapple Dance Studios"]', 1784690324533);
