INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-dong-song-ly-biet', 'Tân Dòng Sông Ly Biệt', 'Romance In The Rain', 'https://phimimg.com/upload/vod/20241207-1/cb2df03171d1f6c8c4bb20ceb462e8d4.jpg', 'https://phimimg.com/upload/vod/20241207-1/cc1e49996c7fe83d7c3c0ad6cdc4fc7c.jpg', '<p>Đầu những năm 1900, tại tỉnh Dong Bei, ở Ha Er Bin, Lục Chấn Hoa, còn được mọi người gọi là Báo đen, là tổng trưởng nổi danh vào thời điểm đó. Fu Wen Pei là một cô gái bình thường xuất thân trong một gia đình trí thức. Trong một lần đang đi trên đường, cô vô tình ngã ngay trước mặt của Lục Chấn Hoa. Khoảnh khắc gặp gỡ ấy trở thành định mệnh của cuộc đời cô, Lục Chấn Hoa nhanh chóng hỏi cưới cô về làm vợ thứ 8 của ông và đám cưới được tổ chức ngay ngày hôm sau. Một năm sau, Lục Chấn Hoa gặp một người con gái khác tên là Wang Xue Qin, cô cũng lập tức được rước về nhà trở thành vợ thứ 9 và là người vợ cuối cùng…</p>', 'Hoàn Tất (49/49)', 49, 'series', 'completed', 17, 2001, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Vy","avatar":""},{"name":"Lâm Tâm Như","avatar":""},{"name":"Tô Hữu Bằng","avatar":""},{"name":"Cổ Cự Cơ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
