INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-sopranos-phan-3', 'Gia Đình Sopranos (Phần 3)', 'The Sopranos (Season 3)', 'https://phimimg.com/upload/vod/20240109-1/633f901e59be17d7d819145ddf30f8d1.jpg', 'https://phimimg.com/upload/vod/20240109-1/57ce4823ba74e22f79d1d406d0f7e88b.jpg', '<p>Trong phần ba, cuộc nghe lén liên bang bắt đầu và Meadow vào đại học. Tony phải đối mặt với những thách thức từ một số người mới khó tính, chẳng hạn như Ralph Cifaretto nóng tính, trùm tội phạm New York Johnny Sack và một nữ nhân viên bán xe hơi gợi cảm.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Gandolfini","avatar":""},{"name":"Edie Falco","avatar":""},{"name":"Jamie-Lynn Sigler","avatar":""},{"name":"Robert Iler","avatar":""},{"name":"Lorraine Bracco","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Steven Van Zandt","avatar":""},{"name":"Tony Sirico","avatar":""},{"name":"Dominic Chianese","avatar":""},{"name":"Aida Turturro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
