INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-sopranos-phan-3', 'Gia Đình Sopranos (Phần 3)', 'The Sopranos (Season 3)', 'gia đình sopranos (phần 3) the sopranos (season 3) james gandolfini edie falco jamie-lynn sigler robert iler lorraine bracco michael imperioli steven van zandt tony sirico dominic chianese aida turturro ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-xam', 'Vùng Xám', 'The Grey Zone', 'https://phimimg.com/upload/vod/20241031-1/3de4390f99ac4e9b8cbd93467fbe05dc.jpg', 'https://phimimg.com/upload/vod/20241031-1/656353cf7e76b9ac870ee23ef11051c4.jpg', '<p>Câu chuyện có thật về Tiến sĩ Miklos Nyiszli, một người Do Thái gốc Hungary được Josef Mengele chọn làm trưởng khoa nghiên cứu bệnh học tại Auschwitz. Nyiszli là một trong những Sonderkommandos của Auschwitz - Biệt đội đặc biệt gồm các tù nhân Do Thái bị Đức Quốc xã bị đặt vào tình thế tiến thoái lưỡng nan về mặt đạo đức khi phải giúp chúng tiêu diệt đồng bào Do Thái để đổi lấy thêm vài tháng sống. Sonderkommandos cùng nhau đấu tranh,tổ chức cuộc nổi dậy vũ trang duy nhất từng diễn ra tại Auschwitz. Khi cuộc nổi dậy sắp bắt đầu, một nhóm trong đơn vị có kẻ phát hiện ra một cô bé 14 tuổi đã sống sót một cách thần kỳ sau vụ xả khí. Là chất xúc tác cho nỗ lực cứu chuộc cá nhân tuyệt vọng của họ, những người tù nhân bị ám ảnh bởi việc cứu đứa trẻ này, ngay cả khi làm như vậy gây nguy hiểm cho cuộc nổi dậy có thể cứu hàng ngàn người. Vậy phải làm sao để cứu mạng sống của chính mình,sẽ hy sinh những gì để cứu mạng sống của người khác?</p>', 'Full', 1, 'single', 'completed', 8, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Arquette","avatar":""},{"name":"Velizar Binev","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Daniel Benzali","avatar":""},{"name":"Allan Corduner","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Natasha Lyonne","avatar":""},{"name":"Mira Sorvino","avatar":""},{"name":"Brían F. O''Byrne","avatar":""},{"name":"Valentin Ganev","avatar":""},{"name":"Velimir Velev","avatar":""},{"name":"David Chandler","avatar":""},{"name":"George Zlatarev","avatar":""},{"name":"Henry Stram","avatar":""},{"name":"Lisa Benavide","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["The Grey Zone"]', 1784690324533);
