INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cuoc-phieu-luu-moi-cua-lucky-luke', 'Những Cuộc Phiêu Lưu Mới Của Lucky Luke', 'The New Adventures Of Lucky Luke', 'https://phimimg.com/upload/vod/20240923-1/6214be927ea984cfd54c5f8033b833ee.jpg', 'https://phimimg.com/upload/vod/20240923-1/3e6ec8f9035690d88d2bc437346be10b.jpg', '<p>Những Cuộc Phiêu Lưu Mới - Lucky Luke Adventures Series là bộ phim được chuyển thể từ bộ truyện tranh cùng tên nổi tiếng, Lucky Luke là bộ phim về chàng cao bồi miền tây hoang dã với bộ trang phục áo sơ mi vàng, bên ngoài là ghi-lê đen cùng chiếc khăn quàng màu đỏ, đầu đội chiếc mũ trắng và luôn ngậm trên miệng một cọng cỏ khô, cùng khả năng bắn súng vô cùng ấn tượng “nhanh hơn cái bóng của mình”. Đồng hành cùng Luke là chú ngựa Jolly Jumper thông minh, dí dỏm, rất trung thành và chú chó Rantanplan ham ăn, lười biếng, và cực kỳ ngốc nghếch có biệt danh &quot;Chú chó ngu ngốc hơn cả cái bóng của mình&quot;.</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 20, 2001, 'Lồng Tiếng', 'FHD', 'Pháp', 0, '[{"name":"Antoine de Caunes","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Lucky Luke - Die neuen Abenteuer","Las Nuevas Aventuras de Lucky Luke","Οι νέες περιπέτειες του Λούκυ Λουκ","Yeni Maceralarıyla Red Kit","The New Adventures of Lucky Luke","Les Nouvelles Aventures de Lucky Luke"]', 1784690324533);
