INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-11-ngot-ngao', 'Tháng 11 Ngọt Ngào', 'Sweet November', 'https://phimimg.com/upload/vod/20231119-1/d7df2ab63b20452710b2c1778a68765f.jpg', 'https://phimimg.com/upload/vod/20231119-1/d3f0e9fb49918b7848d4d7f4bc34c8d9.jpg', '<p>Phim kể lại câu chuyện của Nelson, một anh chàng say mê công việc hơn bất cứ thứ gì trên đời. Cuộc đời anh chỉ thực sự thay đổi khi tình cờ gặp cô gái lập dị có nụ cười thiên sứ - Sara. Hai người tình cờ quen nhau trong cuộc thi bằng lái xe, khi Nelson phải cầu cứu cô nàng lạ mặt “gà bài” cho mình. Hậu quả là Sara bị giám khảo đuổi ra khỏi phòng thi. Không đủ điều kiện để lái xe, Sara tìm đến “ăn vạ” nhà Nelson. Cực chẳng đã, anh chàng phải chiều theo mọi trò kỳ quặc của cô, mặc dù anh là người vô cùng tham công tiếc việc...</p>', 'Full', 1, 'single', 'completed', 12, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Greg Germann","avatar":""},{"name":"Lauren Graham","avatar":""},{"name":"Michael Rosenbaum","avatar":""},{"name":"Frank Langella","avatar":""},{"name":"Robert Joy","avatar":""},{"name":"Liam Aiken","avatar":""},{"name":"Jason Kravits","avatar":""},{"name":"June Carryl","avatar":""},{"name":"Kelvin Han Yee","avatar":""},{"name":"David Fine","avatar":""},{"name":"Chuck Isen","avatar":""},{"name":"Diane Amos","avatar":""},{"name":"Ray Baker","avatar":""},{"name":"Tom Bullock","avatar":""},{"name":"Adele Proom","avatar":""},{"name":"L. Pe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324533);
