INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-ban-phan-8', 'Những Người Bạn (Phần 8)', 'Friends (Season 8)', 'https://phimimg.com/upload/vod/20240910-1/49de6d4340ff9771fa2f86f8e47dcbff.jpg', 'https://phimimg.com/upload/vod/20240910-1/3337844cafd7cdf10d8bb06ee96ac6ad.jpg', '<p>Loạt phim dõi theo những sự cố vui nhộn của 6 người bạn tuổi đôi mươi đang vật lộn với những thử thách trong công việc, cuộc sống, tình yêu tại Manhattan những năm 1990.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jennifer Aniston","avatar":""},{"name":"Courteney Cox","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Matt LeBlanc","avatar":""},{"name":"Matthew Perry","avatar":""},{"name":"David Schwimmer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
