INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-5-nhung-giay-cuoi-cung-toi-thien-duong', 'Thám Tử Lừng Danh Conan 5: Những Giây Cuối Cùng Tới Thiên Đường', 'Case Closed: Countdown to Heaven', 'https://phimimg.com/upload/vod/20231019-1/e43f65745d6cf7e92208e7273a12f8df.jpg', 'https://phimimg.com/upload/vod/20231019-1/cc5229e98bce5cc395a08f479e808f96.jpg', '<p>Haibara đã bị Tổ chức Áo đen nghe lén những cuộc điện thoại và một trong những địa điểm mà Haibara sẽ có mặt là buổi khai trương được tổ chức tại tòa tháp đôi Tokyo cao nhất Nhật Bản. Chúng quyết định đặt bom tại đây để thủ tiêu Haibara đồng thời xóa sạch dữ liệu của tập đoàn xây dựng tòa tháp. Trong khi Conan chưa tìm ra được manh mối thì tòa tháp đôi đã bị đánh bom, hàng loạt vụ nổ xảy ra, tất cả chìm trong biển lửa mù mịt. Conan, Haibara và các bạn đã bị kẹt, không còn lối thoát và có nguy cơ bị lộ thân phận. Trong giờ phút sinh tử ấy, Conan đã nghĩ ra 1 kế hoạch điên rồ để cứu sống mọi người. Sự sống của cả nhóm đặt hết hy vọng vào kế hoạch ấy…</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2001, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Yukitoshi Hori","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Isshin Chiba","avatar":""},{"name":"Sakiko Tamagawa","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324533);
