INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-ruc-chay', 'Mùa Hè Rực Cháy', 'Summer Time', 'https://phimimg.com/upload/vod/20240801-1/3ff318ad7f21e3ecf19946a95e70101c.jpg', 'https://phimimg.com/upload/vod/20230914-1/e90c0102bbf19159b8b34a419199a697.jpg', '<p>Summer Time (2001) xoay quanh nhân vật Sang-ho, một sinh viên ẩn náu trong ngôi làng nhỏ vùng nông thôn. Anh là một người biết nhìn xa trông rộng, các hành động dần táo bạo hơn. Một ngày nọ, anh ấy có cơ hội để thực hiện những tưởng tượng của mình. Một ngày nọ, nhận thấy người chồng của Hee-ran không có nhà nên anh đã cố tình tiếp cận cô, bắt chước màn dạo đầu mà anh quan sát được, nên cô tưởng anh chính là chồng mình. Lần thứ hai đến với cô, anh chạm vào cô theo một cách khác nên Hee-ran đã phát hiện ra anh. Tuy nhiên, 2 người vẫn tiếp tục quan hệ và mở ra một mối tình ngang trái.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324533);
