INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-lam-ngoai-su-huyen-thoai-vo-lam', 'Võ Lâm Ngoại Sử (Huyền Thoại Võ Lâm)', 'Mission of the Warriors', 'https://phimimg.com/upload/vod/20240611-1/0cffa7a033415d5eb96c17905d89a841.jpg', 'https://phimimg.com/upload/vod/20240611-1/d4fab1c1d471b3c2a51d9eef7f89f29b.jpg', '<p>Thời đó, trên giang hồ có 1 người tên Châu Bảo Quý, lấy vợ là Lý Mi Nương và đã sinh ra 1 đứa con gái đặt tên là Châu Thất Thất. Bọn họ sống ở Nhân Nghĩa sơn trang. Đó cũng là nơi mà 3 thiếu niên giang hồ: Thẩm Lãng, Hùng Miêu Nhi và Vương Liên Hoa quen biết nhau. Tuy trẻ tuổi, nhưng họ cũng biết fân biệt trắng đen, phải trái. Khi ấy, 1 tên ma đầu trong võ lâm là Khoái Hoạt vương đã phái thủ hạ đến Nhân Nghĩa sơn trang để đón Châu Thất Thất về, vì tưởng Châu Thất Thất là Lý Mi Nương (mẹ của thất Thất) - ái thê của mình đã qua đời 18 năm về trước. 3 người Thẩm Lãng, Hùng Miêu Nhi và Vương Liên Hoa quyết định bảo vệ Thất Thất. Sau đó, Thẩm Lãng đã cứu thoát 1 người từ tay Khoái Hoạt Vương tên là Bạch Phi Phi, Thẩm Lãng tưởng Phi Phi ko biết võ công nhưng thực sự, cô ấy rất giỏi.Sau đó,2 người yêu nhau, nhưng mẹ của Bạch Phi Phi-Bạch Tịnh ko đồng ý, nhưng trước sau như 1, tấm lòng của Thẩm Lãng với Phi Phi ko hề thay đổi...Môt câu chuyện vừa hài vừa bi, ân oán giang hồ 18 năm, làm hại 3 người phụ nữ nhưng cuối cùng lại cho ra 1 kết thúc tốt đẹp. Tất cả âu cũng là duyên phận.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 20, 2001, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Zhang Yanyan","avatar":""},{"name":"Wang Jianxin","avatar":""},{"name":"Ke Shi","avatar":""},{"name":"Huang Haibing","avatar":""},{"name":"Wang Yan","avatar":""},{"name":"Hongjia Zhu","avatar":""},{"name":"Yue Yueli","avatar":""},{"name":"Dai Chunrong","avatar":""},{"name":"Jin Zhang","avatar":""},{"name":"Hongjie Wan","avatar":""},{"name":"Cheng Si-Han","avatar":""},{"name":"Li Qian","avatar":""},{"name":"Zhuo Fan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324533);
