INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gosford-park', 'Gosford Park', 'Gosford Park', 'https://phimimg.com/upload/vod/20240628-1/746dc5018ea4d8d11d2327181a91d4ca.jpg', 'https://phimimg.com/upload/vod/20240628-1/4f150f511fcd1f1efb1531ca7d3f3474.jpg', '<p>Vào những năm 1930 tại Anh, một nhóm những người giàu có và nổi tiếng tự mãn tụ tập về một khu nghỉ dưỡng săn bắn để thư giãn cuối tuần. Nhưng khi một vụ án mạng xảy ra, tất cả mọi người đều trở thành nghi phạm.</p>', 'Full', 1, 'single', 'completed', 19, 2001, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Maggie Smith","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Camilla Rutherford","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Geraldine Somerville","avatar":""},{"name":"Tom Hollander","avatar":""},{"name":"Natasha Wightman","avatar":""},{"name":"Jeremy Northam","avatar":""},{"name":"Bob Balaban","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324533);
