INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-tieu-thu-jones', 'Nhật Ký Tiểu Thư Jones', 'Bridget Jones''s Diary', 'https://phimimg.com/upload/vod/20240227-1/4f7a06d1bee1e587d7d6b029ce780f64.jpg', 'https://phimimg.com/upload/vod/20240227-1/0405f66646b8e6cd2210ee77a9a40232.jpg', '<p>Nhật Ký Tiểu Thư Jones - Bridget Joness Diary: Phim kể về nhân vật Jones, 31 tuổi, xinh đẹp và độc thân, làm việc tại một nhà xuất bản sách tại London. Cuộc sống của nàng rất tẻ nhạt. Chưa có ai làm nàng rung động. Chán nản, Jones thích cuộc sống phòng không chỉ có rượu và thuốc. Ngay ngày đầu của tuổi 32, nàng được mẹ giới thiệu cho chàng luật sư Mark đã một lần đổ vỡ hạnh phúc. Nhưng nàng không thích cái kiểu lạnh lùng và khó gần cũng như những câu nói mà Mark phê phán về nàng như: Cô ấy vừa mập lại vừa xấu. Nàng bắt đầu viết nhật ký và hẹn hò với tất cả bạn bè đã có gia đình. Nàng viết về đàn ông, viết về tình cảm, về mọi thứ và quyết tâm tìm bằng được cho mình một ý trung nhân. Rắc rối nảy sinh khi sự quyến rũ của nàng làm mềm lòng sếp Daniel vốn có thành tích bất hảo trong việc chinh phục các cô gái và chàng luật sư có bộ mặt kém niềm nở Mark mà nàng đã gặp trước đó.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Renée Zellweger","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Hugh Grant","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
