INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-chuyen-ma-tuy', 'Vận Chuyển Ma Túy', 'Traffic', 'https://phimimg.com/upload/vod/20240220-1/90e690baeda09fbdcc2584eec1d6f1c1.jpg', 'https://phimimg.com/upload/vod/20240220-1/8c553dcfb115c855d84ca8e1007c549c.jpg', '<p>Tại Hoa kỳ, Tổng thống bổ nhiệm chánh án tối cao pháp viện tiểu bang Ohio, Robert Wakefield, vào chức vụ chủ tịch ủy ban bài trừ ma túy. Việc làm trước nhất của chánh án Robert là mở cuộc đối thoại, bắt tay hợp tác với tướng Salazar. Chủ tịch Robert rất lý tưởng, ông quyết tâm làm sạch cộng đồng, trao việc giáo dục con cái cho vợ. Cô con gái duy nhất, 16 tuổi, Caroline Wakefield là một nữ sinh ngoan, hiền, học xuất sắc với toàn điểm A là niềm hãnh diện cho hai ông bà. Và khi chính người con gái ruột thịt của mình vướng vào vòng vây của ma túy và phạm pháp, Robert Hudson Wakefield – một người luôn lên án và truy kích bọn buôn bán ma túy đến cùng và cũng là một người cha vô cùng thương con sẽ phải làm thế nào?</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Benicio Del Toro","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324533);
