INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-tri-tue-nhan-tao', 'AI – Trí Tuệ Nhân Tạo', 'A.I. Artificial Intelligence', 'https://phimimg.com/upload/vod/20240220-1/85da021b9a13d802c226cdf4a3f1b393.jpg', 'https://phimimg.com/upload/vod/20240220-1/fb1ce6de20885fc632452ccd0c1069aa.jpg', '<p>Trong tương lai không xa, mũ đá cực đã tan chảy và sự trỗi dậy của vùng biển đại dương đã nhấn chìm tất cả các thành phố ven biển trên thế giới. Rút tiền vào nội địa của các lục địa, loài người tiếp tục tiến lên, đạt đến điểm tạo ra robot thực tế (được gọi là mechas) để phục vụ họ. Một trong những công ty sản xuất Mecha xây dựng David, một đứa trẻ nhân tạo là người đầu tiên có cảm xúc thực sự, đặc biệt là một tình yêu không bao giờ kết thúc dành cho Mẹ, Monica. Monica là người phụ nữ nhận nuôi anh ta thay thế cho con trai thực sự của cô ấy, người vẫn ở Cryo-Stasis, bị mắc kẹt bởi một căn bệnh nan y. David đang sống hạnh phúc với Monica và chồng, nhưng khi con trai thực sự của họ trở về nhà sau khi chữa trị được phát hiện, cuộc sống của anh ta thay đổi đáng kể</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324533);
