INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-gian-diep', 'Trò Chơi Gián Điệp', 'Spy Game', 'https://phimimg.com/upload/vod/20240220-1/61dbef78e13c7630f20ed6406d1d48f1.jpg', 'https://phimimg.com/upload/vod/20240220-1/71df05d63643e526f0260cfeb046f3c8.jpg', '<p>Một chuyện phức tạp xuất hiện vào ngày làm việc cuối cùng của một cựu nhân viên CIA trong khi anh đang phải tổ chức một vụ giải cứu cho một chàng trai trẻ đang được chính phủ bảo vệ, người đang bị những phần tử Trung Quốc giam giữ...</p>', 'Full', 1, 'single', 'completed', 16, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Redford","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Catherine McCormack","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324533);
