INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-end-all-wars', 'To End All Wars', 'To End All Wars', 'https://phimimg.com/upload/vod/20240219-1/0596b0db8c986d7c13004b616e96cf29.jpg', 'https://phimimg.com/upload/vod/20240219-1/34bb626d8b23827da71d70c9ae2fe666.jpg', '<p>Dựa trên một câu chuyện có thật, bộ phim tập trung vào một nhóm nhỏ binh lính Đồng minh ở Miến Điện bị quân Nhật bắt giữ. Đại úy Ernest Gordon (Ciaran McMenamin), Trung úy Jim Reardon (Kiefer Sutherland) và Thiếu tá Ian Campbell (Robert Carlyle) là một trong số các sĩ quan quân đội bị giam cầm và thường xuyên bị đánh đập cũng như bị tước đoạt lương thực. Trong khi Campbell muốn nổi loạn và cố gắng trốn thoát, thì Gordon cố gắng thực hiện một cách tiếp cận nghiêm khắc hơn, một thái độ tỏ ra gây được tiếng vang một cách đáng ngạc nhiên.</p>', 'Full', 1, 'single', 'completed', 12, 2001, 'Vietsub', '360p', 'Âu Mỹ', 0, '[{"name":"Ciarán McMenamin","avatar":""},{"name":"Robert Carlyle","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Mark Strong","avatar":""},{"name":"Yugo Saso","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
