INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-den', 'Hiệp Sĩ Đen', 'Black Knight', 'https://phimimg.com/upload/vod/20240207-1/2ff4068ed261791f19022087d6dae0f8.jpg', 'https://phimimg.com/upload/vod/20240207-1/8d926f070a97bd3e47464226c45dc9e7.jpg', '<p>Jamal Walker là anh chàng làm việc ở một công viên giải trí, điều đáng tiếc là công viên này vô cùng ế ẩm vì không chịu đổi mới. Trong một lần sơ sẩy, Jamal đã bị ngã xuống con mương...vùng vẫy mãi anh chàng cũng mò được lên bờ và không hề biết rằng mình đã trở lại Anh Quốc năm 1328, thời vua Leo... Và mọi rắc rối dở khóc, dở cười bắt đầu từ đây...</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Lawrence","avatar":""},{"name":"Marsha Thomason","avatar":""},{"name":"Tom Wilkinson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324533);
