INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tien-hoa', 'Sự Tiến Hóa', 'Evolution', 'https://phimimg.com/upload/vod/20240207-1/7790029dfc25eb04e93e35b444ec12db.jpg', 'https://phimimg.com/upload/vod/20240207-1/2aff225eab11fe9940a9be7ce52d20df.jpg', '<p>Khi một thiên thạch rơi xuống trái đất hai giáo sư đại học, Tiến sĩ Ira Kane và Giáo sư Harry Phineas Block, được chỉ định công việc kiểm tra trang web. Tại trang web, họ khám phá các sinh vật không phải của hành tinh này. Chẳng mấy chốc, trang web được chính phủ tiếp quản, buộc Ira và Harry sang một bên. Khi những hình thức sống mới bắt đầu phát triển và bắt đầu ngày càng nguy hiểm, đó là hai giáo sư để cứu hành tinh.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324533);
