INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-tien-thuong-canh-cong-thien-dang', 'Thợ Săn Tiền Thưởng: Cánh Cổng Thiên Đàng', 'Cowboy Bebop: The Movie', 'https://phimimg.com/upload/vod/20240205-1/de8d5f9fde68eff193aeab9826ccd53b.jpg', 'https://phimimg.com/upload/vod/20240205-1/3aedb9e042b990fad2c29963592b8698.jpg', '<p>Đây là một phần của series anime Cowboy Bebop, với phần phim truyền hình đã được phát sóng vào năm 1998. Bối cảnh của toàn bộ series Cowboy Bebop diễn ra vào năm 2071, lúc này con người có thể di chuyển qua toàn bộ hệ Mặt Trời bằng các cổng siêu không gian an toàn, và Sao Hỏa giờ đây trở thành trung tâm văn hóa văn minh của toàn nhân loại. Cuộc sống phát triển đồng nghĩa với phân hóa giàu nghèo và sự bành trướng táo tợn của nhiều tập đoàn tội phạm, gây ảnh hưởng lên bộ máy chính quyền cũng như hệ thống cảnh sát liên hành tinh ISSP (Inter-Solar System Police), khiến việc truy bắt tội phạm gặp nhiều khó khăn. Nhiều món tiền thưởng kếch xù được hứa hẹn trao cho những ai có khả năng chế ngự được tội phạm và khủng bố. Và để đáp ứng nhu cầu xã hội, một mạng lưới những người chuyên đi lùng bắt tội phạm săn tiền thưởng tương tự như thời kỳ cuối thế kỷ 19 ở miền Viễn Tây cũng bắt đầu hình thành. Họ được gọi là các cao bồi. Bebop là tên của con tàu vũ trụ mà những cao bồi tài giỏi sống ở đó, với nhân vật trung tâm là Jet Black, chủ nhân của Bebop. Nội dung phim là một chuyến phiêu lưu chưa kể của phi hành đoàn Bebop, xảy ra giữa hai tập 22 và 23 của bộ anime. Vài ngày trước lễ Halloween năm 2071, một chuyến xe chở hàng đã bị bọn tội phạm làm nổ tung trên Đại lộ số 1, khiến một loại virus hết sức nguy hiểm bị phát tán ra ngoài, lấy đi sinh mạng của hàng trăm người. Một phần thưởng lớn được đưa ra với hi vọng tìm được kẻ đứng đằng sau những vụ tấn công nói trên để ngăn chặn những thảm họa tương tự, và phi hành đoàn Bebop vào cuộc.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2001, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kouichi Yamadera","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Aoi Tada","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324533);
