INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-gia-do-lot', 'Chuyên Gia Đồ Lót', 'La Brassiere', 'https://phimimg.com/upload/vod/20231006-1/f810f3110e57278776bb2e0bfc9e79f4.jpg', 'https://phimimg.com/upload/vod/20231006-1/d26edb16e9073c8890f35dec2b2f2b2b.jpg', '<p>Một công ty áo ngực ở Hồng Kông phá vỡ truyền thống bằng cách thuê hai người đàn ông, Johnny và Wayne, thiết kế một chiếc &quot;áo ngực tối thượng&quot; trong 3 tháng. Trưởng bộ phận thiết kế, Lena, phản đối việc tuyển dụng họ và khiến họ trông như những kẻ ngốc. Tuy nhiên, mọi thứ bắt đầu nóng lên giữa Johnny và ông chủ, Samantha, trong khi Wayne và Lena bắt đầu cảm thấy bị thu hút. Tuy nhiên, công việc tạo ra Ultimate Bra đã sẵn sàng!</p>', 'Full', 1, 'single', 'completed', 16, 2001, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Gigi Leung","avatar":""},{"name":"Lee San-San","avatar":""},{"name":"Chikako Aoyama","avatar":""},{"name":"Cheuk Wan-Chi","avatar":""},{"name":"Rosemary Vandenbroucke","avatar":""},{"name":"Crystal Tin Yue-Lai","avatar":""},{"name":"Asuka Higuchi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324533);
