INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-thu-va-chang-lang-thang-2', 'Tiểu Thư Và Chàng Lang Thang 2', 'Lady And The Tramp II: Scamp''s Adventure', 'https://phimimg.com/upload/vod/20240123-1/0d7b14fa13610e4d28eeff490887cce0.jpg', 'https://phimimg.com/upload/vod/20240123-1/411833a5deeb02107199c7c759c823bf.jpg', '<p>Phim Lady and the Tramp II: Scamps Adventure (2001) kể về gia đình nhà chó Lady và Tramp đã sinh được 4 chú chó con gồm 3 gái và 1 trai cùng sinh sống êm ấm tại nhà vợ chồng ông chủ của Lady. Nhân vật chính của phần 2 này chính là chú chó trai Scamp. Không giống với ba chị em của mình vốn thích thú với cuộc sống ổn định, Scamp giống như cha Tramp, cậu yêu thích sự tự do và mạo hiểm. Một hôm, Scamp trốn khỏi nhà, cậu sống lang thang và kết thân với những chú chó vô chủ. Buster - con chó đầu đàn ngay từ đầu đã không thích Scamp và luôn tìm mọi cách để làm khó cậu. Điều đó đã khiến cho Scamp phân vân về sự lựa chọn của mình: hoặc sống an phận hoặc bắt đầu một cuộc sống lang thang đầy những thách thức và mạo hiểm.</p>', 'Full', 1, 'single', 'completed', 13, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scott Wolf","avatar":""},{"name":"Alyssa Milano","avatar":""},{"name":"Chazz Palminteri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324533);
