INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('old-master-q-2001', 'Old Master Q 2001', 'Old Master Q 2001', 'null', 'https://phimimg.com/upload/vod/20240123-1/e95012f3b5cd569ce06e127b31ce2230.jpg', '<p>Cảnh sát Fong và bạn gái Hoa hậu Trương Quốc Vinh bị mất trí nhớ trong một vụ tai nạn xe hơi. Với sự giúp đỡ từ Laofuzi và Big Potato, họ thoát khỏi bọn xã hội đen và ở bên nhau một lần nữa.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Nicholas Tse","avatar":""},{"name":"Cecilia Cheung","avatar":""},{"name":"Michael Wai-Man Chan","avatar":""},{"name":"Wayne Lai","avatar":""},{"name":"Alfred Cheung","avatar":""},{"name":"Koon-Lan Law","avatar":""},{"name":"Emily Kwan","avatar":""},{"name":"Tats Lau","avatar":""},{"name":"Shiu Hung Hui","avatar":""},{"name":"Frankie Chi-Hung Ng","avatar":""},{"name":"Lam Tse Sin","avatar":""},{"name":"Sammuel Leung","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Mei-Yee Shut","avatar":""},{"name":"Suet Lam","avatar":""},{"name":"Wang Ze","avatar":""},{"name":"Joe Lee Yiu-","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
