INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-son-ky-hiep', 'Thục Sơn Kỳ Hiệp', 'The Legend Of Zu', 'https://phimimg.com/upload/vod/20240121-1/1f94ccf712f6da78a05c737a907e9fe9.jpg', 'https://phimimg.com/upload/vod/20240121-1/f77ee88edc53edaeba404f6351a683ac.jpg', '<p>Giữa trời và đất tồn tại dãy núi Zu, nơi sinh sống của những người bất tử của Omei, ngọn núi cao nhất của Zu, nhưng vương quốc đang gặp nguy hiểm bởi Amnesia, một kẻ bất tử phản bội muốn thống trị Zu và toàn thế giới. White Eyebrows, thủ lĩnh của Zu, kêu gọi các chiến binh chuyên nghiệp nhất của mình để đánh bại Amnesia cho đến khi tiêu diệt nó, nhưng Amnesia ẩn mình trong Blood Cavern huyền thoại và gần như thần thoại để tăng sức mạnh của mình. Trong khi người hầu của Red, Eyebrows, theo dõi sự xâm nhập của Blood Cavern, King Sky và những chiến binh khác sẽ cố gắng tìm cách tiêu diệt Amnesia bằng một thanh kiếm thần bí cổ đại và mạnh mẽ, hy vọng thoát khỏi mối đe dọa của Amnesia.</p>', 'Full', 1, 'single', 'completed', 12, 2001, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ekin Cheng","avatar":""},{"name":"Cecilia Cheung","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Sammo Kam-Bo Hung","avatar":""},{"name":"Zhang Zi Yi","avatar":""},{"name":"Jason Wu","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Kelly Lin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324533);
