INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-dien-vien-ngan-nam', 'Nữ Diễn Viên Ngàn Năm', 'Millennium Actress', 'https://phimimg.com/upload/vod/20240121-1/507f3b7f1a6d0d5457ebbd15ad746681.jpg', 'https://phimimg.com/upload/vod/20240121-1/0aa120cdd0548210dbab3a6af3223461.jpg', '<p>Một studio phim đang bị phá hủy. Người phỏng vấn truyền hình Genya Tachibana đã theo dõi ngôi sao nổi tiếng nhất của nó, Chiyoko Fujiwara, người đã ở lại kể từ khi cô rời đi khoảng 30 năm trước. Tachibana mang đến một chìa khóa cho cô, và nó khiến cô suy ngẫm về sự nghiệp của mình; Khi cô ấy kể câu chuyện, Tachibana và người quay phim đau khổ dài của anh ta được vẽ. Chìa khóa đã được trao cho cô ấy như một thiếu niên bởi một họa sĩ và cách mạng mà cô ấy đã giúp thoát khỏi cảnh sát. Cô trở thành một nữ diễn viên vì nó sẽ khiến anh ta có thể theo dõi anh ta, và cô ấy dành nhiều thập kỷ tới hành động tìm kiếm rằng tìm kiếm trong các thể loại và thời đại khác nhau.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2001, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324533);
