INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-lung-so-hai', 'Kẻ Săn Lùng Sợ Hãi', 'Jeepers Creepers', 'https://phimimg.com/upload/vod/20240109-1/2714ef7df9eb326abc0626af66d620b7.jpg', 'https://phimimg.com/upload/vod/20240109-1/5dd539150fd3250e923b338bed8c1ee8.jpg', '<p>Trên đường trở về nhà trong giờ nghỉ xuân, Darry và Patricia Jenner chứng kiến một người bí ẩn bỏ một cái gì đó xuống một đường hầm. Quyết định khám phá những gì đã bị đổ xuống đó, Darry phát hiện ra một nơi ẩn náu đáng lo ngại đầy những cơ thể đã sửa đổi. Darry và Patricia lên đường để nhận trợ giúp, không biết rằng cá nhân hiện đang biết về những người đã xuống đường hầm. Darry và Patricia sớm nhận ra rằng người theo đuổi của họ không chỉ là một người bí ẩn, mà còn kinh khủng nhiều hơn, người có nhiều cửa hàng hơn họ có thể tưởng tượng được</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324533);
