INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dont-say-a-word', 'Don''t Say A Word', 'Don''t Say A Word', 'https://phimimg.com/upload/vod/20240104-1/e7d01ca08dba782c9559b8844278e1f9.jpg', 'https://phimimg.com/upload/vod/20240104-1/c7c6e9ba97ab332a1db31a0bf2ebae6b.jpg', '<p>Một bác sĩ tâm lý nhận một cô gái bệnh nhân mới. Sáng hôm sau ông ta phát hiện ra con gái của mình đã bị bắt cóc. Và kẻ bắt cóc không tống tiền nhưng lại yêu cầu ông phải tìm cách hỏi cho được 6 con số nằm trong đầu cô gái trẻ kia.</p>', 'Full', 1, 'single', 'completed', 17, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Bean","avatar":""},{"name":"Michael Douglas","avatar":""},{"name":"Brittany Murphy","avatar":""},{"name":"Skye McCole Bartusiak","avatar":""},{"name":"Guy Torry","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324533);
