INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hannibal-ke-an-thit-nguoi', 'Hannibal: Kẻ Ăn Thịt Người', 'Hannibal', 'https://phimimg.com/upload/vod/20240104-1/14d37ffd428d7915c178f696fa002b0d.jpg', 'https://phimimg.com/upload/vod/20240104-1/e7f53ed64786ec089af71bd89d56fd45.jpg', '<p>Chương cuối cùng của Tiến sĩ Hannibal Lecter Băng giới, kẻ tàn sát kẻ giết người. Ông hiện đang ở Ý, và làm việc như một người quản lý tại một bảo tàng. Clarice Starling (Julianne Moore), F.b.i. Người đại diện mà anh ta hỗ trợ để bắt giữ một kẻ giết người hàng loạt, được đặt phụ trách một cuộc phẫu thuật, nhưng khi một trong những người đàn ông của cô ấy xì hơi, cô ấy được gọi đến Mat bởi Cục. Một quan chức cấp cao, Paul Krendler (Ray Liotta) có nó cho cô ấy. Nhưng cô ấy nhận được một sự hối hận bởi vì Mason Verger (Gary Oldman), một trong những nạn nhân của Lecter đang tìm cách quay trở lại tại Lecter cho kẻ giảng bài đã làm với anh ta, muốn sử dụng Starling để dụ dỗ anh ta. Khi Lecter gửi một ghi chú của cô, cô biết rằng anh ở Ý, vì vậy cô yêu cầu cảnh sát để mắt đến anh. Nhưng một cảnh sát tham nhũng, những người muốn nhận được phần thưởng mà verger đặt lên anh ta, nói với verger nơi anh ta, nhưng họ không có được anh ta. Sau đó, Verger quyết định đóng khung Starling, khiến Lecter trở lại Hoa Kỳ và cuộc đua để bắt đầu Lecter.</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324533);
