INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vanh-dai-trang', 'Vành Đai Trắng', 'No Man''s Land', 'https://phimimg.com/upload/vod/20240104-1/e7974e1ecd8a2618f01e15eb55ceb07d.jpg', 'https://phimimg.com/upload/vod/20240104-1/fb4c75d6501b3b8e93d9fc6b1b4efff3.jpg', '<p>No Mans Land - Ničija zemlja (Vành Đai Trắng) là một phim chiến tranh bi hài về cuộc chiến tranh Bosnia năm 1993. Đây là phim đầu tay của nhà biên kịch kiêm đạo diễn Danis Tanović, do các hãng phim của Ý, Pháp, Bỉ, Slovenia, Vương quốc Anh và Bosnia &amp; Hercegovina hợp tác sản xuất. Hai người lính bị thương, một người Bosnia (Čiki) và một người Serb (Nino) nói chuyện với nhau giữa hai chiến tuyến trong khu vành đai trắng, khi họ đấu tranh để sống còn. Hai người lính này đối mặt nhau trong chiến hào của mình, và chờ đợi đêm tối. Họ nguyền rủa và cùng tìm thấy một số điểm chung. Tình thế càng rắc rối hơn, vì có thêm một người lính Bosna khác bị thương nữa (Cera) vừa tỉnh dậy sau khi bị hôn mê. Một quả mìn do quân đội Serb chôn bên dưới anh ta, khiến anh ta không thể di chuyển đi nơi khác được...</p>', 'Full', 1, 'single', 'completed', 12, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Branko Đurić","avatar":""},{"name":"Rene Bitorajac","avatar":""},{"name":"Filip Šovagović","avatar":""},{"name":"Georges Siatidis","avatar":""},{"name":"Sacha Kremer","avatar":""},{"name":"Alain Eloy","avatar":""},{"name":"Katrin Cartlidge","avatar":""},{"name":"Serge-Henri Valcke","avatar":""},{"name":"Simon Callow","avatar":""},{"name":"Tanja Ribič","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
