INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-tai-giang-ho', 'Long Tại Giang Hồ', 'A True Mob Story', 'https://phimimg.com/upload/vod/20240103-1/8332a6cfc32f7e1207878fbd4737ac8e.jpg', 'https://phimimg.com/upload/vod/20240103-1/c63b477c7e6afa816797bdc951b66947.jpg', '<p>A True Mob Story là bộ phim hành động nổi tiếng của Lưu Đức Hoa. Nội dung phim xoay quanh cuộc sống của một tên du đãng luôn muốn trở thành thủ lĩnh. Trong một cuộc hỗn chiến giữa hai ông chủ có thế lực nhất lúc bấy giờ, hắn đã liều mình bảo vệ ông chủ Prince thoát khỏi sự truy sát của đối phương. Điều này đã giúp hắn được toại nguyện. Thế nhưng, điều Cheung Dee không thể lường trước được là cái giá phải trả cho giấc mơ đó quá đắt. Hắn mất vợ, đứa con trai hai tuổi thì mất mẹ. Từ khi tận mắt chứng kiến chiếc xe tải đâm vào vợ mình, hắn thật sự chùn bước. Hắn bắt đầu biết sợ. Sợ chết, sợ vào tù. Hắn không muốn con trai hắn mất luôn cả cha. Nhưng điều có có phải đã quá muộn màng?</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Lương Vịnh Kì","avatar":""},{"name":"Suki Kwan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324533);
