INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ma', 'Thế Giới Ma', 'Ghost World', 'https://phimimg.com/upload/vod/20240104-1/2cf9490195e35075894dc92f1cbacfd3.jpg', 'https://phimimg.com/upload/vod/20240104-1/b929ea47db65dbf355f4530aadd577e4.jpg', '<p>Ghost World ( Thế giới ma) là một bộ phim hài Mỹ năm 2001 của đạo diễn Terry Zwigoff, dựa trên cuốn truyện tranh cùng tên và kịch bản của Daniel Clowes. Câu chuyện tập trung vào cuộc sống của Enid và Rebecca, hai cô gái tuổi teen sống trong một thành phố vô danh của Mỹ. Cả hai đều có những vấn đề liên quan đến những người xung quanh. Khi họ gặp Seymour cũng sống tách biệt với xã hội và thích thu thập mọi thứ cũ kĩ, cuộc sống của Enid đã thay đổi mãi mãi.</p>', 'Full', 1, 'single', 'completed', 12, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Thora Birch","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Brad Renfro","avatar":""},{"name":"Illeana Douglas","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
