INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('coi-xay-gio-do', 'Cối Xay Gió Đỏ', 'Moulin Rouge', 'https://phimimg.com/upload/vod/20240104-1/013b1540d439ef783cd307b8897b2e7b.jpg', 'https://phimimg.com/upload/vod/20240104-1/f5f7dd6a4df57e02478ec96d7718ba0a.jpg', '<p>Phim xoay quanh câu chuyện về một nhà thơ rời bỏ London để tới thủ đô nước Pháp tìm cảm hứng sáng tác. Định mệnh đưa đẩy anh gặp gỡ và đem lòng yêu mến một vũ nữ xinh đẹp của quán bar Cối Xay Gió Màu Đỏ. Hàng loạt những bi kịch, mâu thuẫn đã xảy đến với đôi tình nhân trẻ. Chuyện tình của họ như đứng trước một bờ vực thẳm khi cô gái phát hiện ra mình mắc phải một căn bệnh hiểm nghèo.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"John Leguizamo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324533);
