INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-thoi-giam-can', 'Tình Yêu Thời Giảm Cân', 'Love on a Diet', 'https://phimimg.com/upload/vod/20240102-1/8abda6751daae2a61f64e96f3ac88c83.jpg', 'https://phimimg.com/upload/vod/20240102-1/45b6b89067b7941ca1d368bc9ddfcba9.jpg', '<p>Mimi Mo, cô có một người bạn trai là một nghệ sĩ nổi tiếng tại Nhật Bản. Nhưng do trước đây người bạn trai ấy đi du học, trong lúc đau buồn Mimi đã ăn để quên buồn vì vậy khiến thân hình quá mập. Sau khi du học trở về người bạn trai thông qua đài phát thanh để tìm lại Mimi. Xấu hổ với thân hình của mình đã có lúc cô định tự tử nhưng nhờ sự động viên của bạn bè Mimi chỉ trong vòng một thời gian rất ngắn có một thân hình thật đẹp. Nhưng đó cũng là lúc cô nhận ra mình thật sự yêu ai. Diễn viên chính: Lưu Đức Hoa, Trịnh Tú Văn...</p>', 'Full', 1, 'single', 'completed', 13, 2001, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324533);
