INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phia-sau-chien-tuyen', 'Phía Sau Chiến Tuyến', 'Behind Enemy Lines', 'https://phimimg.com/upload/vod/20240102-1/6b2a97f182fafef3e4679865fab60c53.jpg', 'https://phimimg.com/upload/vod/20240102-1/c9f84df3a33e2f85705a8cb2ab370e3a.jpg', '<p>Một anh lính không quân đã nhập ngũ 7 năm, và bắt đầu cảm thấy bất mãn, nghi ngờ với cái được gọi là Phục vụ đất nước. Vì như lời anh nói với tướng Leslie Reigart: Chúng ta không có chiến tranh, đất nước này chưa bao giờ thật sự có chiến tranh cả, đối với tôi bảy năm là quá đủ... và anh xin được xuất ngũ trở về cuộc sống bình thường.</p>', 'Full', 1, 'single', 'completed', 11, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gene Hackman","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Gabriel Macht","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324533);
