INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-bach-cau', 'Cảnh Sát Bạch Cầu', 'Osmosis Jones', 'https://phimimg.com/upload/vod/20240102-1/3992b6ae706d932f2c3b054f7fd654e1.jpg', 'https://phimimg.com/upload/vod/20240102-1/2f3d144fade6e17a96850ffd93717071.jpg', '<p>Một cảnh sát bạch cầu, với sự trợ giúp của một viên thuốc cảm, phải ngăn chặn một loại virus chết người đang hủy hoại con người mà họ đang sống, Frank.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris Rock","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"David Hyde Pierce","avatar":""},{"name":"Brandy Norwood","avatar":""},{"name":"Bill Murray","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324533);
