INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-nha-soi', 'Anh Em Nhà Sói', 'Brotherhood Of The Wolf', 'https://phimimg.com/upload/vod/20231231-1/e0977c7bc5855137c5ad5901302bbe61.jpg', 'https://phimimg.com/upload/vod/20231231-1/720ad55324d251295919d385969d18ed.jpg', '<p>Vào giữa năm 1760, tỉnh Gévaudan của nước Pháp và những vùng lân cận chấn động bởi sự xuất hiện của một con sói khổng lồ. Nó giết chết hàng trăm người và gây hoang mang tột độ trong cộng đồng dân cư...</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Samuel Le Bihan","avatar":""},{"name":"Mark Dacascos","avatar":""},{"name":"Vincent Cassel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324533);
