INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-duoc-he-moi', 'Không Được Hé Môi', 'Don''t Say A Word', 'null', 'https://phimimg.com/upload/vod/20231230-1/234ebbf1df509a4aa50569a69a2adc16.jpg', '<p>Không Được Hé Môi - Dont Say A Word xoay quanh hành trình một bác sĩ tâm lý cứu cô con gái mình khỏi bọn bắt cóc. Một ngày, ông tiếp nhận một bệnh nhân mới, là một cô gái trẻ nhưng nhiều bí ẩn. Sáng hôm sau vị bác sĩ phát hiện ra con gái mình đã bị bắt cóc. Kẻ bắt cóc không tống tiền nhưng lại yêu cầu ông phải tìm cách hỏi cho được 6 con số nằm trong đầu cô gái trẻ kia.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Jennifer Esposito","avatar":""},{"name":"Brittany Murphy","avatar":""},{"name":"Guy Torry","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324533);
