INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cap-trai-tim', 'Kẻ Cắp Trái Tim', 'Heartbreakers', 'https://phimimg.com/upload/vod/20231219-1/df161d9906e1c6226d461d644984c986.jpg', 'https://phimimg.com/upload/vod/20231219-1/bc2858725c210a0ef2287f1ac5dc0719.jpg', '<p>Max và Page là một nhóm lừa đảo mẹ/con gái xuất sắc, những người có niềm đam mê với khoa học tốt. Max nhắm đến những người đàn ông giàu có, sẵn sàng và kết hôn với họ. Trang sau đó dụ dỗ họ, và Max bắt quả tang chồng cô đang hành động. Sau đó, nó sẽ đến thành phố palimony và điểm dễ dàng tiếp theo.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sigourney Weaver","avatar":""},{"name":"Jennifer Love Hewitt","avatar":""},{"name":"Gene Hackman","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Jason Lee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324533);
