INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mong-ngoi-sao', 'Giấc Mộng Ngôi Sao', 'Rock Star', 'https://phimimg.com/upload/vod/20231211-1/5e27708ecb7eb37aaa375edfab4fad3c.jpg', 'https://phimimg.com/upload/vod/20231211-1/9cfd2c0c2ee93e8e2437d6edecd3637f.jpg', '<p>Một ngôi sao nhạc rock muốn trở thành người đứng đầu một ban nhạc tưởng nhớ có trụ sở tại Pennsylvania đã bị tàn phá khi anh ta đuổi anh ta ra khỏi nhóm do anh ta thành lập. Mọi thứ bắt đầu có lợi cho Izzy khi anh ấy được đề nghị tham gia Steel Dragon, tay chơi rock hạng nặng mà anh ấy đã bắt chước bấy lâu nay. Bộ phim này dựa trên câu chuyện có thật của ban nhạc Judas Priest.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Dominic West","avatar":""},{"name":"Jason Bonham","avatar":""},{"name":"Jeff Pilson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
