INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-cao-diem-2', 'Giờ Cao Điểm 2', 'Rush Hour 2', 'https://phimimg.com/upload/vod/20231211-1/f2e44d8cf7f2d637599e1bbaa039e5a7.jpg', 'https://phimimg.com/upload/vod/20231211-1/1de096e929b0de310046f3b81964ec0d.jpg', '<p>Đó là thời gian nghỉ để Det. James Carter và anh thấy mình cùng với Det. Lee ở Hồng Kông mong muốn phấn khích hơn. Trong khi Carter muốn tiệc tùng và gặp gỡ những người phụ nữ, Lee ra ngoài để theo dõi một Lord Gang Triad, người có thể chịu trách nhiệm giết hai người đàn ông tại Đại sứ quán Mỹ. Mọi thứ trở nên phức tạp khi cặp đôi vấp phải một âm mưu giả bởi L.A. Ông chủ tội phạm Steven Ricky và Triad Ricky Tan, một cựu cảnh sát đã đóng một vai trò bí ẩn trong cái chết của Det. Cha của Lee. Ném vào một cuộc đấu tranh quyền lực giữa Tan và Hu Li li tuyệt đẹp nhưng nguy hiểm và các chàng trai sẽ sớm đến cổ trong các trận đấu nắm đấm và các tình huống đe dọa tính mạng. Một chuyến đi trở về Hoa Kỳ có thể cung cấp các câu trả lời về vụ đánh bom, giả mạo và lòng trung thành thực sự của đại lý hải quan gợi cảm Isabella. Sau đó, một lần nữa, nó có thể trở nên phấn khích hơn Carter đang tìm kiếm trong kỳ nghỉ của mình.</p>', 'Full', 1, 'single', 'completed', 12, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324533);
