INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-cho-meo-1', 'Đại Chiến Chó Mèo 1', 'Cats & Dogs', 'https://phimimg.com/upload/vod/20231211-1/c603a988020e050a01c85b1474746b3f.jpg', 'https://phimimg.com/upload/vod/20231211-1/9fd575db3e835e2863815cef06ace179.jpg', '<p>Một điều mà loài người của chúng ta không hề hay biết về những con vật bầu bạn của mình: loài chó đã phải đấu tranh trong hàng nghìn năm với loài mèo để giúp đỡ nhân loại tránh khỏi sự hủy diệt. Gã mèo lang thang Mr Tinkles, là một trong những thủ lĩnh, đã đặt ra những chiến lược nhằm đánh đuổi thế giới loài chó và xa hơn là thôn tính cả địa cầu bằng những kĩ thuật tối tân của mình...</p>', 'Full', 1, 'single', 'completed', 12, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alec Baldwin","avatar":""},{"name":"Tobey Maguire","avatar":""},{"name":"Jeff Goldblum","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324533);
