INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-kiem-john-gissing', 'Tìm Kiếm John Gissing', 'Search For John Gissing', 'https://phimimg.com/upload/vod/20240102-1/153a24f4578dbdae879387fcb0f098ca.jpg', 'https://phimimg.com/upload/vod/20240102-1/eec4f9f3d91dff11db0f78ec129f9d5b.jpg', '<p>Tìm Kiếm John Gissing - Search For John Gissing kể về Matthew Barnes, một giám đốc điều hành trẻ đang thăng tiến được cử đến London để giám sát một vụ sáp nhập. Cuộc sống của anh cùng vợ của mình tại đây bắt đầu bị đảo lộn mọi thứ bởi người đồng nghiệp người Anh - John Gissing. Matthew cũng phát hiện ra rằng mình chỉ là một con tốt trong cuộc giao tranh giành quyền lợi của công ty khi anh sẽ thay thế John Gissing.</p>', 'Full', 1, 'single', 'completed', 25, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Janeane Garofalo","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"MIKE BINDER","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
