INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-me-xi-co', 'Người Mê Xi Cô', 'The Mexican', 'https://phimimg.com/upload/vod/20231211-1/6cf3fe69836e4205b630aec60b198552.jpg', 'https://phimimg.com/upload/vod/20231211-1/f23fce17d7ca9213a6e47c13c67f99f7.jpg', '<p>Jerry Welbach, một kẻ móc túi bất đắc dĩ, đã được đưa ra hai tối hậu thư: Thứ nhất là từ ông trùm băng đảng của anh ta phải đi du lịch đến Mexico và lấy một khẩu súng lục cổ vô giá, được gọi là Mexico... nếu không sẽ phải gánh chịu hậu quả. Thứ hai là từ bạn gái Samantha của anh ấy để chấm dứt mối quan hệ của anh ấy với đám đông. Jerry cho rằng còn sống và gặp rắc rối với Samantha tốt hơn là giải pháp thay thế lâu dài hơn, vì vậy anh ta đi về phía nam biên giới.</p>', 'Full', 1, 'single', 'completed', 13, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"James Gandolfini","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Gene Hackman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324533);
