INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-huan-luyen', 'Ngày Huấn Luyện', 'Training Day', 'https://phimimg.com/upload/vod/20231211-1/782105be25ee89dfe4a9d24d25b0c75d.jpg', 'https://phimimg.com/upload/vod/20231211-1/b9073665ff076370af63475cf4100cda.jpg', '<p>Bộ phim lấy bối cảnh là một thành phố đầy rẫy những kẻ buôn bán ma tuý. Jake Hoyt (Ethan Hawke) muốn được làm việc trong lực lượng chống buôn bán ma tuý của Los Angeles do Alonzo Harris (Denzel Washington) đứng đầu. Thế nhưng, chàng cảnh sát đầy lý tưởng không hề biết rằng sếp của anh, thay vì trấn áp các băng đảng buôn ma tuý, lại dung túng cho bọn chúng làm ăn để lấy tiền bảo kê. Do là nhân viên mới, Jake buộc phải trải qua một khoá huấn luyện nghiệp vụ kéo dài trong 24 giờ. Thực chất đây chính là sự đối đầu căng thẳng ngầm giữa Jake Hoyt và đội trưởng của anh. Cả Alonzo và Jake đều không thể ngờ rằng đây lại là khởi đầu cho bước ngoặt của cuộc đời họ.</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Scott Glenn","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324533);
