INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-nuoc-my', 'Người Tình Nước Mỹ', 'America''s Sweethearts', 'https://phimimg.com/upload/vod/20231204-1/d128d54727e3dc452068019b899b6426.jpg', 'https://phimimg.com/upload/vod/20231204-1/1ed2c803c013e368b6cfab5b5fb571c7.jpg', '<p>Giữa cuộc chia tay công khai khó chịu của các ngôi sao điện ảnh đã kết hôn, một nhà báo của hãng phim cố gắng che đậy tình hình leo thang khi bộ phim mới nhất của cặp đôi này phát hiện ra nó chỉ là bản in bị đạo diễn bắt cóc.</p>', 'Full', 1, 'single', 'completed', 11, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julia Roberts","avatar":""},{"name":"Billy Crystal","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""},{"name":"John Cusack","avatar":""},{"name":"Hank Azaria","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324533);
