INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-quen-thuoc', 'Người Tình Quen Thuộc', 'Intimacy', 'https://phimimg.com/upload/vod/20231204-1/50386ed975524b4a61e9a2a0fdadec92.jpg', 'https://phimimg.com/upload/vod/20231204-1/3f1b1f7e40aada9aef6eea6eac5338c1.jpg', '<p>Jay, một bartender bị ruồng bỏ bởi chính gia đình của mình do vợ anh đã hết hứng thú với mối quan hệ của họ. Giờ đây khi cô đơn sống trong một ngôi nhà cũ kỹ, hàng tuần Jay đều làm tình với một người phụ nữ mà đến cái tên anh ta cũng không hề biết. Mới đầu họ tìm đến nhau chỉ để thỏa mãn nhu cầu tình dục, nhưng về sau Jay phát hiện ra rằng anh đã yêu người phụ nữ đó.Với sự tò mò về người tình bí ẩn của mình, Jay đi theo người phụ nữ dọc theo những con phố của London tới khu ngoại ô xám xịt nơi cô ở. Anh còn theo chân nàng tới một rạp hát quán rượu nơi cô làm việc vào mỗi tối. Jay biết được tên của cô là Claire, cô đã kết hôn và có một cậu con trai. Jay đã quyết định chấm dứt mối quan hệ của họ…</p>', 'Full', 1, 'single', 'completed', 13, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Rylance","avatar":""},{"name":"Kerry Fox","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Alastair Galbraith","avatar":""},{"name":"Marianne Faithfull","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
