INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuc-cau-sieu-cua-tuoi-tre', 'Khúc Cầu Siêu Của Tuổi Trẻ', 'All About Lily Chou-Chou', 'https://phimimg.com/upload/vod/20231130-1/beac779a04aed94d53b2635634ff63f3.jpg', 'https://phimimg.com/upload/vod/20231130-1/71cf8ae7bcbc64223a369246bc1d5839.jpg', '<p>Phim All About Lily Chou-Chou 2001 kể về Yuichi Hasumi là một học sinh lớp 8, đang sống với mẹ, bạn trai của mẹ và con trai của ông ta tại một vùng nông thôn Nhật Bản. Tại trường học cậu thường bị thầy cô la mắng và bạn bè lợi dụng. Trong những chuỗi ngày ngột ngạt như thế, đối với Yuichi chỉ còn một thứ duy nhất khiến cậu quan tâm là Lily Chou-Chou, ca sỹ ưa thích của cậu...</p>', 'Full', 1, 'single', 'completed', 13, 2001, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hayato Ichihara","avatar":""},{"name":"Shugo Oshinari","avatar":""},{"name":"Yu Aoi","avatar":""},{"name":"Ayumi Ito","avatar":""},{"name":"Takao Osawa","avatar":""},{"name":"Ryo Katsuji","avatar":""},{"name":"Tomohiro Kaku","avatar":""},{"name":"Issey Takahashi","avatar":""},{"name":"Kazusa Matsuda","avatar":""},{"name":"Takahito Hosoyamada","avatar":""},{"name":"Chiyo Abe","avatar":""},{"name":"Izumi Inamori","avatar":""},{"name":"Miwako Ichikawa","avatar":""},{"name":"Anri Ban","avatar":""},{"name":"Takako Baba","avatar":""},{"name":"Yoji Tanaka","avatar":""},{"name":"Yoriko Kitahara","avatar":""},{"name":"Shinji Higuc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324533);
