INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-trom-2001', 'Siêu Trộm', 'The Score', 'https://phimimg.com/upload/vod/20231129-1/bb630b10794a64bc181ad0cac6427bfe.jpg', 'https://phimimg.com/upload/vod/20231129-1/383ef587b8b9bf46f8a738f1b279b930.jpg', '<p>Nick Wells có vỏ bọc bên ngoài là ông chủ một quán rượu danh giá tại Montreal nhưng thực chất lại là một đạo chích sừng sỏ và khôn ranh với 25 năm trong nghề đục tường bẻ khóa mà chưa một lần sa lưới pháp luật. Nguyên tắc làm việc của anh ta là điều nghiên kỹ càng, xóa sạch dấu vết, chắc ăn mới làm và không hành nghề tại địa phương...</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Edward Norton","avatar":""},{"name":"Marlon Brando","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Gary Farmer","avatar":""},{"name":"Jamie Harrold","avatar":""},{"name":"Paul Soles","avatar":""},{"name":"Martin Drainville","avatar":""},{"name":"Serge Houde","avatar":""},{"name":"Jean-René Ouellet","avatar":""},{"name":"Claude Despins","avatar":""},{"name":"Richard Waugh","avatar":""},{"name":"Mark Camacho","avatar":""},{"name":"Marie-Josée Colburn","avatar":""},{"name":"Gavin Svensson","avatar":""},{"name":"Thinh Truong Nguyen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324533);
