INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-co-hoan-luong', 'Ma Cô Hoàn Lương', 'Bad Guy', 'https://phimimg.com/upload/vod/20231129-1/788521d02ddc1350de31556ca6d8f5ba.jpg', 'https://phimimg.com/upload/vod/20231129-1/94366ffba3539638a73ac4301ff06084.jpg', '<p>Một tên tội phạm điều hành một nhà thổ bị ám ảnh bởi một sinh viên đại học xinh đẹp. Khi cô từ chối anh ta, anh ta gài bẫy cô bằng cách giới thiệu cô với một kẻ cho vay nặng lãi và khi cô không thể trả được tiền, cô bị buộc phải làm việc trong nhà thổ. Nhưng khi có cơ hội trốn thoát, cô nhận ra mình không thể quay lại cuộc sống trước đây.</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Cho Jae-hyun","avatar":""},{"name":"Seo Won","avatar":""},{"name":"Kim Yun-tae","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Choi Yoon-young","avatar":""},{"name":"Yoo-jin Shin","avatar":""},{"name":"Kim Jung-young","avatar":""},{"name":"Namkoong Min","avatar":""},{"name":"Kim Yun-tae","avatar":""},{"name":"Lee Han-wi","avatar":""},{"name":"Park Sun Woong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324533);
