INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-phai-phim-teen', 'Không Phải Phim Teen', 'Not Another Teen Movie', 'https://phimimg.com/upload/vod/20231129-1/db69bdd99f0f8962c26c40c6fd713278.jpg', 'https://phimimg.com/upload/vod/20231129-1/6af3bef9b0ebd42a62761d4c145fa5d1.jpg', '<p>Jake Wyler là chàng trai nổi tiếng nhất trường trung học, còn Jany Briggs lại là 1 cô gái rất &quot;quái&quot;. Jake cá độ rằng anh sẽ biến bất kì cô gái nào do đám bạn chọn trở thành nữ hoàng khiêu vũ trong đêm party của trường. Diễn biến của câu chuyện sẽ cho bạn những trận cười nghiêng ngã.</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chyler Leigh","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Jaime Pressly","avatar":""},{"name":"Eric Christian Olsen","avatar":""},{"name":"Mia Kirshner","avatar":""},{"name":"Lacey Chabert","avatar":""},{"name":"Samaire Armstrong","avatar":""},{"name":"Cerina Vincent","avatar":""},{"name":"Mr. T","avatar":""},{"name":"Molly Ringwald","avatar":""},{"name":"Heather Brown","avatar":""},{"name":"Nectar Rose","avatar":""},{"name":"Michael Ensign","avatar":""},{"name":"Kyle Cease","avatar":""},{"name":"Eric Jungmann","avatar":""},{"name":"Desi Lydic","avatar":""},{"name":"Deon Richmond","avatar":""},{"name":"Ron Le","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324533);
