INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-dua-chet-nguoi-2001', 'Trò Đùa Chết Người', 'Joy Ride', 'https://phimimg.com/upload/vod/20231119-1/2fe476d63d08455dbb9fd58c86e8bcb5.jpg', 'https://phimimg.com/upload/vod/20231119-1/bce9be7c85e15940619658c9dcd962f7.jpg', '<p>Câu chuyện càng trở nên gay cấn khi những tài xế xe tải bắt cóc Venna - người yêu trong mộng của Lewis, và cô bạn thân của cô. Trò chơi mèo vờn chuột giờ đây trở thành những cái bẫy giết người. Lewis và Fuller vô cùng hối hận và không ngừng van xin qua bộ đàm. Nhưng mọi chuyện vẫn còn chưa kết thúc...</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Walker","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Leelee Sobieski","avatar":""},{"name":"Michael McCleery","avatar":""},{"name":"Dell Yount","avatar":""},{"name":"Rachel Singer","avatar":""},{"name":"Jim Beaver","avatar":""},{"name":"Jessica Bowman","avatar":""},{"name":"Stuart Stone","avatar":""},{"name":"Basil Wallace","avatar":""},{"name":"Brian Leckner","avatar":""},{"name":"Mary Wickliffe","avatar":""},{"name":"McKenzie Satterthwaite","avatar":""},{"name":"Kenneth White","avatar":""},{"name":"Luis Cortés","avatar":""},{"name":"Satch Huizenga","avatar":""},{"name":"Terry Leonar","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
