INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-khi-2001', 'Hành Tinh Khỉ', 'Planet of the Apes', 'https://phimimg.com/upload/vod/20230912-1/e2f883ffeae4a30a54372487bc0c925d.jpg', 'https://phimimg.com/upload/vod/20230912-1/41752e373c9a099c4d25a713372f8756.jpg', '<p><span style="font-family: ">Hành trình của phi hành gia Leo, người Trái Đất, sau khi thực hiện nhiệm vụ trong vũ trụ gặp phải tai nạn bất ngờ phải đáp xuống một hành tinh kỳ lạ. Nơi đây loài khỉ đã trở thành loài thống lĩnh với trí tuệ và một hệ thống cai trị khắc nghiệt. Cuộc phiêu lưu của Leo để giành lại tự do trong một xã hội của loài linh trưởng giống với loài người nhất này sẽ ra sao khi những bí mật về tổ tiên của hành tinh dần được hé lộ. Một siêu phẩm của đạo diễn Tim Burton với diễn xuất tài năng của ngôi sao hành động Mark Walberg là dấu đảm bảo cho một bộ phim bom tấn của điện ảnh Hoa Kỳ.</span></p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Kris Kristofferson","avatar":""},{"name":"Estella Warren","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Cary-Hiroyuki Tagawa","avatar":""},{"name":"Glenn Shadix","avatar":""},{"name":"Charlton Heston","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324533);
