INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-dien-dai-2001', 'Yêu Điên Dại', 'Head Over Heels', 'https://phimimg.com/upload/vod/20231115-1/517709ea970cfcc5310e0a51becc6a9e.jpg', 'https://phimimg.com/upload/vod/20231115-1/854d021aaf55f1cd4769ee8354aaebbb.jpg', '<p>Amanda là một cô gái kém may mắn với các chàng trai. Cuộc tình gần đây nhất tan vỡ khi cô về nhà và bắt gặp bạn trai của mình ăn nằm với một phụ nữ khác. Cô quyết định dọn ra khỏi căn hộ và đến sống chung cùng 4 cô người mẫu – những người chỉ biết tiệc tùng. Trong thời gian này, cô tìm được một gã trai có tên Jim, người mà cô cảm thấy bị thu hút nhưng lại sợ nỗi ám ảnh của quá khứ. Cô sợ rằng chàng trai này cũng giống như bao người bạn trai khác, sẽ bỏ cô và đi với những người đàn bà khác. Khi Amanda quyết định vượt lên chính mình, chấp nhận hẹn hò với anh chàng kia thì cũng là lúc chính mắt cô chứng kiến anh chàng giết người. Amanda nhanh chóng gọi cho cảnh sát nhưng họ không giúp gì được ngoài những lời hứa. Cô quyết tâm lần theo dấu vết của chàng trai để tìm hiểu ngọn ngành.</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Monica Potter","avatar":""},{"name":"Freddie Prinze Jr.","avatar":""},{"name":"Shalom Harlow","avatar":""},{"name":"Ivana Miličević","avatar":""},{"name":"Sarah Murdoch","avatar":""},{"name":"Tomiko Fraser","avatar":""},{"name":"China Chow","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"Stanley DeSantis","avatar":""},{"name":"Erin-Marie Dykeman","avatar":""},{"name":"James Kirk","avatar":""},{"name":"Elysa Hogg","avatar":""},{"name":"Kristina Lewis","avatar":""},{"name":"Ben Silverman","avatar":""},{"name":"Sam MacMillan","avatar":""},{"name":"Jay Brazeau","avatar":""},{"name":"Raoul G","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324533);
