INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-coc-2001', 'Bắt Cóc', 'Along Came a Spider', 'https://phimimg.com/upload/vod/20231026-1/94239ea5f958f8b58e1fa1bdd90953e7.jpg', 'https://phimimg.com/upload/vod/20231026-1/6a0b8a382f1c529481109538828db9c5.jpg', '<p>Thanh tra kiêm chuyên gia tâm lý Alex Cross bắt tay với một Mật vụ hết thời để tìm con gái thượng nghị sĩ bị bắt cóc tại ngôi trường dự bị danh giá.</p>', 'Full', 1, 'single', 'completed', 13, 2001, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Morgan Freeman","avatar":""},{"name":"Monica Potter","avatar":""},{"name":"Michael Wincott","avatar":""},{"name":"Dylan Baker","avatar":""},{"name":"Mika Boorem","avatar":""},{"name":"Anton Yelchin","avatar":""},{"name":"Kim Hawthorne","avatar":""},{"name":"Jay O. Sanders","avatar":""},{"name":"Billy Burke","avatar":""},{"name":"Michael Moriarty","avatar":""},{"name":"Penelope Ann Miller","avatar":""},{"name":"Anna Maria Horsford","avatar":""},{"name":"Scott Heindl","avatar":""},{"name":"Christopher Shyer","avatar":""},{"name":"Jill Teed","avatar":""},{"name":"Ian Marsh","avatar":""},{"name":"Raoul G","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324533);
