INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bat-coc-2001', 'Bắt Cóc', 'Along Came a Spider', 'bắt cóc along came a spider morgan freeman monica potter michael wincott dylan baker mika boorem anton yelchin kim hawthorne jay o. sanders billy burke michael moriarty penelope ann miller anna maria horsford scott heindl christopher shyer jill teed ian marsh raoul g ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-trong-nuoi-con', 'Gà Trống Nuôi Con', 'I Am Sam', 'https://phimimg.com/upload/vod/20231129-1/c9a87c4b19ad84847c1898923164a9a2.jpg', 'https://phimimg.com/upload/vod/20231129-1/5395cf3316166523a986c2dd8de26115.jpg', '<p>Một ông bố thiểu năng sẽ làm gì khi biết rằng một ngày nào đó, ông sẽ bị chia cắt mãi mãi với cô con gái mà mình yêu thương nhất? Bằng nghị lực và một trái tim nồng nàn nhất, Sam bất chấp tất cả để được đoàn tụ với cô con gái Lucy mà anh đã nuôi nấng trong suốt 7 năm. Sam một mình chăm sóc Lucy từ khi cô bé bị người mẹ bỏ rơi. Anh không có tiền bạc, của cải, một sự nghiệp lẫy lừng hay trí tuệ của nhà bác học để khiến Lucy có thể hãnh diện. Sam chỉ có một tình yêu thương vô bờ bến dành cho cô con gái bé bỏng mà đối với anh, đó là niềm hạnh phúc lớn lao nhất trong cuộc đời. Diễn xuất tuyệt vời của Sean Penn đã khiến người xem phải rơi lệ. Tình cha con giữa Sam và Lucy cũng để lại nhiều suy nghĩ. Liệu rằng mỗi ...</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Penn","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Dianne Wiest","avatar":""},{"name":"Dakota Fanning","avatar":""},{"name":"Richard Schiff","avatar":""},{"name":"Loretta Devine","avatar":""},{"name":"Marin Hinkle","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Brad Silverman","avatar":""},{"name":"Joseph Rosenberg","avatar":""},{"name":"Stanley DeSantis","avatar":""},{"name":"Doug Hutchison","avatar":""},{"name":"Bobby Cooper","avatar":""},{"name":"Mary Steenburgen","avatar":""},{"name":"Eileen Ryan","avatar":""},{"name":"Michael B. Silver","avatar":""},{"name":"Rosal","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
