INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-thien-tai', 'Gia Đình Thiên Tài', 'The Royal Tenenbaums', 'https://phimimg.com/upload/vod/20231128-1/559160213dd12b470bf3dc539195782d.jpg', 'https://phimimg.com/upload/vod/20231128-1/3ce60a42d0c2e052b14d535c6274fe3e.jpg', '<p>Gia đình Tenenbaum sản sinh ra 3 đứa trẻ thiên tài. Cuộc hôn nhân đổ vỡ của ông bà Tenenbaum đã để lại di chứng lên những đứa con cho tới tận khi chúng trưởng thành.</p><p>Cậu cả Chas giờ biến hai đứa con thành những robot phản ứng nhanh với mọi tình huống, sau vụ tai nạn khiến anh mất vợ. Cậu hai Richie, từ một thiên tài quần vợt, trở thành người kín tiếng ngao du khắp nơi. Cô con gái nuôi Margot, từ một thiên tài viết kịch, sống bí ẩn và chỉ thích ngâm mình trong bồn tắm.</p><p>Cơ hội để ông Royal Tenenbaum chuộc lại lỗi lầm xuất hiện khi ông biết mình mắc bệnh ung thư và chỉ còn ít thời gian...</p><p>Bộ phim được xếp vào thể loại bi - hài kịch, khiến người xem có thể bật cười, nhưng cũng khó dứt ra khỏi những chi tiết ảm đạm.</p>', 'Full', 1, 'single', 'completed', 17, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gene Hackman","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"Ben Stiller","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Kumar Pallana","avatar":""},{"name":"Stephen Lea Sheppard","avatar":""},{"name":"Grant Rosenmeyer","avatar":""},{"name":"Jonah Meyerson","avatar":""},{"name":"Seymour Cassel","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Aram Aslanian-Persico","avatar":""},{"name":"Irina Gorovaia","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
