INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-experiment', 'The Experiment', 'The Experiment', 'https://phimimg.com/upload/vod/20231129-1/3a9481597959e7e0ebf38ccb12548173.jpg', 'https://phimimg.com/upload/vod/20231129-1/099cdae85d5c8e7d0d5a7bf8b8e0c12d.jpg', '<p>Das Experiment là một bộ phim kinh dị tâm lý gây sốc về tiềm năng tàn bạo mà con người che giấu. Điều gây sốc hơn nữa là nó dựa trên một sự kiện có thật - một thí nghiệm tâm lý năm 1971 tại Đại học Stanford đã bị hủy bỏ sớm khi những người làm thí nghiệm mất kiểm soát.</p>', 'Full', 1, 'single', 'completed', 12, 2001, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Moritz Bleibtreu","avatar":""},{"name":"Christian Berkel","avatar":""},{"name":"Oliver Stokowski","avatar":""},{"name":"Wotan Wilke Möhring","avatar":""},{"name":"Stephan Szasz","avatar":""},{"name":"Andrea Sawatzki","avatar":""},{"name":"Polat Dal","avatar":""},{"name":"Danny Richter","avatar":""},{"name":"Ralf Müller","avatar":""},{"name":"Markus Rudolf","avatar":""},{"name":"Peter Fieseler","avatar":""},{"name":"Thorsten Dersch","avatar":""},{"name":"Sven Grefer","avatar":""},{"name":"Justus von Dohnányi","avatar":""},{"name":"Nicki von Tempelhoff","avatar":""},{"name":"Timo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
