INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lara-croft-ke-cuop-lang-mo', 'Lara Croft: Kẻ Cướp Lăng Mộ', 'Lara Croft: Tomb Raider', 'https://phimimg.com/upload/vod/20231129-1/efd90a5b6d2436b52555c221da6d6077.jpg', 'https://phimimg.com/upload/vod/20231129-1/5666038ef4bad55310980a9e71afc5df.jpg', '<p>Lara Croft Tomb Raider (Kẻ Cướp Lăng Mộ 1) là bộ phim phiêu lưu chuyển thể từ dòng trò chơi Tomb Raider. Nội dung phim quay quanh cuộc phiêu lưu của Lara Croft sau khi cha cô mất tích và chỉ để lại một bức thư. Trong bức thư, cha cô đã nói cho cô biết bí mật về hai mảnh Tam giác ánh sáng và ông đã cố gắng bảo vệ nó trước lòng tham của những kẻ xấu xa. Tiếc thay đại diện của nhóm Illuminati Manfred Powell đã cướp được Tam giác ánh sáng. Nhiệm vụ của Lara giờ đây là giành lại báu vật nhằm ngăn chặn âm mưu điên rồ của Manfred.</p>', 'Full', 1, 'single', 'completed', 17, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Angelina Jolie","avatar":""},{"name":"Iain Glen","avatar":""},{"name":"Daniel Craig","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"Chris Barrie","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Julian Rhind-Tutt","avatar":""},{"name":"Leslie Phillips","avatar":""},{"name":"Richard Johnson","avatar":""},{"name":"Robert Phillips","avatar":""},{"name":"Rachel Appleton","avatar":""},{"name":"Henry Wyndham","avatar":""},{"name":"David Cheung","avatar":""},{"name":"David K.S. Tse","avatar":""},{"name":"Ayla Amiral","avatar":""},{"name":"Ozzie Yue","avatar":""},{"name":"Wai-Keat Lau","avatar":""},{"name":"Steph","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be11