INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ticker', 'Ticker', 'Ticker', 'https://phimimg.com/upload/vod/20231125-1/1549712756211e81f11a8abd15ef9f86.jpg', 'https://phimimg.com/upload/vod/20231125-1/6df6a0dc46fd4b84d4faad79a668b78d.jpg', '<p>Ray Nettles, một thám tử của San Francisco, và đối tác của anh ta là Fuzzy phải đối đầu với một trong những băng nhóm khủng bố nguy hiểm nhất của thành phố. Khi một trong những kẻ khủng bố, nhà khoa học xinh đẹp Claire Manning bị bắt, Swan, thủ lĩnh của bọn khủng bố, tuyên bố hắn sẽ cho nổ bom khắp thành phố nếu cô không được thả. Vì có thể xảy ra đổ máu, Nettles kêu gọi sự giúp đỡ của chuyên gia chất nổ Frank Glass...</p>', 'Full', 1, 'single', 'completed', 13, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Sizemore","avatar":""},{"name":"Steven Seagal","avatar":""},{"name":"Dennis Hopper","avatar":""},{"name":"Jaime Pressly","avatar":""},{"name":"Nas","avatar":""},{"name":"Rozonda ''Chilli'' Thomas","avatar":""},{"name":"Peter Greene","avatar":""},{"name":"Kevin Gage","avatar":""},{"name":"Michael Halsey","avatar":""},{"name":"Norbert Weisser","avatar":""},{"name":"Romany Malco","avatar":""},{"name":"Joe Spano","avatar":""},{"name":"Mimi Rose","avatar":""},{"name":"Tish Daniels","avatar":""},{"name":"Linda Castro","avatar":""},{"name":"Vanessa Branch","avatar":""},{"name":"Simona Williams","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
