INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-lost-battalion', 'The Lost Battalion', 'The Lost Battalion', 'https://phimimg.com/upload/vod/20231125-1/032cef9a5a31871f8572fe7087fe608a.jpg', 'https://phimimg.com/upload/vod/20231125-1/a9fa5dbde8b3d1ec5f6f3e518129187a.jpg', '<p>Bộ phim truyền hình chiến tranh dựa trên sự thật kể về một tiểu đoàn Mỹ hơn 500 người bị mắc kẹt sau chiến tuyến của kẻ thù trong Rừng Argonne vào tháng 10 năm 1918 ở Pháp trong những tuần kết thúc của Thế chiến thứ nhất.</p>', 'Full', 1, 'single', 'completed', 17, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ricky Schroder","avatar":""},{"name":"Phil McKee","avatar":""},{"name":"Jamie Harris","avatar":""},{"name":"Jay Rodan","avatar":""},{"name":"Adam James","avatar":""},{"name":"Daniel Caltagirone","avatar":""},{"name":"Michael Goldstrom","avatar":""},{"name":"Finbar Lynch","avatar":""},{"name":"Derek Kueter","avatar":""},{"name":"Hugh Fraser","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324533);
