INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-dia-nguc', 'Từ Địa Ngục', 'From Hell', 'https://phimimg.com/upload/vod/20231124-1/a5d0eb9ddd96a225ac3deee031926520.jpg', 'https://phimimg.com/upload/vod/20231124-1/2b7fbcedfe6b0e120504182b93b90a32.jpg', '<p>From Hell kể về cuộc điều tra của Abberline về vụ án bí ẩn xảy ra tại London năm 1888. Có một kẻ giết người chuyên săn đuổi các cô gái điếm vào buổi tối, mổ bụng họ và lấy đi bất kì bộ phận nội tạng nào. Mọi nghi ngờ đều dồn về phía những tên đồ tể, thợ thuộc da hoặc những người Do Thái. Nhưng Abberline biết hung thủ chỉ có thể là một nhà phẫu thuật học tài ba và hắn thuộc tầng lớp quý tộc. Mọi chuyện trở nên nghiêm trọng khi Mary – cô gái điếm mà Abberline yêu trở thành mục tiêu cuối cùng của kẻ giết người, trong khi anh vẫn chưa tìm được hung thủ...</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Heather Graham","avatar":""},{"name":"Ian Holm","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Ian Richardson","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Katrin Cartlidge","avatar":""},{"name":"Terence Harvey","avatar":""},{"name":"Susan Lynch","avatar":""},{"name":"Paul Rhys","avatar":""},{"name":"Lesley Sharp","avatar":""},{"name":"Estelle Skornik","avatar":""},{"name":"Nicholas McGaughey","avatar":""},{"name":"Annabelle Apsion","avatar":""},{"name":"Joanna Page","avatar":""},{"name":"Mark Dexter","avatar":""},{"name":"Danny Midwinter","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
