INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-hoc-viec', 'Giang Hồ Học Việc', 'Knockaround Guys', 'https://phimimg.com/upload/vod/20231123-1/aa65dc070970e3982ebf3555fda3ffd5.jpg', 'https://phimimg.com/upload/vod/20231123-1/28c897290f7df67d543dc9482ca3a16e.jpg', '<p>Giang Hồ Học Việc - Knockaround Guys: là bộ phim tâm lý hài hước xoay quanh anh chàng Matty Demaet. Do gia đình có quan hệ với bọn băng đảng, lý lịch của Matty không đủ lương thiện để có một việc làm đàng hòang, mặt khác anh cũng chưa đủ phẩm chất để trở thành một thành viên thực thụ của bọn tội phạm. Từ lúc tránh né sứ mạng được giao đi thanh tóan một gia đình thù địch, anh bị xem như một kẻ hèn nhát.Từ lúc tránh né nhiệm vụ thanh toán một gia đình thù địch, Matty bị xem như một kẻ hèn nhát. Gã được cử đến Montana lấy một số tiền. Cùng 3 chiến hữu, Matty hăm hở thực hiện phi vụ hòng lấy niềm tin của bố. Nhưng sự vụ trở nên rắc rối khi số tiền bị nẫng mất. Còn tay cảnh sát trưởng địa phương cũng đã để mắt tới nhóm giang hồ vặt...</p>', 'Full', 1, 'single', 'completed', 17, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Barry Pepper","avatar":""},{"name":"Andy Davoli","avatar":""},{"name":"Seth Green","avatar":""},{"name":"Vin Diesel","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Arthur J. Nascarella","avatar":""},{"name":"Nicholas Pasco","avatar":""},{"name":"Shawn Doyle","avatar":""},{"name":"Kevin Gage","avatar":""},{"name":"Dennis Hopper","avatar":""},{"name":"Andrew Francis","avatar":""},{"name":"John Liddle","avatar":""},{"name":"Kris Lemche","avatar":""},{"name":"Dov Tiefenbach","avatar":""},{"name":"Tom Noonan","avatar":""},{"name":"Catherine Fitch","avatar":""},{"name":"Ceciley Jenkins","avatar":""},{"name":"Jennif","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
