INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-cong-chua', 'Nhật Ký Công Chúa', 'The Princess Diaries', 'https://phimimg.com/upload/vod/20231123-1/b9f47eea1d9640464985c874ced689da.jpg', 'https://phimimg.com/upload/vod/20231123-1/40e7058480219e80e315fe1a98d1bf73.jpg', '<p>Ngay cả trong giấc mơ hoang đường nhất, cô học trò Mia nghịch ngợm, đôi phần luộm thuộm cũng chẳng bao giờ nghĩ mình sẽ là con gái một thái tử. Ấy vậy mà một ngày, đích thân nữ hoàng của vương quốc Genovia từ châu Âu xa xôi đã lặn lội tới Mỹ để biến Mia thành công chúa xinh đẹp. Gia nhập cuộc sống hoàng gia, Mia gặp vô số niềm vui, nhưng rắc rối cũng đầy ắp. Dưới sự chỉ dẫn của bà nội - nữ hoàng, Mia phải học cách trị vì đất nước, phải thực hiện cho được một nhiệm vụ quá khó khăn với một cô công chúa 18 tuổi: kén phò mã trong 30 ngày. Lợi dụng dịp này, một thành viên trong nghị viện Genovia đã tự đề cử cháu trai mình làm phò mã với mục tiêu thao túng đất nước. Thật không ngờ là Mia lại yêu chàng trai này say đắm.</p>', 'Full', 1, 'single', 'completed', 18, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anne Hathaway","avatar":""},{"name":"Julie Andrews","avatar":""},{"name":"Patrick John Flueger","avatar":""},{"name":"Heather Matarazzo","avatar":""},{"name":"Héctor Elizondo","avatar":""},{"name":"Mandy Moore","avatar":""},{"name":"Caroline Goodall","avatar":""},{"name":"Robert Schwartzman","avatar":""},{"name":"Erik von Detten","avatar":""},{"name":"Sean O''Bryan","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"Kathleen Marshall","avatar":""},{"name":"Mindy Burbano","avatar":""},{"name":"Kimleigh Smith","avatar":""},{"name":"Elizabeth Gudenrath","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324533);
