INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-ky-cong-chua', 'Nhật Ký Công Chúa', 'The Princess Diaries', 'nhật ký công chúa the princess diaries anne hathaway julie andrews patrick john flueger heather matarazzo héctor elizondo mandy moore caroline goodall robert schwartzman erik von detten sean o''bryan sandra oh kathleen marshall mindy burbano kimleigh smith elizabeth gudenrath ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hal-nong-can', 'Hal Nông Cạn', 'Shallow Hal', 'https://phimimg.com/upload/vod/20231123-1/aee3bc818f40f3c36a12175046544a21.jpg', 'https://phimimg.com/upload/vod/20231123-1/8a58f857e0a53d4ff39aed43a764adf7.jpg', '<p>Câu chuyện kể về Hal, một anh chàng trung bình về mọi mặt từ hình thức, tính tình cho đến công việc, cuộc sống Nhưng anh lại có cái nhìn rất cao về người bạn đời tương lai của mình đặc biệt là về mặt hình thức, dù thiếu chút, hụt chút cũng không được. Chuyện xảy ra khi Hal tình cờ gặp được một nhân vật đặc biệt tên Robbins trong một vụ kẹt thang máy. Đó là một chuyên gia tâm lý, một nhà ngoại cảm và cũng đồng thời là một “phù thủy”có khả năng thôi miên trong thế giới hiện đại. Vài giờ gặp gỡ, nói chuyện ngắn ngủi đó đã làm thay hoàn toàn cuộc sống của anh chàng béo Hal sau này. Những xung đột, mâu thuẫn đã ngầm xảy ra khi Hal gặp Rosemary và bị hút hồn ngay từ cái nhìn đầu tiên, chính điều đó đã khiến anh quyết phải chinh phục cho bằng được nàng.</p>', 'Full', 1, 'single', 'completed', 16, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gwyneth Paltrow","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Jason Alexander","avatar":""},{"name":"Joe Viterelli","avatar":""},{"name":"Rene Kirby","avatar":""},{"name":"Bruce McGill","avatar":""},{"name":"Tony Robbins","avatar":""},{"name":"Susan Ward","avatar":""},{"name":"Zen Gesner","avatar":""},{"name":"Brooke Burns","avatar":""},{"name":"Rob Moran","avatar":""},{"name":"Joshua ''Li''iBoy'' Shintani","avatar":""},{"name":"Kyle Gass","avatar":""},{"name":"Laura Kightlinger","avatar":""},{"name":"Nan Martin","avatar":""},{"name":"Sasha Joseph Neulinge","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324533);
