INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hal-nong-can', 'Hal Nông Cạn', 'Shallow Hal', 'hal nông cạn shallow hal gwyneth paltrow jack black jason alexander joe viterelli rene kirby bruce mcgill tony robbins susan ward zen gesner brooke burns rob moran joshua ''li''iboy'' shintani kyle gass laura kightlinger nan martin sasha joseph neulinge ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-hoi-cua-quy', 'Vũ Hội Của Quỷ', 'Monster''s Ball', 'https://phimimg.com/upload/vod/20231120-1/f02b836bfef7b671c568dd909d7a5a60.jpg', 'https://phimimg.com/upload/vod/20231120-1/ed7f9e96ef91b42de2cae5032b5b2e36.jpg', '<p>Người phụ nữ da màu Leticia có chồng bị kết án tử hình, con trai bị tai nạn qua đời đã đau khổ đến tuyệt vọng, nhưng cô một lần nữa hồi sinh và tiếp tục cuộc sống lạc quan với chính người đã hành quyết chồng mình. Hank Grotowski là một cai ngục, chuyên quản lý các tử tù. Nghề của ông được kế thừa từ người bố giờ đã già và đau yếu là ông Buck Grotowski và được truyền lại cho con trai Sonny Grotowski. Hai bố con ông làm tại một nhà tù địa phương với công việc chuẩn bị những chiếc ghế điện cho những phạm nhân bị tử hình.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Billy Bob Thornton","avatar":""},{"name":"Heath Ledger","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Sean Combs","avatar":""},{"name":"Yasiin Bey","avatar":""},{"name":"Will Rokos","avatar":""},{"name":"Milo Addica","avatar":""},{"name":"Coronji Calhoun","avatar":""},{"name":"Peter Boyle","avatar":""},{"name":"Taylor Simpson","avatar":""},{"name":"Gabrielle Witcher","avatar":""},{"name":"Amber Rules","avatar":""},{"name":"Charles Cowan Jr.","avatar":""},{"name":"Taylor LaGrange","avatar":""},{"name":"Anthony Bean","avatar":""},{"name":"Francine Segal","avatar":""},{"name":"John McConnell","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324533);
