INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('final-fantasy-linh-hon-trai-dat', 'Final Fantasy: Linh Hồn Trái Đất', 'Final Fantasy: The Spirits Within', 'https://phimimg.com/upload/vod/20231116-1/2d2e9b95bbda4d000c1ed6e0b4e2e460.jpg', 'https://phimimg.com/upload/vod/20231116-1/b96b272b197e9d2ff49f74a625da67f5.jpg', '<p>Năm 2065, Trái đất có nguy cơ bị hủy diệt. Một ngôi sao băng đã va chạm với hành tinh xanh mở đầu cho cuộc đổ bộ hàng triệu sinh vật ngoài vũ trụ xuống Trái đất. Những cánh đồng và thành phố bị tàn phá nặng nề bởi những kẻ dã thú. Chỉ còn lại thành phố New York với vài người sống sót qua thảm họa. Nhưng quân xâm lược đã bắt đầu tiến sát tới những thành phố rìa ngoài được xây dựng để bảo vệ những cư dân cuối cùng của Trái đất. Thời gian còn lại chẳng bao nhiêu, ngày tận thế càng đến gần.</p>', 'Full', 1, 'single', 'completed', 20, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ming-Na Wen","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Peri Gilpin","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"James Woods","avatar":""},{"name":"Keith David","avatar":""},{"name":"Jean Simmons","avatar":""},{"name":"Matt McKenzie","avatar":""},{"name":"John DeMita","avatar":""},{"name":"Matt Adler","avatar":""},{"name":"Steve Alterman","avatar":""},{"name":"David Arnott","avatar":""},{"name":"Cathy Cavadini","avatar":""},{"name":"Lanei Chapman","avatar":""},{"name":"Vicki Davis","avatar":""},{"name":"Judi M. Durand","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324533);
