INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-phe', 'Bao Phê', 'How High', 'https://phimimg.com/upload/vod/20231120-1/c59814dc698128f8955a35a5d31117a4.jpg', 'https://phimimg.com/upload/vod/20231120-1/6edcf2d707b7244f71422119a8499b2f.jpg', '<p>Các siêu sao nhạc rap đa bạch kim Redman và Method Man đóng vai Jamal và Silas, hai chàng trai bình thường hút thứ gì đó kỳ diệu, vượt qua kỳ thi tuyển sinh đại học và tốt nghiệp Harvard. Cách thức của Ivy League thật kỳ lạ nhưng Silas và Jamal vẫn tiếp tục cố gắng -- cho đến khi nguồn cung cấp khói siêu nhiên của họ cạn kiệt. Đó là khi họ phải bắt đầu sống bằng trí thông minh của mình và dựa vào tài nguyên thiên nhiên của mình để đạt được thành tích.</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Method Man","avatar":""},{"name":"Redman","avatar":""},{"name":"Obba Babatundé","avatar":""},{"name":"Mike Epps","avatar":""},{"name":"Anna Maria Horsford","avatar":""},{"name":"Fred Willard","avatar":""},{"name":"Jeffrey Jones","avatar":""},{"name":"Héctor Elizondo","avatar":""},{"name":"Lark Voorhies","avatar":""},{"name":"Essence Atkins","avatar":""},{"name":"Al Shearer","avatar":""},{"name":"Chris Elwood","avatar":""},{"name":"T.J. Thyne","avatar":""},{"name":"Justin Urich","avatar":""},{"name":"Dennison Samaroo","avatar":""},{"name":"Tracey Walter","avatar":""},{"name":"Spalding Gray","avatar":""},{"name":"Amber Smit","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324533);
