INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sex-and-lucia', 'Sex and Lucía', 'Sex and Lucía', 'https://phimimg.com/upload/vod/20231116-1/763979f60dca54992754acb2536ec6fd.jpg', 'https://phimimg.com/upload/vod/20231116-1/bc474c86c423ab638a2132761ced0546.jpg', '<p>Nhiều cuộc sống khác nhau hội tụ trên một hòn đảo biệt lập, tất cả được kết nối bởi một tác giả có cuốn tiểu thuyết đã trở nên gắn bó chặt chẽ với cuộc sống của chính mình.</p>', 'Full', 1, 'single', 'completed', 21, 2001, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Paz Vega","avatar":""},{"name":"Tristán Ulloa","avatar":""},{"name":"Elena Anaya","avatar":""},{"name":"Najwa Nimri","avatar":""},{"name":"Daniel Freire","avatar":""},{"name":"Silvia Llanos","avatar":""},{"name":"Diana Suárez","avatar":""},{"name":"Javier Cámara","avatar":""},{"name":"Juan Fernández","avatar":""},{"name":"María Álvarez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324533);
