INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-toi-la-gangster', 'Vợ Tôi Là Gangster', 'My Wife Is A Gangster', 'https://phimimg.com/upload/vod/20231113-1/46d7de9694768aecb7199952e19e2eef.jpg', 'https://phimimg.com/upload/vod/20231113-1/16d05e871c215c0dfc096f45e9d998d9.jpg', '<p>Eunjin, một huyền thoại sống trong giới xã hội đen thống trị thế giới ngầm lấy nam giới làm trung tâm chỉ sử dụng một đôi thanh kiếm đặc trưng của mình. Một ngày nọ, Eun-jin tìm thấy em gái mà cô đã bị chia cắt từ một trại trẻ mồ côi trong thời thơ ấu, và chị gái của cô ấy nói với Eun-jin rằng ước muốn cuối cùng của cô ấy là được thấy Eun-jin kết hôn.</p>', 'Full', 1, 'single', 'completed', 16, 2001, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Shin Eun-kyung","avatar":""},{"name":"Park Sang-myeon","avatar":""},{"name":"Ahn Jae-mo","avatar":""},{"name":"Kim In-kwon","avatar":""},{"name":"Jang Se-jin","avatar":""},{"name":"Shim Won-cheol","avatar":""},{"name":"Yeon Jeong-hun","avatar":""},{"name":"Choi Eun-ju","avatar":""},{"name":"Kang Sung-pil","avatar":""},{"name":"Ko Joo-yeon","avatar":""},{"name":"Choi Min-soo","avatar":""},{"name":"Lee Eung-kyeong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324533);
