INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-cua-rong', 'Nụ Hôn Của Rồng', 'Kiss of the Dragon', 'https://phimimg.com/upload/vod/20231113-1/cc703ddee9a4cf12dffba9ce12f8e214.jpg', 'https://phimimg.com/upload/vod/20231113-1/a230e09f4c57f037f86e5b3e97276f00.jpg', '<p>Kiss Of The Dragon là bộ phim võ thuật xoay quanh nhân vật Liu Siu –Jian, một mật vụ Trung quốc được cử đến Paris hỗ trợ kế hoạch vây bắt tay trùm ma túy gốc Hoa có biệt danh là Mr.Big. Không may mắn Siu-jian bị chính tên thanh tra Jean-Pierre Richard hãm hại bằng việc gán cho anh tội giết người . Siu-jian tìm cách trốn thoát, dưới sự giúp đỡ của cô gái điếm Jessica với điều kiện anh phải giúp cô giải cứu con gái , cuối cùng Siu-jian quyết định đơn thương độc mã tới đồn cảnh sát để cứu con gái Jessica và trừng trị Jean-Pierre.....</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jet Li","avatar":""},{"name":"Bridget Fonda","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"Max Ryan","avatar":""},{"name":"Ric Young","avatar":""},{"name":"Burt Kwouk","avatar":""},{"name":"Laurence Ashley","avatar":""},{"name":"Cyril Raffaelli","avatar":""},{"name":"Didier Azoulay","avatar":""},{"name":"John Forgeham","avatar":""},{"name":"Paul Barrett","avatar":""},{"name":"Kentaro","avatar":""},{"name":"Colin Prince","avatar":""},{"name":"Vincent Glo","avatar":""},{"name":"Vincent Wong","avatar":""},{"name":"Claude Brécourt","avatar":""},{"name":"Frédéric Moulin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
