INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-mot-ten-cuop-the-ky', 'Mười Một Tên Cướp Thế Kỷ', 'Ocean''s Eleven', 'https://phimimg.com/upload/vod/20231114-1/39ff80419414dc91691127b4e81d7ea4.jpg', 'https://phimimg.com/upload/vod/20231114-1/6232bb555cfada5d47878878762fb0f1.jpg', '<p>Danny Ocean - một tay anh chị vừa ra tù đã tập hợp những tay chuyên nghiệp từ khắp các tiểu bang hòng thực hiện một phi vụ béo bở và táo bạo nhất lịch sử cướp tiền ở Las Vegas : đánh cướp 3 sòng bài lớn nhất Las Vegas trong cùng 1 đêm. Liệu họ có thực hiện được không ? Tất cả 11 người đó sẽ thực hiện phi vụ này ra sao ?</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Andy García","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Casey Affleck","avatar":""},{"name":"Scott Caan","avatar":""},{"name":"Elliott Gould","avatar":""},{"name":"Eddie Jemison","avatar":""},{"name":"Bernie Mac","avatar":""},{"name":"Shaobo Qin","avatar":""},{"name":"Carl Reiner","avatar":""},{"name":"Cecelia Ann Birt","avatar":""},{"name":"Paul L. Nolan","avatar":""},{"name":"Carol Florence","avatar":""},{"name":"Lori Galinski","avatar":""},{"name":"Mark Gantt","avatar":""},{"name":"Tim Perez","avatar":""},{"name":"Frank P","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324533);
