INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-vo-diem', 'Chung Vô Diệm', 'Wu Yen', 'https://phimimg.com/upload/vod/20231112-1/dc8e3f6bf488286eb2c38dda1d3abc11.jpg', 'https://phimimg.com/upload/vod/20231112-1/2e468f78b3c7d1bdd891d3e5e0548304.jpg', '<p>Tề Tuyên Vương là người đã có hôn ước trời ban với Chung Vô Diệm nhưng hắn là một kẻ tham sống sợ chết, có mới nới cũ, vô dụng bất tài hèn hạ ... nói chung là nơi hội tụ của tất cả những tật xấu trên đời. Trong một lần tình cờ Tề Tuyên Vương và Chung Vô Diệm đã gặp nhau và cùng giải thoát cho con Hồ Ly Tinh sau này hóa thân thành Hạ Nghênh Xuân. Hạ Nghênh Xuân muốn chiêu dụ Tề Tuyên Vương để cho Chung Vô Diệm trở nên chán ghét hắn, sau đó sẽ đoạt được mỹ nhân nhưng không ngờ chính bản thân mình cũng bị rơi vào lưới tình.</p>', 'Full', 1, 'single', 'completed', 16, 2001, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammi Cheng","avatar":""},{"name":"Anita Mui","avatar":""},{"name":"Cecilia Cheung Pak-Chi","avatar":""},{"name":"Raymond Wong Ho-Yin","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Lung Tin-Sang","avatar":""},{"name":"Hung Wai-Leung","avatar":""},{"name":"Cheng Ka-Sang","avatar":""},{"name":"Wong Chun","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Ai Wai","avatar":""},{"name":"Joe Cheng","avatar":""},{"name":"Cheung Chi-Ping","avatar":""},{"name":"Wong Tin-Lam","avatar":""},{"name":"Bonnie Wong","avatar":""},{"name":"Robert Siu Leung","avatar":""},{"name":"Cheuk Wai-Man","avatar":""},{"name":"Tiffany L","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324533);
