INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('13-oan-hon', '13 Oan Hồn', 'Thir13en Ghosts', 'https://phimimg.com/upload/vod/20231111-1/cdf7cc80f3142752917628ac69ebe487.jpg', 'https://phimimg.com/upload/vod/20231111-1/713462538eff6bfd78a1a38d2a39561c.jpg', '<p>Sau khi thừa kế một biệt thự bí ẩn từ chú Cyrus kỳ cục của mình, Arthur Kriticos và gia đình phát hiện ra rằng căn nhà này là nơi giam giữ 13 linh hồn hung dữ, bị một thợ săn ma kinh nghiệm đóng kín. Khi những linh hồn tối tăm này được thả ra, gia đình Kriticos bị mắc kẹt trong một mê cung kinh dị siêu nhiên. Với sự giúp đỡ của một người nhìn thấu và một chuyên gia về hiện tượng siêu nhiên, họ phải giải mã những bí mật của ngôi nhà để lại giam giữ những hồn ma. Đối mặt với những nỗi sợ khó tưởng, họ chiến đấu để sống sót và bảo vệ lẫn nhau khỏi 13 hồn ma tìm kiếm sự trả thù và sự giải thoát vĩnh hằng.</p>', 'Full', 1, 'single', 'completed', 16, 2001, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Tony Shalhoub","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"Matthew Lillard","avatar":""},{"name":"Shannon Elizabeth","avatar":""},{"name":"Rah Digga","avatar":""},{"name":"Alec Roberts","avatar":""},{"name":"JR Bourne","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"Matthew Harrison","avatar":""},{"name":"Charles Andre","avatar":""},{"name":"Laura Mennell","avatar":""},{"name":"Kathryn Anderson","avatar":""},{"name":"Craig Olejnik","avatar":""},{"name":"Shawna Loyer","avatar":""},{"name":"Xantha Radley","avatar":""},{"name":"C. Ernst Harth","avatar":""},{"name":"John De","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
