INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-ngan-dam-xa', 'Vượt Ngàn Dặm Xa', 'As Far As My Feet Will Carry Me', 'https://phimimg.com/upload/vod/20231111-1/a36821fa21eb4bcc031dccc7d82ee585.jpg', 'https://phimimg.com/upload/vod/20231111-1/ed9ab5a87415611895414e97e04cb5ac.jpg', '<p>Người lính Đức Clemens Forel - quyết tâm đoàn tụ với gia đình thân yêu của mình - đã thực hiện một cuộc trốn thoát đầy kịch tính qua mùa đông lạnh giá, phong cảnh hoang vắng và những cuộc phiêu lưu nguy hiểm đến tính mạng từ một trại lao động ở Siberia sau Thế chiến II. 8000 dặm và ba năm vô tận của sự không chắc chắn sau đó, cuối cùng anh ấy cũng sắp đến được đích của mình... Một bộ phim truyền hình về chỗ ngồi của bạn tôn vinh sức mạnh của tinh thần con người và sức mạnh của ý chí, đồng thời được truyền cảm hứng và sức mạnh bởi tình yêu.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Bernhard Bettermann","avatar":""},{"name":"Michael Mendl","avatar":""},{"name":"Anatoliy Kotenyov","avatar":""},{"name":"André Hennicke","avatar":""},{"name":"Hans Peter Hallwachs","avatar":""},{"name":"Hans-Uwe Bauer","avatar":""},{"name":"Antonio Wannek","avatar":""},{"name":"Irina Narbekova","avatar":""},{"name":"Pavel Lebeshev","avatar":""},{"name":"Aleksandr Efremov","avatar":""},{"name":"Heinrich Giskes","avatar":""},{"name":"Eva-Maria Kurz","avatar":""},{"name":"Irina Pantaeva","avatar":""},{"name":"Iris Böhm","avatar":""},{"name":"Johannes Hitzblech","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324533);
