INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vuot-ngan-dam-xa', 'Vượt Ngàn Dặm Xa', 'As Far As My Feet Will Carry Me', 'vượt ngàn dặm xa as far as my feet will carry me bernhard bettermann michael mendl anatoliy kotenyov andré hennicke hans peter hallwachs hans-uwe bauer antonio wannek irina narbekova pavel lebeshev aleksandr efremov heinrich giskes eva-maria kurz irina pantaeva iris böhm johannes hitzblech ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-vao-tuong-lai', 'Lạc Vào Tương Lai', 'Just Visiting', 'https://phimimg.com/upload/vod/20231109-1/59ccf62f7888f9bbde2c69ac258603f7.jpg', 'https://phimimg.com/upload/vod/20231109-1/5aab34fedff2aa508023fb5ebf092516.jpg', '<p>Một hiệp sĩ và người hầu của anh ta bị phù thủy quấy nhiễu, và để sửa chữa những thiệt hại, họ sử dụng dịch vụ của một phù thủy. Tuy nhiên, đã xảy ra sự cố và họ bị dịch chuyển từ thế kỷ 12 đến năm 2000. Ở đó, hiệp sĩ gặp một số người trong gia đình mình và dần dần biết được thế kỷ mới này như thế nào. Tuy nhiên, anh ta vẫn cần quay trở lại thế kỷ 12 để đối phó với phù thủy, vì vậy anh ta bắt đầu tìm kiếm một phù thủy. Làm lại từ bộ phim Pháp năm 1993 Les Visiteurs (Những vị khách).</p>', 'Full', 1, 'single', 'completed', 16, 2001, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean Reno","avatar":""},{"name":"Christian Clavier","avatar":""},{"name":"Christina Applegate","avatar":""},{"name":"Matt Ross","avatar":""},{"name":"Tara Reid","avatar":""},{"name":"Bridgette Wilson-Sampras","avatar":""},{"name":"John Aylward","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"George Plimpton","avatar":""},{"name":"Sarah Badel","avatar":""},{"name":"Kendra Torgan","avatar":""},{"name":"Lucy Blair","avatar":""},{"name":"Darryl Henriques","avatar":""},{"name":"Tab Baker","avatar":""},{"name":"Ellie Weingardt","avatar":""},{"name":"Eric Aviles","avatar":""},{"name":"Bill Bai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c14