INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-thu-y-2', 'Bác Sĩ Thú Y 2', 'Dr. Dolittle 2', 'https://phimimg.com/upload/vod/20231108-1/fcb15366ffe3a210f32da0797cb130bb.jpg', 'https://phimimg.com/upload/vod/20231108-1/08f4317ea6fd8718abe8a1403f4dad16.jpg', '<p>Bác sỹ John Dolittle, vị bác sỹ thú y được yêu mến, đã trở lại màn ảnh. Nhưng lần này nhiệm vụ của anh là trở thành thần tình yêu của chú gấu trong sở thú Archie, bởi chú đã &quot;rung rinh&quot; trước nàng gấu Ava. Anh phải dạy cho Archie những rung động thật sự để giữ lấy tình yêu của mình.</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Kristen Wilson","avatar":""},{"name":"Kyla Pratt","avatar":""},{"name":"Raven-Symoné","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"James Avery","avatar":""},{"name":"Andy Richter","avatar":""},{"name":"Lil'' Zane","avatar":""},{"name":"Denise Dowse","avatar":""},{"name":"Elayn J. Taylor","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Victor Raider-Wexler","avatar":""},{"name":"Jeffrey Jones","avatar":""},{"name":"Mark Griffin","avatar":""},{"name":"Ken Hudson Campbell","avatar":""},{"name":"Anne Stedman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324533);
