INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-si-thu-y-2', 'Bác Sĩ Thú Y 2', 'Dr. Dolittle 2', 'bác sĩ thú y 2 dr. dolittle 2 eddie murphy kristen wilson kyla pratt raven-symoné steve zahn lisa kudrow james avery andy richter lil'' zane denise dowse elayn j. taylor kevin pollak victor raider-wexler jeffrey jones mark griffin ken hudson campbell anne stedman ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-bat-dac-di-2001', 'Điệp Viên Bất Đắc Dĩ', 'The Accidental Spy', 'https://phimimg.com/upload/vod/20231108-1/4d33b8a56a031d8015f6956b8f3e08df.jpg', 'https://phimimg.com/upload/vod/20231108-1/ada59c73208236a8c6ef3b19a9204e2c.jpg', '<p>Buck Yuen (Jackie Chan) đột nhiên phát hiện ra mình là con trai của một điệp viên người Hàn Quốc. Trước khi lâm chung, ông này có để lại cho đứa con thất lạc lâu năm một gia tài kếch xù. Để giành lại đống của cải đó, Buck khăn gói lên đường sang Thổ Nhĩ Kỳ. Nhưng mọi chuyện lại không theo đúng như kế hoạch anh đã vạch ra. Buck đã tìm ra số tiền thừa kế anh được hưởng nhưng rất nhiều phe phái đã xúm vào tra hỏi anh về những thứ khác mà anh không hề hay biết. Trong số những kẻ tham gia trò chơi “mèo đuổi chuột” cứ bám riết lấy anh chàng người Hoa ngốc nghếch, có một tay trùm xã hội đen Wu Xing-Guo luôn kè kè bên cạnh cô gái điếm tội nghiệp của hắn . Gói hàng bị mất thực chất là một loại virus nguy hiểm chết người mang tên Anthrax II. Rất nhiều kẻ muốn chiếm được chủng virus gây ung thư phổi này nhằm sử dụng như một thứ vũ khí sinh học lợi hại hòng gây áp lực trong chiến tranh. Trong tình huống căng thẳng như vậy, liệu một anh chàng dân đen như Buck có thể làm được gì?</p>', 'Full', 1, 'single', 'completed', 21, 2001, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Vivian Hsu","avatar":""},{"name":"Wu Hsing-Guo","avatar":""},{"name":"Min Kim","avatar":""},{"name":"Alfred Cheung Kin-Ting","avatar":""},{"name":"Lillian Ho","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Poon Hang-Sang","avatar":""},{"name":"Paulyn Sun","avatar":""},{"name":"Vincent Kok","avatar":""},{"name":"Teresa Ha Ping","avatar":""},{"name":"Joh Young-Kwon","avatar":""},{"name":"Anthony Rene Jones","avatar":""},{"name":"Murat Yılmaz","avatar":""},{"name":"Taner Barlas","avatar":""},{"name":"Yıldırım Öcek","avatar":""},{"name":"Figen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
