INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-bong-bong', 'Chàng Trai Bong Bóng', 'Bubble Boy', 'https://phimimg.com/upload/vod/20231108-1/c5c6067a2bd87242b8394fac88ddc7f3.jpg', 'https://phimimg.com/upload/vod/20231108-1/39efb3c71affadad1a71f6225c82a6c7.jpg', '<p>Jimmy là một chàng trai trẻ sinh ra đã không có hệ thống miễn dịch và đã sống cuộc đời của mình trong một chiếc bong bóng nhựa trong phòng ngủ của mình... người khao khát những cái vuốt ve ngọt ngào của cô gái hàng xóm Chloe. Nhưng khi Chloe quyết định kết hôn với bạn trai thời trung học của mình, Jimmy – bộ đồ bong bóng và tất cả – đã đi xuyên quốc gia để ngăn cản cô.</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Swoosie Kurtz","avatar":""},{"name":"Marley Shelton","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Verne Troyer","avatar":""},{"name":"Dave Sheridan","avatar":""},{"name":"Brian George","avatar":""},{"name":"Patrick Cranshaw","avatar":""},{"name":"Stephen Spinella","avatar":""},{"name":"Ever Carradine","avatar":""},{"name":"Geoffrey Arend","avatar":""},{"name":"Beetlejuice","avatar":""},{"name":"Matthew McGrory","avatar":""},{"name":"Bonnie Morgan","avatar":""},{"name":"Jason Sklar","avatar":""},{"name":"Randy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324533);
