INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-de', 'Tiêu đề', 'Headlines', 'https://phimimg.com/upload/vod/20231114-1/dd1e5e477c8b4f744f4996654da136b4.jpg', 'https://phimimg.com/upload/vod/20231114-1/7eb2082da254378ca0d2648a24cbc776.jpg', '<p>Một phóng viên tân binh đang cố gắng khắc phục tình trạng thiếu kinh nghiệm của mình. Một phóng viên kiên định đang cố gắng tìm kiếm những điều tốt đẹp ở con người, và sẵn sàng tha thứ và quên đi những lời xúc phạm trong công việc của cô ấy. Một phóng viên trung niên sử dụng mối liên hệ của mình thông qua nhiều văn phòng cấp cao hơn để làm cho câu chuyện của anh ấy trở nên tổng hợp. Đối phó với báo chí hiện đại, bộ phim cố gắng thực hiện công lý cho cả hai phía của ngành báo chí. Một mặt, các phóng viên đang cố gắng làm tốt công việc đưa tin, và một số khác, đưa ra giải pháp cho các vấn đề. Mặt khác, &quot;nạn nhân &quot; của các phóng viên, những người tin rằng họ có quyền riêng tư, đang ngăn cản các phóng viên thực hiện công việc của họ.</p>', 'Full', 1, 'single', 'completed', 15, 2001, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Wakin Chau","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Maggie Cheung Hoh-Yee","avatar":""},{"name":"Grace Yip","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""},{"name":"Simon Lui Yu-Yeung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
