INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-xua-ngay-xua-o-an-do', 'Ngày Xửa Ngày Xưa Ở Ấn Độ', 'Lagaan: Once Upon a Time in India', 'https://phimimg.com/upload/vod/20231106-1/7af1245a6229e00ed6a7d1fd6af40243.jpg', 'https://phimimg.com/upload/vod/20231106-1/508cc348ac351e18f229d125e7c3e84b.jpg', '<p>Vào những năm 1890 ở Ấn Độ, một chỉ huy người Anh kiêu ngạo thách thức những cư dân bị đánh thuế nặng nề của Champaner tham gia một trận đấu cricket có tỷ lệ cược cao.</p>', 'Full', 1, 'single', 'completed', 16, 2001, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Aamir Khan","avatar":""},{"name":"Gracy Singh","avatar":""},{"name":"Rachel Shelley","avatar":""},{"name":"Paul Blackthorne","avatar":""},{"name":"Kulbhushan Kharbanda","avatar":""},{"name":"Suhasini Mulay","avatar":""},{"name":"Yashpal Sharma","avatar":""},{"name":"Raj Zutshi","avatar":""},{"name":"Rajendra Gupta","avatar":""},{"name":"Akhilendra Mishra","avatar":""},{"name":"Raghubir Yadav","avatar":""},{"name":"Javed Khan","avatar":""},{"name":"Daya Shankar Pandey","avatar":""},{"name":"A.K. Hangal","avatar":""},{"name":"Pradeep Ram Singh Rawat","avatar":""},{"name":"Aditya L","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324533);
