INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-noi-ra', 'Không Nói Ra', 'The Unsaid', 'https://phimimg.com/upload/vod/20231112-1/69d003cb5f94c5707e90fc8f3c35f7e6.jpg', 'https://phimimg.com/upload/vod/20231112-1/8db01f26f9b902a2f7a801300c6fe4ab.jpg', '<p>Bộ phim kể về cuộc đấu tranh của Michael Hunter đối phó với việc tự tử của con trai và Thomas Caffey - một bác sĩ tâm thần nỗ lực phục hồi quá khứ khủng khiếp cho con trai ông.</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Andy García","avatar":""},{"name":"Chelsea Field","avatar":""},{"name":"Vincent Kartheiser","avatar":""},{"name":"Linda Cardellini","avatar":""},{"name":"Teri Polo","avatar":""},{"name":"Trevor Blumas","avatar":""},{"name":"David Millbern","avatar":""},{"name":"Brendan Fletcher","avatar":""},{"name":"Sam Bottoms","avatar":""},{"name":"Sarah Deakins","avatar":""},{"name":"August Schellenberg","avatar":""},{"name":"Kim Schraner","avatar":""},{"name":"Alexandra Staseson","avatar":""},{"name":"Amy Matysio","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
