INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('digimon-tamers-tran-chien-cua-cac-mao-hiem-gia', 'Digimon Tamers: Trận Chiến Của Các Mạo Hiểm Giả!', 'Digimon Tamers: Boukensha-tachi no Tatakai Digimon Tamers: Battle of Adventurers', 'https://phimimg.com/upload/vod/20231103-1/51e1235cb64ef204f66222b1fae6ff41.jpg', 'https://phimimg.com/upload/vod/20231103-1/45605d29bbc23236ba8719d435a29302.jpg', '<p>Takato và Guilmon đi nghỉ ở Okinawa và gặp Minami. Quay trở lại Nhật Bản, một thú cưng máy tính bỗng nhiên trở thành một loại vi-rút, lây nhiễm cho tất cả các máy tính. Khi virus lây lan, Takato cố gắng tìm ra nguyên nhân tại sao các Digimon lại tấn công người bạn mới của mình và mối liên hệ của cô với virus là gì.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2001, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Fumiko Orikasa","avatar":""},{"name":"Makoto Tsumura","avatar":""},{"name":"Mayumi Yamaguchi","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Yoko Asada","avatar":""},{"name":"Tomo Saeki","avatar":""},{"name":"Masako Nozawa","avatar":""},{"name":"Tomoko Kaneda","avatar":""},{"name":"Yuka Imai","avatar":""},{"name":"Aoi Tada","avatar":""},{"name":"Chika Sakamoto","avatar":""},{"name":"Mayumi Yamaguchi","avatar":""},{"name":"Nobuaki Kanemitsu","avatar":""},{"name":"Kaya Matsutani","avatar":""},{"name":"Ai Nagano","avatar":""},{"name":"Kyousei Tsukui","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324533);
