INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phao-dai-cuoi-cung', 'Pháo Đài Cuối Cùng', 'The Last Castle', 'https://phimimg.com/upload/vod/20231103-1/6c050d58619fca9bba6e6a00707bc3ea.jpg', 'https://phimimg.com/upload/vod/20231103-1/6c91d4612ec0416c1b36edc21d04d0c5.jpg', '<p>Sau một phiên xét xử chóng vánh của tòa án binh, đại tướng Eugene Irwin, một trong những chỉ huy mặt trận có nhiều chiến công hiển hách, bị tước quân tịch. Người ta đưa ông vào một trong những nhà tù có chế độ bảo vệ nghiêm ngặt nhất của quân đội. Đại tá Winter, quản lý cấp cao nhất của nhà tù, rất ngưỡng mộ Eugene vì những chiến công hiển hách của ông. Tuy nhiên, chứng kiến những vi phạm có hệ thống của Giám thị trại giam, nhằm chà đạp lòng tự trọng của tù nhân, vốn đều là cựu chiến binh, Eugene đã lãnh đạo tù nhân nổi loạn.</p>', 'Full', 1, 'single', 'completed', 16, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Redford","avatar":""},{"name":"James Gandolfini","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Delroy Lindo","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Kristen Shaw","avatar":""},{"name":"Paul Calderon","avatar":""},{"name":"Brian Goodman","avatar":""},{"name":"Steve Burton","avatar":""},{"name":"Sam Ball","avatar":""},{"name":"Jeremy Childs","avatar":""},{"name":"George W. Scott","avatar":""},{"name":"Steve Sandfort","avatar":""},{"name":"Michael Irby","avatar":""},{"name":"Frank Military","avatar":""},{"name":"Nick Kokich","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533)