INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('15-phut', '15 phút', '15 Minutes', 'https://phimimg.com/upload/vod/20231101-1/1160ab360af84d0c2ec745a81b22cc06.jpg', 'https://phimimg.com/upload/vod/20231101-1/7357b977ef0710456421fbdb345da198.jpg', '<p>Một số người Nga đến New York cứ nghĩ rằng tại đây làm tội phạm thì rất nhanh nổi tiếng, và họ đã thực hiện một kế hoạch trộm máy quay, lấy những thông tin độc và bán cho giới truyền thông. Nhưng họ cũng không ngờ rằng họ đã đụng độ với cảnh sát điều tra. Rồi một âm mưu khác lại nảy sinh trong đầu của họ, từ đây phim với những pha hành động vô cùng mạo hiểm, một cuộc đối đầu giữa những tên cướp người Nga và viên cảnh sát tài ba...</p>', 'Full', 1, 'single', 'completed', 20, 2001, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Edward Burns","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Avery Brooks","avatar":""},{"name":"Melina Kanakaredes","avatar":""},{"name":"Karel Roden","avatar":""},{"name":"Oleg Taktarov","avatar":""},{"name":"Vera Farmiga","avatar":""},{"name":"John DiResta","avatar":""},{"name":"James Handy","avatar":""},{"name":"Darius McCrary","avatar":""},{"name":"Bruce Cutler","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Kim Cattrall","avatar":""},{"name":"David Alan Grier","avatar":""},{"name":"Vladimir Mashkov","avatar":""},{"name":"Arina Gas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
