INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-da-mat', 'Thế Giới Đã Mất', 'Lost Worlds: Life in the Balance', 'https://phimimg.com/upload/vod/20231101-1/d990e886f03a9a810986b0cb3a13a4a6.jpg', 'https://phimimg.com/upload/vod/20231101-1/a2e779dfcd663378c5a48c74d9120df7.jpg', '<p>Lost Worlds xem xét các khía cạnh hoang sơ của thiên nhiên ở những nơi trên thế giới mà con người hiếm khi đặt chân tới. Từ thực vật, động vật, đến địa chất, bộ phim tài liệu được chụp ảnh nghệ thuật này thể hiện các khía cạnh của thế giới sinh vật mà bạn khó có thể thấy ở bất kỳ nơi nào khác.</p>', 'Full', 1, 'single', 'completed', 20, 2001, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Harrison Ford","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324533);
