INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-ao-mong', 'Con Đường Ảo Mộng', 'Mulholland Drive', 'https://phimimg.com/upload/vod/20231029-1/9fa34d7f6a7772b269f24f1bde4cb3de.jpg', 'https://phimimg.com/upload/vod/20231029-1/6e361df0d8753b4f5af9c25aebb2b354.jpg', '<p>Một vụ tai nạn thảm khốc đã diễn ra. Hai tài xế chết ngay tại chỗ còn người phụ nữ ngồi đằng sau bị chấn thương mạnh. Khi tỉnh dậy, cô không thể nhớ được điều gì. Cô đi một cách vô định cho tới khi dừng trước một ngôi nhà khang trang. Sáng hôm sau, thừa lúc chủ nhân ngôi nhà di chuyển đồ đạc đi nơi khác, cô lẻn vào bên trong...</p>', 'Full', 1, 'single', 'completed', 19, 2001, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Naomi Watts","avatar":""},{"name":"Laura Harring","avatar":""},{"name":"Justin Theroux","avatar":""},{"name":"Ann Miller","avatar":""},{"name":"Mark Pellegrino","avatar":""},{"name":"Robert Forster","avatar":""},{"name":"Brent Briscoe","avatar":""},{"name":"Dan Hedaya","avatar":""},{"name":"Angelo Badalamenti","avatar":""},{"name":"Monty Montgomery","avatar":""},{"name":"Lee Grant","avatar":""},{"name":"James Karen","avatar":""},{"name":"Chad Everett","avatar":""},{"name":"Richard Green","avatar":""},{"name":"Rebekah Del Rio","avatar":""},{"name":"Melissa George","avatar":""},{"name":"Jeanne Bates","avatar":""},{"name":"D","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324533);
