INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ma-ca-kiem', 'Mật Mã Cá Kiếm', 'Swordfish', 'https://phimimg.com/upload/vod/20231030-1/74e263649546782f1c9e80b0b9edd60a.jpg', 'https://phimimg.com/upload/vod/20231030-1/eb4d190705325a21a447f5c2af067616.jpg', '<p>Đặc vụ lừa đảo Gabriel Shear quyết tâm lấy được số tiền 9 tỷ USD được giấu trong một tài khoản bí mật của Cục Quản lý Thực thi Ma túy. Anh ta muốn có tiền để chống khủng bố, nhưng lại thiếu kỹ năng máy tính cần thiết để đột nhập vào máy tính lớn của chính phủ. Nhập Stanley Jobson, một chuyên gia mã hóa giỏi, người có thể đăng nhập vào bất cứ thứ gì.</p>', 'Full', 1, 'single', 'completed', 19, 2001, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"John Travolta","avatar":""},{"name":"Hugh Jackman","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Sam Shepard","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Drea de Matteo","avatar":""},{"name":"Jason Christopher","avatar":""},{"name":"Zach Grenier","avatar":""},{"name":"Rudolf Martin","avatar":""},{"name":"Camryn Grimes","avatar":""},{"name":"Angelo Pagan","avatar":""},{"name":"Chic Daniel","avatar":""},{"name":"Kirk B.R. Woller","avatar":""},{"name":"Carmen Argenziano","avatar":""},{"name":"Tim DeKay","avatar":""},{"name":"Laura Lane","avatar":""},{"name":"Tait Ru","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324533);
