INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-cua-amelie-poulain', 'Cuộc Đời Của Amelie Poulain', 'Amélie', 'https://phimimg.com/upload/vod/20231026-1/f39642e21eaaa330235901dcf517510a.jpg', 'https://phimimg.com/upload/vod/20231026-1/c4a6ea83c0e105522f78d360bdc4c317.jpg', '<p>Cuộc Đời Của Amelie Poulain: Làm hầu bàn trong quán cà phê Hai Cối Xay Gió ở Paris, Amelie Poulain (Audrey Tatou) là một trong nhiều cô gái trẻ độc thân, nhút nhát, ít bạn và không phải người mẫu mà các đạo diễn tìm kiếm. Nhưng tiềm ẩn trong cô gái 23 tuổi này là lòng kính Chúa, sự cần cù siêng năng, thông minh và một người tình tuyệt vời. Khi còn là một cô bé ngây thơ, Amelie có một cuộc sống thanh bình nếu không muốn nói là khá tẻ nhạt ở thủ đô Paris. Ngày bé do bố cô chuẩn đoán nhầm cô bị bệnh tim nên cô không được đến trường, chỉ quanh quẩn tự học ở nhà và chơi cùng mấy con rối nhỏ. Lớn lên giữa môi trường không có bạn bè, Amelie có phần cô độc và nhút nhát với thế giới bên ngoài. Thế rồi một ngày kia, Amelie khám phá ra chiếc hộp đồng nhỏ ẩn ...</p>', 'Full', 1, 'single', 'completed', 18, 2001, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Audrey Tautou","avatar":""},{"name":"Mathieu Kassovitz","avatar":""},{"name":"Rufus","avatar":""},{"name":"Lorella Cravotta","avatar":""},{"name":"Serge Merlin","avatar":""},{"name":"Jamel Debbouze","avatar":""},{"name":"Clotilde Mollet","avatar":""},{"name":"Claire Maurier","avatar":""},{"name":"Isabelle Nanty","avatar":""},{"name":"Dominique Pinon","avatar":""},{"name":"Artus de Penguern","avatar":""},{"name":"Yolande Moreau","avatar":""},{"name":"Urbain Cancelier","avatar":""},{"name":"Maurice Bénichou","avatar":""},{"name":"Michel Robin","avatar":""},{"name":"Andrée Damant","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324534);
