INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thu-truoc-cong', 'Kẻ Thù Trước Cổng', 'Enemy at the Gates', 'https://phimimg.com/upload/vod/20231026-1/063d7ce82120f467b815bdaf1f7f1057.jpg', 'https://phimimg.com/upload/vod/20231026-1/641fa7d33d9c3c7410f71484de3b07b6.jpg', '<p>Vassili được ông mình dạy bắn súng từ nhỏ. Lớn lên, anh ta tham gia vào quân đội Hồng Quân Liên Xô trong thế chiến thứ 2. Chính vì khả năng bắn súng tuyệt vời của mình mà anh đã gây nên một hiện tượng cho cả nước Xô Viết và anh được chọn vào đội ngũ bắn tỉa tại Stallingrad... Trận đông chiến ở Stallingrad bấy giờ có vẻ thế trận nghiêng về phía Đức thế nên một vị anh hùng như Vassili là nguồn động viên tinh thần của toàn quân Liên Xô . Chính vì thế, quân Đức đã phải điều động xạ thủ giỏi nhất nước Đức bấy giờ để truy tìm và triệt hạ anh.</p>', 'Full', 1, 'single', 'completed', 20, 2001, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jude Law","avatar":""},{"name":"Joseph Fiennes","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Bob Hoskins","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Eva Mattes","avatar":""},{"name":"Gabriel Thomson","avatar":""},{"name":"Matthias Habich","avatar":""},{"name":"Alexander Schwan","avatar":""},{"name":"Lenn Kudrjawizki","avatar":""},{"name":"Gennadi Vengerov","avatar":""},{"name":"Dan van Husen","avatar":""},{"name":"Ivan Shvedoff","avatar":""},{"name":"Sophie Rois","avatar":""},{"name":"Mario Bandi","avatar":""},{"name":"Hans Martin Stier","avatar":""},{"name":"Cle","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324534);
