INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-tu-kieu-my-2', 'Đoàn Tụ Kiểu Mỹ 2', 'American Pie 2', 'https://phimimg.com/upload/vod/20231024-1/cdb1cbf86444a5afbf8dec0e4698aa26.jpg', 'https://phimimg.com/upload/vod/20231024-1/9e45af16731a6fb3af1147ffadc8f65c.jpg', '<p>Sau năm đầu tiên ở trường đại học, những chàng trai đã gặp lại nhau cho một mùa hè vui nhộn. Jim quyết định phải tìm bạn gái cho mình, và sau khi không thể trông chờ vào Nadia, anh đành nhờ cậy tới sự trợ giúp của cô bạn gái cũ, Michele. Trong lúc đó, Kev và Vicky tìm lại được chính họ trong một tình huống khó xử sau một năm chia tay. Oz phải đối mặt với vấn đề tương đối nan giải với mối tình lâu năm của mình khi Heather quyết định đi du học... Những vui buồn trong các mối tình trai trẻ đã đưa bộ phim tới những tình huống đầy lãng mạn và hài hước.Các băng đảng toàn đang trở lại và càng gần hơn bao giờ hết. Họ quyết định xa hơn bằng cách chi tiêu mùa hè cùng nhau tại một ngôi nhà bãi biển. Họ quyết định tổ chức ...</p>', 'Full', 1, 'single', 'completed', 16, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Biggs","avatar":""},{"name":"Thomas Ian Nicholas","avatar":""},{"name":"Chris Klein","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Eddie Kaye Thomas","avatar":""},{"name":"Alyson Hannigan","avatar":""},{"name":"Shannon Elizabeth","avatar":""},{"name":"Tara Reid","avatar":""},{"name":"Mena Suvari","avatar":""},{"name":"Natasha Lyonne","avatar":""},{"name":"Chris Owen","avatar":""},{"name":"Eugene Levy","avatar":""},{"name":"Molly Cheek","avatar":""},{"name":"Denise Faye","avatar":""},{"name":"Lisa Arturo","avatar":""},{"name":"John Cho","avatar":""},{"name":"Justin Isfeld","avatar":""},{"name":"Eli","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324534);
