INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chau-cang', 'Trân Châu Cảng', 'Pearl Harbor', 'https://phimimg.com/upload/vod/20231022-1/b34add17580f61d7dfae168e8c9706d5.jpg', 'https://phimimg.com/upload/vod/20231022-1/ca92672861f969e30aa88b17b1bd7a31.jpg', '<p>Những người bạn thời thơ ấu Rafe và Danny trở thành phi công quân đội và gặp Evelyn, một y tá hải quân. Tuy nhiên, cả ba người sau đó nhận ra mình đang ở giữa cuộc tấn công vào Trân Châu Cảng trong Thế chiến thứ hai.</p>', 'Full', 1, 'single', 'completed', 18, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Kate Beckinsale","avatar":""},{"name":"Josh Hartnett","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"William Lee Scott","avatar":""},{"name":"Greg Zola","avatar":""},{"name":"Jennifer Garner","avatar":""},{"name":"Jaime King","avatar":""},{"name":"Catherine Kellner","avatar":""},{"name":"Sara Rue","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Dan Aykroyd","avatar":""},{"name":"Colm Feore","avatar":""},{"name":"Mako","avatar":""},{"name":"Jo","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324534);
