INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo', 'Giấc Mơ', 'Donnie Darko', 'https://phimimg.com/upload/vod/20231022-1/966d46f35e672fad411cf9e0923ebdb8.jpg', 'https://phimimg.com/upload/vod/20231022-1/933077c353c1d4f77a94edd38d34e08f.jpg', '<p>Donnie Darko là một cậu học sinh ‘cá biệt’ bị ám ảnh bởi hình ảnh của một con thỏ khổng lồ luôn tìm cách lôi kéo cậu tham gia một loạt tội ác sau một tai nạn kỳ lạ. Những tình huống ly kì hồi hộp làm khán giả bị cuốn theo sự hoang tưởng trong tiềm thức của nhân vật chính. Cho đến cuối cùng, họ mới nhận ra được sự thật của những hoang tưởng ấy bắt nguồn từ đâu...</p>', 'Full', 1, 'single', 'completed', 14, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jake Gyllenhaal","avatar":""},{"name":"Jena Malone","avatar":""},{"name":"James Duval","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"Beth Grant","avatar":""},{"name":"Maggie Gyllenhaal","avatar":""},{"name":"Mary McDonnell","avatar":""},{"name":"Holmes Osborne","avatar":""},{"name":"Noah Wyle","avatar":""},{"name":"Katharine Ross","avatar":""},{"name":"Patrick Swayze","avatar":""},{"name":"Daveigh Chase","avatar":""},{"name":"Arthur Taxier","avatar":""},{"name":"David St. James","avatar":""},{"name":"Patience Cleveland","avatar":""},{"name":"Jazzie Mahannah","avatar":""},{"name":"Jolene","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324534);
