INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-toan-ma', 'Ngôi Nhà Toàn Ma', 'The Others', 'https://phimimg.com/upload/vod/20231023-1/372200a6de0be3dbdbb5f9d00809cfb1.jpg', 'https://phimimg.com/upload/vod/20231023-1/f922f8ef73298610b6b9f6293b792ae6.jpg', '<p>Lấy bối cảnh vào thời điểm hậu Chiến tranh thế giới thứ hai, tại một tòa lâu đài cổ nằm sâu trong một khu rừng quanh năm bao phủ bởi sương mù, nội dung xoay quanh câu chuyện về Grace Stewart (Nicole Kidman), một bà mẹ đơn thân một mình nuôi hai đứa con mắc chứng bệnh sợ ánh sáng. Bà mẹ là một người rất nghiêm khắc và có những quy tắc nhất định trong tòa lâu đài như là rèm cửa phải luôn được che kín, tất cả phòng đều phải được khóa kỹ. Cuộc sống của họ cứ trôi đi cho tới một ngày, có ba người gia nhân tới sống. Mọi chuyện kỳ lạ bắt đầu xảy ra trong tòa lâu đài: tiếng động kinh hoàng trong một căn phòng bí ẩn, cuốn album chụp ảnh những người chết, cô con gái tự nói chuyện một mình...</p>', 'Full', 1, 'single', 'completed', 24, 2001, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Christopher Eccleston","avatar":""},{"name":"Alakina Mann","avatar":""},{"name":"James Bentley","avatar":""},{"name":"Fionnula Flanagan","avatar":""},{"name":"Eric Sykes","avatar":""},{"name":"Elaine Cassidy","avatar":""},{"name":"Renée Asherson","avatar":""},{"name":"Gordon Reid","avatar":""},{"name":"Keith Allen","avatar":""},{"name":"Michelle Fairley","avatar":""},{"name":"Alexander Vince","avatar":""},{"name":"Ricardo López","avatar":""},{"name":"Aldo Grilo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324534);
