INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-nhi', 'Điệp Viên Nhí', 'Spy Kids', 'https://phimimg.com/upload/vod/20231023-1/68fcb028a1d272ed84f2faf9426ffe5a.jpg', 'https://phimimg.com/upload/vod/20231023-1/829f19ebf320f4b2527399b82ab7fa9e.jpg', '<p>Carmen và Juni nghĩ bố mẹ họ thật nhàm chán. Họ ít biết rằng vào thời của họ, Gregorio và Ingrid Cortez là những đặc vụ bí mật hàng đầu của đất nước họ. Họ đã từ bỏ cuộc sống đó để nuôi con. Giờ đây, sự mất tích của một số đồng nghiệp cũ buộc Cortez phải trở về sau khi nghỉ hưu. Điều họ không ngờ tới là Carmen và Juni tham gia vào &quot;công việc kinh doanh của gia đình&quot;.</p>', 'Full', 1, 'single', 'completed', 20, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alexa PenaVega","avatar":""},{"name":"Daryl Sabara","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Teri Hatcher","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Dick Clark","avatar":""},{"name":"George Clooney","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Richard Linklater","avatar":""},{"name":"Mike Judge","avatar":""},{"name":"Guillermo Navarro","avatar":""},{"name":"Johnny Reno","avatar":""},{"name":"Shannon Shea","avatar":""},{"name":"Ka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324534);
