INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phim-kinh-di-hai-my-2', 'Phim Kinh Dị Hài Mỹ 2', 'Scary Movie 2', 'https://phimimg.com/upload/vod/20231018-1/154492949ad19e531b712fea7adadeaf.jpg', 'https://phimimg.com/upload/vod/20231018-1/047191b42854fa1bea1b0abb7406e044.jpg', '<p>him Phim Kinh Dị: Tiếp nối sự thành công của phần đầu tiên, Scary Movie 2 tiếp tục được ra mắt. Lần này,câu chuyện bắt đầu khi giáo sư Oldman và người trợ lý bị bại liệt Dwight quyết định tiến hành một nghiên cứu tại Hell House, ngôi nhà nơi diễn ra lễ trục xuất quỷ của McFeely và Harris. Hai người giả vờ đó là nghiên cứu về chứng rối loạn giấc ngủ. Nhưng tệ thay căn nhà nọ có những điều bí mật mờ ám, gây ra nhiều rắc rối cho nhóm giáo sư và sinh viên. Vẫn phong cách nhái lại những phim khác một cách hài hước, họ sẽ nhắc chúng ta nhớ đến &quot;Exorcist&quot;, &quot;Mission Impossible&quot;, &quot;Charlie’s Angel&quot; và nhiều tác phẩm khác</p>', 'Full', 1, 'single', 'completed', 20, 2001, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Anna Faris","avatar":""},{"name":"Regina Hall","avatar":""},{"name":"Shawn Wayans","avatar":""},{"name":"Marlon Wayans","avatar":""},{"name":"Christopher Masterson","avatar":""},{"name":"David Cross","avatar":""},{"name":"Kathleen Robertson","avatar":""},{"name":"Tori Spelling","avatar":""},{"name":"Tim Curry","avatar":""},{"name":"Chris Elliott","avatar":""},{"name":"James Woods","avatar":""},{"name":"Andy Richter","avatar":""},{"name":"Veronica Cartwright","avatar":""},{"name":"Natasha Lyonne","avatar":""},{"name":"Richard Moll","avatar":""},{"name":"James DeBello","avatar":""},{"name":"Beetlejuice","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324534);
