INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giay-phut-doat-menh-2', 'Giây Phút Đoạt Mệnh 2', 'Running Out Of Time 2', 'https://phimimg.com/upload/vod/20231008-1/1e00e9759a59664dda9bb51f30004ca3.jpg', 'https://phimimg.com/upload/vod/20231008-1/bb9c44831f2835b666a7e28adb8d152b.jpg', '<p>Thanh tra cao cấp Hà Thượng Sinh bị bọn cướp điểm danh đàm phán vụ án, mắt thấy bọn cướp ngông nghênh giữa hiện trường, Hà Thượng Sinh đấu trí hạ gục bọn chúng, nhưng nó vẫn thoát được. Sự thất bại làm Hà Thượng Sinh dấy lên ý chí đấu tranh và sự tò mò, nên đã cùng tên cướp chơi ” Trò nhận tiền chuộc”. Lúc này Hà Thượng Sinh nhận vụ án lại phát hiện ra sự việc đơn giản hơn anh tưởng tượng rất nhiều…</p>', 'Full', 1, 'single', 'completed', 21, 2001, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Ekin Cheng","avatar":""},{"name":"Kelly Lin","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Ruby Wong Cheuk-Ling","avatar":""},{"name":"Ding Yuin-Shan","avatar":""},{"name":"Mai Yong Lin","avatar":""},{"name":"Chiu Chi-Shing","avatar":""},{"name":"Law Wing-cheong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324534);
