INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-nu-ca-ky', 'Nam Nữ Ca Kỳ', 'Let''s Sing Along', 'https://phimimg.com/upload/vod/20231006-1/266a818f542ec2d5f6f4a8b1dea457b3.jpg', 'https://phimimg.com/upload/vod/20231006-1/be9163af0cdad1243b38a2dae3046ddd.jpg', '<p>Chu Wai Tak (Anita Mui), một nữ nhân viên văn phòng rụt rè và nhút nhát, bị bạn trai cũ xấu hổ khi đăng ký cho cô tham gia một cuộc thi ca hát. Tak đang gặp rắc rối vì cô ấy không thể hát khi có người khác ở bên cạnh. Cô nhờ King (Dayo Wong), một người đam mê Karaoke, huấn luyện cô và khiến cô tự tin khi biểu diễn trước người khác. Thời điểm đang đến, King quyết định trao cho Tak trận chung kết</p>', 'Full', 1, 'single', 'completed', 24, 2001, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Anita Mui","avatar":""},{"name":"Dayo Wong","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Crystal Tin Yue-Lai","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Hau Woon-Ling","avatar":""},{"name":"Wong So-Bik","avatar":""},{"name":"Andy Tsang Tak-Wah","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324534);
