INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nam-nu-ca-ky', 'Nam Nữ Ca Kỳ', 'Let''s Sing Along', 'nam nữ ca kỳ let''s sing along anita mui dayo wong hui siu-hung wong yat-fei chapman to crystal tin yue-lai chin ka-lok hau woon-ling wong so-bik andy tsang tak-wah ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-kieng-khem', 'Chuyện Tình Kiêng Khem', 'Love On A Diet', 'https://phimimg.com/upload/vod/20231006-1/2fa20d7c652bf2c1dbb07b4d9f0d6ccd.jpg', 'https://phimimg.com/upload/vod/20231006-1/bfea293acf7293d57d7d1fc35ece6b6d.jpg', '<p>Cô nàng Mimi Mo (Trịnh Tú Văn), cô có bạn trai là một nghệ sĩ nổi tiếng tại Nhật Bản. Cô vốn rất xinh đẹp và nhỏ nhắn nhưng do trước đây, người bạn trai ấy của cô đi du học, trong lúc đau buồn Mimi đã ăn lấy ăn để như giúp quên đi nuỗi buồn nên đã khiến thân hình của cô càng ngày càng tròn trịa. Xấu hổ với thân hình của mình đã có lúc cô định tự tử nhưng cũng từ đó mà cô đã gặp được anh chàng béo tròn không khác gì cô tên là Tubby ( Lưu Đức Hoa). Mặc dù Mimi đã quyết tâm từ bỏ người bạn trai cũ, nhưng khi nghe tin anh ta chuẩn bị đính hôn, cô vẫn cảm thấy thực sự đau buồn và quyết định không từ bỏ nữa, từ đó cô tìm đến các giải pháp giảm cân. Cùng lúc đó, Tubby nhận ra rằng việc giúp đỡ cô đã tiêu tốn một khoản khá lớn. Anh quyết định mở một sàn boxing đường phố để kiếm tiền giúp Mimi tiếp tục giảm cân. Chỉ trong vòng một thời gian rất ngắn đã trở nên xinh đẹp với thân hình cân đối như 10 năm trước, nhưng cũng từ lúc đó mà lúc cô mới thực sự nhận ra rằng mình đang yêu ai.</p>', 'Full', 1, 'single', 'completed', 21, 2001, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Sammi Cheng","avatar":""},{"name":"Wong Tin-lam","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Rikiya Kurokawa","avatar":""},{"name":"Asuka Higuchi","avatar":""},{"name":"Keiji Sato","avatar":""},{"name":"Wong Mei-Fan","avatar":""},{"name":"Po Ming-Nam","avatar":""},{"name":"Ryuji Yamamoto","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324534);
