INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-bo-tuyet-vong', 'Bến Bờ Tuyệt Vọng', 'Desperation Verge', 'https://phimimg.com/upload/vod/20231006-1/3fe5bc1438feeb438605c068f3283a30.jpg', 'https://phimimg.com/upload/vod/20231006-1/b6eec1c512ba7f31e8d9ef3e279b6eba.jpg', '<p>Mouse và Tarzan là hai đệ tử xuất sắc và đáng tin cậy nhất của 
Brother Leopard. Mouse được hướng dẫn bay đến Malaysia với một số tiền 
rất lớn để đối phó với Hội tam hoàng ở đó. Thật bất ngờ, anh và người 
anh em bị tấn công. Chỉ có Mouse mới có thể thoát khỏi bị giết, nhưng 
anh phải trốn và trốn đi nơi khác. Tarzan xuất hiện; tuy nhiên, không ai
 biết tại sao anh ta đã giết Brother Leopard ...</p>', 'Full', 1, 'single', 'completed', 25, 2001, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Hugo Ng","avatar":""},{"name":"Bill Shum Wai","avatar":""},{"name":"Alan Chan Kwok-Kuen","avatar":""},{"name":"Kong Wing-Fai","avatar":""},{"name":"Chim Bing-Hei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324534);
