INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-chien-giang-ho', 'Dã Chiến Giang Hồ', 'Born Wild', 'https://phimimg.com/upload/vod/20231006-1/c289806b6e9271a1b2e66c145dabf846.jpg', 'https://phimimg.com/upload/vod/20231006-1/8480d1c2c5b1366ad7610b92e68d8029.jpg', '<p>rương Hồ và Tấn Hồ là hai anh em song sinh nhưng tính tình lại hoàn toàn khác biệt. Xem phim online này bạn sẽ thấy Tấn thì năng động, thân mật trong khi Trương lại có môt cuộc sống khá khép kín và nhút nhát, nhưng cả hai đều rất thông minh. Một hôm, Trương đón hai vị khách bất ngờ đến từ cục cảnh sát thông báo về cái chết của người anh sinh đôi, như bị một quả tạ giáng xuống, Trương vội vàng tới Hồng Kông nhận dạng anh trai mình.</p>', 'Full', 1, 'single', 'completed', 23, 2001, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Jo Kuk Cho-Lam","avatar":""},{"name":"Ying Kwan Lok","avatar":""},{"name":"Arthur Wong Ngok-Tai","avatar":""},{"name":"Chang Kuo-Chu","avatar":""},{"name":"Phyllis Quek","avatar":""},{"name":"Wrath James White","avatar":""},{"name":"Pai Ying","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324534);
