INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-dep-len-san', 'Trai Đẹp Lên Sàn', 'Zoolander', 'https://phimimg.com/upload/vod/20230919-1/a6f23aa785d3a6d831d461fecee2add1.jpg', 'https://phimimg.com/upload/vod/20230919-1/77ceea03c4e16f8897dfe7eab5e2baff.jpg', '<p>Dọn đường cho Derek Zoolander, người mẫu nam ba lần của năm của VH1. Mặt anh xịu xuống khi Hansel theo phong cách hippie sang trọng lao vào cướp giải thưởng năm nay. Bậc thầy thời trang độc ác Mugatu chớp lấy cơ hội để biến Derek thành một cỗ máy giết người. Đó là một âm mưu được dàn dựng khéo léo và chỉ với sự giúp đỡ của Hansel cùng một số phụ kiện được lựa chọn kỹ lưỡng như Matilda, Derek mới có thể mang lại thế giới an toàn cho người mẫu nam ở khắp mọi nơi.</p>', 'Full', 1, 'single', 'completed', 27, 2001, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Christine Taylor","avatar":""},{"name":"Will Ferrell","avatar":""},{"name":"Milla Jovovich","avatar":""},{"name":"Jerry Stiller","avatar":""},{"name":"David Duchovny","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Judah Friedlander","avatar":""},{"name":"Nathan Lee Graham","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324534);
