INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trai-dep-len-san', 'Trai Đẹp Lên Sàn', 'Zoolander', 'trai đẹp lên sàn zoolander ben stiller owen wilson christine taylor will ferrell milla jovovich jerry stiller david duchovny jon voight judah friedlander nathan lee graham ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-tam-hon-dep', 'Một Tâm Hồn Đẹp', 'A Beautiful Mind', 'https://phimimg.com/upload/vod/20230916-1/aeef189fcb6785b448d129b313fd944e.jpg', 'https://phimimg.com/upload/vod/20230916-1/c05f0d71b04b0d0f7ee9b2810a3dee03.jpg', '<p><span style="font-family: ">Một Tâm Hồn Đẹp (A Beautiful Mind) là một bộ phim tiểu sử kể về cuộc đời của nhà kinh tế học John Nash, giáo sư thuộc viện Toán học trường Princeton từng đoạt giải Nobel kinh tế 1994. Nguyên tác là cuốn tiểu thuyết thể loại truyện ký được Sylvia Nasar dựa trên tư liệu về cuộc đời của Nash viết thành, được tặng giải thưởng Sách Quốc gia 1998 và nhận một để cử giải Pulitzer. Câu chuyện bắt đầu với những năm đầu đời của một thần đồng trẻ tuổi tên John Nash. Tuy nhiên anh sớm bị mắc căn bệnh Tâm thần phân liệt hoang tưởng và phải đấu tranh với nó trong sự gánh nặng đầy đau đớn, chịu đựng của người vợ Alicia và bạn bè. Những khi tâm thần ổn định, anh vẫn tiếp tục nghiên cứu và đạt được những thành tựu lớn, trở thành một trong những nhà toán học có tầm ảnh hưởng nhất của nước Mỹ. A Beautiful Mind thắng 4 giải Oscar, bao gồm Phim hay nhất, Đạo diễn xuất sắc nhất, Kịch bản chuyển thể xuất sắc nhất và Nữ diễn viên phụ xuất sắc nhất.</span></p>', 'Full', 1, 'single', 'completed', 30, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Paul Bettany","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Josh Lucas","avatar":""},{"name":"Adam Goldberg","avatar":""},{"name":"Anthony Rapp","avatar":""},{"name":"Judd Hirsch","avatar":""},{"name":"Jason Gray-Stanford","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324534);
