INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jason-x', 'Jason X', 'Jason X', 'https://phimimg.com/upload/vod/20230912-1/66e00b9bd627aa4a4ed3936bb6a30806.jpg', 'https://phimimg.com/upload/vod/20230912-1/298ef371a183eb2dea0423e2a1263acc.jpg', '<p>Vào năm 2455, Trái đất Cũ giờ đây là một hành tinh bị ô nhiễm bị bỏ hoang trong nhiều thế kỷ - một thế giới màu nâu của những cơn bão dữ dội, những vùng đất độc hại và biển độc. Ấy vậy mà con người lại quay trở lại nơi chết chóc mà họ từng trốn chạy, không phải để sinh sống mà để nghiên cứu những hiện vật cổ xưa, rỉ sét của những nền văn minh lâu đời. Nhưng không phải môi trường độc hại có thể gây tử vong cho những nhà thám hiểm trẻ tuổi, dũng cảm vừa đặt chân lên Trái đất Cũ. Đối với họ, đó là thứ Sáu ngày 13 và Jason vẫn sống!</p>', 'Full', 1, 'single', 'completed', 35, 2001, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kane Hodder","avatar":""},{"name":"Lexa Doig","avatar":""},{"name":"Chuck Campbell","avatar":""},{"name":"Lisa Ryder","avatar":""},{"name":"David Cronenberg","avatar":""},{"name":"Markus Parilo","avatar":""},{"name":"Jonathan Potts","avatar":""},{"name":"Dov Tiefenbach","avatar":""},{"name":"Melyssa Ade","avatar":""},{"name":"Todd Farmer","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324534);
