INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-ai-quoc-nguoi-yeu-nuoc', 'Nhà Ái Quốc (Người Yêu Nước)', 'The Patriot', 'https://phimimg.com/upload/vod/20260705-1/7428ea459bd6d8fd2a6264cff7d9a0dc.jpg', 'https://phimimg.com/upload/vod/20260705-1/677da5f251e9b8506a32bea1b912c7dd.jpg', '<p>Mặc dù cuộc chiến giữa nước Mỹ non trẻ đang cố tách khỏi sự cai trị của đế quốc Anh vẫn ở giai đoạn khốc liệt, nhưng đối với Benjamin Martin (Mel Gibson) thì quá khứ đẫm máu mà anh tham chiến là quá đủ cho một cựu binh hiển hách. Mệt mỏi sau những chuỗi ngày chinh chiến, anh quay về gia đình, chỉ muốn sum họp với những người thương yêu và cố quên đi thực tại vẫn đầy tiếng gầm rú của bom đạn.Tuy nhiên, trong một gia đình mang dòng máu anh hùng lý tưởng thì người con trai lớn của anh là Gabriel Martin (Heath Ledger) khi đã chín chắn và trưởng thành lại không muốn đứng ngoài lề cuộc chiến dân tộc này. Cậu đã tham gia vào đội quân thuộc địa chiến đấu vì tự do. Benjamin, mặc dù mệt mỏi, vẫn không muốn con trai cô độc đối ...</p>', 'Full', 1, 'single', 'completed', 76, 2000, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Heath Ledger","avatar":""},{"name":"Joely Richardson","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"René Auberjonois","avatar":""},{"name":"Lisa Brenner","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"Leon Rippy","avatar":""},{"name":"Adam Baldwin","avatar":""},{"name":"Jay Arlen Jones","avatar":""},{"name":"Joey D. Vieira","avatar":""},{"name":"Gregory Smith","avatar":""},{"name":"Mika Boorem","avatar":""},{"name":"Skye McCole Bartusiak","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Patriota","The Patriot Extended Cut","O Patriotis","The Patriot"]', 1784690324534);
