INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-hai-dem', 'Mười Hai Đêm', 'Twelve Nights', 'https://phimimg.com/upload/vod/20260605-1/5dae49c33754b75251a3a9f83b1c3334.jpg', 'https://phimimg.com/upload/vod/20260605-1/fb6fc51f57895806452e797db00c604b.jpg', '<p>Bộ phim này trải qua 12 đêm quan trọng (không phải những đêm liên tiếp) trong mối quan hệ giữa hai nhân vật. Bộ phim cung cấp một số thông tin chi tiết về sự lặp lại liên quan đến các chu kỳ mối quan hệ từ sự quan tâm thông qua các căng thẳng khác nhau đến sự không quan tâm cuối cùng</p>', 'Full', 1, 'single', 'completed', 31, 2000, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Eason Chan Yik-Shun","avatar":""},{"name":"Cecilia Cheung","avatar":""},{"name":"Candy Lo Hau-Yam","avatar":""},{"name":"Ronald Cheng Chung-Kei","avatar":""},{"name":"Stephen Fung","avatar":""},{"name":"Nicola Cheung Sun-Yuet","avatar":""},{"name":"Vincci Cheuk Wan-Chi","avatar":""},{"name":"Nicholas Tse Ting-Fung","avatar":""},{"name":"Sue Au","avatar":""},{"name":"Jim Yan Chi-Hong","avatar":""},{"name":"Wong Shiu-Keung","avatar":""},{"name":"Wong Man-Chun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Shap yee yeh","12夜","十二夜"]', 1784690324534);
