INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('muoi-hai-dem', 'Mười Hai Đêm', 'Twelve Nights', 'mười hai đêm twelve nights eason chan yik-shun cecilia cheung candy lo hau-yam ronald cheng chung-kei stephen fung nicola cheung sun-yuet vincci cheuk wan-chi nicholas tse ting-fung sue au jim yan chi-hong wong shiu-keung wong man-chun shap yee yeh 12夜 十二夜', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-than-nu-ai', 'Nam Thân Nữ Ái', 'And I Hate You So', 'https://phimimg.com/upload/vod/20260605-1/7b188aea33d7e515e1a84782bec29b9a.jpg', 'https://phimimg.com/upload/vod/20260605-1/9d6dbfa36e9bd80c6f0bc74b6d1c5995.jpg', '<p>Cheung Yung (Quách Phú Thành) làm khách mời trong chương trình trò chuyện trên đài phát thanh. Nhưng anh lại gây gổ với người dẫn chương trình Luna Yung (Trần Tuệ Lâm) vì cô ta dám “xỉ nhục” album kỷ lục của anh và dùng mọi lời lẽ thô tục nhất để nói chuyện với cô ta. Và khi 2 ngọn lửa dần xẹp xuống, họ đột nhiên nhận ra rằng họ đã rất quyến luyến đối phương. &nbsp;And I Hate You So (Nam Thân Nữ Ái) sở hữu motip kinh điển: chàng trai và cô gái ghét nhau vì lý do nào đó, song lại hay chạm mặt nhau rồi sau đấy kết thúc trong tình yêu. Nhưng đó là một công thức hiệu quả của phim Hồng Kông rom-com cổ điển, cho dù bao nhiêu lần đi chăng nữa thì khán giả vẫn quay lại xem thêm. Những khung hình tuyệt đẹp về những khu vực của Hồng Kông như Causeway Bay và SoHo khiến trái tim khán giả rung động.</p>', 'Full', 1, 'single', 'completed', 30, 2000, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok Fu-Shing","avatar":""},{"name":"Kelly Chen Hui-Lin","avatar":""},{"name":"Eric Tsang Chi-Wai","avatar":""},{"name":"Teresa Mo Shun-Kwan","avatar":""},{"name":"Mark Lui","avatar":""},{"name":"Chan Fai-Hung","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Julian Cheung Chi-Lam","avatar":""},{"name":"Jessica Hsuan","avatar":""},{"name":"Michael Tse Tin-Wah","avatar":""},{"name":"Isabel Chan Yat-Ning","avatar":""},{"name":"Pauline Yam Bo-Lam","avatar":""},{"name":"Ng Kit-Yan","avatar":""},{"name":"Ho Chun-Hin","avatar":""},{"name":"Steve","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Siu chan chan","小親親"]', 1784690324534);
