INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-hinh-thay-the', 'Đội Hình Thay Thế', 'The Replacements', 'https://phimimg.com/upload/vod/20260512-1/b31661c3908309b4554bf42e0009ce17.jpg', 'https://phimimg.com/upload/vod/20260512-1/c8873cc665f3fff8911c603ad3e75c20.jpg', '<p>Huấn luyện viên kỳ cựu Jimmy McGinty được bổ nhiệm sau cuộc đình công của các cầu thủ để giúp Washington Sentinels tiến vào vòng play-off. Nhưng giấc mơ bất khả thi đó phụ thuộc vào việc liệu những người thay thế ông có thể trụ vững và hoàn thành nhiệm vụ hay không. Vì vậy, McGinty đã phủi bụi hồ sơ bí mật của mình về những cựu cầu thủ chưa bao giờ có cơ hội (hoặc đã làm hỏng cơ hội được giao) và tập hợp một đội hình tồi tệ, những người có thể sẽ mang đến cho Sentinels cơ hội vô địch.</p>', 'Full', 1, 'single', 'completed', 20, 2000, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Gene Hackman","avatar":""},{"name":"Brooke Langton","avatar":""},{"name":"Orlando Jones","avatar":""},{"name":"Faizon Love","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"Keith David","avatar":""},{"name":"Ace Yonamine","avatar":""},{"name":"Troy Winbush","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Equipo a la fuerza","Дублеры","Los Suplentes","The Replacements"]', 1784690324534);
