INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vao-nam-ra-bac', 'Vào Nam Ra Bắc', 'Down South, Up North', 'https://phimimg.com/upload/vod/20250401-1/5a055e37b5fc85fad4e88516087c2006.jpg', 'https://phimimg.com/upload/vod/20250401-1/5a055e37b5fc85fad4e88516087c2006.jpg', '<p>Bộ phim kể về cuộc hội ngộ bất ngờ giữa một người lính năm xưa và người vũ nữ. Câu chuyện lôi kéo người xem trở về những năm tháng kháng chiến ác liệt ở miền Bắc. Rời Hà Nội để vào Nam chiến đấu, Quang- trắng trẻo, thư sinh và trong sáng như bao chàng trai khác thời chiến tranh – bỗng nhụt chí khi các đồng đội từng trải kể về sự ác liệt của chiến tranh, nỗi ám ảnh rồi đây sẽ chết thảm trên chiến trường mà chưa biết tí gì về mùi đàn bà và sự thật trước mắt hiển hiện khi trên đường hành quân nhiều đồng đội cùng trang lứa đã phải nằm xuống bởi bom đạn. Thế là Quang quyết định đào ngũ trong đêm tối lẫn trốn vào ruộng khoai mì chờ tàu trở ngược ra Bắc và gặp bé Nụ.</p>', 'Full', 1, 'single', 'completed', 22, 2000, 'Vietsub', 'HD', 'Việt Nam', 0, '[]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Vào Nam Ra Bắc"]', 1784690324534);
