INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-thet-3', 'Tiếng Thét 3', 'Scream 3', 'https://phimimg.com/upload/vod/20260416-1/9149eece83eed1a7c55b575438ffe8cb.jpg', 'https://phimimg.com/upload/vod/20260416-1/b7c854d9def354c8d57d5972ba56af7c.jpg', '<p>Một cuộc giết người bắt đầu xảy ra một lần nữa, lần này mục tiêu của nó nhắm vào những người sống sót ban đầu của Woodsboro và những người liên quan đến bộ phim trong một bộ phim, &quot;Stab 3&quot;. Sydney phải đối mặt với những con quỷ trong quá khứ của mình để ngăn chặn kẻ giết người.</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Arquette","avatar":""},{"name":"Neve Campbell","avatar":""},{"name":"Courteney Cox","avatar":""},{"name":"Patrick Dempsey","avatar":""},{"name":"Scott Foley","avatar":""},{"name":"Lance Henriksen","avatar":""},{"name":"Matt Keeslar","avatar":""},{"name":"Jenny McCarthy","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Parker Posey","avatar":""},{"name":"Deon Richmond","avatar":""},{"name":"Kelly Rutherford","avatar":""},{"name":"Liev Schreiber","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Jamie Kennedy","avatar":""},{"name":"Roger L. Jackson","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夺命狂呼3","Κραυγη Αγωνιας 3","הצעקה III","Tiếng Thét 3","Qışqırıq 3","الصرخة ٣","الصرخة 3","Scream 3"]', 1784690324534);
