INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tieng-thet-3', 'Tiếng Thét 3', 'Scream 3', 'tiếng thét 3 scream 3 david arquette neve campbell courteney cox patrick dempsey scott foley lance henriksen matt keeslar jenny mccarthy emily mortimer parker posey deon richmond kelly rutherford liev schreiber patrick warburton jamie kennedy roger l. jackson j 夺命狂呼3 κραυγη αγωνιας 3 הצעקה iii tiếng thét 3 qışqırıq 3 الصرخة ٣ الصرخة 3 scream 3', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-nguyen-hoi-ket', 'Cao Nguyên: Hồi Kết', 'Highlander: Endgame', 'https://phimimg.com/upload/vod/20260315-1/b4d6270b0561200359c3998e656e4d31.jpg', 'https://phimimg.com/upload/vod/20260315-1/22c38a419391a605648309940131f295.jpg', '<p>Hai chiến binh bất tử Connor và Duncan MacLeod buộc phải hợp lực để đối đầu với một kẻ thù đến từ quá khứ xa xôi của Connor tại vùng cao nguyên Scotland — Jacob Kell. Kell là một kẻ bất tử mang sức mạnh vô song, kẻ cầm đầu một đội quân gồm những tay kiếm và sát thủ bất tử cũng hung bạo và tàn ác không kém.&nbsp; Cho đến nay, chưa một kẻ bất tử nào có thể đánh bại được Kell, và cả Connor lẫn Duncan đều hiểu rằng nếu chiến đấu đơn độc, họ không đủ sức để đối đầu với hắn mà vẫn có thể sống sót. Cuối cùng, cả hai đi đến một kết luận nghiệt ngã: một trong hai người phải hy sinh để người còn lại nhận được sức mạnh tổng hợp của cả hai, từ đó mới có hy vọng tiêu diệt Kell vĩnh viễn.&nbsp; Chỉ một người được phép sống sót... câu hỏi đặt ra là: ai sẽ là người ở lại?</p>', 'Full', 1, 'single', 'completed', 19, 2000, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Christopher Lambert","avatar":""},{"name":"Adrian Paul","avatar":""},{"name":"Bruce Payne","avatar":""},{"name":"Lisa Barbuscia","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Jim Byrnes","avatar":""},{"name":"Peter Wingfield","avatar":""},{"name":"Beatie Edney","avatar":""},{"name":"David J. Nicholls","avatar":""},{"name":"John Medlen","avatar":""},{"name":"Adam Copeland","avatar":""},{"name":"Donald Douglas","avatar":""},{"name":"Thomas Lockyer","avatar":""},{"name":"Charmian May","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b