INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-xanh-hy-vong', 'Màu Xanh Hy Vọng', 'The Green Hope', 'https://phimimg.com/upload/vod/20251204-1/587140bb14378c4c39dc9f31587f30b5.jpg', 'https://phimimg.com/upload/vod/20251204-1/c80264598cb2c6c1a16694800a8f0fcb.jpg', '<p>Phương Gia Khiêm từ nhỏ đã có năng khiếu âm nhạc. Nhưng do sống cùng người mẹ nghiện ngập, chịu nhiều giày vò, Khiêm bị ảnh hưởng tâm lý và mắc bệnh tâm thần. Tưởng chừng cuộc đời đã lấy đi tất cả của Khiêm, nhưng may mắn thay, Khiêm vẫn còn một người anh hết lòng yêu thương mình. Đó là Phương Gia Huy. Sau khi cha mẹ li dị, hai anh em Huy và Khiêm thất lạc nhau nhiều năm. Theo tâm nguyện của cha, Huy bôn ba khắp nơi để tìm Khiêm. Ngày gặp lại Khiêm, Huy đã sốc khi biết Khiêm bị tâm thần, còn chứng kiến cảnh em trai bị người đời kỳ thị, xa lánh. Huy quyết tâm bù đắp cho Khiêm. Không chỉ nghỉ việc để toàn tâm toàn ý lo cho Khiêm, Huy còn đón cả bạn bè của Khiêm về ở cùng. Việc này khiến vợ Huy, là Tiễn Giai Quân, bất mãn. Cuối cùng, Huy chọn Khiêm, ngậm ngùi chia tay vợ. Sống chung với người tâm thần không hề dễ dàng. Những lúc Huy cô đơn nhất, luôn có cô trợ lý Thiệu Lệ Hoa kề cạnh, động viên. Hoa từ lâu đã ngưỡng mộ tài năng và tấm lòng của Huy. Tuy nhiên, tình cảm của Hoa dành cho Huy bị Quân lên án gay gắt. Mặt khác, Khiêm tình cờ làm quen với Nguyễn Doanh. Do bị tự kỷ từ nhỏ, Doanh rất đồng cảm với Khiêm. Tính cách lạc quan của Khiêm còn thu hút cô gái ngây thơ, hoạt bát Vi Văn. Họ tạo nên một mối tình tay ba trong sáng, dễ thương. Tình cảm chân thành của bạn bè, người thân dần giúp Khiêm tìm lại được mục đích sống. Nhưng để Khiêm thực sự hòa nhập cộng đồng, còn cả một chặng đường gian nan phía trước...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 16, 2000, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Bowie Lam","avatar":""},{"name":"Melissa Ng Mei-Heng","avatar":""},{"name":"Joey Yung Jo-Yee","avatar":""},{"name":"Stephen Fung","avatar":""},{"name":"Yoyo Mung Ka-Wai","avatar":""},{"name":"Danny Lau Dan","avatar":""},{"name":"Ram Chiang Chi-Kwong","avatar":""},{"name":"Cathy Tsui Chi-Kei","avatar":""},{"name":"Lai Suen","avatar":""},{"name":"Safina Lam","avatar":""},{"name":"Kwan Hoi-San","avatar":""},{"name":"Tavia Yeung","avatar":""},{"name":"Vincent Kok Tak-Chiu","avatar":""},{"name":"Tam Sin-Hung","avatar":""},{"name":"Ronny Ching Siu-Lung","avatar":""},{"name":"Lee Shing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["新鮮人"]', 1784690324534);
