INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-quyen-vo-dich', 'Thần Quyền Vô Địch', 'The Kung Fu Master', 'https://phimimg.com/upload/vod/20251023-1/4b3c8c1d6815f6e2a144eab4b6eff6f0.jpg', 'https://phimimg.com/upload/vod/20251023-1/39679a258612862c8665eb9b117d1410.jpg', '<p>Thời nhà Thanh, Đàm Tông Chính - Đường chủ của Trung Nghĩa Đường, đại diện người Hán tham gia cuộc thi võ thuật &quot;Quyền Khuynh Thiên Hạ&quot;, tỉ thí với đại diện người Mãn là Ngao Phi. Tuy nhiên, do bị thương nên ông phải để con trai Đàm Thiên thay thế. Nào ngờ trước trận đấu, Thiên bị sư thúc Triệu Kiên hạ độc và thua cuộc, cha anh cũng bị hắn hại chết. Vì muốn hoàn thành tâm nguyện của cha, Thiên quyết định mở võ quán và chiêu mộ truyền nhân, nhưng luôn bị Phi âm thầm hãm hại…</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 15, 2000, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Yuen Wah","avatar":""},{"name":"Derek Kwok Jing-Hung","avatar":""},{"name":"Michael Tong Man-Lung","avatar":""},{"name":"Jade Leung Tsang","avatar":""},{"name":"Marco Ngai Chun-Git","avatar":""},{"name":"Natalie Ng Man-Yan","avatar":""},{"name":"Ellesmere Choi","avatar":""},{"name":"Kingdom Yuen King-Tan","avatar":""},{"name":"Mickey Chu Kin-Kwan","avatar":""},{"name":"Kwan Hoi-San","avatar":""},{"name":"Gordon Liu Chia-Hui","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["京城教一"]', 1784690324534);
