INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-dau-doi', 'Tình Yêu Đầu Đời', 'Malèna', 'https://phimimg.com/upload/vod/20251014-1/8f7a308ceffdfb028a53ca376263c0ed.jpg', 'https://phimimg.com/upload/vod/20251014-1/c7164e54dd3cda74d3aa68afd00679f4.jpg', '<p>Vào ngày nước Ý tham chiến năm 1940, có hai điều xảy ra với cậu bé 12 tuổi Renato: cậu bé có được chiếc xe đạp đầu tiên và cậu bé có cái nhìn đầu tiên về Malèna. Cô ấy là một người ngoài xinh đẹp, thầm lặng, đã chuyển đến thị trấn Sicilia này để ở với chồng của cô ấy, Nico. Anh ta nhanh chóng ra trận, để lại cô trước ánh mắt thèm muốn của những người đàn ông và những chiếc lưỡi sắc bén của phụ nữ. Trong vài năm tiếp theo, khi Renato dần trưởng thành, anh chứng kiến Malèna đau khổ và chứng tỏ dũng khí của cô. Anh nhìn thấy sự cô đơn của cô, sau đó đau buồn khi Nico được thông báo đã chết, ảnh hưởng của sự vu khống lên mối quan hệ của cô với cha mình, sự nghèo khó và tìm kiếm việc làm của cô, và sự sỉ nhục cuối cùng. Liệu Renato có học được lòng dũng cảm từ Malèna và đứng lên vì cô ấy?</p>', 'Full', 1, 'single', 'completed', 23, 2000, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Monica Bellucci","avatar":""},{"name":"Giuseppe Sulfaro","avatar":""},{"name":"Luciano Federico","avatar":""},{"name":"Matilde Piana","avatar":""},{"name":"Pietro Notarianni","avatar":""},{"name":"Gaetano Aronica","avatar":""},{"name":"Gilberto Idonea","avatar":""},{"name":"Angelo Pellegrino","avatar":""},{"name":"Gabriella Di Luzio","avatar":""},{"name":"Pippo Provvidenti","avatar":""},{"name":"Maria Terranova","avatar":""},{"name":"Marcello Catalano","avatar":""},{"name":"Elisa Morucci","avatar":""},{"name":"Domenico Gennaro","avatar":""},{"name":"Vitalba","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Малена","말레나","西西裡的美麗傳說","マレーナ","Μαλένα","Der Zauber von Malèna","Maléna","Malena","Malèna"]', 1784690324534);
