INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-bao-kinh-hoang', 'Cơn Bão Kinh Hoàng', 'The Perfect Storm', 'https://phimimg.com/upload/vod/20251012-1/43799a9bd7c85a4b4dde1bb79693ae6c.jpg', 'https://phimimg.com/upload/vod/20251012-1/718fb191d3aa0eb0371b55df4071ee57.jpg', '<p>Phim dựa trên câu chuyện có thật xảy ra tại Glancester bang Massachusetts về hành trình của tàu đánh cá Andrea Gail vượt qua cơn bão biển kinh hoàng. Tài tử đoạt giải Oscar 2006 George Clooney đã vào vai người thuyền trưởng dũng cảm.
 The Perfect Storm là một bộ phim hay, ca ngợi những người ngư dân dũng cảm không ngại cuộc sống lênh đênh sóng nước vốn đầy hiểm nguy rình rập ngoài khơi xa... Bộ phim là một thiên anh hùng ca về lòng quả cảm, ý chí vượt mọi khó khăn của con người trước thiên nhiên, bão tố... Hiệu ứng âm thanh và hình ảnh trong The Perfect Storm đã mang lại hai đề cử Oscar 2000 cho bộ phim này.</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Mark Wahlberg","avatar":""},{"name":"Diane Lane","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Mary Elizabeth Mastrantonio","avatar":""},{"name":"John Hawkes","avatar":""},{"name":"Dash Mihok","avatar":""},{"name":"Karen Allen","avatar":""},{"name":"Bob Gunton","avatar":""},{"name":"Cherry Jones","avatar":""},{"name":"Allen Payne","avatar":""},{"name":"Josh Hopkins","avatar":""},{"name":"Todd Kimsey","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Michael Ironside","avatar":""},{"name":"Rusty","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La Tormenta Perfecta [The Perfect Storm]","En pleine tempête","Meren Raivo","Kusursuz Fırtına","Viharzóna","天摇地动","惊涛骇浪","Perfect Storm","La tempête","La Tormenta Perfecta","Una tormenta perfecta","퍼펙트 스톰","Der Sturm - The Perfect Storm","Kataigida","Mar em Fúria","The Perfect Storm"]', 1784690324534);
