INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-bao-kinh-hoang', 'Cơn Bão Kinh Hoàng', 'The Perfect Storm', 'cơn bão kinh hoàng the perfect storm george clooney mark wahlberg diane lane john c. reilly william fichtner mary elizabeth mastrantonio john hawkes dash mihok karen allen bob gunton cherry jones allen payne josh hopkins todd kimsey christopher mcdonald michael ironside rusty la tormenta perfecta [the perfect storm] en pleine tempête meren raivo kusursuz fırtına viharzóna 天摇地动 惊涛骇浪 perfect storm la tempête la tormenta perfecta una tormenta perfecta 퍼펙트 스톰 der sturm - the perfect storm kataigida mar em fúria the perfect storm', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-y-hoa-da', 'Thần Y Hoa Đà', 'Incurable Traits', 'https://phimimg.com/upload/vod/20251012-1/1541135919e8ee771bb37eece72b6b25.jpg', 'https://phimimg.com/upload/vod/20251012-1/115bcf7fa8b1c4bc2d0beed7bf3743ff.jpg', '<p>Tư chất thông minh cùng với tấm lòng nhân hậu, từ nhỏ, Hoa Đà đã say mê y học, quyết chí trở thành thầy lang giỏi để cứu chữa cho người nghèo. Nhờ cơ duyên, Hoa Đà bái danh y làm sư phụ và nên nghĩa phu thê với Trương Diệu Tâm. Một lần, Quan Vân Trường đưa người quen đến gặp Hoa Đà, xin ông chữa giúp cơn sốt triền miên. Hoa Đà phát hiện đây là chứng bệnh lạ, không phải dạng thương hàn thông thường. Ông nhanh trí kết hợp hai phương pháp trong sách y học – “Luận Thương Hàn” và “Luận Tư Âm”, nghiên cứu thành công cách trị ôn dịch. Danh tiếng Hoa Đà từ đó vang xa, nhưng lại nảy sinh nhiều rắc rối đáng tiếc. Bọn tiểu nhân ganh ghét nên lập mưu hãm hại, khiến Hoa Đà lâm vào họa sát thân. Ông cùng vợ phải trốn chạy thật xa, đến vùng đất mới và tiếp tục hành nghề y. Người bị bệnh nặng cỡ nào cũng được Hoa Đà toàn lực giúp đỡ. Tuy nhiên, kết quả lại không như mong muốn, làm cho Hoa Đà mang nhiều tiếng xấu, sự nghiệp ngày càng xuống dốc. Mãi đến khi Hoa Đà giúp Tào Tháo chữa dứt căn bệnh lâu năm cho con trai, tài năng của ông mới được công nhận. Tào Tháo phong Hoa Đà làm Thái Y Viện Giám. Nhờ vậy, ông mới có cơ hội tổng hợp kiến thức, viết nên cuốn sách nổi tiếng – “Y học đại toàn”.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 14, 2000, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Frankie Lam","avatar":""},{"name":"Felix Wong Yat-Wah","avatar":""},{"name":"Christine Ng Wing-Mei","avatar":""},{"name":"Leung Wing-Lam","avatar":""},{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"Wong Wai","avatar":""},{"name":"Helen Poon Bing-Seung","avatar":""},{"name":"Alvina Kong Yan-Yin","avatar":""},{"name":"Jenny Yam Kong-Sau","avatar":""},{"name":"Tam Yat-Ching","avatar":""},{"name":"Cheung Ying-Tsoi","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Margaret Chung","avatar":""},{"name":"Willie Wai Ga-Hung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["医神华佗","Incurable Traits","醫神華佗"]', 1784690324534);
