INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('than-y-hoa-da', 'Thần Y Hoa Đà', 'Incurable Traits', 'thần y hoa đà incurable traits frankie lam felix wong yat-wah christine ng wing-mei leung wing-lam vincent wan yeung-ming wong wai helen poon bing-seung alvina kong yan-yin jenny yam kong-sau tam yat-ching cheung ying-tsoi helena law lan margaret chung willie wai ga-hung 医神华佗 incurable traits 醫神華佗', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhu-dao-tieu-tu', 'Nhu Đạo Tiểu Tử', 'Aiming High', 'https://phimimg.com/upload/vod/20251010-1/f8d23b4c8b23466b232abb5b7bb68a42.jpg', 'https://phimimg.com/upload/vod/20251010-1/4dda3f793eb04f665111cbbb1acca15a.jpg', '<p>Trở về Hong Kong tham dự lễ cưới của chị gái Triệu San San, Triệu Gia Tuấn tình cờ làm quen với cao thủ Judo La Bân. Là người yêu thích thể thao đặc biệt là bộ môn Judo nên Tuấn rất ngưỡng mộ Bân, còn quyết định nhận anh làm thầy nhưng lại bị chị gái phản đối vì Bân chính là oan gia của cô. Bân đành nhờ em gái mình là Tinh Tinh chỉ dạy cho Tuấn, sự khắt khe của Tinh khiến Tuấn khổ sở, anh quyết định “đi đường tắt”, vờ cưa cẩm cô để được “thủ hạ lưu tình”. Mặt khác, Tuấn cũng thành công hòa giải được San và Bân, mở ra một cuộc tình mới giữa hai người. Giữa lúc mọi thứ đang thuận lợi, Tinh phát hiện ra mục đích thực sự của anh và quyết định chia tay và đến với Lượng - người vừa đánh bại Tuấn trong trận đấu. Trớ trêu thay, đây cũng là lúc Tuấn nhận ra mình đã có tình cảm với Tinh…</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 14, 2000, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Nicholas Tse Ting-Fung","avatar":""},{"name":"Nicola Cheung Sun-Yuet","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Fiona Leung Ngai-Ling","avatar":""},{"name":"Hawick Lau Hau-Wai","avatar":""},{"name":"Cindy Au","avatar":""},{"name":"Willie Wai Ga-Hung","avatar":""},{"name":"Lee San-San","avatar":""},{"name":"Josephine Lam Kei-Yan","avatar":""},{"name":"Yu Chi-Ming","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Teresa Ha Ping","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Joe Ma Tak-Chung","avatar":""},{"name":"Wilson Ai Wa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["挞出爱火花","Aiming High","撻出愛火花","青春爱火花","柔道小子"]', 1784690324534);
