INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-thach-nghiet-nga-2-thoi-dai-khung-hoang-2', 'Thử Thách Nghiệt Ngã 2 (Thời Đại Khủng Hoảng 2)', 'At the Threshold of an Era 2', 'https://phimimg.com/upload/vod/20251010-1/49941ecc48cef79f3038c030437262be.jpg', 'https://phimimg.com/upload/vod/20251010-1/6500f0245e3e36fd4e4fdd04ae9d4701.jpg', '<p>Hứa Văn Bưu bị giết hại ở Đài Loan, Dĩnh Hân trở thành nghi phạm đầu tiên. Cuối cùng, Vinh Thiêm đã phát hiện ra người mình yêu nhất là Hy Hiền, nhưng đáng tiếc cô đã không còn tình cảm với anh nữa. Lúc này, một người giống Dĩnh Hân như đúc - Mỹ Na lại đột ngột xuất hiện. Trương Tự Lực và cha ruột gặp lại nhau, cậu dự định cùng Điền Ninh bên nhau dài lâu, đáng tiếc, sau khi Ninh mất trí nhớ, lại quyết định kết hôn cùng Chí Cường…</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 17, 2000, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Gallen Lo Ka-Leung","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Sunny Chan Kam-Hung","avatar":""},{"name":"Roger Kwok Chun-On","avatar":""},{"name":"Nicky Wu","avatar":""},{"name":"Joe Ma Tak-Chung","avatar":""},{"name":"Samuel Kwok Fung","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Hawick Lau Hau-Wai","avatar":""},{"name":"Ada Choi Siu-Fan","avatar":""},{"name":"Liza Wong Ming-Chuen","avatar":""},{"name":"Kenix Kwok Ho-Ying","avatar":""},{"name":"Flora Chan Wai-Shan","avatar":""},{"name":"Michelle Saram","avatar":""},{"name":"Shing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["At the Threshold of an Era 2","At the Threshold of an Era Ⅱ","創世紀2：天地有情"]', 1784690324534);
