INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-vong-2000', 'Thất vọng', 'War of the Genders', 'https://phimimg.com/upload/vod/20251008-1/7c38bfa2f833b8fbe8e69faa9159f222.jpg', 'https://phimimg.com/upload/vod/20251008-1/304d2fb08a634b641f9dd9dd8de86917.jpg', '<p>Mao Tiểu Tuệ là luật sư có tài &quot;bẻ cong thành thẳng&quot;, là đầu tàu của văn phòng luật sư CK. Do bản tính kén chọn nên đến tuổi trung niên cô vẫn chưa có bạn trai. Cho tới khi anh chàng Dư Lạc Thiên vào làm trợ lý, từ hiểu lầm ban đầu họ trở thành đôi oan gia gây thêm nhiều sóng gió cho văn phòng luật sư.Chúc các bạn xem phim vui vẻ.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 11, 2000, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["男亲女爱","War of the Genders","男親女愛"]', 1784690324534);
