INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phep-thuat-phan-3', 'Phép Thuật (Phần 3)', 'Charmed (Season 3)', 'phép thuật (phần 3) charmed (season 3) holly marie combs alyssa milano rose mcgowan brian krause kaley cuoco charmed: jovens bruxas oi magisses η μαγευτικές チャームド 魔女3姉妹 チャームド〜魔女3姉妹〜 hechiceras чародійки зачаровані всі жінки відьми усі жінки відьми charmed', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xmen-1-di-nhan', 'X-Men 1: Dị Nhân', 'X-Men', 'https://phimimg.com/upload/vod/20250817-1/f2b68e5c6917982406df569b6fe934bc.jpg', 'https://phimimg.com/upload/vod/20250817-1/7596856ff41dce0eebb83d0dae8415fc.jpg', '<p>X-men là những con người có năng lực siêu phàm. Họ tập trung tại một ngôi trường do giáo sư Charles Xavier để giúp cho họ sử dụng năng lực của mình một cách đúng đắn và có ích... Bộ phim bắt đầu từ việc cô bé Rogue bị sự truy lùng của một kẻ có mưu đồ làm bá chủ thế giới khi hắn muốn lợi dụng sức mạnh của Rogue để hoàn thành nguyện vọng của mình. Nhưng mọi thứ đã bị giáo sư và các thành viên của X-men ngăn cản. Phim được dựa theo bộ truyện tranh nổi tiếng của Mỹ.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2000, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hugh Jackman","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Ian McKellen","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"James Marsden","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Anna Paquin","avatar":""},{"name":"Tyler Mane","avatar":""},{"name":"Ray Park","avatar":""},{"name":"Rebecca Romijn","avatar":""},{"name":"Bruce Davison","avatar":""},{"name":"Matthew Sharp","avatar":""},{"name":"Brett Morris","avatar":""},{"name":"Rhona Shekter","avatar":""},{"name":"Kenneth McGregor","avatar":""},{"name":"Shawn Roberts","avatar":""},{"name":"Donna Goodhand","avatar":""},{"name":"John Nel","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["X-Men: The Movie","X-เม็น ศึกมนุษย์พลังเหนือโลก","X-mehed","Mozje X","엑스맨 1","X-odamlar","G''aroyib odamlar","X-מן","Iks-odamlar","X-MEN","X战警1","X-メン","エックスメン","X-Men - Der Film","Dị Nhân","X Men 1","X-Men Movie","X-Men"]', 1784690324534);
