INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xmen-1-di-nhan', 'X-Men 1: Dị Nhân', 'X-Men', 'x-men 1: dị nhân x-men hugh jackman patrick stewart ian mckellen famke janssen james marsden halle berry anna paquin tyler mane ray park rebecca romijn bruce davison matthew sharp brett morris rhona shekter kenneth mcgregor shawn roberts donna goodhand john nel x-men: the movie x-เม็น ศึกมนุษย์พลังเหนือโลก x-mehed mozje x 엑스맨 1 x-odamlar g''aroyib odamlar x-מן iks-odamlar x-men x战警1 x-メン エックスメン x-men - der film dị nhân x men 1 x-men movie x-men', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-phan-ung-phan-2', 'Lực Lượng Phản Ứng (Phần 2)', 'Armed Reaction (Season 2)', 'https://phimimg.com/upload/vod/20250717-1/dcd29f94a58020fd994fbbbd4b9f3c7e.jpg', 'https://phimimg.com/upload/vod/20250717-1/0634253f0228de761d6c7576b6bf0532.jpg', '<p>Từ nhỏ, Trần Tam Nguyên đã chịu sự ảnh hưởng của chú mình là Trần Tiểu Sanh, cô gia nhập đội cảnh sát làm sư tỉ cầm sung và trở thành bạn tốt của Chu Tố Nga. Sau khi ly hôn, Tố Nga quen biết Trần Tiểu Sanh, hai người từ đôi oan gia đấu khẩu dần trở thành tình nhân. Tam Nguyên vì có biểu hiện xuất sắc nên được điều chuyển qua tổ chống mại dâm, hợp tác cùng Trình Phong, trở thành một đôi “anh em” tốt, nhưng một lần tình cờ, cô phát hiện Trình Phong có tình cảm với mình. Nhưng khi hai người ở bên nhau, Tam Nguyên lại đột nhiên ngừng bước…</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 12, 2000, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Âu Dương Chấn Hoa","avatar":""},{"name":"Quan Vịnh Hà","avatar":""},{"name":"Đằng Lệ Danh","avatar":""},{"name":"Ngụy Tuấn Kiệt","avatar":""},{"name":"Chu Mễ Mễ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["陀枪师姐","陀枪师姐2021","陀枪师姐 第5季 2021","Tuo qiang shi jie","陀槍師姐","Armed Reaction"]', 1784690324534);
