INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shin-cau-be-but-chi-con-bao-rung-gia', 'Shin - Cậu Bé Bút Chì: Cơn Bão Rừng Già', 'Crayon Shin-chan: A Storm-invoking Jungle', 'https://phimimg.com/upload/vod/20250710-1/281896bdab69d47c628079fcdc22904f.jpg', 'https://phimimg.com/upload/vod/20250710-1/da5a00daa0fefb1ab84ba38f49c58478.jpg', '<p>Gia đình Shin cùng bạn bè lên tàu du ngoạn để gặp thần tượng Action Kamen rồi sau đó xem phim mới. Tuy nhiên, một bầy khỉ bất ngờ tấn công và bắt cóc toàn bộ người lớn đến một hòn đảo bí ẩn. Shinnosuke, em gái Himawari, chó Shiro và nhóm bạn quyết định lên đường giải cứu cha mẹ. Họ chạm trán Paradise King - kẻ điều khiển đàn khỉ cùng âm mưu kỳ lạ trên đảo. Với sự giúp sức của Action Kamen, họ đánh bại hắn và cùng nhau tận hưởng bộ phim yêu thích.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2000, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akiko Yajima","avatar":""},{"name":"Miki Narahashi","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Satomi Korogi","avatar":""},{"name":"Mari Mashiba","avatar":""},{"name":"Tessyo Genda","avatar":""},{"name":"Akio Otsuka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Crayon Shin-chan: Arashi o Yobu Jungle","クレヨンしんちゃん 嵐を呼ぶジャングル","짱구는 못말려 : 폭풍을 부르는 정글","Crayon Shin-chan: The Storm Called The Jungle","Kureyon Shinchan: Arashi o yobu - Jungle","극장판 짱구는 못말려 8기: 폭풍을 부르는 정글","영화 크레용 신짱: 폭풍을 부르는 정글","Crayon Shin-chan - Jungle That Invites Storm","Shin-chan: Perdidos en la jungla","Shin-chan: Bungle in the Jungle","蜡笔小新：呼风唤雨的热带雨林","蜡笔小新：呼风唤雨！森林大冒险","ชินจัง เดอะมูฟวี่ ตอน ดิ้นรนบนเกาะร้าง","映画 クレヨンしんちゃん 嵐を呼ぶ ジャングル","蜡笔小新：呼风唤雨的丛林","蜡笔小新：风起云涌的丛林冒险"]', 1784690324534);
