INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('shin-cau-be-but-chi-con-bao-rung-gia', 'Shin - Cậu Bé Bút Chì: Cơn Bão Rừng Già', 'Crayon Shin-chan: A Storm-invoking Jungle', 'shin - cậu bé bút chì: cơn bão rừng già crayon shin-chan: a storm-invoking jungle akiko yajima miki narahashi keiji fujiwara satomi korogi mari mashiba tessyo genda akio otsuka crayon shin-chan: arashi o yobu jungle クレヨンしんちゃん 嵐を呼ぶジャングル 짱구는 못말려 : 폭풍을 부르는 정글 crayon shin-chan: the storm called the jungle kureyon shinchan: arashi o yobu - jungle 극장판 짱구는 못말려 8기: 폭풍을 부르는 정글 영화 크레용 신짱: 폭풍을 부르는 정글 crayon shin-chan - jungle that invites storm shin-chan: perdidos en la jungla shin-chan: bungle in the jungle 蜡笔小新：呼风唤雨的热带雨林 蜡笔小新：呼风唤雨！森林大冒险 ชินจัง เดอะมูฟวี่ ตอน ดิ้นรนบนเกาะร้าง 映画 クレヨンしんちゃん 嵐を呼ぶ ジャングル 蜡笔小新：呼风唤雨的丛林 蜡笔小新：风起云涌的丛林冒险', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-ngao-giang-ho-2000', 'Tiếu Ngạo Giang Hồ', 'State Of Divinity', 'https://phimimg.com/upload/vod/20250621-1/838208bfe094ba508e52cd183fd3efc9.jpg', 'https://phimimg.com/upload/vod/20250621-1/e0c434e88f43e4032133aa762f4baf5b.jpg', '<p>Lệnh Hồ Xung là một chàng trai nghĩa hiệp có tính cách lanh lợi, tư chất thông minh khác thường. Nhưng khi bị người yêu Nhạc Linh San phụ bạc, đồng môn hiểu lầm và bị trục xuất khỏi sư môn, Lệnh Hồ Xung đã lang thang, phiêu bạt khắp nơi và trải qua rất nhiều sóng gió.

Trên bước đường phiêu bạt đó, Lệnh Hồ Xung đã may mắn được nhiều cao thủ võ lâm truyền thụ võ công và trở thành một trong những đệ nhất võ lâm ở Trung Nguyên. Với tấm lòng nhân ái, luôn biết hy sinh vì người khác, cuối cùng hạnh phúc cũng đến với Lệnh Hồ Xung. Anh đã lọt vào mắt xanh của Thánh cô Nguyệt Thần giáo Nhậm Doanh Doanh.

Cô sẵn sàng từ bỏ danh lợi, chấp nhận hy sinh cả tính mạng để xả thân cứu người mình yêu. Hai con người với tình yêu sâu nặng đã cùng nhau phiêu bạt khắp thế gian để hợp tấu khúc Tiếu Ngạo Giang Hồ do hai bậc tiền nhân là Khúc Dương và Lưu Chính Phong truyền lại.</p>', 'Hoàn Tất (52/52)', 52, 'series', 'completed', 20, 2000, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Anita Yuen Wing-Yee","avatar":""},{"name":"Richie Jen","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"Vivian Chen","avatar":""},{"name":"Leanne Liu","avatar":""},{"name":"Norman Tsui","avatar":""},{"name":"Chang Fu-Chien","avatar":""},{"name":"Ku Kuan-Chung","avatar":""},{"name":"Lee Lichun","avatar":""},{"name":"Sun Xing","avatar":""},{"name":"馬之秦","avatar":""},{"name":"Chu Chung-heng","avatar":""},{"name":"Vega Tsai","avatar":""},{"name":"Lee Chih-Hsi","avatar":""},{"name":"Yue Yueli","avatar":""},{"name":"Lau Lee-Lee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["笑傲江湖任贤齐版","笑傲江湖.2000.任贤齐","Xiao Ao Jiang Hu","Xiao Ao Jianghu","동방불패 1999","소오강호 2000","동방불패","笑傲江湖"]', 1784690324534);
