INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-ta-diet-ma-phan-2', 'Khử Tà Diệt Ma (Phần 2)', 'My Date with a Vampire (Season 2)', 'https://phimimg.com/upload/vod/20250602-1/8ab9df55a1d69fb91cb68e04032ffed7.jpg', 'https://phimimg.com/upload/vod/20250602-1/03458c95cf0661d0fdc4af8c7f334aa0.jpg', '<p>Câu chuyện xoay quanh Phụng Sanh, một cô gái trở thành ma cà rồng sau một vụ tấn công bí ẩn. Trong khi đó, Long Nhạt là một ma đầu và kẻ săn sinh mạng, tạo nên những cuộc phiêu lưu đầy kịch tính và những hiện tượng siêu nhiên bí ẩn. Xuyên suốt bộ phim, những nhân vật này phải đối mặt với nhiều thử thách nguy hiểm và những mối tình phức tạp, đan xen giữa thế giới thực và thế giới ma quái.</p>', 'Hoàn Tất (43/43)', 43, 'series', 'completed', 11, 2000, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Joey Man Yee-Man","avatar":""},{"name":"Eric Wan Tin-Chiu","avatar":""},{"name":"Kenneth Chan","avatar":""},{"name":"Alice Chan Wai","avatar":""},{"name":"Pinky Cheung Man-Chi","avatar":""},{"name":"Wong Shu-Tong","avatar":""},{"name":"Daniel Cheung","avatar":""},{"name":"Thomas Sin Ho-Ying","avatar":""},{"name":"Asuka Higuchi","avatar":""},{"name":"Ricky Chan Po-Yuen","avatar":""},{"name":"Ruco Chan","avatar":""},{"name":"Andrew Yuen","avatar":""},{"name":"Qin Lan","avatar":""},{"name":"Norman Tsui","avatar":""},{"name":"Remus Kam","avatar":""},{"name":"Tats Lau Yee-Tat","avatar":""},{"name":"Jason","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["我和僵尸有个约会","我和殭屍有個約會","나랑 좀비 약속이 있어서"]', 1784690324534);
