INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diep-vu-tokyo', 'Điệp Vụ Tokyo', 'Tokyo Raiders', 'điệp vụ tokyo tokyo raiders lương triều vỹ trịnh y kiện trần tuệ lâm trương bá chi nakamura toru abe hiroshi endo kumiko ozawa maiyu moriyama yuko sirakawa minami nhậm bảo lâm tokyo raiders dong jing gong lüe εισβολή στο τόκυο 東京攻略', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-hai-tu-than-2000', 'Lưỡi Hái Tử Thần', 'Final Destination', 'https://phimimg.com/upload/vod/20250519-1/058b0a728a529a9850c2360e08926fca.jpg', 'https://phimimg.com/upload/vod/20250519-1/968bd7a84017971a705e3e37b694eb0f.jpg', '<p>Trong chuyến đi với lớp mình đến Paris, Alex Browning (diển bởi Devon Sawa) có một điềm báo rằng chuyến máy bay Volee Air Flight 180 sẽ bị nổ tung sau khi cất cánh. Alex cố gắng rời khỏi máy bay và gây ra một cuộc ẩu chiến với bạn mình. Kết quả, anh, một giáo viên dạy thể dục, và một vài học sinh khác bị đuổi ra khỏi máy bay. Chỉ vài phút sau đó, qua cửa sổ kính, họ chứng kiến cảnh máy bay bị nổ tung tại nhà đón khách của sân bay. Trong lúc họ cảm thấy nhẹ nhỏm vì thoát chết, cơn ác mộng lại ập đến khi thấn Chết lần lượt cướp đi sinh mạng từng người một trong số họ.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Devon Sawa","avatar":""},{"name":"Ali Larter","avatar":""},{"name":"Kerr Smith","avatar":""},{"name":"Kristen Cloke","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Chad Donella","avatar":""},{"name":"Amanda Detmer","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Daniel Roebuck","avatar":""},{"name":"Roger Guenveur Smith","avatar":""},{"name":"Brendan Fehr","avatar":""},{"name":"Forbes Angus","avatar":""},{"name":"Lisa Marie Caruk","avatar":""},{"name":"Christine Chatelain","avatar":""},{"name":"Robert Wisden","avatar":""},{"name":"Barbara Tyson","avatar":""},{"name":"Fred Kea","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["死神来了","絕命終結站","Premonição","ファイナルデスティネーション","死神來了","Final Destination"]', 1784690324534);
