INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-toi-el-dorado', 'Đường Tới El Dorado', 'The Road To El Dorado', 'https://phimimg.com/upload/vod/20231015-1/d47cdef93e38a26e57ab182ac30e51d3.jpg', 'https://phimimg.com/upload/vod/20231015-1/c0eaf7b02f2a25d8ef985c8d203305a9.jpg', '<p>Hai kẻ lừa đảo người Tây Ban Nha thắng được tấm bản đồ đến thành phố vàng huyền thoại, nhưng mọi chuyện không diễn ra như kế hoạch khi họ đến El Dorado.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2000, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kenneth Branagh","avatar":""},{"name":"Kevin Kline","avatar":""},{"name":"Rosie Perez","avatar":""},{"name":"Armand Assante","avatar":""},{"name":"Edward James Olmos","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Tobin Bell","avatar":""},{"name":"Elton John","avatar":""},{"name":"Duncan Marjoribanks","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324534);
