INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoc-mat-tho-ngay', 'Nước Mắt Thơ Ngây', 'Innocent Tears', 'https://phimimg.com/upload/vod/20250406-1/2e034950f4f3358baf794fc938ed1481.jpg', 'https://phimimg.com/upload/vod/20250406-1/70d503d9f0111df8b62e0ec96064566e.jpg', '<p>Thảo là một cô bé mồ côi cha, mẹ thì bị bệnh tật. Em phải tự mưu sinh, lượm những chai lọ cũ để bán lấy tiền mua thuốc cho mẹ. Dù cuộc sống của em thiếu thốn nhưng Thảo vẫn luôn nỗ lực để chăm sóc mẹ – người duy nhất còn lại bên em. Ngược lại, Hùng đầy đủ vật chất nhưng lại thiếu thốn tình cảm gia đình. Mẹ Hùng mải mê với công việc kiếm tiền, còn cha của Hùng lại ngoại tình, khiến gia đình trở nên rạn nứt. Khi Hùng gặp Thảo, một cô bé đơn độc và đầy nghị lực, cậu bắt đầu cảm nhận tình yêu thương và sự gắn kết gia đình. Hùng quyết định bỏ nhà đi bụi, hy vọng ba mẹ của cậu suy nghĩ lại và thay đổi...</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thanh Thủy","avatar":""},{"name":"Ngọc Trai","avatar":""},{"name":"Kim Khánh","avatar":""},{"name":"Hoàng Phúc","avatar":""},{"name":"Vân Anh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324534);
