INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nuoc-mat-tho-ngay', 'Nước Mắt Thơ Ngây', 'Innocent Tears', 'nước mắt thơ ngây innocent tears thanh thủy ngọc trai kim khánh hoàng phúc vân anh 插翅难飞 vol à haut risque flight risk', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-tia-chop', 'Siêu Nhân Tia Chớp', 'Power Rangers Lightspeed Rescue', 'https://phimimg.com/upload/vod/20250320-1/23941b9e79c9879b4cd45d75e13434cf.jpg', 'https://phimimg.com/upload/vod/20250320-1/f5011fde3119ff0d2e4f7bd49d9a38e1.jpg', '<p>Hàng nghìn năm trước đây, Bốn con quỷ đã bị phong ấn trong một hầm mộ bởi một thầy phù thủy. Một nhóm người du lịch vô tình đã mở phong ấn, giải thoát cho 4 con quỷ này. Bọn chúng dưới sự dẫn dắt bởi Diabolico đã trở về tòa lâu đài sau nghìn năm , tiếp tục gây sóng gió cho cuộc sống con người . Bên cạnh đó , một thành phố của Mỹ được biết đến với cái tên Vịnh thủy thủ với sự bảo vệ của tổ chức cứu hộ Lightspeed đã lên một kế hoạch khẩn cấp triệu tập 5 người và dùng công nghệ của tổ chức biến họ thành những chiến binh có đủ sức chống lại Diabolico với âm mưu thống trị thế giới loài người . 5 người được chọn được gọi bằng cái tên “Đội cứu hộ tia chớp” .</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 12, 2000, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Power Rangers Super Megaforce Finale: Legendary Battle","Power Rangers Super Megaforce: The Legendary Battle"]', 1784690324534);
