INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuan', 'Thanh Xuân', 'Plum Blossom', 'https://phimimg.com/upload/vod/20250210-1/802d1cb9a01bae7d1a8e89d660bcc53c.jpg', 'https://phimimg.com/upload/vod/20250210-1/3e7a14e36f1976c83710ee123b745619.jpg', '<p>Học sinh cuối cấp trung học, Jayo bị bạn cùng lớp Hara dụ dỗ vào trải nghiệm tình dục đầu tiên, người cuối cùng đã tự sát khi anh phớt lờ cô. Kể từ đó, anh đắm mình trong tình yêu không tình yêu cho đến khi gặp được y tá vui vẻ Namok. Trong khi đó, người bạn Seuin của anh đã phải lòng giáo viên của mình, điều này là điều cấm kỵ trong xã hội thời bấy giờ.</p>', 'Full', 1, 'single', 'completed', 11, 2000, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Rae-won","avatar":""},{"name":"Kim Jeong-hyeon","avatar":""},{"name":"Jin Hee-kyung","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"Yoon Ji-hye","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Cheongchun","靑春","青春","Youth","청춘"]', 1784690324534);
