INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-co-nang-gilmore-phan-1', 'Những Cô Nàng Gilmore (Phần 1)', 'Gilmore Girls (Season 1)', 'những cô nàng gilmore (phần 1) gilmore girls (season 1) lauren graham alexis bledel scott patterson melissa mccarthy keiko agena yanic truesdale liza weil sean gunn matt czuchry kelly bishop edward herrmann gilmore girls: tal mãe, tal filha gilmore girls', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ay-la-chuyen-nho-phan-3', 'Chuyện Ấy Là Chuyện Nhỏ (Phần 3)', 'Sex And The City (Season 3)', 'https://phimimg.com/upload/vod/20250115-1/ce5cc729bd0267ace547bb91148eec21.jpg', 'https://phimimg.com/upload/vod/20250115-1/fa58783f7abcb5f31a8d92ade66d9385.jpg', '<p>Lấy bối cảnh và quay tại thành phố New York, loạt chương trình có chủ đề xoay quanh cuộc sống của một nhóm bạn gồm bốn người phụ nữ: ba người ngoài ba mươi tuổi và một người khoảng bốn mươi tuổi. Mặc dù mỗi người đều có những tính cách riêng biệt và cuộc sống tình yêu khác nhau, nhưng họ vẫn không thể tách rời và luôn tâm sự, trò chuyện với nhau. Với sự tham gia của Sarah Jessica Parker (trong vai Carrie Bradshaw), Kim Cattrall (trong vai Samantha Jones), Kristin Davis (trong vai Charlotte York) và Cynthia Nixon (trong vai Miranda Hobbes), bộ phim liên tục có nhiều cốt truyện xoay quanh vấn đề xã hội hiện đại và thường liên quan đến các vấn đề như tình dục, tình yêu, chuyện ngoại tình và cuộc sống của phái nữ, đồng thời cho khán giả được khám phá sự khác biệt trong tình bạn và các mối quan hệ lãng mạn qua những góc nhìn khác nhau của 4 nhân vật chính trong phim.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 12, 2000, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sarah Jessica Parker","avatar":""},{"name":"Kim Cattrall","avatar":""},{"name":"Cynthia Nixon","avatar":""},{"name":"Kristin Davis","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sex & the City","SATC","Sex and the City"]', 1784690324534);
