INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-ay-la-chuyen-nho-phan-3', 'Chuyện Ấy Là Chuyện Nhỏ (Phần 3)', 'Sex And The City (Season 3)', 'chuyện ấy là chuyện nhỏ (phần 3) sex and the city (season 3) sarah jessica parker kim cattrall cynthia nixon kristin davis sex & the city satc sex and the city', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-tro-choi-2000', 'Vua Trò Chơi', 'Yu-Gi-Oh! Duel Monsters', 'https://phimimg.com/upload/vod/20241124-1/5b9a1d1216a06bb3244c3fdb1929674a.jpg', 'https://phimimg.com/upload/vod/20241124-1/39cae382ef85b1fb744f95ecd2f898e7.jpg', '<p>Yu-Gi-Oh! Duel Monsters kể về Muto Yugi, một học sinh trường Domino có tính cách nhút nhát, hiền lành. Cậu là cháu nội của Muto Sugoroku. Trước đây, ông cậu vốn là một kiện tướng chơi trò chơi cực kì xuất sắc. Từ nhỏ, ông của Yugi đã dạy cậu chơi các trò chơi, và ông còn cho cậu một bộ xếp hình. Trong khoảng gần bảy năm, cậu đã tìm tòi để lắp ráp thành Trò chơi Ngàn năm (Bộ ghép hình Ngàn Năm). Nhưng cậu đã không thể hoàn thành được vì mảnh chính của trò chơi bị Jonouchi Katsuya chơi xỏ, ném xuống nước. Sau đó, cảm kích vì Yugi đã bảo vệ mình trong một lần bị đội trưởng đội kỉ luật có tính cách du côn đánh, họ trở thành bạn của nhau. Jonouchi lặn xuống nước và lấy lại mảnh chính đưa cho ông nội Yugi.</p>', 'Hoàn Tất (224/224)', 224, 'hoathinh', 'completed', 16, 2000, 'Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroki Takahashi","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["يوغي اوه مبارزة الوحوش","يوغي ي","Yu-Gi-Oh! Dvoboj čudovišta","Ю-Ги-О!","Yu-Gi-Oh! Monstros de Duelo","游戏王DM","游戏王 - 怪兽之决斗","游戏王-怪兽之决斗","游戏王—怪兽之决斗","Yu-Gi-Oh! Duel de Monstres","Yu-Gi-Oh! a Toi de Jouer!","遊戲王","Yu-Gi-Oh!","יוגי-הו!","遊☆戯☆王","Yu☆Gi☆Oh! Dyueru Monsutāzu","Yū Gi Ō Dyueru Monsutāzu","유희왕 듀얼몬스터즈","Yu-Gi-Oh! Duelul Monștrilor","ยูกิโอ ดูเอลมอนสเตอร์","遊戲王 怪獸之決鬥","Yu-Gi-Oh! Rulers of the Due