INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vua-tro-choi-2000', 'Vua Trò Chơi', 'Yu-Gi-Oh! Duel Monsters', 'vua trò chơi yu-gi-oh! duel monsters hiroki takahashi يوغي اوه مبارزة الوحوش يوغي ي yu-gi-oh! dvoboj čudovišta ю-ги-о! yu-gi-oh! monstros de duelo 游戏王dm 游戏王 - 怪兽之决斗 游戏王-怪兽之决斗 游戏王—怪兽之决斗 yu-gi-oh! duel de monstres yu-gi-oh! a toi de jouer! 遊戲王 yu-gi-oh! יוגי-הו! 遊☆戯☆王 yu☆gi☆oh! dyueru monsutāzu yū gi ō dyueru monsutāzu 유희왕 듀얼몬스터즈 yu-gi-oh! duelul monștrilor ยูกิโอ ดูเอลมอนสเตอร์ 遊戲王 怪獸之決鬥 yu-gi-oh! rulers of the duel yu-gi-oh! enter the shadow realm yu-gi-oh! waking the dragons yu-gi-oh! grand championship yu-gi-oh! dawn of the duel 遊☆戯☆王デュエルモンスターズ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-sopranos-phan-2', 'Gia Đình Sopranos (Phần 2)', 'The Sopranos (Season 2)', 'https://phimimg.com/upload/vod/20241105-1/3f643a5a1871d0306b4bb04c41b29d10.jpg', 'https://phimimg.com/upload/vod/20241105-1/a4e1aeef446f7c9d5de8d36a76d3ec31.jpg', '<p>Chú của anh ấy đang ở trong tù. Mẹ anh ấy đang ở trong bệnh viện. Người bạn thân nhất của anh ấy vẫn đang mất tích. Em gái anh ấy sắp chuyển nhà. Các cuộc tấn công hoảng loạn của anh ấy đã trở lại. Và người thu nhỏ của anh ấy từ chối gặp anh ấy. Tony Soprano gần đây đã được nâng lên thành trùm băng đảng sau một vụ phá sản liên bang và khi mùa thứ hai bắt đầu, Tony đang bị căng thẳng hơn bao giờ hết khi giải quyết các yêu cầu của vị trí mới của mình. Tệ hơn nữa, người chị gái thất lạc từ lâu Janice của anh đã đến để chăm sóc người mẹ ốm yếu của họ.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 12, 2000, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Gandolfini","avatar":""},{"name":"Edie Falco","avatar":""},{"name":"Jamie-Lynn Sigler","avatar":""},{"name":"Robert Iler","avatar":""},{"name":"Lorraine Bracco","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Steven Van Zandt","avatar":""},{"name":"Tony Sirico","avatar":""},{"name":"Dominic Chianese","avatar":""},{"name":"Aida Turturro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Família Soprano","人在江湖","Rodina Sopránů","آل سوبرانو","סופרנוס","द सोप्रानोस","سوپرانو","خانواده سوپرانو","سوپرانوز","Rodzina Soprano","Семья Сопрано","Клан Сопрано","The Sopranos"]', 1784690324534);
