INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-sopranos-phan-2', 'Gia Đình Sopranos (Phần 2)', 'The Sopranos (Season 2)', 'gia đình sopranos (phần 2) the sopranos (season 2) james gandolfini edie falco jamie-lynn sigler robert iler lorraine bracco michael imperioli steven van zandt tony sirico dominic chianese aida turturro família soprano 人在江湖 rodina sopránů آل سوبرانو סופרנוס द सोप्रानोस سوپرانو خانواده سوپرانو سوپرانوز rodzina soprano семья сопрано клан сопрано the sopranos', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-mua-thu', 'Trái Tim Mùa Thu', 'Autumn in My Heart', 'https://phimimg.com/upload/vod/20241029-1/d3de6849644e64049c84d4684dd7b32b.jpg', 'https://phimimg.com/upload/vod/20241029-1/db3c3f004471186d48e1d5ed5a915b50.jpg', '<p>Tác phẩm đầu tiên nằm trong loạt phim bốn mùa của đạo diễn Yoon Seok Ho. Phim là câu chuyện tình yêu buồn da diết giữa Joon Seo (Song Seung Hun) và Eun Seo (Song Hye Kyo). Vì một hành động vô tình của cậu bé Joon Seo khi mọi người không chú ý mà Eun Seo đã bị tráo đổi thành em gái ruột của cậu trong phòng hộ sinh. Cả hai đã cùng lớn lên trong một gia đình được cha mẹ yêu thương hết mực, nhưng một tai nạn bất ngờ xảy ra với cô bé Eun Seo. Và cũng từ đây, sự thật cô bé không phải là con ruột trong gia đình ông bà Choi được sáng tỏ. 8 năm sau, họ lại cùng nhau viết tiếp một câu chuyện tình đẫm nước mắt khi yêu nhau mà không thể sống trọn đời bên nhau.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 12, 2000, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"송승헌","avatar":""},{"name":"송혜교","avatar":""},{"name":"원빈","avatar":""},{"name":"한채영","avatar":""},{"name":"Han Na-na","avatar":""},{"name":"Choi Woo-hyuk","avatar":""},{"name":"문근영","avatar":""},{"name":"Lee Ae-jung","avatar":""},{"name":"선우은숙","avatar":""},{"name":"정동환","avatar":""},{"name":"이한위","avatar":""},{"name":"김해숙","avatar":""},{"name":"김나운","avatar":""},{"name":"Kim Hyeong-jong","avatar":""},{"name":"Seo Yoon-jae","avatar":""},{"name":"Ahn Seo-jung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Qəlbimdəki Payız","秋天的童话","가을동화","Gaeul donghwa","Endless Love: Autumn in My Heart","รักนี้ชั่วนิรันดร์","Autumn Tale","Autumn Fairy Tale","Endless Love"]', 1784690324534);
