INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-bat-kha-thi-2', 'Nhiệm Vụ: Bất Khả Thi 2', 'Mission: Impossible II', 'https://phimimg.com/upload/vod/20231014-1/8476bbd55d313d1a04469ad6f2909211.jpg', 'https://phimimg.com/upload/vod/20231014-1/ae8b57ce462fbed98c0bef83b01d7368.jpg', '<p>Tom Cruise trong M:I-2 tiếp tục làm &quot;nức lòng&quot; các cô gái trẻ trong phần tiếp theo bộ phim M:I đã khá thành công. Một loại virus dịch bệnh cực kì nguy hiểm bị một băng nhóm cướp được với mưu đồ đen tối. Nhiệm vụ của anh là phải hủy con virus đó. Phim có nhiều pha hành động nghẹt thở, dưới tài diễn xuất của chàng diễn viên điển trai Tom Cruise.</p>', 'Full', 1, 'single', 'completed', 10, 2000, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Dougray Scott","avatar":""},{"name":"Thandiwe Newton","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Richard Roxburgh","avatar":""},{"name":"John Polson","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Rade Šerbedžija","avatar":""},{"name":"William Mapother","avatar":""},{"name":"Dominic Purcell","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324534);
