INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhiem-vu-bat-kha-thi-2', 'Nhiệm Vụ: Bất Khả Thi 2', 'Mission: Impossible II', 'nhiệm vụ: bất khả thi 2 mission: impossible ii tom cruise dougray scott thandiwe newton ving rhames richard roxburgh john polson brendan gleeson rade šerbedžija william mapother dominic purcell ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-2000', 'Bí Mật', 'The Secret', 'https://phimimg.com/upload/vod/20240906-1/f3176dc288710a0b93d83ac94b901b4b.jpg', 'https://phimimg.com/upload/vod/20240906-1/859d9173c157f1192d79e585b1a940cc.jpg', '<p>Marie, một nhân viên bán bách khoa toàn thư tận nhà thành công, đã kết hôn với chồng là Francois được 12 năm và có một cậu con trai hai tuổi. Mặc dù cô ấy tương đối hài lòng với cuộc sống của mình nhưng cô ấy vẫn cảm thấy có điều gì đó thiếu sót. Nhập Bill người Mỹ gốc Phi 50 tuổi. Ban đầu, cô khó chịu vì sự thiếu kiên nhẫn của anh, nhưng cô nhận ra rằng mình bị anh thu hút không thể cưỡng lại. Chẳng bao lâu sau, cả hai đang ở giữa một mối tình bất chính bẩn thỉu. Cô ấy biết rất ít về người yêu mới của mình và anh ấy dường như không quan tâm đến việc tìm hiểu về cô ấy, nhưng thời gian làm tình kéo dài lại hoàn toàn là một điều khác. Cảm thấy mất kiểm soát, Marie ngày càng bị đẩy lùi bởi hành động của chính mình. Về mặt tâm lý, cô đấu tranh để dung hòa những cuộc gặp gỡ nóng bỏng với Bill và những công việc nhà tầm thường như tắm rửa cho con trai. Hơn nữa, cô thấy mình không có khả năng che giấu hành vi ngoại tình của mình mà trở về nhà với những vết trầy xước và dấu hôn khắp người trước sự tàn phá của Francois.</p>', 'Full', 1, 'single', 'completed', 10, 2000, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Anne Coesens","avatar":""},{"name":"Michel Bompoil","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Jacqueline Jehanneuf","avatar":""},{"name":"Aladin Reibel","avatar":""},{"name":"Quentin Rossi","avatar":""},{"name":"Valérie Vogt","avatar":""},{"name":"Frédéric Sauzay","avatar":""},{"name":"Natalya Ermilova","avatar":""},{"name":"Charlotte Pradon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324534);
