INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan', 'Mỹ Nhân', 'La Belle', 'https://phimimg.com/upload/vod/20240905-1/d7b85075be1a565490930fac72d77f37.jpg', 'https://phimimg.com/upload/vod/20240905-1/22b6a22461ae9477bcf735d7a97ebdad.jpg', '<p>Vào một đêm mưa u ám, một nhà văn bất ngờ gặp được người phụ nữ trong quá khứ của anh đến thăm. Tìm kiếm sự cô đơn từ người yêu cũ, cô tìm thấy niềm an ủi ở người đàn ông này và kể từ ngày đó, họ trân trọng từng tấc cơ thể của nhau và say mê trong sung sướng cho đến khi quá khứ bị cấm đoán của cô dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 12, 2000, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Ji-hyeon","avatar":""},{"name":"오지호","avatar":""},{"name":"Cho Gyeong-han","avatar":""},{"name":"Cho Jong-uk","avatar":""},{"name":"Park Seong-min","avatar":""},{"name":"Koo Bon-yeong","avatar":""},{"name":"Seo Dong-hui","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324534);
