INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trom-long-trao-phung-1', 'Trộm Long Tráo Phụng 1', 'Stealing Dragon Exchanging Phoenix', 'https://phimimg.com/upload/vod/20240628-1/9e716e3d7e94852e6761174952193d1a.jpg', 'https://phimimg.com/upload/vod/20240628-1/53927b9dabb57df95276ad1ecd11078c.jpg', '<p><em>Một vị ái phi của vua vì muốn được làm hoàng hậu đã nỡ lòng đem tráo đổi đứa con gái mới sinh với người con trai của một vị quan trong triều đình. Tuy vậy bà yêu đứa con ruột của mình thắm thiết nên trước khi đem con đi bà đã cắn vào cánh tay nó để làm dấu. Nhưng người phu nhân của vị quan thì không cam tâm, đã đem công chúa bỏ trước một lầu xanh để trả thù vị ái phi kia, và đem cháu gái mình thế vào chỗ. Thời gian trôi qua, vị hoàng tử lớn lên và đã trở thành vua. Tính tình ham chơi nên ông cải trang để gia nhập với giới dân gian. Và trời đất xui khiến đã cho ông gặp được nàng công chúa bị bỏ rơi năm xưa.</em></p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 18, 2000, 'Lồng Tiếng', 'HD', 'Đài Loan', 0, '[{"name":"Trương Đình","avatar":""},{"name":"Tiêu Ân Tuấn","avatar":""},{"name":"Ngưu Lợi","avatar":""},{"name":"Ngưu Thanh Phong","avatar":""},{"name":"Ngô Mạnh Đạt","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324534);
