INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-phap-ton-tu-va-36-ke', 'Binh Pháp Tôn Tử Và 36 Kế', 'Sun Tzu''s The Art Of War And The Thirty Six Stratagems', 'https://phimimg.com/upload/vod/20240624-1/127e76abf8e13ec986cc7aed7e39347a.jpg', 'https://phimimg.com/upload/vod/20240624-1/ee3d5b0fe21c8cccff82c3f99593ad85.jpg', '<p>Lấy bối cảnh thời Chiến Quốc của Trung Quốc cổ đại, bộ phim kể về câu chuyện của Sun Bin, hậu duệ của Tôn Tử và đối thủ của ông là Pang Juan.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 11, 2000, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324534);
