INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('binh-phap-ton-tu-va-36-ke', 'Binh Pháp Tôn Tử Và 36 Kế', 'Sun Tzu''s The Art Of War And The Thirty Six Stratagems', 'binh pháp tôn tử và 36 kế sun tzu''s the art of war and the thirty six stratagems  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-4-thu-pham-trong-doi-mat', 'Thám Tử Lừng Danh Conan 4: Thủ Phạm Trong Đôi Mắt', 'Detective Conan: Captured in Her Eyes', 'https://phimimg.com/upload/vod/20231016-1/7cd867bc0925ad22de3d8e30ef82c61d.jpg', 'https://phimimg.com/upload/vod/20231016-1/0a56158ad654906550fb23dafc6df144.jpg', '<p>Một vụ ám sát đã xảy ra trước mắt Conan. Nạn nhân là cảnh sát Narasawa Osamu hiện đang điều tra vụ án từ 1 năm trước. Quan sát thấy hung thủ cầm ô tay tay phải nên Conan suy luận ra hắn thuận tay trái. Ngay sau đó, vụ thứ 2 đã xảy ra. Người bị giết là cảnh sát Shiba Yoichiro bị bắn ở hầm gửi xe Midoridai. Dựa vào vỏ đạn thu ở hiện trường cảnh sát biết được hai cảnh sát bị giết cùng một khẩu súng. Liệu 2 vụ án này có liên quan đến nhau? Vụ án Narasawa và Shiba điều tra là gì? Thủ phạm vụ án 1 năm trước có liên quan đến 2 vụ án hiện tại không? Ai sẽ là mục tiêu tiếp theo của hắn?</p>', 'Full', 1, 'hoathinh', 'completed', 12, 2000, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Atsuko Yuya","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Gara Takashima","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Isshin Chiba","avatar":""},{"name":"Asako Dodo","avatar":""},{"name":"Hisao Egawa","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324534);
