INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-lung-danh-conan-4-thu-pham-trong-doi-mat', 'Thám Tử Lừng Danh Conan 4: Thủ Phạm Trong Đôi Mắt', 'Detective Conan: Captured in Her Eyes', 'thám tử lừng danh conan 4: thủ phạm trong đôi mắt detective conan: captured in her eyes minami takayama wakana yamazaki atsuko yuya akira kamiya kappei yamaguchi gara takashima kenichi ogata yukiko iwai naoko matsui megumi hayashibara chafurin ikue otani isshin chiba asako dodo hisao egawa ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-ky-phan-2', 'Tây Du Ký (Phần 2)', 'Journey To The West (Season 2)', 'https://phimimg.com/upload/vod/20240811-1/66934a36eddb4897afd28c5694d7886a.jpg', 'https://phimimg.com/upload/vod/20240811-1/f7f81c97816dcd3fa79928c74e6b835a.jpg', '<p>Bộ phim ra đời trong hoàn cảnh khó khăn do được sản xuất vào thập kỉ 1980 thời mà kĩ xảo điện ảnh còn thô sơ lạc hậu. Vốn đầu tư 6 triệu nhân dân tệ tuy là một khoản tiền rất lớn nhưng cũng không đủ trang trải cho toàn bộ phim, các diễn viên cũng chỉ nhận được thù lao tượng trưng, ít ỏi. Phim được làm trong 6 năm trời ròng rã từ năm 1982 đến năm 1988 hoàn thành. Nhiều thông tin cung cấp năm 1986 bộ phim chính thức trình chiếu cho khán thính giả và nhận thấy có nhiều phần thiếu sót nên tiếp tục đầu tư xây dựng và mãi đến năm 1988 thì chính thức hoàn thiện. &nbsp;Đặc biệt, trong 20 năm qua, phim đã nhiều lần phát sóng lại, mỗi lần cả người lớn và trẻ em đều háo hức đón xem. Có thể nói, bản phim Tây Du Kí 1986 đã sống mãi với thời gian và ăn sâu trong kí ức của nhiều thế hệ khán giả. Hầu hết các đài truyền hình của Việt Nam đều ít nhất trình chiếu một lần. Có đài phát sóng đến gần 10 lần và trình chiếu đi và chiếu lại suốt nhiều năm liền.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 15, 2000, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Jinlai","avatar":""},{"name":"Cui Jingfu","avatar":""},{"name":"Liu Dagang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324534);
