INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-qua-nhiet-tinh-phan-1', 'Đừng Quá Nhiệt Tình (Phần 1)', 'Curb Your Enthusiasm (Season 1)', 'https://phimimg.com/upload/vod/20240808-1/a658f1d93601f228af2e01f740ca7539.jpg', 'https://phimimg.com/upload/vod/20240808-1/415c32c110e5c9d9a36c0b7ecaa6dfaf.jpg', '<p>Tầm nhìn hài hước, không theo kịch bản của Larry David, người đóng vai chính mình trong một vũ trụ song song, nơi anh dường như không thể làm bất cứ điều gì đúng đắn, và theo tiêu chuẩn của anh, thì không ai khác có thể làm đúng được.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 12, 2000, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Larry David","avatar":""},{"name":"Jeff Garlin","avatar":""},{"name":"Susie Essman","avatar":""},{"name":"Cheryl Hines","avatar":""},{"name":"J.B. Smoove","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324534);
