INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-tay-du-ky-giai-cuu-phat-to', 'Hậu Tây Du Ký (Giải Cứu Phật Tổ)', 'Journey to the West Afterstory', 'https://phimimg.com/upload/vod/20240611-1/14ea33cec2148ab99cb56fc262c826d0.jpg', 'https://phimimg.com/upload/vod/20240611-1/010f6e5aca51c80cdbb2072a6fabf986.jpg', '<p>Hậu Tây du ký (tên gốc tiếng Trung là 西游记后传, tức Tây du ký hậu truyện) là bộ phim truyền hình dài 30 tập do Trung Quốc sản xuất năm 2000 do Tào Vinh làm đạo diễn, nội dung chủ yếu kể chuyện thầy trò Đường Tăng sau khi thỉnh kinh xong, Như Lai Phật Tổ viên tịch, đại ma đầu là Vô Thiên lợi dụng cơ hội thống trị tam giới, cuối cùng bị Tôn Ngộ Không tiêu diệt, tam giới lại được khôi phục</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 16, 2000, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Cho Wing","avatar":""},{"name":"Huang Haibing","avatar":""},{"name":"Hei Zi","avatar":""},{"name":"Wu Jian","avatar":""},{"name":"Yu Zhen","avatar":""},{"name":"Lv Hanbiao","avatar":""},{"name":"Ma Jielin","avatar":""},{"name":"Li Jing","avatar":""},{"name":"Zhang Zhiwei","avatar":""},{"name":"Qiu Yue","avatar":""},{"name":"Fu Yujia","avatar":""},{"name":"Cui Dai","avatar":""},{"name":"Shan Lianli","avatar":""},{"name":"Li Jun","avatar":""},{"name":"Ma Yashu","avatar":""},{"name":"Yu Yuexian","avatar":""},{"name":"Juan Zi","avatar":""},{"name":"Tongyi Dang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324534);
