INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-rong-khoi-dau-moi', 'Tim Rồng: Khởi Đầu Mới', 'DragonHeart: A New Beginning', 'https://phimimg.com/upload/vod/20231016-1/2f1cdcb12bf975cfdc1e7d38db493b7d.jpg', 'https://phimimg.com/upload/vod/20231016-1/681de0f729ee68b62ea871d71a536735.jpg', '<p>Khi Geoff, một cậu bé chăn ngựa mồ côi (Chris Masterson), phát hiện ra Drake (lồng tiếng cho Robby Benson), con rồng cuối cùng còn sống trên thế giới, cậu nhận ra rằng giấc mơ trở thành hiệp sĩ trong bộ áo giáp sáng ngời giờ đây có thể trở thành hiện thực. Cùng nhau, họ sớm phải đối mặt với những thử thách biến họ thành anh hùng. Nhưng bị cuốn vào niềm phấn khích của cuộc sống mới, Geoff và Drake không nhận ra những mối nguy hiểm tiềm ẩn đang vây quanh họ.</p>', 'Full', 1, 'single', 'completed', 11, 2000, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Christopher Masterson","avatar":""},{"name":"Harry Van Gorkum","avatar":""},{"name":"Rona Figueroa","avatar":""},{"name":"Matt Hickey","avatar":""},{"name":"Henry O","avatar":""},{"name":"Tom Burke","avatar":""},{"name":"Robby Benson","avatar":""},{"name":"Ken Shorter","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324534);
