INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-flintstones-o-viva-rock-vegas', 'Gia Đình Flintstones ở Viva Rock Vegas', 'The Flintstones in Viva Rock Vegas', 'https://phimimg.com/upload/vod/20231016-1/19c5857c8776005863bbb909654dcbfe.jpg', 'https://phimimg.com/upload/vod/20231016-1/e5c818134de7d7e217d006f578cba83e.jpg', '<p>Flintstones lại đạt được mục tiêu đó. Nhóm Flintstones và nhóm Rubbles tới Rock Vegas còn Fred hy vọng tán tỉnh được Wilma đáng yêu. Không có gì có thể cản trở tình yêu, ngoại trừ Chip Rockefeller thông đồng, một tay chơi sinh ra ở Baysville nhưng lại thành công ở thị trấn khốc liệt Rock Vegas. Liệu Fred có giành được tình yêu của Wilma?</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Addy","avatar":""},{"name":"Stephen Baldwin","avatar":""},{"name":"Kristen Johnston","avatar":""},{"name":"Jane Krakowski","avatar":""},{"name":"Joan Collins","avatar":""},{"name":"Thomas Gibson","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Harvey Korman","avatar":""},{"name":"Alex Meneses","avatar":""},{"name":"John Taylor","avatar":""},{"name":"Tony Longo","avatar":""},{"name":"Danny Woodburn","avatar":""},{"name":"Taylor Negron","avatar":""},{"name":"Jack McGee","avatar":""},{"name":"David Jean Thomas","avatar":""},{"name":"Brian Coughlin","avatar":""},{"name":"Richard Karron","avatar":""},{"name":"Je","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324534);
