INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('102-chu-cho-dom', '102 Chú Chó Đốm', '102 Dalmatians', 'https://phimimg.com/upload/vod/20231016-1/e953f2872934ec10bdf3e6e29924742b.jpg', 'https://phimimg.com/upload/vod/20231016-1/2ad7095950f1fd25da9e274e593c1f90.jpg', '<p>Hãy sẵn sàng cho một khoảng thời gian vui vẻ khi một loạt các anh hùng động vật không thể cưỡng lại hoàn toàn mới được tung ra trong cái đuôi gia đình tuyệt vời này! Trong một liên minh khó có thể xảy ra, Waddlesworth hung hãn - một con vẹt luôn nghĩ mình là Rottweiler - hợp tác với Oddball - một chú chó đốm không có dấu hiệu mong muốn giành được vị trí của mình! Họ cùng nhau bắt tay vào một nhiệm vụ đầy cười để đánh lừa Cruella De Vil đầy mưu mô.</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Glenn Close","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"Ioan Gruffudd","avatar":""},{"name":"Alice Evans","avatar":""},{"name":"Tim McInnerny","avatar":""},{"name":"Eric Idle","avatar":""},{"name":"Ben Crompton","avatar":""},{"name":"Carol MacReady","avatar":""},{"name":"Ian Richardson","avatar":""},{"name":"Jim Carter","avatar":""},{"name":"Ron Cook","avatar":""},{"name":"Timothy West","avatar":""},{"name":"David Horovitch","avatar":""},{"name":"Dick Brannick","avatar":""},{"name":"Mike Hayley","avatar":""},{"name":"Nicholas Hutchison","avatar":""},{"name":"Tim Willcox","avatar":""},{"name":"June Watso","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324534);
