INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-song-con-2000', 'Cuộc Chiến Sống Còn', 'Battle Royale', 'https://phimimg.com/upload/vod/20231016-1/c5e49d7d8c13f6dcfe177751017e6f82.jpg', 'https://phimimg.com/upload/vod/20231016-1/cba4378f24c9243e1138c85d71abd5fc.jpg', '<p>Battle Royale - Batoru rowaiaru là một bộ phim phiêu lưu, bạo lực của Nhật Bản sản xuất năm 2000, được chuyển thể từ cuốn tiểu thuyết cùng tên của tác giả Koushun Takami. Đây cũng chính là bộ phim cuối cùng do Kinji Fukasaku làm đạo diễn. Bộ phim đã gây ra sự tranh cãi và đã bị cấm hoặc loại trừ khỏi việc phân phối ở một số quốc gia. Thậm chí đến nay nhiều người vẫn lầm tưởng Mỹ cấm không cho phát hành bộ phim này tại đất nước mình nhưng thực ra là người Nhật, chính xác là công ty Toei đã từ chối bán bán bản quyền bộ phim này cho bất kỳ nhà phân phối nào tại Hoa Kỳ trong một thời gian dài, bởi vì công ty Toei lo lắng về những tranh cãi và vụ kiện tiềm ẩn về sau (cho đến khi Anchor Bay Entertainment cuối cùng cũng đã được mua lại bộ phim vào năm 2010 để phát hành dưới dạng video trực tuyến).</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tatsuya Fujiwara","avatar":""},{"name":"Aki Maeda","avatar":""},{"name":"Takeshi Kitano","avatar":""},{"name":"Tarô Yamamoto","avatar":""},{"name":"Masanobu Ando","avatar":""},{"name":"Ko Shibasaki","avatar":""},{"name":"Chiaki Kuriyama","avatar":""},{"name":"Takashi Tsukamoto","avatar":""},{"name":"Sousuke Takaoka","avatar":""},{"name":"Yukihiro Kotani","avatar":""},{"name":"Eri Ishikawa","avatar":""},{"name":"Sayaka Kamiya","avatar":""},{"name":"Takayo Mimura","avatar":""},{"name":"Yutaka Shimada","avatar":""},{"name":"Ren Matsuzawa","avatar":""},{"name":"Hirohito Honda","avatar":""},{"name":"Ryou","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324534);
