INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phim-kinh-di-hai-my-1', 'Phim Kinh Dị Hài Mỹ 1', 'Scary Movie', 'https://phimimg.com/upload/vod/20231014-1/9035d1d7d40d884a8823fced9b79cb86.jpg', 'https://phimimg.com/upload/vod/20231014-1/c7102cc371cf8a07ec2f9467f975649c.jpg', '<p>Phim kinh dị (Scary Movie) là một series phim hài thú vị. Trong phần 1, phim tập trung nhái mấy cảnh trong mấy phim kinh di như: I Know What You Did Last Summer, Scream nhưng thay vì những cảnh quay đáng sợ như phiên bản gốc, sự hài hước xuất hiện ở từng chi tiết, từng nhân vật, từng cảnh quay trong phim và sẽ theo người xem từ đầu đến cuối phim. Đây được xem là đối thủ đáng gờm của American Pie.</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anna Faris","avatar":""},{"name":"Jon Abrahams","avatar":""},{"name":"Marlon Wayans","avatar":""},{"name":"Shawn Wayans","avatar":""},{"name":"Regina Hall","avatar":""},{"name":"Shannon Elizabeth","avatar":""},{"name":"Cheri Oteri","avatar":""},{"name":"Carmen Electra","avatar":""},{"name":"Tanja Reichert","avatar":""},{"name":"Lochlyn Munro","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324534);
