INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phim-kinh-di-hai-my-1', 'Phim Kinh Dị Hài Mỹ 1', 'Scary Movie', 'phim kinh dị hài mỹ 1 scary movie anna faris jon abrahams marlon wayans shawn wayans regina hall shannon elizabeth cheri oteri carmen electra tanja reichert lochlyn munro ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-binh-thien-quoc', 'Thái Bình Thiên Quốc', 'Thái Bình Thiên Quốc', 'https://phimimg.com/upload/vod/20240620-1/aefde804499e37bd5e83391f1d8ea501.jpg', 'https://phimimg.com/upload/vod/20240620-1/2bc0bf425b828857c7c52f848d555156.jpg', '<p><em>Bối cảnh phim là thời gian sau cuộc chiến tranh nha phiến năm 1840. Không chịu được sự đàn áp tàn khốc của triều đình nhà Thanh và sự bóc lột đến tận cùng của bọn xâm lược nước ngoài, nhiều người dân trên khắp đất nước TƯ đã anh dũng vùng lên kháng cự. Ngày 11/1/1851, Hội Bái Thượng Ðế do Hồng Tú Toàn đứng đầu đã tuyên bố khởi nghĩa tại thôn Kim Ðiền, huyện Quế Bình, tỉnh Quảng Tây, tự xưng là Thái Bình Thiên Quốc. Sau 2 năm 3 tháng tuyên bố khởi nghĩa, nghĩa quân đã chiếm gọn vùng Trường Giang, cắt đứt mọi con đường vận chuyển lương thực của triều Thanh và nhanh chóng tiến quân vào Nam Kinh. Khi đó, Thiên vương Hồng Tú Toàn đã nghe theo đề nghị của Ðông vương Dương Tú Thanh định đô ở đây và lấy tên là Thiên Kinh. Triều đình Mãn Thanh điên cuồng quyết tâm dốc toàn bộ quân chủ lực để đánh quân Thái Bình, trong đó có quân tinh nhuệ của Tăng Quốc Phiên, một người dân tộc Hán, cầm đầu. Nhưng cho dù đội quân của Phiên có mạnh đến đâu cũng không thể thắng được đội quân bách chiến bách thắng của Thái Bình Thiên Quốc. Ðiển hình là hai trận đại bại ở Hồ Nam và Cửu Giang khiến cho Tăng Quốc Phiên phải hai lần trầm mình xuống sông tự vẫn.Tuy nhiên, sau chiến tranh, phong trào Thái Bình cũng bị tổn thất nặng nề đến nỗi nội bộ lục đục, chính vì thế đã bị những thế lực đen tối từ nước ngoài lợi dụng… Sau này, tuy có sự phấn đấu gian khổ của Trần Ngọc Thành và Lý Tú Thành – hai vị tướng dũng cảm của Thái Bình Thiên Quốc, nhưng cuối cùng vẫn không chống chọi lại được trước sự tấn công của thù trong giặc ngoài. Tháng 4/1864, Hồng Tú Toàn bị bệnh qua đời. Tháng 6 năm đó, Thái Bình Thiên Quốc tan rã...</em></p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 13, 2000, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Cao Lan Thôn","avatar":""},{"name":"Lưu Bình","avatar":""},{"name":"Trương Trí Trung","avatar":""},{"name":"Vương Thi Khôi","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324534);
