INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-chieu-thang-dung', 'Mùa hè chiều thẳng đứng', 'Mùa hè chiều thẳng đứng', 'https://phimimg.com/upload/vod/20240607-1/efb166047debb7f94c21bdb7baa36614.jpg', 'https://phimimg.com/upload/vod/20240607-1/7d149af86c8d245409075749e61be5c9.jpg', '<p>Mùa hè chiều thẳng đứng kể về câu chuyện gia đình của 3 chị em gái: Sương (Như Quỳnh), Khanh (Lê Khanh) và Liên (Trần Nữ Yên Khê) quanh ngày giỗ mẹ tại Hà Nội.</p>', 'Full', 1, 'single', 'completed', 16, 2000, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Tran Nu Yen Khe","avatar":""},{"name":"Le Khanh","avatar":""},{"name":"Ngo Quang Hai","avatar":""},{"name":"Chu Hung","avatar":""},{"name":"Le Tuan Anh","avatar":""},{"name":"Nhu Quynh","avatar":""},{"name":"Do Thi Hai Yen","avatar":""},{"name":"Doan Viet Ha","avatar":""},{"name":"Le Vu Long","avatar":""},{"name":"Mạnh Cường","avatar":""},{"name":"Anh Tuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324534);
