INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-song-nhuom-mau', 'Dòng Sông Nhuốm Máu', 'The Crimson Rivers', 'https://phimimg.com/upload/vod/20240219-1/f6a296db7e55a01d6069789e21d9cd97.jpg', 'https://phimimg.com/upload/vod/20240219-1/98b6d4f07f01d7ce5a5baafeda7cba57.jpg', '<p>Hai cảnh sát Pháp, một người đang điều tra một vụ giết người ghê rợn tại một trường cao đẳng miền núi xa xôi, người còn lại đang điều tra việc những kẻ đầu trọc mạo phạm ngôi mộ của một cô gái trẻ, được tập hợp lại với nhau nhờ những manh mối từ các vụ án tương ứng của họ. Ngay sau khi họ bắt đầu làm việc cùng nhau, nhiều vụ giết người đã được thực hiện và cặp đôi bắt đầu khám phá ra những bí mật đen tối đằng sau những vụ giết người.</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean Reno","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"Nadia Farès","avatar":""},{"name":"Dominique Sanda","avatar":""},{"name":"Karim Belkhadra","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324534);
