INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-soi', 'Nàng Sói', 'Ginger Snaps', 'https://phimimg.com/upload/vod/20240219-1/18002b6752c8eadcf4ec88bf804dc0e5.jpg', 'https://phimimg.com/upload/vod/20240219-1/47a7c72e3323b281d83a846d42d7f55d.jpg', '<p>Câu chuyện về hai chị em bị ruồng bỏ, Ginger và Brigitte, ở thị trấn ngoại ô Bailey Downs. Vào đêm có kinh đầu tiên của Ginger, cô bị một sinh vật hoang dã tấn công dã man. Vết thương của Ginger lành lại một cách thần kỳ nhưng có điều gì đó không ổn. Bây giờ Brigitte phải cứu em gái và cứu chính mình.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Katharine Isabelle","avatar":""},{"name":"Emily Perkins","avatar":""},{"name":"Kris Lemche","avatar":""},{"name":"Mimi Rogers","avatar":""},{"name":"Jesse Moss","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324534);
