INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('virgin-stripped-bare-by-her-bachelors', 'Virgin Stripped Bare By Her Bachelors', 'Virgin Stripped Bare By Her Bachelors', 'https://phimimg.com/upload/vod/20240227-1/fd1454e17b5f603265bf384644e08f4c.jpg', 'https://phimimg.com/upload/vod/20240227-1/87ecfeeef559c6dade5752513a4b781c.jpg', '<p>Mối quan hệ tràn ngập những cạm bẫy giữa một nhà sản xuất video nữ dễ chịu và chủ sở hữu thư viện khi chúng bị lôi kéo vào trang web tự kéo của họ. Serenade ngọt ngào chua để tán tỉnh hiện đại.</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324534);
