INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghi-luc-song', 'Nghị Lực Sống', 'Erin Brockovich', 'https://phimimg.com/upload/vod/20240207-1/261d7c55444f77baf1c2b4bf61af8ec9.jpg', 'https://phimimg.com/upload/vod/20240207-1/d685d0dbaefd6c380174a9dbf2eb6107.jpg', '<p>Bộ phim dựa trên câu chuyện có thật về Erin Brockovich, bà mẹ đơn thân với ba con, nhưng không tiền, không việc làm. Bằng sự nỗ lực không ngừng, cô trở thành luật sư thực thụ dù trong tay không hề có bằng cấp nào. Cô được biết đến trong vụ kiện với khoản phí khổng lồ, chưa từng có trong lịch sử nước Mỹ. Phim mang về cho Julia Roberts giải Oscar năm 2001 ở hạng mục Nữ diễn viên chính xuất sắc nhất.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julia Roberts","avatar":""},{"name":"Albert Finney","avatar":""},{"name":"Aaron Eckhart","avatar":""},{"name":"Marg Helgenberger","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324534);
