INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-thu-giong-kinh-hoang', 'Buổi Thử Giọng Kinh Hoàng', 'Audition', 'https://phimimg.com/upload/vod/20240205-1/15dde71908f46c79819fc93f8136e1b0.jpg', 'https://phimimg.com/upload/vod/20240205-1/b48c2a226fa976e78b5143f168120ab2.jpg', '<p>7 năm sau cái chết của vợ, Aoyama quyết định dùng một phương pháp bất thường để tìm bạn gái. Ông tổ chức một cuộc thử vai của các nữ diễn viên trẻ và ông bị thu hút bởi cô vũ công ba-lê Yamazaki Asami. Aoyama bắt đầu hẹn hò với Asami mà không biết rằng Asami là một cô gái luôn lẻ loi trong căn phòng tối của mình, ngoại trừ những xác người bị cô cột trong bao bố dưới sàn nhà…</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Ryo Ishibashi","avatar":""},{"name":"Eihi Shiina","avatar":""},{"name":"Tetsu Sawaki","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324534);
