INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-2000', 'Cứu!!!', 'Help!!!', 'null', 'https://phimimg.com/upload/vod/20240123-1/50bd479239f0552564421213928b8048.jpg', '<p>Bộ ba bác sĩ trẻ đầy lý tưởng đảm nhận việc quản lý bệnh viện tham nhũng, kém hiệu quả, quan tâm đến việc tiết kiệm đô la hơn là tính mạng. Các tình tiết phụ dựng lên dưới hình thức một mối tình tay ba, sự cố mất điện và một vụ tai nạn xe hơi lớn.</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ekin Cheng","avatar":""},{"name":"Jordan Chan","avatar":""},{"name":"Cecilia Cheung","avatar":""},{"name":"Raymond Ho-Yin Wong","avatar":""},{"name":"Shiu Hung Hui","avatar":""},{"name":"Suet Lam","avatar":""},{"name":"Bonnie Wong Man-Wai","avatar":""},{"name":"Lin Jiao","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324534);
