INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('how-the-grinch-stole-christmas', 'How The Grinch Stole Christmas', 'How The Grinch Stole Christmas', 'https://phimimg.com/upload/vod/20240121-1/f96d3c18147665c1de1de9bb7428c6aa.jpg', 'https://phimimg.com/upload/vod/20240121-1/d3d62c3225b469f4ab4c4dd2decdbecb.jpg', '<p>Bên trong một bông tuyết tồn tại vùng đất huyền diệu của Whoville, trong đó sống, một loại người Munchkin gần như đột biến, tất cả đều yêu Giáng sinh. Ngay bên ngoài thị trấn yêu quý của họ sống Grinch (Jim Carrey), một sinh vật khó chịu ghét Giáng sinh và có kế hoạch đánh cắp nó từ những người mà anh ta như vậy. Little Cindy Lou WHO (Taylor Momsen) quyết định kết bạn với Grinch.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324534);
