INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-luc-nam-dam', 'Quyền Lực Nắm Đấm', 'Fist Power', 'null', 'https://phimimg.com/upload/vod/20240104-1/ba93d161e4aaaa691525cb81e00a406e.jpg', '<p>Một nhân viên an ninh đại lục phải chạy đua với đồng hồ để lấy con trai của một người đàn ông đang bắt giữ cả một trường học làm con tin.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Triệu Văn Trác","avatar":""},{"name":"Gigi Lai","avatar":""},{"name":"Austin Wai","avatar":""},{"name":"Long Fang","avatar":""},{"name":"Suet Lam","avatar":""},{"name":"Pei-pei Cheng","avatar":""},{"name":"Liu Jia Rong","avatar":""},{"name":"Te-Lo Mai","avatar":""},{"name":"Robert Mak","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324534);
