INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ring-0-birthday', 'Ring 0: Birthday', 'Ring 0: Birthday', 'https://phimimg.com/upload/vod/20240104-1/6a2b9142ce4d3882f71b64d90a8459c9.jpg', 'https://phimimg.com/upload/vod/20240104-1/99669cec193bbc42107baaf64354ccbe.jpg', '<p>Phần tiền truyện cho bộ phim kinh dị Ringu, bộ phim này cung cấp câu chuyện nền tảng về cách Sadako sau đó trở thành tinh thần giết người báo thù. Câu chuyện bắt đầu với cô ấy như một người nhút nhát, có phần bị rút, học sinh đại học, dù sao cũng tham gia vào một câu lạc bộ kịch. Giám đốc nghĩ rằng cô ấy có tài năng, nhưng một số người biểu diễn khác bắt đầu ghen tị với sự chú ý mà anh ấy cho cô ấy. Trong khi đó, một phóng viên điều tra với mẹ tinh thần của Sadako nghĩ rằng có một điều gì đó rất đáng ngờ về người phụ nữ trẻ, và đến trong khuôn viên trường để đối đầu với Sadako giống như một loạt những cái chết kỳ lạ bắt đầu quét qua câu lạc bộ kịch.</p>', 'Full', 1, 'single', 'completed', 12, 2000, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324534);
