INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-quy-phi', 'Dương Quý Phi', 'The Legend Of Lady Yang', 'https://phimimg.com/upload/vod/20240116-1/bdb59c4adf5ed4750d466fd397d93eba.jpg', 'https://phimimg.com/upload/vod/20240116-1/f6b79cc64d4e1050e19b81fad5fa1764.jpg', '<p>Cô gái mồ côi Dương Ngọc Hoàn (do Hướng Hải Lam đóng) được trời phú cho một sắc đẹp mỹ miều, lại có tài cầm kỳ thi họa, nên sớm lọt vào mắt xanh của vua Đường Huyền Tông (do Giang Hoa đóng). Hoàn được phong làm quý phi, nổi tiếng với điệu múa xuất chúng, say đắm lòng người.&nbsp; &nbsp;&nbsp;Huyền Tông rất mực sủng ái Hoàn, không tiếc công sức, của cải để lấy được nụ cười của nàng. Sự chiều chuộng thái quá của Huyền Tông dành cho Ngọc Hoàn khiến hoàng hậu, các phi tần và cả thái hậu đều ghen tị. Nhất là Võ Huệ Phi (do Quách Thiếu Vân đóng).&nbsp;Ngoài mặt, Huệ Phi rất tốt với Ngọc Hoàn. Nhưng bên trong, cô ta dùng mọi thủ đoạn để hãm hại. Không những khiến Hoàn sảy thai, bị đày vào lãnh cung, Huệ Phi còn điều lính truy sát, làm cho Hoàn bị hủy dung nhan. Mai Phi (do Ngô Mỹ Hạnh đóng) cũng ra sức tranh sủng với Hoàn, muốn đuổi Hoàn ra khỏi hoàng cung.Nhưng, sau mọi lần ám hại, Hoàn càng được nhà vua sủng ái. Những đau thương đã trải qua khiến Hoàn dần thay đổi. Cô trở thành người mưu mô, thường xuyên can dự chính sự và sử dụng quyền lực một cách tùy ý, dung túng cho người nhà. Trong đó có Dương Quốc Trung (do Tăng Vĩ Quyền đóng) – anh họ của Ngọc Hoàn. Nhờ Hoàn giúp đỡ, Trung được Huyền Tông trọng dụng, thăng tiến như diều gặp gió. Trong triều đình, ai cũng dè chừng hắn, chỉ có Lâm Phủ (do Quách Phong đóng) ra mặt chống đối. Sự tác oai tác quái của Trung dẫn đến việc tạo phản của An Lộc Sơn (do Nguyễn Triệu Tường đóng), gây bạo loạn, lòng người căm phẫn. Thái hậu tranh thủ cơ hội, buộc Huyền Tông xử tử Ngọc Hoàn. Nếu trái ý, bà sẽ không phát lệnh tiến quân...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 22, 2000, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Giang Hoa","avatar":""},{"name":"Hướng Hải Lam","avatar":""},{"name":"Ngô Mỹ Hạnh","avatar":""},{"name":"Quách Thiếu Vân","avatar":""},{"name":"Tăng Vĩ Quyền","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324534);
