INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-co-la', 'Sô Cô La', 'Chocolat', 'https://phimimg.com/upload/vod/20240108-1/54799d0dccc39e3da2521f36024c72c2.jpg', 'https://phimimg.com/upload/vod/20240108-1/912393a695bbb82b2b93f462d7d279ee.jpg', '<p>Chocolat là một phim lãng mạn về một cô gái với cửa hàng bán sô cô la của mình, đã khuấy động cuộc sống vốn tĩnh lặng tại một thị trấn nhỏ cổ kính. Những người dân ở đây sau khi nếm những loại kẹo kỳ diệu của cô đã rũ bỏ vẻ đạo mạo để sống một cuộc sống mới đầy đam mê. Tuy nhiên, cuộc đời cô chỉ thực sự thay đổi khi một khách lạ bất ngờ xuất hiện.</p>', 'Full', 1, 'single', 'completed', 12, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Juliette Binoche","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Alfred Molina","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324534);
