INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-boi-khong-gian-2000', 'Cao Bồi Không Gian', 'Space Cowboys', 'https://phimimg.com/upload/vod/20231231-1/e11a008d49fab5cc5850d9dd304036cb.jpg', 'https://phimimg.com/upload/vod/20231231-1/8135c4d6a23854ebf13bd911180fa093.jpg', '<p>Một vệ tinh viễn thông được sản xuất từ thập niên 50 của Nga sắp chệch khỏi quỹ đạo. Cơ quan hàng không vũ trụ Mỹ (NASA) yêu cầu được giúp Nga khắc phục sự cố. Họ muốn nhân cơ hội này để tìm hiểu xem bằng cách nào tình báo Nga lấy được hệ thống điều khiển vệ tinh nhân tạo của Mỹ trong những năm 50. Hơn nữa, vệ tinh có thể được trang bị tên lửa hạt nhân. Nếu dự đoán ấy là đúng, nhân loại sẽ đối mặt với thảm họa nếu nó rơi xuống Trái Đất. Nhưng hệ thống điều khiển trên tàu lạc hậu đến nỗi không một ai ở NASA có thể nắm bắt được. Họ mời phi công đã nghỉ hưu kiêm kỹ sư hàng không Frank Corvin (Clint Eastwood) trợ giúp. Khi còn làm việc cho NASA, Frank từng tham gia thiết kế hệ thống điều khiển ấy. Chính ông là trưởng nhóm phi hành gia thực hiện chuyến bay thử nghiệm đầu tiên lên vũ trụ.</p>', 'Full', 1, 'single', 'completed', 18, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clint Eastwood","avatar":""},{"name":"Tommy Lee Jones","avatar":""},{"name":"Donald Sutherland","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324534);
