INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-tim-kiem-ky-uc', 'Hành Trình Tìm Kiếm Ký Ức', 'Memento', 'https://phimimg.com/upload/vod/20240102-1/3f9bb25d4c2d043dc1130ff6adb24b3d.jpg', 'https://phimimg.com/upload/vod/20240102-1/6d2fcff9ad11c56bf3659618ffb81c9a.jpg', '<p>Memento là câu chuyện xoay quanh Leonard Shelby, một người mắc chứng trí nhớ ngắn hạn truy tìm kẻ đã hãm hiếp và giết chết vợ anh. Leonard chỉ có thể nhớ những chuyện xảy ra trước vụ án mạng còn từ sau đó thì anh không thể nhớ điều gì quá 10 phút nên anh luôn phải ghi chép, chụp ảnh và thậm chí xăm mình để ghi nhớ mọi việc. Phim được chia làm 2 mảng truyện đan xen nhau và cứ thế, bức màn bí mật dần dần được hé lộ qua từng thước phim...</p>', 'Full', 1, 'single', 'completed', 21, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Guy Pearce","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"Joe Pantoliano","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324534);
