INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-san-vang', 'Những Kẻ Săn Vàng', 'Three Kings', 'https://phimimg.com/upload/vod/20240128-1/71d1e18ed56686feef8db6bb58a07d15.jpg', 'https://phimimg.com/upload/vod/20240128-1/568352ba818eb10d06c72a258e284810.jpg', '<p>Tại một căn cứ quân sự Mỹ trên sa mạc gần Kuwait, trung sĩ Troy Barlow cùng hai binh nhất bắt được một nhóm binh sĩ Iraq. Khi lục soát những người này, họ tìm thấy một tấm bản đồ trong quần lót một sĩ quan. Linh tính mách bảo cho Troy biết rằng đó có thể là một tấm bản đồ quan trọng. Viên trung sĩ quyết định không báo cáo sự việc cho những chỉ huy cấp cao hơn mà đưa bản đồ cho thượng sĩ Elgin, một người bạn thân của anh. Họ quyết định tự đi tìm hầm ngầm chứa vàng mà chính quyền Iraq lấy được từ Kuwait để mưu lợi riêng. Nhưng rồi họ từ bỏ ý định khi chứng kiến những vụ thảm sát của quân đội Iraq. Đó là thời điểm sau cuộc chiến vùng vịnh Persia và lực lượng Liên quân vừa ký thỏa thuận ngừng bắn với Iraq...</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Mark Wahlberg","avatar":""},{"name":"Ice Cube","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324534);
