INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-hau-fbi', 'Hoa Hậu FBI', 'Miss Congeniality', 'https://phimimg.com/upload/vod/20240102-1/93aeed11f7f42befdc4fb1167ef78bac.jpg', 'https://phimimg.com/upload/vod/20240102-1/b172cffa9ada5a7f7f573575ce99f2eb.jpg', '<p>Một tên giết người hàng loạt đe dọa cuộc thi hoa hậu Mỹ sẽ là mục tiêu sắp tới của hắn. Để ngăn chặn tấn thảm kịch, FBI cài một người đẹp tham dự. Nhưng phiền một nỗi, Gracie lại không thích làm đẹp hay ăn mặc điệu đà, phấn son, váy áo hay giày cao gót không phải là những thứ ưa thích của gracie. Để chuẩn bị cho thí sinh cứng đầu này tham dự cuộc thi sắc đẹp, sếp lớn đành mời chuyên gia Victor về “đào tạo” Gracie. Sau bao ngày cực hình, ngày thi cũng tới, cô nàng vụng về khăn gói lên đường với tư cách đại diện bang New jersey Khi tên khủng bố vô tình bị tóm, vụ việc tưởng chừng như đã xong, nhưng Gracie lại cho rằng vẫn còn điều mờ ám liên quan đến người quản lý hoa hậu cần phải điều tra...</p>', 'Full', 1, 'single', 'completed', 16, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Benjamin Bratt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324534);
