INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-tren-hanh-tinh-la', 'Quái Vật Trên Hành Tinh Lạ', 'Pitch Black', 'https://phimimg.com/upload/vod/20231227-1/96d3f01253d9bc3f303baea6e8e7505d.jpg', 'https://phimimg.com/upload/vod/20231227-1/837da00bd07dd733708a6ef2d58034aa.jpg', '<p>Tên tội phạm Richard nguy hiểm đến nỗi người ta phải đưa hắn tới một nhà tù bên ngoài Trái Đất để giam giữ. Trên đường đi, phi thuyền chở hắn gặp nạn và rơi xuống một hành tinh bỏ hoang ……nhóm sống sót đột ngột mất tích khi richard bị bắt, người ta cho rằng gã đã bắt cóc anh chàng kia. khi xem xét một cái hang, nữ phi công carolyn phát hiện dấu vết của những sinh vật lạ dưới lòng đất …….</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Radha Mitchell","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Vin Diesel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324534);
