INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dap-den-tiep-noi', 'Đáp Đền Tiếp Nối', 'Pay It Forward', 'https://phimimg.com/upload/vod/20231227-1/9a45f6aaa1175dc23b93cdf45b00548f.jpg', 'https://phimimg.com/upload/vod/20231227-1/39ec6c6477ce321977ca86565e8e85aa.jpg', '<p>Giống như một số đứa trẻ khác, Trevor McKinney, 12 tuổi, tin vào bản chất tốt đẹp của con người. Giống như nhiều đứa trẻ khác, anh quyết tâm thay đổi thế giới tốt đẹp hơn. Không giống như hầu hết những đứa trẻ khác, anh ấy đã thành công.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Spacey","avatar":""},{"name":"Helen Hunt","avatar":""},{"name":"Haley Joel Osment","avatar":""},{"name":"Jay Mohr","avatar":""},{"name":"Jim Caviezel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324534);
