INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sung-than-2000', 'Súng Thần', 'Double Tap', 'https://phimimg.com/upload/vod/20231230-1/4ee4cf5261737cc6c712f95584a9f0fd.jpg', 'https://phimimg.com/upload/vod/20231230-1/2039075aa76006f6cf75b6dc9ecb5c01.jpg', '<p>Rich là một người rất đam mê súng, anh quen với Miêu, một nhân viên của tổ trọng án cùng với một số người bạn khác. Trong ngày họ cùng thi bắn súng thì xuất hiện một kẻ đột nhập gây náo loạn, đối diện với hung thủ không thể nào nổ súng được và kẻ ra tay là Rich, lần đầu tiên trong đời anh cầm súng kết liễu một mạng sống. Ba năm sau một vụ án giết người gây sóng gió trong sở cảnh sát, người phụ trách điều tra là Miêu, và oái oăm thay hung thủ bị tình nghi lại là Rich.</p>', 'Full', 1, 'single', 'completed', 11, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Trương Quốc Vinh","avatar":""},{"name":"Phương Lực Thân","avatar":""},{"name":"Ruby Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324534);
