INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('markova-gay-mua-vui', 'Markova: Gay Mua Vui', 'Markova: Comfort Gay', 'https://phimimg.com/upload/vod/20231227-1/18894a5adbe557c6c4b41d62b314c3a5.jpg', 'https://phimimg.com/upload/vod/20231227-1/c043eeba8bdf7149f95fd0fb6125f26d.jpg', '<p>Walterina Markova nhớ lại cuộc sống ở Philippines với tư cách người đồng tính nam tên là Walter Dempster Jr. trong Thế chiến II, cũng là khoảng thời gian khó khăn và đầy trăn trở.</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Dolphy","avatar":""},{"name":"Eric Quizon","avatar":""},{"name":"Jeffrey Quizon","avatar":""},{"name":"Tony Bueno","avatar":""},{"name":"Ricci Chan","avatar":""},{"name":"R.S. Francisco","avatar":""},{"name":"Melvin Lee","avatar":""},{"name":"Loren Legarda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324534);
