INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-bong-phi-thuong', 'Đội Bóng Phi Thường', 'Remember The Titans', 'https://phimimg.com/upload/vod/20231213-1/2cfb5593f59d7412725cf32ff09b39f8.jpg', 'https://phimimg.com/upload/vod/20231213-1/1742251a785ea9dd4e615307cd6fa8e4.jpg', '<p>Sau khi dẫn dắt đội bóng của mình giành được 15 mùa giải vô địch, huấn luyện viên Bill Yoast bị giáng chức và được thay thế bởi Herman Boone – người cứng rắn, cố chấp và khác hẳn với Yoast được yêu mến hết mức có thể. Hai người đàn ông học cách vượt qua sự khác biệt của họ và biến một nhóm thanh niên thù địch thành nhà vô địch.</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Wood Harris","avatar":""},{"name":"Ryan Hurst","avatar":""},{"name":"Donald Faison","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324534);
