INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('digimon-adventure-02-con-bao-digimon-do-bo-digimental-hoang-kim', 'Digimon Adventure 02 - Cơn Bão Digimon Đổ Bộ! Digimental Hoàng Kim!', 'Digimon Adventure 02 - Hurricane Touchdown! The Golden Digimentals', 'https://phimimg.com/upload/vod/20231213-1/21d25d0189d9136245fd480f363d1fa3.jpg', 'https://phimimg.com/upload/vod/20231213-1/958a8a6c727364270b520ae698988dd7.jpg', '<p>Nhiều năm sau khi một cậu bé ở Mỹ mất đi một trong những người bạn Digimon của mình, một Digimon virus độc ác đã bắt cóc thành công Những đứa trẻ được chọn. Những người bạn trẻ cùng với Digimon phải chạy đua với thời gian để khám phá ra nguồn gốc của mối đe dọa mới này.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2000, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324534);
