INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boc-lua', 'Bốc Lửa', 'Bring It On', 'https://phimimg.com/upload/vod/20231213-1/99f6b01faefbd554b6c073aee6f0fefa.jpg', 'https://phimimg.com/upload/vod/20231213-1/8cca805405d33d7d54b14f7d8f542649.jpg', '<p>Torrance Shipman là một điển hình học sinh trung học Mỹ. Từ khi trở thành đội trưởng đội cổ vũ dày thành tích của trường San Diego Toros, cô như bay lên mây! Cô quyết định không có gì quan trọng bằng hoạt động của đội, kể cả bài tập ở trường. Cô năn nỉ bố mẹ và cả bạn trai làm đủ mọi cách để đội cổ vũ của cô có thể thắng giải vô địch quốc gia lần thứ 6 liên tiếp. Nhưng đội của Toro đã vấp phải một đối thủ đáng gờm Clovers, đội cổ vũ hip hop đến từ Los Angeles. Khi Torrance học được chuyện những anh chị đi trước cô đã chiến thắng bằng cách học hỏi những động tác của các đội khác, cô nhận ra rằng Clovers và đội trưởng Isis của họ mong sẽ có kết quả công bằng hơn. Và đội của Toro đang gặp nguy hiểm! Chỉ còn vài tuần nữa là vòng chung kết bắt đầu. Sự căng thẳng đang tăng cao tột độ...</p>', 'Full', 1, 'single', 'completed', 21, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kirsten Dunst","avatar":""},{"name":"Eliza Dushku","avatar":""},{"name":"Jesse Bradford","avatar":""}]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '[]', 1784690324534);
