INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-bai-lat-ngua', 'Ván Bài Lật Ngửa', 'Reindeer Games', 'https://phimimg.com/upload/vod/20231212-1/3a1b802cabb6202b73be426279e12bb4.jpg', 'https://phimimg.com/upload/vod/20231212-1/52feb25084a888f414cfc3d3700a418b.jpg', '<p>Sau khi giả danh bạn cùng phòng đã chết để được ở bên bạn gái, một cựu tội phạm nhận ra mình là kẻ bất đắc dĩ tham gia vào một vụ cướp sòng bạc.</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Gary Sinise","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Dennis Farina","avatar":""},{"name":"Donal Logue","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324534);
