INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-re-trinh-lang', 'Chú Rể Trình Làng', 'Meet The Parents', 'https://phimimg.com/upload/vod/20231211-1/db51601544bc3d0974db6b84d8b13f1c.jpg', 'https://phimimg.com/upload/vod/20231211-1/63181a0aa2de9fd2529e5b4e03fe23a0.jpg', '<p>Một y tá nam Do Thái có kế hoạch yêu cầu bạn gái sống của mình kết hôn với anh ta. Tuy nhiên, anh ta biết rằng người cha nghiêm khắc của cô mong muốn được yêu cầu bàn tay của con gái mình trước khi cô có thể chấp nhận. Do đó, bắt đầu chuyến thăm từ địa ngục khi hai du lịch gặp gỡ mẹ và cha, người hóa ra là cựu CIA với một máy dò nói dối trong tầng hầm. Thật trùng hợp, một chị cũng đã tuyên bố đám cưới của mình cho một bác sĩ trẻ. Tất nhiên tất cả mọi thứ có thể sai, không, bao gồm cả sự biến mất của con mèo Himalaya yêu dấu của cha, Jinxie</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324534);
