INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cuop-hoan-hao', 'Vụ Cướp Hoàn Hảo', 'Gen-Y Cops', 'https://phimimg.com/upload/vod/20240102-1/4200192d145c8a04ae9772c62ef7763f.jpg', 'https://phimimg.com/upload/vod/20240102-1/e7299fbdda827d716f9c35291fc32259.jpg', '<p>RX-1 là robot do kĩ sư Kurt phát minh ra, tuy nhiên nó lại bị chính phủ Mỹ tước quyền sở hữu vì quá nguy hiểm. Nổi giận, Kurt âm mưu đánh cướp lại RX-1 để bán cho 1 tay tài phiệt khủng bố khét tiếng.</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Phùng Đức Luân","avatar":""},{"name":"Maggie Q","avatar":""},{"name":"Trần Quán Hy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324534);
