INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-trong-danh-du', 'Người Trọng Danh Dự', 'Men Of Honor', 'https://phimimg.com/upload/vod/20231211-1/0619de964275af3c6dec47ed6829e96a.jpg', 'https://phimimg.com/upload/vod/20231211-1/e282617bcbad92ac2d1d6839b6fad72d.jpg', '<p>Chống lại những khó khăn ghê gớm -- và một huấn luyện viên lặn kiểu cũ chán nản với các chính sách mới, ít mang tính định kiến hơn của Hải quân Hoa Kỳ -- Carl Brashear đặt mục tiêu trở thành thợ lặn bậc thầy người Mỹ gốc Phi đầu tiên của Hải quân trong câu chuyện có thật đầy phấn khởi này. Mối quan hệ của họ bắt đầu rạn nứt, nhưng số phận cuối cùng đã âm mưu đưa những người đàn ông lại với nhau trong một môi trường tôn trọng lẫn nhau, chiến thắng và danh dự.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Aunjanue Ellis","avatar":""},{"name":"Hal Holbrook","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324534);
