INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-duoi-nam-mo', 'Bí Mật Dưới Nấm Mồ', 'The Cell', 'https://phimimg.com/upload/vod/20231210-1/413ba7ee7e2c5b66445416b558f0bf6d.jpg', 'https://phimimg.com/upload/vod/20231210-1/4ca87bba2265278f18732c5533fb78b8.jpg', '<p>Với những nghiên cứu của mình trong việc trấn áp tội phạm, FBI đã tạo ra một cổ máy khiến con người có thể chìm trong một thế giới ảo với những sức mạnh siêu nhiên....Catharine Deane là một chuyên gia khoa học về chế tạo những công cụ cho FBI, chính vì đó những tên tội phạm đã bắt cóc gia đình nhằm uy hiếp trong vòng 48 tiếng phải giao cho chúng tất cả công nghệ mới này để giúp cho những tên tội phạm này thống trị và trả thù lại FBI.</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lopez","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Catherine Sutherland","avatar":""},{"name":"James Gammon","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324534);
