INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-truong-hai-mat', 'Ngôi Trường Hai Mặt', 'Persona', 'https://phimimg.com/upload/vod/20231227-1/398cf194c2cae057b9d9191a97c2b455.jpg', 'https://phimimg.com/upload/vod/20231227-1/61e1f423a829515d5c56923e48745518.jpg', '<p>Học sinh cấp ba bị bắt nạt Danda bắt đầu đeo một chiếc mặt nạ sứ và tạo trào lưu. Song cô nàng Yuki sớm phát hiện những chiếc mặt nạ có liên quan đến nhiều vụ giết người.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Fujiwara Tatsuya","avatar":""},{"name":"Kurosu Maya","avatar":""},{"name":"Chiaki Kuriyama","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324534);
