INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-tuyet-mat-phan-8', 'Hồ Sơ Tuyệt Mật (Phần 8)', 'The X-Files (Season 8)', 'https://phimimg.com/upload/vod/20231207-1/d1d70f8a98b075b2fe906dfd857da4b0.jpg', 'https://phimimg.com/upload/vod/20231207-1/a059d8ac53d18aef12c1821592212799.jpg', '<p>Sau khi Mulder mất tích, Scully quay trở lại trụ sở FBI để tìm Đặc vụ John Doggett đang tiến hành một cuộc truy lùng đối tác của FBI. Biết rằng kiểu tìm kiếm đó sẽ vô ích, Scully và Skinner tìm đến Lone Gunmen với hy vọng khám phá thông tin về hoạt động bổ sung của UFO vào khoảng thời gian Mulder mất tích. Mặc dù những thông tin như vậy dẫn họ đến với Gibson Praise, nhưng người đàn ông đi cùng Gibson, một người đàn ông có vẻ là Mulder, thực chất là một thợ săn tiền thưởng người ngoài hành tinh. Cuối cùng nhận ra rằng Mulder sẽ không được tìm thấy dễ dàng như vậy, Đặc vụ Doggett chính thức được giao cho X-Files. Bây giờ, sau tất cả những gì cô ấy đã trải qua với Mulder, chính Scully mới là “người tin tưởng” và là người phải tìm cách làm việc với “kẻ hoài nghi,” John Doggett.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 16, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Duchovny","avatar":""},{"name":"Gillian Anderson","avatar":""},{"name":"Mitch Pileggi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324534);
