INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-chien-tranh', 'Luật Chiến Tranh', 'Rules Of Engagement', 'https://phimimg.com/upload/vod/20231209-1/cb9f509dec795a8ad91b8fa8def2288b.jpg', 'https://phimimg.com/upload/vod/20231209-1/7f11d906a05983b371599cb381751d69.jpg', '<p>Tòa Đại sứ Mỹ ở Yemen bị dân chúng biểu tình tấn công và đã xảy ra đọ súng giữa quân nổi loạn và binh sĩ Mỹ. Trung tá Terry được lệnh dẫn 1 toán thủy quân lục chiến đến giải vây và di tản nhân viên ra khỏi nơi nguy hiểm. Nhưng kế hoạch không như mong muốn mặc dù tính mạng gia đình ngài Đại sứ và quốc kỳ Mỹ đã an toàn. Ông phải ra lệnh bắn vào những người biểu tình. Cuối cùng là 83 người chết và hơn 100 người bị thương và họ không có vũ khí trong tay. Một cuộc điều tra và Childers được đưa ra tòa án binh. Nhưng sự thật này ra sao ? Phải chăng Childers sai hay là có nguyên nhân nào khác khi mà 1 vị sĩ quan cấp cao của thuỷ quân lục chiến lại phá vỡ luật giao chiến?</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tommy Lee Jones","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Guy Pearce","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324534);
