INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tien-ca-2-tro-ve-bien-ca', 'Nàng Tiên Cá 2: Trở Về Biển Cả', 'The Little Mermaid 2: Return To The Sea', 'https://phimimg.com/upload/vod/20231208-1/33770c83d690c1cc06b213d252771e07.jpg', 'https://phimimg.com/upload/vod/20231208-1/a34c20069573141d5836615672cdffe5.jpg', '<p>Hôm nay là ngày vui trọng đại của cả hai thế giới: mặt đất và biển khơi. Vì họ sẽ ăn mừng sự ra đời của một bé gái , con gái của chàng hoàng tử Iris &amp; nàng tiên cá Ariel - Melody.Vua thuỷ tề Triton cũng đến dự và ông có một món quà dành cho cháu,đó là chiếc dây chuyền có khắc tên Melody trên mặt. Khi mở ra nó sẽ hiện ra hình ảnh lâu đài của Triton và những nàng tiên cá đang bơi lội. Như vậy Melody sẽ có thể nhớ ra mình là ai.Bữa tiệc đang rất vui vẻ thì Morgana xuất hiện. Mụ ta lấy chiếc đuôi bạch tuộc của mình quắp chặt bé Melody lại, đòi vua Triton hãy giao vương quốc của mình cho Morgana không Melody sẽ ra đi mãi mãi. Được cha là hoàng tử Eric cứu giúp, Melody đã được cứu nhưng mụ phù thủy độc ác kia đã biến mất và nói ...</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jodi Benson","avatar":""},{"name":"Samuel E. Wright","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Pat Carroll","avatar":""},{"name":"Buddy Hackett","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324534);
