INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-an-voi-em', 'Ái Ân Với Em', 'Baise-moi', 'https://phimimg.com/upload/vod/20231204-1/50b7cfd8ec2294d500b64e868954c369.jpg', 'https://phimimg.com/upload/vod/20231204-1/7c75ebc396a91cf010b9b821c7906a9c.jpg', '<p>Manu đã sống một cuộc sống khó khăn. Bị lạm dụng và cưỡng hiếp dã man, cô lên đường tìm chính mình chỉ để gặp Nadine, một cô gái điếm đã gặp phải quá nhiều bất công trên thế giới. Tức giận với thế giới, họ dấn thân vào một chuyến đi trên con đường ngoằn ngoèo, đầy giận dữ. Họ chọn quan hệ tình dục khi họ muốn và giết người khi họ cần. Để lại dấu vết của những trò nghịch ngợm và xác chết sau khi chúng thức dậy. Tạo ra một cuộc tấn công chớp nhoáng trên phương tiện truyền thông và săn lùng, chẳng mấy chốc mọi người sẽ ra tay để bắt những kẻ chạy trốn trẻ tuổi.</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Karen Lancaume","avatar":""},{"name":"Raffaëla Anderson","avatar":""},{"name":"Ouassini Embarek","avatar":""},{"name":"Adama Niane","avatar":""},{"name":"Marc Barrow","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324534);
