INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nghi', 'Tình Nghi', 'Under Suspicion', 'https://phimimg.com/upload/vod/20231201-1/a35c7f80194111397af3edb2b2938d22.jpg', 'https://phimimg.com/upload/vod/20231201-1/33fe23f539bce9ae1dc591f0b342cd5a.jpg', '<p>Một luật sư được yêu cầu đến đồn cảnh sát để làm sáng tỏ một số điểm lỏng lẻo trong báo cáo của nhân chứng về một vụ giết người dã man. &quot;Việc này sẽ chỉ mất mười phút&quot;, họ nói, nhưng hóa ra mọi việc lại trở nên lỏng lẻo, và mười phút anh ấy rời khỏi bài phát biểu của mình ngày càng dài hơn.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gene Hackman","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Thomas Jane","avatar":""},{"name":"Monica Bellucci","avatar":""},{"name":"Nydia Caro","avatar":""},{"name":"Miguel Ángel Suárez","avatar":""},{"name":"Pablo Cunqueiro","avatar":""},{"name":"Isabel Algaze","avatar":""},{"name":"Jacqueline Duprey","avatar":""},{"name":"Luis Caballero","avatar":""},{"name":"Patricia Beato","avatar":""},{"name":"Sahyly Yamile","avatar":""},{"name":"Hector Travieso","avatar":""},{"name":"Marisol Calero","avatar":""},{"name":"Vanessa Shenk","avatar":""},{"name":"Eliezer Ortiz","avatar":""},{"name":"R","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324534);
