INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-dinh-ma-ca-rong', 'Đóng Đinh Ma Cà Rồng', 'Dracula 2000', 'https://phimimg.com/upload/vod/20231201-1/cafb16de659165d97c18690fbb2bed66.jpg', 'https://phimimg.com/upload/vod/20231201-1/f230aacb8f36535e4540ee70ecead1b1.jpg', '<p>Abraham Van Helsing, người có mối quan hệ với Bá tước Dracula trong quá khứ, hành nghề buôn bán đồ cổ người Anh. Simon là một thợ săn ma cà rồng đang được đào tạo dưới sự học việc của anh ấy.</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gerard Butler","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Jonny Lee Miller","avatar":""},{"name":"Justine Waddell","avatar":""},{"name":"Vitamin C","avatar":""},{"name":"Jennifer Esposito","avatar":""},{"name":"Omar Epps","avatar":""},{"name":"Sean Patrick Thomas","avatar":""},{"name":"Danny Masterson","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Tig Fong","avatar":""},{"name":"Tony Munch","avatar":""},{"name":"Jeri Ryan","avatar":""},{"name":"Shane West","avatar":""},{"name":"Nathan Fillion","avatar":""},{"name":"Tom Kane","avatar":""},{"name":"Jonathan Whittaker","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324534);
