INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-nhat', 'Nhất Nhất', 'Yi Yi', 'https://phimimg.com/upload/vod/20231201-1/b7a5413fe1b57abd1b843e1022444ac1.jpg', 'https://phimimg.com/upload/vod/20231201-1/2cef2564be6724658316946c5e3db98d.jpg', '<p>Bộ phim xoay quanh một gia đình bình thường ở Đài Loan với ba nhân vật chính: người cha NJ, cậu bé Yang Yang và cô bé Ting Ting, con của NJ. Trải dài 3 tiếng đồng hồ, Yi yi mở đầu bằng một đám cưới, kết thúc bằng một lễ tang và chứa đựng rất nhiều chi tiết của cuộc sống thường ngày của con người. NJ đang gặp vấn đề không vừa lòng trong công việc, cậu con trai Yang Yang hay quậy ở trường, còn cô bé Ting Ting đang phải đối mặt với chuyện tình cảm tuổi mới lớn khi rơi vào một mối tình tay ba với bạn trai của bạn thân và bạn thân của cô. Cả ba người cố gắng giải quyết những vấn đề của bản thân, cùng lúc đó lại phải lo cho bà ngoại đang trong cơn hôn mê, trong sự vắng mặt của người mẹ do vấn đề sức khỏe tuổi trung ...</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Wu Nien-Jen","avatar":""},{"name":"Kelly Lee","avatar":""},{"name":"Jonathan Chang","avatar":""},{"name":"Issey Ogata","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Hsi-Sheng Chen","avatar":""},{"name":"Su-Yun Ko","avatar":""},{"name":"Tao Chuang Cheng","avatar":""},{"name":"Shu-shen Hsiao","avatar":""},{"name":"Adriene Lin","avatar":""},{"name":"Pang Chang Yu","avatar":""},{"name":"Ru-Yun Tang","avatar":""},{"name":"Shu-Yuan Hsu","avatar":""},{"name":"Hsin-Yi Tseng","avatar":""},{"name":"Yung-Feng Lee","avatar":""},{"name":"Shi-hui Chin","avatar":""},{"name":"Wu Jie","avatar":""},{"name":"Kuo-Chih Shu","avatar":""},{"name":"Leon Dai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324534);
