INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-thien-than-cua-charlie-2000', 'Những Thiên Thần Của Charlie', 'Charlie''s Angels', 'https://phimimg.com/upload/vod/20231130-1/f67453b8bca16c543187ed2224c49f67.jpg', 'https://phimimg.com/upload/vod/20231130-1/556b426a46056b8e3040c4926f2c87dd.jpg', '<p>Bộ phim truyền hình Charlie&quot;s Angels đã gây nên làn sóng mạnh mẽ và những năm của thập niên 70 nay được xào nấu lại với 3 cô gái tuyệt vời của Hollywood: Cameron Diaz, Drew Barrymore và Lucy Liu. Cốt truyện vẫn xoay quanh những phi vụ khám phá những bí mật của một trong số nmhững vụ án của ngài thám tử Charlie mà đội ngũ chính là 3 cô thiên thần xinh đẹp của ông.</p>', 'Full', 1, 'single', 'completed', 12, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cameron Diaz","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Tim Curry","avatar":""},{"name":"Kelly Lynch","avatar":""},{"name":"Crispin Glover","avatar":""},{"name":"John Forsythe","avatar":""},{"name":"Matt LeBlanc","avatar":""},{"name":"LL Cool J","avatar":""},{"name":"Tom Green","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Sean Whalen","avatar":""},{"name":"Alex Trebek","avatar":""},{"name":"Raliegh Wilson","avatar":""},{"name":"Mark Ryan","avatar":""},{"name":"Bobby Ore","avatar":""},{"name":"Guy Oseary","avatar":""},{"name":"Joe Duer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm