INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('roi-quan-ngu', 'Rời Quân Ngũ', 'Tigerland', 'https://phimimg.com/upload/vod/20231130-1/16d5da03721f047b64de5b841e63b512.jpg', 'https://phimimg.com/upload/vod/20231130-1/4e7e7075d08cb372d9c08078faab058e.jpg', '<p>Một nhóm tân binh trải qua khóa Huấn luyện Bộ binh Nâng cao tại Fort Polk, Tigerland khét tiếng của Louisiana, điểm dừng chân cuối cùng trước Việt Nam của hàng chục nghìn thanh niên vào năm 1971.</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Matthew Davis","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Tom Guiry","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"James MacDonald","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Neil Brown Jr.","avatar":""},{"name":"Matt Gerald","avatar":""},{"name":"Russell Richardson","avatar":""},{"name":"Nick Searcy","avatar":""},{"name":"Afemo Omilami","avatar":""},{"name":"Keith Ewell","avatar":""},{"name":"Stephen Fulton","avatar":""},{"name":"Tyler Cravens","avatar":""},{"name":"Michael Edm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324534);
