INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-khong-chan-dung', 'Người Tình Không Chân Dung', 'Il Mare', 'https://phimimg.com/upload/vod/20231129-1/c103e636a06ca7ea68ba2bfc2f76f95e.jpg', 'https://phimimg.com/upload/vod/20231129-1/cc6ef9ae77bfe10fabd3a871b21a251d.jpg', '<p>Vào năm 1999, một phụ nữ trẻ rời ngôi nhà cổ kính bên bờ biển của mình và trở về thành phố, để lại trong hộp thư một tấm thiệp cho người chủ tiếp theo, kèm theo hướng dẫn chuyển tiếp bất kỳ thư nào của cô ấy đến địa chỉ mới. Vào năm 1997, một kiến trúc sư trẻ mệt mỏi chuyển đến sống tại ngôi nhà đó và tìm thấy lá thư. Câu trả lời của anh, được anh nhét vào hộp thư, tìm đến cô, bắt đầu một câu chuyện tình yêu song song cách nhau hai năm.</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Jun Ji-hyun","avatar":""},{"name":"Lee Jung-jae","avatar":""},{"name":"Kim Mu-saeng","avatar":""},{"name":"Cho Seung-yeon","avatar":""},{"name":"Min Yun-jae","avatar":""},{"name":"Choe Yun-yeong","avatar":""},{"name":"Hong So-yeong","avatar":""},{"name":"Nam Jeong-hee","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324534);
