INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-gia-phai-tra', 'Cái Giá Phải Trả', 'The Way of the Gun', 'https://phimimg.com/upload/vod/20231129-1/d0ea8c2b48691ce020f3df86dde1ebc6.jpg', 'https://phimimg.com/upload/vod/20231129-1/0d5dced6803fd86aad989de962439738.jpg', '<p>Không nghề nghiệp ổn định nhưng lại muốn giàu nhanh, hai thanh niên tìm cách tống tiền một triệu phú. Quyết định ấy dẫn tới một kết cục bi thảm, bởi kẻ bị tống tiền có mối liên hệ mật thiết với thế giới mafia...</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Phillippe","avatar":""},{"name":"Benicio del Toro","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"James Caan","avatar":""},{"name":"Taye Diggs","avatar":""},{"name":"Nicky Katt","avatar":""},{"name":"Geoffrey Lewis","avatar":""},{"name":"Sarah Silverman","avatar":""},{"name":"Dylan Kussman","avatar":""},{"name":"Scott Wilson","avatar":""},{"name":"Kristin Lehman","avatar":""},{"name":"Henry Griffin","avatar":""},{"name":"Armando Guerrero","avatar":""},{"name":"Andres Orozco","avatar":""},{"name":"Irene Santiago","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324534);
