INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-mang-ten-duc-vong-2000', 'Chuyến Tàu Mang Tên Dục Vọng', 'Desirous Express', 'https://phimimg.com/upload/vod/20231006-1/a00912ac6d801d7d73f48fe59c339ec3.jpg', 'https://phimimg.com/upload/vod/20231006-1/0e5591c871ab73548da0f4b13346b0e7.jpg', '<p>Yin là một người phụ nữ cô đơn có chồng là Keung coi cô như là nô 
lệ tình dục của hắn; Cô muốn giết anh nhưng không có can đảm. Anh ta 
thường đi du lịch đến Thâm Quyến để chơi gái, và từng hãm hiếp bạn cô là
 Hong. Chồng của Hong, Long đã ném cô ấy ra khỏi căn hộ của họ. Một đêm 
sau khi hát karaoke, Long và Yin bắt đầu một cuộc làm tình. Long quyết 
định giết Keung. Hong và Yin chia sẻ quá khứ bi thảm của họ với Yin, thú
 nhận về mối quan hệ của cô với Long. Sau đó, Long xuất hiện tại căn hộ 
của Keung, đã lên ý định một âm mưu giết Yin ...</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Emily Kwan Bo-Wai","avatar":""},{"name":"Sherming Yiu","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""},{"name":"Joe Ma","avatar":""},{"name":"Teresa Ha Ping","avatar":""},{"name":"Hui Siu-Hung","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324534);
