INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-phau', 'Giải Phẫu', 'Anatomy', 'null', 'https://phimimg.com/upload/vod/20231208-1/8e250be982b6bdbb0688067bcf2654c1.jpg', '<p>Một sinh viên y khoa trẻ tuổi khám phá ra một hội kín kinh hoàng gồm các bác sĩ phẫu thuật sẽ làm bất cứ điều gì để có được những mẫu vật thú vị.</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Franka Potente","avatar":""},{"name":"Benno Fürmann","avatar":""},{"name":"Anna Loos","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324534);
