INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kong-woo-giu-gap', 'Kong Woo Giu Gap', 'Kong Woo Giu Gap', 'https://phimimg.com/upload/vod/20231129-1/069cc72332bcea79ab4eefb86d1e9d4a.jpg', 'https://phimimg.com/upload/vod/20231129-1/73f5a07e7ed18efe0657129eca2a1f4f.jpg', '<p>Ren Yinjiu, một tay xã hội đen đã hành động quá mức và vô lương tâm trên thế giới trong hai mươi năm, đã gây ra vô số kẻ thù. Một trong những đặc vụ ngầm của anh ta trong cảnh sát, Ye Weixin, biết được trong cuộc điều tra rằng ai đó sẽ giết Ren Yinjiu. Khi Ye Weixin nói với Ren Yinjiu điều đó, Ren Yinjiu lắc đầu và vẫy tay, cho rằng đó chỉ là một trò đùa nhàm chán. Khi anh ta đang cắt tóc, một viên đạn bắn ra từ một nơi tối tăm và làm cháy mái tóc của anh ta. Vào thời điểm đó, Ren Yinjiu cuối cùng cũng tin rằng ai đó thực sự muốn lấy mạng mình và anh ấy đã triệu tập một cuộc họp ngay lập tức. Sau khi Ye Weixin tiếp quản cuộc điều tra, anh ấy nhắc Ren Yinjiu lên danh sách những kẻ tình nghi theo câu nói nổi tiếng của Gu Long, &quot;Kẻ thù lớn nhất luôn là bạn ở bên cạnh bạn&quot;. Kết quả là, người đầu tiên xuất hiện trong tâm trí Ren Yinjiu là vợ anh, Su Hua.</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Sandra Ng Kwan-Yue","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Carl Ng","avatar":""},{"name":"Eason Chan","avatar":""},{"name":"Samuel Pang","avatar":""},{"name":"Jo Kuk Cho-Lam","avatar":""},{"name":"Lee San-San","avatar":""},{"name":"Chan Fai-hung","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Lee Siu-Kei","avatar":""},{"name":"Carl Ng","avatar":""},{"name":"Alex Lam Chi-Sin","avatar":""},{"name":"Ann Hui","avatar":""},{"name":"Roy Cheung","avatar":""},{"name":"Hugo Ng","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Chapman To","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Li","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324534);
