INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-chien-tren-dinh-tu-cam-thanh', 'Quyết Chiến Trên Đỉnh Tử Cấm Thành', 'The Duel', 'https://phimimg.com/upload/vod/20231124-1/6bcea88546757c684d6781572d6f0e71.jpg', 'https://phimimg.com/upload/vod/20231124-1/1f344d114737c00b6dcb74f65b7ee4a4.jpg', '<p>Sau khi biết được chuyện 20 năm về trước bị gian thần trong triều hãm hại đưa vị Hoàng đế hiện tại lên làm vua, Cô Thành bất mãn, thực hiện kế hoạch của mình bằng cách thách đấu một trận với Thuý Tuyết tại chính Tử Cấm thành trong ngày tết nguyên đán.</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Nick Cheung","avatar":""},{"name":"Zhao Wei","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Ekin Cheng Yee-Kin","avatar":""},{"name":"Kristy Yang","avatar":""},{"name":"Tien Hsin","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Geng Le","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""},{"name":"Frankie Ng Chi-Hung","avatar":""},{"name":"David Lee Wai-Sheung","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Jerry Lamb Hiu-Fung","avatar":""},{"name":"Ronald Wong Ban","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324535);
