INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tinh-mua-he', 'Mối Tình Mùa Hè', 'Summer Holiday', 'https://phimimg.com/upload/vod/20231124-1/b1cb970de39669a7bdd43c8954ed4455.jpg', 'https://phimimg.com/upload/vod/20231124-1/f9366ddf43b1469ea7deb9569e7edd49.jpg', '<p>Summer Holiday là về một cô gái HongKong (Sammi Cheng) bị mất công việc văn phòng của mình và thấy rằng bạn trai của cô đã lừa dối cô, và đi đến một hòn đảo ở Malaysia để bán một nửa của mình một bãi biển cô em họ đưa cho cô. Chỉ sau đó cô ấy biết rằng cô em họ đã bán một nửa khác để người bạn thân nhất của mình (Richie Ren) để trả nợ. Trong nhiệm vụ của mình để thuyết phục anh ta để bán, họ bắt đầu rơi vào tình yêu trên một kỳ nghỉ hè tại thiên đường.</p>', 'Full', 1, 'single', 'completed', 12, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Richie Jen","avatar":""},{"name":"Sammi Cheng","avatar":""},{"name":"Ah Niu","avatar":""},{"name":"Michael Wong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324535);
