INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-linh-hon-cua-quy', 'Bảy Linh Hồn Của Quỷ', 'Bedazzled', 'https://phimimg.com/upload/vod/20231116-1/d2adcae52f6f604efca5bad1542c7b9e.jpg', 'https://phimimg.com/upload/vod/20231116-1/af887dd867049f62c66a511c21f99251.jpg', '<p>Bảy Linh Hồn Của Quỷ - Bedazzled xoay quanh thỏa ước của Elliot Richards và cô nàng quỷ dữ xinh đẹp. Linh hồn là thứ quý giá nhất của mỗi con người, nó lại là thứ không thấy và không \</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Brendan Fraser","avatar":""},{"name":"Elizabeth Hurley","avatar":""},{"name":"Frances O''Connor","avatar":""},{"name":"Miriam Shor","avatar":""},{"name":"Orlando Jones","avatar":""},{"name":"Paul Adelstein","avatar":""},{"name":"Toby Huss","avatar":""},{"name":"Gabriel Casseus","avatar":""},{"name":"Brian Doyle-Murray","avatar":""},{"name":"Jeff Doucette","avatar":""},{"name":"Aaron Lustig","avatar":""},{"name":"Rudolf Martin","avatar":""},{"name":"Julian Firth","avatar":""},{"name":"Iain Rogerson","avatar":""},{"name":"Bridget Hodson","avatar":""},{"name":"Roger Hammond","avatar":""},{"name":"Wi","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
