INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-cha-tuyet-voi', 'Người Cha Tuyệt Vời', 'The Family Man', 'https://phimimg.com/upload/vod/20231117-1/ec92c4871e2326aa8dfdb16dcba37736.jpg', 'https://phimimg.com/upload/vod/20231117-1/385d054d8e554a6ce24a7960529414fb.jpg', '<p>Một buổi sáng Ngày Giáng Sinh, Jack Campell, một thương gia độc thân giàu có ở phố Wall thấy mình thức dậy trong một căn nhà ngoại ô bên cạnh Kate, người bạn gái anh đã từ bỏ 13 năm trước. Cuộc sống như đảo lộn trước mặt Jack. Bỗng chốc anh mất công ty mà anh từng làm chủ tịch cùng với căn hộ sang trọng và chiếc xe Ferrairi đắt tiền. Thay vào đó là một người vợ, cùng với hai đứa con và một chiếc xe minivan tầm thường...</p>', 'Full', 1, 'single', 'completed', 16, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Téa Leoni","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Jeremy Piven","avatar":""},{"name":"Saul Rubinek","avatar":""},{"name":"Josef Sommer","avatar":""},{"name":"Makenzie Vega","avatar":""},{"name":"Jake Milkovich","avatar":""},{"name":"Ryan Milkovich","avatar":""},{"name":"Lisa Thornhill","avatar":""},{"name":"Harve Presnell","avatar":""},{"name":"Mary Beth Hurt","avatar":""},{"name":"Amber Valletta","avatar":""},{"name":"Francine York","avatar":""},{"name":"Ruth Williamson","avatar":""},{"name":"John F. O''Donohue","avatar":""},{"name":"Daniel W","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324535);
