INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-mat-trong-60-giay', 'Biến Mất Trong 60 Giây', 'Gone in Sixty Seconds', 'https://phimimg.com/upload/vod/20231113-1/ab83bf993470601b3f8ff6fd9efacfcd.jpg', 'https://phimimg.com/upload/vod/20231113-1/4cc17a848f5bab38ba8d53988ddcf001.jpg', '<p>Phim kể về một tay trộm xe nổi tiếng ở Los Angeles đã &quot;gác kiếm&quot; bị buộc phải &quot;tái xuất giang hồ&quot; để thực hiện một phi vụ có một không hai trong lịch sử trộm xe vì &quot;bắt buộc&quot;. Em trai cậu ta vì muốn xưng danh thiên hạ nên đã bắt chước anh của mình nhưng... sự việc bất thành và bị xã hội đen LA bắt cóc. Giờ đây, anh phải cứu em mình thoát khỏi cái chết...</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Delroy Lindo","avatar":""},{"name":"Timothy Olyphant","avatar":""},{"name":"Chi McBride","avatar":""},{"name":"Christopher Eccleston","avatar":""},{"name":"Will Patton","avatar":""},{"name":"William Lee Scott","avatar":""},{"name":"Scott Caan","avatar":""},{"name":"James Duval","avatar":""},{"name":"T.J. Cross","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Frances Fisher","avatar":""},{"name":"Grace Zabriskie","avatar":""},{"name":"Michael O","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324535);
