INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-doanh-gia', 'Đại Doanh Gia', 'Winner Takes All', 'null', 'https://phimimg.com/upload/vod/20231125-1/ac8a9dc3ef8c50ddc13a496756be692d.jpg', '<p>Ferrari (Tạ Đình Phong), là một kẻ lừa đảo trẻ tuổi. Anh ta đã lừa đảo mọi người vì tiền trong nhiều tình huống. Một ngày nọ, một cảnh sát có biệt danh ‘Ngốc’ (Karl Maka) sắp bắt được anh ta đang lừa đảo. Anh ta thỏa thuận với Ferrari để giúp anh ta bắt được Master Swindler Wong (Sam Hui), kẻ lừa đảo khét tiếng nhất thế giới, người đang viết cuốn tự truyện về những cách lừa đảo của anh ta. Ferrari tình cờ gặp Bastardly Sze (Alec Su), người đang rình rập một phụ nữ giàu có và chụp ảnh cô ấy.</p>', 'Full', 1, 'single', 'completed', 12, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sam Hui Koon-Kit","avatar":""},{"name":"Ricky Hui","avatar":""},{"name":"Karl Maka","avatar":""},{"name":"Nicholas Tse","avatar":""},{"name":"Annie Wu","avatar":""},{"name":"Ruby Lin","avatar":""},{"name":"Alec Su","avatar":""},{"name":"Raymond Wong","avatar":""},{"name":"Joey Yung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324535);
