INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-ma-ca-rong-khat-mau', 'Thợ Săn Ma Cà Rồng: Khát Máu', 'Vampire Hunter D: Bloodlust', 'https://phimimg.com/upload/vod/20231113-1/dd1ec0e056ad3e1e23f7bbd90dd315b0.jpg', 'https://phimimg.com/upload/vod/20231113-1/2b997b0114b1332be4b37f875bd913be.jpg', '<p>D đã được thuê để truy tìm Meier Link, một ma cà rồng nổi tiếng mạnh mẽ đã bắt cóc một phụ nữ, Charlotte Elbourne. Mệnh lệnh của D rất nghiêm ngặt - tìm Charlotte, bằng bất cứ giá nào. Lần đầu tiên, D phải đối mặt với sự cạnh tranh nghiêm trọng. Anh em nhà Markus, một gia đình Thợ săn ma cà rồng, được thuê với cùng một khoản tiền thưởng. D Phải đánh chặn Meier và chinh phục các thế lực thù địch từ mọi phía trong một cuộc chạy đua chết chóc với thời gian.</p>', 'Full', 1, 'single', 'completed', 24, 2000, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hideyuki Tanaka","avatar":""},{"name":"Ichiro Nagai","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Emi Shinohara","avatar":""},{"name":"Yusaku Yara","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Toshihiko Seki","avatar":""},{"name":"Ryuuzaburou Ootomo","avatar":""},{"name":"Takeshi Aono","avatar":""},{"name":"Motomu Kiyokawa","avatar":""},{"name":"Koji Tsujitani","avatar":""},{"name":"Rintaro Nishi","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Chikao Ohtsuka","avatar":""},{"name":"Yoko Soumi","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]',