INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gan-nhu-noi-tieng', 'Gần Như Nổi Tiếng', 'Almost Famous', 'https://phimimg.com/upload/vod/20231113-1/b97e73865e70d0d1ffc926f91538d08b.jpg', 'https://phimimg.com/upload/vod/20231113-1/cca4fafca30bcee907de4997fc2031ce.jpg', '<p>William Miller muốn trở thành nhà báo viết nhạc, cậu đi theo ban nhạc Still Water nhờ vào sự giúp đỡ của một cô gái tên Penny và bạn bè cô. Penny là ai? Một cô gái xinh đẹp đi cổ vũ những chàng trai hát rock. Và cũng như nhiều cô gái khác, họ đam mê âm nhạc và cả những con người chơi nhạc, họ sẵn sàng hiến dâng tất cả...</p>', 'Full', 1, 'single', 'completed', 20, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Fugit","avatar":""},{"name":"Billy Crudup","avatar":""},{"name":"Kate Hudson","avatar":""},{"name":"Frances McDormand","avatar":""},{"name":"Jason Lee","avatar":""},{"name":"Zooey Deschanel","avatar":""},{"name":"Michael Angarano","avatar":""},{"name":"Anna Paquin","avatar":""},{"name":"Fairuza Balk","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Noah Taylor","avatar":""},{"name":"John Fedevich","avatar":""},{"name":"Mark Kozelek","avatar":""},{"name":"Liz Stauber","avatar":""},{"name":"Jimmy Fallon","avatar":""},{"name":"Olivia Rosewood","avatar":""},{"name":"Bijou Phill","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324535);
