INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('blood-the-last-vampire', 'BLOOD THE LAST VAMPIRE', 'BLOOD THE LAST VAMPIRE', 'https://phimimg.com/upload/vod/20231111-1/9112a1e676afa3cc6cf4cf1d91adf6ad.jpg', 'https://phimimg.com/upload/vod/20231111-1/3b78b628be7118354d9a5d780ff2ccbf.jpg', '<p>Tại Nhật Bản, thợ săn ma cà rồng Saya, một người có sức mạnh nguyên thủy, được người liên lạc của cô với chính phủ, David, cử đến trường trung học Yokota vào đêm trước Halloween để săn lùng ma cà rồng. Saya yêu cầu David đưa cho cô ấy một thanh katana mới. Ngay sau đó, cô cứu được y tá Makiho Amano của trường khỏi hai ma cà rồng cải trang thành bạn cùng lớp và Makiho chứng kiến cô chiến đấu chống lại con quỷ mạnh mẽ.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2000, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Youki Kudoh","avatar":""},{"name":"Saemi Nakamura","avatar":""},{"name":"Joe Romersa","avatar":""},{"name":"Rebecca Forstadt","avatar":""},{"name":"Stuart Robinson","avatar":""},{"name":"Akira Koteyama","avatar":""},{"name":"Tom Fahn","avatar":""},{"name":"Fitz Houston","avatar":""},{"name":"Paul Carr","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324535);
