INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('28-days', '28 Days', '28 Days', 'https://phimimg.com/upload/vod/20231111-1/c07aeb1ad5dddbf3f814cc34c08c57cc.jpg', 'https://phimimg.com/upload/vod/20231111-1/a9f9eb6c1c0ef336ace3183ed82afd97.jpg', '<p>Sau khi gặp tai nạn xe hơi trong lúc say rượu vào ngày cưới của em gái, Gwen Cummings được đưa ra lựa chọn giữa nhà tù hoặc trung tâm cai nghiện. Cô chọn trại cai nghiện, nhưng cực kỳ phản đối việc tham gia bất kỳ chương trình điều trị nào mà họ đưa ra, từ chối thừa nhận rằng mình mắc chứng nghiện rượu.</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Viggo Mortensen","avatar":""},{"name":"Dominic West","avatar":""},{"name":"Elizabeth Perkins","avatar":""},{"name":"Azura Skye","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Alan Tudyk","avatar":""},{"name":"Mike O''Malley","avatar":""},{"name":"Marianne Jean-Baptiste","avatar":""},{"name":"Reni Santoni","avatar":""},{"name":"Diane Ladd","avatar":""},{"name":"Margo Martindale","avatar":""},{"name":"Susan Krebs","avatar":""},{"name":"Loudon Wainwright III","avatar":""},{"name":"Katie Scharf","avatar":""},{"name":"Meredith Dea","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324535);
