INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-cong-trong-bong-toi', 'Vũ Công Trong Bóng Tối', 'Dancer in the Dark', 'https://phimimg.com/upload/vod/20231111-1/b571435e59f853eaa8e365d5b7d0f36a.jpg', 'https://phimimg.com/upload/vod/20231111-1/2f82dbd4a4bedd28115b884418c610ab.jpg', '<p>Selma, một người Séc nhập cư sắp bị mù, phải vật lộn để kiếm đủ sống cho bản thân và con trai, người thừa hưởng chứng rối loạn di truyền giống nhau và sẽ chịu chung số phận nếu không có một cuộc phẫu thuật tốn kém. Khi cuộc sống trở nên quá khó khăn, Selma học cách đối phó với tình yêu âm nhạc của mình, thoát khỏi những rắc rối trong cuộc sống - dù chỉ trong chốc lát - bằng cách mơ những con số nhỏ theo nhịp điệu nhịp nhàng của môi trường xung quanh.</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Björk","avatar":""},{"name":"Catherine Deneuve","avatar":""},{"name":"David Morse","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Joel Grey","avatar":""},{"name":"Cara Seymour","avatar":""},{"name":"Vladica Kostic","avatar":""},{"name":"Jean-Marc Barr","avatar":""},{"name":"Vincent Paterson","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Zeljko Ivanek","avatar":""},{"name":"Udo Kier","avatar":""},{"name":"Jens Albinus","avatar":""},{"name":"Reathel Bean","avatar":""},{"name":"Mette Berggreen","avatar":""},{"name":"Lars Michael Dinesen","avatar":""},{"name":"Katrine Fal","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324535);
