INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-do-la', 'Phi Vụ Đô La', 'The Whole Nine Yards', 'https://phimimg.com/upload/vod/20231101-1/e447aa262f65c5552d561ec9813cb92e.jpg', 'https://phimimg.com/upload/vod/20231101-1/5d355a085d6d1a1df68b1bd56a84ef0c.jpg', '<p>Bộ phim kể về Nick - một anh chàng bác sĩ nha khoa ở Canada . Một hôm nhà bên canh có hàng xóm mới chuyển đến và anh phát hiện ra đó chính là Jimmy &quot;The Tulip&quot; Teduski, một tay sát thủ chuyên nghiệp. Vợ Nick bèn thuyết phục anh tới Chicago báo tin cho ông trùm của đám du đáng - kẻ mà muốn Jimmy phải chết.</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Matthew Perry","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Natasha Henstridge","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Rosanna Arquette","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"Harland Williams","avatar":""},{"name":"Carmen Ferland","avatar":""},{"name":"Serge Christianssens","avatar":""},{"name":"Renee Madeline Le Guerrier","avatar":""},{"name":"Jean-Guy Bouchard","avatar":""},{"name":"Howard Bilerman","avatar":""},{"name":"Johnny Goar","avatar":""},{"name":"Deano","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324535);
