INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-trang-khi-yeu', 'Tâm Trạng Khi Yêu', 'In the Mood for Love', 'https://phimimg.com/upload/vod/20231026-1/1e66b784030056ded90f5e2a7a440f0e.jpg', 'https://phimimg.com/upload/vod/20231026-1/b2520d21337b6194c3e0da1bd2020f17.jpg', '<p>Dù ở nơi đất khách quê người nhưng Châu Mộ Vân vẫn không thể nào quên được mối tình giữa anh và Tô Lệ Trân, nếu năm xưa cô quyết định theo anh ra đi thì giờ đây họ sẽ là một đôi tình nhân hạnh phúc hay vẫn phải chia cách? Có lẽ sẽ có người nói rằng từ ngày đầu tiên khi hai người họ cùng trong một ngày cùng dọn vào một căn nhà trọ và trở thành hàng xóm của nhau thì vận mệnh đã dần đưa hai người họ xích lại gần nhau hơn, và rồi ngẫu nhiên phát sinh những mối quan hệ không thể cho ai biết được.</p>', 'Full', 1, 'single', 'completed', 23, 2000, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Rebecca Pan","avatar":""},{"name":"Kelly Lai Chen","avatar":""},{"name":"Siu Ping-lam","avatar":""},{"name":"Chin Tsi-Ang","avatar":""},{"name":"Joe Cheung Tung-cho","avatar":""},{"name":"Ku Jin-Hwa","avatar":""},{"name":"Chan Man-Lei","avatar":""},{"name":"Paulyn Sun","avatar":""},{"name":"Roy Cheung","avatar":""},{"name":"Julien Carbon","avatar":""},{"name":"Charles de Gaulle","avatar":""},{"name":"Laurent Courtiaud","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
