INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-erin-brockovich', 'Nàng Erin Brockovich', 'Erin Brockovich', 'https://phimimg.com/upload/vod/20231030-1/5cc607277cfbcf2a7779483e5b3a9d7c.jpg', 'https://phimimg.com/upload/vod/20231030-1/778b1aa6471c5e24f54e245b6a8228cd.jpg', '<p>Một cựu hoa hậu ba con đã hai lần ly hôn, đến làm việc cho một luật sư và tình cờ xem được hồ sơ y tế mô tả các căn bệnh tập trung tại một thị trấn gần đó. Cô bắt đầu điều tra và sớm vạch trần một vụ che đậy kinh khủng.</p>', 'Full', 1, 'single', 'completed', 16, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julia Roberts","avatar":""},{"name":"Albert Finney","avatar":""},{"name":"Aaron Eckhart","avatar":""},{"name":"Marg Helgenberger","avatar":""},{"name":"Cherry Jones","avatar":""},{"name":"Veanne Cox","avatar":""},{"name":"Conchata Ferrell","avatar":""},{"name":"Tracey Walter","avatar":""},{"name":"Peter Coyote","avatar":""},{"name":"Michael Harney","avatar":""},{"name":"Scarlett Pomers","avatar":""},{"name":"Scotty Leavenworth","avatar":""},{"name":"Gina Gallego","avatar":""},{"name":"T.J. Thyne","avatar":""},{"name":"Valente Rodriguez","avatar":""},{"name":"Erin Brockovich","avatar":""},{"name":"Dav","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324535);
