INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nang-erin-brockovich', 'Nàng Erin Brockovich', 'Erin Brockovich', 'nàng erin brockovich erin brockovich julia roberts albert finney aaron eckhart marg helgenberger cherry jones veanne cox conchata ferrell tracey walter peter coyote michael harney scarlett pomers scotty leavenworth gina gallego t.j. thyne valente rodriguez erin brockovich dav ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-long', 'Khủng Long', 'Dinosaur', 'https://phimimg.com/upload/vod/20231022-1/8582c0e34a9b2634690f00c067f0f30c.jpg', 'https://phimimg.com/upload/vod/20231022-1/ea550f73bbd4cd01137ead9c33b38f5c.jpg', '<p>Nhân lúc một cặp vợ chồng khủng long ăn thịt Iguanodon rời tổ đi kiếm ăn, một con Oviraptor - loài khủng long chuyên trộm trứng - đã tới lấy cắp của trứng của chúng. Qua hàng loạt biến cố, quả trứng rơi xuống đảo Lemur, nơi sinh sống của loài vượn cáo. Sau khi trứng nở ra, một gia đình vượn cáo nuôi nó và đặt tên cho là Aladar. Khi một trận thiên thạch rơi xuống trái đất, Aladar và gia đình phải rời nơi sinh sống của mình, di tản và đối mặt với những nguy hiểm. Trên đường đi, họ đã gặp một đàn Iguanodon, đồng loại của Aladar, họ nhập đàn và tiếp tục một hành trình gian nan đi tìm vùng đất mới. Bộ phim tái hiện lại quang cảnh trái đất cách đây 65 triệu năm, khi khủng long là loài thống trị bề mặt hành tinh trước khi bị tuyệt chủng bởi vụ va chạm giữa trái đất với một thiên thạch khổng lồ. Các họa sĩ đã tới đảo Tahiti và Hawaii để vẽ những cảnh trong phim. Với kinh phí lên tới 200 triệu USD, Dinosaur trở thành bộ phim tốn kém nhất trong năm 2000.</p>', '', 0, 'hoathinh', 'completed', 18, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"D.B. Sweeney","avatar":""},{"name":"Alfre Woodard","avatar":""},{"name":"Ossie Davis","avatar":""},{"name":"Max Casella","avatar":""},{"name":"Hayden Panettiere","avatar":""},{"name":"Samuel E. Wright","avatar":""},{"name":"Julianna Margulies","avatar":""},{"name":"Peter Siragusa","avatar":""},{"name":"Joan Plowright","avatar":""},{"name":"Della Reese","avatar":""},{"name":"Cathy Cavadini","avatar":""},{"name":"Edie Lehmann Boddicker","avatar":""},{"name":"Matt Adler","avatar":""},{"name":"Sandina Bailo-Lape","avatar":""},{"name":"Zachary Bostrom","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324535);
