INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('3-ke-tron-tu', '3 Kẻ Trốn Tù', 'O Brother, Where Art Thou?', 'https://phimimg.com/upload/vod/20231016-1/48c86c409b4ca5159abffdaf3ac778cf.jpg', 'https://phimimg.com/upload/vod/20231016-1/ca7096ef1b8b28a222084cfcd857e7c5.jpg', '<p>Chúng ta sẽ làm quen với Everett ba hoa bốc phét lúc nào cũng bóng mượt, Delmar yếu đuối luôn tuềnh toàng và Pete cao kều tính tình đơ đơ. Cả ba bị xích chung trong một chiếc xiềng sắt khiến họ không thể chạy nhanh, chưa kể bộ quần áo tù nhân sẽ tố cáo thân phận họ. Để phá vỡ gông cùm và thay trang phục, Pete rủ bạn tù về nhà anh họ Wash nhưng vì món tiền thưởng, cả ba đã bị chính gã anh họ bán đứng. Để trả đũa bộ ba chôm luôn xe của nhà Wash cho cuộc hành trình phía trước.Trên đường đi họ gặp gỡ nhiều người bạn mới. Đầu tiên là anh chàng da đen Tommy có tài đánh đàn, hợp lại với nhau, bộ tứ tạo thành ban nhạc The Soggy Bottom Boys (Những chàng trai ướt mông). Chia tay với Tommy, nhóm tù nhân tiếp tục trở thành đồng phạm ...</p>', 'Full', 1, 'single', 'completed', 19, 2000, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"George Clooney","avatar":""},{"name":"John Turturro","avatar":""},{"name":"Tim Blake Nelson","avatar":""},{"name":"Charles Durning","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Michael Badalucco","avatar":""},{"name":"Holly Hunter","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Chris Thomas King","avatar":""},{"name":"Wayne Duvall","avatar":""},{"name":"Daniel von Bargen","avatar":""},{"name":"J.R. Horne","avatar":""},{"name":"Brian Reddy","avatar":""},{"name":"Frank Collison","avatar":""},{"name":"Musetta Vander","avatar":""},{"name":"Ray McKinnon","avatar":""},{"name":"Del P","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324535);
