INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('3-ke-tron-tu', '3 Kẻ Trốn Tù', 'O Brother, Where Art Thou?', '3 kẻ trốn tù o brother, where art thou? george clooney john turturro tim blake nelson charles durning john goodman michael badalucco holly hunter stephen root chris thomas king wayne duvall daniel von bargen j.r. horne brian reddy frank collison musetta vander ray mckinnon del p ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tau-ngam-u571', 'Tàu Ngầm U-571', 'U-571', 'https://phimimg.com/upload/vod/20231016-1/e00f4aaf9a94c772e87e16164b65f33e.jpg', 'https://phimimg.com/upload/vod/20231016-1/1c709e752e47c322af468f0bcaf4eb80.jpg', '<p>Bộ phim lấy bối cảnh cuộc chiến tranh thế giới lần thứ hai, khi các trận thủy chiến trở nên khốc liệt và tàn bạo nhất. Quân Đức đang có nhiều lợi thế vì đối thủ của họ không có khả năng bẽ các mã bảo vệ để xâm nhập vào hệ thống của Đức. Nhưng cho đến khi con tàu mang mã hiệu U phát ra tín hiệu khẩn SOS, thì quân Đồng Minh đã chộp lấy cơ hội và xâm nhập vào hệ thống bảo vệ của Đức. Nhưng chiếm được con tàu chỉ là bước đơn giản nhất. Trận chiến chỉ mới bắt đầu khi quân Đồng Minh bị mắc cạn trên chính con tàu ấy.</p>', 'Full', 1, 'single', 'completed', 21, 2000, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Matthew McConaughey","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Jon Bon Jovi","avatar":""},{"name":"David Keith","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Jake Weber","avatar":""},{"name":"Jack Noseworthy","avatar":""},{"name":"Tom Guiry","avatar":""},{"name":"Will Estes","avatar":""},{"name":"Terrence ''T.C.'' Carson","avatar":""},{"name":"Erik Palladino","avatar":""},{"name":"Dave Power","avatar":""},{"name":"Derk Cheetwood","avatar":""},{"name":"Matthew Settle","avatar":""},{"name":"Rebecca Tilne","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '