INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tau-ngam-u571', 'Tàu Ngầm U-571', 'U-571', 'tàu ngầm u-571 u-571 matthew mcconaughey bill paxton harvey keitel jon bon jovi david keith thomas kretschmann jake weber jack noseworthy tom guiry will estes terrence ''t.c.'' carson erik palladino dave power derk cheetwood matthew settle rebecca tilne ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-gioi-chung-khoan', 'Môi Giới Chứng Khoán', 'Boiler Room', 'https://phimimg.com/upload/vod/20231016-1/2a82f6b1ec55dd956a4e20d14026cf44.jpg', 'https://phimimg.com/upload/vod/20231016-1/164d195c0bf32d31afc6c9918f610920.jpg', '<p>Bỏ học giữa chừng khi đang là sinh viên đại học để tự tìm con đường làm giàu riêng, Seth Davis (Giovanni Ribisi) quyết định mở một sòng bạc bất hợp pháp tại căn nhà thuê của mình. Tuy nhiên, dù thành công về tiền bạc nhưng anh đã đóng cửa sòng bạc này theo nguyện vọng của cha - thẩm phán liên bang Marty Davis (Ron Rifkin), người đã luôn đặt rất nhiều kỳ vọng vào cậu con trai - và chuyển sang làm môi giới chứng khoán. Công việc này đã giúp Seth nhanh chóng đạt được mục tiêu với mức lương cao ngất ngưởng. Công việc thường ngày của Seth là gọi những cú điện đến danh sách những người giàu có, gây áp lực cho khách hàng để họ bán cổ phiếu với giá ưu đãi độc quyền cho hãng chứng khoán này. Thế nhưng một thời gian sau, anh lại phát hiện ra công việc của mình có vẻ bất ổn và bắt đầu tìm hiểu. Những gì mà anh phát hiện được là hết sức bất ngờ và đầy nguy hiểm cùng cánh cửa nhà tù rộng mở với mức án dài hạn...</p>', 'Full', 1, 'single', 'completed', 14, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Giovanni Ribisi","avatar":""},{"name":"Vin Diesel","avatar":""},{"name":"Nia Long","avatar":""},{"name":"Nicky Katt","avatar":""},{"name":"Scott Caan","avatar":""},{"name":"Ron Rifkin","avatar":""},{"name":"Jamie Kennedy","avatar":""},{"name":"Taylor Nichols","avatar":""},{"name":"Bill Sage","avatar":""},{"name":"Tom Everett Scott","avatar":""},{"name":"Ben Affleck","avatar":""},{"name":"Donna Mitchell","avatar":""},{"name":"André Vippolis","avatar":""},{"name":"Jon Abrahams","avatar":""},{"name":"Will McCormack","avatar":""},{"name":"Kirk Acevedo","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Judy Del","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324535);
