INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-dao', 'Tiểu Đảo', 'The Isle', 'https://phimimg.com/upload/vod/20231016-1/5cbf9ff9049a9c843907bfe7fb63d217.jpg', 'https://phimimg.com/upload/vod/20231016-1/26cc457544984eb927e2bc8f05c5d4e7.jpg', '<p>Bộ phim xoay quanh một địa điểm câu cá do một người phụ nữ còn trẻ làm chủ rất bình dị trên một hòn đảo nhỏ ngoài khơi. Và rồi định mệnh an bài khi sắp xếp cho người nữ chủ nhân của khu câu cá này phải lòng người đàn ông đang trốn tránh sự truy đuổi của pháp luật nên phải trốn lên hòn đảo này để né tránh.Và rồi chuyện tình yêu giữa một người phụ nữ câm và một người đàn ông đang bị truy nã bắt đầu...</p>', 'Full', 1, 'single', 'completed', 29, 2000, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Kim Yu-seok","avatar":""},{"name":"Suh Jung","avatar":""},{"name":"Seo Won","avatar":""},{"name":"Son Min-seok","avatar":""},{"name":"Cho Jae-hyun","avatar":""},{"name":"Hang-Seon Jang","avatar":""},{"name":"Han Ji-Sun","avatar":""},{"name":"Kang Jeong-sik","avatar":""},{"name":"Choi Hye-kyeong","avatar":""},{"name":"Jeon Seon-hwa","avatar":""},{"name":"Yoon Hee-won","avatar":""},{"name":"No Jin-won","avatar":""},{"name":"Yang Young-Jo","avatar":""},{"name":"Woo Seung-yeup","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324535);
