INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-mat-tich-2000', 'Chú Chó Mất Tích', 'Barking Dogs Never Bite', 'https://phimimg.com/upload/vod/20231016-1/9b5ec878faac507ea3e9daba9fe2ecda.jpg', 'https://phimimg.com/upload/vod/20231016-1/f352c76e219ee0dcc33eb0617f9e0942.jpg', '<p>Một giảng viên đại học bán thời gian nhàn rỗi cảm thấy khó chịu vì tiếng ngáp của một con chó gần đó. Anh ta quyết định hành động quyết liệt.</p>', 'Full', 1, 'single', 'completed', 20, 2000, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Sung-jae","avatar":""},{"name":"Bae Doona","avatar":""},{"name":"Byun Hee-bong","avatar":""},{"name":"Kim Ho-jung","avatar":""},{"name":"Koh Soo-hee","avatar":""},{"name":"Kim Roi-ha","avatar":""},{"name":"Kim Jin-goo","avatar":""},{"name":"Im Sang-soo","avatar":""},{"name":"Kwon Hyeok-pung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324535);
