INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-cau-cho-mot-giac-mo', 'Lời Nguyện Cầu Cho Một Giấc Mơ', 'Requiem for a Dream', 'https://phimimg.com/upload/vod/20231016-1/8d446b99b1b34544e7dfc3314b464fa0.jpg', 'https://phimimg.com/upload/vod/20231016-1/e5def83377cc10261b47c04dc4274a01.jpg', '<p>Phim Requiem for a Dream là một bộ phim mang tính nghệ thuật cao, bao gồm cả nội dung và cách thể hiện. Trong phim sử dụng rất nhiều hiệu ứng hình ảnh và âm thanh độc đáo, từ việc duplicate liên tục các sequence, ***g hai chuyển động song song multi-frame, fast motion, hiệu ứng mắt cá ( fish-eye ) hay đoạn motion blur lúc Sara trên đường lên tàu hỏa nhưng hiệu ứng hình ảnh mình thích nhất lại là thủ pháp treo camera trước khuôn mặt của nhân vật và để mặc cho khuôn hình đằng sau chuyển động, những cảnh quay như thế này tạo được hiệu quả rất cao trong phim và làm mình rất thích, nhất là lúc Tyrone chạy trốn cảnh sát rồi màn hình đen kịt ập đến hiện lên chữ “FALL”. Cái fish-eye mình đã thấy dùng trong nhiếp ảnh nhiều nhưng ...</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ellen Burstyn","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Marlon Wayans","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Louise Lasser","avatar":""},{"name":"Marcia Jean Kurtz","avatar":""},{"name":"Janet Sarno","avatar":""},{"name":"Suzanne Shepherd","avatar":""},{"name":"Joanne Gordon","avatar":""},{"name":"Charlotte Aronofsky","avatar":""},{"name":"Mark Margolis","avatar":""},{"name":"Michael Kaycheck","avatar":""},{"name":"Jack O''Connell","avatar":""},{"name":"Chas Mastin","avatar":""},{"name":"Ajay","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324535);
