INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('riddick-hanh-tinh-tam-toi', 'Riddick: Hành Tinh Tăm Tối', 'Pitch Black', 'https://phimimg.com/upload/vod/20231016-1/7c5fcfb312fda03edf61c1d044a22c5a.jpg', 'https://phimimg.com/upload/vod/20231016-1/4e66d80f49b2719ddeb82e796638ad8e.jpg', '<p>Con tàu Hunter Gratzner chở 40 hành khách rơi xuống hành tinh lạ sau khi va chạm với thiên thể. 12 còn sống sót, trong đó có tên tội phạm Riddick đang bị áp giải, đi tìm sự sống ở hành tinh có 3 mặt trời này. Khi đêm xuống, không chỉ có Riddick mới là nỗi sợ hãi của đoàn người... Dẫn dắt nhóm người tìm đến khu cung cấp nhiên liệu để vận hành lại con tàu vũ trụ, Riddick phát hiện ra họ không phải là những thực thể sống duy nhất trên hành tinh này.</p>', 'Full', 1, 'single', 'completed', 18, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vin Diesel","avatar":""},{"name":"Radha Mitchell","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Lewis Fitz-Gerald","avatar":""},{"name":"Claudia Black","avatar":""},{"name":"Keith David","avatar":""},{"name":"Rhiana Griffith","avatar":""},{"name":"John Moore","avatar":""},{"name":"Simon Burke","avatar":""},{"name":"Les Chantery","avatar":""},{"name":"Sam Sari","avatar":""},{"name":"Firass Dirani","avatar":""},{"name":"Ric Anderson","avatar":""},{"name":"Vic Wilson","avatar":""},{"name":"Angela Moore","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324535);
