INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-tinh-do', 'Hành Tinh Đỏ', 'Red Planet', 'https://phimimg.com/upload/vod/20231016-1/8a6f5725161a05f4006e2315ec211bbb.jpg', 'https://phimimg.com/upload/vod/20231016-1/c86726f571069c766f69e7a48dc050bc.jpg', '<p>Các phi hành gia tìm kiếm giải pháp để cứu Trái đất đang hấp hối bằng cách tìm kiếm trên Sao Hỏa, nhưng sứ mệnh lại trở nên vô cùng tồi tệ.</p>', 'Full', 1, 'single', 'completed', 19, 2000, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Val Kilmer","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"Simon Baker","avatar":""},{"name":"Terence Stamp","avatar":""},{"name":"Jessica Morton","avatar":""},{"name":"Bob Neill","avatar":""},{"name":"Caroline Bossi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324535);
