INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-tinh-duc', 'Con Đường Tình Dục', 'Road Trip', 'https://phimimg.com/upload/vod/20231016-1/1c5f22d8d065d09c1adad3eb91882633.jpg', 'https://phimimg.com/upload/vod/20231016-1/ee5681154fddca3b86b70e09c4aac0bd.jpg', '<p>Từ đạo diễn của bộ ba Hangover và Joker, Road Trip là một bộ phim hài kinh điển thời đại học. Sau khi một sinh viên đại học Ithaca quay cảnh tình một đêm của mình với một cô gái nữ sinh xinh đẹp, anh ta phát hiện ra một trong những người bạn của mình đã vô tình gửi đoạn băng khiêu dâm tự chế qua đường bưu điện cho bạn gái của anh ta. Trong cơn điên cuồng, anh ta phải mượn xe và lên đường trong nỗ lực truy cản băng. Với dàn diễn viên tài năng bao gồm Breckin Meyer, Rachel Blanchard, Seann William Scott, Amy Smart, Fred Ward, Tom Green, Anthony Rapp, Andy Dick và Ethan Suplee.</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Breckin Meyer","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Paulo Costanzo","avatar":""},{"name":"DJ Qualls","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"Tom Green","avatar":""},{"name":"Rachel Blanchard","avatar":""},{"name":"Anthony Rapp","avatar":""},{"name":"Andy Dick","avatar":""},{"name":"Fred Ward","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"Horatio Sanz","avatar":""},{"name":"Marla Sucharetza","avatar":""},{"name":"Rhoda Griffis","avatar":""},{"name":"Jessica Cauffiel","avatar":""},{"name":"Patricia Gaul","avatar":""},{"name":"Mary Lynn Rajskub","avatar":""},{"name":"Jim","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324535);
