INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-thoi-tien-su-7-hon-da-thien-thach', 'Vùng Đất Thời Tiền Sử 7: Hòn Đá Thiên Thạch', 'The Land Before Time VII: The Stone of Cold Fire', 'https://phimimg.com/upload/vod/20231016-1/a7d54dfae853a1d788b7da9f372ef8bd.jpg', 'https://phimimg.com/upload/vod/20231016-1/3810396b3428ba5c8f51c3451bdd61f7.jpg', '<p>Littlefoot và những người bạn của mình lên đường tìm kiếm &quot;hòn đá lửa lạnh&quot; từ bầu trời đêm rơi xuống. Vì anh ấy là người duy nhất nhìn thấy nó nên không ai thực sự tin anh ấy. Chú của Petrie, Pterano, chỉ đưa ra sự hỗ trợ vì ông cho rằng viên đá có sức mạnh bí mật và muốn nó cho riêng mình nhưng lại che giấu điều này với những người còn lại. Những chú khủng long trẻ tuổi phải tìm ra sự thật trước khi Pterano có được sức mạnh.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 2000, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Thomas Dekker","avatar":""},{"name":"Kenneth Mars","avatar":""},{"name":"Miriam Flynn","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Aria Noelle Curzon","avatar":""},{"name":"Anndi McAfee","avatar":""},{"name":"John Ingle","avatar":""},{"name":"Charles Kimbrough","avatar":""},{"name":"Patti Deutsch","avatar":""},{"name":"Tress MacNeille","avatar":""},{"name":"Michael York","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Zoë Gulliksen","avatar":""},{"name":"B.J. Ward","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324535);
