INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-truong-trai-dat', 'Chiến Trường Trái Đất', 'Battlefield Earth', 'https://phimimg.com/upload/vod/20231016-1/a574b76c3b4612a4fc30304cdf0dfc78.jpg', 'https://phimimg.com/upload/vod/20231016-1/1da59d6d6948cdfd06380f082cb55cee.jpg', '<p>Vào năm 3000, tộc người ngoài hành tinh Psychlos tàn phá Trái Đất và biến những người sống sót thành nô lệ.</p>', 'Full', 1, 'single', 'completed', 19, 2000, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"John Travolta","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Kim Coates","avatar":""},{"name":"Sabine Karsenti","avatar":""},{"name":"Christian Tessier","avatar":""},{"name":"Sylvain Landry","avatar":""},{"name":"Michael Byrne","avatar":""},{"name":"Richard Tyson","avatar":""},{"name":"Christopher Freeman","avatar":""},{"name":"Shaun Austin-Olsen","avatar":""},{"name":"Tim Post","avatar":""},{"name":"Earl Pastko","avatar":""},{"name":"Michel Perron","avatar":""},{"name":"Andy Bradshaw","avatar":""},{"name":"Tait Ruppert","avatar":""},{"name":"Kelly P","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324535);
