INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vien-keo-ngot-ngao', 'Viên Kẹo Ngọt Ngào', 'Chocolat', 'https://phimimg.com/upload/vod/20231016-1/a4c6f9d41d2911c50987ade210278188.jpg', 'https://phimimg.com/upload/vod/20231016-1/9e31c6e0b0e24bfddf9db395ca804f01.jpg', '<p>Chocolat (Viên Kẹo Ngọt Ngào) là một bộ phim tâm lý - lãng mạn được dựa trên truyện ngắn cùng tên của tác giả Joanne Haris do đạo diễn Lasse Hallström thực hiện theo kịch bản Robert Nelson Jacobs. Một câu chuyện của thời hiện đại nhưng nó được kể theo phong cách của chuyện cổ tích: “Ngày xửa ngày xưa, tại một thị trấn tĩnh lặng ở một miền quê nước Pháp, ở nơi đó mọi người đều tin vào sự yên bình, sự thanh thản&quot;. Vào một ngày, khi cơn gió phía bắc thổi tới mang theo cô gái trẻ Vianne Rocher (Juliette Binoche) cùng cô con gái nhỏ 6 tuổi Anouk Rocher (Victoire Thivisol) đến ngôi làng Lansquenet-sous-Tannes. Cô mở ra La Chocolaterie Maya, một cửa tiệm nhỏ bán sôcôla. Những viên sôcôla ngọt ngào nhanh chóng khuấy động cuộc sống vốn tĩnh lặng của thị trấn nhỏ cổ kính. Những người dân ở đây sau khi nếm những loại kẹo kỳ diệu của cô đã rũ bỏ vẻ đạo mạo để sống một cuộc sống mới đầy đam mê. Tuy nhiên, cuộc đời cô chỉ thực sự thay đổi khi một khách lạ bất ngờ xuất hiện...</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Juliette Binoche","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Johnny Depp","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Leslie Caron","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"Aurelien Parent Koenig","avatar":""},{"name":"Lena Olin","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"John Wood","avatar":""},{"name":"Antonio Gil","avatar":""},{"name":"Hélène Cardona","avatar":""},{"name":"Hugh O''Conor","avatar":""},{"name":"Victoire Thivisol","avatar":""},{"name":"Gaelan Connell","avatar":""},{"name":"Élisabeth Commelin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
