INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-co-gai', '100 Cô Gái', '100 Girls', 'https://phimimg.com/upload/vod/20231016-1/4609b3e38ebc9ef2cf5dfe6e7fc47b99.jpg', 'https://phimimg.com/upload/vod/20231016-1/36367e64d56abe82c43d422534e72ed8.jpg', '<p>Matthew, chàng sinh viên vừa mới nhập trường đang trải qua những ngày cô đơn thì vô tình có một cuộc gặp gỡ đầy nhân duyên trong thang máy bị cúp điện. Họ cùng nhau tận hưởng một đêm tuyệt vời trong bóng tối. Khi chàng nhận ra cô gái đó chính là tình yêu đích thực thì cô gái đã biến mất. Manh mối duy nhất là cô nàng ở ký túc xá này. Nhưng có đến 100 cô gái ở đây, liệu Matthew có tìm đúng người mà anh yêu?</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonathan Tucker","avatar":""},{"name":"Emmanuelle Chriqui","avatar":""},{"name":"James DeBello","avatar":""},{"name":"Katherine Heigl","avatar":""},{"name":"Larisa Oleynik","avatar":""},{"name":"Jaime Pressly","avatar":""},{"name":"Marissa Ribisi","avatar":""},{"name":"Johnny Green","avatar":""},{"name":"Aimee Graham","avatar":""},{"name":"Kristina Anapau","avatar":""},{"name":"Ange Billman","avatar":""},{"name":"Rainbeau Mars","avatar":""},{"name":"Mónica Huarte","avatar":""},{"name":"Reilly McLaren","avatar":""},{"name":"Kristin Herold","avatar":""},{"name":"Anya Marina","avatar":""},{"name":"Josep","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
