INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('batman-su-tro-lai-cua-joker', 'Batman: Sự Trở Lại Của Joker', 'Batman Beyond: Return of the Joker', 'https://phimimg.com/upload/vod/20231016-1/97b1d855c248435d2402e7ebf5185b76.jpg', 'https://phimimg.com/upload/vod/20231016-1/96da4f66afa2b54fb09a822ab914f8e6.jpg', '<p>Phim Batman Beyond: Return Of The Joker nói về chuyện xảy ra sau khi Bruce Wayne đã già và giao vai trò Batman cho Terry McGinnis. Mọi chuyện vẫn yên ổn cho đến khi Joker xuất hiện trở lại và trẻ như mấy chục năm trước. Tại sao có thể như vậy? Tim Drake có liên quan gì đến chuyện này? và cuộc điều tra sẽ đi đến đâu, những bí mật nào sẽ được làm sáng tỏ?</p>', 'Full', 1, 'single', 'completed', 20, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Friedle","avatar":""},{"name":"Kevin Conroy","avatar":""},{"name":"Mark Hamill","avatar":""},{"name":"Angie Harmon","avatar":""},{"name":"Dean Stockwell","avatar":""},{"name":"Arleen Sorkin","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Mathew Valencia","avatar":""},{"name":"Andrea Romano","avatar":""},{"name":"Melissa Joan Hart","avatar":""},{"name":"Henry Rollins","avatar":""},{"name":"Michael Rosenbaum","avatar":""},{"name":"Don Harvey","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Rachael Leigh Cook","avatar":""},{"name":"Lauren Tom","avatar":""},{"name":"Teri Garr","avatar":""},{"name":"Ry","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324535);
