INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trua-thuong-hai', 'Trưa Thượng Hải', 'Shanghai Noon', 'https://phimimg.com/upload/vod/20231016-1/7b614d046e87ba0ce43b1001e4c34199.jpg', 'https://phimimg.com/upload/vod/20231016-1/46da13b4128cfd299bae9cd0f38d75f4.jpg', '<p>Công chúa Pei Pei bị bắt cóc khỏi Tử Cấm Thành đưa đến nước Mỹ xa xôi. Chon Wang tuy không được chọn vẫn xung phong gia nhập đội quân đi giải cứu vì chàng đã trót thương thầm nàng công chúa. Trải qua bao sóng gió và những giây phút nguy hiểm đến tính mạng, anh đã bảo vệ công chúa an toàn, nhưng nàng không muốn trở về với cương vị công chúa cao quý...</p>', 'Full', 1, 'single', 'completed', 25, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Roger Yuan","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Brandon Merrill","avatar":""},{"name":"Jason Connery","avatar":""},{"name":"Adrien Dorval","avatar":""},{"name":"Stacy Grant","avatar":""},{"name":"Kate Luyben","avatar":""},{"name":"Henry O","avatar":""},{"name":"Simon Baker","avatar":""},{"name":"Alan C. Peterson","avatar":""},{"name":"Rad Daly","avatar":""},{"name":"Eliza Norbury","avatar":""},{"name":"Eric Chen","avatar":""},{"name":"Cui Ya Hui","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324535);
