INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-xe-taxi-2', 'Quái Xế Taxi 2', 'Taxi 2', 'https://phimimg.com/upload/vod/20231016-1/8f9a200fe4d84bc0ceb49005243b1b22.jpg', 'https://phimimg.com/upload/vod/20231016-1/c633e53ff50bf6b2531201da44b43451.jpg', '<p>Trong chuyến công du tới Pháp, bộ trưởng quốc phòng Nhật có ghé thăm Marseille để tham khảo những kỹ năng huấn luyện chống khủng bố của cảnh sát tại thành phố này. Thật không may, ông lại bị bắt cóc bởi một nhóm người làm việc cho tổ chức tội phạm yakura của Nhật. Daniel (Samy Naceri) trong vai một anh chàng sinh viên y khoa, nhưng thực chất anh là một chàng lái taxi rất chuyên nghiệp. Vốn không ưa cảnh sát nhưng tình cờ, anh buộc lòng hợp tác với cảnh sát Émilien (Frédéric Diefenthal) - người bạn thân anh rất yêu mến, để giải cứu ngài bộ trưởng thoát khỏi bàn tay bọn bắt cóc. Cuộc đua tốc độ xảy ra, Taxi 2 đã sẵn sàng lao vào khuấy động thành phố Paris hoa lệ và êm đềm!</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Samy Naceri","avatar":""},{"name":"Frédéric Diefenthal","avatar":""},{"name":"Marion Cotillard","avatar":""},{"name":"Emma Wiklund","avatar":""},{"name":"Bernard Farcy","avatar":""},{"name":"Jean-Christophe Bouvet","avatar":""},{"name":"Frédérique Tirmont","avatar":""},{"name":"Marc Faure","avatar":""},{"name":"Haruhiko Hirata","avatar":""},{"name":"Tsuyu Shimizu","avatar":""},{"name":"Ko Suzuki","avatar":""},{"name":"Yoshi Oida","avatar":""},{"name":"Kentaro","avatar":""},{"name":"Hiro Uchiyama","avatar":""},{"name":"Onochi Seietsu","avatar":""},{"name":"Édouard Montoute","avatar":""},{"name":"Franç","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324535);
