INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-phu-nu-muon', 'Điều phụ nữ muốn', 'What Women Want', 'https://phimimg.com/upload/vod/20231016-1/157e622216cff8dec54c62878fc89129.jpg', 'https://phimimg.com/upload/vod/20231016-1/386e6019bb829c78bf0d9c2af4e5d880.jpg', '<p>Giám đốc quảng cáo Nick Marshall luôn tỏ ra tự mãn, nhưng điều gì sẽ xảy ra với một anh chàng theo chủ nghĩa sô-vanh khi anh ta đột nhiên có thể nghe được suy nghĩ của phụ nữ? Nick không được thăng chức, nhưng sau một tai nạn khiến anh có thể nghe được suy nghĩ của phụ nữ, anh dùng tài năng mới tìm được của mình để chống lại Darcy, ông chủ mới của anh, người dường như say mê anh.</p>', 'Full', 1, 'single', 'completed', 12, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Helen Hunt","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Alan Alda","avatar":""},{"name":"Ashley Johnson","avatar":""},{"name":"Mark Feuerstein","avatar":""},{"name":"Lauren Holly","avatar":""},{"name":"Delta Burke","avatar":""},{"name":"Valerie Perrine","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Sarah Paulson","avatar":""},{"name":"Ana Gasteyer","avatar":""},{"name":"Lisa Edelstein","avatar":""},{"name":"Loretta Devine","avatar":""},{"name":"Diana Maria Riva","avatar":""},{"name":"Eric Balfour","avatar":""},{"name":"Andrea Baker","avatar":""},{"name":"Robin Pear","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
