INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-duoi-nam-mo', 'Bí Ẩn Dưới Nấm Mồ', 'The Cell', 'https://phimimg.com/upload/vod/20231016-1/424dd03051a02d6c315f19d1adf34ddb.jpg', 'https://phimimg.com/upload/vod/20231016-1/fe77634ec489339513c37c7e02c17ace.jpg', '<p>Với những nghiên cứu của mình trong việc trấn áp tội phạm, FBI đã tạo ra một cổ máy khiến con người có thể chìm trong một thế giới ảo với những sức mạnh siêu nhiên....Catharine Deane là một chuyên gia khoa học về chế tạo những công cụ cho FBI, chính vì đó những tên tội phạm đã bắt cóc gia đình nhằm uy hiếp trong vòng 48 tiếng phải giao cho chúng tất cả công nghệ mới này để giúp cho những tên tội phạm này thống trị và trả thù lại FBI.</p>', 'Full', 1, 'single', 'completed', 20, 2000, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Jennifer Lopez","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Catherine Sutherland","avatar":""},{"name":"James Gammon","avatar":""},{"name":"Colton James","avatar":""},{"name":"Dylan Baker","avatar":""},{"name":"Marianne Jean-Baptiste","avatar":""},{"name":"Gerry Becker","avatar":""},{"name":"Musetta Vander","avatar":""},{"name":"Patrick Bauchau","avatar":""},{"name":"Jake Weber","avatar":""},{"name":"Dean Norris","avatar":""},{"name":"Tara Subkoff","avatar":""},{"name":"Lauri Johnson","avatar":""},{"name":"John Cothran","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324535);
