INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-thu-6', 'Ngày Thứ 6', 'The 6th Day', 'https://phimimg.com/upload/vod/20231016-1/b12205f3dc428ca719a897823750215d.jpg', 'https://phimimg.com/upload/vod/20231016-1/30ce5edacb96a933e03f725efc94a7af.jpg', '<p>Phim lấy bối cảnh của tương lai sắp tới, khi mà con người đã nắm vững quy trình nhân bản. Con người có thể nhân bản mọi sinh vật dù sống hay đã chết. Nhưng việc nhân bản con người là điều luôn bị cấm kị. Tuy nhiên, một nhóm người có âm mưu đen tối vẫn lén lút thực hiện công việc đó.</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Michael Rapaport","avatar":""},{"name":"Tony Goldwyn","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Sarah Wynter","avatar":""},{"name":"Wendy Crewson","avatar":""},{"name":"Rodney Rowland","avatar":""},{"name":"Terry Crews","avatar":""},{"name":"Ken Pogue","avatar":""},{"name":"Colin Cunningham","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Wanda Cannon","avatar":""},{"name":"Taylor Reid","avatar":""},{"name":"Jennifer Gareis","avatar":""},{"name":"Don McManus","avatar":""},{"name":"Steve Bacic","avatar":""},{"name":"Christopher","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324535);
