INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ngai-hai-mat', 'Quý Ngài Hai Mặt', 'Me, Myself & Irene', 'https://phimimg.com/upload/vod/20231016-1/7a0f7944b79a10ba041167c05db92067.jpg', 'https://phimimg.com/upload/vod/20231016-1/ed43ac4979b25be269938aac5d6b42c8.jpg', '<p>Quân nhân bang Rhode Island Charlie Baileygates mắc chứng rối loạn đa nhân cách. Một người có tính cách điên rồ và hung hãn, trong khi người kia thân thiện và thoải mái hơn. Cả hai nhân cách này đều yêu cùng một người phụ nữ tên Irene sau khi Charlie hết thuốc.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Renée Zellweger","avatar":""},{"name":"Anthony Anderson","avatar":""},{"name":"Robert Forster","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Zen Gesner","avatar":""},{"name":"Mongo Brownlee","avatar":""},{"name":"Jerod Mixon","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Cam Neely","avatar":""},{"name":"Shannon Whirry","avatar":""},{"name":"Traylor Howard","avatar":""},{"name":"Tony Cox","avatar":""},{"name":"Rob Moran","avatar":""},{"name":"Nikki Tyler-Flynn","avatar":""},{"name":"Steve Tyler","avatar":""},{"name":"Richard Tyson","avatar":""},{"name":"Michael B","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324535);
