INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quy-ngai-hai-mat', 'Quý Ngài Hai Mặt', 'Me, Myself & Irene', 'quý ngài hai mặt me, myself & irene jim carrey renée zellweger anthony anderson robert forster richard jenkins zen gesner mongo brownlee jerod mixon chris cooper cam neely shannon whirry traylor howard tony cox rob moran nikki tyler-flynn steve tyler richard tyson michael b ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-vo-dao', 'Kẻ Vô Đạo', 'Amores perros', 'https://phimimg.com/upload/vod/20231016-1/444bc0e68351c31b62c6be556b5f5cd7.jpg', 'https://phimimg.com/upload/vod/20231016-1/6475423c54c02897858fb17de254ce02.jpg', '<p>Bộ phim Amores Perros (Kẻ Vô Đạo) hay còn có tên Love Dogs (Những Kẻ Yêu Chó) là ba câu chuyện riêng biệt xoanh quanh một vụ tai nạn, ba câu chuyện về những cảnh đời rất khác nhau nhưng đều có một chủ đề chung: những mất mát, tổn thương con người phải đối diện trong đời, mà đôi khi những điều đó lại đến nhân danh tình yêu. Một cô người mẫu, người được mệnh danh là đẹp nhất Trung Mỹ, yêu thật lòng 1 người đàn ông khiến ông này phải bỏ vợ và 2 đứa con để đến với cô. Nhưng rồi tai nạn xảy ra, cô mất đi sự nghiệp, danh vọng, và suýt mất đi tình yêu. Một anh chàng yêu chị dâu mình, thù anh trai mình, người không thể mang lại hạnh phúc cho cô gái kia. Một tình yêu dại dột liều lĩnh, khiến anh phản bội người anh của mình, nhưng nó không hứa hẹn hạnh phúc. Câu chuyện thứ 3 là về một lão sát thủ già sống cùng đàn chó trong khu ổ chuột chuyên đi giết thuê cho những kẻ phản bội...</p>', 'Full', 1, 'single', 'completed', 22, 2000, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Gael García Bernal","avatar":""},{"name":"Vanessa Bauche","avatar":""},{"name":"Goya Toledo","avatar":""},{"name":"Álvaro Guerrero","avatar":""},{"name":"Emilio Echevarría","avatar":""},{"name":"Jorge Salinas","avatar":""},{"name":"Rodrigo Murray","avatar":""},{"name":"Humberto Busto","avatar":""},{"name":"Gerardo Campbell","avatar":""},{"name":"Rosa María Bianchi","avatar":""},{"name":"Dunia Saldívar","avatar":""},{"name":"Adriana Barraza","avatar":""},{"name":"José Sefami","avatar":""},{"name":"Lourdes Echevarría","avatar":""},{"name":"Marco Pérez","avatar":""},{"name":"Laura","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324535);
