INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoa-ho-tang-long', 'Ngọa Hổ Tàng Long', 'Crouching Tiger, Hidden Dragon', 'https://phimimg.com/upload/vod/20231016-1/67845f1c77229d0818226ddcd5e1aa64.jpg', 'https://phimimg.com/upload/vod/20231016-1/43861f50a3294ed673bd929c43dacc34.jpg', '<p>Câu chuyện bắt đầu từ thanh bảo kiếm Lục Mệnh đã có hơn 400 năm tung hoành giang hồ, mà chủ nhân gần đây của nó là Lý Mộ Bạch (Châu Nhuận Phát) – một cao thủ phái Võ Đang có thể xem là thiên hạ vô địch hiện nay. Dự định rút lui giang hồ, Lý Mộ Bạch đã trao tặng Lục Mệnh kiếm cho Tề lão gia ở kinh thành, tuy nhiên thanh kiếm đã bị một kẻ võ công cao siêu đánh cắp. Có mặt ở hiện trường lúc đó, và đã từng giao đấu với kẻ trộm là nữ hiệp Du Tú Liên (Dương Tử Quỳnh) – chủ nhân của Thái Dương Tiêu Cục. Tên trộm nhờ đồng bọn trợ giúp, Du Tú Liên đã không thể bắt được hắn. Đối tượng mà Du Tú Liên nghi ngờ nhất là tiểu thư của tuần phủ đại nhân – Ngọc Kiều Long.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Zhang Ziyi","avatar":""},{"name":"Chang Chen","avatar":""},{"name":"Sihung Lung","avatar":""},{"name":"Cheng Pei-pei","avatar":""},{"name":"Li Fazeng","avatar":""},{"name":"Gao Xi''an","avatar":""},{"name":"Hai Yan","avatar":""},{"name":"Wang Deming","avatar":""},{"name":"Li Li","avatar":""},{"name":"Suying Huang","avatar":""},{"name":"Zhang Jinting","avatar":""},{"name":"Rui Yang","avatar":""},{"name":"Chen Bing","avatar":""},{"name":"Zhang Jin","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
