INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoa-ho-tang-long', 'Ngọa Hổ Tàng Long', 'Crouching Tiger, Hidden Dragon', 'ngọa hổ tàng long crouching tiger, hidden dragon chow yun-fat michelle yeoh zhang ziyi chang chen sihung lung cheng pei-pei li fazeng gao xi''an hai yan wang deming li li suying huang zhang jinting rui yang chen bing zhang jin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-vo-hinh', 'Người Vô Hình', 'Hollow Man', 'https://phimimg.com/upload/vod/20231016-1/20d2c83eb994b9230bceb55a79143969.jpg', 'https://phimimg.com/upload/vod/20231016-1/aaae69d0608d58ba8bb4209e4d2e761b.jpg', '<p>Tại một phòng thí nghiệm quân sự tối mật, sau nhiều năm nghiên cứu một nhóm các nhà khoa học trẻ tuổi xuất sắc vừa giải mã được chìa khóa của sự vô hình. Người nhóm trưởng kiêu ngạo Sebastian Caine (Kevin Bacon) đã bỏ mặc mọi nguy hiểm để thử nghiệm trên chính cơ thể mình. Trong khi các đồng nghiệp đang ra sức tìm thuốc giải, thì men say về sức mạnh vô hình của anh ta ngày càng tăng. Và anh ta tin rằng, các đồng nghiệp của mình chính là mối đe dọa cho sự tồn tại quyền lực vô hình này và Sebastian đã bắt đầu giết những người của nhóm nghiên cứu trong đó có Linda (Elisabeth Shue) và Matthew (Josh Brolin) phải tìm cách ngăn chặn âm mưu của Sebastian dưới cuộc rượt đuổi vô hình chết chóc trong phòng thí nghiệm…</p>', 'Full', 1, 'single', 'completed', 19, 2000, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Kevin Bacon","avatar":""},{"name":"Elisabeth Shue","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Kim Dickens","avatar":""},{"name":"Greg Grunberg","avatar":""},{"name":"Joey Slotnick","avatar":""},{"name":"Mary Randle","avatar":""},{"name":"William Devane","avatar":""},{"name":"Rhona Mitra","avatar":""},{"name":"Pablo Espinosa","avatar":""},{"name":"Jeffrey Scaperrotta","avatar":""},{"name":"Tom Woodruff Jr.","avatar":""},{"name":"Margot Rose","avatar":""},{"name":"Jimmie F. Skaggs","avatar":""},{"name":"Sarah Bowles","avatar":""},{"name":"Kelli Scott","avatar":""},{"name":"J. Patrick McCo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324535);
