INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-go-thong-gia', 'Gặp Gỡ Thông Gia', 'Meet the Parents', 'https://phimimg.com/upload/vod/20231016-1/54befd68ba29155040ebafce65b3c777.jpg', 'https://phimimg.com/upload/vod/20231016-1/48dd137f7dea175c3d5ffcb9eba8a32d.jpg', '<p>Một anh chàng muốn xin bố của bạn gái chúc phúc cho hôn lễ của họ, trong khi ông bố là cựu nhân viên CIA chỉ nhăm nhe gắn máy phát hiện nói dối lên anh chàng.</p>', 'Full', 1, 'single', 'completed', 13, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Stiller","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Teri Polo","avatar":""},{"name":"Blythe Danner","avatar":""},{"name":"Nicole DeHuff","avatar":""},{"name":"Jon Abrahams","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"James Rebhorn","avatar":""},{"name":"Tom McCarthy","avatar":""},{"name":"Phyllis George","avatar":""},{"name":"Kali Rocha","avatar":""},{"name":"Bernie Sheredy","avatar":""},{"name":"Judah Friedlander","avatar":""},{"name":"Peter Bartlett","avatar":""},{"name":"John Elsen","avatar":""},{"name":"Mark Hammer","avatar":""},{"name":"Amy Hohn","avatar":""},{"name":"William Severs","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
