INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hai-tac-1-dao-chau-bau', 'Đảo Hải Tặc 1: Đảo Châu Báu', 'One Piece: The Movie', 'https://phimimg.com/upload/vod/20231015-1/97899d5d5dc170c905ea3045882c7fb6.jpg', 'https://phimimg.com/upload/vod/20231015-1/2ade79773796bd12b5980b9a0d94e71d.jpg', '<p>Đảo Hải Tặc 1: Đảo Châu Báu – Tương truyền rằng, 1/3 số vàng trên thế giới được nắm giữa trong tay một hải tặc ngoại hiệu là Woonan Vĩ Đại. Nhiều năm sau đó, bí mật nơi tên hải tặc vĩ đại này cất giấu số của cải trở thành mục tiêu săn tìm của bọn cướp biển và cả những tên săn trộm máu mặt khắp đại dương.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 2000, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mayumi Tanaka","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Yuka Imai","avatar":""},{"name":"Takeshi Aono","avatar":""},{"name":"Taiki Matsuno","avatar":""},{"name":"Nachi Nozawa","avatar":""},{"name":"Takeshi Kusao","avatar":""},{"name":"Kenji Utsumi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324535);
