INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-kha-xam-pham', 'Bất Khả Xâm Phạm', 'Unbreakable', 'https://phimimg.com/upload/vod/20231015-1/87061a693042a585390f08eae21b9531.jpg', 'https://phimimg.com/upload/vod/20231015-1/df153b1dca3142777cfe3f048373102c.jpg', '<p>David Dunn (Willis) đang đi tàu từ Thành phố New York trở về nhà đến Philadelphia sau một cuộc phỏng vấn xin việc không suôn sẻ khi xe của anh ta nhảy xuống đường ray và va chạm với một động cơ đang lao tới, David là người sống sót duy nhất trong số 131 hành khách trên bảng. Thật đáng kinh ngạc, David không chỉ còn sống mà dường như anh ấy hầu như không hề bị chạm vào. Khi David tự hỏi điều gì đã xảy ra với anh ấy và tại sao anh ấy có thể bỏ đi, anh ấy gặp một người lạ bí ẩn, Elijah Prince (Samuel L.Jackson), người giải thích cho…</p>', 'Full', 1, 'single', 'completed', 18, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Spencer Treat Clark","avatar":""},{"name":"Charlayne Woodard","avatar":""},{"name":"Eamonn Walker","avatar":""},{"name":"Leslie Stefanson","avatar":""},{"name":"Johnny Hiram Jamison","avatar":""},{"name":"Michaelia Carroll","avatar":""},{"name":"Bostin Christopher","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324535);
