INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-minh-tren-hoang-dao', 'Một Mình Trên Hoang Đảo', 'Cast Away', 'https://phimimg.com/upload/vod/20231015-1/fa62c3d1d409ac311175b8aa2fb5b065.jpg', 'https://phimimg.com/upload/vod/20231015-1/b198b56674b638836631a205997a81ca.jpg', '<p>Chunk Noland là một kỹ sư của công ty giao nhận Fedex. Trong một chuyến công tác, máy bay của anh, do thời tiết xấu, đã đâm xuống biển Thái Bình Dương. Anh bị trôi dạt vào một hoang đảo, và tại đó, anh phải đấu tranh để tồn tại và tìm cách trở về gặp lại người yêu... Cả bộ phim là một cuộc phiêu lưu đầy cam go và sóng gió nhưng cũng rất cảm động và ẩn chứa nhiều bài học sâu sắc.</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Helen Hunt","avatar":""},{"name":"Chris Noth","avatar":""},{"name":"Paul Sanchez","avatar":""},{"name":"Lari White","avatar":""},{"name":"Leonid Citer","avatar":""},{"name":"David Allen Brooks","avatar":""},{"name":"Semion Sudarikov","avatar":""},{"name":"Peter Von Berg","avatar":""},{"name":"Dmitri S. Boudrine","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324535);
