INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-trom-nu-trang', 'Tên Trộm Nữ Trang', 'Snatch', 'https://phimimg.com/upload/vod/20231015-1/fc0098790659c35b31e1cc498d601138.jpg', 'https://phimimg.com/upload/vod/20231015-1/78b2f73a9a48d7de8e1e00ebc5655adb.jpg', '<p>Snatch mang phong thái giống như Pulp Fiction (1994) của Quentin Tarantino. Phim xoay quanh những câu chuyện, những hành động, những toan tính, âm mưu của hai nhóm tội phạm. Tất cả đều rất bình thường, xảy ra trong đời sống hàng ngày, không có gì to tát, ẩn ý hay có tính tuyên ngôn này kia. Cái khác của Guy Ritchie trong Snatch là những tình huống hài nhẹ, tự nhiên nảy sinh ở từng hành động của các nhân vật. Điều này khiến cho Snatch giảm bớt được sự căng thẳng và tạo được thêm sự thích thú ở khán giả so với Pulp Fiction (1994). Một bộ phim về tội phạm với phong cách tưng tửng, hài hước, không có cốt truyện nhưng lại rất hấp dẫn. Trang đánh giá phim trực tuyến IMDb đã xếp hạng Snatch đứng thứ 103 trong Top 250.</p>', 'Full', 1, 'single', 'completed', 20, 2000, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jason Statham","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Dennis Farina","avatar":""},{"name":"Alan Ford","avatar":""},{"name":"Benicio del Toro","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Robbie Gee","avatar":""},{"name":"Lennie James","avatar":""},{"name":"Rade Šerbedžija","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324535);
