INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('romeo-phai-chet', 'Romeo Phải Chết', 'Romeo Must Die', 'https://phimimg.com/upload/vod/20231015-1/bd2041dfaf62be65187e36db67301544.jpg', 'https://phimimg.com/upload/vod/20231015-1/dc5dd5bf4814ae2924704b203de1f06b.jpg', '<p>Han Sing, một cựu cảnh sát Hong Kong đang phải ngồi tù, vượt ngục và sang Mĩ sau khi nghe tin về cái chết của em trai, một thành viên cao cấp trong một băng đảng người Hoa do chính cha của Han Sing đứng đầu.Tại Mĩ, Han Sing phát hiện ra băng nhóm của cha mình đang có một cuộc cạnh tranh khốc liệt với một băng nhóm Mĩ gốc Phi do Isaak O’Day cầm đầu.Cuộc điều tra hung thủ sát hại em trai của Han Sing thêm phần phức tạp khi anh tình cờ quen biết và có cảm tình với Trish, con gái của Isaak.Với sự giúp đỡ của Trish, mọi chuyện dần dần sáng tỏ. Nhưng những điều phát hiện được vượt quá sự tưởng tượng của Han Sing.</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jet Li","avatar":""},{"name":"Aaliyah","avatar":""},{"name":"Isaiah Washington","avatar":""},{"name":"Russell Wong","avatar":""},{"name":"DMX","avatar":""},{"name":"Delroy Lindo","avatar":""},{"name":"D.B. Woodside","avatar":""},{"name":"Jon Kit Lee","avatar":""},{"name":"Edoardo Ballerini","avatar":""},{"name":"Anthony Anderson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324535);
