INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-mat-tri-nho', 'Kẻ Mất Trí Nhớ', 'Memento', 'https://phimimg.com/upload/vod/20231015-1/19e21a0086c0409d68781687666fdff2.jpg', 'https://phimimg.com/upload/vod/20231015-1/e930b82184c7f06e7342d35f7d10bbc9.jpg', '<p>Memento là câu chuyện xoay quanh Leonard Shelby, một người mắc chứng trí nhớ ngắn hạn truy tìm kẻ đã hãm hiếp và giết chết vợ anh. Leonard chỉ có thể nhớ những chuyện xảy ra trước vụ án mạng còn từ sau đó thì anh không thể nhớ điều gì quá 10 phút nên anh luôn phải ghi chép, chụp ảnh và thậm chí xăm mình để ghi nhớ mọi việc. Phim được chia làm 2 mảng truyện đan xen nhau và cứ thế, bức màn bí mật dần dần được hé lộ qua từng thước phim...</p>', 'Full', 1, 'single', 'completed', 18, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Guy Pearce","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Mark Boone Junior","avatar":""},{"name":"Russ Fega","avatar":""},{"name":"Jorja Fox","avatar":""},{"name":"Stephen Tobolowsky","avatar":""},{"name":"Harriet Sansom Harris","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Callum Keith Rennie","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324535);
