INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-doi-ga-bay', 'Phi Đội Gà Bay', 'Chicken Run', 'https://phimimg.com/upload/vod/20231015-1/4b83283f461350b3bcb7b0a04f91d54b.jpg', 'https://phimimg.com/upload/vod/20231015-1/fc460cdad3915e51b0a83fb439881dfb.jpg', '<p>Kể về một câu truyện hài hước về một đàn gà tìm cách trốn thoát khỏi trang trại chăn nuôi do ông Tweedy và bà vợ độc đoán của ông ta trông coi, trước khi họ biến những con gà này thành nhân bánh bao.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 2000, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Julia Sawalha","avatar":""},{"name":"Mel Gibson","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Jane Horrocks","avatar":""},{"name":"Lynn Ferguson","avatar":""},{"name":"Miranda Richardson","avatar":""},{"name":"Tony Haygarth","avatar":""},{"name":"Benjamin Whitrow","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Phil Daniels","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324535);
