INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-sat-nhan-cuong-tin', 'Kẻ Sát Nhân Cuồng Tín', 'American Psycho', 'https://phimimg.com/upload/vod/20231014-1/446678d4d0b307aabc430c67a5adf4a7.jpg', 'https://phimimg.com/upload/vod/20231014-1/7f8c091630b364a0f53eeceed682edd4.jpg', '<p>Dựa vào cuốn tiểu thuyết của Bret Easton Ellis, American Psycho kể về tên tâm thần giết người hàng loạt Patrick Bateman (Christian Bale). Ở tuổi 27, trong mắt mọi người Patrick là một nhân viên hội đủ những tố chất mà mọi người ao ước: đẹp trai, lịch lãm, có trí thức và gia thế vững chãi. Nhưng có lẽ chính vì vậy mà ông trời phải tạo ra một khuyết điểm nơi Patrick để bù đắp những gì mà gã có. Đó chính là lòng đố kỵ, một khuyết điểm đôi khi trở thành một mối nguy hiểm khôn lường.</p>', 'Full', 1, 'single', 'completed', 22, 2000, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Christian Bale","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Josh Lucas","avatar":""},{"name":"Samantha Mathis","avatar":""},{"name":"Matt Ross","avatar":""},{"name":"Bill Sage","avatar":""},{"name":"Chloë Sevigny","avatar":""},{"name":"Cara Seymour","avatar":""},{"name":"Justin Theroux","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324535);
