INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-giac-dau', 'Võ Sĩ Giác Đấu', 'Gladiator', 'https://phimimg.com/upload/vod/20231014-1/64d398a360904eaf83a9a5b98e599849.jpg', 'https://phimimg.com/upload/vod/20231014-1/b0d4f8f3e7c9a85e80dfcd8a9a9a379c.jpg', '<p>Hoàng đế Marcus quyết định chọn vị tướng tin cẩn là Maximus làm người kế vị ngai vàng. Ðiều đó làm Commodus, con trai Marcus, nổi giận. Hắn đã giết cha để chiếm ngôi rồi hãm hại gia đình Maximus. Bản thân Maximus bị trở thành nô lệ, phải tham gia vào các cuộc thi giác đấu... Cuối cùng Maximus cũng về đến Rome và trả thù cho gia đình... Cuộc đời Maximus thay đổi từ ấy, từ một vị tướng oai dũng trở thành một kẻ nô lệ phải trải qua bao thử thách...</p>', 'Full', 1, 'single', 'completed', 23, 2000, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Joaquin Phoenix","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"Oliver Reed","avatar":""},{"name":"Richard Harris","avatar":""},{"name":"Derek Jacobi","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"David Schofield","avatar":""},{"name":"John Shrapnel","avatar":""},{"name":"Tomas Arana","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324535);
