INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('grinch-da-danh-cap-giang-sinh-nhu-the-nao', 'Grinch Đã Đánh Cắp Giáng Sinh Như Thế Nào', 'How the Grinch Stole Christmas', 'https://phimimg.com/upload/vod/20231014-1/e97547b1cd8e228966ecd79427fe8840.jpg', 'https://phimimg.com/upload/vod/20231014-1/1ba94ea91bc9f5b87c454c3f41aa53aa.jpg', '<p>Chuyện xảy ra ở thị trấn Whoville, cậu bé Grinch bất hạnh sinh ra đã có một diện mạo kỳ dị không như những đứa trẻ khác. Trên người cậu bao phủ một lớp lông lá như một con quái vật.Mọi người tránh xa, bạn bè hắt hủi, trêu chọc cậu. Tức giận, Grinch quyết định trộm hết những món quà giáng sinh của các bạn. Nhưng điều đó không làm câu thoải mái hơn, ngược lại, Grinch càng thấy mình cô độc. Chính lúc ấy, Cindy – cô bé duy nhất quan tâm đến Grinch đã giúp cậu nhận ra ý nghĩa đích thực của cuộc sống và hòa nhập với cộng đồng.&nbsp; Kẻ Đánh Cắp Giáng Sinh</p>', 'Full', 1, 'single', 'completed', 22, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Taylor Momsen","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Christine Baranski","avatar":""},{"name":"Bill Irwin","avatar":""},{"name":"Molly Shannon","avatar":""},{"name":"Clint Howard","avatar":""},{"name":"Josh Ryan Evans","avatar":""},{"name":"Mindy Sterling","avatar":""},{"name":"Bryce Dallas Howard","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324535);
