INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-de-lac-da', 'Hoàng Đế Lạc Đà', 'The Emperor''s New Groove', 'https://phimimg.com/upload/vod/20231014-1/63a7433d8a74e728f1ad874c61ac5522.jpg', 'https://phimimg.com/upload/vod/20231014-1/0d0b7970e6c4c4243aa3792dd76064f4.jpg', '<p>Hoàng Đế Kuzco, trẻ tuổi, kinh nghiệm sống ít ỏi nhưng bản tính hiếu thắng, ngạo mạn ích kỷ, ham chơi nên không được lòng thần dân. Hoàng Đế muốn xây 1 bể bơi mùa hè ở trên 1 chóp đồi xinh đẹp để làm quà sinh nhật 18 tuổi cho mình. Nhưng vấp phải sự phản đối dữ dội của bác trưởng làng Pacha và âm mưu giết người cướp ngai vàng mụ phù thủy độc ác Yzma. Hoàng Đế sẽ phải làm gì để chống lại&nbsp;</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Spade","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Eartha Kitt","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Wendie Malick","avatar":""},{"name":"Kellyann Kelso","avatar":""},{"name":"Eli Russell Linnetz","avatar":""},{"name":"Stephen J. Anderson","avatar":""},{"name":"Bob Bergen","avatar":""},{"name":"Rodger Bumpass","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324535);
