INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-cong-bad-boy', 'Đặc Công Bad Boy', 'For Bad Boys Only', 'https://phimimg.com/upload/vod/20231012-1/9741fff2640aa8155d9b83a89390002e.jpg', 'https://phimimg.com/upload/vod/20231012-1/07af27604dbef4ed72b1ade74c695779.jpg', '<p>Biệt đội Bad Boy, một loạt các công ty thám tử tư, bao gồm King (Ekin Cheng Yi-kin), Queen (Kristy Yeung) và Jack (Louis Koo Tin-lok), người có nguồn kinh doanh chính là đoàn tụ các khách hàng. với ngọn lửa đầu tiên của họ, và khi bộ ba đặc vụ trẻ trở về Hồng Kông sau nhiệm vụ ở Thái Lan và ba khách hàng tiếp theo của Biệt đội cung cấp những bức ảnh về tình yêu đã mất, những người phụ nữ trong ảnh dường như là cùng một cá nhân.</p>', 'Full', 1, 'single', 'completed', 17, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ekin Cheng","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Kristy Yang","avatar":""},{"name":"Daniel Chan Hiu-Tung","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Jerry Lamb Hiu-Fung","avatar":""},{"name":"Kelly Lin","avatar":""},{"name":"Josie Ho","avatar":""},{"name":"Blackie Ko Shou-Liang","avatar":""}]', '[]', '[]', 1784690324535);
