INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dac-cong-bad-boy', 'Đặc Công Bad Boy', 'For Bad Boys Only', 'đặc công bad boy for bad boys only ekin cheng louis koo shu qi kristy yang daniel chan hiu-tung mark cheng ho-nam jerry lamb hiu-fung kelly lin josie ho blackie ko shou-liang ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-co-em-khong-co-anh', 'Không Có Em Không Có Anh', 'Eternal Love', 'null', 'https://phimimg.com/upload/vod/20231011-1/8e6aa8969d1d96bdef5a5c18dc415481.webp', '<p>Alex, người từng là một nhà soạn nhạc nổi tiếng, không muốn chạy theo đám đông, và các tác phẩm của ông dần dần không được ưa chuộng. Chán nản, anh gặp Ivy, một cô hầu bàn trong quán bar, Alex khuyên cô gia nhập công ty thu âm, Ivy ngay lập tức trở thành hit nhưng cả hai đã chia tay do khoảng cách ngày càng lớn. Alex vô tình gặp nhạc sĩ Martin ở Đài Loan và phát hiện ra rằng anh đang yêu ca sĩ chính Ling, Alex bối rối, Martin dùng trà đạo như một phép ẩn dụ cho tình yêu, và Alex chợt hiểu ra.</p>', 'Full', 1, 'single', 'completed', 15, 2000, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Alex Fong","avatar":""},{"name":"Yoyo Mung","avatar":""},{"name":"Helena Law Lan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
