INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-co-em-khong-co-anh', 'Không Có Em Không Có Anh', 'Eternal Love', 'không có em không có anh eternal love alex fong yoyo mung helena law lan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-giang-ho', 'Luật Giang Hồ', 'The Blood Rules', 'https://phimimg.com/upload/vod/20231010-1/2072e6d406c37195cff5242afec38ff9.jpg', 'https://phimimg.com/upload/vod/20231010-1/31ffebd9157379f6740fb957e8dc8dde.jpg', '<p>Mike, Jean, Shoot và Q là một băng nhóm cướp chuyên nghiệp làm việc cho chú Lâm. Q yêu bạn gái Bo, yêu đàn ông quyết đoán và cuộc sống xa hoa. Shoot yêu thích những loài cá kỳ lạ và Jean. Jean yêu Mike nhưng anh đã kết hôn với người phụ nữ khác và có một cậu con trai nhỏ. Bác Lâm thích ăn ngon và có nhiều tiền. Sau khi hoàn thành xuất sắc công việc gần đây nhất cho chú Lam, Mike và nhóm của anh muốn được nghỉ ngơi. Bác Lâm nhất quyết yêu cầu họ phải đảm nhận thêm một công việc nữa, đó là cướp tên trùm hội Tam Hoàng Gà Sam mê kim cương theo đúng nghĩa đen của từ này. Vụ cướp không diễn ra quá suôn sẻ; hơn nữa, Tom Wai, một sĩ quan cảnh sát yêu nghề, ngày càng thân thiết hơn…</p>', 'Full', 1, 'single', 'completed', 21, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Michael Wong","avatar":""},{"name":"Suki Kwan","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Wong Tin-lam","avatar":""},{"name":"Stephen Au","avatar":""},{"name":"Crystal Tin Yue-Lai","avatar":""},{"name":"Wai Lit","avatar":""},{"name":"Philip Keung Hiu-Man","avatar":""},{"name":"Yang Hsiung","avatar":""},{"name":"Pauline Yam","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324535);
