INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-nha-nghi', 'Sát Nhân Nhà Nghỉ', 'Resort Massacre', 'null', 'https://phimimg.com/upload/vod/20231010-1/93802a40916b18b865db3723ee6d4787.jpg', '<p>Joey bị thiểu năng trí tuệ hiện đã hơn ba mươi và đang điều hành nhà trọ Sunshine Resorts cùng với mẹ già, bà Lim. Anh ta bị tổn thương thị lực khi còn nhỏ nhìn chằm chằm vào nhật thực ở Cheung Chau; nhưng anh thích nghe, ghi lại cảnh bác Hội bạo lực làm tình. Những người phụ nữ đã mất tích sau khi thuê phòng 13 tại nhà trọ, được cho là do tự sát. Nhưng Joey biết rõ hơn. Mayse, một nhà báo thất nghiệp tại một tạp chí rác rưởi, được lệnh điều tra nhưng lại cử Julie thay thế cô. Khi không thể liên lạc được với Julie trong hai ngày, Mayse tự mình đến Cheung Chau để giải đáp bí ẩn…</p>', 'Full', 1, 'single', 'completed', 21, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sophie Ngan","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"William Ho Ka-Kui","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Cherry Chan Chiu-Chiu","avatar":""},{"name":"Shelley Cheung Siu-Wai","avatar":""},{"name":"Samuel Leung Cheuk-Moon","avatar":""},{"name":"Lee Siu-Kei","avatar":""},{"name":"Shirley Hung Suet-Ying","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324535);
