INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duyen-tinh-okinawa', 'Duyên Tình Okinawa', 'Okinawa Rendezvous', 'https://phimimg.com/upload/vod/20231009-1/109044cbd78c4de25a1c23cb2fd3483d.jpg', 'https://phimimg.com/upload/vod/20231009-1/256d7df30ab579148e08e47965c30f3e.jpg', '<p>Jimmy Tong là một chuyên gia tống tiền và trộm cắp chuyên về tội phạm cổ trắng. Với cú đá phụ của mình, Jimmy đánh cắp cuốn nhật ký cá nhân của thủ lĩnh Yakuza Ken Sato với ý định sử dụng thông tin chi tiết của nó làm nền tảng để tống tiền và tống tiền. Sato đồng ý với thỏa thuận không mấy dễ dàng và chuẩn bị trả cho Jimmy những yêu cầu cắt cổ của anh ta chỉ để Jenny, bạn gái của Sato phản bội anh ta và kiếm tiền đến Okinawa.</p>', 'Full', 1, 'single', 'completed', 23, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Leslie Cheung","avatar":""},{"name":"Faye Wong","avatar":""},{"name":"Stephanie Che","avatar":""},{"name":"Vincent Kok","avatar":""},{"name":"Gigi Lai","avatar":""},{"name":"Asuka Higuchi","avatar":""},{"name":"Masaya Kato","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324535);
