INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-tu-quyen-toc', 'Sinh Tử Quyền Tốc', 'Fist Power', 'https://phimimg.com/upload/vod/20231008-1/304d08cd4c1a0303ab4699ca64e093f9.jpg', 'https://phimimg.com/upload/vod/20231008-1/deb3a3017ac422d4aadf4d550f2d7012.jpg', '<p>Trác là một nhân viên an ninh Đại Lục vô tình dính vào cuộc đua chống lại khủng bố khi anh ta phát hiện một người đàn ông đang giữ một trường học làm con tin để trao đổi với con trai nuôi của mình. Trác quyết định sử dụng võ nghệ và các kỹ năng kinh nghiệm thực chiến của mình để cứu cậu bé và hóa giải nguy hiểm trước khi hắn quyết định giết tất cả mọi người.</p>', 'Full', 1, 'single', 'completed', 21, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Vincent Zhao","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Gigi Lai","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Lung Fong","avatar":""},{"name":"Kara Hui Ying-Hung","avatar":""},{"name":"Lau Kar-Wing","avatar":""},{"name":"Cheng Pei-pei","avatar":""},{"name":"Robert Mak","avatar":""},{"name":"Lam Suet","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324535);
