INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-sat-lenh', 'Giang Hồ Sát Lệnh', 'Jiang Hu: The Triad Zone', 'https://phimimg.com/upload/vod/20231006-1/41005c153ccadaf01ed6d5fd59af8357.jpg', 'https://phimimg.com/upload/vod/20231006-1/07f062c4d915a36341fec4f066a60f97.jpg', '<p>Thủ lĩnh băng đảng Jim Yam đã gần đạt đến đỉnh cao quyền lực trong thế giới ngầm, nhưng điều đó mang lại cho anh ta rất ít sự thỏa mãn. Khi chứng kiến những người đồng nghiệp của mình chết xung quanh mình - nhiều người trong số họ đáng kinh ngạc là do nguyên nhân tự nhiên - anh thấy mình ngày càng trở nên kiên cường hơn vì đó chính là điều mà các ông chủ thường làm. Hồi tưởng lại những ngày còn trẻ ở London, thật buồn khi phải đối chiếu cuộc sống xa hoa - nhưng trống rỗng - hiện tại của anh với tư cách là một trùm tội phạm ở Hồng Kông với những niềm vui mà anh trải qua khi còn là một tên trộm vặt ở Anh. Những đoạn hồi tưởng và thuyết minh này cung cấp cho chúng ta cái nhìn sâu sắc không chỉ về bản thân Yam mà còn cả những cộng sự thân cận nhất của anh ấy, những người mà chúng tôi phát hiện ra rằng sự thật thì anh ấy hầu như không biết.</p>', 'Full', 1, 'single', 'completed', 22, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Sandra Ng Kwun-Yu","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Carl Ng","avatar":""},{"name":"Eason Chan","avatar":""},{"name":"Samuel Pang","avatar":""},{"name":"Jo Kuk Cho-Lam","avatar":""},{"name":"Lee San-San","avatar":""},{"name":"Chan Fai-hung","avatar":""},{"name":"Eric Tsang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":