INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-troi-co-mat', 'Ông Trời Có Mắt', 'Comeuppance', 'https://phimimg.com/upload/vod/20231006-1/e371eb29fb6e980519cb105b189031fb.jpg', 'https://phimimg.com/upload/vod/20231006-1/e2993ffa11f24d730129cb483da1659d.jpg', '<p>Song Ping là một người tốt bụng. Sau khi trải qua cảm giác giết người do nhầm lẫn, anh ta đã đầu độc kẻ ác Wang Jinxiong vì lợi ích của người dân. Vụ việc thu hút sự chú ý của băng đảng và cảnh sát. Nhiệm vụ của Song Ping là tiếp tục lên kế hoạch cho một hành động khác và hành động của anh được phóng viên Jian chọn làm chủ đề của cuốn tiểu thuyết. Song Ping là độc giả của anh và hai người dần dần biến cuốn tiểu thuyết thành nơi nghiên cứu về tội giết người. Cuối cùng, cảnh sát sẽ tìm ra manh mối vụ giết người trong tiểu thuyết của Jian.<br/></p>', 'Full', 1, 'single', 'completed', 21, 2000, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jordan Chan","avatar":""},{"name":"Patrick Tam","avatar":""},{"name":"Sunny Chan","avatar":""},{"name":"Wu Hsing-Guo","avatar":""},{"name":"Joe Lee Yiu-Ming","avatar":""},{"name":"Crystal Lui Kwok-Wai","avatar":""},{"name":"Benny Li Shun-Yan","avatar":""},{"name":"Jeff Kam Chun-Man","avatar":""},{"name":"Luk Man-Wai","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324535);
