INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-bien', 'Vùng Biển', 'The Beach', 'https://phimimg.com/upload/vod/20230912-1/6f9fbe9d68105fee0d38220a49b10d78.jpg', 'https://phimimg.com/upload/vod/20230912-1/c5dca355bff625c3271bc768211f9bcb.jpg', '<p>Richard ở tuổi 20 tới Thái Lan và phát hiện ra mình đang sở hữu một tấm bản đồ kỳ lạ. Tin đồn nói rằng nó dẫn đến một thiên đường bãi biển đơn độc, một niềm hạnh phúc nhiệt đới - đầy phấn khích và hấp dẫn, anh lên đường tìm kiếm nó.</p>', 'Full', 1, 'single', 'completed', 32, 2000, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Virginie Ledoyen","avatar":""},{"name":"Guillaume Canet","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Staffan Kihlbom","avatar":""},{"name":"Paterson Joseph","avatar":""},{"name":"Peter Youngblood Hills","avatar":""},{"name":"Robert Carlyle","avatar":""},{"name":"Jerry Swindall","avatar":""},{"name":"Lars Arentz-Hansen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
