INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-hai-kich', 'Vua Hài Kịch', 'King Of Comedy', 'https://phimimg.com/uploads/movies/20260713/vua-hai-kich-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/vua-hai-kich-poster.webp', '<p>Vua Hài Kịch là một tác phẩm xuất sắc trong sự nghiệp của Châu Tinh Trì kể về Doãn Thiên Sầu là một diễn viên ham mê điện ảnh nhưng phải sống bằng nghề trông coi một nhà văn hóa và xin vào đóng những vai quần chúng cho các bộ phim của ngôi sao Đỗ Huệ Nghi. Mặc dù gây ra nhiều rắc rối ở trường quay, Doãn Thiên Sầu đã được Đỗ Huệ Nghi để ý vì sự ham mê điện ảnh của anh, cô quyết định mời Doãn tham gia bộ phim mới của cô trong vai nam chính. Tuy nhiên sau đó Doãn Thiên Sầu đã bị tước vai này để giao lại cho một ngôi sao điện ảnh khác.</p>', 'Full', 1, 'single', 'completed', 39, 1999, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Cecilia Cheung","avatar":""},{"name":"Karen Mok Man-Wai","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Jazz Lam Tsz-Sin","avatar":""},{"name":"Tenky Tin Kai-Man","avatar":""},{"name":"Lee Siu-Kay","avatar":""},{"name":"Jackie Chan","avatar":""},{"name":"Cheng Man-Fai","avatar":""},{"name":"Steven Fung Min-Hang","avatar":""},{"name":"Bobby Yip Kin-Sang","avatar":""},{"name":"Johnson Lee Sze-Chit","avatar":""},{"name":"Joe Cheng Cho","avatar":""},{"name":"Dai Lung","avatar":""},{"name":"Ben Yuen Foo-Wah","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Hei K