INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-dau-sinh-tu', 'Sàn Đấu Sinh Tử', 'Fight Club', 'https://phimimg.com/upload/vod/20260617-1/ba02b23a0f45f219f2f480f1e1ed82f1.jpg', 'https://phimimg.com/upload/vod/20260617-1/5e057a76968b2c2e4c4fe8c1677afbc0.jpg', '<p>Cuộc gặp gỡ định mệnh của một nhân viên giám định bảo hiểm và một gã lông bông bán xà phòng trên chuyến bay đã mở ra một cuộc phiêu lưu kỳ lạ. Với các &quot;câu lạc bộ chiến đấu&quot; ngầm hình thành ở mọi thị trấn, cuốn theo nhiều diễn biến phức tạp và một cái kết đầy kịch tính.</p>', 'Full', 1, 'single', 'completed', 34, 1999, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Edward Norton","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Meat Loaf","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Zach Grenier","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Eion Bailey","avatar":""},{"name":"Richmond Arquette","avatar":""},{"name":"David Andrews","avatar":""},{"name":"George Maguire","avatar":""},{"name":"Eugenie Bondurant","avatar":""},{"name":"Christina Cabot","avatar":""},{"name":"Sydney ''Big Dawg'' Colston","avatar":""},{"name":"Rachel Singer","avatar":""},{"name":"Chr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mo''adon Krav","Borilački klub","Boytsovskiy klub","Boen klub","Biytsivsʹkyy klub","Байцоўскі клюб","Döyüş Klubu","მალჷმორეფიშ კლუბი","Մարտական ակումբ","النادي د لمدابزة","نادى القتال","Мушташ клубу","فایت کلاب","फाइट क्लब","ਫ਼ਾਈਟ ਕਲੱਬ","搏击会","鬥陣俱樂部","Մարտ Ակումբ","Fight Club"]', 1784690324535);
