INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-himitsu', 'Bí Mật (Himitsu)', 'Secret', 'https://phimimg.com/upload/vod/20260321-1/415ca08abebcd795e56bdc73651a709d.jpg', 'https://phimimg.com/upload/vod/20260321-1/398caf6c81e6a09e2ddef4c9c699da68.jpg', '<p>Bộ phim được chuyển thể từ tiểu thuyết của nhà văn Higashino Keigo. Vợ con của Heisuke Sugita đang trên đường về quê ăn dỗ thì gặp tai nạn xe buýt và rơi vào hôn mê. Ngay sau đó người vợ qua đời và khi con gái là Monami tỉnh dậy, cô lại khẳng định với Heisuke rằng mình chính là Naoko, vợ anh.</p>', 'Full', 1, 'single', 'completed', 24, 1999, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hirosue Ryoko","avatar":""},{"name":"Kaoru Kobayashi","avatar":""},{"name":"Ken Kaneko","avatar":""},{"name":"Yuriko Ishida","avatar":""},{"name":"Hideaki Ito","avatar":""},{"name":"Tomoe Shinohara","avatar":""},{"name":"Kayoko Kishimoto","avatar":""},{"name":"Rie Shibata","avatar":""},{"name":"Ren Osugi","avatar":""},{"name":"Hatsuo Yamaya","avatar":""},{"name":"Yoshiko Inoue","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Himitsu","Secret","비밀","秘密"]', 1784690324535);
