INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-an-phu-thuy-rung-blair', 'Dự Án Phù Thủy Rừng Blair', 'The Blair Witch Project', 'https://phimimg.com/upload/vod/20260227-1/ab147985b2f51b3929a0423d55fa24a7.jpg', 'https://phimimg.com/upload/vod/20260227-1/6529033670bba3b994d213603bbac21f.jpg', '<p>Ba sinh viên làm phim tài liệu cùng nhau vào rừng để quay một bộ phim về một phù thủy huyền thoại được cho là thủ phạm của hàng loạt vụ giết người trong suốt 200 năm qua.</p>', 'Full', 1, 'single', 'completed', 22, 1999, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Heather Donahue","avatar":""},{"name":"Joshua Leonard","avatar":""},{"name":"Michael C. Williams","avatar":""},{"name":"Bob Griffin","avatar":""},{"name":"Jim King","avatar":""},{"name":"Sandra Sánchez","avatar":""},{"name":"Ed Swanson","avatar":""},{"name":"Patricia DeCou","avatar":""},{"name":"Mark Mason","avatar":""},{"name":"Susie Gooch","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["El proyecto Blair Witch","Veštica iz Blera","El Proyecto de la Bruja de Blair","Proklyatieto Bleŭr","To Prógramma Mágissas Bler","Ved''ma iz Bler: Kursovaya s togo sveta","Vidʹma z Bler: Kursova z toho svitu","Blair Witch Project","ブレア・ウィッチ・プロジェクト","Пројекат: Вештица из Блера","Le Projet Blair Witch","Le Projet Blair","Проклятието Блеър","Вештерката од Блер","Ведьма из Блэр: Курсовая с того света","Відьма з Блер: Курсова з того світу","El projecte de la bruixa de Blair","Al mistēr dla stria ad Blair","The Blair Witch Project - Il mistero della s