INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('du-an-phu-thuy-rung-blair', 'Dự Án Phù Thủy Rừng Blair', 'The Blair Witch Project', 'dự án phù thủy rừng blair the blair witch project heather donahue joshua leonard michael c. williams bob griffin jim king sandra sánchez ed swanson patricia decou mark mason susie gooch el proyecto blair witch veštica iz blera el proyecto de la bruja de blair proklyatieto bleŭr to prógramma mágissas bler ved''ma iz bler: kursovaya s togo sveta vidʹma z bler: kursova z toho svitu blair witch project ブレア・ウィッチ・プロジェクト пројекат: вештица из блера le projet blair witch le projet blair проклятието блеър вештерката од блер ведьма из блэр: курсовая с того света відьма з блер: курсова з того світу el projecte de la bruixa de blair al mistēr dla stria ad blair the blair witch project - il mistero della strega di blair blēras ragana: kursa darbs no viņpasaules projektas: bleiro ragana ideglelés a bruxa de blair o projeto blair witch proiect: vrăjitoarea čarovnica iz blaira blair cadısı záhada blair witch مشروع الساحرة بلير پروژه جادوگر بلر مشروع الساحره بلير פרויקט המכשפה מבלייר 블레어 위치 블레어 윗치의 저주 dự án phù thủy rừng blair สอดรู้ สอดเห็น สอดเป็น สอดตาย 女巫布莱尔 厄夜叢林 projekt: vještica iz blaira ალქაჯი ბლერიდან вештица из блера the blair witch project', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-chau-cach-cach-phan-2', 'Hoàn Châu Cách Cách (Phần 2)', 'My Fair Princess (Season 2)', 'https://phimimg.com/upload/vod/20260224-1/14d8aaa322ed1a3721286fc1ea0f199b.jpg', 'https://phimimg.com/upload/vod/20260224-1/47c65a307062f7e0ab328a8de154e73e.jpg', '<p>Chuyển thể từ tiểu thuyết cùng tên của nữ tác giả Quỳnh Dao. Cả bộ phim có 3 phần, sản xuất trong khoảng các năm 1997, 1998 và 2003. Hầu hết các cảnh trong phim đều được thực hiện ở thủ đô Bắc Kinh và tỉnh Hà Bắc của Trung Quốc Đại lục.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 36, 1999, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Triệu Vy","avatar":""},{"name":"Lâm Tâm Như","avatar":""},{"name":"Tô Hữu Bằng","avatar":""},{"name":"Châu Kiệt","avatar":""},{"name":"Phạm Băng Băng","avatar":""},{"name":"Trương Thiết Lâm","avatar":""},{"name":"Đới Xuân Vinh","avatar":""},{"name":"Lý Minh Khải","avatar":""},{"name":"Vương Diễm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["还珠格格","還珠格格","Putri Huan Zhu","還珠姫 〜プリンセスのつくりかた〜　(Kanju Hime ~Purinsesu no Tsukuri Kata~)","ព្រះនាងយេយេ (Preah Neang Ye Ye)","황제의 딸 (Hwangje-ui Ttal; \"Emperor''s Daughter\")","Хуанжу Гэг (Khuanju Geg)","還珠格格 (Waan Jyu Ge Ge )","My Fair Princess","还珠格格 (Huan Zhu Ge Ge)","องค์หญิงกำมะลอ (Xngkh̒ h̄ỵing kảmalx)","還珠格格 (Huan Zhu Ge Ge)","Huanzhu Gege","Princess Pearl","Princess Returning Pearl","Return of the Pearl P