INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('stargate-sg1-phan-3', 'Stargate SG-1 (Phần 3)', 'Stargate SG-1 (Season 3)', 'stargate sg-1 (phần 3) stargate sg-1 (season 3) ben browder amanda tapping christopher judge michael shanks claudia black beau bridges star gate sg-1 старгейт la porte des étoiles 星际之门：sg-1 hvězdná brána hvězdná  brána sg1 stargate - kommando sg-1 stargate: sg-1 stargate sg1 : la porte des étoiles stargate sg-1 סטארגייט ס"ג-1 スターゲイト sg-1 스타게이트 sg-1 звездные врата: зв-1 stargate', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-ti-hon', 'Thợ Săn Tí Hon', 'Hunter X Hunter', 'https://phimimg.com/upload/vod/20240118-1/a22867b68b2f0da20513dddd511c61b3.jpg', 'https://phimimg.com/upload/vod/20240118-1/90a9ac11c3f3f63fecc4fcf380950da1.jpg', '<p>Nhân vật chính Gon·Freecss lớn lên trên đảo Cá Voi, cùng dì Mito và bà cố nương tựa vào nhau. Đứa tính tình cởi mở, có tài giao tiếp với động vật. Gon coi dì Mito là mẹ đẻ của mình bởi đứa mồ côi cả cha lẫn mẹ. Đến lúc 9 tuổi, Gon được một người thanh niên cứu giúp, mới được biết cha mình vẫn còn sống trên đời và ông là thợ săn(Hunter). Bởi vậy, Gon quyết chí trở thành thợ săn, bắt đầu tìm dấu vết người cha từ nơi đấy. Gon liền lên đường tìm cha một mình sau thuyết phục dì Mito. Nhờ vào niềm tin vậy, Gon bắt đầu cuộc phiêu lưu của mình, đứa không những kết được hai người bạn trên đường đi, mà còn không ngừng trưởng thành, gây ra nhiều câu chuyện sau trong thế giới tuyệt vời của thợ săn!</p>', 'Hoàn Tất (148/148)', 148, 'hoathinh', 'completed', 22, 1999, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324535);
