INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-ay-la-vay', 'Cô Ấy Là Vậy', 'She''s All That', 'cô ấy là vậy she''s all that freddie prinze jr. rachael leigh cook paul walker jodi lyn o''keefe kevin pollak anna paquin kieran culkin elden henson matthew lillard usher lil'' kim gabrielle union dulé hill tamara mello clea duvall tim matheson debbi morgan a ela é demais a csaj nem jár egyedül 窈窕美眉 elle a tout pour elle ella es asi ella es así she''s all that', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-nham-ho', 'Mắt Nhắm Hờ', 'Eyes Wide Shut', 'https://phimimg.com/upload/vod/20251114-1/9ed4a6195281c0d9ee33acec0a148c40.jpg', 'https://phimimg.com/upload/vod/20251114-1/7a0247254da8c1156a33c48b70c0eb11.jpg', '<p>Nội dung phim xoay quanh người chồng William sau khi nghe những câu chuyện tình dục mà cô ấy gặp trong giấc mơ, điều đó đã làm người chồng thôi thúc hơn bao giờ hết nên quyết định tham gia một chuyến đi thác loạn cùng bạn của mình nhưng đã thất bại. Sau nhiều lần không thành công anh vô tình gặp lại người bạn cũ của anh là Nick, một nhạc sĩ có tiếng, đã kể lại cho anh ta nghe về câu chuyện trong bữa tiệc tình dục mà Nick đã tham gia. Tại bữa tiệc đó, những người đàn ông sẽ được che mặt bởi một lớp mặt nạ và đến một căn biệt thự, tại đó họ sẽ gặp gỡ và làm tình với nhau. Tuy nhiên, không may cho William khi anh phát hiện rằng trong bữa tiệc đó lại có người nhận ra anh ta...</p>', 'Full', 1, 'single', 'completed', 22, 1999, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Sydney Pollack","avatar":""},{"name":"Marie Richardson","avatar":""},{"name":"Rade Šerbedžija","avatar":""},{"name":"Todd Field","avatar":""},{"name":"Vinessa Shaw","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Sky du Mont","avatar":""},{"name":"Fay Masterson","avatar":""},{"name":"Leelee Sobieski","avatar":""},{"name":"Thomas Gibson","avatar":""},{"name":"Madison Eginton","avatar":""},{"name":"Julienne Davis","avatar":""},{"name":"Jackie Sawiris","avatar":""},{"name":"Leslie Lowe","avatar":""},{"name":"Peter Hans Bens","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["De Olhos Bem Fechados","大開眼戒","Широко затворени очи","Ojos Bien Cerrados","Ojos bien cerrados","عيون مغلقة على اتساعها","아이즈 와이드 셧","С широко закрытыми глазами","Gözleri Tamamen Kapalı","Oči širom zatvorene","Spalující touha","Μάτια ερμητικά κλειστά","Tágra zárt szemek","アイズ ワイド シャット","Plačiai užmerktos akys","Oczy Szeroko Zamknięte","Cu ochii larg inchisi","Широм затворених очију","Široko zaprte oči","Gözü tamamen kapalı","Із широко заплющеними очима","Rhapsody","Traumnovelle","紧闭双眼","大开眼戒","大开眼界","Gözləri Sıxıca Qapalı","Լայն փակված աչքերով","Eyes Wide Shut"]', 1784690324535);
