INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-nham-ho', 'Mắt Nhắm Hờ', 'Eyes Wide Shut', 'mắt nhắm hờ eyes wide shut tom cruise nicole kidman sydney pollack marie richardson rade šerbedžija todd field vinessa shaw alan cumming sky du mont fay masterson leelee sobieski thomas gibson madison eginton julienne davis jackie sawiris leslie lowe peter hans bens de olhos bem fechados 大開眼戒 широко затворени очи ojos bien cerrados ojos bien cerrados عيون مغلقة على اتساعها 아이즈 와이드 셧 с широко закрытыми глазами gözleri tamamen kapalı oči širom zatvorene spalující touha μάτια ερμητικά κλειστά tágra zárt szemek アイズ ワイド シャット plačiai užmerktos akys oczy szeroko zamknięte cu ochii larg inchisi широм затворених очију široko zaprte oči gözü tamamen kapalı із широко заплющеними очима rhapsody traumnovelle 紧闭双眼 大开眼戒 大开眼界 gözləri sıxıca qapalı լայն փակված աչքերով eyes wide shut', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-uop-ai-cap', 'Xác Ướp Ai Cập', 'The Mummy', 'https://phimimg.com/upload/vod/20251020-1/5782a2d1ae18cc1852eb3b0e8b426534.jpg', 'https://phimimg.com/upload/vod/20251020-1/0d23270fce6eaf4c803bf61821de5b4c.jpg', '<p>Một nhóm nhà khảo cổ dẫn đầu là O’Connell tiến hành cuộc hành trình tới xứ sở của kim tự tháp. Họ có tham vọng khám phá bí mật của xác ướp thầy tu Imhotep, nhưng vô tình đem lại cơ hội hồi sinh cho hắn, khiến cuộc chiến sinh tồn nổ ra. &nbsp;Bộ ba Rick – Evelyn – Jonathan rời Cairo xuôi theo dòng dông Nile, ngang qua sa mạc Sahara và họ bắt đầu nhận ra sự khắc nghiệt của thiên nhiên không là gì so với những thế lượng đen tối họ phải đối đầu. Đó là những kẻ tham lam vô độ không ngại gì sự huyền bí của Ai Cập tới kiếm tìm châu báu và sự tấn công của xác ướp hồi sinh Imhotep cùng nhân tình của hắn Anck-su-namun vì để hồi sinh cho người tình, Imhotep cần máu và cơ thể của Evelyn. &nbsp;Mối nguy hiểm không chỉ đến với những kẻ săn kho báu và đoàn khảo cổ của Rick mà nó đã trở thành sự đe dọa cho toàn thế giới khi Imhotep âm mưu gây dựng lại đế chế độc tài Ai Cập cổ xưa bằng phép thuật của một thầy tu quyền năng.</p>', 'Full', 1, 'single', 'completed', 20, 1999, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brendan Fraser","avatar":""},{"name":"Rachel Weisz","avatar":""},{"name":"John Hannah","avatar":""},{"name":"Arnold Vosloo","avatar":""},{"name":"Patricia Velásquez","avatar":""},{"name":"Oded Fehr","avatar":""},{"name":"Kevin J. O''Connor","avatar":""},{"name":"Jonathan Hyde","avatar":""},{"name":"Erick Avari","avatar":""},{"name":"Stephen Dunham","avatar":""},{"name":"Corey Johnson","avatar":""},{"name":"Mohammed Afifi","avatar":""},{"name":"Tuc Watkins","avatar":""},{"name":"Omid Djalili","avatar":""},{"name":"Bernard Fox","avatar":""},{"name":"Aharon Ipalé","avatar":""},{"name":"Carl Chase","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La Mummia","미이라","木乃伊","盗墓迷城","Mummy","The Mummy (La momia)","La momia (The Mummy)","Xác Ướp","The Mummy I","The Mummy 1","盜墓迷城","A Múmia","Mūmija","ハムナプトラ／失われた砂漠の都","The Mummy"]', 1784690324535);
