INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-tinh-ngang-trai', 'Cuộc Tình Ngang Trái', 'A Matter of Business', 'https://phimimg.com/upload/vod/20251010-1/6973338fb6a8ffd2ac003b051268d1a2.jpg', 'https://phimimg.com/upload/vod/20251010-1/33561640d96d2c76a9e99383e7baf478.jpg', '<p>Huỳnh Ngọc Phấn là một cô gái nóng nảy nhưng thẳng thắn bộc trực, bởi tính cách này mà cô đã bị kẻ xấu mượn tay cô để hãm hại cấp trên của cô là Lạc Văn, làm Lạc Văn bị giáng chức oan uổng. Từ đó Phấn và Văn trở thành kẻ thủ không đội trời chung, Văn cũng luôn tìm dịp để trả thù...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 20, 1999, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ada Choi Siu-Fan","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Joseph Cheng King-Kei","avatar":""},{"name":"Cutie Mui Siu-Wai","avatar":""},{"name":"Johnny Siu Juen Dang","avatar":""},{"name":"May Kwong Man-Chun","avatar":""},{"name":"Joe Ma Tak-Chung","avatar":""},{"name":"Leung Wing-Lam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["千里姻緣兜錯圈"]', 1784690324535);
