INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-tinh-ngang-trai', 'Cuộc Tình Ngang Trái', 'A Matter of Business', 'cuộc tình ngang trái a matter of business ada choi siu-fan chin ka-lok joseph cheng king-kei cutie mui siu-wai johnny siu juen dang may kwong man-chun joe ma tak-chung leung wing-lam 千里姻緣兜錯圈', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duyen-no', 'Duyên Nợ', 'Man''s Best Friend', 'https://phimimg.com/upload/vod/20251010-1/6e33e516ade0acb6c9197f87e08e2b5e.jpg', 'https://phimimg.com/upload/vod/20251010-1/f9aef125018ab5de54d06170add4f157.jpg', '<p>Vì cuộc sống mưu sinh, ngoài công việc làm nhân viên thu nợ, Quan Gia Nhân (do Lâm Gia Đống đóng) còn nhận làm thêm nhiều việc cùng một lúc. Thay vì đồng cảm, chia sẻ cùng chồng, Rosa (do Lương Vịnh Lâm đóng) lại cho rằng Gia Nhân không có bản lĩnh, không có tương lai, nên đã để lại cậu con trai cho anh mà ra đi. Tình duyên của Gia Nhân lại tiếp tục lận đận khi cuộc tình với Vương Tư Tư (do Triệu Tịnh Nghi đóng) cũng nhanh chóng kết thúc vì tính tình không hợp nhau.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 1999, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Jessica Hsuan","avatar":""},{"name":"Sammi Cheng","avatar":""},{"name":"Joe Ma Tak-Chung","avatar":""},{"name":"Jerry Lamb Hiu-Fung","avatar":""},{"name":"Lee San-San","avatar":""},{"name":"Kwok Tak-San","avatar":""},{"name":"Ronny Ching Siu-Lung","avatar":""},{"name":"Kenny Wong Tak-Ban","avatar":""},{"name":"Leung Wing-Lam","avatar":""},{"name":"Wong Wai-Leung","avatar":""},{"name":"Law Lok-Lam","avatar":""},{"name":"Emotion Cheung Kam-Ching","avatar":""},{"name":"Choi Kwok-Hing","avatar":""},{"name":"Helen Ma Hoi-Lun","avatar":""},{"name":"Joh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Man''s Best Friend","寵物情緣"]', 1784690324535);
