INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('duyen-no', 'Duyên Nợ', 'Man''s Best Friend', 'duyên nợ man''s best friend louis koo jessica hsuan sammi cheng joe ma tak-chung jerry lamb hiu-fung lee san-san kwok tak-san ronny ching siu-lung kenny wong tak-ban leung wing-lam wong wai-leung law lok-lam emotion cheung kam-ching choi kwok-hing helen ma hoi-lun joh man''s best friend 寵物情緣', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-thach-nghiet-nga-thoi-dai-khung-hoang', 'Thử Thách Nghiệt Ngã (Thời Đại Khủng Hoảng)', 'At the Threshold of an Era', 'https://phimimg.com/upload/vod/20251010-1/c3d2c01f5ecf9ff0ae78db295877977b.jpg', 'https://phimimg.com/upload/vod/20251010-1/57d5195d029d8110163cad83225cc34c.jpg', '<p>Bộ ba Diệp Vinh Thiêm, Hứa Văn Bưu, Mã Chí Cường (La Gia Lương, Trần Cẩm Hồng, Quách Tấn An đóng) là những người bạn thân với nhau từ khi còn nhỏ. Họ lớn lên và cùng mơ ước sẽ lập một công ty riêng của ba người. Rắc rối bắt đầu xảy ra khi Diệp Vinh Thiêm và Hứa Văn Bưu cùng yêu cô gái Thậm Vịnh Hân (Quách Khả Doanh). Ban đầu, với sự quyết đoán, mưu trí đến mức lạnh lùng, Diệp Vinh Thiêm thắng thế. Nhưng rồi người chiến thắng cuối cùng là Hứa Văn Bưu. Sớm giành được thắng lợi trong tình yêu, thành công trong kinh doanh và tiền tài, nhưng Văn Bưu không thấy hạnh phúc. Anh dần sa chân vào con đường tội lỗi và dục vọng thấp hèn để rồi sau này đã phải trả giá đắt khi mọi thứ sụp đổ…</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 23, 1999, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Gallen Lo Ka-Leung","avatar":""},{"name":"Sunny Chan Kam-Hung","avatar":""},{"name":"Roger Kwok Chun-On","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Kenix Kwok Ho-Ying","avatar":""},{"name":"Flora Chan Wai-Shan","avatar":""},{"name":"Ada Choi Siu-Fan","avatar":""},{"name":"Liza Wong Ming-Chuen","avatar":""},{"name":"Maggie Shiu","avatar":""},{"name":"Nicky Wu","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Joe Ma Tak-Chung","avatar":""},{"name":"Hawick Lau Hau-Wai","avatar":""},{"name":"Samuel Kwok Fung","avatar":""},{"name":"Grace Yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["创世纪","創世紀","At the Threshold of an Era"]', 1784690324535);
