INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ve-thanh-nu-jeanne-darc', 'Câu Chuyện Về Thánh Nữ Jeanne D''Arc', 'The Messenger: The Story of Joan of Arc', 'https://phimimg.com/upload/vod/20251011-1/99bafaa797ca5d01ef1e9047ff36f0a5.jpg', 'https://phimimg.com/upload/vod/20251011-1/2affa3ddb566a8fb78130f8b33f3ef13.jpg', '<p>Được dịch từ tiếng Anh-The Messenger: The Story of Joan of Arc là một bộ phim sử thi lịch sử Pháp năm 1999 do Luc Besson đạo diễn với sự tham gia của Milla Jovovich, John Malkovich, Faye Dunaway và Dustin Hoffman. Kịch bản được Besson và Andrew Birkin chấp bút, và nhạc phim gốc được Éric Serra</p>', 'Full', 1, 'single', 'completed', 26, 1999, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Faye Dunaway","avatar":""},{"name":"Dustin Hoffman","avatar":""},{"name":"Pascal Greggory","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"Richard Ridings","avatar":""},{"name":"Desmond Harrington","avatar":""},{"name":"Timothy West","avatar":""},{"name":"Rab Affleck","avatar":""},{"name":"Stéphane Algoud","avatar":""},{"name":"Edwin Apps","avatar":""},{"name":"David Bailie","avatar":""},{"name":"David Barber","avatar":""},{"name":"Timothy Bateson","avatar":""},{"name":"David Be","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Joana D''Arc de Luc Besson","Посланниця: історія Жанни д''Арк","Jeanne d''Arc","Joan of Arc","Luc Besson''s Johanna von Orleans","Juana de Arco","The Messenger։ The Story of Joan of Arc","Jeanne d''Arc: The Messenger","잔다르크","Mesaj: Joan Arc''ın Hekayəsi"]', 1784690324535);
