INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-nha-yamada', 'Gia Đình Nhà Yamada', 'My Neighbors The Yamadas', 'https://phimimg.com/upload/vod/20250716-1/4b9b18a914baf812f29b42fc8fa3d0dc.jpg', 'https://phimimg.com/upload/vod/20250716-1/729afd3680f7d398da2d9961f8667cdc.jpg', '<p>Tại nước Nhật đương thời, cô bé năm tuổi Nonoko và các thành viên khác của gia đình Yamada kỳ quặc cùng nhau trải qua những cuộc phiêu lưu kỳ lạ và rắc rối thường nhật.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 1999, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Hayato Isohata","avatar":""},{"name":"Masako Araki","avatar":""},{"name":"Naomi Uno","avatar":""},{"name":"Toru Masuoka","avatar":""},{"name":"Yukiji Asaoka","avatar":""},{"name":"Akiko Yano","avatar":""},{"name":"Kosanji Yanagiya","avatar":""},{"name":"Tamao Nakamura","avatar":""},{"name":"Chōchō Miyako","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mes voisins les Yamada","Houhokekyo tonari no Yamada-kun","My Neighbours the Yamadas","이웃집 야마다군","Mis Vecinos los Yamada","ホーホケキョ となりの山田くん","Hôhokekyo tonari no Yamada-kun","Hoohokekyo Tonari no Yamada-kun","이웃의 야마다군","我的邻居山田君","Rodzinka Yamadów","Meus Vizinhos, Os Yamadas","A Família Yamada","Мои соседи Ямада","A Yamada család","Моите съседи Ямада","ยามาดะ ครอบครัวนี้ไม่ธรรมดา","Mina grannar Yamadas","隔壁的山田君","Hōhokekyo tonari no Yamada-kun"]', 1784690324535);
