INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-nha-yamada', 'Gia Đình Nhà Yamada', 'My Neighbors The Yamadas', 'gia đình nhà yamada my neighbors the yamadas hayato isohata masako araki naomi uno toru masuoka yukiji asaoka akiko yano kosanji yanagiya tamao nakamura chōchō miyako mes voisins les yamada houhokekyo tonari no yamada-kun my neighbours the yamadas 이웃집 야마다군 mis vecinos los yamada ホーホケキョ となりの山田くん hôhokekyo tonari no yamada-kun hoohokekyo tonari no yamada-kun 이웃의 야마다군 我的邻居山田君 rodzinka yamadów meus vizinhos, os yamadas a família yamada мои соседи ямада a yamada család моите съседи ямада ยามาดะ ครอบครัวนี้ไม่ธรรมดา mina grannar yamadas 隔壁的山田君 hōhokekyo tonari no yamada-kun', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('courage-chu-cho-nhut-nhat-phan-1', 'Courage: Chú Chó Nhút Nhát (Phần 1)', 'Courage the Cowardly Dog (Season 1)', 'https://phimimg.com/upload/vod/20250602-1/64161c3795a6687e8709de70c6a8470c.jpg', 'https://phimimg.com/upload/vod/20250602-1/a51eada95a731ea28d6f242e89bfba0a.jpg', '<p>Chú chó Courage nhút nhát được nhận nuôi bởi bà Muriel ở vùng Nowhere cùng với chồng là Eustace. Những câu chuyện kinh dị ở vùng này sẽ được Courage mang đến cùng với những cách giải quyết đầy dũng cảm.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 26, 1999, 'Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Marty Grabstein","avatar":""},{"name":"Thea White","avatar":""},{"name":"Lionel G. Wilson","avatar":""},{"name":"Simon Prebble","avatar":""},{"name":"Billie Lou Watt","avatar":""},{"name":"Paul Schoeffler","avatar":""},{"name":"Arthur Anderson","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Coraje, el perro cobarde","Agallas, el perro cobarde","Bátor, a gyáva kutya","겁쟁이 강아지 커리지","เคอเรจ เจ้าตูบจอมขลาด","เคอเรจ เจ้าตูบจอมขี้ขลาด","Cesur Korkak Köpek","Courage the Cowardly Dog"]', 1784690324535);
