INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-hut-tu-nhien', 'Lực hút tự nhiên', 'Forces of Nature', 'https://phimimg.com/upload/vod/20250514-1/e474fe1c3d1b43c78896c57569fae9a7.jpg', 'https://phimimg.com/upload/vod/20250514-1/2c7fd371fdcea1c873e7344cf060e276.jpg', '<p>Khi chuyến bay đến đám cưới của anh bị hoãn, Ben thuê xe cùng cô nàng phóng khoáng Sarah. Rồi giữa họ hình thành mối quan hệ khiến anh đặt câu hỏi về cuộc hôn nhân của mình.</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Ben Affleck","avatar":""},{"name":"Maura Tierney","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Blythe Danner","avatar":""},{"name":"Ronny Cox","avatar":""},{"name":"Michael Fairman","avatar":""},{"name":"Janet Carroll","avatar":""},{"name":"Richard Schiff","avatar":""},{"name":"David Strickland","avatar":""},{"name":"Meredith Scott Lynn","avatar":""},{"name":"George D. Wallace","avatar":""},{"name":"Steve Hytner","avatar":""},{"name":"John Doe","avatar":""},{"name":"Jack Kehler","avatar":""},{"name":"Anne Haney","avatar":""},{"name":"Bert Remsen","avatar":""},{"name":"Julie","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Un vent de folie","Las fuerzas de la naturaleza","觸電之旅","Forces of Nature"]', 1784690324535);
