INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luc-hut-tu-nhien', 'Lực hút tự nhiên', 'Forces of Nature', 'lực hút tự nhiên forces of nature sandra bullock ben affleck maura tierney steve zahn blythe danner ronny cox michael fairman janet carroll richard schiff david strickland meredith scott lynn george d. wallace steve hytner john doe jack kehler anne haney bert remsen julie un vent de folie las fuerzas de la naturaleza 觸電之旅 forces of nature', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ba-cuon-vong', 'Người Đàn Bà Cuồn Vọng', 'Indecent Woman', 'https://phimimg.com/upload/vod/20250514-1/27c62b6509951abc45e9cceb593c2066.jpg', 'https://phimimg.com/upload/vod/20250514-1/7b9dd7b2a116c6ee104871f41deba7a7.jpg', '<p>Khi biết chồng mình cố ý đem thân xác cô ra đổi chác vì lợi ích kinh doanh, Lam mất kiểm soát và giết chết chồng. Sau đó, cô lập ra một kế hoạch để dụ dỗ đối tác làm ăn của chồng và cũng ra tay sát hại người này. Lam có ấn tượng tốt với Ka-Wah, và để chiếm được anh, cô đã ép bạn gái của Ka-Wah tự tử. May mắn thay, cô gái trốn thoát được và khi cảnh sát đến, họ phát hiện Ka-Wah bị trói trên giường. Lam bị bắt và bi kịch kết thúc tại đó.</p>', 'Full', 1, 'single', 'completed', 24, 1999, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Yeung Fan","avatar":""},{"name":"Charlie Cho Cha-Lee","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Oscar Lam Wai-Kin","avatar":""},{"name":"Dung Yi","avatar":""},{"name":"Lee Siu-Kay","avatar":""},{"name":"Chung Koo-Ling","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["女色狼","Indecent Woman"]', 1784690324535);
