INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-cat', 'Đời Cát', 'Sandy Lives', 'https://phimimg.com/upload/vod/20250428-1/f69fb1b51a665eb5fc7d0a14bfadd616.jpg', 'https://phimimg.com/upload/vod/20250428-1/4cbd40e0a532647f68a2c3adead1178f.jpg', '<p>Vì chiến tranh, Cảnh buộc phải rời xa người vợ tên Thoa để ra trận, rồi sau đó lại vướng vào mối tình ngang trái với cô gái trẻ tên Tâm. Dù mang trong mình nỗi đau bị phản bội, Thoa vẫn bao dung và tha thứ cho chồng, như một biểu tượng của sự hy sinh thầm lặng và lòng vị tha sâu sắc. Không chỉ là câu chuyện bi kịch cá nhân, Đời Cát còn là tiếng vọng về của những tổn thương kéo dài mà chiến tranh để lại trên số phận con người, chạm đến những tầng sâu cảm xúc bằng sự tinh tế và nhân văn.</p>', 'Full', 1, 'single', 'completed', 16, 1999, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Mai Hoa","avatar":""},{"name":"Hồng Ánh","avatar":""},{"name":"Đơn Dương","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324535);
