INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rosetta', 'Rosetta', 'Rosetta', 'https://phimimg.com/upload/vod/20250424-1/f49ee7c33144ecff0166fef21c16b563.jpg', 'https://phimimg.com/upload/vod/20250424-1/69f5488b029d89c2ce48adb51ddb4731.jpg', '<p>Bộ phim kể về câu chuyện của một cô gái tuổi teen tên là Rosetta, do Émilie Dequenne thủ vai, sống tại một khu caravan với người mẹ nghiện rượu. Để thoát khỏi hoàn cảnh sống khó khăn, Rosetta không ngừng tìm kiếm việc làm để có một cuộc sống ổn định và an toàn hơn. Bộ phim đã nhận được sự khen ngợi từ giới phê bình và giành được nhiều giải thưởng, bao gồm Palme d&#39;Or và giải Nữ diễn viên xuất sắc nhất tại Liên hoan phim Cannes 1999.</p>', 'Full', 1, 'single', 'completed', 11, 1999, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Émilie Dequenne","avatar":""},{"name":"Olivier Gourmet","avatar":""},{"name":"Fabrizio Rongione","avatar":""},{"name":"Anne Yernaux","avatar":""},{"name":"Bernard Marbaix","avatar":""},{"name":"Frédéric Bodson","avatar":""},{"name":"Florian Delain","avatar":""},{"name":"Christiane Dorval","avatar":""},{"name":"Mireille Bailly","avatar":""},{"name":"Thomas Gollas","avatar":""},{"name":"Leon Michaux","avatar":""},{"name":"Victor Marit","avatar":""},{"name":"Colette Regibeau","avatar":""},{"name":"Claire Tefnin","avatar":""},{"name":"Sophia Leboutte","avatar":""},{"name":"Gaetano V","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["露茜妲","美麗的羅西塔","Rosetta"]', 1784690324535);
