INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-gian-huyen-ao', 'Nhân Gian Huyền Ảo', 'A Traditional Story Of Taiwan', 'https://phimimg.com/upload/vod/20250413-1/fdf3878d009fe72765d2bcefb4e10549.jpg', 'https://phimimg.com/upload/vod/20250413-1/9f5ea83ec20488ab0e4ae6cd29a7bc84.jpg', '<p>Không đơn thuần tập trung vào những yếu tố liêu trai, “Nhân gian huyền ảo” còn lột tả sinh động những câu chuyện đời thường đậm triết lý nhân quả báo ứng. Và mỗi câu chuyện qua đi là một bài học được đọng lại với thông điệp chung: hãy làm điều thiện, trọng nhân nghĩa và biết thứ tha.</p>', 'Hoàn Tất (195/195)', 195, 'series', 'completed', 17, 1999, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"La Xảo Hân","avatar":""},{"name":"Trần Uy Hàn","avatar":""},{"name":"Sử Đại Tây","avatar":""},{"name":"Hoắc Chính Kỳ","avatar":""},{"name":"Trần Hiểu Tinh","avatar":""},{"name":"Giản Gia Vĩ","avatar":""},{"name":"Trần Kiến Long","avatar":""},{"name":"Dư Thái Ân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["炎炎消防队 叁之章","炎炎消防队 贰之章","炎炎消防队 壹之章","Fire Force","En''en no Shouboutai","Enn Enn no Shōbōtai","Enen no Shouboutai","Enen no Shouboutai: Ni no Shou","Enen no shôbôtai","En''en no Shouboutai Ni no Shou","Enn Enn no Shouboutai","Enen no Shōbōtai","Enen No Shouboutai - Ni no Shou","炎炎ノ消防隊 弐ノ章","炎炎ノ消防隊 参ノ章","Enen no Shouboutai San","Пламенная бригада пожарных","Пламенный отряд","Огненная бригада пожарных!","Огненная бригада","炎炎消防隊 貳之章","炎炎消防隊 參之章","Fire Brigade of Flames","Fireforce","Blazing Fire Brigade","Bộc Hỏa Nhân Tượng","炎炎ノ消防隊"]', 1784690324535);
