INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhan-gian-huyen-ao', 'Nhân Gian Huyền Ảo', 'A Traditional Story Of Taiwan', 'nhân gian huyền ảo a traditional story of taiwan la xảo hân trần uy hàn sử đại tây hoắc chính kỳ trần hiểu tinh giản gia vĩ trần kiến long dư thái ân 炎炎消防队 叁之章 炎炎消防队 贰之章 炎炎消防队 壹之章 fire force en''en no shouboutai enn enn no shōbōtai enen no shouboutai enen no shouboutai: ni no shou enen no shôbôtai en''en no shouboutai ni no shou enn enn no shouboutai enen no shōbōtai enen no shouboutai - ni no shou 炎炎ノ消防隊 弐ノ章 炎炎ノ消防隊 参ノ章 enen no shouboutai san пламенная бригада пожарных пламенный отряд огненная бригада пожарных! огненная бригада 炎炎消防隊 貳之章 炎炎消防隊 參之章 fire brigade of flames fireforce blazing fire brigade bộc hỏa nhân tượng 炎炎ノ消防隊', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-o-que-toi', 'Chuyện Ở Quê Tôi', 'My Hometown Story', 'https://phimimg.com/upload/vod/20250406-1/4afa9c43a5ec88c43fee019e71fffc0e.jpg', 'https://phimimg.com/upload/vod/20250406-1/49ac82af87cd24e94467a7334d2f4be9.jpg', '<p>Bộ phim xoay quanh chuỗi bi kịch cuộc đời của ông Tư Thương - một người hiền lành, chịu khó và từng tham gia kháng chiến chống thực dân, lại là thủ phạm giết người. Trong thời kỳ đất nước đổi mới, Hai Mạnh là cán bộ trẻ của xã, tuy nhiên anh luôn mượn danh nghĩa này để luồn lách, trục lợi, lộng quyền và ức hiếp dân. Vì thế, cuộc sống của người dân nơi đây luôn thiếu trước hụt sau, khốn khó trăm bề, đến nỗi hai cha con ông Tư Thương còn có ý định bỏ đất, bỏ quê để bắt đầu lại . Tuy nhiên, thảm kịch xảy ra khi Hai Mạnh giở thói lưu manh định hãm hại Trâm - con gái duy nhất của ông Tư Thương. May thay, ông kịp thời trở về và trong lúc giằng co đã dẫn đến cái chết của Hai Mạnh, từ đây hé lộ câu chuyện oan nghiệt của 30 năm về trước...</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 12, 1999, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Mai Huỳnh","avatar":""},{"name":"Nguyễn Trọng Hải","avatar":""},{"name":"Hoàng Phúc","avatar":""},{"name":"Hiền Mai","avatar":""},{"name":"Thùy Liên","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["ואן-פאנץ'' מאן","וואן פאנץ'' מן","वन पंच मैन","مرد یک مشتی","Wanpanman","One Punch Man","ONE PUNCH MAN ワンパンマン","OPM","Человек одного удара","ون بنش مان","Anh Hùng OnePunch","Nhất Quyền Nhân","ワンパンマン"]', 1784690324535);
