INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-o-que-toi', 'Chuyện Ở Quê Tôi', 'My Hometown Story', 'chuyện ở quê tôi my hometown story mai huỳnh nguyễn trọng hải hoàng phúc hiền mai thùy liên ואן-פאנץ'' מאן וואן פאנץ'' מן वन पंच मैन مرد یک مشتی wanpanman one punch man one punch man ワンパンマン opm человек одного удара ون بنش مان anh hùng onepunch nhất quyền nhân ワンパンマン', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-son-ngay-ay', 'Trường Sơn Ngày Ấy', 'Truong Son In Those Days', 'https://phimimg.com/upload/vod/20250406-1/d0a537230b6cb13dffd8d10ffe9db54c.jpg', 'https://phimimg.com/upload/vod/20250406-1/b371d0f2e7d42feccef47627217583c7.jpg', '<p>Trường Sơn ngày ấy mô tả lại giai đoạn Chiến tranh Việt Nam đang diễn ra ác liệt. Tại một cánh rừng nằm ở Dãy Trường Sơn thuộc Miền Nam, hai người lính Giải Phóng là Cường và Nam đang trên đường về đơn vị đã gặp một toán Thám báo, Nam hi sinh. Cường truy đuổi toán Thám báo nhằm tiêu diệt họ. Sau đó, Cường bị thương và nhận ra mình đã lạc giữa Trường Sơn. Không lâu sau đơn vị ghi nhận Cường và Nam đều đã hi sinh. Cường tìm đến một căn cứ nào đó của Quân Giải Phóng và mừng rỡ khi tìm thấy một trạm xá của Quân Giải Phóng nhưng toàn bộ người trong trạm xá đều đã bị giết. Anh buồn bã và thất vọng, chôn cất mọi người xong anh lại tiếp tục đi. Rồi anh gặp Liên, một người lính phụ trách một kho hàng của Quân Giải Phóng nhưng lâu nay không có đoàn công tác nào ghé qua. Ở đây, Cường đã được Liên chăm sóc cho lành vết thương và hai ngườicũng đã nảy sinh tình cảm với nhau. Đến một ngày, bất ngờ Cường rời bỏ Liên lại một mình và tìm đường về đơn vị để tiếp tục tham gia cuộc chiến.</p>', 'Full', 1, 'single', 'completed', 12, 1999, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Chi Bảo","avatar":""},{"name":"Cao Minh Đạt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324535);
