INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-do-choi-2', 'Câu Chuyện Đồ Chơi 2', 'Toy Story 2', 'https://phimimg.com/upload/vod/20250327-1/a509064f985b8895f2e4b59ca5254a54.jpg', 'https://phimimg.com/upload/vod/20250327-1/f5bb58f3046a8a7b6857d133ec3faf91.jpg', '<p>Câu Chuyện Đồ Chơi 2 là cuộc phiêu lưu của Woody (Tom Hanks lồng tiếng) và Buzz Lightyear (Tim Allen) lại tiếp tục khi chủ nhân của chúng Andy (John Morris) đi tham dự trại hè và để mặc chúng ở nhà tự lo liệu. Woody không may bị một tay buôn bán đồ chơi đánh cắp. Buzz cùng các bạn đồ chơi bèn tìm cách giải cứu Woody. Mọi chuyện tưởng chừng thuận lợi nhưng trong khi bị giam giữ, Woody quen được Jessy - một tay &quot;cowgirl&quot;. Thế là cả nhóm quyết định đưa luôn Jessy trở về nhà... sau khi trải qua bao khó khăn.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 1999, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Tim Allen","avatar":""},{"name":"Joan Cusack","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Don Rickles","avatar":""},{"name":"Jim Varney","avatar":""},{"name":"Wallace Shawn","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"Annie Potts","avatar":""},{"name":"Wayne Knight","avatar":""},{"name":"John Morris","avatar":""},{"name":"Laurie Metcalf","avatar":""},{"name":"Estelle Harris","avatar":""},{"name":"R. Lee Ermey","avatar":""},{"name":"Jodi Benson","avatar":""},{"name":"Jonathan Harris","avatar":""},{"name":"Joe Ranft","avatar":""},{"name":"Andrew Stanton","avatar":""},{"name":"Je","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Toy Story 2 - Woody e Buzz alla Riscossa","Toy 