INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-ngan-ha', 'Siêu Nhân Ngân Hà', 'Power Rangers Lost Galaxy', 'https://phimimg.com/upload/vod/20250323-1/3af7007df90f90adb73eff09b438712f.jpg', 'https://phimimg.com/upload/vod/20250323-1/273e910baff333d8c05602e3e3354ee6.jpg', '<p>Ở 1 hành tinh xa xôi – nơi đang phong ấn 5 thanh kiếm thần kỳ trong một khu rừng. Tương truyền chúng là báu vật trấn thủ, bảo vệ nơi này, khống chế ma lực bóng tối của lũ quỷ độc ác.Khi thế lực bóng tối trỗi dậy, 5 thanh kiếm sẽ chọn ra 5 người để bảo vệ hành tinh và cả dải ngân hà.Họ là Leo, Damon, Kendrix, Maya và Kai. Hợp sức lại, họ trở thành biệt đôị bảo vệ ngân hà – Power Ranger Lost Galaxy.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 13, 1999, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Power Rangers Super Megaforce Finale: Legendary Battle","Power Rangers Super Megaforce: The Legendary Battle"]', 1784690324535);
