INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-xanh-sau-tham', 'Biển Xanh Sâu Thẳm', 'Deep Blue Sea', 'https://phimimg.com/upload/vod/20250302-1/412e9503d6ae9abe1c859e09c8b668c8.jpg', 'https://phimimg.com/upload/vod/20250302-1/27f86cacb1afa32a88c7ddb9abd12964.jpg', '<p>Một nhóm các nhà khoa học làm việc trong một khu hải dương học tại bờ biển Baja, California đang làm những nghiên cứu khoa học về loài cá mập. Đặc biệt là nhóm trưởng – nữ giáo sư Susan McAlester (Saffron Burrows) và Jim Whitlock (Stellan Skarsgard) tìm cách cấy mô não người vào cá mập để tìm ra phương thuốc chữa bệnh tâm thần. &nbsp;Họ tin rằng các chất protein chứa trong não cá mập có thể là chìa khóa cho phương thuốc này. Kết quả ngược với mong đợi của mọi người vì chính nghiên cứu ấy lại tạo ra một loài cá mập hung dữ có khả năng suy nghĩ như con người. Chúng không cam chịu sống trong những chiếc lồng kín, bị tiêm những loại thuốc hóa học thử nghiệm mà muốn phá bỏ tất cả để về với đại dương sâu thẳm.</p>', 'Full', 1, 'single', 'completed', 18, 1999, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Thomas Jane","avatar":""},{"name":"Saffron Burrows","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Jacqueline McKenzie","avatar":""},{"name":"Michael Rapaport","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"LL Cool J","avatar":""},{"name":"Aida Turturro","avatar":""},{"name":"Cristos","avatar":""},{"name":"Daniel Rey","avatar":""},{"name":"Valente Rodriguez","avatar":""},{"name":"Brent Roam","avatar":""},{"name":"Eyal Podell","avatar":""},{"name":"Erinn Bartlett","avatar":""},{"name":"Dan Thiel","avatar":""},{"name":"Sabrina Geerinckx","avatar":""},{"name":"Tajsha Thom","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["딥 블루 씨 1","Duboko plavo more","Útok z hlbín","Deep Blue Sea"]', 1784690324535);
