INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-ket-hanh-phuc', 'Đoạn Kết Hạnh Phúc', 'Happy End', 'https://phimimg.com/upload/vod/20250210-1/dba2252cbb6808221affbf9884ae42b9.jpg', 'https://phimimg.com/upload/vod/20250210-1/07fc840a7b9e355a1a07b67a3637931c.jpg', '<p>Người đàn ông từng làm việc ở ngân hàng bị mất việc và bị phản bội. Người vợ thành đạt của anh ta đã có nhân tình. Trái tim rách nát của anh ta nhanh chóng biến thành cơn giận dữ, nhưng người chồng vẫn giữ chiếc nhẫn cưới. Kết cục cuối cùng phải là hạnh phúc. Kế hoạch bí mật để bảo vệ gia đình của anh ta bắt đầu.</p>', 'Full', 1, 'single', 'completed', 21, 1999, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jeon Do-yeon","avatar":""},{"name":"Choi Min-sik","avatar":""},{"name":"Ju Jin-mo","avatar":""},{"name":"Joo Hyun","avatar":""},{"name":"Yoo Yeon-soo","avatar":""},{"name":"Park Ji-il","avatar":""},{"name":"Kim Byung-choon","avatar":""},{"name":"Park Nam-hee","avatar":""},{"name":"Lee Geum-ju","avatar":""},{"name":"Park Seong-il","avatar":""},{"name":"Son Jin-ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Haepi-endeu","快乐到死","해피엔드","해피 엔드","Happy End","ハッピーエンド：1999"]', 1784690324535);
