INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-ngam', 'Biệt Đội Ngầm', 'The Mod Squad', 'https://phimimg.com/upload/vod/20241112-1/d3220122296f816b575ad1344f3e41bc.jpg', 'https://phimimg.com/upload/vod/20241112-1/0c693079ebac3687d6cf34a811b8cfa6.jpg', '<p>The Mod Squad (1999) xoay quanh ba thanh thiếu niên với quá khứ bất hảo, bị bắt giam và nhận được đề nghị đặc biệt: làm việc cùng một cảnh sát ngầm để điều tra một đường dây buôn bán ma túy phức tạp. Trong quá trình thực hiện nhiệm vụ, họ rơi vào một cái bẫy chết người và trở thành mục tiêu truy lùng của cảnh sát. Không còn nhiều thời gian, họ phải nhanh chóng vạch trần sự thật và minh oan cho chính mình.</p>', 'Full', 1, 'single', 'completed', 12, 1999, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Claire Danes","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Omar Epps","avatar":""},{"name":"Dennis Farina","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Steve Harris","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Larry Brandenburg","avatar":""},{"name":"Lionel Mark Smith","avatar":""},{"name":"Sam McMurray","avatar":""},{"name":"Michael O''Neill","avatar":""},{"name":"Stephen Kay","avatar":""},{"name":"Bodhi Elfman","avatar":""},{"name":"Holmes Osborne","avatar":""},{"name":"Dey Young","avatar":""},{"name":"Toby Huss","avatar":""},{"name":"Michael Lerner","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Mod Squad"]', 1784690324535);
