INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-sopranos-phan-1', 'Gia Đình Sopranos (Phần 1)', 'The Sopranos (Season 1)', 'https://phimimg.com/upload/vod/20241105-1/506e6fcdf3457f399e467341bcc00c21.jpg', 'https://phimimg.com/upload/vod/20241105-1/9d8e4d60c5473e852773f201fd617f0b.jpg', '<p>Trong Phần 1, cảm thấy việc quản lý gia đình và công việc kinh doanh của mình đang tuột dốc, trùm băng đảng Tony Soprano phải chịu một loạt cơn lo lắng tấn công khiến anh ta phải vào văn phòng của bác sĩ tâm lý. Mở lòng với căn bệnh teo nhỏ của mình, Tony kể lại chi tiết cuộc đời mình với tư cách là một “nhà tư vấn quản lý chất thải” và cố gắng đối mặt với những áp lực nghề nghiệp và cá nhân đã đưa anh đến bờ vực suy sụp.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 1999, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Gandolfini","avatar":""},{"name":"Edie Falco","avatar":""},{"name":"Jamie-Lynn Sigler","avatar":""},{"name":"Robert Iler","avatar":""},{"name":"Lorraine Bracco","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Steven Van Zandt","avatar":""},{"name":"Tony Sirico","avatar":""},{"name":"Dominic Chianese","avatar":""},{"name":"Aida Turturro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Família Soprano","人在江湖","Rodina Sopránů","آل سوبرانو","סופרנוס","द सोप्रानोस","سوپرانو","خانواده سوپرانو","سوپرانوز","Rodzina Soprano","Семья Сопрано","Клан Сопрано","The Sopranos"]', 1784690324535);
