INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-ca-sau', 'Hồ Cá Sấu', 'Lake Placid', 'https://phimimg.com/upload/vod/20231016-1/231a8dee73c8f5f52559d18eea8121e5.jpg', 'https://phimimg.com/upload/vod/20231016-1/3edb37f855eabe8c4d130b42126375bf.jpg', '<p>Khi một người đàn ông bị một sinh vật lạ ăn thịt, Người quản lý trò chơi địa phương hợp tác với một nhà cổ sinh vật học đến từ New York để tìm ra con quái vật. Thêm vào đó là một nhà từ thiện lập dị có thiên hướng</p>', 'Full', 1, 'single', 'completed', 12, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Pullman","avatar":""},{"name":"Bridget Fonda","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Betty White","avatar":""},{"name":"David James Lewis","avatar":""},{"name":"Tim Dixon","avatar":""},{"name":"Natassia Malthe","avatar":""},{"name":"Mariska Hargitay","avatar":""},{"name":"Meredith Salenger","avatar":""},{"name":"Jed Rees","avatar":""},{"name":"Richard Leacock","avatar":""},{"name":"Jake T. Roberts","avatar":""},{"name":"Warren Takeuchi","avatar":""},{"name":"Ty Olsson","avatar":""},{"name":"Adam Arkin","avatar":""},{"name":"Steve Miner","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324535);
