INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-chang-doc-than', 'Anh Chàng Độc Thân', 'The Bachelor', 'https://phimimg.com/upload/vod/20240913-1/03e959a536d17c222b7a8664039ee80b.jpg', 'https://phimimg.com/upload/vod/20240913-1/0daa2497bb480d0e02143d7c8e4ec713.jpg', '<p>“The Bachelor” là một bộ phim hài lãng mạn của Mỹ, do Gary Sinyor đạo diễn. Phim kể về Jimmie Shannon (Chris O’Donnell), một người đàn ông sợ cam kết, phải tìm một cô dâu trong vòng 24 giờ để thừa kế 100 triệu đô la từ ông nội của mình.</p>', 'Full', 1, 'single', 'completed', 12, 1999, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chris O''Donnell","avatar":""},{"name":"Renée Zellweger","avatar":""},{"name":"Artie Lange","avatar":""},{"name":"Ed Asner","avatar":""},{"name":"Hal Holbrook","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Marley Shelton","avatar":""},{"name":"Peter Ustinov","avatar":""},{"name":"Katharine Towne","avatar":""},{"name":"Rebecca Cross","avatar":""},{"name":"Stacy Edwards","avatar":""},{"name":"Mariah Carey","avatar":""},{"name":"Sarah Silverman","avatar":""},{"name":"Jennifer Esposito","avatar":""},{"name":"Brooke Shields","avatar":""},{"name":"Lydell M. Cheshier","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
