INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-tran', 'Ma Trận', 'The Matrix', 'https://phimimg.com/upload/vod/20231014-1/19e1af28cf91bac65637b7089ac3a6a6.jpg', 'https://phimimg.com/upload/vod/20231014-1/799d42634df3b35ae3fb28cf1bf14a9c.jpg', '<p>The Matrix (MaTrận) là bộ phim khoa học giả tưởng về tương lai. Trong tương lai đó, Thomas, biệt danh Neo, là một hacker luôn có cảm giác khác thường về thế giới thực. Cho tới khi người đàn ông tự xưng là Morpheus tìm đến anh. Người đàn ông này nói cho anh biết, thế giới mà mọi người coi là thực chỉ là một chương trình giả lập để máy móc cai trị con người. Chỉ có một người có thể phá được Ma trận. Những người thật sống sót còn lại cuối cùng và những nhân viên Ma trận đều cùng đi tìm người đó. Và người đó chính là anh – Neo…</p>', 'Full', 1, 'single', 'completed', 18, 1999, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Carrie-Anne Moss","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Marcus Chong","avatar":""},{"name":"Anthony Ray Parker","avatar":""},{"name":"Matt Doran","avatar":""},{"name":"Gloria Foster","avatar":""},{"name":"Belinda McClory","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324535);
