INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-kinh-ngac', 'Hành Trình Kinh Ngạc', 'Amazing Journeys', 'null', 'https://phimimg.com/upload/vod/20231103-1/8266554486007c1077653e502985691f.jpg', '<p>Tập phim do IMAX sản xuất đã tiết lộ những bí mật của những cuộc di cư vĩ đại nhất trên hành tinh chúng ta, cuộc hành trình của bướm chúa Bắc Mỹ, của những con cá voi hay của loài cua đỏ trên đảo Giáng Sinh. Bên cạnh đó còn là cuộc di cư vĩ đại nhất trong các cuộc di cư, đó là cuộc di cư của con người! Chúng ta thống trị mọi ngõ ngách trên hành tinh và làm ảnh hưởng đến các loài vật khác. Tập phim không chỉ mang lại nhiều kiến thức hay mà còn có ý nghĩa giáo dục, bảo vệ môi trường!</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Foxworth","avatar":""},{"name":"Wemi Ajigrotafe","avatar":""},{"name":"David L. Barbee","avatar":""},{"name":"Kerry W. Cook","avatar":""},{"name":"Jimmy I.","avatar":""},{"name":"Ebonie Smith","avatar":""},{"name":"George A. Thomas","avatar":""},{"name":"Tamir Yardenne","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324535);
