INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-kiem-tram-gian-hung', 'Nộ Kiếm Trảm Gian Hùng', 'Hai Rui & Yan Song', 'https://phimimg.com/upload/vod/20240711-1/ca1524c6032d24371198465b4095e99f.jpg', 'https://phimimg.com/upload/vod/20240711-1/64b1139b9b88569ce96ad5d2bc36ac21.jpg', '<p><em>Nhiệm Tùng là một gian thần hiểm ác đời nhà Tồng, đã lộng hành thao túng quyền lực trong triều đình, ngay cả Vua cũng phải kiêng nể. Trong khi đó lại có một đại thần trung can nghĩa đảm là Ông Hải Thoại vì nước vì dân bất mãn với hành vi ngang tàng của Nghiêm Tùng, tà không thể thắng chánh nên cuối cùng Nghiêm Tùng cũng bị chém đầu trị tội...</em></p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 22, 1999, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Đình Oai","avatar":""},{"name":"Thạch Tú","avatar":""},{"name":"Hà Bửu Sinh","avatar":""},{"name":"Trần Vỹ","avatar":""},{"name":"Diêu Gia Ni","avatar":""},{"name":"Lưu Vĩnh","avatar":""},{"name":"Châu Yến Trân","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324535);
