INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('no-kiem-tram-gian-hung', 'Nộ Kiếm Trảm Gian Hùng', 'Hai Rui & Yan Song', 'nộ kiếm trảm gian hùng hai rui & yan song trần đình oai thạch tú hà bửu sinh trần vỹ diêu gia ni lưu vĩnh châu yến trân ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-tieu-phan-2-nguoi-tinh-hiep-khach', 'Bảo Tiêu (Phần 2) - Người Tình Hiệp Khách', 'Bodyguards: Cryptic Crystal', 'https://phimimg.com/upload/vod/20240627-1/c4b9481e7ff1d6892d8fcc262a3243dc.jpg', 'https://phimimg.com/upload/vod/20240627-1/1c281a2776bd64a6d2e6f8a3fd8eead6.jpg', '<p><em>Bảo Tiêu 2 - Thúy Đình Hiệp Nữ: Vốn là Nghiêm Thân Vương trong triều có dã tâm, chuẩn bị tiến hành mưu phản. Trong tay hắn ta có một khối thuỷ tinh làm từ băng tuyết Thiên Sơn, có phép màu nhiệm. Phái võ lâm cao thủ Hồng Khôn (Trương Chấn Hoàn) bí mật liên lạc với Nam Xương phủ. Còn Thừa Tướng thì phái mật thám Thôi Kính Chi, Thúy Đình (Hồ Huệ Trung diễn) theo dõi, tìm cách thu thập chứng cứ mưu phản của Nghiêm Thân Vương. Trong lúc họ đang tìm cách đoạt lấy khối thuỷ tinh, thì Thôi Kính Chi bị Hồng Khôn đả thương, trước lúc chết liền nhờ Quách Húc giúp đỡ em gái mình hoàn thành nhiệm vụ, hy vọng Thúy Đình có thể cùng khối thuỷ tinh kia về cung an toàn. Nhưng anh cũng yêu cầu Quách Húc đến ngày 15 tháng 8 phải ra tay giết Thúy Đình. Trong quá trình hộ tống, Quách Húc phát hiện ra Thúy Đình chính là ái phi và cũng là sát thủ của Nghiêm Thân Vương – Hình Cơ, còn Thái Ngọc cũng bị cuốn vào con đường sai trái Thúy Đình (Hồ Huệ Trung): Là mật thám triều đình, võ công cao cường, tính tình tự phụ kiêu ngạo. Trong lúc truy tìm khối thuỷ tinh , phát hiện ra thân phận thật sự chính là ái phi của Ninh Vương – Hình Cơ.</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 21, 1999, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Gia Kính","avatar":""},{"name":"Trịnh Hạo Nam","avatar":""},{"name":"Trần Hồng Liệt","avatar":""},{"name":"Huỳnh Văn Hào","avatar":""},{"name":"Lưu Ngọc Đình","avatar":""},{"name":"Hồ Huệ Trung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324535);
