INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bao-tieu-phan-2-nguoi-tinh-hiep-khach', 'Bảo Tiêu (Phần 2) - Người Tình Hiệp Khách', 'Bodyguards: Cryptic Crystal', 'bảo tiêu (phần 2) - người tình hiệp khách bodyguards: cryptic crystal hà gia kính trịnh hạo nam trần hồng liệt huỳnh văn hào lưu ngọc đình hồ huệ trung ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-dai-song-kieu-1999', 'Tuyệt Đại Song Kiêu', 'The Legendary Siblings', 'https://phimimg.com/upload/vod/20240625-1/cd52da21f8dd0123b37bab2781ae44ed.jpg', 'https://phimimg.com/upload/vod/20240625-1/51bdd28899319c22680ce17f80cd5681.jpg', '<p>Yến Nam Thiên vì thiên hạ nên đã bỏ rơi Yên Nguyệt cung chủ, vì yêu hóa hận nên Yên Nguyệt ghét tất cả những người đàn ông trên thế gian, nhưng bà vẫn giữ mãi hình bóng của Yến Nam Thiên trong trái tim mình. Bà tìm mọi cơ hội để làm cho Yến Nam Thiên đau khổ. Trong giang hồ lúc bấy giờ, Di Hoa Cung là nơi quyền lực nhất và Yên Nguyệt là người sáng lập. Một lần tình cờ Liên Tinh, sư muội của Yên Nguyệt, cứu được huynh đệ kết nghĩa của Yến Nam Thiên là Ngọc Lan Giang Phong, đệ nhất mĩ nam tử và đem lòng yêu anh, nhưng Giang Phong lại đem lòng yêu Nguyệt Nô, một nô tỳ trong Di Hoa Cung và hai người trốn khỏi Di Hoa Cung.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 19, 1999, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Tô Hữu Bằng","avatar":""},{"name":"Lâm Chí Dĩnh","avatar":""},{"name":"Lý Ỷ Hồng","avatar":""},{"name":"Trần Đức Dung","avatar":""},{"name":"Trịnh Gia Dĩnh","avatar":""},{"name":"Vu Lợi","avatar":""},{"name":"Lâm Thoại Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324535);
