INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuyet-dai-song-kieu-1999', 'Tuyệt Đại Song Kiêu', 'The Legendary Siblings', 'tuyệt đại song kiêu the legendary siblings tô hữu bằng lâm chí dĩnh lý ỷ hồng trần đức dung trịnh gia dĩnh vu lợi lâm thoại dương ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-3-ao-thuat-gia-cuoi-cung-cua-the-ky', 'Thám Tử Lừng Danh Conan 3: Ảo Thuật Gia Cuối Cùng Của Thế Kỷ', 'Detective Conan: The Last Wizard of the Century', 'https://phimimg.com/upload/vod/20231019-1/46fb004874a3202d11135ab0252aa394.jpg', 'https://phimimg.com/upload/vod/20231019-1/e954d2ab54b9a3b1fff45dcaad386105.jpg', '<p>Imperial Easter Egg là món đồ nghệ thuật mà sa hoàng Nga đặt nghệ nhân Faberge tạo ra để làm quà tặng cho hoàng hậu nhân lễ phục sinh. Không chỉ Kid mà rất nhiều nhân vật tham gia vào vụ trộm này : Hoshi Seiran, nhà nghiên cứu vương triều Romanov; Ông Inui, nhà buôn đồ cổ; Ông Serger Ovchinikov - bí thư thứ nhất đại sứ quán Nga; Anh Sagawa Ryu – nhiếp ảnh gia tự do... Một cuộc họp khẩn do thanh tra Chaki chủ trì với sự góp mặt của các thanh tra cảnh sát cao cấp nhằm giải mã thư cảnh báo của siêu đạo chích Kid và ngăn chặn vụ trộm của hắn. Một lần nữa Hattori và Conan lại đụng độ cùng giải mã bí ẩn của Kid và báu vật có 1 không hai. Kid với những trò phù thủy của mình lại biến mất trong quá trình truy đuổi. Một kẻ bí ẩn đã ra tay? Kẻ đó là ai? Kid có thực sự chết? Lâu đài Yokusuka có vẻ như là nơi giả câu đố về báu vật. Mọi người đã cùng lên thuyền tới nơi đó? Những nguy hiểm nào đang chờ đợi họ?!</p>', 'Full', 1, 'hoathinh', 'completed', 14, 1999, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Ryou Horikawa","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Toshiko Fujita","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Haruhiko Jo","avatar":""},{"name":"Fumio Matsuoka","avatar":""},{"name":"Mitsuru Miyamoto","avatar":""},{"name":"Yuko Miyamura","avatar":""},{"name":"Emi Shin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324535);
