INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nhan-toi-pham', 'Tình Nhân Tội Phạm', 'Criminal Lovers', 'https://phimimg.com/upload/vod/20240804-1/42087b581c1bbf4e58289d0ba691f57c.jpg', 'https://phimimg.com/upload/vod/20240804-1/0a0a00d1eddf7118f41165b9c84304c5.jpg', '<p>Sau một xung lực biến thái khiến họ phải giết người, Alice và bạn trai của cô, Luc, kéo xác vào rừng, rồi thấy mình lạc lối trong vô vọng – giống như hoàn cảnh trong truyện cổ tích của Hansel và Gretel. Đói khát và không còn hy vọng được tìm thấy, họ tình cờ đến một ngôi nhà nhỏ đổ nát, nơi một người đàn ông to lớn bắt họ làm tù nhân và tiến hành thỏa mãn ham muốn tình dục của Luc.</p>', 'Full', 1, 'single', 'completed', 11, 1999, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Natacha Régnier","avatar":""},{"name":"Jérémie Renier","avatar":""},{"name":"Miki Manojlović","avatar":""},{"name":"Salim Kéchiouche","avatar":""},{"name":"Yasmine Belmadi","avatar":""},{"name":"Bernard Maume","avatar":""},{"name":"Jean-Louis Debard","avatar":""},{"name":"Catherine Vierne","avatar":""},{"name":"Marielle Coubaillon","avatar":""},{"name":"Olivier Papot","avatar":""},{"name":"Gil Demurger","avatar":""},{"name":"Agnès Accaria","avatar":""},{"name":"Ranzi Adjeri","avatar":""},{"name":"Brigitte Albuquerque","avatar":""},{"name":"Martihino Albuque","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
