INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-bi-an', 'Án Mạng Bí Ẩn', 'Amazing Story', 'https://phimimg.com/upload/vod/20240611-1/64ba619b39c939d3c183bf497248c4e7.jpg', 'https://phimimg.com/upload/vod/20240611-1/80da93f4034d6ea14a4c511f7d2945e4.jpg', '<p><em>Diệp Ngọc Thụ là bác sĩ kiêm giảng viên y học tại viện y Thượng Hải, trái với vẻ ngoài rạng rỡ tươi sáng anh có một thân thế vô cùng đau thương. Trong thời gian anh làm việc tại nơi này liên tiếp xảy ra những vụ án mạng bị quỷ ám vô cùng kỳ bí; khiến nhà khoa học khoái chõ mũi vào chuyện của người khác - Bạch Nhất Phi, anh chàng cảnh sát trung trực Trần Trung Đạo và cô sinh viên y khoa lóng ngóng mới học nghề Hứa Như Nồng lập thành Đội Cảm Tử Truy Nã Ma Quỷ. Những con người này chậm rãi từng bước, từng bước vén lên bức màn bí ẩn thảm khốc. Từ thời điểm bắt đầu khi mọi người hoang mang tin rằng những người bị giết đều bị quỷ ám cho tới suốt hành trình phá án, những diễn biến tình cảm ràng buộc bế tắc cho tới cuối cùng khi sự thật phơi bày đều đầy ắp sự ly kỳ.</em></p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 14, 1999, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Trịnh Tắc Sĩ","avatar":""},{"name":"Lý Nhược Đồng","avatar":""},{"name":"Cảnh Lạc","avatar":""},{"name":"Nghiêm Khoan","avatar":""},{"name":"Trịnh Quốc Lâm","avatar":""},{"name":"Tư Cầm Cao Oa","avatar":""},{"name":"Chu Mạn","avatar":""},{"name":"Chương Tịnh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
