INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-den-nhi-do-6-song-thien-long-tranh-ho-dau', 'Nhất Đen Nhì Đỏ 6 -  Song Thiên Long Tranh Hổ Đấu', 'Who''s The Winner 6', 'https://phimimg.com/upload/vod/20240609-1/1bcf78ea344e64f59f436a67ac6f19fd.jpg', 'https://phimimg.com/upload/vod/20240609-1/290cfd44be6d4209adca6b77115c1ca8.jpg', '<p><em>Sau thành công vang dội của phần 5 trong seri Nhất Đỏ Nhì Đen và cũng là phần 1 của seri Canh Bạc Cuộc Đời, với sự thay đổi hoàn toàn về dàn diễn viên cũng như cốt truyện so với phần 4 khi mà nó được sản xuất bởi điện ảnh Singapore. Thừa thắng xông lên và Nhất Đỏ Nhì Đen 6 ra mắt với sự kỳ vọng lớn sẽ tiếp tục những gì mà bản ATV từng làm được. Ngoài cặp đôi ăn khách nhất của điện ảnh Singapore thời điểm đó là Lý Nam Tinh – Trịnh Huệ Ngọc vốn góp mặt từ phần trước thì phần này còn có sự tham gia của nam diễn viên nổi tiếng đến từ trung quốc và rất nổi tiếng tại Hồng Kông – Vu Vinh Quang.</em></p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 1999, 'Lồng Tiếng', 'HD', 'Singapore', 0, '[{"name":"Lý Nam Tinh","avatar":""},{"name":"Trịnh Huệ Ngọc","avatar":""},{"name":"Vũ Vinh Quang","avatar":""},{"name":"Tăng Giang","avatar":""},{"name":"Châu Sở Minh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324535);
