INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('inferno', 'Inferno', 'Inferno', 'https://phimimg.com/upload/vod/20231016-1/120aa73a90f8de1e5c875493b0c68eab.jpg', 'https://phimimg.com/upload/vod/20231016-1/5644d933152b8bed2cc245147fcc209e.jpg', '<p>Eddie Lomax (Jean-Claude Van Damme) là một người lang thang đã có ý định tự tử kể từ cái chết của người bạn thân Johnny (Danny Trejo). Lái chiếc mô tô của mình vào một thị trấn sa mạc nhỏ nơi Johnny từng sống, Lomax phải đối mặt với một nhóm côn đồ, những kẻ đã đánh anh và cướp chiếc xe đạp của anh. Tuy nhiên, Lomax không phải là người chấp nhận sự bất công, và ngay sau đó anh ta bắt đầu thực hiện một cuộc trả thù bạo lực đối với những người đàn ông đã lấy trộm xe máy của anh ta, với người giúp việc địa phương Jubal Early (Pat Morita) giúp một tay và một số phụ nữ trong khu vực đề nghị giúp đỡ và an ủi. .</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Pat Morita","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Gabrielle Fitzpatrick","avatar":""},{"name":"Larry Drake","avatar":""},{"name":"Vincent Schiavelli","avatar":""},{"name":"David \"Shark\" Fralick","avatar":""},{"name":"Silas Weir Mitchell","avatar":""},{"name":"Jonathan Avildsen","avatar":""},{"name":"Jaime Pressly","avatar":""},{"name":"Bill Erwin","avatar":""},{"name":"Ford Rainey","avatar":""},{"name":"Kevin West","avatar":""},{"name":"Priscilla Pointer","avatar":""},{"name":"Robert","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324535);
