INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('digimon-1999', 'Digimon 1999', 'Digimon Adventure (1999)', 'https://phimimg.com/upload/vod/20240302-1/82cd714459907392597dbb5a318d9c04.jpg', 'https://phimimg.com/upload/vod/20240302-1/657f34f1be5b4116d46d39756e1bb35d.jpg', '<p>Vào thời cổ đại, đã có một cuộc chiến tranh quy mô lớn giữa các Digimon ánh sáng và bóng tối trong Thế giới kỹ thuật số, và sự cân bằng bắt đầu bị phá vỡ. Các Digimon từ xa xưa đã tập hợp lại với nhau để đẩy lùi thế lực đen tối, nhưng vẫn bị xóa sổ. Giờ đây, các thế lực đen tối mới lại đang xâm chiếm Thế giới số và thế giới thực được kết nối thông qua Internet. Vì vậy, một số trẻ em đã được chọn để đánh thức linh hồn của các Digimon cổ đại, và hướng dẫn họ chinh phục thế giới vô cực.</p>', 'Hoàn Tất (54/54)', 54, 'hoathinh', 'completed', 14, 1999, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324536);
