INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('secret', 'Secret', 'Secret', 'https://phimimg.com/upload/vod/20240228-1/ef61ad8b1e47d2a2ece05f620689cf1f.jpg', 'https://phimimg.com/upload/vod/20240228-1/15668ec6bb2c28d95687dff83c3bfb56.jpg', '<p>Himitsu là một bộ phim lãng mạn giả tưởng của Nhật Bản năm 1999 do Yōjirō Takita đạo diễn, với sự tham gia của Ryōko Hirosue, Kaoru Kobayashi và Kayoko Kishimoto và dựa trên tiểu thuyết Naoko của Keigo Higashino. Nó được phát hành vào ngày 25 tháng 9 năm 1999. Bản làm lại bằng tiếng Anh bằng tiếng Pháp, The Secret, được phát hành vào năm 2007.</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Hirosue Ryoko","avatar":""},{"name":"Kaoru Kobayashi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
