INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-tren-doi-quy-am', 'Ngôi Nhà Trên Đồi Quỷ Ám', 'House On Haunted Hill', 'https://phimimg.com/upload/vod/20240205-1/d1dc0069f8a1c272cdfb9fead9bac4e3.jpg', 'https://phimimg.com/upload/vod/20240205-1/9bedc4d3d1a61b6b3d2b1b1194e65b89.jpg', '<p>Nỗi sợ hãi tưởng chừng như vô hại khi một nhóm gồm 5 người nọ cùng tham gia vào chương trình thú vị với phần thưởng là một triệu đô la cho ai có thể ở lại qua đêm và còn sống sót trong ngôi nhà được đồn đại là có ma. Thế nhưng, cái đêm mà bọn họ ở lại ngôi nhà kia nhanh chóng trở thành một đêm kinh hoàng… Một năm sau đó, một nhóm người khác liều lĩnh tiến hành tìm kiếm bức tượng đáng nguyền rủa của Baphomet – một di vật có trị giá hàng triệu đô la. Giờ đây, sự kinh hoàng tiếp tục theo chân các linh hồn bị nguyền rủa quay trở lại</p>', 'Full', 1, 'single', 'completed', 12, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Geoffrey Rush","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Taye Diggs","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324536);
