INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-thanh', 'Dấu Thánh', 'Stigmata', 'https://phimimg.com/upload/vod/20240124-1/14f22e6d67f4e8995ae0540a9abbd5ba.jpg', 'https://phimimg.com/upload/vod/20240124-1/8f09017822f83b7f735d91c05ad0c0e0.jpg', '<p>Một phụ nữ trẻ không có niềm tin tôn giáo mạnh mẽ, Frankie Paige bắt đầu có những trải nghiệm kỳ lạ và bạo lực, cho thấy dấu hiệu của những vết thương mà Chúa Giêsu đã nhận được khi bị đóng đinh. Khi Vatican biết được tình hình của Frankie, một hồng y cấp cao đã yêu cầu Mục sư Andrew Kiernan điều tra trường hợp của cô. Chẳng bao lâu sau, Kiernan nhận ra rằng các thế lực rất nham hiểm đang hoạt động và cố gắng giải cứu Frankie khỏi thực thể đang gây khó chịu cho cô.</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patricia Arquette","avatar":""},{"name":"Gabriel Byrne","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Nia Long","avatar":""},{"name":"Thomas Kopache","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324536);
