INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-chay-tron-1999', 'Cô Dâu Chạy Trốn', 'Runaway Bride', 'https://phimimg.com/upload/vod/20240123-1/1fec536df24a5dab4db6fa2c33a78f45.jpg', 'https://phimimg.com/upload/vod/20240123-1/62f788b8add073a6ae3ba72b106f8088.jpg', '<p>Ike Graham, nhà bình luận ở New York, luôn viết bài của mình vào phút cuối. Lần này, một người đàn ông say xỉn trong quán bar yêu thích của anh ta kể cho Ike nghe về Maggie Carpenter, một người phụ nữ luôn chạy trốn khỏi những chú rể của mình trong thời khắc cuối cùng có thể. Ike, dù sao cũng không có quan điểm tốt nhất về phụ nữ, đã viết một chuyên mục xúc phạm mà không nghiên cứu kỹ về chủ đề này.</p>', 'Full', 1, 'single', 'completed', 11, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julia Roberts","avatar":""},{"name":"Richard Gere","avatar":""},{"name":"Joan Cusack","avatar":""},{"name":"Hector Elizondo","avatar":""},{"name":"Rita Wilson","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324536);
