INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-doan-ket', 'Gia Đình Đoàn Kết', 'Hum Saath-Saath Hain', 'null', 'https://phimimg.com/upload/vod/20240207-1/a76c6583eada20a84cac54ae0558693a.jpg', '<p>Có suy nghĩ sai lệch, một bà mẹ âm mưu không cho hai vợ chồng đứa con trai riêng được chia phần gia sản, tạo nên sự chia rẽ trong gia tộc đã từng hạnh phúc, gắn bó.</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Salman Khan","avatar":""},{"name":"Karisma Kapoor","avatar":""},{"name":"Saif Ali Khan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
