INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-bao-tim', 'Cơn Bão Tím', 'Purple Storm', 'https://phimimg.com/upload/vod/20240111-1/3c01d332303faa5204ee5dbe1e23efb7.jpg', 'https://phimimg.com/upload/vod/20240111-1/a405ad67e7fc52380eeeae48107471b0.jpg', '<p>Cơn Bão Tím - Purple Storm xoay quanh Soong, một tên khủng bố Khmer Đỏ với kế hoạch gieo rắc mây mù bằng vũ khí hóa học Ricin-X, gửi con trai mình, Todd Nguyễn và bạn của anh ta, Guan Ai, đến Hồng Kông trên một con tàu của Triều Tiên. Trên tàu là một thùng chứa chất độc chết người, mà người Triều Tiên cử một đội ám sát đi lấy. Những người Triều Tiên bị giết và Todd bị đánh bất tỉnh. Cảnh sát chiến thuật biển Hồng Kông đáp trả, buộc Guan đổ thùng hàng lên tàu trong khi chạy trốn; trong khi trốn thoát, Guan đã lãng phí cơ hội để giết Todd.</p>', 'Full', 1, 'single', 'completed', 12, 1999, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Ngạn Tổ","avatar":""},{"name":"Châu Hoa Kiện","avatar":""},{"name":"Hà Siêu Nghi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324536);
