INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-ao-giac', 'Ký Ức Ảo Giác', 'Stir Of Echoes', 'https://phimimg.com/upload/vod/20231231-1/38166c5347f150438024e7dc3cad2fe2.jpg', 'https://phimimg.com/upload/vod/20231231-1/01500bfb2d4994716e54f250c3583eb4.jpg', '<p>Ký Ức Ảo Giác - Stir of Echoes là một phim kinh dị siêu nhiên Mỹ 1999 của đạo diễn David Koepp. Tom Witzky (Kevin Bacon) là một chàng trai thuộc tầng lớp lao khá điển hình sống ở Chicago. Tom bị người em dâu thôi miên và anh ta cảm nhận được một điều khủng khiếp trong ngôi nhà của mình và tin rằng ngôi nhà là nơi ma quỷ ẩn nấp. Tom bắt đầu rơi vào tuyệt vọng và những gì diễn ra xung quanh có thể đe dọa đến tính mạng của anh.</p>', 'Full', 1, 'single', 'completed', 14, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Bacon","avatar":""},{"name":"Zachary David Cope","avatar":""},{"name":"Kathryn Erbe","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324536);
