INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-nui-do-con-nguoi-do-con-cho-do', 'Ngọn Núi Đó, Con Người Đó, Con Chó Đó', 'Na Shan Na Ren Na Gou', 'https://phimimg.com/upload/vod/20240102-1/9737734f249402f406bb839156239827.jpg', 'https://phimimg.com/upload/vod/20240102-1/666800f338fbfa5225a8336a98243f48.jpg', '<p>Một người đưa thư già đã dành cả cuộc đời mình để đưa thư đến vùng núi Hồ Nam và sắp nghỉ hưu. Con trai duy nhất của ông sẽ đảm nhận nhiệm vụ của ông. Khi hai cha con hành trình xuyên núi, người con trai bắt đầu hiểu rõ sự vất vả và gánh nặng mà cha anh phải gánh khi làm người đưa thư cho dân làng, và người đưa thư già cũng vô cùng xúc động khi con trai kể lại nỗi lo lắng của mẹ mình khi bà chờ đợi anh. trở về nhà sau mỗi chuyến đi.</p>', 'Full', 1, 'single', 'completed', 15, 1999, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hao Chen","avatar":""},{"name":"Eddie Eagle","avatar":""},{"name":"Ye Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
