INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh-giua-cac-vi-sao-1-hiem-hoa-cua-bong-ma', 'Chiến Tranh Giữa Các Vì Sao 1: Hiểm Họa Của Bóng Ma', 'Star Wars: Episode I - The Phantom Menace', 'https://phimimg.com/upload/vod/20231231-1/f79d00aa8795807bd6fd771db9cb0ca2.jpg', 'https://phimimg.com/upload/vod/20231231-1/a6e834320fcb30cfb8cfd2760c34bb77.jpg', '<p>Naboo, một hành tinh yên bình dưới sự trị vì của nữ hoàng trẻ và sáng suốt Amidala, đang bị đe doạ bởi phái Trade Federation, những hình nộm che mắt cho chúa tể Sith và đệ tử của hắn, Darth Maul. Thống đốc Palpatine là quân sư chính cho nữ hoàng, cho dù có nhiều nghi ngờ xung quanh ông. Hiệp sĩ Jedi Qui-Gon Jinn và Obi-Wan Kenobi được gọi đến để can thiệp vào cuộc hỗn chiến này. Trên đường đi, họ thu nhận thêm đệ tử Anakin Skywalker, người sau này trở thành Darth Vader...</p>', 'Full', 1, 'single', 'completed', 14, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Natalie Portman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324536);
