INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ley-lines', 'Ley Lines', 'Ley Lines', 'https://phimimg.com/upload/vod/20240121-1/a0bdd60e4ed5cb5dc4868ef612635492.jpg', 'https://phimimg.com/upload/vod/20240121-1/dbeae35740e8d1a9174942485e08c3c3.jpg', '<p>Câu chuyện kể về một bộ ba thanh niên Nhật Bản gốc Trung Quốc trốn thoát khỏi cuộc sống ở vùng bán nông thôn và chuyển đến Shinjuku, Tokyo, nơi họ kết bạn với một cô gái điếm Thượng Hải gặp rắc rối và rơi vào tầm ngắm của một tổ chức tội phạm địa phương. Giống như nhiều tác phẩm khác của Miike, bộ phim xem xét khía cạnh tiềm ẩn của xã hội Nhật Bản đáng kính và các vấn đề đồng hóa mà những người Nhật không thuộc sắc tộc phải đối mặt ở Nhật Bản.</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Kazuki Kitamura","avatar":""},{"name":"Dan Li","avatar":""},{"name":"Michisuke Kashiwaya","avatar":""},{"name":"Tomorowo Taguchi","avatar":""},{"name":"Naoto Takenaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324536);
