INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-truyen-tin-cua-chua', 'Người Truyền Tin Của Chúa', 'The Messenger: The Story Of Joan Of Arc', 'https://phimimg.com/upload/vod/20231230-1/eda8c29f2d8ae1a311fe0f3d211f96c8.jpg', 'https://phimimg.com/upload/vod/20231230-1/6ca66f7e6761dcdae796225a3746ddc1.jpg', '<p>Phim lấy bối cảnh lịch sử nước Pháp thế kỉ 15, trong cuộc chiến tranh chống nước Anh. Nước Pháp lúc đó chỉ còn vài thủ phủ là theo Pháp. Vua nước Pháp thì chưa đăng quang, tướng nước Pháp thì thua trận liên miên, quí tộc Pháp thì bị mua chuộc. Trong một ngôi làng nhỏ, nơi mà nước Pháp vẫn còn ngự trị, một cô gái nhỏ tên Joan tin rằng mình được Chúa giao phó nhiệm vụ giải phóng nước Pháp. Trong lúc đi từ nhà thờ về nhà cô nhìn thấy quân Anh bắt đầu đốt ngôi làng của cô. Sống sót sau cuộc tấn công của quân Anh cô đem lòng hận thù. Khi lớn lên, cô may mắn quen được hai người bạn, người đã tin cô được gửi xuống bởi Chúa khi cô đoán trước được những thứ mà người khác không biết...</p>', 'Full', 1, 'single', 'completed', 12, 1999, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Rab Affleck","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324536);
