INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-gian-doan', 'Cô Gái, Gián Đoạn', 'Girl, Interrupted', 'https://phimimg.com/upload/vod/20231227-1/e2dd9ce96ae57a6429122cddfcdb3edf.jpg', 'https://phimimg.com/upload/vod/20231227-1/f0b95cd7c7320fecfe771132bbcdf28a.jpg', '<p>Lấy bối cảnh thế giới đang thay đổi vào cuối những năm 1960, thời gian nghỉ ngơi ngắn theo chỉ định của Susanna Kaysen từ một bác sĩ tâm lý mà cô chỉ gặp một lần trở thành một chuyến hành trình kỳ lạ, vô định vào Alices Wonderland, nơi cô đấu tranh với ranh giới mỏng manh giữa bình thường và điên rồ. đó là thoát ra khi cô ấy đã cam kết, và cuối cùng cô ấy phải lựa chọn giữa thế giới của những người thuộc về bên trong hay thế giới thực tế khó khăn bên ngoài.</p>', 'Full', 1, 'single', 'completed', 23, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Winona Ryder","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Brittany Murphy","avatar":""},{"name":"Clea DuVall","avatar":""},{"name":"Elisabeth Moss","avatar":""},{"name":"Whoopi Goldberg","avatar":""},{"name":"Vanessa Redgrave","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Travis Fine","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
