INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-troi-va-canh-vien', 'Mặt Trời Và Cảnh Viên', 'Sunshine Cops', 'https://phimimg.com/upload/vod/20231215-1/efc815c79937f7376c229fe87d186cfb.jpg', 'https://phimimg.com/upload/vod/20231215-1/2ae50403bb2db487e27c6f643cd20619.jpg', '<p>Phim Mặt Trời Và Cảnh Viên thuộc phim hành động, hình sự của trung quốc xoay quanh các viên cảnh sát...</p>', 'Full', 1, 'single', 'completed', 12, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Phùng Đức Luân","avatar":""},{"name":"Trương Trí Nghiêu","avatar":""},{"name":"Angelica Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324536);
