INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-nguoi-cung-khong-the-thieu', 'Một Người Cũng Không Thể Thiếu', 'Not One Less', 'https://phimimg.com/upload/vod/20231211-1/9337fab4e51dee3842fac6570261cc2c.jpg', 'https://phimimg.com/upload/vod/20231211-1/41fc458b2c83294db543280f30b4baa3.jpg', '<p>Thầy Gao yêu những học sinh trong ngôi làng nghèo của mình và tận tâm giáo dục chúng với hy vọng chúng có tương lai tốt đẹp hơn. Khi anh ta được gọi đi chăm sóc người mẹ đang hấp hối của mình trong một tháng, Thị trưởng gọi một người thay thế 13 tuổi thiếu kinh nghiệm, Wei Minzhi; khiến Giáo viên Gao mất tinh thần. Giáo viên Gao không thể chịu đựng được ý nghĩ mất thêm học sinh nữa: ông ấy đã mất 12 học sinh vì mức độ tiêu hao ngày càng tăng, và ông ấy hứa với Wei thêm 10 nhân dân tệ nếu cô ấy thành công trong việc đảm bảo rằng khi ông ấy trở lại, sẽ không bớt một học sinh nào. Nhiệm vụ khó khăn của Wei để thực hiện mong muốn của cô giáo Gao và mối quan tâm của chính cô đối với phúc lợi của trẻ em bắt đầu.</p>', 'Full', 1, 'single', 'completed', 14, 1999, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Wei Minzhi","avatar":""},{"name":"Zhang Huike","avatar":""},{"name":"Tian Zhenda","avatar":""},{"name":"Gao Enman","avatar":""},{"name":"Sun Zhimei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
