INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-vu-tru-tai-xuat', 'Chiến Binh Vũ Trụ: Tái Xuất', 'Universal Soldier: The Return', 'https://phimimg.com/upload/vod/20231212-1/365876906c37164be58e0c4e3a18551b.jpg', 'https://phimimg.com/upload/vod/20231212-1/6312028a7470ba4ef2ca25c299a20f8a.jpg', '<p>Luc Deveraux là thành viên sống sót duy nhất của Đội chiến binh vũ trụ cũ và hiện anh đang làm việc cho Dylan Cotner - người có kế hoạch và dự án nhằm tạo nên Đội chiến binh vũ trụ mới, kế hoạch đó được kiểm soát bởi siêu máy tính tên SETH. Khi Chính phủ quyết định kết thúc dự án bao gồm cả việc shutdown hệ thống SETH thì chính là lúc cỗ siêu máy tính trở nên thông minh không muốn điều này và tiến hành các bước ngăn chặn: giết Dylan, chuyển thể mình sang một con người, tiêu diệt Luc - người duy nhất có thể biết mã số bí mật để dừng SETH.</p>', 'Full', 1, 'single', 'completed', 15, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Bill Goldberg","avatar":""},{"name":"Heidi Schanz","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324536);
