INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jacob-ke-noi-doi', 'Jacob Kẻ Nói Dối', 'Jakob The Liar', 'https://phimimg.com/upload/vod/20231211-1/8eb2575902515c4c8a92e47955e99a7c.jpg', 'https://phimimg.com/upload/vod/20231211-1/7d4b4fb9ec915e85239427e7e42187bb.jpg', '<p>Năm 1944 ở Ba Lan, một chủ cửa hàng người Do Thái tên là Jakob được triệu tập đến trụ sở khu ổ chuột sau khi bị bắt sau giờ giới nghiêm. Trong khi chờ đợi Kommondant của Đức, Jakob tình cờ nghe được một đài phát thanh của Đức về các hoạt động chuyển quân của Nga. Trở lại khu ổ chuột, người chủ cửa hàng chia sẻ thông tin của mình với một người bạn và sau đó có tin đồn rằng có một đài phát thanh bí mật trong khu ổ chuột.</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Armin Mueller-Stahl","avatar":""},{"name":"Hannah Taylor-Gordon","avatar":""},{"name":"Éva Igó","avatar":""},{"name":"István Bálint","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
