INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-cha-vi-dai', 'Người Cha Vĩ Đại', 'Big Daddy', 'https://phimimg.com/upload/vod/20231211-1/18db83fc26901b8ff45743212819aa50.jpg', 'https://phimimg.com/upload/vod/20231211-1/9bc5b28d32117f82e773032615db8dc4.jpg', '<p>Sonny Koufax (Adam Sandler) là một anh chàng lười biếng vô công rồi nghề mặc dù đã tốt nghiệp chuyên ngành luật tại New York. Sau vụ kiện một chiếc xe cán vào chân anh, Sonny đã thắng kiện với số tiền bồi thường 200.000 USD và sống ung dung với món tiền này. Sự vô tâm cẩu thả của anh khiến cô người yêu Vanessa (Kristy Swanson) ngán lên tận cổ và có ý định chia tay. Mọi việc có nguy cơ không thể cứu vãn nổi nếu không có sự xuất hiện của một cậu nhóc mới 5 tuổi tên là Julian (Cole Sprouse). Một ngày nọ, trước của nhà Sonny xuất hiện một cậu bé với mảnh giấy nhắn để lại. Cậu bé xưng tên là Julian, sự thực cậu chính là con trai của anh bạn cùng phòng Sonny (John Steward). Lúc đó, anh bạn kia đi công tác xa nhà. Sonny bối rối không biết xử lý cậu bé này thế nào cả. Anh đưa Julian đến dịch vụ xã hội, nhưng không may dịch vụ đóng cửa nhân ngày Columbus, cực chẳng đã, Sonny đành đưa cậu bé về nhà và mọi câu chuyện cảm động bắt đầu từ đây.</p>', 'Full', 1, 'single', 'completed', 15, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Joey Lauren Adams","avatar":""},{"name":"Kristy Swanson","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324536);
