INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-trai-khong-khoc', 'Con Trai Không Khóc', 'Boys Don''t Cry', 'https://phimimg.com/upload/vod/20231211-1/df4616a64994e5909849a098f3e5686c.jpg', 'https://phimimg.com/upload/vod/20231211-1/97684c23c77e45de5e81935423dc7f08.jpg', '<p>Một người đàn ông chuyển giới trẻ khám phá bản dạng giới của mình và tìm kiếm tình yêu ở vùng nông thôn Nebraska.</p>', 'Full', 1, 'single', 'completed', 15, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hilary Swank","avatar":""},{"name":"Chloë Sevigny","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Brendan Sexton III","avatar":""},{"name":"Alicia Goranson","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
