INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tra-lai-tinh-yeu-cho-em', 'Trả Lại Tình Yêu Cho Em', 'My Heart Will Go On', 'https://phimimg.com/upload/vod/20231211-1/d0897c5576c8446f5503dbc83033f496.jpg', 'https://phimimg.com/upload/vod/20231211-1/85260f518bc6dc2dd6a18044a65a5c59.jpg', '<p>Bộ phim Trả Lại Tình Yêu Cho Em - My Heart Will Go On xoay quanh một sát thủ chuyên nghiệp tên Leo, người muốn gác kiếm sau những năm tháng trong nghề cũng như lương tâm không cho phép anh tiếp tục làm sát thủ nữa. Tuy nhiên, anh ta bỏ công việc này đồng nghĩa với việc phản bội tổ chức của mình. Vì vậy, anh bị tổ chức tìm cách trừ khử. Sau đó anh đã sóng sót nhờ được hiến tim của một vị cảnh sát. Nhưng trớ trêu thay, anh đã có có kí ức của viên cảnh sát đó và cả vị hôn thê của anh ta.</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Kỳ Long","avatar":""},{"name":"Ngô Khải Hoa","avatar":""},{"name":"Thái Thiếu Phấn","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324536);
