INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-thu-ma-am', 'Biệt Thự Ma Ám', 'The Haunting', 'https://phimimg.com/upload/vod/20231211-1/8799cd3ec537962c96ac2a1d4f8f45b9.jpg', 'https://phimimg.com/upload/vod/20231211-1/8393329793158178254560d0d7a95222.jpg', '<p>Sau khi mẹ qua đời, Eleanor Vance, thường được gọi là Nell, bị chị gái Jane đuổi khỏi nhà. Không có việc làm, cô quyết định tham gia một thử nghiệm về chứng mất ngủ để kiếm mức thù lao 900 USD/tuần. Người chỉ đạo chương trình thử nghiệm là tiến sĩ David Marrow. Thử nghiệm sẽ diễn ra ở Hill House, một lâu đài đẹp nhưng được cho là có ma ở vùng nông thôn Massachusetts. Cùng tham gia với Nell còn có Theo và Luke Sanderson. Cả ba người không hề biết rằng tiến sĩ David tiến hành thử nghiệm với mục đích kiểm tra chứng cuồng loạn và sợ hãi ở cấp độ nhóm, chứ không phải chứng mất ngủ. Trong đêm đầu tiên, ông ta kể cho các tình nguyện viên về lịch sử của lâu đài Hill House. Một nhà tài phiệt thời kỳ Cách mạng công nghiệp tên Hugh Crane đã xây dựng lâu đài này cho bà vợ, Renee. Tuy nhiên, công trình chưa hoàn thành thì Renee qua đời. Về sau Hugh mới biết rằng vợ ông treo cổ tự tử trên một ban công ở ngôi nhà nghỉ ngoài vườn. Từ đó, nhiều hiện tượng kỳ lạ bắt đầu xảy ra...</p>', 'Full', 1, 'single', 'completed', 17, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"Bruce Dern","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324536);
