INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('biet-thu-ma-am', 'Biệt Thự Ma Ám', 'The Haunting', 'biệt thự ma ám the haunting liam neeson catherine zeta-jones owen wilson lili taylor bruce dern ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-tuyet-mat-phan-7', 'Hồ Sơ Tuyệt Mật (Phần 7)', 'The X-Files (Season 7)', 'https://phimimg.com/upload/vod/20231219-1/6cf748c716430e2dd5675c502cbbe06f.jpg', 'https://phimimg.com/upload/vod/20231219-1/4ed2306a321a8a67957f61f831aad845.jpg', '<p>Khi Mulder nằm trong một đơn vị thần kinh, não của anh ta bị tấn công bởi một xung điện chết người, Scully phải vật lộn để giải mã các ký hiệu kỳ lạ bao phủ một con tàu vũ trụ được tìm thấy dưới đáy biển Bờ Biển Ngà của Tây Phi. Nhưng mối liên hệ giữa hai hiện tượng này chỉ là thách thức đầu tiên trong số nhiều thách thức mà các đặc vụ phải đối mặt. Vì họ sắp bước vào thời điểm kết thúc và thời điểm bắt đầu mới. Đối với Mulder, đó là cái chết của mẹ anh và Diana Fowley, cũng như việc anh tìm kiếm người em gái bị bắt cóc, Samantha. Đối với Scully, đây là lúc phải đối mặt với những con quỷ của chính cô ấy, trong số đó có sự trở lại của kẻ tôn sùng cái chết Donnie Pfaster. Tuy nhiên, ngay khi Scully đối mặt với khởi đầu mới cuối cùng, điều kinh hoàng cuối cùng xảy ra - vụ bắt cóc Mulder.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 12, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Duchovny","avatar":""},{"name":"Gillian Anderson","avatar":""},{"name":"Mitch Pileggi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324536);
