INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lich-su-apple-va-microsoft', 'Lịch Sử Apple Và Microsoft', 'Pirates Of Silicon Valley', 'https://phimimg.com/upload/vod/20231210-1/7b56723a8a1914b87b69cdf0a13556d2.jpg', 'https://phimimg.com/upload/vod/20231210-1/e8432ccb2705900c9f9f6235a7bc52b2.jpg', '<p>Câu chuyện về những người đàn ông đã tạo nên thế giới công nghệ như ngày nay, cuộc đấu tranh của họ trong thời gian học đại học, việc thành lập công ty của họ và những hành động tài tình mà họ đã thực hiện để xây dựng các đế chế công ty toàn cầu của Apple Computer Inc. và Tập đoàn Microsoft.</p>', 'Full', 1, 'single', 'completed', 16, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Noah Wyle","avatar":""},{"name":"Anthony Michael Hall","avatar":""},{"name":"Joey Slotnick","avatar":""},{"name":"J.G. Hertzler","avatar":""},{"name":"Wayne Pére","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
