INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-tam-xuong', 'Kẻ Tầm Xương', 'The Bone Collector', 'https://phimimg.com/upload/vod/20231209-1/bdf3a9221ed7369ff2752b3bcfeb7d27.jpg', 'https://phimimg.com/upload/vod/20231209-1/7e1a7d3b005107550814a1d6a103b86a.jpg', '<p>Hàng loạt vụ giết người man rợ xảy ra tại New York. Sau khi rạch nhiều nhát dao và để nạn nhân làm mồi cho lũ chuột, kẻ thủ ác luôn cố tình để lại chỉ dẫn về địa điểm sẽ xảy ra vụ án mạng tiếp theo. Một cuộc đấu trí căng thẳng xảy ra giữa Lincoln Rhyme - sĩ quan điều tra giỏi nhất thành phố nhưng bị liệt toàn thân, nữ cảnh sát xinh đẹp Amelia Donaghy và kẻ thủ ác, liệu công lý có được thực thi?</p>', 'Full', 1, 'single', 'completed', 17, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Queen Latifah","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Leland Orser","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324536);
