INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('7-vien-ngoc-rong-gt', '7 Viên Ngọc Rồng GT', 'Dragon Ball GT', 'https://phimimg.com/upload/vod/20231207-1/c3facfb1c35b2d46532f0627cffad3bb.jpg', 'https://phimimg.com/upload/vod/20231207-1/24098b5236e83a9414dbd31967d10bdf.jpg', '<p>Pilaf cuối cùng cũng có trong tay những viên Ngọc rồng Black Star sau nhiều năm tìm kiếm, thứ được cho là mạnh gấp đôi những viên ngọc bình thường của Trái đất. Pilaf đang chuẩn bị thực hiện ước nguyện thống trị thế giới thì bị Gokuu Son làm gián đoạn. Do đó, Pilaf từ chối điều ước của mình và vô tình biến Gokuu trở lại thành một đứa trẻ. Sau khi điều ước được thực hiện, các viên Ngọc Rồng Sao Đen phân tán khắp thiên hà. Tuy nhiên, Gokuu phát hiện ra rằng chúng sẽ khiến Trái đất nổ tung trừ khi tất cả chúng được tập hợp lại trong vòng một năm. Cùng với với cháu gái Pan và một thanh niên Trunks, Gokuu bắt đầu một cuộc phiêu lưu xuyên vũ trụ để tìm các viên Ngọc Rồng Sao Đen và cứu hành tinh của mình khỏi sự hủy diệt.</p>', 'Hoàn Tất (64/64)', 64, 'hoathinh', 'completed', 16, 1999, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324536);
