INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-trom-hoan-hao', 'Tay Trộm Hoàn Hảo', 'The Thomas Crown Affair', 'https://phimimg.com/upload/vod/20231204-1/2fd86827a7fe8e5b4fe1d2db9e7ba80c.jpg', 'https://phimimg.com/upload/vod/20231204-1/bb9c6e4bd5686b1b6993e9a6ec4dc933.jpg', '<p>Ở thành phố New York, triệu phú trẻ Thomas Crown nổi tiếng vì sự giàu có, lịch lãm, hiểu biết và thói chơi ngông. Anh từng đánh đắm một du thuyền sang trọng hoặc cá cược hàng trăm nghìn USD cho một cú đánh golf chỉ để ghi nhớ một buổi sáng thứ bảy đẹp trời. Chẳng mấy ai biết chính xác Thomas kinh doanh trong lĩnh vực nào, nhưng các nhân viên trong Viện bảo tàng nghệ thuật thành phố thì cho rằng anh sở hữu một công ty kinh doanh bất động sản lớn và là chuyên gia sừng sở trong lĩnh vực mua bán các công ty. Sở dĩ các nhân viên ở Viện bảo tàng nghệ thuật biết rõ Thomas vì anh thường xuyên tới đây để chiêm ngưỡng một bức tranh thuộc trường phái Ấn tượng. Bobby McKinley, người quản lý phòng trưng bày tranh Ấn tượng, ...</p>', 'Full', 1, 'single', 'completed', 12, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Rene Russo","avatar":""},{"name":"Denis Leary","avatar":""},{"name":"Ben Gazzara","avatar":""},{"name":"Frankie Faison","avatar":""},{"name":"Fritz Weaver","avatar":""},{"name":"Charles Keating","avatar":""},{"name":"Mark Margolis","avatar":""},{"name":"Faye Dunaway","avatar":""},{"name":"Michael Lombard","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
