INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-boondock-saints', 'The Boondock Saints', 'The Boondock Saints', 'https://phimimg.com/upload/vod/20231203-1/ab7474cd0d04d94dca1e83413951cab4.jpg', 'https://phimimg.com/upload/vod/20231203-1/e35c6537ea20f7ade1ab86db31a1b8d8.jpg', '<p>Mệt mỏi với tội ác hoành hành khắp các đường phố ở Boston, hai anh em song sinh Công giáo Ireland là Conner và Murphy được truyền cảm hứng bởi đức tin của họ để tẩy sạch tội ác quê hương của họ với thương hiệu của riêng họ về công lý nhiệt thành cảnh giác. Khi họ truy lùng và giết hết tên xã hội đen khét tiếng này đến kẻ khác, họ trở thành những anh hùng dân gian gây tranh cãi trong cộng đồng. Nhưng Paul Smecker, một đặc vụ FBI lập dị, đang nhanh chóng đi vào dấu vết đẫm máu của họ.</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Patrick Flanery","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Norman Reedus","avatar":""},{"name":"David Della Rocco","avatar":""},{"name":"David Ferry","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324536);
