INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tra-thu-kieu-anh', 'Trả Thù Kiểu Anh', 'The Limey', 'https://phimimg.com/upload/vod/20231204-1/d6de39316bdaffea403294e0213f1c69.jpg', 'https://phimimg.com/upload/vod/20231204-1/221a6c56892e5ab1a973a2c4d3392d72.jpg', '<p>Ngay sau khi nghe tin con gái mình bị giết chết, Wilson từng là tội phạm khét tiếng ở Anh đã lên đường tới Mỹ để trả thù cho con gái mình. Liệu ông có tìm được hung thủ?</p>', 'Full', 1, 'single', 'completed', 15, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Terence Stamp","avatar":""},{"name":"Lesley Ann Warren","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Barry Newman","avatar":""},{"name":"Joe Dallesandro","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324536);
