INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giay-phut-doat-menh', 'Giây Phút Đoạt Mệnh', 'Running Out Of Time', 'https://phimimg.com/upload/vod/20231129-1/16c3914c991c7ec3c6dcce904759df5e.jpg', 'https://phimimg.com/upload/vod/20231129-1/f98d11e3a02234cdafeb55fcb46d65c9.jpg', '<p>Tên cướp chẳng còn nhiều thời gian, nên hắn quyết định chơi một trò chơi với Cảnh sát Hong Kong trong 72 giờ tới bằng cách tiến hành một vụ cướp nữ trang và bắt con tin ngoạn mục. Trong quá trình truy đuổi hắn, viên cảnh sát và tên cướp trở thành bạn và cùng nhau chiến đấu với một băng đảng tội phạm.</p>', 'Full', 1, 'single', 'completed', 14, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Yoyo Mung","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Shiu-Hung Hui","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Ruby Wong Cheuk-Ling","avatar":""},{"name":"Hung Wai-Leung","avatar":""},{"name":"Oscar Lam Wai-Kin","avatar":""},{"name":"Jimmy Wong Wa-Wo","avatar":""},{"name":"Lee Sau-Kei","avatar":""},{"name":"Ai Wai","avatar":""},{"name":"Paco Yick Tin-Hung","avatar":""},{"name":"Yau Man-Shing","avatar":""},{"name":"Jerome Fung","avatar":""},{"name":"Li Man-Chun","avatar":""},{"name":"Wong Yui-Sang","avatar":""},{"name":"Ch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324536);
