INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-ao-giac-1999', 'Ký Ức Ảo Giác', 'Stir of Echoes', 'https://phimimg.com/upload/vod/20231116-1/792d51dc02dc39dcc5154dc80f0f367c.jpg', 'https://phimimg.com/upload/vod/20231116-1/caee7128ada79762c2a0eb676a51e7ac.jpg', '<p>Ký Ức Ảo Giác - Stir of Echoes là một phim kinh dị siêu nhiên Mỹ 1999 của đạo diễn David Koepp. Tom Witzky (Kevin Bacon) là một chàng trai thuộc tầng lớp lao khá điển hình sống ở Chicago. Tom bị người em dâu thôi miên và anh ta cảm nhận được một điều khủng khiếp trong ngôi nhà của mình và tin rằng ngôi nhà là nơi ma quỷ ẩn nấp. Tom bắt đầu rơi vào tuyệt vọng và những gì diễn ra xung quanh có thể đe dọa đến tính mạng của anh.</p>', 'Full', 1, 'single', 'completed', 15, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Bacon","avatar":""},{"name":"Kathryn Erbe","avatar":""},{"name":"Illeana Douglas","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Conor O''Farrell","avatar":""},{"name":"Lusia Strus","avatar":""},{"name":"Zachary David Cope","avatar":""},{"name":"Stephen Eugene Walker","avatar":""},{"name":"Mary Kay Cook","avatar":""},{"name":"Larry Neumann Jr.","avatar":""},{"name":"Jennifer Morrison","avatar":""},{"name":"Liza Weil","avatar":""},{"name":"Karen Vaccaro","avatar":""},{"name":"Hyowon K. Yoo","avatar":""},{"name":"Rosario Varela","avatar":""},{"name":"Antonio Pol","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324536);
