INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mickey-mat-xanh', 'Mickey Mắt Xanh', 'Mickey Blue Eyes', 'https://phimimg.com/upload/vod/20231124-1/c55065412abddb9e825d4782b1160aae.jpg', 'https://phimimg.com/upload/vod/20231124-1/73ea61ee6c5d4feff6d1dd83c856416d.jpg', '<p>Sau khi cầu hôn bạn gái, nhà đấu giá lịch lãm phát hiện ra bố của cô là dân xã hội đen và bị kéo vào công việc kinh doanh của gia đình.</p>', 'Full', 1, 'single', 'completed', 17, 1999, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Hugh Grant","avatar":""},{"name":"James Caan","avatar":""},{"name":"Jeanne Tripplehorn","avatar":""},{"name":"Burt Young","avatar":""},{"name":"James Fox","avatar":""},{"name":"Joe Viterelli","avatar":""},{"name":"Gerry Becker","avatar":""},{"name":"Maddie Corman","avatar":""},{"name":"Tony Darrow","avatar":""},{"name":"Paul Lazar","avatar":""},{"name":"Vincent Pastore","avatar":""},{"name":"Lorri Bagley","avatar":""},{"name":"Scott Thompson","avatar":""},{"name":"John Ventimiglia","avatar":""},{"name":"Frank Pellegrino","avatar":""},{"name":"Marsha Dietlein","avatar":""},{"name":"John Di Benedetto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324536);
