INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngai-ripley-tai-ba', 'Ngài Ripley Tài Ba', 'The Talented Mr. Ripley', 'https://phimimg.com/upload/vod/20231116-1/78bdd0fd61e9252e8a111aea968e8ed6.jpg', 'https://phimimg.com/upload/vod/20231116-1/12697f11d44eb57144ecaf730f17b739.jpg', '<p>Tom Ripley là một thanh niên tính toán, tin rằng thà làm người giả còn hơn làm người thật. Cơ hội đến với một công ty đóng tàu giàu có ở Hoa Kỳ thuê Tom đi du lịch đến Ý để mang về cậu con trai ăn chơi của mình, Dickie. Ripley len lỏi vào cuộc sống bình dị của Dickie và bạn gái của anh ta, lao vào một kế hoạch táo bạo của sự hai lòng, dối trá và giết người.</p>', 'Full', 1, 'single', 'completed', 14, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Jack Davenport","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"James Rebhorn","avatar":""},{"name":"Sergio Rubini","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Celia Weston","avatar":""},{"name":"Fiorello","avatar":""},{"name":"Stefania Rocca","avatar":""},{"name":"Ivano Marescotti","avatar":""},{"name":"Anna Longhi","avatar":""},{"name":"Alessandro Fabrizi","avatar":""},{"name":"Lisa Eichhorn","avatar":""},{"name":"Gretc","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
