INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-den-tu-qua-khu', 'Người Đến Từ Quá Khứ', 'Blast from the Past', 'người đến từ quá khứ blast from the past brendan fraser alicia silverstone christopher walken sissy spacek dave foley joey slotnick rex linn deborah kellner nathan fillion jenifer lewis cynthia mace don yesso carmen more dale raoul hayden tank ryan sparks douglas smith scott tho ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-duong-lo-5', 'Âm Dương Lộ 5', 'Troublesome Night 5', 'https://phimimg.com/upload/vod/20231116-1/729fab0aeaf8d8163c64b486ebd898e6.jpg', 'https://phimimg.com/upload/vod/20231116-1/ebc03e1032a9cc8079bcc78e08a096f3.jpg', '<p>Phần thứ năm của loạt phim “Troublesome Night”, bộ phim này là tuyển tập của ba câu chuyện có liên quan. Taxi Cheung gặp khó khăn khi gặp các khách hàng kỳ lạ và bí ẩn trong suốt ca đêm. Đêm đó, bạn và đồng nghiệp của anh, Fat đi đến một ngôi nhà mới với vợ và con trai của mình để trốn khỏi những con cá mập vay tiền, và vận may của anh quay trở lại khi anh phát hiện ra ngôi nhà mới của mình bị ám ảnh bởi một con quỷ, người hứa hẹn cho anh sự giàu có bất ngờ. Nhiều năm sau, con trai của Fat được thuê làm nhân viên an ninh tại một công ty kinh doanh. Ở đó, anh ấy gặp những hoạt động huyền bí trong suốt ca đêm của mình.</p>', 'Full', 1, 'single', 'completed', 17, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Simon Lui Yu-Yeung","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""},{"name":"Frankie Ng Chi-Hung","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Emily Kwan Bo-Wai","avatar":""},{"name":"Amanda Lee","avatar":""},{"name":"Ben Ng Ngai-Cheung","avatar":""},{"name":"John Dang","avatar":""},{"name":"Perrie Lai Hoi-San","avatar":""},{"name":"Lee Kin-Yan","avatar":""},{"name":"Lui Tat","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324536);
