INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-thien-tai-be-bi', 'Những thiên tài bé bi', 'Baby Geniuses', 'https://phimimg.com/upload/vod/20231113-1/0d3ec40a130fbdc7393bf1cedae5d12f.jpg', 'https://phimimg.com/upload/vod/20231113-1/3c758b875dcb7698b83127173bc0d6bd.jpg', '<p>Nhà khoa học cứ tiếp tục nói, những đứa trẻ siêu thông minh bị giam cầm, nhưng mọi thứ trở nên tồi tệ hơn khi xảy ra sự nhầm lẫn giữa một thiên tài nhí và người song sinh của nó.</p>', 'Full', 1, 'single', 'completed', 16, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kathleen Turner","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Kim Cattrall","avatar":""},{"name":"Peter MacNicol","avatar":""},{"name":"Dom DeLuise","avatar":""},{"name":"Ruby Dee","avatar":""},{"name":"Kyle Howard","avatar":""},{"name":"Kaye Ballard","avatar":""},{"name":"Leo Fitzgerald","avatar":""},{"name":"Myles Fitzgerald","avatar":""},{"name":"Gerry Fitzgerald","avatar":""},{"name":"Connor Leggett","avatar":""},{"name":"Griffin Leggett","avatar":""},{"name":"Megan Robbins","avatar":""},{"name":"Gabrielle Robbins","avatar":""},{"name":"Brianna McConnell","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324536);
