INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-on-the-moon', 'Man on the Moon', 'Man on the Moon', 'https://phimimg.com/upload/vod/20231112-1/4c415a30a91ec6fc64757b5dbc00a3ff.jpg', 'https://phimimg.com/upload/vod/20231112-1/be8100d6ab86cd65f0aad5ba5ab8aa95.jpg', '<p>Một bộ phim tiểu sử về diễn viên hài cuối cùng Andy Kaufman. Kaufman, cùng với vai trò của mình trên Taxi (1978), nổi tiếng vì là nhà vô địch đấu vật giao dịch tự tuyên bố của thế giới. Sau khi đánh bại phụ nữ lần nữa, Jerry Lawler (người tự chơi trong phim), một đô vật chuyên nghiệp, mệt mỏi khi nhìn thấy tất cả những điều này và quyết định thách thức Kaufman với một trận đấu. Trong hầu hết các trận đấu, cả hai người có, Lawler đều thịnh hành với Piledriver, đó là một động thái bằng cách tăng vọt một đối thủ đầu tiên vào thảm. Một trong những khoảnh khắc nổi tiếng nhất trong mối thù này là vào đầu những năm 80 khi Kaufman ném cà phê lên Lawler trên [Lỗi], đã vào Fisticuffs với Lawler và tiến hành Sue NBC.</p>', 'Full', 1, 'single', 'completed', 15, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"Courtney Love","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Vincent Schiavelli","avatar":""},{"name":"Peter Bonerz","avatar":""},{"name":"Jerry Lawler","avatar":""},{"name":"Gerry Becker","avatar":""},{"name":"Leslie Lyles","avatar":""},{"name":"Greyson Erik Pendry","avatar":""},{"name":"Brittany Colonna","avatar":""},{"name":"Bobby Boriello","avatar":""},{"name":"George Shapiro","avatar":""},{"name":"Budd Friedman","avatar":""},{"name":"Tom Dreesen","avatar":""},{"name":"Thomas Armbruster","avatar":""},{"name":"Pamel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
