INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-cua-straight', 'Chuyện Của Straight', 'The Straight Story', 'https://phimimg.com/upload/vod/20231113-1/6674b9a7d7a1745a6588d69dbd8a89a7.jpg', 'https://phimimg.com/upload/vod/20231113-1/49592ee840e361ba1402bb67efc62d23.jpg', '<p>Là một nông dân đã nghỉ hưu và góa vợ ở độ tuổi 70, Alvin Straight một ngày nọ biết được rằng người anh xa Lyle của ông đã bị đột quỵ và có thể không hồi phục. Alvin quyết tâm làm mọi chuyện ổn thỏa với Lyle khi anh vẫn còn có thể, nhưng anh trai anh sống ở Wisconsin, trong khi Alvin bị mắc kẹt ở Iowa mà không có ô tô và không có bằng lái xe. Sau đó, anh nảy ra ý tưởng thực hiện chuyến đi trên chiếc máy cắt cỏ cũ của mình, từ đó bắt đầu một cuộc phiêu lưu đẹp như tranh vẽ và đôi khi mang tính tâm linh sâu sắc.</p>', 'Full', 1, 'single', 'completed', 18, 1999, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Richard Farnsworth","avatar":""},{"name":"Sissy Spacek","avatar":""},{"name":"Harry Dean Stanton","avatar":""},{"name":"Everett McGill","avatar":""},{"name":"Kevin Farley","avatar":""},{"name":"John Farley","avatar":""},{"name":"Jane Galloway Heitz","avatar":""},{"name":"Joseph A. Carpenter","avatar":""},{"name":"Donald Wiegert","avatar":""},{"name":"Tracey Maloney","avatar":""},{"name":"Dan Flannery","avatar":""},{"name":"Ed Grennan","avatar":""},{"name":"Jack Walsh","avatar":""},{"name":"Gil Pearson","avatar":""},{"name":"Barbara June Patterson","avatar":""},{"name":"James Cad","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
