INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-cua-straight', 'Chuyện Của Straight', 'The Straight Story', 'chuyện của straight the straight story richard farnsworth sissy spacek harry dean stanton everett mcgill kevin farley john farley jane galloway heitz joseph a. carpenter donald wiegert tracey maloney dan flannery ed grennan jack walsh gil pearson barbara june patterson james cad ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-cua-nhung-chuyen-tau', 'Linh Hồn Của Những Chuyến Tàu', 'Railroad Man', 'https://phimimg.com/upload/vod/20231110-1/41cdcde5c87108d30b5c65f340e38366.jpg', 'https://phimimg.com/upload/vod/20231110-1/c5603995954050bfae015dc6e18f5e98.jpg', '<p>Phim là sự so sánh tương quan giữa bổn phận nghề nghiệp và bổn phận gia đình. Otomatsu Sato là một nhân viên đường sắt luôn tận tụy và trung thành với nghề. Ông dành trọn cuộc đời mình bên ga tàu và xem nó như một phần cuộc sống của ông. Khi con gái ông mất ở bệnh viện, ông vẫn còn bận làm việc ở đường ray xe lửa. Khi vợ ông đi chữa bệnh và mất ở bệnh viện, ông cũng không có mặt cạnh bà khi bà ra đi. Liệu ông có hối hận khi từ bỏ và đánh mất đi gia đình của mình chỉ để dành toàn bộ tâm ý cho sự nghiệp?</p>', 'Full', 1, 'single', 'completed', 17, 1999, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ken Takakura","avatar":""},{"name":"Ryoko Hirosue","avatar":""},{"name":"Hidetaka Yoshioka","avatar":""},{"name":"Masanobu Ando","avatar":""},{"name":"Ken Shimura","avatar":""},{"name":"Shinobu Otake","avatar":""},{"name":"Tomoko Naraoka","avatar":""},{"name":"Yoshiko Tanaka","avatar":""},{"name":"Nenji Kobayashi","avatar":""},{"name":"Eiji Bandô","avatar":""},{"name":"Mitsuru Hirata","avatar":""},{"name":"Hirotaro Honda","avatar":""},{"name":"Renji Ishibashi","avatar":""},{"name":"Kitaro","avatar":""},{"name":"Shigeo Kobayashi","avatar":""},{"name":"Rie Nakahara","avatar":""},{"name":"Ken Nakamoto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
