INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('austin-powers-chang-diep-vien-yeu-toi', 'Austin Powers: Chàng Điệp Viên Yêu Tôi', 'Austin Powers: The Spy Who Shagged Me', 'https://phimimg.com/upload/vod/20231109-1/719334079fd6b1e3c5d3426b71b4ed17.jpg', 'https://phimimg.com/upload/vod/20231109-1/25928e6f6ead82df7d2341422384a2df.jpg', '<p>Tiến sỹ điên Evil đã quay trở lại, cùng với đó là phát minh mới của hắn: một chiếc máy điều khiển thời gian, cho phép hắn có thể trở về thập niên 60 với ý đồ mờ ám.</p>', 'Full', 1, 'single', 'completed', 17, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mike Myers","avatar":""},{"name":"Heather Graham","avatar":""},{"name":"Michael York","avatar":""},{"name":"Robert Wagner","avatar":""},{"name":"Rob Lowe","avatar":""},{"name":"Seth Green","avatar":""},{"name":"Mindy Sterling","avatar":""},{"name":"Verne Troyer","avatar":""},{"name":"Elizabeth Hurley","avatar":""},{"name":"Gia Carides","avatar":""},{"name":"Oliver Muirhead","avatar":""},{"name":"George Cheung","avatar":""},{"name":"Jeffrey Meng","avatar":""},{"name":"Muse Watson","avatar":""},{"name":"Scott Cooper","avatar":""},{"name":"Douglas Fisher","avatar":""},{"name":"Kevin Cooney","avatar":""},{"name":"Clint Howard","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324536);
