INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-hoa-anh-hung', 'Trung Hoa Anh Hùng', 'A Man Called Hero', 'https://phimimg.com/upload/vod/20231109-1/c2f6de51a2a7346ec427cd90e9336a4f.jpg', 'https://phimimg.com/upload/vod/20231109-1/cd6a8bd1cbd6823fdb51081c4d164232.jpg', '<p>Bộ phim dựa theo 1 bộ truyện tranh võ hiệp của Mã Vinh Thành, bối cảnh đấu thế kỉ 20 phim nói về cuộc đời của Hoa Anh Hùng, sinh ra trong một gia đình có truyền thống võ thuật. Một ngày cha mẹ anh bị sát hại, Hoa Anh Hùng đã trả thù cho cha mẹ và mang tội sát nhân. Anh đành từ biệt Khiết Du và Sinh Nô, hai người bạn thân và ra đi. Trải qua nhiều sóng gió lưu lạc từ Trung Hoa đến Hoa Kỳ, cùng với những bằng hữu như La Hán, Nguyên Võ ... Anh Hùng đã gặp phải nhiều khó khăn, những kẻ thù của anh vả của người Hoa ở đất Mĩ không ngừng tìn cách tiêu diệt Anh Hùng và Trung Hoa Lầu ...</p>', 'Full', 1, 'single', 'completed', 17, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ekin Cheng Yee-Kin","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Kristy Yang","avatar":""},{"name":"Nicholas Tse","avatar":""},{"name":"Jerry Lamb Hiu-Fung","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Francis Ng","avatar":""},{"name":"Dion Lam Dik-On","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"Grace Yip","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Frankie Ng Chi-Hung","avatar":""},{"name":"Jude Poyer","avatar":""},{"name":"Ronald Wong Ban","avatar":""},{"name":"Yu Ka-H","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324536);
