INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-dieu-thuoc', 'Nửa Điếu Thuốc', 'Metade Fumaca', 'https://phimimg.com/upload/vod/20231108-1/f95e3575c30640c254d0dc871ed4066b.jpg', 'https://phimimg.com/upload/vod/20231108-1/987efc90162576b719f42e265485092e.jpg', '<p>Nội dung phim xoay quanh câu chuyện về bộ ba những chàng trai hào hoa, tài giỏi lại trở về Hong Kong. Mountain Lion (Tăng Chí Vĩ) đã trông cậy vào Smokey (Tạ Đình Phong) giúp anh nối lại quan hệ với Nine Dragons (Chan Wai-man), người bạn thân trước đây của anh, nhưng cả hai đã có những hiều lầm chỉ vì cùng yêu một cô gái rất bí ẩn (Thư Kỳ). Hai người đã đánh nhau vài năm trước vì cô gái đó.Mountain Lion lại muốn tìm lại cô gái này và anh cần sự giúp đỡ từ người bạn Smokey đưa anh đến những ngõ ngách của của xã hội, điều này đã gợi lại cho anh những ký ức cũng như những kỷ niệm lãng mạn trước đây.</p>', 'Full', 1, 'single', 'completed', 16, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Eric Tsang","avatar":""},{"name":"Nicholas Tse","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Michael Chan","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Kelly Chen","avatar":""},{"name":"Stephen Fung","avatar":""},{"name":"Sandra Ng Kwan-Yue","avatar":""},{"name":"Terence Yin","avatar":""},{"name":"Tony Ho","avatar":""},{"name":"Jo Kuk Cho-Lam","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Stephen Tung Wai","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Alex Lam Chi-Sin","avatar":""},{"name":"Steve Wong Ka-Keung","avatar":""},{"name":"Vincent Wan Ye","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324536);
