INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('asterix-obelix-take-on-caesar', 'Asterix & Obelix Take on Caesar', 'Astérix & Obélix contre César', 'https://phimimg.com/upload/vod/20231114-1/1215dc2c23138443fb9cd38d1aa10d45.jpg', 'https://phimimg.com/upload/vod/20231114-1/8b230c2184d7d85baa43d85ca37620af.jpg', '<p>Lấy bối cảnh vào năm 50 trước Công nguyên, Asterix và Obelix đang sống trong một ngôi làng nhỏ nhưng được bảo vệ cẩn mật ở Gaul, nơi một loại thuốc ma thuật do Druids pha chế biến người dân thị trấn thành những người lính hùng mạnh. Khi quân đội La Mã mở một con đường xuyên qua Gaul để đến Kênh tiếng Anh, Caesar và trợ lý trại Detritus của anh ta phát hiện ra thuốc tiên bí mật và bắt giữ thủ lĩnh Druid, người biết công thức của nó, Asterix và Obelix được cử đi giải cứu họ.</p>', 'Full', 1, 'single', 'completed', 17, 1999, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Christian Clavier","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"Roberto Benigni","avatar":""},{"name":"Michel Galabru","avatar":""},{"name":"Gottfried John","avatar":""},{"name":"Laetitia Casta","avatar":""},{"name":"Claude Piéplu","avatar":""},{"name":"Daniel Prévost","avatar":""},{"name":"Pierre Palmade","avatar":""},{"name":"Arielle Dombasle","avatar":""},{"name":"Marianne Sägebrecht","avatar":""},{"name":"Jean-Pierre Castaldi","avatar":""},{"name":"Jean-Roger Milo","avatar":""},{"name":"Jean-Jacques Devaux","avatar":""},{"name":"Hardy K","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324536);
