INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-cua-thien-yet-2', 'Đêm Của Thiên Yết 2', 'Scorpio Nights 2', 'null', 'https://phimimg.com/upload/vod/20231103-1/d7ada75b84de2b11f69da23eadf2914a.jpg', '<p>Andrew tỉ mỉ gần như đến mức ám ảnh. Từ cách anh ấy mang quần áo của mình đến cách anh ấy giảng bài Vật lý của mình, Andrew là người có phương pháp trong mọi việc anh ấy làm. Nhưng sự tồn tại có trật tự của anh ta đột nhiên bị gián đoạn khi một sinh viên thích phiêu lưu tình dục, Valerie, bắt đầu quyến rũ anh ta. Andrew chịu thua trước sự cám dỗ, và chẳng bao lâu, cả hai bị cuốn vào một mối quan hệ bùng nổ không có giới hạn.</p>', 'Full', 1, 'single', 'completed', 21, 1999, 'Vietsub', 'HD', 'Philippines', 0, '[{"name":"Albert Martinez","avatar":""},{"name":"Joyce Jimenez","avatar":""},{"name":"Daisy Reyes","avatar":""},{"name":"Janus Del Prado","avatar":""},{"name":"Manny Castañeda","avatar":""},{"name":"Bibeth Orteza","avatar":""},{"name":"Jaime Fabregas","avatar":""},{"name":"Cherry Pie Picache","avatar":""},{"name":"Luciano B. Carlos","avatar":""},{"name":"Mel Kimura","avatar":""},{"name":"Carmel Osmeña","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
