INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-giao-anna-va-nha-vua', 'Cô Giáo Anna Và Nhà Vua', 'Anna and the King', 'https://phimimg.com/upload/vod/20231103-1/6e89317206e0f540aadcfd643047cdc0.jpg', 'https://phimimg.com/upload/vod/20231103-1/c7fde69ed69182306f2f7db4af93dc03.jpg', '<p>Câu chuyện về mối tình lãng mạn giữa Vua Xiêm (nay là Thái Lan) và cô giáo góa bụa người Anh Anna Leonowens trong những năm 1860. Anna dạy bọn trẻ và trở nên lãng mạn bởi Nhà vua. Cô thuyết phục anh ta rằng một người đàn ông chỉ có thể được yêu bởi một người phụ nữ.</p>', 'Full', 1, 'single', 'completed', 21, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jodie Foster","avatar":""},{"name":"Chow Yun-fat","avatar":""},{"name":"Bai Ling","avatar":""},{"name":"Tom Felton","avatar":""},{"name":"Syed Alwi","avatar":""},{"name":"Randall Duk Kim","avatar":""},{"name":"Lim Kay Siu","avatar":""},{"name":"Melissa Campbell","avatar":""},{"name":"Keith Chin","avatar":""},{"name":"Mano Maniam","avatar":""},{"name":"Shanthini Venugopal","avatar":""},{"name":"Deanna Yusoff","avatar":""},{"name":"Geoffrey Palmer","avatar":""},{"name":"Ann Firbank","avatar":""},{"name":"Bill Stewart","avatar":""},{"name":"Sean Ghazi","avatar":""},{"name":"K.K. Moggie","avatar":""},{"name":"Dharma Harun","avatar":""},{"name":"Ha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324536);
