INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-mau-thien-duong', 'Sắc Màu Thiên Đường', 'The Colour of Paradise', 'https://phimimg.com/upload/vod/20231102-1/dbf9d5308375f1312163c8f1f9e56e47.jpg', 'https://phimimg.com/upload/vod/20231102-1/f191fa303982eaa99e5c5b23f9d9fd5c.jpg', '<p>Câu chuyện xoay quanh một cậu bé mù tên là Mohammed được cho nghỉ hè tại ngôi trường đặc biệt ở Tehran. Cha của anh, xấu hổ và nặng nề vì Mohammed bị mù, đã đến đón anh muộn và sau đó cố gắng thuyết phục hiệu trưởng giữ Mohammed qua mùa hè. Hiệu trưởng từ chối, vì vậy cha của Mohammed cuối cùng đã đưa anh ta về nhà.</p>', 'Full', 1, 'single', 'completed', 19, 1999, 'Vietsub', 'HD', 'Iran', 0, '[{"name":"Hossein Mahjoub","avatar":""},{"name":"Mohsen Ramezani","avatar":""},{"name":"Salameh Feyzi","avatar":""},{"name":"Farahnaz Safari","avatar":""},{"name":"Elham Sharifi","avatar":""},{"name":"Behzad Rafi","avatar":""},{"name":"Mohamad Rahmani","avatar":""},{"name":"Morteza Fatemi","avatar":""},{"name":"Kamal Mirkarimi","avatar":""},{"name":"Masoome Zinati","avatar":""},{"name":"Zahra Mizani","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
