INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cach-mang-cong-so', 'Cách Mạng Công Sở', 'Office Space', 'https://phimimg.com/upload/vod/20231101-1/4fe86a617f50970238c539282395b8e0.jpg', 'https://phimimg.com/upload/vod/20231101-1/0cd11fb0904330c77bbe30d20d7316f7.jpg', '<p>Một công nhân cổ cồn trắng bị trầm cảm thử liệu pháp thôi miên, chỉ để thấy mình luôn ở trong trạng thái hạnh phúc như ma quỷ có thể quan tâm, khiến anh ta bắt đầu sống theo quy tắc của riêng mình và ấp ủ một nỗ lực bất thành để biển thủ tiền từ những người chủ đang giết chết linh hồn của mình.</p>', 'Full', 1, 'single', 'completed', 19, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ron Livingston","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"David Herman","avatar":""},{"name":"Ajay Naidu","avatar":""},{"name":"Diedrich Bader","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Gary Cole","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"Ali Wentworth","avatar":""},{"name":"Joe Bays","avatar":""},{"name":"John C. McGinley","avatar":""},{"name":"Paul Willson","avatar":""},{"name":"Kinna McInroe","avatar":""},{"name":"Todd Duffey","avatar":""},{"name":"Greg Pitts","avatar":""},{"name":"Michael McShane","avatar":""},{"name":"Linda Wakeman","avatar":""},{"name":"Jennifer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324536);
