INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-vo-si-dao', 'Con Đường Võ Sĩ Đạo', 'Ghost Dog: The Way of the Samurai', 'https://phimimg.com/upload/vod/20231101-1/2541eedc96205dc19d0fda852ea85398.jpg', 'https://phimimg.com/upload/vod/20231101-1/d4e4359a49c4618acf2a8e0cbcbe1629.jpg', '<p>Bộ phim kể về một sát thủ mang trong mình tinh thần Võ sĩ đạo, và anh đã phải đấu tranh ra sao trong một xã hội Mỹ hiện đại thực dụng, đầy cạm bẫy....</p>', 'Full', 1, 'single', 'completed', 22, 1999, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Forest Whitaker","avatar":""},{"name":"John Tormey","avatar":""},{"name":"Isaach De Bankolé","avatar":""},{"name":"Cliff Gorman","avatar":""},{"name":"Henry Silva","avatar":""},{"name":"Tricia Vessey","avatar":""},{"name":"Victor Argo","avatar":""},{"name":"Camille Winbush","avatar":""},{"name":"Gene Ruffini","avatar":""},{"name":"Richard Portnow","avatar":""},{"name":"Frank Minucci","avatar":""},{"name":"Dennis Liu","avatar":""},{"name":"Frank Adonis","avatar":""},{"name":"Damon Whitaker","avatar":""},{"name":"Kenny Guay","avatar":""},{"name":"Vince Viverito","avatar":""},{"name":"Gano Grills","avatar":""},{"name":"Touch","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
