INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tang-thu-13', 'Tầng Thứ 13', 'The Thirteenth Floor', 'https://phimimg.com/upload/vod/20231101-1/6d62d167fa89c7d27d4abb912221057f.jpg', 'https://phimimg.com/upload/vod/20231101-1/f04b9e763e4ea2e89c21b80ad0bd51bb.jpg', '<p>Los Angeles. Một người đàn ông giàu có, được biết đến với cái tên Mr. Fuller, phát hiện ra một bí mật gây sốc về thế giới mà anh ta đang sống. Lo sợ cho tính mạng của mình, anh ta để lại một lời nhắn tuyệt vọng cho một người bạn của mình ở một nơi không ngờ tới nhất.</p>', 'Full', 1, 'single', 'completed', 18, 1999, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Craig Bierko","avatar":""},{"name":"Armin Mueller-Stahl","avatar":""},{"name":"Gretchen Mol","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"Steven Schub","avatar":""},{"name":"Jeremy Roberts","avatar":""},{"name":"Rif Hutton","avatar":""},{"name":"Leon Rippy","avatar":""},{"name":"Janet MacLachlan","avatar":""},{"name":"Brad William Henke","avatar":""},{"name":"Burt Bulos","avatar":""},{"name":"Venessia Valentino","avatar":""},{"name":"Howard S. Miller","avatar":""},{"name":"Tia Texada","avatar":""},{"name":"Shiri Apple","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324536);
