INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-thu-giong', 'Buổi Thử Giọng', 'Audition', 'https://phimimg.com/upload/vod/20231101-1/7bb4c7c0d23caec8f2a77875dce2b5f1.jpg', 'https://phimimg.com/upload/vod/20231101-1/bc69a923623c0ac795c28004c0d7d81a.jpg', '<p>Audition ( オ ー デ ィdishon ) là một bộ phim kinh dị Nhật Bản năm 1999 của đạo diễn Takashi Miike , dựa trên tiểu thuyết năm 1997 của Ryu Murakami . Đó là về một người góa vợ, Shigeharu Aoyama ( Ryo Ishibashi ), người con trai gợi ý rằng anh ta nên tìm một người vợ mới. Aoyama đồng ý, và với một người bạn, thực hiện một buổi thử giọng giả để gặp một đối tác mới tiềm năng trong cuộc sống. Sau khi phỏng vấn một vài phụ nữ, Aoyama bắt đầu quan tâm đến Asami ( Eihi Shiina ), người đáp ứng tốt với anh ta, mặc dù khi họ bắt đầu hẹn hò, quá khứ đen tối của cô bắt đầu ảnh hưởng đến mối quan hệ của họ.</p>', 'Full', 1, 'single', 'completed', 20, 1999, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ryo Ishibashi","avatar":""},{"name":"Eihi Shiina","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Tetsu Sawaki","avatar":""},{"name":"Renji Ishibashi","avatar":""},{"name":"Miyuki Matsuda","avatar":""},{"name":"Toshie Negishi","avatar":""},{"name":"Yuriko Hirooka","avatar":""},{"name":"Shigeru Saiki","avatar":""},{"name":"Ken Mitsuishi","avatar":""},{"name":"Ren Osugi","avatar":""},{"name":"Kanji Tsuda","avatar":""},{"name":"Fumiyo Kohinata","avatar":""},{"name":"Misato Nakamura","avatar":""},{"name":"Yuuto Arima","avatar":""},{"name":"Ayaka Izumi","avatar":""},{"name":"Kimiko Tachibana","avatar":""},{"name":"Ta","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
