INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-bay', 'Gài Bẫy', 'Entrapment', 'https://phimimg.com/upload/vod/20231030-1/2b3e56274bbc67428c2d660e8846ccf6.jpg', 'https://phimimg.com/upload/vod/20231030-1/85fb6ab181b8bb3cfb87d76d44a2524c.jpg', '<p>Khi tên trộm về hưu dính líu đến vụ một bức tranh vô giá biến mất, nữ nhân viên điều tra bảo hiểm nọ bèn gài bẫy để bắt kẻ mà cô nghi ngờ.</p>', 'Full', 1, 'single', 'completed', 16, 1999, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Sean Connery","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Maury Chaykin","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Kevin McNally","avatar":""},{"name":"Terry O''Neill","avatar":""},{"name":"Madhav Sharma","avatar":""},{"name":"David Yip","avatar":""},{"name":"Tim Potter","avatar":""},{"name":"Eric Meyers","avatar":""},{"name":"Aaron Swartz","avatar":""},{"name":"William Marsh","avatar":""},{"name":"Tony Xu","avatar":""},{"name":"Rolf Saxon","avatar":""},{"name":"Tom Clarke Hill","avatar":""},{"name":"David Howard","avatar":""},{"name":"Stuart Yung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324536);
