INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-the-gioi-khong-du', 'Điệp Viên 007: Thế Giới Không Đủ', 'The World Is Not Enough', 'https://phimimg.com/upload/vod/20231026-1/e106c7dfcf359f2303664b9348f7bd89.jpg', 'https://phimimg.com/upload/vod/20231026-1/53504d65ee8f721b8d91a63e1a066d94.jpg', '<p>Trùm tư bản giàu có Robert King bị ám sát trong vụ nổ bom tại Trụ sở M.I. 6. Người thừa kế duy nhất của ông là cô con gái Elektra King. Tài sản to lớn của Elektras đã thu hút sự quan tâm rất nhiều từ phía dư luận. Và tất nhiên trong số đó có cả tên đã giết bố cô, Renard. Một viên đạn gài trong não Renard chính là lý do khiến hắn không biết đến cảm giác đau đớn, và hắn quyết tâm sống sót để trả thù. Là người bạn của cha cô, James Bond nhận trách nhiệm bảo vệ cô gái khỏi sự tấn công của một tên khủng bố điên loạn.</p>', 'Full', 1, 'single', 'completed', 15, 1999, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Robert Carlyle","avatar":""},{"name":"Sophie Marceau","avatar":""},{"name":"Denise Richards","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Desmond Llewelyn","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Samantha Bond","avatar":""},{"name":"Maria Grazia Cucinotta","avatar":""},{"name":"Michael Kitchen","avatar":""},{"name":"Colin Salmon","avatar":""},{"name":"Goldie","avatar":""},{"name":"David Calder","avatar":""},{"name":"Serena Scott Thomas","avatar":""},{"name":"Ulrich Thomsen","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324536);
