INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diep-vien-007-the-gioi-khong-du', 'Điệp Viên 007: Thế Giới Không Đủ', 'The World Is Not Enough', 'điệp viên 007: thế giới không đủ the world is not enough pierce brosnan robert carlyle sophie marceau denise richards robbie coltrane judi dench desmond llewelyn john cleese samantha bond maria grazia cucinotta michael kitchen colin salmon goldie david calder serena scott thomas ulrich thomsen j ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-dep-my', 'Vẻ Đẹp Mỹ', 'American Beauty', 'https://phimimg.com/upload/vod/20231025-1/0893eefcb84f3e572a0dda59e7223232.jpg', 'https://phimimg.com/upload/vod/20231025-1/09e77bafc3d368c3dd01314e2b9b7084.jpg', '<p>Một cuộc phiêu lưu thú vị, đáng lo ngại và đáng ngạc nhiên vào vùng ngoại ô nước Mỹ thông qua cuộc sống của Lester và Carolyn, một cặp vợ chồng thuộc tầng lớp trung lưu có hôn nhân - và cuộc sống của họ - đang dần làm sáng tỏ. Carolyn ghét chồng, con gái khinh bỉ anh ta, và ông chủ của cô ta sắp sa thải anh ta. Vì vậy, Lester quyết định thay đổi một số điều trong cuộc sống của mình; khi anh ta trở nên tự do hơn, anh ta trở nên hạnh phúc hơn, điều đó khiến vợ và con gái anh ta tức giận hơn.</p>', 'Full', 1, 'single', 'completed', 11, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Spacey","avatar":""},{"name":"Annette Bening","avatar":""},{"name":"Thora Birch","avatar":""},{"name":"Wes Bentley","avatar":""},{"name":"Mena Suvari","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Peter Gallagher","avatar":""},{"name":"Scott Bakula","avatar":""},{"name":"Sam Robards","avatar":""},{"name":"Barry Del Sherman","avatar":""},{"name":"John Cho","avatar":""},{"name":"Kent Faulcon","avatar":""},{"name":"Ara Celi","avatar":""},{"name":"Sue Casey","avatar":""},{"name":"Brenda Wehle","avatar":""},{"name":"Lisa Cloud","avatar":""},{"name":"Amber Smith","avatar":""},{"name":"Joel McCr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
