INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-quan-thu-sau', 'Giác Quan Thứ Sáu', 'The Sixth Sense', 'https://phimimg.com/upload/vod/20231022-1/7050f5a722adcdaf826ff71cbc2166c2.jpg', 'https://phimimg.com/upload/vod/20231022-1/4a6329bff454956118204eb1d5837444.jpg', '<p>Bác sĩ Malcolm Crowe là một nhà tâm lý học trẻ em nổi tiếng bị ám ảnh bởi ký ức đau đớn của một bệnh nhân trẻ không cân bằng mà anh ta không thể giúp đỡ. Cole Sear là một đứa trẻ 8 tuổi sợ hãi và bối rối, cần được điều trị và Crowe nhìn thấy một cơ hội để chuộc lỗi bằng cách làm mọi thứ có thể để giúp anh ta. Tuy nhiên, nhà tâm lý học trẻ em không sẵn sàng để biết sự thật khủng khiếp về món quà siêu nhiên của bệnh nhân của mình: anh ta nhận được những chuyến thăm không mong muốn từ những linh hồn đau khổ.</p>', 'Full', 1, 'single', 'completed', 14, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Haley Joel Osment","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Trevor Morgan","avatar":""},{"name":"Donnie Wahlberg","avatar":""},{"name":"Peter Anthony Tambakis","avatar":""},{"name":"Jeffrey Zubernis","avatar":""},{"name":"Bruce Norris","avatar":""},{"name":"Glenn Fitzgerald","avatar":""},{"name":"Greg Wood","avatar":""},{"name":"Mischa Barton","avatar":""},{"name":"Angelica Page","avatar":""},{"name":"Lisa Summerour","avatar":""},{"name":"Firdous Bamji","avatar":""},{"name":"Samia Shoaib","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
