INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mien-tay-hoang-da', 'Miền Tây Hoang Dã', 'Wild Wild West', 'https://phimimg.com/upload/vod/20231016-1/241912e65b045a335eb3694681f45687.jpg', 'https://phimimg.com/upload/vod/20231016-1/53d1f1525fb035c93a32cf71fd83a24f.jpg', '<p>Phim có bối cảnh năm 1869 trong thời kỳ tái thiết nước Mỹ dưới sự lãnh đạo của tổng thống Ulysses S. Grant. Mở đầu cảnh phim là một khu rừng tại Louisiana, một người đàn ông đang cố trốn chạy khỏi cái đĩa bay chết người đang rượt theo anh. Cuối cùng cái đĩa bám kịp và chặt phăng đầu người đàn ông nọ. Ngay sau đó, một người đàn ông xuất hiện, nhặt cái đĩa lên và lẩm bẩm: “Cánh khoa học các người cứ tự cho mình là thông thái đi!” Đó chỉ là một cảnh trong một xã hội giao thoa giữa nếp sống cũ và sự “tấn công” ồ ạt của khoa học kỹ thuật hiện đại. James West (Will Smith thủ vai) và Artemus Gordon (Kevin Kline thủ vai) là hai con người, hai tính cách trái ngược nhau phải kết hợp trong một nhiệm vụ quan trọng và nguy hiểm: bảo vệ tính mạng của tổng thống Grant.</p>', 'Full', 1, 'single', 'completed', 23, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Kevin Kline","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"M. Emmet Walsh","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"Frederique van der Wal","avatar":""},{"name":"Musetta Vander","avatar":""},{"name":"Sofia Eng","avatar":""},{"name":"Garcelle Beauvais","avatar":""},{"name":"Bai Ling","avatar":""},{"name":"Rodney A. Grant","avatar":""},{"name":"E.J. Callahan","avatar":""},{"name":"Debra Christofferson","avatar":""},{"name":"Buck Taylor","avatar":""},{"name":"James Lashly","avatar":""},{"name":"Dea","avatar":""}]', '[{"name":"Hành Động","slug":"