INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-200-tuoi', 'Người 200 Tuổi', 'Bicentennial Man', 'https://phimimg.com/upload/vod/20231016-1/80c1ccefc163e6bcde6057c7736c9af5.jpg', 'https://phimimg.com/upload/vod/20231016-1/cf16480aa60cb49986b99923d0a3fabd.jpg', '<p>Richard Martin mua một món quà là robot NDR-114 mới. Sản phẩm được con út trong gia đình đặt tên là Andrew.</p>', 'Full', 1, 'single', 'completed', 20, 1999, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Kiersten Warren","avatar":""},{"name":"Wendy Crewson","avatar":""},{"name":"Hallie Eisenberg","avatar":""},{"name":"Lindze Letherman","avatar":""},{"name":"Angela Landis","avatar":""},{"name":"John Michael Higgins","avatar":""},{"name":"Bradley Whitford","avatar":""},{"name":"Igor Hiller","avatar":""},{"name":"Joe Bellan","avatar":""},{"name":"Brett Wagner","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Scott Waugh","avatar":""},{"name":"Quinn Smi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
