INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-thu-13', 'Chiến Binh Thứ 13', 'The 13th Warrior', 'https://phimimg.com/upload/vod/20231016-1/22c6e69df9b509e590021324c2e8f5be.jpg', 'https://phimimg.com/upload/vod/20231016-1/102e45b918ddb9078992025a17881766.jpg', '<p>Là một đại sứ Hồi giáo bị lưu đày khỏi quê hương, Ahmad ibn Fadlan nhận thấy mình đang ở cùng với những người Viking. Trong khi hành vi của người Norsemen ban đầu xúc phạm ibn Fadlan, thì những người ngoài cuộc có văn hóa hơn sẽ dần tôn trọng những chiến binh cứng rắn, nếu thô lỗ. Trong chuyến du hành cùng nhau, ibn Fadlan và những người Viking nhận được tin báo về sự hiện diện của tà ác đang đến gần và họ phải chiến đấu với thế lực đáng sợ và ghê gớm mà trước đây được cho là chỉ tồn tại trong truyền thuyết.</p>', 'Full', 1, 'single', 'completed', 23, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Antonio Banderas","avatar":""},{"name":"Diane Venora","avatar":""},{"name":"Dennis Storhøi","avatar":""},{"name":"Vladimir Kulich","avatar":""},{"name":"Omar Sharif","avatar":""},{"name":"Anders T. Andersen","avatar":""},{"name":"Richard Bremmer","avatar":""},{"name":"Tony Curran","avatar":""},{"name":"Mischa Hausserman","avatar":""},{"name":"Neil Maffin","avatar":""},{"name":"Asbjørn ''Bear'' Riis","avatar":""},{"name":"Clive Russell","avatar":""},{"name":"Daniel Southern","avatar":""},{"name":"Oliver Sveinall","avatar":""},{"name":"Sven Wollter","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324536);
