INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jinroh-lu-doan-soi', 'Jin-Roh : Lữ Đoàn Sói', 'Jin-Roh: The Wolf Brigade', 'https://phimimg.com/upload/vod/20231016-1/a6087b3219cef578d5bec2132c146a6f.jpg', 'https://phimimg.com/upload/vod/20231016-1/bd4ff178daeb5561e1077604b24a0685.jpg', '<p>Một thành viên của đơn vị chống khủng bố bán quân sự tinh nhuệ bị tổn thương sau khi chứng kiến vụ đánh bom tự sát của một cô gái trẻ và buộc phải trải qua khóa đào tạo lại. Tuy nhiên, anh ta không hề hay biết, anh ta trở thành nhân vật chủ chốt trong một cuộc tranh chấp giữa các bộ phận cảnh sát đối thủ, khi anh ta thấy mình ngày càng có quan hệ mật thiết với em gái của cô gái đã chết trong vụ tự sát.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 1999, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Yoshikatsu Fujiki","avatar":""},{"name":"Sumi Mutoh","avatar":""},{"name":"Eri Sendai","avatar":""},{"name":"Hiroyuki Kinoshita","avatar":""},{"name":"Kohsei Hirota","avatar":""},{"name":"Yukihiro Yoshida","avatar":""},{"name":"Ryuichi Horibe","avatar":""},{"name":"Kenji Nakagawa","avatar":""},{"name":"Yoshisada Sakaguchi","avatar":""},{"name":"Tamio Ohki","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324536);
