INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-cua-kikujiro', 'Mùa Hè Của Kikujiro', 'Kikujiro', 'https://phimimg.com/upload/vod/20231016-1/b9864bf856eaff97695c7bd1b7fe86cb.jpg', 'https://phimimg.com/upload/vod/20231016-1/47858e12aa5ffc0245a2e07669c3790a.jpg', '<p>Kikujiro là một trong những bộ phim thành công và đáng chú ý nhất của đạo diễn nổi tiếng Takeshi Kitano.&nbsp; Bộ phim kể về hành trình đi tìm mẹ của cậu bé Masao. Chán nản vì kì nghỉ hè buồn tẻ, không ai chơi cùng Masao quyết định đi tìm mẹ, người đã để cậu bé ở lại với bà sau khi bố cậu mất. Một người bạn của bà cậu biết được và quyết định cử chồng mình là Kikujiro, một người đàn ông kì lạ mà đến cuối cuộc hành trình Masao mới biết tên đưa cậu đi tìm mẹ ở một vùng ngoại ô.&nbsp; Một người lớn, một trẻ nhỏ với 2 tính cách đối lập nhau khiến cho cuộc hành trình lúc đầu chẳng mấy khả quan với những tình huống dở khóc dở cười. Liệu cặp đôi này có đi được đến cuối cuộc hành trình, và cậu bé Masao có tìm thấy mẹ của mình, mời các bạn xem phim.</p>', 'Full', 1, 'single', 'completed', 22, 1999, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Takeshi Kitano","avatar":""},{"name":"Yusuke Sekiguchi","avatar":""},{"name":"Kayoko Kishimoto","avatar":""},{"name":"Yuko Daike","avatar":""},{"name":"Kazuko Yoshiyuki","avatar":""},{"name":"Beat Kiyoshi","avatar":""},{"name":"Gurêto Gidayû","avatar":""},{"name":"Rakkyo Ide","avatar":""},{"name":"Nezumi Imamura","avatar":""},{"name":"Fumie Hosokawa","avatar":""},{"name":"Akaji Maro","avatar":""},{"name":"Daigaku Sekine","avatar":""},{"name":"Makoto Inamiya","avatar":""},{"name":"Hisahiko Murasawa","avatar":""},{"name":"Yoji Tanaka","avatar":""},{"name":"Kanako Kojima","avatar":""},{"name":"Fuyu Ooba","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324536);
