INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sung-than', 'Súng Thần', 'The Boondock Saints', 'https://phimimg.com/upload/vod/20231016-1/67437e42726c2cd3070e5755fe31cca7.jpg', 'https://phimimg.com/upload/vod/20231016-1/dd88cf99261b2f136eeda7586dd9b8a9.jpg', '<p>Mệt mỏi với tội ác hoành hành khắp các đường phố ở Boston, hai anh em song sinh Công giáo Ireland là Conner và Murphy được truyền cảm hứng bởi đức tin của họ để tẩy sạch tội ác quê hương của họ với thương hiệu của riêng họ về công lý nhiệt thành cảnh giác. Khi họ truy lùng và giết hết tên xã hội đen khét tiếng này đến kẻ khác, họ trở thành những anh hùng dân gian gây tranh cãi trong cộng đồng. Nhưng Paul Smecker, một đặc vụ FBI lập dị, đang nhanh chóng đi vào dấu vết đẫm máu của họ.</p>', 'Full', 1, 'single', 'completed', 21, 1999, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Willem Dafoe","avatar":""},{"name":"Sean Patrick Flanery","avatar":""},{"name":"Norman Reedus","avatar":""},{"name":"David Della Rocco","avatar":""},{"name":"Billy Connolly","avatar":""},{"name":"David Ferry","avatar":""},{"name":"Brian Mahoney","avatar":""},{"name":"Bob Marley","avatar":""},{"name":"Richard Fitzpatrick","avatar":""},{"name":"William Young","avatar":""},{"name":"Robert Pemberton","avatar":""},{"name":"Bill Craig","avatar":""},{"name":"Dot-Marie Jones","avatar":""},{"name":"Scott Griffith","avatar":""},{"name":"Layton Morrison","avatar":""},{"name":"James Binkley","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324536);
