INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-gian-1999', 'Nội Gián', 'The Insider', 'https://phimimg.com/upload/vod/20231016-1/ef3ad48d532de39a2d9a49962d0b3998.jpg', 'https://phimimg.com/upload/vod/20231016-1/61f0d507e1710fe99dd5598ec2da0317.jpg', '<p>The Insider 1999 kể về câu chuyện của Jeffrey Wigand (Russell Crowe), một nhà nghiên cứu của công ty sản xuất thuốc lá Brown &amp; Williamson. Ông đã đứng lên chống lại những hành động vô lương tâm của công ty khi đã thêm vào trong thuốc lá những chất có hại cho sức khỏe nhằm tăng tác dụng của chất nicotine. Ông đã phải chịu rất nhiều sự đe dọa của các tập đoàn lớn trong ngành công nghiệp thuốc lá, những tập đoàn này đã dùng tiền bạc, quyền lực của mình để mua chuộc bên điều tra và cả tòa án. Nhưng thật may mắn Jeffrey Wigand không đơn độc một mình, anh được sự giúp đỡ nhiệt tình của nhà báo Lowell Bergman (Al Pacino).</p>', 'Full', 1, 'single', 'completed', 14, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Al Pacino","avatar":""},{"name":"Russell Crowe","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Diane Venora","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Lindsay Crouse","avatar":""},{"name":"Debi Mazar","avatar":""},{"name":"Stephen Tobolowsky","avatar":""},{"name":"Colm Feore","avatar":""},{"name":"Bruce McGill","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Rip Torn","avatar":""},{"name":"Lynne Thigpen","avatar":""},{"name":"Hallie Eisenberg","avatar":""},{"name":"Michael Paul Chan","avatar":""},{"name":"Linda Har","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324536);
