INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-cua-phi-hanh-gia', 'Vợ Của Phi Hành Gia', 'The Astronaut''s Wife', 'https://phimimg.com/upload/vod/20231016-1/70911548c79bc6e3ff9946e83b49248e.jpg', 'https://phimimg.com/upload/vod/20231016-1/37f7cd10d79fd12c7c70e4bd6a32a992.jpg', '<p>Khi phi hành gia Spencer Armacost trở về Trái đất sau một nhiệm vụ suýt phải trả giá bằng mạng sống, anh quyết định nhận một công việc bàn giấy để được gặp người vợ xinh đẹp của mình, Jillian, thường xuyên hơn. Dần dần, Jillian nhận thấy tính cách của Spencer dường như đã thay đổi, nhưng mối lo lắng của cô giảm dần khi cô phát hiện ra mình có thai. Khi Jillian sắp trở thành mẹ, mối nghi ngờ của cô về Spencer lại quay trở lại. Tại sao cứ như thể anh ấy là một người khác vậy?</p>', 'Full', 1, 'single', 'completed', 19, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Joe Morton","avatar":""},{"name":"Clea DuVall","avatar":""},{"name":"Nick Cassavetes","avatar":""},{"name":"Donna Murphy","avatar":""},{"name":"Gary Grubbs","avatar":""},{"name":"Blair Brown","avatar":""},{"name":"Tom Noonan","avatar":""},{"name":"Tom O''Brien","avatar":""},{"name":"Lucy Lin","avatar":""},{"name":"Michael Crider","avatar":""},{"name":"Samantha Eggar","avatar":""},{"name":"Rondi Reed","avatar":""},{"name":"Conrad Bachmann","avatar":""},{"name":"Sarah Dampf","avatar":""},{"name":"Charles Lanyer","avatar":""},{"name":"Gary Carlos C","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324536);
