INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-cuong-phong', 'Võ Sĩ Cuồng Phong', 'The Hurricane', 'https://phimimg.com/upload/vod/20231016-1/14bd9680aa6354bdd7ef94953884534a.jpg', 'https://phimimg.com/upload/vod/20231016-1/b310c63936116790cd15f7a6ad700637.jpg', '<p>The Hurricane là biệt hiệu của tay box nhà nghề Rubin Carter, một người Mỹ da đen đã vượt qua nhiều khó khăn để trở thành nhà vô địch đấm bốc hạng trung. Tuy nhiên anh phải ngồi tù oan suốt 20 năm vì bị kết tội nhầm là giết người. Bộ phim lên án tệ phân biệt chủng tộc tại một đất nước luôn kêu gọi tự do đã làm tan vỡ bao giấc mơ tốt đẹp của con người.</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Vicellous Shannon","avatar":""},{"name":"Deborah Kara Unger","avatar":""},{"name":"Liev Schreiber","avatar":""},{"name":"John Hannah","avatar":""},{"name":"Dan Hedaya","avatar":""},{"name":"Debbi Morgan","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"David Paymer","avatar":""},{"name":"Harris Yulin","avatar":""},{"name":"Rod Steiger","avatar":""},{"name":"Badja Djola","avatar":""},{"name":"Vincent Pastore","avatar":""},{"name":"Al Waxman","avatar":""},{"name":"David Lansbury","avatar":""},{"name":"Garland Whitt","avatar":""},{"name":"Chuck Cooper","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
