INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-chon-xua', 'Trở Lại Chốn Xưa', 'The Cider House Rules', 'https://phimimg.com/upload/vod/20231016-1/c31e82d32f6eeb4307179064d271b83c.jpg', 'https://phimimg.com/upload/vod/20231016-1/0344c7e88480c40afee44ce834970cee.jpg', '<p>The Cider House Rules được dàn dựng theo nội dung cuốn tiểu thuyết cùng tên (phát hành vào năm 1985) của nhà văn John Irving. Nhà văn chấp nhận viết kịch bản cho dự án với điều kiện đạo diễn tuyển vai để con trai ông, Colin Irving, đóng nhân vật Wally Worthington. Tuy nhiên, do quá trình sản xuất kéo dài hơn một thập kỷ (vì thiếu kinh phí) nên vào năm 1999, Colin trở nên quá già so với vai diễn. Cuối cùng, đạo diễn quyết định giao cho anh vai một thiếu tá quân đội Mỹ, người đưa tin của Wally Worthington về gia đình. John Irving cũng đóng một vai phụ trong phim. Ban đầu đạo diễn Phillip Borsos được mời chỉ đạo diễn xuất của phim, nhưng ông qua đời trước khi các nhà sản xuất tìm được nguồn kinh phí. Một đạo diễn có tên Michael Winterbottom được mời thay thế Phillip Borsos, nhưng ông này xin rút lui sau khi biết dự án có thể kéo dài hơn 10 năm và cuối đạo diễn Lasse Hallström đã được chọn.</p>', 'Full', 1, 'single', 'completed', 15, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tobey Maguire","avatar":""},{"name":"Charlize Theron","avatar":""},{"name":"Delroy Lindo","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Jane Alexander","avatar":""},{"name":"Kathy Baker","avatar":""},{"name":"Erykah Badu","avatar":""},{"name":"Kieran Culkin","avatar":""},{"name":"Kate Nelligan","avatar":""},{"name":"Heavy D","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Erik Per Sullivan","avatar":""},{"name":"Paz de la Huerta","avatar":""},{"name":"K. Todd Freeman","avatar":""},{"name":"Evan Parke","avatar":""},{"name":"Jimmy Flynn","avatar":""},{"name":"Lonnie Fa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
