INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-truy-tim-tren-thien-ha', 'Cuộc Truy Tìm Trên Thiên Hà', 'Galaxy Quest', 'https://phimimg.com/upload/vod/20231016-1/c4dcd1089f915f46d038986b2a5b0b33.jpg', 'https://phimimg.com/upload/vod/20231016-1/23f9024bfea97f4415cbb5af9222dcbb.jpg', '<p>Ba ngôi sao hết thời của một loạt phim truyền hình đã ngừng phát sóng đột nhiên bị một nhóm người ngoài hành tinh đưa đến một hành tinh khác. Những người ngoài hành tinh này tin rằng loạt phim truyền hình kia nói về cuộc sống trong tương lai của họ. Trên hành tinh lạ, ba người Trái Đất bất đắc dĩ vướng vào một cuộc chiến không mong muốn.</p>', 'Full', 1, 'single', 'completed', 18, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tim Allen","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"Daryl Mitchell","avatar":""},{"name":"Enrico Colantoni","avatar":""},{"name":"Robin Sachs","avatar":""},{"name":"Jed Rees","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Missi Pyle","avatar":""},{"name":"Patrick Breen","avatar":""},{"name":"Jeremy Howard","avatar":""},{"name":"Sam Lloyd","avatar":""},{"name":"Rainn Wilson","avatar":""},{"name":"J.P. Manoux","avatar":""},{"name":"Dian Bachar","avatar":""},{"name":"Heidi Swedberg","avatar":""},{"name":"Kevi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324536);
