INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-tron-oan-nghiet-2', 'Vòng Tròn Oan Nghiệt 2', 'Ring 2', 'https://phimimg.com/upload/vod/20231016-1/49400a5c6a3f3d9ec03dc7a0370e9eb6.jpg', 'https://phimimg.com/upload/vod/20231016-1/d9190742a624a8aebfbe1503648e8df9.jpg', '<p>RINGU 2 : Trong phần 2 này kể từ sequel Ringu (1998), Mai Takano đang cố gắng để tìm hiểu thêm về cái chết của bạn trai cô, Ryuji. Cô đã sớm nghe được những câu chuyện về một băng video bị ám bởi hồn ma của một gái đã chết nhiều năm trước, tên là Sadako,. Bất cứ ai xem cuốn băng này sẽ chết vào một tuần sau đó. Sau khi điều tra, cô ấy biết rằng con trai của Ryuji, Youichi, đang dần dần có những hành động lạ giống như bị ám bơi Sadako.Mai phải tìm cách để giữ cho mình và Yuuichi không trở thành nạn nhân tiếp theo của Sadako.</p>', 'Full', 1, 'single', 'completed', 17, 1999, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Miki Nakatani","avatar":""},{"name":"Hitomi Sato","avatar":""},{"name":"Kyoko Fukada","avatar":""},{"name":"Fumiyo Kohinata","avatar":""},{"name":"Kenjirou Ishimaru","avatar":""},{"name":"Yurei Yanagi","avatar":""},{"name":"Rikiya Ôtaka","avatar":""},{"name":"Yōichi Numata","avatar":""},{"name":"Masako","avatar":""},{"name":"Miwako Kaji","avatar":""},{"name":"Katsumi Muramatsu","avatar":""},{"name":"Daisuke Ban","avatar":""},{"name":"Rie Ino''o","avatar":""},{"name":"Reita Serizawa","avatar":""},{"name":"Shinmei Tsuji","avatar":""},{"name":"Nanako Matsushima","avatar":""},{"name":"Yoshiko Yura","avatar":""},{"name":"H","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 17846