INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-dua-tinh-ai', 'Trò Đùa Tình Ái', 'Cruel Intentions', 'https://phimimg.com/upload/vod/20231016-1/6d47a125a9c3c5874b560cfdc9338aec.jpg', 'https://phimimg.com/upload/vod/20231016-1/790463844aa89ec373d0b41ddf87e019.jpg', '<p>Sebastian Velmont là một gã thợ săn có bộ mặt thiên thần. Hắn thích chơi bời,đùa nghịch với ái tình. Hắn có thể quyến rũ tất cả, từ một thiếu nữ vị thành niên đến một cô gái trưởng thành và cả bà bác sĩ tâm lý đáng tuổi mẹ mình.&nbsp;</p>', 'Full', 1, 'single', 'completed', 13, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ryan Phillippe","avatar":""},{"name":"Sarah Michelle Gellar","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"Selma Blair","avatar":""},{"name":"Louise Fletcher","avatar":""},{"name":"Joshua Jackson","avatar":""},{"name":"Eric Mabius","avatar":""},{"name":"Sean Patrick Thomas","avatar":""},{"name":"Alaina Reed Hall","avatar":""},{"name":"Hiep Thi Le","avatar":""},{"name":"Deborah Offner","avatar":""},{"name":"Tara Reid","avatar":""},{"name":"Drew Snyder","avatar":""},{"name":"Herta Ware","avatar":""},{"name":"Swoosie Kurtz","avatar":""},{"name":"Christine Baranski","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324536);
