INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-linh-dan-ong', 'Bản Lĩnh Đàn Ông', 'Gorgeous', 'https://phimimg.com/upload/vod/20231016-1/90b94b687ee23c8c66a99e2a4c61c371.jpg', 'https://phimimg.com/upload/vod/20231016-1/fd2656b2c48e6ce54bd1ef8d596ded57.jpg', '<p>Gorgeous nói về chuyện tình cảm của một cô gái làng chài.Khi Ah Bu, cô gái sống tại một làng chài viên biển ở Đài Loan,tình cờ nhặt được chai thủy tinh mà bên trong có chứa một thông điệp lãng mạn, cô liền đến Hồng Kông với hy vọng tìm được chàng trai trong mộng của mình. Và cuối cùng bạch mã hoàng tử của cô ấy, Albert, lại là một người đồng tính. Nhưng mọi chuyện vẫn không quá tồi tệ khi cô ấy gặp được Chi Wu. Trong khi đó, bạn trai của Ah Bu tại quê nhà lại đến Hồng Kông tìm và làm mọi cách để cô quay trở về Đài Loan...</p>', 'Full', 1, 'single', 'completed', 20, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Wakin Chau","avatar":""},{"name":"Bradley James Allan","avatar":""},{"name":"Richie Jen","avatar":""},{"name":"Lau Yee Tat","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Chan Chung-Yung","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Jo Kuk Cho-Lam","avatar":""},{"name":"Sandra Ng Kwun-Yu","avatar":""},{"name":"Annie Wu","avatar":""},{"name":"William Chan Yuk-Choh","avatar":""},{"name":"Jacqueline Li","avatar":""},{"name":"Eileen Tung","avatar":""},{"name":"Stephen Chow","avatar":""},{"name":"Carmen S","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"