INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-quai-ac', 'Trò Chơi Quái Ác', 'eXistenZ', 'https://phimimg.com/upload/vod/20231016-1/bd78697be572d4fb6e4a0e8f3ae05068.jpg', 'https://phimimg.com/upload/vod/20231016-1/5216f4f7eec39e71a61445fdd6e440fd.jpg', '<p>Allegra là một trong những nhà thiết kế trò chơi điện tử hàng đầu trên toàn thế giới. Cô và các cộng sự đang cùng nhau kiểm tra lại trò chơi thực tế ảo mới nhất trước khi chính thức tung ra thị trường. Trong trò chơi thực tế mang tên eXistenZ, người chơi phải gắn một thiết bị điều khiển vào sống lưng của mình để các tín hiệu có thể kết nối trực tiếp lên não. Bằng cách đó, họ sẽ được trải qua những sự kiện trong trò chơi với đầy đủ những cảm xúc hệt như một người trong cuộc. Khi Allegra đang đắm mình trong trò chơi thì một kẻ lạ mặt từ hàng ghế khán giả đã bất ngờ xuất hiện trên sân khấu và nã đạn ám sát Allegra.</p>', 'Full', 1, 'single', 'completed', 20, 1999, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Ian Holm","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Don McKellar","avatar":""},{"name":"Callum Keith Rennie","avatar":""},{"name":"Christopher Eccleston","avatar":""},{"name":"Sarah Polley","avatar":""},{"name":"Robert A. Silverman","avatar":""},{"name":"Oscar Hsu","avatar":""},{"name":"Kris Lemche","avatar":""},{"name":"Vik Sahay","avatar":""},{"name":"Kirsten Johnson","avatar":""},{"name":"James Kirchner","avatar":""},{"name":"Balázs Koós","avatar":""},{"name":"Stephanie Belding","avatar":""},{"name":"Gerry","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324536);
