INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-dieu-thien-nien-ky-2000', 'Giai Điệu Thiên Niên Kỷ 2000', 'Fantasia 2000', 'https://phimimg.com/upload/vod/20231016-1/b35dfd8a259696afae9b61278f41e1d4.jpg', 'https://phimimg.com/upload/vod/20231016-1/81fc7d09cbb66d39bcd3f48dc2f4f00c.jpg', '<p>Bộ phim là sự kết hợp tuyệt vời giữa hình ảnh hoạt hình và các tác phẩm của nhạc cổ điển như “Symphony No.5” của Beethoven với điệu nhảy linh hoạt của đàn bướm hay “Piano Concerto No.2, Allergo, Opus 102” của Dmitri Shostakovich với câu chuyện cảm động của vịt Donal đã cứu thế giới loài vật thoát khỏi trận lụt hay một đoạn rất vui nhộn “Rhapsody in blue” của George Gershwin với những chú hồng hạc thật dễ thương...</p>', 'Full', 1, 'hoathinh', 'completed', 21, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Martin","avatar":""},{"name":"Itzhak Perlman","avatar":""},{"name":"Quincy Jones","avatar":""},{"name":"Bette Midler","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"Penn Jillette","avatar":""},{"name":"Teller","avatar":""},{"name":"James Levine","avatar":""},{"name":"Angela Lansbury","avatar":""},{"name":"Wayne Allwine","avatar":""},{"name":"Tony Anselmo","avatar":""},{"name":"Russi Taylor","avatar":""},{"name":"Chicago Symphony Orchestra","avatar":""},{"name":"Hendel Butoy","avatar":""},{"name":"Eric Goldberg","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324536);
