INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-thuoc-phim-toi-loi', 'Những Thước Phim Tội Lỗi', '8MM', 'https://phimimg.com/upload/vod/20231016-1/8ddb9dce9df126c635233748cc48c940.jpg', 'https://phimimg.com/upload/vod/20231016-1/15dabe77bd64fd0306ce3fdc49e83d69.jpg', '<p>Thám tử tư Tom Welles nhận lời một quả phụ giàu có điều tra nguồn gốc đoạn băng 8mm nằm trong két sắt của ông chồng vừa qua đời. Đó là hình ảnh một bé gái bị hành hạ và làm nhục. Tom thu lượm thông tin từ những người quen. Từ các đầu mối hé mở một đường dây tội ác bẩn thỉu. Cuộc sống Tom rơi vào khủng hoảng khi anh ngày càng dấn thân vào cuộc điều tra tìm ra thủ phạm. Dường như đó là một văn phòng hãng phim ở Hollywood.</p>', 'Full', 1, 'single', 'completed', 16, 1999, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Joaquin Phoenix","avatar":""},{"name":"James Gandolfini","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Anthony Heald","avatar":""},{"name":"Chris Bauer","avatar":""},{"name":"Catherine Keener","avatar":""},{"name":"Myra Carter","avatar":""},{"name":"Amy Morton","avatar":""},{"name":"Norman Reedus","avatar":""},{"name":"Jenny Powell","avatar":""},{"name":"Anne Gee Byrd","avatar":""},{"name":"Jack Betts","avatar":""},{"name":"Luis Oropeza","avatar":""},{"name":"Rachel Singer","avatar":""},{"name":"Don Creech","avatar":""},{"name":"Fran Bennett","avatar":""},{"name":"Wilma Bo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324536);
