INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-chuot-sieu-quay', 'Chú Chuột Siêu Quậy', 'Stuart Little', 'https://phimimg.com/upload/vod/20231015-1/97a582b5d8418f1289655ff76b5a98bb.jpg', 'https://phimimg.com/upload/vod/20231015-1/92c8562cb77e3a2d87e5411fbb9f8461.jpg', '<p>Cuộc phiêu lưu của chú chuột dũng cảm và dũng cảm tên là Stuart Little với những phẩm chất con người, người phải đối mặt với một số tai nạn hài hước khi sống với một gia đình loài người khi còn là con của họ.</p>', 'Full', 1, 'single', 'completed', 19, 1999, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Michael J. Fox","avatar":""},{"name":"Geena Davis","avatar":""},{"name":"Hugh Laurie","avatar":""},{"name":"Jonathan Lipnicki","avatar":""},{"name":"Nathan Lane","avatar":""},{"name":"Chazz Palminteri","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Jim Doughan","avatar":""},{"name":"David Alan Grier","avatar":""},{"name":"Bruno Kirby","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324536);
