INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('deuce-bigalow-trai-bao', 'Deuce Bigalow: Trai Bao', 'Deuce Bigalow: Male Gigolo', 'https://phimimg.com/upload/vod/20231015-1/29e287c0e9264cb3edf3421fdc1bdd92.jpg', 'https://phimimg.com/upload/vod/20231015-1/9c3c01b7168b42da6a6b41a034edb52f.jpg', '<p>Deuce Bigalow là một người dọn dẹp bể cá kém hấp dẫn, kém may mắn. Một ngày nọ, anh ta phá hỏng ngôi nhà của một gã trai bao và cần tiền nhanh chóng để sửa chữa nó. Cách duy nhất mà anh ấy có thể làm được là trở thành một gã trai bao, đảm nhận một nhóm khách hàng nữ bất thường. Tuy nhiên, anh ấy gặp phải một số vấn đề. Anh ta phải lòng một trong những khách hàng kỳ lạ của mình và một sĩ quan cảnh sát nhếch nhác đang theo đuổi anh ta.</p>', 'Full', 1, 'single', 'completed', 15, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rob Schneider","avatar":""},{"name":"William Forsythe","avatar":""},{"name":"Eddie Griffin","avatar":""},{"name":"Arija Bareikis","avatar":""},{"name":"Oded Fehr","avatar":""},{"name":"Gail O''Grady","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"Jacqueline Obradors","avatar":""},{"name":"Big Boy","avatar":""},{"name":"Amy Poehler","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324536);
