INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-wars-phan-1-hiem-hoa-bong-ma', 'Star Wars:  Phần 1 - Hiểm Họa Bóng Ma', 'Star Wars: Episode I - The Phantom Menace', 'https://phimimg.com/upload/vod/20231015-1/5e24f275c25d77c25e27dc2de618c54f.jpg', 'https://phimimg.com/upload/vod/20231015-1/f5892a22c96a8e04935ffc87abafa851.jpg', '<p>Naboo, một hành tinh yên bình dưới sự trị vì của nữ hoàng trẻ và sáng suốt Amidala, đang bị đe doạ bởi phái Trade Federation, những hình nộm che mắt cho chúa tể Sith và đệ tử của hắn, Darth Maul. Thống đốc Palpatine là quân sư chính cho nữ hoàng, cho dù có nhiều nghi ngờ xung quanh ông. Hiệp sĩ Jedi Qui-Gon Jinn và Obi-Wan Kenobi được gọi đến để can thiệp vào cuộc hỗn chiến này. Trên đường đi, họ thu nhận thêm đệ tử Anakin Skywalker, người sau này trở thành Darth Vader...</p>', 'Full', 1, 'single', 'completed', 17, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Ewan McGregor","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Jake Lloyd","avatar":""},{"name":"Ian McDiarmid","avatar":""},{"name":"Pernilla August","avatar":""},{"name":"Oliver Ford Davies","avatar":""},{"name":"Hugh Quarshie","avatar":""},{"name":"Ahmed Best","avatar":""},{"name":"Anthony Daniels","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324536);
