INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('star-wars-phan-1-hiem-hoa-bong-ma', 'Star Wars:  Phần 1 - Hiểm Họa Bóng Ma', 'Star Wars: Episode I - The Phantom Menace', 'star wars:  phần 1 - hiểm họa bóng ma star wars: episode i - the phantom menace liam neeson ewan mcgregor natalie portman jake lloyd ian mcdiarmid pernilla august oliver ford davies hugh quarshie ahmed best anthony daniels ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-com-trom-kim-cuong', 'Tên Cớm Trộm Kim Cương', 'Blue Streak', 'https://phimimg.com/upload/vod/20231015-1/b68642a5b0f0b0e7bbaea10069ecd35c.jpg', 'https://phimimg.com/upload/vod/20231015-1/abe6b5b3b3c3cd08f9b58b0843ab5fde.jpg', '<p>Kẻ Trộm Kim Cương, Blue Streak xoay quanh về cuộc phiêu lưu đầy hài hước của Miles Logan một tên trộm chuyên nghiệp. Trong một phi vụ đánh cắp viên kim cương trị giá 17 triệu đôla, Miles đã bị Deke lừa bịp để một mình hắn độc chiếm món hàng. Người bạn của Miles bị giết chết và cảnh sát đã bắt được Miles, nhưng anh đã nhanh trí giấu viên kim cương ở đường ống thông hơi trong một tòa nhà gần đó.Sau hai năm ở tù, Miles quyết tâm lấy lại viên kim cương và tìm cách trả thù kẻ phản bội. Nhưng toà nhà mà anh cất giấu báu vật giờ đây đã trở thành Sở cảnh sát Los Angeles. Một phi vụ mới bắt đầu...</p>', 'Full', 1, 'single', 'completed', 18, 1999, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Martin Lawrence","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Dave Chappelle","avatar":""},{"name":"Peter Greene","avatar":""},{"name":"Nicole Ari Parker","avatar":""},{"name":"William Forsythe","avatar":""},{"name":"Graham Beckel","avatar":""},{"name":"Robert Miranda","avatar":""},{"name":"Olek Krupa","avatar":""},{"name":"Saverio Guerra","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324536);
