INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('10-dieu-em-ghet-anh', '10 Điều Em Ghét Anh', '10 Things I Hate About You', 'https://phimimg.com/upload/vod/20231015-1/cdc22b0fd43fced9752ffbe7eae92895.jpg', 'https://phimimg.com/upload/vod/20231015-1/73f72e67e409cfdb05a93ce22f009194.jpg', '<p>Vừa chuyển tới trường mới, anh chàng Cameron đã phải lòng Bianca - cô nàng hot nhất trường. Tuy nhiên, Bianca chỉ được phép hẹn hò khi cô chị gái mọt sách khó tính Kat có người rủ đi chơi trước. Và Patrick - một tay&nbsp;</p>', 'Full', 1, 'single', 'completed', 14, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Heath Ledger","avatar":""},{"name":"Julia Stiles","avatar":""},{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Larisa Oleynik","avatar":""},{"name":"David Krumholtz","avatar":""},{"name":"Andrew Keegan","avatar":""},{"name":"Susan May Pratt","avatar":""},{"name":"Gabrielle Union","avatar":""},{"name":"Larry Miller","avatar":""},{"name":"Daryl Mitchell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
