INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('10-dieu-em-ghet-anh', '10 Điều Em Ghét Anh', '10 Things I Hate About You', '10 điều em ghét anh 10 things i hate about you heath ledger julia stiles joseph gordon-levitt larisa oleynik david krumholtz andrew keegan susan may pratt gabrielle union larry miller daryl mitchell ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('robot-khong-lo', 'Robot Khổng Lồ', 'The Iron Giant', 'https://phimimg.com/upload/vod/20231015-1/1c8538e4fed966142630f8185d68a915.jpg', 'https://phimimg.com/upload/vod/20231015-1/3770720293cc6e4bef40cd88503c1dce.jpg', '<p>Lấy bối cảnh thập niên 50 khi mà cuộc &quot;chiến tranh lạnh&quot; giữa hai cường quốc Liên Xô và Mỹ đang đến hồi gây cấn, hai phe biểu dương sức mạnh bằng các vệ tinh được đưa lên không gian để rình rập. Tại một thị trấn nhỏ ven biển của Mỹ, dân cư tuy sống êm đềm nhưng cũng không tránh khỏi sự sợ hãi một ngày nào đó sẽ xảy ra chiến tranh tàn khốc. Hogarth Hughes là một cậu bé như các trẻ khác cùng lứa thời đó, rất hiếu động, tò mò, thích xem các phim kinh dị trên TV, mê đọc các truyện tranh viễn tưởng... Một đêm mưa gió nọ, ngoài khơi sấm chớp đầy trời bỗng có luồng lửa từ trên trời đâm thẳng xuống biển... sáng hôm sau dân cư bàn tán đó có thể là một vệ tinh của &quot;địch&quot; hay vật thể lạ từ sao Hoả rớt xuống! Lòng tò mò hôi thúc, tối đó cậu bé Hogarth trốn mẹ vào rừng để điều tra... Một cuộc gặp gỡ bất ngờ diễn ra giữa Hogarth và một... người máy khổng lồ cao cả mấy chục mét.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Vin Diesel","avatar":""},{"name":"Eli Marienthal","avatar":""},{"name":"Jennifer Aniston","avatar":""},{"name":"Harry Connick Jr.","avatar":""},{"name":"James Gammon","avatar":""},{"name":"Cloris Leachman","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"John Mahoney","avatar":""},{"name":"M. Emmet Walsh","avatar":""},{"name":"Jack Angel","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324536);
