INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-sy-khong-dau', 'Kỵ Sỹ Không Đầu', 'Sleepy Hollow', 'https://phimimg.com/upload/vod/20231014-1/021802d06c5302d35849dab5c8b254cb.jpg', 'https://phimimg.com/upload/vod/20231014-1/cb50f4610190c0db2c07e7f5a4cd2432.jpg', '<p>Ichabod Crane là một nhà đầu tư ở New York được giao điều tra các vụ án mạng xảy ra liên tục tại một thung lũng hẻo lánh nọ mà các nạn nhân đều bị chặt đầu đem đi mất. Những người dân địa phương cho rằng đó là việc làm của bóng ma kỵ sĩ không đầu, nhưng Crane không tin. Và dường như anh ta sẽ tìm ra sự thật... và những cái đầu sẽ rơi xuống....</p>', 'Full', 1, 'single', 'completed', 20, 1999, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Christina Ricci","avatar":""},{"name":"Miranda Richardson","avatar":""},{"name":"Michael Gambon","avatar":""},{"name":"Casper Van Dien","avatar":""},{"name":"Jeffrey Jones","avatar":""},{"name":"Richard Griffiths","avatar":""},{"name":"Ian McDiarmid","avatar":""},{"name":"Michael Gough","avatar":""},{"name":"Christopher Walken","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324536);
