INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-xanh', 'Dặm Xanh', 'The Green Mile', 'https://phimimg.com/upload/vod/20231014-1/1b8634b208fb5ad6516f8c733775734f.jpg', 'https://phimimg.com/upload/vod/20231014-1/daa0a2be375d2f917aaa6a001c8cefca.jpg', '<p>Bộ phim là câu chuyện hồi tưởng của một viên coi ngục cai quản những tên tử tù bất trị đang chờ ngày ngồi lên ghế điện trả giá cho những tội ác mà chúng gây ra. Cuộc sống của ông thay đổi hoàn toàn kể từ khi một người tù da đen có khả năng kì lạ xuất hiện trong ngục của ông...</p>', 'Full', 1, 'single', 'completed', 18, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"David Morse","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Michael Jeter","avatar":""},{"name":"Doug Hutchison","avatar":""},{"name":"Sam Rockwell","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Graham Greene","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324536);
