INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-rung-xanh-1999', 'Cậu Bé Rừng Xanh', 'Tarzan', 'https://phimimg.com/upload/vod/20231014-1/c394301783a06f08edafda3988e20b48.jpg', 'https://phimimg.com/upload/vod/20231014-1/532908ece2049c1b4b3dc5abf1c46587.jpg', '<p>Cậu Bé Rừng Xanh là bộ phim phỏng theo tác phẩm nổi tiếng Tarzan of the Apes của Edgar Rice Burroughs, do hãng phim Walt Disney sản xuất.Bộ phim bắt đầu với tai nạn đắm tàu của Tarzan và cha mẹ. Họ dạt vào một hoang đảo ở châu Phi đầy thú dữ. Sau khi mất cả hai người thân vì báo Sabor, cậu bé được khỉ mẹ Karla, con khỉ vừa mất con vì Sabor, cứu sống. Karla đem cậu bé về, đặt tên và nuôi như con đẻ. Dù vậy, Tarzan chưa bao giờ có được tình yêu của đầu đàn Kerchak. Tarzan lớn lên trong sự khác biệt với bầy đàn, cậu chỉ có Terk, con khỉ béo ị và Tantor, con voi nhát cáy làm bạn.Cuộc sống của Tarzan cứ mãi hoang dã như vậy nếu không có một ngày đoàn thám hiểm nghiên cứu giống khỉ đột của giáo sư Porter xuất hiện ở cánh rừng già này. Cùng đi ...</p>', 'Full', 1, 'hoathinh', 'completed', 21, 1999, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tony Goldwyn","avatar":""},{"name":"Minnie Driver","avatar":""},{"name":"Glenn Close","avatar":""},{"name":"Alex D. Linz","avatar":""},{"name":"Rosie O''Donnell","avatar":""},{"name":"Brian Blessed","avatar":""},{"name":"Nigel Hawthorne","avatar":""},{"name":"Lance Henriksen","avatar":""},{"name":"Wayne Knight","avatar":""},{"name":"Taylor Dempsey","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324536);
