INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-be-rung-xanh-1999', 'Cậu Bé Rừng Xanh', 'Tarzan', 'cậu bé rừng xanh tarzan tony goldwyn minnie driver glenn close alex d. linz rosie o''donnell brian blessed nigel hawthorne lance henriksen wayne knight taylor dempsey ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-giai-tri', 'Vua Giải Trí', 'The Lord of Amusement', 'null', 'https://phimimg.com/upload/vod/20231012-1/a3091bcfb0d708650b376b32c1178320.jpg', '<p>Yang Qianhua (do Zhang Jiahui thủ vai) lần đầu tiên đến Hồng Kông và tị nạn cùng với dì của mình, người sở hữu một hộp đêm và làm bồi bàn. Trong hộp đêm, người quản lý chú Chang (do Ng Meng-tat thủ vai) và Anh Pao (do Ng Zhenyu thủ vai) chia sẻ thế giới một cách bình đẳng. Có rất nhiều truyền thuyết về Anh Pao lưu truyền trên thế giới, và Qianhua coi Anh Pao là thần tượng của mình. Anh Pao luôn yêu vũ công Qiqi (do Yao Leyi thủ vai), nhưng Qiqi không thể chịu đựng được tính khí nóng nảy của người cũ và cuối cùng đã chọn cách rời đi. Lợi dụng sự chán nản của anh Pao, chú Chang đã lên kế hoạch trục xuất anh Pao và hộp đêm rơi vào tay chú Chang. Sau khi Pao anh rời đi, chú Chang đã nảy ra ý tưởng với Qianhua, nhưng Qianhua vô tội đã vô tình rơi vào bẫy của chú Chang và cuối cùng mắc phải một khoản nợ khổng lồ. Qianhua, người đang sống trên phố, tình cờ gặp Pao Ge, cả hai đều đầy phẫn nộ khi nói về chú Chang. Để trả thù và lấy lại tình yêu đã mất, Qianhua và Brother Pao quyết định hợp lực để tiêu diệt Bác Chang.</p>', 'Full', 1, 'single', 'completed', 17, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Francis Ng","avatar":""},{"name":"Nick Cheung","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Lee Lik-Chi","avatar":""},{"name":"Elle Choi","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Sherming Yiu","avatar":""},{"name":"Alvina Kong Yan-Yin","avatar":""},{"name":"Baat Leung-Gam","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324536);
