INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bip-dai-chien-las-vegas', 'Vua Bịp Đại Chiến Las Vegas', 'The Conmen In Vegas', 'https://phimimg.com/upload/vod/20231010-1/c4e05e88ae9e8b08842371fd6acafa7b.jpg', 'https://phimimg.com/upload/vod/20231010-1/dd0c0a50692e7ae51f35e05cb92fe80f.jpg', '<p>Trong phim Vua Bịp Đại Chiến Las Vegas, Vua cờ bạc, Vương (Andy Lau-Lưu Đức Hoa), và anh bạn Long gày trơ xương (Nick Cheung-Trương Gia Huy), cùng với em họ Long là Smarty (Chan Pak Cheung-Trần Bách Tường ), lừa đảo một số tiền lớn từ sòng bạc ngầm của Man Đại Nhãn đồi bại. Khi bộ ba sắp sửa tận hưởng số tiền dễ dàng lừa được thì băng của Man lộ diện và bắt được Long. Vương và Smarty được đưa đến gặp các quan chức cao cấp của Trung Quốc, họ giục hai người tới Las Vegas bắt một kẻ lừa đảo tên là Peter Chu (Man Chi Leung-Vạn Tử Lương).</p>', 'Full', 1, 'single', 'completed', 14, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Nick Cheung","avatar":""},{"name":"Natalis Chan","avatar":""},{"name":"Kelly Lin","avatar":""},{"name":"Yu Fang","avatar":""},{"name":"Alex Man","avatar":""},{"name":"Jewel Lee","avatar":""},{"name":"Nam Yin","avatar":""},{"name":"Wong Jing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324536);
