INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-su-giang-ho', 'Luật Sư Giang Hồ', 'Queen''s Bench 3', 'https://phimimg.com/upload/vod/20231010-1/58ddcdaf8a7c8a24a3af0a8e64c036f5.jpg', 'https://phimimg.com/upload/vod/20231010-1/9d87388ef7ae9d177f7d64924f743b60.jpg', '<p>Sau khi thu về 20 triệu đô la Hồng Kông ở phòng vé với bộ phim hài ăn khách Her Fatal Ways năm 1990, bộ ba vàng gồm Lương Gia Huy, Carol Cheng (&quot;Dodo&quot;) và Trương Quốc Vinh trở lại vào cuối năm đó với một người chiến thắng khác trong Queen&#39;s. Ghế III. Bên cạnh việc viết kịch bản, đạo diễn và sản xuất, Alfred Cheung tài năng còn đóng vai chính trong bộ phim truyền hình về phòng xử án với vai Chang, một luật sư trẻ đầy tham vọng, người đảm nhận vụ án khó bào chữa cho Fai (Lương Triều Vỹ), một người đàn ông bị buộc tội giết một cô gái trong rừng. . Chang tin rằng Fai vô tội, nhưng liệu anh có thể cứu được người đàn ông và tóm được thủ phạm thực sự với công tố viên phản bội Fang (nhân vật phản diện trên màn ảnh Sunny Fang Kang) ở phe đối lập? May mắn thay, Chang nhận được sự giúp đỡ từ Carrie Ng với tư cách là một luật sư đồng nghiệp, Carina Lau trong vai bạn gái của Fai và một nhân chứng, và Dodo, người xuất hiện với tư cách khách mời với tư cách là dì của Chang.</p>', 'Full', 1, 'single', 'completed', 18, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Alfred Cheung Kin-Ting","avatar":""},{"name":"Carrie Ng","avatar":""},{"name":"Sunny Fang Kang","avatar":""},{"name":"Carol Cheng","avatar":""},{"name":"Terrence Fok","avatar":""},{"name":"Wai Ching","avatar":""},{"name":"Lau Chin-Dai","avatar":""},{"name":"Chan Yau-Hau","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf