INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-ma-hoang-tu', 'Hắc Mã Hoàng Tử', 'Prince Charming', 'https://phimimg.com/upload/vod/20231010-1/85c1e85c34153fbfb8f14651d268ce8c.jpg', 'https://phimimg.com/upload/vod/20231010-1/7b9690be2663a6ccec806dd3d3b4fdb0.jpg', '<p>Một người đàn ông phải lòng một cô gái đến từ Thượng Hải, người đến Hồng Kông để tìm người mẹ thất lạc đã lâu, nhưng vấn đề nảy sinh khi người cha giàu có của cô cho rằng cô đã bị bắt cóc.</p>', 'Full', 1, 'single', 'completed', 19, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Michelle Reis","avatar":""},{"name":"Deanie Ip","avatar":""},{"name":"Suki Kwan","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Nick Cheung","avatar":""},{"name":"Jimmy Wong Shu-Kei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324536);
