INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-tinh-ao-mong', 'Ái Tình Ảo Mộng', 'Fascination Amour', 'null', 'https://phimimg.com/upload/vod/20231008-1/ee58b019d01e37ea2d51760dc6a423c1.jpg', '<p>Lau là một tay chơi hư hỏng đang ở bên vị hôn thê số 8 - và tạo ra một trò đùa để loại bỏ họ. Cùng với đoàn tùy tùng của mình (bao gồm cả Anthony Wong vui tính) đi cùng, anh lên tàu du lịch Fascination với ý định loại bỏ bản thân khỏi sự sắp đặt mới nhất của mình. Tuy nhiên, anh không tính đến việc phải lòng nữ thừa kế Sandy, người - không có gì ngạc nhiên ở đây - cô gái duy nhất có thể chịu được thái độ “tiền mua được tất cả” của anh. Mọi chuyện không đơn giản như vậy - cô ấy đang đánh mất tài sản và không để tiền mua được mình. Lau phải chứng minh rằng anh có thể là một chàng trai bình thường nên anh theo cô lên bờ với chiếc ba lô và 10 đô la trong túi.</p>', 'Full', 1, 'single', 'completed', 21, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Hikari Ishida","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Lillian Ho","avatar":""},{"name":"Raymond Wong","avatar":""},{"name":"Qu Ying","avatar":""},{"name":"Huang Lei","avatar":""},{"name":"Christine Ng","avatar":""},{"name":"Astrid Chan","avatar":""},{"name":"James Ha Chim-Si","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324536);
