INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-dem-he', 'Ác Mộng Đêm Hè', 'Erotic Nightmare', 'https://phimimg.com/upload/vod/20230922-1/71053fe48239d1f59c10189325496307.jpg', 'https://phimimg.com/upload/vod/20230922-1/504d76f47f1be083e5bd66cf53b18f9a.jpg', '<p>Huỳnh Thu Sanh vào vai một gã đàn ông thiếu thốn đời sống tình dục. Đến gặp thầy pháp, ông được ban cho những giấc mơ ân ái hàng đêm. Ông dần nghiện mơ và si mê một trong những cô gái hay gặp trong giấc mơ của mình. Không may, những giấc mơ ngọt ngào đó là một phần âm mưu của lão thầy pháp, nhằm nắm bắt tâm hồn ông ta…</p>', 'Full', 1, 'single', 'completed', 21, 1999, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Anthony Wong","avatar":""},{"name":"Eric Wan","avatar":""},{"name":"Pinky Cheung","avatar":""},{"name":"Berg Ng","avatar":""},{"name":"Kei Heung","avatar":""},{"name":"Mak King-Ting","avatar":""},{"name":"Alannah Ong","avatar":""},{"name":"Sunny Luk Kim-Ching","avatar":""},{"name":"Le Rong-Rong","avatar":""},{"name":"Siu Ling Wong","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324536);
