INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-banh-trung', 'Hoàng Tử Bánh Trứng', 'The Lucky Guy', 'https://phimimg.com/uploads/movies/20260713/hoang-tu-banh-trung-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/hoang-tu-banh-trung-poster.webp', '<p>The Lucky Guy (1998) - Hoàng Tử Bánh Trứng nói về một chàng trai đẹp trai nhưng nghèo khó, anh ta luôn muốn nổi bật so với mọi người bằng cách thuê người diễn tuồng để nâng anh ta lên thành một anh chàng đệ nhất cao thủ sát gái trong mắt mọi người, làm cho mọi người thần tượng anh ta. Nhưng mọi thứ có nguy cơ chấm hết khi Tiệm cà phê Lucky nơi anh làm việc sẽ phải đối mặt với nguy cơ đóng cửa..</p>', 'Full', 1, 'single', 'completed', 29, 1998, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Eric Kot Man-Fai","avatar":""},{"name":"Daniel Chan Hiu-Tung","avatar":""},{"name":"Sammi Cheng Sau-Man","avatar":""},{"name":"Kristy Yang Gongru","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Sandra Ng Kwan-Yu","avatar":""},{"name":"Tenky Tin Kai-Man","avatar":""},{"name":"Cheng Man-Fai","avatar":""},{"name":"Lee Siu-Kay","avatar":""},{"name":"Vincent Kok Tak-Chiu","avatar":""},{"name":"Joyce Chan Yin-Hang","avatar":""},{"name":"Lee Kin-Yan","avatar":""},{"name":"Mei Yee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["식신2: 럭키 가이","幸运一条龙","럭키 가이","럭키가이","行運一條龍"]', 1784690324536);
