INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-ai', 'Tôi Là Ai?', 'Who Am I?', 'https://phimimg.com/uploads/movies/20260710/toi-la-ai-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/toi-la-ai-poster.webp', '<p>Thành Long vào vai một điệp viên mật bị mất trí sau khi nhảy xuống khỏi một chiếc trực thăng. Không những thế, anh còn bị truy sát bởi một nhóm người mà anh không biết tại sao mình lại bị chúng truy đuổi... Bằng những kỹ năng tuyệt đỉnh của mình. Liệu anh có tìm lại được con người thật của mình và chiến thắng những kẻ truy sát?</p>', 'Full', 1, 'single', 'completed', 52, 1998, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Michelle Ferre","avatar":""},{"name":"Mirai Yamamoto","avatar":""},{"name":"Ron Smerczak","avatar":""},{"name":"Ed Nelson","avatar":""},{"name":"Ton Pompert","avatar":""},{"name":"Glory Simon","avatar":""},{"name":"Fred van Ditmarsch","avatar":""},{"name":"Fritz Krommenhoek","avatar":""},{"name":"Dick Rienstra","avatar":""},{"name":"Rinaldo van Ommeren","avatar":""},{"name":"Pim Daane","avatar":""},{"name":"Jeremiah Fleming","avatar":""},{"name":"Nell Berger","avatar":""},{"name":"Dik Brinksma","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jackie Chan''s Who Am I?","¿Quién soy?","성룡의 C.I.A","Jackie Chan perd la mémoire","Ngo si seoi","Shuki? de Jackie Chan","Wo shi shui","Jackie Chanin Taistele!","Qui suis-je?","An thymitheis... pethanes","Preziveli komandos","Who am I","Quem Sou Eu?","我是誰"]', 1784690324536);
