INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-la-ai', 'Tôi Là Ai?', 'Who Am I?', 'tôi là ai? who am i? jackie chan michelle ferre mirai yamamoto ron smerczak ed nelson ton pompert glory simon fred van ditmarsch fritz krommenhoek dick rienstra rinaldo van ommeren pim daane jeremiah fleming nell berger dik brinksma thành long jackie chan''s who am i? ¿quién soy? 성룡의 c.i.a jackie chan perd la mémoire ngo si seoi shuki? de jackie chan wo shi shui jackie chanin taistele! qui suis-je? an thymitheis... pethanes preziveli komandos who am i quem sou eu? 我是誰', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-giac-mo-tro-thanh-hien-thuc', 'Nơi Giấc Mơ Trở Thành Hiện Thực', 'What Dreams May Come', 'https://phimimg.com/upload/vod/20260619-1/c57825d15fc660fefc7839759eb9ae4c.jpg', 'https://phimimg.com/upload/vod/20260619-1/de3d17cd194bf47bcd2cd36eb222de2e.jpg', '<p>Một cặp vợ chồng cảm thấy thế giới như sụp đổ khi hai đứa con của họ cùng qua đời trong một tai nạn. Vài năm sau, một vụ tai nạn khác tiếp tục cướp đi mạng sống của người chồng. May mắn thay, anh được lên thiên đường. Họ là cặp vợ chồng hết mực yêu thương nhau. Chris Nielsen (Robin Williams) là bác sĩ nhi khoa tại bệnh viện thành phố, còn Annie Collins sở hữu một phòng trưng bày tranh nghệ thuật. Họ có một con trai và một con gái. Chúng đều khỏe mạnh và ngoan ngoãn. Tai họa ập đến khi cả hai đứa chết trong một vụ tai nạn ô tô. Cái chết của con khiến Annie trở nên điên loạn. Cô từng nhiều lần cắt gân tay tự tử nhưng không thành. Chris buộc phải đưa vợ vào bệnh viện tâm thần.</p>', 'Full', 1, 'single', 'completed', 32, 1998, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Annabella Sciorra","avatar":""},{"name":"Josh Paddock","avatar":""},{"name":"Jessica Brooks Grant","avatar":""},{"name":"Max von Sydow","avatar":""},{"name":"Wilma Bonet","avatar":""},{"name":"Lucinda Jenney","avatar":""},{"name":"Rosalind Chao","avatar":""},{"name":"Matt Salinger","avatar":""},{"name":"Maggie McCarthy","avatar":""},{"name":"Carin Sprague","avatar":""},{"name":"June Carryl","avatar":""},{"name":"Werner Herzog","avatar":""},{"name":"Clara Thomas","avatar":""},{"name":"Benjamin Brock","avatar":""},{"name":"Lo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Al di là dei sogni","Amor Além da Vida","美夢成真","رویاها چه می شوند","飛越來仕緣","Hinter dem Horizont - Das Ende ist nur der Anfang","Де живуть мрії","Más allá de los sueños","Mas Alla De Los Sueños","Między Piekłem a Niebem","What Dreams May Come"]', 1784690324536);
