INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('noi-giac-mo-tro-thanh-hien-thuc', 'Nơi Giấc Mơ Trở Thành Hiện Thực', 'What Dreams May Come', 'nơi giấc mơ trở thành hiện thực what dreams may come robin williams cuba gooding jr. annabella sciorra josh paddock jessica brooks grant max von sydow wilma bonet lucinda jenney rosalind chao matt salinger maggie mccarthy carin sprague june carryl werner herzog clara thomas benjamin brock lo al di là dei sogni amor além da vida 美夢成真 رویاها چه می شوند 飛越來仕緣 hinter dem horizont - das ende ist nur der anfang де живуть мрії más allá de los sueños mas alla de los sueños między piekłem a niebem what dreams may come', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-trai-dat-den-mat-trang', 'Từ Trái Đất Đến Mặt Trăng', 'From The Earth To The Moon', 'https://phimimg.com/upload/vod/20260616-1/0c50f35a6f54861ae19313aae95ef2a1.jpg', 'https://phimimg.com/upload/vod/20260616-1/0492356e5095ea6734a10837a6cb4306.jpg', '<p>Bộ phim tái hiện câu chuyện lịch sử về chương trình không gian của Hoa Kỳ, kéo dài từ những ngày đầu khởi sự đầy thách thức vào năm 1961 cho đến sứ mệnh chinh phục Mặt Trăng cuối cùng của con tàu Apollo vào năm 1972.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 18, 1998, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["登月之旅","Dalla Terra alla Luna","From the Earth to the Moon"]', 1784690324536);
