INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-doi-mong', 'Tình Đợi Mong', 'Anna Magdalena', 'https://phimimg.com/upload/vod/20260605-1/3597a51c11a2a7c8704474c0bb9bc2b0.jpg', 'https://phimimg.com/upload/vod/20260605-1/5cb753e6fe3061eedfef6f8396d6ac77.jpg', '<p>Tình Đợi Mong - Anna Magdalena kể về anh thợ sửa đàn piano Trần Gia Phú (Kim Thành Vũ) nhút nhát, vốn quen sống cô đơn, buồn tẻ. Rồi một ngày Dư Vinh Phú (Quách Phú Thành) - Một anh chàng ăn chơi trác táng, lôi thôi nhưng có hấp dẫn không thể cưỡng lại, chuyển đến sống cùng Gia Phú. Cả hai bị quấy rầy, rồi bị ám ảnh bởi tiếng đàn piano nghiệp dư cô gái trên lầu Mạc Mẫn Nhi (Trần Tuệ Lâm). Từ đây một “tam giác tình yêu” dần hình thành!</p>', 'Full', 1, 'single', 'completed', 31, 1998, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Takeshi Kaneshiro","avatar":""},{"name":"Kelly Chen Hui-Lin","avatar":""},{"name":"Aaron Kwok Fu-Shing","avatar":""},{"name":"Anita Yuen Wing-Yee","avatar":""},{"name":"Leslie Cheung","avatar":""},{"name":"Jacky Cheung Hok-Yau","avatar":""},{"name":"Josie Ho","avatar":""},{"name":"Eric Tsang Chi-Wai","avatar":""},{"name":"Leo Ku","avatar":""},{"name":"Wei Wei","avatar":""},{"name":"Yuki Lai Yuen-Tung","avatar":""},{"name":"Jojo Hui Yuet-Chun","avatar":""},{"name":"Jerry Lamb Hiu-Fung","avatar":""},{"name":"Pauline Yeung Yung-Lin","avatar":""},{"name":"Choi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Anna Madelina","Anna Magdalena","친니친니: 안나마덕련나","안나마덕련나","アンナ・マデリーナ：1998","安娜瑪德蓮娜"]', 1784690324536);
