INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thai-quy-quai', 'Bào Thai Quỷ Quái', 'The Demon''s Baby', 'https://phimimg.com/upload/vod/20260505-1/6ce036eaff7d10ab3c2d9d4598f0b48d.jpg', 'https://phimimg.com/upload/vod/20260505-1/6ea64b8874e35175b9db14000b97145e.jpg', '<p>Vào đời cổ Trung Quốc có rất nhiều đạo giáo bí mật, nhất là vào đời Mãn Thanh. …Rất may họ đã bị quan phủ bao vây, mời đại sư Long Thiện bắt 5 con ma nhốt vào 5 cái bình cổvà sau đó dùng tượng Phật vàng trấn áp, đem mẹ con họ hóa thành “Thân ma” để lại nhân gian, hút máu và nước óc. Đồn rằng nếu 5 con ma này ra đời thì pháp luật vô biên, tàn hại nhân gian. Rất may họ đã bị quan phủ bao vây, mời đại sư Long Thiện bắt 5 con ma nhốt vào 5 cái bình cổ và sau đó dùng tượng Phật vàng trấn áp, đem hết tất cả giấu chung và tang vật chông … Nhưng mà nhân gian có đồn rằng 5 con tà linh nếu có cơ hội thì nó sẽ sống lại. Lần này họ không thất bại nữa đâu</p>', 'Full', 1, 'single', 'completed', 31, 1998, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Emotion Cheung Kam-Ching","avatar":""},{"name":"Annie Wu","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Lee Siu-Kay","avatar":""},{"name":"Ronald Wong","avatar":""},{"name":"Lam Yuk-Chi","avatar":""},{"name":"Li Tai-Li","avatar":""},{"name":"Wang Xingzhi","avatar":""},{"name":"Lai Xuan-Ni","avatar":""},{"name":"Chu Ben-Ke","avatar":""},{"name":"Wang Min","avatar":""},{"name":"Wu Hua","avatar":""},{"name":"Shen Ting","avatar":""},{"name":"Wang Yi-Shih","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80ea