INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-dieu-a-kaito', 'Cánh Diều (A kaito)', 'Kite', 'https://phimimg.com/upload/vod/20260207-1/3afe0b3a63ecd3d5199192ea858671a6.jpg', 'https://phimimg.com/upload/vod/20260207-1/db3ada8f890d54090a9d8efd16066947.jpg', '<p>Sawa, cô gái mồ côi từ nhỏ sau khi cha mẹ bị những kẻ sát nhân sát hại, giờ đây trở thành sát thủ chuyên nghiệp cho một tổ chức đánh thuê, nhắm vào những ''tế bào ung thư'' của xã hội. Với vẻ ngoài quyến rũ nhưng lại sở hữu khả năng bạo lực khủng khiếp, cô đã trở thành một vũ khí hoàn hảo. Tuy nhiên, sự hoài nghi bắt đầu nảy sinh trong tâm trí Sawa khi người đồng đội sát thủ của cô, Oburi, quyết định rằng anh muốn rũ bỏ tất cả để thoát khỏi con đường máu này.</p>', 'Full', 1, 'hoathinh', 'completed', 21, 1998, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Konami Yoshida","avatar":""},{"name":"Kousuke Okano","avatar":""},{"name":"Kinryu Arimoto","avatar":""},{"name":"Rokuro Naya","avatar":""},{"name":"Dai Matsumoto","avatar":""},{"name":"Rei Igarashi","avatar":""},{"name":"Naho Hirokawa","avatar":""},{"name":"Itsumi Sawada","avatar":""},{"name":"Hiroshi Aida","avatar":""},{"name":"Nobuyuki Takano","avatar":""},{"name":"Douglas Cartwright","avatar":""},{"name":"William Rain","avatar":""},{"name":"Gary Wynn-Jones","avatar":""},{"name":"Michiko Yamaguchi","avatar":""},{"name":"Jackie Sylvester","avatar":""},{"name":"Richard O''Sa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["A Kite","A Kaito","카이트","Kite","Kite - Ein gefährliches Mädchen","Sexo letal","Domination Nakite","Aitvaras","Кайт 