INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-patch-adams', 'Bác Sĩ Patch Adams', 'Patch Adams', 'https://phimimg.com/upload/vod/20260122-1/05eb1f696d2e2b7d4b1e82d693786f4d.jpg', 'https://phimimg.com/upload/vod/20260122-1/e4c5f38e4283b20f97b43774f450cac7.jpg', '<p>Câu chuyện có thật về Tiến sĩ Hunter &quot;Patch&quot; Adams, người vào những năm 1970 nhận thấy rằng sự hài hước là liều thuốc tốt nhất và sẵn sàng làm bất cứ điều gì để khiến bệnh nhân của mình cười - ngay cả khi điều đó có nghĩa là mạo hiểm sự nghiệp của chính mình.</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Monica Potter","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Daniel London","avatar":""},{"name":"Bob Gunton","avatar":""},{"name":"Harve Presnell","avatar":""},{"name":"Peter Coyote","avatar":""},{"name":"Michael Jeter","avatar":""},{"name":"Josef Sommer","avatar":""},{"name":"Irma P. Hall","avatar":""},{"name":"Barry Shabaka Henley","avatar":""},{"name":"Frances Lee McCain","avatar":""},{"name":"Daniella Kuhn","avatar":""},{"name":"James Greene","avatar":""},{"name":"Harold Gould","avatar":""},{"name":"Bruce Bohne","avatar":""},{"name":"Ha","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Docteur Patch","Patch Adams"]', 1784690324536);
