INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-si-patch-adams', 'Bác Sĩ Patch Adams', 'Patch Adams', 'bác sĩ patch adams patch adams robin williams monica potter philip seymour hoffman daniel london bob gunton harve presnell peter coyote michael jeter josef sommer irma p. hall barry shabaka henley frances lee mccain daniella kuhn james greene harold gould bruce bohne ha docteur patch patch adams', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-tam-anh-hung', 'Chân Tâm Anh Hùng', 'A Hero Never Dies', 'https://phimimg.com/upload/vod/20260109-1/10b57c6f1687f6a663cb6847935cfe1b.jpg', 'https://phimimg.com/upload/vod/20260109-1/592cb558db45f89f43484b3c3dcc1565.jpg', '<p>Nội dung phim xoay quanh 2 anh lớn của 2 bang đối nghịch nhau trong giang hồ là Jack và Martin trong bối cảnh cuộc chiến băng đảng diễn ra rất khốc liệt, người con người rất chung thành, tôn trọng rất nhau và sống cũng rất chung tình. Cả hai nhà lãnh đạo băng đảng của họ đều muốn nhận được lời khuyên từ một thầy bói sống ở Thái Lan. Trong chuyến đi đó, băng đảng của Martin đã phục kích băng của Jack ở một khách sạn tại Thái Lan. Đó là một cuộc tấn công với mục đích thủ tiêu rất rõ ràng, trong đó cả Martin và Jack đều bị thương nặng. &nbsp;Mặc dù những cánh tay đắc lực của mình đang bị thương nhưng đại ca của Jack thì đang ở khách sạn, không giống như đại ca của Martin, người đã đã trốn thoát. Sau đó, cả hai thủ lĩnh của 2 băng đảng, Fong của Martin và Yam của Jack, cùng nhau đi đến diện kiến một vị cao nhân và làm hòa. Trong khi đó, Jack và Martin thì đều nằm viện. Chân của Martin thậm chí còn bị cắt bỏ, và cô bạn gái đang làm nghề gái của anh thì đến để đưa họ trở lại Hong Kong …</p>', 'Full', 1, 'single', 'completed', 22, 1998, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Leon Lai Ming","avatar":""},{"name":"Sean Lau Ching-Wan","avatar":""},{"name":"Fiona Leung Ngai-Ling","avatar":""},{"name":"Yoyo Mung Ka-Wai","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Sato Keiji","avatar":""},{"name":"Yuen Bun","avatar":""},{"name":"Henry Fong Ping","avatar":""},{"name":"Yen Shi-Kwan","avatar":""},{"name":"Michael Lam Wai-Leung","avatar":""},{"name":"Wong Tin-Lam","avatar":""},{"name":"Cheung Chi-Ping","avatar":""},{"name":"Lu Ching-Ting","avatar":""},{"name":"Law Wing-Cheong","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Chiu Chi-","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chan sam ying hung","A Hero never Dies","真心英雄","A Hero Never Dies"]', 1784690324536);
