INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-van-hung-ba-thien-ha', 'Phong Vân: Hùng Bá Thiên Hạ', 'The Storm Riders', 'https://phimimg.com/upload/vod/20251216-1/1bbfd7d0d44a4e69fb13164ba3d95762.jpg', 'https://phimimg.com/upload/vod/20251216-1/b540f7964a7d9f520dafc66ae5319992.jpg', '<p>Hùng Bá tìm khắp bốn bể các nam tử đáp ứng lời tiên tri, sát hại phụ mẫu chúng và nuôi dạy chúng. Giữ kẻ thù bên mình, hắn đào tạo các cô nhi với mưu đồ bá chủ thiên hạ.</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Ekin Cheng","avatar":""},{"name":"Sonny Chiba","avatar":""},{"name":"Kristy Yang Rongru","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Alex Fong Chung-Sun","avatar":""},{"name":"Michael Tse Tin-Wah","avatar":""},{"name":"Lawrence Cheng Tan-Shui","avatar":""},{"name":"Wayne Lai Yiu-Cheung","avatar":""},{"name":"Jason Chu Wing-Tong","avatar":""},{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"Roy Cheung Yiu-Yeung","avatar":""},{"name":"Yu Ronggua","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Feng Yun","Feng Yun Xiong ba bian xia","The Stormriders","Stormriders","Fung wan: Hung ba tin ha","The Storm Riders (1998)","风云","风云之雄霸天下","ฟงอวิ๋น ขี่พายุทะลุฟ้า","Os Cavaleiros da Tempestade","風雲：雄霸天下"]', 1784690324536);
