INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khi-toi-thuong-4', 'Vũ Khí Tối Thượng 4', 'Lethal Weapon 4', 'https://phimimg.com/upload/vod/20251028-1/2e9f261f2a5deae249cc0b07bd555f29.jpg', 'https://phimimg.com/upload/vod/20251028-1/7cf29bdbdd746da8574ce0993ef3574f.jpg', '<p>Trong cuộc phiêu lưu thứ 4 này, 2 viên cảnh sát Riggs và Murtaugh dính vào 1 vụ đưa người vượt biên bất hợp pháp và làm bạc giả. Sát cánh cùng Riggs và Murtaugh còn có anh chàng lính mới Lee Butters và 1 tay đã từng làm nghề rửa tiền Leo Getz. Đối thủ của Riggs và Murtaugh lần này là người đứng đầu Hội Tam Hoàng Wah Sing Ku.</p>', 'Full', 1, 'single', 'completed', 20, 1998, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Joe Pesci","avatar":""},{"name":"Rene Russo","avatar":""},{"name":"Chris Rock","avatar":""},{"name":"Jet Li","avatar":""},{"name":"Darlene Love","avatar":""},{"name":"Traci Wolfe","avatar":""},{"name":"Kim Chan","avatar":""},{"name":"Steve Kahan","avatar":""},{"name":"Damon Hines","avatar":""},{"name":"Ebonie Smith","avatar":""},{"name":"Michael Chow","avatar":""},{"name":"Danny Arroyo","avatar":""},{"name":"Elizabeth Sung","avatar":""},{"name":"Bob Jennings","avatar":""},{"name":"Jeanne Chinn","avatar":""},{"name":"Conan Lee","avatar":""},{"name":"Mary Ellen Trainor","avatar":""},{"name":"Jessic","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["