INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mau-xanh-ao-giac', 'Màu Xanh Ảo Giác', 'Perfect Blue', 'màu xanh ảo giác perfect blue junko iwao rica matsumoto shiho niiyama masaaki okura shinpachi tsuji emiko furukawa yosuke akimoto yoku shioya hideyuki hori emi shinohara masashi ebara kiyoyuki yanada toru furusawa teiya ichiryusai shin-ichiro miki megumi tano emi motoi pāfekuto burū paafekuto buruu pafekuto buru 蓝色恐惧 the perfect blue 未麻之部屋 パーフェクトブルー เพอร์เฟค บลู perfect blue パーフェクト ブルー совершенная грусть идеальная синева perfect blue remastered mükemmel mavi perfect blue perfect blue', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-hoa', 'Ám Hoa', 'The Longest Nite', 'https://phimimg.com/upload/vod/20251008-1/d34bb59026d8433d224b25242f727044.jpg', 'https://phimimg.com/upload/vod/20251008-1/7a8291f5097baed7c3eeed0ba66fac67.jpg', '<p>Phim kể về thế giới ngầm ở Macau với đủ các thứ tệ nạn cướp của, giết người của nhiều bang phái xã hội đen. Hai bang phái mạnh nhất ở Macau do Tá Trị và Cơ Ca cầm đầu đang chuẩn bị cho kế hoạch bắt tay làm ăn để đối phó với Hồng tiên sinh. Tuy nhiên, vào đêm trước vụ đàm phán, Tá Trị nghe tin đồn Cơ Ca thuê sát thủ ám sát mình khiến vụ việc đổ bể. Để làm rõ sự việc, Tá Trị đã thuê một cảnh sát tên A Sâm (Lương Triều Vỹ) đi điều tra sự việc. Dù mang danh là cảnh sát xong A Sâm lại có hành động không khác gì một tên giang hồ đâm thuê chém mướn. Tại đây, A Sâm đối đầu với kỳ phùng địch thủ của mình là Diệu Đông (Lưu Thanh Vân). Diệu Đông có biệt danh anh chàng đầu trọc, là sát thủ nổi tiếng của Cơ Ca. Càng tìm hiểu rõ sự việc, A Sâm càng tiếp tục rơi vào rắc rối khi gặp một cô gái thần bí. Khi biết được sự thật, A Sâm hiểu anh đã không còn đường lùi.</p>', 'Full', 1, 'single', 'completed', 17, 1998, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Sean Lau Ching-Wan","avatar":""},{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Maggie Shiu","avatar":""},{"name":"Sunny Fang Kang","avatar":""},{"name":"Lung Fong","avatar":""},{"name":"Ronny Ching Siu-Lung","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Wong Tin-Lam","avatar":""},{"name":"Lo Hoi-Pang","avatar":""},{"name":"Yuen Bun","avatar":""},{"name":"Lee Sau-Kei","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Wu Kwok-Chiu","avatar":""},{"name":"Jackson Ha Chak-Shun","avatar":""},{"name":"Eric Huen Chi-Kit","avatar":""},{"name":"Chiu Chi-Shing","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["暗花之杀人条件","The Longest Night","暗花","The Longest Nite","Самая долгая ночь","Um fa","Am faa"]', 1784690324536);
