INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sakura-thu-linh-the-bai', 'Sakura Thủ Lĩnh Thẻ Bài', 'Cardcaptor Sakura', 'https://phimimg.com/upload/vod/20250111-1/c014d165688ee9747d7495eab2e2d02b.jpg', 'https://phimimg.com/upload/vod/20250111-1/a0e3af5afa8a701efe06843f41119895.jpg', '<p>Vô tình giải phóng bộ thẻ bài ma thuật được niêm phong nhiều năm trong một quyển sách, cô bé Sakura phát hiện ra mình đang nắm giữ một sức mạnh kì diệu. Sau đó cô bé được giao nhiệm vụ thu phục lại tất cả các thẻ bài đã chạy thoát, nhằm ngăn chặn chúng phá huỷ thế giới.</p>', 'Hoàn Tất (70/70)', 70, 'hoathinh', 'completed', 28, 1998, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Sakura Tange","avatar":""},{"name":"Junko Iwao","avatar":""},{"name":"Motoko Kumai","avatar":""},{"name":"Aya Hisakawa","avatar":""},{"name":"Emi Shinohara","avatar":""},{"name":"Hideyuki Tanaka","avatar":""},{"name":"Masaya Onosaka","avatar":""},{"name":"Megumi Ogata","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Yukana","avatar":""},{"name":"Tomoko Kawakami","avatar":""},{"name":"Nozomu Sasaki","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Ловецът на карти - Сакура","Кардкептър Сакура","Ловката на картa - Сакура","Кардкаптър Сакура","Sakura Card Captors","百变小樱","魔卡少女樱","百变小樱魔术卡","Sakura, chasseuse de cartes","Pesca la tua carta Sakura","Sakura, la partita non è finita","カードキャプターさくら クリアカード編","カードキャプターさくら さくらカード編","カードキャプターさくら クロウカード編","Cardcaptor Sakura","Cardcaptor Sakura: Clear