INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-da-do-2-hanh-trinh-den-the-gioi-moi', 'Công Chúa Da Đỏ 2: Hành Trình Đến Thế Giới Mới', 'Pocahontas II: Journey to a New World', 'https://phimimg.com/upload/vod/20250920-1/8bfbff684a855384e8c8fcbd9a2aa06f.jpg', 'https://phimimg.com/upload/vod/20250920-1/30808fc6b607f1ba9863759a2c2dc416.jpg', '<p>Tiếp theo nội dung của phần 1, thuyền trưởng John Smith trở về nước Anh và gặp nạn. Trong lúc đó, ở Miền Đất Mới, Pocahontas gặp một chàng trai khác là John Rolfe. Khi tin tức về cái chết của John Smith đến được nước Mĩ, Pocahontas đã rất đau buồn, và quyết định lên đường tới Anh trong một sứ mệnh ngoại giao: đặt nền tảng cho hoà bình và hữu nghị giữa hai miền đất. Tuy thế, Ratcliffe vẫn còn muốn chiếm lại Jamestown bằng bất cứ giá nào, và hắn không từ thủ đoạn nào để ngăn cản nàng công chúa trẻ...</p>', 'Full', 1, 'hoathinh', 'completed', 17, 1998, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Billy Zane","avatar":""},{"name":"Irene Bedard","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"David Ogden Stiers","avatar":""},{"name":"Linda Hunt","avatar":""},{"name":"Judy Kuhn","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Jean Stapleton","avatar":""},{"name":"Donal Gibson","avatar":""},{"name":"Finola Hughes","avatar":""},{"name":"Russell Means","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Gregg Rainwater","avatar":""},{"name":"William Morgan Sheppard","avatar":""},{"name":"Kath Soucie","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Ap","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Pocahontas 2: Uma Jornada para o Novo Mundo","Pocahontas 2 - Un Monde Nouveau","Pocahontas 2: Journey to a New World","Pocahontas 2","Pocahontas 2 - Uma Jornada para o Novo Mundo","포카혼타스 2","Pocahontas II","Pocahontas II - Un Monde Nouveau","Pocahontas 2 - Viaggio Nel Nuovo Mondo","Pocahontas II: Cesta do Nového světa","Pocahontas II Journey to a New World (1998)","Pocahontas 2 Journey To the New World","Pocahontas 2. Vár egy új világ","Ποκαχόντας ΙΙ: Ταξίδι σ’ ενα Νέο Κόσμο","Pocahontas II: Journey to a New World"]', 1784690324536);
