INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-chua-da-do-2-hanh-trinh-den-the-gioi-moi', 'Công Chúa Da Đỏ 2: Hành Trình Đến Thế Giới Mới', 'Pocahontas II: Journey to a New World', 'công chúa da đỏ 2: hành trình đến thế giới mới pocahontas ii: journey to a new world billy zane irene bedard jim cummings david ogden stiers linda hunt judy kuhn jeff bennett jean stapleton donal gibson finola hughes russell means brad garrett gregg rainwater william morgan sheppard kath soucie rob paulsen frank welker ap pocahontas 2: uma jornada para o novo mundo pocahontas 2 - un monde nouveau pocahontas 2: journey to a new world pocahontas 2 pocahontas 2 - uma jornada para o novo mundo 포카혼타스 2 pocahontas ii pocahontas ii - un monde nouveau pocahontas 2 - viaggio nel nuovo mondo pocahontas ii: cesta do nového světa pocahontas ii journey to a new world (1998) pocahontas 2 journey to the new world pocahontas 2. vár egy új világ ποκαχόντας ιι: ταξίδι σ’ ενα νέο κόσμο pocahontas ii: journey to a new world', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-thuat-phan-1', 'Phép Thuật (Phần 1)', 'Charmed (Season 1)', 'https://phimimg.com/upload/vod/20250915-1/a362cfca096c23f6169098adabfd0a5b.jpg', 'https://phimimg.com/upload/vod/20250915-1/a33a5f275eb49c74e99b589e387a947f.jpg', '<p>Charmed (Phép Thuật) là bộ phim dài tập của Mỹ gồm 8 phần kể về những chị em gái nhà Halliwell. Họ là những phù thuỷ tốt có phép thuật. Mỗi chị em gái sở hũu một phép thuật khác nhau với những quyền năng và sức mạnh khác nhau. Và phép thuật của họ mạnh mẽ hơn cả khi họ kết hợp với nhau, tạo thành “Bộ ba phép thuật” quyền năng và mạnh mẽ. Họ với phép thuật của mình chống lại những thế lực hắc ám, chiến đấu, chống lại lũ quỷ và bè lũ thợ săn phù thủy. Với “Cuốn sách của bóng tối” làm bạn, làm “người dẫn đường”, họ đã từng bước trưởng thành trong cuộc sống. Sức mạnh của họ ngày càng phát triển, và chính vì thế, những mối nguy hiểm đối với họ ngày càng gia tăng. Họ - những chị em gái nhà Halliwell – luôn kiên cường, mạnh mẽ chống lại cái ác, bảo vệ người vô tội. Mỗi tập phim kể về một câu chuyện nhỏ trong cuộc sống của ba chị em, xen vào đó là những yếu tố hài hước và chân thực trong cuộc sống thường ngày.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 23, 1998, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Holly Marie Combs","avatar":""},{"name":"Alyssa Milano","avatar":""},{"name":"Rose McGowan","avatar":""},{"name":"Brian Krause","avatar":""},{"name":"Kaley Cuoco","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Charmed: Jovens Bruxas","Oi magisses","Η Μαγευτικές","チャームド 魔女3姉妹","チャームド〜魔女3姉妹〜","Hechiceras","Чародійки","Зачаровані","Всі жінки відьми","Усі жінки відьми","Charmed"]', 1784690324536);
