INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-su', 'Tình Sử', 'An Affair', 'https://phimimg.com/upload/vod/20250610-1/0d066bb1ca29f7aca132c5a25803b3af.jpg', 'https://phimimg.com/upload/vod/20250610-1/ab3346439792ef8b4442c9ba06b1eb17.jpg', '<p>Seo-hyun là một bà nội trợ bình thường ở độ tuổi ngoài ba mươi, có một cậu con trai mười tuổi và một người chồng là kiến trúc sư thành đạt. Đối với cô, cuộc sống chỉ là những chuỗi ngày lặp đi lặp lại đầy nhàm chán. Thế nhưng, cuộc sống yên ổn ấy bất ngờ bị đe dọa khi Woo-in – vị hôn phu trẻ trung và quyến rũ của em gái cô – xuất hiện.</p>', 'Full', 1, 'single', 'completed', 16, 1998, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Mi-sook","avatar":""},{"name":"Lee Jung-jae","avatar":""},{"name":"Song Young-chang","avatar":""},{"name":"Jung Kyung-soon","avatar":""},{"name":"Min Kim","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["An Affair","정사","情逝","汉城娩娘","婚外初夜","情事","Jung sa","Jeongsa"]', 1784690324536);
