INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khu-ta-diet-ma-phan-1', 'Khử Tà Diệt Ma (Phần 1)', 'My Date with a Vampire (Season 1)', 'khử tà diệt ma (phần 1) my date with a vampire (season 1) joey man yee-man eric wan tin-chiu kenneth chan alice chan wai pinky cheung man-chi wong shu-tong daniel cheung thomas sin ho-ying asuka higuchi ricky chan po-yuen ruco chan andrew yuen qin lan norman tsui remus kam tats lau yee-tat jason 我和僵尸有个约会 我和殭屍有個約會 나랑 좀비 약속이 있어서', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-du-hanh-bien-phuong-nam', 'Doraemon: Nobita Du Hành Biển Phương Nam', 'Doraemon: Nobita''s Great Adventure in the South Seas', 'https://phimimg.com/upload/vod/20250524-1/77fb8fd525c8f20616c97e2998f80eb7.jpg', 'https://phimimg.com/upload/vod/20250524-1/56a3660058e918732bc4ad335d02667f.jpg', '<p>Việc tìm kiếm tài liệu về biển để phục vụ cho công việc học tập sẽ khiến cánh cửa thần kỳ của Doraemon mở ra và đưa Nobita đến với Shizuka, Gian và Sueno dưới lòng đại dương sâu thẳm. Lần này những người bạn của chúng ta lên một con thuyền khổng lồ và độc đáo để tìm hiểu về những bí ẩn của biển và tìm kiếm kho báu. Điều mà không ai có thể tưởng tượng được là sự biến dạng của dòng không-thời gian sẽ dẫn họ đến thế kỷ XVII giữa một cơn bão lớn sẽ khiến họ bị đắm và nơi Doraemon đánh mất chiếc túi thần kỳ. Không còn thời gian để mất, những người bạn của chúng ta phải tìm ra một lối thoát. Liệu họ có thành công?</p>', 'Full', 1, 'hoathinh', 'completed', 15, 1998, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Tohru Emori","avatar":""},{"name":"Paul Lucas","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Doraemon y los piratas de los mares del sur","Doraemon Nobita no Nankai Dai Boken","Doraemon: Nobita''s South Sea Adventure","Nobita''s Great Adventure in the South Seas","도라에몽: 노비타의 남해대모험","도라에몽: 진구의 바다대모험","극장판 도라에몽: 진구의 바다 대모험","도라에몽 극장판: 진구의 바다 대모험",