INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hercules-vi-than-suc-manh-phan-5', 'Hercules: Vị Thần Sức Mạnh (Phần 5)', 'Hercules: The Legendary Journeys (Season 5)', 'https://phimimg.com/upload/vod/20250424-1/fbd2ee0401e53c9929309a8993195e60.jpg', 'https://phimimg.com/upload/vod/20250424-1/90c7dcb699683841b68a6e1ee8a32b79.jpg', '<p>Một câu chuyện về thời xa xưa - những huyền thoại và sự bí hiểm, khi trái đất còn rất hoang sơ. Những vị thần còn rất nhỏ mọn và tàn bạo, họ gieo rắc cho loài người đau đớn và sự sợ hãi. Nhưng rồi anh ấy xuất hiện. Anh ấy không như những người khác. Mẹ là một phụ nữ xinh đẹp, cha là Vị thần tối cao Zeus, vua của các vị thần. Hercules thừa hưởng sức mạnh mà không ai có, và cả sức mạnh ý chí trong trái tim. Cho dù có trở ngại, nơi đâu cần sự giúp đỡ, nơi đó có một người không bao giờ nghỉ ngơi... Hercules.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 16, 1998, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Sorbo","avatar":""},{"name":"Michael Hurst","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["武神传说","Herkül","Геркулес: Легендарні Подорожі","Геркулес: Героїчні Пригоди","Hercules: The Legendary Journeys"]', 1784690324537);
