INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-nguyet', 'Hải Nguyệt', 'Hai Nguyet', 'https://phimimg.com/upload/vod/20250406-1/d7398ce7e038d3df4dab92a45a4dc20c.jpg', 'https://phimimg.com/upload/vod/20250406-1/05a676a6da1fab63627ea8eaf20979bc.jpg', '<p>Hải Nguyệt là tiểu thư gia đình Hải Hương nổi tiếng với nghề làm nước mắm truyền thống. Trước biến cố thời cuộc, ông Hải Hương đưa gia đình vượt biên qua Pháp. Hải Nguyệt chọn ở lại chịu tang bà cố với quyết tâm gầy dựng nước mắm Hải Hương và vấp phải sự cản trở và ghen tuông của Nục (con riêng ông Hải Hương) cùng mối tình cay đắng với Phi.</p>', 'Full', 1, 'single', 'completed', 12, 1998, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hồng Ánh","avatar":""},{"name":"Quang Hải","avatar":""},{"name":"Hoài An","avatar":""},{"name":"Cô Ba Trà Vinh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324537);
