INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loc-dinh-ky-1998', 'Lộc Đỉnh Ký', 'The Duke Of Mount Deer', 'https://phimimg.com/upload/vod/20250303-1/cf45da6077b41ec232380e107d58fc72.jpg', 'https://phimimg.com/upload/vod/20250303-1/c40b8085ed2236458b98ca8ed94a24e2.jpg', '<p>Vi Tiểu Bảo từ nhỏ theo mẹ sống trong kỷ viện ở Dương Châu; bởi tình cờ biết được bí mật trong cung, nên anh ta bị ép ở lại làm thái giám giả. Sau đó Tiểu Bảo giúp sức tiểu hoàng đế Khang Hy tiêu diệt gian thần, rồi hai người trở thành bạn thân. Hơn nữa, Tiểu Bảo còn được tổng đà chủ của Thiên Địa Hội nhận làm đệ tử, bắt anh ta chờ thời cơ hành thích Khang Hy, làm cho Tiểu Bảo rất khó xử. Tiểu Bảo biết được Thần Long Giáo đã phái người đóng thái hậu giả để nằm vùng tại nội cung hơn mười năm nay, nhằm lấy cắp bản đồ cất giữ báu vật về mạch sống của đại Thanh. Còn thái hậu thật thì bị giam giữ. Khang Hy bắt tay cùng với Tiểu Bảo, cuối cùng cứu thoát được thái hậu. Mặt khác, Tiểu Bảo còn biết được hoàng đế Thuận Trị vẫn còn sống. Tiểu Bảo dùng diệu kế xách động Thần Long Giáo chém giết lẫn nhau, lập công thêm một lần nữa. Tiểu Bảo hưởng tận diễm phúc trần gian. Không lâu sau, Khang Hy hạ lệnh Tiểu Bảo tiêu diệt Thiên Địa Hội, lúc đó anh ta mới hiểu Khang Hy đã biết bí mật của mình từ lâu.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 15, 1998, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Tiểu Xuân","avatar":""},{"name":"Lương Tiểu Băng","avatar":""},{"name":"La Quán Lan","avatar":""},{"name":"Mã Tuấn Vỹ","avatar":""},{"name":"Lưu Ngọc Thúy","avatar":""},{"name":"Trần Thiếu Hà","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Luk ding gei","鹿鼎记","鹿鼎记（ 1998）","鹿鼎记陈小春版","鹿鼎记 1998","鹿鼎記","The Duke of Mount Deer 1998","The Duke of Mount Deer"]', 1784690324537);
