INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dac-nhiem-cid-phan-1', 'Đội Đặc Nhiệm CID (Phần 1)', 'CID (Season 1)', 'https://phimimg.com/upload/vod/20250224-1/964dbe0c2a388e6db82ba3cfa5e81e56.jpg', 'https://phimimg.com/upload/vod/20250224-1/b0fbe7438249971ad91919273bf59132.jpg', '<p>Tính đến thời điểm hiện tại, &quot;Đội đặc nhiệm CID&quot; là bộ phim hình sự - trinh thám duy nhất của Bollywood vẫn được khán giả xem truyền hình Ấn Độ yêu mến, rating cao dù đã phát sóng 18 năm và vẫn đang tiếp tục. Ngày 21/01/1998, tập phim CID đầu tiên lên sóng truyền hình. Ngay lập tức tạo nên cơn sốt, thu hút khán giả xem ti vi. Với khung giờ phát sóng vào tối thứ 7, chủ nhật hàng tuần, CID trở thành bộ phim giải trí cuối tuần cho mọi người, mọi nhà. Những màn rượt đuổi, khai quật tử thi, khám nghiệm pháp ý, lập luận phá án, đấu trí gay cấn với hung thủ... khiến khán giả hồi hộp.</p>', 'Hoàn Tất (1080/1080)', 1080, 'series', 'completed', 14, 1998, 'Lồng Tiếng', 'FHD', 'Ấn Độ', 0, '[{"name":"Shivaji Satham","avatar":""},{"name":"Aditya Srivastava","avatar":""},{"name":"Dayanand Shetty","avatar":""},{"name":"Shraddha Musale","avatar":""},{"name":"Manav Gohil","avatar":""},{"name":"Smita Bansal","avatar":""},{"name":"Amit Misra","avatar":""},{"name":"Kunal Madhiwala","avatar":""},{"name":"Dhananjay Mandrekar","avatar":""},{"name":"Ansha Sayed","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["सीआई डी","CID","சிஐடி","సిఐడి","सीआय डी","সিআইডি","सीआईडी"]', 1784690324537);
