INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-tan-the-1998', 'Ngày Tận Thế', 'Armageddon', 'https://phimimg.com/upload/vod/20250219-1/f6e4b37b56723c101f8b0da8f39b2e68.jpg', 'https://phimimg.com/upload/vod/20250219-1/91945929ad3bf03d50de16e4954e3fe7.jpg', '<p>Sau khi phát hiện ra một tiểu hành tinh kích thước có kích thước bằng bang Texas sẽ đâm vào trái đất trong chưa đầy 1 tháng với vận tốc hơn 1000 dặm/giờ, NASA tuyển một đội ngũ thợ khoan chuyên nghiệp đã có 30 năm kinh nghiệm khoan trên rất nhiều bề mặt khác nhau để lên tiểu hành tinh đó khoan 2 lỗ sâu 300m để nhét 2 quả bom nguyên tử lên đó nhằm tách tiểu hành tinh này thành 2 phần bay lệch theo 2 hướng khác nhau...</p>', 'Full', 1, 'single', 'completed', 12, 1998, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Billy Bob Thornton","avatar":""},{"name":"Ben Affleck","avatar":""},{"name":"Liv Tyler","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Owen Wilson","avatar":""},{"name":"Michael Clarke Duncan","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Ken Hudson Campbell","avatar":""},{"name":"Jessica Steen","avatar":""},{"name":"Keith David","avatar":""},{"name":"Chris Ellis","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Grayson McCouch","avatar":""},{"name":"Clark","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d8