INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-ban-phan-5', 'Những Người Bạn (Phần 5)', 'Friends (Season 5)', 'https://phimimg.com/upload/vod/20240910-1/724d493e7dd904ea91749e83214f7077.jpg', 'https://phimimg.com/upload/vod/20240910-1/df54f4bb8b0c00388d7f25075ab300f7.jpg', '<p>Loạt phim dõi theo những sự cố vui nhộn của 6 người bạn tuổi đôi mươi đang vật lộn với những thử thách trong công việc, cuộc sống, tình yêu tại Manhattan những năm 1990.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 13, 1998, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jennifer Aniston","avatar":""},{"name":"Courteney Cox","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Matt LeBlanc","avatar":""},{"name":"Matthew Perry","avatar":""},{"name":"David Schwimmer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
