INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-2-muc-tieu-thu-14', 'Thám Tử Lừng Danh Conan 2: Mục Tiêu Thứ 14', 'Detective Conan: The Fourteenth Target', 'https://phimimg.com/upload/vod/20231019-1/c6c174d97ceb703f2ac4cb9106ab2bc4.jpg', 'https://phimimg.com/upload/vod/20231019-1/137937bbae1d27ab2f4f593d7e6d89de.jpg', '<p>Conan bị vướng vào rắc rối của gia đình Mori. Murakami, kẻ tội phạm đã bị Mori tống giam nhiều năm trước nay được ra tù. Vì hận thù Mori mà dường như Murakami đang lần lượt gây ra các vụ thương tích và án mạng đối với những người thân thích của ông Mori. Bi kịch thảm sát liên tiếp xảy ra, liệu phán đoán của cảnh sát về hung thủ có đang đi đúng hướng? Conan sẽ làm thế nào để ngăn chặn cuộc đua giết người và tìm ra hung thủ thực sự?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 1998, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Gara Takashima","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Kaneto Shiozawa","avatar":""},{"name":"Ryusei Nakao","avatar":""},{"name":"Asako Dodo","avatar":""},{"name":"Eiichiro Suzuki","avatar":""},{"name":"Hirotaka Suzuoki","avatar":""},{"name":"Miyuki Ichijou","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324537);
