INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-lung-danh-conan-2-muc-tieu-thu-14', 'Thám Tử Lừng Danh Conan 2: Mục Tiêu Thứ 14', 'Detective Conan: The Fourteenth Target', 'thám tử lừng danh conan 2: mục tiêu thứ 14 detective conan: the fourteenth target minami takayama kappei yamaguchi akira kamiya wakana yamazaki chafurin naoko matsui gara takashima kenichi ogata wataru takagi ikue otani yukiko iwai kaneto shiozawa ryusei nakao asako dodo eiichiro suzuki hirotaka suzuoki miyuki ichijou ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-dien-cua-truman', 'Buổi Diễn Của Truman', 'The Truman Show', 'https://phimimg.com/upload/vod/20231015-1/117bc8cfd27c89e90d41388db26280d2.jpg', 'https://phimimg.com/upload/vod/20231015-1/f3119d2b9f207c907073565f4e53323b.jpg', '<p>Chương trình Truman (The Truman Show) là một bộ phim khoa học viễn tưởng hài kịch Mỹ năm 1998 của đạo diễn Peter Weir và biên kịch Andrew Nicol... Bộ phim kể về Truman Burbank là một người đặc biệt, ngôi sao trong show truyền hình thực tế nổi tiếng: The Truman Show nhưng Truman thực sự lại không biết điều đó. Tất cả những hành động nhỏ nhặt nhất của anh trong cuộc sống hàng ngày đều được một đạo diễn kiêm nhà sản xuất ghi lại. Thành phố nơi anh sống trở thành một studio lớn, những người hàng xóm, đồng nghiệp, bạn bè và cả vợ anh đều là những diễn viên chuyên nghiệp của Hollywood. Rồi một ngày, Truman tỏ ra nghi ngờ một điều gì đó...</p>', 'Full', 1, 'single', 'completed', 12, 1998, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Laura Linney","avatar":""},{"name":"Noah Emmerich","avatar":""},{"name":"Natascha McElhone","avatar":""},{"name":"Holland Taylor","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Brian Delate","avatar":""},{"name":"Peter Krause","avatar":""},{"name":"Blair Slater","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
