INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-thanh-thap-dai-khoc-hinh-2', 'Mãn Thanh Thập Đại Khốc Hình 2', 'A Chinese Torture Chamber Story II', 'https://phimimg.com/upload/vod/20240814-1/0f0dcc6952e1cad4b03204685bab79fd.jpg', 'https://phimimg.com/upload/vod/20240814-1/ed96ce6b5e7b5911dda9dd3b3c7a7d91.jpg', '<p>Một tên trộm kết bạn với một vị tướng đang nổi lên trong quân đội. Sau khi vị tướng nhận ra mình phải lòng cô em gái xinh đẹp của một trong những tên trộm (là hôn thê của tên kia), anh ta quyết định làm bất cứ điều gì cần thiết để thoát khỏi sự cạnh tranh và có được cô ấy cho riêng mình.</p>', 'Full', 1, 'single', 'completed', 10, 1998, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"甄楚倩","avatar":""},{"name":"Oscar Lam Wai-Kin","avatar":""},{"name":"Yeung Fan","avatar":""},{"name":"Yang Hsiung","avatar":""},{"name":"初本科","avatar":""},{"name":"Lam Ting-Sang","avatar":""},{"name":"鄭保瑞","avatar":""},{"name":"梁琛榮","avatar":""},{"name":"Ma Chun","avatar":""},{"name":"艾莉","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
