INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-den-nhi-do-5-song-thien-tranh-bip', 'Nhất Đen Nhì Đỏ 5 - Song Thiên Tranh Bịp', 'Who''s The Winner 5', 'https://phimimg.com/upload/vod/20240609-1/3bf0fd6f05968577fbc1f8c806d15aa8.jpg', 'https://phimimg.com/upload/vod/20240609-1/41d77e7066ca0461d80ca30de86601e8.jpg', '<p><em>Phần 5 xoay quanh mối thâm thù giữa hai nhà họ Ngôn Khôn và Long Đình Quang, khi mà họ cùng nhau đấu một ván sinh tử để giành lấy đảo San Hô, kết quả là nhà họ Long đã thắng trong ván bài này trong khi nhà họ Ngôn phải trốn đi để bảo toàn mạng sống. Rồi quá khứ tưởng đã đi vào quên lãng. Tuy nhiên, thật trớ trêu khi con trai nhà họ Ngôn là Ngôn Phi và con gái nhà họ Long là Kỳ Phương đã gặp gỡ và yêu nhau.</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 15, 1998, 'Lồng Tiếng', 'HD', 'Singapore', 0, '[{"name":"Lý Nam Tinh","avatar":""},{"name":"Trịnh Huệ Ngọc","avatar":""},{"name":"Huỳnh Lỗi","avatar":""},{"name":"Giả Tịnh Văn","avatar":""},{"name":"Thẩm Hiểu Hải","avatar":""},{"name":"Phan Hồng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324537);
