INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nick-fury-agent-of-shield', 'Nick Fury: Agent of S.H.I.E.L.D.', 'Nick Fury: Agent of S.H.I.E.L.D.', 'https://phimimg.com/upload/vod/20231016-1/d986705c0eb14924ef6f2a3e8c1e4cb5.jpg', 'https://phimimg.com/upload/vod/20231016-1/db58a9c32b3bdd7ea9b7aa3ebe7c66db.jpg', '<p>Người hùng cứng rắn của Marvel được đưa trở lại để chiến đấu với mối đe dọa của Hydra sau khi bị đày ải ở Yukon kể từ khi Chiến tranh Lạnh kết thúc. Những đứa con của cựu thủ lĩnh Hydra, Nam tước Von Stucker, đã nắm quyền điều hành tổ chức khủng bố. Dưới sự dẫn dắt của cô con gái độc ác Viper, Hydra đã thu giữ một loại virus chết người và đe dọa sự hủy diệt của nước Mỹ.</p>', 'Full', 1, 'single', 'completed', 12, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"David Hasselhoff","avatar":""},{"name":"Lisa Rinna","avatar":""},{"name":"Sandra Hess","avatar":""},{"name":"Neil Roberts","avatar":""},{"name":"Garry Chalk","avatar":""},{"name":"Tracy Waterhouse","avatar":""},{"name":"Tom McBeath","avatar":""},{"name":"Ron Canada","avatar":""},{"name":"Bill Croft","avatar":""},{"name":"Roger Cross","avatar":""},{"name":"Peter Haworth","avatar":""},{"name":"Scott Heindl","avatar":""},{"name":"Adrian G. Griffiths","avatar":""},{"name":"Campbell Lane","avatar":""},{"name":"Mina E. Mina","avatar":""},{"name":"Terry David Mulligan","avatar":""},{"name":"Rick Ravanello","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324537);
