INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loai-ac-doc-2', 'Loài Ác Độc 2', 'Species II', 'https://phimimg.com/upload/vod/20240616-1/5a7c93ae46dae29bb510b01323facd3e.jpg', 'https://phimimg.com/upload/vod/20240616-1/e7beef9e9369508fc81f5a48b215e253.jpg', '<p>Thêm một loài ký sinh đặt chân tới Trái đất. Lần này, vật chủ là Ross, phi hành gia vừa trở về từ sao Hỏa. Trong khi đó, loài ký sinh Sil trong người nữ khoa học gia Eve cũng ngửi ra mùi của &quot;con đực&quot;... &nbsp;Các đặc vụ của chính phủ cần ngăn chặn cuộc phối ngẫu của hai sinh vật lai chết người này.</p>', 'Full', 1, 'single', 'completed', 10, 1998, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Madsen","avatar":""},{"name":"Natasha Henstridge","avatar":""},{"name":"Marg Helgenberger","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"George Dzundza","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Sarah Wynter","avatar":""},{"name":"Justin Lazard","avatar":""},{"name":"Myriam Cyr","avatar":""},{"name":"Baxter Harris","avatar":""},{"name":"Scott Morgan","avatar":""},{"name":"Nancy La Scala","avatar":""},{"name":"Raquel Gardner","avatar":""},{"name":"Henderson Forsythe","avatar":""},{"name":"Robert Hogan","avatar":""},{"name":"Ted Sutton","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324537);
