INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-lang-thi-tham', 'Hành Lang Thì Thầm', 'Whispering Corridors', 'https://phimimg.com/upload/vod/20240425-1/fb557978c42c0377d85a668a9bd95d21.jpg', 'https://phimimg.com/upload/vod/20240425-1/cdfe03be340db70570ad707baa62a8a6.jpg', '<p>Nội dung phim xoay quanh trường trung học nữ sinh Jookran. Ở đây có một giáo viên chủ nhiệm là bà Park, người có biệt danh là “cáo già” do phương pháp giảng dạy tàn bạo. Chuyện phim bắt đầu khi bà Park phát hiện ra sự bất thường từ một học sinh mới chuyển đến. Bà truy xét hồ sơ và thấy học sinh này đã chết từ nhiều năm về trước.</p><p>Quá sợ hãi, bà Park đã nói chuyện này với cô giáo trẻ và cũng từng là học sinh của mình, Hur Eun Young. Sau đó, bà Park bị một kẻ lạ mặt tấn công và xác của bà được các học sinh trong trường phát hiện. Từ đây, ác mộng của ngôi trường thực sự bắt đầu.</p>', 'Full', 1, 'single', 'completed', 10, 1998, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Mi-yeon","avatar":""},{"name":"Kim Gyu-ri","avatar":""},{"name":"Choi Kang-hee","avatar":""},{"name":"Park Jin-hee","avatar":""},{"name":"Yoon Ji-hye","avatar":""},{"name":"Kim Min-jung","avatar":""},{"name":"Lee Yong-nyeo","avatar":""},{"name":"Kim Yu-seok","avatar":""},{"name":"Yoo Yeon-soo","avatar":""},{"name":"Kim Roi-ha","avatar":""},{"name":"Shin Yi","avatar":""},{"name":"Kim Yoon-Jung","avatar":""},{"name":"Choi Seon-mi","avatar":""},{"name":"Park Yong-su","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324537);
