INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-elizabeth-de-nhat', 'Nữ Hoàng Elizabeth Đệ Nhất', 'Elizabeth', 'https://phimimg.com/upload/vod/20240228-1/2fa6ae8e1c0e6743f2453d17c2456f2e.jpg', 'https://phimimg.com/upload/vod/20240228-1/39866ff2ddc62cc99c871abb764416a3.jpg', '<p>Bộ phim này kể chi tiết về sự lên ngôi và triều đại đầu tiên của Nữ hoàng Elizabeth đệ nhất, do Cate Blanchett thủ vai. Trọng tâm chính là những nỗ lực bất tận của hội đồng của cô để kết hôn với cô, sự căm ghét Công giáo đối với cô và mối tình lãng mạn của cô với Lord Robert Dudley.</p>', 'Full', 1, 'single', 'completed', 10, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cate Blanchett","avatar":""},{"name":"Joseph Fiennes","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Christopher Eccleston","avatar":""},{"name":"John Gielgud","avatar":""},{"name":"Richard Attenborough","avatar":""},{"name":"Fanny Ardant","avatar":""},{"name":"Éric Cantona","avatar":""},{"name":"Vincent Cassel","avatar":""},{"name":"Kathy Burke","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
