INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-linh', 'Người Lính', 'Soldier', 'https://phimimg.com/upload/vod/20240228-1/3f2045bf543383aad59462a0c605fbee.jpg', 'https://phimimg.com/upload/vod/20240228-1/2ca519bc6af8321306a5e9d3f932f5ec.jpg', '<p>Trung sĩ Todd là một người lính kỳ cựu của một nhóm tinh nhuệ của lực lượng vũ trang. Sau khi bị đánh bại bởi một giống lính biến đổi gen mới, anh ta bị vứt xuống một hành tinh hoang phế và bỏ mặc cho đến chết. Anh sớm tương tác với một nhóm những người sống sót sau vụ tai nạn, những người dẫn đến một cuộc sống yên bình. Hòa bình bị phá vỡ khi những người lính mới đổ bộ lên hành tinh để tiêu diệt thuộc địa mà Trung sĩ Todd phải bảo vệ.</p>', 'Full', 1, 'single', 'completed', 12, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kurt Russell","avatar":""},{"name":"Jason Scott Lee","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Connie Nielsen","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Gary Busey","avatar":""},{"name":"Michael Chiklis","avatar":""},{"name":"Sara Paxton","avatar":""},{"name":"K.K. Dodds","avatar":""},{"name":"James Black","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324537);
