INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('when-trumpets-fade', 'When Trumpets Fade', 'When Trumpets Fade', 'https://phimimg.com/upload/vod/20231231-1/f1a4d5b64312449ecc25b194bb74eadd.jpg', 'https://phimimg.com/upload/vod/20231231-1/73c57584b039753af81a04a02a7943fb.jpg', '<p>Ở Tây Đức trong Thế chiến thứ hai, Binh nhì David Manning miễn cưỡng bỏ lại một đồng đội bị trọng thương và tìm kiếm những người sống sót trong trung đội của anh ta, chỉ để biết được từ sĩ quan chỉ huy Đại úy Pritchett rằng tất cả họ đều đã thiệt mạng trong chiến đấu. Mặc dù yêu cầu giải ngũ với lý do thiểu năng trí tuệ, Manning được thăng cấp trung sĩ và được giao nhiệm vụ lãnh đạo một trung đội mới gồm những người trẻ tuổi được tuyển chọn.</p>', 'Full', 1, 'single', 'completed', 13, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ron Eldard","avatar":""},{"name":"Zak Orth","avatar":""},{"name":"Frank Whaley","avatar":""},{"name":"Dylan Bruno","avatar":""},{"name":"Devon Gummersall","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
