INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-ngoai-khong-gian-1998', 'Lạc Ngoài Không Gian', 'Lost In Space', 'https://phimimg.com/upload/vod/20240102-1/1fd16696f423db87f4ae2fa79f735cc2.jpg', 'https://phimimg.com/upload/vod/20240102-1/ab375223f5108676db9e523242626251.jpg', '<p>Vào năm 2058, giữa lúc Trái Đất trở nên quá chật chội, một gia đình nọ được phóng vào không gian trong cuộc thám hiểm để tìm lối vào một hành tinh nào đó có môi trường sống như Trái Đất. Nhưng chuyến đi đầy trắc trở vì một viên bác sĩ đi theo đoàn trên phi thuyền tìm cách phá hoại khiến họ bị lạc trong vũ trụ mênh mông không lối về.</p>', 'Full', 1, 'single', 'completed', 13, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gary Oldman","avatar":""},{"name":"William Hurt","avatar":""},{"name":"Matt LeBlanc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324537);
