INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-trom-khet-tieng', 'Siêu Trộm Khét Tiếng', 'Out Of Sight', 'https://phimimg.com/upload/vod/20240102-1/f626ddb35412377abf5ab636c7565b7a.jpg', 'https://phimimg.com/upload/vod/20240102-1/2187909a225a9efb0619fda0818999d4.jpg', '<p>Jack Foley là một trong những tên cướp ngân hàng khét tiếng. Chỉ bằng cái nheo mắt, nụ cười đầy ẩn ý và bộ óc láu lỉnh mà Jack đã qua mặt được nhân viên ngân hàng cả trăm lần trước khi bị FBI tống vào ngục. Giờ đây, với sự trợ giúp của gã bạn nối khố Buddy, hắn một lần nữa chơi khăm các nhà chức trách: thoát khỏi song sắt nhà tù ở Florida và phi thẳng đến Detroit tính sổ một phi vụ làm ăn mới. Hắn hí hửng chờ đợi kiếm được 5 triệu USD từ viên kim cương do Richard Ripley cất giữ. Ripley vốn là đồng đảng với gã nhưng vẫn ung dung sống trong giàu sang mà không hề bị pháp luật “sờ gáy”. Tuy nhiên, Jack không hoàn toàn tự do thực hiện sứ mệnh này. Để ra khỏi nhà tù, hắn đã kéo theo nữ cảnh sát Karen Sisco làm con tin...</p>', 'Full', 1, 'single', 'completed', 12, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Jennifer Lopez","avatar":""},{"name":"Ving Rhames","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324537);
