INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-ranh-do-mong-manh', 'Lằn Ranh Đỏ Mỏng Manh', 'The Thin Red Line', 'https://phimimg.com/upload/vod/20240102-1/fbf38a49f24b6af1d87f47e2fb3957c9.jpg', 'https://phimimg.com/upload/vod/20240102-1/8ecaff63a4024993844cc4d45aac32e4.jpg', '<p>Một nhóm binh sĩ phải đối mặt với một trận chiến khó xảy ra tại Guadalcanal, nơi họ chiến đấu với mọi khó khăn để tồn tại. Khi chiến tranh tiến triển, họ thua kém nhau trong khi vẫn hy vọng giành chiến thắng trong cuộc chiến.</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Penn","avatar":""},{"name":"Adrien Brody","avatar":""},{"name":"Jim Caviezel","avatar":""},{"name":"Ben Chaplin","avatar":""},{"name":"Elias Koteas","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
