INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-em-dem', 'Thị Trấn Êm Đềm', 'Pleasantville', 'https://phimimg.com/upload/vod/20231219-1/c06188236c02375fc992751348471db1.jpg', 'https://phimimg.com/upload/vod/20231219-1/688fecc564ebe8dbf4b029f419cb7946.jpg', '<p>Lạc Vào Thực Tại - Pleasantville (1998):Chán ghét cuộc sống thường nhật, tẻ nhạt của mình. Cậu thiếu niên david (Tobey Maguire) dùng hầu hết thời gian rảnh của mình để xem bộ phim viễn tưởng Pleasantville trong khi cô em gái song sinh Jennifer (Resse Witherspoon) tập trung vào vẻ ngoài và cuộc sống xã hội. Một anh nhân viên sửa ti vi đầy phép màu (Don Knotts) khiến hai người lạc vào thế giới không tưởng của Pleasantville. Ban đầu thì họ cố gắng thoát khỏi nó nhưng sau đó họ khám phá ra những người dân của thị trấn đó có một cuộc sống tràn ngập thú vị và sáng tạo, nhưng cũng đầy đam mê và không chắc chắn. Chính điều này đã làm cho mọi người chuyển cuộc sống của mình từ đen trắng sang màu sắc. Điều này đã làm người xem suy nghĩ rất nhiều, đôi khi chúng ta tưởng tượng cuộc sống của mình chắc chắn phải như vậy nhưng thực tế lại khác hoàn toàn.</p>', 'Full', 1, 'single', 'completed', 13, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tobey Maguire","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"William H. Macy","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
