INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thi-tran-em-dem', 'Thị Trấn Êm Đềm', 'Pleasantville', 'thị trấn êm đềm pleasantville tobey maguire reese witherspoon william h. macy ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-tu-do', 'Sát Thủ Tự Do', 'Ronin', 'https://phimimg.com/upload/vod/20231219-1/8181ee2b34c3d1147bbdbdb4618b8075.jpg', 'https://phimimg.com/upload/vod/20231219-1/1aa18b56a19a14af30920ea30f634144.jpg', '<p>Năm người đàn ông và một phụ nữ không hề quen biết gặp nhau trong một kho hàng hóa tại ngoại ô Paris. Nhiệm vụ của họ là đoạt lấy chiếc vali nhỏ chứa đựng một thứ bí mật. Năm người đàn ông chính là những cựu binh của cuộc chiến tranh lạnh sinh sống nhờ dịch vụ bí mật do họ hùn vốn làm ăn. Còn người phụ nữ Ireland thì lại tỏ ra thiếu kinh nghiệm. Trong một thế giới nơi mà sự trung thực bị đem ra mua bán và sự phản bội là phong cách sống, thì một hạng người khủng bố mới, giết người không ghê tay xuất hiện. Cuộc chiến tranh lạnh có thể đã kết thúc, nhưng lại tạo nên một nhóm giết thuê bí mật mà những tay chuyên nghiệp vốn là những cựu binh họp lại cùng hành động với nhau. Họ thực hiện những công việc kiểu ...</p>', 'Full', 1, 'single', 'completed', 12, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Natascha McElhone","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Sean Bean","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324537);
