INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-thu-tu-do', 'Sát Thủ Tự Do', 'Ronin', 'sát thủ tự do ronin robert de niro jean reno natascha mcelhone stellan skarsgård sean bean ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-vu-kien-dan-su', 'Một Vụ Kiện Dân Sự', 'A Civil Action', 'https://phimimg.com/upload/vod/20231219-1/d61bf5c8e388f654f7d3b41fb38681ec.jpg', 'https://phimimg.com/upload/vod/20231219-1/828d2eec72c502a4bafb20284edf7946.jpg', '<p>Jan Schlichtmann là một luật sư riêng, người làm giàu bằng cách hoàn thành tốt công việc. Anh khiến cho bồi thẩm đoàn đồng cảm với khách hàng của mình và tất nhiên khách hàng tìm được cách dàn xếp ổn thỏa cũng như nhận được sự khoan hồng từ pháp luật. Nhưng khi làm việc cho tám gia đình trong thị trấn nhỏ ở Massachusetts anh đã nhìn rõ hơn công việc của mình với nỗi xúc cảm lớn lao. Tám gia đình đó đã mắc bệnh bạch cầu sau khi uống nước có mầm bệnh từ một nhà cung cấp nước địa phương. Thủ phạm: hai trong số các tập đoàn lớn nhất đất nước đã coi vùng đất cạnh đó như một nơi chứa nước thải. Để tìm ra sự thực, vị luật sư này đã rút túi riêng của mình 2.6 triệu đô la tiền mặt để thực hiện các cuộc xét nghiệm khoa học và y tế. Erin Brockovich có thể chẳng có gì để mất nhưng Jan Schlichtmann thì có. Đó là danh tiếng, công việc và cả cuộc sống.</p>', 'Full', 1, 'single', 'completed', 14, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Travolta","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Tony Shalhoub","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324537);
