INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-bong-dem', 'Thành Phố Bóng Đêm', 'Dark City', 'https://phimimg.com/upload/vod/20231219-1/e08ed0c8227b0fcdcdcdce14fde138ac.jpg', 'https://phimimg.com/upload/vod/20231219-1/92320146ecd21db26083a1667695ea3d.jpg', '<p>Lúc nửa đêm, một người đàn ông choàng tỉnh giấc. Anh phát hiện mình trần trụi trong một bồn tắm tại phòng trọ. Ngay giữa phòng ngủ, xác một người phụ nữ khoả thân nằm trên vũng máu. Người đàn ông không thốt nên lời, anh gần như quay cuồng trong mớ câu hỏi: Tôi là ai? Tôi từ đâu tới? Tôi đã làm gì thế này? Giữa căn phòng tĩnh lặng, đen kịt, người đàn ông đáng thương không tìm đâu thấy một lời giải đáp. Bất chợt, một hồi chuông điện thoại reo vang, một người tự xưng là tiến sĩ Daniel Poe Schreber cho anh biết: rằng anh đang trong một cuộc thí nghiệm, rằng anh đã hoàn mất mất đi trí nhớ và hãy chạy thật nhanh trước khi những kẻ lạ mặt ngoài kia có thể túm lấy anh. Chỉ đợi có thế, người đàn ông lao vào màn đêm đen để tìm kiếm lời giải đáp cho những ẩn số về cuộc đời mình…</p>', 'Full', 1, 'single', 'completed', 14, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rufus Sewell","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Jennifer Connelly","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324537);
