INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tinh-tay-ba-truong-rushmore', 'Mối Tình Tay Ba Trường Rushmore', 'Rushmore', 'https://phimimg.com/upload/vod/20231214-1/07eeef66a050c7c7502e63e2eeefdabf.jpg', 'https://phimimg.com/upload/vod/20231214-1/d3337835cf8bd22d27ca55e987f239ef.jpg', '<p>Bộ phim xoay quanh nhân vật Max Fischer, một thanh niên mới có cá tính rất lập dị đang theo học tại Rushmore Academy. Max xuất thân nhà nghèo, nhưng có những ước mơ, hoài bão rất vĩ đại, thậm chí đến mức bị nhiều người cho là viển vông. Bỗng một ngày nọ, cậu phải lòng cô giáo lớp 1 Miss Cross. Max làm bạn với Blume, một triệu phú tính tình kì dị cũng có tình cảm với Miss Cross. Mối tình tay ba đặc biệt này ngày càng đưa Max đến với nhiều phức tạp trong cuộc sống, trong học tập, và cậu phải dần dần quen với những hậu quả do từng lời nói, từng hành động của mình đem lại.</p>', 'Full', 1, 'single', 'completed', 12, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Schwartzman","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"Olivia Williams","avatar":""},{"name":"Seymour Cassel","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Mason Gamble","avatar":""},{"name":"Sara Tanaka","avatar":""},{"name":"Stephen McCole","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Dipak Pallana","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
