INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ran', 'Mắt Rắn', 'Snake Eyes', 'https://phimimg.com/upload/vod/20231212-1/fe66e65a8841285ca6f6676a0a2ef995.jpg', 'https://phimimg.com/upload/vod/20231212-1/072194f658ecdb79e5ed4efeabaf4952.jpg', '<p>Mọi sự đặt cược đều tan vỡ khi cảnh sát điều tra tội phạm mờ ám Rick Santoro chứng kiến một vụ giết người trong một trận đấu quyền anh. Tùy thuộc vào anh ta và người bạn lâu năm, đặc vụ tình báo Hải quân Kevin Dunne để khám phá âm mưu đằng sau vụ giết người. Ở mỗi lượt đi, Santoro lại có những khám phá ngày càng gây sốc mà ngay cả anh cũng không thể nhắm mắt làm ngơ.</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Gary Sinise","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"John Heard","avatar":""},{"name":"Stan Shaw","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Michael Rispoli","avatar":""},{"name":"Joel Fabiani","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"David Anthony Higgins","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324537);
