INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-cau', 'Tinh Cầu', 'Sphere', 'https://phimimg.com/upload/vod/20231212-1/f9d324061c6a004c79ea4f4f8a89056c.jpg', 'https://phimimg.com/upload/vod/20231212-1/7314a1b8717e45f548331a702c23fdb4.jpg', '<p>Một con tàu vũ trụ được phát hiện dưới đáy Thái Bình Dương, được cho là ít nhất 300 năm tuổi và có nguồn gốc ngoài hành tinh. Một nhóm gồm các nhà khoa học và chuyên gia giỏi được tập hợp và đưa đến Habitat, một môi trường sống dưới nước hiện đại, để điều tra.</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dustin Hoffman","avatar":""},{"name":"Sharon Stone","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Peter Coyote","avatar":""},{"name":"Liev Schreiber","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324537);
