INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-lien-bang', 'Cảnh Sát Liên Bang', 'U.S. Marshals', 'https://phimimg.com/upload/vod/20231212-1/d912a17de5d49799ffe9d7b40dc1b854.jpg', 'https://phimimg.com/upload/vod/20231212-1/56dfcba5791450785f78634096a307ad.jpg', '<p>Viên phó chỉ huy sở cảnh sát Samuel Gerard nhận nhiệm vụ áp giải tội phạm từ Chicago đến New York. Trên đường đi, chiếc máy bay gặp tai nạn, tên tội phạm Mark Sheridan thừa cơ trốn thoát. Ngài phó cảnh sát cùng đội điều tra tài năng của mình liền nhảy vào cuộc. Nhưng tình huống nhanh chóng phát triển thành một vụ việc phức tạp hơn khi Samuel phát hiện ra Mark không chỉ đơn thuần là một tên tội phạm. Có vẻ như những lời buộc tội và câu chuyện xoay quanh hắn không hề có cơ sở, Samuel quyết định điều tra lại vụ án mà không biết rằng mình vô tình bước vào ván cờ đầy mưu mô của chính phủ!</p>', 'Full', 1, 'single', 'completed', 12, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tommy Lee Jones","avatar":""},{"name":"Wesley Snipes","avatar":""},{"name":"Robert Downey Jr.","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324537);
