INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-tinh-nghich', 'Cô Nàng Tinh Nghịch', 'Frivolous Lola', 'https://phimimg.com/upload/vod/20231211-1/cd71a79f0556b7fd3f23388a482ea2bf.jpg', 'https://phimimg.com/upload/vod/20231211-1/8320c33e5a6524b14b69df6dd9af40f9.jpg', '<p>Lola và Masetto chuẩn bị kết hôn. Masetto muốn giữ Lola như một trinh nữ cho đến khi họ kết hôn. Nhưng Lola là thiếu kiên nhẫn chờ đợi cho đến đêm tân hôn. Cô ấy muốn làm chắc chắn rằng Masetto là một người yêu tốt, trước khi cam kết mình vào cuộc hôn nhân. Lola làm mọi thứ để lừa Masetto phá vỡ truyền thống đạo đức...</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Anna Ammirati","avatar":""},{"name":"Serena Grandi","avatar":""},{"name":"Patrick Mower","avatar":""},{"name":"Zuzana Martinková","avatar":""},{"name":"Antonio Salines","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324537);
