INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-bat-tu', 'Quỷ Bất Tử', 'Fallen', 'https://phimimg.com/upload/vod/20231211-1/06da7fd9345b0085ebb4771d764c4c2c.jpg', 'https://phimimg.com/upload/vod/20231211-1/3bcb145c12de64f0d069a76d9c28a0a0.jpg', '<p>Câu chuyện bắt đầu bằng việc hành hình tên sát nhân hàng loạt Edgar Reese và người tóm được hắn là thám tử John Hobbes. Mọi việc tưởng chừng như dừng lại tại đây nếu không có hàng loạt vụ giết người khác lại xảy ra và cách phạm tội lại giống như Edgar Reese và lần này Hobbes lại bị cuốn vào. Càng đi sâu vào vụ án, anh càng phát hiện ra những điều bí ẩn liên quan đến sự hiện diện 1 con quỷ bất tử có trong kinh thánh của người Syri.</p>', 'Full', 1, 'single', 'completed', 12, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"James Gandolfini","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324537);
