INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-tam-anh-hung-tieng-quang-dong', 'Chân Tâm Anh Hùng (Tiếng Quảng Đông)', 'A HERO NEVER DIES ( Cantonese )', 'null', 'https://phimimg.com/upload/vod/20231209-1/9ee0a7be1fea31c0e91b2910edc78b2c.jpg', '<p>Jack và Thu thuộc hai đảng phái trên giang hồ, nhưng họ đã sớm biết đến danh tính của nhau. Một lần họ gặp nhau ở quán bar,họ đã tìm ra được những điểm tương đồng nhau, sau đó hai bên đã quyết đấu, sau trận đấu ở Thái Lan, Thu bị thương tở thành phế nhân, Jack bị truy sát, hai người đã bị hai đảng phái mà họ kính trọng nhất truy đuổ, bị mất đi niềm tin yêu, cuối cùng họ quay lại quán bar và quyết định trả thù.</p>', 'Full', 1, 'single', 'completed', 11, 1998, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ching Wan Lau","avatar":""},{"name":"Leon.Lai Ming","avatar":""},{"name":"Yoyo Mung","avatar":""},{"name":"Yoyo Mung Ka-Wai","avatar":""},{"name":"Suet Lam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324537);
