INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-muu-sat-hoan-hao', 'Vụ Mưu Sát Hoàn Hảo', 'A Perfect Murder', 'https://phimimg.com/upload/vod/20231209-1/8415841c024afda4299bb6824a4b118f.jpg', 'https://phimimg.com/upload/vod/20231209-1/70b2ac01e4331eac188f422392d8dd5c.jpg', '<p>Nhà công nghiệp triệu phú Steven Taylor là một người đàn ông có tất cả mọi thứ nhưng điều mà ông khao khát nhất: tình yêu và sự chung thủy của người vợ. Là một tay chơi cực kỳ thành công trong thế giới tài chính New York, anh coi cô là tài sản quý giá nhất của mình. Nhưng cô ấy cần nhiều hơn vai trò của một phụ kiện rực rỡ.</p>', 'Full', 1, 'single', 'completed', 13, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Hester","avatar":""},{"name":"Tony Martin","avatar":""},{"name":"Bob Franklin","avatar":""},{"name":"Judith Lucy","avatar":""},{"name":"Mick Molloy","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324537);
