INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-parent-trap', 'The Parent Trap', 'The Parent Trap', 'https://phimimg.com/upload/vod/20231208-1/0bd106e5de6a0116d8078865bb82fb24.jpg', 'https://phimimg.com/upload/vod/20231208-1/6b3bc55c31a8cda59fc18b3cf0c1bbfe.jpg', '<p>Khi hai người trước tuổi thanh thiếu niên tên là Hallie và Annie gặp nhau qua trại hè của họ, hai cuộc đời của họ đang reattled khi họ nhận ra rằng họ là cặp song sinh giống hệt nhau. Với cha mẹ, người mẹ Anh còn gọi là thiết kế trang phục nổi tiếng Elizabeth và người cha Mỹ, một nhà sản xuất rượu vang tên là Nick, sống ở hai phía khác nhau của vũ trụ, các cô gái quyết định trao đổi danh tính với hy vọng dành thời gian với cha mẹ khác. Các cô gái sau đó chọn thông báo cho những người bảo vệ trao đổi của họ trong khi tại một khách sạn ở San Francisco, sau đó đoàn tụ cặp đã ly hôn và đưa họ trở lại vào tái hôn với nhau</p>', 'Full', 1, 'single', 'completed', 13, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324537);
