INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-sau-ji-wong', 'Sat Sau Ji Wong', 'Contract Killer', 'https://phimimg.com/upload/vod/20231208-1/bd50ec5cf6e146179325ee8a0fc552f6.jpg', 'https://phimimg.com/upload/vod/20231208-1/f2042dedb9760b586645eafbc68f7651.jpg', '<p>Trong phim Sát Thủ Bá Vương (Hitman) Một cảnh sát đã không thể dùng luật pháp để trừng trị bọn tội phạm nên anh đã biến mình thành 1 sát thủ để tiêu diệt bọn tội phạm. 1 tổ chức xã hội đên đã treo giải thưởng giết 1 thủ lĩnh của yakuza ở nhật bản , giá trị lên đến 100 triệu USD, Sau khi giải thưởng dc phát lên thì làm chấn động thế giới xã hội đen và cảnh sát...</p>', 'Full', 1, 'single', 'completed', 10, 1998, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jet Li","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Gigi Leung","avatar":""},{"name":"Timmy Ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324537);
