INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('madeline-tinh-ngich', 'Madeline Tinh Ngịch', 'Madeline', 'https://phimimg.com/upload/vod/20231219-1/0beae753b3b032bcb9eaf862bc756c7a.jpg', 'https://phimimg.com/upload/vod/20231219-1/2fd73e1f62e426312b1e4e57fd00f661.jpg', '<p>Kinh hoàng trước viễn cảnh ngôi trường thân yêu của mình bị bán, một cô gái trẻ người Pháp tên Madeline đã sử dụng sự thông minh và xảo quyệt của mình để cố gắng cứu lấy ngôi trường, đồng thời kết bạn với một người bạn mới lạ trong quá trình này.</p>', 'Full', 1, 'single', 'completed', 13, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hatty Jones","avatar":""},{"name":"Frances McDormand","avatar":""},{"name":"Nigel Hawthorne","avatar":""},{"name":"Ben Daniels","avatar":""},{"name":"Arturo Venegas","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
