INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-vet-paulie', 'Chú Vẹt Paulie', 'Paulie', 'https://phimimg.com/upload/vod/20231205-1/b8f12ee9aed9e502ce329c04dfabc4d8.jpg', 'https://phimimg.com/upload/vod/20231205-1/1793289865807ff850d0200b7c96a2e4.jpg', '<p>Câu chuyện về Paulie bắt đầu từ nhiều năm trước khi chú được tặng cho một cô bé bị tật nói lắp. Cuối cùng, chú dạy cho cô bé biết nói nhưng sau đó Paulie bị cha cô bé tống khứ vì ông nghĩ con gái ông không thể phân biệt được giữa thực tại và tưởng tượng khi cô tin rằng chú vẹt biết nói tiếng người. Paulie trải qua một chuỗi các cuộc phiêu lưu với một chủ cửa hàng cầm đồ, một góa phụ già, một chàng hát rong người Mỹ gốc Mexico và một kẻ trộm trước khi bị bắt vào viện nghiên cứu....</p>', 'Full', 1, 'single', 'completed', 14, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gena Rowlands","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Cheech Marin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324537);
