INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-si-dam-cuoi', 'Ca Sĩ Đám Cưới', 'The Wedding Singer', 'https://phimimg.com/upload/vod/20231204-1/e8de6474afad271fac027579a593f653.jpg', 'https://phimimg.com/upload/vod/20231204-1/fd87d421a8c5e1605933e1af01888960.jpg', '<p>Đau đớn khi bị người yêu bỏ rơi ngay trong nhà thờ, Robbie Hart từ bỏ ban nhạc rock yêu quý để trở thành một ca sĩ chuyên hát thuê cho các đám cưới trong nhà thờ. Tuy nhiên công việc của anh không thể mang lại không khí vui vẻ trong đám cưới, ngược lại anh thường xuyên làm mọi người bực mình. Cuộc sống của Robbie cân bằng trở lại khi anh quen cô hầu bàn xinh đẹp Julia. Cô luôn có mặt bên cạnh anh, động viên anh những lúc khó khăn. Julia đã có vị hôn phu tương lai là Glenn. Họ yêu nhau trong 4 năm trời nhưng Julia lo lắng rằng Glenn sẽ không cưới cô. Khi Glenn chính thức đồng ý đính hôn cũng là lúc Julia rối bời trong cảm xúc hỗn độn vì cô bắt đầu cảm thấy có tình cảm với Robbie. Tình bạn của họ ngày càng thân thiết, và rồi cả hai đều nhận ra họ dành cho nhau thứ tình cảm đặc biệt chứ không đơn thuần là tình bạn. Robbie trút bỏ nỗi lòng mình vào một bài hát ngọt ngào ở sân bay với đám đông cổ vũ vây quanh… Liệu lời tỏ tình chân thành và lãng mạn của anh có phải là quá muộn?</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"Christine Taylor","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
