INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-don-gian', 'Kế Hoạch Đơn Giản', 'A Simple Plan', 'https://phimimg.com/upload/vod/20231204-1/8e6e25f469bb85864fb06eaeeb658898.jpg', 'https://phimimg.com/upload/vod/20231204-1/6d1a791dcc301328dd28999d169dfc38.jpg', '<p>Bị thu hút bởi sự giàu có bất ngờ, cuộc sống yên bình ở nông thôn của hai anh em nổ ra xung đột giữa lòng tham, sự hoang tưởng và sự ngờ vực khi hơn 4 triệu đô la tiền mặt được phát hiện tại địa điểm xa xôi của một chiếc máy bay nhỏ bị rơi. Kế hoạch đơn giản của họ để giữ lại tiền trong khi tránh bị phát hiện sẽ mở ra chiếc hộp Pandoras khi nỗi sợ bị bắt đã gây ra hành vi hoảng loạn và dẫn đến những hậu quả tai hại.</p>', 'Full', 1, 'single', 'completed', 13, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Paxton","avatar":""},{"name":"Billy Bob Thornton","avatar":""},{"name":"Bridget Fonda","avatar":""},{"name":"Brent Briscoe","avatar":""},{"name":"Jack Walsh","avatar":""},{"name":"Chelcie Ross","avatar":""},{"name":"Becky Ann Baker","avatar":""},{"name":"Gary Cole","avatar":""},{"name":"Bob Davis","avatar":""},{"name":"Peter Syvertsen","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324537);
