INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-gia-dinh', 'Bí Mật Của Gia Đình', 'The Quiet Family', 'https://phimimg.com/upload/vod/20231130-1/190ba1444d5ee29f719649e5741e1689.jpg', 'https://phimimg.com/upload/vod/20231130-1/a8261b2cf3c6d0dc9925f347a1d9fdae.jpg', '<p>Bí Mật của Gia Đình - The Quiet Family (1998):Với mục đích kiếm nhiều tiền hơn, gia đình nọ quyết định mở nhà trọ kinh doanh trên ngọn đồi tại vùng ngoại ô thành phố Seoul. Họ hy vọng sẽ có nhiều du khách ghé tham quan và tá túc, nhưng sau thời gian dài khai trương vẫn không có vị khách nào ở lại. Cho đến một ngày, người đàn ông đầu tiên đặt chân đến và được cả gia đình tiếp đón niềm nở. Nhưng anh ta chết bất ngờ, không rõ lý do...</p>', 'Full', 1, 'single', 'completed', 20, 1998, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Park In-hwan","avatar":""},{"name":"Na Moon-hee","avatar":""},{"name":"Choi Min-sik","avatar":""},{"name":"Song Kang-ho","avatar":""},{"name":"Lee Yoon-sung","avatar":""},{"name":"Go Ho-kyung","avatar":""},{"name":"Ji Soo-won","avatar":""},{"name":"Lee Ki-young","avatar":""},{"name":"Ki Joo-bong","avatar":""},{"name":"Jung Jae-young","avatar":""},{"name":"Jang Ga-hyun","avatar":""},{"name":"Choi Cheol-ho","avatar":""},{"name":"Jung Woong-in","avatar":""},{"name":"Yoo Hyung-gwan","avatar":""},{"name":"Jang In-han","avatar":""},{"name":"Jo Deok-jae","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324537);
