INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-van-hung-ba-thien-ha-1998', 'Phong Vân: Hùng Bá Thiên Hạ', 'The Storm Riders', 'https://phimimg.com/upload/vod/20231123-1/06a069a25f1380235ff56382e80bc433.jpg', 'https://phimimg.com/upload/vod/20231123-1/bee0508c5d516e31e8698f1719c49095.jpg', '<p>Hùng Bá tìm khắp bốn bể các nam tử đáp ứng lời tiên tri, sát hại phụ mẫu chúng và nuôi dạy chúng. Giữ kẻ thù bên mình, hắn đào tạo các cô nhi với mưu đồ bá chủ thiên hạ.</p>', 'Full', 1, 'single', 'completed', 13, 1998, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Ekin Cheng Yee-Kin","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Kristy Yang","avatar":""},{"name":"Alex Fong Chung-Sun","avatar":""},{"name":"Sonny Chiba","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Lawrence Cheng","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""},{"name":"Jason Chu Wing-Tong","avatar":""},{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"Roy Cheung","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Christine Ng","avatar":""},{"name":"Xu Jinglei","avatar":""},{"name":"Elvis Tsui K","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324537);
