INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-tai-giang-ho-1998', 'Long Tại Giang Hồ', 'A True Mob Story', 'https://phimimg.com/upload/vod/20231006-1/631cc88c16abf9ac93da34f4c6518c1a.jpg', 'https://phimimg.com/upload/vod/20231006-1/8a14b0a6652941ee46b8b5aa67145332.jpg', '<p>Nội dung phim xoay quanh cuộc sống của một tên du đãng luôn muốn trở thành thủ lĩnh. Trong một cuộc hỗn chiến giữa hai ông chủ có thế lực nhất lúc bấy giờ, hắn đã liều mình bảo vệ ông chủ Prince thoát khỏi sự truy sát của đối phương. Điều này đã giúp hắn được toại nguyện. Thế nhưng, điều Cheung Dee không thể lường trước được là cái giá phải trả cho giấc mơ đó quá đắt. Hắn mất vợ, đứa con trai hai tuổi thì mất mẹ. Từ khi tận mắt chứng kiến chiếc xe tải đâm vào vợ mình, hắn thật sự chùn bước. Hắn bắt đầu biết sợ. Sợ chết, sợ vào tù. Hắn không muốn con trai hắn mất luôn cả cha. Nhưng điều có có phải đã quá muộn màng?</p>', 'Full', 1, 'single', 'completed', 10, 1998, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Gigi Leung","avatar":""},{"name":"Suki Kwan","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Alex Fong","avatar":""},{"name":"Joe Ma","avatar":""},{"name":"Sam Lee","avatar":""},{"name":"Frankie Ng","avatar":""},{"name":"Ben Ngai-Cheung Ng","avatar":""},{"name":"Michael Chan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
