INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-tuoc-khong-lo-1998', 'Bạch Tuộc Khổng Lồ', 'Deep Rising', 'https://phimimg.com/upload/vod/20231123-1/021ca0ba8a329cd86e61eacaabd01f08.jpg', 'https://phimimg.com/upload/vod/20231123-1/7069826ab7afb6d760c5c8d7c6ca126b.jpg', '<p>Một nhóm không tặc được vũ trang mạnh mẽ lên một chiếc tàu biển sang trọng ở Nam Thái Bình Dương để cướp bóc nó, chỉ để chiến đấu với một loạt sinh vật biển ăn thịt người có kích thước lớn, có xúc tu, những kẻ đã chiếm lấy con tàu trước.</p>', 'Full', 1, 'single', 'completed', 13, 1998, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Treat Williams","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Anthony Heald","avatar":""},{"name":"Kevin J. O''Connor","avatar":""},{"name":"Wes Studi","avatar":""},{"name":"Derrick O''Connor","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Clifton Powell","avatar":""},{"name":"Trevor Goddard","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Una Damon","avatar":""},{"name":"Clint Curtis","avatar":""},{"name":"Warren Takeuchi","avatar":""},{"name":"Linden Banks","avatar":""},{"name":"Jack Anker","avatar":""},{"name":"Anne-S","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324537);
