INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-co-thu', 'Bạn Có Thư', 'You''ve Got Mail', 'https://phimimg.com/upload/vod/20231129-1/6a1c1d67183acf831ac34e67ba0d68d8.jpg', 'https://phimimg.com/upload/vod/20231129-1/c48f861a5e1f69f9bb47a2c3c0275bf3.jpg', '<p>Câu chuyện về hai người sống ở New York quen nhau trên mạng và rất cảm mến nhau. Nhưng ở đời thường, họ không ngờ lại là đối thủ của nhau: Anh là ông chủ tiệm sách lớn. Cô là chủ tiệm sách nhỏ và họ đối đầu trong việc cạnh tranh... Và rồi, anh phát hiện ra nàng chính là người mình quen trên mạng...</p>', 'Full', 1, 'single', 'completed', 14, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Meg Ryan","avatar":""},{"name":"Greg Kinnear","avatar":""},{"name":"Parker Posey","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Dave Chappelle","avatar":""},{"name":"Dabney Coleman","avatar":""},{"name":"Jean Stapleton","avatar":""},{"name":"Heather Burns","avatar":""},{"name":"John Randolph","avatar":""},{"name":"Hallee Hirsh","avatar":""},{"name":"Jeffrey Scaperrotta","avatar":""},{"name":"Cara Seymour","avatar":""},{"name":"Katie Finneran","avatar":""},{"name":"Michael Badalucco","avatar":""},{"name":"Deborah Rush","avatar":""},{"name":"Veanne Cox","avatar":""},{"name":"Bruce","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324537);
