INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-mang-mat-na-sat', 'Người Mang Mặt Nạ Sắt', 'The Man in the Iron Mask', 'https://phimimg.com/upload/vod/20231129-1/46c60a205f8e116c0dad7ca2f806d828.jpg', 'https://phimimg.com/upload/vod/20231129-1/9ac036bd1a250ffd101b5a4476500041.jpg', '<p>Nhiều năm đã trôi qua kể từ khi Ba người lính ngự lâm, Aramis, Athos và Porthos, chiến đấu cùng với người bạn của họ, D&quot;Artagnan. Nhưng với việc Vua Louis độc tài sử dụng quyền lực của mình để tàn phá vương quốc trong khi người anh song sinh của ông, Philippe, vẫn bị giam cầm, những người lính ngự lâm đã đoàn tụ để bắt cóc Louis và thay thế ông bằng Philippe.</p>', 'Full', 1, 'single', 'completed', 14, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Gabriel Byrne","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"Anne Parillaud","avatar":""},{"name":"Judith Godrèche","avatar":""},{"name":"Edward Atterton","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"Hugh Laurie","avatar":""},{"name":"David Lowe","avatar":""},{"name":"Brigitte Boucher","avatar":""},{"name":"Matthew Jocelyn","avatar":""},{"name":"Karine Belly","avatar":""},{"name":"Emmanuel Guttierez","avatar":""},{"name":"Christian Er","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
