INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-bang-nhom', 'Cuộc Chiến Băng Nhóm', 'Gang Land', 'null', 'https://phimimg.com/upload/vod/20231129-1/1df122fce971823eb25f31ce3c6ac360.jpg', '<p>Khi các băng nhóm ngầm của Holywood bắt đầu lấn chiếm lãnh thổ của nhau, thì lòng trung thành của các thành viên trong băng nhóm được quyết định bởi màu da, nỗi đau , bạo lực và tuân theo luật rừng.</p>', 'Full', 1, 'single', 'completed', 16, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"JJ Snyder","avatar":""},{"name":"Damon Jones","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
