INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-cua-nhung-thien-than', 'Thành Phố Của Những Thiên Thần', 'City of Angels', 'https://phimimg.com/upload/vod/20231125-1/abe923f93f183b9a7103442deb26e4ec.jpg', 'https://phimimg.com/upload/vod/20231125-1/dce3de8012fe05e193772f22a7a5b099.jpg', '<p>Khi thiên thần hộ mệnh Seth - người vô hình trông chừng các công dân của Los Angeles - bị quyến rũ bởi Maggie, một bác sĩ phẫu thuật tim có ý chí mạnh mẽ, anh cân nhắc đánh đổi sự tồn tại thuần khiết, ở thế giới khác của mình để lấy một cuộc sống phàm trần với người mình yêu. Cặp đôi bắt đầu một mối tình lãng mạn dịu dàng nhưng bị cấm đoán trải dài trên trời và dưới đất.</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Meg Ryan","avatar":""},{"name":"Andre Braugher","avatar":""},{"name":"Dennis Franz","avatar":""},{"name":"Colm Feore","avatar":""},{"name":"Robin Bartlett","avatar":""},{"name":"Joanna Merlin","avatar":""},{"name":"Sarah Dampf","avatar":""},{"name":"Rhonda Dotson","avatar":""},{"name":"Nigel Gibbs","avatar":""},{"name":"John Putch","avatar":""},{"name":"Lauri Johnson","avatar":""},{"name":"Christian Aubert","avatar":""},{"name":"Jay Patterson","avatar":""},{"name":"Shishir Kurup","avatar":""},{"name":"Brian Markinson","avatar":""},{"name":"Elisabeth Shue","avatar":""},{"name":"Alexander","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324537);
