INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-pho-cua-nhung-thien-than', 'Thành Phố Của Những Thiên Thần', 'City of Angels', 'thành phố của những thiên thần city of angels nicolas cage meg ryan andre braugher dennis franz colm feore robin bartlett joanna merlin sarah dampf rhonda dotson nigel gibbs john putch lauri johnson christian aubert jay patterson shishir kurup brian markinson elisabeth shue alexander ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('babe-chu-heo-trong-thanh-pho', 'Babe: Chú Heo Trong Thành Phố', 'Babe: Pig in the City', 'https://phimimg.com/upload/vod/20231121-1/4af12cab5f2ef69a7df806557cec5dc6.jpg', 'https://phimimg.com/upload/vod/20231121-1/89f931e279f70ceecd590b2c36a9a2d4.jpg', '<p>Để cứu cánh cho nông trại sắp bị tịch thu, chú lợn Babe phải tham dự một hội chợ hứa hẹn nhiều tiền thưởng. Cuộc phiêu lưu của Babe tới thành phố lớn thực sự là cơn ác mộng cho cả chú lợn thông mình và bà chủ của nó.Sau chiến thắng vinh quang của Babe (E. G. Daily lồng tiếng) trong cuộc thi chăn cừu, ông nông dân Arthur Hoggett (James Cromwell) đã từ chối mọi lời mời kiếm tiền nhờ tài năng của chú lợn. Nhưng khi ông ngã xuống giếng bị thương nặng và phải nằm liệt giường, Esme Hoggett (Magna Szubanski) vợ ông đã phải tiếp quản mọi việc của nông trại. Bà đã cố gắng hết sức nhưng không trả được nợ nần cho ngân hàng, tài sản có khả năng bị tịch thu và tất yếu phải nhờ tới sự nổi tiếng của Babe để cứu cánh. Ngay sau đó, ...</p>', 'Full', 1, 'single', 'completed', 21, 1998, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Magda Szubanski","avatar":""},{"name":"Elizabeth Daily","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Mary Stein","avatar":""},{"name":"Mickey Rooney","avatar":""},{"name":"Danny Mann","avatar":""},{"name":"Glenne Headly","avatar":""},{"name":"Steven Wright","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Nathan Kress","avatar":""},{"name":"Myles Jeffrey","avatar":""},{"name":"Stanley Ralph Ross","avatar":""},{"name":"Russi Taylor","avatar":""},{"name":"Adam Goldberg","avatar":""},{"name":"Eddie Barth","avatar":""},{"name":"Bill Capizzi","avatar":""},{"name":"Miriam Margolyes","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324537);
