INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('babe-chu-heo-trong-thanh-pho', 'Babe: Chú Heo Trong Thành Phố', 'Babe: Pig in the City', 'babe: chú heo trong thành phố babe: pig in the city magda szubanski elizabeth daily james cromwell mary stein mickey rooney danny mann glenne headly steven wright james cosmo nathan kress myles jeffrey stanley ralph ross russi taylor adam goldberg eddie barth bill capizzi miriam margolyes ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-bien-phap-tuyet-vong', 'Các Biện Pháp Tuyệt Vọng', 'Desperate Measures', 'https://phimimg.com/upload/vod/20231121-1/3e9909b71c256caf800a784448f649b0.jpg', 'https://phimimg.com/upload/vod/20231121-1/2a62965fc08b326ebf0983d0de33799c.jpg', '<p>Nhân viên cảnh sát San Francisco, Frank Conner đang tìm kiếm một nhà cung cấp tủy xương tương thích cho con trai ông, Matt, người bị bệnh bạch cầu. Trong tuyệt vọng, anh đột nhập vào trụ sở FBI và tìm thấy một kết hợp hoàn hảo. Thật không may, đó là Peter McCabe, một người đang sống trong tù vì tội giết người. Trong thời gian bị giam, McCabe khôn ngoan đã cố gắng trốn thoát và giết chết một số lính canh và tù nhân đồng phạm và phải bị giam trong phòng biệt lập của mình. Đầu tiên, McCabe tỏ ra rất ít quan tâm đến việc giúp đỡ Conner, nhưng sau đó tìm ra cơ hội để biến tình hình thành lợi thế và lập kế hoạch trốn thoát. McCabe đánh cờ với máy tính, dễ dàng đánh bại chương trình và biểu lộ sự cần thiết một cuộc thách thức tương tự như Garry Kasparov hay Deep Blue. Trong khi đó, Conner, cùng với đội trưởng cảnh sát Cassidy và bác sĩ Matt, tiến sĩ Hawkins, chuẩn bị cho McCabe được chuyển đến bệnh viện để cấy ghép.</p>', 'Full', 1, 'single', 'completed', 16, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Keaton","avatar":""},{"name":"Andy García","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"Erik King","avatar":""},{"name":"Efrain Figueroa","avatar":""},{"name":"Joseph Cross","avatar":""},{"name":"Janel Moloney","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"Tracey Walter","avatar":""},{"name":"Keith Diamond","avatar":""},{"name":"Peter Weireter","avatar":""},{"name":"Steve Park","avatar":""},{"name":"Dennis Cockrum","avatar":""},{"name":"John C. Meier","avatar":""},{"name":"Norman Howell","avatar":""},{"name":"John Rottger","avatar":""},{"name":"Donna","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
