INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-ai-cap', 'Hoàng Tử Ai Cập', 'The Prince of Egypt', 'https://phimimg.com/upload/vod/20231123-1/5d40cb47a744410c1d758d595ea63a68.jpg', 'https://phimimg.com/upload/vod/20231123-1/941bc6c8aafccfa63b1755ea6c1557fb.jpg', '<p>Bộ phim kể về câu chuyện của một cậu bé người Do Thái, lưu lạc đến hoàng cung Ai Cập và được nhà vua nhận làm con nuôi, khi lớn lên, cậu tìm lại nguồn gốc của mình và tìm cách giải thoát cho dân tộc mình khỏi ách áp bức của người Ai Cập.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Val Kilmer","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Sandra Bullock","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Steve Martin","avatar":""},{"name":"Martin Short","avatar":""},{"name":"Bobby Motown","avatar":""},{"name":"Eden Riegel","avatar":""},{"name":"Ofra Haza","avatar":""},{"name":"James Avery","avatar":""},{"name":"Aria Noelle Curzon","avatar":""},{"name":"Stephanie Sawyer","avatar":""},{"name":"Francesca Marie","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324537);
