INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-doi-ky-cuc-2', 'Cặp Đôi Kỳ Cục 2', 'The Odd Couple II', 'https://phimimg.com/upload/vod/20231120-1/6d17df7f73f3b04a31f4c13565573e59.jpg', 'https://phimimg.com/upload/vod/20231120-1/9eceb8d6100a7f1a4bb973a68475597f.jpg', '<p>Brucey, con trai của Oscar, gọi cho cha mình để mời anh đến dự đám cưới của ông với con gái của Felix vào Chủ nhật tới ở California. Oscar và Felix gặp lại nhau tại Sân bay Quốc tế Los Angeles và thuê một chiếc ô tô để đến San Malina dự đám cưới.</p>', 'Full', 1, 'single', 'completed', 18, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Lemmon","avatar":""},{"name":"Walter Matthau","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"Jonathan Silverman","avatar":""},{"name":"Lisa Waltz","avatar":""},{"name":"Mary Beth Peil","avatar":""},{"name":"Christine Baranski","avatar":""},{"name":"Jean Smart","avatar":""},{"name":"Rex Linn","avatar":""},{"name":"Jay O. Sanders","avatar":""},{"name":"Barnard Hughes","avatar":""},{"name":"Ellen Geer","avatar":""},{"name":"Doris Belack","avatar":""},{"name":"Mary Fogarty","avatar":""},{"name":"Alice Ghostley","avatar":""},{"name":"Peggy Miley","avatar":""},{"name":"Rebecca Schull","avatar":""},{"name":"Flo","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324537);
