INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-dang-karate-4', 'Nhất Đẳng Karate 4', 'Best of the Best 4: Without Warning', 'https://phimimg.com/upload/vod/20231129-1/387cc48c9fc24235d4c4f2fd7c9a4074.jpg', 'https://phimimg.com/upload/vod/20231129-1/41419c8d9b1d1e7080b2b4d19838e037.jpg', '<p>Nhất Đẳng Karate 4 - Best of the Best 4 kể về một nhóm côn đồ người Nga đã đánh cắp nguồn cung cấp giấy khổng lồ để in tiền Mỹ và khiến thị trường tràn ngập những tờ tiền giả. Một cô gái đã chạy trốn khỏi bọn côn đồ và giao dữ liệu trong đĩa CD cho Tommy Lee. Với tư cách là một huấn luyện viên võ thuật nhưng vì nhiều lý do, Lee không đến gặp cảnh sát với chiếc đĩa mà thay vào đó, tiếp tục chạy trốn, tạo điều kiện cho mafia bắt cóc con gái anh để làm con tin để đổi lấy chiếc đĩa.</p>', 'Full', 1, 'single', 'completed', 17, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Phillip Rhee","avatar":""},{"name":"Ernie Hudson","avatar":""},{"name":"Tobin Bell","avatar":""},{"name":"Thure Riefenstein","avatar":""},{"name":"Jessica Collins","avatar":""},{"name":"Chris Lemmon","avatar":""},{"name":"Paul Gleason","avatar":""},{"name":"Art LaFleur","avatar":""},{"name":"Sven-Ole Thorsen","avatar":""},{"name":"Jessica Huang","avatar":""},{"name":"Jill Ritchie","avatar":""},{"name":"Ilia Volok","avatar":""},{"name":"David ''Shark'' Fralick","avatar":""},{"name":"Shauna O''Brien","avatar":""},{"name":"J.J. Perry","avatar":""},{"name":"Richard Cetro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324537);
