INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-dang-karate-4', 'Nhất Đẳng Karate 4', 'Best of the Best 4: Without Warning', 'nhất đẳng karate 4 best of the best 4: without warning phillip rhee ernie hudson tobin bell thure riefenstein jessica collins chris lemmon paul gleason art lafleur sven-ole thorsen jessica huang jill ritchie ilia volok david ''shark'' fralick shauna o''brien j.j. perry richard cetro ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-tinh-cua-mary', 'Câu Chuyện Tình của Mary', 'There''s Something About Mary', 'https://phimimg.com/upload/vod/20231117-1/904a858ecbce6b638738dfbcc68fb129.jpg', 'https://phimimg.com/upload/vod/20231117-1/ca8ce65432b0af0c021d93462627453e.jpg', '<p>Ted (Ben Stiller) là một chàng trai rụt rè và buồn tẻ ở trường trung học. Vào ngày cuối cùng của năm học, Ted dự định mời Mary (Cameron Diaz), một trong những cô gái xinh đẹp và nổi tiếng nhất trường đi Prom và anh đã thành công. Song Ted đã không bao giờ có mặt ở kỳ Prom năm đó vì một tai nạn hi hữu và buồn cười Mười ba năm sau, Ted nhận ra rằng mình vẫn còn yêu Mary, thông qua một người bạn Woogie (Chris Elliott), anh tìm đến một thám tử tư (Matt Dillon) để truy tìm dấu vết Mary. Tay thám tử sau cùng phát hiện ra rằng mình cũng yêu Mary nên hắn đưa cho Ted vài thông tin giả để Ted từ bỏ hy vọng.Tuy nhiên sau cùng Ted cũng tìm đuợc con đuờng để đến với Mary trong một kết thúc buồn cười.</p>', 'Full', 1, 'single', 'completed', 17, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cameron Diaz","avatar":""},{"name":"Matt Dillon","avatar":""},{"name":"Ben Stiller","avatar":""},{"name":"Lee Evans","avatar":""},{"name":"Chris Elliott","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"Markie Post","avatar":""},{"name":"Keith David","avatar":""},{"name":"W. Earl Brown","avatar":""},{"name":"Sarah Silverman","avatar":""},{"name":"Khandi Alexander","avatar":""},{"name":"Marnie Alexenburg","avatar":""},{"name":"Danny Murphy","avatar":""},{"name":"Richard Tyson","avatar":""},{"name":"Rob Moran","avatar":""},{"name":"Jackie Flynn","avatar":""},{"name":"Hillary Matth","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324537);
