INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-tinh-cua-mary', 'Câu Chuyện Tình của Mary', 'There''s Something About Mary', 'câu chuyện tình của mary there''s something about mary cameron diaz matt dillon ben stiller lee evans chris elliott lin shaye jeffrey tambor markie post keith david w. earl brown sarah silverman khandi alexander marnie alexenburg danny murphy richard tyson rob moran jackie flynn hillary matth ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bich-huyet-lam-thien', 'Bích Huyết Lam Thiên', 'Another Meltdown - The Blacksheep Affair', 'https://phimimg.com/upload/vod/20231115-1/54d2df7c293517fe6727b20382aef6f3.jpg', 'https://phimimg.com/upload/vod/20231115-1/415b317ef015ec671718eb8072da8672.jpg', '<p>Một cảnh sát tên là Yim Dong (Triệu Văn Trác), sau khi phá được một phi vụ cướp hàng không có vũ trang, anh trở thành một anh hùng và được gửi đến Lavernia như là một phụ tá của Đại sứ quán Trung Quốc, nơi mà anh có những người bạn quân nhân mới. Lavernia có nhiều rắc rối hơn so với quốc gia cựu chiến binh thuộc Liên Xô cũ của bạn ở Đông Âu. Có nhiều thuyền viên Trung Quốc đang bị phủ nhận viện trợ và ném mình vào bến cảng. Những người biểu tình muốn sự trở lại của những người cộng sản, trong khi đó một Bộ trưởng Bộ Quốc phòng hão huyền và tham nhũng (cùng những người khác) bán vũ khí cho giáo phái Red Sun với người đứng đầu là Keizo Mishima, gần đây đã bị bắt bởi Yim Dong. Và Dong đã có đủ vấn đề của riêng mình.</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Vincent Zhao Wenzhuo","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Andrew Lin","avatar":""},{"name":"Ken Wong","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Joe Cheung Tung-cho","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"So Wai-Nam","avatar":""},{"name":"Chan Sek","avatar":""},{"name":"Sam Kai-Sen Huang","avatar":""},{"name":"Jude Poyer","avatar":""},{"name":"Mike Lambert","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
