INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-thay-the', 'Sát Thủ Thay Thế', 'The Replacement Killers', 'https://phimimg.com/upload/vod/20231115-1/000dc71b6e046405592b1b2265fab48c.jpg', 'https://phimimg.com/upload/vod/20231115-1/68bfdf55ff22d12292c28d78f17371e7.jpg', '<p>Sát thủ được thuê John Lee được trùm tội phạm khu phố Tàu Terence Wei yêu cầu sát hại cậu con trai nhỏ của cảnh sát Stan Zedkov. Lee đã để cậu bé trong tầm ngắm của mình, nhưng lương tâm của anh ta càng lấn át anh ta, và anh ta đã tha mạng cho đứa trẻ. Sợ rằng Wei sẽ trả thù gia đình mình ở Trung Quốc, Lee tìm đến chuyên gia giả mạo Meg Coburn để lấy hộ chiếu mà anh ta cần để rời khỏi đất nước, nhưng một nhóm sát thủ thay thế đã sớm theo dõi anh ta.</p>', 'Full', 1, 'single', 'completed', 16, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Mira Sorvino","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Jürgen Prochnow","avatar":""},{"name":"Til Schweiger","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"Carlos Gómez","avatar":""},{"name":"Frank Medrano","avatar":""},{"name":"Leo Lee","avatar":""},{"name":"Patrick Kilpatrick","avatar":""},{"name":"Randall Duk Kim","avatar":""},{"name":"Andrew J. Marton","avatar":""},{"name":"Sydney Coberly","avatar":""},{"name":"Yau-Gene Chan","avatar":""},{"name":"Carlos","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
