INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-cao-diem', 'Giờ Cao Điểm', 'Rush Hour', 'https://phimimg.com/upload/vod/20231115-1/880ac8fa406774af3ff7f0e82232b3c8.jpg', 'https://phimimg.com/upload/vod/20231115-1/6bd1992872134d88b93b3f53fde32c24.jpg', '<p>Giờ Cao Điểm là cuộc phiêu lưu của cặp bài trùng: Lee (Thành Long) và James Carter (Christ Turker) trong cuộc chiến chống lại thế lực hắc ám của hội Tam Hoàng. Những màn đấu võ hài hước, những pha mạo hiểm dựng tóc gáy là một phần không thể thiếu tạo nên thương hiệu Thành Long. Bạn sẽ thấy rất rõ điều này qua Giờ Cao Điểm.</p>', 'Full', 1, 'single', 'completed', 17, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Chris Tucker","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Elizabeth Peña","avatar":""},{"name":"Chris Penn","avatar":""},{"name":"Mark Rolston","avatar":""},{"name":"Tzi Ma","avatar":""},{"name":"Rex Linn","avatar":""},{"name":"Ken Leung","avatar":""},{"name":"Robert Littman","avatar":""},{"name":"Michael Chow","avatar":""},{"name":"Julia Hsu","avatar":""},{"name":"Kai Lennox","avatar":""},{"name":"Larry Sullivan","avatar":""},{"name":"Yang Lin","avatar":""},{"name":"Roger Fan","avatar":""},{"name":"George Cheung","avatar":""},{"name":"Lucy Lin","avatar":""},{"name":"Jason Da","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324537);
