INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-cao-bat-dac-di', 'Bị Cáo Bất Đắc Dĩ', 'Wrongfully Accused', 'https://phimimg.com/upload/vod/20231113-1/1e05434aa70f58f2726e43c31442ca19.jpg', 'https://phimimg.com/upload/vod/20231113-1/e25d88752417d6630dc5a33ecbda3ea1.jpg', '<p>Ryan Harrison, thần vĩ cầm, siêu sao và biểu tượng sex không muốn lừa dối người chồng gợi cảm Lauren Goodhue với cô. Ông Goodhue được tìm thấy bị sát hại và Ryan bất ngờ phát hiện ra mình là nghi phạm chính. Sau khi bị kết án tử hình, anh ta đã chạy trốn trong khi bị chuyển đến nơi hành quyết. Giờ đây, cả thế giới đang theo đuổi anh ta khi anh ta vấp phải hết sự cố đáng tiếc này đến sự cố tiếp theo để chứng minh mình vô tội - bằng cách tìm ra một người đàn ông bí ẩn một mắt, một tay, một chân ...</p>', 'Full', 1, 'single', 'completed', 14, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Leslie Nielsen","avatar":""},{"name":"Richard Crenna","avatar":""},{"name":"Kelly LeBrock","avatar":""},{"name":"Melinda McGraw","avatar":""},{"name":"Aaron Pearl","avatar":""},{"name":"Leslie Jones","avatar":""},{"name":"Ben Immanuel","avatar":""},{"name":"Sandra Bernhard","avatar":""},{"name":"Michael York","avatar":""},{"name":"Gerard Plunkett","avatar":""},{"name":"Duncan Fraser","avatar":""},{"name":"John Walsh","avatar":""},{"name":"Maury Hannigan","avatar":""},{"name":"Chick Hearn","avatar":""},{"name":"Lamb Chop","avatar":""},{"name":"Brian Arnold","avatar":""},{"name":"Guy Bews","avatar":""},{"name":"Mary Black","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324537);
