INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('crayon-shinchan-chien-tranh-chop-nhoang-phi-vu-bi-mat-cua-mong-lon', 'Crayon Shin-chan: Chiến Tranh Chớp Nhoáng ! Phi Vụ Bí Mật Của "Móng Lợn"', 'Crayon Shin-chan: Dengeki! Buta no Hizume Daisakusen', 'https://phimimg.com/upload/vod/20231112-1/a28cbb5616a605551ddec533ce313451.jpg', 'https://phimimg.com/upload/vod/20231112-1/148e67b72c28ba0125f4f0c20dfc5389.jpg', '<p>Crayon Shin-chan : Chiến Tranh Chớp Nhoáng ! Phi Vụ Bí Mật Của &quot;Móng Lợn&quot; là câu chuyện kể về Tổ chức “Móng Lợn” với âm mưu sử dụng một món vũ khí bí mật nhằm thống trị nhân loại. Biết được âm mưu đó, tổ chức SML, một tổ chức đứng về phía chính nghĩa đã cử điệp viên Iroke đến cướp đĩa mềm nhằm ngăn chặn kế hoạch của bọn chúng. Lúc này trường mẫu giáo Futaba đang có một bữa tiệc linh đình trên du thuyền đã bị kéo vào cuộc xung đột. Kết quả là nhóm bạn Shinnosuke bị vướng vào công cuộc bỏ trốn của Iroke khỏi trụ sở tổ chức “Móng Lợn”. Cùng với sự chi viện từ phía đồng nghiệp Kinniku và gia đình Nohara. Shinnosuke và mọi người có liệu có chạy thoát thành công và giải cứu nhân loại khỏi âm mưu của tổ chức “Móng Lợn”.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 1998, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Akiko Yajima","avatar":""},{"name":"Miki Narahashi","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Satomi Korogi","avatar":""},{"name":"Tessyo Genda","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Show Hayami","avatar":""},{"name":"Tarō Ishida","avatar":""},{"name":"Minori Matsushima","avatar":""},{"name":"Kaneto Shiozawa","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324537);
