INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-dep-de-chet', 'Quá Đẹp Để Chết', 'Gia', 'https://phimimg.com/upload/vod/20231110-1/5c4471c15b9644b797ace02773e0489b.jpg', 'https://phimimg.com/upload/vod/20231110-1/59237c088dc0ca0903f82ee5f0b5da0d.jpg', '<p>Gia Carangi đến thành phố New York với ước mơ trở thành người mẫu thời trang. Trong vòng vài phút sau khi đến nơi, cô gặp Wilhelmina Cooper, một đặc vụ khôn ngoan và có quyền lực cao, người luôn bảo vệ Gia. Với sự giúp đỡ của Cooper và bản năng bẩm sinh của mình, Gia nhanh chóng vươn lên dẫn đầu thế giới người mẫu. Tuy nhiên, khi Cooper qua đời vì bệnh ung thư phổi, Gia chuyển sang sử dụng ma túy - và cả cô và sự nghiệp của mình bắt đầu vượt khỏi tầm kiểm soát.</p>', 'Full', 1, 'single', 'completed', 16, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Angelina Jolie","avatar":""},{"name":"Elizabeth Mitchell","avatar":""},{"name":"Eric Michael Cole","avatar":""},{"name":"Kylie Travis","avatar":""},{"name":"Louis Giambalvo","avatar":""},{"name":"John Considine","avatar":""},{"name":"Scott Cohen","avatar":""},{"name":"Edmund Genest","avatar":""},{"name":"Mercedes Ruehl","avatar":""},{"name":"Faye Dunaway","avatar":""},{"name":"Holly Baker","avatar":""},{"name":"Joe Basile","avatar":""},{"name":"Rick Batalla","avatar":""},{"name":"Lombardo Boyar","avatar":""},{"name":"Jullian Dulce Vida","avatar":""},{"name":"Brian Donovan","avatar":""},{"name":"Alexa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
