INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-bo-nguoi-tuyet', 'Ông Bố Người Tuyết', 'Jack Frost', 'https://phimimg.com/upload/vod/20231108-1/a29dee51edf025320ecf952beb47ef65.jpg', 'https://phimimg.com/upload/vod/20231108-1/9c48f2f36e1c5d69f155b2818a03624b.jpg', '<p>Ông Bố Người Tuyết - Jack Frost (1998):Phim kể về một gã đàn ông muốn làm tất cả những gì mình thích, muốn làm chồng, làm cha nhưng không quan tâm tới người khác. Ngày kia khi xa cách đứa con trai sau một tai nạn xe hơi, gã mới thấy nếu sống mà không quan tâm đến những người chung quanh thì bạn có thể mất tất cả và tin rằng nếu một ngày kia có thể sống lại như người tuyết thì gã có thể tìm lại những gì đã mất.</p>', 'Full', 1, 'single', 'completed', 17, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Keaton","avatar":""},{"name":"Kelly Preston","avatar":""},{"name":"Mark Addy","avatar":""},{"name":"Joseph Cross","avatar":""},{"name":"Henry Rollins","avatar":""},{"name":"Mika Boorem","avatar":""},{"name":"Andrew Lawrence","avatar":""},{"name":"Eli Marienthal","avatar":""},{"name":"Will Rothhaar","avatar":""},{"name":"Taylor Handley","avatar":""},{"name":"Paul F. Tompkins","avatar":""},{"name":"Dweezil Zappa","avatar":""},{"name":"Jay Johnston","avatar":""},{"name":"Googy Gress","avatar":""},{"name":"Wayne Federman","avatar":""},{"name":"Trevor Rabin","avatar":""},{"name":"Benjamin Brock","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324537);
