INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-sinh-trung-ngoai-hanh-tinh', 'Ký Sinh Trùng Ngoài Hành Tinh', 'The Faculty', 'https://phimimg.com/upload/vod/20231106-1/b2125bc43bcc09c05a02e87de18cca9d.jpg', 'https://phimimg.com/upload/vod/20231106-1/522a75174b760b2cd90ddfea1340a0be.jpg', '<p>Ký Sinh Trùng Ngoài Hành Tinh - The Faculty (1998):Một câu chuyện kinh dị lấy bối cảnh tại một trường trung học nơi các học sinh nghi ngờ đội ngũ giáo viên là người ngoài hành tinh, những người có ý định biến học sinh thành nạn nhân của họ. Herrington High, Ohio, một trường trung học thị trấn nhỏ. Đột nhiên, các giáo viên bắt đầu thay đổi thái độ. Khi Casey và Delilah phải trốn trong tủ quần áo trong phòng khách của giáo viên, họ chứng kiến sự siết cổ của Nurse Harper bởi hai người họ. Bị sốc, họ cố gắng chạy trốn. Chỉ một lúc sau, y tá dường như rất sống, nhưng cũng bằng cách nào đó đã thay đổi, giống như tất cả các giáo viên và hầu hết các học sinh. Chỉ có Casey, Delilah và bốn người khác có vẻ nghi ngờ. Bằng chứng về sự lây nhiễm của người ngoài hành tinh cuối cùng được đưa ra bởi giáo viên hóa học, người cũng chỉ ra một cách để giết chết những người bị nhiễm bệnh. Kế hoạch bây giờ là có được nữ hoàng, trước khi người ngoài hành tinh có thể lan ra khắp cả nước.</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Josh Hartnett","avatar":""},{"name":"Elijah Wood","avatar":""},{"name":"Clea DuVall","avatar":""},{"name":"Jordana Brewster","avatar":""},{"name":"Shawn Hatosy","avatar":""},{"name":"Laura Harris","avatar":""},{"name":"Usher","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Piper Laurie","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Bebe Neuwirth","avatar":""},{"name":"Jon Stewart","avatar":""},{"name":"Daniel von Bargen","avatar":""},{"name":"Summer Phoenix","avatar":""},{"name":"Jon Abraha","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324537);
