INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-sai-quy-du', 'Tay Sai Quỷ Dữ', 'The Minion', 'https://phimimg.com/upload/vod/20231103-1/47bb6730aaf0879d282ffe6b8a9668fb.jpg', 'https://phimimg.com/upload/vod/20231103-1/6658229b68bda7e6977dd5ea6572a8de.jpg', '<p>Tay Sai Quỷ Dữ - The Minion là bộ phim kinh dị xoay quanh thi thể 1500 năm tuổi của một trong những Hiệp sĩ Templar được phát hiện bên dưới tàu điện ngầm của New York. Chẳng bao lâu sau, một tay sai của quỷ và một Hiệp sĩ bị thu hút bởi những bí mật của nó. Vì vậy, giữa họ đã bắt đầu một trận chiến quan trọng và nảy lửa không kém gì số phận của toàn bộ thế giới.</p>', 'Full', 1, 'single', 'completed', 16, 1998, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Françoise Robertson","avatar":""},{"name":"Roc LaFortune","avatar":""},{"name":"David Nerman","avatar":""},{"name":"Allen Altman","avatar":""},{"name":"Jean-Marc Bisson","avatar":""},{"name":"Don Francks","avatar":""},{"name":"Michael Greyeyes","avatar":""},{"name":"Andy Bradshaw","avatar":""},{"name":"Anik Matern","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324537);
