INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ngay-cuoi-cung-1998', 'Những ngày cuối cùng', 'The Last Days', 'https://phimimg.com/upload/vod/20231103-1/599d4002100a1dabab3a0d6c173d3fc8.jpg', 'https://phimimg.com/upload/vod/20231103-1/0ebd30b030d017b3f5cd736f7b1233d3.jpg', '<p>Phim tài liệu đoạt giải Oscar kể câu chuyện đau lòng của năm người Do Thái Hungary, họ đã gánh chịu những kinh hoàng của vụ thảm sát Holocaust và sự cai trị của Hitler.</p>', 'Full', 1, 'single', 'completed', 16, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Basch","avatar":""},{"name":"Martin Basch","avatar":""},{"name":"Randolph Braham","avatar":""},{"name":"Alice Lok Cahana","avatar":""},{"name":"Renee Firestone","avatar":""},{"name":"Irene Zisblatt","avatar":""},{"name":"Tom Lantos","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324537);
