INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thuong-thuyet', 'Kẻ Thương Thuyết', 'The Negotiator', 'https://phimimg.com/upload/vod/20231103-1/0bccf68b9cb8eca73964f54c7c917b3c.jpg', 'https://phimimg.com/upload/vod/20231103-1/4c7e9c724df43c126959bfc5cb516c72.jpg', '<p>Anh là một tay thương thuyết tài ba đã bao lần đối mặt bọn bắt cóc con tin. Thế rồi anh bị gài vào một vụ án mà buộc phải bắt cóc con tin... một tay thương thuyết được phái tới... Hai tay thương thuyết &quot;ma mãnh&quot; ở vào tình thế phải đối đầu với nhau...</p>', 'Full', 1, 'single', 'completed', 20, 1998, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Samuel L. Jackson","avatar":""},{"name":"Kevin Spacey","avatar":""},{"name":"David Morse","avatar":""},{"name":"Ron Rifkin","avatar":""},{"name":"John Spencer","avatar":""},{"name":"J.T. Walsh","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Regina Taylor","avatar":""},{"name":"Bruce Beatty","avatar":""},{"name":"Michael Cudlitz","avatar":""},{"name":"Carlos Gómez","avatar":""},{"name":"Tim Kelleher","avatar":""},{"name":"Dean Norris","avatar":""},{"name":"Nestor Serrano","avatar":""},{"name":"Doug Spinuzza","avatar":""},{"name":"Leonard L. Thoma","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
