INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('banh-bao-nhan-thit-nguoi-2', 'Bánh Bao Nhân Thịt Người 2', 'The Untold Story 2', 'https://phimimg.com/upload/vod/20231103-1/1dcfa6c11d2bc545ae045d5cfce56dd6.jpg', 'https://phimimg.com/upload/vod/20231103-1/e77f1f3809502cc86bf195fac00feac8.jpg', '<p>Máu chảy tự do trong phần tiếp theo của Chuyện chưa kể đầu tiên, giờ tìm thấy Anthony Wong Chau-Sang trong một vai trò khác; trong một bộ phim cũng bạo lực và đáng sợ như bản gốc. Một cặp vợ chồng không hạnh phúc mời cô em họ xinh đẹp của vợ, người đã sống sót sau một trải nghiệm kinh hoàng ở Trung Quốc đại lục, đến sống cùng họ. Cô ấy có cách đặc biệt của riêng mình để vượt qua khó khăn và trở thành bậc thầy của món nướng</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Anthony Wong","avatar":""},{"name":"Melvin Wong Gam-Sam","avatar":""},{"name":"Jamie Luk Kim-Ming","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Emotion Cheung Kam-Ching","avatar":""},{"name":"Paulyn Sun","avatar":""},{"name":"Yeung Fan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
