INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('banh-bao-nhan-thit-nguoi-2', 'Bánh Bao Nhân Thịt Người 2', 'The Untold Story 2', 'bánh bao nhân thịt người 2 the untold story 2 anthony wong melvin wong gam-sam jamie luk kim-ming helena law lan emotion cheung kam-ching paulyn sun yeung fan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-godzilla-1998', 'Quái Vật Godzilla', 'Godzilla', 'https://phimimg.com/upload/vod/20231101-1/29a89b5b75e66a50703fa3a9c7727463.jpg', 'https://phimimg.com/upload/vod/20231101-1/134df481d3b4636e2f1d6d8514540888.jpg', '<p>Sau vụ thử nghiệm bom nguyên tử của Pháp ở Nam Thái Bình Dương, một sinh vật chưa biết đến trước đây xuất hiện quay về phía đông qua kênh đào Panama. Nhà khoa học Niko Tatopolous được gọi đến để điều tra sự việc. Anh nhanh chóng đi đến kết luận rằng một quái vật không lồ hình dáng như thằn lằn đã được tạo ra bởi phóng xạ của vụ nổ. Godzilla sau đó đi về phía bắc, dừng lại tại Manhattan để bắt đầu tàn phá các thành phố lớn. Các lực lượng của quân đội Mỹ đã kết hợp để chống lại quái vật, họ có thể cứu người dân New York không ?</p>', 'Full', 1, 'single', 'completed', 19, 1998, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Matthew Broderick","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Maria Pitillo","avatar":""},{"name":"Hank Azaria","avatar":""},{"name":"Kevin Dunn","avatar":""},{"name":"Michael Lerner","avatar":""},{"name":"Harry Shearer","avatar":""},{"name":"Arabella Field","avatar":""},{"name":"Vicki Lewis","avatar":""},{"name":"Doug Savant","avatar":""},{"name":"Malcolm Danare","avatar":""},{"name":"Lorry Goldman","avatar":""},{"name":"Christian Aubert","avatar":""},{"name":"Philippe Bergeron","avatar":""},{"name":"Frank Bruynbroek","avatar":""},{"name":"François Giroday","avatar":""},{"name":"Nicholas","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
