INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('6-ngay-7-dem', '6 Ngày 7 Đêm', 'Six Days Seven Nights', 'https://phimimg.com/upload/vod/20231030-1/b2cef9b59db4506ce1d211278698450e.jpg', 'https://phimimg.com/upload/vod/20231030-1/10a362a2cc7ba02860c6798e80ea9698.jpg', '<p>Tại hòn đảo Makatea ở Nam Thái Bình Dương, biên tập viên tạp chí định hướng nghề nghiệp Robin Monroe đang có kỳ nghỉ kéo dài một tuần với bạn trai của cô, Frank Martin. Một nhiệm vụ khẩn cấp ở vùng lân cận Tahiti yêu cầu Robin phải thuê phi công gắt gỏng Quinn Harris, người đã đưa họ đến hòn đảo trên một chiếc thủy phi cơ. Khi đang bay, một cơn bão mạnh buộc Quinn phải hạ cánh khẩn cấp xuống một hòn đảo hoang gần đó. Cặp đôi khác biệt này lúc đầu tránh mặt nhau cho đến khi họ buộc phải hợp tác để trốn thoát khỏi hòn đảo – và một số tên cướp biển muốn lấy đầu của họ.</p>', 'Full', 1, 'single', 'completed', 17, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anne Heche","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"David Schwimmer","avatar":""},{"name":"Jacqueline Obradors","avatar":""},{"name":"Temuera Morrison","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Kerry Rossall","avatar":""},{"name":"Douglas Weston","avatar":""},{"name":"Ben Bode","avatar":""},{"name":"Derek Basco","avatar":""},{"name":"Amy Sedaris","avatar":""},{"name":"Priscilla Inga Taylor","avatar":""},{"name":"Long Nguyen","avatar":""},{"name":"John Koyama","avatar":""},{"name":"Jen Sung","avatar":""},{"name":"Jak","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324537);
