INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-gap-tu-than', 'Hẹn Gặp Tử Thần', 'Meet Joe Black', 'https://phimimg.com/upload/vod/20231022-1/ca662572c8657ee31248dbb39a06cd50.jpg', 'https://phimimg.com/upload/vod/20231022-1/1a4c2388dc6ee02a49c394dbe0f8110c.jpg', '<p>Một câu chuyện tình như một tiếng sét ái tình chưa bắt đầu đã vội kết thúc. Họ gặp nhau cảm mến nhau trong phút chốc rồi chia tay nhau trong lưu luyến và rồi vừa gặp trước mắt đó thì đằng sau chàng trai đã bị tay nạn và ra đi mãi mãi đúng là một định mệnh trớ trêu. Và thần chết đã mượn thân thể của chàng trai và đến tham gia đình chủ tịch một công ty lớn, đó cũng là nhà của cô gái, thần chết đem lòng yêu mến người con gái đó nhưng cô gái không hay biết đó chỉ là thân xác của chàng trai chứ thật chất thì không phải chàng trai đó…</p>', 'Full', 1, 'single', 'completed', 17, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Claire Forlani","avatar":""},{"name":"Jake Weber","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"Jeffrey Tambor","avatar":""},{"name":"June Squibb","avatar":""},{"name":"Gene Canfield","avatar":""},{"name":"Suzanne Hevner","avatar":""},{"name":"Stephen Adly Guirgis","avatar":""},{"name":"David S. Howard","avatar":""},{"name":"Lois Kelly-Miller","avatar":""},{"name":"Jahnni St. John","avatar":""},{"name":"Richard Clarke","avatar":""},{"name":"Madeline Balmaceda","avatar":""},{"name":"Marylouis","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324537);
