INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hen-gap-tu-than', 'Hẹn Gặp Tử Thần', 'Meet Joe Black', 'hẹn gặp tử thần meet joe black brad pitt anthony hopkins claire forlani jake weber marcia gay harden jeffrey tambor june squibb gene canfield suzanne hevner stephen adly guirgis david s. howard lois kelly-miller jahnni st. john richard clarke madeline balmaceda marylouis ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-con-trung', 'Thế Giới Côn Trùng', 'A Bug''s Life', 'https://phimimg.com/upload/vod/20231020-1/485feacc8d61d3b403226a4f900b67a8.jpg', 'https://phimimg.com/upload/vod/20231020-1/56fc98fa4dcd9775631fc16c52d9ed58.jpg', '<p>Một xóm kiến nọ bị những con châu chấu to xác, đứng đầu là Hopper (Kevin Spacey lồng tiếng) đô hộ. Đàn kiến tội nghiệp phải cống nạp thức ăn cho quân xâm lược hàng năm và coi đây là một nghi lễ bắt buộc phải thực thi nếu muốn sống yên ổn. Một ngày mùa xuân, khi đồ cúng lễ đã được chuẩn bị sẵn sàng, một anh chàng kiến ưa phát minh ra những đồ quái dị tên là Flik (Dave Foley) đã vô tình làm đổ toàn bộ số hạt và rau quả xuống sông. Đàn châu chấu hung hăng xuất hiện và hết sức tức giận khi không thấy thức ăn được dâng lên như mọi khi. Bọn chúng định tấn công đàn kiến nhưng khi rõ sự tình, chúng cho họ một cơ hội chuộc lỗi, gia hạn đến mùa thu phải gom nhặt đủ số đồ lễ. Nhưng Flik lại nghĩ khác, anh ta muốn đàn ...</p>', 'Full', 1, 'hoathinh', 'completed', 18, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dave Foley","avatar":""},{"name":"Kevin Spacey","avatar":""},{"name":"Julia Louis-Dreyfus","avatar":""},{"name":"Hayden Panettiere","avatar":""},{"name":"Phyllis Diller","avatar":""},{"name":"Richard Kind","avatar":""},{"name":"David Hyde Pierce","avatar":""},{"name":"Joe Ranft","avatar":""},{"name":"Denis Leary","avatar":""},{"name":"Jonathan Harris","avatar":""},{"name":"Madeline Kahn","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Michael McShane","avatar":""},{"name":"John Ratzenberger","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Roddy McDowall","avatar":""},{"name":"Edie","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324537);
