INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('run-so-o-las-vegas', 'Run Sợ ở Las Vegas', 'Fear and Loathing in Las Vegas', 'https://phimimg.com/upload/vod/20231016-1/5f4e8e7e97cb36e6e5b424cfdecbd032.jpg', 'https://phimimg.com/upload/vod/20231016-1/ca7aa3e917de3de3f92dbfc781c8c580.jpg', '<p>Raoul là một nhà báo đã cùng với luật sư của mình đến Las Vegas để đưa tin về cuộc đua xe mô tô 400 bạc hà. Chẳng bao lâu nữa, niềm vui sẽ vượt qua công việc và họ say mê nhiều loại thuốc kích thích.</p>', 'Full', 1, 'single', 'completed', 22, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Benicio del Toro","avatar":""},{"name":"Tobey Maguire","avatar":""},{"name":"Christina Ricci","avatar":""},{"name":"Ellen Barkin","avatar":""},{"name":"Gary Busey","avatar":""},{"name":"Cameron Diaz","avatar":""},{"name":"Mark Harmon","avatar":""},{"name":"Katherine Helmond","avatar":""},{"name":"Michael Jeter","avatar":""},{"name":"Penn Jillette","avatar":""},{"name":"Craig Bierko","avatar":""},{"name":"Lyle Lovett","avatar":""},{"name":"Laraine Newman","avatar":""},{"name":"Harry Dean Stanton","avatar":""},{"name":"Tim Thomerson","avatar":""},{"name":"Flea","avatar":""},{"name":"Christ","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324537);
