INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-so-pi-tim-kiem-niem-tin-trong-su-hon-loan', 'Hằng Số Pi: Tìm Kiếm Niềm Tin Trong Sự Hỗn Loạn', 'Pi', 'https://phimimg.com/upload/vod/20231016-1/65d61fe3819e2932ee009df58838f87f.jpg', 'https://phimimg.com/upload/vod/20231016-1/90e98a0bb6c29bc376fa68d1a4677dff.jpg', '<p>Bộ phim kể về một thiên tài toán học Maximilian Cohen (Sean Gullette) phát minh ra một siêu máy tính có khả năng giải mã số Pi, từ đó tìm được ra tất cả những quy luật trong cuộc sống. Thuật toán do ông phát minh ra có thể là chìa khóa dẫn đến các bí mật vũ trụ, công cụ tối ưu để dự đoán thị trường chứng khoán hay thậm chí, vị thần tiếp theo sau Allah, Jesus và Đức Phật. Khi đánh hơi thấy bí mật này, giáo phái Hasidic và những tên trùm tài chính ở phố Wall đã tìm đến chiêu dụ Max. Vậy rốt cục thuật toán ấy kì diệu đến mức nào? Người ta sẵn sàng làm gì để có thể có được nó? Liệu công cụ ấy có rơi vào tay kẻ xấu, hay nó sẽ được thực hiện đúng như những gì chủ của nó mong đợi là tìm hiểu về ý nghĩa cuộc sống?</p>', 'Full', 1, 'single', 'completed', 16, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Gullette","avatar":""},{"name":"Mark Margolis","avatar":""},{"name":"Ben Shenkman","avatar":""},{"name":"Pamela Hart","avatar":""},{"name":"Stephen Pearlman","avatar":""},{"name":"Samia Shoaib","avatar":""},{"name":"Ajay Naidu","avatar":""},{"name":"Kristyn Mae-Anne Lao","avatar":""},{"name":"Espher Lao Nieves","avatar":""},{"name":"Joanne Gordon","avatar":""},{"name":"Lauren Fox","avatar":""},{"name":"Stanley B. Herman","avatar":""},{"name":"Clint Mansell","avatar":""},{"name":"Tom Tumminello","avatar":""},{"name":"Henri Falconi","avatar":""},{"name":"Isaac Fried","avatar":""},{"name":"Ari Hand","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
