INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-nguoi-anh', 'Băng Đảng Người Anh', 'Lock, Stock and Two Smoking Barrels', 'https://phimimg.com/upload/vod/20231016-1/e0f1c60b0919464638b716090a007477.jpg', 'https://phimimg.com/upload/vod/20231016-1/87000090623b84a4aeecd0d4904442f4.jpg', '<p>ardsharp Eddy, Pals Bacon, Tom và Soap ẩu đả để gom đủ tiền cho Eddy được đấu sòng bài với ông trùm chủ đất Hatchet Harry.Thật không may, kế hoạch bị phá sản, Eddy nợ Harry 0,000 phải trả trong vòng một tuần. Thực ra, Harry muốn chiếm tiệm bar của địch thủ là J.D. (Sting), cũng là bố của Eddy. Để có tiền, Eddy lập kế hoạch ăn trộm cửa tiệm bán cần sa của Winston (Steven Mackintosh), nhưng cuộc đọ súng không tránh khỏi khiến cho kế hoạch của Eddy không dễ dàng được thực hiện.Bộ phim được công chiếu lần đầu tại liên hoan phim Edinburgh năm 1998. Đây cũng là bộ phim đầu tay của đạo diễn kiêm nhà văn Guy Ritchie. Năm 2000, Ritchie đã giành giải thưởng Edgar Award và “Lock, Stock and ...</p>', 'Full', 1, 'single', 'completed', 20, 1998, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Jason Flemyng","avatar":""},{"name":"Dexter Fletcher","avatar":""},{"name":"Nick Moran","avatar":""},{"name":"Jason Statham","avatar":""},{"name":"Steven Mackintosh","avatar":""},{"name":"Nicholas Rowe","avatar":""},{"name":"Nick Marcq","avatar":""},{"name":"Charles Forbes","avatar":""},{"name":"Vinnie Jones","avatar":""},{"name":"Lenny McLean","avatar":""},{"name":"Peter McNicholl","avatar":""},{"name":"P.H. Moriarty","avatar":""},{"name":"Frank Harper","avatar":""},{"name":"Steve Sweeney","avatar":""},{"name":"Huggy Leaver","avatar":""},{"name":"Ronnie Fox","avatar":""},{"name":"Tony McMahon","avatar":""},{"name":"Steph","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324537);
