INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-si-tiec-cuoi', 'Ca Sĩ Tiệc Cưới', 'The Wedding Singer', 'https://phimimg.com/upload/vod/20231016-1/eeee1e8b361d160723499cbf1e395f37.jpg', 'https://phimimg.com/upload/vod/20231016-1/b34d7dd7fccb73bc4eaedab21cc452ad.jpg', '<p>Robbie là một ngôi sao ca nhạc địa phương đã trở thành ca sĩ đám cưới, đã bị hủy hôn vào ngày đám cưới của mình. Trong khi đó cô hầu bàn Julia cuối cùng cũng định ngày cưới với vị hôn phu Glenn. Khi Julia và Robbie gặp nhau, họ thấy rằng mọi thứ phức tạp hơn họ nghĩ...</p>', 'Full', 1, 'single', 'completed', 17, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"Christine Taylor","avatar":""},{"name":"Allen Covert","avatar":""},{"name":"Matthew Glave","avatar":""},{"name":"Ellen Albertini Dow","avatar":""},{"name":"Angela Featherstone","avatar":""},{"name":"Alexis Arquette","avatar":""},{"name":"Christina Pickles","avatar":""},{"name":"Jodi Thelen","avatar":""},{"name":"Frank Sivero","avatar":""},{"name":"Patrick McTavish","avatar":""},{"name":"Gemini Barnett","avatar":""},{"name":"Billy Idol","avatar":""},{"name":"Kevin Nealon","avatar":""},{"name":"Carmen Filpi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324537);
