INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-than-ky-cua-belle', 'Thế Giới Thần Kỳ của Belle', 'Belle''s Magical World', 'https://phimimg.com/upload/vod/20231016-1/43d09f218561d15d9b515e3b8cc379fc.jpg', 'https://phimimg.com/upload/vod/20231016-1/2ca02528fe246c46f587ad4a740817d3.jpg', '<p>Belle, Quái vật, Lumiere, Cogsworth và những cư dân còn lại trong lâu đài sử dụng trí tưởng tượng của mình để dấn thân vào ba cuộc phiêu lưu kỳ diệu trong truyện. Tuyển tập video trực tiếp này đóng vai trò như một</p>', 'Full', 1, 'hoathinh', 'completed', 24, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robby Benson","avatar":""},{"name":"Paige O''Hara","avatar":""},{"name":"David Ogden Stiers","avatar":""},{"name":"Jerry Orbach","avatar":""},{"name":"Anne Rogers","avatar":""},{"name":"Gregory Grudt","avatar":""},{"name":"Kimmy Robertson","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"April Winchell","avatar":""},{"name":"Jo Anne Worley","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324537);
