INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-tron-oan-nghiet', 'Vòng Tròn Oan Nghiệt', 'Ring', 'https://phimimg.com/upload/vod/20231016-1/48064a38c606bcbcaaffe8b387328d38.jpg', 'https://phimimg.com/upload/vod/20231016-1/c4228138d8c9a2fc1b5333f62404f000.jpg', '<p>Phim kể về một cuốn băng video vô tình được thu tại vùng Izu, Japan. Bất kể người nào xem cuộn băng sẽ chết trong vòng một tuần kể từ ngày xem cuốn băng đó. Nạn nhân đầu tiên của cuốn băng là 4 cô cậu học trò trong đó có Tomoko, cháu gái của Asakawa. Trong lúc điều tra về cái chết của Tomoko, cô vô tình bị dính vào lời nguyền của cuốn băng, kéo theo mạng sống của con trai và ngừoi chồng cũ. Quyết tâm không để con trai của mình chết đã khiến hai người ngày đêm dốc sức tìm ra thủ phạm của cuốn băng video kì bí trong lúc mạng sống của cả ba, Asakawa, Ryuji - người chồng - (trong tiểu thuyết thì chỉ là bạn trai của Asakawa), và Yoichi - con trai của Asakawa.</p>', 'Full', 1, 'single', 'completed', 20, 1998, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Nanako Matsushima","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Rikiya Ôtaka","avatar":""},{"name":"Miki Nakatani","avatar":""},{"name":"Yûko Takeuchi","avatar":""},{"name":"Hitomi Sato","avatar":""},{"name":"Yutaka Matsushige","avatar":""},{"name":"Yōichi Numata","avatar":""},{"name":"Katsumi Muramatsu","avatar":""},{"name":"Masako","avatar":""},{"name":"Rie Ino''o","avatar":""},{"name":"Daisuke Ban","avatar":""},{"name":"Kiyoshi Risho","avatar":""},{"name":"Masahiko Ono","avatar":""},{"name":"Yôko Ôshima","avatar":""},{"name":"Kiriko Shimizu","avatar":""},{"name":"Orie Izuno","avatar":""},{"name":"Hi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
