INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-ve-1900', 'Huyền Thoại Về 1900', 'La leggenda del pianista sull''oceano', 'https://phimimg.com/upload/vod/20231016-1/075535f8e234d6ac75de861600ac1106.jpg', 'https://phimimg.com/upload/vod/20231016-1/178c33192b75925071b6e7442522aa12.jpg', '<p>The Legend of 1900 (Huyền Thoại Về 1900), còn có tên tiếng Ý là La leggenda del pianista sull&#39;oceano - huyền thoại về một nghệ sĩ dương cầm trên đại dương, là một bộ phim nói tiếng Anh đầu tiên của đạo diễn người Ý nổi tiếng Giuseppe Tornatore (đạo diễn của Cinema Paradiso, Malena...), lấy cảm hứng từ vở kịch về chàng nghệ sĩ dương cầm lập dị Novecento của Alessandro Baricco. Bộ phim đã giành được nhiều giải thưởng lớn ở Châu Âu và trên thế giới trong đó có giải Quả cầu Vàng cho Phim nước ngoài hay nhất, đặc biệt nữa là giải nhạc nền của nhà soạn nhạc lừng danh Ennio Morricone. Từ bộ phim này, nhiều chi tiết đã được học tập để các nhà làm phim Holywood cho ra đời phim The Pianist (2002). Cả bộ phim là một bản giao hưởng bay bổng và thoát tục về con người nghệ sĩ đích thực.</p>', 'Full', 1, 'single', 'completed', 24, 1998, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Tim Roth","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Mélanie Thierry","avatar":""},{"name":"Bill Nunn","avatar":""},{"name":"Gabriele Lavia","avatar":""},{"name":"Clarence Williams III","avatar":""},{"name":"Peter Vaughan","avatar":""},{"name":"Niall O''Brien","avatar":""},{"name":"Alberto Vazquez","avatar":""},{"name":"Luca De Luigi","avatar":""},{"name":"Femi Elufowoju Jr.","avatar":""},{"name":"Nigel Fan","avatar":""},{"name":"Roger Monk","avatar":""},{"name":"Leonid Zaslavski","avatar":""},{"name":"Bernard Padden","avatar":""},{"name":"Piero Gimondo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324537);
