INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-ba-vuong', 'Sát Thủ Bá Vương', 'Contract Killer', 'https://phimimg.com/upload/vod/20231016-1/a681c98c120192b83eb693ecd4278fb4.jpg', 'https://phimimg.com/upload/vod/20231016-1/efb8f31e31ac25f216053e6cd1237eba.jpg', '<p>Trong phim Sát Thủ Bá Vương (Hitman) Một cảnh sát đã không thể dùng luật pháp để trừng trị bọn tội phạm nên anh đã biến mình thành 1 sát thủ để tiêu diệt bọn tội phạm. 1 tổ chức xã hội đên đã treo giải thưởng giết 1 thủ lĩnh của yakuza ở nhật bản , giá trị lên đến 100 triệu USD, Sau khi giải thưởng dc phát lên thì làm chấn động thế giới xã hội đen và cảnh sát...</p>', 'Full', 1, 'single', 'completed', 15, 1998, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Gigi Leung","avatar":""},{"name":"Timmy Ho","avatar":""},{"name":"Kim Yip Kwong-Kim","avatar":""},{"name":"Frankie Ng","avatar":""},{"name":"John Ching Tung","avatar":""},{"name":"Keiji Sato","avatar":""},{"name":"Paul Rapovski","avatar":""},{"name":"Hideri Meiken","avatar":""},{"name":"Kenji Sahara","avatar":""},{"name":"Lui Tat","avatar":""},{"name":"Jude Poyer","avatar":""},{"name":"Law Shu-Kei","avatar":""},{"name":"Paul Rapovski","avatar":""},{"name":"Ta Lei","avatar":""},{"name":"Leung Shing-Hung","avatar":""},{"name":"Sam Kai-Sen Huang","avatar":""},{"name":"Dion","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
