INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-xe-taxi', 'Quái Xế Taxi', 'Taxi', 'https://phimimg.com/upload/vod/20231016-1/94f4a11a22ec47d7eb97ab712baba4d6.jpg', 'https://phimimg.com/upload/vod/20231016-1/0f973ef684674ad359c23f753a38ec26.jpg', '<p>Tại Marseilles (Pháp),cậu bé giao pizza Daniel thay đổi công việc để trở thành một lái xe taxi, nhưng ước mơ của mình là trở thành một tay đua F1. Bị bắt bởi cảnh sát vì chạy quá tốc độ,Daniel đã giúp đỡ Emilien, một thanh tra truy tìm dấu vết của một người Đức đắp bờ những kẻ cướp, vì thế nên không mất giấy phép lái xe là viêc làm</p>', 'Full', 1, 'single', 'completed', 19, 1998, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Samy Naceri","avatar":""},{"name":"Frédéric Diefenthal","avatar":""},{"name":"Marion Cotillard","avatar":""},{"name":"Manuela Gourary","avatar":""},{"name":"Emma Wiklund","avatar":""},{"name":"Bernard Farcy","avatar":""},{"name":"Georges Neri","avatar":""},{"name":"Guy Quang","avatar":""},{"name":"Maurice Murcia","avatar":""},{"name":"Sabine Bail","avatar":""},{"name":"Dan Herzberg","avatar":""},{"name":"Sébastien Thiery","avatar":""},{"name":"Eric Bérenger","avatar":""},{"name":"Philippe du Janerand","avatar":""},{"name":"Christophe Fesquet","avatar":""},{"name":"Gérard Vantagg","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324537);
