INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-kinh-hai-2', 'Mùa Hè Kinh Hãi 2', 'I Still Know What You Did Last Summer', 'https://phimimg.com/upload/vod/20231016-1/cf6eac3366134ef13a08a540c050bddb.jpg', 'https://phimimg.com/upload/vod/20231016-1/474742a00a6e9b293a6883ac0a122bf2.jpg', '<p>Kỳ nghỉ hè ở Bahamas trở nên chết chóc đối với Julie James khi một tên sát nhân khủng bố cô và bạn bè. Hắn không cho cô chôn vùi những ký ức về quá khứ.</p>', 'Full', 1, 'single', 'completed', 19, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Love Hewitt","avatar":""},{"name":"Freddie Prinze Jr.","avatar":""},{"name":"Brandy Norwood","avatar":""},{"name":"Mekhi Phifer","avatar":""},{"name":"Matthew Settle","avatar":""},{"name":"Muse Watson","avatar":""},{"name":"Jennifer Esposito","avatar":""},{"name":"Bill Cobbs","avatar":""},{"name":"Jeffrey Combs","avatar":""},{"name":"John Hawkes","avatar":""},{"name":"Ellerine Harding","avatar":""},{"name":"Benjamin Brown","avatar":""},{"name":"Red West","avatar":""},{"name":"Michael P. Byrne","avatar":""},{"name":"Michael Bryan French","avatar":""},{"name":"Dee Anne He","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324537);
