INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-huy-diet', 'Thảm Họa Hủy Diệt', 'Deep Impact', 'https://phimimg.com/upload/vod/20231015-1/a9cee6097779b85c5fd848a74119403a.jpg', 'https://phimimg.com/upload/vod/20231015-1/5b4654f133db28da7ff29382ff607adc.jpg', '<p>Gerry Griffin, từng là chuyên gia điều hành chuyến bay của con tàu Appolo 12 và giám đốc Trung tâm vũ trụ Johnson (Houston), đã thủ vai một quan chức NASA trong phim. Joshua Colwell, người đóng một quan chức NASA, cũng chính là cố vấn kỹ thuật cho bộ phim. Một vụ tai tiếng tình ái khiến Bộ trưởng Tài chính Mỹ mất chức. Jenny Lerner, phóng viên của hãng thông tấn MSNBC tại Washington (Mỹ), được giao nhiệm vụ điều tra một vụ việc. Trong quá trình điều tra, cô tình cờ tìm thấy một tài liệu tuyệt mật từ văn phòng tổng thống có tên gọi &#39;Ellie&#39;. Cho rằng tổng thống Tom Beck có quan hệ tình cảm một cô nàng nào đó có tên là Ellie, nữ phóng viên này quyết tâm điều tra. Nhưng rồi cô phát hiện ra rằng những chữ đó ...</p>', 'Full', 1, 'single', 'completed', 21, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Duvall","avatar":""},{"name":"Téa Leoni","avatar":""},{"name":"Elijah Wood","avatar":""},{"name":"Vanessa Redgrave","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Maximilian Schell","avatar":""},{"name":"Leelee Sobieski","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Laura Innes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324537);
