INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoang-toi-lich-su-my', 'Khoảng Tối Lịch Sử Mỹ', 'American History X', 'https://phimimg.com/upload/vod/20231015-1/884849aca9918fb466b6c095e7874040.jpg', 'https://phimimg.com/upload/vod/20231015-1/f277f13199affb83d4eff3de86d7c880.jpg', '<p>Derek Vineyard được tạm tha sau khi ngồi tù 3 năm vì giết hai người đàn ông Mỹ gốc Phi. Qua lời kể của anh trai Danny Vineyard, chúng ta biết rằng trước khi vào tù, Derek là một tên đầu trọc và là thủ lĩnh của một băng nhóm bạo lực theo chủ nghĩa thượng tôn da trắng đã thực hiện các hành vi tội phạm chủng tộc trên khắp L.A. và hành động của hắn đã ảnh hưởng rất nhiều đến Danny. Được cải tạo và mới ra tù, Derek cắt đứt liên lạc với băng đảng và quyết tâm ngăn Danny đi vào con đường bạo lực như anh.</p>', 'Full', 1, 'single', 'completed', 17, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Edward Norton","avatar":""},{"name":"Edward Furlong","avatar":""},{"name":"Beverly D''Angelo","avatar":""},{"name":"Jennifer Lien","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"Fairuza Balk","avatar":""},{"name":"Avery Brooks","avatar":""},{"name":"Elliott Gould","avatar":""},{"name":"Stacy Keach","avatar":""},{"name":"William Russ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
