INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-na-zorro', 'Mặt Nạ Zorro', 'The Mask of Zorro', 'https://phimimg.com/upload/vod/20231015-1/df9c4797f44f884b47755f3ff3e8df46.jpg', 'https://phimimg.com/upload/vod/20231015-1/88dfccbae8f572abedd38505ddde8f41.jpg', '<p>Người hùng Zorro giờ đây đã già, sau một lần trừ gian diệt bạo, người hùng vô tình để lộ thân thế và kết quả phải trả khá đắt: vợ bị giết, con gái bị bắt cóc, nhà cửa cháy trụi. Biết mình không thể trả thù với tuổi tác cao và sức lực như thế, Zorro phải tìm một đệ tử mới và người đó không ai khác chính là thằng nhóc trộm cắp ông cứu năm xưa...</p>', 'Full', 1, 'single', 'completed', 16, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Antonio Banderas","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Catherine Zeta-Jones","avatar":""},{"name":"Stuart Wilson","avatar":""},{"name":"Matt Letscher","avatar":""},{"name":"L.Q. Jones","avatar":""},{"name":"Diego Sieres","avatar":""},{"name":"José María de Tavira","avatar":""},{"name":"Tony Amendola","avatar":""},{"name":"Emiliano Guerra","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324537);
