INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-quy', 'Săn Quỷ', 'Blade', 'https://phimimg.com/upload/vod/20231015-1/dc446b3b550879d03d521f22df06e5be.jpg', 'https://phimimg.com/upload/vod/20231015-1/4ca2b62c71576253808d8f6fdf0a964f.jpg', '<p>Mang trong mình dòng máu ma cà rồng nhưng Blade lại căm thù những kẻ đồng loại muốn cai trị con người. Khi nữ bác sỹ Karen bị ma cà rồng tấn công, Blade giải cứu và tìm mọi cách cứu chữa cho cô. Trong khi đó, chúa đảng ma cà rồng Deacon Frost toan tính cuộc tấn công vào nhân loại.</p>', 'Full', 1, 'single', 'completed', 16, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wesley Snipes","avatar":""},{"name":"Stephen Dorff","avatar":""},{"name":"Kris Kristofferson","avatar":""},{"name":"N''Bushe Wright","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"Udo Kier","avatar":""},{"name":"Arly Jover","avatar":""},{"name":"Traci Lords","avatar":""},{"name":"Kevin Patrick Walls","avatar":""},{"name":"Tim Guinee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324537);
