INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-moc-lan', 'Hoa Mộc Lan', 'Mulan', 'https://phimimg.com/upload/vod/20231014-1/1008153225de7293df38e5c82ebaf7c2.jpg', 'https://phimimg.com/upload/vod/20231014-1/2028ae10ac4468a76f542873c17b0b49.jpg', '<p>Nội dung bộ phim hoạt hình dựa theo một câu chuyện dân gian nổi tiếng của Trung Quốc kể về cô gái giả trai ra trận thường được biết đến dưới cái tên Hoa Mộc Lan. Tuyệt phẩm này của Walt Disney được đề cử một giải Oscar cho “Nhạc phim hay nhất” năm 1999. Mulan (Ming-Na Wen lồng tiếng) là người con duy nhất trong gia đình danh giá. Mặc dù luôn cố gắng làm vừa lòng mẹ cha nhưng dường như cô luôn khiến họ phải thất vọng. Khi quân giặc tới xâm chiếm bờ cõi Trung Hoa, thanh niên trai tráng đều hăng hái ghi tên đi lính. Fa Zhou (Soon-Tek Oh) người cha già của Mulan vốn bị thương và không thể đi vững nhưng vẫn muốn ra trận chiến đấu vì đất nước và vì danh dự của dòng họ. Quá thương cha già phải đi tòng quân, Mulan liền lấy áo giáp và ngựa cải trang thành một người đàn ông, đứng trước bàn thờ tổ tiên khấn vái mong được phù hộ rồi thay cha ra trận. Mushu (Eddie Murphy) một con rồng nhỏ đã được phái đi để bảo vệ Mulan trong khi chiến đấu.</p>', 'Full', 1, 'hoathinh', 'completed', 21, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ming-Na Wen","avatar":""},{"name":"Eddie Murphy","avatar":""},{"name":"BD Wong","avatar":""},{"name":"Miguel Ferrer","avatar":""},{"name":"Harvey Fierstein","avatar":""},{"name":"Freda Foh Shen","avatar":""},{"name":"June Foray","avatar":""},{"name":"James Hong","avatar":""},{"name":"Miriam Margolyes","avatar":""},{"name":"Pat Morita","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324537);
