INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-binh-nhi-ryan', 'Giải Cứu Binh Nhì Ryan', 'Saving Private Ryan', 'https://phimimg.com/upload/vod/20231014-1/874adf6e586960b9bde6af4989e19681.jpg', 'https://phimimg.com/upload/vod/20231014-1/d80dbd8e53e1e5c495e4ba35feba14cb.jpg', '<p>Bắt đầu với cuộc xâm lược của quân Đồng minh Normandy vào ngày 6 tháng 6 năm 1944, các thành viên của tiểu đoàn tấn công thứ hai, dưới quyền Đại úy Miller, chiến đấu để giành quyền kiểm soát bãi biển. Trong trận chiến, hai anh em bị giết. Một chút trước đó, ở New Guinea, một người anh em thứ ba cũng bị giết. Mẹ của ông, bà Ryan, sẽ nhận được ba bức điện tử trong cùng một ngày. Người đứng đầu quân đội Mỹ, George C. Marshall, nhìn thấy cơ hội làm giảm bớt nỗi đau khổ của cô khi anh biết được một người anh em thứ tư, Private James Ryan, và quyết định cử tám người (Thuyền trưởng Miller và một nhóm được chọn từ tiểu đoàn của anh ta) đi tìm Anh ta và đưa anh ta trở về nhà của mẹ mình.</p>', 'Full', 1, 'single', 'completed', 19, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"Edward Burns","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Barry Pepper","avatar":""},{"name":"Adam Goldberg","avatar":""},{"name":"Vin Diesel","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"Ted Danson","avatar":""},{"name":"Jeremy Davies","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324537);
