INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-su-tu-2-niem-kieu-hanh-cua-simba', 'Vua Sư Tử 2: Niềm Kiêu Hãnh Của Simba', 'The Lion King II: Simba''s Pride', 'https://phimimg.com/upload/vod/20231014-1/11871956fd5fb87b4266b70154d0e0ee.jpg', 'https://phimimg.com/upload/vod/20231014-1/770ba6c391f3a8956ef8264e43145c9a.jpg', '<p>Ở đoạn cuối của phần 1, Simba đánh bại ông chú Scar độc ác, đồng thời giành lại ngai vàng ở vùng đất Pride Land. Sau khi lên ngôi vua, Simba và hoàng hậu Nala có một cô con gái tên Kiara. Khi trưởng thành, Kiara kết bạn với Kovu, hậu duệ của một nhóm sư tử từng bị Simba trục xuất khỏi vương quốc vì tội trung thành với Scar. Sau một lần suýt bị nuốt chửng bởi đàn cá sấu, chúng trở nên vô cùng thân thiết. Zira, mẹ của Kovu, từ lâu đã ấp ủ ý định báo thù cho Scar nên huấn luyện để Kovu trở thành một sát thủ...</p>', 'Full', 1, 'hoathinh', 'completed', 21, 1998, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Broderick","avatar":""},{"name":"Neve Campbell","avatar":""},{"name":"Jason Marsden","avatar":""},{"name":"Nathan Lane","avatar":""},{"name":"Ernie Sabella","avatar":""},{"name":"Andy Dick","avatar":""},{"name":"Robert Guillaume","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"Moira Kelly","avatar":""},{"name":"Suzanne Pleshette","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324537);
