INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-am-duong-3', 'Lộ Âm Dương 3', 'Troublesome Night 3', 'https://phimimg.com/upload/vod/20231012-1/0b8c03e80e6b7a840f7737953c9d89eb.jpg', 'https://phimimg.com/upload/vod/20231012-1/b387ab9ead5d8984c59cda8168b0baf5.jpg', '<p>Bộ phim bao gồm ba phân đoạn kết nối lỏng lẻo dựa trên chủ đề trung tâm của một nhà xác. Shishedo, một người thế chấp, đau buồn khi ca sĩ yêu thích của mình, Lam Wing-si, bị giết trong một tai nạn xe hơi. Khuôn mặt của Lam bị tàn phá nặng nề nên Shishedo chiếm vị trí của cô trong quan tài bằng cách cải trang thành ca sĩ quá cố.&nbsp; Anh ta biến mất và để lại cho các đồng nghiệp của mình để đối phó với hậu quả ma quái. Trong phần tiếp theo, Gigi muốn một dịch vụ tưởng niệm cho mẹ cô, người đã treo cổ tự tử. Con ma của mẹ Gigi không hài lòng khi những người thế chấp tham lam cố gắng lừa con gái mình sử dụng dịch vụ của họ để cô ám ảnh họ.&nbsp; Phân đoạn cuối cùng liên quan đến Hùng, một người thế chấp, người đã tự tử sau khi bạn trai bỏ rơi cô vì công việc của cô. Bạn trai của cô phải đối mặt với quả báo khi hồn ma của cô trở lại ám ảnh anh ta và anh ta chết trong một tai nạn sau đó.</p>', 'Full', 1, 'single', 'completed', 18, 1998, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Vincent Kok","avatar":""},{"name":"Lee Kin-Yan","avatar":""},{"name":"Lee Lik-Chi","avatar":""},{"name":"Helen Poon Bing-Seung","avatar":""},{"name":"Simon Lui","avatar":""},{"name":"Rain Lau","avatar":""},{"name":"Allen Ting","avatar":""},{"name":"Frankie Ng","avatar":""},{"name":"Emotion Cheung Kam-Ching","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324537);
