INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-phi-thuong', 'Cảnh Sát Phi Thường', 'Magnificent Team', 'null', 'https://phimimg.com/upload/vod/20231010-1/d2532dcc4f372f025e2e44af112dc0b0.jpg', '<p>Một thám tử chìm (Francis Ng), người yêu của anh ta (Amanda Lee) và một người bạn chung (Christine Ng) cố gắng truy bắt kẻ đang giết người dùng Internet.</p>', 'Full', 1, 'single', 'completed', 21, 1998, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Francis Ng","avatar":""},{"name":"Christine Ng","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Amanda Lee","avatar":""},{"name":"Simon Lui","avatar":""},{"name":"Karen Tong","avatar":""},{"name":"Lo Meng","avatar":""},{"name":"Angela Tong","avatar":""},{"name":"Emily Kwan Bo-Wai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324537);
