INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-ngot', 'Đột Ngột', 'Expect The Unexpected', 'https://phimimg.com/upload/vod/20231009-1/4d0083652d7db264231c55ef6d7896b6.jpg', 'https://phimimg.com/upload/vod/20231009-1/1b3d86de5808e31d559083b48f02bb69.jpg', '<p>Trong bộ phim &quot;cảnh sát và tên cướp&quot; này, một cuộc đột kích vào một cửa hàng trang sức do một nhóm nghệ sĩ nghiệp dư dàn dựng đã sai lầm khủng khiếp, dẫn đến một cuộc đấu súng. Đội ngũ ưu tú của Cục Tội phạm có Tổ chức, do Đại úy Ching King Gen đứng đầu, sẵn sàng hành động ngay lập tức. Hoạt động như một đơn vị, họ mang lại luật pháp và trật tự cho đường phố Hồng Kông, nơi họ phải dựa vào lòng dũng cảm và kỹ năng của mình để tồn tại.</p>', 'Full', 1, 'single', 'completed', 20, 1998, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Ruby Wong Cheuk-Ling","avatar":""},{"name":"Raymond Wong Ho-yin","avatar":""},{"name":"Yoyo Mung","avatar":""},{"name":"Bak Ka-Sin","avatar":""},{"name":"Keiji Sato","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Chiu Chi-Shing","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324537);
