INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-huu-hy-su-2', 'Gia Hữu Hỷ Sự 2', 'All''s Well, End''s Well ''97', 'https://phimimg.com/uploads/movies/20260713/gia-huu-hy-su-2-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/gia-huu-hy-su-2-poster.webp', '<p>Nhà Có Chuyện Vui 1997 hay Gia Hữu Hỷ Sự 2 là bộ phim hài tiếp nối tiếp câu chuyện của ba anh em ở phần 1, với những tình huống rắc rối của một gia đình tưởng chừng như không thể cứu vãn nỗi thế nhưng khi xem phim này bạn sẽ thấy trải qua bao nhiêu trắc trở, họ đã trưởng thành, họ đã hiểu nhau nhiều hơn, và đã yêu thương đùm bọc lẫn nhau tạo nên gia đình vui vẻ... Phim Gia Hữu Hỷ Sự 2 vẫn nhiều tình tiết hài hước thú vị đan xen vào câu chuyện. Hãy cùng trải qua những khoảng thời gian vui vẻ, tuyệt vời!</p>', 'Full', 1, 'single', 'completed', 77, 1997, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Tinh Trì","avatar":""},{"name":"Hoàng Bách Minh","avatar":""},{"name":"Ngô Trấn Vũ","avatar":""},{"name":"Ngô Thiến Liên","avatar":""},{"name":"Chung Lệ Đề","avatar":""},{"name":"Ngũ Vịnh Vy","avatar":""},{"name":"Kiều Hoành","avatar":""},{"name":"Lê Tư","avatar":""},{"name":"Châu Hoa Kiện","avatar":""},{"name":"Lý Huệ Mẫn","avatar":""},{"name":"Lôi Vũ Dương","avatar":""},{"name":"La Hạo Giai","avatar":""},{"name":"La Quán Lan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["All''s Well, End''s Well 1997","가유희사 1997","Alls Well Ends Well 1997 - Gia Hữu Hỷ Sự phần 2","Gia Hữu Hỷ Sự 2 (1997)","97 ga 