INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-lotita', 'Nàng Lotita', 'Lolita', 'https://phimimg.com/upload/vod/20260617-1/9f9961f56c82e6d96044bb3e088b282f.jpg', 'https://phimimg.com/upload/vod/20260617-1/c0f8da6b82bbb433c9c40bf74ae42080.jpg', '<p>Lolita 1997 được chuyển thể từ tác phẩm văn học cùng tên nổi tiếng của nhà văn Vladimir Nabokov, kể về mối tình bất thường và vĩ đại của giáo sư Humbert dành cho con riêng của vợ, Dolores Haze, hay còn gọi là Lolita. Tuy nhiên, ở một góc độ khác, nhiều khán giả nhận xét rằng Lolita phản ánh hiện tượng &quot;ấu dâm&quot;, những ám ảnh tình dục của một người đàn ông trung niên dành cho cô bé nhỏ tuổi hơn, ở bất cứ thời đại nào, hay bất cứ xã hội nào.</p>', 'Full', 1, 'single', 'completed', 81, 1997, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Jeremy Irons","avatar":""},{"name":"Dominique Swain","avatar":""},{"name":"Melanie Griffith","avatar":""},{"name":"Frank Langella","avatar":""},{"name":"Suzanne Shepherd","avatar":""},{"name":"Keith Reddin","avatar":""},{"name":"Erin J. Dean","avatar":""},{"name":"Joan Glover","avatar":""},{"name":"Pat Perkins","avatar":""},{"name":"Ed Grady","avatar":""},{"name":"Angela Paton","avatar":""},{"name":"Michael Goodwin","avatar":""},{"name":"Ben Silverstone","avatar":""},{"name":"Emma Griffiths Malin","avatar":""},{"name":"Ronald Pickup","avatar":""},{"name":"Kathryn Peterson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Lolita: Una pasión prohibida","Lolita de Adrian Lyne","一树梨花压海棠","洛丽塔","لولیتا","Lolita"]', 1784690324537);
