INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-trai-di-voi-ma-mac-ao-giay', 'Liêu Trai: Đi Với Ma Mặc Áo Giấy', 'Erotic Ghost Story: Perfect Match', 'https://phimimg.com/upload/vod/20260503-1/61620c1ff70c796a12e5b86cff43ca3d.jpg', 'https://phimimg.com/upload/vod/20260503-1/37eae827bae1aad637cdd03eae29a7fc.jpg', '<p>Một hôm, thỏ ngọc trên thiên đình thoát xuống trần gian. Thượng đế liền phái thiên binh đuổi theo truy bắt . Thỏ ngọc có thể hóa thân thành các cô gái, là các cô gái nghiêng nước đổ thùng. Một thỏ ngọc biến thành vợ của La Hán &quot;Đa Ngôn&quot; (Bàng Đơn và Từ Cẩm Giang đóng). Trong khi đó, một con thỏ ngọc khác được một chàng học sĩ cứu thoát chết. Để trả ơn, hàng đêm cô chiều chuộng chàng. Sáng sáng, chàng phát hiện mình bị mộng tinh và việc đó lặp đi lặp lại. Những tưởng cả hai thỏ ngọc sẽ được hạnh phúc mãi mãi, nào ngờ thiên binh đã đến nơi rồi…</p>', 'Full', 1, 'single', 'completed', 20, 1997, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Diana Pang Dan","avatar":""},{"name":"Keung Ka-Ling","avatar":""},{"name":"Teresa Mak Ka-Kei","avatar":""},{"name":"Miu Kam-Fung","avatar":""},{"name":"Wong Yat-Fei","avatar":""},{"name":"Chui Bo-Lun","avatar":""},{"name":"Ho Pak-Kwong","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Erotic Ghost Story-Perfect Match","聊斋艳谭Ⅳ：幽媾","聊斋之和尚奇缘","和尚奇缘","聊齋艷譚之幽媾"]', 1784690324537);
