INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-noi-mua-dong-nam-46', 'Hà Nội: Mùa Đông năm 46', 'Hanoi: Winter 1946', 'https://phimimg.com/upload/vod/20250401-1/e1ec9e9feea982ae8dd250d06fca108d.jpg', 'https://phimimg.com/upload/vod/20250401-1/8d89cb7f7e7ce08c250e3e26bc390079.jpg', '<p>“Hà Nội mùa đông 1946” là một phim ghi lại thời khắc lịch sử quan trọng của Hà Nội. Đó là vào mùa đông năm 1946, khi cuộc đàm phán trong Hội nghị Phông-ten-nơ-blô (Fontainebbeau) tại Pháp thất bại, Hồ Chủ tịch ký tạm ước với Pháp để tranh thủ thời gian chuẩn bị đối phó với tình hình. Phim khai thác mạnh khả năng đối nội và đối ngoại đầy trí tuệ của Bác Hồ và các nhà lãnh đạo chính quyền cách mạng trong thời khắc quan trọng đó.</p>', 'Full', 1, 'single', 'completed', 36, 1997, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Tien Loi","avatar":""},{"name":"Võ Hoài Nam","avatar":""},{"name":"Quôc-Tuân","avatar":""},{"name":"Mai Thu Huyền","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Hanoï hiver 1946","Hà Nội mùa đông năm 46"]', 1784690324537);
