INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gian-khong-lo', 'Gián Khổng Lồ', 'Mimic', 'https://phimimg.com/upload/vod/20260326-1/0c19c2a485ff62d2c7515e3f6360abe6.jpg', 'https://phimimg.com/upload/vod/20260326-1/a9baced2df8bf12484d3396f633637f0.jpg', '<p>Một căn bệnh do loài gián thông thường gây ra đang giết chết trẻ em ở Manhattan. Trong nỗ lực ngăn chặn dịch bệnh, nhà côn trùng học Susan Tyler đã tạo ra một giống côn trùng đột biến tiết ra một chất dịch để tiêu diệt gián. Giống côn trùng đột biến này được thiết kế để chết sau một thế hệ, nhưng ba năm sau, Susan phát hiện ra rằng loài này đã sống sót và tiến hóa thành một con quái vật khổng lồ, gớm ghiếc có thể bắt chước hình dạng con người.</p>', 'Full', 1, 'single', 'completed', 17, 1997, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mira Sorvino","avatar":""},{"name":"Jeremy Northam","avatar":""},{"name":"Alexander Goodwin","avatar":""},{"name":"Giancarlo Giannini","avatar":""},{"name":"Charles S. Dutton","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Alix Koromzay","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"James Costa","avatar":""},{"name":"Javon Barnwell","avatar":""},{"name":"Norman Reedus","avatar":""},{"name":"Ho Pak-Kwong","avatar":""},{"name":"Glenn Bang","avatar":""},{"name":"Margaret Ma","avatar":""},{"name":"Warna Fisher","avatar":""},{"name":"Alan Argue","avatar":""},{"name":"Charles Hay","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Mutação","Mimic - Terror en el metro","秘密客","Mimic Terror en el Metro","미믹","變種DNA","Mimic"]', 1784690324538);
