INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('menh-lenh-chien-luoc', 'Mệnh Lệnh Chiến Lược', 'Strategic Command', 'https://phimimg.com/upload/vod/20251023-1/16d07e18b9a04c2eb21695100aa84661.jpg', 'https://phimimg.com/upload/vod/20251023-1/f128ee1ee088025d84a1cf6597a250ab.jpg', '<p>Rick Harding là cựu sĩ quan thủy quân lục chiến, hiện đang làm việc trong FBI với tư cách là nhà thiết kế vũ khí hóa học. Trong khi thu dọn đồ đạc trong đêm, một nhóm binh lính có vũ trang do tên tội phạm bị truy nã Carlos Gruber dẫn đầu đột nhập vào phòng thí nghiệm nghiên cứu của FBI. Họ đánh cắp một lượng lớn hóa chất chiến tranh vi trùng mới được tạo ra có tên là Bromax-360, khiến hai người của họ mất mạng trong quá trình này trước khi trốn thoát vào màn đêm.</p>', 'Full', 1, 'single', 'completed', 18, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Dudikoff","avatar":""},{"name":"Richard Norton","avatar":""},{"name":"Paul Winfield","avatar":""},{"name":"Amanda Wyss","avatar":""},{"name":"Jsu Garcia","avatar":""},{"name":"Robin Lange","avatar":""},{"name":"Gina Mari","avatar":""},{"name":"Stephen Quadros","avatar":""},{"name":"Tim Abell","avatar":""},{"name":"Warren Burton","avatar":""},{"name":"Michael Cavanaugh","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"Jim McMullan","avatar":""},{"name":"Matthew Walker","avatar":""},{"name":"Marcus Aurelius","avatar":""},{"name":"Larry Poindexter","avatar":""},{"name":"William Langlo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Strategic Command","Executive Command","Executive Command - In einsamer Mission","ステルスＶＳステルス エグゼクティブコマンド","エグゼクティブコマンド"]', 1784690324538);
