INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-vi-thien-vuong', 'Mỹ Vị Thiên Vương', 'A Recipe for the Heart', 'https://phimimg.com/upload/vod/20251010-1/8dd8d11a5e296d94ad35d10c93d891aa.jpg', 'https://phimimg.com/upload/vod/20251010-1/9d9dee84d459a7e6504f7808c19558c6.jpg', '<p>Ông chủ Thạch của Mỹ Vị Viên sau khi tham gia thi đấu thua Sơn đã bặt vô âm tín. Vợ ông là Thang Viên Viên cùng con gái Tô Tô cố gắng duy trì Mỹ Vị Viên, chỉ tiếc Tô Tô chưa đủ bản lĩnh, Viên đành đem bán cổ phần, người tiếp quản lại là Sơn - lúc này đã đổi tên thành Cát. Cát và Tô trở thành đôi oan gia đối nghịch với nhau, trong lúc đó Sảng Sảng tự nhận là vợ Cát lại đột nhiên xuất hiện. Khi Viên gặp lại Thạch thì phát hiện Thạch đã mất trí nhớ, quên hết chuyện cũ...</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 13, 1997, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Lydia Shum Tin-Ha","avatar":""},{"name":"Jessica Hsuan","avatar":""},{"name":"Bobby Au-Yeung Tsan-Wah","avatar":""},{"name":"Maggie Cheung Ho-Yee","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Esther Kwan Wing-Ho","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Miriam Yeung Chin-Wah","avatar":""},{"name":"Felton Law Gwan-Joh","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Maggie Wong Mei-Kei","avatar":""},{"name":"John Tang Yat-Kwan","avatar":""},{"name":"Sung Chi-Ling","avatar":""},{"name":"Lo Meng","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["A RECIPE FOR THE HEART","A Recipe for the Heart","美味天王"]', 1784690324538);
