INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-khau-muon-mau', 'Sân Khấu Muôn Màu', 'Show Time Blues', 'https://phimimg.com/upload/vod/20251008-1/85babe2010ae3734ff412b698e4a8cf1.jpg', 'https://phimimg.com/upload/vod/20251008-1/0d818dacd281121b295ab438fef14b05.jpg', '<p>Lục Minh Hà và Hứa Lang Bình đều là ca sĩ nổi tiếng. Họ cùng đem lòng yêu diễn viên Triệu Ninh. Sau đó, Hà phát hiện Ninh đang lợi dụng mình nên quyết định chia tay. Còn Bình cũng tìm được mối tình khác và muốn từ giã làng giải trí. Hai quản lý của Hà và Bình - Lô Chí Tài và Tiểu Hồng cá cược rằng bên nào có thể đào tạo người mới đoạt giải vàng năm tới sẽ thắng cuộc còn bên thua phải rút khỏi ngành. Nhân cơ hội cá cược này, Lệ San ứng tuyển để được lăng xê thành ca sĩ. Đối thủ của cô là Khương Đức Bồi. Hai người không có chút năng khiếu nghệ thuật nào, nhưng thần sai quỷ khiến, họ nhanh chóng trở thành nghệ sĩ ưu tú. Tài và Hồng cùng hai ca sĩ mới nổi dùng nhiều chiêu trò để lấn át đối phương. Cùng lúc đó, cậu của San tên là Minh, kinh doanh quán bar rất ăn khách nhờ có nhóm nhạc &quot;Ba Con Rùa&quot;. Biết được tình hình, San quyết định gia nhập nhóm để đánh bại Bội. Liệu, ai sẽ lên bục vinh quang và ai sẽ phải rời xa ánh đèn sân khấu?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 14, 1997, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Gordon Lam Ka-Tung","avatar":""},{"name":"Alvina Kong Yan-Yin","avatar":""},{"name":"Wayne Lai Yiu-Cheung","avatar":""},{"name":"Cutie Mui Siu-Wai","avatar":""},{"name":"Florence Kwok Siu-Wan","avatar":""},{"name":"Louis Yuen Siu-Cheung","avatar":""},{"name":"Law Ho-Kai","avatar":""},{"name":"Mimi Chu Mai-Mai","avatar":""},{"name":"Joe Ma Tak-Chung","avatar":""},{"name":"Bessie Chan Ming-Kwan","avatar":""},{"name":"Felton Law Gwan-Joh","avatar":""},{"name":"Cho Chun","avatar":""},{"name":"Peter Lai Bei-Dak","avatar":""},{"name":"Lau Ko","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["樂壇插班生"]', 1784690324538);
