INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngai-bean', 'Ngài Bean', 'Bean', 'https://phimimg.com/upload/vod/20251008-1/88abe31c5ef53c9a05a6fc81324aba6d.jpg', 'https://phimimg.com/upload/vod/20251008-1/32f1b492140345307232bbc82d010826.jpg', '<p>Bean là người coi sóc các bức tranh trong Viện bảo tàng Hoàng gia Anh. Ông chủ của anh muốn sa thải anh vì anh ngủ hầu như toàn bộ thời gian làm việc. nhưng không thể vì chủ tịch hội đồng quản trị của viện bảo tàng bảo vệ cho Bean. Thay vào đó, họ gửi anh qua Mĩ, tới một viện bảo tàng nhỏ ở Los Angel. Cuộc phiêu lưu mới của Ngài Bean sẽ như thế nào đây?</p>', 'Full', 1, 'single', 'completed', 13, 1997, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Rowan Atkinson","avatar":""},{"name":"Peter MacNicol","avatar":""},{"name":"Pamela Reed","avatar":""},{"name":"Tricia Vessey","avatar":""},{"name":"Andrew Lawrence","avatar":""},{"name":"Harris Yulin","avatar":""},{"name":"Burt Reynolds","avatar":""},{"name":"Richard Gant","avatar":""},{"name":"Chris Ellis","avatar":""},{"name":"Tom McGowan","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"Peter Egan","avatar":""},{"name":"Peter Capaldi","avatar":""},{"name":"Scott Charles","avatar":""},{"name":"Alison Goldie","avatar":""},{"name":"Julia Pearlstein","avatar":""},{"name":"Rob Brownstein","avatar":""},{"name":"Clive C","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Bean: The Ultimate Disaster Movie","Mr. Bean - Mais Atrapalhado do Que Nunca","Bean, la película del desastre","Bean, lo último en cine catastrófico","Mister Bean - O Filme","Mr. Bean - Az igazi katas