INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngai-bean', 'Ngài Bean', 'Bean', 'ngài bean bean rowan atkinson peter macnicol pamela reed tricia vessey andrew lawrence harris yulin burt reynolds richard gant chris ellis tom mcgowan sandra oh peter egan peter capaldi scott charles alison goldie julia pearlstein rob brownstein clive c bean: the ultimate disaster movie mr. bean - mais atrapalhado do que nunca bean, la película del desastre bean, lo último en cine catastrófico mister bean - o filme mr. bean - az igazi katasztrófafilm bean : l''ultime film catastrophe bean, le film le plus catastrophe mr. bean, le film le plus catastrophe mr. bean : le film le plus catastrophe בין: הקומדיה הקולנועית המטורפת בין: סרט האסונות האולטימטיבי בין: הסרט ngài bean mr bean: 1 - bean, lo último en cine catastrófico 憨豆的大灾难 bean: the movie bean', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-duong-lo-1997', 'Âm Dương Lộ', 'Troublesome Night', 'https://phimimg.com/upload/vod/20250930-1/8cd429be801371779d96c0c8c3fe0bb4.jpg', 'https://phimimg.com/upload/vod/20250930-1/6919ab63e089685f10ea2a61b89ecb96.jpg', '<p>Bộ phim được gộp lại từ 4 câu chuyện ma có liên quan đên nhau. câu chuyện đầu tiên Một nhóm thanh niên đi cắm trại ở một vùng quê hẻo lánh, một thành viên trong nhóm là Ken khi đi qua một khu mộ thì bắt gặp một người phụ nữ ở gần đó. Sau cuộc gặp gỡ, Ken trở thành nan nhận của các thế lực siêu nhiên. Khi những người bạn trở về Hong Kong mà không có anh ta, một câu chuyện khác bắt đầu. Bà To đã sắp xếp để kỷ niệm ngày cưới với chồng nhưng ông không xuất hiện. Kết quả của câu chuyện thứ hai dẫn đến một câu chuyện khác.</p>', 'Full', 1, 'single', 'completed', 14, 1997, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Simon Lui Yu-Yeung","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Allen Ting Chi-Chun","avatar":""},{"name":"Jason Chu Wing-Tong","avatar":""},{"name":"Ada Choi Siu-Fan","avatar":""},{"name":"Teresa Mak Ka-Kei","avatar":""},{"name":"Bak Ka-Sin","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Lee Lik-Chi","avatar":""},{"name":"Frankie Ng Chi-Hung","avatar":""},{"name":"Kingdom Yuen King-Tan","avatar":""},{"name":"Christy Chung Lai-Tai","avatar":""},{"name":"Sunny Chan Kam-Hung","avatar":""},{"name":"Hui Fan","avatar":""},{"name":"Lee Siu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Yin yang lu","陰陽路","Troublesome Night","陰陽路 (1997)"]', 1784690324538);
