INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-kinh-hai', 'Mùa Hè Kinh Hãi', 'I Know What You Did Last Summer', 'https://phimimg.com/upload/vod/20250815-1/65fc1b38e7c021153a120438b0f2060f.jpg', 'https://phimimg.com/upload/vod/20250815-1/3ac2b954e557e5336e93a90749ff75fa.jpg', '<p>Bốn người trẻ tuổi sau khi trở về sau buổi tiệc trên chiếc xe mới đã gây tai nạn làm chết một người đàn ông, nhưng thay vì gọi cảnh sát hay xe cứu thương họ lo sợ cho bản thân sẽ bị dính líu nên tìm cách che giấu tội ác. Họ quăng cái xác chết xuống biển sau đó trở về cuộc sống bình thường. Một năm sau họ nhận được những lá thư có nội dung: &quot;Tao biết chúng mày đã làm gì mùa hè trước&quot; và từng người bị tấn công bởi một người đàn ông với cái móc câu...</p>', 'Full', 1, 'single', 'completed', 13, 1997, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jennifer Love Hewitt","avatar":""},{"name":"Freddie Prinze Jr.","avatar":""},{"name":"Sarah Michelle Gellar","avatar":""},{"name":"Ryan Phillippe","avatar":""},{"name":"Bridgette Wilson-Sampras","avatar":""},{"name":"Johnny Galecki","avatar":""},{"name":"Muse Watson","avatar":""},{"name":"Anne Heche","avatar":""},{"name":"Stuart Greer","avatar":""},{"name":"Dan Albright","avatar":""},{"name":"Rasool J''Han","avatar":""},{"name":"J. Don Ferguson","avatar":""},{"name":"Deborah Hobart","avatar":""},{"name":"Mary McMillan","avatar":""},{"name":"Lynda Clark","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Xero ti kanate persi to kalokairi","Znam što si radila prošlog ljeta","Ani Yodea Ma Asita B''Kayitz Ha-Aharon","Zinau, ka padarei ana vasara","Znam šta ste radili prošlog leta","Souviens-toi... l''été dernier","Koszmar Minionego Lata","Keçən Yay Neylədiyini Bilirəm","E di çfarë ke bërë verën e kaluar","I Know What You Did Last Summer"]', 1784690324538);
