INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mua-he-kinh-hai', 'Mùa Hè Kinh Hãi', 'I Know What You Did Last Summer', 'mùa hè kinh hãi i know what you did last summer jennifer love hewitt freddie prinze jr. sarah michelle gellar ryan phillippe bridgette wilson-sampras johnny galecki muse watson anne heche stuart greer dan albright rasool j''han j. don ferguson deborah hobart mary mcmillan lynda clark xero ti kanate persi to kalokairi znam što si radila prošlog ljeta ani yodea ma asita b''kayitz ha-aharon zinau, ka padarei ana vasara znam šta ste radili prošlog leta souviens-toi... l''été dernier koszmar minionego lata keçən yay neylədiyini bilirəm e di çfarë ke bërë verën e kaluar i know what you did last summer', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rong-den-vo-dai-sinh-tu', 'Rồng Đen: Võ Đài Sinh Tử', 'Mortal Kombat: Annihilation', 'https://phimimg.com/upload/vod/20250804-1/cb37109ad23fdd5716f9f80d2b18529a.jpg', 'https://phimimg.com/upload/vod/20250804-1/b7fa4066c4323276ab80215affa56615.jpg', '<p>Sau sự ra mắt của phần 1 được ra mắt năm 1995, bộ phim Rồng Đen 1 được tiếp nối nội dung với phần 2 ra mắt năm 1997 bởi đạo diễn John R. Leonetti, những diễn biến mới của Rồng Đen 2 đưa chúng ta tới những câu chuyện vừa cũ vừa mới đầy kịch tính cùng nhiều màn hành động, đấu võ mãn nhãn. Ở phần này, Liu Kang (Robin Shou) sẽ là tâm điểm của cuộc chiến, giữa bóng tối và ánh sáng ai sẽ là người chiến thắng và liệu rằng nhân loại có được cứu khỏi sự diệt vong, mọi thứ sẽ có trong Mortal Kombat: Annihilation. Được đầu tư 30 triệu USD, bộ phim hứa hẹn mang lại những thước phim ấn tượng nhất về những nhân vật huyền thoại đi ra từ trong game.</p>', 'Full', 1, 'single', 'completed', 10, 1997, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robin Shou","avatar":""},{"name":"Talisa Soto","avatar":""},{"name":"James Remar","avatar":""},{"name":"Sandra Hess","avatar":""},{"name":"Lynn ''Red'' Williams","avatar":""},{"name":"Brian Thompson","avatar":""},{"name":"Musetta Vander","avatar":""},{"name":"Irina Pantaeva","avatar":""},{"name":"J.J. Perry","avatar":""},{"name":"Keith Cooke","avatar":""},{"name":"Deron McBee","avatar":""},{"name":"Marjean Holden","avatar":""},{"name":"John Medlen","avatar":""},{"name":"Tyrone C. Wiggins","avatar":""},{"name":"Chris Conrad","avatar":""},{"name":"Ridley Tsui Bo-Wah","avatar":""},{"name":"Dana","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"685649