INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-nha-mot-minh-3', 'Ở Nhà Một Mình 3', 'Home Alone 3', 'https://phimimg.com/upload/vod/20250722-1/a00cdaee24b8cbc00f76d43ea8d955f8.jpg', 'https://phimimg.com/upload/vod/20250722-1/ac5e47a0a8a64b4bc69dc8152fa7f4bc.jpg', '<p>Phim Ở Nhà Một Mình 3 kể về một vụ con chip máy tính bị bốn tên trộm quốc tế ăn cắp của công ty máy tính. Chúng đã giấu trong chiếc xe ô tô đồ chơi và bà Hess khi ra sân bay ở San Fansisco đã lấy nhầm túi. Khi đến Chicago, bà lên chiếc taxi trở về trung tâm thành phố và bị một tên chụp biển số xe. Sau khi chú bé Alex dọn tuyết xong, bà không trả tiền công mà lại trả cho chú chiếc xe đồ chơi của bọn trộm và cầm về nhà. Bọn chúng ngơ ngác vì nhà nào cũng giống nhau nên không tìm ra được.</p>', 'Full', 1, 'single', 'completed', 11, 1997, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alex D. Linz","avatar":""},{"name":"Olek Krupa","avatar":""},{"name":"Rya Kihlstedt","avatar":""},{"name":"Lenny Von Dohlen","avatar":""},{"name":"David Thornton","avatar":""},{"name":"Haviland Morris","avatar":""},{"name":"Kevin Kilner","avatar":""},{"name":"Marian Seldes","avatar":""},{"name":"Seth Smith","avatar":""},{"name":"Scarlett Johansson","avatar":""},{"name":"Christopher Curry","avatar":""},{"name":"Baxter Harris","avatar":""},{"name":"James Saito","avatar":""},{"name":"Kevin Gudahl","avatar":""},{"name":"Richard Hamilton","avatar":""},{"name":"Freeman Coffey","avatar":""},{"name":"Krista","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b