INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('o-nha-mot-minh-3', 'Ở Nhà Một Mình 3', 'Home Alone 3', 'ở nhà một mình 3 home alone 3 alex d. linz olek krupa rya kihlstedt lenny von dohlen david thornton haviland morris kevin kilner marian seldes seth smith scarlett johansson christopher curry baxter harris james saito kevin gudahl richard hamilton freeman coffey krista mamma ho preso il morbillo ensam hemma 3 hjemme alene 3 esqueceram de mim 3 kevin 3 - wieder allein zu haus ホーム・アローン3 mi pobre angelito 3 один вдома 3 один удома 3 나 홀로 집에 3 sám doma 3 अकेला घर 3 وحيد في المنزل 3 לבד בבית 3 ở nhà một mình 3 kevin - allein zu haus 3 evdə tək 3 寶貝智多星3：智擒四大癲王 home alone 3', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-vien-ky-jura-2-the-gioi-bi-mat', 'Công Viên Kỷ Jura 2: Thế Giới Bị Mất', 'The Lost World: Jurassic Park', 'https://phimimg.com/upload/vod/20250717-1/2c316602cf7090501638a1be743f599f.jpg', 'https://phimimg.com/upload/vod/20250717-1/acb8bca9dec8b9b48a197da1b2957e75.jpg', '<p>Sau thất bại nặng nề tại đảo Nublar, công viên khủng long bị phá hủy hoàn toàn sau cơn bão. John tiếp tục tổ chức chuyến đi nghiên cứu thứ 2 tại hòn đảo có tên Sorna, thực chất, đây là hòn đảo thứ 2, nơi nuôi dưỡng và ấp trứng khủng long rồi chuyển tới Nublar. Trong chuyến đi lần này có Tiến sĩ Sara Harding, bạn gái của Tiến sĩ Ian Malcom (xuất hiện từ phần 1) Anh không được báo trước rằng cô sẽ tới đảo Sorna, biết rằng chuyến đi này rất nguy hiểm vì Ian đã từng ở trên đảo Nublar, anh quyết định mạo hiểm tới đảo để đưa Laura về. Đến khi tới đảo, anh mới tìm ra sự thật rằng thực chất đây là cuộc săn khủng long quy mô lớn, nhằm bắt chúng đem về thành phố San Fransisco, nơi 1 công viên khủng long mới đã được xây dựng sẵn.</p>', 'Full', 1, 'single', 'completed', 13, 1997, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jeff Goldblum","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Pete Postlethwaite","avatar":""},{"name":"Arliss Howard","avatar":""},{"name":"Richard Attenborough","avatar":""},{"name":"Vince Vaughn","avatar":""},{"name":"Vanessa Lee Chester","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Harvey Jason","avatar":""},{"name":"Richard Schiff","avatar":""},{"name":"Thomas F. Duffy","avatar":""},{"name":"Joseph Mazzello","avatar":""},{"name":"Ariana Richards","avatar":""},{"name":"Thomas Rosales Jr.","avatar":""},{"name":"Camilla Belle","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id"