INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-chua-soi-mononoke', 'Công Chúa Sói Mononoke', 'Princess Mononoke', 'công chúa sói mononoke princess mononoke yoji matsuda yuriko ishida yuko tanaka kaoru kobayashi masahiko nishimura tsunehiko kamijô akihiro miwa mitsuko mori hisaya morishige sumi shimamoto tetsu watanabe makoto satō akira nagoya kei iinuma tsuzuki kayako kimihiro reizei yoshimas mononoke hime 원령공주 princeza mononoke princesa mononoke a princesa mononoke prenses mononoke 幽靈公主 księżniczka mononoke принцесса мононокэ la princesa mononoke شاهزاده مونونوکه 魔法公主 prinses mononoke принцеса мононоке принцезата мононоке принцеза мононоке мононокэ инязортейтерь πριγκίπισσα μονονόκε şahzadə mononoke prinsesse mononoke prinzessin mononoke printsess mononoke bana-phrionnsa mononoke princese mononoke princesė mononokė a vadon hercegnője prințesa mononoke princezná mononoke prinsessa mononoke princezna mononoke մոնոնոքե արքայադուստրը პრინცესა მონონოკე prinsessan mononoke mononoke prinsessa الأميرة مونونوكي شازادە مۆنۆنۆک הנסיכה מונונוקי മോണോനോക്കെ-ഹിമെ 모노노케 히메 канбийке мононоке mitima''ay a kung-cu প্রিন্সেস মনোনোকে เจ้าหญิงจิตวิญญาณแห่งพงไพร princesse mononoké principessa mononoke もののけ姫', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cuoc-phieu-luu-cua-sinbad-phan-2', 'Những Cuộc Phiêu Lưu Của Sinbad (Phần 2)', 'The Adventures of Sinbad (Season 2)', 'https://phimimg.com/upload/vod/20250627-1/51c36267fea02599754f05a292c29303.jpg', 'https://phimimg.com/upload/vod/20250627-1/74d0f0f217a01135b456ce220a4f8478.jpg', '<p>Những Cuộc Phiêu Lưu Của Sinbad là câu chuyện về cuộc phiêu lưu của nhân vật nổi tiếng trong bộ truyện cổ tích nổi tiếng khắp thế giới The Arabian Nights (Nghìn lẻ một đêm). Hai năm sau khi Sinbad bị cuốn đi trong một cơn bão và thức dậy để tìm thấy một chiếc vòng tay bí ẩn đeo trên cổ tay, vị thuyền trưởng nổi tiếng bắt đầu những chuyến đi mới. Sinbad tập hợp một đội gồm có người anh trai bốc đồng Doubar, nhà phát minh, người đàn ông được đánh giá cao của Sciene Firouz, chiến binh thầm lặng Rongar, một phụ nữ Celtic tên là Maeve (người học việc của phù thủy Dimbad, Dim Dim). Sau này tham gia phi hành đoàn là một bí ẩn của một người phụ nữ được gọi là Bryn. Sự biến mất của Dim Dim và một trận chiến liên tục với một phù thủy tên Rumina, người có mối liên hệ với Maeve và Dermott, dẫn dắt cả nhóm đi đến những vùng đất xa xôi, chiến đấu với bạo chúa và quái vật, cùng những cuộc phiêu lưu trên thế giới.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 11, 1997, 'Thuyết Minh', 'HD', 'Canada', 0, '[{"name":"Zen Gesner","avatar":""},{"name":"George Buza","avatar":""},{"name":"Tim Progosh","avatar":""},{"name":"Oris Erhuero","avatar":""},{"name":"Mariah Shirley","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Приключения Синбада","The Adventures of Sinbad"]', 1784690324538);
