INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-cau-ca', 'Vua Câu Cá', 'Super Fishing Grander Musashi', 'https://phimimg.com/upload/vod/20250531-1/8340f2f43ef27149715668ff85ad9ca5.jpg', 'https://phimimg.com/upload/vod/20250531-1/1c12e2356bb6b792ecb59abee0a34bfa.jpg', '<p>Musashi sống cùng với cha mình. Mẹ của cậu đã rời bỏ hai cha con cách đây ba năm. Musashi luôn tin rằng mẹ sẽ quay trở lại với họ. Một ngày nọ, họ chuyển từ Tokyo về sống tại một ngôi làng ở vùng nông thôn. Musashi ghét cuộc sống nơi thôn quê và yêu cầu cha đưa cậu trở lại Tokyo. Cậu tự hỏi liệu mẹ có thể tìm được mình ở nơi ở mới hay không. Không lâu sau khi chuyển đến, Musashi tình cờ nhìn thấy một người đàn ông đang câu cá vược bằng cá mồi giả. Cậu bị mê hoặc bởi kỹ thuật câu cá bằng mồi giả này. Musashi học được rất nhiều điều từ người đàn ông đó và phát hiện ra rằng ông ngoại của mình từng là một nhà vô địch câu cá vược. Musashi cảm thấy rằng câu cá có thể là cách để cậu tìm lại mẹ mình. Cậu thể hiện tài năng xuất chúng trong việc câu cá bằng mồi giả và bắt đầu những chuyến đi đến nhiều nơi trên thế giới để tìm kiếm các loài cá kỳ lạ. Thông qua việc câu cá, Musashi dần dần học cách yêu thiên nhiên và cuộc sống nơi thôn quê.</p>', 'Hoàn Tất (64/64)', 64, 'series', 'completed', 8, 1997, 'Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["天才小魚郎","Мусасі Великий","Super Fishing Grander Musashi","スーパーフィッシング グランダー武蔵"]', 1784690324538);
