INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vua-cau-ca', 'Vua Câu Cá', 'Super Fishing Grander Musashi', 'vua câu cá super fishing grander musashi  天才小魚郎 мусасі великий super fishing grander musashi スーパーフィッシング グランダー武蔵', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-cuoc-phieu-luu-o-thanh-pho-day-cot', 'Doraemon: Nobita và Cuộc Phiêu Lưu Ở Thành Phố Dây Cót', 'Doraemon: Nobita and the Spiral City', 'https://phimimg.com/upload/vod/20250521-1/c166c767c1dfaa794859a48f311017dc.jpg', 'https://phimimg.com/upload/vod/20250521-1/8edce8e6571f9809a40734cf46bcc77b.jpg', '<p>Sau khi Suneo khoe khoang về việc có một trang trại, Nobita được hỏi liệu cậu có hay không, buộc miệng cậu nói có. Doraemon đã trúng một hàng chục giải xổ số trúng thưởng được những hành tinh vô dụng trong vành đai giữa sao Hỏa và sao Mộc. Khi Suneo và những người khác đến xem trang trại, Nobita đã tình cờ đọc được con số cuối cùng của dãy số xổ số cho cửa thần kỳ, dẫn họ đến một khu vực rộng lớn đẹp như mơ. Khi con ngựa đồ chơi của Nobita tung tăng xung quanh thích thú Suneo và những người khác bắt đầu tạo sự sống cho đồ chơi của họ và để chúng sống trong khu vực. Vì vậy, họ quyết định tạo ra thành phố đồng hồ của riêng mình.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 1997, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Sachiko Chijimatsu","avatar":""},{"name":"Nozomu Sasaki","avatar":""},{"name":"Sumiko Shirakawa","avatar":""},{"name":"Masashi Sugawara","avatar":""},{"name":"Kaneto Shiozawa","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Doraemon Nobita no Neji maki Shiti Bokenki","Doraemon i la fàbrica de joguines","Doraemon: Nobita''s Adventure in Clockwork City","Nobita and the Spiral City","도라에몽: 노비타의 태엽도시 모험기","哆啦A夢：大雄的發條都市冒險記","Doraemon the movie: नोबिता इन गोल गोल गोलमाल","哆啦A梦：大雄和发条都市冒险记","哆啦A梦：大雄的发条都市冒险记","電影哆啦A夢：大雄的發條城歷險記","映画ドラえもん のび太のねじ巻き都市冒険記"]', 1784690324538);
