INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-si-quan', 'Hạ Sĩ Quan', 'Sergeant', 'https://phimimg.com/upload/vod/20250406-1/77097c21e76a16332293812c71a6aab4.jpg', 'https://phimimg.com/upload/vod/20250406-1/b4eef591723c8cc3d2300c2de19767b4.jpg', '<p>Câu chuyện binh nghiệp của Long do Huỳnh Anh Tuấn thủ vai, một sinh viên miền Nam tập kết ra Bắc, anh nhập ngũ và bị nhiễm khí độc. Sau khi bình phục, Long chuyển sang làm quân bưu, gia nhập tiểu đoàn công binh đào hầm, vệ binh và lính cơ khí.</p>', 'Full', 1, 'single', 'completed', 14, 1997, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Huỳnh Anh Tuấn","avatar":""},{"name":"Bảo Châu","avatar":""},{"name":"Hà Phương","avatar":""},{"name":"Nguyễn Hoàng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324538);
