INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-co-gai-nha-abbott', 'Ba Cô Gái Nhà Abbott', 'Inventing The Abbotts', 'https://phimimg.com/upload/vod/20250306-1/913a9353fd4075cd3f2c4530a08887e8.jpg', 'https://phimimg.com/upload/vod/20250306-1/b09dc8f374fa0409b0f197f2ab1fc997.jpg', '<p>Bộ phim &#39;&#39;Inventing The Abbotts&#39;&#39; là câu chuyện về hai anh em Jacey và Doug Holt trong mối quan hệ của họ với ba chị em gái xinh đẹp nhà Abbott. Trong khi cậu em ngây thơ và ngốc xít thì người anh trai Jacey lại vô cùng &#39;&#39;sát gái&#39;&#39;. Liệu ai trong họ sẽ chinh phục được những cô gái láng giềng xinh đẹp này?</p>', 'Full', 1, 'single', 'completed', 11, 1997, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joaquin Phoenix","avatar":""},{"name":"Liv Tyler","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Billy Crudup","avatar":""},{"name":"Joanna Going","avatar":""},{"name":"Kathy Baker","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Michael Sutton","avatar":""},{"name":"Garrett M. Brown","avatar":""},{"name":"Barbara Williams","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Nicole M. Vassallo","avatar":""},{"name":"Amanda Sherman","avatar":""},{"name":"Shawn Hatosy","avatar":""},{"name":"Julie Benz","avatar":""},{"name":"Zoe McLellan","avatar":""},{"name":"David F","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Kärlek och hämnd","Вигадане життя Ебботів","Círculo de Pasiones","Inventing the Abbotts"]', 1784690324538);
