INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ba-co-gai-nha-abbott', 'Ba Cô Gái Nhà Abbott', 'Inventing The Abbotts', 'ba cô gái nhà abbott inventing the abbotts joaquin phoenix liv tyler jennifer connelly billy crudup joanna going kathy baker will patton michael sutton garrett m. brown barbara williams alessandro nivola nicole m. vassallo amanda sherman shawn hatosy julie benz zoe mclellan david f kärlek och hämnd вигадане життя ебботів círculo de pasiones inventing the abbotts', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-trinh-sat-phan-3', 'Hồ Sơ Trinh Sát (Phần 3)', 'Detective Investigation Files (Season 3)', 'https://phimimg.com/upload/vod/20250114-1/5d03be4796f9ee606f2c68efe02b540d.jpg', 'https://phimimg.com/upload/vod/20250114-1/55f47710458d2ad17c14987bd3bdad30.jpg', '<p>Hồ Sơ Trinh Sát (tiếng Hoa: 刑事偵緝檔案, tiếng Anh: Detective Investigation Files) là bộ phim đầu tiên về đề tài phá án hình sự của Hồng Kông do giám chế Phan Gia Đức sản xuất, mở đường cho thể loại phim hành động cảnh sát quen thuộc của Hồng Kông sau này. Phim nằm trong top 10 phim kinh điển của truyền hình Hồng Kông qua mọi thời đại. Hồ sơ trinh sát đã khắc họa góc nhìn chân thật của cảnh sát Hồng Kông qua những vụ án ly kỳ, hấp dẫn và có phần rùng rợn. Bộ phim khi được phát sóng đã tạo nên cơn sốt với lượng rating kỷ lục. Thành công của bộ phim đã đưa tên tuổi của Đào Đại Vũ và Quách Khả Doanh trở thành tiểu sinh và hoa đán hàng đầu của TVB của thập niên 90. Nhân vật Trương Đại Dũng của Đào Đại Vũ cũng nằm trong top 100 nhân vật kinh điển nhất của truyền hình Hồng Kông. Bên cạnh đó, Đào Đại Vũ và Quách Khả Doanh còn liên tiếp nhận được giải Cặp đôi được yêu thích nhất 4 năm liền từ 1996-1999.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 10, 1997, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Jessica Hester Hsuan","avatar":""},{"name":"Sunny Chan Kam-Hung","avatar":""},{"name":"Charmaine Sheh Sze-Man","avatar":""},{"name":"Lee San-San","avatar":""},{"name":"Maggie Siu Mei-Kei","avatar":""},{"name":"Andy Tai Chi-Wai","avatar":""},{"name":"Samuel Kwok Fung","avatar":""},{"name":"Edmond So Chi-Wai","avatar":""},{"name":"Eileen Yeow","avatar":""},{"name":"Timothy Cheng Chi-Sing","avatar":""},{"name":"Anne Heung Hoi-Lam","avatar":""},{"name":"Catherine Chau","avatar":""},{"name":"Edward Mok","avatar":""},{"name":"Henr","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Detective Investigation Files","刑事偵緝檔案","刑事侦缉档案"]', 1784690324538);
