INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doat-xa', 'Đoạt Xá', 'Walk In', 'https://phimimg.com/upload/vod/20250104-1/003c2406bcd1922883ec439cc5e6ec82.jpg', 'https://phimimg.com/upload/vod/20250104-1/960d16c6be0dd79b54b5e071eb60fc67.jpg', '<p>Viên cảnh sát do Huang Zihua thủ vai bị bắn trong một vụ cướp và bị liệt. Tên trùm xã hội đen Li Xiuxian, người chịu trách nhiệm điều khiển tên xã hội đen trong vụ án tương tự, đã bị bắn và rơi vào tình trạng thực vật. Wong Zi-hua không muốn dành phần đời còn lại của mình như một kẻ vô dụng, và sử dụng cơ thể của Danny Lee để tái sinh dưới sự hướng dẫn của Jacklyn Wu, người đã biến hình sau khi ông già thông thái lấy đi cơ thể của anh. Thật bất ngờ, Li Xiuxian hóa ra là một kẻ cặn bã đáng ghét, và danh tiếng của anh ta lan rộng khắp quê hương đảo Lantau. Li Xiuxian mới thông minh và có ý thức công lý. Thật thú vị khi xem cách anh ta trả hết nợ và lấy lại trái tim của ba người vợ. Em gái Weng Hong, người biết nội tình, công khai có tình cảm đơn phương với anh trai mình, Huang Zihua rất vui khi được người lớn sắp xếp như đi vệ sinh mỗi khi tán tỉnh phụ nữ nhà họ Lý. một sự ngạc nhiên.</p>', 'Full', 1, 'single', 'completed', 11, 1997, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Jacklyn Wu Chien-Lien","avatar":""},{"name":"Danny Lee Sau-Yin","avatar":""},{"name":"Ada Choi Siu-Fan","avatar":""},{"name":"Dayo Wong Chi-Wah","avatar":""},{"name":"Yu Li","avatar":""},{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"May Law Koon-Lan","avatar":""},{"name":"Gam Wai-Ying","avatar":""},{"name":"Yvonne Yung Hung","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Hui Fan","avatar":""},{"name":"Chan Chi-Fai","avatar":""},{"name":"Pau Hei-Ching","avatar":""},{"name":"Frankie Chin Chi-Leung","avatar":""},{"name":"Alice Fung So-Po","avatar":""},{"name":"F","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Duo she","奪舍"]', 1784690324538);
