INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-nang-vai', 'Anh Hùng Nặng Vai', 'Weapons Of Power', 'https://phimimg.com/upload/vod/20241214-1/dfcc3b85086c684abeb7bb6552b88399.jpg', 'https://phimimg.com/upload/vod/20241214-1/ea3705414551bcf1502a287c9564f4b4.jpg', '<p>Trong ngày tỉ thí để tiếp nhận chức chưởng môn của Tam Tuyệt Trang. Mộ Dung Bạch bị kẻ gian ám hại, tẩm độc vào mũi thương, khiến Đại Sư Huynh mất một tay. Kẻ gian đó là Quân Tử Kiếm Hạ Hầu Đôn, tam sư đệ của Tam Tuyệt Trang. Hạ Hầu Đôn giết sự phụ, đổ tội cho Mộ Dung Bạch, bị đuổi đến đường cùng Mộ Dung Bạch buộc phải bỏ đứa con vừa đầy tháng xuống sông trôi theo dòng nước, nhảy xuống vực thẳm. Hạ Hầu Đôn trở thành trưởng môn.<br/><br/>Lâm đại thẩm giặt đồ bên bờ sông trông thấy đứa bé dễ thương nằm trong chiếc bồn, mang về nuôi, đặt tên là Tiểu Bồn, bà lấy miếng ngọc đứa bé đeo bên mình đeo cho đứa con trai của mình tên là Tiểu Điệp.Thời gian trôi qua, Tiểu Bồn trở thành 1 thanh niên nhiều mưu mẹo còn Tiểu Điệp thật thà chất phác, sức khỏe hơn người. Vì muốn theo đuổi Nặc Phụng, Tiểu Bồn lên Tam Tuyệt Trang bái cha của Nặc Phụng học võ công. Trong lúc này Hạ Hầu Đôn cùng 6 đại môn phái quyết tâm tiêu diệt Ác Nhân Cốc, không ngờ 20 mấy năm sau Cốc chủ Ác Nhân Cốc chính là Mộ Dung Bạch.<br/><br/>Mộ Dung Bạch gặp nạn bị thương vô tình được Tiểu Điệp hết lòng chăm sóc. Mộ Dung Bạch cảm kích, truyền võ công lại cho Tiểu Điệp. Vì chuyện này Tiểu Điệp bị người của Tam Tuyệt Trang truy đuổi, chạy vào Ác Nhân Cốc. Tại đây Tiểu Điệp mới biết thực ra những người của Ác Nhân Cốc là người tốt, sau lưng họ đều có những quá khứ bất hạnh. Đệ Nhất Dâm Phụ Long Thiên Kiều của Ác Nhân Cốc cũng thầm để ý Tiểu Điệp.<br/><br/>Hạ Hầu Đôn vì muốn tìm ra Ác Nhân Cốc sắp đặt Tiểu Bồn &amp; Nặc Phụng trở thành phản đồ, trà trộn vào Ác Nhân Cốc, cùng 6 đại môn phái đồng loạt tập kích. Khi Tiểu Bồn &amp; Nặc Phụng biết được sự thật thì đã muộn</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 16, 1997, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Cổ Cự Cơ","avatar":""},{"name":"Phàn Thiếu Hoàng","avatar":""},{"name":"Phó Minh Hiến","avatar":""},{"name":"La Mãnh","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324538);
