INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-quang-xa-tiet', 'Xuân Quang Xạ Tiết', 'Happy Together', 'https://phimimg.com/upload/vod/20241031-1/2015d021a8e888be6aa626d35ddc2c01.jpg', 'https://phimimg.com/upload/vod/20241031-1/4d2c52601992b30c84e1dab31a51bdd6.jpg', '<p>Lê Diệu Huy (Lương Triều Vỹ) và Hà Bảo Vinh (Trương Quốc Vinh) là một đôi tình nhân đồng tính tại Hồng Kông, họ vẫn thường xuyên chia tay rồi tái hợp, và mọi lần đều do Hà Bảo Vinh chủ động. &quot;Chúng mình làm lại từ đầu đi!&quot;, đó là câu mà Hà Bảo Vinh luôn nói mỗi khi anh ta muốn bắt đầu lại mối quan hệ mà trước đó chính anh ta chủ động chấm dứt.</p>', 'Full', 1, 'single', 'completed', 7, 1997, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Lương Triều Vỹ","avatar":""},{"name":"Trương Quốc Vinh","avatar":""},{"name":"Trương Chấn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Happy Together","Chun guang zha xie","Chun gwong ja sit","Buenos Aires Affair","해피 투게더","Felizes Juntos","춘광사설","Xuân quang xạ tiết","해피투게더","Glücklich vereint","春光乍洩"]', 1784690324538);
