INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-long-bat-bo-1997', 'Thiên Long Bát Bộ 1997', 'The Demi-Gods and Semi-Devils', 'https://phimimg.com/upload/vod/20241005-1/59727cd8a7cd1e325abfcd053dcd9194.jpg', 'https://phimimg.com/upload/vod/20241005-1/ad09f95f117c2fabbf3bea4eca4fd1aa.jpg', '<p>Được đánh giá là bản chuyển thể hay nhất, sát nguyên bản nhất của tiểu thuyết Thiên Long Bát Bộ của nhà văn Kim Dung. Kiều Phong, Đoàn Dự, Hư Trúc, ba người với ba hoàn cảnh, xuất thân khác nhau, cơ duyên đã đưa họ trở thành những người bạn tri kỷ, rồi cùng kết nghĩa huynh đệ đồng sinh cộng tử. Trải qua những cuộc chiến tranh giành tình yêu, giang sơn, liệu họ có thể giải quyết êm đẹp những ân oán chốn giang hồ?</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 13, 1997, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Hạo Dân","avatar":""},{"name":"Lý Nhược Đồng","avatar":""},{"name":"Phàm Thiếu Hoàng","avatar":""},{"name":"Huỳnh Nhật Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["天龙八部 (1997)","천룡팔부","The Demi-Gods and Semi-Devils","demi.gods.and.semi.devils","Eightfold Path of the Heavenly Dragon","天龍八部"]', 1784690324538);
