INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-dem-nong-chay', 'Sau Đêm Nồng Cháy', 'After Sex', 'https://phimimg.com/upload/vod/20240910-1/7552e832701b98482fd319a1aba59e0b.jpg', 'https://phimimg.com/upload/vod/20240910-1/6e0f86e1ca245747ff65aaa715a2e516.jpg', '<p>Là một bộ phim Pháp nói về mối quan hệ tình cảm phức tạp và những cảm xúc trống rỗng sau khi yêu. Nhân vật chính Diane, một phụ nữ trung niên thành công trong sự nghiệp, có cuộc sống hôn nhân với chồng ổn định. Tuy nhiên, cô bị thu hút bởi Emilio, một chàng trai trẻ hơn, và bắt đầu một mối tình ngoài luồng đầy đam mê.</p>', 'Full', 1, 'single', 'completed', 8, 1997, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Brigitte Roüan","avatar":""},{"name":"Patrick Chesnais","avatar":""},{"name":"Boris Terral","avatar":""},{"name":"Nils Tavernier","avatar":""},{"name":"Françoise Arnoul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
