INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shin-cau-be-but-chi-cuoc-truy-duoi-vien-ngoc-hac-am', 'Shin - Cậu Bé Bút Chì: Cuộc Truy Đuổi Viên Ngọc Hắc Ám', 'Crayon Shin-chan: Pursuit of the Balls of Darkness', 'https://phimimg.com/upload/vod/20231108-1/915f3ad354834e7f8a6e36a1eacbe1c2.jpg', 'https://phimimg.com/upload/vod/20231108-1/092e97df0ce23391b2f234701b5d15a5.jpg', '<p>Gia đình nhà Nohara vô tình bị cuốn vào cuộc xung đột giữa hai gia tộc để giành lấy một viên ngọc kỳ lạ có thể hồi sinh một thực thể tà ác hùng mạnh. Do Shinnosuke đã nhặt được viên ngọc ấy, để rồi Himawari vô tình nuốt nó, gia đình Nohara phải tháo chạy khỏi gia tộc Hoàng Tuyền Ngọc đang cố hồi sinh thực thể tà ác ấy. Với sự giúp đỡ của ba anh em từ gia tộc Do Lương Ngọc và một cô thanh tra, liệu họ có thể ngăn cản thực thể tà ác đó hồi sinh và bảo vệ thế giới hay không?</p>', 'Full', 1, 'hoathinh', 'completed', 9, 1997, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Akiko Yajima","avatar":""},{"name":"Miki Narahashi","avatar":""},{"name":"Keiji Fujiwara","avatar":""},{"name":"Satomi Korogi","avatar":""},{"name":"Ako Mayama","avatar":""},{"name":"Chie Sato","avatar":""},{"name":"Daisuke Gori","avatar":""},{"name":"Fumihiko Tachiki","avatar":""},{"name":"Jun Hazumi","avatar":""},{"name":"Kaneto Shiozawa","avatar":""},{"name":"Kaoru Shimamura","avatar":""},{"name":"Keiko Yamamoto","avatar":""},{"name":"Mari Mashiba","avatar":""},{"name":"Masayuki Nakata","avatar":""},{"name":"Michie Tomizawa","avatar":""},{"name":"Teiyu Ichiryusai","avatar":""},{"name":"Minami Taka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324538);
