INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-phieu-luu-cua-gia-dinh-ti-hon', 'Cuộc Phiêu Lưu Của Gia Đình Tí Hon', 'The Borrowers', 'https://phimimg.com/upload/vod/20240906-1/a08259918c55b3e338dc36e6ec6f8dab.jpg', 'https://phimimg.com/upload/vod/20240906-1/d19011d0a5457695254ff9cc9fdbd5f0.jpg', '<p>Gia đình Clock cao 4 inch bí mật ở chung nhà với gia đình Lender có kích thước bình thường, “mượn” những món đồ như chỉ, kim băng, pin và thức ăn thừa. Tuy nhiên, sự chung sống hòa bình của họ bị xáo trộn khi luật sư độc ác Ocious P. Potter đánh cắp di chúc cấp quyền sở hữu ngôi nhà mà anh ta định phá bỏ để xây chung cư. Người cho vay buộc phải di chuyển và Đồng hồ phải đối mặt với nguy cơ bị tiếp xúc với thế giới có kích thước bình thường.</p>', 'Full', 1, 'single', 'completed', 9, 1997, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"John Goodman","avatar":""},{"name":"Mark Williams","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Celia Imrie","avatar":""},{"name":"Flora Newbigin","avatar":""},{"name":"Tom Felton","avatar":""},{"name":"Raymond Pickard","avatar":""},{"name":"Bradley Pierce","avatar":""},{"name":"Aden Gillett","avatar":""},{"name":"Doon Mackichan","avatar":""},{"name":"Hugh Laurie","avatar":""},{"name":"Ruby Wax","avatar":""},{"name":"Andrew Dunford","avatar":""},{"name":"Bob Goody","avatar":""},{"name":"Patrick Monckton","avatar":""},{"name":"Dick Ward","avatar":""},{"name":"George Antoni","avatar":""},{"name":"Alex Winter","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a