INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-tieu-phan-1', 'Bảo Tiêu (Phần 1)', 'Bodyguards: Jade Dolls', 'https://phimimg.com/upload/vod/20240625-1/ee2a4166d3143c8c5985251cbe53b8fb.jpg', 'https://phimimg.com/upload/vod/20240625-1/43a85b172d2c2787be62a0cb609d0679.jpg', '<p><em>Bảo Tiêu - Võ Lâm Bảo Ngọc chứa đựng tuyệt học võ công tái xuất giang hồ, tạo nên một trận ác chiến tranh đoạt. Vì muốn mượn y học bảo điển được ghi chép trong Búp Bê Phỉ Thúy để chửa trị cho Ngũ thiếu gia của Vân Gia Trang, thiếu chủ Quách Húc của Trường Phong tiêu cục nhận mạo hiểm, cùng Tân Lực, Phong Bình và hai huynh muội Trình Thiết Y, Trình Thái Ngọc vận chuyển Búp Bê Phỉ Thúy đến Vân gia trang. Trên đường bảo tiêu, họ gặp phải Ông Thái Bắc chỉ huy Cẩm y vệ, các danh môn chính phái Thiếu Lâm, Hoa Sơn, Thanh Thành và các thế lực tà ác tấn công nhằm chiếm đoạt Búp Bê Phỉ Thúy. Điều khiến công việc càng trở nên khó khăn thêm nữa là người yêu của chàng cũng đứng trong hàng ngũ tranh đoạt. Liệu chàng thiếu hiệp phong lưu đa tình đa nghĩa Quách Húc có thể hoàn thành chuyến bảo tiêu này không? Hay bảo vật sẽ rơi vào tay ai?</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 1997, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Gia Kính","avatar":""},{"name":"Diệp Đồng","avatar":""},{"name":"Trịnh Hào Nam","avatar":""},{"name":"Lý Uyển Hoa","avatar":""},{"name":"Cố Quán Trung","avatar":""},{"name":"Lưu Ngọc Đình","avatar":""},{"name":"Trần Hồng Liệt","avatar":""},{"name":"Thẩm Mạnh Sinh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
