INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-1-qua-bom-choc-troi', 'Thám Tử Lừng Danh Conan 1: Quả Bom Chọc Trời', 'Detective Conan: The Time Bombed Skyscraper', 'https://phimimg.com/upload/vod/20231019-1/10ba75b718b27fded8f14430aee7ac0a.jpg', 'https://phimimg.com/upload/vod/20231019-1/d2e2c4cd6d19ccc793cf1cfb004aa894.jpg', '<p>Trong tập phim này, Shinichi nhận lời mời dự tiệc từ kiến trúc sư Teiji Moriya, người không hề biết cậu đã bị thu nhỏ thành Conan. Cùng lúc đó, một kẻ lạ mặt gọi điện thách thức cậu tìm ra những quả bom đang được đặt xung quanh Tokyo. Hai sự kiện này liệu có liên quan đến nhau? Mọi việc càng trở nên nghiêm trọng khi Ran bị mắc kẹt tại một trong những tòa nhà đã bị đặt bom. Liệu Conan có tìm ra hung thủ và cứu cô bạn mình khỏi khoảnh khắc sinh tử?</p>', 'Full', 1, 'hoathinh', 'completed', 13, 1997, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Tarō Ishida","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Naoko Matsui","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Kaneto Shiozawa","avatar":""},{"name":"Meidai Nomura","avatar":""},{"name":"Ako Mayama","avatar":""},{"name":"Kazuhiro Yamaji","avatar":""},{"name":"Kazuya Ichijo","avatar":""},{"name":"Tomoko Miyadera","avatar":""},{"name":"Yuji","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324538);
