INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-trung-hoc-kindaichi-truyen-thuyet-nang-tien-ca-thuong-hai', 'Thám tử trung học Kindaichi: Truyền thuyết nàng tiên cá Thượng Hải', 'The Files of Young Kindaichi: Legend of the Shanghai Mermaid', 'https://phimimg.com/upload/vod/20240726-1/74f668b9d0d5e1afdfc0a005e0a9c54d.jpg', 'https://phimimg.com/upload/vod/20240726-1/4c2b9a4a5362d771f96f4cf1efecf326.jpg', '<p>&quot;Kindaichi Shonen no Jikenbo: Shanghai Ningyo Densetsu&quot; theo chân thám tử học sinh Kindaichi Hajime trong một chuyến đi đến Thượng Hải. Tại đây, cha của một người bạn Trung Quốc của Kindaichi bị sát hại tại rạp xiếc. Khi điều tra vụ án, Kindaichi phải đối mặt với những bí ẩn liên quan đến truyền thuyết về nhân ngư Thượng Hải đã tồn tại 4000 năm. Những sự kiện kỳ bí và ly kỳ xung quanh truyền thuyết này đưa Kindaichi vào một hành trình đầy thách thức để tìm ra sự thật và vén màn bí ẩn của vụ án mạng.</p>', 'Full', 1, 'single', 'completed', 9, 1997, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tsuyoshi Domoto","avatar":""},{"name":"ともさかりえ","avatar":""},{"name":"Masato Furuoya","avatar":""},{"name":"Tomohiro Hara","avatar":""},{"name":"Mizuki Sano","avatar":""},{"name":"水川あさみ","avatar":""},{"name":"Chen Chi-Chiang","avatar":""},{"name":"Akira Nakao","avatar":""},{"name":"Ada Mauro","avatar":""},{"name":"Makiko Sanuki","avatar":""},{"name":"橋本さとし","avatar":""},{"name":"Xiu Jian","avatar":""},{"name":"Suirei","avatar":""},{"name":"Pepe Hozumi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
