INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-trung-hoc-kindaichi-truyen-thuyet-nang-tien-ca-thuong-hai', 'Thám tử trung học Kindaichi: Truyền thuyết nàng tiên cá Thượng Hải', 'The Files of Young Kindaichi: Legend of the Shanghai Mermaid', 'thám tử trung học kindaichi: truyền thuyết nàng tiên cá thượng hải the files of young kindaichi: legend of the shanghai mermaid tsuyoshi domoto ともさかりえ masato furuoya tomohiro hara mizuki sano 水川あさみ chen chi-chiang akira nakao ada mauro makiko sanuki 橋本さとし xiu jian suirei pepe hozumi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-hoa-than-kiem', 'Tuyết Hoa Thần Kiếm', 'The Snow Is Red', 'https://phimimg.com/upload/vod/20240724-1/b62899a73d4b60d2f6dff5cd9fa70a34.jpg', 'https://phimimg.com/upload/vod/20240724-1/24bcb5af6937132b328da945cba18810.jpg', '<p><em>Vào cuối thời Nam Tống, thiên hạ nhiễu nhương vì sự tranh giành trục lợi của chánh tà hai phái. Tất cả đều bắt nguồn từ việc muốn làm chủ tấm bản đồ tiềm tàng nhiều thánh vật. Lòng tham lam, sự hung tàn đã tạo nên bao phong ba bão táp khiến cho bao người vô tội phải tắm trong bể máu, bao kẻ hiền lương phải thịt nát xương tan vì mưu đồ của những kẻ cuồng vọng. Chồng thù vợ, cha nghịch con, em giết anh, trò phản bội thầy. Luân lý xã hội bị thay thế bằng những thủ đoạn tàn bạo, những trò bán rẻ lương tâm. Vì an nguy của cả võ lâm, các bang phái trên giang hồ quyết tâm truy sát Nhiếp Mỵ Nương – một nữ ma đầu có võ công cái thế ôm mộng khôi phục Thánh Giáo…. Cái chết thương tâm của Nhiếp Mỵ Nương đã khiến cho Nhiếp Tiểu Phụng- đứa con gái duy nhất của ả, cũng là tàn dư cuối cùng của Thánh Giáo khắc cốt một mối thâm thù. Mười sáu năm sau, với tất cả những ân, oán, tình, thù, Tiểu Phụng đã khiến giang hồ một lần nữa chìm trong biển máu với những cuộc tàn sát vô cùng thảm khốc…</em></p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 24, 1997, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Mễ Tuyết","avatar":""},{"name":"Khương Đại Vệ","avatar":""},{"name":"Dương Cung Như","avatar":""},{"name":"Trần Vĩ","avatar":""},{"name":"Viên Văn Kiệt","avatar":""},{"name":"Cung Từ Ân","avatar":""},{"name":"Từ Thiếu Cường","avatar":""},{"name":"Chân Chí Cường","avatar":""},{"name":"Cao Hùng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324538);
