INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-nguoi-dien-loan', 'Kẻ Săn Người Điên Loạn', 'The Peeping Tom', 'https://phimimg.com/upload/vod/20240228-1/fa0baf28bd95880ed976fc80bf296ad7.jpg', 'https://phimimg.com/upload/vod/20240228-1/c1ad6c7214b5a1dbf24a10efaf830b62.jpg', '<p>Một tên biến thái có sở thích quái đản, đó là đôi chân của phụ nữ, chuyên bắt cóc, hãm hiếp và hành hạ đàn bà, đặc biệt thích thú với các trò nghịch ngợm chân. Một lần phạm tội, bị cảnh sát truy đuổi, tình cờ hắn khám phá ra người nữ đội trưởng cảnh sát có đôi chân tuyệt vời. Hắn lén đi theo dõi và xác định, cô ta và gia đình sẽ là những nạn nhên tiếp theo...</p>', 'Full', 1, 'single', 'completed', 11, 1997, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jade Leung","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Miho Nomoto","avatar":""},{"name":"Sara Au","avatar":""},{"name":"Simon Cheung Yuk-San","avatar":""},{"name":"Lee Kin-Yan","avatar":""},{"name":"Lo Hung","avatar":""},{"name":"Rachel Tucker","avatar":""},{"name":"Sin-Yi Yip","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324538);
