INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-sieu-hang', 'Điệp Viên Siêu Hạng', 'The Man Who Knew Too Little', 'https://phimimg.com/upload/vod/20240227-1/272d9dacb76b1f38c07afe63c78a6b40.jpg', 'https://phimimg.com/upload/vod/20240227-1/1dbd1c106388ec04f8c13553ae609114.jpg', '<p>Một người Mỹ nhận được vé tham gia trò chơi có sự tham gia của khán giả ở London, sau đó vướng vào một vụ nhầm lẫn danh tính. Khi một âm mưu quốc tế làm sáng tỏ xung quanh anh ta, anh ta nghĩ rằng đó là một phần của hành động.</p>', 'Full', 1, 'single', 'completed', 12, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Murray","avatar":""},{"name":"Peter Gallagher","avatar":""},{"name":"Joanne Whalley","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Richard Wilson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324538);
