INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-doi-hoan-hao', 'Bộ Đôi Hoàn Hảo', 'Double Team', 'https://phimimg.com/upload/vod/20240205-1/529947ab1a8ed94ba45f4d37e54adf6a.jpg', 'https://phimimg.com/upload/vod/20240205-1/7eccf27d931a677f50ac7ffbe094f33b.jpg', '<p>Một đặc vụ CIA bị thực tập vì không giết được một tên khủng bố quốc tế. Trốn thoát khỏi hòn đảo bị lưu đày, anh lập nhóm với một tay buôn vũ khí hào hoa và lên đường truy tìm tên khủng bố và giải cứu gia đình tên đặc vụ. Cùng với nhau, họ là một kho vũ khí dành cho hai người... với đủ điện áp để làm rung chuyển thế giới tự do.</p>', 'Full', 1, 'single', 'completed', 14, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Dennis Rodman","avatar":""},{"name":"Mickey Rourke","avatar":""},{"name":"Paul Freeman","avatar":""},{"name":"Natacha Lindinger","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324538);
