INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-loi', 'Lạc Lối', 'Lost Highway', 'https://phimimg.com/upload/vod/20240227-1/fa490d3c02696ada38f42dfe8880cd57.jpg', 'https://phimimg.com/upload/vod/20240227-1/110f7d5b5373644b244ca54f8584c64f.jpg', '<p>Cuộc đời của nghệ sĩ saxophone đã bị thay đổi bất ngờ khi ông bị nghi ngờ là thủ phạm gây ra cái chết của vợ mình. Vào tù, ông chấp nhận cuộc sống mới và tìm cách thích nghi với hoàn cảnh. Tuy nhiên, mọi việc không đơn giản như ông nghĩ...</p>', 'Full', 1, 'single', 'completed', 11, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Pullman","avatar":""},{"name":"Patricia Arquette","avatar":""},{"name":"John Roselius","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324538);
