INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('che-giau-su-that', 'Che Giấu Sự Thật', 'Contact', 'https://phimimg.com/upload/vod/20240205-1/4ce3bf975637425341a3e45c1286196f.jpg', 'https://phimimg.com/upload/vod/20240205-1/a26f3cd1c35bdebc6ae3d14037b56915.jpg', '<p>Nhà thiên văn học tiến sĩ Ellie Arroway từ lâu đã quan tâm đến những vùng đất xa xôi xúc, một tình yêu nuôi dưỡng trong thời thơ ấu của cha mình, Ted Arroway, người đã qua đời khi cô chín tuổi để lại của cô sau đó mồ côi. Công việc hiện tại của mình trong việc giám sát cho cuộc sống ngoài trái đất dựa trên tình yêu và là một phần trong một sự kính trọng cha mình. Kể từ nguồn tài trợ từ Quỹ Khoa học Quốc gia (NSF) đã được kéo vào công việc của mình, được gọi một số người, bao gồm cả cao NSF cô David Drumlin, như nhiều khoa học viễn tưởng khoa học hơn, Ellie, với một vài đồng nghiệp của nhà khoa học giả mạo của mình, đã xem xét tài trợ từ có bao giờ họ có thể có được nó để tiếp tục công việc của họ.</p>', 'Full', 1, 'single', 'completed', 11, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jena Malone","avatar":""},{"name":"David Morse","avatar":""},{"name":"Jodie Foster","avatar":""},{"name":"Geoffrey Blake","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Sami Chester","avatar":""},{"name":"Timothy McNeil","avatar":""},{"name":"Laura Elena Surillo","avatar":""},{"name":"Matthew McConaughey","avatar":""},{"name":"Tom Skerritt","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324538);
