INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('go-cua-thien-dang', 'Gõ Cửa Thiên Đàng', 'Knockin'' On Heaven''s Door', 'https://phimimg.com/upload/vod/20240128-1/a458a15f3177b31fdfbc79c0c5826ed3.jpg', 'https://phimimg.com/upload/vod/20240128-1/deb23870d63b4ad66d16e722f547febd.jpg', '<p>Chàng trai hiền lành Rudi bị bệnh ung thư xương. Tại phòng chờ chết của bệnh viện, Rudi được xếp ở cùng phòng với anh chàng ngổ ngáo Martin (Til Schweiger thủ vai). Martin cũng mới bị phát hiện có một khối u trong não, chỉ còn sống được vài ngày. Hai kẻ sắp chết quyết định trốn khỏi bệnh viện. Họ muốn ra biển, vì họ chưa bao giờ đến biển. Martin và Rudi ăn cắp một chiếc Mercedes để dưới garage của bệnh viện và bỏ trốn. Đây là chiếc xe của hai tên gangster Hank và Abdul. Hai tên này có nhiệm vụ giao chiếc xe cho ông trùm mafia Curtiz. Khi mở cốp xe, Martin và Rudi phát hiện một chiếc cặp đựng 1 triệu Mark. Hai người rơi vào một hoàn cảnh bi hài: lần đầu tiên trong đời, họ trở thành những người giàu nhưng lại chỉ có vài ngày để sống. Hơn thế, cuộc sống ngắn ngủi của họ lại liên tục bị đe dọa vì bị cả cảnh sát lẫn mafia đuổi bắt...</p>', 'Full', 1, 'single', 'completed', 13, 1997, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Til Schweiger","avatar":""},{"name":"Jan Josef Liefers","avatar":""},{"name":"Thierry van Werveke","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324538);
