INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-mat', 'Trở Mặt', 'U Turn', 'https://phimimg.com/upload/vod/20240128-1/95e1ccc0832c5728dd1788a84d65f277.jpg', 'https://phimimg.com/upload/vod/20240128-1/5310c38fcd1b060b1bc5d5210f66cc24.jpg', '<p>Khi xe của Bobby bị hỏng trong sa mạc khi đang chạy trốn khỏi một số nhà cái đã lấy hai ngón tay của anh ấy, anh ấy bị mắc kẹt trong thị trấn nhỏ gần đó, nơi mọi người xa lạ hơn bất kỳ ai mà anh ấy gặp. Sau khi có quan hệ với một phụ nữ trẻ đã có gia đình, chồng cô đã thuê Bobby giết cô. Sau đó, cô thuê Bobby để giết người chồng.</p>', 'Full', 1, 'single', 'completed', 11, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Penn","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Jennifer Lopez","avatar":""},{"name":"Joaquin Phoenix","avatar":""},{"name":"Claire Danes","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324538);
