INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gioi-han-cuoc-song', 'Giới Hạn Cuộc Sống', 'The Edge', 'https://phimimg.com/upload/vod/20240205-1/2d56a387e645cd78ba06270b48e5227c.jpg', 'https://phimimg.com/upload/vod/20240205-1/e6bc2ccb0e810ecd3b3d024d13de0e15.jpg', '<p>Câu chuyện nói về chuyến đi của nhà tỷ phú mọt sách Charles Morse (Anthony Hopkins) hộ tống cô vợ người mẫu Mickey (Elle Macpherson) đến Alaska để chụp ảnh. Cả đoàn chỉ có 4 người là 2 vợ chồng Charles và thợ chụp ảnh Robert Green (Alec Baldwin) cùng thư ký của anh ta là Stephen (Harold Perrineau). Mọi chuyện bắt đầu phức tạp khi chiếc máy bay nổ tung trên hồ, cả 4 người bắt đầu phải nghĩ cách sống sót giữa Alaska lạnh giá mù tuyết. Stephen là người bỏ mạng đầu tiên vì 1 con gấu hoang, sau đó lần lượt nội bộ xích mích khi Charles nghi ngờ Robert định giết mình đề thực hiện chuyện yêu đương của hắn ta với Mickey.</p>', 'Full', 1, 'single', 'completed', 13, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anthony Hopkins","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Elle Macpherson","avatar":""},{"name":"Harold Perrineau","avatar":""},{"name":"L.Q. Jones","avatar":""},{"name":"Kathleen Wilhoite","avatar":""},{"name":"Mark Kiely","avatar":""},{"name":"Eli Gabay","avatar":""},{"name":"Larry Musser","avatar":""},{"name":"Brian Arnold","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
