INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-ban-linh-hon-cho-dia-nguc', 'Kẻ Bán Linh Hồn Cho Địa Ngục', 'Spawn', 'https://phimimg.com/upload/vod/20240104-1/ca8b92eb88b87053ecad6a8ff8e40c31.jpg', 'https://phimimg.com/upload/vod/20240104-1/72d56a517c08261cad6d1f89c21a78af.jpg', '<p>Sau khi bị sát hại bởi những đồng nghiệp tham nhũng trong một cơ quan bí mật của chính phủ, Al Simmons đã lập một thỏa thuận với ác quỷ để được hồi sinh để gặp người vợ yêu dấu Wanda. Để đổi lấy việc trở lại Trái đất, Simmons đồng ý lãnh đạo Đội quân Địa ngục trong việc tiêu diệt loài người.</p>', 'Full', 1, 'single', 'completed', 16, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Jai White","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Theresa Randle","avatar":""},{"name":"Nicol Williamson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324538);
