INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hero', 'Hero', 'Hero', 'https://phimimg.com/upload/vod/20240102-1/cf6ee0b140f65e1203f20734ab920afc.jpg', 'https://phimimg.com/upload/vod/20240102-1/9967312b22c3f443f9e8c194813a30b8.jpg', '<p>Ma Wing Jing và anh trai Ma Tai Chueng đến Thượng Hải để kiếm tiền vào cuối triều đại nhà Tần. Kết bạn với một tên cướp quyền lực Wing Jing được trao hộp đêm của anh ta để đổi lấy việc cứu mạng Tam Sei. Thật không may, một Gangster khác muốn có một cái giếng trên lãnh thổ. Tham nhũng và bạo lực thống trị đường phố khi Wing Jing và Tam Sei phải chiến đấu không chỉ với các băng nhóm đối thủ mà còn cả các quan chức cảnh sát tham nhũng.</p>', 'Full', 1, 'single', 'completed', 12, 1997, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Takeshi Kaneshiro","avatar":""},{"name":"Biao Yuen","avatar":""},{"name":"Jessica Hester Hsuan","avatar":""},{"name":"Wah Yuen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324538);
