INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-bat-trum-mafia', 'Truy Bắt Trùm Mafia', 'Donnie Brasco', 'https://phimimg.com/upload/vod/20231231-1/22d4eca2e2cfc40dd842340b3ada1c5f.jpg', 'https://phimimg.com/upload/vod/20231231-1/68a79e09967a5dacc1ae40e43bdf236d.jpg', '<p>Bộ phim kể về nhiệm vụ bí mật có thật của mật vụ FBI Joe Pistone với danh tính khi giả danh tên trộm kim hoàn nhằm thâm nhập vào sào huyệt của tổ chức mafia là Donnie Brasco. Mất gần 10 năm nằm vùng trong hang ổ của tổ chức mafia khét tiếng nhất thành phố New York, cuối cùng Donnie cũng có được danh tính đầy đủ của 120 tên tội phạm và đưa chúng đến với bản án chung thân.</p>', 'Full', 1, 'single', 'completed', 12, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Al Pacino","avatar":""},{"name":"Johnny Depp","avatar":""},{"name":"Michael Madsen","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324538);
