INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-to-khong-trung', 'Bão Tố Không Trung', 'Turbulence', 'https://phimimg.com/upload/vod/20231219-1/4364d8ff56112d8c29b379953299eb85.jpg', 'https://phimimg.com/upload/vod/20231219-1/072496482a17bedb1f71bdce79ed09ca.jpg', '<p>Trên một chuyến bay vận chuyển những kẻ bị kết án nguy hiểm, kẻ sát nhân Ryan Weaver đã trốn thoát và gây ra sự hỗn loạn hoàn toàn trên máy bay. Khi nhiều người trên máy bay trở thành nạn nhân của Weaver, tiếp viên hàng không Teri Halloran cuối cùng phải giữ cho máy bay không bị rơi, với sự hỗ trợ trên mặt đất từ một kiểm soát viên không lưu. Trong khi Halloran vật lộn để điều khiển chiếc máy bay, Weaver tiếp tục khủng bố những thành viên còn sống sót của phi hành đoàn.</p>', 'Full', 1, 'single', 'completed', 11, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ray Liotta","avatar":""},{"name":"Lauren Holly","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"Hector Elizondo","avatar":""},{"name":"Rachel Ticotin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324538);
