INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-chuc', 'Thánh Chức', 'Cure', 'https://phimimg.com/upload/vod/20231219-1/991700d5abda5c8e7c28cde1df16b291.jpg', 'https://phimimg.com/upload/vod/20231219-1/f7afd4bc671f8d49982c2bc5f848bed6.jpg', '<p>Một làn sóng giết người hàng loạt quét qua Tokyo. Cảnh sát không tìm được bất cứ manh mối nào ngoài dấu hiệu đẫm máu là chữ X hung thủ để lại trên cổ mỗi nạn nhân. Thám tử Takabe và nhà tâm lý học Sakuma bắt đầu vào cuộc để phân tích ý nghĩa của dấu hiệu đó, nhưng mọi manh mối điều tra vẫn đi vào ngõ cụt. Cùng lúc đó, một người thanh niên lạ mặt bị bắt gặp ở gần hiện trường vụ án mạng mới nhất. Thám tử Takabe bắt đầu hàng loạt cuộc thẩm vấn để xác định mối liên hệ giữa người thanh niên này và các vụ án mạng...</p>', 'Full', 1, 'single', 'completed', 20, 1997, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Koji Yakusho","avatar":""},{"name":"Masato Hagiwara","avatar":""},{"name":"Tsuyoshi Ujiki","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324538);
