INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-lua', 'Ánh Lửa', 'Firelight', 'https://phimimg.com/upload/vod/20231211-1/b2297860c9f923b8368364e322494b4b.jpg', 'https://phimimg.com/upload/vod/20231211-1/d03d58d4fd477060742752619ab31645.jpg', '<p>Năm 1838, cô gia sư đáng yêu Elisabeth đồng ý sinh con cho một chủ đất người Anh giấu tên, và đổi lại anh ta sẽ trả món nợ cho cha cô. Khi sinh, cô ấy, theo thỏa thuận, từ bỏ đứa trẻ. Bảy năm sau, cô được thuê làm gia sư cho một cô gái ở khu đất Sussex xa xôi. Cha của cô gái, Charles Godwin, hóa ra lại là một chủ đất ẩn danh. Vì vậy, Elisabeth phải làm gia sư cho con gái riêng của cô ấy và cô ấy không thể tiết lộ bí mật về mối quan hệ của mình với cô bé Louisa.</p>', 'Full', 1, 'single', 'completed', 18, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sophie Marceau","avatar":""},{"name":"Stephen Dillane","avatar":""},{"name":"Dominique Belcourt","avatar":""},{"name":"Kevin Anderson","avatar":""},{"name":"Joss Ackland","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
