INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-su-tai-ba', 'Luật Sư Tài Ba', 'The Rainmaker', 'https://phimimg.com/upload/vod/20231209-1/18b9277139505a743fb198e952843f74.jpg', 'https://phimimg.com/upload/vod/20231209-1/160512632febd172a4916a6fb15be91a.jpg', '<p>Luật sư Rudy Baylor kiện công ty bảo hiểm Great Benefits để đòi lại công lý cho một người chết. Trong cuộc chiến pháp lý cam go, anh phải đối đầu với một nhóm luật sư giỏi chuyên môn nhưng thiếu cái tâm trong nghề.</p>', 'Full', 1, 'single', 'completed', 12, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"Jon Voight","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324538);
