INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cube', 'Cube', 'Cube', 'https://phimimg.com/upload/vod/20231209-1/428d69547d2f2f0e4108bc25f82a5c3b.jpg', 'https://phimimg.com/upload/vod/20231209-1/e4cd70324df1fe7d3c8cd1f6bbb5d7a7.jpg', '<p>Sáu người khác nhau, mỗi người từ một cuộc sống rất khác nhau, thức tỉnh để thấy mình trong một khối khổng lồ với hàng ngàn căn phòng có thể. Mỗi người có một kỹ năng trở nên rõ ràng khi họ phải ban nhạc cùng nhau để thoát ra: một cảnh sát, một người dạy toán, một nhà thiết kế tòa nhà, một bác sĩ, một người trốn thoát, và một người đàn ông tàn tật. Mỗi người đóng một phần trong nhiệm vụ ly kỳ của họ để tìm câu trả lời về lý do tại sao họ bị cầm tù</p>', 'Full', 1, 'single', 'completed', 12, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324538);
