INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-chat-toi-ac', 'Bản Chất Tội Ác', 'The Devil''s Own', 'https://phimimg.com/upload/vod/20231207-1/7240d619adbdb803b1be711901813ccb.jpg', 'https://phimimg.com/upload/vod/20231207-1/8ea0d93c7b12f05a7a98b5c45b5cd290.jpg', '<p>Frankie McGuire, một trong những sát thủ nguy hiểm nhất của IRA, lôi kéo một gia đình người Mỹ vào làn đạn khủng bố. Nhưng khi được gửi đến Hoa Kỳ để mua vũ khí, Frankie được ở cùng gia đình Tom OMeara, một cảnh sát New York, người không biết gì về danh tính thực sự của Frankie. Tình bạn đáng ngạc nhiên của họ, và sự nghi ngờ ngày càng tăng của Tom, buộc Frankie phải lựa chọn giữa lời hứa về hòa bình hoặc cả cuộc đời giết người.</p>', 'Full', 1, 'single', 'completed', 11, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Rubén Blades","avatar":""},{"name":"Treat Williams","avatar":""},{"name":"Natascha McElhone","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324538);
