INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-quyen-ru-vinh-cuu', 'Sự Quyến Rũ Vĩnh Cửu', 'Anna Karenina', 'https://phimimg.com/upload/vod/20231204-1/5ec18b623301d7e3d0036fcc44e7f683.jpg', 'https://phimimg.com/upload/vod/20231204-1/bf9ddfb8bac1743ff26410985446d9d3.jpg', '<p>Anna Karenina, vợ của một bộ trưởng hoàng gia Nga, tạo ra một vụ bê bối trong xã hội thượng lưu bằng cách ngoại tình với Bá tước Vronsky, một sĩ quan kỵ binh bảnh bao ở St. Petersburg thế kỷ 19.</p>', 'Full', 1, 'single', 'completed', 14, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sophie Marceau","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Mia Kirshner","avatar":""},{"name":"James Fox","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
