INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-den-the-ma-thoi', 'Chỉ Đến Thế Mà Thôi', 'As Good as It Gets', 'https://phimimg.com/upload/vod/20231130-1/6a5df5134c1e8c9a288c91231d33219e.jpg', 'https://phimimg.com/upload/vod/20231130-1/5c70b240a646e645acc06cc016f926dd.jpg', '<p>Melvin Udall, một nhà văn viết tiểu thuyết lãng mạn cáu kỉnh, cố chấp, ám ảnh cưỡng chế, thô lỗ với tất cả những người anh gặp, kể cả người hàng xóm đồng tính của anh, Simon. Sau khi Simon nhập viện, Melvin thấy cuộc sống của mình bị đảo lộn khi phải chăm sóc chú chó của Simon. Ngoài ra, Carol, nhân viên phục vụ duy nhất tại quán ăn địa phương chịu đựng anh, phải nghỉ việc để chăm sóc cậu con trai ốm yếu, khiến Melvin không thể ăn sáng.</p>', 'Full', 1, 'single', 'completed', 14, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Nicholson","avatar":""},{"name":"Helen Hunt","avatar":""},{"name":"Greg Kinnear","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Shirley Knight","avatar":""},{"name":"Jesse James","avatar":""},{"name":"Yeardley Smith","avatar":""},{"name":"Lupe Ontiveros","avatar":""},{"name":"Skeet Ulrich","avatar":""},{"name":"Harold Ramis","avatar":""},{"name":"Bibi Osterwald","avatar":""},{"name":"Ross Bleckner","avatar":""},{"name":"Bernadette Balagtas","avatar":""},{"name":"Jaffe Cohen","avatar":""},{"name":"Laurie Kilpatrick","avatar":""},{"name":"Alice Vaughn","avatar":""},{"name":"Brian Do","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324538);
