INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('night-vision', 'Night Vision', 'Night Vision', 'https://phimimg.com/upload/vod/20231129-1/e7f3f0bbc1511ef96276d363c600446a.jpg', 'https://phimimg.com/upload/vod/20231129-1/dcf21852fec50eccb159e7fe5a9e3106.jpg', '<p>Một kẻ tâm thần giết người hàng loạt chuyên ghi lại từng cuộc chinh phục đẫm máu của hắn đang bị thả rông, và nhiệm vụ của anh là cảnh sát mô tô nghiện rượu Dak và đối tác cứng rắn mới của hắn, Kristen, phải đưa hắn ra trước công lý. Nhưng khi số lượng cơ thể tăng lên, mối nguy hiểm cũng tăng theo.</p>', 'Full', 1, 'single', 'completed', 12, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fred Williamson","avatar":""},{"name":"Cynthia Rothrock","avatar":""},{"name":"Robert Forster","avatar":""},{"name":"Frank Pesce","avatar":""},{"name":"Amanda Welles","avatar":""},{"name":"Willie Gault","avatar":""},{"name":"Bushwick Bill","avatar":""},{"name":"Rodger Boyce","avatar":""},{"name":"Cliff Stephens","avatar":""},{"name":"Willie Minor","avatar":""},{"name":"Nina Richardson","avatar":""},{"name":"Robert Prentiss","avatar":""},{"name":"Jonathan Hayes","avatar":""},{"name":"Akin Babatunde","avatar":""},{"name":"Mary Kapper","avatar":""},{"name":"Robin McGee","avatar":""},{"name":"Phyllis Cic","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324538);
