INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-ngay-mai-khong-tan-lui', 'Điệp Viên 007: Ngày Mai Không Tàn Lụi', 'Tomorrow Never Dies', 'https://phimimg.com/upload/vod/20231129-1/15d1a9e122f7dbf54acb6361790d6b75.jpg', 'https://phimimg.com/upload/vod/20231129-1/ff1cc85be4524f19fe3f15e37cffafa9.jpg', '<p>Kẻ ngông cuồng Elliot Carver (Jonathan Pryce) muốn phát động chiến tranh trở lại trở thành chiến tranh thế giới thứ 3. Đầu tiên hắn đánh lừa một tàu chiến của Anh đi vào vùng biển của Trung Quốc trong khi họ vẫn tưởng nhầm đang ở trong vùng biển quốc tế, sau đó hắn đánh chìm tàu chiến của Anh đồng thời bắn rơi một máy bay chiến đấu của Trung Quốc, tiếp theo là một loạt các âm mưu khác. Tất cả những hành động đó phục vụ cho mục đích kiếm tiền bằng công ty truyền thông, báo chí, tin tức của hắn! Và James Bond (Pierce Brosnan) người hùng có nhiệm vụ ngăn chặn hành động ấy...</p>', 'Full', 1, 'single', 'completed', 15, 1997, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Teri Hatcher","avatar":""},{"name":"Joe Don Baker","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Ricky Jay","avatar":""},{"name":"Desmond Llewelyn","avatar":""},{"name":"Götz Otto","avatar":""},{"name":"Samantha Bond","avatar":""},{"name":"Vincent Schiavelli","avatar":""},{"name":"Colin Salmon","avatar":""},{"name":"Geoffrey Palmer","avatar":""},{"name":"Julian Fellowes","avatar":""},{"name":"Terence Rigby","avatar":""},{"name":"Nina Young","avatar":""},{"name":"Daphne Deckers","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b