INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-cua-jackie', 'Kế Hoạch Của Jackie', 'Jackie Brown', 'https://phimimg.com/upload/vod/20231129-1/2ce32dbaa319c0a6287e76b451d104dd.jpg', 'https://phimimg.com/upload/vod/20231129-1/b3fbaeece912fce6f52f57551a39f824.jpg', '<p>Jackie Brown là một tiếp viên hàng không bị bắt quả tang đang buôn lậu tiền mặt vào đất nước cho ông chủ tay súng của cô. Khi cảnh sát cố gắng lợi dụng Jackie để tiếp cận ông chủ của cô ấy, cô ấy đã ấp ủ một kế hoạch — với sự giúp đỡ của một người bảo lãnh tại ngoại — để giữ tiền cho riêng mình.</p>', 'Full', 1, 'single', 'completed', 15, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pam Grier","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Bridget Fonda","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Robert Forster","avatar":""},{"name":"Michael Bowen","avatar":""},{"name":"Chris Tucker","avatar":""},{"name":"LisaGay Hamilton","avatar":""},{"name":"Tommy Lister Jr.","avatar":""},{"name":"Hattie Winston","avatar":""},{"name":"Sid Haig","avatar":""},{"name":"Aimee Graham","avatar":""},{"name":"Ellis E. Williams","avatar":""},{"name":"Tangie Ambrose","avatar":""},{"name":"T''Keyah Crystal K","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324538);
