INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-chien-binh-qua-cam', 'Nữ chiến binh quả cảm', 'G.I. Jane', 'https://phimimg.com/upload/vod/20231123-1/480360b09ec09cb0f8e96d409891d254.jpg', 'https://phimimg.com/upload/vod/20231123-1/e9f215aa34049e86d073e989b7427163.jpg', '<p>Để đối phó với áp lực chính trị từ Thượng nghị sĩ Lillian DeHaven, Hải quân Hoa Kỳ bắt đầu một chương trình cho phép sự hội nhập cuối cùng của phụ nữ vào các dịch vụ của mình. Chương trình bắt đầu với một ứng cử viên thử nghiệm duy nhất, Trung úy Jordan O&#39;Neil, người được chọn đặc biệt vì sự nữ tính của cô ấy. O&#39;Neil tham gia chương trình đào tạo khắc nghiệt dưới sự chỉ huy của Master Chief John James Urgayle, người đã đẩy O&#39;Neil một cách bất công cho đến khi quyết tâm của cô giành được sự tôn trọng của anh ta.</p>', 'Full', 1, 'single', 'completed', 14, 1997, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Demi Moore","avatar":""},{"name":"Viggo Mortensen","avatar":""},{"name":"Morris Chestnut","avatar":""},{"name":"Josh Hopkins","avatar":""},{"name":"David Vadim","avatar":""},{"name":"Jim Caviezel","avatar":""},{"name":"Boyd Kestner","avatar":""},{"name":"Kevin Gage","avatar":""},{"name":"David Warshofsky","avatar":""},{"name":"Jason Beghe","avatar":""},{"name":"Anne Bancroft","avatar":""},{"name":"Scott Wilson","avatar":""},{"name":"Daniel von Bargen","avatar":""},{"name":"Angel David","avatar":""},{"name":"Lucinda Jenney","avatar":""},{"name":"John Michael Higgins","avatar":""},{"name":"Stephen Rams","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
