INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-tinh-cai-thien', 'Hào Tình Cái Thiên', 'Theft Under The Sun', 'null', 'https://phimimg.com/upload/vod/20231120-1/838b7f9c715b92dd52cbca6c8114cd7e.jpg', '<p>Hào Tình Cái Thiên - Theft Under The Sun xoay quanh Ah Ho là 1 tay trong và sứ mệnh của anh là phải tóm cổ được Dan, 1 tên tội phạm nước ngoài, rất có quyền lực. Bởi vì 1 vài sự hiểu lầm, anh đã ko được chấp nhận trở về cương vị cảnh sát sau khi nhiệm vụ thất bại. Bác sĩ tâm lý Wu ZhenYu đã cố gắng giúp đỡ Ah Ho quay lại, trong khi So Chi Wai, cấp trên của Ah Ho, thì nghĩ rằng anh đã phản bội cảnh sát.</p>', 'Full', 1, 'single', 'completed', 22, 1997, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Michael Wong","avatar":""},{"name":"Julian Cheung","avatar":""},{"name":"Gigi Lai","avatar":""},{"name":"Francis Ng","avatar":""},{"name":"Edmond So","avatar":""},{"name":"Peter Ngor Chi-Kwan","avatar":""},{"name":"Chan Tung","avatar":""},{"name":"Timmy Ho","avatar":""},{"name":"Rocky Lai Keung-Kun","avatar":""},{"name":"Chan Man-Ching","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324538);
