INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-yeu', 'Quá Yêu', 'Addicted to Love', 'https://phimimg.com/upload/vod/20231116-1/e167de3b8c92b45b6e653179aad920ee.jpg', 'https://phimimg.com/upload/vod/20231116-1/449d2fd9153cf254e47561126d44d2ee.jpg', '<p>Nhà thiên văn học tốt bụng Sam bị tàn phá nặng nề khi tình yêu của đời anh rời bỏ anh để đến với một người Pháp dịu dàng. Do đó, anh ấy làm điều mà mọi người khác bình thường sẽ làm - đến New York và lập nhà trong tòa nhà bỏ hoang đối diện căn hộ của bạn gái cũ, đợi cho đến khi cô ấy quyết định rời xa người yêu hiện tại rồi giành lại cô ấy.</p>', 'Full', 1, 'single', 'completed', 15, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Meg Ryan","avatar":""},{"name":"Matthew Broderick","avatar":""},{"name":"Kelly Preston","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"Maureen Stapleton","avatar":""},{"name":"Nesbitt Blaisdell","avatar":""},{"name":"Remak Ramsay","avatar":""},{"name":"Lee Wilkof","avatar":""},{"name":"Dominick Dunne","avatar":""},{"name":"Susan Forristal","avatar":""},{"name":"Larry Pine","avatar":""},{"name":"Debbon Ayer","avatar":""},{"name":"Maurizio Benazzo","avatar":""},{"name":"Paolo Calamari","avatar":""},{"name":"Helmar Augustus Cooper","avatar":""},{"name":"Tom Forrest","avatar":""},{"name":"Shos","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324538);
