INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-hoa-bat-ngo', 'Tai Họa Bất Ngờ', 'Breakdown', 'https://phimimg.com/upload/vod/20231120-1/b207cb292676f00537ae9a65ae5613fb.jpg', 'https://phimimg.com/upload/vod/20231120-1/a0a9ceb7a18a3e4701ee3aa1b7af1ede.jpg', '<p>Câu chuyện của Breakdown bắt đầu khi vợ chồng Jeff Taylor (Kurt Russell) và Amy (Kathleen Quinlan) cùng nhau đi xuyên nước Mỹ từ Boston đến California bằng xe riêng của gia đình. Khi cả hai đi qua vùng sa mạc phía Tây, một nơi nào đó ở New Mexico, chiếc xe bỗng nhiên bị hỏng. Một người lái xe tải đề nghị đưa Amy đến điểm đỗ xe cách đó không xa, trong khi Jeff ở lại sửa xe. Chờ lâu không thấy vợ quay lại, Jeff kiểm tra lại xe và phát hiện có người cố ý ngắt dây dẫn nguồn điện. Anh quyết định đi vào thị trấn hẻo lánh tìm vợ mà không hay biết mình sắp sửa phải đối đầu với một băng nhóm tội phạm bắt cóc và giết người không ghê tay...</p>', 'Full', 1, 'single', 'completed', 17, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kurt Russell","avatar":""},{"name":"J.T. Walsh","avatar":""},{"name":"Kathleen Quinlan","avatar":""},{"name":"M.C. Gainey","avatar":""},{"name":"Jack Noseworthy","avatar":""},{"name":"Rex Linn","avatar":""},{"name":"Ritch Brinkley","avatar":""},{"name":"Moira Sinise","avatar":""},{"name":"Kim Robillard","avatar":""},{"name":"Thomas Kopache","avatar":""},{"name":"Jack McGee","avatar":""},{"name":"Vincent Berry","avatar":""},{"name":"Helen Duffy","avatar":""},{"name":"Ancel Cook","avatar":""},{"name":"Gene Hartline","avatar":""},{"name":"Steve Waddington","avatar":""},{"name":"Rick Sanders","avatar":""},{"name":"Alitzah","avatar":""},{"name":"Ri","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324538);
