INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-gia-hoa-binh', 'Sứ Giả Hòa Bình', 'The Peacemaker', 'https://phimimg.com/upload/vod/20231119-1/2ace1b0d59298469ba921bee2a2e8a65.jpg', 'https://phimimg.com/upload/vod/20231119-1/82b5b3820fce8bddd747922893c0642b.jpg', '<p>Khi một đoàn tàu chở đầu đạn nguyên tử gặp nạn một cách bí ẩn ở Liên Xô cũ, một chuyên gia hạt nhân phát hiện ra vụ tai nạn thực sự là một phần của âm mưu che đậy hành vi trộm cắp vũ khí. Được giao nhiệm vụ giúp cô thu hồi những quả bom bị mất là một Đại tá Lực lượng Đặc biệt tài giỏi.</p>', 'Full', 1, 'single', 'completed', 15, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Marcel Iureș","avatar":""},{"name":"Aleksandr Baluev","avatar":""},{"name":"Rene Medvešek","avatar":""},{"name":"Armin Mueller-Stahl","avatar":""},{"name":"Goran Visnjic","avatar":""},{"name":"Tamara Tunie","avatar":""},{"name":"Gary Werntz","avatar":""},{"name":"Randall Batinkoff","avatar":""},{"name":"Jim Haynie","avatar":""},{"name":"Alexander Strobele","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Michael Boatman","avatar":""},{"name":"Joan Copeland","avatar":""},{"name":"Carlos Gómez","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324538);
