INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-an-choi-1997', 'Đêm Ăn Chơi', 'Boogie Nights', 'https://phimimg.com/upload/vod/20230917-1/e14457e3b7054e15cba18a0a159d5016.jpg', 'https://phimimg.com/upload/vod/20230917-1/0dc10f039470e15545199f14cfd2f9f3.jpg', '<p>Lấy bối cảnh năm 1977, khi tình dục còn an toàn, khoái cảm là một công việc kinh doanh và việc kinh doanh đang bùng nổ, nhà sản xuất phim khiêu dâm lý tưởng Jack Horner mong muốn nâng tầm nghề của mình lên một loại hình nghệ thuật. Horner phát hiện ra Eddie Adams, một tài năng trẻ nóng bỏng đang làm nhân viên phục vụ bàn trong một hộp đêm và chào đón anh ta vào đại gia đình gồm những nhà làm phim, những kẻ lạc lối và những kẻ ăn bám luôn ở bên cạnh. Sự thăng tiến của Adams từ một người không ai thành một nghệ sĩ giải trí dành cho người lớn nổi tiếng là một điều nhanh chóng, và chẳng bao lâu nữa, cả thế giới dường như đều biết đến bản ngã thay thế phim khiêu dâm của anh ấy, &quot;Dirk Diggler&quot;. Giờ đây, khi vũ trường và ma túy đang thịnh hành, thời trang đang thay đổi và bữa tiệc dường như không bao giờ dừng lại, giấc mơ biến tình dục thành ngôi sao của Adams sắp va chạm với thực tế phũ phàng, lạnh lùng.</p>', 'Full', 1, 'single', 'completed', 19, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Burt Reynolds","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Heather Graham","avatar":""},{"name":"Don Cheadle","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Nicole Ari Parker","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Robert Ridgely","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
