INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-an-choi-1997', 'Đêm Ăn Chơi', 'Boogie Nights', 'đêm ăn chơi boogie nights mark wahlberg burt reynolds julianne moore john c. reilly heather graham don cheadle philip seymour hoffman nicole ari parker william h. macy robert ridgely ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('austin-powers-diep-vien-ngoc-nghech', 'Austin Powers: Điệp Viên Ngốc Nghếch', 'Austin Powers: International Man of Mystery', 'https://phimimg.com/upload/vod/20231117-1/e3ffc5a8fa8fe0598201fcc0306adbb9.jpg', 'https://phimimg.com/upload/vod/20231117-1/1bb543c036f8cc15c11213e2ad1f763f.jpg', '<p>Austin Powers là một điệp viên của thập niên 60, người được đông lạnh một cách đông lạnh và được phát hành vào những năm 1990. Thế giới là một nơi rất khác cho sức mạnh. Thật không may cho Austin, mọi người không còn quan hệ tình dục. Mặc dù anh ta có thể ở một thập kỷ khác, nhiệm vụ của anh ta vẫn như vậy. Anh ấy đã hợp tác với Vanessa Kensington để ngăn chặn Tiến sĩ Evil Evil, người cũng bị đóng băng trong quá khứ. Tiến sĩ Evil đã đánh cắp vũ khí hạt nhân và đang yêu cầu thanh toán (khi anh ta nhận ra số thập niên 90) 100 tỷ đô la. Austin Powers có thể dừng người điên này không? Hoặc anh ta sẽ bắt kịp với tay sai của Evil, với những cái tên như Alotta Fagina và nhiệm vụ ngẫu nhiên? Chỉ có thời gian sẽ nói!</p>', 'Full', 1, 'single', 'completed', 18, 1997, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Mike Myers","avatar":""},{"name":"Elizabeth Hurley","avatar":""},{"name":"Michael York","avatar":""},{"name":"Mimi Rogers","avatar":""},{"name":"Robert Wagner","avatar":""},{"name":"Seth Green","avatar":""},{"name":"Fabiana Udenio","avatar":""},{"name":"Mindy Sterling","avatar":""},{"name":"Paul Dillon","avatar":""},{"name":"Charles Napier","avatar":""},{"name":"Will Ferrell","avatar":""},{"name":"Joann Richter","avatar":""},{"name":"Anastasia Sakelaris","avatar":""},{"name":"Afifi Alaouie","avatar":""},{"name":"Monet Mazur","avatar":""},{"name":"Mark Bringelson","avatar":""},{"name":"Clint Howard","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324538);
