INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('austin-powers-diep-vien-ngoc-nghech', 'Austin Powers: Điệp Viên Ngốc Nghếch', 'Austin Powers: International Man of Mystery', 'austin powers: điệp viên ngốc nghếch austin powers: international man of mystery mike myers elizabeth hurley michael york mimi rogers robert wagner seth green fabiana udenio mindy sterling paul dillon charles napier will ferrell joann richter anastasia sakelaris afifi alaouie monet mazur mark bringelson clint howard e ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-luc-mot', 'Không Lực Một', 'Air Force One', 'https://phimimg.com/upload/vod/20231115-1/626d601d6a256ec0c80952d0d90e86ae.jpg', 'https://phimimg.com/upload/vod/20231115-1/b8feeba90fd47283ecc5bc8dc4beb9be.jpg', '<p>Đang ở độ cao vài chục ngàn mét, chiếc chuyên cơ của Ngài Tổng thống Hoa Kỳ đột nhiên bị không tặc tấn công. Tổng thống lập tức được hộ tống vào khoang cứu sinh rời khỏi chuyên cơ, nhưng vợ và con gái Ngài cùng đoàn tuỳ tùng gồm 50 người đều trở thành con tin của bọn khủng bố. Chính vào lúc mọi tia hy vọng dường như đã tắt ngấm thì bọn khủng bố bỗng bị hạ gục từng tên một. Một nhân vật bí hiểm đang tìm cách giải cứu chiếc chuyên cơ. Nhân vật bí hiểm đó là ai? Liệu Ngài Tổng thống có chấp nhận thương thuyết với bọn khủng bố hay không khi mạng sống của vợ và con mình đang nằm trong tay chúng?…</p>', 'Full', 1, 'single', 'completed', 15, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Glenn Close","avatar":""},{"name":"Wendy Crewson","avatar":""},{"name":"Liesel Matthews","avatar":""},{"name":"Paul Guilfoyle","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Dean Stockwell","avatar":""},{"name":"Tom Everett","avatar":""},{"name":"Jürgen Prochnow","avatar":""},{"name":"Donna Bullock","avatar":""},{"name":"Michael Ray Miller","avatar":""},{"name":"Carl Weintraub","avatar":""},{"name":"Elester Latham","avatar":""},{"name":"Elya Baskin","avatar":""},{"name":"Levan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324538);
