INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-luc-mot', 'Không Lực Một', 'Air Force One', 'không lực một air force one harrison ford gary oldman glenn close wendy crewson liesel matthews paul guilfoyle xander berkeley william h. macy dean stockwell tom everett jürgen prochnow donna bullock michael ray miller carl weintraub elester latham elya baskin levan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('robinson-tren-dao-hoang', 'Robinson Trên Đảo Hoang', 'Robinson Crusoe', 'https://phimimg.com/upload/vod/20231113-1/e864b84c14e5f6a5b1609ff6befec950.jpg', 'https://phimimg.com/upload/vod/20231113-1/1342873d19b23e5c549820fd58881adb.jpg', '<p>Robinson Crusoe trốn khỏi nước Anh trên một con tàu sau khi giết bạn mình vì tình yêu với Mary. Một cơn bão đại dương dữ dội đã đánh đắm con tàu của anh ta và khiến anh ta bị mắc kẹt một mình trên một hòn đảo chưa được khám phá. Bị bỏ lại để tự bảo vệ mình, Crusoe tìm cách sống sót tạm thời trên đảo, cho đến khi anh gặp Friday, một người trong bộ lạc mà anh đã cứu khỏi bị hy sinh. Ban đầu, Crusoe rất vui mừng vì cuối cùng cũng có một người bạn, nhưng anh ấy phải tự bảo vệ mình trước bộ lạc sử dụng hòn đảo để hiến tế người trong bộ lạc cho các vị thần của họ. Theo thời gian, mối quan hệ của họ thay đổi từ chủ-nô sang tình bạn được tôn trọng lẫn nhau bất chấp sự khác biệt về văn hóa và tôn giáo.</p>', 'Full', 1, 'single', 'completed', 14, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"James Frain","avatar":""},{"name":"Polly Walker","avatar":""},{"name":"Ian Hart","avatar":""},{"name":"William Takaku","avatar":""},{"name":"Damian Lewis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
