INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-cong-g4', 'Đặc Công G4', 'Option Zero', 'https://phimimg.com/upload/vod/20231113-1/8c7ecbbe47053ba992e871aaa5931039.jpg', 'https://phimimg.com/upload/vod/20231113-1/28dc77cc5b5a0c596e2b5a32f9856478.jpg', '<p>Đặc Công G4 - Option Zero xoay quanh Ben, một sĩ quan thành viên của lực lượng đặc nhiệm của cảnh sát Hồng Kông, người đã hạ gục một số tội phạm và những tay anh chị có tiếng trong khu vực. Trong khi họ đang theo dõi một tổ chức buôn bán vũ khí của những người Hàn Quốc, các thành viên trong nhóm dần phát triển mối quan hệ tình cảm khá phức tạp. Một ngày nọ, chỉ huy của họ bị giết, một số thành viên đã tham gia vào một công ty vệ sĩ tư nhân ưu tú tên là G4. Mọi thứ dường như trở nên căng thẳng khi các sát thủ đến từ Hàn Quốc xả súng vào những người đàn ông mà G4 được trả tiền để bảo vệ.</p>', 'Full', 1, 'single', 'completed', 15, 1997, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Julian Cheung","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Carman Lee","avatar":""},{"name":"Monica Chan","avatar":""},{"name":"Michael Wong","avatar":""},{"name":"Ching Fung","avatar":""},{"name":"Nancy Lan Sai","avatar":""},{"name":"Hung On Cheung","avatar":""},{"name":"Farini Cheung Yui-Ling","avatar":""},{"name":"Joseph Cheung Man-Kwong","avatar":""},{"name":"Michael Tong","avatar":""},{"name":"Lee Yue-Ling","avatar":""},{"name":"Roderick Lam Chung-Kei","avatar":""},{"name":"John Chan Wing-Fai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324538);
