INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-mua-thoat-y', 'Điệu Múa Thoát Y', 'The Full Monty', 'https://phimimg.com/upload/vod/20231113-1/516fd4797d6b7c79d696082f9a48ffe3.jpg', 'https://phimimg.com/upload/vod/20231113-1/c436bb4d1b56e33bded990c901331412.jpg', '<p>Phim kể về một nhóm gồm 6 chàng trai, trong đó có Gary (Gaz) và Dave, từng làm việc cho một nhà máy thép tại thành phố công nghiệp Sheffield, Anh. Giai đoạn suy thoái kinh tế đẩy nhóm vào cảnh mất việc làm. Tình cờ họ biết đến một gánh vũ công nam của Mỹ đang biểu diễn điệu múa thoát y có tên là Chippendales. Họ nảy ra ý định tập hợp những đồng nghiệp của mình tại nhà máy cũ - cũng đang trong cảnh thất nghiệp - để thành lập một gánh khiêu vũ thoát y nam. Phim hài với số kinh phí khá thấp &quot;The Full Monty&quot; đã được độc giả trang web về điện ảnh bầu chọn là bộ phim hài được yêu thích nhất của mọi thời đại...</p>', 'Full', 1, 'single', 'completed', 17, 1997, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Robert Carlyle","avatar":""},{"name":"Mark Addy","avatar":""},{"name":"Wim Snape","avatar":""},{"name":"Steve Huison","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Paul Barber","avatar":""},{"name":"Hugo Speer","avatar":""},{"name":"Lesley Sharp","avatar":""},{"name":"Emily Woof","avatar":""},{"name":"Deirdre Costello","avatar":""},{"name":"Paul Butterworth","avatar":""},{"name":"Dave Hill","avatar":""},{"name":"Bruce Jones","avatar":""},{"name":"Andrew Livingston","avatar":""},{"name":"Vinny Dhillon","avatar":""},{"name":"Kate Layden","avatar":""},{"name":"Joanna Swain","avatar":""},{"name":"Kate Rutter","avatar":""},{"name":"Jun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324538);
