INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-danh-1997', 'Ẩn Danh', 'Incognito', 'https://phimimg.com/upload/vod/20231109-1/1a2b8439d03fb457d0115d1086e3608a.jpg', 'https://phimimg.com/upload/vod/20231109-1/cd1fb69fc3725f17402f4f5fced2b959.jpg', '<p>Harry Donovan là một tay đạo chích nghệ thuật, người vẽ bức tranh Rembrandt giả với giá năm trăm ngàn đô la. Anh gặp và yêu say đắm cô nàng Marieke ở Paris, thế nhưng hóa ra Marieke lại là một chuyên gia nghệ thuật, người mà khách hàng của Harry đang sử dụng để kiểm tra bức tranh giả mà anh vẽ.</p>', 'Full', 1, 'single', 'completed', 16, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Patric","avatar":""},{"name":"Irène Jacob","avatar":""},{"name":"Ian Richardson","avatar":""},{"name":"Rod Steiger","avatar":""},{"name":"Thomas Lockyer","avatar":""},{"name":"Simon Chandler","avatar":""},{"name":"Pip Torrens","avatar":""},{"name":"Michael Cochrane","avatar":""},{"name":"Togo Igawa","avatar":""},{"name":"Joseph Blatchley","avatar":""},{"name":"Paul Brennen","avatar":""},{"name":"Olivier Pierre","avatar":""},{"name":"Peter Gale","avatar":""},{"name":"Dudley Sutton","avatar":""},{"name":"Adam Fogerty","avatar":""},{"name":"Ricardo Montez","avatar":""},{"name":"Jonathan Newth","avatar":""},{"name":"Ian","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324538);
