INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('an-danh-1997', 'Ẩn Danh', 'Incognito', 'ẩn danh incognito jason patric irène jacob ian richardson rod steiger thomas lockyer simon chandler pip torrens michael cochrane togo igawa joseph blatchley paul brennen olivier pierre peter gale dudley sutton adam fogerty ricardo montez jonathan newth ian ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-bao-bang-gia', 'Cơn Bảo Băng Giá', 'The Ice Storm', 'https://phimimg.com/upload/vod/20231101-1/f0895d5a315b651bad8a2afd5e661b9c.jpg', 'https://phimimg.com/upload/vod/20231101-1/9fc7311f0fde1c74e4639374de15b48b.jpg', '<p>Địa điểm là ngoại ô giàu có của Connecticut, nước Mỹ. Thời điểm là năm 1973, dư âm của những biến động xã hội lớn trong thập niên 1960 vẫn còn, công nghiệp phim khiêu dâm bước vào thời hoàng kim, chiến tranh Việt Nam vào giai đoạn cuối và tổng thống Nixon xuất hiện dày đặc trên truyền hình nói những lời không còn ai tin nữa.
 New Canaan là một thị trấn nhỏ, không phải là vùng đất hứa trong Kinh thánh nhưng là nơi giàu có nhất nước Mỹ. Bối cảnh của bộ phim diễn ra trong 24h của ngày lễ Tạ ơn giữa một trận bão tuyết lịch sử.
 Không có một nhân vật &quot;anh hùng&quot; theo kiểu chính kịch, bộ phim là tập hợp những con người đánh mất sự trong sáng và bản chất tốt đẹp của mình giữa sự hỗn loạn, rối rắm. Họ chôn sâu bí mật, phản bội những người xung quanh và hủy hoại mọi mối quan hệ. Mất sự kết nối, điều duy nhất họ còn chia sẻ với nhau là sự mục ruỗng không thể cứu vãn.</p>', 'Full', 1, 'single', 'completed', 22, 1997, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Kevin Kline","avatar":""},{"name":"Joan Allen","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Jamey Sheridan","avatar":""},{"name":"Christina Ricci","avatar":""},{"name":"Tobey Maguire","avatar":""},{"name":"Elijah Wood","avatar":""},{"name":"Adam Hann-Byrd","avatar":""},{"name":"Michael Cumpsty","avatar":""},{"name":"Katie Holmes","avatar":""},{"name":"Henry Czerny","avatar":""},{"name":"David Krumholtz","avatar":""},{"name":"Kate Burton","avatar":""},{"name":"William Cain","avatar":""},{"name":"Maia Danziger","avatar":""},{"name":"Michael Egerman","avatar":""},{"name":"Christine Farr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
