INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-bao-bang-gia', 'Cơn Bảo Băng Giá', 'The Ice Storm', 'cơn bảo băng giá the ice storm kevin kline joan allen sigourney weaver jamey sheridan christina ricci tobey maguire elijah wood adam hann-byrd michael cumpsty katie holmes henry czerny david krumholtz kate burton william cain maia danziger michael egerman christine farr ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-nghe-gien', 'Công Nghệ Gien', 'Gattaca', 'https://phimimg.com/upload/vod/20231029-1/7f2e682391526d53d0251ed1468bc01d.jpg', 'https://phimimg.com/upload/vod/20231029-1/021e0500ae555aec8f079b382a31d40c.jpg', '<p>Trong phim Công Nghệ Gien, khi nền văn minh phát triển, con người họ can thiệp vào việc sinh sản bằng cách chọn ra những gene tốt nhất. Trong phim hd này, những người mang những bộ gene hoàn hảo sẽ được bay vào vũ trụ. Vincent là một người &quot;bất hợp pháp&quot; vì được sinh ra theo cách tự nhiên. Dù máy tính đã dự báo anh chỉ sống được 30,2 năm, Vincent vẫn ước mơ được bay vào vũ trụ như những con người hoàn hảo kia. Từng bước, anh tiến gần đến giấc mơ của mình. Xem phim Công Nghệ Gien bạn sẽ rất hài lòng với chất lượng dịch vụ phim online.</p>', 'Full', 1, 'single', 'completed', 17, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Uma Thurman","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Alan Arkin","avatar":""},{"name":"Loren Dean","avatar":""},{"name":"Gore Vidal","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Ernest Borgnine","avatar":""},{"name":"Blair Underwood","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Jayne Brook","avatar":""},{"name":"Una Damon","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Maya Rudolph","avatar":""},{"name":"Elizabeth Dennehy","avatar":""},{"name":"Mason Gamble","avatar":""},{"name":"Vincent Nielson","avatar":""},{"name":"Chad Christ","avatar":""},{"name":"Wi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f0084