INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-nghe-gien', 'Công Nghệ Gien', 'Gattaca', 'công nghệ gien gattaca ethan hawke uma thurman jude law alan arkin loren dean gore vidal tony shalhoub ernest borgnine blair underwood xander berkeley jayne brook una damon elias koteas maya rudolph elizabeth dennehy mason gamble vincent nielson chad christ wi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-va-robin', 'Người Dơi và Robin', 'Batman & Robin', 'https://phimimg.com/upload/vod/20231026-1/b39a64015a5795365cd2dc4d963b4e68.jpg', 'https://phimimg.com/upload/vod/20231026-1/8b2894bb1c034be24adec9fe3bcec224.jpg', '<p>Đây là tập phim thứ tư trong loạt phim về Batman. Lần này, Batman (George Clooney thủ vai) và người trợ lý Robin (Chris O&quot;Donnell thủ vai) phải đối phó với Mr. Freeze (Arnold Schwarzenegger thủ vai), một bác sĩ tài ba vì quá thương vợ nên muốn trả thù thành phố Gotham, biến nơi đã gián tiếp gây ra cái chết cho vợ (do không tài trợ kinh phí nghiên cứu và chữa trị bệnh cho vợ) vĩnh viễn ngập trong băng giá. Ngoài ra, hắn còn được sự giúp sức của Thường Xuân Độc (Uma Thurman thủ vai), một người thực vật biến đổi DNA luôn muốn bảo toàn thế giới cho mọi cây cỏ. Cùng lúc đó, Alfred (Michael Gough thủ vai), người quản gia trung thành của Batman mắc phải một căn bệnh hiểm nghèo mà chỉ có Mr. Freeze mới có phương thuốc cứu chữa. Sự việc đã kéo cô ...</p>', 'Full', 1, 'single', 'completed', 13, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Chris O''Donnell","avatar":""},{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Uma Thurman","avatar":""},{"name":"Alicia Silverstone","avatar":""},{"name":"Michael Gough","avatar":""},{"name":"Pat Hingle","avatar":""},{"name":"John Glover","avatar":""},{"name":"Elle Macpherson","avatar":""},{"name":"Vivica A. Fox","avatar":""},{"name":"Vendela Kirsebom","avatar":""},{"name":"Elizabeth Sanders","avatar":""},{"name":"Jeep Swenson","avatar":""},{"name":"John Fink","avatar":""},{"name":"Michael Reid MacKay","avatar":""},{"name":"Eric L","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc2