INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-tau-khong-gian-nhen-khong-lo', 'Chiến Binh Tàu Không Gian: Nhện Khổng Lồ', 'Starship Troopers', 'https://phimimg.com/upload/vod/20231024-1/2438874298a2b4093a6c23471ef3f459.jpg', 'https://phimimg.com/upload/vod/20231024-1/ce25f059d6846624e657cadd6733a918.jpg', '<p>Johnny Rico, Dizzy Flores, Carmen Ibanez học cùng một trường cấp 3 ( high school ). Cuộc đời học sinh trôi qua thật êm đềm và nhiều kỷ niệm. Sau khi tốt nghiệp họ thi vào học viện quân sự.Đùng một cái, chiến tranh giữa con người và loài nhện trên hành tinh không xa nổ ra, loài nhện tinh khôn muốn chiếm trái đất xinh đẹp. Johnny Rico và đồng đội được đào tạo và tham gia các trận đánh với loài nhện hung dữ. Cuộc chiến đấu anh hùng nhưng cũng không kém đau thương và mất mát để bảo vệ trái đất, bảo vệ cuộc sống con người...</p>', 'Full', 1, 'single', 'completed', 16, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Casper Van Dien","avatar":""},{"name":"Dina Meyer","avatar":""},{"name":"Denise Richards","avatar":""},{"name":"Jake Busey","avatar":""},{"name":"Neil Patrick Harris","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Michael Ironside","avatar":""},{"name":"Patrick Muldoon","avatar":""},{"name":"Seth Gilliam","avatar":""},{"name":"Rue McClanahan","avatar":""},{"name":"Blake Lindsley","avatar":""},{"name":"Steven Ford","avatar":""},{"name":"Ungela Brockman","avatar":""},{"name":"Bruce Gray","avatar":""},{"name":"Denise Dowse","avatar":""},{"name":"Amy Smart","avatar":""},{"name":"Tami-Adrian Ge","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2