INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-anastasia', 'Công Chúa Anastasia', 'Anastasia', 'https://phimimg.com/upload/vod/20231024-1/18edfe26878fed3fc6b1aa307465d4f4.jpg', 'https://phimimg.com/upload/vod/20231024-1/729c41444142cdb99903ad1382d636b6.jpg', '<p>Trong câu chuyện kể đầy sinh động và lạc quan về một trong những huyền thoại vĩ đại nhất trong lịch sử, phù thủy độc ác Rasputin đã ếm bùa lên gia đình hoàng gia Romanov và cô gái trẻ Anastasia bị mất tích khi cung điện của họ bị tàn phá. Mười năm sau, Nữ công tước đưa ra phần thưởng cho sự trở lại của Anastasia. Hai người Nga đầy mưu mô, lên kế hoạch cầm đồ một kẻ giả mạo, tổ chức các buổi thử giọng và chọn một cô gái mồ côi có nét giống công chúa mất tích. Họ đưa cô đến Paris để dự lễ hội. phần thưởng mà không biết cô ấy là Anastasia thật.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Meg Ryan","avatar":""},{"name":"John Cusack","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Hank Azaria","avatar":""},{"name":"Bernadette Peters","avatar":""},{"name":"Kirsten Dunst","avatar":""},{"name":"Angela Lansbury","avatar":""},{"name":"Rick Jones","avatar":""},{"name":"Andrea Martin","avatar":""},{"name":"Glenn Walker Harris Jr.","avatar":""},{"name":"Debra Mooney","avatar":""},{"name":"Arthur Malet","avatar":""},{"name":"Charity James","avatar":""},{"name":"Liz Callaway","avatar":""},{"name":"Lacey Chabert","avatar":""},{"name":"Jim Cummi","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324538);
