INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-to-thu-5', 'Nhân Tố Thứ 5', 'The Fifth Element', 'https://phimimg.com/upload/vod/20231021-1/f0214c7b6ffd54aa7ed581a20407a58f.jpg', 'https://phimimg.com/upload/vod/20231021-1/50dd294baad3ec64a462fd02d1947f85.jpg', '<p>Ba trăm năm một lần, Quỷ dữ lại quay lại tìm cách thôn tính loài người ẩn chứa dưới vỏ bọc bí mật là một sức mạnh huỷ diệt không thể chế ngự được, kết hợp từ các nhân tố Kim, Mộc, Thủy, Hỏa trong tự nhiên và “Nhân Tố Thứ 5”. Korben Dallas, một tài xế taxi đã tình cờ đón được một nữ hành khách rất đặc biệt, LeeLoo. Cô không biết nói tiếng Anh nhưng lại có một bộ não thông minh cực kì đáng nể. Korben không thể cưỡng lại được sự quyến rũ đầy hoang dã của LeeLoo. Anh càng không thể ngờ mình đang bị kéo vào một cuộc phiêu lưu đầy sóng gió…</p>', 'Full', 1, 'single', 'completed', 18, 1997, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Milla Jovovich","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Ian Holm","avatar":""},{"name":"Chris Tucker","avatar":""},{"name":"Luke Perry","avatar":""},{"name":"Brion James","avatar":""},{"name":"Tommy Lister Jr.","avatar":""},{"name":"Lee Evans","avatar":""},{"name":"Charlie Creed-Miles","avatar":""},{"name":"Tricky","avatar":""},{"name":"John Neville","avatar":""},{"name":"John Bluthal","avatar":""},{"name":"Mathieu Kassovitz","avatar":""},{"name":"Christopher Fairbank","avatar":""},{"name":"Kim Chan","avatar":""},{"name":"Richard Leaf","avatar":""},{"name":"Julie T. Wal","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8