INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-can-nao', 'Trò Chơi Cân Não', 'The Game', 'https://phimimg.com/upload/vod/20231016-1/0e94597b8ed62561f3f08f58fa06f679.jpg', 'https://phimimg.com/upload/vod/20231016-1/76eae7ae6884a9c6e8cc370453ef730d.jpg', '<p>Bộ phim mở đầu bằng cuộc sống bận rộn hằng ngày của một ông chủ ngân hàng tại San Francisco đã khiến ông trở nên cô độc. Và cao trào của bộ phim bắt đầu khi ông được người em trai tặng một trò chơi đặc biệt – The Game, thứ đã thay đổi quan điểm của ông về cách sống và thế giới xung quanh.</p>', 'Full', 1, 'single', 'completed', 16, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Sean Penn","avatar":""},{"name":"Deborah Kara Unger","avatar":""},{"name":"James Rebhorn","avatar":""},{"name":"Peter Donat","avatar":""},{"name":"Carroll Baker","avatar":""},{"name":"Anna Katarina","avatar":""},{"name":"Armin Mueller-Stahl","avatar":""},{"name":"Charles Martinet","avatar":""},{"name":"Scott Hunter McGuire","avatar":""},{"name":"Florentine Mocanu","avatar":""},{"name":"Elizabeth Dennehy","avatar":""},{"name":"Caroline Barclay","avatar":""},{"name":"Daniel Schorr","avatar":""},{"name":"John Aprea","avatar":""},{"name":"Harri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324538);
