INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong-tay-vuc-hung-su', 'Hoàng Phi Hồng: Tây Vực Hùng Sư', 'Once Upon a Time in China and America', 'https://phimimg.com/upload/vod/20231016-1/b17b4f03476a25935949b1b6d448e26e.jpg', 'https://phimimg.com/upload/vod/20231016-1/87383760dcebb0cfcc67411e64831b11.jpg', '<p>Hoàng Phi Hồng Tây Vực Hùng Sư là bộ phim võ thuật tiếp theo về Hoàng Phi Hồng. Lần này Hoàng Phi Hồng cùng dì Thập Tam của mình và Quỷ Cước Thất đến Mỹ để thăm Buck Tooth Sol, đang điều hành một chi nhánh Bảo Chi Lâm tại đây. Trên đường đi, họ đã quen được một anh chàng người Mỹ tóc vàng Billy. Chuyện trở nên tồi tệ khi chuyến tàu bị cướp và Hoàng Phi Hồng bị mất trí nhớ, bị thất lạc với dì Thập Tam và Quỷ Cước Thất, nhưng được những người da đỏ cứu sống và cưu mang. Cùng lúc đó nhóm cướp tàu đang lên kế hoạch cướp nhà băng, liệu Hoàng Phi Hồng có kịp ngăn chặn chúng và tìm lại được người thân của mình?</p>', 'Full', 1, 'single', 'completed', 22, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jet Li","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Power Chan Kwok-Pong","avatar":""},{"name":"Jeff Wolfe","avatar":""},{"name":"Chrysta Bell","avatar":""},{"name":"Kong Lung","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Roger Yuan","avatar":""},{"name":"Joseph Sayah","avatar":""},{"name":"T.J. Storm","avatar":""},{"name":"Johnny Koo Kwok-Wah","avatar":""},{"name":"Gavin Perry","avatar":""},{"name":"Ryon Marshall","avatar":""},{"name":"Daniel Luján","avatar":""},{"name":"Chris Doughton","avatar":""},{"name":"Jason De Hoyos","avatar":""},{"name":"Freddy Joe","avatar":""},{"name":"St","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324538);
