INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toc-do-2-kiem-soat-hanh-trinh', 'Tốc Độ 2: Kiểm Soát Hành Trình', 'Speed 2: Cruise Control', 'https://phimimg.com/upload/vod/20231016-1/5bd9bf381c742762acf641cc1d217a6e.jpg', 'https://phimimg.com/upload/vod/20231016-1/7edda61d465747da99178b437573a2b3.jpg', '<p>Annie và bạn trai kiêm cảnh sát Alex đi biển để tận hưởng những ngày tháng lãng mạn bên nhau. Trên một chuyến tàu, một hành khách có tên Giger, đã sử dụng tài năng lập trình của mình để chặn đứng hoạt động của con tàu. Nhiệm vụ của Alex lần này là bảo vệ tất cả hành khách và tìm hiểu ra động cơ, mục đích của Giger. Bộ phim lại tiếp tục cống hiến cho khán giả những giây phút gay cấn đến nghẹt thở...</p>', 'Full', 1, 'single', 'completed', 24, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sandra Bullock","avatar":""},{"name":"Jason Patric","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Temuera Morrison","avatar":""},{"name":"Brian McCardie","avatar":""},{"name":"Glenn Plummer","avatar":""},{"name":"Colleen Camp","avatar":""},{"name":"Lois Chiles","avatar":""},{"name":"Mike Hagerty","avatar":""},{"name":"Bo Svenson","avatar":""},{"name":"Francis Guinan","avatar":""},{"name":"Jeremy Hotz","avatar":""},{"name":"Royale Watkins","avatar":""},{"name":"Christine Firkins","avatar":""},{"name":"Tamia","avatar":""},{"name":"Kimmy Robertson","avatar":""},{"name":"Patrika Darbo","avatar":""},{"name":"Connie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324538);
