INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-cung-lap-phuong', 'Mê Cung Lập Phương', 'Cube', 'https://phimimg.com/upload/vod/20231016-1/d465b9f497b329fd87d3ac5d63a65600.jpg', 'https://phimimg.com/upload/vod/20231016-1/a29d7351d1129838df048a3e353a6818.jpg', '<p>Một nhóm người lạ thức dậy và thấy mình được đặt trong một khối lập phương khổng lồ. Mỗi người trong số họ được ban cho một kỹ năng đặc biệt và họ phải làm việc cùng nhau để thoát khỏi một mê cung vô tận với những cạm bẫy chết người.</p>', 'Full', 1, 'single', 'completed', 22, 1997, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Nicole de Boer","avatar":""},{"name":"Nicky Guadagni","avatar":""},{"name":"Maurice Dean Wint","avatar":""},{"name":"David Hewlett","avatar":""},{"name":"Andrew Miller","avatar":""},{"name":"Wayne Robson","avatar":""},{"name":"Julian Richings","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324538);
