INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-khong-gian-hoi-sinh', 'Quái Vật Không Gian: Hồi Sinh', 'Alien Resurrection', 'https://phimimg.com/upload/vod/20231015-1/1d92bf43a891e7df32365dd9cb4a187c.jpg', 'https://phimimg.com/upload/vod/20231015-1/58c18058fd3cc22b1beec85f65341a74.jpg', '<p>200 năm sau cuộc chiến kinh hoàng tại nhà tù liên hành tinh, không một người sống sót nhưng thảm họa đó không khiến Liên đòan Thương mại quan tâm, điều quan tâm của họ chỉ là tiền và quyền lực, họ muốn biến cơ thể đã bị nhiễm ký sinh của Ripley thành nơi cung cấp tế bào để sản sinh ra những chiến binh quái vật. Được hồi sinh trong cơ thể nhưng sâu thẳm trong tâm trí Ripley vẫn hiểu được mối hiểm nguy cho lòai người mà Liên đòan đang kiến tạo. Và cuộc chiến với lòai quái vật cùng những dã tâm của con người vẫn tiếp tục. Nhưng đây sẽ là cuộc chiến cuối cùng...</p>', 'Full', 1, 'single', 'completed', 18, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sigourney Weaver","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Dominique Pinon","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Gary Dourdan","avatar":""},{"name":"Michael Wincott","avatar":""},{"name":"Kim Flowers","avatar":""},{"name":"Dan Hedaya","avatar":""},{"name":"J.E. Freeman","avatar":""},{"name":"Brad Dourif","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324538);
