INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-thuyen-mat-tich', 'Phi Thuyền Mất Tích', 'Event Horizon', 'https://phimimg.com/upload/vod/20231015-1/2d0b93fbdb1172e5756508321558908d.jpg', 'https://phimimg.com/upload/vod/20231015-1/bceb9c198895ec688d3a6f43180cf32b.jpg', '<p>Vào năm 2047, một nhóm phi hành gia được cử đi điều tra và trục vớt con tàu vũ trụ Event Horizon đã biến mất một cách bí ẩn 7 năm trước trong chuyến hành trình đầu tiên. Tuy nhiên, rõ ràng là có thứ gì đó độc ác đang ẩn náu trong các hành lang của nó và nỗi kinh hoàng xảy ra trong hành trình trước đó của Event Horizon vẫn còn hiện hữu.</p>', 'Full', 1, 'single', 'completed', 20, 1997, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Laurence Fishburne","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Kathleen Quinlan","avatar":""},{"name":"Joely Richardson","avatar":""},{"name":"Richard T. Jones","avatar":""},{"name":"Jack Noseworthy","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Peter Marinker","avatar":""},{"name":"Holley Chant","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324538);
