INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phi-thuyen-mat-tich', 'Phi Thuyền Mất Tích', 'Event Horizon', 'phi thuyền mất tích event horizon laurence fishburne sam neill kathleen quinlan joely richardson richard t. jones jack noseworthy jason isaacs sean pertwee peter marinker holley chant ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-ao-den', 'Đặc Vụ Áo Đen', 'Men in Black', 'https://phimimg.com/upload/vod/20231015-1/943151208dd991dc2b5d241fa0f91d47.jpg', 'https://phimimg.com/upload/vod/20231015-1/a0db5892331da3685117e23839247a50.jpg', '<p>Tình cờ chứng kiến một người ngoài hành tinh, nhân viên sở New York James Edwards bỗng chốc trở thành đặc vụ J của MIB - Men in Black, một tổ chức bí mật chuyên quản lí, giám sát hoạt động của người ngoài hành tinh trên Trái Đất. Dìu dắt J là K, một đặc vụ kì cựu. Vừa chân ướt chân ráo vào nghề, J đã phải cùng K giải quyết một vụ lớn. Một sinh vật ngoài hành tinh có hình dáng giống một con gián xuống Trái Đất để tìm một thiên hà siêu nhỏ được giấu trong một chiếc vòng cổ của mèo. Ngân hà này có một nguồn năng lượng vô tận. Vì người đàn ông bị Con Bọ - tên của sinh vật ngoài trái đất kia - giết là thành viên của một hoàng gia người ngoài hành tinh nên hoàng gia nay muốn phá hủy Trái Đất để thiên hà kia không rơi vào con Bọ. Nhiệm vụ của K và J là cứu Trái đất, đồng thời tiêu diệt con Bọ.</p>', 'Full', 1, 'single', 'completed', 20, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tommy Lee Jones","avatar":""},{"name":"Will Smith","avatar":""},{"name":"Linda Fiorentino","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Rip Torn","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Mike Nussbaum","avatar":""},{"name":"Jon Gries","avatar":""},{"name":"Sergio Calderón","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324538);
