INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dac-vu-ao-den', 'Đặc Vụ Áo Đen', 'Men in Black', 'đặc vụ áo đen men in black tommy lee jones will smith linda fiorentino vincent d''onofrio rip torn tony shalhoub siobhan fallon hogan mike nussbaum jon gries sergio calderón ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-will-tot-bung', 'Chàng Will Tốt Bụng', 'Good Will Hunting', 'https://phimimg.com/upload/vod/20231014-1/ed837c1104686612d0a9b97a8eb93848.jpg', 'https://phimimg.com/upload/vod/20231014-1/43e52ac62cbef7c9e283b9db2ceda37c.jpg', '<p>Cậu bé Will Hunting bất hạnh lớn lên trong những xó xỉnh của Boston tham gia vào vô số những trò vô bổ: uống rượu, đánh nhau… Nhưng cậu lại là người thông minh và rất yêu khoa học. Cuộc đời Will đã rẽ sang ngả khác khi anh được nhận vào làm bảo vệ cho Học viện Công nghệ Massachusetts. Một lần vì tò mò Will nhìn trộm buổi học của lớp toán ứng dụng. Cậu đặc biệt thích thú với bài toán hóc búa của giáo sư Gerald Lambeau, Will đã giải nó ngay trong đêm.... Good Will Hunting là minh chứng hùng hồn cho quan điểm nhân tài có ở mọi nơi không kể xuất thân, địa vị, hoàn cảnh chỉ cần có cơ hội họ sẽ thể hiện được năng lực của mình. Qua câu chuyện của Will lại một lần nữa vai trò giáo dục của gia đình được nhấn mạnh nếu Will ...</p>', 'Full', 1, 'single', 'completed', 17, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matt Damon","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"Ben Affleck","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Minnie Driver","avatar":""},{"name":"Casey Affleck","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Vik Sahay","avatar":""},{"name":"John Mighton","avatar":""},{"name":"Rachel Majorowski","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
