INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-si-hec-quyn', 'Dũng Sĩ Héc Quyn', 'Hercules', 'https://phimimg.com/upload/vod/20231014-1/8d7c55928d759b86b5e19aafc57ba9ae.jpg', 'https://phimimg.com/upload/vod/20231014-1/77cd09261a31b7e5f5d72177405bcf9b.jpg', '<p>Trái đất khi xưa bị các Titan tàn phá, cho đến khi chúng bị thần Zeus nhốt lại. Ngay sau đó là sự ra đời của Hercules, con trai của Zeus với Hera. Trong khi hầu hết các thần đều vui mừng thì Hades lại không. Hắn lui về âm phủ và được các nữ thần số mệnh cho biết, trong 18 năm nữa, một đường thẳng tạo bởi các hành tinh sẽ chỉ chỗ tới nơi các Titan bị nhốt để thả chúng ra, tiêu diệt Zeus và chiếm núi Olympus, nhưng chỉ khi Hercules không can dự.</p>', 'Full', 1, 'hoathinh', 'completed', 24, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tate Donovan","avatar":""},{"name":"Josh Keaton","avatar":""},{"name":"Roger Bart","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"James Woods","avatar":""},{"name":"Susan Egan","avatar":""},{"name":"Bobcat Goldthwait","avatar":""},{"name":"Matt Frewer","avatar":""},{"name":"Rip Torn","avatar":""},{"name":"Samantha Eggar","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324538);
