INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('97-aces-go-places', '97 Aces Go Places', '97 Aces Go Places', 'null', 'https://phimimg.com/upload/vod/20231013-1/6f61402e42b9ec0f51424f63e44ecae2.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Người&nbsp;</span><span class="" style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">phụ nữ Miaoling gợi cảm và mê hoặc Wan Ling (do Zhong Liti thủ vai) là một kẻ lừa dối đỏ mặt, hiếm khi bỏ lỡ qua sông hồ. Ông chủ của một xã hội nào đó đã bị Wan Ling lừa cạn kiệt tiền của mình, và chết vì một cơn đau tim trong cơn giận dữ. Trước khi chết, ông chủ đã giao phó xã hội cho con trai duy nhất Haoshi (do Alan Tâm thủ vai), người đã làm việc chăm chỉ ở Hoa Kỳ, và ra lệnh cho anh ta giết Wan Ling bằng chính tay mình để trả thù cho chính mình. Mặc dù 200.&lt;&gt; người miễn cưỡng, dưới áp lực của mẹ (Maria) và các thành viên trong hội, Haoshi cuối cùng đã tiếp quản xã hội và thực hành thiện xạ dưới sự giám sát của tay súng bắn tỉa Drunken Gun (do Tony Leung thủ vai). Hai người đi theo Loan Linh, chờ cơ hội hành động, nhưng Hạo thị dần dần bị ám ảnh bởi người phụ nữ này, vì vậy anh không thể bắt đầu.<br/>Mặt khác, Wan Ling đã từng sử dụng giả của Van Gogh để giao dịch với Lei Yang (do Wu Zhenyu), ông chủ của thế giới ngầm thủ vai, và lừa đảo đối phương &lt;&gt; triệu tiền mặt, để Lei Yang nhảy lên như sấm sét và liên tục cử người đuổi giết. Vài nhóm người và ngựa tụ tập với nhau, và cảnh tượng ngày càng trở nên hỗn loạn....</span></p>', 'Full', 1, 'single', 'completed', 17, 1997, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Tony Leung","avatar":""},{"name":"Alan Tam","avatar":""},{"name":"Chung Liti","avatar":""},{"name":"Chu Kit Yee","avatar":""},{"name":"Wu Zhenyu","avatar":""},{"name":"Maria","avatar":""},{"name":"Lâm Quốc Bân","avatar":""},{"name":"TRẦN Hạo","avatar":""},{"name":"Billy Zhou","avatar":""},{"name":"Lôi Vũ Dương","avatar":""},{"name":"Hoàng Tử Hoa","avatar":""},{"name":"Quan Bảo Huệ","avatar":""},{"name":"Chu Chiêu Long","avatar":""},{"name":"Qian Xiaohao","avatar":""},{"name":"Qian Jiale","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324538);
