INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-van-song', 'Anh Vẫn Sống', 'The Odd One Dies', 'https://phimimg.com/upload/vod/20231010-1/b33de1195663291378161b617252c21b.jpg', 'https://phimimg.com/upload/vod/20231010-1/63d79c19e81af32c6821f48ae2993aa9.jpg', '<p>Một tay xã hội đen tuyệt vọng vì tiền đành mạo hiểm nhận một vụ ám sát để giải quyết vấn đề. Có tiền trong tay, anh ta thử vận may với cờ bạc và thắng liên hồi, cờ đến tay hắn phất phần phật. Với cả một gia tài, hắn không còn mạo hiểm làm tay giết thuê mà tìm một sát thủ khác để làm việc đó. Hắn chọn một cô gái đang tìm việc như vậy nhưng cô ta gây ra bao rắc rối hơn dự tính. RỒi hắn yêu cô gái lúc nào không hay. Giờ đây, mỗi lần có hợp đồng mới, hắn không biết nên gửi cô gái đi làm hay tự mình ra tay và chấp nhận rủi ro</p>', 'Full', 1, 'single', 'completed', 17, 1997, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Takeshi Kaneshiro","avatar":""},{"name":"Carman Lee","avatar":""},{"name":"Byun Woo-min","avatar":""},{"name":"Ken Choi Fung-wah","avatar":""},{"name":"Tian Min-zu","avatar":""},{"name":"Lee Diy-Yue","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Lu Ching-Ting","avatar":""},{"name":"Chiu Chi-Shing","avatar":""},{"name":"Kong Fu-Keung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324538);
