INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-loi-cam-on-ban', 'Xin Lỗi Cảm Ơn Bạn', 'My Dad Is A Jerk', 'https://phimimg.com/upload/vod/20231010-1/19ab6bd7990f42cb36ec940ad481e184.jpg', 'https://phimimg.com/upload/vod/20231010-1/6e633e944cba4163ff896811b109e892.jpg', '<p>Lee Lap Cheung là một kẻ lười biếng chưa trưởng thành và chẳng đi đến đâu. Vợ cũ Yip Ting của anh đã trở thành một người phụ nữ quyền lực trong giới kinh doanh chỉ sau vài năm. Cheung trong lúc tức giận đã yêu cầu Yip Ting cho phép anh và con trai Jason dành thời gian bên nhau. Jason là một đứa trẻ tự do, hồn nhiên và đáng yêu. Tuy là một đứa trẻ nhưng cậu ấy khá chính trực. Dưới ảnh hưởng của anh ấy, Cheung cuối cùng đã thay đổi theo chiều hướng tốt hơn để trở thành một người có tinh thần trách nhiệm thực sự...</p>', 'Full', 1, 'single', 'completed', 16, 1997, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lau Ching-wan","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Cecilia Yip","avatar":""},{"name":"Jason Chu","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Dayo Wong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324538);
