INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-sanh-duyen', 'Bán Sanh Duyên', 'Eighteen Springs', 'https://phimimg.com/upload/vod/20231008-1/33225a8708cebaf180552b04408d6071.jpg', 'https://phimimg.com/upload/vod/20231008-1/831476a3e032bb4a8963e5d58bf49afd.jpg', '<p>Vào những năm 1930 ở Thượng Hải, một cô gái văn phòng trẻ phải lòng một công nhân nhà máy cùng công ty.</p>', 'Full', 1, 'single', 'completed', 20, 1997, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Leon Lai","avatar":""},{"name":"Wu Chien-Lien","avatar":""},{"name":"Ge You","avatar":""},{"name":"Anita Mui","avatar":""},{"name":"Annie Wu","avatar":""},{"name":"Huang Lei","avatar":""},{"name":"Zhiwen Wang","avatar":""},{"name":"Liu Changwei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324538);
