INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-dia-hung-tam', 'Thiên Địa Hùng Tâm', 'Armageddon', 'https://phimimg.com/upload/vod/20231006-1/a62399f0c52b9570aefb3f9c6ff24168.jpg', 'https://phimimg.com/upload/vod/20231006-1/2a23042af074cc9e6bdb1b379d8d875d.jpg', '<p>Bác sĩ Jin Tiesheng là một trong “Mười nhà lãnh đạo tương lai” được Liên hợp quốc bầu chọn. Năm 1997, anh ta được sắp đặt để bị sát hại. Sau khi một số thủ lĩnh khác lần lượt chết, cảnh sát đã cố gắng bảo vệ Jin Tiesheng, người đang đau buồn vì mất bạn gái Adele, vì vậy anh ta từ chối sự bảo vệ của MI6 và chỉ nhờ bạn cùng lớp từ trường tiểu học CID Jiao Dapeng đi cùng. Thông qua cuộc điều tra của Jiao Dapeng và MI6, nhiều nghi phạm đã bị loại trừ. Tuy nhiên, Jin Tiesheng lại gặp phải điều gì đó kỳ lạ. Adele được cho là đã chết xuất hiện và để lại cho anh rất nhiều thông tin. Cô ấy cũng để lại cho Jin và Jiao vé đi Praha, trong đó có lẽ có câu trả lời…</p>', 'Full', 1, 'single', 'completed', 31, 1997, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Michelle Reis","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Claudia Lau Sin-Yi","avatar":""},{"name":"Vincent Kok","avatar":""},{"name":"Michael Lui Mai-Go","avatar":""},{"name":"Jessica Chow Jing","avatar":""},{"name":"Kim Yip Kwong-Kim","avatar":""},{"name":"Angel Wong Chui-Ling","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324538);
