INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-pha-tham-o', 'Cuộc Phá Tham Ô', 'Island Of Greed', 'https://phimimg.com/upload/vod/20231006-1/3bc26eaabeedf5d1496e0463c7769e09.jpg', 'https://phimimg.com/upload/vod/20231006-1/ba38299b3314548cfc06d0c2416e3eea.jpg', '<p>Cuộc Phá Tham Ô là câu chuyện xoay quanh màn đối đầu cực kỳ gay cấn giữa cục trưởng cục điều tra của Bộ tư pháp Phương Quốc Huy (Lưu Đức Hoa) và ông trùm xã hội đen Chu Triêu Tiên (Lương Gia Huy), người rất có thế lực tại trong thế giới ngầm của Đài Loan. Đễ dễ bề cho việc điều tra, Phương Quốc Huy thành lập một tổ điều an băng đảng tội phạm cho Chu đứng đầu. Tuy nhiên, anh vấp phải nhiều khó khăn vì Chu Triêu Viên không chỉ là ông trùm xã hội đen với 2 triệu thành viên mà còn có gia tài kếch xù. Đặc biệt, Chu Triêu Viên còn có khả năng thao túng giới chính trị khi mua chuộc được nhiều viên chức mẫn cán....</p>', 'Full', 1, 'single', 'completed', 19, 1997, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Annie Wu","avatar":""},{"name":"Paulyn Sun","avatar":""},{"name":"Kelly Kuo","avatar":""},{"name":"Winston Chao","avatar":""},{"name":"Lee Lichun","avatar":""},{"name":"King Shih-Chieh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324538);
