INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-tac-1997', 'Không Tặc', 'Con Air', 'https://phimimg.com/upload/vod/20230917-1/0c4dd97428a37013df04ae611cd0801f.jpg', 'https://phimimg.com/upload/vod/20230917-1/25555320947de0a09312e22cbd80cd02.jpg', '<p><span style="font-family: ">Cameron - một phạm nhân trên đường trở về nhà sau vài năm ở tù vì đánh nhau để bảo vệ vợ mình. Dường như mọi sự đã diễn ra không đúng như mong đợi của Cameron khi chiếc phi cơ Con Air bị đám tù nhân có âm mưu tẩu thoát khống chế. Vô tình anh bị kẹt giữa hai phe đối địch, một bên là những tên tội phạm thuộc loại tàn ác nguy hiểm nhất, một bên là những tay cảnh sát mà anh không hề muốn hợp tác chút nào...</span></p>', 'Full', 1, 'single', 'completed', 20, 1997, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"John Cusack","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Dave Chappelle","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"Monica Potter","avatar":""},{"name":"Landry Allbright","avatar":""},{"name":"Rachel Ticotin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324538);
