INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan', 'Thám Tử Lừng Danh Conan', 'Detective Conan', 'https://phimimg.com/upload/vod/20240310-1/2a39971cc29c2802259b918eb437a45b.jpg', 'https://phimimg.com/upload/vod/20240310-1/025424cf62248b9a7b54279ef5416e26.jpg', '<p>Phim hoạt hình Conan bắt đầu sau vụ việc xảy ra tại công viên giải trí nổi tiếng Tropical Land tại khu tàu lượn siêu tốc. Kudo đang điều tra một trong hai người đàn ông có vẻ ngoài khả nghi được cho là nghi phạm trong vụ việc. Anh ta bị tấn công bởi một trong số họ có mật danh là Gin và đồng đội của anh ta tên là Vodka. Sau khi đánh Shinichi, Gin đã đưa cho anh ta một loại thuốc mà sau này được gọi là APTX 4869 để giết anh ta. Trên thực tế, chất độc có một tác dụng phụ hiếm gặp, biến Shinichi từ một cơ thể trưởng thành thành một đứa trẻ thay vì giết chết. Sau sự cố quan trọng, Shinichi về nhà và lấy tên là Conan Edogawa sau khi bị người bạn thời thơ ấu Ran gây áp lực. Shinichi đã cố gắng che giấu danh tính bí mật của mình với những người anh quan tâm để điều tra về tổ chức Áo Đen.</p>', 'Tập 1206', 1500, 'hoathinh', 'ongoing', 123, 1996, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Kenichi Ogata","avatar":""},{"name":"Yukiko Iwai","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"Chafurin","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["名侦探柯南 警察学校篇 疯狂警察故事","名侦探柯南 本厅刑警恋爱物语","Meitantei Conan","Detective Conan","名探偵コナン 警察学校編 Wild Police Story","ยอดนักสืบจิ๋วโคนัน เดอะซีรีส์","Detektif Konan","Case Closed","Great Detective Conan","Detective Conan: Conan vs. The Black Organization","Case Closed: One Truth Prevails","Case Closed (Detective Conan)","Detective Conan: Rivals of the Great Detective","名探偵コナン"]', 1784690324538);
