INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-lung-danh-conan', 'Thám Tử Lừng Danh Conan', 'Detective Conan', 'thám tử lừng danh conan detective conan minami takayama kappei yamaguchi wakana yamazaki akira kamiya rikiya koyama megumi hayashibara kenichi ogata yukiko iwai wataru takagi ikue otani chafurin 名侦探柯南 警察学校篇 疯狂警察故事 名侦探柯南 本厅刑警恋爱物语 meitantei conan detective conan 名探偵コナン 警察学校編 wild police story ยอดนักสืบจิ๋วโคนัน เดอะซีรีส์ detektif konan case closed great detective conan detective conan: conan vs. the black organization case closed: one truth prevails case closed (detective conan) detective conan: rivals of the great detective 名探偵コナン', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-noi-mat-tham', 'Đại Nội Mật Thám', 'Forbidden City Cop', 'https://phimimg.com/uploads/movies/20260713/dai-noi-mat-tham-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/dai-noi-mat-tham-poster.webp', '<p>Phim Đại Nội Mật Thám là bộ phim hài của Châu Tình Trì. Nội dung phim xoay quanh Cung, Hỷ, Phát, Tài là bốn cao thủ hoàng cung chuyên bảo vệ Hoàng Thượng. Trong đó Phát là người tuy không biết võ công nhưng đầu óc lanh lợi, phát minh ra được những món đồ kỳ lạ. Nhưng cuối cùng không được vua trọng dụng bị đưa về làm một người thường dân. Lúc này nước Kim dựa vào thi thể của một người ngoài hành tinh đề lừa gạt nhà vua và hãm hại ông. Ba vị cao thủ kia đều hy sinh chỉ còn Phát nhờ phát minh của mình cứu được nhà vua. Nước Kim đành cho người trà trộn tìm cách quyến rũ Phát, Phát cùng vợ mình tương kế tựu kế tìm cách bắt kẻ gian.</p>', 'Full', 1, 'single', 'completed', 45, 1996, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Carman Lee Yeuk-Tung","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Cheung Tat-Ming","avatar":""},{"name":"Tats Lau Yee-Tat","avatar":""},{"name":"Lee Lik-Chi","avatar":""},{"name":"Alvina Kong Yan-Yin","avatar":""},{"name":"Kingdom Yuen King-Tan","avatar":""},{"name":"Mimi Chu Mai-Mai","avatar":""},{"name":"Lee Kin-Yan","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"Yuen Shun-Yi","avatar":""},{"name":"Chik King-Man","avatar":""},{"name":"Poon Hang-Sang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Dai lap mat tam 008","Daai laap mat taam 008","Forbidden City Cop","大內密探零零發"]', 1784690324538);
