INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-dinh-toi-thuong', 'Quyết Định Tối Thượng', 'Executive Decision', 'https://phimimg.com/upload/vod/20260608-1/e6771ef257dffdd6a1f5582615e4006c.jpg', 'https://phimimg.com/upload/vod/20260608-1/aee61589804aaa3002a34fc48031c58e.jpg', '<p>Một chiếc máy bay Boeing dân dụng 747 đã bị đánh cướp bởi bọn không tặc, tính mạng của các hành khách nằm trong tình trạng vô cùng nguy hiểm, không những vậy trên máy bay còn chứa đựng một quả bom có sức công phá khổng lồ. Lực lượng quân đội Mỹ lập tức triển khai một hành động chưa từng có: đột nhập trên không vào máy bay, cứu các con tin cũng như không chế quả bom...</p>', 'Full', 1, 'single', 'completed', 21, 1996, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kurt Russell","avatar":""},{"name":"Steven Seagal","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Joe Morton","avatar":""},{"name":"David Suchet","avatar":""},{"name":"BD Wong","avatar":""},{"name":"Len Cariou","avatar":""},{"name":"Whip Hubley","avatar":""},{"name":"Andreas Katsulas","avatar":""},{"name":"Mary Ellen Trainor","avatar":""},{"name":"Marla Maples","avatar":""},{"name":"J.T. Walsh","avatar":""},{"name":"Ingo Neuhaus","avatar":""},{"name":"William James Jones","avatar":""},{"name":"Nicholas Pryor","avatar":""},{"name":"Stanley","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Momento crítico","Kriitiline otsus","Ratkaisun hetket","Ordre fra høyeste hold","Decisão Crítica","Decizie Executiva","Konačna odluka","Kriticna tocka","Einsame Entscheidung - Executive Decision","Executive Decision"]', 1784690324538);
