INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-sat', 'Tà Sát', 'The Imp', 'https://phimimg.com/upload/vod/20260604-1/3a89ef82fece3766d25b204b430a3b5a.jpg', 'https://phimimg.com/upload/vod/20260604-1/635f0cb8aab134bfb3f123c2912ec990.jpg', '<p>Ching Kwok Shan nhận được một lá thư từ chị gái sinh đôi Vui vẻ, cảm thấy có điều gì đó tồi tệ đã xảy ra (cô ấy có khả năng ngoại cảm của đôi) và chia sẻ một chiếc xe với một đoàn làm phim để đến nhà trọ từ nơi bức thư đến. Đội ngũ này bao gồm đạo diễn Mark, người dẫn chương trình Angie, và nhà quay phim King Kong và Cass, và tóm tắt của họ là quay một nghi lễ thổ dân hiếm thấy liên quan đến sự hy sinh. Họ vào khách sạn do góa phụ Jing Hua gợi cảm (và rõ ràng nham hiểm), và những điều đáng lo ngại sắp xảy ra.</p>', 'Full', 1, 'single', 'completed', 30, 1996, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Emiko  Ishizuka","avatar":""},{"name":"Ho Kei-Yung","avatar":""},{"name":"Ruby Wong Jo-Yi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["孽欲追击档案之邪杀"]', 1784690324538);
