INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-xuoi-van-ly', 'Ai xuôi vạn lý', 'The Long Journey', 'https://phimimg.com/upload/vod/20250401-1/9f8963ed14da4e755cbda01f97ca7c3a.jpg', 'https://phimimg.com/upload/vod/20250401-1/445bfd62084ed76dfa42e97524bb8b09.jpg', '<p>Ai xuôi vạn lý là bộ phim về đề tài thời hậu chiến của đạo diễn Lê Hoàng, phim được thực hiện năm 1996 do Hãng phim Giải Phóng sản xuất. Đây là một trong những bộ phim điện ảnh được đánh giá là thành công nhất của Lê Hoàng và là một trong những bộ phim kinh điển của nền điện ảnh Việt Nam trong thời kỳ Đổi mới</p>', 'Full', 1, 'single', 'completed', 34, 1996, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Công Ninh","avatar":""},{"name":"Mộc Miên","avatar":""},{"name":"Lê Mai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Ai Xuôi Vạn Lý","Ai xuôi vạn lý"]', 1784690324538);
