INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('qua-den-thanh-pho-thien-than', 'Quạ Đen: Thành Phố Thiên Thần', 'The Crow: City Of Angels', 'quạ đen: thành phố thiên thần the crow: city of angels vincent perez mia kirshner iggy pop thomas jane richard brooks thuy trang vincent castellanos tracey ellis beverley mitchell alan gelfant shelly desai holley chant ian dury kerry rossall eric acosta aaron thell smith chino moreno stephen the crow 2: city of angels the crow 2 the crow ii: city of angels el cuervo 2 ciudad de angeles il corvo 2 - la città degli angeli the crow ii - die rache der krähe the crow ii vrána 2: město andělů the crow 2 - die rache der krähe the crow 2 die rache der kraehe the crow: city of angels', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-thu-anh-hung-liet-truyen', 'Thiên Thu Anh Hùng Liệt Truyện', 'Passengers And Swordsman', 'https://phimimg.com/upload/vod/20260126-1/76f4650b7f7784c396f3436b85191cea.jpg', 'https://phimimg.com/upload/vod/20260126-1/44699e178563c59f78ee07f7750ad098.jpg', '<p>Một đao vung lên vang danh thiên hạ, ôm kiếm vào đời thực hiện chí lớn. Nhưng rồi xác phơi đầu phố chẳng ai hỏi han, mưa phùn hiu quạnh không kẻ thù tai. Chỉ với bốn câu thơ ngắn ngủi đã lột tả được nỗi cô độc và bất lực ẩn sâu trong lòng những anh hùng hiệp khách. Trong dòng chảy lịch sử, những kiếm khách, du hiệp hành tẩu giang hồ bằng võ nghệ, hành hiệp trượng nghĩa đã xuất hiện từ chính sử, dã sử cho đến tiểu thuyết dân gian. Họ là biểu tượng của anh hùng thời đại, vì dân thỉnh mệnh, trừ ác diệt tà. Họ đến từ mọi tầng lớp, mỗi người một xuất thân, có người lưu danh muôn thuở, kẻ lại bị dòng đời lãng quên, nhưng những gì họ làm đều tạo nên những chấn động nhất định tại thời điểm đó. Chúng ta gọi nhóm người lấy bốn bể là nhà, tiếu ngạo giang hồ này là &#39;Lộ Khách và Đao Khách&#39;. Họ dùng bản lĩnh để bôn ba khắp chốn, vẻ ngoài tiêu sái bất cần, hào khí ngất trời. Thế nhưng, liệu sau lưng họ có thực sự là một cuộc đời &#39;không nhuốm bụi trần&#39; – chỉ cần một hớp rượu mạnh, một nhát chém rồng, là ngàn vạn sầu tình theo gió bay đi như tiểu thuyết mô tả? &#39;Tự cổ anh hùng giai khổ não, thiên cổ lưu danh hữu kỷ nhân&#39; (Từ xưa anh hùng đều khổ não, ngàn năm lưu danh được mấy người)...</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 20, 1996, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Khải","avatar":""},{"name":"Viên Khiết Oánh","avatar":""},{"name":"Quan Vịnh Hà","avatar":""},{"name":"Quách Tấn An","avatar":""},{"name":"Quan Lễ Kiệt","avatar":""},{"name":"Lữ Tụng Hiền","avatar":""},{"name":"Ngọ Mã","avatar":""},{"name":"Tiền Tiểu Hào","avatar":""},{"name":"Trương Triệu Huy","avatar":""},{"name":"Ông Hồng","avatar":""},{"name":"Cao Hùng","avatar":""},{"name":"Ngô Nghị Tướng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["路客与刀客","千秋英烈传"]', 1784690324538);
