INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-cua-chien-binh', 'Ngày Của Chiến Binh', 'Day Of The Warrior', 'https://phimimg.com/upload/vod/20250901-1/33ac31fbe133010dc5f7fc0a90be8a5e.jpg', 'https://phimimg.com/upload/vod/20250901-1/89fa2512f0a5e2f15f26d82d3984e628.jpg', '<p>L.E.T.H.A.L. (Legion to Ensure Total Harmony and Law) đang truy lùng một tên tội phạm khét tiếng chỉ được biết đến với biệt danh “Chiến Binh”. Trong khi điều tra đường dây buôn lậu kim cương, trộm cắp nghệ thuật và sản xuất phim khiêu dâm của hắn, các đặc vụ phát hiện rằng hắn đã đột nhập vào cơ sở dữ liệu tuyệt mật và đánh cắp toàn bộ hồ sơ của họ. Với sự hỗ trợ của sư phụ võ thuật Fu, ba nữ đặc vụ Tiger, Willow và Cobra tiếp nhận nhiệm vụ — đồng thời cũng không bỏ lỡ bất kỳ cơ hội nào để… cởi bỏ áo bikini của mình.</p>', 'Full', 1, 'single', 'completed', 24, 1996, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Light","avatar":""},{"name":"Cristian Letelier","avatar":""},{"name":"Julie Strain","avatar":""},{"name":"Julie K. Smith","avatar":""},{"name":"Shae Marks","avatar":""},{"name":"Marcus Bagwell","avatar":""},{"name":"Raye Hollitt","avatar":""},{"name":"Rodrigo Obregón","avatar":""},{"name":"Justin Melvey","avatar":""},{"name":"Gerald Okamura","avatar":""},{"name":"Richard Cansino","avatar":""},{"name":"Cassidy Phillips","avatar":""},{"name":"Tammy Parks","avatar":""},{"name":"Darren Wise","avatar":""},{"name":"Ted Prior","avatar":""},{"name":"Ron Browning","avatar":""},{"name":"Kevin Eastman","avatar":""},{"name":"De","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', 