INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-chuyen-tau-toc-hanh-ngan-ha', 'Doraemon: Nobita và Chuyến Tàu Tốc Hành Ngân Hà', 'Doraemon: Nobita and the Galaxy Super-express', 'doraemon: nobita và chuyến tàu tốc hành ngân hà doraemon: nobita and the galaxy super-express nobuyo oyama noriko ohara michiko nomura kaneta kimotsuki kazuya tatekabe sachiko chijimatsu ryoichi tanaka junichi sugawara kaneto shiozawa kazue ikura minoru yada sakura tange mitsuaki madono yosuke akimoto kenji utsumi rei sakuma koichi 銀河超特急 doraemon nobita to ginga cho tokkyu nobita and the galaxy super-express doraemon: nobita and galactic express 大雄與銀河超特快列車 도라에몽: 노비타와 은하초특급 ドラえもん　のび太と銀河超特急 哆啦a夢：大雄與銀河超特急 doraemon the movie: galaxy super express 映画ドラえもん のび太と銀河超特急 電影哆啦a夢：大雄與銀河超特快列車 ドラえもん のび太と銀河超特急', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-don-doc', 'Cảnh Sát Đơn Độc', 'Lone Star', 'https://phimimg.com/upload/vod/20250520-1/e9aad9ce0da56bb4b53ba0223ad64377.jpg', 'https://phimimg.com/upload/vod/20250520-1/f28b927161fd0c118956ebaaa6b5dda4.jpg', '<p>Sam Deeds là cảnh sát trưởng Hạt Rio, Texas, con trai của cựu cảnh sát trưởng Buddy Deeds. Khi mấy anh lính của một đồn binh gần đó phát hiện một xác người, họ gọi Sam tới để điều tra, các dấu vết cho thấy đây là Charlie Wade, cựu cảnh sát trưởng ác ôn, tiền nhiệm của Buddy và có hiềm khích với Buddy khiến Sam nghĩ chính cha anh là thủ phạm giết Wade. Cuộc điều tra dẫn anh về quá khứ với những bí ẩn sâu kín, cho anh hiểu thêm về cha mình, một huyền thoại của Hạt Rio dưới mắt mọi người, đồng thòi với việc nối lại mối tình xưa với người yêu thời học trò Pilar mà trước đây bị hai gia đình ngăn cấm vì một lý do tới bây giờ anh mới biết...</p>', 'Full', 1, 'single', 'completed', 20, 1996, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chris Cooper","avatar":""},{"name":"Matthew McConaughey","avatar":""},{"name":"Elizabeth Peña","avatar":""},{"name":"Kris Kristofferson","avatar":""},{"name":"Joe Morton","avatar":""},{"name":"Frances McDormand","avatar":""},{"name":"Stephen J. Lang","avatar":""},{"name":"Oni Faida Lampley","avatar":""},{"name":"LaTanya Richardson Jackson","avatar":""},{"name":"Leo Burmester","avatar":""},{"name":"Eleese Lester","avatar":""},{"name":"Richard Coca","avatar":""},{"name":"Miriam Colon","avatar":""},{"name":"Jeff Monahan","avatar":""},{"name":"Eddie Robinson","avatar":""},{"name":"R","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Одинокая звезда","Lone Star"]', 1784690324539);
