INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-dong-kinh-hon', 'Biến Động Kinh Hồn', 'All of a Sudden', 'https://phimimg.com/upload/vod/20250513-1/32fccaa7db6a8ca9446975bf2408505e.jpg', 'https://phimimg.com/upload/vod/20250513-1/f8659616deefd79d949f6d82906dfd46.jpg', '<p>Phim Biến Động Kinh Hồn Ôn Bích Hà không thể gợi cảm hơn với 1 khuôn mặt thiên thần và những đường cong hấp dẫn, Nhậm Đạt Hoa thì hơi khờ khạo nhưng chân chất, có lẽ giới thiệu từng đó là đủ. Còn hung thủ thì đến cuối cùng mới xuất đầu lộ diện.......</p>', 'Full', 1, 'single', 'completed', 19, 1996, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Irene Wan","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Alfred Cheung Kin-Ting","avatar":""},{"name":"Dayo Wong","avatar":""},{"name":"Lam Chiu-Wing","avatar":""},{"name":"Rico Chung Kai-Cheong","avatar":""},{"name":"William Leung Chi-Ming","avatar":""},{"name":"Joe Chu","avatar":""},{"name":"James Tsim Tak-Faat","avatar":""},{"name":"Stephen Poon Tak-Yip","avatar":""},{"name":"Kerrick Wong","avatar":""},{"name":"Fong Yue","avatar":""},{"name":"Leung Kei-Hei","avatar":""},{"name":"Peter Ngor Chi-Kwan","avatar":""},{"name":"Lee Ji-Kei","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["All of a Sudden","驚變"]', 1784690324539);
