INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ba-khong-con', 'Người Đàn Bà Không Con', 'The Childless Woman', 'https://phimimg.com/upload/vod/20250406-1/093be06c6c221268f7abdc4de9aec9ba.jpg', 'https://phimimg.com/upload/vod/20250406-1/c0b023ef7da8fb632cb9147ccbf627d0.jpg', '<p>Bộ phim tái hiện cuộc sống của một làng quê nghèo Việt Nam. Mọi chuyện rắc rối từ khi Hân có bầu với người đàn ông đã có gia đình. Vì không muốn mang tiếng là người phụ nữ không chồng mà chửa, Hân đã thuê một người đàn ông cờ bạc là Tài để làm chồng hờ. Mọi chuyện rắc rối từ khi hai người về sống chung với nhau...</p>', 'Full', 1, 'single', 'completed', 20, 1996, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thúy Loan","avatar":""},{"name":"Huệ Đàn","avatar":""},{"name":"Ngọc Thư","avatar":""},{"name":"Hoa Thúy","avatar":""},{"name":"Trần Nhượng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324539);
