INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-quoc-tieng-ga-trua', 'Tổ Quốc Tiếng Gà Trưa', 'The Homeland And The Noon Rooster''S Call', 'https://phimimg.com/upload/vod/20250406-1/e791f86469e7e6aa011e5300fa6b7954.jpg', 'https://phimimg.com/upload/vod/20250406-1/fbc2ace416587a8305fc148475e07a78.jpg', '<p>Bộ phim chiến tranh Việt Nam &quot;Tổ quốc tiếng gà trưa&quot;, do cố đạo diễn NSND Nguyễn Huy Thành thực hiện, tái hiện hành trình đầy khí phách và đáng tự hào của đồng chí Tôn Đức Thắng. Khi bị trục xuất khỏi lực lượng hải quân vì hành động kéo cờ tham gia phong trào phản chiến, anh lính thủy Tôn Đức Thắng đứng trên ban công một ngôi nhà nhỏ trong con ngõ hẹp ở quân cảng Toulouse. Giữa không gian xa lạ, tiếng gà trưa bất chợt vang lên, gợi nhắc về quê hương, về tuổi thơ bình yên bên xóm làng. Chính từ nỗi nhớ ấy, tinh thần yêu nước và ý chí đấu tranh ngày càng mạnh mẽ trong anh. Không chỉ mang ý nghĩa lịch sử, bộ phim còn là biểu tượng của lòng yêu nước và tinh thần phản kháng, thể hiện khát vọng hòa bình và độc lập của dân tộc Việt Nam.</p>', 'Full', 1, 'single', 'completed', 23, 1996, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hoàng Sơn","avatar":""},{"name":"Sao Mai","avatar":""},{"name":"Mạnh Dung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324539);
