INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-dai-tu-biet', 'Nụ Hôn Dài Từ Biệt', 'The Long Kiss Goodnight', 'https://phimimg.com/upload/vod/20250318-1/f3f9a7e8bae56c96ecedd1555002221b.jpg', 'https://phimimg.com/upload/vod/20250318-1/ec8c39b64c46b50fb8af8258f203ce7d.jpg', '<p>Samantha Caine, người nội trợ ở ngoại ô, là người mẹ lý tưởng của cô con gái 8 tuổi Caitlin. Cô ấy sống ở Honesdale, PA, là một giáo viên trường học và làm món Rice Krispie ngon nhất trong thị trấn. Nhưng khi cô ấy bị một vết sưng trên đầu, cô ấy bắt đầu nhớ lại những phần nhỏ của kiếp trước với tư cách là một đặc vụ tối mật, nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 21, 1996, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Geena Davis","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Yvonne Zima","avatar":""},{"name":"Craig Bierko","avatar":""},{"name":"Tom Amandes","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Patrick Malahide","avatar":""},{"name":"David Morse","avatar":""},{"name":"Joseph McKenna","avatar":""},{"name":"Melina Kanakaredes","avatar":""},{"name":"Dan Warry-Smith","avatar":""},{"name":"Kristen Bone","avatar":""},{"name":"Jennifer Pisana","avatar":""},{"name":"Rex Linn","avatar":""},{"name":"Alan North","avatar":""},{"name":"Edwin Hodge","avatar":""},{"name":"Bill MacDonald","avatar":""},{"name":"Gladys","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Au revoir à jamais","Un largo beso de despedida","بوسه طولانی شب بخیر","롱키스 굿나잇","Tödliche Weihnachten","Прощаль