INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mieng-tra-mieng', 'Ăn Miếng Trả Miếng', 'Eye for an Eye', 'https://phimimg.com/upload/vod/20250318-1/7abb98f52c8f395238bfe7011b173501.jpg', 'https://phimimg.com/upload/vod/20250318-1/a8227c50407e64f91d836a5e04ca433f.jpg', '<p>Đó là thời gian lửa và đá vôi khi người mẹ đau buồn Karen McCann đưa công lý vào tay mình khi một tòa án kangaroo ở Los Angeles không kết án Robert Doob, con quái vật đã hãm hiếp và giết cô con gái 17 tuổi của mình.</p>', 'Full', 1, 'single', 'completed', 14, 1996, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sally Field","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Beverly D''Angelo","avatar":""},{"name":"Charlayne Woodard","avatar":""},{"name":"Joe Mantegna","avatar":""},{"name":"Olivia Burnette","avatar":""},{"name":"Alexandra Kyle","avatar":""},{"name":"Keith David","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Natalija Nogulich","avatar":""},{"name":"Armin Shimerman","avatar":""},{"name":"Nicholas Cascone","avatar":""},{"name":"Darrell Larson","avatar":""},{"name":"Cynthia Rothrock","avatar":""},{"name":"Wan","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Oeil pour oeil","Eye for an Eye - Auge um Auge","Öga för öga","עין תחת עין","Eye for an Eye"]', 1784690324539);
