INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xich-lo', 'Xích lô', 'Cyclo', 'https://phimimg.com/upload/vod/20250315-1/6e0a0a3412ee3555f9c2d7010ae2b80d.jpg', 'https://phimimg.com/upload/vod/20250315-1/c7f524e210e4e3d5f0dca1da7a20549c.jpg', '<p>Theo chân một tài xế xích lô trẻ tuổi trên con đường sa ngã vì nghèo đói của mình vào tội phạm ở Thành phố Hồ Chí Minh hiện đại. Cuộc đấu tranh của cậu bé để kiếm sống cho hai chị gái và ông nội của mình trên những con phố tồi tệ của thành phố dẫn đến tội phạm vặt thay mặt cho một Quý bà bí ẩn mà cậu thuê xích lô.</p>', 'Full', 1, 'single', 'completed', 9, 1996, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Le Van Loc","avatar":""},{"name":"Tony Leung","avatar":""},{"name":"Nhu Quynh","avatar":""},{"name":"Hoàng Phúc","avatar":""},{"name":"Ngo Vu Quang Hal","avatar":""},{"name":"Tuyet Ngan Nguyen","avatar":""},{"name":"Doan Viet Ha","avatar":""},{"name":"Bjuhoang Huy","avatar":""},{"name":"Vo Vinh Phuc","avatar":""},{"name":"Le Kinh Huy","avatar":""},{"name":"Tran Nu Yen Khe","avatar":""},{"name":"Thinh Trinh","avatar":""},{"name":"Chu Hung","avatar":""},{"name":"Nguyen Van Day","avatar":""},{"name":"Manh Cuong Tran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Cyclo","Xích lô"]', 1784690324539);
