INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xich-lo', 'Xích lô', 'Cyclo', 'xích lô cyclo le van loc tony leung nhu quynh hoàng phúc ngo vu quang hal tuyet ngan nguyen doan viet ha bjuhoang huy vo vinh phuc le kinh huy tran nu yen khe thinh trinh chu hung nguyen van day manh cuong tran cyclo xích lô', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-gt', 'Bảy Viên Ngọc Rồng GT', 'Dragon Ball GT', 'https://phimimg.com/upload/vod/20250314-1/872357e853d020d8d213ea3e11817f21.jpg', 'https://phimimg.com/upload/vod/20250314-1/89144614be93cc9c6bae2d9a227069e0.jpg', '<p>Mười năm đã trôi qua kể từ khi Goku rời xa bạn bè và gia đình để rèn luyện kỹ năng. Nhưng rồi, Goku bất ngờ trở nên bất lực trước sức mạnh thần bí của ngọc rồng và một điều ước tai hại do Hoàng đế Pilaf xảo quyệt vô tình tạo ra. Điều ước đó đã biến Goku trở lại thành một đứa trẻ! Goku, cùng với Trunks và cháu gái Pan, lên đường bay vào vũ trụ để tìm kiếm những viên Ngọc Rồng Sao Đen bí ẩn. Nhưng những viên ngọc rồng này ẩn chứa một bí mật chết người: nếu không được thu thập đủ trong vòng một năm, Trái Đất sẽ bị hủy diệt.</p>', 'Hoàn Tất (64/64)', 64, 'hoathinh', 'completed', 14, 1996, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masako Nozawa","avatar":""},{"name":"Yuko Minaguchi","avatar":""},{"name":"Takeshi Kusao","avatar":""},{"name":"Bin Shimada","avatar":""},{"name":"Atsushi Kisaichi","avatar":""},{"name":"Ryo Horikawa","avatar":""},{"name":"Toshio Furukawa","avatar":""},{"name":"Miki Ito","avatar":""},{"name":"Hiromi Tsuru","avatar":""},{"name":"Daisuke Gori","avatar":""},{"name":"Joji Yanami","avatar":""},{"name":"Mayumi Tanaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["龙珠GT","Dragon Ball GT","Dragoi Bola","Bola de Dragón GT","דרגון בול GT","דרגון בול ג''יטי","드래곤 볼 GT","Драконий жемчуг БП","ดราก้อนบอล จีที","ドラゴンボールGT"]', 1784690324539);
