INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-doi-giay-mau', 'Những Đôi Giày Máu', 'Horrible High Heels', 'https://phimimg.com/upload/vod/20241014-1/1db13ef932dfa836e6d55eb589e6067b.jpg', 'https://phimimg.com/upload/vod/20241014-1/04b30a3a12cbcadd2f0e10c11d6a6ea2.jpg', '<p>Một tên biến thái nào đó đã cạo lông các xác chết rồi lột da để đóng giày cao gót. CÔng việc kinh doanh bỗng chốc phát triển chóng mặt do mọi người ưa chuộng loại chất liệu có một không hai này. Cầu tăng nên cung cũng phải tăng, hắn cần có thêm nhiều da tốt để đóng giày</p>', 'Full', 1, 'single', 'completed', 10, 1996, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"成奎安","avatar":""},{"name":"Dick Wei","avatar":""},{"name":"Billy Chow Bei-Lei","avatar":""},{"name":"Suen Tong","avatar":""},{"name":"Chow Yuk-Ling","avatar":""},{"name":"Yue Shut-Man","avatar":""},{"name":"Lin Hsiao-Lu","avatar":""},{"name":"Lam Chak-Ming","avatar":""},{"name":"Siu Yuk-Lung","avatar":""},{"name":"梁琛榮","avatar":""},{"name":"洪鋒","avatar":""},{"name":"Law Kwai-Ying","avatar":""},{"name":"Wong Yin-Cheuk","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ren pi guo zheng xie","人皮高跟鞋","Bloody Shoe"]', 1784690324539);
