INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boi-tham-vien', 'Bồi Thẩm Viên', 'The Juror', 'https://phimimg.com/upload/vod/20240711-1/c84b4827e4c4f564ab2fbbe12326f1e5.jpg', 'https://phimimg.com/upload/vod/20240711-1/7ec78d51255d31c009aa4673ac7dbf5a.jpg', '<p>Khi ông trùm xã hội đen của mình bị xét xử vì tội giết người, một tên côn đồ được mệnh danh là Giáo viên nói với Annie Laird rằng cô phải nói chuyện với các bồi thẩm đoàn của mình để đưa ra phán quyết vô tội, ngụ ý rằng hắn sẽ giết con trai cô là Oliver nếu cô thất bại. Cô cố gắng làm được điều này, nhưng khi biết rõ rằng bọn cướp có thể muốn khiến cô im lặng mãi mãi, cô gửi Oliver ra nước ngoài và cố gắng thu thập bằng chứng về âm mưu chống lại cô, thiết lập một cuộc đối đầu cuối cùng.</p>', 'Full', 1, 'single', 'completed', 10, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Demi Moore","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Joseph Gordon-Levitt","avatar":""},{"name":"Anne Heche","avatar":""},{"name":"James Gandolfini","avatar":""},{"name":"Lindsay Crouse","avatar":""},{"name":"Tony Lo Bianco","avatar":""},{"name":"Michael Constantine","avatar":""},{"name":"Matt Craven","avatar":""},{"name":"Todd Susman","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
