INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tu-da', 'Nhà Tù Đá', 'The Rock', 'https://phimimg.com/upload/vod/20231030-1/cc21f5fd6682e88e4158081774d56569.jpg', 'https://phimimg.com/upload/vod/20231030-1/1be30aa0f0cb7bf03d18b48e65237253.jpg', '<p>Nhà Tù Đá, The Rock thuộc thể loại hành động, cuốn hút người xem từ đầu tới cuối bằng những cảnh hoành tráng. Nicolas Cage có cơ hội thử sức với thể loại này lần đầu tiên bên cạnh những ngôi sao gạo cội như Ed Harris hay Sean Connery huy động một số lính thuộc lực lượng đặc nhiệm hải quân Mỹ SEAL tham gia diễn xuất. The Rock có sự kết hợp nhuần nhuyễn giữa cốt truyện hẫp dẫn, nhiều cảnh hành động, những pha hài hước, điểm vài nét lãng mạn, hiệu ứng hình ảnh và hiệu ứng âm thanh tuyệt vời, bộ phim xứng đáng là một trong những quả bom tấn của thể loại hành động trong nhiều thập kỷ qua.</p>', 'Full', 1, 'single', 'completed', 11, 1996, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sean Connery","avatar":""},{"name":"Nicolas Cage","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"William Forsythe","avatar":""},{"name":"David Morse","avatar":""},{"name":"John Spencer","avatar":""},{"name":"Michael Biehn","avatar":""},{"name":"Vanessa Marcil","avatar":""},{"name":"Claire Forlani","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Gregory Sporleder","avatar":""},{"name":"John C. McGinley","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Steve Harris","avatar":""},{"name":"Greg Collins","avatar":""},{"name":"Brendan Kelly","avatar":""},{"name":"Danny Nucci","avatar":""},{"name":"Cel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7