INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buom-phuong', 'Bướm Phượng', 'Swallowtail Butterfly', 'https://phimimg.com/upload/vod/20231108-1/998fc2bfba39aa39390c45669ebe3997.jpg', 'https://phimimg.com/upload/vod/20231108-1/2b0194f47aac36ded0e1a7e44b64ee72.jpg', '<p>Một khu công nghiệp của Nhật Bản được đặt tên là Yentown vì nhiều người nhập cư đến để kiếm tiền và hy vọng trở về nhà giàu có. Một nhóm nhỏ người ở Yentown cố gắng làm việc cùng nhau để tồn tại, có một cô gái tên Ageha không có gia đình, Glico gái điếm, Fei Hong, một người nhập cư nghèo từ Thượng Hải, Arrow, một cựu võ sĩ quyền anh từ Mỹ và Ren, anh chàng bí ẩn. dường như biết quá nhiều về súng. Vận may sẽ đến với họ khi họ tìm thấy một cuộn băng rằng chúng ta sẽ giúp họ trở nên giàu có nhưng cùng với đó là những rắc rối về tiền bạc sẽ luôn theo sau.</p>', 'Full', 1, 'single', 'completed', 9, 1996, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Ayumi Ito","avatar":""},{"name":"Yosuke Eguchi","avatar":""},{"name":"Chara","avatar":""},{"name":"Hiroshi Mikami","avatar":""},{"name":"Andy Hui","avatar":""},{"name":"Atsuro Watabe","avatar":""},{"name":"Kaori Momoi","avatar":""},{"name":"Tomoko Yamaguchi","avatar":""},{"name":"Nene Otsuka","avatar":""},{"name":"Yoriko Doguchi","avatar":""},{"name":"Mickey Curtis","avatar":""},{"name":"Tetsu Watanabe","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Ken Enomoto","avatar":""},{"name":"Toshiyuki Kitami","avatar":""},{"name":"Kenji Kohashi","avatar":""},{"name":"Shiek Mahmud-Bey","avatar":""},{"name":"Ken Mitsui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324539);
