INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-de-an-may', 'Hoàng Đế Ăn Mày', 'Hoàng Đế Ăn Mày', 'https://phimimg.com/upload/vod/20240711-1/1fa8ab698d94847033ba7074b955e47e.jpg', 'https://phimimg.com/upload/vod/20240711-1/ac76c8b0265c80fc395297d29af9582b.jpg', '<p><em>Trong lịch sử, Chu Nguyên Chương được biết đến là vị vua tàn bạo, máu lạnh, giết người không ghê tay kể cả với những người từng đầu ấp tay gối với mình. Theo các sử liệu ghi lại, Chu Nguyên Chương và Mã Hoàng hậu có tình cảm rất sâu đậm, cả hai đều dành cho nhau sự tôn trọng. Tuy nhiên, vị Hoàng đế khai sáng nhà Minh này vẫn có tam cung lục viện với 42 phi tần, chưa kể đến các Quý nhân, Chiêu nghi, Tiệp dư khác.</em></p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 18, 1996, 'Lồng Tiếng', 'HD', 'Đài Loan', 0, '[{"name":"Hà Gia Kính","avatar":""},{"name":"Dương Lệ Thanh","avatar":""},{"name":"Ngô Thiên Tâm","avatar":""},{"name":"Lý Chí Hy","avatar":""},{"name":"Tống Đạt Dân","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324539);
