INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gilmore-tay-golf-cu-khoi', 'Gilmore Tay Golf Cừ Khôi', 'Happy Gilmore', 'https://phimimg.com/upload/vod/20240905-1/a74495916065e0e07c7a63c085dd7d1a.jpg', 'https://phimimg.com/upload/vod/20240905-1/ac3a0c1f92f53e6de1608a35a2f2f2f3.jpg', '<p>Vận động viên khúc côn cầu thất bại trở thành tay golf xuất chúng. Anh quyết tâm giành chiến thắng trong giải đấu PGA và dùng tiền thưởng cứu lấy ngôi nhà của bà mình.</p>', 'Full', 1, 'single', 'completed', 12, 1996, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Frances Bay","avatar":""},{"name":"Carl Weathers","avatar":""},{"name":"Allen Covert","avatar":""},{"name":"Robert Smigel","avatar":""},{"name":"Bob Barker","avatar":""},{"name":"Richard Kiel","avatar":""},{"name":"Dennis Dugan","avatar":""},{"name":"Joe Flaherty","avatar":""},{"name":"Lee Trevino","avatar":""},{"name":"Kevin Nealon","avatar":""},{"name":"Verne Lundquist","avatar":""},{"name":"Jared Van Snellenberg","avatar":""},{"name":"Ken Camroux-Taylor","avatar":""},{"name":"Rich Elw","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324539);
