INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('te-tuong-luu-gu', 'Tế tướng Lưu Gù', 'Prime Minister Liu Luo Guo', 'https://phimimg.com/upload/vod/20240902-1/b86e43fa85af58605149a19364733d6c.jpg', 'https://phimimg.com/upload/vod/20240902-1/c4fa37e1235ea58fa71b7df7aa06672c.jpg', '<p>Tế tướng Lưu Gù là một bộ phim của điện ảnh Trung Quốc kể về Lưu Dung, một vị quan yêu nước thương dân, trung thành với nhà vua. Nhưng vì ở lưng có một chỗ bị gù nên được gọi là Lưu Gù. Bộ phim lấy bối cảnh thời nhà Thanh.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 10, 1996, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Baotian","avatar":""},{"name":"Wang Gang","avatar":""},{"name":"張國立","avatar":""},{"name":"鄧婕","avatar":""},{"name":"Li Ding","avatar":""},{"name":"Yu Li","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324539);
