INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-den-nhi-do-4-vua-bip-tai-xuat-giang-ho', 'Nhất Đen Nhì Đỏ 4 - Vua Bịp Tái Xuất Giang Hồ', 'Who''s The Winner 4', 'https://phimimg.com/upload/vod/20240609-1/42e266582ca66dcb4f5596b12da65f29.jpg', 'https://phimimg.com/upload/vod/20240609-1/eee0e1bfb75c69875df9acbfe1aa45ef.jpg', '<p><em>Vào một ngày năm 1928, Đổ Thần Trung Quốc Long Tứ ra tù và đi đến Thượng Hải với hai bàn tay trắng. Trên chuyến xe lửa đến Thượng Hải, ngồi cùng toa với Long Tứ toàn là những tay cờ bạc lừng danh trong làng bịp. Cũng trên chuyến xe đó, trong toa xe đó, những ân oán của luật hè phố mạnh được yếu thua bắt đầu manh nha. Long Tứ và đám người kia kết làm anh em, thề có phú cùng hưởng, có họa cùng mang, đến Thượng Hải đánh thiên hạ. Một rừng không thể hai cọp, một giang sơn không thể có hai lãnh chúa. Cây càng cao thì gió càng mạnh. Giữa huynh đệ với nhau, ai mất, ai được, ai hơn, ai thua?</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 1996, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Tạ Hiền","avatar":""},{"name":"Mễ Tuyết","avatar":""},{"name":"Lưu Tùng Nhân","avatar":""},{"name":"Diệp Đồng","avatar":""},{"name":"Dương Cung Như","avatar":""},{"name":"Cao Hùng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324539);
