INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-den-nhi-do-4-vua-bip-tai-xuat-giang-ho', 'Nhất Đen Nhì Đỏ 4 - Vua Bịp Tái Xuất Giang Hồ', 'Who''s The Winner 4', 'nhất đen nhì đỏ 4 - vua bịp tái xuất giang hồ who''s the winner 4 tạ hiền mễ tuyết lưu tùng nhân diệp đồng dương cung như cao hùng ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-kim-binh-mai', 'Tân Kim Bình Mai', 'New Jin Pin Mei', 'https://phimimg.com/upload/vod/20240618-1/55001f83bb310ddb68bec820ffd9f95d.jpg', 'https://phimimg.com/upload/vod/20240618-1/16e679df8904032a86f22454567678ed.jpg', '<p>Cuộc đời nhiều tội ác và trụy lạc của nhân vật Tây Môn Khánh vốn là chủ một hiệu thuốc nhưng không ưa đọc sách, chỉ giỏi chơi bời phóng đãng, lại kết bạn với một bọn du côn đàng điếm. Ông này đã có một vợ chính và ba người thiếp, nhưng thấy Phan Kim Liên có nhan sắc, ông liền lập mưu giết chết chồng nàng là Võ Đại (trong Thủy Hử truyện ghi là Võ Đại Lang), rồi cưới nàng làm thiếp. Võ Tòng (em trai Võ Đại) báo thù, giết lầm người khác nên Tây Môn Khánh vẫn không can gì... Sau đó, Tây Môn Khánh còn mua Lý Bình Nhi về làm vợ lẽ, và gian dâm với người hầu gái của Phan Kim Liên là Bàng Xuân Mai. Nhờ thông đồng với quan lại, Tây Môn Khánh trở thành một cường hào. Rồi nhờ nhận Thái Kinh (một trọng thần) làm cha nuôi, ông được bổ làm một chức quan coi việc xử án trong huyện, nên tha hồ đổi trắng thay đen để ức hiếp dân lành. Có tiền, có thế, ông ta lại càng ăn chơi phóng đãng, hoang dâm vô độ, để rồi cuối cùng lâm bạo bệnh mà chết</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 16, 1996, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Si Man Yeung","avatar":""},{"name":"Pal Sinn Lap-man","avatar":""},{"name":"Ku Kuan-Chung","avatar":""},{"name":"Cindy Yip Sin-Yi","avatar":""},{"name":"Ya-Chun Tseng","avatar":""},{"name":"蔡美优","avatar":""},{"name":"林美仑","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324539);
