INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-mua-he-o-la-goulette', 'Một mùa hè ở La Goulette', 'A Summer in La Goulette', 'https://phimimg.com/upload/vod/20240604-1/edc7dc0ba9f527e58bbb1a860b6b8e5e.jpg', 'https://phimimg.com/upload/vod/20240604-1/a269d9d14112cba716a1367b8b8a7902.jpg', '<p>Mùa hè năm 1967. La Goulette, bãi biển du lịch của Tunisia, là nơi sinh sống của ba cô gái mười bảy tuổi xinh đẹp: Gigi, Sicilia và Catholic; Meriem, Tunisia và Ả Rập; Tina, người Pháp và người Do Thái. Họ muốn có trải nghiệm tình dục đầu tiên trong mùa hè năm đó, thách thức gia đình họ. Cha của họ, Youssef, Jojo và Giuseppe, là bạn cũ và tình bạn của họ sẽ gặp khủng hoảng vì các cô gái, trong khi Hadj, một ông già Ả Rập giàu có, lại muốn cưới Meriem.</p>', 'Full', 1, 'single', 'completed', 13, 1996, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Sonia Mankaï","avatar":""},{"name":"Claudia Cardinale","avatar":""},{"name":"Gamil Ratib","avatar":""},{"name":"Sarah Pariente","avatar":""},{"name":"Ava Cohen-Jonathan","avatar":""},{"name":"Mustapha Adouani","avatar":""},{"name":"Michel Boujenah","avatar":""},{"name":"Ivo Salerno","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324539);
