INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-mua-he-o-la-goulette', 'Một mùa hè ở La Goulette', 'A Summer in La Goulette', 'một mùa hè ở la goulette a summer in la goulette sonia mankaï claudia cardinale gamil ratib sarah pariente ava cohen-jonathan mustapha adouani michel boujenah ivo salerno ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhuc-bo-doan-3', 'Nhục Bồ Đoàn 3', 'Yu Pui Tsuen III', 'https://phimimg.com/upload/vod/20240323-1/32d1bb47defcc2f069ae11d644c4751f.jpg', 'https://phimimg.com/upload/vod/20240228-1/d68d95cd4d284e7ecd25e5fe367cd1f8.jpg', '<p>Đặc vụ nhà Minh Ling Ling Ling (000) được giao nhiệm vụ điều tra vụ ngộ độc ma túy liên quan đến loại thuốc tăng cường hiệu suất trong nhà thổ, Ying Chun Kwok. Ling suy nghĩ rất kỹ và cuối cùng nghĩ ra cách cải trang thành tác giả Yuk Po Tuen (Sex and Zen) để lẻn vào nhà chứa. Các gái mại dâm để ghi tên mình vào cuốn sách đều cám dỗ Ling, người để xoa dịu các quý cô đã biến cuốn sách thành một cuốn truyện tục tĩu. Một ngày nọ, người hầu mù Yuk Chu Nui (Jade Virgin) được thử vai, Ling biết được người mua sẽ nhận được thuốc nên đã tăng giá với hy vọng nhận được bằng chứng. Ai có thể mong đợi rằng người khác sẽ trả giá cao hơn?</p>', 'Full', 1, 'single', 'completed', 13, 1996, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Christine Hung Hiu-Wan","avatar":""},{"name":"Từ Cẩm Giang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
