INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-ham-ruc-lua', 'Đường Hầm Rực Lửa', 'Daylight', 'https://phimimg.com/upload/vod/20240207-1/be69a1ee5116d8d2cf0654d2970d913b.jpg', 'https://phimimg.com/upload/vod/20240207-1/b088c82ac0426ee1fdaa380ca9e50816.jpg', '<p>Một nhóm cướp có vũ trang chạy trốn cảnh sát đến Đường hầm New Jersey và lao thẳng vào những chiếc xe tải vận chuyển chất thải độc hại. Vụ nổ ngoạn mục xảy ra sau đó khiến cả hai đầu đường hầm sụp đổ và một số ít người sống sót sau vụ nổ hiện đang gặp nguy hiểm. Kit Latura là người đàn ông duy nhất có kỹ năng và kiến thức để dẫn nhóm người sống sót ra khỏi đường hầm trước khi cấu trúc sụp đổ.</p>', 'Full', 1, 'single', 'completed', 11, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Amy Brenneman","avatar":""},{"name":"Viggo Mortensen","avatar":""},{"name":"Stan Shaw","avatar":""},{"name":"Barry Newman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324539);
