INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sgt-bilko', 'Sgt. Bilko', 'Sgt. Bilko', 'https://phimimg.com/upload/vod/20240207-1/8a4e464d365a0d4a15b61cad66d89377.jpg', 'https://phimimg.com/upload/vod/20240207-1/c43c116d8be25556e3faca1a4a890a00.jpg', '<p>Quân đội Hoa Kỳ được biết đến với việc tạo ra những cỗ máy chiến đấu tinh gọn nhằm mục đích bảo vệ đất nước vĩ đại của chúng ta. Trung sĩ Ernie Bilko là thủ lĩnh của một nhóm ragtag gồm những người lính đáng tiếc nhất từng gia nhập lực lượng vũ trang.</p>', 'Full', 1, 'single', 'completed', 11, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Martin","avatar":""},{"name":"Dan Aykroyd","avatar":""},{"name":"Phil Hartman","avatar":""},{"name":"Glenne Headly","avatar":""},{"name":"Daryl Mitchell","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324539);
