INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-hong-do', 'Quả Hồng Đỏ', 'Red Persimmon', 'https://phimimg.com/upload/vod/20240228-1/4650af62868d890118759c44548e245a.jpg', 'https://phimimg.com/upload/vod/20240228-1/c89ee8969c359202fab0324d28b9a0ad.jpg', '<p>Năm 1949, Trung Hoa chiếm đất liền. Những người tị nạn và quân đội đến cảng Keelung ở Đài Loan. Trong khi người cha tổ chức các cuộc họp bí mật với các tướng lĩnh khác để cố gắng giành lại vùng đất đã mất thì những đứa trẻ vẫn chơi đùa cùng bà ngoại, người vẫn tận hưởng sự hòa thuận, bình yên trong khó khăn. Dần dần, dường như không còn hy vọng đánh lại tổ quốc. Người cha trở thành tướng quân phải điều hành một công việc kinh doanh nhỏ để nuôi sống gia đình. Anh ta gặp phải một loạt các cuộc đấu tranh. Và cuối cùng những đứa con của anh cũng lớn lên.</p>', 'Full', 1, 'single', 'completed', 12, 1996, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Shut Tiu","avatar":""},{"name":"Shih Chun","avatar":""},{"name":"Zhang Shi","avatar":""},{"name":"Lu Shih","avatar":""},{"name":"René Liu","avatar":""},{"name":"Cheng-Ping Chao","avatar":""},{"name":"Chuan Wang","avatar":""},{"name":"Yang Lin","avatar":""},{"name":"Lung Fang","avatar":""},{"name":"Tao Shu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
