INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-hoang-hon-toi-binh-minh', 'Từ Hoàng Hôn Tới Bình Minh', 'From Dusk Till Dawn', 'https://phimimg.com/upload/vod/20240205-1/7a202d45884552afb7607315a5f9e937.jpg', 'https://phimimg.com/upload/vod/20240205-1/b4d2ca9a9c5322cde1ea769e54a330a8.jpg', '<p>Ở vùng biên giới giữa Mexico và Mỹ có một đền thờ của bộ tộc Aztec cổ đại bị chôn vùi dưới đất. Quán rượu phía trên ngôi đền là nơi trú ngụ của ma cà rồng trong hàng nghìn năm. Một ngày nọ, hai tên tội phạm khét tiếng của Mỹ bước vào quán. Sau khi gây sự với những người trong quán, hai anh em mới hãi hùng nhận ra rằng tất cả những người làm việc trong quán đều là ma cà rồng. Điều gì sẽ xảy ra tiếp theo</p>', 'Full', 1, 'single', 'completed', 9, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"Ernest Liu","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Tom Savini","avatar":""},{"name":"Fred Williamson","avatar":""},{"name":"Michael Parks","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324539);
