INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-bai-3-thieu-nien-than-bai', 'Thần Bài 3: Thiếu Niên Thần Bài', 'God Of Gamblers 3: The Early Stage', 'https://phimimg.com/upload/vod/20240128-1/49eca26257023e7f319489d7ce3cd4f2.jpg', 'https://phimimg.com/upload/vod/20240128-1/32968d24ec067cf06ff486e8a9969d96.jpg', '<p>Tiếp nối những năm đầu của Ko Chun khi anh chiến đấu cho vị trí mà anh đã được định sẵn: Thần cờ bạc.</p>', 'Full', 1, 'single', 'completed', 14, 1996, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lê Minh","avatar":""},{"name":"Trần Tiểu Xuân","avatar":""},{"name":"Viên Vịnh Nghi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
