INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-nguyet', 'Phong Nguyệt', 'Temptress Moon', 'https://phimimg.com/upload/vod/20240128-1/f00113cef3fb0dd0e3b81fc0f4548a30.jpg', 'https://phimimg.com/upload/vod/20240128-1/9845103185c6c450b5c8553f6607d4b5.jpg', '<p>Lấy bối cảnh thời Dân Quốc (1912-1949), bộ phim Phong Nguyệt xoay quanh gia tộc họ Bàng tại một thị trấn gần Thượng Hải với trọng tâm là cô tiểu thư Như Ý (Củng Lợi). Đặc biệt, bộ phim còn có sự tham gia của tay máy Christopher Doyle – vốn đã gắn liền tên tuổi vào phong cách làm phim cùng Vương Gia Vệ</p>', 'Full', 1, 'single', 'completed', 14, 1996, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Leslie Cheung","avatar":""},{"name":"Gong Li","avatar":""},{"name":"Kevin Lin","avatar":""},{"name":"He Saifei","avatar":""},{"name":"Zhang Shi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
