INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phong-nguyet', 'Phong Nguyệt', 'Temptress Moon', 'phong nguyệt temptress moon leslie cheung gong li kevin lin he saifei zhang shi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mong-ho-2', 'Móng Hổ 2', 'Tiger Claws II', 'https://phimimg.com/upload/vod/20240124-1/80f735a8c6a2ff7194332591fcbdebdd.jpg', 'https://phimimg.com/upload/vod/20240124-1/c5ef1ce4e55dddb125c0e3ce26386333.jpg', '<p>Được phát hành năm năm sau phần đầu tiên, Tiger Claws II tìm thấy kẻ giết người hàng loạt võ thuật của Yeung, Chong, bị bắt ra khỏi tù bởi một nhóm nặng ký làm việc cho xã hội đen Dai Lo Fu và đi khắp đất nước đến Khu phố Tàu của San Fransisco. Khi cảnh sát NYC Tarek Richards phát hiện ra một loạt vụ giết người gần đây bằng cách sử dụng M.O. đặc biệt của Chong - một dấu hiệu giống móng vuốt trên mặt nạn nhân - anh ta liên hệ với đối tác cũ của mình, Linda Masterson, hiện đang sống ở L.A., để được giúp đỡ. Nhưng Chong, hóa ra, không liên quan gì đến vụ giết người. Anh ta chỉ bị sử dụng bởi trùm tội phạm Lo Fu, người cần kết hợp năng lượng của mình với Chong để mở một loại cổng thời gian nào đó nhằm cung cấp nguồn cung cấp quan trọng cho các nhà sư Thiếu Lâm cổ đại. Tuy nhiên, trên thực tế, Lo Fu tham lam lên kế hoạch sử dụng cánh cổng để buôn lậu pháo hạng nặng hiện đại trở lại và tự mình cai trị Trung Quốc thời nhà Thanh.</p>', 'Full', 1, 'single', 'completed', 12, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jalal Merhi","avatar":""},{"name":"Bolo Yeung","avatar":""},{"name":"Cynthia Rothrock","avatar":""},{"name":"Ong Soo Han","avatar":""},{"name":"Evan Lurie","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324539);
