INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thinner', 'Thinner', 'Thinner', 'https://phimimg.com/upload/vod/20240104-1/59ea0b203d9cb8fd576794859ddba663.jpg', 'https://phimimg.com/upload/vod/20240104-1/edc51237638dc3de3cf90caf5e2daac9.jpg', '<p>Một luật sư béo phì thấy mình ngày càng Gầy hơn khi một ông già gypsy yểm bùa lên người anh ta. Bây giờ luật sư phải kêu gọi những người bạn của mình trong tội phạm có tổ chức giúp anh ta thuyết phục người gypsy hóa giải lời nguyền. Thời gian không còn nhiều đối với người luật sư tuyệt vọng khi anh ta tiến gần đến cái chết của chính mình và ngày càng gầy đi.</p>', 'Full', 1, 'single', 'completed', 10, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert John Burke","avatar":""},{"name":"Lucinda Jenney","avatar":""},{"name":"Bethany Joy Lenz","avatar":""},{"name":"Joe Mantegna","avatar":""},{"name":"Michael Constantine","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324539);
