INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rong-dat-2-tinh-giac', 'Rồng Đất 2: Tỉnh Giấc', 'Tremors II: Aftershocks', 'https://phimimg.com/upload/vod/20240104-1/561854b3c5156f9d9b626ede3347c2e1.jpg', 'https://phimimg.com/upload/vod/20240104-1/d7ec3a3acb0069ef2d524a6fde2da129.jpg', '<p>Một vài năm sau cuộc chống trả loài sâu đất khổng lồ tại thị trấn Perfection, Nevada, Earl sống khốn khó. Trang trại đà điểu của anh ngày càng suy kiệt. Những người khách lạ ra một cái giá hời cho cuộc săn lùng những con sâu đất mà Earl đã đụng độ.</p>', 'Full', 1, 'single', 'completed', 10, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fred Ward","avatar":""},{"name":"Chris Gartin","avatar":""},{"name":"Helen Shaver","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324539);
