INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-dep-bi-danh-cap', 'Vẻ Đẹp Bị Đánh Cắp', 'Stealing Beauty', 'https://phimimg.com/upload/vod/20240103-1/c2c67e23175bb74410cffa4c64c2287a.jpg', 'https://phimimg.com/upload/vod/20240103-1/fc6178a9bb233f6adbe861de1a02dc38.jpg', '<p>Trong 20 năm, nhiều du khách đã đến biệt thự trên một nghệ sĩ tiếng Anh thuộc sở hữu của người Anh. Lucy, một người Mỹ 19 tuổi, lần cuối cùng có bốn năm trước và muốn gặp lại người Ý trẻ tuổi hôn cô ấy và tương ứng trong một thời gian. Và cô đã đưa cuốn nhật ký của mẹ quá cố tràn đầy những bài thơ bí ẩn cho thấy Lucy đã được thụ thai trên đỉnh đồi đó. Lucy muốn tìm hiểu xem Daddy là phóng viên chiến tranh của Ý đã viết cho mẹ trong 20 năm nữa. Sau đó, một lần nữa Daddy có thể là nhà viết kịch người Anh sắp chết ở nơi cư trú hoặc nghệ sĩ sử dụng cưa máy trên thân cây cho các tác phẩm điêu khắc của mình. Ba, tất nhiên, không có ý tưởng rằng Lucy ở đó để giải quyết một bí ẩn. Họ, vợ của nghệ sĩ, con gái của người vợ đó và người yêu người Mỹ của con gái được hấp dẫn nhất bởi trinh tiết của Lucy.</p>', 'Full', 1, 'single', 'completed', 13, 1996, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324539);
