INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-ca', 'Tần Ca', 'The Emperor''s Shadow', 'https://phimimg.com/upload/vod/20240102-1/3099bf7ba08f7569a2f8954f34127b05.jpg', 'https://phimimg.com/upload/vod/20240102-1/b8bc7234d4b739ad4226a073ac4d902d.jpg', '<p>Câu chuyện phim xoay quanh tình bạn giữa cậu bé Doanh Chính, sau này trở thành Tần Thủy Hoàng, vị hoàng đế đầu tiên của Trung Quốc, và nhạc công Cao Tiệm Ly. Lớn lên chung một mái nhà, cùng trải nhiều gian khó, hiểm nguy, tình bạn của họ thật là khăng khít. Nhưng những biến chuyển của thời thế thay đổi tất cả.Doanh Chính được đưa về nước Tần để lập làm vua. Khi trưởng thành, ông tiến hành hàng loạt cuộc chiến đẫm máu nhằm thống nhất Trung Quốc. Ông bắt cóc Cao Tiệm Ly từ nước Yên để sáng tác Tần Ca, bản nhạc hùng tráng tương xứng với tầm vóc của nước Tần. Hai người bạn cũ xung đột gay gắt về đủ thứ, từ bản nhạc mới tới công trình kỳ vĩ Vạn lý trường thành và nhất là về con gái của Thủy Hoàng, công chúa Nhạc ...</p>', 'Full', 1, 'single', 'completed', 18, 1996, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ge You","avatar":""},{"name":"Jiang Wen","avatar":""},{"name":"Xu Qing","avatar":""},{"name":"Ge Zhijun","avatar":""},{"name":"Wang Qingxiang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
