INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aladdin-va-vua-trom', 'Aladdin Và Vua Trộm', 'Aladdin And The King Of Thieves', 'https://phimimg.com/upload/vod/20231230-1/63069d743c7a60087b60097f29615250.jpg', 'https://phimimg.com/upload/vod/20231230-1/46ca8fcb410c3b87c5c6fa664624e386.jpg', '<p>Phim Aladdin And The King Of Thieves - Aladdin Và Vua Trộm 1996 là câu chuyện tiếp nối, sau khi Aladdin đám cưới với công chúa Jasmine. 40 tên cướp đã đến phá đám cưới và lấy cắp một lá bùa muốn gì được nấy. Aladdin truy tìm 40 tên cướp và ngăn chặn chúng sử dụng lá bùa này cũng như tìm lại người cha đã mất tích từ lâu của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 12, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scott Weinger","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"John Rhys-Davies","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324539);
