INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tinh-dau', 'Mối Tình Đầu', 'First Love', 'https://phimimg.com/upload/vod/20240116-1/337bb11a61297293dcb8075a20fc2cb2.jpg', 'https://phimimg.com/upload/vod/20240116-1/23cd4ec3524253cc63770c3cc2b313fc.jpg', '<p><span style="text-wrap: nowrap;">Mối tình đầu (tiếng Hàn: 첫사랑; Romaja: Cheot Sarang, tên tiếng Anh: First love) là một bộ phim truyền hình Hàn Quốc do đài truyền hình KBS sản xuất, phát sóng lần đầu tiên trên kênh KBS2 vào năm 1996.</span></p><p><span style="text-wrap: nowrap;"><br/></span></p><p><span style="text-wrap: nowrap;">Phim xếp vị trí thứ hai trong số các phim truyền hình Hàn Quốc được yêu thích nhất mọi thời đại, dựa trên xếp hạng số người xem trên mỗi tập, lên tới 65.8% vào lần cuối cùng phát sóng ngày 20 tháng 4 năm 1997. Xếp hạng trung bình tổng hợp là 52.6%.</span></p><p><span style="text-wrap: nowrap;"><br/></span></p><p><span style="text-wrap: nowrap;">Mối tình đầu được trình chiếu tại Việt Nam vào năm 1999. Đây là bộ phim Hàn Quốc đầu tiên được trình chiếu ở Việt Nam, tạo ra làn sóng phim Hàn Quốc.</span></p>', 'Hoàn Tất (66/66)', 66, 'series', 'completed', 15, 1996, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Lee Seung-yeon","avatar":""},{"name":"Choi Soo-jong","avatar":""},{"name":"Bae Yong-joon","avatar":""},{"name":"Park Sang-won","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324539);
