INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('crayon-shinchan-cuoc-phieu-luu-tuyet-voi-o-henderland', 'Crayon Shin-chan : Cuộc Phiêu Lưu Tuyệt Vời Ở Henderland', 'Crayon Shin-chan', 'https://phimimg.com/upload/vod/20231219-1/4e7b544104a3ebb7ef251a763f2e8b3a.jpg', 'https://phimimg.com/upload/vod/20231219-1/2be940d7a2f5c655ea2cec698c00bd63.jpg', '<p>Crayon Shin-chan : Cuộc Phiêu Lưu Tuyệt Vời Ở Henderland kể về Shinnosuke và các bạn ở trường mẫu giáo Futaba đi tới một công viên giải trí tên Henderland tại tỉnh Gunma. Shin bị tách ra khỏi mọi người và vô tình biết được một bí mật đen tối nơi đây. Đó cũng là lúc cậu gặp một cô bé búp bê lên dây cót và cô bé ấy đã giao cho cậu một bộ bài phép thuật. Thế lực ma thuật và đầy đen tối đó luôn sẵn sàng để chống lại Shin và gia đình của cậu ấy. Chúng được cầm đầu bởi hai gã phù thủy cải trang nữ và cậu ấy phải dùng sức mạnh của những quân bài cùng sức mạnh của bản thân, gia đình, và cả các chiến hữu trong tưởng tượng của Shin để đánh bại chúng và trả lại bình yên cho Henderland.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 1996, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324539);
