INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-so', 'Nỗi Sợ', 'Fear', 'https://phimimg.com/upload/vod/20231130-1/aaa9ca105029aad80f2e5376e6ec43a5.jpg', 'https://phimimg.com/upload/vod/20231130-1/644d8014f18c8c989296e4209b0bce96.jpg', '<p>Đi dự tiệc cùng bạn thân, cô nàng &quot;gái ngoan&quot; 16 tuổi gặp một anh chàng đẹp trai, bí ẩn song lại có xuất thân nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 10, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"William Petersen","avatar":""},{"name":"Amy Brenneman","avatar":""},{"name":"Alyssa Milano","avatar":""},{"name":"Christopher Gray","avatar":""},{"name":"Tracy Fraim","avatar":""},{"name":"Gary Riley","avatar":""},{"name":"Jason Kristofer","avatar":""},{"name":"Jed Rees","avatar":""},{"name":"Todd Caldecott","avatar":""},{"name":"Gerry Bean","avatar":""},{"name":"David Fredericks","avatar":""},{"name":"Ravinder Toor","avatar":""},{"name":"Andrew Airlie","avatar":""},{"name":"Jo Bates","avatar":""},{"name":"Will Sengotta","avatar":""},{"name":"L.","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324539);
