INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-tan-con-song', 'Phá Tan Con Sóng', 'Breaking the Waves', 'https://phimimg.com/upload/vod/20231129-1/810d04ba44d90303e27dd8206f604a6e.jpg', 'https://phimimg.com/upload/vod/20231129-1/788eb347d52b975f9fe2ba5512a21800.jpg', '<p>Breaking the Waves là một phim của đạo diễn Lars von Trier, được sản xuất xong trong năm 1996 với ngôi sao Emily Watson. Phim này là phim đầu của bộ 3 phim Trái tim Vàng (Golden Heart Trilogy) của Lars von Trier, gồm cả 2 phim The Idiots (1998) và Dancer in the Dark (2000). Truyện phim kể về cô nàng Bess McNeill kết hôn với Jan, một công nhân làm trên giàn khoan dầu ở ngoài khơi bắc Scotland, bất chấp ý của dân làng và Giáo hội Trưởng Lão (Cơ Đốc) của cô. Bess khá giản dị và ngây thơ, vất vả khi chồng đi làm trên giàn khoan và luôn cầu nguyện cho chồng sớm trở về với mình. Một ngày kia Jan trở về sau một tai nạn lao động, bị gãy cổ và bị liệt, Bess đã tin rằng đây là lỗi của nàng. Jan không còn khả năng tình dục và bị ảnh hưởng tâm thần, Jan yêu cầu vợ làm tình với các người đàn ông khác rồi về thuật lại các chi tiết cho chồng nghe. Ban đầu Bess còn ngại ngùng, sau rồi cũng dấn thân làm tình với người khác, và Bess bắt đầu tin rằng việc mình làm là hợp với ý muốn của Chúa và giúp cho Jan sống sót.</p>', 'Full', 1, 'single', 'completed', 14, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emily Watson","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Katrin Cartlidge","avatar":""},{"name":"Jean-Marc Barr","avatar":""},{"name":"Adrian Rawlins","avatar":""},{"name":"Jonathan Hackett","avatar":""},{"name":"Sandra Voe","avatar":""},{"name":"Udo Kier","avatar":""},{"name":"Mikkel Gaup","avatar":""},{"name":"Roef Ragas","avatar":""},{"name":"Robert Robertson","avatar":""},{"name":"Phil McCall","avatar":""},{"name":"Desmond Reilly","avatar":""},{"name":"Sarah Gudgeon","avatar":""},{"name":"Finlay Welsh","avatar":""},{"name":"David Gallacher","avatar":""},{"name":"Ray Jeffries","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324539);
