INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sling-blade', 'Sling Blade', 'Sling Blade', 'https://phimimg.com/upload/vod/20231125-1/7a0837c4ee71c02c1e03e58a668ae8ed.jpg', 'https://phimimg.com/upload/vod/20231125-1/68656aa4629a68989a4e43d8137ff3df.jpg', '<p>Karl Childers, một người đàn ông thiểu năng trí tuệ, đã bị bệnh viện tâm thần tiểu bang giam giữ từ năm 12 tuổi vì tội giết mẹ mình và người tình của bà. Mặc dù đã được thể chế hóa triệt để, nhưng anh ta được coi là phù hợp để được thả ra thế giới bên ngoài.</p>', 'Full', 1, 'single', 'completed', 12, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Billy Bob Thornton","avatar":""},{"name":"Dwight Yoakam","avatar":""},{"name":"J.T. Walsh","avatar":""},{"name":"John Ritter","avatar":""},{"name":"Lucas Black","avatar":""},{"name":"Natalie Canerday","avatar":""},{"name":"James Hampton","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Rick Dial","avatar":""},{"name":"Brent Briscoe","avatar":""},{"name":"Christine Renee Ward","avatar":""},{"name":"Sarah Boss","avatar":""},{"name":"Kathy Sue Brown","avatar":""},{"name":"Wendell Rafferty","avatar":""},{"name":"Bruce Hampton","avatar":""},{"name":"Vic Chesnutt","avatar":""},{"name":"Mickey Jon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
