INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('beavis-and-butthead-do-america', 'Beavis and Butt-Head Do America', 'Beavis and Butt-Head Do America', 'https://phimimg.com/upload/vod/20231125-1/dbcd771fe78ac80f2c32d8d2abe7dc9c.jpg', 'https://phimimg.com/upload/vod/20231125-1/f4a82ed880ebe949ada6b9c9613f1936.jpg', '<p>Những anh hùng thanh thiếu niên Intrepid của chúng tôi thức dậy để tìm thấy truyền hình yêu quý của họ bị đánh cắp, và bắt tay vào một hành trình hoành tráng trên khắp nước Mỹ để phục hồi nó, và, người biết, thậm chí có thể ghi bàn. Trên đường đi, họ gặp phải một kẻ buôn lậu bị giết người của một người virus chết người và người vợ nguy hiểm của mình, một tác nhân FBI với sự chiếm ưu hóa cho các tìm kiếm khoang, một vài con đường cũ của Motley Crue trông khá quen thuộc, ông Van dreesen hát &quot;Seagull&quot; đồng tính nữ &quot;, một Người phụ nữ nhỏ bé và tất nhiên ông Anderson và trailer của mình. Cornholio lớn có thể cứu ngày? Uh-huh. Huh Huh.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mike Judge","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Cloris Leachman","avatar":""},{"name":"Robert Stack","avatar":""},{"name":"Jacqueline Barba","avatar":""},{"name":"Pamela Blair","avatar":""},{"name":"Eric Bogosian","avatar":""},{"name":"Kristofor Brown","avatar":""},{"name":"Tony Darling","avatar":""},{"name":"John Doman","avatar":""},{"name":"Francis Dumaurier","avatar":""},{"name":"Jim Flaherty","avatar":""},{"name":"Tim Guinee","avatar":""},{"name":"Toby Huss","avatar":""},{"name":"Sam Johnson","avatar":""},{"name":"David Letterman","avatar":""},{"name":"Richard Li","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2