INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-va-doi-tra', 'Bí Mật Và Dối Trá', 'Secrets & Lies', 'https://phimimg.com/upload/vod/20231124-1/d654bf9ddfbc4e09b4ba67db081edf79.jpg', 'https://phimimg.com/upload/vod/20231124-1/7a67e2de1d7440a3450a6ed0f7822680.jpg', '<p>Bí Mật Và Dối Trá - Secrets and Lies (1996):Một cô gái da đen trẻ tuổi tìm kiếm tung tích thật sự của mình, sau khi cha mẹ nuôi của cô qua đời. Cô rất sốc khi biết mẹ đẻ của mình là người da trắng. Nhưng bà mẹ ruột của cô còn sốc hơn khi biết đứa con mà ngày xưa bà đã cho người khác làm con nuôi lại là người da đen. Ban đầu bà khẳng định đó là một sai lầm, nhưng rồi bà sớm nhận ra đó là sự thật khi hàng loạt bí mật và những lời nói dối được tiết lộ.</p>', 'Full', 1, 'single', 'completed', 12, 1996, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Brenda Blethyn","avatar":""},{"name":"Marianne Jean-Baptiste","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Phyllis Logan","avatar":""},{"name":"Claire Rushbrook","avatar":""},{"name":"Lee Ross","avatar":""},{"name":"Lesley Manville","avatar":""},{"name":"Elizabeth Berrington","avatar":""},{"name":"Michele Austin","avatar":""},{"name":"Ron Cook","avatar":""},{"name":"Trevor Laird","avatar":""},{"name":"Brian Bovell","avatar":""},{"name":"Emma Amos","avatar":""},{"name":"Clare Perkins","avatar":""},{"name":"Elias Perkins McCook","avatar":""},{"name":"Jane Mitchell","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
