INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chap-canh-bay-xa', 'Chắp Cánh Bay Xa', 'Fly Away Home', 'https://phimimg.com/upload/vod/20231120-1/736537f60184c98f01fc1545d6f6ffda.jpg', 'https://phimimg.com/upload/vod/20231120-1/f1b353a8579b892bd8678fd702c9a261.jpg', '<p>Amy chỉ mới 13 tuổi khi mẹ cô bị giết. Cô đến Canada để sống với cha mình, một nhà phát minh lập dị mà cô hầu như không biết. Amy đau khổ trong cuộc sống mới... cho đến khi cô phát hiện ra một ổ trứng ngỗng bị bỏ hoang khi một khu rừng địa phương bị phá bỏ. Trứng nở và Amy trở thành &quot;Mama Goose&quot;. Khi mùa Đông đến, Amy và bố cô ấy phải tìm cách dẫn đàn chim về phương Nam….</p>', 'Full', 1, 'single', 'completed', 14, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Daniels","avatar":""},{"name":"Anna Paquin","avatar":""},{"name":"Dana Delany","avatar":""},{"name":"Terry Kinney","avatar":""},{"name":"Holter Graham","avatar":""},{"name":"Jeremy Ratchford","avatar":""},{"name":"Deborah Verginella","avatar":""},{"name":"Michael J. Reynolds","avatar":""},{"name":"David Hemblen","avatar":""},{"name":"Ken James","avatar":""},{"name":"Nora Ballard","avatar":""},{"name":"Sarena Paton","avatar":""},{"name":"Carmen Lishman","avatar":""},{"name":"Christi Hill","avatar":""},{"name":"Judith Orban","avatar":""},{"name":"Jeff Braunstein","avatar":""},{"name":"John Friesen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324539);
