INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-sung-cuoi-cung', 'Tay Súng Cuối Cùng', 'Last Man Standing', 'https://phimimg.com/upload/vod/20231116-1/dac1fe954e827637d63e7e84961aaad6.jpg', 'https://phimimg.com/upload/vod/20231116-1/b32d194248e5a644f44448631ce09e68.jpg', '<p>John Smith là một người lạ bí ẩn bị lôi kéo vào cuộc chiến tàn khốc giữa hai băng đảng thời Cấm. Trong một trò chơi nguy hiểm, anh ta chuyển lòng trung thành từ người này sang người khác, cung cấp dịch vụ của mình cho người trả giá cao nhất. Khi số người chết ngày càng tăng, Smith tự mình nắm lấy luật pháp trong một cuộc đua chết chóc để sống sót.</p>', 'Full', 1, 'single', 'completed', 26, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Bruce Dern","avatar":""},{"name":"William Sanderson","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"David Patrick Kelly","avatar":""},{"name":"Karina Lombard","avatar":""},{"name":"Ned Eisenberg","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"R. D. Call","avatar":""},{"name":"Alexandra Powers","avatar":""},{"name":"Ken Jenkins","avatar":""},{"name":"Ted Markland","avatar":""},{"name":"Leslie Mann","avatar":""},{"name":"Patrick Kilpatrick","avatar":""},{"name":"Cassandra Gava","avatar":""},{"name":"Luis Contrera","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324539);
