INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-da-dom-bong', 'Ngày Đá Đơm Bông', 'One Fine Day', 'https://phimimg.com/upload/vod/20231116-1/739f15ab814423e339902fc2281a8ee4.jpg', 'https://phimimg.com/upload/vod/20231116-1/6b1f0a97f742ad95595fc8753071622a.jpg', '<p>Melanie Parker, một kiến trúc sư và là mẹ của Sammy, và Jack Taylor, một nhà báo và là cha của Maggie, đều đã ly hôn. Họ gặp nhau vào một buổi sáng khi Jack choáng ngợp bất ngờ bị bỏ lại với Maggie và quên mất rằng Melanie sẽ đưa cô đến trường. Kết quả là cả hai đứa trẻ đều bỏ lỡ chuyến đi thực tế ở trường và bị mắc kẹt với cha mẹ. Hai người lớn đặt định kiến tiêu cực về vợ hoặc chồng cũ của họ lên nhau, nhưng cuối cùng phải dựa vào nhau để trông chừng lũ trẻ khi mỗi người phải cứu lấy công việc của mình. Sự hài hước được thêm vào bởi xu hướng cho dị vật vào mũi của Sammy và xu hướng đi lang thang của Maggie.</p>', 'Full', 1, 'single', 'completed', 12, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Pfeiffer","avatar":""},{"name":"George Clooney","avatar":""},{"name":"Mae Whitman","avatar":""},{"name":"Alex D. Linz","avatar":""},{"name":"Charles Durning","avatar":""},{"name":"Jon Robin Baitz","avatar":""},{"name":"Ellen Greene","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"Joe Grifasi","avatar":""},{"name":"Pete Hamill","avatar":""},{"name":"Anna Maria Horsford","avatar":""},{"name":"Gregory Jbara","avatar":""},{"name":"Sheila Kelley","avatar":""},{"name":"Bitty Schram","avatar":""},{"name":"Barry Kivel","avatar":""},{"name":"Robert Klein","avatar":""},{"name":"George Martin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324539);
