INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-mat-mat', 'Điềm Mật Mật', 'Comrades: Almost a Love Story', 'https://phimimg.com/upload/vod/20231113-1/2f6f480e85b4335cf0615245e855d33c.jpg', 'https://phimimg.com/upload/vod/20231113-1/7b8f1d0746e6cc411d7013a7366abdeb.jpg', '<p>Tựa đề của bộ phim được lấy từ một bài hát rất được yêu thích của nữ ca sĩ Đặng Lệ Quân. Bộ phim nói về mối tình của hai người Trung Quốc đại lục nhập cư ở Hồng Kông, với dàn diễn viên chính gồm Lê Minh, Trương Mạn Ngọc, Tằng Chí Vĩ và Dương Cung như. Bộ phim giành được kỷ lục về số giải thưởng được trao tại giải thưởng điện ảnh Hồng Kông với 9 giải. Năm 1986, Lý Tiểu Quân và Lý Kiều từ Đại Lục (Trung Quốc) tới Hồng Kông để lập nghiệp. Họ tình cờ gặp nhau tại McDonald ở Hồng Kông, khi đó Lý Kiều là nhân viên bán thời gian tại McDonald, còn Tiểu Quân thì đang phục vụ tại một sạp bán thịt. Thấy Tiểu Quân hiền lành, thật thà, Lý Kiều đã tìm cách kết bạn để dụ dỗ Tiểu Quân học tiếng Anh nhằm tăng tiền hoa hồng cũng như để dễ dàng nhờ vả những việc khác.</p>', 'Full', 1, 'single', 'completed', 13, 1996, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Leon Lai","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Kristy Yang","avatar":""},{"name":"Christopher Doyle","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Joe Cheung Tung-cho","avatar":""},{"name":"Irene Tsu","avatar":""},{"name":"Ding Yue","avatar":""},{"name":"Michelle Gabriel","avatar":""},{"name":"Crystal Chan","avatar":""},{"name":"Jane Choi","avatar":""},{"name":"Yu Ting","avatar":""},{"name":"Gine Lui","avatar":""},{"name":"Heather Traber","avatar":""},{"name":"Len Berdick","avatar":""},{"name":"Robin Gold","avatar":""},{"name":"Dora Ng Lei-Lo","avatar":""},{"name":"Chi Ming Woo","avatar":""},{"name":"Adrian Kwan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324539);
