INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('romeo-va-juliet', 'Romeo và Juliet', 'Romeo + Juliet', 'https://phimimg.com/upload/vod/20231114-1/4a3a20f0a7a683e8fb1c1008e064889f.jpg', 'https://phimimg.com/upload/vod/20231114-1/74d54cf15f85a3c89f65b3a670442ba3.jpg', '<p>Romeo và Juliet là một bộ phim điện ảnh do Mỹ sản xuất vào năm 1996 dựa theo quyển tiểu thuyết của đại văn hào Shakespeare.Bộ phim kể về một câu chuyện tình lãng mạn của đôi tình nhân trẻ Rome và nàng Juliet. Cả hai yêu nhau nhưng vì sự mâu thuẫn từ nhiều năm của hai gia đình nên họ bị ngăn cấm và chia rẽ. Nhưng vì quá yêu nhau, cuối cùng họ tìm đến cái chết để họ được mãi mãi bên nhau và thoát ra khỏi hận thù của hai gia đình.Phim là một câu chuyện tình đầy ngang trái..</p>', 'Full', 1, 'single', 'completed', 25, 1996, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Leonardo DiCaprio","avatar":""},{"name":"Claire Danes","avatar":""},{"name":"Jesse Bradford","avatar":""},{"name":"Vondie Curtis-Hall","avatar":""},{"name":"Brian Dennehy","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Miriam Margolyes","avatar":""},{"name":"Harold Perrineau","avatar":""},{"name":"Christina Pickles","avatar":""},{"name":"Pete Postlethwaite","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Paul Sorvino","avatar":""},{"name":"Diane Venora","avatar":""},{"name":"M. Emmet Walsh","avatar":""},{"name":"Edwina Moore","avatar":""},{"name":"Zak Orth","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324539);
