INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('secrets-lies', 'Secrets & Lies', 'Secrets & Lies', 'https://phimimg.com/upload/vod/20231115-1/fa7994fba8742199386f23d8c8e9cf1c.jpg', 'https://phimimg.com/upload/vod/20231115-1/7c9f619ac0d40b53b385e120eae6254e.jpg', '<p>Sau khi mẹ nuôi của cô qua đời, Hortense, một chuyên viên đo thị lực da đen thành công, đã tìm kiếm mẹ ruột của cô. Cô bị sốc khi nghiên cứu dẫn cô đến với Cynthia, một phụ nữ da trắng thuộc tầng lớp lao động. Lúc đầu, Cynthia phủ nhận yêu cầu này, nhưng cuối cùng cô cũng thừa nhận đã sinh ra Hortense khi còn là một thiếu niên và hai người bắt đầu gắn bó với nhau. Tuy nhiên, khi Cynthia mời Hortense đến dự bữa tiệc nướng gia đình, mối quan hệ vốn đã căng thẳng của Cynthia với gia đình cô lại càng trở nên phức tạp hơn.</p>', 'Full', 1, 'single', 'completed', 16, 1996, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Brenda Blethyn","avatar":""},{"name":"Marianne Jean-Baptiste","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Phyllis Logan","avatar":""},{"name":"Claire Rushbrook","avatar":""},{"name":"Lee Ross","avatar":""},{"name":"Lesley Manville","avatar":""},{"name":"Elizabeth Berrington","avatar":""},{"name":"Michele Austin","avatar":""},{"name":"Ron Cook","avatar":""},{"name":"Trevor Laird","avatar":""},{"name":"Brian Bovell","avatar":""},{"name":"Emma Amos","avatar":""},{"name":"Clare Perkins","avatar":""},{"name":"Elias Perkins McCook","avatar":""},{"name":"Jane Mitchell","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
