INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-ho', 'Phi Hổ', 'First Option', 'https://phimimg.com/upload/vod/20231115-1/b3c9778f9503189ababaa4a72e1eceb5.jpg', 'https://phimimg.com/upload/vod/20231115-1/39a1903529147b5ce286982e9c6f4a34.jpg', '<p>Phi Hổ - First Option xoay quanh cuộc truy bắt Á Châu Băng Hậu - một trùm ma túy khét tiếng đến Hồng Kông với mục đích vận chuyển một khối lượng ma túy lớn sang châu Mỹ. Cơ quan chịu trách nhiệm vụ này là Hải quan Hồng Kông, một đơn vị không được trang bị vũ khí hiện đại, do đó họ phải hợp tác với lực lượng cảnh sát Hồng Kông mà nòng cốt là SDU (Special Duty Unit, hay đội Phi Hổ) để phá án.</p>', 'Full', 1, 'single', 'completed', 13, 1996, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Michael Wong","avatar":""},{"name":"Gigi Leung Wing-Kei","avatar":""},{"name":"Damian Lau","avatar":""},{"name":"Fung Lee","avatar":""},{"name":"Kathy Chow","avatar":""},{"name":"Joseph Cheung Man-Kwong","avatar":""},{"name":"Kim Yip Kwong-Kim","avatar":""},{"name":"Stephen Chan Tak-Gwong","avatar":""},{"name":"Woo Wai-Chung","avatar":""},{"name":"Anthony Carpio","avatar":""},{"name":"Winston Ellis","avatar":""},{"name":"Brian Banowetz","avatar":""},{"name":"Richard Grosse","avatar":""},{"name":"Luk Man-Wai","avatar":""},{"name":"Oscar Lam Wai-Kin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
