INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phi-ho', 'Phi Hổ', 'First Option', 'phi hổ first option michael wong gigi leung wing-kei damian lau fung lee kathy chow joseph cheung man-kwong kim yip kwong-kim stephen chan tak-gwong woo wai-chung anthony carpio winston ellis brian banowetz richard grosse luk man-wai oscar lam wai-kin ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoat-khoi-los-angeles', 'Thoát Khỏi Los Angeles', 'Escape from L.A.', 'https://phimimg.com/upload/vod/20231111-1/7fefe7ac0a4210dceb6a1b5c97f41ea5.jpg', 'https://phimimg.com/upload/vod/20231111-1/84bcc1aabd29c2cf98c1050138ff9aa0.jpg', '<p>Lần này, một trận động đất kinh hoàng ập đến Los Angeles, biến nó thành một hòn đảo. Tổng thống coi trận động đất là một dấu hiệu từ trên cao, trục xuất Los Angeles khỏi đất nước và biến nó thành thuộc địa hình phạt cho những người bị kết tội phạm tội đạo đức. Khi con gái của ông, một phần của phong trào kháng chiến, đánh cắp thiết bị điều khiển để lấy vũ khí cho ngày tận thế, Snake một lần nữa được khai thác để cứu lấy ngày đó.</p>', 'Full', 1, 'single', 'completed', 13, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kurt Russell","avatar":""},{"name":"Stacy Keach","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"A.J. Langer","avatar":""},{"name":"Bruce Campbell","avatar":""},{"name":"Pam Grier","avatar":""},{"name":"Peter Fonda","avatar":""},{"name":"Georges Corraface","avatar":""},{"name":"Robert Carradine","avatar":""},{"name":"Michelle Forbes","avatar":""},{"name":"Valeria Golino","avatar":""},{"name":"Leland Orser","avatar":""},{"name":"Jeff Imada","avatar":""},{"name":"Al Leong","avatar":""},{"name":"James Lew","avatar":""},{"name":"Breckin Meyer","avatar":""},{"name":"Ina Romeo","avatar":""},{"name":"Peter Jason","avatar":""},{"name":"Jord","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9