INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thoat-khoi-los-angeles', 'Thoát Khỏi Los Angeles', 'Escape from L.A.', 'thoát khỏi los angeles escape from l.a. kurt russell stacy keach steve buscemi a.j. langer bruce campbell pam grier peter fonda georges corraface robert carradine michelle forbes valeria golino leland orser jeff imada al leong james lew breckin meyer ina romeo peter jason jord ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-thoai-tinh-yeu', 'Giai Thoại Tình Yêu', 'Kama Sutra: A Tale of Love', 'https://phimimg.com/upload/vod/20231111-1/cd40d10acb8ac746cb05ed441747b701.jpg', 'https://phimimg.com/upload/vod/20231111-1/0468dc6ebc0f9d4503da95b41c58d647.jpg', '<p>Tara và Maya là hai người bạn không thể tách rời ở Ấn Độ. Thị hiếu, thói quen và sở thích của họ là như nhau. Nhiều năm sau, cả hai đã trưởng thành nhưng vẫn duy trì tình bạn của họ. Tara kết hôn với hoàng tử địa phương, Raj Singh, người sẽ sớm kế vị ngai vàng với tư cách là người thừa kế duy nhất. Sau khi kết hôn, Raj chán Tara và bắt đầu tìm kiếm một người phụ nữ khác để thỏa mãn nhu cầu tình dục của mình. Anh ấy để ý đến Maya và ngay lập tức bị cô ấy thu hút. Anh ấy đã đưa cô ấy vào làm một trong những người hầu gái của mình, và thân mật với cô ấy. Hãy xem điều gì sẽ xảy ra khi Tara phát hiện ra và cô ấy sẽ làm gì để giữ cho cuộc hôn nhân của mình nguyên vẹn.</p>', 'Full', 1, 'single', 'completed', 16, 1996, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Indira Varma","avatar":""},{"name":"Sarita Choudhury","avatar":""},{"name":"Ramon Tikaram","avatar":""},{"name":"Naveen Andrews","avatar":""},{"name":"Rekha","avatar":""},{"name":"Khalid Tyabji","avatar":""},{"name":"Arundathi Nag","avatar":""},{"name":"Surabhi Bhansali","avatar":""},{"name":"Garima Dhup","avatar":""},{"name":"Pearl Padamsee","avatar":""},{"name":"Kusum Haidar","avatar":""},{"name":"Harish Patel","avatar":""},{"name":"Ranjit Chowdhry","avatar":""},{"name":"Achala Sachdev","avatar":""},{"name":"Arjun Sajnani","avatar":""},{"name":"Avijit Dutt","avatar":""},{"name":"Anjum Rajabali","avatar":""},{"name":"Sid","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324539);
