INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-thu-va-bong-dem', 'Ác Thú Và Bóng Đêm', 'The Ghost and the Darkness', 'https://phimimg.com/upload/vod/20231111-1/7e76b3344d57ef5c898e2a593373f45a.jpg', 'https://phimimg.com/upload/vod/20231111-1/48d5479c9e0c09f6fe9f5268248ba5b9.jpg', '<p>Ngài Robert Beaumont bị chậm tiến độ trên một tuyến đường sắt ở Châu Phi. Nhờ kỹ sư nổi tiếng John Henry Patterson điều khiển con tàu, Beaumont mong đợi kết quả. Mọi thứ dường như tuyệt vời cho đến khi phi hành đoàn phát hiện ra xác chết bị cắt xén của quản đốc dự án, dường như bị giết bởi một con sư tử. Sau nhiều cuộc tấn công nữa, Patterson gọi thợ săn nổi tiếng Charles Remington, người cuối cùng cũng gặp được đối thủ của mình trong đàn sư tử khát máu.</p>', 'Full', 1, 'single', 'completed', 13, 1996, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Val Kilmer","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"John Kani","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Bernard Hill","avatar":""},{"name":"Brian McCardie","avatar":""},{"name":"Om Puri","avatar":""},{"name":"Henry Cele","avatar":""},{"name":"Kurt Egelhof","avatar":""},{"name":"Satchu Annamalai","avatar":""},{"name":"Teddy Reddy","avatar":""},{"name":"Raheem Khan","avatar":""},{"name":"Jack Devnarain","avatar":""},{"name":"Glen Gabela","avatar":""},{"name":"Richard Nwamba","avatar":""},{"name":"Nick Lorentz","avatar":""},{"name":"Alex Ferns","avatar":""},{"name":"Kayc","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324539);
