INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-ten-gay', 'Mũi Tên Gãy', 'Broken Arrow', 'https://phimimg.com/upload/vod/20231111-1/f96f5d81a1698f96c9127372b7b64957.jpg', 'https://phimimg.com/upload/vod/20231111-1/6eb19e7a4ed646026edd83f2b109c482.jpg', '<p>Khi phi công tiêm kích tàng hình Vic Deakins cố tình làm rơi khỏi màn hình radar khi đang diễn tập, Lực lượng Không quân kết thúc với hai đầu đạn hạt nhân bị đánh cắp -- và đồng phi công của Deakins, Riley Hale, là hy vọng duy nhất của quân đội để lấy lại chúng. Băng qua những hẻm núi hoang vắng của Utah, Hale hợp tác với nhân viên kiểm lâm công viên Terry Carmichael để đưa Deakins trở lại hộp của mình.</p>', 'Full', 1, 'single', 'completed', 13, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Travolta","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Samantha Mathis","avatar":""},{"name":"Delroy Lindo","avatar":""},{"name":"Frank Whaley","avatar":""},{"name":"Bob Gunton","avatar":""},{"name":"Howie Long","avatar":""},{"name":"Jack Thompson","avatar":""},{"name":"Kurtwood Smith","avatar":""},{"name":"Vondie Curtis-Hall","avatar":""},{"name":"Daniel von Bargen","avatar":""},{"name":"Vyto Ruginis","avatar":""},{"name":"Ousaun Elam","avatar":""},{"name":"Shaun Toub","avatar":""},{"name":"Casey Biggs","avatar":""},{"name":"Jeffrey Stephan","avatar":""},{"name":"Joey Box","avatar":""},{"name":"Jon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324539);
