INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-trong-giang-ho-3-mot-tay-che-troi', 'Người trong giang hồ 3: Một tay che trời', 'Young & Dangerous 3', 'https://phimimg.com/upload/vod/20231110-1/381dfe807bc210b346eddcae74de6e57.jpg', 'https://phimimg.com/upload/vod/20231110-1/6d3632dfefb3c3480cee11bfb58dc54c.jpg', '<p>Thủ lĩnh Lạc Đà của băng Đông Anh bắt đầu mở rộng địa bàn.
 2 đàn em thân tín là Quạ Đen, Tiếu Diện Hổ mấy lần đụng độ Trần Hạo Nam và bàn tính mai phục Tưởng Thiên Sinh bên Hà Lan.</p>', 'Full', 1, 'single', 'completed', 14, 1996, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ekin Cheng Yee-Kin","avatar":""},{"name":"Jordan Chan","avatar":""},{"name":"Roy Cheung","avatar":""},{"name":"Karen Mok Man-Wai","avatar":""},{"name":"Gigi Lai","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Jerry Lamb Hiu-Fung","avatar":""},{"name":"Jason Chu Wing-Tong","avatar":""},{"name":"Spencer Lam","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Michael Chan","avatar":""},{"name":"Lee Siu-Kei","avatar":""},{"name":"Blackie Ko Shou-Liang","avatar":""},{"name":"Victor Hon Kwan","avatar":""},{"name":"Frankie Ng Chi-Hung","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324539);
