INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-na-den-hac-hiep', 'Mặt Nạ Đen: Hắc Hiệp', 'Black Mask', 'https://phimimg.com/upload/vod/20231110-1/cd992bad880583962d9215013116bbfb.jpg', 'https://phimimg.com/upload/vod/20231110-1/14070d58ad82d20c66ce80108e40088d.jpg', '<p>Biệt đội tinh nhuệ 701 bị cấp trên ra lệnh thủ tiêu toàn bộ nhưng không phải tất cả mọi người đều chết. Tsui là một trong những người sống sót và cố gắng quên đi quá khứ đau buồn của mình, nhưng liệu anh có thể sống một cuộc sống đời thường không khi mà sếp của đội xuất hiện và tìm mọi cách để triệt tiêu Tsui.</p>', 'Full', 1, 'single', 'completed', 12, 1996, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Lau Ching-wan","avatar":""},{"name":"Karen Mok Man-Wai","avatar":""},{"name":"Françoise Yip","avatar":""},{"name":"Kong Lung","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Henry Fong","avatar":""},{"name":"Sze Mei-Yee","avatar":""},{"name":"Roy Szeto","avatar":""},{"name":"Suk-Yee Chan","avatar":""},{"name":"Chung King-Fai","avatar":""},{"name":"Ken Lok Tat-Wah","avatar":""},{"name":"Lawrence Ah Mon","avatar":""},{"name":"Dion Lam Dik-On","avatar":""},{"name":"Russ Price","avatar":""},{"name":"Moses Chan","avatar":""},{"name":"Mike Lambert","avatar":""},{"name":"Vict","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324539);
