INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-de-doi', 'Phi Vụ Để Đời', 'Bottle Rocket', 'https://phimimg.com/upload/vod/20231110-1/65ffa6471b394bf2a3339bc6f5a7b2ae.jpg', 'https://phimimg.com/upload/vod/20231110-1/dc3c0375f9a815edc27963eba1914239.jpg', '<p>Sau khi được thả khỏi bệnh viện tâm thần sau khi bị suy nhược thần kinh, Anthony mất phương hướng kết hợp với người bạn Dignan của mình, người có vẻ kém lành mạnh hơn nhiều so với người trước. Dignan đã ấp ủ một kế hoạch rợn tóc gáy cho một vụ phạm tội chưa được xác định bằng cách nào đó có liên quan đến ông chủ cũ của anh ta, ông Henry (được cho là) huyền thoại.</p>', 'Full', 1, 'single', 'completed', 13, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Luke Wilson","avatar":""},{"name":"Robert Musgrave","avatar":""},{"name":"Lumi Cavazos","avatar":""},{"name":"Andrew Wilson","avatar":""},{"name":"James Caan","avatar":""},{"name":"Donny Caicedo","avatar":""},{"name":"Shea Fowler","avatar":""},{"name":"Jim Ponds","avatar":""},{"name":"Kumar Pallana","avatar":""},{"name":"Ned Dowd","avatar":""},{"name":"Tak Kubota","avatar":""},{"name":"Anna Cifuentes","avatar":""},{"name":"Haley Miller","avatar":""},{"name":"Brian Tenenbaum","avatar":""},{"name":"Jenni Tooley","avatar":""},{"name":"Dipak Pallana","avatar":""},{"name":"Darryl Cox","avatar":""},{"name":"Stephen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
