INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sao-hoa-tan-cong', 'Sao Hỏa Tấn Công!', 'Mars Attacks!', 'https://phimimg.com/upload/vod/20231108-1/c1faf1b8a39a60ae5f4be4866e5798d2.jpg', 'https://phimimg.com/upload/vod/20231108-1/330d87550648f285a14a156f705a2148.jpg', '<p>Một hạm đội tàu vũ trụ sao Hỏa bao quanh các thành phố lớn trên thế giới và toàn thể nhân loại chờ xem liệu những vị khách ngoài trái đất có, như họ tuyên bố, &quot;đến trong hòa bình&quot; hay không. Tổng thống Hoa Kỳ James Dale nhận được sự đảm bảo từ giáo sư khoa học Donald Kessler rằng sứ mệnh của người sao Hỏa là một sứ mệnh thân thiện. Nhưng khi một cuộc trao đổi hòa bình kết thúc với sự hủy diệt hoàn toàn của Quốc hội Hoa Kỳ, các quân nhân kêu gọi trả đũa hạt nhân toàn diện.</p>', 'Full', 1, 'single', 'completed', 13, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Nicholson","avatar":""},{"name":"Glenn Close","avatar":""},{"name":"Annette Bening","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"Martin Short","avatar":""},{"name":"Sarah Jessica Parker","avatar":""},{"name":"Michael J. Fox","avatar":""},{"name":"Rod Steiger","avatar":""},{"name":"Tom Jones","avatar":""},{"name":"Lukas Haas","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Jim Brown","avatar":""},{"name":"Lisa Marie","avatar":""},{"name":"Sylvia Sidney","avatar":""},{"name":"Paul Winfield","avatar":""},{"name":"Pam Grier","avatar":""},{"name":"Jack Black","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"6856