INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-diep-vien-cung-cua', 'Chàng Điệp Viên... Cứng Cựa', 'Spy Hard', 'https://phimimg.com/upload/vod/20231108-1/0955ba8728cac4d79dc1521616658c7d.jpg', 'https://phimimg.com/upload/vod/20231108-1/62e0474c11bc35b8fa0668898d806cfd.jpg', '<p>Vị tướng độc ác Rancor có tham vọng thống trị thế giới và chỉ có một người có thể ngăn chặn hắn: Dick Steele, còn được gọi là Đặc vụ WD-40. Rancor cần lấy một mạch máy tính cho tên lửa mà anh ta định bắn, vì vậy Steele hợp tác với Veronique Ukrinsky, một đặc vụ KGB có cha là người thiết kế con chip. Họ cùng nhau cố gắng xác định vị trí trụ sở của kẻ chủ mưu độc ác, nơi cha của Veronique và một số con tin khác đang bị giam giữ.</p>', 'Full', 1, 'single', 'completed', 14, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Leslie Nielsen","avatar":""},{"name":"Nicollette Sheridan","avatar":""},{"name":"Charles Durning","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"Barry Bostwick","avatar":""},{"name":"Andy Griffith","avatar":""},{"name":"Stephanie Romanov","avatar":""},{"name":"Talisa Soto","avatar":""},{"name":"Robert Guillaume","avatar":""},{"name":"Carl Ciarfalio","avatar":""},{"name":"Keith Campbell","avatar":""},{"name":"Esau McKnight","avatar":""},{"name":"Taylor Negron","avatar":""},{"name":"\"Weird Al\" Yankovic","avatar":""},{"name":"Alex Tre","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324539);
