INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoat-y-vu', 'Thoát Y Vũ', 'Striptease', 'https://phimimg.com/upload/vod/20231031-1/c11195d96cd3c9f8368e0794097ead2f.jpg', 'https://phimimg.com/upload/vod/20231031-1/d3a284861015a340ca1a5916b3a13fc6.jpg', '<p>Bị đuổi việc, Erin Grant cần tiền nếu muốn có cơ hội giành lại quyền nuôi con. Nhưng, cuối cùng, cô ấy phải đối mặt với sự thật trần trụi: để tiếp nhận hệ thống, cô ấy sẽ phải cởi bỏ tất cả. Erin lột xác để chinh phục, nhưng cô phải đối mặt với những tình huống ngoài ý muốn khi một con chó săn của một Nghị sĩ tập trung vào cô và mài giũa những công cụ mờ ám trong tầm tay của anh ta, bao gồm cả tống tiền và giết người.</p>', 'Full', 1, 'single', 'completed', 14, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Demi Moore","avatar":""},{"name":"Burt Reynolds","avatar":""},{"name":"Armand Assante","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Paul Guilfoyle","avatar":""},{"name":"Rumer Willis","avatar":""},{"name":"Jerry Grayson","avatar":""},{"name":"Robert Stanton","avatar":""},{"name":"Stuart Pankin","avatar":""},{"name":"Pandora Peaks","avatar":""},{"name":"Barbara Alyn Woods","avatar":""},{"name":"Kimberly Flynn","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Frances Fisher","avatar":""},{"name":"Rena Riffel","avatar":""},{"name":"Dina","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
