INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-ly-va-nguoi-tinh', 'Quản Lý và Người Tình', 'Jerry Maguire', 'https://phimimg.com/upload/vod/20231029-1/c5b764a50089ff278f6dcd6acde1e080.jpg', 'https://phimimg.com/upload/vod/20231029-1/19952d253932e47fbc55603a4aa759c9.jpg', '<p>JERRY MAGUIRE : Jerry Maguire là một nhà đại diện thể thao chuyên nghiệp: anh luôn tìm đủ mọi cách, mọi thủ đoạn để có thể quảng bá và kiếm lời cho thân chủ của mình và bản thân. Một ngày kia anh bỗng trở nên nghi ngờ ý nghĩa của công việc mình đang làm.Khi nói lên điều này, anh đã bị đuổi việc và mất tất cả các thân chủ của mình. Quyết tâm làm lại từ đầu, anh tìm đến Rod Tidwell, một cầu thủ chơi bóng bầu dục để thuyết phục anh ta nhận anh làm gnười đại diện. Mọi việc thực sự khó khăn. Jerry khánh kiệt và hầu như làm không công cho vợ chồng Rod. Bù lại, anh có tình yêu chân thành từ Dorothy, một thu ngân của công ty cũ nơi anh làm.Bằng sự chân thành và quyết tâm, Jerry đã cố gắng vượt qua mọi khó khăn, có lúc tưởng như gục ngã.</p>', 'Full', 1, 'single', 'completed', 15, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Renée Zellweger","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Kelly Preston","avatar":""},{"name":"Jerry O''Connell","avatar":""},{"name":"Jay Mohr","avatar":""},{"name":"Regina King","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Jonathan Lipnicki","avatar":""},{"name":"Todd Louiso","avatar":""},{"name":"Mark Pellington","avatar":""},{"name":"Jeremy Suarez","avatar":""},{"name":"Jared Jussim","avatar":""},{"name":"Benjamin Kimball Smith","avatar":""},{"name":"Ingrid Beer","avatar":""},{"name":"Jann Wenner","avatar":""},{"name":"Nada De","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324539);
