INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('james-va-qua-dao-khong-lo', 'James và Quả Đào Khổng Lồ', 'James and the Giant Peach', 'https://phimimg.com/upload/vod/20231030-1/4bb130b6292b40063016c465694205f1.jpg', 'https://phimimg.com/upload/vod/20231030-1/a2c76483c54bbeaed25390a59d66829e.jpg', '<p>Khi cậu bé mồ côi James đánh rơi chiếc túi ma thuật chứa lưỡi cá sấu, cậu nhận ra mình đang sở hữu một quả đào khổng lồ đưa cậu đến những vùng đất xa lạ.</p>', 'Full', 1, 'single', 'completed', 15, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paul Terry","avatar":""},{"name":"Miriam Margolyes","avatar":""},{"name":"Joanna Lumley","avatar":""},{"name":"Pete Postlethwaite","avatar":""},{"name":"Simon Callow","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"Jane Leeves","avatar":""},{"name":"Susan Sarandon","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Steven Culp","avatar":""},{"name":"Susan Turner-Cray","avatar":""},{"name":"Cirocco Dunlap","avatar":""},{"name":"Kathryn Howell","avatar":""},{"name":"Mike Starr","avatar":""},{"name":"Michael Girardin","avatar":""},{"name":"J. Stephen Coyle","avatar":""},{"name":"To","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324539);
