INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('benh-nhan-nguoi-anh', 'Bệnh Nhân Người Anh', 'The English Patient', 'https://phimimg.com/upload/vod/20231030-1/46d3ad62134e85e7d5834bd9dc18e076.jpg', 'https://phimimg.com/upload/vod/20231030-1/2070a2680c63fa7a43a01934e21adbb2.jpg', '<p>Phim bắt đầu với cảnh chiếc máy bay bị rơi giữa sa mạc Sahara trong thời kỳ hậu chiến tranh thế giới thứ 2, trong máy bay chỉ còn hai hành khách. Toàn bộ nội dung phim xoay quanh cuộc đời và số phận của hai con người này cũng như những gì sẽ xảy ra với họ.Thời điểm hiện tại của phim diễn ra ở Italy những ngày cuối cùng của cuộc chiến tranh thế giới thứ 2. Một người đàn ông bị cháy xém như cái tên của tiêu đề phim - bệnh nhân người Anh - được nữ y tá xinh đẹp Hana (Juliette Binoche) ở lại chăm sóc trong một tu viện cũ kỹ hoang tàn. Hana đã biến nơi này thành một “bệnh viện” tạm bợ để chăm sóc bệnh nhân của cô. Một ngày kia “bệnh viện” có thêm sự xuất hiện của những người lạ, đó là hai chuyên gia phá bom mìn và một ...</p>', 'Full', 1, 'single', 'completed', 19, 1996, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ralph Fiennes","avatar":""},{"name":"Juliette Binoche","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Naveen Andrews","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Julian Wadham","avatar":""},{"name":"Torri Higginson","avatar":""},{"name":"Jürgen Prochnow","avatar":""},{"name":"Kevin Whately","avatar":""},{"name":"Clive Merrison","avatar":""},{"name":"Nino Castelnuovo","avatar":""},{"name":"Hichem Rostom","avatar":""},{"name":"Peter Rühring","avatar":""},{"name":"Geordie Johnson","avatar":""},{"name":"Liisa Repo-M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324539);
