INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-ngu-mo', 'Những Kẻ Ngủ Mơ', 'Sleepers', 'https://phimimg.com/upload/vod/20231026-1/a140183c14d82d854e7147c5a521f069.jpg', 'https://phimimg.com/upload/vod/20231026-1/b861c7e7c1b1081c7462ed3e6948819a.jpg', '<p>Truyện phim bắt đầu từ lời kể của một người đàn ông tên Michael về nhóm bạn thời thơ ấu của mình: vào những năm 1960, cậu bé Miachel và 3 người bạn của mình sống ở khu phố Hells Kitchen, 1 khu phố nghèo trộm cướp có, ma túy có, vợ chồng đánh nhau... Hẳn nhiên ở 1 nơi như vậy thì các cậu bé này cũng không thể tránh khỏi chuyện thường hay bày trò quậy phá và một ngày nọ, những trò quậy phá đó đã dẫn đến thảm kịch khi một ngươì đã thiệt mạng do lỗi của nhóm.Cả 4 bị gửi vào trại giáo dưỡng cho trẻ em quậy phá bất chấp nỗ lực xin giảm án của Cha Bobby (Robert de Niro), linh mục của dân phố Hells Kitchen. Và bi kịch cuộc đời của họ bắt đầu từ đây</p>', 'Full', 1, 'single', 'completed', 13, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Bacon","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Dustin Hoffman","avatar":""},{"name":"Jason Patric","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Brad Renfro","avatar":""},{"name":"Minnie Driver","avatar":""},{"name":"Billy Crudup","avatar":""},{"name":"Ron Eldard","avatar":""},{"name":"Vittorio Gassman","avatar":""},{"name":"Terry Kinney","avatar":""},{"name":"Bruno Kirby","avatar":""},{"name":"Frank Medrano","avatar":""},{"name":"Joe Perrino","avatar":""},{"name":"Geoffrey Wigdor","avatar":""},{"name":"Jonathan Tucker","avatar":""},{"name":"Peter Appel","avatar":""},{"name":"Joseph Atta","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6