INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-gu-o-nha-tho-duc-ba', 'Thằng Gù Ở Nhà Thờ Đức Bà', 'The Hunchback of Notre Dame', 'https://phimimg.com/upload/vod/20231024-1/c9ff72295f6549b2df8ea91f71627f2e.jpg', 'https://phimimg.com/upload/vod/20231024-1/a51d43c985199385a66ad15c999d8018.jpg', '<p>Câu chuyện phim dựa theo nội dung cuốn tiểu thuyết “Nhà thờ Đức Bà Paris” (Notre-Dame de Paris) của đại văn hào Pháp, Victor Hugo, xuất bản năm 1831. Nội dung nói lên mối tình tuyệt vọng được cho là bất diệt của một con người xấu xí như một quái vật tên Quasimodo, đối với một cô gái du mục Gypsi xinh đẹp tên Esméralda. (Gypsi là một sắc tộc thiểu số của người Romani sống ở châu Âu. Bohémien là lối sống du mục, rày đây mai đó với sinh hoạt là những đêm cắm trại, mà những thiếu nữ tung váy sặc sở trong những điệu vũ nóng bỏng, mê hoặc. Họ hầu như không có nghề nghiệp lương thiện, phần đông sống bằng nghề bói toán và trộm cắp, chôm chỉa) Những nhân vật chính như Quasimodo, Esméralda kết cuộc đều chết hết, nhưng mối tình ...</p>', 'Full', 1, 'hoathinh', 'completed', 19, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hulce","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Heidi Mollenhauer","avatar":""},{"name":"Tony Jay","avatar":""},{"name":"Kevin Kline","avatar":""},{"name":"Charles Kimbrough","avatar":""},{"name":"Mary Wickes","avatar":""},{"name":"Jane Withers","avatar":""},{"name":"Jason Alexander","avatar":""},{"name":"Paul Kandel","avatar":""},{"name":"Mary Kay Bergman","avatar":""},{"name":"David Ogden Stiers","avatar":""},{"name":"Gary Trousdale","avatar":""},{"name":"Corey Burton","avatar":""},{"name":"Bill Fagerbakke","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Patrick Pinney","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324539);
