INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-vo', 'Đổ Vỡ', 'Crash', 'https://phimimg.com/upload/vod/20231023-1/c9fa81b573651c84131ff5722f81c46b.jpg', 'https://phimimg.com/upload/vod/20231023-1/e6ef1ed4d4c755794974e2e340444b1a.jpg', '<p>Bộ phim ra đời năm 1996 kể về một nhà sản xuất phim (James Spader) có một cuộc hôn nhân cởi mở với người vợ (Holly Hunter). Một tai nạn giao thông làm thay đổi hoàn toàn đời sống tình dục của họ. Tất cả các nhân vật trong phim đều mắc một chứng nghiện sex kỳ lạ. Những cảnh nóng trần trụi được kết hợp với những cảnh tai nạn đẫm máu. Mặc dù Crash từng giành một giải thưởng đặc biệt vì “tính sáng tạo và táo bạo” tại LHP Cannes nhưng tác phẩm này đã khiến nhiều khán giả phải đứng dậy bỏ về vì phẫn nộ và cảm thấy ghê tởm.</p>', 'Full', 1, 'single', 'completed', 21, 1996, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"James Spader","avatar":""},{"name":"Holly Hunter","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Deborah Kara Unger","avatar":""},{"name":"Rosanna Arquette","avatar":""},{"name":"Peter MacNeill","avatar":""},{"name":"Cheryl Swarts","avatar":""},{"name":"Yolande Julian","avatar":""},{"name":"Nicky Guadagni","avatar":""},{"name":"Ronn Sarosiak","avatar":""},{"name":"Boyd Banks","avatar":""},{"name":"Judah Katz","avatar":""},{"name":"Markus Parilo","avatar":""},{"name":"Alice Poon","avatar":""},{"name":"John Stoneham Jr.","avatar":""},{"name":"David Cronenberg","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
