INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-hoc-duong-1996', 'Phù Thủy Học Đường', 'The Craft', 'https://phimimg.com/upload/vod/20231016-1/358086f8c5d32142d05c5b179219f120.jpg', 'https://phimimg.com/upload/vod/20231016-1/a69cc5af6c056eaaf78d99c16e12ecb1.jpg', '<p>Ở một ngôi trường Công giáo, cô học sinh mới nhập bọn với đám phù thủy tuổi teen chuyên dùng phép thuật để đối phó với bất cứ ai cản đường họ, ngay cả bố mẹ họ.</p>', 'Full', 1, 'single', 'completed', 14, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robin Tunney","avatar":""},{"name":"Fairuza Balk","avatar":""},{"name":"Neve Campbell","avatar":""},{"name":"Rachel True","avatar":""},{"name":"Skeet Ulrich","avatar":""},{"name":"Christine Taylor","avatar":""},{"name":"Breckin Meyer","avatar":""},{"name":"Nathaniel Marston","avatar":""},{"name":"Cliff DeYoung","avatar":""},{"name":"Assumpta Serna","avatar":""},{"name":"Helen Shaver","avatar":""},{"name":"Jeanine Jackson","avatar":""},{"name":"Brenda Strong","avatar":""},{"name":"Elizabeth Guber","avatar":""},{"name":"Jennifer Greenhut","avatar":""},{"name":"Arthur Senzy","avatar":""},{"name":"Endre","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324539);
