INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-xoa-so', 'Kẻ Xóa Sổ', 'Eraser', 'https://phimimg.com/upload/vod/20231015-1/10cd3e31f9e80a51c5a8c95705501659.jpg', 'https://phimimg.com/upload/vod/20231015-1/564a962e909d9b3576c92ca5fcf5969c.jpg', '<p>Sỹ quan John Kruger thuộc chương trình bảo vệ nhân chứng. Anh có nhiệm vụ “xóa sổ” tung tích của họ khỏi những kẻ truy lùng . Lee Cullen, một nhân viên của tập đoàn Cyrez, là nhân viên nằm vùng của FBI. Cô đã phát giác ra loại vũ khí sử dụng từ trường mà tập đoàn này đang nghiên cứu. Cyrez không thể để Lee tiếp tục tuồn thông tin cho FBI và lên kế hoạch trừ khử cô… Lee được giao cho John bảo vệ. Sự vụ trở nên nghiêm trọng hơn khi John phát giác ra một đồng đội của anh cũng dính líu sâu sắc với việc buôn bán loại vũ khí nguy hiểm mà Cyrez vừa nghiên cứu thành công!</p>', 'Full', 1, 'single', 'completed', 21, 1996, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Vanessa Williams","avatar":""},{"name":"James Caan","avatar":""},{"name":"James Coburn","avatar":""},{"name":"Robert Pastorelli","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Danny Nucci","avatar":""},{"name":"Andy Romano","avatar":""},{"name":"Nick Chinlund","avatar":""},{"name":"Michael Papajohn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324539);
