INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('101-chu-cho-dom-1996', '101 Chú Chó Đốm', '101 Dalmatians', 'https://phimimg.com/upload/vod/20231015-1/2a9dc1093ceeed40d3c27623d13cfc8f.jpg', 'https://phimimg.com/upload/vod/20231015-1/b5061db30338b630dad37ead16f30dcc.jpg', '<p>Câu chuyện xảy ra tại London. Có một chú chó đốm tên là Pongo, sống chung với cậu chủ Roger Radcliff - chuyên viết nhạc và sống độc thân. Cậu đã tìm vợ cho cậu chủ của mình và tìm được một nửa cho chính mình, nàng chó đốm Perdita. Họ sống với nhau thật hạnh phúc... cho đến khi Perdita sinh hạ 15 chú chó con. Mụ chủ nhà Cruella Devil say mê điên cuống những chiếc áo lông thú, đã đánh cắp bầy chó đốm con. Số phận của Pongo và Perdita chắc chắn cũng sẽ tồi tệ như thế nếu như hai người chủ tốt bụng của chúng quyết định bằng mọi cách tìm lại các cục cưng của mình. Trong cuộc hành trình đó, tình cờ họ lại được chiêm ngưỡng thêm 99 chú chó đốm tuyệt đẹp khác.</p>', 'Full', 1, 'single', 'completed', 20, 1996, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Glenn Close","avatar":""},{"name":"Jeff Daniels","avatar":""},{"name":"Joely Richardson","avatar":""},{"name":"Joan Plowright","avatar":""},{"name":"Hugh Laurie","avatar":""},{"name":"Mark Williams","avatar":""},{"name":"John Shrapnel","avatar":""},{"name":"Tim McInnerny","avatar":""},{"name":"Hugh Fraser","avatar":""},{"name":"Zohren Weiss","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324539);
