INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-tinh-nam-nu', 'Sắc Tình Nam Nữ', 'Viva Erotica', 'https://phimimg.com/upload/vod/20231015-1/91b4751d77b3d4079a442ab658dd39fc.jpg', 'https://phimimg.com/upload/vod/20231015-1/ea0d2790e2b722ce475d0d8cc3d62d6a.jpg', '<p>Phim Sắc Tình Nam Nữ - Viva Erotica (1997): đạo diễn Nhĩ Đông Thăng và La Chí Lương đã chung tay thực hiện một tác phẩm về đề tài tình dục đặc sắc với dàn diễn viên tên tuổi như Trương Quốc Vinh, Thư Kỳ, Mạc Văn Úy… Nội dung kể về một đạo diễn trẻ, vì mưu sinh nên đã nhận lời dàn dựng một bộ phim rẻ tiền, Sắc tình nam nữ phản ánh tất cả sự cay đắng của những người tham gia làm phim ba tại Hong Kong thời điểm đó. Phim đã mang về cho Thư Kỳ 2 giải thưởng Nữ diễn viên phụ xuất sắc và Diễn viên trẻ triển vọng trong LHP Hong Kong năm 1997.</p>', 'Full', 1, 'single', 'completed', 17, 1996, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Leslie Cheung","avatar":""},{"name":"Karen Mok","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Elvis Tsui","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Lau Ching-wan","avatar":""},{"name":"Allen Ting","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Man Lan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
