INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-doc-lap', 'Ngày Độc Lập', 'Independence Day', 'https://phimimg.com/upload/vod/20231015-1/79046ba8297678acab46bb4d5ba3d62d.jpg', 'https://phimimg.com/upload/vod/20231015-1/6ae8563af56452ef2561db85d1337ba3.jpg', '<p>Người ngoài hành tinh đã đến trái đất và mục tiêu của họ là để chiếm lấy tài nguyên và phá huỷ. Chiến đấu bằng công nghệ cao, sử dụng vũ khí tốt nhất của con người là cách duy nhất để tồn tại. Vũ khí hạt nhân đã được sử dụng...</p>', 'Full', 1, 'single', 'completed', 19, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Mary McDonnell","avatar":""},{"name":"Judd Hirsch","avatar":""},{"name":"Robert Loggia","avatar":""},{"name":"Randy Quaid","avatar":""},{"name":"Margaret Colin","avatar":""},{"name":"James Rebhorn","avatar":""},{"name":"Harvey Fierstein","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324539);
