INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-moment-of-romance-3', 'A Moment of Romance 3', 'A Moment of Romance 3', 'null', 'https://phimimg.com/upload/vod/20231013-1/7daab51b22ae35af2a4c997a67eed9c8.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Trong những ngày đầu của Chiến tranh chống Nhật, Liu Tianwei (do Andy Lau thủ vai), con trai thứ hai của gia đình Lưu, một gia đình trong giới quân sự và chính trị Vũ Hán, từng là trung úy bay trong bộ phận không quân. Trong một lần làm nhiệm vụ, anh gặp phải đội quân Nhật Bản hung dữ, mặc dù đã trốn thoát nhưng không bị thương nhẹ, buộc phải đổ bộ xuống một ngôi làng nhỏ trên núi, và được dì làng Xiaohe (do Wu Qianlian) thủ vai, giải cứu. Dưới sự chăm sóc cẩn thận của Xiaohe, Tianwei dần hồi phục, và hai người yêu nhau, nhưng bị trưởng thôn phản đối. Tianwei quyết định đưa Xiao He cùng rời khỏi làng, nhưng Xiao He không bắt được máy bay. Trên đường trở về căn cứ, anh gặp lại máy bay địch, hai chiếc máy bay bị quân Nhật bắn hạ, đồng nghiệp cảm thấy Thiên Vĩ đã làm mọi người mệt mỏi, nhưng gia đình anh đã tổ chức một buổi lễ chào đón hoành tráng cho anh, điều này khiến Tianwei rất khó chịu. Vào thời điểm này, chính phủ Quốc dân đảng quyết định đến Trùng Khánh, và để bảo vệ đội quân lớn, không quân sẽ thực hiện một nhiệm vụ tử thần, đó là ném bom căn cứ Nhật Bản. Tianwei quyết định tham gia bất chấp sự phản đối của gia đình, và đội trưởng (do Fang Zhongxin thủ vai) lần đầu tiên phản đối và cảm động trước sự khăng khăng của Tianwei, và sự hiểu lầm giữa các đồng nghiệp đã được loại bỏ. Lúc này, Tiểu Hà cũng đến Vũ Hán tìm Thiên Ngụy, nói dù thế nào cũng sẽ đợi Thiên Vĩ trở về. Sau khi chiến dịch bắt đầu, Tiêu Hà và Ngụy Mục cùng nhau chờ Thiên Vĩ ở căn cứ, nhưng chỉ chờ tin tức Thiên Vĩ tử vì đạo, Tiêu Hà khăng khăng dọn dẹp sân bay bất chấp cản trở, chờ đợi kỳ tích, mọi người đều cảm động, cuối cùng Thiên Vĩ thật sự bay về căn cứ một cách thần kỳ.</span></p>', 'Full', 1, 'single', 'completed', 15, 1996, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Wu Qianlian","avatar":""},{"name":"Fang Zhongxin","avatar":""},{"name":"Fan Zhigang","avatar":""},{"name":"Leung Pak-kin","avatar":""},{"name":"Yu Yongzhen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
