INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loc-xoay', 'Lốc Xoáy', 'Twister', 'https://phimimg.com/upload/vod/20230926-1/917a4c1820c162f8572e6a1d784a9fab.jpg', 'https://phimimg.com/upload/vod/20230926-1/d6b44995a58a0c71161a0b14ba8f828a.jpg', '<p>Một loạt lốc xoáy dữ dội chưa từng có đang quét qua Oklahoma. Những người đuổi theo cơn lốc xoáy, do Tiến sĩ Jo Harding đứng đầu, cố gắng phát hành một thiết bị đột phá cho phép họ theo dõi chúng và tạo ra một hệ thống cảnh báo tiên tiến hơn. Họ có sự tham gia của Jo sắp trở thành chồng cũ Bill, một cựu thợ săn lốc xoáy và bạn gái Melissa của anh ấy.</p>', 'Full', 1, 'single', 'completed', 22, 1996, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Helen Hunt","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Jami Gertz","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Lois Smith","avatar":""},{"name":"Alan Ruck","avatar":""},{"name":"Sean Whalen","avatar":""},{"name":"Scott Thomson","avatar":""},{"name":"Todd Field","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324539);
