INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-hiep-dai-chien-thanh-bai-2', 'Hắc Hiệp Đại Chiến Thánh Bài 2', 'The Saint Of Gamblers', 'https://phimimg.com/uploads/movies/20260713/hac-hiep-dai-chien-thanh-bai-2-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/hac-hiep-dai-chien-thanh-bai-2-poster.webp', '<p>Sau khi A Tinh trở nên nổi tiếng, cùng với Đỗ Hiệp và Thánh bài đi khắp nơi du đấu để lại đó là một mình chú hai của A Tinh là Đạt Đen, người có công lớn trong việc đưa tên tuổi cũng như tài năng đặc biệt của A Tinh chi nhiều người biết tới. Giờ đây, chú Đạt cần phải làm cái gì đó để có thể kiếm tiền sau chuỗi ngày bên cạnh A Tinh, vì thế chú chọn cách là đi tìm một A Tinh thứ 2 với những khả năng đặc biệt, một truyền nhân mới của Đỗ Thánh chắc chắn sẽ giúp chú Đạt tiếp tục sống dư dả mà không phải lo về chuyện tiền bạc.Nơi mà ông ta hướng tới chính là một ngôi làng nổi tiếng với những người có công năng đặc dị.</p>', 'Full', 1, 'single', 'completed', 46, 1995, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Eric Kot Man-Fai","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Chingmy Yau Suk-Ching","avatar":""},{"name":"Ben Lam Kwok-Bun","avatar":""},{"name":"Diana Pang Dan","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Ashton Chen","avatar":""},{"name":"Corey Yuen","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"John Ching Tung","avatar":""},{"name":"William Duen Wai-Lun","avatar":""},{"name":"Natalis Chan Pak-Cheung","avatar":""},{"name":"Manfred Wong Man-Chun","avatar":""},{"name":"Lo Fan","avatar":""},{"name":"Teresa Ha Ping","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["赌圣2：街头赌圣","賭聖2之街頭賭聖","The Saint of the Gamblers","Olhos de Serpente","賭聖II：街頭賭聖"]', 1784690324539);
