INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-bien-tinh-quan', 'Bách Biến Tinh Quân', 'Sixty Million Dollar Man', 'https://phimimg.com/uploads/movies/20260713/bach-bien-tinh-quan-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/bach-bien-tinh-quan-poster.webp', '<p>Trong phim Bách Biến Tinh Quân - Sixty Million Dollar Man 1995, một chàng trai trẻ bị bọn đầu gấu đánh đến gần chết vì đã đụng đến con gái yêu của một trùm xã hội đen. Nhưng trong phim này, anh đã được một vị bác sĩ khùng cứu chữa sống lại và biến anh trở thành một người có thể thay đổi nhân dạng của mình, và từ đó những cuộc trả thù hài hước được thực hiện dưới tay của người hùng mới này.</p>', 'Full', 1, 'single', 'completed', 51, 1995, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Gigi Leung Wing-Kei","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Paulyn Sun","avatar":""},{"name":"Joe Cheng Cho","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Manfred Wong Man-Chun","avatar":""},{"name":"Alvina Kong Yan-Yin","avatar":""},{"name":"Johnny Tang Siu-Chun","avatar":""},{"name":"Mimi Chu Mai-Mai","avatar":""},{"name":"Wong Yat-Fei","avatar":""},{"name":"Guy Lai Ying-Chau","avatar":""},{"name":"Lee Kin-Yan","avatar":""},{"name":"Sung Boon-Chung","avatar":""},{"name":"Chan Chi-Fai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Baak bin sing gwan","Bai bian xing jun","Sixty Million Dollar Man","คนไม่ธรรมดายืดได้หดได้","百变星君","百變