INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-thoai-tay-du-phan-ii-tien-ly-ky-duyen', 'Đại Thoại Tây Du Phần II: Tiên Lý Kỳ Duyên', 'A Chinese Odyssey Part Two: Cinderella', 'https://phimimg.com/uploads/movies/20260713/dai-thoai-tay-du-phan-ii-tien-ly-ky-duyen-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/dai-thoai-tay-du-phan-ii-tien-ly-ky-duyen-poster.webp', '<p>Ở phần trước, để có thể trở về hình dạng ban đầu của mình, Tôn Ngộ Không phải dùng đến chiếc hộp Nguyệt Quang, nhưng tại đây anh lại đụng độ với Tử Hà và bị cô nàng phá đám bằng cách hoán đổi tính cách của Tôn Ngộ Không và em của mình. Tệ hơn nữa là Tôn Ngộ Không lại muốn trở về tương lai tìm vợ của mình nhưng liệu có được hay không khi mà Tử Hà đang tìm đủ mọi cách để ngăn chặn không cho Tôn Ngộ Không trở về tương lai.</p>', 'Full', 1, 'single', 'completed', 55, 1995, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Tinh Trì","avatar":""},{"name":"Ngô Mạnh Đạt","avatar":""},{"name":"Chu Nhân","avatar":""},{"name":"Thái Thiếu Phân","avatar":""},{"name":"Mạc Văn Úy","avatar":""},{"name":"Lam Khiết Anh","avatar":""},{"name":"La Gia Anh","avatar":""},{"name":"Lưu Trấn Vĩ","avatar":""},{"name":"Lục Thụ Minh","avatar":""},{"name":"Lý Kiện Nhân","avatar":""},{"name":"Giang Ước Thành","avatar":""},{"name":"Ngô Ngọc Cẩn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","i