INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-thoai-tay-du-phan-ii-tien-ly-ky-duyen', 'Đại Thoại Tây Du Phần II: Tiên Lý Kỳ Duyên', 'A Chinese Odyssey Part Two: Cinderella', 'đại thoại tây du phần ii: tiên lý kỳ duyên a chinese odyssey part two: cinderella châu tinh trì ngô mạnh đạt chu nhân thái thiếu phân mạc văn úy lam khiết anh la gia anh lưu trấn vĩ lục thụ minh lý kiện nhân giang ước thành ngô ngọc cẩn stephen chow a chinese odyssey part two - cinderella 西游记ii之仙履奇缘 선리기연 서유기-선리기연 a chinese odyssey part ii-cinderella đại thoại tây du 2 - tiên lý kỳ duyên (1995) tây du ký 2 - tiên lý kỳ duyên (1995) a chinese odyssey ii -- cinderella ไซอิ๋วกี่ เดี๋ยวลิงเดี๋ยวคน 2 a chinese odyssey part 2 sai yau gei: sin leui kei yun a chinese odyssey part two a chinese odyssey part ii le roi singe 2 - cendrillon xi you ji da jie ju zhi xian lu qi yuan a kínai odüsszeusz 2. チャイニーズ・オデッセイ part1 月光の恋 китайская одиссея 2: золушка 西遊記大結局之仙履奇緣 a chinese odyssey part ii cinderella a chinese odyssey part two cinderella 서유기 part 2 - 선리기연 서유기 part 2: 선리기연 a chinese odyssey vol 2 pandora''s box 大话西游之仙履奇缘', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-thoai-tay-du-i-nguyet-quang-bao-hap', 'Đại Thoại Tây Du I: Nguyệt Quang Bảo Hạp', 'A Chinese Odyssey Part One: Pandora''s Box', 'https://phimimg.com/uploads/movies/20260713/dai-thoai-tay-du-i-nguyet-quang-bao-hap-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/dai-thoai-tay-du-i-nguyet-quang-bao-hap-poster.webp', '<p>500 năm trước, Tôn Ngộ Không vì có âm mưu để Ngưu Ma Vương ăn thịt Đường Tăng và đánh cắp Nguyệt Quang Bảo Hợp nên bị Quan Âm trừng phạt. 500 năm sau, hậu thân của Tôn Ngộ Không là Chí Tôn Bảo trở thành bang chủ của toán cướp chuyên hành nghề trên vùng sa mạc. Trong một lần tình cờ Chí Tôn Bảo bắt gặp hai chị em yêu tinh Xuân Tam Thập Nương - Bạch Tinh Tinh và bị hai người bắt về Động Bàn Tơ cùng với thủ hạ của Chí Tôn Bảo là Nhị Đương Gia. Tại đây Chí Tôn Bảo nhặt được Nguyệt Quang Bảo Hợp - bảo vật của Bàn Tơ Đại Tiên và quay trở lại quá khứ 500 năm trước.</p>', 'Full', 1, 'single', 'completed', 61, 1995, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Tinh Trì","avatar":""},{"name":"Ngô Mạnh Đạt","avatar":""},{"name":"La Gia Anh","avatar":""},{"name":"Mạc Văn Úy","avatar":""},{"name":"Lam Khiết Anh","avatar":""},{"name":"Chu Nhân","avatar":""},{"name":"Lưu Trấn Vĩ","avatar":""},{"name":"Giang Ước Thành","avatar":""},{"name":"Lục Thụ Minh","avatar":""},{"name":"Lý Kiện Nhân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["A Chinese Odyssey Part One - Pandora''s Box","西游记I之月光宝盒","Le roi singe 1 - La boîte de Pandore","西遊記第壹佰零壹回之月光寶盒","월광보합","서유기-월광보합","A Chinese Odyssey Part I-Pandora''s Box","Đại Thoại Tây Du - Nguyệt Quang Bảo Hợp","Tây Du Ký - Nguyệt Quang Bảo Hợp (1995)","Eine chinesische Odyssee","ไซอิ๋วกี่ เดี๋ยวลิงเดี๋ยวคน","A Chinese Odyssey Part 1","A.Chinese.Odyssey.Part.I.Pandoras.Box","A Chinese Odyssey I -- Pandora''s Box","大话西游之月光宝盒","Sai yau gei - Yut gwong bou haap","Da Hua Xi You Zhi Yue Guang Bao He","서유기 Part 1 - 월광보합","서유기 Part 1: 월광보합","A Chinese Odyssey Vol 1 Pandora''s Box"]', 1784690324539);
