INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-thoai-tay-du-i-nguyet-quang-bao-hap', 'Đại Thoại Tây Du I: Nguyệt Quang Bảo Hạp', 'A Chinese Odyssey Part One: Pandora''s Box', 'đại thoại tây du i: nguyệt quang bảo hạp a chinese odyssey part one: pandora''s box châu tinh trì ngô mạnh đạt la gia anh mạc văn úy lam khiết anh chu nhân lưu trấn vĩ giang ước thành lục thụ minh lý kiện nhân stephen chow a chinese odyssey part one - pandora''s box 西游记i之月光宝盒 le roi singe 1 - la boîte de pandore 西遊記第壹佰零壹回之月光寶盒 월광보합 서유기-월광보합 a chinese odyssey part i-pandora''s box đại thoại tây du - nguyệt quang bảo hợp tây du ký - nguyệt quang bảo hợp (1995) eine chinesische odyssee ไซอิ๋วกี่ เดี๋ยวลิงเดี๋ยวคน a chinese odyssey part 1 a.chinese.odyssey.part.i.pandoras.box a chinese odyssey i -- pandora''s box 大话西游之月光宝盒 sai yau gei - yut gwong bou haap da hua xi you zhi yue guang bao he 서유기 part 1 - 월광보합 서유기 part 1: 월광보합 a chinese odyssey vol 1 pandora''s box', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-hanh-phuc-mai-mai-truyen-co-tich-cho-moi-dua-tre', 'Sống Hạnh Phúc Mãi Mãi: Truyện Cổ Tích Cho Mọi Đứa Trẻ', 'Happily Ever After: Fairy Tales for Every Child', 'https://phimimg.com/upload/vod/20260620-1/faa03bfd68f330b0fb77ef8f83c8ae57.jpg', 'https://phimimg.com/upload/vod/20260620-1/0de2d47e52fc82f6ff59bcd9aaf6f396.jpg', '<p><em>Happily Ever After: Fairy Tales for Every Child</em> là một loạt phim truyền hình hoạt hình tuyển tập của Mỹ. Bộ phim kể lại các câu chuyện cổ tích kinh điển quen thuộc nhưng được làm mới hoàn toàn dưới góc nhìn đa văn hóa, đa sắc tộc, kết hợp với các phong cách âm nhạc độc đáo và sự tham gia lồng tiếng của nhiều ngôi sao nổi tiếng.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 42, 1995, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robert Guillaume","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Happily Ever After: Fairy Tales for Every Child"]', 1784690324539);
