INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ban-kem', 'Người Bán Kem', 'Ice Cream Man', 'https://phimimg.com/upload/vod/20260610-1/ad712538346a0403506ca70f517d7b9c.jpg', 'https://phimimg.com/upload/vod/20260610-1/d17814fcb40adb9acb566432a668aa03.jpg', '<p>Khi còn nhỏ, Gregory Tudor đã tận mắt chứng kiến người bán kem trong vùng bị sát hại. Khi trưởng thành, hắn kế thừa chính công việc kinh doanh này, nhưng lại chọn cách tiêm những nguyên liệu ghê rợn — bao gồm cả các bộ phận cơ thể người — vào trong những món kem mát lạnh của mình. Đến khi một cậu bé trong khu phố đột ngột mất tích, đám trẻ địa phương bắt đầu nghi ngờ Gregory và quyết định hợp lực cùng nhau để vạch trần sự thật kinh hoàng này.</p>', 'Full', 1, 'single', 'completed', 27, 1995, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Clint Howard","avatar":""},{"name":"Justin Isfeld","avatar":""},{"name":"Anndi McAfee","avatar":""},{"name":"JoJo Adams","avatar":""},{"name":"Mikey LeBeau","avatar":""},{"name":"Sandahl Bergman","avatar":""},{"name":"Andrea Evans","avatar":""},{"name":"Steve Garvey","avatar":""},{"name":"Olivia Hussey","avatar":""},{"name":"David Warner","avatar":""},{"name":"Jan-Michael Vincent","avatar":""},{"name":"David Naughton","avatar":""},{"name":"Janet Wood","avatar":""},{"name":"Stephen Fiachi","avatar":""},{"name":"Stephanie Champlin","avatar":""},{"name":"Doug Llewelyn","avatar":""},{"name":"Tom Reilly","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Sorveteiro","I gusti del terrore","Мороженщик","El vendedor de helados","Ice Cream Man"]', 1784690324539);
