INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-luu-manh', 'Bác Sĩ Lưu Manh', 'Doctor Mack', 'https://phimimg.com/upload/vod/20260605-1/3b8b22f9fdd935ec3542cf2edd11346f.jpg', 'https://phimimg.com/upload/vod/20260605-1/11ad8e67aa3f534885270d019ca65428.jpg', '<p>Từ khi bỏ học trường y, Lau Mack sống một cuộc sống khiêm nhường nhưng viên mãn, điều hành một phòng khám nhỏ trong một khu ổ chuột, chữa trị cho người dân địa phương và những cô gái mại dâm nghèo khổ làm việc tại đó. Một đêm nọ, anh hộ tống một tên cướp súng bị thương đến bệnh viện công, nơi anh bất ngờ gặp lại người bạn cũ thời đại học, Tiến sĩ Jaw, giờ là một bác sĩ phẫu thuật nổi tiếng với tham vọng trở thành quản lý cấp cao. Trước sự ngạc nhiên cay đắng của Jaw, anh thấy mình bị lu mờ bởi tài năng y khoa và lòng tốt của Lau đối với bệnh nhân. Tuy nhiên, Jaw quyết tâm đẩy nhanh sự nghiệp của mình bằng cách gây tổn hại cho Lau. Âm mưu của anh diễn ra hoàn hảo, cho đến khi một tai nạn giao mạng anh vào tay Lau.</p>', 'Full', 1, 'single', 'completed', 32, 1995, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Lau Ching-Wan","avatar":""},{"name":"Andy Hui Chi-On","avatar":""},{"name":"Christy Chung Lai-Tai","avatar":""},{"name":"Alex To","avatar":""},{"name":"Hilary Tsui Ho-Ying","avatar":""},{"name":"Eileen Tung Oi-Ling","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Gigi Leung Wing-Kei","avatar":""},{"name":"Richard Ng Yiu-Hon","avatar":""},{"name":"Law Kar","avatar":""},{"name":"Jordan Chan Siu-Chun","avatar":""},{"name":"Lawrence Ng Kai-Wah","avatar":""},{"name":"Jessica Chau Ching","avatar":""},{"name":"W","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Doctor Mack","Dr. Mack","Mack the Knife","Lau man yi sang","Dr  Mack","流氓医生","流氓醫生"]', 1784690324539);
