INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liet-hoa-chien-xa', 'Liệt Hoả Chiến Xa', 'Full Throttle', 'https://phimimg.com/upload/vod/20260602-1/2555738e487ce876b2aeafc1438c6175.jpg', 'https://phimimg.com/upload/vod/20260602-1/f5ef757aa496b6187e36ff7ffcc80a0f.jpg', '<p>Joe là một tay đua mô tô vô địch, buộc phải đặt câu hỏi về toàn bộ lối sống của mình sau khi anh và một số người bạn thân bị thương nặng trong các vụ tai nạn xe máy. Sau đó, anh đấu tranh để duy trì bản sắc của một người dám chấp nhận rủi ro; và đấu tranh để duy trì và định hình lại mối quan hệ với vị hôn thê, bạn bè và người cha xa cách của mình.</p>', 'Full', 1, 'single', 'completed', 28, 1995, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Gigi Leung Wing-Kei","avatar":""},{"name":"David Wu","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Katherine Lau Ying-Hung","avatar":""},{"name":"Teresa Ha Ping","avatar":""},{"name":"Bruce Law Lai-Yin","avatar":""},{"name":"Lee Mei-Ling","avatar":""},{"name":"Lo Chi-Leung","avatar":""},{"name":"Jimmy Wong","avatar":""},{"name":"Jian Rui-Chao","avatar":""},{"name":"Joe Cheung Tung-Cho","avatar":""},{"name":"Cho Sai","avatar":""},{"name":"Leung Gam-San","avatar":""},{"name":"Hau W","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["烈火戰車","烈火戰車"]', 1784690324539);
