INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ly-tri-va-tinh-cam', 'Lý Trí Và Tình Cảm', 'Sense And Sensibility', 'https://phimimg.com/upload/vod/20260509-1/ecf04345bc8a53bb43e07358716fb75c.jpg', 'https://phimimg.com/upload/vod/20260509-1/276ae0cd720565b8635a8ecc4953adc4.jpg', '<p>Chị em nhà Dashwood – Elinor điềm đạm và Marianne nồng nhiệt – nhận ra cơ hội kết hôn của mình dường như đã khép lại sau khi gia đình đột ngột mất đi khối tài sản. Sau cái chết bất ngờ của ông Henry Dashwood, toàn bộ điền sản theo luật phải truyền lại cho con trai ông. Hoàn cảnh này khiến vợ và các con gái của ông Dashwood rơi vào cảnh không nhà cửa và chỉ còn đủ tiền để duy trì cuộc sống tối thiểu. Khi Elinor và Marianne nỗ lực tìm kiếm hạnh phúc trong một xã hội bị ám ảnh bởi tiền bạc và địa vị, họ phải học cách cân bằng giữa lý trí và tình cảm trong cách đối diện với cả tài chính lẫn những người đàn ông quanh mình.</p>', 'Full', 1, 'single', 'completed', 21, 1995, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emma Thompson","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Hugh Grant","avatar":""},{"name":"Gemma Jones","avatar":""},{"name":"Greg Wise","avatar":""},{"name":"Elizabeth Spriggs","avatar":""},{"name":"Imogen Stubbs","avatar":""},{"name":"Harriet Walter","avatar":""},{"name":"James Fleet","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Hugh Laurie","avatar":""},{"name":"Emilie François","avatar":""},{"name":"Robert Hardy","avatar":""},{"name":"Richard Lumsden","avatar":""},{"name":"Tom Wilkinson","avatar":""},{"name":"Ian Brimble","avatar":""},{"name":"Isabell","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b0306