INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thua-ke-1995', 'Người Thừa Kế (Trở Lại Trường Học)', 'Billy Madison', 'https://phimimg.com/upload/vod/20260116-1/df6ce29febf586b8e9f7aaa5b2c5912d.jpg', 'https://phimimg.com/upload/vod/20260116-1/d2639e700837f4549c5d12ce2a5c9ff2.jpg', '<p>Billy Madison là cậu con trai 27 tuổi của Bryan Madison, một người đàn ông rất giàu có người đi đầu trong ngành kinh doanh khách sạn. Billy được hưởng quyền thừa kế của cha nhưng với điều kiện anh phải học xong 12 lớp, và chỉ với 2 tuần một lớp, để chứng tỏ anh đủ khả năng dẫn dắt công việc của gia đình.</p>', 'Full', 1, 'single', 'completed', 15, 1995, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Bradley Whitford","avatar":""},{"name":"Josh Mostel","avatar":""},{"name":"Bridgette Wilson-Sampras","avatar":""},{"name":"Darren McGavin","avatar":""},{"name":"Norm Macdonald","avatar":""},{"name":"Mark Beltzman","avatar":""},{"name":"Larry Hankin","avatar":""},{"name":"Theresa Merritt","avatar":""},{"name":"Dina Platias","avatar":""},{"name":"Hrant Alianak","avatar":""},{"name":"Vincent Marino","avatar":""},{"name":"Christopher Kelk","avatar":""},{"name":"Marc Donato","avatar":""},{"name":"Keith Cole","avatar":""},{"name":"Chris Mei","avatar":""},{"name":"Conor D","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["超龄插班生","Billy Madison"]', 1784690324539);
