INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-cham-la-chet', 'Bắn Chậm Là Chết (Nhanh Thì Sống, Chậm Thì Chết)', 'The Quick and the Dead', 'https://phimimg.com/upload/vod/20260115-1/3d89a3d300f9f8d5cdefd1c1396b2648.jpg', 'https://phimimg.com/upload/vod/20260115-1/3ea8c468e151bbccb8a5187063291cc3.jpg', '<p>Phim The Quick and the Dead Sau nhiều năm lưu lạc, nữ xạ thủ quyến rũ Ellen trở về với mong muốn trả thù cho cha. Để tiếp cận được mục tiêu, cô phải tham gia vào một cuộc đấu súng tay đôi giữa các tay súng miền Tây hoang dã do Herod tổ chức. Herod là một kẻ máu lạnh hung ác, nắm quyền sinh sát toàn thị trấn, cũng chính là kẻ xưa kia đã hãm hại cha cô. Điều lệ của cuộc thi thật đơn giản: ai nhanh tay hơn sẽ là người chiến thắng, chậm tay thì chết. Tuy nhiên, đằng sau cuộc tranh tài này là cuộc chiến giữa cái thiện với cái ác ...</p>', 'Full', 1, 'single', 'completed', 36, 1995, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sharon Stone","avatar":""},{"name":"Gene Hackman","avatar":""},{"name":"Russell Crowe","avatar":""},{"name":"Leonardo DiCaprio","avatar":""},{"name":"Tobin Bell","avatar":""},{"name":"Roberts Blossom","avatar":""},{"name":"Kevin Conway","avatar":""},{"name":"Keith David","avatar":""},{"name":"Lance Henriksen","avatar":""},{"name":"Pat Hingle","avatar":""},{"name":"Gary Sinise","avatar":""},{"name":"Mark Boone Junior","avatar":""},{"name":"Olivia Burnette","avatar":""},{"name":"Fay Masterson","avatar":""},{"name":"Raynor Scheine","avatar":""},{"name":"Woody Strode","avatar":""},{"name":"Jerry Swindall","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5e