INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-vang-1995', 'Cậu Bé Vàng', 'Golden Boy', 'https://phimimg.com/upload/vod/20251105-1/77d060ed3f302b28ed5acc4017540501.jpg', 'https://phimimg.com/upload/vod/20251105-1/27ca5a4b7a092c9a1661fb27bd1e60b6.jpg', '<p>Kintarou Ooe là một chuyên gia làm việc bán thời gian, rong ruổi khắp các đường cao tốc và đường nhỏ của Nhật Bản trên con chiến mã đáng tin cậy của mình, Mikazuki 5, và tìm việc làm ở bất cứ đâu có thể. Những cuộc phiêu lưu của anh mang đến cho anh kiến thức và kinh nghiệm không thể dạy trong lớp học, từ tham nhũng chính trị đến sự nhạy cảm của trái tim thiếu nữ.</p>', 'Hoàn Tất (6/6)', 6, 'hoathinh', 'completed', 18, 1995, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mitsuo Iwata","avatar":""},{"name":"Gorō Naya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["黄金小子","黄金宝贝","GOLDEN BOY-ゴールデンボーイ- さすらいのお勉強野郎","ゴールデンボーイ","GOLDEN BOY Sasurai no Obenkyou Yarou","Golden Boy – Sasurai no O-Benkyō Yarō","골든 보이","골든보이","Голден Бой","Golden Boy: Bound for Glory","Golden Boy: Treasure Hunt","Golden Boy","GOLDEN BOY さすらいのお勉強野郎"]', 1784690324539);
