INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoang-doi-bao-tap', 'Khoảng Đời Bão Táp (Đoạn Tình Thời Phong Bạo)', 'Before Dawn', 'https://phimimg.com/upload/vod/20251012-1/be780a438017f144438ad5a66026962c.jpg', 'https://phimimg.com/upload/vod/20251012-1/271a955b544212ec2e48420eee1284af.jpg', '<p>Lâm Thanh Nhi mồ côi mẹ từ nhỏ, cô và cha mình sống nương tựa vào nhau. Không may, cha cô đắc tội với bọn xã hội đen và bị chúng bắt cóc. Vì để cứu cha, Thanh Nhi cầu cứu cảnh sát Hồng Khôn giúp đỡ. Nhưng ngờ đâu Hồng Khôn chính là đồng bọn của phía xã hội đen, vốn câu kết với nhau từ lâu, cha của Thanh Nhi cũng bị chúng hại chết, còn cô may mắn được bạn trai Trương Sở Văn giải cứu.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 1995, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Kitty Lai Mei-Han","avatar":""},{"name":"Frankie Lam","avatar":""},{"name":"Alex Fong Chung-Sun","avatar":""},{"name":"Marco Ngai Chun-Git","avatar":""},{"name":"Bao Fang","avatar":""},{"name":"Yeung Ling","avatar":""},{"name":"Danny Summer","avatar":""},{"name":"Shum Wai","avatar":""},{"name":"Ruco Chan Chin-Pang","avatar":""},{"name":"Helen Ma Hoi-Lun","avatar":""},{"name":"Lily Leung Shun-Yin","avatar":""},{"name":"Tam Sin-Hung","avatar":""},{"name":"Lau Kong","avatar":""},{"name":"Deon Cheung Chung-Chi","avatar":""},{"name":"Sunny Tai Yiu-Ming","avatar":""},{"name":"Gregory","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Before Dawn","愛在暴風的日子"]', 1784690324539);
