INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-san-khau-san-khau-phong-van', 'Điệp Vụ Sân Khấu (Sân Khấu Phong Vân)', 'A Stage of Turbulence', 'https://phimimg.com/upload/vod/20251010-1/01d2ec5b2ce4d7bdde2f4aff94cfe13f.jpg', 'https://phimimg.com/upload/vod/20251010-1/2e4f1fff0a8622d5adb7aa9d6e089f02.jpg', '<p>Bộ phim lấy bối cảnh đầu dân quốc, khi nhiều thế lực truy tìm kho báu bí ẩn của hoàng tộc Mãn Thanh. Đặc vụ Nam Phương chính phủ là Như trà trộn vào gánh hát để điều tra nhưng bị mất trí nhớ và được chưởng môn Thẩm Thiết Lan nhận nuôi, đổi tên thành Thẩm Cúc Tiên. Cô bị các sư tỷ Cúc San và Cúc Thu ganh ghét, đặc biệt khi cả hai đều có tình cảm với thiếu gia Hạo Quang. Khi gánh hát nữ dần khẳng định vị thế, Cúc Tiên bất ngờ nhớ lại quá khứ và phát hiện mình mang bí mật kho báu, trở thành mục tiêu truy sát của nhiều thế lực giang hồ</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 21, 1995, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Fiona Leung Ngai-Ling","avatar":""},{"name":"Vivian Chow","avatar":""},{"name":"He Meitian","avatar":""},{"name":"Sunny Chan Kam-Hung","avatar":""},{"name":"Law Lok-Lam","avatar":""},{"name":"Lee Kuei-Ying","avatar":""},{"name":"Maple Hui Chau-Yi","avatar":""},{"name":"Joyce Koi","avatar":""},{"name":"Roman Tam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["刀馬旦"]', 1784690324539);
