INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-song-phang', 'Trò Chơi Sòng Phẳng', 'Fair Game', 'https://phimimg.com/upload/vod/20251009-1/831751cc6fff6c59482db62b245ac721.jpg', 'https://phimimg.com/upload/vod/20251009-1/1e4f1718bce52f7fd7735848905734ab.jpg', '<p>Anh là một cảnh sát đang trên bờ vực. Cô là một người phụ nữ mang trong mình một bí mật nguy hiểm. Họ đã bị mafia Nga nhắm đến, và giờ cả hai đều là mục tiêu. - Max Kirkpatrick là một cảnh sát bảo vệ Kate McQuean, một luật sư dân sự, khỏi một nhóm KGB phản bội đang tìm cách thủ tiêu cô.</p>', 'Full', 1, 'single', 'completed', 18, 1995, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"William Baldwin","avatar":""},{"name":"Cindy Crawford","avatar":""},{"name":"Steven Berkoff","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Miguel Sandoval","avatar":""},{"name":"Johann Carlo","avatar":""},{"name":"Salma Hayek Pinault","avatar":""},{"name":"John Bedford Lloyd","avatar":""},{"name":"Jenette Goldstein","avatar":""},{"name":"Paul Dillon","avatar":""},{"name":"Olek Krupa","avatar":""},{"name":"Gustav Vintas","avatar":""},{"name":"Marc Macaulay","avatar":""},{"name":"Ruben Rabasa","avatar":""},{"name":"Sonny Carl Davis","avatar":""},{"name":"Antoni","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Facile preda","Caza legal","Cible de choix","Atraccion Explosiva","对抗性游戏","Fair Game","挑逗性游戏","Atração Explosiva"]', 1784690324539);
