INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-nu-canh-sat-thien-xa', 'Ba Nữ Cảnh Sát Thiện Xạ', 'Corruption Doesn''t Pay', 'https://phimimg.com/upload/vod/20251008-1/25839f15f538498c46ee742c37d046e5.jpg', 'https://phimimg.com/upload/vod/20251008-1/0ce562c535058ce55635e91b205eea09.jpg', '<p>Ba đội viên Phan Úy Hân, Cam Bảo Ni và Trì Trung Liên và chủ nhiệm điều tra cao cấp ICAC -Trác Minh thường đồng sinh cộng tử thi hành nhiệm vụ. Hân, Ni, Liên không chỉ là cộng sự ăn ý mà còn là chị em tốt. Ngoài đối mặt với những thách thức trong công việc, họ cũng gặp khó khăn khi giải quyết việc gia đình. Liên do không thể cùng lúc gánh vác việc nhà và việc điều tra, cuối cùng phải xin nghỉ. Trác Minh và Hân điều tra một vụ hối lộ công ty tài chính, đối đầu với Tài. Tài lập kế hoạch sát hại nhân chứng Trang Văn Hiên. Trong lúc ngàn cân treo sợi tóc, Hân và Ni kịp thời tháo được ngòi nổ quả bom. Lúc này, Liên vì lo lắng cho sự an nguy của hai bạn thân nên đã đến cùng nhau đối chọi với Tài...<br/></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 15, 1995, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Sheren Tang Shui-Man","avatar":""},{"name":"Esther Kwan Wing-Ho","avatar":""},{"name":"Kiki Sheung","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Alex Fong Chung-Sun","avatar":""},{"name":"Lau Kong","avatar":""},{"name":"Savio Tsang","avatar":""},{"name":"Cheung Ying-Tsoi","avatar":""},{"name":"Lai Suen","avatar":""},{"name":"Lee Shing-Cheong","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"Bessie Chan Ming-Kwan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Corruption Doesn''t Pay","廉政英雌之火槍柔情