INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-lam-tieu-tu-3-tan-o-long-vien-3', 'Thiếu Lâm Tiểu Tử 3 (Tân Ô Long Viện 3)', 'Shaolin Popey 3: Super Mischieves', 'https://phimimg.com/upload/vod/20250925-1/e44b81666952d52834f28a0276286fa0.jpg', 'https://phimimg.com/upload/vod/20250925-1/ebbd8e896272e4dd3ec0936c54358eb0.jpg', '<p>Sau trận chiến bảo vệ “Dịch Cân Kinh”, thầy trò Tiểu Văn sống những ngày yên bình trong chùa. Tuy nhiên, khi A Chân – cô gái được mời về chăm sóc Tiểu Văn – lại đánh cắp bí kíp võ công, Tiểu Văn cùng Tiểu Long và sư huynh phải xuống núi truy tìm. Trên đường, họ kết bạn với A Kim, vượt qua nhiều hiểm nguy và tiến vào Thiên Ma Cổ Bảo, nơi cuộc chiến giành lại “Dịch Cân Kinh” một lần nữa bùng nổ.</p>', 'Full', 1, 'single', 'completed', 20, 1995, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Ashton Chen","avatar":""},{"name":"Steven Hao","avatar":""},{"name":"Richard Ng Man-Tat","avatar":""},{"name":"Lau Shun","avatar":""},{"name":"Eric Kot Man-Fai","avatar":""},{"name":"Elsie Yeh","avatar":""},{"name":"Vivian Hsu","avatar":""},{"name":"Michael Lee Ming-Yeung","avatar":""},{"name":"Pal Sinn Lap-Man","avatar":""},{"name":"Wong Yat-Fei","avatar":""},{"name":"Chen Wei-Min","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["無敵反斗星","无敌反斗星","Super Mischievous","Wu di fan dou xing","Shaolin Popey III","笑林小子3：无敌反斗星"]', 1784690324540);
