INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-da-do', 'Công Chúa Da Đỏ', 'Pocahontas', 'https://phimimg.com/upload/vod/20250920-1/a3736b8caebae75b0eddc731baf7d6f0.jpg', 'https://phimimg.com/upload/vod/20250920-1/7b77e5ecd0f2ca90ef9c75cbfc697cb2.jpg', '<p>Năm 1607, làn sóng khai thác thuộc địa mới ở Châu Âu diễn ra ồ ạt. Con tàu của thuyền trưởng John Smith và vị thống đốc tham lam Ratcliffe tìm đến xứ Bắc Mỹ, ngày đó vẫn còn là một vùng đất nằm trong bí ẩn.
 Ngay khi đặt chân tới vùng đất lạ, nhóm của John và bộ lạc da đỏ của thủ lĩnh Powhatan. John đem lòng yêu con gái của Powhatan là Pocahontas, nhưng những bất đồng trong lối sống và tham vọng của bản quốc đã khiến mối tình của họ bị chia cắt bởi chiến tranh với người da đỏ...</p>', 'Full', 1, 'hoathinh', 'completed', 19, 1995, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Irene Bedard","avatar":""},{"name":"Mel Gibson","avatar":""},{"name":"David Ogden Stiers","avatar":""},{"name":"John Kassir","avatar":""},{"name":"Christian Bale","avatar":""},{"name":"Judy Kuhn","avatar":""},{"name":"Billy Connolly","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Russell Means","avatar":""},{"name":"Linda Hunt","avatar":""},{"name":"Danny Mann","avatar":""},{"name":"Joe Baker","avatar":""},{"name":"Michelle St. John","avatar":""},{"name":"James Apaumut Fall","avatar":""},{"name":"Gordon Tootoosis","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Charlie Adler","avatar":""},{"name":"Deb","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Walt Disney''s Pocahontas","Disneys 33 Pocahontas","ポカホンタス","Pocahontas - Eine indianische Legende","포카혼타스","Pocahontas","Покахонтас","Pocahontas 1","Pocahontas I","포카 혼타스 1","Pocahontas - Une legende indienne","Pocahontas: O Encontro de Dois Mundos","Ποκαχόντας"]', 1784690324540);
