INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-su-ma-quy', 'Thiên Sứ Ma Qủy', 'Devil Angel', 'https://phimimg.com/upload/vod/20250805-1/d024e263411a6551b2f7fda3ce629b8b.jpg', 'https://phimimg.com/upload/vod/20250805-1/a282d30d2a99de4a4293f19195869a9e.jpg', '<p>Tiểu Huyên (Từ Nhược Huyên) một hôm ở nhà nhận được cuộc gọi từ bạn trai Tử Kiệt (Giang Quốc Bân). Tử Kiệt nói rằng việc anh biển thủ công quỹ ở công ty đã bị bại lộ, nên cả hai quyết định bỏ trốn cùng số tiền ít ỏi còn lại. Trên đường, họ đến vách đá và thề sẽ sống chết có nhau. Một ngày nọ, khi Tử Kiệt đang mượn xăng từ một người lạ, anh bị bà Du – góa phụ của tập đoàn Du Thị (Dương Tư Mẫn) – để mắt và ra giá 2 triệu tệ cho một lần “bồi tiếp”. Tử Kiệt tức giận từ chối. Không ngờ, Tiểu Huyên trong lúc gọi điện cho mẹ đã làm mất túi du lịch, khiến cả hai trắng tay. Bất đắc dĩ, Tử Kiệt phải nhận lời mời của bà Du. Sau một đêm ở bên bà, anh quay về khách sạn và cãi nhau kịch liệt với Tiểu Huyên, nhưng rồi cả hai lại làm hòa. Đúng lúc họ rời khách sạn, CID xuất hiện bắt giam Tử Kiệt. Trong cơn tuyệt vọng, Tiểu Huyên chỉ còn cách tìm đến bà Du để cầu cứu…</p>', 'Full', 1, 'single', 'completed', 15, 1995, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Vivian Hsu","avatar":""},{"name":"Asami Kanno","avatar":""},{"name":"Goo Chang","avatar":""},{"name":"Franco Chiang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mo gui tian shi","Evil Angel","魔鬼天使","마귀천사","Devil Angel"]', 1784690324540);
