INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-thi-tham-cua-trai-tim', 'Lời Thì Thầm Của Trái Tim', 'Whisper Of The Heart', 'lời thì thầm của trái tim whisper of the heart yoko honna issey takahashi takashi tachibana shigeru muroi minami takayama mayumi izuka yorie yamashita keiju kobayashi naohisa inoue shigeru tsuyuguchi toshio suzuki maiko kayama yoshimi nakajima mai chiba satoru takahashi akiko sakaguchi mimi o sumaseba 梦幻街少女 susurros del corazón whisper of the heart mimi wo sumaseba 귀를 기울이면 якщо прислухатись 耳をすませば วันนั้น...วันไหน หัวใจจะเป็นสีชมพู sussurros do coração se ouvires atentamente if you listen closely si tu tends l''oreille 夢幻街少女 心之谷 шепот сердца نجوای درون', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('7-toi-loi-chet-nguoi', '7 Tội Lỗi Chết Người', 'Se7en', 'https://phimimg.com/upload/vod/20250619-1/73976d30abee27f841bb961cf5a23797.jpg', 'https://phimimg.com/upload/vod/20250619-1/80129055e29c6936e4d982bf4c9df764.jpg', '<p>Hai viên cảnh sát William Somerset và David Mills phối hợp điều tra một vụ án phức tạp liên quan đến 7 điều cấm trong Kinh thánh. Hung thủ được dự đoán là do trước kia hắn lớn lên trong môi trường đạo nghiêm khắc nên tâm lí bất ổn và rồi lần lượt giết người dựa trên 7 tội lỗi trong Kinh thánh mà hắn gán cho mỗi người. &nbsp;7 tội lỗi đó là: kiêu hãnh (Pride), ghen tị (Envy), ham ăn (Gluttony), sắc dục (Lust), tức giận (Wrath), tham lam (Greed) và lười biếng (Sloth). Án mạng đầu tiên là một tên béo phì với dòng chữ Gluttony viết bằng máu trên tường. Greed là án mạng xảy ra sau đó ở nơi làm của 1 tên luật sư. Một tên buôn ma túy tên Victor bị giết với tội lười biếng - Sloth. Lust là tội gán cho một cô gái điếm. Cuối cùng, Pride là 1 cô nàng quá mải mê chăm chút bề ngoài của mình.</p>', 'Full', 1, 'single', 'completed', 15, 1995, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Morgan Freeman","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Gwyneth Paltrow","avatar":""},{"name":"John Cassini","avatar":""},{"name":"Peter Crombie","avatar":""},{"name":"Reg E. Cathey","avatar":""},{"name":"R. Lee Ermey","avatar":""},{"name":"Daniel Zacapa","avatar":""},{"name":"Andrew Kevin Walker","avatar":""},{"name":"George Christy","avatar":""},{"name":"Endre Hules","avatar":""},{"name":"Hawthorne James","avatar":""},{"name":"Bob Mack","avatar":""},{"name":"William Davidson","avatar":""},{"name":"Bob Collins","avatar":""},{"name":"Jimmy Dale Hartsell","avatar":""},{"name":"Richard R","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Seven Deadly Sins","Seven","Sete Pecados Mortais","سبعة","Se7en"]', 1784690324540);
