INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-oan-hiep-si', 'Ân Oán Hiệp Sĩ (Thần Long Kiếm Hiệp)', 'The Holy Dragon Saga', 'https://phimimg.com/upload/vod/20250514-1/34e9f7f548ee49f8dc17196b6388980f.jpg', 'https://phimimg.com/upload/vod/20250514-1/687622c4dcc8eb29ee2d0aed8489c370.jpg', '<p>Ân Oán Hiệp Sĩ kể lại chuyện quan hệ đối lập giữa thiếu trang chủ Liên Tiễn và kiếm khách Cô Trúc Vô Danh. Họ có thù không đội trời chung nhưng lại hay tương trợ với nhau. Trong phim này, ân oán giữa hai người chỉ có cách giải quyết bằng tình nghĩa. Mặt khác, bên cạnh Kiều Tam và Cô Trúc Vô Danh lại có các cô Nguyệt Ảnh Khưu Sa và Liệt Phong sinh ra những mối tình vương vấn, nan giải. Liệu phim sẽ diễn biến thế nào mời các bạn cùng theo dõi bộ phim Ân Oán Hiệp Sĩ.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 36, 1995, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Catherine Hung Yan","avatar":""},{"name":"Cheung Yuen-Mei","avatar":""},{"name":"Frankie Lam","avatar":""},{"name":"Cho Chun","avatar":""},{"name":"William Chu Wai-Lim","avatar":""},{"name":"Marco Ngai Chun-Git","avatar":""},{"name":"Choi Kwok-Hing","avatar":""},{"name":"Lily Li","avatar":""},{"name":"Chang Yi","avatar":""},{"name":"Steve Lee Ka-Ting","avatar":""},{"name":"Liu Chun-Hung","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["The Holy Dragon Saga","箭俠恩仇"]', 1784690324540);
