INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phai-co-ca-hai', 'Phải Có Cả Hai', 'It Takes Two', 'https://phimimg.com/upload/vod/20250502-1/227af8583b36a63efdd360ebf669994f.jpg', 'https://phimimg.com/upload/vod/20250502-1/a6b4fd9440748b0ef292522691646d81.jpg', '<p>Sau khi gặp nhau tại trại hè, cô bé mồ côi Amanda và tiểu thư Alyssa lợi dụng ngoại hình giống hệt nhau của họ để se duyên cho bố của Alyssa với một nhân viên xã hội tận tâm.</p>', 'Full', 1, 'single', 'completed', 15, 1995, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kirstie Alley","avatar":""},{"name":"Steve Guttenberg","avatar":""},{"name":"Ashley Olsen","avatar":""},{"name":"Mary-Kate Olsen","avatar":""},{"name":"Jane Sibbett","avatar":""},{"name":"Philip Bosco","avatar":""},{"name":"Michelle Grisom","avatar":""},{"name":"Desmond Robertson","avatar":""},{"name":"Tiny Mills","avatar":""},{"name":"Shanelle Henry","avatar":""},{"name":"Michèle Lonsdale Smith","avatar":""},{"name":"Sean Orr","avatar":""},{"name":"Elizabeth Walsh","avatar":""},{"name":"Dov Tiefenbach","avatar":""},{"name":"Douglas O''Keeffe","avatar":""},{"name":"Anthony A","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Me and My Shadow","Matrimonio a Quattro Mani","Berdemata gia dyo","Mperdemata gia dyo","Malé dohadzovačky","ひとりっこのじじょう","It Takes Two"]', 1784690324540);
