INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truoc-ngay-den-toi', 'Trước Ngày Đền Tội', 'Dead Man Walking', 'https://phimimg.com/upload/vod/20250415-1/8080649966af285f3b939d4ac37183f2.jpg', 'https://phimimg.com/upload/vod/20250415-1/c2f61d912094f1cf54a0d768ff6d803f.jpg', '<p>Ở xứ đạo St. Thomas, ai cũng biết sơ Helen Prejean, người dẫn đầu phong trào phản đối án tử hình. Một hôm, sơ nhận được một lá thư của Matthew Poncelet - kẻ sắp phải lên giá treo cổ vì tội giết người. Hắn đang bị giam tại một nhà tù bang New Orleans. Trong thư, tử tội cầu xin Helen làm cố vấn tinh thần và tác động tới chính quyền để hắn được giảm án. Matthew bị bắt và khép vào tội sát nhân sau khi cảnh sát tìm thấy một đôi trai gái bị giết chết một cách dã man trong một bìa rừng 6 năm về trước. Cùng bị bắt với Matthew còn có một tên nữa. Khi đứng trước tòa, chúng đổ tội cho nhau. Matthew đuối lý hơn nên lĩnh án tử hình, còn tên kia thoát chết. Tử tội kháng án lên tòa án liên bang nhưng họ quyết định y án. Khi ngày lên giá treo cổ tới gần, hắn quyết định cầu cứu sơ Helen. Hắn một mực khẳng định mình bị oan...</p>', 'Full', 1, 'single', 'completed', 14, 1995, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Susan Sarandon","avatar":""},{"name":"Sean Penn","avatar":""},{"name":"Robert Prosky","avatar":""},{"name":"Raymond J. Barry","avatar":""},{"name":"R. Lee Ermey","avatar":""},{"name":"Celia Weston","avatar":""},{"name":"Lois Smith","avatar":""},{"name":"Scott Wilson","avatar":""},{"name":"Roberta Maxwell","avatar":""},{"name":"Margo Martindale","avatar":""},{"name":"Barton Heyman","avatar":""},{"name":"Steve Boles","avatar":""},{"name":"Nesbitt Blaisdell","avatar":""},{"name":"Ray Aranha","avatar":""},{"name":"Larry Pine","avatar":""},{"name":"Gil Robbins","avatar":""},{"name":"Kevin Cooney","avatar":""},{"name":"Clancy B","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Mientras estés conmigo","Осъденият на смърт идва","Kuolemaantuomittu","Tha ziso","Przed egzekucja","A Última Caminhada","Zadnji sprehod","Surmamõistetu","Gever Met Mahaleh","Dead Man Walking - Sein letzter Gang","데드 맨 워킹","死囚漫步","Dead Man Walking"]', 1784690324540);
