INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-dep-gia-tao', 'Sắc Đẹp Giả Tạo', 'A Fake Pretty Woman', 'https://phimimg.com/upload/vod/20250104-1/8567633dccb96f8484d77fb7a018e0e1.jpg', 'https://phimimg.com/upload/vod/20250104-1/2c7cfac8bc86dde07b5ffce270eea0e4.jpg', '<p>Một cô hầu bàn không an toàn (Yvonne Yung Hung) nghĩ rằng mọi vấn đề của cô sẽ được giải quyết nếu cô phẫu thuật thẩm mỹ để trở nên xinh đẹp. Ban đầu, cô trở thành người mẫu và bắt đầu hẹn hò với một tỷ phú ngay sau khi phẫu thuật.</p>', 'Full', 1, 'single', 'completed', 19, 1995, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Yvonne Yung Hung","avatar":""},{"name":"Carol Tam","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"David Lam Wai","avatar":""},{"name":"Debbie Cheung Jing","avatar":""},{"name":"Lawrence Ng Kai-Wah","avatar":""},{"name":"Terrence Fok","avatar":""},{"name":"Kingdom Yuen King-Tan","avatar":""},{"name":"Ricky Ho","avatar":""},{"name":"Eddie Chan Shu-Chi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zheng rong","整容"]', 1784690324540);
