INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-hon-dang', 'Mê Hồn Đảng', 'Spike Drink Gang', 'https://phimimg.com/upload/vod/20250104-1/4cf01838a03d90e0e0c0cf57e0a28155.jpg', 'https://phimimg.com/upload/vod/20250104-1/92cc26ef45d780399470827b053203cb.jpg', '<p>Lau Lee Hung, thủ lĩnh của &quot;Băng đảng ma túy&quot; là cai ngục tại nhà tù nam, nhưng đã bị người giám sát sa thải vì một số hành vi sai trái, cướp thành công số tiền tiết kiệm 800.000 USD của Rainbow. Sau đó, một sinh viên vô tội bị đánh thuốc mê, cưỡng hiếp rồi giam giữ. để đòi tiền chuộc. Viên cảnh sát nghiêm túc về tội ác mà băng nhóm ma túy đang phạm phải và gửi đi điều tra. Rainbow và chồng cô sẽ giúp cảnh sát bắt Lau......</p>', 'Full', 1, 'single', 'completed', 13, 1995, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Yvonne Yung Hung","avatar":""},{"name":"Lo Meng","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Power Chan Kwok-Pong","avatar":""},{"name":"Lee Siu-Kay","avatar":""},{"name":"Raven Choi Yip-San","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["迷魂黨"]', 1784690324540);
