INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-nu-nui-linh-son', 'Tiên Nữ Núi Linh Sơn', 'Ling Shan Xia Lu', 'https://phimimg.com/upload/vod/20241028-1/e5a77b765c7cd5a9b5cd68920195b24e.jpg', 'https://phimimg.com/upload/vod/20241028-1/7a1ca1a81761a890ad4bb1c0d77bd6bd.jpg', '<p>Xoay quanh chuyện một nàng tiên nữ ở trên núi Linh Sơn, vì nhiệm vụ bảo vệ Linh Chi Thảo Nhân mà đã vô tình giết chết Pháp hậu khiến Pháp sư của nước Thiên Long nổi giận, niệm thần chú khi ban ngày cô biến thành người nhưng cứ những đêm trăng tròn cô phải hóa thành sói, có một tình yêu thật đẹp nhưng cũng lắm gian nan bên thư sinh Trương Tường...</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 21, 1995, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"iêu Tường","avatar":""},{"name":"Lưu Tích Minh","avatar":""},{"name":"Tống Dật Dân","avatar":""},{"name":"Quý Cần","avatar":""},{"name":"Lưu Tuyết Hoa","avatar":""},{"name":"Phàn Nhật Hành","avatar":""},{"name":"Lý Cần","avatar":""},{"name":"Lâm Tiểu Lâu","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324540);
