INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-ban-phan-2', 'Những Người Bạn (Phần 2)', 'Friends (Season 2)', 'https://phimimg.com/upload/vod/20240910-1/b351e84cf06e68c67048b028953ca082.jpg', 'https://phimimg.com/upload/vod/20240910-1/6725b5e75b0821aff8db68b57d2b37b2.jpg', '<p>Loạt phim dõi theo những sự cố vui nhộn của 6 người bạn tuổi đôi mươi đang vật lộn với những thử thách trong công việc, cuộc sống, tình yêu tại Manhattan những năm 1990.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 15, 1995, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jennifer Aniston","avatar":""},{"name":"Courteney Cox","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Matt LeBlanc","avatar":""},{"name":"Matthew Perry","avatar":""},{"name":"David Schwimmer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324540);
