INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-dao', 'Tuyệt Đao', 'The Blade', 'https://phimimg.com/upload/vod/20231130-1/4a84a3f9b7b85ead7658aaa2d1de4994.jpg', 'https://phimimg.com/upload/vod/20231130-1/0c03cd0a631682843dd8f5e2f2825dec.jpg', '<p>Phim Tuyệt Đao (The Blade): bộ phim nói về môt chàng trai rơi vào tình cảnh không nhà không của,cha mẹ bị giết chết sau một vụ cướp,và anh ta cũng bị mất một tay. Quyết tâm trả thù nhưng chỉ với một cánh tay anh ta không thể học được các loại đao pháp. Nhưng cuối cùng anh ta đã học được tuyệt học dùng đao với một thanh đoản đao sắc bén. Với võ công có một không hai, anh đã giết những tên cướp hung bạo trừ hại cho dân và trả thù cho cha mẹ.</p>', 'Full', 1, 'single', 'completed', 13, 1995, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Vincent Zhao Wenzhuo","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Sonny Song","avatar":""},{"name":"Austin Wai Tin-Chi","avatar":""},{"name":"Moses Chan","avatar":""},{"name":"Chung Bik-Ha","avatar":""},{"name":"Jason Chu Wing-Tong","avatar":""},{"name":"Valerie Chow","avatar":""},{"name":"Michael Tse","avatar":""},{"name":"Chin Tsi-Ang","avatar":""},{"name":"Chan Chi-Fai","avatar":""},{"name":"Dickens Chan Wing-Chung","avatar":""},{"name":"Suet Nei","avatar":""},{"name":"Sze-Ma Wah-Lung","avatar":""},{"name":"Paco Yick Tin-Hung","avatar":""},{"name":"Raymond Wong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324540);
