INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-su-khoa-than', 'Thiên Sứ Khỏa Thân', 'Angel Heart', 'https://phimimg.com/upload/vod/20230922-1/b0a18111844bd8167e49a45ad548de9b.jpg', 'https://phimimg.com/upload/vod/20230922-1/2bb3219cd84685c3f54e87ea213c450e.jpg', '<p>Trải qua khoảng thời gian đau khổ trong tù, Miao Wei tìm kiếm cả những người tình cũ bình thường và cả người yêu thời thơ ấu Wennie. Không lâu nữa họ sẽ kết hôn và cùng nhau đi trên con đường hoàn hảo nhưng Miao Wei đã mang theo những vết sẹo từ thời gian ở tù cho đến những khoảnh khắc thân mật với Wennie. Cho rằng anh yêu cô quá nhiều, mối quan hệ bắt đầu tan vỡ theo những cách nguy hiểm...</p>', 'Full', 1, 'single', 'completed', 14, 1995, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Vivian Hsu","avatar":""},{"name":"Franco Jiang","avatar":""},{"name":"Stanley Chu","avatar":""},{"name":"Gu Bao-Ming","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324540);
