INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-co-gai-toc-bac', 'Chuyện Tình Cô Gái Tóc Bạc', 'The Romance Of The White Hair Maiden', 'https://phimimg.com/upload/vod/20240724-1/11aaf2543635c2774cd8519d39bf3dd7.jpg', 'https://phimimg.com/upload/vod/20240724-1/db7513a11794af6a732b4bc487d58db8.jpg', '<p><em>Chuyện Tình Cô Gái Tóc Bạc là một tác phẩm kiếm hiệp vào loại nổi tiếng nhất của Lương Vũ Sinh, bằng chứng là nó đã được chuyển thể thành phim điện ảnh và truyền hình rất nhiều lần ... Trác Nhất Hàng là đại đệ tử của phái Võ Đang với tài nghệ vào loại hàng đầu trong Bát đại môn phái. Anh là niềm hy vọng của cả phái Võ Đang và giang hồ trong cảnh loạn lạc cuối đời nhà Minh. Tuy nhiên Nhất Hàng lại chẳng màng chức vị hay danh tiếng, anh chỉ thích đối tửu cùng người bạn lâu năm Ngô Tam Quế và tơ tưởng tới người trong mộng của anh - Ngọc La Sát xinh đẹp, đệ nhất sát thủ của Thần Cung giáo - kẻ địch của Bát đại môn phái. Và rồi Nhất Hàng cùng Ngọc La Sát cũng đến được với nhau, Nhất Hàng đặt tên cho người yêu của mình là Luyện Nghê Thường, còn nàng Nghê Thường bắt người yêu phải thề rằng anh sẽ luôn tin tưởng vào cô bất kể chuyện gì xảy ra. Và tất nhiên với một mối tình ngang trái kiểu Romeo và Juliette thì sẽ có rất nhiều thứ ập đến với Nhất Hàng và Nghê Thường, đó là sự ngăn cản từ phía phái Võ Đang với Nhất Hàng, từ phía Cơ Vô Song giáo chủ Thần Cung giáo, đó là sự kiện nhà Thanh xâm chiếm Trung Quốc nhờ sự tiếp tay của Ngô Tam Quế. Kết quả thì như tất cả những ai yêu kiếm hiệp đều đã biết, nàng Nghê Thường biến thành Bạch phát ma nữ với mái tóc trắng xóa, còn Nhất Hàng suốt phần đời còn lại đứng canh trên đỉnh núi tuyết trắng để tìm thứ thảo dược giúp hồi sinh mái tóc của nàng Nghê Thường. Nhưng cái người xem quan tâm là bi kịch nào đã đẩy Nghê Thường và Nhất Hàng tới số phận đau khổ như vậy.</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 27, 1995, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Thái Thiếu Phân","avatar":""},{"name":"Hà Bửu Sinh","avatar":""},{"name":"Lý Quế Anh","avatar":""},{"name":"La Mãnh","avatar":""},{"name":"Trần Gia Huy","avatar":""},{"name":"Lý Thành Xương","avatar":""},{"name":"Trần Bội San","avatar":""},{"name":"Mã Đức Chung","avatar":""},{"name":"Vũ Phong","avatar":""},{"name":"Vương Vỹ","avatar":""},{"name":"Lê Hán Trì","avatar":""},{"name":"Tần Hoàng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324540);
