INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-trek-voyager-phan-1', 'Star Trek: Voyager (Phần 1)', 'Star Trek: Voyager (Season 1)', 'https://phimimg.com/upload/vod/20240302-1/e527a39c53d6c3436887ffc8af346d2c.jpg', 'https://phimimg.com/upload/vod/20240302-1/3cd5b76335715b780d41ca27333c4e0c.jpg', '<p>Trên hành trình 75 năm của Voyager để trở lại Trái Đất, các thành viên phi hành đoàn bắt gặp những chủng loài lạ, khi họ đến gần một góc phần tư bí ẩn của không gian.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 15, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kate Mulgrew","avatar":""},{"name":"Robert Beltran","avatar":""},{"name":"Roxann Dawson","avatar":""},{"name":"Jennifer Lien","avatar":""},{"name":"Robert Duncan McNeill","avatar":""},{"name":"Ethan Phillips","avatar":""},{"name":"Robert Picardo","avatar":""},{"name":"Tim Russ","avatar":""},{"name":"Jeri Ryan","avatar":""},{"name":"Vương Dĩ Chiêm","avatar":""},{"name":"Tarik Ergin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324540);
