INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-thien-than', 'Cô Bé Thiên Thần', 'Saint Tail', 'https://phimimg.com/upload/vod/20240302-1/8cf08daf7e25989ec6800e78e867c6a5.jpg', 'https://phimimg.com/upload/vod/20240302-1/61dd25e8e9c8b27f1c4924de65a0482d.jpg', '<p>Meimi là một nữ sinh bình thường nhưng khi đêm xuống thì cô trở thành một siêu trộm biệt danh là Saint Tail. Cố gắng bắt Meimi là Asuka Jr một thám tử nghiệp dư học cùng lớp với cô. Rồi trời xui đất khiến sao cho một người thì mỗi khi ăn trộm lại la làng cho thám tử biết còn 1 người thì lúc đầu muốn bắt trộm sau lại muốn chiếm luôn tên trộm đó thế là Happy Ending</p>', 'Hoàn Tất (43/43)', 43, 'hoathinh', 'completed', 24, 1995, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324540);
