INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-van-chuyen-data', 'Người Vận Chuyển Data', 'Johnny Mnemonic', 'https://phimimg.com/upload/vod/20240228-1/abbeeba9477dd28f9dac14e45a2abd6a.jpg', 'https://phimimg.com/upload/vod/20240228-1/0a71108c619d8c9fb42fe5d42d71ec5f.jpg', '<p>Trong thế giới đen tối 2021, Johnny là một kẻ buôn bán dữ liệu có thiết bị cấy ghép cho phép anh ta lưu trữ an toàn những dữ liệu quá nhạy cảm đối với mạng máy tính thông thường. Trong một lần giao hàng, anh ta chấp nhận một gói hàng không chỉ vượt quá giới hạn an toàn của bộ cấy ghép—và sẽ giết anh ta nếu dữ liệu không được xóa kịp thời—mà còn chứa thông tin quan trọng và có giá trị hơn nhiều so với những gì anh ta từng tưởng tượng. Trong cuộc chạy đua với thời gian, anh phải tránh những sát thủ được cử đến để giết anh và xóa dữ liệu trước khi nó kết thúc cuộc đời anh.</p>', 'Full', 1, 'single', 'completed', 14, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Dina Meyer","avatar":""},{"name":"Ice-T","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Denis Akiyama","avatar":""},{"name":"Henry Rollins","avatar":""},{"name":"Barbara Sukowa","avatar":""},{"name":"Udo Kier","avatar":""},{"name":"Tracy Tweed","avatar":""},{"name":"Falconer Abraham","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324540);
