INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sahara', 'Sahara', 'Sahara', 'https://phimimg.com/upload/vod/20240219-1/f75451fb9e90d7ff03aab676f434f6d9.jpg', 'https://phimimg.com/upload/vod/20240219-1/c059c3847b6617d9454fc4d8e8675bc8.jpg', '<p>Sau khi Tobruk thất thủ vào tháng 6 năm 1942, trung sĩ quân đội Hoa Kỳ Joe Gunn dẫn xe tăng của mình vào sa mạc Sahara, để trốn tránh lực lượng của Rommel đang tiến lên và tiếp cận phòng tuyến của quân Đồng minh. Trên đường đi, anh ta nhặt được một số binh lính Đồng minh, nhưng chẳng bao lâu sau họ sẽ cạn kiệt nước. Họ tìm thấy nước ở chiếc giếng cổ, nhưng chiếc giếng lại là mục tiêu của cả một tiểu đoàn Đức. Bất chấp những khó khăn bất khả thi, Trung sĩ Gunn quyết định bảo vệ cái giếng.</p>', 'Full', 1, 'single', 'completed', 14, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Belushi","avatar":""},{"name":"Jerome Ehlers","avatar":""},{"name":"Mark Lee","avatar":""},{"name":"Michael Massee","avatar":""},{"name":"Robert Wisdom","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324540);
