INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('crying-freeman', 'Crying Freeman', 'Crying Freeman', 'https://phimimg.com/upload/vod/20240207-1/c4c89689c8d82d727a0149a3026df394.jpg', 'https://phimimg.com/upload/vod/20240207-1/e64bb67a358a9ad2651caf6644966134.jpg', '<p>Nước Mắt Sát Thủ xoay quanh một sát thủ nổi tiếng với khả năng giết người chớp nhoáng, anh ta đã làm việc cho một tổ chức bí mật của Trung Quốc, được biết tới với đặc điểm khá đặc biệt khi mà mỗi sau khi giết người đều rơi lệ vì hối tiếc, mặc dù trong lúc thực hiện đều cho thấy sự dứt khoát và không thương tiếc đối với con mồi. Lần này, anh chàng ra tay sát hại dã man một cách chớp nhoáng 3 người trong băng đảng xã hội đen nổi tiếng của Nhật là Yakuza của và vô tình một nghệ sĩ xinh đẹp đã nhìn thấy anh ta.</p>', 'Full', 1, 'single', 'completed', 12, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Dacascos","avatar":""},{"name":"Byron Mann","avatar":""},{"name":"Masaya Kato","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"Julie Condra","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324540);
