INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('showgirls', 'Showgirls', 'Showgirls', 'https://phimimg.com/upload/vod/20240207-1/ac9b03509c70b507622152cf597e4349.jpg', 'https://phimimg.com/upload/vod/20240207-1/d2f2bb48a17c7f7eba0b7da67e0d41ee.jpg', '<p>Naomi Malone, một cô gái cá tính sở hữu một thân hình bốc lửa, muốn lên Las Vegas để đổi đời. Tại Las Vegas, việc đầu tiên cô kiếm được là múa cột thoát y trong một hộp đêm rẻ tiền Cheetah. Nhờ các mối quan hệ cùng thân hình quyến rũ và khả năng bốc lửa của mình, Naomi đã dần trở ngôi sao của sàn Stardust, nơi trình diễn vũ thoát y nổi tiếng tại Las Vegas. Nhưng càng nổi tiếng, cô thấy mình càng dấn sâu vào thế giới nhiều cám dỗ và đầy thủ đoạn mà trước kia cô từng ao ước.</p>', 'Full', 1, 'single', 'completed', 10, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Elizabeth Berkley","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Glenn Plummer","avatar":""},{"name":"Robert Davi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324540);
