INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-lieu-mang', 'Kẻ Liều Mạng', 'Desperado', 'https://phimimg.com/upload/vod/20240207-1/34f240421897ae0efeec42cab32dc222.jpg', 'https://phimimg.com/upload/vod/20240207-1/5c4b3e80cf6b31d12186956e62e396f1.jpg', '<p>Mariachi lao đầu vào thế giới ngầm biên giới đen tối khi lần theo dấu vết máu đến tên cuối cùng của trùm ma túy Mexico khét tiếng, Bucho, cho một cuộc đọ sức đầy hành động, đầy đạn. Với sự giúp đỡ của người bạn thân nhất và một chủ hiệu sách xinh đẹp, Mariachi lần theo dấu vết của Bucho, đối đầu với đội quân những kẻ liều lĩnh và để lại dấu vết máu của chính mình.</p>', 'Full', 1, 'single', 'completed', 11, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Antonio Banderas","avatar":""},{"name":"Salma Hayek","avatar":""},{"name":"Joaquim de Almeida","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Cheech Marin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324540);
