INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-thuc-nguy-hiem', 'Nhận Thức Nguy Hiểm', 'Dangerous Minds', 'https://phimimg.com/upload/vod/20240207-1/c198f020b5bd85e9ebd1f804868aaed4.jpg', 'https://phimimg.com/upload/vod/20240207-1/82657773b9094306465148ea9b716c08.jpg', '<p>Cựu lính thủy đánh bộ Louanne Johnson nhận được hợp đồng giảng dạy trong một chương trình thí điểm dành cho những thanh thiếu niên thông minh nhưng kém thành tích tại một trường trung học khét tiếng trong thành phố. Sau khi trải qua một ngày đầu tiên tồi tệ, cô ấy quyết định mình phải lịch sự theo chiều gió. Khi Johnson trở lại lớp học, cô ấy đã trang bị cho mình một thái độ thẳng thắn được thể hiện qua quá trình huấn luyện quân sự và quyết tâm không sợ hãi để cải thiện cuộc sống của học sinh -- bất kể giá nào.</p>', 'Full', 1, 'single', 'completed', 11, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michelle Pfeiffer","avatar":""},{"name":"George Dzundza","avatar":""},{"name":"Courtney B. Vance","avatar":""},{"name":"Robin Bartlett","avatar":""},{"name":"John Neville","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324540);
