INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-doi-trang', 'Điệp Vụ Dơi Trắng', 'Ace Ventura: When Nature Calls', 'https://phimimg.com/upload/vod/20240123-1/be2a65ebd47263adb79c833951cf8154.jpg', 'https://phimimg.com/upload/vod/20240123-1/21e9d57ccb64863dcca85ccd57b3c3f8.jpg', '<p>Ace Ventura, nổi lên từ người lưu vong tự áp đặt trong một Himalaya Hideaway từ xa, đi đến Châu Phi với Explorer Fulton Greenwall để tìm một con dơi linh thiêng được bảo sẽ ngăn chặn một cuộc chiến giữa với Wachotoo và Wachati Tribes. Tất nhiên, khi Ace tham gia, tất cả phá vỡ địa ngục ...</p>', 'Full', 1, 'single', 'completed', 13, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324540);
