INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-dang-ngo', 'Những Kẻ Đáng Ngờ', 'The Usual Suspects', 'https://phimimg.com/upload/vod/20240121-1/41964ae1deed1abc341d1eb6cbfc67fd.jpg', 'https://phimimg.com/upload/vod/20240121-1/3316ac21ec665fdf575c295f4e888270.jpg', '<p>Trong một phòng thẩm vấn ở LA, Verbal Kint cố gắng thuyết phục các đặc vụ liên bang rằng một chúa tể tội phạm huyền thoại, Keyser Soze, không chỉ tồn tại mà còn có trách nhiệm lôi kéo anh ta và bốn đối tác của anh ta vào một vụ trộm trị giá hàng triệu đô la và kết thúc bằng một vụ nổ ở cảng San Pedro - chỉ còn lại một số người sống sót. Verbal thu hút những người thẩm vấn của mình bằng một câu chuyện đáng kinh ngạc về năng lực gần như siêu phàm của tên tội phạm.</p>', 'Full', 1, 'single', 'completed', 11, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Spacey","avatar":""},{"name":"Stephen Baldwin","avatar":""},{"name":"Gabriel Byrne","avatar":""},{"name":"Chazz Palminteri","avatar":""},{"name":"Kevin Pollak","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324540);
