INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-bac-1995', 'Sòng Bạc', 'Casino', 'https://phimimg.com/upload/vod/20240121-1/16a6a98a986071b5271fcc68924a15bf.jpg', 'https://phimimg.com/upload/vod/20240121-1/7c8dfb904f7613475d45287f8ff8969c.jpg', '<p>Bộ phim Casino - Sòng Bạc nói về những ông chủ kinh doanh sòng bạc tại thành phố hoa lệ Los Angeles không ai mà không biết đến Ace Rothstein, một đại gia khét tiếng trong giới thượng lưu với những casino thời thượng và hút hàng. Ace có hai người thân thiết nhất luôn bên cạnh mình là Nicky Santoro, người bạn chí cốt, luôn thay anh giải quyết những phi vụ rắc rối, và Ginger, cô bạn đời xinh đẹp, quyến rũ và rất cá tính. Nhưng không phải nắm giữ một núi tiền thì hạnh phúc sẽ luôn mỉm cười, bằng chứng là quanh Ace có không biết bao nhiêu kẻ thù...</p>', 'Full', 1, 'single', 'completed', 14, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Sharon Stone","avatar":""},{"name":"Joe Pesci","avatar":""},{"name":"Don Rickles","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"James Woods","avatar":""},{"name":"Alan King","avatar":""},{"name":"Pasquale Cajano","avatar":""},{"name":"L.Q. Jones","avatar":""},{"name":"Dick Smothers","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324540);
