INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mighty-morphin-power-rangers-the-movie', 'Mighty Morphin Power Rangers: The Movie', 'Mighty Morphin Power Rangers: The Movie', 'https://phimimg.com/upload/vod/20240104-1/1860fe7f748fc45f5756d05f18c22cd2.jpg', 'https://phimimg.com/upload/vod/20240104-1/4a960ca41cea7620ad92cc2e996aacd7.jpg', '<p>Sáu thiếu niên đáng kinh ngạc xuất kích và đánh bại cái ác ở khắp mọi nơi với tư cách là Mighty Morphin Power Rangers, nhưng lần này Power Rangers có thể gặp phải trận đấu của họ khi họ đối đầu với Ivan Ooze, con quái vật độc ác nhất mà thiên hà từng thấy.</p>', 'Full', 1, 'single', 'completed', 12, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason David Frank","avatar":""},{"name":"Steve Cardenas","avatar":""},{"name":"Amy Jo Johnson","avatar":""},{"name":"David Yost","avatar":""},{"name":"Johnny Yong Bosch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324540);
