INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-fluke', 'Chú Chó Fluke', 'Fluke', 'https://phimimg.com/upload/vod/20240108-1/92343eabe72e2a5a027d2a92602436b2.jpg', 'https://phimimg.com/upload/vod/20240108-1/b684449906e9dc6aa393701e1a89a318.jpg', '<p>Thomas Johnson nghiện công việc chết trong một tai nạn ô tô và sống lại như một con chó. Nhớ lại một số con người của mình, anh ta quay trở lại với vợ và con trai của mình để bảo vệ họ khỏi người đàn ông đã gây ra tai nạn cho anh ta. Nhưng thời gian trôi qua, anh ấy nhớ lại nhiều hơn về cuộc đời mình và nhận ra mình không phải là một người chồng và người cha tốt như vậy.</p>', 'Full', 1, 'single', 'completed', 15, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Modine","avatar":""},{"name":"Nancy Travis","avatar":""},{"name":"Eric Stoltz","avatar":""},{"name":"Max Pomeranc","avatar":""},{"name":"Ron Perlman","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324540);
