INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-hai-con-khi', 'Mười Hai Con Khỉ', '12 Monkeys', 'https://phimimg.com/upload/vod/20240104-1/63e5ce915a4a7e5368e8c7faafb49e57.jpg', 'https://phimimg.com/upload/vod/20240104-1/5f9a5e0f1ff71f5b4ad6c19a7a02811b.jpg', '<p>James Cole, một tù nhân của tiểu bang vào năm 2035, có thể kiếm được tạm tha nếu anh ta đồng ý du hành ngược thời gian và cản trở một bệnh dịch tàn khốc. Virus đã xóa sạch hầu hết dân số Trái đất và phần còn lại sống dưới lòng đất vì không khí độc hại. Trở về năm 1990, sáu năm trước khi bắt đầu bệnh dịch hạch, Cole sớm bị giam cầm trong một cơ sở tâm thần vì những cảnh báo của ông nghe có vẻ điên rồ. Ở đó, ông gặp một nhà khoa học tên Tiến sĩ Kathryn Railly và Jeffrey Goines, con trai điên của một nhà chính virus nổi tiếng. Cole được các nhà chức trách trở lại vào năm 2035, và cuối cùng kết thúc tại điểm đến dự định của ông vào năm 1996. Ông bắt cóc Dr. Railly để tranh thủ sự giúp đỡ trong nhiệm vụ của mình. Cole phát hiện ra Graffiti bởi một nhóm quyền động vật rõ ràng được gọi là đội quân của mười hai con khỉ, nhưng khi anh ta delves vào bí ẩn, anh ta nghe thấy giọng nói, mất đi vòng bi và nghi ngờ sự tỉnh táo của chính mình. Anh ta phải tìm ra nếu GOINES, người dường như là một kẻ mất trí say sưa, giữ chìa khóa cho câu đố.</p>', 'Full', 1, 'single', 'completed', 14, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324540);
