INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ngam-1995', 'Thế Giới Ngầm', 'Underground', 'https://phimimg.com/upload/vod/20240111-1/f8f947e17d857de6c09a0537e20e033e.jpg', 'https://phimimg.com/upload/vod/20240111-1/57f6511c39b3631b062ef58614cd5900.jpg', '<p>Một nhóm những người theo chủ nghĩa xã hội người Serbia chuẩn bị cho cuộc chiến trong một thế giới ngầm siêu thực chứa đầy những bữa tiệc, bi kịch, tình yêu và thù hận.</p>', 'Full', 1, 'single', 'completed', 18, 1995, 'Vietsub', 'HD', 'Quốc Gia Khác', 0, '[{"name":"Miki Manojlović","avatar":""},{"name":"Lazar Ristovski","avatar":""},{"name":"Mirjana Joković","avatar":""},{"name":"Slavko Štimac","avatar":""},{"name":"Ernst Stötzner","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324540);
