INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-thu-giau-mat', 'Xạ Thủ Giấu Mặt', 'The Shooter', 'null', 'https://phimimg.com/upload/vod/20240102-1/b660cbb01c94a10be9f1abb06986b026.jpg', '<p>Xạ Thủ Giấu Mặt - The Shooter xoay quanh câu chuyện Đại sứ Cuba bị giết ở New York. Để ngăn chặn một cuộc tấn công khác của những kẻ khủng bố tại hội nghị thượng đỉnh Mỹ-Cuba ở Praha, CIA phái một trong những đặc vụ liên bang giỏi nhất của họ, Michael Dane. Kẻ giết người bị tình nghi là chủ câu lạc bộ đồng tính nữ, Simone Rosset. Nhưng như thường lệ, mọi thứ phức tạp hơn nhiều so với lúc đầu; và do đó Dane phải vận dụng bộ não thay vì cơ bắp của mình để có thể tồn tại.</p>', 'Full', 1, 'single', 'completed', 12, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Assumpta Serna","avatar":""},{"name":"Maruschka Detmers","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324540);
