INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-dang-karate-3', 'Nhất Đẳng Karate 3', 'Best Of The Best 3', 'https://phimimg.com/upload/vod/20240123-1/45728260d12a1a3ee9b2914f886b3376.jpg', 'https://phimimg.com/upload/vod/20240123-1/5ba9e99485abcb4e508da53a5bfbea7a.jpg', '<p>Nhất Đẳng Karate 3 - Best of the Best 3 xoay quanh một thị trấn nhỏ, nơi đang bị khủng bố và kiểm soát bởi một nhóm người độc ác và tàn bạo. Khi đến thăm em gái đang sống ở đây, Tommy bị cuốn vào cuộc xung đột với Hansen - kẻ đứng đầu băng nhóm tàn ác này. Khi gia đình mình bị tấn công và các cháu của mình bị Hansen bắt cóc, Tommy buộc phải đứng ra chiến đấu giành lại công bằng.</p>', 'Full', 1, 'single', 'completed', 12, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gina Gershon","avatar":""},{"name":"Christopher McDonald","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324540);
