INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jumanji', 'Jumanji', 'Jumanji', 'https://phimimg.com/upload/vod/20231219-1/3ebc30e6c399c5acbeb165438e2f074e.jpg', 'https://phimimg.com/upload/vod/20231219-1/5a86c11d34c184f0e177b1fb582b54a6.jpg', '<p>Phim là một câu chuyện kể về Adam vô tình có được chiếc hộp trò chơi, và anh đã rủ cô bạn cùng chơi, khi đang chơi Adam bổng bị hút vào trong chiếc hộp, mãi đến 26 năm sau anh mới có cơ hội ra khỏi chiếc hộp đó vì có người đã khỏi động được chiếc hộp, nhưng anh không phải chui ra một mình mà còn rất nhiều con thú kỳ quái.</p>', 'Full', 1, 'single', 'completed', 14, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Jonathan Hyde","avatar":""},{"name":"Kirsten Dunst","avatar":""},{"name":"Bradley Pierce","avatar":""},{"name":"Bonnie Hunt","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324540);
