INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-z-hoa-giai-phong-an', 'Bảy Viên Ngọc Rồng Z: Hóa Giải Phong Ấn', 'Dragon Ball Z: Wrath Of The Dragon', 'https://phimimg.com/upload/vod/20231211-1/27e4411b4243143c6d67b0fb64f04c7a.jpg', 'https://phimimg.com/upload/vod/20231211-1/15d682267369cc006ed45562a38c11d4.jpg', '<p>Nội dung của phim bắt đầu từ một sinh vật bí ẩn tên là Hoy đến trên Trái đất và những chiến binh Z về cái cách để sử dụng các viên ngọc rồng nhằm để giúp cậu ta hồi sinh một sinh vật có tên là Tapion. Tapion được biết tới là một chiến binh cổ đại bị giam cầm trong một hộp âm nhạc, và Hoy cần anh để chống lại quái vật Hildegarn , người sẽ đến để tiêu diệt Trái Đất. Nhưng khi họ nhận ra rằng Hoy là người sống sót cuối cùng trong một trận chiến ác liệt liên quan tới sự hủy diệt của những người mà họ cho là thấp kém hơn, và rằng vì Tapion trước khi chết đã phong ấn chính mình vào trong con quái vật để hắn không thể sống sót trở lại, chính vì vậy mà vô tình Hoy không phải chỉ cứu Tapion mà còn cứu luôn cả Hildegarn, lúc này nhóm của Goku bị đặt vào tình thế nguy hiểm và phải chiến đấu bên cạnh Tapion để ngăn chặn quái vật hung ác.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 1995, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324540);
