INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-buoc-tren-may', 'Dạo Bước Trên Mây', 'A Walk In The Clouds', 'https://phimimg.com/upload/vod/20231212-1/8b38a063a5f6e3bc95dfde10a6ed2d1d.jpg', 'https://phimimg.com/upload/vod/20231212-1/8e71145b1217d5b4d9ee947a5b538f94.jpg', '<p>Một người lính trẻ của Mỹ đã kết hôn, Paul, trở về nhà sau Thế chiến II và gặp một cô gái, Victoria, trên đường đi. Victoria đang mang thai và sợ hãi về việc trở về nhà đến gia đình Mexico của mình, nơi cô ấy nghiêm khắc về người cha bảo vệ chắc chắn sẽ không chấp nhận cô ấy mất thai. Muốn giúp đỡ, Paul đề nghị đặt ra khi chồng làm dịu mọi thứ cho đến khi thời gian như vậy, anh ta tự do rời đi một lần nữa nhưng khi họ dành thời gian bên nhau, họ bắt đầu yêu nhau. Tuy nhiên, Paul vẫn kết hôn và họ phải giữ mình lại trước khi định mệnh sẽ can thiệp và bi kịch sẽ xảy ra sau đó và cuối cùng họ sẽ ở bên nhau.</p>', 'Full', 1, 'single', 'completed', 19, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324540);
