INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-dung-cam-1995', 'Trái Tim Dũng Cảm', 'Braveheart', 'https://phimimg.com/upload/vod/20231211-1/556c43708303dfe03cc1b4714aad3c5d.jpg', 'https://phimimg.com/upload/vod/20231211-1/f3c37b106bc184c0f7488d5f1b5b2f4e.jpg', '<p>Bị mất cả cha và anh trai trong cuộc chiến chống lại quân Anh, người vợ yêu dấu sau này cũng chết dưới tay lãnh chúa độc ác, William Wallace với niềm khát khao tự do và nỗi đau mất mát đã đứng lên tập hợp nghĩa quân nổi dậy vì nền tự do của Scotland. Phim có bối cảnh thị trấn Elerslie, Scotland vào thế kỷ 13. William Wallace (Mel Gibson) sống cùng cha (Sandy Nelson) và người anh trai Malcolm (Sean Lawlor) tại thị trấn nhỏ bé này. Cuộc sống của ba cha con không yên ổn bởi tình hình chính trị lúc bấy giờ vô cùng phức tạp. Bên ngoài, đế quốc Anh vẫn lăm le đô hộ, nội bộ bên trong lục đục, tương tàn lẫn nhau. Các quý tộc dùng tiền bạc và quyền lực để chiếm đoạt ngai vàng đang bỏ trống do nhà vua vừa qua đời. Nhưng chính các nhà quý tộc này cũng trở thành các con bài dưới vị vua nước Anh Edward (Patrick McGoohan) thâm hiểm và tài giỏi. Vị vua này trao cho các nhà quý tộc Scott nhiều đặc quyền đặc lợi nhằm ru ngủ và mua chuộc họ.</p>', 'Full', 1, 'single', 'completed', 12, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Sophie Marceau","avatar":""},{"name":"Patrick McGoohan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324540);
