INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-trieu-do', 'Thủy Triều Đỏ', 'Crimson Tide', 'https://phimimg.com/upload/vod/20231211-1/0775e35af6ef275eedce140acc819c48.jpg', 'https://phimimg.com/upload/vod/20231211-1/9a1de82b63af8f589c5a559412a2899e.jpg', '<p>Khi một cựu quân nhân Liên Xô nắm quyền kiểm soát một căn cứ tên lửa hạt nhân, nó gây nên tình trạng khẩn cấp toàn cầu, lớn nhất kể từ cuộc khủng khoảng tên lửa ở Cuba. Thế giới đứng trên bờ vực của thảm họa, tàu khu trục USS Alabama tiến hành tuần tra các vùng biển nước Nga mang theo hỏa lực hạt nhân đủ để bắt đầu Thế chiến III. Khi cuộc khủng hoảng leo thang, một sự kiện không thể tưởng tượng đã xảy ra: Tàu khu trục Alabama nhận được lệnh để khởi động tên lửa hạt nhân của mình...</p>', 'Full', 1, 'single', 'completed', 12, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gene Hackman","avatar":""},{"name":"Denzel Washington","avatar":""},{"name":"Matt Craven","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324540);
