INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-me-dien-anh', 'Giang Hồ Mê Điện Ảnh', 'Get Shorty', 'https://phimimg.com/upload/vod/20231211-1/63cddc91b47888d35e5ef270c964b7e0.jpg', 'https://phimimg.com/upload/vod/20231211-1/bfb8b4032f1f81ed6542dff964f1773a.jpg', '<p>Chili Palmer là một tên cướp ở Miami được ông chủ của mình, Bones Barboni, kẻ tâm thần, cử đến để đòi một khoản nợ khó đòi từ Harry Zimm, một nhà sản xuất Hollywood chuyên sản xuất những bộ phim kinh dị sến sẩm. Khi Chili gặp người phụ nữ hàng đầu của Harry, tia lửa lãng mạn bay lên. Sau khi giới thiệu câu chuyện cuộc đời mình như một ý tưởng phim, Chili biết được rằng trở thành một tên cướp và trở thành một nhà sản xuất ở Hollywood thực sự không khác nhau mấy.</p>', 'Full', 1, 'single', 'completed', 13, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Travolta","avatar":""},{"name":"Gene Hackman","avatar":""},{"name":"Rene Russo","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"Dennis Farina","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324540);
