INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-tuoc-ma-ca-rong', 'Bá Tước Ma Cà Rồng', 'Dracula: Dead And Loving It', 'https://phimimg.com/upload/vod/20231219-1/be6b1f1df8b54aea32f45d712ad17a65.jpg', 'https://phimimg.com/upload/vod/20231219-1/6a3682ed0ea8456dd8f0257c4fb57d92.jpg', '<p>Dracula Dead And Loving It kể về những điều bí ẩn trong thế giới của ma cà rồng mà không phải ai cũng có cơ hội được tìm hiểu tường tận. Như thường lệ, người Anh giàu có bị tấn công bởi Dracula và Giáo sư Van Helsing xuất hiện để cứu nguy.</p>', 'Full', 1, 'single', 'completed', 14, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Leslie Nielsen","avatar":""},{"name":"Mel Brooks","avatar":""},{"name":"Peter MacNicol","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324540);
