INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phich-lich-hoa', 'Phích Lịch Hỏa', 'Thunderbolt', 'https://phimimg.com/upload/vod/20231205-1/a2a94d6cf63dce9325529e6af1616b3a.jpg', 'https://phimimg.com/upload/vod/20231205-1/f89743c3795b290263a572b1bfbaa2f8.jpg', '<p>Để giải thoát cho người em gái bị bắt cóc của mình, người thợ sửa xe thể thao Thành Long đã phải đánh bại một tay đua đường phố siêu tội phạm.</p>', 'Full', 1, 'single', 'completed', 11, 1995, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Anita Yuen","avatar":""},{"name":"Michael Wong Man-Tak","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Dayo Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324540);
