INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('all-things-fair', 'All Things Fair', 'All Things Fair', 'https://phimimg.com/upload/vod/20231203-1/6b6368658b786e13c479c901c2483ff5.jpg', 'https://phimimg.com/upload/vod/20231203-1/cf64d36dc33c582a891ba1c0f014fe7a.jpg', '<p>Malmö, Thụy Điển trong Thế chiến thứ hai. Stig là một học sinh 15 tuổi trên bờ vực trưởng thành. Viola là 37 tuổi và giáo viên của mình. Anh ta bị thu hút bởi vẻ đẹp và trưởng thành của cô ấy. Cô bị anh ta bị lôi cuốn bởi tuổi trẻ và sự hồn nhiên của mình. Đồng thời, Stig trở thành bạn bè với chồng của Viola Kjell, người dạy anh âm nhạc cổ điển, và vụ việc tiếp tục ngay cả sau khi anh hiểu rằng anh có mối quan hệ với vợ. Nhưng không có gì để ngăn chặn nó. Nhưng mối quan hệ đam mê và bị cấm của Stig và Viola sẽ có hậu quả mà họ không bao giờ có thể mong đợi.</p>', 'Full', 1, 'single', 'completed', 21, 1995, 'Vietsub', 'HD', 'Thụy Điển', 0, '[]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324540);
