INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-tac', 'Tin Tặc', 'Hackers', 'https://phimimg.com/upload/vod/20231203-1/52e0848dc063f890314464065dbf2e6a.jpg', 'https://phimimg.com/upload/vod/20231203-1/3f86b1b8526c472de6bd339ccc94cead.jpg', '<p>Sau khi quậy tan nát hệ thống máy tính nước Mỹ với một loại virus tự viết, anh chàng thiên tài hacker nọ bị cấm tiệt đến gần máy vi tính cho đến năm sinh nhật thứ 18. Nhiều năm sau, anh chàng cùng đám bạn của mình phát hiện ra một loại virus máy tính nguy hiểm, trong khi bị cảnh sát an ninh mạng truy đuổi và kể cả tay hacker giấu mặt đang sử dụng con virus để tống tiền các hãng vận chuyển tàu trên thế giới. Họ phải chặn đứng âm mưu xấu xa và chứng minh mình vô tội…</p>', 'Full', 1, 'single', 'completed', 13, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonny Lee Miller","avatar":""},{"name":"Angelina Jolie","avatar":""},{"name":"Jesse Bradford","avatar":""},{"name":"Matthew Lillard","avatar":""},{"name":"Renoly Santiago","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324540);
