INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('babe-chu-heo-chan-cuu', 'Babe: Chú Heo Chăn Cừu', 'Babe', 'https://phimimg.com/upload/vod/20231202-1/f8cd44e171ee0d6255de1e86b9dd7062.jpg', 'https://phimimg.com/upload/vod/20231202-1/f369842ee809b140b2d597932bda6d15.jpg', '<p>Một đàn lợn bị đem ra làm vật giết thịt trong lễ hội. Nhờ đoán chính xác trọng lượng của Babe trong một trò chơi mà bác nông dân Arthur Hoggett được đưa con lợn bé nhất trong đàn về nhà, nhờ đó nó thoát khỏi số phận bi thảm như mẹ và các anh em. Arthur đặt tên cho con vật là Babe và để nó ở cùng với Fly, con chó chăn cừu, và bầy con của nó. Bác nông dân căn dặn Babe rằng chú sẽ không được hưởng một số đặc quyền như các con chó, chẳng hạn như vào nhà hoặc ra cánh đồng. Cuộc sống hạnh phúc của Babe bắt đầu từ đây...</p>', 'Full', 1, 'single', 'completed', 19, 1995, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Christine Cavanaugh","avatar":""},{"name":"Miriam Margolyes","avatar":""},{"name":"Danny Mann","avatar":""},{"name":"Hugo Weaving","avatar":""},{"name":"Miriam Flynn","avatar":""},{"name":"James Cromwell","avatar":""},{"name":"Magda Szubanski","avatar":""},{"name":"Russi Taylor","avatar":""},{"name":"Roscoe Lee Browne","avatar":""},{"name":"Evelyn Krape","avatar":""},{"name":"Michael Edward-Stevens","avatar":""},{"name":"Charles Bartlett","avatar":""},{"name":"Paul Livingston","avatar":""},{"name":"Zoe Burton","avatar":""},{"name":"Paul Goddard","avatar":""},{"name":"Wade Haywar","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f1