INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ace-venture-tieng-goi-hoang-da', 'Ace Venture: Tiếng Gọi Hoang Dã', 'Ace Ventura: When Nature Calls', 'https://phimimg.com/upload/vod/20231202-1/c1a6aa7d9368f1ce04cb82b0ec37c671.jpg', 'https://phimimg.com/upload/vod/20231202-1/970e127393faa6c8367178c44e466ef6.jpg', '<p>Ace đi đến các khu rừng châu Phi để chữa trị cho một con dơi trắng quý hiếm. Nhưng nếu anh thất bại, một cuộc chiến với bộ tộc Wachootoo hung bạo chắc chắn sẽ xảy ra.</p>', 'Full', 1, 'single', 'completed', 10, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Ian McNeice","avatar":""},{"name":"Simon Callow","avatar":""},{"name":"Maynard Eziashi","avatar":""},{"name":"Bob Gunton","avatar":""},{"name":"Sophie Okonedo","avatar":""},{"name":"Tommy Davidson","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"Danny Daniels","avatar":""},{"name":"Sam Phillips","avatar":""},{"name":"Damon Standifer","avatar":""},{"name":"Andrew Steel","avatar":""},{"name":"Bruce Spence","avatar":""},{"name":"Tom Grunke","avatar":""},{"name":"Arsenio \"Sonny\" Trinidad","avatar":""},{"name":"Kristin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324540);
