INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-basketball-diaries', 'The Basketball Diaries', 'The Basketball Diaries', 'https://phimimg.com/upload/vod/20231210-1/598b1ce8d5d6c69c8bbc0b16f02de60a.jpg', 'https://phimimg.com/upload/vod/20231210-1/9f042ed056377390beca0b23310c7ac2.jpg', '<p>Bộ phim chuyển thể của đường phố Jim Carroll khó khăn về phong cách vạn hoa miễn phí rơi vào thế giới nghiện ma túy. Là một thành viên của một đội bóng rổ trường trung học dường như bất bại, giữa cuộc sống của Jim xung quanh sân bóng rổ và tòa án trở thành một phép ẩn dụ cho thế giới trong tâm trí anh ta. Một người bạn tốt nhất đang chết vì bệnh bạch cầu, một huấn luyện viên (Swifty), người có những pha tự do không thể chấp nhận được với các chàng trai trong đội của mình, Angst tình dục tuổi teen và một sự thèm ăn không lành mạnh cho heroin - tất cả những điều này bắt đầu lấn chiếm giấc mơ của Jim Jim Trở thành một ngôi sao bóng rổ. Chẳng mấy chốc, những con đường tối của New York trở thành nơi ẩn náu từ mối quan tâm gắn kết của mẹ mình đối với con trai mình. Anh ta không thể về nhà và lối thoát duy nhất của anh ta khỏi thực tế trên đường phố là heroin mà anh ta đánh cắp, cướp và gái dâm. Chỉ với sự giúp đỡ của Reggie, một người bạn hàng xóm lớn tuổi mà Jim đã chọn một trò chơi ngay bây giờ và sau đó, anh ta có thể bắt đầu cuộc hành trình dài trở lại Sanity.</p>', 'Full', 1, 'single', 'completed', 20, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '[]', 1784690324540);
