INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-phan-dredd', 'Thẩm Phán Dredd', 'Judge Dredd', 'https://phimimg.com/upload/vod/20231129-1/8fedd4c41070b35fb4784faaec69da50.jpg', 'https://phimimg.com/upload/vod/20231129-1/2dea04efd95572e299dd2f01011d30d1.jpg', '<p>Năm 2139, trái đất trở nên chật chội. Tội phạm tại các thành phố gia tăng và chúng hung hãn và hoạt động ngang nhiên hơn rất nhiều. Để đối phó với tình trạng này, 1 hệ thống pháp luật mới được dựng lên, đó là hệ thống Judge 3 trong 1: cảnh sát - quan toà - hành hình.<br/><br/>Ở thành phố Mega City 1, người đứng đầu Judge là Joseph Dredd. Rắc rối xảy ra khi Dredd phát hiện ra 1 người có cùng DNA với mình. Và nhiệm vụ của Dredd là phải tìm hiểu quá khứ và xem âm mưu của hắn ở thành phố này là gì.</p>', 'Full', 1, 'single', 'completed', 12, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Diane Lane","avatar":""},{"name":"Armand Assante","avatar":""},{"name":"Rob Schneider","avatar":""},{"name":"Jürgen Prochnow","avatar":""},{"name":"Max von Sydow","avatar":""},{"name":"Christopher Adamson","avatar":""},{"name":"Joanna Miles","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Balthazar Getty","avatar":""},{"name":"Maurice Roëves","avatar":""},{"name":"Ian Dury","avatar":""},{"name":"Ewen Bremner","avatar":""},{"name":"Peter Marinker","avatar":""},{"name":"Martin McDougall","avatar":""},{"name":"Mitchell Ryan","avatar":""},{"name":"Scott Wi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324540);
