INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-cua-co-dau-phan-2', 'Bố Của Cô Dâu Phần 2', 'Father of the Bride Part II', 'https://phimimg.com/upload/vod/20231125-1/113b54cbd708e246a630b4eca6cd3e13.jpg', 'https://phimimg.com/upload/vod/20231125-1/b9367ee5596df67ac4df174749cf4636.jpg', '<p>Rắc rối gia đình liên tục bám theo George Banks. Sau khi sống sót qua đám cưới của con gái trong phần một, bây giờ George phải tiếp tục đối đấu với cái thai của cô bé. Để làm sự việc phức tạp hơn, cô vợ Nina cũng cùng lúc mang thai!</p>', 'Full', 1, 'single', 'completed', 13, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Martin","avatar":""},{"name":"Diane Keaton","avatar":""},{"name":"Martin Short","avatar":""},{"name":"Kimberly Williams-Paisley","avatar":""},{"name":"George Newbern","avatar":""},{"name":"Kieran Culkin","avatar":""},{"name":"BD Wong","avatar":""},{"name":"Peter Michael Goetz","avatar":""},{"name":"Kate McGregor-Stewart","avatar":""},{"name":"Jane Adams","avatar":""},{"name":"Eugene Levy","avatar":""},{"name":"Rebecca Chambers","avatar":""},{"name":"April Ortiz","avatar":""},{"name":"Dulcy Rogers","avatar":""},{"name":"Kathy Anthony","avatar":""},{"name":"Adrian Canzoneri","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324540);
