INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-ay-va-bay-gio', 'Ngày Ấy Và Bây Giờ', 'Now and Then', 'https://phimimg.com/upload/vod/20231123-1/9237ce3ab367c55a802d41a1759cbf4b.jpg', 'https://phimimg.com/upload/vod/20231123-1/9b3abcc8e4bfbc1b519ba066f620eeb6.jpg', '<p>Hoài niệm về quãng thời gian buồn vui lẫn lộn từ thời thơ ấu đến tuổi dậy thì, bốn người bạn gái thời thơ ấu — Teeny, Chrissy, Samantha và Roberta — nhớ lại mùa hè kỳ diệu năm 1970. Trong chuyến đi bộ về ký ức, họ hòa giải những trải nghiệm với con trai, bí mật, kẻ bắt nạt, v.v.</p>', 'Full', 1, 'single', 'completed', 15, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christina Ricci","avatar":""},{"name":"Rosie O''Donnell","avatar":""},{"name":"Thora Birch","avatar":""},{"name":"Melanie Griffith","avatar":""},{"name":"Gaby Hoffmann","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Ashleigh Aston Moore","avatar":""},{"name":"Rita Wilson","avatar":""},{"name":"Devon Sawa","avatar":""},{"name":"Walter Sparrow","avatar":""},{"name":"Cloris Leachman","avatar":""},{"name":"Lolita Davidovich","avatar":""},{"name":"Janeane Garofalo","avatar":""},{"name":"Hank Azaria","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Rumer Willis","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324540);
