INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-bau-cong-go', 'Kho Báu Công Gô', 'Congo', 'https://phimimg.com/upload/vod/20231123-1/37f2d4d1de1b6f1280a455e2ca1a60e6.jpg', 'https://phimimg.com/upload/vod/20231123-1/2d7f9b403c8a658b08de3b45f6636f6a.jpg', '<p>Tám người bắt tay vào một chuyến thám hiểm đến Congo, một vùng đất bí ẩn của châu Phi chưa được khám phá, nơi lòng tham của con người và các quy luật tự nhiên đã trở nên điên cuồng. Khi những người thích cảm giác mạnh -- một số có động cơ thầm kín -- tình cờ gặp một chủng loài vượn sát thủ.</p>', 'Full', 1, 'single', 'completed', 16, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Laura Linney","avatar":""},{"name":"Dylan Walsh","avatar":""},{"name":"Ernie Hudson","avatar":""},{"name":"Tim Curry","avatar":""},{"name":"Grant Heslov","avatar":""},{"name":"Adewale Akinnuoye-Agbaje","avatar":""},{"name":"Joe Don Baker","avatar":""},{"name":"Lorene Noh","avatar":""},{"name":"Mary Ellen Trainor","avatar":""},{"name":"Misty Rosas","avatar":""},{"name":"Stuart Pankin","avatar":""},{"name":"Carolyn Seymour","avatar":""},{"name":"Romy Rosemont","avatar":""},{"name":"James Karen","avatar":""},{"name":"Bill Pugin","avatar":""},{"name":"Lawrence T. Wrentz","avatar":""},{"name":"John Hawkes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324540);
