INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-diep-vu-mat-vang', 'Điệp Viên 007: Điệp Vụ Mắt Vàng', 'GoldenEye', 'https://phimimg.com/upload/vod/20231119-1/134b1e623ba5c6833abd50655e6911d1.jpg', 'https://phimimg.com/upload/vod/20231119-1/def4f9b401cefdefffc62ce8361b03a4.jpg', '<p>Được lệnh đến Nga để tìm ra mật mã bí mật của Goldeneye, một thứ vũ khí bí mật có thề phá hủy cả trái đất. Trong khi thi hành nhiệm vụ, điệp viên 007 phải đụng độ với vị đồng nghiệp xấu tính 006 Alec Trevelyan. Anh sẽ làm thế nào để hoàn thành nhiệm vụ khó khăn của mình...</p>', 'Full', 1, 'single', 'completed', 14, 1995, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Izabella Scorupco","avatar":""},{"name":"Famke Janssen","avatar":""},{"name":"Joe Don Baker","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Robbie Coltrane","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"Gottfried John","avatar":""},{"name":"Alan Cumming","avatar":""},{"name":"Desmond Llewelyn","avatar":""},{"name":"Samantha Bond","avatar":""},{"name":"Michael Kitchen","avatar":""},{"name":"Serena Gordon","avatar":""},{"name":"Simon Kunz","avatar":""},{"name":"Pavel Douglas","avatar":""},{"name":"Olivier Lajous","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324540);
