INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diep-vien-007-diep-vu-mat-vang', 'Điệp Viên 007: Điệp Vụ Mắt Vàng', 'GoldenEye', 'điệp viên 007: điệp vụ mắt vàng goldeneye pierce brosnan sean bean izabella scorupco famke janssen joe don baker judi dench robbie coltrane tchéky karyo gottfried john alan cumming desmond llewelyn samantha bond michael kitchen serena gordon simon kunz pavel douglas olivier lajous ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-nho', 'Công Chúa Nhỏ', 'A Little Princess', 'https://phimimg.com/upload/vod/20231119-1/c1579e16cb53501d64ad289f7998486d.jpg', 'https://phimimg.com/upload/vod/20231119-1/8f8238c0faecf0cc27903619955d8d03.jpg', '<p>Sara và bố từ Ấn Độ trở về New York vì chiến tranh thế giới lần thứ 1 nổ ra. Em được gửi vào một ngôi trường dành cho nữ sinh quý tộc vì bố em phải ra chiến trường. Vào ngày sinh nhật của mình em nhận được tin bố em đã hy sinh ngoài chiến trường và tài sản gia đình sẽ bị phong tỏa. Từ một học sinh quý tộc em phải trở thành người hầu trong trường nội trú của mình vì không có tiền đóng học phí. Điều ấy cũng không ngăn được em vẫn là một nàng công chúa nhỏ trong mắt mọi người xung quanh vì những cử chỉ đẹp mà em dành cho những con người đau khổ khác, và rồi như những câu chuyện cổ tích mà em hay kể, một điều kỳ diệu đã đến với em...</p>', 'Full', 1, 'single', 'completed', 15, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Liesel Matthews","avatar":""},{"name":"Eleanor Bron","avatar":""},{"name":"Liam Cunningham","avatar":""},{"name":"Rusty Schwimmer","avatar":""},{"name":"Vanessa Lee Chester","avatar":""},{"name":"Rachael Bella","avatar":""},{"name":"Camilla Belle","avatar":""},{"name":"Kelsey Mulrooney","avatar":""},{"name":"Lauren Blumenfeld","avatar":""},{"name":"Vincent Schiavelli","avatar":""},{"name":"Time Winters","avatar":""},{"name":"Arthur Malet","avatar":""},{"name":"Heather DeLoach","avatar":""},{"name":"Alexandra Rea-Baum","avatar":""},{"name":"Juliana Harkavy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"9