INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loai-ac-doc', 'Loài Ác Độc', 'Species', 'https://phimimg.com/upload/vod/20231114-1/c2d0788ae2eb0fb3340f1448b3abef96.jpg', 'https://phimimg.com/upload/vod/20231114-1/faf3fd570ab1361e75feaa42c98c20cc.jpg', '<p>Năm 1993, dự án nghiên cứu văn minh ngoài Trái đất phát hiện sinh thể ngoài hành tinh và phối nó với gien người. Sinh vật lai mang tên Sil, mang hình hài một người đẹp nhưng có thể biến thành một sinh vật khát máu trong tích tắc. Đặc vụ Xavier được giao nhiệm vụ &quot;giải quyết&quot; Sil.</p>', 'Full', 1, 'single', 'completed', 16, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Natasha Henstridge","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Marg Helgenberger","avatar":""},{"name":"Alfred Molina","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Michelle Williams","avatar":""},{"name":"Jordan Lund","avatar":""},{"name":"Herta Ware","avatar":""},{"name":"William Utay","avatar":""},{"name":"Don Fischer","avatar":""},{"name":"Scott McKenna","avatar":""},{"name":"Virginia Morris","avatar":""},{"name":"Jayne Luke","avatar":""},{"name":"David K. Schroeder","avatar":""},{"name":"David Jensen","avatar":""},{"name":"Esthe","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324540);
