INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truoc-luc-binh-minh', 'Trước Lúc Bình Minh', 'Before Sunrise', 'https://phimimg.com/upload/vod/20231113-1/3f24c0a22bacdd57ac7fd56314d992e2.jpg', 'https://phimimg.com/upload/vod/20231113-1/b17284cb1b68cfd0e5923c97be067cfe.jpg', '<p>Anh chàng người Mỹ Jesse tình cờ gặp cô gái Pháp Celine trên một chuyến tàu du lịch vòng quanh châu Âu. Đích đến của chàng là Vienna, để rồi bay về Mỹ vào sáng sớm hôm sau. Nàng thì trên đường trở lại Pháp để bắt đầu kỳ học mới. Họ phải lòng nhau ngay từ cái nhìn đầu tiên.Hai người trò chuyện rất tâm đầu ý hợp, quên cả ăn uống. Thế rồi, khi đến Vienna, chàng tìm cách thuyết phục nàng bầu bạn với mình nốt buổi tối ngày hôm đó, hai người sẽ đi dạo vòng quanh thành phố, chờ đợi đến bình minh, ấy là lúc chàng phải lên đường.Before Sunrise là một bộ phim hiếm hoi lãng mạn mà không bị &quot;sến&quot;. Tình yêu của con người ta khi còn đang độ thăng hoa thì bất cứ một tình huống nho nhỏ nào xảy ra cũng đều là một kỷ niệm lãng ...</p>', 'Full', 1, 'single', 'completed', 16, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ethan Hawke","avatar":""},{"name":"Julie Delpy","avatar":""},{"name":"Andrea Eckert","avatar":""},{"name":"Haymon Maria Buttinger","avatar":""},{"name":"Erni Mangold","avatar":""},{"name":"Tex Rubinowitz","avatar":""},{"name":"Dominik Castell","avatar":""},{"name":"Harold Waiglein","avatar":""},{"name":"Karl Bruckschwaiger","avatar":""},{"name":"Hanno Pöschl","avatar":""},{"name":"Bilge Jeschim","avatar":""},{"name":"Kurti","avatar":""},{"name":"Hans Weingartner","avatar":""},{"name":"Liese Lyon","avatar":""},{"name":"Peter Ily Huemer","avatar":""},{"name":"Otto Reiter","avatar":""},{"name":"Hubert F","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324540);
