INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-mat-trang', 'Bí Ẩn Mặt Trăng', 'Apollo 13', 'https://phimimg.com/upload/vod/20231111-1/4c0a00e1d05f7403f2b1928e34a8ee64.jpg', 'https://phimimg.com/upload/vod/20231111-1/6d8c458099f9e09dec3360628f4b37a9.jpg', '<p>Phim dựa trên câu chuyện có thật về chuyến du hành vũ trụ của NASA lên mặt trăng vào năm 1970. Jim Lovell, Fred Haise và Jack Swigert, 3 phi hành gia sẽ cùng tham gia vào chuyến Apollo 14 nhưng được chuyển công tác và sẽ lên mặt trăng bằng chuyến Apollo 13. Chuyến du hành tưởng chừng thành công nhưng đường truyền oxy cho con tàu bị đứt. Nhiệm vụ thám hiểm mặt trăng trở thành cuộc tìm kiếm đường về Trái đất cho các phi hành gia.</p>', 'Full', 1, 'single', 'completed', 19, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Gary Sinise","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Kathleen Quinlan","avatar":""},{"name":"David Andrews","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Christian Clemenson","avatar":""},{"name":"Brett Cullen","avatar":""},{"name":"Loren Dean","avatar":""},{"name":"Clint Howard","avatar":""},{"name":"Ben Marley","avatar":""},{"name":"Marc McClure","avatar":""},{"name":"Tracy Reiner","avatar":""},{"name":"Joe Spano","avatar":""},{"name":"Mary Kate Schellhardt","avatar":""},{"name":"Emily Ann","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324540);
