INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-tre-em-bi-mat-tich', 'Thành Phố Trẻ Em Bị Mất Tích', 'The City of Lost Children', 'https://phimimg.com/upload/vod/20231111-1/f2bb7c33899ca8c6cb376c8f6edde0e5.jpg', 'https://phimimg.com/upload/vod/20231111-1/3afa75300545ff922a38120978733154.jpg', '<p>Một nhà khoa học trong một xã hội siêu thực bắt cóc trẻ em để đánh cắp giấc mơ của chúng, hy vọng rằng chúng làm chậm quá trình lão hóa của ông.</p>', 'Full', 1, 'single', 'completed', 15, 1995, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Ron Perlman","avatar":""},{"name":"Dominique Pinon","avatar":""},{"name":"Judith Vittet","avatar":""},{"name":"Daniel Emilfork","avatar":""},{"name":"Jean-Claude Dreyfus","avatar":""},{"name":"Geneviève Brunet","avatar":""},{"name":"Odile Mallet","avatar":""},{"name":"Mireille Mossé","avatar":""},{"name":"Serge Merlin","avatar":""},{"name":"Rufus","avatar":""},{"name":"Ticky Holgado","avatar":""},{"name":"Cris Huerta","avatar":""},{"name":"Jean-Louis Trintignant","avatar":""},{"name":"Joseph Lucien","avatar":""},{"name":"Mapi Galán","avatar":""},{"name":"Briac Barthélémy","avatar":""},{"name":"Pierre","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324540);
