INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-le', 'Buổi Lễ', 'La Ceremonie', 'https://phimimg.com/upload/vod/20231111-1/b293eec0405ebd4fc53980e4ab7ac4a1.jpg', 'https://phimimg.com/upload/vod/20231111-1/ba0f8437ee993ef196ca6533446db60c.jpg', '<p>Sophie, một cô hầu gái ít nói và nhút nhát làm việc cho một gia đình thượng lưu người Pháp, tìm thấy một người bạn là Jeanne, trưởng bưu điện năng động và kiên quyết, người đã khuyến khích cô đứng lên chống lại những ông chủ tư sản của mình.</p>', 'Full', 1, 'single', 'completed', 16, 1995, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Isabelle Huppert","avatar":""},{"name":"Sandrine Bonnaire","avatar":""},{"name":"Jean-Pierre Cassel","avatar":""},{"name":"Jacqueline Bisset","avatar":""},{"name":"Virginie Ledoyen","avatar":""},{"name":"Valentin Merlet","avatar":""},{"name":"Julien Rochefort","avatar":""},{"name":"Dominique Frot","avatar":""},{"name":"Jean-François Perrier","avatar":""},{"name":"Ludovic Brillant","avatar":""},{"name":"Claire Chiron","avatar":""},{"name":"Claire-Marie Dentraygues","avatar":""},{"name":"Jean-Pierre Descheix","avatar":""},{"name":"Penny","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324540);
