INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-doi-huyen-thoai', 'Cặp Đôi Huyền Thoại', 'Legendary Couple', 'https://phimimg.com/upload/vod/20231109-1/94e9f6836d3f98ec6877d4d30c95b115.jpg', 'https://phimimg.com/upload/vod/20231109-1/c5bb418d32ffa6b6cecde525c050f2d3.jpg', '<p>Phim xoay quanh Ko Tin-lap, một kế toán viên trung thực và nghiêm túc trong công việc, cùng hành trình trở thành một tay sát thủ khét tiếng khiến cảnh sát phải run sợ. Sau khi được cấp trên giao nhiệm vụ vận chuyển 5 triệu đô la đến ngân hàng, Tin-lap bất ngờ bị nhóm cướp lấy toàn bộ số tiền. Bị cả cảnh sát và sếp đổ oan dàn cảnh cướp tiền, anh đau đớn và phải chấp nhận dùng toàn bộ tài sản để bồi thường. Không còn gì để mất, Tin-lap quyết định bắt cóc cô con gái của sếp để trả thù.</p>', 'Full', 1, 'single', 'completed', 17, 1995, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Chingmy Yau","avatar":""},{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"Ng Yip-Kwong","avatar":""},{"name":"Gregory Charles Rivers","avatar":""},{"name":"Suk-Mui Tam","avatar":""},{"name":"Stuart Yung Sai-Kit","avatar":""},{"name":"Wong Lai-Mui","avatar":""},{"name":"Chan Chi-Fai","avatar":""},{"name":"Nam Yin","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"Frankie Ng Chi-Hung","avatar":""},{"name":"Jack Wong Wai-Leung","avatar":""},{"name":"Kenji Tanigaki","avatar":""},{"name":"Raven Choi Yip-San","avatar":""},{"name":"Yiu Ma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324540);
