INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('roi-khoi-las-vegas', 'Rời Khỏi Las Vegas', 'Leaving Las Vegas', 'https://phimimg.com/upload/vod/20231101-1/91482eb501cac682db2af29a1ae44c8c.jpg', 'https://phimimg.com/upload/vod/20231101-1/3a2743173f020886996b419d2da4e9ff.jpg', '<p>Ben Sanderson, một nhà biên kịch nghiện rượu ở Hollywood, người đã mất tất cả vì uống rượu, đến Las Vegas để uống rượu đến chết. Ở đó, anh gặp và hình thành một tình bạn không mấy dễ chịu và hiệp ước không can thiệp với cô gái điếm Sera.</p>', 'Full', 1, 'single', 'completed', 15, 1995, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Nicolas Cage","avatar":""},{"name":"Elisabeth Shue","avatar":""},{"name":"Julian Sands","avatar":""},{"name":"Richard Lewis","avatar":""},{"name":"Steven Weber","avatar":""},{"name":"Kim Adams","avatar":""},{"name":"Emily Procter","avatar":""},{"name":"Stuart Regen","avatar":""},{"name":"Valeria Golino","avatar":""},{"name":"Graham Beckel","avatar":""},{"name":"Albert Henderson","avatar":""},{"name":"Shashi Bhatia","avatar":""},{"name":"Carey Lowell","avatar":""},{"name":"Anne Lange","avatar":""},{"name":"Thomas Kopache","avatar":""},{"name":"Vincent Ward","avatar":""},{"name":"Lucinda Jenney","avatar":""},{"name":"French","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324540);
