INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-boc-ma-1995', 'Vỏ Bọc Ma', 'GHOST IN THE SHELL', 'https://phimimg.com/upload/vod/20231026-1/a12c099745f8a61084b674a155a3b6d0.jpg', 'https://phimimg.com/upload/vod/20231026-1/36a5874b2befb5a18825855dbec9ce64.jpg', '<p>Vào năm 2029, các rào cản của thế giới chúng ta đã bị phá vỡ bởi mạng và điều khiển học, nhưng điều này lại mang đến lỗ hổng mới cho con người dưới hình thức hack não. Khi một hacker được truy nã gắt gao được gọi là &quot;The Puppetmaster&quot; bắt đầu lôi kéo họ vào chính trị, Phần 9, một nhóm cảnh sát được tăng cường điều khiển học, được gọi đến để điều tra và ngăn chặn Puppetmaster.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 1995, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Atsuko Tanaka","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Iemasa Kayumi","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Yutaka Nakano","avatar":""},{"name":"Tamio Ohki","avatar":""},{"name":"Tessyo Genda","avatar":""},{"name":"Naruki Masahisa","avatar":""},{"name":"Masato Yamanouchi","avatar":""},{"name":"Shinji Ogawa","avatar":""},{"name":"Mitsuru Miyamoto","avatar":""},{"name":"Kazuhiro Yamaji","avatar":""},{"name":"Shigeru Chiba","avatar":""},{"name":"Hiroshi Yanaka","avatar":""},{"name":"Ginzo Matsuo","avatar":""},{"name":"Takashi Matsuyama","avatar":""},{"name":"Sanry","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324540);
