INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-sa-nga-1995', 'Thiên Thần Sa Ngã', 'Fallen Angels', 'https://phimimg.com/upload/vod/20231026-1/5e6747fe13d0c6862cb2f06e312aae82.jpg', 'https://phimimg.com/upload/vod/20231026-1/3cd1e8806e73e05859572ec6e0d771cd.jpg', '<p>Bộ phim giới thiệu về những tay sát thủ và thế giới ngầm của Hồng Kông, được Vương Gia Vệ phát triển từ những tình tiết của Trùng Khánh Sâm Lâm, tác phẩm thành công trước đó của ông. Một tay sát thủ bỏ lại sau lưng những tội lỗi để sống một cuộc sống mới trong khi người nữ trợ tá lại nảy sinh tình cảm với anh. Ngoài ra bộ phim còn kể về một tay intertwined, chuyên sống bằng cách quản lý các công việc của người khác khi họ đã đóng cửa và đang tìm kiếm đồng sự.</p>', 'Full', 1, 'single', 'completed', 26, 1995, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Leon Lai","avatar":""},{"name":"Charlie Yeung","avatar":""},{"name":"Takeshi Kaneshiro","avatar":""},{"name":"Karen Mok","avatar":""},{"name":"Michelle Reis","avatar":""},{"name":"Chan Man-Lei","avatar":""},{"name":"Toru Saito","avatar":""},{"name":"Benz Kong To-Hoi","avatar":""},{"name":"Chan Fai-hung","avatar":""},{"name":"Kwan Lee-na","avatar":""},{"name":"Wu Yuk-Ho","avatar":""},{"name":"Johnnie Kong","avatar":""},{"name":"Wong Kwan-Hong","avatar":""},{"name":"Mak Shu-San","avatar":""},{"name":"Ken Choi Kwok-Ping","avatar":""},{"name":"Chan Siu-Wah","avatar":""},{"name":"Chow Gam-Kong","avatar":""},{"name":"Leung Shin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324540);
