INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-con-khi', '12 Con Khỉ', 'Twelve Monkeys', 'https://phimimg.com/upload/vod/20231024-1/15ef173d399b922d1eb734eca0d3fc2c.jpg', 'https://phimimg.com/upload/vod/20231024-1/ed5e17e4cf56c11e72e47bd827d46679.jpg', '<p>Tù nhân James Cole tình nguyện trở về quá khứ. Nhiệm vụ của anh là tìm ra nguyên nhân căn bệnh dịch đang giết chết hàng tỷ người. Thật không may, anh lại trở về trước thời điểm cần thiết 6 năm. Sau khi tự mình giải thích với bác sĩ Kathryn Reilly, anh chỉ thành công khi tận tâm trong một trại thương điên. Cùng với bạn chung phòng mất trí Jeffrey Goines và 2 manh mối, Cole không ngừng tranh đấu để vén màn bí mật của những nhà cách mạng, những người lên kế hoạch gây chiến tranh virus trên toàn thế giới.</p>', 'Full', 1, 'single', 'completed', 15, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Madeleine Stowe","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"David Morse","avatar":""},{"name":"Jon Seda","avatar":""},{"name":"Christopher Meloni","avatar":""},{"name":"Joey Perillo","avatar":""},{"name":"LisaGay Hamilton","avatar":""},{"name":"Matt Ross","avatar":""},{"name":"Annie Golden","avatar":""},{"name":"Michael Chance","avatar":""},{"name":"H. Michael Walls","avatar":""},{"name":"Bob Adrian","avatar":""},{"name":"Bill Raymond","avatar":""},{"name":"Ernest Abuba","avatar":""},{"name":"Nell Johnson","avatar":""},{"name":"Rozw","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324540);
