INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-dau-thu-thach-3-bao-thu', 'Đương Đầu Thử Thách 3: Báo Thù', 'Die Hard: With a Vengeance', 'https://phimimg.com/upload/vod/20231023-1/ac6e017ab3fa691fa149a1586b2b2d7f.jpg', 'https://phimimg.com/upload/vod/20231023-1/a69e4d306fca1268d4fee13ab0140498.jpg', '<p>Vào một buổi sáng, một quả bom phát nổ tại Bonwit Teller Department Store. Một người tên là Simon gọi điện đến sở và yêu cầu gặp John McClane, giờ là một kẻ nát rượu và bị đình chỉ khỏi sở cảnh sát New York. Simon muốn McClane phải tham gia một trò chơi nếu không sẽ cho nổ quả bom tiếp theo.</p>', 'Full', 1, 'single', 'completed', 18, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Graham Greene","avatar":""},{"name":"Colleen Camp","avatar":""},{"name":"Larry Bryggman","avatar":""},{"name":"Anthony Peck","avatar":""},{"name":"Nicholas Wyman","avatar":""},{"name":"Sam Phillips","avatar":""},{"name":"Kevin Chamberlin","avatar":""},{"name":"Sharon Washington","avatar":""},{"name":"Stephen Pearlman","avatar":""},{"name":"Michael Alexander Jackson","avatar":""},{"name":"Aldis Hodge","avatar":""},{"name":"Mischa Hausserman","avatar":""},{"name":"Edwin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324540);
