INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ga-trai-hu', 'Những Gã Trai Hư', 'Bad Boys', 'https://phimimg.com/upload/vod/20231023-1/4645e23c23d7ad3caccbf2c6c7ccbd2d.jpg', 'https://phimimg.com/upload/vod/20231023-1/30a9c71f3b9ab5ed6aa0906c840f863a.jpg', '<p>Hai viên cảnh sát Marcus Burnett (Martin Lawrence) và Mike Lowery (Will Smith) có 72 tiếng đồng hồ để truy tìm lại đống heroin trị giá 100 triệu đôla bị đánh cắp ngay trong sở cảnh sát của họ, trước khi họ bị thanh tra nội bộ túm gáy. Lowery càng dính líu sâu khi một người bạn của anh là nạn nhân của bọn buôn ma túy. Cả hai gặp thêm đủ rắc rối phiền hà khi phải thuyết phục một nữ nhân chứng cùng hợp tác...</p>', 'Full', 1, 'single', 'completed', 16, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Will Smith","avatar":""},{"name":"Martin Lawrence","avatar":""},{"name":"Téa Leoni","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Theresa Randle","avatar":""},{"name":"Marg Helgenberger","avatar":""},{"name":"Nestor Serrano","avatar":""},{"name":"Julio Oscar Mechoso","avatar":""},{"name":"Saverio Guerra","avatar":""},{"name":"Anna Levine Thomson","avatar":""},{"name":"Kevin Corrigan","avatar":""},{"name":"Michael Imperioli","avatar":""},{"name":"Lisa Boyle","avatar":""},{"name":"Michael Taliferro","avatar":""},{"name":"Emmanuel X","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324540);
