INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-phung-dich-thu', 'Kỳ Phùng Địch Thủ', 'Heat', 'https://phimimg.com/upload/vod/20231020-1/aefd2b8adab1d7951d95c51e5f1caea6.jpg', 'https://phimimg.com/upload/vod/20231020-1/c100c6a8acbeb4a52a1ee9828823a7c2.jpg', '<p>Một chiếc xe bọc thép chở tiền bị đánh cắp giữa thành phố Los Angeles. Ba nhân viên bảo vệ trên xe bị bắn chết. tẩu thoát ngay trước một rừng cảnh sát, bọn cướp không đả động tới tiền mặt, chỉ mang theo một đống trái phiếu trị giá 1,6 triệu đô la của Malibu Equity Investment, một công ty sản xuất vũ khí. Một tay cớm sừng sỏ của sở cảnh sát Los Angeles lần theo dấu vết và nhận ra, anh phải đối đầu với 1 tổ chức xã hội đen nguy hiểm, được cầm đầu bởi 1 tên trùm cũng sừng sỏ không kém.</p>', 'Full', 1, 'single', 'completed', 20, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Al Pacino","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Val Kilmer","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"Diane Venora","avatar":""},{"name":"Amy Brenneman","avatar":""},{"name":"Ashley Judd","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Wes Studi","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Tom Noonan","avatar":""},{"name":"Kevin Gage","avatar":""},{"name":"Hank Azaria","avatar":""},{"name":"Susan Traylor","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324540);
