INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-qua-cam', 'Trái Tim Quả Cảm', 'Braveheart', 'https://phimimg.com/upload/vod/20231015-1/f553c06cf87514785c262bb6d98cd572.jpg', 'https://phimimg.com/upload/vod/20231015-1/e963ba0fd203f7d7c690c5b0bfb51d7e.jpg', '<p>Trái tim dũng cảm (tên tiếng Anh: Braveheart) là bộ phim sử thi, hành động được công chiếu vào năm 1995 của đạo diễn kiêm diễn viên Mel Gibson. Bộ phim đề cập đến cuộc đời của hiệp sĩ William Wallace người đã lãnh đạo nhân dân Scotland đấu tranh giành độc lập trước sự đô hộ của nước Anh dưới triều đại của Vua Edward I của Anh (Người được biết đến với biệt hiệu chân dài) ở thế kỷ XIII</p>', 'Full', 1, 'single', 'completed', 17, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Catherine McCormack","avatar":""},{"name":"Sophie Marceau","avatar":""},{"name":"Patrick McGoohan","avatar":""},{"name":"Angus Macfadyen","avatar":""},{"name":"Brendan Gleeson","avatar":""},{"name":"James Robinson","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Sean McGinley","avatar":""},{"name":"Gerda Stevenson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324540);
