INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-toi-la-anh-hung', 'Cha Tôi Là Anh Hùng', 'My Father Is A Hero', 'https://phimimg.com/upload/vod/20231010-1/898de9bc5b278c20928f5511f868014b.jpg', 'https://phimimg.com/upload/vod/20231010-1/956871134d16807d4d5b617978f44472.jpg', '<p>Cuộc đời một cảnh sát chìm Trung Quốc do Jet Li thủ vai, gia đình anh rất vất vả, vợ ốm nặng, nhưng bù lại anh có một đứa con ngoan hiếu thảo và giỏi võ. Được cấp trên giao nhiệm vụ sang Hồng Kông thâm nhập một tổ chức XHĐ, những biến cố với cuộc đời anh bắt đầu. Vợ chết, con bị đe dọa, anh đã hy sinh rất nhiều để hoàn thành nhiệm vụ. Hãy xem phim để hiểu rõ hơn. Bộ phim kết thúc có hậu nhưng vẫn mang mác nỗi buồn lần niềm vui, trong một xã hội đang dần bị danh lợi chi phối, đâu đó vẫn có những con người luôn sống hết mình vì lý tưởng, vì xã hội.</p>', 'Full', 1, 'single', 'completed', 21, 1995, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Anita Mui","avatar":""},{"name":"Tse Miu","avatar":""},{"name":"Blackie Ko Shou-Liang","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Damian Lau","avatar":""},{"name":"Collin Chou","avatar":""},{"name":"Bonnie Fu","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Corey Yuen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324540);
