INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-mao-hiem-gia', 'Đại Mạo Hiểm Gia', 'Great Adventurers', 'null', 'https://phimimg.com/upload/vod/20231008-1/00f23e4df0150d74b22fced93d35b6a1.jpg', '<p>Andy còn nhỏ khi cha mẹ anh bị sát hại bởi một điệp viên hai mang ở Việt Nam, Ray Liu. Andy được người bạn thân nhất của bố nuôi dưỡng. Khi lớn lên, anh trở thành phi công còn Ray là một người đàn ông rất quyền lực và giàu có ở Việt Nam. Sau nỗ lực ám sát Ray không thành công, anh ta thu thập bằng chứng tội phạm của Ray Liu cho CIA ở Mỹ. Biết mối liên kết duy nhất của Ray chính là con gái ông. Trong khi giả làm trùm tội phạm để gây ấn tượng với Ray và gần gũi hơn với con gái mình, anh ta đã yêu con gái mình. Anh ta cũng có quan hệ tình cảm với tình nhân của Ray, Mona. Andy bối rối khi biết mình phải giết cha của người mình yêu thương nhất trên đời.</p>', 'Full', 1, 'single', 'completed', 34, 1995, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Rosamund Kwan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324540);
