INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thu-bong-dem', 'Kẻ Thù Bóng Đêm', 'Enemy Shadow', 'https://phimimg.com/upload/vod/20231006-1/c5c044fad2a8244c77e82b937af8b45b.jpg', 'https://phimimg.com/upload/vod/20231006-1/b5ae41e29a53bd798ca8c3ebb6b67519.jpg', '<p>Một cảnh sát mới phải chịu lửa khi bọn cướp ngân hàng giết chết người yêu của cô và cấp trên của cô ngay trước mặt cô và cô không bắn trả được. Cô quyết tâm trở nên cứng rắn và thô bạo rồi hoạt động bí mật.</p>', 'Full', 1, 'single', 'completed', 23, 1995, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jade Leung","avatar":""},{"name":"James Pax","avatar":""},{"name":"Kenneth Chan","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Ben Ngai-Cheung Ng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324540);
