INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-khuc-nua-dem', 'Điệp Khúc Nửa Đêm', 'The Phantom Lover', 'https://phimimg.com/upload/vod/20230926-1/35bb1da4a7715e6bf56f49a43812f914.jpg', 'https://phimimg.com/upload/vod/20230926-1/a4b50b559e224c38ff6ba9028aa593e7.jpg', '<p>Năm 1936 ở Trung Quốc, một đoàn kịch gần như phá sản bắt đầu biểu diễn trong một nhà hát bị đốt cháy, nơi nam diễn viên vĩ đại Song Danping bị giết. Một trong những diễn viên, Wei Qing, bắt đầu nhìn thấy những sự hiện ra kỳ lạ có thể hồi sinh đoàn kịch của anh ấy và đưa anh ấy vào số phận tương tự như Song Danping.</p>', 'Full', 1, 'single', 'completed', 24, 1995, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Leslie Cheung","avatar":""},{"name":"Wu Chien-Lien","avatar":""},{"name":"Liu Lin","avatar":""},{"name":"Roy Szeto","avatar":""},{"name":"Bao Fang","avatar":""},{"name":"Phillip Chung-Fung Kwok","avatar":""},{"name":"Yu Yankai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324540);
