INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-ma-than-thien', 'Con Ma Thân Thiện', 'Casper', 'https://phimimg.com/upload/vod/20230913-1/210dbdf38b85f1f204d0886c37fbfb49.jpg', 'https://phimimg.com/upload/vod/20230913-1/d67118b8cef50d13747d10b0835e7bc1.jpg', '<p>Casper là một hồn ma trẻ tốt bụng thường ám ảnh một biệt thự ở Maine. Khi chuyên gia James Harvey đến để liên lạc với Casper và những linh hồn đồng đội của anh, anh mang theo cô con gái tuổi teen của mình, Kat. Casper nhanh chóng yêu Kat, nhưng mối quan hệ mới chớm nở của họ trở nên phức tạp không chỉ bởi trạng thái trong suốt của anh mà còn bởi những người chú hiện hình gây rắc rối và những trò hề tinh nghịch của họ.</p>', 'Full', 1, 'hoathinh', 'completed', 34, 1995, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christina Ricci","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Malachi Pearson","avatar":""},{"name":"Cathy Moriarty","avatar":""},{"name":"Eric Idle","avatar":""},{"name":"Joe Alaskey","avatar":""},{"name":"Joe Nipote","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Chauncey Leopardi","avatar":""},{"name":"Spencer Vrooman","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324540);
