INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-dieu-dai-hiep', 'Thần Điêu Đại Hiệp', 'Return of The Condor Heroes', 'https://phimimg.com/upload/vod/20230911-1/6529643631bdf3a314dd006ea0bb6055.jpg', 'https://phimimg.com/upload/vod/20230911-1/991875626a4e975c95a989e9d04d280d.jpg', '<p>Thần điêu đại hiệp là bộ phim truyền hình do đài truyền hình TVB - Hồng Kông phát hành dựa trên tiểu thuyết cùng tên của nhà văn Kim Dung.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 36, 1995, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Louis Koo","avatar":""},{"name":"Carman Lee","avatar":""},{"name":"Gigi Fu Ming-Hin","avatar":""},{"name":"Theresa Lee Yee-Hung","avatar":""},{"name":"Jason Pai Piao","avatar":""},{"name":"Bonnie Ngai Chau-Wah","avatar":""},{"name":"Suet Lee","avatar":""},{"name":"Maggie Cheung Hoh-Yee","avatar":""},{"name":"Yiu-Cheung Lai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324540);
