INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-pha-hoai', 'Vua Phá Hoại', 'Love On Delivery', 'https://phimimg.com/uploads/movies/20260713/vua-pha-hoai-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/vua-pha-hoai-poster.webp', '<p>Hà Kim Ngân (do Châu Tinh Trì thủ vai), một anh chàng giao hàng nhút nhát và hiền lành, thường xuyên bị bắt nạt. Anh thầm yêu cô gái bán đồ hộp xinh đẹp tên A Lợi (Chung Lệ Đề), nhưng lại không dám bày tỏ. Một ngày nọ, anh bị một võ sĩ giỏi võ công tên Đoạn Thủy Lưu (Lâm Quốc Bân) hành hung ngay trước mặt A Lợi. Quá tủi nhục, Hà Kim Ngân quyết định tìm đến một võ sư ẩn dật tên Quỷ Vương Đạt (Ngô Mạnh Đạt) để học võ. Tuy nhiên, Quỷ Vương Đạt thực chất chỉ là một kẻ lừa đảo, không hề biết võ công, nhưng lại cố gắng "đào tạo" Hà Kim Ngân bằng những phương pháp kỳ lạ và hài hước.</p>', 'Full', 1, 'single', 'completed', 32, 1994, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Christy Chung Lai-Tai","avatar":""},{"name":"Ben Lam Kwok-Bun","avatar":""},{"name":"Joe Cheng Cho","avatar":""},{"name":"Billy Chow Bei-Lei","avatar":""},{"name":"Leo Ku Kui-Kei","avatar":""},{"name":"Wong Yat-Fei","avatar":""},{"name":"Vincent Kok Tak-Chiu","avatar":""},{"name":"Gabriel Wong Yat-Shan","avatar":""},{"name":"Peter Lai Bei-Dak","avatar":""},{"name":"Lee Lik-Chi","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Radium Cheung","avatar":""},{"name":"Philip Chan Yan-Kin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["King of Destruction","破坏之王","Poh waai ji wong","파괴지왕","주성치의 파괴지왕","破壞之王"]', 1784690324540);
