INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vua-pha-hoai', 'Vua Phá Hoại', 'Love On Delivery', 'vua phá hoại love on delivery stephen chow ng man-tat christy chung lai-tai ben lam kwok-bun joe cheng cho billy chow bei-lei leo ku kui-kei wong yat-fei vincent kok tak-chiu gabriel wong yat-shan peter lai bei-dak lee lik-chi paul chun pui radium cheung philip chan yan-kin châu tinh trì king of destruction 破坏之王 poh waai ji wong 파괴지왕 주성치의 파괴지왕 破壞之王', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-xam-loc-coc', 'Quan Xẩm Lốc Cốc', 'Hail The Judge', 'https://phimimg.com/uploads/movies/20260713/quan-xam-loc-coc-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/quan-xam-loc-coc-poster.webp', '<p>Hail The Judge có tựa đề tiếng việt là Quan Xẩm Lốc Cốc, được công chiếu vào năm 1994 và cũng là một trong những bộ phim xuất sắc nhất của ông trong khoảng thời gian đỉnh cao của sự nghiệp. Phim được chỉ đạo nội dung bởi đạo diễn lừng danh Vương Tinh, cùng sự tham gia của nhiều ngôi sao đình đám bên canh j cái tên Châu Tinh Trì như Trương Mẫn, Ngô Mạnh Đạt, Chung Lệ Đề,…
 Nội dung phim Quan Xẩm Lốc Cốc xoay quanh một vị quan huyện tham lam xấu xa và nhận hối lộ do Châu Tinh Trì thủ vai. Nhưng một ngày nọ,ông ta gặp một vị trạng sư tài ba tên Phương Đường Kính hiện là đệ nhất trạng sư Quãng Đông, ông ta mau chóng tìm được điểm yếu của vị tham quan và làm cho vị quan thân bại danh liệt. Sau khi đã nhận ra lỗi lầm của mình, vị tham quan quyết tâm quay lại trở thành người tốt và lật đổ Phương Đường Kính một cách ngoạn mục.</p>', 'Full', 1, 'single', 'completed', 36, 1994, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Sharla Cheung","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Lawrence Ng Kai-Wah","avatar":""},{"name":"Ada Choi Siu-Fan","avatar":""},{"name":"Collin Chou","avatar":""},{"name":"Ku Feng","avatar":""},{"name":"Christy Chung Lai-Tai","avatar":""},{"name":"Joey Leung Wing-Chung","avatar":""},{"name":"Ng Wui","avatar":""},{"name":"Teresa Ha Ping","avatar":""},{"name":"Jimmy Au Shui-Wai","avatar":""},{"name":"Lo Hung","avatar":""},{"name":"Wong Yat-Fei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เปาบุ้นจิ้นหน้าขาว","구품지마관","九品芝麻官","九品芝麻官之白面包青天","Quan Xẩm Lốc Cốc"]', 1784690324540);
