INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quoc-san-007', 'Quốc Sản 007', 'From Beijing With Love', 'https://phimimg.com/uploads/movies/20260713/quoc-san-007-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/quoc-san-007-poster.webp', '<p>Phim Quốc Sản 007 là một bộ phim hài, hành động của Châu Tinh Trì dựa theo bộ phim Điệp viên 007 James Bond của Mỹ. Trong phim này, bạn sẽ thấy Châu Tinh Trì vào vai một điệp viên với nhiệm vụ truy tìm một kho báu. Lý do duy nhất khiến anh được cấp trên cử đi thực hiện là bởi anh không có tài nhưng lại cực kì may mắn. Liệu Châu Tinh Trì có hoàn thành được nhiệm vụ không?</p>', 'Full', 1, 'single', 'completed', 41, 1994, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Anita Yuen Wing-Yee","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Pauline Chan Bo-Lin","avatar":""},{"name":"Joe Cheng Cho","avatar":""},{"name":"Wong Kam-Kong","avatar":""},{"name":"Wong Yat-Fei","avatar":""},{"name":"Lee Lik-Chi","avatar":""},{"name":"Johnny Tang Siu-Chun","avatar":""},{"name":"Leung See-Ho","avatar":""},{"name":"Lee Kin-Yan","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Raymond Tsang Chau-Ming","avatar":""},{"name":"Yip Chun","avatar":""},{"name":"Jerry Koo Ming-Wah","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gwok chaan Ling Ling Chat","國產凌凌漆","007 북경특급","Liebesgrüsse aus Peking","国产凌凌漆","国产007","From Beijing with Love"]', 1784690324540);
