INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quoc-san-007', 'Quốc Sản 007', 'From Beijing With Love', 'quốc sản 007 from beijing with love stephen chow anita yuen wing-yee law kar-ying pauline chan bo-lin joe cheng cho wong kam-kong wong yat-fei lee lik-chi johnny tang siu-chun leung see-ho lee kin-yan yu rongguang raymond tsang chau-ming yip chun jerry koo ming-wah châu tinh trì gwok chaan ling ling chat 國產凌凌漆 007 북경특급 liebesgrüsse aus peking 国产凌凌漆 国产007 from beijing with love', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-thieu-hong-lien-tu', 'Hỏa Thiêu Hồng Liên Tự', 'Burning Paradise', 'https://phimimg.com/upload/vod/20260605-1/6077a248b60ee72e17b51a5b87e6ca19.jpg', 'https://phimimg.com/upload/vod/20260605-1/5f9abf271de7b4c73110f38a3ff488ee.jpg', '<p>Lấy bối cảnh trong triều đại nhà Thanh, nội dung của phim Burning Paradise in Hell xoay quanh vị anh hùng võ thuật Phương Thế Ngọc ( Lí Thiên Sênh), người đang bị truy đuổi bởi những quân lính của triều đình. Trong quá trình trốn chạy, chàng trai trẻ bắt gặp và kết bạn với một kỹ nữ vừa trốn thoát ra khỏi lầu xanh tên là Tou-Tou (Lý Nhược Đồng), nhưng cả hai bị bắt và đưa đến Hồng Liên Tự, nơi đáng sợ nhất kể từ Đền Doom. Đó là nơi mà những người xấu được cầm đầu bởi một tay cướp nổi tiếng tàn ác (Wong Kam-Kong) khủng bố mọi người bằng cách xé toạc đầu của phụ nữ và vẽ những thứ đáng sợ trên tường. Sau đó là rất nhiều những trận chiến diễn ra, liệu rằng ai sẽ là người chiến thắng cuối cùng.</p>', 'Full', 1, 'single', 'completed', 38, 1994, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Willie Chi Tin-Sang","avatar":""},{"name":"Carman Lee Yeuk-Tung","avatar":""},{"name":"John Ching Tung","avatar":""},{"name":"Maggie Lam Chuen","avatar":""},{"name":"Yang Sheng","avatar":""},{"name":"Yuen Gam-Fai","avatar":""},{"name":"Wong Kam-Kong","avatar":""},{"name":"Wu Xiqian","avatar":""},{"name":"Li Ji","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Le Temple du Lotus Rouge","Burning Paradise in Hell","火燒紅蓮寺","Burning Paradise","新火烧红莲寺","The Rape of the Red Temple","O Templo Vermelho"]', 1784690324540);
