INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phong-cap-cuu-phan-1', 'Phòng Cấp Cứu (Phần 1)', 'ER (Season 1)', 'phòng cấp cứu (phần 1) er (season 1) maura tierney parminder nagra linda cardellini scott grimes david lyons angela bassett john stamos plantão médico 急诊室的故事 急诊室的春天 emergency room e.r. - emergency room er', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tu-shawshank', 'Nhà Tù Shawshank', 'The Shawshank Redemption', 'https://phimimg.com/upload/vod/20260410-1/fb9841d4285d99e4f525ba3adead96b8.jpg', 'https://phimimg.com/upload/vod/20260410-1/3566656647a560cf62a64bdd6a3c2a5d.jpg', '<p>Nhà tù Shawshank kể về Andrew, một nhân viên nhà băng, bị kết án chung thân sau khi giết vợ và nhân tình của cô. Anh một mực cho rằng mình bị oan. Andy bị đưa tới nhà tù Shawshank. Tại đây, thế giới ngầm của các phạm nhân, sự hà khắc của hệ thống quản giáo xung đột và giành nhau quyền thống trị. Chỉ có các phạm nhân trung lập là bị kẹt ở giữa và có thể bỏ mạng. Làm quen với tay ‘quản lý chợ đen’ Redding, Andy dần thích nghi với cuộc sống tại Shawshank. Song, kế hoạch lớn hơn việc tồn tại ở nhà tù này đang được anh suy tính. Qua con mắt và lời kể của Redding, cuộc vượt ngục vĩ đại này được kể tuần tự cùng một kết thúc bất ngờ</p>', 'Full', 1, 'single', 'completed', 23, 1994, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tim Robbins","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Bob Gunton","avatar":""},{"name":"William Sadler","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Gil Bellows","avatar":""},{"name":"James Whitmore","avatar":""},{"name":"Mark Rolston","avatar":""},{"name":"Jeffrey DeMunn","avatar":""},{"name":"Larry Brandenburg","avatar":""},{"name":"Neil Giuntoli","avatar":""},{"name":"Brian Libby","avatar":""},{"name":"David Proval","avatar":""},{"name":"Joseph Ragno","avatar":""},{"name":"Jude Ciccolella","avatar":""},{"name":"Paul McCrane","avatar":""},{"name":"Renee Blaine","avatar":""},{"name":"Scott","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Rita Hayworth - nyckel till flykten","肖申克的救赎","Gaqceva shoushenkidan","Şouşenkdən qaçış","Искупление Шоушенком","Shoushenkden Qacish","Rastgari Dar Shawshank","Homot Shel Tikva","Shôshanku no sora ni","Бекство из Шошенка","쇼생크 탈출","Les Évadés","Skazani na Shawshank","ショーシャンクの空に：1994","رستگاری در شاوشنگ","쇼생크탈출","Um Sonho de Liberdade","刺激1995","Փախուստ Շոուշենքից","Sueño de Libertad","Выкупленне з Шаўшэнку","شاوشانك ريديمبشن","Bēgšana no Saušenkas","Brīvības cena","The Shawshank Redemption"]', 1784690324540);
