INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-tu-shawshank', 'Nhà Tù Shawshank', 'The Shawshank Redemption', 'nhà tù shawshank the shawshank redemption tim robbins morgan freeman bob gunton william sadler clancy brown gil bellows james whitmore mark rolston jeffrey demunn larry brandenburg neil giuntoli brian libby david proval joseph ragno jude ciccolella paul mccrane renee blaine scott rita hayworth - nyckel till flykten 肖申克的救赎 gaqceva shoushenkidan şouşenkdən qaçış искупление шоушенком shoushenkden qacish rastgari dar shawshank homot shel tikva shôshanku no sora ni бекство из шошенка 쇼생크 탈출 les évadés skazani na shawshank ショーシャンクの空に：1994 رستگاری در شاوشنگ 쇼생크탈출 um sonho de liberdade 刺激1995 փախուստ շոուշենքից sueño de libertad выкупленне з шаўшэнку شاوشانك ريديمبشن bēgšana no saušenkas brīvības cena the shawshank redemption', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuy-quyen-2', 'Túy Quyền 2', 'The Legend Of Drunken Master', 'https://phimimg.com/upload/vod/20260408-1/32224ab9aa0f453a0ef9a73b1de116e6.jpg', 'https://phimimg.com/upload/vod/20260408-1/35b57c8ad99a535a1ff21f7261fb6f01.jpg', '<p>Cùng cha trở về nhà, Hoàng Phi Hồng mắc kẹt vào giữa hai trận tuyến, một bên là bọn buôn lậu đồ cổ người phương Tây, bên kia là những người bảo vệ cổ vật. Lúc này Phi Hồng đã là một cao thủ túy quyền nhưng người cha luôn tìm cách cấm cản vì sợ anh dấn sâu vào giang hồ hiểm ác lắm chuyện thị phi. Hoàng Phi Hồng sẽ không chỉ phải tìm cách chặn tay bọn buôn lậu nước ngoài, mà còn phải vượt qua được định kiến và sự cấm đoán của người cha vô cùng nghiêm khắc</p>', 'Full', 1, 'single', 'completed', 20, 1994, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Ti Lung","avatar":""},{"name":"Anita Mui Yim-Fong","avatar":""},{"name":"Ram Chiang Chi-Kwong","avatar":""},{"name":"Lau Kar-Leung","avatar":""},{"name":"Ken Lo Wai-Kwong","avatar":""},{"name":"Pak Ho-Sung","avatar":""},{"name":"Felix Wong Yat-Wah","avatar":""},{"name":"Hoh Wing-Fong","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Lau Kar-Yung","avatar":""},{"name":"Yvonne Yung Hung","avatar":""},{"name":"Suki Kwan Sau-Mei","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Vindy Chan Wai-Yee","avatar":""},{"name":"Wong San","avatar":""},{"name":"Alan C","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jui kuen II","Ivresse au combat","Drunken Master  II","醉拳II","醉拳二","Sui ken 2","Drunken Master 2","Grothies kai diamantia","Zui quan II","醉拳2","Legend of the Drunken Master","A Lenda do Mestre Invencível 2","酔拳2"]', 1784690324540);
