INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-den-1994', 'Quạ Đen', 'The Crow', 'https://phimimg.com/upload/vod/20260207-1/60f718c19649b7284a00176a380c36ab.jpg', 'https://phimimg.com/upload/vod/20260207-1/2807a7f38f69d76b0ab70f1b9c5365ae.jpg', '<p>Đêm trước đám cưới, nhạc sĩ Eric Draven (Brandon Lee) và vị hôn thê của anh bị các thành viên của một băng đảng nội thành bạo lực sát hại dã man. Vào ngày giỗ của họ, Eric sống lại từ nấm mồ và khoác lên mình chiếc áo choàng gothic của Quạ, một kẻ báo thù siêu nhiên. Truy tìm những tên côn đồ chịu trách nhiệm về tội ác và giết chúng không thương tiếc, Eric cuối cùng phải đối mặt với trùm xã hội đen Top Dollar (Michael Wincott) để hoàn thành nhiệm vụ rùng rợn của mình.</p>', 'Full', 1, 'single', 'completed', 17, 1994, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brandon Lee","avatar":""},{"name":"Rochelle Davis","avatar":""},{"name":"Ernie Hudson","avatar":""},{"name":"Michael Wincott","avatar":""},{"name":"Bai Ling","avatar":""},{"name":"Sofia Shinas","avatar":""},{"name":"Anna Thomson","avatar":""},{"name":"David Patrick Kelly","avatar":""},{"name":"Angel David","avatar":""},{"name":"Laurence Mason","avatar":""},{"name":"Michael Massee","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Jon Polito","avatar":""},{"name":"Bill Raymond","avatar":""},{"name":"Marco Rodríguez","avatar":""},{"name":"Kim Sykes","avatar":""},{"name":"Rock Taulbee","avatar":""},{"name":"Norman Max M","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Il Corvo 1 - The Crow","O Corvo","Ölümsüz Aşk","Le Corbeau","کلاغ","The Crow"]', 1784690324540);
