INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-song-hung-du', 'Dòng Sông Hung Dữ', 'The River Wild', 'https://phimimg.com/upload/vod/20260123-1/a18b6cd4a64e2af671553b824165aa58.jpg', 'https://phimimg.com/upload/vod/20260123-1/8de1f1ca0372e8cde70b91836caf95fd.jpg', '<p>Tom Hartman có một gia đình hạnh phúc với vợ là Gail Hartman và cậu con trai Rourke. Trong một kỳ nghỉ họ quyết định thám hiểm một dòng sông bằng xuồng. Tại đây họ gặp hai gã cướp ngân hàng đang trên đường trốn chạy. Sau khi cho hai kẻ này đi nhờ xuồng họ bị chúng bắt cóc làm con tin. Liệu Tom có thể mưu trí cứu vợ và con mình?</p>', 'Full', 1, 'single', 'completed', 19, 1994, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Meryl Streep","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"Joseph Mazzello","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"William Lucking","avatar":""},{"name":"Stephanie Sawyer","avatar":""},{"name":"Elizabeth Hoffman","avatar":""},{"name":"Victor Galloway","avatar":""},{"name":"Diane Delano","avatar":""},{"name":"Thomas F. Duffy","avatar":""},{"name":"Paul Cantelon","avatar":""},{"name":"Glenn Morshower","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["狂野之河","Am wilden Fluß","Dzika Rzeka","O Rio Selvagem","The River Wild"]', 1784690324540);
