INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-flintstones', 'Gia Đình Flintstones', 'The Flintstones', 'https://phimimg.com/upload/vod/20260122-1/29b852af14f0b609b44c8efcf3aaddee.jpg', 'https://phimimg.com/upload/vod/20260122-1/04b945fddd576fe5f971346c23cc9e36.jpg', '<p>Trong một thế giới thời kỳ đồ đá tồn tại song song với hiện đại, Fred Flintstone nhờ bạn giúp đỡ mà bất ngờ trở thành giám đốc một công ty lớn và nhanh chóng tận hưởng cuộc sống giàu sang. Mải mê với danh vọng, anh dần phớt lờ lời khuyên của bạn bè và người vợ Wilma. Không hay biết mình bị ông chủ thao túng, Fred bị lôi kéo vào những việc sai trái và còn bị bồ nhí của hắn tìm cách quyến rũ. Chỉ đến khi nhận ra sự thật, Fred mới hiểu rằng mình đã đánh đổi quá nhiều cho giấc mơ giàu có.</p>', 'Full', 1, 'single', 'completed', 25, 1994, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"John Goodman","avatar":""},{"name":"Elizabeth Perkins","avatar":""},{"name":"Rick Moranis","avatar":""},{"name":"Rosie O''Donnell","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Elizabeth Taylor","avatar":""},{"name":"Dann Florek","avatar":""},{"name":"Richard Moll","avatar":""},{"name":"Irwin Keyes","avatar":""},{"name":"Jonathan Winters","avatar":""},{"name":"Harvey Korman","avatar":""},{"name":"Lainey Silver","avatar":""},{"name":"Melanie Silver","avatar":""},{"name":"Hlynur Sigurðsson","avatar":""},{"name":"Marinó Sigurðss","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["The Flintstones","Os Flintstones - O Filme","Los Picapiedra","Fred Flinta är här igen","摩登原始人之摔跤赛攻击波","Os Flintstones","The Flintstones - Die Familie Feuerstein","新聰明笨伯"]', 1784690324540);
