INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-troi-1994', 'Cổng Trời', 'Stargate', 'https://phimimg.com/upload/vod/20260105-1/f8d284c9073a24ac1ca4fa88fc21e9f9.jpg', 'https://phimimg.com/upload/vod/20260105-1/a93e5fd8c0535f51151489267372d4b6.jpg', '<p>Hành trình phiêu lưu khoa học viễn tưởng mang tên Stargate sẽ đưa bạn đến một thế giới huyền bí, nơi những bí ẩn cổ đại của Ai Cập được kết nối với những khám phá ngoài vũ trụ. Tìm thấy trong thời đại pharaon, cổng thiên văn khổng lồ – Stargate – là một công trình thần kỳ với khả năng dịch chuyển giữa các vì sao. Bằng cách sử dụng thiết bị này, một đội quân tinh nhuệ, gồm những nhà khoa học, quân nhân và một nhà Ai Cập học, sẽ được dẫn dắt đến một hành tinh xa xăm, nơi con người sinh sống giống hệt như kỹ nghệ cổ đại Ai Cập.</p>', 'Full', 1, 'single', 'completed', 20, 1994, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Spader","avatar":""},{"name":"Kurt Russell","avatar":""},{"name":"Jaye Davidson","avatar":""},{"name":"Viveca Lindfors","avatar":""},{"name":"Alexis Cruz","avatar":""},{"name":"Mili Avital","avatar":""},{"name":"Erick Avari","avatar":""},{"name":"John Diehl","avatar":""},{"name":"Djimon Hounsou","avatar":""},{"name":"Carlos Lauchu","avatar":""},{"name":"Leon Rippy","avatar":""},{"name":"French Stewart","avatar":""},{"name":"Derek Webster","avatar":""},{"name":"Christopher John Fields","avatar":""},{"name":"Gianin Loffler","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Rae Allen","avatar":""},{"name":"Rich","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởn