INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-gia-tuyet', 'Ông Già Tuyết', 'The Santa Clause', 'https://phimimg.com/upload/vod/20251214-1/53d066e41c9f6c989991a2d78183e00e.jpg', 'https://phimimg.com/upload/vod/20251214-1/f903e5cd35e0ac274bba6869f6be4671.jpg', '<p>Vào đêm Giáng sinh, ông bố đã ly hôn Scott Calvin và con trai phát hiện ra ông già Noel đã bị ngã khỏi mái nhà của họ.&nbsp; Khi Scott cầm dây cương của cỗ xe tuần lộc phép thuật, anh nhận ra rằng mình đã trở thành ông già Noel mới, và phải thuyết phục một thế giới đầy những người không tin vào phép màu, bao gồm cả chính bản thân anh.</p>', 'Full', 1, 'single', 'completed', 15, 1994, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tim Allen","avatar":""},{"name":"Judge Reinhold","avatar":""},{"name":"Wendy Crewson","avatar":""},{"name":"Eric Lloyd","avatar":""},{"name":"David Krumholtz","avatar":""},{"name":"Larry Brandenburg","avatar":""},{"name":"Mary Gross","avatar":""},{"name":"Paige Tamada","avatar":""},{"name":"Peter Boyle","avatar":""},{"name":"Judith Scott","avatar":""},{"name":"Jayne Eastwood","avatar":""},{"name":"Melissa King","avatar":""},{"name":"Bradley Wentworth","avatar":""},{"name":"Azura Bates","avatar":""},{"name":"Joshua Satok","avatar":""},{"name":"Zachary McLemore","avatar":""},{"name":"Joyce Guy","avatar":""},{"name":"Lindsay","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La Santa Cláusula","Nu är det jul igen"