INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-gia-tuyet', 'Ông Già Tuyết', 'The Santa Clause', 'ông già tuyết the santa clause tim allen judge reinhold wendy crewson eric lloyd david krumholtz larry brandenburg mary gross paige tamada peter boyle judith scott jayne eastwood melissa king bradley wentworth azura bates joshua satok zachary mclemore joyce guy lindsay la santa cláusula nu är det jul igen 산타클로스 the santa clause 1 santa clause 1 圣诞快乐又疯狂 the santa clause', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-na-xanh', 'Mặt Nạ Xanh', 'The Mask', 'https://phimimg.com/upload/vod/20251104-1/154966f7a1cb1eed3451fb4cbe019e72.jpg', 'https://phimimg.com/upload/vod/20251104-1/94f71023b94a8b3279ee2728202e3245.jpg', '<p>Câu chuyện vui nhộn về anh chàng nhân viên ngân hàng Stanley Ipkiss nhút nhát, vụng về. Kể từ khi tình cờ tìm thấy chiếc mặt nạ của Chúa tể bóng đêm Loki, cuộc đời Ipkiss thay đổi hoàn toàn. Anh chàng có những khả năng siêu tưởng điên rồ như biến đổi cơ thể, bay nhảy lung tung, dọa nạt mọi người và nhiều câu chuyện hài hước khác…</p>', 'Full', 1, 'single', 'completed', 16, 1994, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jim Carrey","avatar":""},{"name":"Peter Riegert","avatar":""},{"name":"Peter Greene","avatar":""},{"name":"Amy Yasbeck","avatar":""},{"name":"Richard Jeni","avatar":""},{"name":"Orestes Matacena","avatar":""},{"name":"Tim Bagley","avatar":""},{"name":"Nancy Fish","avatar":""},{"name":"Johnny Williams","avatar":""},{"name":"Reg E. Cathey","avatar":""},{"name":"Jim Doughan","avatar":""},{"name":"Denis Forest","avatar":""},{"name":"Cameron Diaz","avatar":""},{"name":"Joseph Alfieri","avatar":""},{"name":"B.J. Barie","avatar":""},{"name":"Catherine Berge","avatar":""},{"name":"Philip Boardman","avatar":""},{"name":"Krista Buo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["La maschera","Jim Carrey''s Die Maske - Vom Loser zum Helden","Die Maske - Von Null auf Held","La Mascara: La película","Jim Carrey''s D