INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cuoc-phieu-luu-cua-sherlock-holmes-phan-7', 'Những Cuộc Phiêu Lưu Của Sherlock Holmes (Phần 7)', 'Sherlock Holmes (Season 7)', 'https://phimimg.com/upload/vod/20251026-1/44c27c86ab9f4d6fbc77a8cfc884b354.jpg', 'https://phimimg.com/upload/vod/20251026-1/6527f87b7026ab82e17803146fcd7ffa.jpg', '<p>Sherlock Holmes sử dụng khả năng của mình để giải quyết các vụ án của khách hàng tư nhân và những vụ án mà Scotland Yard không thể giải quyết, cùng với người bạn của ông là Tiến sĩ Watson.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 20, 1994, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jeremy Brett","avatar":""},{"name":"Edward Hardwicke","avatar":""},{"name":"Rosalie Williams","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["福尔摩斯冒险史","福尔摩斯探案集之福尔摩斯冒险史","福尔摩斯历险记","the Adventures of Sherlock Holmes","Sherlock Holmes","The Adventures of Sherlock Holmes","Σέρλοκ Χολμς","Οι περιπέτειες του Σέρλοκ Χολμς","הרפתקאותיו של שרלוק הולמס","셜록 홈즈의 모험","셜록홈즈의 모험","셜록 홈즈의 회상","셜록홈즈의 회상","셜록 홈즈의 귀환","셜록홈즈의 귀환","셜록 홈즈의 사건집","셜록홈즈의 사건집","셜록 홈즈","Приключения Шерлока Холмса","شرلوك هولمز"]', 1784690324540);
