INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-cuoc-phieu-luu-cua-sherlock-holmes-phan-7', 'Những Cuộc Phiêu Lưu Của Sherlock Holmes (Phần 7)', 'Sherlock Holmes (Season 7)', 'những cuộc phiêu lưu của sherlock holmes (phần 7) sherlock holmes (season 7) jeremy brett edward hardwicke rosalie williams 福尔摩斯冒险史 福尔摩斯探案集之福尔摩斯冒险史 福尔摩斯历险记 the adventures of sherlock holmes sherlock holmes the adventures of sherlock holmes σέρλοκ χολμς οι περιπέτειες του σέρλοκ χολμς הרפתקאותיו של שרלוק הולמס 셜록 홈즈의 모험 셜록홈즈의 모험 셜록 홈즈의 회상 셜록홈즈의 회상 셜록 홈즈의 귀환 셜록홈즈의 귀환 셜록 홈즈의 사건집 셜록홈즈의 사건집 셜록 홈즈 приключения шерлока холмса شرلوك هولمز', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-vuong-doat-ngoi', 'Cửu Vương Đoạt Ngôi', 'Secret Battle of the Majesty', 'https://phimimg.com/upload/vod/20251023-1/0cb6701fe09fb18ebaac8076daf00616.jpg', 'https://phimimg.com/upload/vod/20251023-1/f98a238843ae82837fcdbfa9b4d57531.jpg', '<p>Khang Hy Thanh triều có 9 người con trai tính tình khác biệt và có mưu chước lên ngôi báu, Khang Hy có thành kiến với Tứ A Ca Dận Chân, tuy Chân có tài. Khang Hy thương yêu đại thái tử Dận Nhưng, làm cho Nhưng ngang ngược lộng quyền, hành hạ Dận Chân đến nổi Chân như điên như khùng, hãm hiếp Miêu Hân và bị Khang Hy bỏ tù. Khang Hy khi bệnh nằm trên giường được tin Dận Chinh chiến thắng ngoài biên cương định lập di chiếu truyền ngôi cho Chinh. Dận Chân biết được giết cha và sửa thánh chỉ để lên ngôi. Chinh được tin trở về muốn đối kháng với Chân nhưng đã quá muộn, còn các hoàng tử khác đều bị kiềm chế. Chân lên ngôi lấy hiệu Ung Chính và trở thành nhất đại bá chủ</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 17, 1994, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Kwong Wa","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Pat Poon","avatar":""},{"name":"Lawrence Yan Chi-Keung","avatar":""},{"name":"Annie Man Chung-Han","avatar":""},{"name":"Berg Ng Ting-Yip","avatar":""},{"name":"Erica Choi Hiu-Yee","avatar":""},{"name":"Wong Wan-Choi","avatar":""},{"name":"Gam San","avatar":""},{"name":"Ma Chung-Tak","avatar":""},{"name":"Suk-Ching Au","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["君临天下之九龙夺嫡","九王夺位","君临天下之九龙夺位","Secret Battle of the Majesty","君臨天下"]', 1784690324540);
