INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuu-vuong-doat-ngoi', 'Cửu Vương Đoạt Ngôi', 'Secret Battle of the Majesty', 'cửu vương đoạt ngôi secret battle of the majesty elvis tsui kam-kong kwong wa kent tong pat poon lawrence yan chi-keung annie man chung-han berg ng ting-yip erica choi hiu-yee wong wan-choi gam san ma chung-tak suk-ching au 君临天下之九龙夺嫡 九王夺位 君临天下之九龙夺位 secret battle of the majesty 君臨天下', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-thieu-nien-na-tra', 'Thanh Thiếu Niên Na Tra', 'Rebels Of The Neon God', 'https://phimimg.com/upload/vod/20251014-1/69123298f1ec54093920788776670696.jpg', 'https://phimimg.com/upload/vod/20251014-1/c1e30b67e53472291f0cf91b89bb7180.jpg', '<p>Phim kể về Tiểu Khang, một cậu học sinh áp lực bị cha mẹ ép học thêm liên tục. Một ngày, sau khi bỏ trốn khỏi lớp học thêm và mang theo tiền hoàn phí, cậu bắt đầu lang thang vô định ở khu Tây Môn Đình – nơi đầy màu sắc của giới trẻ Đài Bắc.Tại đây, Tiểu Khang gặp A Trạch – một “thanh niên hư hỏng” sống buông thả bên ngoài nhưng cô độc bên trong. Bị thu hút bởi vẻ tự do của A Trạch, Tiểu Khang khao khát hòa nhập vào thế giới ấy, song dần nhận ra rằng đằng sau vẻ hào nhoáng là nỗi trống rỗng và cô đơn sâu sắc.Trong quá trình dõi theo A Trạch, Tiểu Khang bắt đầu nhận ra xu hướng giới tính khác biệt của mình, đồng thời cũng thấy được sự lặp lại, bế tắc của cuộc sống A Trạch. Dẫu vậy, A Trạch vẫn có bạn bè bên cạnh – A Bân và bạn gái A Quế, giúp anh có chút ấm áp trong chuỗi ngày “đến đâu hay đến đó”.</p>', 'Full', 1, 'single', 'completed', 20, 1994, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Lý Khang Sinh","avatar":""},{"name":"Trần Chiêu Vinh","avatar":""},{"name":"Vương Du Văn","avatar":""},{"name":"Lục Di Tĩnh","avatar":""},{"name":"Miêu Thiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qing shao nian nuo zha","Rebellen im Neonlicht","Rebeldes do Deus Neon","Επαναστάτες του ηλεκτρικού θεού","Neonisten gyermekei","Buntownicy neonowego boga","Os Rebeldes do Deus Neon","Les Rebelles du dieu néon","Youth","Rebels of the Neon God","青少年哪吒"]', 1784690324540);
