INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-thieu-nien-na-tra', 'Thanh Thiếu Niên Na Tra', 'Rebels Of The Neon God', 'thanh thiếu niên na tra rebels of the neon god lý khang sinh trần chiêu vinh vương du văn lục di tĩnh miêu thiên qing shao nian nuo zha rebellen im neonlicht rebeldes do deus neon επαναστάτες του ηλεκτρικού θεού neonisten gyermekei buntownicy neonowego boga os rebeldes do deus neon les rebelles du dieu néon youth rebels of the neon god 青少年哪吒', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-xa-dieu', 'Anh Hùng Xạ Điêu', 'The Legend of the Condor Heroes', 'https://phimimg.com/upload/vod/20251012-1/446b505b420e00b10c36e0ac6d380fd8.jpg', 'https://phimimg.com/upload/vod/20251012-1/c31e1603efb3023cf68a43d99bcfcde2.jpg', '<p>Hoàng Dung là con gái của đảo chủ đảo Đào Hoa, Đông Tà Hoàng Dược Sư và Phùng Thị Mai Hương. Nàng mồ côi mẹ từ nhỏ và được cha nuôi nấng, truyền thụ võ nghệ. Tính cách Hoàng Dung khá giống với cha mình, nàng thông minh, nhanh trí, nhiều mưu kế nhưng cũng rất điêu ngoa, cổ quái, thường làm việc theo ý mình. Hoàng Dung vô cùng xinh đẹp nhưng võ công rất cao, trên người lại mặc Nhuyễn Vị Giáp khiến cho những kẻ háo sắc không thể đến gần. Môn võ công nổi tiếng của nàng là Đả Cẩu Bổng Pháp. Một lần Hoàng Dược Sư mắng nàng, Hoàng Dung liền bỏ đi. Trên đường đi nàng cải trang thành thằng bé ăn mày và gặp gỡ Quách Tĩnh. Hoàng Dung nhanh chóng bị thu hút bởi sự tốt bụng, thật thà, chất phác, lương thiện của Quách Tĩnh. Nàng đã sắp xếp cho Quách Tĩnh học võ công của Bắc Cái Hồng Thất Công. Bản thân nàng cũng học quyền pháp Tiêu Dao Du từ vị tiền bối này. Trên quá trình hành tẩu giang hồ, Hoàng Dung và Quách Tĩnh đã trải qua rất nhiều sóng gió, có lúc bị thương nặng, có lúc lạc nhau hàng tháng trời. Sau cùng hai người cũng vượt qua kết làm phu thê. Hoàng Dung là bang chủ đời thứ 19 của Cái Bang.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 20, 1994, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Julian Cheung Chi-Lam","avatar":""},{"name":"Athena Chu Yan","avatar":""},{"name":"Gallen Lo Ka-Leung","avatar":""},{"name":"Emily Kwan Bo-Wai","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Wayne Lai Yiu-Cheung","avatar":""},{"name":"Danny Lau Dan","avatar":""},{"name":"Chu Tit-Wo","avatar":""},{"name":"Vincent Lam Wai","avatar":""},{"name":"Dominic Lam Ka-Wah","avatar":""},{"name":"Savio Tsang","avatar":""},{"name":"Leung Yuen-Jing","avatar":""},{"name":"Lily Ng Lai-Chu","avatar":""},{"name":"Lau Kong","avatar":""},{"name":"Ben Wong","avatar":""},{"name":"Joa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["射雕英雄传张智霖版","射雕英雄传","射雕英雄传 1994","She Diao Ying Xiong Zhuan","射雕英雄傳","사조영웅전","The Legend of the Condor Heroes","The Legend of the Condor Heroes 1994"]', 1784690324540);
