INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-gau-truc', 'Cuộc Chiến Gấu Trúc', 'Pom Poko', 'cuộc chiến gấu trúc pom poko makoto nonomura nijiko kiyokawa shigeru izumiya norihei miki yuriko ishida megumi hayashibara yumi ichihara akira kamiya takehiro murata gannosuke ashiya kosan yanagiya shinchou kokontei bunshi katsura vi beichou katsura akira fukuzawa haya la guerra de los mapaches the raccoon war heisei tanuki gassen ponpoko 歡喜碰碰狸 heisei-era raccoon dog war ponpoko i antepithesi ton raccoon milhemet hadvivonim bойна тануки в периоды хэйсэй и помпоко 百变狸猫 la guerra de los mapaches de pompoko війна тануки в періоди хейсей і помпоко понпоко: війна танукі в період хейсей пом поко помпоко 百變狸貓 pompoko the racoon war pompoko: a grande batalha dos guaxinins pom poko 平成狸合戦ぽんぽこ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hong-sung-vo-hinh-3', 'Họng Súng Vô Hình 3', 'Naked Gun 33⅓: The Final Insult', 'https://phimimg.com/upload/vod/20250712-1/eddb1a7eae1fb0bd7308bdda9fbb6ee5.jpg', 'https://phimimg.com/upload/vod/20250712-1/9fe7db8d8a61c56c2cb91705eb1144e9.jpg', '<p>The Naked Gun là loạt phim hành động hài hước với sự tham gia của dàn diễn viên Leslie Nielsen, Priscilla Presley, George Kennedy và O. J. Simpson, bao gồm 3 phần từ năm 1988 tới năm 1994. Loạt phim khá thành công bởi phong cách nhái phim điệp viên, nhái những nhân vật nổi tiếng và những câu nói nổi tiếng, là đại diễn tiêu biểu của thể loại parody cổ điển. Nếu bạn đã chán ngấy với những bộ phim hài rẻ tiền gần đây thì khi xem lại loạt phim này chắc chắn sẽ đem lại cho bạn những nụ cười sảng khoái.</p>', 'Full', 1, 'single', 'completed', 16, 1994, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Leslie Nielsen","avatar":""},{"name":"Priscilla Presley","avatar":""},{"name":"George Kennedy","avatar":""},{"name":"O. J. Simpson","avatar":""},{"name":"Fred Ward","avatar":""},{"name":"Kathleen Freeman","avatar":""},{"name":"Anna Nicole Smith","avatar":""},{"name":"Ellen Greene","avatar":""},{"name":"Ed Williams","avatar":""},{"name":"Raye Birk","avatar":""},{"name":"Matt Roe","avatar":""},{"name":"Wylie Small","avatar":""},{"name":"Sharon Cornell","avatar":""},{"name":"Earl Boen","avatar":""},{"name":"Jeff Wright","avatar":""},{"name":"Lorali Hart","avatar":""},{"name":"Mallory Sandler","avatar":""},{"name":"K.L. Segal","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm L