INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyet-du-sat-nhan', 'Huyết Dụ Sát Nhân', 'Red to Kill', 'https://phimimg.com/upload/vod/20250526-1/9115e761f8086d7f2247c6f274fafe39.jpg', 'https://phimimg.com/upload/vod/20250526-1/8604d761c3eec2f0fba01a17fcc71cc9.jpg', '<p>Một tên giết người tâm thần có vấn đề với màu đỏ và đặc biệt với phụ nữ. Khi gặp phụ nữ trong bộ đồ màu đỏ, hắn trở nên điên loạn và cực kì nguy hiểm. Ngày nọ, hắn tấn công và xâm hai một cô gái làm công tác xã hội ở trại chăm sóc người bị thiểu năng. Cô gái may mắn thoát chết, lên kế hoạch trả thù kẻ gây ra vết thương lòng cho mình và loại trừ một mối nguy cho cả xã hội vì với cảnh sát, cô không thể chờ đến khi họ vào cuộc được.</p>', 'Full', 1, 'single', 'completed', 30, 1994, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Lily Chung Suk-Wai","avatar":""},{"name":"Money Lo Man-Yee","avatar":""},{"name":"Ben Ng Ngai-Cheung","avatar":""},{"name":"Bobby Yip Kin-Sang","avatar":""},{"name":"Hui Sze-Man","avatar":""},{"name":"Andy Tai Chi-Wai","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Red To Kill","Yeuk saat","弱殺"]', 1784690324540);
