INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-ba-chang-hiep-si-mong-mo', 'Doraemon: Nobita và Ba Chàng Hiệp Sĩ Mộng Mơ', 'Doraemon: Nobita''s Three Visionary Swordsmen', 'https://phimimg.com/upload/vod/20250521-1/f4a1392b6675476fb8d21857ba9c67e1.jpg', 'https://phimimg.com/upload/vod/20250521-1/3ea1c9deeb19a16f472c78164d42f1d0.jpg', '<p>Mệt mỏi vì liên tục gặp ác mộng, Nobita yêu cầu Doraemon mang đến một Cỗ máy ước mơ để Nobita có thể mơ bất cứ điều gì cậu muốn. Sau khi nỗ lực để có được một giấc mơ về sự sụp đổ của Atlantis không thành công, anh ta chọn một giấc mơ nơi anh ta đang ở trong một thế giới giả tưởng với nguồn cảm hứng từ &quot;Ba chàng lính ngự lâm&quot;. Nobita và những người bạn của mình phải cùng nhau đánh bại tên Vua độc ác trước khi hắn thoát khỏi giấc mơ của Nobita để đi vào giấc mơ của người khác.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 1994, 'Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Kazuya Tatekabe","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["夢幻三劍士","Nobita and Fantastic Three Musketeers","Doraemon Nobita to Mugen Sankenshi","Nobita''s.Nobita and Fantastic Three Musketeers","Nobita''s Three Visionary Swordsmen","哆啦A夢：大雄與夢幻三劍士","도라에몽: 노비타와 몽환삼검사","Doraemon the Movie: Nobita''s Three Magical Swordsmen","โดราเอมอนเดอะมูฟวี่: โนบิตะ 3 อัศวินในจินตนาการ","โดราเอมอนเดอะมูฟวี่: โนบิตะสามอัศวินในจินตนาการ","Doreamon: Tiga Sekawan Pahlawan Pedang Impian","Doraemon: Pemain Pedang Perak","映画ドラえもん のび太と夢幻三剣士"]', 1784690324540);
