INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-long-bat-bo-thien-son-dong-lao', 'Thiên Long Bát Bộ: Thiên Sơn Đồng Lão', 'The Maidens Of Heavenly Mountains', 'https://phimimg.com/upload/vod/20250523-1/ba319b9db628dd2ffbe26afdf0904526.jpg', 'https://phimimg.com/upload/vod/20250523-1/157f9288593ca65c88159b44471591df.jpg', '<p>Khi vị võ sư được yêu mến trở bệnh, hai tỷ muội hay cãi vã phải bảo vệ quyền uy của vị võ sư trước một kẻ thù tàn ác và cả gia tộc mình.</p>', 'Full', 1, 'single', 'ongoing', 11, 1994, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Lâm Thanh Hà","avatar":""},{"name":"Trương Mẫn","avatar":""},{"name":"Củng Lợi","avatar":""},{"name":"Lâm Văn Long","avatar":""},{"name":"Từ Thiếu Cường","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Xin tian long ba bu zhi tian shan tong lao","San tin lung bat bo: Tin San Tung Lo","The Maidens of Heavenly Mountain","The Immortals","Dragon Chronicles: The Maidens","8 Guardians of Buddhism","The Dragon Chronicles: The Maidens of Heavenly Mountain","The Dragon Chronicles","新天龍八部之天山童姥"]', 1784690324540);
