INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-long-bat-bo-thien-son-dong-lao', 'Thiên Long Bát Bộ: Thiên Sơn Đồng Lão', 'The Maidens Of Heavenly Mountains', 'thiên long bát bộ: thiên sơn đồng lão the maidens of heavenly mountains lâm thanh hà trương mẫn củng lợi lâm văn long từ thiếu cường xin tian long ba bu zhi tian shan tong lao san tin lung bat bo: tin san tung lo the maidens of heavenly mountain the immortals dragon chronicles: the maidens 8 guardians of buddhism the dragon chronicles: the maidens of heavenly mountain the dragon chronicles 新天龍八部之天山童姥', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chu-ben-thuong-hai-phan-2', 'Bá Chủ Bến Thượng Hải (Phần 2)', 'Shanghai Godfather (Season 2)', 'https://phimimg.com/upload/vod/20250522-1/ddaad4276f3b10768841ab6ad51cb602.jpg', 'https://phimimg.com/upload/vod/20250522-1/dfecc29b07574d3ee3798f16e4549534.jpg', '<p>Bộ phim là phần tiếp theo của loạt phim nổi tiếng cùng tên, tiếp tục khai thác thế giới ngầm Thượng Hải trong bối cảnh thời kỳ Dân Quốc. Phần này tập trung vào cuộc đời và hành trình của nhân vật chính Đỗ Quốc Sinh, một chàng trai nghèo từ nông thôn lên thành phố với khát vọng đổi đời. Tại Thượng Hải, Đỗ Quốc Sinh tình cờ gặp gỡ và đánh nhau với Trương Thiết Lâm. Sau đó, hai người trở thành huynh đệ, cùng nhau xây dựng danh tiếng tại bến Thượng Hải. Tuy nhiên, tính khí nóng nảy của Trương Thiết Lâm bị kẻ xấu lợi dụng, dẫn đến mâu thuẫn và đối đầu với Đỗ Quốc Sinh. Sự xuất hiện của Thích Kế Quang càng làm cho tình hình thêm phức tạp, khi cuộc chiến giữa các thế lực không chỉ vì quyền lực mà còn vì tình yêu với một người phụ nữ.&nbsp;</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 1994, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Đình Oai","avatar":""},{"name":"Từ Thiếu Cường","avatar":""},{"name":"Mạch Lệ Hồng","avatar":""},{"name":"Vương My","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["上海皇帝杜月笙","中国教父","再見黃埔灘2之再起風雲"]', 1784690324540);
