INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('den-thuong-de-cung-phai-cuoi-5', 'Đến Thượng Đế Cũng Phải Cười 5', 'The Gods Must Be Funny in China', 'https://phimimg.com/upload/vod/20250516-1/6e323a047306a8831a50c64f6ffabf84.jpg', 'https://phimimg.com/upload/vod/20250516-1/3b534c166fa1eaacd6be1aae00617c7e.jpg', '<p>Những trò hề xảy ra khi N!xau the Bushman đến Bắc Kinh, nơi anh được tuyển dụng để đi cùng một đội điền kinh trong cuộc đua sinh tồn kéo dài một tuần qua vùng hoang dã của Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 9, 1994, 'Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"N!xau","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Cynthia Khan","avatar":""},{"name":"Gloria Yip Wan-Yee","avatar":""},{"name":"Peter Chan Lung","avatar":""},{"name":"Billy Lau Nam-Kwong","avatar":""},{"name":"Billy Ching Sau-Yat","avatar":""},{"name":"Joseph Cheng King-Kei","avatar":""},{"name":"Simon Lui Yu-Yeung","avatar":""},{"name":"Cheng Pei-Pei","avatar":""},{"name":"Tai Bo","avatar":""},{"name":"Evergreen Mak Cheung-Ching","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["The Gods Must Be Crazy V","Az istenek a fejükre estek Kínában is","The Gods Must Be Crazy 5","The Gods Must Be Funny","Fei jau chiu yan","Los dioses Deben Estar Locos 5","부시맨 5 - 팬더곰과 부시맨","Fei zhou chao ren","The Gods Must Be Funny in China","Die Götter müssen verrückt sein 5","上帝三度來瘋狂","上帝3瘋狂","非洲超人","팬더곰과 부시맨"]', 1784690324540);
