INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-thanh-cam-cung-ky-an-thanh-cung-13-trieu', 'Mãn Thanh Cấm Cung Kỳ Án (Thanh Cung 13 Triều)', 'Sex and the Emperor', 'https://phimimg.com/upload/vod/20250416-1/8f64861b556a491d40f6d9d48164d709.jpg', 'https://phimimg.com/upload/vod/20250416-1/29e55e17c41e1b30e35d97cd654803eb.jpg', '<p>Bối cảnh của phim được lấy vào thời kỳ thối nát của triều đại nhà Thanh khi mà những người duy nhất sống trong Tử Cấm Thành chỉ còn có một nhà vua trẻ tuổi mới lên ngôi, thê thiếp của y, những người hầu và các hoạn quan. Hoàng Đế đa dâm vô độ tới mức thấy bất kỳ người con gái đẹp nào cũng mang về làm vợ, say đắm trong nhục dục từ ngày này qua ngày khác mà không có điểm dừng mặc cho việc đang bỏ bê việc triều chính. Thái giám riêng của Thái hậu lan truyền tin đồn Guilian có ý định trở thành Hoàng hậu tiếp theo để rồi cô bị một thân tín của bà ta bán cô trở thành nô lệ tình dục. Tại một nhà thổ với rất nhiều ganh tị với sắc đẹp của cô, Guilian đã phải vượt qua rất nhiều khó khăn, tủi nhục bằng kỹ thuật tình dục siêu bí mật mà nó khiến cho những người đàn ông sự thỏa mãn nhưng không làm tổn hại tới cơ thể của cô. Hoàng đế thì tối ngày lo lắng cho cô nên đã ra ngoài tìm kiếm cô trở vềnhưng rồi cũng lạc vào những đam mê xác thịt trốn lầu xanh.</p>', 'Full', 1, 'single', 'completed', 29, 1994, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Yvonne Yung Hung","avatar":""},{"name":"Leung See-Ho","avatar":""},{"name":"Sung Boon-Chung","avatar":""},{"name":"Jimmy Wong Shu-Kei","avatar":""},{"name":"Kingdom Yuen King-Tan","avatar":""},{"name":"Stuart Yung Sai-Kit","avatar":""},{"name":"Julie Lee","avatar":""},{"name":"Chin Gwan","avatar":""},{"name":"Wong Yat-Fei","avatar":""},{"name":"Hui Sze-Man","avatar":""},{"name":"Lui Tat","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Man qing jin gong qi an","จักรพรรดิ์รักจนลืมโลก","Sex And The Last Emperor","满清禁宫秘史","Sex and The Emperor","Sex and the Emperor","满清禁宫奇案"]', 1784690324541);
