INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuy-sinh-mong-tu-loan-tu-chi-ho', 'Túy Sinh Mộng Tử: Loan Tử Chi Hổ', 'The Tragic Fantasy: Tiger of Wanchai', 'https://phimimg.com/upload/vod/20250104-1/a4da67587296aab6329bb93d5e37a514.jpg', 'https://phimimg.com/upload/vod/20250104-1/d4003b8f68889d562b3ce25f615d8d19.jpg', '<p>Bị xã hội đen đánh bại lần cuối, nhân viên bãi đậu xe Chan Yiu-Hing mở một cơ sở kinh doanh bảo vệ và tự mình trở thành anh hùng của thế giới ngầm. Khi bạn gái muốn ổn định cuộc sống, Chan nhận ra mình không thể thoát khỏi quá khứ.</p>', 'Full', 1, 'single', 'completed', 10, 1994, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Sean Lau Ching-Wan","avatar":""},{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"Roy Cheung Yiu-Yeung","avatar":""},{"name":"Charine Chan Ka-Ling","avatar":""},{"name":"Marianne Chan","avatar":""},{"name":"Yvonne Yung Hung","avatar":""},{"name":"Ben Lam Kwok-Bun","avatar":""},{"name":"Lo Lieh","avatar":""},{"name":"William Ho","avatar":""},{"name":"Ku Feng","avatar":""},{"name":"Victor Hon Kwan","avatar":""},{"name":"Jameson Lam Wa-Fan","avatar":""},{"name":"Chan Tat-Kwong","avatar":""},{"name":"Benny Lai Keung-Kuen","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["醉生夢死之灣仔之虎"]', 1784690324541);
