INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuy-sinh-mong-tu-loan-tu-chi-ho', 'Túy Sinh Mộng Tử: Loan Tử Chi Hổ', 'The Tragic Fantasy: Tiger of Wanchai', 'túy sinh mộng tử: loan tử chi hổ the tragic fantasy: tiger of wanchai simon yam sean lau ching-wan vincent wan yeung-ming roy cheung yiu-yeung charine chan ka-ling marianne chan yvonne yung hung ben lam kwok-bun lo lieh william ho ku feng victor hon kwan jameson lam wa-fan chan tat-kwong benny lai keung-kuen 醉生夢死之灣仔之虎', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhap-ma', 'Nhập Ma', 'Fatal Obsession', 'https://phimimg.com/upload/vod/20250104-1/6f1d42a4bb8c53d4fa7040a92b8db56e.jpg', 'https://phimimg.com/upload/vod/20250104-1/b3efdeb87751f7796aef3ccbc44a71a6.jpg', '<p>Cheung là vũ công hàng đầu trong một đội nhảy. Cô ấy quá tập trung vào việc luyện tập khiêu vũ và thường xuyên bỏ rơi bạn trai Franky một mình. Điều này đã dẫn đến mối tình giữa Franky và một nữ vũ công khác là Clara, cũng là bạn cùng phòng của Cheung. Franky quyết định chia tay với Cheung, nhưng biết rằng điều này sẽ ảnh hưởng đến buổi biểu diễn trước công chúng của cô, Franky đã hứa với Clara sẽ nói cho Cheung biết sự thật sau buổi biểu diễn. Mối quan hệ phức tạp của ba người đã bị giám đốc sân khấu của đội nhảy Tat Ming phát hiện. luôn luôn nói Cheung muốn dành nhiều thời gian hơn cho Franky nhưng Cheung chỉ phớt lờ lời nói của anh. Vào ngày sinh nhật của Cheung, cả bốn đi chơi và vô tình đụng phải một ngôi nhà xác chết sau một vụ tai nạn ô tô. Tuy nhiên, ngay từ đầu, Cheung đã giả vờ như thường lệ và ngay sau đó cô đã tìm ra kế hoạch trả thù..</p>', 'Full', 1, 'single', 'completed', 10, 1994, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"Yvonne Yung Hung","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Lily Chung Suk-Wai","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"Victor Hon Kwan","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Lee Siu-Kay","avatar":""},{"name":"Lily Leung Shun-Yin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["入魔"]', 1784690324541);
