INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-toi-mot-cai-nao', 'Hôn Tôi Một Cái Nào', 'The Romance Of The Vampires', 'https://phimimg.com/upload/vod/20250104-1/5cd4c005dc375adbaceb624549e9f7d5.jpg', 'https://phimimg.com/upload/vod/20250104-1/c7367e51e80fc5628025c43705163304.jpg', '<p>Tình yêu và đam mê là tên của trò chơi trong bộ phim kinh dị về ma cà rồng lãng mạn này. Thay vì &quot;Tôi muốn máu của bạn...&quot;, ma cà rồng đau khổ trong câu chuyện này tự trừng phạt mình bằng cách từ chối hút máu nạn nhân của mình.</p>', 'Full', 1, 'single', 'completed', 9, 1994, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Yvonne Yung Hung","avatar":""},{"name":"Mondi Yau Yuet-Ching","avatar":""},{"name":"Ben Lam Kwok-Bun","avatar":""},{"name":"Louis Yuen Siu-Cheung","avatar":""},{"name":"Chui Bo-Lun","avatar":""},{"name":"Kingdom Yuen King-Tan","avatar":""},{"name":"Billy Chow Bei-Lei","avatar":""},{"name":"Teddy Yip Wing-Cho","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xi wo yi ge wen","吸我一個吻"]', 1784690324541);
