INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-chien-phong-than', 'Tái Chiến Phong Thần', 'Heavenly Beings', 'https://phimimg.com/upload/vod/20241207-1/061b9bed2b7208191a03ba8bb0ef501c.jpg', 'https://phimimg.com/upload/vod/20241207-1/a4dbbd12de909f64c7e6b725dc870dbf.jpg', '<p>Thần lửa đến nhân gian là Hoa Cương, cùng với tiên nữ đào hoa Lý Dịch Quân, bị thần xử tội vì tình yêu mà biến thành hổ chó, sau đó bị thần kỳ lân giết hại không thành. sửa sai trong đầu và cấu kết với đại quỷ thần. May mắn thay, hắn chết vì mặt trời và mặt trăng. Chỉ có giúp đỡ lẫn nhau thì hai người mới có thể tái sinh làm người. Với sự giúp đỡ của phương pháp trừ quỷ của Quan Âm và sức mạnh của người phàm , chúng ta có thể trừ quỷ và hạ quỷ ...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 19, 1994, 'Lồng Tiếng', 'FHD', 'Singapore', 0, '[]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["再战封神榜"]', 1784690324541);
