INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diet-mon-tham-an-2', 'Diệt Môn Thảm Án 2', 'Daughter Of Darkness 2', 'https://phimimg.com/upload/vod/20241110-1/8f291cc616489bfdd14fcee76408ef86.jpg', 'https://phimimg.com/upload/vod/20241110-1/2b7dcda759fd3c989bebef417292504f.jpg', '<p>Một đôi trai gái yêu nhau dắt nhau về thăm người anh họ ở một ngôi làng vùng ven đô. Trên đường đi, họ gây tai nạn với một tay đầu gấu làng và bị bắt vạ, may người anh họ xuất hiện đúng lúc giải nguy. Người đàn ông vốn bị chứng bất lực nhưng rất yêu vợ mình nên nhờ người anh họ giúp vợ thỏa mãn tình dục. Trong một lần như vậy, cảnh hoan lạc bị tay giang hồ ghi trộm dê tống tiền và tống tình. Người đàn ông vác súng đi trả thủ và cứu thoát người yêu bị giam giữ và hãm hiếp. Chuyện tưởng thế là xong nào ngờ một sáng nọ, có người báo tin, diệt môn thảm án xảy ra, đó chính là gia đình của tay giang hồ hẻm. Cảnh sát buộc mọi đàn ông trong làng vê lấy mẫu tinh dịch, nhưng hung thủ có vẻ như không phải là giống đực.</p>', 'Full', 1, 'single', 'completed', 11, 1994, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Julia Cheng Yim-Lai","avatar":""},{"name":"Ben Ng Ngai-Cheung","avatar":""},{"name":"Dick Lau Tik-Chi","avatar":""},{"name":"William Ho","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Linda Cheung Lan-Ying","avatar":""},{"name":"Victor Hon Kwan","avatar":""},{"name":"Lo Hung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Daughter of Darkness II","灭门惨案2借种","Mit moon cham on 2: Che chung","灭门惨案