INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diet-mon-tham-an-2', 'Diệt Môn Thảm Án 2', 'Daughter Of Darkness 2', 'diệt môn thảm án 2 daughter of darkness 2 julia cheng yim-lai ben ng ngai-cheung dick lau tik-chi william ho liu kai-chi linda cheung lan-ying victor hon kwan lo hung daughter of darkness ii 灭门惨案2借种 mit moon cham on 2: che chung 灭门惨案2：借种 滅門慘案 ii 借種 滅門慘案ii：借種', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-sach-tu-than', 'Danh Sách Tử Thần', 'Hunting List', 'https://phimimg.com/upload/vod/20241101-1/c90add9ff86a98e64bd7aa66b12ca073.jpg', 'https://phimimg.com/upload/vod/20241101-1/80b3ea983ded1c86df6b6aae42a3b3b6.jpg', '<p>Năm 1994, điện ảnh HK phát hành bộ phim “Hunting List” và nhanh chóng tạo nên cơn sốt thời điểm bấy giờ, và đây cũng được đánh giá là một bộ phim hành động đầy máu lửa của điện ảnh Hồng Kông, sự kết hợp với những cảnh nóng đầy mê hoặc. Là một bộ phim nhỏ có không khí sôi động, “Danh Sách Tử Thần” mang đến những pha hành động thuần túy và bạo lực đẫm máu. Những cảnh trong Hunting List thậm chí còn thô bạo và tàn bạo hơn nhiều so với những cảnh gốc trong phim Mỹ dưới ngòi bút của Tarantino, nó mang đặc trưng phong cách điện ảnh xứ cảng thơm thời điểm bấy giờ.</p>', 'Full', 1, 'single', 'completed', 15, 1994, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"徐若瑄","avatar":""},{"name":"呂良偉","avatar":""},{"name":"秦沛","avatar":""},{"name":"Lo Suk-Fong","avatar":""},{"name":"Pal Sinn Lap-man","avatar":""},{"name":"Ku Feng","avatar":""},{"name":"Jackson Liu","avatar":""},{"name":"太保","avatar":""},{"name":"Franco Chiang","avatar":""},{"name":"Kon Tak-Mun","avatar":""},{"name":"Sun Ya-Tung","avatar":""},{"name":"Yu Kam-Po","avatar":""},{"name":"Tu Fu-Ping","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Hunting List","終極獵殺","桃色追缉令","终极猎杀","종극엽살"]', 1784690324541);
