INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('danh-sach-tu-than', 'Danh Sách Tử Thần', 'Hunting List', 'danh sách tử thần hunting list 徐若瑄 呂良偉 秦沛 lo suk-fong pal sinn lap-man ku feng jackson liu 太保 franco chiang kon tak-mun sun ya-tung yu kam-po tu fu-ping hunting list 終極獵殺 桃色追缉令 终极猎杀 종극엽살', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-trang-nguyen', 'Võ Trạng Nguyên', 'The Kung Fu Scholar', 'https://phimimg.com/upload/vod/20241019-1/5a089aee4c6d4dffd31ebe25210899b1.jpg', 'https://phimimg.com/upload/vod/20241019-1/4229ad3f76d5016bf7cf7f6bfd9049b0.jpg', '<p>Phim xoay quanh 2 anh chàng tên là Luận Văn Từ (Trương Vệ Kiện) và Liễu Tiên Khai (Quách Phú Thành), vốn là 2 học sinh thông minh và tài giỏi, 2 người không chỉ có tố chất hơn người mà họ còn đều là những người thích diệt trừ cái ác, họ cùng nhau phát hiện lật đổ được nhiều mưu đồ đen tối. Họ cũng nhiều lần bị truy đuổi quyết liệt. Cả hai đều yêu người bạn học cùng lớp xinh đẹp tên là Ching-ching (Châu Huệ Mẫn), người cháu gái của Hiệu trưởng Heung, Từ thậm chí còn yêu Ching ngay từ cái nhìn đầu tiên mặc cho việc quy định của trường không cho phép chuyện yêu đương trong trường. &nbsp;Sau đó, một cuộc cạnh tranh cực kỳ khốc liệt giữa 2 trường Minh và đối thủ, là trường Oriental đã diễn ra. Để giành chiến thắng trong cuộc thi, Hiệu trưởng Heung đã cho Lee đi thi đấu, Lee đã được tìm thấy bởi các mật thám triều đình , tuy nhiên, với sự giúp đỡ của Lun và Lau, Lee đã cố gắng để trốn thoát và họ quay trở lại cuộc thi và chiến thắng. Từ đó, Lun và Lau trở thành những người bạn tốt nhất…</p>', 'Full', 1, 'single', 'completed', 11, 1994, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"張衛健","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"Aaron Kwok","avatar":""},{"name":"周慧敏","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"Gordon Liu Chia-hui","avatar":""},{"name":"Michael Chow Man-Kin","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"Baat Leung-Gam","avatar":""},{"name":"夏萍","avatar":""},{"name":"黃一山","avatar":""},{"name":