INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-1994', 'Quái Vật', 'The Monster', 'https://phimimg.com/upload/vod/20240925-1/e64c824fd900a814dc2159ebaf3f630c.jpg', 'https://phimimg.com/upload/vod/20240925-1/1a002c687fb4c16a3c7a524f8b36dbf4.jpg', '<p>Một kẻ giết người tình dục hàng loạt độc ác đang lẩn trốn, và người làm vườn cảnh quan kiêm thợ trang trí cửa hàng Loris là nghi phạm chính, nhờ thói quen đáng tiếc của anh ta là bị vướng vào những tình huống thỏa hiệp (mà luôn có một lời giải thích hoàn toàn vô tội rằng cảnh sát không thể giải quyết được. điểm). Nữ cảnh sát chìm Jessica được nhà tâm lý học cảnh sát lập dị Taccone giao nhiệm vụ theo dõi Loris và ...</p>', 'Full', 1, 'single', 'completed', 16, 1994, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Roberto Benigni","avatar":""},{"name":"Michel Blanc","avatar":""},{"name":"Nicoletta Braschi","avatar":""},{"name":"Dominique Lavanant","avatar":""},{"name":"Jean-Claude Brialy","avatar":""},{"name":"Laurent Spielvogel","avatar":""},{"name":"Ivano Marescotti","avatar":""},{"name":"Franco Mescolini","avatar":""},{"name":"Massimo Girotti","avatar":""},{"name":"Luciana Pieri Palombi","avatar":""},{"name":"Vittorio Amandola","avatar":""},{"name":"Rita Di Lernia","avatar":""},{"name":"Gennaro Morrone","avatar":""},{"name":"Vincenzo Vitaglia","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The monster","Монстр","Секс-террорист","IQ本色","Le monstre","המופרע","A Szörnyeteg","Il mostro"]', 1784690324541);
