INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-thanh-tam-doat-ngu-linh-ky', 'Địch Thanh Tam Đoạt Ngũ Linh Kỳ', 'The Great General', 'https://phimimg.com/upload/vod/20240622-1/47f1179eb8c36d8634cd3eec7a39b234.jpg', 'https://phimimg.com/upload/vod/20240622-1/2275f3602f04f4593b437fa82ad0df3e.jpg', '<p><em>Trân Châu Kỳ là bảo vật chấn quốc của nước đại Tống, nhờ có nó mà xưa nay nước này luôn trong trạng thái hưng thịnh và ngai vàng của vua cũng vững chắc. Nhưng một ngày nọ Trân Châu Kỳ bị mất tích do bị Hoa Nhị đánh cắp, sau đó Hoa Nhị vì muốn tránh sự truy đuổi của quân triều định nên đã ôm báu vật vật nhảy xuống sông, từ đó báu vật này bị thất lạc. Nhiều năm sau nó đã xuất hiện trở lại và lần xuất hiện này Trân Châu Kỳ đã đem lại tai họa lớn của Dương gia tướng. Dương Tôn Bảo được về kinh thành mừng thọ lão thái quân sau nhiều năm trấn giữ biên cương. Khi về anh dẫn theo 1 người có Trân Châu Kỳ nhắm dâng lên hoàng thượng nhưng không ngờ rằng đó là 1 âm mưu nhằm hãm hại trung thần của bọn tham quan.</em></p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 1994, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Hương Cầm","avatar":""},{"name":"Từ Thiếu Cường","avatar":""},{"name":"Mạch Cảnh Đình","avatar":""},{"name":"Lý Nhuận Kỳ","avatar":""},{"name":"Vương Diễm Na","avatar":""},{"name":"Lưu Tùng Nhân","avatar":""},{"name":"Lữ Tụng Hiền","avatar":""},{"name":"Vạn Ỷ Văn","avatar":""},{"name":"Đàm Bỉnh Văn","avatar":""},{"name":"Phùng Quốc","avatar":""},{"name":"Chân Chí Cường","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 178469032