INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tokyo-khi-dem-ve', 'Tokyo Khi Đêm Về', 'A New Love in Tokyo', 'https://phimimg.com/upload/vod/20230918-1/048da0752ab9df41c0da618a8c679917.jpg', 'https://phimimg.com/upload/vod/20230918-1/623add4c975f254aaf902a32f47861de.jpg', '<p>Hãy nhìn vào cuộc sống của hai gái mại dâm ở Tokyo: Rei, người làm công việc thống trị S&amp;M và Ayumi, làm nghề gái gọi đơn giản hơn. Ngoài cuộc sống công việc của họ, bộ phim còn đề cập đến cuộc sống riêng tư của họ. Rei đang diễn xuất trong một đoàn kịch nghiệp dư cùng với nhân viên lễ tân từ dịch vụ hộ tống của Ayumi, trong khi Ayumi đang sống với bạn trai sinh viên của cô khi anh đấu tranh để cuối cùng được nhận vào đại học.</p>', 'Full', 1, 'single', 'completed', 12, 1994, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sawa Suzuki","avatar":""},{"name":"Reiko Kataoka","avatar":""},{"name":"Aya Sugimoto","avatar":""},{"name":"Hiromitsu Suzuki","avatar":""},{"name":"Tomorowo Taguchi","avatar":""},{"name":"Takashi Matsuo","avatar":""},{"name":"Toshi Shioya","avatar":""},{"name":"Suzuki Matsuo","avatar":""},{"name":"Yoshihiko Hakamada","avatar":""},{"name":"Shinji Takeda","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
