INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('com-thoi-gian', 'Cớm Thời Gian', 'Timecop', 'https://phimimg.com/upload/vod/20240220-1/91a4631a0a1d60d2819362e4f4320a5a.jpg', 'https://phimimg.com/upload/vod/20240220-1/7defe526534e6bac8a79f930f382ba6b.jpg', '<p>Một sĩ quan của cơ quan an ninh điều chỉnh du hành thời gian, phải tự bảo vệ mạng sống của mình trước một chính trị gia mờ ám có liên quan đến quá khứ của anh ta.</p>', 'Full', 1, 'single', 'completed', 13, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Mia Sara","avatar":""},{"name":"Ron Silver","avatar":""},{"name":"Bruce McGill","avatar":""},{"name":"Gloria Reuben","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324541);
