INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-thay', 'Xin Chào Thầy', 'Class Of Distinction', 'https://phimimg.com/upload/vod/20240215-1/27f0168fb938c913743e9e343ab83b49.jpg', 'https://phimimg.com/upload/vod/20240215-1/e409ab2150de4fc4bc595187c5f4715f.jpg', '<p>Chúc Đại Bảo (Lê Minh đóng) sau khi làm việc trong ngành quảng cáo nhưng anh gặp nhiều khó khăn đâm ra thất chí, đã được hồng nhan tri kỉ (Tuyên Huyên đóng) giới thiệu đến 1 trường học, đảm nhận vai trò 1 thầy giáo đứng lớp. Tại trường học Bảo đã quen được Phương Đồng Tâm-một nữ giáo viên(Lý Ỷ Hồng đóng), cô ấy đã làm cho anh hiểu rằng cần đặc biệt quan tâm đến những học sinh bướng bỉnh, phải có thái độ dạy học tận tình, tận tụy. ban đầu Bảo gặp nhều khó khăn khi tiếp cận với học sinh nhưng bằng sự chân thành của mình bảo đã dần dần chiếm được cảm tình và lòng tin của các em học sinh, và rất được học sinh yêu quý, tuy mỗi em một hoàn cảnh, một tính cách nhưng tình cảm của chúng đối với anh là hoàn toàn chân thành. Bạn gái của Bảo vì tham hư vinh mà nỡ bỏ anh ra đi, khiến anh rất đau lòng. Trong quá trình dạy học, Chúc Đại Bảo đã nảy sinh lòng cảm mến đối với Phương Đồng Tâm, đáng tiếc, cô ấy sớm đã có bạn trai là Lục Kiến Tài (Cổ thiên Lạc đóng). Sau đó Tâm Di lại đem lòng ái mộ Chúc Đại Bảo, CHúc Đại Bảo vốn rất khéo léo tinh tế trong chuyện tình cảm nam nữ, nhưng cũng hok biết phải lựa chọn thế nào. Ở mặt khác, cha của Chúc Đại Bảo (Hoàng Chiêm đóng) tự cho mình là người phong lưu, nên đã khiến cho mẹ của Chúc Đại Bảo phải ra ở riêng, còn cậu của anh (La Gia Anh đóng) thường xuyên đấu khẩu với bà nội của anh (Hạ Bình đóg), 1 gia đình mà mọi người lun cãi nhau như thế nàykhiến Chúc Đại bảo vô cùng nhức đầu.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 1994, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Lê Minh","avatar":""},{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Tuyên Huyên","avatar":""},{"name":"Lý Ỷ Hồng","avatar":""},{"name":"La Văn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324541);
