INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-bao-thien-ha', 'Hắc Báo Thiên Hạ', 'The Black Panther Warriors', 'https://phimimg.com/upload/vod/20240207-1/da0ab5a7b049cb04f3e18b25bc2ff8c5.jpg', 'https://phimimg.com/upload/vod/20240207-1/06aa3b10a88807d52beba8e7da4cc6e5.jpg', '<p>Hắc Báo Thiên Hạ - The Black Panther Warriors xoay quanh một tay lính đánh thuê tên Hắc Báo. Anh được một người ẩn danh trả số tiền lớn để đánh cắp tài liệu mật từ đồn cảnh sát - nơi hệ thống bảo mật thuộc hàng tối tân nhất thế giới. Để hoàn thành việc, Hắc Báo hợp tác với chuyên gia máy tính, vũ khí và một thần bài nổi tiếng. Nhưng không ngờ, công việc nguy hiểm này chính là cái bẫy để tiêu diệt Hắc Báo. Dưới sự giúp đỡ của những người bạn, anh quyết tâm trả thù và khám phá sự thật đằng sau đó.</p>', 'Full', 1, 'single', 'completed', 13, 1994, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lương Gia Huy","avatar":""},{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Trương Vệ Kiện","avatar":""},{"name":"Lâm Thanh Hà","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324541);
