INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-live', 'To Live', 'To Live', 'https://phimimg.com/upload/vod/20240219-1/757e31b074d3f50e4cdc22bd72602a88.jpg', 'https://phimimg.com/upload/vod/20240219-1/de6047145c62ad910620485b67e9084f.jpg', '<p>Fugui và Jiazhen phải chịu đựng những sự kiện hỗn loạn ở Trung Quốc khi vận may cá nhân của họ chuyển từ quyền sở hữu đất đai giàu có sang giai cấp nông dân. Nghiện cờ bạc, Fugui mất tất cả. Trong những năm sau đó, anh ta bị dồn vào cả quân đội dân tộc chủ nghĩa và quân đội cộng sản, trong khi Jiazhen bị buộc phải làm công việc tầm thường.</p>', 'Full', 1, 'single', 'completed', 11, 1994, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ge You","avatar":""},{"name":"Gong Li","avatar":""},{"name":"Niu Ben","avatar":""},{"name":"Jiang Wu","avatar":""},{"name":"Huang Zong Luo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
