INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sirens', 'Sirens', 'Sirens', 'https://phimimg.com/upload/vod/20240121-1/fd883c44a1d05e798560339eb809de49.jpg', 'https://phimimg.com/upload/vod/20240121-1/c53feffa8660d2fc974df47d6e4f1711.jpg', '<p>Vào những năm 1930 ở Úc, giáo sĩ Anh giáo Anthony Campion và vợ chính của ông, Estella, được yêu cầu đến thăm họa sĩ nổi tiếng Norman Lindsay, người đã lên kế hoạch đóng góp cho một cuộc triển lãm nghệ thuật quốc tế bị coi là báng bổ. Trong khi Campion và Lindsay tranh luận, Estella thấy mình bị thu hút bởi ba người mẫu xinh đẹp đang ngồi cho tác phẩm hiện tại của họa sĩ, Sheela có suy nghĩ phóng khoáng, Pru gợi cảm và Giddy trinh nguyên.</p>', 'Full', 1, 'single', 'completed', 11, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Hugh Grant","avatar":""},{"name":"Tara Fitzgerald","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Elle Macpherson","avatar":""},{"name":"Portia de Rossi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
