INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sai-lam-dang-tiec', 'Sai Lầm Đáng Tiếc', 'China Moon', 'https://phimimg.com/upload/vod/20240121-1/457d9b17cd1affdb845d002f30e03cba.jpg', 'https://phimimg.com/upload/vod/20240121-1/3617d1fd887606b457175c8ba88f7342.jpg', '<p>Thám tử Kyle Bodine phải lòng Rachel Munro, người bị mắc kẹt trong một cuộc hôn nhân bạo lực. Sau khi bắn chết chồng, Kyle miễn cưỡng đồng ý giúp giấu xác, nhưng đối tác của Kyle tỏ ra tinh tế khác thường trong việc tìm ra manh mối.</p>', 'Full', 1, 'single', 'completed', 12, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ed Harris","avatar":""},{"name":"Madeleine Stowe","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Patricia Healy","avatar":""},{"name":"Benicio del Toro","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324541);
