INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('leon-the-professional', 'Léon: The Professional', 'Léon: The Professional', 'https://phimimg.com/upload/vod/20240118-1/93d5af92a67d101b24233a7f7c249276.jpg', 'https://phimimg.com/upload/vod/20240118-1/e7e62317c4f22c8e25725652fcd86015.jpg', '<p>Cô bé Mathilda có hoàn cảnh đặc biệt. Cả nhà buôn ma tuý, cha và chị gái không hề quan tâm gì đến mình, chỉ có cậu em trai là người mà Mathilda yêu thương nhất. Cuộc sống cứ tiếp diễn trôi và trong một bầu không khí đầy khủng hoảng của người chị mất nết cùng người cha buôn ma tuý, tưởng như tương lai Mathilda cũng trở thành một cô bé hư. Mãi cho đến một ngày, khi một cảnh sát tha hoá vì cạnh tranh làm ăn mà giết cả nhà Mathilda, cuộc sống của cô bé mới bắt đầu thay đổi. Cô chạy trốn và được Leon (Jean Reno), một tên giết thuê bảo bọc. Cô học bắn súng để trả thù, và đã được Leon giúp đỡ.</p>', 'Full', 1, 'single', 'completed', 11, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean Reno","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Danny Aiello","avatar":""},{"name":"Peter Appel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
