INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('death-and-the-maiden', 'Death And The Maiden', 'Death And The Maiden', 'https://phimimg.com/upload/vod/20231231-1/f5e62c341120379d8b773b8acc631861.jpg', 'https://phimimg.com/upload/vod/20231231-1/0686e0445e24b40d3e6dc7637afb4fb8.jpg', '<p>Một nhà hoạt động chính trị tin chắc rằng vị khách của cô là một người đàn ông đã từng tra tấn cô vì chính phủ.</p>', 'Full', 1, 'single', 'completed', 14, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sigourney Weaver","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Stuart Wilson","avatar":""},{"name":"Krystia Mova","avatar":""},{"name":"Jonathan Vega","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324541);
