INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-dom-ngo-1994', 'Kẻ Dòm Ngó', 'The Voyeur', 'https://phimimg.com/upload/vod/20231230-1/20fc5b5319009c430e90d95533b64eb7.jpg', 'https://phimimg.com/upload/vod/20231230-1/c42dec21bd79eff7f1e54e1587229c7e.jpg', '<p>Tại một trường cao đẳng ở Rome, một giáo sư có biệt danh là Dodo đang rơi vào tình trạng trầm cảm. Người vợ xinh đẹp tuyệt trần của anh ta vừa bỏ anh ta để theo một người đàn ông khác. Dodo rất muốn cô ấy quay lại và có những giấc mơ khiêu dâm về cô ấy. Một cô sinh viên trẻ đẹp trong lớp nhờ anh chở về nhà và dụ dỗ người đàn ông may mắn, nhưng anh vẫn thắc mắc về vợ mình và người tình của cô.</p>', 'Full', 1, 'single', 'completed', 15, 1994, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Katarina Vasilissa","avatar":""},{"name":"Francesco Casale","avatar":""},{"name":"Cristina Garavaglia","avatar":""},{"name":"Raffaella Offidani","avatar":""},{"name":"Antonio Salines","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
