INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-land-before-time-ii-the-great-valley-adventure', 'The Land Before Time II: The Great Valley Adventure', 'The Land Before Time II: The Great Valley Adventure', 'https://phimimg.com/upload/vod/20231219-1/5ad495cc211dd26153bfa5dd71f0bbe6.jpg', 'https://phimimg.com/upload/vod/20231219-1/2666885532684f51f4ab4a0bc6343c23.jpg', '<p>Sau khi phát hiện những tên trộm trứng từ nơi ẩn náu bí mật của chúng, Littlefoot và cả nhóm bắt đầu một nhiệm vụ giải cứu táo bạo và phải tìm đường trở về nhà.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scott McAfee","avatar":""},{"name":"Candace Hutson","avatar":""},{"name":"Heather Hogan","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Linda Gary","avatar":""},{"name":"Kenneth Mars","avatar":""},{"name":"John Ingle","avatar":""},{"name":"Tress MacNeille","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324541);
