INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-escape', 'No Escape', 'No Escape', 'https://phimimg.com/upload/vod/20231219-1/a096842f510e7576b5c848dea87c5c19.jpg', 'https://phimimg.com/upload/vod/20231219-1/1e536e53bf708627ecdb6843cf708a1a.jpg', '<p>Vào năm 2022, một quản giáo tàn nhẫn đã tạo ra giải pháp cuối cùng cho những tù nhân rắc rối và bạo lực nhất của mình: Absolom, một hòn đảo rừng bí mật nơi các tù nhân bị bỏ rơi và bỏ mặc cho đến chết. Nhưng Thuyền trưởng Thủy quân lục chiến John Robbins, bị kết tội giết một sĩ quan chỉ huy, quyết tâm trốn khỏi hòn đảo để tiết lộ sự thật đằng sau hành động giết người của mình và làm rõ tên tuổi của mình.</p>', 'Full', 1, 'single', 'completed', 13, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ray Liotta","avatar":""},{"name":"Lance Henriksen","avatar":""},{"name":"Stuart Wilson","avatar":""},{"name":"Kevin Dillon","avatar":""},{"name":"Kevin J. O''Connor","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324541);
