INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('genesis-the-creation-and-the-flood', 'Genesis: The Creation And The Flood', 'Genesi: La Creazione E Il Diluvio', 'https://phimimg.com/upload/vod/20231214-1/4700f2362d670db74e680a9536431e19.jpg', 'https://phimimg.com/upload/vod/20231214-1/490aa3816d54e5ea46e0656951f675d3.jpg', '<p>Một bóng tối bao trùm. Đột nhiên, giọng nói của một đứa trẻ, sợ hãi, hỏi han, xuyên qua bóng tối ... Những tia sáng le lói đầu tiên bắt đầu chạm trổ những hình thù bí ẩn từ trong bóng tối ... Trong số đó, có một cụ già. Ông trấn an đứa trẻ, khuyên nó đi xem những điều kỳ diệu của trái đất. Và chính bằng đôi mắt của đứa trẻ này, chúng ta sẽ chứng kiến sự sáng tạo của thế giới.</p>', 'Full', 1, 'single', 'completed', 11, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wil Anderson","avatar":""},{"name":"Dave Hughes","avatar":""},{"name":"Rhys Muldoon","avatar":""},{"name":"Corinne Grant","avatar":""},{"name":"Omero Antonutti","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
