INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-va-suc-quyen-ru', 'Cái Chết Và Sức Quyến Rũ', 'Death And The Maiden', 'https://phimimg.com/upload/vod/20231212-1/7f5569eaf1a9694bbe0fa839b22941e8.jpg', 'https://phimimg.com/upload/vod/20231212-1/0b43964a655cca1adda13832bd23d407.jpg', '<p>Cái Chết Và Sức Quyến Rũ - Death and the Maiden là một bộ phim Mỹ-Anh-Pháp 1994 của đạo diễn Roman Polanski. Paulina Escobar (Sigourney Weaver) tin rằng vị khách (Ben Kingsley) mà người chồng luật sư của cô (Stuart Wilson) mang đến nhà với kẻ bắt cóc, tra tấn và hãm hiếp cô năm trước là một. Luôn chỉa súng vào mặt hắn, cô liên tục tra tấn và yêu cầu người đàn ông thú nhận tội ác của mình. Người chồng đứng ngoài nhưng anh ta bắt đầu nghi ngờ câu chuyện của vợ. Và một phiên tòa được mở để tìm ra sự thật. Đâu là sự thật và ai sẽ chịu hoàn toàn trách nhiệm?</p>', 'Full', 1, 'single', 'completed', 12, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sigourney Weaver","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Stuart Wilson","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324541);
