INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-rung-xanh', 'Câu Chuyện Rừng Xanh', 'The Jungle Book 1994', 'https://phimimg.com/upload/vod/20231211-1/c93e8422e2911f7df30198b12c194bce.jpg', 'https://phimimg.com/upload/vod/20231211-1/b9e0367242870544fc6bed8a06b1f268.jpg', '<p>Cậu Bé Rừng Xanh là một phim sản xuất bởi Disney dựa vào truyện cùng tên của Rudyard Kipling. Cậu bé Mowgli năm tuổi bị lạc mất cha khi ông dẫn đoàn đi thám hiểm rừng già Ấn Độ. May thay, các ác thú lại có lòng nhân từ nên không xơi cậu mà lại còn nuôi nấng, dậy dỗ và bảo vệ cậu. Lá rụng về cội, đến tuổi trưởng thành, cậu cũng nung nấu ý định quay về phố thị, tìm lại người cha cùng cô bé ngày xưa trong đoàn thám hiểm. Nhưng rừng già còn có một con thú khác, không hiền lành như những người bạn thú của cậu. Đó là con hổ hung dữ khát máu Shere Khan.</p>', 'Full', 1, 'single', 'completed', 14, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Scott Lee","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Lena Headey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324541);
