INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-ban-phan-1', 'Những Người Bạn (Phần 1)', 'Friends (Season 1)', 'https://phimimg.com/upload/vod/20231219-1/012990939160b38bb6d081458d4ac9e9.jpg', 'https://phimimg.com/upload/vod/20231219-1/8599c96b53e5bbe8ddf47b0c36b3697e.jpg', '<p>Loạt phim dõi theo những sự cố vui nhộn của 6 người bạn tuổi đôi mươi đang vật lộn với những thử thách trong công việc, cuộc sống, tình yêu tại Manhattan những năm 1990.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 17, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Aniston","avatar":""},{"name":"Courteney Cox","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Matt LeBlanc","avatar":""},{"name":"Matthew Perry","avatar":""},{"name":"David Schwimmer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324541);
