INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-gi-dang-an-mon-gilbert-grape', 'Điều Gì Đang Ăn Mòn Gilbert Grape', 'What''s Eating Gilbert Grape', 'https://phimimg.com/upload/vod/20231211-1/c39fed509940ec52d2bd3f0136c7ac44.jpg', 'https://phimimg.com/upload/vod/20231211-1/ed7c2bea141a130053484d1118b6dae6.jpg', '<p>Johnny vào vai Gilbert Grape sinh sống cùng mẹ và em trai Arnie ở một thị trấn nhỏ với nguồn thu chủ yếu nhờ vào khách vãng lai. Vì mẹ của cả hai anh em quá đau khổ trước cái chết của chồng nên Gilbert phải thay mẹ chăm sóc cho cậu em Arnie. Khi gặp Becky cùng bà của cô bị kẹt lại ở thị trấn, Gilbert lập tức say mê nàng, nhưng câu chuyện tình lãng mạn của Gilbert không đâu vào đâu khi anh còn trách nhiệm trông cậu em nhỏ...</p>', 'Full', 1, 'single', 'completed', 13, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Leonardo DiCaprio","avatar":""},{"name":"Juliette Lewis","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324541);
