INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dieu-gi-dang-an-mon-gilbert-grape', 'Điều Gì Đang Ăn Mòn Gilbert Grape', 'What''s Eating Gilbert Grape', 'điều gì đang ăn mòn gilbert grape what''s eating gilbert grape johnny depp leonardo dicaprio juliette lewis ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-troi-tu-do', 'Vùng Trời Tự Do', 'Drop Zone', 'https://phimimg.com/upload/vod/20231230-1/96fdc2955c0a2dfa2f26b57b3523d51a.jpg', 'https://phimimg.com/upload/vod/20231230-1/157e04019bec73d1b920d2215ae87af9.jpg', '<p>Một vụ vượt ngục táo bạo từ một chiếc máy bay ở độ cao 30.000 feet khiến Thống chế Hoa Kỳ Pete Nessip thương tiếc một người anh trai và nổ súng để trả thù. Sau khi được yêu cầu nộp huy hiệu của mình, anh ta tìm kiếm Jessie Crossman, một vận động viên nhảy dù nổi tiếng, và đề nghị tài trợ cho phi hành đoàn của cô ấy cho buổi trình diễn nhảy dù nhân Ngày Độc lập hàng năm ở Washington, D.C., nếu cô ấy huấn luyện anh ta. Trong khi đó, kẻ chủ mưu đằng sau vụ bẻ khóa giữa không trung đang lên kế hoạch đánh cắp máy tính táo bạo vào Ngày Độc lập.</p>', 'Full', 1, 'single', 'completed', 13, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wesley Snipes","avatar":""},{"name":"Gary Busey","avatar":""},{"name":"Yancy Butler","avatar":""},{"name":"Michael Jeter","avatar":""},{"name":"Corin Nemec","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324541);
