INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-anh-hung-ban-sac', 'Tân Anh Hùng Bản Sắc', 'Return To A Better Tomorrow', 'https://phimimg.com/upload/vod/20231209-1/bdd754bb30efc6ad37f4ee3030919d16.jpg', 'https://phimimg.com/upload/vod/20231209-1/df37f28eb01985a79df451b042cd5dba.jpg', '<p>Tân Anh Hùng Bản Sắc - Return To A Better Tomorrow xoay quanh thanh niên tên Tuấn (Trịnh Y Kiện), được biết đến là một trong những thanh niên nổi tiếng của vùng và có nhiều cô gái theo đuổi. Một lần, Tuấn cứu Ha - kẻ bị buộc tội giết người tình của vợ và từ đó họ trở thành bạn tốt, sống chết có nhau. Thế nhưng, tình bạn này đứng trước nhiều thử thách và có nguy cơ trở mặt thành thù.</p>', 'Full', 1, 'single', 'completed', 12, 1994, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Trịnh Y Kiện","avatar":""},{"name":"Lưu Thanh Vân","avatar":""},{"name":"Khưu Thục Trinh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324541);
