INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuy-quyen-ii', 'Túy Quyền II', 'Drunken Master II', 'https://phimimg.com/upload/vod/20231208-1/c2a55172d3ac88ef5dd537318dd5442b.jpg', 'https://phimimg.com/upload/vod/20231208-1/7b658e0c01b7bad9b41f241f06652113.jpg', '<p>Trở về nhà cùng cha sau chuyến đi mua sắm, Vương Phi Hồng vô tình bị cuốn vào cuộc chiến giữa những người nước ngoài mong muốn xuất khẩu các hiện vật cổ của Trung Quốc và những người trung thành không muốn những món đồ đó rời khỏi đất nước. Fei-Hong phải chiến đấu chống lại người nước ngoài bằng phong cách Drunken Boxing của mình và vượt qua sự phản đối của cha mình.</p>', 'Full', 1, 'single', 'completed', 19, 1994, 'Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Lung Ti","avatar":""},{"name":"Anita Mui","avatar":""},{"name":"Felix Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324541);
