INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-sung-tren-san-dien', 'Tiếng Súng Trên Sàn Diễn', 'Bullets Over Broadway', 'https://phimimg.com/upload/vod/20231208-1/cb7781f1616734294402e79e0df2de6d.jpg', 'https://phimimg.com/upload/vod/20231208-1/e8bebb638de41793278f5f340e734cf9.jpg', '<p>Sau khi nhà viết kịch trẻ tuổi, David Shayne nhận được tài trợ cho vở kịch của mình từ gangster Nick Valenti, Olive, bạn gái của Nick, đã nhận được vai bác sĩ tâm lý một cách thần kỳ—nhưng cô ấy không chỉ là một bim bim không bao giờ có thể vượt qua vai bác sĩ tâm lý—cô ấy còn là một nữ diễn viên đáng sợ. David chịu đựng người đàn ông hàng đầu là một người nghiện ăn, một quý bà muốn phần của mình trở nên vui nhộn và sát thủ / vệ sĩ can thiệp của Olive, nhưng, cuối cùng anh ta phải quyết định xem nghệ thuật hay cuộc sống quan trọng hơn.</p>', 'Full', 1, 'single', 'completed', 12, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jim Broadbent","avatar":""},{"name":"John Cusack","avatar":""},{"name":"Harvey Fierstein","avatar":""},{"name":"Chazz Palminteri","avatar":""},{"name":"Mary-Louise Parker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324541);
