INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-phu-nu-be-nho', 'Những Người Phụ Nữ Bé Nhỏ', 'Little Women', 'https://phimimg.com/upload/vod/20231208-1/44cedfa75e8c9d923f5f2632299410b1.jpg', 'https://phimimg.com/upload/vod/20231208-1/02106adffefedc294328ff67d1097aaa.jpg', '<p>Có người mẹ nghị lực, chị em Jo, Meg, Beth và Amy cùng trải qua những nỗi niềm tuổi trưởng thành, bất hạnh trong gia đình và khát vọng của bản thân ở nước Mỹ thế kỷ 19.</p>', 'Full', 1, 'single', 'completed', 12, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Susan Sarandon","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Gabriel Byrne","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324541);
