INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-z-broly-de-nhi', 'Bảy Viên Ngọc Rồng Z: Broly Đệ Nhị', 'Dragon Ball Z: Bio-Broly', 'https://phimimg.com/upload/vod/20231206-1/abfcde1fe8c0ab421d242920d4e4b543.jpg', 'https://phimimg.com/upload/vod/20231206-1/7380089fd50f25dd42f4e5761cb294ef.jpg', '<p>Bảy Viên Ngọc Rồng: Broly Đệ Nhị kể về gã tỷ phú Jaguard đã chế tạo được các chiến binh sinh học. Gã rắp tâm dùng lực lượng này để trả thù ông Satan. Lời thách đấu đã được chuyển đi. Cùng lúc, Robot số 18 không để Satan được yên vì món nợ chưa trả khi cô nàng này giúp Satan trở thành vô địch Đại hội võ thuật lần thứ 25. Satan đến hoang đảo nơi diễn ra cuộc đấu dưới sự áp tải của số 18 và 2 chú nhóc Goten, Trunk. Không ai ngờ tới, một trong số các Chiến binh sinh học còn có bản sao của Broly… Khi gã tỉnh giấc, cuộc đối đầu giờ càng cam go.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 1994, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324541);
