INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('3-ninjas-sieu-quay', '3 Ninjas Siêu Quậy', '3 Ninjas Kick Back', 'https://phimimg.com/upload/vod/20231205-1/8e90ca9101d10cf397866faf9ccc8b1e.jpg', 'https://phimimg.com/upload/vod/20231205-1/90d005ac008baa28248f01e3f92788ed.jpg', '<p>Trong một trận đấu bóng chày tranh chức vô địch, ba anh em nghe tin ông của họ ở Nhật Bản đang gặp khó khăn nên đã ra tay giúp đỡ ông, khiến trận đấu bị thủng lưới. Khi đến Nhật Bản, họ phải sử dụng tất cả sức mạnh của mình để bảo vệ anh ta trước kẻ thù truyền kiếp của anh ta, kẻ đã quay trở lại để trả thù chính xác.</p>', 'Full', 1, 'single', 'completed', 14, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Victor Wong","avatar":""},{"name":"Max Elliott Slade","avatar":""},{"name":"Sean Fox","avatar":""},{"name":"J. Evan Bonifant","avatar":""},{"name":"Caroline Junko King","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324541);
