INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thuc-nam-nu', 'Ẩm Thực Nam Nữ', 'Eat Drink Man Woman', 'https://phimimg.com/upload/vod/20231202-1/938993c09875533c0d7d35000d677c78.jpg', 'https://phimimg.com/upload/vod/20231202-1/ce01bf4059b0d0e2e11f5b6f0463127b.jpg', '<p>Ông Chu là một đầu bếp tài năng của Grand Hotel (Đài Bắc) nay đã nghỉ hưu. Niềm vui duy nhất của ông là chuẩn bị những bữa ăn ngon cho ba con gái, những người ông đã một mình nuôi nấng sau nhiều năm. Cả ba cô con gái của ông Chu đều chưa có ý định lập gia đình riêng trong đó người con cả dường như đã lỡ thì và không có ai theo đuổi, người con gái thứ hai thì quá chú tâm vào công việc còn người con út thì vẫn chưa đến tuổi lập gia đình.</p>', 'Full', 1, 'single', 'completed', 16, 1994, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Sihung Lung","avatar":""},{"name":"Yang Kuei-Mei","avatar":""},{"name":"Wu Chien-Lien","avatar":""},{"name":"Wang Yu-wen","avatar":""},{"name":"Winston Chao","avatar":""},{"name":"Sylvia Chang","avatar":""},{"name":"Chen Chao-jung","avatar":""},{"name":"Lester Chan","avatar":""},{"name":"Chen Yu","avatar":""},{"name":"Gua Ah-leh","avatar":""},{"name":"Chi-Der Hong","avatar":""},{"name":"Gin-Ming Hsu","avatar":""},{"name":"Huel-Yi Lin","avatar":""},{"name":"Shih-Jay Lin","avatar":""},{"name":"Chin-Cheng Lu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324541);
