INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-gia-chat-no', 'Chuyên Gia Chất Nổ', 'The Specialist', 'https://phimimg.com/upload/vod/20231130-1/5ede2750de22dd74ef0d3be578b34941.jpg', 'https://phimimg.com/upload/vod/20231130-1/3216c4f848fc77780358c1e3bd8b90d9.jpg', '<p>Cô bé May Munro lẽ ra đã có một cuộc sống rất yên ấm bên gia đình. Nào ngờ chỉ trong một đêm, tai họa từ đâu ập xuống đã cướp đi tuổi thơ hạnh phúc của May. Do cha của May vô tình trông thấy một điều không nên thấy nên toàn bộ gia đình cô đã bị bọn mafia sát hại. Nhờ trốn trong chiếc tủ quần áo, May bảo toàn được tính mạng, nhưng sau khi đã tận mắt chứng kiến cái chết của cha mẹ mình thì cuộc sống đối với May cũng chẳng còn mấy ý nghĩa. Thời gian dần trôi qua, cô bé May ngày nào giờ đã là một phụ nữ xinh đẹp và quyến rũ (Sharon Stone). Tưởng như mọi vết thương lòng đã có thể nguôi ngoai theo năm tháng nhưng sự thật là May đang nung nấu một kế hoạch trả thù...</p>', 'Full', 1, 'single', 'completed', 14, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Sharon Stone","avatar":""},{"name":"James Woods","avatar":""},{"name":"Rod Steiger","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Mario Ernesto Sánchez","avatar":""},{"name":"Sergio Doré Jr.","avatar":""},{"name":"Chase Randolph","avatar":""},{"name":"Jeana Bell","avatar":""},{"name":"Brittany Paige Bouck","avatar":""},{"name":"Emilio Estefan Jr.","avatar":""},{"name":"LaGaylia Frazier","avatar":""},{"name":"Ramón González Cuevas","avatar":""},{"name":"Tony Munafo","avatar":""},{"name":"Cheito Quinonez","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324541);
