INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vach-tran', 'Vạch Trần', 'Disclosure', 'https://phimimg.com/upload/vod/20231129-1/f38973db75ecae7936f2cbb65bea16ff.jpg', 'https://phimimg.com/upload/vod/20231129-1/4ab5fcbf922c86ace5193822568d09aa.jpg', '<p>Tom Sanders là một người quản lý tại một công ty máy tính ở Seattle. Hạnh phúc kết hôn với trẻ em, Tom có hy vọng lớn cho một chương trình khuyến mãi của ông chủ của mình, nhưng nó sẽ đến Meredith Johnson, bạn gái cũ quyến rũ của Tom, thay vào đó. Bằng cách nào đó Tom lấy nó với một hạt muối, cho đến khi một cuộc họp cá nhân biến thành một sự quyến rũ khi Meredith quyết định sống lại tưởng tượng tình dục của mình và nhận từ nơi họ rời đi. Tom từ chối, làm cho Meredith bực bội. Lựa chọn duy nhất của Tom; để kiện quấy rối tình dục. Nhưng mọi người đều tin rằng đó là cách khác và ông chủ của anh ta muốn chuyển anh ta sang một bộ phận khác, buộc anh ta phải mất tất cả. Tom phát hiện không chỉ là hệ thống bị lừa dối anh ta, mà Meredith sẽ phá hủy sự nghiệp của mình và củng cố mình bằng cách đổ lỗi cho anh ta một lỗi nghiêm trọng về sự phán xét về phía cô ấy</p>', 'Full', 1, 'single', 'completed', 10, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Dylan Baker","avatar":""},{"name":"Jacqueline Kim","avatar":""},{"name":"Roma Maffia","avatar":""},{"name":"Caroline Goodall","avatar":""},{"name":"Rosemary Forsyth","avatar":""},{"name":"Dennis Miller","avatar":""},{"name":"Suzie Plakson","avatar":""},{"name":"Nicholas Sadler","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"Anneliza Scott","avatar":""},{"name":"Rohana Razali","avatar":""},{"name":"Anne Flanagan","avatar":""},{"name":"Kate Williamson","avatar":""},{"name":"Farrah","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324541);
