INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-gi-cua-anh', 'Em Là Gì Của Anh', 'Hum Aapke Hain Koun', 'https://phimimg.com/upload/vod/20231129-1/2a0b79b125fbacb25bf7e48e3b06bd02.jpg', 'https://phimimg.com/upload/vod/20231129-1/4d44974899f34c04588076fa933471e0.jpg', '<p>Mặc dù Nisha phải lòng Prem, cô vẫn đồng ý kết hôn với anh trai anh vì lợi ích của hai gia đình. Nhưng số phận có lẽ còn những toan tính khác cho đôi uyên ương.</p>', 'Full', 1, 'single', 'completed', 14, 1994, 'Vietsub', 'HD', 'Ấn Độ', 0, '[{"name":"Salman Khan","avatar":""},{"name":"Madhuri Dixit","avatar":""},{"name":"Mohnish Behl","avatar":""},{"name":"Renuka Shahane","avatar":""},{"name":"Anupam Kher","avatar":""},{"name":"Reema Lagoo","avatar":""},{"name":"Laxmikant Berde","avatar":""},{"name":"Priya Arun","avatar":""},{"name":"Alok Nath","avatar":""},{"name":"Satish Shah","avatar":""},{"name":"Bindu","avatar":""},{"name":"Himani Shivpuri","avatar":""},{"name":"Ajit Vachani","avatar":""},{"name":"Dilip Joshi","avatar":""},{"name":"Dinesh Hingoo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324541);
