INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mary-shelleys-frankenstein', 'Mary Shelley''s Frankenstein', 'Mary Shelley''s Frankenstein', 'https://phimimg.com/upload/vod/20231129-1/30103483c351b377302e9fb06ad019c9.jpg', 'https://phimimg.com/upload/vod/20231129-1/f6e96cd197f7e85e568885a7fc09b8ff.jpg', '<p>Dựa trên tiểu thuyết của Mary Shelley, &quot;Frankenstein&quot; kể câu chuyện về Victor Frankenstein, một bác sĩ trẻ đầy triển vọng, bị tàn phá bởi cái chết của mẹ mình trong khi sinh nở, bị ám ảnh bởi việc hồi sinh người chết. Các thí nghiệm của anh ta dẫn đến việc tạo ra một con quái vật mà Frankenstein đã đặt cùng với phần còn lại của các xác chết. Không lâu trước khi Frankenstein hối hận về hành động của mình.</p>', 'Full', 1, 'single', 'completed', 14, 1994, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"Tom Hulce","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Aidan Quinn","avatar":""},{"name":"Ian Holm","avatar":""},{"name":"Richard Briers","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Robert Hardy","avatar":""},{"name":"Cherie Lunghi","avatar":""},{"name":"Celia Imrie","avatar":""},{"name":"Trevyn McDowell","avatar":""},{"name":"Mark Hadfield","avatar":""},{"name":"Gerard Horan","avatar":""},{"name":"Joanna Roth","avatar":""},{"name":"Alfred Bell","avatar":""},{"name":"Sasha Hanau","avatar":""},{"name":"Joseph Eng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"n