INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-z-broly-tro-lai-lan-nua', 'Bảy Viên Ngọc Rồng Z: Broly Trở Lại Lần Nữa', 'Dragon Ball Z: Broly – Second Coming', 'https://phimimg.com/upload/vod/20231125-1/0d84c3f8098d6ed802e0345ada1ab879.jpg', 'https://phimimg.com/upload/vod/20231125-1/5c256d1190cbccfb82843089f260b1d8.jpg', '<p>Broly đã trở lại và tìm cách trả thù Goku, không may là Goku đã qua đời. Liệu hành động lần này của hắn sẽ nhắm vào mục tiêu nào?</p>', 'Full', 1, 'hoathinh', 'completed', 16, 1994, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masako Nozawa","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Takeshi Kusao","avatar":""},{"name":"Yuko Minaguchi","avatar":""},{"name":"Junko Shimakata","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Hisao Egawa","avatar":""},{"name":"Yoshiyuki Kono","avatar":""},{"name":"Asuka Kimura","avatar":""},{"name":"Bin Shimada","avatar":""},{"name":"Hitoshi Takagi","avatar":""},{"name":"Joji Yanami","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324541);
