INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-vo-anh-hung', 'Tinh Võ Anh Hùng', 'Fist of Legend', 'https://phimimg.com/upload/vod/20231123-1/79a08af4011c68797974c2bae7a7acb4.jpg', 'https://phimimg.com/upload/vod/20231123-1/591d40776098e6bcedde3b5b02a96b6a.jpg', '<p>Trần Chân, đệ tử đầu tiên của Hoắc Nguyên Giáp, chiến đấu quên mình để cứu lấy Tinh Võ Môn sau cái chết của sư phụ. Trần Chân là một nhân vật nổi tiếng của điện ảnh Hồng Kông. Vị anh hùng này từng nhiều lần xuất hiện trên màn ảnh qua diễn xuất của những kỳ tài võ học như Lý Tiểu Long, Chung Tử Đơn... Đây được xem là một trong những bộ phim võ thuật hay nhất mọi thời đại và là vai diễn tuyệt vời nhất của Lý Liên Kiệt.</p>', 'Full', 1, 'single', 'completed', 15, 1994, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Shinobu Nakayama","avatar":""},{"name":"Chin Siu-ho","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Yasuaki Kurata","avatar":""},{"name":"Billy Chow Bei-Lei","avatar":""},{"name":"Ada Choi","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"Jackson Liu","avatar":""},{"name":"Suk-Mui Tam","avatar":""},{"name":"Wong San","avatar":""},{"name":"Derek Cheung Chi-Chuen","avatar":""},{"name":"Toshimichi Takahashi","avatar":""},{"name":"Mike Leeder","avatar":""},{"name":"Lee Man-Biu","avatar":""},{"name":"Shaun Britton","avatar":""},{"name":"Jimmy Wong Wa-Wo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324541);
