INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-beverly-hills-3', 'Cảnh Sát Beverly Hills 3', 'Beverly Hills Cop III', 'https://phimimg.com/upload/vod/20231114-1/e466b74855bd7099013422d56774085e.jpg', 'https://phimimg.com/upload/vod/20231114-1/748ea4b75df3a105b2ab63e1a11df144.jpg', '<p>“Beverly Hills Cop III là bộ phim hài hành động của Mỹ năm 1994 với sự tham gia của Eddie Murphy và đạo diễnJohn Landis. Đây là phần thứ ba trong loạt phim Beverly Hills Cop. &nbsp;Murphy tiếp tục vào vai cảnh sát Detroit Axel Foley, người một lần nữa quay trở lại Beverly Hills, California , để ngăn chặn một nhóm làm ăn phi pháp và cũng là những kẻ chịu trách nhiệm về cái chết của chỉ huy của anh. &nbsp;Foley hợp tác với bạn của anh, thám tử Billy Rosewood (Judge Reinhold), và cuộc điều tra đưa cả hai đến một công viên giải trí được gọi là Wonder World…”</p>', 'Full', 1, 'single', 'completed', 16, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Judge Reinhold","avatar":""},{"name":"Héctor Elizondo","avatar":""},{"name":"Timothy Carhart","avatar":""},{"name":"John Saxon","avatar":""},{"name":"Theresa Randle","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"Alan Young","avatar":""},{"name":"Gilbert R. Hill","avatar":""},{"name":"Bronson Pinchot","avatar":""},{"name":"Jon Tenney","avatar":""},{"name":"Joey Travolta","avatar":""},{"name":"Eugene Collier","avatar":""},{"name":"Jimmy Ortega","avatar":""},{"name":"Ousaun Elam","avatar":""},{"name":"Ray Lykins","avatar":""},{"name":"Tim Gilbert","avatar":""},{"name":"Rick","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-