INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tien-ti-hon', 'Nàng Tiên Tí Hon', 'Thumbelina', 'https://phimimg.com/upload/vod/20231113-1/05851ab77cb77e910b53609e8edb4cee.jpg', 'https://phimimg.com/upload/vod/20231113-1/af16b22458a2165d6115657940f33990.jpg', '<p>Sinh ra từ một bông hoa và chỉ cao vài inch, Thumbelina tội nghiệp lo lắng rằng cô sẽ không bao giờ gặp được ai đó có kích thước giống mình cho đến khi cô tình cờ lọt vào mắt xanh của Hoàng tử Cornelius của các nàng tiên. Tuy nhiên, ngay khi cô tìm thấy tình yêu thì nó đã bị cô cướp mất khi cô bị cô Cóc bắt cóc. Bây giờ Thumbelina phải thoát khỏi vòng vây của cô Cóc và tìm kiếm Hoàng tử Cornelius. May mắn thay, có cả một thành phố động vật sẵn sàng giúp đỡ cô.</p>', 'Full', 1, 'hoathinh', 'completed', 21, 1994, 'Vietsub', 'HD', 'Ireland', 0, '[{"name":"Jodi Benson","avatar":""},{"name":"Gino Conforti","avatar":""},{"name":"Barbara Cook","avatar":""},{"name":"Will Ryan","avatar":""},{"name":"June Foray","avatar":""},{"name":"Kenneth Mars","avatar":""},{"name":"Gary Imhoff","avatar":""},{"name":"Joe Lynch","avatar":""},{"name":"Charo","avatar":""},{"name":"Danny Mann","avatar":""},{"name":"Loren Lester","avatar":""},{"name":"Kendall Cunningham","avatar":""},{"name":"Tawny Sunshine Glover","avatar":""},{"name":"Michael Nunes","avatar":""},{"name":"Gilbert Gottfried","avatar":""},{"name":"Pat Musick","avatar":""},{"name":"Neil Ross","avatar":""},{"name":"Carol Channing","avatar":""},{"name":"Joh","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4