INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-cua-be', 'Một Ngày Của Bé', 'Baby''s Day Out', 'https://phimimg.com/upload/vod/20231111-1/1b976b43a1ff1d265a2223b3160b1828.jpg', 'https://phimimg.com/upload/vod/20231111-1/10b2e96a0d49b11d8e1b1db3c5e05db5.jpg', '<p>Một Ngày Của Bé &nbsp;là 1 bộ phim hài hước kể về cuộc phiêu lưu thú vị của cậu bé Bink 1 tuổi từ trong nôi ra ngoài đời. Vốn là con của 1 gia đình triệu phú, lúc mới sinh đã được bao bọc trong nhung lụa nên Bink dễ dàng trở thành mục tiêu của bọn bắt cóc tống tiền. Sau khi cải trang và chiếm được bé Bink, 3 tên tội phạm Eddie, Norby và Veeko vô cùng hí hửng vì nghĩ mình sắp vớ được 1 món hời lớn. &nbsp;Tuy nhiên, cũng từ đây, những rắc rối, không phải bắt nguồn từ cảnh sát mà từ chính cậu bé chỉ vừa mới chập chững biết bò này, đã liên tục xảy ra với bọn chúng. Eddie, Norby và Veeko lần lượt trở thành những “nạn nhân tội nghiệp” cho những trò nghịch phá hồn nhiên của Bink. Bằng sự thông minh, ngây thơ và hài hước cùng sự giúp đỡ của những nhân vật tốt bụng như chú đười ươi trong vườn thú, cô giữ trẻ hay những cựu chiến binh hóm hỉnh, Bink đã lần lượt cho bọn bắt cóc 1 bài học đích đáng, khiến bọn chúng phải bao phen sống dở chết dở.</p>', 'Full', 1, 'single', 'completed', 17, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joe Mantegna","avatar":""},{"name":"Lara Flynn Boyle","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Brian Haley","avatar":""},{"name":"Cynthia Nixon","avatar":""},{"name":"Fred Thompson","avatar":""},{"name":"John Neville","avatar":""},{"name":"Matthew Glave","avatar":""},{"name":"Adam Robert Worton","avatar":""},{"name":"Jacob Joseph Worton","avatar":""},{"name":"Brigid Duffy","avatar":""},{"name":"Guy Hadley","avatar":""},{"name":"Eddie Bracken","avatar":""},{"name":"Kenneth L. Jordahl","avatar":""},{"name":"Raymond Henderson","avatar":""},{"name":"Jim Foley","avatar":""},{"name":"Jac","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
