INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-dep-mien-tay', 'Những Người Đẹp Miền Tây', 'Bad Girls', 'https://phimimg.com/upload/vod/20231108-1/6afad927ed8a55a6afe3ee19415c1fc0.jpg', 'https://phimimg.com/upload/vod/20231108-1/ff43aa3abf9795e2bcb2309b48a89a71.jpg', '<p>Bốn cô gái điếm xinh đẹp bỏ trốn sau khi giết một người có thế lực. Họ định bỏ nghề bắt đầu một cuộc sống mới ở một vùng đất mới, nhưng không dễ dàng vì sự săn đuổi của các thám tử cùng với sự cản trở của những người quen cũ.</p>', 'Full', 1, 'single', 'completed', 23, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Madeleine Stowe","avatar":""},{"name":"Mary Stuart Masterson","avatar":""},{"name":"Andie MacDowell","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"James Russo","avatar":""},{"name":"James Le Gros","avatar":""},{"name":"Robert Loggia","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Jim Beaver","avatar":""},{"name":"Nick Chinlund","avatar":""},{"name":"Neil Summers","avatar":""},{"name":"Daniel O''Haco","avatar":""},{"name":"Richard Reyes","avatar":""},{"name":"Alex Kubik","avatar":""},{"name":"Will MacMillan","avatar":""},{"name":"Harry Northup","avatar":""},{"name":"Don","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324541);
