INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-noi-doi-chan-thuc', 'Lời Nói Dối Chân Thực', 'True Lies', 'https://phimimg.com/upload/vod/20231103-1/225d83feb70194dbfa02892145b5bf6d.jpg', 'https://phimimg.com/upload/vod/20231103-1/abcbde7651a09a52d8c49ab5a2ad9a73.jpg', '<p>Harry Tasker là một điệp viên bí mật cho Chính phủ Hoa Kỳ. Xem phim này bạn sẽ thấy trong nhiều năm, ông đã giữ kín công việc của mình với người vợ yêu quý của ông. Nhưng rồi một ngày kia, ông buộc phải tiết lộ danh tính của mình và cố gắng để ngăn chặn khủng bố hạt nhân khi ông và vợ bị bắt cóc bởi những kẻ khủng bố. Liệu vợ ông có chấp nhận một</p>', 'Full', 1, 'single', 'completed', 15, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Jamie Lee Curtis","avatar":""},{"name":"Tom Arnold","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Tia Carrere","avatar":""},{"name":"Art Malik","avatar":""},{"name":"Eliza Dushku","avatar":""},{"name":"Grant Heslov","avatar":""},{"name":"Charlton Heston","avatar":""},{"name":"Marshall Manesh","avatar":""},{"name":"James Allen","avatar":""},{"name":"Dieter Rauter","avatar":""},{"name":"Jane Morris","avatar":""},{"name":"Katsy Chappell","avatar":""},{"name":"Crystina Wyler","avatar":""},{"name":"Ofer Samra","avatar":""},{"name":"Paul Barselou","avatar":""},{"name":"Cha","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324541);
