INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-giet-nguoi-bam-sinh', 'Kẻ Giết Người Bẩm Sinh', 'Natural Born Killers', 'https://phimimg.com/upload/vod/20231103-1/22fae5f62c5c4802c6011fc2978a9d5c.jpg', 'https://phimimg.com/upload/vod/20231103-1/204769103e6db01bde279860dc8c873d.jpg', '<p>Hai kẻ bất hạnh Mickey và Mallory, những kẻ vô gia cư và là hai tên giết người hàng loạt. Mickey Knox, một tên giao thịt bò có người yêu là Mallory Wilson. Hắn giúp cô giết chết ông bố bệnh hoạn và thiêu cháy bà mẹ đang ngủ rồi cùng nhau bắt đầu cuộc hành trình rùng rợn trên đường Route 666. Cứ mỗi dặm, bọn họ lại tấn công những người đi cùng đường với mình…</p>', 'Full', 1, 'single', 'completed', 15, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Woody Harrelson","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"Robert Downey Jr.","avatar":""},{"name":"Tommy Lee Jones","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"Rodney Dangerfield","avatar":""},{"name":"Edie McClurg","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Russell Means","avatar":""},{"name":"Maria Pitillo","avatar":""},{"name":"Sean Stone","avatar":""},{"name":"Everett Quinton","avatar":""},{"name":"O-Lan Jones","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Steven Wright","avatar":""},{"name":"Lanny Flaherty","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
