INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-bat-hu', 'Tình Yêu Bất Hủ', 'Immortal Beloved', 'https://phimimg.com/upload/vod/20231101-1/eb3b277d43c8c030c2ee37957b1aaaa0.jpg', 'https://phimimg.com/upload/vod/20231101-1/878dc807faeed1e56a098e8b22704252.jpg', '<p>Biên niên sử về cuộc đời của nhà soạn nhạc cổ điển khét tiếng Ludwig van Beethoven và cuộc đấu tranh đau đớn của ông với chứng mất thính giác. Sau cái chết của Beethoven vào năm 1827, trợ lý của ông, Schindler, tìm kiếm một người phụ nữ khó nắm bắt được nhắc đến trong những bức thư tình của nhà soạn nhạc là &quot;người yêu bất tử&quot;. Khi Schindler giải đáp bí ẩn, một loạt đoạn hồi tưởng hé lộ quá trình biến đổi của Beethoven từ một chàng trai trẻ đầy nhiệt huyết thành một thiên tài âm nhạc đầy rắc rối.</p>', 'Full', 1, 'single', 'completed', 18, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gary Oldman","avatar":""},{"name":"Jeroen Krabbé","avatar":""},{"name":"Isabella Rossellini","avatar":""},{"name":"Johanna ter Steege","avatar":""},{"name":"Marco Hofschneider","avatar":""},{"name":"Miriam Margolyes","avatar":""},{"name":"Barry Humphries","avatar":""},{"name":"Valeria Golino","avatar":""},{"name":"Gerard Horan","avatar":""},{"name":"Christopher Fulford","avatar":""},{"name":"Luigi Diberti","avatar":""},{"name":"Michael Culkin","avatar":""},{"name":"Sandra Voe","avatar":""},{"name":"Bernard Rose","avatar":""},{"name":"Alexandra Pigg","avatar":""},{"name":"Donal G","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324541);
