INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-thoi-tien-su-2-phieu-luu-o-thung-lung-ky-vi', 'Vùng Đất Thời Tiền Sử 2: Phiêu Lưu Ở Thung Lũng Kỳ Vĩ', 'The Land Before Time II: The Great Valley Adventure', 'https://phimimg.com/upload/vod/20231101-1/48e163fa7953aa7aa14e1d1ec32cfb5a.jpg', 'https://phimimg.com/upload/vod/20231101-1/ec15e6a832ad8586a40d4a374f717787.jpg', '<p>Sau khi phát hiện bọn trộm trứng ở nơi ẩn náu bí mật của chúng, Chân Bé và nhóm bạn bắt đầu nhiệm vụ giải cứu táo bạo và phải tìm đường trở về nhà.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 1994, 'Vietsub', 'HD', 'Hàn Quốc', 0, '[{"name":"Scott McAfee","avatar":""},{"name":"Candace Hutson","avatar":""},{"name":"Heather Hogan","avatar":""},{"name":"Jeff Bennett","avatar":""},{"name":"Rob Paulsen","avatar":""},{"name":"Linda Gary","avatar":""},{"name":"Kenneth Mars","avatar":""},{"name":"John Ingle","avatar":""},{"name":"Tress MacNeille","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324541);
