INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-van-ma-ca-rong', 'Phỏng Vấn Ma Cà Rồng', 'Interview with the Vampire', 'https://phimimg.com/upload/vod/20231022-1/525c629dd45b08c1af46b82838e9d04e.jpg', 'https://phimimg.com/upload/vod/20231022-1/b1fc4cefa67945ce23b4082128793482.jpg', '<p>Một ma cà rồng kể lại câu chuyện cuộc đời sử thi về tình yêu, sự phản bội, sự cô đơn và cơn đói đen tối của mình với một phóng viên quá tò mò.</p>', 'Full', 1, 'single', 'completed', 14, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Stephen Rea","avatar":""},{"name":"Kirsten Dunst","avatar":""},{"name":"Domiziana Giordano","avatar":""},{"name":"Thandiwe Newton","avatar":""},{"name":"Indra Ové","avatar":""},{"name":"Laure Marsac","avatar":""},{"name":"Virginia McCollam","avatar":""},{"name":"John McConnell","avatar":""},{"name":"Mike Seelig","avatar":""},{"name":"Bellina Logan","avatar":""},{"name":"Lyla Hay Owen","avatar":""},{"name":"Lee E. Scharfstein","avatar":""},{"name":"Helen Mc","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324541);
