INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiem-hoa-hien-huu', 'Hiểm Họa Hiện Hữu', 'Clear and Present Danger', 'https://phimimg.com/upload/vod/20231016-1/1ee25afeef17aad168d01d6312d98766.jpg', 'https://phimimg.com/upload/vod/20231016-1/50d2982409651c116bcc08a3b20c7dc3.jpg', '<p>Chuyện phim dựa theo tiểu thuyết cùng tên của nhà văn Tom Clancy. Jack Ryan (Harrison Ford) là một điệp viên kỳ cựu của CIA. Anh đang thực thi một nhiệm vụ liên quan đến vụ buôn bán ma túy ở Colombia sau cuộc thảm sát trên chiếc thuyền ở Nam Caribbe. Khi người tiền nhiệm James Greer bị ung thư không thể tiếp tục xử lý vụ này, Jack Ryan được đề bạt làm Phó giám đốc CIA với nhiệm vụ đầu tiên trên cương vị mới là điều tra cái chết bí ẩn của một người bạn vong niên của tổng thống và toàn thể gia đình ông này bị ám sát trên chiếc thuyền nọ. Nhưng anh không ngờ trước đó, CIA đã phái một viên sĩ quan hiếu chiến chỉ huy lực lượng bủa vây băng nhóm này. Felix Cortez (Willem Dafoe) chính là kẻ đứng giữa hai phe phái đầy nguy hiểm này. ...</p>', 'Full', 1, 'single', 'completed', 17, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Anne Archer","avatar":""},{"name":"Joaquim de Almeida","avatar":""},{"name":"Henry Czerny","avatar":""},{"name":"Harris Yulin","avatar":""},{"name":"Donald Moffat","avatar":""},{"name":"Miguel Sandoval","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Raymond Cruz","avatar":""},{"name":"Dean Jones","avatar":""},{"name":"Thora Birch","avatar":""},{"name":"Ann Magnuson","avatar":""},{"name":"Hope Lange","avatar":""},{"name":"Tom Tammi","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"Ted Raimi","avatar":""},{"name":"Greg Germann","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324541);
