INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-dia', 'Thiên Địa', 'Heaven And Earth', 'https://phimimg.com/upload/vod/20231010-1/c14f0af4d2fee274fcb437f2bfc3d9a7.jpg', 'https://phimimg.com/upload/vod/20231010-1/37b35e28dd1d17c80c5425a87ede8081.jpg', '<p>Lấy bối cảnh những năm 1920, phim có sự tham gia của Lưu Đức Hoa trong vai một điều tra viên chính phủ Nam Kinh, gốc Quảng Đông, người đã được chính phủ bổ nhiệm làm Ủy viên đầu tiên của lệnh cấm buôn bán thuốc phiện.</p>', 'Full', 1, 'single', 'completed', 13, 1994, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Damian Lau","avatar":""},{"name":"Cherie Chan Siu-Ha","avatar":""},{"name":"Gu Bao-Ming","avatar":""},{"name":"King Shih-Chieh","avatar":""},{"name":"Yu Feihong","avatar":""},{"name":"Hon San","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
