INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-dia', 'Thiên Địa', 'Heaven And Earth', 'thiên địa heaven and earth andy lau damian lau cherie chan siu-ha gu bao-ming king shih-chieh yu feihong hon san ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('999-ai-la-ke-sat-nhan', '999 Ai Là Kẻ Sát Nhân', 'The Crucifixion', 'null', 'https://phimimg.com/upload/vod/20231010-1/26b2a42446a35a2922298d95664ba254.jpg', '<p>Các sĩ quan CID Ho Tin-nam (Michael Chow) và Jacky Wong (Hilary Tsui) đi theo một con chó hoang đến thi thể bị đóng đinh của một tài xế xe tải ở một vùng hẻo lánh. Phần lớn sự nghi ngờ tập trung vào người bạn lái xe tải Chan (Shing Fui-on), đặc biệt khi vợ của nạn nhân cũng bị giết. Khi không chỉ Chan mà cả con chó hoang tọc mạch cũng được thêm vào số nạn nhân ngày càng tăng, sự chú ý tập trung vào thỏa thuận giữa các tài xế với một gái điếm Trung Quốc tên Yin-fong. Cô từng là liên lạc viên bí mật của họ ở Thâm Quyến và đã tự sát khi những người đàn ông từ chối để cô ngừng cung cấp dịch vụ cho họ. Em gái song sinh của Yin-fong là Mei-ping (Miki Ng) cũng trở thành nghi phạm, nhưng một vụ giết người khác lại mang lại cho cô bằng chứng ngoại phạm. Cảnh sát Hồ Tin-nam và Jacky phải đối mặt với vô số manh mối cá trích đỏ và số lượng thi thể ngày càng tăng trước khi họ có thể đưa kẻ giết người thực sự ra trước công lý.</p>', 'Full', 1, 'single', 'completed', 21, 1994, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Michael Chow Man-Kin","avatar":""},{"name":"Hilary Tsui","avatar":""},{"name":"Timothy Zao","avatar":""},{"name":"Ivy Leung Si-Man","avatar":""},{"name":"Teresa Ha Ping","avatar":""},{"name":"Mikie Ng","avatar":""},{"name":"Jay Lau","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Joyce Geung Yung","avatar":""},{"name":"Helena Law Lan","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324541);
