INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-forrest-gump', 'Cuộc Đời Forrest Gump', 'Forrest Gump', 'https://phimimg.com/upload/vod/20230923-1/496cbec2d5df42fa0c816a7a9ee12206.jpg', 'https://phimimg.com/upload/vod/20230923-1/0238878e80d08aac4e1d4126f23840ba.jpg', '<p>Forrest Gump là một đứa trẻ bất hạnh khi sinh ra đã không có cha, hơn nữa Forrest còn bị thiểu năng. Forrest luôn bị bạn bè cùng trang lứa trêu trọc, bắt nạt. Người bạn duy nhất của Forrest là Jenny, chính Jenny đã phát hiện ra những khả năng đặc biệt của anh. Tốt nghiệp đại học Forrest nhập ngũ và tham chiến ở Việt Nam, Bubba trở thành bạn thân thứ 2 của anh. Forrest rời chiến trường với vết thương và khả năng chơi bóng bàn xuất sắc. Những biến cố nối tiếp nhau xuất hiện làm thay đổi hoàn toàn cuộc đời Forrest.</p>', 'Full', 1, 'single', 'completed', 26, 1994, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Gary Sinise","avatar":""},{"name":"Sally Field","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Michael Conner Humphreys","avatar":""},{"name":"Hanna Hall","avatar":""},{"name":"Haley Joel Osment","avatar":""},{"name":"Siobhan Fallon Hogan","avatar":""},{"name":"Rebecca Williams","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324541);
