INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hong-hy-quan', 'Hồng Hy Quan', 'Legend of the Red Dragon', 'https://phimimg.com/upload/vod/20230912-1/85c1669e1143ba4563a61fd907557c99.jpg', 'https://phimimg.com/upload/vod/20230912-1/b49c59255a8867c0c0bb8bd20cacd34b.jpg', '<p><span style="font-family: ">Hồng Hy Quan và người con trai 7 tuổi của mình phải bảo vệ cho 5 đứa trẻ có nguồn gốc từ Thiếu Lâm Tự vì chúng đang mang trên người tấm bản đồ dẫn đến một kho báu lớn bị thất lạc từ xưa. Nhưng liệu họ có thể tìm đến kho báu kia hay không khi mà theo sau họ là đối thủ truyền kiếp của Hồng Hy Quan, sư đệ đồng môn trước kia luôn có ganh tị với anh, Mã Linh Nhi kẻ giờ đây sau khi thoát chết đã biến thành quái nhân với võ công cao cường.</span></p>', 'Full', 1, 'single', 'completed', 37, 1994, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Chingmy Yau","avatar":""},{"name":"Tse Miu","avatar":""},{"name":"Damian Lau","avatar":""},{"name":"Chan Chung-Yung","avatar":""},{"name":"Deanie Ip","avatar":""},{"name":"Chunhua Ji","avatar":""},{"name":"Wong Jing","avatar":""},{"name":"Johnny Wang Lung-Wei","avatar":""},{"name":"Jiankui Sun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324541);
