INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-ba-ho-diem-thu-huong-1993', 'Đường Bá Hổ điểm Thu Hương', 'Flirting Scholar', 'https://phimimg.com/uploads/movies/20260713/duong-ba-ho-diem-thu-huong-1993-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/duong-ba-ho-diem-thu-huong-1993-poster.webp', '<p>Đường Bá Hổ điểm Thu Hương (1993) là một trong những bộ phim hài hay nhất của Châu Tinh Trì. Châu Tinh Trì vào vai Đường Bá Hổ, một anh chàng đào hoa và mê thơ, sống buồn chán với 8 bà vợ của mình. Cho đến một ngày kia, anh tìm được tình yêu đích thực của mình là Thu Hương nhưng gia đình hai bên không hợp nhau. Liệu Bá Hổ và Thu Hương có đến được với nhau chăng?</p>', 'Full', 1, 'single', 'completed', 37, 1993, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Gong Li","avatar":""},{"name":"Natalis Chan Pak-Cheung","avatar":""},{"name":"Cheng Pei-Pei","avatar":""},{"name":"Mimi Chu Mai-Mai","avatar":""},{"name":"Bryan Leung Kar-Yan","avatar":""},{"name":"Kingdom Yuen King-Tan","avatar":""},{"name":"James Wong Jim","avatar":""},{"name":"Gabriel Wong Yat-Shan","avatar":""},{"name":"Dickson Lee Kar-Sing","avatar":""},{"name":"Francis Ng Chun-Yu","avatar":""},{"name":"Chan Fai-Hung","avatar":""},{"name":"David Lam Wai","avatar":""},{"name":"Chu Tit-Wo","avatar":""},{"name":"Gordon Liu Chia-Hui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["唐伯虎点秋香","ถังไป่หู่ ใหญ่ไม่ต้องประกาศ","당백호점추향","唐伯虎點秋香","Flirting Scholar 1993 - Đường Bá Hổ, Điểm Thu Hương","Đường Bá Hổ, Điểm Thu Hương (1993)","The Flirting Scholar","Tang Bohu Dian Qiuxiang","Флиртующий ученый","Tong Pak Foo dim Chau Heung"]', 1784690324541);
