INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('duong-ba-ho-diem-thu-huong-1993', 'Đường Bá Hổ điểm Thu Hương', 'Flirting Scholar', 'đường bá hổ điểm thu hương flirting scholar stephen chow gong li natalis chan pak-cheung cheng pei-pei mimi chu mai-mai bryan leung kar-yan kingdom yuen king-tan james wong jim gabriel wong yat-shan dickson lee kar-sing francis ng chun-yu chan fai-hung david lam wai chu tit-wo gordon liu chia-hui châu tinh trì 唐伯虎点秋香 ถังไป่หู่ ใหญ่ไม่ต้องประกาศ 당백호점추향 唐伯虎點秋香 flirting scholar 1993 - đường bá hổ, điểm thu hương đường bá hổ, điểm thu hương (1993) the flirting scholar tang bohu dian qiuxiang флиртующий ученый tong pak foo dim chau heung', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-hoc-uy-long-iii', 'Trường Học Uy Long III', 'Fight Back to School 3', 'https://phimimg.com/uploads/movies/20260713/truong-hoc-uy-long-iii-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/truong-hoc-uy-long-iii-poster.webp', '<p>Trong phim Trường Học Uy Long 3 (1993), cảnh sát Chow được điều đi điều tra vụ ám sát nhà tỷ phú Million Wong, người mà có một sự giống nhau về ngoại hình đến kỳ lạ với Chow. Xem phim này, bạn sẽ thấy anh đã nhập vai nhà tỷ phú Wong và cảnh sát đã liên hệ với bà Wong để cho bà ta biết chồng bà vẫn còn sống và hiện mắc một chứng bệnh mất trí nhớ. Trong phim, qua buổi họp mặt với những người bạn cùng với gia đình của tỷ phú Wong, và trải qua bao nhiêu sự hiểu lầm, cuối cùng Chow cũng đã tìm được câu trả lời cho mình - Ai là thủ phạm?</p>', 'Full', 1, 'single', 'completed', 40, 1993, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Anita Mui Yim-Fong","avatar":""},{"name":"Sharla Cheung","avatar":""},{"name":"Natalis Chan Pak-Cheung","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Kathy Chow Hoi-Mei","avatar":""},{"name":"Mimi Chu Mai-Mai","avatar":""},{"name":"Bryan Leung Kar-Yan","avatar":""},{"name":"Philip Chan Yan-Kin","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"John Ching Tung","avatar":""},{"name":"Chang Gan-Wing","avatar":""},{"name":"Lee Yiu-King","avatar":""},{"name":"Wu Zhan-Peng","avatar":""},{"name":"Chang Seng-Kwong","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fight Back to School 3","도학위룡 3 - 용과계년","逃学威龙 3","Fight Back to School III","Fight Back to School III 1993 - Trường Học Uy Long 3","Trường Học Uy Long phần 3 (1993)","逃學威龍3","逃学威龙3：龙过鸡年","逃學威龍III：龍過雞年","逃学威龙3之龙过鸡年","逃學威龍III之龍過雞年"]', 1784690324541);
