INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-hoc-uy-long-iii', 'Trường Học Uy Long III', 'Fight Back to School 3', 'trường học uy long iii fight back to school 3 stephen chow anita mui yim-fong sharla cheung natalis chan pak-cheung anthony wong chau-sang kathy chow hoi-mei mimi chu mai-mai bryan leung kar-yan philip chan yan-kin paul chun pui john ching tung chang gan-wing lee yiu-king wu zhan-peng chang seng-kwong châu tinh trì fight back to school 3 도학위룡 3 - 용과계년 逃学威龙 3 fight back to school iii fight back to school iii 1993 - trường học uy long 3 trường học uy long phần 3 (1993) 逃學威龍3 逃学威龙3：龙过鸡年 逃學威龍iii：龍過雞年 逃学威龙3之龙过鸡年 逃學威龍iii之龍過雞年', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-ngay-nhuc-hinh', 'Ba Ngày Nhục Hình', '3 Days Of A Blind Girl', 'https://phimimg.com/upload/vod/20260511-1/c7995eb3e99d0d6fc17614e01edfaeef.jpg', 'https://phimimg.com/upload/vod/20260511-1/f88379d066e770fa50b85a7c1b3db726.jpg', '<p>Một cô gái trẻ ngày nọ bỗng bị mù sau một vụ tai nạn, dù chồng cô, vốn là một bác sĩ giỏi, đã cố hết sức. Trong một lần chồng đi xa, bỗng xuất hiện một gã đàn ông ở nhà cô. Hắn tiết lộ chồng cô đã từng hãm hiếp rồi giết chết vợ hắn nên giờ hắn phải trả thù. Một cô gái mù sẽ phải làm sao trong hoàn cảnh này ???</p>', 'Full', 1, 'single', 'completed', 19, 1993, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"葉玉卿","avatar":""},{"name":"黃秋生","avatar":""},{"name":"陳友","avatar":""},{"name":"陸劍明","avatar":""},{"name":"陳月茹","avatar":""},{"name":"張堅庭","avatar":""},{"name":"陳榮照","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Retribution Sight Unseen","Three Days of a Blind Girl","맹녀칠십이소시","Maang Lui 72 Siu Si","盲女七十二小时","盲女72小時"]', 1784690324541);
