INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rong-cau-chuyen-ve-bruce-lee', 'Rồng: Câu Chuyện Về Bruce Lee', 'Dragon: The Bruce Lee Story', 'https://phimimg.com/upload/vod/20260225-1/a6f34b9d81b5bd23ab033a874f7be036.jpg', 'https://phimimg.com/upload/vod/20260225-1/e13b275f3cddc3622a943ff422f3b9e0.jpg', '<p>Bộ phim là một cái nhìn thoáng qua về cuộc đời, tình yêu và tinh thần bất khuất của huyền thoại Lý Tiểu Long. Từ những ngày tháng thơ ấu rèn luyện võ thuật khắc nghiệt, Lý Tiểu Long hiện thực hóa giấc mơ mở trường dạy võ tại Mỹ. Không lâu sau, anh được một nhà sản xuất Hollywood phát hiện và bắt đầu hành trình vươn lên thành ngôi sao rực rỡ, cùng thời kỳ thống trị ngắn ngủi nhưng đầy huy hoàng của một trong những anh hùng hành động lôi cuốn nhất trong lịch sử điện ảnh.</p>', 'Full', 1, 'single', 'completed', 25, 1993, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Jason Scott Lee","avatar":""},{"name":"Lauren Holly","avatar":""},{"name":"Robert Wagner","avatar":""},{"name":"Michael Learned","avatar":""},{"name":"Nancy Kwan","avatar":""},{"name":"Lim Kay Tong","avatar":""},{"name":"Ric Young","avatar":""},{"name":"Wang Luoyong","avatar":""},{"name":"Sterling Macer Jr.","avatar":""},{"name":"Sven-Ole Thorsen","avatar":""},{"name":"Ong Soo Han","avatar":""},{"name":"Eric Bruskotter","avatar":""},{"name":"Aki Aleong","avatar":""},{"name":"Chao-Li Chi","avatar":""},{"name":"Sam Hau","avatar":""},{"name":"Iain M. Parker","avatar":""},{"name":"Michelle Tennant","avatar":""},{"name":"Clyde","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","