INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-dinh-addams-2-nhung-gia-tri-song-cua-gia-dinh-addams', 'Gia Đình Addams 2 (Những Giá Trị Sống Của Gia Đình Addams)', 'Addams Family Values', 'gia đình addams 2 (những giá trị sống của gia đình addams) addams family values anjelica huston raúl juliá christopher lloyd joan cusack christina ricci carol kane jimmy workman david krumholtz peter macnicol christine baranski carel struycken christopher hart dana ivey kaitlyn hooper kristen hooper mercedes mcnab sam 阿达一族 сімейка адамсів 2: моральні цінності семейные ценности аддамс los locos addams 2 החיים על פי משפחת אדאמס familien addams – og synet på livet la famille addams 2, les valeurs de la famille addams the addams family values die addams family in verrückter tradition addamsova rodina 2 obitelj addams 2 a família addams 2 addams family values', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngan-ho-ve-dem', 'Ngân Hồ Về Đêm', 'The Silver Tycoon', 'https://phimimg.com/upload/vod/20251023-1/43507e3513bda974fb14fa03a96b8428.jpg', 'https://phimimg.com/upload/vod/20251023-1/b640c71d5efcfc2c390844e47e82d5e8.jpg', '<p>Đoàn Thiệu Tường là phú thương trẻ tuổi, đẹp trai ở Thượng Hải. Miêu Mẫn Linh rất thần tượng Thiệu Tường nhưng anh chỉ yêu vị hôn thê Lương Tích Mai đang sống ở Hồng Kông. Cô có người anh rể tên Tống Học Lễ, vốn là người thô thiển, thiếu văn hóa. Con trai của Học Lễ tên Tống Sĩ Nguyên, vốn là bạn thân của Thiệu Tường. Hai người có cùng ước mơ biến Thượng Hải thành Hollywood của Trung Quốc.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 15, 1993, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Felix Wong Yat-Wah","avatar":""},{"name":"Sunny Fang Kang","avatar":""},{"name":"Kwong Wa","avatar":""},{"name":"Margie Tsang Wah-Sin","avatar":""},{"name":"Jackie Lui Chung-Yin","avatar":""},{"name":"Erica Choi Hiu-Yee","avatar":""},{"name":"Christine Ng Wing-Mei","avatar":""},{"name":"Nick Cheung Ka-Fai","avatar":""},{"name":"Jay Lau Kam-Ling","avatar":""},{"name":"Nina Paw Hei-Ching","avatar":""},{"name":"Lee Heung-Kam","avatar":""},{"name":"Sunny Chan Kam-Hung","avatar":""},{"name":"Tam Bing-Man","avatar":""},{"name":"Lok Pooi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["銀狐"]', 1784690324541);
