INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-duong-toi-loi-cua-carlito', 'Con Đường Tội Lỗi Của Carlito', 'Carlito''s Way', 'con đường tội lỗi của carlito carlito''s way al pacino sean penn penelope ann miller john leguizamo ingrid rogers luis guzmán james rebhorn joseph siravo viggo mortensen richard foronjy jorge porcel frank minucci adrian pasdar john ortiz ángel salazar al israel rick aviles jaime sán l''impasse carlito carlitova cesta atrapado por su pasado путь карлито o pagamento final à la manière de carlito fanget af fortiden υπόθεση καρλίτο carlitov način carlito útja karlito kelias carlitos weg путь карлитo perseguido pelo passado 情梟的黎明 カリートの道 カリートの道：1993 carlito''s way', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-thanh-pho-1993', 'Thợ Săn Thành Phố', 'City Hunter', 'https://phimimg.com/upload/vod/20250810-1/e1d2f6be7e7ea2c1237a799ec29e1e5f.jpg', 'https://phimimg.com/upload/vod/20250810-1/2a1a31901ad5b1ddcc44a1aab9f0fc17.jpg', '<p>Bộ phim xoay quanh Ryo Saeba (Thành Long đóng) – một thám tử tư tài giỏi nhưng có tính cách hào hoa, mê gái. Anh được thuê để tìm con gái mất tích của một trùm báo chí. Cuộc điều tra đưa anh lên một con tàu sang trọng, nơi tình cờ tập trung nhiều băng nhóm tội phạm nguy hiểm. Trên tàu, Ryo không chỉ phải tìm ra cô gái mà còn phải đối mặt với một nhóm khủng bố âm mưu chiếm đoạt con tàu. Trong hành trình, anh có những pha hành động kịch tính, xen lẫn các tình huống hài hước và những màn cải trang khó đỡ. Phim kết hợp phong cách hành động võ thuật đặc trưng của Thành Long với yếu tố hài lãng mạn, mang lại một trải nghiệm giải trí sôi động và đầy màu sắc.</p>', 'Full', 1, 'single', 'completed', 18, 1993, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Thành Long","avatar":""},{"name":"Trưởng Khả Ninh","avatar":""},{"name":"Cổ Đình Kính","avatar":""},{"name":"Yêu Nga","avatar":""},{"name":"Cao Hổ","avatar":""},{"name":"Richard Norton","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sing si lip yan","城市獵人","City Hunter","Niki Larson","Jackie Chan City Hunter","Cazador de ciudad","Cazador urbano","O Caçador de Encrencas","City Hunter - O Caçador de Encrencas","Şehir Avcısı","城市猎人","Městský lovec","시티 헌터","시티헌터"]', 1784690324541);
