INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tho-san-thanh-pho-1993', 'Thợ Săn Thành Phố', 'City Hunter', 'thợ săn thành phố city hunter thành long trưởng khả ninh cổ đình kính yêu nga cao hổ richard norton jackie chan sing si lip yan 城市獵人 city hunter niki larson jackie chan city hunter cazador de ciudad cazador urbano o caçador de encrencas city hunter - o caçador de encrencas şehir avcısı 城市猎人 městský lovec 시티 헌터 시티헌터', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diet-mon-tham-an', 'Diệt Môn Thảm Án', 'Daughter Of Darkness', 'https://phimimg.com/upload/vod/20250806-1/479169afd09f7e0139bd9cf80ecc4868.jpg', 'https://phimimg.com/upload/vod/20250806-1/995fdc7c9480f26e17373fa041cf0c01.jpg', '<p>A Huệ là con nuôi trong gia đình, sống cuộc đời bị áp bức, phải nhẫn nhịn dưới mái nhà người khác. Một hôm, cha nuôi A Mạch say rượu và mất hết nhân tính, cưỡng hiếp cô. Bị xúc phạm nhưng không ai che chở, A Huệ nghĩ đến bạn trai A Kỳ nhưng vì không muốn anh đau khổ nên giấu kín sự thật. Sau đó, A Mạch càng lấn tới, dùng ảnh khỏa thân để uy hiếp cô. Trong lúc giằng co, A Kỳ bắt gặp và tức giận bắn trọng thương A Mạch, nhưng bị đánh ngất. Trong cơn phẫn nộ và tuyệt vọng, A Huệ cầm súng bắn chết cả gia đình rồi đến đồn cảnh sát tự thú, nhận hết tội lỗi về mình. Tuy nhiên, khi nghe hết sự thật, viên cảnh sát tiếp nhận vụ án đã động lòng thương cảm với cô.</p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Lily Chung Suk-Wai","avatar":""},{"name":"Hugo Ng","avatar":""},{"name":"William Ho","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Money Lo Man-Yee","avatar":""},{"name":"Lo Hung","avatar":""},{"name":"Chiu Wai","avatar":""},{"name":"Gam Biu","avatar":""},{"name":"Lee Wan-Fei","avatar":""},{"name":"Che Kau-Wa","avatar":""},{"name":"Ng Chin-Yan","avatar":""},{"name":"Chan Yuk-Kwan","avatar":""},{"name":"Lee Sam","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Daughter of Darkness","쇼킹홍콩2","滅門慘案之孽殺","灭门惨案之孽杀"]', 1784690324541);
