INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-vien-ky-jura', 'Công Viên Kỷ Jura', 'Jurassic Park', 'https://phimimg.com/upload/vod/20250717-1/5bb04db763f3c3cce9bb22d393a81832.jpg', 'https://phimimg.com/upload/vod/20250717-1/54a3425c026b7a295f6c3874223e8270.jpg', '<p>Mong muốn tái sinh những loài Khủng Long, nhà tài phiệt John Hammond đã xây dựng trung tâm nghiên cứu trên một hòn đảo bí mật và những chú Khủng Long lần lượt ra đời. Vui mừng trước thành quả đạt được, John mời nhóm các nhà khoa học tới chiêm ngưỡng thành quả của mình nhưng thật không may trong đêm mưa bão hệ thống bảo vệ gặp trục trặc, hàng trăm con Khủng Long đã thoát ra ngoài...</p>', 'Full', 1, 'single', 'completed', 17, 1993, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sam Neill","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Richard Attenborough","avatar":""},{"name":"Bob Peck","avatar":""},{"name":"Martin Ferrero","avatar":""},{"name":"BD Wong","avatar":""},{"name":"Joseph Mazzello","avatar":""},{"name":"Ariana Richards","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Wayne Knight","avatar":""},{"name":"Gerald R. Molen","avatar":""},{"name":"Miguel Sandoval","avatar":""},{"name":"Cameron Thor","avatar":""},{"name":"Christopher John Fields","avatar":""},{"name":"Whit Hertford","avatar":""},{"name":"Dean","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jurassic Park (Remastered)","Park Ha-Yura","Park iz doba jure","حديقة جوراسية","จูราสสิค ปาร์ค 1 : กำเนิดใหม่ไดโนเสาร์","Jurassic Park 1","侏罗纪公园","ジュラシック・パーク","Parque Jurásico (Jurassic Park)","Dzhurasik park","Jurassic Park I","Jurassic Park 3D","Յուրայի դարաշրջանի այգին","Jurassic Park - O Parque dos Dinossauros","Jurassic Park"]', 1784690324541);
