INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-dai-duong', 'Sóng Đại Dương', 'Ocean Waves', 'https://phimimg.com/upload/vod/20250715-1/e0c292311c5efd187f535116ea4c72bb.jpg', 'https://phimimg.com/upload/vod/20250715-1/8c4034ce583e07e4b01318e7c771ff86.jpg', '<p>Là một phim nói về tình cảm lứa tuổi học trò, 72 phút của Ocean Waves trôi qua một cách lặng lẽ, để lại nhiều cảm xúc, làm cho người xem hồi tưởng lại một thời cắp sách đến trường, một tình yêu chớm nở nhưng lại giữ kín trong tim, để rồi bất giác một lúc nào đó, ta lại nhớ đến một bóng hình...</p>', 'Full', 1, 'hoathinh', 'completed', 17, 1993, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuo Tobita","avatar":""},{"name":"Yoko Sakamoto","avatar":""},{"name":"Toshihiko Seki","avatar":""},{"name":"Yuri Amano","avatar":""},{"name":"Kae Araki","avatar":""},{"name":"Jun''ichi Kanemaru","avatar":""},{"name":"Ai Satou","avatar":""},{"name":"Aya Hisakawa","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Hikaru Midorikawa","avatar":""},{"name":"Sumi Shimamoto","avatar":""},{"name":"Reiko Suzuki","avatar":""},{"name":"Kinryu Arimoto","avatar":""},{"name":"Takeshi Watabe","avatar":""},{"name":"Ako Mayama","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["I Can Hear the Sea","Umi ga Kikoeru","海がきこえる","听到涛声","바다가 들린다","海潮之声","听见涛声","โอเชียน เวฟส์ สองหัวใจหนึ่งรักเดียว","Tu peux entendre la mer","Hai Chao Zhi Sheng","Amvaj-e Oghyanoos","Puc escoltar el mar","Eu Posso Ouvir o Oceano","Хвилі океану","Мен