INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('song-dai-duong', 'Sóng Đại Dương', 'Ocean Waves', 'sóng đại dương ocean waves nobuo tobita yoko sakamoto toshihiko seki yuri amano kae araki jun''ichi kanemaru ai satou aya hisakawa tomokazu seki hikaru midorikawa sumi shimamoto reiko suzuki kinryu arimoto takeshi watabe ako mayama i can hear the sea umi ga kikoeru 海がきこえる 听到涛声 바다가 들린다 海潮之声 听见涛声 โอเชียน เวฟส์ สองหัวใจหนึ่งรักเดียว tu peux entendre la mer hai chao zhi sheng amvaj-e oghyanoos puc escoltar el mar eu posso ouvir o oceano хвилі океану мені чутний океан', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-thien-than', 'Đôi Mắt Thiên Thần', 'Angel Eyes', 'https://phimimg.com/upload/vod/20250602-1/d27eb915f9953bf00b153d9e666c46a3.jpg', 'https://phimimg.com/upload/vod/20250602-1/ed56b2dc25311ef02c8ad726fcd96ea1.jpg', '<p>Angel là một thiếu nữ có tâm lý bất ổn, mang trong mình nỗi ám ảnh bệnh hoạn với người cha dượng Steven. Sau cái chết đầy nghi vấn của mẹ, Angel bị đưa vào cơ sở điều trị tâm thần. Nhiều năm sau, cô được thả ra và tìm đến Steven, người hiện đang sống cùng bạn gái mới, Michelle. Steven, với lòng trắc ẩn, đồng ý cho Angel ở lại, nhưng không biết rằng cô vẫn mang trong mình những ám ảnh cũ.Angel bắt đầu thực hiện những hành động nguy hiểm, từ việc quyến rũ Steven đến việc tìm cách loại bỏ Michelle. Cô thậm chí còn cố gắng quyến rũ cả Michelle, tạo nên một mối quan hệ đầy căng thẳng và nguy hiểm. Trong khi đó, Steven cũng phải đối mặt với một mối đe dọa khác từ tên trùm ma túy Johnny Ventura.</p>', 'Full', 1, 'single', 'completed', 32, 1993, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Erik Estrada","avatar":""},{"name":"John Phillip Law","avatar":""},{"name":"Monique Gabrielle","avatar":""},{"name":"Raven","avatar":""},{"name":"John Coleman","avatar":""},{"name":"Hoke Howell","avatar":""},{"name":"Richard Harrison","avatar":""},{"name":"Suzanne Ager","avatar":""},{"name":"Martin Nicholas","avatar":""},{"name":"Robert Quarry","avatar":""},{"name":"Sazzy Lee Calhoun","avatar":""},{"name":"Paula Revee","avatar":""},{"name":"Fred Olen Ray","avatar":""},{"name":"Gail Jensen","avatar":""},{"name":"Morgan Connelly","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Angel Eyes"]', 1784690324541);
