INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-mat-thien-than', 'Đôi Mắt Thiên Thần', 'Angel Eyes', 'đôi mắt thiên thần angel eyes erik estrada john phillip law monique gabrielle raven john coleman hoke howell richard harrison suzanne ager martin nicholas robert quarry sazzy lee calhoun paula revee fred olen ray gail jensen morgan connelly angel eyes', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-gettysburg', 'Cuộc chiến Gettysburg', 'Gettysburg', 'https://phimimg.com/upload/vod/20250601-1/83233aa8a12cbd1a7eca73860dff5f4c.jpg', 'https://phimimg.com/upload/vod/20250601-1/b2c5226082789f63da5057b7ed8f84eb.jpg', '<p>Bộ phim lịch sử – chiến tranh sử thi của Mỹ, tái hiện trận đánh Gettysburg nổi tiếng trong cuộc Nội chiến Hoa Kỳ, diễn ra từ ngày 1 đến ngày 3 tháng 7 năm 1863. Đây là một trong những trận chiến quan trọng và đẫm máu nhất của cuộc chiến, được coi là bước ngoặt trong lịch sử nước Mỹ.</p>', 'Full', 1, 'single', 'completed', 19, 1993, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jeff Daniels","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Sam Elliott","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"C. Thomas Howell","avatar":""},{"name":"Richard Anderson","avatar":""},{"name":"Richard Jordan","avatar":""},{"name":"Kevin Conway","avatar":""},{"name":"Andrew Prine","avatar":""},{"name":"Cooper Huckabee","avatar":""},{"name":"Patrick Gorman","avatar":""},{"name":"Bo Brinkman","avatar":""},{"name":"James Lancaster","avatar":""},{"name":"Kieran Mulroney","avatar":""},{"name":"James Patrick Stuart","avatar":""},{"name":"Tim","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Gettysburg 1993","盖茨堡之役","美国战火","Gettysburg"]', 1784690324541);
