INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-gettysburg', 'Cuộc chiến Gettysburg', 'Gettysburg', 'cuộc chiến gettysburg gettysburg jeff daniels tom berenger martin sheen sam elliott stephen lang c. thomas howell richard anderson richard jordan kevin conway andrew prine cooper huckabee patrick gorman bo brinkman james lancaster kieran mulroney james patrick stuart tim gettysburg 1993 盖茨堡之役 美国战火 gettysburg', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-me-cung-thiec', 'Doraemon: Nobita và Mê Cung Thiếc', 'Doraemon: Nobita and the Tin Labyrinth', 'https://phimimg.com/upload/vod/20250521-1/7460d3da1db05f1bb0e9052b6ea88c37.jpg', 'https://phimimg.com/upload/vod/20250521-1/a8cf6f67a982cb577331561b4feb4a44.jpg', '<p>Bố Nobita tình cờ thấy một quảng cáo kỳ lạ về một khu nghỉ dưỡng tuyệt vời trên truyền hình vào lúc nửa đêm. Đang buồn ngủ, anh ấy đặt chỗ trước dù thậm chí không nhận ra mình đang nói chuyện với quảng cáo. Ngày hôm sau, anh thảo luận với gia đình về kế hoạch kỳ nghỉ của họ, chỉ để nhận ra rằng anh không thể tìm thấy nơi nào trên trái đất. Đột nhiên, mặc dù có một chiếc vali trong phòng Nobita và bị tò mò như vậy, cậu mở nó ra chỉ để tìm thấy cánh cổng dẫn đến một khu nghỉ dưỡng xinh đẹp được quản lý bởi những con rô bốt thiếc. Vẫn tốt hơn, nó hoàn toàn miễn phí. Có vẻ như có một chương trình nghị sự ẩn đằng sau người mời họ đến đó.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 1993, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Sachiko Chijimatsu","avatar":""},{"name":"Yôsuke Naka","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Nobuyo Oyama","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Nobita and Tin-Plate Labyrinth","白金迷宮","Doraemon: Nobita and Tin-Plate Labyrinth","Doraemon i el secret del laberint","Doraemon y el secreto del laberinto","Doraemon Nobita to Buriki no Rabirinsu","Nobita and the Tin Labyrinth","大雄與白金迷宮","大雄在白金迷宮","도라에몽: 노비타와 브리키의 미궁","哆啦A夢：大雄與白金迷宮","Doraemon the Movie: खेल खिलौना भूल भूलैया","哆啦A梦：大雄和白金迷宫","도라에몽: 진구와 양철인형","도라에몽 극장판: 진구와 양철인형","Doraemon: Istana Emas Putih","映画ドラえもん のび太とブリキの迷宮（ラビリンス）","Operasi Di Planet Zamu","映画ドラえもん のび太とブリキの迷宮"]', 1784690324541);
