INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-me-cung-thiec', 'Doraemon: Nobita và Mê Cung Thiếc', 'Doraemon: Nobita and the Tin Labyrinth', 'doraemon: nobita và mê cung thiếc doraemon: nobita and the tin labyrinth noriko ohara michiko nomura kazuya tatekabe sachiko chijimatsu yôsuke naka kaneta kimotsuki nobuyo oyama nobita and tin-plate labyrinth 白金迷宮 doraemon: nobita and tin-plate labyrinth doraemon i el secret del laberint doraemon y el secreto del laberinto doraemon nobita to buriki no rabirinsu nobita and the tin labyrinth 大雄與白金迷宮 大雄在白金迷宮 도라에몽: 노비타와 브리키의 미궁 哆啦a夢：大雄與白金迷宮 doraemon the movie: खेल खिलौना भूल भूलैया 哆啦a梦：大雄和白金迷宫 도라에몽: 진구와 양철인형 도라에몽 극장판: 진구와 양철인형 doraemon: istana emas putih 映画ドラえもん のび太とブリキの迷宮（ラビリンス） operasi di planet zamu 映画ドラえもん のび太とブリキの迷宮', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong-ngoai-truyen-than-ke-dau-ngo-cong', 'Hoàng Phi Hồng Ngoại Truyện: Thần Kê Đấu Ngô Công', 'Last Hero In China', 'https://phimimg.com/upload/vod/20250523-1/a35bd510d9a7d4f8806cc063045bc181.jpg', 'https://phimimg.com/upload/vod/20250523-1/8197c2bea105c4025cb7cb89cdaa48f5.jpg', '<p>Phật Sơn liên tiếp xảy ra những vụ mất tích của các cô gái trẻ khiến người dân lo lắng không yên. Phi Hồng và các đệ tử Bảo Chi Lâm lên một kế hoạch giăng bẫy để bọn bắt cóc lộ mặt, cả bọn dùng dì Thập Tam làm mồi nhử. Lần theo dấu vết các cô giá trẻ bị bán cho lầu xanh, Hoàng Phi Hồng tìm ra kẻ chủ mưu là một tên ác tăng tại Năng Nhân Tự, cùng cấu kết với tên cẩu quan Thiên Tổng của triều đình. Trúng gian kế của kẻ địch, Phi Hồng mất đi thính giác và bị đánh bại... Anh sẽ phải làm gì để khôi phục danh dự và chiến thắng kẻ thù?</p>', 'Full', 1, 'single', 'completed', 17, 1993, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Lý Liên Kiệt","avatar":""},{"name":"Trương Mẫn","avatar":""},{"name":"Trương Vệ Kiện","avatar":""},{"name":"Trần Bách Tường","avatar":""},{"name":"Lương Gia Nhân","avatar":""},{"name":"Viên Vịnh Nghi","avatar":""},{"name":"Từ Trung Tín","avatar":""},{"name":"Lưu Gia Huy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Claws of Steel","Deadly China Hero","Huang Fei Hong 5: Tie ji dou wu gong","Iron Rooster vs. the Centipede","Tie ji dou wu gong","Acélkarmok","Wong Fei Hung ji Tit gai dau ng gung","Last Hero in China","황비홍 - 철계투오공","黄飞鸿之铁鸡斗蜈蚣","последний герой китая","黃飛鴻之鐵雞鬥蜈蚣"]', 1784690324541);
