INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoang-phi-hong-ngoai-truyen-than-ke-dau-ngo-cong', 'Hoàng Phi Hồng Ngoại Truyện: Thần Kê Đấu Ngô Công', 'Last Hero In China', 'hoàng phi hồng ngoại truyện: thần kê đấu ngô công last hero in china lý liên kiệt trương mẫn trương vệ kiện trần bách tường lương gia nhân viên vịnh nghi từ trung tín lưu gia huy jet li claws of steel deadly china hero huang fei hong 5: tie ji dou wu gong iron rooster vs. the centipede tie ji dou wu gong acélkarmok wong fei hung ji tit gai dau ng gung last hero in china 황비홍 - 철계투오공 黄飞鸿之铁鸡斗蜈蚣 последний герой китая 黃飛鴻之鐵雞鬥蜈蚣', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chu-ben-thuong-hai-phan-1', 'Bá Chủ Bến Thượng Hải (Phần 1)', 'Shanghai Godfather (Season 1)', 'https://phimimg.com/upload/vod/20250522-1/4bd7feaa49cf78aeee32fe30369241e2.jpg', 'https://phimimg.com/upload/vod/20250522-1/1b3e52d88a095809f1b22287dd67c99f.jpg', '<p>Bộ phim&nbsp;khai thác cuộc sống phồn vinh nhưng vô cùng phức tạp nơi Bến Thượng Hải trong những năm 30 của thế kỷ trước giống như Máu Nhuộm Bến Thượng Hải kinh điển của TVB ra mắt năm nào. Từ làng quê nghèo, Nhân vật chính của Bá Chủ Bến Thượng Hải là chàng trai Đỗ Quốc Sinh, từ làng quê nghèo, một mình anh khăn gói lên Thượng Hải với mơ ước đổi đời. Tuổi thơ khốn khó đã hình thành trong Sinh một quyết tâm to lớn mong một ngày không xa sẽ thoát khỏi sự cùng quẫn vì cái nghèo bằng mọi giá. Trong một lần tình cờ, anh đánh nhau với Trương Thiết Lâm, rồi cuối cùng hai người trở thành huynh đệ tốt của nhau, vươn lên có chút tiếng tăm ở bến Thượng Hải. Trương Thiết Lâm là người hào sảng xả thân vì huynh đệ nhưng điểm yếu của anh ta chính là tính khí nóng nảy, thường mất bình tĩnh trong hành động, vì thế đã bị kẻ xấu lợi dụng và chống đối lại Đỗ Quốc Sinh khi mà sự thành công và thế lực của người này lại chính là cái gai trong mắt kẻ khác.. Số phận buộc anh trở thành đại ca khét tiếng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 16, 1993, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Đình Oai","avatar":""},{"name":"Lưu Ngọc Đình","avatar":""},{"name":"Lý Hương Cầm","avatar":""},{"name":"Trần Ỷ Minh","avatar":""},{"name":"Ngô Nghị Tướng","avatar":""},{"name":"Tần Bái","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["上海皇帝杜月笙","中国教父","再見黃埔灘"]', 1784690324541);
