INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-trek-the-he-tiep-theo-phan-7', 'Star Trek: Thế Hệ Tiếp Theo (Phần 7)', 'Star Trek: The Next Generation (Season 7)', 'https://phimimg.com/upload/vod/20250519-1/794862b1e411330c9dfa8d603275c86d.jpg', 'https://phimimg.com/upload/vod/20250519-1/eb58e2392a878274dbc1392114914495.jpg', '<p>Nhiều thập kỷ sau cuộc phiêu lưu của phi hành đoàn Enterprise đầu tiên, Thuyền trưởng Jean-Luc Picard chỉ huy tàu Enterprise mới với sứ mệnh khám phá những thế giới mới.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 15, 1993, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patrick Stewart","avatar":""},{"name":"Jonathan Frakes","avatar":""},{"name":"Brent Spiner","avatar":""},{"name":"LeVar Burton","avatar":""},{"name":"Michael Dorn","avatar":""},{"name":"Marina Sirtis","avatar":""},{"name":"Gates McFadden","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["星际旅行：下一代","Star Trek: Das nächste Jahrhundert","Star Trek: Die nächste Generation","스타 트렉: 넥스트 제너레이션","스타트렉: 넥스트 제너레이션","Viaje a las estrellas: La Nueva Generacion","Star Trek TNG","Star Trek: The Next Generation"]', 1784690324541);
