INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-tombstone', 'Thị Trấn Tombstone', 'Tombstone', 'https://phimimg.com/upload/vod/20250511-1/56c015a7f920690ba83c85a3ab89d386.jpg', 'https://phimimg.com/upload/vod/20250511-1/ae5b10a1b5c25849cade1777a01e00b4.jpg', '<p>Bộ phim dựa trên một vụ đấu súng nổi tiếng ở thị trấn Tombstone vào năm 1881. Ngày 26/10/1881, một nhóm xã hội đen tấn công cảnh sát trưởng của thị trấn Tombstone và những người thân của ông. Chỉ trong 30 giây, người ta nghe thấy khoảng 30 phát súng. Mặc dù ngắn ngủi, sự kiện này được coi là biểu tượng cho cuộc đấu tranh khốc liệt giữa luật pháp và tình trạng vô chính phủ ở miền Tây nước Mỹ trong thế kỷ 19.</p>', 'Full', 1, 'single', 'completed', 20, 1993, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kurt Russell","avatar":""},{"name":"Val Kilmer","avatar":""},{"name":"Sam Elliott","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Powers Boothe","avatar":""},{"name":"Michael Biehn","avatar":""},{"name":"Charlton Heston","avatar":""},{"name":"Jason Priestley","avatar":""},{"name":"Jon Tenney","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"Thomas Haden Church","avatar":""},{"name":"Dana Delany","avatar":""},{"name":"Paula Malcomson","avatar":""},{"name":"Lisa Collins","avatar":""},{"name":"Dana Wheeler-Nicholson","avatar":""},{"name":"Joanna Pacula","avatar":""},{"name":"Michael R","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Σύγκρουση στον Πράσινο Βάλτο","Tombstone: La leyenda de Wyatt Earp","Tombstone","Tombstone: A Justiça Está Chegando"]', 1784690324541);
