INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-sach-schindler', 'Danh Sách Schindler', 'Schindler''s List', 'https://phimimg.com/upload/vod/20250309-1/fd208d112df33f5bc3594fd3275e5db9.jpg', 'https://phimimg.com/upload/vod/20250309-1/8658ea2d0f5edfa43404303573cf76f7.jpg', '<p>Bản danh sách của Schindler (Schindler`s List) là một bộ phim truyện sản xuất năm 1993 của Hoa Kỳ về Oskar Schindler, một nhà kinh doanh người Đức. Phim bắt đầu vào năm 1939 với sự tập trung người Ba Lan gốc Do Thái của chính quyền Đức Quốc Xã sau khi xâm lược Ba Lan, từ việc bao vây, giam lỏng trong vùng tới xây dựng những khu tập trung Kraków Ghetto không lâu sau khi Đệ nhị thế chiến bắt đầu. Trong lúc đó, Oskar Schindler (Liam Neeson), một doanh nhân thất bại, đến thành phố từ Sudetenland với những hy vọng làm giàu.</p>', 'Full', 1, 'single', 'completed', 14, 1993, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Caroline Goodall","avatar":""},{"name":"Jonathan Sagall","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"Malgorzata Gebel","avatar":""},{"name":"Shmuel Levy","avatar":""},{"name":"Mark Ivanir","avatar":""},{"name":"Béatrice Macola","avatar":""},{"name":"Andrzej Seweryn","avatar":""},{"name":"Friedrich von Thun","avatar":""},{"name":"Krzysztof Luft","avatar":""},{"name":"Harry Nehring","avatar":""},{"name":"Norbert Weisser","avatar":""},{"name":"Adi Nitzan","avatar":""},{"name":"Mich","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["قائمة شندلر","舒特拉的名單","Lista Shindlera","シンドラーのリスト","シンドラーのリスト：1993","Schindlers List","Η Λίστα του Σίντλερ","La lista de Schindler","辛德勒的名單","Շինդլերի Ցուցակը","רשימת שינדלר","Schindler''s List - La lista di Schindler","Спіс Шындлера","A Lista de Schindler","ชะตากรรมที่โลกไม่ลืม","Schindler''s List"]', 1784690324541);
