INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tren-duong-bon-tau', 'Trên Đường Bôn Tẩu', 'Women On The Run', 'https://phimimg.com/upload/vod/20250118-1/a285e33b93584f2ccc2dc890eaddba62.jpg', 'https://phimimg.com/upload/vod/20250118-1/2d1b37996217e3cbe3bffbc3ecbab254.jpg', '<p>Một cô gái Siu Yin 17 tuổi đã trở thành quán quân võ thuật Quãng Đông, hâm mộ Lý Tiểu Long và Lý Liên Kiệt, khát khao đến Hong Kong để kiếm được nhiều tiền, bị bạn trai lừa gạt, từ miền quê lên thành thị ở Quãng Đông, làm gái mại dâm, bị ép chơi ma tuy, hại cuộc đời cô thê thảm, sau những chịu đựng, đau đớn bị lừa gạt, cô tung 1 cước, bạn trai chết, cô bỏ trốn qua được Hong Kong tiếp tục hành nghề để kiếm sống qua ngày, khi cảnh sát đến truy quét tội phạm, cô bỏ chạy, leo lên toà nhà đang thi công, đứng ngoài giàn giáo bằng tre, hâm dọa sẽ nhảy xuống để chết.</p>', 'Full', 1, 'single', 'completed', 13, 1993, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Farini Cheung Yui-ling","avatar":""},{"name":"Tamara Guo","avatar":""},{"name":"Won Jin","avatar":""},{"name":"Corey Yuen","avatar":""},{"name":"David Lai Dai-Wai","avatar":""},{"name":"Wong Wai-Tak","avatar":""},{"name":"Chan Sek","avatar":""},{"name":"Johnny Cheung Wa","avatar":""},{"name":"Benny Lai Keung-Kuen","avatar":""},{"name":"Adam Chan Chung-Tai","avatar":""},{"name":"So Wai-Nam","avatar":""},{"name":"Lam Kwok-Kit","avatar":""},{"name":"Kong Miu-Deng","avatar":""},{"name":"Lee Kin","avatar":""},{"name":"Wu Zhan-Peng","avatar":""},{"name":"Chun Kwai-Bo","avatar":""},{"name":"Lau Tze-Ming","avatar":""},{"name":"Lu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chek law kwong ban","마담 캅스","郎心狼心","