INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-linh-tinh', 'Khách Sạn Linh Tinh', 'The Spirit Of Love', 'https://phimimg.com/upload/vod/20240711-1/177b18cfca6f0ff7ed42e061cecbfbfd.jpg', 'https://phimimg.com/upload/vod/20240711-1/0f904cb2622e64db314b511608b790f8.jpg', '<p><em>Truyền thuyết kể rằng một nhóm yêu tinh sống trên trời, họ là những vị thần bảo vệ thế giới, hay còn được gọi là cha vợ của trái đất. Khách sạn yêu tinh mô tả trải nghiệm của một nữ yêu tinh Dongdong (Chen Songling) xuống trần gian. Cô được bổ nhiệm làm thần hộ mệnh trong một khách sạn cũ, qua những gì cô nhìn thấy và nghe thấy trong khách sạn, cô bắt đầu hiểu được suy nghĩ của con người và cảm xúc yêu, ghét, hận thù và ngu dốt.</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 1993, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Tùng Linh","avatar":""},{"name":"Lâm Văn Long","avatar":""},{"name":"Vương Thư Kỳ","avatar":""},{"name":"Trần Khải Thái","avatar":""},{"name":"Tăng Vỹ Quyền","avatar":""},{"name":"Trịnh Trung Cơ","avatar":""},{"name":"Sở Nguyên","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324541);
