INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-hung-bip-vuong', 'Thư Hùng Bịp Vương', 'Being Honest', 'https://phimimg.com/upload/vod/20240613-1/4922e3d5b37ef19207beffa661ad4df2.jpg', 'https://phimimg.com/upload/vod/20240613-1/d1b1cc8c5d0e9b07fdfff165dfda919a.jpg', '<p><em>Thư Hùng Bịp Vương xoay quanh anh chàng Kha Bình Thân, vốn chơi thân với Diệp Quốc Cơ, nhưng lại bị tên này lợi dụng lòng tốt, lừa đảo tới mức phải ngồi tù, cũng từ đó mà thay đổi cả cuộc đời. Thời gian trong tù, Bình Thân quen thân với một tay chuyên lừa bịp, sau này đi theo hắn để lừa bịp sống qua ngày. Một hôm, vô tình cậu có cơ duyên gặp được vua lừa bịp tên Vi, được ông ta nhận làm đệ tử và chính thức bước chân gia nhập vào hàng ngũ chúa lừa chúa bịp. Nhưng trong một vụ hiểu lầm, 2 thầy trò thách thức nhau rằng kẻ nào là người đầu tiên lừa được một cô gái tên Nguyễn Hy Linh sẽ là người chiến thắng, tuy nhiên Linh mới chính là chúa lừa bịp thực sự. Sau đó, cả 3 đã cùng nhau hợp tác để thực hiện những phi vụ lừa bịp quy mô lớn, trong khi tài nghệ của Bình Thân ngày càng tiến bộ do nhận được sự chỉ dạy của 2 chúa bịp, Thân trở</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 1993, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Kathy Chow","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Perrie Lai Hoi-San","avatar":""},{"name":"Yeung Tak-Si","avatar":""},{"name":"Ga-Bo Tsui","avatar":""},{"name":"Bessie Chan","avatar":""},{"name":"Wong Wai","avatar":""},{"name":"Lily Leung Shun-Yin","avatar":""},{"name":"Shing-Seung Wong","avatar":""},{"name":"Sophie Ngan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324541);
