INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-den-nhi-do-3-doc-ba-thien-ha', 'Nhất Đen Nhì Đỏ 3 - Độc Bá Thiên Hạ', 'Who''s The Winner 3', 'https://phimimg.com/upload/vod/20240609-1/c5a69f0ec0972461e84c23cb195164c3.jpg', 'https://phimimg.com/upload/vod/20240609-1/90f739b5bd78b033f9687b84d324b518.jpg', '<p><em>Bộ phim Ðộc Bá Thiên Hạ là Phần 3 của Nhất Ðen Nhì Ðỏ. Phần này, đóng ở bên Pháp, đã tốn kém hơn 30 triệu đô la, bộ phim từ đổ tà Trình Nhật Phong (Nhâm Ðạt Hòa) đã được giới cờ bạc Thế Giới cộng nhận là Ðệ Nhất Cao Thủ , nhưng Tưởng quyền (Cao Hùng) bất phục, liên kết với Dịch Thiên Dương (Thang Chấn Nghiệp) mưu kế ám hại Phong, từ đó trận chiến bao gồm hải, lục, không đổ chiến bất đầu xảy ra.</em></p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 12, 1993, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Thang Chấn Nghiệp","avatar":""},{"name":"Cao Hùng","avatar":""},{"name":"Vạn Ỷ Vân","avatar":""},{"name":"Giang Hoa","avatar":""},{"name":"Ngô Vịnh Vy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324541);
