INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-tac-xi', 'Sát Thủ Tắc Xi', 'Taxi Hunter', 'https://phimimg.com/upload/vod/20240619-1/6c980419e22b9c986a3078c9038746ce.jpg', 'https://phimimg.com/upload/vod/20240619-1/b6dc3168138d40ec862c155b3ad55721.jpg', '<p>Cuộc sống của doanh nhân hiền lành Anthony Wong tan vỡ khi người vợ đang mang thai của anh bị một tài xế taxi bận rộn cán qua. Chuyện này và một vụ việc khác xảy ra với một tài xế taxi nhếch nhác khiến Wong phải thực hiện nhiệm vụ tiêu diệt những tài xế taxi tồi.</p>', 'Full', 1, 'single', 'completed', 10, 1993, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"黃秋生","avatar":""},{"name":"于荣光","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"Athena Chu","avatar":""},{"name":"Perrie Lai Hoi-San","avatar":""},{"name":"陳輝虹","avatar":""},{"name":"Oi-Kit Fan","avatar":""},{"name":"Lung Tin-Sang","avatar":""},{"name":"Lam King-Kong","avatar":""},{"name":"Ray Mak","avatar":""},{"name":"Wu Fung","avatar":""},{"name":"Chan Kai-Tong","avatar":""},{"name":"Hau Woon-Ling","avatar":""},{"name":"James Ha Chim-Si","avatar":""},{"name":"Lam Chiu-Wing","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
