INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-thu-tac-xi', 'Sát Thủ Tắc Xi', 'Taxi Hunter', 'sát thủ tắc xi taxi hunter 黃秋生 于荣光 ng man-tat athena chu perrie lai hoi-san 陳輝虹 oi-kit fan lung tin-sang lam king-kong ray mak wu fung chan kai-tong hau woon-ling james ha chim-si lam chiu-wing ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-de-thuong-hai-hung-ba-thien-ha', 'Hoàng Đế Thượng Hải Hùng Bá Thiên Hạ', 'Lord Of East China Sea 2', 'https://phimimg.com/upload/vod/20231007-1/babe3565c4a443daa32a654e20294b28.jpg', 'https://phimimg.com/upload/vod/20231007-1/95b79b1b46465a89d5a950e084617e76.jpg', '<p>Câu chuyện tiếp tục về cuộc đời của một trong những người đàn ông quyền lực nhất Trung Quốc trong nửa đầu thế kỷ 20. Đến cuối những năm 1920, Luk đã tự khẳng định mình là lãnh chúa của Thượng Hải; một tay chơi trong chính trị, kinh doanh và thế giới ngầm khổng lồ . Nhưng sự hào phóng của anh ấy bắt đầu làm căng thẳng tài chính của anh ấy. Suy nghĩ về tương lai của mình, anh ấy quyết định cam kết mạnh mẽ với đất nước, lựa chọn xã hội cao hơn. Nhưng cuộc tấn công năm 1937 của người Nhật vào Thượng Hải đã ném cả Luk và đất nước của anh ấy vào tình trạng hỗn loạn Luk buộc phải trốn sang Hồng Kông. Anh trở về sau chiến tranh, nhưng nhận thấy chính phủ Dân tộc chủ nghĩa mới không đủ sức. Khi Trung Quốc bắt đầu quá trình chuyển đổi sang chế độ Cộng sản, Luk buồn bã nhận ra rằng mình đang hướng tới sự lãng quên.</p>', 'Full', 1, 'single', 'completed', 24, 1993, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ray Lui","avatar":""},{"name":"Kent Cheng","avatar":""},{"name":"Elvis Tsui","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Cecilia Yip","avatar":""},{"name":"Michael Miu","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Kelvin Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
