INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-de-thuong-hai', 'Hoàng Đế Thượng Hải', 'Lord Of East China Sea', 'https://phimimg.com/upload/vod/20240616-1/ed2ba1ecf94dfd57f296d41f57d9bea5.jpg', 'https://phimimg.com/upload/vod/20240616-1/eef8b8242c06d5319fa4c6bf9b313eaf.jpg', '<p>Người đàn ông bản lĩnh và vô cùng khôn ngoan Nguyệt Sanh, mặc dù chỉ xuất thân là người bán hoa quả nhưng anh đã từng bước trở thành ông vua của Thượng Hải. Sau khi đứng ra đòi số tiền bồi thường cho một gia đình khó khăn khi ông của cô bị ông chủ Huỳnh giết chết, Sanh được nhận làm việc cho sòng bài của ông ta. Không lâu sau, anh khẳng định được tầm ảnh hưởng tại đây và trở thành bàn tay phải đắc lực của ông Huỳnh, cả 2 cùng nhau làm ăn với người Pháp và kiếm được bội tiền từ việc buôn bán thuốc phiện. Cuối cùng, Sanh bị quân Tưởng Giới Thạch hãm hại, mất đi tất cả.</p>', 'Full', 1, 'single', 'completed', 10, 1993, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ray Lui","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Cecilia Yip","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Siqin Gaowa","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Michael Miu","avatar":""},{"name":"Kelvin Wong","avatar":""},{"name":"Lam Wai","avatar":""},{"name":"William Ho Ka-Kui","avatar":""},{"name":"Ronny Ching Siu-Lung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324541);
