INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-duong-cam', 'Chiếc Dương Cầm', 'The Piano', 'https://phimimg.com/upload/vod/20231204-1/a5c8855ce3074979751fafd6ac3e762b.jpg', 'https://phimimg.com/upload/vod/20231204-1/83b8053bba26f7276a7daa30784815a3.jpg', '<p>Chiếc Dương Cầm - The Piano (1993):Ở thế kỷ thứ 19, Ada là một người đàn bà câm đến New Zealand để cưới một địa chủ giàu có già cả theo kế hoạch được sắp đặt sẵn. Cô mang theo con gái Flora và cố gắng mang theo cây dương cầm yêu quý. Vậy mà, thật kinh hoàng, ông chồng mới của cô lại bỏ cây đàn ngay bờ biển. Khi đã quá tuyệt vọng, Ada cảm thấy tình yêu trỗi dậy khi Baines, một người mới định cư dốt nát đầy những hình xăm kiểu Maori trên người, đã mang cây đàn của cô về và mua nó...</p>', 'Full', 1, 'single', 'completed', 15, 1993, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Holly Hunter","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Sam Neill","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324541);
