INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('slam-dunk-tv-series', 'Slam Dunk TV Series', 'Slam Dunk', 'https://phimimg.com/upload/vod/20240229-1/b94d88dbda0e32aae47ce3f84ab145ef.jpg', 'https://phimimg.com/upload/vod/20240229-1/316f6d08fa068f5b83feaf5849da4c25.jpg', '<p>Slam Dunk là câu chuyện xoay quanh nhân vật Hanamichi Sakuragi, vốn là học sinh cá biệt, cầm đầu một băng nhóm chuyên gây lộn. Hanamichi từng tỏ tình và bị từ chối 50 lần khi còn học cấp 2. Lên trung học, Cậu ta gặp Haruko Akagi, cô gái trong mơ, và rất hạnh phúc khi cô không hề sợ cậu như những cô gái khác.</p>', 'Full', 101, 'hoathinh', 'completed', 25, 1993, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '[]', 1784690324541);
