INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-tau-tu-than', 'Đoàn Tàu Tử Thần', 'Death Train', 'https://phimimg.com/upload/vod/20240228-1/9a91ad38da0da4c840a6d6eb965b93ad.jpg', 'https://phimimg.com/upload/vod/20240228-1/48cda6b4632f9739cace94898c212c97.jpg', '<p>Khi một vị tướng Nga phản bội gửi một quả bom hạt nhân bay tới Trung Đông trên một chuyến tàu bị cướp, các đặc vụ được phái đến để giải giáp thiết bị chết người này. Mười tấn thép và một ounce plutonium nóng hiện đang được vận chuyển thô bạo khắp châu Âu. Khi thời gian không còn nhiều, các đặc vụ tiến hành một cuộc tấn công liều lĩnh, đầy đạn vào một mục tiêu đang di chuyển chết người do một lính đánh thuê máu lạnh điều khiển.</p>', 'Full', 1, 'single', 'completed', 15, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Alexandra Paul","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"Christopher Lee","avatar":""},{"name":"John Abineri","avatar":""},{"name":"Nic D''Avirro","avatar":""},{"name":"Clarke Peters","avatar":""},{"name":"Andreas Jung","avatar":""},{"name":"Ron Berglas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324541);
