INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-o-kalifornia', 'Sát Nhân Ở Kalifornia', 'Kalifornia', 'https://phimimg.com/upload/vod/20240228-1/f2772893be88ac4da3202fbca0f11b36.jpg', 'https://phimimg.com/upload/vod/20240228-1/6d208c3d34f6f09404cd292558e27d5e.jpg', '<p>Tốt nghiệp đại học với tấm bằng cử nhân tâm lý, nhà báo Brian Kessler (David Duchovny) muốn tới California cùng với cô bạn gái Carrie Laughlin (Michelle Forbes) để tìm hiểu một số nơi từng xảy ra các vụ án mạng. Brian và Carrie, một phóng viên ảnh, ấp ủ kế hoạch viết sách về những tên sát nhân hàng loạt và Khi dự án viết sách của hai người nhận được tài trợ của một nhà xuất bản, họ quyết định lên đường.Khoản tiền mà nhà xuất bản ứng trước chỉ đủ để cặp tình nhân trang trải các chi phí sinh hoạt cơ bản và mua một chiếc Lincoln Continental mui mềm. Số tiền còn lại không đủ để thực hiện chuyến đi tới California.Tù nhân Early Grayce (Brad Pitt) được tạm tha nhờ cam kết không phạm luật trong thời gian thử thách. Sau khi biết tin ...</p>', 'Full', 1, 'single', 'completed', 13, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"David Duchovny","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"Michelle Forbes","avatar":""},{"name":"Sierra Pecheur","avatar":""},{"name":"John Dullaghan","avatar":""},{"name":"Kathy Larson","avatar":""},{"name":"David Milford","avatar":""},{"name":"Judson Vaughn","avatar":""},{"name":"John Zarchen","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324541);
