INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-binh', 'Âm Binh', 'Army Of Darkness', 'https://phimimg.com/upload/vod/20240228-1/32a8050ce053882f5b7dbd96283543e1.jpg', 'https://phimimg.com/upload/vod/20240228-1/04a58c26eed9f412081204ab39643cba.jpg', '<p>Câu thần chú vô tình đưa Ash trở về quá khứ, năm 1300, vua Athur còn đang trị vì. Lúc này cuộc chiến giữa hai vùng nam-bắc diễn ra vô cùng ác liệt. Bị lầm tưởng là nội gián, anh bị bắt giam. Do đánh bại được 2 tên quỷ dữ trong hầm ngục, mọi người nghĩ rằng Ash là người anh hùng được lựa chọn theo lời tiên tri. Anh là người duy nhất có khả năng tìm lại Necronomicon, Quyển sách của người chết để giúp đỡ người dân. Đó cũng là cách duy nhất giúp anh trở về thời hiện đại. Bởi đọc sai lời chú, Ash đã vô tình đánh thức đoàn quân bóng tối. Nhiệm vụ của anh lúc bấy giờ là lãnh đạo mọi người, đương đầu với đội quân ma quỷ...</p>', 'Full', 1, 'single', 'completed', 13, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Campbell","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"Marcus Gilbert","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324541);
