INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thanh-thien-1993-phan-6', 'Bao Thanh Thiên 1993 (Phần 6)', 'Justice Bao 6', 'https://phimimg.com/upload/vod/20240215-1/ac26b1bccff36282264cc453f26cf49b.jpg', 'https://phimimg.com/upload/vod/20240215-1/aec8ea44cc6e63a0be007a7e5f9ed2de.jpg', '<p>Phủ Khai Phong có Bao Thanh Thiên, thiết diện vô tư xử ngay gian, nghĩa hiệp Triển Chiêu đến trợ giúp, Vương Triều Mã Hán ở cạnh bên. Nhắc đến Bao Thanh Thiên là nhắc đến vị quan mặt sắt đen sì, mà lòng sáng như gương, thanh liêm chính trực, chí công vô tư, không sợ cường quyền, sẵn sàng vì dân kêu oan, ngày xử án dương gian, đêm xử án âm phủ. Những câu chuyện kể về Bao Thanh Thiên luôn là những câu chuyện kể hoài không hết, luôn làm say mê lòng người.</p>', 'Hoàn Tất (236/236)', 236, 'series', 'completed', 17, 1993, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Gia Kính","avatar":""},{"name":"Kim Siêu Quần","avatar":""},{"name":"Phạm Hồng Hiên","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324541);
