INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-vuong-biet-co', 'Bá Vương Biệt Cơ', 'Farewell My Concubine', 'https://phimimg.com/upload/vod/20240205-1/c68f78b67ca4a8d850fd09db141bea8d.jpg', 'https://phimimg.com/upload/vod/20240205-1/486e661a99afcc6c08717cf79e5e2e18.jpg', '<p>Hai người bạn cùng lớn lên trong một đoàn kịch cổ truyền của Trung Quốc trong thời kì nhiễu loạn, họ đã cùng chia sẻ bao thăng trầm ngọt bùi trong cuộc sống , họ sẽ mãi là bạn tốt nếu như 1 trong 2 người không nảy sinh tình cảm trái với tự nhiên, đem lòng yêu thương người bạn trai của mình, đó cũng là bi kịch cả đời của nhân vật chính trong câu chuyện. Bộ phim đưa tên tuổi diễn viên Trương Quốc Vinh lên hàng ngôi sao và dường như nhân vật trong phim cũng vận vào số phận của diễn viên này...</p>', 'Full', 1, 'single', 'completed', 13, 1993, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leslie Cheung","avatar":""},{"name":"Zhang Feng Yi","avatar":""},{"name":"Gong Li","avatar":""},{"name":"Jiang Wenli","avatar":""},{"name":"Ge You","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324541);
