INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('benny-va-joon', 'Benny Và Joon', 'Benny & Joon', 'https://phimimg.com/upload/vod/20240126-1/03623c083f4c824d27ae850f80289131.jpg', 'https://phimimg.com/upload/vod/20240126-1/3e3bc849f8733c798b183df28e11f460.jpg', '<p>Trong một thị trấn nhỏ, công nhân cơ khí Benny hết lòng thương yêu Joon, cô em gái mắc bệnh tâm thần của mình. Thậm chí, anh không quản ngại khi tận tay chăm sóc em. Rồi một ngày kia, Sam ghé qua nhà anh ít ngày. Khi đến nơi, Sam nhanh chóng ấn tượng với cuộc sống quái dị ở ngôi nhà mà anh em Benny và Joon sinh sống. Hai chàng trai có thể gặp nhiều phiền toái khi sống cùng cô gái không trí tuệ Joon nhưng họ cũng tìm thấy được ý nghĩa của cuộc sống. Tuy nhiên, khi Benny nhận ra điều đó thì rạn nứt giữa tình an hem bắt đầu xuất hiện. Họ phải làm gì để chấp nhận người mới đến kỳ quặc này?</p>', 'Full', 1, 'single', 'completed', 14, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Mary Stuart Masterson","avatar":""},{"name":"Aidan Quinn","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324541);
