INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-hai-hong-anh', 'Bá Hải Hồng Anh', 'The Avenging Quartet', 'https://phimimg.com/upload/vod/20240121-1/16b0b72bd845d852ee6998e5b13b5f7d.jpg', 'https://phimimg.com/upload/vod/20240121-1/8b6978b43205670125425b296457cba7.jpg', '<p>Bộ phim Bá Hải Hồng Anh - The Avenging Quartet xoay quanh câu chuyện về bức tranh nổi tiếng thời kháng chiến Nhật Bản. Vị tướng Nhật Bản Yamashita đã giấu bí mật về vũ khí virus sử dụng trong chiến tranh trong bức tranh này. Trải qua nhiều năm, bức tranh này đã trở về Trung Quốc và lọt vào tay một họa sĩ tên là A Hùng. Vì muốn lấy lại bức tranh, người Nhật đã cử một võ sĩ Oshima đến Trung Quốc, hợp tác với một bà trùm xã hội đen để truy lùng A Hùng. Bên cạnh đó, hai cô gái cùng đem lòng yêu A Hùng là A Thanh và A Phụng cũng đang tìm kiếm anh khắp nơi. Liệu bức tranh sẽ rơi vào tay ai? A Hùng có thoát khỏi sự tìm kiếm gắt gao của nhiều người như vậy?</p>', 'Full', 1, 'single', 'completed', 14, 1993, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lý Tử Hùng","avatar":""},{"name":"Dương Lệ Thanh","avatar":""},{"name":"Tiền Gia Lạc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324541);
