INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngai-ba-tuoc-lac-vao-tuong-lai', 'Ngài Bá Tước Lạc Vào Tương Lai', 'The Visitors', 'https://phimimg.com/upload/vod/20240104-1/1c49afda7e7d765393f3a7e162d73837.jpg', 'https://phimimg.com/upload/vod/20240104-1/dbef60f8e8b612175a6156ec93fb6dea.jpg', '<p>Hai thầy trò ông Bá tước nhờ vào thầy phù thủy để đưa mình về tương lai nhằm cứu vãn đám cưới, nhưng có một sự sai lầm lão phù thủy già lại đưa họ về nước pháp thời hiện đại... Chính sự khác biệt về thời gian đã gây ra không ít tình huống dở khóc dở cười. Liệu Ngài Bá tước có thể trở về đúng thời điểm để cứu vãn cuộc hôn nhân của mình không?</p>', 'Full', 1, 'single', 'completed', 12, 1993, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean Reno","avatar":""},{"name":"Valérie Lemercier","avatar":""},{"name":"Christian Clavier","avatar":""},{"name":"Marie-Anne Chazel","avatar":""},{"name":"Christian Bujeau","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324541);
