INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-trong-an', 'Tổ Trọng án', 'Crime Story', 'https://phimimg.com/upload/vod/20240108-1/fa86ecf2c5a96a9fe14d32c8c68b9652.jpg', 'https://phimimg.com/upload/vod/20240108-1/c1457c07cf5bfb4defb67397df9eb983.jpg', '<p>Khi một băng đảng tàn nhẫn bắt cóc một doanh nhân giàu có, một cảnh sát dày dạn kinh nghiệm tham gia vụ án bắt đầu nghi ngờ cấp trên của mình có liên quan đến chuyện này.</p>', 'Full', 1, 'single', 'completed', 30, 1993, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Thành Long","avatar":""},{"name":"Trịnh Tắc Sĩ","avatar":""},{"name":"La Gia Anh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324542);
