INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-de-bac-cai', 'Nam Đế Bắc Cái', 'The Condor Heroes Return', 'https://phimimg.com/upload/vod/20240109-1/f7f03ab2bb97c7b6f19a745c041456ee.jpg', 'https://phimimg.com/upload/vod/20240109-1/14f9177eec7b5964bb3adb9f6ed3e12b.jpg', '<p>Hồng Thất xuất thân từ gia đình có thể lực, nhưng những sai lầm của chàng đã mang đến những biến cố cho gia đình. Bản thân Hồng Thất sau khi sa cơ đã ngộ ra được nhiều điều, nhưng đó cũng là lúc chàng bị cố nhân hắt hủi, khinh khi. Một lần tình cờ, Hồng Thất gặp gỡ và làm quen với Đoàn Trí Hưng, thái tử Đại Lý. Ban đầu xảy ra nhiều xích mích nhưng về sau cả hai đã kết tâm giao, cùng chống lại thế lực đen tối trên giang hồ.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 18, 1993, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Trịnh Y Kiện","avatar":""},{"name":"Ngụy Tuấn Kiệt","avatar":""},{"name":"Lê Diệu Tường","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
