INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tc-2000', 'TC 2000', 'TC 2000', 'https://phimimg.com/upload/vod/20231231-1/f68cb39be83bfb68298981c7db2b275b.jpg', 'https://phimimg.com/upload/vod/20231231-1/ddd339e34cab14ea800eb0a9d3f564f8.jpg', '<p>Ở đâu đó trong tương lai, môi trường quá mức cần thiết đã đến. Nhiều người đã chết. Người giàu có thể xây dựng thế giới ngầm, người nghèo phải ở trên bề mặt xây dựng băng nhóm để tồn tại. Jason Storm, một người bảo vệ thế giới ngầm biết về một âm mưu giết tất cả mọi người trên bề mặt. Anh ta cần phải chạy trốn lên mặt nước và thu phục Sumai, một bậc thầy võ thuật được kính trọng, làm đồng minh của mình để ngăn chặn âm mưu bẩn thỉu.</p>', 'Full', 1, 'single', 'completed', 23, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bolo Yeung","avatar":""},{"name":"Billy Blanks","avatar":""},{"name":"Jalal Merhi","avatar":""},{"name":"Bobbie Phillips","avatar":""},{"name":"Matthias Hues","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324542);
