INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nowhere-to-run', 'Nowhere To Run', 'Nowhere To Run', 'https://phimimg.com/upload/vod/20231230-1/b258b2114d2c09d4e01a93c2a78d9fff.jpg', 'https://phimimg.com/upload/vod/20231230-1/6ed96fba3d8c5d5aef64378394fd28c5.jpg', '<p>Sam, một kẻ bị kết án trốn thoát, hạ cánh trên một đất nông nghiệp thuộc sở hữu của một góa phụ. Khi anh ta biết rằng một nhà thầu tàn nhẫn đang cố gắng chiếm lấy đất của mình, anh ta giúp cô chiến đấu chống lại sự bất công.</p>', 'Full', 1, 'single', 'completed', 15, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324542);
