INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nowhere-to-run', 'Nowhere To Run', 'Nowhere To Run', 'nowhere to run nowhere to run  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-hung-khat-mau', 'Bọ Hung Khát Máu', 'Cronos', 'https://phimimg.com/upload/vod/20231230-1/ce3167acf4a817c225100d837a965c0b.jpg', 'https://phimimg.com/upload/vod/20231230-1/3b9d426db90c5385b14f9cba44080a1f.jpg', '<p>Trong bộ phim này, Cronos là tên của một con bọ hung. Nhưng con bọ hung này không phải là do tự nhiên sinh ra. Nó là một loại máy mạ vàng siêu nhỏ hình bọ hung đã có tuổi thọ 450 năm. Một người buôn bán đồ cổ đã phát hiện ra nó vào năm 1993. Ngay lập tức rất nhiều kẻ không từ bỏ một thủ đoạn nào, thậm chí phải hi sinh tính mạng nhiều người hòng giành được thiết bị này. Khi cầm Cronos trong tay, con bọ hung này sẽ bám vào người chủ, rồi biến người chủ thành ma cà rồng. Cronos đem tới quyền năng sức mạnh vẻ đẹp cho người bình thường, và cũng đem tới cơn khát máu. Lẽ dĩ nhiên, những kẻ sở hữu được Cronos sẽ trở thành ma cà rồng...</p>', 'Full', 1, 'single', 'completed', 18, 1993, 'Vietsub', 'HD', 'Mexico', 0, '[{"name":"Federico Luppi","avatar":""},{"name":"Ron Perlman","avatar":""},{"name":"Claudio Brook","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324542);
