INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lu-quy-nho', 'Lũ Quỷ Nhỏ', 'The Sandlot', 'https://phimimg.com/upload/vod/20231227-1/827068a6b65ad329c1ec90d3a81e1f58.jpg', 'https://phimimg.com/upload/vod/20231227-1/a35ca54886016ce63db3e310e3bca4b2.jpg', '<p>Trong một mùa hè của tình bạn và cuộc phiêu lưu, một cậu bé trở thành thành viên của băng đảng, chín cậu bé trở thành một đội và thủ lĩnh của họ trở thành huyền thoại bằng cách đối mặt với bí ẩn đáng sợ bên ngoài bức tường cánh đồng bên phải.</p>', 'Full', 1, 'single', 'completed', 15, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Guiry","avatar":""},{"name":"Mike Vitar","avatar":""},{"name":"Patrick Renna","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"Chauncey Leopardi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324542);
