INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('troi-va-dat', 'Trời Và Đất', 'Heaven & Earth', 'https://phimimg.com/upload/vod/20231211-1/4179eba9eb04bc3313c2e6318cf05b83.jpg', 'https://phimimg.com/upload/vod/20231211-1/8d06d97a546cf735a7878930fd81700f.jpg', '<p>Bộ phim dựa trên câu chuyện có thật về bà Phùng Thị Lệ Lý, nói về giai đoạn chiến tranh Việt nam từ năm 1949-1986. Phim kể về cuộc đời của Lệ Lý, cô gái sinh tại Làng Kỳ La. Cuộc sống yên bình nơi ngôi làng nhỏ của những người dân nghèo, sống an lành với Cha Trời (Father Heaven) và Mẹ Đất (Mother Earth), đã bị phá vỡ bởi chiến tranh, khiến cho bao gia đình, đôi lứa phải chia ly.</p>', 'Full', 1, 'single', 'completed', 13, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kuh Ledesma","avatar":""},{"name":"Dingdong Dantes","avatar":""},{"name":"Dennis Trillo","avatar":""},{"name":"Nadine Samonte","avatar":""},{"name":"Tommy Lee Jones","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
