INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nhuoc-huu-tinh-2', 'Thiên Nhược Hữu Tình 2', 'A Moment Of Romance II', 'https://phimimg.com/upload/vod/20231211-1/f9eb896adcd9314b4c646ba8cc76abe0.jpg', 'https://phimimg.com/upload/vod/20231211-1/61adfb02d905c61dca61ae49cd9a047a.jpg', '<p>Thiên Nhược Hữu Tình 2 – A Moment Of Romance II, kể về cuộc tình của A Phú và Tiểu Thiến. A Tiểu Thiến là một cô gái xuất thân từ hoàng tộc, vì ơn cứu mạng nên cho dành tình cảm cho chàng trai dũng cảm A Phú. Nhưng cô bị cha mẹ ép gả cho con trai của Đỗ Thụy Đạt là Đỗ Duẫn Đường. Từ đây, Tiểu Thiến chôn vùi nỗi đau vào lòng, cố gắng sống trong Đỗ gia đầy phức tạp, và rồi cô đã trở thành nữ cường nhân đầy quyền lực ở đất Thượng Hải. Tuy nhiên, bất chấp tất cả tính mạng, A Phú quyết định bằng mọi giá sẽ giải cứu người mình yêu.</p>', 'Full', 1, 'single', 'completed', 14, 1993, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Huỳnh Thu Sinh","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Quách Phú Thành","avatar":""},{"name":"Ngô Thanh Liên","avatar":""},{"name":"Quách Tấn An","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
