INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-chu-minh-giao', 'Giáo Chủ Minh Giáo', 'Kung Fu Cult Master', 'https://phimimg.com/upload/vod/20231211-1/17ba0e57c42ffebf27f66bf8d90beb4e.jpg', 'https://phimimg.com/upload/vod/20231211-1/439aa8b26d241bfc8c82a19d37eded4f.jpg', '<p>Hai môn phái cùng hợp tác với nhau để bảo vệ dân chúng và chống lại những thế lực xấu xa. Một chàng trai trẻ mang trong mình một lời nguyền, là người duy nhất được truyền dạy bộ bí kiếp võ công huyền thoại Cửu Âm Chân Kinh.</p>', 'Full', 1, 'single', 'completed', 22, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Trương Mẫn","avatar":""},{"name":"Khâu Thục Trinh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324542);
