INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-6-ngay-13-phan-9', 'Thứ 6 Ngày 13 Phần 9', 'Jason Goes To Hell: The Final Friday', 'https://phimimg.com/upload/vod/20231211-1/c73a73112aa10865ddd2f2c035797001.jpg', 'https://phimimg.com/upload/vod/20231211-1/ffd50e70bd94d9e9c5679a67e17d7539.jpg', '<p>Jason Voorhees bị lực lượng đặc nhiệm FBI truy lùng và tiêu diệt thành từng mảnh, được tái sinh với khả năng lạnh thấu xương để giả định danh tính của bất kỳ ai anh chạm vào.</p>', 'Full', 1, 'single', 'completed', 25, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kane Hodder","avatar":""},{"name":"John D. LeMay","avatar":""},{"name":"Kari Keegan","avatar":""},{"name":"Steven Williams","avatar":""},{"name":"Steven Culp","avatar":""},{"name":"Erin Gray","avatar":""},{"name":"Rusty Schwimmer","avatar":""},{"name":"Richard Gant","avatar":""},{"name":"Leslie Jordan","avatar":""},{"name":"Billy Green Bush","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324542);
