INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thu-6-ngay-13-phan-9', 'Thứ 6 Ngày 13 Phần 9', 'Jason Goes To Hell: The Final Friday', 'thứ 6 ngày 13 phần 9 jason goes to hell: the final friday kane hodder john d. lemay kari keegan steven williams steven culp erin gray rusty schwimmer richard gant leslie jordan billy green bush ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-o-philadelphia', 'Chuyện Ở Philadelphia', 'Philadelphia', 'https://phimimg.com/upload/vod/20231208-1/a660979fc97e2de2c037c496df0246c8.jpg', 'https://phimimg.com/upload/vod/20231208-1/2e7af1ac3c46235ead35053b2e6ebdc6.jpg', '<p>Tương lai nghề nghiệp của luật sư Andrew Beckett (Tom Hanks) đang như diều gặp gió vì anh được giao cho một vụ kiện khá quan trọng. Nhưng chuyện không may đã xảy ra khi tập hồ sơ anh hoàn tất sau nhiều đêm thức trắng đã không cánh mà bay. Andrew đã bị đuổi việc với lí do không hoàn tất công việc, một lí do rất chính đáng. Nhưng Andrew tin rằng anh bị đuổi việc vì một lý do khác mà tập đoàn luật gia đang cố ém nhẹm: Andrew là người đồng tính luyến ái và tệ hơn nữa là bị bịnh Aids. Andrew muốn đâm đơn kiện công ty vì lý do đuổi việc không chính đáng, anh đã gõ cửa nhiều văn phòng luật sư nhưng toàn gặp từ chối vì không ai dám kiện một tập đoàn vững mạnh như thế. Một ngày kia, anh gặp Joe, cảm kích và hâm mộ chí khí của Andrew, luật sư Joe đồng ý giúp anh kiện công ty.</p>', 'Full', 1, 'single', 'completed', 14, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Denzel Washington","avatar":""},{"name":"Roberta Maxwell","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
