INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-o-philadelphia', 'Chuyện Ở Philadelphia', 'Philadelphia', 'chuyện ở philadelphia philadelphia tom hanks denzel washington roberta maxwell ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-dang-karate-2', 'Nhất Đẳng Karate 2', 'Best of The Best 2', 'https://phimimg.com/upload/vod/20231207-1/0d0fa792cbeafc1e7f3b763afba025d0.jpg', 'https://phimimg.com/upload/vod/20231207-1/76b59ca5a2c88bed7eb22128fdec1084.jpg', '<p>Nhất Đẳng Karate 2 - Best of the Best 2 nối tiếp nội dung trong phần 1, kể về thời gian sau khi đánh bại đội karate quốc gia Hàn Quốc trong cuộc thi, Alex, Tommy và Travis đã thành lập một studio võ thuật ở Las Vegas. Để có thêm tiền, Travis chiến đấu trong một đấu trường thế giới ngầm - đây cũng chính là nguyên nhân dẫn đến cái chết của anh dưới bàn tay của Brakus - một võ sĩ độc ác. Tìm cách trả thù, Alex và Tommy tấn công Brakus, khiến mặt anh ta bị sẹo, và sau đó chạy trốn đến sa mạc. Tức giận, Brakus ra lệnh cho người của mình tìm và giết họ.</p>', 'Full', 1, 'single', 'completed', 15, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eric Roberts","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324542);
