INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-dien-va-nguoi-dep', 'Chó Điên Và Người Đẹp', 'Mad Dog and Glory', 'https://phimimg.com/upload/vod/20231204-1/25455f8ec6cf0897e6d25f6b3b0df677.jpg', 'https://phimimg.com/upload/vod/20231204-1/3c704a822d7759efc7e445914593161d.jpg', '<p>Wayne Dobie là một cảnh sát nhút nhát có phong thái trầm lặng nên anh có biệt danh trìu mến là Chó Điên. Sau khi Mad Dog cứu mạng Frank Milo, một tên trùm tội phạm và một diễn viên hài độc thoại đầy tham vọng, anh ta đã đề nghị bầu bạn với một cô hầu bàn trẻ hấp dẫn tên Glory trong một tuần. Lúc đầu cả hai đều không thoải mái về sự sắp xếp, nhưng cuối cùng họ yêu nhau. Tuy nhiên, tình hình trở nên phức tạp khi Milo đòi lại Glory.</p>', 'Full', 1, 'single', 'completed', 15, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Uma Thurman","avatar":""},{"name":"Bill Murray","avatar":""},{"name":"David Caruso","avatar":""},{"name":"Mike Starr","avatar":""},{"name":"Tom Towles","avatar":""},{"name":"Kathy Baker","avatar":""},{"name":"Derek Anunciation","avatar":""},{"name":"Doug Hara","avatar":""},{"name":"Evan Lionel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
