INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('demolition-man', 'Demolition Man', 'Demolition Man', 'https://phimimg.com/upload/vod/20231201-1/d6131c3d6415bdb4b90e1866d6da3fa1.jpg', 'https://phimimg.com/upload/vod/20231201-1/f6b60866e2128645ba87728c11e377c2.jpg', '<p>Simon Phoenix, một tên tội phạm bạo lực bị đóng băng đông lạnh vào năm 1996, trốn thoát trong phiên điều trần tạm tha vào năm 2032 tại San Angeles không tưởng. Cảnh sát không có khả năng đối phó với những cách bạo lực của anh ta và quay sang kẻ bắt giữ anh ta, người cũng đã bị đông lạnh sau khi bị buộc tội oan giết 30 người vô tội trong khi bắt giữ Phoenix.</p>', 'Full', 1, 'single', 'completed', 20, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Wesley Snipes","avatar":""},{"name":"Sandra Bullock","avatar":""},{"name":"Nigel Hawthorne","avatar":""},{"name":"Benjamin Bratt","avatar":""},{"name":"Rob Schneider","avatar":""},{"name":"Bob Gunton","avatar":""},{"name":"Glenn Shadix","avatar":""},{"name":"Denis Leary","avatar":""},{"name":"Bill Cobbs","avatar":""},{"name":"Grand L. Bush","avatar":""},{"name":"Pat Skipper","avatar":""},{"name":"Steve Kahan","avatar":""},{"name":"Paul Bollen","avatar":""},{"name":"Mark Colson","avatar":""},{"name":"Andre Gregory","avatar":""},{"name":"John Enos III","avatar":""},{"name":"Troy Eva","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324542);
