INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-giau-mat', 'Sát Thủ Giấu Mặt', 'Lamb Killer', 'https://phimimg.com/upload/vod/20231211-1/58c45f797404ff1ced68674ff0200d03.jpg', 'https://phimimg.com/upload/vod/20231211-1/71772f8ddda8d4392b27e12aca60fc4d.jpg', '<p>Sát Thủ Giấu Mặt - Lamb Killer xoay quanh câu chuyện về một cặp song sinh tên là Jenny và Yuk Lan. Từ nhỏ, cả hai đã bị chia cắt. Sau cái chết của Jenny, thanh tra Âu đã được yêu cầu trợ giúp từ Yuk Lan. Cô muốn tìm ra kẻ giết chị gái mình bằng cách giả danh tính của cô.</p>', 'Full', 1, 'single', 'completed', 17, 1993, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Mao Nghiệp Quân","avatar":""},{"name":"Trương Kiên Đình","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
