INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-chang-linh-ngu-lam-1993', 'Ba Chàng Lính Ngự Lâm', 'The Three Musketeers', 'https://phimimg.com/upload/vod/20231129-1/a17a857bf7ec82d56ba289ae86a8bfea.jpg', 'https://phimimg.com/upload/vod/20231129-1/cadbe0295afe57c13cc4a46968b1ab53.jpg', '<p>Ba Chàng Lính Ngự Lâm - The Three Musketeers (1993):D&#39;Artagnan (Logan Lerman) gia nhập lực lượng với ba người lính ngự lâm cựu chiến binh để ngăn chặn phản diện Đức Hồng Y Richelieu (Christoph Waltz) chiếm ngôi vua của Pháp và nhận chìm châu Âu trong cuộc chiến máu lửa, phim với nhịp độ nhanh, nhiều pha hành động lôi cuốn phiêu lưu cổ điển Dumas.</p>', 'Full', 1, 'single', 'completed', 25, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kiefer Sutherland","avatar":""},{"name":"Chris O''Donnell","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Charlie Sheen","avatar":""},{"name":"Tim Curry","avatar":""},{"name":"Rebecca De Mornay","avatar":""},{"name":"Paul McGann","avatar":""},{"name":"Gabrielle Anwar","avatar":""},{"name":"Michael Wincott","avatar":""},{"name":"Julie Delpy","avatar":""},{"name":"Hugh O''Conor","avatar":""},{"name":"Christopher Adamson","avatar":""},{"name":"Philip Tan","avatar":""},{"name":"Erwin Leder","avatar":""},{"name":"Axel Anselm","avatar":""},{"name":"Bruno Thost","avatar":""},{"name":"Oliv","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324542);
