INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-dien-hy-su-1993', 'Hoa Điền Hỷ Sự', 'All''s Well End''s Well Too', 'https://phimimg.com/upload/vod/20231007-1/4df5851ce5dcb48ee3c4766f93a2f805.jpg', 'https://phimimg.com/upload/vod/20231007-1/ba8ab81bac62e388f169b39d903cf5ee.jpg', '<p>Chow Tung (Samuel Hui) là một người đàn ông hào nhoáng, người đã được sắp xếp để kết hôn cùng ngày với cô em gái xấu xí Gut (Sandra Ng) lấy những người&nbsp; phối ngẫu không phải do họ lựa chọn. Chow, là một người con hiếu thảo, đồng ý thực hiện theo kế hoạch của mẹ mình (Ricky Hui). Cốt truyện nổi bật lên khi Chow gặp nàng Bạch Tuyết xinh đẹp (Rosamund Kwan) và quyết định kết hôn với nàng. Họ không hề hay biết, người tình của Bạch Tuyết là pháp sư David Cooper Feel (Trương Quốc Vinh) bày ra một kế hoạch và Chow đã kết hôn với Jinx (Teresa Mo).</p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Leslie Cheung","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Sam Hui","avatar":""},{"name":"Teresa Mo","avatar":""},{"name":"Ricky Hui","avatar":""},{"name":"Sandra Ng Kwun-Yu","avatar":""},{"name":"Money Lo","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"Raymond Wong","avatar":""},{"name":"Clifton Ko Chi-Sum","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
