INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-ve-nha-hanh-trinh-phi-thuong', 'Hướng Về Nhà: Hành Trình Phi Thường', 'Homeward Bound: The Incredible Journey', 'https://phimimg.com/upload/vod/20231125-1/0d381486473da7c1423e19f0938c6995.jpg', 'https://phimimg.com/upload/vod/20231125-1/059f401d75051de062c648521ce20a65.jpg', '<p>Bản làm lại của bộ phim kinh điển nổi tiếng của Disney, lần này có sự góp mặt của một số giọng nói nổi tiếng trong vai hai chú chó và một chú mèo đi khắp nước Mỹ gặp phải đủ loại cuộc phiêu lưu trong hành trình tìm kiếm đoàn tụ với chủ nhân của chúng.</p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael J. Fox","avatar":""},{"name":"Sally Field","avatar":""},{"name":"Don Ameche","avatar":""},{"name":"Kim Greist","avatar":""},{"name":"Kevin Chevalia","avatar":""},{"name":"Anne Christianson","avatar":""},{"name":"Ted D''Arms","avatar":""},{"name":"Don Alder","avatar":""},{"name":"Ed Bernard","avatar":""},{"name":"Benj Thall","avatar":""},{"name":"Veronica Lauren","avatar":""},{"name":"William Phipps","avatar":""},{"name":"Gary Taylor","avatar":""},{"name":"Jean Smart","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Robert Hays","avatar":""},{"name":"Bart The Bear","avatar":""},{"name":"Woody Eney","avatar":""},{"name":"Ric","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324542);
