INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-o-bronx', 'Chuyện Ở Bronx', 'A Bronx Tale', 'https://phimimg.com/upload/vod/20231125-1/5abaea6e894cea175a68e9cec8eb8821.jpg', 'https://phimimg.com/upload/vod/20231125-1/e04fd34ab351bad7d086f553a1c64940.jpg', '<p>Cậu bé Calogero trở thành tâm điểm trong cuộc chiến tâm lý dai dẳng nhưng không cân sức giữa bố cậu, một tài xế lương thiện, và thủ lĩnh mafia phố Bronx. Sống trong ranh giới giữa thiện và ác dưới sự bảo ban của ông trùm xã hội đen, con đường trở thành người tốt của Calogero là cả một câu chuyện ly kỳ...</p>', 'Full', 1, 'single', 'completed', 15, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Chazz Palminteri","avatar":""},{"name":"Lillo Brancato","avatar":""},{"name":"Francis Capra","avatar":""},{"name":"Taral Hicks","avatar":""},{"name":"Kathrine Narducci","avatar":""},{"name":"Clem Caserta","avatar":""},{"name":"Alfred Sauchelli","avatar":""},{"name":"Jr.","avatar":""},{"name":"Frank Pietrangolare","avatar":""},{"name":"Joe Pesci","avatar":""},{"name":"Robert D''Andrea","avatar":""},{"name":"Eddie Montanaro","avatar":""},{"name":"Fred Fischer","avatar":""},{"name":"Dave Salerno","avatar":""},{"name":"Joseph D''Onofrio","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324542);
