INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-phuong-bat-bai-phong-van-tai-khoi', 'Đông Phương Bất Bại: Phong Vân Tái Khởi', 'Swordsman III: The East Is Red', 'https://phimimg.com/upload/vod/20231125-1/63e2d4af24059ea7aee4ce25d1b81352.jpg', 'https://phimimg.com/upload/vod/20231125-1/9777edfb858eb1a9bc060386e677fed5.jpg', '<p>Sau cái chết hiển hiện của Đông phương bất bại, nhiều kẻ giả mạo đã sử dụng tên của cô, thành lập giáo phái riêng và thu nạp đồ đệ nhằm tăng cường sức mạnh.</p>', 'Full', 1, 'single', 'completed', 19, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Brigitte Lin","avatar":""},{"name":"Joey Wong","avatar":""},{"name":"Jean Wang Ching-Ying","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"Eddy Ko","avatar":""},{"name":"Lee Ka-Ting","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"Yen Shi-Kwan","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Fennie Yuen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324542);
