INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dong-phuong-bat-bai-phong-van-tai-khoi', 'Đông Phương Bất Bại: Phong Vân Tái Khởi', 'Swordsman III: The East Is Red', 'đông phương bất bại: phong vân tái khởi swordsman iii: the east is red brigitte lin joey wong jean wang ching-ying yu rongguang shun lau eddy ko lee ka-ting kingdom yuen yen shi-kwan wu ma fennie yuen ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-khong-tieu-tu', 'Chân Không Tiểu Tử', 'The Bare-Footed Kid', 'https://phimimg.com/upload/vod/20231124-1/6e2f6284ca41faba1f241089d9fe73af.jpg', 'https://phimimg.com/upload/vod/20231124-1/c368a3340c6cfaab455f933bdeeea2bb.jpg', '<p>Sau cái chết của cha mình, Quan Phong Diệu một thanh niên nghèo tìm kiếm người bạn của cha mình là Đoạn Thanh Vân và nhận được sự giúp đỡ từ Thanh Vân và bà chủ Tứ Qúy Chức. Bởi vì có võ thuật cao, Phong Diệu được Thạch Hòa Phố thuê về làm và đã bị Nguyên Thiên Hữu lừa và lợi dung để giết chết Thạch Hòa Phố và vô tình đã hại chết Đoạn Thanh Vân. Trước khi chết Đoạn Thanh Vân truyền hết võ công của cha Phong Diệu lại cho anh và cuối cùng anh đã giết chết hết những người của Thạch Hòa Phố nhưng vì bị thương quá nặng nên anh đã chết và trước khi chết anh còn cố mang đôi giày mới của mình lần cuối cùng. Cả đời ngay cả tên mình cũng không biết viết thì còn làm được gì.</p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Ti Lung","avatar":""},{"name":"Wu Chien-Lien","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Tin Ching","avatar":""},{"name":"Wong San","avatar":""},{"name":"Chu Tit-Wo","avatar":""},{"name":"Benny Lai Keung-Kuen","avatar":""},{"name":"Johnny Cheung Wa","avatar":""},{"name":"Yuen Ling-To","avatar":""},{"name":"Cheng Ka-Sang","avatar":""},{"name":"Leung Kai-Chi","avatar":""},{"name":"Hau Woon-Ling","avatar":""},{"name":"Jacky Cheung Chun-","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
