INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chan-khong-tieu-tu', 'Chân Không Tiểu Tử', 'The Bare-Footed Kid', 'chân không tiểu tử the bare-footed kid aaron kwok maggie cheung ti lung wu chien-lien paul chun kenneth tsang eddie cheung wong yat-fei tin ching wong san chu tit-wo benny lai keung-kuen johnny cheung wa yuen ling-to cheng ka-sang leung kai-chi hau woon-ling jacky cheung chun- ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-stalingrad', 'Trận Chiến Stalingrad', 'Stalingrad', 'https://phimimg.com/upload/vod/20231124-1/95ec1a7991154ed89d6814e5e0c745de.jpg', 'https://phimimg.com/upload/vod/20231124-1/6bd56dc1fa4a0edcf097dde433f050eb.jpg', '<p>Như chúng ta đã biết WWII là cuộc chiến tàn khốc nhất trong lịch sử nhân lọai. Đã có rất nhiều câu truyện và bộ phim được dựng lên dựa theo đề tài này, như Enemy At The Gates, Tinh Cầu, Jakov - kẻ nói dối, Trân Châu Cảng, Thép đã tôi thế đấy,Cầu Sông Kwai (The Bridge on the River Kwai), Schindler’s List ... còn rất nhiều và rất nhiều bộ phim như vậy. Trong cộc chiếm thảm khốc ấy, có thể nói đến công lao của nước Liên Xô anh hùng đã làm nên một trận chiến vệ quốc vĩ đại. Mà nổi bậc nhất là trận Stalingrad. Chúng ta đã xem rất nhiều phim về WWII mà Liên Xô (hay Nga) đã làm. Lần đầu tiên có một bộ phim nhìn nhận và trải nghiệm trận đánh Stalingrad dưới góc nhìn của một người lính Đức. Họ không còn là một con quỷ Fascist bạo tàn ...</p>', 'Full', 1, 'single', 'completed', 13, 1993, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Dominique Horwitz","avatar":""},{"name":"Thomas Kretschmann","avatar":""},{"name":"Jochen Nickel","avatar":""},{"name":"Sebastian Rudolph","avatar":""},{"name":"Dana Vávrová","avatar":""},{"name":"Martin Benrath","avatar":""},{"name":"Sylvester Groth","avatar":""},{"name":"Karel Heřmánek","avatar":""},{"name":"Heinz Emigholz","avatar":""},{"name":"Oliver Broumis","avatar":""},{"name":"Dieter Okras","avatar":""},{"name":"Zdeněk Vencl","avatar":""},{"name":"Mark Kuhn","avatar":""},{"name":"Ferdinand Schuster","avatar":""},{"name":"Alexander Wachholz","avatar":""},{"name":"Ulrike A","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324542);
