INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thanh-thien-1993-phan-5', 'Bao Thanh Thiên 1993 (Phần 5)', 'Justice Bao 5', 'https://phimimg.com/upload/vod/20231203-1/f81749656aae8e0d1676c4eca9f7c48b.jpg', 'https://phimimg.com/upload/vod/20231203-1/de07149a68f18f268889a4c1f4ed64bd.jpg', '<p>Phủ Khai Phong có Bao Thanh Thiên, thiết diện vô tư xử ngay gian, nghĩa hiệp Triển Chiêu đến trợ giúp, Vương Triều Mã Hán ở cạnh bên. Nhắc đến Bao Thanh Thiên là nhắc đến vị quan mặt sắt đen sì, mà lòng sáng như gương, thanh liêm chính trực, chí công vô tư, không sợ cường quyền, sẵn sàng vì dân kêu oan, ngày xử án dương gian, đêm xử án âm phủ. Những câu chuyện kể về Bao Thanh Thiên luôn là những câu chuyện kể hoài không hết, luôn làm say mê lòng người.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 22, 1993, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Hà Gia Kính","avatar":""},{"name":"Kim Siêu Quần","avatar":""},{"name":"Phạm Hồng Hiên","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324542);
