INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong-dau-hoang-phi-hong', 'Hoàng Phi Hồng đấu Hoàng Phi Hồng', 'Master Wong Vs Master Wong', 'https://phimimg.com/upload/vod/20231120-1/7eeda097a62a8bdf3c145806e040f528.jpg', 'https://phimimg.com/upload/vod/20231120-1/40c87c7c0faf395e1c9da842b27807d4.jpg', '<p>Nhất đại tông sư Hoàng Phi Hồng vì Phật Sơn vô ảnh cước mà danh tiếng chấn động Phật Sơn, Tạ lão gia mời anh cùng gom tiền cho nạn dân. Trong một lần tình cờ, Hoàng Phi Hồng biết được ông chủ Tạ mượn việc gom tiền để trục lợi, lúc đến hỏi tội, ông chủ Tạ lại cho nữ cải trang nam nhi đóng giả Hoàng Phi Hồng đến đối chất với chính Hoàng Phi Hồng thật. Trình diễn màn kịch hay Hoàng Phi Hồng đấu Hoàng Phi Hồng trên màn ảnh rộng.</p>', 'Full', 1, 'single', 'completed', 15, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Alan Tam","avatar":""},{"name":"Carol Cheng","avatar":""},{"name":"Teresa Mo","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Gabriel Wong","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"Wong San","avatar":""},{"name":"Kenny Wong Tak-Ban","avatar":""},{"name":"Joey Leung","avatar":""},{"name":"Vincent Kok","avatar":""},{"name":"Tang Tai-Wo","avatar":""},{"name":"Ho Chi-Moon","avatar":""},{"name":"David Wu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324542);
