INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-cuoi-cung', 'Người Hùng Cuối Cùng', 'Last Action Hero', 'https://phimimg.com/upload/vod/20231116-1/93a134905c7b0f8e0012e6a47f020c70.jpg', 'https://phimimg.com/upload/vod/20231116-1/4c59500a4ba58107899ec2318334585b.jpg', '<p>Sau cái chết của cha mình, cậu bé Danny Madigan cảm thấy thoải mái khi xem những bộ phim hành động có cảnh sát bất khả chiến bại của Los Angeles Jack Slater. Sau khi được quản lý rạp chiếu phim Nick trao cho một chiếc vé ma thuật, Danny bị hút vào màn hình và gắn bó với Slater. Khi nhân vật phản diện hư cấu độc ác Benedict có trong tay chiếc vé và bước vào thế giới thực, Danny và Jack phải đi theo và ngăn chặn hắn.</p>', 'Full', 1, 'single', 'completed', 18, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Austin O''Brien","avatar":""},{"name":"Bridgette Wilson-Sampras","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"Art Carney","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Frank McRae","avatar":""},{"name":"Tom Noonan","avatar":""},{"name":"Robert Prosky","avatar":""},{"name":"Anthony Quinn","avatar":""},{"name":"Mercedes Ruehl","avatar":""},{"name":"Ian McKellen","avatar":""},{"name":"Professor Toru Tanaka","avatar":""},{"name":"Joan Plowright","avatar":""},{"name":"Keith Barish","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b