INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toc-truong-huyen-thoai', 'Tộc Trưởng Huyền Thoại', 'Geronimo: An American Legend', 'https://phimimg.com/upload/vod/20231119-1/ed821cfb63ba44a58188fc3653bad62d.jpg', 'https://phimimg.com/upload/vod/20231119-1/5f71aa1b0c1c56ac3d8a2244e61301eb.jpg', '<p>Người da đỏ Apache đã miễn cưỡng đồng ý giải quyết theo một bảo lưu đã được Chính phủ Hoa Kỳ chấp thuận. Không phải tất cả người Apache đều có thể thích nghi với cuộc sống của nông dân trồng ngô. Một người đặc biệt, Geronimo, luôn bồn chồn. Bị đẩy đến bờ vực bởi những lời hứa bị phá vỡ và những hành động cần thiết của chính phủ, Geronimo và khoảng ba mươi chiến binh khác thành lập một đội tấn công làm bẽ mặt chính phủ bằng cách trốn tránh bị bắt, đồng thời đòi lại những gì thuộc về họ.</p>', 'Full', 1, 'single', 'completed', 34, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Patric","avatar":""},{"name":"Gene Hackman","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Wes Studi","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Rodney A. Grant","avatar":""},{"name":"Kevin Tighe","avatar":""},{"name":"Steve Reevis","avatar":""},{"name":"Carlos Palomino","avatar":""},{"name":"Victor Aaron","avatar":""},{"name":"Stuart Proud Eagle Grant","avatar":""},{"name":"Stephen McHattie","avatar":""},{"name":"John Finn","avatar":""},{"name":"Lee de Broux","avatar":""},{"name":"Rino Thunder","avatar":""},{"name":"Hoke Howell","avatar":""},{"name":"Richard Martin Jr.","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324542);
