INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-man-va-toi-ac', 'Lãng Mạn và Tội Ác', 'True Romance', 'https://phimimg.com/upload/vod/20231118-1/e983b013368d9357be8e2cc09b0a1c83.jpg', 'https://phimimg.com/upload/vod/20231118-1/17fb69e5255c74f5e88249cd696759f5.jpg', '<p>Clarence kết hôn với cô gái điếm Alabama, ăn trộm cocaine từ tay ma cô và cố gắng bán nó ở Hollywood, trong khi chủ sở hữu của cô ấy cố gắng đòi lại.</p>', 'Full', 1, 'single', 'completed', 17, 1993, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Christian Slater","avatar":""},{"name":"Patricia Arquette","avatar":""},{"name":"Michael Rapaport","avatar":""},{"name":"Bronson Pinchot","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Dennis Hopper","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Saul Rubinek","avatar":""},{"name":"James Gandolfini","avatar":""},{"name":"Frank Adonis","avatar":""},{"name":"Paul Bates","avatar":""},{"name":"Val Kilmer","avatar":""},{"name":"Chris Penn","avatar":""},{"name":"Anna Thom","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324542);
