INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-chu-nhoc', 'Cuộc Đời Chú Nhóc', 'This Boy''s Life', 'https://phimimg.com/upload/vod/20231116-1/2f945427e30d7e28adcedacca0d27955.jpg', 'https://phimimg.com/upload/vod/20231116-1/15d89715d601f1e07c8513e3a7e49c20.jpg', '<p>Khi hai mẹ con chuyển đến Seattle với hy vọng có một cuộc sống tốt đẹp hơn, người mẹ gặp một người đàn ông có vẻ lịch sự. Mọi thứ trở nên tồi tệ khi người đàn ông trở nên bạo hành, gây nguy hiểm đến tính mạng của họ. Khi người mẹ đấu tranh để duy trì hy vọng trong một tình huống bất khả thi, cậu con trai lên kế hoạch trốn thoát.</p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Ellen Barkin","avatar":""},{"name":"Leonardo DiCaprio","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Eliza Dushku","avatar":""},{"name":"Jonah Blechman","avatar":""},{"name":"Kathy Kinney","avatar":""},{"name":"Gerrit Graham","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Zachary Ansley","avatar":""},{"name":"Tobey Maguire","avatar":""},{"name":"Tracey Ellis","avatar":""},{"name":"Robert Zameroski","avatar":""},{"name":"Travis MacDonald","avatar":""},{"name":"Morgan Brayton","avatar":""},{"name":"Frank C. Turner","avatar":""},{"name":"Sean","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
