INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-phuong-tam-hiep', 'Đông Phương Tam Hiệp', 'The Heroic Trio', 'https://phimimg.com/upload/vod/20231116-1/fb3454b841377ad6724a75d4c9ad58c2.jpg', 'https://phimimg.com/upload/vod/20231116-1/7b5dd432424ce3fba3160b3c8d884c6f.jpg', '<p>Đông Phương Tam Hiệp - The Heroic Trio xoay quanh sự kết hợp giữa ba chuyên gia võ thuật đầy quyền lực được thủ vai bởi 3 nữ diễn viên nổi tiếng nhất tại xứ cảng thơm trong thập niên 90 thế kỷ trước là Dương Tử Quỳnh, Trương Mạn Ngọc và Mai Diễm Phương trong vai Chat, Ching và Tung . Mỗi thành viên với bản sắc siêu anh hùng bí mật của mình sẽ được thể hiện trong từng thời điểm cần thiết, họ cùng nhau chiến đấu chống lại cái ác tối thượng với sức mạnh cực ghê gớm. Kẻ thù của họ là một pháp sư điên nhưng cực kỳ mạnh mẽ, người mà tin rằng nếu ông bắt cóc tất cả các em bé ở Trung Quốc, ông ta có thể xây dựng một lớp cai trị của quỷ dữ và cuối cùng là có thể thống trị cả thế giới.</p>', 'Full', 1, 'single', 'completed', 14, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Anita Mui","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Damian Lau","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Yen Shi-Kwan","avatar":""},{"name":"James Pax","avatar":""},{"name":"Mimi Chu","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Chui To","avatar":""},{"name":"Philip Keung Ho-Man","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Lee Siu-Kei","avatar":""},{"name":"Chan Cheuk-Yan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
