INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-cuc-truong-tam-phong', 'Thái Cực Trương Tam Phong', 'Tai Chi Master', 'https://phimimg.com/upload/vod/20231117-1/770c696f59a03089f9dba62e72f739c8.jpg', 'https://phimimg.com/upload/vod/20231117-1/9343a33cf22ceee56c938c8d6be9f275.jpg', '<p>Tiên Bảo bị trục xuất ra khỏi Thiếu Lâm Tự bởi có những hành động không phù hợp với bang quy của Thiếu Lâm Tự. Quân Bảo, cũng là một đệ tử Thiếu Lâm và là người bạn nối khố thuở nhỏ với Tiên Bảo. Vì xem trọng tình bạn nên Quân Bảo đã quyết định ra đi cùng với Tiên Bảo. Nhưng do lý tưởng của 2 người khác nhau, Quân Bảo vẫn là một anh chàng hiền lành, dễ mến. Ngược lại Tiên Bảo bị sự cám dỗ của một băng đảng xấu xa và quyết định làm việc dưới trướng của tên ma đầu Jin. Việc Quân Bảo và Tiên Bảo phải đối đầu với nhau trong một trận chiến sống còn sau này là một điều tất yếu ...</p>', 'Full', 1, 'single', 'completed', 23, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Chin Siu-ho","avatar":""},{"name":"Fennie Yuen","avatar":""},{"name":"Hai Yu","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"Kam Kong Chow","avatar":""},{"name":"Jiankui Sun","avatar":""},{"name":"Ho Wing-Cheung","avatar":""},{"name":"Yu Yankai","avatar":""},{"name":"Yung-Chang Ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
