INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-bo-nong', 'Hồ Sơ Bồ Nông', 'The Pelican Brief', 'https://phimimg.com/upload/vod/20231117-1/a6a94086540e8427298912a3bcfa4833.jpg', 'https://phimimg.com/upload/vod/20231117-1/bef2db46e4aa4634dc25b82e91e7f702.jpg', '<p>Giả thuyết của một sinh viên luật về cái chết gần đây của hai thẩm phán Tòa án Tối cao đã lôi kéo cô vào một mạng lưới giết người, tham nhũng và tham lam sâu rộng.</p>', 'Full', 1, 'single', 'completed', 17, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julia Roberts","avatar":""},{"name":"Denzel Washington","avatar":""},{"name":"Sam Shepard","avatar":""},{"name":"John Heard","avatar":""},{"name":"Tony Goldwyn","avatar":""},{"name":"James B. Sikking","avatar":""},{"name":"William Atherton","avatar":""},{"name":"Robert Culp","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Hume Cronyn","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Anthony Heald","avatar":""},{"name":"Nicholas Woodeson","avatar":""},{"name":"Stanley Anderson","avatar":""},{"name":"John Finn","avatar":""},{"name":"Cynthia Nixon","avatar":""},{"name":"Jake Weber","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
