INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-danh-cha', 'Nhân Danh Cha', 'In the Name of the Father', 'https://phimimg.com/upload/vod/20231115-1/4454bb8a7a4c4406398a07f3ed4238fa.jpg', 'https://phimimg.com/upload/vod/20231115-1/950efed17791ab0a7c8634878cbafcc7.jpg', '<p>Một tên trộm thời gian nhỏ từ Belfast, Gerry Conlon, bị dính líu sai đến vụ đánh bom IRA vào một quán rượu giết chết một số người khi anh ta ở London. Anh ta và bốn người bạn của mình bị cảnh sát Anh ép buộc phải thú nhận tội lỗi của họ. Cha của Gerry và những người thân khác ở London cũng có liên quan đến vụ án. Anh ta ở tù mười lăm năm với cha mình để cố gắng chứng minh mình vô tội.</p>', 'Full', 1, 'single', 'completed', 15, 1993, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Daniel Day-Lewis","avatar":""},{"name":"Pete Postlethwaite","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"John Lynch","avatar":""},{"name":"Corin Redgrave","avatar":""},{"name":"Beatie Edney","avatar":""},{"name":"John Benfield","avatar":""},{"name":"Paterson Joseph","avatar":""},{"name":"Marie Jones","avatar":""},{"name":"Gerard McSorley","avatar":""},{"name":"Frank Harper","avatar":""},{"name":"Mark Sheppard","avatar":""},{"name":"Don Baker","avatar":""},{"name":"Alison Crosbie","avatar":""},{"name":"Nye Heron","avatar":""},{"name":"Anthony Brophy","avatar":""},{"name":"Frankie McCaffe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
