INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong-4-phong-tu-vuong', 'Hoàng Phi Hồng 4: Phong Tứ Vương', 'Once Upon a Time in China IV', 'https://phimimg.com/upload/vod/20231113-1/abe1d642b7537dc71f8e6093a9b08d0f.jpg', 'https://phimimg.com/upload/vod/20231113-1/2cc029308dbd0c9385350cd1a977cb13.jpg', '<p>Hoàng Phi Hồng phải đối phó với cả các mối đe dọa từ nước ngoài và Hiệp hội Đèn lồng Đỏ theo chủ nghĩa dân tộc trong phần tiếp theo của loạt phim kung fu nổi tiếng này.</p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Vincent Zhao Wenzhuo","avatar":""},{"name":"Jean Wang Ching-Ying","avatar":""},{"name":"Max Mok Siu-Chung","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Billy Chow Bei-Lei","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"Louis Roth","avatar":""},{"name":"Andy Wong Chi-Man","avatar":""},{"name":"Kwok Nga-Cheung","avatar":""},{"name":"Wang Jinghua","avatar":""},{"name":"Wong Tak-Yan","avatar":""},{"name":"Ling Kam-Wa","avatar":""},{"name":"Chen Jiming","avatar":""},{"name":"Tong Pau-Chung","avatar":""},{"name":"Lam Chi-Tai","avatar":""},{"name":"Leun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324542);
