INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wallace-va-gromit-chiec-quan-rac-roi', 'Wallace và Gromit - Chiếc Quần Rắc Rối', 'The Wrong Trousers', 'https://phimimg.com/upload/vod/20231112-1/7d8e398e55dc8cd24ef78252ab91d509.jpg', 'https://phimimg.com/upload/vod/20231112-1/3a2b9a30754c7d92050ff7d2ac48622a.jpg', '<p>Wallace cho một chú chim cánh cụt thuê phòng ngủ cũ của Gromit, nó rất thích chiếc quần kỹ thuật do Wallace tạo ra. Tuy nhiên, Gromit sau đó biết rằng chú chim cánh cụt là tội phạm bị truy nã.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 1993, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Peter Sallis","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324542);
