INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sung-rong', 'Súng Rồng', 'Guns Of Dragon', 'https://phimimg.com/upload/vod/20231121-1/b83b59a27e2b84c6584819cb0f59af63.jpg', 'https://phimimg.com/upload/vod/20231121-1/65649ad2b3253a6fb02e735451dec546.jpg', '<p>Bộ phim Súng Rồng - Guns Of Dragon xoay quanh nhân vật Lâm Quốc Chính - cảnh sát trưởng trẻ tuổi nhất Hồng Kông. Anh bay đến Mỹ với hy vọng đoàn tụ với vợ con, nhưng không may lại chạm mặt với Boss, Vương Tử, Đại Phi - bọn xã hội đen năm xưa từng là kẻ thù của mình. Anh đã định vứt bỏ tất cả để sống bên gia đình, nhưng bọn chúng và ông trùm của bọn chúng - Đại Ca (hay còn gọi là Tướng Quân) lại bắt cóc vợ anh để uy hiếp, buộc anh lại phải gánh vác trách nhiệm của một người cảnh sát lần nữa.</p>', 'Full', 1, 'single', 'completed', 13, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ray Lui","avatar":""},{"name":"John Shum Kin-Fun","avatar":""},{"name":"Yvonne Yung Hung","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Alex Fong","avatar":""},{"name":"Kong Lung","avatar":""},{"name":"Billy Lui","avatar":""},{"name":"Jackson Liu","avatar":""},{"name":"Chun Ho","avatar":""},{"name":"Steven Darrow","avatar":""},{"name":"Chun Kwai-Bo","avatar":""},{"name":"Leung Ga-Hung","avatar":""},{"name":"Wong Wai-Fai","avatar":""},{"name":"Frank Minucci","avatar":""},{"name":"Tse Ning","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324542);
