INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ly-lac-phu-ky-an', 'Lý Lạc Phủ Kỳ Án', 'The Incorruptible', 'https://phimimg.com/upload/vod/20231111-1/8798572c4de1e9ffdb6d48e47d6a5fea.jpg', 'https://phimimg.com/upload/vod/20231111-1/0f722e8ce571f662755ad21c49d6f0bd.jpg', '<p>Bộ phim Lý Lạc Phủ Kỳ Án - The Incorruptible kể về hành trình của một thám tử trẻ trung thực, liêm khiết cùng những nỗ lực của anh ta trong cuộc chiến chống lại một tên trùm xấu xa. Sau khi hoàn thành chương trình học ở Anh, Lạc Phu trở về Hồng Kông để thành lập tổ chức chống lại hội tam hoàng. Anh ta đã triệt phá hơn ba trăm gian hàng cờ bạc bất hợp pháp chỉ trong một đêm và do đó đã trở nên nổi tiếng. Hội Tam Hoàng không thể mua chuộc Lý Lạc Phu và vì vậy hai bên trở thành kẻ thù truyền kiếp. Cuối cùng, họ đã bắt cóc vợ của Lý Lạc Phu để đe dọa anh ta. Anh ta tuyệt vọng để cứu vợ mình, đã đến thương lượng với kẻ thù một mình. May mắn thay, Lý Lạc Phu cuối cùng cũng đã bắt và triệt hạ hội tam hoàng bất chấp nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 17, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ray Lui","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Anita Yuen","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Carrie Ng","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Tommy Wong Kwong-Leung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324542);
