INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('crazy-love', 'Crazy Love', 'Crazy Love', 'https://phimimg.com/upload/vod/20231109-1/dd919e80f49993d5cf56de5bf580259d.jpg', 'https://phimimg.com/upload/vod/20231109-1/a4f5b7252110d196d8dc2e3bfae26d09.jpg', '<p>Những gì được cho là trường học mùa hè ở Anh trở thành một cuộc hành trình kỳ lạ và lãng mạn đầy phiêu lưu của một cô gái tuổi teen xinh đẹp. [from the Tai Seng Catalog] Một câu chuyện hay về một cô gái trẻ có tinh thần tự do (hoặc tùy theo quan điểm của bạn, hay trêu chọc) trong một hành trình khám phá ngắn.</p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Loletta Lee","avatar":""},{"name":"Terrence Fok Shui-Wa","avatar":""},{"name":"Kai-Chung Mak","avatar":""},{"name":"Tom Poon Chun-Wai","avatar":""},{"name":"San Tak-Kan","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Tommy Wong Kwong-Leung","avatar":""},{"name":"Timothy Zao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
