INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-sat-thu-bui-doi', 'Nữ Sát Thủ Bụi Đời', 'Point of No Return', 'https://phimimg.com/upload/vod/20231108-1/60533e6ecc9ed763f3b6d7e900356683.jpg', 'https://phimimg.com/upload/vod/20231108-1/e4d66d162ca3fcd14cefda3bf65ff0f7.jpg', '<p>Tội phạm cứng rắn Maggie Hayward bạo lực liên tục, ngay cả khi bị cảnh sát giam giữ, kết thúc trong phòng hành quyết. Tuy nhiên, đặc vụ bí mật hàng đầu của chính phủ Hoa Kỳ &#39;Bob&#39; đã sắp xếp một cái chết được dàn dựng, vì vậy Maggie có thể được huấn luyện công phu để trở thành một kẻ giết người ma quái và khuất phục trước sự phục tùng.</p>', 'Full', 1, 'single', 'completed', 18, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bridget Fonda","avatar":""},{"name":"Gabriel Byrne","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Miguel Ferrer","avatar":""},{"name":"Anne Bancroft","avatar":""},{"name":"Olivia d''Abo","avatar":""},{"name":"Richard Romanus","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Lorraine Toussaint","avatar":""},{"name":"Geoffrey Lewis","avatar":""},{"name":"Mic Rodgers","avatar":""},{"name":"Michael Rapaport","avatar":""},{"name":"Ray Oriel","avatar":""},{"name":"Spike McClure","avatar":""},{"name":"Lieux Dressler","avatar":""},{"name":"John Capodice","avatar":""},{"name":"Car","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
