INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-toi-pham', 'Câu Chuyện Tội Phạm', 'Crime Story', 'https://phimimg.com/upload/vod/20231107-1/991a739db9708487033bc7924dab843f.jpg', 'https://phimimg.com/upload/vod/20231107-1/1927fce8841127f4921e1fff7b66a91f.jpg', '<p>Hung, 1 cảnh sát HongKong thái hóa tham gia 1 hàng ngũ thế giới ngầm từ HongKong, Trung Quốc, Đài Loan với âm mưu bắt cóc 1 tỷ phú địa ốc. Điều tra viên Eddie Chan được phân công vào công tác bảo vệ. Và Hung xung phong tác chiến với Eddie. Tại Đài Load, Eddie bắt đầu nghi ngờ Hung. Và rồi khi Eddie tiến gần đến chỗ kết thúc vụ án thì Hung sắp sửa ra tay khử Eddie để bịt đầu mối.</p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Susanna Au-Yeung Pui-San","avatar":""},{"name":"Christine Ng","avatar":""},{"name":"Poon Ling-Ling","avatar":""},{"name":"Blackie Ko Shou-Liang","avatar":""},{"name":"William Duen Wai-Lun","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Paul Chung Fat","avatar":""},{"name":"Wan Fat","avatar":""},{"name":"Wan Seung-Lam","avatar":""},{"name":"Stephen Chan Tak-Gwong","avatar":""},{"name":"James Ha Chim-Si","avatar":""},{"name":"Yu Kwok-Lok","avatar":""},{"name":"Chu P","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
