INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-hu-truyen', 'Thủy Hử Truyện', 'All Men Are Brothers - Blood of the Leopard', 'https://phimimg.com/upload/vod/20231103-1/dabb29c7a37b28bacde66170ba5496e5.jpg', 'https://phimimg.com/upload/vod/20231103-1/023bc7544b4c1503364b149d63a001ab.jpg', '<p>Phim nói về Lâm Xung và Lỗ Trí Thâm kết nghĩa huynh đệ. Sau đó Lâm Xung bị đày ra biên ải. Phim có nhiều màn võ thuật đẹp mắt và mang tính hài hước.</p>', 'Full', 1, 'single', 'completed', 27, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Joey Wong","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Lau Ching-wan","avatar":""},{"name":"David Lam Wai","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"Pal Sinn Lap-man","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Austin Wai Tin-Chi","avatar":""},{"name":"Tai Bo","avatar":""},{"name":"Chow Chi-Fai","avatar":""},{"name":"Billy Ching Sau-Yat","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
