INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dennis-sieu-quay', 'Dennis Siêu Quậy', 'Dennis the Menace', 'https://phimimg.com/upload/vod/20231103-1/82dc306c31a417f4bdfc5e34621d9f39.jpg', 'https://phimimg.com/upload/vod/20231103-1/2fa80103330e553086f48c68148768c2.jpg', '<p>Sự khó chịu luôn hiện hữu của ông Wilson đến từ một đứa trẻ tinh nghịch tên là Dennis. Nhưng anh ta sẽ cần những mánh khóe của Dennis để khám phá ra bộ sưu tập tiền vàng đã bị mất tích khi một kẻ lang thang mờ ám tên là Switchblade Sam đến thị trấn.</p>', 'Full', 1, 'single', 'completed', 17, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Walter Matthau","avatar":""},{"name":"Mason Gamble","avatar":""},{"name":"Joan Plowright","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Lea Thompson","avatar":""},{"name":"Robert Stanton","avatar":""},{"name":"Amy Sakasitz","avatar":""},{"name":"Kellen Hathaway","avatar":""},{"name":"Paul Winfield","avatar":""},{"name":"Natasha Lyonne","avatar":""},{"name":"Devin Ratray","avatar":""},{"name":"Hank Johnston","avatar":""},{"name":"Melinda Mullins","avatar":""},{"name":"Billie Bird","avatar":""},{"name":"Bill Erwin","avatar":""},{"name":"Arnold Stang","avatar":""},{"name":"Ben Stein","avatar":""},{"name":"Et","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324542);
