INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-du-du-xanh', 'Mùi Đu Đủ Xanh', 'The Scent of Green Papaya', 'https://phimimg.com/upload/vod/20231031-1/87c5eeef1f15c2055b646616d6e9c885.jpg', 'https://phimimg.com/upload/vod/20231031-1/80b16057d14de65a3ea57072b838efd9.jpg', '<p>Bộ phim nói về Mùi, một cô bé ôn hòa và luôn tò mò về thế giới xung quanh. Cô đi ở cho một gia đình buôn vải ở Sài Gòn khoảng những năm 1950. Trong gia đình này, người vợ là trụ cột chính, gánh vác công việc, còn ông chồng chỉ biết chơi bời và bà mẹ chồng. Ông bà chủ có ba con trai, một người trưởng thành, tên là Trung, con trai thứ tên là Lãng. Hai con trai còn lại, một đang tuổi vị thành niên ít quan tâm tới Mùi. Đứa thứ hai khoảng tuổi Mùi thường xuyên trêu chọc cô. Khi người chồng bỏ đi lần thứ tư và cuối cùng, ông lấy đi toàn bộ số tiền có trong nhà. Mặc mọi chuyện diễn ra xung quanh, bé Mùi chăm chỉ làm việc và say mê với thế giới riêng của bé.</p>', 'Full', 1, 'single', 'completed', 19, 1993, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Trần Nữ Yên Khê","avatar":""},{"name":"Man San Lu","avatar":""},{"name":"Thi Loc Truong","avatar":""},{"name":"Nguyen Anh Hoa","avatar":""},{"name":"Hoa Hoi Vuong","avatar":""},{"name":"Ngoc Trung Tran","avatar":""},{"name":"Vantha Talisman","avatar":""},{"name":"Keo Souvannavong","avatar":""},{"name":"Van Oanh Nguyen","avatar":""},{"name":"Gerard Neth","avatar":""},{"name":"Nhat Do","avatar":""},{"name":"Thi Hai Vo","avatar":""},{"name":"Thi Thanh Tra Nguyen","avatar":""},{"name":"Lam Huy Bui","avatar":""},{"name":"Xuan Thu Nguyen","avatar":""},{"name":"Xuan Loi Phan","avatar":""},{"name":"Xuan Dung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324542);
