INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-mau-gia-danh', 'Bảo Mẫu Giả Danh', 'Mrs. Doubtfire', 'https://phimimg.com/upload/vod/20231026-1/b6d6576b7fca931edf88384770d72d5a.jpg', 'https://phimimg.com/upload/vod/20231026-1/8724acdd5e10c7f1a6eddd42fd4e19e7.jpg', '<p>Daniel, một diễn viên đã ly hôn, cải trang thành bà Doubtfire, một nữ quản gia già người Scotland, để làm việc tại nhà của vợ cũ và dành nhiều thời gian hơn cho con cái.</p>', 'Full', 1, 'single', 'completed', 18, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Sally Field","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Lisa Jakub","avatar":""},{"name":"Matthew Lawrence","avatar":""},{"name":"Mara Wilson","avatar":""},{"name":"Robert Prosky","avatar":""},{"name":"Anne Haney","avatar":""},{"name":"Harvey Fierstein","avatar":""},{"name":"Scott Capurro","avatar":""},{"name":"Polly Holliday","avatar":""},{"name":"Sydney Walker","avatar":""},{"name":"Joe Bellan","avatar":""},{"name":"Martin Mull","avatar":""},{"name":"Terence McGovern","avatar":""},{"name":"Karen Kahn","avatar":""},{"name":"Eva Gholson","avatar":""},{"name":"James Cu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324542);
