INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bao-mau-gia-danh', 'Bảo Mẫu Giả Danh', 'Mrs. Doubtfire', 'bảo mẫu giả danh mrs. doubtfire robin williams sally field pierce brosnan lisa jakub matthew lawrence mara wilson robert prosky anne haney harvey fierstein scott capurro polly holliday sydney walker joe bellan martin mull terence mcgovern karen kahn eva gholson james cu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-khach-ninja', 'Lãng Khách Ninja', 'Ninja Scroll', 'https://phimimg.com/upload/vod/20231026-1/d3176f67fb9082755049567f76a9b094.jpg', 'https://phimimg.com/upload/vod/20231026-1/cf95bbf201a771a426200f26e7597f0f.jpg', '<p>Ninja Scroll gây ấn tượng vì tốc độ và máu me trong phim. Rất nhiều máu… cho vỏn vẹn 90 phút phim, những cảnh chiến đấu với vũ khí và phép thuật mới lạ mang lại cho bạo lực một vẻ đẹp hoàn mỹ. &nbsp;Phim kể về Jubei Kibagami, một ninja đánh thuê, nay đây mai đó, người có tài dùng kiếm chém được gió. Sau lần giải cứu một nữ ninja của mạc phủ từ tay một con quái vật thuộc nhóm ninja yêu quái đang âm mưu lật đổ mạc phủ, số phận đẩy anh vào một cuộc phiêu lưu nguy hiểm, đầy ác mộng trong thế giới yêu ma mà cái chết có thể đến bất kỳ lúc nào… &nbsp;Cùng với Akira và Ghost in the Shell, Ninja được xem là một trong những bộ anime (cho người lớn) xuất sắc nhất tới hiện nay. Còn vào những năm 1990, đây chính là anime nổi tiếng nhất Nhật Bản. Ninja Scroll từng giành giải thưởng Citizen Award tại Liên hoan phim Yubari Fantastic quốc tế năm 1993.&quot;</p>', 'Full', 1, 'hoathinh', 'completed', 20, 1993, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Koichi Yamadera","avatar":""},{"name":"Emi Shinohara","avatar":""},{"name":"Takeshi Aono","avatar":""},{"name":"Daisuke Gori","avatar":""},{"name":"Ryuuzaburou Ootomo","avatar":""},{"name":"Akimasa Omori","avatar":""},{"name":"Gara Takashima","avatar":""},{"name":"Norio Wakamoto","avatar":""},{"name":"Toshihiko Seki","avatar":""},{"name":"Masako Katsuki","avatar":""},{"name":"Reizō Nomoto","avatar":""},{"name":"Ichiro Nagai","avatar":""},{"name":"Osamu Saka","avatar":""},{"name":"Katsuji Mori","avatar":""},{"name":"Yusaku Yara","avatar":""},{"name":"Junichi Sugawara","avatar":""},{"name":"Shûichirô M","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324542);
