INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lang-khach-ninja', 'Lãng Khách Ninja', 'Ninja Scroll', 'lãng khách ninja ninja scroll koichi yamadera emi shinohara takeshi aono daisuke gori ryuuzaburou ootomo akimasa omori gara takashima norio wakamoto toshihiko seki masako katsuki reizō nomoto ichiro nagai osamu saka katsuji mori yusaku yara junichi sugawara shûichirô m ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-ban-tia', 'Lính Bắn Tỉa', 'Sniper', 'https://phimimg.com/upload/vod/20231030-1/16d065309c968da9b76a68b784f8343f.jpg', 'https://phimimg.com/upload/vod/20231030-1/454c182bc741fdb4626bb1e90bf44e25.jpg', '<p>Không ồn ào. Không lộ diện. Không cần đến một sư đoàn quân đội để hạ gục mục tiêu. Đó là điều mà chính phủ nói đến một tay bắn tỉa, người sẽ quyết định số phận của những tay “sừng sỏ” bằng một phát đạn. Theo tin tình báo từ kênh đào Panama, tay trùm ma tuý Raoul Ochoa, kẻ nuôi tham vọng kiểm soát vùng kênh đào Panama đang bí mật hậu thuẫn cho tướng Alvaraz, một trong những ứng cử viên tranh cử chức tổng thống nhiệm kì tới. Cái tên đầu tiên được chính phủ nhắc đến không ai khác ngoài Thomas Beckett. Trung sĩ xạ thủ Thomas Beckett chưa từng bỏ qua một mục tiêu trong số 74 nhân vật chống đối chính phủ. Lần này, chốn rừng già đã giăng sẵn hàng ngàn cặm bẫy để chờ đợi người lính bắn tỉa gan dạ…</p>', 'Full', 1, 'single', 'completed', 20, 1993, 'Vietsub', 'HD', 'Peru', 0, '[{"name":"Tom Berenger","avatar":""},{"name":"Billy Zane","avatar":""},{"name":"J.T. Walsh","avatar":""},{"name":"Aden Young","avatar":""},{"name":"Kenneth Radley","avatar":""},{"name":"Reynaldo Arenas","avatar":""},{"name":"Gary Swanson","avatar":""},{"name":"Hank Garrett","avatar":""},{"name":"Frederick Miragliotta","avatar":""},{"name":"Vanessa Steele","avatar":""},{"name":"Carlos Álvarez","avatar":""},{"name":"Tyler Coppin","avatar":""},{"name":"Teo Gebert","avatar":""},{"name":"Edward Wiley","avatar":""},{"name":"William Curtin","avatar":""},{"name":"Howard Bosse","avatar":""},{"name":"Christos A. Linou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
