INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-de-nghi-khiem-nha', 'Lời Đề Nghị Khiếm Nhã', 'Indecent Proposal', 'https://phimimg.com/upload/vod/20231026-1/a62759d443586d6c04fa4d0b772bf755.jpg', 'https://phimimg.com/upload/vod/20231026-1/2f6b394c8c1c2845ed52a6c27f6aa663.jpg', '<p>Câu chuyện về một cặp vợ chồng trẻ. Để xây dựng một ngôi nhà như mơ ước, cả hai đã vướng phải một món nợ lớn. Túng thế, họ quyết định đến Las Vegas để cầu may thế nhưng lại tiếp tục bị thua sạch tiền. Trong tình thế cấp bách ấy, bỗng có một tay tỉ phú đề nghị được ngủ với cô vợ một đêm với giá 1 triệu $.</p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Redford","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Woody Harrelson","avatar":""},{"name":"Seymour Cassel","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Billy Bob Thornton","avatar":""},{"name":"Billy Connolly","avatar":""},{"name":"Rip Taylor","avatar":""},{"name":"Pierre Epstein","avatar":""},{"name":"Joel Brooks","avatar":""},{"name":"Pamela Holt","avatar":""},{"name":"Nicholas Georgiade","avatar":""},{"name":"Danny Zorn","avatar":""},{"name":"Kevin West","avatar":""},{"name":"Tommy Bush","avatar":""},{"name":"Mariclare Costello","avatar":""},{"name":"Jedda Jones","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
