INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ninja-rua-3', 'Ninja Rùa 3', 'Teenage Mutant Ninja Turtles III', 'https://phimimg.com/upload/vod/20231023-1/169e74120ae4d785e3983d4bf332f099.jpg', 'https://phimimg.com/upload/vod/20231023-1/30df4b8d434e93960edf8f5b7ca94faf.jpg', '<p>Bốn chú rùa du hành ngược thời gian về thời của các samurai huyền thoại và chết người ở Nhật Bản cổ đại, nơi họ rèn luyện để hoàn thiện nghệ thuật trở thành một samurai. Những chú rùa cũng hỗ trợ một ngôi làng nhỏ trong cuộc nổi dậy.</p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Elias Koteas","avatar":""},{"name":"Paige Turco","avatar":""},{"name":"Stuart Wilson","avatar":""},{"name":"Sab Shimono","avatar":""},{"name":"Vivian Wu","avatar":""},{"name":"Mark Caso","avatar":""},{"name":"Matt Hill","avatar":""},{"name":"Jim Raposa","avatar":""},{"name":"David Fraser","avatar":""},{"name":"James Murray","avatar":""},{"name":"Eidan Hanzei","avatar":""},{"name":"John Aylward","avatar":""},{"name":"Mak Takano","avatar":""},{"name":"Steve Akahoshi","avatar":""},{"name":"Travis A. Moon","avatar":""},{"name":"Kent Kim","avatar":""},{"name":"Ken Kensei","avatar":""},{"name":"Tad Horino","avatar":""},{"name":"Glen Chin","avatar":""},{"name":"Koichi Sak","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324542);
