INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ninja-rua-3', 'Ninja Rùa 3', 'Teenage Mutant Ninja Turtles III', 'ninja rùa 3 teenage mutant ninja turtles iii elias koteas paige turco stuart wilson sab shimono vivian wu mark caso matt hill jim raposa david fraser james murray eidan hanzei john aylward mak takano steve akahoshi travis a. moon kent kim ken kensei tad horino glen chin koichi sak ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-dau-xuan', 'Ngày Đầu Xuân', 'Groundhog Day', 'https://phimimg.com/upload/vod/20231021-1/24a39a1e74d34815c0b3e7ce8db9913c.jpg', 'https://phimimg.com/upload/vod/20231021-1/e2768ef147aaaac0162e11888045c756.jpg', '<p>Groundhog Day (Ngày Đầu Xuân) là một bộ phim hài sản xuất năm 1993 được Harold Ramis đạo diễn, kịch bản của Danny Rubin và Harold Ramis. Khi mới ra mắt, Groundhog Day không phải là một tác phẩm được đánh giá cao, mà chỉ được nhìn nhận là một bộ phim hài giải trí không tồi. Tuy nhiên, càng về sau, khi được nghiên cứu và nghiền ngẫm, bộ phim đã chứng minh giá trị của mình. Với một cốt truyện thông minh và những triết lý đắt giá, Groundhog Day xứng đáng vị trí 65 trong danh sách 100 tác phẩm điện ảnh xuất sắc nhất mọi thời đại do Hollywood bình chọn. Hội Biên kịch phim nước Mỹ (WGA) bình chọn ra 101 kịch bản hài hước nhất lịch sử, trong đó Groundhog Day đứng thứ 3, ngay sau hai tác phẩm hài kinh điển Annie Hall (1977) và Some Like It Hot (1959). Và cho đến nay bộ phim vẫn nằm trong Top 250 phim hay nhất của IMDb.</p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Murray","avatar":""},{"name":"Andie MacDowell","avatar":""},{"name":"Chris Elliott","avatar":""},{"name":"Stephen Tobolowsky","avatar":""},{"name":"Brian Doyle-Murray","avatar":""},{"name":"Angela Paton","avatar":""},{"name":"Rick Ducommun","avatar":""},{"name":"Rick Overton","avatar":""},{"name":"Robin Duke","avatar":""},{"name":"Willie Garson","avatar":""},{"name":"Ken Hudson Campbell","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Harold Ramis","avatar":""},{"name":"Marita Geraghty","avatar":""},{"name":"Les Podewell","avatar":""},{"name":"Tom Milanovich","avatar":""},{"name":"P","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324542);
