INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('y-thien-do-long-ky-ma-giao-giao-chu', 'Ỷ Thiên Đồ Long Ký: Ma giáo giáo chủ', 'The Kung Fu Cult Master', 'https://phimimg.com/upload/vod/20231016-1/d314502fe8d8559ac4746dcb28e96800.jpg', 'https://phimimg.com/upload/vod/20231016-1/e0d9d442f016b85e740cd0d4945bd041.jpg', '<p>Trong phim giả tưởng sống động về võ thuật này, Trương Vô Kỵ mắc kẹt trong cuộc chiến giữa các phe đối địch đang nhắm đến hai thanh bảo kiếm là Đồ Long và Ỷ Thiên.</p>', 'Full', 1, 'single', 'completed', 25, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Chingmy Yau","avatar":""},{"name":"Sharla Cheung","avatar":""},{"name":"Gigi Lai","avatar":""},{"name":"Sammo Hung","avatar":""},{"name":"Collin Chou","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"Zhang Chunzhong","avatar":""},{"name":"Sun Meng-Quan","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Francis Ng","avatar":""},{"name":"Tenky Tin Kai-Man","avatar":""},{"name":"Cho Wing","avatar":""},{"name":"Chow Yee-Fan","avatar":""},{"name":"Choi Kin-Shing","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324542);
