INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong-3-su-vuong-tranh-ba', 'Hoàng Phi Hồng 3: Sư vương tranh bá', 'Once Upon a Time in China III', 'https://phimimg.com/upload/vod/20231016-1/2954ccabc49d364af169705494176fb8.jpg', 'https://phimimg.com/upload/vod/20231016-1/d3a3b195ce0e759c0e7b0b25ea250648.jpg', '<p>Tại Bắc Kinh, Hoàng Phi Hồng đối đầu với âm mưu chính trị và mối tình tay ba khi một cuộc thi múa lân khơi dậy những mối thù sâu nặng.</p>', 'Full', 1, 'single', 'completed', 18, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Max Mok Siu-Chung","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"John Wakefield","avatar":""},{"name":"Chiu Chin","avatar":""},{"name":"Cunzhuang Ge","avatar":""},{"name":"Wong Tak-Yan","avatar":""},{"name":"Zhang Chunzhong","avatar":""},{"name":"Meng Chin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324542);
