INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muc-tieu-kho-diet', 'Mục Tiêu Khó Diệt', 'Hard Target', 'https://phimimg.com/upload/vod/20231016-1/4af7232eb6e1e3c2e564ed68d6ad6693.jpg', 'https://phimimg.com/upload/vod/20231016-1/4c3f9279338e9676989f41ae1fec36ae.jpg', '<p>Mục Tiêu Khó Tiêu Diệt là một bộ phim hành động do Mỹ sản xuất vào năm 1993, bộ phim nói về một cô gái trẻ đi tìm lại người cha đã cách biệt nhiều năm của mình. Trên đường tìm kiếm, cô gặp và làm quen một người đàn ông, anh ta đã giúp đỡ cô hết mình để tìm lại người cha. Tuy nhiên sau đó cô sớm nhận ra rằng cha cô đã qua đời và đồng thời cả hai phát hiện ra một bí mật rằng có một tổ chức chuyên kinh doanh tính mạng của con người.</p>', 'Full', 1, 'single', 'completed', 18, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Arnold Vosloo","avatar":""},{"name":"Lance Henriksen","avatar":""},{"name":"Yancy Butler","avatar":""},{"name":"Sven-Ole Thorsen","avatar":""},{"name":"Wilford Brimley","avatar":""},{"name":"Ted Raimi","avatar":""},{"name":"Kasi Lemmons","avatar":""},{"name":"Willie C. Carpenter","avatar":""},{"name":"Eliott Keener","avatar":""},{"name":"Chuck Pfarrer","avatar":""},{"name":"Robert Apisa","avatar":""},{"name":"Douglas Forsythe Rye","avatar":""},{"name":"Mike Leinert","avatar":""},{"name":"Lenore Banks","avatar":""},{"name":"Barbara Tas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
