INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sup-do', 'Sụp Đổ', 'Falling Down', 'https://phimimg.com/upload/vod/20231016-1/fe5cc5c139c46b182d3454c784137988.jpg', 'https://phimimg.com/upload/vod/20231016-1/145d60c1ee47814d0e0c2f804cd0b5a9.jpg', '<p>Một người đàn ông trung tuần, vợ ly dị, mỗi tuần chỉ được phép đến thăm con một lần, lại bị thất nghiệp, nỗi uất hận của ông lên đến tột đỉnh khi bị kẹt xe giữa buổi trưa nắng gắt, ông bỏ mặc chiếc xe và đi bộ về nhà. Trên đường đi, ông dồn mọi uất ức vào những gì gặp trên đường...</p>', 'Full', 1, 'single', 'completed', 15, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Barbara Hershey","avatar":""},{"name":"Rachel Ticotin","avatar":""},{"name":"Tuesday Weld","avatar":""},{"name":"Frederic Forrest","avatar":""},{"name":"Lois Smith","avatar":""},{"name":"Ebbe Roe Smith","avatar":""},{"name":"Michael Paul Chan","avatar":""},{"name":"Raymond J. Barry","avatar":""},{"name":"D.W. Moffett","avatar":""},{"name":"Stephen Park","avatar":""},{"name":"Kimberly Scott","avatar":""},{"name":"James Keane","avatar":""},{"name":"Macon McCalman","avatar":""},{"name":"Richard Montoya","avatar":""},{"name":"Bru","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
