INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cheo-leo-vach-nui', 'Cheo Leo Vách Núi', 'Cliffhanger', 'https://phimimg.com/upload/vod/20231015-1/5bf50bf92c78089f203aaf9d8cdda0e0.jpg', 'https://phimimg.com/upload/vod/20231015-1/7f8f3e152746bcba7892f99bd87852cf.jpg', '<p>Một năm sau khi mất bạn mình trong một cú ngã thảm khốc 4.000 feet, cựu kiểm lâm Gabe Walker và đồng đội của anh ta, Hal, được kêu gọi trở về cùng một đỉnh để giải cứu một nhóm người leo núi bị mắc kẹt, chỉ để tìm hiểu những người leo núi thực sự là những kẻ không tặc. đang tìm kiếm hộp đầy tiền.</p>', 'Full', 1, 'single', 'completed', 24, 1993, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Janine Turner","avatar":""},{"name":"Rex Linn","avatar":""},{"name":"Caroline Goodall","avatar":""},{"name":"Leon","avatar":""},{"name":"Craig Fairbrass","avatar":""},{"name":"Gregory Scott Cummins","avatar":""},{"name":"Denis Forest","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
