INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hang-luat', 'Hãng Luật', 'The Firm', 'https://phimimg.com/upload/vod/20231015-1/a368192ffcac29fce1a427444b3c1c21.jpg', 'https://phimimg.com/upload/vod/20231015-1/b1f88342b59578596cf7a35c51df09be.jpg', '<p>Tốt nghiệp trường Luật Harvard, chàng trai trẻ nọ nhận được lời đề nghị béo bở từ một hãng luật danh tiếng: một công việc đáng mơ ước đi kèm với những &quot;phúc lợi&quot; đáng sợ.</p>', 'Full', 1, 'single', 'completed', 18, 1993, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Jeanne Tripplehorn","avatar":""},{"name":"Gene Hackman","avatar":""},{"name":"Hal Holbrook","avatar":""},{"name":"Terry Kinney","avatar":""},{"name":"Wilford Brimley","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Holly Hunter","avatar":""},{"name":"Karina Lombard","avatar":""},{"name":"David Strathairn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
