INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-phat-ma-nu-2', 'Bạch Phát Ma Nữ 2', 'The Bride With White Hair 2', 'null', 'https://phimimg.com/upload/vod/20231013-1/cb072f7a4660976a44a2341ee5d00e10.webp', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Kể từ khi phù thủy sùng bái Lian Nei (do Lin Qingxia thủ vai) và người học việc đầu tiên của Wudang là Zhuo Yihang (do Leslie Cheung thủ vai) chia tay, họ đã biến mất kể từ đó. Nhưng vài năm sau, mụ phù thủy đã phát điên, thành lập Cung điện Quỷ và thực hành những phép lạ bất khả chiến bại của thế giới, giết chết những người tử tế ở khắp mọi nơi. Trác ở lại một mình trên đỉnh núi tuyết, chờ ngày hoa lạ nở rộ tìm người yêu, để người yêu cũ có thể tái sinh với mái tóc đen.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Vào đêm khi hậu duệ của Võ Đang là Feng Junjie (do Chen Jinhong thủ vai) kết hôn với Yu Qin (do Wan Qiwen thủ vai), một cô gái ngọc bích của phe Cangfang, phù thủy xuất hiện trở lại, giết chết vị khách và bắt cóc cô dâu, và Jie không may bị thương nặng để cứu Yu Qin. Ngoại trừ Jie và Little Junior Brother Green Mark, không ai trong phái Wudang được tha.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Jay và Green Mark sau đó hợp nhất với nhiều phe phái phản diện khác nhau để chuẩn bị tấn công cung điện ma thuật của phù thủy, giải cứu người vợ yêu dấu của mình và thề sẽ giết phù thủy.</span></p>', 'Full', 1, 'single', 'completed', 16, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lin Qingxia","avatar":""},{"name":"Chan Kam Hung","avatar":""},{"name":"Chung Liti","avatar":""},{"name":"Wan Yiwen","avatar":""},{"name":"Leslie Cheung","avatar":""},{"name":"Zhong Shuhui","avatar":""},{"name":"Tôn Quốc Hạo","avatar":""},{"name":"Lý Tương Tần","avatar":""},{"name":"Rowland","avatar":""},{"name":"Đào Tuấn Vĩ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324542);
