INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-gia-duong-the-lam', 'Thiếu Gia Đường Thể Lam', 'The Prince of Portland Street', 'https://phimimg.com/upload/vod/20231012-1/f8517589de270497a5e154fe1bc7edba.jpg', 'https://phimimg.com/upload/vod/20231012-1/69decaad7a866d599e75e0fefe7f4d14.jpg', '<p>Yam vào vai Anh Pao, một thủ lĩnh băng đảng được kính trọng, người đại diện là một chiến binh đường phố là một trong những người giỏi nhất. Nhưng Pao bị thương ở đầu trong một trận đánh nhau, khiến khả năng trí tuệ của anh bị suy giảm chỉ còn như một đứa trẻ mười tuổi. Xuất hiện như một đứa trẻ, anh ấy phải nhờ đến người bạn thân Kao Chao (Trương Diệu Kỳ) và bạn gái Yao Yao (Anita Yuen) để vượt qua. Nhưng với một tin đồn lớn đang rình rập, liệu thân phận trẻ con của Pao có khiến tất cả họ phải chịu số phận không?</p>', 'Full', 1, 'single', 'completed', 25, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Simon Yam","avatar":""},{"name":"Dicky Cheung Wai-Kin","avatar":""},{"name":"Anita Yuen","avatar":""},{"name":"Sarah Lee Lai-Yui","avatar":""},{"name":"Tommy Wong","avatar":""},{"name":"Fong Ping","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324542);
INSERT OR IGNORE INTO movie_categories (movie_slug, category_slug) VALUES ('thieu-gia-duong-the-lam', 'hinh-su');
