INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thieu-gia-duong-the-lam', 'Thiếu Gia Đường Thể Lam', 'The Prince of Portland Street', 'thiếu gia đường thể lam the prince of portland street simon yam dicky cheung wai-kin anita yuen sarah lee lai-yui tommy wong fong ping ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-the-truy-hon', 'Tái Thế Truy Hồn', 'Vendetta', 'https://phimimg.com/upload/vod/20231012-1/8e75ae662f599efc6c725a1e07fb269a.jpg', 'https://phimimg.com/upload/vod/20231012-1/0d661c28b943553a14568df50bfecd06.jpg', '<p>Một tên cướp bị bắt và hai anh chị em của hắn bị cảnh sát bắn chết. Cùng ngày hôm đó, vợ viên cảnh sát sinh đôi. Trên trán các bé có vết bớt giống hệt vết thương trên người hai tên cướp đã chết.</p>', 'Full', 1, 'single', 'completed', 25, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Tommy Wong","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Eddie Chan Shu-Chi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324542);
