INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-hau-tu', 'Thiết Hầu Tử', 'Iron Monkey', 'https://phimimg.com/upload/vod/20231006-1/edc678e4431c5a3b1a14b8ee44c67d95.jpg', 'https://phimimg.com/upload/vod/20231006-1/a905d4b82803c69c2747458e3b9d98aa.jpg', '<p>Trong tình cảnh khốn quẫn của dân nghèo, một người anh hùng xuất hiện tại thủ phủ tỉnh Triết Giang. Với trình độ võ thuật siêu phàm, chàng cướp của nhà giàu và chia cho dân nghèo. Hiệp khách thường bịt mặt và và tự xưng là Thiết Hầu Tử mỗi khi hành sự.</p>', 'Full', 1, 'single', 'completed', 33, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Yu Rongguang","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Jean Wang","avatar":""},{"name":"Angie Tsang Sze-Man","avatar":""},{"name":"Yen Shi-Kwan","avatar":""},{"name":"James Wong","avatar":""},{"name":"Yuen Shun-Yi","avatar":""},{"name":"Hsiao Hou","avatar":""},{"name":"Lee Fai","avatar":""},{"name":"Chun Kwai-Bo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
