INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-hu-tieu-truyen', 'Thủy Hử Tiếu Truyện', 'Laughter''s Of Water Margins', 'https://phimimg.com/upload/vod/20231006-1/84abad8d5725265dbd8e89f0af8aff89.jpg', 'https://phimimg.com/upload/vod/20231006-1/421530aa6141493ac24657e8763f85ed.jpg', '<p>Võ sĩ hổ Wu Sung ban đầu là một kẻ hèn nhát. Nhưng khi say rượu, anh lại dũng cảm vô cùng. Một lần ở Jingyang Gang, Wu Sung say rượu và giết chết một con hổ. Cuộc chiến dũng cảm của anh đã gây ấn tượng với Sung Jiang và Lao Zhishen. Anh trai của Wu Sang, Wu Dalang, có vẻ như có mối thù với Pan Jinlian, nhưng thực chất họ là một cặp lừa đảo. Pan dùng sắc đẹp của mình dụ dỗ đàn ông lên giường, sau đó Wu Dalangn sẽ đến tống tiền nạn nhân, đòi số tiền khổng lồ. Họ đã rất thành công.......</p>', 'Full', 1, 'single', 'completed', 30, 1993, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sam Hui","avatar":""},{"name":"Teresa Mo","avatar":""},{"name":"Ricky Hui","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"James Wong","avatar":""},{"name":"Lydia Shum Tin-Ha","avatar":""},{"name":"Tommy Wong","avatar":""},{"name":"Frankie Ng","avatar":""},{"name":"Raymond Wong","avatar":""},{"name":"Kenny Wong Tak-Ban","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324542);
