INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-cua-bien-hoa-dong', 'Chúa Của Biển Hoa Đông', 'Lord of East China Sea', 'https://phimimg.com/upload/vod/20231006-1/ca597214c010a44b7d7da5fef50b96fd.jpg', 'https://phimimg.com/upload/vod/20231006-1/3d0a8446247b282293dc8d0f957c978c.jpg', '<p>Người đàn ông bản lĩnh và vô cùng khôn ngoan Nguyệt Sanh, mặc dù chỉ xuất thân là người bán hoa quả nhưng anh đã từng bước trở thành ông vua của Thượng Hải. Sau khi đứng ra đòi số tiền bồi thường cho một gia đình khó khăn khi ông của cô bị ông chủ Huỳnh giết chết, Sanh được nhận làm việc cho sòng bài của ông ta. Không lâu sau, anh khẳng định được tầm ảnh hưởng tại đây và trở thành bàn tay phải đắc lực của ông Huỳnh, cả 2 cùng nhau làm ăn với người Pháp và kiếm được bội tiền từ việc buôn bán thuốc phiện. Cuối cùng, Sanh bị quân Tưởng Giới Thạch hãm hại, mất đi tất cả.</p>', 'Full', 1, 'single', 'completed', 21, 1993, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ray Lui","avatar":""},{"name":"Kent Cheng","avatar":""},{"name":"Elvis Tsui","avatar":""},{"name":"Cecilia Yip","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Siqin Gaowa","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Michael Miu","avatar":""},{"name":"Kelvin Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
