INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-lien-ta-giao', 'Bạch Liên Tà Giáo', 'White Lotus Cult', 'https://phimimg.com/upload/vod/20231006-1/c42534e1fbb7b2b692e4aad8d9f02cca.jpg', 'https://phimimg.com/upload/vod/20231006-1/6d9be1f634073d37532edfdd4bb0ae70.jpg', '<p>Bạch Liên Giáo vốn dĩ là tổ chức phục minh chống lại nhà thanh, 
rất nhiều lần bị triều đình nhà Thanh bắt giưc, lưu truyền đến năm Quang
 Hy mới thôi, mọi người trong hội bắt đầu hỗn loạn. Trong đó phái Trừng 
Thiên lấy ta mê hoặc con người, thế lực rất lớn.Lúc bấy giờ thế lực bên 
ngoài xâm lược phái Thưa thiên lấy khẩu hiệu ủng hộ nhà Thanh và chống 
lại giặc ngoại xâm, được Từ Hy Thái Hậu sủng ái, tuy chủ đích chống lại 
giặc ngoại xâm nhưng lại cấu kết với bọn lưu mạnh sát hại Từ Hy Thái 
Hậu, sau bí mất cứu viện trợ. &nbsp;Một mặt lại truyền giáo lấy công, một mặt
 gia họa chó Kim Trấn sư huynh người anh em của mình, đã mưu hại đối 
phương, để đoạt lấy mật sách sư môn nhằm luyện Bạch liên tà khí bị tẩu 
hỏa nhập ma. Kim Trấn đại nạn không chết, phục thương rời khỏi kinh.</p>', 'Full', 1, 'single', 'completed', 21, 1993, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Elsie Yeh","avatar":""},{"name":"Fennie Yuen","avatar":""},{"name":"Do Siu-Chun","avatar":""},{"name":"Yu Hai","avatar":""},{"name":"Chunhua Ji","avatar":""},{"name":"Cho Wing","avatar":""},{"name":"Wong Kam-Kong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
