INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-phat-ma-nu', 'Bạch Phát Ma Nữ', 'The Bride With White Hair', 'https://phimimg.com/upload/vod/20231006-1/cbe17d7d695c6d7af5acb8d551825e20.jpg', 'https://phimimg.com/upload/vod/20231006-1/04ede500c4033697ff008cdf2e987cee.jpg', '<p>Một anh chàng có tố chất võ học đang theo sư phụ học võ trên núi Võ Đang nhưng lại không có nhiều cảm hứng với võ học. Anh ta cũng là người kế nhiệm không mong muốn của Võ Đang. Một ngày , anh gặp một cô gái xinh đẹp, một kẻ giết người cho tà giáo.</p>', 'Full', 1, 'single', 'completed', 21, 1993, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Leslie Cheung","avatar":""},{"name":"Brigitte Lin","avatar":""},{"name":"Francis Ng","avatar":""},{"name":"Elaine Lui Siu-Ling","avatar":""},{"name":"Yammie Lam","avatar":""},{"name":"Law Lok-Lam","avatar":""},{"name":"Bao Fang","avatar":""},{"name":"Eddy Ko","avatar":""},{"name":"Joseph Cheng King-Kei","avatar":""},{"name":"Wong Gwan-Hong","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
