INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loc-dinh-ky-ii-than-long-giao', 'Lộc Đỉnh Ký II: Thần Long Giáo', 'Royal Tramp 2', 'https://phimimg.com/uploads/movies/20260713/loc-dinh-ky-ii-than-long-giao-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/loc-dinh-ky-ii-than-long-giao-poster.webp', '<p>Láu cá mà có duyên, Vi Tiểu Bảo chạm trán với một đối thủ cũ, có được các kỹ năng chiến đấu mới và dùng mồm mép để lấy lòng hoàng thượng.</p>', 'Full', 1, 'single', 'completed', 60, 1992, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Brigitte Lin","avatar":""},{"name":"Chingmy Yau Suk-Ching","avatar":""},{"name":"Natalis Chan Pak-Cheung","avatar":""},{"name":"Michele Reis","avatar":""},{"name":"Fennie Yuen Kit-Ying","avatar":""},{"name":"Vivian Chen","avatar":""},{"name":"Deric Wan","avatar":""},{"name":"Kent Tong Chun-Yip","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Damian Lau Chung-Yan","avatar":""},{"name":"Yen Shi-Kwan","avatar":""},{"name":"Sandra Ng Kwan-Yu","avatar":""},{"name":"Sharla Cheung","avatar":""},{"name":"Carol Tam","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lu ding ji 2","鹿鼎记2：神龙教","Royal Tramp II","녹정기 2","녹정기 2 - 신룡교","鹿鼎記2之神龍教","鹿鼎记2神龙教","鹿鼎記II神龍教","Royal Tramp 1992 - Tân Lộc Đỉnh Ký 2: Thần Long Giáo","Tân Lộc Đỉnh Ký 2 (1992)","鹿鼎记2","Luk ting kei II San lung gau","鹿鼎記2神龍教","녹정기 2: 신룡교","녹정기 Ⅱ - 신룡교","녹정기II와신룡교","녹정기II와 신룡교","녹정기II 신룡교","녹정기 II 신룡교","Royal Tramp 2 CN","The China Royal Tramp II","鹿鼎記 II : 神龍敎"]', 1784690324542);
