INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loc-dinh-ky-ii-than-long-giao', 'Lộc Đỉnh Ký II: Thần Long Giáo', 'Royal Tramp 2', 'lộc đỉnh ký ii: thần long giáo royal tramp 2 stephen chow brigitte lin chingmy yau suk-ching natalis chan pak-cheung michele reis fennie yuen kit-ying vivian chen deric wan kent tong chun-yip paul chun pui damian lau chung-yan yen shi-kwan sandra ng kwan-yu sharla cheung carol tam châu tinh trì lu ding ji 2 鹿鼎记2：神龙教 royal tramp ii 녹정기 2 녹정기 2 - 신룡교 鹿鼎記2之神龍教 鹿鼎记2神龙教 鹿鼎記ii神龍教 royal tramp 1992 - tân lộc đỉnh ký 2: thần long giáo tân lộc đỉnh ký 2 (1992) 鹿鼎记2 luk ting kei ii san lung gau 鹿鼎記2神龍教 녹정기 2: 신룡교 녹정기 ⅱ - 신룡교 녹정기ii와신룡교 녹정기ii와 신룡교 녹정기ii 신룡교 녹정기 ii 신룡교 royal tramp 2 cn the china royal tramp ii 鹿鼎記 ii : 神龍敎', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loc-dinh-ky-i-vi-tieu-bao', 'Lộc Đỉnh Ký I: Vi Tiểu Bảo', 'Royal Tramp', 'https://phimimg.com/uploads/movies/20260713/loc-dinh-ky-i-vi-tieu-bao-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/loc-dinh-ky-i-vi-tieu-bao-poster.webp', '<p>Lộc Đỉnh Ký là câu chuyện về chàng trai Vi Tiểu Bảo có xuất thân hèn kém, có mẹ là một kỷ nữ lầu xanh, không có gì trong tay nhưng bù lại rất thông minh và láu cá. Xem phim này, bạn sẽ thấy do được hoàng thượng ưu ái và có diễm phúc lớn khi cưới được tới 7 bà vợ xinh đẹp, tài giỏi. Cùng một bộ tiểu thuyết nhưng với những cải biên mới từ kịch bản, dàn diễn viên, kỹ xảo, trang phục, ngoại cảnh... phim Tân Lộc Đỉnh Kí hứa hẹn là một bộ phim đáng để xem.</p>', 'Full', 1, 'single', 'completed', 51, 1992, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Sharla Cheung","avatar":""},{"name":"Chingmy Yau Suk-Ching","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Natalis Chan Pak-Cheung","avatar":""},{"name":"Deric Wan","avatar":""},{"name":"Fennie Yuen Kit-Ying","avatar":""},{"name":"Vivian Chen","avatar":""},{"name":"Damian Lau Chung-Yan","avatar":""},{"name":"Sandra Ng Kwan-Yu","avatar":""},{"name":"Lau Kong","avatar":""},{"name":"Steve Lee Ka-Ting","avatar":""},{"name":"Brigitte Lin","avatar":""},{"name":"Xiong Xinxin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["鹿鼎記I","鹿鼎记","鹿鼎记1之皇城争霸","Royal Tramp","Lu ding ji","녹정기 1","鹿鼎记1","The China Royal Tramp I","鹿鼎記"]', 1784690324542);
