INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loc-dinh-ky-i-vi-tieu-bao', 'Lộc Đỉnh Ký I: Vi Tiểu Bảo', 'Royal Tramp', 'lộc đỉnh ký i: vi tiểu bảo royal tramp stephen chow ng man-tat sharla cheung chingmy yau suk-ching elvis tsui kam-kong natalis chan pak-cheung deric wan fennie yuen kit-ying vivian chen damian lau chung-yan sandra ng kwan-yu lau kong steve lee ka-ting brigitte lin xiong xinxin châu tinh trì 鹿鼎記i 鹿鼎记 鹿鼎记1之皇城争霸 royal tramp lu ding ji 녹정기 1 鹿鼎记1 the china royal tramp i 鹿鼎記', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-trang-nguyen-to-khat-nhi', 'Võ Trạng Nguyên Tô Khất Nhi', 'King Of Beggars', 'https://phimimg.com/uploads/movies/20260713/vo-trang-nguyen-to-khat-nhi-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/vo-trang-nguyen-to-khat-nhi-poster.webp', '<p>Võ Trạng Nguyên Tô Khất Nhi là một bộ phim võ thuật hài hước của Châu Tinh Trì trong vai một sĩ tử lên kinh ứng thí nhưng bị bắt vì gian lận trong thi cử, anh và cha anh đã phải lạy lục van xin để bảo toàn tính mạng. Nhưng lúc này anh lại bị kẻ thù hãm hại, chặt đứt gân tay, may mắn thay được một người lạ, cũng là người từng được anh cứu trước đây giúp đỡ trở thành vua ăn mày và cũng chính là người có thể cứu được vận mệnh của đất nước.</p>', 'Full', 1, 'single', 'completed', 54, 1992, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Sharla Cheung","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Vindy Chan Wai-Yee","avatar":""},{"name":"Norman Tsui Siu-Keung","avatar":""},{"name":"David Lam Wai","avatar":""},{"name":"Wong Chung","avatar":""},{"name":"Natalis Chan Pak-Cheung","avatar":""},{"name":"Lawrence Cheng Tan-Shui","avatar":""},{"name":"Matthew Wong Hin-Mung","avatar":""},{"name":"Peter Lai Bei-Dak","avatar":""},{"name":"Jackson Ng Yuk-Sue","avatar":""},{"name":"Chow Yee-Fan","avatar":""},{"name":"Lee Kin-Yan","avatar":""},{"name":"Kingdom Yuen King-Tan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["King of Beggars","Mo jong yuen So Hat-Yi","Mendigo a la fuerza","무장원 소걸아","武狀元蘇乞兒","King of Beggars 1992 - Võ Trạng Nguyên Tô Khất Nhi","Võ Trạng Nguyên Tô Khất Nhi (1992)"]', 1784690324542);
