INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-trang-nguyen-to-khat-nhi', 'Võ Trạng Nguyên Tô Khất Nhi', 'King Of Beggars', 'võ trạng nguyên tô khất nhi king of beggars stephen chow sharla cheung ng man-tat vindy chan wai-yee norman tsui siu-keung david lam wai wong chung natalis chan pak-cheung lawrence cheng tan-shui matthew wong hin-mung peter lai bei-dak jackson ng yuk-sue chow yee-fan lee kin-yan kingdom yuen king-tan châu tinh trì king of beggars mo jong yuen so hat-yi mendigo a la fuerza 무장원 소걸아 武狀元蘇乞兒 king of beggars 1992 - võ trạng nguyên tô khất nhi võ trạng nguyên tô khất nhi (1992)', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xam-xu-quan', 'Xẩm Xử Quan', 'Justice, My Foot!', 'https://phimimg.com/uploads/movies/20260713/xam-xu-quan-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/xam-xu-quan-poster.webp', '<p>Trạng sư Tống Sỹ Kiệt, do miệng lưỡi giảo hoạt, có thể biến trắng thành đen, bẻ cong sự thật nên được nhờ vả nhiều. Song vì nghiệp chướng quá lớn nên con trai cứ sinh ra là chết yểu. Sau cái chết của đứa con thứ 13, Sỹ Kiệt quyết tâm gác bút, từ bỏ nghiệp trạng sư. Cả gia đình ông mở hàng trà quán ở ngoại thành sống cuộc sống mới. Tuy vậy, khi một quả phụ bụng mang dạ chửa tới nhờ Tống Sỹ Kiệt giúp mình minh oan vụ án mạng của gia đình, ông lại phải tái xuất công đường. Vấp phải hệ thống công quyền thối nát, sẵn sàng dùng đủ thủ đoạn để lấp liếm sự thật, Tống Sỹ Kiệt phải trổ hết tài năng để một lần giành được công lý đích thực!</p>', 'Full', 1, 'single', 'completed', 40, 1992, 'Vietsub + Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Anita Mui Yim-Fong","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Carrie Ng Ka-Lai","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Bryan Leung Kar-Yan","avatar":""},{"name":"Eddy Ko Hung","avatar":""},{"name":"Mimi Chu Mai-Mai","avatar":""},{"name":"Cheng Kwun-Min","avatar":""},{"name":"Kingdom Yuen King-Tan","avatar":""},{"name":"Wong Yat-Fei","avatar":""},{"name":"Chun Wong","avatar":""},{"name":"Jonathan Ki-Yee Chik","avatar":""},{"name":"Wong Tin-Lam","avatar":""},{"name":"Wong San","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sam sei goon","Justice, My Foot!","Shen si guan","审死官","Justice My Foot","審死官","¡Justicia, ni hablar!"]', 1784690324542);
