INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xam-xu-quan', 'Xẩm Xử Quan', 'Justice, My Foot!', 'xẩm xử quan justice, my foot! stephen chow anita mui yim-fong ng man-tat carrie ng ka-lai paul chun pui bryan leung kar-yan eddy ko hung mimi chu mai-mai cheng kwun-min kingdom yuen king-tan wong yat-fei chun wong jonathan ki-yee chik wong tin-lam wong san châu tinh trì sam sei goon justice, my foot! shen si guan 审死官 justice my foot 審死官 ¡justicia, ni hablar!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-hoc-uy-long-ii', 'Trường Học Uy Long II', 'Fight Back to School 2', 'https://phimimg.com/uploads/movies/20260713/truong-hoc-uy-long-ii-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/truong-hoc-uy-long-ii-poster.webp', '<p>Trong phim Trường Học Uy Long 2 (1992), Châu Tinh Trì vẫn trở lại trong vai cảnh sát chìm Chow Sing-Sing, anh vừa bị giáng chức xuống làm cảnh sát tuần tra giao thông vì đã dám trêu chọc cấp trên của mình. Mặc dù không được cấp trên chỉ định làm nhiệm vụ nào nhưng anh vẫn quyết định xâm nhập vào một trường trung học để điều tra và ngăn chặn một vụ khủng bố đang chuẩn bị tiến hành. Chỉ có một vấn đề là Bộ Cảnh Sát không muốn anh tham gia vào vụ việc này nhưng bấy nhiêu đó cũng không thể làm khó được anh chàng cảnh sát tài hoa đẹp trai này.</p>', 'Full', 1, 'single', 'completed', 42, 1992, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Tinh Trì","avatar":""},{"name":"Trương Mẫn","avatar":""},{"name":"Ngô Mạnh Đạt","avatar":""},{"name":"Chu Ân","avatar":""},{"name":"Diệp Đức Nhàn","avatar":""},{"name":"Hoàng Triêm","avatar":""},{"name":"Hoàng Nhất Sơn","avatar":""},{"name":"Châu Văn Kiện","avatar":""},{"name":"Lý Lệ Nhị","avatar":""},{"name":"Kha Thụ Lương","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tao xue wei long 2","逃学威龙 II","도학위룡 2 - 첩혈위룡","Fight Back to School 2","Fight Back to School 1992 - Trường Học Uy Long phần 2","Trường Học Uy Long phần 2 (1992)","Fight Back to School II","첩혈위룡","도학위룡 2; 첩혈위룡","도학위룡 2: 첩혈위룡","逃學威龍２"]', 1784690324542);
