INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-ba-vuong-4', 'Nữ Bá Vương 4', 'The Inspector Wears Skirts IV', 'https://phimimg.com/upload/vod/20260420-1/0524cfff545fe783d699b33d34b4ee52.jpg', 'https://phimimg.com/upload/vod/20260420-1/c2a727b25e9dee9f6349e258ab18a6e0.jpg', '<p>Để ngăn chặn việc giải thể đội Bá VƯơng Hoa, các thành viên mới ngày thường hay xung đột với nhau nay dẹp qua một bên chuyện cá nhân để tìm và mời các công thần năm xưa của đội như đội trưởng Amy, nay là một bà vợ ly dị chồng sống cùng một đứa con nhỏ và Mây, nay có trạng thái tâm thần bất ổn, để giúp họ huấn luyện và tổ chức lại đội ngũ.</p>', 'Full', 1, 'single', 'completed', 22, 1992, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Sandra Ng Kwan-Yu","avatar":""},{"name":"Cynthia Khan","avatar":""},{"name":"Michelle Chia","avatar":""},{"name":"Moon Lee Choi-Fung","avatar":""},{"name":"Billy Lau Nam-Kwong","avatar":""},{"name":"Woo Fung","avatar":""},{"name":"Choi Jeong-Il","avatar":""},{"name":"Peter Chan Lung","avatar":""},{"name":"Paul Fonoroff","avatar":""},{"name":"Sheila Chan Suk-Lan","avatar":""},{"name":"Cheng Pak-Lam","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Joanna Chan","avatar":""},{"name":"Maryanna Yip San","avatar":""},{"name":"James Tien Chun","avatar":""},{"name":"Teddy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Inspector Wears Skirts 4","92 Ba wang hua yu Ba wang hua","霸王花4","92霸王花與霸王花","''92霸王花與霸王花"]', 1784690324542);
