INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-dot-nhap', 'Những Kẻ Đột Nhập', 'Sneakers', 'https://phimimg.com/upload/vod/20260128-1/ad88fd9f6544ed2266385be6051ef4e2.jpg', 'https://phimimg.com/upload/vod/20260128-1/6fef435967db666de4292991d5362450.jpg', '<p>Sneakers xoay quanh một nhóm chuyên gia an ninh chuyên kiểm tra hệ thống bằng cách đột nhập hợp pháp, cho đến khi họ bị một thế lực bí ẩn ép buộc tham gia vào vụ đánh cắp thiết bị có khả năng phá vỡ mọi mã hóa. Khi nhận ra sức mạnh nguy hiểm của công nghệ này, cả nhóm bị cuốn vào mạng lưới truy đuổi, phản bội và các bí mật từ quá khứ của chính mình. Để tự bảo vệ và ngăn thiết bị rơi vào tay kẻ xấu, họ buộc phải dùng trí tuệ và kỹ năng để lật ngược thế cờ.</p>', 'Full', 1, 'single', 'completed', 19, 1992, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robert Redford","avatar":""},{"name":"Sidney Poitier","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Dan Aykroyd","avatar":""},{"name":"River Phoenix","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Denise Dowse","avatar":""},{"name":"Timothy Busfield","avatar":""},{"name":"Mary McDonnell","avatar":""},{"name":"Donal Logue","avatar":""},{"name":"Eddie Jones","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"Bodhi Elfman","avatar":""},{"name":"Jo Marr","avatar":""},{"name":"Gary Hershberger","avatar":""},{"name":"Hanyee","avatar":""},{"name":"Time Winters","avatar":""},{"name":"Jun Asai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Héroes por azar","通天神偷","Проникване","Sneakers (Los Fisgones)","I Signori Della Truffa","Les Escrocs","Sneakers","شیادان","潜行者"]', 1784690324542);
