INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-canh-sat-3-sieu-canh-sat', 'Câu Chuyện Cảnh Sát 3: Siêu Cảnh Sát', 'Police Story 3: Super Cop', 'https://phimimg.com/upload/vod/20251222-1/37c1e149ee75d04ccf178fe7515eaf31.jpg', 'https://phimimg.com/upload/vod/20251222-1/7a7296b95a1e53cb43e52d62c9557061.jpg', '<p>Bộ phim tuy đã rất quen thuộc với người xem nhưng dường như nó có một sự cuốn hút lạ thường với sự kết hợp hoàn hảo giữa đạo diễn Stanley Tong và diễn viên Thành Long.Một nhân viên cảnh sát Hong Kong, được gửi đến Trung Hoa đại lục hoạt động ngầm nhằm phá vỡ đường dây buôn lậu thuốc phiện tại đây. Sau nhiều lỗ lực và sự nhanh nhạy vốn có của một viên cảnh sát anh đã đưa được người em của tên trùm buôn lậu ra khỏi tù, nhưng rồi anh bị lại bị điều đến một trụ sở khác của Hong Kong để làm viêc.Nơi mà người vợ của tên trùm đang bị bắt giữ tại Malaysia vì vận chuyển ma túy và sẽ sớm bị xử lý.Tuy nhiên, cô ta là người duy nhất biết được mã số của một tài khoản bí mật hàng triệu USD tại Thụy Sĩ. Anh và các cộng sự phải làm thế nào trong hoàn cảnh này, nếu xử lý cô ta thì mọi bí mật về mật mã sẽ không còn nhưng nếu muốn có mật mã thì không thể xử lý được cô ta.</p>', 'Full', 1, 'single', 'completed', 32, 1992, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Bill Tung Biu","avatar":""},{"name":"Josephine Koo Mei-Wah","avatar":""},{"name":"Kelvin Wong Siu","avatar":""},{"name":"William Duen Wai-Lun","avatar":""},{"name":"Philip Chan Yan-Kin","avatar":""},{"name":"Lo Lieh","avatar":""},{"name":"Mars","avatar":""},{"name":"Shum Wai","avatar":""},{"name":"Hon Yee-Sang","avatar":""},{"name":"Sam Wong Ming-Sing","avatar":""},{"name":"Lam Chi-Tai","avatar":""},{"name":"Cheng Ka-Sang","avatar":""},{"name":"Wo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ging chaat goo si III: Chiu kup ging chaat","Policijska priča 3: Super policajac","Jackie Chan - Police Story III","Police Story III: Supercop","Police Story III: Super Cop","Police Story III Super Cop","Jing cha gu shi III: Chao ji jing cha","Police Story 3: Super Cop","Полицијска прича 3: Суперполицајац","Полицијска прича 3","Policijska priča 3","Policijska priča 3: Superpolicajac","Police Story 3 - Supercop","Supercop","폴리스스토리 3: 초급경찰","Police Story 3: Supercop","ポリス･ストーリー3","警察故事 III：超級警察"]', 1784690324542);
