INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-thuy-hu', 'Anh Hùng Thủy Hử', 'Story of The Water Margin', 'https://phimimg.com/upload/vod/20251012-1/2ef4a1c97246e16792ba37aebdabce13.jpg', 'https://phimimg.com/upload/vod/20251012-1/aad1724283fb7815001edf8c17c30ed6.jpg', '<p>Thời kỳ Bắc Tống dưới triều đại của vua Tống Huy Tông, quan lại tham nhũng, dân chúng phải chịu cảnh lầm than. Nhiều người dân lương thiện bị áp bức và buộc phải nổi dậy. Cuối cùng, 108 vị anh hùng tụ họp tại núi Lương Sơn, lập nên một đội quân mang danh &quot;thay trời hành đạo&quot;, chuyên trừng trị quan lại tham nhũng và giúp đỡ người dân. Mỗi vị anh hùng đều có tài năng đặc biệt, từ võ nghệ cao cường đến mưu lược xuất sắc. Những câu chuyện nổi bật trong phim như Tống Giang trung nghĩa, Võ Tòng đánh hổ, Lâm Xung chịu đựng gian khổ hay Lỗ Trí Thâm đại náo, đã tạo nên sức hút mãnh liệt, khắc họa rõ nét tinh thần phản kháng của những anh hùng chống lại sự áp bức bất công trong xã hội.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 39, 1992, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Savio Tsang","avatar":""},{"name":"Lily Chung Suk-Wai","avatar":""},{"name":"Anita Yuen Wing-Yee","avatar":""},{"name":"Newton Lai Hon-Chi","avatar":""},{"name":"Jimmy Au Shui-Wai","avatar":""},{"name":"Lam Sheung-Mo","avatar":""},{"name":"Wayne Lai Yiu-Cheung","avatar":""},{"name":"Mak Tin-Yan","avatar":""},{"name":"Betty Mak Chui-Han","avatar":""},{"name":"Wong San","avatar":""},{"name":"Brian Wong","avatar":""},{"name":"Yeung Tak-Si","avatar":""},{"name":"Lee Ji-Kei","avatar":""},{"name":"Eugina Lau Mei-Guen","avatar":""},{"name":"Shing-Seung Wong","avatar":""},{"name":"Gordo","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["水滸英雄傳"]', 1784690324542);
