INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anh-hung-thuy-hu', 'Anh Hùng Thủy Hử', 'Story of The Water Margin', 'anh hùng thủy hử story of the water margin savio tsang lily chung suk-wai anita yuen wing-yee newton lai hon-chi jimmy au shui-wai lam sheung-mo wayne lai yiu-cheung mak tin-yan betty mak chui-han wong san brian wong yeung tak-si lee ji-kei eugina lau mei-guen shing-seung wong gordo 水滸英雄傳', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-nha-mot-minh-2-lac-o-new-york', 'Ở Nhà Một Mình 2: Lạc Ở New York', 'Home Alone 2: Lost In New York', 'https://phimimg.com/upload/vod/20250722-1/a0c514251a4944e1ad04a63914471826.jpg', 'https://phimimg.com/upload/vod/20250722-1/5825280d59229eeae9d55002af819cca.jpg', '<p>Sau khi tình cờ bay đến New York một mình, cậu bé Kevin McCallister nghỉ lại một khách sạn và chặn đứng âm mưu cướp cửa hàng đồ chơi của hai địch thủ cũ.</p>', 'Full', 1, 'single', 'completed', 19, 1992, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Macaulay Culkin","avatar":""},{"name":"Joe Pesci","avatar":""},{"name":"Daniel Stern","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"John Heard","avatar":""},{"name":"Brenda Fricker","avatar":""},{"name":"Tim Curry","avatar":""},{"name":"Devin Ratray","avatar":""},{"name":"Gerry Bamman","avatar":""},{"name":"Rob Schneider","avatar":""},{"name":"Michael C. Maronna","avatar":""},{"name":"Terrie Snell","avatar":""},{"name":"Hillary Wolf","avatar":""},{"name":"Maureen Elisabeth Shay","avatar":""},{"name":"Dana Ivey","avatar":""},{"name":"Eddie Bracken","avatar":""},{"name":"Kieran Cul","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Home Alone 2","Alone Again","Ensam Hemma 2","小鬼當家2：紐約迷途記","Hômu arôn 2","Reszkessetek, betörők! 2.: Elveszve New Yorkban","Monos sto spiti 2 - Hamenos sti Nea Yorki","Μόνος στο σπίτι 2: Χαμένος στη Νέα Υόρκη","Üksinda kodus 2: kadunud New Yorgis","Mi Pobre Angelito 2","Maman, j''ai encore raté l''avion...","Alene hjemme 2: Glemt i New York","Maman, j''ai encore raté l''avion et je suis perdu dans New York","Mi pobre angelito 2 - Perdido en Nueva York","Sozinho em Casa 2: Perdido em Nova Iorque","Singur acasa: Pierdut in New York","나 홀로 집에 2","ホームアローン2","وحيد في المنزل 2","Home Alone II: Lost In New York","לבד בבית 2: אבוד בניו יורק","Ở Nhà Một Mình 2: Lạc Ở New York","Үйде жалғыз қалғанда 2: Нью-Йоркте жоғалған","Один дома 2: Потерявшийся в Нью-Йорке","Evdə Tək 2","Kevin Allein in New York","Maman, (2) j''ai encore raté l''avion !","Maman, j’ai raté l’avion 2 - Maman, j’ai encore raté l’avion !","寶貝智多星2","Տանը Մենակ 2","Tany menak","Home Alone 2: Lost in New York"]', 1784690324542);
