INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('o-nha-mot-minh-2-lac-o-new-york', 'Ở Nhà Một Mình 2: Lạc Ở New York', 'Home Alone 2: Lost In New York', 'ở nhà một mình 2: lạc ở new york home alone 2: lost in new york macaulay culkin joe pesci daniel stern catherine o''hara john heard brenda fricker tim curry devin ratray gerry bamman rob schneider michael c. maronna terrie snell hillary wolf maureen elisabeth shay dana ivey eddie bracken kieran cul home alone 2 alone again ensam hemma 2 小鬼當家2：紐約迷途記 hômu arôn 2 reszkessetek, betörők! 2.: elveszve new yorkban monos sto spiti 2 - hamenos sti nea yorki μόνος στο σπίτι 2: χαμένος στη νέα υόρκη üksinda kodus 2: kadunud new yorgis mi pobre angelito 2 maman, j''ai encore raté l''avion... alene hjemme 2: glemt i new york maman, j''ai encore raté l''avion et je suis perdu dans new york mi pobre angelito 2 - perdido en nueva york sozinho em casa 2: perdido em nova iorque singur acasa: pierdut in new york 나 홀로 집에 2 ホームアローン2 وحيد في المنزل 2 home alone ii: lost in new york לבד בבית 2: אבוד בניו יורק ở nhà một mình 2: lạc ở new york үйде жалғыз қалғанда 2: нью-йоркте жоғалған один дома 2: потерявшийся в нью-йорке evdə tək 2 kevin allein in new york maman, (2) j''ai encore raté l''avion ! maman, j’ai raté l’avion 2 - maman, j’ai encore raté l’avion ! 寶貝智多星2 տանը մենակ 2 tany menak home alone 2: lost in new york', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-heo-mau-do', 'Chú Heo Màu Đỏ', 'Porco Rosso', 'https://phimimg.com/upload/vod/20250716-1/870fccf52a4451b592279c0cbdc87afe.jpg', 'https://phimimg.com/upload/vod/20250716-1/8589484a6d5a9d8e8d9ef86c4ee6f82d.jpg', '<p>Không tặc hoành hành khắp vùng biển Adriatic và chỉ có tay phi công người Ý này mới đủ can trường để đương đầu với chúng. Có điều, ông ta là phi công nửa người nửa heo.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 1992, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Shūichirō Moriyama","avatar":""},{"name":"Tokiko Kato","avatar":""},{"name":"Bunshi Katsura VI","avatar":""},{"name":"Tsunehiko Kamijô","avatar":""},{"name":"Akemi Okamura","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Hiroko Seki","avatar":""},{"name":"Reizō Nomoto","avatar":""},{"name":"Osamu Saka","avatar":""},{"name":"Yu Shimaka","avatar":""},{"name":"Mahito Tsujimura","avatar":""},{"name":"Minoru Yada","avatar":""},{"name":"Yoko Soumi","avatar":""},{"name":"Yuzuru Fujimoto","avatar":""},{"name":"Tatsuyuki Jinnai","avatar":""},{"name":"Kazunori Arai","avatar":""},{"name":"Nobuo Tanaka","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Crimson Pig","Kurenai no buta","Кнур Багряний","Txarri gorrixa","På flygande uppdrag","飞天红猪侠","Porco Rosso: O Porquinho Voador","飛天紅豬俠","Pòrco Rósso","Порко Россо","Porco Rosso: O Último Herói Romântico","O Porquinho Voador","紅の豚"]', 1784690324542);
