INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('maruta-2-phong-thi-nghiem-cua-ac-quy', 'Maruta 2: Phòng Thí Nghiệm Của Ác Quỷ', 'Man Behind the Sun 2: Laboratory of the Devil', 'https://phimimg.com/upload/vod/20250710-1/8d14f1943a798e4c8ea66207a8ac47ec.jpg', 'https://phimimg.com/upload/vod/20250710-1/c715ff96d5f86162827c69023066f281.jpg', '<p>Maruta 2: Phòng Thí Nghiệm Của Ác Quỷ tiếp tục khai thác những tội ác tàn bạo của Đơn vị 731 – một đơn vị nghiên cứu vũ khí sinh học và hóa học thuộc Quân đội Đế quốc Nhật Bản trong Thế chiến thứ hai. Bộ phim được dựa trên các sự kiện có thật và các tài liệu lịch sử, tập trung vào những thí nghiệm vô nhân đạo mà đơn vị này đã tiến hành trên các tù nhân chiến tranh, trong đó có nhiều người Trung Quốc và Nga.</p>', 'Full', 1, 'single', 'completed', 18, 1992, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Kong","avatar":""},{"name":"Yuen-Ching Leung","avatar":""},{"name":"Wan Ying Ying","avatar":""},{"name":"Gang Wang","avatar":""},{"name":"Wang Runshen","avatar":""},{"name":"Andrew Yu","avatar":""},{"name":"Zhu Decheng","avatar":""},{"name":"Zhang Guowen","avatar":""},{"name":"Jiang Yishou","avatar":""},{"name":"Xingqiang Li","avatar":""},{"name":"Dingyao Liu","avatar":""},{"name":"Xu Ge","avatar":""},{"name":"Gong Zhu","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Unit 731: Laboratory of the Devil","Men Behind the Sun 2","Men Behind the Sun 2: Laboratory of the Devil","El laboratorio del diablo","黑太陽731續集之殺人工廠","Maruta 2: Laboratory of the Devil","Man Behind the Sun 2: Laboratory of the Devil","Hei Tai Yang 731: Xu ji zhi sha ren gong chang","จับคนมาทำเชื้อโรค","Sfagi sto stratopedo ton kolasmenon 2: To ergastiri tou Diavolou","Hak tai yeung 731 chuk chap ji sai yan gung chong","Jednostka 731 - Laboratorium diabła","Люди за Солнцем 2: Лаборатория дьявола","Hắc Thái Dương 731 2: Công Xưởng Sát Nhân","Man Behind the Sun 2","마루타 디 오리지널: 살인공창"]', 1784690324542);
