INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('maruta-2-phong-thi-nghiem-cua-ac-quy', 'Maruta 2: Phòng Thí Nghiệm Của Ác Quỷ', 'Man Behind the Sun 2: Laboratory of the Devil', 'maruta 2: phòng thí nghiệm của ác quỷ man behind the sun 2: laboratory of the devil chu kong yuen-ching leung wan ying ying gang wang wang runshen andrew yu zhu decheng zhang guowen jiang yishou xingqiang li dingyao liu xu ge gong zhu unit 731: laboratory of the devil men behind the sun 2 men behind the sun 2: laboratory of the devil el laboratorio del diablo 黑太陽731續集之殺人工廠 maruta 2: laboratory of the devil man behind the sun 2: laboratory of the devil hei tai yang 731: xu ji zhi sha ren gong chang จับคนมาทำเชื้อโรค sfagi sto stratopedo ton kolasmenon 2: to ergastiri tou diavolou hak tai yeung 731 chuk chap ji sai yan gung chong jednostka 731 - laboratorium diabła люди за солнцем 2: лаборатория дьявола hắc thái dương 731 2: công xưởng sát nhân man behind the sun 2 마루타 디 오리지널: 살인공창', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-co-gia-doi', 'Quý Cô Giả Dối', 'False Lady', 'https://phimimg.com/upload/vod/20250624-1/71b53984456a8c88eaa3814c3aa3e000.jpg', 'https://phimimg.com/upload/vod/20250624-1/ef95ec3b3bf4fe2323adf4f2b51f3734.jpg', '<p>A Mạn (do Lý Trung Ninh thủ vai) và Kỳ Kỳ (do Cố Kiệt thủ vai) đã yêu nhau nhiều năm, tình cảm vô cùng sâu đậm. Cả hai đều có tính cách tự do, phóng khoáng nên đã hứa rằng dù yêu nhau nhưng tuyệt đối sẽ không kết hôn. Trong một tai nạn bất ngờ, A Mạn không may thiệt mạng khi cố gắng cứu Kỳ Kỳ. Linh hồn anh đến âm phủ mới phát hiện ra mình vẫn chưa hết dương thọ, nhưng khi trở về dương gian thì thi thể đã bị hỏa táng. Không còn cách nào khác, A Mạn đành phải nhập vào thân xác của một người phụ nữ và tìm đến Kỳ Kỳ. Tuy nhiên, Kỳ Kỳ lại lầm tưởng đây là một người tình cũ của A Mạn khi còn sống, gây ra một hiểu lầm lớn. Trong lúc rối ren, A Mạn lấy thân phận của em họ Mạn Địch (do Trần Dĩnh Chi thủ vai) để thuyết phục Kỳ Kỳ đồng ý cho “cô” ở lại. John (do Đào Đại Vũ thủ vai), bạn thân của A Mạn khi còn sống, sau nhiều lần thử thách cuối cùng cũng tin rằng người phụ nữ kiều diễm trước mặt chính là người bạn tinh nghịch năm nào. Mạn Địch ngày càng trở nên duyên dáng, thậm chí bắt đầu nảy sinh ham muốn với đàn ông, khiến John âm thầm ghen tuông. Cô dùng vẻ quyến rũ để giúp ký kết một thương vụ lớn và tỏa sáng tại buổi tiệc mừng công của công ty, trong khi John lại lặng lẽ rời đi. Thực ra, Mạn Địch đã sớm nảy sinh tình cảm với anh. Cô lặng lẽ đi theo và cuối cùng hai người cũng thổ lộ tình cảm, từ đôi bạn thân trở thành người yêu.</p>', 'Full', 1, 'single', 'completed', 20, 1992, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chan Wing-Chi","avatar":""},{"name":"Michael Tao Tai-Yu","avatar":""},{"name":"Lee Chung-Ling","avatar":""},{"name":"Charlie Cho Cha-Lee","avatar":""},{"name":"Lee Yuet-Sin","avatar":""},{"name":"Jacky Chan Kin-Yat","avatar":""},{"name":"Goo Wai-Jan","avatar":""},{"name":"Hon Chai","avatar":""},{"name":"Ho Pak-Kwong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ai ye nu peng you","哎吔女朋友"]', 1784690324542);
