INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-vai-nguoi-tot', 'Chỉ Vài Người Tốt', 'A Few Good Men', 'https://phimimg.com/upload/vod/20250618-1/6542dd6656e38f54996b13f4056bf768.jpg', 'https://phimimg.com/upload/vod/20250618-1/72adb0fcd7b1afe6a1c144626a253611.jpg', '<p>Án mạng xảy ra trong đơn vị lính thủy đánh bộ. Hạ sĩ Harold Dawson và binh nhì Louden Downey trói và nhét giẻ vào mồm binh nhì William T. Santiago. Sau đó vài giờ anh này tử vong. Các điều tra viên cho rằng trong giẻ có thuốc độc. Harold và Louden bị bắt và truy tố về tội giết người. Đại tá Nathan R. Jessep, chỉ huy cao nhất tại căn cứ, chỉ định nữ trung úy JoAnne Galloway, thanh tra nội bộ và trung úy Daniel Kaffee, thanh tra tư pháp hải quân, làm luật sư bào chữa cho hai bị cáo trước tòa án quân sự. Sau khi thu thập khá đầy đủ chứng cứ, JoAnne và Daniel phát hiện ra rằng vụ án mạng không phải là hậu quả của một mối tư thù cá nhân.</p>', 'Full', 1, 'single', 'completed', 20, 1992, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Jack Nicholson","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Kevin Pollak","avatar":""},{"name":"James Marshall","avatar":""},{"name":"J. T. Walsh","avatar":""},{"name":"Christopher Guest","avatar":""},{"name":"J.A. Preston","avatar":""},{"name":"Matt Craven","avatar":""},{"name":"Wolfgang Bodison","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"John M. Jackson","avatar":""},{"name":"Noah Wyle","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Lawrence Lowe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770