INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-vuong-quoc-tren-may', 'Doraemon: Nobita và Vương Quốc Trên Mây', 'Doraemon: Nobita and the Kingdom of Clouds', 'https://phimimg.com/upload/vod/20250521-1/53bf90587900f357d3f577fa3ffec4e7.jpg', 'https://phimimg.com/upload/vod/20250521-1/2bd42420e47fbf84301d6a504ea18ba6.jpg', '<p>Doraemon đã sử dụng những bảo bối của mình để cùng với Nobita tạo ra thế giới của riêng cậu trên bầu trời, một đám mây khổng lồ. Trong cuộc hành trình trên đám mây, cả nhóm nhận ra những người ngoài hành tinh đang tìm cách phá hủy nền văn minh loài người vì thiếu cam kết với môi trường. Doraemon và nhóm bạn phải tìm đồng minh và thuyết phục những người trên mây trên Trái đất rằng có những người chiến đấu vì thiên nhiên. Trong cuộc phiêu lưu của mình, gặp gỡ những người bạn tốt, trải qua vô số nguy hiểm, chạm trán với động vật thời tiền sử và cố gắng để bảo vệ hành tinh của chúng ta.</p>', 'Full', 1, 'hoathinh', 'completed', 21, 1992, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Sachiko Chijimatsu","avatar":""},{"name":"Masayuki Katô","avatar":""},{"name":"Ryoichi Tanaka","avatar":""},{"name":"Miki Ito","avatar":""},{"name":"Akira Murayama","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["雲之王國","Doraemon Nobita to Kumo no okoku","Nobita and the Kingdom of Clouds","Doraemon e il regno delle nuvole","大雄與雲之國","哆啦A夢：大雄與雲之王國","Doraemon - The Movie: Il Regno delle Nuvole","Doraemon Nobita và vương quốc trên mây","도라에몽 노비타와 구름의 왕국","โดราเอมอน ตอน บุกอาณาจักรเมฆ","Doraemon the Movie: नोबिता इन जन्नत नं. 1","doremon vuong quoc tren may","哆啦A梦：大雄的云之王国","映画ドラえもん のび太と雲の王国"]', 1784690324542);
