INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-phun-lua', 'Cô Nàng Phun Lửa', 'She Starts The Fire', 'https://phimimg.com/upload/vod/20250410-1/59ee397b7c6c49e53c0cdc5aab3d1921.jpg', 'https://phimimg.com/upload/vod/20250410-1/9d2f7823a9942e0566ac403d8f18c31f.jpg', '<p>Xá Xíu (do Trịnh Đan Sâm thủ vai) là một thanh niên lông bông, sống bằng nghề giả thần giả quỷ để lừa tiền thiên hạ. Một ngày nọ, tại nhà của chị Đại B (do Diệp Đức Hiền thủ vai) – một bà chủ làm việc trong hộp đêm và cũng là người cho Xá Xíu thuê trọ – xuất hiện một vị khách đặc biệt: Vân Vân (do Khâu Thục Trinh thủ vai), cô cháu gái xinh đẹp của chị. Chị Đại B lập mưu dụ dỗ Vân Vân làm vũ nữ hộp đêm để kiếm tiền từ sắc đẹp của cô. Một đêm nọ, Pháo Ca – trùm xã hội đen – đến hộp đêm giải trí, vừa thấy Vân Vân đã mê mẩn nhan sắc nên sai người bắt cô về. Không ai ngờ rằng Vân Vân – tưởng là một cô gái yếu đuối – lại sở hữu siêu năng lực có thể phun lửa, và chính năng lực đó đã giúp cô thoát thân. Xá Xíu sau đó phát hiện ra bí mật này và lập tức nảy ra một âm mưu đầy hiểm độc…</p>', 'Full', 1, 'single', 'completed', 15, 1992, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Chingmy Yau Suk-Ching","avatar":""},{"name":"Lawrence Cheng Tan-Shui","avatar":""},{"name":"Deanie Yip Tak-Han","avatar":""},{"name":"Carol Cheng","avatar":""},{"name":"Paul Chu Kong","avatar":""},{"name":"Michael Lai Siu-Tin","avatar":""},{"name":"Manfred Wong Man-Chun","avatar":""},{"name":"Peter Lai Bei-Dak","avatar":""},{"name":"John Ching Tung","avatar":""},{"name":"Vindy Chan Wai-Yee","avatar":""},{"name":"Kingdom Yuen King-Tan","avatar":""},{"name":"Lee Siu-Kay","avatar":""},{"name":"Damian Lau Chung-Yan","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Pen huo nu lang","噴火女郎"]', 1784690324542);
