INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-nga', 'Vô Ngã', 'Baraka', 'https://phimimg.com/upload/vod/20250324-1/9059fd3dd8ad2839e4279d5bac5b18c1.jpg', 'https://phimimg.com/upload/vod/20250324-1/2bd1bdafc28a537678740bff4b8265f7.jpg', '<p>Không có câu chuyện thông thường, bộ phim này trình bày những thước phim về con người, địa điểm và mọi thứ từ khắp nơi trên thế giới. Từ những thành phố hỗn loạn đến những vùng đất hoang vu cằn cỗi, bộ phim đưa người xem trên toàn cầu chứng kiến nhiều cảnh tượng khác nhau trong cả lĩnh vực tự nhiên và công nghệ. Đi sâu vào các trại tập trung trước đây, tác phẩm không né tránh mặt tối của nhân loại, và cuối cùng cho thấy phần nào thế giới được kết nối với nhau bởi cả bi kịch và sự sống động của cuộc sống.</p>', 'Full', 1, 'single', 'completed', 12, 1992, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patrick Disanto","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Baraka - Eine Welt jenseits der Worte","Világok arca - Baraka","Baraka"]', 1784690324542);
