INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-tu-gia-di-cong-tac', 'Thái Tử Gia Đi Công Tác', 'Freedom Run Q', 'https://phimimg.com/upload/vod/20250104-1/6af0a4f8c451f39a28ca2e8a944eba14.jpg', 'https://phimimg.com/upload/vod/20250104-1/cce7a4ad37c5d0dfdefad17bf65e16c8.jpg', '<p>Thám tử cảnh sát đặc biệt Zhang Depei (do Zhang Jianting thủ vai) đến từ Hoa Kỳ và sĩ quan cảnh sát địa phương Hồng Kông Zheng Tianhui (do Zheng Danshui thủ vai) là hai chàng trai trẻ xuất thân từ những gia đình giàu có. Họ luôn vi phạm mong muốn của cha mẹ để theo đuổi nghề y. và chọn nghề cảnh sát. Khi điều tra một vụ án ma túy, cả hai không hề quen biết nhau và trở thành cộng sự tốt. Khi đó, trùm ma túy Tam giác vàng đã phát triển một loại ma túy cực kỳ tinh khiết - bụi thiên thần. Chúng có ý định dùng Hong Kong làm bàn đạp để đưa ma túy và công thức của nó vào Mỹ. Để ngăn chặn sự lây lan của ma túy, cảnh sát Hoa Kỳ và Hồng Kông đã cùng nhau điều tra vụ án. Tình báo tiết lộ rằng doanh nhân giàu có Chen Baichang và đoàn võ thuật Vân Nam sắp biểu diễn ở Hồng Kông đã bị nghi ngờ nghiêm trọng và ông chủ của họ đã cải trang và lẻn vào địa điểm...</p>', 'Full', 1, 'single', 'completed', 15, 1992, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Bill Tung Biu","avatar":""},{"name":"Alfred Cheung Kin-Ting","avatar":""},{"name":"Lawrence Cheng Tan-Shui","avatar":""},{"name":"Elizabeth Lee Mei-Fung","avatar":""},{"name":"Jeanette Lin Tsui","avatar":""},{"name":"Yvonne Yung Hung","avatar":""},{"name":"Derek Cheung Chi-Chuen","avatar":""},{"name":"Chan Chi-Fai","avatar":""},{"name":"Lam Kau","avatar":""},{"name":"Sunny Fang Kang","avatar":""},{"name":"Dion Lam Dik-On","avatar":""},{"name":"Frankie Chin Chi-Leung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["太子爺出差"]', 1784690324542);
