INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-thoi-dai', 'Đại Thời Đại', 'The Greed of Man', 'https://phimimg.com/upload/vod/20241120-1/cdb048a3dbc6d7b0788967543a6c16dc.jpg', 'https://phimimg.com/upload/vod/20241120-1/49ae018df7eac8c8e9b84639fe614bad.jpg', '<p>Đại Thời Đại là một bộ phim truyền hình Hồng Kông do đài TVB sản xuất năm 1992. Nội dung phim kéo dài qua ba thập niên từ những năm 70 tới những năm 90 của thế kỷ 20, kể về những mâu thuẫn thanh toán lẫn nhau giữa các thế lực xã hội đen cho tới những cuộc chiến trong thị trường cổ phiếu Hồng Kông.Bộ phim được đánh giá rất cao khi trình chiếu vào tháng 10 năm 1992.Đồng thời bộ phim cũng gây &quot;hiệu ứng Đinh Giải&quot; trong ngành cổ phiếu Hồng Kông.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 15, 1992, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Sean Lau Ching-Wan","avatar":""},{"name":"Adam Cheng","avatar":""},{"name":"Amy Kwok","avatar":""},{"name":"Ben Wong","avatar":""},{"name":"Alice Chan","avatar":""},{"name":"Xu Jinglei","avatar":""},{"name":"Kenneth Chan","avatar":""},{"name":"Anders Nelsson","avatar":""},{"name":"Belinda Hamnett","avatar":""},{"name":"Kristal Tin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["大时代","The Greed of Man","大時代"]', 1784690324542);
