INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-loa-the', 'Sát Thủ Lõa Thể', 'Naked Killer', 'https://phimimg.com/upload/vod/20241031-1/8daccc58b727750ffb449b2b2fa4c4e9.jpg', 'https://phimimg.com/upload/vod/20241031-1/0c48675b4434a31164afa8bd0a3c8e03.jpg', '<p>Sát Thủ Lõa Thể (Naked Killer 1992) kể về câu chuyện của một cô gái trẻ bí ẩn trẻ tuổi tên Kitty, người được đào tạo đặc biệt bởi một chuyên gia về võ thuật để trở thành một sát thủ chuyên nghiệp. Sau đó, cô được tuyển dụng bởi một kẻ giết người thực sự, một phụ nữ nổi bật nhắm mục tiêu vào những kẻ hiếp dâm và thực hiện các hành vi tình dục điên cuồng ngay tại nhà của những kẻ đó, tất cả được làm việc một cách nhanh gọn, không dấu vết nhưng cái cách mà những sát thủ này hạ gục con mồi không khỏi khiến các điều tra viên cảm thấy khó hiểu, đặc biệt họ không nghĩ rằng nó được thực hiện bởi một người con gái.</p>', 'Full', 1, 'single', 'completed', 13, 1992, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Chingmy Yau","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Carrie Ng","avatar":""},{"name":"Yiu Wai","avatar":""},{"name":"Hui Siu-Hung","avatar":""},{"name":"Madoka Sugawara","avatar":""},{"name":"Dick Lau Tik-Chi","avatar":""},{"name":"Ken Lo","avatar":""},{"name":"Yu Kwok-Lok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chik loh go yeung","Desnuda para matar","เพชฌฆาตกระสุนเปลือย","Chiklo Gouyeung","赤裸羔羊","Naked Killer","Çılpaq Qatil"]', 1784690324542);
