INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-dia-phi-ung', 'Đại Địa Phi Ưng', 'Land Of The Condors', 'https://phimimg.com/upload/vod/20240711-1/be65e4f6e807ba0419cc762205ba8e5a.jpg', 'https://phimimg.com/upload/vod/20240711-1/9bda351573e554784057cfa430dce4cc.jpg', '<p><em>Phim võ thuật Hồng Kong - Trung Quốc sản xuất năm 1992 với những màn võ thuật đẹp mắt với phần thể hiện của các diễn viên Lê Mỹ Nhàn, Trịnh Lợi, Lương Gia Huy, Chu Khiết Nghi, Thiệu Trong Hanh, Ngô Trấn Vũ, Hồ Tiết Sơn, Ngô Cương, Lưu Tú Bình. Phim Đại Địa Phi Ưng xoay quanh những người sống ở đại mạc tin tưởng vào thần linh thánh mẫu, nhưng rồi cuộc sống bình yên của họ cũng không thể tiếp tục duy trì, các thị tộc tranh giành quyền trượng chém giết lẫn nhau và những nhân sĩ trong giang hồ cũng tìm đến.</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 19, 1992, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Trấn Vũ","avatar":""},{"name":"Lê Mỹ Nhàn","avatar":""},{"name":"Lưu Gia Huy","avatar":""},{"name":"Thiệu Trọng Hành","avatar":""},{"name":"Ngô Cương","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324542);
