INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-dia-phi-ung', 'Đại Địa Phi Ưng', 'Land Of The Condors', 'đại địa phi ưng land of the condors ngô trấn vũ lê mỹ nhàn lưu gia huy thiệu trọng hành ngô cương ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-anh-kim-dao', 'Vô Ảnh Kim Đao', 'The Revelation Of The Last Hero', 'https://phimimg.com/upload/vod/20240711-1/37d710eaa3c4974c3736f807d5344895.jpg', 'https://phimimg.com/upload/vod/20240711-1/e1ec9f205b4679076f915a8785fc3982.jpg', '<p><em>Quyết chiến của 2 cao thủ Tư Mã Tung Hoành và Hồng Chân, Hồng Chân thua, võ công bị phế đày tới đảo Vô Ngã. Hoàng Cực Thần Toán Dao Khan Tiết đoán biết Hoành sẽ xưng bá gây họa cho võ lâm. Hoành toan tính giết Dao Khan Tiết để bịt đầu mối. Tiết mang theo con gái là Bình trốn trên thuyền của Hoành , và cùng Chân hướng về đảo Vô Ngã. Trên đường gặp bão, thuyền bị chìm, Hoành tưởng mọi người đã chết, nhưng thật sự đã thoát nạn và trôi dạt vào 1 đảo khác. Bảy năm sau, Bình trở về trả thù. Chàng trai trẻ Lạc Phong vô tình bị lôi cuốn vào cuộc ân oán này.Vì giữ mạng cho chàng, phải nhờ đến sứ giả Hồng Bào Hiệp Nguyên Thuật. Sau đó, cùng quen biết với Bình, Hách Liên Bột Bột và Lăng Tương. Đồng thời, trong giang hồ nổi tiếng về uy lực của thanh Phong chi đao. Ai sở hữu được nó sẽ hùng bá thiên hạ. Chính vì thế, cuộc truy tìm thanh đao này đã khiến giang hồ nổi lên bao sóng gió. Sau khi Tương vì thất tình, nên đã ngã vào vòng tay của Lực Hành - con trai của Khan Tiết - có tính tình quái lạ, vì danh lợi làm những việc bại hoại võ lâm. Phong, Bình và Bột đành phải liên kết đối phó, nhiều trận ác chiến liên tiếp xảy ra.</em></p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 19, 1992, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Quách Phú Thành","avatar":""},{"name":"Viên Khiết Doanh","avatar":""},{"name":"Lương Tiểu Băng","avatar":""},{"name":"Lâm Văn Long","avatar":""},{"name":"Thái Thiếu Phấn","avatar":""},{"name":"Lương Gia Nhân","avatar":""},{"name":"Quách Chính Hồng","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324542);
