INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-anh-kim-dao', 'Vô Ảnh Kim Đao', 'The Revelation Of The Last Hero', 'vô ảnh kim đao the revelation of the last hero quách phú thành viên khiết doanh lương tiểu băng lâm văn long thái thiếu phấn lương gia nhân quách chính hồng ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-cay-3-am-binh', 'Ma Cây 3: Âm Binh', 'Evil Dead III: Army Of Darkness', 'https://phimimg.com/upload/vod/20240825-1/0237a389f4c382d22f4f580f5ab3265f.jpg', 'https://phimimg.com/upload/vod/20240825-1/29ba8c5b0932fad86e659750ac7ce8f1.jpg', '<p>Tiếp nối thành công của 2 phần trước, đạo diễn Sam Raimi cùng nhà sản xuất Universal Pictures tiếp tục cuộc hành trình chống lại Ma Cây trong phần 3 được ra mắt vào năm 1992 , Ma Cây 3: Đội Quân Bóng Tối hứa hẹn mang tới nhiều cảnh quay kinh dị, rùng rợn và ám ảnh nhất khi được đầu tư nhiều hơn hẳn phần 1 và 2 với số tiền là 10 triệu USD. Đây cũng là phần cuối cùng trong loạt phim kinh dị mang tên Ma Cây được rất nhiều người yêu thích, Evil Dead 3: Army Of Darkness sẽ khép lại cuộc chiến người và quỷ với nhịp độ cao, nhiều cảnh chém giết lên đến cao trào và một nội dung lôi cuốn. Hẳn nhiều người còn nhớ quyển sách Necronomicon trong Ma Cây 2 vốn được biết tới là một quyển sách của người chết. Và Ash đang lạc vào thế giới của những năm 1300, khi vua Arthur còn trị vì, bởi anh vô tình đọc sai một câu thần chú. Ma Cây 3 có nội dung chính là xoay quanh cuộc hành trình của Ash trong quá khứ với rất nhiều sự việc xảy ra mà không thể nào lường trước được bởi mọi thứ đến với anh một cách quá bất ngờ. Không lâu sau khi bị lạc vào quá khức, Ash nhanh chóng bị bắt bởi những người lính trong hoàng gia bởi vì họ cho rằng anh là gián điệp của Duke Henry, người đang gây chiến với đức vua Arthur. Tuy nhiên, khi bị bắt vào ngục, Ash đã giết được 2 con quái vật và được phong làm anh hùng, anh được gán ghép với một trong những người em gái xinh đẹp của Arthur, Sheila. Liệu rằng anh chàng sẽ ở lại quá khứ để lấy người em gái của Vua hay là cố gắng tìm mọi cách để quay trở về hiện tại ….</p>', 'Full', 1, 'single', 'completed', 14, 1992, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bruce Campbell","avatar":""},{"name":"Embeth Davidtz","avatar":""},{"name":"Marcus Gilbert","avatar":""},{"name":"Ian Abercrombie","avatar":""},{"name":"Richard Grove","avatar":""},{"name":"Timothy Patrick Quill","avatar":""},{"name":"Michael Earl Reid","avatar":""},{"name":"Bridget Fonda","avatar":""},{"name":"Patricia Tallman","avatar":""},{"name":"Ted Raimi","avatar":""},{"name":"Deke Anderson","avatar":""},{"name":"Deke Anderson","avatar":""},{"name":"Bruce Thomas","avatar":""},{"name":"Sara Shearer","avatar":""},{"name":"Shiva Gordon","avatar":""},{"name":"Billy Bryan","avatar":""},{"name":"Nadi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324542);
