INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ma-cay-3-am-binh', 'Ma Cây 3: Âm Binh', 'Evil Dead III: Army Of Darkness', 'ma cây 3: âm binh evil dead iii: army of darkness bruce campbell embeth davidtz marcus gilbert ian abercrombie richard grove timothy patrick quill michael earl reid bridget fonda patricia tallman ted raimi deke anderson deke anderson bruce thomas sara shearer shiva gordon billy bryan nadi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-dai-hoang-hau', 'Nhất Đại Hoàng Hậu', 'Empress Of The Time', 'https://phimimg.com/upload/vod/20240616-1/5bff733e22c8adf455b8abfd8a2f288f.jpg', 'https://phimimg.com/upload/vod/20240616-1/4568ea12caad362e78716093e6ac04e1.jpg', '<p><em>Một câu chuyện về quyền lực,gia tộc,tình yêu của một nữ nhi hoàn mỹ. Đó là Hiếu Trang - nhan sắc khuynh quốc khuynh thành,trí tuệ uyên bác hưng quốc an bang,từ bi khoan dung khắp thiên hạ. Đại Ngọc Nhi - Hiếu Trang Văn hoàng hậu họ Bác Nhĩ Tể Cát Đặc Thị tên là Bố Mộc Bố Thái theo truyền thuyết dã sử gọi là Đại Ngọc Nhi. Năm 1613,sinh ra tại Mông Cổ Năm 1623,Đại Ngọc Nhi vô tình gặp gỡ với Ái Tân Giác La Đa Nhĩ Cổn Hai người từ thanh mai trúc mã đã thật sự yêu nhau nên nguyện lấy nhau.Nhưng Đại Ngọc Nhi phải theo sắp đặt của cha mình phải trở thành trác phúc tấn của Khả Hãn Hoàng Thái Cực.Song khó mà cắt được tình cảm sâu đậm của cô và Nhiếp Chính vương Đa Nhĩ Cổn.Sau này,Hoàng Thái Cực biết chuyện đã nghi ngờ a ca Phúc Lâm có phải con Đa Nhĩ Cổn không ? Đaị Ngọc Nhi dám yêu dám hận,từ bi thông minh cùng nhan sắc mỹ lệ đã dùng tài năng hỗ trợ Đại Thanh để lại những thành tựu to lớn cho triều đại suốt 260 năm thống trị.Bà qua đời lúc 75 tuổi. Nhất đại hoàng hậu Đại Ngọc Nhi tuy lấy đề tài cũ nhưng với Phan Nghinh Tử - thiếu nữ Đại Ngọc Nhi xinh đẹp dù đã 47 tuổi,Nhĩ Đông Thăng hào hoa và Lưu Thanh Vân âm mưu xảo quyệt tạo nên sức hút của bộ phim kinh điển này...</em></p>', 'Hoàn Tất (54/54)', 54, 'series', 'completed', 20, 1992, 'Lồng Tiếng', 'HD', 'Đài Loan', 0, '[{"name":"Phan Nghinh Tử","avatar":""},{"name":"Quý Cần","avatar":""},{"name":"Cao Vẫn","avatar":""},{"name":"Lưu Thanh Vân","avatar":""},{"name":"Nhĩ Đông Thăng","avatar":""},{"name":"Tôn Bằng","avatar":""},{"name":"Ngô Tuyết Phân","avatar":""},{"name":"Bảo Chính Phương","avatar":""},{"name":"Vu Chỉ Úy","avatar":""},{"name":"Khương Quan Quần","avatar":""},{"name":"Uông Cường","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324542);
