INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-quy-ho-ly-tinh', 'Nhân Quỷ Hồ Ly Tinh', 'The Man, The Ghost And The Fox', 'https://phimimg.com/upload/vod/20240616-1/c6014c38196d38dd50a6a06a300da7d9.jpg', 'https://phimimg.com/upload/vod/20240616-1/282dc3b6520cc638d98b26166f3ff694.jpg', '<p><em>Yến Thái Thần trong lúc đối phó với Linh Sơn Hồ Ly đã quen biết với Lãnh Thu Luyện của Thiên Dao Cung. Thu Luyện vốn là gái giả trai, quấn quýt bên Thái Thần lâu ngày phát sinh tình cảm nhưng không thể tỏ bày. Hồ yêu sai Hồ Tương Tương hành thích Thái Thần, nào ngờ Tương và Thần lại đem lòng yêu nhau... Sát thủ Thạch Tam Lam bị thủ lãnh quỷ đao cửu u đuổi giết vì có tướng mạo giống sư đệ của Thái Thần là Lăng Thiên Vũ. Tam Lang vì tránh sự truy sát mới giả dạng Thiên Vũ nào ngờ Thiên Vũ lại là kẻ sát hại sư mẫu phản bội sư môn...</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 1992, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Đại Dung","avatar":""},{"name":"Chung Thục Tuệ","avatar":""},{"name":"Ngô Vịnh Hồng","avatar":""},{"name":"Âu Thoại Vỹ","avatar":""},{"name":"Thôi Gia Bảo","avatar":""},{"name":"Trần An Doanh","avatar":""},{"name":"Lạc Ứng Quân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
