INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhan-quy-ho-ly-tinh', 'Nhân Quỷ Hồ Ly Tinh', 'The Man, The Ghost And The Fox', 'nhân quỷ hồ ly tinh the man, the ghost and the fox ngô đại dung chung thục tuệ ngô vịnh hồng âu thoại vỹ thôi gia bảo trần an doanh lạc ứng quân ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-den-nhi-do-2-thien-ha-vo-dich', 'Nhất Đen Nhì Đỏ 2 - Thiên Hạ Vô Địch', 'Who''s The Winner 2', 'https://phimimg.com/upload/vod/20240609-1/d0b0b0e599c8d7beee8d284aaabb415d.jpg', 'https://phimimg.com/upload/vod/20240609-1/66c74b11f89c646bbad86012bd1536b2.jpg', '<p><em>Bộ phim Nhất Đen Nhì Đỏ đã đạt kỷ lục doanh thu trên thị trường hải ngoại như: Hồng Kông, Đài Loan, Mã Lai Á, Mỹ và Canada, đài truyền hình Á Thị (ATV), vì muốn thỏa mãn sự yêu cầu của khán giả ở khắp nơi, nên qua tiếp phần kế là Nhất Đen Nhì Đỏ Tập 2″ tức là Thiên Hạ Vô Địch, bộ phim này thực sự lên tới đỉnh cao về action và bài bạc, làm nổi bật ân oán tình thù. Suốt bộ phim là những màn đấu bài long trời lở đất giữa những cao thủ. Phim được thu hình tại sòng bài lớn nhất tại Mã Lai Á, cộng thêm 3 phim trường được trang hoàng thật sang trọng, lộng lẫy, thêm vào đàn nghệ sĩ cột trụ của Hồng Kông như: Trần Đình Oai, Tăng Hoa Thiên va Lử Tụng Hiền. v.v…</em></p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 14, 1992, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Trần Đình Oai","avatar":""},{"name":"Tăng Hoa Thiên","avatar":""},{"name":"Lữ Tụng Hiền","avatar":""},{"name":"Cao Hùng","avatar":""},{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Thang Trấn Nghiệp","avatar":""},{"name":"Vạn Ỷ Văn","avatar":""},{"name":"Ngũ Vịnh Vy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324542);
