INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-sieu-nguoi-may-so-13', 'Bảy Viên Ngọc Rồng: Siêu Người Máy Số 13', 'Dragon Ball Z: Super Android 13!', 'https://phimimg.com/upload/vod/20231023-1/ca811f1a80e0784ed5e2f15e9a4692ea.jpg', 'https://phimimg.com/upload/vod/20231023-1/be335c2027a7d03ef7c1f5a08edabf15.jpg', '<p>Tên bác học điên Kore đã chế tạo ra người máy Android 16 (King kông), Android 17(Pic) và Android 18 (Poc) nhằm phục vụ âm mưu của mình và hắn đã bị chính các “đứa con” của mình giết chết tại phòng thí nghiệm. Tuy Kore đã chết nhưng công trình nghiên cứu của hắn vẫn còn đó gây hiểm họa cho Trái đất.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 1992, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masako Nozawa","avatar":""},{"name":"Ryou Horikawa","avatar":""},{"name":"Takeshi Kusao","avatar":""},{"name":"Toshio Furukawa","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Kōhei Miyauchi","avatar":""},{"name":"Kazuyuki Sogabe","avatar":""},{"name":"Hisao Egawa","avatar":""},{"name":"Toshio Kobayashi","avatar":""},{"name":"Koji Yada","avatar":""},{"name":"Naoko Watanabe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324542);
