INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-sat-nhan', 'Cậu Bé Sát Nhân', 'Mikey', 'https://phimimg.com/upload/vod/20240205-1/bfc933b31324c7315d69fa4aeb79f145.jpg', 'https://phimimg.com/upload/vod/20240205-1/9ddc08f5d736b0306f7aa6ec2c423091.jpg', '<p>Mikey chỉ cần một ngôi nhà ổn định tốt. Anh ấy đã chuyển từ nhà nuôi dưỡng sang nhà nuôi dưỡng cả đời. Cuối cùng anh ấy cũng đến được với một gia đình yêu thương mới, nhưng đứa con nhỏ hoàn hảo của họ không giống như vẻ ngoài của anh ấy. Những người chăm sóc trước đây của anh ấy đều chết vì những tai nạn bí ẩn hoàn toàn không phải là tai nạn. Mikey là một kẻ giết người máu lạnh, và không mất nhiều thời gian để anh ta nhắm vào gia đình mới nhận nuôi của mình và bất kỳ ai khác cản đường anh ta.</p>', 'Full', 1, 'single', 'completed', 14, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brian Bonsall","avatar":""},{"name":"Josie Bissett","avatar":""},{"name":"Ashley Laurence","avatar":""},{"name":"Mimi Craven","avatar":""},{"name":"Whit Hertford","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324542);
