INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong-92-long-hanh-thien-ha', 'Hoàng Phi Hồng 92: Lộng Hành Thiên Hạ', 'The Master', 'null', 'https://phimimg.com/upload/vod/20240205-1/8521affd222d65dd7c09c60a25b3d123.jpg', '<p>Trong quá trình đi tìm sư phụ đang bôn ba nơi đất Mỹ mở võ quán Bảo Chi Lâm của mình, A Kiệt bị cuốn vào cuộc tranh giành giữa các bang phái giang hồ ở Mỹ. Để giải cứu sư phụ, A Kiệt đã dùng toàn bộ sức lực và tiềm năng của mình, dùng võ thuật và y học Trung Hoa chinh phục đối thủ, cũng đồng thời chiếm được trái tim của một cô gái Hoa kiều xinh xắn. Nhưng do A Kiệt không hiểu ngôn ngữ, lề thói của nơi bản địa nên cũng đã gây ra rất nhiều chuyện cười ra nước mắt...</p>', 'Full', 1, 'single', 'completed', 12, 1992, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jet Li","avatar":""},{"name":"Wah Yuen","avatar":""},{"name":"Crystal Kwok","avatar":""},{"name":"杰瑞·特林伯","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324542);
