INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-dang-tu-hai', 'Long Đằng Tứ Hải', 'Gun N'' Rose', 'https://phimimg.com/upload/vod/20240128-1/615c820f6afc4e4c6b348768dd9ae865.jpg', 'https://phimimg.com/upload/vod/20240128-1/d5178a0bd7ea0d572839a1ce19596f06.jpg', '<p>Phim kể về vùng đông bắc Trung Quốc thời kỳ bị Nhật đô hộ, đã lập nên nước Mãn Châu, trong vùng có 1 anh chàng du thủ du thực tên Tiểu Đông Bắc, hàng ngày hành nghề trộm cắp kiếm ăn, những tưởng sẽ sống thế cả đời, nhưng không ngờ anh chàng lại dính vào cuộc đấu tranh của hội cứu quốc và quân Nhật, hội cứu quốc muốn cướp 8 tấn vàng của quân Nhật dùng để mua vũ khí và Tiểu Đông Bắc vô tình biết được bí mật này, liệu rồi vàng sẽ về tay ai...</p>', 'Full', 1, 'single', 'completed', 13, 1992, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Leon Lai","avatar":""},{"name":"Alan Tang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324542);
