INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-cua-vua-he', 'Cuộc Đời Của Vua Hề', 'Chaplin', 'https://phimimg.com/upload/vod/20240126-1/ca86d947a1fa2c14f2d3a2dbe623a1d9.jpg', 'https://phimimg.com/upload/vod/20240126-1/6aaffadb8f5d190c3798de2f0047047e.jpg', '<p>Bộ phim đem đến cho người xem một góc nhìn toàn cảnh hơn về cuộc đời của vua hề Sác-lô, người đã gắn bó cả đời với hình tượng The little tramp để mang tới tiếng cười sảng khoái mà cũng đầy trăn trở cho khán giả. Đằng sau thành công, vinh quang tột đỉnh của một người được tôn là vua hài, còn đó những khoảng lặng trong cuộc đời và tình yêu của Charlie Chaplin...</p>', 'Full', 1, 'single', 'completed', 13, 1992, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Robert Downey Jr.","avatar":""},{"name":"Geraldine Chaplin","avatar":""},{"name":"Paul Rhys","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
