INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-cong-ly', 'Sứ Mệnh Công Lý', 'Mission Of Justice', 'https://phimimg.com/upload/vod/20240126-1/5b095e5aff4bff687b3f6ff94b152795.jpg', 'https://phimimg.com/upload/vod/20240126-1/a7dea0f5db6ce0560c256e37930cf5c7.jpg', '<p>Sứ Mệnh Công Lý - Mission Of Justice kể về Moon và Bullet - hai điệp viên làm việc cho Liên đoàn Chống tội phạm do Đại tá Carry dẫn đầu. Moon và Bullet được gửi đến để theo dõi một phụ nữ tên là Yie Feng, người điều hành một đường dây chuyên bán hàng trắng, hàng giả và hoạt động xã hội đen bất hợp pháp. Trận chiến chống ma túy ngày càng trở nên khốc liệt khi người hỗ trợ cho Moon và Bullet bị giết.</p>', 'Full', 1, 'single', 'completed', 12, 1992, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Gia Lệ","avatar":""},{"name":"Gary Daniels","avatar":""},{"name":"Lý Thái Phụng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324542);
