INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-the-xac', 'Bằng Chứng Thể Xác', 'Body Of Evidence', 'https://phimimg.com/upload/vod/20240123-1/9b8d24aa616e4909b986d589daad4230.jpg', 'https://phimimg.com/upload/vod/20240123-1/160a2e16648bd5ba9853c4481f254bf3.jpg', '<p>Khi một triệu phú lớn tuổi được tìm thấy đã chết với cocaine trong người, di chúc của ông ta để lại 8 triệu đô la cho Rebecca Carlson, người đã ngoại tình với ông ta. Luật sư quận Robert Garrett quyết định truy tố Rebecca, lập luận rằng cô ấy cố tình quan hệ tình dục hoang dã với ông già để kích thích ông ta quá mức và dẫn đến cái chết sớm của ông ta. Luật sư bào chữa Frank Dulaney bào chữa cho Rebecca trước tòa khi bị cuốn vào một mối tình nguy hiểm với cô.</p>', 'Full', 1, 'single', 'completed', 15, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Madonna","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Julianne Moore","avatar":""},{"name":"Anne Archer","avatar":""},{"name":"Jürgen Prochnow","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324542);
