INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-bien-phu', 'Điện Biên Phủ', 'Điện Biên Phủ', 'https://phimimg.com/upload/vod/20240121-1/4ac14181351dd2f03b58d5b7291655d8.jpg', 'https://phimimg.com/upload/vod/20240121-1/e551a3928d4e18c77f2ae5eb09ef2660.jpg', '<p>Điện Biên Phủ (tiếng Pháp: Diên Biên Phu), là bộ phim được viết kịch bản và đạo diễn bởi cựu chiến binh Pháp Pierre Schoendoerffer. Phim miêu tả cuộc vây hãm 55 ngày Điện Biên Phủ (1954), trận chiến cuối cùng của quân đội thuộc địa Liên hiệp Pháp trong cuộc chiến tranh Đông Dương lần thứ nhất, và trong những ngày cuối cùng ở Đông Dương thuộc Pháp. Phim được đề cử giải César hạng mục Âm nhạc hay nhất năm 1993.</p>', 'Full', 1, 'single', 'completed', 12, 1992, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Donald Pleasence","avatar":""},{"name":"Patrick Catalifo","avatar":""},{"name":"Jean-François Balmer","avatar":""},{"name":"Ludmila Mikaël","avatar":""},{"name":"François Négret","avatar":""},{"name":"Maxime Leroux","avatar":""},{"name":"Raoul Billerey","avatar":""},{"name":"Anh The","avatar":""},{"name":"Christopher Buchholz","avatar":""},{"name":"Patrick Chauvel","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324542);
