INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-long-hoi', 'Song Long Hội', 'Twin Dragons', 'https://phimimg.com/upload/vod/20240104-1/2c2172459cc59afc01faf0670af9caaf.jpg', 'https://phimimg.com/upload/vod/20240104-1/15c8fb2e55ecc8cdc5a8c3aaaaf864fa.jpg', '<p>Sinh ra cùng một mẹ, cùng một ngày, cùng một tháng, cùng một năm, nhưng số phận của hai con người ấy lại khác nhau hoàn toàn chỉ sau khi chào đời có vài giờ ngắn ngủi! Bác Mệnh, tự cho mình là đứa trẻ xấu số nhất trên thế gian này, mẹ làm vũ nữ, và nó cũng chẳng biết bố mình là ai. Bác Mệnh sinh sống và trưởng thành trong những khu nhà ổ chuột của Hồng Kông, một mình tự bươn chải kiếm sống bằng đủ thứ nghề. Nhưng Bác Mệnh không biết rằng, trong lúc anh đang từng ngày từng giờ vật lộn, bon chen với cuộc sống thì phía bên kia trời Tây xa xôi, người anh ruột của anh, Mã Hữu đang ung dung bước trên con đường vinh quang của mình.</p>', 'Full', 1, 'single', 'completed', 13, 1992, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Thành Long","avatar":""},{"name":"Trương Khả Di","avatar":""},{"name":"Teddy Robin Kwan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324542);
