INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-yeu-thu', 'Thành Phố Yêu Thú', 'Wicked City', 'https://phimimg.com/upload/vod/20240103-1/adddd8e634632779d7a383819cdd9836.jpg', 'https://phimimg.com/upload/vod/20240103-1/53cfcdb0b7646b27e5c48a23292f3038.jpg', '<p>Phim Thành Phố Yêu Thú (The Wicked City) mở ra khi màn đêm buông xuống đất của mặt trời mọc, và siêu sao Jacky Cheung đang đưa một người phụ nữ lên lầu. Tuy nhiên, mọi việc dường như không có vẻ như người phụ nữ nhanh chóng biến thành sinh vật nhện với chân dài và các đòn cọ dài, nhưng Cheung đã sẵn sàng chiến đấu… Phim Thành phố yêu thú có sự tham gia của Lê Minh, Lý Gia Hân, Trương Học Hữu...</p>', 'Full', 1, 'single', 'completed', 16, 1992, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Lê Minh","avatar":""},{"name":"Lý Gia Hân","avatar":""},{"name":"Trương Học Hữu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
