INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-nguy-hiem', 'Người Tình Nguy Hiểm', 'Wei Xian Qing Ren', 'null', 'https://phimimg.com/upload/vod/20240102-1/9b2fc3d412f5259a989825467ee6b040.jpg', '<p>Hán, Hi, Quan và Bonnie is bốn tên cướp ngân hàng. Chúng tôi đã cướp một chiếc xe ô tô tiền tệ, Hán và Hi chặn cảnh truy đuổi. Quan và Bonnie chấm phá cảnh Gia Huy trong quá trình chạy. Quan vô tình thả xe và bị Gia Huy bắt. Biết đồng bọn sa lưới, kẻ máu lạnh vào cảnh sát và bắn chết Quân để dùng thuốc. Làm quan trọng tiết kiệm, cảnh sát chuyển đổi Gia Huy và nữ cảnh sát San trọng án để hỗ trợ điều tra. Hai người hợp tác cùng hai thanh tra oan gia đối đầu Lưu và Hợp tác mã, bắt tay từ nhân viên áp giải, lần theo manh mối đến một quán karaoke. Gia Huy và Mẫn, nữ ca sinh chân tình rơi vào lưới tình. Không lâu sau, anh biết thêm manh mối về tên cướp xe chủ tiền từ Mẫn…</p>', 'Full', 1, 'single', 'completed', 12, 1992, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Sing Sing (昵称) / Fu Shing Kwok (本名)","avatar":""},{"name":"Ching Wan Lau","avatar":""},{"name":"Fanny Yuen","avatar":""},{"name":"Bryan Leung","avatar":""},{"name":"Elvis Tsui","avatar":""},{"name":"Kingdom Yuen","avatar":""},{"name":"TIMOTHY","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324542);
