INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-khach-so-57', 'Hành Khách Số 57', 'Passenger 57', 'https://phimimg.com/upload/vod/20240102-1/2e7c68c4fbe4d074d5679819809c7f0b.jpg', 'https://phimimg.com/upload/vod/20240102-1/5ba47c174c0d9cbed5ea6835ffa99a2a.jpg', '<p>Một tên khủng bố khét tiếng đã trốn tránh bị bắt trong một thời gian dài bằng cách cực kỳ thông minh và tàn nhẫn. Mọi chuyện trở nên thú vị khi anh ta cướp một chiếc máy bay chở chuyên gia an ninh nổi tiếng John Cutter, người sẽ không ủng hộ những việc như thế này.</p>', 'Full', 1, 'single', 'completed', 14, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wesley Snipes","avatar":""},{"name":"Bruce Payne","avatar":""},{"name":"Tom Sizemore","avatar":""},{"name":"Alex Datcher","avatar":""},{"name":"Bruce Greenwood","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324542);
