INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aladdin-va-cay-den-than', 'Aladdin Và Cây Đèn Thần', 'Aladdin', 'https://phimimg.com/upload/vod/20231215-1/c35eaf541b343f1a7ab85ab1799da7d0.jpg', 'https://phimimg.com/upload/vod/20231215-1/5997c09cfe4a046156d5e136d7ead587.jpg', '<p>Aladdin và cây đèn thần (tiếng Anh: Aladdin) là bộ phim hoạt hình kể về một chàng trai trẻ vô tình có được cây đèn thần kỳ diệu. Nhờ có vị thần đèn vui tính, Aladdin và cây đèn thần mồ côi lang thang có tất cả nhưng gì anh mơ ước như của cải và cô công chúa xinh đẹp.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Scott Weinger","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"Linda Larkin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324542);
