INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-yeu-anh-da-phong-to-cac-con', 'Em Yêu, Anh Đã Phóng To Các Con', 'Honey, I Blew Up The Kid', 'https://phimimg.com/upload/vod/20231213-1/78ee5c17854fb95ed196dc021d74b2c8.jpg', 'https://phimimg.com/upload/vod/20231213-1/096d239e755a0101e2a2b6d4c658c8c7.jpg', '<p>Sau khi vô tình thu nhỏ mấy đứa trẻ thì giờ đây Wayne Szalinski tìm cách phóng to... công trình nghiên cứu này được cả một đoàn thể các nhà khoa học cùng tham gia nhưng vẫn không thành công.Trong một lần cùng với Nick và Adam, con út của Wayne, ghé qua công ty Wayne đã mượn con thú nhồi bông của Adam làm thí nghiệm. Lúc đó cả Nick và Wayne đều chăm chú khởi động máy quên không đế ý tới Adam... thằng nhóc tinh nghịch đi lại gần chỗ con thỏ và vô tình bị trúng phải tia laser nhưng Wayne và Nick không phát hiện ra...</p>', 'Full', 1, 'single', 'completed', 13, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rick Moranis","avatar":""},{"name":"Marcia Strassman","avatar":""},{"name":"Robert Oliveri","avatar":""},{"name":"Daniel Shalikar","avatar":""},{"name":"Joshua Shalikar","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324542);
