INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-tai', 'Gia Tài', 'Howards End', 'https://phimimg.com/upload/vod/20240104-1/e501ac1f6e4b75dceb99d8fc5a53c225.jpg', 'https://phimimg.com/upload/vod/20240104-1/625f5aa3c4920afa0a7e093b43fc0586.jpg', '<p>Bộ phim mô tả chi tiết về xã hội Anh đậm dấu ấn giai cấp hồi đầu thế kỷ 20.Trung tâm của bộ phim là Margaret Schlegel (Emma Thompson), người vừa được thừa kế một phần gia sản từ goá phụ thượng lưu Ruth Wiulcox (Vanessa Redgrave). Những nhân vật chính bị chia rẽ bởi giai cấp gồm quý tộc Henry Wilcox (Anthony Hopkins), trung lưu Margaret và người chị em Helen (Helena Bonham Carter) cùng anh thủ thư giới công nhân Leonard Bast (Sam West) và vợ (Nicola Duffett).</p>', 'Full', 1, 'single', 'completed', 13, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Emma Thompson","avatar":""},{"name":"Helena Bonham Carter","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Samuel West","avatar":""},{"name":"Vanessa Redgrave","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324543);
