INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-trai-tim-mua-dong', 'Một Trái Tim Mùa Đông', 'A Heart In Winter', 'https://phimimg.com/upload/vod/20231211-1/baffe932be53fcf5919afc41bada2c76.jpg', 'https://phimimg.com/upload/vod/20231211-1/fccdff333c912cfd7e9905a0250c0cf9.jpg', '<p>Nghệ sĩ vĩ cầm xinh đẹp Camille có hai nỗi ám ảnh: âm nhạc của Ravel và một người bạn của chồng cô, người chế tạo đàn vĩ cầm. Nhưng trái tim anh dường như lạnh giá khi cô đang chơi đùa say đắm.</p>', 'Full', 1, 'single', 'completed', 14, 1992, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Daniel Auteuil","avatar":""},{"name":"Emmanuelle Béart","avatar":""},{"name":"André Dussollier","avatar":""},{"name":"Élisabeth Bourgine","avatar":""},{"name":"Brigitte Catillon","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324543);
