INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-gia-uy-long', 'Chân Giả Uy Long', 'Gameboy Kids', 'https://phimimg.com/upload/vod/20231205-1/3ec8576dc1e2587670f2a92fc2e2e9d9.jpg', 'https://phimimg.com/upload/vod/20231205-1/3d672b579a5f57917f14358955e1c638.jpg', '<p>Nội dung của phim Chân giả Uy Long xoay quanh anh chàng Wong Kau-Tai (Lưu Đức Hoa), là người kế nhiệm của một tay trùm xã hội đen bởi vì cậu ta có gương mặt giống y hệt y. Khi mà ông chủ của họ đang gặp các vấn đề liên quan đến sự trả thù của các băng nhóm, có thể bị ám sát bất cứ lúc nào nên chúng đã dùng Wong để làm người thay thế, mục đích là bảo toàn tính mạng cho ông trùm.Là một người có IQ cao, Wong trở thành một tay “giang hồ rởm” bất đắc dĩ, anh bắt đầu có những chính sách làm ăn khác người, khiến mọi thứ bắt đầu đảo lộn đến dở khóc dở cười, thế nhưng quan trọng là anh ta góp phần quan trọng trong việc giúp băng nhóm ngày càng mạnh hơn theo chiều hướng làm ăn lương thiện. Anh đã làm cho xã hội đen một điều không tưởng.</p>', 'Full', 1, 'single', 'completed', 15, 1992, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lawrence Cheng","avatar":""},{"name":"Lưu Đức Hoa","avatar":""},{"name":"Mark King","avatar":""},{"name":"Quách Phú Thành","avatar":""},{"name":"Quan Chi Lâm","avatar":""},{"name":"Spencer Lam","avatar":""},{"name":"...","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324543);
