INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-chuot-va-nguoi', 'Của Chuột Và Người', 'Of Mice and Men', 'https://phimimg.com/upload/vod/20231205-1/a3bd832c067c961e9aaf3505ecaaeaf8.jpg', 'https://phimimg.com/upload/vod/20231205-1/f8da4cfbbfad1c2bcb9d45f3b898ad7d.jpg', '<p>Dựa theo tiểu thuyết của John Steinbeck, câu chuyện về hai người bạn đồng hành George và Lennie lang thang khắp vùng đồng quê nước Mỹ trong thời kỳ Đại suy thoái để thực hiện mơ ước có một cuộc sống tốt đẹp hơn…</p>', 'Full', 1, 'single', 'completed', 15, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Malkovich","avatar":""},{"name":"Gary Sinise","avatar":""},{"name":"Ray Walston","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324543);
