INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cua-chuot-va-nguoi', 'Của Chuột Và Người', 'Of Mice and Men', 'của chuột và người of mice and men john malkovich gary sinise ray walston ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-nuoc-mat', 'Trò Chơi Nước Mắt', 'The Crying Game', 'https://phimimg.com/upload/vod/20231204-1/8c1d40ccb8a9215256d4f4a956fcc846.jpg', 'https://phimimg.com/upload/vod/20231204-1/861d89cd7d9a5b4f50f66a825584da34.jpg', '<p>Phim Trò Chơi Nước Mắt - The Crying Game 1992 với chủ đề cuộc xung đột vũ trang ở Ailen. Mở đầu phim hồi hộp với những tình tiết chính trị, chiến tranh giữa Quân Anh và Quân đội Cộng hòa Ireland (IRA). Trước ngưỡng cửa cái chết, chàng lính da màu Jody vẫn thể hiện được sự hài hước vốn có và kết thân với chính kẻ đang giam cầm mình. Hai người lính trẻ thuộc hai phe đối đầu nhau trên mặt trận sinh tử nay lại có cơ hội ngồi đối diện nhau cả ngày lẫn đêm để kể về chuyện đời, từ ấu thơ dữ dội đến tình yêu thầm kín. Jody tin một người đàn ông tuyệt vời như Fergus có thể thay mình mang lại hạnh phúc cho cô người yêu ở đâu tận London xa xôi, để rồi chàng trai Fergie mang một trọng trách lớn khi quyết định thay người bạn–đã–có-thể-thân của mình gửi lời yêu mãi mãi cho cô nàng tên Dil xinh đẹp mà Jody đã hoài nhớ mong, từ dáng vóc đến nụ cười kể cả khi cận kề cái chết. Tuy nhiên Dil vẫn còn một bí mật mà cô dùng mọi cách ẩn giấu....</p>', 'Full', 1, 'single', 'completed', 13, 1992, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Stephen Rea","avatar":""},{"name":"Miranda Richardson","avatar":""},{"name":"Jaye Davidson","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Adrian Dunbar","avatar":""},{"name":"Breffni McKenna","avatar":""},{"name":"Joe Savino","avatar":""},{"name":"Birdy Sweeney","avatar":""},{"name":"Andrée Bernard","avatar":""},{"name":"Jim Broadbent","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chi