INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-z-nguoi-may-so-13', 'Bảy Viên Ngọc Rồng Z: Người Máy Số 13', 'Dragon Ball Z: Super Android 13!', 'https://phimimg.com/upload/vod/20231203-1/561c71ccba578bcccc48d39895f46c7e.jpg', 'https://phimimg.com/upload/vod/20231203-1/6e93df212aa671324df7978766d62ade.jpg', '<p>Tên bác học điên Kore đã chế tạo ra người máy Android 16 (King kông), Android 17 (Pic) và Android 18 (Poc) nhằm phục vụ âm mưu của mình và hắn đã bị chính các “đứa con” của mình giết chết tại phòng thí nghiệm. Tuy Kore đã chết nhưng công trình nghiên cứu của hắn vẫn còn đó gây hiểm họa cho Trái đất.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 1992, 'Thuyết Minh', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324543);
