INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-hiep', 'Thánh Hiệp', 'The Sting', 'https://phimimg.com/upload/vod/20231205-1/571fdbcba4f0c498019530e64cca3490.jpg', 'https://phimimg.com/upload/vod/20231205-1/5001bcd715987d986b6aa68707a56fc4.jpg', '<p>Lưu Đức Hoa trong vai một thám tử tư liêm chính, người làm việc miễn phí đến nay đã 3 năm 8 tháng dựa vào lời dạy của người thầy. Hai ngày nữa hết hạn lời hứa thì phụ tá Joe của anh nhận một vụ án với số tiền bị mất là 1 triệu dollar HongKong. Ngay ngày hôm sau, người khách bí ẩn chết bất đắc kì tử, khiến anh phải truy tìm người vợ của anh này để liên lạc. BỖng dưng số tiền đó lại là tiền của xã hội đen và nó không phải là 1 triệu, mà là 10 triệu.</p>', 'Full', 1, 'single', 'completed', 18, 1992, 'Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Simon Lui","avatar":""},{"name":"Quan Chi Lâm","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324543);
