INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-vu-tru', 'Chiến Binh Vũ Trụ', 'Universal Soldier', 'https://phimimg.com/upload/vod/20231130-1/f1b2766e4479ee7f458939611940383b.jpg', 'https://phimimg.com/upload/vod/20231130-1/06672e10839d5cc335268e92be32a829.jpg', '<p>Van Damme trong vai Luc Devreaux, còn Lundgren trong vai trung sĩ Sndrew Scoot, 2 chiến binh này đã giết chết lẫn nhau trong cuộc chiến và được làm sống dậy 25 năm sau trong 1 chương trình tuyệt mật của chính phủ. Với tên gọi &quot;chiến binh vũ trụ&quot; họ là những cỗ máy giết người không ngừng nghỉ với hệ gen đã được hoàn thiện không có ký ức và chỉ biết tuân theo mệnh lệnh. &nbsp;Nhưng trong khi tiến hành 1 chiến dịch chống khủng bố, ký ức của Devreaux chợt quay về và anh ta bỏ trốn nhiệm vụ. Một cuộc săn đổi giữa các siêu nhân diễn ra khi Devreaux muốn quay về nhà trong khi trung sĩ Scoot muốn đòi lại món nợ của kẻ đã giết mình năm xưa... Devreaux gặp lại cha mẹ mình tại quê nhà cũng là lúc Scoot chờ sẵn cho trận thư hùng...</p>', 'Full', 1, 'single', 'completed', 14, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Ally Walker","avatar":""},{"name":"Ed O''Ross","avatar":""},{"name":"Ralf Moeller","avatar":""},{"name":"Jerry Orbach","avatar":""},{"name":"Leon Rippy","avatar":""},{"name":"Tico Wells","avatar":""},{"name":"Robert Trebor","avatar":""},{"name":"Tommy Lister Jr.","avatar":""},{"name":"Simon Rhee","avatar":""},{"name":"Rance Howard","avatar":""},{"name":"Lilyan Chauvin","avatar":""},{"name":"Thomas Rosales Jr.","avatar":""},{"name":"Ned Bellamy","avatar":""},{"name":"George Fisher","avatar":""},{"name":"Duane Davis","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad35638