INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-gio-hu', 'Đồi Gió Hú', 'Emily Bronte''s Wuthering Heights', 'https://phimimg.com/upload/vod/20231211-1/ea5dd35c691fcf526af8c48ac553f1b9.jpg', 'https://phimimg.com/upload/vod/20231211-1/b1b6087cb4bf1b7be5be00b8260800a8.jpg', '<p>Bộ phim chuyển thể từ tiểu thuyết của Emily Brönte kể về mối tình ngang trái của một cặp đôi và mối quan hệ của họ cộng hưởng qua nhiều thế hệ.</p>', 'Full', 1, 'single', 'completed', 15, 1992, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Juliette Binoche","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Janet McTeer","avatar":""},{"name":"Sophie Ward","avatar":""},{"name":"Simon Shepherd","avatar":""},{"name":"Jeremy Northam","avatar":""},{"name":"Jason Riddington","avatar":""},{"name":"Simon Ward","avatar":""},{"name":"Paul Geoffrey","avatar":""},{"name":"Jonathan Firth","avatar":""},{"name":"Dick Sullivan","avatar":""},{"name":"Robert Demeger","avatar":""},{"name":"John Woodvine","avatar":""},{"name":"Jennifer Daniel","avatar":""},{"name":"Janine Wood","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324543);
