INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cool-world', 'Cool World', 'Cool World', 'https://phimimg.com/upload/vod/20231129-1/1ddc728a3962800d5828d5ed1e040382.jpg', 'https://phimimg.com/upload/vod/20231129-1/1ca7f08bca84f14f456b8045501a2760.jpg', '<p>Một tai nạn kỳ lạ đưa Frank Harris đến Cool World, vương quốc của phim hoạt hình. Nhiều năm sau, họa sĩ vẽ tranh biếm họa Jack Deebs, người đang vẽ Cool World, cũng vượt qua. Anh ta để mắt đến người phụ nữ quyến rũ trong phim hoạt hình Holli Will, nhưng cô ấy có kế hoạch của riêng mình để trở thành hiện thực, và Frank phải ngăn chặn cô ấy.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kim Basinger","avatar":""},{"name":"Gabriel Byrne","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Michele Abrams","avatar":""},{"name":"Deirdre O''Connell","avatar":""},{"name":"Janni Brenn","avatar":""},{"name":"William Frankfather","avatar":""},{"name":"Greg Collins","avatar":""},{"name":"Maurice LaMarche","avatar":""},{"name":"Michael David Lally","avatar":""},{"name":"Carrie Hamilton","avatar":""},{"name":"Stephen Worth","avatar":""},{"name":"Murray Podwal","avatar":""},{"name":"Jenine Jennings","avatar":""},{"name":"Joey Camen","avatar":""},{"name":"Paul Ben-Vic","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324543);
