INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-bip-1992', 'Lừa Bịp', 'The Sting', 'https://phimimg.com/upload/vod/20231010-1/fc0357985c6c3406d09d842bc73ddbc7.jpg', 'https://phimimg.com/upload/vod/20231010-1/796b1f028b0fa2888e65a9cf2755d4a5.jpg', '<p>Simon Tam, &quot;The Sting&quot;, đã học được một số kỹ năng truyền thống Trung Quốc từ sư phụ của mình. Để tránh những điều không may, anh đã không nhận bất kỳ công việc kinh doanh nào trong 5 năm. Bây giờ Simon đang được thuê để bảo vệ một kế toán viên Law, nhưng Law lại chết một cách bí ẩn. Di sản trị giá 300 triệu đô la của Law, thu hút sự chú ý của một tổ chức buôn lậu, đã bị mất tích. Điều này dẫn đến một cuộc rượt đuổi lớn trị giá 300 triệu đô la mà Simon tham gia.</p>', 'Full', 1, 'single', 'completed', 15, 1992, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Simon Lui","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Bowie Lam","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Lo Hung","avatar":""},{"name":"Bao Fang","avatar":""},{"name":"Henry Fong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324543);
