INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-duoc-bao-truoc-1992', 'Cái Chết Được Báo Trước', 'Death Becomes Her', 'https://phimimg.com/upload/vod/20231015-1/d918eacfa81a5806ebaa1060f14dbe24.jpg', 'https://phimimg.com/upload/vod/20231015-1/02ec2a9e85f9c33c65701f2457d07f28.jpg', '<p>Madeline đã kết hôn với Ernest, người từng là hôn phu của đối thủ không đội trời chung của Helen.&nbsp; Sau khi hồi phục việc suy sụp tinh thần, Helen thề sẽ giết Madeline và cướp lại Ernest. Thật không may cho tất cả mọi người, sự ra đời của một loại thuốc ma thuật khiến mọi thứ trở nên phức tạp hơn rất nhiều so với một âm mưu giết người đơn thuần.</p>', 'Full', 1, 'single', 'completed', 14, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Goldie Hawn","avatar":""},{"name":"Bruce Willis","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Isabella Rossellini","avatar":""},{"name":"Ian Ogilvy","avatar":""},{"name":"Adam Storke","avatar":""},{"name":"Nancy Fish","avatar":""},{"name":"Alaina Reed Hall","avatar":""},{"name":"Michelle Johnson","avatar":""},{"name":"Mary Ellen Trainor","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324543);
