INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-mohican-cuoi-cung', 'Người Mohican Cuối Cùng', 'The Last of the Mohicans', 'https://phimimg.com/upload/vod/20231129-1/baa7b5255bbaa84ba3055312d5e20db0.jpg', 'https://phimimg.com/upload/vod/20231129-1/9bc7ee659781ffe3f9005a6303f85d8e.jpg', '<p>Tại cuộc chiến thuộc địa Mỹ, giữa cuộc chiến đẫm máu giữa các đồng minh Anh, Pháp và thổ dân Mỹ. Cora Munro con gái của một Đại tá quý tộc người Anh và nhóm của cô bị một nhóm chiến binh Huron bắt giữ. May mắn thay, một nhóm ba người thợ săn Mohican, bao gồm Hawkeye người Mohican đến giải cứu họ. Một mối tình lãng mạn say đắm sớm nở rộ giữa Cora và Hawkeye, nhưng nhiều thế lực đã thử thách tình yêu của họ khi họ tiếp tục hành trình qua biên giới.</p>', 'Full', 1, 'single', 'completed', 14, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Day-Lewis","avatar":""},{"name":"Madeleine Stowe","avatar":""},{"name":"Jodhi May","avatar":""},{"name":"Russell Means","avatar":""},{"name":"Wes Studi","avatar":""},{"name":"Eric Schweig","avatar":""},{"name":"Steven Waddington","avatar":""},{"name":"Maurice Roëves","avatar":""},{"name":"Patrice Chéreau","avatar":""},{"name":"Edward Blatchford","avatar":""},{"name":"Terry Kinney","avatar":""},{"name":"Tracey Ellis","avatar":""},{"name":"Justin M. Rice","avatar":""},{"name":"Dennis Banks","avatar":""},{"name":"Pete Postlethwaite","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"Mac And","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"