INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-ngao-giang-ho-2-dong-phuong-bat-bai', 'Tiếu Ngạo Giang Hồ 2: Đông Phương Bất Bại', 'The Legend of the Swordsman', 'https://phimimg.com/upload/vod/20231124-1/7eb76e4534c06634970a72ae4fd10748.jpg', 'https://phimimg.com/upload/vod/20231124-1/1830f614bd3b1c1e6aee89f164b9fb7e.jpg', '<p>Lấy bối cảnh thời nhà Minh, Tiếu ngạo giang hồ: Đông Phương Bất Bại kể tiếp những cuộc phiêu lưu của Lệnh Hồ Xung cùng cô bạn gái Nhạc Linh San sau khi họ rời khỏi Hoa Sơn vì bị thầy dạy là Nhạc Bất Quần phản bội. Mặc dù Nhạc Linh San đã thầm yêu Lệnh Hồ Xung nhưng Lệnh lại dành tình cảm của anh cho Nhâm Doanh Doanh, người có cha là Nhâm Ngã Hành, giáo chủ Nhật Nguyệt thần giáo trước khi bị Đông Phương Bất Bại lật đổ. Mặc dù là đàn ông nhưng do luyện Quỳ Hoa bảo điển, Đông Phương Bất Bại dần mang tướng mạo của một phụ nữ, trong một lần tình cờ đụng độ, Lệnh Hồ Xung đã tỏ lòng mến mộ Đông Phương Bất Bại và kết bạn với kẻ đại ác này. Nhưng sự thật cuối cùng bị phơi bày và Lệnh Hồ Xung phải gạt tình cảm riêng để tiêu diệt Đông Phương Bất Bại vì sự bình an của thiên hạ.</p>', 'Full', 1, 'single', 'completed', 27, 1992, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Brigitte Lin","avatar":""},{"name":"Jet Li","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Michelle Reis","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Candice Yu","avatar":""},{"name":"Fennie Yuen","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"Yen Shi-Kwan","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Thomas Cheung Kwok-Leung","avatar":""},{"name":"Andrew Kam","avatar":""},{"name":"Sam Ho Choi-Chow","avatar":""},{"name":"Ken Choi Kwok-Ping","avatar":""},{"name":"Wong Wai-Shun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324543);
