INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-cac-so-hanh-dong', 'Khi Các Sơ Hành Động', 'Sister Act', 'https://phimimg.com/upload/vod/20231124-1/c2fdbee7900f234270e2aa769d25ec43.jpg', 'https://phimimg.com/upload/vod/20231124-1/44d2f2400df1adf9cb3eb8f5fdf842fb.jpg', '<p>Một ca sĩ Reno chứng kiến một vụ giết người của đám đông và cảnh sát đã giấu cô ấy trong một nữ tu viện để bảo vệ cô ấy khỏi những kẻ sát nhân của đám đông. Mẹ bề trên không tin tưởng cô ấy, và thực hiện các bước để hạn chế ảnh hưởng của cô ấy đối với các nữ tu khác. Cuối cùng, nữ ca sĩ đã giải cứu được dàn hợp xướng đang thất bại và bắt đầu giúp đỡ các dự án cộng đồng, giúp cô ấy có một cuộc phỏng vấn trên TV — và được đám đông nhận diện.</p>', 'Full', 1, 'single', 'completed', 21, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Whoopi Goldberg","avatar":""},{"name":"Maggie Smith","avatar":""},{"name":"Kathy Najimy","avatar":""},{"name":"Wendy Makkena","avatar":""},{"name":"Mary Wickes","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Bill Nunn","avatar":""},{"name":"Robert Miranda","avatar":""},{"name":"Richard Portnow","avatar":""},{"name":"Ellen Albertini Dow","avatar":""},{"name":"Carmen Zapata","avatar":""},{"name":"Pat Crawford Brown","avatar":""},{"name":"Prudence Wright Holmes","avatar":""},{"name":"Ruth Kobart","avatar":""},{"name":"Susan Browning","avatar":""},{"name":"Edith Diaz","avatar":""},{"name":"Be","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324543);
