INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-cuc-di-kien', 'Thu Cúc Đi Kiện', 'The Story of Qiu Ju', 'https://phimimg.com/upload/vod/20231117-1/44c635a1c9e68847d0e3f3cd32c8de3e.jpg', 'https://phimimg.com/upload/vod/20231117-1/6c011d70ea211a720ae32aeeedf20131.jpg', '<p>Khi chồng cô bị trưởng thôn đá vào háng, Qiu Ju, một phụ nữ nông dân, mặc dù đang mang thai, đã đến một thị trấn gần đó, và sau đó là một thành phố lớn để đối phó với các quan chức của nó và tìm công lý.</p>', 'Full', 1, 'single', 'completed', 26, 1992, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gong Li","avatar":""},{"name":"Liu Peiqi","avatar":""},{"name":"Liuchun Yang","avatar":""},{"name":"Lei Kesheng","avatar":""},{"name":"Ge Zhijun","avatar":""},{"name":"Wanqing Zhu","avatar":""},{"name":"Luowen Cui","avatar":""},{"name":"Huiqin Yang","avatar":""},{"name":"Jianfa Wang","avatar":""},{"name":"Zi Lin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324543);
