INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-long-mon-khach-san', 'Tân Long Môn Khách Sạn', 'New Dragon Gate Inn', 'https://phimimg.com/upload/vod/20231115-1/388421944fdde7c9684dd47d2ffec262.jpg', 'https://phimimg.com/upload/vod/20231115-1/89ee99fe9e7600a62ae76d5896cc0466.jpg', '<p>Thời nhà Minh, Ngụy Trung Hiền là một hoạn quan cuồng quyền lực, người cai trị vùng sa mạc của Trung Quốc như thể ông ta là Hoàng đế, tàn nhẫn ngăn chặn những âm mưu chống lại ông ta và đặt bẫy cho một trong những kẻ thù của ông ta tại khách sạn Long Môn.</p>', 'Full', 1, 'single', 'completed', 16, 1992, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Brigitte Lin","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"Yen Shi-Kwan","avatar":""},{"name":"Lawrence Ng","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"Yuen Bun","avatar":""},{"name":"Yumiko Cheng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324543);
