INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('scent-of-a-woman', 'Scent of a Woman', 'Scent of a Woman', 'https://phimimg.com/upload/vod/20231115-1/52c0ef81c4161c19cf8325b71baf713f.jpg', 'https://phimimg.com/upload/vod/20231115-1/ea525f53618b4da81b94fcad19560946.jpg', '<p>Charlie Simms là một học sinh tại một trường dự bị tư thục, xuất thân từ một gia đình nghèo. Để kiếm tiền cho chuyến bay về nhà tới Gresham, Oregon vào dịp Giáng sinh, Charlie nhận một công việc trong dịp Lễ Tạ ơn, chăm sóc sĩ quan quân đội Hoa Kỳ đã nghỉ hưu, Trung tá Frank Slade, một người đàn ông trung niên vụng về sống cùng cháu gái và gia đình cô.</p>', 'Full', 1, 'single', 'completed', 16, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Chris O''Donnell","avatar":""},{"name":"Al Pacino","avatar":""},{"name":"James Rebhorn","avatar":""},{"name":"Gabrielle Anwar","avatar":""},{"name":"Philip Seymour Hoffman","avatar":""},{"name":"Bradley Whitford","avatar":""},{"name":"Richard Venture","avatar":""},{"name":"June Squibb","avatar":""},{"name":"Frances Conroy","avatar":""},{"name":"Rochelle Oliver","avatar":""},{"name":"Tom Riis Farrell","avatar":""},{"name":"Nicholas Sadler","avatar":""},{"name":"Todd Louiso","avatar":""},{"name":"Gene Canfield","avatar":""},{"name":"Ron Eldard","avatar":""},{"name":"Sally Murp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324543);
