INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuc-han', 'Phục Hận', 'Rapid Fire', 'https://phimimg.com/upload/vod/20231110-1/b08bd16e37ad9dc5d22b401589efe96f.jpg', 'https://phimimg.com/upload/vod/20231110-1/7a399fbf97988e8cff764ea1dd9db49a.jpg', '<p>Sinh viên đại học Jake Lo bị truy đuổi bởi những kẻ buôn lậu, bọn cướp và đặc vụ liên bang quanh co sau khi anh chứng kiến một vụ giết người của trùm Mafia.</p>', 'Full', 1, 'single', 'completed', 19, 1992, 'Vietsub', 'HD', 'Thái Lan', 0, '[{"name":"Brandon Lee","avatar":""},{"name":"Powers Boothe","avatar":""},{"name":"Nick Mancuso","avatar":""},{"name":"Raymond J. Barry","avatar":""},{"name":"Kate Hodge","avatar":""},{"name":"Tzi Ma","avatar":""},{"name":"Tony Longo","avatar":""},{"name":"Michael Paul Chan","avatar":""},{"name":"Dustin Nguyen","avatar":""},{"name":"Brigitta Stenberg","avatar":""},{"name":"Basil Wallace","avatar":""},{"name":"Al Leong","avatar":""},{"name":"François Chau","avatar":""},{"name":"Quentin O''Brien","avatar":""},{"name":"D.J. Howard","avatar":""},{"name":"Maurice Chasse","avatar":""},{"name":"Walter Addison","avatar":""},{"name":"Joh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324543);
