INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-cho-beethoven', 'Chú chó Beethoven', 'Beethoven', 'https://phimimg.com/upload/vod/20231110-1/3870f4b1769a7c6e6e7228ae636b0c14.jpg', 'https://phimimg.com/upload/vod/20231110-1/fc67b28f56db465e35c8880333f3a987.jpg', '<p>Gia đình Newton sống trong ngôi nhà tiện nghi của họ, nhưng dường như vẫn thiếu thứ gì đó. Cái &quot;lỗ&quot; này được lấp đầy bởi một chú chó con nhỏ bước vào nhà và cuộc sống của họ. Beethoven, như tên gọi của ông, lớn lên thành một con chó khổng lồ... một Thánh Bernard. Bác sĩ Varnick, bác sĩ thú y địa phương có một nhiệm vụ bên lề bí mật và khủng khiếp, đòi hỏi rất nhiều chó để làm thí nghiệm. Beethoven nằm trong danh sách bác sĩ tồi.</p>', 'Full', 1, 'single', 'completed', 17, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charles Grodin","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Dean Jones","avatar":""},{"name":"Nicholle Tom","avatar":""},{"name":"Christopher Castile","avatar":""},{"name":"Sarah Rose Karr","avatar":""},{"name":"Chris","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"David Duchovny","avatar":""},{"name":"Patricia Heaton","avatar":""},{"name":"Laurel Cronin","avatar":""},{"name":"O-Lan Jones","avatar":""},{"name":"Nancy Fish","avatar":""},{"name":"Craig Pinkard","avatar":""},{"name":"Robi Davidson","avatar":""},{"name":"Sherri Paysinger","avatar":""},{"name":"Patri","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324543);
