INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-phi-va-a-ky', 'A Phi Và A Kỳ', 'The Days of Being Dumb', 'https://phimimg.com/upload/vod/20231119-1/4419e9c2f47ca026547ce92455a2379d.jpg', 'https://phimimg.com/upload/vod/20231119-1/07242891c0cf6f37a75deb352e3b5e87.jpg', '<p>Một bộ phim hài hước châm biếm xã hội đen của đạo diễn nổi tiếng Hong Kong Kha Thụ Lương, dù tên phim có phần tương đồng nhưng bộ phim này hoàn toàn không liên quan đến bộ phim nổi tiếng khác “Days of Being Wild”. Lương Triều Vỹ và Trương Học Hữu trong vai hai tên gangster có nhiều tham vọng Phi và Kỳ. Họ là những kẻ xui xẻo đến mức mà tất cả những ông trùm trước của họ đều chết ngay trong ngày đầu thuê họ. Các băng đảng đều không muốn dính đến họ, vì vậy Phi và Kỳ quyết định trở thành những tên &quot;dẫn gái&quot;, họ đưa cô gái trẻ tên Jane (vai diễn điện ảnh đầu tiên của Viên Vịnh Nghi) từ Singapore đến để hành nghề. Thật không may, không ai nói cho Jane biết bản chất công việc của mình, và cả Phi và Kỳ đều không đủ sức bắt cô đồng ý làm theo họ. Số phận của Phi và Kỳ thay đổi khi tên trùm xã hội đen tàn bạo nhất Hong Kong, Quan (Thang Trấn Nghiệp) thuê họ với ảo tưởng rằng vận đen của họ có thể có hữu dụng cho hắn. Cuộc sống xa hoa trong thế giới tội phạm của họ không kéo dài, khi Jane – người mà cả hai cùng phải lòng – đột ngột bỏ đi, còn cảnh sát lập ra một cái bẫy bằng cách thuyết phục Quan rằng Phi và Kỳ sẽ tố cáo hắn tại tòa án. Những nỗ lực can đảm nhưng đen đủi tuyệt vọng của Phi và Kỳ nhằm thoát khỏi những tình huống hiểm nghèo hết lần này đến lần khác làm nên yếu tố giải trí cho bộ phim.</p>', 'Full', 1, 'single', 'completed', 14, 1992, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jacky Cheung","avatar":""},{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Anita Yuen","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Jamie Luk Kim-Ming","avatar":""},{"name":"Ben Luk Man-Wah","avatar":""},{"name":"Billy Ching Sau-Yat","avatar":""},{"name":"Wong Ying-Kit","avatar":""},{"name":"Glen Chin","avatar":""},{"name":"Jamie Luk Kim-Ming","avatar":""},{"name":"Leung Kei-Hei","avatar":""},{"name":"Ho Chi-Moon","avatar":""},{"name":"Yeung Wan-King","avatar":""},{"name":"Chan Chi-Fai","avatar":""},{"name":"Four Tse Liu-Shut","avatar":""},{"name":"Lam","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324543);
