INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-uc', 'Oan Ức', 'My Cousin Vinny', 'https://phimimg.com/upload/vod/20231101-1/729eb48fed6e39b9f09cd440d8a881a9.jpg', 'https://phimimg.com/upload/vod/20231101-1/710a71723b9bc059652c68e555aec05f.jpg', '<p>Hai người bạn vô tư đi du lịch qua Alabama bị bắt nhầm và bị buộc tội giết người. May mắn thay, một trong số họ có một người anh họ là luật sư - Vincent Gambini, một cựu thợ sửa ô tô đến từ Brooklyn, người vừa vượt qua kỳ thi luật sư sau lần thử thứ sáu. Khi anh ấy đến cùng bạn gái mặc đồ da của mình, để thử vụ án đầu tiên, đó là một cú sốc thực sự - đối với anh ấy và Deep South!</p>', 'Full', 1, 'single', 'completed', 14, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joe Pesci","avatar":""},{"name":"Ralph Macchio","avatar":""},{"name":"Marisa Tomei","avatar":""},{"name":"Mitchell Whitfield","avatar":""},{"name":"Fred Gwynne","avatar":""},{"name":"Lane Smith","avatar":""},{"name":"Austin Pendleton","avatar":""},{"name":"Bruce McGill","avatar":""},{"name":"Maury Chaykin","avatar":""},{"name":"Paulene Myers","avatar":""},{"name":"Raynor Scheine","avatar":""},{"name":"James Rebhorn","avatar":""},{"name":"Chris Ellis","avatar":""},{"name":"Lou Walker","avatar":""},{"name":"Michael Burgess","avatar":""},{"name":"Michael Simpson","avatar":""},{"name":"Kenny Jones","avatar":""},{"name":"Thoma","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324543);
