INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh', 'Người Tình', 'The Lover', 'https://phimimg.com/upload/vod/20231026-1/8171703183c70a63191a2e5cd7171c1b.jpg', 'https://phimimg.com/upload/vod/20231026-1/cd436bccbb9b740cb6d3eac78a768388.jpg', '<p>Một thiếu nữ nghèo người Pháp tham gia vào một cuộc tình bất chính với một người thừa kế giàu có người Hoa vào những năm 1920 ở Sài Gòn. Lần đầu tiên trong đời cô ấy có quyền kiểm soát, và cô ấy sử dụng nó một cách khéo léo với người tình bị vây hãm của mình trong suốt một loạt các cuộc gặp gỡ bí mật và những cuộc chạm trán khốc liệt.</p>', 'Full', 1, 'single', 'completed', 17, 1992, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jane March","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Frédérique Meininger","avatar":""},{"name":"Arnaud Giovaninetti","avatar":""},{"name":"Melvil Poupaud","avatar":""},{"name":"Lisa Faulkner","avatar":""},{"name":"Jeanne Moreau","avatar":""},{"name":"Xiem Mang","avatar":""},{"name":"Philippe Le Dem","avatar":""},{"name":"Ann Schaufuss","avatar":""},{"name":"Tania Torrens","avatar":""},{"name":"Espérance Pham Thai Lan","avatar":""},{"name":"Hélène Patarot","avatar":""},{"name":"Yvonne Wingerter","avatar":""},{"name":"Raymonde Heudeline","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324543);
