INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-tha-thu', 'Không Tha Thứ', 'Unforgiven', 'https://phimimg.com/upload/vod/20231026-1/42dffd1157900583ec728dec0a1ceee7.jpg', 'https://phimimg.com/upload/vod/20231026-1/ac66a97f670d99d58e67e92d4e5dac0e.jpg', '<p>Big Whisky là một thị trấn kỳ lạ của những năm đầu thế kỷ 19 tại miền Tây nước Mỹ bởi hầu hết mọi người đều muốn sống lặng lẽ. Câu chuyện bắt đầu với hình ảnh một ngôi nhà, một cái cây và một người đàn ông ngồi bên nấm mộ. Mặt trời đang chiếu qua khung cửa của những ngôi nhà quanh đó, ở đấy mỗi người có một cuộc đời khác nhau trong sự yên bình chung của cả thị trấn. William Munny là một cư dân của thị trấn Big Whisky. Ông vốn là một sát thủ khét tiếng quyết rũ bỏ giang hồ để về hưởng cuộc sống bình thường bên cạnh con. Vợ ông, bà Claudia ra đi để lại cho ông một ngôi nhà sơ sài và hai cậu con trai nhỏ. Cuộc sống trở nên khó khăn khi William không đủ tiền trang trải sinh hoạt hằng ngày của ba bố con. Một hôm, có một người đàn ông tên Schofield Kid đến tìm William Munny vì nghe nói ông là một người lạnh lùng băng giá và không có dây thần kinh sợ hãi. William đã nhẹ nhàng nói rằng: “Tôi không còn là con người đó nữa Kid ạ. Chính vợ tôi đã đưa tôi ra khỏi những cơn nghiện ngập và tội lỗi”.</p>', 'Full', 1, 'single', 'completed', 21, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clint Eastwood","avatar":""},{"name":"Gene Hackman","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Jaimz Woolvett","avatar":""},{"name":"Richard Harris","avatar":""},{"name":"Anna Levine Thomson","avatar":""},{"name":"Frances Fisher","avatar":""},{"name":"Saul Rubinek","avatar":""},{"name":"David Mucci","avatar":""},{"name":"Rob Campbell","avatar":""},{"name":"Anthony James","avatar":""},{"name":"Ron White","avatar":""},{"name":"Jefferson Mappin","avatar":""},{"name":"Jeremy Ratchford","avatar":""},{"name":"Philip Maurice Hayes","avatar":""},{"name":"Tara Frederick","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324543);
