INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuan-trang-mat', 'Tuần Trăng Mật', 'Bitter Moon', 'https://phimimg.com/upload/vod/20231030-1/fdccf7fe8b8af3d8333ac046735476a9.jpg', 'https://phimimg.com/upload/vod/20231030-1/eda86b44f09d9245ebccedafca4057a1.jpg', '<p>Một hành khách trên một con tàu du lịch nảy sinh tình cảm say mê không thể cưỡng lại được với người vợ lập dị của một người bị liệt nửa người.</p>', 'Full', 1, 'single', 'completed', 19, 1992, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Peter Coyote","avatar":""},{"name":"Emmanuelle Seigner","avatar":""},{"name":"Hugh Grant","avatar":""},{"name":"Kristin Scott Thomas","avatar":""},{"name":"Victor Banerjee","avatar":""},{"name":"Sophie Patel","avatar":""},{"name":"Patrick Albenque","avatar":""},{"name":"Smilja Mihailovitch","avatar":""},{"name":"Leo Eckmann","avatar":""},{"name":"Luca Vellani","avatar":""},{"name":"Richard Dieux","avatar":""},{"name":"Danny Wuyts","avatar":""},{"name":"Daniel Dhubert","avatar":""},{"name":"Nathalie Galán","avatar":""},{"name":"Eric Gonzales","avatar":""},{"name":"Jim Adhi Limas","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324543);
