INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-khong-gian-3', 'Quái Vật Không Gian 3', 'Alien³', 'https://phimimg.com/upload/vod/20231024-1/d1f9321468547a96c8f88d13b941239f.jpg', 'https://phimimg.com/upload/vod/20231024-1/c3295ea3bb671bf1e6c361fe9c654e02.jpg', '<p>Trốn thoát khỏi hành tinh chết chóc, số phận đã quá khắc nghiệt với Ripley khi bắt cô luôn đơn độc trước hiểm nguy, những người bạn đồng hành lần lượt bỏ xác trong vũ trụ sâu thẳm. Tàu cứu sinh đưa Ripley lạc đến 1 hành tinh hoang vắng, nơi lưu đày tù nhân liên hành tinh. Nhưng sự hiểm nguy luôn rình rập, khi 1 tế bào quái vật ký sinh đã kịp len lỏi vào trong thân tàu cứu sinh kia của Ripley. Một lần nữa, cuộc chiến đấu sinh tồn không khoan nhượng lại bùng nổ nhưng lần này, cái giá phải trả là quá lớn...</p>', 'Full', 1, 'single', 'completed', 16, 1992, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sigourney Weaver","avatar":""},{"name":"Charles S. Dutton","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Lance Henriksen","avatar":""},{"name":"Paul McGann","avatar":""},{"name":"Brian Glover","avatar":""},{"name":"Ralph Brown","avatar":""},{"name":"Danny Webb","avatar":""},{"name":"Christopher John Fields","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Christopher Fairbank","avatar":""},{"name":"Carl Chase","avatar":""},{"name":"Leon Herbert","avatar":""},{"name":"Vincenzo Nicoli","avatar":""},{"name":"Pete Postlethwaite","avatar":""},{"name":"Paul Bre","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324543);
