INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-phan-boi', 'Những Kẻ Phản Bội', 'Reservoir Dogs', 'https://phimimg.com/upload/vod/20231024-1/775dbedb5a771c226f873479b90ec895.jpg', 'https://phimimg.com/upload/vod/20231024-1/350df15736c7f684220403ceed79f532.jpg', '<p>Họ hoàn toàn là những người xa lạ, cùng hợp lại để thực hiện một phi vụ tội ác hoàn hảo. Kế hoạch đơn giản tuyệt hảo chẳng may rơi vào cảnh đẫm máu, và những tên giết người man rợ nhận ra trong số họ có một kẻ là cảnh sát chìm. Nhưng mà là ai? Eservoir Dogs là bộ phim truyện đầu tiên được trình làng do Quentin Tarantino làm đạo diễn kiêm viết kịch bản. Phim kể về những sự việc đã xảy ra trước và sau vụ cướp nữ trang không thành. Dàn diễn viên bao gồm Harvey Keitel, Tim Roth, Michaeal Madsen, Chris Penn, Steve Busceni và Lawrence Tierney, Tarantino cũng góp một vai nhỏ trong phim. Phim kết hợp nhiều bản nhạc và tính thẩm mĩ đã trở thành đặc trưng phong cách phim Tarantino: tội ác, bạo lực, những đoạn hội thoại đáng nhớ với những lời ...</p>', 'Full', 1, 'single', 'completed', 13, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harvey Keitel","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Chris Penn","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Lawrence Tierney","avatar":""},{"name":"Randy Brooks","avatar":""},{"name":"Kirk Baltz","avatar":""},{"name":"Edward Bunker","avatar":""},{"name":"Quentin Tarantino","avatar":""},{"name":"Rich Turner","avatar":""},{"name":"David Steen","avatar":""},{"name":"Tony Cosmo","avatar":""},{"name":"Stevo Polyi","avatar":""},{"name":"Michael Sottile","avatar":""},{"name":"Robert Ruth","avatar":""},{"name":"Lawrence Bender","avatar":""},{"name":"Linda Kaye","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324543);
