INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-tro-lai', 'Người Dơi Trở Lại', 'Batman Returns', 'https://phimimg.com/upload/vod/20231023-1/e177d2e90bbd9f29772fef7eed93a162.jpg', 'https://phimimg.com/upload/vod/20231023-1/f36945e4801833f4e442790bb4d552f6.jpg', '<p>Một ác nhân mang biệt danh Chim cánh cụt xuất hiện đe họa hòa bình của Gotham. Hắn còn được sự hậu thuẫn của tay tài phiệt thối nát Max hòng chiếm chiếc ghế thị trưởng thành phố. Người dơi tái xuất, nhưng trên đường thực thi công lý, anh còn đụng độ Miêu nữ, một phụ nữ bí ẩn như danh tính Người dơi...</p>', 'Full', 1, 'single', 'completed', 16, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Keaton","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"Michael Gough","avatar":""},{"name":"Pat Hingle","avatar":""},{"name":"Michael Murphy","avatar":""},{"name":"Cristi Conaway","avatar":""},{"name":"Andrew Bryniarski","avatar":""},{"name":"Vincent Schiavelli","avatar":""},{"name":"Steve Witting","avatar":""},{"name":"Jan Hooks","avatar":""},{"name":"John Strong","avatar":""},{"name":"Rick Zumwalt","avatar":""},{"name":"Anna Katarina","avatar":""},{"name":"Gregory Scott Cummin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324543);
