INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nang-goc', 'Bản Năng Gốc', 'Basic Instinct', 'https://phimimg.com/upload/vod/20231023-1/c6808494cac8b56f4124193d00dadd87.jpg', 'https://phimimg.com/upload/vod/20231023-1/f3c7df13d8742b9d33c9040604edeccd.jpg', '<p>Nick, một thanh tra hay say rượu đột nhiên bị cuốn vào một vụ án giết người bí hiểm với một nữ nhà văn viết tiểu thuyết về tình dục Catherine Trammell. Cuốn truyện mới nhất của Catherine có nhiều điểm tương đồng kì lạ với vụ án mà Nick đang điều tra. Trong khi quen Catherine các vụ án tương tự liên tiếp xảy ra và luôn có giống như liên quan đến cô ta. Bác sĩ tâm thần và đồng nghiệp rất lo lắng cho tính mạng của Nick vì có thể người tình đồng tính của Catherine có thể ghen tức và giết anh...</p>', 'Full', 1, 'single', 'completed', 20, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Sharon Stone","avatar":""},{"name":"George Dzundza","avatar":""},{"name":"Jeanne Tripplehorn","avatar":""},{"name":"Leilani Sarelle","avatar":""},{"name":"Denis Arndt","avatar":""},{"name":"Bruce A. Young","avatar":""},{"name":"Chelcie Ross","avatar":""},{"name":"Dorothy Malone","avatar":""},{"name":"Wayne Knight","avatar":""},{"name":"Daniel von Bargen","avatar":""},{"name":"Stephen Tobolowsky","avatar":""},{"name":"Benjamin Mouton","avatar":""},{"name":"Jack McGee","avatar":""},{"name":"Bill Cable","avatar":""},{"name":"Stephen Rowe","avatar":""},{"name":"Mitc","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324543);
