INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dracula-ba-tuoc-ma-ca-rong', 'Dracula: Bá tước ma cà rồng', 'Bram Stoker''s Dracula', 'https://phimimg.com/upload/vod/20231022-1/5b134d368a9bbad04ae1a8191d1ab0bf.jpg', 'https://phimimg.com/upload/vod/20231022-1/350caf6adfab49e2ac4fe99d3b32926b.jpg', '<p>Khi Dracula đến Luân Đôn tìm người phụ nữ trông giống người vợ đã qua đời từ lâu, thợ săn ma cà rồng – Giáo sư Van Helsing – quyết chấm dứt cơn cuồng loạn.</p>', 'Full', 1, 'single', 'completed', 13, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gary Oldman","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Keanu Reeves","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Sadie Frost","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Billy Campbell","avatar":""},{"name":"Tom Waits","avatar":""},{"name":"Monica Bellucci","avatar":""},{"name":"Florina Kendrick","avatar":""},{"name":"Michaela Bercu","avatar":""},{"name":"Jay Robinson","avatar":""},{"name":"I.M. Hobson","avatar":""},{"name":"Laurie Franks","avatar":""},{"name":"Maud Winchester","avatar":""},{"name":"Octavian Cadia","avatar":""},{"name":"R","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324543);
