INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong-2-nam-nhi-duong-tu-cuong', 'Hoàng Phi Hồng 2: Nam Nhi Đương Tự Cường', 'Once Upon a Time in China II', 'https://phimimg.com/upload/vod/20231016-1/c63ee1e8953ce375c7c131ce951773a4.jpg', 'https://phimimg.com/upload/vod/20231016-1/8fb5a85cb011f82892fdc9b89a46b05a.jpg', '<p>Vào thời Mãn Thanh, các chính sách mở cửa của triều đình phong kiến được tiến hành một cách hỗn loạn, mối quan hệ chính trị giữa ba nước Anh - Trung - Nhật vẫn còn là một ẩn số khó đoán. Trong khi triều đình chỉ chăm chăm đàm phán, duy trì mối quan hệ hợp tác với người Anh, lúc bấy giờ, Bạch Liên giáo đang hoành hành khắp nơi. Lợi dụng tinh thần yêu nước của những người dân lương thiện, chúng giả thần giả quỷ, lừa gạt không biết bao nhiêu là tiền của của dân lành. Sự an nguy của đồng bào lại đặt vào tay Hoàng sư phụ.</p>', 'Full', 1, 'single', 'completed', 15, 1992, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Max Mok Siu-Chung","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Yen Shi-Kwan","avatar":""},{"name":"Leung Yat-Ho","avatar":""},{"name":"Paul Fonoroff","avatar":""},{"name":"Michael Miller","avatar":""},{"name":"Dion Lam Dik-On","avatar":""},{"name":"Kent Chow Shu-Gei","avatar":""},{"name":"Joseph Chi","avatar":""},{"name":"Zhang Tielin","avatar":""},{"name":"Mike Leeder","avatar":""},{"name":"Chuen Chiang","avatar":""},{"name":"William Ho Ka-Kui","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324543);
