INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-ai-quoc', 'Trò Chơi Ái Quốc', 'Patriot Games', 'https://phimimg.com/upload/vod/20231016-1/0b9ebe258e2528d17ef17f7eff7a4171.jpg', 'https://phimimg.com/upload/vod/20231016-1/8ee98a1c6b3dcb5a511e03b106212cd8.jpg', '<p>Trò Chơi Ái Quốc phim nói về Jack Ryan của CIA đã bị một tổ chức khủng bố âm mưu ám sát vì đã cứu mạng hoàng tử xứ Wales. Cuộc ám sát tuy thất bại nhưng bọn khủng bố còn rất nhiều cơ hội để ám sát Ryan. Liệu anh ta có thoát chết thêm lần nữa không và kết cục thế nào, hãy đón xem phim Trò Chơi Ái Quốc với những pha hành động vô cùng đẹp mắt nhưng cũng không kém phần nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 16, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Anne Archer","avatar":""},{"name":"Thora Birch","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Patrick Bergin","avatar":""},{"name":"Polly Walker","avatar":""},{"name":"James Fox","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"Richard Harris","avatar":""},{"name":"J.E. Freeman","avatar":""},{"name":"Alex Norton","avatar":""},{"name":"Hugh Fraser","avatar":""},{"name":"David Threlfall","avatar":""},{"name":"Alun Armstrong","avatar":""},{"name":"Berlinda Tolbert","avatar":""},{"name":"Gerald Sim","avatar":""},{"name":"Pip To","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324543);
