INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-bong-chay-nu', 'Giải Bóng Chày Nữ', 'A League of Their Own', 'https://phimimg.com/upload/vod/20231016-1/8006590c32c0279fa8d257d1f4bf95e4.jpg', 'https://phimimg.com/upload/vod/20231016-1/0c97f89caf61613899b6e3b8cf59b3ca.jpg', '<p>Thế chiến lần thứ hai bắt đầu. Năm 1943, khi những cầu thủ bóng chày chuyên nghiệp nam đều bị gọi đi lính, một nhóm các cô gái đã dám rời bỏ quê nhà để tham gia Giải bóng chày chuyên nghiệp nữ Mỹ với quyết tâm giữ cho môn thể thao này không bị mai một. Bộ phim chủ yếu xoay quay câu chuyện về hai chị em Dottie Hinson và Kit Keller. Dottie là cầu thủ tài năng chơi hay nhất đội còn Kit thì luôn ghen tị với người em gái. Mối quan hệ rất “con gái” giữa hai chị em đã tạo nên sự hấp dẫn và phức tạp cho bộ phim.Nút thắt của A League of Their Own nằm ở nhân vật Jimmy Dugan. Đây là cựu cầu thủ bóng chày một thời nổi tiếng, nhưng giờ đây chỉ là một tay nát rượu, lôi thôi lếch thếch và cư xử rất bất ...</p>', 'Full', 1, 'single', 'completed', 18, 1992, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Geena Davis","avatar":""},{"name":"Madonna","avatar":""},{"name":"Lori Petty","avatar":""},{"name":"Rosie O''Donnell","avatar":""},{"name":"Megan Cavanagh","avatar":""},{"name":"Tracy Reiner","avatar":""},{"name":"Bitty Schram","avatar":""},{"name":"Ann Cusack","avatar":""},{"name":"Anne Ramsay","avatar":""},{"name":"Freddie Simpson","avatar":""},{"name":"Renée Coleman","avatar":""},{"name":"Robin Knight","avatar":""},{"name":"Patti Pelton","avatar":""},{"name":"Kelli Simpkins","avatar":""},{"name":"Neezer Tarleton","avatar":""},{"name":"Connie Pounds-Taylor","avatar":""},{"name":"Kath","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324543);
