INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kung-fu-bo-cap', 'Kung Fu Bọ Cạp', 'Operation Scorpio', 'https://phimimg.com/upload/vod/20231010-1/f34ec2ca7e0902c1807258e71af28915.jpg', 'https://phimimg.com/upload/vod/20231010-1/6044075e28582a5fe69e2a2a9d5b542e.jpg', '<p>Họa sĩ truyện tranh mới nổi Yu Shu thấy mình đang sống trong những tưởng tượng về thế giới thay thế của mình khi anh cứu một cô gái trẻ khỏi một đường dây mại dâm bất hợp pháp. Với sự trợ giúp của trí tưởng tượng dồi dào và sự giúp đỡ của một chuyên gia kung fu già Yu Shu đã trở thành một điều mà ngay cả anh cũng chưa bao giờ dám mơ ước - một anh hùng ngoài đời thực.</p>', 'Full', 1, 'single', 'completed', 19, 1992, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chin Ka-Lok","avatar":""},{"name":"Won Jin","avatar":""},{"name":"Lau Kar-leung","avatar":""},{"name":"Frankie Chin Chi-Leung","avatar":""},{"name":"May Lo Mei-Wei","avatar":""},{"name":"Wu Fung","avatar":""},{"name":"Victor Hon Kwan","avatar":""},{"name":"Yuen Shun-Yi","avatar":""},{"name":"David Lo Dai-Wai","avatar":""},{"name":"Lawrence Lau Sek-Yin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324543);
