INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-gia-xao-quyet', 'Chuyên Gia Xảo Quyệt', 'Tricky Brains', 'https://phimimg.com/uploads/movies/20260713/chuyen-gia-xao-quyet-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/chuyen-gia-xao-quyet-poster.webp', '<p>Tricky Brains (1991) - Chuyên Gia Xảo Quyệt là bộ phim hài xoay quanh nhân vật Cổ Tinh, một chuyên gia bịp bợm đẹp trai, thông minh được thuê đội lốt người em cùng cha khác mẹ bị thất lạc từ nhỏ của Văn Kiệt. Chẳng bao lâu sau, dưới bàn tay đạo diễn của Cổ Tinh, việc làm ăn của công ty Văn Kiệt cũng như quan hệ tình cảm giữa Văn Kiệt và Trình Lạc Nhi mỗi lúc một trở nên tồi tệ. Tuy nhiên, bất chấp mọi tai ương, cha con Văn Kiệt vẫn một lòng yêu thương săn sóc Cổ Tinh và điều đó khiến chuyên gia bịp bợm cảm động, quyết định thay đổi. Liệu sự hối cải của Cổ Tinh có quá muộn màng? Liệu trong phim này anh có giúp Văn Kiệt vượt qua được sóng gió trong sự nghiệp và hàn gắn tình yêu với Lạc Nhi. Bằng phong cách hài hước kết hợp giữa diễn xuất hình thể và các tình huống khác thường đã làm nên thương hiệu Châu Tinh Trì, bộ phim này đem lại những giây phút thư giãn thoải mái cho người xem.</p>', 'Full', 1, 'single', 'completed', 43, 1991, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Stephen Chow","avatar":""},{"name":"Rosamund Kwan Chi-Lam","avatar":""},{"name":"Chingmy Yau Suk-Ching","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Wong Jing","avatar":""},{"name":"Bau Hon-Lam","avatar":""},{"name":"John Ching Tung","avatar":""},{"name":"Mannor Chan Man-Na","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Yu Miu-Lin","avatar":""},{"name":"Lo Fan","avatar":""},{"name":"Charlie Cho Cha-Lee","avatar":""},{"name":"Jo Jo Ngan Lai-Yue","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["The Ultimate Trickster","整蠱專家","Tricky Brains 1991 - Chuyên Gia Xảo Quyệt","Chuyên Gia Xảo Quyệt 1991","Tricky Brains"]', 1784690324543);
