INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-gia-xao-quyet', 'Chuyên Gia Xảo Quyệt', 'Tricky Brains', 'chuyên gia xảo quyệt tricky brains andy lau stephen chow rosamund kwan chi-lam chingmy yau suk-ching ng man-tat waise lee chi-hung wong jing bau hon-lam john ching tung mannor chan man-na shing fui-on yu miu-lin lo fan charlie cho cha-lee jo jo ngan lai-yue châu tinh trì the ultimate trickster 整蠱專家 tricky brains 1991 - chuyên gia xảo quyệt chuyên gia xảo quyệt 1991 tricky brains', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-co-bac-bip', 'Nữ Cờ Bạc Bịp', 'The Top Bet', 'https://phimimg.com/uploads/movies/20260713/nu-co-bac-bip-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/nu-co-bac-bip-poster.webp', '<p>Sau khi Thần Bài A Tinh chiến thắng trận cuối cùng trong cuộc thi quy tụ những cây bài xuất sắc nhất trên thế giới mang tên AFTW, Tinh quyết định đi du lịch vòng quanh thế giới. Điều này khiến chú Đạt bị rời vào một vị trí khó khăn khi một tay xã hội đen người Đài Loan xuất hiện thông báo rằng Thần Bài hoặc là phải chơi cho anh ta trong một giải đấu sắp tới hoặc là Đạt phải chết. Do đó, trừ khi có ai đó tốt hơn so với Thần Bài có thể được tìm thấy.</p>', 'Full', 1, 'single', 'completed', 44, 1991, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Carol Cheng","avatar":""},{"name":"Anita Mui Yim-Fong","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Sandra Ng Kwan-Yu","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Jeffrey Lau Chun-Wai","avatar":""},{"name":"Kenny Bee","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Lowell Lo Koon-Ting","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Corey Yuen","avatar":""},{"name":"Stephen Chow","avatar":""},{"name":"Angelina Lo Yuen-Yan","avatar":""},{"name":"Lau Shun","avatar":""},{"name":"Elaine Law Suet-Ling","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["赌圣延续篇：赌霸","The Top Bet","도패","도성 2 - 도패","Dou baa","도패 / 도성 2","도성2","賭霸"]', 1784690324543);
