INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-thanh', 'Tình Thánh', 'The Magnificent Scoundrels', 'https://phimimg.com/uploads/movies/20260713/tinh-thanh-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/tinh-thanh-poster.webp', '<p>Bộ phim Thánh Tình (The Magnificent Scoundrels) kể về anh chàng A Tinh (Châu Tinh Trì) chuyên đi lừa gạt mọi người. Anh có thu nhận 1 đệ tử là 1 cô gái. Sau đó 2 thầy trò anh vào lừa 1 gia đình giàu có ở HongKong. Không ngờ trong ngôi nhà đó cũng xuất hiện 1 nhóm người cũng đi lừa đảo khác. Hai bên lúc đầu cứ tưởng nhau là chủ nhà. Bắt đầu xuất hiện những tình huống dở khóc, dở cười. Cuối cùng họ phát hiện ra nhau và cùng hợp tác và đi lừa những tên xã hội đen và rất thành công!</p>', 'Full', 1, 'single', 'completed', 50, 1991, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Teresa Mo Shun-Kwan","avatar":""},{"name":"Tien Niu","avatar":""},{"name":"Amy Yip Chi-Mei","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Roy Cheung Yiu-Yeung","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Mimi Chu Mai-Mai","avatar":""},{"name":"Karl Maka","avatar":""},{"name":"Sandra Ng Kwan-Yu","avatar":""},{"name":"Gabriel Wong Yat-Shan","avatar":""},{"name":"Onitsuka Ng Kin-Chung","avatar":""},{"name":"Chan Yuet-Yue","avatar":""},{"name":"Corey Yuen","avatar":""},{"name":"Yip Wing-Yee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["신격대도","The Magnificent Scoundrels","情聖","Thánh Tinh 1991","情圣"]', 1784690324543);
