INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-thanh', 'Tình Thánh', 'The Magnificent Scoundrels', 'tình thánh the magnificent scoundrels stephen chow teresa mo shun-kwan tien niu amy yip chi-mei wu ma roy cheung yiu-yeung yuen wah mimi chu mai-mai karl maka sandra ng kwan-yu gabriel wong yat-shan onitsuka ng kin-chung chan yuet-yue corey yuen yip wing-yee châu tinh trì 신격대도 the magnificent scoundrels 情聖 thánh tinh 1991 情圣', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-tich-truyen-nhan', 'Long Tích Truyền Nhân', 'Legend Of The Dragon', 'https://phimimg.com/upload/vod/20231006-1/3042cdee7ee61ea7c7cddf981a681b34.jpg', 'https://phimimg.com/upload/vod/20231006-1/ad0cde5f942483f47d77d9bb38305a30.jpg', '<p>Long Tích Truyền Nhân - Legend Of The Dragon là một bộ phim hài hành động Hồng Kông năm 1990 của đạo diễn Daniel Lee, với sự tham gia của Châu Tinh Trì, Nguyên Hoa, Mao Thuấn Quân, Lương Gia Nhân...&nbsp; Họ Châu là 1 gia tộc lớn ở Đại Á, nổi tiếng với nghề múa lân. Châu Tử Long(Châu Tinh Trì) là con trai của Châu Phi Hùng(Nguyên Hoa) - một đại võ sư được người trong vùng kính trọng. Tử Long ham mê chơi bời, không lo học võ, bù lại anh chàng lại có khả năng chơi bida xuất thần. Chàng trai trẻ rời khỏi làng quê để tìm kiếm vận may ở Hồng Kông dưới sự dẫn dắt đáng ngờ của chú Nhân (Lương Gia Nhân), người đã khuyến khích anh ta sử dụng khả năng thiên phú của mình để hưởng lợi. Bộ phim cũng có sự tham gia của vận động viên 6 lần vô địch bi da thế giới Jimmy White trong thế giới thực, là đối thủ cuối cùng của Châu Tử Long(Châu Tinh Trì).</p>', 'Full', 1, 'single', 'completed', 44, 1991, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Teresa Mo","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Lee Hoi-Sang","avatar":""},{"name":"Lung Fong","avatar":""},{"name":"Amy Yip","avatar":""},{"name":"Corey Yuen","avatar":""},{"name":"Jimmy White","avatar":""},{"name":"Kwok Kwan-Shing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324543);
