INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-bai-3-tro-lai-thuong-hai', 'Thánh Bài 3: Trở Lại Thượng Hải', 'God Of Gamblers III: Back To Shanghai', 'https://phimimg.com/uploads/movies/20260713/thanh-bai-3-tro-lai-thuong-hai-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/thanh-bai-3-tro-lai-thuong-hai-poster.webp', '<p>Trong khi giao chiến với một tay bạc có siêu năng lực, Tinh trở lại Thượng Hải vào năm 1937. Bây giờ, anh phải đối mặt với quá khứ của gia đình mình và quay về năm 1991.</p>', 'Full', 1, 'single', 'completed', 45, 1991, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Gong Li","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"Charles Heung","avatar":""},{"name":"Sandra Ng Kwan-Yu","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Sharla Cheung","avatar":""},{"name":"John Ching Tung","avatar":""},{"name":"Tien Feng","avatar":""},{"name":"Wong Jing","avatar":""},{"name":"Lung Fong","avatar":""},{"name":"Wong Wan-Sze","avatar":""},{"name":"Yeung Ching-Ching","avatar":""},{"name":"Billy Chow Bei-Lei","avatar":""},{"name":"Barry Wong Ping-Yiu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["赌侠II之上海滩赌圣","God of Gamblers III","赌侠2之上海滩赌圣","赌侠2：上海滩赌圣","คนตัดคน 3 เจาะเวลาหาเจ้าพ่อเซี่ยงไฮ้","คนตัดคน 3","賭俠2之上海灘賭聖","Les Dieux du jeu 3 : Retour à Shanghai","God of Gamblers II:  Back to Shanghai","Qumar Tanrıları 3: Şanghaya Qayıdış","Kumar Tanrılar 3: Şanghaya Dönüş","God of Gambler