INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-hoc-uy-long-i', 'Trường Học Uy Long I', 'Fight Back To School', 'https://phimimg.com/uploads/movies/20260713/truong-hoc-uy-long-i-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/truong-hoc-uy-long-i-poster.webp', '<p>Phim Trường Học Uy Long (1991) kể về một người cảnh sát chìm Chow Sing-Sing (Châu Tinh Trì), thâm nhập vào một trường trung học với mục tiêu là tìm cho ra cây súng của sếp mình bị đánh cắp. Trong phim, cùng với sự trợ giúp của các đồng nghiệp cảnh sát cũng giả dạng thành học sinh, công cuộc tìm kiếm của Chow cũng vẫn gặp đầy khó khăn bởi sự lì lợm của những đứa học trò. Sự khó chịu của các thầy cô giáo, và hơn nữa là Chow lại đụng độ với tên đầu gấu của trường. Nhưng đối với Chow, để bù lại những khó khăn thử thách đó thì chỉ cần được gặp mặt cô giáo (mới chuyển công tác đến trường) là đủ.</p>', 'Full', 1, 'single', 'completed', 40, 1991, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Tinh Trì","avatar":""},{"name":"Ngô Mạnh Đạt","avatar":""},{"name":"Trương Mẫn","avatar":""},{"name":"Trương Diệu Dương","avatar":""},{"name":"Hoàng Nhất Sơn","avatar":""},{"name":"Tần Bái","avatar":""},{"name":"Uyển Quỳnh Đan","avatar":""},{"name":"Trần Quốc Tân","avatar":""},{"name":"Hoàng Tử Dương","avatar":""},{"name":"Hoàng Bỉnh Diệu","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["逃学威龙1","도학위룡","도학위룡 1","Fight Back to School","