INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-hoc-uy-long-i', 'Trường Học Uy Long I', 'Fight Back To School', 'trường học uy long i fight back to school châu tinh trì ngô mạnh đạt trương mẫn trương diệu dương hoàng nhất sơn tần bái uyển quỳnh đan trần quốc tân hoàng tử dương hoàng bỉnh diệu stephen chow 逃学威龙1 도학위룡 도학위룡 1 fight back to school 逃學威龍', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-khuat', 'Góc Khuất', 'My Own Private Idaho', 'https://phimimg.com/upload/vod/20260602-1/bdad8de2795c691f82b7d828ed6acc9a.jpg', 'https://phimimg.com/upload/vod/20260602-1/90b1b17acec699cb03ef460fac64277c.jpg', '<p>Bộ phim xoay quanh những góc khuất đen tối bên lề của đường phố Portland, Oregon miền Tây nước Mỹ, thông qua tình bạn của hai thanh niên sống lang thang Mike Waters (River Phoenix) và Scott Favor (Keanu Reeves). Mike sống nội tâm và đồng tính, anh đi tìm người mẹ ghẻ lạnh đã hất hủi mình. Scott là đứa con nổi loạn của một gia đình tài phiệt. Anh đã cùng với bạn của mình hút ma túy, bán mình như một “trai bao” và sống lay lắt cùng một bang nhóm hè phố…</p>', 'Full', 1, 'single', 'completed', 15, 1991, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"River Phoenix","avatar":""},{"name":"Keanu Reeves","avatar":""},{"name":"James Russo","avatar":""},{"name":"William Richert","avatar":""},{"name":"Rodney Harvey","avatar":""},{"name":"Chiara Caselli","avatar":""},{"name":"Michael Parker","avatar":""},{"name":"Jessica Makinson","avatar":""},{"name":"Flea","avatar":""},{"name":"Grace Zabriskie","avatar":""},{"name":"Tom Troupe","avatar":""},{"name":"Udo Kier","avatar":""},{"name":"Sally Curtice","avatar":""},{"name":"Robert Lee Pitchlynn","avatar":""},{"name":"Mickey Cottrell","avatar":""},{"name":"Wade Evans","avatar":""},{"name":"Matthew Ebert","avatar":""},{"name":"Scott","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Belli e Dannati","不羁的天空","属于我的爱达荷","我私人的爱达荷","男人的一半還是男人","Garotos de Programa","Mi mundo privado","Idaho: El camino de mis sueños","A Caminho de Idaho","Mi Idaho privado","Моят личен Айдахо","Idaho","Mon Idaho","Das Ende der Unschuld","My Private Idaho – Das Ende der Unschuld","My Own Private Idaho","Matkalla Idahoon","På lift mot Idaho","To diko mou Idaho","Το δικό μου Αϊντάχο","Otthonom Idaho","Otthonom, Idaho","Idaho Sheli","My Private Idaho","Manasis Aidahas","I drift mot Idaho","Moje wlasne Idaho","Moj privatni Ajdaho","Мой личный штат Айдахо","På drift mot Idaho","Moj mali Idaho","Benim Güzel Idaho''m","리버피닉스의 아이다호","Los dueños de la noche","Мій особистий штат Айдахо"]', 1784690324543);
