INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('goc-khuat', 'Góc Khuất', 'My Own Private Idaho', 'góc khuất my own private idaho river phoenix keanu reeves james russo william richert rodney harvey chiara caselli michael parker jessica makinson flea grace zabriskie tom troupe udo kier sally curtice robert lee pitchlynn mickey cottrell wade evans matthew ebert scott belli e dannati 不羁的天空 属于我的爱达荷 我私人的爱达荷 男人的一半還是男人 garotos de programa mi mundo privado idaho: el camino de mis sueños a caminho de idaho mi idaho privado моят личен айдахо idaho mon idaho das ende der unschuld my private idaho – das ende der unschuld my own private idaho matkalla idahoon på lift mot idaho to diko mou idaho το δικό μου αϊντάχο otthonom idaho otthonom, idaho idaho sheli my private idaho manasis aidahas i drift mot idaho moje wlasne idaho moj privatni ajdaho мой личный штат айдахо på drift mot idaho moj mali idaho benim güzel idaho''m 리버피닉스의 아이다호 los dueños de la noche мій особистий штат айдахо', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-nguoi-may', 'Mỹ Nhân Người Máy', 'Robotrix', 'https://phimimg.com/upload/vod/20260513-1/183a57f83b78a015ef6627b3af1b2f10.jpg', 'https://phimimg.com/upload/vod/20260513-1/c0abee2815f0f60596d1368671520a5a.jpg', '<p>Phim xoay quanh câu chuyện tên bác học điên đã chuyển não bộ của mình vào thân thể của một con robot mạnh mẽ và độc ác do ông chế tạo ra để thực hiện những phi vụ phạm pháp, sát hại người vô tội trong số đó có một nữ thám tử đang điều tra ông ấy.Sau cái chết đó, nữ thám tử đã được chuyển chuyển thể thành một dạng robot để đối đầu với tên khoa học điên rồ đó...Ngoài những cảnh nóng được thực hiện bởi những mỹ nhân đến từ Nhật và Hồng Kông, phim còn có những cảnh hành động được dàn dựng khá công phu, trong đó phải kể đến vai diễn của nam diễn viên võ thuật Chu Tỉ Lợi.</p>', 'Full', 1, 'single', 'completed', 19, 1991, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"葉子楣","avatar":""},{"name":"青山知可子","avatar":""},{"name":"Hui Hiu-Daan","avatar":""},{"name":"吳大維","avatar":""},{"name":"周比利","avatar":""},{"name":"胡楓","avatar":""},{"name":"翁世傑","avatar":""},{"name":"林聰","avatar":""},{"name":"鬼塚","avatar":""},{"name":"區月華","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '["사이보그 마담","Nu ji xie ren","女機械人","女机械人","バストロイド　香港大作戦！！"]', 1784690324543);
