INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('my-nhan-nguoi-may', 'Mỹ Nhân Người Máy', 'Robotrix', 'mỹ nhân người máy robotrix 葉子楣 青山知可子 hui hiu-daan 吳大維 周比利 胡楓 翁世傑 林聰 鬼塚 區月華 사이보그 마담 nu ji xie ren 女機械人 女机械人 バストロイド　香港大作戦！！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-dao-sinh-cuoi-cung', 'Hướng đạo sinh cuối cùng', 'The Last Boy Scout', 'https://phimimg.com/upload/vod/20260508-1/5684a08e1d9a42f3557371b567455fa2.jpg', 'https://phimimg.com/upload/vod/20260508-1/cd0c2b479f273b1be549f45f7f15dacc.jpg', '<p>Tại một nơi nào đó ở Los Angeles, thành phố của những giấc mơ tan vỡ, một vũ nữ thoát y bị sát hại. Giờ đây, thám tử tư mà cô thuê và bạn trai cũ, một cầu thủ bóng đá, sẽ tìm ra kẻ giết người... nếu họ không giết nhau trước. Nhưng càng điều tra, họ càng vướng sâu vào một mạng lưới tống tiền, hăm dọa và chính trị tham nhũng ẩn giấu dưới bề mặt của bóng đá chuyên nghiệp.</p>', 'Full', 1, 'single', 'completed', 18, 1991, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Damon Wayans","avatar":""},{"name":"Chelsea Field","avatar":""},{"name":"Noble Willingham","avatar":""},{"name":"Taylor Negron","avatar":""},{"name":"Danielle Harris","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Bruce McGill","avatar":""},{"name":"Badja Djola","avatar":""},{"name":"Kim Coates","avatar":""},{"name":"Chelcie Ross","avatar":""},{"name":"Joe Santos","avatar":""},{"name":"Clarence Felder","avatar":""},{"name":"Tony Longo","avatar":""},{"name":"Frank Collison","avatar":""},{"name":"Bill Medley","avatar":""},{"name":"Verne Lundquist","avatar":""},{"name":"Dick Butk","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Den siste scouten","Последний бойскаут","Le Dernier boy scout","Son Gorev","Zadnji skavt","Poslednji skaut","A Fúria do Último Escuteiro","Ostatni skaut","Den siste speider","El Último Boy Scout","L''ultimo boy scout","Az utolsó cserkész","Prljavi igraju prljavo","Ο τελευταίος πρόσκοπος","Le dernier samaritain","Viimeinen partiopoika","El último Boy Scout","Last Boy Scout - Das Ziel ist Überleben","O Último Boy Scout","Последният бойскаут","Poslední skaut","Posledný skaut","最後戰士","ラスト・ボーイスカウト：1991","The Last Boy Scout"]', 1784690324543);
