INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huong-dao-sinh-cuoi-cung', 'Hướng đạo sinh cuối cùng', 'The Last Boy Scout', 'hướng đạo sinh cuối cùng the last boy scout bruce willis damon wayans chelsea field noble willingham taylor negron danielle harris halle berry bruce mcgill badja djola kim coates chelcie ross joe santos clarence felder tony longo frank collison bill medley verne lundquist dick butk den siste scouten последний бойскаут le dernier boy scout son gorev zadnji skavt poslednji skaut a fúria do último escuteiro ostatni skaut den siste speider el último boy scout l''ultimo boy scout az utolsó cserkész prljavi igraju prljavo ο τελευταίος πρόσκοπος le dernier samaritain viimeinen partiopoika el último boy scout last boy scout - das ziel ist überleben o último boy scout последният бойскаут poslední skaut posledný skaut 最後戰士 ラスト・ボーイスカウト：1991 the last boy scout', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('defenseless', 'Defenseless', 'Defenseless', 'https://phimimg.com/upload/vod/20260505-1/fc8143446af226eaf3774a0610b9fe4a.jpg', 'https://phimimg.com/upload/vod/20260505-1/f39516118b628c6fdada44045e432a32.jpg', '<p>Một luật sư ở Los Angeles bào chữa cho người bạn cùng phòng thời đại học cũ của mình, người mà chồng cô ấy - cũng là người tình của cô ấy - đã bị sát hại.</p>', 'Trailer', 1, 'single', 'ongoing', 18, 1991, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Barbara Hershey","avatar":""},{"name":"Sam Shepard","avatar":""},{"name":"Christine Elise","avatar":""},{"name":"Mary Beth Hurt","avatar":""},{"name":"J.T. Walsh","avatar":""},{"name":"Kellie Overbey","avatar":""},{"name":"Jay O. Sanders","avatar":""},{"name":"John Kapelos","avatar":""},{"name":"Sheree North","avatar":""},{"name":"Randy Brooks","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Sans aucune défense","Wehrlos","Defenseless"]', 1784690324543);
