INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-lanh', 'Đá Lạnh', 'Stone Cold', 'https://phimimg.com/upload/vod/20260501-1/80720f812c6e054ca8adc6ffffc820ba.jpg', 'https://phimimg.com/upload/vod/20260501-1/bde2776104d08ec3e2431d34d0bb5946.jpg', '<p>Joe Huff (Brian Bosworth) là một cảnh sát cô độc, cứng rắn và có khả năng thâm nhập vào các băng nhóm nguy hiểm. FBI tống Joe vào một hoạt động bí mật đòi hỏi phải thâm nhập vào &quot;The Brotherhood&quot; - một băng đảng đua xe đạp hùng mạnh ở Mississippi có liên quan đến vụ sát hại các quan chức chính phủ cũng như buôn bán ma túy với mafia.</p>', 'Full', 1, 'single', 'completed', 13, 1991, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brian Bosworth","avatar":""},{"name":"Lance Henriksen","avatar":""},{"name":"William Forsythe","avatar":""},{"name":"Arabella Holzbog","avatar":""},{"name":"Sam McMurray","avatar":""},{"name":"Richard Gant","avatar":""},{"name":"Paulo Tocha","avatar":""},{"name":"David Tress","avatar":""},{"name":"Evan James Malmuth","avatar":""},{"name":"Tony Pierce","avatar":""},{"name":"Billy Million","avatar":""},{"name":"Robert Winley","avatar":""},{"name":"Gregory Scott Cummins","avatar":""},{"name":"Demetre Phillips","avatar":""},{"name":"Magic Schwarz","avatar":""},{"name":"Laura Albert","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Stone Cold (1991)","Dur comme Stone","九反威龍","Stone Cold - Kalt wie Stein","九反威龙","A Fúria do Justiceiro","Stone Cold"]', 1784690324543);
