INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('da-lanh', 'Đá Lạnh', 'Stone Cold', 'đá lạnh stone cold brian bosworth lance henriksen william forsythe arabella holzbog sam mcmurray richard gant paulo tocha david tress evan james malmuth tony pierce billy million robert winley gregory scott cummins demetre phillips magic schwarz laura albert stone cold (1991) dur comme stone 九反威龍 stone cold - kalt wie stein 九反威龙 a fúria do justiceiro stone cold', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-giap-thuong-de-2', 'Áo Giáp Thượng Đế 2', 'Operation Condor (Armour Of God 2)', 'https://phimimg.com/upload/vod/20260219-1/c1bd7addd459f50ff4cec18bda2d11cf.jpg', 'https://phimimg.com/upload/vod/20260418-1/b63202ee0b0319c08a67b759737fe927.jpg', '<p>Lần này, Jackie được Liên Hợp Quốc và một tổ chức quốc tế bí mật giao nhiệm vụ tìm kiếm 249 tấn vàng bị cướp từ quân Đức Quốc xã vào cuối Thế chiến II và chôn giấu ở một sa mạc thuộc châu Phi. Mặc dù ban đầu không mấy hứng thú, Jackie bị thuyết phục tham gia nhiệm vụ sau khi nhận được một khoản tiền lớn và biết rằng nhóm tìm kiếm ban đầu đã biến mất một cách bí ẩn.
 Trong hành trình của mình, Jackie phải hợp tác với ba người phụ nữ xinh đẹp: Ada (Carol Cheng), một chuyên gia bản đồ; Elsa (Eva Cobo de Dueñas), cháu gái của một chỉ huy Đức Quốc xã có liên quan đến kho báu; và Momoko (Shoko Ikeda), một cô gái Nhật Bản bị mất trí nhớ và luôn bị truy đuổi.</p>', 'Full', 1, 'single', 'completed', 21, 1991, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Thành Long","avatar":""},{"name":"Trịnh Dụ Linh","avatar":""},{"name":"Eva Cobo","avatar":""},{"name":"Shoko Ikeda","avatar":""},{"name":"Lâm Uy","avatar":""},{"name":"Jonathan Isgar","avatar":""},{"name":"Dan Mintz","avatar":""},{"name":"Božidar Smiljanić","avatar":""},{"name":"Aldo Sambrell","avatar":""},{"name":"Lô Huệ Quang","avatar":""},{"name":"Ken Goodman","avatar":""},{"name":"Winston Ellis","avatar":""},{"name":"Wayne Archer","avatar":""},{"name":"Bruce Fontaine","avatar":""},{"name":"Steve Tartalia","avatar":""},{"name":"John Ladalski","avatar":""},{"name":"Mark King","avatar":""},{"name":"Joe Bryan Baker","avatar":""},{"name":"Charl","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Operation Condor","Fei ying gai wak","Božji oklop 2 - Operacija Kondor","Keravnos sti Sahara","Project Eagle","Armour of God II: Operation Condor","Fei ying ji hua","Long xiong hu di xu ji","Božiji oklop II: Operacija Kondor","Божји оклоп 2: Операција Кондор","Božji oklop 2: Operacija Kondor","Доспехи Бога 2","La armadura de dios II","L''armadura de Déu 2: Operació Còndor","Operation Condor: Armour of God II","Armour of God 2: Operation Condor","Operation Condor: Armour of God 2","Armour of God II - Der starke Arm der Götter","The Armour of God II: Operation Condor","プロジェクト・イーグル","飛鷹計劃"]', 1784690324543);
