INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ao-giap-thuong-de-2', 'Áo Giáp Thượng Đế 2', 'Operation Condor (Armour Of God 2)', 'áo giáp thượng đế 2 operation condor (armour of god 2) thành long trịnh dụ linh eva cobo shoko ikeda lâm uy jonathan isgar dan mintz božidar smiljanić aldo sambrell lô huệ quang ken goodman winston ellis wayne archer bruce fontaine steve tartalia john ladalski mark king joe bryan baker charl jackie chan operation condor fei ying gai wak božji oklop 2 - operacija kondor keravnos sti sahara project eagle armour of god ii: operation condor fei ying ji hua long xiong hu di xu ji božiji oklop ii: operacija kondor божји оклоп 2: операција кондор božji oklop 2: operacija kondor доспехи бога 2 la armadura de dios ii l''armadura de déu 2: operació còndor operation condor: armour of god ii armour of god 2: operation condor operation condor: armour of god 2 armour of god ii - der starke arm der götter the armour of god ii: operation condor プロジェクト・イーグル 飛鷹計劃', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-the-hao-menh', 'Nhất Thế Hảo Mệnh', 'You Bet Your Life', 'https://phimimg.com/upload/vod/20260323-1/b403dd77d52e50bc1c2fe09e3b5d3b00.jpg', 'https://phimimg.com/upload/vod/20260323-1/73b66fd438db1515592df75dbe19f746.jpg', '<p>Vợ chồng A Hữu (Lư Quán Đình thủ vai) và A Như (Ngô Quân Như thủ vai) là những kẻ nghiện cờ bạc đến xương tủy, nhưng trớ trêu thay vận may quá kém khiến cuộc sống luôn túng quẫn. Họ cùng với cậu em trai của A Như là A Minh (Hoàng Nhất Sơn thủ vai) đang thuê chung một nhà và thường xuyên phải tìm đủ mọi cách để khất nợ tiền thuê phòng.&nbsp; Trong tòa chung cư họ ở có một căn phòng hung ám, nơi một cô gái nhảy từng tự sát, và hàng năm đều có một vị cao tăng đến đây làm phép siêu độ cho vong hồn. Một ngày nọ, vợ chồng A Hữu kinh ngạc khi thấy một tay chơi bài thắng lớn. Qua lời của người bạn thân Thất Ca (Viên Tường Nhân thủ vai), họ biết được đối phương đã dùng bí thuật Mao Sơn mang tên &quot;Hút tài khí&quot; để đổi vận. Hai vợ chồng bèn bắt chước làm theo, nhưng lại vô tình làm hỏng xác ướp dùng để hút khí.&nbsp; Sau đó, hai người tiếp tục dùng phương pháp &quot;nuôi quỷ&quot; do Thất Ca truyền dạy để lập giao kèo với hồn ma cô gái nhảy trong tòa nhà. Kể từ đó, họ đánh đâu thắng đó, nhưng phải chịu sự ràng buộc bởi điều kiện của nữ quỷ: &quot;Trước 7 giờ tối mỗi ngày phải tiêu hết sạch số tiền thắng được của ngày hôm trước&quot;. Việc tiêu tiền khiến họ luôn trong trạng thái nơm nớp lo sợ. Và rồi, một sự cố ngoài ý muốn đã xảy ra...</p>', 'Full', 1, 'single', 'completed', 20, 1991, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"La Khôn Đình","avatar":""},{"name":"Ngô Quân Như","avatar":""},{"name":"Hoàng Nhất Sơn","avatar":""},{"name":"Trần Long","avatar":""},{"name":"Hứa Thiệu Hùng","avatar":""},{"name":"Nguyên Trường Nhạn","avatar":""},{"name":"Ôn Lệ Ngọc","avatar":""},{"name":"Diệp Vinh Tổ","avatar":""},{"name":"Trịnh Thiệu Bình","avatar":""},{"name":"Trịnh Mẫn Hà","avatar":""},{"name":"Lý Trung Linh","avatar":""},{"name":"Trần Vinh Biểu","avatar":""},{"name":"Hoàng Nhất Phi","avatar":""},{"name":"Dư Mộ Liên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Charmed Life","一世好命"]', 1784690324543);
