INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-the-hao-menh', 'Nhất Thế Hảo Mệnh', 'You Bet Your Life', 'nhất thế hảo mệnh you bet your life la khôn đình ngô quân như hoàng nhất sơn trần long hứa thiệu hùng nguyên trường nhạn ôn lệ ngọc diệp vinh tổ trịnh thiệu bình trịnh mẫn hà lý trung linh trần vinh biểu hoàng nhất phi dư mộ liên a charmed life 一世好命', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mannequin-two-on-the-move', 'Mannequin Two: On the Move', 'Mannequin Two: On the Move', 'https://phimimg.com/upload/vod/20260214-1/eaad8320089cfd364f72b5e88dd3078c.jpg', 'https://phimimg.com/upload/vod/20260214-1/8b6ae7e9cfcbe84341c229e76aabf4fd.jpg', '<p>Mannequin Two: On the Move là một bộ phim hài lãng mạn năm 1991 và là phần tiếp theo của bộ phim Mannequin năm 1987.</p>', 'Full', 1, 'single', 'completed', 14, 1991, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kristy Swanson","avatar":""},{"name":"William Ragsdale","avatar":""},{"name":"Meshach Taylor","avatar":""},{"name":"Terry Kiser","avatar":""},{"name":"Stuart Pankin","avatar":""},{"name":"Cynthia Harris","avatar":""},{"name":"Heather Henderson","avatar":""},{"name":"Andrew Hill Newman","avatar":""},{"name":"John Edmondson","avatar":""},{"name":"Erick Weiss","avatar":""},{"name":"Julie Foreman","avatar":""},{"name":"Phil Latella","avatar":""},{"name":"Mark Gray","avatar":""},{"name":"Jackye Roberts","avatar":""},{"name":"John Casino","avatar":""},{"name":"Laurie Wing","avatar":""},{"name":"Julie Warde","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Mannequin 2: On the Move","几世情缘","Me Enamore de un Maniquí 2","Mannequin Two: On the Move","Manequim 2: A Magia do Amor","神气活现2：千年痴情","Mannequin II: On the Move (1991)"]', 1784690324543);
