INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mannequin-two-on-the-move', 'Mannequin Two: On the Move', 'Mannequin Two: On the Move', 'mannequin two: on the move mannequin two: on the move kristy swanson william ragsdale meshach taylor terry kiser stuart pankin cynthia harris heather henderson andrew hill newman john edmondson erick weiss julie foreman phil latella mark gray jackye roberts john casino laurie wing julie warde mannequin 2: on the move 几世情缘 me enamore de un maniquí 2 mannequin two: on the move manequim 2: a magia do amor 神气活现2：千年痴情 mannequin ii: on the move (1991)', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-an-rong-thieng-ban-1991', 'Dấu Ấn Rồng Thiêng (Bản 1991)', 'Dragon Quest: The Adventure Of Dai', 'https://phimimg.com/upload/vod/20260113-1/84439f817d86682ebf2b1602d44e6bf7.jpg', 'https://phimimg.com/upload/vod/20260113-1/8e16ca9d4920f2deb462d96b078dde92.jpg', '<p>Sau thất bại của Ma vương Hadlar, tất cả quái vật đã được giải phóng khỏi ý chí tà ác của hắn và chuyển đến đảo Delmurin để sống trong hòa bình. Dai là con người duy nhất sinh sống trên hòn đảo này. Được nuôi dưỡng bởi quái vật hiền lành Brass, ước mơ của Dai là trở thành một anh hùng. Cơ hội đã đến khi Hadlar hồi sinh, và vị anh hùng tiền nhiệm Avan đã tìm đến để huấn luyện Dai chuẩn bị cho cuộc chiến.Thế nhưng, Hadlar bất ngờ xuất hiện với tuyên bố rằng hắn hiện đang phục vụ cho một Ma vương còn hùng mạnh hơn gấp bội, với mục tiêu tiêu diệt Avan. Để cứu các học trò của mình, Avan đã sử dụng ma pháp hy sinh tính mạng để tấn công, nhưng vẫn không thể đánh bại được Hadlar. Ngay khi tưởng chừng như Dai và người đồng môn Pop đã rơi vào đường cùng, một ấn ký lạ bỗng xuất hiện trên trán Dai. Cậu đột ngột nhận được sức mạnh phi thường và đẩy lùi được Hadlar. Kể từ đó, hai người học trò bắt đầu cuộc hành trình đầy gian khổ để trả thù cho thầy Avan và mang lại hòa bình cho thế giới.</p>', 'Hoàn Tất (46/46)', 46, 'hoathinh', 'completed', 12, 1991, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshiko Fujita","avatar":""},{"name":"Aya Hisakawa","avatar":""},{"name":"Banjo Ginga","avatar":""},{"name":"Hideyuki Hori","avatar":""},{"name":"Isamu Tanonaka","avatar":""},{"name":"Kenji Utsumi","avatar":""},{"name":"Mina Tominaga","avatar":""},{"name":"Takeshi Aono","avatar":""},{"name":"Yumi Touma","avatar":""},{"name":"Aruno Tahara","avatar":""},{"name":"Chieko Namba","avatar":""},{"name":"Ken Yamaguchi","avatar":""},{"name":"Naoki Tatsuta","avatar":""},{"name":"Unsho Ishizuka","avatar":""},{"name":"Hiroshi Masuoka","avatar":""},{"name":"Kiyoyuki Yanada","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fly, o Pequeno Guerreiro","勇者斗恶龙 达伊的大冒险","Dragon Quest : La Quête de Daï","Fly","I Cavalieri del Drago","Dragon Quest -Dai no Daibōken-","Dai no Daibouken","Dragon Quest: Dai no Daibouken","드래곤 퀘스트 다이의 대모험","드래곤 퀘스트 - 타이의 대모험","드래곤 퀘스트: 다이의 대모험","드래곤 퀘스트: 타이의 대모험","Dragon Quest: Adventure of Dai","Dragon Quest: Dai''s Great Adventure","ドラゴンクエスト ダイの大冒険"]', 1784690324543);
