INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-cuoc-phieu-luu-cua-sherlock-holmes-phan-5', 'Những Cuộc Phiêu Lưu Của Sherlock Holmes (Phần 5)', 'Sherlock Holmes (Season 5)', 'những cuộc phiêu lưu của sherlock holmes (phần 5) sherlock holmes (season 5) jeremy brett edward hardwicke rosalie williams 福尔摩斯冒险史 福尔摩斯探案集之福尔摩斯冒险史 福尔摩斯历险记 the adventures of sherlock holmes sherlock holmes the adventures of sherlock holmes σέρλοκ χολμς οι περιπέτειες του σέρλοκ χολμς הרפתקאותיו של שרלוק הולמס 셜록 홈즈의 모험 셜록홈즈의 모험 셜록 홈즈의 회상 셜록홈즈의 회상 셜록 홈즈의 귀환 셜록홈즈의 귀환 셜록 홈즈의 사건집 셜록홈즈의 사건집 셜록 홈즈 приключения шерлока холмса شرلوك هولمز', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('han-thu-duong-doi', 'Hận Thù Đường Đời', 'The Good Fella from Temple Street', 'https://phimimg.com/upload/vod/20251023-1/2348b3ed985adc9076e884063d55424a.jpg', 'https://phimimg.com/upload/vod/20251023-1/adfa6e680bfecb7a73677d5de486c565.jpg', '<p>Trương Tuệ Đức là cô gái nghèo ở Đại Lục một mình bôn ba đến Hồng Kông tìm người thân. Đến nơi mới hay người thân đã không còn. Với bản tính thật thà cả tin, cô bị bà chủ nhà chứa lừa ép phải làm gái. Tuệ Đức đồng ý đám cưới với một cảnh sát địa phương với mong ước sẽ có một cuộc sống tốt đẹp hơn, họ có với nhau một đứa con gái đặt tên là Bội Linh. Với tấm lòng nhân hậu, Tuệ Đức đã nhận một bé trai bị bỏ rơi bên đường về làm con nuôi dưỡng và đặt tên là Thiên Tứ. Bội Linh lớn lên trở thành một thiếu nữ hư hỏng, ngày ngày đối diện với Thiên Tứ, nên đã nảy sinh tình cảm với anh nuôi của mình.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 9, 1991, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324543);
