INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-menh-me-cung', 'Vận Mệnh Mê Cung', 'A New Life', 'https://phimimg.com/upload/vod/20251010-1/2f4ac700d73a8f8d941d6b0da64bfec0.jpg', 'https://phimimg.com/upload/vod/20251010-1/4609b829bcc7d5af12b1e91491381c61.jpg', '<p>Nhiệm Chỉ Hào xuất thân là một tên xã hội đen, giết người cướp của như cơm bữa nhưng nhờ được Hạ Tỉnh Văn thức tỉnh, anh đã quay trở về thành con người lương thiện, giúp ích cho xã hội. Trang Gia Tuấn vì bị Phương Thế Hy gài bẫy nên đã lâm vào con đường tham nhũng, còn bị cướp mất vợ và gián tiếp giết chết con trai duy nhất. Từ đó, trong đầu Gia Tuấn chỉ có thù hận và anh chấp nhận gia nhập băng đảng xã hội đen, chờ đợi ngày trả thù. Sau cùng là Mã Tường từng lâm cảnh cảnh tù đày, sau khi được ra tù anh làm ăn lương thiện. Nhưng một lần nữa, anh lại bước chân vào con đường tội lỗi...</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 10, 1991, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Savio Tsang","avatar":""},{"name":"Margie Tsang Wah-Sin","avatar":""},{"name":"Kitty Lai Mei-Han","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"Joseph Lee Kwok-Lun","avatar":""},{"name":"Yip Yuk-Ping","avatar":""},{"name":"Hung Chiu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["释囚故事","A New Life","命運迷宮"]', 1784690324543);
