INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-toi-ac-1991', 'Thành Phố Tội Ác', 'New Jack City', 'https://phimimg.com/upload/vod/20251010-1/e4026a9538670acaf54b0b92236cf80c.jpg', 'https://phimimg.com/upload/vod/20251010-1/2b410dd6cc634b51bc4674c47010ffdf.jpg', '<p>Phim kể về Nino Brown (Wesley Snipes) - một trùm tội phạm tàn nhẫn đã xây dựng đế chế ma túy “Cash Money Brothers” trong thời kỳ đại dịch crack ở New York những năm 1980. Khi Nino thống trị khu Harlem bằng bạo lực và quyền lực, hai cảnh sát chìm - Scotty Appleton (Ice-T) và Nick Peretti (Judd Nelson) - được giao nhiệm vụ triệt phá băng đảng này từ bên trong.</p>', 'Full', 1, 'single', 'completed', 12, 1991, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Wesley Snipes","avatar":""},{"name":"Ice-T","avatar":""},{"name":"Allen Payne","avatar":""},{"name":"Chris Rock","avatar":""},{"name":"Mario Van Peebles","avatar":""},{"name":"Michael Michele","avatar":""},{"name":"Bill Nunn","avatar":""},{"name":"Russell Wong","avatar":""},{"name":"Bill Cobbs","avatar":""},{"name":"Christopher Williams","avatar":""},{"name":"Judd Nelson","avatar":""},{"name":"Vanessa Williams","avatar":""},{"name":"Tracy Camilla Johns","avatar":""},{"name":"Anthony DeSando","avatar":""},{"name":"Nick Ashford","avatar":""},{"name":"Phyllis Yvonne Stickney","avatar":""},{"name":"Thalm","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["New Jack City: A Gangue Brutal","Zehirli Sokaklar","New Jack City"]', 1784690324543);
