INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-huy-diet-2-ngay-phan-xet', 'Kẻ Hủy Diệt 2: Ngày Phán Xét', 'Terminator 2: Judgment Day', 'https://phimimg.com/upload/vod/20250804-1/b00582bafa4cd2aa3a47498d1dd8bbb8.jpg', 'https://phimimg.com/upload/vod/20250804-1/ceae29514e42b825240c625cc7fb8c3b.jpg', '<p>Arnold Schwarzenegger một lần nữa trở lại vai diễn đáng nhớ nhất trong sự nghiệp - Robot T-800. 10 năm sau kể từ những sự kiện của phần đầu, những thử thách của Sarah Connor chỉ mới bắt đầu khi phải chống chọi để bảo vệ con trai John của mình khỏi một Kẻ Hủy Diệt mới, được gửi về quá khứ để tiêu diệt John Connor thời còn là một đứa trẻ.</p>', 'Full', 1, 'single', 'completed', 13, 1991, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Linda Hamilton","avatar":""},{"name":"Edward Furlong","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Earl Boen","avatar":""},{"name":"Joe Morton","avatar":""},{"name":"S. Epatha Merkerson","avatar":""},{"name":"Castulo Guerra","avatar":""},{"name":"Danny Cooksey","avatar":""},{"name":"Jenette Goldstein","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Leslie Hamilton Gearren","avatar":""},{"name":"Ken Gibbel","avatar":""},{"name":"Robert Winley","avatar":""},{"name":"Pete Schrum","avatar":""},{"name":"Shane Wi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["未來戰士續集","T2","Terminator 2: Judgement Day