INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('den-thuong-de-cung-phai-cuoi-3', 'Đến Thượng Đế Cũng Phải Cười 3', 'The Gods Must Be Crazy: Crazy Safari', 'https://phimimg.com/upload/vod/20250516-1/f3d5934d7662846135d49f5dc9dd2828.jpg', 'https://phimimg.com/upload/vod/20250516-1/b7c360a43634749c1c5024e78fd52a38.jpg', '<p>Hai anh chàng, một trong số họ là một pháp sư, đang vận chuyển một ma cà rồng Trung Quốc cổ đại chỉ có thể được điều khiển bằng một loạt băng màu vàng, và là tổ tiên của anh chàng kia. Trên đường đi, khi đang bay qua Châu Phi, máy bay của họ bị chết máy. Và trong số tất cả các nơi, họ hạ cánh ở đâu? Đúng vậy, trong ngôi làng của bộ tộc &quot;Các vị thần phải điên rồ&quot;.</p>', 'Full', 1, 'single', 'completed', 9, 1991, 'Vietsub + Thuyết Minh', 'HD', 'Hồng Kông', 0, '[{"name":"N!xau","avatar":""},{"name":"Lam Ching-Ying","avatar":""},{"name":"Chan San-Hiu","avatar":""},{"name":"Peter Chan Lung","avatar":""},{"name":"Peter Pau Tak-Hai","avatar":""},{"name":"Michelle Bestbier","avatar":""},{"name":"Saul Bamberger","avatar":""},{"name":"Peter Mahlangu","avatar":""},{"name":"Bo Kaesje","avatar":""},{"name":"Christopher Kubheka","avatar":""},{"name":"Elias Meintjies","avatar":""},{"name":"Paddy O''Byrne","avatar":""},{"name":"Stephen Chow","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Peter Pau Tak-Hai","avatar":""},{"name":"Graham Armitage","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Fei zhou he shang","The Gods Must Be Crazy III","The Gods Must Be Crazy 3","非洲和尚","Tanrılar Çıldırmış Olmalı 3","강시와 부시맨"]', 1784690324543);
