INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-song-kinh-hoang', 'Dòng Sông Kinh Hoàng', 'Cape Fear', 'https://phimimg.com/upload/vod/20250701-1/323e029f7ad0bff4f72299067bddf5d2.jpg', 'https://phimimg.com/upload/vod/20250701-1/0cd93d6ee4a7070d0081313fa41c0026.jpg', '<p>Cuộc sống gia đình của một luật sư đáng kính bỗng dưng đảo lộn sau khi một tên tội phạm mãn hạn tù. Tất cả bắt đầu từ việc ông không chịu cung cấp bằng chứng có lợi cho hắn trong phiên tòa xét xử hơn 10 năm về trước. Tên tội phạm này sẽ làm gì để trả thù người đã đưa mình vào tù? Số phận của gia đình vị luật sư đáng kính này ra sao?</p>', 'Full', 1, 'single', 'completed', 12, 1991, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Jessica Lange","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"Joe Don Baker","avatar":""},{"name":"Robert Mitchum","avatar":""},{"name":"Gregory Peck","avatar":""},{"name":"Martin Balsam","avatar":""},{"name":"Illeana Douglas","avatar":""},{"name":"Fred Thompson","avatar":""},{"name":"Zully Montero","avatar":""},{"name":"Craig Henne","avatar":""},{"name":"Forest Burton","avatar":""},{"name":"Edgar Allan Poe IV","avatar":""},{"name":"Rod Ball","avatar":""},{"name":"W. Paul Bodie","avatar":""},{"name":"Joel Kolker","avatar":""},{"name":"Ant","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cape Fear - il Promontorio della Paura","Cabo do Medo","Cape Fear - A rettegés foka","Cabo de miedo","El Cabo del Miedo","Нос Страх","Les nerfs à vif","To akrotiri tou fovou","Rt straha","Przyląde