INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('frankie-va-johnny', 'Frankie Và Johnny', 'Frankie And Johnny', 'https://phimimg.com/upload/vod/20250618-1/a8d0ec6542b2c4b6950c9a7b2a67506d.jpg', 'https://phimimg.com/upload/vod/20250618-1/2579eab2608cbf7b1fd00162ca70fb84.jpg', '<p>Khi Johnny được thả khỏi tù vì tội làm giả giấy tờ, anh nhanh chóng tìm được việc làm đầu bếp tại một quán ăn nhỏ ở New York. Sau một cuộc tình ngắn ngủi với cô phục vụ bàn tên Cora, anh bắt đầu có cảm tình với Frankie — bạn thân và cũng là đồng nghiệp của Cora. Ban đầu Frankie khá dè dặt trước sự theo đuổi của Johnny, nhưng cuối cùng cô cũng mở lòng sau khi người bạn thân nhất của mình, Tim, thuyết phục cô cho Johnny một cơ hội.</p>', 'Full', 1, 'single', 'completed', 10, 1991, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Al Pacino","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Héctor Elizondo","avatar":""},{"name":"Nathan Lane","avatar":""},{"name":"Jane Morris","avatar":""},{"name":"Kate Nelligan","avatar":""},{"name":"Greg Lewis","avatar":""},{"name":"Al Fann","avatar":""},{"name":"Glenn Plummer","avatar":""},{"name":"Sean O''Bryan","avatar":""},{"name":"Fernando López","avatar":""},{"name":"Ele Keats","avatar":""},{"name":"Phil Leeds","avatar":""},{"name":"K Callan","avatar":""},{"name":"Shannon Wilcox","avatar":""},{"name":"Harvey Miller","avatar":""},{"name":"Tim Hopper","avatar":""},{"name":"Robert Ball","avatar":""},{"name":"Terri S","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]',