INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-trai-chi-di-2-tuc-tap-ngu-thong-than', 'Liêu Trai Chí Dị 2: Tục Tập Ngũ Thông Thần', 'Erotic Ghost Story II', 'https://phimimg.com/upload/vod/20250530-1/bec16e9332242c29a815ebc71735226e.jpg', 'https://phimimg.com/upload/vod/20250530-1/828a88a6cbbd8fa8cdfa34a2c5135464.jpg', '<p>Phim nối tiếp câu chuyện sau khi Ngũ Thông Thần “làm thịt” ba cô hồ ly ở phần 1 và bị một đạo tiên tiêu diệt. Nhưng Ngũ Thông Thần của ma giới tái sinh và rơi vào lưới tình của một cô gái tên là Tiểu Yến.</p>', 'Full', 1, 'single', 'completed', 12, 1991, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Charine Chan Ka-Ling","avatar":""},{"name":"Kwok Yiu-Wah","avatar":""},{"name":"Chik King-Man","avatar":""},{"name":"Sayuri Ichijo","avatar":""},{"name":"Tsang Siu-Yin","avatar":""},{"name":"Amy Yip Chi-Mei","avatar":""},{"name":"Man Siu","avatar":""},{"name":"Wong Woon-Lok","avatar":""},{"name":"Andy Kwong Ting-Wo","avatar":""},{"name":"Naomi Hagio","avatar":""},{"name":"Wong Mei-Guen","avatar":""},{"name":"Lui Lai-Si","avatar":""},{"name":"Hui Sze-Man","avatar":""},{"name":"Chow Chi-Hung","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Erotic Ghost Story 2","Erotic Ghost Story II","요제연담 2: 오통신","聊斋艳谭续集五通神","真説エロティック・ゴースト・ストーリー／覇王ウーチュンの逆襲","聊斋艳谭之五通神","聊斋艳谭2：五通神","聊齋艷譚續集 五通神"]', 1784690324543);
