INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tung-hoanh-tu-hai', 'Tung Hoành Tứ Hải', 'Once A Thief', 'https://phimimg.com/upload/vod/20250523-1/4c87ca3d96329517db2546b247b697d7.jpg', 'https://phimimg.com/upload/vod/20250523-1/1bfb160a6bbc3da59ccc01a665b94a75.jpg', '<p>Joe, Jim và Sherry là những đứa trẻ mồ côi lớn lên dưới sự nuôi dưỡng và dạy dỗ của siêu trộm Chow. Khi trưởng thành, cả ba lại tiếp nối con đường làm đạo tặc: lao vào tìm kiếm, đánh cắp những bức tranh quý hiếm. Theo một đơn hàng “đặc biệt” của một trùm buôn tranh, Joe và Jim phải đột nhập vào tòa lâu đài bí mật ở Bờ biển Ngà được bảo vệ nghiêm ngặt với hệ thống báo động hiện đại đánh cắp một bức tranh quý.Thế nhưng, sự việc lần này đã không trót lọt khi cả hai vừa thoát ra ngoài. Joe bị giết còn Jim may mắn thoát chết.</p>', 'Full', 1, 'single', 'completed', 12, 1991, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Nhuận Phát","avatar":""},{"name":"Trương Quốc Vinh","avatar":""},{"name":"Chu Giang","avatar":""},{"name":"Chung Sở Hồng","avatar":""},{"name":"Tăng Giang","avatar":""},{"name":"John Woo","avatar":""},{"name":"Hồ Đại Vi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Once a Thief","Zong heng si hai","Rajadas de Fogo","Reto a la ley","Kerran varas, aina varas","Les associés","Killer Target","Un ladrón es siempre un ladrón","縱橫四海","Chung hang sei hoi","Вор в законе","종횡사해","狼たちの絆","Tung Hoành Tứ Hải","纵横四海"]', 1784