INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-o-xu-so-nghin-le-mot-dem', 'Doraemon: Nobita Ở Xứ Sở Nghìn Lẻ Một Đêm', 'Doraemon: Nobita''s Dorabian Nights', 'https://phimimg.com/upload/vod/20250521-1/606e40a4ac0e41fd93cb60ddfffa24d7.jpg', 'https://phimimg.com/upload/vod/20250521-1/f2d88cd667741b3e3ed02425bd10f6a4.jpg', '<p>Với bảo bối &quot;Đôi giày trong truyện tranh&quot; của mình, Doraemon cùng Nobita có thể đi vào thế giới các quyển truyện khác nhau. Nobita yêu cầu Doraemon cho phép cậu chia sẻ bảo bối này với Shizuka và Doraemon đồng ý.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 1991, 'Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Noriko Ohara","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Doraemon: Las mil y una aventiras","Nobita''s Dorabian Nights","Doraemon Nobita no Dorabian Naito","哆啦A夢：大雄的天方夜譚","도라에몽: 노비타와 도라비안 나이트","哆啦A梦：大雄的天方夜谭","大雄的一千零一夜","Doraemon the Movie: Nobita''s Dorabian Nights","ドラえもん のび太のドラビアンナイト","のび太のドラビアンナイト","도라에몽: 진구의 도라비안 나이트","哆啦A梦：大雄的阿拉伯之夜","映画ドラえもん のび太のドラビアンナイト"]', 1784690324543);
