INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-son-hiep-khach', 'Tây Sơn Hiệp Khách', 'Tay Son Swordsman', 'https://phimimg.com/upload/vod/20250406-1/ce23bdd469a3bfff99bdb1a08522d989.jpg', 'https://phimimg.com/upload/vod/20250406-1/0acd1231ed074713a5482a7e256f5f6b.jpg', '<p>&quot;Tây Sơn Hiệp Khách&quot; được chuyển thể từ tiểu thuyết võ thuật &quot;Ngọc Trản Thần Công&quot; năm 1990 của Lê Hoàng Khải và là một trong những phim cổ trang đầu tiên của điện ảnh Việt Nam, gồm hai phần: Tây Sơn Hiệp Khách và Ngọc Trản Thần Công. Trong phim vận dụng khá nhiều yếu tố của võ Bình Định, tiêu biểu là bài quyền &quot;Ngọc Trản Ngân Đài&quot;.</p>', 'Full', 1, 'single', 'completed', 10, 1991, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lý Hùng","avatar":""},{"name":"Diễm Hương","avatar":""},{"name":"Lê Tuấn Anh","avatar":""},{"name":"Việt Trinh","avatar":""},{"name":"Ngọc Hiệp","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324543);
