INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-gia-toc', 'Đại Gia Tộc', 'Big Family', 'https://phimimg.com/upload/vod/20250324-1/fcf2afcbd42ff228fab5a30f773f2b28.jpg', 'https://phimimg.com/upload/vod/20250324-1/bb7e1c82c93689b61f271716ace918e7.jpg', '<p>Là một trong những thể loại rất thành công của TVB suốt từ những năm đầu thập lập đài. Đề tài gia đình được sử dụng một cách thường xuyên và luôn có một lượng người xem ổn định với nhiều độ tuổi, thành phần khác nhau nhờ vào cốt truyện dễ hiểu, đặc biệt là những phim đề cập tới gia tộc mà minh chứng chính là Đại Gia Tộc của đạo diễn nổi tiếng Lý Chiêm Thắng được ra mắt vào năm 1991. Phim không chỉ được đánh giá cao về nội dung, sự kịch tính ngày càng tăng về những tập sau mà còn xuất sắc về mặt diễn xuất khi quy tụ dàn diễn viên cực chất lượng của nhà đài tại thời điểm đó.Nội dung của phim Đại Gia Tộc bắt đầu từ việc tranh giành tài sản Vĩnh Nghiệp của 2 cha con Tưởng Văn Sơn, từ đó mà những mối bất hòa bắt đầu nảy sinh giữa 2 người. Thực tế, con trai Văn Sơn là Tưởng Tiến, người đã theo mẹ đến Mã Lai ngay từ khi còn nằm trong bụng nhưng khi lớn lên thì chú Kiệt của Tiến gọi về làm trong Vĩnh Nghiệp.Vốn dĩ mọi chuyện không có gì gọi là nghiêm trọng nếu như không có sự xuất hiện của Tiền Huệ Châu, người đã đứng ra tiếp quản gia đình, từ đó gây ra không ít việc khó dễ để rồi hậu quả là làm cho Kiệt phải chết, thậm chí tồi tệ hơn, con trai của bà ta – Khang, là người thay thế chức vụ của Kiệt, những biến cố trong Đại Gia Tộc nhà họ Tưởng ngày càng lên đến đỉnh điểm…</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 1991, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Alex Man Chi-Leung","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Tien Niu","avatar":""},{"name":"Samantha Chuk Man-Kwan","avatar":""},{"name":"Wing Lam","avatar":""},{"name":"Elizabeth Lee Mei-Fung","avatar":""},{"name":"Canti Lau Sek-Ming","avatar":""},{"name":"Paul Chu Kong","avatar":""},{"name":"Benz Hui Siu-Hung","avatar":""},{"name":"Wayne Lai Yiu-Cheung","avatar":""},{"name":"Kwan Hoi-San","avatar":""},{"name":"Teresa Ha Ping","avatar":""},{"name":"Alice Fung So-Bor","avatar":""},{"name":"Cutie Mui Siu-Wai","avatar":""},{"name":"Kong Nga","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["大家族"]', 1784690324543);
