INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-gia-toc', 'Đại Gia Tộc', 'Big Family', 'đại gia tộc big family alex man chi-leung kenneth tsang tien niu samantha chuk man-kwan wing lam elizabeth lee mei-fung canti lau sek-ming paul chu kong benz hui siu-hung wayne lai yiu-cheung kwan hoi-san teresa ha ping alice fung so-bor cutie mui siu-wai kong nga 大家族', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-kiem-cuong-sa', 'Nộ Kiếm Cuồng Sa', 'The Sword of Conquest', 'https://phimimg.com/upload/vod/20250318-1/1ae8bed679ba728961a0029db6d1671d.jpg', 'https://phimimg.com/upload/vod/20250318-1/8a983b65c72649528b6d04537b101992.jpg', '<p>Tiết Độ Sứ trấn thủ Hà Tây - Hoắc Chánh Oai vì muốn xây tường thành nhanh chóng gây nên bao sóng gió. Hoàng thượng phái Thiên Hạ Đệ Nhất Bảo Thủ - Hồng Thiên Dậu đến giúp sức, hoàn thành đúng thời hạn. Hồng Thiên Dậu phát hiện Chánh Oai ra lệnh giết các em nhỏ để cúng tế cho việc xây dựng tường thành, bị Quách Chánh Oai hãm hại ngũ mã phanh thây. Chánh Oai đồng thời còn để ý vợ của Hồng Thiên Dậu là Nguyễn Tố Trúc. Vì giữ trong sạch Uyển Tố Trúc nhảy xuống tường thành tự vẫn. 2 đứa con Nhật Phi &amp; Nguyệt Ảnh của Hồng Thiên Dậu nhờ có Ngô Ân tráo đổi. Trển đường tháo chạy, Ngô Ân làm rớt đứa bé gái dọc đường, được Mã Tặc Tiết Bách Xuyên đi ngang qua lượm về nuôi. Đứa bé trai, Ngô Ân đem gửi vào Chùa La Ma nhờ Phổ Thiết Pháp Vương nuôi nấng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 19, 1991, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Eddie Kwan Lai-Kit","avatar":""},{"name":"Kathy Chow Hoi-Mei","avatar":""},{"name":"Rain Lau Yuk-Chui","avatar":""},{"name":"Liza Wong Ming-Chuen","avatar":""},{"name":"Law Kar-Ying","avatar":""},{"name":"Wong Wai","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["怒劍嘯狂沙"]', 1784690324543);
