INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-tinh-hiruko', 'Yêu Tinh Hiruko', 'Hiruko The Goblin', 'https://phimimg.com/upload/vod/20250118-1/512b7ffde1e396c5d3ae5db777ffaeb9.jpg', 'https://phimimg.com/upload/vod/20250118-1/ddf886a5defb2c86fd7376074375c5d4.jpg', '<p>Hiruko the Goblin là một bộ phim kinh dị Nhật Bản năm 1991 do Shinya Tsukamoto đạo diễn và Kenji Sawada đóng vai chính. Nó dựa trên manga của Daijiro Morohoshi.</p>', 'Full', 1, 'single', 'completed', 10, 1991, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kenji Sawada","avatar":""},{"name":"Naoto Takenaka","avatar":""},{"name":"Megumi Ueno","avatar":""},{"name":"Masaki Kudou","avatar":""},{"name":"Hideo Murota","avatar":""},{"name":"Kimiko Yo","avatar":""},{"name":"Ken Mitsuishi","avatar":""},{"name":"Bang-ho Cho","avatar":""},{"name":"Yumi Mitani","avatar":""},{"name":"Chika Asamoto","avatar":""},{"name":"Imari Tsuji","avatar":""},{"name":"Anri Hayashi","avatar":""},{"name":"Mitsue Midorikawa","avatar":""},{"name":"Naoko Shimizu","avatar":""},{"name":"Imari Tsuji","avatar":""},{"name":"Daisuke Yamashita","avatar":""},{"name":"Kimiko Yo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Hiruko the Goblin","Yôkai hantâ: Hiruko","ヒルコ／妖怪ハンター"]', 1784690324544);
