INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-mon-da-yen', 'Hào môn dạ yến', 'The Banquet', 'https://phimimg.com/upload/vod/20250104-1/9717a5d0a3af3b489a1dc8ae32337344.jpg', 'https://phimimg.com/upload/vod/20250104-1/cfde07c3d715233f86d6d7147015c0e9.jpg', '<p>Nhà phát triển Tsang Siu-Chi và người đại diện của ông đã mua hai trong số bốn bất động sản. Nhà phát triển đối thủ, Boss Hung. Cả hai đều đặt mục tiêu mua cả bốn bất động sản để họ có thể phá bỏ và xây dựng khách sạn.</p>', 'Full', 1, 'single', 'completed', 9, 1991, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Eric Tsang Chi-Wai","avatar":""},{"name":"Carol Cheng","avatar":""},{"name":"Richard Ng Yiu-Hon","avatar":""},{"name":"Sammo Hung Kam-Bo","avatar":""},{"name":"Jacky Cheung Hok-Yau","avatar":""},{"name":"Tony Leung Ka-Fai","avatar":""},{"name":"Rosamund Kwan Chi-Lam","avatar":""},{"name":"George Lam Chi-Cheung","avatar":""},{"name":"Tony Leung Chiu-Wai","avatar":""},{"name":"John Shum Kin-Fun","avatar":""},{"name":"Gong Li","avatar":""},{"name":"Stephen Chow Sing-Chi","avatar":""},{"name":"Leon Lai Ming","avatar":""},{"name":"Sally Yeh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["豪门夜宴","豪門夜宴"]', 1784690324544);
