INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-trong-thoi-ky-cuong-loan', 'Tình Yêu Trong Thời Kỳ Cuồng Loạn', 'Sólo con tu pareja', 'https://phimimg.com/upload/vod/20250102-1/6e5c97d8934488b9f70080fda321d18a.jpg', 'https://phimimg.com/upload/vod/20250102-1/958b636a33499dee0cec86ab0610f39c.jpg', '<p>Tomás Tomás là một tay chơi yuppie trẻ tuổi với hàng loạt bạn gái bị bỏ rơi. Nhưng khi Silvia, nạn nhân trong một trong những cuộc phiêu lưu của anh ta, cố gắng trả thù bằng cách gõ &quot;dương tính&quot; vào bài kiểm tra AIDS của mình, Tomás lần đầu tiên trải nghiệm thực tế về tình yêu và cái chết.</p>', 'Full', 1, 'single', 'completed', 29, 1991, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Daniel Giménez Cacho","avatar":""},{"name":"Claudia Ramírez","avatar":""},{"name":"Luis de Icaza","avatar":""},{"name":"Astrid Hadad","avatar":""},{"name":"Dobrina Liubomirova","avatar":""},{"name":"Isabel Benet","avatar":""},{"name":"Luz María Jerez","avatar":""},{"name":"Monserrat Ontiveros","avatar":""},{"name":"Regina Orozco","avatar":""},{"name":"Rodolfo Arias","avatar":""},{"name":"Víctor Carpinteiro","avatar":""},{"name":"Claudette Maillé","avatar":""},{"name":"Ariel López Padilla","avatar":""},{"name":"Mónica Dionne","avatar":""},{"name":"Manuel Sev","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Love in the Time of Hysteria","Only with Your Partner","Тільки з вашим партнером","Sólo con tu pareja"]', 1784690324544);
