INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truc-phu-nhan', 'Trúc Phu Nhân', 'Madame Bamboo', 'https://phimimg.com/upload/vod/20241213-1/107ee83177d1c608be0ed146962c1d0c.jpg', 'https://phimimg.com/upload/vod/20241213-1/124e5edf2dba78d3f0174c4c16e9e44a.jpg', '<p>Trúc Phu Nhân kể về câu chuyện của hai kỹ nữ đang nhớ lại hoàn cảnh đã đưa họ đến lầu xanh. Người phụ nữ đầu tiên bị bán vào lầu xanh sau khi bị phát hiện có những hành động trái luân thường đạo lý. Người phụ nữ thứ hai đã đính hôn với tình yêu đích thực của mình nhưng cha mẹ cô lại hứa hôn với một cậu bé bảy tuổi vì tiền...</p>', 'Full', 1, 'single', 'completed', 9, 1991, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Pal Sinn Lap-man","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhu fu ren","竹夫人"]', 1784690324544);
