INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-vui-ve-5', 'Ma Vui Vẻ 5', 'Happy Ghost V', 'https://phimimg.com/upload/vod/20240930-1/815d4b88328f80729ad5040a68339cb4.jpg', 'https://phimimg.com/upload/vod/20240930-1/88708e056b8510f82c7bd93ea0d10ed5.jpg', '<p>Một câu chuyện ngọt ngào về chú chó của một cô gái trẻ thỏa thuận với Hồn ma Hạnh phúc (Raymond Wong) để trở thành con người trong 44 ngày. Nhưng sau khi những ngày đó qua đi, anh ta phải đi đầu thai.</p>', 'Full', 1, 'single', 'completed', 7, 1991, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Raymond Wong","avatar":""},{"name":"Kris Aquino","avatar":""},{"name":"郭晉安","avatar":""},{"name":"黃光亮","avatar":""},{"name":"Josh","avatar":""},{"name":"黃新","avatar":""},{"name":"So Chung","avatar":""},{"name":"Chui Bo-Fung","avatar":""},{"name":"羅君左","avatar":""},{"name":"James Lai Wing-Keung","avatar":""},{"name":"Dung Wai-Gong","avatar":""},{"name":"Veronica Chan","avatar":""},{"name":"Chan Chi-Fai","avatar":""},{"name":"李忠志","avatar":""},{"name":"林剛","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["开心鬼5","開心鬼上錯身"]', 1784690324544);
