INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-dai-thien-kieu', 'Nhất Đại Thiên Kiều', 'Legend Of A Beauty', 'https://phimimg.com/upload/vod/20240627-1/13bc86ad0e535c7b5c621d0f6e353897.jpg', 'https://phimimg.com/upload/vod/20240627-1/5da67b83fa5c708cb1511282e925607c.jpg', '<p><em>Câu chuyện xảy ra vào đời Đường. Thượng Quan Hồng vì muốn hoàn thành tâm nguyện của phụ thân mà khổ luyện võ công hầu đánh bại cao thủ võ lâm đương thời là Đao Thần và Kiếm Tri, trong một lần ác đấu đã bị Kim Diện Nhân thừa cơ hãm hại. Đệ tử phái Điểm Thương là Diệp Phong có duyên sư đồ với Kiếm Tri nên tận lực truy tầm hung thủ, không để ý đến mối tình thâm của Hồng dành cho mình mà lại có tình ý với Liễu Oanh. Vì muốn cứu nguy cho Phong trong một hiểm cảnh nên Hồng đã thọ thương và ăn nhầm trái Thiên Hương Đậu Khấu và trơi vào trạng thái chết giả. Phong và Oanh đi tìm trái Thiên Hương Đậu Khấu thứ 2 để cứu Hồng, không ngờ chính Oanh cũng bị buộc phải ăn trái Thiên Hương Đậu Khấu. Sau cùng Phong tìm được trái Thiên Hương Đậu Khấu thứ 3. Một bên nặng ơn cứu mạng, một bên lại nặng vì tình. Diệp Phong nên đưa linh dược cho nàng nào?</em></p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 19, 1991, 'Lồng Tiếng', 'HD', 'Singapore', 0, '[{"name":"Mễ Tuyết","avatar":""},{"name":"Trần Bích Phụng","avatar":""},{"name":"Trần Lợi Bình","avatar":""},{"name":"Trần Thiên Văn","avatar":""},{"name":"Chu Nhiệm","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324544);
