INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-huyet-nam-nhi', 'Thiết Huyết Nam Nhi', 'Blood And Iron', 'https://phimimg.com/upload/vod/20240622-1/b21580b21b24e057f7c2bc0607433aed.jpg', 'https://phimimg.com/upload/vod/20240622-1/542838c09ae4d6b3aa858d5bea88aed0.jpg', '<p><em>Giang Gia Minh và Thạch Tử Duy là cảnh sát Hong Kong, trong thời gian hai người đi điều tra vụ án tại Trung Quốc họ đã làm quen với cảnh sát địa phương là Cao Kiến Trung. Sau đó Trung đột nhiên vượt biên xuống Hong Kong khiến Minh và Duy thấy ngạc nhiên. Thật ra Trung đã làm tay trong nằm vùng trong tổ chức phạm tội và được tay sai của tổ chức là Vương Quốc Trụ tin cậy, Trung có cô bạn gái là Tố Lan. Về sau mọi người liên thủ trừ khử kẻ cầm đầu trong tổ chức...</em></p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 8, 1991, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Lưu Tích Minh","avatar":""},{"name":"Quan Lễ Kiệt","avatar":""},{"name":"Âu Thoại Vỹ","avatar":""},{"name":"Lương Bội Linh","avatar":""},{"name":"Huỳnh Thu Sinh","avatar":""},{"name":"Dương Mỹ Nghi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324544);
