INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xo-so', 'Xổ Số', 'The Raffle / La Riffa', 'https://phimimg.com/upload/vod/20230925-1/9cfed9e21b4c4b4dfdd68503e26a33ae.jpg', 'https://phimimg.com/upload/vod/20230925-1/c0593f6c05688eaf5c054d4be8a4a8a7.jpg', '<p>Francesca, một người phụ nữ vô cùng xinh đẹp, sau cái chết của chồng mình phát hiện ra sự không chung thủy và số nợ khổng lồ mà anh ta để lại. Cesare là bạn thân nhất của Francesca, anh ấy là luật sư. Theo lời khuyên của anh, Francesca bắt đầu bán tất cả hàng hóa của mình, như ngôi nhà, đồ trang sức, lông thú và cuối cùng là du thuyền. Bằng cách này, cô ấy có thể sống sót trong thời gian còn lại của năm, nhưng không có triển vọng cho tương lai và mọi nỗ lực xin việc đều thất bại. Cuối cùng, cô quyết định tổ chức một cuộc xổ số mà giải thưởng là của cô.</p>', 'Full', 1, 'single', 'completed', 17, 1991, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Monica Bellucci","avatar":""},{"name":"Giulio Scarpati","avatar":""},{"name":"Massimo Ghini","avatar":""},{"name":"Elena Cantarone","avatar":""},{"name":"Carla Cassola","avatar":""},{"name":"Sandra Collodel","avatar":""},{"name":"Paolo Busiri Vinci","avatar":""},{"name":"Paolo De Vita","avatar":""},{"name":"Roberto Della Casa","avatar":""},{"name":"Christina Engelhardt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324544);
