INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-cua-bill-va-ted', 'Hành Trình Của Bill Và Ted', 'Bill & Ted''s Bogus Journey', 'https://phimimg.com/upload/vod/20240803-1/c8300e8cea370ccbcf11732b8a87a2f9.jpg', 'https://phimimg.com/upload/vod/20240803-1/85b2f7acc04694a62f2bf302bf2d8046.jpg', '<p>Bill &amp; Ted’s Bogus Journey 1991 là phần tiếp theo của bộ phim Bill &amp; Ted’s Excellent Adventure. Trong phần này, hai nhân vật chính, Bill và Ted, phải đối mặt với những phiên bản ác độc của chính họ từ tương lai. Họ bị giết và phải tìm cách trở lại thế giới sống để ngăn chặn kế hoạch của những kẻ ác độc. Phim có nhiều yếu tố hài hước và phiêu lưu, với sự tham gia của các diễn viên Keanu Reeves (Ted) và Alex Winter (Bill). Nếu bạn thích những bộ phim hài hước và kỳ quặc, đây có thể là một lựa chọn thú vị</p>', 'Full', 1, 'single', 'completed', 8, 1991, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Alex Winter","avatar":""},{"name":"William Sadler","avatar":""},{"name":"Joss Ackland","avatar":""},{"name":"Pam Grier","avatar":""},{"name":"George Carlin","avatar":""},{"name":"Amy Stoch","avatar":""},{"name":"Jim Martin","avatar":""},{"name":"Hal Landon Jr.","avatar":""},{"name":"Annette Azcuy","avatar":""},{"name":"Sarah Trigger","avatar":""},{"name":"Chelcie Ross","avatar":""},{"name":"Taj Mahal","avatar":""},{"name":"Robert Noble","avatar":""},{"name":"Hal Landon Sr.","avatar":""},{"name":"Eleni Kelakos","avatar":""},{"name":"Roy Brocksmith","avatar":""},{"name":"J. Patrick McNama","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89