INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-do-nhi-den-1', 'Nhất Đỏ Nhì Đen 1', 'Who''s The Winner', 'https://phimimg.com/upload/vod/20240609-1/a3f432be31dc8e053c045f18588fca89.jpg', 'https://phimimg.com/upload/vod/20240609-1/5b6e70067525a4ebdb85b568bf683b47.jpg', '<p><em>Thạch Chí Khang (Trần Đình Oai) là một thanh niên nhiệt tình trung hậu, làm phụ bếp ở sòng bài, nhờ dịp may đã thấy nhị đại cao thủ Phương Chân (Cao Hùng) và Nhiếp Vạn Long (Tần Phối) đánh bài với nhau, bắt đầu có hứng thú với bài bạc, có một hôm một thanh niên tên Bá Kỳ (Lữ Tụng Hiền) tới sòng bài và ăn hết các tay bịp từ Indonesia tới, gây náo động cả sòng bài, vài tìm cách giết Long để trả thù cho Cha, nhưng đã thất bại và được sự giúp đỡ của Khang và thoát khỏi vòng tay của Long, hai người trở thành bạn thân, trong một dịp may Khang được Ton Nhất Phong (Trương Tinh) dạy nghề bài bạc, Khang và Kỳ hùn hạp mở sòng bài, mục đích để ảnh hưởng sòng bài của Long, nên Long cho người phá và đốt sòng bài làm cho Kỳ chết cháy, cuối cùng hai bên dùng bài để làm nơi quyết đấu, kết quả Khang tìm được yếu điểm của Long, đánh một vố chí tử và Khang trở thành Vua cờ bạc</em></p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 12, 1991, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Trần Đình Oai","avatar":""},{"name":"Lữ Tụng Hiền","avatar":""},{"name":"Trương Gia Huy","avatar":""},{"name":"Vạn Ỷ Văn","avatar":""},{"name":"Ngô Ỷ Lợi","avatar":""},{"name":"Tần Bái","avatar":""},{"name":"Cao Hùng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324544);
