INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-cooler-phuc-han', 'Bảy Viên Ngọc Rồng: Cooler Phục Hận', 'Dragon Ball Z: Cooler''s Revenge', 'https://phimimg.com/upload/vod/20231023-1/fffc3482c19285040335e7ef036efd91.jpg', 'https://phimimg.com/upload/vod/20231023-1/a12e2e6f787227390d790772c999a276.jpg', '<p>Coolers, anh trai Freiza đến trái đất để trả thù cho em mình và cũng nhân tiện thực hiện âm mưu xâm chiếm trái đất. Trong tập này, Songoku sẽ biến thành siêu xay da cấp 2 với sức mạnh vượt trội !</p>', 'Full', 1, 'hoathinh', 'completed', 14, 1991, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masako Nozawa","avatar":""},{"name":"Toshio Furukawa","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Naoki Tatsuta","avatar":""},{"name":"Naoko Watanabe","avatar":""},{"name":"Kōhei Miyauchi","avatar":""},{"name":"Ichiro Nagai","avatar":""},{"name":"Ryusei Nakao","avatar":""},{"name":"Show Hayami","avatar":""},{"name":"Masato Hirano","avatar":""},{"name":"Masaharu Sato","avatar":""},{"name":"Joji Yanami","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324544);
