INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gai-lang-choi', 'Gái Làng Chơi', 'Whore', 'https://phimimg.com/upload/vod/20240617-1/54768f7b49079366303c812b4e32de25.jpg', 'https://phimimg.com/upload/vod/20240617-1/46318ad99e97fbea05b6f7df95cd4a83.jpg', '<p>Một đêm trong cuộc đời của một cô gái điếm chu đáo là nền tảng cho bức chân dung của Ken Russell về nghề lâu đời nhất thế giới.</p>', 'Full', 1, 'single', 'completed', 9, 1991, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Theresa Russell","avatar":""},{"name":"Benjamin Mouton","avatar":""},{"name":"Antonio Fargas","avatar":""},{"name":"Elizabeth Morehead","avatar":""},{"name":"Daniel Quinn","avatar":""},{"name":"Sanjay Chandani","avatar":""},{"name":"Jason Saucier","avatar":""},{"name":"Michael Crabtree","avatar":""},{"name":"Jered Barclay","avatar":""},{"name":"Doug MacHugh","avatar":""},{"name":"Amanda Goodwin","avatar":""},{"name":"Frank Smith","avatar":""},{"name":"Jason Kristofer","avatar":""},{"name":"Robert O''Reilly","avatar":""},{"name":"Ginger Lynn Allen","avatar":""},{"name":"Charl","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324544);
