INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-o-tieu-dong-kinh', 'Trận Chiến Ở Tiểu Đông Kinh', 'Showdown In Little Tokyo', 'https://phimimg.com/upload/vod/20240228-1/eac644548ce10db07bc15adee1983896.jpg', 'https://phimimg.com/upload/vod/20240228-1/effce451ec36cad76cfa8c253168e3cd.jpg', '<p>Là một người Mỹ gốc Nhật, Chris Kenner là cảnh sát được giao nhiệm vụ phụ trách khu Little Tokyo của Los Angeles. Kenner hợp tác với Johnny Murata, một người Mỹ gốc Nhật không còn liên lạc với cội nguồn của mình. Bất chấp sự khác biệt của họ, cả hai người đàn ông đều xuất sắc về võ thuật và sử dụng các kỹ năng đáng gờm của mình khi đối đầu với Yoshida, một tay buôn ma túy yakuza độc ác có quan hệ với quá khứ của Kenner.</p>', 'Full', 1, 'single', 'completed', 9, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Brandon Lee","avatar":""},{"name":"Cary-Hiroyuki Tagawa","avatar":""},{"name":"Tia Carrere","avatar":""},{"name":"Philip Tan","avatar":""},{"name":"Rodney Kageyama","avatar":""},{"name":"Ernie Lively","avatar":""},{"name":"Renee Griffin","avatar":""},{"name":"Reid Asato","avatar":""},{"name":"Takayo Fischer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324544);
