INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dying-young', 'Dying Young', 'Dying Young', 'https://phimimg.com/upload/vod/20240228-1/cac378ff33bcfa9f2366009f244230cc.jpg', 'https://phimimg.com/upload/vod/20240228-1/eed3e51a716c8069d5fcc33815c8c864.jpg', '<p>Sau khi phát hiện ra bạn trai đã phản bội mình, Hilary ONeil đang tìm kiếm một khởi đầu mới và một công việc mới. Cô bắt đầu làm y tá riêng cho một chàng trai trẻ mắc bệnh ung thư máu. Dần dần, họ yêu nhau nhưng họ luôn biết tình yêu của mình không thể kéo dài vì định mệnh anh sẽ phải chết.</p>', 'Full', 1, 'single', 'completed', 10, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Julia Roberts","avatar":""},{"name":"Campbell Scott","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Colleen Dewhurst","avatar":""},{"name":"David Selby","avatar":""},{"name":"Ellen Burstyn","avatar":""},{"name":"Dion Anderson","avatar":""},{"name":"George Martin","avatar":""},{"name":"A.J. Johnson","avatar":""},{"name":"Daniel Beer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324544);
