INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bill-teds-bogus-journey', 'Bill & Ted''s Bogus Journey', 'Bill & Ted''s Bogus Journey', 'https://phimimg.com/upload/vod/20240228-1/bb0b668613d374c24990edb63491aff1.jpg', 'https://phimimg.com/upload/vod/20240228-1/c0933f755ac8222316a3cd8dbf322425.jpg', '<p>Những người lười biếng đáng yêu Bill và Ted một lần nữa bị cuốn vào một cuộc phiêu lưu kỳ ảo khi De Nomolos, một nhân vật phản diện đến từ tương lai, gửi các bản sao robot độc ác của hai chàng trai để tiêu diệt và thay thế họ. Người máy đôi thực sự đã thành công trong việc giết chết Bill và Ted, nhưng cả hai vẫn quyết tâm thoát khỏi thế giới bên kia, thách thức Thần chết trong một loạt trò chơi để trở về vùng đất của người sống.</p>', 'Full', 1, 'single', 'completed', 12, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keanu Reeves","avatar":""},{"name":"Alex Winter","avatar":""},{"name":"William Sadler","avatar":""},{"name":"Joss Ackland","avatar":""},{"name":"Pam Grier","avatar":""},{"name":"George Carlin","avatar":""},{"name":"Amy Stoch","avatar":""},{"name":"Jim Martin","avatar":""},{"name":"Hal Landon Jr.","avatar":""},{"name":"Annette Azcuy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324544);
