INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-pup-named-scoobydoo-phan-4', 'A Pup Named Scooby-Doo (Phần 4)', 'A Pup Named Scooby-Doo (Season 4)', 'https://phimimg.com/upload/vod/20240229-1/2413569fb71ab59426f4650d346df1e1.jpg', 'https://phimimg.com/upload/vod/20240229-1/c91558884b1c3254c14a376340111e31.jpg', '<p>Con chó có trái tim gà được yêu thích nhất thế giới, khi còn là một con chó con? Đúng rồi! Và băng đảng cũ đã trở lại với anh ta. Shaggy, Daphne, Velma và Freddy đều ở đây với tư cách là những đứa trẻ nghịch ngợm — nghịch ngợm, giải quyết những bí ẩn dành cho trẻ em và đụng độ với ma cà rồng, ma và yêu tinh.</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 11, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Don Messick","avatar":""},{"name":"Casey Kasem","avatar":""},{"name":"Carl Steven","avatar":""},{"name":"Kellie Martin","avatar":""},{"name":"Christina Lange","avatar":""},{"name":"Scott Menville","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324544);
