INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khi-hoan-hao', 'Vũ Khí Hoàn Hảo', 'The Perfect Weapon', 'https://phimimg.com/upload/vod/20240228-1/bea1e20ad6b3c40a25173a8c4a519260.jpg', 'https://phimimg.com/upload/vod/20240228-1/f60ee2d65417ae8559fc90079c278ffb.jpg', '<p>Jeff là một thanh niên khó trị và được cha đăng ký vào học trường võ karate. Một người bạn thân của cậu ở trường sau đó đã bị giết hại. Cậu ấy phải sử dụng mọi kỹ năng của mình để trả thù...</p>', 'Full', 1, 'single', 'completed', 21, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Speakman","avatar":""},{"name":"John Dye","avatar":""},{"name":"Mako","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324544);
