INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cuoc-phieu-luu-cua-tintin-phan-1', 'Những Cuộc Phiêu Lưu Của Tintin (Phần 1)', 'The Adventures Of Tintin (Season 1)', 'https://phimimg.com/upload/vod/20240220-1/e09e9eabd30ccf95876592ab4a7ed862.jpg', 'https://phimimg.com/upload/vod/20240220-1/f56b3e672f5a0a0026094796d621766b.jpg', '<p>The Adventures Of Tintin - Season 1 là series phim được chuyển thể cùng tên do nhà văn người Bỉ Hergé sáng tác với tên gốc là Les Adventuré de Tintin. Anh chàng Tintin - chàng phóng viên tài năng và hài hước có chỏm tóc vàng hoe cùng chú cún trung thành Milou đã là một hình tượng rất thân thuộc đối với trẻ em cũng như nhiều người lớn trên toàn thế giới. Những câu chuyện về Tintin đã vượt qua biên giới, vượt qua mọi thời đại: hàng loạt bản dựng khác nhau từ phim hoạt hình cho tới nhạc kịch và trên màn ảnh rộng. Mỗi câu chuyện về chàng phóng viên Tintin đều mang đậm triết lý sống “chính nghĩa thắng gian tà”, vượt qua trở ngại bằng trí tuệ. Ngoài ra, Tintin còn được yêu thích vì biết coi trọng tình bạn, giữ lời hứa, giúp đỡ kẻ yếu, đấu tranh với tội phạm, trí dũng song toàn nhưng lại rất bình dị!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 16, 1991, 'Lồng Tiếng', 'HD', 'Pháp', 0, '[{"name":"Colin O''Meara","avatar":""},{"name":"Thierry Wermuth","avatar":""},{"name":"Christian Pellissier","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324544);
