INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-so-phan-veronique', 'Hai Số Phận Veronique', 'La Double Vie De Véronique', 'https://phimimg.com/upload/vod/20240219-1/47d94b1ea358bb05f16cb64af58c25c3.jpg', 'https://phimimg.com/upload/vod/20240219-1/603f400a01146ef746e24a2c04318d9e.jpg', '<p>Véronique là một phụ nữ Pháp trẻ đẹp khao khát trở thành một ca sĩ nổi tiếng; Weronika sống ở Ba Lan, có mục tiêu nghề nghiệp tương tự và trông giống Véronique, mặc dù hai người không có quan hệ họ hàng với nhau. Bộ phim theo chân cả hai người phụ nữ khi họ phải đối mặt với những thăng trầm trong cuộc sống cá nhân, Véronique bắt đầu một mối tình lãng mạn khác thường với Alexandre Fabbri, một nghệ sĩ múa rối có thể giúp cô giải quyết các vấn đề tồn tại của mình.</p>', 'Full', 1, 'single', 'completed', 11, 1991, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Irène Jacob","avatar":""},{"name":"Halina Gryglaszewska","avatar":""},{"name":"Philippe Volter","avatar":""},{"name":"Guillaume de Tonquédec","avatar":""},{"name":"Kalina Jędrusik","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324544);
