INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('choi-hoac-chet-1991', 'Chơi Hoặc Chết', 'Do Or Die', 'https://phimimg.com/upload/vod/20240219-1/063f0d5d1b1f796ef94e8054b1970a8c.jpg', 'https://phimimg.com/upload/vod/20240219-1/0ecc04ce98ef56dc67272fa4a16ce88f.jpg', '<p>Trùm tội phạm châu Á Kaneshiro bắt được hai đặc vụ ngầm khiêu gợi của liên bang, Donna và Nicole. Nhưng thay vì thanh lý chúng, anh lại để bộ đôi ngực khủng bắt đầu bằng một trò chơi mèo vờn chuột chết chóc có sự tham gia của sáu đội sát thủ khác. Hành động nóng bỏng đưa họ từ Hawaii đến Las Vegas và Louisiana.</p>', 'Full', 1, 'single', 'completed', 10, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pat Morita","avatar":""},{"name":"Erik Estrada","avatar":""},{"name":"Dona Speir","avatar":""},{"name":"Roberta Vasquez","avatar":""},{"name":"Bruce Penhall","avatar":""},{"name":"Cynthia Brimhall","avatar":""},{"name":"William Bumiller","avatar":""},{"name":"Michael J. Shane","avatar":""},{"name":"Pandora Peaks","avatar":""},{"name":"Carolyn Liu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324544);
