INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-vuong-cu-dam-mau', 'Lực Vương: Cú Đấm Máu', 'The Story Of Ricky', 'https://phimimg.com/upload/vod/20240128-1/2d018092d9067bddcb2e6f2c95cfb17e.jpg', 'https://phimimg.com/upload/vod/20240128-1/2059e98c3cfed7df73224166a8e7b8a4.jpg', '<p>Lực Vương, một thanh niên thần bí, cố tình ở lại trong ngục để tìm một bí mật. Một mình dẹp tan các thế lực tà ác, hắc ám trong trại giam tư nhân thời cận tương lai ở Nhật Bản. Mang dấu ấn huyền bí Lục Vong Tinh trên tay, 5 viên đạn cắm trong người. Lực Vương là người có thân thế rất đặc biệt, sức mạnh siêu phàm, nội công cao cường. Sau khi ra ngục, lại gây một trận phong vân đi tìm sư phụ và hiểu được thân thế kinh hồn...</p>', 'Full', 1, 'single', 'completed', 11, 1991, 'Thuyết Minh', 'SD', 'Hồng Kông', 0, '[{"name":"Phàn Thiếu Hoàng","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324544);
