INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-thuong-dang', 'Chiến Binh Thượng Đẳng', 'Hot Shots!', 'https://phimimg.com/upload/vod/20240122-1/ddb27755febfeaab8cf08ecc9f5856a4.jpg', 'https://phimimg.com/upload/vod/20240122-1/0ccff2b38101325c450f1b1aee627981.jpg', '<p>Topper Harley, tay phi công tài năng nhưng tâm lý đầy bất ổn, được gọi lại phục vụ trên tàu chiến SS Essess. Nhiệm vụ lần này của chàng là phá kế hoạch khủng bố bằng nguyên tử của độc tài Saddam Hussein. Ăn theo phim bom tấn Top Gun, có thể xem Hot Shots! thuộc một trong những phim chế hay nhất thế kỷ 20!</p>', 'Full', 1, 'single', 'completed', 11, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlie Sheen","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Valeria Golino","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324544);
