INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('den-long-do-treo-cao', 'Đèn Lồng Đỏ Treo Cao', 'Raise the Red Lantern', 'https://phimimg.com/upload/vod/20231016-1/1f2cf73af8d7eab036c1b446b7f2ee6d.jpg', 'https://phimimg.com/upload/vod/20231016-1/10523d36ace2bd0656eb1d8fe7568604.jpg', '<p>Mới 19 tuổi cô đã phải về làm vợ lẽ cho gia đình họ Trần với sự ép buộc của dì gẻ. Nếu gia đình cô không làm ăn thất bại thì cô cũng được coi là một tiểu thư con nhà giàu danh giá. Nhưng giờ đây đời cô coi như hết, phải làm vợ lẽ cho một ông già mặc dù ông ta rất giàu có.</p>', 'Full', 1, 'single', 'completed', 11, 1991, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gong Li","avatar":""},{"name":"Ma Jingwu","avatar":""},{"name":"He Saifei","avatar":""},{"name":"Cao Cuifen","avatar":""},{"name":"Kong Lin","avatar":""},{"name":"Shuyuan Jin","avatar":""},{"name":"Chu Xiao","avatar":""},{"name":"Ding Weimin","avatar":""},{"name":"Cao Zengyin","avatar":""},{"name":"Cui Zhi-Gang","avatar":""},{"name":"Espérance Pham Thai Lan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324544);
