INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-eo-bien-xanh', 'Trở Lại Eo Biển Xanh', 'Return To The Blue Lagoon', 'https://phimimg.com/upload/vod/20240104-1/086911ba9d7b63ff152286ea4b692a1f.jpg', 'https://phimimg.com/upload/vod/20240104-1/564a06497c58246b5aa2f7bdda4b462e.jpg', '<p>Trong phần tiếp theo của The Blue Lagoon, đứa con trai mồ côi của cặp tình nhân trong bộ phim gốc bị mắc kẹt trên một hòn đảo với một góa phụ và con gái của bà.</p>', 'Full', 1, 'single', 'completed', 11, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"Brian Krause","avatar":""},{"name":"Lisa Pelikan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324544);
