INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhuc-bo-doan-1', 'Nhục Bồ Đoàn 1', 'Sex and Zen', 'https://phimimg.com/upload/vod/20231020-1/c844d2a88ca89892a9742db26a9615f9.jpg', 'https://phimimg.com/upload/vod/20231020-1/f040c9e6db3273810a074e40f6f4e473.jpg', '<p>Phim kể về một anh chàng tuy đã có vợ nhưng vẫn mơ mộng chuyện đi tằng tịu với vợ người khác để thỏa mãn dục vọng. Nhưng khổ cái là &quot;súng&quot; của anh chàng khá nhỏ, ngay cả chuyện động phòng với cô vợ cũng chả làm cho ra hồn. Hàng không ngon nhưng cái ý tưởng dâm dục kia vẫn không bỏ. Trong một lần tình cờ, anh chàng đã gặp một tay trộm chuyên nghiệp cực giỏi về khinh công và bàn chuyện hợp tác đưa anh ta thâm nhập nhà nào có gái đẹp. Điểm đến của cặp bài trùng này là nhà của một thợ nhuộm vải, anh chàng cực kỳ to khỏe nhưng đối xử với vợ rất tệ. Bằng việc cắt &quot;hàng&quot; của mình thay thế bằng hàng của con ngựa, anh chàng kia đã dụ dỗ được vợ của người thợ nhuộm, không những thế còn tém luôn vợ của một viên quan. Núi này cao còn có núi khác cao hơn. Không ngờ bà vợ của viên quan kia cùng bà chị họ lại dâm dục kinh hoàng với những màn tra tấn quá sức chịu đựng. Mặt khác anh chàng thợ nhuộm sau khi mất vợ đã Tìm ngược lại vợ của anh chàng dâm dê xài &quot;súng ngựa kia&quot;…</p>', 'Full', 1, 'single', 'completed', 24, 1991, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lawrence Ng","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Amy Yip","avatar":""},{"name":"Isabelle Chow Wang","avatar":""},{"name":"Rena Murakami","avatar":""},{"name":"Carrie Ng","avatar":""},{"name":"Lo Lieh","avatar":""},{"name":"Tien Feng","avatar":""},{"name":"Au Wai-Yee","avatar":""},{"name":"Poon Ka Tak","avatar":""},{"name":"Ryoko Shinmura","avatar":""},{"name":"Mari Ayukawa","avatar":""},{"name":"Tang Yat-Lung","avatar":""},{"name":"Lo Duen","avatar":""},{"name":"Peter Ngor Chi-Kwan","avatar":""},{"name":"John Cheung Chan-Sang","avatar":""},{"name":"Fran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '[]', 1784690324544);
