INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-toan-may-man', 'Hoàn Toàn May Mắn', 'Pure Luck', 'https://phimimg.com/upload/vod/20231231-1/6f63c004eb8c5e230c6f4abd11a4f6bf.jpg', 'https://phimimg.com/upload/vod/20231231-1/47a5587c4b3f969e6def5144c8bacddb.jpg', '<p>Con gái của một doanh nhân giàu có đã biến mất ở Mexico và mọi nỗ lực tìm kiếm cô đều không thành công. Một nhà tâm lý học, biết rằng cô gái cực kỳ xui xẻo, đã thuyết phục cha cô cử một trong những nhân viên của ông, một kế toán cực kỳ xui xẻo, đến Mexico để tìm cô. Có lẽ anh ta sẽ gặp may mắn, và sự xui xẻo của anh ta có thể giúp tìm ra cô gái kém may mắn.</p>', 'Full', 1, 'single', 'completed', 12, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Martin Short","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Harry Shearer","avatar":""},{"name":"Sheila Kelley","avatar":""},{"name":"Sam Wanamaker","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324544);
