INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-cua-freddy-con-ac-mong-cuoi-cung', 'Cái Chết Của Freddy: Cơn Ác Mộng Cuối Cùng', 'Freddy''s Dead: The Final Nightmare', 'https://phimimg.com/upload/vod/20231230-1/fe28b1180397cbf1d3cc1c659deaed18.jpg', 'https://phimimg.com/upload/vod/20231230-1/5d9af02c68b3d23822ed9d1dbf0dcc83.jpg', '<p>Ngay khi bạn nghĩ rằng đã an toàn để ngủ, Freddy Krueger trở lại trong phần thứ sáu của bộ phim Ác mộng trên phố Elm, trong vai nhà tâm lý học Maggie Burroughs, bị dày vò bởi những cơn ác mộng tái diễn, gặp một bệnh nhân có cùng giấc mơ kinh hoàng. Cuộc tìm kiếm câu trả lời của họ dẫn đến một ngôi nhà nào đó trên Phố Elm - nơi những cơn ác mộng trở thành hiện thực.</p>', 'Full', 1, 'single', 'completed', 10, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Englund","avatar":""},{"name":"Lisa Zane","avatar":""},{"name":"Shon Greenblatt","avatar":""},{"name":"Lezlie Deane","avatar":""},{"name":"Yaphet Kotto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324544);
