INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinh-thien-long-ho-bao', 'Kinh Thiên Long Hổ Báo', 'Lethal Panther', 'null', 'https://phimimg.com/upload/vod/20231215-1/2a219b84dcfe87719fcb02409fcf5c42.jpg', '<p>Bộ phim Kinh Thiên Long Hổ Báo - Lethal Panther xoay quanh câu chuyện cuộc chiến giành địa bàn giữa các băng đảng trong thế lực ngầm tại Hương cảng, chẳng ai chịu nhường ai, cả hai phía đều sai nữ sát thủ của mình để tiêu diệt thủ lĩnh của đối phương. Liệu ai sẽ giành được phần thắng trong lần tranh đoạt địa bàn hoạt động này?</p>', 'Full', 1, 'single', 'completed', 12, 1991, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Phương Trung Tín","avatar":""},{"name":"Hồ Tuệ Trung","avatar":""},{"name":"Hoàng Doãn Tài","avatar":""},{"name":"Huyền Trí Huệ","avatar":""},{"name":"Lư Huệ Quang","avatar":""},{"name":"Ngô Khải Hoa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324544);
