INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-cua-co-dau-phan-1', 'Bố Của Cô Dâu (Phần 1)', 'Father Of The Bride', 'https://phimimg.com/upload/vod/20231213-1/88271dc3e25c676a82e5838d56f5cde6.jpg', 'https://phimimg.com/upload/vod/20231213-1/85d3128742674646f013fe4ecb7e0d8b.jpg', '<p>George Bank chỉ là môt người đàn ông trung lưu bình thường với cô con gái Annie 21 tuổi sắp sửa cưới 1 người đàn ông thượng lưu, nhưng George không thể tưởng tượng được cuộc sống của ông sẽ ra sao khi thiếu vắng hình bóng con gái. George luôn lo lắng và chưa sẵn sàng chấp nhận sự thật là cô con gái bẻ nhỏ của ông giờ đã thành 1 người phụ nữ, nhưng cuối cùng đám cưới lại được tổ chức bởi 1 người tổ chức đám cưới nước ngoài tại chính ngôi nhà của họ, đến lúc này, Goerge phải cố gắng chấp nhận sự thật là con người ai cũng phải trưởng thành...</p>', 'Full', 1, 'single', 'completed', 11, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Martin","avatar":""},{"name":"Diane Keaton","avatar":""},{"name":"Martin Short","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324544);
