INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-truong-loi-lac-2', 'Thám Trưởng Lôi Lạc 2', 'Lee Rock 2', 'https://phimimg.com/upload/vod/20231213-1/889cdb1fbc759f13719b9e7861b1de39.jpg', 'https://phimimg.com/upload/vod/20231213-1/d230e2b20dd4f72547ccbfc9f3571635.jpg', '<p>Thám Trưởng Lôi Lạc 2 - Lee Rock 2 tiếp tục những câu chuyện mới trong cuộc đời của thám trưởng Lôi Lạc. Trong phần này, ủy viên cảnh sát mới cảm thấy Lôi Lạc thực sự là người có năng lực nhất trong toàn bộ lực lượng cảnh sát. Anh đã nâng đỡ Lôi Lạc lên cấp bậc thanh tra. Từ đó Lôi Lạc trượt dài trên con đường đầy tội lỗi.</p>', 'Full', 1, 'single', 'completed', 12, 1991, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Ngô Mạnh Đạt","avatar":""},{"name":"Trương Mẫn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324544);
