INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-ton-vo-thuong-ii', 'Chí Tôn Vô Thượng II', 'Casino Raider 2', 'https://phimimg.com/upload/vod/20231211-1/48c101b4ce371511497817bb44ec3150.jpg', 'https://phimimg.com/upload/vod/20231211-1/820eac643e0cd46d447f9dc029d38350.jpg', '<p>Chí Tôn Vô Thượng II - Casino Raider 2 xoay quanh anh chàng Chicken Feet (Lưu Đức Hoa), chuyên quản lý các sòng cờ bạc trong xã hội đen. Một ngày nọ, anh bị tay trùm của Hội Tam Hoàng là James bán đứng và bị bắt vào tù. Sau khi ra tù, anh đã rũ bỏ tất cả không còn nhúng tay vào giang hồ nữa nhưng tên James vẫn không buông tha anh khiến anh phải một lần nữa cầm đao đi lấy lại những gì tên James đã lấy của anh.</p>', 'Full', 1, 'single', 'completed', 15, 1991, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Hoàng Thu Sinh","avatar":""},{"name":"Ngô Thiện Liên","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324544);
