INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ot-nao-ot-chang-cay', 'Ớt Nào Ớt Chẳng Cay', 'Paprika', 'https://phimimg.com/upload/vod/20231211-1/3c1f01a5693fb4097a546aea7d85c11f.jpg', 'https://phimimg.com/upload/vod/20231211-1/0af53a74f4826d4674e3a03a67a9bcc5.jpg', '<p>Một cô gái trẻ đẹp đến trị trấn để giúp vị hôn phu của mình trong công việc kinh doanh. Thời gian sau cô gái cô quyết định tách ra khỏi cái bóng của vị hôn phu để bắt đầu kinh doanh riêng và những câu chuyện bí mật về tình ái được hé mở.</p>', 'Full', 1, 'single', 'completed', 13, 1991, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Debora Caprioglio","avatar":""},{"name":"Stéphane Ferrara","avatar":""},{"name":"Martine Brochard","avatar":""},{"name":"Stéphane Bonnet","avatar":""},{"name":"Rossana Gavinel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324544);
