INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-naked-gun-2-12-the-smell-of-fear', 'The Naked Gun 2 1/2: The Smell Of Fear', 'The Naked Gun 2 1/2: The Smell Of Fear', 'https://phimimg.com/upload/vod/20231209-1/7f0946b0b6c7b216d89c5dd8d29d3673.jpg', 'https://phimimg.com/upload/vod/20231209-1/31d2f8cee7447e24d3153a77266de4dd.jpg', '<p>Trung úy Frank Drebbin trở lại để cứu một lần nữa. Lần này anh ấy ra ngoài để lá Big Boy trong kinh doanh năng lượng. Một nhà khoa học hàng đầu (Tiến sĩ Mainheimer) sắp xuất bản báo cáo về nguồn cung cấp năng lượng cho tương lai. Mọi thứ không đẹp cho các nhà cung cấp truyền thống; Dầu, than và hạt nhân. Để cứu ngành công nghiệp của họ, các nhà cung cấp bắt cóc Mainheimer và thay thế anh ta bằng một mồi nhử với một báo cáo thuận lợi hơn. Jane, thư ký của bác sĩ, là ngọn lửa cũ của Debin. Ngoại tình đam mê của họ là do đó đã được nhen nhủ.</p>', 'Full', 1, 'single', 'completed', 23, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324544);
