INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-z-chua-te-oc-sen', 'Bảy Viên Ngọc Rồng Z: Chúa Tể Ốc Sên', 'Dragon Ball Z: Lord Slug', 'https://phimimg.com/upload/vod/20231129-1/7c1c19dfa06273ff18d4b6c4fed40281.jpg', 'https://phimimg.com/upload/vod/20231129-1/bfbafc5152456439f31c6e65251fd17f.jpg', '<p>Gohan đến thăm Piccolo và cho anh nghe một giai điệu mới mà Gohan đã học để huýt sáo. Do khả năng nghe của người Namekian, Piccolo bị đau nên đã tức giận ra lệnh cho Gohan dừng lại khi cả hai cảm nhận được một mối đe dọa đang đến gần từ ngoài không gian. Bulma và cha cô phát hiện ra rằng một thiên thạch chứa các dạng sống đang hướng về Trái đất và sẽ phá hủy hành tinh khi va chạm. Giữa lúc khối người hoảng loạn, Goku và Krillin lao vào chặn thiên thạch và hy vọng đẩy nó ra xa bằng cách cho nổ tung nó bằng sóng Kamehameha nhưng cả hai đều bất tỉnh bởi lực của thiên thạch tuy rằng nó đã nổ tung trên quỹ đạo. Sau đó, một con tàu vũ trụ sau đó hạ cánh xuống một trong những thành phố của Trái đất.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 1991, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Toshio Furukawa","avatar":""},{"name":"Kenji Utsumi","avatar":""},{"name":"Masako Nozawa","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Joji Yanami","avatar":""},{"name":"Naoko Watanabe","avatar":""},{"name":"Hiromi Tsuru","avatar":""},{"name":"Kōhei Miyauchi","avatar":""},{"name":"Naoki Tatsuta","avatar":""},{"name":"Keiichi Nanba","avatar":""},{"name":"Shozo Iizuka","avatar":""},{"name":"Koji Totani","avatar":""},{"name":"Daisuke Gori","avatar":""},{"name":"Shigeru Chiba","avatar":""},{"name":"Yukitoshi Hori","avatar":""},{"name":"Yusaku Yara","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324544);
