INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-tinh-1991', 'Ngoại Tình', 'Under Suspicion', 'https://phimimg.com/upload/vod/20230922-1/a3f74942174226e3cd2820f2a72233cb.jpg', 'https://phimimg.com/upload/vod/20230922-1/1e1049fce42926ceb6b89cdab15a0db5.jpg', '<p>Vào cuối những năm 1950, sĩ quan cảnh sát Anh Tony Aaron từ chức sau khi ngủ với Hazel, vợ của người đàn ông mà ngôi nhà mà anh ta phải canh gác. Trong công việc mới của mình là một thám tử tư giả, anh ta giúp các cặp vợ chồng ly hôn bằng cách chụp ảnh Hazel &quot;ngoại tình&quot; với người chồng. Khi cô bị sát hại khi đang làm việc, Tony bắt đầu ngoại tình với Angeline, tình nhân của người đàn ông đã chết, trong khi cố gắng chứng minh mình vô tội.</p>', 'Full', 1, 'single', 'completed', 12, 1991, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Laura San Giacomo","avatar":""},{"name":"Kenneth Cranham","avatar":""},{"name":"Alphonsia Emmanuel","avatar":""},{"name":"Maggie O''Neill","avatar":""},{"name":"Stephen Moore","avatar":""},{"name":"Malcolm Storry","avatar":""},{"name":"Richard Graham","avatar":""},{"name":"Alan Talbot","avatar":""},{"name":"Martin Grace","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324544);
