INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-muu-vuot-quan-hung', 'Kỳ Mưu Vượt Quần Hùng', 'Don''t Fool Me', 'https://phimimg.com/upload/vod/20231121-1/1a787504e39462326ec56d2c6c74c419.jpg', 'https://phimimg.com/upload/vod/20231121-1/28eac20d900b343cb7d9650b8e2f27a1.jpg', '<p>Kỳ Mưu Vượt Quần Hùng - Don&quot;t Fool Me (1991) Ngôi sao của Anh hùng Wah (Lưu Đức Hoa) và Cheung Ho-kit (Lương Triều Vỹ) là hai người bạn cũ gặp nhau ở kiếp sau. Hero là một thành viên băng đảng bộ ba và Kit là một nhân viên bán bảo hiểm, Hero đang tìm kiếm một sự thay đổi nghề nghiệp và Kit đã trở nên vỡ mộng với cuộc sống sau khi phát hiện ra anh ta có một &quot; bong bóng &quot; trong não có thể vỡ bất cứ lúc nào giết chết anh ta. Cả hai quyết định đổi đời một chút với Hội Tam Hoàng sẽ trở nên đáng kính và Nhân viên bán bảo hiểm tiếp quản thế giới của Hội Tam Hoàng. Cũng như một cuộc sống mới, cả hai người bạn tìm thấy tình yêu mới.</p>', 'Full', 1, 'single', 'completed', 11, 1991, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Teresa Mo","avatar":""},{"name":"Fennie Yuen","avatar":""},{"name":"Michael Chan","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Feng Tien","avatar":""},{"name":"Charine Chan","avatar":""},{"name":"James Au","avatar":""},{"name":"Jeffrey Lam Wai-Hung","avatar":""},{"name":"Stuart Yung Sai-Kit","avatar":""},{"name":"James Ha Chim-Si","avatar":""},{"name":"Gabriel Wong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324544);
