INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pretty-ghost', 'Pretty Ghost', 'Pretty Ghost', 'https://phimimg.com/upload/vod/20231123-1/f499a432674f86bc910952e6ba6602f5.jpg', 'https://phimimg.com/upload/vod/20231123-1/70f478457be1d6e9388fe9c026685627.jpg', '<p>Thanh tra xây dựng Tony điều tra một tòa nhà cũ bị bỏ hoang trong một khu thực vật hoang vắng và trở thành nạn nhân của một con quỷ không yên, muốn sống lại trong cơ thể của Tony. Tuy nhiên, linh hồn của một phụ nữ trẻ bất ngờ xuất hiện, cứu Tony và vô tình hút một phần sinh lực của anh, qua đó, chia sẻ cảm xúc và cảm xúc của anh. Con ma yêu Tony, nhưng anh ta muốn sử dụng cô để giúp anh ta thu hút người đồng nghiệp tuyệt đẹp của mình.</p>', 'Full', 1, 'single', 'completed', 13, 1991, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Ellen Chan Nga-Lun","avatar":""},{"name":"Peter Lai Bei-Dak","avatar":""},{"name":"Siu-Wai Mui","avatar":""},{"name":"Wu Fung","avatar":""},{"name":"Michael Chow Man-Kin","avatar":""},{"name":"Yip Hon-Leung","avatar":""},{"name":"Margaret Lee","avatar":""},{"name":"Lawrence Cheng","avatar":""},{"name":"Alfred Cheung Kin-Ting","avatar":""},{"name":"Andy Chin","avatar":""},{"name":"Peter Mak Tai-kit","avatar":""},{"name":"Ha Sao Hin","avatar":""},{"name":"Barry Jue Wai-Gwong","avatar":""},{"name":"Leung","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324544);
