INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wild-orchid-ii-two-shades-of-blue', 'Wild Orchid II: Two Shades of Blue', 'Wild Orchid II: Two Shades of Blue', 'https://phimimg.com/upload/vod/20231123-1/6debe4228f3a7f8fcdfada8be00d823b.jpg', 'https://phimimg.com/upload/vod/20231123-1/d1fd7a66ea66cd941007ffac41a5c3d0.jpg', '<p>Blue là một cô gái tuổi teen sống với người cha chơi nhạc Jazz Ham. Ham bị bệnh nặng và qua đời, và bây giờ Blue phải tự nuôi sống bản thân bằng cách nào đó. Elle, bà chủ của một nhà thổ, thuyết phục cô ấy đến sống và làm việc tại cơ sở của cô ấy. Cô quyết định rời bỏ công việc kinh doanh và sống một cuộc sống bình thường. Elle rất vui khi thấy rằng cô ấy không bao giờ có một cái.</p>', 'Full', 1, 'single', 'completed', 15, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nina Siemaszko","avatar":""},{"name":"Wendy Hughes","avatar":""},{"name":"Tom Skerritt","avatar":""},{"name":"Robert Davi","avatar":""},{"name":"Brent David Fraser","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Joe Dallesandro","avatar":""},{"name":"Casey Sander","avatar":""},{"name":"Stafford Morgan","avatar":""},{"name":"Don Bloomfield","avatar":""},{"name":"Liane Curtis","avatar":""},{"name":"Bridgit Ryan","avatar":""},{"name":"Lydie Denier","avatar":""},{"name":"Gloria Reuben","avatar":""},{"name":"Victoria Mahoney","avatar":""},{"name":"Kathy Hartsell","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324544);
