INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-truong-loi-lac', 'Thám Trưởng Lôi Lạc', 'Lee Rock 1', 'https://phimimg.com/upload/vod/20231123-1/b5969e2a25a48800390448798adac94c.jpg', 'https://phimimg.com/upload/vod/20231123-1/ba8373faf107bf84b94051a04df71d55.jpg', '<p>Phần đầu của series phim về một tay cảnh sát bẩn gồm sự thăng tiến và sụp đổ mà Lee Rock là một bản sao hoàn chỉnh. Rock đến Hong Kong theo diện di cư từ Đại Lục sang. Khinh bỉ sự nghèo khổ, Rock cố gắng chui vào ngành cảnh sát. Là một cảnh sát sạch khiến hắn kiếm được ít tiền hơn nên hắn học hỏi và làm theo các tay cảnh sát khác, lươn lẹo một chút nhưng không hại ai cả. Nhưng cứ như vậy thì hắn chả bao giờ leo lên tới đỉnh cả.</p>', 'Full', 1, 'single', 'completed', 23, 1991, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Sharla Cheung","avatar":""},{"name":"Chingmy Yau","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Kwan Hoi-San","avatar":""},{"name":"Michael Chan","avatar":""},{"name":"Tam Sin-Hung","avatar":""},{"name":"James Tien Chuen","avatar":""},{"name":"Lung Fong","avatar":""},{"name":"Victor Hon Kwan","avatar":""},{"name":"Lee Siu-Kei","avatar":""},{"name":"Eddy Ko","avatar":""},{"name":"Wong Yat-fei","avatar":""},{"name":"Jamie Luk Kim-Ming","avatar":""},{"name":"Louis Roth","avatar":""},{"name":"Wong Chun","avatar":""},{"name":"Garry Chan Chi-Shing","avatar":""},{"name":"Ricky","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324544);
