INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-tuong-lua', 'Bức Tường Lửa', 'Backdraft', 'https://phimimg.com/upload/vod/20231123-1/1a18a6510eb38b2bda790781b3e9b633.jpg', 'https://phimimg.com/upload/vod/20231123-1/82bcb0c5620c75765b88f66cdc41559e.jpg', '<p>Stephen và Brian hai anh em cùng là lính cứu hỏa cho một nơi được coi là có trách nhiệm nặng nề nhất nước Mỹ: Sở cứu hỏa Chicago! Họ nối nghiệp người cha quá cố của mình, ông đã hy sinh trong khi làm nhiệm vụ. Nhưng điều thú vị là ở chỗ: mỗi người lại có một thái độ khác nhau trước nỗi mất mát này: được làm công việc này là đam mê của người anh, anh luôn muốn được chứng kiến tận mắt và làm hết mình để chặn ngọn lửa; còn cậu em chỉ đến với nghề này sau khi đã chịu vài thất bại trong những nghề nghiệp khác nhau. Chính trong lúc đang có những mâu thuẫn về tính cách cũng như công việc, họ phải cùng nhau đấu tranh để chiến thắng ngọn lửa ghớm giếc, bị thao túng bởi một tên sát nhân biết cách giết người bằng lửa.</p>', 'Full', 1, 'single', 'completed', 15, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kurt Russell","avatar":""},{"name":"William Baldwin","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Donald Sutherland","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Rebecca De Mornay","avatar":""},{"name":"Jason Gedrick","avatar":""},{"name":"J.T. Walsh","avatar":""},{"name":"Anthony Mockus Sr.","avatar":""},{"name":"Cedric Young","avatar":""},{"name":"Juan Ramírez","avatar":""},{"name":"Kevin Casey","avatar":""},{"name":"Jack McGee","avatar":""},{"name":"Mark Wheeler","avatar":""},{"name":"Richard Lexsee","avatar":""},{"name":"Beep","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324544);
