INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-im-lang-cua-bay-cuu', 'Sự Im Lặng Của Bầy Cừu', 'The Silence of the Lambs', 'https://phimimg.com/upload/vod/20231123-1/712e6c865714ad0ca495981aa11ed3b0.jpg', 'https://phimimg.com/upload/vod/20231123-1/3481811832217e336a5167807211c228.jpg', '<p>Một cô gái trẻ mất tích và vụ án này có liên quan đến một kẻ giết người hàng loạt, để thỏa mãn cho những ý nghĩ bệnh hoạn của gã. Người duy nhất có thể làm vụ án sáng tỏ là tên tù nhân tâm thần, chuyên ăn thịt người Hannibal Lecter ( Anthony Hopkins ). Cô nhân viên trẻ Clarice được giao nhiệm vụ khai thác thông tin ở Hannibal. Từ đó, cô dần khám phá ra bí mật của những tiếng kêu kì lạ từ đàn cừu mà mình hằng ám ảnh…Một bộ phim đầy tính nhân bản được thể hiện qua những đoạn đốI thoại của Clarice và Hannibal và ở cái kết khiến người xem phải suy nghĩ rất nhiều…Bộ phim đã đoạt cùng lúc 5 giải Oscar quan trọng: giải phim hay nhất, đạo diễn, biên kịch, nam nữ diễn viên chính xuất sắc nhất. Đây là một thành tích ...</p>', 'Full', 1, 'single', 'completed', 18, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jodie Foster","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Ted Levine","avatar":""},{"name":"Anthony Heald","avatar":""},{"name":"Brooke Smith","avatar":""},{"name":"Diane Baker","avatar":""},{"name":"Kasi Lemmons","avatar":""},{"name":"Frankie Faison","avatar":""},{"name":"Tracey Walter","avatar":""},{"name":"Charles Napier","avatar":""},{"name":"Danny Darst","avatar":""},{"name":"Alex Coleman","avatar":""},{"name":"Dan Butler","avatar":""},{"name":"Paul Lazar","avatar":""},{"name":"Ron Vawter","avatar":""},{"name":"Roger Corman","avatar":""},{"name":"Lawrence A. Bonney","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324544);
