INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-im-lang-cua-bay-cuu', 'Sự Im Lặng Của Bầy Cừu', 'The Silence of the Lambs', 'sự im lặng của bầy cừu the silence of the lambs jodie foster anthony hopkins scott glenn ted levine anthony heald brooke smith diane baker kasi lemmons frankie faison tracey walter charles napier danny darst alex coleman dan butler paul lazar ron vawter roger corman lawrence a. bonney ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tren-mat-trang', 'Người Trên Mặt Trăng', 'The Man in the Moon', 'https://phimimg.com/upload/vod/20231116-1/837bee995f85385755828cdb61d96e19.jpg', 'https://phimimg.com/upload/vod/20231116-1/a143d7db80b993bbfe56bf6070cf3c12.jpg', '<p>Bối cảnh phim diễn ra tại một trang trại bên ngoài một thị trấn nhỏ ở nông thôn, vào những năm 1950. Hai cô gái tuổi teen đang được nuôi dạy bởi những bậc cha mẹ nghiêm khắc nhưng cũng rất mực yêu thương con. Một trong hai cô gái, Dani, 14 tuổi, vừa bước qua tuổi thiếu nữ.
 Chị gái của Dani, Maureen, khoảng 17 tuổi. Vào những đêm hè nóng nực, họ ngủ trên hiên nhà có màn che và trò chuyện với nhau, Dani than thở rằng cô ấy sẽ không bao giờ xinh đẹp và nổi tiếng như chị gái mình. Đó là điều các em gái đều cảm thấy.</p>', 'Full', 1, 'single', 'completed', 14, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Reese Witherspoon","avatar":""},{"name":"Sam Waterston","avatar":""},{"name":"Tess Harper","avatar":""},{"name":"Gail Strickland","avatar":""},{"name":"Jason London","avatar":""},{"name":"Emily Warfield","avatar":""},{"name":"Bentley Mitchum","avatar":""},{"name":"Ernie Lively","avatar":""},{"name":"Dennis Letts","avatar":""},{"name":"Earleen Bergeron","avatar":""},{"name":"Anna Chappell","avatar":""},{"name":"Brandi Smith","avatar":""},{"name":"Sandi Smith","avatar":""},{"name":"Derek Ball","avatar":""},{"name":"Spencer Ball","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324544);
