INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toto-anh-hung', 'Toto Anh Hùng', 'Toto the Hero', 'https://phimimg.com/upload/vod/20231114-1/894125b99dfefaf88c8cb9e7a3d11d92.jpg', 'https://phimimg.com/upload/vod/20231114-1/6e031a0e3eb3736d668454223fca0864.jpg', '<p>Thomas, 80 tuổi, kể lại thời thơ ấu và tuổi trung niên của mình thông qua một loạt hồi tưởng và chuỗi giấc mơ. Thomas tin rằng anh ấy đã bị lấy đi một cuộc sống tốt đẹp hơn khi mới sinh ra; Sau một vụ cháy bệnh viện, anh ấy nhớ lại rất rõ ràng việc bị tráo đổi với một đứa trẻ mới sinh khác, và sau đó lớn lên trong một hộ gia đình nghèo hơn bên cạnh.</p>', 'Full', 1, 'single', 'completed', 15, 1991, 'Vietsub', 'HD', 'Bỉ', 0, '[{"name":"Michel Bouquet","avatar":""},{"name":"Thomas Godet","avatar":""},{"name":"Gisela Uhlen","avatar":""},{"name":"Jo De Backer","avatar":""},{"name":"Mireille Perrier","avatar":""},{"name":"Sandrine Blancke","avatar":""},{"name":"Peter Böhlke","avatar":""},{"name":"Didier Ferney","avatar":""},{"name":"Hugo Harold-Harrison","avatar":""},{"name":"Pascal Duquenne","avatar":""},{"name":"Karim Moussati","avatar":""},{"name":"Léopold Verlaine-Corbion","avatar":""},{"name":"Maxime Verspecht","avatar":""},{"name":"Alice van Dormael","avatar":""},{"name":"Damien Delauno","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324544);
