INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ve-thelma-va-louise', 'Câu Chuyện Về Thelma Và Louise', 'Thelma & Louise', 'https://phimimg.com/upload/vod/20231110-1/ecdb2381506e07f4729b60477b219904.jpg', 'https://phimimg.com/upload/vod/20231110-1/7fb8c66ad5c6c0249f330f64a183a0d8.jpg', '<p>Hai người bạn thân nhất đặt ra một cuộc phiêu lưu, nhưng nó sớm quay lại với một lối thoát đáng sợ khỏi bị cảnh sát săn bắn, vì hai cô gái này trốn thoát vì tội ác mà họ cam kết.</p>', 'Full', 1, 'single', 'completed', 14, 1991, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Susan Sarandon","avatar":""},{"name":"Geena Davis","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Stephen Tobolowsky","avatar":""},{"name":"Timothy Carhart","avatar":""},{"name":"Lucinda Jenney","avatar":""},{"name":"Jason Beghe","avatar":""},{"name":"Sonny Carl Davis","avatar":""},{"name":"Ken Swofford","avatar":""},{"name":"Shelly Desai","avatar":""},{"name":"Carol Mansell","avatar":""},{"name":"Stephen Polk","avatar":""},{"name":"Rob Roy Fitzgerald","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324544);
