INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-chich-hudson-hawk', 'Đạo Chích Hudson Hawk', 'Hudson Hawk', 'https://phimimg.com/upload/vod/20231109-1/0ab8fa35e753e2a695a2a713ad92154b.jpg', 'https://phimimg.com/upload/vod/20231109-1/bd81746d3b773a5148980d20d5def89a.jpg', '<p>Eddie Hawkins, được gọi là Hudson Hawk, vừa được trả tự do sau mười năm tù và dự định sống phần còn lại của cuộc đời mình một cách trung thực. Nhưng sau đó, cặp vợ chồng Mayflower điên rồ đã tống tiền anh ta để đánh cắp một số tác phẩm của Leonardo da Vinci. Nếu anh ta từ chối, họ đe dọa sẽ giết người bạn Tommy của anh ta.</p>', 'Full', 1, 'single', 'completed', 14, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Danny Aiello","avatar":""},{"name":"Andie MacDowell","avatar":""},{"name":"James Coburn","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Sandra Bernhard","avatar":""},{"name":"David Caruso","avatar":""},{"name":"Frank Stallone","avatar":""},{"name":"Donald Burton","avatar":""},{"name":"Don Harvey","avatar":""},{"name":"Andrew Bryniarski","avatar":""},{"name":"Lorraine Toussaint","avatar":""},{"name":"Burtt Harris","avatar":""},{"name":"Carmine Zozzora","avatar":""},{"name":"Stefano Molinari","avatar":""},{"name":"Enrico Lo Verso","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324544);
