INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-vo', 'Điểm Vỡ', 'Point Break', 'https://phimimg.com/upload/vod/20231108-1/147a7c8426030ffbe20154e1a5502243.jpg', 'https://phimimg.com/upload/vod/20231108-1/faab58bd553c3a5995bb6669be92c30d.jpg', '<p>Ở Los Angeles, một nhóm cướp ngân hàng tự gọi mình là Cựu Tổng thống phạm tội khi đeo mặt nạ của Reagan, Carter, Nixon và Johnson. Tin rằng các thành viên của băng đảng có thể là những người lướt sóng, F.B.I. cử đặc vụ trẻ Johnny Utah đến bãi biển bí mật để hòa nhập với những người lướt sóng và thu thập thông tin.</p>', 'Full', 1, 'single', 'completed', 16, 1991, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Patrick Swayze","avatar":""},{"name":"Keanu Reeves","avatar":""},{"name":"Gary Busey","avatar":""},{"name":"Lori Petty","avatar":""},{"name":"John C. McGinley","avatar":""},{"name":"James Le Gros","avatar":""},{"name":"John Philbin","avatar":""},{"name":"BoJesse Christopher","avatar":""},{"name":"Julian Reyes","avatar":""},{"name":"Daniel Beer","avatar":""},{"name":"Chris Pedersen","avatar":""},{"name":"Vincent Klyn","avatar":""},{"name":"Anthony Kiedis","avatar":""},{"name":"Dave Olson","avatar":""},{"name":"Lee Tergesen","avatar":""},{"name":"Christopher Pettiet","avatar":""},{"name":"Sydney Walsh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324544);
