INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dep-va-quai-vat-1991', 'Người Đẹp và Quái Vật', 'Beauty and the Beast', 'https://phimimg.com/upload/vod/20231108-1/4a98011fd089bcf13e423ff0cb4df0ff.jpg', 'https://phimimg.com/upload/vod/20231108-1/4c526c7d5e17816e108a69812028c3e8.jpg', '<p>Một chàng hoàng tử trẻ sống trong một tòa lâu đài nguy nga tráng lệ. Chàng có tất cả nhưng kiêu ngạo, tàn nhẫn và không biết đến tình yêu thương... &nbsp;Chàng sẽ sống ra sao khi bị biến thành một con quái vật xấu xí? &nbsp;Lời nguyền chỉ được hóa giải, khi chàng học được cách yêu ai đó, và cũng được người đó đáp lại trước khi cánh hoa hồng cuối cùng rơi xuống!</p>', 'Full', 1, 'hoathinh', 'completed', 15, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Paige O''Hara","avatar":""},{"name":"Robby Benson","avatar":""},{"name":"Richard White","avatar":""},{"name":"Jerry Orbach","avatar":""},{"name":"David Ogden Stiers","avatar":""},{"name":"Angela Lansbury","avatar":""},{"name":"Rex Everhart","avatar":""},{"name":"Jesse Corti","avatar":""},{"name":"Bradley Pierce","avatar":""},{"name":"Hal Smith","avatar":""},{"name":"Jo Anne Worley","avatar":""},{"name":"Mary Kay Bergman","avatar":""},{"name":"Kath Soucie","avatar":""},{"name":"Alvin Epstein","avatar":""},{"name":"Tony Jay","avatar":""},{"name":"Brian Cummings","avatar":""},{"name":"Alec Murphy","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324544);
