INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-cuop-bugsy', 'Tên Cướp Bugsy', 'Bugsy', 'https://phimimg.com/upload/vod/20231108-1/0eb9bc76de42fc70c5804bb4671c9ca6.jpg', 'https://phimimg.com/upload/vod/20231108-1/14992cef918de12d1ba6e745e645bc41.jpg', '<p>Xoay quanh chuyện tình của một tay gangster hào hoa và một cô nữ minh tinh đang lên, Bugsy (1991) là bộ phim với những tình tiết hấp dẫn, gay cấn về một phần lịch sử của Las Vagas – sòng bạc nổi tiếng nhất thế giới hiện nay. Benjamin “Bugsy” Siegel (Warren Beatty) là một tay gangster quyến rũ có công việc làm ăn ở New York cùng với Meyer Lansky (Ben Kingsley) và Charlie “Lucky” Luciano (Bill Abraham). Được các cộng sự gửi tới Los Angeles làm ăn nhưng khi vừa đặt chân tới đây, Benjamin đã ngay lập tức bị quyến rũ trước vẻ đẹp và tài trí của một diễn viên điện ảnh đang lên – Virginia Hill (Annette Bening). Trên đường tới Nevada, Benjamin nảy ra ý tưởng về một sòng bài ở Sa mạc và kêu gọi các “đồng sự” giúp đỡ cả vật chất và tinh thần. Ông tuyển Mickey Cohen (Harvey Keitel) phụ giúp; kêu gọi tài trợ từ Meyer Lansky và các cộng sự gangster khác ở New York, thu được gần 1 triệu USD để xây dựng sòng bạc. Benjamin ngay lập tức bắt tay vào xây dựng Flamingo Las Vegas Hotel Casino. Tuy nhiên, với “năng khiếu” làm kế toán của một diễn viên điện ảnh như Virginia và “tài năng” quản lý tài chính của một tay gangster, dự án casino bị đội vốn gấp 6 lần và lâm vào nợ nần. Sự ăn chơi của bộ đôi và tính ngông cuồng của “Bugsy” Siegel là điều không thể chấp nhận được đối với thế giới ngầm, nhất là với “ông trùm của các ông trùm” Lucky Luciano…</p>', 'Full', 1, 'single', 'completed', 23, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Warren Beatty","avatar":""},{"name":"Annette Bening","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Elliott Gould","avatar":""},{"name":"Joe Mantegna","avatar":""},{"name":"Bebe Neuwirth","avatar":""},{"name":"Bill Graham","avatar":""},{"name":"Lewis van Bergen","avatar":""},{"name":"Wendy Phillips","avatar":""},{"name":"Richard C. Sarafian","avatar":""},{"name":"Karen Russell","avatar":""},{"name":"Robert Beltran","avatar":""},{"name":"Stefanie Mason","avatar":""},{"name":"Kimberly McCullough","avatar":""},{"name":"Andy Romano","avatar":""},{"name":"Br","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324544);
