INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ten-cuop-bugsy', 'Tên Cướp Bugsy', 'Bugsy', 'tên cướp bugsy bugsy warren beatty annette bening harvey keitel ben kingsley elliott gould joe mantegna bebe neuwirth bill graham lewis van bergen wendy phillips richard c. sarafian karen russell robert beltran stefanie mason kimberly mccullough andy romano br ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-chua', 'Hổ Chúa', 'The Tigers', 'https://phimimg.com/upload/vod/20231114-1/90b91c9ac719274141bf5be0cf3d75fa.jpg', 'https://phimimg.com/upload/vod/20231114-1/342f7042210ca5e7621cfd4fae6a9d36.jpg', '<p>Bộ phim là câu chuyện về một đội cảnh sát được nhân dân hết mực tin tưởng và ủng hộ. Năm cảnh sát: chú Thiên, Bang, Minh, Hoa, Bê phối hợp ăn ý, lập nhiều chiến công, được gọi là ngũ hổ tướng. Một lần truy nã tội phạm, chú Thiên phát hiện tên cầm đầu lại là em vợ. Hắn hối lộ chú Thiên 1 triệu đô. Trước cám dỗ của đồng tiền, niềm tin vào công lý của ngũ hổ tướng bắt đầu lay động. Giữa tiền bạc và lương tâm nghề nghiệp, họ sẽ chọn bên nào? Bộ phim diễn tả mặt tối của xã hội một cách chân thực nhất. Không chỉ gây ấn tượng với khán giả về những cảnh quay hành động giật gân vô cùng kịch tính, Ngũ hổ tướng còn xen lẫn những ý nghĩa về con người và xã hội vô cùng xúc động.</p>', 'Full', 1, 'single', 'completed', 16, 1991, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Felix Wong","avatar":""},{"name":"Michael Miu","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"Irene Wan","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Philip Chan","avatar":""},{"name":"Yammie Lam","avatar":""},{"name":"Lo Lieh","avatar":""},{"name":"Chen Kuan-tai","avatar":""},{"name":"Michael Dinga","avatar":""},{"name":"Wong Kam-Kong","avatar":""},{"name":"Hui Fan","avatar":""},{"name":"Joan Tong Lai-Kau","avatar":""},{"name":"Danny Poon","avatar":""},{"name":"Simon Cheung Yuk-San","avatar":""},{"name":"Lee Chi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324544);
