INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ho-chua', 'Hổ Chúa', 'The Tigers', 'hổ chúa the tigers andy lau tony leung chiu-wai kent tong felix wong michael miu leung kar-yan irene wan shing fui-on philip chan yammie lam lo lieh chen kuan-tai michael dinga wong kam-kong hui fan joan tong lai-kau danny poon simon cheung yuk-san lee chi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('paris-dang-bung-chay', 'Paris Đang Bùng Cháy', 'Paris Is Burning', 'https://phimimg.com/upload/vod/20231103-1/77fdf197ffed2faef0712ccda66ef6fb.jpg', 'https://phimimg.com/upload/vod/20231103-1/14c5986e97d13f6ac4a32815401209e9.jpg', '<p>Voguing đến từ đâu và chính xác thì điều gì đang tạo bóng râm? Bộ phim tài liệu mang tính bước ngoặt này cung cấp một bức ảnh chụp sống động về những năm 1980 qua con mắt của cảnh kéo bóng ở khu Harlem của người Mỹ gốc Phi và người Latinh ở Thành phố New York. Được thực hiện trong hơn bảy năm, PARIS IS BURNING mang đến một bức chân dung gần gũi về các &quot;ngôi nhà&quot; thời trang đối thủ, từ những cuộc tranh giành danh hiệu khốc liệt cho đến những bà mẹ nội trợ cung cấp thức ăn trong một thế giới tràn lan chứng sợ đồng tính, chuyển giới, phân biệt chủng tộc, AIDS và nghèo đói. Với sự góp mặt của những người theo dõi huyền thoại, nữ hoàng kéo và phụ nữ chuyển giới — bao gồm Willi Ninja, Pepper LaBeija, Dorian Corey và Venus Xtravaganza.</p>', 'Full', 1, 'single', 'completed', 19, 1991, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Pepper LaBeija","avatar":""},{"name":"Octavia St. Laurent","avatar":""},{"name":"Venus Xtravaganza","avatar":""},{"name":"Dorian Corey","avatar":""},{"name":"Willi Ninja","avatar":""},{"name":"Paris Dupree","avatar":""},{"name":"Freddie Pendavis","avatar":""},{"name":"Sol Williams Pendavis","avatar":""},{"name":"Junior LaBeija","avatar":""},{"name":"Angie Xtravaganza","avatar":""},{"name":"Carmen Xtravaganza","avatar":""},{"name":"Brooke Xtravaganza","avatar":""},{"name":"Kim Pendavis","avatar":""},{"name":"Sandy Ninja","avatar":""},{"name":"Avis Pendavis","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324544);
