INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-doi', 'Đường Đời', 'Boyz n the Hood', 'https://phimimg.com/upload/vod/20231029-1/1209ec6e7eeef2492ef4a73ae8a79f58.jpg', 'https://phimimg.com/upload/vod/20231029-1/42d8fa8078a8a86481612d2253ba738a.jpg', '<p>Chuyện phim Boyz N The Hood kể về một nhóm bạn có tuổi thơ lớn lên từ khu ổ chuột của Los Angeles. Cùng xuất thân từ khu ổ chuột nên mọi người đều có đời sống sinh hoạt hết sức khó khăn. Liệu trong điều kiện khó khăn đó, sẽ xảy ra thêm những chyện gì nữa. Xin mời các bạn cùng xem phim Boyz N The Hood và tìm hiểu nhé!</p>', 'Full', 1, 'single', 'completed', 14, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Laurence Fishburne","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Ice Cube","avatar":""},{"name":"Morris Chestnut","avatar":""},{"name":"Angela Bassett","avatar":""},{"name":"Nia Long","avatar":""},{"name":"Tyra Ferrell","avatar":""},{"name":"Lexie Bigham","avatar":""},{"name":"Desi Arnez Hines II","avatar":""},{"name":"John Cothran","avatar":""},{"name":"Jessie Lawrence Ferguson","avatar":""},{"name":"Tammy Hanson","avatar":""},{"name":"Regina King","avatar":""},{"name":"Yolanda Whittaker","avatar":""},{"name":"Alysia Rogers","avatar":""},{"name":"Leonette Scott","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324544);
