INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong', 'Hoàng Phi Hồng', 'Once Upon a Time in China', 'https://phimimg.com/upload/vod/20231016-1/ecc4a5b020415b62d8995b016839238e.jpg', 'https://phimimg.com/upload/vod/20231016-1/eaf30fbac130c2db70fce15e3c5c65e6.jpg', '<p>Trong bối cảnh bị nước ngoài xâm lược, Hoàng Phi Hồng chiến đấu để bảo vệ cộng đồng của mình khỏi bọn quan liêu, những tay côn đồ tại địa phương và một đối thủ võ thuật.</p>', 'Full', 1, 'single', 'completed', 14, 1991, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"Jacky Cheung","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Yuen Gam-Fai","avatar":""},{"name":"Yen Shi-Kwan","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Yau Gin-Gwok","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"Yuen Shun-Yi","avatar":""},{"name":"Xinxin Xiong","avatar":""},{"name":"Jonathan Isgar","avatar":""},{"name":"Mark King","avatar":""},{"name":"Steve Tartalia","avatar":""},{"name":"Colin George","avatar":""},{"name":"Leung Gam-San","avatar":""},{"name":"Sin Ka-Fai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324544);
