INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-lai-duoi-day-bien', 'Gặp Lại Dưới Đáy Biển', 'Hook', 'https://phimimg.com/upload/vod/20231015-1/fadb09f3658116fbf0d32a9bf29efbf6.jpg', 'https://phimimg.com/upload/vod/20231015-1/ce4348efa162efe62079935c74842003.jpg', '<p>Phim kể về cậu bé Peter Pan trưởng thành trở thành một luật sư chuyên giải quyết vấn đề sát nhập công ty. Peter kết hôn với con gái của Wendy. Thuyền trưởng Hook bắt cóc con của họ khiến Peter phải trở về Never Land cùng với Tinkerbell để tìm sự giúp đỡ. Cùng với các Lost boys, Peter đã đánh bại Thuyền trưởng Hook một lần nữa.</p>', 'Full', 1, 'single', 'completed', 20, 1991, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dustin Hoffman","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Bob Hoskins","avatar":""},{"name":"Maggie Smith","avatar":""},{"name":"Caroline Goodall","avatar":""},{"name":"Charlie Korsmo","avatar":""},{"name":"Amber Scott","avatar":""},{"name":"Dante Basco","avatar":""},{"name":"Isaiah Robinson","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324544);
