INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-mieu', 'Hắc Miêu', 'Black Cat', 'https://phimimg.com/upload/vod/20231014-1/1851ac57aeea28f6a79a0b0ab86ca53f.jpg', 'https://phimimg.com/upload/vod/20231014-1/c2e875ba26a82ca2d90f300875f1a3f0.jpg', '<p>Cô gái đầy nổi loạn Catherina vì giết người nên bị truy bắt. CIA thấy được khả năng của Catherina đã tẩy não và biến cô thành một công cụ có lợi với biệt danh Black Cat nhằm lợi dụng cô đối đầu với bọn sát thủ biến đổi gien. Với sự góp mặt của 2 diễn viên chuyên góp mặt ở thể loại hành động pha chút kinh dị Lương Tranh và Thù Văn Bá.</p>', 'Full', 1, 'single', 'completed', 15, 1991, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jade Leung","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Thomas Lam","avatar":""},{"name":"Curtis Fraser","avatar":""},{"name":"Denise Stauffer","avatar":""},{"name":"Jordy Shane","avatar":""},{"name":"Audrey Rene","avatar":""},{"name":"Mary Rawbins","avatar":""},{"name":"Randi Lynne","avatar":""},{"name":"Glen Morrison","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324544);
