INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('au-revoir-mon-amour', 'Au Revoir, Mon Amour', 'Au Revoir, Mon Amour', 'null', 'https://phimimg.com/upload/vod/20231013-1/1d00e8334713f079a85af3a6957e3b16.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Sáu năm trước, Lương Sen (do Lương Gia Kính thủ vai)&nbsp;</span><span class="" style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">nói lời chia tay với người yêu đau lòng Mei Yi (do Anita Mui thủ vai) và ra hậu phương tham gia bữa tiệc ngầm, và Mei trở thành ca sĩ hộp đêm theo Mr. Wu (do Zeng Jiang thủ vai).<br/>Năm 1941, Chiến tranh Thái Bình Dương nổ ra và tình hình thế giới hỗn loạn. Liang Sen và các đồng chí cách mạng của ông trở lại Tô giới Công cộng Thượng Hải và chứng kiến vụ giết hại dã man năm nhà sư Nhật Bản đêm đó, và kẻ chủ mưu đằng sau nó hóa ra là Shirakawa Nhật Bản (Hayabusa Kunimura). Liang theo Shirakawa đến hộp đêm, và hai người đã đánh nhau, Shirakawa bị giết, và Liang bị thương ở một số nơi. Trong thời gian hồi phục, Liang Sen đoàn tụ với người yêu Mei, và mối quan hệ cũ liên tục và khó từ bỏ.<br/>Cái chết của Shirakawa đã làm gia tăng mâu thuẫn trong nhượng bộ, và Tie Zemin (do Xu Shaoqiang thủ vai), người đứng đầu Cục 76, đã tàn nhẫn săn lùng và giết chết đảng ngầm.</span></p>', 'Full', 1, 'single', 'completed', 19, 1991, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Leung Ka Fai","avatar":""},{"name":"Anita Mui","avatar":""},{"name":"Wu Ka Li","avatar":""},{"name":"Xu Shaoqiang","avatar":""},{"name":"Kunimura Hayabusa","avatar":""},{"name":"Tăng Giang","avatar":""},{"name":"Hidekazu Akai","avatar":""},{"name":"Aoyama Chikeko","avatar":""},{"name":"Đặng Thôi Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324544);
