INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nu-u-hon-3', 'Thiến Nữ U Hồn 3', 'A Chinese Ghost Story 3', 'https://phimimg.com/upload/vod/20231012-1/281b4524794fadeea09da446010917bd.jpg', 'https://phimimg.com/upload/vod/20231012-1/6bb07d0a71893b98632ea5413f934a88.jpg', '<p>Mọc lên giữa khu rừng hoang vắng là chùa Phong Lan, nơi cư ngụ của những yêu nữ thành tinh và là bãi tha ma của những kẻ qua đường háo sắc. Một ngày nọ, một vị cao tăng cùng đồ đệ Fong của mình đi qua khu rừng này. Được biết về ngôi đền ma quái, vị cao tăng quyết định trừ tà, phổ độ chúng sinh. Tiểu đồ đệ của ông chẳng may đã quyến luyến với ma nữ Liên Hoa. Đúng lúc đó, Ma vương xuất hiện và thực hiện mưu đồ nắm quyền thiên hạ của mình. Và trong trận chiến sinh tử giữa sư phụ và Ma vương, làm thế nào Fong có thể cùng sư phụ đánh đuổi yêu ma vừa bảo vệ hạnh phúc của mình?</p>', 'Full', 1, 'single', 'completed', 28, 1991, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Jacky Cheung","avatar":""},{"name":"Joey Wong","avatar":""},{"name":"Nina Li Chi","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"Tiffany Lau Yuk-Ting","avatar":""},{"name":"Tommy Wong","avatar":""},{"name":"Sam Ho Choi-Chow","avatar":""},{"name":"Waise Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324544);
