INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyen-linh-ngoc', 'Nguyễn Linh Ngọc', 'Center Stage', 'https://phimimg.com/upload/vod/20231006-1/b4b9302d4b0352196eba76d610bf2f8e.jpg', 'https://phimimg.com/upload/vod/20231006-1/91afc16b9ea6e7e87e2a853b8ccd4adf.jpg', '<p>Bộ phim dựa trên một câu chuyện có thật: cuộc đời bi thảm của nữ diễn viên đầu tiên của màn bạc Trung Quốc, Nguyễn Linh Ngọc. Bộ phim này ghi lại sự nổi tiếng của cô với tư cách là một nữ diễn viên điện ảnh ở Thượng Hải trong những năm 1930.</p>', 'Full', 1, 'single', 'completed', 21, 1991, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Maggie Cheung","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Chin Han","avatar":""},{"name":"Yanyan Chen","avatar":""},{"name":"Waise Lee","avatar":""},{"name":"Cecilia Yip","avatar":""},{"name":"Kelvin Wong","avatar":""},{"name":"Yip San","avatar":""},{"name":"Ruan Lingyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324544);
