INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-dich-hanh-van-tinh', 'Vô Địch Hạnh Vận Tinh', 'When Fortune Smiles', 'https://phimimg.com/uploads/movies/20260713/vo-dich-hanh-van-tinh-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/vo-dich-hanh-van-tinh-poster.webp', '<p>Chow vào vai Wan-Sing, một tên cướp được Shing Fui-On thuê để bịa đặt với người thừa kế. Người em họ của Shing, Fei-Fei được hưởng một di sản kếch sù khi cô đám cưới và Shing muốn giành lấy di sản đó. Tuy nhiên, Fei-Fei đã bị giả mạo. Người anh họ Anthony Wong cũng muốn số di sản đó vào tay mình và bắt người em ruột Feng để mạo nhận em họ hắn và lấy số tiền đó. Những mối phức tạp này cứ đan chéo nhau không kết thúc, dẫn đến một hành động điên rồ kết thúc ở ngoài bờ biển. Mặc dù vậy những nhân vật cũng có những động cơ xấu, diễn viên nam bản thân họ đáng yêu và có đủ khả năng để làm bộ phim hấp dẫn. Một ngôi sao nhạc pop nhìn lạ lẫm và đạo diễn Anthony Chan cố một trang sức được coi như là một mật thám không ngừng đâm sầm vào Wan-Sing và giúp đỡ anh bất cứ khi nào cần thiết.</p>', 'Full', 1, 'single', 'completed', 57, 1990, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Sandra Ng Kwan-Yu","avatar":""},{"name":"Anthony Chan Yau","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Cutie Mui Siu-Wai","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Lam Kau","avatar":""},{"name":"Stuart Yung Sai-Kit","avatar":""},{"name":"Mai Kei","avatar":""},{"name":"Billy Chow Bei-Lei","avatar":""},{"name":"Hui Ying-Sau","avatar":""},{"name":"Billy Ching Sau-Yat","avatar":""},{"name":"Kan Tat-Wah","avatar":""},{"name":"Sai Gwa-Pau","avatar":""},{"name":"Lui Tat","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["When Fortune Smiles 1990 - Vô Địch Hạnh Vận Tinh","Vô Địch Hạnh Vận Tinh 1990","Wu di xing yun xing","คนตัดดวง","คนเล็กสุดเฮง","無敵幸運星"]', 1784690324544);
