INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-dich-hanh-van-tinh', 'Vô Địch Hạnh Vận Tinh', 'When Fortune Smiles', 'vô địch hạnh vận tinh when fortune smiles stephen chow sandra ng kwan-yu anthony chan yau anthony wong chau-sang cutie mui siu-wai shing fui-on lam kau stuart yung sai-kit mai kei billy chow bei-lei hui ying-sau billy ching sau-yat kan tat-wah sai gwa-pau lui tat châu tinh trì when fortune smiles 1990 - vô địch hạnh vận tinh vô địch hạnh vận tinh 1990 wu di xing yun xing คนตัดดวง คนเล็กสุดเฮง 無敵幸運星', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-mau-le', 'Giang Hồ Máu Lệ', 'The Unmatchable Match', 'https://phimimg.com/uploads/movies/20260713/giang-ho-mau-le-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/giang-ho-mau-le-poster.webp', '<p>Trước khi trở thành “vua hài” của châu Á, Châu Tinh Trì đã phải thể hiện mình qua khá nhiều bộ phim từ truyền hình cho tới điện ảnh, đặc biệt ông thường đảm nhiệm vai diễn trong những bộ phim hành động mà Giang Hồ Máu Lệ - The Unmatchable Match (1990) chính là một trong những tác phẩm quan trọng đưa tên tuổi của ông tới gần nhất với khán giả, bộ phim ra mắt năm 1990 của đạo diễn Parkman Wong, đồng thời cũng là người viết kịch bản cho phim. Ở thời điểm đó, The Unmatchable Match không được đánh giá quá cao bởi danh tiếng của A Tinh vẫn chưa thực sự nổi trội và đây cũng mới chỉ là phim thứ 2 mà Parkman trong vai trò chỉ đạo, một diễn viên vốn quen thuộc với vai phụ trong suốt nhiều năm.</p>', 'Full', 1, 'single', 'completed', 40, 1990, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Michael Chan Wai-Man","avatar":""},{"name":"Vivian Chow","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Ricky Wong Chun-Tong","avatar":""},{"name":"Alan Ng Siu-Hung","avatar":""},{"name":"Danny Lee Sau-Yin","avatar":""},{"name":"Lau Yuk-Gei","avatar":""},{"name":"James Ha Chim-Si","avatar":""},{"name":"Connie Mak Git-Man","avatar":""},{"name":"Karel Wong Chi-Yeung","avatar":""},{"name":"Chow Cheong-Wa","avatar":""},{"name":"Stephen Chang Gwong-Chin","avatar":""},{"name":"Kwan Hoi-San","avatar":""},{"name":"Nick Cheung Ka-Fai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["風雨同路","The Unmatchable Match"]', 1784690324544);
