INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-cua-toi', 'Anh Hùng Của Tôi', 'My Hero', 'https://phimimg.com/uploads/movies/20260713/anh-hung-cua-toi-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/anh-hung-cua-toi-poster.webp', '<p>Anh Hùng Của Tôi là bộ phim hài xoay quanh chàng trai A Tinh, một tay bổi bàn hộp đêm nhưng rất thích đọc truyện tranh và thường mơ mộng trở thành một ông trùm và nổi tiếng. Trong phim, sau một lần cứu thoát tay anh chị trong hội Tam Hoàng, Tinh được gia nhập hội. Song thế giới ngầm không như những gì anh chàng mê chuyện tranh này tưởng tượng. Cuộc đời A Tinh rồi sẽ ra sao? Liệu Tinh có thể tiếp tục trụ vững trong thế giới đầy máu me chết chóc?</p>', 'Full', 1, 'single', 'completed', 37, 1990, 'Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Wilson Lam Chun-Yin","avatar":""},{"name":"Ann Bridgewater","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Peter Yang Kwan","avatar":""},{"name":"Bryan Leung Kar-Yan","avatar":""},{"name":"Tung Chi","avatar":""},{"name":"Albert Cheung Miu-Hau","avatar":""},{"name":"Joh Chung-Sing","avatar":""},{"name":"Hoh Dung","avatar":""},{"name":"Chiang Tao","avatar":""},{"name":"Lily Li","avatar":""},{"name":"Yuen Woo-ping","avatar":""},{"name":"Lung Ming-Yan","avatar":""},{"name":"Alex Ng Hong-Ling","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一本漫畫闖天涯","My Hero","My Hero 1990 - Anh Hùng Của Tôi","Anh Hùng Của Tôi 1990","一本漫画闯天涯"]', 1784690324544);
