INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tra-lau-long-phung', 'Trà Lầu Long Phụng', 'Lung Fung Restaurant', 'https://phimimg.com/uploads/movies/20260713/tra-lau-long-phung-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/tra-lau-long-phung-poster.webp', '<p>Lung Fung Restaurant (Trà Lầu Long Phụng) là bộ phim nói về hai người bạn chí cốt,tình thân như hai anh em ruột thịt. Sau khi người chú của người kia bị sát hại, Long dự định sẽ làm lại tất cả, xây dựng cuộc đời nhưng vì chuyện này mà mới sau khi mãn hạn tù,anh ta cùng người anh em kia cùng nhau trả thù cho người đã mất...</p>', 'Full', 1, 'single', 'completed', 32, 1990, 'Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Max Mok Siu-Chung","avatar":""},{"name":"Stephen Chow","avatar":""},{"name":"Ellen Chan Nga-Lun","avatar":""},{"name":"Charine Chan Ka-Ling","avatar":""},{"name":"Ng Man-Tat","avatar":""},{"name":"Chu Tit-Wo","avatar":""},{"name":"Parkman Wong Pak-Man","avatar":""},{"name":"Wong Chak-Man","avatar":""},{"name":"Tam Sin-Hung","avatar":""},{"name":"Henry Fong Ping","avatar":""},{"name":"Chan Ging-Cheung","avatar":""},{"name":"Gilbert Lam Wai-San","avatar":""},{"name":"Strawberry Yeung Yuk-Mui","avatar":""},{"name":"Jameson Lam Wa-Fan","avatar":""},{"name":"So Wai-Nam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Lung Fung Restaurant","龍鳳茶樓","难忘的爱","龙凤茶楼","龍鳳茶樓"]', 1784690324544);
