INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-huynh-trung-ta', 'Sư Huynh Trúng Tà', 'Look Out, Officer!', 'https://phimimg.com/uploads/movies/20260713/su-huynh-trung-ta-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/su-huynh-trung-ta-poster.webp', '<p>Là bộ phim hài kể về một cảnh sát có tên Paio bị giết chết và oái oăm thay, linh hồn anh ta không thể siêu thoát. Trong phim, thiên đàng đã gửi anh ta trở lại nhân gian để tìm một vị cứu tinh giúp xóa tên anh ta ở nhân gian cho linh hồn siêu thoát. Trong phim, Hsing chính là vị cứu tinh ấy của Piao. Anh ta sẽ giúp linh hồn siêu thoát và tìm ra kẻ đã ám hại Piao. Đổi lại, Piao phải phù hộ và giúp anh ta hai việc: tìm một cô bạn gái ưng ý và cho anh ta thăng chức.</p>', 'Full', 1, 'single', 'completed', 37, 1990, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Bill Tung Biu","avatar":""},{"name":"Stanley Fung Shui-Fan","avatar":""},{"name":"Sunny Fang Kang","avatar":""},{"name":"Vivian Chen","avatar":""},{"name":"Amy Yip Chi-Mei","avatar":""},{"name":"Cutie Mui Siu-Wai","avatar":""},{"name":"Mak Yan-Wa","avatar":""},{"name":"Bak Ka-Sin","avatar":""},{"name":"Chan Lap-Ban","avatar":""},{"name":"Lee Hang","avatar":""},{"name":"Buffalo Tang Tai-Wo","avatar":""},{"name":"Chun Kwai-Bo","avatar":""},{"name":"Tony Tam Chun-To","avatar":""},{"name":"Mak Wai-Cheung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Shaolin Idiot","귀경출사","Look Out Officer","Look Out, Off