INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-quyt-day-mong-tay-nhon', 'Vỏ Quýt Dày Móng Tay Nhọn', 'Curry & Pepper', 'https://phimimg.com/uploads/movies/20260713/vo-quyt-day-mong-tay-nhon-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/vo-quyt-day-mong-tay-nhon-poster.webp', '<p>Trong phim Vỏ Quýt Dày Móng Tay Nhọn, hai cảnh sát trở thành chủ đề của tài liệu một phóng viên tin tức xinh đẹp. Xem phim này, bạn sẽ thấy hai người sớm nhận ra nhiều điều và bắt đầu có những hành động cực kỳ vui nhộn và hài hước. Phim hứa hẹn sẽ tạo cho người xem những giây phút thư giãn tuyệt vời.</p>', 'Full', 1, 'single', 'completed', 49, 1990, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trương Học Hữu","avatar":""},{"name":"Châu Tinh Trì","avatar":""},{"name":"Bách An Ni","avatar":""},{"name":"Tăng Chí Vỹ","avatar":""},{"name":"Kha Thụ Lương","avatar":""},{"name":"Sầm Kiến Huân","avatar":""},{"name":"Hoàng Bỉnh Diệu","avatar":""},{"name":"Lưu Vĩ Cường","avatar":""},{"name":"Phan Văn Kiệt","avatar":""},{"name":"Michael Dingo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ga li la jiao","Curry and Pepper","咖喱辣椒"]', 1784690324544);
