INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-witches', 'The Witches', 'The Witches', 'https://phimimg.com/upload/vod/20260508-1/87f5fb86ea7a1f8e28c3f2e33b678790.jpg', 'https://phimimg.com/upload/vod/20260508-1/2c5aca8ea9fc72a86c58e53bcfbbd854.jpg', '<p>Bộ phim kể về một cậu bé mồ côi vô tình phát hiện ra hội nghị bí mật của các phù thủy đang âm mưu biến toàn bộ trẻ em trên thế giới thành chuột, nhưng cậu không may bị biến thành chuột trước và buộc phải cùng bà ngoại thông minh, gan dạ của mình tìm cách ngăn chặn kế hoạch tàn ác này, từ đó mở ra một hành trình vừa rùng rợn vừa kịch tính …</p>', 'Full', 1, 'single', 'completed', 18, 1990, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jasen Fisher","avatar":""},{"name":"Mai Zetterling","avatar":""},{"name":"Anjelica Huston","avatar":""},{"name":"Charlie Potter","avatar":""},{"name":"Rowan Atkinson","avatar":""},{"name":"Bill Paterson","avatar":""},{"name":"Brenda Blethyn","avatar":""},{"name":"Jane Horrocks","avatar":""},{"name":"Nora Connolly","avatar":""},{"name":"Rose English","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Roald Dahl''s, The Witches","La maldición de las brujas","Bosorky","Las Brujas","The Witches"]', 1784690324544);
