INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('texasville', 'Texasville', 'Texasville', 'https://phimimg.com/upload/vod/20260505-1/f36fdc8c98526216b0381a1546524072.jpg', 'https://phimimg.com/upload/vod/20260505-1/e4531eaf46616747bf0863e038117066.jpg', '<p>Mùa hè năm 1984: 30 năm sau khi Duane làm đội trưởng đội bóng bầu dục trường trung học và Jacy trở thành nữ hoàng vũ hội, thị trấn Texas này gần Wichita Falls chuẩn bị kỷ niệm 100 năm thành lập. Giá dầu giảm, các ngân hàng phá sản, và Duane nợ 12 triệu đô la. Vợ anh, Karla, uống rượu quá nhiều, con cái anh lúc nào cũng gặp rắc rối, và anh lăng nhăng với vợ của bạn bè. Jacy trở lại thị trấn sau một sự nghiệp diễn xuất không mấy thành công, cuộc sống ở Ý và cái chết của con trai cô. Mọi người cho rằng Duane và Jacy sẽ nối lại mối tình thời trung học. Và Sonny thì mệt mỏi về tinh thần, khiến người ta lo lắng cho sự an toàn của anh. Liệu những người bạn này có thể tìm được sự cân bằng ở tuổi trung niên?</p>', 'Trailer', 1, 'single', 'ongoing', 17, 1990, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jeff Bridges","avatar":""},{"name":"Cybill Shepherd","avatar":""},{"name":"Annie Potts","avatar":""},{"name":"Randy Quaid","avatar":""},{"name":"Cloris Leachman","avatar":""},{"name":"Timothy Bottoms","avatar":""},{"name":"William McNamara","avatar":""},{"name":"Eileen Brennan","avatar":""},{"name":"Angie Bolling","avatar":""},{"name":"Meri Beth Moore","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Техасвилль","Texasville"]', 1784690324544);
