INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-ba-vuong-3', 'Nữ Bá Vương 3', 'The Inspector Wears Skirts III', 'https://phimimg.com/upload/vod/20260420-1/719934328e0df18ef249a037dbb79e40.jpg', 'https://phimimg.com/upload/vod/20260420-1/d05d4f6c861141b800b17b8dbd578be0.jpg', '<p>Thanh tra Kan (Stanley Fung), hiện đã kết hôn với Madame Wu (Sibelle Hu), được giao nhiệm vụ huấn luyện các thành viên Biệt đội Banshee sau khi Madame Wu nghỉ hưu một nửa. Trong nhiệm vụ tiếp theo, Biệt đội được giao nhiệm vụ bí mật vào một Con tàu Casino để bắt giữ một nhóm trộm chịu trách nhiệm về việc đánh cắp vũ khí quân sự và lực lượng thực thi pháp luật.</p>', 'Full', 1, 'single', 'completed', 22, 1990, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Sandra Ng Kwan-Yu","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Amy Yip Chi-Mei","avatar":""},{"name":"Maryanna Yip San","avatar":""},{"name":"Wong Wai-Kei","avatar":""},{"name":"Stanley Fung Shui-Fan","avatar":""},{"name":"Sibelle Hu Hui-Chung","avatar":""},{"name":"Billy Lau Nam-Kwong","avatar":""},{"name":"Woo Fung","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Michael Chow Man-Kin","avatar":""},{"name":"Barry Wong Ping-Yiu","avatar":""},{"name":"Peter Chan Lung","avatar":""},{"name":"Manfred Wong Man-","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Inspector Wears Skirts 3","霸王花3","Raid On Royal Casino Marine","霸王花之皇家賭船","The Inspector Wears Skirts III","皇家賭船(霸王花第三集)","霸王花之皇家赌船"]', 1784690324544);
