INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ma-trai-tu-nu', 'Hồn Ma Trại Tù Nữ', 'Jail House Eros', 'https://phimimg.com/upload/vod/20260308-1/f4817aeefc897877af1e1f3ae5b9fbe1.jpg', 'https://phimimg.com/upload/vod/20260308-1/d016a3a58e2ea7e78b8a0774eff96ea8.jpg', '<p>Trong chốn lao tù, anh chàng Blackie đã vạch ra một kế hoạch vượt ngục hoàn hảo. Thế nhưng, nữ quản ngục mang số hiệu 5354 vô tình tử nạn trong lúc đang ân ái. Cô ta biến thành một ác ma hung dữ, đối nghịch hoàn toàn với một linh hồn tốt bụng — người đã chết trong một nỗ lực vượt ngục trước đó. Cuối cùng, một thỏa thuận kỳ lạ đã được xác lập giữa tên trưởng ngục, những người thợ trang trí nội thất, Blackie và linh hồn tốt bụng kia. Họ quyết định nhờ đến bạn gái của trưởng ngục — vốn là một bậc thầy trừ tà — để trục xuất nữ ác ma. Đổi lại, Blackie và linh hồn tốt sẽ được rời đi một cách êm đẹp...</p>', 'Full', 1, 'single', 'completed', 20, 1990, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Stanley Fung Shui-Fan","avatar":""},{"name":"Pauline Wong Yuk-Wan","avatar":""},{"name":"Chan Kit-Ling","avatar":""},{"name":"Susan Ha Chi-Chun","avatar":""},{"name":"Loletta Lee Lai-Chun","avatar":""},{"name":"Maria Cordero","avatar":""},{"name":"Amy Yip Chi-Mei","avatar":""},{"name":"Joanna Chan","avatar":""},{"name":"Wong Mei-Wah","avatar":""},{"name":"Ngai Suet","avatar":""},{"name":"Edith Au","avatar":""},{"name":"Cheng Yuen-Man","avatar":""},{"name":"殷晓仪","avatar":""},{"name":"郭天儿","avatar":""},{"name":"Lawrence Lau Sek-Yin","avatar":""},{"name":"Jeng Gwan-Chi","avatar":""},{"name":"Dickson Lee","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-l