INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-huyet-nhai-dau', 'Điệp Huyết Nhai Đầu', 'Bullet in the Head', 'https://phimimg.com/upload/vod/20260108-1/6c00495da93658c4f46ecf6f5a016784.jpg', 'https://phimimg.com/upload/vod/20260108-1/849a03662816d416d48ddcf443176326.jpg', '<p>Ben (Lương Triều Vỹ), Frank (Trương Học Hữu) và Paul (Waise Lee) là 3 người bạn thân. Họ đã gắn bó suốt cả thời niên thiếu trên những đường phố Hong Kong. Tuy nghèo khó, nhưng họ sống trung thành với nhau qua nhiều biến cố của đời sống. Khi Ben quyết định cưới vợ, Frank và Paul đã tìm cách vay mượn một khoản tiền để lo cho bạn. Frank bị bọn ganster đuổi đánh trọng thương. Để đòi lại công bằng, Ben đã lỡ tay giết chết một tên và cả ba buộc phải trốn đi ngay sau đêm tân hôn…</p>', 'Full', 1, 'single', 'completed', 21, 1990, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Jacky Cheung Hok-Yau","avatar":""},{"name":"Waise Lee Chi-Hung","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Fennie Yuen Kit-Ying","avatar":""},{"name":"Yolinda Yan Chor-Sin","avatar":""},{"name":"Lam Chung","avatar":""},{"name":"Nina Paw Hei-Ching","avatar":""},{"name":"Chang Gan-Wing","avatar":""},{"name":"So Hang-Suen","avatar":""},{"name":"Chang Tseng","avatar":""},{"name":"Siao San-Yan","avatar":""},{"name":"Paco Yick Tin-Hung","avatar":""},{"name":"Pei Yun","avatar":""},{"name":"Tsui Kwong-Lam","avatar":""},{"name":"Ding","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"