INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-vo-hinh-2', 'Quái Thú Vô Hình 2', 'Predator 2', 'https://phimimg.com/upload/vod/20251116-1/770cf2e13f6799f2fdd2532da3f10d47.jpg', 'https://phimimg.com/upload/vod/20251116-1/4af69377439211765dd64afc3bf5d29b.jpg', '<p>Tiếp nối sự thành công của phần một. Phần thứ hai của series phim Predator (Quái Thú Vô Hình) được ra mắt năm 1990. Thành phố Los Angeles rung động vì cuộc đụng độ đẫm máu giữa hai băng đảng gốc Nam Mỹ. Nhưng khi cảnh sát Mike và đồng sự Jerry vào cuộc điều tra, những manh mối lại dẫn đến một thế lực thứ ba: Loài sinh vật ngoài hành tinh với bản năng săn mồi siêu đẳng.</p>', 'Full', 1, 'single', 'completed', 18, 1990, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Danny Glover","avatar":""},{"name":"Gary Busey","avatar":""},{"name":"Rubén Blades","avatar":""},{"name":"María Conchita Alonso","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Robert Davi","avatar":""},{"name":"Adam Baldwin","avatar":""},{"name":"Kevin Peter Hall","avatar":""},{"name":"Kent McCord","avatar":""},{"name":"Morton Downey","avatar":""},{"name":"Jr.","avatar":""},{"name":"Calvin Lockhart","avatar":""},{"name":"Steve Kahan","avatar":""},{"name":"Henry Kingi","avatar":""},{"name":"Corey Rand","avatar":""},{"name":"Elpidia Carrillo","avatar":""},{"name":"Lilyan Chauvin","avatar":""},{"name":"Michael Mark","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["鐵血戰士續集","鐵血戰士 2","Хищник 2","Rovdjuret 2","O Predador 2 - A Caçada