INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-nghiem-diem-chet-1990', 'Trải Nghiệm Điểm Chết', 'Flatliners', 'https://phimimg.com/upload/vod/20251114-1/93c93807ef1f8a7c73bd27c9d84ffc98.jpg', 'https://phimimg.com/upload/vod/20251114-1/fbccab8899848b82a5e25eef00a3f6ba.jpg', '<p>Phim xoay quanh một nhóm sinh viên y khoa tò mò về thế giới sau cái chết. Họ tiến hành những thí nghiệm nguy hiểm: tự làm tim ngừng đập (flatline) trong thời gian ngắn rồi được hồi sinh bởi đồng đội. Mỗi người khi “chết lâm sàng” đều trải qua những ảo giác kỳ lạ và ám ảnh từ quá khứ, khiến họ phải đối mặt với tội lỗi và nỗi sợ sâu thẳm trong tâm trí.</p>', 'Full', 1, 'single', 'completed', 16, 1990, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kiefer Sutherland","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"William Baldwin","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Kimberly Scott","avatar":""},{"name":"Joshua Rudoy","avatar":""},{"name":"Benjamin Mouton","avatar":""},{"name":"Aeryk Egan","avatar":""},{"name":"Kesha Reed","avatar":""},{"name":"Hope Davis","avatar":""},{"name":"Jim Ortlieb","avatar":""},{"name":"John Duda","avatar":""},{"name":"Megan Stewart","avatar":""},{"name":"Tressa Thomas","avatar":""},{"name":"Sanna Vraa","avatar":""},{"name":"Beth Grant","avatar":""},{"name":"Marilyn Dodds Fr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Línea Mortal","Elumängud","Raja tuntemattomaan","Inn i det ukjente","Comatoşii","Tan