INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trai-nghiem-diem-chet-1990', 'Trải Nghiệm Điểm Chết', 'Flatliners', 'trải nghiệm điểm chết flatliners kiefer sutherland julia roberts kevin bacon william baldwin oliver platt kimberly scott joshua rudoy benjamin mouton aeryk egan kesha reed hope davis jim ortlieb john duda megan stewart tressa thomas sanna vraa beth grant marilyn dodds fr línea mortal elumängud raja tuntemattomaan inn i det ukjente comatoşii tanka linija smrti 유혹의 선 φλατλάινερς: ταξιδιώτες στην αλλη ζωή φλατλάινερς: ταξιδιώτες στην άλλη ζωή l''expérience interdite flatliners', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-co-that', 'Giấc Mơ Có Thật', 'Jacob''s Ladder', 'https://phimimg.com/upload/vod/20251028-1/9c4a4e21174e08589a85c8a3b6038f34.jpg', 'https://phimimg.com/upload/vod/20251028-1/571031aa59e70aea38ca47e0fd530ffe.jpg', '<p>Sau khi trở về nhà từ Chiến tranh Việt Nam, cựu chiến binh Jacob Singer phải vật lộn để giữ vững sự tỉnh táo. Bị ám ảnh bởi ảo giác và những ký ức hồi tưởng, Singer nhanh chóng suy sụp khi thế giới và con người xung quanh anh biến đổi và xoắn lại thành những hình ảnh kinh hoàng. Bạn gái anh, Jezzie, và vợ cũ, Sarah, cố gắng giúp đỡ, nhưng vô ích. Ngay cả Louis, người bạn nắn xương của Singer, cũng không thể giúp anh khi anh dần trở nên điên loạn.</p>', 'Full', 1, 'single', 'completed', 16, 1990, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tim Robbins","avatar":""},{"name":"Elizabeth Peña","avatar":""},{"name":"Danny Aiello","avatar":""},{"name":"Matt Craven","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Jason Alexander","avatar":""},{"name":"Patricia Kalember","avatar":""},{"name":"Eriq La Salle","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Brian Tarantina","avatar":""},{"name":"Anthony Alessandro","avatar":""},{"name":"Brent Hinkley","avatar":""},{"name":"S. Epatha Merkerson","avatar":""},{"name":"Suzanne Shepherd","avatar":""},{"name":"Doug Barron","avatar":""},{"name":"Jan Saint","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Jacob''s mardröm","La escalera de Jacob","Dante''s Inferno","Jaakobin painajainen","Xypnima ston efialti","A Escada de Jacob","BZ - Viagem Alucinante","Dzejkobova lestvica","Лестница Иакова","Jacobova ljestvica uzasa","Jacob''s Ladder"]', 1784690324544);
