INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-canh-sat-1990', 'Câu Chuyện Cảnh Sát', 'The Cop Story', 'https://phimimg.com/upload/vod/20251010-1/f8caf8df4d50d1f61eee7eec0812fc6b.jpg', 'https://phimimg.com/upload/vod/20251010-1/0f38e77fcbb084edcedc30a259cecf2d.jpg', '<p>Thám tử Trác Lam và Hướng Thăng vốn là bạn thân. Năm xưa, Thăng vì cái chết thảm của chị gái là Hướng Quỳ mà trở mặt với Lam. Một lần, họ tái ngộ trong một vụ cướp trang sức, cùng nhau bắt cướp và hàn gắn tình bạn. Thăng sau đó trở thành nội gián, tiếp cận ông trùm xã hội đen Trần Bang để điều tra. Trác Lam muốn kết hôn với cô chủ quán karaoke Hạ Văn Phụng, nhưng cô vì tự ti xuất thân của mình mà một mực từ chối anh. Đang lúc chán nản, Lam gặp và nảy sinh tình cảm với nữ luật sư La Nhất Nghiên. Khi Phụng muốn quay lại với Lam, anh bị kéo vào một mối quan hệ tình cảm phức tạp với Nghiên và Hoa Học Khiêm - một thương gia luôn yêu thầm Nhất Nghiên. Bề ngoài, Khiêm là một thương gia kinh doanh trang sức, nhưng thực chất hắn lại ngầm tiến hành các hoạt động buôn lậu công nghệ tiên tiến. Sau khi Thăng phát hiện chứng cứ tội phạm của Khiêm, anh đã bị ám hại. Bị thôi thúc bởi công lý và sự trả thù cá nhân, Lam thề sẽ đưa Khiêm ra trước pháp luật…</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 21, 1990, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Deric Wan","avatar":""},{"name":"Pauline Yeung Bo-Ling","avatar":""},{"name":"Tse Ning","avatar":""},{"name":"Dickson Lee Kar-Sing","avatar":""},{"name":"Kwan Hoi-San","avatar":""},{"name":"Andy Tai Chi-Wai","avatar":""},{"name":"Simon Lui Yu-Yeung","avatar":""},{"name":"Carrie Ho Ka-Lai","avatar":""},{"name":"Terence Choi","avatar":""},{"name":"Carrie Choi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["零点出击","零點出擊"]', 1784690324544);
