INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-duong-thanh-cong', 'Bước Đường Thành Công', 'Rain In The Heart', 'https://phimimg.com/upload/vod/20251008-1/fc7bf61325b19a8550085ecfc26a72cd.jpg', 'https://phimimg.com/upload/vod/20251008-1/10819a4f5bcd22dbff5b7eb8b09a0bf0.jpg', '<p>Gia Vĩ vốn là con tư sinh của ông chủ tiệm bánh, từ nhỏ bị mọi người khinh bỉ nên Vĩ rất ghét cha mình. Đến khi ông qua đời, VĨ mới biết nỗi khổ của cha mình nên đồng ý giúp quản lý tiệm bánh. Trên con đường phát triển sự nghiệp Vĩ được Thuận Phần giúp đỡ, nhưng trước khi thành hôn thì bị người yêu cũ của Vĩ tìm cách phá hoại khiến Vĩ và Phần trở thành kẻ thù…</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 17, 1990, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Roger Kwok Chun-On","avatar":""},{"name":"Dominic Lam Ka-Wah","avatar":""},{"name":"Josephine Lam Kei-Yan","avatar":""},{"name":"Kwan Hoi-San","avatar":""},{"name":"May Hoh","avatar":""},{"name":"Gallen Lo Ka-Leung","avatar":""},{"name":"Winnie Lau Siu-Wai","avatar":""},{"name":"Kathy Chow Hoi-Mei","avatar":""},{"name":"Perrie Lai Hoi-San","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["成功路上"]', 1784690324544);
