INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-maruko', 'Cô Bé Maruko', 'Chibi Maruko-chan', 'https://phimimg.com/upload/vod/20250819-1/fd7790af0f1cd2c3f70b72bc6b0b0233.jpg', 'https://phimimg.com/upload/vod/20250819-1/30aed65c3277ccebf79cf8325afb8c08.jpg', '<p>&quot;Chibi Maruko-chan&quot; xoay quanh cuộc sống thường nhật của cô bé tiểu học tên Maruko (Momoko Sakura) sống cùng gia đình ở thành phố Shimizu, tỉnh Shizuoka (Nhật Bản), vào những năm 1970. Với tính cách lém lỉnh, hậu đậu nhưng đầy tình cảm, Maruko thường xuyên vướng vào những tình huống dở khóc dở cười cùng bạn bè và người thân. Bộ phim khắc họa một cách nhẹ nhàng và sâu sắc về cuộc sống gia đình, tình bạn và những vấn đề giản dị nhưng rất thật trong tuổi thơ.</p>', 'Hoàn Tất (97/97)', 97, 'hoathinh', 'completed', 19, 1990, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ماروكو الصغيرة","樱桃小丸子","치비마루코쨩","NEW 마루코는 아홉살","หนูน้อยจอมฮา..มารูโกะจัง","จิบิ มารุโกะจัง","ちびまる子ちゃん"]', 1784690324544);
