INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngai-bean-1990', 'Ngài Bean', 'Mr. Bean', 'https://phimimg.com/upload/vod/20251001-1/c504a4bd6a35a3e9301bc6e4f96bbfe2.jpg', 'https://phimimg.com/upload/vod/20251001-1/264f1f4d4353c98a6e1b5b5e356c8230.jpg', '<p>Mr. Bean là một bộ phim truyền hình hài kịch nổi tiếng của Anh gồm 15 tập do ngôi sao nam Rowan Atkinson trong vai nhân vật chính được đặt tên cho phim. Kịch bản phim được viết bởi Rowan Atkinson, Robin Driscoll, Richard Curtis và Ben Elton. Tập đầu tiên, &quot;Mr. Bean&quot; đã được phát sóng ngày 1 tháng 1 năm 1990 và tập cuối &quot;The Best Bits of Mr. Bean&quot; vào ngày 15 tháng 12 năm 1995.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 14, 1990, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Rowan Atkinson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Mr. Bean: A Série","Nolojen TIlanteiden Mies","Mr bean s","Bean","戇豆先生","Mr. Bean"]', 1784690324544);
