INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-dan-ong', 'Chợ Đàn Ông', 'Man Market', 'https://phimimg.com/upload/vod/20250913-1/e82fae01c94a495c53a9958417c7073a.jpg', 'https://phimimg.com/upload/vod/20250913-1/15b350448c35ab5c6b3b364a4d24c637.jpg', '<p>Yeong-chun trở thành trai bao sau khi người phụ nữ anh từng nghĩ là tình yêu đích thực rời bỏ mình. Lý do cô ta bỏ đi chỉ vì Yeong-chun không có tiền. Khi cơ hội kiếm được một khoản lớn từ một người phụ nữ trung niên xuất hiện, anh lập tức nắm lấy. Nhưng để đổi lại số tiền đó, anh sẽ phải làm gì?</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Min-soo","avatar":""},{"name":"Ma Hung-sik","avatar":""},{"name":"Lee Eung-kyung","avatar":""},{"name":"Cho Jae-hyun","avatar":""},{"name":"Sunwoo Yong-nyeo","avatar":""},{"name":"Bang Hee","avatar":""},{"name":"Kim Ae-kyung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["남자시장"]', 1784690324544);
