INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-canh-diet-ma', 'Đặc Cảnh Diệt Ma', 'Magic Cop', 'https://phimimg.com/upload/vod/20250808-1/6c42cc81c0a36f248799d186aa1f55f2.jpg', 'https://phimimg.com/upload/vod/20250808-1/bfaa38098d101f0497e77fdb72b4f154.jpg', '<p>Trong một vụ điều tra buôn bán ma túy tại đặc cảnh Hồng Kông, vụ án có nhiều điểm vô cùng rắc rối nên đã mời một đặc cảnh ngày xưa (Lâm Chánh Anh) đã từng phá nhiều vụ tương tự, đồng thời cũng là vị pháp sư giỏi. Lần theo dấu vết của bọn tội phạm để lại, ông đã tìm ra mấu chốt vấn đề. Một nữ pháp sư Nhật Bản đã sử dụng xác chết để thực hiện buôn lậu. Cô ta tìm đến ông và quyết tâm giết chết ông. Những tài nghệ trừ ma diệt yêu của Lâm Chánh Anh một lần nữa được phô bày trước mắt khán giả thông qua bộ phim này.</p>', 'Full', 1, 'single', 'completed', 18, 1990, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Lâm Chính Anh","avatar":""},{"name":"Lâm Tuấn Hiền","avatar":""},{"name":"Miêu Kiều Vĩ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mr. Vampire 5","驅魔警察","驱魔警察","Магический полицейский","Qu mo jing cha","僵尸先生5：驱魔警察","驱魔探长"]', 1784690324544);
