INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-tia-chop-1990', 'Người Hùng Tia Chớp', 'The Flash', 'https://phimimg.com/upload/vod/20250801-1/166d57e34574bd485d36e4111d727e0d.jpg', 'https://phimimg.com/upload/vod/20250801-1/f22b8ca4d1978a4bf42e6dc72c039c00.jpg', '<p>Khi một tia sét giáng xuống phòng thí nghiệm của cảnh sát, một hỗn hợp các chất mang điện bao phủ nhà hóa học Barry Allen, biến anh trở thành người nhanh nhất thế giới – The Flash.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 13, 1990, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"John Wesley Shipp","avatar":""},{"name":"Amanda Pays","avatar":""},{"name":"Alex Désert","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Flash - O ultimo Vingador","闪电侠","Blesk","Flash – Der Rote Blitz","The Flash (1990)","The Flash 1990","Flash, Le Flash Rouge","Flash: Ο άνθρωπος - αστραπή!","Вспышка","The Flash"]', 1784690324544);
