INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-giac-mo', 'Những Giấc Mơ', 'Dreams', 'những giấc mơ dreams akira terao mitsuko baisho toshie negishi mieko harada mitsunori isaki toshihiko nakano yoshitaka zushi hisashi igawa chosuke ikariya chishū ryū martin scorsese masayuki yui tetsuo yamashita misato tate catherine cadou mieko suzuki ryûjirô akira kurosawa''s dreams yume rêves de kurosawa 夢 - dreams сны акиры куросавы kurosawovy sny akira kurosawa: álmok yuxular sonhos de akira kurosawa съновидения los sueños de akira drømme 夢 黑泽明之梦 sunshine through the rain the peach orchard the blizzard the tunnel crows mount fuji in red the village of the water mills the weeping demon', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve-tuong-lai-3', 'Trở Về Tương Lai 3', 'Back To The Future Part III', 'https://phimimg.com/upload/vod/20250728-1/239b73a6562c646d73304c9c5ea1d692.jpg', 'https://phimimg.com/upload/vod/20250728-1/f1a7f26d992476010c700d20aa71f1c3.jpg', '<p>Năm 1955, chiếc xe DeLorean đồng thời là cỗ máy thời gian bị sét đánh khiến Tiến sĩ Emmet và cố máy biến mất, Marty bị kẹt lại nơi đây. Đồng thời lúc đó anh cũng nhận được một bưu phẩm gửi đến cho anh. Chữ ký trên đó là của Tiến Sĩ, nhưng lá thư kèm theo được viết năm...1885.Với sự giúp đỡ của Tiến sĩ Emmet phiên bản 1955, Marty phục hồi được cỗ máy thời gian và chuẩn bị trở về. Tuy nhiên do tò mò về cuộc sống của Tiến sĩ khi bị kẹt ở quá khứ, Marty quay xe trở lại năm 1885, miền Tây nước Mỹ mà quên mất một điều quan trọng: thời điểm đó chưa có xăng, và anh chàng sẽ ko thể trở lại hiện tại được...</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael J. Fox","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Mary Steenburgen","avatar":""},{"name":"Thomas F. Wilson","avatar":""},{"name":"Lea Thompson","avatar":""},{"name":"Elisabeth Shue","avatar":""},{"name":"Matt Clark","avatar":""},{"name":"Richard Dysart","avatar":""},{"name":"Pat Buttram","avatar":""},{"name":"Harry Carey","avatar":""},{"name":"Jr.","avatar":""},{"name":"Dub Taylor","avatar":""},{"name":"James Tolkan","avatar":""},{"name":"Marc McClure","avatar":""},{"name":"Wendie Jo Sperber","avatar":""},{"name":"Jeffrey Weissman","avatar":""},{"name":"Christopher Wynne","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ritorno al futuro III","בחזרה לעתיד 3","Regreso al Futuro III","Retour vers le futur 3","Atgal i ateiti III","Vrnitev v prihodnost 3","Back to the Future Part 3","Ritorno al futuro 3","Volver al futuro III","Volver al Futuro III","Retour vers le futur III","Назад в будущее 3","vissza a jovobe 3","De Volta para o Futuro 3","Powrót do Przyszłości 3","Zurück in die Zukunft 3","tro ve tuong lai 3","Retour vers le Futur 3ème partie","Regreso al futuro III","უკან მომავალში მესამე ნაწილი","უკან მომავალში ნაწილი 3","Повратак у будућност 3","빽 투 더 퓨쳐 3","빽 투 더 퓨처 3","백 투 더 퓨처 3","백 투 더 퓨쳐 3","バック・トゥ・ザ・フューチャー3","バック・トゥ・ザ・フューチャー PART3：1990","Ritorno al futuro - parte 3","Gələcəyə Dönüş 3","回到未來 3","Back to the Future III","Back to the Future 3","Zurueck in die Zukunft 3","Հետ Դեպի Ապագա 3","Het Depi Apaga  3","De Volta Para o Futuro - Parte III","Back to the Future Part III"]', 1784690324544);
