INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-bai-1-dai-dien-ma-cao', 'Thánh Bài 1: Đại Diện Ma Cao', 'All For The Winner', 'https://phimimg.com/upload/vod/20250715-1/c8b676c945c5816409fe64484ac3f256.jpg', 'https://phimimg.com/upload/vod/20250715-1/72c444ae7e77618f6fcd18fb46b9e706.jpg', '<p>All For The Winner (1990) - Thánh Bài là bộ phim hài xoay quanh Tả Tụng Tinh, một anh chàng khù khờ từ đại lục đến Hồng Kông thăm ông chú hai &quot;Đạt đen&quot;. Vốn mê cờ bạc, chú Hai của Tinh muốn mượn &quot;Công Năng Đặc Dị&quot; của anh để khuấy đảo giới bài bạc Hồng Kông. Trong phim hay này, định mệnh khiến Tinh chạm trán Ỷ Mộng và nhanh chóng si mê cô gái nhan sắc này. Ỷ Mộng lôi kéo Tinh về dưới trướng vua cờ bạc Hồng Kông là Hồng Quang, nhưng Tinh nhanh chóng nhận thấy dã tâm của tên trùm này và từ chối. Anh quyết định làm đại diện cho Ma Cao tham gia cuộc thi cờ bạc thế giới để hạ gục Hồng Quang.</p>', 'Full', 1, 'single', 'completed', 12, 1990, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Stephen Chow","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Sharla Cheung","avatar":""},{"name":"Sandra Ng","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Angelina Lo","avatar":""},{"name":"Corey Yuen Kwai","avatar":""},{"name":"Jeffrey Lau","avatar":""},{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"Sheila Chan Suk-Lan","avatar":""},{"name":"Chik King-Man","avatar":""},{"name":"Jameson Lam Wa-Fan","avatar":""},{"name":"Mama Hung","avatar":""},{"name":"Dion Lam","avatar":""},{"name":"Adam Chan Chung-Tai","avatar":""},{"name":"Sam Ho Choi-Chow","avatar":""},{"name":"Chan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca