INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-hanh-tinh-muong-thu', 'Doraemon: Nobita và Hành Tinh Muông Thú', 'Doraemon: Nobita and the Animal Planet', 'https://phimimg.com/upload/vod/20250521-1/670b7060048ed73674fe97719961af83.jpg', 'https://phimimg.com/upload/vod/20250521-1/6f046a44bdb832b242f06e9a6994e6ff.jpg', '<p>Một làn sương mù màu hồng bí ẩn đưa Nobita, Doraemon, Shizuka, Suneo và Gian đến một hành tinh có nhiều loài vật sinh sống. Truyền thuyết kể rằng tổ tiên của quần thể này từng sống trên mặt trăng, nhưng họ đã được đưa ra khỏi đó để trốn thoát khỏi những sinh vật phàm ăn sống ở đó. Nobita và những người bạn của mình tò mò khám phá hành tinh khác biệt này cho đến khi khám phá ra bí mật đằng sau làn sương mù kỳ lạ. Nobita đã đến thế giới động vật thông qua &quot;Hơi gas dịch chuyển&quot;, chất cho phép bạn đi đến bất cứ đâu, giống như &quot;Cánh cửa bất kỳ&quot; mà Doraemon sử dụng. Họ tình cờ gặp Chippo, một cậu bé trông giống một chú chó và rất thích phiêu lưu. Một nhóm tên là Numiges có kế hoạch tiếp quản hành tinh động vật. Doraemon và những người bạn lên kế hoạch ngăn chặn chúng với sự giúp đỡ của con vật.</p>', 'Full', 1, 'hoathinh', 'completed', 10, 1990, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Kazuya Tatekabe","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["動物行星","Nobita and the Animal Planet","Doraemon Nobita to Animaru Puranetto","大雄與動物行星","哆啦A夢：大雄與惑星之迷","도라에몽: 노비타와 동물혹성","Doraemon the Movie: नोबिता और जंगल में दंगल","Doraemon: Nobita dan Planet Haiwan","โดราเอมอนเดอะมูฟวี่: ตะลุยดาวต่างมิติ","โดราเอมอน ตอน ตะลุยดาวต่างมิติ","Nobita dan Planet Haiwan","電影哆啦A夢：大雄與惑星之迷","映画ドラえもん のび太とアニマル惑星"]', 1784690324545);
