INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-bup-be-2', 'Ma Búp Bê 2', 'Child''s Play 2', 'https://phimimg.com/upload/vod/20250515-1/e6088a1e9a068283f364a108172d6bd4.jpg', 'https://phimimg.com/upload/vod/20250515-1/24752df391c6aa848ce07b5e177f83ba.jpg', '<p>Khi mẹ của Andy nhập viện tâm thần, cậu bé được đưa vào chăm sóc nuôi dưỡng, và Chucky, quyết tâm đòi lại linh hồn của Andy, đã không còn xa nữa.</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alex Vincent","avatar":""},{"name":"Brad Dourif","avatar":""},{"name":"Christine Elise","avatar":""},{"name":"Jenny Agutter","avatar":""},{"name":"Gerrit Graham","avatar":""},{"name":"Grace Zabriskie","avatar":""},{"name":"Peter Haskell","avatar":""},{"name":"Beth Grant","avatar":""},{"name":"Greg Germann","avatar":""},{"name":"Raymond Singer","avatar":""},{"name":"Stuart Mabray","avatar":""},{"name":"Matt Roe","avatar":""},{"name":"Don Pugsley","avatar":""},{"name":"Ed Krieger","avatar":""},{"name":"Vince Melocchi","avatar":""},{"name":"Charles Meshack","avatar":""},{"name":"Herbie Braha","avatar":""},{"name":"Adam Wylie","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chucky 2 - Die Mörderpuppe ist wieder da","Chucky, o Boneco Diabólico 2","Chuckie, o Boneco Diabólico 2","Grzeczny chłopiec 2","Child Play 2","I koukla tou satana no 2","Brinquedo Assassino 2","Child''s Play 2"]', 1784690324545);
