INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-truong-chia-nua-vang-trang', 'Chiến Trường Chia Nửa Vầng Trăng', 'The Battlefield Where The Moon Was Halved', 'https://phimimg.com/upload/vod/20250406-1/36282bcbef1bc251acb6efe55d285ba6.jpg', 'https://phimimg.com/upload/vod/20250406-1/2fd6be2afc1c19c863569a55ab38c8b7.jpg', '<p>Bên cạnh không khí đầy chết chóc là những cảnh thơ mộng, mối tình đẹp giữa chiến trường. Chuyện tình đầy cảm động của cô Trung uý Hậu cần do diễn viên Mai Phương đảm nhận với chiến sĩ trinh sát hay nhân vật Đại uý Vũ Đức do diễn viên Thương Tín thủ vai để lại xúc cảm mạnh mẽ trong lòng người xem về khát khao được yêu, được sống tự do và quyết tâm chiến đấu mạnh mẽ.</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thúy Anh","avatar":""},{"name":"Thương Tín","avatar":""},{"name":"Thúy An","avatar":""},{"name":"Quang Đại","avatar":""},{"name":"Mai Phương","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["The Struma"]', 1784690324545);
