INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-truong-chia-nua-vang-trang', 'Chiến Trường Chia Nửa Vầng Trăng', 'The Battlefield Where The Moon Was Halved', 'chiến trường chia nửa vầng trăng the battlefield where the moon was halved thúy anh thương tín thúy an quang đại mai phương the struma', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-ky-uc', 'Truy Tìm Ký Ức', 'Total Recall', 'https://phimimg.com/upload/vod/20231026-1/fabc6269c1a8b504a5d3c978b744994f.jpg', 'https://phimimg.com/upload/vod/20231026-1/ecd08932cae104af6b3f3fdb4a4f79fa.jpg', '<p>Lấy bối cảnh tương lai, năm 2084. Douglas Quaid là một công nhân xây dựng. Hằng đêm Doug gặp những cơn ác mộng về sao Hỏa, điều này trở nên ám ảnh anh. Doug đến công ty Rekall, một công ty chuyên kinh doanh các loại ký ức giả về những kỳ nghỉ lý tưởng. Khi Doug được cấy vào người ký ức về sao Hỏa, mọi chuyện trở nên cực kỳ tồi tệ. Doug mất hết ký ức của mình và bị theo đuổi bởi một nhóm sát thủ. Cô vợ xinh đẹp của anh, Lori, cũng là một điệp viên, người khẳng định rằng cuộc đời anh là một vở kịch lừa dối, anh thực sự không phải là con người mà anh biết. Sau khi phát hiện ra mình là Hauser, một điệp viên tình báo của sao Hỏa, Quaid quyết định đến sao Hỏa với hy vọng tìm kiếm câu trả lời. Ở đó, anh gặp một người phụ nữ tên là Melina, người đang phục vụ cho phe nổi loạn, chống lại Vilos Cohaggen, nhà cầm quyền nhũng nhiễu ở đây. Khi Doug bắt đầu phát hiện ra con người thật của mình cũng là lúc anh nghi ngờ sự thật. Liệu đây là trò lừa của công ty Rekall hay tất cả là sự thật?</p>', 'Full', 1, 'single', 'completed', 13, 1990, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Rachel Ticotin","avatar":""},{"name":"Sharon Stone","avatar":""},{"name":"Ronny Cox","avatar":""},{"name":"Michael Ironside","avatar":""},{"name":"Marshall Bell","avatar":""},{"name":"Mel Johnson Jr.","avatar":""},{"name":"Michael Champion","avatar":""},{"name":"Roy Brocksmith","avatar":""},{"name":"Ray Baker","avatar":""},{"name":"Rosemary Dunsmore","avatar":""},{"name":"David Knell","avatar":""},{"name":"Alexia Robinson","avatar":""},{"name":"Dean Norris","avatar":""},{"name":"Mark Carlton","avatar":""},{"name":"Debbie Lee Carringto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324545);
