INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-duong-danh-tham', 'Đại Đường Danh Thám', 'The Blood Hounds', 'https://phimimg.com/upload/vod/20250318-1/55c0f083724d4cb36101a6eec43b564f.jpg', 'https://phimimg.com/upload/vod/20250318-1/8956e6e71b8a80250a928e29242a84ad.jpg', '<p>Phim kiếm hiệp cổ trang xưa, với sự tham gia của các diễn viên: Ngô Trấn Vũ, Khương Đại Vệ, Lương Bội Linh, Doãn Thiên Chiếu...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 22, 1990, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Francis Ng Chun-Yu","avatar":""},{"name":"Andy Tai Chi-Wai","avatar":""},{"name":"Fiona Leung Ngai-Ling","avatar":""},{"name":"Sam Kam","avatar":""},{"name":"Julia Cheng Yim-Lai","avatar":""},{"name":"Cheung Fung-Lei","avatar":""},{"name":"Josephine Lam Kei-Yan","avatar":""},{"name":"Ching-Ching Yiu","avatar":""},{"name":"Sophie Ngan Chin-Man","avatar":""},{"name":"Alan Chan Kwok-Kuen","avatar":""},{"name":"Ben Wong Tin-Dok","avatar":""},{"name":"Stephan Yip Tin-Hang","avatar":""},{"name":"Yeung Chung","avatar":""},{"name":"Kwan Ching","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["The Blood Hounds","大唐名捕"]', 1784690324545);
