INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-duong-danh-tham', 'Đại Đường Danh Thám', 'The Blood Hounds', 'đại đường danh thám the blood hounds francis ng chun-yu andy tai chi-wai fiona leung ngai-ling sam kam julia cheng yim-lai cheung fung-lei josephine lam kei-yan ching-ching yiu sophie ngan chin-man alan chan kwok-kuen ben wong tin-dok stephan yip tin-hang yeung chung kwan ching the blood hounds 大唐名捕', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-dau-xanh', 'Quỷ Đầu Xanh', 'Till Death Shall We Start', 'https://phimimg.com/upload/vod/20250310-1/5fdbc3351a65507f0c352872dcf18eb8.jpg', 'https://phimimg.com/upload/vod/20250310-1/b38fe7500c132e1d9b3d04f4b85d4e6a.jpg', '<p>Chàng trai trẻ David (do Trần Hữu thủ vai) không may qua đời khi còn chưa từng trải chuyện tình cảm. Vì mang theo tâm nguyện chưa trọn, linh hồn anh không thể siêu thoát, cứ vất vưởng nơi trần thế, trở thành một cô hồn dã quỷ. David phát hiện rằng, để có thể bước vào vòng luân hồi, anh phải tìm được một cô gái đồng trinh và khiến cô tự nguyện hiến thân cho mình. Nếu không, anh chỉ có thể chờ đến lúc hồn bay phách tán, tan biến hoàn toàn. Một ngày nọ, David tình cờ gặp gỡ Huệ Hiền (do Vương Văn Quân thủ vai) – một cô gái xinh đẹp khiến anh say mê ngay từ cái nhìn đầu tiên. David hóa thân thành một quý ông bảnh bao, phong độ và bắt đầu theo đuổi Huệ Hiền một cách nhiệt tình. Theo thời gian, Huệ Hiền dần rung động trước sự quyến rũ của David, tình cảm bắt đầu lung lay. Tuy nhiên, bạn trai của Huệ Hiền – Hạnh Cao (do Ngô Diệu Hán thủ vai) – bắt đầu nghi ngờ David. Sau khi điều tra, anh phát hiện ra thân phận và mục đích thật sự đáng sợ của David. Hạnh Cao lập tức cảnh báo Huệ Hiền, nhưng cô lại không tin, mà đâu hay biết rằng tính mạng của mình đã rơi vào tình thế ngàn cân treo sợi tóc…</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Richard Ng Yiu-Hon","avatar":""},{"name":"Anthony Chan Yau","avatar":""},{"name":"Wong Man-Gwan","avatar":""},{"name":"Si-Ma Yin","avatar":""},{"name":"Alfred Cheung Kin-Ting","avatar":""},{"name":"Joh Chung-Sing","avatar":""},{"name":"Tiffany Lau Yuk-Ting","avatar":""},{"name":"Woo Fung","avatar":""},{"name":"Peter Chan Lung","avatar":""},{"name":"Ka Lee","avatar":""},{"name":"Paul Che Biu-Law","avatar":""},{"name":"Teddy Yip Wing-Cho","avatar":""},{"name":"Andrew Lam","avatar":""},{"name":"Ben Wong Tin-Dok","avatar":""},{"name":"Cheng Yuen-Man","avatar":""},{"name":"Ricky Ho P","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["衰鬼撬墻腳"]', 1784690324545);
