INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quy-dau-xanh', 'Quỷ Đầu Xanh', 'Till Death Shall We Start', 'quỷ đầu xanh till death shall we start richard ng yiu-hon anthony chan yau wong man-gwan si-ma yin alfred cheung kin-ting joh chung-sing tiffany lau yuk-ting woo fung peter chan lung ka lee paul che biu-law teddy yip wing-cho andrew lam ben wong tin-dok cheng yuen-man ricky ho p 衰鬼撬墻腳', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-la-dia-vong-1990', 'Thiên La Địa Võng', 'Heaven''s Retribution', 'https://phimimg.com/upload/vod/20241028-1/526d88eef8b824d4b292e3d92112dabf.jpg', 'https://phimimg.com/upload/vod/20241028-1/045120660a5a14e79ef970d4045a9d96.jpg', '<p>Thiên La Địa Võng được phát sóng vào năm 1990 của đài ATV quy tụ dàn diễn viên rất đáng chú ý, ngoài những ngôi sao quen thuộc của nhà đài thì phim còn có sự tham gia của những cái tên rất nổi tiếng bên TVB, đó là Ngô Khải Hoa, Nhậm Đạt Hoa, Mễ Tuyết, Thích Mỹ Trân… Phim khai thác song song cuộc sống đầy khắc nghiệt tại trung quốc thời nội chiến cho tới đất Hồng Kông phát triển nhưng không kém phần phức tạp, đan xen là những câu chuyện về tình bạn tình yêu đầy lôi cuốn.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 12, 1990, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Felix Wong","avatar":""},{"name":"吳啟華","avatar":""},{"name":"米雪","avatar":""},{"name":"任達華","avatar":""},{"name":"翁虹","avatar":""},{"name":"Jaime Mei Chun Chik","avatar":""},{"name":"Christine Ng","avatar":""},{"name":"Miu Kam-Fung","avatar":""},{"name":"Peter Yang Kwan","avatar":""},{"name":"Kong To","avatar":""},{"name":"Sun Xing","avatar":""},{"name":"Leung See-Ho","avatar":""},{"name":"Patricia Chong","avatar":""},{"name":"Kam Hing-Yin","avatar":""},{"name":"Lee Heung-Kam","avatar":""},{"name":"Gregory Lee Wing-Hor","avatar":""},{"name":"Augustine Lee","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["天网","還看今朝","天網"]', 1784690324545);
