INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vietnam-texas', 'Vietnam, Texas', 'Vietnam, Texas', 'https://phimimg.com/upload/vod/20241001-1/b1033a2dd04b18166740c32e6bf1b64c.jpg', 'https://phimimg.com/upload/vod/20241001-1/4cf7e133689e9bfeca0fd251a3f0b0c3.jpg', '<p>Một linh mục phát hiện ra rằng ông có một đứa con trong thời gian phục vụ ở Việt Nam, và mẹ con họ đã chuyển đến Houston, Texas, trong khu Little Saigon. Khi tìm kiếm họ, ông cũng phát hiện ra sự kỳ thị lớn đối với người Việt Nam, đặc biệt là trong cộng đồng ngư dân nơi họ đang cố gắng làm việc. Quyết tâm sửa chữa những sai lầm, linh mục này thường dùng nắm đấm hơn là thuyết phục thân thiện, theo kiểu của một linh mục.</p>', 'Full', 1, 'single', 'completed', 14, 1990, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robert Ginty","avatar":""},{"name":"Haing S. Ngor","avatar":""},{"name":"Kiều Chinh","avatar":""},{"name":"Tamlyn Tomita","avatar":""},{"name":"Steve Buckingham","avatar":""},{"name":"Tim Thomerson","avatar":""},{"name":"John Pleshette","avatar":""},{"name":"David Chow","avatar":""},{"name":"Bert Remsen","avatar":""},{"name":"Chi Muoi Lo","avatar":""},{"name":"Michele B. Chan","avatar":""},{"name":"Sachi Parker","avatar":""},{"name":"Peter Pan","avatar":""},{"name":"Steven Vincent Leigh","avatar":""},{"name":"Richard Masur","avatar":""},{"name":"Wesley Leong","avatar":""},{"name":"Sebastian Massa","avatar":""},{"name":"Cr","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["越戰焚情","Vietnam Texas"]', 1784690324545);
