INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-vui-ve-4', 'Ma Vui Vẻ 4', 'Happy Ghost IV', 'https://phimimg.com/upload/vod/20240930-1/c8030f717974eb1e1717d4c360ea0a21.jpg', 'https://phimimg.com/upload/vod/20240930-1/43e3bdc80910221e977c53b43c34e6e3.jpg', '<p>Một nhóm sinh viên đại học phát hiện ra tàn tích của một lãnh chúa xấu xa từ một hang động cũ và mang nó về ký túc xá của họ, cuối cùng điều này đã đánh thức hồn ma của lãnh chúa. Nó đang tìm cách trả thù cho kẻ giết mình, người đã tái sinh thành cô bạn gái hợm hĩnh của ông Hong là Annie. Khi Hong và Annie gặp nguy hiểm, linh hồn tái sinh của Hong tiếp quản để cứu anh và Annie, đồng thời đánh bại con quỷ</p>', 'Full', 1, 'single', 'completed', 12, 1990, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Raymond Wong","avatar":""},{"name":"Pauline Yeung Bo-Ling","avatar":""},{"name":"胡楓","avatar":""},{"name":"曹查理","avatar":""},{"name":"黃光亮","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"May Lo Mei-Mei","avatar":""},{"name":"Wong Ka-Kui","avatar":""},{"name":"Steve Wong Ka-Keung","avatar":""},{"name":"Yip Sai-Wing","avatar":""},{"name":"Loletta Lee","avatar":""},{"name":"陳妙瑛","avatar":""},{"name":"Paul Wong","avatar":""},{"name":"陳妙瑛","avatar":""},{"name":"袁潔瑩","avatar":""},{"name":"黃霑","avatar":""},{"name":"Charine Chan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["開心鬼救開心鬼","开心鬼4","Happy Ghost IV"]', 1784690324545);
