INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-dem', 'Ca Đêm', 'Graveyard Shift', 'https://phimimg.com/upload/vod/20240911-1/a5301954e0a5b65f3de001c4adaf0917.jpg', 'https://phimimg.com/upload/vod/20240911-1/e1a76f194e543b67bb56d45d5e66e617.jpg', '<p>Guy Filbrook cùng gia đình dời tới một căn nhà mới khang trang trong niềm háo hức. Nhưng ông không hề hay biết đó là một quyết định sai lầm nhất trong cuộc đời mình. Bởi con mắt phàm trần không cho Guy biết được một sự thật kinh sợ rằng ngôi nhà đang bị một lời nguyền rủa. Cách đây nhiều năm, một cái chết bí ẩn của cô gái trẻ đã làm rúng động mọi người. Và nay trong khu vườn hoang tàng, linh hồn non trẻ kia vẫn vởn vơ cùng những con búp bê kỳ dị nằm cạnh ngôi mộ cô chủ trẻ của chúng trong lòng đất âm u...Rồi ngày tàn khốc đã tới vì gia đình vô tội này đã vi phạm lời nguyền khi vô tình chạm vào điều cấm kỵ</p>', 'Full', 1, 'single', 'completed', 10, 1990, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Andrews","avatar":""},{"name":"Kelly Wolf","avatar":""},{"name":"Stephen Macht","avatar":""},{"name":"Andrew Divoff","avatar":""},{"name":"Vic Polizos","avatar":""},{"name":"Brad Dourif","avatar":""},{"name":"Robert Alan Beuth","avatar":""},{"name":"Ilona Margolis","avatar":""},{"name":"Jimmy Woodard","avatar":""},{"name":"Jonathan Emerson","avatar":""},{"name":"Minor Rootes","avatar":""},{"name":"Kelly L. Goodman","avatar":""},{"name":"Susan Lowden","avatar":""},{"name":"Joe Perham","avatar":""},{"name":"Dana Packard","avatar":""},{"name":"Skip Wheeler","avatar":""},{"name":"Richard France","avatar":""},{"name":"An","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324545);
