INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-z-ke-manh-nhat', 'Bảy Viên Ngọc Rồng Z: Kẻ Mạnh Nhất', 'Dragon Ball Z: The World''s Strongest', 'https://phimimg.com/upload/vod/20231024-1/013638a2e61bbe3db7d00c057c6fc532.jpg', 'https://phimimg.com/upload/vod/20231024-1/2a274eaf6f4c65ab469b975e42e60191.jpg', '<p>Giáo sư Uiro được Ngọc Rồng hồi sinh và âm mưu thống trị thế giới. Để kéo dài tuổi thọ, lão đã tự tạo ra cho mình một con robot và cố gắng tìm ra người mạnh nhất thế giới. Vì nghĩ rằng Quy Lão là người mạnh nhất thế giới nên lão đã bắt cóc cả Bulma lẫn Quy Lão về căn cứ của mình. Liệu Goku có cứu được Quy Lão hay không?</p>', 'Full', 1, 'hoathinh', 'completed', 16, 1990, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Masako Nozawa","avatar":""},{"name":"Toshio Furukawa","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Hiromi Tsuru","avatar":""},{"name":"Kōhei Miyauchi","avatar":""},{"name":"Mayumi Shou","avatar":""},{"name":"Naoki Tatsuta","avatar":""},{"name":"Kenji Utsumi","avatar":""},{"name":"Koji Yada","avatar":""},{"name":"Yukimasa Kishino","avatar":""},{"name":"Ken Yamaguchi","avatar":""},{"name":"Daisuke Gori","avatar":""},{"name":"Kôji Nakata","avatar":""},{"name":"Joji Yanami","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324545);
