INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bay-vien-ngoc-rong-z-ke-manh-nhat', 'Bảy Viên Ngọc Rồng Z: Kẻ Mạnh Nhất', 'Dragon Ball Z: The World''s Strongest', 'bảy viên ngọc rồng z: kẻ mạnh nhất dragon ball z: the world''s strongest masako nozawa toshio furukawa mayumi tanaka hiromi tsuru kōhei miyauchi mayumi shou naoki tatsuta kenji utsumi koji yada yukimasa kishino ken yamaguchi daisuke gori kôji nakata joji yanami ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-bat-tu', 'Tình Yêu Bất Tử', 'Cyrano de Bergerac', 'https://phimimg.com/upload/vod/20231016-1/e492cb40e7665c67e12812655415ea8b.jpg', 'https://phimimg.com/upload/vod/20231016-1/4f797f614802300a22daa4c2d90832bb.jpg', '<p>Cyrano de Bergerac kể về mối tình tay ba giữa chàng Cyrano, nàng Roxane xinh đẹp (đồng thời là em họ của Cyrano) và Christian de Neuvillette. Câu chuyện bắt đầu với nhà thơ, chàng ngự lâm quân tài ba Cyrano, yêu say đắm nàng Roxane nhưng lại tự ti vì chiếc mũi quá khổ. Khi bị Valvert, con trai của bá tước Guiche, người đã được đính ước với Roxane, chế nhạo vì vẻ ngoài xấu xí, chàng thi sĩ Cyrano đã đáp trả lại bằng những lời thơ trước khi cho anh ta gục ngã dưới thanh kiếm của mình. Ngay từ phút đầu gặp gỡ, Cyrano đã phải lòng nàng Roxane xinh đẹp nhưng qua lời thổ lộ của nàng, chàng biết được trái tim yếu đuối bé nhỏ ấy chỉ dành cho Christian, một tên ngốc, đẹp mã mà rỗng tuếch. Vậy nhưng Cyrano vẫn quyết định dùng ngòi bút của mình để viết những bức tình thư ngọt ngào giúp Christian chinh phục được trái tim người thiếu nữ trong mộng ấy.</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Gérard Depardieu","avatar":""},{"name":"Anne Brochet","avatar":""},{"name":"Vincent Perez","avatar":""},{"name":"Jacques Weber","avatar":""},{"name":"Roland Bertin","avatar":""},{"name":"Philippe Morier-Genoud","avatar":""},{"name":"Pierre Maguelon","avatar":""},{"name":"Josiane Stoléru","avatar":""},{"name":"Alain Rimoux","avatar":""},{"name":"Anatole Delalande","avatar":""},{"name":"Philippe Volter","avatar":""},{"name":"Jean-Marie Winling","avatar":""},{"name":"Louis Navarre","avatar":""},{"name":"Gabriel Monnet","avatar":""},{"name":"François Marié","avatar":""},{"name":"Pie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324545);
