INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-lai-ky-uc', 'Tìm Lại Ký Ức', 'Total Recall', 'https://phimimg.com/upload/vod/20240228-1/d7b3543c79072db9a0b0927e894b0b87.jpg', 'https://phimimg.com/upload/vod/20240228-1/ec9c1d076adb118d0d3ebe37cbc5a21e.jpg', '<p>Bộ phim lấy bối cảnh tương lai, năm 2084. Douglas Quaid là một công nhân xây dựng. Hằng đêm Doug đều có những cơn ác mộng về Sao Hỏa, và điều này trở nên ám ảnh anh. Doug đến công ty Rekall Inc., một công tay chuyên kinh doanh các loại ký ức giả về những kỳ nghỉ lý tưởng. Khi Doug được cấy vào người ký ức về Sao Hỏa, mọi chuyện trở nên cực kỳ tồi tệ. Doug mất hết ký ức của mình, và anh đang bị đuổi theo với một nhóm sát thủ, còn cô vợ xinh đẹp của anh, Lori, cũng là một điệp viên, người khẳng định rằng cả cuộc đời anh là một vở kịch lừa dối, anh thực sự không phải là con người mà anh biết. Sau khi phát hiện ra anh là Hauser, một điệp viên tình báo của Sao Hỏa, Quaid quyết định đến sao Hỏa với hy vọng là tìm ra được cho mình câu trả lời. Ở đó, anh gặp một người phụ nữ tên là Melina, người đang phục vụ cho phe nổi loạn, chống lại Vilos Cohaggen, nhà cầm quyền nhũng nhiễu ở đây. Khi Doug bắt đầu phát hiện ra con người thật của mình cũng là lúc anh nghi ngờ sự thật. Liệu đây là trò lừa của công ty Rekall Inc., hay tất cả là sự thật?</p>', 'Full', 1, 'single', 'completed', 13, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Sharon Stone","avatar":""},{"name":"Michael Ironside","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324545);
