INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-dau-voi-thu-thach-2', 'Đương Đầu Với Thử Thách 2', 'Die Hard: Die Harder', 'https://phimimg.com/upload/vod/20240220-1/536f170ab40091266ca2c538227a15e7.jpg', 'https://phimimg.com/upload/vod/20240220-1/bb5b43d1b268fdf4ca46188c773a3c11.jpg', '<p>Đó là một ngày buồn thảm và kinh hoàng nhất của thành phố Los Angeles, 230 hành khách trên một chuyến bay bị nổ tung khi chiếc máy bay đâm xầm xuống đất. Bọn khủng bố, đứng đầu là tên máu lạnh Col Stuart, đã dùng sự kiện kinh hoàng để gửi đến cảnh sát liên bang một thông điệp cứng rắn. Chúng muốn kẻ cầm đầu Franco Nero, đang bị áp giải trên một trong những chuyến bay cất cánh từ sân bay Dulles, phải được thả trong vòng 24 tiếng...</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"William Atherton","avatar":""},{"name":"Bonnie Bedelia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324545);
