INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-lua', 'Đảo Lửa', 'Island Of Fire', 'https://phimimg.com/upload/vod/20240207-1/7b49cd7686ea2015f0693420997ca67d.jpg', 'https://phimimg.com/upload/vod/20240207-1/9682d279c7bf71552f13ec6946e7dab8.jpg', '<p>Đảo Lửa - Island Of Fire (1990):Thanh tra Wei Wang có nhiệm vụ điều tra một nghi phạm đang ở trong tù bị tình nghi có liên quan đến cái chết của thầy anh ta. Bên trong nhà tù, Wei bị uy hiếp bởi tù nhân, và anh phát hiện ra sự thật đằng sau sự điên loạn của hệ thống trừng phạt nơi đây. Liệu thanh tra Wei có thể tồn tại và tìm ra những kẻ đứng sau núp bóng chính phủ mà vẫn giữ được sự ôn hòa???</p>', 'Full', 1, 'single', 'completed', 17, 1990, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Thành Long","avatar":""},{"name":"Hồng Kim Bảo","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324545);
