INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hao-hiep', 'Nữ Hào Hiệp', 'Executioners', 'https://phimimg.com/upload/vod/20240121-1/148161faff4eb4b72d25af05b2f9979c.jpg', 'https://phimimg.com/upload/vod/20240121-1/047f3cc4a0604d1a8fc6c9fbd459b5dd.jpg', '<p>Nữ Hào Hiệp - Executioners là bộ phim thuộc thể loại hành động võ thuật Trung Quốc năm 1990. Thành phố bị tàn phá bởi vũ khí hạt nhân. Một tên ác quỷ với gương mặt và thân thể bị biến dạng nắm trong tay nguồn nước khan hiếm ít ỏi của thành phố. Bộ Tam Nữ Hào hiệp buộc ra tay lần nữa để ngăn chặn quân đội lũng đoạn tàn sát dân thường và tìm nguồn nước để cứu thành phố.</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Trương Mạn Ngọc","avatar":""},{"name":"Dương Tử Quỳnh","avatar":""},{"name":"Mai Diễm Phương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324545);
