INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-huu', 'Chiến Hữu', 'GoodFellas', 'https://phimimg.com/upload/vod/20240103-1/d69b04d9e1533becf556304d14728a57.jpg', 'https://phimimg.com/upload/vod/20240103-1/0ef55c7a6dcb5d03cf599d2fee964d3d.jpg', '<p>Câu chuyện về Henry Hill và cuộc sống của anh ta trong đám đông, che đậy mối quan hệ của mình với vợ Karen Hill và các đối tác mob của ông Jimmy Conway và Tommy Devito trong Syndicate tội phạm người Ý-Mỹ.</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324545);
