INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-sat-thu-xinh-dep', 'Nữ Sát Thủ Xinh Đẹp', 'Lethal Panther', 'https://phimimg.com/upload/vod/20231231-1/65f0260c52a15f1c13fcfcbb7c08aebd.jpg', 'https://phimimg.com/upload/vod/20231231-1/4b70339ca3b3df8cc7d7cfb1cf7a03c9.jpg', '<p>Nữ Sát Thủ Xinh Đẹp (Kinh Thiên Long Hổ Báo) - Lethal Panther (1990) là một bộ phim hành động pha lẫn 18+ Hồng Kong của đạo diễn Godfrey Ho. Nội dung phim xoay quanh câu chuyện cuộc chiến giành địa bàn giữa các băng đảng trong thế lực ngầm tại Hương cảng, chẳng ai chịu nhường ai, cả hai phía đều sai nữ sát thủ của mình để tiêu diệt thủ lĩnh của đối phương. Liệu ai sẽ giành được phần thắng trong lần tranh đoạt địa bàn hoạt động này?</p>', 'Full', 1, 'single', 'completed', 16, 1990, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Sibelle Hu","avatar":""},{"name":"Maria Yuen Chi-Wai","avatar":""},{"name":"Yoko Miyamoto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324545);
