INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-cua-nhung-xac-chet', 'Đêm Của Những Xác Chết', 'Night Of The Living Dead', 'https://phimimg.com/upload/vod/20231231-1/80fb44f332aa3341dee1c7633d1fa05b.jpg', 'https://phimimg.com/upload/vod/20231231-1/4b0578684aea26f9d5259623bba651ef.jpg', '<p>Như thường lệ, năm nào, chị em Barbara và Johnny đều đến cắm hoa trên mộ của cha họ. Đường từ nhà đến đó rất xa, xung quanh là cả một khu nghĩa địa hoang vắng. Lần này, trong ít phút yên lặng để cầu nguyện cho cha, Johnny nhớ lại quãng thời gian anh còn bé, khi đó Johnny đã nói đùa với chị gái mình rằng: Họ đến để tìm chị đó, Barbara. Rồi màn đêm đã buông xuống, họ vẫn chưa rời mộ cha để trở về. Bỗng nhiên, một người đàn ông xuất hiện. Ông ta tiến gần về phía Barbara rồi bất ngờ tấn công và giết chết Johnny. Quá khiếp sợ, Barbara vùng chạy và trốn vào một ngôi nhà ở gần đó. Tại đây, cô gặp Ben cùng với nhiều người đang chạy trốn khác. Họ mở radio và biết được một tin khủng khiếp: các xác chết tấn công những người đang sống.</p>', 'Full', 1, 'single', 'completed', 12, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tony Todd","avatar":""},{"name":"Patricia Tallman","avatar":""},{"name":"Tom Towles","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324545);
