INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('misery', 'Misery', 'Misery', 'https://phimimg.com/upload/vod/20231230-1/0a41c526f482bf72cf4c992b960507fd.jpg', 'https://phimimg.com/upload/vod/20231230-1/1d31b90ff47b1b25f924d16e1b109072.jpg', '<p>Tiểu thuyết gia Paul Sheldon đâm xe trên con đường đầy tuyết ở Colorado. Anh ta được tìm thấy bởi Annie Wilkes, người hâm mộ số một của nữ anh hùng Misery Chastain của Paul. Annie cũng không ổn định một cách nguy hiểm, còn Paul thì thấy mình bị tàn tật, bị đánh thuốc mê và phải chịu sự thương xót của cô ấy.</p>', 'Full', 1, 'single', 'completed', 10, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Caan","avatar":""},{"name":"Kathy Bates","avatar":""},{"name":"Richard Farnsworth","avatar":""},{"name":"Frances Sternhagen","avatar":""},{"name":"Lauren Bacall","avatar":""},{"name":"Graham Jarvis","avatar":""},{"name":"Jerry Potter","avatar":""},{"name":"Thomas Brunelle","avatar":""},{"name":"June Christopher","avatar":""},{"name":"Julie Payne","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324545);
