INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-mat-thu-dich', 'Vượt Mặt Thù Địch', 'Miller''s Crossing', 'https://phimimg.com/upload/vod/20231219-1/4da5e48a2a4f990d0d3a673d80fcb0e2.jpg', 'https://phimimg.com/upload/vod/20231219-1/15c02f946192e200027ef1cda6ed214a.jpg', '<p>Lắng nghe trái tim mình, đó là lời nài nỉ của Bernie Bernbaum (John Turturro) khi quỳ gối trong một khu rừng mùa thu trước Gabriel Byrne (Tom Reagan) về việc có nên thực hiện lệnh của Johnny Caspar (Jon Polito). Đây là cảnh ấn tượng, khó quên và tuyệt nhất trong gia tài thể loại gangster noir của Anh em nhà Coen. Nội dung phim thông qua mối quan hệ giữa Tom Reagan và ông trùm tội phạm Leo OBannon kể về cuộc chiến giữa các băng nhóm đối thủ Ailen và Ý trong một thị trấn nhỏ...</p>', 'Full', 1, 'single', 'completed', 10, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gabriel Byrne","avatar":""},{"name":"Albert Finney","avatar":""},{"name":"Jon Polito","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"J.E. Freeman","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324545);
