INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-si-quyen-cuoc', 'Võ Sĩ Quyền Cước', 'The Young Kickboxers', 'https://phimimg.com/upload/vod/20231213-1/0741dcb9da6140ffb42d3475883ac174.jpg', 'https://phimimg.com/upload/vod/20231213-1/f1423e7f1d3113f896ab017ba1f79b48.jpg', '<p>Bộ phim Võ Sĩ Quyền Cước - The Young Kickboxers kể về Bách Xuân Lương - một người thợ đào vàng có võ công cao cường cùng đồng đội của mình đã tìm được một mỏ vàng vô cùng quý giá. Mọi người đã giao nhiệm vụ cho Xuân Lương đem một ít vàng về quê để hỏi vợ cho họ. Trong lúc đó, một người thợ tên Hắc Tử vì ghen tỵ mà đã phản bội đồng đội của mình, lập mưu cùng kẻ thù hòng chiếm lấy lấy mỏ vàng. Liệu Bách Xuân Lương liệu có thể kịp trở về để ngăn cản kế hoạch này hay không?</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Chao-Hsuan Hu","avatar":""},{"name":"Shiao-Hu Tso","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324545);
