INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giot-mau-cuoi-cung', 'Giọt Máu Cuối Cùng', 'The Last Blood', 'https://phimimg.com/upload/vod/20231211-1/abc7c99b198e86dd86285fbb0cdcba3a.jpg', 'https://phimimg.com/upload/vod/20231211-1/56f4c24c916f530bc6409b14d9f2e726.jpg', '<p>Giọt Máu Cuối Cùng - The Last Blood xoay quanh việc nhóm khủng bố Lữ Đoàn Đỏ lên kế hoạch giết Đạt Lai Lạt Ma nhân chuyến thăm của ông đến Singapore trong ngày quốc khánh. Theo lịch trình, ông sẽ gặp Ling May, một nữ nhân mang cùng lá số tử vi với ông. Nhưng khi vừa xuống sân bay, khung cảnh đã ngập máu.</p>', 'Full', 1, 'single', 'completed', 13, 1990, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Tăng Chí Vĩ","avatar":""},{"name":"Đàm Vĩnh Lân","avatar":""},{"name":"Lương Gia Nhân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324545);
