INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-ho-2', 'Lồng Hổ 2', 'Tiger Cage II', 'https://phimimg.com/upload/vod/20231211-1/7d12f73d7a40a75a59d13cb470ca121b.jpg', 'https://phimimg.com/upload/vod/20231211-1/738326755f7f52c9c4c42f8e097a0033.jpg', '<p>Một cựu cảnh sát và luật sư ly hôn hợp tác với một xã hội đen để xóa tên tuổi của họ sau khi tham gia vào một âm mưu tiền bẩn do một kẻ rửa tiền độc ác cầm đầu, kẻ có kế hoạch mở rộng kinh doanh và quét sạch bất kỳ ai cản đường anh ta.</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chân Tử Đan","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Carol ''Do Do'' Cheng","avatar":""},{"name":"David Wu","avatar":""},{"name":"Robin Shou","avatar":""},{"name":"Cynthia Khan","avatar":""},{"name":"Lieh Lo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324545);
