INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-an-tu-than', 'Dấu Ấn Tử Thần', 'Marked For Death', 'https://phimimg.com/upload/vod/20231208-1/8abe7f0c9bf9c3fb9f39b33350f4446a.jpg', 'https://phimimg.com/upload/vod/20231208-1/176b167f0ed46facc19818dd317297d8.jpg', '<p>Trinh thám Chicago DEA John Hatcher vừa mới trở về nhà từ Colombia, nơi mà một người bạn của anh đã bị giết bởi đường dây buôn thuốc phiện. Sau cái chết của người bạn, John quyết định xin nghỉ việc một thời gian. Nhưng một sự việc đã xảy ra sau khi anh gặp lại chị gái Melissa và con gái của cô. John đã buộc phải tham gia trận đấu súng chống lại tên trùm của ma tuý Jamaica - Screwface. Sau khi bị thua, hắn quyết định trả thù bằng cách tấn công chị gái và cháu John. Anh liền hợp nhất với Max, huấn luyện viên đội bóng, và Charles, cảnh sát chìm. Cả ba đã lao vào cuộc tìm kiếm Screwface để cứu lấy mạng sống của những người thân yêu</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steven Seagal","avatar":""},{"name":"Joanna Pacula","avatar":""},{"name":"Basil Wallace","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324545);
