INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-doan-phu-quy', 'Binh Đoàn Phú Quý', 'The Fortune Code', 'https://phimimg.com/upload/vod/20231207-1/9013fda7301d94a1a2a42c6e6d3f8307.jpg', 'https://phimimg.com/upload/vod/20231207-1/3b662b1ffd863309bf0833fd3f5d8de9.jpg', '<p>Binh Đoàn Phú Quý - The Fortune Code lấy bối cảnh cuộc chiến tranh thế giới thứ 2. Phim xoay quanh hành trình thanh niên tên Wah (Lưu Đức Hoa) truy tìm người giữ mật mã để có thể truy cập tài khoản ngân hàng Thụy Sĩ, có chứa một khoản tiền cực lớn. Nhiệm vụ của anh phải được hoàn thành trước khi những kẻ tàn ác nhận được mật mã và trước khi chúng tiêu diệt toàn bộ trại tập trung. Phim có những pha hành động đẹp mắt của Lưu Đức Hoa và Hồng Kim Bảo.</p>', 'Full', 1, 'single', 'completed', 19, 1990, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Hồng Kim Bảo","avatar":""},{"name":"Mai Diễm Phương","avatar":""},{"name":"Miêu Kiều Vỹ","avatar":""},{"name":"Trịnh Tắc Sĩ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324545);
