INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khieu-vu-voi-bay-soi', 'Khiêu Vũ Với Bầy Sói', 'Dances with Wolves', 'https://phimimg.com/upload/vod/20231201-1/d4f7dd68d313cb9cd4fbd48c2b2fce9b.jpg', 'https://phimimg.com/upload/vod/20231201-1/833b5f0643e4a234a69705b0180732c3.jpg', '<p>Đại tá John Dunbar thoát chết sau một cuộc giao tranh với một bên chân bị thương nặng. Đau đớn đến cùng cực tưởng như không thể chịu đựng được nữa, Dunbar tuyệt vọng và suýt nữa tự tử. Đột nhiên trong lúc tuyệt vọng và lang thang ở biên giới phía tây, Dunbar bắt gặp một con sói tên là Two-Socks và bộ lạc người da đỏ Sioux. Họ đã cứu anh. Tại đây anh gặp một cô gái da trắng được bộ lạc Siox cưu mang và nuôi dưỡng đã 10 năm trời. Tình cảm của họ nhanh chóng nảy nở...</p>', 'Full', 1, 'single', 'completed', 21, 1990, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kevin Costner","avatar":""},{"name":"Mary McDonnell","avatar":""},{"name":"Graham Greene","avatar":""},{"name":"Rodney A. Grant","avatar":""},{"name":"Floyd ''Red Crow'' Westerman","avatar":""},{"name":"Tantoo Cardinal","avatar":""},{"name":"Robert Pastorelli","avatar":""},{"name":"Charles Rocket","avatar":""},{"name":"Maury Chaykin","avatar":""},{"name":"Jimmy Herman","avatar":""},{"name":"Nathan Lee Chasing His Horse","avatar":""},{"name":"Michael Spears","avatar":""},{"name":"Jason R. Lone Hill","avatar":""},{"name":"Tony Pi","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324545);
