INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khieu-vu-voi-bay-soi', 'Khiêu Vũ Với Bầy Sói', 'Dances with Wolves', 'khiêu vũ với bầy sói dances with wolves kevin costner mary mcdonnell graham greene rodney a. grant floyd ''red crow'' westerman tantoo cardinal robert pastorelli charles rocket maury chaykin jimmy herman nathan lee chasing his horse michael spears jason r. lone hill tony pi ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-sat-thu-nikita', 'Nữ Sát Thủ Nikita', 'La Femme Nikita', 'https://phimimg.com/upload/vod/20231125-1/b669caa04a1fe961c37a056991df949d.jpg', 'https://phimimg.com/upload/vod/20231125-1/28323a3c6c379d7a6fab8d2a3f38c2dd.jpg', '<p>Nikita rất trẻ, cô đã hai mươi tuổi, nhưng nó đã lấy một con đường sai lầm. Trong một vụ cướp với băng đảng của ông, giết chết một cảnh sát và bị kết án tù chung thân. Dịch vụ bí mật, khuyết điểm, cung cấp cho anh ta một cách hiểu: để trở thành một đại lý đặc biệt, sẵn sàng cho bất cứ điều gì trong dịch vụ của họ. Phim Nữ Sát Thủ Nikita: Nikita đồng ý và bắt đầu học tập rất khó khăn cho không chỉ các chế độ khác nhau của giết chết, thoát ra khỏi hoặc đối phó với tình huống bất ngờ, nhưng còn làm thế nào để cư xử giống như một người phụ nữ có lớp, có khả năng lái xe một cách dễ dàng trong mọi môi trường. Dưới sự lãnh đạo của Bob, Nikita đến để kiềm chế nhân vật nổi loạn của mình và vượt qua các vòng chung kết khủng khiếp. Nó dường như đã trở thành một con người khác và rơi vào tình yêu. Nhưng chúng ta nên tin tưởng vào dịch vụ bí mật?</p>', 'Full', 1, 'single', 'completed', 16, 1990, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Anne Parillaud","avatar":""},{"name":"Jean-Hugues Anglade","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Marc Duret","avatar":""},{"name":"Jeanne Moreau","avatar":""},{"name":"Patrick Fontana","avatar":""},{"name":"Roland Blanche","avatar":""},{"name":"Jacques Boudet","avatar":""},{"name":"Jean Bouise","avatar":""},{"name":"Philippe du Janerand","avatar":""},{"name":"Alain Lathière","avatar":""},{"name":"Laura Chéron","avatar":""},{"name":"Pierre-Alain de Garrigues","avatar":""},{"name":"Helene Aligier","avatar":""},{"name":"Philippe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324545);
