INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-sat-thu-nikita', 'Nữ Sát Thủ Nikita', 'La Femme Nikita', 'nữ sát thủ nikita la femme nikita anne parillaud jean-hugues anglade tchéky karyo jean reno marc duret jeanne moreau patrick fontana roland blanche jacques boudet jean bouise philippe du janerand alain lathière laura chéron pierre-alain de garrigues helene aligier philippe ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-lan-tinh-giac', 'Những Lần Tỉnh Giấc', 'Awakenings', 'https://phimimg.com/upload/vod/20231125-1/bd779a8a0430dd92d84436325462360b.jpg', 'https://phimimg.com/upload/vod/20231125-1/c46c74fe6ceb0e08c065039c2973daf1.jpg', '<p>Bộ phim bắt đầu khi bác sĩ Malcolm Sayer (Robin Williams) người chưa từng có kinh nghiệm về lâm sàng, nhận nhiệm vụ mới ở một bệnh viện tâm thần với những bệnh nhân bị liệt não, không có thuốc chữa. Những bệnh nhân này mắc một thứ bệnh Catatonic - bại não, với hệ thần kinh tê liệt, không có nhận thức với cuộc sống xung quanh. Họ không bao giờ ý thức được những gì mình đang làm mà chỉ phản ứng lại với những tác động đặc biệt như đau đớn. Với lòng yêu thương con người, ông đã thử nghiệm loại thuốc mới và đã đưa được các bệnh nhân tưởng chừng đã mất liên lạc vĩnh viễn với thế giới bên ngoài - thức tỉnh. Bác sỹ Sayer vượt qua những nghi ngại của đồng nghiệp, vượt qua những lề thói suy nghĩ để đem đến một điều kỳ diệu ở bệnh viện. Từ đó, các bác sỹ khác và y tá nhận ra rằng, thẳm sâu trong những gương mặt vô cảm ấy, bệnh nhân của họ vẫn đang sống...</p>', 'Full', 1, 'single', 'completed', 11, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Robin Williams","avatar":""},{"name":"John Heard","avatar":""},{"name":"Julie Kavner","avatar":""},{"name":"Penelope Ann Miller","avatar":""},{"name":"Ruth Nelson","avatar":""},{"name":"Max von Sydow","avatar":""},{"name":"Anne Meara","avatar":""},{"name":"Dexter Gordon","avatar":""},{"name":"George Martin","avatar":""},{"name":"Alice Drummond","avatar":""},{"name":"Richard Libertini","avatar":""},{"name":"Laura Esterman","avatar":""},{"name":"Barton Heyman","avatar":""},{"name":"Judith Malina","avatar":""},{"name":"Mary Alice","avatar":""},{"name":"Keith Diamond","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324545);
