INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vit-donal-va-kho-bau-quoc-gia', 'Vịt Donal Và Kho Báu Quốc Gia', 'DuckTales: The Movie - Treasure of the Lost Lamp', 'https://phimimg.com/upload/vod/20231125-1/08d63012923d78c0240efa5e40c2b6bf.jpg', 'https://phimimg.com/upload/vod/20231125-1/178804a8c962be01b6f28aeb7d13c94c.jpg', '<p>DuckTales: The Movie - Treasure Of The Lost Lamp kể về bác vịt Scrooge McDuck và những nhân vật đầy màu sắc trong chuyến săn tìm kho báu vui nhộn. Cùng với những đứa cháu Huey, Dewey, Louie, và cô cháu gái Webbigail Vanderquack luôn sát cánh, người bác giàu có yêu thích của mọi người, Scrooge McDuck, khởi hành từ ngôi nhà tại Duckburg để tìm của cải mất tích từ lâu của tên trộm huyền thoại Collie Baba. Nhưng việc tìm kiếm không hề đơn giản như bác nghĩ! Cuộc phiêu lưu kỳ thú dẫn tới một sự hỗn loạn khôi hài và ma thuật, một bài học về việc có những thứ có giá trị hơn tiền, vàng và đồ trang sức.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 1990, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Alan Young","avatar":""},{"name":"Terence McGovern","avatar":""},{"name":"Russi Taylor","avatar":""},{"name":"Richard Libertini","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"June Foray","avatar":""},{"name":"Chuck McCann","avatar":""},{"name":"Joan Gerber","avatar":""},{"name":"Rip Taylor","avatar":""},{"name":"Charlie Adler","avatar":""},{"name":"Sherry Lynn","avatar":""},{"name":"Mickie McGowan","avatar":""},{"name":"Jack Angel","avatar":""},{"name":"Frank Welker","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324545);
