INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-gia-nu-tuong', 'Hoàng Gia Nữ Tướng', 'She Shoots Straight', 'https://phimimg.com/upload/vod/20231124-1/aff474a4d398cfe0c21a5842ab19493c.jpg', 'https://phimimg.com/upload/vod/20231124-1/ec8f63d6be46732c89fcd6a4c7319235.jpg', '<p>She Shoots Straight bắt đầu từ chuyện tình lãng mạn và hôn nhân tại nơi làm việc giữa một nữ cảnh sát tên là Mina Kao (Joyce Godenzi) và thanh tra Huang Tsung-pao (Lương Gia Huy). Tuy nhiên, gia đình của Huang luôn phản đối cuộc hôn nhân này. Trong khi đó, một nữ cảnh sát vốn người em chồng tương lai của Mina là Chia-ling (Lưu Gia Linh) đặc biệt phê bình về sự thiên vị, và thậm chí còn nhận xét về cô ấy là người Âu Á khi mà quá hiện đại và phóng khoáng. &nbsp;Mọi việc trở nên phức tạp khi mà một băng nhóm người Việt Nam được cầm đầu bởi Yuan Hua (Nguyên Hoa) cố gắng thực hiện một vụ cướp tài sản có vũ trang. Sau khi băng đảng bị cản trở, một cuộc đọ súng xảy ra trong đó cảnh sát có người bị thường. Trao trả thù, Yuan Hua đặt một cái bẫy chặn lại bằng cách sử dụng thiết bị chiến tranh ở rừng Việt Nam. Chia-ling lúc này một mình thực hiện nhiệm vụ nên gặp nguy hiểm, Mina và Tsung-po cứu cô, nhưng Tsung-po đã bị giết bởi một cái bẫy, chết trước em gái và cô dâu.</p>', 'Full', 1, 'single', 'completed', 16, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Joyce Godenzi","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Tang Pik-Wan","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Sarah Lee Lai-Yui","avatar":""},{"name":"Angile Leung Wan Yui","avatar":""},{"name":"Sandra Ng Kwan-Yue","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Agnes Aurelio","avatar":""},{"name":"Sammo Hung","avatar":""},{"name":"David Lau","avatar":""},{"name":"Wan Fat","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Teddy Yip Wing-Cho","avatar":""},{"name":"Paul Chung Fat","avatar":""},{"name":"Amy Yip","avatar":""},{"name":"Corey Yuen","avatar":""},{"name":"Kwan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324545);
