INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('48-gio-nua', '48 Giờ Nữa', 'Another 48 Hrs.', 'https://phimimg.com/upload/vod/20231123-1/ba2f075358fe447c96027f16ea8d52b0.jpg', 'https://phimimg.com/upload/vod/20231123-1/fe66cbca5da4c1c95e69ad18de86caff.jpg', '<p>Nội dung phim xoay quanh nhân vật viên cảnh sát Jack Cates với nhiệm vụ theo đuổi tên trùm buôn ma túy Iceman. Trong suốt 4 năm, viên cảnh sát Jack Cates theo đuổi tên trùm buôn ma tuý Iceman. Trong 1 cuộc đụng độ với Tyrone Burroughs và Arthur Brock, Jack đã buộc phải giết Brock để tự vệ nhưng Burroughs đã trốn thoát. Jack phải đối mặt với một án tù do khẩu súng của Brock không được tìm thấy. Và ngay trong ngày đầu tiên ra tù của Reggie Hammond – một tay lừa bịp nổi tiếng, Jack đã phải thuyết phục anh chàng này giúp đỡ làm trong sạch tên tuổi của mình và tóm gọn Iceman.</p>', 'Full', 1, 'single', 'completed', 14, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Brion James","avatar":""},{"name":"Kevin Tighe","avatar":""},{"name":"Ed O''Ross","avatar":""},{"name":"David Anthony Marshall","avatar":""},{"name":"Andrew Divoff","avatar":""},{"name":"Bernie Casey","avatar":""},{"name":"Brent Jennings","avatar":""},{"name":"Ted Markland","avatar":""},{"name":"Tisha Campbell","avatar":""},{"name":"Felice Orlandi","avatar":""},{"name":"Edward Walsh","avatar":""},{"name":"Page Leong","avatar":""},{"name":"Cathy Haase","avatar":""},{"name":"Dennis Hayden","avatar":""},{"name":"Kelly L. Goodman","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"