INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-vien-cuu-ho-2', 'Nhân Viên Cứu Hộ 2', 'The Rescuers Down Under', 'https://phimimg.com/upload/vod/20231114-1/6f8ad37eaa04bfcfe602874ef29e2120.jpg', 'https://phimimg.com/upload/vod/20231114-1/f5c389eb2a3aae89b9817cf57ed8257c.jpg', '<p>Từ sự thành công của bộ phim The Rescuers 1977 , người ta đã làm một bộ nối tiếp có tên là The Rescuers Down Under vào năm 1990. Cody, cậu bé từ vùng Mugwomp đã vô tình giải cứu Marahute và lạc vào chuyến phiêu lưu kỳ thú.
 Lần này, Bernard và Bianca nhận nhiệm vụ đến Úc để giải cứu cho cậu bé Cody và một con đại bàng vàng thuộc giống loài cực hiếm khỏi tay bọn săn trộm nguy hiểm.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bob Newhart","avatar":""},{"name":"Eva Gabor","avatar":""},{"name":"John Candy","avatar":""},{"name":"Tristan Rogers","avatar":""},{"name":"Adam Ryen","avatar":""},{"name":"George C. Scott","avatar":""},{"name":"Wayne Robson","avatar":""},{"name":"Douglas Seale","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Bernard Fox","avatar":""},{"name":"Peter Firth","avatar":""},{"name":"Ed Gilbert","avatar":""},{"name":"Carla Meyer","avatar":""},{"name":"Russi Taylor","avatar":""},{"name":"Peter Greenwood","avatar":""},{"name":"Billy Barty","avatar":""},{"name":"Mickie McGowan","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324545);
