INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('her-fatal-ways', 'Her Fatal Ways', 'Her Fatal Ways', 'https://phimimg.com/upload/vod/20231114-1/8dcad639c6ae96c27fe9d132e905539f.jpg', 'https://phimimg.com/upload/vod/20231114-1/bb540106f2ab2417af4f48ef467da1c1.jpg', '<p>Thanh tra cảnh sát Trung Quốc đại lục xinh đẹp Cousin buộc phải làm việc với một cảnh sát Hồng Kông, chiến đấu chống lại anh ta gần như cho đến cuối danh sách tín dụng, khi cô ấy tiết lộ nhiều hơn các bằng chứng Cộng sản của mình.</p>', 'Full', 1, 'single', 'completed', 17, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Carol Cheng","avatar":""},{"name":"Alfred Cheung Kin-Ting","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Lam Kau","avatar":""},{"name":"Michael Chow Man-Kin","avatar":""},{"name":"Sheila Chan Suk-Lan","avatar":""},{"name":"Sunny Fang Kang","avatar":""},{"name":"Walter Tso Tat-Wah","avatar":""},{"name":"Lam Chung","avatar":""},{"name":"Emotion Cheung Kam-Ching","avatar":""},{"name":"Ku Ming-Wah","avatar":""},{"name":"Dion Lam Dik-On","avatar":""},{"name":"Woo Maan-Yam","avatar":""},{"name":"Leung Chui-Hung","avatar":""},{"name":"Lee Yiu-Ging","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324545);
