INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-keo-hoc-yeu', 'Người Kéo Học Yêu', 'Edward Scissorhands', 'https://phimimg.com/upload/vod/20231114-1/ca6456c93071ad06a33d04704aa58d83.jpg', 'https://phimimg.com/upload/vod/20231114-1/8c957ba4005937605f4bfcfa97ef2794.jpg', '<p>Phim kể về Edward Scissorhands (Johnny Depp) - một &quot;sản phẩm&quot; có bàn tay gắn đầy kéo được tạo ra bởi nhà khoa học điên loạn. Anh rơi vào tình yêu với Kim Boggs (do Winona Ryder thủ vai) dù cô đã có bạn trai. Kể từ đó, Edward bắt đầu hành trình chinh phục trái tim người đẹp và nhờ đó hiểu hơn về chính mình.</p>', 'Full', 1, 'single', 'completed', 13, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Johnny Depp","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Dianne Wiest","avatar":""},{"name":"Alan Arkin","avatar":""},{"name":"Anthony Michael Hall","avatar":""},{"name":"Vincent Price","avatar":""},{"name":"Kathy Baker","avatar":""},{"name":"Robert Oliveri","avatar":""},{"name":"Conchata Ferrell","avatar":""},{"name":"Caroline Aaron","avatar":""},{"name":"Dick Anthony Williams","avatar":""},{"name":"O-Lan Jones","avatar":""},{"name":"Susan Blommaert","avatar":""},{"name":"Linda Perri","avatar":""},{"name":"John Davidson","avatar":""},{"name":"Biff Yeager","avatar":""},{"name":"Donna Pi","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324545);
