INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-nha-pacific-heights', 'Khu Nhà Pacific Heights', 'Pacific Heights', 'https://phimimg.com/upload/vod/20231115-1/95223d67673ef75d58824252648128d7.jpg', 'https://phimimg.com/upload/vod/20231115-1/e31eccde9e8f16e9b4c23e5679e91282.jpg', '<p>Một cặp vợ chồng làm việc chăm chỉ để cải tạo ngôi nhà mơ ước của họ và trở thành chủ nhà để trả tiền cho nó. Thật không may, một trong những người thuê nhà của họ có kế hoạch của riêng mình.</p>', 'Full', 1, 'single', 'completed', 13, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Melanie Griffith","avatar":""},{"name":"Matthew Modine","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Mako","avatar":""},{"name":"Nobu McCarthy","avatar":""},{"name":"Laurie Metcalf","avatar":""},{"name":"Carl Lumbly","avatar":""},{"name":"Dorian Harewood","avatar":""},{"name":"Luca Bercovici","avatar":""},{"name":"Tippi Hedren","avatar":""},{"name":"Sheila McCarthy","avatar":""},{"name":"Guy Boyd","avatar":""},{"name":"Jerry Hardin","avatar":""},{"name":"Dan Hedaya","avatar":""},{"name":"James Staley","avatar":""},{"name":"Miriam Margolyes","avatar":""},{"name":"Takayo Fischer","avatar":""},{"name":"Frank D","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324545);
