INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hnery-gia-coi', 'Hnery Gìa Cỗi', 'Henry & June', 'https://phimimg.com/upload/vod/20231107-1/de50580cac985d3f7e18cb26d002b8ae.jpg', 'https://phimimg.com/upload/vod/20231107-1/9dec2f5e72faa4671ea582acf6a5a3f9.jpg', '<p>Trong khi đi du lịch ở Paris, tác giả Henry Miller và vợ của mình, June, gặp Anais Nin, và những tia lửa tình dục bùng lên khi Nin bắt đầu mối quan hệ tình cảm với một người lưỡng tính công khai June. Khi June buộc phải quay trở lại Mỹ, cô đã ban phước lành cho Nin được ngủ với chồng mình. Sau đó, khi June trở lại Pháp, một hình thức ba người bất ngờ, và đôi khi gây tranh cãi.</p>', 'Full', 1, 'single', 'completed', 17, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Fred Ward","avatar":""},{"name":"Uma Thurman","avatar":""},{"name":"Maria de Medeiros","avatar":""},{"name":"Kevin Spacey","avatar":""},{"name":"Bruce Myers","avatar":""},{"name":"Juan Luis Buñuel","avatar":""},{"name":"Féodor Atkine","avatar":""},{"name":"Sylvie Huguel","avatar":""},{"name":"Artus de Penguern","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Gary Oldman","avatar":""},{"name":"Brigitte Lahaie","avatar":""},{"name":"Jean-Philippe Écoffey","avatar":""},{"name":"Erika Maury-Lascoux","avatar":""},{"name":"Maïté Maillé","avatar":""},{"name":"Annie Fratel","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324545);
