INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ke-nhi-tai', 'Nhất Kế Nhì Tài', 'No Risk, No Gain', 'https://phimimg.com/upload/vod/20231103-1/2067e3d44953d7ef997ab6799c9aacdb.jpg', 'https://phimimg.com/upload/vod/20231103-1/bdab0a4dfff8f6002185b7d6062c7454.jpg', '<p>Nội dung của phim xoay quanh tay trùm cờ bạc có năng khiếu bẩm sinh với tài năng xuất chúng tên là Ray (Đàm Vịnh Lân), anh ta đồng thời đang làm cố vấn cho những sòng bài danh tiếng của Mỹ. Trong sự nghiệp của mình, anh đã từng đối đầu với rất nhiều những thử thách nhưng tất cả đều được anh ta vượt qua một cách không quá khó khăn, tuy nhiên chỉ đến khi đối thủ tên Chiang thực sự xuất hiện với biệt danh “Mắt hổ”, người đã thách thức Ray so tài với anh ta tại Macao, thì lúc này cuộc phiêu lưu của Ray mới thực sự bắt đầu trở lại.</p>', 'Full', 1, 'single', 'completed', 16, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Anthony Wong","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Natalis Chan","avatar":""},{"name":"Alan Tam","avatar":""},{"name":"Michelle Reis","avatar":""},{"name":"Christine Ng","avatar":""},{"name":"Chan Chung-Yung","avatar":""},{"name":"May Lo Mei-Wei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324545);
