INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-cua-lulu', 'Thời Đại Của Lulu', 'The Ages of Lulu', 'https://phimimg.com/upload/vod/20231101-1/85f9abd1ea6e79639ffb6a9522962c22.jpg', 'https://phimimg.com/upload/vod/20231101-1/3ae171f8b8c36226a2d5f1d899994813.jpg', '<p>Cô bé Lulu mười lăm tuổi chưa từng biết đến bất cứ tình cảm nào từ gia đình. Nhưng khi cô ấy đi xem một buổi hòa nhạc rock với Pablo, một người bạn của gia đình, anh ấy đã giới thiệu cho Lulu trải nghiệm tình dục đầu tiên của cô ấy. Nhiều năm sau, Pablo và Lulu kết hôn; Pablo đã tạo ra một thế giới riêng tư, được che chở cho Lulu, không gì có thể xâm phạm vào. Tuy nhiên, Lulu cảm thấy mệt mỏi với sự tồn tại của mình, và bắt đầu lang thang trong các quán bar râm mát, tìm kiếm cảm giác mạnh và nguy hiểm gián tiếp.</p>', 'Full', 1, 'single', 'completed', 18, 1990, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[{"name":"Francesca Neri","avatar":""},{"name":"Óscar Ladoire","avatar":""},{"name":"María Barranco","avatar":""},{"name":"Fernando Guillén Cuervo","avatar":""},{"name":"Rosana Pastor","avatar":""},{"name":"Javier Bardem","avatar":""},{"name":"Juan Graell","avatar":""},{"name":"Rodrigo Valverde","avatar":""},{"name":"Pilar Bardem","avatar":""},{"name":"Marta May","avatar":""},{"name":"Pepa Serrano","avatar":""},{"name":"Luis Amposta","avatar":""},{"name":"Tomás Ordóñez","avatar":""},{"name":"Ángel Fernández","avatar":""},{"name":"Leonor Bruna","avatar":""},{"name":"Pep Corominas","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324545);
