INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-dau-thu-thach-2-kho-chet-hon', 'Đương Đầu Thử Thách 2: Khó Chết Hơn', 'Die Hard 2', 'https://phimimg.com/upload/vod/20231023-1/582e79261a8123c1b9fe73b255b5c940.jpg', 'https://phimimg.com/upload/vod/20231023-1/5450c27169c9bf6ccdc0e53767e58837.jpg', '<p>Sau sự cố ở Los Angeles, dường như McClane lại lần nữa không may khi gặp bọn khủng bố khác. Một nhóm khủng bố dẫn đầu bởi Col Stuart (William Sadler) đã dùng vũ lực để ép toàn bộ sân bay quốc tế Dulles ở Washington DC làm con tin. Bọn chúng kiểm sát tất cả các thiết bị điện tử điều hướng ở sân bay nhằm mục đích yêu sách giải cứu tên trùm ma túy.</p>', 'Full', 1, 'single', 'completed', 16, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Bonnie Bedelia","avatar":""},{"name":"William Sadler","avatar":""},{"name":"Art Evans","avatar":""},{"name":"Dennis Franz","avatar":""},{"name":"William Atherton","avatar":""},{"name":"John Amos","avatar":""},{"name":"Fred Thompson","avatar":""},{"name":"Tom Bower","avatar":""},{"name":"Franco Nero","avatar":""},{"name":"Sheila McCarthy","avatar":""},{"name":"Reginald VelJohnson","avatar":""},{"name":"Don Harvey","avatar":""},{"name":"Tony Ganios","avatar":""},{"name":"Peter Nelson","avatar":""},{"name":"Robert Patrick","avatar":""},{"name":"Mick Cunningham","avatar":""},{"name":"John L","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324545);
