INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('duong-dau-thu-thach-2-kho-chet-hon', 'Đương Đầu Thử Thách 2: Khó Chết Hơn', 'Die Hard 2', 'đương đầu thử thách 2: khó chết hơn die hard 2 bruce willis bonnie bedelia william sadler art evans dennis franz william atherton john amos fred thompson tom bower franco nero sheila mccarthy reginald veljohnson don harvey tony ganios peter nelson robert patrick mick cunningham john l ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ba-dep', 'Người Đàn Bà Đẹp', 'Pretty Woman', 'https://phimimg.com/upload/vod/20231020-1/02f49371bd2f95894584c591e15c939b.jpg', 'https://phimimg.com/upload/vod/20231020-1/d71e8d40cb5f0e27e678b264d7462a2d.jpg', '<p>Câu chuyện tình của nàng Lọ lem thời hiện đại giữa khu phố xa hoa Berverly Hill của Hollywood đã làm đắm say biết bao người khi bộ phim Người đàn bà đẹp - Pretty Woman lần đầu ra rạp năm 1990. Lối diễn xuất duyên dáng cùng nụ cười toả sáng của Julia Robert trong vai cô gái đứng đường đã làm xiêu lòng không chỉ chàng doanh nhân giàu có bậc nhất Hollywood do tài tử Richard Gere thủ vai mà còn xiêu lòng những vị khán giả khó tính nhất. Một cốt truyện cổ điển khi chàng &quot;hoàng tử&quot; bỏ tiền thuê cô gái xinh đẹp làm bạn gái trong một tuần với mức giá vô cùng hậu hĩnh, để rồi tình yêu chớm nở giữa hai con người cách biết về thân phận và địa vị xã hội. Nhưng bằng góc quay đậm chất lãng mạn với thông điệp tình yêu vượt mọi rào cản, Người đàn bà đẹp là một trong những bộ phim tình cảm hay nhất mọi thời đại.</p>', 'Full', 1, 'single', 'completed', 15, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Gere","avatar":""},{"name":"Julia Roberts","avatar":""},{"name":"Ralph Bellamy","avatar":""},{"name":"Jason Alexander","avatar":""},{"name":"Laura San Giacomo","avatar":""},{"name":"Alex Hyde-White","avatar":""},{"name":"Amy Yasbeck","avatar":""},{"name":"Elinor Donahue","avatar":""},{"name":"Hector Elizondo","avatar":""},{"name":"Judith Baldwin","avatar":""},{"name":"Jason Randal","avatar":""},{"name":"Bill Applebaum","avatar":""},{"name":"Tracy Bjork","avatar":""},{"name":"Gary Greene","avatar":""},{"name":"Billy Gallo","avatar":""},{"name":"Abdul Salaam El Razzac","avatar":""},{"name":"Han","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324545);
