INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ma', 'Hồn Ma', 'Ghost', 'https://phimimg.com/upload/vod/20231019-1/83b51c8f9bf5fbd7acb82cb968d47fe5.jpg', 'https://phimimg.com/upload/vod/20231019-1/ec01863556ea877eeaae84aa31eeac89.jpg', '<p>Nội dung phim xoay quanh tình yêu bất diệt của cặp uyên ương Sam (Patrick Swayze) và Molly (Demi Moore). Trước khi phải chia xa mãi mãi, Sam và Molly từng có những tháng ngày hạnh phúc bên nhau trong một ngôi nhà nhỏ tại New York.</p>', 'Full', 1, 'single', 'completed', 16, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Swayze","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Whoopi Goldberg","avatar":""},{"name":"Tony Goldwyn","avatar":""},{"name":"Vincent Schiavelli","avatar":""},{"name":"Rick Aviles","avatar":""},{"name":"Martina Deignan","avatar":""},{"name":"Rick Kleber","avatar":""},{"name":"Phil Leeds","avatar":""},{"name":"Armelia McQueen","avatar":""},{"name":"Gail Boggs","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Alma Beltran","avatar":""},{"name":"Vivian Bonnell","avatar":""},{"name":"Derek Thompson","avatar":""},{"name":"Tom Finnegan","avatar":""},{"name":"Bruce Jarchow","avatar":""},{"name":"Sai","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324545);
