INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ngay-sam-day', 'Những Ngày Sấm Dậy', 'Days of Thunder', 'https://phimimg.com/upload/vod/20231016-1/4a54817dac41e5124a9f914e25f488c8.jpg', 'https://phimimg.com/upload/vod/20231016-1/e0892efc57b5de0486f5d706028b5ebc.jpg', '<p>Cole Trickle, tay lái trẻ có khả năng điều khiển xe tuyệt vời nhưng còn non kinh nghiệm. Được nhà tài phiệt Tim Dolan tuyển mộ vào để tham gia đua giải Nascar lừng danh, Cole rất nóng lòng chứng tỏ cho các đàn anh thấy anh giỏi thế nào. Thái độ khoe mẽ của tài năng trẻ này khiến anh gặp vấn đề với không chỉ những bậc tiền bối mà cả các đồng đội của mình. Days of Thunder được nhớ tới nhiều không chỉ bởi đây là phim của Tom Cruise mà còn vì đây là tác phẩm đưa anh tới với người vợ thứ hai Nicole Kiman – nữ bác sĩ phẫu thuật xinh đẹp Claire trong phim.</p>', 'Full', 1, 'single', 'completed', 14, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Robert Duvall","avatar":""},{"name":"Nicole Kidman","avatar":""},{"name":"Randy Quaid","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Michael Rooker","avatar":""},{"name":"Fred Thompson","avatar":""},{"name":"John C. Reilly","avatar":""},{"name":"J.C. Quinn","avatar":""},{"name":"Don Simpson","avatar":""},{"name":"Caroline Williams","avatar":""},{"name":"Margo Martindale","avatar":""},{"name":"Michael Burgess","avatar":""},{"name":"Gerald R. Molen","avatar":""},{"name":"Donna W. Scott","avatar":""},{"name":"Leilani Sarelle","avatar":""},{"name":"Chris Ellis","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20