INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-dat-khong-lo', 'Sâu Đất Khổng Lồ', 'Tremors', 'https://phimimg.com/upload/vod/20231015-1/bc2a58c2df45c4c3d20b711dcced2562.jpg', 'https://phimimg.com/upload/vod/20231015-1/3e72b0c992fe59a45b6f13cec75f9dfd.jpg', '<p>Một thị trấn nhỏ dần dần trở thành mục tiêu của một sinh vật kỳ lạ sống ẩn trong lòng đất. Nhưng sinh vật này là gì, và nó ở đâu?Cùng thời gian đó, một nhà địa chấn học nữ đang làm việc trong khu vực. Cô phát hiện ra các chấn động do lũ quái trong lòng đất gây ra. Chúng có thể xuất hiện bất ngờ không báo trước.Bị mắc kẹt trong chính thị trấn của mình, những người dân nơi đây không có lối thoát…</p>', 'Full', 1, 'single', 'completed', 18, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Bacon","avatar":""},{"name":"Fred Ward","avatar":""},{"name":"Finn Carter","avatar":""},{"name":"Michael Gross","avatar":""},{"name":"Reba McEntire","avatar":""},{"name":"Victor Wong","avatar":""},{"name":"Robert Jayne","avatar":""},{"name":"Ariana Richards","avatar":""},{"name":"Charlotte Stewart","avatar":""},{"name":"Tony Genaro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324545);
