INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-tim-tau-ngam-thang-muoi-do', 'Săn Tìm Tàu Ngầm Tháng Mười Đỏ', 'The Hunt for Red October', 'https://phimimg.com/upload/vod/20231015-1/6eb5ebb621abc03544e4c6f64cc4ea5a.jpg', 'https://phimimg.com/upload/vod/20231015-1/3e4028e8b45ac07f3cdbec42dcf5d4ec.jpg', '<p>Thuyền Trưởng Marko Ramius của Hải Quân Sô Viết mặc quần áo lạnh cho điều kiện bình thường của Hạm Đội Tầu Ngầm Bắc Cực ở cảng Polyarnyy. Năm lớp long cừu và da đóng kín ông ta lại. Một chiếc tàu kéo dơ dáy đẩy đầu chiếc tầu ngầm vòng tới hướng bắc, đâu mặt với dòng sông. Bến tầu đã giam chiếc tầu Red October của ông ta hai tháng rồi bây giờ chỉ còn là một hộp si măng đầy nước, một trong nhiều cái được xây đặc biệt để chứa tầu ngầm tên lửa chiến lược từ điều kiện khó khăn xung quanh. Vòng ngoài là lính thủy và công nhân bến tầu nhìn chiếc tầu rời bến trong sự phớt lạnh của người Nga, không vẫy tay không đón chào.“Máy tầu thẳng tới chậm thôi, Kamarov” Ramius ra lệnh. Tầu kéo rời xa ra, và Ramius nhìn ra sau ...</p>', 'Full', 1, 'single', 'completed', 12, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Connery","avatar":""},{"name":"Alec Baldwin","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"Joss Ackland","avatar":""},{"name":"Richard Jordan","avatar":""},{"name":"Peter Firth","avatar":""},{"name":"Tim Curry","avatar":""},{"name":"Courtney B. Vance","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324545);
