INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-gia-3', 'Bố Già 3', 'The Godfather Part III', 'https://phimimg.com/upload/vod/20231014-1/d17752199ad6fdb380e89ee9e3c36b34.jpg', 'https://phimimg.com/upload/vod/20231014-1/5fabf9c6bb1692c63274117488b0f0a9.jpg', '<p>The Godfather Part III là phần 3 và cũng là phần cuối cùng của loạt phim The Godfather. Lúc này, Michael Corleone đã trở thành một người giàu có và đầy quyền lực sau những cuộc thanh toán và âm mưu, đã bắt đầu đối diện với tuổi già và cảm giác tội lỗi về những tội ác khủng khiếp ông ta đã gây ra trong những năm trước đó. Bố già bắt đầu lo lắng cho những đứa con của ông ta, về tương lai, hạnh phúc của chúng. Michael Corleone trở về Thành phố New York, nơi ông ta sử dụng quyền lực và tiền bạc có được để xây dựng cho mình hình ảnh trước công chúng như một người có nhân cách và địa vị cao quý. Một trong những biện pháp Michael dùng để cố gắng xóa bỏ quá khứ tội ác của nhà Corleone là thành lập quỹ từ thiện Vito Corleone. Tưởng đâu quá khứ sẽ ngủ yên với danh vị đẹp đẽ nhưng số phận không để yên khi các băng đảng khác vẫn nuôi mối thù...</p>', 'Full', 1, 'single', 'completed', 18, 1990, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Al Pacino","avatar":""},{"name":"Diane Keaton","avatar":""},{"name":"Talia Shire","avatar":""},{"name":"Andy García","avatar":""},{"name":"Eli Wallach","avatar":""},{"name":"Joe Mantegna","avatar":""},{"name":"George Hamilton","avatar":""},{"name":"Bridget Fonda","avatar":""},{"name":"Sofia Coppola","avatar":""},{"name":"Raf Vallone","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324545);
