INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-gap-go-ngan-ngui-o-shinjuku', 'Cuộc gặp gỡ ngắn ngủi ở Shinjuku', 'Brief Encounter in Shinjuku', 'https://phimimg.com/upload/vod/20231014-1/e2b5d3b09b6228bd094b2d4a831b0bae.jpg', 'https://phimimg.com/upload/vod/20231014-1/667741083bd569aa90777c345d011cbe.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Một bản phác thảo cảm xúc đô thị, nhân vật chính là A Kuan (do Zheng Danrui thủ vai) - một người đàn ông thành thị nhỏ bé, không trung thành với cảm xúc của mình và thường pha trò. Ah Kuan và vợ Anna (do Zheng Yuling thủ vai) đã quay lại với nhau, và cả hai có thể đã sống một cuộc sống hài hòa. Sự xuất hiện của cô thư ký nhỏ khiến Ah Kuan có một trái tim khác. Cô liều lĩnh và khó chịu trước những người cầu hôn, điều này khiến Ah Kuan chăm sóc cô rất tốt vào các ngày trong tuần, điều này khiến người đẹp thầm yêu. Một chuyến công tác hai ngày đến Nhật Bản đã biến thành một nơi nghỉ ngơi lãng mạn.</span><br/><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Tuy nhiên, sau khi trở về Hồng Kông, cô thư ký nhỏ quyết định kết hôn với bạn trai nha sĩ, và cô giải thích với Anna rằng cô và Ah Kuan chỉ là đồng nghiệp. Tuy nhiên, tờ giấy không thể khống chế ngọn lửa, nha sĩ và Anna biết rằng họ có mối quan hệ cá nhân, vì vậy người đàn ông nhỏ bé Ah Kuan phải đối mặt với một thử thách cảm xúc khác.</span></p>', 'Full', 1, 'single', 'completed', 17, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lawrence Cheng","avatar":""},{"name":"Carol Cheng","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Manfred Wong","avatar":""},{"name":"Chow Mei-Fung","avatar":""},{"name":"Peter Lai Bei-Dak","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Eric Yeung Jan-Yiu","avatar":""},{"name":"Lee Chung-Ling","avatar":""},{"name":"Chang Gan-Wing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324545);
