INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-gap-go-ngan-ngui-o-shinjuku', 'Cuộc gặp gỡ ngắn ngủi ở Shinjuku', 'Brief Encounter in Shinjuku', 'cuộc gặp gỡ ngắn ngủi ở shinjuku brief encounter in shinjuku lawrence cheng carol cheng rosamund kwan manfred wong chow mei-fung peter lai bei-dak kenneth tsang eric yeung jan-yiu lee chung-ling chang gan-wing ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nu-u-hon-2', 'Thiện Nữ U Hồn 2', 'A Chinese Ghost Story 2', 'https://phimimg.com/upload/vod/20231012-1/7f9b8e30a97abdfc9c6beaa12ad7b66e.jpg', 'https://phimimg.com/upload/vod/20231012-1/7ed29d1ad5b90ff818c3801b6da4288e.jpg', '<p>Ling Choi Sin bị quan quân bắt nhầm vào ngục. Tại đây, anh quen một bậc tiền bối uyên bác, người giúp anh thoát khỏi nơi này. Trên đường đi, Ling tình cờ gặp hai chị em Windy và Moon, con gái của ngài Fu, đang bị bọn gian thần giam giữ. Hai chị em đều phải lòng anh chàng đẹp trai nhưng trái tim của Ling chỉ hướng về Windy, cô gái có khuôn mặt giống hệt hồn ma của Lit Siu Seen. Cùng nhau họ lập kế hoạch giải cứu cha của Windy và được sự giúp đỡ của chàng pháp sư trẻ Yen…</p>', 'Full', 1, 'single', 'completed', 19, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Leslie Cheung","avatar":""},{"name":"Joey Wong","avatar":""},{"name":"Jacky Cheung","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Waise Lee","avatar":""},{"name":"Michelle Reis","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Lau Siu-Hung","avatar":""},{"name":"Wong Yue-Chun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324545);
