INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loan-the-nhi-nu', 'Loạn Thế Nhi Nữ', 'Shanghai Shanghai', 'https://phimimg.com/upload/vod/20231010-1/a88819d032c665050381424ca4e90af6.jpg', 'https://phimimg.com/upload/vod/20231010-1/0ed1588c44839c33b70b221212f1e4ce.jpg', '<p>Người anh Đại Hổ là một cảnh sát thanh liêm, chính trực làm việc trong hệ thống phòng chống tham nhũng, còn người em Tiểu Hổ là một chàng trai trẻ tuổi đang đi kiếm anh trai mình. Tiểu Hổ vô tình phát hiện ra đường dây phạm tội của một tay giang hồ có tiếng là Chin Hung Yun (Hồng Kim Bảo) nên anh đã lên kế hoạch xâm nhập vào tổ chức đó nhằm tiêu diệt chúng. Tuy nhiên, cảnh sát đã hiểu lầm Tiểu Hổ là một trong những tay xã hội đen nên đã bắt anh, vì vậy mà Đại Hổ đã phải đối đầu với phe cảnh sát để cứu em trai mình ra.</p>', 'Full', 1, 'single', 'completed', 15, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"George Lam Chi-Cheung","avatar":""},{"name":"Tien Niu","avatar":""},{"name":"Anita Mui","avatar":""},{"name":"Sandy Lam","avatar":""},{"name":"Richard Yuen Tak","avatar":""},{"name":"Mang Hoi","avatar":""},{"name":"Sam Wong Ming-Sing","avatar":""},{"name":"Lo Lieh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324545);
