INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-ngao-giang-ho', 'Tiếu Ngạo Giang Hồ', 'Swordsman', 'https://phimimg.com/upload/vod/20231010-1/fd6355d36576e29d144a08e3de2aabab.jpg', 'https://phimimg.com/upload/vod/20231010-1/0bd2eaca5a62839b2c58f09270539c6f.jpg', '<p>Vào những năm cuối của triều đại nhà Minh, một cuộn sách chứa bí mật võ thuật rất có giá trị của Hoàng Đế bị đánh cắp, một đội quân được điều đi để tìm kẻ lấy cắp và lấy lại nó.</p>', 'Full', 1, 'single', 'completed', 22, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sam Hui","avatar":""},{"name":"Cecilia Yip","avatar":""},{"name":"Jacky Cheung","avatar":""},{"name":"Sharla Cheung","avatar":""},{"name":"Fennie Yuen","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Shun Lau","avatar":""},{"name":"Lam Ching-Ying","avatar":""},{"name":"Wu Ma","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324545);
