INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-canh-do-long-2', 'Đặc Cảnh Đồ Long 2', 'Tiger Cage 2', 'https://phimimg.com/upload/vod/20231010-1/f0e1660656e20ad07a116d9d96115bd3.jpg', 'https://phimimg.com/upload/vod/20231010-1/f3d3a147cd6b147e141b064578cdb0a1.jpg', '<p>Alan là một cảnh sát cừ khôi bị kết tội mưu sát một cách oan ức. Cùng với cô luật sư xinh đẹp Mary, và luật sư David, 3 bọn họ quyết tâm truy tìm cho ra những người đã hãm hại họ.</p>', 'Full', 1, 'single', 'completed', 16, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Donnie Yen","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"David Wu","avatar":""},{"name":"Robin Shou","avatar":""},{"name":"Carol Cheng","avatar":""},{"name":"Cynthia Khan","avatar":""},{"name":"Leung Lam Ling","avatar":""},{"name":"Lo Lieh","avatar":""},{"name":"Michael Woods","avatar":""},{"name":"John Salvitti","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324545);
