INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cop-xo-long-2', 'Cọp Xổ Lồng 2', 'Tiger On The Beat 2', 'https://phimimg.com/upload/vod/20231010-1/7f07d59e6171cc8799a5f3936e6348a1.jpg', 'https://phimimg.com/upload/vod/20231010-1/d03739e5f1cedc76ae18afe984f3bb03.jpg', '<p>Lam, một cảnh sát sắp 40 nhưng chưa có nhiều thành tích, luôn muốn đạt được điều gì đó đáng nhớ trước khi nghỉ hưu. Anh bị chị gái buộc phải tìm một cô gái Trung Quốc tử tế cho cháu trai mình, Baffalo, một &quot;người Mỹ gốc Hoa&quot;. Nhưng Baffalo lại để mắt đến cô bạn thân Ellen, người đã vô tình chứng kiến một vụ giết người. Vụ việc khiến Lam, Baffalo và Ellen dính vào một đường dây buôn lậu vũ khí ngầm tàn nhẫn, kẻ giết người đã cử kẻ giết người đến để tiêu diệt họ.</p>', 'Full', 1, 'single', 'completed', 15, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Danny Lee Sau-Yin","avatar":""},{"name":"Conan Lee","avatar":""},{"name":"Ellen Chan","avatar":""},{"name":"Gordon Liu Chia-hui","avatar":""},{"name":"Roy Cheung","avatar":""},{"name":"Maria Cordero","avatar":""},{"name":"James Wong","avatar":""},{"name":"Phillip Ko","avatar":""},{"name":"Robert Mak","avatar":""},{"name":"Norman Chui","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324545);
