INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-vui-va-chuyen-tinh', 'Cuộc Vui Và Chuyện Tình', 'The Fun, The Luck & The Tycoon', 'https://phimimg.com/upload/vod/20231010-1/a007b4a3ff8eeb043a5b087700ba132e.jpg', 'https://phimimg.com/upload/vod/20231010-1/8058aafdf7bb9a2162caaa0d3f1dbf51.jpg', '<p>Lam Bo Sun, người đàn ông giàu nhất Hồng Kông, được cho là sẽ kết hôn với người có địa vị xã hội đen tối nhất trong vài tuần nữa. Trong một lần bất chợt, anh bỏ lại mọi thứ và kiếm việc làm nhân viên phục vụ thấp kém tại một nhà hàng mì, và tìm thấy cô gái trong mơ của mình.</p>', 'Full', 1, 'single', 'completed', 18, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Sylvia Chang","avatar":""},{"name":"Nina Li Chi","avatar":""},{"name":"Lawrence Cheng","avatar":""},{"name":"Wong Kwan-Yuen","avatar":""},{"name":"Steve Wong Ka-Keung","avatar":""},{"name":"Wong Ka-Kui","avatar":""},{"name":"Ha Yu","avatar":""},{"name":"Wong San","avatar":""},{"name":"Wong Man","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324545);
