INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-vui-va-chuyen-tinh', 'Cuộc Vui Và Chuyện Tình', 'The Fun, The Luck & The Tycoon', 'cuộc vui và chuyện tình the fun, the luck & the tycoon chow yun-fat sylvia chang nina li chi lawrence cheng wong kwan-yuen steve wong ka-keung wong ka-kui ha yu wong san wong man ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-dia-cuong-thi', 'Cấm Địa Cương Thi', 'Mortuary Blues', 'https://phimimg.com/upload/vod/20231010-1/d9bc20bfe6c8d7d580110d461c8aafc0.jpg', 'https://phimimg.com/upload/vod/20231010-1/2527e18c64a7650c2e8066a5ba8b611b.jpg', '<p>Trên một hòn đảo xa xôi ngoài khơi Hồng Kông, những cư dân giàu có và hạnh phúc của nó đang tổ chức một nghi lễ hàng năm bằng cách dàn dựng một chương trình biểu diễn ca nhạc. Hòn đảo này không hiệu quả nhưng người dân rất giàu. Không có gì ngạc nhiên khi cảnh sát trưởng Yuan Kuei trở nên nghi ngờ. Anh ta nghĩ rằng anh ta đang ngồi trên đầu của một vòng ma tuý. Hai người của ông được lệnh theo dõi chặt chẽ chuyển động của những người trong đoàn opera. Người đứng đầu không biết rằng thực sự những người dân trên đảo đang sống nhờ vào chiến lợi phẩm mà tổ tiên của họ tạo ra bằng cách đột kích một kho vàng của chính phủ cách đây vài thế kỷ. Họ đã chôn phần lớn kho báu và một cương thi dưới một ngôi chùa.</p>', 'Full', 1, 'single', 'completed', 21, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Corey Yuen","avatar":""},{"name":"Sandra Ng Kwun-Yu","avatar":""},{"name":"Sheila Chan Suk-Lan","avatar":""},{"name":"Lowell Lo","avatar":""},{"name":"Alex To Tak-Wai","avatar":""},{"name":"Amy Yip","avatar":""},{"name":"David Lo Dai-Wai","avatar":""},{"name":"Jaclyn Chu Wai-San","avatar":""},{"name":"Colette Koo Ka-Ling","avatar":""},{"name":"Suen Tong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324545);
