INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cam-dia-cuong-thi', 'Cấm Địa Cương Thi', 'Mortuary Blues', 'cấm địa cương thi mortuary blues corey yuen sandra ng kwun-yu sheila chan suk-lan lowell lo alex to tak-wai amy yip david lo dai-wai jaclyn chu wai-san colette koo ka-ling suen tong ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vet-can-tinh-yeu', 'Vết Cắn Tình Yêu', 'A Bite of Love', 'https://phimimg.com/upload/vod/20231006-1/311d552ce3c4f0f91413d0ba5d1b8893.jpg', 'https://phimimg.com/upload/vod/20231006-1/aa2a692cc9b66ab71b34fe124ed09b9c.jpg', '<p>Công tước Lee tuy là zombie nhưng lại rất tốt bụng. Vì không chịu hút máu người và làm tổn thương người vô tội nên hắn ngày càng yếu đi. Một ngày nọ, Công tước Lee gặp một người phụ nữ tên Anna. Sự dịu dàng và quyến rũ tuyệt vời của Anna đã thu hút anh sâu sắc và anh phải lòng cô. Trong một tai nạn, Công tước Lee đã dùng máu của chính mình để cứu sống một đứa trẻ mồ côi Berlin. Cảnh tượng này tình cờ bị Anna nhìn thấy và danh tính của Công tước Lee bị bại lộ. Anh trai của Anna Feng Renyu là một kẻ xấu, làm đủ mọi việc xấu xa. Anh ta biết rằng máu của Công tước Lee có thể khiến con người sống lại nên đã bắt cóc Anna và Công tước Lee. May mắn thay, người hầu của Lee Duke đã liều mạng để cứu họ và âm mưu của Feng Renyu đã thất bại. Tuy nhiên, cuối cùng Feng Renyu vẫn nhận được máu của Công tước Lee, và sau 24 giờ, anh sẽ trở thành một thây ma bất khả xâm phạm và bất tử.</p>', 'Full', 1, 'single', 'completed', 25, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"George Lam Chi-Cheung","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Norman Chui","avatar":""},{"name":"Hui Siu-Hung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324545);
