INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-phi-chinh-truyen', 'A Phi Chính Truyện', 'Days of Being Wild', 'https://phimimg.com/upload/vod/20231006-1/667fa50e94e5085b9d0f0a030897e7ab.jpg', 'https://phimimg.com/upload/vod/20231006-1/0d3e3f1cf22afd26e8f5914256905ab2.jpg', '<p>Yuddy, một tay chơi Hong Kong nổi tiếng với việc làm tan nát trái tim các cô gái, cố gắng tìm kiếm sự an ủi và sự thật sau khi phát hiện ra người phụ nữ đã nuôi nấng anh ta không phải là mẹ của anh ta.</p>', 'Full', 1, 'single', 'completed', 23, 1990, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Leslie Cheung","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Rebecca Pan","avatar":""},{"name":"Jacky Cheung","avatar":""},{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Maritoni Fernandez","avatar":""},{"name":"Alicia Alonzo","avatar":""},{"name":"Tita Muñoz","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324545);
