INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('a-phi-chinh-truyen', 'A Phi Chính Truyện', 'Days of Being Wild', 'a phi chính truyện days of being wild leslie cheung andy lau maggie cheung carina lau rebecca pan jacky cheung tony leung chiu-wai maritoni fernandez alicia alonzo tita muñoz ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-cua-nhung-mai-nha', 'Đứa Con Của Những Mái Nhà', 'Halfaouine: Boy of the Terraces', 'https://phimimg.com/upload/vod/20230925-1/6b33cf1872f1b78dba803aba24dfb6c0.jpg', 'https://phimimg.com/upload/vod/20230925-1/a8f37eef8ebab009f280d7d39f95f467.jpg', '<p>Noura mười hai tuổi lơ lửng không chắc chắn trong thế giới địa ngục đầy khó khăn giữa thời thơ ấu và tuổi trưởng thành. Ham muốn tình dục ngày càng tăng của anh ấy đã khiến anh ấy bị cấm vào phòng tắm dành cho phụ nữ, nơi mẹ anh ấy đã đưa anh ấy khi anh ấy còn nhỏ, nhưng anh ấy vẫn chưa đủ lớn để tham gia vào các cuộc thảo luận trưởng thành với đàn ông ở ngôi làng Tunisia của mình. Người bạn thực sự duy nhất của Noura là một kẻ gây rối tên Salih - một kẻ bị chính trị trong làng ruồng bỏ.</p>', 'Full', 1, 'single', 'completed', 26, 1990, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Selim Boughedir","avatar":""},{"name":"Mustafa Adouani","avatar":""},{"name":"Rabia Ben Abdallah","avatar":""},{"name":"Mohammed Driss","avatar":""},{"name":"Hélène Catzaras","avatar":""},{"name":"Fatima Ben Saïdane","avatar":""},{"name":"Carolyn Chelby","avatar":""},{"name":"Abdelhamid Guayas","avatar":""},{"name":"Jamel Sassi","avatar":""},{"name":"Zahira Ben Ammar","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324545);
