INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghia-dam-quan-anh', 'Nghĩa Đảm Quần Anh', 'Just Heroes', 'https://phimimg.com/uploads/movies/20260713/nghia-dam-quan-anh-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/nghia-dam-quan-anh-poster.webp', '<p>Bộ phim Nghĩa Đảm Quần Anh – Just Heroes là bộ phim hành động võ thuật Hồng Kông được sản xuất năm 1989. Bộ phim bắt đầu sau cái chết của thủ lĩnh một tổ chức tội phạm lớn ở Hồng Kông, tất cả những nhà lãnh đạo khác của tổ chức đều nhăm nhe tranh giành quyền lực tối thượng đó. Pak Wai là người tìm cách đưa kẻ phản bội tổ chức ra ngoài ành sáng nhưng không tìm ra được bằng chứng cụ thể, trong khi Sou, thủ lĩnh được bầu tạm thời đã liên tiếp bị tấn công bất ngờ khi anh ta cố gắng đưa tổ chức trở lại hoạt động dưới sự kiểm soát của mình. Hành động của họ bị ngăn cản bởi Jacky, người đang cố gây ra mâu thuẫn trong nội bộ tổ chức. Đỉnh điểm của mâu thuẫn được đẩy lên khi kẻ phản bội lộ mặt và quyết tâm giành quyền kiểm soát tổ chức.</p>', 'Full', 1, 'single', 'completed', 45, 1989, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"David Chiang Da-Wei","avatar":""},{"name":"Danny Lee Sau-Yin","avatar":""},{"name":"Chen Kuan-Tai","avatar":""},{"name":"Tien Niu","avatar":""},{"name":"Cally Kwong Mei-Wan","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"James Wong Jim","avatar":""},{"name":"Stephen Chow","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Zhao Lei","avatar":""},{"name":"Ku Feng","avatar":""},{"name":"Ti Lung","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Bill Tung Biu","avatar":""},{"name":"Lau Kar-Wing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f697926089