INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoang-troi-uoc-mo-canh-dong-mo-uoc', 'Khoảng Trời Ước Mơ (Cánh Đồng Mơ Ước)', 'Field of Dreams', 'https://phimimg.com/upload/vod/20260704-1/06231137d54004b5c2cc43bd94f0d78e.jpg', 'https://phimimg.com/upload/vod/20260704-1/9e3424209073c0ab333a2e0349c51611.jpg', '<p>Ray Kinsella, một nông dân nghèo sống cùng vợ Annie và con gái Karin ở vùng ngoại ô Iowa. Cuộc sống của anh thanh bình nếu không kể đến người cha đã khuất John Kinsella, một người yêu bóng chày, mê đội Chicago White Sox. Đối với Ray, cha của anh như một người đàn ông hết thời bị cuộc đời dằn vặt. Ray muốn thực hiện ước mơ của người cha, xây dựng 1 sân bóng chày trên chính ruộng ngô của mình. Nhưng khi anh bắt đầu thực hiện ý tưởng đó, anh đột nhiên nghe thấy một giọng nói đầy chất cảnh báo rằng &quot;nếu anh xây, ông ấy sẽ đến&quot;. Liệu Ray có thể theo đuổi được giấc mơ của cha cũng như của chính mình?</p>', 'Full', 1, 'single', 'completed', 40, 1989, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Costner","avatar":""},{"name":"Amy Madigan","avatar":""},{"name":"Gaby Hoffmann","avatar":""},{"name":"Ray Liotta","avatar":""},{"name":"Timothy Busfield","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"Burt Lancaster","avatar":""},{"name":"Frank Whaley","avatar":""},{"name":"Dwier Brown","avatar":""},{"name":"James Andelin","avatar":""},{"name":"Mary Anne Kean","avatar":""},{"name":"Fern Persons","avatar":""},{"name":"Kelly Coffield Park","avatar":""},{"name":"Michael Milhoan","avatar":""},{"name":"Steve Eastin","avatar":""},{"name":"Charles Hoyes","avatar":""},{"name":"Art LaFle","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Campo dos Sonhos","Поле чудес","Le Champs des rêves","Campo de sueños","Shoeless Joe","꿈의 구장","O Xypolitos Tzo","Ο Ξυπόλητος Τζο","フィールド・オブ・ドリームス","フィールド・オブ・ドリームス：1989","L''uomo dei sogni","梦幻成真","梦幻之地","梦幻球场","棒球男孩","O Campo dos Sonhos","El campo de los sueños","Field of Dreams"]', 1784690324545);
