INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khoang-troi-uoc-mo-canh-dong-mo-uoc', 'Khoảng Trời Ước Mơ (Cánh Đồng Mơ Ước)', 'Field of Dreams', 'khoảng trời ước mơ (cánh đồng mơ ước) field of dreams kevin costner amy madigan gaby hoffmann ray liotta timothy busfield james earl jones burt lancaster frank whaley dwier brown james andelin mary anne kean fern persons kelly coffield park michael milhoan steve eastin charles hoyes art lafle campo dos sonhos поле чудес le champs des rêves campo de sueños shoeless joe 꿈의 구장 o xypolitos tzo ο ξυπόλητος τζο フィールド・オブ・ドリームス フィールド・オブ・ドリームス：1989 l''uomo dei sogni 梦幻成真 梦幻之地 梦幻球场 棒球男孩 o campo dos sonhos el campo de los sueños field of dreams', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-ngoai-o', 'Khu ngoại ô', 'The ''Burbs', 'https://phimimg.com/upload/vod/20260602-1/93ef61a5b405bedd1327246a2d34c468.jpg', 'https://phimimg.com/upload/vod/20260602-1/10c6f70fec009165160d1595c7402364.jpg', '<p>Khi những người hàng xóm mới bí ẩn chuyển đến sống cạnh nhà, Ray Peterson, một người dân vùng ngoại ô, và bạn bè của anh ta để nỗi lo sợ lấn át lý trí, bắt đầu nghi ngờ những người mới đến đang làm điều gì đó xấu xa và tiến hành điều tra. Nhưng đó không phải là cách mà Ray, người thích uống bia, đọc báo và xem bóng đá trên truyền hình hơn, mong muốn trải qua kỳ nghỉ của mình.</p>', 'Full', 1, 'single', 'completed', 26, 1989, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Bruce Dern","avatar":""},{"name":"Carrie Fisher","avatar":""},{"name":"Rick Ducommun","avatar":""},{"name":"Wendy Schaal","avatar":""},{"name":"Corey Feldman","avatar":""},{"name":"Courtney Gains","avatar":""},{"name":"Henry Gibson","avatar":""},{"name":"Gale Gordon","avatar":""},{"name":"Dick Miller","avatar":""},{"name":"Robert Picardo","avatar":""},{"name":"Theodore Gottlieb","avatar":""},{"name":"Franklyn Ajaye","avatar":""},{"name":"Cory Danziger","avatar":""},{"name":"Rance Howard","avatar":""},{"name":"Heather Haase","avatar":""},{"name":"Nicky Katt","avatar":""},{"name":"Bill Steve","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Предградията","邻居","The ''Burbs"]', 1784690324545);
