INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoi-ma-song-hung', 'Nuôi Ma Song Hùng', 'Funny Ghost', 'https://phimimg.com/upload/vod/20260426-1/9b447b1e76026f6b7029ff57df09ad92.jpg', 'https://phimimg.com/upload/vod/20260426-1/f436743ee5bb29979b820376892862a8.jpg', '<p>Dư vô tình rơi từ tòa nhà xuống và tìm thấy một túi tiền và một chiếc cốc đá của Đại ca Hùng. Đại ca Hùng phái sát thủ Lâu Nam Quang đi truy lùng và lấy lại chiếc cốc đá vì chiếc cốc đá chứa một hồn ma mà Đại ca Hùng đã mua với giá cao từ Sư phụ, nếu sở hữu được nó điều ước sẽ thành hiện thực.Cảnh sát phái hai thám tử để điều tra sự thật đằng sau vụ án. Sau khi Dư và Nga lấy được cốc đá, chắc chắn họ sẽ thắng mọi vụ cá cược, các tờ tiền liên tục tự động đến trước cửa nhà họ đồng thời bị Lâu đuổi giết và theo sau là hai thám tử, điều này không thể giải thích được.</p>', 'Full', 1, 'single', 'completed', 26, 1989, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Bách Tường","avatar":""},{"name":"Ngô Quân Như","avatar":""},{"name":"Giang Hân Yến","avatar":""},{"name":"Hồ Phong","avatar":""},{"name":"Lưu Nam Quang","avatar":""},{"name":"Tào Đạt Hoa","avatar":""},{"name":"Trương Quốc Trụ","avatar":""},{"name":"Diệp Vinh Tổ","avatar":""},{"name":"Tào Tra Lý","avatar":""},{"name":"Tô Gia Bảo","avatar":""},{"name":"Chung Tinh","avatar":""},{"name":"Hứa Oánh Oánh","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bloody Ghost","猛鬼撞鬼"]', 1784690324545);
