INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nuoi-ma-song-hung', 'Nuôi Ma Song Hùng', 'Funny Ghost', 'nuôi ma song hùng funny ghost trần bách tường ngô quân như giang hân yến hồ phong lưu nam quang tào đạt hoa trương quốc trụ diệp vinh tổ tào tra lý tô gia bảo chung tinh hứa oánh oánh bloody ghost 猛鬼撞鬼', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-ba-vuong-2', 'Nữ Bá Vương 2', 'The Inspector Wears Skirts II', 'https://phimimg.com/upload/vod/20260420-1/8785ade82ac5ef16aff6789e3ffa5b9d.jpg', 'https://phimimg.com/upload/vod/20260420-1/33358b61cda77acd8fcc1673f3dae2d1.jpg', '<p>Phim xoay quanh hành trình phá án của nhóm những “nữ cảnh sát” nhí nhố, ngổ ngáo những cũng rất dễ thương với tên gọi là Bá Vương Hoa , lần này họ kết nạp thêm bốn thành viên mới vào Học viện Cảnh sát Hong Kong và cùng tham gia khóa huấn luyện khắc nghiệt của Madam Wu. Bởi vĩ mỗi người là có những tính cách khác biệt nhau, thậm chí là đối lập nhau so với những thành viên cũ của đôi, vì thế mà những trận cãi vã, những trấn đấu tay đôi cả bằng mồm lẫn chân tay diễn ra như cơm bữa. &nbsp;Tuy nhiên, sau đó, họ đã làm hòa với nhau khi họ cùng tham gia với các Thành viên của đội Phi hổ, dưới sự giám sát của Thanh tra Kan (Shui-Fan Fung), để trải qua các khóa đào tạo mới cùng nhau và kết hợp các lực lượng để cùng nhau tiêu diệt một nhóm khủng bố. Trong khi đó, Kan luôn cố gắng lôi cuốn Madam Wu, cố gắng giành lấy cô một cách khéo léo từ Mr.Lo (Melvin Fong) trong trận đấu Karate, sau đó là lập ra những kế hoạch hết sức thú vị.</p>', 'Full', 1, 'single', 'completed', 18, 1989, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Sibelle Hu Hui-Chung","avatar":""},{"name":"Sandra Ng Kwan-Yu","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"May Lo Mei-Wei","avatar":""},{"name":"Regina Kent","avatar":""},{"name":"Amy Yip Chi-Mei","avatar":""},{"name":"Joanna Chan","avatar":""},{"name":"Tiffany Lau Yuk-Ting","avatar":""},{"name":"Tai Wan-Wai","avatar":""},{"name":"Bill Tung Biu","avatar":""},{"name":"Melvin Wong","avatar":""},{"name":"Stanley Fung Shui-Fan","avatar":""},{"name":"Billy Lau Nam-Kwong","avatar":""},{"name":"Johnny Cheung Wa","avatar":""},{"name":"Go Shut-Fu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Shen yong fei hu ba wang hua","Inspector Wears Skirts 2","神勇飞虎霸王花","霸王花2","神勇飛虎霸王花","The Inspector Wears Skirts 2","The Inspector Wears Skirts Part II"]', 1784690324545);
