INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-pho-ky-quai', 'Khu Phố Kỳ Quái', 'The ''Burbs', 'https://phimimg.com/upload/vod/20260417-1/561ae3b5e39865dc27ea766ca80dca49.jpg', 'https://phimimg.com/upload/vod/20260417-1/8ccd922ca87ce31a78a616c46d44725d.jpg', '<p>Khi những người hàng xóm mới bí ẩn chuyển đến sống cạnh nhà, Ray Peterson, một người dân vùng ngoại ô, và bạn bè của anh ta để nỗi lo sợ lấn át lý trí, bắt đầu nghi ngờ những người mới đến đang làm điều gì đó xấu xa và tiến hành điều tra. Nhưng đó không phải là cách mà Ray, người thích uống bia, đọc báo và xem bóng đá trên truyền hình hơn, mong muốn trải qua kỳ nghỉ của mình.</p>', 'Full', 1, 'single', 'completed', 20, 1989, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Bruce Dern","avatar":""},{"name":"Carrie Fisher","avatar":""},{"name":"Rick Ducommun","avatar":""},{"name":"Wendy Schaal","avatar":""},{"name":"Corey Feldman","avatar":""},{"name":"Courtney Gains","avatar":""},{"name":"Henry Gibson","avatar":""},{"name":"Gale Gordon","avatar":""},{"name":"Dick Miller","avatar":""},{"name":"Robert Picardo","avatar":""},{"name":"Theodore Gottlieb","avatar":""},{"name":"Franklyn Ajaye","avatar":""},{"name":"Cory Danziger","avatar":""},{"name":"Rance Howard","avatar":""},{"name":"Heather Haase","avatar":""},{"name":"Nicky Katt","avatar":""},{"name":"Bill Steve","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Предградията","邻居","The ''Burbs"]', 1784690324545);
