INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-pho-elm-5-dua-be-trong-mo', 'Ác Mộng Phố Elm 5: Đứa Bé Trong Mơ', 'A Nightmare on Elm Street: The Dream Child', 'https://phimimg.com/upload/vod/20260206-1/8b2f55fb7d9de36318183f3e1ee67388.jpg', 'https://phimimg.com/upload/vod/20260206-1/fd41acac692603f06e44edc05bd7dc41.jpg', '<p>Alice, sống sót sau phần trước của loạt phim Ác mộng, thấy những giấc mơ chết chóc của Freddy Krueger bắt đầu lại một lần nữa. Lần này, kẻ sát nhân đáng khinh bỉ đang tấn công tâm trí đang say ngủ của đứa con chưa chào đời của Alice. Ý định của anh ta là được &quot;tái sinh&quot; vào thế giới thực. Người duy nhất có thể ngăn cản Freddy là người mẹ đã khuất của anh, nhưng liệu Alice có thể giải thoát linh hồn của mình kịp thời để cứu con trai mình?</p>', 'Full', 1, 'single', 'completed', 20, 1989, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robert Englund","avatar":""},{"name":"Lisa Wilcox","avatar":""},{"name":"Erika Anderson","avatar":""},{"name":"Valorie Armstrong","avatar":""},{"name":"Michael Ashton","avatar":""},{"name":"Kelly Jo Minter","avatar":""},{"name":"Danny Hassel","avatar":""},{"name":"Nicholas Mele","avatar":""},{"name":"Joe Seely","avatar":""},{"name":"Burr DeBenning","avatar":""},{"name":"Clarence Felder","avatar":""},{"name":"Beatrice Boepple","avatar":""},{"name":"Matt Borlenghi","avatar":""},{"name":"Noble Craig","avatar":""},{"name":"E.R. Davies","avatar":""},{"name":"Beth DePatie","avatar":""},{"name":"Will Egan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Painajainen Elm Streetillä 5 – Painajaisten lapsi","A Nightmare on Elm Street 5 - The Dream Child","Pesadilla en Elm Street 5","Pesadilla en Elm Street 5: El niño de los sueños","Rémálom az Elm utcában 5.: Az álomgyerek","猛鬼街5","Freddy - Chapitre 5 - L''Enfant du cauchemar","A Nightmare on Elm Street Part 5: The Dream Child","Pesadilla en la Calle Elm 5 El Niño de los Sueños","Freddy 5","Pesadilla en la Calle del Infierno 5","A Nightmare On Elm Street 5","Pesadilla 5: el niño de los sueños","Freddy 5 - L''Enfant du cauchemar","A Nightmare on Elm Street 5: The Dream Child","Freddy 5 :  L''héritier du rêve","エルム街の悪夢5 ザ・ドリームチャイルド","エルム街の悪夢 5 ザ・ドリームチャイルド","Koszmar z Ulicy Wiązów 5: Dziecko Snów","Кошмари на Елм стрийт 5: Детето на сънищата","Strava u Ulici brijestova 5: Dijete snova","Noční můra v Elm Street 5: Dítě snu","Freddys sidste mareridt","Elmi tänava luupainaja 5","Εφιάλτης στο δρόμο με τις λεύκες Νο 5: Ο Φρέντυ μπαμπάς","Martröð á Elmarsstræti: Drauma barnið","Terror på Elm Street 5 - The Dream Child","Pesadelo em Elm Street 5","Strava u Ulici brestova 5: Dete snova","Coșmarul de pe Elm Street 5: Copilul din vis","Nočná mora v Elm Street 5: Dieťa sna","Elm Sokağı Kabusu 5: Hayal Çocuk","Жах на вулиці В''язів 5: Дитина сну","Pesadilla 5: El niño de los sueños","Nightmare on Elm Street: Das Trauma","A Hora do Pesadelo 5: O Maior Horror de Freddy","A Nightmare on Elm Street: The Dream Child"]', 1784690324545);
