INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-den', 'Mưa Đen', 'Black Rain', 'https://phimimg.com/upload/vod/20260202-1/b92888f72e598523b40cbd237f242462.jpg', 'https://phimimg.com/upload/vod/20260202-1/3baa09e3c771b1107a90768c86bb55a3.jpg', '<p>Tại Osaka, hai cảnh sát Thành phố New York hợp tác với một thanh tra địa phương thượng tôn pháp luật, cùng vượt qua những rào cản văn hóa để bắt lại tay yakuza trốn thoát.</p>', 'Full', 1, 'single', 'completed', 17, 1989, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Andy Garcia","avatar":""},{"name":"Ken Takakura","avatar":""},{"name":"Kate Capshaw","avatar":""},{"name":"Yūsaku Matsuda","avatar":""},{"name":"Shigeru Kōyama","avatar":""},{"name":"John Spencer","avatar":""},{"name":"Yuya Uchida","avatar":""},{"name":"Guts Ishimatsu","avatar":""},{"name":"Tomisaburō Wakayama","avatar":""},{"name":"Miyuki Ono","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"John Costelloe","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"Bruce Katzman","avatar":""},{"name":"Tim Kelleher","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ブラック・レイン","ブラック・レイン：1989","Schwarzer Regen","黑雨","흑우: 블랙레인","Black Rain"]', 1784690324545);
