INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-buck', 'Chú Buck', 'Uncle Buck', 'https://phimimg.com/upload/vod/20260122-1/f6c4193b11ed36a170a173cd241dd711.jpg', 'https://phimimg.com/upload/vod/20260122-1/e827ce7a4fd073aa93165fc87a6de5f8.jpg', '<p>Buck Russell, một anh chàng độc thân đáng yêu nhưng nhếch nhác, đột nhiên trở thành người chăm sóc tạm thời cho cháu trai và cháu gái của mình sau một trường hợp khẩn cấp trong gia đình. Thái độ phóng túng của anh sớm gây ra căng thẳng với cô cháu gái lớn Tia, cô bạn gái trung thành Chanice và cả những người khác...</p>', 'Full', 1, 'single', 'completed', 17, 1989, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"John Candy","avatar":""},{"name":"Jean Louisa Kelly","avatar":""},{"name":"Gaby Hoffmann","avatar":""},{"name":"Macaulay Culkin","avatar":""},{"name":"Amy Madigan","avatar":""},{"name":"Elaine Bromka","avatar":""},{"name":"Garrett M. Brown","avatar":""},{"name":"Laurie Metcalf","avatar":""},{"name":"Jay Underwood","avatar":""},{"name":"Brian Tarantina","avatar":""},{"name":"Mike Starr","avatar":""},{"name":"Suzanne Shepherd","avatar":""},{"name":"William Windom","avatar":""},{"name":"Dennis Cockrum","avatar":""},{"name":"Joel Robinson","avatar":""},{"name":"Colin Baumgartner","avatar":""},{"name":"Er","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Strýko Buck","El tío Buck","Tío Buck al rescate","아저씨는 못 말려","Uncle Buck"]', 1784690324545);
