INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khi-toi-thuong-2', 'Vũ Khí Tối Thượng 2', 'Lethal Weapon 2', 'https://phimimg.com/upload/vod/20251028-1/9090c2eeb21174f44ec826215ec5c2fe.jpg', 'https://phimimg.com/upload/vod/20251028-1/549188637447597eb703e103db6b421f.jpg', '<p>Roger Murtaugh và Martin Riggs được cấp trên ra lệnh cho họ bảo vệ nhân chứng trong một vụ buôn ma túy. Nhưng họ phát hiện ra tên đầu sỏ thuốc phiện là một quan chứng ngoại giao tại Nam Mỹ. Riggs và Murtaugh sẽ phải giải quyết vụ án này như thế nào?</p>', 'Full', 1, 'single', 'completed', 21, 1989, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Joe Pesci","avatar":""},{"name":"Joss Ackland","avatar":""},{"name":"Derrick O''Connor","avatar":""},{"name":"Patsy Kensit","avatar":""},{"name":"Darlene Love","avatar":""},{"name":"Traci Wolfe","avatar":""},{"name":"Mark Rolston","avatar":""},{"name":"Steve Kahan","avatar":""},{"name":"Jenette Goldstein","avatar":""},{"name":"Dean Norris","avatar":""},{"name":"Juney Smith","avatar":""},{"name":"Nestor Serrano","avatar":""},{"name":"Philip Suriano","avatar":""},{"name":"Grand L. Bush","avatar":""},{"name":"Tony Carreiro","avatar":""},{"name":"Damon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Smrtonosno oružje 2","轰天炮2","Lethal Weapon 2"]', 1784690324545);
