INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-so-diet-ma', 'Cơ Sở Diệt Ma', 'Ghost Busting', 'https://phimimg.com/upload/vod/20250809-1/37b086ea4f7d96af416911570ea70d33.jpg', 'https://phimimg.com/upload/vod/20250809-1/2a678ce07a17861a89bc55ba4560e2a3.jpg', '<p>Mông Ca La (Trần Bách Tường) và Robert Chai (Trần Sơn Hà) vốn là nhân viên tiếp thị của một công ty điện máy hạng nhất. Theo lệnh sếp, họ đến sửa chữa thiết bị tại một biệt thự hẻo lánh, nhưng không ngờ đây lại là “ngôi nhà ma” – nơi trú ngụ của một ma nữ hút máu (Quan Minh Ngọc), một hồn ma ẻo lả (Hoàng Tĩnh Hoa) và một hồn ma quản gia (Trịnh Gia Sanh). Ma nữ hút máu bị dụ ra thành phố và tàn sát nhân viên cùng tài xế công ty. May mắn, cả hai được pháp sư Trương Quốc Vinh (Chung Phát) cứu thoát, tạm thời hóa giải nguy hiểm. Vì quá sợ hãi, Mông Ca La và Robert quyết định tìm việc mới tại Công ty đầu tư họ Giản. Tại đây, Robert gặp và phải lòng Diệp Linh (Khâu Thục Trinh). Trương pháp sư tiết lộ Diệp Linh sinh vào “ngày mười giờ mười” – thể chất đặc biệt khiến ma quỷ phải khiếp sợ. Trong khi đó, tổng giám đốc Giản Mỹ Chi (Quách Tú Vân) muốn chọn pháp sư bảo vệ công ty nên tổ chức một “trại huấn luyện bắt ma” để Trương pháp sư và pháp sư Mai Diễm Phương (Vương Ngọc Hoàn) do Quý Cô (Ngô Quân Như) dẫn đến thi tài cao thấp. Cuộc chiến pháp thuật dở khóc dở cười bắt đầu, đưa cả công ty vào những tình huống vừa hồi hộp vừa hài hước.</p>', 'Full', 1, 'single', 'completed', 17, 1989, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Bách Tường","avatar":""},{"name":"Trần Sơn Hà","avatar":""},{"name":"Quan Minh Ngọc","avatar":""},{"name":"Hoàng Tĩnh Hoa","avatar":""},{"name":"Trịnh Gia Sanh","avatar":""},{"name":"Chung Phát","avatar":""},{"name":"Tào Trà Lý","avatar":""},{"name":"Khâu Thục Trinh","avatar":""},{"name":"Ngô Quân Như","avatar":""},{"name":"Vương Ngọc Hoàn","avatar":""},{"name":"Quách Tú Vân","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hua gui you xian gong si","捉鬼有限公司","嘩鬼有限公司"]', 1784690324545);
