INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-so-diet-ma', 'Cơ Sở Diệt Ma', 'Ghost Busting', 'cơ sở diệt ma ghost busting trần bách tường trần sơn hà quan minh ngọc hoàng tĩnh hoa trịnh gia sanh chung phát tào trà lý khâu thục trinh ngô quân như vương ngọc hoàn quách tú vân hua gui you xian gong si 捉鬼有限公司 嘩鬼有限公司', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve-tuong-lai-2', 'Trở Về Tương Lai 2', 'Back To The Future Part II', 'https://phimimg.com/upload/vod/20250728-1/11cd299041b1d23abc0bde48061936cb.jpg', 'https://phimimg.com/upload/vod/20250728-1/d1fdeb364a06169c2aa01a3366804b51.jpg', '<p>Phần hai của bộ phim mở đầu với cảnh Marty McFly và tiến sĩ Emmett Brown hành trình tới năm 2015 để ngăn chặn con trai của Marty tham gia một vụ cướp. Cùng đi với họ là Jennifer Parker, bạn gái của Marty. Theo lời của tiến sĩ Brown, con trai cả của Marty, Marty Junior, bị một người bạn cùng lớp là Griff Tannen rủ tham gia một vụ cướp cùng với mấy đàn em của hắn. Griff Tannen là cháu nội của Biff Tannen, người cùng học với bố Marty. Vị tiến sĩ lập dị khẳng định rằng, việc Marty Junior tham gia vụ cướp sẽ dẫn tới sự sụp đổ của toàn bộ gia đình McFly.</p>', 'Full', 1, 'single', 'completed', 13, 1989, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael J. Fox","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Lea Thompson","avatar":""},{"name":"Thomas F. Wilson","avatar":""},{"name":"Elisabeth Shue","avatar":""},{"name":"James Tolkan","avatar":""},{"name":"Jeffrey Weissman","avatar":""},{"name":"Casey Siemaszko","avatar":""},{"name":"Billy Zane","avatar":""},{"name":"J.J. Cohen","avatar":""},{"name":"Charles Fleischer","avatar":""},{"name":"E. Casanova Evans","avatar":""},{"name":"Jay Koch","avatar":""},{"name":"Charles Gherardi","avatar":""},{"name":"Ricky Dean Logan","avatar":""},{"name":"Darlene Vogel","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae