INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tro-ve-tuong-lai-2', 'Trở Về Tương Lai 2', 'Back To The Future Part II', 'trở về tương lai 2 back to the future part ii michael j. fox christopher lloyd lea thompson thomas f. wilson elisabeth shue james tolkan jeffrey weissman casey siemaszko billy zane j.j. cohen charles fleischer e. casanova evans jay koch charles gherardi ricky dean logan darlene vogel back to the future part 2 ritorno al futuro ii 回到未來ii בחזרה לעתיד ii regreso al futuro ii retour vers le futur 2 ritorno al futuro 2 volver al futuro ii atgal i ateiti ii vrnitev v prihodnost ii vissza a jovobe ii de volta para o futuro 2 tilbage til fremtden del ii バック・トゥ・ザ・フュー チャー 2 back to the future 2 retour vers le futur ii tro ve tuong lai 2 назад в будущее 2 zurück in die zukunft 2 უკან მომავალში ნაწილი 2 უკან მომავალში მეორე ნაწილი повратак у будућност 2 백 투 더 퓨쳐 2 백 투 더 퓨처 2 빽 투 더 퓨처 2 빽 투 더 퓨쳐 2 バック・トゥ・ザ・フューチャー2 バック・トゥ・ザ・フューチャー part2：1989 ritorno al futuro - parte 2 gələcəyə dönüş 2 回到未來 2 back to the future ii zurueck in die zukunft 2 հետ դեպի ապագա 2 het depi apaga 2 paradox back to the future part ii', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-vu-giao-hang-kiki', 'Dịch Vụ Giao Hàng Kiki', 'Kiki''s Delivery Service', 'https://phimimg.com/upload/vod/20250716-1/3053819af571daf02e44f2edf58847cc.jpg', 'https://phimimg.com/upload/vod/20250716-1/94ec2af944b111067d821e219bcf19a0.jpg', '<p>Bộ phim bắt đầu ngay thời điểm Kiki - một cô bé phù thuỷ thực tập - đủ tuổi để rời gia đình và đến một nơi khác, nơi cô phải sống một mình trong vòng một năm để cô có thể trở thành một phù thủy thực thụ. Kiki khởi hành vào buổi tối cùng với sự cổ vũ của mọi người, sử dụng chiếc chổi của mẹ cô, và mang theo chú mèo Jiji cùng một số thứ cần thiết. Kiki chọn thành phố Koriko, một nơi mà cô có thể nhìn thấy biển, một thành phố có chiếc tháp đồng hồ cổ kính. Nhưng với một cô bé 13 tuổi cùng với chiếc chổi bay khắp thành phố thì khó mà có thể tìm được một chỗ để trú thân. Nhờ một lần vô tình giúp đỡ bà chủ tiệm bánh, Kiki đã bắt đầu công việc chuyển phát bằng chiếc chổi bay của mình.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 1989, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Takayama","avatar":""},{"name":"Rei Sakuma","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Keiko Toda","avatar":""},{"name":"Mieko Nobusawa","avatar":""},{"name":"Koichi Miura","avatar":""},{"name":"Haruko Katō","avatar":""},{"name":"Hiroko Seki","avatar":""},{"name":"Yuriko Fuchizaki","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Kikuko Inoue","avatar":""},{"name":"Yuko Kobayashi","avatar":""},{"name":"Mika Doi","avatar":""},{"name":"Takaya Hashi","avatar":""},{"name":"Chika Sakamoto","avatar":""},{"name":"Yoshiko Asai","avatar":""},{"name":"Hiroko Maruyama","avatar":""},{"name":"Shin","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2