INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dich-vu-giao-hang-kiki', 'Dịch Vụ Giao Hàng Kiki', 'Kiki''s Delivery Service', 'dịch vụ giao hàng kiki kiki''s delivery service minami takayama rei sakuma kappei yamaguchi keiko toda mieko nobusawa koichi miura haruko katō hiroko seki yuriko fuchizaki koichi yamadera kikuko inoue yuko kobayashi mika doi takaya hashi chika sakamoto yoshiko asai hiroko maruyama shin majo no takkyûbin majo no takkyuubin служба доставки кікі юної відьми відьмина експрес-пошта 魔女宅急便 kikis budservice kiki''nin çatdırılma servisi balaca cadı kiki kiki’s delivery service 魔女宅急便(1989) kiki''nin kurye servisi o serviço de entregas da kiki kiki: a aprendiz de feiticeira serviço de entrega da kiki kiki la petite sorcière 마녀 배달부 키키 kiki entregas a domicilio 魔女の宅急便', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-thi-tien-sinh-5-cuong-thi-dau-ma-ca-rong', 'Cương Thi Tiên Sinh 5: Cương Thi Đấu Ma Cà Rồng', 'Vampire Vs. Vampire', 'https://phimimg.com/upload/vod/20250603-1/d4d5fd5a6c8d9dfa3ac19d0e156b9be0.jpg', 'https://phimimg.com/upload/vod/20250603-1/a8462bde689b452eb3b9d4f31b9d3fb0.jpg', '<p>Trong phim, Lâm Chánh Anh vào vai một đạo sĩ có biệt danh là One-Eyebrow (Nhất My Đạo Nhân), ông phát hiện ra rằng nguồn cung cấp nước trong làng của ông đã bị ô nhiễm bởi những con dơi, và trong quá trình đào giếng để tìm nguồn cung cấp nước mới, ông đã vô tình tìm thấy thi thể của một linh mục ác độc. Trong khi đang đối phó với một loạt các sinh vật bao gồm một cương thi trẻ tinh nghịch, một ma nữ độc ác và một cô gái lầu xanh bị giết chết một cách oan nghiệt, xác chết của cô ta đã sống lại thành một con cương thi đầy thù hận.</p>', 'Full', 1, 'single', 'completed', 19, 1989, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Lam Ching-Ying","avatar":""},{"name":"Chin Siu-Ho","avatar":""},{"name":"Lui Fong","avatar":""},{"name":"Billy Lau Nam-Kwong","avatar":""},{"name":"Sandra Ng","avatar":""},{"name":"Maria Cordero","avatar":""},{"name":"Lam Jing-Wang","avatar":""},{"name":"Tiffany Lau","avatar":""},{"name":"Frank Juhasz","avatar":""},{"name":"Yip So","avatar":""},{"name":"Regina Kent","avatar":""},{"name":"Chan Suet-Man","avatar":""},{"name":"Joanna Chan Pui-San","avatar":""},{"name":"Chin Yuet-Sang","avatar":""},{"name":"Law Ching-Ho","avatar":""},{"name":"Wong Chi-Keung","avatar":""},{"name":"King Lee King-Chu","avatar":""},{"name":"Chan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["一眉道人","One Eyebrowed Priest","Yi mei dao ren","Vampire vs. Vampire"]', 1784690324545);
