INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-nuoc-nhat-thoi-nguyen-thuy-1989', 'Doraemon: Nobita và Nước Nhật Thời Nguyên Thủy', 'Doraemon: Nobita and the Birth of Japan', 'https://phimimg.com/upload/vod/20250521-1/b77b528c8abc365050a474918ad642d8.jpg', 'https://phimimg.com/upload/vod/20250521-1/7ffc819b5bdf5aaa759b53da34be8956.jpg', '<p>Khi Nobita, Doraemon và nhóm bạn muốn bỏ trốn khỏi nhà vì nhiều lý do khác nhau, họ phải đối mặt với nhiệm vụ tìm một nơi nào đó để sống. Tuy nhiên, mỗi mảnh đất dường như đã đều đã có chủ nên việc xây cho mình một ngôi nhà dường như là điều không thể, cho đến khi Nobita có ý tưởng du hành ngược lại bảy mươi nghìn năm về quá khứ. Trong khi cả nhóm đang tự làm cho mình ở nhà ở một Nhật Bản không có người ở quá khứ, thì ở hiện tại, một trục trặc trong không-thời gian đã khiến một cậu bé người tiền sử lao vào giữa thành phố. Khi họ trở về hiện tại, Doraemon và những người bạn bắt gặp đứa trẻ - tên là Kukuru - và đưa cậu ta trở lại thiên đường thời tiền sử của họ. Cùng nhau, cả nhóm quyết định đưa cậu bé trở về đúng mốc thời gian của mình và giúp cậu giải thoát bộ tộc đang bị bắt của mình, ngay cả khi điều đó có nghĩa là phải đối mặt với sự nguy hiểm của kẻ thù của Kukuru: bộ tộc bóng tối.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 1989, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["日本誕生","Nobita and the Birth of Japan","Doraemon Nobita no Nihon Tanjo","大雄與日本的誕生","哆啦A夢：大雄的日本誕生","Doraemon: Nobita no Nippon Tanjou","ドラえもん のび太の日本誕生","映画ドラえもん のび太の日本誕生","Doraemon the Movie: Birth of Japan","哆啦A梦：大雄与日本诞生","Doraemon: Kelahiran Jepun","電影哆啦A夢：大雄與日本的誕生"]', 1784690324545);
