INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tho-du-doi', 'Tuổi Thơ Dữ Dội', 'Fierce Childhood', 'https://phimimg.com/upload/vod/20250406-1/d38f6da1a61f73984b834bb69e87c060.jpg', 'https://phimimg.com/upload/vod/20250406-1/da53d9b8e6b7f8fd5884c8ced71112c9.jpg', '<p>Bộ phim &quot;Tuổi Thơ Dữ Dội&quot; được chuyển thể từ tiểu thuyết cùng tên của cố nhà văn Phùng Quán, do NSƯT Nguyễn Vinh Sơn làm đạo diễn, ra mắt vào năm 1989. Phim là câu chuyện có thật của những chiến sĩ nhí tham gia vào cuộc kháng chiến chống Pháp bảo vệ Tổ quốc với chuỗi chiến công đầy ắp được tạo nên bằng máu xương và nước mắt.</p>', 'Full', 1, 'single', 'completed', 8, 1989, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lê Công Tuấn Anh","avatar":""},{"name":"Vũ Thanh Bình","avatar":""},{"name":"Nguyễn Hoàng Anh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324545);
