INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-ke-dao-tau', 'Ba Kẻ Đào Tẩu', 'Three Fugitives', 'https://phimimg.com/upload/vod/20250110-1/ebd3c38b6607c843335fa1d222ce83b0.jpg', 'https://phimimg.com/upload/vod/20250110-1/b27e1748705acbb4acc720e8f56f5e60.jpg', '<p>Vào ngày đầu tiên sau khi ra tù vì 14 vụ cướp ngân hàng có vũ trang, Lucas thấy mình bị cuốn vào vụ cướp của người khác. Perry đã quyết định huy động ngân hàng địa phương để quyên góp tiền để anh có thể giữ lại con gái mình, Meg, và giúp cô ấy điều trị mà cô ấy cần. Dugan, một thám tử, cho rằng Lucas đã giúp lên kế hoạch cho vụ cướp, và do đó Lucas, Perry và Meg trở thành ba kẻ chạy trốn.</p>', 'Full', 1, 'single', 'completed', 9, 1989, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nick Nolte","avatar":""},{"name":"Martin Short","avatar":""},{"name":"Sarah Rowland Doroff","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"Alan Ruck","avatar":""},{"name":"Kenneth McMillan","avatar":""},{"name":"David Arnott","avatar":""},{"name":"Bruce McGill","avatar":""},{"name":"Lee Garlington","avatar":""},{"name":"Sy Richardson","avatar":""},{"name":"Rocky Giordani","avatar":""},{"name":"Rick Hall","avatar":""},{"name":"Bill Cross","avatar":""},{"name":"Stanley Brock","avatar":""},{"name":"John Procaccino","avatar":""},{"name":"Kathy Kinney","avatar":""},{"name":"Way Ching Yu","avatar":""},{"name":"Ja","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["两大一小三俘虏","Os Três Fugitivos","Three Fugitives"]', 1784690324545);
