INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-gia-truyen-thuyet', 'Vạn Gia Truyền Thuyết', 'The Vixen''s Tale', 'https://phimimg.com/upload/vod/20241207-1/f0d3bd5a873205a97a2feabc17f1d558.jpg', 'https://phimimg.com/upload/vod/20241207-1/a0ecf3c32c82737f29c97092411c4fb2.jpg', '<p>Thư sinh Vạn Văn Thông có biệt tài vẽ tranh rất đẹp, trong lần té xuống sông Văn Thông được một cô gái áo trắng cứu sống khiến Văn Thông si tình ôm mộng vẽ thành bức tranh tuyệt sắc giai nhân.Văn Thông sống cùng cha mẹ, em họ Lý Đại Muối và cậu Lý Đức Phúc rất vui vẻ, nhưng Vạn Niên Nhân cha của Văn Thông là người có năng lực bí ẩn đã sống qua mấy trăm năm. Văn Thông gặp Cổ Nguyệt sống trong kỹ viện có khuôn mặt giống y như cô gái áo trắng đã cứu anh, Văn Thông đem tranh gửi tặng theo đuổi Cổ Nguyệt. Cổ Nguyệt cũng có tình cảm với Văn Thông nhưng vì Cổ Nguyệt là hồ ly tinh, sống trong kỹ viện chuyên bắt đàn ông về cho mẹ là Hồ Nương. Hồ Nương năm xưa bị phụ bạc suýt mất đi đạo hạnh ngàn năm nên rất hận đàn ...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 1989, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Roger Kwok","avatar":""},{"name":"Yammie Lam","avatar":""},{"name":"Sheren Tang","avatar":""},{"name":"Hugo Ng Doi-Yung","avatar":""},{"name":"Au-Yeung Tsan-Wah","avatar":""},{"name":"Cutie Mui Siu-Wai","avatar":""},{"name":"Felton Law Gwan-Joh","avatar":""},{"name":"Steve Lee Ka-Ting","avatar":""},{"name":"Pak Yan","avatar":""},{"name":"Amy Wu Mei-Yee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e