INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-ngay-4-thang-7', 'Sinh Ngày 4 Tháng 7', 'Born On The Fourth Of July', 'https://phimimg.com/upload/vod/20240901-1/28b19a9deee6460e0a94eab34751d3e2.jpg', 'https://phimimg.com/upload/vod/20240901-1/b5d16c3c31bb01695d8cb3f7301ee242.jpg', '<p>Bị tê liệt trong chiến tranh Việt Nam, Ron Kovic trở thành một nhà hoạt động chính trị phản chiến và ủng hộ nhân quyền sau khi cảm thấy bị phản bội bởi đất nước mà anh đã chiến đấu.</p>', 'Full', 1, 'single', 'completed', 11, 1989, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Raymond J. Barry","avatar":""},{"name":"Caroline Kava","avatar":""},{"name":"Holly Marie Combs","avatar":""},{"name":"Kyra Sedgwick","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Rob Camilletti","avatar":""},{"name":"Stephen Baldwin","avatar":""},{"name":"Mark Moses","avatar":""},{"name":"Vivica A. Fox","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"Jerry Levine","avatar":""},{"name":"Frank Whaley","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Josh Evans","avatar":""},{"name":"Bob Gunton","avatar":""},{"name":"Cordelia González","avatar":""},{"name":"Tony","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324545);
