INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sinh-ngay-4-thang-7', 'Sinh Ngày 4 Tháng 7', 'Born On The Fourth Of July', 'sinh ngày 4 tháng 7 born on the fourth of july tom cruise raymond j. barry caroline kava holly marie combs kyra sedgwick tom berenger rob camilletti stephen baldwin mark moses vivica a. fox lili taylor jerry levine frank whaley willem dafoe josh evans bob gunton cordelia gonzález tony ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-van-cong-truyen-ky', 'Tấn Văn Công Truyền Kỳ', 'Chun Man Kung Chuen Ki', 'https://phimimg.com/upload/vod/20240802-1/d04bf8b2fb7ca5b75082e7b3e3822c4b.jpg', 'https://phimimg.com/upload/vod/20240802-1/017e70759a45ea4101c19e8c75a9ac85.jpg', '<p>Tấn Văn Công (diễn viên Lê Minh) tên thật là Cơ Trùng Nhĩ (姬重耳), là vị vua thứ 24 của nước Tấn - chư hầu nhà Chu thời Xuân Thu trong lịch sử Trung Quốc. Ông cai trị từ năm 636 TCN đến năm 628 TCN, tổng cộng 8 năm. Tấn Văn công có một sự nghiệp hết sức đáng chú ý, lưu vong 19 năm, được các thủ hạ Triệu Thôi (赵衰; tiên tổ nước Triệu), Hồ Uyển (狐偃), Cổ Đà (贾佗), Tiên Chẩn (先轸), Ngụy Vũ tử (魏武子; tiên tổ nước Ngụy); sau ông trở về lên ngôi vua nước Tấn, tạo nên nền móng cơ sở sự hùng mạnh của nước Tấn trong cả thế kỉ về sau. Cũng từ ông, mà các tiên tổ nước Triệu, nước Ngụy và nước Hàn dần có thế lực, kết quả là tạo nên 3 quốc gia Tam Tấn nổi tiếng thời Chiến Quốc. Vì sự nghiệp rạng rỡ và đầy tính huyền thoại, ông được xếp vào trong Ngũ Bá thời Xuân Thu, được sử sách nhắc tới nhiều.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 20, 1989, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Lê Minh","avatar":""},{"name":"La Huệ Quyên","avatar":""},{"name":"Âu Dương Chấn Hoa","avatar":""},{"name":"Huỳnh Tử Dương","avatar":""},{"name":"Lý Trung Ninh","avatar":""},{"name":"Hoàng Tân","avatar":""},{"name":"Lưu Quế Phương","avatar":""},{"name":"Quách Tú Vân","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '[]', 1784690324545);
