INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tan-van-cong-truyen-ky', 'Tấn Văn Công Truyền Kỳ', 'Chun Man Kung Chuen Ki', 'tấn văn công truyền kỳ chun man kung chuen ki lê minh la huệ quyên âu dương chấn hoa huỳnh tử dương lý trung ninh hoàng tân lưu quế phương quách tú vân ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-khach-hanh', 'Hiệp Khách Hành', 'Hap Hak Hang', 'https://phimimg.com/upload/vod/20240613-1/0e50040d6361f0bd5d73118cf3c50f83.jpg', 'https://phimimg.com/upload/vod/20240613-1/d313c896e37839dc287fe685b43cc2dd.jpg', '<p><em>Hiệp khách hành năm 1989 của TVB là một trong những phiên bản phim kinh điển, tái hiện thành công tiểu thuyết cùng tên của nhà văn Kim Dung. Đây cũng là bộ phim gắn liền với tên tuổi của nam tài tử Lương Triều Vỹ, khi anh phải hóa thân vào hai nhân vật có tính cách trái ngược nhau, vừa hài vừa bi. Câu chuyện xoay quanh hai anh em song sinh là Thạch Trung Ngọc và Thạch Phá Thiên (do Lương Triều Vỹ đóng). Phá Thiên thất lạc gia đình từ nhỏ, sống với mẹ nuôi trên núi. Nhờ cơ duyên gặp phải cao nhân, Thiên được truyền bí kíp võ công cái thế và bất đắc dĩ trở thành bang chủ Trường Lạc.</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 18, 1989, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Tony Leung Chiu-wai","avatar":""},{"name":"Sheren Tang","avatar":""},{"name":"Chun Wong","avatar":""},{"name":"Kwan Hoi-San","avatar":""},{"name":"Leung Bo-Ching","avatar":""},{"name":"Tin Ching","avatar":""},{"name":"Chang Yi","avatar":""},{"name":"Julia Cheng Yim-Lai","avatar":""},{"name":"Ching-Ching Yiu","avatar":""},{"name":"Marina Lau","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324545);
