INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-kim-lien-tien-the-kim-sinh', 'Phan Kim Liên: Tiền Thế Kim Sinh', 'Reincarnation Of Golden Lotus', 'https://phimimg.com/upload/vod/20231010-1/044e5ed6793872a59b9313d33f748770.jpg', 'https://phimimg.com/upload/vod/20231010-1/c8df847c87138491ed3de44009aa727c.jpg', '<p>Một người phụ nữ bị nguyền rủa nhan sắc ở Trung Quốc và trở thành con mồi cho đàn ông. Bị hiệu trưởng trường múa ba lê cưỡng hiếp và đưa đi trại lao động, cô trốn thoát đến Hồng Kông suy đồi bằng cách kết hôn với một chủ ngân hàng giàu có. Cô thấy mình bị cuốn hút vào những vấn đề bạo dâm và trong đoạn hồi tưởng, cô phát hiện ra mình là tái sinh của một kỹ nữ nổi tiếng thời Trung Quốc cổ đại.</p>', 'Full', 1, 'single', 'completed', 9, 1989, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Joey Wong","avatar":""},{"name":"Wilson Lam","avatar":""},{"name":"Pal Sinn Lap-man","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Ku Feng","avatar":""},{"name":"Lisa Chiao Chiao","avatar":""},{"name":"Chan Lap-Ban","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324545);
