INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-toi-loi-1989', 'Thiên Thần Tội Lỗi', 'Arabella Black Angel', 'https://phimimg.com/upload/vod/20240620-1/36bb1b15020a0ead89f19b4bc3bf6576.jpg', 'https://phimimg.com/upload/vod/20240620-1/6a044d8951680ed879b635ec3da293e3.jpg', '<p>Arabella là một nữ sinh có quan hệ tình dục với bất kỳ người đàn ông nào. Một ngày nọ, chồng cô, một nhà văn, gặp cô và một người đàn ông khác. Cô ấy có một phản ứng kỳ lạ: giết người yêu. Chồng cô giấu xác. Kể từ thời điểm đó, anh khuyến khích cô gặp gỡ những người đàn ông khác và viết ra những kinh nghiệm trong cuốn sách mới của mình.</p>', 'Full', 1, 'single', 'completed', 28, 1989, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Tinì Cansino","avatar":""},{"name":"Valentina Visconti","avatar":""},{"name":"Francesco Casale","avatar":""},{"name":"Carlo Mucari","avatar":""},{"name":"Renato D''Amore","avatar":""},{"name":"Giose Davi","avatar":""},{"name":"David D''Ingeo","avatar":""},{"name":"Rena Niehaus","avatar":""},{"name":"Ida Galli","avatar":""},{"name":"Vinicio Diamanti","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324545);
