INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chip-n-dale-rescue-rangers-phan-2', 'Chip ''n'' Dale Rescue Rangers (Phần 2)', 'Chip ''n'' Dale Rescue Rangers (Season 2)', 'https://phimimg.com/upload/vod/20240302-1/7a0072874c618be53c079ece6bd3da79.jpg', 'https://phimimg.com/upload/vod/20240302-1/f98d95a90805c05f76d5f2b98e266607.jpg', '<p>Chip và Dale đứng đầu một nhóm nhân vật động vật nhỏ, lập dị, không chỉ giám sát thế giới con người mà còn cả cộng đồng động vật, giải quyết những bí ẩn ở bất cứ nơi nào họ có thể. Các Đội cứu hộ xử lý các vụ án rơi vào tình thế khó khăn.</p>', 'Hoàn Tất (47/47)', 47, 'hoathinh', 'completed', 13, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Corey Burton","avatar":""},{"name":"Tress MacNeille","avatar":""},{"name":"Jim Cummings","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324545);
