INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arabella-thien-than-den', 'Arabella: Thiên Thần Đen', 'Arabella: Black Angel', 'https://phimimg.com/upload/vod/20240228-1/3e4d7a411fdcec7f54fa9721a9e830ed.jpg', 'https://phimimg.com/upload/vod/20240228-1/72514c64c8d216f6b11e0b09dde5ee33.jpg', '<p>Một kẻ cuồng dâm vô độ với người chồng là nhà văn ngồi trên xe lăn phát hiện ra rằng những chiến công khủng khiếp của cô đã làm trẻ hóa khả năng sáng tạo và ham muốn tình dục của anh, nhưng chẳng bao lâu sau, tất cả những người tình của cô đều bị sát hại bởi một kẻ tấn công vô danh.</p>', 'Full', 1, 'single', 'completed', 16, 1989, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Tinì Cansino","avatar":""},{"name":"Valentina Visconti","avatar":""},{"name":"Francesco Casale","avatar":""},{"name":"Carlo Mucari","avatar":""},{"name":"Renato D''Amore","avatar":""},{"name":"Giose Davi","avatar":""},{"name":"David D''Ingeo","avatar":""},{"name":"Rena Niehaus","avatar":""},{"name":"Ida Galli","avatar":""},{"name":"Vinicio Diamanti","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324545);
