INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-kheo', 'Nói Khéo', 'Say Anything...', 'https://phimimg.com/upload/vod/20240219-1/44c19eee7a3810675cf67233a7145736.jpg', 'https://phimimg.com/upload/vod/20240219-1/d41d577332e3d0b93a0445cd9b3a3d35.jpg', '<p>Lloyd, một người luôn lạc quan, tìm cách chiếm được trái tim của Diane, một học sinh trung học xinh đẹp không thể đạt được và là học sinh đạt điểm A. Anh ấy làm mọi người ngạc nhiên - kể cả chính anh ấy - khi cô ấy đáp lại tình cảm. Nhưng người bố đã ly hôn, chiếm hữu quá mức của Diane không đồng ý và sẽ cần nhiều thứ hơn là sức mạnh của tình yêu để chinh phục tất cả.</p>', 'Full', 1, 'single', 'completed', 11, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Cusack","avatar":""},{"name":"Ione Skye","avatar":""},{"name":"John Mahoney","avatar":""},{"name":"Lili Taylor","avatar":""},{"name":"Amy Brooks","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324545);
