INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ve-christy-brown', 'Câu Chuyện Về Christy Brown', 'My Left Foot: The Story Of Christy Brown', 'https://phimimg.com/upload/vod/20240219-1/eff82d16cdd7dbe23213fd529eb29761.jpg', 'https://phimimg.com/upload/vod/20240219-1/a55e51d0701ae682f2012474f1fb220d.jpg', '<p>Không ai mong đợi nhiều ở Christy Brown, một cậu bé bị bại não sinh ra trong một gia đình lao động Ireland. Mặc dù Christy bị liệt tứ chi và về cơ bản là bị liệt, nhưng một sự kiện kỳ diệu đã xảy ra khi mới 5 tuổi, cậu bé đã thể hiện khả năng kiểm soát bàn chân trái của mình bằng cách dùng phấn viết nguệch ngoạc một từ trên sàn nhà. Với sự giúp đỡ của người mẹ nghiêm khắc — và không thiếu sự can đảm và quyết tâm — Christy đã vượt qua bệnh tật để trở thành một họa sĩ, nhà thơ và tác giả.</p>', 'Full', 1, 'single', 'completed', 12, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Day-Lewis","avatar":""},{"name":"Brenda Fricker","avatar":""},{"name":"Alison Whelan","avatar":""},{"name":"Declan Croghan","avatar":""},{"name":"Eanna MacLiam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324545);
