INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-gai-ong-trum', 'Con Gái Ông Trùm', 'The Best Of Best', 'https://phimimg.com/upload/vod/20240128-1/0e9e3c688e77383f4bcd2d6abc15891b.jpg', 'https://phimimg.com/upload/vod/20240128-1/765672a6c373c4d42973bfcc1a1f0bdf.jpg', '<p>Con Gái Ông Trùm - The Best Of Best xoay quanh chàng trai tên A Đệ, một cảnh sát đặc nhiệm. Trong một lần giải cứu con tin, anh đã cứu được cô gái xinh đẹp, sau vài lần gặp mặt họ đã yêu nhau từ lúc nào. Nhưng tình yêu của họ bị ông trùm cấm cản. Và từ đây mọi chuyện bắt đầu…</p>', 'Full', 1, 'single', 'completed', 12, 1989, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Ngô Mạnh Đạt","avatar":""},{"name":"Tần Bái","avatar":""},{"name":"Carri Nguyễn","avatar":""},{"name":"Jacky Hữu","avatar":""},{"name":"Sammi Văn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324545);
