INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('police-academy-6-city-under-siege', 'Police Academy 6: City Under Siege', 'Police Academy 6: City Under Siege', 'https://phimimg.com/upload/vod/20240108-1/73defcffebf607cffd34a39e6c41b2e8.jpg', 'https://phimimg.com/upload/vod/20240108-1/93860b7135f21b7b936d05a65d2849ef.jpg', '<p>Sau cuộc phiêu lưu tốc độ cao trong Học viện Cảnh sát 5: Phân công: Bãi biển Miami (1988), một số vụ cướp trong khu vực Wilson Heights sành điệu khủng bố thành phố. Sau đó, để làm cho vấn đề tồi tệ hơn, khi bộ ba của những kẻ trộm Cat-Burglars quản lý một kẻ thù táo bạo ngay dưới cái mũi của đội trưởng Harris, tùy thuộc vào việc chỉ huy Lassard và một nhóm sinh viên tốt nghiệp trung thành từ Học viện Cảnh sát ban đầu (1984) đến ngăn chặn làn sóng trộm cắp. Bây giờ, như một nốt ruồi là rò rỉ thông tin có giá trị, chỉ một hoạt động bí mật được tổ chức tốt có thể phơi bày Mastermind bí ẩn, một trong những vụ án tội phạm của băng đảng. Có thể làm nứt tốt nhất của Lassard có thể xảy ra trường hợp của băng đảng Wilson Heights? -Nick Riganas</p>', 'Full', 1, 'single', 'completed', 14, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324546);
