INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuc-tham-1989', 'Vực Thẳm', 'The Abyss', 'https://phimimg.com/upload/vod/20231219-1/bd038676cbf5790874c239cab4bd1ccd.jpg', 'https://phimimg.com/upload/vod/20231219-1/4b846aee3a69335775b0667da4756c91.jpg', '<p>Một đội giàn khoan dầu dân sự được tuyển dụng để tiến hành nỗ lực tìm kiếm và cứu hộ khi một tàu ngầm hạt nhân chìm một cách bí ẩn. Một thợ lặn sớm thấy mình trong một cuộc phiêu lưu ngoạn mục ở độ sâu 25.000 feet dưới bề mặt đại dương, nơi anh ta đối đầu với một thế lực bí ẩn có khả năng thay đổi hoặc hủy diệt thế giới.</p>', 'Full', 1, 'single', 'completed', 16, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ed Harris","avatar":""},{"name":"Mary Elizabeth Mastrantonio","avatar":""},{"name":"Michael Biehn","avatar":""},{"name":"Leo Burmester","avatar":""},{"name":"Todd Graff","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324546);
