INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-nhan-luu-vong-3', 'Quân Nhân Lưu Vong 3', 'Long Arm of the Law III', 'https://phimimg.com/upload/vod/20231129-1/cbb730bc6ac8b7eda1cd456bef7ab943.jpg', 'https://phimimg.com/upload/vod/20231129-1/8fd3d992209e52ae32e58184bebe94fd.jpg', '<p>Phim Quân Nhân Lưu Vong Phần 3 (Long Arm of Law 3): đạo diễn Johnny Mak tiếp tục được sản xuất thêm 2 phần, trong đó đáng chú ý phải kể tới phần 3 phát hành vào năm 1989, tác phẩm có sự tham gia của 2 ngôi sao mới thời điểm đó – Lưu Đức Hoa và Mạc Thiếu Thông, tựa tiếng Việt của phần này là Quân Nhân Lưu Vong. Nếu như chỉ đạo võ thuật kiêm nhà sản xuất ở phần đầu là Hồng Kim Bảo thì ở phần thứ 3, Siu-Hung Leung là người đảm nhiệm vai trò chỉ đạo hành động trong khi người “cầm trịch” cho phim là đạo diễn nổi tiếng Michael Mak.</p>', 'Full', 1, 'single', 'completed', 20, 1989, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Elizabeth Lee Mei-Fung","avatar":""},{"name":"Max Mok Siu-Chung","avatar":""},{"name":"Elvis Tsui Kam-Kong","avatar":""},{"name":"Kirk Wong Chi-Keung","avatar":""},{"name":"John Ladalski","avatar":""},{"name":"Ken Boyle","avatar":""},{"name":"Hon Yee-Sang","avatar":""},{"name":"Mai Kei","avatar":""},{"name":"Alex Ng Hong-Ling","avatar":""},{"name":"Stephen Chan Tak-Gwong","avatar":""},{"name":"Lam Kai-Wing","avatar":""},{"name":"Wai Ching","avatar":""},{"name":"Robin Shou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324546);
