INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-bi-an', 'Chuyến Tàu Bí Ẩn', 'Mystery Train', 'https://phimimg.com/upload/vod/20231125-1/2303d5bc87f8f6a53e730492a3777611.jpg', 'https://phimimg.com/upload/vod/20231125-1/2dbf9e78f2a71e9c9155ab1e4eb50819.jpg', '<p>Ở Memphis, Tennessee, chỉ trong một đêm, Khách sạn Arcade, được điều hành bởi một nhân viên bán hàng ban đêm lập dị và một người phục vụ không biết gì, được một cặp vợ chồng trẻ người Nhật Bản đi du lịch tìm kiếm cội nguồn của nhạc rock ghé thăm; một phụ nữ Ý đang để tang tình cờ gặp một cô gái lang băm đang bỏ trốn; và bộ ba trộm tình cờ hài hước đang tìm chỗ trốn.</p>', 'Full', 1, 'single', 'completed', 13, 1989, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Youki Kudoh","avatar":""},{"name":"Masatoshi Nagase","avatar":""},{"name":"Screamin'' Jay Hawkins","avatar":""},{"name":"Cinqué Lee","avatar":""},{"name":"Nicoletta Braschi","avatar":""},{"name":"Elizabeth Bracco","avatar":""},{"name":"Joe Strummer","avatar":""},{"name":"Rick Aviles","avatar":""},{"name":"Steve Buscemi","avatar":""},{"name":"Tom Noonan","avatar":""},{"name":"Rufus Thomas","avatar":""},{"name":"Tom Waits","avatar":""},{"name":"Jodie Markell","avatar":""},{"name":"William Hoch","avatar":""},{"name":"Pat Hoch","avatar":""},{"name":"Joshua Elvis Hoch","avatar":""},{"name":"Reginald F","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324546);
