INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-tich', 'Kỳ Tích', 'The Canton Godfather', 'https://phimimg.com/upload/vod/20231124-1/60e71a858e00662636b4fd7adc42f61e.jpg', 'https://phimimg.com/upload/vod/20231124-1/b25294969c5d5ffbc8635d26ebf87094.jpg', '<p>Thành Long vào vai của một thanh niên nông dân người đã cứu được con trai của một têm trùm băng đảng và sau đó anh trở thành đầu lĩnh của băng nhóm này. Anh và cô ca sĩ hộp đêm của băng đảng cùng có những nghĩa cử tốt dành cho bà lão bán hoa hồng khi con gái bà đến thăm trong khi cuộc chiến giữa các băng nhóm đối nghịch đang trở nên gay gắt…</p>', 'Full', 1, 'single', 'completed', 15, 1989, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Anita Mui","avatar":""},{"name":"Gua Ah-leh","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Ko Chun-Hsiung","avatar":""},{"name":"Sunny Fang Kang","avatar":""},{"name":"Bill Tung","avatar":""},{"name":"Feng Tien","avatar":""},{"name":"Ngai Jan","avatar":""},{"name":"Gloria Yip Wan-Yee","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Lo Lieh","avatar":""},{"name":"Lee Hoi-Sang","avatar":""},{"name":"Michael Chow Man-Kin","avatar":""},{"name":"Paul Che Biu-law","avatar":""},{"name":"Ray Lui","avatar":""},{"name":"David Lui","avatar":""},{"name":"Mars","avatar":""},{"name":"Kenn","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324546);
