INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-lenh-hanh-quyet', 'Điệp Viên 007: Lệnh Hành Quyết', 'Licence to Kill', 'https://phimimg.com/upload/vod/20231121-1/8b0a754bfec81d4c973f5fb26215e69f.jpg', 'https://phimimg.com/upload/vod/20231121-1/4ad2e285b6c1d828b4f95adf6d7eaa75.jpg', '<p>Khi trùm ma tuý Franz Sanchez tìm cách trả thù người bạn của 007 (Felix Leiter) một cách dã man, Bonds quyết định từ bỏ Cơ quan tình báo Anh và bắt đầu những hành động chống lại thế lực đen tối này. Anh nhận ra mình sẽ không thể sống thoải mái nếu như Sanchez không thất bại. Và để hoàn thành mục tiêu, 007 liên kết với nữ phi công xinh đẹp và cô bạn gợi tình của Sanchezis. Chiến thắng được thế giới ngầm thật không dễ dàng, Bond đã phải vượt qua cuộc rượt đuổi bằng thuyền, vật lộn cả trên không trung trong một chiếc máy bay không người lái và những cuộc đối đầu trên sa mạc Mexico đầy nguy hiểm, chết chóc.</p>', 'Full', 1, 'single', 'completed', 16, 1989, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Timothy Dalton","avatar":""},{"name":"Carey Lowell","avatar":""},{"name":"Robert Davi","avatar":""},{"name":"Talisa Soto","avatar":""},{"name":"Anthony Zerbe","avatar":""},{"name":"Frank McRae","avatar":""},{"name":"Everett McGill","avatar":""},{"name":"Wayne Newton","avatar":""},{"name":"Benicio del Toro","avatar":""},{"name":"Anthony Starke","avatar":""},{"name":"Pedro Armendáriz Jr.","avatar":""},{"name":"Desmond Llewelyn","avatar":""},{"name":"David Hedison","avatar":""},{"name":"Priscilla Barnes","avatar":""},{"name":"Robert Brown","avatar":""},{"name":"Caroline Bliss","avatar":""},{"name":"Don","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324546);
