INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('monsieur-hire', 'Monsieur Hire', 'Monsieur Hire', 'https://phimimg.com/upload/vod/20231123-1/854c4e07cb285e09239beaedb9279d4d.jpg', 'https://phimimg.com/upload/vod/20231123-1/60fab00522e7082b5525019e69191988.jpg', '<p>Một người đàn ông Pháp theo dõi một phụ nữ trẻ đáng yêu trên đường đi. Khi anh ta bị người phụ nữ phát hiện ngay sau khi bị cảnh sát thẩm vấn về một vụ giết người ở địa phương, cuộc sống đơn giản của người đàn ông trở nên phức tạp hơn.</p>', 'Full', 1, 'single', 'completed', 15, 1989, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Michel Blanc","avatar":""},{"name":"Sandrine Bonnaire","avatar":""},{"name":"Luc Thuillier","avatar":""},{"name":"André Wilms","avatar":""},{"name":"Philippe Dormoy","avatar":""},{"name":"Marie Gaydu","avatar":""},{"name":"Cristiana Réali","avatar":""},{"name":"Michel Morano","avatar":""},{"name":"Nora Noël","avatar":""},{"name":"Bernard Soufflet","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324546);
