INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-bachelors-swan-song', 'The Bachelor''s Swan Song', 'The Bachelor''s Swan Song', 'null', 'https://phimimg.com/upload/vod/20231129-1/97d213f374a1f53595d361a207075dce.jpg', '<p>Chen Zinan và Zhang Xiaoyu đã yêu nhau nhiều năm. Họ nói với bố mẹ và kết hôn vì Xiaoyu nghĩ rằng cô đã có thai. Zinan đầu tư vào ngoại tệ và dùng hết số tiền tiết kiệm được cho việc kết hôn. Vì vậy họ phải vay tiền cho vay nặng lãi để cưới. Không ngờ, chủ nợ đến đòi nợ trước ngày cưới. Zinan phải trả lại họ món quà bằng tiền mặt vì đã trả tiền cho bữa tiệc. Thật khó để thu thập toàn bộ số tiền, nhưng nó đã bị cướp trong đêm đó. Zinan đã giúp cảnh sát lấy lại tiền và cũng xóa bỏ mối nghi ngờ của chủ nợ.</p>', 'Full', 1, 'single', 'completed', 25, 1989, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Maggie Cheung","avatar":""},{"name":"Kenny Bee","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Lawrence Cheng","avatar":""},{"name":"Fung Woo","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Meg Lam Kin-Ming","avatar":""},{"name":"Lydia Shum Tin-Ha","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Lam Kau","avatar":""},{"name":"Tai Bo","avatar":""},{"name":"Alfred Cheung Kin-Ting","avatar":""},{"name":"Pauline Wong Siu-Fung","avatar":""},{"name":"Jamie Luk Kim-Ming","avatar":""},{"name":"Ronald Wong Ban","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324546);
