INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-cha-me', 'Làm Cha Mẹ', 'Parenthood', 'https://phimimg.com/upload/vod/20231115-1/44ae22308db04be4815c6e8c25bdb6ea.jpg', 'https://phimimg.com/upload/vod/20231115-1/f8a4cd12831d44d8e5f351aa738c4dbe.jpg', '<p>Câu chuyện về gia đình Buckman và những người bạn, cố gắng nuôi dạy con cái của họ. Họ đau khổ/tận hưởng tất cả những sự kiện xảy ra: họ hàng ghẻ lạnh, &#39;con cừu đen&#39; của gia đình, những kẻ lập dị, những bộ xương trong tủ quần áo và những thanh thiếu niên nổi loạn.</p>', 'Full', 1, 'single', 'completed', 16, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Martin","avatar":""},{"name":"Mary Steenburgen","avatar":""},{"name":"Dianne Wiest","avatar":""},{"name":"Jason Robards","avatar":""},{"name":"Rick Moranis","avatar":""},{"name":"Tom Hulce","avatar":""},{"name":"Martha Plimpton","avatar":""},{"name":"Keanu Reeves","avatar":""},{"name":"Harley Jane Kozak","avatar":""},{"name":"Joaquin Phoenix","avatar":""},{"name":"Dennis Dugan","avatar":""},{"name":"Eileen Ryan","avatar":""},{"name":"Helen Shaw","avatar":""},{"name":"Jasen Fisher","avatar":""},{"name":"Paul Linke","avatar":""},{"name":"Alisan Porter","avatar":""},{"name":"Zachary La Voy","avatar":""},{"name":"Ivyann","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324546);
