INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('burning-sensation', 'Burning Sensation', 'Burning Sensation', 'https://phimimg.com/upload/vod/20231109-1/f042c3a1570be34a8f75588c2849299f.jpg', 'https://phimimg.com/upload/vod/20231109-1/9373af2530d1dc87098e6fa9d8ed15cd.jpg', '<p>Một lính cứu hỏa đã trục vớt một ngôi đền tâm linh từ một tòa nhà cũ đang cháy, nơi thả hồn ma hiền lành của một ca sĩ kinh kịch Trung Quốc, đã thiệt mạng trong một vụ cháy sân khấu 30 năm trước. Biết ơn vì đã cứu cô, con ma đã yêu người lính cứu hỏa và sẽ không dừng lại để đảm bảo an toàn cho anh ta khỏi những tệ nạn rình rập phía trước. Đồng thời, người lính cứu hỏa không nhận ra mình đang hẹn hò với một hồn ma.</p>', 'Full', 1, 'single', 'completed', 17, 1989, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Kenny Bee","avatar":""},{"name":"Carol Cheng","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Eva Lai Yin-Shan","avatar":""},{"name":"James Wong","avatar":""},{"name":"James Tien Chuen","avatar":""},{"name":"Blackie Ko Shou-Liang","avatar":""},{"name":"Teddy Yip Wing-Cho","avatar":""},{"name":"Clifton Ko Chi-Sum","avatar":""},{"name":"Yuen Miu","avatar":""},{"name":"Richard Yuen Tak","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324546);
