INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dead-poets-society', 'Dead Poets Society', 'Dead Poets Society', 'https://phimimg.com/upload/vod/20231109-1/ae3cc8779e45bff72ca830a3c9fb3d28.jpg', 'https://phimimg.com/upload/vod/20231109-1/1b623af678fadd24708789af24a0bca1.jpg', '<p>Đau đớn, Todd Anderson nhút nhát đã được gửi đến trường nơi anh trai nổi tiếng của ông là Valedictorian. Bạn cùng phòng của anh ấy, Neil Perry, mặc dù cực kỳ tươi sáng và phổ biến, rất nhiều dưới ngón tay cái của cha hống hách của anh ấy. Hai người, cùng với những người bạn khác của họ, gặp gỡ giáo sư Keat, giáo viên tiếng Anh mới của họ, người nói với họ về xã hội nhà thơ chết và khuyến khích họ đi ngược lại hiện trạng. Mỗi người không theo cách riêng của mình, và được thay đổi cho cuộc sống.</p>', 'Full', 1, 'single', 'completed', 17, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Robert Sean Leonard","avatar":""},{"name":"Gale Hansen","avatar":""},{"name":"Josh Charles","avatar":""},{"name":"Dylan Kussman","avatar":""},{"name":"Allelon Ruggiero","avatar":""},{"name":"James Waterston","avatar":""},{"name":"Norman Lloyd","avatar":""},{"name":"Kurtwood Smith","avatar":""},{"name":"Carla Belver","avatar":""},{"name":"Leon Pownall","avatar":""},{"name":"George Martin","avatar":""},{"name":"Joe Aufiery","avatar":""},{"name":"Matt Carey","avatar":""},{"name":"Kevin Cooney","avatar":""},{"name":"Jane Moore","avatar":""},{"name":"Lara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324546);
