INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-yeu-anh-da-thu-nho-cac-con', 'Em yêu, Anh Đã Thu Nhỏ Các Con', 'Honey, I Shrunk the Kids', 'https://phimimg.com/upload/vod/20231101-1/c452d07a038a11e582784203f81eb50b.jpg', 'https://phimimg.com/upload/vod/20231101-1/cf204a2da82d89a77c527c041c11bfc5.jpg', '<p>Wayne Szalinski là một nhà khoa học tài ba, trong suốt 5 năm trời nghiên cứu ông đã phát minh ra cái máy có thể thu nhỏ mọi thứ nhưng ông vẫn chưa tìm ra các nào có thể giảm cường độ của laser khiến các mẫu thử nghiệm bị nổ tung. Trong một lần tình cờ, khi Wayne đi vắng, các con anh đã trở thành vật thí nghiệm thành công của phát minh mới.Trở về nhà, Wayne hốt hoảng khi các con mất tích. Từ đây, một cuộc hành trình đầy gian nan và nguy hiểm của những đứa trẻ để có thể trở về nhà bắt đầu diễn ra...</p>', 'Full', 1, 'single', 'completed', 15, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rick Moranis","avatar":""},{"name":"Matt Frewer","avatar":""},{"name":"Marcia Strassman","avatar":""},{"name":"Kristine Sutherland","avatar":""},{"name":"Thomas Wilson Brown","avatar":""},{"name":"Jared Rushton","avatar":""},{"name":"Amy O''Neill","avatar":""},{"name":"Robert Oliveri","avatar":""},{"name":"Carl Steven","avatar":""},{"name":"Mark L. Taylor","avatar":""},{"name":"Kimmy Robertson","avatar":""},{"name":"Lou Cutell","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Sammy (dog)","avatar":""},{"name":"Craig Richard Nelson","avatar":""},{"name":"Scott Martin","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0b