INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('indiana-jones-va-cuoc-thap-tu-chinh-cuoi-cung', 'Indiana Jones và Cuộc Thập Tự Chinh Cuối Cùng', 'Indiana Jones and the Last Crusade', 'https://phimimg.com/upload/vod/20231022-1/8b6e2c5d0ab03e45cb02f4b4e1b454a9.jpg', 'https://phimimg.com/upload/vod/20231022-1/113365d6408e1f19ec9aad25365af023.jpg', '<p>Truyền thuyết bắt đầu từ cuối thể kỷ 12, ngủ yên qua hơn 7 thế kỷ cho đến tận bây giờ, khi Hitler ôm mộng bá chủ thế giới và đánh thức quá khứ. Ngoài việc dùng quân đội xâm chiếm các nước khác trên khắp Châu Âu, hắn còn sử dụng riêng một đạo quân chuyên săn tìm các bảo vật quí giá để tìm hiểu những sức mạnh kỳ diệu từ truyền thuyết. Liệu indy có tìm được chiếc cốc thánh và ngăn chặn được âm mưu của Hitler?</p>', 'Full', 1, 'single', 'completed', 17, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Sean Connery","avatar":""},{"name":"Denholm Elliott","avatar":""},{"name":"Alison Doody","avatar":""},{"name":"John Rhys-Davies","avatar":""},{"name":"Julian Glover","avatar":""},{"name":"River Phoenix","avatar":""},{"name":"Michael Byrne","avatar":""},{"name":"Kevork Malikyan","avatar":""},{"name":"Robert Eddison","avatar":""},{"name":"Richard Young","avatar":""},{"name":"Alexei Sayle","avatar":""},{"name":"Alex Hyde-White","avatar":""},{"name":"Paul Maxwell","avatar":""},{"name":"Isla Blair","avatar":""},{"name":"Vernon Dobtcheff","avatar":""},{"name":"J.J. Hard","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324546);
