INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-quang', 'Vinh Quang', 'Glory', 'https://phimimg.com/upload/vod/20231016-1/5eee3288a26dfe42c72b233b978b9cff.jpg', 'https://phimimg.com/upload/vod/20231016-1/063733da75edd87b8fbfb04ba8c559b5.jpg', '<p>Bộ phim là bản anh hùng ca về 1 trung đoàn gồm toàn những người lính da đen trong cuộc nội chiến Hoa Kỳ. Đại uý Robert Shaw là 1 sĩ quan Hợp chủng quốc da trắng có nhiệm vụ đưa 700 người lính da đen nghèo khó tới trận chiến với quân Đồng minh. Nhưng kẻ thù thực sự Shaw phải đối mặt khi bảo vệ cấp dưới của mình chính là phe của anh.</p>', 'Full', 1, 'single', 'completed', 21, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Matthew Broderick","avatar":""},{"name":"Denzel Washington","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Morgan Freeman","avatar":""},{"name":"Jihmi Kennedy","avatar":""},{"name":"Andre Braugher","avatar":""},{"name":"John Finn","avatar":""},{"name":"Donovan Leitch","avatar":""},{"name":"JD Cullum","avatar":""},{"name":"Bob Gunton","avatar":""},{"name":"Cliff DeYoung","avatar":""},{"name":"Christian Baskous","avatar":""},{"name":"RonReaco Lee","avatar":""},{"name":"Jay O. Sanders","avatar":""},{"name":"Alan North","avatar":""},{"name":"Richard Riehle","avatar":""},{"name":"Peter Michael Go","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324546);
