INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-doi-1989', 'Người Dơi', 'Batman', 'https://phimimg.com/upload/vod/20231015-1/553a889155ab32c025d3bf468c8d6d5d.jpg', 'https://phimimg.com/upload/vod/20231015-1/ba50be84a6d65d50bdbd7bdbede1f5f2.jpg', '<p>Hiệp sĩ bóng tối của thành phố Gotham đụng độ kẻ thù đầu tiên của mình: tên Jocker có bộ mặt thằng hề, một kẻ nguy hiểm đang lên kế hoạch phun khí độc để khiến mọi người đều chết với bộ mặt cười như hắn. Một nữ phóng viên cố gắng tìm cách lần ra dấu vết của Batman và nàng lại rơi vào vòng tay của chàng tỷ phu Bruce Wayne..</p>', 'Full', 1, 'single', 'completed', 19, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Keaton","avatar":""},{"name":"Jack Nicholson","avatar":""},{"name":"Kim Basinger","avatar":""},{"name":"Michael Gough","avatar":""},{"name":"Jerry Hall","avatar":""},{"name":"Robert Wuhl","avatar":""},{"name":"Pat Hingle","avatar":""},{"name":"Billy Dee Williams","avatar":""},{"name":"Jack Palance","avatar":""},{"name":"Tracey Walter","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324546);
