INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('halloween-5-michael-myers-bao-thu', 'Halloween 5: Michael Myers Báo Thù', 'Halloween 5: The Revenge of Michael Myers', 'https://phimimg.com/upload/vod/20231015-1/e68645fce52df89472b35f177fe61dcc.jpg', 'https://phimimg.com/upload/vod/20231015-1/0940048717725d8cd47fb9e6261de365.jpg', '<p>Được cho là đã chết sau cuộc đấu súng với cảnh sát Haddonfield, Michael Myers được bí mật chăm sóc sức khỏe trở lại - và một năm sau quay trở lại để giết người một lần nữa và một lần nữa nhắm vào cháu gái nhỏ của mình, Jamie. Jamie hiện đang hồi phục tại bệnh viện nhi địa phương sau khi tấn công mẹ kế và khiến bà bị mất giọng. Mối liên hệ tinh thần của cô với người chú độc ác có thể là chìa khóa để nhổ bỏ cây phả hệ của cô.</p>', 'Full', 1, 'single', 'completed', 16, 1989, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Donald Pleasence","avatar":""},{"name":"Danielle Harris","avatar":""},{"name":"Ellie Cornell","avatar":""},{"name":"Wendy Foxworth","avatar":""},{"name":"Beau Starr","avatar":""},{"name":"Don Shanks","avatar":""},{"name":"Jeffrey Landman","avatar":""},{"name":"Tamara Glynn","avatar":""},{"name":"Matthew Walker","avatar":""},{"name":"Betty Carvalho","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324546);
