INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-fishy-story', 'A Fishy Story', 'A Fishy Story', 'null', 'https://phimimg.com/upload/vod/20231013-1/7c3768cd872a6b7cf269a9696aad5dd7.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">Vào cuối&nbsp;</span><span class="" style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">những năm 20 của thế kỷ 60, các cuộc bạo loạn cánh tả quét qua Hồng Kông và tình hình hỗn loạn.<br/>Từ nông thôn đến đô thị, Xiaoyu (do Maggie Cheung thủ vai) là một diễn viên nhỏ không có lối thoát, và anh ấy thực sự làm bất cứ điều gì cần thiết để lên đỉnh cao vì tiền. Với sự giúp đỡ của một đạo diễn, Xiaoyu chuyển đến một căn hộ mới và gặp Ah Gong (do Zhong Zhentao thủ vai), người sống trên sân thượng một cách tình cờ. Ah Kung nghèo khó làm tài xế taxi nhãn trắng vào ban ngày và trở thành bạn tình của bà Kuo vào ban đêm. Từ sự khinh miệt và thù hận ban đầu, hai người dị dạng cuối cùng đã đến với nhau. Họ làm việc chăm chỉ để kiếm tiền và điều hành cuộc sống của họ, nhưng tình hình sóng gió vẫn phá vỡ hạnh phúc nhỏ bé của họ hết lần này đến lần khác...<br/>Bộ phim đã giành được ba giải thưởng tại Giải thưởng Điện ảnh Hồng Kông năm 1990 cho Nữ diễn viên chính xuất sắc nhất (Maggie Cheung), Chỉ đạo nghệ thuật xuất sắc nhất và Kịch bản hay nhất.</span></p>', 'Full', 1, 'single', 'completed', 16, 1989, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Maggie Cheung","avatar":""},{"name":"Chung Zhentao","avatar":""},{"name":"Chen You","avatar":""},{"name":"Gu Meihua","avatar":""},{"name":"Wu Jiali","avatar":""},{"name":"Lý Diên Lang","avatar":""},{"name":"Lâm Công","avatar":""},{"name":"Tân Càn Hồng","avatar":""},{"name":"Bảo Đức Khê","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324546);
