INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-hoi-tam-hoang', 'Cuộc Chiến Hội Tam Hoàng', 'Triads The Inside Story', 'https://phimimg.com/upload/vod/20231012-1/e15b806b65df83a4ec22c710887c2830.jpg', 'https://phimimg.com/upload/vod/20231012-1/e7b9f9d955154d990cfbe3a9ed71d2cb.jpg', '<p>Nổi lên từ những vai diễn “để đời” tại TVB, Châu Nhuận Phát ngày càng trở nên nổi tiếng với những vai diễn trong phim điện ảnh, ông liên tục góp mặt trong những siêu phẩm hành động – xã hội đen của điện ảnh Hồng Kông, trong đó ngoài những vai diễn dạng “sát thủ thầm lặng” thì tài tử họ Châu còn rất xuất sắc với những vai diễn cần nhiều cảm xúc mà tiêu biểu phải kể đến Cuộc Chiến Hội Tam Hoàng của đạo diễn danh tiếng Taylor Wong. Phim khai thác những góc khuất trong cuộc chiến ngầm của những băng đảng xã hội đen Hồng Kông thập niên 80 thế kỷ trước, dàn diễn viên quy tụ đều là những cái tên rất quen thuộc với thể loại này như Trương Diệu Dương, Trần Huệ Mẫn, Thành Khuê An, Tăng Giang… tất cả mang đến một tựa phim chất lượng cả về diễn xuất cho tới tạo hình.</p>', 'Full', 1, 'single', 'completed', 18, 1989, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Roy Cheung","avatar":""},{"name":"Michael Chan","avatar":""},{"name":"Connie Mak","avatar":""},{"name":"Tien Feng","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Sit Chi-Lun","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Lam Kau","avatar":""},{"name":"Lung Ming-Yan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324546);
