INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-diet-nhan-chung', 'Tiêu Diệt Nhân Chứng', 'In The Line Of Duty 4', 'https://phimimg.com/upload/vod/20231007-1/d524ec721b72d1a6da618a8a73784bb3.jpg', 'https://phimimg.com/upload/vod/20231007-1/937f8db99abe3699c47cf523249d5a2f.jpg', '<p>Hai thám tử đang gặp rắc rối và đối mặt nhau khi họ cố gắng ngăn chặn một kế hoạch buôn bán ma túy có thể liên quan đến mối quan hệ quốc tế với tội phạm có tổ chức. Nhưng giữa cuộc điều tra của họ, công nhân bến tàu nhập cư vô tội Luk Wan-Ting bị cuốn vào cuộc hỗn chiến khi anh chứng kiến vụ sát hại một nhân viên tình báo và bị buộc tội.</p>', 'Full', 1, 'single', 'completed', 33, 1989, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cynthia Khan","avatar":""},{"name":"Donnie Yen","avatar":""},{"name":"Michael Wong","avatar":""},{"name":"Simon Yuen Yat-Choh","avatar":""},{"name":"Lisa Chiao Chiao","avatar":""},{"name":"Wai Gei-Shun","avatar":""},{"name":"Yuen Shun-Yi","avatar":""},{"name":"Michael Woods","avatar":""},{"name":"John Salvitti","avatar":""},{"name":"Stephen Berwick","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324546);
