INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-a-long', 'Chuyện Tình A Long', 'All About Ah Long', 'https://phimimg.com/upload/vod/20231006-1/077aa78f54848d3c2e31d61d227ba954.jpg', 'https://phimimg.com/upload/vod/20231006-1/7733f494b7fdc38bf231f802fa8a6c4a.jpg', '<p>All About A Long kể về câu chuyện gia đình của nhân vật chính A Long (Châu Nhuận Phát) – 1 tay đua xe chuyên nghiệp. Do mâu thuẫn với về đặc thù nghề nghiệp, vợ anh đã quyết định ly hôn, sang nước ngoài sinh sống và để cậu con trai bé nhỏ ở lại. Từ đó, A Long quyết định chuyển công tác, lựa chọn công việc khác. Nhiều năm sau, người phụ nữ này trở về Hồng Kông đề nghị đưa con trai sang Mỹ cùng sinh sống. Để cứu vãn tình thế, A Long trở lại với đường đua và trong lần tái xuất này anh đã rủi ro gặp tai nạn qua đời, để lại nỗi xót thương vô hạn cho con trai và cả người bạn gái sắp tái hôn.</p>', 'Full', 1, 'single', 'completed', 27, 1989, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Sylvia Chang","avatar":""},{"name":"Wong Kwan-Yuen","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"Wong Tin-lam","avatar":""},{"name":"Alan Yu Ga-Lun","avatar":""},{"name":"Tam Sin-Hung","avatar":""},{"name":"Joe Chu Kai-Sang","avatar":""},{"name":"Sze Kai-Keung","avatar":""},{"name":"Tsui Oi-Sam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324546);
