INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phich-lich-tien-phong-phan-xet-cuoi-cung', 'Phích Lịch Tiên Phong (Phán Xét Cuối Cùng)', 'Final Justice', 'https://phimimg.com/uploads/movies/20260713/phich-lich-tien-phong-phan-xet-cuoi-cung-thumb.webp', 'https://phimimg.com/uploads/movies/20260713/phich-lich-tien-phong-phan-xet-cuoi-cung-poster.webp', '<p>Trương là một cảnh sát trẻ tài ba mẫn cán tại Hồng Kông. Tình cờ gặp tên lưu manh A Huy, Trương quyết định thả hắn để sau này còn sử dụng Huy nhằm thâm nhập thế giới ngầm.
 Trong một phi vụ buôn vũ khí lớn, A Huy được sử dụng làm tay trong, xâm nhập hang ổ bọn tội phạm. Kế hoạch có nguy cơ đổ bể nhưng Trương bất chấp chỉ thị cấp trên, tìm mọi cách để giữ mạng sống cho Huy.</p>', 'Full', 1, 'single', 'completed', 49, 1988, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Danny Lee Sau-Yin","avatar":""},{"name":"Stephen Chow","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Tommy Wong","avatar":""},{"name":"Victor Hon Kwan","avatar":""},{"name":"Ricky Wong Chun-Tong","avatar":""},{"name":"Ken Lo Wai-Kwong","avatar":""},{"name":"Chiu Jun-Chiu","avatar":""},{"name":"Wong Aau","avatar":""},{"name":"Debbie Chui","avatar":""},{"name":"Stephen Chang Gwong-Chin","avatar":""},{"name":"Hung Tung-Kim","avatar":""},{"name":"Ng Yuen-Sam","avatar":""},{"name":"Shing Fu-On","avatar":""},{"name":"Parkman Wong Pak-Man","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["霹靂先鋒","벽력선봉","霹雳先锋","Final Justice"]', 1784690324546);
