INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-ba-vuong', 'Nữ Bá Vương', 'The Inspector Wears Skirts', 'https://phimimg.com/upload/vod/20260420-1/b1edd7be07e8bbd0f59123b0cff240c8.jpg', 'https://phimimg.com/upload/vod/20260420-1/0b9391f06d61f8704324a4ae1c1269af.jpg', '<p>Bộ phim xoay quanh một biệt đội nữ cảnh sát phải đối mặt với sự quấy rối và thiếu tôn trọng từ các đồng nghiệp nam, các vấn đề cá nhân cũng như một số tội phạm nghiêm trọng.ts. Chẳng bao lâu nữa, họ sẽ phải chứng tỏ mình trong nhiệm vụ.</p>', 'Full', 1, 'single', 'completed', 22, 1988, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Cynthia Rothrock","avatar":""},{"name":"Sibelle Hu Hui-Chung","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Sandra Ng Kwan-Yu","avatar":""},{"name":"Ann Bridgewater","avatar":""},{"name":"Regina Kent","avatar":""},{"name":"Ellen Chan Nga-Lun","avatar":""},{"name":"Lee Pooi-Ling","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Mars","avatar":""},{"name":"Chan Tat-Kwong","avatar":""},{"name":"Nicky Li Chung-Chi","avatar":""},{"name":"Lai Ming-Si","avatar":""},{"name":"Lau Wai-Man","avatar":""},{"name":"Stanley Fung Shui-Fan","avatar":""},{"name":"Alex T","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Top Squad","Ba wong fa","Lady Enforcers","The Inspector Wears Skirts","霸王花"]', 1784690324546);
