INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-em-ac-mong', 'Chị em ác mộng', 'Nightmare Sisters', 'https://phimimg.com/upload/vod/20260409-1/39b9d111f68916ddb18328be65c82361.jpg', 'https://phimimg.com/upload/vod/20260409-1/93c4484a7b2e8f3b526b1ea4e8d913b7.jpg', '<p>Ba cô gái nhút nhát trong hội nữ sinh mời ba chàng trai mới gia nhập hội nam sinh đến chơi một đêm vui vẻ, nhưng khi cả nhóm tổ chức một buổi gọi hồn, các cô gái phát hiện mình bị một pháp sư nhập hồn và biến thành những nữ quỷ dâm đãng, phóng túng.</p>', 'Full', 1, 'single', 'completed', 58, 1988, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Linnea Quigley","avatar":""},{"name":"Brinke Stevens","avatar":""},{"name":"Michelle Bauer","avatar":""},{"name":"Timothy Kauffman","avatar":""},{"name":"Matthew Phelps","avatar":""},{"name":"C. Jay Cox","avatar":""},{"name":"Richard Gabai","avatar":""},{"name":"Marcus Vaughter","avatar":""},{"name":"William Dristas","avatar":""},{"name":"James R. Sweeney","avatar":""},{"name":"Sandy Brooke","avatar":""},{"name":"Michael Sonye","avatar":""},{"name":"Kenneth J. Hall","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Koszmarne siostry","Кошмарные сёстры","Sorority Sisters","Sorority Succubus Sisters","Explosion der Leidenschaften","ナイトメア・シスターズ","Nightmare Sisters"]', 1784690324546);
