INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-quy-quai', 'Ngôi Nhà Quỷ Quái', 'Bless This House', 'https://phimimg.com/upload/vod/20260211-1/687eb2f2035bb3bce34b0030bcd7a456.jpg', 'https://phimimg.com/upload/vod/20260211-1/d35c7ef19d14196d561502303f742f33.jpg', '<p>Kiến trúc sư Chú Phiêu (Đổng Phiêu đóng) đã làm việc chăm chỉ trong ngành suốt 20 năm. Gần đây, nhờ một bản thiết kế được ông chủ đánh giá cao, ông không chỉ được thăng chức mà còn được ban quyền sử dụng một căn biệt thự trong núi. Chú Phiêu cùng vợ (Địch Ba Lạp đóng) hớn hở chia tay căn nhà cũ chật chội, đưa con gái lớn A Trân (Lý Lệ Trân đóng) và bạn trai của cô là Đại Cựu (Hà Khải Nam đóng) đến thăm biệt thự. Mặc dù nội thất cần được mua sắm lại và A Trân nhìn thấy những bóng đen khả nghi trong nhà, nhưng điều đó vẫn không ngăn được niềm vui dọn nhà mới của cả gia đình. Tuy nhiên, chẳng bao lâu sau, hàng loạt sự việc kỳ quái đã xảy ra. Trên căn gác mái lộn xộn dường như ẩn náu những hồn ma mang ác ý với gia đình Chú Phiêu. Sau khi chuyên gia bắt quái do Đại Cựu mời đến bị lũ quỷ trêu chọc tơi tả, Chú Phiêu định chụp ảnh ác quỷ thì lại bị chúng nhập xác, khiến tính cách ông trở nên hung bạo bất thường. Ngay khi gia đình sắp phải lặp lại bi kịch tiền kiếp của lũ quỷ, một đạo sĩ độc nhãn sống gần đó (Lương Tiểu Long đóng) đã ra tay tương trợ...&quot;</p>', 'Full', 1, 'single', 'completed', 16, 1988, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Đổng Phiêu","avatar":""},{"name":"Địch Bác La","avatar":""},{"name":"Lý Lệ Trân","avatar":""},{"name":"Hà Khải Nam","avatar":""},{"name":"Lương Tiểu Long","avatar":""},{"name":"Văn Tuấn","avatar":""},{"name":"Trần Trác Ân","avatar":""},{"name":"Hàn Khuân","avatar":""},{"name":"Trần Nguyệt Nhi","avatar":""},{"name":"Maria Kent","avatar":""},{"name":"Ông Tử Trung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Haunted","猛鬼佛跳墙","SOS Maison hantée","猛鬼佛跳牆","Bless This House"]', 1784690324546);
