INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-pho-elm-4-ke-lam-chu-giac-mo', 'Ác Mộng Phố Elm 4: Kẻ Làm Chủ Giấc Mơ', 'A Nightmare on Elm Street 4: The Dream Master', 'https://phimimg.com/upload/vod/20260206-1/a7ee3a73946f3d74e424a6e17740cf1b.jpg', 'https://phimimg.com/upload/vod/20260206-1/e0691821e68e8a231fe8921c917252d1.jpg', '<p><br/></p><p><br/></p><article>Ác mộng trên phố Elm 4: Kẻ làm chủ giấc mơ Năm 1988, một năm sau các sự kiện của phần trước, Kristen, Kincaid và Joey đã được thả khỏi Westin Hills và trở lại cuộc sống như những thanh thiếu niên bình thường cùng gia đình. Tuy nhiên, Kristen tin rằng Freddy Krueger sẽ trở lại và khi cô ấy mơ thấy mình đang ở trong căn phòng nồi hơi cũ của Freddy, cô ấy đã triệu hồi Joey và Kincaid vào giấc mơ. Kincaid và Joey rất buồn vì cô ấy đã quay trở lại lối cũ khi họ còn ở Westin Hills.</article><p><br/></p>', 'Full', 1, 'single', 'completed', 19, 1988, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robert Englund","avatar":""},{"name":"Rodney Eastman","avatar":""},{"name":"Danny Hassel","avatar":""},{"name":"Andras Jones","avatar":""},{"name":"Tuesday Knight","avatar":""},{"name":"Ken Sagoes","avatar":""},{"name":"Lisa Wilcox","avatar":""},{"name":"Brooke Bundy","avatar":""},{"name":"Nicholas Mele","avatar":""},{"name":"Toy Newkirk","avatar":""},{"name":"Brooke Theiss","avatar":""},{"name":"John Beckman","avatar":""},{"name":"Kisha Brackel","avatar":""},{"name":"Wanda Bursey","avatar":""},{"name":"Hope Marie Carlton","avatar":""},{"name":"Kristen Clayton","avatar":""},{"name":"Duane Davis","avatar":""},{"name":"Rich","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Painajainen Elm Streetillä 4 – Unien valtias","Pesadilla en Elm Street 4: El amo del sueño","Rémálom az Elm utcában 4.: Az álmok ura","猛鬼街4","Freddy - Chapitre 4 - Le Cauchemar de Freddy","Le Cauchemar de Freddy 4","A Nightmare on Elm Street Part 4: Dream Master","Pesadilla en la Calle Elm 4 El Maestro de los Sueños","A Nightmare on Elm Street 4: The Dream Master","Freddy 4","Pesadilla en la Calle del Infierno 4","Freddy 4 - Le Cauchemar de Freddy","Pesadilla en la calle Elm 4: El Amo del Sueño","エルム街の悪夢4 ザ・ドリームマスター 最後の反撃","Koszmar z Ulicy Wiązów 4: Władca Snów","Жах на вулиці В''язів 4: Повелитель сну","Strava u Ulici brijestova 4: Gospodar snova","Noční můra v Elm Street 4: Vládce snu","Εφιάλτης στον δρόμο με τις λεύκες Νο 4","Кошмари на Елм стрийт 4: Господарят на сънищата","A Hora do Pesadelo 4: O Mestre dos Sonhos","Elmi tänava luupainaja 4","Martröð á Elmarsstræti 4: Drauma Meistarinn","Košmaras Guobų gatvėje. Sapnų valdovas","Terror på Elm Street 4 - Freddys mareritt","Nočná mora v Elm Street 4: Vládca snov","Terror på Elm Street 4 - Freddys mardröm","Elm Sokağı Kabusu 4: Rüya Ustası","Pesadilla 4: El dueño del sueño","Pesadilla en la calle del infierno 4","Nightmare 4 - Das wahre Böse stirbt nie"]', 1784690324546);
