INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-canh-sat-2', 'Câu Chuyện Cảnh Sát 2', 'Police Story 2', 'https://phimimg.com/upload/vod/20251222-1/6290ebdda74dd0cf5ffc19e7a23fe319.jpg', 'https://phimimg.com/upload/vod/20251222-1/5bc81a04076a2d0c5a02569c517197de.jpg', '<p>Sau sự kiện trong phần đầu, thanh tra Trần Gia Câu bị giáng chức xuống phục vụ tại lực lượng cảnh sát tuần tra giao thông. Nhiệm vụ mới của Gia Câu làm hài lòng bạn gái anh, Mỹ. Cô rất vui khi bạn trai của mình không còn phải đảm nhận các vụ án nguy hiểm và có nhiều thời gian hơn để gặp cô. Tuy nhiên, Trần Gia Câu sớm gặp lại Chu Thao và cánh tay phải của y là John Cao. Chu Thao được các bác sĩ kết luận chỉ còn sống được ba tháng nữa do trọng bệnh. Vì vậy hắn được tại ngoại để chữa bệnh. Chu Thao thề rằng ngày nào hắn còn sống thì cuộc sống của Gia Câu sẽ không yên bình. John Cao cùng một vài đàn em xuất hiện tại chung cư của Gia Câu và đe dọa với anh. Cảm thấy không an toàn, Gia Câu bảo Mỹ về nhà dì của cô lánh tạm. ...</p>', 'Full', 1, 'single', 'completed', 17, 1988, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Bill Tung Biu","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Lam Kwok-Hung","avatar":""},{"name":"Mars","avatar":""},{"name":"Benny Lai Keung-Kuen","avatar":""},{"name":"Kenny Ho Kar-King","avatar":""},{"name":"Johnny Cheung Wa","avatar":""},{"name":"Lung Tin-Sang","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Ben Lam Kwok-Bun","avatar":""},{"name":"Guan Shan","avatar":""},{"name":"Yeung Chak-Lam","avatar":""},{"name":"Teddy Yip Wing-Cho","avatar":""},{"name":"Wong Wai","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Lisa Chiao Chiao","avatar":""},{"name":"Dan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Police Story Part II","Ging chaat goo si juk jaap","Kowloon''s Eye","Police Force II","Police Story Sequel","Police Story 2: Codinome Radical","Police Story II","O anthropos vomva","警察故事2","Полицейская история 2","Jackie Chan - Police Story II","Codinome: Radical","ポリス･スト−リ−2 / 九龍の眼","警察故事續集"]', 1784690324546);
