INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-chien-tranh-1988', 'Quái Thú Chiến Tranh', 'The Beast of War', 'https://phimimg.com/upload/vod/20251028-1/35bbd13baedc32f29568d1788193dafe.jpg', 'https://phimimg.com/upload/vod/20251028-1/d6b6af3a86d4c3c6ee26032612a7ddad.jpg', '<p>Một chiếc xe tăng Liên Xô và đội quân chiến đấu của nó bị lạc khỏi đội tuần tra và bị lạc trong một thung lũng ở Afghanistan khi một nhóm phiến quân đang tìm cách trả thù đang truy đuổi họ.</p>', 'Full', 1, 'single', 'completed', 17, 1988, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"George Dzundza","avatar":""},{"name":"Jason Patric","avatar":""},{"name":"Steven Bauer","avatar":""},{"name":"Stephen Baldwin","avatar":""},{"name":"Don Harvey","avatar":""},{"name":"Kabir Bedi","avatar":""},{"name":"Erick Avari","avatar":""},{"name":"Chaim Jeraffi","avatar":""},{"name":"Shoshi Marciano","avatar":""},{"name":"Yitzhak Ne''eman","avatar":""},{"name":"David Sherrill","avatar":""},{"name":"Moshe Vapnik","avatar":""},{"name":"Claude Aviram","avatar":""},{"name":"Victor Ken","avatar":""},{"name":"Avi Keedar","avatar":""},{"name":"Osnat Mor","avatar":""},{"name":"Rami Heuberger","avatar":""},{"name":"Avi Gil","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Beast of War","La Bête de guerre","Bestias de la Guerra","The Beast"]', 1784690324546);
