INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-hiep-1988', 'Cưỡng Hiếp', 'Necromancer', 'https://phimimg.com/upload/vod/20251026-1/d81f805acb323900b5abf42f64f44d3e.jpg', 'https://phimimg.com/upload/vod/20251026-1/470a444b32a3d49dce1d2b7afee2439f.jpg', '<p>Julie, một nữ sinh đại học, bị hai bạn học tấn công tình dục. Trong cơn tuyệt vọng muốn trả thù, cô tìm đến một pháp sư gọi hồn, người bắt đầu sử dụng sức mạnh ma quỷ của mình để trừng phạt tất cả những gã đàn ông mà Julie căm ghét.</p>', 'Full', 1, 'single', 'completed', 21, 1988, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Elizabeth Kaitan","avatar":""},{"name":"John Tyler","avatar":""},{"name":"Rhonda Dorton","avatar":""},{"name":"Stan Hurwitz","avatar":""},{"name":"Lisa Beth Wilson","avatar":""},{"name":"Ed Wright","avatar":""},{"name":"Russ Tamblyn","avatar":""},{"name":"David Flynn","avatar":""},{"name":"Shawn Eisner","avatar":""},{"name":"Lois Masten Ewing","avatar":""},{"name":"Lisa Randolph","avatar":""},{"name":"Scott Harrison","avatar":""},{"name":"Keith Burns","avatar":""},{"name":"Carla Baron","avatar":""},{"name":"Jimmy Williams","avatar":""},{"name":"Shannon McLeod","avatar":""},{"name":"Waide Aaron Riddle","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Necromancer"]', 1784690324546);
