INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuong-hiep-1988', 'Cưỡng Hiếp', 'Necromancer', 'cưỡng hiếp necromancer elizabeth kaitan john tyler rhonda dorton stan hurwitz lisa beth wilson ed wright russ tamblyn david flynn shawn eisner lois masten ewing lisa randolph scott harrison keith burns carla baron jimmy williams shannon mcleod waide aaron riddle necromancer', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muc-tieu-cuoi-cung', 'Mục Tiêu Cuối Cùng', 'A Friend In Need', 'https://phimimg.com/upload/vod/20251010-1/99642a784b67923d9bbcaeea5b9c91b9.jpg', 'https://phimimg.com/upload/vod/20251010-1/32ec384a0f69e750b8a405b96722d97b.jpg', '<p>Lâm Hân thi rớt đại học, sau đó cô xin vào làm ở công ty thời trang của ông An. Tại đây, được sự khích lệ của Khương Thuấn Linh nên Hân theo học thiết kế thời trang và coi Linh là ân sư của mình. Bạn trai Hân, Phương Hạo Minh, cùng lúc có tình cảm với Nguyễn Khiết Trang, lại chính là bạn tri kỷ của Hân. Hơn nữa, Minh và Trang phải kết hôn vì trót có thai. Hân rất đau lòng, may có anh hàng xóm Quan Học Văn đến an ủi và khiến Hân mở lòng một lần nữa. Văn đã có lòng yêu thương Hân từ lâu, nhưng bởi anh là người sống nội tâm nên chưa bao giờ tỏ lòng với Hân. Vì công việc, Linh làm quen với nhiếp ảnh Hạ Tổ Âm, hai người nhanh chóng trở thành một đôi. Vì bất đồng quan điểm, Linh rời khỏi công ty, sau đó cùng Hân mở công ty khác. Tổ Âm tuyệt đối ủng hộ việc này. Sau một thời gian tiếp xúc, Âm và Hân lại dần có tình cảm với nhau. Tính tình của Linh mạnh mẽ, cô dùng mọi thủ đoạn để chiến thắng trong sự nghiệp. Tổ Âm coi thường hành vi của Linh, dành hết tình cảm cho Hân. Linh thất bại trong sự nghiệp lẫn tình yêu, mẹ cô lại qua đời, cô hận Hân nên hại gia đình Hân. Tổ Âm có dự án quay phim tài liệu tại Châu Phi, anh có ý muốn Hân đi cùng, nhưng Hân rất khó quyết định. Liệu Hân có can đảm cùng Tổ Âm bay tới chân trời mới?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 18, 1988, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Jacqueline Law Wai-Guen","avatar":""},{"name":"Fiona Leung Ngai-Ling","avatar":""},{"name":"Leon Lai","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Jaime Chik Mei-Chun","avatar":""},{"name":"David Siu Chung-Hang","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Chim Bing-Hei","avatar":""},{"name":"William So Wing-Hong","avatar":""},{"name":"So Hang-Suen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["飛躍霓裳"]', 1784690324546);
