INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-dom-dom', 'Mộ Đom Đóm', 'Grave Of The Fireflies', 'https://phimimg.com/upload/vod/20250907-1/bd0c692102c0ed564ffce84f19f100a9.jpg', 'https://phimimg.com/upload/vod/20250907-1/029dbce2d9baca1c1c8cdd0ea0108e16.jpg', '<p>Bộ phim được đặt trong bối cảnh giai đoạn cuối chiến tranh thế giới thứ 2 ở Nhật, kể về câu chuyện cảm động về tình anh em của hai đứa trẻ mồ côi là Seita và Setsuko. Hai anh em mất mẹ trong một trận bom dữ dội của không quân Mỹ khi cha của chúng đang chiến đấu cho Hải quân Nhật. Hai đứa bé phải vật lộn giữa nạn đói, giữa sự thờ ơ của những người xung quanh (trong đó có cả người cô họ của mình)...</p>', 'Full', 1, 'hoathinh', 'completed', 22, 1988, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Tsutomu Tatsumi","avatar":""},{"name":"Ayano Shiraishi","avatar":""},{"name":"Yoshiko Shinohara","avatar":""},{"name":"Akemi Yamaguchi","avatar":""},{"name":"Masayo Sakai","avatar":""},{"name":"Kozo Hashida","avatar":""},{"name":"Kazumi Nozaki","avatar":""},{"name":"Yoshio Matsuoka","avatar":""},{"name":"Masahiro Kanetake","avatar":""},{"name":"Kiyoshi Yanagawa","avatar":""},{"name":"Hajime Maki","avatar":""},{"name":"Atsuo Omotem","avatar":""},{"name":"Teruhisa Harita","avatar":""},{"name":"Hiroshi Tanaka","avatar":""},{"name":"Michio Denpo","avatar":""},{"name":"Shiro Tamaki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["再见萤火虫","Die letzten Leuchtkäfer","再見螢火蟲","Graf van de Vuurvliegjes","Căn hầm đom đóm","Jaanimardikate haud","Jonvabalių kapas","سيتا الحنون","Mormântul Licuricilor","Могила светлячков","Una tomba per le lucciole","ग्रेव ऑफ फिरेफ़्लिएस","火垂るの墓","Túmulo dos Vagalumes","Grave of the Fireflies สุสานหิ่งห้อย","O Túmulo dos Pirilampos","Grave of the Fireflies","Ateşböceklerinin Mezarı","La tumba de las luciérnagas","반딧불의 묘","Atəşböcəyinin Məzarı","Hotaru no Haka","Yonar Qo‘ng‘izlar Qabri","O Túmulo dos Vagalumes"]', 1784690324546);
