INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mo-dom-dom', 'Mộ Đom Đóm', 'Grave Of The Fireflies', 'mộ đom đóm grave of the fireflies tsutomu tatsumi ayano shiraishi yoshiko shinohara akemi yamaguchi masayo sakai kozo hashida kazumi nozaki yoshio matsuoka masahiro kanetake kiyoshi yanagawa hajime maki atsuo omotem teruhisa harita hiroshi tanaka michio denpo shiro tamaki 再见萤火虫 die letzten leuchtkäfer 再見螢火蟲 graf van de vuurvliegjes căn hầm đom đóm jaanimardikate haud jonvabalių kapas سيتا الحنون mormântul licuricilor могила светлячков una tomba per le lucciole ग्रेव ऑफ फिरेफ़्लिएस 火垂るの墓 túmulo dos vagalumes grave of the fireflies สุสานหิ่งห้อย o túmulo dos pirilampos grave of the fireflies ateşböceklerinin mezarı la tumba de las luciérnagas 반딧불의 묘 atəşböcəyinin məzarı hotaru no haka yonar qo‘ng‘izlar qabri o túmulo dos vagalumes', '');
