INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hang-xom-cua-toi-la-totoro', 'Hàng Xóm Của Tôi Là Totoro', 'My Neighbor Totoro', 'hàng xóm của tôi là totoro my neighbor totoro noriko hidaka chika sakamoto hitoshi takagi shigesato itoi sumi shimamoto tanie kitabayashi toshiyuki amagasa yuko maruyama masashi hirose reiko suzuki machiko washio naoki tatsuta tomohiro nishimura chie koujiro yuko mizutani shigeru chiba tonari no totoro magiska äventyr med totoro näkymätön ystävä totoro totoro auzokidea mon voisin totoro komşum totoro 龍貓 이웃집 토토로 my neighbour totoro min nabo totoro qonşum totoro 龙猫 η γειτονιά του δάσους: οι περιπέτειες του τοτόρο mening qo‘shnim totoro мой сосед тоторо meu amigo totoro となりのトトロ', '');
