INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hong-sung-vo-hinh', 'Họng Súng Vô Hình', 'The Naked Gun: From the Files of Police Squad!', 'họng súng vô hình the naked gun: from the files of police squad! leslie nielsen priscilla presley ricardo montalban george kennedy o. j. simpson susan beaubian nancy marchand raye birk jeannette charles ed williams tiny ron ''weird al'' yankovic leslie maier winifred freedman joe grifasi tony bra the naked gun police squad! mannen med den nakna pistolen bláznivá strela - z archívu policajného oddelenia голи пиштољ bláznivá střela: z archivů policejního oddělení la pistola sin funda çıplak silah: polis kayıtlarından! 총알 탄 사나이 la pistola desnuda mannen och det nakna vapnet the naked gun: from the files of police squad!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-thi-tien-sinh-4-cuong-thi-thuc-thuc', 'Cương Thi Tiên Sinh 4: Cương Thi Thúc Thúc', 'Mr Vampire Saga 4', 'https://phimimg.com/upload/vod/20250603-1/cec0098c24c34ae4813c9e888d1fe832.jpg', 'https://phimimg.com/upload/vod/20250603-1/1ca1415769d86c9c620960b0357e6546.jpg', '<p>Trong một khu rừng chỉ có hai ngôi nhà của lão Hòa Thượng và lão đạo sĩ Bốn Mắt. Dù là hàng xóm duy nhất của nhau, nhưng hai người không ưa nhau, thường xuyên cà khịa, chơi khăm lẫn nhau. Gia Lạc, đồ đệ của Bốn Mắt lại khá thân thiết với Hòa Thượng. Một hôm, Hòa Thượng dẫn về một nữ đồ đệ dữ dằn tên Tinh Tinh. Gia Lạc tưởng Tinh Tinh là con trai nên đã ôm cô trêu ghẹo. Tinh Tinh giận dữ, Hòa Thượng bèn giả vờ đánh Gia Lạc nhưng Tinh Tinh sớm nhận ra và dội nước cả hai người.</p>', 'Full', 1, 'single', 'completed', 21, 1988, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Wu Ma","avatar":""},{"name":"Loletta Lee Lai-Chun","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Anthony Chan Yau","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Pauline Wong Yuk-Wan","avatar":""},{"name":"Hoh Kin-Wai","avatar":""},{"name":"Chun Kwai-Bo","avatar":""},{"name":"Chu Tau","avatar":""},{"name":"Pang Yun-Cheung","avatar":""},{"name":"Paul Chung Fat","avatar":""},{"name":"Ka Lee","avatar":""},{"name":"Chow Gam-Kong","avatar":""},{"name":"Kwan Yung","avatar":""},{"name":"Cheung Wing-Cheung","avatar":""},{"name":"Lung Ying","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Mr. Vampire Saga Four","Mr. Vampire Saga IV","Mr. Vampire Saga","Jiang shi shu shu","Mr Vampire 4","僵尸先生4：僵尸叔叔","凶屋叔叔","美女僵尸","殭屍叔叔"]',