INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuong-thi-tien-sinh-4-cuong-thi-thuc-thuc', 'Cương Thi Tiên Sinh 4: Cương Thi Thúc Thúc', 'Mr Vampire Saga 4', 'cương thi tiên sinh 4: cương thi thúc thúc mr vampire saga 4 wu ma loletta lee lai-chun chin ka-lok anthony chan yau yuen wah pauline wong yuk-wan hoh kin-wai chun kwai-bo chu tau pang yun-cheung paul chung fat ka lee chow gam-kong kwan yung cheung wing-cheung lung ying mr. vampire saga four mr. vampire saga iv mr. vampire saga jiang shi shu shu mr vampire 4 僵尸先生4：僵尸叔叔 凶屋叔叔 美女僵尸 殭屍叔叔', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-tay-du-ki', 'Doraemon: Nobita Tây Du Kí', 'Doraemon: The Record of Nobita''s Parallel Journey to the West', 'https://phimimg.com/upload/vod/20250521-1/3423836fd86f286e66a0de35d52a14f6.jpg', 'https://phimimg.com/upload/vod/20250521-1/f5ab79db69a5015e0f58f86bb7f9aa6b.jpg', '<p>Nobita, Chaien, Shizuka và Suneo đang chuẩn bị cho vở kịch &quot;Tây Du Ký&quot; ở trường. Khi họ đang tranh cãi về việc ai sẽ đóng vai Tôn Ngộ Không , Nobita đã gợi ý rằng Tôn Ngộ Không thật nên đóng vai đó. Vì Tôn Ngộ Không chỉ là truyền thuyết nên Nobita và Doraemon đã quyết định quay ngược thời gian bằng cách sử dụng cỗ máy thời gian và giả làm Tôn Ngộ Không để chứng minh cho Gian, Shizuka và Suneo rằng mình đúng. Thật không may, cỗ máy của Doraemon đã cho phép những con quái vật hư cấu đến thế giới thực và đánh bại toàn bộ chủng tộc loài người, do đó biến tương lai (thời của Nobita) thành một thế giới bị quỷ thống trị. Để đảo ngược sự thay đổi, Doraemon và nhóm bạn cần phải trở về quá khứ và bắt những con quỷ trở lại . Trên đường đi, họ đã gặp nhà sư Tam Tạng thực sự và rinrei (một đứa trẻ đi cùng nhà sư). Cuối cùng, họ đã đưa những con quỷ trở lại máy và tiêu diệt chúng với sự giúp đỡ của Dorami, do đó biến tương lai trở lại bình thường.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 1988, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Kazuya Tatekabe","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Doraemon Nobita no Parareru saiyuki","The Record of Nobita''s Parallel \"Journey to the West\"","The Record of Nobita''s Parallel \"Visit to the West\"","哆啦A夢：大雄的平行西遊記","โดราเอมอน ตอน ตำนานเทพนิยายไซอิ๋ว","Doraemon The Record of Nobita''s Parallel Visit to the West","nobita tay du ki","doremon tay du ki","Doraemon: Nobita''s Version of Saiyuki","Doraemon: The Record of Nobita''s Parallel Visit to the West","Perjalanan Ke Barat","電影哆啦A夢：大雄西遊記","映画ドラえもん のび太のパラレル西遊記"]', 1784690324546);
