INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-mat-tich-dot-ngot', 'Vụ Mất Tích Đột Ngột', 'The Vanishing', 'https://phimimg.com/upload/vod/20250424-1/bd1d355b71519484cf5b8969dd2e7816.jpg', 'https://phimimg.com/upload/vod/20250424-1/884ec4fe3d10ad2eb619893fe45da0d9.jpg', '<p>Rex và Saskia, một cặp đôi trẻ đang yêu, đi nghỉ mát cùng nhau. Họ dừng lại tại một trạm dừng chân đông đúc thì Saskia bị bắt cóc. Sau ba năm không có bất kỳ dấu vết nào của Saskia, Rex bắt đầu nhận được những bức thư từ kẻ bắt cóc.</p>', 'Full', 1, 'single', 'completed', 36, 1988, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Bernard-Pierre Donnadieu","avatar":""},{"name":"Gene Bervoets","avatar":""},{"name":"Johanna ter Steege","avatar":""},{"name":"Gwen Eckhaus","avatar":""},{"name":"Pierre Forget","avatar":""},{"name":"Bernadette Le Saché","avatar":""},{"name":"Tania Latarjet","avatar":""},{"name":"Lucille Glenn","avatar":""},{"name":"Roger Souza","avatar":""},{"name":"Caroline Appéré","avatar":""},{"name":"Didier Rousset","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["The Vanishing - Spurlos verschwunden","The Vanishing","Исчезновение","L''Homme Qui Voulait Savoir","Spoorloos","ザ・バニシング-消失-","A Desaparecida","Zniknięcie"]', 1784690324546);
