INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-hoa-hong', 'Nhiệm Vụ Hoa Hồng', 'Mission Rose', 'https://phimimg.com/upload/vod/20250406-1/f0e379dd2f80e8ade828983e12910482.jpg', 'https://phimimg.com/upload/vod/20250406-1/1ccf97d950b7ef746375a1acc358c76b.jpg', '<p>&quot;Nhiệm Vụ Hoa Hồng&quot; là một bộ phim chiến tranh – tình báo đầy kịch tính, khai thác chủ đề về những chiến sĩ tình báo hoạt động bí mật trong lòng địch. Phim xoay quanh một nhóm điệp viên cách mạng được giao nhiệm vụ thâm nhập vào hàng ngũ của chính quyền Sài Gòn, thực hiện một nhiệm vụ quan trọng có tên mật mã &quot;Hoa Hồng&quot;. Họ phải đối mặt với những nguy hiểm chực chờ, những cuộc đấu trí căng thẳng, những cuộc truy đuổi nghẹt thở, và đặc biệt là những tình huống buộc họ phải hy sinh tình cảm cá nhân để bảo vệ bí mật quốc gia. Bộ phim không chỉ tái hiện cuộc chiến đấu âm thầm nhưng vô cùng nguy hiểm của các điệp viên cách mạng, mà còn khắc họa tâm lý phức tạp, sự giằng xé nội tâm giữa lòng trung thành với tổ quốc và những cảm xúc rất con người.</p>', 'Full', 1, 'single', 'completed', 18, 1988, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mai Phương","avatar":""},{"name":"Hồng Chi","avatar":""},{"name":"Lý Huỳnh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324546);
