INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-binh-thien-quoc-1988', 'Thái Bình Thiên Quốc', 'Twilight of a Nation', 'https://phimimg.com/upload/vod/20250318-1/efdef23d9288b22084b5a445bb137072.jpg', 'https://phimimg.com/upload/vod/20250318-1/b73a1897b95d18824bb1c0b8da2c0b53.jpg', '<p>Thái Bình Thiên Quốc xoay quanh câu chuyện về Hồng Tú Toàn, là một người đàn ông luôn có lòng tin rằng bản thân đã được vị thượng đế ban tặng danh dự để thành lập một hội Thượng Đế. Thế nhưng lúc bấy giờ triều đại nhà Thanh ngày càng trở nên thối nát, người vợ của Toàn bị quân nhà thanh sát hại, do đó anh quyết định thành lập ra một Thái Bình Thiên Quốc là một khu vực độc lập và tuyển binh để bắt đầu một cuộc chiến khởi nghĩa.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 17, 1988, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ray Lui","avatar":""},{"name":"Barbara Chan","avatar":""},{"name":"Jimmy Au Shui-Wai","avatar":""},{"name":"Felix Wong Yat-Wah","avatar":""},{"name":"Carrie Choi","avatar":""},{"name":"Teresa Mo Shun-Kwan","avatar":""},{"name":"Sean Lau Ching-Wan","avatar":""},{"name":"Sheren Tang Shui-Man","avatar":""},{"name":"Joseph Lee Kwok-Lun","avatar":""},{"name":"Chan Wing-Chun","avatar":""},{"name":"Newton Lai Hon-Chi","avatar":""},{"name":"Aaron Kwok Fu-Shing","avatar":""},{"name":"Lee Yiu-King","avatar":""},{"name":"Kiki Sheung","avatar":""},{"name":"Yung Wai-Man","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["太平天国","太平天國","Twilight of a Nation"]', 1784690324546);
