INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-mon', 'Danh Môn', 'Withered in the Wind', 'https://phimimg.com/upload/vod/20250318-1/96ee0a7ea3c32505b4b724d25ca975fb.jpg', 'https://phimimg.com/upload/vod/20250318-1/2a04e4ffa103f2996824a22b4c2c1ac3.jpg', '<p>Lấy bối cảnh nhưng năm 1930, khi cách mạng Trung Quốc nổ ra, Danh Môn xoay quanh cuộc sống của gia đình Quân phiệt Đoạn Hổ. Từ đó, cho thấy những mâu thuẫn của thời đại phong kiến, xung đột giữa dân tộc, tình yêu và tư tưởng bảo thủ…. Đoạn Ngọc Đình là con trai của Nhà Quân phiệt Đoạn Hổ, lớn lên trong gia đình phong kiến truyền thống khiến Đình không vượt qua được rào cản gia đình để tiếp tục tình yêu với cô gái xuất thân lầu xanh.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 17, 1988, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Eddie Cheung Siu-Fai","avatar":""},{"name":"Wilson Lam Jun-Yin","avatar":""},{"name":"Tse Ning","avatar":""},{"name":"Kitty Lai Mei-Han","avatar":""},{"name":"Elliot Ngok Wah","avatar":""},{"name":"Wan-Choi Wong","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Dicky Cheung Wai-Kin","avatar":""},{"name":"Teresa Mo Shun-Kwan","avatar":""},{"name":"Money Lo Man-Yee","avatar":""},{"name":"Chim Bing-Hei","avatar":""},{"name":"Nam Hung","avatar":""},{"name":"Pak Yan","avatar":""},{"name":"Amy Wu Mei-Yee","avatar":""},{"name":"So Hang-Suen","avatar":""},{"name":"Liu Kai-Chi","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Withered in the Wind","名門"]', 1784690324546);
