INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-lam-truyen-ky', 'Võ Lâm Truyền Kỳ', 'The Saga of The Lost Kingdom', 'https://phimimg.com/upload/vod/20241207-1/894089669a01682705cedcf62def5565.jpg', 'https://phimimg.com/upload/vod/20241207-1/4f20e195888ad576f693f1eddb62933f.jpg', '<p>Dinh Đang là một thái tử của dòng tộc Tần Thủy Hoàng sống trong một hòn đảo mà giang hồ gọi là Mao Khê. Tuy là thái tử nhưng Dinh Đang không được thông minh lắm và luôn là đề tài chế diễu của các cô gái trên đảo. Trong một dịp tình cờ Quá Đào Tường lọt vào đảo và được Dinh Đang cứu thoát, nhưng cũng vì vậy mà Dinh Đang phải lang thang trên giang hồ vì không biết đường trở lại Mao Khê. Trải qua những khó khăn, cuối cùng Dinh Đang gặp và yêu Hồ Điệp Phu Nhân, một thiếu nữ trẻ đứng đầu một giáo phái luôn bị giang hồ cho là tà phái...</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 21, 1988, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Roger Kwok","avatar":""},{"name":"Margie Tsang Wah-Sin","avatar":""},{"name":"Kathy Chow","avatar":""},{"name":"Eddie Cheung Siu-Fai","avatar":""},{"name":"Hugo Ng Doi-Yung","avatar":""},{"name":"Dicky Cheung Wai-Kin","avatar":""},{"name":"Mimi Kung","avatar":""},{"name":"Jacqueline Law","avatar":""},{"name":"May Hoh","avatar":""},{"name":"Chun Wong","avatar":""},{"name":"Pak Yan","avatar":""},{"name":"Ga-Bo Tsui","avatar":""},{"name":"Ronna Ko","avatar":""},{"name":"Eddy Ko Hung","avatar":""},{"name":"Wong San","avatar":""},{"name":"Seung-Goon Yuk","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["龙侠传奇 / The Saga of the Lost Kingdom","贏單傳奇"]', 1784690324546);
