INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-tu-dien-ki-bi', 'Cuốn Từ Điển Kì Bí', 'Kiteretsu Daihyakka', 'https://phimimg.com/upload/vod/20240923-1/5a424e37a30eee7a4d83daec9255cf21.jpg', 'https://phimimg.com/upload/vod/20240923-1/68b499ae6f1e88f8c348595d86d452d3.jpg', '<p>Nhân vật chính là cậu bé thiên tài khoa học tên Kiteretsu, người đã chế tạo ra một người máy đồng hành tên là Korosuke. Anh ấy thường xuyên du hành xuyên thời gian cùng bạn bè và Korosuke trên cỗ máy thời gian do anh ấy chế tạo. Miyoko là một cô gái hàng xóm và về cơ bản là bạn gái của anh ấy. Tongari là đối thủ của anh ấy, người tình cờ có một số đặc điểm giống Honekawa Suneo. Buta Gorilla là một kẻ bắt nạt hàng xóm điển hình, người cũng có những đặc điểm giống Gian ngoại trừ việc anh ta thường chống đối Korosuke (mặc dù họ đang học tiểu học).</p>', 'Hoàn Tất (331/331)', 331, 'hoathinh', 'completed', 14, 1988, 'Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"小山茉美","avatar":""},{"name":"本多知恵子","avatar":""},{"name":"龍田直樹","avatar":""},{"name":"藤田淑子","avatar":""},{"name":"三ツ矢雄二","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["奇天烈百科全书","Kiteretsu, el primo mas listo de Nobita","키테레츠 대백과","المخترع الصغير","คิเตเร็ทสึ เจ้าหนูนักประดิษฐ์","キテレツ大百科"]', 1784690324546);
