INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuon-tu-dien-ki-bi', 'Cuốn Từ Điển Kì Bí', 'Kiteretsu Daihyakka', 'cuốn từ điển kì bí kiteretsu daihyakka 小山茉美 本多知恵子 龍田直樹 藤田淑子 三ツ矢雄二 奇天烈百科全书 kiteretsu, el primo mas listo de nobita 키테레츠 대백과 المخترع الصغير คิเตเร็ทสึ เจ้าหนูนักประดิษฐ์ キテレツ大百科', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-giang-sinh-dang-nho', 'Đêm Giáng Sinh Đáng Nhớ', 'Scrooged', 'https://phimimg.com/upload/vod/20240713-1/ea95c9d6f427c1c1475355c259923b67.jpg', 'https://phimimg.com/upload/vod/20240713-1/bc433fde968fadf357375f188fe91a37.jpg', '<p>Frank Cross là một giám đốc điều hành truyền hình cực kỳ thành công nhưng tham vọng lạnh lùng và bản tính nghiêm khắc đã khiến tình yêu của đời anh mất đi. Nhưng sau khi sa thải một nhân viên vào đêm Giáng sinh, Frank bị hàng loạt hồn ma đến thăm, những người cho anh cơ hội đánh giá lại hành động của mình và sửa chữa những sai lầm trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 12, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Murray","avatar":""},{"name":"Karen Allen","avatar":""},{"name":"John Forsythe","avatar":""},{"name":"John Glover","avatar":""},{"name":"Bobcat Goldthwait","avatar":""},{"name":"David Johansen","avatar":""},{"name":"Carol Kane","avatar":""},{"name":"Robert Mitchum","avatar":""},{"name":"Nicholas Phillips","avatar":""},{"name":"Michael J. Pollard","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324546);
