INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-giang-sinh-dang-nho', 'Đêm Giáng Sinh Đáng Nhớ', 'Scrooged', 'đêm giáng sinh đáng nhớ scrooged bill murray karen allen john forsythe john glover bobcat goldthwait david johansen carol kane robert mitchum nicholas phillips michael j. pollard ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thanh-gian-du', 'Âm Thanh Giận Dữ', 'Sound and Fury', 'https://phimimg.com/upload/vod/20231108-1/dac32a7b63f02f2acff6241c1b68f4b9.jpg', 'https://phimimg.com/upload/vod/20231108-1/89bc795b2ed8f81220e5bfd958af81da.jpg', '<p>Bộ phim này mô tả sự khốn khổ của những đứa trẻ bị bỏ rơi ở các thành phố lớn. 13 tuổi, Bruno xuất thân từ một gia đình nề nếp, nhưng kể từ khi bà ngoại qua đời, cậu dành phần lớn thời gian ở một mình, trong thế giới ảo mộng, trong khi mẹ cậu đi làm xa. Nhưng sau đó, anh kết bạn với Jean-Roger bạo lực, xuất thân từ một gia đình bị xáo trộn nghiêm trọng, nơi không ai quan tâm đến những gì anh ta đang làm. Ở trường, Jean-Roger khiến giáo viên của họ rơi vào tuyệt vọng chỉ để mua vui. Để tách hai cậu bé ra, cô bắt đầu kích thích sở thích của Bruno bằng cách cho cậu học thêm. Khi Jean-Roger lo sợ mất đi người bạn duy nhất của mình, anh ta càng trở nên hung hăng hơn.</p>', 'Full', 1, 'single', 'completed', 11, 1988, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Bruno Cremer","avatar":""},{"name":"François Négret","avatar":""},{"name":"Vincent Gasperitsch","avatar":""},{"name":"Fabienne Babe","avatar":""},{"name":"María Luisa García","avatar":""},{"name":"Fejria Deliba","avatar":""},{"name":"Thierry Helene","avatar":""},{"name":"Sandrine Arnault","avatar":""},{"name":"Victoire Buff","avatar":""},{"name":"Françoise Vatel","avatar":""},{"name":"Albert Montias","avatar":""},{"name":"Lucien Plazanet","avatar":""},{"name":"Aurélie Sterling","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324546);
