INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('frantic', 'Frantic', 'Frantic', 'https://phimimg.com/upload/vod/20240827-1/f62ca16c6f96ee866e67c5db5df7ca01.jpg', 'https://phimimg.com/upload/vod/20240827-1/4e991acd459a853049dfe6904679b5b4.jpg', '<p>Trong một phòng khách sạn ở Paris, một bác sĩ vừa bước ra khỏi phòng tắm thì phát hiện vợ mình đã biến mất. Anh sớm nhận ra mình đã bị cuốn vào một thế giới đầy mưu mô, gián điệp, xã hội đen, ma túy và giết người</p>', 'Full', 1, 'single', 'completed', 11, 1988, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Emmanuelle Seigner","avatar":""},{"name":"Betty Buckley","avatar":""},{"name":"Dominique Pinon","avatar":""},{"name":"Jacques Ciron","avatar":""},{"name":"John Mahoney","avatar":""},{"name":"Jimmie Ray Weeks","avatar":""},{"name":"David Huddleston","avatar":""},{"name":"Alexandra Stewart","avatar":""},{"name":"Yorgo Voyagis","avatar":""},{"name":"Djiby Soumare","avatar":""},{"name":"Roch Leibovici","avatar":""},{"name":"Dominique Virton","avatar":""},{"name":"Gérard Klein","avatar":""},{"name":"Stéphane D''Audeville","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324546);
