INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('frantic', 'Frantic', 'Frantic', 'frantic frantic harrison ford emmanuelle seigner betty buckley dominique pinon jacques ciron john mahoney jimmie ray weeks david huddleston alexandra stewart yorgo voyagis djiby soumare roch leibovici dominique virton gérard klein stéphane d''audeville ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-quy-bat-ma', 'Chung Quỳ Bắt Ma', 'The Chinese Ghost Buster', 'https://phimimg.com/upload/vod/20240616-1/07ba0194ae25e909ef10582eab91906c.jpg', 'https://phimimg.com/upload/vod/20240616-1/da2a275a396fddac07bd08bf0b4e095e.jpg', '<p><em>Zhong Kui (Luo Lelin), một học giả từ Trung Nam vào thời nhà Đường, đến Bắc Kinh để dự thi, vị hoàng đế này không được đưa vào danh sách vì ngoại hình xấu xí. Thiên hoàng đã phong anh ta là Vị thần thiêng liêng của Diệt quỷ và Diệt trừ yêu ma. kết hôn với Ping. Trong dân gian có năm con ma đang loạn lạc, Kui làm phép để điều phục năm con ma, và đặt tên nó là ma vương. Shi Du gặp hai ma nữ là Ziyun và Zihua và đặc biệt say mê Zihua, hai người nảy sinh tình yêu. Không may, sự việc bị ba hoa chủ phát hiện ra và họ đã gây sức ép với hoa, và Hoa cuối cùng không còn sự lựa chọn nào khác, trong trường hợp này, anh đã quyết định cắt cổ bản thân để chấm dứt tình cảm đau buồn này, điều này đã gián tiếp khiến Zhong và Samo bắt đầu một chuỗi trận chiến khốc liệt. Đồng thời, trước danh tiếng trừ quỷ của Zhong, Tu Qin, một pháp sư khác, đã ghen tị và thách thức Zhong liên tục. Cặp đôi Zhang trông bình thường hóa ra lại là hồn ma cướp đoạt linh hồn của quỷ giới Qizhen, sau này quay lưng lại với tà ác, muốn đạt được kết quả khả quan, sự việc bị ba con quỷ phát hiện. , người dụ bọn họ phạm giới. Có hại cho dân chúng, Zhong Kui đối mặt với kẻ thù hai bên gặp nguy hiểm, dù sao thì cái ác cũng không thể thắng, cuối cùng Zhong có thể trừ khử ba quỷ và hai quỷ, hoàn thành đại sự. nhiệm vụ từ trên trời giáng xuống, và trở thành một vị thần diệt ma nổi tiếng trong lịch sử.</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 25, 1988, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"La Lạc Lâm","avatar":""},{"name":"Thái Thiện Nghi","avatar":""},{"name":"Lý Văn Bưu","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324546);
