INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-tay-cao-boi', 'Những Tay Cao Bồi', 'Young Guns', 'https://phimimg.com/upload/vod/20240616-1/4c2993fc83becadf35519c96c1b7a542.jpg', 'https://phimimg.com/upload/vod/20240616-1/59b367e430ad16bc232314a8ceb6dc1b.jpg', '<p>Một bộ phim nói về các tay súng cowboy của Mỹ. Trong phần 1 (sx năm 1988) đều nói về những ngày tháng của Billy The Kid và đồng đội như thực hiện các vụ ám sát với phong cách ngổ ngáo lì lơm của Billy The Kid. Phần 2 (1990) nói vềnhững ngày tháng bị săn lùng và kết thúc cuộc đời do sự phản bội của Pat Garrett, một tay súng mà Billy làm quen trong giang hồ. Tuy nhiên bộ phim còn để cửa ngõ cho sự tranh luận rằng liệu tay súng Pat Garrett có thực sự giết chết Billy The Kid hay chưa? Hay là Billy The Kid vẫn sống cho đến kết thúc cuộc đời vào năm 1950?</p>', 'Full', 1, 'single', 'completed', 10, 1988, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emilio Estevez","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Lou Diamond Phillips","avatar":""},{"name":"Charlie Sheen","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Casey Siemaszko","avatar":""},{"name":"Terence Stamp","avatar":""},{"name":"Jack Palance","avatar":""},{"name":"Terry O''Quinn","avatar":""},{"name":"Sharon Thomas Cain","avatar":""},{"name":"Geoffrey Blake","avatar":""},{"name":"Alice Carter","avatar":""},{"name":"Brian Keith","avatar":""},{"name":"Thomas Callaway","avatar":""},{"name":"Patrick Wayne","avatar":""},{"name":"Lisa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324546);
