INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('big', 'Big', 'Big', 'https://phimimg.com/upload/vod/20240227-1/f5ee23e1c1b502096d5fe0f04f97b039.jpg', 'https://phimimg.com/upload/vod/20240227-1/6d2c5a4d3b63f2d897f68b344e3df69a.jpg', '<p>Khi một cậu bé thực hiện một điều ước lớn lao tại một cỗ máy lễ hội—cậu bé thức dậy vào sáng hôm sau và thấy rằng điều đó đã được thực hiện và cơ thể cậu đã già đi chỉ sau một đêm. Nhưng bên trong anh vẫn là cậu bé 13 tuổi. Bây giờ anh ấy phải học cách đương đầu với thế giới xa lạ của những người trưởng thành, bao gồm cả việc kiếm việc làm và có cuộc gặp gỡ lãng mạn đầu tiên với một người phụ nữ.</p>', 'Full', 1, 'single', 'completed', 14, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Elizabeth Perkins","avatar":""},{"name":"Robert Loggia","avatar":""},{"name":"John Heard","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324546);
