INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-co-hang-xom', 'Chuyện Cô Hàng Xóm', 'A Short Film About Love', 'https://phimimg.com/upload/vod/20240227-1/3e06fdfa8df9ad0bb86071c3dcfdabec.jpg', 'https://phimimg.com/upload/vod/20240227-1/9663fccd451a61bb88fd485fd8484a8b.jpg', '<p>Tomek, 19 tuổi, thoát khỏi cuộc sống cô đơn của mình bằng cách theo dõi người hàng xóm Magda đối diện qua ống nhòm. Cô ấy là một nghệ sĩ ở độ tuổi ngoài ba mươi, và dường như có mọi thứ - đặc biệt là một dòng đàn ông liên tục vẫy gọi và gọi cho cô ấy. Nhưng khi cả hai cuối cùng gặp nhau, họ phát hiện ra rằng họ có nhiều điểm chung hơn là xuất hiện từ cái nhìn đầu tiên ...</p>', 'Full', 1, 'single', 'completed', 17, 1988, 'Vietsub', 'HD', 'Ba Lan', 0, '[{"name":"Grażyna Szapołowska","avatar":""},{"name":"Olaf Lubaszenko","avatar":""},{"name":"Stefania Iwińska","avatar":""},{"name":"Piotr Machalica","avatar":""},{"name":"Artur Barciś","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324546);
