INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-quay-pha-3', 'Ma Quậy Phá 3', 'Poltergeist III', 'https://phimimg.com/upload/vod/20240220-1/45c978e0c6c07af35ba789195e003537.jpg', 'https://phimimg.com/upload/vod/20240220-1/71f10f8f2b47ffdf8d541718d75c76fa.jpg', '<p>Carol Anne đã được gửi đến sống với dì và chú của cô ấy trong nỗ lực che giấu cô ấy khỏi nanh vuốt của Mục sư Kane ma quái, nhưng anh ta đã theo dõi cô ấy và khủng bố cô ấy trong căn hộ của người thân cô ấy trong một tòa nhà kính cao. Liệu cuối cùng anh ta có đạt được mục tiêu của mình và bắt được Carol Anne một lần nữa hay Tangina sẽ có thể ngăn cản anh ta một lần nữa?</p>', 'Full', 1, 'single', 'completed', 12, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Skerritt","avatar":""},{"name":"Nancy Allen","avatar":""},{"name":"Heather O''Rourke","avatar":""},{"name":"Lara Flynn Boyle","avatar":""},{"name":"Kipley Wentz","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324546);
