INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-mau-thuong-dang', 'Dòng Máu Thượng Đẳng', 'Bloodsport', 'https://phimimg.com/upload/vod/20240207-1/ac97084f7b5cbbd17838329946bea5e7.jpg', 'https://phimimg.com/upload/vod/20240207-1/8e86b73f1490d4bbab78cdfe2c67196d.jpg', '<p>Phim dựa trên câu chuyện có thật về huyền thoại võ thuật Frank Dux. Trong vai 1 quân nhân tham gia 1 giải đấu võ ngầm ở Hồng Kông nhằm thực hiện nguyện vọng của người bạn đã khuất, cũng là con trai của sư phụ anh...</p>', 'Full', 1, 'single', 'completed', 19, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Donald Gibb","avatar":""},{"name":"Leah Ayres","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324546);
