INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-sung', 'Tay Súng', 'Gunmen', 'null', 'https://phimimg.com/upload/vod/20240207-1/4b485b2c1d1a53e68bfdd753e20e0efe.jpg', '<p>Khi Nội chiến Trung Quốc nổ ra, Ting Kwan-pik và các đồng đội của anh ta là Cheung Cho-fan, Lau Fuk-kwong, và đội trưởng Zeng Chaozheng bị bắt bởi người của lãnh chúa Duẩn Qirui. Trong lúc hỗn loạn, Lau cầm theo một quả lựu đạn, và họ đã trốn thoát được. Sau chiến tranh, Ting trở về nhà với vợ là Cho Chiu và con gái Sze-sze. Một năm sau, Ting trở thành cảnh sát. Trong một cuộc truy quét ma túy, Ting đã giết chú của Haye. Trong đám tang, tay sai của Haye rất tức giận và thề sẽ trả thù cho chú của Haye bằng cách giết Ting. Khi một cuộc đấu súng nghiêm trọng nổ ra, các cảnh sát đồng nghiệp của Ting đến để giúp đỡ. Cuộc chiến cướp đi sinh mạng của cả hai bên.</p>', 'Full', 1, 'single', 'completed', 11, 1988, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tony Ka Fai Leung","avatar":""},{"name":"Adam Cheng","avatar":""},{"name":"Lee Mei-Fung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324546);
