INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-vien-ngoc-rong-cuoc-phieu-luu-huyen-bi', 'Bảy Viên Ngọc Rồng: Cuộc Phiêu Lưu Huyền Bí', 'Dragon Ball: Mystical Adventure', 'https://phimimg.com/upload/vod/20240205-1/11134b3467f4afb326427c4add11976a.jpg', 'https://phimimg.com/upload/vod/20240205-1/2ef5b20b1d4bb5260b8937f3b55f1c63.jpg', '<p>Vợ của Hoàng đế Chiaotzu bị mất tích. Sư phụ Shen nói với ông ta rằng nếu thu thập đủ 7 viên Ngọc Rồng thì có thể triệu tập Rồng Thần để biến một điều ước thành thật.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 1988, 'Vietsub', 'HD', 'Nhật Bản', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324546);
