INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bay-vien-ngoc-rong-cuoc-phieu-luu-huyen-bi', 'Bảy Viên Ngọc Rồng: Cuộc Phiêu Lưu Huyền Bí', 'Dragon Ball: Mystical Adventure', 'bảy viên ngọc rồng: cuộc phiêu lưu huyền bí dragon ball: mystical adventure  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-trong-mua', 'Người Đàn Ông Trong Mưa', 'Rain Man', 'https://phimimg.com/upload/vod/20240128-1/1d18d353af907d4690b8b3458de95658.jpg', 'https://phimimg.com/upload/vod/20240128-1/0bb27beb5176d2d9b45092d0ac69ff3e.jpg', '<p>Charles Sanford Charlie kim loại trắng dùng trong máy là tự làm trung tâm Los Angeles dựa trên ô tô đại lý / hustler / mê đọc sách người đang có chiến tranh với cuộc sống riêng của mình. Charlie, là một thiếu niên trẻ, sử dụng 1949 Buick của cha mình mui trần mà không được phép và kết quả là, ông đã đi vào tù trong hai ngày trên tài khoản đó cha mình báo cáo nó bị đánh cắp. Đó là sau đó Charlie biết rằng cha ghẻ lạnh của ông qua đời và để lại cho anh từ ý chí cuối cùng của mình và ước một chiếc giường lớn hoa hồng và chiếc xe trong khi phần còn lại sẽ của $ 3 Triệu đi vào một quỹ ủy thác để được phân phối cho một ai đó. Charlie có vẻ khá tức giận của thành viên này và quyết định xem xét vấn đề này. Dường như nếu đó ai đó là Raymond, anh chưa biết Charlie, một bác học mắc chứng tự kỷ đang sống trong một thế giới của riêng mình, cư trú tại Viện Walbrook. Charlie sau đó bắt cóc Raymond và quyết định đưa anh ta vào một ham muốn cho chuyến đi của cuộc sống đến bờ biển phía tây như một mối đe dọa để có được thừa kế $ 3 triệu. hành vi và cằn nhằn Raymond, trong đó có các cuộc đàm phán lặp đi lặp lại của Abbott &amp; Costello, Bốn phút đến Wapner và từ chối để bay vào một hãng hàng không Qantas trừ ổ đĩa Charlie điên ... và ra khỏi thế giới ích kỷ của mình vào một chuyến đi xuyên quốc gia của tinh khiết tình yêu và sự hiểu biết rằng hai cả hai đều có.</p>', 'Full', 1, 'single', 'completed', 10, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324546);
