INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-duong-xanh', 'Đại Dương Xanh', 'The Big Blue', 'https://phimimg.com/upload/vod/20240124-1/b0d6d11548cb94f3f0196c46af051e76.jpg', 'https://phimimg.com/upload/vod/20240124-1/9125c3e43e84bf455acca697df849e77.jpg', '<p>Hai người đàn ông đáp lại tiếng gọi của đại dương trong cuộc phiêu lưu giả tưởng lãng mạn này. Jacques và Enzo là một đôi bạn thân từ thuở nhỏ và có chung niềm đam mê với môn thể thao nguy hiểm là lặn tự do. Thợ lặn chuyên nghiệp Jacques đã chọn đi theo bước chân của cha mình, người đã chết trên biển khi Jacques còn là một cậu bé; trước sự bối rối của các nhà khoa học, Jacques có một khả năng đáng chú ý là điều chỉnh nhịp tim và kiểu thở của mình trong nước, do đó các dấu hiệu sinh tồn của anh ấy gần giống với dấu hiệu của cá heo hơn là của nam giới. Khi Enzo thuyết phục Jacques miễn cưỡng cạnh tranh với anh ta trong một cuộc thi lặn tự do -- xác định xem ai có thể lặn sâu hơn và lâu hơn mà không cần thiết bị lặn -- Jacques gặp Johana, một nhà điều tra bảo hiểm xinh đẹp đến từ Mỹ, và anh ấy thấy rằng mình phải lựa chọn giữa tình yêu của mình cho tình yêu biển cả của cô và anh.</p>', 'Full', 1, 'single', 'completed', 16, 1988, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean-Marc Barr","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Rosanna Arquette","avatar":""},{"name":"Paul Shenar","avatar":""},{"name":"Sergio Castellitto","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324546);
