INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-diary-of-a-big-man', 'The Diary of a Big Man', 'Daai Jeung Foo Yat Gei', 'https://phimimg.com/upload/vod/20240104-1/bb902e6c9b274cf6b0af5c167a013087.jpg', 'https://phimimg.com/upload/vod/20240104-1/7d3a74e746acdda6a6b1dec184ccad25.jpg', '<p>Một người hai vợ một chồng nhận thấy mình đang bày ra hết kế hoạch này đến kế hoạch khác với người bạn thân nhất của mình, Chí Hùng, để ngăn cản một trong hai người vợ của anh ta phát hiện ra việc hai vợ chồng của anh ta. Sự can thiệp ngoài ý muốn của một sĩ quan cảnh sát cũng như hàng loạt sự việc đáng tiếc dẫn đến việc người vợ phát hiện ra toàn bộ âm mưu. Họ hợp tác với vị hôn thê đang bực tức của Chí Hùng, Ka Lai, để trả thù chính xác hai người đàn ông.</p>', 'Full', 1, 'single', 'completed', 11, 1988, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-Fat","avatar":""},{"name":"Sally Yeh","avatar":""},{"name":"Joey Wang","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324546);
