INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-tan-gai-biet-doi-san-tinh', 'Kế Hoạch Tán Gái (Biệt Đội Săn Tình)', 'How To Pick Girls Up!', 'https://phimimg.com/upload/vod/20240128-1/ed16283fa71d788d2573972bd3f5b117.jpg', 'https://phimimg.com/upload/vod/20240128-1/6c9b93b13098b35aaed144d36894c603.jpg', '<p>Phim kể về ba người đàn ông thất tình, vô vọng theo đuổi cô gái trong mộng. Cuộc đời họ thay đổi hoàn toàn sau cuộc gặp gỡ với chuyên gia ái tình Đàm Dục Luân khi cả ba có ý định nhảy lầu tự tử.</p>', 'Full', 1, 'single', 'completed', 15, 1988, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Trương Mạn Ngọc","avatar":""},{"name":"Trần Nhã Luân","avatar":""},{"name":"Khâu Thục Trinh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324546);
