INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-tien-su', 'Vùng Đất Tiền Sử', 'The Land Before Time', 'https://phimimg.com/upload/vod/20231227-1/e38c29088612d5daec6dcef435e7caea.jpg', 'https://phimimg.com/upload/vod/20231227-1/9f5df1a5b4c6291f340ddacc549fe3fb.jpg', '<p>Littlefoot là một chú khủng long cổ dài tinh nghịch. Cuộc sống đột nhiên đổi thay khi núi lửa phun trào, cỏ cây khô héo, khí hậu khắc nghiệt, nước cạn khô dần. Để tồn tại, chú cùng mẹ và ông bà phải di cư tới “miền đất hứa. Đó là Great Valley – Thung lũng kỳ diệu nơi nước và thức ăn luôn sẵn có, cũng là nơi chúng có thể sống và lớn lên trong bình yên. Nhưng để đến được đó, năm người bạn phải trải qua rất nhiều khó khăn. Liệu họ có đến được miền đất hứa của mình không?</p>', 'Full', 1, 'single', 'completed', 14, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Pat Hingle","avatar":""},{"name":"Gabriel Damon","avatar":""},{"name":"Judith Barsi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324546);
