INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-phi-lam-mon', 'Song Phì Lâm Môn', 'Double Fattiness', 'https://phimimg.com/upload/vod/20231215-1/6a156cf128317d74245db3ab0cd185c1.jpg', 'https://phimimg.com/upload/vod/20231215-1/cbc648a5717f648be98a2e8976790a4d.jpg', '<p>Sau khi qua đời vì bệnh tim, một phụ nữ là chủ gia đình kiêm chủ tiệm bánh mì dẹt trở lại thế giới của người sống trong cơ thể của một phụ nữ trẻ tuổi hơn.</p>', 'Full', 1, 'single', 'completed', 11, 1988, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Đổng Phiếu","avatar":""},{"name":"Lydia Shum","avatar":""},{"name":"Tăng Chí Vỹ","avatar":""},{"name":"Trương Mạn Ngọc","avatar":""},{"name":"Trần Quốc Tân","avatar":""},{"name":"Tần Bái","avatar":""},{"name":"Khương Đại Vệ","avatar":""},{"name":"Hoàng Bân","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324546);
