INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-canh-sat-5', 'Học Viện Cảnh Sát 5', 'Police Academy 5: Assignment: Miami Beach', 'https://phimimg.com/upload/vod/20231211-1/0baeb4e9061bb475bd0b17118659c235.jpg', 'https://phimimg.com/upload/vod/20231211-1/a271f80c45f7cbe03d6e61aa5ce09612.jpg', '<p>Thật vậy, dường như một số người không bao giờ học hỏi, và sau sự thất bại gần đây của đội trưởng Harris Harris trong Học viện Cảnh sát 4: Công dân tuần tra (1987), một lần nữa, nhân viên lén lút muốn tiếp quản công việc của Aging Lassard, và bước vào đôi giày của anh ấy. Lần này, cơ hội hoàn hảo phát sinh trong hình dạng của Cán bộ cảnh sát uy tín của thập kỷ trong Bãi biển Sunny Miami, để tưởng nhớ sự cống hiến của Lassard cho lực lượng; Tuy nhiên, một cuộc gặp gỡ định mệnh với bộ ba những tên trộm kim cương táo bạo dẫn đến một cuộc rượt đuổi nguy hiểm, tốc độ cao trên khắp everglades. Bây giờ, tùy thuộc vào cháu trai của Lassard, Trung sĩ Nick Lassard và sinh viên tốt nghiệp trung thành của Học viện để cứu ngày. Các chàng trai có thể cản trở kế hoạch của Harris không?</p>', 'Full', 1, 'single', 'completed', 14, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324546);
