INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-chon-toi-ac', 'Mồ Chôn Tội Ác', 'Dirty Harry 5: The Dead Pool', 'https://phimimg.com/upload/vod/20231211-1/74a93e542e54c6f846312a68304fe9a8.jpg', 'https://phimimg.com/upload/vod/20231211-1/fee5f9bc802218e220fee57dbd844d0c.jpg', '<p>Vào năm 1971, San Francisco đối mặt với nỗi kinh hoàng gây ra bởi một kẻ điên rồ được biết đến với cái tên Scorpio. Hắn luôn tấn công những nạn nhân vô tội và đòi tiền chuộc bằng cách bỏ lại giấy nhắn tại hiện trường tội ác. Thanh tra viên Harry Callahan được bổ nhiệm điều tra vụ này cùng cộng sự mới Chico Gonzalez. Nhiệm vụ của hai thanh tra là theo sát Scorpio để ngăn cản hắn ta. Tuy nhiên, Scorpio đã dùng những chiêu trò đốn mạt chống lại Callahan và thách thức vị cảnh sát này bằng thái độ bẩn thỉu.</p>', 'Full', 1, 'single', 'completed', 12, 1988, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Clint Eastwood","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Patricia Clarkson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324546);
