INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-quan-he-nguy-hiem-1988', 'Mối Quan Hệ Nguy Hiểm', 'Dangerous Liaisons', 'https://phimimg.com/upload/vod/20231211-1/239c8099a9e776dc7b128a645bd1d260.jpg', 'https://phimimg.com/upload/vod/20231211-1/8ec4a1e80a209e49fde7cb323df8d275.jpg', '<p>Quan Hệ Nguy Hiểm - Dangerous Liaisons là một bộ phim truyền hình lịch sử 1988 của đạo diễn Stephen Frears dựa trên vở kịch Les Liaisons dangereuses của Christopher Hampton. The Marquise de Merteuil (Glenn Close) và Vicomte de Valmont (John Malkovich) luôn nghen tuôn một cách nhỏ mọn và vô tâm với cuộc sống mệt mỏi tại tòa án Hoàng Gia Pháp vào thế kỉ 18 vô tình làm hỏng cuộc sống lãng mạn của de Merteuil (Uma Thurman). Những trò chơi tình ái, những thách thức giữa những con người có cảm xúc mãnh liệt bắt đầu tiến xa hơn và hướng tới những bi kịch nguy hiểm hơn...</p>', 'Full', 1, 'single', 'completed', 13, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Glenn Close","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Michelle Pfeiffer","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324546);
