INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moonwalker', 'Moonwalker', 'Moonwalker', 'https://phimimg.com/upload/vod/20231210-1/1be9e51fa96abc74c02714c40e659e51.jpg', 'https://phimimg.com/upload/vod/20231210-1/24df0ded4533bc0ba74044905c2e7e79.jpg', '<p>Một bộ phim bắt đầu với video ca nhạc Man in the Mirror, sau đó chuyển sang phần dựng phim bằng các video clip về sự nghiệp của Michael. Tiếp theo là một video nhại lại video Bad của anh ấy bởi trẻ em, và sau đó Michael bị người hâm mộ truy đuổi trong một cảnh giả tưởng. 2 video khác được chiếu, và sau đó là một bộ phim trong đó Michael đóng vai một anh hùng có sức mạnh ma thuật. Trong đó, anh ta bị truy đuổi bởi trùm buôn ma túy Mr. Big và cứu được ba đứa trẻ. Các video có trong phim là Smooth Criminal và Come Together.</p>', 'Full', 1, 'single', 'completed', 10, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Jackson","avatar":""},{"name":"Joe Pesci","avatar":""},{"name":"Mick Jagger","avatar":""},{"name":"Sean Lennon","avatar":""},{"name":"Kellie Parker","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324546);
