INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('women-on-the-verge-of-a-nervous-breakdown', 'Women On The Verge Of A Nervous Breakdown', 'Women On The Verge Of A Nervous Breakdown', 'https://phimimg.com/upload/vod/20231208-1/17d1509decdd845aac4d0a769b0394cb.jpg', 'https://phimimg.com/upload/vod/20231208-1/0a3b6234a93023f54d8c4a6e1df8162c.jpg', '<p>Người yêu của Pepa, Iván, rời xa cô và cô cố gắng liên lạc với anh để tìm hiểu lý do tại sao anh rời đi. Trong việc tìm kiếm Iván, cô ấy đối đầu với vợ con mình, người không biết gì như cô ấy. Trong khi đó, Candela, bạn của cô, sợ cảnh sát có thể đang tìm kiếm cô vì bạn trai cũ, một kẻ khủng bố Hồi giáo và các hoạt động tội phạm của ông. Khi cốt truyện phát triển, người ta tiết lộ rằng cuộc sống của mọi người đều đan xen nhiều hơn so với những gì họ có thể mong đợi.</p>', 'Full', 1, 'single', 'completed', 15, 1988, 'Vietsub', 'HD', 'Tây Ban Nha', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324546);
