INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-dien-loan', 'Cảnh Sát Điên Loạn', 'Maniac Cop', 'https://phimimg.com/upload/vod/20231208-1/50f7f84cf5b98168246dbe346ab53e34.jpg', 'https://phimimg.com/upload/vod/20231208-1/ee7f813f85fd3989c7d3e7e504b7b252.jpg', '<p>Ở New York, mọi người bị giết và bóp cổ đến chết một cách dã man trên đường phố rộng rãi. Tất cả các nhân chứng đều đồng ý rằng kẻ sát nhân mặc đồng phục cảnh sát. Ngay sau đó, cảnh sát tìm kiếm và tìm thấy một kẻ tình nghi trong hàng ngũ của chính họ: Jack Forrest, kẻ bị tình nghi đã giết vợ của chính mình và những người không may còn lại chết dưới triều đại khủng bố của Maniac Cop. Để chứng minh mình vô tội, anh điều tra vụ án cùng với đối tác của mình, Theresa Mallory.</p>', 'Full', 1, 'single', 'completed', 11, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Atkins","avatar":""},{"name":"Bruce Campbell","avatar":""},{"name":"Laurene Landon","avatar":""},{"name":"Richard Roundtree","avatar":""},{"name":"William Smith","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324546);
