INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-tinh-tay-ba', 'Mối Tình Tay Ba', 'The Unbearable Lightness of Being', 'https://phimimg.com/upload/vod/20231202-1/a420aff858a10d47ecc7f7f3037acce4.jpg', 'https://phimimg.com/upload/vod/20231202-1/9ee80c2ade0a404569c55d835e83e764.jpg', '<p>Bác sĩ phẫu thuật thành công Tomas rời Praha để phẫu thuật, gặp một nhiếp ảnh gia trẻ tên là Tereza và đưa cô ấy trở lại với anh ta. Tereza ngạc nhiên khi biết Tomas đã có quan hệ tình cảm với Sabina phóng túng, nhưng khi cuộc xâm lược của Liên Xô xảy ra, cả ba người đều trốn sang Thụy Sĩ. Sabina bắt đầu ngoại tình, Tom tiếp tục lăng nhăng, và Tereza chán ghét trở về Tiệp Khắc. Nhận ra sai lầm của mình, Tomas quyết định đuổi theo cô.</p>', 'Full', 1, 'single', 'completed', 11, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Daniel Day-Lewis","avatar":""},{"name":"Juliette Binoche","avatar":""},{"name":"Lena Olin","avatar":""},{"name":"Derek de Lint","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Erland Josephson","avatar":""},{"name":"Pavel Landovský","avatar":""},{"name":"Donald Moffat","avatar":""},{"name":"Daniel Olbrychski","avatar":""},{"name":"Tomasz Borkowy","avatar":""},{"name":"Bruce Myers","avatar":""},{"name":"Pavel Slabý","avatar":""},{"name":"Pascale Kalensky","avatar":""},{"name":"Jacques Ciron","avatar":""},{"name":"Anne Lonnberg","avatar":""},{"name":"László Szabó","avatar":""},{"name":"V","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324546);
