INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oliver-va-nhung-nguoi-ban', 'Oliver và Những Người Bạn', 'Oliver & Company', 'https://phimimg.com/upload/vod/20231129-1/8698a39dfdda495d00b2c17f4b5b53eb.jpg', 'https://phimimg.com/upload/vod/20231129-1/80d478e5fb5f4c8c42e408cbaf940fd6.jpg', '<p>Chú mèo mồ côi Oliver bị lạc ở Manhattan và được thu nạp vào một băng móc túi, cầm đầu là chó Dodger và ông chủ Fagin. Khi cô bé sống ở Fifth Avenue tìm thấy Oliver và mang cậu về nuôi, ông chủ của Fagin, Sykes muốn bắt cóc tống tiền cả hai. Biết được kế hoạch thâm độc này, những chiến hữu của Oliver đã hợp sức tính toán giải cứu cho cậu và cô chủ kia dẫn đến những cuộc phiêu lưu cực kỳ hấp dẫn của các nhân vật.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joey Lawrence","avatar":""},{"name":"Billy Joel","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Richard Mulligan","avatar":""},{"name":"Roscoe Lee Browne","avatar":""},{"name":"Sheryl Lee Ralph","avatar":""},{"name":"Dom DeLuise","avatar":""},{"name":"Taurean Blacque","avatar":""},{"name":"Carl Weintraub","avatar":""},{"name":"Robert Loggia","avatar":""},{"name":"Natalie Gregory","avatar":""},{"name":"William Glover","avatar":""},{"name":"Bette Midler","avatar":""},{"name":"Deborah Gates","avatar":""},{"name":"Charles Bartlett","avatar":""},{"name":"Jonathan Brandis","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324546);
