INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-den-trai-tim', 'Trái tim đến trái tim', 'Heart To Hearts', 'https://phimimg.com/upload/vod/20231123-1/447fa33ef5373f3e37b293ba9d3dfc44.jpg', 'https://phimimg.com/upload/vod/20231123-1/4fd8a5875e9ac1745acfde8203759ef6.jpg', '<p>Sau khi chia tay với bạn gái, Liu Yali gặp một cô gái trẻ thiên tài tên là Wu Huimin trong dàn hợp xướng. Liu đã chăm sóc Huimin, nhưng bà mẹ đơn thân của Huimin cho rằng Liu ác cảm. Liu và mẹ của Huimin trở thành kẻ thù của nhau; tuy nhiên, họ dần yêu nhau. Lúc này, bạn gái cũ của Yali quay lại và yêu cầu quay lại với anh ta ...</p>', 'Full', 1, 'single', 'completed', 13, 1988, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"George Lam Chi-Cheung","avatar":""},{"name":"Carol Cheng","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Vivian Chow","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Chan San-Hiu","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Lawrence Cheng","avatar":""},{"name":"Lowell Lo Koon-Ting","avatar":""},{"name":"Yip Hon-Leung","avatar":""},{"name":"Manfred Wong","avatar":""},{"name":"Chow Mei-Fung","avatar":""},{"name":"Law Ching-Ho","avatar":""},{"name":"Dennis Chan Kwok-San","avatar":""},{"name":"Michael Chow Man-Kin","avatar":""},{"name":"Woo-Ping Yuen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324546);
