INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-gia-toc', 'Long Gia Tộc', 'The Dragon Family', 'https://phimimg.com/upload/vod/20231116-1/c4ba944b483d586f758fdbfb94069d8d.jpg', 'https://phimimg.com/upload/vod/20231116-1/2875a96c6ab5b3333c310e2aef58901b.jpg', '<p>Long Gia Tộc - The Dragon Family nói về một gia đình trong giới xã hội đen Hồng Kông những năm 80 thế kỷ trước, thời điểm mà các thủ lĩnh của Tứ gia tộc thề sẽ làm ăn chân chính, từ bỏ hẳn nghề buôn ma túy. Riêng nhóm thứ 2 vẫn tiếp tục làm ăn bất hợp pháp và còn lên kế hoạch gài bẫy 1 đứa con của Long lão đại, khiến anh này mất mạng. Từ đây, sóng gió giang hồ lại nổi lên và đỉnh điểm là các cuộc thanh toán trả thù đẫm máu.</p>', 'Full', 1, 'single', 'completed', 14, 1988, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Alan Tam","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"Max Mok Siu-Chung","avatar":""},{"name":"Michael Miu","avatar":""},{"name":"Ko Chun-Hsiung","avatar":""},{"name":"Lisa Chiao Chiao","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Lau Kar-Wing","avatar":""},{"name":"Ku Feng","avatar":""},{"name":"Stanley Fung","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Norman Chui Siu-Keung","avatar":""},{"name":"Phillip Ko","avatar":""},{"name":"Blackie Ko Sho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324546);
