INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-chong-la-qua-du', 'Một chồng là quá đủ', 'One Husband Too Many', 'https://phimimg.com/upload/vod/20231116-1/57f1634030a094ff810ecfb9d724b749.jpg', 'https://phimimg.com/upload/vod/20231116-1/64310161428165eb10857f49a8224bcd.jpg', '<p>Là phần tiếp theo của A Happy Bigamist, bộ phim này kể về cuộc sống của cả Anthony Chan và Kenny Bee sau khi vợ của họ (Anita Mui và Pat Ha) đã rời bỏ họ. Khi cả hai người vợ của họ đã ra đi, cả hai đều cố gắng tán tỉnh Cherie Chung mà không cho cô ấy biết rằng họ đang sống cùng nhau. Một bộ phim hài khác của đạo diễn Anthony Chan.</p>', 'Full', 1, 'single', 'completed', 12, 1988, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Kenny Bee","avatar":""},{"name":"Michael Chan","avatar":""},{"name":"Cherie Chung","avatar":""},{"name":"Pat Ha","avatar":""},{"name":"Anita Mui","avatar":""},{"name":"Anthony Chan Yau","avatar":""},{"name":"Bolo Yeung","avatar":""},{"name":"Alfred Cheung Kin-Ting","avatar":""},{"name":"Tin Ching","avatar":""},{"name":"Bruce Mang","avatar":""},{"name":"Joanna Chan Pui-San","avatar":""},{"name":"Richard Yuen Tak","avatar":""},{"name":"Yip Hon-Leung","avatar":""},{"name":"Yat Boon-Chai","avatar":""},{"name":"Sabrina Ho","avatar":""},{"name":"Wong Chi-Ming","avatar":""},{"name":"Luk Ying-Hong","avatar":""},{"name":"Fong Yue","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324546);
