INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-chong-la-qua-du', 'Một chồng là quá đủ', 'One Husband Too Many', 'một chồng là quá đủ one husband too many kenny bee michael chan cherie chung pat ha anita mui anthony chan yau bolo yeung alfred cheung kin-ting tin ching bruce mang joanna chan pui-san richard yuen tak yip hon-leung yat boon-chai sabrina ho wong chi-ming luk ying-hong fong yue ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('camille-cuoc-doi-va-so-phan', 'Camille: Cuộc Đời Và Số Phận', 'Camille Claudel', 'https://phimimg.com/upload/vod/20231130-1/7b999a3f29cda73b52ea4f2b3cc86148.jpg', 'https://phimimg.com/upload/vod/20231130-1/a7238b4af152513e59f7887f128f2e3b.jpg', '<p>Camille Claudel là một bộ phim Pháp năm 1988 của đạo diễn Bruno Nuytten kể về cuộc đời của nhà điêu khắc thế kỷ 19 Camille Claudel (8/12/1864 - 19/10/1943). Bộ phim dựa trên cuốn sách của Reine-Marie Paris, cháu gái của nhà thơ, nhà văn và nhà ngoại giao Paul Claudel (là em trai Camille). Vai Camille Claudel do một trong những nữ diễn viên nổi tiếng nhất nước Pháp đương đại, Isabelle Adjani đảm nhận. Bộ phim đã xuất sắc đoạt 5 giải Cesar trong số 12 đề cử, đại diện cho nước Pháp tranh giải Oscar Phim ngoại ngữ hay nhất và thêm một đề cử Oscar cho Isabelle Adjani. Năm 2013, Camille Claudel một lần nữa lên màn ảnh rộng qua diễn xuất của Jiliette Binoche trong phim Camille Claudel 1915 của đạo diễn Bruno Dumont.</p>', 'Full', 1, 'single', 'completed', 13, 1988, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Isabelle Adjani","avatar":""},{"name":"Gérard Depardieu","avatar":""},{"name":"Laurent Grévill","avatar":""},{"name":"Alain Cuny","avatar":""},{"name":"Roch Leibovici","avatar":""},{"name":"Madeleine Robinson","avatar":""},{"name":"Philippe Clévenot","avatar":""},{"name":"Katrine Boorman","avatar":""},{"name":"Maxime Leroux","avatar":""},{"name":"Danièle Lebrun","avatar":""},{"name":"Jean-Pierre Sentier","avatar":""},{"name":"Roger Planchon","avatar":""},{"name":"Aurelle Doazan","avatar":""},{"name":"Madeleine Marie","avatar":""},{"name":"Gérard Baume","avatar":""},{"name":"Mart","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324546);
