INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-thuat-cua-dao-2', 'Nghệ Thuật Cua Đào 2', 'The Romancing Star II', 'https://phimimg.com/upload/vod/20231117-1/e5bb0ef2fdebd66c4861c30f1d1e63b6.jpg', 'https://phimimg.com/upload/vod/20231117-1/fc6f1a1e28563bd8831af48e073dfce8.jpg', '<p>Ba chàng độc thân lập dị tham gia một chương trình truyền hình, họ nỗ lực tán tỉnh người thương và bị cuốn vào cuộc chiến giữa các đài truyền hình.</p>', 'Full', 1, 'single', 'completed', 14, 1988, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Stanley Fung","avatar":""},{"name":"Chow Yun-fat","avatar":""},{"name":"Natalis Chan","avatar":""},{"name":"Wong Wan-Si","avatar":""},{"name":"Elizabeth Lee Mei-Fung","avatar":""},{"name":"Carina Lau","avatar":""},{"name":"Wong Jing","avatar":""},{"name":"Lo Hoi-pang","avatar":""},{"name":"Michael Lai Siu-Tin","avatar":""},{"name":"Alan Tam","avatar":""},{"name":"William Ho Ka-Kui","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324546);
