INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nghe-thuat-cua-dao-2', 'Nghệ Thuật Cua Đào 2', 'The Romancing Star II', 'nghệ thuật cua đào 2 the romancing star ii andy lau eric tsang stanley fung chow yun-fat natalis chan wong wan-si elizabeth lee mei-fung carina lau wong jing lo hoi-pang michael lai siu-tin alan tam william ho ka-kui ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-luong-do', 'Cao Lương Đỏ', 'Red Sorghum', 'https://phimimg.com/upload/vod/20231117-1/4e73f61d7b1ccb6c72e58b705d67acbf.jpg', 'https://phimimg.com/upload/vod/20231117-1/445b424c85ce9b70e786aa8a15a15c52.jpg', '<p>Bối cảnh câu chuyện là những năm 1920 và 1930 tại miền quê Cao Mật ở miền Nam Trung Hoa. Câu chuyện được kể từ ngôi thứ nhất, với nhân vật chính là bà nội của người kể chuyện. Cô gái trẻ đầy khát vọng yêu đương đã bị gả cho một người đàn ông mắc bệnh phong. Ngày lên kiệu hoa, cô gái đầy chán chường ấy đã gặp và say mê một trong những người phu kiệu khỏe mạnh, mà sau này đã trở thành tư lệnh Dư Chiêm Ngao, người anh hùng phục kích đoàn xe Nhật. Ngày hôm ấy chính anh đã cứu cô khỏi tay bọn cướp. Hai ngày sau ở nhà chồng, cô thức trắng với con dao trong tay. Ngày thứ ba được trả về, người phu kiệu đã cướp cô chạy vào rừng cao lương đỏ. Ba ngày hạnh phúc trong rừng đã đem lại cho cô một đứa con trai, cha của người kể chuyện. Năm 14 tuổi, người con trai gia nhập đoàn quân của Dư Chiêm Ngao mà ông vẫn coi là cha nuôi. Người con gái giờ đây đã là người thiếu phụ, ngày ngày vẫn làm bánh đem ra chiến trường khao quân. Trong một lần gánh bánh gặp đúng lúc xe giặc đang đi qua, bà đã hy sinh. Trước khi chết bà nói cho con trai biết về người cha thật sự, và ra đi nhẹ nhàng trên đệm cây cao lương, nơi đã chứng kiến tình yêu và hạnh phúc của bà.</p>', 'Full', 1, 'single', 'completed', 14, 1988, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gong Li","avatar":""},{"name":"Jiang Wen","avatar":""},{"name":"Teng Ru-jun","avatar":""},{"name":"Ji Liu","avatar":""},{"name":"Ming Qian","avatar":""},{"name":"Chunhua Ji","avatar":""},{"name":"Zhai Chunhua","avatar":""},{"name":"Jia Zhaoji","avatar":""},{"name":"Yuxiang Zhang","avatar":""},{"name":"Guiyun Zhou","avatar":""},{"name":"Yang Qianbin","avatar":""},{"name":"Guoqing Xu","avatar":""},{"name":"Yao Er-Ga","avatar":""},{"name":"Yusheng Li","avatar":""},{"name":"Kun Dong","avatar":""},{"name":"Hu Xiaoguang","avatar":""},{"name":"Zhang Yimou","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324546);
