INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cao-luong-do', 'Cao Lương Đỏ', 'Red Sorghum', 'cao lương đỏ red sorghum gong li jiang wen teng ru-jun ji liu ming qian chunhua ji zhai chunhua jia zhaoji yuxiang zhang guiyun zhou yang qianbin guoqing xu yao er-ga yusheng li kun dong hu xiaoguang zhang yimou ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-akira', 'Chúa Tể Akira', 'AKIRA', 'https://phimimg.com/upload/vod/20231113-1/faa98d215f94bf52f24e197a935138eb.jpg', 'https://phimimg.com/upload/vod/20231113-1/734cd44b8f65991b816972defbf50ce3.jpg', '<p>Akira (Chúa tể Akira) Tháng bảy năm 1988, một vụ nổ bí ẩn nhấn chìm Tokyo vào biển lửa, đồng thời châm ngòi cho đại chiến thế giới lần ba. Ba mươi mốt năm sau, chiến tranh kết thúc. Tokyo vực dậy từ đống tro tàn và dần phát triển thành một trong những thành phố thịnh vượng nhất thế giới, kéo theo đó là tình trạng đạo đạo đức và nhân tính suy tàn do sự lên ngôi của tiền bạc, vật chất trong xã hội. Kaneda và Tetsuo là bạn chí cốt và cũng là thành viên của băng đua xe Capsule. Trong cái đêm định mệnh khi giao đấu với băng đảng đối địch, Tetsuo tình cờ chạm trán với một mẫu vật trốn thoát khỏi phòng thí nghiệm. Cuộc chạm trán nhanh chóng biến thành thảm họa khi cả mẫu vật lẫn Tetsuo đều bị chính phủ bắt giữ. Nhiệm vụ của Kaneda bây giờ là phải tìm mọi cách cứu Tetsuo. Thế nhưng số phận sớm đẩy cả Kaneda lẫn Tetsuo vào vòng xoáy bạo lực khi những bí mật từ hơn ba mươi năm trước dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 13, 1988, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Mitsuo Iwata","avatar":""},{"name":"Nozomu Sasaki","avatar":""},{"name":"Mami Koyama","avatar":""},{"name":"Tessyo Genda","avatar":""},{"name":"Koichi Kitamura","avatar":""},{"name":"Yuriko Fuchizaki","avatar":""},{"name":"Masaaki Okura","avatar":""},{"name":"Takeshi Kusao","avatar":""},{"name":"Kazuhiro Kamifuji","avatar":""},{"name":"Tatsuhiko Nakamura","avatar":""},{"name":"Fukue Itô","avatar":""},{"name":"Yuka Ôno","avatar":""},{"name":"Hiroshi Ôtake","avatar":""},{"name":"Kazumi Tanaka","avatar":""},{"name":"Masato Hirano","avatar":""},{"name":"Masayuki Katô","avatar":""},{"name":"Michihiro Ikem","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324546);
