INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-si-co-dong-gundam-char-phan-cong', 'Chiến sĩ cơ động Gundam: Char phản công', 'Mobile Suit Gundam: Char''s Counterattack', 'https://phimimg.com/upload/vod/20231113-1/6117f8af63887afa96d77110a18dafa4.jpg', 'https://phimimg.com/upload/vod/20231113-1/706c4c0bd5452047535a075aa0aadf0a.jpg', '<p>Mười ba năm sau chiến tranh, đội quân Neo Zeon lại đe dọa hòa bình. Trang bị Nu Gundam, Amuro Ray và lực lượng Liên bang ra trận một lần nữa.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 1988, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Shuichi Ikeda","avatar":""},{"name":"Toru Furuya","avatar":""},{"name":"Fuyumi Shiraishi","avatar":""},{"name":"Hirotaka Suzuoki","avatar":""},{"name":"Kazue Ikura","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Maria Kawamura","avatar":""},{"name":"Mayumi Shou","avatar":""},{"name":"Mitsuki Yayoi","avatar":""},{"name":"Nozomu Sasaki","avatar":""},{"name":"Shin Mori","avatar":""},{"name":"Shinobu Adachi","avatar":""},{"name":"Yoshiko Sakakibara","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324546);
