INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-chay-luc-nua-dem', 'Trốn Chạy Lúc Nửa Đêm', 'Midnight Run', 'https://phimimg.com/upload/vod/20231111-1/7d806a515ee947893c672729672fd3f6.jpg', 'https://phimimg.com/upload/vod/20231111-1/221c98a7b040d5ed2e8d55217ff4271f.jpg', '<p>Một nhân viên kế toán biển thủ 15 triệu đô la tiền của đám đông, được tại ngoại và bị truy đuổi bởi những kẻ săn tiền thưởng, FBI và Mafia.</p>', 'Full', 1, 'single', 'completed', 15, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Charles Grodin","avatar":""},{"name":"Yaphet Kotto","avatar":""},{"name":"John Ashton","avatar":""},{"name":"Dennis Farina","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Richard Foronjy","avatar":""},{"name":"Robert Miranda","avatar":""},{"name":"Jack Kehoe","avatar":""},{"name":"Wendy Phillips","avatar":""},{"name":"Danielle DuClos","avatar":""},{"name":"Philip Baker Hall","avatar":""},{"name":"Tom McCleister","avatar":""},{"name":"Mary Gillis","avatar":""},{"name":"John Toles-Bey","avatar":""},{"name":"Thomas J. Hageboeck","avatar":""},{"name":"St","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324546);
