INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-tinh-lang-tu', 'Lệ Tình Lãng Tử', 'As Tears Go By', 'https://phimimg.com/upload/vod/20231109-1/e4248c0eff7bd22105fb09faaec21f90.jpg', 'https://phimimg.com/upload/vod/20231109-1/186a3cae7bbc1585de00eabdda3aae12.jpg', '<p>Lệ Tình Lãng Tử (Vượng Giác Ca Môn | Vượng Giác Tạp Môn) là một bộ phim điện ảnh do Hồng Kông sản xuất vào năm 1988.Trong phim Lưu Đức Hoa vào vai một một tay chơi khét tiếng,anh cũng là một dân anh chị có máu mặt trong vùng.Một lần nọ, người em họ của anh ta từ quê lên chữa bệnh và ở chung một nhà với anh ra, 2 người theo thời gian đã yêu nhau say đắm, những tưởng cuộc sống của hai người sẽ bình yên thì lúc này người bạn thân nhất như anh em bỗng dưng đắt tội với một trùm giang hồ và buộc Lưu Đức Hoa phải ra tay cứu lấy bạn của mình. Số mệnh của hai người có nguy cơ âm dương cách biệt vì lần này là một đối thủ rất mạnh và tàn ác.</p>', 'Full', 1, 'single', 'completed', 12, 1988, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Jacky Cheung","avatar":""},{"name":"Alex Man","avatar":""},{"name":"Lam Kau","avatar":""},{"name":"William Chang Suk-Ping","avatar":""},{"name":"Chan Chi-Fai","avatar":""},{"name":"Pak Yan","avatar":""},{"name":"Chun Kwai-Bo","avatar":""},{"name":"Fei Pak","avatar":""},{"name":"Hui Fan","avatar":""},{"name":"Ronald Wong Ban","avatar":""},{"name":"Wong Aau","avatar":""},{"name":"Wong Kim-Fung","avatar":""},{"name":"Benz Kong To-Hoi","avatar":""},{"name":"Kan Tat-Wah","avatar":""},{"name":"Wai Ching","avatar":""},{"name":"Pong Keung-Fai","avatar":""},{"name":"Kam Shan","avatar":""},{"name":"Chui Si-","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324546);
