INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xac-song-tro-lai-2', 'Xác Sống Trở Lại 2', 'Return of the Living Dead Part II', 'https://phimimg.com/upload/vod/20231103-1/0efff85ad23c2bcaf7c53b18119ea00b.jpg', 'https://phimimg.com/upload/vod/20231103-1/6b52b53801484a8d4e8aefcebb160166.jpg', '<p>Một nhóm trẻ em phát hiện ra một trong những chiếc thùng chứa xác chết đang thối rữa và giải phóng khí Trioxin 2-4-5 vào không khí, khiến người chết một lần nữa sống dậy từ ngôi mộ và tìm kiếm bộ não.</p>', 'Full', 1, 'single', 'completed', 15, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"James Karen","avatar":""},{"name":"Thom Mathews","avatar":""},{"name":"Suzanne Snyder","avatar":""},{"name":"Michael Kenworthy","avatar":""},{"name":"Marsha Dietlein","avatar":""},{"name":"Dana Ashbrook","avatar":""},{"name":"Philip Bruns","avatar":""},{"name":"Jonathan Terry","avatar":""},{"name":"Thor Van Lingen","avatar":""},{"name":"Sally Smythe","avatar":""},{"name":"Don Maxwell","avatar":""},{"name":"Jason Hogan","avatar":""},{"name":"Allan Trautman","avatar":""},{"name":"Forrest J. Ackerman","avatar":""},{"name":"Mitch Pileggi","avatar":""},{"name":"Brian Peck","avatar":""},{"name":"Troy Fromi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324546);
