INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-den-chet', 'Bắn Đến Chết', 'Shoot to Kill', 'https://phimimg.com/upload/vod/20231101-1/b85c0e5ef86c8e21702926576eb44e5c.jpg', 'https://phimimg.com/upload/vod/20231101-1/2ac09faae3e90afede8bd980b15c1f9f.jpg', '<p>Khi một kẻ giết người xảo quyệt biến mất vào vùng núi gồ ghề ở Tây Bắc Thái Bình Dương, đặc vụ FBI đang truy đuổi Warren Stantin phải đổi những con đường quen thuộc trong thành phố để lấy những con đường mòn hoang vu xa lạ. Hoàn toàn mất khả năng của mình, Stantin buộc phải tranh thủ sự trợ giúp của chuyên gia theo dõi Jonathan Knox. Đó là một mối quan hệ sóng gió nhưng quan trọng mà họ phải duy trì để tồn tại... và một mối quan hệ ngày càng trở nên tuyệt vọng khi Sarah, bạn gái của Knox trở thành con tin mới nhất của kẻ giết người!</p>', 'Full', 1, 'single', 'completed', 14, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sidney Poitier","avatar":""},{"name":"Tom Berenger","avatar":""},{"name":"Kirstie Alley","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Richard Masur","avatar":""},{"name":"Andrew Robinson","avatar":""},{"name":"Kevin Scannell","avatar":""},{"name":"Frederick Coffin","avatar":""},{"name":"Michael MacRae","avatar":""},{"name":"Robert Lesser","avatar":""},{"name":"Milton Selzer","avatar":""},{"name":"Les Lannom","avatar":""},{"name":"Walter Marsh","avatar":""},{"name":"Frank C. Turner","avatar":""},{"name":"Sam Hiona","avatar":""},{"name":"Michael Chapman","avatar":""},{"name":"Janet Rotblat","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324546);
