INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-no-song', 'Chúng Nó Sống', 'They Live', 'https://phimimg.com/upload/vod/20231026-1/6e302b9a6cdbc82b91b91e11679356d3.jpg', 'https://phimimg.com/upload/vod/20231026-1/5b33737e2964db3067241d97049f6f21.jpg', '<p>They Live là bộ phim hành động năm 1988 do John Carpenter làm đạo diễn, và lấy cảm hứng từ truyện ngắn &quot;Tám giờ buổi sáng&quot; của Ray Nelson và cuốn tiểu thuyết chuyển thể truyện tranh &quot;Nada&quot;. John Nada là một công nhân xây dựng đang thất nghiệp. Anh ta đến một thị trấn mới và tìm thấy một cặp kính mắt cho phép anh ta nhìn thấy không chỉ những người ngoài hành tinh đang sống giữa chúng ta mà còn có những thông điệp ngầm bắt con người tuân thủ chúng, ẩn trong các phương tiện truyền thông. Nada quyết định cho Frank, bạn anh biết chiếc kính đang cho anh thấy những gì. Frank nghĩ anh lừa minh và đã xảy ra một trận đấu tay đôi giữa hai người bạn làm công. Sau khi chứng minh được sự thật từ những điều Nada nói, hai người đã cùng nhau tìm hiểu ...</p>', 'Full', 1, 'single', 'completed', 16, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Roddy Piper","avatar":""},{"name":"Keith David","avatar":""},{"name":"Meg Foster","avatar":""},{"name":"George Buck Flower","avatar":""},{"name":"Peter Jason","avatar":""},{"name":"Raymond St. Jacques","avatar":""},{"name":"Jason Robards III","avatar":""},{"name":"John Lawrence","avatar":""},{"name":"Susan Barnes","avatar":""},{"name":"Sy Richardson","avatar":""},{"name":"Wendy Brainard","avatar":""},{"name":"Lucille Meredith","avatar":""},{"name":"Susan Blanchard","avatar":""},{"name":"Norman Alden","avatar":""},{"name":"Dana Bratton","avatar":""},{"name":"John F. Goff","avatar":""},{"name":"Norman","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324546);
