INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-vo-phuong-xa', 'Tìm Vợ Phương Xa', 'Coming to America', 'https://phimimg.com/upload/vod/20231024-1/3409c826f1078440334b3c044b074504.jpg', 'https://phimimg.com/upload/vod/20231024-1/3196cb81115f82ab4f9e4e36077f4cb7.jpg', '<p>Đó là sinh nhật lần thứ 21 của Hoàng tử Akeem xứ Zamunda và cũng là ngày anh chuẩn bị kết hôn với một người con gái mà anh chưa từng một lần gặp mặt. Hoàng tử quyết định phá luật lệ và du lịch tới Mỹ để tìm kiếm tình yêu thực sự của cuộc đời anh.</p>', 'Full', 1, 'single', 'completed', 14, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Arsenio Hall","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"John Amos","avatar":""},{"name":"Shari Headley","avatar":""},{"name":"Frankie Faison","avatar":""},{"name":"Louie Anderson","avatar":""},{"name":"Eriq La Salle","avatar":""},{"name":"Allison Dean","avatar":""},{"name":"Madge Sinclair","avatar":""},{"name":"Paul Bates","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Ralph Bellamy","avatar":""},{"name":"Don Ameche","avatar":""},{"name":"Vanessa Bell Calloway","avatar":""},{"name":"Calvin Lockhart","avatar":""},{"name":"Garcelle","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324546);
