INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-rambo-3', 'Chiến Binh Rambo 3', 'Rambo III', 'https://phimimg.com/upload/vod/20231022-1/6a3293221990084c85a464e08690b9e2.jpg', 'https://phimimg.com/upload/vod/20231022-1/d13f8d9a1352584fe065554188f2b6fc.jpg', '<p>Sau những cuộc phiêu lưu nguy hiểm và đầy máu, John Rambo trở lại Thái Lan và sống ẩn dật trong tu viện, gắn bó với Phật Giáo trong những chuỗi ngày tách biệt với thế giới vồn vã. Trong lúc đó, phong trào chiến tranh của người Afghanistan chống lại người Xô Viết đang trở nên hừng hực lửa. Torautman cầu cứu sự viện trợ của Rambo, mong muốn anh sẽ lại sát cánh với mình như ngày nào. Rambo lưỡng lự vì cuộc sống thanh bình nơi tu viện từ khi nào đã trở nên gần gũi với anh. Nhưng khi được tin dữ người bằng hữu đã bị bắt và quân đội anh đều bỏ mạng dưới làn đạn, Rambo không thể làm ngơ. Bỏ lại cuộc sống tĩnh lặng và những vướng mắc trong lòng, Rambo xông vào hiểm nguy tới Afghanistan…</p>', 'Full', 1, 'single', 'completed', 21, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Richard Crenna","avatar":""},{"name":"Marc de Jonge","avatar":""},{"name":"Kurtwood Smith","avatar":""},{"name":"Spiros Focás","avatar":""},{"name":"Sasson Gabai","avatar":""},{"name":"Doudi Shoua","avatar":""},{"name":"Randy Raney","avatar":""},{"name":"Marcus Gilbert","avatar":""},{"name":"Alon Abutbul","avatar":""},{"name":"Mahmoud Assadollahi","avatar":""},{"name":"Yosef Shiloach","avatar":""},{"name":"Harold Diamond","avatar":""},{"name":"Mati Seri","avatar":""},{"name":"Hany Said El Deen","avatar":""},{"name":"Shaby Ben-Aroya","avatar":""},{"name":"Marc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"