INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-dau-thu-thach', 'Đương Đầu Thử Thách', 'Die Hard', 'https://phimimg.com/upload/vod/20231020-1/79474cc727be7c328678b213033d21b9.jpg', 'https://phimimg.com/upload/vod/20231020-1/f89c436d0b3e3ce7df484845fbd7b0a2.jpg', '<p>Sĩ quan sở cảnh sát New York John McClane (Bruce Willis) bay tới Los Angeles để dự Giáng sinh cùng vợ vốn đang có trục trặc tình cảm. Không may, một nhóm khủng bố đừng đầu bởi Hans Gruber (Alan Rickman) đã bắt làm con tin tất cả mọi người trong tòa nhà mà vợ anh làm việc. McClane phải làm gì để giải thoát mọi người? - 40 câu chuyện. Mười hai tên khủng bố. Một viên cảnh sát.</p>', 'Full', 1, 'single', 'completed', 17, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bruce Willis","avatar":""},{"name":"Alan Rickman","avatar":""},{"name":"Alexander Godunov","avatar":""},{"name":"Bonnie Bedelia","avatar":""},{"name":"Reginald VelJohnson","avatar":""},{"name":"Paul Gleason","avatar":""},{"name":"De''voreaux White","avatar":""},{"name":"William Atherton","avatar":""},{"name":"Hart Bochner","avatar":""},{"name":"James Shigeta","avatar":""},{"name":"Bruno Doyon","avatar":""},{"name":"Andreas Wisniewski","avatar":""},{"name":"Clarence Gilyard Jr.","avatar":""},{"name":"Joey Plewa","avatar":""},{"name":"Lorenzo Caccialanza","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324546);
