INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tucker-ban-linh-va-hoai-bao', 'Tucker: Bản Lĩnh và Hoài Bão', 'Tucker: The Man and His Dream', 'https://phimimg.com/upload/vod/20231016-1/41fd6c7cdc3dab89dfb8aa4d2bf037a4.jpg', 'https://phimimg.com/upload/vod/20231016-1/4376d6b54952072b566cf06043be6b94.jpg', '<p>Sau Thế chiến II, Preston Tucker mơ ước sáng tạo ra một chiếc xe hơi thời thượng hơn. Tuy nhiên, Tucker gặp phải vô vàn trở ngại, chủ yếu đến từ ngành công nghiệp ô tô.</p>', 'Full', 1, 'single', 'completed', 13, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Bridges","avatar":""},{"name":"Joan Allen","avatar":""},{"name":"Martin Landau","avatar":""},{"name":"Frederic Forrest","avatar":""},{"name":"Mako","avatar":""},{"name":"Dean Stockwell","avatar":""},{"name":"Christian Slater","avatar":""},{"name":"Nina Siemaszko","avatar":""},{"name":"Marshall Bell","avatar":""},{"name":"Peter Donat","avatar":""},{"name":"Elias Koteas","avatar":""},{"name":"Jay O. Sanders","avatar":""},{"name":"Corin Nemec","avatar":""},{"name":"Don Novello","avatar":""},{"name":"Anders Johnson","avatar":""},{"name":"Dean Goodman","avatar":""},{"name":"John X. Heart","avatar":""},{"name":"Patti Austi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324547);
