INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rap-chieu-bong-thien-duong', 'Rạp Chiếu Bóng Thiên Đường', 'Cinema Paradiso', 'https://phimimg.com/upload/vod/20231015-1/c7b84fed0f1518549970161f2d835392.jpg', 'https://phimimg.com/upload/vod/20231015-1/5d20fb8f297e0fe2c62035a7a158f859.jpg', '<p>Đã mang tiếng là dân mê phim mà chưa xem qua Cinema Paradiso thì quả là một thiếu sót cực lớn! Vì sao ư? Vì đây chính là bộ phim tôn vinh điện ảnh và những fan cuồng của điện ảnh.Với 1 giải Oscar và 1 Golden Globe dành cho phim nói tiếng nước ngoài hay nhất, 1 giải thưởng lớn của BGK tại liên hoan phim Cannes cùng vô số các giải thưởng khác, Cinema Paradiso xứng đáng là một tượng đài trong lòng những người yêu phim. Hãy xem phim để cùng cười, cùng khóc với câu chuyện và những nhân vật. Hãy xem phim để thấy tự hào mình là một người yêu điện ảnh và thêm yêu điện ảnh.Chắc chắn bộ phim sẽ mang lại cho bạn những giây phút cực kỳ vui vẻ nhưng cũng không thiếu đi những khoảng lặng mà cho tới tận lúc ra về bạn vẫn còn cảm thấy xúc ...</p>', 'Full', 1, 'single', 'completed', 22, 1988, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Philippe Noiret","avatar":""},{"name":"Jacques Perrin","avatar":""},{"name":"Marco Leonardi","avatar":""},{"name":"Salvatore Cascio","avatar":""},{"name":"Agnese Nano","avatar":""},{"name":"Antonella Attili","avatar":""},{"name":"Enzo Cannavale","avatar":""},{"name":"Isa Danieli","avatar":""},{"name":"Leo Gullotta","avatar":""},{"name":"Pupella Maggio","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324547);
