INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('halloween-4-su-tro-lai-cua-michael-myers', 'Halloween 4: Sự Trở Lại của Michael Myers', 'Halloween 4: The Return of Michael Myers', 'https://phimimg.com/upload/vod/20231015-1/87e7bc6cf412769b013447c39b071a2b.jpg', 'https://phimimg.com/upload/vod/20231015-1/718fa078127db229205fbf5758b0deca.jpg', '<p>Michael Myers có vẻ hôn mê đang được chuyển từ bệnh viện này sang bệnh viện khác, nhưng anh tỉnh dậy khi đội cứu thương nói về cháu gái còn sống của anh, Jamie. Sau khi tàn sát những người hầu của mình, Myers bắt đầu đi tìm người thân còn sống của mình, may mắn thay, được chăm sóc bởi một người chị nuôi tốt bụng và tháo vát tên Rachel. Trong khi đó, bác sĩ Loomis luôn thận trọng vẫn tiếp tục theo dõi sát thủ.</p>', 'Full', 1, 'single', 'completed', 14, 1988, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Donald Pleasence","avatar":""},{"name":"Danielle Harris","avatar":""},{"name":"Ellie Cornell","avatar":""},{"name":"George P. Wilbur","avatar":""},{"name":"Michael Pataki","avatar":""},{"name":"Beau Starr","avatar":""},{"name":"Kathleen Kinmont","avatar":""},{"name":"Sasha Jenson","avatar":""},{"name":"Gene Ross","avatar":""},{"name":"Carmen Filpi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324547);
