INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('couples-couples-couples', 'Couples, Couples, Couples', 'Couples, Couples, Couples', 'https://phimimg.com/upload/vod/20231013-1/580be5495f8249df51f8b9886b7f5fc4.jpg', 'https://phimimg.com/upload/vod/20231013-1/e026d2ba53949080420c829ec7987a77.jpg', '<p>Cặp đôi, Cặp đôi, Cặp đôi là một bộ phim hài có nội dung rộng rãi về những thay đổi thất thường trong chuyện tình cảm và việc sinh con.</p>', 'Full', 1, 'single', 'completed', 20, 1988, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Cherie Chung","avatar":""},{"name":"Jacky Cheung","avatar":""},{"name":"Melvin Wong Gam-Sam","avatar":""},{"name":"Corey Yuen","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Lowell Lo","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Lawrence Cheng","avatar":""},{"name":"Peter Chan","avatar":""},{"name":"Hei-lin Chan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324547);
