INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cop-xo-long', 'Cọp Xổ Lồng', 'Tiger On Beat', 'https://phimimg.com/upload/vod/20231010-1/bdbc0e0cad7d69497ee27c34d5808eaf.jpg', 'https://phimimg.com/upload/vod/20231010-1/5260f4f327e69d6b0e128d55a7f884bd.jpg', '<p>Một viên cảnh sát lão làng và tay cộng sự học việc phải giải quyết vụ án mạng của tay trùm buôn ma túy. Bộ phim hành động hài Hồng Kông nhái theo phong cách của &quot;Lethal Weapon&quot; này là một trong những bộ phim đầu sự nghiệp của Châu Nhuận Phát.</p>', 'Full', 1, 'single', 'completed', 15, 1988, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Conan Lee","avatar":""},{"name":"Nina Li Chi","avatar":""},{"name":"Shirley Ng","avatar":""},{"name":"James Wong","avatar":""},{"name":"Ti Lung","avatar":""},{"name":"Gordon Liu Chia-hui","avatar":""},{"name":"Norman Chui","avatar":""},{"name":"Phillip Ko","avatar":""},{"name":"Shing Fui-On","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324547);
