INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cop-xo-long', 'Cọp Xổ Lồng', 'Tiger On Beat', 'cọp xổ lồng tiger on beat chow yun-fat conan lee nina li chi shirley ng james wong ti lung gordon liu chia-hui norman chui phillip ko shing fui-on ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-canh-sat-phan-2', 'Câu Chuyện Cảnh Sát (Phần 2)', 'Prison On Fire (Season 2)', 'https://phimimg.com/upload/vod/20231010-1/193d396369ab9038f6f1c435439cdeb4.jpg', 'https://phimimg.com/upload/vod/20231010-1/5c30df08a0a95908bb1fb8cc1e652484.jpg', '<p>Sau sự kiện trong phần đầu, thanh tra Trần Gia Câu bị giáng chức xuống phục vụ tại lực lượng cảnh sát tuần tra giao thông. Nhiệm vụ mới của Gia Câu làm hài lòng bạn gái anh, Mỹ. Cô rất vui khi bạn trai của mình không còn phải đảm nhận các vụ án nguy hiểm và có nhiều thời gian hơn để gặp cô. Tuy nhiên, Trần Gia Câu sớm gặp lại Chu Thao và cánh tay phải của y là John Cao. Chu Thao được các bác sĩ kết luận chỉ còn sống được ba tháng nữa do trọng bệnh. Vì vậy hắn được tại ngoại để chữa bệnh. Chu Thao thề rằng ngày nào hắn còn sống thì cuộc sống của Gia Câu sẽ không yên bình. John Cao cùng một vài đàn em xuất hiện tại chung cư của Gia Câu và đe dọa với anh. Cảm thấy không an toàn, Gia Câu bảo Mỹ về nhà dì của cô lánh tạm. ...</p>', 'Full', 1, 'single', 'completed', 20, 1988, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Lam Kwok-Hung","avatar":""},{"name":"Bill Tung","avatar":""},{"name":"Mars","avatar":""},{"name":"John Cheung Ng-Long","avatar":""},{"name":"Benny Lai Keung-Kuen","avatar":""},{"name":"Ben Lam","avatar":""},{"name":"Danny Chow Yun-Kin","avatar":""},{"name":"Tai Bo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324547);
