INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-hoc-trong-lua', 'Trường Học Trong Lửa', 'School On Fire', 'https://phimimg.com/upload/vod/20231009-1/71491648dd2676e0f078825d35f551c1.jpg', 'https://phimimg.com/upload/vod/20231009-1/f67a8fbada91a406cfcafb7b3c6f6cb8.jpg', '<p>Một nữ sinh trẻ, Yuen Fong bị vướng vào vòng vây bi thảm của hoạt động hội tam hoàng sau khi cô làm chứng trước tòa về việc đánh đập hội tam hoàng. Khi tin tức này đến tai thủ lĩnh hội tam hoàng Brother Smart, Yuen Fong phải trả tiền bảo vệ cho anh ta vì những gì cô đã làm khi các sự việc bắt đầu leo thang.</p>', 'Full', 1, 'single', 'completed', 19, 1988, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Fennie Yuen","avatar":""},{"name":"Sarah Lee Lai-Yui","avatar":""},{"name":"Roy Cheung","avatar":""},{"name":"Damian Lau","avatar":""},{"name":"Lam Ching-Ying","avatar":""},{"name":"Victor Hon Kwan","avatar":""},{"name":"Tommy Wong","avatar":""},{"name":"Raymond Lee Wai-Man","avatar":""},{"name":"Ricky Ho","avatar":""},{"name":"Tse Wai-Kit","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324547);
