INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-truong-phu-nhat-ki', 'Đại Trượng Phu Nhật Kí', 'The Diary of a Big Man', 'https://phimimg.com/upload/vod/20231004-1/603c3c8fc12d293beffca0549db1422f.jpg', 'https://phimimg.com/upload/vod/20231004-1/64d3b5c810deb25f6b74e0a48721051d.jpg', '<p>Một người đàn ông đã cưới hai vợ dựng lên một màn kịch tinh vi để duy trì cuộc sống hai mặt của mình – cho đến khi hai cô vợ của anh tình cờ chạm trán nhau.</p>', 'Full', 1, 'single', 'completed', 21, 1988, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Joey Wong","avatar":""},{"name":"Sally Yeh","avatar":""},{"name":"Waise Lee","avatar":""},{"name":"Carrie Ng","avatar":""},{"name":"Kent Cheng","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"David Wu","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Tai Bo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324547);
