INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-nhan-4-nhiem-vu-gin-giu-hoa-binh', 'Siêu Nhân 4: Nhiệm Vụ Gìn Giữ Hòa Bình', 'Superman IV: The Quest For Peace', 'siêu nhân 4: nhiệm vụ gìn giữ hòa bình superman iv: the quest for peace christopher reeve margot kidder gene hackman mariel hemingway jackie cooper marc mcclure jon cryer sam wanamaker mark pillow damian mclawhorn superman 4: em busca da paz superman iv - the quest for peace superman classic iv: the quest for peace superman 4 - the quest for peace スーパーマンiv／最強の敵 superman iv: i kamp för freden superman iv: en busca de la paz 슈퍼맨 iv-최강의 적 superman iv : le face-à-face superman 4 : le face-à-face superman iv superman 4: the quest for peace superman iv: the quest for peace', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-pho-elm-3-nhung-chien-binh-trong-mo', 'Ác Mộng Phố Elm 3: Những Chiến Binh Trong Mơ', 'A Nightmare on Elm Street 3: Dream Warriors', 'https://phimimg.com/upload/vod/20260206-1/12796908fb9ad9a7ee91d6afd1f03a9f.jpg', 'https://phimimg.com/upload/vod/20260206-1/0751c65104230f4a208e610d83f1eadf.jpg', '<p>Một năm sau sự kiện trong phần hai. Kristen Parker cùng gia đình dọn đến 1 ngôi nhà trên phố Elm. Trong đêm đầu tiên ngủ tại căn nhà này Kristen đã gặp một cơn ác mộng khủng khiếp và cô tự hủy hoại mình. Gia đình cho rằng cô đã bị điên nên quyết định gửi Kristen vào bệnh viện tâm thần Westin Hills. Tại đây cô gia nhập 1 nhóm người bao gồm Joey, Taryn, Roland, Phillip, Jennifer và Will. Tất cả đều vì một lý do nào đó mà có mặt tại nơi này dưới sự điều trị của bác sĩ Neil và phụ tá Nancy Thompson. Nancy dựa vào những kinh nghiệm đã từng đối đầu với Freddy để giúp bọn trẻ đối mặt với tên quái vật và sống sót...</p>', 'Full', 1, 'single', 'completed', 12, 1987, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Heather Langenkamp","avatar":""},{"name":"Patricia Arquette","avatar":""},{"name":"Craig Wasson","avatar":""},{"name":"Robert Englund","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Ken Sagoes","avatar":""},{"name":"Rodney Eastman","avatar":""},{"name":"Jennifer Rubin","avatar":""},{"name":"Bradley Gregg","avatar":""},{"name":"Ira Heiden","avatar":""},{"name":"Penelope Sudrow","avatar":""},{"name":"John Saxon","avatar":""},{"name":"Priscilla Pointer","avatar":""},{"name":"Nan Martin","avatar":""},{"name":"Clayton Landey","avatar":""},{"name":"Brooke Bundy","avatar":""},{"name":"Krist","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Painajainen Elm Streetillä 3 – Unien soturit","Rémálom az Elm utcában 3.: Álomharcosok","Freddy - Chapitre 3 - Les Griffes du cauchemar","Pesadilla en la Calle Elm 3 Guerrero de los Sueños","Nightmare on Elm Street 3 - Freddy Krüger Lebt","Freddy 3","Pesadilla en la Calle del Infierno 3","Pesadilla en Elm Street 3: Los guerreros del sueño : 1987","A Nightmare On Elm Street 3","Pesadilla en lo profundo de la noche 3: Guerreros del sueño","Freddy 3 - Les Griffes du cauchemar","エルム街の悪夢3 惨劇の館","エルム街の悪夢 3 惨劇の館","Nightmare III - Freddy Krüger lebt","Koszmar z Ulicy Wiązów 3: Wojownicy Snów","Жах на вулиці В’язів 3: Воїни снів","Кошмари на Елм стрийт, Част 3: Воини на съня","Nocní mura v Elm Street 3: Bojovníci ze sna","Mareridt på Elm Street: Dream Warriors","Terror på Elm Street 3 - Freddys återkomst","Elm Sokağı Kabusu 3: Rüya Savaşçıları","Nočná mora v Elm Street 3: Bojovníci zo sna","Terror på Elm Street 3 - Freddys tilbakekomst","Košmaras Guobų gatvėje 3: Sapnų kariai","Εφιάλτης στο δρόμο με τις λεύκες - Μέρος 3: Οι πολεμιστές του ονείρου","Elmi tänava luupainaja 3","Strava u Ulici brijestova 3: Ratnici snova","How the Nightmare on Elm Street All Began","Freddy''s Funhouse","A Hora do Pesadelo 3: Os Guerreiros dos Sonhos","A Nightmare on Elm Street 3: Dream Warriors"]', 1784690324547);
