INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ac-mong-pho-elm-3-nhung-chien-binh-trong-mo', 'Ác Mộng Phố Elm 3: Những Chiến Binh Trong Mơ', 'A Nightmare on Elm Street 3: Dream Warriors', 'ác mộng phố elm 3: những chiến binh trong mơ a nightmare on elm street 3: dream warriors heather langenkamp patricia arquette craig wasson robert englund laurence fishburne ken sagoes rodney eastman jennifer rubin bradley gregg ira heiden penelope sudrow john saxon priscilla pointer nan martin clayton landey brooke bundy krist painajainen elm streetillä 3 – unien soturit rémálom az elm utcában 3.: álomharcosok freddy - chapitre 3 - les griffes du cauchemar pesadilla en la calle elm 3 guerrero de los sueños nightmare on elm street 3 - freddy krüger lebt freddy 3 pesadilla en la calle del infierno 3 pesadilla en elm street 3: los guerreros del sueño : 1987 a nightmare on elm street 3 pesadilla en lo profundo de la noche 3: guerreros del sueño freddy 3 - les griffes du cauchemar エルム街の悪夢3 惨劇の館 エルム街の悪夢 3 惨劇の館 nightmare iii - freddy krüger lebt koszmar z ulicy wiązów 3: wojownicy snów жах на вулиці в’язів 3: воїни снів кошмари на елм стрийт, част 3: воини на съня nocní mura v elm street 3: bojovníci ze sna mareridt på elm street: dream warriors terror på elm street 3 - freddys återkomst elm sokağı kabusu 3: rüya savaşçıları nočná mora v elm street 3: bojovníci zo sna terror på elm street 3 - freddys tilbakekomst košmaras guobų gatvėje 3: sapnų kariai εφιάλτης στο δρόμο με τις λεύκες - μέρος 3: οι πολεμιστές του ονείρου elmi tänava luupainaja 3 strava u ulici brijestova 3: ratnici snova how the nightmare on elm street all began freddy''s funhouse a hora do pesadelo 3: os guerreiros dos sonhos a nightmare on elm street 3: dream warriors', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-vo-hinh', 'Quái Thú Vô Hình', 'Predator', 'https://phimimg.com/upload/vod/20251116-1/7a8bab540a9502aacb1a6b1ee65bed9b.jpg', 'https://phimimg.com/upload/vod/20251116-1/a79983e6d3c50c2eb788624a162a25ff.jpg', '<p>Predator (tên tiếng Việt là Quái vật ăn thịt hay Quái vật vô hình) là bộ phim khoa học viễn tưởng, hành động Mỹ. Bộ phim xoay quanh trung đội đặc nhiệm của thiếu tá Alan &quot;Dutch&quot; Schaefer được lệnh tới khu vực rừng nhiệt đới ở biên giới giải cứu một bộ trưởng bị phiến quân Guatemala bắt cóc. George Dillon, một điệp viên của CIA, được phái tới để hỗ trợ nhóm đặc nhiệm. Họ di chuyển bằng trực thăng tới vùng hoạt động của lực lượng phiến loạn.Chỉ ít lâu sau khi đặt chân vào rừng rậm, cả nhóm nhận ra mình đang bị rơi vào cạm bẫy chết chóc. Duy có điều, kẻ săn mồi này lại đến từ ngoài trái đất. Trong trạng thái hoang mang tột độ, họ chụm đầu vào nhau để tìm biện pháp đối phó ...</p>', 'Full', 1, 'single', 'completed', 13, 1987, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Carl Weathers","avatar":""},{"name":"Kevin Peter Hall","avatar":""},{"name":"Elpidia Carrillo","avatar":""},{"name":"Bill Duke","avatar":""},{"name":"Jesse Ventura","avatar":""},{"name":"Sonny Landham","avatar":""},{"name":"Richard Chaves","avatar":""},{"name":"R.G. Armstrong","avatar":""},{"name":"Shane Black","avatar":""},{"name":"Peter Cullen","avatar":""},{"name":"Steve Boyum","avatar":""},{"name":"William H. Burton Jr.","avatar":""},{"name":"Henry Kingi","avatar":""},{"name":"Sven-Ole Thorsen","avatar":""},{"name":"Jack Verbois","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Primevil","Alien Hunter","Hunter","O kynigos","Ha-Toref","Rándýrið","Predator 3D","Хищникът","Predator - Jagten er begyndt","Ο Κυνηγός","Prédateur","프레데터","הטורף 1","鐵血戰士","プレデター：1987","プレデター","O Predador","Predator"]', 1784690324547);
