INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-khi-toi-thuong', 'Vũ Khí Tối Thượng', 'Lethal Weapon', 'https://phimimg.com/upload/vod/20251028-1/61d10d75f923f42b20647a7014ed4781.jpg', 'https://phimimg.com/upload/vod/20251028-1/c47ae55af4b237d32b2b2278ee69dc74.jpg', '<p>Phim nói về Murtaugh là một cảnh sát sắp về hưu và có 1 gia đình êm ấm, trong khi đó Riggs là một cảnh sát trẻ có vấn đề về tâm lý sau khi trải qua cú sốc mất vợ. Hai con người với cá tính, tuổi tác và cuộc sống hoàn toàn trái ngược chỉ có duy nhất 1 điểm chung là ghét làm việc theo nhóm nhưng giờ họ phải học cách phối hợp với nhau để đánh bại một tổ chức tội ác buôn lậu ma túy.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Gary Busey","avatar":""},{"name":"Mitchell Ryan","avatar":""},{"name":"Tom Atkins","avatar":""},{"name":"Darlene Love","avatar":""},{"name":"Traci Wolfe","avatar":""},{"name":"Jackie Swanson","avatar":""},{"name":"Damon Hines","avatar":""},{"name":"Ebonie Smith","avatar":""},{"name":"Bill Kalmenson","avatar":""},{"name":"Lycia Naff","avatar":""},{"name":"Patrick Cameron","avatar":""},{"name":"Don Gordon","avatar":""},{"name":"Jimmie F. Skaggs","avatar":""},{"name":"Jason Ronard","avatar":""},{"name":"Blackie Dammett","avatar":""},{"name":"Gail Bowman","avatar":""},{"name":"R","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f58