INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bu-nhin-rom', 'Bù Nhìn Rơm', 'Strawman', 'bù nhìn rơm strawman trác thắng lợi trương bạch châu ngô bính nam văn anh dương quý mỹ kha tuấn hùng lâm mỹ chiếu lý côn anh anh phương long dao cao ren 村と爆弾 稻草人', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-cay-2-1987', 'Ma Cây 2', 'Evil Dead II', 'https://phimimg.com/upload/vod/20250830-1/14fc5055e0c43fd656e7edcdaacdc534.jpg', 'https://phimimg.com/upload/vod/20250830-1/aef9645356f747d5d932806c75de50c8.jpg', '<p>Ash cùng cô bạn gái Linda đến nghỉ mát tại ngôi nhà gỗ trong một khu rừng. Ash vô tình mở lại cuốn băng của vị giáo sư, chủ nhân quá cố của ngôi nhà. Đó chính là câu thần chú từ Quyển sách của người chết (Book of the Dead) giải thoát cho thể lực quỷ dữ trong rừng. Chúng biến Linda trở thành ma (deadite). Khi ấy, Annie, con gái của giáo sư trở về cùng bạn trai và những người dẫn đường. Họ và Ash phải chiến đấu để có thể sống sót. Khi Annie đọc câu thần chú để tống khứ ác quỷ, Ash bị cuốn trở về quá khứ...</p>', 'Full', 1, 'single', 'completed', 12, 1987, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bruce Campbell","avatar":""},{"name":"Sarah Berry","avatar":""},{"name":"Dan Hicks","avatar":""},{"name":"Kassie DePaiva","avatar":""},{"name":"Ted Raimi","avatar":""},{"name":"Denise Bixler","avatar":""},{"name":"Richard Domeier","avatar":""},{"name":"John Peakes","avatar":""},{"name":"Lou Hancock","avatar":""},{"name":"Snowy Winters","avatar":""},{"name":"Sol Abrams","avatar":""},{"name":"Josh Becker","avatar":""},{"name":"Sam Raimi","avatar":""},{"name":"Scott Spiegel","avatar":""},{"name":"Thomas Kidd","avatar":""},{"name":"Mitch Cantor","avatar":""},{"name":"Jenny Griffith","avatar":""},{"name":"William Preston Rober","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2f