INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-thi-tien-sinh-3-linh-huyen-tien-sinh', 'Cương Thi Tiên Sinh 3: Linh Huyễn Tiên Sinh', 'Mr. Vampire III', 'https://phimimg.com/upload/vod/20250603-1/2509b31a9a86e45bfdb00b18228b35da.jpg', 'https://phimimg.com/upload/vod/20250603-1/ff335fdf3fb3b91c46af470a72001c8f.jpg', '<p>Linh Huyễn Tiên Sinh một xác ướp được vận chuyển về kinh thành, trên đường đi nó đã thoát ra được và trở thành cương thi hại người, những người vận chuyển bị giết gần hết. Chỉ còn 2 người thoát được, một trong số đó có một cậu bé bị nhiễm thi độc do cương thi cắn</p>', 'Full', 1, 'single', 'completed', 13, 1987, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Lam Ching-Ying","avatar":""},{"name":"Richard Ng Yiu-Hon","avatar":""},{"name":"Billy Lau Nam-Kwong","avatar":""},{"name":"Pauline Wong Yuk-Wan","avatar":""},{"name":"Chow Gam-Kong","avatar":""},{"name":"Lui Fong","avatar":""},{"name":"Hoh Kin-Wai","avatar":""},{"name":"Cheung Wing-Cheung","avatar":""},{"name":"Ka Lee","avatar":""},{"name":"Baan Yun-Sang","avatar":""},{"name":"Lee Chi-Kit","avatar":""},{"name":"Chu Tau","avatar":""},{"name":"Gam Biu","avatar":""},{"name":"Sammo Hung","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Corey Yuen Kwai","avatar":""},{"name":"Teddy Yip Wing-Cho","avatar":""},{"name":"Tam Yat-","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Mr. Vampire Part 3","Mr. Vampire III","靈幻先生","僵尸先生3","Mr Vampire 3"]', 1784690324547);
