INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuong-thi-tien-sinh-3-linh-huyen-tien-sinh', 'Cương Thi Tiên Sinh 3: Linh Huyễn Tiên Sinh', 'Mr. Vampire III', 'cương thi tiên sinh 3: linh huyễn tiên sinh mr. vampire iii lam ching-ying richard ng yiu-hon billy lau nam-kwong pauline wong yuk-wan chow gam-kong lui fong hoh kin-wai cheung wing-cheung ka lee baan yun-sang lee chi-kit chu tau gam biu sammo hung wu ma corey yuen kwai teddy yip wing-cho tam yat- mr. vampire part 3 mr. vampire iii 靈幻先生 僵尸先生3 mr vampire 3', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-ca-phe-bagdad', 'Quán Cà Phê Bagdad', 'Out of Rosenheim / Bagdad Cafe', 'https://phimimg.com/upload/vod/20250601-1/4337217d18ee0a14f551a4a27524ebc0.jpg', 'https://phimimg.com/upload/vod/20250601-1/3ed10f4e85d54ea379f4e9a8de27d19d.jpg', '<p>&quot;Bagdad Cafe&quot; kể về câu chuyện của Jasmin Münchgstettner, một người phụ nữ người Đức trung niên đến từ Rosenheim, sau khi tranh cãi với chồng trong một chuyến đi xuyên sa mạc Nevada, đã rời bỏ ông ta và bắt đầu hành trình một mình. Cô dừng chân tại một quán cà phê tồi tàn và lạc hậu tên là Bagdad Cafe, nằm giữa sa mạc hoang vắng của Mỹ. Chủ quán là Brenda, một phụ nữ Mỹ da đen, cũng đang gặp khó khăn trong cuộc sống và mối quan hệ gia đình. Ban đầu, mối quan hệ giữa Jasmin và Brenda rất căng thẳng do sự khác biệt về văn hóa, ngôn ngữ và tính cách. Nhưng dần dần, Jasmin – với sự điềm tĩnh, tử tế và một chút phép thuật (cô có tài biểu diễn ảo thuật) – đã giúp biến đổi quán cà phê thành một nơi ấm áp, hấp dẫn, và là trung tâm kết nối cộng đồng. Tình bạn giữa hai người phụ nữ rất khác biệt trở thành điểm sáng của bộ phim.</p>', 'Full', 1, 'single', 'completed', 18, 1987, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Marianne Sägebrecht","avatar":""},{"name":"CCH Pounder","avatar":""},{"name":"Jack Palance","avatar":""},{"name":"Christine Kaufmann","avatar":""},{"name":"Monica Calhoun","avatar":""},{"name":"Darron Flagg","avatar":""},{"name":"George Aguilar","avatar":""},{"name":"G. Smokey Campbell","avatar":""},{"name":"Hans Stadlbauer","avatar":""},{"name":"Alan S. Craig","avatar":""},{"name":"Apesanahkwat","avatar":""},{"name":"Ronald Lee Jarvis","avatar":""},{"name":"Mark Daneri","avatar":""},{"name":"Ray Young","avatar":""},{"name":"Gary Lee Davis","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Καφέ Μπαγκντάτ","バグダッド・カフェ","Out of Rosenheim","Bagdad Cafe","Bagdad Café","甜蜜咖啡屋"]', 1784690324547);
