INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-hiep-si-rong', 'Doraemon: Nobita và Hiệp Sĩ Rồng', 'Doraemon: Nobita and the Knights on Dinosaurs', 'https://phimimg.com/upload/vod/20250521-1/021d708873897910a07b5f5b14561832.jpg', 'https://phimimg.com/upload/vod/20250521-1/a2bfaa664aa1f39050532836266cebbc.jpg', '<p>Nobita và Doraemon đang tìm ra một sự thật về khủng long. Nobita đã nhìn thấy một thứ gì đó dưới đại dương khi họ đi qua một hang động dẫn đến một thế giới dưới lòng đất với đầy rẫy những người khủng long. Nobita và những người bạn của mình vô cùng ngạc nhiên trước phát hiện mới của mình nhưng đáng buồn là ký ức của họ phải bị xóa sạch và phải quay trở lại trái đất.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 1987, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Kazuya Tatekabe","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["龍之騎士","Doraemon Nobita to Ryu no kishi","Nobita and the Knights on Dinosaurs","大雄與恐龍騎士","哆啦A夢：大雄與龍之騎士","โดราเอมอน ตอน เผชิญอัศวินไดโนเสาร์","โดราเอมอน ตอน บุกแดนใต้พิภพ","도라에몽: 노비타와 용의 기사","noibia cuoc phieu luu vao long dat","Doraemon the Movie: डायनासोर योद्धा","Doraemon: Nobita dan Panglima Penunggang Dinosaur","電影哆啦A夢：大雄與恐龍騎士","映画ドラえもん のび太と竜の騎士"]', 1784690324547);
