INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phien-toa-can-chanh-an', 'Phiên Tòa Cần Chánh Án', 'The Court Needs A Chief Justice', 'https://phimimg.com/upload/vod/20250406-1/a25e5089f46b7193e04ada8b22218d7e.jpg', 'https://phimimg.com/upload/vod/20250406-1/edb5f29ccde4e5fb06e63babeef960b3.jpg', '<p>Chồng Quỳnh Mai thường dằn vặt , trách móc cô chỉ lo vinh quang của nghề diễn xuất khi cô không chịu đẻ con và lại hai lần phá thai. Quỳnh Mai ôm đau khổ trong lòng mà không tâm sự cho chồng. Sau này do quá đau khổ nên Quỳnh Mai đã tự kết liễu mình. Khi công an điều tra về cái chết, người chồng mới biết được cô phá thai hai lần do thai nhi bị dị tật vì ảnh hưởng chất độc chiến tranh.</p>', 'Full', 1, 'single', 'completed', 12, 1987, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thụy Hoàng","avatar":""},{"name":"NSND Trần Vịnh","avatar":""},{"name":"Thanh Điền","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324547);
