INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-khong-mang-sung', 'Người Không Mang Súng', 'The One Who Does Not Carry A Gun', 'https://phimimg.com/upload/vod/20250406-1/dae6d142f15015ea357282bc568e2479.jpg', 'https://phimimg.com/upload/vod/20250406-1/b4745eeddf9fa30d1edee56fea244897.jpg', '<p>&quot;Người Không Mang Súng&quot; là một bộ phim chiến tranh Việt Nam xúc động, khai thác một góc nhìn khác về cuộc kháng chiến chống Mỹ - đó là những người không trực tiếp cầm vũ khí, nhưng vẫn đóng góp hết mình vào sự nghiệp giải phóng dân tộc. Phim kể về những người lính thầm lặng, không trực tiếp chiến đấu nhưng đóng vai trò quan trọng trong chiến tranh, như giao liên, vận chuyển lương thực hay cán bộ tuyên truyền. Họ đối mặt với hiểm nguy, sống giữa ranh giới mong manh của sự sống và cái chết. Phim có sự tham gia của Lý Huỳnh, Kim Chi và Thúy An, khắc họa hình ảnh người cách mạng bất khuất, những bà mẹ, cô gái kiên cường đã góp sức vào cuộc đấu tranh của dân tộc.</p>', 'Full', 1, 'single', 'completed', 12, 1987, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lý Huỳnh","avatar":""},{"name":"Kim Chi","avatar":""},{"name":"Thúy An","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324547);
