INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-khong-mang-sung', 'Người Không Mang Súng', 'The One Who Does Not Carry A Gun', 'người không mang súng the one who does not carry a gun lý huỳnh kim chi thúy an 插翅难飞 vol à haut risque flight risk', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-ha-dai-phong-van', 'Hoàng Hà Đại Phong Vân', 'The Grand Canal', 'https://phimimg.com/upload/vod/20250319-1/c386fb3f1541a726da199a4bcdbfba76.jpg', 'https://phimimg.com/upload/vod/20250319-1/e4fd858e99eb96de99daaaa05ae28add.jpg', '<p>Phim kết hợp đặc điểm của thể loại lịch sử diễn nghĩa và võ hiệp, khắc họa quá trình thay đổi triều đại đầy sóng gió, ân oán giữa các nhân vật anh hùng trong thiên hạ thời tao loạn, tạo nên những tình tiết cảm động lòng người, hình thành nên những câu chuyện tình yêu, tình bằng hữu rất đẹp trên màn ảnh. Lúc đó giám chế Lưu Sĩ Du dự định tập họp đầy đủ &quot;Ngũ hổ tướng&quot; nổi tiếng nhất trên màn ảnh nhỏ thập niên 80 để đóng bộ phim này, nhưng cuối cùng chỉ có Lương Triều Vỹ và Huỳnh Nhật Hoa ký tiếp hợp đồng ở lại TVB, thế là ba vai diễn quan trọng khác đều được giao cho các diễn viên mới: Lưu Thanh Vân, Ngô Khải Hoa và Âu Thoại Vỹ. Phía nữ chính cũng là một điểm sáng với sự góp mặt của các hoa đán đang được yêu thích lúc bấy giờ là Trần Ngọc Liên, Tăng Hoa Thiên, diễn viên thực lực Trần Tú Châu, ngoài ra giám chế Lưu Sĩ Du còn giao hai vai diễn nặng ký khác cho Vương Ỷ Cầm và Trịnh Diễm Phụng, vừa đoạt giải quán quân và á quân trong cuộc thi &quot;Người đẹp truyền hình&quot; TVB lần thứ 1 năm 1986. Bên cạnh dàn diễn viên hùng hậu, TVB cũng rất xem trọng phần chế tác, đầu tư chi phí thực hiện 20 triệu HK$, cảnh quay hoành tráng, trang phục hoa lệ… Để đạt được hiệu quả chân thật, hoành tráng, đoàn làm phim còn sang tận tỉnh Tây An, Trung Quốc quay ngoại cảnh. Cứu vãn cơ đồ là bộ phim truyền hình có vốn đầu tư lớn nhất thập niên 80 của TVB. Nội dung kể vào đời vua Tùy Văn Đế, có chàng trai Trương Tam Lang – biệt hiệu Cầu Nhiêm Khách, là một khách giang hồ hành hiệp trượng nghĩa. Ái thiếp Tuyên Hoa phu nhân của Văn Đế là hồng nhan tri kỷ của anh, và tính hào phóng của Cầu Nhiêm Khách trước sau còn được Lan Lăng công chúa, Lý Tương Nhi và Trưởng Tôn Vô Cấu đem lòng yêu mến, từ đó triển khai mối tình duyên phức tạp. Số trời đưa đẩy, anh lần lượt gặp và quen với các vị hào kiệt Lý Tịnh, Hồng Phất Nữ, Lý Thế Dân và Lý Mật, đúng lúc Dương Quảng âm mưu soán ngôi, thi hành chính sách tàn bạo, Cầu Nhiêm Khách cùng quần hùng ra tay cứu lấy dân lành, nhưng không ngờ có người lại vì lợi ích cá nhân mà bất chấp tình nghĩa, từ đó nảy sinh hàng loạt câu chuyện gay cấn, hồi hộp…</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 21, 1987, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Tony Leung","avatar":""},{"name":"Idy Chan Yuk-Lin","avatar":""},{"name":"Felix Wong Yat-Wah","avatar":""},{"name":"Sean Lau Ching-Wan","avatar":""},{"name":"Margie Tsang Wah-Sin","avatar":""},{"name":"Michael Tao Tai-Yu","avatar":""},{"name":"Lawrence Ng Kai-Wah","avatar":""},{"name":"Rebecca Chan","avatar":""},{"name":"Kwan Ching","avatar":""},{"name":"Bao Fang","avatar":""},{"name":"Ng Sai-Mei","avatar":""},{"name":"Jimmy Au Shui-Wai","avatar":""},{"name":"Wong Yee Kam","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Liu Kai-Chi","avatar":""},{"name":"Cheng Yim-Fung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["大運河"]', 1784690324547);
