INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-mat-troi', 'Đế Chế Mặt Trời', 'Empire of the Sun', 'https://phimimg.com/upload/vod/20250314-1/f1ac48e5a9a83fe5a582f8f07840f891.jpg', 'https://phimimg.com/upload/vod/20250314-1/87d0e0a838d0e01a04841af7f913cf61.jpg', '<p>Empire of the Sun dựa trên tiểu thuyết tự truyện của J.G.Ballard được Steven Spielberg đạo diễn thành phim năm 1987. Phim kể về những ngày tháng bươn chải để tồn tại của cậu bé Jim Graham thất lạc cha mẹ, sống trong trại tập trung của quân Nhật tại Thượng Hải trong thế chiến thứ 2. Nhân vật chính chỉ là một cậu bé nhưng bộ phim thì tuyệt vời cho mọi lứa tuổi. - Nominated for 6 Oscars</p>', 'Full', 1, 'single', 'completed', 12, 1987, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Christian Bale","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Miranda Richardson","avatar":""},{"name":"Nigel Havers","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Leslie Phillips","avatar":""},{"name":"Masatô Ibu","avatar":""},{"name":"Emily Richard","avatar":""},{"name":"Rupert Frazer","avatar":""},{"name":"Peter Gale","avatar":""},{"name":"Takatarô Kataoka","avatar":""},{"name":"Ben Stiller","avatar":""},{"name":"David Neidorf","avatar":""},{"name":"Ralph Seymour","avatar":""},{"name":"Robert Stephens","avatar":""},{"name":"Zhai Naishe","avatar":""},{"name":"Guts Ishima","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["L''Empire Du Soleil","Das Reich der Sonne","Solens rike","L''impero del sole","Günəş İmperiyası","Imperium Słońca","Empire of the Sun"]', 1784690324547);
