INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('de-che-mat-troi', 'Đế Chế Mặt Trời', 'Empire of the Sun', 'đế chế mặt trời empire of the sun christian bale john malkovich miranda richardson nigel havers joe pantoliano leslie phillips masatô ibu emily richard rupert frazer peter gale takatarô kataoka ben stiller david neidorf ralph seymour robert stephens zhai naishe guts ishima l''empire du soleil das reich der sonne solens rike l''impero del sole günəş i̇mperiyası imperium słońca empire of the sun', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-ho-da-den', 'Anh Họ Đã Đến', 'My Cousin The Ghost', 'https://phimimg.com/upload/vod/20250306-1/38ee71fae5d63b8692a77d46071dcaac.jpg', 'https://phimimg.com/upload/vod/20250306-1/5aef24bcf31080cdde1db4dc7de813e4.jpg', '<p>Anh họ Big trở về quê từ Vương quốc Anh với mục đích tìm vợ và lập gia đình. Trước đó, anh đã đuổi người bạn nhập cư bất hợp pháp Ma ra khỏi Anh, để lại những mối thù chưa được giải quyết. Tuy nhiên, mọi chuyện trở nên tạm gác sang một bên khi không chỉ một, không hai mà là ba hồn ma cần phải xử lý, trong đó có một hồn ma mà anh họ Big đã phải lòng.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Kenny Bee","avatar":""},{"name":"Richard Ng Yiu-Hon","avatar":""},{"name":"Mang Hoi","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Tai Bo","avatar":""},{"name":"Teddy Yip Wing-Cho","avatar":""},{"name":"James Tien Chun","avatar":""},{"name":"Billy Ching Sau-Yat","avatar":""},{"name":"Tin Ching","avatar":""},{"name":"Sai Gwa-Pau","avatar":""},{"name":"Wong Wan-Sze","avatar":""},{"name":"Lee Chi-Kit","avatar":""},{"name":"Ding Yue","avatar":""},{"name":"Yat Boon-Chai","avatar":""},{"name":"Ng Min-Kan","avatar":""},{"name":"Yip So","avatar":""},{"name":"Chu Tau","avatar":""},{"name":"Yung Yin-Fan","avatar":""},{"name":"Cheng Mang-Ha","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["表哥到"]', 1784690324547);
