INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xom-vang', 'Xóm Vắng', 'Deep Garden', 'https://phimimg.com/upload/vod/20241028-1/5eaedd3721a362b9e416f186aa5560c3.jpg', 'https://phimimg.com/upload/vod/20241028-1/1db2874b99fab8cf56f11c57304dd89a.jpg', '<p>“XÓM VẮNG” nói về chuyện tình đầy éo le và trắc trở của một cô giáo dạy đàn tên là Phương Tư Doanh và một người đàn ông nho nhã hiền hòa nhưng bị mù đôi mắt trong một trận hỏa hoạn kinh hoàng.Tư Doanh là một cô giáo dạy đàn cho một đứa bé tên là Đình Đình, Đình Đình là con gái của Bách Phối Văn, cũng chính là người đàn ông mù kia.Bộ phim chuyển thể từ một tác phẩm của nhà văn Quỳnh Dao và thực sự thành công khi lấy không biết bào nhiêu nước mắt của khán giả xem truyền hình.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 18, 1987, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Leanne Liu","avatar":""},{"name":"Chin Han","avatar":""},{"name":"Mark Lee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["You Can''t Tell Him","Đình Viện Thâm Thâm","庭院深深"]', 1784690324547);
