INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-son-than-tien', 'Linh Sơn Thần Tiễn', 'The Sacred Arrow Of Spirit Mountain', 'https://phimimg.com/upload/vod/20241028-1/e7e68057094c43e3fe558e2cbc40f09e.jpg', 'https://phimimg.com/upload/vod/20241028-1/739b1c399ffafa11f1ca4837c92d75ba.jpg', '<p>Một bộ phim Đài Loan đã từng nổi tiếng vào những năm 1987 và sau đó. Thời mà chưa có truyền thông giải trí mạnh mẽ như bây giờ, phim được chiếu trên các băng đĩa hồi đó. Tuy nhiên nội dung lại hấp dẫn người xem. Phim được cho thành công trong làng giải trí Hoa ngữ thời bấy giờ, tình yêu của một cặp trai gái mà ai cũng phải ganh ghét, nhiều cảnh võ thuật cũng đẹp mắt trong phim sẽ làm cho bạn hồi tưởng về một bộ phim thời xưa.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 19, 1987, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["灵山神箭"]', 1784690324547);
