INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-phu-thuy-thanh-pho-eastwick', 'Những Phù Thủy Thành Phố Eastwick', 'The Witches of Eastwick', 'https://phimimg.com/upload/vod/20231030-1/74e25003f4b5894622c1944bde2daecb.jpg', 'https://phimimg.com/upload/vod/20231030-1/339a327e3d65f233fc75e42317ca40dd.jpg', '<p>Ba người phụ nữ độc thân ở ngôi làng Rhode Island đẹp như tranh vẽ đã đạt được mong ước của mình - với cái giá phải trả - khi một người đàn ông bí ẩn và hào hoa xuất hiện trong cuộc đời họ.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Nicholson","avatar":""},{"name":"Cher","avatar":""},{"name":"Susan Sarandon","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Veronica Cartwright","avatar":""},{"name":"Richard Jenkins","avatar":""},{"name":"Keith Jochim","avatar":""},{"name":"Carel Struycken","avatar":""},{"name":"Helen Lloyd Breed","avatar":""},{"name":"Caroline Struzik","avatar":""},{"name":"Michele Sincavage","avatar":""},{"name":"Carole Ita White","avatar":""},{"name":"Harriet Medin","avatar":""},{"name":"Jane A. Johnston","avatar":""},{"name":"Merrily Horowitz","avatar":""},{"name":"Babb","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324547);
