INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-phu-thuy-thanh-pho-eastwick', 'Những Phù Thủy Thành Phố Eastwick', 'The Witches of Eastwick', 'những phù thủy thành phố eastwick the witches of eastwick jack nicholson cher susan sarandon michelle pfeiffer veronica cartwright richard jenkins keith jochim carel struycken helen lloyd breed caroline struzik michele sincavage carole ita white harriet medin jane a. johnston merrily horowitz babb ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiet-cuong-phan-duong', 'Tiết Cương Phản Đường', 'Destined To Rebe', 'https://phimimg.com/upload/vod/20240623-1/5ba1b33087f36433c9e204c1f5f251ae.jpg', 'https://phimimg.com/upload/vod/20240623-1/00c98d6b862a1086a2c987c65555711e.jpg', '<p><em>Tiết gia vốn được coi là rường cột của Đại Đường, liên tiếp 2 đời Đông chinh Tây phạt, công cán hiển hách. Nhưng trên đời có câu Nhất tướng công thành vạn cốt khô, Tiết Nhơn Quý và Tiết Đinh San qua hai lần nhận lãnh ấn soái mở cuộc chinh đông và chinh tây tuy đem lại bình yên cho xã tắc nhưng quy ra thì cũng tạo ra bao vạn oan hồn oán khí bám theo nhà họ Tiết. Đại Nguyên soái Tây Liêu Dương Phàm, sau khi bị vợ chồng Tiết Đinh San và Phàn Lê Huê giết chết oán khí không dứt đã đầu thai vào thành con trai của hai người. Phàn Lê Huê thấu hiểu thiên cơ biết được con trai ruột của mình Tiết Cương chính là do Dương Phàm đầu thai hòng mong tru diệt nhà họ Tiết. Lê Huê vì muốn trừ diệt tâm ma cho con cắt đi mối nguy cho nhà họ Tiết nào ngờ ý trời đã định khó thể khiên cưỡng cuối cùng bị con trai mình vô tình hại chết. Tiết Cương trong hội hoa đăng, lỡ tay đánh chết con riêng của Thái Hậu Võ Tắc Thiên khiến cho họ Tiết bị tru di tam tộc, còn bản thân phải bôn đào. Nhờ sự giúp đỡ của Quán Chủ Vĩnh Thái, dần dần Tiết Cương đã trừ được tâm ma của mình, đứng lên chiêu binh chống lại Võ Tắc Thiên (lúc này đã lên ngôi hoàng đế) hòng báo thù nhà và chấn hưng Đại Đường...</em></p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 20, 1987, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Lưu Thanh Vân","avatar":""},{"name":"Quan Lễ Kiệt","avatar":""},{"name":"Ngô Trấn Vũ","avatar":""},{"name":"Lưu Mỹ Quyên","avatar":""},{"name":"Thiệu Mỹ Kỳ","avatar":""},{"name":"Tạ Hiền","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324547);
