INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-loi-thoat-1987', 'Không Lối Thoát', 'No Way Out', 'https://phimimg.com/upload/vod/20240804-1/84c51e747e7a3c638199dde217497625.jpg', 'https://phimimg.com/upload/vod/20240804-1/c656e69a7964e888c51a4445a013463c.jpg', '<p>Bộ phim này thuộc thể loại hành động và phiêu lưu, với sự tham gia của Kevin Costner và Gene Hackman. Nội dung phim xoay quanh Tom Farrell, một sĩ quan hải quân bị cuốn vào một vụ án giết người phức tạp liên quan đến một gián điệp KGB.</p>', 'Full', 1, 'single', 'completed', 12, 1987, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Costner","avatar":""},{"name":"Gene Hackman","avatar":""},{"name":"Sean Young","avatar":""},{"name":"Will Patton","avatar":""},{"name":"Howard Duff","avatar":""},{"name":"George Dzundza","avatar":""},{"name":"Jason Bernard","avatar":""},{"name":"Iman","avatar":""},{"name":"Fred Thompson","avatar":""},{"name":"Leon Russom","avatar":""},{"name":"Dennis Burkley","avatar":""},{"name":"Marshall Bell","avatar":""},{"name":"Chris D.","avatar":""},{"name":"Michael Shillo","avatar":""},{"name":"Nicholas Worth","avatar":""},{"name":"Leo Geter","avatar":""},{"name":"Matthew Barry","avatar":""},{"name":"John D''Aquino","avatar":""},{"name":"Pete","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324547);
