INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vuot-nguc-trai-tu-than-1987', 'Vượt Ngục Trại Tử Thần', 'Escape from Sobibor', 'vượt ngục trại tử thần escape from sobibor alan arkin joanna pacula rutger hauer hartmut becker jack shepherd emil wolk simon gregor linal haft jason norman robert gwilym eli nathenson kurt raab eric p. caspar hugo bower klaus grünberg wolfgang bathke henning gissel henry stolow ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bad-taste', 'Bad Taste', 'Bad Taste', 'https://phimimg.com/upload/vod/20240228-1/8577bfd1fe0ef3809af9f00fc203a65e.jpg', 'https://phimimg.com/upload/vod/20240228-1/ab8bb5aaf030857f632da585b368aeb5.jpg', '<p>Một nhóm từ chuỗi cửa hàng thức ăn nhanh liên thiên hà Crumbs Crunchy Delights đáp xuống Trái đất với kế hoạch biến thịt người thành một loại hương vị mới nhất. Sau khi họ quét sạch thị trấn Kaihoro của New Zealand, Cơ quan Điều tra và Quốc phòng Astro (AIaDS) của đất nước này được gọi đến để giải quyết vấn đề. Mọi chuyện trở nên phức tạp do Giles, một nhân viên cứu trợ đến Kaihoro cùng ngày để thu tiền lẻ từ người dân. Anh ta bị người ngoài hành tinh bắt giữ và AIaDS thực hiện một nhiệm vụ giải cứu nhanh chóng trở thành một cuộc tấn công tổng lực vào trụ sở của người ngoài hành tinh.</p>', 'Full', 1, 'single', 'completed', 10, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Terry Potter","avatar":""},{"name":"Pete O''Herne","avatar":""},{"name":"Craig Smith","avatar":""},{"name":"Mike Minett","avatar":""},{"name":"Doug Wren","avatar":""},{"name":"Peter Vere-Jones","avatar":""},{"name":"Ken Hammon","avatar":""},{"name":"Robin Griggs","avatar":""},{"name":"Michael Gooch","avatar":""},{"name":"Peter Gooch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324547);
