INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhuc-bo-doan-2', 'Nhục Bồ Đoàn 2', 'Yu Pui Tsuen 2', 'https://phimimg.com/upload/vod/20240228-1/61839f2aa7d47469e2f87571c57a6635.jpg', 'https://phimimg.com/upload/vod/20240228-1/44928a174769a2974c8dc371102aea75.jpg', '<p>Trước khi Sex And Zen của Michael Mak trở thành bộ phim được yêu thích trong thập niên 90, đã có Yu Pui Tsuen (The Carnal Pray Mat, 1987) của Ho Fan. Nhưng không có bom sex Amy Yip, sự hài hước thô tục hay những mối tình đồng tính nữ, Yu Pui Tsuen phải dựa vào cảnh khỏa thân và tình dục từ dàn diễn viên họ hàng vô danh của mình để cứu vãn tình thế. Khi một chàng trai mơ thấy mình chết đuối sau một đêm đam mê xác thịt, anh ta đã nhờ một nhà sư Phật giáo dịch lại trải nghiệm đó cho anh ta. Nhà sư trả lời rằng giấc mơ là lời cảnh báo không nên quá ham mê thú vui xác thịt, nhưng người đàn ông đã phớt lờ lời khuyên của ông, cưới một trinh nữ và làm tình với cô ấy liên tục. Tuy nhiên, sau nhiều chuyện nóng nảy, người đàn ông bắt đầu nhận ra sự khôn ngoan trong lời cảnh báo của nhà sư.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Cheng Yuen-Man","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324547);
