INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-thien-ha', 'Đại Chiến Thiên Hà', 'Spaceballs', 'https://phimimg.com/upload/vod/20240207-1/e410250028eb91af383390a33f2db438.jpg', 'https://phimimg.com/upload/vod/20240207-1/6c0df2454b0215c9aaff58bd698180df.jpg', '<p>Khi Mũ bảo hiểm bóng tối bất chính ấp ủ kế hoạch cướp Công chúa Vespa và đánh cắp không khí trên hành tinh của cô ấy, Lone Starr, kẻ cho thuê không gian và người bạn đồng hành không biết gì của anh ta bay đến giải cứu. Trên đường đi, họ gặp Yogurt, người đã đặt Lone Starr một cách khôn ngoan trước sức mạnh của The Schwartz. Anh ta có thể làm chủ nó kịp thời để tiết kiệm thời gian không?</p>', 'Full', 1, 'single', 'completed', 9, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Rick Moranis","avatar":""},{"name":"Mel Brooks","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Daphne Zuniga","avatar":""},{"name":"John Candy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324547);
