INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-running-man', 'The Running Man', 'The Running Man', 'https://phimimg.com/upload/vod/20240128-1/e3b8984d14b8a997f14fd3bdbca8a0e8.jpg', 'https://phimimg.com/upload/vod/20240128-1/e1aad3c8f5bbf118843aa19b2e6ae699.jpg', '<p>Ở một nước Mỹ loạn lạc, một cảnh sát bị kết án sai sẽ được tự do khi anh ta buộc phải tham gia vào một chương trình trò chơi truyền hình, nơi những kẻ bị kết án, những kẻ chạy trốn, phải chiến đấu với những kẻ giết người vì sự tự do của họ.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"María Conchita Alonso","avatar":""},{"name":"Yaphet Kotto","avatar":""},{"name":"Jim Brown","avatar":""},{"name":"Jesse Ventura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324547);
