INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-running-man', 'The Running Man', 'The Running Man', 'the running man the running man arnold schwarzenegger maría conchita alonso yaphet kotto jim brown jesse ventura ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-chan-to-va-nha-henderson', 'Quái Vật Chân To Và Nhà Henderson', 'Harry And The Hendersons', 'https://phimimg.com/upload/vod/20240126-1/4f035bffbd93024e49e7e21ef61b2231.jpg', 'https://phimimg.com/upload/vod/20240126-1/ee88c3e64b47b0ec54aa8f6879354141.jpg', '<p>Trên đường trở về nhà sau chuyến săn bắn trong rừng, chiếc xe của gia đình Henderson đã đâm phải một con vật qua đường. Ban đầu mọi người sợ hãi ngỡ rằng đó là người vì nó đi 2 chân sau, nhưng khi kiểm tra thì họ phát hiện đó là một con bigfoot (dã nhân, vượn người). Họ nghĩ nó đã chết và mang xác về hy vọng kiếm ít tiền. Nhưng thực sự nó chưa chết và sống cùng cả nhà. Không như họ nghĩ, Harry (tên bigfoot) là một con vật rất hiền lành và thân thiện. Gia đình Henderson giờ đây phải lo quyền nuôi giữ và tránh khỏi các cặp mắt dòm ngó con vật này.</p>', 'Full', 1, 'single', 'completed', 8, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Lithgow","avatar":""},{"name":"Melinda Dillon","avatar":""},{"name":"Margaret Langrick","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324547);
