INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-nhung-dua-tre', 'Tạm Biệt Những Đứa Trẻ', 'Au Revoir Les Enfants', 'https://phimimg.com/upload/vod/20240121-1/3072f3515e842ea4762b5d571dd707bc.jpg', 'https://phimimg.com/upload/vod/20240121-1/f58fc0f221bd8f16b21c148eff48926e.jpg', '<p>Au revoir les enfants kể một câu chuyện đau lòng về tình bạn và sự mất mát tàn khốc của hai cậu bé sống ở nước Pháp bị Đức quốc xã chiếm đóng. Tại một trường nội trú Công giáo cấp tỉnh, những thanh niên sớm phát triển tận hưởng tình bạn thực sự — cho đến khi một bí mật được tiết lộ. Dựa trên những sự kiện thời thơ ấu của chính nhà văn kiêm đạo diễn Malle, bộ phim là một câu chuyện tinh tế, được quan sát chính xác về lòng dũng cảm, sự hèn nhát và sự thức tỉnh đầy bi kịch.</p>', 'Full', 1, 'single', 'completed', 8, 1987, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Gaspard Manesse","avatar":""},{"name":"Raphael Fejtö","avatar":""},{"name":"Francine Racette","avatar":""},{"name":"Stanislas Carré de Malberg","avatar":""},{"name":"Philippe Morier-Genoud","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324547);
