INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ve-chu-cho-hachiko', 'Câu Chuyện Về Chú Chó Hachiko', 'Hachi-ko', 'https://phimimg.com/upload/vod/20240104-1/a93f0ab29a938b64698db14e478cbd97.jpg', 'https://phimimg.com/upload/vod/20240104-1/0395fe93a1982259d50e2b404cd66bb3.jpg', '<p>Đây là câu chuyện thật về một chú chó tên Hachiko, bức tượng tưởng niệm của chú đã được dựng tại trước ga Shibuya. Bộ phim Hachiko Monogatari sản xuất năm 1987, không hề có yếu tố cường điệu, khoa trương, đã mô tả một cách chân thật nhất cuộc đời, niềm kiêu hãnh và lòng trung thành của chú chó Hachiko. Bộ phim đạt được thành công lớn, tạo tiếng vang cho ngành điện ảnh Nhật lúc bấy giờ. Bộ phim là tiền đề, niềm cảm hứng để các nhà làm phim Hollywood sản xuất lại vào năm 2009 với sự tham gia của tài tử Richard Gere. Hachiko Monogatari xứng đáng là một kiệt tác điện ảnh, một tác phẩm tâm lý mẫu mực.</p>', 'Full', 1, 'single', 'completed', 10, 1987, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tatsuya Nakadai","avatar":""},{"name":"Kaoru Yachigusa","avatar":""},{"name":"Mako Ishino","avatar":""},{"name":"Masumi Harukawa","avatar":""},{"name":"Taiji Tonoyama","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324547);
