INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('project-a-2', 'Project A 2', 'Project A 2', 'https://phimimg.com/upload/vod/20240102-1/24e227a7bf9ea6dcd1035f45fe9beb14.jpg', 'https://phimimg.com/upload/vod/20240102-1/f5c6d6d6d1710204c57f9d8619950062.jpg', '<p>Kế Hoạch A 2 - Phần 2 của series phim hành động Project A do Thành Long đạo diễn tiếp tục xoay quanh nhân vật Mã Như Long. Lần này, anh quay lại với cuộc phiêu lưu mới cùng lực lượng tuần duyên, lần này nhiệm vụ anh tham gia là quét sạch bọn tham nhũng tại địa phương, đồng thời anh cũng bị vướng vào rắc rối với một nhóm những người phiến loạn.</p>', 'Full', 1, 'single', 'completed', 9, 1987, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Michael Chan","avatar":""},{"name":"Rosamund Kwan","avatar":""},{"name":"Bill Tung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324547);
