INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-quyen-ru-chet-nguoi', 'Sự Quyến Rũ Chết Người', 'Fatal Attraction', 'https://phimimg.com/upload/vod/20231219-1/e9bf5658553450d255510d6317a555b5.jpg', 'https://phimimg.com/upload/vod/20231219-1/26ac50658454235a2a9043ff1ece3c62.jpg', '<p>Luật sư Dan Callagher nổi tiếng ở New York có một cuộc hôn nhân hạnh phúc, nhưng anh lại ngoại tình với nữ đồng nghiệp Alex. Đôi tình nhân lén lút này vui vẻ bên nhau trong những ngày cuối tuần khi vợ và con của Dan đi xa. Alex không muốn mối quan hệ của họ chỉ là nhân tình nhân mãi, cô tìm mọi cách để giành Dan về phía mình. Cô gái trẻ này sẽ làm gì để đạt được điều mình muốn?</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Michael Douglas","avatar":""},{"name":"Glenn Close","avatar":""},{"name":"Anne Archer","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324547);
