INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('final-victory', 'Final Victory', 'Final Victory', 'https://phimimg.com/upload/vod/20231219-1/e15c53f70a156df48ee13c5b5a8b553a.jpg', 'https://phimimg.com/upload/vod/20231219-1/9f960438d38b0574b58608072942476a.jpg', '<p>Trước khi vào tù, ông trùm xã hội đen đã nhờ người của mình là A Xiong chăm sóc cho các nhân tình. Cả hai người phụ nữ đều nhầm tưởng A Xiong là bạn trai của người kia. Cô chủ nhỏ tuổi Mimi đem lòng yêu anh. Khi sắp được sếp cho ra mắt, hai vợ chồng quyết định giải quyết một việc ngoài ý muốn.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Eric Tsang","avatar":""},{"name":"Margaret Lee Din-Long","avatar":""},{"name":"Loretta Lee","avatar":""},{"name":"Tsui Hark","avatar":""},{"name":"Hark Tsui","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324547);
