INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('maurice', 'Maurice', 'Maurice', 'https://phimimg.com/upload/vod/20231214-1/080721dd359a114f99c8c767d452bddc.jpg', 'https://phimimg.com/upload/vod/20231214-1/7e1444e02d0b1b0b8e2b8c719cc3f46a.jpg', '<p>Hai trường tiếng Anh Chums thấy mình đang yêu ở Cambridge. Để lấy lại vị trí của mình trong xã hội, Clive đã từ bỏ tình yêu bị cấm đoán, Maurice (phát âm là Morris) và kết hôn. Trong khi ở với Clive và người vợ nông, Anne, Maurice cuối cùng đã phát hiện ra sự lãng mạn trong vòng tay của Alec, người chơi game. Được viết từ nỗi đau cá nhân, đó là E.M. Câu chuyện của Forster về các điều khoản với tình dục trong độ tuổi Edwardian.</p>', 'Full', 1, 'single', 'completed', 8, 1987, 'Vietsub', 'HD', 'Anh', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324547);
