INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuc-ca-la-bamba', 'Khúc Ca La Bamba', 'La Bamba', 'https://phimimg.com/upload/vod/20231211-1/0e8880aed106c721fe5ed7551d6c9c7d.jpg', 'https://phimimg.com/upload/vod/20231211-1/4180dd48cc3d3f5d21041ec696845d72.jpg', '<p>Sinh ra trong nghèo khổ. Định mệnh thành ngôi sao. Cuộc đời như mơ chính là câu giới thiệu cho bộ phim La Bamba (1987). Trong phim này Lou Diamond Phillips hóa thân thành Ritchie Valens, một ca sĩ Rock&amp;Roll trẻ tuổi, một tài năng với tương lai rạng ngời phía trước đột ngột qua đời vì tai nạn máy bay ở tuổi 17.</p>', 'Full', 1, 'single', 'completed', 8, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lou Diamond Phillips","avatar":""},{"name":"Danielle von Zerneck","avatar":""},{"name":"Elizabeth Peña","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324547);
