INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-canh-sat-4', 'Học Viện Cảnh Sát 4', 'Police Academy 4: Citizens On Patrol', 'https://phimimg.com/upload/vod/20231211-1/0f18074c9f5779bf9deda514f9bb1e18.jpg', 'https://phimimg.com/upload/vod/20231211-1/176062bb1607eadadf5ec7098e95248f.jpg', '<p>Bị thuyết phục rằng lực lượng cảnh sát trung thành của ông được làm việc quá sức, và trên tất cả, undersaffed, chỉ huy tóc bạc Eric Lassard xuất hiện với một ý tưởng táo bạo: Tại sao không tuyển dụng dân thường háo hức giúp một tay trong việc nghiền nát tội phạm? Với tâm trí này, công dân đầy tham vọng về chương trình chiến đấu tội phạm tuần tra đến với cuộc sống; Tuy nhiên, đối thủ Arch-Arch của Học viện Cảnh sát (1984) Sao úng (1984), Thuyền trưởng Harris, bị phá hoại về việc phá hoại hoạt động, có động cơ thầm kín. Cán bộ Mahoney có thể, và phần còn lại của đội, nhận được các tân binh thành hình, và nhận được, một lần nữa, Lassard ra khỏi điểm chặt chẽ?</p>', 'Full', 1, 'single', 'completed', 8, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Guttenberg","avatar":""},{"name":"Bubba Smith","avatar":""},{"name":"Michael Winslow","avatar":""},{"name":"David Graf","avatar":""},{"name":"Tim Kazurinsky","avatar":""},{"name":"Sharon Stone","avatar":""},{"name":"Leslie Easterbrook","avatar":""},{"name":"Marion Ramsey","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324547);
