INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-chay-tu-than', 'Trốn Chạy Tử Thần', 'The Running Man', 'https://phimimg.com/upload/vod/20231211-1/60dfdbe88242ba32b67aeedcbc68e4dc.jpg', 'https://phimimg.com/upload/vod/20231211-1/1bd2e0d65de8c8387cd7a015d467d48e.jpg', '<p>Ở một nước Mỹ loạn lạc, một cảnh sát bị kết án sai sẽ được tự do khi anh ta buộc phải tham gia vào một chương trình trò chơi truyền hình, nơi những kẻ bị kết án, những kẻ chạy trốn, phải chiến đấu với những kẻ giết người vì sự tự do của họ.</p>', 'Full', 1, 'single', 'completed', 7, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"María Conchita Alonso","avatar":""},{"name":"Yaphet Kotto","avatar":""},{"name":"Jim Brown","avatar":""},{"name":"Jesse Ventura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324547);
