INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-trang-truy-nu-tu', 'Tinh Trang Truy Nữ Tử', 'Romancing Star', 'https://phimimg.com/upload/vod/20231210-1/96cb1293186fe91059e20e8b42501501.jpg', 'https://phimimg.com/upload/vod/20231210-1/839a5fc685f116d991cae34cfb2f2b66.jpg', '<p>Tinh Trang Truy Nữ Tử - Romancing Star là bộ 3 phim về những chàng trai hiền lành, chất phác, lương thiện, yêu đời và đặc biệt là hám gái, nhất là gái đẹp. Họ là những người lao động phổ thông, vốn là thợ sửa xe ôtô. Duyên phận run rủi khi toàn những bóng hồng nghiêng nước nghiêng thành đi qua đời họ.</p>', 'Full', 1, 'single', 'completed', 8, 1987, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Lưu Gia Linh","avatar":""},{"name":"Lưu Đức Hoa","avatar":""},{"name":"Châu Huệ Mẫn","avatar":""},{"name":"Khưu Thục Trinh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324547);
