INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuc-mung-bigamist', 'Chúc Mừng Bigamist', 'Happy Bigamist', 'null', 'https://phimimg.com/upload/vod/20231208-1/5085a1f7512914edac9353606e895376.jpg', '<p>Nam diễn viên sân khấu A Xin dọn đến sống với bạn gái Baijia sau khi ly hôn. Cuộc sống êm đềm của họ tan vỡ sau khi vợ cũ Huijia của anh phải chuyển về vì kinh doanh thất bại. Baijia sợ rằng họ sẽ quay lại với nhau, vì vậy cô ấy đã để mắt đến Huikang. Trong khi dì của A Xin, người mới từ Mỹ trở về đã nhầm tưởng Baijia là một người giúp việc. A Xin đã cố gắng giới thiệu bạn trai cho Huikang, nhưng không khỏi cảm thấy ghen tị và mắc lỗi trên sân khấu.</p>', 'Full', 1, 'single', 'completed', 6, 1987, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Anthony Chan","avatar":""},{"name":"Anita Mui","avatar":""},{"name":"Pat Ha","avatar":""},{"name":"Patricia Ha","avatar":""},{"name":"Ha Man Chik","avatar":""},{"name":"Kenny Bee","avatar":""},{"name":"Jan To Chung","avatar":""},{"name":"Chun-to Chung","avatar":""},{"name":"Chun To Chung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324547);
