INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-tre-con', 'Vua Trẻ Con', 'King of the Children', 'https://phimimg.com/upload/vod/20231204-1/f1f3c23601f8445493a8054b4b532ffd.jpg', 'https://phimimg.com/upload/vod/20231204-1/5e06660750ce92d67f91f7726a63003c.jpg', '<p>Trong cuộc Cách mạng Văn hóa, một thanh niên thất học đang lao động ở nông thôn thì bất ngờ được phân công dạy ở một trường làng gần đó. Dần dần, anh thấy tự tin khi bỏ sách giáo khoa Maoist và khuyến khích những đứa trẻ hầu như không biết chữ viết về cuộc sống và cảm xúc của chính chúng. Đồng thời, qua hàng loạt cuộc gặp gỡ đẹp như mơ với một chàng chăn bò trẻ tuổi, anh bắt đầu cảm nhận được những khả năng của một cuộc sống vượt ra ngoài khuôn khổ của nền giáo dục truyền thống.</p>', 'Full', 1, 'single', 'completed', 9, 1987, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tạ Viên","avatar":""},{"name":"Dương Học Văn","avatar":""},{"name":"Trần Thiệu Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324547);
