INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-ruc-lua', 'Anh Em Rực Lửa', 'Flaming Brothers', 'null', 'https://phimimg.com/upload/vod/20231204-1/78c8d39003ccc4336a93d137a745bbf2.jpg', '<p>Hai đứa trẻ mồ côi, A Lun và A Tian trở thành đôi bạn thân trên đường phố Macao. Cuối cùng, khi họ tìm đường, A Lun bị truy lùng ở Thái Lan vì đã giết một người đàn ông của một trùm băng đảng. Sau khi gặp người bạn thời thơ ấu Kaxi, A Tian đã yêu cô ấy và cặp đôi đã đính hôn. Điều gì đang chờ đợi hai người đàn ông trẻ tuổi?</p>', 'Full', 1, 'single', 'completed', 8, 1987, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yun-Fat Chow","avatar":""},{"name":"Alan Tang Kwong Wing","avatar":""},{"name":"Pat Ha","avatar":""},{"name":"Patricia Ha","avatar":""},{"name":"Ha Man Chik","avatar":""},{"name":"Emily Chu","avatar":""},{"name":"James Yi Lui","avatar":""},{"name":"Ng Hoi-Tin","avatar":""},{"name":"Zhen Ni","avatar":""},{"name":"Yin Tse","avatar":""},{"name":"Philip Chan","avatar":""},{"name":"Norman Chui","avatar":""},{"name":"Chen Li Pin","avatar":""},{"name":"Zhang Zuo Zhou","avatar":""},{"name":"Chun Wong","avatar":""},{"name":"Yau Fong","avatar":""},{"name":"Eddy Ko","avatar":""},{"name":"Biu Gam","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324547);
