INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cant-buy-me-love', 'Can''t Buy Me Love', 'Can''t Buy Me Love', 'https://phimimg.com/upload/vod/20231129-1/ea1e8da6ede91a4c574c246b137449ce.jpg', 'https://phimimg.com/upload/vod/20231129-1/84968068b6981381091c8f45df21a3ed.jpg', '<p>Học sinh trung học mọt sách Ronald Miller giải cứu hoạt náo viên Cindy Mancini khỏi sự trừng phạt của cha mẹ sau khi cô vô tình làm hỏng quần áo thiết kế riêng của mẹ mình. Ronald đồng ý trả 1.000 đô la cho bộ trang phục với một điều kiện: cô ấy sẽ cư xử như thể họ là một cặp trong cả tháng. Tuy nhiên, ngày tháng trôi qua, Cindy ngày càng yêu mến Ronald, khiến anh trở nên nổi tiếng. Nhưng khi người bạn thân cũ của Ronald bị bỏ lại phía sau, anh ấy nhận ra rằng thành công xã hội không phải là tất cả.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Patrick Dempsey","avatar":""},{"name":"Amanda Peterson","avatar":""},{"name":"Courtney Gains","avatar":""},{"name":"Tina Caspary","avatar":""},{"name":"Seth Green","avatar":""},{"name":"Sharon Farrell","avatar":""},{"name":"Darcy DeMoss","avatar":""},{"name":"Dennis Dugan","avatar":""},{"name":"Cloyce Morrow","avatar":""},{"name":"Devin DeVasquez","avatar":""},{"name":"Eric Bruskotter","avatar":""},{"name":"Gerardo Mejía","avatar":""},{"name":"Cort McCown","avatar":""},{"name":"Ami Dolenz","avatar":""},{"name":"Max Perlich","avatar":""},{"name":"David Schermerhorn","avatar":""},{"name":"Steve Franken","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324547);
