INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-thoai-mua-thu', 'Đồng Thoại Mùa Thu', 'An Autumn''s Tale', 'https://phimimg.com/upload/vod/20231129-1/7cc6ee684542be69466e745e77821ad2.jpg', 'https://phimimg.com/upload/vod/20231129-1/6bf7eed8e3584605c013cddd6c927e6c.jpg', '<p>Lee Kay – người gốc Hong Kong – chuyển đến khu người Hoa ở thành phố New York khi đang học đại học. Khi cô biết được bạn trai đang lừa dối mình, người anh họ đã an ủi cô.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Cherie Chung","avatar":""},{"name":"Danny Chan Bak-Keung","avatar":""},{"name":"Gigi Wong","avatar":""},{"name":"Wu Fu-Sheng","avatar":""},{"name":"Yung-Cho Ching","avatar":""},{"name":"Huang Man","avatar":""},{"name":"Ming-Suen Jeng","avatar":""},{"name":"Brenda Lo","avatar":""},{"name":"George Gerard","avatar":""},{"name":"Ozzy Kid","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324547);
