INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-sac-anh-hung-2', 'Bản Sắc Anh Hùng 2', 'A Better Tomorrow II', 'https://phimimg.com/upload/vod/20231125-1/088fb02d53ff147f8b7229c207e99768.jpg', 'https://phimimg.com/upload/vod/20231125-1/6f269d157b48b857f4111c3a7fc4d6b8.jpg', '<p>Tống Tử Hào được thả sau vài năm ngồi tù, với điều kiện ông phải điều tra thông tin về Long Tứ - một ông trùm tiền giả, bạn cũ của ông, cho cảnh sát. Ban đầu Hào từ chối, nhưng khi biết Kiệt - em trai mình cũng tham gia điều tra thì ông đành nhận lời. Nhưng sau đó lại xảy ra chuyện, con gái của Long Tứ bị ám sát, Long Tứ cũng bị ám sát hụt ở New York. Long Tứ trở nên ngớ ngẩn và mất trí nhớ tạm thời, nhờ có Ken giúp đỡ đưa ông trở về Hongkong. Về Hong Kong, mọi người khám phá ra rằng đứng đằng sau vụ ám sát Long Tứ là Cao, một đối tác cũ của Long.</p>', 'Full', 1, 'single', 'completed', 9, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ti Lung","avatar":""},{"name":"Leslie Cheung","avatar":""},{"name":"Dean Shek","avatar":""},{"name":"Chow Yun-fat","avatar":""},{"name":"Guan Shan","avatar":""},{"name":"Emily Chu Bo-Yee","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Lam Chung","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"Lung Ming-Yan","avatar":""},{"name":"Peter Wang","avatar":""},{"name":"Louis Roth","avatar":""},{"name":"Regina Kent","avatar":""},{"name":"Ken Boyle","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Mike Abbott","avatar":""},{"name":"Mark King","avatar":""},{"name":"Dean Harrington","avatar":""},{"name":"Law Shu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name