INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dieu-hoang-da', 'Vũ Điệu Hoang Dã', 'Dirty Dancing', 'https://phimimg.com/upload/vod/20231125-1/8313593d45075f3fb76bc98405c92955.jpg', 'https://phimimg.com/upload/vod/20231125-1/d724521f0969e4f307cda2661bd684e3.jpg', '<p>Mong đợi sự tẻ nhạt thường thấy đi kèm với một mùa hè ở Catskills cùng gia đình, Frances &quot;Baby&quot; 17 tuổi; Houseman ngạc nhiên khi thấy mình bước vào vị trí của một tay đua chuyên nghiệp — và bất ngờ phải lòng.</p>', 'Full', 1, 'single', 'completed', 10, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jennifer Grey","avatar":""},{"name":"Patrick Swayze","avatar":""},{"name":"Jerry Orbach","avatar":""},{"name":"Cynthia Rhodes","avatar":""},{"name":"Jack Weston","avatar":""},{"name":"Jane Brucker","avatar":""},{"name":"Kelly Bishop","avatar":""},{"name":"Lonny Price","avatar":""},{"name":"Max Cantor","avatar":""},{"name":"Charles ''Honi'' Coles","avatar":""},{"name":"Neal Jones","avatar":""},{"name":"''Cousin Brucie'' Morrow","avatar":""},{"name":"Wayne Knight","avatar":""},{"name":"Paula Trueman","avatar":""},{"name":"Alvin Myerovich","avatar":""},{"name":"Mira","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324547);
