INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sworn-brothers', 'Sworn Brothers', 'Sworn Brothers', 'https://phimimg.com/upload/vod/20231115-1/01b89ecc57e2d81f1bc061946df8e3dc.jpg', 'https://phimimg.com/upload/vod/20231115-1/bc4388e3e3f3ed71425479591a4ed675.jpg', '<p>Uncle Leopard nhận con trai của bạn mình là A Ding, người lớn lên với con trai riêng của mình là A Guo như anh em. A Guo trở thành cảnh sát sau khi tốt nghiệp học viện, trong khi A ding trở thành cánh tay phải của Yang Donghai, kẻ đứng đầu một băng đảng buôn bán vũ khí và buôn bán ma túy. Sau khi biết ý định rời đi của A Ding, Yang biến anh ta trở thành nạn nhân trong cuộc chiến với một băng nhóm đối thủ.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"Peter Yang Kwan","avatar":""},{"name":"Bill Tung","avatar":""},{"name":"Siu Hung-Mui","avatar":""},{"name":"Eddy Ko","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"Fung Yuen-Chi","avatar":""},{"name":"Wong Chi-Keung","avatar":""},{"name":"Pauline Wong Yuk-Wan","avatar":""},{"name":"Ka Lee","avatar":""},{"name":"Shum Lo","avatar":""},{"name":"Lui Tat","avatar":""},{"name":"Kan Tat-Wah","avatar":""},{"name":"Tony Au Ting-Ping","avatar":""},{"name":"Wan Doh-Ming","avatar":""},{"name":"Simon Cheung Yuk-San","avatar":""},{"name":"Cheung Yuen-Wa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324547);
