INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-con-lac-loai', 'Những Đứa Con Lạc Loài', 'The Lost Boys', 'https://phimimg.com/upload/vod/20231115-1/83438bd4d351cdb13545ae0411a106ca.jpg', 'https://phimimg.com/upload/vod/20231115-1/f98e5e81db053318c3ad1839d9172cf5.jpg', '<p>Những Đứa Con Lạc Loài - The Lost Boys: đặc biệt gây chú ý với khẩu hiện trên poster: &quot;Ngủ suốt cả ngày. Tiệc tùng thâu đêm. Không bao giờ già. Không bao giờ chết. Thật là tuyệt khi làm ma cà rồng&quot;. Được thực hiện dưới bàn tay nhào nặn của Joel Schumacher, &quot;The Lost Boys&quot;xoay quanh câu chuyện một nhóm các cậu bé chống lại băng đảng ma cà rồng.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jason Patric","avatar":""},{"name":"Corey Haim","avatar":""},{"name":"Dianne Wiest","avatar":""},{"name":"Barnard Hughes","avatar":""},{"name":"Edward Herrmann","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Jami Gertz","avatar":""},{"name":"Corey Feldman","avatar":""},{"name":"Jamison Newlander","avatar":""},{"name":"Brooke McCarter","avatar":""},{"name":"Billy Wirth","avatar":""},{"name":"Alex Winter","avatar":""},{"name":"Chance Michael Corbitt","avatar":""},{"name":"Alexander Bacan Chapman","avatar":""},{"name":"Nori Morgan","avatar":""},{"name":"Kelly Jo Min","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324547);
