INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-ca-map-bao-thu', 'Hàm Cá Mập: Báo Thù', 'Jaws: The Revenge', 'https://phimimg.com/upload/vod/20231113-1/95f5eb8fd51fc72905a71eda11eb4e88.jpg', 'https://phimimg.com/upload/vod/20231113-1/30696893274c8069bace77f370a1632c.jpg', '<p>Sau một cuộc tấn công chết người khác của cá mập, Ellen Brody quyết định rằng cô đã chán đảo Amity của New England và chuyển đến vùng biển Caribe để đoàn tụ với con trai cô, Michael và gia đình anh. Nhưng một con cá mập trắng lớn đã theo cô đến đó, thèm khát nhiều mạng sống hơn.</p>', 'Full', 1, 'single', 'completed', 12, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lorraine Gary","avatar":""},{"name":"Lance Guest","avatar":""},{"name":"Mario Van Peebles","avatar":""},{"name":"Michael Caine","avatar":""},{"name":"Karen Young","avatar":""},{"name":"Judith Barsi","avatar":""},{"name":"Lynn Whitfield","avatar":""},{"name":"Mitchell Anderson","avatar":""},{"name":"Jay Mello","avatar":""},{"name":"Cedric Scott","avatar":""},{"name":"Charles Bowleg","avatar":""},{"name":"Mary Smith","avatar":""},{"name":"Edna Billotto","avatar":""},{"name":"Fritzi Jane Courtney","avatar":""},{"name":"Melvin Van Peebles","avatar":""},{"name":"Cyprian R. Dube","avatar":""},{"name":"Lee","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324547);
