INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-quy-du-1987', 'Linh Hồn Quỷ Dữ', 'Angel Heart', 'https://phimimg.com/upload/vod/20231111-1/2a5815f22e06fdb705ee046479d63de7.jpg', 'https://phimimg.com/upload/vod/20231111-1/50f752767b3538463c39477790e2ced4.jpg', '<p>Thám tử tư Harry Angel được một người đàn ông giàu có bí ẩn, tên là Louis Cyphre, thuê đi tìm một nhạc công &quot;mắc nợ&quot; với ông ta có tên là Johnny Favorite. Tưởng chừng như công việc vô cùng đơn giản, Angel tìm tới những người từng biết Johnny để truy tìm. Nhưng những người mà Angel gặp, lần lượt bị sát hại một cách dã man. Angel từ từ phát hiện ra một âm mưu kinh khủng liên quan đến tà thuật. Johnny Favorite là ai? Tại sao Louise Cyphre muốn tìm cho bằng được hắn?</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mickey Rourke","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Lisa Bonet","avatar":""},{"name":"Charlotte Rampling","avatar":""},{"name":"Stocker Fontelieu","avatar":""},{"name":"Brownie McGhee","avatar":""},{"name":"Michael Higgins","avatar":""},{"name":"Elizabeth Whitcraft","avatar":""},{"name":"Eliott Keener","avatar":""},{"name":"Charles Gordone","avatar":""},{"name":"Dann Florek","avatar":""},{"name":"Kathleen Wilhoite","avatar":""},{"name":"George Buck","avatar":""},{"name":"Judith Drake","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Dave Pe","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324547);
