INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-84-duong-charing-cross', 'Số 84 Đường Charing Cross', '84 Charing Cross Road', 'https://phimimg.com/upload/vod/20231109-1/50655dc3abb739b96b8f98ceedd3d2ad.jpg', 'https://phimimg.com/upload/vod/20231109-1/0fd9c1d783c2f3561bbedf1d97c96bd9.jpg', '<p>Nhà văn New York nhiệt huyết Helene gửi bức thư ngắn đến cửa hàng sách nhỏ ở London và tạo nên câu chuyện thư tín cảm động và hài hước với người bán sách dè dặt Frank.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Anne Bancroft","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Judi Dench","avatar":""},{"name":"Jean De Baer","avatar":""},{"name":"Maurice Denham","avatar":""},{"name":"Eleanor David","avatar":""},{"name":"Mercedes Ruehl","avatar":""},{"name":"Daniel Gerroll","avatar":""},{"name":"Wendy Morgan","avatar":""},{"name":"Ian McNeice","avatar":""},{"name":"Connie Booth","avatar":""},{"name":"J. Smith-Cameron","avatar":""},{"name":"Tom Isbell","avatar":""},{"name":"Anne Dyson","avatar":""},{"name":"Ronn Carroll","avatar":""},{"name":"Sam Stoneburner","avatar":""},{"name":"Charles Lewsen","avatar":""},{"name":"Bern","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324547);
