INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-beverly-hills-2', 'Cảnh Sát Beverly Hills 2', 'Beverly Hills Cop II', 'https://phimimg.com/upload/vod/20231109-1/5a7b45760794d85e90f766a41e6d2685.jpg', 'https://phimimg.com/upload/vod/20231109-1/48177e601286615fa40b8e3bdfc77917.jpg', '<p>&quot;Axel Foley (Murphy) một lần nữa lại dấn thân vào nơi nguy hiểm. Lần này anh ta sẽ tiến sâu vào miền hoang dã Nam California đầy nắng và cây cọ để truy tìm kẻ đã bắn chết đội trưởng Andrew Bogomil. tiến sâu vào , nơi mà anh thể hiện các màn đấu súng nghẹt thở với băng đảng buôn lậu vũ khí quốc tế. Tiếp tục đồng hành trong cuộc hành trình vẫn là 2 trợ tá Judge Reinhold và John Ashton. Và lần này, đạo diễn Tony Scott của Top Gun vẫn mang đến cho người xem những tiếp tấu nhanh, vui nhộn và nghẹt thở...&quot;</p>', 'Full', 1, 'single', 'completed', 12, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Judge Reinhold","avatar":""},{"name":"John Ashton","avatar":""},{"name":"Jürgen Prochnow","avatar":""},{"name":"Brigitte Nielsen","avatar":""},{"name":"Allen Garfield","avatar":""},{"name":"Brian O''Connor","avatar":""},{"name":"Ronny Cox","avatar":""},{"name":"Dean Stockwell","avatar":""},{"name":"Paul Reiser","avatar":""},{"name":"Gilbert R. Hill","avatar":""},{"name":"Paul Guilfoyle","avatar":""},{"name":"Robert Ridgely","avatar":""},{"name":"Alice Adair","avatar":""},{"name":"Eugene Butler","avatar":""},{"name":"Glenn Withrow","avatar":""},{"name":"Stephen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324547);
