INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-de-cuoi-cung', 'Hoàng Đế Cuối Cùng', 'The Last Emperor', 'https://phimimg.com/upload/vod/20231109-1/3d2303089e835525ace091dad89b64a9.jpg', 'https://phimimg.com/upload/vod/20231109-1/d90b76338e5f7ed5973a0d0d710412dc.jpg', '<p>Bernardo Bertolucci là đạo diễn người Ý, ảnh hưởng của Trào lưu Tân hiện thực quá mạnh mẽ nên phim của Bertolucci cũng mang hơi hướng đặc tính của lối làm phim thuộc Trào lưu này. Ông sử dụng nhiều cảnh đặc tả, góc máy đuổi bắt hoặc đón sẵn chờ nhân vật trung tâm xuất hiện. Không tô vẽ hào quang, cốt cách cho nhân vật mà để cho mọi sự tự nhiên được diễn ra... Bộ phim đã giành tổng cộng 9 giải Oscar, bao gồm cả giải Phim hay nhất và Đạo diễn xuất sắc nhất. Đây là một bộ phim hi hữu khi giành chiến thắng ở tất cả 9 hạng mục mà nó được đề cử. Đồng thời phim cũng đoạt giải BAFTA Phim hay nhất và Quả cầu Vàng ở hạng mục Phim chính kịch xuất sắc nhất.</p>', 'Full', 1, 'single', 'completed', 18, 1987, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"John Lone","avatar":""},{"name":"Joan Chen","avatar":""},{"name":"Peter O''Toole","avatar":""},{"name":"Ruocheng Ying","avatar":""},{"name":"Victor Wong","avatar":""},{"name":"Dennis Dun","avatar":""},{"name":"Ryuichi Sakamoto","avatar":""},{"name":"Maggie Han","avatar":""},{"name":"Ric Young","avatar":""},{"name":"Vivian Wu","avatar":""},{"name":"Cary-Hiroyuki Tagawa","avatar":""},{"name":"Jade Go","avatar":""},{"name":"Fumihiko Ikeda","avatar":""},{"name":"Richard Vuu","avatar":""},{"name":"Tsou Tijger","avatar":""},{"name":"Tao Wu","avatar":""},{"name":"Guang Fan","avatar":""},{"name":"Henry Kyi","avatar":""},{"name":"Alvin Riley III","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324547);
