INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('may-bay-xe-lua-va-xa-hoi', 'Máy Bay, Xe Lửa, và Xa Hơi', 'Planes, Trains and Automobiles', 'https://phimimg.com/upload/vod/20231108-1/d4593c0dad2c86b5298e13f38116a7df.jpg', 'https://phimimg.com/upload/vod/20231108-1/4348c7500c601b7f0cac20f46b1ce82a.jpg', '<p>Một giám đốc tiếp thị cáu kỉnh, Neal Page, đang trên đường về nhà ở Chicago để dự Lễ Tạ ơn khi một số sự chậm trễ buộc anh ta phải đi du lịch với một nhân viên bán rèm vòng tắm có ý tốt nhưng hống hách, Del Griffith.</p>', 'Full', 1, 'single', 'completed', 14, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Steve Martin","avatar":""},{"name":"John Candy","avatar":""},{"name":"Laila Robins","avatar":""},{"name":"Michael McKean","avatar":""},{"name":"Dylan Baker","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Olivia Burnette","avatar":""},{"name":"Carol Bruce","avatar":""},{"name":"Diana Douglas","avatar":""},{"name":"Martin Ferrero","avatar":""},{"name":"Larry Hankin","avatar":""},{"name":"Richard Herd","avatar":""},{"name":"Susan Kellermann","avatar":""},{"name":"Matthew Lawrence","avatar":""},{"name":"Edie McClurg","avatar":""},{"name":"Susan Isaacs","avatar":""},{"name":"John Randolph Jones","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324547);
