INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuong-trinh-kinh-di-2', 'Chương Trình Kinh Dị 2', 'Creepshow 2', 'https://phimimg.com/upload/vod/20231103-1/4b8d521432a3b9a423324ad4442bb693.jpg', 'https://phimimg.com/upload/vod/20231103-1/768b57eaebaa774b5782d2fdd55a6f66.jpg', '<p>Sự kỳ lạ lấy cảm hứng từ EC Comics trở lại với ba câu chuyện. Đầu tiên, một bức tượng gỗ của một người Mỹ bản địa trở nên sống động để trả thù chính xác kẻ đã giết những người chủ lớn tuổi của mình. Trong phần thứ hai, bốn thiếu niên bị mắc kẹt trên một chiếc bè trên hồ với một đốm màu đang đói. Và trong phần ba, một người phụ nữ chạy trốn bị khủng bố bởi người quá giang mà cô ấy vô tình giết chết... hay cô ấy đã làm vậy?</p>', 'Full', 1, 'single', 'completed', 12, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lois Chiles","avatar":""},{"name":"George Kennedy","avatar":""},{"name":"Dorothy Lamour","avatar":""},{"name":"Daniel Beer","avatar":""},{"name":"Jeremy Green","avatar":""},{"name":"Page Hannah","avatar":""},{"name":"Don Harvey","avatar":""},{"name":"David Holbrook","avatar":""},{"name":"Stephen King","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Frank Salsedo","avatar":""},{"name":"Paul Satterfield","avatar":""},{"name":"Tom Wright","avatar":""},{"name":"Tom Savini","avatar":""},{"name":"Domenick John","avatar":""},{"name":"Philip Dore","avatar":""},{"name":"Maltby Napoleon","avatar":""},{"name":"Tyrone Ton","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324547);
