INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chao-buoi-sang-viet-nam', 'Chào Buổi Sáng, Việt Nam', 'Good Morning, Vietnam', 'https://phimimg.com/upload/vod/20231031-1/31093539a247e1464e807e7b7b024bd5.jpg', 'https://phimimg.com/upload/vod/20231031-1/1889d45ed42f28196963e575ff8c38a0.jpg', '<p>Người đàn ông hài hước của đài phát thanh Adrian Cronauer được cử đến Việt Nam để mang một chút hài hước trở lại cuộc sống của những người lính. Sau khi thành lập cửa hàng, Cronauer làm say mê các G.I. nhưng đã khiến sĩ quan cấp trên của anh ta, Trung sĩ Thiếu tá Dickerson, bị sốc vì hành động bất kính của anh ta trong cuộc chiến. Trong khi Dickerson cố gắng kiểm duyệt các chương trình phát sóng của Cronauer, Cronauer theo đuổi mối quan hệ với một cô gái Việt Nam tên Trinh, người đã cho anh ta thấy sự khủng khiếp của chiến tranh.</p>', 'Full', 1, 'single', 'completed', 17, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Trần Thanh Tùng","avatar":""},{"name":"Chintara Sukapatana","avatar":""},{"name":"Bruno Kirby","avatar":""},{"name":"Robert Wuhl","avatar":""},{"name":"J.T. Walsh","avatar":""},{"name":"Noble Willingham","avatar":""},{"name":"Richard Edson","avatar":""},{"name":"Juney Smith","avatar":""},{"name":"Richard Portnow","avatar":""},{"name":"Floyd Vivino","avatar":""},{"name":"Cu Ba Nguyen","avatar":""},{"name":"Dan Stanton","avatar":""},{"name":"Don Stanton","avatar":""},{"name":"Danny Aiello III","avatar":""},{"name":"James McInt","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f