INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-cong-chua', 'Cô Dâu Công Chúa', 'The Princess Bride', 'https://phimimg.com/upload/vod/20231031-1/a425db6e4b886cc274f7dcd2985c5764.jpg', 'https://phimimg.com/upload/vod/20231031-1/1df95db0839b26f0086a0b0a9fea0ad2.jpg', '<p>The Princess Bride là câu chuyện cổ tích về nàng Buttercup và chàng nông dân Westley. Nàng Buttercup, giống như bao thiếu nữ mới lớn khác, tính tình đỏng đảnh thích hạnh hoẹ anh chàng nhà quê Westley chăn ngựa. Nói chung mỗi lần hạnh hoẹ được Westley là nàng sướng vô cùng, nhưng tới một ngày kia, nàng chợt nhận ra là mình phải lòng chàng, và mỗi lần nàng hạnh hoẹ chàng thì chàng cũng sung sướng không kém. Tuy nhiên, chàng thì nghèo, không có tiền, mà không thể lãng mạn theo cách một mái nhà tranh hai trái tìm vàng được, nên quyết tâm ra đi tìm đường kiếm tiền để quay về cưới vợ. Trước khi đi chàng cố vớt vát dặn dò nàng hãy đợi anh về, rằng tình yêu đích thực thì không bao giờ chết. Nhưng mà số phận thì nghiệt ngã, chàng đi chẳng được ...</p>', 'Full', 1, 'single', 'completed', 14, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Cary Elwes","avatar":""},{"name":"Robin Wright","avatar":""},{"name":"Mandy Patinkin","avatar":""},{"name":"Chris Sarandon","avatar":""},{"name":"André Roussimoff","avatar":""},{"name":"Christopher Guest","avatar":""},{"name":"Wallace Shawn","avatar":""},{"name":"Peter Falk","avatar":""},{"name":"Fred Savage","avatar":""},{"name":"Billy Crystal","avatar":""},{"name":"Carol Kane","avatar":""},{"name":"Mel Smith","avatar":""},{"name":"Peter Cook","avatar":""},{"name":"Margery Mason","avatar":""},{"name":"Willy DeVille","avatar":""},{"name":"Mark Knopfler","avatar":""},{"name":"Guy Fletcher","avatar":""},{"name":"Willoughby","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324547);
