INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-dinh-1987', 'Ma Đinh', 'Hellraiser', 'https://phimimg.com/upload/vod/20231030-1/209f362cac6f9422b9a0e39430ec261d.jpg', 'https://phimimg.com/upload/vod/20231030-1/c7cd213ab0edcac2e79145c1ceae0549.jpg', '<p>Sau khi mày mò chiếc hộp anh mua khi ở nước ngoài, Frank lệch lạc tình dục đã vô tình mở ra một cánh cổng dẫn đến địa ngục, nơi những con quỷ tôn sùng do Pinhead cầm đầu xé nát cơ thể anh. Khi anh trai của Frank và vợ anh ta chuyển đến nhà anh ta, một bộ xương Frank xuất hiện với chị dâu của anh ta và yêu cầu cô cung cấp xác chết cho anh ta để anh ta tái sinh.</p>', 'Full', 1, 'single', 'completed', 12, 1987, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Clare Higgins","avatar":""},{"name":"Ashley Laurence","avatar":""},{"name":"Sean Chapman","avatar":""},{"name":"Oliver Smith","avatar":""},{"name":"Andrew Robinson","avatar":""},{"name":"Robert Hines","avatar":""},{"name":"Doug Bradley","avatar":""},{"name":"Grace Kirby","avatar":""},{"name":"Nicholas Vince","avatar":""},{"name":"Simon Bamford","avatar":""},{"name":"Anthony Allen","avatar":""},{"name":"Leon Davis","avatar":""},{"name":"Michael Cassidy","avatar":""},{"name":"Frank Baker","avatar":""},{"name":"Kenneth Nelson","avatar":""},{"name":"Gay Baynes","avatar":""},{"name":"Niall Buggy","avatar":""},{"name":"Dave Atk","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324547);
