INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-giap-sat', 'Áo Giáp Sắt', 'Full Metal Jacket', 'https://phimimg.com/upload/vod/20231021-1/469e4d4ac8510fefc4a1fc2da154fb48.jpg', 'https://phimimg.com/upload/vod/20231021-1/2ccb094d69ef0741f91ecaaa715228e0.jpg', '<p>Áo Giáp Sắt - Full Metal Jacket (1987) Full Metal Jacket là bộ phim có cách nhìn khác biệt hẳn so với tất cả những bộ phim về cuộc chiến Việt Nam. Trong khi hầu hết chọn những cánh rừng rậm nhiệt đới làm trung tâm của câu chuyện thì Full Metal Jacket lại đưa chiến sự khốc liệt đi thẳng vào đô thị miền Nam Việt Nam.</p>', 'Full', 1, 'single', 'completed', 19, 1987, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Matthew Modine","avatar":""},{"name":"Adam Baldwin","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"R. Lee Ermey","avatar":""},{"name":"Dorian Harewood","avatar":""},{"name":"Arliss Howard","avatar":""},{"name":"Kevyn Major Howard","avatar":""},{"name":"Ed O''Ross","avatar":""},{"name":"John Terry","avatar":""},{"name":"Bruce Boa","avatar":""},{"name":"Kieron Jecchinis","avatar":""},{"name":"Jon Stafford","avatar":""},{"name":"Tim Colceri","avatar":""},{"name":"Peter Edmund","avatar":""},{"name":"Kirk Taylor","avatar":""},{"name":"Ian Tyler","avatar":""},{"name":"Gary Landon M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324547);
