INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pho-wall', 'Phố Wall', 'Wall Street', 'https://phimimg.com/upload/vod/20231016-1/79cf46b9d3ac16878579fb5a7bbb61f6.jpg', 'https://phimimg.com/upload/vod/20231016-1/76f5567cd2861b7bc92b0584c1d66d60.jpg', '<p>Một nhà môi giới chứng khoán trẻ và thiếu kiên nhẫn sẵn sàng làm bất cứ điều gì để đạt đến đỉnh cao, bao gồm cả giao dịch dựa trên thông tin nội bộ bất hợp pháp được lấy từ một kẻ đột kích công ty tàn nhẫn và tham lam, người đã bảo vệ giới trẻ.</p>', 'Full', 1, 'single', 'completed', 12, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Charlie Sheen","avatar":""},{"name":"Michael Douglas","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Daryl Hannah","avatar":""},{"name":"John C. McGinley","avatar":""},{"name":"Hal Holbrook","avatar":""},{"name":"Sean Young","avatar":""},{"name":"Terence Stamp","avatar":""},{"name":"James Spader","avatar":""},{"name":"Chuck Pfeiffer","avatar":""},{"name":"Lauren Tom","avatar":""},{"name":"Tamara Tunie","avatar":""},{"name":"Franklin Cover","avatar":""},{"name":"James Karen","avatar":""},{"name":"Saul Rubinek","avatar":""},{"name":"Leslie Lyles","avatar":""},{"name":"Faith Geer","avatar":""},{"name":"Frank Adoni","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324547);
