INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('pho-wall', 'Phố Wall', 'Wall Street', 'phố wall wall street charlie sheen michael douglas martin sheen daryl hannah john c. mcginley hal holbrook sean young terence stamp james spader chuck pfeiffer lauren tom tamara tunie franklin cover james karen saul rubinek leslie lyles faith geer frank adoni ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-the-mua-chuoc', 'Không Thể Mua Chuộc', 'The Untouchables', 'https://phimimg.com/upload/vod/20231016-1/48f678762780dbd911c8855d1a905bab.jpg', 'https://phimimg.com/upload/vod/20231016-1/429ede23079663dcbf5348570a276c0b.jpg', '<p>Nội dung phim lấy bối cảnh thành phố Chicago đầu thế kỉ 20, khi tội phạm đầy rẫy ngoài đường và những băng nhóm xã hội đen mặc sức tung hoành. Al Capone – kẻ đứng đầu thế giới ngầm đã tạo nên một thế lực bất khả xâm phạm, nhưng vỏ quýt dày có móng tay nhọn. Chính phủ Liên bang Mỹ đã đích thân tuyển chọn và lập ra một đội cảnh sát thông minh dũng cảm và không bao giờ có thể mua chuộc được họ. Chuyện phim xoay quanh cuộc chiến đẫm máu của nhóm cảnh sát này với những tên tội phạm nguy hiểm.</p><p>Phim có góc nhìn rộng về cuộc chiến trong thế giới tội phạm vào những năm 1920, cùng với đó là nhiều tiếng cười và âm nhạc hoành tráng tạo dấu ấn sâu sắc cho khán giả. Nhiều ý kiến cho rằng, không phải Scarface mà chính The Untouchables mới là phim tội phạm xuất sắc nhất của Palma. Phim đã trở thành một trong những “bom tấn” của thập niên 80 và cũng là phim về mafia xuất sắc của giai đoạn này.</p>', 'Full', 1, 'single', 'completed', 23, 1987, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Costner","avatar":""},{"name":"Sean Connery","avatar":""},{"name":"Charles Martin Smith","avatar":""},{"name":"Andy García","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Richard Bradford","avatar":""},{"name":"Jack Kehoe","avatar":""},{"name":"Brad Sullivan","avatar":""},{"name":"Billy Drago","avatar":""},{"name":"Patricia Clarkson","avatar":""},{"name":"Vito D''Ambrosio","avatar":""},{"name":"Steven Goldstein","avatar":""},{"name":"Peter Aylward","avatar":""},{"name":"Don Harvey","avatar":""},{"name":"Robert Swan","avatar":""},{"name":"John J. Walsh","avatar":""},{"name":"Del","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324547);
