INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-anh-sang-ban-ngay', 'Điệp Viên 007: Ánh Sáng Ban Ngày', 'The Living Daylights', 'https://phimimg.com/upload/vod/20231016-1/36a1592d1c7ec3bb26120436d0959908.jpg', 'https://phimimg.com/upload/vod/20231016-1/64b8450d033e9407e0b0d82ead3da35f.jpg', '<p>Sau khi Bond giúp đỡ sĩ quan người Nga Georgi Koskov (Jeroen Krabbe) ly khai khỏi quân ngũ Koskov lại một lần nữa bị bắt cóc khỏi nơi ẩn náu. Hành trình giải cứu của Bond lần này lại đụng độ với cô gái tuyệt đẹp có tên Kara. Ngay lập tức, Bond đã phải lòng cô gái này và họ đã cùng sát cánh bên nhau để tháo gỡ mớ dây đằng sau các vụ việc bí ẩn này...</p>', 'Full', 1, 'single', 'completed', 16, 1987, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Timothy Dalton","avatar":""},{"name":"Maryam d''Abo","avatar":""},{"name":"Joe Don Baker","avatar":""},{"name":"Art Malik","avatar":""},{"name":"John Rhys-Davies","avatar":""},{"name":"Jeroen Krabbé","avatar":""},{"name":"Andreas Wisniewski","avatar":""},{"name":"Thomas Wheatley","avatar":""},{"name":"Desmond Llewelyn","avatar":""},{"name":"Robert Brown","avatar":""},{"name":"Geoffrey Keen","avatar":""},{"name":"Walter Gotell","avatar":""},{"name":"Caroline Bliss","avatar":""},{"name":"John Terry","avatar":""},{"name":"Virginia Hey","avatar":""},{"name":"John Bowe","avatar":""},{"name":"Julie T.","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324547);
