INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-ban-khong-noi-nen-loi', 'Diệp Bân không nói nên lời', 'Code of Honour', 'null', 'https://phimimg.com/upload/vod/20231013-1/056a61a59dd82aeb1269001a32a63ad5.jpg', '<p><span style="color: rgb(17, 17, 17); font-family: Helvetica, Arial, sans-serif; font-size: 13px; text-wrap: wrap; background-color: rgb(255, 255, 255);">He Zhendong, người đã đi ra khỏi cánh cửa bị đánh, suýt bị giết trong một cuộc tấn công ở Việt Nam, nhưng may mắn thay, Wang Yiyong đã cứu anh ta, và hai người trở nên bất khả chiến bại. Sau khi Hồ Thành trở nên rất giàu có, anh ta muốn đi theo con đường đúng đắn, nhưng các trợ lý của anh ta là Lý Bưu, Nippon Tsai và chú Bao không kiểm soát được, bí mật mở rộng quyền lực và hợp tác để bán ma túy, và thanh tra cảnh sát theo dõi anh ta cả ngày lẫn đêm, muốn đưa He ra trước công lý. Không lâu sau, chứng cứ của ba người rơi vào tay Mai, và He đã bị sốc bởi thực tế rằng anh ta là một nhân chứng bị nhiễm độc và đồng ý tham gia tố tụng. Wang đã giết chết ba người một mình, bị thương nặng và được thả mà không có nhân chứng. Khi Wang rời Hồng Kông, anh ta bị bao vây bởi một số lượng lớn cảnh sát.</span></p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Lin Wei","avatar":""},{"name":"Ke Junxiong","avatar":""},{"name":"Fang Gang","avatar":""},{"name":"Cheng Kuian","avatar":""},{"name":"Shen Wei","avatar":""},{"name":"Devi","avatar":""},{"name":"Châu Nhuận Phát béo","avatar":""},{"name":"Lee Xiuxian","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324547);
