INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nu-u-hon', 'Thiện Nữ U Hồn', 'A Chinese Ghost Story', 'https://phimimg.com/upload/vod/20231012-1/30ce704fe0fdd6b2e066efa3a729a344.jpg', 'https://phimimg.com/upload/vod/20231012-1/077704b39b2522d34a1957bda76f9a93.jpg', '<p>Hồ ly Tiểu Thiện vì mong ước được đầu thai thành người mà trở thành nỗi khiếp sợ của hàng ngàn người. Còn chàng thư sinh Ninh Thái Thần với tình yêu đầu đời dành cho người con gái tuyệt thế giai nhân mà sẵn sàng hy sinh mạng sống. Một chuyện tình tay ba đẫm nước mắt nhưng cũng tràn ngập hạnh phúc...</p>', 'Full', 1, 'single', 'completed', 13, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Leslie Cheung","avatar":""},{"name":"Joey Wong","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"David Lam Wai","avatar":""},{"name":"Sit Chi-Lun","avatar":""},{"name":"David Wu","avatar":""},{"name":"Wong Jing","avatar":""},{"name":"Chiang Kam","avatar":""},{"name":"Huang Ha","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324547);
