INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yen-chi-khau', 'Yên Chi Khâu', 'Rouge', 'null', 'https://phimimg.com/upload/vod/20231011-1/082ecf6c6b15f06e2b986ca65b3cc52f.jpg', '<p>Hồn ma của một kỹ nữ qua đời năm 1934 trở lại Hồng Kông 53 năm sau, tìm cách đoàn tụ với người đàn ông cô yêu.</p>', 'Full', 1, 'single', 'completed', 18, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Anita Mui","avatar":""},{"name":"Leslie Cheung","avatar":""},{"name":"Alex Man","avatar":""},{"name":"Emily Chu Bo-Yee","avatar":""},{"name":"Irene Wan","avatar":""},{"name":"Tam Sin-Hung","avatar":""},{"name":"Chu Shui-Tong","avatar":""},{"name":"Wong Yu","avatar":""},{"name":"Lau Kar-Wing","avatar":""},{"name":"Kara Hui Ying-Hung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324547);
