INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-tan-nuong', 'Quỷ Tân Nương', 'Spiritual Love', 'https://phimimg.com/upload/vod/20231010-1/743a4ba7fd9a1b60ab49596ed9b50c73.jpg', 'https://phimimg.com/upload/vod/20231010-1/19854c474accaaead3289ed3875bc4e3.jpg', '<p>Một người đàn ông tên là Pu Yung-tsai sống với người anh họ của mình là một sinh viên Phong thủy và Mao Sơn. Pu mua một chiếc bàn cổ từ một cửa hàng đồ cũ và bên trong là bức thư tuyệt mệnh do một phụ nữ trẻ tên là Wei Hsiao-tieh viết. Pu trả lời bức thư và từ bỏ 3 năm cuộc đời của mình, để người phụ nữ có thể trở lại Trái đất và thoát khỏi cuộc hôn nhân bị ép buộc của mình. Sau đó, Pu chia tay với bạn gái của mình, May, vì anh ta bắt gặp cô ấy ngoại tình. Pu sau đó bắt đầu mối quan hệ với Hsiao-tieh. Sau đó May muốn quay lại với Pu vì bạn trai giàu có của cô đã bỏ rơi cô. Cô ấy tự tử để hưởng lợi từ Pu nhưng nó phản tác dụng và cô ấy chết. [2]</p>', 'Full', 1, 'single', 'completed', 17, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Cherie Chung","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Deanie Ip","avatar":""},{"name":"Pauline Wong Siu-Fung","avatar":""},{"name":"Alex Ng Hong-Ling","avatar":""},{"name":"Lee Heung","avatar":""},{"name":"Hoi Yee San","avatar":""},{"name":"Yu Kwok-Lok","avatar":""},{"name":"Fung Yuen-Chi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324547);
