INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-san-nguoi', 'Điệp Vụ Săn Người', 'To Err Is Humane', 'https://phimimg.com/upload/vod/20231010-1/66cd4f22f56a127e37948cfd54acef0e.jpg', 'https://phimimg.com/upload/vod/20231010-1/f6525bb01c404c537a8767b7ea6994d7.jpg', '<p>Sammo và Kenny là những nhân viên cấp thấp của một cửa hàng trang sức. Sammo thường xuyên là mục tiêu lạm dụng từ người quản lý. Một ngày nọ, cả hai được cử đi đưa những viên kim cương cho một sheik. Họ bị cướp trên đường đến ngân hàng. Từng người một họ bị buộc tội thông đồng với bọn cướp. Điều đó khiến Sammo rất tức giận. Để trả thù, anh ta lên kế hoạch bắt cóc nữ quản lý. Kenny bằng cách nào đó biết được âm mưu. Sammo nhầm người phụ nữ, vô tình bắt cóc Joel.</p>', 'Full', 1, 'single', 'completed', 11, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Joey Wong","avatar":""},{"name":"Kenny Bee","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Ng Man-tat","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Bolo Yeung","avatar":""},{"name":"Carrie Ng","avatar":""},{"name":"Anthony Chan Yau","avatar":""},{"name":"Charlie Cho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324547);
