INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-canh-sat-ma-am', 'Đồn Cảnh Sát Ma Ám', 'The Haunted Cop Shop', 'https://phimimg.com/upload/vod/20231010-1/93f3798ef0a8c3c9dd9e0f162028c951.jpg', 'https://phimimg.com/upload/vod/20231010-1/a0be65c60d454e48db716ecc3dff66ac.jpg', '<p>Đồn cảnh sát từng là câu lạc bộ quân đội trong thời kỳ Nhật Bản chiếm đóng Hồng Kông. Nhiều sĩ quan Nhật Bản đã thực hiện hara kiri ở đó vào Ngày V-J. Tòa nhà cũ vì thế trở thành ngôi nhà ma. Tên trộm vặt Ming bị giam dưới tầng hầm. Đó là Lễ hội ma khi các hồn ma được phép nghỉ một đêm. Đại tá xuất hiện và cắn Ming, người trở thành ma cà rồng.</p>', 'Full', 1, 'single', 'completed', 15, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jacky Cheung","avatar":""},{"name":"Ricky Hui","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Kitty Chan","avatar":""},{"name":"Wu Fung","avatar":""},{"name":"Paul Chung Fat","avatar":""},{"name":"Rico Chu","avatar":""},{"name":"Si-Ma Yin","avatar":""},{"name":"Fung Ging-Man","avatar":""},{"name":"Chan Kim-Wan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324547);
