INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giam-nguc-phong-van-phan-1', 'Giam Ngục Phong Vân (Phần 1)', 'Prison On Fire (Season 1)', 'https://phimimg.com/upload/vod/20231010-1/92f30ea2e1038d00c31d9c16ed75aff7.jpg', 'https://phimimg.com/upload/vod/20231010-1/7083bc70135db7e9bc062dad6d7e3019.jpg', '<p>Hai tù nhân xa lạ đã trở thành một đôi bạn thân và cùng nhau đối mặt với cuộc sống phức tạp trong một trại giam ở Trung Quốc. Đối mặt với những khó khăn từ phía nhân viên quản trại và cả những tên giang hồ trong tù, tình huynh đệ giúp họ vượt qua gian khó để nuôi hy vọng làm lại cuộc đời…</p>', 'Full', 1, 'single', 'completed', 18, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Roy Cheung","avatar":""},{"name":"Tommy Wong","avatar":""},{"name":"Victor Hon Kwan","avatar":""},{"name":"Terrence Fok Shui-Wa","avatar":""},{"name":"Frankie Ng","avatar":""},{"name":"Wong Man-Gwan","avatar":""},{"name":"Joe Chu Kai-Sang","avatar":""},{"name":"Shing Fui-On","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324547);
