INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-ung-phuong-dong', 'Phi Ưng Phương Đông', 'Eastern Condors', 'https://phimimg.com/upload/vod/20231009-1/03efcd289bf2ea43a4cd49c474f94974.jpg', 'https://phimimg.com/upload/vod/20231009-1/5488a2a84715021d70d411fb90a09504.jpg', '<p>Một nhóm tù nhân Trung Quốc được giam giữ và đào tạo đặc biệt ở Mỹ đã được trao cho cơ hội để được tự do và nhiệm vụ mà họ cần làm chính là xâm nhập vào đất nước Việt Nam để phá hủy một căn cứ bí mật của các phi vụ mà Hoa Kỳ để lại trong quá trình chiến sự diễn ra.</p>', 'Full', 1, 'single', 'completed', 17, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"Joyce Godenzi","avatar":""},{"name":"Lam Ching-Ying","avatar":""},{"name":"Charlie Chin Chiang-Lin","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Yuen Woo-ping","avatar":""},{"name":"Hsiao Ho","avatar":""},{"name":"Chin Ka-Lok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324547);
