INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-dien-cuong', 'Thế Giới Điên Cuồng', 'It''s a Mad, Mad, Mad World', 'https://phimimg.com/upload/vod/20231006-1/6850df310daf147a468cfb8396fc503b.jpg', 'https://phimimg.com/upload/vod/20231006-1/251b2a074cdafd67134823800a92f8c9.jpg', '<p>Bill, một phóng viên tin tức truyền hình, cố gắng kiếm sống để nuôi sống bản thân, vợ và ba cô con gái ở thành thị Hồng Kông. Trong sự bất hạnh của Bill và gia đình, vận may và cuộc sống của họ cuối cùng đã thay đổi khi vợ của Bill bất ngờ trúng số.</p>', 'Full', 1, 'single', 'completed', 23, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Bill Tung","avatar":""},{"name":"Lydia Shum Tin-Ha","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Charine Chan","avatar":""},{"name":"David Chiang","avatar":""},{"name":"Loletta Lee","avatar":""},{"name":"Pauline Kwan","avatar":""},{"name":"Raymond Fung Sai-Hung","avatar":""},{"name":"Cheng Siu-Ping","avatar":""},{"name":"Elsie Chan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324547);
