INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-ho-phong-van', 'Long Hổ Phong Vân', 'City On Fire', 'https://phimimg.com/upload/vod/20231006-1/b74dfdfcd7b5c5a2a83c56ba9d35c713.jpg', 'https://phimimg.com/upload/vod/20231006-1/fc4f02b51c70c8ca7f2bdb536943dbb4.jpg', '<p>Long hổ phong vân là câu truyện về Cao Thu, một đặc cảnh chuyên được giao nhiệm vụ thâm nhập các băng đảng xã hội đen của Hồng Kông. Quá chán nản với công việc nội gián vừa hiểm nguy vừa đòi hỏi cách hành xử hai mặt, lại mong muốn được sớm lập gia đình với người bạn gái A Hồng, Cao Thu cố gắng tìm mọi cách từ bỏ công việc cảnh sát chìm này. Tuy nhiên, sau khi một cảnh sát chìm khác bị bại lộ danh tính khi đang điều tra một vụ cướp trang sức và bị bọn tội phạm sát hại, thượng cấp của Cao là thanh tra Lưu đã thuyết phục Cao Thu thực hiện phi vụ nội gián cuối cùng - luồn vào hàng ngũ một băng cướp để moi thông tin về kế hoạch đánh cướp của chúng nhờ đó giúp cảnh sát bắt được băng cướp đồ trang sức này ngay tại trận...</p>', 'Full', 1, 'single', 'completed', 19, 1987, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Danny Lee Sau-Yin","avatar":""},{"name":"Sun Yueh","avatar":""},{"name":"Roy Cheung","avatar":""},{"name":"Elvis Tsui","avatar":""},{"name":"Kong Lau","avatar":""},{"name":"Fong Yau","avatar":""},{"name":"Chan Chi-Fai","avatar":""},{"name":"Cheng Mang-Ha","avatar":""},{"name":"Parkman Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324547);
