INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-nu-bao-thu', 'Dân Nữ Báo Thù', 'Entrails of a Beautiful Woman / Entrails of a Virgin / Guts of a Virgin', 'https://phimimg.com/upload/vod/20260601-1/3423e406327ddc20d042553f12e3a554.jpg', 'https://phimimg.com/upload/vod/20260601-1/82f6e408bd50184fe21383c0a8400b7f.jpg', '<p>Phim kể về một nữ bác sĩ tâm lý xinh đẹp tên Megumi Ozawa, người bị sát hại dã man khi cố gắng trả thù cho bệnh nhân của mình—một nạn nhân của băng đảng Yakuza. Sau khi bị giết và chôn cùng xác của một tay gangster đối thủ, cô hồi sinh dưới dạng một thực thể siêu nhiên đầy thù hận, bắt đầu hành trình báo thù đẫm máu.</p>', 'Full', 1, 'single', 'completed', 53, 1986, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Megumi Ozawa","avatar":""},{"name":"Seira Kitagawa","avatar":""},{"name":"Ken Yoshizawa","avatar":""},{"name":"Ayako Ishii","avatar":""},{"name":"Shinji Sekikawa","avatar":""},{"name":"Kazuhiro Sano","avatar":""},{"name":"Yoshinari Yoshie","avatar":""},{"name":"Kimiya Kôdagawa","avatar":""},{"name":"Masakitto Boto","avatar":""},{"name":"Somusakku Sōmanchan","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Guts of a Beauty","Bijo no harawata","美女器官","Beauty Guts","Guts of a Virgin 2 - Guts of a Beauty","美女のはらわた"]', 1784690324547);
