INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-giap-thuong-de-long-huynh-ho-de', 'Áo Giáp Thượng Đế (Long Huynh Hổ Đệ)', 'Armour Of God', 'https://phimimg.com/upload/vod/20260218-1/e045dfe58580cdca6bd7a8d811c46a96.jpg', 'https://phimimg.com/upload/vod/20260218-1/1ae51debb57366c6d684e87884880d35.jpg', '<p>Jackie (do Thành Long thủ vai), một nhà thám hiểm và cựu ca sĩ nhạc rock nổi tiếng, được biết đến với biệt danh &quot;Kền kền châu Á&quot; (Asian Condor). Anh chuyên đi khắp thế giới để tìm kiếm và bán những cổ vật quý hiếm. Một ngày nọ, bạn gái cũ của Jackie là Laura (Rosamund Kwan) bị một giáo phái bí ẩn bắt cóc. Giáo phái này yêu cầu Jackie phải giao nộp &quot;Áo Giáp Thượng Đế&quot; - một bộ giáp cổ xưa được cho là có sức mạnh thần bí, nằm trong truyền thuyết. Thực chất, Áo Giáp Thượng Đế là một bộ sưu tập gồm nhiều mảnh giáp được cất giữ ở những nơi khác nhau trên thế giới.</p>', 'Full', 1, 'single', 'completed', 23, 1986, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Thành Long","avatar":""},{"name":"Tăng Chí Vỹ","avatar":""},{"name":"Quan Chi Lâm","avatar":""},{"name":"La Phù Lạc","avatar":""},{"name":"Ken Boyle","avatar":""},{"name":"Rosamund Kwan","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["देवाचे चिलखत","ईश्वर का कवच","Lung hing foo dai","Long xiong hu di","Božská relikvie","Jumalan aseet","Jackie Chan - O keravnos tou theou","サンダーアーム/龍兄虎弟","L''armadura de Déu","Operation Con