INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-xanh', 'Nhung Xanh', 'Blue Velvet', 'https://phimimg.com/upload/vod/20260210-1/ede5c936af269664549378e6feba17ad.jpg', 'https://phimimg.com/upload/vod/20260210-1/bbadc3380b92496431d5c0ff7765eb89.jpg', '<p>Blue Velvet kể về cậu sinh viên đại học Jeffrey Beaumont tình cờ phát hiện được một cái tai người nằm trong bãi cỏ và đã quyết định sẽ tự tiến hành việc điều tra cùng với phụ tá là cô gái Sandy Williams, con gái của một thám tử trong vùng. Theo những thông tin manh mối Sandy đã cung cấp, Jeffrey tìm cách đột nhập vào căn hộ của kẻ bị tình nghi là cô ca sĩ Dorothy Vallens, người chuyên hát bài hát Nhung xanh cho một quán bar hạng hai. Và theo một cách không thể nào ngăn cản và ngờ tới, Jeffrey đã trở thành nhân chứng bị cuốn vào một thế giới lạ kỳ, điên loạn của một nhóm tội phạm biến chất.</p>', 'Full', 1, 'single', 'completed', 20, 1986, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Isabella Rossellini","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"Dennis Hopper","avatar":""},{"name":"Laura Dern","avatar":""},{"name":"Hope Lange","avatar":""},{"name":"Dean Stockwell","avatar":""},{"name":"George Dickerson","avatar":""},{"name":"Priscilla Pointer","avatar":""},{"name":"Frances Bay","avatar":""},{"name":"Jack Harvey","avatar":""},{"name":"Ken Stovitz","avatar":""},{"name":"Brad Dourif","avatar":""},{"name":"Jack Nance","avatar":""},{"name":"J. Michael Hunter","avatar":""},{"name":"Dick Green","avatar":""},{"name":"Fred Pickler","avatar":""},{"name":"Philip Markert","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f69792608