INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-du-trong-xac-thit', 'Quỷ Dữ Trong Xác Thịt', 'Devil in the Flesh', 'https://phimimg.com/upload/vod/20251228-1/4d034ce73bd0512b8089fd2d9ea1ffa0.jpg', 'https://phimimg.com/upload/vod/20251228-1/e68e8649c71b74b8e1c58e85ec98056d.jpg', '<p>Câu chuyện xoay quanh mối tình đầy cấm đoán giữa Andrea, một học sinh trung học, và Giulia, người phụ nữ lớn tuổi hơn đang đính hôn với một tù nhân chính trị. Khi mối quan hệ của họ ngày càng trở nên mãnh liệt và vượt ngoài kiểm soát, cả hai bị cuốn vào vòng xoáy của dục vọng, tội lỗi và bi kịch. Phim khai thác sâu sắc sự giằng xé giữa bản năng …</p>', 'Full', 1, 'single', 'completed', 20, 1986, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Katia Caballero","avatar":""},{"name":"Keith Smith","avatar":""},{"name":"Alisa Meadows","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Beyond Innocence","Le Diable au Corps","Devil in the Flesh"]', 1784690324547);
