INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ran-ho-mang-1986', 'Rắn Hổ Mang', 'Cobra', 'https://phimimg.com/upload/vod/20251209-1/cf459de2bddc40775f347d07f0e4fb06.jpg', 'https://phimimg.com/upload/vod/20251209-1/971871c6656d6127f01a543cd9d112d3.jpg', '<p>Cobra là một bộ phim hành động Mỹ năm 1986 của đạo diễn George P. Cosmatos và được viết bởi Sylvester Stallone, người cũng đóng vai chính. Phim có sự tham gia của Reni Santoni, Brigitte Nielsen và Andrew Robinson. Đây là bộ phim đầu tiên Brian Thompson đóng một vai nổi bật.</p>', 'Full', 1, 'single', 'completed', 19, 1986, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Brigitte Nielsen","avatar":""},{"name":"Reni Santoni","avatar":""},{"name":"Brian Thompson","avatar":""},{"name":"Lee Garlington","avatar":""},{"name":"Art LaFleur","avatar":""},{"name":"Andrew Robinson","avatar":""},{"name":"Marco Rodríguez","avatar":""},{"name":"Val Avery","avatar":""},{"name":"Nina Axelrod","avatar":""},{"name":"David Rasche","avatar":""},{"name":"John Herzfeld","avatar":""},{"name":"Ross St. Phillip","avatar":""},{"name":"John Hauk","avatar":""},{"name":"Nick Angotti","avatar":""},{"name":"Brad Bovee","avatar":""},{"name":"Kevin Breslin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kobra","Die City-Cobra","铁胆威龙","眼镜蛇血战斧头党","Stallone: Cobra","Cobra"]', 1784690324547);
