INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dat-ma-su-to', 'Đạt Ma Sư Tổ', 'Dharma', 'https://phimimg.com/upload/vod/20251023-1/17e3d964be2d9ef3077bcfe744e87f03.jpg', 'https://phimimg.com/upload/vod/20251023-1/d67743f09e526a44959001a18d8453c6.jpg', '<p>Thời Nam triều Lương Võ Đế, gian thần Vương Lương lộng quyền, hãm hại trung thần, tham vọng muốn lấy kinh niết bàn, khống chế phái Thiếu Lâm. Trụ trì của Thiếu Lâm trước lúc viên tịch đã đưa kinh niết bàn cho Đạt Ma. Đạt Ma trở thành mục tiêu mà Vương Lương muốn loại trừ…</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 16, 1986, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Ray Lui","avatar":""},{"name":"Teresa Mo Shun-Kwan","avatar":""},{"name":"Jimmy Au Shui-Wai","avatar":""},{"name":"Amy Chan","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Newton Lai Hon-Chi","avatar":""},{"name":"Yeung Chak-Lam","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Chan Wing-Chun","avatar":""},{"name":"Michael Tao Tai-Yu","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["DHRAMA","達摩"]', 1784690324547);
