INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-ky-phan-1', 'Tây Du Ký (Phần 1)', 'Journey To The West (Season 1)', 'https://phimimg.com/upload/vod/20250814-1/331ba7ce5ee7495c00b9bd9ddcd1bd37.jpg', 'https://phimimg.com/upload/vod/20250814-1/f39af4b6efc136cfe442f839161a5f63.jpg', '<p>Bộ phim ra đời trong hoàn cảnh khó khăn do được sản xuất vào thập kỉ 1980 thời mà kĩ xảo điện ảnh còn thô sơ lạc hậu. Vốn đầu tư 6 triệu nhân dân tệ tuy là một khoản tiền rất lớn nhưng cũng không đủ trang trải cho toàn bộ phim, các diễn viên cũng chỉ nhận được thù lao tượng trưng, ít ỏi. Phim được làm trong 6 năm trời ròng rã từ năm 1982 đến năm 1988 hoàn thành. Nhiều thông tin cung cấp năm 1986 bộ phim chính thức trình chiếu cho khán thính giả và nhận thấy có nhiều phần thiếu sót nên tiếp tục đầu tư xây dựng và mãi đến năm 1988 thì chính thức hoàn thiện. &nbsp;Đặc biệt, trong 20 năm qua, phim đã nhiều lần phát sóng lại, mỗi lần cả người lớn và trẻ em đều háo hức đón xem. Có thể nói, bản phim Tây Du Kí 1986 đã sống mãi với thời gian và ăn sâu trong kí ức của nhiều thế hệ khán giả. Hầu hết các đài truyền hình của Việt Nam đều ít nhất trình chiếu một lần. Có đài phát sóng đến gần 10 lần và trình chiếu đi và chiếu lại suốt nhiều năm liền.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 42, 1986, 'Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lục Tiểu Linh Đồng","avatar":""},{"name":"Từ Thiếu Hoa","avatar":""},{"name":"Uông Việt","avatar":""},{"name":"Trì Trọng Thụy","avatar":""},{"name":"Mã Đức Hoa","avatar":""},{"name":"Diêm Hoài Lễ","avatar":""},{"name":"Từ Huệ Kính","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"},{"name":"Kinh Điển","slug":"kinh-dien","id":"268385d0de78827ff7bb25c35036ee2a"}]', '["西游记续集","西游记","Xi you ji","Journey to the West","Xi you ji xuji","Journey to the West :  Season 2","Journey.to.the.West"]', 1784690324547);
