INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tay-du-ky-phan-1', 'Tây Du Ký (Phần 1)', 'Journey To The West (Season 1)', 'tây du ký (phần 1) journey to the west (season 1) lục tiểu linh đồng từ thiếu hoa uông việt trì trọng thụy mã đức hoa diêm hoài lễ từ huệ kính 西游记续集 西游记 xi you ji journey to the west xi you ji xuji journey to the west :  season 2 journey.to.the.west', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('laputa-lau-dai-tren-khong', 'Laputa: Lâu Đài Trên Không', 'Castle In The Sky', 'https://phimimg.com/upload/vod/20250716-1/9605f99c5aebcb583e988fe48dea3a4f.jpg', 'https://phimimg.com/upload/vod/20250716-1/04d907a284c8a9bab9a9ff315a29a172.jpg', '<p>Bộ phim hoạt hình phiêu lưu cho trẻ em kể về cậu bé thợ mỏ và cô bé bí ẩn. Hai em khao khát tìm kiếm hòn đảo mất tích đã lâu mà mọi người đồn rằng có rất nhiều của cải.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 1986, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Keiko Yokozawa","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Minori Terada","avatar":""},{"name":"Kotoe Hatsui","avatar":""},{"name":"Fujio Tokita","avatar":""},{"name":"Ichiro Nagai","avatar":""},{"name":"Hiroshi Ito","avatar":""},{"name":"Machiko Washio","avatar":""},{"name":"Takuzō Kamiyama","avatar":""},{"name":"Yoshito Yasuhara","avatar":""},{"name":"Sukekiyo Kameyama","avatar":""},{"name":"Eken Mine","avatar":""},{"name":"TARAKO","avatar":""},{"name":"Masashi Sugawara","avatar":""},{"name":"Reiko Suzuki","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Tomomichi Nishimura","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Tenkuu no Shiro Laputa","Laputa: Castle in the Sky","Laputa - Il castello nel cielo","לפוטה טירת הרקיע","הטירה המרחפת","O Castelo no Céu","Лапута: Замъкът в небето","天空之城","Lapu