INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('laputa-lau-dai-tren-khong', 'Laputa: Lâu Đài Trên Không', 'Castle In The Sky', 'laputa: lâu đài trên không castle in the sky keiko yokozawa mayumi tanaka minori terada kotoe hatsui fujio tokita ichiro nagai hiroshi ito machiko washio takuzō kamiyama yoshito yasuhara sukekiyo kameyama eken mine tarako masashi sugawara reiko suzuki hochu otsuka tomomichi nishimura tenkuu no shiro laputa laputa: castle in the sky laputa - il castello nel cielo לפוטה טירת הרקיע הטירה המרחפת o castelo no céu лапута: замъкът в небето 天空之城 laputa: nebeský zámek laputa - slottet i himlen laputa - linna taivaalla laputa - slottet i himlen le château dans le ciel το κάστρο στον ουρανό laputa - az égi palota dangaus pilis laputa el castillo en el cielo tenkû no shiro rapyuta laputa - himmelslottet laputa - podniebny zamek небесный замок лапута zamak na nebu laputa: zámok v oblakoch gökteki kale небесний замок лапута laputa: lâu đài trên không 천공의 성 라퓨타 لاپوتا قلعه‌ای در آسمان 天空の城ラピュタ：1986 הטירה שבשמיים gökteki kale: laputa 天空の城ラピュタ laputa: pils debesīs taevane kindlus', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-thi-tien-sinh-2-gia-dinh-cuong-thi', 'Cương Thi Tiên Sinh 2: Gia Đình Cương Thi', 'Mr. Vampire II', 'https://phimimg.com/upload/vod/20250603-1/4055c9c23341ec5690834f38fd768d52.jpg', 'https://phimimg.com/upload/vod/20250603-1/9f038c1daadba505f8b5c1874964994a.jpg', '<p>Kwok trong một lần tìm kiếm những món đồ cổ đã lạc vào một ngôi mộ cổ và tìm thấy 3 xác ướp ma cà rồng đã bị ếm bùa. Kwok quyết định đem con ma cà rồng con về thành phố nhưng vô tình đã làm miếng giấy bùa rớt khỏi 2 con ma kia, 2 con ma này tấn công vào thành phố hòng tìm lại được con ma cà rồng nhỏ kia.</p>', 'Full', 1, 'single', 'completed', 18, 1986, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Lam Ching-Ying","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"Moon Lee Choi-Fung","avatar":""},{"name":"Paul Chung Fat","avatar":""},{"name":"Billy Lau Nam-Kwong","avatar":""},{"name":"Ka Lee","avatar":""},{"name":"Cheung Wing-Cheung","avatar":""},{"name":"Pauline Wong Yuk-Wan","avatar":""},{"name":"Hoh Kin-Wai","avatar":""},{"name":"Hon To-Yue","avatar":""},{"name":"Choi Man-Gam","avatar":""},{"name":"Woo Fung","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Walter Tso Tat-Wah","avatar":""},{"name":"Stanley Fung Shui-Fan","avatar":""},{"name":"Manfred Wong Man-Chun","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Mr. Vampire Part 2","Mr. Vampire II","殭屍家族","僵尸先生2","강시선생 2","Mr Vampire 2"]', 1784690324547);
