INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuong-thi-tien-sinh-2-gia-dinh-cuong-thi', 'Cương Thi Tiên Sinh 2: Gia Đình Cương Thi', 'Mr. Vampire II', 'cương thi tiên sinh 2: gia đình cương thi mr. vampire ii lam ching-ying yuen biao moon lee choi-fung paul chung fat billy lau nam-kwong ka lee cheung wing-cheung pauline wong yuk-wan hoh kin-wai hon to-yue choi man-gam woo fung wu ma walter tso tat-wah stanley fung shui-fan manfred wong man-chun mr. vampire part 2 mr. vampire ii 殭屍家族 僵尸先生2 강시선생 2 mr vampire 2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tro-nhat-khac', 'Nhà Trọ Nhất Khắc', 'Maison Ikkoku', 'https://phimimg.com/upload/vod/20250524-1/15aa749fcb5606f5e3ffa9730db4eee5.jpg', 'https://phimimg.com/upload/vod/20250524-1/344079ebf0ce0e8d99c273fb4b0f4783.jpg', '<p>Như cái tên của tác phẩm đã nêu, câu chuyện xảy ra tại một nhà trọ mang tên là Nhất Khắc (Ikkoku). Người quản lý nhà trọ trước đó đã quyết định nghỉ hưu, và ông cử một phụ nữ trẻ tên là Otonashi Kyoko đến thay thế mình. Người quản lý xinh đẹp đã khiến Godai Yusaku, người học trò nghèo trọ ở phòng 5 thầm yêu thương. Tuy nhiên, Yusaku gặp rất nhiều khó khăn trong việc bày tỏ tình cảm với Kyoko. Những lần anh tỏ tình với Kyoko hầu như đều thất bại: hoặc anh bị người khác vô tình làm gián đoạn, hoặc anh làm Kyoko hiểu lầm và gây ra những tình huống dở khóc dở cười. Mọi chuyện trở nên rắc rối hơn khi Kyoko gia nhập một câu lạc bộ quần vợt dành cho phụ nữ, ở đó cô gặp Mitaka Shun, một người thanh niên giàu có, đẹp trai nhưng tốt bụng. Shun thực lòng yêu thương Kyoko và mong cô kết hôn với anh, nhưng Kyoko cảm thấy khó xử khi đứng trước tình cảm của Yusaku lẫn Shun. Tiếp đó, Nikaido Nozomu, một cậu học sinh 18 tuổi gia nhập &quot;cộng đồng&quot; Ikkoku để rồi cũng thầm thương cô quản lý xinh đẹp của khu nhà trọ. Và một điều ít ai biết là Kyoko đã từng có một người chồng yểu mệnh tên là Otonashi Soichiro, anh qua đời chỉ sáu tháng sau khi hai người kết hôn và hình ảnh người chồng quá cố vẫn còn rất sâu đậm trong trái tim Kyoko. Rõ ràng, đối với Yusaku, một người học trò nghèo, cục mịch và gặp nhiều lận đận trong thi cử, việc có được trái tim của Kyoko không hề đơn giản...</p>', 'Hoàn Tất (96/96)', 96, 'hoathinh', 'completed', 19, 1986, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Issei Futamata","avatar":""},{"name":"Sumi Shimamoto","avatar":""},{"name":"Shigeru Chiba","avatar":""},{"name":"Yuko Mita","avatar":""},{"name":"Kazuyo Aoki","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Norio Wakamoto","avatar":""},{"name":"Toshio Furukawa","avatar":""},{"name":"Hiromi Tsuru","avatar":""},{"name":"Minori Matsushima","avatar":""},{"name":"Chika Sakamoto","avatar":""},{"name":"Hisako Kyoda","avatar":""},{"name":"Kazue Komiya","avatar":""},{"name":"Kosei Tomita","avatar":""},{"name":"Anna Cummer","avatar":""},{"name":"Alexandra Carter","avatar":""},{"name":"Andrea Libman","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Maison Ikkoku","메존일각 주민들 이야기","めぞん一刻"]', 1784690324547);
