INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-tro-nhat-khac', 'Nhà Trọ Nhất Khắc', 'Maison Ikkoku', 'nhà trọ nhất khắc maison ikkoku issei futamata sumi shimamoto shigeru chiba yuko mita kazuyo aoki akira kamiya norio wakamoto toshio furukawa hiromi tsuru minori matsushima chika sakamoto hisako kyoda kazue komiya kosei tomita anna cummer alexandra carter andrea libman maison ikkoku 메존일각 주민들 이야기 めぞん一刻', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-binh-doan-nguoi-sat-1986', 'Doraemon: Nobita và Binh Đoàn Người Sắt', 'Doraemon: Nobita and the Steel Troops', 'https://phimimg.com/upload/vod/20250521-1/24b9889ea71659f91ffc9b3554901b16.jpg', 'https://phimimg.com/upload/vod/20250521-1/59819ead79ded37a10d9a1da9a91b8a6.jpg', '<p>Câu chuyện bắt đầu với việc Nobita và Shizuka ngồi trên ống cống cũ ở sân chơi thì Suneo đến và khoe con robot của mình. Nobita trở nên ghen tị và yêu cầu Doraemon chế tạo cho cậu một người máy khổng lồ. Thật trùng hợp, các bộ phận của robot bắt đầu từ trên trời rơi xuống. Sau đó Nobita và Doraemon bắt tay vào lắp ráp robot. Khi họ hoàn thành, Nobita, Doraemon và Shizuka nhận ra rằng robot Zanda Clause là một vũ khí chiến tranh sau khi cả ba vô tình phá huỷ một toà nhà ở thế giới trong gương. Sau đó Nobita gặp một cô gái tên Riruru, cô ấy nói với Nobita rằng người máy là của cô ấy. Nobita đưa cho cô con người máy và lối vào thế giới trong gương. Doraemon và Nobita đã đi theo Riruru và nhận ra cô là gián điệp của Metropolis và xây dựng căn cứ để đón quân đội đến xâm chiếm trái đất.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 1986, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Kazuo Kumakura","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["鐵人兵團","Nobita and the Steel Troops","Doraemon Nobita to Tetsujin Heidan","哆啦A夢：大雄與鐵人兵團","โดราเอมอน ตอน สงครามหุ่นเหล็ก","도라에몽: 노비타와 철인병단","도라에몽: 진구와 철인군단","극장판 도라에몽: 진구와 철인병단","Doraemon: Nobita dan Panglima Besi","Doraemon: Nobita dan Tentera Robot","叮噹勇斗铁人兵团","映画ドラえもん のび太と鉄人兵団"]', 1784690324547);
