INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-binh-doan-nguoi-sat-1986', 'Doraemon: Nobita và Binh Đoàn Người Sắt', 'Doraemon: Nobita and the Steel Troops', 'doraemon: nobita và binh đoàn người sắt doraemon: nobita and the steel troops nobuyo oyama noriko ohara michiko nomura kazuya tatekabe kaneta kimotsuki kazuo kumakura 鐵人兵團 nobita and the steel troops doraemon nobita to tetsujin heidan 哆啦a夢：大雄與鐵人兵團 โดราเอมอน ตอน สงครามหุ่นเหล็ก 도라에몽: 노비타와 철인병단 도라에몽: 진구와 철인군단 극장판 도라에몽: 진구와 철인병단 doraemon: nobita dan panglima besi doraemon: nobita dan tentera robot 叮噹勇斗铁人兵团 映画ドラえもん のび太と鉄人兵団', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-pha-phach', 'Biệt Đội Phá Phách', 'Naughty Boys', 'https://phimimg.com/upload/vod/20250416-1/e6f4dc3c30640142456a0c59d0c6466d.jpg', 'https://phimimg.com/upload/vod/20250416-1/f51fe5c4e591cb20e7aaa4e45b1e3722.jpg', '<p>Bốn người bạn thân thiết là Trương Kim Thắng, Mã Huy, Vương Phiêu và Hác Cường cùng nhau thực hiện một vụ cướp tiệm kim hoàn và bị bắt vào tù. Trước khi được thả, ba người Mã Huy, Vương Phiêu và Hác Cường bị gia hạn án tù do đánh nhau trong nhà tù, chỉ có Kim Thắng được thả đúng hạn. Kim Thắng đi đến nơi cất giấu kim cương theo chỉ dẫn, nhưng phát hiện chúng đã biến mất. Ba người bạn trong tù nghi ngờ Kim Thắng đã chiếm đoạt số kim cương và lên kế hoạch truy tìm anh. Trong khi đó, một nữ thám tử tư tên là Lâm Vận Thi tiếp cận Kim Thắng để điều tra vụ việc. Cả hai cùng nhau chạy trốn và điều tra, phát hiện ra rằng Mã Huy đã cấu kết với người ngoài để lấy trộm kim cương và đổ tội cho Kim Thắng. Cuối cùng, họ hợp tác để vạch trần âm mưu và đưa kẻ xấu ra ánh sáng.</p>', 'Full', 1, 'single', 'completed', 18, 1986, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Thành Long","avatar":""},{"name":"Lưu Gia Linh","avatar":""},{"name":"Lâu Nam Quang","avatar":""},{"name":"Huệ Anh Hồng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Naughty Boys","扭計雜牌軍"]', 1784690324547);
