INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-binh-yen-chim-hot', 'Nơi Bình Yên Chim Hót', 'A Place Where Peaceful Birds Sing', 'https://phimimg.com/upload/vod/20250406-1/af9749235da47198a2dfc0f1606972ca.jpg', 'https://phimimg.com/upload/vod/20250406-1/7332060763d6366a8482c099a0ee4ded.jpg', '<p>Một người cô giáo luôn được sự kính yêu và tôn trọng của nhiều học sinh, cô luôn dạy học trò phải cố gắng ở vùng quê khó khăn nhưng cô luôn muốn sống một cuộc sống sung sướng ở thành thị.</p>', 'Full', 1, 'single', 'completed', 18, 1986, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lý Hùng","avatar":""},{"name":"Lê Cung Bắc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324547);
