INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-nuoc-noi', 'Mùa Nước Nổi', 'The Floating Season', 'https://phimimg.com/upload/vod/20250406-1/3d7c80bd0043a1e29e7488f099f3090d.jpg', 'https://phimimg.com/upload/vod/20250406-1/4ef27deae72c19384e47596197785964.jpg', '<p>&quot;Mùa nước nổi&quot; (1986) là bộ phim chiến tranh Việt Nam ca ngợi tinh thần đấu tranh kiên cường của nông dân miền Tây, vượt qua địa hình khắc nghiệt và thời tiết bất lợi để chiến thắng kẻ thù. Đây là một trong ba tác phẩm hợp tác giữa nhạc sĩ Trịnh Công Sơn, đạo diễn Hồng Sến và nhà văn Nguyễn Quang Sáng, cùng với &quot;Mùa gió chướng&quot; và &quot;Cánh đồng hoang&quot;. Bộ phim quy tụ nhiều nghệ sĩ gạo cội như: Năm Sa Đéc vào vai bà má Nam Bộ nhân hậu, để lại dấu ấn sâu sắc. NSƯT Hồ Kiểng hóa thân thành tên mật thám phản diện, trong khi NSƯT Bắc Sơn đảm nhận vai Ba Hoành – chủ quán rượu giả câm làm liên lạc cho bộ đội và những gương mặt trẻ như Robert Hải, Thúy An, Hai Nhất, Đào Bá Sơn, Thoại Mỹ…</p>', 'Full', 1, 'single', 'completed', 20, 1986, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thúy An","avatar":""},{"name":"Năm Sa Đéc","avatar":""},{"name":"Hồ Kiểng","avatar":""},{"name":"Đào Bá Sơn","avatar":""},{"name":"Thoại Mỹ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324547);
