INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mua-nuoc-noi', 'Mùa Nước Nổi', 'The Floating Season', 'mùa nước nổi the floating season thúy an năm sa đéc hồ kiểng đào bá sơn thoại mỹ 插翅难飞 vol à haut risque flight risk', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-son-thanh-mau', 'Hoa Sơn Thánh Mẫu', 'The Lamp Lore', 'https://phimimg.com/upload/vod/20250318-1/2db82652678ce6c7f1ec7704c254fe47.jpg', 'https://phimimg.com/upload/vod/20250318-1/c5e370d4caa160cbb259a83646d50064.jpg', '<p>Đại Ma Thần trong ma giới sau khi luyện thành ma công, vào ngày chúc thọ của Ngọc Hoàng đánh đến thiên đình. Ngọc Hoàng bị trong thương may nhờ có Hoa Sơn Thánh Mẫu dùng Bảo Liên Đăng đánh bại, rút về hang động trị thương. Nhị Lang Thần, Dao Trì Tiên Tử phát hiện có nội gián trong thiên đình tiếp tay với Đại Ma Thần. Sau khi đánh bại Đại Ma Thần, Bảo Liên Đăng bị mất phép thuật. Muốn khôi phục Bảo Liên Đăng phải tìm cho 3 ra món bảo vật. Hoa Sơn Thánh Mẫu cùng Dao Trì Tiên Tử lên đường tìm bảo vật. Trên đường đi Dao Trì Tiên Tử năm lần bảy lượt cản trở Hoa Sơn Thánh Mẫu vì Dao Trì chính là Huyết Ma, nội gián dưới tay Đại Ma Thần. Qua nhiều thử thách Hoa Sơn Thánh Mẫu cũng tìm được 3 món bảo vật để luyện lại Bảo Liên Đăng. Không thể phá hoại Bao Liên Đăng, Đại Ma Thần dùng càn khôn đại pháp đưa Huyết Ma nghịch chuyển thời gian trở về 500 trước giết chết tiền thân của Hoa Sơn Thámh Mẫu là nữ thường dân tên Kinh Hoa sống ở trấn Bồng Lai. Vì không có tiền thân sẽ không có Hoa Sơn Thánh Mẫu. Huyết Ma quay trở về 500 năm trước, giết hết những cô gái mang tên Kinh Hoa. Nhưng chưa giết được Kinh Hoa thật sự. Kinh Hoa sống cùng đại ca Dương Tiễn, cũng là tiền thân của Nhị Lang Thần trong gánh hát. Sau khi gặp nạn không chết Kinh Hoa cùng Dương Tiễn gặp được Thái Cực Tiên ông được ông nhận làm đệ tử. Nhưng Kinh Hoa cũng đã động lòng với một người phàm Lưu Minh Xương. Kinh Hoa cùng Lưu Minh Xương trãi qua nhiều sóng gió vì Lưu Minh Xương nguyện là uyên ương không làm tiên, kết duyên vợ chồng sinh được 1 người con trai. Huyết Ma nhiều lần mưu hại Kinh Hoa không thành, trước khi chết kịp nói với Kinh Hoa, Đại Ma Thần sắp đến, chỉ dẩn cho Kinh Hoa đến Hoa Sơn. Kinh Hoa giờ đây không muốn liên lụy chồng con, và biết được vận số của mình, sự tồn vong của đất trời, Kinh Hoa gạt nước mắt một mình đến Hoa Sơn. Đại Ma Thần trở về 500 trước nhốt Kinh Hoa trong Hoa Sơn, nơi đây cũng là nơi cất giữ Bảo Liên Đăng. Lưu Minh Xương tưởng Kinh Hoa đã chết vô cùng đau khổ. Sau cùng lên kinh ứng thí trở thành trạng nguyên &amp; lập gia đình khác. Mười mấy năm sau, Kinh Hoa được thoát ra, luyện thành Bảo Liên Đăng trở về thiên đình 500 sau nhập một vào Hoa Sơn Thánh Mẫu tiêu diệt được Đại Ma Thần. Cuối cùng vợ chồng họ cũng gặp lại nhau nhưng Kinh Hoa đã là Hoa Sơn Thánh Mẫu bay trở về trời.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 16, 1986, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Liza Wong Ming-Chuen","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Lo Hoi-Pang","avatar":""},{"name":"Sharon Yeung","avatar":""},{"name":"Yu Chi-Ming","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Tam Bing-Man","avatar":""},{"name":"Lee Lung-Kei","avatar":""},{"name":"Lee Heung-Kam","avatar":""},{"name":"Ho Bik-Kin","avatar":""},{"name":"Gary Ho Kwai-Lam","avatar":""},{"name":"Dorothy Yu Yee-Ha","avatar":""},{"name":"Yue Ming","avatar":""},{"name":"Ling Hon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["寶蓮燈"]', 1784690324547);
