INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-song-ly-biet', 'Dòng Sông Ly Biệt', 'Lovers Under The Rain', 'https://phimimg.com/upload/vod/20241207-1/50a8064069232d151249be7f9eddc014.jpg', 'https://phimimg.com/upload/vod/20241207-1/57a7c6491b8705349a027b6177add939.jpg', '<p>Lấy bối cảnh những năm 60 của thế kỷ trước (cũng chính là thời điểm Quỳnh Dao sáng tác truyện), Dòng sông ly biệt kể về một gia đình phức tạp, lại được đặt trong lúc thời có nhiều biến động, với những mâu thuẫn giữa hai thế hệ già - trẻ, giữa tư tưởng phong kiến còn sót lại với lối suy nghĩ hiện đại đang nhen nhúm trong tâm tư mỗi con người. Đó là một người cha đã già, luôn mắc kẹt trong quá khứ với vô vàn những chiến tích vẻ vang nhưng cũng không kém phần hãi hùng; hai người mẹ, một kiên trì nhẫn nhịn đến mức cùng cực, một ghê gớm sắc sảo và đầy quyền lực; và những đứa con của họ, dần dà mang trong mình tư tưởng nổi loạn vì đã sống quá lâu trong cảnh thiếu thốn tình thương. Tất cả những bi kịch đó, tưởng chừng sẽ mãi mãi bị chôn vùi trong sự sung túc giả tạo, bỗng một ngày, từng chút từng chút một, đều bị khơi lên bởi ngọn lửa thù hằn...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 19, 1986, 'Lồng Tiếng', 'FHD', 'Đài Loan', 0, '[{"name":"Lưu Tuyết Hoa","avatar":""},{"name":"Tần Hán","avatar":""},{"name":"Triệu Vĩnh Hinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324547);
