INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-vui-ve-3', 'Ma Vui Vẻ 3', 'Happy Ghost III', 'https://phimimg.com/upload/vod/20231008-1/445276163bec5ba9fb684e784cf61616.jpg', 'https://phimimg.com/upload/vod/20231008-1/6de5b90a1de8f3297bb9a04b43ca402b.jpg', '<p>Nội dung của phim Ma Vui Vẻ 3 xoay quanh một ca sĩ trẻ, người không thành công trong sự nghiệp và cuộc sống, sự bế tắc đã đưa cô ấy tới quyết định tự tử và sau khi chết đó, cô sẽ được đầu thai, lần này là vào một gia đình chuyên về âm nhạc. Linh hồn của cô ấy phải đến bệnh viện, nơi người mẹ tương lai của cô ấy hiện đã sẵn sàng để sinh ra cô ấy, để cô ấy có thể bước vào bụng mẹ và được sinh ra.&nbsp; Thật không may, cô bỏ lỡ thời gian sinh của cô vốn đã được chỉ định, lý do là sự can thiệp vô tình của một thanh niên tên là Hong. Lúc đầu, cô tức giận và làm cho cuộc sống của anh ta trở nên khó khăn, nhưng cuối cùng thì họ lại phải lòng nhau, mặc dù cô không thể ở lại lâu nhưng cô lại có một cơ hội cuối cùng để được tái sinh một lần nữa.</p>', 'Full', 1, 'single', 'completed', 17, 1986, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Raymond Wong","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Charine Chan","avatar":""},{"name":"Danny Poon","avatar":""},{"name":"Ho Pak-Kwong","avatar":""},{"name":"Walter Tso Tat-Wah","avatar":""},{"name":"Wong Siu-Ming","avatar":""},{"name":"Ngai Tim-Choi","avatar":""},{"name":"Kobe Wong Kam-Bo","avatar":""},{"name":"Aai Dung-Gwa","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324547);
