INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('asterix-phieu-luu-o-britain', 'Asterix Phiêu Lưu Ở Britain', 'Asterix in Britain', 'https://phimimg.com/upload/vod/20231103-1/253f2bd95026c48a783383102389ac82.jpg', 'https://phimimg.com/upload/vod/20231103-1/6498d607ed91fb0b1993f3aa1c7f2f52.jpg', '<p>Một ngôi làng nhỏ cổ kính của Anh vẫn chống lại quân xâm lược La Mã. Asterix và Obelix được mời giúp đỡ. Họ phải đối mặt với sương mù, mưa, bia ấm và thịt lợn luộc với nước sốt bạc hà, nhưng họ sẽ sớm gặp phải tình trạng người La Mã của Thống đốc Encyclopaedius Britannicus đang suy tàn và thất thủ. Cho đến khi một cuộc đua hoang dã để giành lấy một thùng thuốc ma thuật đưa họ vào cuộc uống rượu.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 1986, 'Vietsub', 'HD', 'Đan Mạch', 0, '[{"name":"Roger Carel","avatar":""},{"name":"Pierre Tornade","avatar":""},{"name":"Graham Bushnell","avatar":""},{"name":"Pierre Mondy","avatar":""},{"name":"Maurice Risch","avatar":""},{"name":"Roger Lumont","avatar":""},{"name":"Nicolas Silberg","avatar":""},{"name":"Albert Augier","avatar":""},{"name":"Paul Bisciglia","avatar":""},{"name":"Bertie Cortez","avatar":""},{"name":"Martine Messager","avatar":""},{"name":"Henri Poirier","avatar":""},{"name":"Alain Doutey","avatar":""},{"name":"Patrick Floersheim","avatar":""},{"name":"Gérard Croce","avatar":""},{"name":"Michel Elias","avatar":""},{"name":"Michel G","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324547);
