INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiet-dinh-san-va-pham-le-hoa', 'Tiết Đình San Và Phạm Lê Hoa', 'General Father , General Son', 'https://phimimg.com/upload/vod/20240623-1/299a6e58fa468c1ace0b6ff57eed928f.jpg', 'https://phimimg.com/upload/vod/20240623-1/84dd782c47d181811fde952436af8127.jpg', '<p><em>Tiết Đinh Sơn (Tiết Đình San) là con trai của tiêt nhân quý, khi tiết nhan quý bị quân giặc bao vây, tiết đinh sơn cùng em gái của mình đã kéo binh lính đi giải cứu cho cha, nhưng anh đã bị tên Đậu Kim Đồng bắt ép phải phối hợp với hắn, không còn cách nào khác tiết đinh son đành chấp nhận, Phàn Lê Huê (Phạm Lê Hoa) là 1 nữ tưởng tại ả tay liêu, cô với Tiết Đình San là 1 đôi trời ban. cô đã giúp Tiết Đình San giải cứu cho cha anh.</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 19, 1986, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Huỳnh Nhật Hoa","avatar":""},{"name":"Trần Mẫn Nhi","avatar":""},{"name":"Cung Từ Ân","avatar":""},{"name":"Dung Tuệ Văn","avatar":""},{"name":"Hạ Vũ","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324548);
