INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-am-anh-nguy-hiem', 'Nỗi Ám Ảnh Nguy Hiểm', 'The Devil''s Honey', 'https://phimimg.com/upload/vod/20240726-1/3e009048655149459aa087f1c84773e4.jpg', 'https://phimimg.com/upload/vod/20240726-1/d630dcc9997c65544d47d767653b0f83.jpg', '<p>Một phụ nữ trẻ bắt cóc một bác sĩ, kẻ mà cô ta cho là phải chịu trách nhiệm cho cái chết của bạn trai mình và thực hiện nhiều hành vi tra tấn tình dục khác nhau với anh ta.</p>', 'Full', 1, 'single', 'completed', 19, 1986, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Brett Halsey","avatar":""},{"name":"Corinne Cléry","avatar":""},{"name":"Blanca Marsillach","avatar":""},{"name":"Stefano Madia","avatar":""},{"name":"Paula Molina","avatar":""},{"name":"Bernard Seray","avatar":""},{"name":"Lucio Fulci","avatar":""},{"name":"Eulalia Ramón","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
