INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-lui-khong-hang', 'Không Lui Không Hàng', 'No Retreat, No Surrender', 'https://phimimg.com/upload/vod/20240228-1/8d436f8698ecf3a95504edc57287fe92.jpg', 'https://phimimg.com/upload/vod/20240228-1/1f1e2da05d98af21629be9d28162934e.jpg', '<p>Cậu bé Jason Stillwell cùng cha mẹ chuyển đến Seattle, nơi những kẻ bắt nạt địa phương quấy rối họ không thương tiếc. Cha của Jason, Tom, không tin vào bạo lực nên gia đình rất bất bình. Một ngày nọ, Jason đăng ký tham gia một lớp học võ thuật và lặng lẽ thăng hạng để trở thành đối thủ lớn. Khí phách của anh được thử thách trong một trận đấu quốc tế với Ivan, một nhà vô địch người Nga.</p>', 'Full', 1, 'single', 'completed', 20, 1986, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kurt McKinney","avatar":""},{"name":"Jean-Claude Van Damme","avatar":""},{"name":"J.W. Fails","avatar":""},{"name":"Kathie Sileno","avatar":""},{"name":"Kim Tae-Jeong","avatar":""},{"name":"Kent Lipham","avatar":""},{"name":"Ron Pohnel","avatar":""},{"name":"Dale Jacoby","avatar":""},{"name":"Peter Cunningham","avatar":""},{"name":"Timothy D. Baker","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324548);
