INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('37-do-2-buoi-sang', '37 Độ 2 Buổi Sáng', 'Betty Blue', 'https://phimimg.com/upload/vod/20240219-1/ada487fab143d9790b785a258d06d2ac.jpg', 'https://phimimg.com/upload/vod/20240219-1/a40302d6c551cd2f2f201bff7c1de479.jpg', '<p>Zorg là một thanh niên đang sống trong một căn nhà gỗ và làm nhiệm vụ quản lý những căn nhà gỗ khác cho ông chủ. Anh làm việc chăm chỉ và viết lách trong những giờ rảnh rỗi. Một ngày kia, Betty bước vào đời anh, tình cờ Betty khám phá cuốn tiểu thuyết của anh và cô thuyết phục anh đem đi in, nhưng bị các nhà xuất bản từ chối.</p>', 'Full', 1, 'single', 'completed', 18, 1986, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean-Hugues Anglade","avatar":""},{"name":"Béatrice Dalle","avatar":""},{"name":"Gérard Darmon","avatar":""},{"name":"Consuelo De Haviland","avatar":""},{"name":"Clémentine Célarié","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
