INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('crossroads', 'Crossroads', 'Crossroads', 'https://phimimg.com/upload/vod/20240205-1/454e9a07da07bd917ae2f8dec0fe4aa0.jpg', 'https://phimimg.com/upload/vod/20240205-1/54b2e718375bb985eadc659731044202.jpg', '<p>Một bậc thầy guitar muốn trở thành nhạc blues tìm kiếm một bài hát đã thất lạc từ lâu của nhạc sĩ huyền thoại Robert Johnson.</p>', 'Full', 1, 'single', 'completed', 9, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ralph Macchio","avatar":""},{"name":"Joe Seneca","avatar":""},{"name":"Jami Gertz","avatar":""},{"name":"Joe Morton","avatar":""},{"name":"Robert Judd","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324548);
