INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phich-lich-dai-lac-ba', 'Phích Lịch Đại Lạc Bá', 'Where''s Officer Tuba', 'https://phimimg.com/upload/vod/20231230-1/db56408982c0a49590c8118e4f294089.jpg', 'https://phimimg.com/upload/vod/20231230-1/3b2f1ba3ceb4fc9202a6055a536ebc28.jpg', '<p>Sĩ quan Tuba và Cảnh sát Cảnh sát Chow cố gắng truy lùng một băng nhóm tống tiền. Không thành công trong việc bắt giữ băng đảng, Chow bị hạ gục và trong lúc hấp hối, Tuba phải hứa rằng anh sẽ đánh bại bọn côn đồ và trả thù cho cái chết của mình. Khi Tuba thực hiện một nhiệm vụ cảnh sát khác với tân binh Cheung và cố gắng thu hút Joanne, bạn gái của mình, anh đã quên lời hứa của mình với Châu Tinh Trì. Vì vậy, linh hồn của Chow xuất hiện và ám ảnh Tuba, cố gắng bắt anh ta hoàn thành sứ mệnh của mình.</p>', 'Full', 1, 'single', 'completed', 12, 1986, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Sammo Kam-Bo Hung","avatar":""},{"name":"David Chiang","avatar":""},{"name":"Jacky Cheung","avatar":""},{"name":"Joey Wang","avatar":""},{"name":"Dennis Chan","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Stanley Sui-Fan Fung","avatar":""},{"name":"Jung-Lee Hwang","avatar":""},{"name":"John Sham","avatar":""},{"name":"Tai-Bo","avatar":""},{"name":"Melvin Wong","avatar":""},{"name":"Fung Woo","avatar":""},{"name":"Ip Wing Cho","avatar":""},{"name":"Teddy Yip(别名)","avatar":""},{"name":"Liu Qiu Sheng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d