INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-cua-chua', 'Sứ Mệnh Của Chúa', 'The Mission', 'https://phimimg.com/upload/vod/20231219-1/39b44850213a8120083676233e600da6.jpg', 'https://phimimg.com/upload/vod/20231219-1/2ccbc844ad5d73d565bf19034903dc50.jpg', '<p>Khi một tu sĩ Dòng Tên người Tây Ban Nha đi vào vùng hoang dã Nam Mỹ để xây dựng một sứ mệnh với hy vọng cải đạo người da đỏ trong vùng, một thợ săn nô lệ đã được cải đạo và tham gia sứ mệnh của anh ta. Khi Tây Ban Nha bán thuộc địa cho Bồ Đào Nha, họ buộc phải bảo vệ tất cả những gì họ đã xây dựng trước những kẻ xâm lược Bồ Đào Nha.</p>', 'Full', 1, 'single', 'completed', 10, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"Ray McAnally","avatar":""},{"name":"Aidan Quinn","avatar":""},{"name":"Liam Neeson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
