INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-quay-pha-2', 'Ma Quậy Phá 2', 'Poltergeist II: The Other Side', 'https://phimimg.com/upload/vod/20231213-1/8ca2566f6064cfa209db5a55e32d2298.jpg', 'https://phimimg.com/upload/vod/20231213-1/7da64d349c14f1d9935561c18f293724.jpg', '<p>Gia đình Freeling chuyển đến sống với mẹ của Diane trong nỗ lực thoát khỏi chấn thương tâm lý và hậu quả của việc Carol Anne bị Quái thú bắt cóc. Nhưng Quái thú không dễ dàng bị loại bỏ và xuất hiện trong một bóng ma với tư cách là Mục sư Kane, một kẻ cuồng tín tôn giáo chịu trách nhiệm về cái chết của nhiều tín đồ của mình. Mục tiêu của anh ta rất đơn giản - anh ta muốn có Carol Anne thiên thần.</p>', 'Full', 1, 'single', 'completed', 10, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Craig T. Nelson","avatar":""},{"name":"JoBeth Williams","avatar":""},{"name":"Heather O''Rourke","avatar":""},{"name":"Oliver Robins","avatar":""},{"name":"Zelda Rubinstein","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324548);
