INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('police-academy-3-back-in-training', 'Police Academy 3: Back in Training', 'Police Academy 3: Back in Training', 'https://phimimg.com/upload/vod/20231203-1/a94dc9023aa91bba201717c22d31b5ae.jpg', 'https://phimimg.com/upload/vod/20231203-1/02b4df3b6888fd088ec48ce6dae64093.jpg', '<p>Sau khi hoàn thành nhiệm vụ của họ trong Học viện Cảnh sát 2: Bài tập đầu tiên của họ (1985), Cán bộ Carey Mahoney và phần còn lại của các sinh viên tốt nghiệp gốc từ Học viện Cảnh sát của Chỉ huy Lassard (1984) thấy mình với lưng với Bức tường. Dường như, do sự cắt giảm tài trợ, chỉ có thể có một tổ chức cảnh sát trong thành phố, và chỉ huy Lassard và Mauser phải cố gắng hết sức để có được sự chấp thuận của Thống đốc Neilson. Tất nhiên, Mauser Conniving đã pha chế một kế hoạch ác khéo léo để phá hoại các đối thủ của mình. Có thể Mahoney, cùng với một số ít tân binh, cứu ngày và học viện yêu thích của họ?</p>', 'Full', 1, 'single', 'completed', 9, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324548);
