INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-sau-ngay-13-phan-6-jason-song-lai', 'Thứ Sáu Ngày 13 – Phần 6: Jason Sống Lại', 'Friday the 13th: Part 6: Jason Lives', 'https://phimimg.com/upload/vod/20231203-1/1a266a4ce1b71114a3f3c3511f56cead.jpg', 'https://phimimg.com/upload/vod/20231203-1/430f32c82367e7713f785cab689888b4.jpg', '<p>Lúc trẻ đã giết được Jason, nay Tommy điều tra về tên ác nhân quái dị này để đảm bảo rằng hắn đã chết. Rồi anh nhận ra hắn đã được nghỉ ngơi đầy đủ để trở lại giết chóc.</p>', 'Full', 1, 'single', 'completed', 8, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Thom Mathews","avatar":""},{"name":"Jennifer Cooke","avatar":""},{"name":"David Kagen","avatar":""},{"name":"Renée Jones","avatar":""},{"name":"Kerry Noonan","avatar":""},{"name":"Darcy DeMoss","avatar":""},{"name":"Tom Fridley","avatar":""},{"name":"Alan Blumenfeld","avatar":""},{"name":"Tony Goldwyn","avatar":""},{"name":"Ron Palillo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324548);
