INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-tai-giang-ho-1986', 'Long Tại Giang Hồ', 'Legacy Of Rage', 'https://phimimg.com/upload/vod/20231006-1/7cca6710a10874a9c7396f1e92fdf836.jpg', 'https://phimimg.com/upload/vod/20231006-1/c7d2cb8d50ab8129dbec540797711d53.jpg', '<p>Brandon vào vai Brandon Ma, một Joe đi làm bình thường, làm hai công việc để có thể hỗ trợ bạn gái May và ước mơ sở hữu một chiếc mô tô của mình. Bạn thân nhất của Brandon là Michael, một kẻ bán ma túy đầy tham vọng và sát nhân. Michael thèm muốn May và vì vậy anh ấy nghĩ ra một kế hoạch để giành được cô ấy cho mình, đồng thời giải quyết vấn đề mà anh ấy đang gặp phải. Có vẻ như một cảnh sát chìm tên là Sharky đã sử dụng mối quan hệ với cảnh sát của mình để thống trị hoạt động buôn bán cocaine ở địa phương, vì vậy Michael đã ra lệnh giết anh ta và sử dụng Brandon làm kẻ sa ngã. Brandon phải vào tù, mặc dù anh nghĩ rằng mình sẽ sớm được thả nhờ nỗ lực của người bạn tốt Michael. Tám năm sau, Brandon cuối cùng cũng ra tù và thề sẽ trả thù.</p>', 'Full', 1, 'single', 'completed', 10, 1986, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Brandon Lee","avatar":""},{"name":"Michael Wong","avatar":""},{"name":"Michael Chan","avatar":""},{"name":"Regina Kent","avatar":""},{"name":"Mang Hoi","avatar":""},{"name":"Kirk Wong","avatar":""},{"name":"Ku Feng","avatar":""},{"name":"Chu Hak","avatar":""},{"name":"Teddy Yip Wing-Cho","avatar":""},{"name":"Ng Man-tat","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
