INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-trek-4-hanh-trinh-ve-nha', 'Star Trek 4: Hành Trình Về Nhà', 'Star Trek IV: The Voyage Home', 'https://phimimg.com/upload/vod/20231120-1/e02d99653f17e32c1a6813dac853f892.jpg', 'https://phimimg.com/upload/vod/20231120-1/fdde495a1c0d1440f14a23c9acdfbd5a.jpg', '<p>Đó là thế kỷ 23, và một sức mạnh bí ẩn ngoài hành tinh đang đe dọa Trái đất bằng cách làm bốc hơi các đại dương và phá hủy bầu khí quyển. Trong một nỗ lực điên cuồng để cứu nhân loại, Kirk và phi hành đoàn của anh phải du hành thời gian trở lại San Francisco năm 1986, nơi họ tìm thấy một thế giới của nhạc punk, bánh pizza và những chiếc xe buýt thay đổi chính xác xa lạ như bất cứ thứ gì họ từng gặp ở những nơi xa xôi Thiên hà. Một cuộc phiêu lưu Star Trek ly kỳ, đầy hành động!</p>', 'Full', 1, 'single', 'completed', 12, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"William Shatner","avatar":""},{"name":"Leonard Nimoy","avatar":""},{"name":"DeForest Kelley","avatar":""},{"name":"Catherine Hicks","avatar":""},{"name":"James Doohan","avatar":""},{"name":"George Takei","avatar":""},{"name":"Walter Koenig","avatar":""},{"name":"Nichelle Nichols","avatar":""},{"name":"Mark Lenard","avatar":""},{"name":"Jane Wyatt","avatar":""},{"name":"Majel Barrett","avatar":""},{"name":"Robert Ellenstein","avatar":""},{"name":"John Schuck","avatar":""},{"name":"Brock Peters","avatar":""},{"name":"Robin Curtis","avatar":""},{"name":"Michael Snyder","avatar":""},{"name":"Kirk R. That","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324548);
