INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-nguyen', 'Cao Nguyên', 'Highlander', 'https://phimimg.com/upload/vod/20231115-1/ea5a759dc2034cdbb44550653aef7590.jpg', 'https://phimimg.com/upload/vod/20231115-1/9a6182c48a4b845ff3c76e89bee27c55.jpg', '<p>Anh ta đã đánh trận đầu tiên trên Cao nguyên Scotland vào năm 1536. Anh ta sẽ đánh trận chiến vĩ đại nhất của mình trên các đường phố của Thành phố New York vào năm 1986. Tên anh ta là Connor MacLeod. Anh ấy là bất tử.</p>', 'Full', 1, 'single', 'completed', 12, 1986, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Christophe Lambert","avatar":""},{"name":"Roxanne Hart","avatar":""},{"name":"Clancy Brown","avatar":""},{"name":"Sean Connery","avatar":""},{"name":"Beatie Edney","avatar":""},{"name":"Alan North","avatar":""},{"name":"Jon Polito","avatar":""},{"name":"Sheila Gish","avatar":""},{"name":"Hugh Quarshie","avatar":""},{"name":"Peter Diamond","avatar":""},{"name":"Billy Hartman","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"Celia Imrie","avatar":""},{"name":"Christopher Malcolm","avatar":""},{"name":"Frank Dux","avatar":""},{"name":"Ian Reddington","avatar":""},{"name":"Alistair Findlay","avatar":""},{"name":"Edwar","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"}]', '[]', 1784690324548);
