INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suoi-nguon', 'Suối Nguồn', 'Manon of the Spring', 'https://phimimg.com/upload/vod/20231114-1/a919778e4c78a70c45d933bcc2a5f90e.jpg', 'https://phimimg.com/upload/vod/20231114-1/ae80c316706602cb002c7ef093cd62f0.jpg', '<p>Một cô gái chăn cừu đẹp nhưng nhút nhát có âm mưu trả thù những người đàn ông tham lam đã thu hồi đất của cha mình và khiến ông qua đời.</p>', 'Full', 1, 'single', 'completed', 14, 1986, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Yves Montand","avatar":""},{"name":"Daniel Auteuil","avatar":""},{"name":"Emmanuelle Béart","avatar":""},{"name":"Hippolyte Girardot","avatar":""},{"name":"Margarita Lozano","avatar":""},{"name":"Yvonne Gamy","avatar":""},{"name":"Ticky Holgado","avatar":""},{"name":"Jean Bouchaud","avatar":""},{"name":"Elisabeth Depardieu","avatar":""},{"name":"Gabriel Bacquier","avatar":""},{"name":"Armand Meffre","avatar":""},{"name":"André Dupon","avatar":""},{"name":"Pierre Nougaro","avatar":""},{"name":"Jean Maurel","avatar":""},{"name":"Roger Souza","avatar":""},{"name":"Didier Pain","avatar":""},{"name":"Pier","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
