INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-coi-ngoai', 'Từ Cõi Ngoài', 'From Beyond', 'https://phimimg.com/upload/vod/20231110-1/0597d3ff48c0e3fc6571aad232fb65ee.jpg', 'https://phimimg.com/upload/vod/20231110-1/ef21ba8414e9a86a9abef4e5a206cdd7.jpg', '<p>Một nhóm các nhà khoa học đã phát triển Máy cộng hưởng, một cỗ máy cho phép bất cứ ai ở trong tầm nhìn xa hơn thực tế có thể cảm nhận được thông thường. Nhưng khi thí nghiệm thành công, họ ngay lập tức bị tấn công bởi những dạng sống khủng khiếp.</p>', 'Full', 1, 'single', 'completed', 12, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeffrey Combs","avatar":""},{"name":"Barbara Crampton","avatar":""},{"name":"Ken Foree","avatar":""},{"name":"Ted Sorel","avatar":""},{"name":"Carolyn Purdy-Gordon","avatar":""},{"name":"Bunny Summers","avatar":""},{"name":"Bruce McGuire","avatar":""},{"name":"Del Russel","avatar":""},{"name":"Dale Wyatt","avatar":""},{"name":"Andrew Lord Miller","avatar":""},{"name":"John Leamer","avatar":""},{"name":"Regina Bleesz","avatar":""},{"name":"Karen Christenfeld","avatar":""},{"name":"Albert Band","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324548);
