INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-tai-pho-hoa', 'Cuộc Chiến Tại Phố Hoa', 'Big Trouble in Little China', 'https://phimimg.com/upload/vod/20231102-1/0587a280360b4821dcde5c2e6a348fff.jpg', 'https://phimimg.com/upload/vod/20231102-1/22c42788298a818c3f6acc844a11f5ac.jpg', '<p>Khi tài xế xe tải Jack Burton đồng ý đưa bạn mình, Wang Chi, đến đón vị hôn thê của mình tại sân bay, anh ta không ngờ mình lại bị cuốn vào một trận chiến siêu nhiên giữa thiện và ác. Vị hôn thê của Wang có đôi mắt xanh ngọc lục bảo, điều này khiến cô trở thành mục tiêu hoàn hảo của phù thủy bất tử Lo Pan—người phải kết hôn với một cô gái có đôi mắt xanh lục để có thể lấy lại hình dạng vật lý của mình.</p>', 'Full', 1, 'single', 'completed', 14, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kurt Russell","avatar":""},{"name":"Kim Cattrall","avatar":""},{"name":"Dennis Dun","avatar":""},{"name":"James Hong","avatar":""},{"name":"Victor Wong","avatar":""},{"name":"Kate Burton","avatar":""},{"name":"Donald Li","avatar":""},{"name":"Carter Wong","avatar":""},{"name":"Peter Kwong","avatar":""},{"name":"James Pax","avatar":""},{"name":"Suzee Pai","avatar":""},{"name":"Chao Li Chi","avatar":""},{"name":"Jeff Imada","avatar":""},{"name":"Rummel Mor","avatar":""},{"name":"Craig Ng","avatar":""},{"name":"June Kyoto Lu","avatar":""},{"name":"Noel Toy","avatar":""},{"name":"Jade Go","avatar":""},{"name":"Jerry Hardin","avatar":""},{"name":"James Lew","avatar":""},{"name":"Jim Lau","avatar":""},{"name":"Ken","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Giả Tượ