INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-than-vung-texas-2', 'Tử Thần Vùng Texas 2', 'The Texas Chainsaw Massacre 2', 'https://phimimg.com/upload/vod/20231026-1/ed9b7733dd37742e71c3ba8a1ee86b1f.jpg', 'https://phimimg.com/upload/vod/20231026-1/ecaf808a722599722db2a83078a83836.jpg', '<p>Tên điên cuồng sử dụng cưa máy Leatherface một lần nữa lại thực hiện cách ăn thịt đồng loại của mình, cùng với những thành viên còn lại trong gia tộc xoắn xuýt của hắn, bao gồm cả Chop-Top cũng bị xáo trộn không kém. Lần này, tên sát nhân đeo mặt nạ đã để mắt tới tay chơi xóc đĩa xinh đẹp Vanita &quot;Stretch&quot; Brock, người hợp tác với luật sư Texas Lefty Enright để chiến đấu với kẻ tâm thần và gia đình hắn ở sâu trong hang ổ của chúng, một công viên giải trí rùng rợn bị bỏ hoang.</p>', 'Full', 1, 'single', 'completed', 12, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Caroline Williams","avatar":""},{"name":"Dennis Hopper","avatar":""},{"name":"Bill Johnson","avatar":""},{"name":"Jim Siedow","avatar":""},{"name":"Bill Moseley","avatar":""},{"name":"Lou Perryman","avatar":""},{"name":"Ken Evert","avatar":""},{"name":"Harlan Jordan","avatar":""},{"name":"Kirk Sisco","avatar":""},{"name":"James N. Harrell","avatar":""},{"name":"Kinky Friedman","avatar":""},{"name":"Barry Kinyon","avatar":""},{"name":"Chris Douridas","avatar":""},{"name":"Judy Kelly","avatar":""},{"name":"John Martin Ivey","avatar":""},{"name":"Wirt Cain","avatar":""},{"name":"Dan Jenkins","avatar":""},{"name":"Tobe Hoope","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324548);
