INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tu-than-vung-texas-2', 'Tử Thần Vùng Texas 2', 'The Texas Chainsaw Massacre 2', 'tử thần vùng texas 2 the texas chainsaw massacre 2 caroline williams dennis hopper bill johnson jim siedow bill moseley lou perryman ken evert harlan jordan kirk sisco james n. harrell kinky friedman barry kinyon chris douridas judy kelly john martin ivey wirt cain dan jenkins tobe hoope ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-doi', 'Trung Đội', 'Platoon', 'https://phimimg.com/upload/vod/20231026-1/5c79406a6f137d88666b1304676dd05f.jpg', 'https://phimimg.com/upload/vod/20231026-1/cf168b0dd83eec9c6cfe7594cdb4dff4.jpg', '<p>Trung Đội mang lại cái nhìn rõ ràng hơn về cuộc chiến tranh phi nghĩa của đế quốc Mỹ tại Việt Nam. Phim khắc họa sâu sắc sự khủng hoảng cùng cực, bệ rạc của những tên lính xâm lược.Tân binh Chris Taylor (Charlie Sheen) là lính tình nguyện được điều động sang Việt Nam năm 1967, anh được bổ sung vào trung đội Bravo 6 thuộc Sư đoàn Bộ binh 25 Mỹ, vốn đã bị tiêu hao nặng sau những trận càn liên miên ở biên giới Việt Nam - Campuchia. Bravo 6 dưới quyền chỉ huy của trung úy Wolfe trẻ tuổi và chưa có kinh nghiệm trận mạc. Những cựu binh của trung đội là trung sĩ Barnes (Tom Berenger) và trung sĩ Elias (Willem Dafoe) luôn đối chọi nhau và lấn lướt quyền của trung đội trưởng.Trong một cuộc hành quân càn quét, Bravo 6 đã tràn vào ngôi làng tình nghi có ...</p>', 'Full', 1, 'single', 'completed', 17, 1986, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Tom Berenger","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Charlie Sheen","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Francesco Quinn","avatar":""},{"name":"John C. McGinley","avatar":""},{"name":"Richard Edson","avatar":""},{"name":"Kevin Dillon","avatar":""},{"name":"Reggie Johnson","avatar":""},{"name":"Keith David","avatar":""},{"name":"Johnny Depp","avatar":""},{"name":"David Neidorf","avatar":""},{"name":"Mark Moses","avatar":""},{"name":"Chris Pedersen","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Corkey Ford","avatar":""},{"name":"Corey Glover","avatar":""},{"name":"Bob Orwi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich