INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-dung-ben-toi', 'Hãy Đứng Bên Tôi', 'Stand by Me', 'https://phimimg.com/upload/vod/20231016-1/29f8095406db39b94ae6a88890f93ab4.jpg', 'https://phimimg.com/upload/vod/20231016-1/90c1032c85f8ad924cade1f4c684f66a.jpg', '<p>Muốn phiêu lưu trong rừng để tìm xác một thiếu niên mất tích, bốn cậu bé nhận ra một số sự thật về chính mình trên đường đi.</p>', 'Full', 1, 'single', 'completed', 16, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Wil Wheaton","avatar":""},{"name":"River Phoenix","avatar":""},{"name":"Jerry O''Connell","avatar":""},{"name":"Corey Feldman","avatar":""},{"name":"Kiefer Sutherland","avatar":""},{"name":"Casey Siemaszko","avatar":""},{"name":"Gary Riley","avatar":""},{"name":"Bradley Gregg","avatar":""},{"name":"Jason Oliver","avatar":""},{"name":"Marshall Bell","avatar":""},{"name":"Frances Lee McCain","avatar":""},{"name":"Bruce Kirby","avatar":""},{"name":"William Bronder","avatar":""},{"name":"Scott Beach","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"John Cusack","avatar":""},{"name":"Made","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
