INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-chuot-tai-ba', 'Thám tử chuột tài ba', 'The Great Mouse Detective', 'https://phimimg.com/upload/vod/20231016-1/5ef5e3313a385810b81a3afbf22d7829.jpg', 'https://phimimg.com/upload/vod/20231016-1/64daa007399f07f6db942066a69f72d0.jpg', '<p>Thám tử chuột tài ba (tiếng Anh: The Great Mouse Detective) là một bộ phim hoạt hình năm 1986 sản xuất bởi Hãng phim hoạt hình Disney. Là bộ phim thứ 26 của Disney, được đạo diễn bởi Burny Mattison, David Michener cùng với nhóm John Musker và Ron Clements, là đạo diễn của bộ phim Nàng Tiên Cá (1989) và Aladdin và cây đèn thần (1992). Bộ phim cũng được biết đến với tên gọi Cuộc phiêu lưu của thám tử chuộc tài ba cho bản chiếu rạp lại vào năm 1992 và Thám tử chuột Basil tài ba ở một vài quốc gia. Dàn diễn viên chính của bộ phim đều là các loài chuột sống ở thành phố Luân Đôn, Anh. Bộ phim được khởi chiếu vào ngày 2/7/1986.</p>', 'Full', 1, 'hoathinh', 'completed', 21, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Barrie Ingham","avatar":""},{"name":"Val Bettin","avatar":""},{"name":"Vincent Price","avatar":""},{"name":"Susanne Pollatschek","avatar":""},{"name":"Candy Candido","avatar":""},{"name":"Diana Chesney","avatar":""},{"name":"Eve Brenner","avatar":""},{"name":"Alan Young","avatar":""},{"name":"Basil Rathbone","avatar":""},{"name":"Ellen Fitzhugh","avatar":""},{"name":"Walker Edmiston","avatar":""},{"name":"Wayne Allwine","avatar":""},{"name":"Tony Anselmo","avatar":""},{"name":"Frank Welker","avatar":""},{"name":"Laurie Main","avatar":""},{"name":"Shani Wallis","avatar":""},{"name":"Melissa Manchester","avatar":""}]', '[{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406c