INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-cong-sieu-dang', 'Phi Công Siêu Đẳng', 'Top Gun', 'https://phimimg.com/upload/vod/20231014-1/584f7fe8d3d7345e6e7071b61cda87ab.jpg', 'https://phimimg.com/upload/vod/20231014-1/c70b7c9d99fc065d1664965d43e2415a.jpg', '<p>Tom Cruise vào vai một phi công tài ba phải vật lộn để cân bằng cuộc sống, trách nhiệm và tình cảm trong lúc đua tranh tại trường huấn luyện máy bay chiến đấu Hải Quân.</p>', 'Full', 1, 'single', 'completed', 12, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Kelly McGillis","avatar":""},{"name":"Val Kilmer","avatar":""},{"name":"Anthony Edwards","avatar":""},{"name":"Tom Skerritt","avatar":""},{"name":"Michael Ironside","avatar":""},{"name":"John Stockwell","avatar":""},{"name":"Barry Tubb","avatar":""},{"name":"Rick Rossovich","avatar":""},{"name":"Tim Robbins","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324548);
