INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-khong-gian-2', 'Quái Vật Không Gian 2', 'Aliens', 'https://phimimg.com/upload/vod/20231014-1/8de73e9f8dd51f1494040f7b46c0a195.jpg', 'https://phimimg.com/upload/vod/20231014-1/d3c0e1f2cfeaf15a48e02b11e5ac3024.jpg', '<p>Từ sau thảm họa tàu Nostromo, cùng 57 năm trôi dạt trong không gian, dường như câu chuyện về lòai quái vật ký sinh của Ripley không được Liên đòan Thương mại công nhận. Một ngày nọ, một tiểu hành tinh bỗng nhiên bị mất liên lạc hòan tòan với trái đất, để xác minh sự việc, Liên đòan cử Ripley cùng một tóan đặc nhiệm thẳng tiến đến tiểu hành tinh nọ. Cũng như số phận của những con người trên tàu Nostromo thuở nào, họ lại tiến vào địa ngục không lối thoát, đó là hành tinh xa lạ tràn ngập lũ quái vật ký sinh đang không ngừng phát triển cùng những mưu mô toan tính và lòng tham vô đáy của con người…</p>', 'Full', 1, 'single', 'completed', 16, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sigourney Weaver","avatar":""},{"name":"Michael Biehn","avatar":""},{"name":"Lance Henriksen","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Jenette Goldstein","avatar":""},{"name":"Carrie Henn","avatar":""},{"name":"Paul Reiser","avatar":""},{"name":"Mark Rolston","avatar":""},{"name":"William Hope","avatar":""},{"name":"Al Matthews","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324548);
