INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghia-cai-van-thien', 'Nghĩa Cái Vân Thiên', 'A Hearty Response', 'https://phimimg.com/upload/vod/20231013-1/c085d9c0484144b6edec50d8d2603951.jpg', 'https://phimimg.com/upload/vod/20231013-1/0db8e65de937c6161b32262685123572.jpg', '<p>Trong chiến dịch cuối cùng của họ (không thành công), cảnh sát Hong Kong Ho Ting-Bon và Long Man đã vô tình gây ra vết thương nhẹ ở đầu cho một phụ nữ còn khá trẻ. Vì đã nhập cảnh trái phép vào đất nước này và không có nơi nào khác để sinh sống, cô ấy đã giả vờ rằng mình bị mất trí nhớ và cô ấy nghĩ rằng Ting-Bon là chồng của mình. Anh ta cảm thấy tội lỗi về&nbsp;</p>', 'Full', 1, 'single', 'completed', 14, 1986, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Joey Wong","avatar":""},{"name":"David Lui","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Poon Lai-Yin","avatar":""},{"name":"Lee Heung-Kam","avatar":""},{"name":"Bill Shum Wai","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Wong Wan-Si","avatar":""},{"name":"Ying Kwan Lok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324548);
