INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-so-co-la', 'Thanh Tra Sô Cô La', 'Chocolate Inspector', 'https://phimimg.com/upload/vod/20231012-1/b92de6ab8e643c9a7ff4055ee61ef6a7.jpg', 'https://phimimg.com/upload/vod/20231012-1/c9afc53fb627959ed5128d759e30f5e9.jpg', '<p>Thanh tra Chu là một tên ngốc khi cạnh tranh với thanh tra Clouseau. Sau khi không bắt được một bãi đậu xe đầy kẻ trộm, anh bị giáng chức xuống đội tìm người mất tích, chỉ để đối mặt với vụ bắt cóc con trai ngôi sao của một chương trình nấu ăn trên truyền hình. Thanh tra Chocolate làm hỏng vụ án, không nhảy điệu tango và can thiệp vào cuộc thi Hoa hậu Hồng Kông trong nỗ lực giải quyết vụ án</p>', 'Full', 1, 'single', 'completed', 13, 1986, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Michael Hui","avatar":""},{"name":"Anita Mui","avatar":""},{"name":"Ricky Hui","avatar":""},{"name":"Sibelle Hu","avatar":""},{"name":"Roy Chiao","avatar":""},{"name":"Cheung Lai-Ping","avatar":""},{"name":"Michael Chan","avatar":""},{"name":"Lo Jun-Man","avatar":""},{"name":"Lo Jun-Git","avatar":""},{"name":"Sandra Lang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324548);
