INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('si-quan-tuba', 'Sĩ Quan Tuba', 'Where''s Officer Tuba', 'https://phimimg.com/upload/vod/20231012-1/ae8396d06d8e58a2a436aa3b29d4dc77.jpg', 'https://phimimg.com/upload/vod/20231012-1/846b279c894444384a5c379d0b44ff4b.jpg', '<p>Tuba là một cảnh sát nhút nhát, thích chơi trong ban nhạc kèn đồng của ban nhạc cảnh sát hơn là đi dạo trên đường phố. Một ngày nọ, anh thấy mình bị cuốn vào một vụ tống tiền với thám tử Rambo Chow. Khi Rambo bị trọng thương, anh đã đưa ra lời thề nửa vời là sẽ trả thù cho cái chết của mình. Tuba hơi ngạc nhiên khi linh hồn của Rambo quay trở lại để đảm bảo rằng người cảnh sát nhút nhát sẽ thực hiện lời hứa của mình. Được hỗ trợ bởi cộng sự tài năng Cheung, Tuba cuối cùng đã triệu hồi được dũng sĩ để truy tìm những kẻ xấu.</p>', 'Full', 1, 'single', 'completed', 16, 1986, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Jacky Cheung","avatar":""},{"name":"Joey Wong","avatar":""},{"name":"David Chiang","avatar":""},{"name":"Stanley Fung","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Paul Chang Chung","avatar":""},{"name":"Wu Fung","avatar":""},{"name":"Teddy Yip Wing-Cho","avatar":""},{"name":"Tai Bo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324548);
