INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-ma-dan', 'Đao Mã Đán', 'Peking Opera Blues', 'https://phimimg.com/upload/vod/20231010-1/27ede1eec4bf5493db2ed5428cfc2bef.jpg', 'https://phimimg.com/upload/vod/20231010-1/75d9edf055f6ed593c2bea1b2599775a.jpg', '<p>Tào Vân, con của Tào đốc quân, là thành viên của nhóm phiến quân. Dù cha mình là trung gian trong vụ việc vay tiền, nhưng Tào Vân dám hy sinh vì đại sự và tham gia vào vụ đánh cắp văn kiện.Trong một lần tình cờ, Tào Vân cứu thoát Hồng, cô ca sỹ đang bị quân lính lục soát giữa đường.Âm mưu đánh cắp văn kiện được cả nhóm thực hiện tại một gánh hát. Song, vì sự cố, kế hoạch đổ bể. Còn lão Bạch chủ gánh hát thì trút giận lên cô con gái, vốn không được phép lên sân khấu kinh kịch. Mối quan hệ giữa ba người nảy nở trong tình thế ngặt nghèo, trong khi kế hoạch đánh cắp văn kiện quan trọng vẫn tiếp tục.</p>', 'Full', 1, 'single', 'completed', 19, 1986, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Brigitte Lin","avatar":""},{"name":"Sally Yeh","avatar":""},{"name":"Cherie Chung","avatar":""},{"name":"Mark Cheng Ho-Nam","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Cheung Kwok-Keung","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Ku Feng","avatar":""},{"name":"Kenneth Tsang","avatar":""},{"name":"Huang Ha","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324548);
