INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tac-an-y-4', 'Đối Tác Ăn Ý 4', 'Aces Go Places 4 : You Never Die Twice', 'https://phimimg.com/upload/vod/20231006-1/07d778775e19ca087eb57d9802c76466.jpg', 'https://phimimg.com/upload/vod/20231006-1/7edfdae6fb9678af3dcc35697b194cb0.jpg', '<p>Một nhà khoa học già ở New Zealand đã phát minh ra một lăng kính tên là &quot;Sirius&quot;, có thể kích hoạt tiềm năng của một người và phát triển siêu năng lực đáng kinh ngạc. Tuy nhiên, phát minh này sớm bị các băng nhóm địa phương nhắm đến. Họ tấn công phòng thí nghiệm và giết chết nhà khoa học. Vào thời điểm quan trọng, Sirius bị chàng thanh niên Jin Gang tham gia thí nghiệm và con gái của nhà khoa học, Sally, bắt đi. Sau khi trở về Hồng Kông, Jin Gang nhờ thám tử Hói giúp đỡ. Bất ngờ thay, các băng nhóm truy đuổi và bắt vợ của Bald làm con tin. Để cứu người vợ yêu dấu của mình, Bald đưa con trai của mình và cùng Jin Gang thực hiện hành trình tới New Zealand...</p>', 'Full', 1, 'single', 'completed', 21, 1986, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sam Hui","avatar":""},{"name":"Karl Maka","avatar":""},{"name":"Sally Yeh","avatar":""},{"name":"Sylvia Chang","avatar":""},{"name":"Cyrus Wong Ka-Ming","avatar":""},{"name":"Sek Kin","avatar":""},{"name":"Kwan Tak-Hing","avatar":""},{"name":"Walter Tso Tat-Wah","avatar":""},{"name":"Roy Chiao","avatar":""},{"name":"Pomson Shi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324548);
