INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tu-khoa-than', 'Nhà Tù Khỏa Thân', 'The Naked Cage', 'https://phimimg.com/upload/vod/20230922-1/4a6c7c22dfb0d5ac02863103699bb010.jpg', 'https://phimimg.com/upload/vod/20230922-1/a8a9da796865bf909363dcfde5ae9330.jpg', '<p>Một phụ nữ trẻ bị kết tội oan về một vụ cướp ngân hàng và bị đưa đến một nhà tù an ninh tối đa do một quản giáo tham nhũng điều hành, nơi cô buộc phải chịu đựng nhiều sự phẫn nộ khác nhau.</p>', 'Full', 1, 'single', 'completed', 20, 1986, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Shari Shattuck","avatar":""},{"name":"Angel Tompkins","avatar":""},{"name":"Lucinda Crosby","avatar":""},{"name":"Stacey Shaffer","avatar":""},{"name":"Christina Whitaker","avatar":""},{"name":"Nick Benedict","avatar":""},{"name":"John Terlesky","avatar":""},{"name":"Faith Minton","avatar":""},{"name":"Aude Charles","avatar":""},{"name":"Angela Elayne Gibbs","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
