INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-bao-thu', 'Thiên Thần Báo Thù', 'The Seven Angels', 'https://phimimg.com/upload/vod/20260308-1/885cd256f1349ce128198a28a6cf16d8.jpg', 'https://phimimg.com/upload/vod/20260308-1/469ac539b78ce5033c52133740f7c510.jpg', '<p>Bảy nữ cảnh sát vốn đang trong diện bị đình chỉ công tác bao gồm: Gái Hào Phóng, Nữ Giáo Đồ, Ái Kim (Mê Tiền), Sherlock Holmes, Lục Xích Tam (Cao 1m9), Phì Muội (Cô Nàng Béo) và đội trưởng Càng Cua. Họ được giao một nhiệm vụ bí mật: Cải trang thành những tiếp viên tại một hộp đêm phong cách Nhật Bản để truy tìm một kẻ sát nhân biến thái chuyên nhắm vào phụ nữ.&nbsp; Tại hộp đêm &#39;Tội Ác Thành&#39;, nhóm nữ cảnh sát liên tục bị QE – &#39;má mì&#39; quyền lực nhất ở đó – gây khó dễ và chèn ép. Trong đêm quảng bá bảng xếp hạng &#39;Long Phụng&#39;, đội trưởng Càng Cua ra lệnh cho cả nhóm phải dốc toàn lực để lôi kéo khách hàng nhằm thu thập manh mối.&nbsp; Lợi dụng sơ hở, Đại Chi Cường (em trai của QE) đã dụ dỗ Gái Hào Phóng ra ngoài với cái cớ chụp ảnh. Tại đây, hắn lộ nguyên hình là kẻ biến thái, định giở trò đồi bại và quay lại cảnh giết người để làm kỷ niệm. Ngay trong khoảnh khắc nghìn cân treo sợi tóc, nhóm nữ cảnh sát đã kịp thời ập đến để giải cứu đồng đội và vạch trần bộ mặt thật của kẻ thủ ác.</p>', 'Full', 1, 'single', 'completed', 23, 1985, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Deanie Ip","avatar":""},{"name":"Richard Ng Man-Tat","avatar":""},{"name":"Tsang Kwok-Chi","avatar":""},{"name":"Bolo Yeung","avatar":""},{"name":"Roy Cheung Yiu-Yeung","avatar":""},{"name":"Lo Hoi-Pang","avatar":""},{"name":"Benz Hui Siu-Hung","avatar":""},{"name":"Elaine Jin Yan-Ling","avatar":""},{"name":"Meg Lam Kin-Ming","avatar":""},{"name":"Gam Biu","avatar":""},{"name":"Hui Ying-Sau","avatar":""},{"name":"Chong Man-Ching","avatar":""},{"name":"Walter Tso Tat-Wah","avatar":""},{"name":"Yu Chi-Ming","avatar":""},{"name":"Yu Miu-Lin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["歡場"]', 1784690324548);
