INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-pho-elm-2-su-tra-thu-cua-freddy', 'Ác Mộng Phố Elm 2: Sự Trả Thù Của Freddy', 'A Nightmare on Elm Street Part 2: Freddy''s Revenge', 'https://phimimg.com/upload/vod/20260206-1/91ba14cb04eee3327cc9acfa050cc54f.jpg', 'https://phimimg.com/upload/vod/20260206-1/e412ce2f83920705482bc12733b40d13.jpg', '<p>Jesse Walsh cùng gia đình chuyển đến ngôi nhà của người sống sót duy nhất sau một loạt các cuộc tấn công của quái vật rình rập trong mơ, Freddy Krueger. Ở đó, anh bị ám ảnh bởi những cơn ác mộng và những xung lực bạo lực không thể giải thích được.</p>', 'Full', 1, 'single', 'completed', 20, 1985, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robert Englund","avatar":""},{"name":"Mark Patton","avatar":""},{"name":"Kim Myers","avatar":""},{"name":"Robert Rusler","avatar":""},{"name":"Clu Gulager","avatar":""},{"name":"Hope Lange","avatar":""},{"name":"Marshall Bell","avatar":""},{"name":"Melinda O. Fee","avatar":""},{"name":"Tom McFadden","avatar":""},{"name":"Sydney Walsh","avatar":""},{"name":"Edward Blackoff","avatar":""},{"name":"Christie Clark","avatar":""},{"name":"Lyman Ward","avatar":""},{"name":"Donna Bruce","avatar":""},{"name":"Hart Sprager","avatar":""},{"name":"Allison Barron","avatar":""},{"name":"JoAnn Willette","avatar":""},{"name":"Steve Eastin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Painajainen Elm Streetillä 2 – Freddyn kosto","A Nightmare on Elm Street - Freddy''s Revenge","Pesadilla en Elm Street 2: La venganza de Freddy","Pesadilla en Elm Street 2: La venganza de Freddy : 1985","猛鬼街2","Freddy - Chapitre 2 - La Revanche de Freddy","Nightmare on Elm Street 2 - Die Rache","Pesadilla en la Calle Elm 2 La Venganza de Freddy","A Nightma