INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-canh-sat', 'Câu Chuyện Cảnh Sát', 'Police Story', 'https://phimimg.com/upload/vod/20251222-1/a9ead2119182811f108768ce19eaa84a.jpg', 'https://phimimg.com/upload/vod/20251222-1/4ee4f8ffc8c7c0153ec60119ac835e8c.jpg', '<p>Nội dung của phim Câu Chuyện Cảnh Sát bắt đầu từ việc Thanh tra cảnh sát Trần Gia Câu được lệnh bảo vệ một nhân chứng quan trọng là Salina, thư kí của tay trùm ma túy Chu Thao, trong một vụ kiện tố cáo y. Tuy nhiên Trần Gia Câu không ngờ rằng anh đã bị Chu Thao gài bẫy vào một vụ giết người. Để giải oan cho mình Trần Gia Câu buộc phải một mình đi tìm bằng chứng và đối đầu với toàn bộ băng đảng của Chu Thao.Trong Phim, Trần Gia Câu phải một mình chống lại cả băng đảng, chúng ta sẽ thấy được những pha hành động hết sức mạo hiểm của nam diễn viên, những màn đấu võ, rượt đuổi đậm chất Hollywood xen lẫn vào đó là những tình tiết hài hước đúng chất của Thành Long.</p>', 'Full', 1, 'single', 'completed', 20, 1985, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Brigitte Lin","avatar":""},{"name":"Maggie Cheung","avatar":""},{"name":"Bill Tung Biu","avatar":""},{"name":"Chor Yuen","avatar":""},{"name":"Charlie Cho Cha-Lee","avatar":""},{"name":"Lam Kwok-Hung","avatar":""},{"name":"Kam Hing-Yin","avatar":""},{"name":"Mars","avatar":""},{"name":"Kent Tong","avatar":""},{"name":"David Lau Chi-Wing","avatar":""},{"name":"Wan Fat","avatar":""},{"name":"Fung Hak-On","avatar":""},{"name":"Tai Bo","avatar":""},{"name":"Lau Nga-Lai","avatar":""},{"name":"Wan Ling-Kwong","avatar":""},{"name":"Woo Fung","avatar":""},{"name":"Winnie Yu Ching","avatar":""},{"name":"Clarence Ford","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Ging chaat goo si","Jackie Chan''s Police Story","Police Force","Jackie Chan''s Police Force","Arrebentando Hong Kong","Police Story 1","Jing cha gu shi","Pulis Kee Kahaanee","ポリス･ストーリー / 香港国際警察","El protector 2 (Historia policial)","Policijska zgodba","Kanun Namına","Jackie Chan - Police Story","I epistrofi tou Kinezou","Policyjna opowieść","Police Story: A Guerra das Drogas","警察故事"]', 1784690324548);
