INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-canh-sat', 'Câu Chuyện Cảnh Sát', 'Police Story', 'câu chuyện cảnh sát police story jackie chan brigitte lin maggie cheung bill tung biu chor yuen charlie cho cha-lee lam kwok-hung kam hing-yin mars kent tong david lau chi-wing wan fat fung hak-on tai bo lau nga-lai wan ling-kwong woo fung winnie yu ching clarence ford thành long ging chaat goo si jackie chan''s police story police force jackie chan''s police force arrebentando hong kong police story 1 jing cha gu shi pulis kee kahaanee ポリス･ストーリー / 香港国際警察 el protector 2 (historia policial) policijska zgodba kanun namına jackie chan - police story i epistrofi tou kinezou policyjna opowieść police story: a guerra das drogas 警察故事', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-xe-den-phan-4', 'Hiệp Sĩ Xe Đen (Phần 4)', 'Knight Rider (Season 4)', 'https://phimimg.com/upload/vod/20251208-1/b89f1695422535cc7388f5b9cdcc64d0.jpg', 'https://phimimg.com/upload/vod/20251208-1/19a0f591ace85d6c8ca2a934fc63a0f6.jpg', '<p><span style="text-wrap-mode: wrap;">Michael Long, một sĩ quan cảnh sát chìm, bị bắn trọng thương trong lúc điều tra và bị những kẻ tấn công bỏ mặc cho đến chết.Anh được cứu bởi Wilton Knight, một triệu phú sắp qua đời và là nhà phát minh giàu có. Wilton đã sắp xếp một cuộc phẫu thuật cứu mạng cho Michael, bao gồm một khuôn mặt mới và một danh tính mới—là Michael Knight.Michael sau đó được giao một chiếc xe đặc biệt, không thể phá hủy và được trang bị máy tính hóa, gọi là Knight Industries Two Thousand (thường được gọi là KITT), cùng với một nhiệm vụ: bắt giữ những tên tội phạm nằm ngoài tầm với của pháp luật.Bộ phim mô tả các cuộc phiêu lưu của Michael khi anh và KITT chiến đấu với các thế lực tà ác dưới danh nghĩa Quỹ Luật pháp và Chính phủ.</span></p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 20, 1985, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Hasselhoff","avatar":""},{"name":"Edward Mulhare","avatar":""},{"name":"William Daniels","avatar":""},{"name":"Patricia McPherson","avatar":""},{"name":"Peter Parros","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hình Sự","slug":"hinh-su"