INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-le-cua-quy-co-reijo-nikudorei', 'Nô Lệ Của Quý Cô (Reijo niku-dorei)', 'On The Beach', 'https://phimimg.com/upload/vod/20250727-1/7cc66f2d28c84a75aab9c6fdc5784bbd.jpg', 'https://phimimg.com/upload/vod/20250727-1/c4fcf5d0b5a620bc78dfa100f83876de.jpg', '<p>Vào một mùa hè ở làng Shonan, Sumiko, con gái của gia tộc quyền quý Shikishima, yêu thích hội họa và đang trải qua khoảng thời gian nguôi ngoai sau cuộc hôn nhân sắp đặt thất bại. Tuy nhiên, cô lại bị thu hút bởi Nishina, một người đàn ông thô lỗ và thô tục. Trong khi đó, em gái Naomi luôn ghen tị với vẻ đẹp của chị, tự thấy mình xấu xí vì mọi đàn ông đều thích Sumiko. Cả hai chị em rồi cũng vướng vào một rắc rối lớn khi phát hiện ra ý đồ thật sự của Nishina — kẻ giấu mình sau lớp mặt nạ để cưỡng đoạt phụ nữ.</p>', 'Full', 1, 'single', 'completed', 25, 1985, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rei Akasaka","avatar":""},{"name":"Aki Hayasaka","avatar":""},{"name":"Hideaki Tezuka","avatar":""},{"name":"Sadami Sakamoto","avatar":""},{"name":"Ranko Mizuki","avatar":""},{"name":"Rena Kuroki","avatar":""},{"name":"赤坂丽","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Daughter Meat Slave","Reijo niku-dorei","Reijo nikudorei","Reijō niku dorei","Young Flesh Slave","영양육노예","深闺性奴","令嬢肉奴隷"]', 1784690324548);
