INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thanh-cua-thanh-pho-ngam', 'Âm thanh của thành phố ngầm', 'Subway', 'https://phimimg.com/upload/vod/20250710-1/82e3062ca9d2c96cdee5bdfb76c72cdd.jpg', 'https://phimimg.com/upload/vod/20250710-1/68ef054285f36ca625826ef4db685200.jpg', '<p>Fred (Christopher Lambert) là một tên trộm chuyên nghiệp. Sau khi đánh cắp một số tài liệu nhạy cảm tại một buổi tiệc của giới thượng lưu, anh bị truy đuổi dữ dội. Trong cảnh rượt đuổi kịch tính đầu phim, Fred nhảy xuống đường tàu điện ngầm Paris và lẩn vào trong mê cung của hệ thống Metro đầy bóng tối và bí ẩn.</p>', 'Full', 1, 'single', 'completed', 19, 1985, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Isabelle Adjani","avatar":""},{"name":"Christopher Lambert","avatar":""},{"name":"Richard Bohringer","avatar":""},{"name":"Michel Galabru","avatar":""},{"name":"Jean-Hugues Anglade","avatar":""},{"name":"Jean-Pierre Bacri","avatar":""},{"name":"Jean Bouise","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Jean-Claude Lecas","avatar":""},{"name":"Pierre-Ange Le Pogam","avatar":""},{"name":"Éric Serra","avatar":""},{"name":"Arthur Simms","avatar":""},{"name":"Michel D''Oz","avatar":""},{"name":"Alain Guillard","avatar":""},{"name":"Jimmy Blanche","avatar":""},{"name":"Be","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["花都夜深沉","Метро","Subway"]', 1784690324548);
