INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-thanh-cua-thanh-pho-ngam', 'Âm thanh của thành phố ngầm', 'Subway', 'âm thanh của thành phố ngầm subway isabelle adjani christopher lambert richard bohringer michel galabru jean-hugues anglade jean-pierre bacri jean bouise jean reno jean-claude lecas pierre-ange le pogam éric serra arthur simms michel d''oz alain guillard jimmy blanche be 花都夜深沉 метро subway', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuong-thi-tien-sinh', 'Cương Thi Tiên Sinh', 'Mr. Vampire', 'https://phimimg.com/upload/vod/20250603-1/8e2bf9d78858b61bb3eea121e75fc6be.jpg', 'https://phimimg.com/upload/vod/20250603-1/eb57b166b8b0c3451406a2979f9c98da.jpg', '<p>Sư phụ Kau là một thầy pháp trừ tà sống cùng với hai đệ tử là Ho và Dan. Ho với vẻ ngoài đẹp trai, bay bướm nhưng rất nghịch phá, còn Dan tuy khờ khạo, nhát gan nhưng vô cùng tốt bụng. Một lần Sư phụ Kau đã đồng ý thực hiện mai táng cho cha của Yam lão gia-một thương nhân giàu có. Ông đã cùng với Ho và Dan đến mộ làm pháp sự nhưng sư phụ Kau cũng đã phát hiện xác chết gần như nguyên vẹn và trông có vẻ còn sống. Sư phụ Kau muốn thiêu xác nhưng ông Yam ko đồng ý, vì vậy ông mới đem cái xác về nhà mình và làm pháp sự để ngăn chặn xác chết sống dậy nhưng đã thất bại. Xác chết đó thành cương thi và giết ông Yam. Còn sư phụ Kau bị hiểu lầm đã giết ông Yam nên ông bị sếp Wai bắt giam cùng với xác Yam lão gia, đêm đó Yam lão gia thànnh cương thi nhưng nhờ có sự phối hợp giữa Ho va sư phụ Kau, Yam cương thi bị thiêu.</p>', 'Full', 1, 'single', 'completed', 24, 1985, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Lam Ching-Ying","avatar":""},{"name":"Ricky Hui Koon-Ying","avatar":""},{"name":"Chin Siu-Ho","avatar":""},{"name":"Moon Lee Choi-Fung","avatar":""},{"name":"Huang Ha","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Pauline Wong","avatar":""},{"name":"Billy Lau Nam-Kwong","avatar":""},{"name":"Anthony Chan Yau","avatar":""},{"name":"Ka Lee","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Wong Wan-Sze","avatar":""},{"name":"Tenky Tin Kai-Man","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"Chan Ming-Wai","avatar":""},{"name":"Chow Gam-Kong","avatar":""},{"name":"Yuen Miu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Mr. Stiff Corpse","Jiang shi xian sheng","Geung si sin sang","Mr. Vampire (El señor de los vampiros)","Mr. Vampire","僵尸先生","殭屍先生"]', 1784690324548);
