INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-cuoc-chien-vu-tru', 'Doraemon: Nobita và Cuộc Chiến Vũ Trụ', 'Doraemon: Nobita''s Little Star Wars', 'https://phimimg.com/upload/vod/20250521-1/2ef26e7412956778068b294483031f7d.jpg', 'https://phimimg.com/upload/vod/20250521-1/1a82bfa24e5eb984e41acbbdc19724d3.jpg', '<p>Papi, vị tổng thống nhỏ bé của một hành tinh xa xôi, trốn thoát đến Trái đất để tránh bị bắt bởi lực lượng quân sự đã chiếm giữ đất nước. Mặc dù được chào đón bởi Doraemon, Nobita và bạn bè của họ, người ngoài hành tinh nhỏ bé nhận thấy rằng kẻ thù của mình cũng đã đến trái đất nên không muốn để những người bạn của mình tham gia vào cuộc chiến này. Doraemon, Nobita, Gian, Suneo và Shizuka bắt đầu một cuộc phiêu lưu mới khi họ cố gắng che giấu và bảo vệ Papi.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 1985, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Sachiko Chijimatsu","avatar":""},{"name":"Dai Kanai","avatar":""},{"name":"Keiko Han","avatar":""},{"name":"Yuji Mitsuya","avatar":""},{"name":"Yusaku Yara","avatar":""},{"name":"Ryusei Nakao","avatar":""},{"name":"Sumiko Shirakawa","avatar":""},{"name":"Masako Matsubara","avatar":""},{"name":"Nobuo Yana","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["宇宙小戰爭","Nobita''s Little Star Wars","Doraemon Nobita no Ritoru Suta Wozu","Doraemon in Nobita''s Little Space Wars","โดราเอมอน ตอน สงครามอวกาศ","哆啦A夢：大雄的宇宙小戰爭","도라에몽: 노비타의 우주소전쟁","Doraemon Nobita''s Little Space Wars","doremon va ten doc tai vu tru","電影哆啦A夢：大雄與宇宙小戰爭","映画ドラえもん のび太の宇宙小戦争"]', 1784690324548);
