INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-cuoc-chien-vu-tru', 'Doraemon: Nobita và Cuộc Chiến Vũ Trụ', 'Doraemon: Nobita''s Little Star Wars', 'doraemon: nobita và cuộc chiến vũ trụ doraemon: nobita''s little star wars nobuyo oyama noriko ohara kazuya tatekabe kaneta kimotsuki michiko nomura sachiko chijimatsu dai kanai keiko han yuji mitsuya yusaku yara ryusei nakao sumiko shirakawa masako matsubara nobuo yana 宇宙小戰爭 nobita''s little star wars doraemon nobita no ritoru suta wozu doraemon in nobita''s little space wars โดราเอมอน ตอน สงครามอวกาศ 哆啦a夢：大雄的宇宙小戰爭 도라에몽: 노비타의 우주소전쟁 doraemon nobita''s little space wars doremon va ten doc tai vu tru 電影哆啦a夢：大雄與宇宙小戰爭 映画ドラえもん のび太の宇宙小戦争', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-re-trai-tren-duong-mon', 'Lối Rẽ Trái Trên Đường Mòn', 'The Left Turn On The Trail', 'https://phimimg.com/upload/vod/20250406-1/4d2bca41f85c1de0efe334f9ee4977c2.jpg', 'https://phimimg.com/upload/vod/20250406-1/f97810344ade81ea32efd9990b99d60a.jpg', '<p>Lối Rẽ Trên Đường Mòn&quot; là một bộ phim Việt Nam do đạo diễn Huy Thành thực hiện, với kịch bản của Nguyễn Mạnh Tuấn. Phim có sự tham gia của các diễn viên Lâm Tới, Kim Thành và Kim Chi. Bộ phim kể về hành trình của những con người đứng trước những ngã rẽ quan trọng trong cuộc đời. Trong bối cảnh xã hội đầy biến động, các nhân vật phải đối mặt với những lựa chọn khó khăn, đòi hỏi sự dũng cảm và quyết đoán. Với diễn xuất chân thực của dàn diễn viên tài năng, &quot;Lối Rẽ Trên Đường Mòn&quot; mang đến cho khán giả những cảm xúc sâu lắng và suy ngẫm về những quyết định trong cuộc sống. Trong &quot;Lối Rẽ Trên Đường Mòn&quot;, yếu tố chiến tranh được khắc họa một cách chân thực, phản ánh những biến động xã hội và cuộc đấu tranh sinh tồn của con người trong thời kỳ loạn lạc. Bộ phim không chỉ mô tả chiến tranh như một bối cảnh đơn thuần, mà còn đi sâu vào những tác động của nó đến từng nhân vật, từ những người lính, người dân thường cho đến những kẻ phản bội và cơ hội.</p>', 'Full', 1, 'single', 'completed', 18, 1985, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lâm Tới","avatar":""},{"name":"Kim Thanh","avatar":""},{"name":"Kim Chi","avatar":""},{"name":"Lê Cung Bắc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324548);
