INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-lai-mot-minh', 'Còn Lại Một Mình', 'Still Left Alone', 'https://phimimg.com/upload/vod/20250406-1/0ce9e207e756c0fab76dc1eea21f2a8f.jpg', 'https://phimimg.com/upload/vod/20250406-1/4018d32d12025a23e5af3ef7081a0981.jpg', '<p>“Còn lại một mình” là bộ phim lịch sử Việt Nam của đạo diễn Hồng Sến, với sự tham gia của các diễn viên Phương Thanh, Quốc Hùng, Robert Hải… Bộ phim khắc họa những bi kịch, mất mát trong chiến tranh, tập trung vào số phận những con người bị cuốn vào vòng xoáy lịch sử. Với phong cách đặc trưng của Hồng Sến, phim không chỉ tái hiện chân thực bối cảnh thời chiến mà còn đào sâu vào tâm lý nhân vật, phản ánh sự cô độc, đau thương và ý chí kiên cường của con người trong thời khắc khó khăn. &quot;Còn lại một mình&quot; mang đến câu chuyện đầy cảm xúc, để lại ấn tượng sâu sắc về giá trị của tình người và sự hy sinh.</p>', 'Full', 1, 'single', 'completed', 16, 1985, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Phương Thanh","avatar":""},{"name":"Quốc Hùng","avatar":""},{"name":"Robert Hải","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324548);
