INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-lang-tu', 'Giang Hồ Lãng Tử', 'The Young Wanderer', 'https://phimimg.com/upload/vod/20240623-1/307b961781898072237c8f501529f85c.jpg', 'https://phimimg.com/upload/vod/20240623-1/bba68a964dacc882787b04c9e22d6fcf.jpg', '<p><em>Dịch Thủy Hàn cùng thuật sĩ giang hồ Quách Thành Công kết bạn hành tẩu giang hồ, sống bằng việc lừa đảo. Một lần bị hiểu lầm liên quan đến 1 vụ án nên bị Nam Cung Thế Gia đuổi bắt, được Bang chủ cái bang Đào Nhât Túy gíup đỡ, cũng vì thế mà đã cũng để tử của Nam Cung Tống Hiểu Dương và Nguyễn Hồng Diệp kết thành bằng hữu. Đào Nhất Túy điều tra vụ cướp do Tam đại hộ pháp Ma giáo gây ra nên xuất lĩnh quần hùng tiêu diệt Ma Giáo may mắn cứu được Ngũ Đại cao thủ võ lâm.</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 20, 1985, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Huỳnh Nhật Hoa","avatar":""},{"name":"Lưu Gia Linh","avatar":""},{"name":"Trang Tịnh Nhi","avatar":""},{"name":"Liêu Khải Trí","avatar":""},{"name":"Dung Tuệ Văn","avatar":""},{"name":"Tần Bái","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324548);
