INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loan', 'Loạn', 'Ran', 'https://phimimg.com/upload/vod/20240228-1/073b378a62c72512c7563e207c7e46a4.jpg', 'https://phimimg.com/upload/vod/20240228-1/2b091b26eab30231cc2706422e2ad6a8.jpg', '<p>Bối cảnh phim là một thời Chiến quốc giả tưởng, sau khi Ichimonji Hidetori lần lượt đánh chiếm hết 3 thành trì bên địch và trở thành đại lãnh chúa của cả vùng. Một ngày nọ, nhân buổi đi săn, Hidetora bất ngờ thông cáo cho các quan khách rằng mình sẽ nhường ngôi vị lại cho con trưởng, còn bản thân thì về ẩn cư. Hidetora lấy 3 mũi tên, bảo với con trai rằng, 1 mũi tên thì dễ bẻ nhưng gọp 3 mũi lại thì không thể bẻ được. Nhưng con trai út thấy thế lại chê cha già lẩm cẩm, dùng sức bẻ gãy cả ba mũi tên. Cảm thấy mất mặt trước các quan khách, Hidetori nổi giận đuổi con trai út đi rồi về làm phận khách tại thành trì của con trưởng. Và cũng bắt đầu từ đây, sự thực hư trong lòng hiếu thảo của từng người con được bộc lộ, dẫn đến mối tranh chấp, bất hòa của cả dòng họ Ichimonji...</p>', 'Full', 1, 'single', 'completed', 20, 1985, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tatsuya Nakadai","avatar":""},{"name":"Akira Terao","avatar":""},{"name":"Jinpachi Nezu","avatar":""},{"name":"Daisuke Ryu","avatar":""},{"name":"Mieko Harada","avatar":""},{"name":"Yoshiko","avatar":""},{"name":"Miyazaki","avatar":""},{"name":"Peter","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
