INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-meo', 'Mắt Mèo', 'Cat''s Eye', 'https://phimimg.com/upload/vod/20240228-1/80bbe007770b97f2aa0cbfa6c9750b6e.jpg', 'https://phimimg.com/upload/vod/20240228-1/69bdfc383669d1adf2dbf39da41c4a04.jpg', '<p>Ba truyện ngắn của người gây sốc Stephen King được liên kết bởi một con mèo hoang lang thang từ câu chuyện này sang câu chuyện khác trong bộ ba bức tranh rùng rợn này bắt đầu khi Dick (James Woods) cố gắng bỏ thuốc lá bằng mọi cách cần thiết. Tiếp theo, chúng ta gặp Johnny, một người đàn ông ngoại tình bị chồng của người yêu ép lên một mỏm đá nguy hiểm của tòa nhà. Cuối cùng, Amanda bị đe dọa bởi một gã lùn độc ác, kẻ gây nghi ngờ cho con mèo của gia đình.</p>', 'Full', 1, 'single', 'completed', 19, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Drew Barrymore","avatar":""},{"name":"James Woods","avatar":""},{"name":"Alan King","avatar":""},{"name":"Kenneth McMillan","avatar":""},{"name":"Robert Hays","avatar":""},{"name":"Candy Clark","avatar":""},{"name":"James Naughton","avatar":""},{"name":"Tony Munafo","avatar":""},{"name":"James Rebhorn","avatar":""},{"name":"Mary D''Arcy","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324548);
