INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-ong-di-giay-do', 'Người Đàn Ông Đi Giày Đỏ', 'The Man With One Red Shoe', 'https://phimimg.com/upload/vod/20240228-1/4eb69a937b1121ed06fe5cdd7034617c.jpg', 'https://phimimg.com/upload/vod/20240228-1/af9cdfa8d38377f68be753436f70edf0.jpg', '<p>Người Đàn Ông Đi Giày Đỏ - The Man With One Red Shoe là một bộ phim hài 1985 của đạo diễn Stan Dragoti và đây là một phiên bản làm lại của bộ phim Pháp 1972 Le Grand Blond avec une chaussure noire. Một quan chức chính phủ Cooper (Dabney Coleman) tham gia một trò chơi kinh tởm để chiếm ưu thế trước đối thủ của mình với hy vọng được thăng tiến. Nghệ sĩ violin khiêm tốn Richard (Tom Hanks) bị chọn làm quân cờ trong trò chơi và bị gán là đã tham gia vào hoạt động gián điệp quốc tế. Cooper đưa nhân viên hàng đầu của mình, đặc vụ tuyệt đẹp Maddy (Lori Singer) đế quyến rũ Richard. Thật đáng buồn, anh chàng nhạc sĩ ngây không biết gì về âm mưu chính trị và luôn tin rằng anh đã gặp một nửa của trái tim mình.</p>', 'Full', 1, 'single', 'completed', 23, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Lori Singer","avatar":""},{"name":"Dabney Coleman","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324548);
