INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('silverado', 'Silverado', 'Silverado', 'null', 'https://phimimg.com/upload/vod/20240219-1/9e05a6a95ab45a4c9edc51ca9388d12a.jpg', '<p>Đến một thị trấn nhỏ để tìm vận may, nhóm cao bồi Viễn Tây tinh quái và tạp nham đụng độ với bọn lãnh đạo biến chất và những kẻ thù trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 38, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Kline","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Kevin Costner","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Điển","slug":"kinh-dien","id":"268385d0de78827ff7bb25c35036ee2a"}]', '[]', 1784690324548);
