INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cop-busters', 'Cop Busters', 'Cop Busters', 'null', 'https://phimimg.com/upload/vod/20240207-1/fe1d3827792ecc55d0c4eee558f69a45.jpg', '<p>Cảnh sát giao thông Gou-Hung và Dai-Jo là hai kẻ lập dị. Họ bị giáng cấp xuống bộ phận xe kéo do hoạt động kém. Cả hai tìm thấy cô gái đáng thương Bun trong lúc hành động và quyết định tạm thời đưa cô vào nhà và thông báo cho dì Marry của Bun để đến Hồng Kông. Gou-Hung và Bun trở thành bạn bè theo thời gian, nhưng Dai-Jo nhầm hành động của Mary là thể hiện tình yêu, khiến mối quan hệ giữa bốn người trở nên khó xử…</p>', 'Full', 1, 'single', 'completed', 19, 1985, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Kent Cheng","avatar":""},{"name":"Wong Ching","avatar":""},{"name":"Yang Qun","avatar":""},{"name":"Elaine Jin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324548);
