INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phat-minh-ky-quai', 'Phát Minh Kỳ Quái', 'Weird Science', 'https://phimimg.com/upload/vod/20240228-1/02ef7cb3c3195dd57a11e1c7765458b7.jpg', 'https://phimimg.com/upload/vod/20240228-1/06302ff0aa9af18af4013887108f4850.jpg', '<p>Weird Science (Phát minh kỳ quái) là câu chuyện về hai cậu học sinh Gary Wallace và Wyatt Donnelly, do thường xuyên bị làm nhục bởi các học sinh lớp trên và cũng mong muốn có được một cô bạn gái xinh đẹp, hai cậu quyết định dùng công nghệ máy tính để tạo ra một phụ nữ từ một cô búp bê. Họ quyết định người phụ nữ được tạo phải thật đẹp và giỏi với ngoại hình, năng khiếu, trí tuệ được lấy mẫu từ những người tuyệt vời trên thế giới. Tuy nhiên việc này cần có một năng lượng rất lớn và hai cậu phải xâm nhập vào hệ thống máy tính quốc gia để lấy cắp. Việc chuyển tải nguồn năng lượng cực kỳ lớn tập trung về cô búp bê đã gây nên hiệu ứng kinh khủng không ngờ, kết quả là một cô gái siêu việt được tạo thành…</p>', 'Full', 1, 'single', 'completed', 10, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anthony Michael Hall","avatar":""},{"name":"Kelly LeBrock","avatar":""},{"name":"Ilan Mitchell-Smith","avatar":""},{"name":"Bill Paxton","avatar":""},{"name":"Suzanne Snyder","avatar":""},{"name":"Judie Aronson","avatar":""},{"name":"Robert Rusler","avatar":""},{"name":"Robert Downey Jr.","avatar":""},{"name":"Steve James","avatar":""},{"name":"Vernon Wells","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324548);
