INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-chung-1985', 'Nhân Chứng', 'Witness', 'https://phimimg.com/upload/vod/20240205-1/6413d6d5c965a148b2200c1082e36c78.jpg', 'https://phimimg.com/upload/vod/20240205-1/3e6775afb506c4e6cc0f410a2f12e7c0.jpg', '<p>Một đứa trẻ Amish được che chở là nhân chứng duy nhất của một vụ giết người tàn bạo trong nhà vệ sinh ở nhà ga xe lửa Philadelphia, và cậu phải được bảo vệ. Nhiệm vụ được giao cho một thám tử lầm lì hoạt động bí mật trong một cộng đồng người Hà Lan ở Pennsylvania. Trong trang trại, anh dần dần hòa nhập bất chấp bản tính thành thị của mình và tạo nên mối quan hệ lãng mạn với người mẹ xinh đẹp của đứa trẻ.</p>', 'Full', 1, 'single', 'completed', 10, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Kelly McGillis","avatar":""},{"name":"Josef Sommer","avatar":""},{"name":"Lukas Haas","avatar":""},{"name":"Jan Rubeš","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324548);
