INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-hay-mo', 'Chàng Trai Hay Mơ', 'Brazil', 'https://phimimg.com/upload/vod/20240220-1/948bb06ca52ad6762c714500e771e642.jpg', 'https://phimimg.com/upload/vod/20240220-1/3178fc0e4ecbcbddbf8dc5e150ac4247.jpg', '<p>Một bộ phim lạ thường và đầy ám ảnh của đạo diễn Terry Gilliam. Brazil kể về một thế giới tương lai siêu thực đen tối, bối cảnh của phim là một xã hội retro-future, nơi mà các chiến dịch đánh bom khủng bố chống chính quyền đã diễn ra 13 năm qua. Sam Lowry (Jonathan Pryce), nhân vật chính là một kĩ thuật viên/một công chức thiếu tham vọng. Ham muốn duy nhất của Sam đó là thoát khỏi kĩ thuật công nghệ và sự đàn áp của bộ máy chính quyền để đến với giấc mơ của mình: trong giấc mơ đó, Sam đóng vai hiệp sĩ đi cứu cô gái trong mơ. Rồi một lần, trong khi đi sửa lại một cuộc bắt người nhầm của giới cầm quyền, Sam đã vô tình gặp Jill Layton (Kim Greist), cô gái vẫn xuất hiện trong mơ giấc mơ của anh, rắc rối bắt đầu nảy sinh từ đó...</p>', 'Full', 1, 'single', 'completed', 12, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jonathan Pryce","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Katherine Helmond","avatar":""},{"name":"Ian Holm","avatar":""},{"name":"Bob Hoskins","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324548);
