INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vac-dau-den', 'Vạc Dầu Đen', 'The Black Cauldron', 'https://phimimg.com/upload/vod/20240104-1/51e9d4f0377447520a319dd6c015ebc2.jpg', 'https://phimimg.com/upload/vod/20240104-1/a6d1fd98880c2a839aa1ddc497458ab5.jpg', '<p>The Black Cauldron (Vạc dầu đen) là bộ phim hoạt hình thứ 25 của hãng hoạt hình Walt Disney vào năm 1985, dựng dựa trên cuốn tiểu thuyết cùng tên của nhà văn Lloy Alexander. Ted Berman vã Richard Rich đã cùng nhau viết kịch bản và đạo diễn bộ phim.
 Bộ phim xoay quanh cuộc đối đầu của Vua Sừng với Taran, công chúa Eilonwy, Flewddur Fflam và một sinh vật có tên là Gurgi để giành được chiếc vạc dầu đen. Một bên muốn dùng chiếc vạc để thống trị thế giới và một bên muốn phá hủy nó.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Grant Bardsley","avatar":""},{"name":"Susan Sheridan","avatar":""},{"name":"John Byner","avatar":""},{"name":"Nigel Hawthorne","avatar":""},{"name":"John Hurt","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324548);
