INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-nien-vang-su', 'Đồng Niên Vãng Sự', 'A Time To Live And A Time To Die', 'https://phimimg.com/upload/vod/20231230-1/a87b004ce81d80727932622667ed8c07.jpg', 'https://phimimg.com/upload/vod/20231230-1/dcfabb5a9966557d956c8f4f7dd05e35.jpg', '<p>Bộ phim bán tự truyện về thời thơ ấu và thời niên thiếu của đạo diễn Hou Hsiao-Hsien, khi ông lớn lên ở Đài Loan.</p>', 'Full', 1, 'single', 'completed', 16, 1985, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Tien Feng","avatar":""},{"name":"Mei Fang","avatar":""},{"name":"Tang Ru-Yun","avatar":""},{"name":"Hsiao Ai","avatar":""},{"name":"Yu An-Shun","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
