INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-hen', 'Điểm Hẹn', 'Rendez-vous', 'https://phimimg.com/upload/vod/20231231-1/bba4f7d08877fa98ec20ed87b8246156.jpg', 'https://phimimg.com/upload/vod/20231231-1/7e27df633ab7d12566a56ff91d4cc055.jpg', '<p>Nina, cô gái trẻ đến từ các tỉnh lẻ khám phá thủ đô, tình cờ gặp gỡ mọi người, theo học nghề sân khấu và yêu. Trước hết, Paulot là hình dáng trấn an của một người đàn ông bình thường, rắn chắc như một tảng đá. Sau đó là Quentin, một diễn viên sa ngã bị dày vò bởi một bộ phim truyền hình trong quá khứ, bạo lực nhanh như chớp. Cuối cùng, Scrutzler, một đạo diễn thiếu linh hoạt và kiệt sức đã chọn Nina, ném cô ấy lên sân khấu. Một sự mặc khải được sinh ra qua ba cuộc gặp gỡ này. Nhưng, với chính mình, Nina có một cuộc hẹn.</p>', 'Full', 1, 'single', 'completed', 11, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Lambert Wilson","avatar":""},{"name":"Juliette Binoche","avatar":""},{"name":"Wadeck Stanczak","avatar":""},{"name":"Jean-Louis Trintignant","avatar":""},{"name":"Dominique Lavanant","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
