INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diem-hen', 'Điểm Hẹn', 'Rendez-vous', 'điểm hẹn rendez-vous lambert wilson juliette binoche wadeck stanczak jean-louis trintignant dominique lavanant ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('den-ma-xem', 'Đến Mà Xem', 'Come And See (Idi I Smotri)', 'https://phimimg.com/upload/vod/20231210-1/975314b797fd15463d0bd48032d3a251.jpg', 'https://phimimg.com/upload/vod/20231210-1/84af5b17c917e726a79540a3ecb47b91.jpg', '<p>Việc quân Đức xâm lược một ngôi làng ở Byelorussia đã đưa Florya trẻ tuổi vào rừng để gia nhập các chiến binh Kháng chiến mệt mỏi, đi ngược lại mong muốn của gia đình anh. Ở đó, anh gặp một cô gái, Glasha, người đã cùng anh trở về làng của mình. Khi trở về nhà, Florya thấy gia đình và những người nông dân của mình bị thảm sát. Sự sống sót tiếp tục của anh giữa những mảnh vụn tàn khốc của chiến tranh ngày càng trở nên ác mộng, một trận chiến giữa tuyệt vọng và hy vọng.</p>', 'Full', 1, 'single', 'completed', 10, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Aleksei Kravchenko","avatar":""},{"name":"Olga Mironova","avatar":""},{"name":"Liubomiras Laucevicius","avatar":""},{"name":"Vladas Bagdonas","avatar":""},{"name":"Viktors Lorencs","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324548);
