INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('its-a-drink-its-a-bomb', 'It''s A Drink! It''s A Bomb!', 'It''s A Drink! It''s A Bomb!', 'null', 'https://phimimg.com/upload/vod/20231209-1/313c6ccd2fa1125c681a7721663ae1d9.jpg', '<p>Một cảnh sát Hồng Kông quanh co thiết kế một quả bom ngụy trang trong một lon nước ngọt và bán nó cho hai kẻ buôn người Nhật Bản; tuy nhiên, cộng sự của cảnh sát đánh cắp quả bom, không muốn nó được sử dụng cho mục đích xấu xa. Anh ta giấu quả bom trước khi bị bọn buôn người giết. Sau đó, vụ việc đã quy tụ ba nhân chứng trộn lẫn vào cốt truyện: một nhà khoa học nhạc rock sành điệu, một tài xế taxi khôn ngoan và một người đi xe đạp quá hăng hái. Họ phải hợp tác để xác định vị trí quả bom bị mất tích trước khi các đại lý tìm thấy nó.</p>', 'Full', 1, 'single', 'completed', 11, 1985, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Maggie Cheung","avatar":""},{"name":"George Lam","avatar":""},{"name":"John Sham","avatar":""},{"name":"Dennis Chan","avatar":""},{"name":"Eddy Ko","avatar":""},{"name":"Liu Jiang","avatar":""},{"name":"Michael Lee","avatar":""},{"name":"Kai Chi Liu","avatar":""},{"name":"Lowell Lo","avatar":""},{"name":"Elvis Tsui","avatar":""},{"name":"Wu-Ma Feng","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Angelina","avatar":""},{"name":"Tin Sang Lung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324548);
