INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lien-hoan-phao', 'Liên Hoàn Pháo', 'Magnum Thunderbolt', 'null', 'https://phimimg.com/upload/vod/20231227-1/fb8d452517ab8babbac65601f4c3a1f8.jpg', '<p>Bộ phim Liên Hoàn Pháo - Magnum Thunderbolt kể về cuộc chiến giữa các băng đảng ma túy khét tiếng và phía cảnh sát. Sau khi em trai mình, Cao Dĩ Cường, cũng là thanh tra trưởng, bị bọn buôn ma túy hại chết một cách tức tưởi, Cao Dĩ Phi, một sát thủ chuyên nghiệp tìm cách báo thù cho em trai mình. Tuy nhiên, điều anh không thể ngờ tới là người đứng đằng sau cái chết của em trai lại là người bạn năm xưa của mình - Trần Thế Mẫn. Hắn đã phối hợp với một trùm buôn ma túy khác là Chu Dịch Phát để hại chết Cao Dĩ Cường nhằm thoát khỏi lưới pháp luật.</p>', 'Full', 1, 'single', 'completed', 16, 1985, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Ray Lui","avatar":""},{"name":"Michael Wai-Man Chan","avatar":""},{"name":"Phillip Ko","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324548);
