INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('police-academy-2-their-first-assignment', 'Police Academy 2: Their First Assignment', 'Police Academy 2: Their First Assignment', 'https://phimimg.com/upload/vod/20231208-1/05d6a12bdefb73c8efabf86d8f78a845.jpg', 'https://phimimg.com/upload/vod/20231208-1/f9bc82c3944bb8c5e62dc2ab391e1230.jpg', '<p>Kiếm được các huy hiệu mới sáng bóng của họ sau khi tốt nghiệp Học viện Cảnh sát uy tín (1984) của Chỉ huy Eric Lassard, Cán bộ Carey Mahoney, cùng với năm sinh viên tốt nghiệp hàng đầu khác, thấy mình được chuyển đến khu vực tồi tệ nhất trong thành phố, được điều hành bởi anh trai của Eric, Thuyền trưởng Pete Lassard. Khi thị trấn giữ một kỷ lục về tỷ lệ tội phạm, chủ yếu là do những người chèo thuyền, nhóm ông chủ tội phạm vô vị, Zed, những tân binh thiếu kinh nghiệm có rất nhiều trên đĩa của họ, trong khi đó, Mauser trung úy Hunge đang mơ về việc tạo tên cho mình. Bây giờ, chỉ có Mahoney và một nhiệm vụ bí mật phối hợp có thể cản trở kế hoạch của Mauser. Nhưng, các sĩ quan cảnh sát lập dị nhất thế giới có thể cứu ngày nào?</p>', 'Full', 1, 'single', 'completed', 11, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324548);
