INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doa-hong-tim-cairo', 'Đóa Hồng Tím Cairo', 'The Purple Rose Of Cairo', 'https://phimimg.com/upload/vod/20231219-1/93a9967667215e9e8f92004e0398e0fa.jpg', 'https://phimimg.com/upload/vod/20231219-1/d6e6b8987d9aa8d294e4c1a4236a9bbb.jpg', '<p>Cecilia là một cô hầu bàn ở New Jersey, sống một cuộc sống buồn tẻ trong thời kỳ Đại suy thoái. Lối thoát duy nhất của cô ấy khỏi thực tại trần tục của mình là rạp chiếu phim. Sau khi mất việc, Cecilia đến xem Bông hồng tím của Cairo với hy vọng vực dậy tinh thần, nơi cô ấy đã xem đi xem lại nhà khảo cổ học bảnh bao Tom Baxter.</p>', 'Full', 1, 'single', 'completed', 10, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mia Farrow","avatar":""},{"name":"Jeff Daniels","avatar":""},{"name":"Danny Aiello","avatar":""},{"name":"Irving Metzman","avatar":""},{"name":"Stephanie Farrow","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324548);
