INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('max-dien-3', 'Max Điên 3', 'Mad Max Beyond Thunderdome', 'https://phimimg.com/upload/vod/20231204-1/39897f0530cb963ac6de49bb96794961.jpg', 'https://phimimg.com/upload/vod/20231204-1/f3f86869de68c1c97f8d41392a6759d1.jpg', '<p>Bartertown là một thành phố cạnh một sa mạc đã được quản lý để giữ lại một số công nghệ khi nền văn minh bị sụp đổ. Tài nguyên bị các thành phần man rợ cướp bóc. Max tham gia vào một cuộc đấu tranh quyền lực, trong ba bộ phim Mad Max này,lần đầu tiên phải giữ gìn thị trấn, các sa mạc và sau đó giải cứu những đứa trẻ vô tội mà ông đã phát hiện ra.</p>', 'Full', 1, 'single', 'completed', 14, 1985, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Tina Turner","avatar":""},{"name":"Bruce Spence","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324548);
