INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-kich-cuu-con', 'Biệt Kích Cứu Con', 'Commando', 'https://phimimg.com/upload/vod/20231204-1/c419163d01d6acd999fa5ca2143c4735.jpg', 'https://phimimg.com/upload/vod/20231204-1/71e7b219ebcfcf655ae415b64f362e97.jpg', '<p>John Matrix, cựu thủ lĩnh của một lực lượng tấn công biệt kích luôn hoàn thành những công việc khó khăn nhất, buộc phải hành động trở lại khi cô con gái nhỏ của anh bị bắt cóc. Để tìm thấy cô ấy, Matrix phải chiến đấu vượt qua một loạt những kẻ chơi chữ, những kẻ giết người, một trong những biệt kích cũ của anh ta và một đội quân tư nhân được trang bị đầy đủ. Với sự giúp đỡ của một nữ tiếp viên nóng nảy và một người bạn cũ, Matrix chỉ có vài giờ để vượt qua thử thách lớn nhất: tìm ra con gái mình trước khi cô bé bị giết.</p>', 'Full', 1, 'single', 'completed', 10, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Arnold Schwarzenegger","avatar":""},{"name":"Rae Dawn Chong","avatar":""},{"name":"Dan Hedaya","avatar":""},{"name":"Vernon Wells","avatar":""},{"name":"James Olson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324548);
