INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-dam-huyen-thoai-4', 'Tay Đấm Huyền Thoại 4', 'Rocky IV', 'https://phimimg.com/upload/vod/20231130-1/7d381fbfcabbb52fddbcbfe180da35ee.jpg', 'https://phimimg.com/upload/vod/20231130-1/cdb2b7dbde8fa246ff628afc27596c46.jpg', '<p>Tay Đấm Huyền Thoại phần 4 là một bộ phim điện ảnh do Mỹ sản xuất vào năm 1985, đây là phần thứ 4 trong loạt series Rocky do Sylvester Stallone thủ vai chính.Phim được công chiếu vào ngày 27 tháng 11 năm 1985 và đạt được doanh thu 300 triệu USD.</p>', 'Full', 1, 'single', 'completed', 13, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Talia Shire","avatar":""},{"name":"Burt Young","avatar":""},{"name":"Carl Weathers","avatar":""},{"name":"Dolph Lundgren","avatar":""},{"name":"Brigitte Nielsen","avatar":""},{"name":"Tony Burton","avatar":""},{"name":"Rocky Krakoff","avatar":""},{"name":"Michael Pataki","avatar":""},{"name":"Stu Nahan","avatar":""},{"name":"Al Bandiero","avatar":""},{"name":"Dominic Barto","avatar":""},{"name":"Danial Brown","avatar":""},{"name":"James Brown","avatar":""},{"name":"Rose Mary Campos","avatar":""},{"name":"Jack Carpenter","avatar":""},{"name":"Mark De Alessandr","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
