INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-mai-phi-chau', 'Xa Mãi Phi châu', 'Out of Africa', 'https://phimimg.com/upload/vod/20231125-1/bba697b983cae896fd2647c79c66a207.jpg', 'https://phimimg.com/upload/vod/20231125-1/d7f89d4c575b7c14da74faf7d68f3a17.jpg', '<p>Ra khỏi châu Phi kể câu chuyện về cuộc đời của tác giả người Đan Mạch Karen Blixen, người vào đầu thế kỷ 20 đã chuyển đến châu Phi để xây dựng một cuộc sống mới cho chính mình. Bộ phim dựa trên tiểu thuyết tự truyện của Karen Blixen từ năm 1937.</p>', 'Full', 1, 'single', 'completed', 11, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Redford","avatar":""},{"name":"Meryl Streep","avatar":""},{"name":"Klaus Maria Brandauer","avatar":""},{"name":"Michael Kitchen","avatar":""},{"name":"Malick Bowens","avatar":""},{"name":"Michael Gough","avatar":""},{"name":"Suzanna Hamilton","avatar":""},{"name":"Rachel Kempson","avatar":""},{"name":"Graham Crowden","avatar":""},{"name":"Leslie Phillips","avatar":""},{"name":"Shane Rimmer","avatar":""},{"name":"Joseph Thiaka","avatar":""},{"name":"Stephen Kinyanjui","avatar":""},{"name":"Mike Bugara","avatar":""},{"name":"Job Seda","avatar":""},{"name":"Mohammed Umar","avatar":""},{"name":"Do","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
