INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-cua-rong', 'Trái tim của rồng', 'Heart Of Dragon', 'https://phimimg.com/upload/vod/20231123-1/d5736268fd8e3669445b5eb2cc8e49b3.jpg', 'https://phimimg.com/upload/vod/20231123-1/e240ef906f8f9708f6d88bd78eb26293.jpg', '<p>Tai khao khát trở thành một thủy thủ không biết lái từ khi còn nhỏ. Thật không may, anh trai của anh, Dodo, bị thiểu năng trí tuệ bẩm sinh. Để chăm sóc anh trai, Tai không bao giờ thực hiện được ước mơ của mình và không được chào đón tại đồn cảnh sát vì tính khí bất cần của mình. Một ngày nọ, sau khi nói chuyện lại với sếp, anh ta bỏ việc vì tức giận. Dodo nhầm nó với việc đứa em trai bỏ rơi mình, và bắt đầu tiến lên bằng chính nỗ lực của mình. Một ngày nọ, khi đang chơi đùa với lũ trẻ trong xóm, anh vô tình tìm thấy món đồ trang sức do một số tên cướp để lại. Một cậu bé trong nhóm trẻ em, vì tham tiền mà đẩy Dodo xuống đồi và lấy đi số nữ trang. Không ngờ, bọn cướp quay lại. Nghe tin, Tài lao đến, tri hô cướp tài sản.</p>', 'Full', 1, 'single', 'completed', 13, 1985, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Sammo Hung","avatar":""},{"name":"Emily Chu Bo-Yee","avatar":""},{"name":"Mang Hoi","avatar":""},{"name":"Melvin Wong Gam-Sam","avatar":""},{"name":"Lam Ching-Ying","avatar":""},{"name":"Chin Ka-Lok","avatar":""},{"name":"James Tien Chuen","avatar":""},{"name":"Paul Chung Fat","avatar":""},{"name":"Tai Bo","avatar":""},{"name":"Lam Ying-Fat","avatar":""},{"name":"Clarence Lee Ga-Ho","avatar":""},{"name":"Cheng Mang-Ha","avatar":""},{"name":"Yuen Wah","avatar":""},{"name":"Corey Yuen","avatar":""},{"name":"Peter Chan Lung","avatar":""},{"name":"Dick Wei","avatar":""},{"name":"Phillip Ko","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong",