INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-trung-phat', 'Thiên Thần Trừng Phạt', 'Pale Rider', 'https://phimimg.com/upload/vod/20231109-1/a4bcfe0acd5a85d20fdbcf21b7de1953.jpg', 'https://phimimg.com/upload/vod/20231109-1/7df5bc57bd116e7ae4cae3cf482f0d55.jpg', '<p>Lấy bối cảnh một khu mỏ khai thác vàng nằm ở chân núi của California đã bị đóng cửa bởi một chủ đất, với âm mưu cướp đoạt toàn bộ số tài nguyên thiên nhiên đó. Nổ ra xung đột và đấu tranh giữa những người công nhân thợ mỏ nghèo với tên chủ đất này. Thế rồi, một người anh hùng đã xuất hiện, anh đã thuyết phục người chủ đất từ bỏ ý định tấn công những người công nhân vô tội và khắc khổ này…</p>', 'Full', 1, 'single', 'completed', 23, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clint Eastwood","avatar":""},{"name":"Michael Moriarty","avatar":""},{"name":"Carrie Snodgress","avatar":""},{"name":"Chris Penn","avatar":""},{"name":"Richard Dysart","avatar":""},{"name":"Sydney Penny","avatar":""},{"name":"Richard Kiel","avatar":""},{"name":"Doug McGrath","avatar":""},{"name":"John Russell","avatar":""},{"name":"Charles Hallahan","avatar":""},{"name":"Marvin J. McIntyre","avatar":""},{"name":"Fran Ryan","avatar":""},{"name":"Richard Hamilton","avatar":""},{"name":"Graham Paul","avatar":""},{"name":"Chuck Lafont","avatar":""},{"name":"Jeffrey Weissman","avatar":""},{"name":"Allen K","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '[]', 1784690324548);
