INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-gia-trai', 'Cô Nàng Giả Trai', 'Just One of the Guys', 'https://phimimg.com/upload/vod/20231108-1/897ca02b0a080508cc21735616c97baa.jpg', 'https://phimimg.com/upload/vod/20231108-1/126541c155206f92c967fa0eb9aa5ef0.jpg', '<p>Terry Griffith có mọi thứ, ưa nhìn, nổi tiếng, một bạn trai hoàn hảo, một đề tài thực tập dễ nhai (cô nghĩ vậy) nên cô cảm thấy rất yêu đời. Khi thầy giáo môn báo luận đưa đề tài thực tập cô suýt ngã ngửa khi đó là đề tài nghiên cứu về nam sinh. Nhưng ba bảy cũng liều, cô giả trai để thâm nhập vào một trường nội trú nam sinh để quyết giành giải thực tập sinh của năm.</p>', 'Full', 1, 'single', 'completed', 15, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Joyce Hyser","avatar":""},{"name":"Clayton Rohner","avatar":""},{"name":"Billy Jayne","avatar":""},{"name":"Toni Hudson","avatar":""},{"name":"William Zabka","avatar":""},{"name":"Leigh McCloskey","avatar":""},{"name":"Sherilyn Fenn","avatar":""},{"name":"Deborah Goodrich","avatar":""},{"name":"Arye Gross","avatar":""},{"name":"Robert Fieldsteel","avatar":""},{"name":"Stuart Charno","avatar":""},{"name":"John Apicella","avatar":""},{"name":"Kenneth Tigar","avatar":""},{"name":"Steven Basil","avatar":""},{"name":"J. Williams","avatar":""},{"name":"Don Blanton","avatar":""},{"name":"Ramon Chavez","avatar":""},{"name":"Frank","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324548);
