INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('-xac-song-tro-lai-', 'Xác Sống Trở Lại', 'The Return of the Living Dead', 'https://phimimg.com/upload/vod/20231101-1/00a226b36f69dffbeecac76c1616209b.jpg', 'https://phimimg.com/upload/vod/20231101-1/fc5f32b51a69771b15c7ecf05aca4408.jpg', '<p>Khi quản đốc Frank cho nhân viên mới Freddy xem một thí nghiệm quân sự bí mật trong một kho tiếp tế ở Louisville, Kentucky, hai klutze đã vô tình giải phóng một loại khí có thể biến xác chết thành những thây ma ăn thịt. Khi dịch bệnh lan rộng khắp thị trấn, và các sinh vật thỏa mãn cơn đói theo những cách đẫm máu và kỳ dị, Frank và Freddy chiến đấu để sinh tồn với sự giúp đỡ của ông chủ và một người hành quyết bí ẩn.</p>', 'Full', 1, 'single', 'completed', 13, 1985, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Clu Gulager","avatar":""},{"name":"James Karen","avatar":""},{"name":"Don Calfa","avatar":""},{"name":"Thom Mathews","avatar":""},{"name":"Miguel A. Núñez Jr.","avatar":""},{"name":"Beverly Randolph","avatar":""},{"name":"Brian Peck","avatar":""},{"name":"Jonathan Terry","avatar":""},{"name":"John Philbin","avatar":""},{"name":"Linnea Quigley","avatar":""},{"name":"Jewel Shepard","avatar":""},{"name":"Mark Venturini","avatar":""},{"name":"Cathleen Cordell","avatar":""},{"name":"Drew Deighan","avatar":""},{"name":"James Dalesandro","avatar":""},{"name":"John Durbin","avatar":""},{"name":"David Bond","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324548);
