INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-canh-tuong-chet-choc', 'Điệp Viên 007: Cảnh Tượng Chết Chóc', 'A View to a Kill', 'https://phimimg.com/upload/vod/20231026-1/3248b55d7510b989a3253de30b84b900.jpg', 'https://phimimg.com/upload/vod/20231026-1/6b3c7814b499821bec02bedf60e85421.jpg', '<p>Khi Bond được gửi đi để khám phá về vụ khu công nghệ cao Zorin, anh đã khám phá ra được ổ nhóm của tội ác và lừa đảo. Người sở hữu công ty bí hiểm này, Max Zorin (Christopher Walken) đã đặt ra kế hoạch để điều khiển thế giới thông qua những vi mạch. Và hắn sẵn sàng bỏ ra hàng tỷ đồng để thực hiện cho mưu đồ này. Nhưng trước khi Bond dừng được hoạt động của Zorin, anh phải đối mặt với bạn gái của kẻ điên cuồng này, May Day xinh đẹp. Cùng với sự trợ giúp của cô nàng Stacey quyến rũ, Bond đã tấn công được vào Zorin, bẻ gẫy âm mưu thâm độc của Max…</p>', 'Full', 1, 'single', 'completed', 15, 1985, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Roger Moore","avatar":""},{"name":"Tanya Roberts","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"Grace Jones","avatar":""},{"name":"Patrick Macnee","avatar":""},{"name":"Patrick Bauchau","avatar":""},{"name":"David Yip","avatar":""},{"name":"Fiona Fullerton","avatar":""},{"name":"Manning Redwood","avatar":""},{"name":"Alison Doody","avatar":""},{"name":"Willoughby Gray","avatar":""},{"name":"Desmond Llewelyn","avatar":""},{"name":"Robert Brown","avatar":""},{"name":"Lois Maxwell","avatar":""},{"name":"Walter Gotell","avatar":""},{"name":"Geoffrey Keen","avatar":""},{"name":"Jean Roug","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324548);
