INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-6-ngay-13-khoi-dau-moi', 'Thứ 6 Ngày 13: Khởi Đầu Mới', 'Friday the 13th: A New Beginning', 'https://phimimg.com/upload/vod/20231024-1/57df4456e3fdbbf599799410b40e6f6b.jpg', 'https://phimimg.com/upload/vod/20231024-1/05c792aa480a75e762843c3abac7e82f.jpg', '<p>Kẻ điên cuồng giết người Jason trở về từ ngôi mộ để gây ra tình trạng hỗn loạn đẫm máu hơn. Tommy trẻ tuổi có thể đã trốn thoát khỏi Crystal Lake, nhưng anh vẫn bị ám ảnh bởi những sự kiện khủng khiếp xảy ra ở đó. Khi những vụ giết người đẫm máu bắt đầu xảy ra tại ngôi nhà hẻo lánh dành cho những thanh thiếu niên gặp rắc rối nơi anh hiện đang sống, có vẻ như kẻ thù ác mộng của anh, Jason, đã quay trở lại để thực hiện những vụ tàn sát tàn bạo hơn.</p>', 'Full', 1, 'single', 'completed', 14, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tiffany Helm","avatar":""},{"name":"John Shepherd","avatar":""},{"name":"Juliette Cummins","avatar":""},{"name":"Melanie Kinnaman","avatar":""},{"name":"Richard Young","avatar":""},{"name":"Deborah Voorhees","avatar":""},{"name":"Mark Venturini","avatar":""},{"name":"Shavar Ross","avatar":""},{"name":"Marco St. John","avatar":""},{"name":"Corey Feldman","avatar":""},{"name":"Richard Lineback","avatar":""},{"name":"Rebecca Wood","avatar":""},{"name":"Ron Sloan","avatar":""},{"name":"Anthony Barrile","avatar":""},{"name":"Todd Bryant","avatar":""},{"name":"Caskey Swaim","avatar":""},{"name":"Corey Park","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324548);
