INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-rambo-2', 'Chiến Binh Rambo 2', 'Rambo: First Blood Part II', 'https://phimimg.com/upload/vod/20231022-1/6c144ac8967dd9f2b8f8b68e6d70d0a6.jpg', 'https://phimimg.com/upload/vod/20231022-1/34b9a4218fd60df22371a61b94d9bf2e.jpg', '<p>Tiếp nối phần phim trước, John Rambo bị chính quyền Mỹ bắt và cho làm việc trong một nhà tù kiêm trại lao động với công việc chính là khai thác đá. Một ngày kia, Rambo được người chỉ huy cũ của mình là Đại tá Samuel Trautman đến thăm. Trautman nói rằng chính quyền Mỹ sẽ trả tự do cho Rambo, với điều kiện anh phải lập công chuộc tội bằng cách xâm nhập vào Việt Nam để tìm kiếm tù binh Mỹ từ thời chiến tranh...</p>', 'Full', 1, 'single', 'completed', 20, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Richard Crenna","avatar":""},{"name":"Charles Napier","avatar":""},{"name":"Steven Berkoff","avatar":""},{"name":"Julia Nickson","avatar":""},{"name":"Martin Kove","avatar":""},{"name":"George Cheung","avatar":""},{"name":"Andy Wood","avatar":""},{"name":"William Ghent","avatar":""},{"name":"Vojislav Govedarica","avatar":""},{"name":"Dana Lee","avatar":""},{"name":"Baoan Coleman","avatar":""},{"name":"Steve Williams","avatar":""},{"name":"Don Collins","avatar":""},{"name":"Christopher Grant","avatar":""},{"name":"John Sterlini","avatar":""},{"name":"Alain Hoc","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324548);
