INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-do-kho-bau', 'Bản Đồ Kho Báu', 'The Goonies', 'https://phimimg.com/upload/vod/20231023-1/23f80b8bcd96b64a4327d9e9edf061fa.jpg', 'https://phimimg.com/upload/vod/20231023-1/16b0bb16ed47df54b01540fc8ad29dfc.jpg', '<p>Bản Đồ Kho Báu (1985) là bộ phim phiêu lưu - hài của đạo diễn Richard Donner. Kịch bản được viết bởi Chris Columbus dựa trên một câu truyện của nhà sản xuất Steven Spielberg. Một nhóm bạn trẻ gồm Mikey Walsh, người anh trai Brand của Mikey và các thành viên Andy, Data, Stef, Mouth và Chunk, đang bị buộc phải rời bỏ ngôi nhà của mình bởi có một kế hoạch dỡ bỏ những ngôi nhà này. Trong khi tập hợp lại để tìm cách cứu những ngôi nhà thân yêu, nhóm bạn đã tìm thấy một bản đồ kho báu. Họ bắt đầu hành trình tìm kiếm kho báu của tên cướp biển huyền thoại thế kỷ 17: Willy một-mắt...</p>', 'Full', 1, 'single', 'completed', 14, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sean Astin","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Jeff Cohen","avatar":""},{"name":"Corey Feldman","avatar":""},{"name":"Kerri Green","avatar":""},{"name":"Martha Plimpton","avatar":""},{"name":"Ke Huy Quan","avatar":""},{"name":"John Matuszak","avatar":""},{"name":"Robert Davi","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Anne Ramsey","avatar":""},{"name":"Lupe Ontiveros","avatar":""},{"name":"Mary Ellen Trainor","avatar":""},{"name":"Keith Walker","avatar":""},{"name":"Steve Antin","avatar":""},{"name":"Paul Tuerpe","avatar":""},{"name":"George Robotham","avatar":""},{"name":"Charles Mc","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324548);
