INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lanh-chua-hidetora', 'Lãnh Chúa Hidetora', 'Ran', 'https://phimimg.com/upload/vod/20231016-1/700416bd1a4a314f889a7eefe4ee0004.jpg', 'https://phimimg.com/upload/vod/20231016-1/ccd26d6e2db3c2c2a246237009f6aa3f.jpg', '<p>Cùng với những Rashomon, Seven Samurai... thì Ran là 1 trong những tác phẩm nổi tiếng và hay nhất của đạo diễn huyền thoại Akira Kurosawa. Bộ phim này được ông ấp ủ từ lâu nhưng chỉ đến khi những người hâm mộ ông như đạo diễn S.Stenberg và G.Lucas giúp đỡ ông mới có kinh phí thực hiện. Bộ phim nói đến mối quan hệ quân thần, vua tôi, mối quan hệ cha con trong thời phong kiến. Cảnh phim dàn dựng cực kỳ hoành tráng. Tâm trạng nhân vật được đẩy lên đến đỉnh điểm trong những đoạn cao trào. Kurosawa đúng là bậc thầy về dàn dựng phim chiến trận... Akira Kurosawa đã kể lại vở bi kịch King Lear của Shakespeare thông qua nhân vật samurai. Chỉ huy Tatsuya Nakadia đã mang vương quốc đặt vào tay người con trai trưởng của ông. Cuộc đấu tranh giành ...</p>', 'Full', 1, 'single', 'completed', 26, 1985, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Tatsuya Nakadai","avatar":""},{"name":"Akira Terao","avatar":""},{"name":"Jinpachi Nezu","avatar":""},{"name":"Daisuke Ryū","avatar":""},{"name":"Mieko Harada","avatar":""},{"name":"Yoshiko Miyazaki","avatar":""},{"name":"Mansai Nomura","avatar":""},{"name":"Hisashi Igawa","avatar":""},{"name":"Shinnosuke Ikehata","avatar":""},{"name":"Masayuki Yui","avatar":""},{"name":"Kazuo Kato","avatar":""},{"name":"Norio Matsui","avatar":""},{"name":"Toshiya Ito","avatar":""},{"name":"Heihachiro Suzuki","avatar":""},{"name":"Kenji Kodama","avatar":""},{"name":"Haruko Tōgō","avatar":""},{"name":"Reiko Nanjo","avatar":""},{"name":"Tok","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324548);
