INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nhanh-thi-song', 'Bắn Nhanh Thì Sống', 'Silverado', 'https://phimimg.com/upload/vod/20231016-1/09c417480adf2fcf068ad9d7b5f97e42.jpg', 'https://phimimg.com/upload/vod/20231016-1/01ef7fad8d8c5b25d95be3a9dff383ed.jpg', '<p>Đến một thị trấn nhỏ để tìm vận may, nhóm cao bồi Viễn Tây tinh quái và tạp nham đụng độ với bọn lãnh đạo biến chất và những kẻ thù trong quá khứ.</p>', 'Full', 1, 'single', 'completed', 23, 1985, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kevin Kline","avatar":""},{"name":"Scott Glenn","avatar":""},{"name":"Danny Glover","avatar":""},{"name":"Kevin Costner","avatar":""},{"name":"Brian Dennehy","avatar":""},{"name":"Rosanna Arquette","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Linda Hunt","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Brad Leland","avatar":""},{"name":"Marvin J. McIntyre","avatar":""},{"name":"Sheb Wooley","avatar":""},{"name":"Jonathan Kasdan","avatar":""},{"name":"Todd Allen","avatar":""},{"name":"Kenny Call","avatar":""},{"name":"Bill Thurman","avatar":""},{"name":"Meg Kasdan","avatar":""},{"name":"Dick Durock","avatar":""},{"name":"G","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324548);
