INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-bat-coc', 'Cảnh Sát Bắt Cóc', 'Cop Busters', 'https://phimimg.com/upload/vod/20231013-1/e6304e4ae35c256ccb1ceabb0dfbddab.jpg', 'https://phimimg.com/upload/vod/20231013-1/ab72567a46d24e0c00810ead68a04666.jpg', '<p>Big Bear và Big Mouth được nuôi dưỡng trong cùng một trại trẻ mồ côi. Họ đã làm việc ở bộ phận giao thông của sở cảnh sát trong nhiều năm. Họ được sư đoàn trưởng giao nhiệm vụ kéo xe; nhưng vào ngày đầu tiên nhận nhiệm vụ, họ đã đón nhầm một bé gái tên Bun. Họ rất vui mừng khi biết Bun có một người dì hấp dẫn tên là Mary. Theo kiểu điển hình, Big Mouth nhầm việc thể hiện tình cảm của Mary là thể hiện tình yêu và rất đau khổ khi cô từ chối anh ta.</p>', 'Full', 1, 'single', 'completed', 18, 1985, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Elaine Jin","avatar":""},{"name":"Chun Yang","avatar":""},{"name":"Wong Ching","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324548);
