INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ngoi-sao-may-man', 'Những Ngôi Sao May Mắn', 'Twinkle Twinkle Lucky Stars', 'https://phimimg.com/upload/vod/20231010-1/2c17c281bd729f63ca0ad721441fa594.jpg', 'https://phimimg.com/upload/vod/20231010-1/c1fed3fc4a7922ac0ce3f2e787b05bae.jpg', '<p>Nội dung của bộ phim Những Ngôi Sao May Mắn bắt đầu từ việc một tin cho cảnh sát đã gửi một lá thư có chứa thông tin nhạy cảm trên một hoạt động bất hợp pháp ma túy cho bạn bè của mình, Yi-Ching. Trong khi đi nghỉ ở Thái Lan, người đưa tin bị ám sát bởi tay sai của các trùm ma túy và, để che đậy hoạt động của họ, họ cố gắng để loại bỏ Yi-Ching và hai đại lý Lau.&nbsp; Quay trở lại Hồng Kông, các thám tử cảnh sát cơ bắp và Ricky Fung được giao nhiệm vụ bảo vệ Linh và Thanh tra Barbara Woo được giao để bảo vệ Yi-Ching. Cô được đưa đến nơi ẩn náu của “5 ngôi sao may mắn” , và cũng tranh thủ sự giúp đỡ của họ trong việc làm giảm các hoạt động ma túy của những tổ chức tội phạm. Năm người năm tính cách, tất cả đều cố gắng đeo đuổi nữ cảnh sát xinh đẹp, liệu ai sẽ thành công , nhiều tình tiết hài hước cười ra nước mắt cũng bắt đầu từ đây .</p>', 'Full', 1, 'single', 'completed', 15, 1985, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Stanley Fung","avatar":""},{"name":"Michael Miu","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Charlie Chin Chiang-Lin","avatar":""},{"name":"Jackie Chan","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"Sibelle Hu","avatar":""},{"name":"Walter Tso Tat-Wah","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324548);
