INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bao-ve-1985', 'Người Bảo Vệ', 'The Protector', 'https://phimimg.com/upload/vod/20231010-1/898920156e54af2e377fd05f39be98ae.jpg', 'https://phimimg.com/upload/vod/20231010-1/c7ac909f9b246c1d1063345b15896be6.jpg', '<p>Billy Wong là một nhân viên cảnh sát ở New York, đồng nghiệp của anh bị bắn hạ trong một vụ cướp. Billy và đồng nghiệp mới là Danny Garoni tiếp tục làm nhân viên an ninh ở một buổi diễn thời trang khi con gái một nhà tài phiệt bị bắt cóc. Cơ quan liên bang nhận định rằng cha của Laura có dính dáng tới Ko - một ông trùm thuốc phiện ở Hong Kong, thế là ủy viên cảnh sát NY gửi 2 nhân viên cảnh sát tới Hong Kong để điều tra...</p>', 'Full', 1, 'single', 'completed', 20, 1985, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Danny Aiello","avatar":""},{"name":"Sandy Alexander","avatar":""},{"name":"Victor Arnold","avatar":""},{"name":"Irene Britto","avatar":""},{"name":"Jesse Cameron-Glickenhaus","avatar":""},{"name":"Al Cerullo","avatar":""},{"name":"Roy Chiao","avatar":""},{"name":"Richard Clarke","avatar":""},{"name":"Patrick James Clarke","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324548);
