INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-may-man', 'Ngôi Sao May Mắn', 'My Lucky Stars', 'https://phimimg.com/upload/vod/20231010-1/d9b0d7804eb4aff369667f0d1831762f.jpg', 'https://phimimg.com/upload/vod/20231010-1/1ebd80e95fb6337d2569621ec9a7a0ce.jpg', '<p>Bộ phim &quot;Ngôi Sao May Mắn - My Lucky Stars&quot; là một bộ phim điện ảnh do Hồng Kông sản xuất năm 1985. Bộ phim có sự góp mật của ngôi sao võ thuật Hồng Kông là Thành Long và Hồng Kim Bảo. Lúc này có một nhóm sát thủ đến từ quốc gia Thái Lan, họ đến để ám sát một trùm mafia Hồng Kông.Thành Long sẽ vào vai cảnh sát,anh cùng một đội đặc biệt cùng nhau chống lại tội phạm...</p>', 'Full', 1, 'single', 'completed', 20, 1985, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Jackie Chan","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Charlie Chin Chiang-Lin","avatar":""},{"name":"Stanley Fung","avatar":""},{"name":"Sibelle Hu","avatar":""},{"name":"Walter Tso Tat-Wah","avatar":""},{"name":"James Tien Chuen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324548);
