INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-tu-da-tinh', 'Hoa Tử Đa Tình', 'Affectionately Yours', 'https://phimimg.com/upload/vod/20231006-1/924da461055baeeb8f1175a4ac1e0c7c.jpg', 'https://phimimg.com/upload/vod/20231006-1/ce8c28aa396272d6d9f4e73f23236ecf.jpg', '<p>Alan sở hữu một cửa hàng hoa, nhưng trước nỗi buồn của anh, bạn gái anh đã quyết định rời bỏ anh. Connie luôn có cảm tình với Alan nhưng không tìm được cơ hội bày tỏ tình cảm. Vì vậy, dưới sự thuyết phục của anh trai cô, Ruddy, cũng là bạn của Alan, cô đã khiến Alan say, và cả hai trở thành một món đồ trong mớ hỗn độn. Trong chuyến đi đến Nhật Bản, Alan tình cờ gặp Atsuko và cả hai yêu nhau từ cái nhìn đầu tiên. Đối với Atsuko, Alan và cha của Atsuko tổ chức một trận đấu Kendo Nhật Bản. Alan thua cuộc đấu tay đôi và chán nản rời đi, nhưng Atsuko lại vô cùng xúc động.</p>', 'Full', 1, 'single', 'completed', 23, 1985, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Alan Tam","avatar":""},{"name":"Atsuko Yamazaki","avatar":""},{"name":"Maria Chung Wai-Bing","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Billy Lau","avatar":""},{"name":"Yiu Yau-Hung","avatar":""},{"name":"Sze Kai-Keung","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324548);
