INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-gio-cho-den-thang-muoi', 'Bao giờ cho đến tháng Mười', 'When the Tenth Month Comes', 'https://phimimg.com/upload/vod/20250401-1/1fffc8c3551b6f522082f445976565bf.jpg', 'https://phimimg.com/upload/vod/20250401-1/9fd9493189e5144c085edba26175a130.jpg', '<p>Bao giờ cho đến tháng Mười được sản xuất năm 1984 đã được coi là một trong những bộ phim kinh điển của nền điện ảnh Việt Nam. Ngày 15 tháng 9 năm 2008, CNN đánh giá “Bao giờ cho đến tháng Mười” là một trong 18 bộ phim châu Á xuất sắc mọi thời đại. Bao giờ cho đến tháng mười là một bộ phim mang nhiều bản sắc dân tộc khi lấy nhân vật chính là người phụ nữ, đạo diễn Đặng Nhật Minh đã góp phần làm tăng vẻ đẹp thầm kín cao cả trong tâm hồn người phụ nữ Việt Nam.</p>', 'Full', 1, 'single', 'completed', 22, 1984, 'Vietsub', 'HD', 'Việt Nam', 0, '[{"name":"Lê Vân","avatar":""},{"name":"Hữu Mười","avatar":""},{"name":"Đặng Lưu Việt Bảo","avatar":""},{"name":"Lại Phú Cương","avatar":""},{"name":"Nguyen Minh Vuong","avatar":""},{"name":"Trịnh Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["The Love Doesn''t Come Back","Quand viendra le mois d''octobre","10月になれば","Bao giờ cho đến tháng Mười"]', 1784690324548);
