INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-pho-elm', 'Ác Mộng Phố Elm', 'A Nightmare on Elm Street', 'https://phimimg.com/upload/vod/20260206-1/c16422ccbd62b01ad922902d1af2bf29.jpg', 'https://phimimg.com/upload/vod/20260206-1/a575d32a6be70a6f12cb02816d32c660.jpg', '<p>Vào đầu những năm 80, một kẻ tâm thần có tên Freddy Krueger được biết đến dưới cái biệt danh &quot;Springwood Slasher&quot;, đã giết rất nhiều trẻ em với đôi găng tay có những lưỡi dao cạo gắn vào ngón tay. Khi quan tòa đưa ra một quyết định ngớ ngẩn và Freddy đã được tha bổng, thì hắn đã bị những cặp vợ chồng có con cái bị hắn sát hại thiêu sống trong phòng. Vài năm sau, Nancy Thompson, con gái của viên cảnh sát đã bắt giữ Krueger đã trải qua những cơn ác mộng kinh hoàng có liên quan đến một kẻ bị thiêu sống với cái găng tay gắn lưỡi dao. Hồn ma của Freddy Krueger đã quay trở lại và ám ảnh giấc mơ của mọi người. Khi người bạn thân nhất của Nancy là Tina trở thành nạn nhân của Krueger, Nancy nhận ra rằng cô không thể làm ngơ và phải tìm cách để ngăn tên tâm thần điên cuồng này hoặc cô sẽ không bao giờ được ngủ...</p>', 'Full', 1, 'single', 'completed', 20, 1984, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Heather Langenkamp","avatar":""},{"name":"Robert Englund","avatar":""},{"name":"John Saxon","avatar":""},{"name":"Ronee Blakley","avatar":""},{"name":"Johnny Depp","avatar":""},{"name":"Jsu Garcia","avatar":""},{"name":"Amanda Wyss","avatar":""},{"name":"Charles Fleischer","avatar":""},{"name":"Joseph Whipp","avatar":""},{"name":"Ed Call","avatar":""},{"name":"Sandy Lipton","avatar":""},{"name":"Lin Shaye","avatar":""},{"name":"Joe Unger","avatar":""},{"name":"Mimi Craven","avatar":""},{"name":"Jack Shea","avatar":""},{"name":"David Andrews","avatar":""},{"name":"Jeff Levine","avatar":""},{"name":"Donna Woodrum","avatar":""},{"name":"Shashawne","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Freddy - Chapitre 1 - Les Griffes de la nuit","Pesadilla en la Calle Elm","Freddy 1 - Les Griffes de la nuit","Freddy 1","Nightmare on Elm Street 1 - Mörderische Träume","Pesadilla en lo profundo de la noche","Koszmar z Ulicy Wiązów","Pesadilla en Elm Street","Nightmare on Elm Street - Mörderische Träume","Nightmare - Mörderische Träume","Εφιάλτης στο δρόμο με τις λεύκες","Les Griffes de la nuit","Terror på Elm Street","Nightmare - Dal profondo della notte","Pesadelo em Elm Street","Pesadilla en la calle del infierno","Erumu gai no akumu","Painajainen Elm Streetillä","Pesadilla en Elmo Street","A Hora do Pesadelo","Morderisk mareridt","Rémálom az Elm utcában","Noční můra v Elm Street","半夜鬼上床","Qarağac küçəsində qarabasma","Ác Mộng Phố Elm","Қарағаш көшесіндегі қорқыныш","Košmaras Guobu gatveje","Cosmar pe Strada Ulmilor","Страва у Улици брестова","Nočná mora z Elm Street","Mora v ulici brestov","Elm ko''chasidagi kabus","Strava u Ulici brijestova","Кошмари на Елм Стрийт","Жах на вулиці В''язів","A Nightmare on Elm Street"]', 1784690324548);
