INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ac-mong-pho-elm', 'Ác Mộng Phố Elm', 'A Nightmare on Elm Street', 'ác mộng phố elm a nightmare on elm street heather langenkamp robert englund john saxon ronee blakley johnny depp jsu garcia amanda wyss charles fleischer joseph whipp ed call sandy lipton lin shaye joe unger mimi craven jack shea david andrews jeff levine donna woodrum shashawne freddy - chapitre 1 - les griffes de la nuit pesadilla en la calle elm freddy 1 - les griffes de la nuit freddy 1 nightmare on elm street 1 - mörderische träume pesadilla en lo profundo de la noche koszmar z ulicy wiązów pesadilla en elm street nightmare on elm street - mörderische träume nightmare - mörderische träume εφιάλτης στο δρόμο με τις λεύκες les griffes de la nuit terror på elm street nightmare - dal profondo della notte pesadelo em elm street pesadilla en la calle del infierno erumu gai no akumu painajainen elm streetillä pesadilla en elmo street a hora do pesadelo morderisk mareridt rémálom az elm utcában noční můra v elm street 半夜鬼上床 qarağac küçəsində qarabasma ác mộng phố elm қарағаш көшесіндегі қорқыныш košmaras guobu gatveje cosmar pe strada ulmilor страва у улици брестова nočná mora z elm street mora v ulici brestov elm ko''chasidagi kabus strava u ulici brijestova кошмари на елм стрийт жах на вулиці в''язів a nightmare on elm street', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-tuyet-mat', 'Nhiệm Vụ Tuyệt Mật', 'Top Secret!', 'https://phimimg.com/upload/vod/20260205-1/cc8ce02897e6e2ef9cc3198e6f170839.jpg', 'https://phimimg.com/upload/vod/20260205-1/02d2af7524bfa761d3bd9dc7e78358f4.jpg', '<p>Nhiệm vụ tuyệt mật là một bộ phim hài chế và hành động Mỹ ra rạp năm 1984 rất được yêu thích, lấy đề tài gián điệp thời Chiến tranh Lạnh và chế lời nhạc của Elvis Presley.</p>', 'Full', 1, 'single', 'completed', 21, 1984, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Val Kilmer","avatar":""},{"name":"Lucy Gutteridge","avatar":""},{"name":"Peter Cushing","avatar":""},{"name":"Jeremy Kemp","avatar":""},{"name":"Christopher Villiers","avatar":""},{"name":"Warren Clarke","avatar":""},{"name":"Harry Ditson","avatar":""},{"name":"Jim Carter","avatar":""},{"name":"Eddie Tagoe","avatar":""},{"name":"Omar Sharif","avatar":""},{"name":"Tristram Jellinek","avatar":""},{"name":"Billy J. Mitchell","avatar":""},{"name":"Ian McNeice","avatar":""},{"name":"Michael Gough","avatar":""},{"name":"Gertan Klauber","avatar":""},{"name":"John Sharp","avatar":""},{"name":"Dimitri Andreas","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Top Secret! Super Confidencial","Szigorúan titkos","Ultra Secreto","Top Secret","Top Secret!"]', 1784690324548);
