INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhiem-vu-tuyet-mat', 'Nhiệm Vụ Tuyệt Mật', 'Top Secret!', 'nhiệm vụ tuyệt mật top secret! val kilmer lucy gutteridge peter cushing jeremy kemp christopher villiers warren clarke harry ditson jim carter eddie tagoe omar sharif tristram jellinek billy j. mitchell ian mcneice michael gough gertan klauber john sharp dimitri andreas top secret! super confidencial szigorúan titkos ultra secreto top secret top secret!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-xe-den-phan-3', 'Hiệp Sĩ Xe Đen (Phần 3)', 'Knight Rider (Season 3)', 'https://phimimg.com/upload/vod/20251208-1/4c70a1e030d8de4f3db1d4beb71ab3fb.jpg', 'https://phimimg.com/upload/vod/20251208-1/4fdb977b9d7c894c39362d38b8b0214f.jpg', '<p><span style="text-wrap-mode: wrap;">Michael Long, một sĩ quan cảnh sát chìm, bị bắn trọng thương trong lúc điều tra và bị những kẻ tấn công bỏ mặc cho đến chết.Anh được cứu bởi Wilton Knight, một triệu phú sắp qua đời và là nhà phát minh giàu có. Wilton đã sắp xếp một cuộc phẫu thuật cứu mạng cho Michael, bao gồm một khuôn mặt mới và một danh tính mới—là Michael Knight.Michael sau đó được giao một chiếc xe đặc biệt, không thể phá hủy và được trang bị máy tính hóa, gọi là Knight Industries Two Thousand (thường được gọi là KITT), cùng với một nhiệm vụ: bắt giữ những tên tội phạm nằm ngoài tầm với của pháp luật.Bộ phim mô tả các cuộc phiêu lưu của Michael khi anh và KITT chiến đấu với các thế lực tà ác dưới danh nghĩa Quỹ Luật pháp và Chính phủ.</span></p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 18, 1984, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Hasselhoff","avatar":""},{"name":"Edward Mulhare","avatar":""},{"name":"William Daniels","avatar":""},{"name":"Patricia McPherson","avatar":""},{"name":"Peter Parros","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hình Sự","slug":"hinh-su"