INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-sherlock-hound-meitantei-holmes', 'Thám Tử Sherlock Hound (Meitantei Holmes)', 'Sherlock Hound', 'https://phimimg.com/upload/vod/20251026-1/bf64f2815f53328c619663b4ed29eb78.jpg', 'https://phimimg.com/upload/vod/20251026-1/9c41d01b2e46512441b5926bc9555d14.jpg', '<p>Tại một Luân Đôn phong cách steampunk, thám tử đại tài Sherlock Holmes cùng bác sĩ Watson thường xuyên phá giải những vụ án hóc búa nhất — mà thủ phạm, phần lớn thời gian, lại chính là kẻ thù truyền kiếp của họ: giáo sư Moriarty, một thiên tài kiêu ngạo nhưng vụng về.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 19, 1984, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Taichiro Hirokawa","avatar":""},{"name":"Chikao Ohtsuka","avatar":""},{"name":"Yoko Asagami","avatar":""},{"name":"Kosei Tomita","avatar":""},{"name":"Shozo Iizuka","avatar":""},{"name":"Hiroshi Masuoka","avatar":""},{"name":"Mitsuo Senda","avatar":""},{"name":"Hitomi Oikawa","avatar":""},{"name":"Ichiro Nagai","avatar":""},{"name":"Kumiko Takizawa","avatar":""},{"name":"Mayumi Tanaka","avatar":""},{"name":"Miki Takahashi","avatar":""},{"name":"Run Sasaki","avatar":""},{"name":"Ryo Horikawa","avatar":""},{"name":"Show Hayami","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["شرلوك هولمز","妙犬神探","Sherlock Holmes","Sherlock Holmes La serie animada","Sherlock Koira","Sherlock Holmes Le Célèbre Détective","Les aventures de Sherlock Holmes","Sherlock Holmes, a mesterkopó","Il fiut