INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tau-bounty', 'Tàu Bounty', 'The Bounty', 'https://phimimg.com/upload/vod/20251008-1/013be0daa1b6de8cff807c5d0933874b.jpg', 'https://phimimg.com/upload/vod/20251008-1/3aff1403640bf089d7d35d252fc6bfb1.jpg', '<p>Bộ phim The Bounty (1984) là một tác phẩm điện ảnh lịch sử đầy kịch tính, tái hiện lại vụ nổi loạn nổi tiếng trên tàu HMS Bounty của Hải quân Hoàng gia Anh. &nbsp;Tàu HMS Bounty khởi hành từ Portsmouth, Anh vào năm 1787, với nhiệm vụ thu thập cây bánh mì từ Tahiti để mang về vùng Caribbean. Thuyền trưởng Bligh, một người đầy tham vọng, muốn dùng chuyến đi này để hoàn tất hành trình vòng quanh thế giới. Tuy nhiên, thời tiết khắc nghiệt buộc họ phải thay đổi lộ trình. Bligh bổ nhiệm Fletcher Christian làm sĩ quan phó, nhưng mối quan hệ giữa họ dần trở nên căng thẳng. Sau khi đến Tahiti, Christian bị cuốn hút bởi cuộc sống tự do và tình yêu với một cô gái bản địa. Khi con tàu chuẩn bị rời đi, Christian dẫn đầu một cuộc nổi loạn chống lại Bligh, chọn ở lại thiên đường nhiệt đới thay vì tiếp tục hành trình đầy gian nan.</p>', 'Full', 1, 'single', 'completed', 20, 1984, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Anthony Hopkins","avatar":""},{"name":"Daniel Day-Lewis","avatar":""},{"name":"Bernard Hill","avatar":""},{"name":"Phil Davis","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Wi Kuki Kaa","avatar":""},{"name":"Tevaite Vernette","avatar":""},{"name":"Laurence Olivier","avatar":""},{"name":"Edward Fox","avatar":""},{"name":"Philip Martin Brown","avatar":""},{"name":"Simon Chandler","avatar":""},{"name":"Malcolm Terris","avatar":""},{"name":"Simon Adams","avatar":""},{"name":"John Sessions","avatar":""},{"name":"Andrew Wilde","avatar":""},{"name":"Neil Morrisse","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Mutiny on the Bounty","Bunt na Bounty","Баунті","바운티호의 반란","바운티호","The Bounty"]', 1784690324549);
