INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-hai-chi-da', 'Thượng Hải Chi Dạ', 'Shanghai Blues', 'https://phimimg.com/upload/vod/20250913-1/feb46c7e97c95ffb523f7c0a6961da84.jpg', 'https://phimimg.com/upload/vod/20250913-1/79d396be6d6c85f74106c90508f7e7f4.jpg', '<p>Năm 1937 tại Thượng Hải, trong một trận không kích của Nhật Bản, một người lính sắp ra trận tình cờ gặp một cô gái trẻ dưới gầm cầu. Họ hẹn ước sẽ gặp lại nhau sau khi chiến tranh kết thúc, nhưng lại không biết tên hay diện mạo của đối phương. Mười năm sau, cô gái năm ấy đã trở thành ca sĩ phòng trà và cưu mang một cô gái ngây thơ mới từ nông thôn lên thành phố. Cô gái quê say đắm chàng nhạc sĩ trẻ sống ở tầng trên – mà không hề hay biết anh chính là người lính năm xưa dưới gầm cầu.</p>', 'Full', 1, 'single', 'completed', 14, 1984, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Kenny Bee","avatar":""},{"name":"Sylvia Chang","avatar":""},{"name":"Sally Yeh","avatar":""},{"name":"Tin Ching","avatar":""},{"name":"Loletta Lee Lai-Chun","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Manfred Wong Man-Chun","avatar":""},{"name":"Fung Ging-Man","avatar":""},{"name":"Woo Fung","avatar":""},{"name":"Kong Lung","avatar":""},{"name":"Yue Ga-Hei","avatar":""},{"name":"Helen Ma Hoi-Lun","avatar":""},{"name":"Huang Man","avatar":""},{"name":"Tung Lo","avatar":""},{"name":"Ng Hon-Keung","avatar":""},{"name":"Siu Kin-Hang","avatar":""},{"name":"Chang Diy-Mei","avatar":""},{"name":"Tang Siu-Lam","avatar":""},{"name":"Ding Y","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug