INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-chuyen-phieu-luu-vao-xu-quy-1984', 'Doraemon: Nobita và Chuyến Phiêu Lưu Vào Xứ Quỷ', 'Doraemon: Nobita''s Great Adventure in the World of Magic', 'https://phimimg.com/upload/vod/20250521-1/00b381022bc9ea4ac7fbd46898aa9d9b.jpg', 'https://phimimg.com/upload/vod/20250521-1/a7091f3374a6930f49d515c4c3efd386.jpg', '<p>Nobita sử dụng Tủ điện thoại yêu cầu của Doraemon biến thế giới trở thành nơi có thể sử dụng phép thuật. Phép thuật thay thế khoa học và công nghệ và tất cả mọi người đều sử dụng nó trong cuộc sống hàng ngày của họ, ngoại trừ Nobita, người mà (như thường lệ) không giỏi trong việc sử dụng phép thuật. Chán nản, cậu ta định đưa mọi thứ trở về ban đầu, nhưng mẹ cậu đã vứt Tủ điện thoại yêu cầu vào bãi rác.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 1984, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Sachiko Chijimatsu","avatar":""},{"name":"Tadashi Nakamura","avatar":""},{"name":"Mami Koyama","avatar":""},{"name":"Keiko Yokozawa","avatar":""},{"name":"Sumiko Shirakawa","avatar":""},{"name":"Ryoichi Tanaka","avatar":""},{"name":"Kazuyo Aoki","avatar":""},{"name":"Masayuki Katô","avatar":""},{"name":"Toshiya Ueda","avatar":""},{"name":"Genzô Wakayama","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn T