INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-toi-cua-tinh-yeu', 'Mặt Tối Của Tình Yêu', 'The Dark Side Of Love', 'https://phimimg.com/upload/vod/20241101-1/cda18f273def58879f57f669967ab954.jpg', 'https://phimimg.com/upload/vod/20241101-1/20a4888891f86ab0d40101bc2b79fd9c.jpg', '<p>Mối quan hệ tình dục giữa một người phụ nữ thành đạt và anh trai cô ấy, một thanh niên sống nội tâm, đạo đức giả và cũng là một người mê phim khiêu dâm.</p>', 'Full', 1, 'single', 'completed', 20, 1984, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Monica Guerritore","avatar":""},{"name":"Lorenzo Lena","avatar":""},{"name":"Saverio Vallone","avatar":""},{"name":"Gilla Novak","avatar":""},{"name":"Gianfranco Manfredi","avatar":""},{"name":"Svevo Samperi","avatar":""},{"name":"Raffaele Fornaro","avatar":""},{"name":"Emanuele Fornaro","avatar":""},{"name":"Andrea Trevisan","avatar":""},{"name":"Matteo Briga","avatar":""},{"name":"Francesco Narducci","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Plaisirs interdits","Patrizia","Les plaisirs interdits","Hunger nach Zärtlichkeit","Patrizia: Hunger nach Zärtlichkeit","Patrizia, retratos de una mujer","Rakkauden hämärät kohteet","O Lado Sensual de Patricia","Фотографируя Патрицию","Aşkın Karanlık Yüzü","Темна сторона любові","Fotografando Patrizia"]', 1784690324549);
