INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-toi-cua-tinh-yeu', 'Mặt Tối Của Tình Yêu', 'The Dark Side Of Love', 'mặt tối của tình yêu the dark side of love monica guerritore lorenzo lena saverio vallone gilla novak gianfranco manfredi svevo samperi raffaele fornaro emanuele fornaro andrea trevisan matteo briga francesco narducci plaisirs interdits patrizia les plaisirs interdits hunger nach zärtlichkeit patrizia: hunger nach zärtlichkeit patrizia, retratos de una mujer rakkauden hämärät kohteet o lado sensual de patricia фотографируя патрицию aşkın karanlık yüzü темна сторона любові fotografando patrizia', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-vui-ve', 'Ma Vui Vẻ', 'The Happy Ghost', 'https://phimimg.com/upload/vod/20240930-1/c5def4a4eaa328954ca6011f47e72eb4.jpg', 'https://phimimg.com/upload/vod/20240930-1/8cce645f162cb0f207dcd29ed741ae4e.jpg', '<p>Nội dung của phim Ma Vui Vẻ bắt đầu từ việc ba cô nàng Bonnie (Bonnie Law), Juliet (Loletta Lee) và Venus (Sandy Lamb) rủ nhau cùng đi dã ngoại trước kỳ thi học kỳ. Trong chuyến đi, 3 người đã gặp phải một trận mưa lớn, họ phải tìm nơi đế trốn và vô tình họ lán lại tại một ngôi đền nhỏ, nơi mà Bonnie đã mang về từ đó một mẩu dây thừng bởi tính hiếu kỳ của cô. Tuy nhiên, Bonnie đã không hề biết rằng thứ mà cô đã đem về gắn liền với một hồn ma thời Trung Hoa cổ xưa, một học giả tên là Pik (Raymond Bak-Ming Wong). Mặc dù vậy, may mắn cho cô là con ma này rất “lành tính”, nó không những không hại cô mà Pik còn giúp Bonnie giành được giải thưởng trong cuộc thi thể thao ở trường, cũng như giúp đỡ Venus và Juliet nhiều việc khác. Dần dần, 3 ba cô gái bắt đầu phụ thuộc và những sự giúp dỡ của Pik trong mọi việc của mình.</p>', 'Full', 1, 'single', 'completed', 18, 1984, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"羅明珠","avatar":""},{"name":"Loletta Lee","avatar":""},{"name":"Sandy Lam San-San","avatar":""},{"name":"Raymond Wong","avatar":""},{"name":"Teresa Carpio","avatar":""},{"name":"Ng Siu-Gong","avatar":""},{"name":"Leung Shut-Fan","avatar":""},{"name":"Leung Yuen-Cheung","avatar":""},{"name":"Yu Chan-Kau","avatar":""},{"name":"Chi-Shan Lai","avatar":""},{"name":"Brenda Lo Yip-Mei","avatar":""},{"name":"Go Wang","avatar":""},{"name":"Amy Chin Siu-Wai","avatar":""},{"name":"Chan Kit-Ling","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["开心鬼","Happy Ghost","개심귀","개심귀 1","開心鬼"]', 1784690324549);
