INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-cong-chua-o-thung-lung-gio', 'Nàng Công Chúa Ở Thung Lũng Gió', 'Nausicaä of the Valley of the Wind', 'https://phimimg.com/upload/vod/20240920-1/1ef26e3c5a58eb9f4347583a7ffa19c3.jpg', 'https://phimimg.com/upload/vod/20240920-1/3c219d3f1501788f6e6d028f5c15c154.jpg', '<p>Khi tài nguyên thiên nhiên của hành tinh bị hủy hoại, công chúa chiến binh Nausicaa tập hợp thần dân của mình chống lại đội quân hung tàn của nữ hoàng độc ác.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 1984, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"島本須美","avatar":""},{"name":"永井一郎","avatar":""},{"name":"納谷悟朗","avatar":""},{"name":"松田洋治","avatar":""},{"name":"榊原良子","avatar":""},{"name":"家弓家正","avatar":""},{"name":"京田尚子","avatar":""},{"name":"辻村真人","avatar":""},{"name":"冨永みーな","avatar":""},{"name":"宮内幸平","avatar":""},{"name":"八奈見乗児","avatar":""},{"name":"矢田稔","avatar":""},{"name":"吉田理保子","avatar":""},{"name":"水鳥鐵夫","avatar":""},{"name":"菅谷政子","avatar":""},{"name":"Takako Sasuga","avatar":""},{"name":"坂本千夏","avatar":""},{"name":"TARAKO","avatar":""},{"name":"麦人","avatar":""},{"name":"坪井章子","avatar":""},{"name":"中村武己","avatar":""},{"name":"Takako Ota","avatar":""},{"name":"島田敏","avatar":""},{"name":"野村信次","avatar":""},{"name":"Hisako Ayuhara","avatar":""},{"name":"大塚芳忠","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["I nafsika tis koiladas ton anemon","Kaze no tani no Naushika","Навсікая з Долини Вітрів","Nausikaja iz Doline Vetra","Nausicaä - Prinzessin aus dem Tal der Winde","La princesse des étoiles","SternenKrieger - Warriors of the Wind","Наусика из Долины Ветров","Baram Gegok ui Nausika","Nausica of the Valley of the Wind","Kaze no Tani no Nausicaa","바람 계곡의 나우시카","Nausicaa of the Valley of the Wind","Nausicaa z Doliny Wiatru","Nausicaä – prinsessen fra Vindens dal","Nausicaä de la vallée du vent","Nausika del valle del viento","Valley of the Wind","Nausicaä do Vale do Vento","Nausicaä of the Valley of the Wind","Nausicaä aus dem Tal der Winde","Nausicaä del valle del viento","Le combat des princes de l''espace","風の谷のナウシカ"]', 1784690324549);
