INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nang-cong-chua-o-thung-lung-gio', 'Nàng Công Chúa Ở Thung Lũng Gió', 'Nausicaä of the Valley of the Wind', 'nàng công chúa ở thung lũng gió nausicaä of the valley of the wind 島本須美 永井一郎 納谷悟朗 松田洋治 榊原良子 家弓家正 京田尚子 辻村真人 冨永みーな 宮内幸平 八奈見乗児 矢田稔 吉田理保子 水鳥鐵夫 菅谷政子 takako sasuga 坂本千夏 tarako 麦人 坪井章子 中村武己 takako ota 島田敏 野村信次 hisako ayuhara 大塚芳忠 i nafsika tis koiladas ton anemon kaze no tani no naushika навсікая з долини вітрів nausikaja iz doline vetra nausicaä - prinzessin aus dem tal der winde la princesse des étoiles sternenkrieger - warriors of the wind наусика из долины ветров baram gegok ui nausika nausica of the valley of the wind kaze no tani no nausicaa 바람 계곡의 나우시카 nausicaa of the valley of the wind nausicaa z doliny wiatru nausicaä – prinsessen fra vindens dal nausicaä de la vallée du vent nausika del valle del viento valley of the wind nausicaä do vale do vento nausicaä of the valley of the wind nausicaä aus dem tal der winde nausicaä del valle del viento le combat des princes de l''espace 風の谷のナウシカ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-dai-nu-hoang-vo-tac-thien', 'Nhất Đại Nữ Hoàng - Võ Tắc Thiên', 'Empress Wu', 'https://phimimg.com/upload/vod/20240622-1/086c5c3c1649ac725edd24014ee15080.jpg', 'https://phimimg.com/upload/vod/20240622-1/c58b447a34ce380bfad9a9396201f63f.jpg', '<p><em>Tiết Nhơn Quý chinh Đông đánh Ma Thiên Lãnh chém Cáp Tô Văn, thâu phục nước Cao Ly (Hàn Quốc ngày nay). Sau đó đến lượt con trai Tiết Nhơn quý là Tiết Đinh San chính tay thâu phục các nước Tây Vực mở mang bờ cõi, thống nhất các nước Đại Đường cho Đường Thái Tôn Lý Thái Dân. Câu chuyện về Võ Tắc Thiên là một chuyện do Lâm Ngũ Đường viết vào thời Hậu Đường, dựa theo những sự kiện lịch sử có thật...Đường Thái Tôn trong một lần du hành cứu một thiếu nữ tên Võ Mị Nương - con gái Đô Đốc Lợi Châu Võ Sĩ Hoạch. Trong lần tuyển phi sau đó Thái Tôn đã cho tuyển Mị Nương vào cung phong làm Tài Nhân. Về sau có nhà tiên tri xem thiên văn cho vua biết được người con gái Lợi Châu họ Võ sau ba đời nhà Đường sẽ chiếm ngôi vua. Do vậy trước khi băng hà Lý Thái Tôn di chiếu cho đưa Võ Mị Nương đến một tu viện xa xôi hẻo lánh làm ni cô. Nhưng lúc này hoàng tử Lý Trị đã đem lòng yêu Võ Tài Nhân, nên sau đó đã tìm cách đưa nàng trở về cung. Lý Trị lên ngôi hoàng đế là một vị vua nhu nhược nên Võ Chiêu Nghi đã dần dần thu hết quyền hành trong tay. Sau khi Lý Trị chết các con của Lý Trị đều bất tài nên Võ Tắc Thiên đã phế vua và tự phong là Hoàng đế lập ra nhà Châu. Đây là lần đầu tiên và duy nhất trong lịch sử Trung Hoa một người đàn bà đã chính thức trở thành Hoàng Đế. Sau này cũng chính Tiết Giao và con cháu nhà họ Tiết đã giúp con cháu họ Lý khôi phục giang sơn nhà Đường. Nhà Hậu Đường là một thời thịnh trị và phát triển.</em></p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 17, 1984, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Phan Nghinh Tử","avatar":""},{"name":"Lương Tu Thân","avatar":""},{"name":"Hứa Gia Vinh","avatar":""},{"name":"Thôi Hạo Nhiên","avatar":""},{"name":"Tưởng Nhật Hành","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324549);
