INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ngon-tay-uot-at', 'Những Ngón Tay Ướt Át', 'Woman Who Wets Her Fingers', 'https://phimimg.com/upload/vod/20240804-1/b1520a8e5d41621db40804e7b63d0e9c.jpg', 'https://phimimg.com/upload/vod/20240804-1/a2b348a540f99cf6dc16dc1904cd5319.jpg', '<p>Vũ nữ thoát y ngoài đời thực Madoka Mika vào vai ROSE RED hư cấu, một cựu nữ hoàng thoát y hiện đang tham gia các buổi trình diễn lưu động trong khi cố gắng nuôi dạy con mình và cân bằng chuyện tình cảm của mình.</p>', 'Full', 1, 'single', 'completed', 18, 1984, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Madoka Mika","avatar":""},{"name":"Takashi Naito","avatar":""},{"name":"志水季里子","avatar":""},{"name":"Koichi Ueda","avatar":""},{"name":"Kibaji Tankobo","avatar":""},{"name":"Akira Takahashi","avatar":""},{"name":"Saburô Shôji","avatar":""},{"name":"Hideo Shirayama","avatar":""},{"name":"Seru Rando","avatar":""},{"name":"Tetsu Ōe","avatar":""},{"name":"Sue Mitobe","avatar":""},{"name":"Toshiyuki Kitami","avatar":""},{"name":"藤ひろ子","avatar":""},{"name":"Usagi Asō","avatar":""},{"name":"Makoto Yoshino","avatar":""},{"name":"廣田行生","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324549);
