INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-tu-bo-tron', 'Nữ Tu Bỏ Trốn', 'Gwendoline', 'https://phimimg.com/upload/vod/20240802-1/0ceffc24c51b4458b74522b7b63c28c3.jpg', 'https://phimimg.com/upload/vod/20240802-1/c9f05230bd54e27b56e8bbecb8abaa97.jpg', '<p>Gwendoline, một nữ tu bỏ trốn, đến Hồng Kông với nhiệm vụ tìm cha cô, người được nhìn thấy lần cuối ở Vùng đất huyền thoại của Yik Yak để tìm kiếm một con bướm quý hiếm. Cô ấy được hướng dẫn trên hành trình đầy nguy hiểm của mình bởi Willard lính đánh thuê ích kỷ.</p>', 'Full', 1, 'single', 'completed', 15, 1984, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Tawny Kitaen","avatar":""},{"name":"Brent Huff","avatar":""},{"name":"Zabou Breitman","avatar":""},{"name":"Bernadette Lafont","avatar":""},{"name":"Jean Rougerie","avatar":""},{"name":"Roland Amstutz","avatar":""},{"name":"Vernon Dobtcheff","avatar":""},{"name":"Takashi Kawahara","avatar":""},{"name":"Maurice Lamy","avatar":""},{"name":"Jim Adhi Limas","avatar":""},{"name":"Georges Lycan","avatar":""},{"name":"Roger Paschy","avatar":""},{"name":"Stanley Kapoul","avatar":""},{"name":"André Julien","avatar":""},{"name":"Kristopher Kum","avatar":""},{"name":"Loi Lam Duc","avatar":""},{"name":"Chen Chan","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324549);
