INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-tu-bo-tron', 'Nữ Tu Bỏ Trốn', 'Gwendoline', 'nữ tu bỏ trốn gwendoline tawny kitaen brent huff zabou breitman bernadette lafont jean rougerie roland amstutz vernon dobtcheff takashi kawahara maurice lamy jim adhi limas georges lycan roger paschy stanley kapoul andré julien kristopher kum loi lam duc chen chan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xu-cat', 'Xứ Cát', 'Dune', 'https://phimimg.com/upload/vod/20231023-1/8fd89e01eeee6811fdcdb2ef4007b613.jpg', 'https://phimimg.com/upload/vod/20231023-1/de16af144d9debce3a331f1412e214d5.jpg', '<p>Một miền cát Arrakis đầy bí ẩn và quyến rũ. Ở đó có nền khoa học kỹ thuật phát triển với tàu chim, máy tính – người Mentat, súng laze những vẫn đầy hoang sơ với những sinh vật đáng sợ như sâu cát. Ở đó có những mưu toan đấu đá giữa các gia tộc Atreides, Harkonnen, Corrino, và học viện Bene Gesserit, nhưng ở đó cũng toát lên nét thuần hậu của người Fremen và tình cảm chân thành giữa con người với nhau.</p>', 'Full', 1, 'single', 'completed', 18, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kyle MacLachlan","avatar":""},{"name":"Francesca Annis","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Linda Hunt","avatar":""},{"name":"José Ferrer","avatar":""},{"name":"Leonardo Cimino","avatar":""},{"name":"Freddie Jones","avatar":""},{"name":"Brad Dourif","avatar":""},{"name":"Richard Jordan","avatar":""},{"name":"Virginia Madsen","avatar":""},{"name":"Silvana Mangano","avatar":""},{"name":"Everett McGill","avatar":""},{"name":"Sting","avatar":""},{"name":"Kenneth McMillan","avatar":""},{"name":"Jack Nance","avatar":""},{"name":"Siân Phillips","avatar":""},{"name":"Jürgen Prochnow","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324549);
