INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-nhiem-doc-bao-thu', 'Người Hùng Nhiễm Độc Báo Thù', 'The Toxic Avenger', 'https://phimimg.com/upload/vod/20240228-1/c778d5f422cf7431863c31795319806e.jpg', 'https://phimimg.com/upload/vod/20240228-1/80e1665fe227aa5455739f2af40559ea.jpg', '<p>Tromaville có một anh hùng mới quái dị. Kẻ báo thù độc hại được sinh ra khi cậu bé lau nhà Melvin Junko rơi vào thùng chất thải độc hại. Bây giờ những kẻ làm ác sẽ có rất nhiều để mất.</p>', 'Full', 1, 'single', 'completed', 17, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Torgl","avatar":""},{"name":"Mitch Cohen","avatar":""},{"name":"Andree Maranda","avatar":""},{"name":"Pat Ryan","avatar":""},{"name":"Cindy Manion","avatar":""},{"name":"Patrick Kilpatrick","avatar":""},{"name":"Jennifer Prichard","avatar":""},{"name":"Robert Prichard","avatar":""},{"name":"Kenneth Kessler","avatar":""},{"name":"Gary Schneider","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324549);
