INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-cu-ngu', 'Người Cư Ngụ', 'The Occupant', 'https://phimimg.com/upload/vod/20240228-1/dad90d8913a10afaff7e84ab5ae7e010.jpg', 'https://phimimg.com/upload/vod/20240228-1/8468cd495f6ba5903d691290c324f292.jpg', '<p>Angie đến Hồng Kông để làm luận án thạc sĩ nói về sự mê tín của Trung Quốc. Cô thuê một căn hộ rộng rãi, mà không biết nó bị ám bởi hồn ma của một ca sĩ...</p>', 'Full', 1, 'single', 'completed', 19, 1984, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Raymond Wong","avatar":""},{"name":"Sally Yeh","avatar":""},{"name":"Chow Yun-fat","avatar":""},{"name":"Lo Lieh","avatar":""},{"name":"Melvin Wong Gam-Sam","avatar":""},{"name":"Judy Lee Chu-Dik","avatar":""},{"name":"Connie Mak","avatar":""},{"name":"Wellington Fung Wing","avatar":""},{"name":"Kenny Ho","avatar":""},{"name":"Yiu Yau-Hung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324549);
