INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-vao-nam-2010', 'Bí Ẩn Vào Năm 2010', '2010- The Year We Make Contact', 'https://phimimg.com/upload/vod/20240220-1/2a7dd2547c887f231ce93bed825b33d4.jpg', 'https://phimimg.com/upload/vod/20240220-1/a8c2660bb9e63e8664653246877d1a9f.jpg', '<p>2010: The Year We Make Contact kể về sự hợp tác bất đắc dĩ giữa Mỹ và Liên Xô để tìm hiểu nguyên nhân tai nạn 9 năm trước, việc cả một phi hành đoàn trên con tàu Discovery đã bị mất liên lạc khi đã tiếp cận được mặt trăng Europa của Sao Mộc. Lần này 1 phi hành đoàn khác được gửi đến Sao Mộc bằng phi thuyền Leonov của Liên Xô do cơ trưởng Tanya Kirbuk (Helen Mirren) nắm quyền với nhiệm vụ tìm kiếm con tàu Discovery và tìm hiểu những bí mật còn dang dở có thể đang nằm trong chiếc siêu máy tính có trí thông minh nhân tạo HAL 9000. Nhiệm vụ có vẻ dễ dàng khi các nhà khoa học Mỹ của tiến sĩ Heywood Floyd (Roy Scheider) cùng phi hành đoàn tiếp cận được con tàu Discovery và tái khởi động HAL 9000. Thế nhưng càng đi sâu vào phân tích dữ liệu, những bí mật ghê gớm về cỗ máy tính siêu thông minh đã dần hé lộ. Liệu lần này các phi hành gia có chung số phận với phi hành đoàn 9 năm trước đây không?</p>', 'Full', 1, 'single', 'completed', 19, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Roy Scheider","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Helen Mirren","avatar":""},{"name":"Bob Balaban","avatar":""},{"name":"Keir Dullea","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324549);
