INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-gian-la-mau', 'Đơn Giản Là Máu', 'Blood Simple', 'https://phimimg.com/upload/vod/20240220-1/cf8bf9f56683d16a19dd44ea8efc91b3.jpg', 'https://phimimg.com/upload/vod/20240220-1/b5d9fcd05c7b28d6d3c02f3021697813.jpg', '<p>Chủ một quán bar ở một thị trấn nhỏ tồi tàn ở Texas phát hiện ra rằng một trong những nhân viên của anh ta đang ngoại tình với vợ anh ta. Một chuỗi hiểu lầm hỗn loạn, dối trá và nghịch ngợm xảy ra sau khi anh ta lập ra một âm mưu giết họ.</p>', 'Full', 1, 'single', 'completed', 16, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Getz","avatar":""},{"name":"Frances McDormand","avatar":""},{"name":"Dan Hedaya","avatar":""},{"name":"M. Emmet Walsh","avatar":""},{"name":"Samm-Art Williams","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324549);
