INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('silent-night-deadly-night', 'Silent Night, Deadly Night', 'Silent Night, Deadly Night', 'https://phimimg.com/upload/vod/20240128-1/0924d6b2518f3d6938d72389cd4ce4ff.jpg', 'https://phimimg.com/upload/vod/20240128-1/9dc3c8e5840f431084a8c29718c3a788.jpg', '<p>Sau khi thấy cha mẹ bị giết trước mặt anh, một cậu bé dành phần lớn cuộc đời mình trong một trại trẻ mồ côi, nơi anh bị mẹ bị lạm dụng vượt trội. Khi anh ta trở thành thiếu niên, anh ta có một công việc như một ông già Noel cửa hàng đồ chơi. Khi nhìn thấy hai người quan hệ tình dục trong cửa hàng mang lại những đoạn hồi tưởng của cha mẹ, sự hỗn loạn của anh ta khiến anh ta trở thành một kẻ giết người nối tiếp Santa.</p>', 'Full', 1, 'single', 'completed', 13, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324549);
