INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ghostbusters', 'Ghostbusters', 'Ghostbusters', 'https://phimimg.com/upload/vod/20240128-1/3952fae9972af7206e9878bf1d108194.jpg', 'https://phimimg.com/upload/vod/20240128-1/e750b77d168cbff3f020140dce7bb3fe.jpg', '<p>Ghostbusters 1984 là bộ phim thuộc thể loại siêu nhiên hài hước của đạo diễn Ivan Reitman trở thành hiện tượng của thập niên 20. Nội dung phim kể về một nhóm các nhà khoa học lập dị đi bắt ma ở New York, và một ngôi nhà chọc trời ở khu buôn bán sầm uất vô tình trở thành nơi tập trung các hoạt động ma quỷ nên nó đã trở thành mục tiêu mà nhóm các nhà khoa học cần phải xử lý, nhưng mọi việc không hề dễ dàng....</p>', 'Full', 1, 'single', 'completed', 10, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bill Murray","avatar":""},{"name":"Dan Aykroyd","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Harold Ramis","avatar":""},{"name":"Rick Moranis","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324549);
