INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ghostbusters', 'Ghostbusters', 'Ghostbusters', 'ghostbusters ghostbusters bill murray dan aykroyd sigourney weaver harold ramis rick moranis ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-dong-chet', 'Cánh Đồng Chết', 'The Killing Fields', 'https://phimimg.com/upload/vod/20240104-1/90905c9c571705b919dd72a0bb089b03.jpg', 'https://phimimg.com/upload/vod/20240104-1/9a813a3851631123eb68d2f082c0d3a7.jpg', '<p>Câu chuyện bắt đầu vào tháng Năm năm 1973. Hai phóng viên Sydney Schanberg và Al Rockoff của tờ New York Times vừa đến thủ đô Phnom Penh để đưa tin về cuộc nội chiến giữa quân đội Campuchia và nhóm quân li khai Khmer Đỏ đang diễn ra hết sức ác liệt. Người chịu trách nhiệm tháp tùng họ trong những ngày công tác tại Campuchia là thông dịch viên Dith Pran. Sydney và Al đặt chân xuống sân bay chưa được bao lâu thì biến cố lớn xảy ra. Một quả bom B52 không hiểu vì lý do gì đã rơi thẳng xuống ngôi làng nhỏ Neak Leung. Các phóng viên quyết định vào cuộc để điều tra xem đây chỉ là một tai nạn hay là một vụ thảm sát có chủ đích. Tuy nhiên, họ lại vấp phải sự ngăn cản quyết liệt đến khó hiểu từ phía quân đội Mỹ. Bằng sự khôn khéo của mình, thông dịch viên Dith Pran cuối cùng cũng đưa được Sydney và Al đến tận hiện trường. Họ đã bàng hoàng cực độ khi chứng kiến một khung cảnh tang thương mà bom đạn chiến tranh gây ra... Hai năm sau, quân Khmer Đỏ thắng thế và tiến thẳng vào thủ đô. Tính mạng của tất cả những người nước ngoài đang sống tại đây đều bị đe dọa. Chính vì vậy, nhóm phóng viên quyết định quay về nước và đưa Dith Pran theo cùng. Nhưng Dith Pran lại không thể rời khỏi Campuchia và quãng đời còn lại của anh có thể sẽ bị chôn vùi vĩnh viễn trong nhà tù cải tạo của Khmer Đỏ...</p>', 'Full', 1, 'single', 'completed', 10, 1984, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sam Waterston","avatar":""},{"name":"Haing S. Ngor","avatar":""},{"name":"John Malkovich","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324549);
