INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('canh-dong-chet', 'Cánh Đồng Chết', 'The Killing Fields', 'cánh đồng chết the killing fields sam waterston haing s. ngor john malkovich ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tightrope', 'Tightrope', 'Tightrope', 'https://phimimg.com/upload/vod/20231214-1/f99af2abaaacc3ec202e5142e9c19f00.jpg', 'https://phimimg.com/upload/vod/20231214-1/aff8d042877248b1b94ae40cbd254fcd.jpg', '<p>Wes Block là một thám tử chuyên điều tra vụ án giết người hàng loạt. Nạn nhân của anh ta là những phụ nữ trẻ và xinh đẹp, những người mà anh ta hãm hiếp và giết chết. Các vụ giết người đang trở nên cá nhân khi kẻ giết người chọn nạn nhân là người quen của Block. Ngay cả con gái của ông cũng bị đe dọa.</p>', 'Full', 1, 'single', 'completed', 10, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clint Eastwood","avatar":""},{"name":"Geneviève Bujold","avatar":""},{"name":"Dan Hedaya","avatar":""},{"name":"Alison Eastwood","avatar":""},{"name":"Jenny Beck","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324549);
