INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-lam-tu-2-thieu-lam-tieu-tu', 'Thiếu Lâm Tự 2: Thiếu Lâm Tiểu Tử', 'Shaolin Temple 2: Kids From Shaolin', 'https://phimimg.com/upload/vod/20231214-1/87887ef6a8dfdd5b6620ddf3ad8848fa.jpg', 'https://phimimg.com/upload/vod/20231214-1/67883489d5ba9717ab21e1e580885fc2.jpg', '<p>Một cao thủ Võ Đang ẩn cư họ Bao sinh được 8 cô con gái. Nhà ở bờ sông, cách thôn dân bên cạnh một chiếc cầu. Tam Long cùng bạn bè chơi đùa ở gần đó, thường xuyên tìm cách trêu chọc đùa nghịch với các cô gái họ Bao. Đột nhiên có biến cố khủng khiếp xảy ra, và họ không thể chơi đùa với nhau được nữa...</p>', 'Full', 1, 'single', 'completed', 18, 1984, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jet Li","avatar":""},{"name":"Lan Ding","avatar":""},{"name":"Qiuyan Huang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324549);
