INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-phu-nu-ao-do', 'Người Phụ Nữ Áo Đỏ', 'The Woman In Red', 'https://phimimg.com/upload/vod/20231213-1/2aa2e5ebfab5a58cc4eaf0bb79640fde.jpg', 'https://phimimg.com/upload/vod/20231213-1/ff5f8957463184d98b4d26dfa3f44205.jpg', '<p>Khi một người đàn ông có gia đình hạnh phúc, người không bao giờ tính đến chuyện ngoại tình, gặp một người phụ nữ xinh đẹp mặc đồ đỏ, anh ta hoàn toàn say mê và khao khát được làm quen với cô ấy. Tuy nhiên, khi anh ta cố gắng thực hiện nhiều kế hoạch khác nhau để lẻn ra ngoài gặp cô, anh ta nhận ra rằng việc ngoại tình không hề dễ dàng như vẻ ngoài của nó.</p>', 'Full', 1, 'single', 'completed', 10, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Gene Wilder","avatar":""},{"name":"Charles Grodin","avatar":""},{"name":"Joseph Bologna","avatar":""},{"name":"Judith Ivey","avatar":""},{"name":"Kelly LeBrock","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324549);
