INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('splash', 'Splash', 'Splash', 'https://phimimg.com/upload/vod/20231211-1/2332df10c6398afa520aa4a13ffcbe3c.jpg', 'https://phimimg.com/upload/vod/20231211-1/68afa2bc5d52997506d5813020478926.jpg', '<p>Một doanh nhân thành đạt đem lòng yêu cô gái trong mộng của mình. Tuy nhiên, có một điều phức tạp lớn; anh ta rơi móc, câu và chìm cho một nàng tiên cá.</p>', 'Full', 1, 'single', 'completed', 10, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Hanks","avatar":""},{"name":"Daryl Hannah","avatar":""},{"name":"Eugene Levy","avatar":""},{"name":"John Candy","avatar":""},{"name":"Dody Goodman","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324549);
