INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-lang-bat-quai-con', 'Ngũ Lang Bát Quái Côn', 'The 8 Diagram Pole Fighter', 'https://phimimg.com/upload/vod/20231211-1/b37b7bafbfd385b29bb50d308cc20743.jpg', 'https://phimimg.com/upload/vod/20231211-1/e011ddce02bfa89dfe67756b4d79a3ad.jpg', '<p>Với sự giúp đỡ của tên phản tặc Phan Mỹ, vốn là Quốc trượng của triều đại nhà Tống, người Khiết Đan đã thống lĩnh đội quân Liêu Quốc đánh bẫy và tiêu diệt thành công Thống soái Dương Nghiệp và bảy đứa con trai của ông tại bãi Kim Khê. Dương Nghiệp và các con trai, người bị giết, người bị bắt, chỉ duy nhất con trai thứ năm và thứ sáu là chạy thoát. Trong lúc đó, người con trai thứ năm tìm nơi trú ẩn tại Thanh Lương Tự trên núi Ngũ Đài Sơn. Nhưng trụ trì của Thanh Lương Tự không cho rằng anh đủ tĩnh tâm để trở thành đệ tử phật môn.Vì không được mang vũ khí vào tự, nên anh đã sử dụng kĩ năng với thương để luyện tập với gậy, và cuối cùng tạo ra kĩ thuật bát quái côn độc nhất vô nhị. Khi cuối cùng anh cũng đã có thể trút được nỗi căm hận cũng như bỏ lại quá khứ của mình, thì có tin dữ rằng quân Khiết Đan đã bắt giữ tiểu muội, Dương Bát Muội, người đang đi tìm anh. Giờ, anh phải phá bỏ lời thề với đức Phật để cứu Bát Muội và trả món nợ thâm thù huyết hải</p>', 'Full', 1, 'single', 'completed', 13, 1984, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Gordon Liu Chia-Hui","avatar":""},{"name":"Kara Hui","avatar":""},{"name":"Alexander Fu Sheng","avatar":""},{"name":"Johnny Wang Lung-Wei","avatar":""},{"name":"Lily Li Li-Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324549);
