INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('amadeus', 'Amadeus', 'Amadeus', 'https://phimimg.com/upload/vod/20231208-1/a4a732b5e84dd08a91e3b9707f7f82cf.jpg', 'https://phimimg.com/upload/vod/20231208-1/317bb18aea025224bfe42d56ed532981.jpg', '<p>Antonio Salieri tin rằng âm nhạc của Wolfgang Amadeus Mozart là thiêng liêng và kỳ diệu. Anh ta chúc anh ta là một nhạc sĩ giỏi như Mozart để anh ta có thể ca ngợi Chúa thông qua sáng tác. Ông bắt đầu sự nghiệp của mình như một người đàn ông sùng đạo tin rằng thành công và tài năng của mình với tư cách là một nhà soạn nhạc là những phần thưởng của Chúa cho lòng đạo đức của mình. Ông cũng là nội dung như sự tôn trọng, tốt về tài chính, nhà soạn nhạc tòa án của Hoàng đế Joseph II. Nhưng anh ta bị sốc khi biết rằng Mozart là một sinh vật thô tục như vậy, và không thể hiểu tại sao Thiên Chúa ủng hộ Mozart là nhạc cụ của mình. Sự đố kị của Salieri đã khiến anh ta trở thành kẻ thù của Thiên Chúa có sự vĩ đại được thể hiện rõ trong Mozart. Anh ấy sẵn sàng trả thù Chúa và Mozart cho sự tầm thường của chính mình.</p>', 'Full', 1, 'single', 'completed', 11, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '[]', 1784690324549);
