INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-trek-3-hanh-trinh-di-tim-spock', 'Star Trek 3: Hành Trình Đi Tìm Spock', 'Star Trek III: The Search For Spock', 'https://phimimg.com/upload/vod/20231208-1/a77e9fe4b9642dd0289c74c7bc9c2861.jpg', 'https://phimimg.com/upload/vod/20231208-1/c6970b811933391c49ae612e253f5ce8.jpg', '<p>Đô đốc Kirk và thủy thủ đoàn cầu của ông mạo hiểm đánh cắp con tàu Enterprise đã ngừng hoạt động để quay trở lại hành tinh Genesis bị hạn chế nhằm thu hồi thi thể của Spock.</p>', 'Full', 1, 'single', 'completed', 9, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"William Shatner","avatar":""},{"name":"DeForest Kelley","avatar":""},{"name":"Robin Curtis","avatar":""},{"name":"Merritt Butrick","avatar":""},{"name":"Christopher Lloyd","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324549);
