INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-than-lua', 'Cô Bé Thần Lửa', 'Firestarter', 'https://phimimg.com/upload/vod/20231129-1/05afcf8e88d52b5f3298586479771b61.jpg', 'https://phimimg.com/upload/vod/20231129-1/70b0c179319b243b029cf15cb8ea700d.jpg', '<p>Andrew và Vicky McGee đã gặp gỡ nhau khi tham gia vào một cuộc thí nghiệm nhằm kiếm tiền nuôi thân. Đây là cuộc thí nghiệm được tiến hành bằng cách thử khâm liệm con người để tìm ra thế giới bí mật của tâm linh. Sau đó, cả hai tổ chức đám cưới và sinh ra một bé gái xinh xắn, Charile. Kết quả của cuộc thí nghiệm đã ảnh hưởng đến Charile, khiến cô bé có khả năng đốt cháy mọi thứ chỉ bằng một ý nghĩ. Andy cũng phát hiện ra khả năng kỳ lạ của mình bằng cách biến mọi người xung quanh phải làm theo mong muốn của cô. Gia đình đặc biệt này một lần nữa lại rơi vào tầm ngắm của tiến sĩ Joseph Wanless, ông dự tính sẽ tiếp tục đem họ làm thí nghiệm trước khi giết họ.</p>', 'Full', 1, 'single', 'completed', 10, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Drew Barrymore","avatar":""},{"name":"David Keith","avatar":""},{"name":"Freddie Jones","avatar":""},{"name":"Heather Locklear","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"George C. Scott","avatar":""},{"name":"Art Carney","avatar":""},{"name":"Louise Fletcher","avatar":""},{"name":"Moses Gunn","avatar":""},{"name":"Antonio Fargas","avatar":""},{"name":"Drew Snyder","avatar":""},{"name":"Curtis Credel","avatar":""},{"name":"Keith Colbert","avatar":""},{"name":"Dick Warlock","avatar":""},{"name":"Jeff Ramsey","avatar":""},{"name":"Jack Magner","avatar":""},{"name":"Lisa Anne Barnes","avatar":""},{"name":"Larr","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324549);
