INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('starman', 'Starman', 'Starman', 'https://phimimg.com/upload/vod/20231120-1/18cf4a5d251a8438054ddac30dab15ca.jpg', 'https://phimimg.com/upload/vod/20231120-1/079fda613ec88bdfcc5d805fd11a0cc3.jpg', '<p>Khi một người ngoài hành tinh đội lốt chồng của một góa phụ trẻ và yêu cầu cô chở anh ta từ Wisconsin đến Arizona, chính phủ cố gắng ngăn chặn họ.</p>', 'Full', 1, 'single', 'completed', 11, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeff Bridges","avatar":""},{"name":"Karen Allen","avatar":""},{"name":"Charles Martin Smith","avatar":""},{"name":"Richard Jaeckel","avatar":""},{"name":"Robert Phalen","avatar":""},{"name":"Tony Edwards","avatar":""},{"name":"John Walter Davis","avatar":""},{"name":"Ted White","avatar":""},{"name":"Dirk Blocker","avatar":""},{"name":"M.C. Gainey","avatar":""},{"name":"Sean Stanek","avatar":""},{"name":"George Buck Flower","avatar":""},{"name":"Russ Benning","avatar":""},{"name":"Ralph Cosham","avatar":""},{"name":"David Wells","avatar":""},{"name":"Anthony Grumbach","avatar":""},{"name":"James Deeth","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324549);
