INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gremlins', 'Gremlins', 'Gremlins', 'https://phimimg.com/upload/vod/20231113-1/fe503d42891caa26f82397dd4662e4a8.jpg', 'https://phimimg.com/upload/vod/20231113-1/fcf8f4c664baa972b267bb79d6ce6b59.jpg', '<p>Khi Billy Peltzer được tặng một con thú cưng kỳ lạ nhưng đáng yêu tên là Gizmo vào dịp Giáng sinh, anh ấy đã vô tình vi phạm ba quy tắc quan trọng trong việc chăm sóc Mogwai và giải phóng một bầy yêu tinh tinh nghịch vào một thị trấn nhỏ.</p>', 'Full', 1, 'single', 'completed', 15, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Zach Galligan","avatar":""},{"name":"Phoebe Cates","avatar":""},{"name":"Hoyt Axton","avatar":""},{"name":"Frances Lee McCain","avatar":""},{"name":"Corey Feldman","avatar":""},{"name":"Keye Luke","avatar":""},{"name":"John Louie","avatar":""},{"name":"Dick Miller","avatar":""},{"name":"Jackie Joseph","avatar":""},{"name":"Polly Holliday","avatar":""},{"name":"Judge Reinhold","avatar":""},{"name":"Edward Andrews","avatar":""},{"name":"Belinda Balaski","avatar":""},{"name":"Scott Brady","avatar":""},{"name":"Susan Burgess","avatar":""},{"name":"Harry Carey","avatar":""},{"name":"Jr.","avatar":""},{"name":"Donald Elson","avatar":""},{"name":"Jon","avatar":""}]', '[{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324549);
