INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('paris-va-texas', 'Paris và Texas', 'Paris, Texas', 'https://phimimg.com/upload/vod/20231111-1/e441cbd766024de7417922fe6c188cd1.jpg', 'https://phimimg.com/upload/vod/20231111-1/3a77d37daaa15b795d05970aa1a28e41.jpg', '<p>Travis trở về sau 4 năm mất tích, anh xuất hiện trong một sa mạc vùng biên giới Mexico, trong tình trạng rách rưới, đói khát và hầu như không nhớ được điều gì. Sau khi xộc vào một quán rượu tìm nước, anh ngã quỵ xuống. Một bác sĩ đã cứu sống anh. Theo địa chỉ ghi trong một tờ giấy nhét sâu trong ví, người ta gọi cho em trai anh - Walt - một nhân viên thiết kế biển quảng cáo. Travis bắt đầu cuộc hành trình làm quen trở lại với đứa con trai đã lên 7 và đi tìm người vợ trẻ đã bỏ rơi anh - Jane.</p>', 'Full', 1, 'single', 'completed', 15, 1984, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Harry Dean Stanton","avatar":""},{"name":"Nastassja Kinski","avatar":""},{"name":"Dean Stockwell","avatar":""},{"name":"Hunter Carson","avatar":""},{"name":"Aurore Clément","avatar":""},{"name":"Bernhard Wicki","avatar":""},{"name":"John Lurie","avatar":""},{"name":"Jeni Vici","avatar":""},{"name":"Sally Norvell","avatar":""},{"name":"Socorro Valdez","avatar":""},{"name":"Claresie Mobley","avatar":""},{"name":"Viva","avatar":""},{"name":"Tom Farrell","avatar":""},{"name":"Sam Berry","avatar":""},{"name":"Edward Fayton","avatar":""},{"name":"Justin Hogg","avatar":""},{"name":"Sharon Menzel","avatar":""},{"name":"The Mydoll","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324549);
