INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-beverly-hills', 'Cảnh Sát Beverly Hills', 'Beverly Hills Cop', 'https://phimimg.com/upload/vod/20231030-1/06ceeb406ab535eed839b6c87b5abc01.jpg', 'https://phimimg.com/upload/vod/20231030-1/2effc8b3c2c9ff8da2e3aa723545ea29.jpg', '<p>Nội dung phim xoay quanh chuyến đi đến Los Angleles của anh chàng cảnh sát Axel Foley(Eddie Murphy), một viên cảnh sát rất lắm lời ở Detroit. Sau khi bạn anh gặp rắc rối, anh đã phá vỡ mọi quy luật cần có của một cảnh sát và đặt vé bay thẳng đến Los Angleles để tìm nguyên nhân cái chết của bạn mình. Ở đây, anh đã lần theo dấu vết của những kẻ giết người trên những con phố xa hoa của Beverly Hills, và anh đã gặp không ít chuyện rắc rối trong cuộc truy tìm đầy gian nan này...</p>', 'Full', 1, 'single', 'completed', 11, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Eddie Murphy","avatar":""},{"name":"Judge Reinhold","avatar":""},{"name":"John Ashton","avatar":""},{"name":"Lisa Eilbacher","avatar":""},{"name":"Ronny Cox","avatar":""},{"name":"Steven Berkoff","avatar":""},{"name":"James Russo","avatar":""},{"name":"Jonathan Banks","avatar":""},{"name":"Stephen Elliott","avatar":""},{"name":"Gilbert R. Hill","avatar":""},{"name":"Art Kimbro","avatar":""},{"name":"Joel Bailey","avatar":""},{"name":"Bronson Pinchot","avatar":""},{"name":"Paul Reiser","avatar":""},{"name":"Michael Champion","avatar":""},{"name":"Frank Pesce","avatar":""},{"name":"Gene Borkan","avatar":""},{"name":"Michael","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324549);
