INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-bat-tan', 'Câu Chuyện Bất Tận', 'The NeverEnding Story', 'https://phimimg.com/upload/vod/20231025-1/d5a219c08dc25a54489f269ea36e9358.jpg', 'https://phimimg.com/upload/vod/20231025-1/e43426f03bcdc125bed3d084372e560c.jpg', '<p>Trong khi trốn tránh những kẻ bắt nạt trên gác mái của trường, một cậu bé khám phá ra vùng đất Fantasia phi thường thông qua một cuốn sách ma thuật có tên Câu chuyện bất tận. Cuốn sách kể về câu chuyện của Atreyu, một chiến binh trẻ, với sự giúp đỡ của một con rồng may mắn. tên là Falkor, phải cứu Fantasia khỏi sự hủy diệt của The Nothing.</p>', 'Full', 1, 'single', 'completed', 18, 1984, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Noah Hathaway","avatar":""},{"name":"Barret Oliver","avatar":""},{"name":"Tami Stronach","avatar":""},{"name":"Moses Gunn","avatar":""},{"name":"Patricia Hayes","avatar":""},{"name":"Sydney Bromley","avatar":""},{"name":"Tilo Prückner","avatar":""},{"name":"Gerald McRaney","avatar":""},{"name":"Chris Eastman","avatar":""},{"name":"Darryl Cooksey","avatar":""},{"name":"Nicholas Gilbert","avatar":""},{"name":"Thomas Hill","avatar":""},{"name":"Deep Roy","avatar":""},{"name":"Beth Anderson","avatar":""},{"name":"Donald Arthur","avatar":""},{"name":"Bernd Eichinger","avatar":""},{"name":"Dee Harris","avatar":""},{"name":"Fran","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324549);
