INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoc-my-mot-thoi', 'Nước Mỹ Một Thời', 'Once Upon a Time in America', 'https://phimimg.com/upload/vod/20231024-1/3775b9e331492d4a3c0fbb91220a1916.jpg', 'https://phimimg.com/upload/vod/20231024-1/867997d08d31fec79f4d7e3d6e230860.jpg', '<p>Bộ phim Nước Mỹ một thời với chủ đề hết sức đa dạng từ tình bạn, tình yêu, tình dục, lòng tham, sự phản bội, sự mất mát. Phim chia thành 3 giai đoạn trong lịch sử nước Mỹ: những năm đầu thập niên 20, khoảng năm 1933 và năm 1968. Nhân vật chính trong phim là Noodles một đứa trẻ đường phố ở New York chuyên đi móc túi, cướp giật. Noodles thầm yêu Deborah và thường nhìn trộm Deborah tập múa, Deborah vừa yêu vừa sợ Noodles nên chuyện tình khá thú vị. Tuy nhiên sau lệnh cấm rượu của nước Mỹ, băng nhóm của Noodles đã tham gia kinh doanh bất hợp pháp món hàng này và đụng độ với một băng nhóm khác dẫn đến cái chết của 1 thành viên. Bộ phim với nhiều cảnh bạo lực nhưng phản ánh vô cùng chân thực nước Mỹ thời kỳ này.</p>', 'Full', 1, 'single', 'completed', 19, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"James Woods","avatar":""},{"name":"Elizabeth McGovern","avatar":""},{"name":"Treat Williams","avatar":""},{"name":"Tuesday Weld","avatar":""},{"name":"Joe Pesci","avatar":""},{"name":"Burt Young","avatar":""},{"name":"James Hayden","avatar":""},{"name":"William Forsythe","avatar":""},{"name":"Larry Rapp","avatar":""},{"name":"Amy Ryder","avatar":""},{"name":"Scott Schutzman Tiler","avatar":""},{"name":"Rusty Jacobs","avatar":""},{"name":"Jennifer Connelly","avatar":""},{"name":"Brian Bloom","avatar":""},{"name":"Adrian Curran","avatar":""},{"name":"Mike Monetti","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324549);
