INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-6-ngay-13-hoi-cuoi', 'Thứ 6 Ngày 13: Hồi Cuối', 'Friday the 13th: The Final Chapter', 'https://phimimg.com/upload/vod/20231023-1/f05a69b6c62f0441cb28f71b291e078b.jpg', 'https://phimimg.com/upload/vod/20231023-1/46ac2e0a924f32d3b4cf2e533bdba76d.jpg', '<p>Sau khi hồi sinh trong nhà xác bệnh viện, Jason tập trung sự chú ý báo thù vào gia đình Jarvis và một nhóm thanh thiếu niên cho đến nay vẫn vô tư.</p>', 'Full', 1, 'single', 'completed', 14, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Judie Aronson","avatar":""},{"name":"Kimberly Beck","avatar":""},{"name":"Joan Freeman","avatar":""},{"name":"Barbara Howard","avatar":""},{"name":"Corey Feldman","avatar":""},{"name":"Erich Anderson","avatar":""},{"name":"Peter Barton","avatar":""},{"name":"Crispin Glover","avatar":""},{"name":"Clyde Hayes","avatar":""},{"name":"Lawrence Monoson","avatar":""},{"name":"Camilla More","avatar":""},{"name":"Carey More","avatar":""},{"name":"Bonnie Hellman","avatar":""},{"name":"Lisa Freeman","avatar":""},{"name":"Bruce Mahler","avatar":""},{"name":"Frankie Hill","avatar":""},{"name":"Wayne Grace","avatar":""},{"name":"Willia","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324549);
