INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('indiana-jones-va-ngoi-den-chet-choc', 'Indiana Jones và Ngôi Đền Chết Chóc', 'Indiana Jones and the Temple of Doom', 'https://phimimg.com/upload/vod/20231023-1/3a9221881bd84bbdf8e20fa38ec9a356.jpg', 'https://phimimg.com/upload/vod/20231023-1/2c4e0f464c5c01b7aee1da5728a32fff.jpg', '<p>May mắn thoát hiểm trong một vụ giao dịch không thành với một tay buôn đồ cổ xảo quyệt người Trung Quốc, máy bay của Tiến sĩ Indiana Jones (Harrison Ford) rơi xuống một vùng đất hẻo lánh ở Ấn Độ. Nơi đây vừa bị kẻ xấu cướp mất những viên đá thiêng, khiến cuộc sống dân chúng trở nên điêu đứng.Tiến sĩ Jones và bạn bè đồng ý giúp đỡ ngôi làng, tới cung điện của thủ tướng Chatter Lal hỏi thăm. Mặc dù anh ta không hiểu chuyện gì đã xảy ra nhưng vẫn mời họ nghỉ lại lâu đài một đêm. Tuy nhiên, chính trong đêm đó, tiến sĩ Jones phát hiện ra một hệ thống hang động ngầm dẫn đến bí mật của những vụ trẻ em mất tích và cả bí ẩn đằng sau 5 hòn đá quyền lực của Sankara. Đã đến lúc ông vào cuộc, lấy lại ...</p>', 'Full', 1, 'single', 'completed', 13, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Kate Capshaw","avatar":""},{"name":"Ke Huy Quan","avatar":""},{"name":"Amrish Puri","avatar":""},{"name":"Roshan Seth","avatar":""},{"name":"Philip Stone","avatar":""},{"name":"Roy Chiao","avatar":""},{"name":"David Yip","avatar":""},{"name":"Ric Young","avatar":""},{"name":"Chua Kah Joo","avatar":""},{"name":"Rex Ngui","avatar":""},{"name":"Philip Tan","avatar":""},{"name":"Dan Aykroyd","avatar":""},{"name":"Akio Mitamura","avatar":""},{"name":"Michael Yama","avatar":""},{"name":"D.R. Nanayakkara","avatar":""},{"name":"Dharmadasa Kuruppu","avatar":""},{"name":"Stany De Silva","avatar":""},{"name":"Ruby de","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324549);
