INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-do-ky-cua-thien-tai', 'Sự Đố Kỵ Của Thiên Tài', 'Amadeus', 'https://phimimg.com/upload/vod/20231016-1/5a58c05547939c0a942264806b7f2a27.jpg', 'https://phimimg.com/upload/vod/20231016-1/afa5db4045aa0c83bbd2045870e97cef.jpg', '<p>Amadeus tái hiện một phần cuộc đời của Wolfgang Amadeus Mozart, nhạc sĩ thiên tài người Áo, và Antonio Salieri, cũng là một nhạc sĩ tài năng cùng thời với Mozart. Antonio Salieri được cho là người đã gián tiếp gây nên cái chết của Mozart, khiến thần đồng âm nhạc này qua đời ở tuổi 35 (vào năm 1791) Amadeus không phải là bộ phim xây dựng nên một khuôn mẫu Mozart hoàn hảo để mọi khán giả yêu điện ảnh cũng như yêu âm nhạc cổ điển có thể chiêm ngưỡng. Hình ảnh của ông trong phim được xây dựng theo một góc độ khác, hết sức chân thực: một con người tục tĩu, đôi khi như một anh hề, một người con kính nể cha, làm việc cật lực nhưng lại nợ nần chồng chất, nhưng trên hết là một nhà soạn nhạc thiên tài của mọi thời đại</p>', 'Full', 1, 'single', 'completed', 26, 1984, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"F. Murray Abraham","avatar":""},{"name":"Tom Hulce","avatar":""},{"name":"Elizabeth Berridge","avatar":""},{"name":"Roy Dotrice","avatar":""},{"name":"Simon Callow","avatar":""},{"name":"Christine Ebersole","avatar":""},{"name":"Jeffrey Jones","avatar":""},{"name":"Barbara Bryne","avatar":""},{"name":"Cynthia Nixon","avatar":""},{"name":"Douglas Seale","avatar":""},{"name":"Charles Kay","avatar":""},{"name":"Kenny Baker","avatar":""},{"name":"Martin Cavina","avatar":""},{"name":"Roderick Cook","avatar":""},{"name":"Milan Demjanenko","avatar":""},{"name":"Peter DiGesu","avatar":""},{"name":"Patrick Hi","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324549);
