INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tu-hieu-cau', 'Quân Tử Hiếu Cầu', 'The Other Side Of Gentleman', 'https://phimimg.com/upload/vod/20231010-1/f76178d2e5929adc55de3fb578f50cd6.jpg', 'https://phimimg.com/upload/vod/20231010-1/81c3ff1d9eacfccb8a87f4091521a86f.jpg', '<p>Là một phần của thí nghiệm xã hội học, Brigitte Lin cố gắng khiến tay chơi tầng lớp thấp hơn Alan Tam phải lòng cô. Anh không chỉ phải lòng cô mà còn thấy khó có thể quay lại cuộc sống ăn chơi của mình.</p>', 'Full', 1, 'single', 'completed', 18, 1984, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Alan Tam","avatar":""},{"name":"Brigitte Lin","avatar":""},{"name":"Chang Kuo-Chu","avatar":""},{"name":"Bennett Pang Kin-San","avatar":""},{"name":"Kan Yee-Ching","avatar":""},{"name":"Chan Chi-Wing","avatar":""},{"name":"Barry Wong","avatar":""},{"name":"Pamela Pak","avatar":""},{"name":"Stephen Tung Wai","avatar":""},{"name":"Fung Ging-Man","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324549);
