INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-vui-ve', 'Giáng Sinh Vui Vẻ', 'Merry Christmas', 'https://phimimg.com/upload/vod/20231010-1/b2d96b3f4dc612a0080981d348a72b36.jpg', 'https://phimimg.com/upload/vod/20231010-1/7a55075527b9ef679f5e0bf15cfd0236.jpg', '<p>Một góa phụ tên Baldy (Karl Maka) khao khát người hàng xóm đáng yêu của mình, nhưng không đủ can đảm để nói với cô ấy cho đến khi một người đàn ông khác bước vào bức tranh và cưỡng bức anh ta. Biết Mak, biên tập viên trung niên của tờ báo, thường xuyên nhớ đến người vợ quá cố của mình, những đứa con yêu quý của ông đã thuyết phục ông hẹn hò với Siu Fung, ca sĩ sống cạnh nhà. Đúng lúc này, chú Sam, anh họ của Siu Fung, từ Mỹ trở về và cầu hôn Siu Fung. Một ngày nọ, mâu thuẫn xảy ra giữa Sam và Mak khiến Siu Fung nổi giận với Mak..</p>', 'Full', 1, 'single', 'completed', 20, 1984, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Karl Maka","avatar":""},{"name":"Paula Tsui","avatar":""},{"name":"Danny Chan Bak-Keung","avatar":""},{"name":"Loletta Lee","avatar":""},{"name":"Angile Leung Wan Yui","avatar":""},{"name":"Cyrus Wong Ka-Ming","avatar":""},{"name":"Leslie Cheung","avatar":""},{"name":"Yuen Woo-ping","avatar":""},{"name":"Go Wang","avatar":""},{"name":"Sandy Lam","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324549);
