INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dang-dai-le-minh', 'Đẳng Đãi Lê Minh', 'Hong Kong 1941', 'https://phimimg.com/upload/vod/20231007-1/987813596cd0d1e59bbc69edf411b428.jpg', 'https://phimimg.com/upload/vod/20231007-1/dd5e8bbfdec1f24aa41a9f8da10e8ad0.jpg', '<p>Nhiều năm sau, một người phụ nữ kể lại câu chuyện cá nhân của mình về việc Nhật Bản tiếp quản Hồng Kông vào năm 1941. Cô ấy là Nam, trẻ trung, hấp dẫn, con gái của một thương gia buôn gạo giàu có và là nạn nhân của những cơn động kinh đau đớn, tàn tật. Người bạn thời thơ ấu của cô là Coolie Keung, người có gia đình từng rất giàu có; anh bây giờ nghèo khó, một đứa trẻ cứng rắn, một nhà lãnh đạo, yêu cô. Tham gia vào các bước kết hợp Fay, lạnh lùng và tháo vát, một diễn viên đến từ miền Bắc, có ý định đến Gold Mountain ở Mỹ hoặc Úc. Họ tạo thành một nhóm ba người, nhưng vào ngày họ rời Hồng Kông, cuộc xâm lược đã ngăn cản họ. Fay phải giải cứu Keung khỏi những kẻ cộng tác, Nam phải lòng Fay và nguy hiểm đang chờ đợi nỗ lực trốn thoát tiếp theo của họ. Được viết bởi</p>', 'Full', 1, 'single', 'completed', 17, 1984, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Chow Yun-fat","avatar":""},{"name":"Alex Man","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Paul Chun","avatar":""},{"name":"Cecilia Yip","avatar":""},{"name":"Ku Feng","avatar":""},{"name":"Angela Yu Chien","avatar":""},{"name":"Yee San Hon","avatar":""},{"name":"Sai-Kit Yung","avatar":""},{"name":"Po-Chih Leong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324549);
