INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-hai-giai-doan', 'Luật Hai Giai Đoạn', 'Law With Two Phases', 'https://phimimg.com/upload/vod/20231006-1/657da3b55a0a42f37ca19a1d653d50aa.jpg', 'https://phimimg.com/upload/vod/20231006-1/d60df8d15bccf66a4f4c9dceb9b20b7d.jpg', '<p>Hief B (Danny Lee) là một thành viên CID độc đáo, người dựa nhiều vào bản năng hơn là cuốn sách để giải quyết các tình huống. Anh ấy là một người thực tế, là con trai của mẹ, không được giáo dục quá tốt và là thành viên xuất sắc của CID. Sĩ quan cảnh sát Kit (Eddie Chan) vừa được thăng cấp từ cấp bậc lên CID, đồng thời đang ôn thi để trở thành Thanh tra. Cảnh sát trưởng B dẫn dắt anh ta để điều tra nhiều vụ án liên quan đến băng đảng. Kit, trước đây là loại cảnh sát bình thường, học được rất nhiều điều từ Cảnh sát trưởng B.</p>', 'Full', 1, 'single', 'completed', 19, 1984, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Danny Lee Sau-Yin","avatar":""},{"name":"Eddie Chen","avatar":""},{"name":"Tai Bo","avatar":""},{"name":"Parkman Wong","avatar":""},{"name":"Rico Chu","avatar":""},{"name":"Ou-Yang Sha-Fei","avatar":""},{"name":"Patricia Chong Jing-Yee","avatar":""},{"name":"Yu Miu-Lin","avatar":""},{"name":"So Hang-Suen","avatar":""},{"name":"Shing Fui-On","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324549);
