INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-benh-hoan-loan-tri', 'Kẻ Bệnh Hoạn (Loạn Trí)', 'Angst', 'https://phimimg.com/upload/vod/20260502-1/3b15e1bfb240044ee5a53cceffd59805.jpg', 'https://phimimg.com/upload/vod/20260502-1/4d60da7ee65d06193efe06926c8c0965.jpg', '<p>Phim kể về một người đàn ông được ra tù sau khi phục vụ mười năm vì tội giết một người phụ nữ lớn tuổi. Anh nhanh chóng bắt đầu cảm thấy sự cưỡng bách để giết một lần nữa. Sau khi thất bại trong việc giết chết một tài xế taxi, anh bỏ chạy và phát hiện ra một ngôi nhà nông thôn hẻo lánh, nơi mà một người phụ nữ trẻ sống với người mẹ ốm yếu và em trai tàn tật. Sau đó, ông bắt đầu đưa ra những thú vui bệnh hoạn của mình vào chúng, cố gắng giữ họ làm con tin, trong khi nghĩ về thời thơ ấu khó khăn của anh với mẹ lạm dụng của mình và bà ngoại …</p>', 'Full', 1, 'single', 'completed', 22, 1983, 'Vietsub', 'FHD', 'Áo', 0, '[{"name":"Erwin Leder","avatar":""},{"name":"Robert Hunger-Bühler","avatar":""},{"name":"Silvia Rabenreither","avatar":""},{"name":"Karin Springer","avatar":""},{"name":"Edith Rosset","avatar":""},{"name":"Josefine Lakatha","avatar":""},{"name":"Rudolf Götz","avatar":""},{"name":"Renate Kastelik","avatar":""},{"name":"Hermann Groissenberger","avatar":""},{"name":"Claudia Schinko","avatar":""},{"name":"Beate Jurkowitsch","avatar":""},{"name":"Rosa Schandl","avatar":""},{"name":"Rolf Bock","avatar":""},{"name":"Emil Polaczek","avatar":""},{"name":"Helmut Hrdina","avatar":""},{"name":"Adolf","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Schizophrenia, le tueur de l''ombre","S