INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-xe-den-phan-2', 'Hiệp Sĩ Xe Đen (Phần 2)', 'Knight Rider (Season 2)', 'https://phimimg.com/upload/vod/20251208-1/3019e9b73e8f15d084236067bcfdd050.jpg', 'https://phimimg.com/upload/vod/20251208-1/f347c5b21946fef36cd721763bd2cc77.jpg', '<p><span style="text-wrap-mode: wrap;">Michael Long, một sĩ quan cảnh sát chìm, bị bắn trọng thương trong lúc điều tra và bị những kẻ tấn công bỏ mặc cho đến chết.Anh được cứu bởi Wilton Knight, một triệu phú sắp qua đời và là nhà phát minh giàu có. Wilton đã sắp xếp một cuộc phẫu thuật cứu mạng cho Michael, bao gồm một khuôn mặt mới và một danh tính mới—là Michael Knight.Michael sau đó được giao một chiếc xe đặc biệt, không thể phá hủy và được trang bị máy tính hóa, gọi là Knight Industries Two Thousand (thường được gọi là KITT), cùng với một nhiệm vụ: bắt giữ những tên tội phạm nằm ngoài tầm với của pháp luật.Bộ phim mô tả các cuộc phiêu lưu của Michael khi anh và KITT chiến đấu với các thế lực tà ác dưới danh nghĩa Quỹ Luật pháp và Chính phủ.</span></p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 1983, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Hasselhoff","avatar":""},{"name":"Edward Mulhare","avatar":""},{"name":"William Daniels","avatar":""},{"name":"Patricia McPherson","avatar":""},{"name":"Peter Parros","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["El auto fantástico","Рицарят ездач","Super Máquina","霹雳游侠","Knight Rider (1982)","Knight Rider classic","K 2000","Ο Ιππότης της Ασφάλτου","KITT El Auto Increíble","Лицар доріг","Knight Rider Classic","Knight Rider"]', 1784690324549);
