INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-lau-dai-duoi-day-bien', 'Doraemon: Nobita và Lâu Đài Dưới Đáy Biển', 'Doraemon: Nobita and the Castle of the Undersea Devil', 'https://phimimg.com/upload/vod/20250521-1/ed5a8ac38c681d14facfd11187ace425.jpg', 'https://phimimg.com/upload/vod/20250521-1/1bb13f16f3e79bc4382cd9f091d58cb7.jpg', '<p>Nobita và những người bạn của mình đi khám cắm trại tại vùng biển bên dưới Thái Bình Dương. Gian và Suneo lấy chiếc xe đi dưới biển của Doraemon và đi đến Đại Tây Dương để cố gắng tìm một con tàu kho báu. Trên đường đi, họ phát hiện ra rằng khẩu súng bảo vệ môi trường mà Doraemon sử dụng để bảo vệ họ đang cạn kiệt năng lượng khiến cả hai có thể bị nguy hiểm. May mắn thay, họ được giải cứu bởi một số sinh vật kì lạ sống dưới đáy biển.</p>', 'Full', 1, 'hoathinh', 'completed', 22, 1983, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Kazuya Tatekabe","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["海底鬼岩城","doraemon atlantis - El Castillo Del Mal","Doraemon Nobita no Kaitei Kiganjo","Nobita and the Castle of the Undersea Devil","Doraemon: Nobita and the Castle of the Undersea Devil","Doraemon: Nobita''s Monstrous Underwater Castle","ドラえもん のび太の海底鬼岩城","哆啦A夢：大雄的海底鬼岩城","โดราเอมอน ตอน ผจญภัยใต้