INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-lau-dai-duoi-day-bien', 'Doraemon: Nobita và Lâu Đài Dưới Đáy Biển', 'Doraemon: Nobita and the Castle of the Undersea Devil', 'doraemon: nobita và lâu đài dưới đáy biển doraemon: nobita and the castle of the undersea devil nobuyo oyama noriko ohara michiko nomura kaneta kimotsuki kazuya tatekabe 海底鬼岩城 doraemon atlantis - el castillo del mal doraemon nobita no kaitei kiganjo nobita and the castle of the undersea devil doraemon: nobita and the castle of the undersea devil doraemon: nobita''s monstrous underwater castle ドラえもん のび太の海底鬼岩城 哆啦a夢：大雄的海底鬼岩城 โดราเอมอน ตอน ผจญภัยใต้สมุทร 도라에몽: 노비타의 해저귀암성 doraemon nobita dan istana kota hantu dasar lautan doraemon the movie: nobita''s underwater adventure 電影哆啦a夢：大雄在海底鬼岩城 映画ドラえもん のび太の海底鬼岩城', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-va-gan', 'Xa Và Gần', 'Far And Near', 'https://phimimg.com/upload/vod/20250406-1/5c32fb112d3afdfc309361722b668fe8.jpg', 'https://phimimg.com/upload/vod/20250406-1/cc61ac085219416af549dc066235b90b.jpg', '<p>Trước năm 1975, gia đình ông Sĩ và bà Thuận Thành phải chịu cảnh li tán. Trong khi ông Sĩ và Hải - người con trai - tập kết ra Bắc và trở thành cán bộ nòng cốt. Trong miền Nam, bà Thuận Thành cùng những đứa con còn lại bươn chải kiếm sống và trở nên giàu có. Khi đất nước thống nhất, vợ chồng người con trai thứ động viên bà Thành sang Mỹ định cư nhưng bà từ chối, bà muốn ở lại chờ chồng và con lớn trở về. Khi gia đình đoàn tụ cũng là lúc rắc rối nảy sinh vì những tư tưởng trái ngược nhau. Mâu thuẫn đỉnh điểm khi xuất hiện Hà, một cán bộ trẻ nhiệt huyết và năng lực, và cũng là vợ Hải.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 19, 1983, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thùy Vân","avatar":""},{"name":"Bắc Sơn","avatar":""},{"name":"Hà Xuyên","avatar":""},{"name":"Bích Liên","avatar":""},{"name":"Trần Vịnh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["ואן-פאנץ'' מאן","וואן פאנץ'' מן","वन पंच मैन","مرد یک مشتی","Wanpanman","One Punch Man","ONE PUNCH MAN ワンパンマン","OPM","Человек одного удара","ون بنش مان","Anh Hùng OnePunch","Nhất Quyền Nhân","ワンパンマン"]', 1784690324549);
