INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xa-va-gan', 'Xa Và Gần', 'Far And Near', 'xa và gần far and near thùy vân bắc sơn hà xuyên bích liên trần vịnh ואן-פאנץ'' מאן וואן פאנץ'' מן वन पंच मैन مرد یک مشتی wanpanman one punch man one punch man ワンパンマン opm человек одного удара ون بنش مان anh hùng onepunch nhất quyền nhân ワンパンマン', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-dat-va-bien', 'Hòn Đất Và Biển', 'The Island And The Sea', 'https://phimimg.com/upload/vod/20250406-1/e158eef8623bc7d97554b33305f51610.jpg', 'https://phimimg.com/upload/vod/20250406-1/f47b59f8aa59d6548c46f1bd3811893c.jpg', '<p>&quot;Hòn Đất Và Biển&quot; là một bộ phim xuất sắc của điện ảnh Việt Nam, kể về cuộc chiến đấu anh dũng của nhân dân huyện Hòn Đất (tỉnh Kiên Giang) trong kháng chiến chống Mỹ. Bộ phim được chuyển thể từ tiểu thuyết Hòn Đất của nhà văn Anh Đức, dựa trên hình mẫu có thật của nữ anh hùng Phan Thị Ràng, người đã hy sinh để bảo vệ cách mạng. Nhân vật trung tâm của phim là Chị Sứ (do Minh Đức thủ vai), một nữ du kích trẻ tuổi, gan dạ và giàu lòng yêu nước. Khi Mỹ - Ngụy mở cuộc càn quét dữ dội vào Hòn Đất, chị Sứ cùng đồng đội đã kiên cường chiến đấu, bám trụ trên mảnh đất quê hương. Dù bị bắt và tra tấn dã man, chị vẫn giữ vững ý chí, không khai báo bí mật của cách mạng. Bộ phim tái hiện lại những ngày khốc liệt, khi quân địch đàn áp nhưng không thể khuất phục tinh thần bất khuất của những chiến sĩ kiên trung. Câu chuyện kết thúc bằng sự hy sinh bi tráng của chị Sứ, nhưng để lại niềm tin mãnh liệt vào thắng lợi cuối cùng của dân tộc.</p>', 'Full', 1, 'single', 'completed', 18, 1983, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hiệp Định","avatar":""},{"name":"Thúy An","avatar":""},{"name":"Quốc Hùng","avatar":""},{"name":"Lý Huỳnh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["插翅难飞","Vol à Haut Risque","Flight Risk"]', 1784690324549);
