INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dep-trong-nguc-day-troi', 'Người Đẹp Trong Ngục Dây Trói', 'Beauty in Rope Hell', 'https://phimimg.com/upload/vod/20250314-1/50073f14623348f3d5df8672b6d37df7.jpg', 'https://phimimg.com/upload/vod/20250314-1/ad1e3e76c21cf90b586840db608a5ce3.jpg', '<p>Phim phát hành vào năm 1983 và được chỉ đạo bởi đạo diễn Genji Nakamura – cái tên không quá xuất sắc nhưng sở hữu hàng trăm tác phẩm từ khi bắt đầu sự nghiệp từ đầu thập niên 70. Beauty in Rope Hell mặc dù là một tựa phim mang yếu tố bạo dâm nhưng nó lại được xây dựng theo cách nhẹ nhàng đầy thú vị. Trong Ngục Dây Thừng được lấy bối cảnh tại Nhật Bản trong thời gian diễn ra chiến tranh thế giới thứ 2, phim bắt đầu từ một gã đưa thư say mê “như điếu đổ” một tiểu thư đài các nhà nọ, thế nhưng cô gái xinh đẹp này đã có chồng. Không từ bỏ tham vọng được chiếm hữu cô, hắn quyết định bắt cóc cô về và tống vào “nhà tù” mà hắn tạo ra. Từ đó, hắn ta biến cô thành nô lệ tình dục của hắn với các trò bạo dâm và chìm trong hoan lạc. Trò bạo dâm mà hắn yêu thích nhất chính là trói cô lại bằng dây thừng và hiếp dâm cô một cách dã man, trong khi cô không đủ sức để kháng cự cũng không thể trốn thoát để rồi cô dần phục tùng người mà cô từng cực kỳ sợ hãi…</p>', 'Full', 1, 'single', 'completed', 23, 1983, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Miki Takakura","avatar":""},{"name":"Maya Ito","avatar":""},{"name":"Kazuhiro Yamaji","avatar":""},{"name":"Yuri Morita","avatar":""},{"name":"Satsuki Watanabe","avatar":""},{"name":"Masayoshi Nogami","avatar":""},{"name":"Kenji Nuibe","avatar":""},{"name":"Hajime Ishigami","avatar":""},{"name":"Daisuke Iijima","avatar":""},{"name":"Kenji Shimamura","avatar":""},{"name":"Seiroku Miyagawa","avatar":""},{"name":"Shigeo Katō","avatar":""},{"name":"Junpei Natsuki","avatar":""},{"name":"Yutaka Ikejima","avatar":""},{"name":"Reika Kazami","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Dan Oniroku: Bijo Nawa Jigoku","団鬼六 美女縄地獄","Dan Oniroku: My Journey to the Future","Beauty in Rope Hell","團鬼六：美女繩地獄","団鬼六　美女縄地獄"]', 1784690324549);
