INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-chim-hot-trong-bui-man-gai', 'Tiếng Chim Hót Trong Bụi Mận Gai', 'The Thorn Birds', 'https://phimimg.com/upload/vod/20250221-1/147e82d2364de5f012e39039583a6ece.jpg', 'https://phimimg.com/upload/vod/20250221-1/8a766d06c0c88dafc7693d90052a5616.jpg', '<p>Nội dung phim xoay quanh câu chuyện buồn về ba thế hệ nhà Cleary với những mất mát, đau thương, những bi kịch giấu kín của những kiếp người, và trên hết là mối tình say đắm, mãnh liệt nhưng bi thảm của Meggie với cha Ralph. Một tình yêu không thể có được và bị ngăn cấm bởi những định kiến hà khắc của xã hội, một bản tình ca vĩnh cửu, như tiếng hót hay nhất của con chim cất lên chỉ một lần trong đời rồi lao ngực vào chiếc gai nhọn hoắt của bụi mận gai. Phim giành giải Quả cầu vàng năm 1983 với sự diễn xuất tinh tế của Richard Chamberlain (trong vai cha Ralph) và Rachel Ward (trong vai nàng Meggie), đồng thời nhận hai giải Quả cầu vàng cho diễn xuất của nam chính và diễn viên phụ.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 22, 1983, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Richard Chamberlain","avatar":""},{"name":"Rachel Ward","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Bryan Brown","avatar":""},{"name":"Brett Cullen","avatar":""},{"name":"Stephanie Faracy","avatar":""},{"name":"Barry Corbin","avatar":""},{"name":"John de Lancie","avatar":""},{"name":"Barbara Stanwyck","avatar":""},{"name":"Piper Laurie","avatar":""},{"name":"Earl Holliman","avatar":""},{"name":"Philip Anglim","avatar":""},{"name":"John Friedrich","avatar":""},{"name":"Ken Howard","avatar":""},{"name":"Richard Kiley","avatar":""},{"name":"Mare Winningham","avatar":""},{"name":"Cha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["El pájaro canta hasta morir","Птиците умират сами","Pássaros Feridos","Tornfuglene","Ogalinnud","Okalinnut","Les oiseaux se cachent pour mourir","A tövismadarak","Uccelli di rovo","Ptaki Ciernistych Krzewów","Поющие в терновнике","Törnfåglarna","The Thorn Birds"]', 1784690324549);
