INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lucky-luke-anh-em-nha-daltons', 'Lucky Luke: Anh Em Nhà Daltons', 'Lucky Luke: The Daltons On The Loose', 'https://phimimg.com/upload/vod/20240928-1/0fe39f68b64a2b547bc3e2888bd15f84.jpg', 'https://phimimg.com/upload/vod/20240928-1/b2c53e9c657f23077125cd1a202d06ac.jpg', '<p>Hãy cùng cười thả ga với cuộc vượt ngục của băng nhóm The Daltons! Băng nhóm vận dụng tất cả các thủ đoạn để tạo ra cuộc vượt ngục lịch sử như: đường hầm, chất nổ, khinh khí cầu và lợi dụng nước mưa. Tuy nhiên, với những thành viên hết sức khờ khạo và ngốc nghếch, Anh Em Nhà Dalton hết lần này đến lần khác đều thất bại và gây ra những sai lầm hết sức ngớ ngẩn! Điều duy nhất băng nhóm này không biết làm chính là dùng trí.</p>', 'Full', 1, 'hoathinh', 'completed', 24, 1983, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Daniel Ceccaldi","avatar":""},{"name":"Jacques Balutin","avatar":""},{"name":"Roger Carel","avatar":""},{"name":"Jacques Deschamps","avatar":""},{"name":"Michel Elias","avatar":""},{"name":"Bernard Haller","avatar":""},{"name":"Jacques Fabbri","avatar":""},{"name":"Gérard Hernandez","avatar":""},{"name":"Roger Lumont","avatar":""},{"name":"Jacques Legras","avatar":""},{"name":"Jacques Morel","avatar":""},{"name":"Ada Lonati","avatar":""},{"name":"Henri Poirier","avatar":""},{"name":"Pierre Trabaud","avatar":""},{"name":"Jean-Marc Thibault","avatar":""},{"name":"Rosy Varte","avatar":""},{"name":"Henri","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Lucky Luke: Daltons on the Loose","Το κυνήγι των Ντάλτον","Τρελή καταδίωξη","Lucky Luke - Det stora äventyret","Lucky Luke : Les Dalton en cavale"]', 1784690