INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lucky-luke-anh-em-nha-daltons', 'Lucky Luke: Anh Em Nhà Daltons', 'Lucky Luke: The Daltons On The Loose', 'lucky luke: anh em nhà daltons lucky luke: the daltons on the loose daniel ceccaldi jacques balutin roger carel jacques deschamps michel elias bernard haller jacques fabbri gérard hernandez roger lumont jacques legras jacques morel ada lonati henri poirier pierre trabaud jean-marc thibault rosy varte henri lucky luke: daltons on the loose το κυνήγι των ντάλτον τρελή καταδίωξη lucky luke - det stora äventyret lucky luke : les dalton en cavale', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinh-doanh-mao-hiem', 'Kinh Doanh Mạo Hiểm', 'Risky Business', 'https://phimimg.com/upload/vod/20240804-1/02a082f45544b4a11f9baa17c8678b2f.jpg', 'https://phimimg.com/upload/vod/20240804-1/ef25af58e2225e898bc8732f09b89c5a.jpg', '<p>Phim kể về anh chàng Joel Goodson, một công tử ăn chơi trác táng vô cùng sành điệu và sĩ diện. Joel sinh ra trong một gia đình giàu có, với ông bố bà mẹ hết lòng vì con cái. Đến tuổi trưởng thành, Joel luôn có ý tưởng chống đối và xáo trộn mọi thứ. Trong một dịp bố mẹ đi xa, Joel quyết định làm bữa tiệc chia tay với trinh tiết của một gã thanh niên. Và bi kịch đã đến với Joel từ chính lần đập phá này. Sau khi “hết hồn” với cô nàng chuyển giới, Joel lại lao phải một ả yêu nữ. Từng chút đời tư bừa bãi của Joel bắt đầu lộ diện ra ánh sáng với bao rắc rối và sức ép từ mọi người xung quanh, nhưng cũng từ đó Joel đã học được một cách kinh doanh cho lợi nhuận lớn nhưng nhiều rủi ro.</p>', 'Full', 1, 'single', 'completed', 17, 1983, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Cruise","avatar":""},{"name":"Rebecca De Mornay","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Richard Masur","avatar":""},{"name":"Bronson Pinchot","avatar":""},{"name":"Curtis Armstrong","avatar":""},{"name":"Nicholas Pryor","avatar":""},{"name":"Janet Carroll","avatar":""},{"name":"Shera Danese","avatar":""},{"name":"Raphael Sbarge","avatar":""},{"name":"Bruce A. Young","avatar":""},{"name":"Kevin Anderson","avatar":""},{"name":"Sarah Partridge","avatar":""},{"name":"Nathan Davis","avatar":""},{"name":"Scott Harlan","avatar":""},{"name":"Sheila Keenan","avatar":""},{"name":"Lucy","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324549);
