INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kinh-doanh-mao-hiem', 'Kinh Doanh Mạo Hiểm', 'Risky Business', 'kinh doanh mạo hiểm risky business tom cruise rebecca de mornay joe pantoliano richard masur bronson pinchot curtis armstrong nicholas pryor janet carroll shera danese raphael sbarge bruce a. young kevin anderson sarah partridge nathan davis scott harlan sheila keenan lucy ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-dau-song-hung', 'Bắc Đẩu Song Hùng', 'Angels And Devils', 'https://phimimg.com/upload/vod/20240616-1/3fd158f14ca9f86a42fd5ab0d6ec5600.jpg', 'https://phimimg.com/upload/vod/20240616-1/551d0b0776aee14711e0c0e198b84968.jpg', '<p><em>Vu Phàm là một diễn viên đóng thế, tính tình phóng khoáng, nhiều chuyện, là người không có kế hoạch cho tương lai của mình. Ước mơ lớn nhất của Vu Phàm là trở thành một ngôi sao của Hồng Kông. Giang Hạo Văn hoàn toàn trái ngược với Vu Phàm, Văn là người trầm tính, nhút nhát là một nhân viên văn phòng của một công ty tư vấn nhỏ. Văn thường bị ông chủ của mình chèn ép, đánh cắp ý tưởng. Bất mãn, Văn nộp đơn xin từ chức trở thành người thất nghiệp. Hai người tính tình hoàn toàn trái ngược nhau, do hoàn cảnh đưa đẩy cuối cùng trở thành người sống cùng trong một ngôi nhà. Phàm luôn thấy Văn là kẻ nhàm chán và ngược lại Văn cũng khó chịu với lối sống của Phàm. Sau những hiểu lầm, hai người dần dần xích lại nhau, giúp đỡ nhau trong lúc khó khăn và trở thành tri kỷ. Giang Hạo Văn nhờ sự động viên của Vu Phàm đã trở thành nhân viên xã hội, giúp đỡ các thanh niên sa ngã quay trở lại con đường chân chính. Do công việc, một lần Hạo Văn bị dính vào một tổ chức ma túy, vô tình phá vỡ một vụ làm ăn của tổ chức này khiến Phàm và Văn bị sát thủ Tống Ba truy sát. Phàm và Văn đã hiệp lực cùng nhau thoát khỏi tay Ba, phá vỡ tổ chức ma túy để rồi nổi tiếng, trong một đêm cả hai trở thành thần tượng của giới trẻ Hồng Kông.</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 15, 1983, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Châu Nhuận Phát","avatar":""},{"name":"Lương Triều Vỹ","avatar":""},{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Trần Tú Châu","avatar":""},{"name":"Quan Lễ Kiệt","avatar":""},{"name":"Diêu Vỹ","avatar":""},{"name":"Âu Dương Chấn Hoa","avatar":""},{"name":"Đào Đại Vũ","avatar":""},{"name":"Châu Tinh Trì","avatar":""},{"name":"Quách Phong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324549);
