INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-dau-song-hung', 'Bắc Đẩu Song Hùng', 'Angels And Devils', 'bắc đẩu song hùng angels and devils châu nhuận phát lương triều vỹ nhậm đạt hoa trần tú châu quan lễ kiệt diêu vỹ âu dương chấn hoa đào đại vũ châu tinh trì quách phong stephen chow ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-ho-an-thu', 'Long Hổ Ân Thù', 'The Bold Ones', 'https://phimimg.com/upload/vod/20240611-1/0fea58d615d397e97b7eb246a0c66013.jpg', 'https://phimimg.com/upload/vod/20240611-1/118f39d384ab780d79a1b363dfc9ff72.jpg', '<p><em>Jiang Si và Yao Wu ban đầu lớn lên cùng nhau trong một trại trẻ mồ côi, nhưng bị chia cắt do hỏa hoạn ở trại trẻ mồ côi. Yao Wu được chú Jianghu nhận nuôi, sống hết ngày vì tiền và móc túi; trong khi Jiang Si đang đi tuần. Ở Thượng Hải vào những năm 1930, rồng và rắn hỗn hợp, hai gia đình Qiao và Fan đối nghịch nhau, và tranh chấp nảy sinh từ lúc nào không hay. Boss Fan không hài lòng với việc Boss Qiao được bầu chọn bởi tất cả các băng đảng, và yêu cầu Ding Li, người đã nghỉ hưu từ Thiên Tân, đến thương lượng với Tan Sheng, Qianwang của Quảng Đông. Qiao gia đình để lên kế hoạch trả thù. Thế hệ thứ hai của hai gia tộc lớn, con gái của Tianyi là Wannong, nhưng cô ấy thích Fan Baoguang, được sử dụng để đối phó với gia đình Qiao. anh ta chống trả ...</em></p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 15, 1983, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Kent Tong","avatar":""},{"name":"Austin Wai Tin-Chi","avatar":""},{"name":"Stephen Tung Wai","avatar":""},{"name":"Isabella Wong","avatar":""},{"name":"Bonnie Fu","avatar":""},{"name":"Eddie Kwan Lai-Kit","avatar":""},{"name":"Eddie Cheung","avatar":""},{"name":"Lau Nga-Lai","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324549);
