INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh-giua-cac-vi-sao-tap-6-su-quay-tro-lai-cua-jedi', 'Chiến Tranh Giữa Các Vì Sao Tập 6: Sự Quay Trở Lại Của Jedi', 'Star Wars: Episode VI - Return Of The Jedi', 'https://phimimg.com/upload/vod/20240207-1/0909faab82c619d8639f6ceea3cbe809.jpg', 'https://phimimg.com/upload/vod/20240207-1/a65d88ebcdf3a8e4c8fd6f0fc2377358.jpg', '<p>Luke Skywalker chiến đấu với Jabba The Hutt và Darth Vader để cứu những đồng đội của mình trong Liên minh Rebel và Triumph trên Đế chế Thiên hà. Han Solo và Princess Leia xác nhận lại tình yêu của họ, và đội của họ với Chewbacca, Lando Calrissian, Ewoks và Droids C-3po và R2-D2 để hỗ trợ sự gián đoạn của mặt tối, và sự thất bại của Hoàng đế độc ác.</p>', 'Full', 1, 'single', 'completed', 22, 1983, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324549);
