INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-meaning-of-life', 'The Meaning Of Life', 'The Meaning Of Life', 'https://phimimg.com/upload/vod/20240205-1/038282f7d042d37afc9548edc0f3f499.jpg', 'https://phimimg.com/upload/vod/20240205-1/c7f344e842e999007eda61573e2bc662.jpg', '<p>Các câu hỏi của cuộc sống được trả lời trong một loạt các mô tả kỳ quặc, bắt đầu bằng việc một công ty bảo hiểm ngoan cố ở London biến trước mắt chúng ta thành một con tàu cướp biển. Sau đó, có các bác sĩ Y tế Quốc gia cố gắng yêu cầu một lá gan khỏe mạnh từ một người hiến tặng vẫn còn sống. Kẻ háu ăn nhất thế giới đưa nghệ thuật nôn mửa lên một tầm cao mới trước khi hạ gục ngoạn mục.</p>', 'Full', 1, 'single', 'completed', 20, 1983, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Terry Gilliam","avatar":""},{"name":"Graham Chapman","avatar":""},{"name":"John Cleese","avatar":""},{"name":"Eric Idle","avatar":""},{"name":"Terry Jones","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324549);
