INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-tien-xuong-mau', 'Đồng Tiền Xương Máu', 'Bloody Money', 'null', 'https://phimimg.com/upload/vod/20240219-1/ddd5ffd357a53297311e1e85d2e9c3b2.jpg', '<p>Bộ phim Đồng Tiền Xương Máu - Bloody Money xoay quanh Bullet, người con trai đẹp trai của một diễn viên đóng thế kỳ cựu. Bullet và anh trai Chin sống trong một căn hộ nhỏ với người cha nghèo khó. Tuy nhiên lúc bấy giờ, ngành công nghiệp điện ảnh Hồng Kông đang xuống dốc, đặc biệt là đối với những bộ phim kung-fu. Mọi chuyện còn trở nên tồi tệ hơn khi gia đình họ trở thành những người vô gia cư, sống bất hợp pháp tại Hong Kong mà không có giấy tờ nhập cư…</p>', 'Full', 1, 'single', 'completed', 19, 1983, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Châu Nhuận Phát","avatar":""},{"name":"Chu Thiết Hòa","avatar":""},{"name":"Trần Mẫn Nhi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324549);
