INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-giang-sinh', 'Chuyện Giáng Sinh', 'A Christmas Story', 'https://phimimg.com/upload/vod/20240123-1/691bc38cdf57093087b3c9d9ae5dce8b.jpg', 'https://phimimg.com/upload/vod/20240123-1/16f0026bb2ef787d27648caceda68ba5.jpg', '<p>Hãy nghĩ lại xem khi bạn còn nhỏ, có bao giờ bạn đặc biệt thèm muốn một món quà Giáng Sinh nhiều đến mức mà sự ám ảnh của bạn đã trở thành một triệu chứng lâm sàng chưa? Chào mừng các bạn đã đến với kí ức tuổi thơ vui nhộn của Jean Shepherd về một Giáng Sinh đặc biệt…và một món quà đặc biệt nhưng khó có thể có được: khẩu súng Red Ryder BB.Lấy bối cảnh vào cuối thập niên 1940 ở Indiana, từng mảnh đời của những kẻ hay bắt nạt trên sân chơi phải nhận sự trừng phạt giao hoà một cách thật tuyệt vời với những cảnh nói về người cha ngoại đạo của McGavin nguyền rủa hệ thống sưởi ấm lỗi thời.Billingsley vào vai cậu bé mập mạp, và Dillon là người mẹ lí tưởng mà bất cứ ai cũng muốn có. Thêm vào đó, Shepherd dẫn ...</p>', 'Full', 1, 'single', 'completed', 12, 1983, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Melinda Dillon","avatar":""},{"name":"Darren McGavin","avatar":""},{"name":"Peter Billingsley","avatar":""},{"name":"Jean Shepherd","avatar":""},{"name":"Ian Petrella","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324549);
