INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-chan-lac-loi', 'Bước Chân Lạc Lối', 'On The Wrong Track', 'https://phimimg.com/upload/vod/20231219-1/decdf792b2fc223a78632da193a9e7e7.jpg', 'https://phimimg.com/upload/vod/20231219-1/07416654e327527b5f1ddea9ebc0380a.jpg', '<p>Nhìn vào hai anh em, những người có sự nghiệp liều lĩnh với tư cách là thành viên băng đảng tạo ra xung đột với bạn bè, gia đình, cảnh sát, trường học và cuộc sống của họ.</p>', 'Full', 1, 'single', 'completed', 14, 1983, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Andy Lau","avatar":""},{"name":"Yim Chau-Wa","avatar":""},{"name":"Elliot Ngok","avatar":""},{"name":"Prudence Liew Mei-Kwan","avatar":""},{"name":"Winnie Chin Wai-Yee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324549);
