INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tchao-pantin', 'Tchao Pantin', 'So Long, Stooge', 'https://phimimg.com/upload/vod/20231212-1/a1e62bcccbda851a07daf0555ed70bc3.jpg', 'https://phimimg.com/upload/vod/20231212-1/3a84e5d5d577652261ec796765e1e780.jpg', '<p>Ở quận XVIII của Paris, Lambert làm ca đêm ở một trạm xăng, ít nói, sống một mình, uống rượu. Một ngày nọ, một kẻ lừa đảo nhỏ nửa người Do Thái nửa người Ả Rập đang gặp khó khăn nghiêm trọng, đẩy một chiếc xe máy. Tên là Bensoussan, anh ta trú ẩn tại nhà ga giả vờ cần một chiếc bugi. Hai người đàn ông trở thành bạn bè.</p>', 'Full', 1, 'single', 'completed', 12, 1983, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Coluche","avatar":""},{"name":"Agnès Soral","avatar":""},{"name":"Richard Anconina","avatar":""},{"name":"Philippe Léotard","avatar":""},{"name":"Ahmed Ben Smail","avatar":""},{"name":"Albert Dray","avatar":""},{"name":"Annie Kerani","avatar":""},{"name":"Pierrick Mescam","avatar":""},{"name":"Vincent Martin","avatar":""},{"name":"Michel Paul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324549);
