INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-mat-1983', 'Đối Mặt', 'Dirty Harry 4: Sudden Impact', 'https://phimimg.com/upload/vod/20240108-1/8aca3b0955168c118aa12d96ad6a9c5d.jpg', 'https://phimimg.com/upload/vod/20240108-1/33b8b52fadfefc16908c91aa5644c424.jpg', '<p>Một nạn nhân của vụ hiếp dâm muốn được trả thù ở 1 thị trấn nhỏ bên ngoài thành phố San Francisco. Thanh tra Harry, người đang bị đình chỉ vì chọc tức cấp trên của mình được giao cho nhiệm vụ lần này...</p>', 'Full', 1, 'single', 'completed', 11, 1983, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Clint Eastwood","avatar":""},{"name":"Sondra Locke","avatar":""},{"name":"Pat Hingle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324549);
