INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-giai-phach-duong-2', 'Tối Giai Phách Đương 2', 'Aces Go Places II', 'null', 'https://phimimg.com/upload/vod/20231209-1/f771d94bc1d923deee96b4c5b42b7494.jpg', '<p>Sau khi King Kong vượt qua được White Gloves, người anh em sau của Black Gloves được Mafia chỉ định tiếp tục giao dịch và trả thù King Kong. Sau nhiều trận chiến chống lại người máy tiên tiến, King Kong đã chiến thắng nhờ may mắn, nhưng lại rơi vào tay bịp bợm của băng nhóm tội phạm của Niuniu và Youyou, và trở thành kẻ tình nghi. Trên đường bỏ trốn, King Kong đã làm hỏng đám cưới của bạn đời. Đối tác của anh ta là Thám tử Bareheaded đã làm việc cùng với King Kong, nhưng người sau đó lại bị Youyou lừa một lần nữa. Sau đó, họ buộc phải cướp viên kim cương. Trong khi Găng tay đen lại gửi người máy đi. Và King Kong đã cử người theo phe robot. Nó sẽ bị nhốt trong một cuộc chiến rối rắm</p>', 'Full', 1, 'single', 'completed', 11, 1983, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Samuel Hui","avatar":""},{"name":"Sylvia Chang","avatar":""},{"name":"Charlie Cho","avatar":""},{"name":"Tat-wah Cho","avatar":""},{"name":"Tsui Hark","avatar":""},{"name":"Hark Tsui","avatar":""},{"name":"Karl Maka","avatar":""},{"name":"Yasuaki Kurata","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Raymond Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324549);
