INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-nu-tu-thuc', 'Trường Nũ Tư Thục', 'Private School', 'https://phimimg.com/upload/vod/20231125-1/5f23bb77d0a5ee9a19b63f63c091243f.jpg', 'https://phimimg.com/upload/vod/20231125-1/1e4443c844120d0120575c4bc50aed84.jpg', '<p>Học sinh trường tư thục Christine yêu Jim. Nhưng bạn cùng lớp của cô ấy, Jordan, cũng đang tranh giành sự chú ý của Jim và cố gắng chấm dứt mối quan hệ của anh ấy với Christine. Trong khi đó, Bubba, bạn của Jim, bắt tay vào một loạt cuộc phiêu lưu tình dục, bao gồm cả việc hóa trang thành phụ nữ để vào phòng thay đồ nữ. Bất chấp những nỗ lực của Jim và Christine để dành thời gian ở một mình, nhiều âm mưu và trò tai quái khác nhau đã cản trở.</p>', 'Full', 1, 'single', 'completed', 14, 1983, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Phoebe Cates","avatar":""},{"name":"Betsy Russell","avatar":""},{"name":"Matthew Modine","avatar":""},{"name":"Michael Zorek","avatar":""},{"name":"Fran Ryan","avatar":""},{"name":"Kathleen Wilhoite","avatar":""},{"name":"Ray Walston","avatar":""},{"name":"Sylvia Kristel","avatar":""},{"name":"Frank Aletter","avatar":""},{"name":"Jonathan Prince","avatar":""},{"name":"Richard Stahl","avatar":""},{"name":"Julie Payne","avatar":""},{"name":"Frances Bay","avatar":""},{"name":"Burke Byrnes","avatar":""},{"name":"Steve Levitt","avatar":""},{"name":"Lynda Wiesmeier","avatar":""},{"name":"Nadine Van der Vel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324549);
