INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mickey-va-nhung-nguoi-ban-giang-sinh', 'Mickey Và Những Người Bạn Giáng Sinh', 'Mickey''s Christmas Carol', 'https://phimimg.com/upload/vod/20231108-1/f0c8dae259620b60b354e1b25a7ce581.jpg', 'https://phimimg.com/upload/vod/20231108-1/6038857bad657e5dbba592d09235e3f5.jpg', '<p>Ebenezer Scrooge quá tham lam khi hiểu rằng Giáng sinh là thời điểm dành cho lòng tốt và sự rộng lượng. Nhưng với sự hướng dẫn của một số người bạn mới quen, Scrooge học cách đón nhận tinh thần của mùa lễ hội. Kể lại câu chuyện kinh điển của Dickens với các nhân vật kinh điển của Disney.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 1983, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Alan Young","avatar":""},{"name":"Wayne Allwine","avatar":""},{"name":"Clarence Nash","avatar":""},{"name":"Hal Smith","avatar":""},{"name":"Will Ryan","avatar":""},{"name":"Patricia Parris","avatar":""},{"name":"Dick Billingsley","avatar":""},{"name":"Eddie Carroll","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hoạt Hình","slug":"hoat-hinh","id":"d9983d88d8929b1d9f767884e2999e27"}]', '[]', 1784690324549);
