INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-xe-tai-hoa', 'Chiếc Xe Tai Họa', 'Christine', 'https://phimimg.com/upload/vod/20231101-1/3d43accd6cea0db3332551090f312c16.jpg', 'https://phimimg.com/upload/vod/20231101-1/2ff274a7afd68d2e75711d8e802d131f.jpg', '<p>Cô sinh viên lập dị Arnie Cunningham phải lòng Christine, một chiếc Plymouth Fury đời 1958 rỉ sét, và bị ám ảnh bởi việc khôi phục lại chiếc ô tô cổ điển về thời huy hoàng trước đây của cô. Khi chiếc xe thay đổi, Arnie cũng vậy, sự tự tin mới bắt đầu chuyển sang kiêu ngạo sau tay lái vì vẻ đẹp kỳ lạ của mình. Leigh, bạn gái của Arnie và người bạn thân nhất Dennis tìm đến anh ta, chỉ để gặp một Fury độc nhất vô nhị.</p>', 'Full', 1, 'single', 'completed', 15, 1983, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Keith Gordon","avatar":""},{"name":"John Stockwell","avatar":""},{"name":"Alexandra Paul","avatar":""},{"name":"Robert Prosky","avatar":""},{"name":"Harry Dean Stanton","avatar":""},{"name":"Christine Belford","avatar":""},{"name":"Roberts Blossom","avatar":""},{"name":"William Ostrander","avatar":""},{"name":"David Spielberg","avatar":""},{"name":"Malcolm Danare","avatar":""},{"name":"Steven Tash","avatar":""},{"name":"Stuart Charno","avatar":""},{"name":"Kelly Preston","avatar":""},{"name":"Marc Poppel","avatar":""},{"name":"Robert Darnell","avatar":""},{"name":"Douglas Warhit","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324549);
