INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-luc-den-toi', 'Thế Lực Đen Tối', 'Videodrome', 'https://phimimg.com/upload/vod/20231031-1/2cc0ad19ac22f7a4d644832bd58f41a6.jpg', 'https://phimimg.com/upload/vod/20231031-1/9c93404e36f86189e7cb7e0aeef67667.jpg', '<p>Là chủ tịch của một kênh truyền hình rác rưởi, Max Renn đang khao khát chương trình mới để thu hút người xem. Khi tình cờ xem &quot;Videodrome&quot;, một chương trình truyền hình chuyên về tra tấn và trừng phạt vô cớ, Max nhận thấy tiềm năng thành công và phát sóng chương trình trên kênh của mình. Tuy nhiên, sau khi bạn gái của anh ấy thử giọng cho chương trình và không bao giờ quay lại, Max điều tra sự thật đằng sau Videodrome và phát hiện ra rằng hình ảnh bạo lực có thể không giả như anh ấy nghĩ.</p>', 'Full', 1, 'single', 'completed', 21, 1983, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"James Woods","avatar":""},{"name":"Sonja Smits","avatar":""},{"name":"Debbie Harry","avatar":""},{"name":"Peter Dvorsky","avatar":""},{"name":"Leslie Carlson","avatar":""},{"name":"Jack Creley","avatar":""},{"name":"Lynne Gorman","avatar":""},{"name":"Julie Khaner","avatar":""},{"name":"Reiner Schwarz","avatar":""},{"name":"David Bolt","avatar":""},{"name":"Lally Cadeau","avatar":""},{"name":"Henry Gomez","avatar":""},{"name":"Harvey Chao","avatar":""},{"name":"David Tsubouchi","avatar":""},{"name":"Kay Hawtrey","avatar":""},{"name":"Sam Malkin","avatar":""},{"name":"Bob Church","avatar":""},{"name":"Jayne Eastwood","avatar":""},{"name":"Franc","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug