INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-ca-map-3d', 'Hàm Cá Mập 3D', 'Jaws 3-D', 'https://phimimg.com/upload/vod/20231030-1/57f3e82f500b9e4db001e976a2451829.jpg', 'https://phimimg.com/upload/vod/20231030-1/fdbe0d40689fe4d99897bd0dd0a12600.jpg', '<p>Bộ phim thứ ba trong loạt phim này kể về một nhóm các nhà sinh vật học biển cố gắng bắt một con cá mập trắng lớn còn nhỏ đã lang thang vào Công viên Thế giới Biển của Florida. Tuy nhiên, sau đó người ta phát hiện ra rằng mẹ cá mập dài 35 feet cũng là khách của Sea World. Tiếp theo là cảnh con cá mập tàn phá du khách trong công viên.</p>', 'Full', 1, 'single', 'completed', 16, 1983, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dennis Quaid","avatar":""},{"name":"Bess Armstrong","avatar":""},{"name":"Simon MacCorkindale","avatar":""},{"name":"Louis Gossett Jr.","avatar":""},{"name":"John Putch","avatar":""},{"name":"Lea Thompson","avatar":""},{"name":"P.H. Moriarty","avatar":""},{"name":"Dan Blasko","avatar":""},{"name":"Liz Morris","avatar":""},{"name":"Lisa Maurer","avatar":""},{"name":"Harry Grant","avatar":""},{"name":"Andy Hansen","avatar":""},{"name":"P.T. Horn","avatar":""},{"name":"John Perry Edson","avatar":""},{"name":"Kaye Stevens","avatar":""},{"name":"Rich Valliere","avatar":""},{"name":"Alonzo Ward","avatar":""},{"name":"Cathy Cerv","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324549);
