INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-wars-su-tro-lai-cua-jedi', 'Star Wars: Sự Trở Lại Của Jedi', 'Return of the Jedi', 'https://phimimg.com/upload/vod/20231025-1/4782833ccb89daf83fc3a634a955b40a.jpg', 'https://phimimg.com/upload/vod/20231025-1/444991a0b956562b8c15cf69ce26fdf5.jpg', '<p>Câu chuyện với trận đụng độ giữa Luke và kẻ thù không đội trời chung Darth Vader. Với vũ khí hủy diệt Death Star được khôi phục lại, đạo quân khát máu của Đế chế trực chỉ hành tinh của nữ hoàng Leia. Luke nay đã trở thành một Jedi thực thụ được sự giúp đỡ của đạo quân Ewoks gồm những sinh vật kỳ lạ sẵn sàng đương đầu thử thách...</p>', 'Full', 1, 'single', 'completed', 17, 1983, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Hamill","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Carrie Fisher","avatar":""},{"name":"Billy Dee Williams","avatar":""},{"name":"Anthony Daniels","avatar":""},{"name":"Peter Mayhew","avatar":""},{"name":"Sebastian Shaw","avatar":""},{"name":"Ian McDiarmid","avatar":""},{"name":"Frank Oz","avatar":""},{"name":"James Earl Jones","avatar":""},{"name":"David Prowse","avatar":""},{"name":"Alec Guinness","avatar":""},{"name":"Kenny Baker","avatar":""},{"name":"Michael Pennington","avatar":""},{"name":"Kenneth Colley","avatar":""},{"name":"Michael Carter","avatar":""},{"name":"Denis La","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324549);
