INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chia-khoa-tinh-yeu', 'Chìa Khóa Tình Yêu', 'La chiave', 'https://phimimg.com/upload/vod/20231019-1/7367af56428df0f35d0fded5a9ebbab4.jpg', 'https://phimimg.com/upload/vod/20231019-1/033f92d197f95f102d83140b326fd219.jpg', '<p>Chủ nghĩa phát xít Ý bắt đầu trỗi dậy một cách mạnh mẽ ở Venice trong những năm 1940, Giáo sư Nino Rolfe và người vợ trẻ hơn nhiều tuổi của ông, một cô gái người Ý sang trọng và xa hoa tên Teresa, cảm thấy sự buồn bã sau hai mươi năm chung sống, chứng kiến sự nồng nhiệt của 2 người héo mòn và niềm đam mê cũng cạn kiệt. Tất nhiên, tất cả những gì còn lại bây giờ là để trí tưởng tượng của anh ta chạy lung tung và thổ lộ những suy nghĩ sâu sắc và táo bạo của mình vào cuốn nhật ký công phu của mình, với hy vọng rằng Teresa sẽ sớm tìm thấy nó và đọc nó.</p>', 'Full', 1, 'single', 'completed', 21, 1983, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Stefania Sandrelli","avatar":""},{"name":"Frank Finlay","avatar":""},{"name":"Franco Branciaroli","avatar":""},{"name":"Barbara Cupisti","avatar":""},{"name":"Armando Marra","avatar":""},{"name":"Maria Grazia Bon","avatar":""},{"name":"Gino Cavalieri","avatar":""},{"name":"Piero Bortoluzzi","avatar":""},{"name":"Irma Veithen","avatar":""},{"name":"Eolo Capritti","avatar":""},{"name":"Maria Pia Colonnello","avatar":""},{"name":"Milly Corinaldi","avatar":""},{"name":"Edgardo Fugagnoli","avatar":""},{"name":"Luciano Gasper","avatar":""},{"name":"Giovanni Miche","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324549);
