INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-trum-mat-seo', 'Ông Trùm Mặt Sẹo', 'Scarface', 'https://phimimg.com/upload/vod/20231019-1/9c4398f321e048aff298e70217a7e972.jpg', 'https://phimimg.com/upload/vod/20231019-1/0ac94b2e7a1ac03776eb2512aba50799.jpg', '<p>125 nghìn người tị nạn ở Cuba được nhập cảnh Mỹ và đoàn tụ với người thân. Trong đám đông đó, Tony Montana lại nuôi tham vọng khác. Từ một gã tay chân cho băng đảng và bắt đầu dấn thân vào con đường tăm tối, Tony ngày càng bị cơn khát quyền lực dằn vặt, ngay cả khi đã trở thành ông trùm.</p>', 'Full', 1, 'single', 'completed', 17, 1983, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Al Pacino","avatar":""},{"name":"Steven Bauer","avatar":""},{"name":"Michelle Pfeiffer","avatar":""},{"name":"Mary Elizabeth Mastrantonio","avatar":""},{"name":"Robert Loggia","avatar":""},{"name":"Miriam Colon","avatar":""},{"name":"F. Murray Abraham","avatar":""},{"name":"Paul Shenar","avatar":""},{"name":"Harris Yulin","avatar":""},{"name":"Ángel Salazar","avatar":""},{"name":"Arnaldo Santana","avatar":""},{"name":"Pepe Serna","avatar":""},{"name":"Michael P. Moran","avatar":""},{"name":"Al Israel","avatar":""},{"name":"Dennis Holahan","avatar":""},{"name":"Mark Margolis","avatar":""},{"name":"Mic","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324549);
