INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-bao-gio-noi-khong-nua', 'Đừng Bao Giờ Nói Không Nữa', 'Never Say Never Again', 'https://phimimg.com/upload/vod/20231016-1/8c16f85e341abbaa70e89d1bf2c33250.jpg', 'https://phimimg.com/upload/vod/20231016-1/a12ae7961e62eea5affd3babd838a1dc.jpg', '<p>James Bond trở lại với tư cách là điệp viên 007 một lần nữa để chiến đấu với tổ chức độc ác SPECTRE. Bond phải đánh bại Largo, kẻ đã đánh cắp hai đầu đạn nguyên tử để tống tiền. Nhưng Bond có một đồng minh là bạn gái của Largo, Domino liễu rũ, người đã yêu Bond và tìm cách trả thù. Đây là lần cuối cùng Sean Connery với tư cách là Điệp viên 007.</p>', 'Full', 1, 'single', 'completed', 19, 1983, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Sean Connery","avatar":""},{"name":"Klaus Maria Brandauer","avatar":""},{"name":"Max von Sydow","avatar":""},{"name":"Barbara Carrera","avatar":""},{"name":"Kim Basinger","avatar":""},{"name":"Bernie Casey","avatar":""},{"name":"Alec McCowen","avatar":""},{"name":"Edward Fox","avatar":""},{"name":"Pamela Salem","avatar":""},{"name":"Rowan Atkinson","avatar":""},{"name":"Valerie Leon","avatar":""},{"name":"Milos Kirek","avatar":""},{"name":"Pat Roach","avatar":""},{"name":"Anthony Sharp","avatar":""},{"name":"Prunella Gee","avatar":""},{"name":"Gavan O''Herlihy","avatar":""},{"name":"Ronald Pickup","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324549);
