INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-voi-bach-tuoc', 'Điệp Viên 007: Vòi Bạch Tuộc', 'Octopussy', 'https://phimimg.com/upload/vod/20231015-1/e2213010c37235646db711aadf366965.jpg', 'https://phimimg.com/upload/vod/20231015-1/ae7fc3964b532ecc1625f318b000ad2f.jpg', '<p>Khi một điệp viên bị phát hiện đã chết khi đang giữ một quả trứng Faberge, người Anh đã nghi ngờ và cử James Bond đến để điều tra. 007 phát hiện ra mối liên quan giữa quả trứng vô giá, tổ chức ăn trộm tinh vi cùng tấm bản đồ của tên chỉ huy quân Soviet nổi loạn nhằm phát động chiến tranh thế giới thứ 3 .</p>', 'Full', 1, 'single', 'completed', 18, 1983, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Roger Moore","avatar":""},{"name":"Maud Adams","avatar":""},{"name":"Louis Jourdan","avatar":""},{"name":"Kristina Wayborn","avatar":""},{"name":"Kabir Bedi","avatar":""},{"name":"Steven Berkoff","avatar":""},{"name":"David Meyer","avatar":""},{"name":"Tony Meyer","avatar":""},{"name":"Desmond Llewelyn","avatar":""},{"name":"Robert Brown","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324549);
