INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-hung-truy-quy', 'Thất Hùng Truy Quỷ', 'The Trail', 'https://phimimg.com/upload/vod/20231010-1/004e1cc1bf97aa981f5665d279124040.jpg', 'https://phimimg.com/upload/vod/20231010-1/53054ef3484156f4d861ceecf4141a46.jpg', '<p>Một nhóm buôn lậu thuốc phiện, cải trang thành các Đạo sĩ vận chuyển xác chết, được thuê để vận chuyển một xác chết thực sự đến nơi an nghỉ cuối cùng.</p>', 'Full', 1, 'single', 'completed', 20, 1983, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Ricky Hui","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Tanny Tien-Ni","avatar":""},{"name":"Tsui Siu-Ling","avatar":""},{"name":"Miao Tien","avatar":""},{"name":"Paul Chung Fat","avatar":""},{"name":"Anthony Chan Yau","avatar":""},{"name":"Mars","avatar":""},{"name":"Addy Sung Gam-Loi","avatar":""},{"name":"Fung Fung","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324549);
