INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gian-diep-da-ly-huong', 'Gián điệp Dạ Lý Hương', 'All The Wrong Spies', 'https://phimimg.com/upload/vod/20231006-1/59b2af13ffb7b544f04c58f39a3929b9.jpg', 'https://phimimg.com/upload/vod/20231006-1/b97009033191965d66c83926b6138515.jpg', '<p>Trước Thế chiến thứ hai, các điệp viên từ khắp nơi trên thế giới tập trung tại Hồng Kông. Điều tra viên tư nhân Yo được Tianzi số 1, điệp viên hoạt động ở Trung Quốc ủy nhiệm giao bản thiết kế vũ khí bị đánh cắp từ Đức cho các đặc vụ tình báo Mỹ, trong khi Đức Quốc xã truy đuổi đến Hồng Kông để gây rắc rối, khiến bản thiết kế rơi vào tay kẻ phản bội. giám đốc cảnh sát. Yo và chánh thanh tra tình cờ gặp Tianzi No.1 sau khi họ lẻn vào nhà của giám đốc và đánh nhau trong bóng tối mà không nhận ra nhau. Sau này, khi Yo hóa trang thành một điệp viên Nhật Bản để nhận bản in xanh, anh phát hiện ra rằng Tianzi No.1 chính là vợ sắp cưới của giám đốc.<br/></p>', 'Full', 1, 'single', 'completed', 21, 1983, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"George Lam Chi-Cheung","avatar":""},{"name":"Teddy Robin","avatar":""},{"name":"Brigitte Lin","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Shing Fui-On","avatar":""},{"name":"Tsui Hark","avatar":""},{"name":"Karl Maka","avatar":""},{"name":"Dean Shek","avatar":""},{"name":"Paul Chun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324549);
