INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bingo-bongo', 'Bingo Bongo', 'Bingo Bongo', 'https://phimimg.com/upload/vod/20260505-1/a6241862762657d3afab9cb1f4c67929.jpg', 'https://phimimg.com/upload/vod/20260505-1/ba252e92843ae995f570ca88925ed297.jpg', '<p>Người vượn, được tìm thấy ở đâu đó trong rừng rậm Congo, được chuyển đến Milan và đặt tên là Bingo Bongo. Người duy nhất tin vào những phẩm chất con người của anh ta là Laura, một nhà nhân chủng học, vì vậy tình cảm giữa họ dần nảy nở thành tình yêu.</p>', 'Trailer', 1, 'single', 'ongoing', 30, 1982, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Adriano Celentano","avatar":""},{"name":"Carole Bouquet","avatar":""},{"name":"Felice Andreasi","avatar":""},{"name":"Enzo Robutti","avatar":""},{"name":"Walter D''Amore","avatar":""},{"name":"Roberto Marelli","avatar":""},{"name":"Guido Spadea","avatar":""},{"name":"Alfio Patané","avatar":""},{"name":"Elizabeth Cobben","avatar":""},{"name":"Maurizio Tabani","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Бинго Бонго","Bingo Bongo"]', 1784690324549);
