INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cuoc-truy-hoan-khong-ke-xiet-cua-emmanuelle', 'Những Cuộc Truy Hoan Không Kể Xiết Của Emmanuelle', 'The Inconfessable Orgies of Emmanuelle', 'https://phimimg.com/upload/vod/20260430-1/5a81ae05dd975875b8d6ba63966a3454.jpg', 'https://phimimg.com/upload/vod/20260430-1/6449dd4bd874f4c93ecce57462818e94.jpg', '<p>Emmanuelle gần đây đã đoàn tụ với chồng, nhưng tại bữa tiệc tiếp theo, cô say xỉn và cởi trần cho bạn bè của anh ta. Anh trở về với người yêu. Sau đó, một Emmanuelle tỉnh táo cố gắng chuộc lỗi, nhưng chồng cô từ chối tha thứ. Cô đi du lịch để gặp anh ta, bị cưỡng hiếp trên đường bởi hai tên tội phạm, và bước vào một cuộc sống tình dục xấu xa để quên anh ta.</p>', 'Full', 1, 'single', 'completed', 58, 1982, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Muriel Montossé","avatar":""},{"name":"Antonio Mayans","avatar":""},{"name":"Asunción Calero","avatar":""},{"name":"Carmen Carrión","avatar":""},{"name":"Antonio Rebollo","avatar":""},{"name":"Ángel Ordiales","avatar":""},{"name":"Juan Soler","avatar":""},{"name":"Flavia Hervás","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Emmanuelle Exposed","Emmanuelle Forever","The Inconfessable Orgies of Emmanuelle","Las orgías inconfesables de Emmanuelle"]', 1784690324549);
