INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-tham-hiem-vung-dat-moi', 'Doraemon: Nobita Thám Hiểm Vùng Đất Mới', 'Doraemon: Nobita and the Haunts of Evil', 'https://phimimg.com/upload/vod/20250521-1/13ded44347927c7001f7d6575eb5189e.jpg', 'https://phimimg.com/upload/vod/20250521-1/f4ddf3421a1a5c450a6f28945670ac5f.jpg', '<p>Không gì là không thể đối với chiếc túi thần kỳ của Doraemon, nhất là khi sử dụng những bảo bối để thực hiện những chuyến phiêu lưu kỳ thú nhất. Có nơi nào mà con người chưa từng khám phá không? Cánh cửa thần kỳ dẫn những người bạn của chúng ta đến trung tâm Châu Phi, gần ngay khu rừng sương mù, một khu rừng bị bao phủ bởi lớp sương mù dày đặc ngăn cản các vệ tinh chụp ảnh. Nobita và những người bạn của mình tin rằng đây là có rất nhiều điều mới mẻ để khám phá</p>', 'Full', 1, 'hoathinh', 'completed', 16, 1982, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Sumiko Shirakawa","avatar":""},{"name":"Kazuyo Aoki","avatar":""},{"name":"Mari Shimizu","avatar":""},{"name":"Kazuko Sugiyama","avatar":""},{"name":"Masahiko Murase","avatar":""},{"name":"Yoko Kuri","avatar":""},{"name":"Sachiko Chijimatsu","avatar":""},{"name":"Masayuki Katô","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144e