INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-tham-hiem-vung-dat-moi', 'Doraemon: Nobita Thám Hiểm Vùng Đất Mới', 'Doraemon: Nobita and the Haunts of Evil', 'doraemon: nobita thám hiểm vùng đất mới doraemon: nobita and the haunts of evil nobuyo oyama noriko ohara michiko nomura kazuya tatekabe kaneta kimotsuki sumiko shirakawa kazuyo aoki mari shimizu kazuko sugiyama masahiko murase yoko kuri sachiko chijimatsu masayuki katô nobita and the haunts of evil doraemon nobita no daimakyo 哆啦a夢：大雄的大魔境 โดราเอมอน ตอน ตะลุยแดนมหัศจรรย์ 도라에몽: 진구의 대마경 도라에몽: 노비타의 대마경 doraemon 1982 doraemon: nobita dan hantu kejahatan 大雄的大魔境 電影哆啦a夢：大雄在大魔境 映画ドラえもん のび太の大魔境', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-tro-choi-ao-giac-1982', 'Tron: Trò Chơi Ảo Giác', 'Tron', 'https://phimimg.com/upload/vod/20250412-1/cd2a919bab3dc183457c903ac419bdb1.jpg', 'https://phimimg.com/upload/vod/20250412-1/dd67060d1e18501df4f34ab3d7cfb51a.jpg', '<p>Khi Flynn, một nhà sáng tạo trò chơi điện tử thiên tài, hack vào hệ thống chính của công ty cũ, anh bất ngờ bị dịch chuyển vào một thế giới số hóa kỳ diệu… và trở thành một phần trong chính trò chơi mà mình đang thiết kế. Trong hành trình băng qua không gian mạng, Flynn phải đối đầu với Chương trình Kiểm soát Chính (Master Control Program) — một hệ thống độc tài đầy toan tính. Đồng hành cùng anh là Tron, một chương trình bảo mật được tạo ra nhằm khôi phục sự cân bằng cho thế giới kỹ thuật số.</p>', 'Full', 1, 'single', 'completed', 17, 1982, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jeff Bridges","avatar":""},{"name":"Bruce Boxleitner","avatar":""},{"name":"David Warner","avatar":""},{"name":"Cindy Morgan","avatar":""},{"name":"Barnard Hughes","avatar":""},{"name":"Dan Shor","avatar":""},{"name":"Peter Jurasik","avatar":""},{"name":"Tony Stephano","avatar":""},{"name":"Craig Chudy","avatar":""},{"name":"Vince Deadrick Jr.","avatar":""},{"name":"Sam Schatz","avatar":""},{"name":"Michael Dudikoff","avatar":""},{"name":"Jackson Bostwick","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["TRON: The Original Classic","컴퓨터 전사 트론","컴퓨터전사 트론","Tron: Uma Odisseia Eletrônica","创","Tron"]', 1784690324549);
