INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-nho-tren-thao-nguyen-phan-9', 'Ngôi Nhà Nhỏ Trên Thảo Nguyên (Phần 9)', 'Little House On The Prairie (Season 9)', 'https://phimimg.com/upload/vod/20240924-1/12de91185700e9559dbb204b3ac3ebca.jpg', 'https://phimimg.com/upload/vod/20240924-1/650c8fc3afc7ca218ed252d85b8aac35.jpg', '<p>Bộ phim này được sản xuất vào thập kỷ 1970 và thập kỷ 1980 (hơn 200 tập) dựa trên tác phẩm của Laura Wilder, kể về cuộc sống của gia đình Ingalls và nhiều gia đình khác trong quá trình khai hoang thị trấn Walnut Grove, Minnesota. Bộ phim đề cao tình cảm vợ chồng, cha mẹ và con cái, tình làng nghĩa xóm, tình bằng hữu luôn trong sáng, đậm đà và chan hòa mặc cho cuộc sống còn nhiều khó khăn gian khổ.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 17, 1982, 'Thuyết Minh', 'HD', 'Âu Mỹ', 0, '[{"name":"Melissa Gilbert","avatar":""},{"name":"Dean Butler","avatar":""},{"name":"Karen Grassle","avatar":""},{"name":"Katherine MacGregor","avatar":""},{"name":"Melissa Sue Anderson","avatar":""},{"name":"Richard Bull","avatar":""},{"name":"Victor French","avatar":""},{"name":"Jonathan Gilbert","avatar":""},{"name":"Allison Balson","avatar":""},{"name":"Lindsay Kennedy","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324549);
