INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-vu-ca-dem', 'Dịch Vụ Ca Đêm', 'Night Shift', 'https://phimimg.com/upload/vod/20240913-1/491c75bf93239b6282af5c6e7c1ee28a.jpg', 'https://phimimg.com/upload/vod/20240913-1/76cdec0f0e6f28bce08a673a89cda516.jpg', '<p>“Night Shift” là một bộ phim hài của Mỹ ra mắt năm 1982, do Ron Howard đạo diễn. Phim kể về Chuck Lumley (Henry Winkler), một nhân viên nhà xác làm ca đêm, và Bill Blazejowski (Michael Keaton), đồng nghiệp mới của anh ta. Cả hai quyết định mở một dịch vụ mại dâm ngay tại nhà xác sau khi gặp Belinda (Shelley Long), một cô gái mại dâm hàng xóm</p>', 'Full', 1, 'single', 'completed', 13, 1982, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Henry Winkler","avatar":""},{"name":"Michael Keaton","avatar":""},{"name":"Shelley Long","avatar":""},{"name":"Gina Hecht","avatar":""},{"name":"Pat Corley","avatar":""},{"name":"Bobby Di Cicco","avatar":""},{"name":"Nita Talbot","avatar":""},{"name":"Basil Hoffman","avatar":""},{"name":"Tim Rossovich","avatar":""},{"name":"Clint Howard","avatar":""},{"name":"Joe Spinell","avatar":""},{"name":"Cheryl Carter","avatar":""},{"name":"Becky Gonzalez","avatar":""},{"name":"Corki Grazer","avatar":""},{"name":"Jaid Barrymore","avatar":""},{"name":"Ava Lazar","avatar":""},{"name":"Ola Ray","avatar":""},{"name":"Cassandra Gava","avatar":""},{"name":"Ash","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324550);
