INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tu-amazon', 'Trại Tù Amazon', 'Amazon Jail', 'https://phimimg.com/upload/vod/20240228-1/a16c157616fcfde31376dacf583ebf33.jpg', 'https://phimimg.com/upload/vod/20240228-1/b8913b59443e43163ac84d1976b5638f.jpg', '<p>Những phụ nữ trẻ ở Amazon bị bắt cóc bởi một nhóm tôn thờ ma quỷ, những kẻ định bán họ làm nô lệ tình dục. Một số phụ nữ trốn thoát nhưng bị những kẻ bắt giữ họ truy đuổi vào rừng. Những người phụ nữ phải liên kết với nhau để lật ngược thế cờ những kẻ bắt cóc họ.</p>', 'Full', 1, 'single', 'completed', 22, 1982, 'Vietsub', 'HD', 'Brazil', 0, '[{"name":"Elizabeth Hartmann","avatar":""},{"name":"Maurício do Valle","avatar":""},{"name":"Sandra Graffi","avatar":""},{"name":"Lígia de Paula","avatar":""},{"name":"Elys Cardoso","avatar":""},{"name":"Shirley Benny","avatar":""},{"name":"Márcia Fraga","avatar":""},{"name":"Regina Lopes","avatar":""},{"name":"Kátia Spencer","avatar":""},{"name":"Fátima Nunes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324550);
