INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-truyen-hinh', 'Vua Truyền Hình', 'The King Of Comedy', 'https://phimimg.com/upload/vod/20240228-1/94d8e2f1b446fa59241b538457d19047.jpg', 'https://phimimg.com/upload/vod/20240228-1/4fcfe437944eee86d676dc952d599c7b.jpg', '<p>Diễn viên hài đầy tham vọng Rupert Pupkin cố gắng đạt được thành công trong giới giải trí bằng cách theo dõi thần tượng của mình, một người dẫn chương trình trò chuyện đêm khuya luôn khao khát sự riêng tư của riêng mình.</p>', 'Full', 1, 'single', 'completed', 18, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Jerry Lewis","avatar":""},{"name":"Diahnne Abbott","avatar":""},{"name":"Sandra Bernhard","avatar":""},{"name":"Shelley Hack","avatar":""},{"name":"Kim Chan","avatar":""},{"name":"Ed Herlihy","avatar":""},{"name":"Lou Brown","avatar":""},{"name":"Margo Winkler","avatar":""},{"name":"Ralph Monaco","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
