INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-pham-nguoi-may', 'Tội Phạm Người Máy', 'Blade Runner', 'https://phimimg.com/upload/vod/20240227-1/4b1f05f56fc83c34ec772f64747c20be.jpg', 'https://phimimg.com/upload/vod/20240227-1/16e784997ef6bf57b38a2d28aeef4d4d.jpg', '<p>Nhân vật chính là cảnh sát đã về hưu Rick Deckard sống ở Los Angeles vào năm 2019. Khi đó, thành phố này đã trở thành một trong những nơi tối tăm nhất trên Trái Đất, với quảng cáo cỡ lớn khắp nơi, ô nhiễm trầm trọng, những cỗ máy bay lượn đầy trời, người máy gần như giống hệt con người được chế tạo ra để phục vụ cho công cuộc khai thác, xâm lấn các hành tinh khác của con người. Khi còn làm việc, Rick Deckard săn lùng và tiêu diệt những tên người máy nổi loạn chống lại loài người. Được sếp cũ của mình triệu tập, Rick bị giao một nhiệm vụ mới: phải tìm và diệt một nhóm 4 tên người máy đã trốn thoát trở về Trái Đất và đang cố gắng ẩn náu đâu đó ở Los Angeles. Nhiệm vụ đặt lên vai, Rick không còn cách nào khác là phải đối mặt với vô số nguy hiểm đến từ những con người nhân tạo...</p>', 'Full', 1, 'single', 'completed', 16, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Rutger Hauer","avatar":""},{"name":"Sean Young","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324550);
