INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fanny-va-alexander', 'Fanny Và Alexander', 'Fanny And Alexander', 'https://phimimg.com/upload/vod/20240207-1/3b956b0bca78d9ec59a768b9029d04fb.jpg', 'https://phimimg.com/upload/vod/20240207-1/7767f86c6d99f58f2297bc959a3380da.jpg', '<p>Fanny and Alexander nhận được sự đón chào nhiệt liệt của cả giới phê bình điện ảnh lẫn công chúng, và mang lại cho Ingmar Bergman bốn giải Oscar- một thành tích hiếm gặp với một bộ phim không nói tiếng Anh, trong đó có giải hình ảnh đẹp nhất cho tay máy Sven Nykvist.</p>', 'Full', 1, 'single', 'completed', 19, 1982, 'Vietsub', 'HD', 'Thụy Điển', 0, '[{"name":"Bertil Guve","avatar":""},{"name":"Pernilla Allwin","avatar":""},{"name":"Allan Edwall","avatar":""},{"name":"Ewa Fröling","avatar":""},{"name":"Erland Josephson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324550);
