INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('fanny-va-alexander', 'Fanny Và Alexander', 'Fanny And Alexander', 'fanny và alexander fanny and alexander bertil guve pernilla allwin allan edwall ewa fröling erland josephson ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bao', 'Người Báo', 'Cat People', 'https://phimimg.com/upload/vod/20240128-1/cc3f9f8d08fb9e771547e73b9864bde9.jpg', 'https://phimimg.com/upload/vod/20240128-1/e704d62cc7cd3334fa822293c43bf307.jpg', '<p>Sau nhiều năm xa cách, Irena và anh trai bộ trưởng của cô, Paul, đoàn tụ ở New Orleans trong câu chuyện khiêu dâm về siêu nhiên này. Khi các nhà động vật học bắt được một con báo hoang dã, Irena bị thu hút bởi con mèo -- và người phụ trách vườn thú bị thu hút bởi cô ấy. Chẳng bao lâu nữa, anh trai của Irena sẽ phải tiết lộ bí mật gia đình: rằng khi bị kích thích tình dục, họ sẽ biến thành những con mèo rừng săn mồi.</p>', 'Full', 1, 'single', 'completed', 19, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Nastassja Kinski","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"John Heard","avatar":""},{"name":"Ruby Dee","avatar":""},{"name":"Ed Begley Jr.","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324550);
