INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-bao', 'Người Báo', 'Cat People', 'người báo cat people nastassja kinski malcolm mcdowell john heard ruby dee ed begley jr. ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-giap-ky-mon', 'Độn Giáp Kỳ Môn', 'Miracle Fighters', 'null', 'https://phimimg.com/upload/vod/20240128-1/7da25920a0e551fedbe0a501397eafac.jpg', '<p>Cựu Vệ binh Hoàng gia Kao buộc phải chạy trốn khi cấp trên không thể chấp nhận việc anh ta là một người Mãn Châu kết hôn với một phụ nữ Hán. Một hoàng tử trẻ đã vô tình bị giết khi bắt cóc cậu bé để giúp cậu trốn thoát. 14 năm sau, Kao giờ là một kẻ say xỉn mang trong mình cảm giác tội lỗi, đang sống với một đứa trẻ mồ côi tên là Shu Geng. Hai cặp vợ chồng phù thủy già hay cãi vã, Old Man và Old Spinster, luôn cạnh tranh với nhau về những vấn đề nhỏ nhặt nhất. Không lâu sau, kẻ thù truyền kiếp của Kao, Socerer Bat mạnh mẽ, đã tìm ra tung tích của anh ta và giết chết anh ta. Mang trong mình những tham vọng xấu xa, Sorcerer Bat buộc Shu Geng đóng giả hoàng tử muộn màng, với ý định một ngày nào đó anh ta có thể cai trị cùng với vị vua sắp trở thành. Shu Geng cố gắng trốn thoát, giữa cuộc gặp gỡ kỳ lạ với chú hề trong lọ, và gặp hai cặp vợ chồng pháp sư cãi lộn thậm chí còn xa lạ, những người dạy cho anh ta nghề của họ.</p>', 'Full', 1, 'single', 'completed', 19, 1982, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Yuan Ri Chu","avatar":""},{"name":"Bryan Leung","avatar":""},{"name":"Cheung-Yan Yuen","avatar":""},{"name":"Shun-Yee Yuen","avatar":""},{"name":"Eddy Ko","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324550);
