INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-vat-bien-hinh', 'Sinh Vật Biến Hình', 'The Thing', 'https://phimimg.com/upload/vod/20240121-1/9dd8ecf5d9df42cb546c944123b0dd85.jpg', 'https://phimimg.com/upload/vod/20240121-1/e634318ceab5374d35284bb85be68ac4.jpg', '<p>Một đoàn nghiên cứu của Mỹ ở Nam cực phát hiện thấy tiếng súng nổ, và một người đàn ông trên chiếc trực thăng Na Uy đang điên cuồng đuổi giết một chú chó. Hai người này (viên phi công và tay súng) sau đó đều bị chết, một do tai nạn và một do anh này không giao tiếp được tiếng Anh lại giơ súng về phía đoàn nghiên cứu. Những người trong nhóm không hiểu được chuyện gì đã xảy ra khiến cho hai người kia có thái độ như thế, nhưng họ vẫn quyết định đưa chú chó bị đuổi giết về nuôi dưỡng. Điều họ không thể ngờ là con chó đó đã bị một sinh vật ngoài hành tinh bám vào...</p>', 'Full', 1, 'single', 'completed', 17, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kurt Russell","avatar":""},{"name":"Wilford Brimley","avatar":""},{"name":"Keith David","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324550);
