INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-trek-2-con-thinh-no-cua-khan', 'Star Trek 2: Cơn Thịnh Nộ Của Khan', 'Star Trek II: The Wrath Of Khan', 'https://phimimg.com/upload/vod/20231231-1/0c9577b925abc3b7ab0fe113e9f37cc7.jpg', 'https://phimimg.com/upload/vod/20231231-1/f4d2e5b2df288f95d675981aed1b1157.jpg', '<p>Đó là thế kỷ 23. Liên bang Starship U.S.S. Enterprise đang thực hiện các cuộc diễn tập huấn luyện thường lệ và Đô đốc James T. Kirk dường như cam chịu thực tế rằng chuyến thị sát này có thể là sứ mệnh không gian cuối cùng trong sự nghiệp của ông. Nhưng Khan đã trở lại. Được hỗ trợ bởi nhóm siêu nhân di truyền bị lưu đày của mình, Khan - kẻ phản bội xuất sắc của Trái đất thế kỷ 20 - đã đột kích vào Trạm vũ trụ Regula One, đánh cắp một thiết bị tuyệt mật có tên Project Genesis, giành quyền kiểm soát một Con tàu vũ trụ khác của Liên bang và bắt đầu truy đuổi Enterprise, quyết tâm không để bất cứ điều gì cản trở nhiệm vụ của mình: giết Đô đốc Kirk... ngay cả khi điều đó có nghĩa là Armageddon toàn cầu.</p>', 'Full', 1, 'single', 'completed', 18, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"William Shatner","avatar":""},{"name":"Leonard Nimoy","avatar":""},{"name":"DeForest Kelley","avatar":""},{"name":"Ricardo Montalban","avatar":""},{"name":"Kirstie Alley","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324550);
