INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-dam-huyen-thoai-3-1982', 'Tay Đấm Huyền Thoại 3', 'Rocky III', 'https://phimimg.com/upload/vod/20231231-1/1ab462e08c893930ce1febf411c7153c.jpg', 'https://phimimg.com/upload/vod/20231231-1/93d7378859976c202f23d0901854b678.jpg', '<p>Khi Rocky Balboa tìm được chỗ đứng trong trái tim của hàng triệu người hâm mộ, cuộc sống không còn gì có thể tốt đẹp hơn. Anh giành được chiến thắng 10 trận liên tiếp, giành được những hợp đồng béo bở và ngày càng nổi tiếng trên toàn thế giới. Nhưng khi Rocky bị đánh bại, dường như hào quang đã tắt. Đã xem xét đến chuyện treo găng, Rocky lại nhận được sự cổ vũ động viên của một người không ngờ tới: Đối thủ cũ, Apollo Creed. Với sự giúp đỡ của Apollo, Rocky cố gắng để lấy lại danh hiệu trong trận đối đầu với Clubber trong trận đấu khốc liệt tranh chức vô địch.</p>', 'Full', 1, 'single', 'completed', 21, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Talia Shire","avatar":""},{"name":"Burt Young","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324550);
