INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-quay-pha', 'Ma Quậy Phá', 'Poltergeist', 'https://phimimg.com/upload/vod/20231219-1/a54b8fbed8f95300f5f4384c14a88986.jpg', 'https://phimimg.com/upload/vod/20231219-1/189c14781104ef8e09db602520cdb3b5.jpg', '<p>Steve Freeling sống với vợ, Diane, và ba đứa con của họ, Dana, Robbie và Carol Anne, ở Nam California, nơi ông bán nhà cho công ty xây dựng khu phố. Nó bắt đầu chỉ với một vài sự cố kỳ lạ, chẳng hạn như bát đĩa bị vỡ và đồ đạc tự di chuyển xung quanh. Tuy nhiên, khi nhận ra rằng có một thứ gì đó thực sự xấu xa đang ám ảnh ngôi nhà của mình, Steve đã gọi một nhóm các nhà cận tâm lý học do Tiến sĩ Lesh dẫn đầu để giúp đỡ trước khi quá muộn.</p>', 'Full', 1, 'single', 'completed', 21, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Craig T. Nelson","avatar":""},{"name":"JoBeth Williams","avatar":""},{"name":"Beatrice Straight","avatar":""},{"name":"Dominique Dunne","avatar":""},{"name":"Oliver Robins","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324550);
