INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pink-floyd-the-wall', 'Pink Floyd: The Wall', 'Pink Floyd: The Wall', 'https://phimimg.com/upload/vod/20231211-1/93fc2177900dfa4b523ecc8970530578.jpg', 'https://phimimg.com/upload/vod/20231211-1/3ba965d6f5448a6fa8c604a4a59675b7.jpg', '<p>Một ngôi sao nhạc rock đang gặp rắc rối rơi vào tình trạng điên loạn khi bị mọi người cô lập về thể chất và xã hội.</p>', 'Full', 1, 'single', 'completed', 18, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Bob Geldof","avatar":""},{"name":"Christine Hargreaves","avatar":""},{"name":"James Laurenson","avatar":""},{"name":"Eleanor David","avatar":""},{"name":"Kevin McKeon","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
