INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('et-sinh-vat-ngoai-hanh-tinh', 'E.T: Sinh Vật Ngoài Hành Tinh', 'E.T. The Extra-Terrestrial', 'https://phimimg.com/upload/vod/20231211-1/274381039c7e15da1692c693243928bb.jpg', 'https://phimimg.com/upload/vod/20231211-1/b970fe4c649a6beb5f3afee1fc7183f0.jpg', '<p>Một đứa trẻ gặp khó khăn triệu tập sự can đảm để giúp một người ngoài hành tinh thân thiện thoát khỏi Trái đất và trở về thế giới nhà của mình.</p>', 'Full', 1, 'single', 'completed', 19, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324550);
