INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-de-1982', 'Bóng Đè', 'Incubus', 'https://phimimg.com/upload/vod/20231102-1/df6c1125d5459a9a274dfe4e7594b86e.jpg', 'https://phimimg.com/upload/vod/20231102-1/5181155bfb95941b1054e8de2f5171c8.jpg', '<p>Tại thị trấn Galen nhỏ ở New England, một cậu bé tuổi teen tuyên bố rằng cậu mơ thấy những phụ nữ trẻ bị hãm hiếp và sát hại dã man. Một bác sĩ và cảnh sát trưởng địa phương phát hiện ra rằng những giấc mơ của cậu bé là có thật và rằng một điều huyền bí độc ác có thể đứng sau những vụ giết người tàn bạo. Họ phải truy tìm kẻ giết người độc ác, kẻ có thể là hóa thân không thể tiêu diệt của một con quỷ sinh ra từ địa ngục.</p>', 'Full', 1, 'single', 'completed', 18, 1982, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"John Cassavetes","avatar":""},{"name":"John Ireland","avatar":""},{"name":"Helen Hughes","avatar":""},{"name":"Kerrie Keane","avatar":""},{"name":"Erin Noble","avatar":""},{"name":"Duncan McIntosh","avatar":""},{"name":"Harvey Atkin","avatar":""},{"name":"Harry Ditson","avatar":""},{"name":"Mitch Martin","avatar":""},{"name":"Matt Birman","avatar":""},{"name":"Beverly Cooper","avatar":""},{"name":"Brian Young","avatar":""},{"name":"Barbara Franklin","avatar":""},{"name":"Neil Dainard","avatar":""},{"name":"Jennifer Leak","avatar":""},{"name":"Denise Fergusson","avatar":""},{"name":"Helene Udy","avatar":""},{"name":"Michel","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324550);
