INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-muu-khung-bo', 'Âm Mưu Khủng Bố', 'Bloody Mission', 'null', 'https://phimimg.com/upload/vod/20231219-1/4ead31f589fdcffef3906a7c722b34f3.jpg', '<p>Bộ phim Âm Mưu Khủng Bố - Bloody Mission lấy bối cảnh năm 1982, khi ở Mỹ xảy ra bạo loạn nghiêm trọng. Bốn thành viên của Đảng Dân chủ lúc đó cùng bộ Quốc phòng mở cuộc họp hội đồng Nhà nước nhằm thảo luận giải quyết vấn đề. Tuy nhiên, không lâu sau đó, ba trên bốn thành viên của Đảng Dân chủ lần lượt bị ám sát, chỉ còn thành viên cuối cùng là Kei Son còn sống sót. Sau cuộc họp với Liên Hợp Quốc, Kei Son có chuyến thăm đến Hồng Kông. Lúc đó, người đứng đầu Tổng Lãnh sự quán Mỹ tại Hồng Kông cùng vợ bị bắt cóc, khiến cho mối quan hệ giữa hai nước ngày càng leo thang. Vì vậy, nhiệm vụ từ phía Hồng Kông là phải bảo vệ Kei Son kjoir các phần tử khủng bố bằng mọi giá</p>', 'Full', 1, 'single', 'completed', 20, 1982, 'Thuyết Minh', 'HD', 'Trung Quốc', 0, '[{"name":"Từ Thiếu Cường","avatar":""},{"name":"Bành Cương","avatar":""},{"name":"Lôi Thành Công","avatar":""},{"name":"Lưu Vĩnh","avatar":""},{"name":"Thích Quán Quân","avatar":""},{"name":"Tỉnh Lị","avatar":""},{"name":"Trình Bằng","avatar":""},{"name":"Trương Phục Kiến","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324550);
