INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-nu-hien-binh', 'Nam Nữ Hiến Binh', 'The Gendarme and the Gendarmettes', 'https://phimimg.com/upload/vod/20231202-1/2282633d8403ef67d0b42fb8d0473c63.jpg', 'https://phimimg.com/upload/vod/20231202-1/7807ff870f2d67e4fbf211cd90d912ec.jpg', '<p>Trụ sở cảnh sát của Cruchot chuyển đến sở chỉ huy mới. Họ không những được trang bị những thiết bị công nghệ cao mà còn phải nhận nhiệm vụ đào tạo cho 4 nữ cảnh sát trẻ. Những nữ cảnh sát trẻ cuốn hút đã nhận được sự tiếp đón nồng hậu khi họ xuất hiện. Tất cả đều tranh nhau để được làm việc với những cô nàng và nó thực sự gây ra sự náo loạn đến mất trí bởi những quý cô kiều diễm này.</p>', 'Full', 1, 'single', 'completed', 21, 1982, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Louis de Funès","avatar":""},{"name":"Michel Galabru","avatar":""},{"name":"Maurice Risch","avatar":""},{"name":"Jacques François","avatar":""},{"name":"Guy Grosso","avatar":""},{"name":"Michel Modo","avatar":""},{"name":"Patrick Préjean","avatar":""},{"name":"France Rumilly","avatar":""},{"name":"Catherine Serre","avatar":""},{"name":"Nicaise Jean-Louis","avatar":""},{"name":"Sophie Michaud","avatar":""},{"name":"Elisabeth Etienne","avatar":""},{"name":"Claude Gensac","avatar":""},{"name":"Jean-Louis Richard","avatar":""},{"name":"Pierre Repp","avatar":""},{"name":"Franck-Olivi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324550);
