INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-chon-cua-sophie', 'Lựa Chọn Của Sophie', 'Sophie''s Choice', 'https://phimimg.com/upload/vod/20231129-1/b97717985e3df3af8339e2a7cc521e06.jpg', 'https://phimimg.com/upload/vod/20231129-1/925bfdcbfb3f81dbc74551f4d08ab801.jpg', '<p>Sophie là một người còn sống sót từ địa ngục trần gian - trại tập trung của Đức quốc xã trong những năm thế chiến. Cô tìm thấy lý do để tiếp tục sống bên cạnh Nathan, một người nhanh nhẹn nhưng lại sống với sự ám ảnh về những lần tàn sát dã man người Do Thái của bọn phát xít. Họ làm bạn với Stingo, một người tường thuật phim, một người viết kịch bản mới đến New York. Cuộc sống của họ tưởng sẽ hạnh phúc khi bước qua khổ đau nhưng nó lại đi ngược lại. Hạnh phúc của họ bị đe dọa bởi chính sự ám ảnh của Nathan và bóng ma vô hình trong Shophie. Bộ phim được đề cử 4 giải Oscar. Sau 12 lần được đề cử nhưng lại ra về trắng tay, với diễn xuất quá xuất sắc trong Sophie&#39;s Choice 1982, lần đầu tiên Meryl Streep chạm tay vào Tượng vàng Oscar.</p>', 'Full', 1, 'single', 'completed', 15, 1982, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Meryl Streep","avatar":""},{"name":"Kevin Kline","avatar":""},{"name":"Peter MacNicol","avatar":""},{"name":"Rita Karin","avatar":""},{"name":"Josh Mostel","avatar":""},{"name":"Robin Bartlett","avatar":""},{"name":"Eugene Lipinski","avatar":""},{"name":"John Rothman","avatar":""},{"name":"Joseph Leon","avatar":""},{"name":"David Wohl","avatar":""},{"name":"Günther Maria Halmer","avatar":""},{"name":"Karlheinz Hackl","avatar":""},{"name":"Ulli Fessl","avatar":""},{"name":"Katharina Thalbach","avatar":""},{"name":"Moishe Rosenfeld","avatar":""},{"name":"Stephen D. Newman","avatar":""},{"name":"Greta T","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324550);
