INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-gandhi', 'Cuộc Đời Gandhi', 'Gandhi', 'https://phimimg.com/upload/vod/20231129-1/398683fec0de9c9ec864f3faceb97499.jpg', 'https://phimimg.com/upload/vod/20231129-1/9c0ae5bcc25e48516e3fe40891049927.jpg', '<p>Vào những năm đầu của thế kỷ 20, Mohandas K. Gandhi, một luật sư được đào tạo ở Anh, từ bỏ mọi của cải vật chất để theo đuổi sự nghiệp độc lập của Ấn Độ. Đối mặt với sự phản kháng vũ trang của chính phủ Anh, Gandhi áp dụng chính sách &#39;phản kháng thụ động&#39;, nỗ lực giành tự do cho người dân của mình mà không cần đổ máu.</p>', 'Full', 1, 'single', 'completed', 13, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Ben Kingsley","avatar":""},{"name":"Candice Bergen","avatar":""},{"name":"Edward Fox","avatar":""},{"name":"John Gielgud","avatar":""},{"name":"Trevor Howard","avatar":""},{"name":"John Mills","avatar":""},{"name":"Martin Sheen","avatar":""},{"name":"Ian Charleson","avatar":""},{"name":"Athol Fugard","avatar":""},{"name":"Günther Maria Halmer","avatar":""},{"name":"Saeed Jaffrey","avatar":""},{"name":"Geraldine James","avatar":""},{"name":"Alyque Padamsee","avatar":""},{"name":"Amrish Puri","avatar":""},{"name":"Roshan Seth","avatar":""},{"name":"Rohini Hattangadi","avatar":""},{"name":"Ian Bannen","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324550);
