INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-sat-nhan-newyork', 'Tên Sát Nhân NewYork', 'The New York Ripper', 'https://phimimg.com/upload/vod/20231115-1/cfb09287d569e1401972b3563a1b463d.jpg', 'https://phimimg.com/upload/vod/20231115-1/9fe50dab390e4ba8ca1be81ac45dba5f.jpg', '<p>Tên Sát Nhân New York - The New York Ripper (1982) là một bộ phim của đạo diễn Lucio Fulci do đất nước Italia sản xuất nhưng phim lại được lấy và quay trực tiếp tại thành phố New York của Hoa Kỳ. Nội dung phim xoay quanh câu chuyện điều tra của một thám tử tư kết hợp cùng một bậc thầy tâm lý để điều tra vụ án về tên sát nhân hàng loạt và biến thái trong phim Tên Sát Nhân New York - The New York Ripper (1982), con mồi của hắn ta chính là những phụ nữ yếu đuối sống trong thành phố, cách thức ra tay rất thủ đoạn và độc ác.</p>', 'Full', 1, 'single', 'completed', 30, 1982, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Jack Hedley","avatar":""},{"name":"Almanta Suska","avatar":""},{"name":"Howard Ross","avatar":""},{"name":"Andrea Occhipinti","avatar":""},{"name":"Alexandra Delli Colli","avatar":""},{"name":"Paolo Malco","avatar":""},{"name":"Cinzia de Ponti","avatar":""},{"name":"Cosimo Cinieri","avatar":""},{"name":"Daniela Doria","avatar":""},{"name":"Babette New","avatar":""},{"name":"Zora Kerova","avatar":""},{"name":"Antone Pagán","avatar":""},{"name":"Josh Cruze","avatar":""},{"name":"Rita Silva","avatar":""},{"name":"Giordano Falzoni","avatar":""},{"name":"Lucio Fulci","avatar":""},{"name":"Barbara Cupisti","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324550);
