INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-quan-cua-garp', 'Thế Giới Quan Của Garp', 'The World According to Garp', 'https://phimimg.com/upload/vod/20231115-1/d5fd5afe6388133233f119bd68505cfc.jpg', 'https://phimimg.com/upload/vod/20231115-1/af170aadcb67d75ef595b64a4e5f81f7.jpg', '<p>Một nhà văn trẻ đang gặp khó khăn nhận thấy cuộc sống và công việc của mình bị chi phối bởi người vợ không chung thủy và người mẹ nữ quyền cực đoan của anh ta, người mà bản tuyên ngôn bán chạy nhất đã biến cô ấy thành một biểu tượng văn hóa.</p>', 'Full', 1, 'single', 'completed', 25, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robin Williams","avatar":""},{"name":"Mary Beth Hurt","avatar":""},{"name":"Glenn Close","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Hume Cronyn","avatar":""},{"name":"Jessica Tandy","avatar":""},{"name":"Swoosie Kurtz","avatar":""},{"name":"Brenda Currin","avatar":""},{"name":"Peter Michael Goetz","avatar":""},{"name":"Jenny Wright","avatar":""},{"name":"John Irving","avatar":""},{"name":"Amanda Plummer","avatar":""},{"name":"Bette Henritze","avatar":""},{"name":"Katherine Borowitz","avatar":""},{"name":"Kate McGregor-Stewart","avatar":""},{"name":"Mark Soper","avatar":""},{"name":"War","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324550);
