INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-lam-tu', 'Thiếu Lâm Tự', 'The Shaolin Temple', 'https://phimimg.com/upload/vod/20231102-1/12098f603a7ce9be5022c0d0d767e0cf.jpg', 'https://phimimg.com/upload/vod/20231102-1/0ef0e6f4b6c7268883e9852c9a83ff22.jpg', '<p>&quot;Thiếu Lâm tự&quot; là câu chuyện kể về một chàng trai quyết tâm rèn luyện mình để có thể tự tay giết chết kẻ thù giết cha và phản bội Hoàng đế. Đại Đường đang trải qua những năm tháng khắc nghiệt nhất, Hoàng đế trẻ nhà Đường bị một trong những tướng lĩnh thân cận của mình phản bội. Sau đó hắn ta nghiễm nhiên trở thành Hoàng đế tại thủ phủ phía đông Đại Đường. Được sự trợ giúp từ một tên tay sai độc ác, bọn chúng hành hạ dã man và sát hại không biết bao nhiêu nô lệ làm nô dịch cho chúng. Con trai của một nô lệ đã trốn thoát được với ý định đến chùa Thiếu Lâm quyết học kungfu để trả món nợ máu. Tại Thiếu Lâm, chàng trai trẻ đã được các nhà sư cứu vớt, chữa lành vết thương và ra sức dạy võ. Trong một môi trường thử thách khắc nghiệt của nhà Phât, liệu chàng trai có đủ nghị lực để chiến thắng bản thân mình, rèn giũa thành tài để trả mối thù cho cha và cho cả đất nước?
 =</p>', 'Full', 1, 'single', 'completed', 26, 1982, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jet Li","avatar":""},{"name":"Hai Yu","avatar":""},{"name":"Yu Cheng-Hui","avatar":""},{"name":"Chunhua Ji","avatar":""},{"name":"Ding Laam","avatar":""},{"name":"Hu Jian Qiang","avatar":""},{"name":"Jiankui Sun","avatar":""},{"name":"Liu Huai Liang","avatar":""},{"name":"Zhang Jian","avatar":""},{"name":"Yan Di Hua","avatar":""},{"name":"Wang Guang Quan","avatar":""},{"name":"Du Chuan Yang","avatar":""},{"name":"Cui Zhi Qiang","avatar":""},{"name":"Cham Fung","avatar":""},{"name":"Pan Han-Guang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324550);
