INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('halloween-3-thoi-dai-phu-thuy', 'Halloween 3: Thời Đại Phù Thủy', 'Halloween III: Season of the Witch', 'https://phimimg.com/upload/vod/20231024-1/5e5969c34427a78d4c0a63e770d75fdf.jpg', 'https://phimimg.com/upload/vod/20231024-1/124b14d1f0444b17f555e1e68fcb77f6.jpg', '<p>Tiến sĩ Daniel Challis và Ellie Grimbridge tình cờ phát hiện ra một âm mưu giết người khủng khiếp khi cha của Ellie, nhân viên bán hàng mới lạ, Harry, bị giết khi đang sở hữu một chiếc mặt nạ halloween do công ty mặt nạ Silver Shamrock sản xuất. Chủ sở hữu công ty, Conal Cochran, muốn đưa Halloween trở lại nguồn gốc đen tối hơn bằng cách sử dụng những chiếc mặt nạ của mình -- và âm mưu không thể diễn tả được của anh ta sẽ gây ra cái chết và sự hủy diệt trên khắp đất nước.</p>', 'Full', 1, 'single', 'completed', 14, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Tom Atkins","avatar":""},{"name":"Stacey Nelkin","avatar":""},{"name":"Dan O''Herlihy","avatar":""},{"name":"Michael Currie","avatar":""},{"name":"Ralph Strait","avatar":""},{"name":"Jadeen Barbor","avatar":""},{"name":"Brad Schacter","avatar":""},{"name":"Garn Stephens","avatar":""},{"name":"Nancy Kyes","avatar":""},{"name":"Jonathan Terry","avatar":""},{"name":"Al Berry","avatar":""},{"name":"Wendy Wessberg","avatar":""},{"name":"Essex Smith","avatar":""},{"name":"Maidie Norman","avatar":""},{"name":"John MacBride","avatar":""},{"name":"Dick Warlock","avatar":""},{"name":"Joshua John Miller","avatar":""},{"name":"Mi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324550);
