INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-6-ngay-13-phan-3', 'Thứ 6 Ngày 13 Phần 3', 'Friday the 13th Part III', 'https://phimimg.com/upload/vod/20231024-1/7075de39a02090c93dadc40a4ee7359f.jpg', 'https://phimimg.com/upload/vod/20231024-1/a51920303b588ac1448d42868dffc921.jpg', '<p>Một mùa hè bình dị biến thành cơn ác mộng kinh hoàng không thể tả xiết đối với một nhóm cố vấn ngây thơ khác. Bỏ qua di sản đẫm máu của Camp Crystal Lake, từng người một họ trở thành nạn nhân của tên điên khùng Jason, kẻ luôn rình rập họ...</p>', 'Full', 1, 'single', 'completed', 24, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Dana Kimmell","avatar":""},{"name":"Catherine Parks","avatar":""},{"name":"Richard Brooker","avatar":""},{"name":"Tracie Savage","avatar":""},{"name":"David Wiley","avatar":""},{"name":"Rachel Howard","avatar":""},{"name":"Anne Gaybis","avatar":""},{"name":"Larry Zerner","avatar":""},{"name":"Paul Kratka","avatar":""},{"name":"Jeffrey Rogers","avatar":""},{"name":"Steve Miner","avatar":""},{"name":"David Katims","avatar":""},{"name":"Kevin O''Brien","avatar":""},{"name":"Nick Savage","avatar":""},{"name":"Cheri Maugans","avatar":""},{"name":"Gloria Charles","avatar":""},{"name":"Steve Susskind","avatar":""},{"name":"P","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324550);
