INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-rambo', 'Chiến Binh Rambo', 'First Blood', 'https://phimimg.com/upload/vod/20231022-1/79826df499cac84c18e2de3328e6dee5.jpg', 'https://phimimg.com/upload/vod/20231022-1/00780fd0bfb2a715ce02171fa930982d.jpg', '<p>&quot;Rambo&quot; (1982) xoay quanh cuộc phiêu lưu của John J.Rambo, một người lính trở về từ cuộc chiến tranh, nhưng anh không thể thích nghi với cuộc sống bình thường nên chấp nhận nay đây mai đó. John tới Hope, một thị trấn nhỏ ở bang Washington. Cảnh sát trưởng Will Teasle Will bắt giữ anh vì tội sống lang thang, chống lại người thi hành công vụ và mang vũ khí trái phép. John đánh gục toàn bộ đám cảnh sát bằng tay không, lao ra ngoài và nhảy lên một chiếc moto. Một cuộc phiêu lưu bắt đầu từ đây...</p>', 'Full', 1, 'single', 'completed', 20, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sylvester Stallone","avatar":""},{"name":"Richard Crenna","avatar":""},{"name":"Brian Dennehy","avatar":""},{"name":"Bill McKinney","avatar":""},{"name":"Jack Starrett","avatar":""},{"name":"Michael Talbott","avatar":""},{"name":"Chris Mulkey","avatar":""},{"name":"John McLiam","avatar":""},{"name":"Alf Humphreys","avatar":""},{"name":"David Caruso","avatar":""},{"name":"David L. Crowley","avatar":""},{"name":"Don MacKay","avatar":""},{"name":"Charles A. Tamburro","avatar":""},{"name":"David Petersen","avatar":""},{"name":"Craig Huston","avatar":""},{"name":"Patrick Stack","avatar":""},{"name":"Steph","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183