INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-pham-nhan-ban', 'Tội Phạm Nhân Bản', 'Blade Runner', 'https://phimimg.com/upload/vod/20231020-1/d6ba2c7eb0a3f8960e3628448c0a53a5.jpg', 'https://phimimg.com/upload/vod/20231020-1/2ce10643cc72a99eeec844b23225e385.jpg', '<p>Blade Runner lấy bối cảnh thế giới tương lai, nơi ô nhiễm môi trường, khủng hoảng lương thực khiến cuộc sống của con người trở thành địa ngục. Để thoát khỏi diệt vong, nhân loại tiến hành khai phá các hành tinh khác trong vũ trụ để thành lập thuộc địa. Họ sử dụng người nhân bản do Eldon Tyrell chế tạo làm nguồn lao động chính. Người nhân bản được tạo ra rất giống với con người, có cảm xúc, suy nghĩ nhưng có tuổi thọ nhất định ở một số phiên bản. Blade Runner là lực lượng cảnh sát được thành lập để săn đuổi và tiêu diệt những người nhân bản lẩn trốn trên trái đất. Trong phần này, các Blade Runner đều là con người. Sang phần phim Blade Runner 2049, các Nexus-9 cũng được tham gia lực lượng này.</p>', 'Full', 1, 'single', 'completed', 21, 1982, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harrison Ford","avatar":""},{"name":"Rutger Hauer","avatar":""},{"name":"Sean Young","avatar":""},{"name":"Edward James Olmos","avatar":""},{"name":"M. Emmet Walsh","avatar":""},{"name":"Daryl Hannah","avatar":""},{"name":"William Sanderson","avatar":""},{"name":"Brion James","avatar":""},{"name":"Joe Turkel","avatar":""},{"name":"Joanna Cassidy","avatar":""},{"name":"James Hong","avatar":""},{"name":"Kevin Thompson","avatar":""},{"name":"Hy Pyke","avatar":""},{"name":"Kimiko Hiroshige","avatar":""},{"name":"Ben Astar","avatar":""},{"name":"Dawna Lee Heising","avatar":""},{"name":"Alexis Rhee","avatar":""},{"name":"Bob Ok","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324550);
