INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-mon-don-giap', 'Kỳ Môn Độn Giáp', 'Miracle Fighters', 'https://phimimg.com/upload/vod/20231010-1/86f142e5bb2a660542e6c6218746279f.jpg', 'https://phimimg.com/upload/vod/20231010-1/b864ecf9b4063a86e452071b90580f03.jpg', '<p>Hai đạo sĩ lớn tuổi, Chi Men và Dun Jai, học phép thuật từ cùng một giáo viên, luôn cãi nhau. Họ mang đến niềm vui và sự dạy dỗ kung fu chuyên nghiệp cho chàng trai trẻ bị nhầm tưởng là thái tử của Triều đình, mất tích từ khi còn nhỏ. Hoàng đế phái một hoạn quan có sức mạnh thần kỳ để bắt chàng trai trẻ. Nhưng trước tiên anh phải đối phó với Chi Men và Dun Jia, những người bảo vệ chàng trai trẻ.</p>', 'Full', 1, 'single', 'completed', 18, 1982, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Simon Yuen Yat-Choh","avatar":""},{"name":"Leung Kar-yan","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"Brandy Yuen Jan-Yeung","avatar":""},{"name":"Eddy Ko","avatar":""},{"name":"Yuen Shun-Yi","avatar":""},{"name":"Huang Ha","avatar":""},{"name":"Tino Wong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324550);
