INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-thieu-gia', 'Long Thiếu Gia', 'Dragon Lord', 'https://phimimg.com/upload/vod/20231007-1/68bb203f19822e6ed9225187090150e2.jpg', 'https://phimimg.com/upload/vod/20231007-1/e76fa1d232dd259f56c5acb2b55f77e9.jpg', '<p>Trong phim, nhân vật chính do Jackie thủ vai cố gắng gửi 1 bức thư tình cho bạn gái bằng 1 cánh diều nhưng không may cánh diều lại bị thất lạc. Trong lúc cố gắng đi tìm lại cánh diều của mình, Chan nhận ra rằng mình đi lạc vào hang ổ của một nhóm cướp - Bọn cướp này đang có âm mưu trộm cổ vật của trung hoa ...</p>', 'Full', 1, 'single', 'completed', 24, 1982, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Michael Chan","avatar":""},{"name":"Suet Lee","avatar":""},{"name":"Mars","avatar":""},{"name":"Tien Feng","avatar":""},{"name":"Paul Chang Chung","avatar":""},{"name":"Tai Bo","avatar":""},{"name":"Cheng Kang-Yeh","avatar":""},{"name":"Anna Ng Yuen-Yee","avatar":""},{"name":"Cheng Mang-Ha","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
