INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-phong-ke-trom', 'Đề Phòng Kẻ Trộm', 'Carry On Pickpocket', 'https://phimimg.com/upload/vod/20231006-1/7ada5d3d26dd7dbe1e73a04999ae430f.jpg', 'https://phimimg.com/upload/vod/20231006-1/7c9e345e70672d01df5b9e3f7715483e.jpg', '<p>Bậc thầy trộm cắp Jin đã cùng con gái Annie và hai người học việc Migang và Yantong ăn trộm trên những con phố đông đúc và chưa bao giờ thất bại. Một ngày nọ, Migang và Yantong đến vũ trường dành cho phụ nữ. Migang yêu một người trong số họ tên là Yaling ngay từ cái nhìn đầu tiên. Họ đã bị chặn lại bởi một cuộc chiến. Wu Shazhan định bắt họ nhưng không thành công. Chẳng bao lâu, một băng nhóm tội phạm đánh giá cao khả năng ăn trộm của chúng và có ý định mua chứng minh thư mà chúng lấy trộm. Sau đó họ buộc phải hoàn thành nhiệm vụ. Sau đó, Yaling nói với Migang rằng cô là một nữ cảnh sát chìm và nhờ anh giúp đỡ. Sau đó họ vướng vào một loạt thủ đoạn bẩn thỉu…</p>', 'Full', 1, 'single', 'completed', 24, 1982, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Frankie Chan Fan-Kei","avatar":""},{"name":"Deanie Ip","avatar":""},{"name":"Richard Ng","avatar":""},{"name":"Pang Sau-Ha","avatar":""},{"name":"Lau Hak-Suen","avatar":""},{"name":"Peter Chan","avatar":""},{"name":"Dick Wei","avatar":""},{"name":"Jamie Luk Kim-Ming","avatar":""},{"name":"Ka Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324550);
