INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tang-le-va-le-tang', 'Tang lễ và Lễ tang', 'The Dead and the Deadly', 'https://phimimg.com/upload/vod/20230912-1/5a0840f469a3ab7b60d1e86d95eb0e0e.jpg', 'https://phimimg.com/upload/vod/20230912-1/1cad1cee73cb7ac1288eef8a106fb1ff.jpg', '<p>Wah Li, được bạn bè gọi là Fat Boy, sống với chú cố của mình là linh mục (Bác). Cùng với những người bạn kỳ quặc Lai Li và Momo, Wah Li giúp Bác điều hành các dịch vụ tang lễ ở địa phương. Khi thi thể Ma Lun Chio được người vợ mới và &quot;anh trai&quot; của cô mang về làng, Wai Li tỏ ra nghi ngờ. Anh bắt đầu tìm hiểu xem bạn mình đã chết như thế nào, nhưng mọi thứ không như những gì họ tưởng.</p>', 'Full', 1, 'single', 'completed', 31, 1982, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Lam Ching-Ying","avatar":""},{"name":"Cherie Chung","avatar":""},{"name":"Hui Leung-Mei","avatar":""},{"name":"Chin Yuet-Sang","avatar":""},{"name":"To Siu-Ming","avatar":""},{"name":"Chang Ching-Po","avatar":""},{"name":"Hui Ying-Ying","avatar":""},{"name":"Paul Chung Fat","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324550);
