INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-de-luu-manh', 'Hoàng Đế Lưu Manh', 'The Misadventure of Zoo', 'https://phimimg.com/upload/vod/20251008-1/dd3c2e16c3df0ea3621aeb7929e52d68.jpg', 'https://phimimg.com/upload/vod/20251008-1/cbb1863809e9629782bcd892fcad4771.jpg', '<p>The Misadventure of Zoo là một bộ phim truyền hình của đài TVB, được công chiếu vào năm 1981. Bài hát chủ đề “Personhood Loves Freedom” do Joseph Koo viết lời, Wong Jim hát, Adam Cheng hát, và bài hát chủ đề “Cheers” được sáng tác và sắp xếp bởi Joseph Koo, viết lời của Wong Jim, được hát bởi Adam Cheng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 1981, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Adam Cheng Siu-Chow","avatar":""},{"name":"Louise Lee Si-Kei","avatar":""},{"name":"Bai Lan","avatar":""},{"name":"Lydia Shum Tin-Ha","avatar":""},{"name":"Tang Pik-Wan","avatar":""},{"name":"Chong Man-Ching","avatar":""},{"name":"Deanie Yip Tak-Han","avatar":""},{"name":"Felix Wong Yat-Wah","avatar":""},{"name":"Chun Wong","avatar":""},{"name":"Lung Tin-Sang","avatar":""},{"name":"Tsang Choh-Lam","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Kent Cheng Jak-Si","avatar":""},{"name":"Lo Hoi-Pang","avatar":""},{"name":"Kong Ngai","avatar":""},{"name":"Ng Man-Tat","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Rogue Emperor","The Misadventure of Zoo","流氓皇帝"]', 1784690324550);
