INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-cay-1981', 'Ma Cây', 'The Evil Dead', 'https://phimimg.com/upload/vod/20250830-1/ab46ae6e087ccda90841c7467e3df79f.jpg', 'https://phimimg.com/upload/vod/20250830-1/2474a43937aab90ece577f75c0c845ac.jpg', '<p>Năm người bạn đi nghỉ hè và trú tại ngôi nhà nhỏ trong một khu rừng. Họ tình cờ tìm thấy &quot;Quyển sách của người chết&quot; (The Book of the Dead) và cuốn băng ghi âm của một vị giáo sư, chủ nhân của ngôi nhà này. Một trong số họ mở cuốn băng nghe. Đó chính là bùa chú được giáo sư dịch từ Necronomicon (Book of the Dead), chìa khóa giải thoát thế lực quỷ dữ trong khu rừng (ma cây). Một cô gái trong nhóm mất bình tĩnh đã chạy sâu vào trong rừng và bị ma cây cưỡng hiếp. Những người còn lại dần dần bị sát hại và biến thành ma (deadite). Ash, thành viên duy nhất còn sống sót phải chứng kiến những cảnh tượng ghê rợn và tự giải thoát bản thân mình.</p>', 'Full', 1, 'single', 'completed', 18, 1981, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bruce Campbell","avatar":""},{"name":"Ellen Sandweiss","avatar":""},{"name":"Richard DeManincor","avatar":""},{"name":"Betsy Baker","avatar":""},{"name":"Theresa Tilly","avatar":""},{"name":"Philip A. Gillis","avatar":""},{"name":"Dorothy Tapert","avatar":""},{"name":"Cheryl Guttridge","avatar":""},{"name":"Barbara Carey","avatar":""},{"name":"David Horton","avatar":""},{"name":"Wendall Thomas","avatar":""},{"name":"Don Long","avatar":""},{"name":"Stu Smith","avatar":""},{"name":"Kurt Rauf","avatar":""},{"name":"Ted Raimi","avatar":""},{"name":"Ivan Raimi","avatar":""},{"name":"Bill Vincent","avatar":""},{"name":"Mary Bet","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184