INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tarzan-nguoi-khi', 'Tarzan Người Khỉ', 'Tarzan The Ape Man', 'https://phimimg.com/upload/vod/20250806-1/487faf364853063466a0c3c916c39d2a.jpg', 'https://phimimg.com/upload/vod/20250806-1/dabdb38187675a187c8827aa5b48f39f.jpg', '<p>Câu chuyện được kể từ góc nhìn của Jane, theo chân Jane Parker đến châu Phi thăm cha và cùng ông tham gia một chuyến thám hiểm. Vài lần chạm mặt Tarzan đã thắp lên mối hấp dẫn đầy đam mê giữa họ. Khi đoàn thám hiểm bị một bộ tộc man rợ bắt giữ, Tarzan xuất hiện để giải cứu.</p>', 'Full', 1, 'single', 'completed', 20, 1981, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bo Derek","avatar":""},{"name":"Richard Harris","avatar":""},{"name":"John Phillip Law","avatar":""},{"name":"Miles O''Keeffe","avatar":""},{"name":"Steve Strong","avatar":""},{"name":"Wilfrid Hyde-White","avatar":""},{"name":"Laurie Main","avatar":""},{"name":"Harold Ayer","avatar":""},{"name":"Akushula Selayah","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Tarzan, the Ape Man","Tarzan, Herr des Urwalds","Tarzan, Herr der Affen","Tarzan, Herr des Dschungels","Tarzan the Ape Man"]', 1784690324550);
