INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-lich-su-khai-pha-vu-tru-1981', 'Doraemon: Nobita và Lịch Sử Khai Phá Vũ Trụ', 'Doraemon: The Record of Nobita, Spaceblazer', 'https://phimimg.com/upload/vod/20250521-1/61db7dbce86b3b5eb0bdb27d78f831c0.jpg', 'https://phimimg.com/upload/vod/20250521-1/1a1da81391aa571cc8a3c44f899c96fb.jpg', '<p>Bảy năm trước, Lopplc và Morina đang chơi ở một công viên. Đột nhiên họ cảm thấy một trận động đất trên Hành tinh Koya Koya. Trận động đất lớn đến mức hành tinh đã bị phá hủy. Mọi người phải thoát ra ngoài bằng một con tàu khổng lồ. Một tia sét bất ngờ gây mất điện và làm hư hỏng con tàu. Giáo sư (cha của Morina) muốn sửa con tàu vũ trụ, nhưng một tia sét khác đã đưa anh ta đến một không gian khác.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 1981, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Kazuya Tatekabe","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Masako Sugaya","avatar":""},{"name":"Emiko Tsukada","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["宇宙開拓史","Doraemon Nobita no Uchu Kaitakushi","The Record of Nobita, Spaceblazer","哆啦A夢：大雄的宇宙開拓史","โดราเอมอน ตอน โนบิตะนักบุกเบิกอวกาศ","도라에몽: 노비타의 우주개척사","Doraemon Nobita no Uchuu Kaitakushi","ドラえもん のび太の宇宙開拓史","映画ドラえもん のび太の宇宙開拓史"]', 1784690324550);
