INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-lich-su-khai-pha-vu-tru-1981', 'Doraemon: Nobita và Lịch Sử Khai Phá Vũ Trụ', 'Doraemon: The Record of Nobita, Spaceblazer', 'doraemon: nobita và lịch sử khai phá vũ trụ doraemon: the record of nobita, spaceblazer nobuyo oyama kazuya tatekabe kaneta kimotsuki michiko nomura noriko ohara masako sugaya emiko tsukada 宇宙開拓史 doraemon nobita no uchu kaitakushi the record of nobita, spaceblazer 哆啦a夢：大雄的宇宙開拓史 โดราเอมอน ตอน โนบิตะนักบุกเบิกอวกาศ 도라에몽: 노비타의 우주개척사 doraemon nobita no uchuu kaitakushi ドラえもん のび太の宇宙開拓史 映画ドラえもん のび太の宇宙開拓史', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-boi', 'Trưởng Bối', 'My Young Auntie', 'https://phimimg.com/upload/vod/20250319-1/efd7939a3a2c69c7fb3a0fa0f74d5239.jpg', 'https://phimimg.com/upload/vod/20250319-1/a480393ed1bef73bba342395684ccd61.jpg', '<p>Đây là một bộ phim võ thuật, kiếm hiệp, hài ý nhị, thật hay, vô cùng hấp dẫn từ đầu đến cuối, với 3 siêu sao nỗi tiếng về phim kiếm hiệp là Lưu Gia Lương, Lưu Gia Huy và Huệ Ánh Hồng. Cốt truyện thât với tranh chấp gia tài của anh họ Dư gây ra nhiều cuộc đấu nhau kiếm, võ thuật thật ác liệt dài suốt 2 tiếng với nhiều tình tiết thật buồn cười nhưng thật ý nhị không vô duyên chút nào. Xem phim này xong, bạn nào không cười đấy mới là chuyện lạ . Trong phim này Lưu Gia Huy rất tiếc còn đóng vai phụ.</p>', 'Full', 1, 'single', 'completed', 16, 1981, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Lau Kar-Leung","avatar":""},{"name":"Kara Wai Ying-Hung","avatar":""},{"name":"Hsiao Ho","avatar":""},{"name":"Johnny Wang Lung-Wei","avatar":""},{"name":"Wilson Tong","avatar":""},{"name":"Kwon Yeong-Moon","avatar":""},{"name":"Walter Tso Tat-Wah","avatar":""},{"name":"Gordon Liu Chia-Hui","avatar":""},{"name":"Richard Yuen Tak","avatar":""},{"name":"Robert Mak Tak-Law","avatar":""},{"name":"King Lee King-Chu","avatar":""},{"name":"Wang Sha","avatar":""},{"name":"Lam Fai-Wong","avatar":""},{"name":"Aai Dung-Gwa","avatar":""},{"name":"San Sin","avatar":""},{"name":"Wong Ching-Ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zhang bei","Cheung bui","Моя молодая тётушка","Fangs of the Tigress","The Senior","Minha Tia Jovem","My Young Auntie","長輩"]', 1784690324550);
