INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-nu-ba-tuoc', 'Người Tình Nữ Bá Tước', 'Lady Chatterley''s Lover', 'https://phimimg.com/upload/vod/20231203-1/a5073ad54996babe9667a7bd9c10b81e.jpg', 'https://phimimg.com/upload/vod/20231203-1/1bb5785dcbb394ccf45ef34426d61eff.jpg', '<p>Một bộ phim chuyển thể từ tiểu thuyết của D.H. Lawrence. Sau một chấn thương tàn tật khiến chồng bị liệt dương, Lady Chatterly bị giằng xé giữa tình yêu dành cho chồng và ham muốn thể xác. Với sự đồng ý của chồng, cô ấy tìm kiếm những cách khác để đáp ứng nhu cầu của mình.</p>', 'Full', 1, 'single', 'completed', 18, 1981, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sylvia Kristel","avatar":""},{"name":"Shane Briant","avatar":""},{"name":"Nicholas Clay","avatar":""},{"name":"Ann Mitchell","avatar":""},{"name":"Elizabeth Spriggs","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
