INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-duc-vong', 'Khách Sạn Dục Vọng', 'Honey', 'https://phimimg.com/upload/vod/20240804-1/bdee6eb7071b69b9587a8147af5d679d.jpg', 'https://phimimg.com/upload/vod/20240804-1/ed49e04e34d750abcc221de8f165b46f.jpg', '<p>Một câu chuyện tưởng tượng khiêu dâm siêu thực về một phụ nữ trẻ bước vào một khách sạn mê cung kỳ quái.</p>', 'Full', 1, 'single', 'completed', 24, 1981, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Clio Goldsmith","avatar":""},{"name":"Catherine Spaak","avatar":""},{"name":"Fernando Rey","avatar":""},{"name":"Donatella Damiani","avatar":""},{"name":"Nieves Navarro","avatar":""},{"name":"Lino Troisi","avatar":""},{"name":"Adriana Russo","avatar":""},{"name":"Giuseppe Pennese","avatar":""},{"name":"Francisca Fernández","avatar":""},{"name":"Luc Merenda","avatar":""},{"name":"Anja Engstrom","avatar":""},{"name":"Manlio De Angelis","avatar":""},{"name":"Germana Dominici","avatar":""},{"name":"Milla Johansson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324550);
