INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-tu-vong', 'Tháp Tử Vong', 'Game of Death II', 'https://phimimg.com/upload/vod/20240802-1/aee4b3068c13fb6cd49903a0291c7b19.jpg', 'https://phimimg.com/upload/vod/20240802-1/e6330b07711a00685f319d638cf5e61e.jpg', '<p>Nội dung của phim bắt đầu từ thời điểm Billy Lo trở lại để khám phá ra sự thật sau cái chết của anh bạn là Chin Ku. Mặc dù được biết Chin Ku chết do bệnh, tuy nhiên có nhiều nghi vấn về sự thật cái chết này và bộc lộ rõ hơn khi xảy ra vụ cướp quan tài của Chin Ku trong lúc mọi người đang chuẩn bị an táng cho anh ngoài nghĩa trang.</p>', 'Full', 1, 'single', 'completed', 17, 1981, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"김태정","avatar":""},{"name":"Bruce Lee","avatar":""},{"name":"Hwang Jang-Lee","avatar":""},{"name":"Roy Horan","avatar":""},{"name":"Roy Chiao","avatar":""},{"name":"Hao Li-Jen","avatar":""},{"name":"杜偉和","avatar":""},{"name":"Tiger Yang Cheong-Woo","avatar":""},{"name":"李海生","avatar":""},{"name":"Wang Ho","avatar":""},{"name":"Brian Baek Hwang-gi","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"Brandy Yuen Jan-Yeung","avatar":""},{"name":"Graham Ravey","avatar":""},{"name":"Chik Ngai-Hung","avatar":""},{"name":"Chui Fat","avatar":""},{"name":"Tam Bo","avatar":""},{"name":"Pan Yung-Sheng","avatar":""},{"name":"Chan Dik-Hak","avatar":""},{"name":"Wong Chi-Ming","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324550);
