INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thap-tu-vong', 'Tháp Tử Vong', 'Game of Death II', 'tháp tử vong game of death ii 김태정 bruce lee hwang jang-lee roy horan roy chiao hao li-jen 杜偉和 tiger yang cheong-woo 李海生 wang ho brian baek hwang-gi yuen biao brandy yuen jan-yeung graham ravey chik ngai-hung chui fat tam bo pan yung-sheng chan dik-hak wong chi-ming ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-quan', 'Võ Quán', 'Martial Club', 'https://phimimg.com/upload/vod/20240726-1/df4dca5af89ac49264ad7cf6e566431b.jpg', 'https://phimimg.com/upload/vod/20240726-1/80b0eb23c9b4411c826418a229f46a89.jpg', '<p>Đạo diễn võ thuật nổi tiếng của Shaw Brothers, Lưu Gia Lương một lần nữa lại đem đến khán giả một bộ phim hành động với những mà kung fu đỉnh cao được kết hợp với những loại hình văn hoá Á Đông đặc sắc, lần này chính là Múa Lân. Bộ phim xoay quanh mâu thuẫn, hận thù, ân oán của những đội múa lân Trung Hoa. Dương Lâm và Phi Hùng, vốn là bằng hữu thân thiết, nhưng trải qua nhiều biến cố, hãm hại do kẻ đố kỵ Sơn Hào gây ra, liệu tình bạn của họ có còn vẹn nguyên? Những màn đấu võ đỉnh cao được kết hợp với nghệ thuật múa lân sẽ đem đến những khung hình mãn nhãn cho bất cứ người xem khó tình nào.</p>', 'Full', 1, 'single', 'completed', 20, 1981, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Gordon Liu Chia-hui","avatar":""},{"name":"惠英紅","avatar":""},{"name":"Johnny Wang Lung-Wei","avatar":""},{"name":"Wilson Tong","avatar":""},{"name":"Robert Mak Tak-Law","avatar":""},{"name":"Ku Feng","avatar":""},{"name":"李擎柱","avatar":""},{"name":"Chu Tit-Wo","avatar":""},{"name":"Hsiao Ho","avatar":""},{"name":"Sek Gong","avatar":""},{"name":"Chow Siu-Loi","avatar":""},{"name":"Wong Ching-Ho","avatar":""},{"name":"Gam Tin-Chue","avatar":""},{"name":"Wang Han-Chen","avatar":""},{"name":"Ching Miao","avatar":""},{"name":"Lam Hak-Ming","avatar":""},{"name":"Lau Kar-leung","avatar":""},{"name":"Ting Tung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324550);
