INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('reds', 'Reds', 'Reds', 'https://phimimg.com/upload/vod/20240228-1/838ae2515d8bc209a36d350772b49734.jpg', 'https://phimimg.com/upload/vod/20240228-1/918c2185f37ad92d31fa98329d53f153.jpg', '<p>Tường thuật về những năm tháng cách mạng của nhà báo huyền thoại người Mỹ John Reed, người đã chia sẻ cuộc đời nghề nghiệp đầy phiêu lưu của mình với cam kết triệt để đối với cuộc cách mạng xã hội chủ nghĩa ở Nga, giấc mơ truyền bá các nguyên tắc của nó trong các thành viên của giai cấp công nhân Mỹ và mối tình lãng mạn đầy rắc rối của ông. mối quan hệ với nhà văn Louise Bryant.</p>', 'Full', 1, 'single', 'completed', 18, 1981, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Warren Beatty","avatar":""},{"name":"Diane Keaton","avatar":""},{"name":"Edward Herrmann","avatar":""},{"name":"Jerzy Kosiński","avatar":""},{"name":"Jack Nicholson","avatar":""},{"name":"Paul Sorvino","avatar":""},{"name":"Maureen Stapleton","avatar":""},{"name":"Nicolas Coster","avatar":""},{"name":"M. Emmet Walsh","avatar":""},{"name":"Ian Wolfe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
