INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-be-hat-tieu', 'Cô Bé Hạt Tiêu', 'Chie The Brat', 'https://phimimg.com/upload/vod/20240102-1/5139c37edec6dd25a355591ecda8c939.jpg', 'https://phimimg.com/upload/vod/20240102-1/e74368fb093fd6d75f174991fd5b92cf.jpg', '<p>Chie Takemoto là một cô gái đáng tin cậy, cố gắng giúp đỡ người cha rắc rối của mình điều hành một quán rượu nhỏ ở Osaka. Cha cô không hề hay biết, cô thỉnh thoảng đến thăm người mẹ đã bỏ ông cách đây không lâu. Cô ấy dự định cố gắng đoàn tụ họ, nhưng phải đến khi cha cô ấy kiếm được việc làm.</p>', 'Full', 1, 'hoathinh', 'completed', 17, 1981, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Chinatsu Nakayama","avatar":""},{"name":"Norio Nishikawa","avatar":""},{"name":"Kiyoshi Nishikawa","avatar":""},{"name":"Yasushi Yokoyama","avatar":""},{"name":"Shinsuke Shimada","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
