INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-nha-ke', 'Bạn Gái Nhà Kế', 'The Woman Next Door', 'https://phimimg.com/upload/vod/20231219-1/d25629a15e1a95b16ea18eebc6d66f10.jpg', 'https://phimimg.com/upload/vod/20231219-1/1fb69548889f1ce1ebc1f6fe8b07a51b.jpg', '<p>Bà Jouve, người kể chuyện, kể về bi kịch của Bernard và Mathilde. Bernard đang sống hạnh phúc với vợ Arlette và cậu con trai Thomas. Một ngày nọ, một cặp vợ chồng Philippe và Mathilde Bauchard chuyển đến ngôi nhà bên cạnh. Đây là cuộc hội ngộ tình cờ của Bernard và Mathilde, hai người đã có một mối tình say đắm nhiều năm trước. Mối quan hệ hồi sinh... Một nghiên cứu ảm đạm về cảm xúc của con người.</p>', 'Full', 1, 'single', 'completed', 17, 1981, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Gérard Depardieu","avatar":""},{"name":"Fanny Ardant","avatar":""},{"name":"Henri Garcin","avatar":""},{"name":"Michèle Baumgartner","avatar":""},{"name":"Roger Van Hool","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
