INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-su-tu-gia-tren-sa-mac', 'Con Sư Tử Già Trên Sa Mạc', 'Lion Of The Desert', 'https://phimimg.com/upload/vod/20231214-1/19e93b6070b1b207be9fd79eefbda43e.jpg', 'https://phimimg.com/upload/vod/20231214-1/afb31bdc0cda9d480deb0a46382d2161.jpg', '<p>Bộ phim này kể về câu chuyện của Omar Mukhtar, một phiến quân Hồi giáo Ả Rập đã chiến đấu chống lại cuộc xâm lược Libya của Ý trong Thế chiến thứ hai. Nó mang đến cho người xem phương Tây cái nhìn thoáng qua về khu vực và chương lịch sử ít được biết đến này, đồng thời vạch trần những phương tiện man rợ mà đội quân chinh phục đã cố gắng khuất phục người bản xứ.</p>', 'Full', 1, 'single', 'completed', 20, 1981, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anthony Quinn","avatar":""},{"name":"Rod Steiger","avatar":""},{"name":"Oliver Reed","avatar":""},{"name":"Irene Papas","avatar":""},{"name":"Raf Vallone","avatar":""},{"name":"John Gielgud","avatar":""},{"name":"Andrew Keir","avatar":""},{"name":"Gastone Moschin","avatar":""},{"name":"Stefano Patrizi","avatar":""},{"name":"Adolfo Lastretti","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
