INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-chuyen-nghiep', 'Tay Chuyên Nghiệp', 'The Professional', 'https://phimimg.com/upload/vod/20231212-1/f4e0f95976a4644141aec1a9d5e1487c.jpg', 'https://phimimg.com/upload/vod/20231212-1/d2ad3bbae61e19d2704da42cb29a4c2f.jpg', '<p>Đặc vụ mật vụ Pháp Josselin Beaumont được cử đi tiêu diệt lãnh chúa châu Phi NJala. Nhưng khi nhiệm vụ của anh ấy bị hủy bỏ, anh ấy bị sốc khi biết rằng chính phủ của anh ấy đang giao nộp anh ấy cho chính quyền địa phương. Anh ta bị đưa ra một phiên tòa giả và bị kết án 20 năm lao động khổ sai. Nhưng Beaumont trốn thoát khỏi nhà tù và thề không chỉ trả thù những kẻ phản bội mình mà còn hoàn thành nhiệm vụ ban đầu.</p>', 'Full', 1, 'single', 'completed', 19, 1981, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Jean-Paul Belmondo","avatar":""},{"name":"Robert Hossein","avatar":""},{"name":"Elisabeth Margoni","avatar":""},{"name":"Jean-Louis Richard","avatar":""},{"name":"Jean Desailly","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324550);
