INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('clash-of-the-titans', 'Clash of the Titans', 'Clash of the Titans', 'https://phimimg.com/upload/vod/20231206-1/ff165f1b4b7d742fc5ba2a62ed55201c.jpg', 'https://phimimg.com/upload/vod/20231206-1/0f21988b1613f8846602d3b5ed59f17b.jpg', '<p>Chuyện kể về người anh hùng Perseus, một á thần và là con trai của thần Zeus. Những người thân của chàng bị người chú là thần cai quản địa ngục Hades hãm hại, trong đó có cả người yêu là công chúa Andromeda. Không còn gì để mất, Perseus tình nguyện gánh vác một nhiệm vụ nguy hiểm: đánh bại thần Hades trước khi hắn cướp được quyền lực từ thần Zeus và biến trái đất thành địa ngục.</p>', 'Full', 1, 'single', 'completed', 18, 1981, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Harry Hamlin","avatar":""},{"name":"Laurence Olivier","avatar":""},{"name":"Claire Bloom","avatar":""},{"name":"Maggie Smith","avatar":""},{"name":"Jack Gwillim","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324550);
