INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('clash-of-the-titans', 'Clash of the Titans', 'Clash of the Titans', 'clash of the titans clash of the titans harry hamlin laurence olivier claire bloom maggie smith jack gwillim ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-gia-chi-tu', 'Phá Gia Chi Tử', 'The Prodigal Son', 'https://phimimg.com/upload/vod/20231206-1/8d161e47559082d52f3e53f9f8ae4675.jpg', 'https://phimimg.com/upload/vod/20231206-1/b81e0d7a5d0f774923d9805a1c6fcd4d.jpg', '<p>Liang Zan là con trai duy nhất của gia đình Liang, thích luyện tập wushu từ khi còn nhỏ. Để phát triển sở thích của mình, cha của Liang Zan đã thuê nhiều bậc thầy hàng đầu với số tiền khổng lồ để trao đổi các kỹ năng. Bị cha của Liang mua chuộc, tất cả các võ sư giả vờ bị đánh bại trong cuộc thi, vì vậy Liang Zan nghĩ rằng mình là người đứng đầu. Một ngày nọ, Liang gặp Liang Erdi và mất hút hoàn toàn. Sau đó Liang nhận ra kỹ năng thực sự của mình và nhận Erdi làm thầy của mình. Sau khi học tập chăm chỉ, Liang Zan trở về Phật Sơn và mở một phòng khám để giúp đỡ những người nghèo. Một ngày nọ, con trai nuôi Ni Fei của Hoàng thân đến thăm Liang Zan và có ý định cạnh tranh với ông. Điện hạ đã sắp xếp người để giết Liang Zan vì sợ con trai nuôi của ông ta sẽ bị thương.</p>', 'Full', 1, 'single', 'completed', 16, 1981, 'Vietsub', 'HD', 'Trung Quốc', 0, '[{"name":"Biao Yuen","avatar":""},{"name":"Lam Ching-ying","avatar":""},{"name":"Frankie","avatar":""},{"name":"Sammo Kam-Bo Hung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324550);
