INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-doc', 'Kẻ Đọc', 'Scanners', 'https://phimimg.com/upload/vod/20231201-1/b5714c836e9e52738cd1b5542f80e0db.jpg', 'https://phimimg.com/upload/vod/20231201-1/4b2d6f6f50f09b60f5e092978466c6be.jpg', '<p>Sau khi một người đàn ông có khả năng ngoại cảm phi thường — và có sức hủy diệt đáng sợ — bị bắt bởi các đặc vụ từ một tập đoàn lừa đảo bí ẩn, anh ta phát hiện ra mình không phải là người duy nhất sở hữu những sức mạnh kỳ lạ như vậy, và một số “máy quét” khác đã có tâm trí của họ. thống trị thế giới, trong khi những người khác đang cố gắng ngăn chặn chúng.</p>', 'Full', 1, 'single', 'completed', 19, 1981, 'Vietsub', 'HD', 'Canada', 0, '[{"name":"Jennifer O''Neill","avatar":""},{"name":"Stephen Lack","avatar":""},{"name":"Patrick McGoohan","avatar":""},{"name":"Lawrence Dane","avatar":""},{"name":"Michael Ironside","avatar":""},{"name":"Robert A. Silverman","avatar":""},{"name":"Lee Broker","avatar":""},{"name":"Mavor Moore","avatar":""},{"name":"Adam Ludwig","avatar":""},{"name":"Murray Cruchley","avatar":""},{"name":"Fred Döderlein","avatar":""},{"name":"Géza Kovács","avatar":""},{"name":"Sonny Forbes","avatar":""},{"name":"Jérôme Tiberghien","avatar":""},{"name":"Denis Lacroix","avatar":""},{"name":"Elizabeth Mudr","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324550);
