INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-doc', 'Kẻ Đọc', 'Scanners', 'kẻ đọc scanners jennifer o''neill stephen lack patrick mcgoohan lawrence dane michael ironside robert a. silverman lee broker mavor moore adam ludwig murray cruchley fred döderlein géza kovács sonny forbes jérôme tiberghien denis lacroix elizabeth mudr ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-tau-ngam-ban-dao-dien', 'Trận Chiến Tàu Ngầm: Bản Đạo Diễn', 'Das Boot: Director''s Cut', 'https://phimimg.com/upload/vod/20231124-1/c0610a49cbd1fbfef45f69628807bcb8.jpg', 'https://phimimg.com/upload/vod/20231124-1/496ee90ffe7385e9f249db15a6c5bd60.jpg', '<p>Có thể nói, Das Boot là một trong những bộ phim hành động đáng xem nhất từ trước tới nay. Thấm trong từng thước phim, chính là những cảm giác hồi hộp và lạnh sống lưng đầy căng thẳng mà đạo diễn Wolfgang Peterson đã dày công xây dựng. Khoác lên mình một phong cách đầy mới mẻ, Das Boot giống như một bộ phim tài liệu xoay quanh chuyến hải trình của con tàu U-96 cùng những thủy thủ trên nó. Bộ phim cung cấp một cái nhìn vô cùng thuyết phục về chiến tranh dưới những máu và nước mắt trải dài trong tác phẩm, cũng như tình người và tình đồng đội được gây dựng lên từ cuộc sống chật chội nơi một con tàu ngầm.</p>', 'Full', 1, 'single', 'completed', 22, 1981, 'Vietsub', 'HD', 'Đức', 0, '[{"name":"Jürgen Prochnow","avatar":""},{"name":"Herbert Grönemeyer","avatar":""},{"name":"Klaus Wennemann","avatar":""},{"name":"Hubertus Bengsch","avatar":""},{"name":"Martin Semmelrogge","avatar":""},{"name":"Bernd Tauber","avatar":""},{"name":"Erwin Leder","avatar":""},{"name":"Martin May","avatar":""},{"name":"Heinz Hoenig","avatar":""},{"name":"Uwe Ochsenknecht","avatar":""},{"name":"Claude-Oliver Rudolph","avatar":""},{"name":"Jan Fedder","avatar":""},{"name":"Rita Cadillac","avatar":""},{"name":"Ralf Richter","avatar":""},{"name":"Joachim Bernhard","avatar":""},{"name":"Oliver Str","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '[]', 1784690324550);
