INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xung-dot-cuoi-cung', 'Xung Đột Cuối Cùng', 'Omen III: The Final Conflict', 'https://phimimg.com/upload/vod/20231114-1/619f70b513f1aa3d102cf16056e63b29.jpg', 'https://phimimg.com/upload/vod/20231114-1/99714e73475b2348c51b8656cca83123.jpg', '<p>Damien Thorn đã giúp giải cứu thế giới khỏi suy thoái kinh tế, dường như là một nhà hảo tâm lành tính của công ty. Sau đó, khi trở thành Đại sứ Hoa Kỳ tại Vương quốc Anh, Damien đã ứng nghiệm một lời tiên tri đáng sợ trong Kinh thánh. Anh ta cũng phải đối mặt với cái chết có thể xảy ra của chính mình khi một sự kiện thiên văn mang đến sự tái lâm của Chúa Kitô.</p>', 'Full', 1, 'single', 'completed', 15, 1981, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Sam Neill","avatar":""},{"name":"Rossano Brazzi","avatar":""},{"name":"Don Gordon","avatar":""},{"name":"Lisa Harrow","avatar":""},{"name":"Barnaby Holm","avatar":""},{"name":"Mason Adams","avatar":""},{"name":"Robert Arden","avatar":""},{"name":"Leueen Willoughby","avatar":""},{"name":"Marc Boyle","avatar":""},{"name":"Milos Kirek","avatar":""},{"name":"Tommy Duggan","avatar":""},{"name":"Louis Mahoney","avatar":""},{"name":"Richard Oldfield","avatar":""},{"name":"Tony Vogel","avatar":""},{"name":"Arwen Holm","avatar":""},{"name":"Hugh Moxey","avatar":""},{"name":"William Fox","avatar":""},{"name":"John Baskcomb","avatar":""},{"name":"Norman","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324550);
