INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-007-rieng-cho-doi-mat-em', 'Điệp Viên 007: Riêng Cho Đôi Mắt Em', 'For Your Eyes Only', 'https://phimimg.com/upload/vod/20231111-1/2398c3eac87023d03ce4c3400e21c901.jpg', 'https://phimimg.com/upload/vod/20231111-1/4f095f200e36178374f70204df77b620.jpg', '<p>Một chiếc tàu đánh cá trá hình của Anh đã bị tai nạn. Trên tàu có một thiết bị giải mã tiên tiến được gọi là ATAC, cái mà người Anh sử dụng để truyền tín hiệu cho hạm đội Polaris của họ. Người Anh đã cử James Bond đến để điều tra nhưng một khi quân Soviets biết được mất mát này của người Anh, chúng sẽ lợi dụng để phát động tấn công. Vì vậy, việc lấy lại cỗ máy là việc phải làm bằng mọi giá...</p>', 'Full', 1, 'single', 'completed', 15, 1981, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Roger Moore","avatar":""},{"name":"Carole Bouquet","avatar":""},{"name":"Topol","avatar":""},{"name":"Julian Glover","avatar":""},{"name":"Lynn-Holly Johnson","avatar":""},{"name":"Cassandra Harris","avatar":""},{"name":"Jill Bennett","avatar":""},{"name":"Michael Gothard","avatar":""},{"name":"John Wyman","avatar":""},{"name":"Jack Hedley","avatar":""},{"name":"Lois Maxwell","avatar":""},{"name":"Desmond Llewelyn","avatar":""},{"name":"Geoffrey Keen","avatar":""},{"name":"Walter Gotell","avatar":""},{"name":"James Villiers","avatar":""},{"name":"John Moreno","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Paul","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324550);
