INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiem-huu-linh-hon', 'Chiếm Hữu Linh Hồn', 'Possession', 'https://phimimg.com/upload/vod/20231026-1/2d009e9f83d9ca9a31a48c5fa3744dda.jpg', 'https://phimimg.com/upload/vod/20231026-1/85701c5d5ee641149d465135d9f34d61.jpg', '<p>Phim xoay quanh cuộc sống hôn nhân giữa cặp với chồng Mark và Anna. Hai người có những năm tháng hạnh phúc và đứa con đáng yêu Bob minh chứng cho điều đó. Một ngày nọ, Anna đòi ly hôn sau chuyến công tác xa dài ngày của chồng.</p>', 'Full', 1, 'single', 'completed', 21, 1981, 'Vietsub', 'HD', 'Pháp', 0, '[{"name":"Isabelle Adjani","avatar":""},{"name":"Sam Neill","avatar":""},{"name":"Margit Carstensen","avatar":""},{"name":"Heinz Bennent","avatar":""},{"name":"Johanna Hofer","avatar":""},{"name":"Carl Duering","avatar":""},{"name":"Shaun Lawton","avatar":""},{"name":"Michael Hogben","avatar":""},{"name":"Maximilian Rüthlein","avatar":""},{"name":"Leslie Malton","avatar":""},{"name":"Thomas Frey","avatar":""},{"name":"Harry Riebauer","avatar":""},{"name":"Dragomir Stanojević","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324550);
