INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-soi-my-o-london', 'Người Sói Mỹ ở London', 'An American Werewolf in London', 'https://phimimg.com/upload/vod/20231022-1/4e7b27ed644b58db0af5d84fd645a969.jpg', 'https://phimimg.com/upload/vod/20231022-1/6a2c302159bb5f0280acbd3dfe3256ee.jpg', '<p>Câu chuyện bắt đầu khi 2 thanh niên người Mỹ chuyển đến London và trên đường đi bộ trên đất trống họ tìm thấy quán rượu &quot;Con Cừu Bị Thịt&quot;, gặp những người rất kỳ quặc với ngôi sao vẽ trên tường với 2 đèn cầy và khi Jack hỏi về cái đó thì những người trong quán có phản ứng rất đáng sợ và đuổi 2 người ra khỏi quán rồi nói 1 câu kỳ lạ &quot;Cẩn Thận Mặt Trăng&quot;.</p>', 'Full', 1, 'single', 'completed', 16, 1981, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"David Naughton","avatar":""},{"name":"Jenny Agutter","avatar":""},{"name":"Griffin Dunne","avatar":""},{"name":"John Woodvine","avatar":""},{"name":"Don McKillop","avatar":""},{"name":"Brian Glover","avatar":""},{"name":"David Schofield","avatar":""},{"name":"Lila Kaye","avatar":""},{"name":"Rik Mayall","avatar":""},{"name":"Sean Baker","avatar":""},{"name":"Frank Oz","avatar":""},{"name":"Paul Kember","avatar":""},{"name":"Joe Belcher","avatar":""},{"name":"Paddy Ryan","avatar":""},{"name":"Anne-Marie Davies","avatar":""},{"name":"Colin Fernandes","avatar":""},{"name":"Albert Moses","avatar":""},{"name":"Jim Henson","avatar":""},{"name":"Dave","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324550);
