INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('max-dien-2', 'Max Điên 2', 'Mad Max 2', 'https://phimimg.com/upload/vod/20231023-1/c465c9327f492a0868592460ad7f7679.jpg', 'https://phimimg.com/upload/vod/20231023-1/5e05b913fdbcf0d6a92cf1d47a4153a2.jpg', '<p>Max Rockatansky trở lại với tư cách là người anh hùng cô độc lái xe trên những con đường bụi bặm ở vùng hẻo lánh của Úc thời hậu tận thế trong cuộc tìm kiếm xăng không ngừng nghỉ. Dàn trận chống lại anh ta và những bị cáo xấu xa khác của một kho chứa nhiên liệu là những chiến binh kỳ quái được chỉ huy bởi Chúa tể Humungus lôi cuốn, một nhà lãnh đạo bạo lực có sự cẩn trọng cũng cằn cỗi như cảnh quan xung quanh.</p>', 'Full', 1, 'single', 'completed', 16, 1981, 'Vietsub', 'HD', 'Úc', 0, '[{"name":"Mel Gibson","avatar":""},{"name":"Bruce Spence","avatar":""},{"name":"Michael Preston","avatar":""},{"name":"Max Phipps","avatar":""},{"name":"Vernon Wells","avatar":""},{"name":"Kjell Nilsson","avatar":""},{"name":"Emil Minty","avatar":""},{"name":"Virginia Hey","avatar":""},{"name":"William Zappa","avatar":""},{"name":"Arkie Whiteley","avatar":""},{"name":"Steve J. Spears","avatar":""},{"name":"Syd Heylen","avatar":""},{"name":"Moira Claux","avatar":""},{"name":"David Downer","avatar":""},{"name":"Kristoffer Greaves","avatar":""},{"name":"Max Fairchild","avatar":""},{"name":"Tyler Coppin","avatar":""},{"name":"David Sli","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324550);
