INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('max-dien-2', 'Max Điên 2', 'Mad Max 2', 'max điên 2 mad max 2 mel gibson bruce spence michael preston max phipps vernon wells kjell nilsson emil minty virginia hey william zappa arkie whiteley steve j. spears syd heylen moira claux david downer kristoffer greaves max fairchild tyler coppin david sli ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chay-tron-khoi-new-york', 'Chạy Trốn Khỏi New York', 'Escape from New York', 'https://phimimg.com/upload/vod/20231016-1/7135308f96d974e54bf4d3e5ecf79100.jpg', 'https://phimimg.com/upload/vod/20231016-1/f6b328c640c454686e52889a29a33125.jpg', '<p>Đây là bộ phim khoa học giả tưởng mang phong cách hành động, lấy bối cảnh tương lai gần về một nước Mỹ tội phạm lan tràn và khu Manhattan của New York biến thành một nhà tù khổng lồ có an ninh cực kỳ nghiêm ngặt. Trong khi đó, chiếc chuyên cơ Air Force One chở tổng thống Mỹ (do Donald Pleasence đóng) đâm xuống Manhattan và ông bị những tù nhân bắt cóc. Một cựu binh huyền thoại là Snake Plissken được cử đến với sứ mệnh trong 24 giờ phải tìm và cứu được tổng thống. Cảnh đáng nhớ nhất trong bộ phim này là khi một tên bắt cóc trưng ra chiếc nhẫn của tổng thống, trên đó vẫn còn nguyên ngón tay của ông để chứng tỏ chúng đang giữ ông chủ Nhà Trắng.</p>', 'Full', 1, 'single', 'completed', 18, 1981, 'Vietsub', 'HD', 'Anh', 0, '[{"name":"Kurt Russell","avatar":""},{"name":"Lee Van Cleef","avatar":""},{"name":"Ernest Borgnine","avatar":""},{"name":"Donald Pleasence","avatar":""},{"name":"Isaac Hayes","avatar":""},{"name":"Season Hubley","avatar":""},{"name":"Harry Dean Stanton","avatar":""},{"name":"Adrienne Barbeau","avatar":""},{"name":"Tom Atkins","avatar":""},{"name":"Charles Cyphers","avatar":""},{"name":"Frank Doubleday","avatar":""},{"name":"John Strobel","avatar":""},{"name":"George Buck Flower","avatar":""},{"name":"John Cothran","avatar":""},{"name":"Nancy Stephens","avatar":""},{"name":"Steven Ford","avatar":""},{"name":"Jo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324550);
