INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chay-tron-khoi-new-york', 'Chạy Trốn Khỏi New York', 'Escape from New York', 'chạy trốn khỏi new york escape from new york kurt russell lee van cleef ernest borgnine donald pleasence isaac hayes season hubley harry dean stanton adrienne barbeau tom atkins charles cyphers frank doubleday john strobel george buck flower john cothran nancy stephens steven ford jo ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chung-am-thanh', 'Bằng Chứng Âm Thanh', 'Blow Out', 'https://phimimg.com/upload/vod/20231016-1/a7840e0ab62fa17396b327013759eb3e.jpg', 'https://phimimg.com/upload/vod/20231016-1/a29da7b9d4726a6a7153dc90fc370a35.jpg', '<p>Trong khi đang thu âm tại một công viên để làm hậu kỳ cho một bộ phim thể loại slasher (chém giết) kinh phí thấp, kỹ thuật viên âm thanh người Philadelphia Jack Terry (John Travolta) nhìn thấy một chiếc xe hơi lao ra khỏi đường và lao xuống hồ gần đó. Jack đã cứu được một phụ nữ trẻ, Sally (Nancy Allen ) và đưa cô đến bệnh viện. Sau đó anh mới biết trên xe còn một người đàn ông nữa đã chết, một nhân vật có tên tuổi, ứng cử viên Tổng thống và là Thống đốc đương nhiệm George McRyan. Bằng kinh nghiệm của một chuyên gia âm thanh khi nghe lại đoạn băng ghi âm, cộng thêm khi chứng kiến các thế lực bí ẩn tìm cách hủy bằng chứng, loại bỏ nhân chứng là cô gái Sally, Jack biết rằng đây không chỉ là một vụ tai nạn đơn thuần mà là một vụ án mạng, một âm mưu bẩn thỉu...</p>', 'Full', 1, 'single', 'completed', 13, 1981, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"John Travolta","avatar":""},{"name":"Nancy Allen","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Dennis Franz","avatar":""},{"name":"Peter Boyden","avatar":""},{"name":"John Aquino","avatar":""},{"name":"John McMartin","avatar":""},{"name":"Deborah Everton","avatar":""},{"name":"J. Patrick McNamara","avatar":""},{"name":"Roger Wilson","avatar":""},{"name":"Missy Cleveland","avatar":""},{"name":"Curt May","avatar":""},{"name":"Lori-Nan Engler","avatar":""},{"name":"Barbara Sigel","avatar":""},{"name":"David De Felice","avatar":""},{"name":"Roberto Lombardi","avatar":""},{"name":"Missy Crutc","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324550);
