INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cao-va-cho-san', 'Cáo và Chó Săn', 'The Fox and the Hound', 'https://phimimg.com/upload/vod/20231015-1/bd5d5fd4208be2f67e2c5c637bd9153d.jpg', 'https://phimimg.com/upload/vod/20231015-1/9bf48d696166fa94c48178ae50a60016.jpg', '<p>Một bộ phim hoạt hình kể về tình bạn giữa một con cáo và một con chó săn. Một trong những bộ phim hoạt hình hiếm hoi mang lại cảm giác buồn và sâu lắng của Walt Disney.</p>', 'Full', 1, 'hoathinh', 'completed', 19, 1981, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mickey Rooney","avatar":""},{"name":"Kurt Russell","avatar":""},{"name":"Pearl Bailey","avatar":""},{"name":"Jack Albertson","avatar":""},{"name":"Sandy Duncan","avatar":""},{"name":"Jeanette Nolan","avatar":""},{"name":"Pat Buttram","avatar":""},{"name":"John Fiedler","avatar":""},{"name":"John McIntire","avatar":""},{"name":"Richard Bakalyan","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324550);
