INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-si-tan-thoi', 'Vệ Sĩ Tân Thời', 'Security Unlimited', 'https://phimimg.com/upload/vod/20231009-1/af6a4bbefbdb85b1103bf297c84eee3b.jpg', 'https://phimimg.com/upload/vod/20231009-1/4cd555b322d0270bcf363ba311ac0dd5.jpg', '<p>Đây là câu chuyện về một cơ quan bảo vệ và ba đặc vụ của nó - Michael, Sam và Ricky. Sam và Ricky đang giao một số tiền lớn cho ngân hàng thì một vụ cướp xảy ra ngay trước mắt họ. sau một loạt những cuộc rượt đuổi vui nhộn dựng tóc gáy, các đặc vụ đã có được người của mình. Với việc Michael và Sam đưa tiền thưởng cho Ricky. Họ sống một cách bừa bãi mãi mãi về sau.</p>', 'Full', 1, 'single', 'completed', 21, 1981, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Michael Hui","avatar":""},{"name":"Ricky Hui","avatar":""},{"name":"Sam Hui","avatar":""},{"name":"Marylinn Wong Cho-Shut","avatar":""},{"name":"Stanley Fung","avatar":""},{"name":"Chan Sing","avatar":""},{"name":"Lee Hoi-Sang","avatar":""},{"name":"David Cheung","avatar":""},{"name":"Yue Tau-Wan","avatar":""},{"name":"Kobe Wong Kam-Bo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324550);
