INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dang-sau-cong-tu-vien', 'Đằng sau cổng tu viện', 'The True Story of the Nun of Monza', 'https://phimimg.com/upload/vod/20250614-1/6d4e3c0df86c4abdbc5c64d6d1c6dae7.jpg', 'https://phimimg.com/upload/vod/20250614-1/6698157d21393e0523cff88e22d24311.jpg', '<p>Sơ Virginia de Leyva trở thành Mẹ Bề trên mới tại tu viện Monza. Tu viện nói trên hóa ra lại là một cái nôi thực sự của tội lỗi xác thịt và sự trụy lạc. Linh mục sa đọa Don Arrigone và kẻ lăng nhăng dâm đãng Giampaolo Osio âm mưu quyến rũ em gái Virginia. Nhưng liệu những hành động gian ác và dâm đãng của họ có tiếp tục không bị phát hiện?</p>', 'Full', 1, 'single', 'completed', 22, 1980, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Zora Kerova","avatar":""},{"name":"Mario Cutini","avatar":""},{"name":"Paola Corazzi","avatar":""},{"name":"Annie Carol Edel","avatar":""},{"name":"Franco Garofalo","avatar":""},{"name":"Paola Montenero","avatar":""},{"name":"Mario Novelli","avatar":""},{"name":"Ornella Picozzi","avatar":""},{"name":"Leda Simonetti","avatar":""},{"name":"Franca Stoppi","avatar":""},{"name":"Andrea Aureli","avatar":""},{"name":"Tom Felleghy","avatar":""},{"name":"Giovanni Attanasio","avatar":""},{"name":"Andrea Aureli","avatar":""},{"name":"Alba Maiolini","avatar":""},{"name":"Fabio Spaltro","avatar":""},{"name":"Fern","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Libertine Novices","Novices Libertines","Voeux de sang","Vœux de sang","A Monja de Monza","尼僧の背徳","La vera storia della monaca di Monza"]', 1784690324550);
