INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-chu-khung-long-cua-nobita-1980', 'Doraemon: Chú Khủng Long của Nobita', 'Doraemon: Nobita''s Dinosaur', 'https://phimimg.com/upload/vod/20250521-1/5b008784524673a896c15f714bcf4473.jpg', 'https://phimimg.com/upload/vod/20250521-1/07159b5a9e23175ea48fdddae396d057.jpg', '<p>Nobita tình cờ tìm được một quả trứng khủng long hóa thạch, Nobita đã dùng bảo bối &quot;Khăn trùm thời gian&quot; đưa quả trứng trở về thời điểm 100 triệu năm trước và ấp cho trứng nở. Nỗ lực của cậu đã thành công khi loài bò sát thuộc chi Futabasaurus chào đời, được Nobita đặt tên là Pīsuke. Nobita và Doraemon bí mật chăm sóc Pīsuke đến khi trưởng thành, tình bạn giữa cậu và khủng long cũng được vun đắp theo thời gian. Đến khi Pīsuke không thể sống vừa trong nhà nữa, Nobita nuôi khủng long ở hồ nước trong công viên, không may cư dân thành phố phát hiện ra và tiến hành khảo cứu; Nobita và Doraemon buộc phải thả Pīsuke về lại quê hương ở thời kỳ Creta muộn khoảng 100 triệu năm trước.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 1980, 'Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuyo Oyama","avatar":""},{"name":"Noriko Ohara","avatar":""},{"name":"Michiko Nomura","avatar":""},{"name":"Kaneta Kimotsuki","avatar":""},{"name":"Kazuya Tatekabe","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["โดเรม่อนผจญไดโนเสา","Doraemon Nobita no Kyoryu","ドラえもん のび太の恐竜","大雄的小恐龍",