INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('den-thuong-de-cung-phai-cuoi', 'Đến Thượng Đế Cũng Phải Cười', 'The Gods Must Be Crazy', 'đến thượng đế cũng phải cười the gods must be crazy marius weyers sandra prinsloo n!xau louw verwey michael thys nic de jager fanyana h. sidumo joe seakatsie brian o''shaughnessy ken gampu paddy o''byrne graham armitage vera blacker katinka heyns janet meshad jamie uys los dioses deben estar locos 众神也疯狂 (上) боговете сигурно са полудели los dioses deben estar locos боги, наверное, сошли с ума os deuses devem estar loucos 부시맨 เทวดาท่าจะบ๊องส์ les dieux sont tombés sur la tête כולם נפלו על הראש zijn de goden gek? bohovia sa museli zblázniť bohové musejí být sílení az istenek a fejükre estek ミラクル・ワールド ブッシュマン богови су пали на теме gudarna måste vara tokiga 上帝也瘋狂 мабуть боги з''їхали з глузду đến thượng đế cũng phải cười tanrılar çıldırmış olmalı the gods must be crazy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-dau', 'Chị Dậu', 'Dau Sister', 'https://phimimg.com/upload/vod/20250428-1/7a658f52b5148cbec9e8b1205735c59f.jpg', 'https://phimimg.com/upload/vod/20250428-1/e67caa14e4657fa94d20c040bacab318.jpg', '<p>Chị Dậu là một tác phẩm điện ảnh kinh điển của Việt Nam, được chuyển thể từ tiểu thuyết Tắt Đèn của nhà văn Ngô Tất Tố. Lấy bối cảnh xã hội dưới thời thực dân phong kiến, phim kể về một người phụ nữ nông dân nghèo phải vùng lên để bảo vệ chồng con và danh dự của mình. Khi chồng bị bắt vì không nộp đủ sưu thuế, chị Dậu phải bán con, bán chó để cứu chồng và cuối cùng bị đẩy vào bước đường cùng. Từ thân phận một người vợ, người mẹ, chị dần trở thành biểu tượng của tinh thần phản kháng và khát vọng sống mãnh liệt.</p>', 'Full', 1, 'single', 'completed', 16, 1980, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Kim Lân","avatar":""},{"name":"Lê Vân","avatar":""},{"name":"Nguyễn Anh Thái","avatar":""},{"name":"Nguyễn Tuân","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
