INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-nha-nho-tren-thao-nguyen-phan-7', 'Ngôi Nhà Nhỏ Trên Thảo Nguyên (Phần 7)', 'Little House On The Prairie (Season 7)', 'ngôi nhà nhỏ trên thảo nguyên (phần 7) little house on the prairie (season 7) melissa gilbert dean butler karen grassle katherine macgregor melissa sue anderson richard bull victor french jonathan gilbert allison balson lindsay kennedy ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-thieu-lam-tam-thap-luc-phong', 'Trở Lại Thiếu Lâm Tam Thập Lục Phòng', 'Return to the 36th Chamber', 'https://phimimg.com/upload/vod/20240802-1/00bf002dedaed95b36299e33eac5fa6b.jpg', 'https://phimimg.com/upload/vod/20240802-1/2751980da6969dc7a42370d7e0cafacc.jpg', '<p>Các công nhân của một nhà máy nhuộm bị cắt 20% lương khi chủ nhà máy đưa một số côn đồ người Mãn Châu đến để cố gắng tăng sản lượng. Tuyệt vọng đòi lại toàn bộ số tiền lương của mình, các công nhân đã thuê một diễn viên đóng giả một linh mục và chuyên gia kung-fu từ chùa Thiếu Lâm. Chủ nhà máy chứng minh diễn viên lừa đảo và trừng phạt tất cả những người liên quan. Nam diễn viên trẻ cảm thấy mình đã khiến người lao động thất vọng và hứa sẽ chuộc lỗi. Anh lên đường đến Thiếu Lâm, quyết tâm được nhận làm học trò kung-fu tại ngôi chùa ưu tú.</p>', 'Full', 1, 'single', 'completed', 19, 1980, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Gordon Liu Chia-hui","avatar":""},{"name":"惠英紅","avatar":""},{"name":"Hsiao Ho","avatar":""},{"name":"Wong Ching-Ho","avatar":""},{"name":"Wa Lun","avatar":""},{"name":"李擎柱","avatar":""},{"name":"Yau Chui-Ling","avatar":""},{"name":"陳思佳","avatar":""},{"name":"Sek Gong","avatar":""},{"name":"Best Kwon Yeong-Moon","avatar":""},{"name":"Yeung Ching-Ching","avatar":""},{"name":"Johnny Wang Lung-Wei","avatar":""},{"name":"Chiang Tao","avatar":""},{"name":"Jang Il-Do","avatar":""},{"name":"San Sin","avatar":""},{"name":"Jackson Ng Yuk-Sue","avatar":""},{"name":"Kim Se-Ok","avatar":""},{"name":"Cheung Chok-Chow","avatar":""},{"name":"Lam Hak-Ming","avatar":""},{"name":"Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324550);
