INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-lam-nhat-tuyet-ly-biet-cau', 'Võ Lâm Nhất Tuyệt (Ly Biệt Câu)', 'In Search Of', 'https://phimimg.com/upload/vod/20240611-1/9d82e81ab965518daedf49125caf9149.jpg', 'https://phimimg.com/upload/vod/20240611-1/51152a4e870fc79561842ab354d92983.jpg', '<p>Dịch phu nhân (Nam Hồng) bị ép gả vào Dịch Vương Phủ và thường bị hành hạ. Hiệp đạo Dương Hận (Lưu Đan) vào phủ hành thích bị thương may được Dịch phu nhân cứu vớt, hai người nảy sinh tình cảm. Khi Dịch vương Gia xuất chinh trở về và biết được bà đã sinh ra một sông bảo, ông tức giận và nhốt bà vào ngục. Hai mươi năm sau khi sông bảo này lớn lên. Dương Tranh (Huỳnh Thụ Đường) trở thành một danh bộ võ công cao cường. Dịch Thanh Lan (Tạ Hiền) thừa kế vương vị, vì muốn che dấu xuất thân và bị thiên long bang lợi dụng khiến hai anh em sinh đôi trở thành kẻ thù ...</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 24, 1980, 'Lồng Tiếng', 'HD', 'Hồng Kông', 0, '[{"name":"Patrick Tse Yin","avatar":""},{"name":"Deborah Lee","avatar":""},{"name":"Wong Shu-Tong","avatar":""},{"name":"Lisa Lui Yau-Wai","avatar":""},{"name":"Nam Hung","avatar":""},{"name":"Lau Dan","avatar":""},{"name":"Chun Wong","avatar":""},{"name":"Ronna Ko","avatar":""},{"name":"Lam Wai-Tiu","avatar":""},{"name":"Lau Siu-Ming","avatar":""},{"name":"Wong Chi-Wai","avatar":""},{"name":"Chow Chung","avatar":""},{"name":"Cheng Lai-Fong","avatar":""},{"name":"Chan Yau-Hau","avatar":""},{"name":"Helena Law Lan","avatar":""},{"name":"Cho Chai","avatar":""},{"name":"Kam Hing-Yin","avatar":""},{"name":"Wong San","avatar":""},{"name":"Chan Pak-Cheung","avatar":""},{"name":"Ko","avatar":""}]', '[{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324550);
