INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nghia-giang-ho', 'Tình Nghĩa Giang Hồ', 'Invincible Medic', 'https://phimimg.com/upload/vod/20240611-1/c447a47071a29455845bc4016e8438b0.jpg', 'https://phimimg.com/upload/vod/20240611-1/5b8ef860d57b4ab8079988c906ac48d7.jpg', '<p>Tình Nghĩa Giang Hồ, The Invincible Medic xoay quanh về Tất Chánh xuất thân từ 1 nhà giàu, võ công cao cường, nhưng tính tình lương thiện, thấy chém giết là căm ghét, nên đã tế thế cứu dân nên đã chuyển sang học y để cứu các người dân trong 1 thị trấn nhỏ là Hẽm Phố Nhân, và chiêu mộ được các trợ thủ có ý chí giúp dân. Tất Chánh ngoài việc cứu dân mà còn giúp họ giải quyết những khó khăn cho nên người dân trong hẻm rất tôn trọng ông.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 22, 1980, 'Lồng Tiếng', 'HD', 'Trung Quốc', 0, '[{"name":"Thạch Tú","avatar":""},{"name":"Cảnh Đại Âm","avatar":""},{"name":"Châu Tú Lan","avatar":""},{"name":"Lý Lâm Lâm","avatar":""},{"name":"Liêu Khải Trí","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
