INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-ma', 'Ngôi Nhà Ma', 'The Shining', 'https://phimimg.com/upload/vod/20240227-1/c1db33966aa34e1d721fdabb5139f460.jpg', 'https://phimimg.com/upload/vod/20240227-1/25295f83d44feeb6b0bedb6b0e8d269c.jpg', '<p>Jack Torrance tìm việc trông coi khách sạn Overlook, trên dãy núi Colorado và cả gia đình ông đã chuyển tới sống ở đây. Do nơi này bị đóng cửa trong suốt mùa đông, vì thế chỉ có gia đình của Jack Torrance sống ở đây trong một thời gian dài. Sau đó, một cơn bão tuyết ập xuống và khiến gia đình ông bị kẹt lại bên trong khách sạn. Danny - con trai của Torrance, một cậu bé có khả năng thần giao cách cảm và có thể nhìn thấy những việc trong quá khứ cũng như trong tương lai. Cậu bé phát hiện ra rằng rằng khách sạn này đang bị ma ám và hồn ma đó đang dần biến cha của cậu thành một kẻ hung ác...</p>', 'Full', 1, 'single', 'completed', 16, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jack Nicholson","avatar":""},{"name":"Shelley Duvall","avatar":""},{"name":"Scatman Crothers","avatar":""},{"name":"Danny Lloyd","avatar":""},{"name":"Barry Nelson","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324550);
