INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-2', 'Siêu Nhân 2', 'Superman II', 'https://phimimg.com/upload/vod/20240128-1/5344b9fd1a0f156886deb65e7a7e4a75.jpg', 'https://phimimg.com/upload/vod/20240128-1/50f5b38f2f3603d40653e3d6a8e55b46.jpg', '<p>Ba tên tội phạm trốn thoát khỏi hành tinh Krypton kiểm tra dũng khí của Người đàn ông thép. Dưới sự lãnh đạo của Tướng quân Zod, người Kryptonians nắm quyền kiểm soát Nhà Trắng và hợp tác với Lex Luthor để tiêu diệt Siêu nhân và thống trị thế giới. Nhưng Superman, người cố gắng biến mình thành con người để đến gần Lois hơn, nhận ra mình có trách nhiệm cứu hành tinh.</p>', 'Full', 1, 'single', 'completed', 14, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Margot Kidder","avatar":""},{"name":"Christopher Reeve","avatar":""},{"name":"Gene Hackman","avatar":""},{"name":"Ned Beatty","avatar":""},{"name":"Jackie Cooper","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324550);
