INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-toc-an-thit-nguoi', 'Bộ Tộc Ăn Thịt Người', 'Cannibal Holocaust', 'https://phimimg.com/upload/vod/20240121-1/2ddf86443ba11a9691c6f0123b56f2af.jpg', 'https://phimimg.com/upload/vod/20240121-1/434f022c5a23882f2a12167b40239ecb.jpg', '<p>Một giáo sư Đại học New York trở về sau nhiệm vụ giải cứu rừng nhiệt đới Amazon với đoạn phim được quay bởi một nhóm phóng viên tài liệu bị mất tích đang làm phim về các bộ lạc ăn thịt người địa phương trong khu vực.</p>', 'Full', 1, 'single', 'completed', 15, 1980, 'Vietsub', 'HD', 'Ý', 0, '[{"name":"Robert Kerman","avatar":""},{"name":"Perry Pirkanen","avatar":""},{"name":"Salvatore Basile","avatar":""},{"name":"Luca Barbareschi","avatar":""},{"name":"Francesca Ciardi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324550);
