INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-bao-cao-cap', 'Trai Bao Cao Cấp', 'American Gigolo', 'https://phimimg.com/upload/vod/20240111-1/f8c0c5cb9b2f799c77b924eb8d3a6b7a.jpg', 'https://phimimg.com/upload/vod/20240111-1/21d45bf72a3a2622edfd4c99b2c46f5f.jpg', '<p>Julian kiếm sống béo bở bằng nghề hộ tống những phụ nữ lớn tuổi ở khu vực Los Angeles. Anh ta bắt đầu mối quan hệ với Michelle, vợ của một chính trị gia địa phương, mà không mong đợi bất kỳ khoản tiền nào. Một trong những khách hàng của anh ta bị sát hại và Thám tử Sunday bắt đầu cung cấp cho anh ta thông tin chi tiết về các khách hàng khác nhau của anh ta, điều mà anh ta miễn cưỡng làm vì tính chất công việc của mình. Julian bắt đầu nghi ngờ mình bị gài bẫy. Trong khi đó Michelle bắt đầu yêu anh ta.</p>', 'Full', 1, 'single', 'completed', 15, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Richard Gere","avatar":""},{"name":"Lauren Hutton","avatar":""},{"name":"Hector Elizondo","avatar":""},{"name":"K Callan","avatar":""},{"name":"Carole Cook","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324550);
