INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-tham-hoa', 'Chuyến Bay Thảm Họa', 'Airplane!', 'https://phimimg.com/upload/vod/20240104-1/ea286e30d3e1321cb20927094c84624f.jpg', 'https://phimimg.com/upload/vod/20240104-1/bda8681c7a962d5c42341b1f328d237b.jpg', '<p>Những con người và sự kiện trong phim này là hư cấu - thật may mắn! Một kiệt tác hài kịch độc đáo, Máy bay! có Robert Hays trong vai một cựu phi công máy bay chiến đấu bị buộc phải tiếp nhận quyền điều khiển một chiếc máy bay khi tổ bay không chịu nổi ngộ độc thực phẩm; Julie Hagerty trong vai bạn gái / tiếp viên / phi công phụ của anh ấy; và dàn diễn viên toàn sao bao gồm Robert Stack, Lloyd Bridges, Peter Graves, Leslie Nielsen, Kareem Abdul-Jabbar ... và nhiều hơn nữa. Những pha nhảy cao vui nhộn của họ giả mạo các bộ phim về thảm họa máy bay, sự cuồng nhiệt của tôn giáo, quảng cáo trên truyền hình, tình yêu lãng mạn ... danh sách này liên tiếp quay cuồng. Và câu chuyện chạy từ khoảnh khắc thú vị này sang khoảnh khắc thú vị tiếp theo.</p>', 'Full', 1, 'single', 'completed', 16, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Hays","avatar":""},{"name":"Julie Hagerty","avatar":""},{"name":"Leslie Nielsen","avatar":""},{"name":"Kareem Abdul-Jabbar","avatar":""},{"name":"Lloyd Bridges","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324550);
