INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-duc-noi-dien', 'Bò Đực Nổi Điên', 'Raging Bull', 'https://phimimg.com/upload/vod/20231211-1/9e2a0796b709b6418cf9b4c20b4e3ee1.jpg', 'https://phimimg.com/upload/vod/20231211-1/54d17a0df33c207e79bf4608a28e432f.jpg', '<p>Cuộc đời của võ sĩ quyền anh Jake LaMotta, người mà sự bạo lực và nóng nảy đã đưa anh ta lên đỉnh cao trên võ đài đã phá hủy cuộc sống của anh ta bên ngoài nó.</p>', 'Full', 1, 'single', 'completed', 15, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert De Niro","avatar":""},{"name":"Joe Pesci","avatar":""},{"name":"Cathy Moriarty","avatar":""},{"name":"Frank Vincent","avatar":""},{"name":"Nicholas Colasanto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
