INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-voi', 'Người Voi', 'The Elephant Man', 'https://phimimg.com/upload/vod/20231208-1/5a06595d74e7d48e1a884058bd5d736c.jpg', 'https://phimimg.com/upload/vod/20231208-1/829cc7d2715002d36a709f2d240cd0b6.jpg', '<p>Bộ phim là một câu chuyện có thật về một người đàn ông có khuôn mặt bị biến dạng hoàn toàn và một cơ thể tàn tật John Merrick. Bản chất của con người là tò mò và độc ác, John đã được “ông chủ” xem như một quái vật kì dị và mang ra triển lãm làm cho tiêu khiển cho một bộ phận khán giả hiếu kì để kiếm sống. Một lần tình cờ xem biểu diễn những người dị dạng ở Luôn Đôn, bác sĩ Frederick thủ vai đã nhìn thấy và chứng kiến sự đối xử tàn tệ của lão Bytes, người quản lý ông bác sĩ đã quyết định đưa John về chữa trị. Câu chuyện diễn tiến tiếp theo mang lại cho người xem đầy xúc cảm, từ tình yêu thương đậm giá trị nhân văn của con người...</p>', 'Full', 1, 'single', 'completed', 14, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Anthony Hopkins","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Anne Bancroft","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324550);
