INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-voi', 'Người Voi', 'The Elephant Man', 'người voi the elephant man anthony hopkins john hurt anne bancroft ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('eo-bien-xanh', 'Eo Biển Xanh', 'The Blue Lagoon', 'https://phimimg.com/upload/vod/20231208-1/3cfdab3917034785e073ebd8a73e459f.jpg', 'https://phimimg.com/upload/vod/20231208-1/d2527420f4b705b0b5cb221b8ab69f94.jpg', '<p>Trên một hành trình đến San Francisco, Richard, cha và anh em họ Emmeline thấy mình trên một con tàu sắp nổ tung. Vội vã đến một chiếc xuồng cứu sinh với nút Paddy, hai đứa trẻ trốn thoát trong khi cha của họ (và chú) đang trên một chiếc xuồng cứu sinh khác. Trong sự hỗn loạn sau đây, xuồng cứu sinh được tách ra. Paddy, Richard và Emmeline thấy mình không có thức ăn và không có nước bị mắc kẹt ở giữa hư không. Sau một thời gian, ba người bắt gặp một thiên đường chưa được khám phá, nơi lúa nhanh chóng dạy trẻ em câu cá, săn bắn và xây dựng. Sau đó, có thể một hoặc hai tháng, lúa rất say trên một thùng rượu rum được tìm thấy trên đảo khi họ đến lần đầu tiên, và chết đuối vào giữa đêm. Emmeline và Richard, bây giờ cô đơn và rất sợ hãi, di chuyển vị trí và xây dựng lại ngôi nhà trên đảo của họ. Nhiều năm sau, hai thanh thiếu niên trẻ đã phát triển một ngôi nhà rất thật, nhưng hormone và cảm xúc giữa hai phong cách kết bạn của họ, cho đến khi Richard, người vẫn còn rất quyết tâm đến San Francisco, đang buông xuống bởi Emmeline khi một con tàu đi ngang qua Đảo và cô không thắp sáng ngọn lửa. Ném cô ra khỏi nhà, họ đã cùng nhau xây dựng, Emmeline cố gắng tự tồn tại nhưng bị tổn thương. Sau khi Richard thấy cô sắp chết, anh nhận ra cách anh thực sự cảm thấy cô và quản lý để cứu cô. Thiên nhiên điều hành khóa học của nó và tình bạn của họ biến thành tình yêu khi cặp đôi tìm hiểu về sự thật về cuộc sống, khi Emmeline có em bé và không hiểu tại sao.</p>', 'Full', 1, 'single', 'completed', 13, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Brooke Shields","avatar":""},{"name":"Christopher Atkins","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324550);
