INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-suong-ma', 'Làn Sương Ma', 'The Fog', 'https://phimimg.com/upload/vod/20231206-1/82a95d284e38d7774b446998e6e56d8a.jpg', 'https://phimimg.com/upload/vod/20231206-1/36caf3bd6e0f8705a7c55f57fa76f3cd.jpg', '<p>Bộ phim The Fog lấy bối cảnh là một thị trấn phía bắc California, nơi 100 năm trước, một con tàu biến mất một cách bí ẩn trong làn sương mù dày đặc. Và hồn ma của các thuỷ thủ đã khuất nay quay trở lại để trả mối thù của họ.</p>', 'Full', 1, 'single', 'completed', 11, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Adrienne Barbeau","avatar":""},{"name":"Jamie Lee Curtis","avatar":""},{"name":"Janet Leigh","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324550);
