INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-thien-duong', 'Cổng Thiên Đường', 'Heaven''s Gate', 'https://phimimg.com/upload/vod/20231130-1/1a4edc233c11e6a55e6f4215a4899b3c.jpg', 'https://phimimg.com/upload/vod/20231130-1/5a953b21cdc1217703a81b87ecc3bda0.jpg', '<p>Sinh viên tốt nghiệp Harvard James Averill là cảnh sát trưởng của Hạt Jackson thịnh vượng, Wyo., Khi một trận chiến nổ ra giữa những người nhập cư nghèo khổ trong khu vực và những người nông dân chăn nuôi gia súc giàu có. Các chủ trang trại có mối quan hệ chính trị chống lại những người nhập cư với sự giúp đỡ của Nathan Champion, một lính đánh thuê cạnh tranh với Averill vì tình yêu của bà địa phương Ella Watson. Khi cuộc đấu tranh leo thang, Averill và Champion bắt đầu đặt câu hỏi về quyết định của họ.</p>', 'Full', 1, 'single', 'completed', 20, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Kris Kristofferson","avatar":""},{"name":"Christopher Walken","avatar":""},{"name":"John Hurt","avatar":""},{"name":"Sam Waterston","avatar":""},{"name":"Brad Dourif","avatar":""},{"name":"Isabelle Huppert","avatar":""},{"name":"Joseph Cotten","avatar":""},{"name":"Jeff Bridges","avatar":""},{"name":"Ronnie Hawkins","avatar":""},{"name":"Paul Koslo","avatar":""},{"name":"Geoffrey Lewis","avatar":""},{"name":"Richard Masur","avatar":""},{"name":"Rosie Vela","avatar":""},{"name":"Mary Catherine Wright","avatar":""},{"name":"Nicholas Woodeson","avatar":""},{"name":"Stefan Shcherby","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324550);
