INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ma-am', 'Câu Chuyện Ma Ám', 'Haunted Tales', 'https://phimimg.com/upload/vod/20231211-1/1da04bbf72061e23a2c9b19ec11b7859.jpg', 'https://phimimg.com/upload/vod/20231211-1/a7477a05e2667f1dc1b11de2f3d9a3ca.jpg', '<p>1. Một vụ tai nạn khiến một người đàn ông thiệt mạng, và người vợ của anh ta bị thương nặng. Chẳng bao lâu, anh ta trở lại như một hồn ma để cố gắng đưa cô ấy đi cùng. 2. Người chăm sóc trúng số nhờ thần sa. Mọi thứ bắt đầu trở nên tồi tệ khi anh ấy thất hứa với nó.</p>', 'Full', 1, 'single', 'completed', 18, 1980, 'Vietsub', 'HD', 'Đài Loan', 0, '[{"name":"Ling Yun","avatar":""},{"name":"Ching Li","avatar":""},{"name":"Lin Chen-Chi","avatar":""},{"name":"Lau Luk-Wah","avatar":""},{"name":"Chan Shen","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324550);
