INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-ma-am', 'Câu Chuyện Ma Ám', 'Haunted Tales', 'câu chuyện ma ám haunted tales ling yun ching li lin chen-chi lau luk-wah chan shen ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-6-ngay-13-1980', 'Thứ 6 Ngày 13', 'Friday the 13th', 'https://phimimg.com/upload/vod/20231018-1/57a1a12e60bd232e01355f1b76f2f31a.jpg', 'https://phimimg.com/upload/vod/20231018-1/d7cbc74d0444ddef624bbfd068dabd15.jpg', '<p>Cô gái trẻ Alice Hardy cùng nhóm bạn thân đến nghỉ dưỡng tại khu nhà bên bờ hồ Camp Crystal bình yên và thơ mộng. Tiếp đón họ là người phụ nữ trung niên Pamela Voorhees sống cô độc một mình tại đây từ khi cậu con trai duy nhất của bà - Jason bị đồn là chết đuối từ nhỏ. Chưa kịp hưởng những vui thú của kì nghỉ hè, hàng loạt những cái chết ghê rợn ập đến với nhóm Alice mà không rõ hành tung của hung thủ. Những căn nhà bên bờ hồ giờ đây thực sự là nỗi ác mộng với nhóm bạn trẻ.</p>', 'Full', 1, 'single', 'completed', 13, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Jeannine Taylor","avatar":""},{"name":"Laurie Bartram","avatar":""},{"name":"Harry Crosby","avatar":""},{"name":"Robbi Morgan","avatar":""},{"name":"Adrienne King","avatar":""},{"name":"Mark Nelson","avatar":""},{"name":"Betsy Palmer","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Mary Rocco","avatar":""},{"name":"Rex Everhart","avatar":""},{"name":"Walt Gorney","avatar":""},{"name":"Willie Adams","avatar":""},{"name":"Peter Brouwer","avatar":""},{"name":"Debra S. Hayes","avatar":""},{"name":"Ronn Carroll","avatar":""},{"name":"Ron Millkie","avatar":""},{"name":"Ari Lehman","avatar":""},{"name":"Dorothy Kobs","avatar":""},{"name":"Ke","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324550);
