INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-cai-the-1980', 'Anh Hùng Cái Thế', 'By Hook Or By Crook', 'https://phimimg.com/upload/vod/20231014-1/f91d9c2d5eeabf0cb6b4f2f28405ae61.jpg', 'https://phimimg.com/upload/vod/20231014-1/be8293857d415933c45dafab6934b4c5.jpg', '<p>&#39;FLOWER KID&#39; là kiểu anh hùng &#39;Robin Hood&#39; chuyên cướp của người giàu và chia cho người nghèo. Anh ấy được nhiều người yêu mến, đặc biệt là một cậu bé tên &#39;FATSO&#39;, người tự coi mình là &#39;FLOWER KID jr.&#39; Madam Bee, một người phụ nữ gan dạ và độc ác rất ghét &#39;FLOWER KID&#39; vì anh ta từng từ chối giết chồng cô. Sau đó, cô kết hôn với một &#39;Big Shot&#39; giàu có và sử dụng tiền bạc cũng như quyền lực của anh ta để thuê một thợ săn tiền thưởng tên là &#39;SKINNY&#39;. Skinny bắt được anh hùng bắt chước &#39;Fatso&#39;. Họ chiến đấu, thấu hiểu, trở thành bạn tốt và tiếp tục tìm kiếm &#39;Fflower Kid&#39;...</p>', 'Full', 1, 'single', 'completed', 10, 1980, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Karl Maka","avatar":""},{"name":"Dean Shek","avatar":""},{"name":"Paul Chung Fat","avatar":""},{"name":"Tang Ching","avatar":""},{"name":"Lam Ching-Ying","avatar":""},{"name":"Eric Tsang","avatar":""},{"name":"Yolande Yau Pui-Ling","avatar":""},{"name":"Tai San","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324550);
