INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoc-dong-thoi-gian', 'Ngược Dòng Thời Gian', 'Somewhere in Time', 'https://phimimg.com/upload/vod/20231129-1/a4fa75228539906eec8737f877fd1e34.jpg', 'https://phimimg.com/upload/vod/20231129-1/f784067fa4e1ea6fd8ca15f60d134b37.jpg', '<p>Nhà văn trẻ Richard Collier đã gặp một bà già trong đêm khai mạc vở kịch đầu tiên của anh ấy, người đã cầu xin anh ấy &quot;Hãy quay lại với tôi&quot;. Bối rối, anh cố gắng tìm hiểu về cô và biết rằng cô là một nữ diễn viên sân khấu nổi tiếng từ đầu những năm 1900. Ngày càng bị ám ảnh bởi cô ấy, bằng cách tự thôi miên, anh ấy đã xoay sở để du hành ngược thời gian - nơi anh ấy gặp cô ấy.</p>', 'Full', 1, 'single', 'completed', 16, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Christopher Reeve","avatar":""},{"name":"Jane Seymour","avatar":""},{"name":"Christopher Plummer","avatar":""},{"name":"Teresa Wright","avatar":""},{"name":"Bill Erwin","avatar":""},{"name":"George Voskovec","avatar":""},{"name":"Susan French","avatar":""},{"name":"John Alvin","avatar":""},{"name":"Eddra Gale","avatar":""},{"name":"Audrey Bennett","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Laurence Coven","avatar":""},{"name":"Susan Bugg","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324550);
