INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('confidence', 'Confidence', 'Bizalom', 'https://phimimg.com/upload/vod/20231130-1/6d321b6d6c001a189965b47f18cd8f75.jpg', 'https://phimimg.com/upload/vod/20231130-1/a9b1dc33229c468ccfdd3f7242a93fe4.jpg', '<p>Janos và Kata bị ném vào nhau trong Thế chiến thứ hai và buộc phải đóng giả vợ chồng để trốn Đức quốc xã. Cường độ và sự gần gũi ngột ngạt của mối quan hệ mới của họ và hoàn cảnh mà họ thấy mình, buộc họ phải đối mặt với những định kiến và giả định trong quá khứ và thách thức những gì họ thực sự tin tưởng.</p>', 'Full', 1, 'single', 'completed', 17, 1980, 'Vietsub', 'HD', 'Hungary', 0, '[{"name":"Ildikó Bánsági","avatar":""},{"name":"Péter Andorai","avatar":""},{"name":"Ildikó Kishonti","avatar":""},{"name":"Lajos Balázsovits","avatar":""},{"name":"Tamás Dunai","avatar":""},{"name":"Zoltán Bezerédy","avatar":""},{"name":"Oszkárné Gombik","avatar":""},{"name":"Károly Csáki","avatar":""},{"name":"Judit Halász","avatar":""},{"name":"Éva Bartis","avatar":""},{"name":"Béla Éless","avatar":""},{"name":"Danielle du Tombe","avatar":""},{"name":"Gyula Gazdag","avatar":""},{"name":"Gyöngyi Dorogi","avatar":""},{"name":"László Littmann","avatar":""},{"name":"Károly Kovács","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324550);
