INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-wars-de-che-phan-cong', 'Star Wars: Đế Chế Phản Công', 'Star Wars: The Empire Strikes Back', 'https://phimimg.com/upload/vod/20231113-1/37d0b77ca1565e7b4a121a5ee7ec1387.jpg', 'https://phimimg.com/upload/vod/20231113-1/7ac877cd1cd02592290a1feedd71c151.jpg', '<p>Trước sự truy đuổi gắt gao của quân đội đế quốc, lực lượng nổi loạn phải đến lánh nạn ở hành tinh Hoth băng giá. Nhưng ngay cả ở nơi hẻo lánh này, họ vẫn không thoát khỏi nanh vuốt của tên Dath Vader tàn ác. Hắn tổ chức những đợt tấn công dồn dập vào căn cứ của phe nổi loạn với những vũ khí tối tân nhất. Phá được vòng vây, Han Solo, Công chúa Leia và Chewbacca chạy trốn đến hành tinh Bespin...</p>', 'Full', 1, 'single', 'completed', 18, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Mark Hamill","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Carrie Fisher","avatar":""},{"name":"Billy Dee Williams","avatar":""},{"name":"Anthony Daniels","avatar":""},{"name":"David Prowse","avatar":""},{"name":"Peter Mayhew","avatar":""},{"name":"Kenny Baker","avatar":""},{"name":"Frank Oz","avatar":""},{"name":"Alec Guinness","avatar":""},{"name":"Jeremy Bulloch","avatar":""},{"name":"Jason Wingreen","avatar":""},{"name":"John Hollis","avatar":""},{"name":"Jack Purvis","avatar":""},{"name":"Des Webb","avatar":""},{"name":"Kathryn Mullen","avatar":""},{"name":"Marjorie Eaton","avatar":""},{"name":"Clive Rev","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 178469