INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-tinh-yeu', 'Chuyến Bay Tình Yêu', 'Airplane!', 'https://phimimg.com/upload/vod/20231025-1/f8499f4dbd0a340809cd99a650be8675.jpg', 'https://phimimg.com/upload/vod/20231025-1/1f10554d82e1ae82a2f67dc69babbe29.jpg', '<p>Một cựu phi công chiến đấu buộc phải nắm quyền điều khiển một chiếc máy bay khi phi hành đoàn tử vong vì ngộ độc thực phẩm.</p>', 'Full', 1, 'single', 'completed', 16, 1980, 'Vietsub', 'HD', 'Âu Mỹ', 0, '[{"name":"Robert Hays","avatar":""},{"name":"Julie Hagerty","avatar":""},{"name":"Leslie Nielsen","avatar":""},{"name":"Kareem Abdul-Jabbar","avatar":""},{"name":"Lloyd Bridges","avatar":""},{"name":"Peter Graves","avatar":""},{"name":"Lorna Patterson","avatar":""},{"name":"Robert Stack","avatar":""},{"name":"Jim Abrahams","avatar":""},{"name":"Jonathan Banks","avatar":""},{"name":"Stephen Stucker","avatar":""},{"name":"Frank Ashmore","avatar":""},{"name":"Craig Berenson","avatar":""},{"name":"Barbara Billingsley","avatar":""},{"name":"Lee Bryant","avatar":""},{"name":"Joyce Bulifant","avatar":""},{"name":"Mae","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324550);
