INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-da-quy', 'Quỷ Đả Quỷ', 'Spooky Encounters', 'https://phimimg.com/upload/vod/20231010-1/e6b845ab126e6e12730949390b7165dc.jpg', 'https://phimimg.com/upload/vod/20231010-1/a72289508be81f376e3da69b8e828270.jpg', '<p>Bộ phim lấy bối cảnh Hồng Kông vào thời xưa, trong một ngôi làng nọ, có một người đàn ông biệt danh Trương &quot;to gan&quot; rất gan dạ, không tin chuyện ma quỷ. Trương làm nghề đánh xe ngựa cho ông Đàm lão gia, đến giờ nghỉ thì anh ta đi ăn đậu hũ ở quán của bác Phúc. Cô vợ của Trương ham muốn tiền bạc nên đã ngoại tình với Đàm lão gia, Đàm lão gia sợ bị Trương phát hiện nên tính thuê người giết Trương.</p>', 'Full', 1, 'single', 'completed', 18, 1980, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Sammo Hung","avatar":""},{"name":"Paul Chung Fat","avatar":""},{"name":"Wu Ma","avatar":""},{"name":"Lam Ching-Ying","avatar":""},{"name":"Peter Chan Lung","avatar":""},{"name":"To Siu-Ming","avatar":""},{"name":"Huang Ha","avatar":""},{"name":"Leung Suet-Mei","avatar":""},{"name":"Tai Bo","avatar":""},{"name":"Chang Ching-Po","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324550);
