INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suat-de-xuat-ma', 'Suất Đệ Xuất Mã', 'The Young Master', 'https://phimimg.com/upload/vod/20231010-1/8ebdbfff756b27597763481ac9f2f3e9.jpg', 'https://phimimg.com/upload/vod/20231010-1/267f439ae2ad4877b8fe565967e41ddc.jpg', '<p>Tiểu Sư Phụ là một bộ phim điện ảnh do Hồng kông sản xuất vào năm 1980,đây là bộ phim do Thành Long làm đạo diễn kiêm diễn viên chính.Bộ phim có nhiều cảnh quay nhào lộn hấp dẫn và nguy hiểm do chính Thành Long thực hiện mà không hề có diễn viên đóng thế. Mời các bạn cùng xem bộ phim võ thuật cổ trang mang tên Tiểu Sư Phụ.</p>', 'Full', 1, 'single', 'completed', 20, 1980, 'Vietsub', 'HD', 'Hồng Kông', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Wai Pak","avatar":""},{"name":"Yuen Biao","avatar":""},{"name":"Sek Kin","avatar":""},{"name":"Lily Li","avatar":""},{"name":"Whang In-sik","avatar":""},{"name":"Lee Hoi-Sang","avatar":""},{"name":"Fung Hak-On","avatar":""},{"name":"Fung Fung","avatar":""},{"name":"Fan Mei-Sheng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324550);
